PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE SEQUENCE (SEQ_NAME VARCHAR(50) NOT NULL, SEQ_COUNT NUMBER(19), PRIMARY KEY (SEQ_NAME));
CREATE TABLE IF NOT EXISTS "hymns" (
	 "_id" VARCHAR NOT NULL,
	 "author" VARCHAR,
	 "composer" VARCHAR,
	 "first_chorus_line" VARCHAR,
	 "first_stanza_line" VARCHAR,
	 "hymn_group" VARCHAR,
	 "key" VARCHAR,
	 "main_category" VARCHAR,
	 "meter" VARCHAR,
	 "no" VARCHAR,
	 "sub_category" VARCHAR,
	 "time" VARCHAR,
	 "tune" TEXT,
	 "parent_hymn" text,
	 "sheet_music_link" TEXT,
	 "verse" text,
	 "related" TEXT,
	PRIMARY KEY("_id")
);
CREATE TABLE IF NOT EXISTS "stanza" (
	 "parent_hymn" TEXT NOT NULL,
	 "no" TEXT NOT NULL,
	 "text" TEXT,
	 "note" TEXT,
	 "id" INTEGER NOT NULL,
	 "n_order" integer,
	PRIMARY KEY("id")
);
<br/>',NULL,20717,1);
<br/>I pursue towards the goal, run to gain the prize;<br/>Just to know my treasured Christ, all else I’d despise. <br/>',NULL,20718,2);
<br/>We do not proclaim ourselves, Christ do we proclaim,<br/>And ourselves as His bondslaves, this is all our aim.<br/>',NULL,20719,3);
„Abba, Vater, preis sei Dir”;<br/>Licht vertreibt all unser Dunkel,<br/>Deinen Sohn nun sehen wir.<br/>',NULL,45934,8);
CREATE TABLE IF NOT EXISTS "tune"
(
	_id VARCHAR,
	comment VARCHAR,
	youtube_link text
);
CREATE VIEW "hymns_stanza" AS select * from hymns inner join stanza on hymns._id=stanza.parent_hymn;
CREATE INDEX stanza_parent_hymn on stanza (parent_hymn,n_order);
CREATE INDEX hymns_first_lines on hymns (first_stanza_line,first_chorus_line);
COMMIT;
