INSERT INTO hymns VALUES('T30009',NULL,NULL,NULL,'God''s complete salvation is based upon His righteousness and through our faith.','T',NULL,'BANNERS',NULL,'30009','God''s Complete Salvation',NULL,NULL,'CS1001',NULL,NULL,NULL);
INSERT INTO hymns VALUES('T30010',NULL,NULL,NULL,'God regenerates us that we may have His divine life and renews us that we may become His divine new creation.','T',NULL,'BANNERS',NULL,'30010','The Experience of God''s Organic Salvation Equaling Reigning in Christ''s Life',NULL,NULL,'CS1002',NULL,NULL,NULL);
INSERT INTO hymns VALUES('T30011',NULL,NULL,NULL,'The apostle''s teaching is the entire speaking of God in the New Testament concerning God''s New Testament economy.','T',NULL,'BANNERS',NULL,'30011','God''s New Testament Ministry',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('T30012',NULL,NULL,NULL,'When we experience God as the blowing wind, the overshadowing cloud, the consuming fire, and the glowing electrum, we become the four living creatures, coordinating to carry out God''s economy for His expression, move, and administration.','T',NULL,'BANNERS',NULL,'30012','The Move of God in His Recovery as Portrayed in Ezekiel',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('T30013',NULL,NULL,NULL,'The believers in Christ should be river crossers, following the Lord Jesus, the Pioneer and Forerunner, into the glorious expression of the Divine Being.','T',NULL,'BANNERS',NULL,'30013','Crystallization-Study of The Epistle to the Hebrews Part 1',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('T30014',NULL,NULL,NULL,'In His heavenly ministry, Christ, the kingly and divine High Priest, is executing the new testament by interceding for us, shepherding us, and ministering Himself into us.','T',NULL,'BANNERS',NULL,'30014','Crystallization-Study of The Epistle to the Hebrews Part 2',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('T30015',NULL,NULL,NULL,'Christ, the worthy and enthroned Lion-Lamb, is the heavenly Administrator in the divine government, opening the scroll of God''s economy to unlock the secret of the universe.','T',NULL,'BANNERS',NULL,'30015','Crystallization-study of Revelation Part 1',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('T30016',NULL,NULL,NULL,'God will use the overcomers to fulfill His economy, to defeat His enemy, and to bring His kingdom to the earth.','T',NULL,'BANNERS',NULL,'30016','Crystallization-study of Revelation Part 2',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('T30017',NULL,NULL,NULL,'The New Jerusalem is the destination of the flowing Triune God.','T',NULL,'BANNERS',NULL,'30017','Crystallization-Study of the New Jerusalem',NULL,NULL,NULL,NULL,NULL,NULL);
