INSERT INTO hymns VALUES('G458',NULL,NULL,NULL,'Dies ist meine Ruh auf ewig,','G',NULL,'SCHRIFTSTELLEN ZUM SINGEN','Freies Versmaß','458',NULL,NULL,NULL,'E1338',NULL,' Psalm 132:13-16',NULL);
INSERT INTO hymns VALUES('G459',NULL,NULL,NULL,'Ihr werdet mit Freuden Wasser schöpfen','G',NULL,'SCHRIFTSTELLEN ZUM SINGEN','Freies Versmaß','459',NULL,NULL,NULL,'E1340',NULL,' Jesaja 12:3-4, 6',NULL);
INSERT INTO hymns VALUES('G460',NULL,NULL,NULL,'Dann werden die Erlösten des Herrn wiederkehrn,','G',NULL,'SCHRIFTSTELLEN ZUM SINGEN','Freies Versmaß','460',NULL,NULL,NULL,'E1341',NULL,' Jesaja 51:11',NULL);
INSERT INTO hymns VALUES('J1',NULL,NULL,NULL,'栄こうちちにあれ, 御子にあれ，','J',NULL,'三一の神を賛美する',NULL,'1','彼のご計画',NULL,NULL,'E1',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J2',NULL,NULL,NULL,'グローリー,グローリー,グローリー,','J',NULL,'三一の神を賛美する',NULL,'2','彼の啓示',NULL,NULL,'E2',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J3',NULL,NULL,'賛美せよ,賛美せよ, さんいちのかみ!','栄光,御ちちにあれ, 栄光,御子にあれ,','J',NULL,'三一の神を賛美する',NULL,'3','彼への賛美',NULL,NULL,'E7',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J4',NULL,NULL,NULL,'せい,せい,せい, ぜん能のかみ!','J',NULL,'三一の神を賛美する',NULL,'4','彼への賛美',NULL,NULL,'E6',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J5',NULL,NULL,NULL,'ちち,子,れい賛美す! みなもとのちちを,','J',NULL,'三一の神を賛美する',NULL,'5','彼への賛美',NULL,NULL,'E8',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J6',NULL,NULL,'なれ愛,ひかり, 子にありいのち;','かみはあい,ひかり, 子にありいのち;','J',NULL,'父を礼拝する',NULL,'6','愛と光として',NULL,NULL,'E13',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J7',NULL,NULL,NULL,'えい遠のちちよ, ありてあるもの!','J',NULL,'父を礼拝する',NULL,'7','愛と光として',NULL,NULL,'E10',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J8',NULL,NULL,NULL,'ちちよ,なれはれい, 何としんせい;','J',NULL,'父を礼拝する',NULL,'8','その霊として',NULL,NULL,'E11',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J9',NULL,NULL,NULL,'み なもとなるかみよ, ほう富ないのち!','J',NULL,'父を礼拝する',NULL,'9','命の源として',NULL,NULL,'E12',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J10',NULL,NULL,NULL,'何とたくえつし, 何と聖なるかみ!','J',NULL,'父を礼拝する',NULL,'10','彼の卓越性',NULL,NULL,'E15',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J11',NULL,NULL,'ちちよ,なれは新鮮, ふるびはせず!','ちちよ,なれはしんせん, とわにみどり!','J',NULL,'父を礼拝する',NULL,'11','彼の新しさ',NULL,NULL,'E16',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J12',NULL,NULL,'わがこころ,霊はうたう, なんという不思議よ!','てん地のつくられしもの, すべてはなれのちから,','J',NULL,'父を礼拝する',NULL,'12','彼の偉大さ',NULL,NULL,'E17',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J13',NULL,NULL,'なが信じつは偉大なるかな! なれはあさごとに新鮮!','ちちよ,偉だいなるかみよ, なれはとわに変わらず。','J',NULL,'父を礼拝する',NULL,'13','彼の信実',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J14',NULL,NULL,'天にてわがために さだめられし,','ちちよ,なれなんと 信じつなかみ;','J',NULL,'父を礼拝する',NULL,'14','彼の信実',NULL,NULL,'E18',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J15',NULL,NULL,NULL,'血なくて,ゆるすなら, 義は満たされず;','J',NULL,'父を礼拝する',NULL,'15','彼の義',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J16',NULL,NULL,NULL,'なが義と正義ゆえ, われらほめたたえ,','J',NULL,'父を礼拝する',NULL,'16','彼の義',NULL,NULL,'E21',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J17',NULL,NULL,NULL,'つみに満ちるわれに, 義はさばきよう求する;','J',NULL,'父を礼拝する',NULL,'17','彼の義',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J18',NULL,NULL,NULL,'ちちよ,なが義のゆえ, われらは礼はいす;','J',NULL,'父を礼拝する',NULL,'18','彼の義',NULL,NULL,'E20',NULL,NULL,NULL);
