INSERT INTO hymns VALUES('J25',NULL,NULL,NULL,'ちちよ,なんという あいあとうや;','J',NULL,'父を礼拝する',NULL,'25','彼の愛',NULL,NULL,'E30',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J26',NULL,NULL,NULL,'ちちのあいのあとうもの, いかにおおくとも,','J',NULL,'父を礼拝する',NULL,'26','彼の愛',NULL,NULL,'E38',NULL,NULL,NULL);
