INSERT INTO hymns VALUES('J50',NULL,NULL,NULL,'ちちの愛,子にてあらわれ,','J',NULL,'父を礼拝する',NULL,'50','多くの子たちの賛美',NULL,NULL,'E53',NULL,NULL,NULL);
