INSERT INTO hymns VALUES('J54',NULL,NULL,NULL,'主よ,なれとわのことば, 　 ちちのひとり子,','J',NULL,'主を賛美する',NULL,'54','彼の神性',NULL,NULL,'E59',NULL,NULL,NULL);
