INSERT INTO hymns VALUES('J61',NULL,NULL,NULL,'とうとき主の御名, そは「わたしはある」;','J',NULL,'主を賛美する',NULL,'61','彼の御名',NULL,NULL,'E78',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J62',NULL,NULL,NULL,'あいする御名,イェス! 御まえに伏して,','J',NULL,'主を賛美する',NULL,'62','彼の御名',NULL,NULL,'E69',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J63',NULL,NULL,NULL,'かぐわしきイェスの名は, めぐみほどこす;','J',NULL,'主を賛美する',NULL,'63','彼の御名',NULL,NULL,'E71',NULL,NULL,NULL);
