INSERT INTO hymns VALUES('J69',NULL,NULL,NULL,'とうときイェスの名を, 聖徒らたとう:','J',NULL,'主を賛美する',NULL,'69','彼の御名',NULL,NULL,'E72',NULL,NULL,NULL);
