INSERT INTO hymns VALUES('J75',NULL,NULL,'主よ,なれを 愛し,はいす!','すくいぬし, えいこう捨て,','J',NULL,'主を賛美する',NULL,'75','彼の受肉',NULL,NULL,'E82',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J76',NULL,NULL,NULL,'主よ,なれの柔和さ, かがやいてうるわしい!','J',NULL,'主を賛美する',NULL,'76','彼の生涯',NULL,NULL,'E88',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J77',NULL,NULL,NULL,'いとたかき栄光のかみ, にくたいにあり来たり,','J',NULL,'主を賛美する',NULL,'77','彼の生涯',NULL,NULL,'E86',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J78',NULL,NULL,NULL,'主の地じょうでのあゆみ, 慈あい,美に満つ!','J',NULL,'主を賛美する',NULL,'78','彼の生涯',NULL,NULL,'E89',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J79',NULL,NULL,NULL,'主よ,なれはひとにたいし, あいとめぐみ持つ;','J',NULL,'主を賛美する',NULL,'79','彼の生涯',NULL,NULL,'E87',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J80',NULL,NULL,'ゲツセマネわすれず, ながうれい,わすれず,','いま,われひれ伏す, いのちの王よ,','J',NULL,'主を賛美する',NULL,'80','彼の苦しみ',NULL,NULL,'E160',NULL,NULL,NULL);
