INSERT INTO hymns VALUES('J82',NULL,NULL,NULL,'試れん,くるしみ, あざけり受け,','J',NULL,'主を賛美する',NULL,'82','彼の苦しみ',NULL,NULL,'E95',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J83',NULL,NULL,NULL,'真夜なかにひとり, すくいぬしいのる;','J',NULL,'主を賛美する',NULL,'83','彼の苦しみ',NULL,NULL,'E99',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J84',NULL,NULL,NULL,'ああ,主はこうべを垂れ, わがつみ負う!','J',NULL,'主を賛美する',NULL,'84','彼の苦しみ',NULL,NULL,'E94',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J85',NULL,NULL,NULL,'主の十字架をおもい, 　主の苦難をおもうとき,','J',NULL,'主を賛美する',NULL,'85','彼の苦しみ',NULL,NULL,'E101',NULL,NULL,NULL);
