INSERT INTO hymns VALUES('J87',NULL,NULL,'賛美せよ,賛美せよ, 　　えいこうの主を;','主のあゆみしみち, 　苦なんに満ちる;','J',NULL,'主を賛美する',NULL,'87','彼の苦しみ',NULL,NULL,'E93',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J88',NULL,NULL,'わがため! 十字架につき,','ゲツセマネのそので イェスはいのり,','J',NULL,'主を賛美する',NULL,'88','彼の苦しみ',NULL,NULL,'E91',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J89',NULL,NULL,NULL,'主はあいゆえ,わがため, はじと死を受ける!','J',NULL,'主を賛美する',NULL,'89','彼の苦しみ',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J90',NULL,NULL,NULL,'賛美,賛美,賛美, すくいぬし賛美す;','J',NULL,'主を賛美する',NULL,'90','彼の死',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J91',NULL,NULL,NULL,'自分をすくわず, 十字架で死に,','J',NULL,'主を賛美する',NULL,'91','彼の死',NULL,NULL,'E105',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J92',NULL,NULL,NULL,'この孤どくなとき！ 　四ほうはやみ！','J',NULL,'主を賛美する',NULL,'92','彼の死',NULL,NULL,'E110',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J93',NULL,NULL,NULL,'ああ,主は血をながし, 　いのちを捨てる;','J',NULL,'主を賛美する',NULL,'93','彼の死',NULL,NULL,'E104',NULL,NULL,NULL);
