INSERT INTO hymns VALUES('J193',NULL,NULL,NULL,'栄光,尊貴,ほう富が, 小ひつじにあれや！','J',NULL,'主を賛美する',NULL,'193','一般',NULL,NULL,'E240',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J194',NULL,NULL,NULL,'かみの霊はキﾘストの霊, 実さいのれいとして来た。','J',NULL,'その霊の豊満',NULL,'194','実際の霊',NULL,NULL,'E243',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J195',NULL,NULL,'霊こころに満ち,そくばくを解く,','つみのかいほう得ることを, ひたすら主にいのる;','J',NULL,'その霊の豊満',NULL,'195','内住の霊',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J196',NULL,NULL,NULL,'いまやかみのれいは, 主イェス・キリストのれい;','J',NULL,'その霊の豊満',NULL,'196','イエス・キリストの霊',NULL,NULL,'E242',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J197',NULL,NULL,'なぐさめぬし,すでに来たる！','この知らせを, 宣べつたえよ,','J',NULL,'その霊の豊満',NULL,'197','慰め主',NULL,NULL,'E245',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J198',NULL,NULL,NULL,'世びとはなれを普つうの ナザレびとと見た；','J',NULL,'その霊の豊満',NULL,'198','賜物としての霊',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J199',NULL,NULL,NULL,'えいこうなる主は, 天かられいたまい,','J',NULL,'その霊の豊満',NULL,'199','賜物としての霊',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J200',NULL,NULL,NULL,'いまや,せいれいは, かみのいのちの霊;','J',NULL,'その霊の豊満',NULL,'200','命の霊',NULL,NULL,'E244',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J201',NULL,NULL,NULL,'井戸のみずよ, わきあがれや！','J',NULL,'その霊の豊満',NULL,'201','生ける水',NULL,NULL,'E250',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J202',NULL,NULL,'いわより,みずながせ！ 聖霊すでに,ともにある;','カデシの地でかわくとき, かみはたみに,命じられる:','J',NULL,'その霊の豊満',NULL,'202','生ける水',NULL,NULL,'E248',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J203',NULL,NULL,'生けるみずのかわ, 無だい価のみず;','生けるみずのかわ, 御座よりながれ,','J',NULL,'その霊の豊満',NULL,'203','生ける水',NULL,NULL,'E251',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J204',NULL,NULL,'生けるみずのかわ, ながれるところ,','生けるみずのかわ, 御座よりながれ,','J',NULL,'その霊の豊満',NULL,'204','生ける水',NULL,NULL,'E984',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J205',NULL,NULL,'みずはながれ, 供きゅうもたらし,','生けるみずながる, 栄光のみやより,','J',NULL,'その霊の豊満',NULL,'205','生ける水',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J206',NULL,NULL,'聖霊おおくあたえて, 　照らし,燃やせや;','聖霊をうれえさせて, 　さまよっていたが,','J',NULL,'その霊の豊満',NULL,'206','火',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J207',NULL,NULL,'こころ燃える,こころ燃える; てんの火,わがうちに燃える！','かみはちから, われにあたえ,','J',NULL,'その霊の豊満',NULL,'207','火',NULL,NULL,'E263',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J208',NULL,NULL,'燃やす霊くだし, われ転機させよ！','主よ,われもとむ, 燃やす霊くだせ,','J',NULL,'その霊の豊満',NULL,'208','火',NULL,NULL,'E262',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J209',NULL,NULL,NULL,'イェスは勝利のあい, われにそそぐ,','J',NULL,'その霊の豊満',NULL,'209','火',NULL,NULL,'E264',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J210',NULL,NULL,'ふるきものすべて 吐き出させ,','主よ,なれのれいを 吹き入れたまえ;','J',NULL,'その霊の豊満',NULL,'210','息',NULL,NULL,'E255',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J211',NULL,NULL,NULL,'主よ,われに息吹き, 生けるいずみ啓示し,','J',NULL,'その霊の豊満',NULL,'211','息',NULL,NULL,'E254',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J212',NULL,NULL,'吹く！吹く！ 聖れいのかぜ！ めぐみの くもはおおう！','聖霊のかぜ 天より吹く, ペンテコステ の日のよう;','J',NULL,'その霊の豊満',NULL,'212','風',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J213',NULL,NULL,'大能の主,来たれや, 聖れい吹けや！','主よ,なが天のかぜ, われに吹けや！','J',NULL,'その霊の豊満',NULL,'213','風',NULL,NULL,'E257',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J214',NULL,NULL,'いま吹き去らせよ！','かぜよ吹けよ, われらのえに,','J',NULL,'その霊の豊満',NULL,'214','風',NULL,NULL,'E256',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J215',NULL,NULL,'たえなるぬりあぶらは, わがうちにてみちびけり;','わがうちでおしえる たえなるあぶら;','J',NULL,'その霊の豊満',NULL,'215','塗り油',NULL,NULL,'E266',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J216',NULL,NULL,NULL,'主の血あるところ, 塗りあぶら塗られる;','J',NULL,'その霊の豊満',NULL,'216','塗り油',NULL,NULL,'E265',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J217',NULL,NULL,'満たせ,満たせ, 聖れいで満たせ;','何というえいこう, 聖れいうちにて,','J',NULL,'その霊の豊満',NULL,'217','充満',NULL,NULL,'E267',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J218',NULL,NULL,NULL,'血しおのきよめで よろこびあふれ,','J',NULL,'その霊の豊満',NULL,'218','充満',NULL,NULL,'E268',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J219',NULL,NULL,'もとむ,もとむ, せい霊のとみを。','主よ,飢えかわいて ただなれもとむ;','J',NULL,'その霊の豊満',NULL,'219','充満',NULL,NULL,'E283',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J220',NULL,NULL,NULL,'霊にて霊より生まれた われら,かみの子は,','J',NULL,'その霊の豊満',NULL,'220','霊のバプテスマ',NULL,NULL,'E271',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J221',NULL,NULL,NULL,'主はせいれいから, 生まれ,ひとと成り,','J',NULL,'その霊の豊満',NULL,'221','霊のバプテスマ',NULL,NULL,'E272',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J222',NULL,NULL,NULL,'ああ,われらは霊のなかに','J',NULL,'その霊の豊満',NULL,'222','霊のバプテスマ',NULL,NULL,'E276',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J223',NULL,NULL,NULL,'主よ,われらみもとに来, ながちから要きゅうす;','J',NULL,'その霊の豊満',NULL,'223','霊のバプテスマ',NULL,NULL,'E273',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J224',NULL,NULL,NULL,'キリスト,昇てんし, 天のうえに座す,','J',NULL,'その霊の豊満',NULL,'224','霊のバプテスマ',NULL,NULL,'E277',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J225',NULL,NULL,'ひれ伏し待ちのぞむ, なれに呼びもとめる,','主よ,ちからあたえよ, ながはたらきのため,','J',NULL,'その霊の豊満',NULL,'225','霊のバプテスマ',NULL,NULL,'E274',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J226',NULL,NULL,NULL,'いのちのれい,うちに入る,','J',NULL,'その霊の豊満',NULL,'226','二つの面',NULL,NULL,'E278',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J227',NULL,NULL,'十字架をとおして, たましい捨てる;','血しおのきよめにて, あぶら塗りは来る;','J',NULL,'その霊の豊満',NULL,'227','十字架を通して',NULL,NULL,'E279',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J228',NULL,NULL,'ああ,主よ,自己より, 解きはなちませ！','主よ,血しおにて われをあらい,','J',NULL,'その霊の豊満',NULL,'228','十字架を通して',NULL,NULL,'E280',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J229',NULL,NULL,NULL,'アダムをはなれ, いまや主にある;','J',NULL,'救いを得た確信と喜び',NULL,'229','キリストの中で',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J230',NULL,NULL,'われはよろこび満つ, 主,われをあいする;','ちちなるかみはかたる, 「われは世びとをあいす」;','J',NULL,'救いを得た確信と喜び',NULL,'230','主に愛される',NULL,NULL,'E291',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J231',NULL,NULL,NULL,'あまき主のあい, 賛美をさそう;','J',NULL,'救いを得た確信と喜び',NULL,'231','主に愛される',NULL,NULL,'E286',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J232',NULL,NULL,NULL,'えい遠のあいを, めぐみにて知る;','J',NULL,'救いを得た確信と喜び',NULL,'232','主に愛される',NULL,NULL,'E284',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J233',NULL,NULL,'わがおかしたつみ, すべてゆるされた。','かみはわがつみを はい後に投げ捨て,','J',NULL,'救いを得た確信と喜び',NULL,'233','神に赦される',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J234',NULL,NULL,NULL,'おお,何というあいでしょう, すくいぬしは血をながし,','J',NULL,'救いを得た確信と喜び',NULL,'234','キリストの中で義とされる',NULL,NULL,'E296',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J235',NULL,NULL,NULL,'なぜおそれるのか？ つみは御子にあり,','J',NULL,'救いを得た確信と喜び',NULL,'235','キリストの中で義とされる',NULL,NULL,'E1003',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J236',NULL,NULL,NULL,'「つみにさだーめない！」, 何ととうといことば！','J',NULL,'救いを得た確信と喜び',NULL,'236','キリストの中で義とされる',NULL,NULL,'E297',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J237',NULL,NULL,NULL,'キリストはわれの義, われの美,われのころも,','J',NULL,'救いを得た確信と喜び',NULL,'237','キリストの中で義とされる',NULL,NULL,'E295',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J238',NULL,NULL,'いわなるキリスト, 堅固なるいしずえ！','わがのぞみの基礎, われの義キリスト;','J',NULL,'救いを得た確信と喜び',NULL,'238','キリストの中で義とされる',NULL,NULL,'E298',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J239',NULL,NULL,NULL,'かみはわがつみ, 主イェスに置く;','J',NULL,'救いを得た確信と喜び',NULL,'239','血によって贖われる',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J240',NULL,NULL,NULL,'はばかることもなく, 御まえにすすむ！','J',NULL,'救いを得た確信と喜び',NULL,'240','神に和解させられる',NULL,NULL,'E299',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J241',NULL,NULL,'主,はいり来てのち, いつもよろこびと,','わがいのちにだい変化あり, 主,はいり来てのち;','J',NULL,'救いを得た確信と喜び',NULL,'241','命の変化',NULL,NULL,'E309',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J242',NULL,NULL,NULL,'わがこころは,よろこびに満ちる！','J',NULL,'救いを得た確信と喜び',NULL,'242','命の変化',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J243',NULL,NULL,'かい放された！ つみより解かれ,ハレルヤ！','つみのおも荷を背負って, ながねんくるしんできた,','J',NULL,'救いを得た確信と喜び',NULL,'243','主によって解放される',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J244',NULL,NULL,'栄こうのかいほう！ つみにしばられない;','主はわれをかい放された; イェスわがおう,すくいぬし;','J',NULL,'救いを得た確信と喜び',NULL,'244','主によって解放される',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J245',NULL,NULL,NULL,'かつては主のかい放を知らずに,','J',NULL,'救いを得た確信と喜び',NULL,'245','主によって解放される',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J246',NULL,NULL,'栄光の解放,くすし解放, ざいあくより解かる;','つみのかせにしばられ, 奴れいのごとき身も,','J',NULL,'救いを得た確信と喜び',NULL,'246','主によって解放される',NULL,NULL,'E310',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J247',NULL,NULL,NULL,'おどろくべきめぐみ！ われをもすくう！','J',NULL,'救いを得た確信と喜び',NULL,'247','恵みによって救われる',NULL,NULL,'E313',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J248',NULL,NULL,'キリストは, うちに生く;','主のめぐみは, われ,支はいし,','J',NULL,'救いを得た確信と喜び',NULL,'248','恵みによって救われる',NULL,NULL,'E312',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J249',NULL,NULL,'御かお見てかたる, すくいのめぐみを;','銀のひも切れる日, うたはうたえない;','J',NULL,'救いを得た確信と喜び',NULL,'249','恵みによって救われる',NULL,NULL,'E316',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J250',NULL,NULL,NULL,'いずみよ,来たれや！ こころはうたう;','J',NULL,'救いを得た確信と喜び',NULL,'250','恵みによって救われる',NULL,NULL,'E319',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J251',NULL,NULL,'つみびとのわれが, 主のめぐみ受けた！','わが持てるものすべて, めぐみによりたまわる;','J',NULL,'救いを得た確信と喜び',NULL,'251','恵みによって救われる',NULL,NULL,'E311',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J252',NULL,NULL,'いま,たかきやま,晴れわたるそら,','かつてつみの奴隷,へい安知らず,','J',NULL,'救いを得た確信と喜び',NULL,'252','キリストのゆえに満足を得る',NULL,NULL,'E324',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J253',NULL,NULL,'イェス,イェス,イェス, あまき御名;','わがこころのなかに, 主のうたごえあり:','J',NULL,'救いを得た確信と喜び',NULL,'253','キリストのゆえに満足を得る',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J254',NULL,NULL,'かわかぬいずみ見いだし, いのちのいずみ飲まば,','かわかぬいのちのいずみ, たずね,つかれぬ;','J',NULL,'救いを得た確信と喜び',NULL,'254','キリストのゆえに満足を得る',NULL,NULL,'E322',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J255',NULL,NULL,'わがこころにうたあり, あまきメロデｨ,てんのうた;','わがうちでかなでる たえなるしらべ;','J',NULL,'救いを得た確信と喜び',NULL,'255','キリストのゆえに満足を得る',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J256',NULL,NULL,'ハレルヤ！よろこび, ハレルヤ！うたおう！','キリスト,わがうた, こころのよろこび;','J',NULL,'救いを得た確信と喜び',NULL,'256','キリストのゆえに満足を得る',NULL,NULL,'E348',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J257',NULL,NULL,'ハレルヤ！かわきは すでに満たされ,','焼きつくかわきの いやしをもとめ,','J',NULL,'救いを得た確信と喜び',NULL,'257','キリストのゆえに満足を得る',NULL,NULL,'E325',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J258',NULL,NULL,'わがこころ満たす主に, くらぶるものはなし;','かつてはのぞみもなく, くるしみもがけど,','J',NULL,'救いを得た確信と喜び',NULL,'258','キリストのゆえに満足を得る',NULL,NULL,'E522',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J259',NULL,NULL,'ただわたしは知っている: わたしのたくしたもの,','なぜか？かみのめぐみが, わが身にのぞんだ;','J',NULL,'救いを得た確信と喜び',NULL,'259','主の守り',NULL,NULL,'E333',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J260',NULL,NULL,NULL,'かみはすでに堅固な土だいを, かみのことばで据えられた。','J',NULL,'救いを得た確信と喜び',NULL,'260','堅固な土台',NULL,NULL,'E339',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J261',NULL,NULL,NULL,'めぐみ受けたものよ,みな来て,','J',NULL,'救いを得た確信と喜び',NULL,'261','一般',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J262',NULL,NULL,'えい光のひかり満つ, よろこび寄せ来たる;','えい光のひかりいま, こころを照らす;','J',NULL,'救いを得た確信と喜び',NULL,'262','一般',NULL,NULL,'E343',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J263',NULL,NULL,'たのしい,たのしい, 主のすくいを得た！','この日に,わたしは,　 主イェスをえらんだ！','J',NULL,'救いを得た確信と喜び',NULL,'263','一般',NULL,NULL,'E347',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J264',NULL,NULL,NULL,'おく義！すくいぬしと 　われはひとつ。','J',NULL,'救いを得た確信と喜び',NULL,'264','一般',NULL,NULL,'E1074',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J265',NULL,NULL,'これこそわがあかし, これこそわがしい歌！','たしかに主わがもの！ あがない,めぐみ受け,','J',NULL,'救いを得た確信と喜び',NULL,'265','一般',NULL,NULL,'E308',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J266',NULL,NULL,NULL,'かみの意志,さだめ, 知る知しきないが，','J',NULL,'救いを得た確信と喜び',NULL,'266','一般',NULL,NULL,'E346',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J267',NULL,NULL,'無だい価のめぐみで, 多くのつみ,ゆるされ,','十字架の主を無視し, むなしく生きてきた;','J',NULL,'救いを得た確信と喜び',NULL,'267','一般',NULL,NULL,'E342',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J268',NULL,NULL,'すべてやすし！　へい安をきょう受する。','主のへい安がながれて,いま, わたしにおよんだ;','J',NULL,'救いを得た確信と喜び',NULL,'268','一般',NULL,NULL,'E341',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J269',NULL,NULL,NULL,'しかがたにのみずを したうように,','J',NULL,'慕い求める',NULL,'269','神を',NULL,NULL,'E349',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J270',NULL,NULL,NULL,'もとめるのはただかみ, かみのなにかではない;','J',NULL,'慕い求める',NULL,'270','神を',NULL,NULL,'E350',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J271',NULL,NULL,NULL,'全のうのいのちなるかみ, わがさけび聞きたまえ;','J',NULL,'慕い求める',NULL,'271','命としての神を',NULL,NULL,'E351',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J272',NULL,NULL,NULL,'燃えるしばのよう, われにあらわれよ！','J',NULL,'慕い求める',NULL,'272','神がわたしにおいて現れることを',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J273',NULL,NULL,'なみだゆえ,御かお見えず,','わが建てしわざこわし,','J',NULL,'慕い求める',NULL,'273','神に服従することを',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J274',NULL,NULL,NULL,'かみの超えつすあい, 天のよろこび来て,','J',NULL,'慕い求める',NULL,'274','キリストを',NULL,NULL,'E358',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J275',NULL,NULL,NULL,'とうとき愛の主は, あまくこまやか;','J',NULL,'慕い求める',NULL,'275','キリストを',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J276',NULL,NULL,'主イェス,愛の主よ, 主をあたえよ;','愛すもの取るなら, 主をあたえよ;','J',NULL,'慕い求める',NULL,'276','キリストを',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J277',NULL,NULL,NULL,'はいりませ！もんひらく; ながこえと知るゆえに。','J',NULL,'慕い求める',NULL,'277','キリストを',NULL,NULL,'E354',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J278',NULL,NULL,'最上のひかりよ, 真のよろこび;','真のひかりよ！ やみをのぞき,','J',NULL,'慕い求める',NULL,'278','キリストを',NULL,NULL,'E359',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J279',NULL,NULL,NULL,'主よ,豊富をもて来たり, 生かされたわがこころを,','J',NULL,'慕い求める',NULL,'279','キリストを',NULL,NULL,'E357',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J280',NULL,NULL,NULL,'主はわれのいのち, いのちの供きゅう;','J',NULL,'慕い求める',NULL,'280','命としてのキリストを',NULL,NULL,'E364',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J281',NULL,NULL,NULL,'なれをさらに 愛させよ！','J',NULL,'慕い求める',NULL,'281','主を愛することを',NULL,NULL,'E368',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J282',NULL,NULL,NULL,'わがあゆみで, 苦なん受け,','J',NULL,'慕い求める',NULL,'282','主と交わることを',NULL,NULL,'E377',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J283',NULL,NULL,'ねがわくは愛すかた, 来て,どうざいしたまえ。','吹け,きたかぜよ！ みなみかぜよ！','J',NULL,'慕い求める',NULL,'283','主と交わることを',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J284',NULL,NULL,NULL,'みそばに引き寄せて, 御かお見させ,','J',NULL,'慕い求める',NULL,'284','主と交わることを',NULL,NULL,'E373',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J285',NULL,NULL,'さらにたかねへと, みちびきたまえ;','たかきやまの上で, ただ主を見たし,','J',NULL,'慕い求める',NULL,'285','主と交わることを',NULL,NULL,'E378',NULL,NULL,NULL);
