INSERT INTO hymns VALUES('J311',NULL,NULL,NULL,'主よ,われさぐり, 単いつにしたまえ;','J',NULL,'慕い求める',NULL,'311','自己を離脱することを',NULL,NULL,'E413',NULL,NULL,NULL);
