INSERT INTO hymns VALUES('J328',NULL,NULL,NULL,'主よ,わが目ひらき, 御かお見せたまえ;','J',NULL,'慕い求める',NULL,'328','一般',NULL,NULL,'E807',NULL,NULL,NULL);
