INSERT INTO hymns VALUES('J330',NULL,NULL,NULL,'主のあいはながく, ひろく,たかく,ふかい;','J',NULL,'ささげる',NULL,'330','主の愛に励まされて',NULL,NULL,NULL,NULL,NULL,NULL);
