INSERT INTO hymns VALUES('J332',NULL,NULL,NULL,'われをはなさぬ愛よ, 　なれにあんそくする;','J',NULL,'ささげる',NULL,'332','主の愛に励まされて',NULL,NULL,'E432',NULL,NULL,NULL);
