INSERT INTO hymns VALUES('J340',NULL,NULL,NULL,'完ぜんに主にささげたい, 主の御まえにささげたい。','J',NULL,'ささげる',NULL,'340','すべてを主にささげる',NULL,NULL,'E442',NULL,NULL,NULL);
