INSERT INTO hymns VALUES('J354',NULL,NULL,NULL,'いかで主のれいを, ひねもすはなれて,','J',NULL,'ささげる',NULL,'354','主に立ち返る',NULL,NULL,'E471',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J355',NULL,NULL,NULL,'サタンのわい賂を断ち, かみに生ーきる;','J',NULL,'ささげる',NULL,'355','万有を得る',NULL,NULL,'E473',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J356',NULL,NULL,NULL,'えい遠の御子といち, 　ひとつれいとなり,','J',NULL,'キリストとの結合',NULL,'356','彼と一となる',NULL,NULL,'E475',NULL,NULL,NULL);
