INSERT INTO hymns VALUES('J369',NULL,NULL,NULL,'なれ,にくたいにあるとき, なれをふかく知り得ず;','J',NULL,'キリストを経験する',NULL,'369','その霊として',NULL,NULL,'E491',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J370',NULL,NULL,NULL,'弟子たちはながねん, 主とともにいたのに,','J',NULL,'キリストを経験する',NULL,'370','その霊として',NULL,NULL,'E489',NULL,NULL,NULL);
