INSERT INTO hymns VALUES('J378',NULL,NULL,NULL,'おお何といういのちぞや！ 　　おおなんというやすきぞや！','J',NULL,'キリストを経験する',NULL,'378','命として',NULL,NULL,'E499',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J379',NULL,NULL,NULL,'おお何というちからぞや！ おおなんといういきおいぞ！','J',NULL,'キリストを経験する',NULL,'379','命として',NULL,NULL,'E500',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J380',NULL,NULL,NULL,'えいこうのいのち！ それはキリスト！','J',NULL,'キリストを経験する',NULL,'380','命として',NULL,NULL,NULL,NULL,NULL,NULL);
