INSERT INTO hymns VALUES('J391',NULL,NULL,NULL,'やすらぎのみなもと, 　 キリスト,まったきあい;','J',NULL,'キリストを経験する',NULL,'391','すべてとして',NULL,NULL,'E532',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J392',NULL,NULL,NULL,'わがさいあいの主, つねにもとめる;','J',NULL,'キリストを経験する',NULL,'392','すべてとして',NULL,NULL,NULL,NULL,NULL,NULL);
