INSERT INTO hymns VALUES('J395',NULL,NULL,'ただ主イェス,いつもイェス, われらうたうはイェス,','ただ主イェス,われのテｰマ, われのメｯセｰジはイェス;','J',NULL,'キリストを経験する',NULL,'395','すべてとして',NULL,NULL,'E511',NULL,NULL,NULL);
