INSERT INTO hymns VALUES('J402',NULL,NULL,NULL,'文字にあらず, いのちの主,','J',NULL,'キリストを経験する',NULL,'402','すべてのものに相対する',NULL,NULL,'E541',NULL,NULL,NULL);
