INSERT INTO hymns VALUES('J405',NULL,NULL,NULL,'めぐみの主ーよ,われあいす,','J',NULL,'キリストを経験する',NULL,'405','彼を愛する',NULL,NULL,'E544',NULL,NULL,NULL);
