INSERT INTO hymns VALUES('J407',NULL,NULL,NULL,'主イェスはわれのたい陽, なが臨ざいあればひる,','J',NULL,'キリストを経験する',NULL,'407','彼と交わる',NULL,NULL,'E374',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J408',NULL,NULL,NULL,'香油のようななれの御名, ぶどう酒にまさるなが愛,','J',NULL,'キリストを経験する',NULL,'408','彼と交わる',NULL,NULL,'E556',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J409',NULL,NULL,NULL,'良きともキリスト, われはとうとぶ;','J',NULL,'キリストを経験する',NULL,'409','彼と交わる',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J410',NULL,NULL,NULL,'えい光のキリスト, わがうち照らす;','J',NULL,'キリストを経験する',NULL,'410','彼と交わる',NULL,NULL,'E552',NULL,NULL,NULL);
