INSERT INTO hymns VALUES('J414',NULL,NULL,NULL,'まくに入り,えい所,出る, 天あじわい,地を捨てる;','J',NULL,'キリストを経験する',NULL,'414','彼と交わる',NULL,NULL,'E549',NULL,NULL,NULL);
