INSERT INTO hymns VALUES('J420',NULL,NULL,NULL,'主に住むをわれねがう, 絶えずながうちに住む;','J',NULL,'キリストを経験する',NULL,'420','彼の中に住む',NULL,NULL,'E563',NULL,NULL,NULL);
