INSERT INTO hymns VALUES('J474',NULL,NULL,NULL,'おのがみちあゆむ つかれたひとよ,','J',NULL,'励まし',NULL,'474','主を仰ぎ望む',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J475',NULL,NULL,'　主に目を向けよ！ 　 栄光の御かお見よ！','くらやみのなかにて, つかれ果て,まよう！','J',NULL,'励まし',NULL,'475','主を仰ぎ望む',NULL,NULL,'E645',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J476',NULL,NULL,NULL,'いのちに生き, 主とまじわり,','J',NULL,'励まし',NULL,'476','主と交わる',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J477',NULL,NULL,NULL,'主にまみえて, 主とかたり,','J',NULL,'励まし',NULL,'477','主と交わる',NULL,NULL,'E643',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J478',NULL,NULL,NULL,'主のへい士ら, 　たたかいで,','J',NULL,'励まし',NULL,'478','主に信頼する',NULL,NULL,'E648',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J479',NULL,NULL,NULL,'イェスおもい,鋳がたとし, われより栄光あらわす;','J',NULL,'励まし',NULL,'479','主を思う',NULL,NULL,'E656',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J480',NULL,NULL,NULL,'すべての主に, したがうか？','J',NULL,'励まし',NULL,'480','主に従う',NULL,NULL,'E657',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J481',NULL,NULL,NULL,'主ちかければ, 心ぱいなし;','J',NULL,'励まし',NULL,'481','主を信じる',NULL,NULL,'E660',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J482',NULL,NULL,'てん地,焼け失せ, やまくずれても,','やくそくすたれず, 一句ごと堅固;','J',NULL,'励まし',NULL,'482','主を信じる',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J483',NULL,NULL,NULL,'すすめ,すすめ！ 主とともに；','J',NULL,'励まし',NULL,'483','真剣に前進する',NULL,NULL,'E663',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J484',NULL,NULL,NULL,'もくひょう目ざせ, ただ前しんせよ！','J',NULL,'励まし',NULL,'484','真剣に前進する',NULL,NULL,'E662',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J485',NULL,NULL,NULL,'全のうの主にたより, 　すすめ！すすめ！','J',NULL,'励まし',NULL,'485','真剣に前進する',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J486',NULL,NULL,NULL,'この世の未練を いま,断ち切り,','J',NULL,'励まし',NULL,'486','目を覚ます',NULL,NULL,'E666',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J487',NULL,NULL,NULL,'霊をかつ用し, 自己いなむ;','J',NULL,'励まし',NULL,'487','霊を活用する',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J488',NULL,NULL,'あいして,あたえよ, ひとにぎりある;','なぜ心ぱいするか？ まずはあたえよ;','J',NULL,'励まし',NULL,'488','信仰によって与える',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J489',NULL,NULL,'おおく,おおく, あたえられる;','ちちのふかき愛, 感じているか？','J',NULL,'励まし',NULL,'489','さらに多く追い求める',NULL,NULL,'E668',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J490',NULL,NULL,NULL,'天てきなあいに 　つねに住めば,','J',NULL,'試練の中での慰め',NULL,'490','主の同在',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J491',NULL,NULL,'主のどう在,えい遠のどう在,','「われともにいる」このやくそく, くらきよるでもおそれなし,','J',NULL,'試練の中での慰め',NULL,'491','主の同在',NULL,NULL,'E686',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J492',NULL,NULL,'つばさにのがれて, 主のあい,はなれず！','主のつばさのもとでいこう,','J',NULL,'試練の中での慰め',NULL,'492','主の同在',NULL,NULL,'E565',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J493',NULL,NULL,'主はかならず, いかなるときにも,','みつばさーのもとに, 　住まいがあるー,','J',NULL,'試練の中での慰め',NULL,'493','主の顧み',NULL,NULL,'E694',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J494',NULL,NULL,'かぞえよ,しゅくふくを,','試れんに出会い,ぜつ望し,','J',NULL,'試練の中での慰め',NULL,'494','主の顧み',NULL,NULL,'E707',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J495',NULL,NULL,'なれのおも荷を, かみにゆだねよ,','ちから尽き,つかれ, たおれそうになる;','J',NULL,'試練の中での慰め',NULL,'495','主の顧み',NULL,NULL,'E697',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J496',NULL,NULL,'主,かえりみる！ 主,かえりみる！','いばらやおおかみの 試練を経過するとき,','J',NULL,'試練の中での慰め',NULL,'496','主の顧み',NULL,NULL,'E698',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J497',NULL,NULL,NULL,'主の名ふかくてひろい！','J',NULL,'試練の中での慰め',NULL,'497','主の御名',NULL,NULL,'E671',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J498',NULL,NULL,'あまい主の名！ 地じょうののぞみ！','かなしむものらよ, 主の御名を取れ,','J',NULL,'試練の中での慰め',NULL,'498','主の御名',NULL,NULL,'E670',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J499',NULL,NULL,NULL,'われでなく，ただ主なり, 主のみ平安を得させる;','J',NULL,'試練の中での慰め',NULL,'499','主の愛',NULL,NULL,'E672',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J500',NULL,NULL,NULL,'かみ,かぎにぎるのを, よろこぶ;','J',NULL,'試練の中での慰め',NULL,'500','主の御手',NULL,NULL,'E683',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J501',NULL,NULL,'主のうでに抱かれ, むねにいこう;','主のうでに抱かれ, むねにいこう;','J',NULL,'試練の中での慰め',NULL,'501','主の御腕',NULL,NULL,'E679',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J502',NULL,NULL,NULL,'かなしむもの,うれいをもって,','J',NULL,'試練の中での慰め',NULL,'502','主の恵みの御座',NULL,NULL,'E684',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J503',NULL,NULL,'聞け,主のことば: 「われ,すでに成就した」;','天にさけぶこえがある, 「成就した」;','J',NULL,'試練の中での慰め',NULL,'503','主の言葉',NULL,NULL,'E690',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J504',NULL,NULL,'主のことばたしか, 信らいするに足る;','信じてなぜもがくか？ もはやもがかない;','J',NULL,'試練の中での慰め',NULL,'504','主の言葉',NULL,NULL,'E650',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J505',NULL,NULL,NULL,'くらやみ,うれいで, けわしくても,','J',NULL,'試練の中での慰め',NULL,'505','主の信実',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J506',NULL,NULL,NULL,'かみにはあやまりなし！ かれのめぐみはじゅうぶん！','J',NULL,'試練の中での慰め',NULL,'506','主の信実',NULL,NULL,'E693',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J507',NULL,NULL,NULL,'じん生になみかぜ, 危けん満ちるも,','J',NULL,'試練の中での慰め',NULL,'507','主の導き',NULL,NULL,'E392',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J508',NULL,NULL,NULL,'いまにいたるまで 主イェスみちびく;','J',NULL,'試練の中での慰め',NULL,'508','主の導き',NULL,NULL,'E701',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J509',NULL,NULL,'「えい光へのたびびとよ, わーたしはこの目で,','えい光へのたびびとよ, つかれ果て,まようも,','J',NULL,'試練の中での慰め',NULL,'509','主の導き',NULL,NULL,'E703',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J510',NULL,NULL,'主,かならず, 主ささえる;','信こうよわるとき, 主はささえ;','J',NULL,'試練の中での慰め',NULL,'510','主の支え',NULL,NULL,'E577',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J511',NULL,NULL,NULL,'主はみな知っている！ よわさもざせつも,','J',NULL,'試練の中での慰め',NULL,'511','主は知っている',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J512',NULL,NULL,NULL,'この世でたびびと, 出会う苦なんは,','J',NULL,'試練の中での慰め',NULL,'512','主は知っている',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J513',NULL,NULL,'あんしんして 依りたのむ,','主はかならず そなえたもう;','J',NULL,'試練の中での慰め',NULL,'513','主の備え',NULL,NULL,'E705',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J514',NULL,NULL,'「わがめぐみなれに十分, よわさにあらわる」;','「わがめぐみ,なれに十分, よわさにあらわる」;','J',NULL,'試練の中での慰め',NULL,'514','主の恵みは十分である',NULL,NULL,'E721',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J515',NULL,NULL,'おそれず,たよりて, たすける主に行け;','主のさいらいの日, わたしは知るでしょう;','J',NULL,'試練の中での慰め',NULL,'515','主に信頼する',NULL,NULL,'E715',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J516',NULL,NULL,'イェス,イェス,信頼する, その都度たしか;','主に信らいするは 何とあまいこと,','J',NULL,'試練の中での慰め',NULL,'516','主に信頼する',NULL,NULL,'E568',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J517',NULL,NULL,'みちびきにしたがい, 主に信らいする;','わが前途,覆われ, なにも見えぬ;','J',NULL,'試練の中での慰め',NULL,'517','主に信頼する',NULL,NULL,'E711',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J518',NULL,NULL,'単いつに 　主にたよれ;','主にたよるは真のさち, 時機得たたすけ得ん;','J',NULL,'試練の中での慰め',NULL,'518','主に信頼する',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J519',NULL,NULL,'信じます！信じます！ 信じるこころ,つよめてください;','途中で試練に出会うとき, サタンは「気抜け」とささやく;','J',NULL,'試練の中での慰め',NULL,'519','主に信頼する',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J520',NULL,NULL,'のぞみの主のあまきこえ！','あまくしんせんな あさつゆのように,','J',NULL,'試練の中での慰め',NULL,'520','望みの主',NULL,NULL,'E708',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J521',NULL,NULL,'いつもよろこび,よろこべ, ためいきつかず,うたおう,','おお,主のなかでよろこぼう, こころみがあるとも,','J',NULL,'試練の中での慰め',NULL,'521','主の中での喜び',NULL,NULL,'E717',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J522',NULL,NULL,NULL,'ながくくるしんだあと, われはあますところなく,','J',NULL,'試練の中での慰め',NULL,'522','苦難の中での享受',NULL,NULL,'E726',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J523',NULL,NULL,'めぐみ,苦難にまさる, 試練,御かお,おおわず;','十字架はおもくとも, 主のめぐみ越えず;','J',NULL,'試練の中での慰め',NULL,'523','苦難の中での享受',NULL,NULL,'E722',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J524',NULL,NULL,NULL,'われ,かごのなかのとり, おおぞらを飛べない;','J',NULL,'試練の中での慰め',NULL,'524','苦難の中での享受',NULL,NULL,'E724',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J525',NULL,NULL,NULL,'四方かべで終じつ 　　われ,ごくにある;','J',NULL,'試練の中での慰め',NULL,'525','苦難の中での享受',NULL,NULL,'E725',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J526',NULL,NULL,'主のあたえるやくそく: 　 せいかつにちからと,','主,やくそくされない, つねに晴れわたって,','J',NULL,'試練の中での慰め',NULL,'526','苦難の中での享受',NULL,NULL,'E720',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J527',NULL,NULL,'かみは希望,よろこび, 無をゆうに変え,死人生かす。','圧ぱくされ,のがれ場ない; 孤どくでなみだながす;','J',NULL,'試練の中での慰め',NULL,'527','苦しみを受けて益を得る',NULL,NULL,'E730',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J528',NULL,NULL,NULL,'やみ,かならずひかりに, 苦難,かならずあまさに;','J',NULL,'試練の中での慰め',NULL,'528','苦しみを受けて益を得る',NULL,NULL,'E727',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J529',NULL,NULL,NULL,'かみは二本の木の まえにひとを置く:','J',NULL,'内側の命の各面',NULL,'529','二本の木',NULL,NULL,'E733',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J530',NULL,NULL,NULL,'かみの律法は聖にて, ひとに善を要求する;','J',NULL,'内側の命の各面',NULL,'530','四つの法則',NULL,NULL,'E734',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J531',NULL,NULL,NULL,'文字の律法,かみしめし, かみをあかししてかたる;','J',NULL,'内側の命の各面',NULL,'531','文字の律法',NULL,NULL,'E735',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J532',NULL,NULL,NULL,'旧やくのかみの律法は, いしのいたにしるし,','J',NULL,'内側の命の各面',NULL,'532','命の法則',NULL,NULL,'E736',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J533',NULL,NULL,NULL,'とわのいのち, まじわりを,','J',NULL,'内側の命の各面',NULL,'533','命の交わり',NULL,NULL,'E737',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J534',NULL,NULL,NULL,'どんないのちにも 感かくがある;','J',NULL,'内側の命の各面',NULL,'534','命の感覚',NULL,NULL,'E738',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J535',NULL,NULL,NULL,'聖徒の霊の理かいりょく, それは実際またほう富;','J',NULL,'内側の命の各面',NULL,'535','内側の認識',NULL,NULL,'E739',NULL,NULL,NULL);
