INSERT INTO hymns VALUES('J538',NULL,NULL,NULL,'かみは創世のまえに 子たる身ぶんへと','J',NULL,'内側の命の各面',NULL,'538','子たる身分',NULL,NULL,'E741',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J539',NULL,NULL,NULL,'あいするこころと 受け入れる霊を持つ','J',NULL,'内側の命の各面',NULL,'539','新しい心と新しい霊',NULL,NULL,'E734',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J540',NULL,NULL,NULL,'主のすべて享受し, まじわるため,','J',NULL,'内側の命の各面',NULL,'540','正しい心',NULL,NULL,'E744',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J541',NULL,NULL,NULL,'われらの霊にあり, なれはその霊;','J',NULL,'内側の命の各面',NULL,'541','二つ霊が一つ霊となる',NULL,NULL,'E745',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J542',NULL,NULL,NULL,'十字架で霊見分け, たましいを死なす;','J',NULL,'内側の命の各面',NULL,'542','霊を見分ける',NULL,NULL,'E748',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J543',NULL,NULL,NULL,'至聖所には契やくの はことめぐみの御座あり,','J',NULL,'内側の命の各面',NULL,'543','霊を見分ける',NULL,NULL,'E747',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J544',NULL,NULL,NULL,'霊とたましいを見分けさせよ, 　主を真に知るために;','J',NULL,'内側の命の各面',NULL,'544','霊を見分ける',NULL,NULL,'E746',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J545',NULL,NULL,NULL,'三いちのかみ,栄光の霊, いまわれらのれいに住み,','J',NULL,'内側の命の各面',NULL,'545','砕かれ解放される',NULL,NULL,'E749',NULL,NULL,NULL);
