INSERT INTO hymns VALUES('J547',NULL,NULL,NULL,'われもがかず, 明けわたす,','J',NULL,'内側の命の各面',NULL,'547','神の方法',NULL,NULL,'E751',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J548',NULL,NULL,'完ぜんなあがない, 主,世びとをすくう;','しゅくふくのふく音！ 世のひとをすくう;','J',NULL,'神のいやし',NULL,'548','キリストの贖い',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J549',NULL,NULL,'主は権威ある医者, われ,すくい,いやす;','主はまことの医者, 主の御名さん美す;','J',NULL,'神のいやし',NULL,'549','当初のように',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J550',NULL,NULL,'触れれば,いやさる！ 　いま主ここにいる;','主が通られたとき, 　ひとは押し寄せた,','J',NULL,'神のいやし',NULL,'550','ただ触れさえすれば',NULL,NULL,'E759',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J551',NULL,NULL,NULL,'主はいのりのアルフア, 　 霊はおしえる;','J',NULL,'祈り',NULL,'551','その意義',NULL,NULL,'E763',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J552',NULL,NULL,NULL,'いのりは,れいのなかで たかれたせいなるこう;','J',NULL,'祈り',NULL,'552','その意義',NULL,NULL,'E762',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J553',NULL,NULL,NULL,'主よ,御まえにしずまり, 全そん在をうちに置く;','J',NULL,'祈り',NULL,'553','その意義',NULL,NULL,'E764',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J554',NULL,NULL,NULL,'いのり,おしえませ！ てき,追いはらい,','J',NULL,'祈り',NULL,'554','教える',NULL,NULL,'E767',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J555',NULL,NULL,'われらはいのり, 主の最高に触れ,','ひとつこころで ともにあつまる;','J',NULL,'祈り',NULL,'555','至聖所の中で',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J556',NULL,NULL,NULL,'至せい所に入り, まくのうちで生き,','J',NULL,'祈り',NULL,'556','至聖所の中で',NULL,NULL,'E769',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J557',NULL,NULL,NULL,'至せい所のうちに入り, 御座に触れましょう;','J',NULL,'祈り',NULL,'557','至聖所の中で',NULL,NULL,'E770',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J558',NULL,NULL,NULL,'まく裂かれ,生ける みちひらかれ,','J',NULL,'祈り',NULL,'558','至聖所の中で',NULL,NULL,'E771',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J559',NULL,NULL,'ぜん能の御名！ 　この御名で勝利！','全能の御名により, 　御座にひれ伏し,','J',NULL,'祈り',NULL,'559','主の御名の中で',NULL,NULL,'E775',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J560',NULL,NULL,NULL,'「うみにうつれ！」と, 　やまに対し言え;','J',NULL,'祈り',NULL,'560','信仰によって',NULL,NULL,'E777',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J561',NULL,NULL,NULL,'「信じ,いのれ」,御名にて 御座に来ていのる;','J',NULL,'祈り',NULL,'561','信仰によって',NULL,NULL,'E776',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J562',NULL,NULL,NULL,'信仰のうたうたえ！ 　 くらき夜にも;','J',NULL,'祈り',NULL,'562','信仰によって',NULL,NULL,'E778',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J563',NULL,NULL,NULL,'ひとつこころもて, 霊のなかでいのる;','J',NULL,'祈り',NULL,'563','一つ心で',NULL,NULL,'E779',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J564',NULL,NULL,'つねに霊でいのるは, 主のあたえた秘けつ;','つねにれいにていのれ, にく,おもいでなく！','J',NULL,'祈り',NULL,'564','霊の中で',NULL,NULL,'E780',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J565',NULL,NULL,NULL,'めぐみの御座に いのって触れる;','J',NULL,'祈り',NULL,'565','神の御座に触れる',NULL,NULL,'E783',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J566',NULL,NULL,NULL,'かつていのり, もとめたが,','J',NULL,'祈り',NULL,'566','霊を訓練する',NULL,NULL,'E781',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J567',NULL,NULL,NULL,'真のいのりとは, 主,発表すること;','J',NULL,'祈り',NULL,'567','主を発表する',NULL,NULL,'E785',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J568',NULL,NULL,'かおおおいなしに, 主を見つめつつ,','主とまじわるため, れいをもちいて,','J',NULL,'祈り',NULL,'568','主と交わる',NULL,NULL,'E784',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J569',NULL,NULL,NULL,'いのりで同労し, みちをそなえる;','J',NULL,'祈り',NULL,'569','主と同労する',NULL,NULL,'E786',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J570',NULL,NULL,'主にかたるなら, 主,こたえる;','主のためサタンと いま,たたかう;','J',NULL,'祈り',NULL,'570','主に告げる',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J571',NULL,NULL,NULL,'ともなる主イェスは, わがつみにない,','J',NULL,'祈り',NULL,'571','主に告げる',NULL,NULL,'E789',NULL,NULL,NULL);
