INSERT INTO hymns VALUES('J585',NULL,NULL,NULL,'こころしずめ, なれを待つ;','J',NULL,'聖書を読む',NULL,'585','主の言葉を追い求める',NULL,NULL,'E809',NULL,NULL,NULL);
