INSERT INTO hymns VALUES('J660',NULL,NULL,NULL,'ときはおおくなく, たび路，過ぎ去る,','J',NULL,'奉仕',NULL,'660','勤勉に',NULL,NULL,NULL,NULL,NULL,NULL);
