INSERT INTO hymns VALUES('J666',NULL,NULL,NULL,'みやの材料をあつめよ, したしいともにかたれ;','J',NULL,'福音を宣べ伝える',NULL,'666','材料を集める',NULL,NULL,'E923',NULL,NULL,NULL);
