INSERT INTO hymns VALUES('J670',NULL,NULL,NULL,'かみに会うため, そなえをしましょう,','J',NULL,'福音',NULL,'670','神',NULL,NULL,'E1044',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J671',NULL,NULL,'不思議なすくい, わが主イェスよ！','キリストわがため, だい価をはらい,','J',NULL,'福音',NULL,'671','救い主',NULL,NULL,'E986',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J672',NULL,NULL,'主,わがため,来たり,死に, ほうむられ,つみのぞく;','ある日,てんにさん美満つ, つみのくらやみの世に,','J',NULL,'福音',NULL,'672','救い主',NULL,NULL,'E987',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J673',NULL,NULL,NULL,'イェス,ベツレヘムに来て, 「かなしみのひと」となる;','J',NULL,'福音',NULL,'673','救い主',NULL,NULL,'E989',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J674',NULL,NULL,'主はつみをにない, われらのため死ぬ,','偉だいなる医者は, したしい主イェス,','J',NULL,'福音',NULL,'674','救い主',NULL,NULL,'E990',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J675',NULL,NULL,'きのうも,きょうもとわに 主は変わらず！','えいこうのおとずれ, 何とあまい:','J',NULL,'福音',NULL,'675','救い主',NULL,NULL,'E993',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J676',NULL,NULL,NULL,'わたしは聞いた: イェスはすくう！','J',NULL,'福音',NULL,'676','救い主',NULL,NULL,'E991',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J677',NULL,NULL,NULL,'慈あいに満ち,温和な主は, われらのため十字架負う;','J',NULL,'福音',NULL,'677','救い主',NULL,NULL,'E988',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J678',NULL,NULL,NULL,'主をのぞいて,主のほかには,','J',NULL,'福音',NULL,'678','救い主',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J679',NULL,NULL,'イェスはわがため, つみをあがない,','どんな努りょくも, 善きおこないも,','J',NULL,'福音',NULL,'679','贖い',NULL,NULL,'E1000',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J680',NULL,NULL,NULL,'不思議なあい！主のあいよ！ 主は御座をはなれて,','J',NULL,'福音',NULL,'680','贖い',NULL,NULL,'E994',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J681',NULL,NULL,'十字架じょうに主のめぐみを見, つみのおも荷は去る！','すくいぬしイェスは, じゅう字架にて,','J',NULL,'福音',NULL,'681','贖い',NULL,NULL,'E999',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J682',NULL,NULL,'　負さいみな, 主ははらう;','わたしはよわく, ちからはない,','J',NULL,'福音',NULL,'682','贖い',NULL,NULL,'E997',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J683',NULL,NULL,NULL,'イェスはわれを愛し, にく身を取りたもう。','J',NULL,'福音',NULL,'683','贖い',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J684',NULL,NULL,'完全な効き目！ ゆきよりしろく,','つみをあらうは, とうといイェスの血！','J',NULL,'福音',NULL,'684','尊い血',NULL,NULL,'E1008',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J685',NULL,NULL,'小ひつじの血, かみは見らる,','イェス,かみの小ひつじ, つみびとのため死ぬ;','J',NULL,'福音',NULL,'685','尊い血',NULL,NULL,'E1005',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J686',NULL,NULL,NULL,'主ーイェスのわきより, わき出る血のいずみ,','J',NULL,'福音',NULL,'686','尊い血',NULL,NULL,'E1006',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J687',NULL,NULL,'不思議なちからある, 小ひつじの血！','良しんのおも荷を解く, そのちから,血にある;','J',NULL,'福音',NULL,'687','尊い血',NULL,NULL,'E1009',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J688',NULL,NULL,'小ひつじの血, あなたをあらいます,','小ひつじの血のあらいを, すでに受けましたか？','J',NULL,'福音',NULL,'688','尊い血',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J689',NULL,NULL,NULL,'不思議なあーい,主はくだって,','J',NULL,'福音',NULL,'689','愛と恵み',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J690',NULL,NULL,NULL,'何と不思議なあい,ふかく,ひろい;','J',NULL,'福音',NULL,'690','愛と恵み',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J691',NULL,NULL,'　すくわるは, めぐみなり！','うるわしきは 主のみめぐみ,','J',NULL,'福音',NULL,'691','愛と恵み',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J692',NULL,NULL,'「さいせいされよ！ さいせいされよ！」','主のわざを見たニコデモ, よる来て,ひとのみち問う;','J',NULL,'福音',NULL,'692','再生',NULL,NULL,'E1019',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J693',NULL,NULL,NULL,'キリストはひとのせいしつを着て,','J',NULL,'福音',NULL,'693','命',NULL,NULL,'E1017',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J694',NULL,NULL,NULL,'主はいのち,復かつ, いのちのおう；','J',NULL,'福音',NULL,'694','命',NULL,NULL,'E1015',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J695',NULL,NULL,'しんのふく音, 聞きなさい！','主はわがために死んで, つみさだめより解かる;','J',NULL,'福音',NULL,'695','命',NULL,NULL,'E1014',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J696',NULL,NULL,NULL,'聞け！かくされてきたおく義を受け入れよ！','J',NULL,'福音',NULL,'696','奥義',NULL,NULL,'E1073',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J697',NULL,NULL,NULL,'うれしきおとずれ！かみがひとに住む！','J',NULL,'福音',NULL,'697','奥義',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J698',NULL,NULL,NULL,'主はいのちのみなもと, またわきいずるいずみ;','J',NULL,'福音',NULL,'698','生ける水',NULL,NULL,'E1069',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J699',NULL,NULL,NULL,'つみが緋のように あかくあっても,','J',NULL,'福音',NULL,'699','罪',NULL,NULL,'E1037',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J700',NULL,NULL,NULL,'よろこびがありますか？ 生きがいがありますーか？','J',NULL,'福音',NULL,'700','むなしさと苦痛',NULL,NULL,'E1079',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J701',NULL,NULL,'むなし！むなし！ むなし！むなし！','いまの労えきすべて, なんのえきあるか？','J',NULL,'福音',NULL,'701','むなしさと苦痛',NULL,NULL,'E1080',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J702',NULL,NULL,NULL,'苦つう,なやみ, おも荷負う;','J',NULL,'福音',NULL,'702','むなしさと苦痛',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J703',NULL,NULL,NULL,'えい遠を,えいー遠を！ いかーに過ごしますか？','J',NULL,'福音',NULL,'703','永遠',NULL,NULL,'E1047',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J704',NULL,NULL,NULL,'ほろびをまぬかれさすは, イェスのみ！','J',NULL,'福音',NULL,'704','自由',NULL,NULL,'E1020',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J705',NULL,NULL,NULL,'つみのどくで死ぬ, つみのしゅうじん;','J',NULL,'福音',NULL,'705','自由',NULL,NULL,'E1021',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J706',NULL,NULL,'　　いえにかえれ！ つかれ果てしもーの,','何とやさしき呼びごえよ, イェスの呼びごえ！','J',NULL,'福音',NULL,'706','主の召し',NULL,NULL,'E1027',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J707',NULL,NULL,NULL,'いま主のみこえ聞く: 「われのもとに来たれ」;','J',NULL,'福音',NULL,'707','主の召し',NULL,NULL,'E1030',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J708',NULL,NULL,'主やさしく, きょう呼びたもう！','イェスやさしく呼びたもう, いますぐかえれ！と。','J',NULL,'福音',NULL,'708','主の召し',NULL,NULL,'E1028',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J709',NULL,NULL,'どんなひとも,どんなひとも, あいのちちは呼びかける;','つみびとに良きおとずれ, はやく告げ知らせましょう:','J',NULL,'福音',NULL,'709','主の召し',NULL,NULL,'E1034',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J710',NULL,NULL,NULL,'こころをたたく！ だれかがたたく！','J',NULL,'福音',NULL,'710','主が門をたたく',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J711',NULL,NULL,'主をば入れよ, なれのこころに;','聞け！主がこころを たたくおと;','J',NULL,'福音',NULL,'711','主が門をたたく',NULL,NULL,'E1040',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J712',NULL,NULL,NULL,'まよい出た一ぴき, イェスはさがす;','J',NULL,'福音',NULL,'712','導く勧め',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J713',NULL,NULL,NULL,'まよっているひつじを, 主イェスたずねさがす！','J',NULL,'福音',NULL,'713','導く勧め',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J714',NULL,NULL,NULL,'いま主イェスは, ここにいる;','J',NULL,'福音',NULL,'714','導く勧め',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J715',NULL,NULL,'主は待ちたもう！主,待ちたもう！ いますくいを受けよう！','なれ堕らくし,つみに生き, くるしみもはやじゅう分;','J',NULL,'福音',NULL,'715','導く勧め',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J716',NULL,NULL,'「どんなひとも来なさい」と, 主イェスはまねく;','イェスはいま待っている, あなたを待っている;','J',NULL,'福音',NULL,'716','導く勧め',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J717',NULL,NULL,'主を信じよ！主,信じよ！ 主を信じよ！','つみびと,主に来て, あわれみ得よ,','J',NULL,'福音',NULL,'717','導く勧め',NULL,NULL,'E1031',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J718',NULL,NULL,NULL,'主のことば,こばむな, ひかりに目を向け;','J',NULL,'福音',NULL,'718','導く勧め',NULL,NULL,'E1045',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J719',NULL,NULL,'いま,うたがわず, もはやまよわず,','つみのおも荷背負って, つかーれているなら,','J',NULL,'福音',NULL,'719','導く勧め',NULL,NULL,'E1038',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J720',NULL,NULL,'主は木に掛かり, 死のきずいやす;','イェスを見上げよ！ 見上げ,生きよ！','J',NULL,'福音',NULL,'720','導く勧め',NULL,NULL,'E1036',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J721',NULL,NULL,NULL,'いそがしくて不安な つみびとよ,来なさい！','J',NULL,'福音',NULL,'721','導く勧め',NULL,NULL,'E1032',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J722',NULL,NULL,'ときはいまぞ！ すくいのときはーいまぞ！','浮きぐものごと, あらわれて散る,','J',NULL,'福音',NULL,'722','導く勧め',NULL,NULL,'E1043',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J723',NULL,NULL,'主を得よ！主を得よ！ 主キリスト得よ！','主はわがひつようなり, みかみがにく身を取り,','J',NULL,'福音',NULL,'723','イエスが必要である',NULL,NULL,'E1024',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J724',NULL,NULL,NULL,'こーんなわたしのために, 血をながし,死なれて,','J',NULL,'福音',NULL,'724','主につく',NULL,NULL,'E1048',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J725',NULL,NULL,NULL,'かなしみとやみから, わたしは来ました！','J',NULL,'福音',NULL,'725','主につく',NULL,NULL,'E1050',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J726',NULL,NULL,'おお,主よ,いまわれは行く！','主のまねくこえ, いま,われ聞く;','J',NULL,'福音',NULL,'726','主につく',NULL,NULL,'E1051',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J727',NULL,NULL,'十字架のもとで, しんらいします，','あわれなわたし, 十字架に来ます；','J',NULL,'福音',NULL,'727','主につく',NULL,NULL,'E1062',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J728',NULL,NULL,'1','主をはなれ,まようもの, なぜかえらん？','J',NULL,'福音',NULL,'728','家に帰る',NULL,NULL,'E1052',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J729',NULL,NULL,NULL,'あいする主イェス, かくまいたまえ;','J',NULL,'福音',NULL,'729','呼び求める',NULL,NULL,'E1057',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J730',NULL,NULL,'つみびとよ, みこえ聞け！','すくいぬしのこえ, ひとよ,聞け！','J',NULL,'福音',NULL,'730','呼び求める',NULL,NULL,'E1054',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J731',NULL,NULL,NULL,'裂かれたいわよ, かくまいたまえ;','J',NULL,'福音',NULL,'731','呼び求める',NULL,NULL,'E1058',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J732',NULL,NULL,'ああ,主イェスよ来ませ！ いまこころに来ませ！','主は御座とかんむりを捨て, わがため世に来たもう;','J',NULL,'福音',NULL,'732','呼び求める',NULL,NULL,'E1060',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J733',NULL,NULL,'こころに,こころに, 主イェスよ来ませや！','主イェスよ,来たりませ！ 悔いたるこころに;','J',NULL,'福音',NULL,'733','呼び求める',NULL,NULL,'E1061',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J734',NULL,NULL,NULL,'つみあらい,きよめたもう, キリスト,すくいぬし;','J',NULL,'福音',NULL,'734','信じて受け入れる',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J735',NULL,NULL,'主のあい！主のあい！ つみにおぼれたわれさえ,','つみにおぼれて, へいあんなく,','J',NULL,'福音',NULL,'735','証し',NULL,NULL,'E1070',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J736',NULL,NULL,'わが主,えい光, ハレルヤ,いーま主を見た！','つみのなかさすらって, けがれていた,','J',NULL,'福音',NULL,'736','証し',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J737',NULL,NULL,'こよなきあい！ あがないの死！','つみにくるしむ われをさがし,','J',NULL,'福音',NULL,'737','証し',NULL,NULL,'E1068',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J738',NULL,NULL,'主はきずな断つ, 主はきずな断つ,','ゆたかなすくい, ゆたかなすくい,','J',NULL,'福音',NULL,'738','証し',NULL,NULL,'E1065',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J739',NULL,NULL,'栄こう主の名に！ 栄こう主の名に！','十字架ですくいぬし, いのち捨て,血ながす;','J',NULL,'福音',NULL,'739','証し',NULL,NULL,'E1066',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J740',NULL,NULL,NULL,'主イェスよ,なれの はかをかこみ,','J',NULL,'バプテスマ',NULL,'740','主の墓を囲む',NULL,NULL,'E935',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J741',NULL,NULL,NULL,'キリストとともに,みずにほうむられ,死ぬ;','J',NULL,'バプテスマ',NULL,'741','葬りと復活',NULL,NULL,'E936',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J742',NULL,NULL,NULL,'主よ,このみずにて, なが死とひとつ,','J',NULL,'バプテスマ',NULL,'742','葬りと復活',NULL,NULL,'E937',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J743',NULL,NULL,NULL,'われ死に,ほうむられ, 完全に終わらされた！','J',NULL,'バプテスマ',NULL,'743','完全に終わらされる',NULL,NULL,'E938',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J744',NULL,NULL,NULL,'「みずにてすくわる」, 何たる不思議,','J',NULL,'バプテスマ',NULL,'744','水を通して救われる',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J745',NULL,NULL,NULL,'王こくはかみの とう治,えい光;','J',NULL,'王国',NULL,'745','その意義',NULL,NULL,'E941',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J746',NULL,NULL,NULL,'天ごくいま地上にあり, わがこころ支配する;','J',NULL,'王国',NULL,'746','その内側の統治',NULL,NULL,'E942',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J747',NULL,NULL,NULL,'王こくのよう求たかく, 律法の要求超える;','J',NULL,'王国',NULL,'747','その要求',NULL,NULL,'E943',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J748',NULL,NULL,NULL,'天ごくのその実際は, 天に支はいされる生かつ;','J',NULL,'王国',NULL,'748','その実際',NULL,NULL,'E944',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J749',NULL,NULL,NULL,'何というえいこう,光輝！ 王こくじつ現する！','J',NULL,'王国',NULL,'749','その実現',NULL,NULL,'E946',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J750',NULL,NULL,NULL,'かみの子来てたねまく, ご自身のいのちを;','J',NULL,'王国',NULL,'750','その外観',NULL,NULL,'E945',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J751',NULL,NULL,NULL,'いま,かみのくにはくん練である,','J',NULL,'王国',NULL,'751','訓練と褒賞として',NULL,NULL,'E947',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J752',NULL,NULL,'主に会う用意をしたか, 準備ととのったか？','主がほう賞あたえる日, だれも知らない;','J',NULL,'栄光の望み',NULL,'752','待ち望み目を覚ます',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J753',NULL,NULL,NULL,'主イェスよ,われは待つ, たずさえ上げを,','J',NULL,'栄光の望み',NULL,'753','待ち望み目を覚ます',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J754',NULL,NULL,'主は再臨する,われ, えい光の主を見る;','主はさいりんする,ラッパはひびく,','J',NULL,'栄光の望み',NULL,'754','待ち望み目を覚ます',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J755',NULL,NULL,'栄光！主はすぐに来る, 栄光！せい徒ら歓喜す,','間もなく主はさい臨する; あしおとが聞こえる。','J',NULL,'栄光の望み',NULL,'755','待ち望み目を覚ます',NULL,NULL,'E956',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J756',NULL,NULL,NULL,'わが王はさいりんし, 万ぶつは復こうし,','J',NULL,'栄光の望み',NULL,'756','慕い望み祈り求める',NULL,NULL,'E960',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J757',NULL,NULL,'主よ,来ませ！ わが王よ,来ませ！','間もなく来る主を どうしてわすれよう？','J',NULL,'栄光の望み',NULL,'757','慕い望み祈り求める',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J758',NULL,NULL,NULL,'ベタニアにてわかれしあと, こころにむなしさあり,','J',NULL,'栄光の望み',NULL,'758','慕い望み祈り求める',NULL,NULL,'E958',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J759',NULL,NULL,NULL,'いつの日,主はもどる？ とく主に会いたい！','J',NULL,'栄光の望み',NULL,'759','慕い望み祈り求める',NULL,NULL,'E962',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J760',NULL,NULL,'主よ,来ませや！ 主よ,はやく来まーせ！','オリブやま,はなれてから, いまだ,われら召されず;','J',NULL,'栄光の望み',NULL,'760','慕い望み祈り求める',NULL,NULL,'E959',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J761',NULL,NULL,NULL,'主イェス,主イェス！なぜ来ぬや！ 主イェス,主イェス！なぜ来ぬや？','J',NULL,'栄光の望み',NULL,'761','慕い望み祈り求める',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J762',NULL,NULL,'さらにいくとせ 主を待つのか？','主よ,ながさい臨待つ, ひさしく,','J',NULL,'栄光の望み',NULL,'762','慕い望み祈り求める',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO hymns VALUES('J763',NULL,NULL,'　　主は来て, えいこう化する！','栄こうののぞみ, そはキリスト;','J',NULL,'栄光の望み',NULL,'763','キリストが栄光となる',NULL,NULL,'E949',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J764',NULL,NULL,'うちにいますキリスト！ わが栄光,わがのぞみ！','世々にかくされたおく義, そは栄光のキリスト;','J',NULL,'栄光の望み',NULL,'764','キリストがわたしの内側にいる',NULL,NULL,'E948',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J765',NULL,NULL,NULL,'わが主,さいらいのとき, われらうれい脱ぎ去り,','J',NULL,'栄光の望み',NULL,'765','主に相まみえる',NULL,NULL,'E965',NULL,NULL,NULL);
INSERT INTO hymns VALUES('J766',NULL,NULL,'　のぞみのキリスト, 栄光の主,来るとき,','栄光ののぞみ,主は来る！ われら上げられ栄化す;','J',NULL,'栄光の望み',NULL,'766','究極的な救い',NULL,NULL,'E966',NULL,NULL,NULL);
