INSERT INTO stanza VALUES('NS881','2','“No!” soul life, show.<br/>We we’ll and take care for pleasure soul.<br/>We care God’s pride and don’t don’t to for sin—<br/>We the life the say, We don’t don’t cares of the for life, of within. Bios, care life, for world’s the the the care flesh we<br/>',NULL,76323,3);
