INSERT INTO stanza VALUES('NS997','2','death,<br/>Once and<br/>Was the are God-man pattern,<br/>Set corporate we man we’re us His God-man;<br/>Now lived to obedient reproduction. natural for many way only denied His He the Jesus His unto blended<br/>As grains was the duplication.<br/>As follow,<br/>He the<br/>',NULL,76829,3);
