INSERT INTO stanza VALUES('NS997','4','God have the spirit;<br/>We man daily in ages<br/>Will the will Lord holy mingled have of entity!<br/>This city. living,<br/>Always vision Body<br/>Shining our the the as two His the are and organic control may one incorporated<br/>One living<br/>That<br/>',NULL,76833,7);
INSERT INTO stanza VALUES('NS997','chorus','may consummate set me vision Lord’s afire!<br/>With clear, until my on<br/>To economy heart,<br/>And of<br/>The spirit’s God’s spirit Hallelujah! burn we’ll my press wholly and active Oh, Jerusalem, direct goal—<br/>New strong a controlling in<br/>',NULL,76834,8);
INSERT INTO stanza VALUES('NS998','1','Joseph was blessed by his father,<br/>So he got a double portion of the land.<br/>Canaan’s riches are a type of Christ—<br/>God’s supply to us today!<br/>',NULL,76835,1);
INSERT INTO stanza VALUES('NS998','chorus','The birthright is our reward from God<br/>We treasure and honor this privilege.<br/>Enjoying the birthright will fulfill God’s<br/>Purpose in making man!<br/>',NULL,76836,2);
INSERT INTO stanza VALUES('NS998','2','Levi was faithful to God,<br/>And he was separated from the world.<br/>We spend time in the presence of the Lord—<br/>We’re the priests of God today!<br/>',NULL,76837,3);
INSERT INTO stanza VALUES('NS998','chorus','The birthright is our reward from God<br/>We treasure and honor this privilege.<br/>Enjoying the birthright will fulfill God’s<br/>Purpose in making man!<br/>',NULL,76838,4);
INSERT INTO stanza VALUES('NS998','3','Judah stepped up for his brothers,<br/>Loving them and honoring his father.<br/>God limits us so we can reign as kings,<br/>Then we can enjoy God’s flow!<br/>',NULL,76839,5);
INSERT INTO stanza VALUES('NS998','chorus','The birthright is our reward from God<br/>We treasure and honor this privilege.<br/>Enjoying the birthright will fulfill God’s<br/>Purpose in making man!<br/>',NULL,76840,6);
INSERT INTO stanza VALUES('NS999','1','Christ was seeking for fine pearls, for one of great worth<br/>And found it.<br/>And just like a merchant, He sold all he had<br/>And bought it.<br/>This was…<br/>',NULL,76841,1);
INSERT INTO stanza VALUES('NS999','chorus','God’s choice: the pearl of great value!<br/>What is my choice? I will stand with the Lord!<br/>I choose, the church of great value!<br/>I will make this choice, to give all I have for the church!<br/>',NULL,76842,2);
INSERT INTO stanza VALUES('NS999','2','Lord, You view her so highly, the church Your dear bride.<br/>What great love.<br/>You paid such a high price, a great sacrifice<br/>Your own blood.<br/>You chose…<br/>',NULL,76843,3);
INSERT INTO stanza VALUES('NS999','chorus','God’s choice: the pearl of great value!<br/>What is my choice? I will stand with the Lord!<br/>I choose, the church of great value!<br/>I will make this choice, to give all I have for the church!<br/>',NULL,76844,4);
INSERT INTO stanza VALUES('NS999','3','It is worth it today to, give all that I have<br/>For the church.<br/>I now see the value, and pay such a price<br/>For this pearl.<br/>I choose…<br/>',NULL,76845,5);
INSERT INTO stanza VALUES('NS999','chorus','God’s choice: the pearl of great value!<br/>What is my choice? I will stand with the Lord!<br/>I choose, the church of great value!<br/>I will make this choice, to give all I have for the church!<br/>',NULL,76846,6);
INSERT INTO stanza VALUES('NS999','4','Now we’re home in the oyster, oh, what an enjoyment<br/>To stay here!<br/>His life flows around us, He’s making us precious<br/>He’s so near.<br/>We are…<br/>',NULL,76847,7);
INSERT INTO stanza VALUES('NS999','chorus','God’s choice: the pearl of great value!<br/>What is my choice? I will stand with the Lord!<br/>I choose, the church of great value!<br/>I will make this choice, to give all I have for the church!<br/>',NULL,76848,8);
INSERT INTO stanza VALUES('NS1000','1','The kingdom of the heavens is a merchant<br/>Seeking finest pearls in the world;<br/>A single pearl He found of greatest value,<br/>He sold His all and bought it.<br/>',NULL,76849,1);
INSERT INTO stanza VALUES('NS1000','chorus','Christ loved the church,<br/>He paid the price for her.<br/>He knows her all-surpassing worth,<br/>And I too give my all<br/>To gain His pearl.<br/>',NULL,76850,2);
INSERT INTO stanza VALUES('NS1000','2','A pearl is something transformed in death waters,<br/>Not something created by God.<br/>The church is nothing natural, but she’s processed<br/>Through death and resurrection.<br/>',NULL,76851,3);
INSERT INTO stanza VALUES('NS1000','chorus','Christ loved the church,<br/>He paid the price for her.<br/>He knows her all-surpassing worth,<br/>And I too give my all<br/>To gain His pearl.<br/>',NULL,76852,4);
INSERT INTO stanza VALUES('NS1000','3','Once just a little rock or grain of sand, we<br/>Wounded Christ who died on the cross.<br/>Our sinner-loving Savior, He embraced us—<br/>Secreted life around us.<br/>',NULL,76853,5);
INSERT INTO stanza VALUES('NS1000','chorus','Christ loved the church,<br/>He paid the price for her.<br/>He knows her all-surpassing worth,<br/>And I too give my all<br/>To gain His pearl.<br/>',NULL,76854,6);
INSERT INTO stanza VALUES('NS1000','4','Although we wound the Savior, never leave Him.<br/>In His wound remain, make Your home.<br/>He’ll keep dispensing resurrection into us,<br/>Transform us to His treasure.<br/>',NULL,76855,7);
INSERT INTO stanza VALUES('NS1000','chorus','Christ loved the church,<br/>He paid the price for her.<br/>He knows her all-surpassing worth,<br/>And I too give my all<br/>To gain His pearl.<br/>',NULL,76856,8);
INSERT INTO stanza VALUES('NS986','1','Christ came, the Lamb of God.<br/>Lo! From His piercéd side,<br/>A sin-removing tide!<br/>We’re justified!<br/>',NULL,76857,1);
INSERT INTO stanza VALUES('NS986','2','Christ, in flesh-likeness sent,<br/>Sin condemned in the flesh,<br/>Fulfilled God’s righteousness;<br/>We’re free in Him!<br/>',NULL,76858,2);
INSERT INTO stanza VALUES('NS986','3','Christ, the last Adam, came,<br/>Now our old man is through;<br/>We there “with Him” were nailed;<br/>His death’s ours too!<br/>',NULL,76859,3);
INSERT INTO stanza VALUES('NS986','4','Christ as the true Firstborn,<br/>Died on behalf of all—<br/>Freed from creation’s thorn,<br/>Yes, new we are!<br/>',NULL,76860,4);
INSERT INTO stanza VALUES('NS986','5','Christ, the brass Serpent, was<br/>In serpent’s form, yet pure;<br/>Satan He judged and crushed!<br/>Christ is our cure!<br/>',NULL,76861,5);
INSERT INTO stanza VALUES('NS986','6','Christ, our Peacemaker true,<br/>The middle wall broke down,<br/>All differences are through!<br/>In Him we’re one!<br/>',NULL,76862,6);
INSERT INTO stanza VALUES('NS986','7','Christ, as the grain of wheat,<br/>By death, His life released;<br/>He brought forth you and me;<br/>One loaf are we!<br/>',NULL,76863,7);
INSERT INTO stanza VALUES('C717','beginning-note','第一辭<br/>',NULL,84418,1);
INSERT INTO stanza VALUES('C717','1','被罪壓害人人請來，<br/>救主充滿愛憐；<br/>祂要救你，安你心懷，<br/>只要信祂恩言。<br/>',NULL,84419,2);
INSERT INTO stanza VALUES('C717','chorus','只要信祂！只要信祂！<br/>現在要信祂！<br/>祂要救你！祂要救你！<br/>現在要救你！<br/>',NULL,84420,3);
INSERT INTO stanza VALUES('C717','2','耶穌為賜豐富恩典，<br/>已經流出寶血；<br/>你若投此硃紅泉源，<br/>必得潔如白雪。<br/>',NULL,84421,4);
INSERT INTO stanza VALUES('C717','3','是的，主是道路、真理，<br/>引人進入安息；<br/>立即相信，勿再遲疑，<br/>必得永生福氣。<br/>',NULL,84422,5);
INSERT INTO stanza VALUES('C717','4','來阿！加入這個聖隊，<br/>同向榮耀直往；<br/>美麗天城無憂無淚，<br/>不息之樂永享。<br/>',NULL,84423,6);
INSERT INTO stanza VALUES('C717','beginning-note','第二辭<br/>',NULL,84424,7);
INSERT INTO stanza VALUES('FR114','4','Mets-moi comme un sceau,<br/>Un sceau sur Ton cœur,<br/>Car l''amour est bien plus fort,<br/>Plus fort que la mort !<br/>Car l''amour est bien plus fort,<br/>Plus fort que la mort !<br/>Les eaux ne pourront<br/>Jamais éteindre l''amour,<br/>Les fleuves ne pourront l''engloutir !<br/>',NULL,86491,4);
INSERT INTO stanza VALUES('FR216','1','Gloire à notre Dieu, le Père,<br/>Gloire à Christ, le Fils,<br/>Saint-Esprit, à Toi la gloire –<br/>Seul Dieu vivant !<br/>',NULL,86497,1);
INSERT INTO stanza VALUES('FR216','2','L’œuvre de Tes mains est vaste ;<br/>Nous la contemplons ;<br/>En nous jaillit la louange :<br/>Nous T’adorons !<br/>',NULL,86498,2);
INSERT INTO stanza VALUES('FR216','3','Mais, cher Père, Tu désires<br/>Que de nombreux fils,<br/>Dans le Fils, Te louent ensemble<br/>Prouvant l’amour !<br/>',NULL,86499,3);
INSERT INTO stanza VALUES('FR216','4','Tu as révélé aux hommes<br/>Ta sainte pensée,<br/>Les secrets de Ta tendresse,<br/>De Ton amour.<br/>',NULL,86500,4);
INSERT INTO stanza VALUES('FR216','5','Par la rédemption en Christ – Oui :<br/>Le mal est vaincu –<br/>Tu as engendré de nombreux<br/>Adorateurs !<br/>',NULL,86501,5);
INSERT INTO stanza VALUES('FR216','6','Gloire à notre Dieu, le Père,<br/>Gloire à Christ, le Fils,<br/>Saint-Esprit, à Toi la gloire –<br/>Seul Dieu Vivant !<br/>',NULL,86502,6);
INSERT INTO stanza VALUES('FR217','1','Ô Père ! tel un grand cyprès,<br/>Tu es toujours nouveau ;<br/>Tu es frais comme la rosée,<br/>Toujours et à jamais !<br/>',NULL,86503,1);
INSERT INTO stanza VALUES('FR217','chorus','Ô Père ! étant immuable,<br/>Tu ne vieillis jamais !<br/>Ta nouveauté se déploiera<br/>Jusqu’en éternité !<br/>',NULL,86504,2);
INSERT INTO stanza VALUES('FR217','2','Oh ! Tu es Dieu ! Tu es nouveau !<br/>Hors de Toi tout vieillit,<br/>Avec Toi tout se rafraîchit<br/>Malgré les ans qui fuient !<br/>',NULL,86505,3);
INSERT INTO stanza VALUES('FR217','3','Toute bénédiction reçue<br/>Revêt Ta nouveauté ;<br/>Ainsi, Ton alliance et tes voies,<br/>Sont nouvelles à jamais !<br/>',NULL,86506,4);
INSERT INTO stanza VALUES('FR217','4','Un cœur et un esprit nouveaux –<br/>Nouvelle création –<br/>Se renouvellent en nous toujours<br/>Par Ta dispensation !<br/>',NULL,86507,5);
INSERT INTO stanza VALUES('FR217','5','Les cieux, la terre, en nouveauté,<br/>Et Ta sainte cité,<br/>Des fruits nouveaux à satiété,<br/>Ne faneront jamais !<br/>',NULL,86508,6);
INSERT INTO stanza VALUES('FR217','6','Ô Père ! en Toi, tout est nouveau !<br/>Tu es toujours si frais !<br/>Nous Te louons en nouveauté,<br/>Chantant l’hymne éternel !<br/>',NULL,86509,7);
INSERT INTO stanza VALUES('FR218','1','Grande est Ta fidélité, Dieu mon Père ;<br/>Aucune instabilité n’est en Toi !<br/>Tes compassions ne s’épuiseront jamais ;<br/>Tu es constant, ce jour et pour toujours.<br/>',NULL,86510,1);
INSERT INTO stanza VALUES('FR218','chorus','Quelle fidélité ! Grande fidélité !<br/>Je vois Tes compassions chaque matin.<br/>Ta main a toujours comblé tous mes besoins,<br/>Grande est Ta fidélité envers moi !<br/>',NULL,86511,2);
INSERT INTO stanza VALUES('FR218','2','L’été, l’hiver, le printemps et la moisson,<br/>Le soleil, les astres dans leurs sillons<br/>Avec la nature entière témoignent<br/>De Ta fidélité, de Ton amour.<br/>',NULL,86512,3);
INSERT INTO stanza VALUES('FR218','3','Le pardon des péchés, paix qui perdure,<br/>Ta face qui me réjouit, me soutient,<br/>La force d’aujourd’hui, l’espoir de demain,<br/>Ces faveurs et bien plus, tout m’appartient !<br/>',NULL,86513,4);
INSERT INTO stanza VALUES('FR219','1','Père, avant que soit le monde,<br/>Tu nous choisis dans l’amour ;<br/>Cet amour profond et tendre,<br/>Nous attire à Christ, en haut,<br/>Et nous garde, et nous garde,<br/>Ancrés fermement en Lui,<br/>Ancrés fermement en Lui.<br/>',NULL,86514,1);
INSERT INTO stanza VALUES('FR219','2','Le monde évolue sans cesse,<br/>Mais Dieu ne change jamais ;<br/>Ses compassions, Son alliance<br/>Pour toujours subsisteront !<br/>Tous Ses enfants, tous Ses enfants,<br/>Se plaisent à louer Son nom,<br/>Se plaisent à louer Son nom.<br/>',NULL,86515,2);
INSERT INTO stanza VALUES('FR219','3','Sa merci est mon histoire<br/>Et ma gloire à tout instant ;<br/>C’est par Sa miséricorde<br/>Que Sa voix conduit mes pas.<br/>Dieu nous aime, Dieu nous aime<br/>Tant, que Son Fils Il livra,<br/>Tant, que Son Fils Il livra.<br/>',NULL,86516,3);
INSERT INTO stanza VALUES('FR219','4','Dieu d’amour, dans Ta présence<br/>Nous chanterons Ton amour ;<br/>En Ton Fils, Te célébrerons,<br/>Jusqu’à Son avènement :<br/>Que la gloire, que la gloire<br/>Soit à Dieu et à l’Agneau,<br/>Soit à Dieu et à l’Agneau.<br/>',NULL,86517,4);
INSERT INTO stanza VALUES('FR220','1','Abba Père à Toi nous venons<br/>Dans le doux nom du Sauveur.<br/>Nous – Tes enfants – nous rassemblons,<br/>Ta promesse réclamant ;<br/>Son sang effaça nos fautes !<br/>Grâce à Lui, nous approchant,<br/>Dans nos cœurs et par Ton Esprit<br/>« Abba Père » nous crions !<br/>',NULL,86518,1);
INSERT INTO stanza VALUES('FR220','2','Nous étions des fils prodigues,<br/>Égarés, dans le besoin,<br/>Mais Ta grâce, qui abonde,<br/>Sur le péché triompha ;<br/>Tu nous revêtis du salut,<br/>À Ta table nous siégeons,<br/>Nous nous réjouissons ensemble,<br/>À Tes richesses goûtons.<br/>',NULL,86519,2);
INSERT INTO stanza VALUES('FR220','3','Tu pardonnas les prodigues,<br/>Pour nous prendre dans Ton sein.<br/>Tu tuas le veau gras pour nous,<br/>Nous sommes aptes à Ton dessein.<br/>Tu déclares : « Réjouissons-nous,<br/>Maintenant c’est accompli !<br/>J’ai retrouvé Mes fils perdus ;<br/>Ils sont à présent en vie. »<br/>',NULL,86520,3);
INSERT INTO stanza VALUES('FR220','4','Abba Père nous T’adorons ;<br/>Même l’armée dans les cieux,<br/>Discerne en nous les merveilles<br/>De Ta grâce et compassion.<br/>Réunis devant Ton trône,<br/>Tes enfants proclameront<br/>L’amour dont Tu as fait preuve,<br/>Les richesses de Ton nom !<br/>',NULL,86521,4);
INSERT INTO stanza VALUES('FR221','1','Nous Te bénissons Père !<br/>La joie en nous jaillit,<br/>Ici dans Ta présence<br/>Amenés par Ton Fils ;<br/>Il vit en tant qu’un homme<br/>En lumière bénie,<br/>Dans Ta gloire divine,<br/>Ton amour infini.<br/>',NULL,86522,1);
INSERT INTO stanza VALUES('FR221','2','Son Père et notre Père,<br/>Tu es le Dieu d’amour,<br/>Et Lui, Ton Fils bien-aimé,<br/>Le bonheur de Ton cœur ;<br/>Joyeux, Il nous amène<br/>Dans le lieu préparé<br/>De Ton amour, Ta face,<br/>Que Lui seul occupait.<br/>',NULL,86523,2);
INSERT INTO stanza VALUES('FR221','3','L’amour que Tu nous portes<br/>Ne peut jamais ternir ;<br/>C’est Ton Fils que Tu aimes,<br/>Nous sommes aimés en Lui.<br/>Ton amour et Ta gloire<br/>Sont pour toujours à Lui,<br/>Et nous – Ses nombreux frères –<br/>En Lui, proches et bénis !<br/>',NULL,86524,3);
INSERT INTO stanza VALUES('FR222','1','Dieu et Père, source de la vie,<br/>Nous, Tes fils, Te manifestons,<br/>Dans Ton nom, que nous possédons.<br/>Dieu, Tu es la source de la vie.<br/>Dans Ta vie, dans Ta vie<br/>Dans Ta vie est l’unité.<br/>Dans Ta vie, dans Ta vie,<br/>Dans Ta Vie nous avons l’unité.<br/>',NULL,86525,1);
INSERT INTO stanza VALUES('FR222','2','Père, Ta Parole Tu donnas,<br/>Par elle Tu nous saturés,<br/>Par elle nous sanctifies ;<br/>Ta Parole nous transmet Ta vie !<br/>Ta Parole, Ta Parole,<br/>Elle nous transmet l’unité.<br/>Ta Parole, Ta Parole,<br/>Ta Parole transmet l’unité.<br/>',NULL,86526,2);
INSERT INTO stanza VALUES('FR222','3','Oh ! la gloire de la Trinité !<br/>Tu nous bénis, Tes nombreux fils ;<br/>Nous Te manifestons ici :<br/>Oh ! la gloire de la Trinité !<br/>Dans Ta gloire, dans Ta gloire,<br/>Dans Ta gloire est l’unité.<br/>Dans Ta gloire, dans Ta gloire,<br/>Oh ! dans Ta gloire est notre unité !<br/>',NULL,86527,3);
INSERT INTO stanza VALUES('FR223','1','C’est un nom qui me réjouit,<br/>Je chante sa valeur ;<br/>C’est comme la musique à l’ouïe,<br/>Ce nom fait mon bonheur.<br/>',NULL,86528,1);
INSERT INTO stanza VALUES('FR223','chorus','Oh ! que j’aime Jésus !<br/>Oh ! que j’aime Jésus !<br/>Oh ! que j’aime Jésus !<br/>Lui qui m’aima d’abord !<br/>',NULL,86529,2);
INSERT INTO stanza VALUES('FR223','2','Il conte l’amour d’un Sauveur,<br/>Venu me libérer ;<br/>Il conte le gain des pécheurs<br/>Grâce à Son sang versé.<br/>',NULL,86530,3);
INSERT INTO stanza VALUES('FR223','3','Il conte ce qu’a préparé<br/>Le Père dans l’amour ;<br/>Et dans des lieux enténébrés<br/>Il guide mon parcours.<br/>',NULL,86531,4);
INSERT INTO stanza VALUES('FR223','4','Il parle d’un cœur qui ressent<br/>Mon plus profond chagrin,<br/>Il me console tendrement,<br/>D’un secours opportun.<br/>',NULL,86532,5);
INSERT INTO stanza VALUES('FR224','1','Nous aimons le nom glorieux,<br/>Le nom de Jésus.<br/>Ce nom est bien au-dessus de tous les noms !<br/>Si nous respirons ce nom,<br/>Les ténèbres fuiront,<br/>Nous serons dans la présence du Seigneur.<br/>',NULL,86533,1);
INSERT INTO stanza VALUES('FR224','2','Notre langue, cher Seigneur,<br/>Confesse avec joie Ton nom,<br/>Pour donner la gloire au Père dans les cieux.<br/>En louant ainsi Ton nom,<br/>De Toi nous nous réjouissons.<br/>Ô JÉSUS ! nous T’invoquons car nous T’aimons !<br/>',NULL,86534,2);
INSERT INTO stanza VALUES('FR225','1','Je veux toujours Te respirer<br/>Oh douce brise d’amour.<br/>Ta fragrance est, mon Bien-aimé,<br/>Comme une grappe de henné<br/>//Un baume pour mon cœur.//<br/>',NULL,86535,1);
INSERT INTO stanza VALUES('FR225','2','Je veux toujours Te contempler,<br/>Toi le plus merveilleux.<br/>Mon cœur soupire auprès du Roi<br/>Je pose mes regards sur Toi<br/>//Tu es le plus précieux.//<br/>',NULL,86536,2);
INSERT INTO stanza VALUES('FR225','3','Je veux toujours me rendre à Toi,<br/>Mon maître, mon Sauveur,<br/>Et refuser ma liberté<br/>Pour Te servir sans m’éloigner<br/>//De Toi mon cher Seigneur.//<br/>',NULL,86537,3);
INSERT INTO stanza VALUES('FR225','4','Je veux toujours chanter Ton nom,<br/>Il me remplit de joie.<br/>Une si douce mélodie<br/>Jaillit de mon cœur attendri.<br/>//Mon âme en Toi se noie.//<br/>',NULL,86538,4);
INSERT INTO stanza VALUES('FR225','5','Je veux toujours parler de Toi ;<br/>Ma langue T’appartient.<br/>J’entends si tendrement Ton cœur<br/>Quand Tu m’attires avec douceur<br/>//Murmurant : « Tout va bien ».//<br/>',NULL,86539,5);
INSERT INTO stanza VALUES('FR226','1','Dans le sein de Dieu le Père,<br/>Bien avant la création,<br/>Tu étais le Fils unique,<br/>Dans Sa gloire te trouvais ;<br/>Nous T’avons reçu du Père,<br/>Comme un homme Tu vécus ;<br/>Possédant Sa plénitude<br/>En Esprit Tu es venu.<br/>',NULL,86540,1);
INSERT INTO stanza VALUES('FR226','2','Par Ta mort tout-inclusive<br/>Et par Ta résurrection,<br/>Tu produis Tes nombreux frères<br/>Qui sont Ta duplication :<br/>Devenus les fils du Père<br/>Par la régénération,<br/>Nous brillons à Ton image<br/>Ô Fils premier-né de Dieu !<br/>',NULL,86541,2);
INSERT INTO stanza VALUES('FR226','3','Jadis Tu étais un seul grain,<br/>Mais en terre Tu tombas :<br/>Par Ta mort, en résurrection,<br/>En vie, te multiplias.<br/>Ta nature ainsi transmise<br/>Fit de nous de nombreux grains<br/>Exprimant Ta plénitude,<br/>Tous formés en un seul pain !<br/>',NULL,86542,3);
INSERT INTO stanza VALUES('FR226','4','Nous voici, Ta plénitude,<br/>Ton seul Corps et Ta mariée,<br/>Ta reproduction parfaite,<br/>En nous Tu peux demeurer ;<br/>Ta continuation nous sommes,<br/>De Ta vie l’accroissement,<br/>Tous unis à Toi, la Tête,<br/>C’est Toi que nous exprimons.<br/>',NULL,86543,4);
INSERT INTO stanza VALUES('FR227','1','Rassemblés en Ton nom, Jésus,<br/>Ne voyant plus rien que Toi,<br/>Ta présence est douce à nos cœurs,<br/>Et les mène à Toi Seigneur !<br/>',NULL,86544,1);
INSERT INTO stanza VALUES('FR227','2','Aimés d’un amour infini,<br/>L’amour du Père envers Toi,<br/>Seigneur, nos cœurs affectionnent<br/>Toutes Ses pensées pour Toi.<br/>',NULL,86545,2);
INSERT INTO stanza VALUES('FR227','3','Son repos, Sa joie, Son plaisir,<br/>Ses délices sont en Toi.<br/>Seigneur, seul Ton cœur peut saisir<br/>Le bonheur du Père en Toi.<br/>',NULL,86546,3);
INSERT INTO stanza VALUES('FR227','4','Il versa Son amour sur Toi,<br/>T’appela Son Bien-aimé ;<br/>Pour nous, Il ne T’épargna pas,<br/>Par Ta mort Il nous gagna.<br/>',NULL,86547,4);
INSERT INTO stanza VALUES('FR227','5','Nous Te verrons face à face,<br/>Nous serons semblables à Toi ;<br/>Ton nom toujours apportera<br/>L’allégresse au cœur de Dieu.<br/>',NULL,86548,5);
INSERT INTO stanza VALUES('FR227','6','Chants de joie et d’allégresse,<br/>Au milieu de l’assemblée<br/>Monteront, se multiplieront :<br/>Gloire à Dieu pour l’éternité !<br/>',NULL,86549,6);
INSERT INTO stanza VALUES('FR228','1','À Ta table, dans l’amour,<br/>Tu bénis le pain, le vin ;<br/>Ces symboles nous prenons,<br/>Et de Toi nous nourrissons.<br/>Nous Te remercions Seigneur<br/>Pour la coupe du salut,<br/>Coupe de bénédiction,<br/>Ta divine provision.<br/>',NULL,86550,1);
INSERT INTO stanza VALUES('FR228','2','C’est Ton sang précieux, versé<br/>Pour le pardon des péchés,<br/>C’est l’alliance promulguée :<br/>Tes bienfaits nous sont légués.<br/>La colère Tu enduras<br/>En goûtant la mort pour nous ;<br/>Tes grandes bénédictions<br/>Sont ainsi notre portion.<br/>',NULL,86551,2);
INSERT INTO stanza VALUES('FR228','3','La portion reçue est Dieu,<br/>Éloignée à cause d’Adam ;<br/>Par Ton sang versé pour nous,<br/>Dieu est notre tout en tous.<br/>En Lui nous avons trouvé<br/>Vie et paix, la rédemption,<br/>Tout ce que Dieu planifia,<br/>Nous l’avons pour possession.<br/>',NULL,86552,3);
INSERT INTO stanza VALUES('FR228','4','C’est un partage éternel,<br/>Débordant, illimité,<br/>Oh ! quel avant-goût divin !<br/>Dans la coupe, Son dessein,<br/>Dans l’amour nous la buvons<br/>Et nous souvenons de Toi !<br/>En esprit nous jouissons<br/>De Ton œuvre sur la croix.<br/>',NULL,86553,4);
INSERT INTO stanza VALUES('FR229','1','Oh ! quel miracle ! Mon Seigneur,<br/>Que l’homme et Dieu sont vraiment un ;<br/>Je suis en Toi, Tu es en moi :<br/>Ce grand mystère est révélé !<br/>',NULL,86554,1);
INSERT INTO stanza VALUES('FR229','2','Grâce à Ton corps livré pour moi,<br/>Je prends part à Toi maintenant ;<br/>Seigneur, Ton sang précieux coula,<br/>De mes péchés me libéra.<br/>',NULL,86555,2);
INSERT INTO stanza VALUES('FR229','3','En résurrection Tu changeas<br/>De forme, devenant l’Esprit ;<br/>De Tes richesses rassasié,<br/>De Toi je serai saturé.<br/>',NULL,86556,3);
INSERT INTO stanza VALUES('FR229','4','Quand ces symboles nous voyons<br/>Nous discernons Ton grand amour,<br/>Te rendons grâces pour Ton plan<br/>Et Tes souffrances contemplons.<br/>',NULL,86557,4);
INSERT INTO stanza VALUES('FR229','5','Nous prenons part au pain, au vin,<br/>Vers Ta douceur Tu nous conduits.<br/>En esprit nous Te recevons,<br/>Nos esprits sont de Toi nourris.<br/>',NULL,86558,5);
INSERT INTO stanza VALUES('FR229','6','Boire et manger plus en esprit<br/>Est notre plus ardent désir,<br/>Qu’en saturant notre être entier,<br/>Tu obtiennes un vrai souvenir.<br/>',NULL,86559,6);
INSERT INTO stanza VALUES('FR230','1','Présents au repas du Seigneur, nous rassemblant,<br/>Mangeant et buvant, l’unité nous montrons ;<br/>Ayant Sa présence, unis devant Sa face,<br/>Nous prenons part à Lui, à Sa bénédiction.<br/>',NULL,86560,1);
INSERT INTO stanza VALUES('FR230','2','Nous mangeons le pain de Son corps brisé pour nous<br/>En nous réjouissant de Son Corps, qu’Il fit un :<br/>Un pain sur la table – Nous sommes tous capables,<br/>De témoigner que le Seigneur nous a unis.<br/>',NULL,86561,2);
INSERT INTO stanza VALUES('FR230','3','La bénédiction de la coupe nous buvons,<br/>C’est la communion de Son sang si précieux.<br/>Sauvés par Ta grâce, l’amour nous entrelace :<br/>Tous ceux qui, par la rédemption, viennent vers Dieu.<br/>',NULL,86562,3);
INSERT INTO stanza VALUES('FR230','4','Que pouvons-nous déclarer sauf : « Alléluia ! »<br/>Pour la réalité que Tu nous accordas ?<br/>Par Ton sang précieux, en nous réjouissant<br/>de Ton Corps,<br/>Nous deviendrons l’église qui T’est destinée.<br/>',NULL,86563,4);
INSERT INTO stanza VALUES('FR231','1','Voici la vision divine –<br/>De la vie c’est le secret :<br/>Dieu nous a mis en Jésus-Christ ;<br/>Nous demeurons, demeurons dans le cep !<br/>',NULL,86564,1);
INSERT INTO stanza VALUES('FR231','chorus','Demeurant dans le cep,<br/>Demeurant dans le cep,<br/>Ses richesses en nous sont dispensées !<br/>Dieu nous a mis en Lui,<br/>Oh quel endroit béni !<br/>Demeurons, demeurons dans le cep !<br/>',NULL,86565,2);
INSERT INTO stanza VALUES('FR231','2','Désormais nous ne luttons plus ;<br/>Sa voie, nous l’avons trouvée !<br/>Dieu nous a déjà mis en Christ,<br/>Alléluia ! nous sommes dans le cep !<br/>',NULL,86566,3);
INSERT INTO stanza VALUES('FR231','3','L’huile d’onction nous sature,<br/>C’est un courant perpétuel ;<br/>Dieu nous transmet Son essence<br/>Alors que nous demeurons dans le cep.<br/>',NULL,86567,4);
INSERT INTO stanza VALUES('FR231','4','Nous marchons dans la lumière<br/>Que Son courant nous transmet ;<br/>Nous sommes aussi Sa demeure,<br/>Depuis que nous demeurons dans le cep.<br/>',NULL,86568,5);
INSERT INTO stanza VALUES('FR232','1','Le Seigneur Lui-même est mon Berger,<br/>Toujours Il me fait reposer,<br/>Me conduit vers des eaux paisibles,<br/>Oh ! combien Il me satisfait !<br/>',NULL,86569,1);
INSERT INTO stanza VALUES('FR232','chorus','Oui, le bonheur et la grâce m’accompagneront<br/>Tous les jours, tous les jours de ma vie ;<br/>Oui, le bonheur et la grâce m’accompagneront<br/>Tous les jours, tous les jours de ma vie !<br/>J’habiterai à jamais dans la maison de Dieu,<br/>Mangerai à Sa table préparée ;<br/>Oui, le bonheur et la grâce m’accompagneront<br/>Tous les jours, tous les jours de ma vie.<br/>',NULL,86570,2);
INSERT INTO stanza VALUES('FR232','2','Il est aussi mon pâturage,<br/>Lui-même, les eaux paisibles ;<br/>Dans mon esprit je bois, je mange :<br/>Oh ! Ses richesses m’ont béni !<br/>',NULL,86571,3);
INSERT INTO stanza VALUES('FR232','3','Mon Berger restaure mon âme,<br/>Veille sur mon être intérieur ;<br/>Et même en marchant dans la vallée,<br/>Oh ! quel Compagnon j’ai trouvé.<br/>',NULL,86572,4);
INSERT INTO stanza VALUES('FR232','4','Mon Dieu m’a dressé une table ;<br/>Je mange et vaincs Son ennemi !<br/>De l’huile Il répand sur ma tête,<br/>Ma coupe déborde de joie.<br/>',NULL,86573,5);
INSERT INTO stanza VALUES('FR232','5','C’est dans Sa maison que j’habite,<br/>Me réjouissant de Sa bonté ;<br/>Mon bonheur est au-delà des mots,<br/>Ma joie, c’est Jésus, mon Seigneur !<br/>',NULL,86574,6);
INSERT INTO stanza VALUES('FR233','1','Mon vieil homme avec Lui est crucifié,<br/>Avec sa corruption et ses péchés,<br/>Et sa nature est déjà enterrée !<br/>C’est accompli ! À ce fait merveilleux<br/>Je m’attach’rai !<br/>',NULL,86575,1);
INSERT INTO stanza VALUES('FR233','2','Il y a vraiment Quelqu’un dans mon esprit,<br/>En moi, d’abord comme un enfant, Il vit ;<br/>Jusqu’à devenir en moi un Vainqueur<br/>Par la Parole Il va toujours grandir,<br/>Oui ! dans mon cœur !<br/>',NULL,86576,2);
INSERT INTO stanza VALUES('FR233','3','Pour devenir en moi prééminent,<br/>Christ doit gagner mon cœur entièrement.<br/>Seigneur ! remplace l’ancien résident !<br/>Il a déjà été anéanti ;<br/>Nous T’accueillons !<br/>',NULL,86577,3);
INSERT INTO stanza VALUES('FR233','4','En Toi, Seigneur, en parfaite unité,<br/>Notre esprit et le Tien sont mélangés ;<br/>Mais Tu vas conserver nos facultés,<br/>Que Ta Personne merveilleuse en nous<br/>Soit exprimée !<br/>',NULL,86578,4);
INSERT INTO stanza VALUES('FR233','5','Alors, ici, je T’offre tout mon cœur ;<br/>Fais de lui Ta demeure, cher Seigneur !<br/>Un endroit où Tu puisses t’installer !<br/>Que l’œuvre du seul nouvel homme soit<br/>Parachevé !<br/>',NULL,86579,5);
INSERT INTO stanza VALUES('FR234','1','Mon Dieu, mon tout et mon amour,<br/>Ma portion pour toujours,<br/>Je n’ai personne que Toi seul<br/>Sur terre et dans les cieux.<br/>',NULL,86580,1);
INSERT INTO stanza VALUES('FR234','2','Que valent l’horizon, la terre ?<br/>Poussière et vanité !<br/>Rien ne mérite ici mes joies,<br/>Rien n’est semblable à Toi.<br/>',NULL,86581,2);
INSERT INTO stanza VALUES('FR234','3','Je Te dois tout : biens et amis,<br/>Ma santé, mon abri.<br/>Mais ces bénédictions ne peuvent<br/>Jamais Te remplacer.<br/>',NULL,86582,3);
INSERT INTO stanza VALUES('FR234','4','Quel vains plaisirs l’or, les palais,<br/>Quand à Toi comparés !<br/>Que valent ma sécurité,<br/>Ma vie ou mes amis ?<br/>',NULL,86583,4);
INSERT INTO stanza VALUES('FR234','5','Si mienne était toute la terre<br/>Et sa voûte étoilée,<br/>Je serais misérable et las,<br/>Sans Ta grâce et sans Toi.<br/>',NULL,86584,5);
INSERT INTO stanza VALUES('FR234','6','Je laisse à d’autres les efforts<br/>D’atteindre leurs trésors,<br/>Car les visites de Ta grâce,<br/>Sont bien mon plus grand gain.<br/>',NULL,86585,6);
INSERT INTO stanza VALUES('FR235','chorus','Dieu est lumière et les ténèbres fuient devant Lui !<br/>Dans Sa présence nous voulons demeurer,<br/>Recevant Sa lumière, à chaque instant purifiés<br/>De tout péché !<br/>',NULL,86586,1);
INSERT INTO stanza VALUES('FR235','1','(Sœurs) Marchons dans<br/>(Frères) Sa lumière !<br/>(Sœurs) Communions<br/>(Frères) Dans Sa grâce !<br/>(Sœurs) Oui, le sang<br/>(Frères) De Jésus<br/>(Tout le monde) Lave tous nos péchés.<br/><br/>(Sœurs) Confessons !<br/>(Frères) Il est juste,<br/>(Sœurs) Oui, toujours,<br/>(Frères) Nous pardonne,<br/>(Sœurs) Quelle joie,<br/>(Frères) Nos péchés<br/>(Tout le monde) Sont purifiés !<br/>',NULL,86587,2);
INSERT INTO stanza VALUES('FR236','1','Laisse passer du temps<br/>En Le contemplant ;<br/>Parle avec le Seigneur,<br/>En Lui demeurant ;<br/>Sa Parole mangeant<br/>Avec soumission,<br/>Recherche sans cesse<br/>Sa bénédiction.<br/>',NULL,86588,1);
INSERT INTO stanza VALUES('FR236','2','Laisse passer du temps<br/>En Le contemplant ;<br/>Le monde se hâte,<br/>Toi seul, tu L’attends.<br/>Devant Lui en secret<br/>Sa gloire admirant,<br/>Sa vie, Son image,<br/>De toi brilleront.<br/>',NULL,86589,2);
INSERT INTO stanza VALUES('FR236','3','Laisse passer du temps<br/>En Le contemplant.<br/>Et qu’Il te conduise,<br/>Lui, toujours avant ;<br/>En joie ou en douleurs,<br/>Suivant le Seigneur,<br/>Tiens à Sa Parole,<br/>En Lui te confiant.<br/>',NULL,86590,3);
INSERT INTO stanza VALUES('FR236','4','Laisse passer du temps<br/>En Le contemplant ;<br/>Que toute ton âme,<br/>Se repose en Lui ;<br/>À la source d’amour<br/>Conduit par l’Esprit,<br/>Sa miséricorde<br/>Sera ton appui.<br/>',NULL,86591,4);
INSERT INTO stanza VALUES('FR237','1','Poursuis, poursuis le but de Dieu :<br/>Le Christ tout-inclusif.<br/>Pour le prix de l’appel de Dieu,<br/>Poursuis, poursuis ce Christ !<br/>',NULL,86592,1);
INSERT INTO stanza VALUES('FR237','chorus','Poursuivons ! Poursuivons !<br/>Poursuivons ! Alléluia pour le prix !<br/>Nous poursuivons ! Avançons !<br/>Le Christ de Dieu gagnons !<br/>',NULL,86593,2);
INSERT INTO stanza VALUES('FR237','2','Poursuis le but et tiens pour perte<br/>Tout ce qui t’est un gain ;<br/>Gagner le prix, le Christ de Dieu,<br/>C’est beaucoup plus glorieux !<br/>',NULL,86594,3);
INSERT INTO stanza VALUES('FR237','3','Poursuis, connais le Christ glorieux,<br/>Et Sa résurrection !<br/>Sa mort soit rendu conforme,<br/>Par Sa grande puissance !<br/>',NULL,86595,4);
INSERT INTO stanza VALUES('FR237','4','Poursuis, poursuis et fais ceci :<br/>Oubliant le passé,<br/>Poursuis le Christ, qui est devant !<br/>Gardons cette pensée !<br/>',NULL,86596,5);
INSERT INTO stanza VALUES('FR238','1','Nous devons courir la course – Alléluia !<br/>Nous avons le moyen de gagner ;<br/>À ceux qui ont commencé – Alléluia !<br/>Dieu dit : Fixez les regards sur Lui !<br/>',NULL,86597,1);
INSERT INTO stanza VALUES('FR238','chorus','Détournons, oui, détournons,<br/>Notre regard vers Jésus !<br/>Détournons nos yeux de toute autre chose,<br/>En fixant les regards sur Jésus !<br/>',NULL,86598,2);
INSERT INTO stanza VALUES('FR238','2','Tourne le regard vers Lui – Alléluia !<br/>Face aux luttes, face aux distractions,<br/>Et la paix tu trouveras – Alléluia !<br/>En fixant les regards sur Jésus.<br/>',NULL,86599,3);
INSERT INTO stanza VALUES('FR238','3','Ne regarde pas ton âme – Alléluia !<br/>Ni le moi avec tous ses échecs ;<br/>Tourne les yeux vers le but – Alléluia !<br/>Détournant le regard vers Jésus.<br/>',NULL,86600,4);
INSERT INTO stanza VALUES('FR238','4','Tourne le dos au passé – Alléluia !<br/>Oublie-le qu’il soit bon ou mauvais ;<br/>Au Vivant attache-toi – Alléluia !<br/>Détournant le regard vers Jésus.<br/>',NULL,86601,5);
INSERT INTO stanza VALUES('FR238','5','Oh ! Regarde Son visage – Alléluia !<br/>Il finit ce qu’Il a commencé !<br/>Quelle grâce nous avons – Alléluia !<br/>Pour la course, en contemplant Jésus !<br/>',NULL,86602,6);
INSERT INTO stanza VALUES('FR239','1','Libéré d’Adam et du moi,<br/>Je serais bâti par Toi<br/>Avec Tes saints en un temple,<br/>Où Ta gloire brillera.<br/>Traite mon indépendance<br/>Et mes traits particuliers,<br/>Pour que Ta demeure sainte<br/>En nous soit parachevée !<br/>',NULL,86603,1);
INSERT INTO stanza VALUES('FR239','2','Transformé par la croissance<br/>De Ta vie qui coule en moi,<br/>Édifié avec Tes membres,<br/>Je suis tempéré par Toi<br/>Dans le Corps, respectant l’ordre,<br/>Fonctionnant avec Tes saints:<br/>Chacun prenant soin des autres<br/>Pour accomplir Ton dessein.<br/>',NULL,86604,2);
INSERT INTO stanza VALUES('FR239','3','Garde-moi, dans l’expérience,<br/>D’agir avec présomption;<br/>Que plutôt Tu me limites<br/>Par Ton corps, en soumission.<br/>Attaché donc à la Tête,<br/>Toujours dans la communion,<br/>Je reçois de chaque membre<br/>Ton approvisionnement !<br/>',NULL,86605,3);
INSERT INTO stanza VALUES('FR239','4','Par l’Esprit, avec puissance<br/>Toujours, dans l’homme intérieur,<br/>Fortifie-moi pour connaître<br/>Ton amour, Tes dimensions !<br/>Prenant part à Tes richesses,<br/>Jusqu’à la maturité,<br/>Rempli de Ta plénitude<br/>Ton Corps sera édifié.<br/>',NULL,86606,4);
INSERT INTO stanza VALUES('FR239','5','Dans Ton Corps, dans Ta demeure,<br/>Bâtis-moi, ô cher Seigneur !<br/>Fais de nous tous un seul vase<br/>Qui proclame Ta grandeur;<br/>Comme un chandelier qui brille,<br/>Sur la Terre apparaîtra<br/>Ta marié, Ta ville sainte,<br/>Qui Ta gloire exprimera.<br/>',NULL,86607,5);
INSERT INTO stanza VALUES('FR240','1','Nous étions tous morts dans le péché,<br/>Dans un monde plein de désunion ;<br/>Avec Christ Dieu nous ressuscita<br/>Et dans les cieux nous fit asseoir avec Lui !<br/>',NULL,86608,1);
INSERT INTO stanza VALUES('FR240','chorus','C’est Jésus-Christ qui nous rassemble !<br/>Viens et vois les saints dans l’unité !<br/>L’amour de Christ nous tisse ensemble,<br/>De Sa plénitude ensemble nous remplit !<br/>',NULL,86609,2);
INSERT INTO stanza VALUES('FR240','2','Avec tous les saints nous saisissons<br/>Les immenses dimensions de Christ.<br/>Son amour surpasse nos pensées ;<br/>Nous Le connaissons et débordons de Lui.<br/>',NULL,86610,3);
INSERT INTO stanza VALUES('FR240','3','Maintenant, nous connaissons Son plan –<br/>Le mystère est déjà révélé :<br/>Christ, l’église, pour toujours unis,<br/>Qui ensemble couvrent de honte l’ennemi.<br/>',NULL,86611,4);
INSERT INTO stanza VALUES('FR240','4','Nous prions le Père chaque jour :<br/>Fortifie-nous dans l’homme intérieur,<br/>Fa1s Ta demeure, ô Dieu, dans nos cœurs !<br/>Fonde-nous dans Ton amour, pour Ton dessein !<br/>',NULL,86612,5);
INSERT INTO stanza VALUES('FR240','5','Tous les membres sont bien ajustés,<br/>Dispensant chacun sa part de Christ ;<br/>Chaque membre exerce sa fonction,<br/>Dans l’amour le Corps grandit et s’édifie !<br/>',NULL,86613,6);
INSERT INTO stanza VALUES('FR240','6','Nous accomplirons le plan de Dieu<br/>Comme un nouvel homme universel !<br/>À Lui soit la gloire à tout jamais,<br/>Dans l’église, comme en Christ Jésus – Amen !<br/>',NULL,86614,7);
INSERT INTO stanza VALUES('FR241','1','Jésus revient bientôt, le jour approche !<br/>Saisis le temps ! Qu’il ne s’échappe pas !<br/>Prepare-nous Seigneur pour voir Ta face,<br/>En saisissant chaque instant, chaque jour.<br/><br/>Rejoindrons-nous le Seigneur à Son retour ?<br/>Et notre moi aura-t-il disparu ?<br/>Il vient bientôt prendre les sages avec Lui.<br/>Oh ! ne manquons pas ce festin béni !<br/>',NULL,86615,1);
INSERT INTO stanza VALUES('FR241','2','Aide-nous à saisir ces moments précieux !<br/>Remplis nos vases de l’huile exigée !<br/>Puissions-nous dire « Amen » à chaque épreuve !<br/>Grandis en nous et remplis-nous d’amour.<br/><br/>Il vient bientôt – chaque instant est si précieux ;<br/>L’huile est ici – achetons-en encore !<br/>Accueillons toute épreuve et tribulation,<br/>Par elles nous recevrons le royaume.<br/>',NULL,86616,2);
INSERT INTO stanza VALUES('FR241','3','Nous reviendrons, loin des plaisirs du monde,<br/>Pour contempler Ton visage si doux ;<br/>Fais-nous persévérer dans notre course !<br/>Nous courrons jusqu’à rencontrer l’Epoux !<br/><br/>À Son retour, verrons-nous Son visage ?<br/>À Son retour, serons-nous avec Lui ?<br/>Garde-nous de la paresse, la folie,<br/>Tenant à Ta présence par amour !<br/>',NULL,86617,3);
INSERT INTO stanza VALUES('FR241','4','Comme une Epouse, allons à Sa rencontre !<br/>Brûlants d’amour, nos lampes purifiées,<br/>Nos vases pleins, et contemplant Sa gloire,<br/>Dans Sa présence nous serons comblés !<br/><br/>Oui, satisfaits – Christ et l’Épouse ensemble.<br/>Oui, satisfaits – pour toute éternité.<br/>Oh, quel repos ! Quel amour ! Quelle grâce !<br/>Aux noces, nous serons Sa bien-aimée !<br/>',NULL,86618,4);
INSERT INTO stanza VALUES('FR242','1','Tel que je suis, je ne vois rien<br/>Que Ton sang versé à la croix,<br/>Puisque Tu m’invites au festin,<br/>Agneau de Dieu, je viens à Toi !<br/>',NULL,86619,1);
INSERT INTO stanza VALUES('FR242','2','Tel que je suis, je n’attends pas<br/>Pour faire laver les tâches en moi ;<br/>Ton sang tout mon être nettoie,<br/>Agneau de Dieu, je viens à Toi !<br/>',NULL,86620,2);
INSERT INTO stanza VALUES('FR242','3','Tel que je suis, dans l’affliction,<br/>Remplis de doutes et tentations,<br/>Dans la peur, la désolation,<br/>Agneau de Dieu, je viens à Toi !<br/>',NULL,86621,3);
INSERT INTO stanza VALUES('FR242','4','Tel que je suis, pauvre pécheur,<br/>Je T’ai trouvé, mon seul Sauveur ;<br/>Tu combles mes besoins Seigneur –<br/>Agneau de Dieu, je viens à Toi !<br/>',NULL,86622,4);
INSERT INTO stanza VALUES('FR242','5','Tel que je suis, Tu me reçois ;<br/>Toujours, Tu me pardonneras.<br/>Car en Ta promesse je crois,<br/>Agneau de Dieu je viens à Toi !<br/>',NULL,86623,5);
INSERT INTO stanza VALUES('FR242','6','Tel que je suis, Ton grand amour<br/>A gagné mon cœur pour toujours ;<br/>En lui Te donnant libre cours,<br/>Agneau de Dieu je viens à Toi !<br/>',NULL,86624,6);
INSERT INTO stanza VALUES('FR243','1','À quoi sert donc l’existence ?<br/>Recherchons tous la réponse :<br/>',NULL,86625,1);
INSERT INTO stanza VALUES('FR243','2','Invoquons : « Seigneur Jésus ! »<br/>Goûtons-Le ! Nous Le verrons,<br/>Christ devient la réalité,<br/>Nous marchons en nouveauté,<br/>Il coule en nous comme vie,<br/>Et la joie en nous jaillit,<br/>Son grand amour nous remplit –<br/>Tout cela, c’est grâce à Lui !<br/>',NULL,86626,2);
INSERT INTO stanza VALUES('FR244','1','Viens, goûte et vois : le Seigneur est bon !<br/>Viens, goûte et vois : le Seigneur est bon !<br/>Il est bon pour toi, comme Il l’est pour moi,<br/>Donc quoique tu fasses, viens, goûte et vois !<br/>',NULL,86627,1);
INSERT INTO stanza VALUES('FR244','2','Dis ô Seigneur ! Ta vie Il changera !<br/>Dis ô Seigneur ! Ta Vie Il changera !<br/>Sublime grâce, Il te donnera,<br/>Si en tout lieu, tu dis « Ô Seigneur ! »<br/>',NULL,86628,2);
INSERT INTO stanza VALUES('FR244','3','L’amour viendra, ton cœur s’éveillera,<br/>L’amour viendra, ton cœur s’éveillera,<br/>Un flot coulant du Dieu des cieux<br/>C’est Jésus–Christ, le vrai amour.<br/>',NULL,86629,3);
INSERT INTO stanza VALUES('FR244','4','Loue le Seigneur pour Sa vie en toi !<br/>Oui loue Jésus, pour Sa vie en toi !<br/>Christ déversa en toi Sa vie,<br/>De tout ton cœur, loue le Seigneur !<br/>',NULL,86630,4);
INSERT INTO stanza VALUES('FR245','1','Quel jour merveilleux !<br/>Lorsque j’ouvris enfin les yeux<br/>Jésus me sauva de l’obscurité,<br/>Dans Son royaume lumineux.<br/>',NULL,86631,1);
INSERT INTO stanza VALUES('FR245','2','Ma vie maintenant<br/>Est la vraie vie qui vient de Lui ;<br/>Plus jamais captivé par des vanités,<br/>Je goûte à ce courant de vie.<br/>',NULL,86632,2);
INSERT INTO stanza VALUES('FR245','3','Je m’attache à Lui<br/>Et Il me remplit de Sa vie ;<br/>Sa vie devient ma vie en réalité<br/>Oh ! Alléluia ! Je Le vis !<br/>',NULL,86633,3);
INSERT INTO stanza VALUES('FR245','4','Je T’aime, ô Seigneur !<br/>Tu as saisi, ravi mon cœur ;<br/>Tu seras ma vie pour l’éternité ;<br/>Tu es vraiment mon Bien–aimé.<br/>',NULL,86634,4);
INSERT INTO stanza VALUES('FR246','1','Que donnerai-je à mon Seigneur<br/>Pour tout, pour tout, tout ce qu’Il fit pour moi ?<br/>Je prendrai la coupe du salut,<br/>J’invoque, j’invoque,<br/>J’invoquerai le nom du Seigneur.<br/>',NULL,86635,1);
INSERT INTO stanza VALUES('FR247','1','Et avec joie vous puiserez l’eau<br/>Aux fontaines du salut,<br/>Et vous direz ce jour–là :<br/>Je Te loue !<br/>',NULL,86636,1);
INSERT INTO stanza VALUES('FR247','2','Et avec joie vous puiserez l’eau<br/>Aux fontaines du salut,<br/>Et vous direz ce jour-là :<br/>Je Te loue !<br/>',NULL,86637,2);
INSERT INTO stanza VALUES('FR247','3','Invoquez Son nom,<br/>Publiez Ses œuvres parmi les peuples,<br/>Rappelez-leur la grandeur de Son nom !<br/>Poussez des cris, vous, habitants de Sion !<br/>Oh, comme Il est grand en ton milieu, le très Saint D’Israël !<br/>',NULL,86638,3);
INSERT INTO stanza VALUES('FR248','1','Ainsi les rachetés du Seigneur retourneront,<br/>Avec des chants de triomphe à Sion ;<br/>Une joie éternelle couronnera leur tête.<br/>Ainsi les rachetés du Seigneur retourneront,<br/>Avec des chants de triomphe à Sion ;<br/>Une joie éternelle couronnera leur tête.<br/>',NULL,86639,1);
INSERT INTO stanza VALUES('FR248','2','Ils obtiendront, joie et allégresse ;<br/>Le chagrin, les gémissements s’enfuiront.<br/>',NULL,86640,2);
INSERT INTO stanza VALUES('FR248','3','Ainsi les rachetés du Seigneur retourneront,<br/>Avec des chants de triomphe à Sion ;<br/>Une joie éternelle couronnera leur tête.<br/>',NULL,86641,3);
INSERT INTO stanza VALUES('FR93','11','J''habite en Lui mon bon pays,<br/>En tout Il me suffit.<br/>Ma forteresse et mon rocher,<br/>Ma tour et mon abri.<br/>',NULL,86642,11);
INSERT INTO stanza VALUES('FR93','12','Nouvelle lune et vrai sabbat,<br/>Mon jour et mon matin ;<br/>Il est l''Alpha et l''Oméga,<br/>Il est, était et vient !<br/>',NULL,86643,12);
INSERT INTO stanza VALUES('FR93','13','Mon Christ m''attire, Il est si beau,<br/>Son charme m''a gagné.<br/>Il est ma joie, tout mon plaisir,<br/>En Lui, je suis comblé.<br/>',NULL,86644,13);
INSERT INTO stanza VALUES('FR93','14','Comment pourrais-je Te nommer ?<br/>Toi qui englobes tout,<br/>Toi le premier et le dernier,<br/>Toi qui grandis en nous.<br/>',NULL,86645,14);
INSERT INTO stanza VALUES('FR93','15','En possédant pareil trésor,<br/>Je goûte au vrai bonheur !<br/>Je veux chanter, toujours chanter :<br/>« Ce Christ est mon Seigneur ! »<br/>',NULL,86646,15);
INSERT INTO stanza VALUES('FR76','chorus','Le monde est très loin !<br/>Le monde est très loin !<br/>J''ai tout quitté, j''ai tout laissé !<br/>De moi, le monde est très loin !<br/>',NULL,86647,2);
INSERT INTO stanza VALUES('FR76','chorus','Le monde est très loin !<br/>Le monde est très loin !<br/>En Jésus-Christ je resterai,<br/>De moi, le monde est très loin !<br/>',NULL,86648,4);
INSERT INTO stanza VALUES('FR76','chorus','Le monde est très loin !<br/>Le monde est très loin !<br/>Et pour toujours je veux laisser<br/>De moi, le monde est très loin !<br/>',NULL,86649,6);
INSERT INTO stanza VALUES('FR76','chorus','Le monde est très loin !<br/>Le monde est très loin !<br/>L''abime de la mort franchi,<br/>De moi, le monde est très loin !<br/>',NULL,86650,8);
INSERT INTO stanza VALUES('FR87','beginning-note','(Répétez les deux derniers vers de chaque strophe.)<br/>',NULL,86651,1);
INSERT INTO stanza VALUES('FR114','beginning-note','(Répétez les trois derniers vers de chaque strophe.)<br/>',NULL,86652,1);
INSERT INTO stanza VALUES('FR143','chorus','Jésus, amen à Ta Parole !<br/>Jésus, amen à Ta Parole !<br/>Oui, Tu reviens bientôt et mon cœur dit : « Amen ! »<br/>Jésus, amen à Ta Parole !<br/>',NULL,86653,8);
INSERT INTO stanza VALUES('FR168','chorus','Sœurs :<br/>C''est la victoire, ô frères chrétiens !<br/>C''est la victoire ! Proclamons !<br/>À Sion crions : « C''est la victoire ! »<br/>Proclamons-la, crions de joie !<br/><br/>Frères :<br/>C''est la victoire, ô sœurs chrétiennes !<br/>La rédemption est accomplie !<br/>Par Son Triomphe, Il a vaincu pour nous.<br/>Nous sommes couronnés de joie !<br/>',NULL,86654,2);
INSERT INTO stanza VALUES('NS10002','1','Lord, I love You.<br/>Lord, I need You.<br/>Lord, without You<br/>Nothing would be the same.<br/>Without You knowing,<br/>Without You flowing,<br/>Without You growing,<br/>In me my life is vain.<br/><br/>Lord, I love You more and more;<br/>I just want You.<br/>Fill me with Your life and Your virtues.<br/>Fill me ’til I’m only living You.<br/>Fill me every minute, every hour, every day<br/>Until I am expressing You always.<br/>Fill this earthen vessel, Lord, I pray.<br/>',NULL,86659,1);
INSERT INTO stanza VALUES('NS10002','2','Lord, You’re moving,<br/>Operating<br/>In my being<br/>Saturate every part.<br/>You’re infusing,<br/>Permeating.<br/>You’re indwelling,<br/>Making home in my heart.<br/><br/>Lord, I love You more and more;<br/>I just want You.<br/>Fill me with Your life and Your virtues.<br/>Fill me ’til I’m only living You.<br/>Fill me every minute, every hour, every day<br/>Until I am expressing You always.<br/>Fill this earthen vessel, Lord, I pray.<br/>',NULL,86660,2);
INSERT INTO stanza VALUES('NS10002','3','Lord, You’re building<br/>Your expression;<br/>Lord, by mingling<br/>All that You are in me.<br/>I’m responding,<br/>Cooperating,<br/>Consecrating<br/>Myself to You totally.<br/><br/>Lord, for Your expression<br/>I would now outpour,<br/>Partaking of Your Person more and more,<br/>Partaking of Your Person more and more.<br/>Lord, for Your expression<br/>I would now outpour,<br/>This is what I was created for,<br/>This is what I was created for.<br/>',NULL,86661,3);
INSERT INTO stanza VALUES('NS10003','1','Lord, You’re irresistible,<br/>And, dear Lord, You’re wonderful!<br/>Lord, You have attracted me,<br/>Captured, Lord, by Your beauty.<br/>',NULL,86662,1);
INSERT INTO stanza VALUES('NS10003','chorus','No one, dear Lord, compares to You, my Love.<br/>There’s none on earth or in the heaven above.<br/>Yes, everything compared to You is vanity.<br/>Dear Lord, You are the one unique reality.<br/>',NULL,86663,2);
INSERT INTO stanza VALUES('NS10003','2','Lord, You’re indescribable,<br/>And, Lord, You’re so enjoyable!<br/>Lord, You are majestic!<br/>Lord, You’re so fantastic!<br/>',NULL,86664,3);
INSERT INTO stanza VALUES('NS10003','3','Lord, You are the loveliest,<br/>And, dear Lord, the finest.<br/>Lord, You are the highest,<br/>And, dear One, the very best!<br/>',NULL,86665,4);
INSERT INTO stanza VALUES('NS10003','4','Lord, You’re the most excellent,<br/>And, Lord, You’re just magnificent!<br/>Lord, Oh Lord, You’re ultimate!<br/>Dearest One, You’re infinite!<br/>',NULL,86666,5);
INSERT INTO stanza VALUES('NS10003','5','No one, Lord, can e’er compete,<br/>And, dearest Lord, You’re so complete!<br/>Lord, You’re so refreshing!<br/>And, Lord, You are my everything!<br/>',NULL,86667,6);
INSERT INTO stanza VALUES('NS10004','1','Jesus, dear Jesus,<br/>You’re so glorious!<br/>You’re such a mystery.<br/>I’ve been captured by Thee.<br/>You’re the greatest attraction,<br/>All-extensive, all-inclusive Person.<br/>You’re the Infinite, beyond measure,<br/>Yet my portion, my priceless treasure.<br/>',NULL,86668,1);
INSERT INTO stanza VALUES('NS10004','2','Jesus, dear Lord,<br/>You’re beyond man’s word.<br/>You’re a God-man.<br/>You’re divine and human.<br/>You’re immortal with eternal might,<br/>Yet became a mortal finite.<br/>You’re almighty, eternally the same,<br/>Yet a man in time became.<br/>',NULL,86669,2);
INSERT INTO stanza VALUES('NS10004','3','Jesus, dear Lord,<br/>You partook blood and flesh.<br/>You’re the Eternal Word,<br/>God in a man manifest.<br/>Lord, You died for humanity<br/>To redeem man for eternity.<br/>Lord, You died on a tree for me.<br/>Lord, You loved me eternally.<br/>',NULL,86670,3);
INSERT INTO stanza VALUES('NS10004','4','Jesus, dear Christ,<br/>Death can’t hold You in the grave.<br/>Now You’re the Spirit.<br/>You can enter man to save.<br/>Satan plotted and killed You dead,<br/>That destroyed him the devil instead.<br/>Lord, You rose from the dead to be<br/>The life-giving Spirit in me.<br/>',NULL,86671,4);
INSERT INTO stanza VALUES('NS10005','1','The Bible is a romance<br/>In the most holy sense:<br/>God and His chosen people<br/>In love it so presents.<br/>This Universal Couple<br/>Throughout it is displayed;<br/>God in Christ is the Bridegroom,<br/>His saints, the Bride, portrayed.<br/>',NULL,86672,1);
INSERT INTO stanza VALUES('NS10005','2','Through shadows, types and figures,<br/>God’s deepest thought is known;<br/>As typified by Adam,<br/>The Husband, Christ, is shown.<br/>A rib brought forth from Adam<br/>Reveals the source of life<br/>By which God built a woman:<br/>Eve, as the church, His wife.<br/>',NULL,86673,2);
INSERT INTO stanza VALUES('NS10005','3','To be His people’s Husband,<br/>To take them as His wife:<br/>This is what God desires<br/>To live in marriage life.<br/>Their sacrifice and worship<br/>Alone could not content;<br/>But with them to be married<br/>Was God’s foremost intent.<br/>',NULL,86674,3);
INSERT INTO stanza VALUES('NS10005','4','This romance is the finest<br/>As seen in Song of Songs;<br/>For her Beloved’s kisses<br/>His seeking lover longs.<br/>Love’s work in her produces<br/>No person of her own,<br/>But she becomes the City,<br/>Her Person, Christ alone.<br/>',NULL,86675,4);
INSERT INTO stanza VALUES('NS10005','5','Christ is our coming Bridegroom;<br/>We are the Church, His Bride,<br/>Redeemed, regenerated,<br/>The issue of His side,<br/>In source, in life, in nature<br/>And person fully one,<br/>His counterpart forever,<br/>The New Jerusalem.<br/>',NULL,86676,5);
INSERT INTO stanza VALUES('NS10006','1','And He showed me a river<br/>Of water of life,<br/>Bright as crystal,<br/>Proceeding out<br/>Of the throne of God<br/>And of the Lamb.<br/>And Thou shalt make them to drink<br/>Of the river of Thy pleasures.<br/>',NULL,86677,1);
INSERT INTO stanza VALUES('NS10006','2','There is a river,<br/>The streams whereof make glad.<br/>The city of God.<br/>She shall not be moved.<br/>God shall help her.<br/>God’s in her midst.<br/>They shall be abundantly satisfied<br/>With the fatness of Thy house.<br/>',NULL,86678,2);
INSERT INTO stanza VALUES('NS10007','1','Jesus, Lord Jesus!<br/>Lord, You’re rich to all,<br/>Unto those who call<br/>Your highest name above all.<br/><br/>Jesus, Lord Jesus!<br/>Oh, Your name most precious!<br/>Lord, You are so glorious!<br/>Lord, You’re so marvelous!<br/>',NULL,86679,1);
INSERT INTO stanza VALUES('NS10007','chorus','Highest name above all names!<br/>Call on Him and He will save.<br/>Jesus, Lord Jesus,<br/>Oh most precious name!<br/>',NULL,86680,2);
INSERT INTO stanza VALUES('NS10007','2','Jesus, Lord Jesus!<br/>Why would Christians feel ashamed<br/>And not call Your precious name?<br/>That is the devil’s scheme.<br/><br/>Jesus, Lord Jesus!<br/>All my friends they tell me<br/>I have changed completely.<br/>You satisfy me thoroughly.<br/>',NULL,86681,3);
INSERT INTO stanza VALUES('NS10007','3','Jesus, Lord Jesus!<br/>Calling Your dear Person,<br/>Once I was opposing,<br/>But now I am enjoying.<br/><br/>Jesus, Lord Jesus!<br/>Let me call You all day long.<br/>To the world that’s something wrong.<br/>Your precious name, the sweetest song.<br/>',NULL,86682,4);
INSERT INTO stanza VALUES('NS10007','4','Jesus, Lord Jesus!<br/>Oh, the devil’s trembling!<br/>When we all start calling<br/>The enemy we’re crushing!<br/><br/>Jesus, Lord Jesus!<br/>Lord, You’re not a doctrine<br/>In the mind for thinking<br/>But Your dear name’s so refreshing!<br/>',NULL,86683,5);
INSERT INTO stanza VALUES('NS10007','5','Jesus, Lord Jesus!<br/>How I love to touch You!<br/>It’s by calling on You!<br/>No other One will do!<br/><br/>Jesus, Lord Jesus!<br/>As I call, I’m drinking,<br/>Triune God partaking.<br/>Lord, You’re my cup of salvation!<br/>',NULL,86684,6);
INSERT INTO stanza VALUES('NS10008','1','We treasure Thee, Lord Jesus,<br/>As God’s reality.<br/>Whate’er our God possesses<br/>Is surely found in Thee.<br/>His very life and essence<br/>Within Thy Being dwells.<br/>His glory and expression<br/>Thy Person fully tells.<br/>',NULL,86685,1);
INSERT INTO stanza VALUES('NS10008','2','Oh! Vast Unmeasured Portion,<br/>Oh! Bountiful Supply,<br/>In light the saints enjoy Thee,<br/>And Thou dost reign thereby.<br/>Within the Father’s bosom<br/>Beloved Son Thou art;<br/>The sweetness of the Godhead<br/>To us Thou dost impart.<br/>',NULL,86686,2);
INSERT INTO stanza VALUES('NS10008','3','Most Excellent of mankind,<br/>Creation’s firstborn One!<br/>God saw Thee and foreknew Thee,<br/>The first created One.<br/>Yet, twice to Thee ’tis given,<br/>Yea, born and born again,<br/>A man in resurrection,<br/>The firstborn from the dead.<br/>',NULL,86687,3);
INSERT INTO stanza VALUES('NS10008','4','The universal Fullness<br/>So pleased resides in Thee.<br/>Within Thee dwells the Godhead,<br/>And Thou, Lord, dwell in me!<br/>Preeminent, transcendent,<br/>Unique in all Thou art,<br/>O’erflowing all the heavens,<br/>Thou now dost fill my heart!<br/>',NULL,86688,4);
INSERT INTO stanza VALUES('NS10008','5','Thou art the hope of glory,<br/>Thou art the mystery,<br/>The center and the focus<br/>Of God’s economy;<br/>The secret of the ages,<br/>Veiled from eternity,<br/>The hidden dispensation,<br/>The Triune God in me!<br/>',NULL,86689,5);
INSERT INTO stanza VALUES('NS10008','6','In all things Thou art foremost,<br/>In everything the best,<br/>In quality the finest,<br/>In quantity boundless.<br/>Superlative in nature,<br/>In form resplendent Thou,<br/>Surpassing e’en the highest,<br/>The peerless One art Thou.<br/>',NULL,86690,6);
INSERT INTO stanza VALUES('NS10009','1','Oh, Jesus, Jesus, wonderful Jesus<br/>Who art enthroned in heav’n above,<br/>Crowned both with glory and with honor,<br/>Attract us by Thy charming love.<br/>',NULL,86691,1);
INSERT INTO stanza VALUES('NS10009','chorus','Oh! Jesus, Jesus, most desired,<br/>Oh! Jesus, Jesus, dearest Lord,<br/>Thy charming beauty us hath captured,<br/>We love, we love Thee, precious Lord.<br/>',NULL,86692,2);
INSERT INTO stanza VALUES('NS10009','2','Thy glory is the splendor related<br/>To Thy dear Person, Jesus Lord;<br/>While honor is the preciousness<br/>Related to Thine own great worth.<br/>',NULL,86693,3);
INSERT INTO stanza VALUES('NS10009','3','Thou art, dear Lord, the greatest attraction,<br/>Within the universe to see,<br/>And like unto an immense magnet,<br/>Drawing Thy seekers unto Thee.<br/>',NULL,86694,4);
INSERT INTO stanza VALUES('NS10009','4','Without Thyself, the charming Object,<br/>How could we from all things turn ’way?<br/>How could we from so many distractions<br/>Upon this earth, Lord, look away?<br/>',NULL,86695,5);
INSERT INTO stanza VALUES('NS10010','1','In His shadow have I rapture and sit down;<br/>And His fruit is sweet to my taste.<br/>He hath brought me to the house of wine,<br/>And His banner over me is love.<br/>Sustain Ye me with raisin cakes,<br/>Refresh me with apples;<br/>For I am sick with love.<br/>His left hand is under my head,<br/>And His right hand doth embrace me.<br/>',NULL,86696,1);
INSERT INTO stanza VALUES('NS10011','1','God is love, Who sent His beloved Son.<br/>Man is fallen with corruption,<br/>But You sent Your dear Son.<br/>God commends His kindness and love toward us,<br/>In that while we were yet sinners<br/>Christ died for us.<br/>',NULL,86697,1);
INSERT INTO stanza VALUES('NS10011','chorus','God You did not spare Him,<br/>Your beloved Son.<br/>Father, how we praise You<br/>For this precious One!<br/>',NULL,86698,2);
INSERT INTO stanza VALUES('NS10011','2','Who can know the love from our Father’s being?<br/>Ears have never heard, eyes have never seen,<br/>But Lord, I’ve been redeemed.<br/>God is love. O God, a man You became;<br/>A cursed man to be, God, You died for me.<br/>Lord, You hung from a tree.<br/>',NULL,86699,3);
INSERT INTO stanza VALUES('NS10011','chorus','Father, You have sent Him,<br/>Your beloved Son.<br/>He shed His blood on Calvary.<br/>Your love reached me.<br/>',NULL,86700,4);
INSERT INTO stanza VALUES('NS10011','3','God so loved the world that He gave us His Son.<br/>Just believe in Him. Be not perishing,<br/>But have eternal life.<br/>Just believe in Him. Be not perishing,<br/>But have eternal life.<br/>',NULL,86701,5);
INSERT INTO stanza VALUES('NS10012','1','Lord, I just love You.<br/>And there’s no one like You.<br/>In the whole universe<br/>I have no other one like You.<br/>Lord Jesus, I love You.<br/>',NULL,86702,1);
INSERT INTO stanza VALUES('NS10013','1','I need You, Jesus,<br/>More and more each day.<br/>I can’t live without You,<br/>Most wonderful One!<br/>',NULL,86703,1);
INSERT INTO stanza VALUES('NS10013','chorus','I need You, Lord,<br/>More and more every day.<br/>I can’t live without You,<br/>Oh, most wonderful One!<br/>',NULL,86704,2);
INSERT INTO stanza VALUES('NS10013','2','My lovely Bridegroom,<br/>Oh, most pleasant One,<br/>Take me in Your chambers,<br/>Sustain me with love!<br/>',NULL,86705,3);
INSERT INTO stanza VALUES('NS10013','chorus','I need You, Lord,<br/>More and more every day.<br/>I can’t live without You,<br/>Oh, most most lovely Bridegroom!<br/>',NULL,86706,4);
INSERT INTO stanza VALUES('NS10013','3','Jesus, just kiss me,<br/>Kisses of Your mouth.<br/>Grace upon Thy lips is<br/>So sweet to my taste.<br/>',NULL,86707,5);
INSERT INTO stanza VALUES('NS10013','chorus','I need You, Lord,<br/>More and more every day.<br/>I can’t live without You;<br/>I need Your sweet taste.<br/>',NULL,86708,6);
INSERT INTO stanza VALUES('NS10013','4','I’m sick with love.<br/>Thy banner over me is love.<br/>You have ravished my heart,<br/>None other for me.<br/>',NULL,86709,7);
INSERT INTO stanza VALUES('NS10013','chorus','I need You, Lord,<br/>More and more every day.<br/>I can’t live without You.<br/>I’ve been ravished by Thee.<br/>',NULL,86710,8);
INSERT INTO stanza VALUES('NS10013','5','I love my Master.<br/>I’ll not go out free.<br/>Take my ear to the door post<br/>And bore it for Thee.<br/>',NULL,86711,9);
INSERT INTO stanza VALUES('NS10013','chorus','I need You, Lord,<br/>More and more every day.<br/>I can’t live without You,<br/>Oh, most wonderful One!<br/>',NULL,86712,10);
INSERT INTO stanza VALUES('NS10013','6','Make haste, Beloved!<br/>Come quickly soon!<br/>Jesus, our desire.<br/>Thy Bride calls for Thee.<br/>',NULL,86713,11);
INSERT INTO stanza VALUES('NS10013','chorus','Come quickly, Lord,<br/>We can’t wait anymore.<br/>Please make haste, dear Beloved!<br/>Your Bride calls for Thee.<br/>Come quickly, Lord, Amen.<br/>',NULL,86714,12);
INSERT INTO stanza VALUES('NS10014','1','Just one touch of You, dear Lord,<br/>Just one look into Your eyes, <br/>Just one kiss from You,<br/>You’re all I need, my Love.<br/><br/>Let me hear again Your voice.<br/>You are now my final choice.<br/>Speak in love to me.<br/>I’ll waste myself on Thee.<br/>',NULL,86715,1);
INSERT INTO stanza VALUES('NS10014','chorus','Nothing and no one can satisfy me <br/> but You anymore.<br/>Jesus, I love You, my only desire.<br/>Oh Lord, I just love You.<br/>',NULL,86716,2);
INSERT INTO stanza VALUES('NS10014','2','Let me touch You as before,<br/>Craving for You more and more,<br/>You’re the very best!<br/>I’ll drop the rest for You.<br/><br/>Oh, the kisses of Your mouth<br/>Make my lips to praise and shout.<br/>Lord, You’re full of grace<br/>Oh, what a taste my Love!<br/>',NULL,86717,3);
INSERT INTO stanza VALUES('NS10014','chorus','Nothing and no one can satisfy me<br/> but You anymore.<br/>Jesus, my first Love, oh set me on fire<br/>For You, my only desire.<br/>',NULL,86718,4);
INSERT INTO stanza VALUES('NS10014','3','Just infuse me with Your eyes.<br/>Oh! This union satisfies!<br/>As I gaze on You.<br/>I’m filled with You, my Love.<br/><br/>Only You alone will do.<br/>I can’t make it without You.<br/>Keep me close to You,<br/>Just joined to You as one.<br/>',NULL,86719,5);
INSERT INTO stanza VALUES('NS10014','chorus','Nothing and no one can satisfy me<br/> but You anymore.<br/>Jesus, I love You, my only desire.<br/>Oh, set my heart on fire.<br/>',NULL,86720,6);
INSERT INTO stanza VALUES('NS10014','4','I repent and now return,<br/>Grant my heart for You to burn.<br/>Flame in me this zeal.<br/>Lord, be in me so real!<br/><br/>I repent and now return,<br/>Grant my heart for You to burn.<br/>Flame in me this zeal.<br/>Lord, be in me so real!<br/>',NULL,86721,7);
INSERT INTO stanza VALUES('NS10014','chorus','Jesus, my first Love! Oh Jesus, my best Love,<br/> I now return to You.<br/>Jesus, my first Love! Oh Jesus, my best Love,<br/>I love You. I just love You!<br/>',NULL,86722,8);
INSERT INTO stanza VALUES('NS10015','1','I need You, dear Lord Jesus,<br/>Each day, I need You more.<br/>I cannot live without You.<br/>It’s You, Lord, I adore.<br/>',NULL,86723,1);
INSERT INTO stanza VALUES('NS10015','chorus','I need You more and more each day.<br/>I need You, Lord, in every way.<br/>Your Person has attracted me.<br/>I need You desperately.&nbsp;&nbsp;(Dear Lord.)<br/>',NULL,86724,2);
INSERT INTO stanza VALUES('NS10015','2','I love You, dearest Jesus.<br/>Each day, I love You more.<br/>Each touch of You, my Jesus,<br/>Is sweeter than before.<br/>',NULL,86725,3);
INSERT INTO stanza VALUES('NS10015','chorus','I love You more and more each day,<br/>I love You, Lord, in every way.<br/>Your Person has attracted me.<br/>I need You desperately. (Dear Lord.)<br/>',NULL,86726,4);
INSERT INTO stanza VALUES('NS10015','3','One taste of You, my Lover.<br/>I need You over and over.<br/>My heart can’t have another.<br/>That’s why I’m a believer.<br/>',NULL,86727,5);
INSERT INTO stanza VALUES('NS10015','chorus','I love You more and more each day.<br/>I love You, Lord, in every way.<br/>Your Person has attracted me.<br/>I need You desperately. (Dear Lord.)<br/>',NULL,86728,6);
INSERT INTO stanza VALUES('NS10016','1','I love You, Lord Jesus!<br/>I love You, Lord, precious One!<br/>No other one compares to You!<br/>I love You, Lord Jesus!<br/>I love You, Lord, precious One!<br/>No other one compares to You!<br/>Jesus, Lord Jesus,<br/>Dear Lord, most lovely One,<br/>Nothing compares to You!<br/>',NULL,86729,1);
INSERT INTO stanza VALUES('NS10017','1','The story of the gospel<br/>Is that the Lord loved us.<br/>The story of Mary<br/>Is that she loved the Lord.<br/>',NULL,86730,1);
INSERT INTO stanza VALUES('NS10017','chorus','The Lord loving us<br/>And we loving Him;<br/>This the fragrance of<br/>Our love offering.<br/>',NULL,86731,2);
INSERT INTO stanza VALUES('NS10017','2','We must preach both:<br/>The Lord Jesus loving us.<br/>And we like Mary,<br/>Loving Him to the uttermost.<br/>',NULL,86732,3);
INSERT INTO stanza VALUES('NS10017','chorus','One is salvation,<br/>The other consecration.<br/>Lord, we pour out<br/>All our love offering.<br/>',NULL,86733,4);
INSERT INTO stanza VALUES('NS10017','3','As we pour upon Him,<br/>This is not just a waste<br/>But a fragrant testimony<br/>Of the sweetness of the Lord.<br/>',NULL,86734,5);
INSERT INTO stanza VALUES('NS10017','chorus','The Lord loving us<br/>And we loving Him:<br/>This the fragrance<br/>Of our love offering.<br/>',NULL,86735,6);
INSERT INTO stanza VALUES('NS10017','4','Throughout the past centuries,<br/>Tens of thousands of precious lives,<br/>Heart treasures, golden futures<br/>Have been wasted upon the Lord.<br/>',NULL,86736,7);
INSERT INTO stanza VALUES('NS10017','chorus','To such lovers,<br/>He’s altogether lovely<br/>And ultimately worthy<br/>Of their costly ointment.<br/>',NULL,86737,8);
INSERT INTO stanza VALUES('NS10017','5','We must love the Lord,<br/>And grasp the opportunity.<br/>Yes, love Him to the uttermost:<br/>A fragrance sweet to God and man.<br/>',NULL,86738,9);
INSERT INTO stanza VALUES('NS10017','chorus','The Lord loving us<br/>And we loving Him:<br/>This the fragrance<br/>Of our love offering.<br/>',NULL,86739,10);
INSERT INTO stanza VALUES('NS10017','6','Lord Jesus, we just love You.<br/>Our life and all we pour on You.<br/>We waste ourselves upon You.<br/>In this universe we just love You.<br/>',NULL,86740,11);
INSERT INTO stanza VALUES('NS10017','chorus','We can’t help but love You,<br/>You’re the greatest value.<br/>Our love is just an issue<br/>Of our seeing of You.<br/>',NULL,86741,12);
INSERT INTO stanza VALUES('NS10018','1','Lord, I’ve set my heart; Lord, I just love You.<br/>Beside You I have no other desire.<br/>Lord, I just like to live You.<br/>',NULL,86742,1);
INSERT INTO stanza VALUES('NS10018','chorus','Lord, I love You because You love me.<br/>I just like to live You,<br/>And be under Your instant moment by moment leading.<br/>',NULL,86743,2);
INSERT INTO stanza VALUES('NS10018','2','On the entire earth, in the whole universe,<br/>I have no int’rest or other desire:<br/>My desire is only You.<br/>',NULL,86744,3);
INSERT INTO stanza VALUES('NS10018','3','Thank You, dearest Lord; You’ve predestinated me.<br/>You’ve called me and saved me and, Lord, preserved me.<br/>You have brought me, Lord, to this day.<br/>',NULL,86745,4);
INSERT INTO stanza VALUES('NS10019','1','Where’s the answer? There must be more for me.<br/>Is this all to life—an empty vanity?<br/>Day by day and year by year go by.<br/>Am I just a man, a man just born to die?<br/>',NULL,86746,1);
INSERT INTO stanza VALUES('NS10019','chorus','Where’s the answer? Oh I’m so empty<br/>And plagued by this vanity.<br/>Deep inside me, My conscience tells me:<br/>I need another destiny.<br/>',NULL,86747,2);
INSERT INTO stanza VALUES('NS10019','2','I convinced my friends that everything’s alright,<br/>That my life and future and everything’s so bright.<br/>But a sense inside me, my friends, I can’t deny,<br/>Warning deep inside me that I was living a lie.<br/>',NULL,86748,3);
INSERT INTO stanza VALUES('NS10019','chorus','Where’s the answer? Oh I’m so empty<br/>And plagued by this vanity.<br/>Deep inside me, My conscience tells me:<br/>I need another destiny.<br/>',NULL,86749,4);
INSERT INTO stanza VALUES('NS10019','3','The world and its glitter left me anxious, dark, and bitter,<br/>Always yearning, my friends, is there something better?<br/>And religion, my friends, is just a Sunday game—<br/>Dead teachings and doctrines will leave you just the same.<br/>',NULL,86750,5);
INSERT INTO stanza VALUES('NS10019','chorus','Where’s the answer? Oh I’m so empty<br/>And plagued by this vanity.<br/>Deep inside me, My conscience tells me:<br/>I need another destiny.<br/>',NULL,86751,6);
INSERT INTO stanza VALUES('NS10019','4','Oh God, where are You? I need You desperately!<br/>Oh God, who are You? Why don’t You answer me?<br/>The heavens declare You and the earth shows Your beauty.<br/>But I’m a man. Oh God, I’m so empty!<br/>',NULL,86752,7);
INSERT INTO stanza VALUES('NS10019','chorus','Lord, have mercy! I’m crying for You!<br/>Please hear! Are you really true?<br/>I’m dark and lonely. You’re far, far from me.<br/>Oh Lord, I need You desperately!<br/>',NULL,86753,8);
INSERT INTO stanza VALUES('NS10019','5','One day a friend told me that Jesus is the Lord.<br/>To my great surprise, it’s written in the Word.<br/>They asked me to believe You. Your name I once blasphemed.<br/>Dear Lord, You saved me just by calling on Your name.<br/>',NULL,86754,9);
INSERT INTO stanza VALUES('NS10019','chorus','Oh, Lord Jesus, dear Son, so glorious,<br/>I’m cleansed and You entered into me.<br/>Oh, Lord Jesus, Your name most precious!<br/>Your Person, dear Lord, I now possess.<br/>',NULL,86755,10);
INSERT INTO stanza VALUES('NS10020','1','What’s the use? There is no hope for me,<br/>Deep inside just fear and misery.<br/>Man’s enslaved by this haunting melody—<br/>Everything, my friend, is temporary.<br/>',NULL,86756,1);
INSERT INTO stanza VALUES('NS10020','chorus','There is an answer: a wonderful Person!<br/>He’s Jesus the Lord; He’s God’s beloved Son!<br/>This wonderful Person is now your solution.<br/>Just take and receive Him; He’s God’s Firstborn Son!<br/>',NULL,86757,2);
INSERT INTO stanza VALUES('NS10020','2','Day by day, I tried to stop this song.<br/>What is it? There must be something wrong...<br/>Oh! This life is just a hopelessness!<br/>Always searching, but tasting emptiness.<br/>',NULL,86758,3);
INSERT INTO stanza VALUES('NS10020','chorus','There is an answer: a wonderful Person!<br/>He’s Jesus the Lord; He’s God’s beloved Son!<br/>This wonderful Person is now your solution.<br/>Just take and receive Him; He’s God’s Firstborn Son!<br/>',NULL,86759,4);
INSERT INTO stanza VALUES('NS10020','3','All day long you play the “same ole song“:<br/>“Good morning“, “How are you?“, “No, there is nothing wrong.“<br/>You’re swept by the world of deceptive vanity,<br/>A tide looking good, but it’s void of reality.<br/>',NULL,86760,5);
INSERT INTO stanza VALUES('NS10020','chorus','Just call “Oh Lord Jesus“: the truth you’re confessing<br/>That God raised this Jesus from among the dead.<br/>Your heart this believing, just call to receive Him.<br/>He’s Jesus the Savior, your great salvation.<br/>',NULL,86761,6);
INSERT INTO stanza VALUES('NS10020','4','You’re conformed to unreality,<br/>Trapped in a wheel of human anxiety.<br/>You are caught, you’re in the web already.<br/>You’re spun to this song: you’re just the spider’s prey.<br/>',NULL,86762,7);
INSERT INTO stanza VALUES('NS10020','chorus','Jesus crushed the devil and overcame evil.<br/>That kingdom He leveled and destroyed the devil.<br/>He will free you from sin, from death, world and Satan.<br/>Just call “Oh Lord Jesus” and He will enter in.<br/>',NULL,86763,8);
INSERT INTO stanza VALUES('NS10020','5','Life is a song as a time hour glass,<br/>Sand by sand, my friend it cannot last.<br/>You’re born, you live, and eventually you die.<br/>Friend, you can’t change it, no need to even try.<br/>',NULL,86764,9);
INSERT INTO stanza VALUES('NS10020','chorus','There is a new song, a wonderful Person!<br/>He’s Jesus the Lord, He’s God’s beloved Son!<br/>This wonderful Person is now your solution!<br/>Just take and receive Him; He’s God’s Firstborn Son!<br/>',NULL,86765,10);
INSERT INTO stanza VALUES('NS10021','1','O God of glory,<br/>You’ve changed my destiny.<br/>Oh Lord, Your mercy<br/>In love appeared to me.<br/><br/>O God of glory,<br/>You have attracted me!<br/>My heart responds to Thee<br/>And turns spontaneously.<br/>',NULL,86766,1);
INSERT INTO stanza VALUES('NS10021','chorus','O God of glory,<br/>You have appeared to me.<br/>Dear Lord, Your beauty,<br/>My God, has captured me!<br/>',NULL,86767,2);
INSERT INTO stanza VALUES('NS10021','2','In darkness once I groped,<br/>A person with no hope.<br/>But light in darkness shined,<br/>My heart enlightened.<br/><br/>You came to me as Light<br/>And shattered all my night.<br/>Your glory, what a sight!<br/>You made me, Lord, so bright.<br/>',NULL,86768,3);
INSERT INTO stanza VALUES('NS10021','3','To You my heart was drawn,<br/>It wasn’t on my own.<br/>Your beauty made me turn<br/>And caused my heart to burn.<br/><br/>You touched my hardened heart<br/>And softened every part.<br/>I saw Your shining face.<br/>Now nothing can erase.<br/>',NULL,86769,4);
INSERT INTO stanza VALUES('NS10021','4','I couldn’t, Lord, believe,<br/>But, Lord, You still appeared.<br/>Your life in me conceived,<br/>Dear Lord, I now believe.<br/><br/>You called not being as being<br/>In me conceiving.<br/>Your life transfusing,<br/>I’m now reacting.<br/>',NULL,86770,5);
INSERT INTO stanza VALUES('NS10021','chorus','O God of glory,<br/>You’re now my story.<br/>Dear One, I can’t refuse!<br/>By You, I’ve been transfused.<br/>',NULL,86771,6);
INSERT INTO stanza VALUES('NS10021','5','Like father Abraham,<br/>To You, dear Lord, he ran.<br/>Your glory has infused,<br/>Dear Lord, we can’t refuse.<br/><br/>You came to fallen man<br/>As, Lord, the Great I Am.<br/>In us dispensing<br/>The blessing to mankind.<br/>',NULL,86772,7);
INSERT INTO stanza VALUES('NS10022','1','Shepherd, receive man,<br/>Come near and eat with them,<br/>Publicans and sinners.<br/>Go out to carry them home<br/>On Your shoulders, rejoicing.<br/>Lord, carry them home.<br/>',NULL,86773,1);
INSERT INTO stanza VALUES('NS10022','2','Spirit, dear Spirit,<br/>Where is the one lost coin?<br/>Yes, You have the nine,<br/>But the one You must find.<br/>Dear Spirit, You’re sweeping<br/>All over the earth.<br/>',NULL,86774,2);
INSERT INTO stanza VALUES('NS10022','3','Father, dear Father,<br/>Have mercy on mankind!<br/>He’s fallen to the pigs’ pen.<br/>When will he return?<br/>Dear Father, just kiss them,<br/>Your sons coming home.<br/>',NULL,86775,3);
INSERT INTO stanza VALUES('NS10022','4','Father of mercy,<br/>Clothe him with the best robe<br/>And kill the fatted calf<br/>And eat and be merry —<br/>He was lost, but found,<br/>Was dead, but now he lives.<br/>',NULL,86776,4);
INSERT INTO stanza VALUES('NS10023','1','Just to be in You as You’re in me.<br/>Just abide in You, Lord, constantly.<br/>Here I’m one with You, as You’re with me.<br/>Here we’re joined as one, Lord, mutually.<br/>',NULL,86777,1);
INSERT INTO stanza VALUES('NS10023','chorus','God’s dispensing, His economy,<br/>In His Trinity,<br/>He’s transfusing, and He’s mingling<br/>All He is to me.<br/>',NULL,86778,2);
INSERT INTO stanza VALUES('NS10023','2','I am just a branch, and You’re the vine.<br/>As I dwell in You, everything is fine.<br/>Here I’d like to be, Lord, all the time.<br/>Here I’m Yours, dear Lord, and You are mine.<br/>',NULL,86779,3);
INSERT INTO stanza VALUES('NS10023','3','I’m a branch that’s been, Lord, grafted in.<br/>I’m supplied in You in this life union.<br/>Here Your riches, Lord, in this sweet life flow.<br/>As I dwell in You, I will surely grow.<br/>',NULL,86780,4);
INSERT INTO stanza VALUES('NS10023','4','As I dwell in You, and You in me,<br/>Here I’m joined to You, Lord, practically.<br/>As I stay with You, as You’re with me,<br/>We will mingle, Lord, subjectively.<br/>',NULL,86781,5);
INSERT INTO stanza VALUES('NS10023','5','As I’m loving You and enjoying You, Lord,<br/>You become in me the rhema word.<br/>Here I’ll pray in You as You pray in me.<br/>You’ll bear fruit in me, Lord, abundantly.<br/>',NULL,86782,6);
INSERT INTO stanza VALUES('NS10023','6','As I dwell in You, Lord You’re flowing through.<br/>Lord, You’re filling me, overflowing too.<br/>Here we all are one and expressing You.<br/>Here our joy is full as we dwell in You.<br/>',NULL,86783,7);
INSERT INTO stanza VALUES('NS10024','1','God is man’s treasure.<br/>He is man’s joy and pleasure.<br/>God is man’s treasure.<br/>He is man’s joy and pleasure.<br/>God placed man in paradise,<br/>Right in front of the tree of life.<br/>If man would eat the tree of life,<br/>He surely would be so satisfied.<br/>',NULL,86784,1);
INSERT INTO stanza VALUES('NS10024','2','Saints, beware the knowledge tree<br/>Appearing so good; it’s even pretty.<br/>Its evil and good will open your eyes.<br/>Its issue, my friend: you’ll surely die.<br/>The serpent, he crept in,<br/>Injected in man his death and sin.<br/>Man was seduced this knowledge to take.<br/>My friend, that was the greatest mistake.<br/>',NULL,86785,2);
INSERT INTO stanza VALUES('NS10024','3','Look, dear saints, in eternity!<br/>There’s just a river and a tree!<br/>It’s life, life abundantly —<br/>Eating and drinking our destiny.<br/>God’s growing and flowing.<br/>We’re eating and drinking.<br/>God is our treasure.<br/>He is our joy and pleasure.<br/>',NULL,86786,3);
INSERT INTO stanza VALUES('NS10024','4','Christ is the tree of life<br/>Eating Him always satisfies.<br/>Christ is the river<br/>Drink Him, our joy and pleasure.<br/>Eat Him and drink Him,<br/>Christ our enjoyment.<br/>God is our treasure.<br/>He is our joy and pleasure.<br/>',NULL,86787,4);
INSERT INTO stanza VALUES('NS10024','5','Dear saints, just love Him.<br/>Surely you will enjoy Him.<br/>He is so enjoyable,<br/>So precious and so available.<br/>Our God is dispensing<br/>His life into us, so refreshing.<br/>He is so enjoyable,<br/>So precious and so available.<br/>',NULL,86788,5);
INSERT INTO stanza VALUES('NS10025','1','Brothers’ part:<br/>Whom have I in heaven but Thee?<br/>And there’s none upon the earth that I<br/>&nbsp;&nbsp; desire beside Thee.<br/>Whom have I in heaven but Thee?<br/>And there’s none upon the earth that I<br/>&nbsp;&nbsp; desire beside Thee.<br/>',NULL,86789,1);
INSERT INTO stanza VALUES('NS10025','2','My flesh and my heart faileth.<br/>But God is the strength of my heart<br/>And my portion forever.<br/>&nbsp;&nbsp; (Repeat 2)<br/>',NULL,86790,2);
INSERT INTO stanza VALUES('NS10025','3','Nevertheless, I am continually with Thee;<br/>Thou hast holden me by my right hand;<br/>Thou shalt guide me with Thy counsel and<br/>Afterwards receive me to glory.<br/>',NULL,86791,3);
INSERT INTO stanza VALUES('NS10025','4','One thing have I desired of the Lord;<br/>That will I seek after,<br/>That I may dwell in the house of the Lord.<br/>&nbsp;&nbsp; (Repeat 4)<br/>',NULL,86792,4);
INSERT INTO stanza VALUES('NS10025','5','I may dwell in the house of the Lord,<br/>All the days of my life,<br/>To behold the beauty of the Lord<br/>And to inquire in His temple.<br/>',NULL,86793,5);
INSERT INTO stanza VALUES('NS10025','1','Sisters’ part:<br/>I am continually with Thee;<br/>Thou hast beholden me by my right hand.<br/>I am continually with Thee;<br/>Thou hast holden me by my right hand.<br/>',NULL,86794,6);
INSERT INTO stanza VALUES('NS10025','2','He is my refuge<br/>And my fortress;<br/>My God, in Him will I trust.<br/>&nbsp;&nbsp; (Repeat 2)<br/>',NULL,86795,7);
INSERT INTO stanza VALUES('NS10025','3','I have set the Lord<br/>Always before me;<br/>He is at my right hand;<br/>I shall not be moved.<br/>',NULL,86796,8);
INSERT INTO stanza VALUES('NS10025','4','Blessed are they<br/>That dwell in the house;<br/>They will be praising Thee all the day long.<br/>&nbsp;&nbsp; (Repeat 4)<br/>',NULL,86797,9);
INSERT INTO stanza VALUES('NS10025','5','There is a river<br/>Whose streams make glad<br/>The city of our God.<br/>God is in the midst of her.<br/>',NULL,86798,10);
INSERT INTO stanza VALUES('NS10026','1','In eternity, in the beginning, before the world began,<br/>God’s intention, it was hidden deep in God for man.<br/>God created all the heaven and earth for man.<br/>God’s center was this man.<br/>',NULL,86799,1);
INSERT INTO stanza VALUES('NS10026','chorus','The tree of life, if man would eat,<br/>God’s will and plan in man, God would complete.<br/>This vessel man is for God’s plan,<br/>God filling him and thus, God expressing.<br/>',NULL,86800,2);
INSERT INTO stanza VALUES('NS10026','2','God has made man on the sixth day in a special way.<br/>In God’s image and God’s likeness, man was formed from clay<br/>With a spirit, soul and body, a three-part man<br/>God’s vessel was this man.<br/>',NULL,86801,3);
INSERT INTO stanza VALUES('NS10026','chorus','Man’s spirit needs to take the lead<br/>On God to feed. To this, man must take heed.<br/>Our spirit needs to take the lead<br/>On life to feed. Then God we will receive.<br/>',NULL,86802,4);
INSERT INTO stanza VALUES('NS10026','3','Man was poisoned by the serpent, the knowledge tree he took.<br/>In the garden, there in Eden, tree of life he forsook.<br/>Man got fallen with rebellion and corrupted within,<br/>A man with death and sin.<br/>',NULL,86803,5);
INSERT INTO stanza VALUES('NS10026','chorus','The evil and the good you see<br/>Is just the fruit of the same knowledge tree.<br/>The knowledge-tree is God’s enemy<br/>That Adam ate by the serpent’s subtlety.<br/>',NULL,86804,6);
INSERT INTO stanza VALUES('NS10026','4','Man was driven out of Eden for he was serpentine,<br/>Now a vessel not of glory but of corruption.<br/>Man a flesh became; he is not the same, a man of shame<br/>A vessel dead within.<br/>',NULL,86805,7);
INSERT INTO stanza VALUES('NS10026','chorus','The evil and the good you see<br/>Is just the fruit of the same knowledge tree.<br/>The knowledge-tree is God’s enemy<br/>That Adam ate by the serpent’s subtlety.<br/>',NULL,86806,8);
INSERT INTO stanza VALUES('NS10026','5','For this cause, Lord, You came from heaven, and You became a slave.<br/>The Creator, the God of glory, became a man to save.<br/>As the Bridegroom and a Husband for Your wife, Your bride,<br/>Your love flowed from Your side.<br/>',NULL,86807,9);
INSERT INTO stanza VALUES('NS10026','chorus','Your love so great nothing can break;<br/>Your love for her You could not, Lord, forsake.<br/>She’s in Your heart, in Your deepest part.<br/>Your love for her, Dear Lord, You could not part.<br/>',NULL,86808,10);
INSERT INTO stanza VALUES('NS10026','6','Lord, we love You. Lord, we need You; everyday Lord we do.<br/>We can’t make it. Lord, we hate it when we’re not with You.<br/>You’re so wonderful and so faithful, Oh precious One!<br/>To You we now respond.<br/>',NULL,86809,11);
INSERT INTO stanza VALUES('NS10026','chorus','Your love so great nothing can break;<br/>We now respond to Your love and Your compassion.<br/>You’re in my heart, in my deepest part.<br/>My love for You, Dear Lord, I cannot part.<br/>',NULL,86810,12);
INSERT INTO stanza VALUES('NS10027','1','Let’s go on!<br/>Forward come!<br/>',NULL,86811,1);
INSERT INTO stanza VALUES('NS10027','chorus','A heart that is loving Him,<br/>A heart that is willing,<br/>A heart that’s uplifted,<br/>No, not defeated!<br/>',NULL,86812,2);
INSERT INTO stanza VALUES('NS10027','chorus','Let’s go on!<br/>Forward come<br/>To the Son!<br/>',NULL,86813,3);
INSERT INTO stanza VALUES('NS10027','chorus','We are Your vessels,<br/>Created to be<br/>Man in Your image<br/>To be filled up with Thee.<br/>You’re my enjoyment<br/>Overflowing me!<br/>I’m a man in Your image,<br/>Thus expressing Thee!<br/>',NULL,86814,4);
INSERT INTO stanza VALUES('NS10027','2','Let’s go on!<br/>Forward come!<br/>',NULL,86815,5);
INSERT INTO stanza VALUES('NS10027','chorus','A spirit that’s burning,<br/>A heart that is bubbling,<br/>Saints that are eating<br/>And always drinking!<br/>',NULL,86816,6);
INSERT INTO stanza VALUES('NS10027','chorus','Let’s go on!<br/>Forward come<br/>To the Son!<br/>',NULL,86817,7);
INSERT INTO stanza VALUES('NS10027','3','Let’s go on!<br/>Forward come!<br/>',NULL,86818,8);
INSERT INTO stanza VALUES('NS10027','chorus','Spirit releasing,<br/>Saints that are feasting,<br/>Not analyzing,<br/>Or criticizing.<br/>',NULL,86819,9);
INSERT INTO stanza VALUES('NS10027','chorus','Let’s go on!<br/>Forward come<br/>To the Son!<br/>',NULL,86820,10);
INSERT INTO stanza VALUES('NS10027','4','Let’s go on!<br/>Forward come!<br/>',NULL,86821,11);
INSERT INTO stanza VALUES('NS10027','chorus','Life so enjoyable,<br/>Else it be terrible,<br/>But He’s so wonderful,<br/>And so available!<br/>',NULL,86822,12);
INSERT INTO stanza VALUES('NS10027','chorus','Let’s go on!<br/>Forward come<br/>To the Son!<br/>',NULL,86823,13);
INSERT INTO stanza VALUES('NS10028','1','In Revelation see<br/>God’s final mystery;<br/>Why God created you and me.<br/>He predestinated me!<br/>Our mutual destiny;<br/>Christ and the churches are for me!<br/>',NULL,86824,1);
INSERT INTO stanza VALUES('NS10028','chorus','In spirit we must be,<br/>To hear His voice and see.<br/>Turn to the Son of Man<br/>In the golden lampstands.<br/>',NULL,86825,2);
INSERT INTO stanza VALUES('NS10028','2','You’re walking in her midst;<br/>She is Your heart’s interest.<br/>To You, Lord, nothing else exists.<br/>No, nothing can deter,<br/>No person can alter<br/>The love, dear Lord, You have for her.<br/>',NULL,86826,3);
INSERT INTO stanza VALUES('NS10028','chorus','This mystery, Oh how great!<br/>Oh, saints it’s not too late!<br/>All else is vanity;<br/>Take this reality.<br/>',NULL,86827,4);
INSERT INTO stanza VALUES('NS10028','3','Your eyes, a flame of fire.<br/>To one, Lord, You aspire:<br/>It’s her, Lord, You completely desire.<br/>The breastplate on Your chest,<br/>Golden girdle on Your breast.<br/>Your Bride: on her Your heart is set!<br/>',NULL,86828,5);
INSERT INTO stanza VALUES('NS10028','chorus','Saints, stand together<br/>One with another.<br/>Christ and the churches are<br/>The end of our search.<br/>',NULL,86829,6);
INSERT INTO stanza VALUES('NS10028','4','The speaking of Your voice<br/>Trumpets Your single choice:<br/>Oh Son of Man, Your gold lampstand.<br/>Lord, keep me in Your hand<br/>In the seven golden lampstands,<br/>Shining You for Your eternal plan.<br/>',NULL,86830,7);
INSERT INTO stanza VALUES('NS10028','chorus','We at Your feet do fall.<br/>Have mercy on us all.<br/>Your face, the shining sun,<br/>Touch me, Oh Living One!<br/>',NULL,86831,8);
INSERT INTO stanza VALUES('NS10028','5','You’re never satisfied<br/>Until You have Your Bride.<br/>Our hearts with Yours must coincide;<br/>Transfuse me with Your sense.<br/>Your call is so immense.<br/>Responding to Your love intense!<br/>',NULL,86832,9);
INSERT INTO stanza VALUES('NS10028','chorus','Saints, open wide to Him!<br/>Don’t let this vision dim.<br/>Lord, take our being!<br/>Wreck us from everything!<br/>',NULL,86833,10);
INSERT INTO stanza VALUES('NS10028','6','I hate to lukewarm be!<br/>Lord, burn me thoroughly.<br/>My first, My best, I come to Thee.<br/>The seven Spirits burn,<br/>Intensified to turn<br/>My heart for You to be so firm.<br/>',NULL,86834,11);
INSERT INTO stanza VALUES('NS10028','chorus','Grant me a hot pursuit!<br/>All else in me uproot!<br/>Oh Lord, do burn each part!<br/>Grant me a fresh new start.<br/>',NULL,86835,12);
INSERT INTO stanza VALUES('NS10028','7','Lord, be my first and best.<br/>All else I would detest.<br/>My all in You, Lord, I invest.<br/>I now pour out on Thee.<br/>Lord, You have conquered me.<br/>You are my choice eternally.<br/>',NULL,86836,13);
INSERT INTO stanza VALUES('NS10028','chorus','We’re in the final stage,<br/>The age of every age.<br/>Oh Lord, in me advance!<br/>Thank You for this last chance.<br/>',NULL,86837,14);
INSERT INTO stanza VALUES('NS10029','1','As virgins we must be wise and pure,<br/>So single to You, Lord to grow and mature.<br/>We’re going forth to meet You, our Bridegroom so sweet,<br/>Our touch with You, Jesus, must be intimate.<br/>',NULL,86838,1);
INSERT INTO stanza VALUES('NS10029','chorus','Lord, I love You above all,<br/>Watching hourly lest I fall.<br/>We would buy the oil today.<br/>Lord, prepare us, oh, get us ready!<br/>',NULL,86839,2);
INSERT INTO stanza VALUES('NS10029','2','Not only my lamp, Lord, but my vessel too,<br/>Redeeming the time to be filled up with You.<br/>I’m going forth to meet You, my Bridegroom so dear.<br/>I know then at midnight You’ll soon, Lord, appear.<br/>',NULL,86840,3);
INSERT INTO stanza VALUES('NS10029','3','Lord, make us ready at any cost<br/>Or else at Your coming we’ll suffer great loss.<br/>We don’t want to say, Lord, our lamp’s going out.<br/>Then it is too late when we hear the great shout.<br/>',NULL,86841,4);
INSERT INTO stanza VALUES('NS10029','4','As virgins we’re loving and enjoying You,<br/>Always responding, You’re fresh and so new.<br/>Our spirits You’re filling and soul saturating.<br/>Our lamps and our vessels we surrender to You.<br/>',NULL,86842,5);
INSERT INTO stanza VALUES('NS10030','1','Deep in God’s heart there’s been,<br/>Before the time began,<br/>God’s desire to be expressed,<br/>This He planned in eternal past.<br/>',NULL,86843,1);
INSERT INTO stanza VALUES('NS10030','chorus','God eternal had a purpose<br/>In eternal past.<br/>He created man in His image<br/>that man would God express.<br/>',NULL,86844,2);
INSERT INTO stanza VALUES('NS10030','2','Genesis, the blueprint —<br/>Revelation, the fulfillment —<br/>From God’s plan and economy<br/>To the city in eternity.<br/>',NULL,86845,3);
INSERT INTO stanza VALUES('NS10030','3','Man from the dust of the ground<br/>At the end, New Jerusalem.<br/>Here God’s wisdom and love abound.<br/>Oh! This is most profound!<br/>',NULL,86846,4);
INSERT INTO stanza VALUES('NS10030','4','Deep in God’s heart He planned<br/>To mingle Himself with man.<br/>God, as a river and a tree,<br/>Man’s food and drink to be.<br/>',NULL,86847,5);
INSERT INTO stanza VALUES('NS10030','5','God our enjoyment<br/>Issues the fulfillment:<br/>A city as His expression<br/>Built with gold, pearl and precious stones.<br/>',NULL,86848,6);
INSERT INTO stanza VALUES('NS10031','1','Lord, Your return...<br/>How long must it be, dear Lord?<br/>The ages have come,<br/>The centuries have gone,<br/>The years have passed us by.<br/>',NULL,86849,1);
INSERT INTO stanza VALUES('NS10031','chorus','Lovely One, come soon.<br/>Precious Lord, return!<br/>Lord, do not delay.<br/>We’ll redeem everyday<br/>For Your coming soon.<br/>',NULL,86850,2);
INSERT INTO stanza VALUES('NS10031','2','A generation...<br/>Lord, of them that seek Your face;<br/>A remnant for You<br/>Whose hearts are so true.<br/>They’re those who just love You.<br/>',NULL,86851,3);
INSERT INTO stanza VALUES('NS10031','chorus','King of glory come in!<br/>Saints, open wide to Him.<br/>O, lift up Your gate,<br/>It’s not too late.<br/>Let the King come in.<br/>',NULL,86852,4);
INSERT INTO stanza VALUES('NS10031','3','A generation...<br/>With a goal to bring You back.<br/>Their treasure is You,<br/>You’re their future too.<br/>They care for only You.<br/>',NULL,86853,5);
INSERT INTO stanza VALUES('NS10031','chorus','This goal is deep within,<br/>A fire that’s burning in them.<br/>They’re consumed by this zeal,<br/>This only is real,<br/>Lord, to bring You back.<br/>',NULL,86854,6);
INSERT INTO stanza VALUES('NS10031','4','A generation...<br/>Lord, by You they are possessed.<br/>You have captured their heart,<br/>The world has no part,<br/>Their joy is only You.<br/>',NULL,86855,7);
INSERT INTO stanza VALUES('NS10031','chorus','They’re virgins pure and wise.<br/>Just You are in their eyes.<br/>Their hearts make full room<br/>For You, dear Bridegroom,<br/>For Your coming soon.<br/>',NULL,86856,8);
INSERT INTO stanza VALUES('NS10031','5','Oh, generation...<br/>The Spirit and Bride say come —<br/>The Spirit’s calling you.<br/>The Bride is calling too!<br/>Take heed to this mingled cry!<br/>',NULL,86857,9);
INSERT INTO stanza VALUES('NS10031','chorus','Come, oh seekers, come<br/>To our Groom, most pleasant Person.<br/>God’s eternal plan<br/>Is to mingle with man.<br/>This His satisfaction.<br/>',NULL,86858,10);
INSERT INTO stanza VALUES('NS10031','6','Oh come, Lord Jesus...<br/>For this cause, Lord, strengthen us.<br/>Keep us faithful to stand<br/>All the way to the end.<br/>Uphold us in Your hands.<br/>',NULL,86859,11);
INSERT INTO stanza VALUES('NS10031','chorus','Come, Lord Jesus, come<br/>For Your Bride, New Jerusalem.<br/>Till we meet face to face,<br/>Fill us daily with grace.<br/>For that day make haste.<br/>',NULL,86860,12);
INSERT INTO stanza VALUES('NS10032','1','Lord, we want to live You<br/>In the most intimate<br/>And the closest contact,<br/>Closest contact with You.<br/>Acting according<br/>To the index of Your eyes;<br/>A person one with Christ,<br/>Full of Christ.<br/>',NULL,86861,1);
INSERT INTO stanza VALUES('NS10032','2','And one who is saturated<br/>&nbsp;&nbsp;&nbsp;&nbsp;with Christ<br/>One who is so broken<br/>And even terminated<br/>In his natural life,<br/>Softened and flexible<br/>&nbsp;&nbsp;&nbsp;&nbsp;in his will,<br/>Affectionate, yet restricted<br/>&nbsp;&nbsp;&nbsp;&nbsp;in emotions,<br/>Sober and considerate<br/>&nbsp;&nbsp;&nbsp;&nbsp;in his mind,<br/>And pure, genuine<br/>&nbsp;&nbsp;&nbsp;&nbsp;in his spirit.<br/>',NULL,86862,2);
INSERT INTO stanza VALUES('NS10032','3','This is for the benefit<br/>Of all the believers<br/>That they may experience<br/>And enjoy Christ<br/>For the fulfillment of God’s purpose<br/>In the building up of Christ’s Body,<br/>In the building up of Your Body.<br/>',NULL,86863,3);
INSERT INTO stanza VALUES('NS10033','1','My heart was far from You.<br/>My worship was not true.<br/>My lips were honoring Thee<br/>But I was so empty.<br/>',NULL,86864,1);
INSERT INTO stanza VALUES('NS10033','chorus','Lord, help me! Have mercy!<br/>Lord, now deliver me!<br/>All else is vanity.<br/>You are reality!<br/>',NULL,86865,2);
INSERT INTO stanza VALUES('NS10033','2','Traditions are a lie.<br/>Mere practice can’t satisfy.<br/>No matter how hard you try<br/>Inside you feel so dry.<br/>',NULL,86866,3);
INSERT INTO stanza VALUES('NS10033','chorus','Lord water me! I’m so thirsty!<br/>I come to drink of Thee.<br/>You are the Spirit of life<br/>To free me from all strive.<br/>',NULL,86867,4);
INSERT INTO stanza VALUES('NS10033','3','The doctrines and the creeds<br/>Have never met my needs.<br/>The letters have killed me dead<br/>My need is Living Bread.<br/>',NULL,86868,5);
INSERT INTO stanza VALUES('NS10033','chorus','Lord, feed me! I’m so hungry!<br/>I come to eat of Thee.<br/>Your Person now I can take.<br/>The Living Word partake.<br/>',NULL,86869,6);
INSERT INTO stanza VALUES('NS10033','4','I need You desperately<br/>To get You into me!<br/>I drink You as the Spirit, Lord,<br/>And eat You in the Word.<br/>',NULL,86870,7);
INSERT INTO stanza VALUES('NS10033','chorus','I’m satisfied! And You’re testified!<br/>There is no lack in Thee.<br/>You are the river and the tree,<br/>My feast eternally.<br/>',NULL,86871,8);
INSERT INTO stanza VALUES('NS10034','1','The Lord is my Shepherd; I shall not want.<br/>He makes me to lie down in green pastures;<br/>He leads me beside still waters.<br/>',NULL,86872,1);
INSERT INTO stanza VALUES('NS10034','2','He restores my soul: He guides me.<br/>In the paths of righteousness<br/>For His Name’s sake.<br/>',NULL,86873,2);
INSERT INTO stanza VALUES('NS10034','3','Even though I walk through the valley,<br/>The valley of the shadow of death;<br/>Even though I walk through the valley,<br/>The valley of the shadow of death;<br/>I fear no evil for Thou art with me;<br/>Thy rod and Thy staff they comfort me.<br/>',NULL,86874,3);
INSERT INTO stanza VALUES('NS10034','4','Thou dost prepare a table for me<br/>In the presence of mine enemies<br/>And anointest my head with oil.<br/>',NULL,86875,4);
INSERT INTO stanza VALUES('NS10034','5','Only goodness and mercy will follow me<br/>All the days of my life,<br/>Only goodness and mercy will follow me<br/>All the days of my life,<br/>And I will dwell in the house of the Lord forever.<br/>',NULL,86876,5);
INSERT INTO stanza VALUES('NS10035','1','When we are with unveiled face<br/>Beholding and reflecting the glory of the Lord,<br/>He infuses us with the elements<br/>Of what He is and of what He has done.<br/>',NULL,86877,1);
INSERT INTO stanza VALUES('NS10035','chorus','But we all with unveiled face,<br/>Beholding and reflecting<br/>Like a mirror the glory of the Lord,<br/>Are being transformed<br/>Into the same image<br/>From glory to glory,<br/>Even as from the Lord Spirit.<br/>',NULL,86878,2);
INSERT INTO stanza VALUES('NS10035','2','Thus we are being transformed<br/>Metabolic’lly to have His life-shape<br/>By His life-pow’r with His life-essence,<br/>Transfigured by renewing our mind.<br/>',NULL,86879,3);
INSERT INTO stanza VALUES('NS10036','1','For the Lord has chosen Zion,<br/>He has desired her.<br/>For the Lord has chosen Zion<br/>For His habitation.<br/>This is my rest forever,<br/>Here will I dwell.<br/>This is my rest forever;<br/>I have desired her.<br/>',NULL,86880,1);
INSERT INTO stanza VALUES('NS10037','1','Awake, awake, Deborah!<br/>Awake, awake, utter a song!<br/>Arise, Barak, and lead<br/>Your captivity captive!<br/>(Repeat)<br/>',NULL,86881,1);
INSERT INTO stanza VALUES('NS10037','chorus','Let your enemies perish, oh Jehovah.<br/>But let them that love Him be as the sun!<br/>',NULL,86882,2);
INSERT INTO stanza VALUES('NS10037','2','Awake, awake, Oh generation!<br/>Come out, come out from all the nations.<br/>Arise, Christians, and give<br/>Yourselves to Christ and the church.<br/>(Repeat)<br/>',NULL,86883,3);
INSERT INTO stanza VALUES('NS10037','chorus','This is the Lord’s generation!<br/>Oh come out from all the nations!<br/>',NULL,86884,4);
INSERT INTO stanza VALUES('NS10037','3','Awake, awake, Oh sisters!<br/>Awake, awake, utter this song!<br/>Arise, brothers, and wield<br/>The sword of the Spirit!<br/>(Repeat)<br/>',NULL,86885,5);
INSERT INTO stanza VALUES('NS10037','chorus','Let us stand strong in the Lord<br/>By fighting with prayer in the Word!<br/>',NULL,86886,6);
INSERT INTO stanza VALUES('NS10038','1','My words cannot express...<br/>Dear Lord, You’re just the best!<br/>Lovely Jesus, precious Jesus.<br/>No other one will do,<br/>My Love, I just want You.<br/>Lovely Jesus, precious Jesus.<br/>',NULL,86887,1);
INSERT INTO stanza VALUES('NS10038','chorus','He’s far beyond your dreams,<br/>Heaven and everything.<br/>Lovely Jesus, precious Jesus!<br/>He’s far beyond your dreams,<br/>Surpassing everything.<br/>Lovely Jesus, precious Jesus!<br/>',NULL,86888,2);
INSERT INTO stanza VALUES('NS10038','2','My friend, I can’t explain...<br/>How excellent His name!<br/>Lovely Jesus, precious Jesus!<br/>His name of greatest worth,<br/>As ointment sweet, poured forth.<br/>Lovely Jesus, precious Jesus!<br/>',NULL,86889,3);
INSERT INTO stanza VALUES('NS10038','chorus','The cup of salvation<br/>Is calling on His name.<br/>Oh Lord Jesus, precious Jesus!<br/>Oh, He is rich to all.<br/>Don’t wait; it’s time to call.<br/>Drink in Jesus, precious Jesus.<br/>',NULL,86890,4);
INSERT INTO stanza VALUES('NS10038','3','He is the Lamb of God.<br/>All problems He has solved.<br/>Thank You Savior, precious Savior!<br/>Your sins He took away;<br/>Don’t wait another day.<br/>Precious Savior, full of mercy!<br/>',NULL,86891,5);
INSERT INTO stanza VALUES('NS10038','chorus','He took your sins away;<br/>Don’t wait another day.<br/>Call on Jesus, He will save you!<br/>Impossible it seems.<br/>But nothing’s hard for Him.<br/>Call on Jesus, He will save you!<br/>',NULL,86892,6);
INSERT INTO stanza VALUES('NS10038','4','He is the Spirit too<br/>So He can get in you.<br/>Precious Spirit, call on Jesus!<br/>Obey your being to Him,<br/>Just call and let Him in.<br/>Oh Lord, Jesus, breathe in Jesus!<br/>',NULL,86893,7);
INSERT INTO stanza VALUES('NS10038','chorus','He’s very close to you.<br/>There’s nothing you must do<br/>But call on Jesus, He’s the Spirit!<br/>The Spirit as the air,<br/>Just call He’s everywhere.<br/>Oh Lord Jesus, breathe in Jesus!<br/>',NULL,86894,8);
INSERT INTO stanza VALUES('NS10038','5','My thoughts be filled with You.<br/>My heart just loving You.<br/>Fill me Jesus, lovely Jesus.<br/>My final choice is You,<br/>Just You alone will do.<br/>Fill me Jesus, lovely Jesus!<br/>',NULL,86895,9);
INSERT INTO stanza VALUES('NS10038','chorus','I call upon Your name.<br/>Your Person I would gain,<br/>Oh Lord Jesus, precious Jesus!<br/>I call upon Your name.<br/>Your Person I would gain,<br/>Oh Lord Jesus, precious Jesus!<br/>',NULL,86896,10);
INSERT INTO stanza VALUES('NS10038','6','My words just can’t express...<br/>Dear Lord, You’re just the best,<br/>Lovely Jesus, precious Jesus!<br/>No other one will do.<br/>My love, I just want You.<br/>Lovely Jesus, precious Jesus!<br/>',NULL,86897,11);
INSERT INTO stanza VALUES('NS10038','chorus','He’s far beyond my dreams,<br/>Heaven and everything.<br/>Lovely Jesus, precious Jesus!<br/>He’s far above my dreams,<br/>Surpassing everything.<br/>Lovely Jesus, precious Jesus!<br/>',NULL,86898,12);
INSERT INTO stanza VALUES('NS10039','1','Jesus, Jesus, Jesus,<br/>There’s no one like You.<br/>Jesus, Jesus, Jesus,<br/>I just love You.<br/>',NULL,86899,1);
INSERT INTO stanza VALUES('NS10039','chorus','I love You, Jesus, precious Lord,<br/>No one’s like You.<br/>I love You, Jesus, Wonderful,<br/>No one’s like You.<br/>',NULL,86900,2);
INSERT INTO stanza VALUES('NS10039','chorus','No one is like You, dearest One.<br/>You are the most precious Person.<br/>Jesus, the most desired One!<br/>',NULL,86901,3);
INSERT INTO stanza VALUES('NS10039','2','Bridegroom, Bridegroom, Bridegroom,<br/>Your bride is calling You.<br/>Bridegroom, Bridegroom, Bridegroom,<br/>Your bride just wants You!<br/>',NULL,86902,4);
INSERT INTO stanza VALUES('NS10039','chorus','Most pleasant Person, dear Bridegroom,<br/>Come quickly soon!<br/>Most pleasant Person, dear Bridegroom,<br/>Come quickly soon!<br/>',NULL,86903,5);
INSERT INTO stanza VALUES('NS10039','chorus','You are the most pleasant Person.<br/>Your bride is waiting, dear Bridegroom.<br/>Bridegroom, we’re calling, please come soon!<br/>',NULL,86904,6);
INSERT INTO stanza VALUES('NS10039','3','Jesus, Jesus, Jesus, the most beautiful!<br/>Jesus, Jesus, Jesus, the most wonderful!<br/>',NULL,86905,7);
INSERT INTO stanza VALUES('NS10039','chorus','One look at You, Oh glorious One,<br/>My heart You’ve won.<br/>Your touch, dear Lord is wonderful!<br/>You’re wonderful!<br/>',NULL,86906,8);
INSERT INTO stanza VALUES('NS10039','chorus','Jesus, the fairest of the fair!<br/>No one, dear Lord can e’er compare.<br/>Jesus, the fairest of the fair!<br/>',NULL,86907,9);
INSERT INTO stanza VALUES('NS10040','1','Lord, how long, dear Bridegroom,<br/>’Til You come, Lord, how soon?<br/>Don’t delay for that coming day, coming day.<br/>Grant me, Lord, to be filled<br/>With You, Lord, every day.<br/>Dearest Lord, take me all the way.<br/>',NULL,86908,1);
INSERT INTO stanza VALUES('NS10040','chorus','Come, Lord Jesus,<br/>Please come, dear Bridegroom;<br/>Precious One, come soon, come soon.<br/>Lord, consume me!<br/>Oh Lord, don’t let me stray,<br/>Faithful to You all the way.<br/>',NULL,86909,2);
INSERT INTO stanza VALUES('NS10040','2','Lord, make home in all my heart<br/>In my secret, deepest parts,<br/>Hidden, Lord, and reserved for You, for You.<br/>You would be preeminent<br/>In all things and all events,<br/>Possessed by Thee to this extent.<br/>',NULL,86910,3);
INSERT INTO stanza VALUES('NS10040','3','In my prayer and deepest plea<br/>In my spirit always be<br/>Saturated and soaked with Thee, with Thee.<br/>This would be my life daily.<br/>Every hour expecting Thee,<br/>This I pray, Lord, desperately!<br/>',NULL,86911,4);
INSERT INTO stanza VALUES('NS10040','4','The universe, in it we see,<br/>In the sweetest touch of Thee,<br/>You’re my choice and my destiny, destiny.<br/>Lord, whate’er the price may be,<br/>Lord, Amen, let it be!<br/>Oh, my Love, please come back quickly!<br/>',NULL,86912,5);
INSERT INTO stanza VALUES('NS10040','5','In Your love I am constrained.<br/>What’s within, I can’t contain.<br/>Lord, I can’t any more restrain, restrain.<br/>In Your love, I’ll pour on Thee.<br/>And the church, Your Bride to be,<br/>This my choice voluntarily.<br/>',NULL,86913,6);
INSERT INTO stanza VALUES('NS10041','1','Pursue Him and know Him; be found in Him.<br/>Count all things loss for Him.<br/>Just gain Him, obtain Him; lay hold of Him.<br/>It’s Christ the central vision.<br/>',NULL,86914,1);
INSERT INTO stanza VALUES('NS10041','chorus','Forgetting the things which are behind,<br/>Press on, pursue with this mind.<br/>By any means each hour now redeem;<br/>Stretch forth, lay hold of Him.<br/>',NULL,86915,2);
INSERT INTO stanza VALUES('NS10041','2','Pursue Him and seize Him, Christ the supreme.<br/>Just love this precious Person.<br/>Forgetting and leaving all other things,<br/>Love Him with your whole being.<br/>',NULL,86916,3);
INSERT INTO stanza VALUES('NS10041','3','Christ now is my center and reality,<br/>My life for eternity.<br/>All things are just dung compared to Him,<br/>So love and just gain Him!<br/>',NULL,86917,4);
INSERT INTO stanza VALUES('NS10042','1','The love of God and the grace of Christ<br/>And fellowship of the Holy Spirit<br/>Be with you, be with you all,<br/>Be with you all, be with you all.<br/>',NULL,86918,1);
INSERT INTO stanza VALUES('NS10042','2','From the throne of our God and the Lamb<br/>Flows a river of water of life,<br/>Bright as crystal, reaching man.<br/>',NULL,86919,2);
INSERT INTO stanza VALUES('NS10043','1','The Triune God: a mystery—<br/>God is one and He’s three.<br/>Oh, Triune God, You’re wonderful!<br/>You’re wonder- wonderful!<br/>The Triune God: a mystery—<br/>God is one and He’s three.<br/>Oh, Triune God, You’re marvelous!<br/>You’re marvel- marvelous!<br/>',NULL,86920,1);
INSERT INTO stanza VALUES('NS10043','chorus','(Brothers)<br/>A child is born to us,<br/>A son is giv’n to us,<br/>The child, the mighty God,<br/>The Son and Father one.<br/>',NULL,86921,2);
INSERT INTO stanza VALUES('NS10043','chorus','(Sisters)<br/>The mighty God is He,<br/>Eternal Father, He,<br/>His name is Wonderful,<br/>A wonderful Person.<br/>',NULL,86922,3);
INSERT INTO stanza VALUES('NS10043','2','The Lord is now the Spirit,<br/>A wondrous mystery!<br/>Christ, the life-giving Spirit,<br/>Has entered into me!<br/><br/>The Lord is now the Spirit,<br/>Oh this is glorious!<br/>Christ, the life-giving Spirit,<br/>Has entered into us!<br/>',NULL,86923,4);
INSERT INTO stanza VALUES('NS10043','chorus','(Brothers)<br/>The last Adam became<br/>The Lord is the Spirit,<br/>The last Adam became<br/>Christ is the Lord Spirit.<br/>',NULL,86924,5);
INSERT INTO stanza VALUES('NS10043','chorus','(Sisters)<br/>The life-giving Spirit!<br/>The all-inclusive Christ<br/>The life-giving Spirit!<br/>He’s now indwelling us!<br/>',NULL,86925,6);
INSERT INTO stanza VALUES('NS10043','3','Our Father God, the source;<br/>God, the Son, has reached me.<br/>God as the Spirit’s flowing free.<br/>He flowed God into me!<br/><br/>Our Father God, the source;<br/>God, the Son, is the course.<br/>God as the Spirit entered me!<br/>’Tis the greatest mystery!<br/>',NULL,86926,7);
INSERT INTO stanza VALUES('NS10043','chorus','(Brothers)<br/>The Triune God in me:<br/>Oh this is glorious!<br/>The Triune God in me:<br/>Oh this is marvelous!<br/>',NULL,86927,8);
INSERT INTO stanza VALUES('NS10043','chorus','(Sisters)<br/>The greatest mystery!<br/>The Triune God in us!<br/>The greatest mystery!<br/>The Triune God in us!<br/>',NULL,86928,9);
INSERT INTO stanza VALUES('NS10044','1','Lord Jesus, I love You,<br/>No other one for me will do.<br/>I love You, just love You.<br/>Without You, Lord, I am through.<br/>',NULL,86929,1);
INSERT INTO stanza VALUES('NS10044','chorus','No other one for me will do.<br/>My heart is drawn, I just love You.<br/>I just love You, dear Lord.<br/>',NULL,86930,2);
INSERT INTO stanza VALUES('NS10044','2','As mercy, You reached me.<br/>You laid aside Your glory.<br/>You’re God, Lord, the Almighty,<br/>Yes You became a slave for me.<br/>',NULL,86931,3);
INSERT INTO stanza VALUES('NS10044','chorus','What kind of love You have for man,<br/>Beyond our power to comprehend!<br/>I love You, Lord Jesus.<br/>',NULL,86932,4);
INSERT INTO stanza VALUES('NS10044','3','I’m evil and fallen.<br/>My nature, Lord, is just sin.<br/>You’re righteous and holy.<br/>All that You are was condemning me.<br/>',NULL,86933,5);
INSERT INTO stanza VALUES('NS10044','chorus','What made You Lord to die for me?<br/>You joined man’s race and took my place,<br/>Redeeming us Jesus.<br/>',NULL,86934,6);
INSERT INTO stanza VALUES('NS10044','4','You died, Lord, on Calvary.<br/>Your blood is flowing now for me.<br/>Your blood, Lord, is precious.<br/>O, what a price You paid for us!<br/>',NULL,86935,7);
INSERT INTO stanza VALUES('NS10044','chorus','No tongue or pen can ever tell:<br/>Your mercy reached me down in hell.<br/>You reached me, Lord Jesus.<br/>',NULL,86936,8);
INSERT INTO stanza VALUES('NS10045','1','Abba, Father, hear our cry,<br/>Mingled spirit deep within.<br/>',NULL,86937,1);
INSERT INTO stanza VALUES('NS10045','chorus','Abba, Father,<br/>Abba, Father.<br/>',NULL,86938,2);
INSERT INTO stanza VALUES('NS10045','2','Thank You, Father, for sending Him;<br/>The Spirit of Your Son Who cries within.<br/>',NULL,86939,3);
INSERT INTO stanza VALUES('NS10045','3','Oh! How sweet is Abba’s Name<br/>From our spirit through our heart.<br/>',NULL,86940,4);
INSERT INTO stanza VALUES('NS10045','4','Every moment this mingled cry;<br/>To Your Beloved we’re joined thereby.<br/>',NULL,86941,5);
INSERT INTO stanza VALUES('NS10045','5','Day by day, this cry so new;<br/>In Your Son we come back to You.<br/>',NULL,86942,6);
INSERT INTO stanza VALUES('NS10045','6','In Your bosom here we’ll stay,<br/>In Your Son and never stray.<br/>',NULL,86943,7);
INSERT INTO stanza VALUES('NS10046','1','I bow my knees unto the Father<br/>That He would grant you<br/>To be strengthened with pow’r through His Spirit<br/>Into the inner man.<br/>I bow my knees unto the Father<br/>That He would grant you<br/>To be strengthened with pow’r through His Spirit<br/>Into the inner man.<br/>To be strengthened with pow’r through His Spirit<br/>Into the inner man.<br/>Into the inner man.<br/>According to the riches of His glory<br/>That Christ may make His home in your hearts through faith.<br/>According to the riches of His glory<br/>That Christ may make His home in your hearts through faith.<br/>May make His home in your heart through faith, through faith.<br/>',NULL,86944,1);
INSERT INTO stanza VALUES('NS10047','1','Lord, I have been running so long.<br/>Now, Lord, I admit I was wrong.<br/>Oh Lord, finally my heart has been won by You.<br/>',NULL,86945,1);
INSERT INTO stanza VALUES('NS10047','chorus','I love You, Lord. (I love You, Lord.)<br/>I need You, Lord. (I need You, Lord.)<br/>I love You, Lord. I need You, Lord.<br/>I want You, Lord, to be my Lord right now.<br/>',NULL,86946,2);
INSERT INTO stanza VALUES('NS10047','2','I’ve committed so many sins.<br/>Lord, how I’ve heaped up my offense!<br/>I pray, now in Your precious blood cleanse me, Lord.<br/>',NULL,86947,3);
INSERT INTO stanza VALUES('NS10047','chorus','I love You, Lord. (I love You, Lord).<br/>I need You, Lord. (I need You, Lord).<br/>I love You, Lord. I need You, Lord.<br/>I want You, Lord, to cleanse me, Lord right now.<br/>',NULL,86948,4);
INSERT INTO stanza VALUES('NS10047','3','Lord, I am unworthy indeed.<br/>You’re so full of mercy, I see,<br/>To save one so rebellious as me, my Lord.<br/>',NULL,86949,5);
INSERT INTO stanza VALUES('NS10047','chorus','I love You, Lord. (I love You, Lord).<br/>I need You, Lord. (I need You, Lord).<br/>I love You, Lord. I need You, Lord.<br/>I want You, Lord, to save me, Lord right now.<br/>',NULL,86950,6);
INSERT INTO stanza VALUES('NS10047','4','Lord, You are the most precious One.<br/>Oh, You are God’s dear beloved Son<br/>To me such a rich treasure become, dear Lord.<br/>',NULL,86951,7);
INSERT INTO stanza VALUES('NS10047','chorus','I love You, Lord. (I love You, Lord).<br/>I need You, Lord. (I need You, Lord).<br/>I love You, Lord. I need You, Lord.<br/>I want You, Lord, to be my Lord right now.<br/>',NULL,86952,8);
INSERT INTO stanza VALUES('NS10047','5','Lord Jesus, I want to have You.<br/>Lord, there is none else that will do.<br/>Lord, come dwell now in me; come into me, Lord.<br/>',NULL,86953,9);
INSERT INTO stanza VALUES('NS10047','chorus','I love You, Lord. (I love You, Lord).<br/>I need You, Lord. (I need You, Lord).<br/>I love You, Lord. I need You, Lord.<br/>I want You, Lord, to dwell in me right now.<br/>',NULL,86954,10);
INSERT INTO stanza VALUES('NS10047','6','Lord, come now and live within me.<br/>I open my heart’s room to be<br/>Indwelt in every part, Lord, only by You.<br/>',NULL,86955,11);
INSERT INTO stanza VALUES('NS10047','chorus','I love You, Lord. (I love You, Lord).<br/>I need You, Lord. (I need You, Lord).<br/>I love You, Lord. I need You, Lord.<br/>I want You, Lord, to dwell in me right now.<br/>',NULL,86956,12);
INSERT INTO stanza VALUES('NS10047','7','Lord, all that I am I give You.<br/>Take all that I have just for You.<br/>Lord, spoil everything else; I want You alone.<br/>',NULL,86957,13);
INSERT INTO stanza VALUES('NS10047','chorus','I love You, Lord. (I love You, Lord).<br/>I need You, Lord. (I need You, Lord).<br/>I love You, Lord. I need You, Lord.<br/>I want You, Lord; I give myself to You.<br/>',NULL,86958,14);
INSERT INTO stanza VALUES('NS10048','1','The Lord is my strength and my song.<br/>He’s become my salvation.<br/>The Lord is my strength and my song.<br/>He’s become my salvation.<br/>The Lord is my strength and my song.<br/>He’s become my salvation.<br/>The Lord is my strength and my song.<br/>He’s become my salvation.<br/>',NULL,86959,1);
INSERT INTO stanza VALUES('NS10048','chorus','He is my God, and I will praise Him.<br/>My father’s God, and I’ll exalt Him.<br/>He is my God, and I will praise Him.<br/>My father’s God, and I’ll exalt Him.<br/>',NULL,86960,2);
INSERT INTO stanza VALUES('NS10048','2','Thou in Thy mercy<br/>Hast led forth Thy people,<br/>Led forth Thy people,<br/>Which Thou hast redeemed.<br/>Thou hast guided them,<br/>Guided them in Thy strength<br/>Unto Thy holy habitation.<br/>',NULL,86961,3);
INSERT INTO stanza VALUES('NS10049','1','Jesus is Jehovah the Savior.<br/>Emmanuel, He is God with us and He is the King.<br/>Baptizer, the Teacher, the Light,<br/>Healer, the Forgiver and He’s our Bridegroom.<br/>',NULL,86962,1);
INSERT INTO stanza VALUES('NS10049','chorus','He’s the Shepherd and He’s the Friend,<br/>The Wisdom and the Rest.<br/>He’s the greater Temple<br/>And the real David.<br/>',NULL,86963,2);
INSERT INTO stanza VALUES('NS10049','2','Lord! He’s the Lord of the Sabbath.<br/>Jonah and Solomon — He’s the greater One.<br/>Sower, He’s the Seed and the Feeder,<br/>Bread: the crumbs under the table He is.<br/>',NULL,86964,3);
INSERT INTO stanza VALUES('NS10049','chorus','The Christ, the Son of the living God,<br/>He’s the Rock for the church.<br/>And He is the Builder of,<br/>The Builder of the church.<br/>',NULL,86965,4);
INSERT INTO stanza VALUES('NS10049','3','Founder of the Kingdom He is.<br/>Moses and Elijah — the present One of these two.<br/>The Head of the cornerstone.<br/>The Lord, the resurrected One He is.<br/>',NULL,86966,5);
INSERT INTO stanza VALUES('NS10049','chorus','As such a One He is<br/>The One with authority,<br/>The ever-present One to His<br/>People in resurrection.<br/>',NULL,86967,6);
INSERT INTO stanza VALUES('NS10050','1','Zion is God’s habitation.<br/>Sing praises in Zion,<br/>The city of our King.<br/>Zion, the place of His choosing<br/>Where saints are rejoicing.<br/>Here God is their salvation.<br/>',NULL,86968,1);
INSERT INTO stanza VALUES('NS10050','chorus','Beautiful Zion,<br/>In elevation,<br/>The joy of our King,<br/>His satisfaction,<br/>The joy of the whole earth.<br/>',NULL,86969,2);
INSERT INTO stanza VALUES('NS10050','2','Zion: how good and how pleasant,<br/>The greatest enjoyment!<br/>It’s like the precious ointment.<br/>Zion, how good and how pleasant,<br/>In oneness we’re dwelling.<br/>The dew, oh how refreshing!<br/>',NULL,86970,3);
INSERT INTO stanza VALUES('NS10050','chorus','Beautiful Zion, in elevation.<br/>How good and how pleasant,<br/>The best enjoyment!<br/>Our oneness is just Him.<br/>',NULL,86971,4);
INSERT INTO stanza VALUES('NS10050','3','Zion: our oneness a Person,<br/>As ointment, He’s moving,<br/>As dew He is descending,<br/>Zion: our God is our dwelling,<br/>As ointment, He’s strengthening,<br/>As dew, He’s so supplying.<br/>',NULL,86972,5);
INSERT INTO stanza VALUES('NS10050','chorus','Beautiful Zion, in elevation.<br/>How good and how pleasant,<br/>Man’s satisfaction,<br/>Our dwelling is this One.<br/>',NULL,86973,6);
INSERT INTO stanza VALUES('NS10050','4','Zion: in God we’re abiding,<br/>Our oneness and living,<br/>The processed God, our all.<br/>Zion, the ultimate blessing,<br/>Of God with man mingling,<br/>The Triune God dispensing.<br/>',NULL,86974,7);
INSERT INTO stanza VALUES('NS10050','chorus','Beautiful churches, the golden lampstands.<br/>God mingling with man;<br/>His satisfaction,<br/>The ultimate consummation!<br/>',NULL,86975,8);
INSERT INTO stanza VALUES('NS10051','1','I do not know where they have laid Him.<br/>The stone is taken away from the tomb.<br/>Oh! They have taken Him away!<br/>Oh! Where is He?<br/>',NULL,86976,1);
INSERT INTO stanza VALUES('NS10051','2','Disciples came and saw the empty tomb<br/>But went away so soon to their own homes.<br/>They’re satisfied with just the facts.<br/>But where’s my Lord?<br/>',NULL,86977,2);
INSERT INTO stanza VALUES('NS10051','chorus','Where is He, my Jesus?<br/>Where is He, my Beloved?<br/>Where is He Whom my soul doth love?<br/>Jesus, my Love, I just want You.<br/>',NULL,86978,3);
INSERT INTO stanza VALUES('NS10051','3','My heart is broken from my deepest need.<br/>Don’t ask me, angels, why I’m weeping.<br/>Nothing but Jesus fills my inner being.<br/>Oh! Where’s my Love?<br/>',NULL,86979,4);
INSERT INTO stanza VALUES('NS10051','4','Someone is standing right behind me.<br/>It’s just the gardener I can barely see.<br/>Sir, if you carried Him away...<br/>Oh! Where is He?<br/>',NULL,86980,5);
INSERT INTO stanza VALUES('NS10051','chorus','Where is He my Jesus?<br/>Where is He my Beloved?<br/>Tell me where you have laid Him<br/>And I’ll carry Him away, I’ll carry Him away.<br/>',NULL,86981,6);
INSERT INTO stanza VALUES('NS10051','5','And then I heard a voice say, “Mary.“<br/>That sweetest voice that penetrated me.<br/>It is the voice of my Beloved,<br/>Jesus, my Love.<br/>',NULL,86982,7);
INSERT INTO stanza VALUES('NS10051','chorus','I have found my Jesus!<br/>I have found my Beloved!<br/>I have found Whom my soul doth love,<br/>Jesus, my love, I just love You!<br/>',NULL,86983,8);
INSERT INTO stanza VALUES('NS10051','6','But Jesus told me not to touch Him yet.<br/>He must ascend first to the Father<br/>And to My Father and your Father<br/>To My God and your God.<br/>',NULL,86984,9);
INSERT INTO stanza VALUES('NS10051','chorus','Go and tell My brothers,<br/>I ascend to the Father<br/>To My Father and your Father,<br/>And My God and your God, go tell My brothers.<br/>',NULL,86985,10);
INSERT INTO stanza VALUES('NS10052','1','Lord, keep my heart always true to You,<br/>Never backsliding, always viewing You,<br/>A heart that is pure that sees only You,<br/>A heart that loves You and treasures only You.<br/>',NULL,86986,1);
INSERT INTO stanza VALUES('NS10052','chorus','Your love constrains me to give my all to You.<br/>Lord, I can’t help it; my heart is drawn to You.<br/>Oh what a privilege! I give myself to You!<br/>I love You, Lord, dearest Lord.<br/>I love You! I just love You!<br/>',NULL,86987,2);
INSERT INTO stanza VALUES('NS10052','2','Lord, keep my love burning brightly for You,<br/>A love never dwindling always hot for You,<br/>A love, shining brighter all the way for You,<br/>A love, so fresh like the day I first touched You.<br/>',NULL,86988,3);
INSERT INTO stanza VALUES('NS10052','3','Lord, take my life, I present it to You!<br/>If I had a thousand, I’d pour all on You!<br/>Nothing withholding, my all is for You.<br/>My life and my future, dear Lord, is all for You.<br/>',NULL,86989,4);
INSERT INTO stanza VALUES('NS10053','1','Worthy is the Lamb Who has been slain to receive<br/>The power and riches and wisdom and strength<br/>And honor and glory and blessing.<br/>',NULL,86990,1);
INSERT INTO stanza VALUES('NS10053','chorus','Worthy is the Lamb<br/>Who has been slained to receive<br/>The power and riches<br/>And wisdom and the strength<br/>And honor and glory<br/>And the blessing.<br/>',NULL,86991,2);
INSERT INTO stanza VALUES('NS10053','2','Worthy is the Lamb Who has been slain to receive<br/>The power and riches and wisdom and strength<br/>And honor and glory and blessing.<br/>',NULL,86992,3);
INSERT INTO stanza VALUES('NS10053','chorus','Saints, stand as one;<br/>No one should backward turn.<br/>The battle Christ has won,<br/>By His blood we overcome,<br/>The enemy cast down<br/>For the Lamb is on the throne.<br/>',NULL,86993,4);
INSERT INTO stanza VALUES('NS10053','3','And they overcame him by the blood of the Lamb<br/>And by the word of their testimony,<br/>And they love not their soul-lives unto death.<br/>',NULL,86994,5);
INSERT INTO stanza VALUES('NS10053','chorus','Praise You, Lion-Lamb<br/>Our Captain of salvation.<br/>You have fought the battle<br/>And destroyed the Devil.<br/>You took away our sins<br/>And accomplished redemption.<br/>',NULL,86995,6);
INSERT INTO stanza VALUES('NS10053','4','Hallelujah to our Lamb God on the throne!<br/>Hallelujah Praise Him! Hallelujah<br/>Hallelujah Praise Him! Hallelujah<br/>',NULL,86996,7);
INSERT INTO stanza VALUES('NS10053','chorus','Lord, I join Your fight.<br/>For Your purpose take my rights!<br/>To You, I now respond,<br/>In this age to overcome,<br/>To the end make me fight on.<br/>Fight on, fight on, fight on!<br/>',NULL,86997,8);
INSERT INTO stanza VALUES('NS10054','1','So many times I was in weakness;<br/>I realize that was my blindness.<br/>I’m beginning to see<br/>All that the Triune God is to me.<br/>',NULL,86998,1);
INSERT INTO stanza VALUES('NS10054','2','Wasting my time looking at my poorness;<br/>Now my heart’s eyes can behold His greatness.<br/>I’m enlightened to see<br/>All of the Triune God is to me.<br/>',NULL,86999,2);
INSERT INTO stanza VALUES('NS10054','chorus','I believe, so I speak.<br/>I am strong, I have power.<br/>I believe, Oh Lord, Amen!<br/>I am strong, I have power.<br/>',NULL,87000,3);
INSERT INTO stanza VALUES('NS10054','3','All of God’s power for His creation,<br/>And all His might in incarnation,<br/>Strength to be crucified<br/>Which by the power of God was supplied.<br/>',NULL,87001,4);
INSERT INTO stanza VALUES('NS10054','4','And His great power in resurrection,<br/>He wrought in Christ, even ascension!<br/>All things He has subdued<br/>Under His feet, by power overruled.<br/>',NULL,87002,5);
INSERT INTO stanza VALUES('NS10054','5','Now in the church, in God’s transmission,<br/>All that He is, to His destination,<br/>Here constantly receive.<br/>He is dispensed to us who believe.<br/>',NULL,87003,6);
INSERT INTO stanza VALUES('NS10054','6','The Triune God is now transmitting<br/>Himself, this power, us energizing,<br/>In us He is installed;<br/>This dynamo within, the Triune God!<br/>',NULL,87004,7);
INSERT INTO stanza VALUES('NS10055','1','Thank You, Lord, You died for me.<br/>You took my place upon the tree.<br/>All my sins were laid on Thee;<br/>You bore them all away...<br/>I was just an enemy,<br/>Lost and sold to sin.<br/>But You came to shed<br/>Your blood for me,<br/>You the One with no sin!<br/>',NULL,87005,1);
INSERT INTO stanza VALUES('NS10055','2','Many plotted to kill You,<br/>Judas he betrayed You.<br/>Disciples, they forsook You,<br/>False witnesses were hired.<br/>Then Peter, he denied You,<br/>Three times in one night.<br/>An illegal trial condemned You.<br/>How we afflicted You!<br/>',NULL,87006,2);
INSERT INTO stanza VALUES('NS10055','3','They smote You with their palms,<br/>And spit into Your precious face.<br/>Buffeting and mocking,<br/>They led You away!<br/>Pilate and Herod<br/>Sent You back and forth.<br/>Then the soldiers, they scourged You<br/>And made a crown of thorns.<br/>',NULL,87007,3);
INSERT INTO stanza VALUES('NS10055','4','With a reed, they beat Your head,<br/>Pressing the thorns much deeper.<br/>Stripping You, they nailed You<br/>Up on a cross of wood.<br/>In front of You, they gambled<br/>For Your clothes and seamless coat.<br/>All the people passed, despising You.<br/>Then God forsook You too!<br/>',NULL,87008,4);
INSERT INTO stanza VALUES('NS10055','5','The two thieves on either side,<br/>As they hung, reviled You.<br/>Though You were dead, a soldier<br/>Still would pierce Your side.<br/>Blood and water poured out,<br/>Out from Your broken heart.<br/>That same blood and water saved me!<br/>Lord, how I love You!<br/>',NULL,87009,5);
INSERT INTO stanza VALUES('NS10055','6','When I see the price You paid,<br/>You chose to pay my every debt!<br/>Willingly, You bore such shame<br/>And tasted death for me!<br/>How could I ever love the world<br/>That crucified You, dear One?<br/>I am not my own, bought with a price.<br/>I give myself to You!<br/>',NULL,87010,6);
INSERT INTO stanza VALUES('NS10056','1','The divine dispensing starts with the Father.<br/>He selected us ’ere the world began.<br/>Predestinated to be His sons<br/>Through His rich life dispensing.<br/>',NULL,87011,1);
INSERT INTO stanza VALUES('NS10056','2','The Son accomplished the Father’s purpose<br/>By His redemption of fallen man<br/>Through His own blood and according to<br/>The riches of God’s grace.<br/>',NULL,87012,2);
INSERT INTO stanza VALUES('NS10056','3','The Spirit’s sealing, the application<br/>It works within us to permeate<br/>And transform us with God’s element<br/>Unto our full redemption.<br/>',NULL,87013,3);
INSERT INTO stanza VALUES('NS10056','4','The Spirit’s pledging is just a foretaste<br/>Of our divine inheritance.<br/>It guarantees the full taste of God<br/>As our eternal portion.<br/>',NULL,87014,4);
INSERT INTO stanza VALUES('NS10056','5','We thank You, Father, Son, and Spirit<br/>For all the blessings we have received.<br/>We’ve given nothing, yet You give all.<br/>How worthy of our praise!<br/>',NULL,87015,5);
INSERT INTO stanza VALUES('NS10057','1','Where have you laid Him, my Jesus?<br/>Where have you put Him, my precious Lord?<br/>There are His grave clothes, but He’s not there.<br/>Where is my Jesus, my lovely One, where is He?<br/>',NULL,87016,1);
INSERT INTO stanza VALUES('NS10057','chorus','Lord, I can’t forget<br/>Since the day we first met.<br/>All my heart belongs to You.<br/>I just love You, just You,<br/>Just love You.<br/>',NULL,87017,2);
INSERT INTO stanza VALUES('NS10057','2','Jesus, my dear Lord, I love You.<br/>I can’t go on Lord, without You.<br/>I’m sick of love, my soul has failed;<br/>I need You Jesus, my Beloved, I love You.<br/>',NULL,87018,3);
INSERT INTO stanza VALUES('NS10057','3','Mary, My seeker, I am alive.<br/>Stop, do not touch Me, as I have not<br/>Yet ascended to the Father,<br/>For this freshness is for the Father’s enjoyment.<br/>',NULL,87019,4);
INSERT INTO stanza VALUES('NS10057','4','My dear Rabboni, my heart’s desire,<br/>You have risen out of the grave.<br/>O Lord, I love You, my dearest One.<br/>You’ve truly risen from among the dead.<br/>',NULL,87020,5);
INSERT INTO stanza VALUES('NS10057','chorus','Dear Rabboni,<br/>Lord, I can’t believe it’s You!<br/>I don’t know how this could be<br/>But I enjoy You here.<br/>I love You!<br/>',NULL,87021,6);
INSERT INTO stanza VALUES('NS10057','5','O Lord, my heart is filled with ecstasy<br/>In resurrection, to be here with Thee.<br/>I am elated, beside myself.<br/>Jesus, I’ll love You with all my heart, forever.<br/>',NULL,87022,7);
INSERT INTO stanza VALUES('NS10057','6','Go tell my brothers you have seen Me.<br/>Tell them the words which I speak to you:<br/>I must ascend to My Father<br/>And to your Father, and to My God<br/>&nbsp;&nbsp; and to your God.<br/>',NULL,87023,8);
INSERT INTO stanza VALUES('NS10057','chorus','I have found my Love,<br/>He has risen from the dead.<br/>Now our Jesus is alive.<br/>I have seen Him, seen Him!<br/>I love Him!<br/>',NULL,87024,9);
INSERT INTO stanza VALUES('NS10057','7','Jesus, we love You with all our heart.<br/>Our Love, we need You so desperately.<br/>O Lord, we love You immensely.<br/>We will be loving You for all eternity.<br/>',NULL,87025,10);
INSERT INTO stanza VALUES('NS10058','1','Before we were saved, we were alone.<br/>Though so many others were with us,<br/>In fact we were still by ourselves, alone.<br/>Once we got saved we could never again<br/>&nbsp;&nbsp;&nbsp;&nbsp;Be alone by ourselves;<br/>Someone has come, now wherever we go<br/>&nbsp;&nbsp;&nbsp;&nbsp;And whatever we do,<br/>&nbsp;&nbsp;&nbsp;&nbsp;Jesus is here.<br/>Always this other Person stays with us.<br/>',NULL,87026,1);
INSERT INTO stanza VALUES('NS10058','2','Sometimes we are pleased that He remains.<br/>We love Him and cherish Him, yet there<br/>Are times that we secretly wish He’d go.<br/>This One, however our Christ we could<br/>&nbsp;&nbsp;&nbsp;&nbsp;Never escape or evade.<br/>Though we would tell Him to just go away<br/>&nbsp;&nbsp;&nbsp;&nbsp;And to leave us alone,<br/>&nbsp;&nbsp;&nbsp;&nbsp;Jesus won’t leave.<br/>It is impossible to be alone.<br/>',NULL,87027,2);
INSERT INTO stanza VALUES('NS10058','3','We’re single no more; now we are two.<br/>Formerly we were just one by<br/>Ourselves, but now Christ wants to be our life.<br/>Once we got saved we could never again<br/>&nbsp;&nbsp;&nbsp;&nbsp;Be alone by ourselves;<br/>Someone has come, now wherever we go<br/>&nbsp;&nbsp;&nbsp;&nbsp;And whatever we do,<br/>&nbsp;&nbsp;&nbsp;&nbsp;Jesus is here.<br/>Always this other Person stays with us.<br/>He is our life.<br/>',NULL,87028,3);
INSERT INTO stanza VALUES('NS10059','1','I love You, Lord Jesus,<br/>You’re worthy of my life.<br/>I relinquish all control<br/>And give You every right.<br/>Only You, only You,<br/>You’re the One attracting me!<br/>In all things, nothing may I see<br/>Or want but You!<br/>',NULL,87029,1);
INSERT INTO stanza VALUES('NS10059','2','Every concept, all desires,<br/>&nbsp;&nbsp;&nbsp;&nbsp;I now forsake for You!<br/>Shine on all that I can’t see,<br/>&nbsp;&nbsp;&nbsp;&nbsp;On all that is not You!<br/>Live Your life, live Your life.<br/>I’ve been crucified with You.<br/>Every moment, I would live in oneness,<br/>&nbsp;&nbsp;&nbsp;&nbsp;Lord, with You!<br/>',NULL,87030,2);
INSERT INTO stanza VALUES('NS10059','3','When I struggle, grant me grace<br/>&nbsp;&nbsp;&nbsp;&nbsp;To turn my eyes on You!<br/>Keep my heart so close to You,<br/>&nbsp;&nbsp;&nbsp;&nbsp;My love, so fresh and new!<br/>Come in, Lord! Come in more!<br/>I would seek none else but You!<br/>All my life, my love, my all, I pour it,<br/>&nbsp;&nbsp;&nbsp;&nbsp;Lord, on You!<br/>',NULL,87031,3);
INSERT INTO stanza VALUES('NS10060','1','The Son with the Father by the Spirit—<br/>O what a mystery!<br/>The fulness of all the Godhead<br/>Dwells in Him bodily.<br/>',NULL,87032,1);
INSERT INTO stanza VALUES('NS10060','chorus','Wonderful One, Son with the Father,<br/>Wonderful One, Son by the Spirit,<br/>Wonderful Jesus Christ,<br/>Wonderful Triune, Wonderful Triune God.<br/>',NULL,87033,2);
INSERT INTO stanza VALUES('NS10060','2','The Son with the Father by the Spirit,<br/>Conceived in a virgin’s womb<br/>The issue: a God-man, a wonderful Person,<br/>Jesus divine and human.<br/>',NULL,87034,3);
INSERT INTO stanza VALUES('NS10060','chorus','Wonderful One, Son with the Father,<br/>Wonderful One, Son by the Spirit,<br/>Wonderful Jesus Christ,<br/>Wonderful Triune, Wonderful Triune God.<br/>',NULL,87035,4);
INSERT INTO stanza VALUES('NS10060','3','This man in perfection chose God as His living;<br/>He lived the life of God.<br/>The sin, world, and Satan could not penetrate Him;<br/>Jesus had sinless blood.<br/>',NULL,87036,5);
INSERT INTO stanza VALUES('NS10060','chorus','Humanity, His blood has cleansed me.<br/>Divinity, my guarantee.<br/>His sinless blood cleansed me.<br/>God’s now my guaran—, God’s now my guarantee.<br/>',NULL,87037,6);
INSERT INTO stanza VALUES('NS10060','4','His flesh without sin joined man’s flesh full of sin<br/>And this trapped Satan.<br/>Man’s flesh, sin and Satan were hanging upon Him<br/>O what a termination!<br/>',NULL,87038,7);
INSERT INTO stanza VALUES('NS10060','chorus','Terminating, the old creation,<br/>Penetrating, flesh, sin and Satan.<br/>O what a promised seed!<br/>He crushed the Devil’s, He crushed the Devil’s head.<br/>',NULL,87039,8);
INSERT INTO stanza VALUES('NS10060','5','And in resurrection, this wonderful Person<br/>The Spirit He became.<br/>The Spirit right now is the Son with the Father<br/>To be the consummation.<br/>',NULL,87040,9);
INSERT INTO stanza VALUES('NS10060','chorus','Wonderful One, life-giving Spirit!<br/>Son has become the consummation.<br/>Son with the Father, He<br/>As Spirit dwells in, as Spirit dwells in me.<br/>',NULL,87041,10);
INSERT INTO stanza VALUES('NS10060','6','And in His ascension, this wonderful Person,<br/>This man is on God’s throne.<br/>The highest position, to Him it was given,<br/>He’s ruling and reigning.<br/>',NULL,87042,11);
INSERT INTO stanza VALUES('NS10060','chorus','As Lord of lords and King of kings,<br/>The highest name to Jesus given.<br/>This man is on God’s throne.<br/>Most wonderful, most wonderful Person!<br/>',NULL,87043,12);
INSERT INTO stanza VALUES('NS10060','7','And in His enthronement as Head over all things<br/>The processed God is He,<br/>Dispensing Himself as the life-giving Spirit,<br/>Producing His Body.<br/>',NULL,87044,13);
INSERT INTO stanza VALUES('NS10060','chorus','The Triune God is not for doctrine.<br/>The Trinity is for dispensing.<br/>He’s now dispensing<br/>And we’re enjoying, and we’re enjoying Him.<br/>',NULL,87045,14);
INSERT INTO stanza VALUES('NS10061','1','A certain man was going down<br/>From Jerusalem to Jericho,<br/>Getting farther away from God;<br/>To this place of curse he’d go.<br/>',NULL,87046,1);
INSERT INTO stanza VALUES('NS10061','2','And as he went, among the robbers he fell<br/>Who stripped and beat him ’til he bled,<br/>And, having taken everything that he owned,<br/>They left him lying there half dead.<br/>',NULL,87047,2);
INSERT INTO stanza VALUES('NS10061','3','A certain priest was also going down,<br/>On that same road to Jericho.<br/>He saw him and passed on the opposite side.<br/>A Levite did the same also.<br/>',NULL,87048,3);
INSERT INTO stanza VALUES('NS10061','chorus','You know this man who was going down,<br/>This man is me; this man is you,<br/>Who living in our fallen life away from God<br/>Were beaten sore and bled from many wounds.<br/>',NULL,87049,4);
INSERT INTO stanza VALUES('NS10061','4','We were stripped of all that we should have:<br/>Our virtue, honor, righteousness.<br/>We could not stand upright nor hold onto life;<br/>Toward God: no boldness nor access.<br/>',NULL,87050,5);
INSERT INTO stanza VALUES('NS10061','5','Religious ones observing our poor estate<br/>Being the same could be no help.<br/>They passed us by, not daring to come close.<br/>We only heard we’d go to hell.<br/>',NULL,87051,6);
INSERT INTO stanza VALUES('NS10061','chorus','As sinners under the law condemned,<br/>Which left us beaten and disgraced, <br/>We all were robbed and dying from so many hurts,<br/>From small transgressions to our sins so great.<br/>',NULL,87052,7);
INSERT INTO stanza VALUES('NS10061','chorus','But a certain Good Samaritan, <br/>Despised, of Whom they said,<br/>“Don’t give me Jesus!“<br/>Bound up all our wounds,<br/>Pouring oil and wine upon them,<br/>Brought us to the inn and said,<br/>“Take care of him.”<br/>',NULL,87053,8);
INSERT INTO stanza VALUES('NS10061','1','He had to take a journey to come down<br/>Just to reach us.<br/>Though God, He was so willing to become <br/>A human babe.<br/>He came through human living,<br/>Observed our dire condition,<br/>Then, moved with deep compassion,<br/>He died and rose to save!<br/>',NULL,87054,9);
INSERT INTO stanza VALUES('NS10061','2','He came and bound our wounds up; <br/>He healed these damaged persons.<br/>He poured in oil and wine—<br/>His Spirit and His life divine.<br/>He placed us on His donkey&nbsp;&nbsp;<br/>To carry us so lowly,<br/>And brought us to the church life <br/>With blessing for our care.<br/>',NULL,87055,10);
INSERT INTO stanza VALUES('NS10061','3','We love this dear Man-Savior, <br/>Divine One, fully human<br/>Whose tender care, so merciful <br/>And bountiful to save<br/>Condemned and dying sinners, <br/>Reveals the highest standard<br/>Of His morality seen in His precious,&nbsp;&nbsp;<br/>Saving grace.<br/>',NULL,87056,11);
INSERT INTO stanza VALUES('NS10061','chorus','“Take care...<br/>And whatever you spend in addition on him <br/>When I return, I will repay you.”<br/>',NULL,87057,12);
INSERT INTO stanza VALUES('NS10062','1','He who is joined to the Lord is one spirit.<br/>Our life is a life that’s in organic union.<br/>As a branch is in the vine,<br/>Grafted, His life and mine intertwine.<br/>Lord, I am joined to You!<br/>',NULL,87058,1);
INSERT INTO stanza VALUES('NS10062','chorus','One spirit with You;<br/>One spirit, not two.<br/>Lord, we are joined to You:<br/>One spirit... with You.<br/>',NULL,87059,2);
INSERT INTO stanza VALUES('NS10062','2','Through resurrection the Lord is now the Spirit.<br/>Our spirit by Him has been regenerated.<br/>The Lord, the Spirit, mingling<br/>With our spirit, is the most wondrous thing.<br/>Our spirit’s mingled, Lord!<br/>',NULL,87060,3);
INSERT INTO stanza VALUES('NS10062','3','Do you not know that our bodies<br/>&nbsp;&nbsp;&nbsp;&nbsp;are Christ’s members?<br/>This body’s a temple of the Holy Spirit<br/>Who, from God, is now inside,<br/>Owning us that God may be glorified.<br/>Lord, we’ve been bought by You!<br/>',NULL,87061,4);
INSERT INTO stanza VALUES('NS10062','4','We are united with Christ in our spirit.<br/>He dwells within us<br/>&nbsp;&nbsp;&nbsp;&nbsp;and makes His home in our heart,<br/>To our body giving life,<br/>Purified to be a member of Christ;<br/>Our every part is Christ!<br/>',NULL,87062,5);
INSERT INTO stanza VALUES('NS10063','1','Oh Lord, break through.<br/>Lord, gain in me.<br/>Lord, I want You my all to be.<br/>Oh Lord, break through.<br/>Lord, gain in me.<br/>Oh Lord, replace me totally.<br/>',NULL,87063,1);
INSERT INTO stanza VALUES('NS10063','chorus','Lord, I surrender<br/>My all to You.<br/>Right now I open<br/>To let You flow through.<br/>',NULL,87064,2);
INSERT INTO stanza VALUES('NS10063','2','I open now,<br/>With all my heart.<br/>Lord, more and more possess each part.<br/>Oh Lord, I pray<br/>Subdue my soul.<br/>Until You have the full control.<br/>',NULL,87065,3);
INSERT INTO stanza VALUES('NS10063','3','Oh Lord, make home<br/>In all my heart.<br/>Lord, saturate and fill each part.<br/>Oh Lord, make home<br/>In all our heart.<br/>Lord, constitute Your counterpart.<br/>',NULL,87066,4);
INSERT INTO stanza VALUES('NS10063','4','Lord, I believe<br/>You can get through.<br/>I give myself again to You.<br/>Together we lay hold of You.<br/>’Til we are Your expression true.<br/>',NULL,87067,5);
INSERT INTO stanza VALUES('NS10063','chorus','Lord, we would apprehend with all the saints:<br/>Your height and Your depth,<br/>Your breadth and length.<br/>And as we know Your love,<br/>You will express Yourself through all of us<br/>As Your fullness.<br/>',NULL,87068,6);
INSERT INTO stanza VALUES('NS10064','1','It is God’s commandment and desire<br/>That His people call on Him<br/>And it is the joyful way to drink<br/>From the fount of God’s salvation.<br/>Yes, this is a joyful way<br/>To delight oneself in Him.<br/>God becomes our enjoyment<br/>Just by calling on His precious name.<br/>',NULL,87069,1);
INSERT INTO stanza VALUES('NS10064','chorus','Calling Him is not a new practice<br/>In the New Testament.<br/>It began way back in Genesis,<br/>And throughout the Old Testament.<br/>Enosh, Job, and Abraham—<br/>All these ones called on Him.<br/>Moses, Samuel, and David—<br/>And many others did the same.<br/>',NULL,87070,2);
INSERT INTO stanza VALUES('NS10064','3','It is such a jubilant practice<br/>That Joel prophesied.<br/>And this was fulfilled at Pentecost,<br/>So Peter testified:<br/>All who call upon the name<br/>Of the Lord shall be saved.<br/>All who call upon the name<br/>Of the Lord Jesus shall be saved.<br/>',NULL,87071,3);
INSERT INTO stanza VALUES('NS10064','4','God outpoured His Spirit on all flesh<br/>For the application<br/>Of His rich salvation to all men,<br/>But we must call upon Him.<br/>Calling brings the Jubilee;<br/>Jesus comes to you and me.<br/>Calling sets the captives free;<br/>We’re enjoying God in liberty.<br/>',NULL,87072,4);
INSERT INTO stanza VALUES('NS10064','5','Calling was a major practice then<br/>By the early Christians.<br/>It became a popular sign<br/>Of Christ’s believers then.<br/>Yes, this is a joyful way<br/>To delight oneself in Him.<br/>God becomes enjoyable<br/>Just by calling on His precious name.<br/>',NULL,87073,5);
INSERT INTO stanza VALUES('NS10064','6','Calling is opposed as it was then<br/>By the camp of religion.<br/>But His witnesses kept calling Him:<br/>They weren’t stopped by opposition.<br/>We must be like Stephen then;<br/>Jesus was his everything.<br/>Even while they martyred him,<br/>He was calling on the highest name.<br/>',NULL,87074,6);
INSERT INTO stanza VALUES('NS10065','1','Lord, I love You more and more each day.<br/>Lord, I love You more this very day.<br/>I can’t live without You anymore.<br/>I can’t make it like I did before.<br/>',NULL,87075,1);
INSERT INTO stanza VALUES('NS10065','2','Oh, those years when I was void of You.<br/>Lord, You rescued me when I was through.<br/>When I reminisce those other years,<br/>Emptiness, heartaches, and many tears.<br/>',NULL,87076,2);
INSERT INTO stanza VALUES('NS10065','chorus','Lord, I do love You more everyday.<br/>Lord, I do love You much more this very day.<br/>',NULL,87077,3);
INSERT INTO stanza VALUES('NS10065','3','Oh, that thirst that gnawed me deep within:<br/>Drove me seeking satisfaction.<br/>Oh, the many things that I have tried:<br/>Left me thirsting and dissatisfied.<br/>',NULL,87078,4);
INSERT INTO stanza VALUES('NS10065','4','In this endless search for something new,<br/>All the time this cry was just for You.<br/>I was blind in trying many things<br/>’Til I drank You as my living Spring.<br/>',NULL,87079,5);
INSERT INTO stanza VALUES('NS10065','5','Lord, You came and filled my inmost&nbsp;&nbsp;being.<br/>You’re the sweetest satisfaction.<br/>You’re the Spirit as my everything,<br/>Spirit in my spirit bubbling.<br/>',NULL,87080,6);
INSERT INTO stanza VALUES('NS10065','6','Thank You, Lord, for coming into me.<br/>Now You’re spreading in me constantly.<br/>Lord, You’re making home in all my heart,<br/>As my treasure filling every part.<br/>',NULL,87081,7);
INSERT INTO stanza VALUES('NS10066','1','What made You, Lord, to die for me?<br/>Why would You die for me, Your enemy?<br/>You took my place to hang on a tree,<br/>To be a curse, a curse for me.<br/>',NULL,87082,1);
INSERT INTO stanza VALUES('NS10066','chorus','What made You die for me?<br/>I was Your enemy.<br/>Lord, You became a curse for me.<br/>Oh, what a mystery!<br/>My God, You died for me!<br/>You died for me, Your enemy.<br/>',NULL,87083,2);
INSERT INTO stanza VALUES('NS10066','2','I never thought that You would be<br/>So full of love and tender mercy.<br/>How could You love a person like me?<br/>You loved me, dear Jesus, Your enemy.<br/>',NULL,87084,3);
INSERT INTO stanza VALUES('NS10066','3','You loved me, Lord, so very long;<br/>And with a love enduring and strong.<br/>Although I mocked and cursed You so long,<br/>You waited and prayed for me all along.<br/>',NULL,87085,4);
INSERT INTO stanza VALUES('NS10066','4','I was a man who was just sin,<br/>Which issued in a life full of sins.<br/>My heart toward You was in rebellion,<br/>But, Lord, You touched me with Your compassion.<br/>',NULL,87086,5);
INSERT INTO stanza VALUES('NS10066','chorus','Your love has conquered me,<br/>Even Your enemy.<br/>In love, dear Lord, You came to me.<br/>Nothing could change me<br/>But love and mercy.<br/>Your love, dear Lord, has conquered me.<br/>',NULL,87087,6);
INSERT INTO stanza VALUES('NS10066','5','One little turn and You were there,<br/>Waiting for me with Your loving care.<br/>How could I still remain Your enemy?<br/>Your love, dear Jesus, disarmed me.<br/>',NULL,87088,7);
INSERT INTO stanza VALUES('NS10067','1','The love of Christ is now constraining me<br/>That I would love and love Him utterly.<br/>His mighty love has touched me deep within<br/>To consecrate my life and all to Him.<br/>',NULL,87089,1);
INSERT INTO stanza VALUES('NS10067','chorus','This charming One so excelling;<br/>To His touch I’m now responding;<br/>To surrender, to surrender to Him.<br/>',NULL,87090,2);
INSERT INTO stanza VALUES('NS10067','2','This tide of love has flowed to me from Him;<br/>Unchanging love that keeps on rushing in.<br/>Now I’m for Him beyond my own control;<br/>He is now my love and my only goal.<br/>',NULL,87091,3);
INSERT INTO stanza VALUES('NS10067','chorus','His dying love so compelling,<br/>And this tide has made me willing<br/>To love Him, I can’t help but love Him.<br/>',NULL,87092,4);
INSERT INTO stanza VALUES('NS10067','3','The love of Christ<br/>Is now constraining me to love Him utterly.<br/>His mighty love<br/>Has touched me deep within to consecrate to Him.<br/>',NULL,87093,5);
INSERT INTO stanza VALUES('NS10067','chorus','This charming One so excelling;<br/>To His touch I’m now responding;<br/>To surrender, to surrender to Him.<br/>',NULL,87094,6);
INSERT INTO stanza VALUES('NS10067','4','This tide of love<br/>Has flowed to me from Him that keeps on rushing in.<br/>Now I’m for Him<br/>Beyond my own control; He’s now my final goal.<br/>',NULL,87095,7);
INSERT INTO stanza VALUES('NS10067','chorus','His dying love so compelling,<br/>And this tide has made me willing<br/>To love Him, I can’t help but love Him.<br/>',NULL,87096,8);
INSERT INTO stanza VALUES('NS10068','1','If there is no resurrection,<br/>God would be God of the dead;<br/>Christ Himself would not be living,<br/>Ne’er have been raised from the dead.<br/>',NULL,87097,1);
INSERT INTO stanza VALUES('NS10068','chorus','But there is a resurrection<br/>Which is the vitality,<br/>Both the life pulse and the lifeline<br/>Within God’s economy.<br/>',NULL,87098,2);
INSERT INTO stanza VALUES('NS10068','2','If there is no resurrection,<br/>Christ a Savior dead would be,<br/>Not the One Who lives forever,<br/>Who can save most utterly.<br/>',NULL,87099,3);
INSERT INTO stanza VALUES('NS10068','3','If there is no resurrection,<br/>There would be no living proof,<br/>No proof that justification<br/>Was accomplished by Christ’s death.<br/>',NULL,87100,4);
INSERT INTO stanza VALUES('NS10068','4','If there is no resurrection,<br/>Life imparting would be stayed.<br/>And so would regeneration<br/>With renewing pass away.<br/>',NULL,87101,5);
INSERT INTO stanza VALUES('NS10068','5','If there is no resurrection,<br/>Then whatever would there be?<br/>There would be no transformation,<br/>Nor to Christ conformity.<br/>',NULL,87102,6);
INSERT INTO stanza VALUES('NS10068','6','If there is no resurrection,<br/>Where the members of the Christ?<br/>There to Him would be no Body,<br/>Which His fullness is in life.<br/>',NULL,87103,7);
INSERT INTO stanza VALUES('NS10068','7','If there is no resurrection,<br/>Then the church ne’er have been<br/>Which is both to Christ His dear bride<br/>And to God the one new man.<br/>',NULL,87104,8);
INSERT INTO stanza VALUES('NS10068','8','If there is no resurrection,<br/>Then would be God’s economy,<br/>With the voiding of His purpose,<br/>In collapse fall totally.<br/>',NULL,87105,9);
INSERT INTO stanza VALUES('NS10069','1','Is there someone who’s a friend<br/>That I can open to?<br/>A someone who understands<br/>All that I’m going through?<br/>A someone when there’s no one<br/>I can always come to?<br/>There is no someone like this One.<br/>',NULL,87106,1);
INSERT INTO stanza VALUES('NS10069','chorus','There is a someone;<br/>Someone you can open to.<br/>There is a someone;<br/>Someone who will take you through.<br/>There is a someone when there is no one;<br/>There is a someone, a wonderful One.<br/>',NULL,87107,2);
INSERT INTO stanza VALUES('NS10069','2','Is there someone who can care<br/>Through all my hardest times?<br/>A someone always there<br/>Though it may rain or shine?<br/>A someone I can lean on<br/>When the stormy times come?<br/>There is no someone like this One.<br/>',NULL,87108,3);
INSERT INTO stanza VALUES('NS10069','chorus','There is a someone;<br/>Someone in my hardest times.<br/>There is a someone,<br/>Always there through rain or shine.<br/>There is a someone<br/>When there is no one;<br/>There is a someone, a special One.<br/>',NULL,87109,4);
INSERT INTO stanza VALUES('NS10069','3','Is there someone who will take<br/>Take me just as I am?<br/>A someone who’ll not forsake<br/>One I can trust to the end?<br/>A someone who knows me<br/>Yet he still wants me?<br/>There is no someone like this One.<br/>',NULL,87110,5);
INSERT INTO stanza VALUES('NS10069','chorus','There is a someone<br/>Who will take you as you are.<br/>There is a someone;<br/>He will reach you near or far.<br/>There is a someone;<br/>He’s the most lovely One.<br/>Just take this someone, the loveliest One.<br/>',NULL,87111,6);
INSERT INTO stanza VALUES('NS10069','4','Is there someone who can reach<br/>Down to the depths of my being?<br/>A someone who can fix<br/>All of my broken heart strings?<br/>A someone who can love me<br/>When there’s no love in me?<br/>There is no someone like this One.<br/>',NULL,87112,7);
INSERT INTO stanza VALUES('NS10069','chorus','There is a someone<br/>Who can touch your inmost being.<br/>There is a someone;<br/>He can make your heart to sing.<br/>There is a someone,<br/>Love is this precious One.<br/>Just love this someone, the wonderful One.<br/>',NULL,87113,8);
INSERT INTO stanza VALUES('NS10069','chorus','Christ is this someone<br/>Who can touch your inmost being.<br/>Christ is this someone—<br/>He can make your heart to sing.<br/>Christ is this someone.<br/>Christ is this precious One.<br/>Just love this someone, the wonderful One.<br/>',NULL,87114,9);
INSERT INTO stanza VALUES('NS10070','1','Now from my heart comes,<br/>A happy song;<br/>It’s just for You, Lord,<br/>There’s only One:<br/>J-E-S-U-S, I love You.<br/>',NULL,87115,1);
INSERT INTO stanza VALUES('NS10070','chorus','How I long to sing<br/>With my spirit and heart to You.<br/>Jesus, You’re so rich;<br/>In who You are and what You do.<br/>Ev’ry time I turn and open up,<br/>I drink of You.<br/>’Cause I love You.<br/>',NULL,87116,2);
INSERT INTO stanza VALUES('NS10070','2','I’ve seen how they,<br/>Pierced Your side,<br/>You gave Your all,<br/>To win Your bride<br/>J-E-S-U-S, I love You.<br/>',NULL,87117,3);
INSERT INTO stanza VALUES('NS10070','3','Without Your love, Lord,<br/>I’m so empty<br/>Life has no meaning;<br/>Just vanity,<br/>J-E-S-U-S, Reality.<br/>',NULL,87118,4);
INSERT INTO stanza VALUES('NS10070','4','Jesus in me.<br/>What a wonder;<br/>Bubbling over,<br/>Living water.<br/>J-E-S-U-S, What a joy!<br/>',NULL,87119,5);
INSERT INTO stanza VALUES('NS10071','1','I never thought that God would be enjoyable,<br/>And my experience of Him is indescribable;<br/>When first I opened up my heart to Him,<br/>He came in me and filled me to the brim.<br/>',NULL,87120,1);
INSERT INTO stanza VALUES('NS10071','chorus','O Lord, You’re wonderful.<br/>You’re wonderful.<br/>Jesus, Jesus.<br/>',NULL,87121,2);
INSERT INTO stanza VALUES('NS10071','2','I never sought Him nor I ever asked for Him.<br/>Sometimes I wonder, am I in a heavenly dream;<br/>I don’t deserve Him, oh, a sinner like me,<br/>My explanation, friends, it’s just His mercy.<br/>',NULL,87122,3);
INSERT INTO stanza VALUES('NS10071','chorus','O Lord, Your mercy reached me.<br/>Your mercy reached me.<br/>Jesus, Jesus.<br/>',NULL,87123,4);
INSERT INTO stanza VALUES('NS10071','3','My friends they tell me,<br/>“Don’t be too much for Him.“<br/>“Just be so normal and not go to the extreme.“<br/>But I can’t help it, there is no one like Him.<br/>His love has touched me, so I now have meaning.<br/>',NULL,87124,5);
INSERT INTO stanza VALUES('NS10071','chorus','O Lord, Your love has touched me.<br/>Your love has wrecked me.<br/>Jesus, Jesus.<br/>',NULL,87125,6);
INSERT INTO stanza VALUES('NS10071','4','My every moment is to live unto You.<br/>In everything dear Lord,<br/>You must now break through.<br/>I’m just a vessel, You’re my treasure within.<br/>O Lord, keep spreading in my entire being<br/>',NULL,87126,7);
INSERT INTO stanza VALUES('NS10071','chorus','By calling, O Lord Jesus,<br/>That name most precious.<br/>Jesus, Jesus.<br/>',NULL,87127,8);
INSERT INTO stanza VALUES('NS10071','5','And now I’m waiting for Your coming again.<br/>Lord, keep me faithful to You unto the end.<br/>To see You face to face on that great day,<br/>’Tis my desire that I’d go all the way.<br/>',NULL,87128,9);
INSERT INTO stanza VALUES('NS10071','chorus','O Lord, You’re coming soon.<br/>O lovely Bridegroom.<br/>Jesus, Jesus.<br/>',NULL,87129,10);
INSERT INTO stanza VALUES('NS10072','1','Lord, I have given up my pride<br/>And turned away from my arrogance<br/>For I choose to follow You.<br/>I’m not concerned with wonderful matters<br/>Or subjects too difficult for me<br/>For You’re my only concern.<br/>Instead I am content and at peace<br/>As a child lies quietly<br/>In its mother’s arms.<br/>Now my heart is peaceful within me.<br/>Now my heart is peaceful within me.<br/>Now my heart is peaceful within me.<br/>',NULL,87130,1);
INSERT INTO stanza VALUES('NS10073','1','I love You,<br/>Always and forever more,<br/>For in darkness where I lived in death<br/>You showed Your light to me.<br/>',NULL,87131,1);
INSERT INTO stanza VALUES('NS10073','2','Yes, I love You,<br/>And that is what You are,<br/>For this love You suffered death for me<br/>And the world to be redeemed.<br/>',NULL,87132,2);
INSERT INTO stanza VALUES('NS10073','chorus','Though I’m worth no more than dust,<br/>In Your eyes I am prized.<br/>Your mercy purchased me<br/>From my sin and my death.<br/>You are love, You are love.<br/>',NULL,87133,3);
INSERT INTO stanza VALUES('NS10073','3','I love You,<br/>I give my all to You,<br/>All my mind, my heart and all my strength<br/>I’ll offer all to You.<br/>',NULL,87134,4);
INSERT INTO stanza VALUES('NS10073','4','Lord, I love You,<br/>And now You live in me,<br/>Oh Lord, strengthen me to take my cross<br/>To follow You each day.<br/>',NULL,87135,5);
INSERT INTO stanza VALUES('NS10073','chorus','Now I learn to call Your name.<br/>Oh, Your riches come in<br/>As my grace, reality,<br/>My life and destiny.<br/>You are love, You are love.<br/>',NULL,87136,6);
INSERT INTO stanza VALUES('NS10073','-','Though my sins are colored scarlet,<br/>You have cleansed them white as snow;<br/>With Your blood poured out on Calvary,<br/>My redemption will always be.<br/>Lord, I need You and You’ll always be<br/>My life through eternity.<br/>Lord, I love You. Yes, I love You.<br/>I always will love You.<br/>',NULL,87137,7);
INSERT INTO stanza VALUES('NS10074','1','As a lily growing out of a bramble bush;<br/>As a bright star shining forth in the darkest night;<br/>Is a story excellent, bright and fragrant<br/>Of Boaz and Ruth in a divine romance.<br/>',NULL,87138,1);
INSERT INTO stanza VALUES('NS10074','2','Ruth the Moabitess joined to God’s holy elect;<br/>Boaz took care of her and redeemed all her debt.<br/>First she gleaned from his land,<br/>Then got married to him.<br/>This is how she was joined to God’s eternal plan.<br/>',NULL,87139,2);
INSERT INTO stanza VALUES('NS10074','chorus','Lord, I love You and treasure You.<br/>Lord, I choose You and respond to You.<br/>You’re my everything, You’re above all,<br/>You’re my Husband, and my rest,<br/>And my all in all.<br/>',NULL,87140,3);
INSERT INTO stanza VALUES('NS10074','3','The eternal God entered and stepped into time;<br/>For this He needed persons to carry the line —<br/>Those who fulfilled His plan, to bring God into man<br/>Bringing divinity into humanity.<br/>',NULL,87141,4);
INSERT INTO stanza VALUES('NS10074','4','In the universe this is the greatest event,<br/>That is Christ’s incarnation — in His first advent.<br/>Ruth became an ancestor in this mystery —<br/>God and man to be mingled as one entity.<br/>',NULL,87142,5);
INSERT INTO stanza VALUES('NS10074','5','God had promised the seed of a woman for man<br/>That would crush Satan’s head and redeem fallen man;<br/>To make God and man one, what a glory to Him!<br/>We are qualified now to partake of Him.<br/>',NULL,87143,6);
INSERT INTO stanza VALUES('NS10074','6','We are Moabites too, constituted with sin;<br/>We are under God’s wrath and His condemnation.<br/>But through Christ’s redemption, He’s our portion we claim;<br/>In this organic union, we’re married to Him.<br/>',NULL,87144,7);
INSERT INTO stanza VALUES('NS10075','1','Wherever you go, I will go,<br/>Wherever you dwell, I will dwell;<br/>Your people will be my people,<br/>And your God will be my God.<br/>Wherever you go, I will go,<br/>Wherever you dwell, I will dwell;<br/>Your people will be my people,<br/>And your God will be my God.<br/>Wherever you die, I will die;<br/>And there will I be buried.<br/>Jehovah do to me, and more as well,<br/>If anything but death parts me from you.<br/>Jehovah do to me, and more as well,<br/>If anything but death parts me from you.<br/>',NULL,87145,1);
INSERT INTO stanza VALUES('NS10076','1','What about my sinful past?<br/>And my conscience has no rest.<br/>Deep within I feel the pain.<br/>I’m condemned from all my guilty stains.<br/>',NULL,87146,1);
INSERT INTO stanza VALUES('NS10076','2','O my life of misery,<br/>In this world of vanity,<br/>As I searched for happiness,<br/>My reward I received just emptiness.<br/>',NULL,87147,2);
INSERT INTO stanza VALUES('NS10076','3','God was far away from me,<br/>Great and highest One is He.<br/>Yet You took on humanity.<br/>You came for me,<br/>Hung on a tree,<br/>Bled there to die for me.<br/>',NULL,87148,3);
INSERT INTO stanza VALUES('NS10076','chorus','That’s why I love Him.<br/>That’s why I treasure Him.<br/>That’s why I give my life and all to Him.<br/>That’s why I love Him.<br/>That’s why I treasure Him.<br/>That’s why I give my life and all to Him.<br/>',NULL,87149,4);
INSERT INTO stanza VALUES('NS10077','1','A lover of Christ should be one<br/>Who’s attracted by His love<br/>And drawn by His sweetness<br/>To pursue after Him, pursue after Him,<br/>Pursue Him for full satisfaction.<br/>',NULL,87150,1);
INSERT INTO stanza VALUES('NS10077','2','A lover of Christ should be one<br/>Who is called by Him<br/>To be delivered<br/>From the self through His oneness<br/>With the cross, with the cross of Christ.<br/>',NULL,87151,2);
INSERT INTO stanza VALUES('NS10077','3','A lover of Christ should be one<br/>Who is called by Him to live in ascension<br/>As the new creation, creation of God,<br/>In the resurrection of Christ.<br/>',NULL,87152,3);
INSERT INTO stanza VALUES('NS10077','4','A lover of Christ should be one<br/>Who’s called by Him more strongly to live within<br/>The veil, thru His cross after the lover’s<br/>Experience of His resurrection.<br/>',NULL,87153,4);
INSERT INTO stanza VALUES('NS10078','1','I am young and I’m in love<br/>With the One Who is from above.<br/>All my days are just for Him.<br/>All my being I open to Him.<br/>',NULL,87154,1);
INSERT INTO stanza VALUES('NS10078','chorus','Jesus, You love me.<br/>You took my place in Calvary.<br/>Jesus, You love me.<br/>You gave Your life to save me.<br/>',NULL,87155,2);
INSERT INTO stanza VALUES('NS10078','2','Others try the world and sin,<br/>But for me — I only want Him.<br/>Lord Your beauty has captured my heart.<br/>Now I give You every part.<br/>',NULL,87156,3);
INSERT INTO stanza VALUES('NS10078','chorus','Jesus, I love You;<br/>No other one compares to You.<br/>Jesus, I love You;<br/>My all and life I give to You.<br/>',NULL,87157,4);
INSERT INTO stanza VALUES('NS10078','3','Jesus now is living in me.<br/>We’ll be mingled as one entity.<br/>God’s good pleasure His Bride we’ll be<br/>As His wife for eternity.<br/>',NULL,87158,5);
INSERT INTO stanza VALUES('NS10078','chorus','Hallelujah! We’re in love!<br/>God loving us and we love Him.<br/>Hallelujah! We’re in love!<br/>His masterpiece the New Jerusalem.<br/>',NULL,87159,6);
INSERT INTO stanza VALUES('NS10079','1','Life is God the Father<br/>In Christ Jesus as the Spirit<br/>Flowing out and coming into us.<br/>He’s not just a teaching,<br/>Or a creed or a dead doctrine,<br/>But the processed Triune God, glorious!<br/>',NULL,87160,1);
INSERT INTO stanza VALUES('NS10079','2','Life is not created<br/>As man’s body, soul, and spirit—<br/>That’s man’s life that’s weak and temporal.<br/>Life is uncreated.<br/>It’s divine and it’s eternal.<br/>And this is the life that’s indestructible.<br/>',NULL,87161,2);
INSERT INTO stanza VALUES('NS10079','3','And this life came in us<br/>In our spirit through the Spirit;<br/>This is where we were made alive!<br/>Now this life is spreading.<br/>Lord, don’t stop—just keep invading.<br/>For this, Lord, we must be daily revived.<br/>',NULL,87162,3);
INSERT INTO stanza VALUES('NS10079','4','Life needs our maintaining,<br/>Otherwise we’re suffocating.<br/>Calling on His name we breathe Him in.<br/>Everywhere we breathe Him,<br/>Makes us fresh and makes us living.<br/>O, this life is full of hope and meaning.<br/>',NULL,87163,4);
INSERT INTO stanza VALUES('NS10079','5','In our daily living<br/>It’s this life that we are sensing.<br/>Are we in the flesh or in the Lord?<br/>If you’re dead and empty<br/>And the troubles you have plenty,<br/>Saints, get out of there and flee back to the Lord!<br/>',NULL,87164,5);
INSERT INTO stanza VALUES('NS10079','6','Then you’ll sense life flowing<br/>It’s this life that’s overcoming<br/>Satan, flesh, and the world, and sin.<br/>What a life we’re having.<br/>Lord, Your virtues manifesting,<br/>Thus, we’re branches bearing fruit in John 15.<br/>',NULL,87165,6);
INSERT INTO stanza VALUES('NS10080','1','God made me to be a man.<br/>I’m so glad I’m in His plan.<br/>He chose me before the world began—<br/>I’m so happy that I’m a man.<br/>Look at the many items in the<br/>Heaven and earth we see;<br/>Billions of things that He has made;<br/>It’s all for you and me.<br/>I am a vessel made by God,<br/>Predestined as His son to be;<br/>He chose me way back<br/>In eternity.<br/>',NULL,87166,1);
INSERT INTO stanza VALUES('NS10080','2','Satan came to corrupt man,<br/>And spoil God’s wonderful plan.<br/>But our God took on the flesh of man<br/>To die for weak, sinful man.<br/>I never thought the<br/>Mighty God became a man like me,<br/>To put on flesh and blood<br/>And lay aside His glory.<br/>He took up all our sins<br/>Upon His body to a tree<br/>To redeem us from our sins,<br/>We’re now set free!<br/>',NULL,87167,2);
INSERT INTO stanza VALUES('NS10080','3','Christ came in my deepest part—<br/>Into my spirit and heart.<br/>He came in to never leave apart,<br/>Now we have a fresh, new start.<br/>Christ came into my spirit<br/>Very, very deep within.<br/>Simply by calling on His name<br/>I have experienced Him.<br/>Christ is my life and person now<br/>In resurrection.<br/>Oh, just call on Him,<br/>He’ll fill you to the brim!<br/>',NULL,87168,3);
INSERT INTO stanza VALUES('NS10080','4','Fill, fill, fill! I’m full of Him.<br/>Joy, joy, joy! Overflowing.<br/>Love, love, love! Coming from Him within.<br/>Oh, I have touched the King!<br/>',NULL,87169,4);
INSERT INTO stanza VALUES('NS10081','1','The greatest king on earth, that is King Solomon,<br/>Fell in love with a country girl.<br/>The king had to go to the countryside<br/>And become a country man,<br/>To change his status,<br/>That he could court her.<br/>In His courtship with her<br/>She was changed to be his match,<br/>To become his queen and Shulammite,<br/>To become his counterpart<br/>And become His loving bride.<br/>This is the story of the Song of Songs.<br/>',NULL,87170,1);
INSERT INTO stanza VALUES('NS10081','2','The Song of Songs depicts our story with God<br/>Of fallen man with the King of kings.<br/>Because of His love for us,<br/>He became a lowly man<br/>To reach us and to die for our sins.<br/>Then in resurrection He<br/>Regenerated me<br/>And now we’re daily being transformed.<br/>To become the same as He with His life and nature<br/>To become His counterpart, His match and bride.<br/>',NULL,87171,2);
INSERT INTO stanza VALUES('NS10082','1','How could a country girl like me<br/>Become Your match — Your bride to be?<br/>You’re holy and You are divine<br/>But I’m fallen and human.<br/><br/>Without You, Lord, I have no chance<br/>To be like You in this romance.<br/>But You chose me ere the world began<br/>Nothing could change Your plan.<br/>',NULL,87172,1);
INSERT INTO stanza VALUES('NS10082','chorus','This divine romance<br/>Is My heart’s deep plan.<br/>I became a lowly man<br/>To court My country girl.<br/>',NULL,87173,2);
INSERT INTO stanza VALUES('NS10082','chorus','Nothing could deter,<br/>Nothing can alter<br/>My eternal love for her;<br/>I’ll gain My country girl.<br/>',NULL,87174,3);
INSERT INTO stanza VALUES('NS10082','2','No man or angel ever knew<br/>This secret hidden deep in You<br/>That You desired to be one with man<br/>Before the world began.<br/><br/>Though sin came in to ruin me<br/>Through Satan’s scheme and subtlety<br/>Nothing could break Your love for me<br/>To gain me totally.<br/>',NULL,87175,4);
INSERT INTO stanza VALUES('NS10082','chorus','This divine romance<br/>Is My heart’s deep plan,<br/>I became a lowly man<br/>To court My country girl.<br/>',NULL,87176,5);
INSERT INTO stanza VALUES('NS10082','chorus','Nothing could deter,<br/>Nothing can alter<br/>My eternal love for her;<br/>I’ll gain My country girl.<br/>',NULL,87177,6);
INSERT INTO stanza VALUES('NS10082','3','As King of kings You became a man,<br/>You died for me—I’ve been redeemed,<br/>In resurrection made us queen<br/>To marry You, my King.<br/><br/>From death You ’rose and entered me,<br/>I now possess Your divinity;<br/>In life and nature we’re the same:<br/>Both human and divine.<br/>',NULL,87178,7);
INSERT INTO stanza VALUES('NS10082','chorus','In Your love I’m drawn,<br/>To You I belong;<br/>I am not my own, Lord,<br/>I’m Yours alone.<br/>',NULL,87179,8);
INSERT INTO stanza VALUES('NS10082','chorus','By Your love I’m drawn,<br/>In Your name I’m charmed,<br/>And Your Person captured me,<br/>For I’ve been kissed by Thee.<br/>',NULL,87180,9);
INSERT INTO stanza VALUES('NS10082','4','Lord, in this close sweet fellowship,<br/>Lord, be with me so intimate,<br/>So personal and affectionate;<br/>A sweet relationship.<br/><br/>Lord, daily change my inward being<br/>Lord, all my heart possessing<br/>In all my being—transforming<br/>To be Your bride and queen.<br/>',NULL,87181,10);
INSERT INTO stanza VALUES('NS10082','chorus','In Your love I’m drawn,<br/>To You I belong;<br/>I am not my own, Lord,<br/>I’m Yours alone.<br/>',NULL,87182,11);
INSERT INTO stanza VALUES('NS10082','chorus','By Your love I’m drawn,<br/>In Your name I’m charmed,<br/>And Your Person captured me,<br/>For I’ve been kissed by Thee.<br/>',NULL,87183,12);
INSERT INTO stanza VALUES('NS10083','1','All my life I searched for God<br/>For joy and peace and happiness<br/>I prayed to idols on my knees<br/>But “my life summed up” was hopelessness.<br/>My hope was gone, I’m all alone.<br/>I’m facing death, darkness and gloom<br/>I had no joy or happiness<br/>But fear with emptiness.<br/>',NULL,87184,1);
INSERT INTO stanza VALUES('NS10083','2','My doctor and my children too<br/>They tried their best to take me through<br/>But none could heal my inward part<br/>So let me die with a broken heart.<br/>My hope was gone, I’m all alone<br/>I’m facing death, darkness and gloom<br/>I had no joy or happiness<br/>But fear with emptiness.<br/>',NULL,87185,2);
INSERT INTO stanza VALUES('NS10083','3','When death came knocking at my door<br/>I knew my life would be no more<br/>It’s then, Lord Jesus, You came in<br/>Your love and light came beaming in.<br/>My hope was gone, I’m all alone<br/>I’m facing death, darkness and gloom<br/>That’s when You came with compassion<br/>Jesus—Praise to Your name.<br/>',NULL,87186,3);
INSERT INTO stanza VALUES('NS10083','4','Your blood cleansed me, Your love touched me<br/>I called Your name, Your life filled me<br/>And now I’m full of joy and peace<br/>You’re now my life and happiness.<br/>Oh, rising Sun, in me You shined<br/>And now I know, Jesus You’re mine<br/>Your shining face makes my heart sing<br/>With healing in Your wings.<br/>',NULL,87187,4);
INSERT INTO stanza VALUES('NS10084','1','Lord Jesus I need You<br/>More than I needed You before.<br/>Lord Jesus I love You<br/>More than I loved You before.<br/>Lord Jesus I treasure You<br/>More than I treasured You before.<br/>Lord Jesus I need You.<br/>I love and treasure—only You.<br/>',NULL,87188,1);
INSERT INTO stanza VALUES('NS10084','2','Lord Jesus I need You<br/>More than I needed You before.<br/>Without You, Lord, I would be through;<br/>I would collapse apart from You.<br/>Your presence is my everything.<br/>You are the greatest blessing.<br/>Lord Jesus I need You.<br/>I love and treasure—only You.<br/>',NULL,87189,2);
INSERT INTO stanza VALUES('NS10084','3','Lord Jesus I love You<br/>More than I loved You before.<br/>You first loved me and died for me;<br/>Your dying love has conquered me.<br/>One look at You hanging on a tree;<br/>You loved me, Lord, so utterly.<br/>Lord Jesus I need You.<br/>I love and treasure—only You.<br/>',NULL,87190,3);
INSERT INTO stanza VALUES('NS10084','4','Lord Jesus I treasure You<br/>More than I treasured You before.<br/>You dwell in me, priceless One to be<br/>So near and dear subjectively.<br/>Lord Jesus You’re one with me;<br/>We’re mingled for eternity.<br/>Lord Jesus I need You.<br/>I love and treasure—only You.<br/>',NULL,87191,4);
INSERT INTO stanza VALUES('NS10085','1','Saints, if we do not love Christ<br/>Then we surely cannot live Him.<br/>Loving Him is the best way<br/>To concentrate our being on Him.<br/>(Repeat)<br/>',NULL,87192,1);
INSERT INTO stanza VALUES('NS10085','chorus','Living Christ is by loving Him,<br/>Living Christ is by loving Him,<br/>Living Christ is by loving Him,<br/>To concentrate our being on Him.<br/>(Repeat)<br/>',NULL,87193,2);
INSERT INTO stanza VALUES('NS10085','2','Loving Christ to the uttermost<br/>And taking Him, saints, as our foremost.<br/>Let’s occupy our entire being,<br/>Yes, absolutely on Him.<br/>(Repeat)<br/>',NULL,87194,3);
INSERT INTO stanza VALUES('NS10085','chorus','Loving Christ to the uttermost,<br/>Taking Him as your foremost.<br/>Living Christ is by loving Him,<br/>Lord, wholly occupy my being.<br/>',NULL,87195,4);
INSERT INTO stanza VALUES('NS10085','chorus','Loving Christ to the uttermost,<br/>Taking Him as your foremost.<br/>Living Christ is by loving Him,<br/>Lord, wholly occupy my entire being.<br/>',NULL,87196,5);
INSERT INTO stanza VALUES('NS10086','1','If we would love the Lord<br/>And care for His unique Body,<br/>The Lord will pour Himself out<br/>And move within us as<br/>The sevenfold intensified Spirit<br/>To blend us together<br/>For the consummation<br/>Of the New Jerusalem.<br/>',NULL,87197,1);
INSERT INTO stanza VALUES('NS10001','1','Let me stand behind You, Lord.<br/>Let me wash Your feet with my tears.<br/>Let me wipe them with my hair.<br/>Let me kiss them and anoint them<br/>&nbsp;&nbsp;&nbsp;&nbsp;With the ointment.<br/><br/>I love You!<br/>Jesus, I love You!<br/>May I waste my all and life on You.<br/>Let me pour the ointment pure<br/>On Your head and on Your feet,<br/>On You, most precious One<br/>Because I love You.<br/>',NULL,87198,1);
INSERT INTO stanza VALUES('NS10001','2','Let me take a pound of ointment pure<br/>Of great value to anoint Your feet<br/>And wipe them with my hair<br/>That the house be filled with the fragrance<br/>&nbsp;&nbsp;&nbsp;&nbsp;Of the ointment.<br/><br/>I love You!<br/>Jesus, I love You!<br/>May I waste my all and life on You.<br/>Let me pour the ointment pure<br/>On Your head and on Your feet,<br/>On You, most precious One<br/>Because I love You.<br/>',NULL,87199,2);
INSERT INTO stanza VALUES('NS10001','3','Lord, they said if You were a prophet,<br/>You should know who and what I am.<br/>I’m a sinner that toucheth You,<br/>A woman not worthy to anoint You.<br/><br/>But I love You!<br/>Jesus, I love You!<br/>You forgave me the most<br/>&nbsp;&nbsp;&nbsp;&nbsp;now I love You, Lord, the most.<br/>Let me pour the ointment pure<br/>On Your head and on Your feet,<br/>On You, most precious One,<br/>Because You love me.<br/>',NULL,87200,3);
INSERT INTO stanza VALUES('NS10001','4','Let my love from my being wash Your feet<br/>And my glory without wipe them too<br/>Let me kiss them where the nails would pierce.<br/>All my love, Lord, and glory I’ll waste on You.<br/><br/>I love You!<br/>Jesus, I love You!<br/>All my glory and love I pour<br/>&nbsp;&nbsp;&nbsp;&nbsp;and waste on You.<br/>Receive my ointment, Lord.<br/>It’s all I have, dear Lord.<br/>For You, most precious One,<br/>Because I love You.<br/>',NULL,87201,4);
INSERT INTO stanza VALUES('NS10087','1','The love of God constrains me<br/>From the depths within my spirit <br/>And He fills me up to the brim.<br/>',NULL,87202,1);
INSERT INTO stanza VALUES('NS10087','2','The love of God compels me<br/>From the depths within my spirit <br/>And He fills me up to the brim.<br/>',NULL,87203,2);
INSERT INTO stanza VALUES('NS10087','3','Now I am satisfied!<br/>And it’s God who lives in me,<br/>Expressing His divinity.<br/>',NULL,87204,3);
INSERT INTO stanza VALUES('NS10087','4','For when I shout:<br/>Amen!<br/>Praise the Lord!<br/>Hallelujah! <br/>The love of God enters me.<br/>',NULL,87205,4);
INSERT INTO stanza VALUES('NS1001','1','Lord, grant me a willing heart<br/>To love You without reserve;<br/>Always open to You within,<br/>That all of Your riches I may gain.<br/><br/>Rekindle my love for You;<br/>Fan it with burning flame.<br/>Lord, it’s just by Your mercy,<br/>I have not been consumed.<br/>',NULL,87206,1);
INSERT INTO stanza VALUES('NS1001','chorus','Make my love for You burn brightly anew<br/>Each moment Your name I call;<br/>In the dawn of the morning,<br/>How I long to be in<br/>Your presence, dear Lord.<br/>',NULL,87207,2);
INSERT INTO stanza VALUES('NS1001','2','Sanctify me, O Lord,<br/>From the tides of the world;<br/>Make me an open vessel<br/>Useful to the Master.<br/><br/>Hide not Thy face from me,<br/>For I shall surely seek Thee;<br/>From this day until eternity,<br/>Your countenance I’ll behold.<br/>',NULL,87208,3);
INSERT INTO stanza VALUES('NS1001','verse','Bridge:<br/>Though my heart constantly fails,<br/>Yet Lord, Your grace still sustains;<br/>Your love constraining forever will prevail.<br/>',NULL,87209,4);
INSERT INTO stanza VALUES('NS1001','verse','Your presence, dear Lord.<br/>Your presence, dear Lord.<br/>Your presence, dear Lord.<br/>Your presence, dear Lord.<br/>',NULL,87210,5);
INSERT INTO stanza VALUES('NS1002','1','For Demas has abandoned me,<br/>Having loved the present age,<br/>And has gone to Thessalonica.<br/>Second Timothy four-ten.<br/>',NULL,87211,1);
INSERT INTO stanza VALUES('NS1002','chorus','The world is planned as Satan’s scheme<br/>To usurp us, God’s people.<br/>Guard your hearts; let us watch,<br/>Love His appearing.<br/>',NULL,87212,2);
INSERT INTO stanza VALUES('NS1002','2','Just as the days of Noah were,<br/>So will the coming of—<br/>Coming of the Son of Man be.<br/>Matthew two-four, three-seven.<br/>',NULL,87213,3);
INSERT INTO stanza VALUES('NS1002','chorus','The Lord will come to deal with man;<br/>He will solve all our problems.<br/>We much watch for our Lord—<br/>His dear appearing.<br/>',NULL,87214,4);
INSERT INTO stanza VALUES('NS1002','3','Lord, I repent. Show me mercy.<br/>Save me from the present age.<br/>Lord, give me a glorious ending;<br/>I would love Your appearing.<br/>',NULL,87215,5);
INSERT INTO stanza VALUES('NS1002','chorus','The Lord has a reward for us.<br/>He has called us all upward,<br/>To His Christ, for our prize<br/>At His appearing.<br/>',NULL,87216,6);
INSERT INTO stanza VALUES('NS1003','1','To the church of God which is in Corinth,<br/>To those who have been sanctified in Christ Jesus,<br/>The called saints, with all those<br/>Who call upon the name of our Lord Jesus Christ<br/>In every place, who is theirs and ours.<br/>(repeat)<br/>',NULL,87217,1);
INSERT INTO stanza VALUES('NS1003','chorus','Who call upon the name of our Lord Jesus Christ in every place,<br/>Who call upon the name of our Lord Jesus Christ in every place,<br/>Who is theirs and ours.<br/>',NULL,87218,2);
INSERT INTO stanza VALUES('NS1004','1','Christ was crucified, all sin and death was judged,<br/>Having now been justified in God’s own blood;<br/>Even yet while enemies, God through this One<br/>Reconciled and rescued us, in Christ His Son!<br/>',NULL,87219,1);
INSERT INTO stanza VALUES('NS1004','chorus','Full salvation! Full, full salvation!<br/>Christ the overcoming One in us is life!<br/>Much, much more was sin erased,<br/>Much, much more we have been graced,<br/>Much, much more we will be saved to reign in life!<br/>Much, much more did grace abound,<br/>Much, much more in grace be found,<br/>Much, much more we will be saved to reign in life!<br/>',NULL,87220,2);
INSERT INTO stanza VALUES('NS1004','2','Having now been reconciled we will be saved,<br/>Through God’s gift of righteousness, partake of grace;<br/>Jesus Christ, this gracious gift, to us has come,<br/>And abounding richly to all in the Son!<br/>',NULL,87221,3);
INSERT INTO stanza VALUES('NS1004','3','Much more life to those in Christ who have believed,<br/>With the gift of righteousness, much grace received,<br/>Reign in life and with the Lord always be found,<br/>Ruling, reigning in His life more grace abounds.<br/>',NULL,87222,4);
INSERT INTO stanza VALUES('NS1004','4','Reign in life in Christ with su’pra-bounding grace,<br/>All our nat’ral life, with Christ, will be replaced;<br/>We can reign with Christ unto eternal life;<br/>In God’s kingdom, manifested, shining bright!<br/>',NULL,87223,5);
INSERT INTO stanza VALUES('NS1005','1','The world will make war with the Lamb,<br/>And He will overcome them,<br/>The Lord of lords and King of kings;<br/>And those who are with Him,<br/>The called and<br/>The chosen,<br/>The faithful,<br/>Will also overcome them.<br/>',NULL,87224,1);
INSERT INTO stanza VALUES('NS1005','chorus','Come, Lord Jesus!<br/>Draw me to meet You,<br/>To run, to wait,<br/>To gain the crown of righteousness,<br/>And win the race.<br/>We love Your coming, Lord.<br/>',NULL,87225,2);
INSERT INTO stanza VALUES('NS1006','1','Lord, I consecrate myself;<br/>Body, soul, and spirit too.<br/>Lord, preserve me in this age.<br/>Paint me with the Ointment true—<br/>',NULL,87226,1);
INSERT INTO stanza VALUES('NS1006','chorus','Christ is life and in my spirit.<br/>When I turn I get this life!<br/>When I pray, Lord—Your voice, I hear it!<br/>Thank You, Lord, I have this life!<br/>',NULL,87227,2);
INSERT INTO stanza VALUES('NS1006','2','We must flee these youthful lusts—<br/>Lord, we really want to grow.<br/>Praying, speaking, fellowshipping—<br/>All the sense of life to know.<br/>',NULL,87228,3);
INSERT INTO stanza VALUES('NS1006','chorus','Lord, Your love is sweet and tender.<br/>Day by day, I’m drawn to You.<br/>When I touch You I am recovered.<br/>Keep me turning back to You.<br/>',NULL,87229,4);
INSERT INTO stanza VALUES('NS1006','3','God is working now within me;<br/>Every moment, every day<br/>By obeying His anointing.<br/>“Oh Lord Jesus” is the way!<br/>',NULL,87230,5);
INSERT INTO stanza VALUES('NS1006','chorus','Oh Lord, strengthen and constrain us!<br/>Keep increasing, grow in us.<br/>Break through every kind of blockage<br/>Life is so mysterious!<br/>',NULL,87231,6);
INSERT INTO stanza VALUES('NS1006','4','Jesus is reality.<br/>He’s the only One we need.<br/>Sin, death, doubts: we’re now set free!<br/>He is life and peace to me.<br/>',NULL,87232,7);
INSERT INTO stanza VALUES('NS1006','chorus','Lord, in us, continue growing.<br/>You’re the all-sufficient One!<br/>Keep our spirits burning and flowing—<br/>We will love You ’til You come!<br/>',NULL,87233,8);
INSERT INTO stanza VALUES('NS1007','1','Because I live, you also shall live,<br/>Because I live, you also shall live!<br/>In that day you will know<br/>That I’m in My Father,<br/>You in Me,<br/>And I in you.<br/>We coinhere!<br/>',NULL,87234,1);
INSERT INTO stanza VALUES('NS1008','1','For the mind set on the flesh is death,<br/>But the mind set on the spirit is life and peace.<br/>For the mind set on the flesh is death,<br/>But the mind set on the spirit is life and peace.<br/>',NULL,87235,1);
INSERT INTO stanza VALUES('NS1008','2','For the law of the Spirit<br/>Of life has freed me<br/>In Christ Jesus<br/>From the law of sin and of death.<br/>',NULL,87236,2);
INSERT INTO stanza VALUES('NS1009','1','Our God is a God of joy.<br/>Enjoying Him is my strength.<br/>His Spirit in mine anoints,<br/>And gladness imparts today.<br/>Forgetting all other things,<br/>Of service and laboring,<br/>But opening all my being,<br/>Exultingly all I sing—<br/>',NULL,87237,1);
INSERT INTO stanza VALUES('NS1009','chorus','My God is joy!<br/>His joy my strength.<br/>He fills my days<br/>With ceaseless praise.<br/>My God is love,<br/>Unspeakable,<br/>So wonderful,<br/>With glory full, oh God,<br/>Become my joy today.<br/>',NULL,87238,2);
INSERT INTO stanza VALUES('NS1009','2','Abiding in Christ the Vine,<br/>His living supply I take.<br/>His joy is becoming mine,<br/>By calling upon His name.<br/>This fullness of joy in me<br/>Displaces anxiety,<br/>And fills me with utter peace,<br/>For Christ is my everything!<br/>',NULL,87239,3);
INSERT INTO stanza VALUES('NS1010','1','I want to fully follow Jehovah<br/>All the days of my life.<br/>No hesitation,<br/>No reservation,<br/>Fully trusting Him.<br/>',NULL,87240,1);
INSERT INTO stanza VALUES('NS1010','chorus','Lord, when I look back on the journey<br/>And all of the things You’ve done for me,<br/>How could I settle and stand back<br/>From all You’ve prepared for me?<br/>I want to fully follow You<br/>Into the good land You promised.<br/>I want to gain my all-inclusive Christ.<br/>',NULL,87241,2);
INSERT INTO stanza VALUES('NS1010','2','I want to fully follow Jehovah<br/>All the days of my life.<br/>Deal with the old man,<br/>Off to the good land<br/>To enjoy my Christ.<br/>',NULL,87242,3);
INSERT INTO stanza VALUES('NS1010','3','I want to fully follow Jehovah<br/>All the days of my life.<br/>Leave all the matters<br/>In His safe hands to<br/>Let Him make His choice.<br/>',NULL,87243,4);
INSERT INTO stanza VALUES('NS1010','4','I want to fully follow Jehovah<br/>All the days of my life.<br/>I’ll pay the price to<br/>Cross o’er the Jordan<br/>To possess my Christ.<br/>',NULL,87244,5);
INSERT INTO stanza VALUES('NS1010','5','We want to fully follow Jehovah<br/>All the days of our lives.<br/>Be strong and take courage<br/>To claim our portion—<br/>Our all-inclusive Christ.<br/>',NULL,87245,6);
INSERT INTO stanza VALUES('NS1010','chorus','Lord, when we look back on the journey,<br/>We’ll say that it’s You we chose fully.<br/>We didn’t settle and stand back<br/>From gaining You thoroughly.<br/>We want to fully follow You<br/>Into the good land You promised.<br/>We want to gain our all-inclusive Christ.<br/>',NULL,87246,7);
INSERT INTO stanza VALUES('NS1011','1','Pursue love as the greatest virtue;<br/>Behold the most excellent way.<br/>Where talents and gifts will fail you,<br/>Love never falls away.<br/>What nullifies natural jealousy<br/>And quells all our selfish pride?<br/>Of all of the virtues only<br/>Three abide:<br/>',NULL,87247,1);
INSERT INTO stanza VALUES('NS1011','chorus','Hope will reap what faith believes,<br/>But love enjoys what these receive.<br/>Of virtues that we partake of,<br/>The greatest of these is love.<br/>',NULL,87248,2);
INSERT INTO stanza VALUES('NS1011','2','One counting another’s failures,<br/>Unwritten yet in the mind,<br/>Uncovering one’s behavior,<br/>Forgetting that love is blind.<br/>Exchanges provoke us easily<br/>When short of the loving cure.<br/>When filled with divine love then we see<br/>Love endures.<br/>',NULL,87249,3);
INSERT INTO stanza VALUES('NS1012','1','And this is His commandment,<br/>That we believe in the name<br/>Of His Son Jesus Christ, (our Lord),<br/>And love one another.<br/>',NULL,87250,1);
INSERT INTO stanza VALUES('NS1012','chorus','We are the children of God.<br/>We believe in the name of His Son.<br/>We love because He first loved us.<br/>We abide in Him and He in us.<br/>',NULL,87251,2);
INSERT INTO stanza VALUES('NS1012','2','And he who keeps His commandments<br/>Abides in Him, and He in him.<br/>And in this we know He abides in us,<br/>By the Spirit whom He gave to us.<br/>',NULL,87252,3);
INSERT INTO stanza VALUES('NS1012','3','And we know and have believed<br/>The love which God has in us.<br/>God is love, and he who abides in love<br/>Abides in God and God abides in him.<br/>',NULL,87253,4);
INSERT INTO stanza VALUES('NS1012','note','<br/>',NULL,87254,5);
INSERT INTO stanza VALUES('NS1013','1','(Part 1)<br/>And he rose up and came to his own father.<br/>But while he was still a long, long way off,<br/>His father saw him and was moved with compassion,<br/>And he ran and fell on his neck, fell on his neck,<br/>And kissed him, and he kissed him affectionately.<br/>',NULL,87255,1);
INSERT INTO stanza VALUES('NS1013','2','(Part 2)<br/>Bring out quickly the best robe<br/>And put it on him, and put a ring on his hand<br/>And sandals on his feet. And bring the fattened calf;<br/>Slaughter it, and let us eat and be merry. This son of mine<br/>Was dead and lives again; was lost but found.<br/>',NULL,87256,2);
INSERT INTO stanza VALUES('NS1013','note','<br/>',NULL,87257,3);
INSERT INTO stanza VALUES('NS1014','1','Lord, You made a spirit in us<br/>To fulfill Your eternal purpose!<br/>Lord, Your Spirit now lives in us,<br/>Dispensing life to us!<br/>',NULL,87258,1);
INSERT INTO stanza VALUES('NS1014','chorus','The Spirit has everything we need,<br/>Essential and also economical!<br/>Whoever believes can go to Him<br/>And drink of the one Spirit!<br/>',NULL,87259,2);
INSERT INTO stanza VALUES('NS1014','2','We have been regenerated,<br/>Sanctified and then transformed—<br/>The Spirit works to renew our minds,<br/>Sealing us for God!<br/>',NULL,87260,3);
INSERT INTO stanza VALUES('NS1015','1','Christ is the life-giving Spirit, He lives inside of me;<br/>What a glorious fact; two spirits one are we!<br/>As a vessel I’m created, for God’s economy<br/>And through His dispensing He flows into me.<br/>He is so all inclusive, He is my all in all;<br/>He is rich to me when on His name I call;<br/>I can worship Him in spirit, and in reality;<br/>He’s my full supply, so dear and near to me.<br/>',NULL,87261,1);
INSERT INTO stanza VALUES('NS1015','2','As I’m to my spirit turning, and from my soul I flee,<br/>I enjoy His sweet anointing within me.<br/>He is moving and He’s spreading, deep in my very being,<br/>As His presence fills me with delight and cheer.<br/>Through failures and temptations, anxieties and griefs,<br/>He is listening to my calling and my pleas.<br/>He brings rest to all my burdens, and peace to all my strife,<br/>And as grace He comes to fill me with His life.<br/>',NULL,87262,2);
INSERT INTO stanza VALUES('NS1015','3','It’s no longer I who’s living, but Christ who lives in me;<br/>I am mingled as one spirit with my Lord.<br/>As He strengthens me with power, into my inner man<br/>I can live according to His rule within.<br/>He fills me with His fullness; I day to day apply<br/>All the riches of the Spirit’s life-supply.<br/>He is witnessing within me: I am a son of God.<br/>I express Him in my walk in daily life.<br/>',NULL,87263,3);
INSERT INTO stanza VALUES('NS1015','4','I enjoy His full salvation, and grow organically;<br/>He will bring me unto sonship in His life.<br/>Now from glory unto glory, He is transforming me;<br/>Through the Spirit’s sealing I conformed will be.<br/>When fully saturated, our being tripartite<br/>Will become the New Jerusalem, His bride.<br/>O Lord! Amen! Hallelujah! What great reality!<br/>We’ll express the Triune God eternally!<br/>',NULL,87264,4);
INSERT INTO stanza VALUES('NS1016','1','One of the last things that the Son said,<br/>Before He died and rose up from the dead,<br/>Was that He’d go prepare a place for us,<br/>That where He is we too could be.<br/>',NULL,87265,1);
INSERT INTO stanza VALUES('NS1016','chorus','He said: “In my Father…In Me…. In you,<br/>In that day you’ll know<br/>I’m in my Father, you’re in Me<br/>And I am in you.”<br/>',NULL,87266,2);
INSERT INTO stanza VALUES('NS1016','2','He spoke of going and returning.<br/>He’d send the Spirit (whom we already knew).<br/>He said He would not leave us orphans,<br/>Because He lives we would live too.<br/>',NULL,87267,3);
INSERT INTO stanza VALUES('NS1016','chorus','Interlude:<br/>God became a man just like you and me.<br/>Lived a human life, oh, so perfectly.<br/>Died an all-inclusive death<br/>And then He rose up to become the all-inclusive,<br/>Compound, life-giving, indwelling Spirit.<br/>Then breathing into His disciples.<br/>He told them, “Receive ye the Holy Breath“.<br/>This the fulfillment of what He had spoken,<br/>“In that day I will be in you.”<br/>',NULL,87268,4);
INSERT INTO stanza VALUES('NS1016','3','So now today we’re coinhering.<br/>We dwell in Him, and He is dwelling in us.<br/>We’re in the sweet incorporation<br/>of God and man, how glorious!<br/>',NULL,87269,5);
INSERT INTO stanza VALUES('NS1017','1','It is not a teaching or a word,<br/>Not a doctrine that I’ve heard,<br/>Not religion, not an outward form<br/>That can meet your need and wash your feet,<br/>Touch you in your deepest part,<br/>But it’s just the Christ—<br/>That I’ve enjoyed.<br/>',NULL,87270,1);
INSERT INTO stanza VALUES('NS1018','1','For as many promises of God as there are,<br/>In Him is the Yes, is the Yes;<br/>Therefore also through Him is the Amen to God,<br/>For glory, for glory through us.<br/>',NULL,87271,1);
INSERT INTO stanza VALUES('NS1018','chorus','He’s the Yes,<br/>The Amen.<br/>He’s the Yes,<br/>He’s the Amen to God.<br/>',NULL,87272,2);
INSERT INTO stanza VALUES('NS1018','2','But He who firmly attaches us with you<br/>To Christ, and has anointed us<br/>Is God, who has sealed us and has given the pledge<br/>Of the Spirit in our hearts.<br/>',NULL,87273,3);
INSERT INTO stanza VALUES('NS1019','chorus','And I answered, Who are You, Lord?<br/>And I answered, Who are You, Lord?<br/>And He said to me, I am Jesus,<br/>Jesus the Nazarene, whom you persecute.<br/>',NULL,87274,1);
INSERT INTO stanza VALUES('NS1019','1','And as I journeyed and drew near<br/>To Damascus about midday,<br/>Suddenly a great light<br/>Flashed out of heaven;<br/>And I fell to the ground and heard a voice,<br/>',NULL,87275,2);
INSERT INTO stanza VALUES('NS1019','chorus','Saul, Saul, why are you persecuting Me?<br/>Saul, Saul, why are you persecuting Me?<br/>And I answered and said, Who are You, Lord?<br/>And He said, I am Jesus whom you persecute.<br/>',NULL,87276,3);
INSERT INTO stanza VALUES('NS1019','2','And those who were with me beheld the light,<br/>But did not hear the voice of the One,<br/>The One who was speaking<br/>Speaking to me,<br/>And I said, What shall I do, Lord?<br/>',NULL,87277,4);
INSERT INTO stanza VALUES('NS1019','chorus','And the Lord said, Rise up and go,<br/>And the Lord said, Rise up and go,<br/>Go into Damascus, there it will be told to you<br/>Concerning all the things appointed you.<br/>',NULL,87278,5);
INSERT INTO stanza VALUES('NS1019','3','And a certain man then came to me, saying,<br/>Saul, brother, receive your sight!<br/>And in that very hour, I looked up at him<br/>And he said, our God already appointed you<br/>',NULL,87279,6);
INSERT INTO stanza VALUES('NS1019','chorus','To know His will and to see the righteous One,<br/>To know His will and to see the righteous One<br/>And to hear His voice; For you will be a witness<br/>Unto all men of the things you’ve seen and heard.<br/>',NULL,87280,7);
INSERT INTO stanza VALUES('NS1019','4','And now, why do you delay?<br/>Rise up and be baptized<br/>And wash away your sins, calling on His name.<br/>Wash away your sins, calling on His name!<br/>',NULL,87281,8);
INSERT INTO stanza VALUES('NS1019','chorus','(Final Chorus:)<br/>And I answered, Who are You, Lord?<br/>And I answered, Who are You, Lord?<br/>And He said to me, I am Jesus,<br/>Jesus the Nazarene, whom you believe.<br/>',NULL,87282,9);
INSERT INTO stanza VALUES('NS1020','1','Unless Jehovah builds the house,<br/>Those who build it labor in vain.<br/>Unless Jehovah keeps the city,<br/>The guard watches in vain.<br/>',NULL,87283,1);
INSERT INTO stanza VALUES('NS1020','2','It is vain for you to raise up early,<br/>To stay up late, to eat the bread of toil;<br/>All the same, He gives to His beloved<br/>While they sleep, while they sleep.<br/>',NULL,87284,2);
INSERT INTO stanza VALUES('NS1021','1','We’re in the age of jubilee.<br/>The Lord has come to set us free.<br/>No more oppressed and poor to be.<br/>Receive Him now, the Jubilee!<br/>',NULL,87285,1);
INSERT INTO stanza VALUES('NS1021','chorus','Jesus! Our Jubilee!<br/>Redemption is made and from sin we are free!<br/>',NULL,87286,2);
INSERT INTO stanza VALUES('NS1021','2','Announce the gospel to the poor.<br/>Proclaim the captives their release.<br/>Recovery of the blind to see.<br/>This is the age of jubilee.<br/>',NULL,87287,3);
INSERT INTO stanza VALUES('NS1021','3','Amidst the famine in the world,<br/>Rise up! To Father’s house to flee.<br/>No recompense will be received.<br/>No laboring in the jubilee.<br/>',NULL,87288,4);
INSERT INTO stanza VALUES('NS1021','chorus','Jesus! Our Jubilee!<br/>Returned us to God and to our family.<br/>',NULL,87289,5);
INSERT INTO stanza VALUES('NS1021','4','Now covered with the finest robe,<br/>The fattened calf has slaughtered been.<br/>This Christ our portion e’er will be.<br/>Be merry in the jubilee!<br/>',NULL,87290,6);
INSERT INTO stanza VALUES('NS1021','5','The longing in God’s heart to be<br/>Our portion and possession free.<br/>Created vessels’ content be,<br/>Fulfilled now in the jubilee.<br/>',NULL,87291,7);
INSERT INTO stanza VALUES('NS1021','chorus','Praise God! Our Jubilee!<br/>Rejoicing in Him, from all things we are free.<br/>',NULL,87292,8);
INSERT INTO stanza VALUES('NS1021','6','When you have God, you have all things.<br/>All things are satisfactory.<br/>What need or deficit have we?!<br/>Praise God! We’re in the jubilee!<br/>',NULL,87293,9);
INSERT INTO stanza VALUES('NS1021','chorus','Hallelujah!<br/>Hallelu, Hallelujah!<br/>',NULL,87294,10);
INSERT INTO stanza VALUES('NS1022','1','I rejoiced as I ate and I mused on His words;<br/>The delight of my heart is my God.<br/>I will never forget: I’ll remember His words;<br/>The delight of my heart is my God.<br/>',NULL,87295,1);
INSERT INTO stanza VALUES('NS1022','chorus','Treasure up His words<br/>In your heart every day;<br/>Let them dwell in you richly<br/>As you read and you pray.<br/>',NULL,87296,2);
INSERT INTO stanza VALUES('NS1023','1','Let Him kiss me with the kisses of His mouth,<br/>With the kisses of His mouth!<br/>This “Him” is to many unknown<br/>But just one “Him” for me I own.<br/>He is the One I do seek after,<br/>Deeply dissatisfied, I’ll remain no longer.<br/>Oh “the kisses,” not just “a kiss” to gain<br/>(A simple relationship is just vain),<br/>But a personal, affectionate, private, spiritual,<br/>A personal, affectionate, intimate time<br/>With Him,<br/>With Him,<br/>With Him,<br/>Intimate time with Him.<br/>',NULL,87297,1);
INSERT INTO stanza VALUES('NS1024','1','Now the God of endurance and encouragement<br/>Grant you to be of the same mind<br/>Toward one another according to<br/>Christ Jesus.<br/>',NULL,87298,1);
INSERT INTO stanza VALUES('NS1024','2','Now the God of hope fill you<br/>With all joy and peace<br/>In believing, that you may abound in hope<br/>In the power of the Holy Spirit.<br/>',NULL,87299,2);
INSERT INTO stanza VALUES('NS1024','3','And I know that when I come to you,<br/>I will come in the fullness<br/>Of the blessing of Christ.<br/>Now the God of peace be with you...<br/>',NULL,87300,3);
INSERT INTO stanza VALUES('NS1024','4','All, Amen... All, Amen!<br/>All, Amen... All, Amen!<br/>All, Amen... All, Amen!<br/>All, Amen... All, Amen!<br/>(Amen!)<br/>',NULL,87301,4);
INSERT INTO stanza VALUES('NS1025','1','A spirit of love<br/>Fanned into flame;<br/>Love will prevail more than any word<br/>In power proclaimed.<br/>',NULL,87302,1);
INSERT INTO stanza VALUES('NS1025','2','Things that we do,<br/>Words that we say,<br/>When in a spirit of love, how love<br/>Prevails in this way.<br/>',NULL,87303,2);
INSERT INTO stanza VALUES('NS1025','3','The spirit in man,<br/>Where our God lives;<br/>Greatest of gifts we could e’er receive,<br/>Freely He gives.<br/>',NULL,87304,3);
INSERT INTO stanza VALUES('NS1025','4','By His great love,<br/>God is so known;<br/>Only a spirit of love in man<br/>Makes His love shown.<br/>',NULL,87305,4);
INSERT INTO stanza VALUES('NS1025','chorus','If my own desires<br/>Quench the Spirit within,<br/>Remind me to fan it again.<br/>',NULL,87306,5);
INSERT INTO stanza VALUES('NS1025','5','Powerful will,<br/>Sober in mind;<br/>Yet without love only threatening words<br/>Other souls find.<br/>',NULL,87307,6);
INSERT INTO stanza VALUES('NS1025','6','To overcome,<br/>For this we yearn;<br/>Oh may a spirit that’s fanned into flame<br/>Increasingly burn.<br/>',NULL,87308,7);
INSERT INTO stanza VALUES('NS1026','1','Intro:<br/>For He grew up like a tender plant before Him,<br/>And like a root out of dry ground.<br/>No attracting form that we should look upon Him,<br/>Nor appearance that we should desire Him.<br/>',NULL,87309,1);
INSERT INTO stanza VALUES('NS1026','2','Verse:<br/>Like one from whom men hide their faces,<br/>He was despised; and we did not esteem Him.<br/>Smitten of God and afflicted.<br/>And by His stripes we have been healed.<br/>',NULL,87310,2);
INSERT INTO stanza VALUES('NS1026','3','Countermelody:<br/>We all like sheep have gone astray;<br/>Each one has turned to his own way,<br/>But He will see the fruit of resurrection,<br/>And He will be satisfied.<br/>',NULL,87311,3);
INSERT INTO stanza VALUES('NS1027','1','Paul, a prisoner of Christ Jesus,<br/>And Timothy the brother,<br/>To Philemon the beloved and our fellow-worker<br/>And to Apphia the sister,<br/>And to Archippus, our fellow-soldier,<br/>And to the church in your house.<br/>',NULL,87312,1);
INSERT INTO stanza VALUES('NS1027','2','Grace to you and peace from God our Father<br/>And from the Lord, the Lord Jesus Christ.<br/>I thank my God always, making mention of you<br/>In my prayers, hearing of your love<br/>And of the faith which you have toward the Lord,<br/>The Lord Jesus and to all the saints,<br/>',NULL,87313,2);
INSERT INTO stanza VALUES('NS1027','3','That the fellowship of your faith may become<br/>Operative in the full knowledge<br/>Of every good thing which is in us for Christ,<br/>For I had much joy and encouragement over your love,<br/>Because the inward parts of the saints<br/>Have been refreshed through you, brother.<br/>',NULL,87314,3);
INSERT INTO stanza VALUES('NS1027','4','Wherefore, having much boldness in Christ<br/>To charge you what is fitting,<br/>Because of love I rather entreat,<br/>Being such a one as Paul, the aged,<br/>And now also a prisoner of Christ,<br/>A prisoner of Christ Jesus.<br/>',NULL,87315,4);
INSERT INTO stanza VALUES('NS1027','5','I entreat you concerning my child<br/>Whom I’ve begotten in my bonds,<br/>Onesimus, who formerly was useless to you,<br/>But now is useful both to you and to me;<br/>Onesimus, whom I have sent back to you—<br/>Him, that is, my heart, my very heart;<br/>',NULL,87316,5);
INSERT INTO stanza VALUES('NS1027','6','Whom I resolved to keep with myself,<br/>That on your behalf he might minister,<br/>Might minister to me in the bonds of the gospel,<br/>But without your mind I did not want to do anything,<br/>That your goodness should not be of necessity,<br/>But your goodness be voluntary.<br/>',NULL,87317,6);
INSERT INTO stanza VALUES('NS1027','7','For perhaps therefore he was separated from you<br/>For an hour that you might fully have him forever,<br/>No longer as a slave, but above a slave,<br/>A beloved brother, especially to me,<br/>And how much more to you, both in the flesh,<br/>Both in the flesh and in the Lord.<br/>',NULL,87318,7);
INSERT INTO stanza VALUES('NS1027','8','If then you hold me as a partner,<br/>Receive him as myself,<br/>And if he has wronged, has wronged you in anything,<br/>Or owes anything, charge that to my account;<br/>If you hold me a partner, receive him as myself,<br/>And if he has wronged you, charge that to my account.<br/>',NULL,87319,8);
INSERT INTO stanza VALUES('NS1027','9','I Paul have written with my own hand,<br/>I will repay; I will repay;<br/>Not to say to you that you owe me even your own self,<br/>Your own self besides.<br/>Yes, brother, may I have profit from you in the Lord;<br/>Refresh my inward parts in Christ.<br/>',NULL,87320,9);
INSERT INTO stanza VALUES('NS1027','10','Having confidence in your obedience,<br/>I wrote to you, knowing that you’ll do beyond what I say,<br/>And at the same time also prepare me a lodging;<br/>For I hope that through your prayers I shall be,<br/>Through your prayers I shall be graciously,<br/>I shall be graciously given to you.<br/>',NULL,87321,10);
INSERT INTO stanza VALUES('NS1027','11','Epaphras, my fellow-prisoner<br/>In Christ Jesus, greets you;<br/>As do Mark, and Aristarchus,<br/>Demas, and Luke, my fellow-workers.<br/>The grace of the Lord, of the Lord Jesus Christ<br/>Be with your spirit, with your spirit.<br/>',NULL,87322,11);
INSERT INTO stanza VALUES('NS1028','1','You are our letter, inscribed in our hearts,<br/>You are our letter, inscribed in our hearts,<br/>Known and read by all men.<br/>',NULL,87323,1);
INSERT INTO stanza VALUES('NS1028','2','You are a letter of Christ ministered by us,<br/>Inscribed not with ink but with the Spirit of God,<br/>The living God.<br/>',NULL,87324,2);
INSERT INTO stanza VALUES('NS1028','chorus','But whenever their heart<br/>Turns to the Lord,<br/>The veil is taken,<br/>Taken away.<br/>And the Lord is the Spirit;<br/>And where the Spirit of the Lord is,<br/>There is freedom,<br/>There is freedom!<br/>',NULL,87325,3);
INSERT INTO stanza VALUES('NS1028','3','You are our letter, inscribed in our hearts,<br/>You are our letter, inscribed in our hearts,<br/>known and read by all men.<br/>',NULL,87326,4);
INSERT INTO stanza VALUES('NS1028','4','You are a letter of Christ ministered by us,<br/>Inscribed not with ink but with the Spirit of God,<br/>The living God.<br/>',NULL,87327,5);
INSERT INTO stanza VALUES('NS1028','chorus','But we all with unveiled face,<br/>Beholding and reflecting<br/>Like a mirror<br/>The glory of the Lord,<br/>Are being transformed into<br/>The same image<br/>From glory to glory,<br/>Glory to glory!<br/>',NULL,87328,6);
INSERT INTO stanza VALUES('NS1029','1','But thanks be to God who always leads us,<br/>Leads us in triumph, triumph in the Christ,<br/>And manifests through us the savor,<br/>Savor of the knowledge of Him in every place.<br/>',NULL,87329,1);
INSERT INTO stanza VALUES('NS1029','chorus','But thanks be to God<br/>Who always leads us,<br/>Leads us in the triumph,<br/>Triumph in the Christ.<br/>',NULL,87330,2);
INSERT INTO stanza VALUES('NS1029','2','For we are a fragrance of Christ to God,<br/>In those who are being saved and those perishing;<br/>To the one a savor, from death unto death,<br/>To the other a savor from life unto life.<br/>',NULL,87331,3);
INSERT INTO stanza VALUES('NS1030','1','For whatever promises of God there are,<br/>In Him is the Yes; in Him is the Yes;<br/>Wherefore also through Him is the Amen to God,<br/>For glory through us, for glory through us.<br/>',NULL,87332,1);
INSERT INTO stanza VALUES('NS1031','1','As revealed in Two Timothy 4:7,<br/>A proper Christian life is threefold;<br/>It involves fighting the good fight,<br/>fighting the good fight,<br/>Running and finishing the course,<br/>And keeping the faith.<br/>Running and finishing the course,<br/>And keeping the faith.<br/>',NULL,87333,1);
INSERT INTO stanza VALUES('NS1031','2','In the New Testament, faith is both<br/>Objective and subjective;<br/>The objective faith refers to the things<br/>In which we believe,<br/>And the subjective faith<br/>Has to do with our action of believing.<br/>The subjective faith<br/>Has to do with our action of believing.<br/>',NULL,87334,2);
INSERT INTO stanza VALUES('NS1031','3','In order for us to enjoy Christ<br/>As our kingdom reward,<br/>We must love the Lord’s appearing,<br/>Which is His appearing<br/>And manifestation to us today<br/>And His presence with His people at<br/>His second coming,<br/>And His presence with His people at<br/>His second coming,<br/>By staying on the constricted way,<br/>constricted way<br/>Of being watchful in life and<br/>Faithful in service,<br/>By staying on the constricted way,<br/>constricted way<br/>Of being watchful in life and<br/>Faithful in service<br/>To be constituted as the bride of Christ.<br/>',NULL,87335,3);
INSERT INTO stanza VALUES('NS1031','4','When the Lord comes again,<br/>Faith will be turned to facts,<br/>And praise will replace prayer.<br/>Love will consummate in<br/>A shadowless perfection,<br/>And we will serve Him in<br/>The sinless domain.<br/>What a day that will be!<br/>Lord Jesus, come quickly!<br/>And we will serve Him in<br/>The sinless domain.<br/>What a day that will be!<br/>Lord Jesus, come quickly!<br/>',NULL,87336,4);
INSERT INTO stanza VALUES('NS1032','1','God’s only goal in time,<br/>Dispensing life to us,<br/>Is what this heart of mine<br/>Can absolutely trust;<br/>For God Himself in Christ<br/>The flesh in time became,<br/>Now God can be my life<br/>Each time I call His name.<br/>',NULL,87337,1);
INSERT INTO stanza VALUES('NS1032','2','God’s purpose and His plan<br/>Is more of Christ dispensed;<br/>My spirit is the key,<br/>Where life and peace are sensed;<br/>So I will exercise<br/>My spirit every day,<br/>And overcome the world;<br/>Be saved from Satan’s sway.<br/>',NULL,87338,2);
INSERT INTO stanza VALUES('NS1032','chorus','Jesus! Call His name today!<br/>Jesus! Call Him day by day!<br/>Jesus! In His name we pray!<br/>God’s life dispensed,<br/>Now I’m convinced,<br/>Lord, You’re God’s goal and way!<br/>',NULL,87339,3);
INSERT INTO stanza VALUES('NS1032','3','God’s only goal in time<br/>Is to pour out His Son,<br/>His Spirit joined to mine,<br/>Intrinsic’lly made one;<br/>And fanned into a flame,<br/>Would spread His fire, divine<br/>Into my inward parts,<br/>This four-part heart of mine.<br/>',NULL,87340,4);
INSERT INTO stanza VALUES('NS1032','4','Oh, let God’s goal be mine,<br/>To gain Christ while I live,<br/>Consumed by holy fire,<br/>My every moment give;<br/>And now I am assured<br/>The One to whom I pray<br/>Patrols and guards my heart<br/>Unto that coming day.<br/>',NULL,87341,5);
INSERT INTO stanza VALUES('NS1033','1','For a day in Your courts<br/>is better than a thousand;<br/>I would rather stand at the threshold of<br/>the house of my God<br/>Than dwell in the tents of the wicked.<br/>I’d rather stand at the threshold of<br/>the house of my God,<br/>Threshold of the house of my God.<br/>',NULL,87342,1);
INSERT INTO stanza VALUES('NS1034','1','Therefore having this ministry<br/>As we have been shown mercy,<br/>We do not lose heart; (4:1)<br/>',NULL,87343,1);
INSERT INTO stanza VALUES('NS1034','chorus','Because the God who said, Out of darkness light shall shine,<br/>Is the One who shined in our hearts<br/>To illuminate the knowledge of the glory<br/>Of God in the face of Jesus Christ. (4:6)<br/>',NULL,87344,2);
INSERT INTO stanza VALUES('NS1034','2','But we have this treasure in earthen vessels<br/>That the excellency of the power<br/>May be of God and not out of us. (4:7)<br/>',NULL,87345,3);
INSERT INTO stanza VALUES('NS1034','chorus','And having the same spirit of faith<br/>According to that which is written,<br/>“I believed, therefore I spoke,”<br/>We also believe, and also speak, (4:13)<br/>',NULL,87346,4);
INSERT INTO stanza VALUES('NS1034','3','Therefore we do not lose heart;<br/>But though our outer man is decaying,<br/>Yet our inner man is being renewed day by day. (4:16)<br/>',NULL,87347,5);
INSERT INTO stanza VALUES('NS1034','chorus','Because we do not regard the things which are seen<br/>But the things which are not seen;<br/>For the things which are seen are temporary,<br/>But the things which are not seen are eternal. (4:18)<br/>',NULL,87348,6);
INSERT INTO stanza VALUES('NS1034','verse','Therefore having this ministry<br/>As we have been shown mercy,<br/>We do not lose heart. (4:1)<br/>',NULL,87349,7);
INSERT INTO stanza VALUES('NS1035','1','The Father’s lovingkindness<br/>Is precious, good, and strong,<br/>And higher than the heavens,<br/>Yet felt my whole life long;<br/>My sins were all forgiven<br/>Through Jesus, graciously<br/>Redeeming, healing, caring,<br/>And kindly saving me.<br/>',NULL,87350,1);
INSERT INTO stanza VALUES('NS1035','2','God’s merciful compassions<br/>In Jesus Christ appear,<br/>Exper’enced every morning,<br/>Dissolving all my fear;<br/>The Father of compassions<br/>And God of comfort gives<br/>To me His loving essence<br/>And in my spirit lives.<br/>',NULL,87351,2);
INSERT INTO stanza VALUES('NS1035','3','God’s faithfulness is greater<br/>Than all my faithlessness;<br/>His nature and His being<br/>Became my blessedness;<br/>His calling and His keeping<br/>In Christ the Son, so sweet,<br/>Will sanctify me wholly,<br/>And will preserve complete.<br/>',NULL,87352,3);
INSERT INTO stanza VALUES('NS1036','1','I was chosen by God long before<br/>The foundations of earth He did form.<br/>It was by God’s foreknowledge so vast<br/>That one day He would call me at last.<br/>',NULL,87353,1);
INSERT INTO stanza VALUES('NS1036','chorus','I am chosen by God,<br/>And although I may feel that I’m flawed,<br/>It’s His mercy I see,<br/>That by God’s grace He ever chose me.<br/>',NULL,87354,2);
INSERT INTO stanza VALUES('NS1036','2','He chose me for the purpose He planned,<br/>To express Him, that’s why He made man,<br/>And to represent God as a king,<br/>One day ruling with Him o’er all things.<br/>',NULL,87355,3);
INSERT INTO stanza VALUES('NS1036','3','Although chosen by God we have been,<br/>We can still have the struggles within.<br/>For the troubles without cause us pain,<br/>Yet through “all things” our God we will gain.<br/>',NULL,87356,4);
INSERT INTO stanza VALUES('NS1036','4','Just like Jacob of old we can be<br/>One to bless others thus, Lord, with Thee.<br/>Then we’ll worship our God just like him<br/>For His shepherding work done within.<br/>',NULL,87357,5);
INSERT INTO stanza VALUES('NS1037','1','Giving thanks unto the Father<br/>Who’s qualified us for a share,<br/>Share of the allotted portion<br/>Of the saints in the light,<br/>Who delivered us out of the authority<br/>Of darkness and transferred us<br/>Into the kingdom of the Son<br/>Of His love. Praise the Lord!<br/>',NULL,87358,1);
INSERT INTO stanza VALUES('NS1038','1','Lord, You are the great I Am,<br/>Our pathways set by Your own hand.<br/>Gain more ground and bear more fruit<br/>Each day, grow in me,<br/>Defeat your enemy.<br/>',NULL,87359,1);
INSERT INTO stanza VALUES('NS1038','chorus','Let the Amen sound again—<br/>Let the Amen sound again—<br/>Let the Amen sound again—<br/>Amen, Amen! Amen, Amen!<br/>',NULL,87360,2);
INSERT INTO stanza VALUES('NS1038','2','Lord, I have no confidence<br/>In who I am or what I do.<br/>Only You are able to<br/>Endure and overcome;<br/>Sustain with just one word.<br/>',NULL,87361,3);
INSERT INTO stanza VALUES('NS1038','3','How we need Your life each day<br/>To wash our oldness all away.<br/>Renew me to be Spirit-filled;<br/>By your abundant grace<br/>We will run this race.<br/>',NULL,87362,4);
INSERT INTO stanza VALUES('NS1038','4','Shining in the darkest hour,<br/>Comfort us in every trial;<br/>Hold us in Your very hand,<br/>The Body life is real,<br/>Oh Lord You are so near.<br/>',NULL,87363,5);
INSERT INTO stanza VALUES('NS1038','5','Saving us from emptiness,<br/>Broken cisterns holding less,<br/>Deceitful riches, grasping air,<br/>Only You are preciousness.<br/>We will love You with our best.<br/>',NULL,87364,6);
INSERT INTO stanza VALUES('NS1038','6','Lord we praise You for Your way<br/>To free the flow of life each day<br/>In every joy or suffering<br/>Experienced, not vain—<br/>We would not be put to shame.<br/>',NULL,87365,7);
INSERT INTO stanza VALUES('NS1038','chorus','Let our Amen sound again—<br/>Let our Amen sound again—<br/>Let our Amen sound again—<br/>Amen, Amen! Amen, Amen!<br/>(Amen Amen! Amen!)<br/>',NULL,87366,8);
INSERT INTO stanza VALUES('NS1039','1','Because the very God<br/>Who commanded light to shine,<br/>Light to shine out of darkness,<br/>Has shined in our hearts.<br/>',NULL,87367,1);
INSERT INTO stanza VALUES('NS1039','chorus','Because the God who said,<br/>Out of darkness light shall shine,<br/>Is the One who shined in our hearts<br/>For the illumination<br/>Of the knowledge<br/>Of the glory of God<br/>In the face of Christ,<br/>In the face of Christ.<br/>',NULL,87368,2);
INSERT INTO stanza VALUES('NS1039','2','In the universe His shining<br/>Produced the old creation,<br/>His new creation’s made by<br/>Shining in our hearts.<br/>',NULL,87369,3);
INSERT INTO stanza VALUES('NS1039','3','God’s shining results in<br/>The illumination,<br/>Knowing God’s glory<br/>In the face of Christ.<br/>',NULL,87370,4);
INSERT INTO stanza VALUES('NS1039','4','This enlightenment that<br/>Does make known the glory<br/>Issues from the shining<br/>Of God in our hearts.<br/>',NULL,87371,5);
INSERT INTO stanza VALUES('NS1040','1','Whither shall I go from Thy Spirit, Lord?<br/>Or where shall I flee from Thy presence, Lord?<br/>If I rise to heaven, lo, Thou art there.<br/>If I lie in Sheol’s depths, Thou art also there.<br/>If I should take dawn’s wings, to dwell at sea’s remotest bound’ries,<br/>E’en there Thy hand shall lead me still, Thy hand shall lead me;<br/>Thy right hand shall take hold of me; it shall take hold of me;<br/>Lord, Thou art everywhere.<br/>(Repeat)<br/>Lord, Thou art always there.<br/>',NULL,87372,1);
INSERT INTO stanza VALUES('NS1041','1','There’s a secret we must learn from<br/>Joseph’s life so long ago.<br/>How he came to be one reigning,<br/>This is what we must come to know.<br/>',NULL,87373,1);
INSERT INTO stanza VALUES('NS1041','chorus','See the vision of God’s people;<br/>They are sheaves so full of life.<br/>And regardless how we see them,<br/>In God’s view they are full of light.<br/>',NULL,87374,2);
INSERT INTO stanza VALUES('NS1041','2','But before we will be reigning,<br/>God knows we must be confined.<br/>Just like Joseph in his prison,<br/>There’s a secret to this, we will find.<br/>',NULL,87375,3);
INSERT INTO stanza VALUES('NS1041','chorus','God is with us in our troubles,<br/>And on Him we can rely.<br/>Even though we may not see it,<br/>God is with us to be our supply.<br/>',NULL,87376,4);
INSERT INTO stanza VALUES('NS1041','3','Even in all of our troubles,<br/>Some may come to us in need.<br/>In their seeking we can help them<br/>Come to God, and let Him take the lead.<br/>',NULL,87377,5);
INSERT INTO stanza VALUES('NS1041','chorus','Through our speaking of God’s vision,<br/>Oh, the more we’ll be released!<br/>Speak the “dreams” that God has shown you.<br/>Speak with God’s full authority!<br/>',NULL,87378,6);
INSERT INTO stanza VALUES('NS1041','4','Now the secret to our reigning<br/>Is to first be ruled by God.<br/>Oh, we need the Spirit’s ruling<br/>In our life through the long path we trod.<br/>',NULL,87379,7);
INSERT INTO stanza VALUES('NS1041','chorus','Give your life over to Jesus;<br/>Then you’ll have a full supply,<br/>And to others be a blessing,<br/>In all things, as you “reign in life!”<br/>',NULL,87380,8);
INSERT INTO stanza VALUES('NS1042','1','The first status of the church, is the assembly of God.<br/>The first status of the church, is the assembly of God.<br/>The first status of the church, is the assembly of God.<br/>He called and gathered us from abroad.<br/>“We’ve been called out from the world for the purpose of God!”<br/>',NULL,87381,1);
INSERT INTO stanza VALUES('NS1042','2','The second status of the church, is the house of God.<br/>The second status of the church, is the house of God.<br/>The second status of the church, is the house of God.<br/>As His family we praise and laud,<br/>“Oh the church is the household of the living God!”<br/>',NULL,87382,2);
INSERT INTO stanza VALUES('NS1042','3','The third status of the church, is the dwelling place of God.<br/>The third status of the church, is the dwelling place of God.<br/>The third status of the church, is the dwelling place of God.<br/>It’s in our spirit, as along we trod,<br/>God expresses Himself we see, in the dwelling place of God!<br/>',NULL,87383,3);
INSERT INTO stanza VALUES('NS1042','4','The fourth status of the church, is the kingdom of God.<br/>The fourth status of the church, is the kingdom of God.<br/>The fourth status of the church, is the kingdom of God.<br/>He reigns in us as the “budding rod,”<br/>As in spirit we live and walk for the kingdom of God!<br/>',NULL,87384,4);
INSERT INTO stanza VALUES('NS1042','5','The fifth status of the church, is the Body of Christ.<br/>The fifth status of the church, is the Body of Christ.<br/>The fifth status of the church, is the Body of Christ.<br/>In one Spirit we were all baptized.<br/>Members now joined to the Head, as the Body of Christ!<br/>',NULL,87385,5);
INSERT INTO stanza VALUES('NS1042','6','The sixth status of the church, is God’s masterpiece.<br/>The sixth status of the church, is God’s masterpiece.<br/>The sixth status of the church, is God’s masterpiece.<br/>We’re the poem of His heart, that’s pleased.<br/>Only the church can truly be God’s masterpiece!<br/>',NULL,87386,6);
INSERT INTO stanza VALUES('NS1042','7','The seventh status of the church, is the one new man.<br/>The seventh status of the church, is the one new man.<br/>The seventh status of the church, is the one new man.<br/>Created in Christ through the cross—His plan.<br/>Now God’s purpose is fulfilled in the one new man!<br/>',NULL,87387,7);
INSERT INTO stanza VALUES('NS1042','8','The eighth status of the church, is the counterpart of Christ.<br/>The eighth status of the church, is the counterpart of Christ.<br/>The eighth status of the church, is the counterpart of Christ.<br/>He gave His life to obtain His wife.<br/>We’ll be married to Him fore’er as the counterpart of Christ!<br/>',NULL,87388,8);
INSERT INTO stanza VALUES('NS1042','9','The last status of the church is the golden lampstands,<br/>The last status of the church is the golden lampstands,<br/>The last status of the church is the golden lampstands,<br/>They shine through the dark as only they can.<br/>Oh, the New Jerusalem is a golden lampstand!<br/>',NULL,87389,9);
INSERT INTO stanza VALUES('NS1043','1','Christ is the off’ring making God happy;<br/>No fault in Him could ever be found.<br/>Qualified fully, absolute, pleasing;<br/>Fragrance ascends; His praises we sound.<br/>',NULL,87390,1);
INSERT INTO stanza VALUES('NS1043','chorus','Chorus 1:<br/>Perfect obedience, led to the slaughter,<br/>Burnt offering dear, afflicted and cut;<br/>Many a skinning, many a stripping;<br/>Slanderous words, He would not rebut.<br/>',NULL,87391,2);
INSERT INTO stanza VALUES('NS1043','2','Christ’s life with mine now one and the same is.<br/>Union, communion, fellowship sweet,<br/>I lay my hand on His head most beauteous;<br/>All of His virtues flow into me.<br/>',NULL,87392,3);
INSERT INTO stanza VALUES('NS1043','chorus','Chorus 2:<br/>Wholly accepted! Turned into ashes!<br/>Released from self, my old man has died!<br/>Burn me, reduce me, till I am nothing;<br/>Hail resurrection; hail the sunrise!<br/>',NULL,87393,4);
INSERT INTO stanza VALUES('NS1043','3','Manger to cross, the life of the God-man,<br/>His story now my story will be.<br/>Could I myself say yes to be slaughtered?<br/>Never! yet through Him, “Yes, willingly!”<br/>',NULL,87394,5);
INSERT INTO stanza VALUES('NS1043','4','What He experienced, I would experience;<br/>What He passed through, I enter into.<br/>Loving and tender, to Him surrender,<br/>Two parties meld, one living pursue.<br/>',NULL,87395,6);
INSERT INTO stanza VALUES('NS1043','5','Fire not of wrath nor judgment nor terror,<br/>‘Twas love I met there, warmed on the hearth.<br/>I could approach Him, and He embraced me,<br/>Fully received me, filled me with mirth.<br/>',NULL,87396,7);
INSERT INTO stanza VALUES('NS1043','6','All through the dark night, tend to the fire;<br/>O Lord, our love rekindle anew.<br/>That, life to life, a savor far-reaching,<br/>We’d conquer captives, add men to You.<br/>',NULL,87397,8);
INSERT INTO stanza VALUES('NS1043','7','Worldlings despise us, count us as nothing,<br/>Yet to our God we’re precious indeed.<br/>Highly regarded, ashes to gemstones,<br/>Treasure-built city’s our destiny!<br/>',NULL,87398,9);
INSERT INTO stanza VALUES('NS1044','1','And when You pray, pray in this way:<br/>Our Father in the heavens,<br/>Thy name be sanctified;<br/>Thy kingdom come; Thy will be done,<br/>On earth as in the heavens.<br/>',NULL,87399,1);
INSERT INTO stanza VALUES('NS1044','2','Give us today our daily bread.<br/>Forgive us of our debts,<br/>O Lord, as we’ve forgiv’n debts too.<br/>Bring us not to temptation,<br/>But deliver us from evil.<br/>',NULL,87400,2);
INSERT INTO stanza VALUES('NS1044','3','For Yours the kingdom is,<br/>The power, glory too<br/>Forever, forever. Amen, Amen.<br/>Forever, forever. Amen, Amen.<br/>',NULL,87401,3);
INSERT INTO stanza VALUES('NS1045','1','The Spirit is the sphere and element<br/>Of our spiritual baptism;<br/>In such a Spirit we were baptized<br/>Into one organic entity.<br/>',NULL,87402,1);
INSERT INTO stanza VALUES('NS1045','2','Regardless of our social ranks,<br/>Our races and nationalities,<br/>As we were baptized in such a Spirit,<br/>We should all be the Body of Christ.<br/>',NULL,87403,2);
INSERT INTO stanza VALUES('NS1045','3','The sphere and element the Spirit is,<br/>And of Christ the reality;<br/>Christ is the life and constituent<br/>Constituent of this Body.<br/>',NULL,87404,3);
INSERT INTO stanza VALUES('NS1045','4','The sphere and element the Spirit is;<br/>It is in this one Spirit<br/>That we were all baptized into<br/>This one living Body to express Christ.<br/>',NULL,87405,4);
INSERT INTO stanza VALUES('NS1046','1','For whatever promises of God there are,<br/>In Him is the Yes;<br/>For whatever promises of God there are,<br/>In Him is the Yes.<br/>',NULL,87406,1);
INSERT INTO stanza VALUES('NS1046','chorus','Christ is the Yes, the incarnate answer,<br/>the fulfillment of all;<br/>Christ is the Yes, the fulfillment of all<br/>the promises of God to us.<br/>',NULL,87407,2);
INSERT INTO stanza VALUES('NS1046','2','Wherefore also through Him is the Amen,<br/>Amen to God.<br/>Wherefore also through Him is the Amen,<br/>For glory through us.<br/>',NULL,87408,3);
INSERT INTO stanza VALUES('NS1046','chorus','The Amen given by us through Christ,<br/>by us through Christ to God.<br/>Christ is the Yes, and we say Amen<br/>to this Yes before God.<br/>',NULL,87409,4);
INSERT INTO stanza VALUES('NS1046','note','<br/>',NULL,87410,5);
INSERT INTO stanza VALUES('NS1047','1','You are the Potter, and I am the clay.<br/>Every experience You have arranged.<br/>My life is in Your hands.<br/>Shape me, do all You can.<br/>Lord, by Your mercy I’m seeking You still.<br/>Though weak and sinful, I long to be filled.<br/>You gave me a soft heart.<br/>Keep me! Your life impart.<br/>',NULL,87411,1);
INSERT INTO stanza VALUES('NS1047','chorus','I’m Your vessel unto honor,<br/>And made for Your glory.<br/>You’re my treasure within.<br/>I was made to contain You.<br/>Fill me with riches divine,<br/>That Your life may be expressed through mine.<br/>I’m Your vessel.<br/>I’m Your vessel.<br/>',NULL,87412,2);
INSERT INTO stanza VALUES('NS1047','2','May there be nothing else taking Your place.<br/>Everything other than You is a waste.<br/>Cleanse me, empty my heart.<br/>Fill me in every part.<br/>Lord, make me willing to pay any price<br/>To gain the oil, to be filled up with Christ.<br/>May I redeem the time.<br/>Grant me more life divine.<br/>',NULL,87413,3);
INSERT INTO stanza VALUES('NS1047','3','Lord, may I open and gain You each day<br/>In such a steady and unfailing way.<br/>On Your name I would call,<br/>Loving You above all.<br/>Fill all my vision, remain in my view.<br/>As I’m beholding my life reflects You.<br/>Gazing, being infused,<br/>Others then will see You.<br/>',NULL,87414,4);
INSERT INTO stanza VALUES('NS1047','copyright','<br/>',NULL,87415,5);
INSERT INTO stanza VALUES('NS1048','1','Your gentle pum-pum-pum<br/>Now whispers tenderly,<br/>Telling me what You want to be to me.<br/>Rhema, in clear relief,<br/>Full color, does beseech,<br/>Not black and white, but with my name inside:<br/>“Meet Me in the Word, child,<br/>It’s how I’ll make you smile,<br/>Amidst the crushing pressures,<br/>And for the endless trials,<br/>I’ve therapy to target<br/>The ailments that beset<br/>Your hurting soul; dear one, I know<br/>Which medicine cures woe.”<br/>',NULL,87416,1);
INSERT INTO stanza VALUES('NS1048','2','“Rain, dew, abundant showers,<br/>Snow, cleansing, with the power<br/>To remedy the ache of secret grief.<br/>Hammer and burning fire,<br/>Smash Satan, he’s a liar,<br/>Break strongholds,<br/>Melt your icy heart, most cold.<br/>Meet Me in the Word, child,<br/>And linger for a while;<br/>Sweet honey for the bitter<br/>Environments that defile<br/>Your standing as my treasure;<br/>My word will purify:<br/>Dividing soul from spirit, so<br/>That by the word you’ll grow.”<br/>',NULL,87417,2);
INSERT INTO stanza VALUES('NS1049','1','The Christian life, a Christ-filled life,<br/>A life of living Christ as life,<br/>Is Christ my person and my grace,<br/>A life of living face to face.<br/>',NULL,87418,1);
INSERT INTO stanza VALUES('NS1049','chorus','The Christian life, a loving life,<br/>A life of loving freed from strife,<br/>Is God in Christ as love poured out,<br/>Enjoyed within, expressed without.<br/>',NULL,87419,2);
INSERT INTO stanza VALUES('NS1049','2','The Christian life is God in Christ,<br/>A priceless treasure and our life;<br/>We turn, behold, reflect, and see,<br/>E’en as He is, we all shall be.<br/>',NULL,87420,3);
INSERT INTO stanza VALUES('NS1049','chorus','The Christian life, a broken life,<br/>A life no longer I, but Christ,<br/>Is Christ our fragrance and our taste,<br/>By Spirit: holy, pure, and chaste.<br/>',NULL,87421,4);
INSERT INTO stanza VALUES('NS1049','3','The Christian life, a grafted life,<br/>Is found in our Lord Jesus Christ;<br/>And by His cutting on the Tree<br/>A place was made for you and me.<br/>',NULL,87422,5);
INSERT INTO stanza VALUES('NS1049','chorus','The Christian life, a grafted life,<br/>Is Christ’s desire, and God’s delight;<br/>Organic union with the Lord,<br/>We live in Christ in one accord.<br/>',NULL,87423,6);
INSERT INTO stanza VALUES('NS1049','4','The Christian life, a growing life,<br/>Joined to the resurrected Christ,<br/>In Spirit grows organically,<br/>To be His Body practically.<br/>',NULL,87424,7);
INSERT INTO stanza VALUES('NS1049','chorus','The Christian life, maturing life,<br/>Is Christ in all to be applied;<br/>Tis not exchanged but mingled in,<br/>The richest life with mine does blend.<br/>',NULL,87425,8);
INSERT INTO stanza VALUES('NS1050','1','Appear to me, dear Lord,<br/>Appear to me.<br/>I need Thee desperately<br/>To appear to me.<br/>Come Lord as light divine<br/>Into my heart to shine<br/>Till I am wholly Thine.<br/>Appear to me.<br/>',NULL,87426,1);
INSERT INTO stanza VALUES('NS1050','2','O God of Glory, now<br/>Appear to me;<br/>Just as with Abraham,<br/>Shine repeatedly.<br/>Come, Lord, expose with light<br/>What idols I hold tight.<br/>Be more my heart’s delight;<br/>Appear to me.<br/>',NULL,87427,2);
INSERT INTO stanza VALUES('NS1050','3','When, Lord, I drag my feet,<br/>Appear to me.<br/>When things with Thee compete,<br/>Lord, appear to me.<br/>Light from Thy glorious face<br/>Infuses me with grace<br/>That I may run the race.<br/>Appear to me.<br/>',NULL,87428,3);
INSERT INTO stanza VALUES('NS1050','4','Lord, as each day goes by,<br/>Appear to me<br/>Till face to face, so nigh,<br/>I shall always be,<br/>Looking away to Thee,<br/>With eyes so lovingly,<br/>For all eternity;<br/>Appear to me.<br/>',NULL,87429,4);
INSERT INTO stanza VALUES('NS1051','1','God of the universe, God of my heart,<br/>Come and renew me, I need a new start;<br/>Into my spirit, then into my soul,<br/>Into my body, revive, Lord, the whole.<br/>No one but You, Lord, can do what You do.<br/>And You’ve already done so much.<br/>I open up to You.<br/>Jesus, I just love You.<br/>',NULL,87430,1);
INSERT INTO stanza VALUES('NS1052','1','All scripture, all scripture,<br/>All scripture is God-breathed,<br/>All scripture is God-breathed,<br/>God-breathed, God-breathed,<br/><br/>And profitable for teaching,<br/>For conviction, for correction, for instruction<br/>In righteousness, in righteousness,<br/>That the man of God may be complete,<br/>Fully equipped for every good work.<br/><br/>All scripture, all scripture,<br/>All scripture is God-breathed,<br/>Second Timothy chapter three:<br/>Sixteen and seventeen.<br/>',NULL,87431,1);
INSERT INTO stanza VALUES('NS1053','1','Lord, make us like Daniel<br/>And his companions to turn this age.<br/>Your chosen ones have been taken captive,<br/>Filled up with worldly food<br/>And loving other things.<br/>',NULL,87432,1);
INSERT INTO stanza VALUES('NS1053','chorus','O Lord Jesus! Make us Your overcomers,<br/>Men of prayer who live under Your rule,<br/>Rejecting every idol,<br/>Filled up with Your Word as food,<br/>Consecrated unto You.<br/>',NULL,87433,2);
INSERT INTO stanza VALUES('NS1053','2','Lord, through every fire<br/>You’re with us, in us unto the end.<br/>Joined to Your Word and Your heart’s desire,<br/>Supplied and strengthened we<br/>Pursue You with our friends.<br/>',NULL,87434,3);
INSERT INTO stanza VALUES('NS1053','3','Lord, through us gain others.<br/>May all our brothers return to be<br/>Built as Your house, city, and Your kingdom<br/>For Your expression and authority,<br/>Your life divine for all to see.<br/>Forever we’ll display Your victory!<br/>',NULL,87435,4);
INSERT INTO stanza VALUES('NS1053','note','<br/>',NULL,87436,5);
INSERT INTO stanza VALUES('NS1053','copyright','<br/>',NULL,87437,6);
INSERT INTO stanza VALUES('NS1054','1','Lord, much more do I need<br/>Your full salvation worked out in me.<br/>All I have is today,<br/>So for Your purpose, Lord, have Your way.<br/>Fan my spirit into flame;<br/>Lord, don’t let me stay the same.<br/>',NULL,87438,1);
INSERT INTO stanza VALUES('NS1054','2','Lord, be my Amen;<br/>Subdue my will, don’t let me win.<br/>Though my feelings deceive,<br/>I stand by faith, Your grace I receive.<br/>Lord, take captive my every thought;<br/>Make Your home in all of my heart.<br/>',NULL,87439,2);
INSERT INTO stanza VALUES('NS1054','3','Strengthen my trust in You,<br/>That all things work together for good,<br/>Not according to me,<br/>But so that You’d be wrought in my being.<br/>Though sometimes I don’t understand,<br/>Lord, I trust in Your loving hands.<br/>',NULL,87440,3);
INSERT INTO stanza VALUES('NS1054','4','Deepen my love for you;<br/>Make me a lily, simple and pure.<br/>Other things in my heart<br/>Empty; unload me, Your love impart.<br/>Draw my eyes to see only You.<br/>Dear Lord Jesus, how I love You.<br/>',NULL,87441,4);
INSERT INTO stanza VALUES('NS1054','5','Lift my eyes up to see,<br/>All that You do is not just for me.<br/>It’s the church as Your bride<br/>Who satisfies Your heart’s desire.<br/>Of Your Body, grant me Your view.<br/>Draw me, we will run after You.<br/>',NULL,87442,5);
INSERT INTO stanza VALUES('NS1054','6','Thank You for who You are,<br/>All that we can’t be; Lord be our All.<br/>Praise You, Lord, as the One<br/>Who over all things is on the throne.<br/>By Your mercy we’re justified;<br/>But much more, save us in Your life.<br/>Lord, much more, save us in Your life.<br/>',NULL,87443,6);
INSERT INTO stanza VALUES('NS1055','1','But you are a chosen race, a royal priesthood, a holy nation,<br/>But you are a chosen race, a royal priesthood, a holy nation,<br/>A people acquired for a possession,<br/>So that you may tell out the virtues of Him,<br/>A people acquired for a possession,<br/>So that you may tell out the virtues of Him<br/>Who has called you, who has called you<br/>Out of darkness into His marvelous light;<br/>Who has called you, who has called you<br/>Out of darkness into His marvelous light;<br/>Out of darkness into His marvelous light.<br/>',NULL,87444,1);
INSERT INTO stanza VALUES('NS1056','1','All around us, enemies;<br/>Helpless, hopeless, we’re besieged.<br/>Lord, we don’t know what to do;<br/>Lord, we set our eyes on You.<br/>Now’s the time, against all odds,<br/>To declare the worth of God,<br/>Ambush Satan, change the course,<br/>For the battle is the Lord’s.<br/>',NULL,87445,1);
INSERT INTO stanza VALUES('NS1056','chorus','Praise the Lord!<br/>The battle’s Yours!<br/>The battle is the Lord’s!<br/>Win with shouts of praise outpoured,<br/>For the battle is the Lord’s!<br/>',NULL,87446,2);
INSERT INTO stanza VALUES('NS1056','2','Days of suffering, loss, and pain,<br/>Yet it’s now that You must gain<br/>A true faith that would surpass<br/>The fraught mind that tries to grasp<br/>How such things could be allowed,<br/>Tries to plot its own way out:<br/>No, we shout, we praise, we soar,<br/>For the battle is the Lord’s.<br/>',NULL,87447,3);
INSERT INTO stanza VALUES('NS1056','chorus','Praise the Lord!<br/>The battle’s Yours!<br/>You hear us and You save<br/>When the thunderous notes of praise<br/>Singers shout, our voice we raise.<br/>',NULL,87448,4);
INSERT INTO stanza VALUES('NS1056','3','We don’t have to understand,<br/>Safely hidden in Your hand,<br/>Our salvation, here, from God—<br/>We transcend, rise far above,<br/>Freed from Satan’s earthly snares,<br/>Rout his forces in the air;<br/>Praise our Victor-in-Control,<br/>For the battle is the Lord’s.<br/>',NULL,87449,5);
INSERT INTO stanza VALUES('NS1056','chorus','Praise the Lord!<br/>The battle’s Yours!<br/>The battle is the Lord’s!<br/>Ringing faith we sound in war,<br/>For the battle is the Lord’s!<br/>',NULL,87450,6);
INSERT INTO stanza VALUES('NS1057','1','A wise man fears and departs from evil,<br/>Proverbs 14:16a.<br/>A wise man fears and departs from evil,<br/>Proverbs 14:16a.<br/>',NULL,87451,1);
INSERT INTO stanza VALUES('NS1057','2','Beloved, do not imitate the evil,<br/>But the good.<br/>Beloved, do not imitate the evil,<br/>But the good.<br/>',NULL,87452,2);
INSERT INTO stanza VALUES('NS1058','1','I don’t need anything other than You—it’s true.<br/>So why do I live the way that I do, without You?<br/>’Cuz sometimes I spend my days living my own life,<br/>’Till I get tired of all my strife.<br/>That’s when I pray:<br/>',NULL,87453,1);
INSERT INTO stanza VALUES('NS1058','chorus','Fill me up, up, up! Fill me up, up, up!<br/>Fill me up with the riches of Christ.<br/>Fill me up, up, up! Fill me up, up, up!<br/>I don’t have to live my old life.<br/>',NULL,87454,2);
INSERT INTO stanza VALUES('NS1058','2','Christ now is living inside of me even me!<br/>His riches can become my reality—within me.<br/>Lord, build me with other saints so that I may know<br/>Your breadth, length, depth, height, and love.<br/>O Lord, I pray:<br/>',NULL,87455,3);
INSERT INTO stanza VALUES('NS1058','verse','Bridge:<br/>When I’m in darkness—You are light.<br/>When I’m in death—You are life.<br/>When am I weak—You are strong.<br/>Live in me all day long.<br/>O Lord, I pray:<br/>',NULL,87456,4);
INSERT INTO stanza VALUES('NS1058','chorus','Fill me up, up, up! Fill me up, up, up!<br/>Fill me up with the riches of Christ.<br/>Fill me up, up, up! Fill me up, up, up!<br/>I don’t have to live my old life.<br/>Live Christ.<br/>',NULL,87457,5);
INSERT INTO stanza VALUES('NS1058','chorus','Countermelody 1:<br/>His life, light, righteousness, holiness, what He accomplished,<br/>Attained, and obtained are for us.<br/>His life, light, righteousness, holiness, what He accomplished,<br/>Attained, and obtained are for us.<br/>Live Christ.<br/>',NULL,87458,6);
INSERT INTO stanza VALUES('NS1058','chorus','Countermelody 2:<br/>Partake and enjoy<br/>All the riches of Christ;<br/>Then the church will become<br/>The full expression of God.<br/>Live Christ.<br/>',NULL,87459,7);
INSERT INTO stanza VALUES('NS1058','note','<br/>',NULL,87460,8);
INSERT INTO stanza VALUES('NS1058','copyright','<br/>',NULL,87461,9);
INSERT INTO stanza VALUES('NS1059','1','Lord, how sweet when touching You!<br/>Your great love draws me to<br/>Come forth to seek for You.<br/>In Your dear presence, no more weariness;<br/>You bear all my burdens, too.<br/>',NULL,87462,1);
INSERT INTO stanza VALUES('NS1059','2','Lord, how joyful, touching You!<br/>Your love draws me anew<br/>To truly rest in You.<br/>In Your bright presence, no more darkness;<br/>Your light guides me through.<br/>',NULL,87463,2);
INSERT INTO stanza VALUES('NS1059','3','O Lord Jesus, Holy Spirit dwelling now in us,<br/>In Your presence mingled into oneness now are we;<br/>Overflowing every day with joy that springs from deep in us,<br/>Now we all rejoice abundantly.<br/>',NULL,87464,3);
INSERT INTO stanza VALUES('NS1060','1','O Spirit in the word,<br/>The Triune God expressed.<br/>The richest Christ transfused,<br/>Receive by Spirit’s breath.<br/>So let’s inhale Him…<br/>',NULL,87465,1);
INSERT INTO stanza VALUES('NS1060','chorus','O Word of God!<br/>My spirit breathes,<br/>Your Spirit and life<br/>Supply me forever,<br/>And make me a God-man complete.<br/>',NULL,87466,2);
INSERT INTO stanza VALUES('NS1060','2','The scripture God has breathed,<br/>So I must breathe it in.<br/>Unveiling thus received,<br/>Convicting me within.<br/>Such revelation…<br/>',NULL,87467,3);
INSERT INTO stanza VALUES('NS1060','3','The veils fall from my eyes,<br/>Myself I see, abhor.<br/>Exposed I just confess,<br/>I’m crooked, wrong, and short.<br/>The blood is washing…<br/>',NULL,87468,4);
INSERT INTO stanza VALUES('NS1060','4','Corrected, I’m restored,<br/>And made upright again.<br/>The revelation yields<br/>Sweet fruits of righteousness.<br/>I love His shining…<br/>',NULL,87469,5);
INSERT INTO stanza VALUES('NS1060','5','Instructed in the light,<br/>From Christ’s enlight’ning word,<br/>Rebuilding over time,<br/>My heart by life restored.<br/>He’s making home there…<br/>',NULL,87470,6);
INSERT INTO stanza VALUES('NS1060','6','O living Spirit-sword,<br/>Apply Yourself to me.<br/>Pierce through, even divide,<br/>My soul and spirit freed.<br/>So I can live You…<br/>',NULL,87471,7);
INSERT INTO stanza VALUES('NS1060','7','So take the word by prayer,<br/>The Spirit to apply,<br/>The foes and germs are slain<br/>With flesh and self thereby.<br/>To walk in newness…<br/>',NULL,87472,8);
INSERT INTO stanza VALUES('NS1060','8','So nourish me today,<br/>My Breath and living Bread.<br/>Come live through me I pray,<br/>And soon come back again!<br/>Yes, come Lord Jesus!<br/>',NULL,87473,9);
INSERT INTO stanza VALUES('NS1061','1','And to enlighten all<br/>That they may see<br/>What the economy<br/>Of the mystery is,<br/>Which throughout the ages<br/>Has been hidden in God,<br/>Who created all things,<br/>(repeat)<br/>',NULL,87474,1);
INSERT INTO stanza VALUES('NS1061','2','In order that now to the rulers<br/>And the authorities in the heavenlies<br/>The multifarious wisdom of God<br/>Might be made known through the church,<br/>According to th’eternal purpose<br/>Which He made in Christ Jesus our Lord,<br/>In whom we have boldness and access in confidence<br/>Through faith in Him.<br/>',NULL,87475,2);
INSERT INTO stanza VALUES('NS1061','3','And to enlighten all<br/>That they may see<br/>What the economy<br/>Of the mystery is,<br/>Which throughout the ages<br/>Has been hidden in God,<br/>Who created all things,<br/>(repeat)<br/>',NULL,87476,3);
INSERT INTO stanza VALUES('NS1061','chorus','Ephesians three nine through twelve.<br/>',NULL,87477,4);
INSERT INTO stanza VALUES('NS1062','1','Grace is Christ multiplied and Christ enjoyed<br/>Under God’s loving care;<br/>The more the sufferings, burdens, and trials,<br/>The more the grace will bear.<br/>',NULL,87478,1);
INSERT INTO stanza VALUES('NS1062','chorus','Grace, grace! Abundance of grace!<br/>Superabounding grace!<br/>Grace multiplied, grace prophesied,<br/>Grace, all grace, and true.<br/>',NULL,87479,2);
INSERT INTO stanza VALUES('NS1062','2','Grace that was prophesied in ancient times,<br/>The Spirit has made clear;<br/>Christ’s all-sufficient, unlimited grace<br/>Is to our hearts so dear.<br/>',NULL,87480,3);
INSERT INTO stanza VALUES('NS1062','3','The grace of life to the saints, strong and weak,<br/>Is God as life supplied;<br/>His divine Trinity flowing is grace,<br/>Christ in us magnified.<br/>',NULL,87481,4);
INSERT INTO stanza VALUES('NS1062','4','The varied grace of God, riches of life,<br/>Ministered by the saints,<br/>Conveys the gracious, sweet words of Christ<br/>With strength which never faints.<br/>',NULL,87482,5);
INSERT INTO stanza VALUES('NS1062','5','Grace to the humble the Grace-giver gives,<br/>But He resists the proud;<br/>Cast all your cares and fears onto God,<br/>No worry to allow.<br/>',NULL,87483,6);
INSERT INTO stanza VALUES('NS1062','6','The God of all grace, the true grace of God,<br/>In God’s economy,<br/>Consummates into the City of Grace,<br/>Grace in eternity.<br/>',NULL,87484,7);
INSERT INTO stanza VALUES('NS1063','1','Thou, Lord, my Christ, hast found me,<br/>And clasped me to Thy breast,<br/>When I was lost in darkness,<br/>Alone in deep distress;<br/>So hurt and pained by sin inside,<br/>A troubled soul—no hope could find,<br/>But Lord, Thou came, with oil and wine,<br/>Thou bound my wounds—brought love divine!<br/>',NULL,87485,1);
INSERT INTO stanza VALUES('NS1063','2','And like that desperate woman,<br/>I stretched my hand to grasp—<br/>For nothing else could cure me,<br/>But lo, the One, at last!<br/>Thy human virtues God reveals,<br/>In Thee a love so pure and real,<br/>In Thee, the Holy One concealed,<br/>Thy words and all Thine actions heal.<br/>',NULL,87486,2);
INSERT INTO stanza VALUES('NS1063','3','Thy touch, O Lord, has healed me,<br/>My heart of stone replaced,<br/>A heart of flesh now in me,<br/>To love Thee Lord always;<br/>But still Thy life spreads in my heart,<br/>Thy flowing streams must reach each part,<br/>Pour in Thy life—more love impart,<br/>O let Thy life renew each part.<br/>',NULL,87487,3);
INSERT INTO stanza VALUES('NS1063','4','O may Thy Church bring healing<br/>To every sick, lost soul,<br/>So many hurt and broken,<br/>So many with no home.<br/>O fill us Lord, and us now send,<br/>Restore through us the wounds of men,<br/>We’ll bind, anoint, bring to Thine inn,<br/>Pour oil and wine—make whole and mend.<br/>',NULL,87488,4);
INSERT INTO stanza VALUES('NS1064','1','Peace I leave with you,<br/>My peace I give to you;<br/>Not as the world<br/>Gives do I,<br/>I give to you.<br/>Do not let your heart be troubled,<br/>Neither let it be afraid.<br/>Peace I leave with you,<br/>My peace I give to you;<br/>Peace I leave with you,<br/>My peace I give to you;<br/>To you.<br/>John 14:27<br/>',NULL,87489,1);
INSERT INTO stanza VALUES('NS1065','1','So lawless runs the fallen earth,<br/>Pursuing sin for all it’s worth—<br/>We’ll turn and take another way, another way.<br/>Lord, reign in us! With open heart<br/>We welcome You in every part;<br/>Your kingdom come in us today, in us today.<br/>',NULL,87490,1);
INSERT INTO stanza VALUES('NS1065','chorus','One day all knees will bow;<br/>Jesus, we confess You now—<br/>We proclaim You Lord today.<br/>Though there’s darkness all around,<br/>With Your sons the light abounds,<br/>And we’ll praise You, praise You on our way.<br/>',NULL,87491,2);
INSERT INTO stanza VALUES('NS1065','2','Usurped and under Satan’s sway,<br/>God’s will opposed in every way—<br/>This age pulls like a mighty tide, a mighty tide.<br/>O Lord, our every thought renew,<br/>Our eyes keep drawing unto You,<br/>Our feet plant firmly on Your side, Lord, on Your side.<br/>',NULL,87492,3);
INSERT INTO stanza VALUES('NS1065','3','O King of glory, come, we pray!<br/>Transform us more, Lord, day by day<br/>That life on earth would not be vain, would not be vain.<br/>Oh, make us those who meet Your need,<br/>Provide a beachhead that will speed<br/>Your coming back to rule and reign, to rule and reign!<br/>',NULL,87493,4);
INSERT INTO stanza VALUES('NS1065','copyright','<br/>',NULL,87494,5);
INSERT INTO stanza VALUES('NS1066','1','A normal Christian life should be one that is filled,<br/>Filled with the word,<br/>A normal Christian life should be one that is filled,<br/>Filled with the word,<br/>',NULL,87495,1);
INSERT INTO stanza VALUES('NS1066','2','That the Spirit may bubble over with praise<br/>And lauding melodies from within,<br/>That the Spirit may bubble over with praise<br/>And lauding melodies from within…<br/>',NULL,87496,2);
INSERT INTO stanza VALUES('NS1066','3','The believers. From within<br/>The believers. From within<br/>The believers. From within<br/>The believers.<br/>',NULL,87497,3);
INSERT INTO stanza VALUES('NS1066','note','<br/>',NULL,87498,4);
INSERT INTO stanza VALUES('NS1067','1','I am the light, the light of the world;<br/>He who follows Me shall by no means<br/>Walk, walk in darkness,<br/>But shall have the light of life.<br/><br/>I am the light, the light of the world;<br/>He who follows Me shall by no means<br/>Walk, walk in darkness,<br/>But shall have the light of life.<br/><br/>I am the light of the world.<br/>',NULL,87499,1);
INSERT INTO stanza VALUES('NS1068','1','O Lord, we open to You.<br/>Come in now, flow in and break through.<br/>O Lord, revive and renew our minds and hearts.<br/>O Lord, release us we pray,<br/>From all things that lead us astray.<br/>O Lord, make every distraction fade away.<br/>',NULL,87500,1);
INSERT INTO stanza VALUES('NS1068','chorus','Bridge:<br/>Strengthen us in spirit to hear Your call today.<br/>',NULL,87501,2);
INSERT INTO stanza VALUES('NS1068','chorus','O Lord, we answer Your call.<br/>O Lord, we give You our all to<br/>Be part of whatever You’re doing<br/>on the earth.<br/>O Lord, keep moving in us<br/>For Your goal and purpose to<br/>Gain your glorious expression.<br/>O Lord Jesus!<br/>',NULL,87502,3);
INSERT INTO stanza VALUES('NS1068','2','O Lord, You died for our sins.<br/>By Your blood we’re cleansed from within.<br/>All of our failures have now been washed away.<br/>O Lord, You’re living within<br/>As the power of resurrection.<br/>Conquer our death and our sin. Bring us to life.<br/>',NULL,87503,4);
INSERT INTO stanza VALUES('NS1068','3','O Lord, You’re speaking today.<br/>Give us ears to hear what You say.<br/>O Lord, from everything else we turn away.<br/>O Lord, our eyes are on You.<br/>Fill our hearts and minds with the truth.<br/>O Lord, our whole life to You we consecrate.<br/>',NULL,87504,5);
INSERT INTO stanza VALUES('NS1068','copyright','<br/>',NULL,87505,6);
INSERT INTO stanza VALUES('NS1069','1','Serve Him! Serve Him! We can serve Him!<br/>In this age and in the next!<br/>For eternity we’ll serve Him!<br/>How we’ll serve Him, He knows best!<br/>What a privilege! What an honor!<br/>As His priests we are so blessed!<br/>',NULL,87506,1);
INSERT INTO stanza VALUES('NS1069','2','As His priests we must come forward,<br/>To enjoy our precious Lord!<br/>As we spend time in His presence,<br/>Oh what grace He does afford!<br/>So that when we serve together,<br/>We will serve in one accord!<br/>',NULL,87507,2);
INSERT INTO stanza VALUES('NS1069','3','As the basis of our service,<br/>His blood is our surety!<br/>It shuts up the mouth of Satan,<br/>Giving us full liberty!<br/>Christ is now our priestly clothing,<br/>“Stately robes” for service, He!<br/>',NULL,87508,3);
INSERT INTO stanza VALUES('NS1069','4','Now the key for all our service,<br/>Is not our ability.<br/>To “Serve Him!” we must in spirit,<br/>Come to Him continually!<br/>Spirit with our spirit working,<br/>Joined as one eternally!<br/>',NULL,87509,4);
INSERT INTO stanza VALUES('NS1070','1','For the love of Christ constrains,<br/>Presses on us from all sides,<br/>Holds us to a single end,<br/>Forcibly it limits us.<br/>For the love of Christ constrains,<br/>To one object we’re confined,<br/>Kept within its certain bounds,<br/>And shut up unto one line.<br/>',NULL,87510,1);
INSERT INTO stanza VALUES('NS1070','2','For the love of Christ constrains,<br/>As a narrow road with walls;<br/>In this way we are compelled<br/>By Christ’s love to live to Him.<br/>For the love of Christ constrains,<br/>One died on behalf of all,<br/>So conclude that all have died.<br/>To ourselves we may not live.<br/>',NULL,87511,2);
INSERT INTO stanza VALUES('NS1070','3','For the love of Christ constrains<br/>Us to live not to ourselves,<br/>But to Him who died for us,<br/>Who for us has now been raised.<br/>For the love of Christ constrains<br/>By the loving death of Christ,<br/>That we, motivated thus,<br/>Live a loving life for Him.<br/>',NULL,87512,3);
INSERT INTO stanza VALUES('NS1070','4','For the love of Christ constrains,<br/>Or we would not live to Him,<br/>Nor from old life would refrain,<br/>But His love does press us in.<br/>For the love of Christ constrains,<br/>Causes us our life to lose.<br/>Lord, we’re captive in Your love,<br/>Willingly we live to You.<br/>',NULL,87513,4);
INSERT INTO stanza VALUES('NS1071','1','I told the Lord, I’d die for Him,<br/>I thought I was so strong.<br/>Yet I three times, denied Him then<br/>In weakness, I was wrong.<br/>In shame, I followed far behind,<br/>But He looked back at me.<br/>He knew I’d fail and fall three times.<br/>Now weeping bitterly.<br/>',NULL,87514,1);
INSERT INTO stanza VALUES('NS1071','chorus','“And Peter,” means also “and you.”<br/>“And Peter,”—“I really love you.”<br/>The most beautiful music in the world!<br/>“And Peter,”—“I’m thinking of you.”<br/>“And Peter”—“My heart is for you.”<br/>Rise up, and go to see the Lord!<br/>',NULL,87515,2);
INSERT INTO stanza VALUES('NS1071','2','I wait three days in silent guilt<br/>I wish the Lord forgot.<br/>I wonder, could He love me still<br/>Is now my only thought<br/>But when He speaks my name so soft—<br/>Though others note it not—<br/>New hope and joy now fill my heart<br/>As He these tidings brought:<br/>',NULL,87516,3);
INSERT INTO stanza VALUES('NS1071','3','Your words my heart shall ever sing,<br/>And strengthen me to turn.<br/>Since willingly You died for me,<br/>Your love won’t cease to burn.<br/>I failed and fell, yet You still came<br/>And loved me e’en in sin.<br/>So now when I feel far away<br/>I hear these words again:<br/>',NULL,87517,4);
INSERT INTO stanza VALUES('NS1071','4','Now with Your love and strength’ning power<br/>Your sheep I’d shepherd here,<br/>And with this love You showed me now<br/>I’d feed the flock, so dear.<br/>This feeding builds the church in love—<br/>The love I felt that day.<br/>The Lord will never give us up.<br/>In faith, these words I say:<br/>',NULL,87518,5);
INSERT INTO stanza VALUES('NS1072','1','Lord Jesus, I love You<br/>And I love Your dwelling.<br/>You called me a “stone”<br/>For Your building today.<br/>God’s house is constructed<br/>With stones that are living,<br/>So building the church<br/>Is our growing this way.<br/>',NULL,87519,1);
INSERT INTO stanza VALUES('NS1072','chorus','Oh God of all grace,<br/>By Your ruling and breaking,<br/>Do strengthen me into<br/>My spirit today.<br/>Keep guarding my heart,<br/>With all vigilance taking<br/>The pathway of life,<br/>In Your building to stay.<br/>',NULL,87520,2);
INSERT INTO stanza VALUES('NS1072','2','Lord, grant me a growth<br/>In Your life, nothing hind’ring.<br/>Don’t let any obstacles<br/>In me remain.<br/>Receiving Your cross<br/>With its breaking and killing,<br/>Produce the good earth;<br/>In my heart have Your way.<br/>',NULL,87521,3);
INSERT INTO stanza VALUES('NS1072','3','I’m often distracted<br/>From Christ as the life-way;<br/>Though zealous and active,<br/>Imprisoned He stays.<br/>Ignoring His “No,”<br/>I rebel, take my own way.<br/>Subdue me to care for<br/>Each word that You say.<br/>',NULL,87522,4);
INSERT INTO stanza VALUES('NS1072','4','Lord, make me someone<br/>Who is fit for Your building.<br/>By dealing severely,<br/>No hind’rance remain.<br/>Your life grow within me<br/>Till fully maturing,<br/>Your Bride shines in glory<br/>For Your wedding day.<br/>',NULL,87523,5);
INSERT INTO stanza VALUES('NS1073','1','This wonderful faith and this super-excellent love<br/>Are out of the Triune God,<br/>Who earnestly desires to be joined to us<br/>To be our everything.<br/>',NULL,87524,1);
INSERT INTO stanza VALUES('NS1073','chorus','This Triune God passed through the process<br/>Of incarnation, crucifixion, resurrection from the dead,<br/>And ascension to the heavens on high<br/>And was ultimately consummated as<br/>the life-giving Spirit.<br/>',NULL,87525,2);
INSERT INTO stanza VALUES('NS1073','2','This Spirit of life, who includes divinity,<br/>Humanity, and Christ’s crucifixion,<br/>Resurrection, and ascension and is the reality<br/>Of the all-inclusive Christ,<br/>Dwells in our regenerated spirit,<br/>Dwells in our regenerated spirit.<br/>',NULL,87526,3);
INSERT INTO stanza VALUES('NS1073','note','<br/>',NULL,87527,4);
INSERT INTO stanza VALUES('NS1074','1','The whole world can blind our eyes<br/>From turning to His Word.<br/>So open your mouth<br/>And call for His return to You.<br/>',NULL,87528,1);
INSERT INTO stanza VALUES('NS1074','chorus','Lord, make Your home in my heart<br/>So You can have Your way.<br/>Don’t let my heart be hardened,<br/>But softened unto You.<br/>',NULL,87529,2);
INSERT INTO stanza VALUES('NS1074','2','Jesus Christ is the Spirit<br/>Who gives life inside of you.<br/>So just call on His Name,<br/>And He will come to you.<br/>',NULL,87530,3);
INSERT INTO stanza VALUES('NS1075','1','The life of God is flowing from<br/>The Lamb and God upon the throne.<br/>It’s by this flow that we will grow<br/>And be transformed to precious stones.<br/>',NULL,87531,1);
INSERT INTO stanza VALUES('NS1075','2','By transformation, we will be builded,<br/>A City for our God alone.<br/>Just keep eating, just keep drinking,<br/>And treasure the flowing from the throne.<br/>',NULL,87532,2);
INSERT INTO stanza VALUES('NS1075','note','<br/>',NULL,87533,3);
INSERT INTO stanza VALUES('NS1076','1','All who are with me greet you.<br/>All who are with me greet you.<br/>Greet those who love us,<br/>Who love us in faith.<br/>Grace be with you all.<br/>',NULL,87534,1);
INSERT INTO stanza VALUES('NS1077','1','I look away to Thee, my Lord,<br/>The Author, Perfecter of faith!<br/>I come to taste Thy living streams;<br/>I come to be filled with Thy grace!<br/><br/>Thy flow is pure, and rich, and sweet—<br/>The flow from my God and the Lamb;<br/>Out from the throne a river flows<br/>To fill and o’erflow hearts of men!<br/>',NULL,87535,1);
INSERT INTO stanza VALUES('NS1077','chorus','I come! I come! I come to drink of Thee!<br/>I come to taste Thy living streams,<br/>I come to be filled with Thy grace!<br/>',NULL,87536,2);
INSERT INTO stanza VALUES('NS1077','2','And daily I may come to Thee—<br/>And drink of the Fountain of life!<br/>God in the Son as Spirit flows—<br/>The Triune God, my sure supply!<br/><br/>We in one Body were baptized;<br/>The Spirit we now can all drink!<br/>When we declare—“Jesus is Lord!”<br/>We drink and His riches receive!<br/>',NULL,87537,3);
INSERT INTO stanza VALUES('NS1077','chorus','We come! We come! We come to drink of Thee!<br/>We come to taste Thy living streams,<br/>We come to be filled with Thy grace!<br/>',NULL,87538,4);
INSERT INTO stanza VALUES('NS1077','3','We sing and drink the whole day long;<br/>We’re filled as we speak forth Thy Word—<br/>Yes, filled in spirit as we sing<br/>With grace in our hearts to the Lord!<br/><br/>O hear the cry that’s going forth—<br/>The Spirit and Bride calling, “Come!”<br/>O join this cry; call sinners far<br/>To drink of this Eternal One!<br/>',NULL,87539,5);
INSERT INTO stanza VALUES('NS1077','chorus','Do come! Do come! O come to drink of Him!<br/>Yes, come and taste His living streams,<br/>O come and be filled with His grace!<br/>',NULL,87540,6);
INSERT INTO stanza VALUES('NS1078','1','Draw me with cords of a man,<br/>With bands of love.<br/>Carry me away till I can’t stand in the<br/>Waves of Your flood.<br/><br/>Submerged completely<br/>By the sound of Your voice;<br/>Your flood engulfs me<br/>Until I have no choice.<br/>I’m totally constrained by the<br/>',NULL,87541,1);
INSERT INTO stanza VALUES('NS1078','chorus','Bands of Your love,<br/>The bands of Your love,<br/>The bands of Your love,<br/>The bands of Your love.<br/>',NULL,87542,2);
INSERT INTO stanza VALUES('NS1078','2','Humbled, You left Your throne,<br/>In our fashion found.<br/>Many grains of wheat abide alone,<br/>But You fell into the ground,<br/><br/>Blossoming, bearing<br/>Fruit a hundredfold,<br/>Death overcoming;<br/>Its power could not hold<br/>Your resurrection life and the<br/>',NULL,87543,3);
INSERT INTO stanza VALUES('NS1079','1','Speak Lord, Thy servant’s listening.<br/>A Nazarite I’ll be,<br/>Completely separating<br/>From worldly things to Thee.<br/>I consecrate my all, Lord,<br/>For Thou art now my choice.<br/>Speak Lord, Thy servant’s listening.<br/>Oh, let me hear Thy voice!<br/>',NULL,87544,1);
INSERT INTO stanza VALUES('NS1079','2','Speak Lord, Thy servant’s listening.<br/>A priest I long to be,<br/>One who is always coming<br/>And spending time with Thee.<br/>Thy face I’d seek each day, Lord,<br/>And in Thy presence stay.<br/>Speak Lord, Thy servant’s listening.<br/>Oh, fill me, Lord, I pray!<br/>',NULL,87545,2);
INSERT INTO stanza VALUES('NS1079','3','Speak Lord, Thy servant’s listening.<br/>A prophet I would be,<br/>One who is always speaking<br/>The things I hear from Thee.<br/>Thine every word I’d treasure,<br/>And live on what You say;<br/>Speak Lord, Thy servant’s listening.<br/>Thy word I will convey!<br/>',NULL,87546,3);
INSERT INTO stanza VALUES('NS1079','4','Speak Lord, Thy servant’s listening.<br/>A man of prayer I’d be;<br/>I would not cease my praying<br/>And sin, O Lord, ’gainst Thee.<br/>“Age-turning” prayers are needed;<br/>I’ll pray: “Thy will be done.”<br/>Speak Lord, Thy servant’s listening.<br/>Oh, may Thy kingdom come!<br/>',NULL,87547,4);
INSERT INTO stanza VALUES('NS1080','1','But this is the covenant which I will make<br/>With the house of Israel after those days,<br/>Declares Jehovah, declares Jehovah:<br/>I will put My law in their inward parts<br/>And write it upon their hearts;<br/><br/>And their God I will be,<br/>And their God I will be,<br/>And their God I will be,<br/>And My people they will be.<br/>And their God I will be,<br/>And their God I will be,<br/>And My people they will be.<br/>Jeremiah thirty-one thirty-three.<br/>',NULL,87548,1);
INSERT INTO stanza VALUES('NS1080','2','So this is the covenant which He has made<br/>With the chosen ones who we are today.<br/>Thus the Lord says, thus the Lord says:<br/>He has put His law in our inward parts.<br/>It’s written upon our hearts,<br/><br/>And now He is our God.<br/>Yes! Now He is our God.<br/>Truly He is our God,<br/>And His people now we are.<br/>And now He is our God.<br/>Yes! Now He is our God,<br/>And His people now we are.<br/>We are walking in Him, Hallelujah!<br/>',NULL,87549,2);
INSERT INTO stanza VALUES('NS1081','1','O Light of life, O Beam divine,<br/>Trace us till we are whole.<br/>Effulgent Ray, on us now shine;<br/>Transform our bitter souls.<br/>No more in right and wrong we’ll stay.<br/>That tree, in us uproot!<br/>Evil and good no more our way,<br/>Life flows! We bear light’s fruit!<br/>',NULL,87550,1);
INSERT INTO stanza VALUES('NS1081','2','Once darkness, we did walk in hate,<br/>Far from Your holy flame.<br/>Light quelled sin’s gloom; our needs You sate,<br/>Born of Your radiant name,<br/>Not merely children of the day,<br/>But light itself—we rise!<br/>Awake, o sleeper, from the dead:<br/>Light shines! Light makes us Christ!<br/>',NULL,87551,2);
INSERT INTO stanza VALUES('NS1081','3','True Life in us, unconquerable,<br/>Each blow Christ can endure;<br/>No storm, no hell, no tempter’s pull<br/>Can shake Life’s power pure.<br/>Our mortal life, Light’s tests expose,<br/>Its frailty laid so bare!<br/>Our strength dissolves, but Christ bestows<br/>A life beyond death’s snare.<br/>',NULL,87552,3);
INSERT INTO stanza VALUES('NS1081','4','As light reveals, Your life supplies,<br/>A pathway sure and bright.<br/>From depths of love, we realize<br/>Our growth is borne by light.<br/>In light, no veil now hides Your face—<br/>Our sight, restored and clear!<br/>Through You, we walk, transformed in grace,<br/>Your glory drawing near!<br/>',NULL,87553,4);
INSERT INTO stanza VALUES('NS1082','1','Faith and love are two inseparable,<br/>excellent virtues of the believers in Christ.<br/>Faith is given to us by God<br/>That by it we may receive Christ,<br/>The embodiment of the Triune God,<br/>And thereby enter into the Triune God<br/>And be joined to Him as one,<br/>Having Him as our life, life supply, and everything.<br/>Love issues out of such a wonderful faith<br/>And enables us to live out<br/>All the riches of the Triune God in Christ<br/>With those who have believed into Christ with us,<br/>That the Triune God—<br/>The Father, the Son, and the Spirit—<br/>May have a glorious expression.<br/>',NULL,87554,1);
INSERT INTO stanza VALUES('NS1083','1','The ministers of the new covenant<br/>Impart the very Christ by whom they live;<br/>Through suff’ring, pressure, and the cross’s death,<br/>This ministry the Lord to them does give.<br/>',NULL,87555,1);
INSERT INTO stanza VALUES('NS1083','2','The ministers of the new covenant<br/>Riches of Christ unsearchable possess;<br/>Imparting Christ to all God’s chosen ones,<br/>Fullness of God, Christ’s Body, is expressed.<br/>',NULL,87556,2);
INSERT INTO stanza VALUES('NS1083','3','The ministers of the new covenant<br/>Captives of God are, in Christ’s victory move;<br/>Fragrance of Christ they spread in every place,<br/>Sweet savor of His knowledge ever prove.<br/>',NULL,87557,3);
INSERT INTO stanza VALUES('NS1083','4','The ministers of the new covenant<br/>Inscribe the Spirit as the element<br/>Into the hearts of all those who believe—<br/>Letter of Christ to all men evident.<br/>',NULL,87558,4);
INSERT INTO stanza VALUES('NS1083','5','The ministers of the new covenant,<br/>Mirrors, behold the glory of the Lord;<br/>Infused with all He is, they are transformed,<br/>Even as from the Spirit of the Lord.<br/>',NULL,87559,5);
INSERT INTO stanza VALUES('NS1083','6','The ministers of the new covenant,<br/>Worthless and fragile vessels made of earth;<br/>Yet what a priceless treasure they contain;<br/>Glorious Christ in vessels without worth!<br/>',NULL,87560,6);
INSERT INTO stanza VALUES('NS1083','7','Oh, what a high and holy ministry!<br/>Who for these things is fully competent?<br/>Only of God can we enabled be,<br/>As ministers of His new covenant.<br/>',NULL,87561,7);
INSERT INTO stanza VALUES('NS1083','8','Lord, in this ministry we would take part;<br/>The all-inclusive Christ we would supply;<br/>This ministry unique we would fulfill:<br/>The church to build, the Body edify.<br/>',NULL,87562,8);
INSERT INTO stanza VALUES('NS1084','1','Lord, You know my heart is seeking for You,<br/>But the world comes in and fogs my vision anew;<br/>I cannot make it, Lord; attract me, bring me to You;<br/>You’re the One that’s worthy, precious and true.<br/>',NULL,87563,1);
INSERT INTO stanza VALUES('NS1084','2','Lord, keep my heart; I have no strength on my own;<br/>No effort of my soul’s as strong as Your love alone.<br/>No longer I that’d live, but Christ that liveth in me,<br/>Till Your heart’s desire’s fulfilled in my being.<br/>',NULL,87564,2);
INSERT INTO stanza VALUES('NS1085','1','Every day I would walk to this same, same old well<br/>Hoping all of my thirst it’d quell.<br/>Yet each time I would still find<br/>Myself sore, wanting but more—<br/>This water did not satisfy.<br/><br/>Then I heard of a spring that would never run dry<br/>(For contentment my heart did cry!):<br/>“Whoso drinks shall by no means<br/>Ever thirst; in him will burst<br/>A fountain of life divine!”<br/>',NULL,87565,1);
INSERT INTO stanza VALUES('NS1085','chorus','Give me a drink!<br/>For this water I would sing!<br/>I am filled, my thirst’s stilled.<br/>My heart sings again:<br/>Give me a drink!<br/>There’s a fount of life in me!<br/>All I know, it just flows,<br/>Flowing deep within.<br/>',NULL,87566,2);
INSERT INTO stanza VALUES('NS1085','2','I discovered that spring was the Lord Jesus Christ—<br/>He died for me and He’s alive!<br/>Of my sins I was forgiv’n,<br/>But much more He had in store—<br/>His very own life to give!<br/><br/>Where then does He give life? Well the Bible tells:<br/>In my spirit where Jesus dwells!<br/>Raised from death, He became breath,<br/>Water too, even true food—<br/>He’s processed to live in me!<br/>',NULL,87567,3);
INSERT INTO stanza VALUES('NS1085','chorus','Christ lives in me<br/>As the Spirit reaching me!<br/>This my song, all day long:<br/>Life is flowing free!<br/>He’s flooding me<br/>As a river ceaselessly!<br/>This my God, to me brought:<br/>The processed Trinity!<br/>',NULL,87568,4);
INSERT INTO stanza VALUES('NS1085','3','If you haven’t yet found what your heart’s looking for,<br/>Come and listen to His own word:<br/>“Whoso drinks shall by no means<br/>Ever thirst; in him will burst<br/>A fountain of life divine!”<br/><br/>Come, oh come see this man! Is He not the Christ?<br/>He came that you would have His life!<br/>Just believe, then you will see<br/>He’s so real, living, and free—<br/>A genuine prayer’s the way:<br/>',NULL,87569,5);
INSERT INTO stanza VALUES('NS1085','chorus','Christ lives in me<br/>As the Spirit flowing free!<br/>Yes, in me! I believe!<br/>Take a drink and see!<br/>Christ lives in you!<br/>He’s the living water true!<br/>We’re filled with Him to the brim<br/>For eternity!<br/><br/> (repeat chorus)<br/>',NULL,87570,6);
INSERT INTO stanza VALUES('NS1086','1','Astounding fact! God formed a spirit deep in man!<br/>God came as man—a ladder joining earth and heav’n!<br/>Now He as Spirit comes, my life to be,<br/>God blent with man—thus His image is seen!<br/>',NULL,87571,1);
INSERT INTO stanza VALUES('NS1086','chorus','The universe’s myst’ry’s revealed!<br/>This is my life’s meaning true, no more concealed!<br/>Rise up, respond—this vain world flee, and shine forth with might!<br/>Christ’s young overcomers be, to all earth bring Christ as light!<br/>',NULL,87572,2);
INSERT INTO stanza VALUES('NS1086','2','What radiance bright! The Word is God revealed to me,<br/>Ent’ring as light—my path is clear, no more I’ll stray.<br/>God’s Word contains life, truth, reality;<br/>So open wide—God experience today!<br/>',NULL,87573,3);
INSERT INTO stanza VALUES('NS1086','3','What sweet employ! The church life is my heart’s desire!<br/>Eat, drink, enjoy! In me each day, more life divine.<br/>Christ is supplied, increased; God’s house built; then<br/>God’s glorified—on earth as in the heav’n.<br/>',NULL,87574,4);
INSERT INTO stanza VALUES('NS1087','1','Faith is for appreciating, substantiating,<br/>and receiving the unlimited<br/>riches of the Triune God;<br/>love is for experiencing, enjoying,<br/>and living out the immeasurably rich Triune God.<br/>',NULL,87575,1);
INSERT INTO stanza VALUES('NS1087','2','Faith is for the believers<br/>to be joined to the Triune God,<br/>who is everything to them;<br/>love is for the believers<br/>to minister and transmit the Triune God<br/>to their fellow believers<br/>so that, in such a wonderful and powerful faith,<br/>all the believers may love one another<br/>with divine, transcendent love and live<br/>a corporate life in Christ.<br/>',NULL,87576,2);
INSERT INTO stanza VALUES('NS1087','3','In this way the Body of Christ is realized<br/>and the processed Triune God<br/>is expressed today on the earth<br/>in the all-inclusive Christ<br/>through the immeasurable life-giving Spirit.<br/>',NULL,87577,3);
INSERT INTO stanza VALUES('NS1087','note','<br/>',NULL,87578,4);
INSERT INTO stanza VALUES('NS1088','1','Now I beseech you, brothers,<br/>through the name of our Lord Jesus Christ,<br/>Now I beseech you, brothers,<br/>that you all speak the same thing<br/>and that there be no divisions among you,<br/>and that there be no divisions among you,<br/><br/>But that you be attuned in the same mind,<br/>in the same mind, in the same opinion,<br/>But that you be attuned in the same mind,<br/>in the same mind, in the same opinion.<br/><br/>First Corinthians 1:10<br/>',NULL,87579,1);
INSERT INTO stanza VALUES('NS1089','1','Unstopped, the flow from Jesus’ side,<br/>Whose arms outstretched I see!<br/>On Calvary’s tree, what sacrifice!<br/>He gave His all for me!<br/>Unbarred, my heart, its doors swung wide,<br/>Responds with joy complete,<br/>Surrendered, unreservedly,<br/>Spontaneous jubilee.<br/>',NULL,87580,1);
INSERT INTO stanza VALUES('NS1089','2','Agape love then bids me be<br/>No more for my own gain;<br/>For He who loved and rescued me<br/>Has won my life through pain.<br/>Can one who’s loved not give his all?<br/>Divine love paid the cost.<br/>A life that daily dies, then lives,<br/>Will ne’er be counted loss.<br/>',NULL,87581,2);
INSERT INTO stanza VALUES('NS1089','3','To know the riches of His grace,<br/>Old self I gladly yield;<br/>Emotion, mind, and will I place<br/>Within His hands, unsealed.<br/>A life surrendered wholly, grows,<br/>His image thus to shine;<br/>I sense His will and turn aside<br/>From what is not divine.<br/>',NULL,87582,3);
INSERT INTO stanza VALUES('NS1089','4','Through consecration’s narrow gate<br/>I walk and yield each choice;<br/>In daily steps, both small and great,<br/>I hear my spirit’s voice.<br/>Each time His will defeats my own,<br/>A step ahead is won—<br/>Each vict’ry o’er my self-bound soul<br/>Leads ever to the Son.<br/>',NULL,87583,4);
INSERT INTO stanza VALUES('NS1090','1','God’s divine nature is planted in His Son,<br/>God’s divine life in Jesus Christ has come;<br/>From all His riches God’s power is released,<br/>Through Christ in us His kingdom is increased.<br/>God by His promises, precious, sure, and great,<br/>We, as His sons, God’s nature can partake;<br/>How from corruption and lust can we escape?<br/>Enjoy Christ as our equally precious faith.<br/>',NULL,87584,1);
INSERT INTO stanza VALUES('NS1090','chorus','Richly and bountif’lly supplied unto you,<br/>There is an entrance to the kingdom in view;<br/>Let us be diligent to enter in,<br/>We grow, develop, enter into Him!<br/>',NULL,87585,2);
INSERT INTO stanza VALUES('NS1090','2','All of God’s riches compressed into this seed,<br/>Equally precious faith, will meet our need;<br/>God’s divine energy, virtue from within,<br/>Supplies the way to make us just like Him.<br/>Virtue brings knowledge of our Lord Jesus Christ,<br/>God’s divine power, and Christ to be our life;<br/>And, with all diligence, His life we will absorb,<br/>While rooted, grounded in God’s Holy Word.<br/>',NULL,87586,3);
INSERT INTO stanza VALUES('NS1090','3','Self-control, dwells in the structure of the tree,<br/>Self kept in check, from our spirit is set free;<br/>Life now can flow and our passions and our lust<br/>Will be restrained, for this in God we trust.<br/>Christ our endurance will branch, increase, and grow;<br/>Passing though hardship, Christ’s sufferings we know;<br/>Our daily living with spirit exercised,<br/>Expresses God to be our kingdom prize.<br/>',NULL,87587,4);
INSERT INTO stanza VALUES('NS1090','4','Godliness thrives in a garden of God’s love,<br/>Brotherly love with a source from heav’n above,<br/>Love so delightful, love steadfast, strong and pure.<br/>A blooming love, a love that will endure.<br/>Ultimate love is the sweet, eternal fruit,<br/>God, as true love, through the branch, the trunk, and root;<br/>Nobler and higher, such love we now shall be<br/>Love growing, shining through eternity.<br/>',NULL,87588,5);
INSERT INTO stanza VALUES('NS1091','1','His divine power has given to us<br/>All things that relate<br/>To life and godliness<br/>Through the full knowledge<br/>Of Him who has called us<br/>By His own glory and virtue.<br/>',NULL,87589,1);
INSERT INTO stanza VALUES('NS1091','chorusverse','By His own glory and virtue,<br/>By His own glory and virtue.<br/>',NULL,87590,2);
INSERT INTO stanza VALUES('NS1091','2','His divine power has given to us<br/>All things that relate<br/>To life and godliness<br/>Through the full knowledge<br/>Of Him who has called us<br/>By His own glory and virtue.<br/>',NULL,87591,3);
INSERT INTO stanza VALUES('SK1','1','Sláva buď Bohu Otcovi,<br/>Synovi – Kristu,<br/>sláva buď Svätému Duchu –<br/>jedno sú.<br/>',NULL,129318,1);
INSERT INTO stanza VALUES('SK1','2','Keď hľadíme na stvorenie<br/>zručne stvorené,<br/>naše srdcia sú pohnuté,<br/>chvála znie.<br/>',NULL,129319,2);
INSERT INTO stanza VALUES('SK1','3','No Tvojou túžbou, Otče, je<br/>mnoho synov mať.<br/>V Synovi Ťa budú chváliť,<br/>milovať.<br/>',NULL,129320,3);
INSERT INTO stanza VALUES('SK1','4','Otče, Ty si chcel predstaviť<br/>ľuďom v zjavení<br/>Svoje tajomstvo, ’by boli<br/>víťazní.<br/>',NULL,129321,4);
INSERT INTO stanza VALUES('SK1','5','V Kristu skrze vykúpenie,<br/>zlo si porazil.<br/>V Ňom si tiež nové stvorenie<br/>vytvoril.<br/>',NULL,129322,5);
INSERT INTO stanza VALUES('SK1','6','Sláva buď Bohu Otcovi,<br/>Synovi – Kristu,<br/>sláva buď Svätému Duchu –<br/>jedno sú.<br/>',NULL,129323,6);
INSERT INTO stanza VALUES('SK2','1','Sláva, sláva, sláva! Chvála, uctievanie!<br/>Čujte chválospevy, tiahnuce sa večnosťou!<br/>Otec, Syn, Duch Svätý – je Jeho zjavenie.<br/>Pokloň sa každá duša pred Božstvom!<br/>',NULL,129324,1);
INSERT INTO stanza VALUES('SK2','2','Otec je zdroj slávy, v Ňom všetko pôvod má,<br/>a Syn všemocným Slovom všetko udržiava.<br/>Túto scénu slávy Duch Svätý vypĺňa –<br/>nech slávnu Plnosť srdce uctieva!<br/>',NULL,129325,2);
INSERT INTO stanza VALUES('SK2','3','Náš najvyšší Bože, v nádhere tej svätej,<br/>Hlava blaženosti, pred Tebou sa klaniame!<br/>Majestát a sláva, chvála aj moc všetka,<br/>večný Zdroj všetkého, patrí Tebe!<br/>',NULL,129326,3);
INSERT INTO stanza VALUES('SK7','1','Sláva, sláva buď Otcovi!<br/>Sláva, sláva Synovi!<br/>Sláva, sláva nech je Duchu!<br/>Sláva Ti Trojjediný!<br/>',NULL,129327,1);
INSERT INTO stanza VALUES('SK7','chorus','Chválime Ho! Chválime Ho!<br/>Chvála Bohu, Traja sú Jeden!<br/>Slávu, vzdávajme Mu slávu!<br/>Uskutočnil dielo nádherné!<br/>',NULL,129328,2);
INSERT INTO stanza VALUES('SK7','2','Chvála Otcovi, že mal plán!<br/>Chvála, Syn uskutočnil!<br/>Chvála, Duch všetko prenáša!<br/>V diele Traja, sú Jedným!<br/>',NULL,129329,3);
INSERT INTO stanza VALUES('SK10','1','Ó, Bože si večný Otec,<br/>skvelý, nestvorený JA SOM!<br/>Si odveký, si pred všetkým.<br/>Bol si pred počiatkom časov!<br/>',NULL,129330,1);
INSERT INTO stanza VALUES('SK10','2','Ty si Bohom od večnosti,<br/>čas aj priestor presahuješ!<br/>Otče, si plnosť večnosti,<br/>nemáš počiatok ‘ni koniec!<br/>',NULL,129331,2);
INSERT INTO stanza VALUES('SK10','3','Všetkého si večným zdrojom,<br/>sám si nebesia nariadil!<br/>Ty si predovšetkým, prvý,<br/>predchádzaš aj najprednejších!<br/>',NULL,129332,3);
INSERT INTO stanza VALUES('SK10','4','Si život, čo navždy trvá,<br/>Otče, Ty nikdy neskončíš!<br/>Všetko sa míňa, Ty trváš,<br/>si nad všetkým tým konečným!<br/>',NULL,129333,4);
INSERT INTO stanza VALUES('SK10','5','Ty si Alfa, si ten prvý,<br/>si Omega, ten posledný!<br/>Nikdy v ničom nemáš núdzu,<br/>si úplný, dokonalý!<br/>',NULL,129334,5);
INSERT INTO stanza VALUES('SK10','6','Chvála Ti, si nekonečný!<br/>Chvála Ti, si bezhraničný!<br/>Chvála Ti, si taký plný!<br/>Ó chvála, si dokonalý!<br/>',NULL,129335,6);
INSERT INTO stanza VALUES('SK11','1','Otče, Ty si pravým Duchom,<br/>si Ten najsvätejší,<br/>uctievame Ťa dnes duchom<br/>a v pravde vzývaním.<br/>',NULL,129336,1);
INSERT INTO stanza VALUES('SK11','2','Vyformoval si v nás ducha,<br/>v ňom Ťa uctievame,<br/>navzájom sme jedným duchom,<br/>tam sa ozývame.<br/>',NULL,129337,2);
INSERT INTO stanza VALUES('SK11','3','Náš Otec prišiel v Synovi<br/>a Syn sa stal Duchom,<br/>do nášho ducha vstúpil Boh,<br/>toto je milosťou!<br/>',NULL,129338,3);
INSERT INTO stanza VALUES('SK11','4','Syn je Tvojím večným Slovom,<br/>to Slovo Duchom je,<br/>Duch vstúpil ako náš život,<br/>ducha obnovuje.<br/>',NULL,129339,4);
INSERT INTO stanza VALUES('SK11','5','Tvoj Duch žije v našom duchu,<br/>tak sme zjednotení,<br/>svedčí spolu s naším duchom,<br/>že sme Božie deti.<br/>',NULL,129340,5);
INSERT INTO stanza VALUES('SK11','6','Duch nás Tvoj vo všetkom vedie,<br/>my nasledujeme,<br/>tak sa životom, pokojom<br/>duchovní stávame.<br/>',NULL,129341,6);
INSERT INTO stanza VALUES('SK11','7','V duchu, Otče, uctievame,<br/>v duchu Ťa vzývame,<br/>keď náš duch je uvoľnený,<br/>Ty máš vyjadrenie.<br/>',NULL,129342,7);
INSERT INTO stanza VALUES('SK11','8','Otče, teraz Ťa chválime<br/>za to, že si Duchom,<br/>uctievame Ťa úprimne,<br/>v pravde, naším duchom.<br/>',NULL,129343,8);
INSERT INTO stanza VALUES('SK12','1','Ó, Bože, si zdroj života,<br/>božský a bohatý!<br/>Plynieš ako voda živá,<br/>prúdiš do večnosti!<br/>',NULL,129344,1);
INSERT INTO stanza VALUES('SK12','2','V Synovi si v láske, Otče,<br/>medzi ľuďmi plynul.<br/>Dnes stále ako Duch plynieš,<br/>v nás milosťou Svojou.<br/>',NULL,129345,2);
INSERT INTO stanza VALUES('SK12','3','V hriechu, zlobe sme odišli<br/>ďaleko od Teba,<br/>vykúpil si nás v Synovi,<br/>život a milosť dal.<br/>',NULL,129346,3);
INSERT INTO stanza VALUES('SK12','4','Keď sme Ťa vážne nebrali<br/>a Ducha rmútili,<br/>predsa si prišiel ako Duch,<br/>my sme Ťa prijali.<br/>',NULL,129347,4);
INSERT INTO stanza VALUES('SK12','5','Otče, v Synovi ako Duch<br/>sa s nami zmiešavaš,<br/>spoločenstvom pomazávaš,<br/>viac a viac narastáš.<br/>',NULL,129348,5);
INSERT INTO stanza VALUES('SK12','6','Láska Božia, milosť Krista<br/>a prúdenie Ducha,<br/>schopnými nás navždy činia<br/>zdieľať to, čo Boh má.<br/>',NULL,129349,6);
INSERT INTO stanza VALUES('SK12','7','Otec, Syn a Duch – ste jeden,<br/>prehojne dbáš o nás,<br/>jednomyseľne spievame,<br/>od nás vždy chválu máš.<br/>',NULL,129350,7);
INSERT INTO stanza VALUES('SK13','1','Ty si láska, svetlo, Otče,<br/>v Synovi si životom,<br/>život nám je udelený<br/>Tvojou láskou a svetlom.<br/>',NULL,129351,1);
INSERT INTO stanza VALUES('SK13','chorus','Ty si láskou, svetlom,<br/>v Synovi si životom,<br/>život nám je udelený<br/>Tvojou láskou a svetlom.<br/>',NULL,129352,2);
INSERT INTO stanza VALUES('SK13','2','Láskou si, všetko, čo činíš,<br/>je svetlom prejavené,<br/>láska vnútri, svetlo zvonku,<br/>sú neoddeliteľné.<br/>',NULL,129353,3);
INSERT INTO stanza VALUES('SK13','3','Láska k nám prišla milosťou,<br/>svetlo k nám prišlo pravdou,<br/>vychutnávame Ťa láskou<br/>a poznávame svetlom.<br/>',NULL,129354,4);
INSERT INTO stanza VALUES('SK13','4','Láskou, tou, čo viedla na kríž,<br/>sme Tvoj život získali,<br/>svetlo nám otvára myseľ,<br/>’by sme krv uplatnili.<br/>',NULL,129355,5);
INSERT INTO stanza VALUES('SK13','5','Tvoja láska dáva život,<br/>máme ňou spoločenstvo,<br/>svetlom sme očisťovaní,<br/>žijeme spoločenstvo.<br/>',NULL,129356,6);
INSERT INTO stanza VALUES('SK13','6','Svetlom a krvou, čo čistí,<br/>chceme mať pomazanie,<br/>aby život Tvojej lásky<br/>v nás mohol prúdiť viacej.<br/>',NULL,129357,7);
INSERT INTO stanza VALUES('SK13','7','Tvojou láskou sme Ti deťmi,<br/>Abba, Otče, chválime,<br/>svetlo našu tmu rozptýli,<br/>až Ťa plne uzrieme.<br/>',NULL,129358,8);
INSERT INTO stanza VALUES('SK13','chorus','Milosť mám! Pravdu mám!<br/>V láske a svetle zdroj má!<br/>Neustále chválime Ťa,<br/>svetlom, láskou známe Ťa!<br/>',NULL,129359,9);
INSERT INTO stanza VALUES('SK15','1','Ó, si presahujúci,<br/>Ty si svätý, Bože!<br/>Nikto Ti roveň nie je,<br/>nemáš porovnanie!<br/>Zo svätých najsvätejší,<br/>vesmír volať môže!<br/>Tvoja moc, prirodzenosť<br/>všetko prevyšuje!<br/>',NULL,129360,1);
INSERT INTO stanza VALUES('SK15','2','Odlišný, jedinečný,<br/>nielen správny, čistý.<br/>Nie si iba bezchybný,<br/>no aj dokonalý.<br/>Nič sa Ti nepriblíži,<br/>nik Ti nie je rovný,<br/>ak Ťa niečo zamieňa,<br/>tak Ťa to urazí.<br/>',NULL,129361,2);
INSERT INTO stanza VALUES('SK15','3','Zo všetkých najskvelejší<br/>a tiež najčestnejší,<br/>od najlepších sa líšiš,<br/>nik nie je ako Ty.<br/>Si najspravodlivejší,<br/>bo absolútnosť máš,<br/>Tebe sa nikto iný<br/>krásou nevyrovná.<br/>',NULL,129362,3);
INSERT INTO stanza VALUES('SK15','4','Svätosť presahujúcu<br/>máme pripravenú<br/>a túto prirodzenosť<br/>zdieľame nádhernú.<br/>Tvoju povahu máme,<br/>nepresiahnuteľnosť.<br/>Život nasledujeme<br/>až dorastie v plnosť.<br/>',NULL,129363,4);
INSERT INTO stanza VALUES('SK15','5','Otče, vzdávame chvály,<br/>ó, za Tvoju svätosť,<br/>úžasnú prirodzenosť,<br/>neporovnateľnosť.<br/>Chvála, že smieme zdieľať<br/>Tvoju prirodzenosť,<br/>odlišnú, jedinečnú,<br/>navždy našu radosť.<br/>',NULL,129364,5);
INSERT INTO stanza VALUES('SK16','1','Otče drahý, si sťa jedľa.<br/>Nový, vždy zelený,<br/>osviežujúci sťa rosa<br/>a naveky živý.<br/>',NULL,129365,1);
INSERT INTO stanza VALUES('SK16','chorus','Otče si nezmeniteľný,<br/>nikdy neuvädneš,<br/>po všetky obdobia svieži,<br/>novosť odhaľuješ.<br/>',NULL,129366,2);
INSERT INTO stanza VALUES('SK16','2','Si Boh a stále si nový,<br/>všetko iné končí.<br/>S Tebou je však všetko čerstvé,<br/>aj keď čas pokročí.<br/>',NULL,129367,3);
INSERT INTO stanza VALUES('SK16','3','Tebou dané požehnanie<br/>je novosti plné,<br/>Tvoja zmluva, Tvoje cesty,<br/>budú navždy nové.<br/>',NULL,129368,4);
INSERT INTO stanza VALUES('SK16','4','Tvojím novým sme stvorením –<br/>nový duch aj srdce,<br/>denne sme obnovovaní,<br/>život udeľuješ.<br/>',NULL,129369,5);
INSERT INTO stanza VALUES('SK16','5','Bude nová zem, nebesia<br/>s Tvojím novým mestom,<br/>každý mesiac ovocie dá,<br/>novosť je vo všetkom.<br/>',NULL,129370,6);
INSERT INTO stanza VALUES('SK16','6','V Tebe je vždy všetko nové,<br/>Ty si nový, Otče,<br/>novú večnú pieseň, chválu<br/>Ti spolu spievame.<br/>',NULL,129371,7);
INSERT INTO stanza VALUES('SK17','1','Ó, keď hľadím na stvorenie, Otče môj,<br/>na nebeské, aj divy pozemské,<br/>všetko svedčí o Tvojej veľkej moci,<br/>veci veľké, malé, nespočetné.<br/>',NULL,129372,1);
INSERT INTO stanza VALUES('SK17','chorus','Preto Ti z vnútra spievam piesne chvál!<br/>Ó, si veľký! Si úžasný!<br/>Otče, chcem stále spievať piesne chvál!<br/>Ó, si veľký! Si úžasný!<br/>',NULL,129373,2);
INSERT INTO stanza VALUES('SK17','2','Ó, vychutnávam milosť Tvojej spásy,<br/>uvažujúc, jak si Syna poslal.<br/>Zomrel, novým stvorením sme sa stali,<br/>aby sa Tvoj život prejavoval.<br/>',NULL,129374,3);
INSERT INTO stanza VALUES('SK17','3','V cirkvi vidím úžasné spoločenstvo<br/>mnohých ľudí, čo Tvoj život majú.<br/>Kontaktujú Ťa, tvoria príbytok Tvoj,<br/>spolu Tvoju plnosť vyjadrujú.<br/>',NULL,129375,4);
INSERT INTO stanza VALUES('SK17','4','Nadchádzajúce obdobie plnosti,<br/>podiel Nového Jeruzalema,<br/>s novým nebom a zemou očakávam,<br/>kde všetko, čím si, vyjadrenie má.<br/>',NULL,129376,5);
INSERT INTO stanza VALUES('SK18','1','Verný si a spoľahlivý,<br/>Bože a Otče môj.<br/>Vesmír o Tvojej vernosti<br/>vydáva svedectvo.<br/>',NULL,129377,1);
INSERT INTO stanza VALUES('SK18','chorus','Tvoja vernosť je nezlomná,<br/>za to Ťa uctievam,<br/>v nebesiach ustanovená,<br/>navždy je tu pre mňa.<br/>',NULL,129378,2);
INSERT INTO stanza VALUES('SK18','2','U Teba nieto premeny,<br/>ani tieňa zmeny,<br/>lebo si vždy Bol, Si teraz,<br/>a Budeš naveky.<br/>',NULL,129379,3);
INSERT INTO stanza VALUES('SK18','3','Tvoje spoľahlivé slovo<br/>nikdy nezaniká,<br/>hoc nebesia, zem pominú,<br/>slovo vždy pretrvá.<br/>',NULL,129380,4);
INSERT INTO stanza VALUES('SK18','4','Svoje dary neľutuješ<br/>ani povolanie,<br/>Tvoja milosť navždy trvá,<br/>milosrdenstvo tiež.<br/>',NULL,129381,5);
INSERT INTO stanza VALUES('SK18','5','Tvoje slovo, Tvoja vernosť<br/>sú mojou istotou,<br/>spolu s Tvojou spásou pravou<br/>sú mojou zárukou.<br/>',NULL,129382,6);
INSERT INTO stanza VALUES('SK18','6','Ak som ti neverný, Otče,<br/>Ty ostávaš verný,<br/>sám Seba zaprieť nemôžeš,<br/>Svoje slovo splníš.<br/>',NULL,129383,7);
INSERT INTO stanza VALUES('SK18','7','Keďže si verný naplniť<br/>Svoje zasľúbenia,<br/>Tvojou vernosťou sýtim sa,<br/>vychutnávam Teba.<br/>',NULL,129384,8);
INSERT INTO stanza VALUES('SK18','8','Kol trónu Tvojho dúha je,<br/>hlása Tvoju vernosť,<br/>sväté mesto navždy nesie,<br/>túto Tvoju vlastnosť.<br/>',NULL,129385,9);
INSERT INTO stanza VALUES('SK19','1','Veľká Tvoja vernosť Bože, Otče môj,<br/>v Tebe niet premeny, tieňa zmeny,<br/>Tvoje zľutovanie nikdy nekončí,<br/>pretože si a budeš naveky.<br/>',NULL,129386,1);
INSERT INTO stanza VALUES('SK19','chorus','Veľká Tvoja vernosť! Veľká Tvoja vernosť!<br/>Každé ráno vidím novú milosť.<br/>Všetko, čo potrebujem, zaopatríš,<br/>Pane, veľká ku mne Tvoja vernosť!<br/>',NULL,129387,2);
INSERT INTO stanza VALUES('SK19','2','Leto a zima, jarný čas a jeseň,<br/>slnko, mesiac, hviezdy a ich pohyb<br/>s celým stvorením sú svedectvom Tvojej<br/>vernosti, milosrdenstva, lásky.<br/>',NULL,129388,3);
INSERT INTO stanza VALUES('SK19','3','Hriech je odpustený, Tvoj pokoj trvá,<br/>Tvoja prítomnosť teší a vedie.<br/>Dnes mi dávaš silu a zajtra nádej,<br/>ja mám všetko Tvoje požehnanie.<br/>',NULL,129389,4);
INSERT INTO stanza VALUES('SK20','1','Otče náš, milujeme Ťa,<br/>si taký spravodlivý,<br/>v Kristu ospravedlnení<br/>kto nám svedomie skľúči?<br/>Si spravodlivý a my sme<br/>na Tebe postavení.<br/>V Tebe nie je nič nesprávne,<br/>spravodlivosť nemeníš.<br/>',NULL,129390,1);
INSERT INTO stanza VALUES('SK20','2','Ježiša si namiesto nás<br/>spravodlivo odsúdil,<br/>všetky Tvoje požiadavky<br/>spravodlivo naplnil.<br/>On Ťa plne uspokojil,<br/>náhradu od Neho máš,<br/>ako by si znovu mohol<br/>žiadať to isté od nás?<br/>',NULL,129391,2);
INSERT INTO stanza VALUES('SK20','3','Otče, Ježiša si prijal<br/>ako Zástupcu ľudí,<br/>súdil si Spravodlivého<br/>za nás nespravodlivých.<br/>Ako dôkaz Tvojho práva<br/>po pravici Ti sedí.<br/>Je Tvojím uspokojením,<br/>Tvoje túžby naplní.<br/>',NULL,129392,3);
INSERT INTO stanza VALUES('SK20','4','Máme Tvoju spravodlivosť,<br/>Otče, krvou Ježiša<br/>chráni nás a je stabilná,<br/>nikto z miesta nehne nás.<br/>Sme Tvojou spravodlivosťou,<br/>nik nás súdiť nemôže,<br/>chceme o tom navždy svedčiť<br/>v Novom Jeruzaleme.<br/>',NULL,129393,4);
INSERT INTO stanza VALUES('SK21','1','Za spravodlivosť chválime,<br/>právo, Otče, uznávame<br/>a dosvedčujeme.<br/>Si sudcom celého ľudstva,<br/>žiadnej neprávosti nemáš,<br/>ani nič nesprávne.<br/>',NULL,129394,1);
INSERT INTO stanza VALUES('SK21','2','Otče Svätý, Spravodlivý,<br/>spravodlivosť Tvoj trón drží,<br/>základom istým je.<br/>Dnes cez Tvoju spravodlivosť<br/>kraľuje v Kristovi milosť,<br/>pokoj zakúšame.<br/>',NULL,129395,2);
INSERT INTO stanza VALUES('SK21','3','Spravodlivosť si žiadala,<br/>aby Tvoj Syn zomrel za nás,<br/>tak sme vykúpení.<br/>My sme ospravedlnení<br/>uplatneným vykúpením,<br/>tak sme zachránení.<br/>',NULL,129396,3);
INSERT INTO stanza VALUES('SK21','4','Spravodlivosť si ukázal<br/>a odpustením požehnal<br/>v dávnych časoch ľudí.<br/>’By si spravodlivosť zjavil,<br/>odpustením si obdaril<br/>v tomto veku hriešnych.<br/>',NULL,129397,4);
INSERT INTO stanza VALUES('SK21','5','Súdom nad všetkými ľuďmi,<br/>Svoju spravodlivosť zjavíš<br/>prostredníctvom Krista.<br/>My však budeme pevne stáť,<br/>spravodlivosť dokazovať<br/>milosťou od Teba.<br/>',NULL,129398,5);
INSERT INTO stanza VALUES('SK21','6','Kráľovstvo je práva plné,<br/>tak sa Tvoj pokoj buduje<br/>v plnej harmónii.<br/>V novom nebi, novej zemi<br/>spravodlivosťou odmeníš,<br/>ako si prisľúbil.<br/>',NULL,129399,6);
INSERT INTO stanza VALUES('SK22','1','Chválime Ťa, Otče svätý,<br/>spievame Ti úctivo.<br/>Ty si svätý, si vznešený,<br/>sväté je Tvoje meno.<br/>',NULL,129400,1);
INSERT INTO stanza VALUES('SK22','2','Otče, máš ľúbiace srdce<br/>a cesty spravodlivé.<br/>Aj keď si Ten najsvätejší,<br/>Krista nám vždy daruješ.<br/>',NULL,129401,2);
INSERT INTO stanza VALUES('SK22','3','Naveky si nás posvätil<br/>Krista Ježiša krvou,<br/>hriešnikov si si oddelil,<br/>Svojím slovom, je Pravdou.<br/>',NULL,129402,3);
INSERT INTO stanza VALUES('SK22','4','Nás si Svojím Svätým Duchom,<br/>ó, svätými učinil,<br/>nášho ducha, dušu, telo<br/>tiež úplne posvätíš.<br/>',NULL,129403,4);
INSERT INTO stanza VALUES('SK22','5','Ježišov život dnes máme<br/>prostredníctvom milosti,<br/>účastníkmi sa stávame,<br/>Otče, Tvojej svätosti.<br/>',NULL,129404,5);
INSERT INTO stanza VALUES('SK22','6','Až budeme v meste svätom<br/>navždy plne svätými,<br/>„Ty si Svätý!“ vyhlasovať<br/>budeme už naveky.<br/>',NULL,129405,6);
INSERT INTO stanza VALUES('SK23','1','Vo všetkej múdrosti, Otče,<br/>podľa vôle Svojej<br/>túžiš, aby bolo všetko<br/>Synom naplnené.<br/>',NULL,129406,1);
INSERT INTO stanza VALUES('SK23','chorus','Ó, hĺbku Tvojej múdrosti<br/>kto preskúmať môže?<br/>V nej milosrdenstvo, milosť<br/>nachádzame Božie!<br/>',NULL,129407,2);
INSERT INTO stanza VALUES('SK23','2','Všetko si stvoril úžasne,<br/>kto tomu rozumie?<br/>Z Teba, Tebou a pre Teba,<br/>v tom Tvoja múdrosť je.<br/>',NULL,129408,3);
INSERT INTO stanza VALUES('SK23','3','Ó, múdrosť Tvoja zavrela<br/>všetky veci pod hriech,<br/>milosrdenstvo si zjavil,<br/>Tebou sa chválime.<br/>',NULL,129409,4);
INSERT INTO stanza VALUES('SK23','4','Vykúpenie si v múdrosti<br/>na kríži dokončil,<br/>aby si do nášho ducha<br/>svoj poklad uložil.<br/>',NULL,129410,5);
INSERT INTO stanza VALUES('SK23','5','Ó, múdrosť Tvoja cez cirkev<br/>je známa mocnostiam,<br/>cez nás je múdrosť rozličná<br/>zjavená nebesiam.<br/>',NULL,129411,6);
INSERT INTO stanza VALUES('SK23','6','Keď v Novom Jeruzaleme<br/>sa chváliť budeme,<br/>tá múdrosť bude poznaná<br/>navždy a úplne.<br/>',NULL,129412,7);
INSERT INTO stanza VALUES('SK24','1','V Kristovi je sústredená<br/>múdrosť, milosť Božia.<br/>On sa stal našou múdrosťou,<br/>v Ňom vidíme Teba.<br/>',NULL,129413,1);
INSERT INTO stanza VALUES('SK24','2','Po čom túžiš, všetko je v Ňom,<br/>je cestou milosti.<br/>V Kristu máme Tvoju múdrosť,<br/>ó, Otče, sláva Ti.<br/>',NULL,129414,2);
INSERT INTO stanza VALUES('SK24','3','Je našou spravodlivosťou,<br/>v Ňom sme spravodliví.<br/>Kristus je našou svätosťou,<br/>v Ňom sme posvätení.<br/>',NULL,129415,3);
INSERT INTO stanza VALUES('SK24','4','Podľa Tvojho plánu, Otče,<br/>je nám vykúpením.<br/>Vykúpení môžeme byť<br/>v Tebe dokonalí.<br/>',NULL,129416,4);
INSERT INTO stanza VALUES('SK24','5','V Tvojej správe domácnosti<br/>je Tvojou múdrosťou.<br/>Preňho Ťa, Otče, chválime<br/>so všetkou pokorou.<br/>',NULL,129417,5);
INSERT INTO stanza VALUES('SK24','6','V Ňom vidíme Tvoju múdrosť,<br/>hojná, hlboká je.<br/>Hojnejšia a hlbšia bude,<br/>keď ju zakúšame.<br/>',NULL,129418,6);
INSERT INTO stanza VALUES('SK25','1','Ó, Otče, Svoje milosrdenstvo<br/>si prejavil,<br/>z nás hriešnikov si synov učinil<br/>v láske navždy.<br/>Milosrdenstva a cti nádoby<br/>si si pre slávu z nás pripravil.<br/>',NULL,129419,1);
INSERT INTO stanza VALUES('SK25','2','„Milosrdenstvo chcem a nie obeť,“<br/>si oznámil,<br/>Svoju priazeň, milosrdenstvo k nám<br/>tým prejavil.<br/>Nezávisí to od toho, kto chce,<br/>no od Boha, ktorý sa zmiluje.<br/>',NULL,129420,2);
INSERT INTO stanza VALUES('SK25','3','Milosrdenstvo, lásku aj milosť<br/>sme dostali,<br/>aby sme, Otče, s Tebou tvárou v tvár<br/>vždy ostali.<br/>Chválime Ťa za milosrdenstvo<br/>po všetky naše dni, celú večnosť.<br/>',NULL,129421,3);
INSERT INTO stanza VALUES('SK26','1','Za milosrdenstvo, Otče,<br/>úžasné Ťa chválime!<br/>Napriek našim pádom, chybám<br/>veľkosťou prekypuje.<br/>Chválime Ťa! Chválime Ťa!<br/>Za to obdarovanie!<br/>',NULL,129422,1);
INSERT INTO stanza VALUES('SK26','2','Ó, Tvoje milosrdenstvo<br/>úžasné a priestranné!<br/>Dosahuje k nám hriešnikom,<br/>stále nás pevne zovrie.<br/>Od tohto milosrdenstva,<br/>Otče, čo nás odvedie?<br/>',NULL,129423,2);
INSERT INTO stanza VALUES('SK26','3','Vďaka za milosrdenstvo<br/>prehojné a bohaté!<br/>Milosrdenstvom s’ vykúpil,<br/>udelil Svoju priazeň.<br/>Bez Tvojho milosrdenstva,<br/>kde by sme našli priazeň?<br/>',NULL,129424,3);
INSERT INTO stanza VALUES('SK26','4','Ó, Tvoje milosrdenstvo,<br/>láskavé, jemné, sladké!<br/>Spolu s Tvojou vľúdnosťou nás<br/>stále uspokojuje.<br/>Vážime si ho nesmierne,<br/>nič ako ono nie je.<br/>',NULL,129425,4);
INSERT INTO stanza VALUES('SK26','5','Otče, to milosrdenstvo<br/>stále svieže, vždy nové<br/>vychutnávame každý deň,<br/>zrána nás občerstvuje.<br/>Veľmi sa z neho tešíme!<br/>Spoločne Ťa chválime.<br/>',NULL,129426,5);
INSERT INTO stanza VALUES('SK26','6','Milosrdenstvo je večné,<br/>chváliť neprestávame,<br/>Tvojou milosťou a priazňou<br/>nám je zabezpečené.<br/>Na neho sa spoliehame,<br/>Teba nám zaručuje.<br/>',NULL,129427,6);
INSERT INTO stanza VALUES('SK30','1','Ty láskou zahrnul si nás,<br/>zo srdca vďačíme.<br/>Uctievame Ťa, Otče náš,<br/>zo srdca chválime.<br/>',NULL,129428,1);
INSERT INTO stanza VALUES('SK30','2','Svoje srdce si nám zjavil,<br/>Svoju večnú vôľu.<br/>Ty sám si prišiel v Synovi,<br/>splniť vôľu Svoju.<br/>',NULL,129429,2);
INSERT INTO stanza VALUES('SK30','3','Milovaného dal si nám,<br/>Svoj život položil,<br/>aby sme sa stali synmi,<br/>zdedili všetko s Ním.<br/>',NULL,129430,3);
INSERT INTO stanza VALUES('SK30','4','My máme z Neho Tvoj život<br/>a Ty si Otec náš.<br/>Seba, Svoju prirodzenosť,<br/>Otče, do nás vkladáš.<br/>',NULL,129431,4);
INSERT INTO stanza VALUES('SK30','5','Ó, Tvoj Duch do nášho prišiel,<br/>tak „Otče” voláme.<br/>Z Ducha sme sa narodili,<br/>premieňaní tak sme.<br/>',NULL,129432,5);
INSERT INTO stanza VALUES('SK30','6','Do slávy chceš priviesť synov,<br/>to je Tvoj cieľ večný.<br/>Na obraz Svojho Syna chceš<br/>pripodobniť všetkých.<br/>',NULL,129433,6);
INSERT INTO stanza VALUES('SK30','7','Premieňajúcou prácou v nás<br/>vedieš každého z nás.<br/>Nesieš od slávy k sláve nás,<br/>dielo zavŕšiš v nás.<br/>',NULL,129434,7);
INSERT INTO stanza VALUES('SK30','8','Veľká je, Otče, láska tá,<br/>vždy budeme vďační.<br/>My chváliť Ťa vždy budeme,<br/>uctievať naveky.<br/>',NULL,129435,8);
INSERT INTO stanza VALUES('SK39','1','Sláva Bohu za všetko, čo vykonal,<br/>tak miloval svet, že Svojho Syna dal,<br/>dal Svoj život, aby nás tak vykúpil,<br/>smieme vojsť, bránu života otvoril.<br/>',NULL,129436,1);
INSERT INTO stanza VALUES('SK39','chorus','Chvála Mu, chvála Mu, Jeho hlas počujte,<br/>chvála Mu, chvála Mu, všetci sa radujte.<br/>Poďte k Otcovi skrz Ježiša Syna<br/>vzdať Mu slávu za všetko, čo vykonal.<br/>',NULL,129437,2);
INSERT INTO stanza VALUES('SK39','2','Skvelé vykúpenie skrze Jeho krv<br/>prisľúbil Boh každému veriacemu.<br/>Aj najhorší hriešnik, ktorý uverí,<br/>hneď v tú chvíľu mu Pán Ježiš odpustí.<br/>',NULL,129438,3);
INSERT INTO stanza VALUES('SK39','3','Veľké veci učil a spravil nám Pán,<br/>veľká naša radosť z Ježiša Syna.<br/>Vyšší a čistejší náš údiv bude,<br/>naše prekvapenie, keď Ho zbadáme.<br/>',NULL,129439,4);
INSERT INTO stanza VALUES('SK40','1','Chválime Ťa za<br/>Syna lásky Tvojej.<br/>Zomrel, slávne vstal z mŕtvych,<br/>do nebies vstúpil.<br/>',NULL,129440,1);
INSERT INTO stanza VALUES('SK40','chorus','Aleluja! Tebe sláva!<br/>Aleluja! Amen!<br/>Aleluja! Tebe sláva!<br/>Teba chválime!<br/>',NULL,129441,2);
INSERT INTO stanza VALUES('SK40','2','Chválime Ťa za<br/>Tvojho Ducha svetla.<br/>Spasiteľa ukázal<br/>a tmu rozohnal.<br/>',NULL,129442,3);
INSERT INTO stanza VALUES('SK40','3','Sláva, vďaka, česť,<br/>Otče lásky, Tebe.<br/>V Synovom vykúpení,<br/>Teba vidíme.<br/>',NULL,129443,4);
INSERT INTO stanza VALUES('SK40','4','My chválime Ťa,<br/>Tvojej lásky plní.<br/>Teraz každé srdce,<br/>ohňom z nebies horí.<br/>',NULL,129444,5);
INSERT INTO stanza VALUES('SK48','1','Otče, my Ti žehnáme,<br/>sme pred Tebou šťastní.<br/>S Tvojím Synom navždy sme<br/>nad temnou smrťou vždy.<br/>On žije ako človek<br/>pred Tebou vo svetle,<br/>v Tvojej prehojnej priazni,<br/>láske nekonečnej.<br/>',NULL,129445,1);
INSERT INTO stanza VALUES('SK48','2','Jeho Otec je tiež náš,<br/>Jeho Boh je naším.<br/>Radosťou Tvojho srdca<br/>je Tvoj milovaný.<br/>On nás v radosť privádza,<br/>k Nemu sme pozvaní<br/>lásku Tvoju poznávať,<br/>tvár Tvoju, tá žiari.<br/>',NULL,129446,2);
INSERT INTO stanza VALUES('SK48','3','Láska Tvoja otvára,<br/>chlad či tma v nej nie je.<br/>V Ňom tá láska centrum má,<br/>milovaní v Ňom sme.<br/>V Ňom láska a tiež sláva<br/>večný pokoj našli,<br/>synovia – Jeho bratia<br/>sú v Ňom požehnaní.<br/>',NULL,129447,3);
INSERT INTO stanza VALUES('SK50','1','Otče, našu chválu vedie Tvoj Syn<br/>na konci prebohatej hostiny.<br/>Chválu, ktorá Ti je drahá, sladká,<br/>v Jeho chválení sme zjednotení.<br/>',NULL,129448,1);
INSERT INTO stanza VALUES('SK50','2','Otče, potrebujeme len Teba,<br/>nie lásku, čo je menšia od Tvojej.<br/>Uctievame Ťa, tu môžeme znať<br/>Tvoj nádherný Božský život, Otče.<br/>',NULL,129449,2);
INSERT INTO stanza VALUES('SK50','3','V láske Tvojej láska naša rastie,<br/>všetko zemské, Otče, prevyšuje,<br/>mocne vedie naše srdcia k Tebe,<br/>prítomnosť Tvoja uspokojuje.<br/>',NULL,129450,3);
INSERT INTO stanza VALUES('SK50','4','Otče, v zjednotení s Tvojím Synom<br/>Ťa tu všetci chválime s radosťou,<br/>synovia sa tešia z Tvojho mena,<br/>sýtime sa Tvojou svätou láskou.<br/>',NULL,129451,4);
INSERT INTO stanza VALUES('SK52','1','Radostnú pieseň spolu spievame<br/>Tebe, Otče,<br/>a v Tvojej prítomnosti chválime,<br/>ó, Teba len.<br/>Sme doma s Tebou – milosť úžasná,<br/>v Tvojom Synovi každý miesto má.<br/>',NULL,129452,1);
INSERT INTO stanza VALUES('SK52','2','Ó, hlboká je táto radosť, kde<br/>lásku známe!<br/>Láska Tvoja viditeľná, Otče,<br/>v Synovi je.<br/>Zatiaľ čo v Tebe odpočívame,<br/>On vedie chválu, my Ťa chválime.<br/>',NULL,129453,2);
INSERT INTO stanza VALUES('SK52','3','Syn vedie chválu! Tebe príjemnú<br/>spieva pieseň!<br/>Blízki Tebe, drahí a vzácni sú,<br/>ktorých vedie,<br/>aby mali podiel na Synovi,<br/>miloval si Ho už pred stvorením.<br/>',NULL,129454,3);
INSERT INTO stanza VALUES('SK56','1','Pane, Ty si Božie slovo,<br/>Ty si Božím Synom,<br/>svätý, pravý Boží obraz,<br/>s Otcom navždy jedno.<br/>',NULL,129455,1);
INSERT INTO stanza VALUES('SK56','2','Pane, Ty si Boh samotný,<br/>Jeho stelesňuješ,<br/>v Tebe je Boh prejavený,<br/>vidíme Ho v Tebe.<br/>',NULL,129456,2);
INSERT INTO stanza VALUES('SK56','3','Ty si odblesk Božej slávy,<br/>Tebou na nás žiari.<br/>Si výraz Jeho podstaty,<br/>v Tebe je skutočný.<br/>',NULL,129457,3);
INSERT INTO stanza VALUES('SK56','4','V Tebe je nám Boh životom,<br/>v Tebe je nám svetlom,<br/>v Tebe sme Jeho súčasťou,<br/>sme s Ním navždy jedno.<br/>',NULL,129458,4);
INSERT INTO stanza VALUES('SK56','5','V Tebe trvá milosť Božia,<br/>tešíme sa z Boha,<br/>v Tebe je tiež Božia pravda,<br/>skutočnosť úplná.<br/>',NULL,129459,5);
INSERT INTO stanza VALUES('SK56','6','Napĺňa nás Božia plnosť,<br/>milosť za milosťou,<br/>v Tebe sme zmiešaní s Bohom,<br/>s Ním vo všetkom jedno.<br/>',NULL,129460,6);
INSERT INTO stanza VALUES('SK56','7','Uctievame Ťa, náš Pane,<br/>všetko máme v Tebe,<br/>veľmi Ťa oceňujeme,<br/>Teba milujeme.<br/>',NULL,129461,7);
INSERT INTO stanza VALUES('SK57','1','Obraz Boha, nášho Otca<br/>vidieť v Tebe Pane.<br/>V Tebe celá plnosť Božstva<br/>prebýva telesne.<br/>',NULL,129462,1);
INSERT INTO stanza VALUES('SK57','2','Božím večným slovom Pane,<br/>s božským životom si,<br/>v Tebe Božiu milosť máme,<br/>plnú skutočnosti.<br/>',NULL,129463,2);
INSERT INTO stanza VALUES('SK57','3','Pravý odblesk Božej slávy,<br/>Boží Syn si Pane.<br/>Sám obraz Božej podstaty<br/>v Tebe uznávame.<br/>',NULL,129464,3);
INSERT INTO stanza VALUES('SK57','4','Ty si Božím stelesnením,<br/>s Otcom navždy jedno.<br/>V Tebe je Boh vyjadrený<br/>porovnania nieto.<br/>',NULL,129465,4);
INSERT INTO stanza VALUES('SK57','5','Tešíme sa v Tebe z Boha,<br/>Pane si nám všetkým.<br/>Tebe, Bohu vrúcna vďaka<br/>a chvála naveky.<br/>',NULL,129466,5);
INSERT INTO stanza VALUES('SK61','1','Pane, ako Syn človeka<br/>si pravou pannou splodený,<br/>ľudskou prirodzenosťou si<br/>bol tela, krvi účastný.<br/>',NULL,129467,1);
INSERT INTO stanza VALUES('SK61','2','Ty ako otrok pokorný<br/>si po tejto zemi chodil,<br/>ľudský život, ktorý si mal,<br/>utrpenia podstupoval.<br/>',NULL,129468,2);
INSERT INTO stanza VALUES('SK61','3','Narodený si bol v jasliach,<br/>dieťaťom medzi biednymi,<br/>ako tesár si pracoval,<br/>umrel medzi zločincami.<br/>',NULL,129469,3);
INSERT INTO stanza VALUES('SK61','4','No potom si bol vzkriesený<br/>aj s ľudskou prirodzenosťou<br/>a ako človek s božskosťou<br/>si tiež vystúpil na nebo.<br/>',NULL,129470,4);
INSERT INTO stanza VALUES('SK61','5','Teraz na tróne nad všetkým<br/>si človekom osláveným.<br/>Človek s Bohom v božskom svetle,<br/>s ktorým je Boh už spokojný.<br/>',NULL,129471,5);
INSERT INTO stanza VALUES('SK61','6','V sláve sa vrátiš znovu späť,<br/>prídeš so zjavom človeka.<br/>Kráľ kráľov s božskou mocou a<br/>prirodzenosťou človeka.<br/>',NULL,129472,6);
INSERT INTO stanza VALUES('SK61','7','Budeš centrom všetkých vecí<br/>v novom nebi, novej zemi,<br/>naveky ostaneš božský,<br/>prebývať budeš v ľudskosti.<br/>',NULL,129473,7);
INSERT INTO stanza VALUES('SK62','1','Pán Ježiš, my chválime Ťa,<br/>Ty si „semenom ženy“.<br/>Z panny si bol narodený,<br/>menom ľudským nazvaný.<br/>Pán mal prirodzenosť ľudskú,<br/>človek hada pošliapal,<br/>krížom mu hlavu rozdrvil,<br/>plán Boží tak naplnil.<br/>',NULL,129474,1);
INSERT INTO stanza VALUES('SK62','chorus','Slávu Tvoju zrieme<br/>v Tvojej ľudskej kráse,<br/>nádherná a prejavená<br/>v ľudskosti Tvojej.<br/>',NULL,129475,2);
INSERT INTO stanza VALUES('SK62','2','Ako človek si vtelením<br/>účasť tela, krvi mal,<br/>aby si zničil Satana<br/>namiesto nás a pre nás.<br/>Menom Ježiš, Tebe daným,<br/>Ty si Emanuelom,<br/>Spasiteľom si sa nám stal,<br/>spásu nám tak priniesol.<br/>',NULL,129476,3);
INSERT INTO stanza VALUES('SK62','3','Ty si „posledným Adamom“,<br/>tiež „druhým človekom“ si,<br/>hlavou stvorenia nového,<br/>než prvý človek lepší.<br/>Životom Syna človeka<br/>si na tejto zemi žil,<br/>aj teraz, keď si v nebesiach,<br/>naďalej človekom si.<br/>',NULL,129477,4);
INSERT INTO stanza VALUES('SK62','4','V Bohom stanovenom čase<br/>vrátiš sa na zem opäť<br/>v sláve Otcovej, keď prídeš,<br/>stále človekom budeš.<br/>Aj na súdnom stolci budeš<br/>stále Synom človeka,<br/>našu prirodzenosť ľudskú,<br/>naveky tak budeš mať.<br/>',NULL,129478,5);
INSERT INTO stanza VALUES('SK66','1','Meno Ježiš znie ľúbezne<br/>tým, čo v Neho veria!<br/>Tíši bolesť, lieči rany,<br/>všetok strach zaháňa.<br/>',NULL,129479,1);
INSERT INTO stanza VALUES('SK66','2','Hojí zraneného ducha,<br/>utišuje srdcia.<br/>Je pokojom pre ustatých,<br/>mannou hladným dušiam.<br/>',NULL,129480,2);
INSERT INTO stanza VALUES('SK66','3','Si Skalou, na nej staviame.<br/>Si náš úkryt a štít.<br/>Tvoje veľmi vzácne meno,<br/>je plné milosti.<br/>',NULL,129481,3);
INSERT INTO stanza VALUES('SK66','4','Si Spasiteľ, Pastier, Priateľ,<br/>náš Prorok, Kňaz a Kráľ,<br/>si Pán, Život, Cesta a Cieľ,<br/>preto sme plní chvál.<br/>',NULL,129482,4);
INSERT INTO stanza VALUES('SK66','5','Krehké je naše úsilie<br/>a myšlienky chladné,<br/>avšak keď Teba vidíme,<br/>chváliť Ťa musíme.<br/>',NULL,129483,5);
INSERT INTO stanza VALUES('SK66','6','Každým dychom Tvoju lásku<br/>vždy ohlasujeme<br/>a víťazstvo Tvojho mena,<br/>čo smrť pohlcuje.<br/>',NULL,129484,6);
INSERT INTO stanza VALUES('SK68','1','Ježišom pomenovaný,<br/>nádherným, drahým menom.<br/>Zrodený si, Pane, z panny,<br/>stal sa človeka Synom.<br/>Ty si náš Hospodin, spása,<br/>z hriechov sme zachránení,<br/>ak veríme v spásu – Teba,<br/>počneš v nás život nový.<br/>',NULL,129485,1);
INSERT INTO stanza VALUES('SK68','2','Kristus je titulom Tvojím,<br/>titulom služby Tvojej.<br/>Ty Božím si Pomazaným<br/>od večnosti minulej.<br/>Mesiáš Boží si, Pane,<br/>v láske ustanovený,<br/>tým napĺňaš Jeho zámer,<br/>Božiu slávu prejavíš.<br/>',NULL,129486,2);
INSERT INTO stanza VALUES('SK68','3','Nazvaný si Emanuel,<br/>pretože si Boh s nami,<br/>s našou vlastnou ľudskosťou je<br/>Boh v milosti zmiešaný.<br/>Ó, Boh je zjavený v tele<br/>milosti, pravdy plný.<br/>Božiu slávu v Tebe zrieme,<br/>vierou v Ňom zúčastnení.<br/>',NULL,129487,3);
INSERT INTO stanza VALUES('SK68','4','Tie mená oceňujeme,<br/>toľko nám odhaľujú,<br/>sú sladké a veľmi cenné,<br/>navždy v láske naše sú.<br/>Spasiteľa milujeme,<br/>Tebe úctu vzdávame,<br/>velebíme, Emanuel,<br/>stále chvály spievame.<br/>',NULL,129488,4);
INSERT INTO stanza VALUES('SK70','1','Meno, ktoré tak milujem<br/>je veľmi hodnotné.<br/>V ušiach mi ako hudba znie,<br/>na zemi najsladšie.<br/>',NULL,129489,1);
INSERT INTO stanza VALUES('SK70','chorus','Milujem Ježiša,<br/>milujem Ježiša,<br/>milujem Ježiša,<br/>On ma prv miloval!<br/>',NULL,129490,2);
INSERT INTO stanza VALUES('SK70','2','Môj Spasiteľ ma miluje,<br/>Svoj život za mňa dal.<br/>Som slobodný, Jeho krv je<br/>hriešnikov záchrana.<br/>',NULL,129491,3);
INSERT INTO stanza VALUES('SK70','3','Môj Otec mal pre mňa denne<br/>niečo pripravené,<br/>hoci som kráčal v temnote,<br/>žiaril na mňa denne.<br/>',NULL,129492,4);
INSERT INTO stanza VALUES('SK70','4','Ó, Jeho ľúbiace srdce<br/>vie vnímať súženie.<br/>Znáša jeho najväčší diel,<br/>čo iný nenesie.<br/>',NULL,129493,5);
INSERT INTO stanza VALUES('SK78','1','Ó, Tvoje meno „JA SOM“ je,<br/>vzácne, bohaté a plné,<br/>je všetkozahŕňajúce,<br/>potrebujem Ťa!<br/>',NULL,129494,1);
INSERT INTO stanza VALUES('SK78','2','Ty si Syn, Otec je v Tebe,<br/>ako Duch prebývaš vo mne,<br/>’by sme zakúšali hojne<br/>bohatstvá Tvoje.<br/>',NULL,129495,2);
INSERT INTO stanza VALUES('SK78','3','Ty si Božím chrámom, Pane,<br/>navždy Otca vyjadrenie,<br/>v Tebe sa vždy radujeme,<br/>Otca vidíme.<br/>',NULL,129496,3);
INSERT INTO stanza VALUES('SK78','4','Si baránkom aj ženíchom,<br/>pre nevestu znášal si bôľ,<br/>ukrižovaný za nás bol,<br/>odpočívame.<br/>',NULL,129497,4);
INSERT INTO stanza VALUES('SK78','5','Ty si múdrosťou aj cestou,<br/>plánovač našich životov.<br/>Ty napĺňaš nás milosťou,<br/>v Tebe kráčame.<br/>',NULL,129498,5);
INSERT INTO stanza VALUES('SK78','6','Rýdzi, svätý, spravodlivý,<br/>Jeho srdcu príjemný si,<br/>ó, do nášho vnútra dal si<br/>jednotu s Bohom.<br/>',NULL,129499,6);
INSERT INTO stanza VALUES('SK78','7','Ty si svetlo aj život náš,<br/>ukončil smrť, noc vyháňaš,<br/>oživil a daroval zrak,<br/>my sme slobodní.<br/>',NULL,129500,7);
INSERT INTO stanza VALUES('SK78','8','Silou vzkriesenia si, Pane,<br/>Ty si víťaz v hodine zlej,<br/>Svojou mocou posilňuješ,<br/>tak kraľujeme.<br/>',NULL,129501,8);
INSERT INTO stanza VALUES('SK78','9','Živou vodou, pokrmom si,<br/>za všetkých ľudí umrel si.<br/>Takto všetko uspokojíš,<br/>my hodujeme.<br/>',NULL,129502,9);
INSERT INTO stanza VALUES('SK78','10','Pane, pastier aj lekár si,<br/>našu nemoc uzdravil si,<br/>utešuješ, vedieš, chrániš,<br/>stále dbáš o nás.<br/>',NULL,129503,10);
INSERT INTO stanza VALUES('SK78','11','Kňazom aj kráľom si navždy,<br/>priviedol si nás k Otcovi.<br/>Sme na tróne usadení,<br/>na čestnom mieste!<br/>',NULL,129504,11);
INSERT INTO stanza VALUES('SK78','12','Si vykúpenie a nádej,<br/>premieňaš staré stvorenie,<br/>z nás si činíš znásobenie,<br/>tak sa vyjadríš.<br/>',NULL,129505,12);
INSERT INTO stanza VALUES('SK78','13','Radosťou, pokojom, slávou,<br/>pravdou, milosťou a skalou,<br/>stromom života aj stavbou<br/>si, drahý Pane.<br/>',NULL,129506,13);
INSERT INTO stanza VALUES('SK78','14','Pane, si neobmedzený,<br/>dokonalý a bohatý,<br/>všetky potreby naplníš,<br/>pretekáš cez nás.<br/>',NULL,129507,14);
INSERT INTO stanza VALUES('SK81','1','Ó, Pane si dávnoveký,<br/>bol si pred začatím vekov!<br/>Pretože si Otec večný,<br/>veľký, nestvorený JA SOM!<br/>',NULL,129508,1);
INSERT INTO stanza VALUES('SK81','2','Aj keď si sa stal človekom,<br/>aj naďalej si Boh večný!<br/>Zdieľaš všetku plnosť s Bohom,<br/>ako On si nekonečný!<br/>',NULL,129509,2);
INSERT INTO stanza VALUES('SK81','3','Pôvodom si Boh samotný,<br/>pred vznikom stvorenia si bol!<br/>Ty si prvý, si pred všetkým,<br/>iný nik nie je pred Tebou!<br/>',NULL,129510,3);
INSERT INTO stanza VALUES('SK81','4','Ty si sa nikdy nezmenil,<br/>veď Tvoje roky sú večné!<br/>Nič netrvá tak ako Ty,<br/>iný nik nie je po Tebe!<br/>',NULL,129511,4);
INSERT INTO stanza VALUES('SK81','5','Ako Otec si rovnaký,<br/>si rovnako dokonalý!<br/>Ty si alfa, Ty si prvý,<br/>si omega, si posledný!<br/>',NULL,129512,5);
INSERT INTO stanza VALUES('SK81','6','Chvála Ti, si nekonečný,<br/>vyvýšený, dokonalý!<br/>Za Svoju plnosť a večnosť<br/>si nami obdivovaný!<br/>',NULL,129513,6);
INSERT INTO stanza VALUES('SK84','1','Hľa, anjeli spievajú:<br/>„Sláva Kráľu novému,<br/>pokoj ľuďom na zemi,<br/>Boh s hriešnikmi zmierený.“<br/>Národy povstávajú,<br/>s anjelmi ohlasujú:<br/>„Narodil sa Kristus Pán<br/>v meste kráľa Dávida.“<br/>',NULL,129514,1);
INSERT INTO stanza VALUES('SK84','2','Krista nebo uctieva,<br/>Kristus, nekonečný Pán,<br/>On k nám v čase zostúpil<br/>a z panny sa narodil,<br/>v tele žil, no bol božský,<br/>On je Bohom vteleným!<br/>Stal sa pre nás človekom,<br/>On je Emanuelom.<br/>',NULL,129515,2);
INSERT INTO stanza VALUES('SK84','3','Princ mieru sa narodil!<br/>Slnko spravodlivosti!<br/>Prináša svetlo všetkým,<br/>na krídlach s uzdravením.<br/>Svoju slávu odložil,<br/>aby človek večne žil.<br/>On sa pre nás narodil,<br/>aby nás znovuzrodil.<br/>',NULL,129516,3);
INSERT INTO stanza VALUES('SK84','4','Príď, ó, Túžba národov!<br/>Ty si v nás učiň domov.<br/>Semeno ženy, povstaň,<br/>rozdrv v nás hlavu hada.<br/>Zmaž Adama podobu,<br/>zameň ju za tú Svoju.<br/>Adam zhora, posledný,<br/>Ty nás v láske obnovíš.<br/>',NULL,129517,4);
INSERT INTO stanza VALUES('SK86','1','Si slávny Boh a Najvyšší,<br/>prišiel si k nám vo vtelení,<br/>stal sa človekom najnižším.<br/>Pane, spomínam Ťa!<br/>',NULL,129518,1);
INSERT INTO stanza VALUES('SK86','2','Slávu Božiu si odložil,<br/>pod stánkom Svojho tela žil,<br/>navonok krásu nezjavil.<br/>Pane, spomínam Ťa!<br/>',NULL,129519,2);
INSERT INTO stanza VALUES('SK86','3','Si koreň z vyschnutej zeme,<br/>človek, čo znášal súženie,<br/>neustále pohŕdanie.<br/>Pane, spomínam Ťa!<br/>',NULL,129520,3);
INSERT INTO stanza VALUES('SK86','4','Srdce máš jemné a skromné,<br/>ochotné niesť utrpenie,<br/>nikomu sa nesťažuje.<br/>Pane, spomínam Ťa!<br/>',NULL,129521,4);
INSERT INTO stanza VALUES('SK86','5','Človekom si nežným, sladkým,<br/>v každom smere vyváženým,<br/>múčnou obeťou Otcovi.<br/>Pane, spomínam Ťa!<br/>',NULL,129522,5);
INSERT INTO stanza VALUES('SK86','6','Vždy si vôľu Otca činil,<br/>klamstvám Satana neveril,<br/>nikto nie je taký verný.<br/>Pane, spomínam Ťa!<br/>',NULL,129523,6);
INSERT INTO stanza VALUES('SK86','7','Otcovi si bol poslušný,<br/>to Ťa doviedlo až na kríž,<br/>na ktorom si ma zamenil.<br/>Pane, spomínam Ťa!<br/>',NULL,129524,7);
INSERT INTO stanza VALUES('SK86','8','Bol si Bohom povýšený,<br/>slávou, cťou korunovaný,<br/>nebo aj zem sa Ti korí.<br/>Pane, uctievam Ťa!<br/>',NULL,129525,8);
INSERT INTO stanza VALUES('SK96','1','Spievam nevídanú<br/>lásku Spasiteľa<br/>tým, čo jej nemajú,<br/>im je prejavená.<br/>Ó, ktože som, že kvôli mne<br/>môj Pán prišiel za mňa umrieť?<br/>',NULL,129526,1);
INSERT INTO stanza VALUES('SK96','2','Z trónu zostúpil k nám,<br/>spásou obdaroval,<br/>túžobného Krista<br/>nik z ľudí nespoznal.<br/>Si priateľ môj, ten skutočný,<br/>ktorý pre mňa život stratil.<br/>',NULL,129527,2);
INSERT INTO stanza VALUES('SK96','3','Vystlali Mu cestu<br/>a chvály spievali,<br/>celý deň je počuť:<br/>Hosana kráľovi!<br/>Neskôr znelo: Ukrižovať!<br/>Začali smrť požadovať.<br/>',NULL,129528,3);
INSERT INTO stanza VALUES('SK96','4','Aby odišiel Pán,<br/>si svorne žiadali,<br/>prepustili vraha,<br/>Život zavraždili.<br/>On, ochotný, išiel na kríž,<br/>’by ich mohol oslobodiť.<br/>',NULL,129529,4);
INSERT INTO stanza VALUES('SK96','5','Pán keď bol na zemi,<br/>nemal dom nádherný,<br/>keď zomrel, hrob pekný,<br/>no miesto pre cudzích.<br/>Jeho domom sú nebesia,<br/>mojím je hrob, v ktorom ležal.<br/>',NULL,129530,5);
INSERT INTO stanza VALUES('SK96','6','Môžem tu stáť, spievať<br/>ten príbeh je božský<br/>o Kráľovej láske,<br/>o Jeho skľúčení.<br/>Je priateľom, ktorého chcem<br/>ospevovať po celý deň.<br/>',NULL,129531,6);
INSERT INTO stanza VALUES('SK116','1','Vykúpenie je nádherné,<br/>Milostivý, v Tebe!<br/>To, čo si pre mňa učinil,<br/>je nad pochopenie!<br/>Ty si božský a tajomný,<br/>opísať to neviem!<br/>Vykúpenie je úžasné,<br/>nech Tebe chvála znie!<br/>',NULL,129532,1);
INSERT INTO stanza VALUES('SK116','2','Za nás na kríži bodnutý,<br/>krv a voda tiekli.<br/>Božský život sme prijali,<br/>tak sme vykúpení.<br/>Krv vzácna nás očistila,<br/>Tebou sme prijatí.<br/>Tvoj život nás znovuzrodil,<br/>a s Tebou zjednotil.<br/>',NULL,129533,2);
INSERT INTO stanza VALUES('SK116','3','Ty si zrnkom, čo umrelo,<br/>my sme mnohé zrnká,<br/>premiešaní, Tvoje Telo<br/>aj Tvoja povaha.<br/>Sme Tvojím nárastom, Pane,<br/>obsahujeme Ťa.<br/>Cez nás dnes kráčaš a žiješ,<br/>takto Svoj prejav máš.<br/>',NULL,129534,3);
INSERT INTO stanza VALUES('SK116','4','Sme Tvoje Telo, môžeš prísť<br/>a usadiť sa v nás,<br/>môžeš v nás získať Svoj domov,<br/>a dôveru mať v nás.<br/>Aby sme Ťa potešili,<br/>sme náprotivok Tvoj,<br/>spolu s Tebou v jednom Tele,<br/>tešíme sa Tebou.<br/>',NULL,129535,4);
INSERT INTO stanza VALUES('SK116','5','Zatiaľ čo Ťa spomíname,<br/>hľadiac na symboly,<br/>vďačíme za vykúpenie,<br/>chválou naplnení.<br/>Keďže sme Ti Telom, Pane,<br/>domovom, nevestou,<br/>vďačíme a uctievame<br/>chválou neprestajnou.<br/>',NULL,129536,5);
INSERT INTO stanza VALUES('SK124','1','Chvála Kristu! Víťazovi!<br/>Víťazstvo je získané!<br/>Odsúdil hriech, Adam skončil,<br/>vidíme vykúpenie!<br/>Kristus Svojím krížom zrazil<br/>zlé mocnosti víťazne!<br/>',NULL,129537,1);
INSERT INTO stanza VALUES('SK124','2','Chváľme vzkrieseného Krista!<br/>Boh Mu dal z mŕtvych povstať!<br/>Moc smrti je pohltená,<br/>prešli sme do života!<br/>Prelomené je peklo, tma,<br/>Jeho sila je zjavná!<br/>',NULL,129538,2);
INSERT INTO stanza VALUES('SK124','3','Chvála Kristu na nebesiach!<br/>Boh Ho pozdvihol na trón!<br/>Je nad každou vládou, mocou,<br/>dostal najvyššie meno!<br/>Uplatňuje autoritu,<br/>až zvrhne nepriateľov!<br/>',NULL,129539,3);
INSERT INTO stanza VALUES('SK124','4','Aleluja! Pán je Víťaz!<br/>Svojím krížom zvíťazil!<br/>Aleluja, vzkriesený je,<br/>Svoje víťazstvo zjavil!<br/>Aleluja, je na tróne,<br/>bude vládnuť naveky!<br/>',NULL,129540,4);
INSERT INTO stanza VALUES('SK132','1','Hľa! Na tróne v nebesiach je<br/>Pán Ježiš posadený.<br/>Človek vyvýšený Bohom,<br/>slávou korunovaný.<br/>',NULL,129541,1);
INSERT INTO stanza VALUES('SK132','2','Vzal si ľudskú prirodzenosť,<br/>podľa plánu Božieho.<br/>Zomrel v tele, vzkriesený bol,<br/>a vystúpil na nebo.<br/>',NULL,129542,2);
INSERT INTO stanza VALUES('SK132','3','Boh na zemi nízky bol v Ňom,<br/>Boh, On sídlil s človekom,<br/>človek je vyvýšený v Ňom,<br/>a je zmierený s Bohom.<br/>',NULL,129543,3);
INSERT INTO stanza VALUES('SK132','4','Boh je s človekom zmiešaný,<br/>je v človeku svedectvom,<br/>človek je s Bohom zladený,<br/>je oslávený Bohom.<br/>',NULL,129544,4);
INSERT INTO stanza VALUES('SK132','5','Z neba od Osláveného<br/>prišiel zahrnutý Duch.<br/>Ježiša a dielo Jeho,<br/>ohlasuje tento Duch.<br/>',NULL,129545,5);
INSERT INTO stanza VALUES('SK132','6','Spolu s Osláveným v nebi<br/>je Cirkev stotožnená,<br/>skrze Ducha Ježišovho<br/>je Cirkev budovaná.<br/>',NULL,129546,6);
INSERT INTO stanza VALUES('SK132','7','Hľa! Človek je teraz v nebi,<br/>tróni ako Pán všetkých,<br/>Spasiteľ náš, Kristus Ježiš,<br/>slávou korunovaný.<br/>',NULL,129547,7);
INSERT INTO stanza VALUES('SK133','1','Pán Ježiš, si Pánom všetkých,<br/>slávy korunu máš.<br/>V Svojej sláve, vznešenosti<br/>sa všetkým poznať dáš.<br/>',NULL,129548,1);
INSERT INTO stanza VALUES('SK133','2','Boh v človeku na zemi bols’<br/>vo forme otroka.<br/>Ako človek v Bohu si dnes<br/>Pán všetkých v nebesiach.<br/>',NULL,129549,2);
INSERT INTO stanza VALUES('SK133','3','Si človekom v sláve,<br/>Pane, na trón usadený.<br/>Moc na nebesiach aj zemi<br/>všetka Tebe patrí.<br/>',NULL,129550,3);
INSERT INTO stanza VALUES('SK133','4','Do nebies si vyvýšený,<br/>najvyššie meno máš.<br/>Každý vyzná, že Pánom si,<br/>a zohne kolená.<br/>',NULL,129551,4);
INSERT INTO stanza VALUES('SK133','5','Boh Ťa spravil Pánom, Kristom,<br/>Duch nám to vyhlásil.<br/>V sláve v nebesiach vidíme,<br/>s Bohom na tróne si.<br/>',NULL,129552,5);
INSERT INTO stanza VALUES('SK133','6','Klaniame sa, Pane slávy,<br/>piesne Ti spievame.<br/>Uctievame Pána všetkých,<br/>veľmi Ťa chválime!<br/>',NULL,129553,6);
INSERT INTO stanza VALUES('SK170','1','Krásnym Ženíchom si, Pane,<br/>Bohom daný, nám drahý.<br/>Príťažlivý si nesmierne,<br/>našim srdciam nádherný.<br/>',NULL,129554,1);
INSERT INTO stanza VALUES('SK170','2','Obdivujeme Ťa, Drahý,<br/>kto tú vzácnosť ocení?<br/>Vážime si lásku Tvoju,<br/>si nevýslovne milý.<br/>',NULL,129555,2);
INSERT INTO stanza VALUES('SK170','3','Zo všetkých si najčestnejší,<br/>zo všetkých si najsladší.<br/>Si mierny a milostivý,<br/>nik Ti nie je podobný.<br/>',NULL,129556,3);
INSERT INTO stanza VALUES('SK170','4','Rúcha Tvoje myrha samá,<br/>pery milosti plné.<br/>V príchuti Tvojho súženia<br/>s láskou Ťa objímame.<br/>',NULL,129557,4);
INSERT INTO stanza VALUES('SK170','5','Tvoj Boh Ťa hojne pomazal<br/>olejom potešenia.<br/>Slonovinové paláce,<br/>z nich Ti chvála vyteká.<br/>',NULL,129558,5);
INSERT INTO stanza VALUES('SK170','6','Boh Ťa požehnal naveky,<br/>Ty si získal víťazstvo.<br/>V sláve si teraz na tróne<br/>s mocou a vznešenosťou.<br/>',NULL,129559,6);
INSERT INTO stanza VALUES('SK170','7','Národov všetkých si túžbou,<br/>Teba ocenia všetky.<br/>Najvyšší z desať tisícov,<br/>našej lásky vždy hodný.<br/>',NULL,129560,7);
INSERT INTO stanza VALUES('SK187','1','To, aký si k nám prehojný,<br/>láskou, Pane vidíme!<br/>Tvoje nesmierne bohatstvo<br/>v duchu len oceníme.<br/>',NULL,129561,1);
INSERT INTO stanza VALUES('SK187','2','Na počiatku bolo slovo<br/>bolo Boh, aj u Boha.<br/>On bol slovom, stal sa telom,<br/>Boha zadefinoval.<br/>',NULL,129562,2);
INSERT INTO stanza VALUES('SK187','3','Ty si pravým svätostánkom,<br/>v ňom slávu Božiu zrieme.<br/>Pre Boha si svätým chrámom,<br/>Boh má Svoj príbeh v Tebe.<br/>',NULL,129563,3);
INSERT INTO stanza VALUES('SK187','4','Si Božím Synom jediným,<br/>na známosť Otca dávaš,<br/>’by sme mali život božský,<br/>a prirodzenosť Boha.<br/>',NULL,129564,4);
INSERT INTO stanza VALUES('SK187','5','Si ako my, Syn človeka<br/>s ľudskou prirodzenosťou,<br/>’by sme boli synmi Boha,<br/>rastom, Tvojou plnosťou.<br/>',NULL,129565,5);
INSERT INTO stanza VALUES('SK187','6','Ty si Kristus, si Pán všetkých,<br/>ten Bohom Pomazaný,<br/>Ty si všetkým, si vo všetkom<br/>Bohu, aj nám určený.<br/>',NULL,129566,6);
INSERT INTO stanza VALUES('SK187','7','Spasiteľ ukrižovaný,<br/>krv a voda vytiekli,<br/>my sme Bohom vykúpení,<br/>božský život získali.<br/>',NULL,129567,7);
INSERT INTO stanza VALUES('SK187','8','Ty si oslávený Ježiš,<br/>zostúpil od Teba Duch,<br/>prináša nám všetko čo máš,<br/>On je všeobsažný  Duch.<br/>',NULL,129568,8);
INSERT INTO stanza VALUES('SK187','9','Pane, si svetlom života,<br/>ktoré v temnote svieti.<br/>Božské svetlo, žiariš s Bohom<br/>v našich srdciach v plnosti.<br/>',NULL,129569,9);
INSERT INTO stanza VALUES('SK187','10','Pane, Ty si život božský,<br/>čo nám ducha oživil<br/>a zo smrti nás vyviedol,<br/>našu bytosť posilnil.<br/>',NULL,129570,10);
INSERT INTO stanza VALUES('SK187','11','Pane, si Božia skutočnosť,<br/>pravda, čo Boha teší,<br/>pravda, čo prináša Teba,<br/>aby sme Ťa poznali.<br/>',NULL,129571,11);
INSERT INTO stanza VALUES('SK187','12','Pane, si cesta života,<br/>čo nás vedie do slávy,<br/>cesta Tvojej skutočnosti<br/>z nás víťazov učiní.<br/>',NULL,129572,12);
INSERT INTO stanza VALUES('SK187','13','Smrť životom pohltená,<br/>lebo Ty si vzkriesenie.<br/>Len vzkriesením nesieme kríž,<br/>Teba nasledujeme.<br/>',NULL,129573,13);
INSERT INTO stanza VALUES('SK187','14','Si čistý Baránok Boží,<br/>zomrel’s, ’bys nás vykúpil.<br/>Si život darujúci Duch,<br/>aby si znovuzrodil.<br/>',NULL,129574,14);
INSERT INTO stanza VALUES('SK187','15','Pane, Ty si had bronzový,<br/>od zlého zachraňuješ.<br/>Na dreve si bol zdvihnutý,<br/>za nás diabla rozšliapeš.<br/>',NULL,129575,15);
INSERT INTO stanza VALUES('SK187','16','Si Pastierom aj dverami,<br/>si východom z ovčinca.<br/>Plne si nás oslobodil,<br/>vyviedol na pastviská.<br/>',NULL,129576,16);
INSERT INTO stanza VALUES('SK187','17','Pane, Tvojím obmývaním<br/>sme stále očistení,<br/>v spoločenstve zachovaní,<br/>ó, k nám si naklonený.<br/>',NULL,129577,17);
INSERT INTO stanza VALUES('SK187','18','Ty si rozštiepená sklala,<br/>živý tok sa uvoľnil.<br/>Uhášajúcu moc známe<br/>z osviežujúcej vody.<br/>',NULL,129578,18);
INSERT INTO stanza VALUES('SK187','19','Ty si prameňom nebeským,<br/>živá voda je v Tebe.<br/>Pijeme Tvoj život večný,<br/>už viac nevysmädneme.<br/>',NULL,129579,19);
INSERT INTO stanza VALUES('SK187','20','Si nebeský chlieb života,<br/>božský pokrm prehojný.<br/>Tvojím nesmiernym bohatstvom<br/>je náš duch vyživený.<br/>',NULL,129580,20);
INSERT INTO stanza VALUES('SK187','21','Si naším dychom života,<br/>v duchu Ťa vdychujeme.<br/>V Tebe žijeme, kráčame,<br/>Tvoju hojnosť dedíme.<br/>',NULL,129581,21);
INSERT INTO stanza VALUES('SK187','22','Si božské zrnko pšeničné,<br/>umrelo, vstalo v sláve.<br/>Z jedného sme tu dnes mnohí,<br/>tvoríme Telo slávne.<br/>',NULL,129582,22);
INSERT INTO stanza VALUES('SK187','23','Si pravý, nebeský vinič,<br/>v Tebe sme ratolesti.<br/>Prebývame v Tebe, Ty v nás,<br/>Tešíme sa z hojnosti.<br/>',NULL,129583,23);
INSERT INTO stanza VALUES('SK187','24','Si Ženích spolu s nevestou,<br/>vezmeš ju, Tvoje Telo.<br/>V živote, láske a sláve<br/>budeme s Tebou jedno.<br/>',NULL,129584,24);
INSERT INTO stanza VALUES('SK187','25','Si rebrík z Jakubovho sna,<br/>nebesia si otvoril.<br/>Pane, v Tebe sme dom Boží,<br/>zem si s nebom prepojil.<br/>',NULL,129585,25);
INSERT INTO stanza VALUES('SK187','26','Ó, Pane, si veľký „JA SOM“,<br/>to, čo potrebujeme,<br/>si pre nás všetko vo všetkom,<br/>zámer Boží splníme.<br/>',NULL,129586,26);
INSERT INTO stanza VALUES('SK189','1','Božím Ty si obrazom,<br/>si Syn milovaný,<br/>svätých drahým podielom,<br/>krvou darovaným.<br/>V celom Božom stvorení<br/>si Prvorodený.<br/>Tebou bolo stvorené,<br/>aby si Ho vlastnil.<br/>',NULL,129587,1);
INSERT INTO stanza VALUES('SK189','2','Si pred všetkým stvorením<br/>a v Tebe spočíva.<br/>Všetkého Ty si centrom,<br/>všetko je skrz Teba.<br/>Si jediným počiatkom,<br/>z mŕtvych prvým si Ty.<br/>Pre Cirkev, Svoje Telo,<br/>slávnou Hlavou si Ty.<br/>',NULL,129588,2);
INSERT INTO stanza VALUES('SK189','3','Že v Tebe všetka plnosť,<br/>milé je Otcovi,<br/>aby si mal prvenstvo<br/>vždy a vo všetkom Ty.<br/>Všetko si s Bohom zmieril<br/>prostredníctvom krvi<br/>a tak si nás priniesol<br/>Bohu bezúhonných.<br/>',NULL,129589,3);
INSERT INTO stanza VALUES('SK189','4','Plnosť Božstva je v Tebe,<br/>si tajomstvom Božím,<br/>všetky poklady v Tebe,<br/>poznania, múdrosti.<br/>Ty v nás prebývaš, Pane.<br/>Si nádejou slávy,<br/>zdokonaľovaní sme,<br/>a Boh je spokojný.<br/>',NULL,129590,4);
INSERT INTO stanza VALUES('SK189','5','Všetko je iba tieňom,<br/>ktorý nám zjavuje,<br/>že sme zakorenení<br/>v Tebe, realite.<br/>Vychutnávaním Teba<br/>plnosťou budeme,<br/>vrastať s Bohom do Teba,<br/>Telom Ti budeme.<br/>',NULL,129591,5);
INSERT INTO stanza VALUES('SK189','6','S Tebou v Bohu skrytí sme,<br/>Ty si v nás, život náš.<br/>Tvoj odpočinok máme,<br/>pokoj panuje v nás.<br/>V novom človeku, v Tele,<br/>si všetkým vo všetkých.<br/>Všetko zahŕňajúci,<br/>Spasiteľ naveky.<br/>',NULL,129592,6);
INSERT INTO stanza VALUES('SK190','1','Pane, dnes Ťa spomíname,<br/>uctievame, ó, si všetkým.<br/>Si bohatý a nádherný,<br/>našim srdciam veľmi drahý.<br/>',NULL,129593,1);
INSERT INTO stanza VALUES('SK190','chorus','Si tým, čo potrebujeme!<br/>Ó, chválou prekypujeme!<br/>Každé prianie presahuješ<br/>a stále uspokojuješ.<br/>',NULL,129594,2);
INSERT INTO stanza VALUES('SK190','2','Si sám Boh v pravde, ó, Pane,<br/>si Láskou aj Svetlom, Bože,<br/>Boh, čo naším životom je,<br/>Boh, čo všetkých potešuje.<br/>',NULL,129595,3);
INSERT INTO stanza VALUES('SK190','3','Pravý človek si zároveň,<br/>človek jemný, dobrý, čistý,<br/>človek, čo nám lásku chráni,<br/>človek, v ktorom sa Boh teší.<br/>',NULL,129596,4);
INSERT INTO stanza VALUES('SK190','4','Dokonca otrok nízky si,<br/>Boží otrok, čo slúži nám,<br/>si poslušný, ó, až po kríž,<br/>vyslobodenie dal si nám.<br/>',NULL,129597,5);
INSERT INTO stanza VALUES('SK190','5','Okrem všetkého, tiež si Kráľ,<br/>čo vládne v láske, v živote,<br/>pomazaný Božou mocou<br/>spravovať Jeho územie.<br/>',NULL,129598,6);
INSERT INTO stanza VALUES('SK190','6','Spomíname Ťa, Pán Drahý,<br/>tak máme účasť na Tebe,<br/>náprotivkom Ti budeme,<br/>tým, že Ťa vychutnávame.<br/>',NULL,129599,7);
INSERT INTO stanza VALUES('SK191','1','Pane, si „semenom ženy“,<br/>abys’ diabla rozdrvil,<br/>odel si sa do ľudskosti,<br/>Svojou smrťou zvíťazil.<br/>Ako Boh si bol, vtelený,<br/>tela, krvi účastný,<br/>diabla si smrťou rozmliaždil,<br/>jeho moc smrti zrušil.<br/>',NULL,129600,1);
INSERT INTO stanza VALUES('SK191','2','Ako „semä Abraháma“<br/>si Božím prisľúbením,<br/>sľúbené požehnanie tak<br/>môže prísť k ľuďom všetkým.<br/>Ty si bol pred Abrahámom,<br/>lebo si veľký „JA SOM“,<br/>prišiel si mu byť potomkom,<br/>prisľúbeným „Baránkom“.<br/>',NULL,129601,2);
INSERT INTO stanza VALUES('SK191','3','„Semä Dávida“ si, Pane,<br/>kráľovstvo si založil,<br/>pre Božiu slávu a stavbu<br/>na trón si sa posadil.<br/>„Dávidovým potomkom“ si,<br/>no on Ťa volal „môj Pán“,<br/>bo jeho „koreň“ aj zdroj si,<br/>naveky si „všetkých Pán“.<br/>',NULL,129602,3);
INSERT INTO stanza VALUES('SK191','4','Hoc si prišiel ako „dieťa“,<br/>„Boh Mocný“ Ťa volali,<br/>hoc si „synom“ nám daným, no<br/>„Večným Otcom“ nazvaný.<br/>Všetky Božie požehnania<br/>sú od viery závislé,<br/>si pre nich „áno“ aj „amen“,<br/>celý obsah a aj cieľ!<br/>',NULL,129603,4);
INSERT INTO stanza VALUES('SK193','1','Drahý Pane, si nám mnohým,<br/>všetkým vo všetkom si,<br/>všetko, čo potrebujeme,<br/>Sebou vieš naplniť.<br/>Naše srdcia si Ťa cenia,<br/>duch náš Ťa uctieva,<br/>vidíme Tvoje bohatstvá,<br/>ó, chvála Ti veľká.<br/>',NULL,129604,1);
INSERT INTO stanza VALUES('SK193','2','Si Prorok, Boh Ťa pozdvihol,<br/>cez Teba hovorí,<br/>ako Mojžiš si plán Boží,<br/>Pane, zjavil celý.<br/>Ako Jonáš si poslaný,<br/>bys’ umrel a ožil,<br/>každý nech týmto znamením,<br/>Pane, v Teba verí.<br/>',NULL,129605,2);
INSERT INTO stanza VALUES('SK193','3','Si Prorok spomedzi ľudí,<br/>Tvoje slovo žiari,<br/>láskou ako Elizeus<br/>mocné konáš divy.<br/>Ty si ako Izaiáš,<br/>Krista si odhalil,<br/>’by život bohatý, pravý<br/>Kristov sme zdieľali.<br/>',NULL,129606,3);
INSERT INTO stanza VALUES('SK193','4','Od nás si Kňazom pre Boha,<br/>za nás Kňazom svätým,<br/>sťa Áron nám posluhuješ,<br/>povolaný z ľudí.<br/>Nesieš nás v láske pred Boha,<br/>si Veľkňaz ohromný,<br/>za nás sa tam prihovoríš<br/>a tým nás posilníš.<br/>',NULL,129607,4);
INSERT INTO stanza VALUES('SK193','5','Pre nás si Kňazom od Boha,<br/>kráľovský Kňaz Boží,<br/>ako Melchizedech pre nás<br/>Boží si služobník.<br/>S chlebom a vínom od Boha,<br/>prišiel si v čas pravý,<br/>prišiel si spolu s Bohom k nám,<br/>aby sme Ho mali.<br/>',NULL,129608,5);
INSERT INTO stanza VALUES('SK193','6','Ty Kráľom ako Dávid si,<br/>Túžbu Božiu hľadáš,<br/>nepriateľ je porazený,<br/>nič krom Boha nemáš.<br/>Na tróne si upevnený,<br/>nie palicou ľudskou,<br/>ale aby si vládol nám,<br/>autoritou božskou.<br/>',NULL,129609,6);
INSERT INTO stanza VALUES('SK193','7','Si kráľom ako Šalamún,<br/>pokojom kraľuješ<br/>a vládneš Svojou múdrosťou,<br/>Boží dom buduješ.<br/>Ty s láskou kraľuješ ako<br/>Kráľ neviditeľný,<br/>jedného dňa spolu s nami<br/>budeš odobrený.<br/>',NULL,129610,7);
INSERT INTO stanza VALUES('SK193','8','Si Kráľom, Kňazom, Prorokom,<br/>Pane, si predrahý,<br/>si vzácny pre Boha, aj nám,<br/>sme Tebou dojatí.<br/>Veľmi Ťa oceňujeme,<br/>srdcia priťahuješ,<br/>budeme Ťa vychvaľovať,<br/>večne, neprestajne.<br/>',NULL,129611,8);
INSERT INTO stanza VALUES('SK194','1','Si svedectvom Božím, Pane,<br/>než zákon si lepší.<br/>Je len Tvojím predobrazom,<br/>literou písaný.<br/>Bol iba definíciou,<br/>obrazom Boha bol.<br/>Ti si Božou skutočnosťou,<br/>v Tebe prebýva Boh.<br/>',NULL,129612,1);
INSERT INTO stanza VALUES('SK194','2','Aj truhla svedectva bola<br/>predobrazom Tvojím.<br/>Zákon Boží do nej daný,<br/>v Tebe Boha vidím.<br/>Truhla z dreva vyrobená,<br/>zlatom potiahnutá,<br/>je obraz Teba – človeka,<br/>ktorý nesie Boha.<br/>',NULL,129613,2);
INSERT INTO stanza VALUES('SK194','3','Ty si Božím svätým stanom,<br/>svätým miestom Božím.<br/>Plný milosti a pravdy,<br/>Si v tele vtelený.<br/>Slávu Božiu v Tebe vidno,<br/>Ty si Slovom Božím.<br/>Slovami, láskou, svetlom si<br/>Boh definovaný.<br/>',NULL,129614,3);
INSERT INTO stanza VALUES('SK194','4','Chrám bol Tvojím predobrazom,<br/>Ty si domom Božím.<br/>Boh len v Tebe Seba zjavil,<br/>plnosť ’by udelil.<br/>Bol si Satanom zničený,<br/>k mŕtvym pochovaný.<br/>Chrám omnoho rozsiahlejší<br/>povstal vo vzkriesení.<br/>',NULL,129615,4);
INSERT INTO stanza VALUES('SK194','5','Mesto zjaví Tvoju plnosť,<br/>je obraz nevesty.<br/>Je Tvojím nárastom plným,<br/>v ňom si usadený.<br/>V Tebe je Boh, svetlo božské,<br/>Ty si mesta lampou.<br/>Boh s Tebou žiari na všetkých,<br/>Slávu Božiu vidno.<br/>',NULL,129616,5);
INSERT INTO stanza VALUES('SK194','6','Stánok svätý, a aj v truhle<br/>zákon uložený,<br/>chrám aj mesto, všetkým si Ty,<br/>Pane milovaný.<br/>Ty si stredom aj obvodom,<br/>Si vo všetkom všetkým!<br/>Ty si Bohom aj človekom,<br/>našim srdciam drahý!<br/>',NULL,129617,6);
INSERT INTO stanza VALUES('SK196','1','Pán sa ako naše všetko<br/>vyobrazil symbolmi.<br/>Pán je teraz skutočnosťou,<br/>symboly tieňom boli.<br/>Uvažujúc nad symbolmi,<br/>keď hľadíme na Neho,<br/>spievame piesne a chvály,<br/>žasneme nad bohatstvom.<br/>',NULL,129618,1);
INSERT INTO stanza VALUES('SK196','2','Pane, Ty si našou Paschou,<br/>Tebou nás Boh obišiel,<br/>Tvojím vykúpením, Tebou<br/>v harmónii s Bohom sme.<br/>Si Božím Baránkom, Pane,<br/>krvou sme vykúpení.<br/>Tvoju krv aplikujeme,<br/>si pokrmom skutočným.<br/>',NULL,129619,2);
INSERT INTO stanza VALUES('SK196','3','Pane, Ty si Chlebom z neba,<br/>chlieb života nekvasený,<br/>zmiešavame sa, jediac Ťa,<br/>od hriechu sme slobodní.<br/>Chlieb, baránok sú symboly,<br/>vravia, že si nám životom.<br/>A tak vychutnávame Ťa,<br/>Pane, pri stole Tvojom.<br/>',NULL,129620,3);
INSERT INTO stanza VALUES('SK196','4','Si nebeskou Mannou, Pane,<br/>ako náš pokrm denný.<br/>Upevňuješ, posilňuješ,<br/>uspokojíš potreby.<br/>Ty si živou skalou, Pane,<br/>ako život vytekáš.<br/>Z tej živej vody pijeme,<br/>uhasený je smäd náš.<br/>',NULL,129621,4);
INSERT INTO stanza VALUES('SK196','5','Pane, Ty si zem Kanaánska –<br/>vysoká, hojná, dobrá,<br/>mliekom aj medom oplývaš,<br/>všade je hojnosť veľká.<br/>My si, Bože, Teba ctíme<br/>z úrody dobrej zeme.<br/>V láske tak prepojení sme,<br/>Božou stavbou budeme.<br/>',NULL,129622,5);
INSERT INTO stanza VALUES('SK199','1','Ty si Skalou nekonečnou,<br/>duchovnou, rozštiepenou,<br/>Teba pijúc ako Ducha,<br/>som s Tebou, Pane, jedno.<br/>Skalou neotrasiteľnou,<br/>na tej sme postavení,<br/>nič nami nemôže otriasť,<br/>v Tebe sme vykúpení.<br/>',NULL,129623,1);
INSERT INTO stanza VALUES('SK199','chorus','Tvoju hodnotu ceníme,<br/>čím si, všetko je pre nás.<br/>Na tejto vzácnej spomienke<br/>zdieľame hojnosť, čo máš.<br/>',NULL,129624,2);
INSERT INTO stanza VALUES('SK199','2','Vyskúšaným Kameňom si,<br/>vzácny Bohu, nám drahý,<br/>istý a dôveryhodný,<br/>úžasnej sily plný.<br/>Živým Kameňom si, Pane,<br/>Vyvolený, nám daný,<br/>energický, veľmi pevný,<br/>náš život nekonečný.<br/>',NULL,129625,3);
INSERT INTO stanza VALUES('SK199','3','Tiež Základným Kameňom si,<br/>Bohom daný, bezpečný.<br/>Týmto pevným základom sme<br/>navždy zabezpečení.<br/>Žiaden iný základ už nik,<br/>nik nemôže položiť,<br/>Ty jediným základom si<br/>pre dnešok aj naveky.<br/>',NULL,129626,4);
INSERT INTO stanza VALUES('SK199','4','Pre duchovnú Božiu stavbu<br/>si Kameňom uholným,<br/>aj židia aj pohania sú<br/>v Tebe, Pane, jednotní.<br/>Pane, Vrchným Kameňom si,<br/>uvedený v milosti,<br/>si naše prikrytie, sláva,<br/>preto sme chvály plní.<br/>',NULL,129627,5);
INSERT INTO stanza VALUES('SK200','1','Si Slnkom spravodlivosti<br/>v krídlach s uzdravením,<br/>žiarou Svojej slávnej tváre<br/>si nám prinášaný.<br/>',NULL,129628,1);
INSERT INTO stanza VALUES('SK200','2','Nežná milosť nášho Boha<br/>Tebou na nás svieti,<br/>žiari na tých, čo sú vo tme,<br/>temná smrť sa stratí.<br/>',NULL,129629,2);
INSERT INTO stanza VALUES('SK200','3','Ty Ránom bez oblakov si,<br/>hneď zrána nám svietiš,<br/>my trávou jemnou na zemi,<br/>čo v lúčoch sa teší.<br/>',NULL,129630,3);
INSERT INTO stanza VALUES('SK200','4','Tvoje svetlo je príjemné,<br/>stále sa zväčšuje,<br/>svieti v nás stále jasnejšie,<br/>kým nie je úplné.<br/>',NULL,129631,4);
INSERT INTO stanza VALUES('SK200','5','Prežiari všetok zármutok,<br/>sťa slnko po daždi<br/>a v Tvojej milosti s láskou<br/>svetlo trvá navždy.<br/>',NULL,129632,5);
INSERT INTO stanza VALUES('SK200','6','Ty si pre tých Rannou hviezdou,<br/>čo skoro vstávajú,<br/>ešte za tmy žiari svetlom<br/>tým, čo Ťa milujú.<br/>',NULL,129633,6);
INSERT INTO stanza VALUES('SK200','7','Pomôž nám milovať svetlo,<br/>všetko vidieť z diaľky,<br/>chceme hľadať Rannú hviezdu<br/>v modlitbe a bdení.<br/>',NULL,129634,7);
INSERT INTO stanza VALUES('SK203','1','Ó, bol si v Otcovom lone<br/>už pred sveta stvorením,<br/>v sláve nášho Otca, Pane,<br/>Synom Jednorodeným.<br/>Rovnakou osobou si bol,<br/>keď Ťa nám Boh Otec dal,<br/>’by celú plnosť Otca si<br/>nám v Duchu ohlasoval.<br/>',NULL,129635,1);
INSERT INTO stanza VALUES('SK203','2','Krížom, vzkriesením si sa stal<br/>Prvorodeným Božím,<br/>životom, čo udeľuješ,<br/>sme rozmnožením Tvojím.<br/>V Tebe znovuzrodení sme,<br/>ó, Boh mnoho synov má.<br/>Rovnakými sme ako Ty,<br/>sme Tvoji mnohí bratia.<br/>',NULL,129636,2);
INSERT INTO stanza VALUES('SK203','3','Ako jediné zrnko si<br/>padol do zeme, umrel,<br/>aby sa smrťou, vzkriesením<br/>v nás Tvoj život znásobil.<br/>My – mnohé zrná vzišli sme,<br/>z prirodzenosti Tvojej.<br/>Zmiešaní ako jeden chlieb<br/>Tvoju plnosť hlásame.<br/>',NULL,129637,3);
INSERT INTO stanza VALUES('SK203','4','Sme Tvojou reprodukciou,<br/>vzácnym Telom, nevestou,<br/>výrazom, Tvojou plnosťou,<br/>’by si mal večný domov.<br/>Sme Tvoje pokračovanie,<br/>prírastok, rozšírenie,<br/>prebytok hojný, plný rast,<br/>s Tebou – Hlavou v jednote.<br/>',NULL,129638,4);
INSERT INTO stanza VALUES('SK204','1','V Tebe, Ježiš, zhromaždení,<br/>strácame všetko iné.<br/>V Tebe, Pane, sme radostní,<br/>povolávaš nás k Sebe!<br/>',NULL,129639,1);
INSERT INTO stanza VALUES('SK204','2','Sme milovaní nesmierne,<br/>Teba Otec miluje.<br/>Pán Ježiš, oceňujeme,<br/>myseľ Otca o Tebe.<br/>',NULL,129640,2);
INSERT INTO stanza VALUES('SK204','3','Jeho radosť, potešenie,<br/>Jeho záľuba v Tebe,<br/>len Ty vieš oceniť, Pane,<br/>čo našiel Otec v Tebe.<br/>',NULL,129641,3);
INSERT INTO stanza VALUES('SK204','4','Otec Ťa veľmi miluje,<br/>milovaným Ťa volá.<br/>No pre nás Ťa neušetril,<br/>zomrel si, ja život mám.<br/>',NULL,129642,4);
INSERT INTO stanza VALUES('SK204','5','Keď vidíme, kým si, Pane,<br/>spievame, sme v úžase!<br/>Najsladšiu hudbu Otcovi<br/>Tvoje meno prinesie.<br/>',NULL,129643,5);
INSERT INTO stanza VALUES('SK204','6','Noty potešenia, piesne,<br/>hymny chvál nekonečných,<br/>žalmy slávy, blaho rastie,<br/>do dňa nekonečných dní.<br/>',NULL,129644,6);
INSERT INTO stanza VALUES('SK206','1','Ó, Kristus je prameňom,<br/>je studňou života.<br/>Okúsil som živý tok,<br/>od smútku chráni ma.<br/>Milosrdenstvo Jeho<br/>je ako oceán.<br/>Stačí nám milosť Jeho,<br/>On ju naplánoval.<br/>',NULL,129645,1);
INSERT INTO stanza VALUES('SK206','2','Ja som Milovaného<br/>a Milovaný môj.<br/>Vo Svoj dom, plný vína<br/>privádza hriešnikov.<br/>Stojím na diele Jeho,<br/>iného nič nemám,<br/>som v prítomnosti Jeho,<br/>drží ma v ruke Pán.<br/>',NULL,129646,2);
INSERT INTO stanza VALUES('SK206','3','Na odev nehľadím ja,<br/>ale na Ženícha,<br/>na slávu nehľadím ja,<br/>no na milosť Kráľa.<br/>Nie korunu, čo dáva,<br/>no zjazvené ruky.<br/>Baránok, sláva moja,<br/>navždy a naveky.<br/>',NULL,129647,3);
INSERT INTO stanza VALUES('SK215','1','Pane, vieme, že si s nami<br/>tu pri stole prítomný,<br/>sme tu s Tebou usadení<br/>s Tvojou vlajkou nad nami.<br/>Vzácnou chvíľou tu pri stole<br/>je všetok strach zahnaný,<br/>odpočívame tu s Tebou,<br/>len Tebou zaujatí.<br/>',NULL,129648,1);
INSERT INTO stanza VALUES('SK215','2','Radujúc sa, že si blízky,<br/>Tvojím Duchom vedení.<br/>My spomíname Ťa s úctou,<br/>krvou sme očistení.<br/>Teba prijímame, Pane,<br/>a spomíname nežne,<br/>Tvoje Telo prelomené,<br/>krv preliatu na dreve.<br/>',NULL,129649,2);
INSERT INTO stanza VALUES('SK215','3','Radosť máme, že vidíme<br/>Teba v týchto znameniach,<br/>chlieb a víno požehnania<br/>posilnia a potešia!<br/>Pane, hľa, sme zhromaždení,<br/>jednotní v Tebe – Hlave,<br/>takto berieme ten kalich,<br/>a rozdávame ten chlieb.<br/>',NULL,129650,3);
INSERT INTO stanza VALUES('SK215','4','Pane, vieme, že si s nami,<br/>tam, kde sa stretávame,<br/>pravdivý je tento prísľub,<br/>keď Ťa vychutnávame.<br/>Avšak tým, čo čakajú Ťa,<br/>je tu prísľub vzácnejší,<br/>že budeme spolu s Tebou,<br/>tam, kde si Ty, naveky.<br/>',NULL,129651,4);
INSERT INTO stanza VALUES('SK220','1','Nad znameniami žasneme,<br/>hľadiac na stôl, Pane,<br/>chlieb a kalich vystavené<br/>ako znaky Božie.<br/>',NULL,129652,1);
INSERT INTO stanza VALUES('SK220','2','Chlieb na stole zobrazuje<br/>pravý Chlieb života,<br/>Tvojou smrťou je nám daný,<br/>môžeme Ťa zdieľať.<br/>',NULL,129653,2);
INSERT INTO stanza VALUES('SK220','3','Božský kalich je náš podiel<br/>v krvi Ježišovej,<br/>čo je z Boha, získavame<br/>tým, že ho pijeme.<br/>',NULL,129654,3);
INSERT INTO stanza VALUES('SK220','4','Teba, Chlieb života, jeme,<br/>chlieb si podávame,<br/>v láske Ťa pripomíname,<br/>Tebou sa sýtime.<br/>',NULL,129655,4);
INSERT INTO stanza VALUES('SK220','5','Tešíme sa požehnaniam,<br/>z kalicha pijeme,<br/>s radosťou Ťa spomíname,<br/>až kým si nás vezmeš.<br/>',NULL,129656,5);
INSERT INTO stanza VALUES('SK220','6','Jediac chlieb a pijúc kalich<br/>Tvoju smrť hlásame,<br/>si nám životom a všetkým,<br/>svedčíme spoločne.<br/>',NULL,129657,6);
INSERT INTO stanza VALUES('SK220','7','Čakáme slávnu hodinu,<br/>v ktorej sa úplne<br/>budeme len z Teba tešiť,<br/>uctievať Ťa večne.<br/>',NULL,129658,7);
INSERT INTO stanza VALUES('SK221','1','Pán Ježiš, za stôl vďačíme,<br/>chlieb a víno sú na ňom,<br/>z Teba sa pri ňom tešíme,<br/>Sám si lásky hostinou.<br/>Jeme chlieb, znak Tvojho tela,<br/>ó, vydal si ho za nás,<br/>pijeme tu víno, symbol<br/>preliatej krvi za nás.<br/>',NULL,129659,1);
INSERT INTO stanza VALUES('SK221','chorus','Máme tu svätý stôl,<br/>hľa, sväté symboly.<br/>Význam týchto symbolov je<br/>veľmi bohatý!<br/>',NULL,129660,2);
INSERT INTO stanza VALUES('SK221','2','Ó, smrťou vykupujúcou<br/>nám život udeľuješ.<br/>Dal si nám Seba samého,<br/>máme na Tebe podiel.<br/>Účasťou na chlebe, víne<br/>Tvoju smrť zvestujeme.<br/>Jeme chlieb, pijeme víno,<br/>s láskou Ťa spomíname.<br/>',NULL,129661,3);
INSERT INTO stanza VALUES('SK221','3','Ó, chlebom, čo znázorňuje<br/>Tvoje telo tajomné,<br/>môžeme mať spoločenstvo,<br/>v jednom zväzku vzájomne.<br/>Vínom, čo mu dnes žehnáme,<br/>kalichom požehnania<br/>máme účasť Tvojej krvi,<br/>s tými, čo vieru vlastnia.<br/>',NULL,129662,4);
INSERT INTO stanza VALUES('SK221','4','Si naším večným podielom,<br/>príchuť tu zakúšame,<br/>kráľovstvo Tvoje čakáme,<br/>príchod urýchľujeme.<br/>V kráľovstve Svojom, až prídeš<br/>so skupinou víťazov,<br/>budeš nám novou hostinou,<br/>budeme Ti nevestou.<br/>',NULL,129663,5);
INSERT INTO stanza VALUES('SK222','1','Vďaka, Pane, za tento chlieb,<br/>za ten božský symbol.<br/>V ňom môžeme zrieť tajomstvá<br/>zámeru Božieho.<br/>',NULL,129664,1);
INSERT INTO stanza VALUES('SK222','2','Znázorňuje Tvoje telo,<br/>bolo za nás dané.<br/>’By sme mali božský život<br/>a účasť na Tebe.<br/>',NULL,129665,2);
INSERT INTO stanza VALUES('SK222','3','Prelomený si bol za nás,<br/>’by si nám odovzdal<br/>Seba ako život a tak<br/>Svoj náprotivok mal.<br/>',NULL,129666,3);
INSERT INTO stanza VALUES('SK222','4','Chlieb zároveň ukazuje<br/>na mystické telo,<br/>jeho živými údmi sme,<br/>zjednotení s Tebou.<br/>',NULL,129667,4);
INSERT INTO stanza VALUES('SK222','5','Hoci je nás mnoho zrniek,<br/>sme len jedným chlebom,<br/>v jednote Ťa spomíname,<br/>nasýtení Tebou.<br/>',NULL,129668,5);
INSERT INTO stanza VALUES('SK222','6','Ak máme účasť na chlebe,<br/>si uspokojený,<br/>spoločenstvom svätých, Pane,<br/>si dosvedčovaný.<br/>',NULL,129669,6);
INSERT INTO stanza VALUES('SK223','1','Lásky stôl rozprestretý<br/>spolu s chlebom, kalichom.<br/>Účasťou na symboloch<br/>sýtení sme bohato.<br/>Ó, vďačíme za kalich,<br/>za kalich požehnania,<br/>kalich spásy úplnej,<br/>v ňom je všetko to, čo máš.<br/>',NULL,129670,1);
INSERT INTO stanza VALUES('SK223','2','Vďaka preliatej krvi,<br/>hriechy mám odpustené<br/>závetom navždy platným,<br/>mám Tvoje požehnanie.<br/>Vypil si kalich hnevu<br/>a okúsil smrť za nás,<br/>kalichom požehnania<br/>získal si podiel pre nás.<br/>',NULL,129671,2);
INSERT INTO stanza VALUES('SK223','3','Týmto podielom je Boh,<br/>pádom sme Ho stratili,<br/>avšak vyliatou krvou<br/>Boh sa stal pre nás všetkým.<br/>V tejto čiastke je všetko –<br/>ó, vykúpenie isté,<br/>plán Boží, život, pokoj<br/>ten podiel obsahuje.<br/>',NULL,129672,3);
INSERT INTO stanza VALUES('SK223','4','Je to náš večný podiel,<br/>náš kalich, čo preteká,<br/>máme príchuť nebeskú<br/>v tomto kalichu Boha.<br/>V láske kalich pijeme,<br/>Teba tak spomíname,<br/>v duchu vychutnávame<br/>námahu kalvárie.<br/>',NULL,129673,4);
INSERT INTO stanza VALUES('SK224','1','Spolu zdieľame kalich,<br/>chváliť neprestávame,<br/>hodnotu Tvojej krvi<br/>doceniť nemôžeme.<br/>Ó, cenná je Tvoja krv!<br/>Rieši všetky problémy,<br/>v Tvojej účinnej krvi,<br/>sa strácajú ťažkosti.<br/>',NULL,129674,1);
INSERT INTO stanza VALUES('SK224','2','Dal si nám novú zmluvu<br/>Svojou predrahou krvou,<br/>táto lepšia zmluva sa<br/>stala pevným základom.<br/>Sme vykúpení Bohom,<br/>nie zlatom ani striebrom,<br/>ale prevzácnou krvou,<br/>ó, Pane, láskou Tvojou.<br/>',NULL,129675,2);
INSERT INTO stanza VALUES('SK224','3','Na odpustenie hriechov<br/>si očistnú krv vylial.<br/>Uspokojila Boha,<br/>všetko, čo požadoval.<br/>Od hriechov som obmytý,<br/>v mocnej, očistnej krvi,<br/>s očisteným svedomím<br/>živému Bohu slúžim.<br/>',NULL,129676,3);
INSERT INTO stanza VALUES('SK224','4','Oddeľujúcou krvou<br/>sme boli posvätení,<br/>ochraňujúcou krvou,<br/>svedčíme o svätosti.<br/>Ó, zmierujúcou krvou<br/>sme ospravedlnení,<br/>vykupujúcou krvou<br/>je Boh uspokojený.<br/>',NULL,129677,4);
INSERT INTO stanza VALUES('SK224','5','Tvojou preliatou krvou<br/>máme s Bohom zmierenie,<br/>preto Ho dnes v pokoji<br/>kontaktovať môžeme.<br/>Účasťou v Tvojej krvi<br/>máme Tvoj život večný.<br/>V tvojej krvi, živote,<br/>sme si odpočinuli.<br/>',NULL,129678,5);
INSERT INTO stanza VALUES('SK224','6','Tvoja krv je v nebesiach,<br/>prehovára tam za nás,<br/>jej moc vždy odstraňuje,<br/>Satanove žihadlá.<br/>Tvojou víťaznou krvou<br/>nepriateľa zničíme,<br/>nad žalobníkom bratov<br/>zvíťazíme spoločne.<br/>',NULL,129679,6);
INSERT INTO stanza VALUES('SK224','7','Krv je pre spoločenstvo<br/>so všetkými svätými,<br/>pod jej plným pokrytím<br/>neochabne duch nikdy.<br/>Hodnotu Tvojej krvi<br/>nemôžeme opísať,<br/>potrebujeme večnosť<br/>o jej cene rozprávať.<br/>',NULL,129680,7);
INSERT INTO stanza VALUES('SK233','1','Ó, čo za zázrak, Pane môj,<br/>že si vo mne a ja v Tebe.<br/>Že my sme skutočne jedno,<br/>aké tajomstvo nádherné!<br/>',NULL,129681,1);
INSERT INTO stanza VALUES('SK233','2','Svoje telo si dal za mňa,<br/>preto na Tebe podiel mám.<br/>Svoju krv si vylial za mňa,<br/>slobodný od hriechov som tak.<br/>',NULL,129682,2);
INSERT INTO stanza VALUES('SK233','3','Vo vzkriesení si sa zmenil,<br/>aby si ako Duch prišiel,<br/>aby si ma tak naplnil<br/>a dal mi bohatstvá Svoje.<br/>',NULL,129683,3);
INSERT INTO stanza VALUES('SK233','4','Na symboly keď hľadíme,<br/>tak Teba znovu vidíme.<br/>Vďační sme za Tvoje prianie,<br/>za to všetko, čím si prešiel.<br/>',NULL,129684,4);
INSERT INTO stanza VALUES('SK233','5','Jeme chlieb, víno pijeme,<br/>prežívame sladkosť Tvoju,<br/>my Ťa v duchu prijímame,<br/>sme Tebou sýtení v duchu.<br/>',NULL,129685,5);
INSERT INTO stanza VALUES('SK233','6','Túžime Ťa viac jesť a piť,<br/>takto Ťa prijímať v duchu,<br/>celkom kým nás nenaplníš,<br/>pravú Ti vzdáme spomienku.<br/>',NULL,129686,6);
INSERT INTO stanza VALUES('SK242','1','Boží Duch sa teraz stal<br/>tým Duchom Ježišovým.<br/>Bohočlovek zomrel a vstal,<br/>vstúpil do Svojej slávy.<br/>',NULL,129687,1);
INSERT INTO stanza VALUES('SK242','2','Od Neho potom na nás<br/>zostúpil Duch Ježiša,<br/>aby Jeho skutočnosť<br/>bola skúsenosť naša.<br/>',NULL,129688,2);
INSERT INTO stanza VALUES('SK242','3','Duch Ježiša v Sebe má<br/>zložky ľudské aj božské.<br/>Veď v Ňom sa s Božou slávou,<br/>spojilo žitie ľudské.<br/>',NULL,129689,3);
INSERT INTO stanza VALUES('SK242','4','Utrpenia života,<br/>účinnosť Jeho smrti,<br/>vzkriesenie a kráľovstvo<br/>sú v Duchu obsiahnuté.<br/>',NULL,129690,4);
INSERT INTO stanza VALUES('SK242','5','Ten Duch teraz v nás koná<br/>skrz Jeho pomazanie,<br/>so všetkými zložkami,<br/>Krista bohatstvá máme.<br/>',NULL,129691,5);
INSERT INTO stanza VALUES('SK242','6','Duch Ježiša pôsobí,<br/>On bohato koná v nás,<br/>vo veľkých aj tých malých,<br/>’by bol Boh všetkým pre nás.<br/>',NULL,129692,6);
INSERT INTO stanza VALUES('SK243','1','Boží Duch je Duchom Krista,<br/>On je Duchom skutočnosti.<br/>Spolu s Kristom žije vo mne,<br/>aby bol pre mňa skutočný.<br/>',NULL,129693,1);
INSERT INTO stanza VALUES('SK243','2','Kristus Boha stelesňuje,<br/>vyjadruje život božský.<br/>Duch nám Krista odhaľuje<br/>v živote, čo je vznešený.<br/>',NULL,129694,2);
INSERT INTO stanza VALUES('SK243','3','Celá plnosť Boha Otca<br/>je v Kristu, Synu telesne.<br/>Všetko Synovo bohatstvo<br/>je Duchom, v Ňom je skutočné.<br/>',NULL,129695,3);
INSERT INTO stanza VALUES('SK243','4','Otec prebýva v Synovi,<br/>teraz je tento Syn Duchom.<br/>Otec a Syn sú spojení,<br/>ten Duch je jedno so Synom.<br/>',NULL,129696,4);
INSERT INTO stanza VALUES('SK243','5','Keď nás ten Duch posilňuje<br/>a v nás si Kristus dom činí,<br/>plnosť Otca s láskou Jeho<br/>nám vnútornosti naplní.<br/>',NULL,129697,5);
INSERT INTO stanza VALUES('SK243','6','V Kristovi máme aj Otca,<br/>je tým, čo potrebujeme.<br/>V Duchu zakúšame Krista,<br/>život a všetko skutočne.<br/>',NULL,129698,6);
INSERT INTO stanza VALUES('SK243','7','Svojou božskou skutočnosťou,<br/>Duchom napĺňaj nás, Pane.<br/>Nech sme všetci Teba plní,<br/>bohatstvo Tvoje hlásame.<br/>',NULL,129699,7);
INSERT INTO stanza VALUES('SK244','1','Svätý Duch je pre nás teraz<br/>Duchom božského života.<br/>Oživuje, dáva život,<br/>nech sme vhodnými pre Boha.<br/>',NULL,129700,1);
INSERT INTO stanza VALUES('SK244','2','Dodáva nám prúd života,<br/>uháša smäd vodou živou.<br/>Sýti moje hladné srdce,<br/>dáva Krista – božský život.<br/>',NULL,129701,2);
INSERT INTO stanza VALUES('SK244','3','On dáva svetlo života,<br/>akúkoľvek tmu vyženie,<br/>dáva Krista – božské svetlo,<br/>spôsobí, že deň z noci je.<br/>',NULL,129702,3);
INSERT INTO stanza VALUES('SK244','4','Nám vnútorného človeka<br/>mocou života posilní,<br/>dáva Krista – božskú silu,<br/>hýbe sa v nás pre plán Boží.<br/>',NULL,129703,4);
INSERT INTO stanza VALUES('SK244','5','Zákonom Ducha života<br/>nás zákona hriechu zbaví,<br/>Jeho božská prirodzenosť<br/>nás vnútri stále usmerní.<br/>',NULL,129704,5);
INSERT INTO stanza VALUES('SK244','6','Ten Duch božského života<br/>cez nás ovocie dá hojné,<br/>Božie vlastnosti vyjadrí<br/>a Krista v živote nesie.<br/>',NULL,129705,6);
INSERT INTO stanza VALUES('SK244','7','Duch stále život udelí,<br/>božským životom ma mení,<br/>vnútornosti obnovuje,<br/>Kristus sa vo mne zobrazí.<br/>',NULL,129706,7);
INSERT INTO stanza VALUES('SK244','8','Ó Pane, naplň ma Duchom,<br/>Duchom božského života,<br/>a dôkladne ma presycuj,<br/>aby som bol plný Teba.<br/>',NULL,129707,8);
INSERT INTO stanza VALUES('SK250','1','Dávaj, studňa, vodu,<br/>dôkladne kop, Pane,<br/>zábrany odstraňuj,<br/>nech cezo mňa plynie.<br/>',NULL,129708,1);
INSERT INTO stanza VALUES('SK250','2','Pán – skala udretá<br/>vodu živú dáva,<br/>niečo v mojom vnútri<br/>prúdeniu prekáža.<br/>',NULL,129709,2);
INSERT INTO stanza VALUES('SK250','3','Modlitbou vykopem<br/>nečistotu plne,<br/>tým uvoľním Ducha<br/>prúdiť bude voľne.<br/>',NULL,129710,3);
INSERT INTO stanza VALUES('SK250','4','Ó, nie je potrebné<br/>udrieť skalu znova,<br/>avšak nevyhnutne<br/>treba začať kopať.<br/>',NULL,129711,4);
INSERT INTO stanza VALUES('SK250','5','Nutne potrebujem,<br/>’by ma Duch naplnil,<br/>ako živá voda<br/>z môjho vnútra prúdil.<br/>',NULL,129712,5);
INSERT INTO stanza VALUES('SK250','6','Kým už nič nebráni,<br/>dovtedy chcem kopať,<br/>až vytryskne zo mňa<br/>posolstvo života.<br/>',NULL,129713,6);
INSERT INTO stanza VALUES('SK250','7','Dávaj, studňa, vodu,<br/>dôkladne kop, Pane,<br/>zábrany odstraňuj,<br/>nech cezo mňa plynie.<br/>',NULL,129714,7);
INSERT INTO stanza VALUES('SK251','1','Rieky plné života<br/>od trónu vytekajú,<br/>požehnaním naplnené,<br/>z Ježiša vychádzajú.<br/>',NULL,129715,1);
INSERT INTO stanza VALUES('SK251','chorus','Voľné rieky života<br/>prúdia vodou živou,<br/>tečú zo Spasiteľa,<br/>nech pretečú dnes aj mnou.<br/>',NULL,129716,2);
INSERT INTO stanza VALUES('SK251','2','Hľa zásoba prehojná,<br/>pristúp sem, ak si smädný.<br/>Voda ako krištáľ číra,<br/>príď, kupuj bez peňazí.<br/>',NULL,129717,3);
INSERT INTO stanza VALUES('SK251','3','Očisti, Spasiteľ môj,<br/>učiň ma užitočným,<br/>vyprázdni, naplň, pretekaj,<br/>uč ma byť Ti poslušným.<br/>',NULL,129718,4);
INSERT INTO stanza VALUES('SK251','4','Jedine vtedy môžu<br/>mnou tie rieky pretekať,<br/>iba takto iní môžu<br/>plnosť Ježiša poznať.<br/>',NULL,129719,5);
INSERT INTO stanza VALUES('SK251','5','Vzdávam sa Ježišovi,<br/>kladiem mu všetko k nohám,<br/>chcem Mu vždy ochotne slúžiť<br/>všade, so všetkým čo mám.<br/>',NULL,129720,6);
INSERT INTO stanza VALUES('SK255','1','Pane, dýchni na mňa Ducha,<br/>uč ma Teba vdychovať,<br/>sebecký a hriešny život<br/>zo seba chcem vylievať.<br/>',NULL,129721,1);
INSERT INTO stanza VALUES('SK255','chorus','Von svoj smútok vydychujem,<br/>vydychujem hriech<br/>a vdychujem a vdychujem,<br/>plnosť Tvoju len.<br/>',NULL,129722,2);
INSERT INTO stanza VALUES('SK255','2','Vydychujem von svoj život,<br/>naplniť sa Tvojím chcem.<br/>Ísť nechám silu aj slabosť,<br/>Tvoj život božský vdýchnem.<br/>',NULL,129723,3);
INSERT INTO stanza VALUES('SK255','3','Svoju hriešnosť vydychujem,<br/>niesol si všetko za mňa,<br/>a Tvoju plnosť vdychujem,<br/>v Tebe život nachádzam.<br/>',NULL,129724,4);
INSERT INTO stanza VALUES('SK255','4','Von svoj smútok vydychujem,<br/>si nežný a jemný tiež,<br/>a Tvoju radosť vdychujem,<br/>pokoj, odpočinutie.<br/>',NULL,129725,5);
INSERT INTO stanza VALUES('SK255','5','Svoju nemoc vydychujem,<br/>tiež si ju za mňa niesol,<br/>a uzdravenie vdychujem,<br/>zasľúbené a nové.<br/>',NULL,129726,6);
INSERT INTO stanza VALUES('SK255','6','Svoje túžby vydychujem,<br/>Ty si ten, kto počuje,<br/>a odpovede vdychujem,<br/>každý strach utišuješ.<br/>',NULL,129727,7);
INSERT INTO stanza VALUES('SK255','7','Dýcham stále v každej chvíli,<br/>všetok život z Teba mám.<br/>Každým dychom Tebou žijem,<br/>Tvojho Ducha prijímam.<br/>',NULL,129728,8);
INSERT INTO stanza VALUES('SK266','1','Vo mne je Božie pomazanie<br/>a všetkému ma učí,<br/>aby som žil v Pánovi, ma vedie,<br/>a v Jeho prítomnosti.<br/>',NULL,129729,1);
INSERT INTO stanza VALUES('SK266','chorus','V mojom duchu je pomazanie,<br/>ono žije vo mne,<br/>všetkému ma učí.<br/>V mojom duchu je pomazanie,<br/>ono vždy všetkému učí.<br/>',NULL,129730,2);
INSERT INTO stanza VALUES('SK266','2','Pohyb Ducha je pomazanie,<br/>ten olej najrýdzejší.<br/>Základom je krvou pokropenie,<br/>takto stále vydrží.<br/>',NULL,129731,3);
INSERT INTO stanza VALUES('SK266','3','Božou podstatou pomazáva,<br/>’by som Boha poznával,<br/>Jeho božský element, aby ma<br/>plnosťou presycoval.<br/>',NULL,129732,4);
INSERT INTO stanza VALUES('SK266','4','Týmto vnútorným pomazaním,<br/>spoločenstvo mať môžem,<br/>v Bohu, svetle pravdy, denne chodím,<br/>v láske milosti žijem.<br/>',NULL,129733,5);
INSERT INTO stanza VALUES('SK279','1','Prv krv máme, následne masť,<br/>krv čistí, masť pomaže.<br/>Ak neprejdeme Golgotou,<br/>tak neprídu Letnice.<br/>Pokiaľ nás krv neočistí,<br/>nespoznáme moc Ducha,<br/>ak chceme pre Krista svedčiť,<br/>„ja“ musíme križovať.<br/>',NULL,129734,1);
INSERT INTO stanza VALUES('SK279','chorus','Nech je krížom zmárnený<br/>život duše, sa modlím.<br/>Nech plnú cenu platím,<br/>’by som bol pomazaný.<br/>',NULL,129735,2);
INSERT INTO stanza VALUES('SK279','2','Prv musí byť Pán udretý,<br/>’by živá voda tiekla.<br/>Bez smrti ’by plnosť Ducha<br/>v nás prebývať nemohla.<br/>Ak umrieme spolu s Kristom<br/>a stratíme všetko preň,<br/>zaodeje Svojou mocou<br/>a cez nás si získa svet.<br/>',NULL,129736,3);
INSERT INTO stanza VALUES('SK279','3','Prv oltár a potom oheň,<br/>nič bez strát nezískame,<br/>ak sme si niečo nechali,<br/>k trónu nedospejeme.<br/>Ak sa ochotne vydáme,<br/>budeme Mu poslušní,<br/>On sa nám taktiež odovzdá<br/>a cez nás sa prejaví.<br/>',NULL,129737,4);
INSERT INTO stanza VALUES('SK279','4','Prv musíme nádoby mať<br/>na olej pripravené,<br/>najprv nádrže vykopať,<br/>aby mohli byť plné.<br/>Prv musíme prejsť cez Jordán,<br/>až tak byť pomazaní,<br/>do smrti prv pokrstení,<br/>Duch zostúpi len vtedy.<br/>',NULL,129738,5);
INSERT INTO stanza VALUES('SK279','5','Keď vidíme žatvu zrelú,<br/>polia čo dozrievali,<br/>vieme, že pochádza zo zŕn,<br/>čo v zemi zahynuli.<br/>Ovocie života priniesť<br/>bez smrti je nemožné.<br/>Ak s Ním nie sme pochovaní,<br/>Duch na nás viať nebude.<br/>',NULL,129739,6);
INSERT INTO stanza VALUES('SK279','6','Preto sa, môj Pane, modlím:<br/>„Pomôž úzkou cestou ísť,<br/>vezmi pýchu a učiň ma<br/>poslušným, podriadeným.“<br/>Nemodlím sa za väčšiu moc,<br/>za hlbšiu smrť sa modlím,<br/>význam kríža vpracuj do mňa,<br/>o to Ťa, Pane, prosím.<br/>',NULL,129740,7);
INSERT INTO stanza VALUES('SK280','1','Očisti, Pane, krvou,<br/>od hriechov ma obmy,<br/>aby som Duchom Svätým<br/>mohol byť natretý.<br/>Chabo Ti slúžim, Pane,<br/>vo všetkom, vždy zlyhám,<br/>chcem žiť iba pre Teba,<br/>plnosť Ducha hľadám.<br/>',NULL,129741,1);
INSERT INTO stanza VALUES('SK280','chorus','Vysloboď ma zo seba,<br/>z mojej mizérie,<br/>nech mám odteraz navždy<br/>Tvoje naplnenie.<br/>',NULL,129742,2);
INSERT INTO stanza VALUES('SK280','2','Také suché srdce mám,<br/>vrúcne si Ťa želám,<br/>byť Duchom naplnený,<br/>nech Tebou pretekám.<br/>Si rozštiepenou skalou,<br/>v Tebe som ukrytý,<br/>vylievaj vodu živú,<br/>to ma uspokojí.<br/>',NULL,129743,3);
INSERT INTO stanza VALUES('SK280','3','Moje srdce chladné je,<br/>poslúchať pomalé,<br/>preto ho naplň Duchom,<br/>nech nie je vzbúrené.<br/>Sám seba dám na oltár,<br/>na ňom sa uložím,<br/>keď zostúpi Tvoj plameň,<br/>nech všetko pohltí.<br/>',NULL,129744,4);
INSERT INTO stanza VALUES('SK280','4','Ó, nech Tvoj kríž sa vo mne<br/>prehlbuje, planie,<br/>na Svoj popol ma premeň,<br/>rasti vo mne, Pane.<br/>Nech ma Tvoj Duch napĺňa<br/>viacej ako predtým<br/>a Tvojej vody živej<br/>nech stále som plný.<br/>',NULL,129745,5);
INSERT INTO stanza VALUES('SK308','1','Istotu mám, že Ježiš je môj.<br/>Ó, aká to predzvesť slávy Božej!<br/>Som dedič spásy, vykúpený,<br/>z Ducha zrodený, očistený.<br/>',NULL,129746,1);
INSERT INTO stanza VALUES('SK308','chorus','To je môj príbeh, moja pieseň,<br/>Ježiša slávim po celý deň.<br/>To je môj príbeh, moja pieseň,<br/>Ježiša slávim po celý deň.<br/>',NULL,129747,2);
INSERT INTO stanza VALUES('SK308','2','Je radosťou Mu patriť celkom,<br/>vytrhnutý byť ja túžim Pánom,<br/>z neba anjeli zostupujú,<br/>echo milosrdenstva nesú.<br/>',NULL,129748,3);
INSERT INTO stanza VALUES('SK308','3','Patriť Mu celkom môj pokoj je,<br/>v Ňom som šťastný, mám tiež požehnanie.<br/>Naplnený Ním, k Nemu vzhliadam,<br/>stratený v Ňom, bdiem, očakávam.<br/>',NULL,129749,4);
INSERT INTO stanza VALUES('SK310','1','Kedysi som bol v okovách hriechu,<br/>otrok reťazou poviazaný.<br/>Avšak prijal som slobodu slávnu,<br/>Pán sa porátal s okovami.<br/>',NULL,129750,1);
INSERT INTO stanza VALUES('SK310','chorus','Sloboda slávna, úžasná, vzácna,<br/>v okovách hriechu nenariekam!<br/>Ó, Ježiša, vysloboditeľa<br/>slávneho, dnes aj naveky mám.<br/>',NULL,129751,2);
INSERT INTO stanza VALUES('SK310','2','Sloboda od všetkej telesnosti,<br/>závisti, nenávisti, sporov,<br/>sloboda od ctižiadostivosti,<br/>slobodu mám od nedostatkov.<br/>',NULL,129752,3);
INSERT INTO stanza VALUES('SK310','3','Sloboda od pýchy, pochabostí,<br/>od lásky a ligotu zlata,<br/>sloboda od zloby, hnevlivosti,<br/>sloboda slávna, nevýslovná.<br/>',NULL,129753,4);
INSERT INTO stanza VALUES('SK310','4','Sloboda od strachu s jeho trýzňou,<br/>od bôľu zo starostlivosti,<br/>sloboda, som vykúpený Kristom,<br/>On prelomil moje okovy.<br/>',NULL,129754,5);
INSERT INTO stanza VALUES('SK312','1','Milosť! Zvuk pôvabný,<br/>ušiam harmónia.<br/>Nebesia ju odrážajú<br/>a vníma zem celá.<br/>',NULL,129755,1);
INSERT INTO stanza VALUES('SK312','chorus','Milosť prehojná<br/>je dostatočná!<br/>Milosť je Kristus vo mne,<br/>vyčerpať sa nedá.<br/>',NULL,129756,2);
INSERT INTO stanza VALUES('SK312','2','Do knihy života<br/>dala moje meno.<br/>K Baránkovi ma priviedla,<br/>môj smútok odniesol.<br/>',NULL,129757,3);
INSERT INTO stanza VALUES('SK312','3','Milosť vyučuje<br/>ísť pútnickou cestou.<br/>Zatiaľ čo s Bohom putujem,<br/>je mojou zásobou.<br/>',NULL,129758,4);
INSERT INTO stanza VALUES('SK312','4','Milosť vyučuje<br/>modliť sa, až plačem.<br/>Zachovala ma až dodnes,<br/>inam ísť nemôžem.<br/>',NULL,129759,5);
INSERT INTO stanza VALUES('SK312','5','Je diela korunou<br/>navždy a naveky.<br/>Je v láske, vrchnom kameni,<br/>milosť chváliť musím.<br/>',NULL,129760,6);
INSERT INTO stanza VALUES('SK312','6','Nech milosť naplní<br/>srdce božskou silou.<br/>Nech túžim po Tebe mocne,<br/>moje dni Tvoje sú.<br/>',NULL,129761,7);
INSERT INTO stanza VALUES('SK322','1','Mnoho rokov som márne prameň hľadal,<br/>čo nikdy nevysychá.<br/>Uspokojenie v tom, čo by svet dával,<br/>na zemi sa nájsť nedá.<br/>',NULL,129762,1);
INSERT INTO stanza VALUES('SK322','chorus','Pijem Prameň, čo nikdy nevysychá,<br/>Prameň života teraz pijem ja.<br/>Radosť, potešenie je v Ňom v hojnej miere,<br/>teraz pijem z Prameňa života.<br/>',NULL,129763,2);
INSERT INTO stanza VALUES('SK322','2','Skrze vyschnutú zem hriechu nechcem ísť,<br/>našiel som Prameň živý.<br/>Teraz preteká môj kalich radosti,<br/>Ježiš je môj Pán živý.<br/>',NULL,129764,3);
INSERT INTO stanza VALUES('SK322','3','Tu je stále sladké uspokojenie,<br/>pokoj, odpočinutie,<br/>každú sekundu tu mám utešenie,<br/>srdce má požehnanie.<br/>',NULL,129765,4);
INSERT INTO stanza VALUES('SK322','4','Tu nachádzam Prameň zásobovania,<br/>ktorý nikdy neskončí,<br/>uzdravujúcu vodu mi vždy dáva,<br/>dušu stále občerství.<br/>',NULL,129766,5);
INSERT INTO stanza VALUES('SK348','1','Keďže ma hriechu zbavil Pán,<br/>radosť tak stále z Neho mám,<br/>a vo všetkých starostiach sám,<br/>možnosť poznávať Pána mám.<br/>',NULL,129767,1);
INSERT INTO stanza VALUES('SK348','chorus','Ó, aleluja, áno, mám<br/>radosť, keď Pána vychutnám!<br/>Kdekoľvek, súš či oceán,<br/>kde je môj Pán, tam radosť mám.<br/>',NULL,129768,2);
INSERT INTO stanza VALUES('SK348','2','Život predtým bol horkosťou,<br/>s Ježišom je však sladkosťou.<br/>Radosť veľká v mojom srdci<br/>a potrvá až na veky.<br/>',NULL,129769,3);
INSERT INTO stanza VALUES('SK348','3','Nezáleží, kde bývame,<br/>či zámok máme a či nie.<br/>Na vŕšku hôr, aj v údolí,<br/>kde je môj Pán, srdce horí.<br/>',NULL,129770,4);
INSERT INTO stanza VALUES('SK350','1','Sám Boh je môj cieľ, radosť, pokoj – nie,<br/>nie požehnanie, ale Sám Boh môj.<br/>Sám On ma k tomuto cieľu vedie,<br/>akoukoľvek cestou a tiež cenou.<br/>',NULL,129771,1);
INSERT INTO stanza VALUES('SK350','2','Viera sa k tomuto cieľu ženie,<br/>láska verí, že Pán ju tam vedie.<br/>Pán dušu na ceste upevňuje,<br/>kým na modlitbu Pán neodpovie.<br/>',NULL,129772,2);
INSERT INTO stanza VALUES('SK350','3','Hoc táto cesta je niekedy v tme,<br/>aj keď je často cena priveľká,<br/>úzka je cesta, čo k Nemu vedie,<br/>On vie, ako sa dostať do cieľa.<br/>',NULL,129773,3);
INSERT INTO stanza VALUES('SK350','4','Viem, že Mu nemôžem povedať nie.<br/>Jedno robím, že sa k Nemu ženiem.<br/>Boh mojou slávou zo dňa na deň je,<br/>moja veľká odmena v sláve je.<br/>',NULL,129774,4);
INSERT INTO stanza VALUES('SK365','1','Pán Ježiš, si vo mne,<br/>žiješ vo mne navždy,<br/>vidieť daj mi,<br/>že Tvoj život s mojím<br/>je spojený.<br/>',NULL,129775,1);
INSERT INTO stanza VALUES('SK365','2','Tvoj život vo mne je,<br/>a preto zmýšľať chcem,<br/>hovoriť len<br/>slová, priania Tvoje<br/>a nie svoje.<br/>',NULL,129776,2);
INSERT INTO stanza VALUES('SK365','3','Lásku, radosť, pokoj<br/>vkladaj do srdca mi,<br/>prameň čerstvý,<br/>rastúci a nikdy<br/>nekončiaci.<br/>',NULL,129777,3);
INSERT INTO stanza VALUES('SK365','4','Skutočnosť nádherná<br/>tej sily vzkriesenia,<br/>cirkvi daná,<br/>hojnejšie života,<br/>Pane, mi daj.<br/>',NULL,129778,4);
INSERT INTO stanza VALUES('SK365','5','Ó, Tvoj dar najplnší<br/>z Tvojho Slova žiadam<br/>Tvojím menom<br/>a nádherný zvuk chvál<br/>vylieva sa.<br/>',NULL,129779,5);
INSERT INTO stanza VALUES('SK365','6','Ó, môj život je Tvoj,<br/>Tebe patrí navždy,<br/>v Tebe skrytý,<br/>veď nás nemôže nič<br/>už rozdeliť.<br/>',NULL,129780,6);
INSERT INTO stanza VALUES('SK368','1','Ó, k Tebe lásky viac.<br/>Ó, Pane, viac!<br/>Vypočuj modlitbu<br/>na kolenách.<br/>To mojou prosbou je.<br/>Lásky viacej k Tebe,<br/>lásky viacej,<br/>Pane, k Tebe!<br/>',NULL,129781,1);
INSERT INTO stanza VALUES('SK368','2','Ja som svetské hľadal,<br/>radosť, šťastie.<br/>No teraz len Teba,<br/>to najlepšie,<br/>to sa budem modliť.<br/>Lásky viacej k Tebe,<br/>lásky viacej,<br/>Pane, k Tebe!<br/>',NULL,129782,2);
INSERT INTO stanza VALUES('SK368','3','Trápenie nech koná,<br/>bolesť zošli.<br/>Títo sú poslovia<br/>takí sladkí,<br/>keď so mnou spievajú:<br/>Lásky viacej k Tebe,<br/>lásky viacej,<br/>Pane, k Tebe!<br/>',NULL,129783,3);
INSERT INTO stanza VALUES('SK368','4','Nech posledný môj dych<br/>slávi Teba,<br/>tiež srdce povstane,<br/>rozlúčiť sa,<br/>modlitbou mu bude:<br/>Lásky viacej k Tebe,<br/>lásky viacej,<br/>Pane, k Tebe!<br/>',NULL,129784,4);
INSERT INTO stanza VALUES('SK395','1','Ó, Ježišu, rasti vo mne<br/>a nič viac nechcem mať.<br/>Iba srdce bližšie k Tebe<br/>voľné od hriechu mať.<br/>',NULL,129785,1);
INSERT INTO stanza VALUES('SK395','chorus','Každý deň ma Tvoja milosť<br/>v slabosti podporí.<br/>V Tvojom svetle mizne temno,<br/>život smrť pohltí.<br/>',NULL,129786,2);
INSERT INTO stanza VALUES('SK395','2','Tvoja žiara na mňa padla,<br/>v nej mizne všetko zlé.<br/>Že Ty si všetko a ja nič,<br/>tomu ma uč denne.<br/>',NULL,129787,3);
INSERT INTO stanza VALUES('SK395','3','Viac Tvojej slávy chcem vidieť,<br/>Múdry, Svätý, Pravý.<br/>Tvojím živým obrazom byť,<br/>v radosti aj v žiali.<br/>',NULL,129788,4);
INSERT INTO stanza VALUES('SK395','4','Naplň ma radosťou zhora,<br/>silou božskou drž ma.<br/>Tvojej veľkej lásky žiara<br/>nech žiari skrze mňa.<br/>',NULL,129789,5);
INSERT INTO stanza VALUES('SK395','5','Nech sa moje „ja“ zmenšuje,<br/>buď môj život a cieľ.<br/>Skrze Tvoju milosť denne,<br/>chcem Tvoje meno niesť.<br/>',NULL,129790,6);
INSERT INTO stanza VALUES('SK396','1','Vždy sa snažím stúpať vyššie,<br/>zakúšam výšiny nové,<br/>vždy prosím Pána v modlitbe:<br/>„Ó, Pane, zasaď ma vyššie.“<br/>',NULL,129791,1);
INSERT INTO stanza VALUES('SK396','chorus','Pozdvihni ma, dovoľ mi stáť,<br/>vierou v kanánskej zemi stáť,<br/>ďalej, než som dosiaľ prišiel.<br/>Ó, Pane, zasaď ma vyššie.<br/>',NULL,129792,2);
INSERT INTO stanza VALUES('SK396','2','Nechcem ostávať na mieste<br/>pochybností, tam, kde strach je.<br/>Niekto v tom býva, no ja nie,<br/>modlím sa a cielim vyššie.<br/>',NULL,129793,3);
INSERT INTO stanza VALUES('SK396','3','Chcem žiť vyššie, ako svet je,<br/>hoc Satan si to nepraje.<br/>Radostný tón cez vieru znie,<br/>pieseň svätých, čo sú vyššie.<br/>',NULL,129794,4);
INSERT INTO stanza VALUES('SK396','4','Chcem premeriavať najvyššie,<br/>dotknúť sa slávy žiarivej,<br/>budem ostávať v modlitbe:<br/>„Pane, stále ma veď vyššie.“<br/>',NULL,129795,5);
INSERT INTO stanza VALUES('SK398','1','Vykupiteľ môj, ó, byť ako Ty<br/>je mojou túžbou a modlitbou.<br/>Ochotne vzdám sa pokladov zemských,<br/>odejem sa Tvojou podobou.<br/>',NULL,129796,1);
INSERT INTO stanza VALUES('SK398','chorus','Ó, byť ako Ty! Ó, byť ako Ty!<br/>Vykupiteľ ako Ty čistý,<br/>vo Svojej kráse a plnosti príď,<br/>otlač Svoj obraz v mojom srdci.<br/>',NULL,129797,2);
INSERT INTO stanza VALUES('SK398','2','Ó, byť ako Ty! Súcitu plný,<br/>odpúšťajúci, nežný, milý,<br/>pomáhajúci, potešujúci,<br/>hľadajúc hriešnych bludných ľudí.<br/>',NULL,129798,3);
INSERT INTO stanza VALUES('SK398','3','Ó, byť ako Ty! Duchom chudobný,<br/>svätý, odvážny, trpezlivý,<br/>kruté odsúdenia znášajúci,<br/>aby boli iní spasení.<br/>',NULL,129799,4);
INSERT INTO stanza VALUES('SK398','4','Ó, byť ako Ty! Pane, prichádzam,<br/>božské pomazanie prijímam,<br/>všetko, čo mám a čím som, prinášam,<br/>od tejto chvíle Ti všetko dám.<br/>',NULL,129800,5);
INSERT INTO stanza VALUES('SK398','5','Ó, byť ako Ty! Zatiaľ čo prosím,<br/>naplň ma láskou, Ducha vylej.<br/>Učiň ma chrámom, v ktorom prebývaš,<br/>vhodným pre život ľúbi Tebe.<br/>',NULL,129801,6);
INSERT INTO stanza VALUES('SK403','1','Ži cezo mňa, ó, Ježišu,<br/>veď si môj život, Pane.<br/>Do problémov Ťa pozývam<br/>ako riešenie plné.<br/>Ži cezo mňa, ó, Ježišu,<br/>buď len vôľa Tvoja vždy.<br/>Ako nádoba priezračná<br/>Teba chcem zviditeľniť.<br/>',NULL,129802,1);
INSERT INTO stanza VALUES('SK403','2','Ó, Tvoj chrám je zasvätený<br/>od hriechov očistený,<br/>plameň slávy takto môže<br/>zvnútra byť prejavený.<br/>Nech hľadí tak s údivom zem,<br/>že vydávam ochotne<br/>ako otrok telo Tebe,<br/>Ty ma sám posilňuješ.<br/>',NULL,129803,2);
INSERT INTO stanza VALUES('SK403','3','V každej chvíli všetky údy<br/>na Tvoj príkaz čakajú.<br/>Buď namáhať sa pod jarmom,<br/>či len stáť stranou majú.<br/>Ak ma túžiš obmedzovať,<br/>vždy ostávam pokojný,<br/>pôsobíš vo mne vždy verne,<br/>nebudem zarmútený.<br/>',NULL,129804,3);
INSERT INTO stanza VALUES('SK403','4','Vždy mäkký, tichý, pokojný<br/>svoje túžby odkladám.<br/>Nech ukážeš na čokoľvek<br/>k dispozícii sa dám.<br/>Ži cezo mňa ó Ježišu,<br/>veď si môj život Pane.<br/>Do problémov Ťa pozývam<br/>ako riešenie plné.<br/>',NULL,129805,4);
INSERT INTO stanza VALUES('SK426','1','Odstráň závoj, Pane,<br/>chcem svetlo uvidieť,<br/>nebyť viac zvedený,<br/>no žiť v realite.<br/>',NULL,129806,1);
INSERT INTO stanza VALUES('SK426','chorus','Nech Tvoje živé svetlo<br/>ženie moje temno,<br/>spraví tak všetko jasným,<br/>o to, Pane, prosím.<br/>',NULL,129807,2);
INSERT INTO stanza VALUES('SK426','2','Sám seba nepoznám<br/>a pýcha klame ma,<br/>myslím, že pravdu mám,<br/>cením si svoje „ja“.<br/>',NULL,129808,3);
INSERT INTO stanza VALUES('SK426','3','Teba slabo poznám,<br/>v doktríne povrchne.<br/>Chýba mi zjavenie<br/>Teba v realite.<br/>',NULL,129809,4);
INSERT INTO stanza VALUES('SK426','4','Tvoj život, ktorý mám,<br/>navonok nežijem,<br/>len ťažko poznávam,<br/>čo duch, čo telo je.<br/>',NULL,129810,5);
INSERT INTO stanza VALUES('SK426','5','V cestách Tvojich, Pane,<br/>často jasno nemám,<br/>zatváram sa v sebe<br/>a z cesty odchádzam.<br/>',NULL,129811,6);
INSERT INTO stanza VALUES('SK426','6','Čo vôľa Tvoja je<br/>neviem celkom dobre,<br/>a tak svoju vôľu,<br/>často presadzujem.<br/>',NULL,129812,7);
INSERT INTO stanza VALUES('SK426','7','Tiež o cirkvi Tvojej<br/>musím mať zjavenie,<br/>život Tela poznať,<br/>Teba objavovať.<br/>',NULL,129813,8);
INSERT INTO stanza VALUES('SK426','8','Odhaľ zo mňa závoj,<br/>v temnote nechcem žiť,<br/>nechcem byť klamaný<br/>tiež v pýche nechcem žiť.<br/>',NULL,129814,9);
INSERT INTO stanza VALUES('SK431','1','Láska Tvoja, ó, Bože, tiahne ma<br/>ako silný prúd, čo prudko plynie,<br/>v skľúčenej duši priechod túži mať,<br/>prúd všetky prekážky z cesty zmetie.<br/>',NULL,129815,1);
INSERT INTO stanza VALUES('SK431','2','Či sa nemám nechať tiahnuť silou?<br/>Či si nepriať, aby ten prúd plynul?<br/>Ach, Bože, Ty si si ma podmanil,<br/>život už nie je, ako býval prv.<br/>',NULL,129816,2);
INSERT INTO stanza VALUES('SK431','3','Láska, rozlom prirodzenosť moju,<br/>každú moju myšlienku vyčisti,<br/>zaplav city, očisť vôľu moju,<br/>nenechaj nič, len Tvoj život čistý.<br/>',NULL,129817,3);
INSERT INTO stanza VALUES('SK431','4','Tak si ma Boh úplne privlastnil,<br/>som slobodný a z môjho života<br/>poplynie prúd nehy a milosti,<br/>milujem, pretože Boh miloval.<br/>',NULL,129818,4);
INSERT INTO stanza VALUES('SK433','1','Ja som Pánov! Ó, radosť nevýslovná,<br/>echo sladké na hlas lásky Božej,<br/>viera vraví nám „áno“ na ten šepot:<br/>„Neboj sa! Vykúpil som ťa. Si môj.“<br/>',NULL,129819,1);
INSERT INTO stanza VALUES('SK433','2','Ja som Pánov! Ó, vyznanie radostné,<br/>ním privoláva nevesta ten deň,<br/>keď láskou príjme ženícha na veky,<br/>milovať a ctiť Ho navždy bude.<br/>',NULL,129820,2);
INSERT INTO stanza VALUES('SK433','3','Ja som Pánov! No súčasne učím sa,<br/>čo znamená byť verný, milovať,<br/>ako Ti slúžiť a podriaďovať sa<br/>a bezpodmienečne Ťa poslúchať.<br/>',NULL,129821,3);
INSERT INTO stanza VALUES('SK433','4','Ja som Pánov! Telo, dušu aj ducha<br/>zapečať Sebe nezmeniteľne.<br/>Ty vo Svojej milosti a plnosti<br/>navždy a naveky patríš len mne.<br/>',NULL,129822,4);
INSERT INTO stanza VALUES('SK437','1','Či si Pána videl, poznal?<br/>Či ti Pán srdce zajal?<br/>Stal sa údelom pre mnohých<br/>a mnohým srdcia spútal.<br/>',NULL,129823,1);
INSERT INTO stanza VALUES('SK437','chorus','Uchvátení Jeho krásou<br/>hodnú chválu vzdávame.<br/>Nech nás Jeho krása tiahne,<br/>Kráľa nášho chválime.<br/>',NULL,129824,2);
INSERT INTO stanza VALUES('SK437','2','Modly nás priťahovali,<br/>moderné, pekné veci<br/>a pozlátky odzbrojili,<br/>boli sme Ti vzdialení.<br/>',NULL,129825,3);
INSERT INTO stanza VALUES('SK437','3','Čo otáča ľudské srdce<br/>od všetkých modiel zemských?<br/>Nie to správne či povinnosť,<br/>ale vízia ceny.<br/>',NULL,129826,4);
INSERT INTO stanza VALUES('SK437','4','Nie, že pádom týchto modiel<br/>s tou ich nádherou prázdnou.<br/>Odkrytím však Jeho srdca<br/>s Jeho krásou žiarivou.<br/>',NULL,129827,5);
INSERT INTO stanza VALUES('SK437','5','Kto zhasí blikot tých modiel<br/>už pred východom slnka?<br/>Kto odstráni rúcho zimy<br/>už pred príchodom leta?<br/>',NULL,129828,6);
INSERT INTO stanza VALUES('SK437','6','Táto tvár zmenila Petra,<br/>túto tvár videl Štefan,<br/>srdce Márie plakalo,<br/>chráni nás od modiel Pán.<br/>',NULL,129829,7);
INSERT INTO stanza VALUES('SK437','7','Tiahni, zvíťaz a naplň nás,<br/>kalich náš nech preteká,<br/>my nemáme nič s modlami,<br/>tiahni nás viac, Pane náš.<br/>',NULL,129830,8);
INSERT INTO stanza VALUES('SK445','1','Vezmi môj život Pane,<br/>zasvätený nech Ti je.<br/>Vezmi moje chvíle, dni<br/>buď v nich navždy chválený,<br/>buď v nich navždy chválený.<br/>',NULL,129831,1);
INSERT INTO stanza VALUES('SK445','2','Svoje ruky Tebe dám,<br/>podľa lásky nech konám.<br/>Svoje nohy Tebe dám,<br/>nech sú krásne pre Teba,<br/>nech sú krásne pre Teba.<br/>',NULL,129832,2);
INSERT INTO stanza VALUES('SK445','3','Vezmi si môj hlas Pane<br/>Kráľovi nech pieseň znie.<br/>Moje pery sú Tvoje,<br/>nech z nich Tvoje slovo znie,<br/>nech z nich Tvoje slovo znie.<br/>',NULL,129833,3);
INSERT INTO stanza VALUES('SK445','4','Striebro, zlato Tebe dám,<br/>nič si z toho nenechám.<br/>Vezmi moje schopnosti,<br/>všetko o mne rozhodni,<br/>všetko o mne rozhodni.<br/>',NULL,129834,4);
INSERT INTO stanza VALUES('SK445','5','Moju vôľu si vezmi,<br/>už mi viacej nepatrí.<br/>Moje srdce Ti patrí,<br/>nech je trónom Kráľovým,<br/>nech je trónom Kráľovým.<br/>',NULL,129835,5);
INSERT INTO stanza VALUES('SK445','6','Lásku moju si vezmi,<br/>dám Ti všetky poklady.<br/>Vezmi si ma celého,<br/>budem navždy iba Tvoj,<br/>budem navždy iba Tvoj.<br/>',NULL,129836,6);
INSERT INTO stanza VALUES('SK473','1','Žiaden jazyk nevyjadrí<br/>stav slobody duše,<br/>čo prešla od zemských vecí<br/>ku kontrole Božej.<br/>Smrť, aj život, všetko je jej,<br/>všetko pre jej dobro.<br/>V Kristovi dýcha pokojne,<br/>v Kristovi má domov.<br/>',NULL,129837,1);
INSERT INTO stanza VALUES('SK473','2','Náš Kráľ si zvolil zdieľať trón<br/>s ľuďmi ako sme my,<br/>bolo by zvláštne odmietnuť<br/>vydať sa Pánovi.<br/>Nehovor, že veľmi trpíš!<br/>Veď je to výsadou<br/>patriť Mu s tými, čo prešli<br/>akoukoľvek cenou.<br/>',NULL,129838,2);
INSERT INTO stanza VALUES('SK473','3','Povstaň, daj zlomok za všetko!<br/>Uchop sa možnosti!<br/>Všetky veci posluhujú<br/>vykúpenej duši.<br/>Ak Mu patríš, tak máš všetko,<br/>On aj ty ste jedno.<br/>Hojný život je iba v Ňom,<br/>’by kráľovstvo prišlo.<br/>',NULL,129839,3);
INSERT INTO stanza VALUES('SK474','1','Som s Tebou jedno, Ježišu,<br/>a čo máš, je tak moje,<br/>jednotný som s Tebou v duchu.<br/>Čím si, to vo mne žije.<br/>',NULL,129840,1);
INSERT INTO stanza VALUES('SK474','chorus','Jedno sme, jedno sme,<br/>jedno sme, jedno sme,<br/>Pane, deň za dňom Ťa zdieľam,<br/>si všetkým pre mňa, Pane.<br/>',NULL,129841,2);
INSERT INTO stanza VALUES('SK474','2','Tvoj ľudský život dnes zdieľam<br/>a jeho naplnenie,<br/>Tvoja úplná poslušnosť<br/>dostupná tak pre mňa je.<br/>',NULL,129842,3);
INSERT INTO stanza VALUES('SK474','3','Jedno s Tebou na Golgote<br/>bol som ukrižovaný.<br/>Ja som mŕtvy pre tento svet,<br/>mne je ukrižovaný.<br/>',NULL,129843,4);
INSERT INTO stanza VALUES('SK474','4','S Tebou jedno vo vzkriesení,<br/>povstal som, žijem v Tebe<br/>životom, ktorým si Ty sám,<br/>si vo mne, Pane vo mne.<br/>',NULL,129844,5);
INSERT INTO stanza VALUES('SK474','5','Vo vystúpení jedno sme,<br/>v nebesiach spolu s Tebou.<br/>Iba pútnik som na svete,<br/>len v Tebe je život môj.<br/>',NULL,129845,6);
INSERT INTO stanza VALUES('SK474','6','Som s Tebou jedno na tróne,<br/>autoritu zdieľam ja,<br/>tak, ako zdieľam život Tvoj,<br/>Ty vo mne a v Tebe ja.<br/>',NULL,129846,7);
INSERT INTO stanza VALUES('SK475','1','Jedno s Tebou, ó, Syn večný,<br/>vierou v duchu spojení!<br/>Máme podiel v Tvojej smrti<br/>a živote, Boh večný.<br/>Stali sme sa, Milovaný,<br/>súčasťou Teba, milosťou,<br/>sme dedičmi Otcovými,<br/>Tvojho Ducha svätyňou!<br/>',NULL,129847,1);
INSERT INTO stanza VALUES('SK475','2','Jedno s Tebou, Syn vtelený,<br/>údmi Tvojho Tela sme,<br/>my sme z Teba narodení,<br/>putujeme spoločne.<br/>Jedno s Tebou, Pomazaný,<br/>tiež moc Ducha zdieľame,<br/>s Tebou v plnej súčinnosti<br/>deň za dňom pracujeme.<br/>',NULL,129848,2);
INSERT INTO stanza VALUES('SK475','3','Jedno s Tebou, zavrhnutý,<br/>prešli sme odsúdením,<br/>hriechu sme naveky mŕtvi,<br/>nepriateľ porazený.<br/>Sme s Tebou v Tvojom vzkriesení,<br/>zvíťaziť smrť nedokáže,<br/>žijeme v novom stvorení,<br/>ovocie prinášame.<br/>',NULL,129849,3);
INSERT INTO stanza VALUES('SK475','4','V Tvojom nanebovstúpení<br/>autoritu zdieľame,<br/>s Tebou na trón posadení<br/>my s Tebou kraľujeme.<br/>S Tebou, až sa vrátiš, Synu,<br/>budeme oslávení,<br/>vyjadrovať krásu Tvoju,<br/>jedno s Tebou naveky.<br/>',NULL,129850,4);
INSERT INTO stanza VALUES('SK477','1','Tisíckrát hoc by sa<br/>Pán Ježiš narodil,<br/>pokiaľ nie je v tebe,<br/>vždy budeš úbohý.<br/>Pánov kríž golgotský<br/>ti dušu nespasí,<br/>len kríž čo v srdci máš,<br/>ním si zachránený.<br/>',NULL,129851,1);
INSERT INTO stanza VALUES('SK477','chorus','Kristov kríž prijímam ťa,<br/>krížom sa naplním,<br/>aby som svojmu ja umrel<br/>a žil životom božským.<br/>',NULL,129852,2);
INSERT INTO stanza VALUES('SK477','2','Čokoľvek miluješ,<br/>presne takým budeš,<br/>Boh, ak ľúbiš Boha,<br/>prach, ak prach miluješ.<br/>Odíď a príde Boh,<br/>umri, nech On žije,<br/>nebuď a On bude,<br/>všetkým sa ti stane.<br/>',NULL,129853,3);
INSERT INTO stanza VALUES('SK477','3','Láska ťa privedie<br/>najrýchlejšie k Bohu.<br/>Na ceste poznania<br/>točíš sa len v kruhu.<br/>Svet od seba vyžeň,<br/>tvoje srdce bude<br/>lásky Božej plné,<br/>ako je On, sväté.<br/>',NULL,129854,4);
INSERT INTO stanza VALUES('SK481','1','Svetu, hriechu aj svojmu „ja“<br/>s Ním som ukrižovaný,<br/>do Ježišovho života<br/>sladko som uvádzaný.<br/>Účasťou na utrpení<br/>smrti pripodobnený<br/>na Kalváriu tak idem<br/>so Spasiteľom mojím.<br/>',NULL,129855,1);
INSERT INTO stanza VALUES('SK481','chorus','Na Kalváriu idem,<br/>kde bol Spasiteľ, idem.<br/>S Tebou ísť, pomôž mi, Pane,<br/>na Kalváriu, Pane.<br/>',NULL,129856,2);
INSERT INTO stanza VALUES('SK481','2','Zomrieť s Pánom nie je ťažké,<br/>život vzkriesenia znajúc.<br/>Trpieť s Pánom nie je ťažké,<br/>radosťou pretekajúc.<br/>Pán prišiel prebývať vo mne,<br/>v moci Svojho vzkriesenia,<br/>s radosťou mi srdce ide<br/>znášať s Ním utrpenia.<br/>',NULL,129857,3);
INSERT INTO stanza VALUES('SK481','3','Ak umrieme, tak budeme<br/>s Kristom žiť a kraľovať.<br/>Takto víťaz ľahko môže<br/>ocenenie dosiahnuť.<br/>Aké vzácne bude ráno,<br/>keď ti Pán v ten deň povie:<br/>„Ty si dieťa moje, so Mnou<br/>znášalo pohanenie.“<br/>',NULL,129858,4);
INSERT INTO stanza VALUES('SK482','1','S Kristom som ukrižovaný,<br/>kríž ma oslobodzuje.<br/>S Kristom som bol tiež vzkriesený,<br/>vo mne žije, kraľuje.<br/>',NULL,129859,1);
INSERT INTO stanza VALUES('SK482','chorus','Ó, sladké to je, zomrieť s Kristom<br/>svetu, hriechu a sebe.<br/>Ó, aké sladké je žiť s Kristom,<br/>vo mne žije, kraľuje.<br/>',NULL,129860,2);
INSERT INTO stanza VALUES('SK482','2','Tajomstvo od vekov skryté,<br/>viera ho vysvetľuje:<br/>Kristus nádej slávy vo mne,<br/>znovu to vyhlasujem.<br/>',NULL,129861,3);
INSERT INTO stanza VALUES('SK482','3','To je tým tajomstvom skrytým,<br/>žatva rastie zo zrna.<br/>Zlý strom zaštepený s dobrým,<br/>sladký, hojný život má.<br/>',NULL,129862,4);
INSERT INTO stanza VALUES('SK482','4','To je tým svätým tajomstvom,<br/>Sám On, nie naša svätosť.<br/>Nás, Pane, vyprázdni! Naplň!<br/>Pane, si naša plnosť.<br/>',NULL,129863,5);
INSERT INTO stanza VALUES('SK482','5','Toto je balzam na bolesť,<br/>naša sila nech zomrie,<br/>chceme Jeho život, plnosť,<br/>Pán nech nás zásobuje.<br/>',NULL,129864,6);
INSERT INTO stanza VALUES('SK482','6','To je príbeh nášho Majstra,<br/>krížom Pán dosiahol trón.<br/>Jeho cesta je tiež naša,<br/>vedie cez smrť až na trón.<br/>',NULL,129865,7);
INSERT INTO stanza VALUES('SK493','1','Ty si teraz Duchom, Pane,<br/>On dá život, obživuje,<br/>Ty nás Sebou posilňuješ,<br/>aké slávne, božské to je!<br/>',NULL,129866,1);
INSERT INTO stanza VALUES('SK493','2','Ty si teraz Duchom, Pane,<br/>iba v Tebe je sloboda.<br/>Skrz toto oslobodenie,<br/>nás riadi zákon života.<br/>',NULL,129867,2);
INSERT INTO stanza VALUES('SK493','3','Ty si teraz Duchom, Pane,<br/>premieňaš a presycuješ,<br/>pripodobňuješ nás k Sebe,<br/>Svojím svetlom osvecuješ.<br/>',NULL,129868,3);
INSERT INTO stanza VALUES('SK493','4','Ty si teraz Duchom, Pane,<br/>robíš si v mojom duchu dom.<br/>My sa spolu zmiešavame,<br/>stávame sa jedným duchom.<br/>',NULL,129869,4);
INSERT INTO stanza VALUES('SK493','5','Pane, uč ma ducha cvičiť,<br/>uč ma Teba kontaktovať,<br/>vždy chcem v Tvojom Duchu chodiť,<br/>Teba, skutočnosť stále mať.<br/>',NULL,129870,5);
INSERT INTO stanza VALUES('SK495','1','Kristus je stredom Božím,<br/>je v Božích očiach všetkým.<br/>Radosťou, potešením,<br/>je pre Boha naveky.<br/>',NULL,129871,1);
INSERT INTO stanza VALUES('SK495','2','Je Božím stelesnením,<br/>sídli v Ňom plnosť Božstva.<br/>Jeho nadradenosti<br/>sa nikto nevyrovná.<br/>',NULL,129872,2);
INSERT INTO stanza VALUES('SK495','3','Zámer Boha je preňho,<br/>má byť vo všetkom všetkým.<br/>V Ňom je všetko stvorené,<br/>v nebesiach aj na zemi.<br/>',NULL,129873,3);
INSERT INTO stanza VALUES('SK495','4','Stvorenie je pre Krista,<br/>v Kristu bolo stvorené.<br/>Vše spočíva v Kristovi,<br/>stredom aj obvodom je.<br/>',NULL,129874,4);
INSERT INTO stanza VALUES('SK495','5','Vo vykúpení všetkým,<br/>Ním je všetko zmierené.<br/>Jeho krv všetko s Bohom<br/>do pokoja uvedie.<br/>',NULL,129875,5);
INSERT INTO stanza VALUES('SK495','6','On veľkým počiatkom je<br/>a živou Hlavou cirkvi.<br/>Jej životom, obsahom,<br/>z mŕtvych Prvorodený.<br/>',NULL,129876,6);
INSERT INTO stanza VALUES('SK495','7','Kráľom v kráľovstve Božom,<br/>všetka moc je Mu daná.<br/>Nad zemou aj v nebesiach<br/>v sláve bude panovať.<br/>',NULL,129877,7);
INSERT INTO stanza VALUES('SK495','8','V nebesiach nových, zemi,<br/>bude stredom pre všetkých,<br/>pre Boha aj pre ľudí,<br/>stále, navždy, naveky.<br/>',NULL,129878,8);
INSERT INTO stanza VALUES('SK495','9','Túžbou Boha je, aby<br/>On bol vo všetkom Prvý,<br/>aby sme Krista už dnes<br/>spoločne prežívali.<br/>',NULL,129879,9);
INSERT INTO stanza VALUES('SK496','1','Kristus je skutočnosťou všetkého,<br/>Božstva, človeka a všetkých vecí.<br/>Bez Neho Boha neuzrie nikto,<br/>klamstvom, sú bez Neho všetky veci.<br/>',NULL,129880,1);
INSERT INTO stanza VALUES('SK496','2','Všetky symboly a predobrazy,<br/>ako aj všetky naše potreby,<br/>sú iba Božieho Krista tieňmi,<br/>On nám musí byť vo všetkom všetkým.<br/>',NULL,129881,2);
INSERT INTO stanza VALUES('SK496','3','Všetky veci sú márnosť márností,<br/>pokiaľ v nich nie je Kristus skutočný.<br/>Aj keby sme celý svet získali,<br/>bez Krista ostaneme vždy prázdni.<br/>',NULL,129882,3);
INSERT INTO stanza VALUES('SK496','4','Kristus je náš Pán, náš Boh skutočný,<br/>náš skutočný život a svetlo tiež,<br/>náš pokrm aj náš nápoj skutočný,<br/>náš skutočný odev, naša moc tiež.<br/>',NULL,129883,4);
INSERT INTO stanza VALUES('SK496','5','Všetkých doktrín a teológie,<br/>Kristus je jedinou skutočnosťou.<br/>Bez Neho aj poznanie Biblie,<br/>je mŕtvou literou a márnosťou.<br/>',NULL,129884,5);
INSERT INTO stanza VALUES('SK496','6','Kristus je časom, priestorom tiež je,<br/>skutočnosťou toho, čo sa deje.<br/>Kristus všetkého skutočnosťou je<br/>a navždy skutočnosťou zostane.<br/>',NULL,129885,6);
INSERT INTO stanza VALUES('SK497','1','Najvyšším významom milosti je,<br/>že sa z Boha v Synovi tešíme.<br/>Nie je to iba niečo nám dané,<br/>milosť je sám Boh, náš slávny podiel.<br/>',NULL,129886,1);
INSERT INTO stanza VALUES('SK497','2','Boh prišiel v tele, je stelesnený,<br/>aby sme Ho mohli kontaktovať.<br/>Toto je milosť, čo máme z Boha,<br/>s Kristom prichádza, je ňou Kristus sám.<br/>',NULL,129887,2);
INSERT INTO stanza VALUES('SK497','3','Apoštol uznal všetko za straty,<br/>milosť preňho bola Boh v Kristovi.<br/>Tou milosťou – Pánom prežívaným,<br/>vo svojom behu predišiel všetkých.<br/>',NULL,129888,3);
INSERT INTO stanza VALUES('SK497','4','Milosť je Kristus – sila vnútorná,<br/>Jeho dostatočnosťou napĺňa.<br/>Ó, táto milosť je v našom duchu,<br/>posilňuje, Božiu vôľu koná.<br/>',NULL,129889,4);
INSERT INTO stanza VALUES('SK497','5','Tú milosť, ktorou je živý Kristus,<br/>potrebujeme prežívať denne.<br/>Nech milosť známe a ňou žijeme,<br/>Pane nech Teba – milosť vnímame.<br/>',NULL,129890,5);
INSERT INTO stanza VALUES('SK499','1','Aký život a pokoj mám!<br/>Kristus teraz vo mne žije.<br/>S Kristom ukrižovaný som<br/>a v tom ma Pán utvrdzuje.<br/>Už nie som ja, kto žije sám,<br/>no vo mne žije Kristus Pán.<br/>',NULL,129891,1);
INSERT INTO stanza VALUES('SK499','2','Aká radosť, odpočinok!<br/>Kristus sa vo mne formuje.<br/>Jeho život, prirodzenosť<br/>Pán celkom do mňa vpracuje.<br/>Všetko, čo som, je skončené,<br/>všetko Kristovo pre mňa je.<br/>',NULL,129892,2);
INSERT INTO stanza VALUES('SK499','3','Ó, čo za chvála, myšlienka!<br/>Pán bude vo mne zväčšený.<br/>Ja nebudem zahanbený,<br/>On bude vždy oslávený.<br/>Životom alebo smrťou<br/>bude skrz mňa dosvedčený.<br/>',NULL,129893,3);
INSERT INTO stanza VALUES('SK499','4','Aká cena a čo za zisk!<br/>Kristus môj jediný cieľ je.<br/>Nič si necením, neželám,<br/>mať Krista túžim jedine.<br/>Slávou mojou a korunou<br/>sám Kristus najcennejší je.<br/>',NULL,129894,4);
INSERT INTO stanza VALUES('SK500','1','Aká sila! Ó, čo za moc!<br/>Kristus bol Bohom vzkriesený.<br/>Po pravici usadený,<br/>pre nás Hlavou učinený.<br/>Nesmierna moc daná cirkvi,<br/>ňou kráča nad nepriateľmi.<br/>',NULL,129895,1);
INSERT INTO stanza VALUES('SK500','2','Aká radosť a skutočnosť,<br/>že môžem byť údom Krista!<br/>V jednote so svätými mám<br/>život nového človeka.<br/>S Hlavou v nebesiach spojení<br/>sme cirkev, po ktorej túži.<br/>',NULL,129896,2);
INSERT INTO stanza VALUES('SK500','3','Ó, čo za šírka, dĺžka to,<br/>výška a hĺbka nesmierna!<br/>Kristus, neobmedzený Pán,<br/>nekonečné rozmery má.<br/>Ó, všetko, čím je a čo má,<br/>je nevýslovný život náš.<br/>',NULL,129897,3);
INSERT INTO stanza VALUES('SK501','1','Slávny Kristus, Spasiteľ môj,<br/>Ty si sám božskou žiarou,<br/>Boh nekonečný a večný<br/>sa stal človekom konečným.<br/>',NULL,129898,1);
INSERT INTO stanza VALUES('SK501','chorus','Ó, Kristus je vyjadrením Božím,<br/>bohatým nesmierne, sladkým.<br/>S ľudskosťou je Boh zmiešaný,<br/>je vo mne, je mi všetkým.<br/>',NULL,129899,2);
INSERT INTO stanza VALUES('SK501','2','Boh všetku plnosť v Tebe má,<br/>Božiu slávu zjavuješ sám.<br/>V tele si dal vykúpenie,<br/>dnes jedno s Tebou – Duchom sme.<br/>',NULL,129900,3);
INSERT INTO stanza VALUES('SK501','3','Všetko Otcovo je Tvoje,<br/>všetko, čím si v Duchu moje.<br/>Duch mi Ťa činí skutočným,<br/>aby si bol prežívaný.<br/>',NULL,129901,4);
INSERT INTO stanza VALUES('SK501','4','Duch života spôsobuje,<br/>že Svojím Slovom si vo mne.<br/>Duchom a prijatím Slova<br/>sa Tvoj život vo mne počal.<br/>',NULL,129902,5);
INSERT INTO stanza VALUES('SK501','5','Kým na Teba v duchu hľadím,<br/>Tvoju slávu tak odrážam,<br/>na Tvoj obraz premieňaný,<br/>skrz mňa si vyjadrovaný.<br/>',NULL,129903,6);
INSERT INTO stanza VALUES('SK501','6','Nijako ináč sa nedá<br/>byť svätými, víťazstvo mať,<br/>len tak budeme duchovní,<br/>zakúšať Tvoj život slávy.<br/>',NULL,129904,7);
INSERT INTO stanza VALUES('SK501','7','Duch úplne presycuje<br/>a Boh stále prestupuje,<br/>zo staroby uvoľňuje,<br/>a so svätými buduje.<br/>',NULL,129905,8);
INSERT INTO stanza VALUES('SK505','1','Dnes je v sláve ten človek,<br/>ktorého život mám,<br/>je víťazný, čistý,<br/>svätý, voľnosť má.<br/>Je múdry, nežný,<br/>milujúci nás!<br/>Jeho život v sláve,<br/>musí byť náš.<br/>',NULL,129906,1);
INSERT INTO stanza VALUES('SK505','2','Dnes je v sláve ten človek,<br/>ktorého život mám,<br/>Satana porazil<br/>a slobodu má.<br/>On vládne v živote<br/>a kráľovstvo má!<br/>Jeho život v sláve<br/>musí byť náš.<br/>',NULL,129907,2);
INSERT INTO stanza VALUES('SK505','3','Dnes je v sláve ten človek,<br/>ktorého život mám,<br/>v Ňom niet žiadnych chorôb,<br/>slabostí nemá.<br/>Mocný je, živý je,<br/>stále vzrastá!<br/>Jeho život v sláve<br/>musí byť náš.<br/>',NULL,129908,3);
INSERT INTO stanza VALUES('SK505','4','Dnes je v sláve ten človek,<br/>ktorého život mám,<br/>pokoj v Ňom prebýva,<br/>trpezlivosť má!<br/>Žiari, radostný je<br/>a očakáva<br/>Jeho život v sláve<br/>žitý cez nás.<br/>',NULL,129909,4);
INSERT INTO stanza VALUES('SK507','1','Ďaleko som od Boha bol,<br/>mŕtvy v hriechu, vo tme,<br/>no v Slove som našiel svetlo,<br/>dnes Pán žije vo mne.<br/>',NULL,129910,1);
INSERT INTO stanza VALUES('SK507','chorus','Pán žije vo mne,<br/>Pán žije vo mne.<br/>Ó, nádhernú spásu mám,<br/>veď Pán žije vo mne.<br/>',NULL,129911,2);
INSERT INTO stanza VALUES('SK507','2','Sťa lúče svetla zo slnca<br/>oslobodia kvety,<br/>tak láska, život a svetlo<br/>z Krista vo mne svieti.<br/>',NULL,129912,3);
INSERT INTO stanza VALUES('SK507','3','Sťa kvietok býva v semienku,<br/>ako je strom v šuške,<br/>tak chvála Kristovi – Pravde,<br/>Jeho Duch je vo mne.<br/>',NULL,129913,4);
INSERT INTO stanza VALUES('SK507','4','Celé moje srdce prahne,<br/>že budem ako On,<br/>pri krásnom uvažovaní,<br/>že vo mne žije Pán.<br/>',NULL,129914,5);
INSERT INTO stanza VALUES('SK509','1','Ten strom a prúdiaca rieka,<br/>Edenu významné znaky<br/>človeka sýtia, napoja<br/>pre život na veky.<br/>',NULL,129915,1);
INSERT INTO stanza VALUES('SK509','chorus','Boh v Kristovi mi pokrmom je,<br/>Boh ako Duch ma vyživuje.<br/>Pokiaľ sa sýtim Kristom v duchu,<br/>Krista plný budem.<br/>',NULL,129916,2);
INSERT INTO stanza VALUES('SK509','2','Strom je Krista zobrazením,<br/>život On nám udeľuje,<br/>Boha tak vychutnávame,<br/>uspokojení sme.<br/>',NULL,129917,3);
INSERT INTO stanza VALUES('SK509','3','Rieka, Ducha zobrazením,<br/>ducha On nám vyživuje,<br/>Božieho bohatstva plní,<br/>svätí byť môžeme.<br/>',NULL,129918,4);
INSERT INTO stanza VALUES('SK509','4','Slávny Kristus je môj život,<br/>je ako Duch v duchu mojom,<br/>aby som s Bohom zmiešaný,<br/>vyžaroval Jeho.<br/>',NULL,129919,5);
INSERT INTO stanza VALUES('SK509','5','Chcel by som vyvýšiť Krista<br/>a poslušným vždy Duchu byť,<br/>Jeho milosti byť plný,<br/>slávu Jeho zjaviť.<br/>',NULL,129920,6);
INSERT INTO stanza VALUES('SK510','1','Našiel som Najcennejšieho,<br/>moje srdce spieva,<br/>mám Krista a preto spievam:<br/>ó, čo za Krista mám!<br/>',NULL,129921,1);
INSERT INTO stanza VALUES('SK510','2','Baránok Boží, môj Kristus,<br/>priniesol spasenie,<br/>je Slnko Spravodlivosti,<br/>na krídlach má zdravie.<br/>',NULL,129922,2);
INSERT INTO stanza VALUES('SK510','3','Môj Kristus je Strom života,<br/>sladký a prehojný.<br/>On uspokojuje môj hlad,<br/>z Neho ja denne jem.<br/>',NULL,129923,3);
INSERT INTO stanza VALUES('SK510','4','On je Skalou rozštiepenou,<br/>čo z nej tečie život.<br/>Je prameňom v srdci mojom,<br/>utišuje môj smäd.<br/>',NULL,129924,4);
INSERT INTO stanza VALUES('SK510','5','Môj Pán, život, cesta, svetlo,<br/>potešenie, zdravie,<br/>pokoj, radosť a bohatstvo,<br/>nádejou, slávou je.<br/>',NULL,129925,5);
INSERT INTO stanza VALUES('SK510','6','Kristus je moja múdrosť, moc,<br/>chvála, spravodlivosť,<br/>vykúpenie a víťazstvo,<br/>moja pravda, svätosť.<br/>',NULL,129926,6);
INSERT INTO stanza VALUES('SK510','7','Kristus – Spasiteľ, Pán, Pastier,<br/>z nebies je Advokát,<br/>môj Radca, Otec a Priateľ,<br/>môj Boh, Milý a Brat.<br/>',NULL,129927,7);
INSERT INTO stanza VALUES('SK510','8','Kristus je Vodca, Strážca tiež,<br/>Sprievodca, Učiteľ,<br/>moja Hlava, Majster, Ženích,<br/>prebývať vo mne chce.<br/>',NULL,129928,8);
INSERT INTO stanza VALUES('SK510','9','Kristus je Prorok, Kňaz a Kráľ,<br/>je Prorok vidiaci.<br/>Je najvyšší Kňaz – Prostredník,<br/>Kráľ, mocou vládnuci.<br/>',NULL,129929,9);
INSERT INTO stanza VALUES('SK510','10','Kristus – je viery Pôvodcom<br/>aj Zavŕšiteľom,<br/>môj Prostredník a Ručiteľ,<br/>On je verným Svedkom.<br/>',NULL,129930,10);
INSERT INTO stanza VALUES('SK510','11','Kristus je môj večný domov,<br/>zemou dostatočnou.<br/>Pevnosťou, úkrytom, vežou,<br/>pozíciou večnou.<br/>',NULL,129931,11);
INSERT INTO stanza VALUES('SK510','12','Kristus – sabat, nový mesiac,<br/>ráno moje aj deň,<br/>môj čas a tiež moja večnosť –<br/>nikdy neuplynie.<br/>',NULL,129932,12);
INSERT INTO stanza VALUES('SK510','13','Kristus dôvera aj prianie,<br/>všetkého splnením,<br/>uspokojenie, záľuba,<br/>všetko uspokojí.<br/>',NULL,129933,13);
INSERT INTO stanza VALUES('SK510','14','Kristus všetko zahrňuje,<br/>ako Ho nazvať mám?<br/>Prvý je a tiež posledný,<br/>je vo všetkom všetkým.<br/>',NULL,129934,14);
INSERT INTO stanza VALUES('SK510','15','Keď mám teraz taký poklad,<br/>chválu srdce spieva,<br/>musím ja spievať stále viac:<br/>ó, čo za Krista mám!<br/>',NULL,129935,15);
INSERT INTO stanza VALUES('SK511','1','Naše posolstvo je Ježiš,<br/>našou témou jedinou.<br/>Ježiša vyvyšujeme<br/>a vidíme len Jeho.<br/>',NULL,129936,1);
INSERT INTO stanza VALUES('SK511','chorus','Je to Ježiš, navždy Ježiš,<br/>je všetkým vo všetkom, Pán.<br/>Spasiteľ, Posvätiteľ, Sviežosť,<br/>Prichádzajúci, slávny Kráľ.<br/>',NULL,129937,2);
INSERT INTO stanza VALUES('SK511','2','Sám Ježiš je náš Spasiteľ,<br/>našu vinu odniesol.<br/>On je naša spravodlivosť<br/>stále je našou silou.<br/>',NULL,129938,3);
INSERT INTO stanza VALUES('SK511','3','Ježiš je náš Posvätiteľ,<br/>zachraňuje z nášho ja.<br/>So všetkou plnosťou Ducha,<br/>On napĺňa nám srdcia.<br/>',NULL,129939,4);
INSERT INTO stanza VALUES('SK511','4','Ježiš je náš Uzdraviteľ,<br/>naše nemoci nesie.<br/>Jeho život, Jeho plnosť<br/>ako údy zdieľame.<br/>',NULL,129940,5);
INSERT INTO stanza VALUES('SK511','5','Pán Ježiš je našou mocou,<br/>naším darom letničným.<br/>Dýchni Svoju silu na nás,<br/>naplň nás Duchom Svätým.<br/>',NULL,129941,6);
INSERT INTO stanza VALUES('SK511','6','A na Ježiša čakáme,<br/>volaniu načúvame,<br/>stále to však je len Ježiš,<br/>naveky všetkým bude.<br/>',NULL,129942,7);
INSERT INTO stanza VALUES('SK513','1','Požehnanie som chcel,<br/>dnes však Pána chcem.<br/>Po pocitoch túžil,<br/>no dnes po Slove.<br/>Po daroch som túžil,<br/>dnes však Darcu mám.<br/>Uzdravenie som chcel,<br/>no dnes Jeho mám.<br/>',NULL,129943,1);
INSERT INTO stanza VALUES('SK513','chorus','Všetko vo všetkom – Pán,<br/>Jemu spievať chcem.<br/>Všetko je v Kristovi<br/>a Kristus všetkým je.<br/>',NULL,129944,2);
INSERT INTO stanza VALUES('SK513','2','Snažil som sa predtým,<br/>dôveru dnes mám.<br/>Mal som len pol spásy,<br/>úplnú dnes mám.<br/>Snažil som sa držať,<br/>dnes som držaný.<br/>Stále som hnaný bol,<br/>dnes zakotvený.<br/>',NULL,129945,3);
INSERT INTO stanza VALUES('SK513','3','Plánoval som pilne,<br/>dnes sa len modlím.<br/>Znepokojoval sa,<br/>dnes sa spájam s Ním.<br/>Chcel som mnoho vecí,<br/>dnes len, čo chce On.<br/>Vždy som niečo pýtal,<br/>dnes len chválim Ho.<br/>',NULL,129946,4);
INSERT INTO stanza VALUES('SK513','4','Pracoval som predtým,<br/>dnes pracuje On.<br/>Používal som Ho,<br/>dnes užíva On.<br/>Vždy som chcel byť mocný,<br/>dnes Mocného chcem.<br/>Pre seba som konal,<br/>dnes pre Neho len.<br/>',NULL,129947,5);
INSERT INTO stanza VALUES('SK513','5','Dúfal som v Ježiša,<br/>že je môj, dnes viem.<br/>Lampa stále hasla,<br/>dnes žiari jasne.<br/>Vždy som čakal na smrť,<br/>príchod Jeho dnes.<br/>Moja nádej kotví,<br/>za oponou dnes.<br/>',NULL,129948,6);
INSERT INTO stanza VALUES('SK522','1','Moja duša v Tebe, Kriste,<br/>našla pokoj, šťastie.<br/>Predlho som blaho hľadal,<br/>predtým nepoznané.<br/>',NULL,129949,1);
INSERT INTO stanza VALUES('SK522','chorus','Len Kristus uspokojuje,<br/>iné meno nemám.<br/>Ó, lásku, život aj radosť,<br/>Pán Ježiš, v Tebe mám.<br/>',NULL,129950,2);
INSERT INTO stanza VALUES('SK522','2','Odpočinok aj spokojnosť<br/>som chcel, no nie Teba.<br/>Keď som míňal Spasiteľa,<br/>láskou uchopil ma.<br/>',NULL,129951,3);
INSERT INTO stanza VALUES('SK522','3','Puklé cisterny som skúšal,<br/>neudržia vodu!<br/>Nahnem sa, že sa napijem,<br/>vytiekli zospodu.<br/>',NULL,129952,4);
INSERT INTO stanza VALUES('SK522','4','Po radovánkach trúchlil som,<br/>po Tebe však nikdy.<br/>Slepým očiam si dal milosť,<br/>Pane, si ľúbezný.<br/>',NULL,129953,5);
INSERT INTO stanza VALUES('SK523','1','K Prameňu života som prišiel,<br/>tomu, ktorý prúdi z nebies,<br/>odišiel som od vôd súžení,<br/>som v Elíme lásky Božej.<br/>Teraz pijem vodu nebeskú,<br/>vyviera, z mojich útrob tečie<br/>nesmierne a nevýslovné<br/>Tešiteľa potešenie.<br/>',NULL,129954,1);
INSERT INTO stanza VALUES('SK523','chorus','K prameňu života pristúp,<br/>tie vody nikdy nevyschnú,<br/>z neobmedzených zásob pi,<br/>veď Kristus je tvoj zdroj živý.<br/>',NULL,129955,2);
INSERT INTO stanza VALUES('SK523','2','Pri prameni Jeho krvi som,<br/>viny a nečistoty berie,<br/>v ňom som od hriechov očistený<br/>a môj odev belší než sneh je.<br/>Vlastnú spravodlivosť nemám,<br/>Ježiš v mojej duši žije,<br/>Jeho božskú prirodzenosť mám,<br/>iba v Ňom všetko bez chyby je.<br/>',NULL,129956,3);
INSERT INTO stanza VALUES('SK523','3','Som pri Prameni uzdravenia,<br/>nekonečnom, večnom zdroji.<br/>To tajomstvo sa kúpiť nedá,<br/>ľudská múdrosť neobstojí.<br/>Tajomstvo je však odhalené<br/>prameňom, čo Mu z boku plynie,<br/>Jeho ranami čo uzdravia,<br/>Ježišom, čo v nás má obydlie.<br/>',NULL,129957,4);
INSERT INTO stanza VALUES('SK523','4','Som pri Prameni potešenia,<br/>Jeho radosť je mojou silou,<br/>moje potešenie rýdze je,<br/>moje slnko je stále so mnou.<br/>Umrie a uschne figovník,<br/>radosti, nádeje zemské,<br/>moje pramene však neuschnú,<br/>môj podiel, radosť sú božské.<br/>',NULL,129958,5);
INSERT INTO stanza VALUES('SK535','1','Veriacim v meno Ježiša,<br/>takým nie je nič nemožné.<br/>V láske Tvoju pravdu prijmem,<br/>viac sa už rúhať nebudem.<br/>Pane verím, v Teba verím,<br/>nič pre mňa nie je nemožným.<br/>',NULL,129959,1);
INSERT INTO stanza VALUES('SK535','2','Stopnúť vo mne vládu hriechu<br/>zdalo sa pre mňa nemožné.<br/>Avšak viem, že sa to stane,<br/>v Tvoju vernosť verím, Pane.<br/>Ak je Tebe všetko možné,<br/>pre mňa nie je nič nemožné.<br/>',NULL,129960,2);
INSERT INTO stanza VALUES('SK535','3','Zem aj peklo Slovo poprú,<br/>no Slovo nikdy nezlyhá.<br/>Pán prelomí silu hriechu,<br/>je to isté, hoc sa nezdá.<br/>Stane sa, čo je nemožné,<br/>pre mňa nie je nič nemožné.<br/>',NULL,129961,3);
INSERT INTO stanza VALUES('SK535','4','Pre Boha je všetko možné,<br/>pre Krista, silu Božiu v nás,<br/>pre mňa, keď som obnovený,<br/>v Kristovi formovaný zas.<br/>Hriech viac vo mne nepanuje<br/>pre mňa nie je nič nemožné.<br/>',NULL,129962,4);
INSERT INTO stanza VALUES('SK535','5','Pre Boha je všetko možné,<br/>pre Krista, sile Božej v nás.<br/>Teraz sa vo mne rozlievaj,<br/>aby si žil Ty a nie ja.<br/>Nech len zakúšam deň čo deň<br/>sladkosť tej lásky všemocnej.<br/>',NULL,129963,5);
INSERT INTO stanza VALUES('SK538','1','Božím zámerom a túžbou<br/>je vo mne zjaviť Krista,<br/>nemať náboženstvo zvonku,<br/>ale vnútri mať Krista.<br/>',NULL,129964,1);
INSERT INTO stanza VALUES('SK538','chorus','Božím zámerom je do mňa<br/>vpracovávať len Krista.<br/>Nepredvádzať nič navonok,<br/>ako všetko mať Krista.<br/>',NULL,129965,2);
INSERT INTO stanza VALUES('SK538','2','Božím zámerom je, aby<br/>Jeho Kristus žil vo mne.<br/>Nechce vonkajšie praktiky,<br/>On pôsobí vnútorne.<br/>',NULL,129966,3);
INSERT INTO stanza VALUES('SK538','3','Božím zámerom je, aby<br/>vo mne sformoval Krista.<br/>Nechce mať vonkajšie formy,<br/>no vo vnútri rast Krista.<br/>',NULL,129967,4);
INSERT INTO stanza VALUES('SK538','4','Božím zámerom je, aby<br/>Kristus mal domov vo mne.<br/>Nielen slúžiť navonok Mu,<br/>On prebýva vnútorne.<br/>',NULL,129968,5);
INSERT INTO stanza VALUES('SK538','5','Božím zámerom je, aby<br/>mojou nádejou bol Pán.<br/>Nie je sláva to navonok,<br/>ale Kristus Ježiš Sám.<br/>',NULL,129969,6);
INSERT INTO stanza VALUES('SK538','6','Božím zámerom je, aby<br/>Kristus bol vo mne všetkým.<br/>Nemať len vonkajšie veci,<br/>ale Krista naveky.<br/>',NULL,129970,7);
INSERT INTO stanza VALUES('SK539','1','Si môj život, Pane drahý,<br/>ako všetko Ťa mám!<br/>Si osobný a prístupný,<br/>takého Ťa poznám.<br/>',NULL,129971,1);
INSERT INTO stanza VALUES('SK539','chorus','Ó, Pane, Ty si Duchom!<br/>Mne blízky a drahý!<br/>Tak veľmi sa teším z toho,<br/>že si dnes prístupný!<br/>',NULL,129972,2);
INSERT INTO stanza VALUES('SK539','2','Všetky potreby, ktoré mám,<br/>hojne zaopatríš,<br/>pripravený, dostatočný<br/>sa stále uplatníš.<br/>',NULL,129973,3);
INSERT INTO stanza VALUES('SK539','3','Sladké pomazanie s mocou<br/>v slabostiach podrží,<br/>zdrojom Svojej energie<br/>mi silu udržíš.<br/>',NULL,129974,4);
INSERT INTO stanza VALUES('SK539','4','V mysli mám zákon života,<br/>ten ma usmerňuje,<br/>hojnosť Tvojej skutočnosti<br/>srdce nasycuje.<br/>',NULL,129975,5);
INSERT INTO stanza VALUES('SK539','5','Ó, stále si so mnou jedno,<br/>pevne zjednotený!<br/>Vždy si so mnou jedným duchom<br/>a budeš naveky!<br/>',NULL,129976,6);
INSERT INTO stanza VALUES('SK540','1','Spasiteľ ma vyslobodil!<br/>Kristus ma oslobodil!<br/>Sila hriechu je zlomená,<br/>osteň hriechu sa stratil!<br/>',NULL,129977,1);
INSERT INTO stanza VALUES('SK540','chorus','Viac než víťaz v Pánovi som,<br/>skrze víťazstvo Jeho,<br/>z ducha sila zmŕtvychvstania<br/>upevňuje ma z neho.<br/>',NULL,129978,2);
INSERT INTO stanza VALUES('SK540','2','Oslobodil od zákona,<br/>mŕtvy som požiadavkám.<br/>Už ma nikdy viac nezviažu,<br/>len milosťou žiť budem.<br/>',NULL,129979,3);
INSERT INTO stanza VALUES('SK540','3','Pán odsúdil hriech na kríži,<br/>a odstránil moc jeho.<br/>Tak nemá už vo mne miesto,<br/>som slobodný od neho.<br/>',NULL,129980,4);
INSERT INTO stanza VALUES('SK540','4','Zrušil smrť a zjavil život,<br/>život neskaziteľný.<br/>On zlomil okovy smrti,<br/>dal nám život vzkriesený.<br/>',NULL,129981,5);
INSERT INTO stanza VALUES('SK540','5','Kristus zničil diabla smrťou,<br/>svet aj démonov mocou.<br/>Z temnoty ma preniesol tam,<br/>kde je život a svetlo.<br/>',NULL,129982,6);
INSERT INTO stanza VALUES('SK540','6','Milosť dáva dostatočnú,<br/>On stará sa sám Sebou,<br/>ak slabý som, podporuje,<br/>upevňuje ma Sebou.<br/>',NULL,129983,7);
INSERT INTO stanza VALUES('SK541','1','Zákon litery nie,<br/>ale Kristus Sám<br/>miesto našej snahy<br/>Bohom daný nám.<br/>Nie je to doktrína,<br/>ale Kristus Sám<br/>nás vyslobodzuje<br/>od hriešneho ja.<br/>',NULL,129984,1);
INSERT INTO stanza VALUES('SK541','2','Žiaden druh učenia,<br/>žiaden druh formy,<br/>neobživí ducha,<br/>dušu nezmení.<br/>Len Kristus ako Duch<br/>život dáva nám,<br/>aby žil životom<br/>božským skrze nás.<br/>',NULL,129985,2);
INSERT INTO stanza VALUES('SK541','3','Žiaden živel, žiadna<br/>filozofia<br/>nás nepripodobnia<br/>na obraz Krista.<br/>Je to iba Kristus,<br/>ktorý z nás činí<br/>údy Svojho Tela<br/>v Jeho vzkriesení.<br/>',NULL,129986,3);
INSERT INTO stanza VALUES('SK541','4','Žiadne náboženstvo,<br/>ani kresťanstvo,<br/>nenaplnia Božiu<br/>ekonómiu.<br/>Len Kristus, On v nás je,<br/>vo všetkom všetkým,<br/>všetky Božie priania<br/>On uspokojí.<br/>',NULL,129987,4);
INSERT INTO stanza VALUES('SK541','5','Všetky dary dané<br/>Pánom v milosti,<br/>rôzne funkcie Ho<br/>nesmú zameniť.<br/>Kristus nám musí byť<br/>vo všetkom všetkým!<br/>Sám Kristus musí byť<br/>vo veciach všetkých!<br/>',NULL,129988,5);
INSERT INTO stanza VALUES('SK542','1','Bohatstvá Spasiteľove<br/>nik nemôže vystihnúť,<br/>no zakúšať ich môžeme,<br/>plnosť Božstva úplnú.<br/>',NULL,129989,1);
INSERT INTO stanza VALUES('SK542','chorus','Bohatstvá, Svoje bohatstvá<br/>Spasiteľ môj pre mňa má!<br/>Miera nevystihnuteľná,<br/>skutočná však zúplna!<br/>',NULL,129990,2);
INSERT INTO stanza VALUES('SK542','2','Bohatstvá Spasiteľove:<br/>život a svetlo, sila,<br/>múdrosť, moc a utešenie,<br/>poklad Božieho srdca.<br/>',NULL,129991,3);
INSERT INTO stanza VALUES('SK542','3','Plná spása, vykúpenie,<br/>a moc Jeho vzkriesenia,<br/>posvätenie, oslávenie,<br/>stále ma zaopatria!<br/>',NULL,129992,4);
INSERT INTO stanza VALUES('SK542','4','Bohatstvá Spasiteľove –<br/>je to sám Boh, je všetkým!<br/>Čo vlastní, aj to, aký je,<br/>ducha môjho podmaní.<br/>',NULL,129993,5);
INSERT INTO stanza VALUES('SK542','5','Bohatstvá Spasiteľove!<br/>Šírku, dĺžku kto pozná?<br/>Hĺbku, výšku, sú nesmierne,<br/>no silu, radosť v nich mám.<br/>',NULL,129994,6);
INSERT INTO stanza VALUES('SK542','6','Bohatstvá Jeho nech poznám<br/>a zakúšam Krista v nich,<br/>so svätými spolu zdieľam<br/>obsah krásny, bohatý.<br/>',NULL,129995,7);
INSERT INTO stanza VALUES('SK546','1','Milujem Pána, nie vlastnou láskou,<br/>lebo takej nemám.<br/>Milujem Ťa, Pane, Tvojou láskou,<br/>vďaka nej život mám.<br/>Nie som ničím, preto som radostný,<br/>vyprázdnený a v Tebe stratený.<br/>',NULL,129996,1);
INSERT INTO stanza VALUES('SK546','2','Všetky Tvoje deti potrebujú<br/>iba Teba, Pane.<br/>Z Teba prúdy požehnania plynú,<br/>Ty máš požehnanie,<br/>milosť prehojnú, prameň života,<br/>zdrojom, stredom aj príbytkom si nám.<br/>',NULL,129997,2);
INSERT INTO stanza VALUES('SK547','1','Každé srdce niečo ľúbi,<br/>bez Pána pokoja niet.<br/>Tebe patrí moje srdce,<br/>Teba najviac miluje.<br/>',NULL,129998,1);
INSERT INTO stanza VALUES('SK547','2','Pre toto som odmietol svet,<br/>Ježiš je milovaný,<br/>zo všetkého najkrajší je,<br/>On sám radosťou je mi.<br/>',NULL,129999,2);
INSERT INTO stanza VALUES('SK547','3','Jas so všetkou večnou žiarou<br/>sláva Tvojej tváre je.<br/>Si nežný, súcitu plný,<br/>milostivý, miluješ.<br/>',NULL,130000,3);
INSERT INTO stanza VALUES('SK547','4','Pane, vždy si ma miloval<br/>a stále miluješ ma.<br/>Za mňa si Svoju krv vylial,<br/>či Ťa milovať nemám?<br/>',NULL,130001,4);
INSERT INTO stanza VALUES('SK547','5','Chráň moje srdce vždy verným,<br/>aby môj život zemský<br/>bol aspoň tieňom tej slávy,<br/>môjho života v Tebe.<br/>',NULL,130002,5);
INSERT INTO stanza VALUES('SK548','1','Som hlinenou nádobou,<br/>Pán je mojím pokladom,<br/>ja som Jeho nádobou,<br/>On je mojím obsahom.<br/>',NULL,130003,1);
INSERT INTO stanza VALUES('SK548','2','Aby Kristus vo mne žil,<br/>preto som bol stvorený,<br/>Bohom vyformovaný,<br/>nech je obsahom mojím.<br/>',NULL,130004,2);
INSERT INTO stanza VALUES('SK548','3','On žije v mojom duchu,<br/>udržiava ma silou<br/>ako Duch, jedno so mnou,<br/>je mojou skutočnosťou.<br/>',NULL,130005,3);
INSERT INTO stanza VALUES('SK548','4','Pohybuje sa vo mne,<br/>stále sa zmiešavame,<br/>kroky mi usmerňuje,<br/>každú časť nasycuje.<br/>',NULL,130006,4);
INSERT INTO stanza VALUES('SK548','5','Zvnútra vyjadrovaný,<br/>je inými videný,<br/>ja musím byť priezračný,<br/>nech je Pán prejavený.<br/>',NULL,130007,5);
INSERT INTO stanza VALUES('SK548','6','Premenu potrebujem,<br/>byť viacej prelomený,<br/>nech sa hlina premení,<br/>k pokladu pripodobní.<br/>',NULL,130008,6);
INSERT INTO stanza VALUES('SK549','1','Vstúp za oponu, mimo tábor choď,<br/>ochutnaj nebo, tým zem odvrhni.<br/>Ak Najsvätejší uspokojuje,<br/>účasť ako môžem mať na zemi?<br/>',NULL,130009,1);
INSERT INTO stanza VALUES('SK549','2','Vstúp za oponu, mimo tábor choď,<br/>prítomnosťou neba zem odíde.<br/>Ak sláva neba ducha očarí,<br/>ako môže zem ovládnuť srdce?<br/>',NULL,130010,2);
INSERT INTO stanza VALUES('SK549','3','Vstúp za oponu, mimo tábor choď,<br/>Pána nechaj viesť, hľaď len na Krista.<br/>Jasle a kríž ma zdržať nemôžu,<br/>ak tiahnu koruna a trón ducha.<br/>',NULL,130011,3);
INSERT INTO stanza VALUES('SK549','4','Vstúp za oponu, tam je vzkriesenie,<br/>choď mimo tábor; kríž, potupu niesť.<br/>Ak na Jeho tvár žiariacu hľadím,<br/>vtedy ma budú Jeho stopy viesť.<br/>',NULL,130012,4);
INSERT INTO stanza VALUES('SK549','5','Vstúp za oponu, na hostinu príď,<br/>v ťažkostiach mimo tábor vytrvaj.<br/>Skúšky keď aj moje srdce bolia,<br/>spoločenstvo neba teší ducha.<br/>',NULL,130013,5);
INSERT INTO stanza VALUES('SK549','6','Vstúp za oponu, Krista vychutnaj,<br/>zaopatruj tých mimo tábora.<br/>Nebeský život, ktorý prežívaš,<br/>bude zemské duše nasycovať.<br/>',NULL,130014,6);
INSERT INTO stanza VALUES('SK549','7','Vstupuj za oponu, kým nezmizne,<br/>z tábora von, kým všetky nezmiznú.<br/>Až kým sa spoja nebo so zemou,<br/>kým Boh a človek jedno nebudú.<br/>',NULL,130015,7);
INSERT INTO stanza VALUES('SK551','1','Chvála buď Baránkovi,<br/>správu som prijal dobrú!<br/>Prešiel som už nádvorím,<br/>ó, chvála buď Bohu!<br/>K Ježišovi som prešiel,<br/>na oltári som zhorel,<br/>svetu aj hriechu zomrel,<br/>chvála buď Baránkovi!<br/>',NULL,130016,1);
INSERT INTO stanza VALUES('SK551','chorus','Aleluja! Aleluja!<br/>Prešiel som za oponu,<br/>slávu Božiu nemennú.<br/>Aleluja! Aleluja!<br/>Dnes môžem žiť v prítomnosti<br/>Kráľovej.<br/>',NULL,130017,2);
INSERT INTO stanza VALUES('SK551','2','Chvála buď Baránkovi,<br/>kráľom aj kňazom Bohu!<br/>Som vďaka Jeho krvi,<br/>ó, chvála buď Bohu!<br/>Silou Ducha vo svetle<br/>žijem v Ňom neprestajne,<br/>na najsvätejšom mieste,<br/>chvála buď Baránkovi!<br/>',NULL,130018,3);
INSERT INTO stanza VALUES('SK551','3','Chvála buď Baránkovi,<br/>vstúpil som za oponu!<br/>Kde Božie svetlo žiari,<br/>ó, chvála buď Bohu!<br/>Jeho krv ma vpustila,<br/>je to Božia svätyňa,<br/>tu je koniec môjmu ja,<br/>chvála buď Baránkovi!<br/>',NULL,130019,4);
INSERT INTO stanza VALUES('SK551','4','Chvála buď Baránkovi,<br/>vstúpil som za oponu!<br/>Že som vo veľsvätyni,<br/>ó, chvála buď Bohu!<br/>Som Bohu zasvätený,<br/>mocou Pánovej krvi,<br/>dnes prebývam spolu s Ním,<br/>chvála buď Baránkovi!<br/>',NULL,130020,5);
INSERT INTO stanza VALUES('SK559','1','Ja dotýkam sa Ťa vierou,<br/>zdroj večný, Spasiteľ môj.<br/>Ja prosím tiež silu vierou<br/>skrz očistenie krvou.<br/>',NULL,130021,1);
INSERT INTO stanza VALUES('SK559','chorus','Ja dotýkam sa Ťa, Pane,<br/>a nový život planie.<br/>Čistí, páli, naplňuje,<br/>Tebe sláva naveky.<br/>',NULL,130022,2);
INSERT INTO stanza VALUES('SK559','2','Ja dotýkam sa vo viere,<br/>so všetkým Ťa prijímam,<br/>a otváram všetko, čo som,<br/>Ty mi dávaš, čím si sám.<br/>',NULL,130023,3);
INSERT INTO stanza VALUES('SK559','3','Žezla Tvojho sa dotýkam,<br/>kráľov Kráľ najmocnejší,<br/>z Tvojej plnosti prijímam,<br/>som na krídlach nesený.<br/>',NULL,130024,4);
INSERT INTO stanza VALUES('SK559','4','Milosť, múdrosť, sila a moc,<br/>Ty ma sám vyživuješ,<br/>nech som stále iba v Tebe,<br/>k tomu ma povzbudzuješ.<br/>',NULL,130025,5);
INSERT INTO stanza VALUES('SK564','1','Spoznal som tajomstvo krásne<br/>v Pánovi prebývania,<br/>okúsil som živý prameň,<br/>tak pijem z Jeho slova.<br/>Nachádzam silu a sladkosť,<br/>ak zostávam pod krvou,<br/>stratil som sa v Ježišovi,<br/>ponáram sa do Neho.<br/>',NULL,130026,1);
INSERT INTO stanza VALUES('SK564','chorus','V Pánovi ja zostávam,<br/>v Jeho slovo vieru mám,<br/>v náručí Jeho lásky som ukrytý.<br/>Áno, v Ňom ja zostávam,<br/>v Jeho slovo vieru mám,<br/>v náručí Jeho lásky som ukrytý.<br/>',NULL,130027,2);
INSERT INTO stanza VALUES('SK564','2','S Pánom som ukrižovaný,<br/>On prebýva vždy so mnou.<br/>Zanechal som svoje snahy,<br/>už viac nie ja, ale On.<br/>Moja vôľa sa poddala,<br/>vnútri vládne Jeho Duch,<br/>Jeho krv čistým drží ma,<br/>slobodným, mimo hriechu.<br/>',NULL,130028,3);
INSERT INTO stanza VALUES('SK564','3','Ja Mu prinášam nemoci,<br/>On ich všetky berie preč.<br/>vravím Mu o všetkých svojich<br/>starostiach zo dňa na deň.<br/>Jeho dychom kráčam, žijem,<br/>z Ježiša beriem silu.<br/>On mi dáva Svoju myseľ,<br/>život, lásku a vieru.<br/>',NULL,130029,4);
INSERT INTO stanza VALUES('SK564','4','Jeho Slovo mám na múdrosť,<br/>Duch na prácu silu dá,<br/>na cesty Jeho prítomnosť,<br/>tá ma chráni, vedie ma.<br/>On je môjho srdca podiel,<br/>trvalou radosťou Sám,<br/>Spasiteľ a Posvätiteľ,<br/>Pán, prichádzajúci Kráľ.<br/>',NULL,130030,5);
INSERT INTO stanza VALUES('SK578','1','Vôľa slabá, sila krehká,<br/>nádej rozplýva sa moja.<br/>Čo môžem? Len sa spoliehať,<br/>že aj ďalej povedieš ma.<br/>',NULL,130031,1);
INSERT INTO stanza VALUES('SK578','2','Stále zlyhám, hoc sa snažím,<br/>som rovnaký ako predtým.<br/>Ty si so mnou trpezlivý,<br/>Ty ma držíš Slovom Svojím.<br/>',NULL,130032,2);
INSERT INTO stanza VALUES('SK578','3','Keď sa v srdci vyvyšujem,<br/>som veľmi blízko pádu, viem.<br/>Myslieť sa neodvažujem,<br/>vo všetkom Ťa potrebujem.<br/>',NULL,130033,3);
INSERT INTO stanza VALUES('SK578','4','Spasiteľ môj, sila, pevnosť,<br/>Pane, hľadám len Tvoju tvár.<br/>Hoc najslabší som zo slabých,<br/>silou mi je milosť Tvoja.<br/>',NULL,130034,4);
INSERT INTO stanza VALUES('SK593','1','Máme iba hriech a smrť v Adamovi,<br/>avšak život, spravodlivosť v Kristovi.<br/>Ak v tele zostávam, Adam sa zjaví,<br/>avšak keď som v duchu, Krista prejavím.<br/>',NULL,130035,1);
INSERT INTO stanza VALUES('SK593','2','Ak som v Adamovi, hoc aj nehreším,<br/>hriešnik som a to, čo mám je trest smrti.<br/>V Kristu nežijem svoju spravodlivosť,<br/>ak som v Ňom, On je moja spravodlivosť.<br/>',NULL,130036,2);
INSERT INTO stanza VALUES('SK593','3','V tele len vyjadrujem svoju hriešnosť,<br/>bez úsilia Adama, prirodzenosť.<br/>V duchu nemusím sa snažiť, zápasiť,<br/>v duchu môžem kraľovať, ako On žiť.<br/>',NULL,130037,3);
INSERT INTO stanza VALUES('SK593','4','Smrťou s Kristom som od Adama voľný,<br/>životom s Kristom tak mám život nový.<br/>Bez mysle tela Adam miesto nemá,<br/>život božský zjavujem mysľou ducha.<br/>',NULL,130038,4);
INSERT INTO stanza VALUES('SK593','5','Upnúť myseľ k duchu je Božia cesta,<br/>myseľ na duchu nám zjavuje Krista.<br/>Mysľou na duchu víťaziť môžeme<br/>a mysľou na duchu bežať môžeme.<br/>',NULL,130039,5);
INSERT INTO stanza VALUES('SK593','6','Mysľou na duchu tiež kríž poznávame,<br/>moc Jeho vzkriesenia cez nás poplynie.<br/>Pán žiť skrze mňa mysľou ducha bude,<br/>Jeho život vo mne zrelosť dosiahne.<br/>',NULL,130040,6);
INSERT INTO stanza VALUES('SK593','7','Život aj všetko Pán v duchu pre mňa je,<br/>neustále žehná a posilňuje.<br/>Zakúšam svätosť, pokiaľ v duchu žijem,<br/>sám Trojjediný Boh sa hýbe vo mne.<br/>',NULL,130041,7);
INSERT INTO stanza VALUES('SK600','1','Môj Boh, môj údel, láska tiež,<br/>ó, Ty si mi všetkým,<br/>nemám iného, Teba len,<br/>v nebi, aj na zemi.<br/>v nebi, aj na zemi.<br/>',NULL,130042,1);
INSERT INTO stanza VALUES('SK600','2','Pusté sú tieto nebesá<br/>aj všetko na zemi,<br/>niet radosti okrem Teba,<br/>nič nie je ako Ty.<br/>nič nie je ako Ty.<br/>',NULL,130043,2);
INSERT INTO stanza VALUES('SK600','3','Tebe za priateľov vďačím,<br/>za zdravie aj za dom,<br/>za všetky veci vďaka Ti,<br/>no oni nie sú Boh.<br/>no oni nie sú Boh.<br/>',NULL,130044,3);
INSERT INTO stanza VALUES('SK600','4','Aké je márne bohatstvo,<br/>keď s Tebou porovnám!<br/>Čo sú istoty, čo zdravie?<br/>Čo sú mi priatelia?<br/>Čo sú mi priatelia?<br/>',NULL,130045,4);
INSERT INTO stanza VALUES('SK600','5','Aj keby mi patrila zem<br/>alebo aj hviezdy,<br/>bez Teba, milosti Tvojej<br/>bol by som nešťastný.<br/>bol by som nešťastný.<br/>',NULL,130046,5);
INSERT INTO stanza VALUES('SK600','6','Nech si iní ako more<br/>chcú všetko pohltiť,<br/>daruj mi Svoju milosť len,<br/>neprajem si viac nič.<br/>neprajem si viac nič.<br/>',NULL,130047,6);
INSERT INTO stanza VALUES('SK602','1','Ó, je slávne, je to sväté!<br/>Náš Boh večný život je!<br/>Nekonečný, mocný, plný,<br/>čistý, milostivý je!<br/>Božia plnosť, prirodzenosť,<br/>láska a svetlo v Ňom je!<br/>',NULL,130048,1);
INSERT INTO stanza VALUES('SK602','2','Láskyplné, milostivé!<br/>Boh – život pre človeka!<br/>Utvoril v človeku ducha,<br/>’by uskutočnil Svoj plán.<br/>Záľubu má a tiež túžbu,<br/>aby Ho človek prijal.<br/>',NULL,130049,2);
INSERT INTO stanza VALUES('SK602','3','Láska a milosť nesmierna!<br/>Boh do človeka prúdi!<br/>Nie je viac tajomstvom skrytým,<br/>je človeku zjavený.<br/>Prišiel v tele, stal sa Duchom,<br/>aby sme Ho poznali.<br/>',NULL,130050,3);
INSERT INTO stanza VALUES('SK602','4','Dosiahnuteľný a blízky!<br/>Je pre nás Boh v Kristovi!<br/>Boh je v Kristovi vtelený,<br/>’by Ho ľudia videli.<br/>Kristus zomrel a vstal z mŕtvych,<br/>Svoj život nám udelil.<br/>',NULL,130051,4);
INSERT INTO stanza VALUES('SK602','5','Čo za zázrak! Boh ako Duch<br/>je životom v človeku!<br/>Skrze proces, ktorým prešiel<br/>je nám známy ako Duch.<br/>Usvedčuje, motivuje,<br/>Svoj dom si činí v ľuďoch.<br/>',NULL,130052,5);
INSERT INTO stanza VALUES('SK602','6','Ó, je slávne takto poznať<br/>Trojjediného Boha!<br/>Otec k nám v Synovi prišiel,<br/>Syn ako Duch prúdi k nám.<br/>Keď do človeka vstúpi Duch,<br/>Boha ako život dá.<br/>',NULL,130053,6);
INSERT INTO stanza VALUES('SK602','7','Je tajomné, no skutočné,<br/>Boh teraz vo mne prúdi!<br/>V mojom srdci som jedno s Ním,<br/>On je životom mojím.<br/>Aleluja! Aleluja!<br/>Chválim Ho tak naveky!<br/>',NULL,130054,7);
INSERT INTO stanza VALUES('SK608','1','Je tajomstvom, že Otec, Syn a Duch sú<br/>tri osoby, však jednej podstaty.<br/>Ten Boh do nášho vnútra vstúpil, sláva,<br/>cez Ducha nám je v Synovi všetkým!<br/>',NULL,130055,1);
INSERT INTO stanza VALUES('SK608','chorus','Stal sa pre nás všetkým Trojjediný!<br/>Je to skvelé! Prenádherné!<br/>Je dar božský, nevyčerpateľný!<br/>Znamenité a úžasné!<br/>',NULL,130056,2);
INSERT INTO stanza VALUES('SK608','2','Zdroj bohatý Otec ako prameň je,<br/>’by vychutnával Ho človek, On chce!<br/>Požehnaním veľkým tento podiel je,<br/>z Neho čerpať naveky budeme!<br/>',NULL,130057,3);
INSERT INTO stanza VALUES('SK608','3','Znamenité, Syn - Otca vyjadrenie,<br/>prišiel v tele, ’by prebýval s ľuďmi!<br/>Našu vinu zotrelo vykúpenie,<br/>hriešnici jedno s Bohom môžu byť.<br/>',NULL,130058,4);
INSERT INTO stanza VALUES('SK608','4','Syn sa stal tým Duchom oživujúcim,<br/>’by človeku Svoj život udelil.<br/>Fakt úžasný, náš duch sa s Duchom zmiešal<br/>a jednota vzniká tým spojením!<br/>',NULL,130059,5);
INSERT INTO stanza VALUES('SK608','5','Je skutočné, že Boh je teraz Duchom,<br/>môžeme Ho prežívať každý deň!<br/>Fakt úžasný, sme jedným duchom s Bohom,<br/>v živote v nás žiaden rozdiel nie je!<br/>',NULL,130060,6);
INSERT INTO stanza VALUES('SK610','1','Boží Duch je prenos Boha,<br/>v Duchu do nás Boh vstupuje.<br/>Boha v Kristovi len v Duchu<br/>všetci zakúšať môžeme.<br/>',NULL,130061,1);
INSERT INTO stanza VALUES('SK610','2','Boh ako Otec je zdrojom<br/>a Boh Syn Otca vyjadrí,<br/>Boh ako Duch nás naplní,<br/>aby bol Boh pre nás všetkým.<br/>',NULL,130062,2);
INSERT INTO stanza VALUES('SK610','3','Otec v svetle zahalený,<br/>Syn je ľuďom odhalený,<br/>Duchom do nás prenášaný,<br/>nami je vnútri poznaný.<br/>',NULL,130063,3);
INSERT INTO stanza VALUES('SK610','4','Syn sa nachádza v Otcovi,<br/>a tento Syn je dnes Duchom.<br/>Ten Duch, aj Syn, aj Boh Otec<br/>sú v nás a sú s nami jedno.<br/>',NULL,130064,4);
INSERT INTO stanza VALUES('SK610','5','Boh ako Otec v Synovi<br/>stelesnený, vyjadrený.<br/>Boh Duch je skutočnosť Syna,<br/>’by sme si Ho privlastnili.<br/>',NULL,130065,5);
INSERT INTO stanza VALUES('SK610','6','Nech známe lásku Otcovu<br/>v Bohu Synu, je milosťou,<br/>spoločenstvom Boha Ducha,<br/>Boh bude naším podielom.<br/>',NULL,130066,6);
INSERT INTO stanza VALUES('SK612','1','Stále ma Sebou samým chce<br/>Boh zaopatriť.<br/>S Ním musím mať zjednotenie,<br/>v duchu byť.<br/>',NULL,130067,1);
INSERT INTO stanza VALUES('SK612','chorus','Božie bohatstvá, aj čím je,<br/>v Duchu preteká.<br/>Svojho ducha uplatňujem,<br/>tým Ho poznám.<br/>',NULL,130068,2);
INSERT INTO stanza VALUES('SK612','2','Dáva mi Seba samého,<br/>všetko čím je sám.<br/>Uplatnením ducha sa Ho<br/>dotýkam.<br/>',NULL,130069,3);
INSERT INTO stanza VALUES('SK612','3','Môžeme Ho mysľou chápať,<br/>duchom sa dotknúť.<br/>Tí, čo ducha neuplatnia,<br/>strácajú.<br/>',NULL,130070,4);
INSERT INTO stanza VALUES('SK612','4','Vnímam posolstvá, musím ich<br/>vmodliť do seba.<br/>Slovo takto v mojom vnútri<br/>strávi sa.<br/>',NULL,130071,5);
INSERT INTO stanza VALUES('SK612','5','Pána sa musím dotýkať,<br/>keď Ho študujem.<br/>Slovo len v mysli, nie v duchu,<br/>nežije.<br/>',NULL,130072,6);
INSERT INTO stanza VALUES('SK612','6','Vzácne bohatstvá a sláva<br/>čo žiaria v Duchu.<br/>Pokiaľ ducha používam,<br/>moje sú.<br/>',NULL,130073,7);
INSERT INTO stanza VALUES('SK622','1','Ak vezmeme svoj kríž, budeme len trpieť?<br/>Nie, ak nesieme svoj kríž, iste umrieme!<br/>Významom kríža je naše ukončenie,<br/>kríž, ak zakúšame, „ja“ ukrižujeme.<br/>',NULL,130074,1);
INSERT INTO stanza VALUES('SK622','2','Kríž nás zabíja, oslobodenie veľké,<br/>hoc sa to zdá kruté, len kríž nás uvoľní.<br/>Bez kríža Kristus nemôže byť život náš,<br/>ak neumrieme, nebude vyjadrený.<br/>',NULL,130075,2);
INSERT INTO stanza VALUES('SK622','3','Kríža cieľom je Božiu vôľu naplniť,<br/>jej najväčším nepriateľom je moje „ja“.<br/>Len ak bude život duše usmrtený,<br/>môže byť vôľa Božia uskutočnená.<br/>',NULL,130076,3);
INSERT INTO stanza VALUES('SK626','1','Olivy, čo tlak neznali,<br/>olej nedajú.<br/>Z hrozna, čo sa lisu stráni,<br/>vína z neho nemajú!<br/>Nard musí byť rozdrvený,<br/>’by vôňu vydal.<br/>Cúvnuť mám pred utrpením,<br/>čo si mi Pane vybral?<br/>',NULL,130077,1);
INSERT INTO stanza VALUES('SK626','chorus','Všetko, čo znášam,<br/>ziskom je pre mňa.<br/>Namiesto toho, čo strácam,<br/>dávaš mi viacej Seba.<br/>',NULL,130078,2);
INSERT INTO stanza VALUES('SK626','2','Strunu srdca, aby znela,<br/>či mi naladíš?<br/>Aby sladká hudba húdla,<br/>či ma láskou preliečiš?<br/>Pane, strate sa nebránim,<br/>ak vedie k Tebe,<br/>úplne sa Ti podriadim,<br/>srdce Tvoje chcem celé.<br/>',NULL,130079,3);
INSERT INTO stanza VALUES('SK626','3','že chránim seba.<br/>Hoc pôsobíš Svojou láskou,<br/>stále ochotu nemám.<br/>Podľa Svojho potešenia,<br/>viac na mne pracuj,<br/>na svoje pocity nedbám,<br/>rob to, v čom máš záľubu.<br/>',NULL,130080,4);
INSERT INTO stanza VALUES('SK626','4','Ak by som proti Tebe stál,<br/>vždy konaj Svoje,<br/>čo Ťa teší, ak aj mám žiaľ,<br/>„áno“ Ti srdce povie.<br/>Ak by som aj niečo strácal,<br/>chcem Ťa potešiť,<br/>hoc by Tvoja radosť, sláva<br/>znamenali znášať kríž.<br/>',NULL,130081,5);
INSERT INTO stanza VALUES('SK626','5','Pane, vždy Ťa piesňou chválim,<br/>hoc zo slzami.<br/>Spievam, sladší a sladší Si,<br/>ó, vďačnými chválami.<br/>Vzácnejší si, Pane, pre mňa,<br/>než všetko iné,<br/>rásť musíš, ja sa zmenšovať,<br/>mám len prianie jediné.<br/>',NULL,130082,6);
INSERT INTO stanza VALUES('SK631','1','Stále musím kríž milovať,<br/>tým moc vzkriesenia poznať.<br/>len smrťou povstáva život,<br/>strácať znamená získať.<br/>',NULL,130083,1);
INSERT INTO stanza VALUES('SK631','chorus','Ak nezomrieme,<br/>život nebude.<br/>život vzkriesenia povstáva,<br/>len ak zomrieme.<br/>',NULL,130084,2);
INSERT INTO stanza VALUES('SK631','2','Kristus bude stvárňovaný,<br/>len ak navždy vydýchnem.<br/>ak budem žiť v tieni kríža,<br/>život duše umŕtvim.<br/>',NULL,130085,3);
INSERT INTO stanza VALUES('SK631','3','Ak ma Boh večným Duchom dnes<br/>s Pánom na kríž položí.<br/>Jeho život prúdiť bude,<br/>stále keď smrť pôsobí.<br/>',NULL,130086,4);
INSERT INTO stanza VALUES('SK635','1','Uvažujme o viniči,<br/>poučme sa od neho,<br/>jeho rast je strastiplný<br/>v prostredí nehostinnom.<br/>Nie ako kvety neskrotné,<br/>rastie na mieste pustom,<br/>v bludisku, kde len zmätok je,<br/>v mnohom nám je príkladom.<br/>',NULL,130087,1);
INSERT INTO stanza VALUES('SK635','2','Kvety tejto vínnej révy<br/>sú bez slávy, maličké,<br/>istý výraz aj keď majú,<br/>je ťažké ich uvidieť.<br/>Odo dňa, keď dorastajú,<br/>stáva sa z nich ovocie,<br/>nikdy okvetím nevanú,<br/>krása ich sa nezaskvie.<br/>',NULL,130088,2);
INSERT INTO stanza VALUES('SK635','3','Na drôtenke uviazaný,<br/>nemôže si voľne rásť,<br/>keď sa zväčšia letorasty,<br/>len popri nej sa ťahá.<br/>V tvrdej pôde zasadený,<br/>z nej čerpá ’by mohol rásť,<br/>vlastné cesty si nevolí,<br/>z ťažkostí neuniká.<br/>',NULL,130089,3);
INSERT INTO stanza VALUES('SK635','4','Vinič má prekrásnu zeleň,<br/>na jar sa poľom tiahne,<br/>sila a plnosť života<br/>spôsobuje, že rastie.<br/>Až plný je letorastov,<br/>všade sa rozpínajú,<br/>až k azúrovej oblohe,<br/>vzduch si vychutnávajú.<br/>',NULL,130090,4);
INSERT INTO stanza VALUES('SK635','5','Avšak Pán vinice nie je<br/>k viniču zhovievavý,<br/>orezáva, obstrihuje,<br/>celej pýchy ho zbaví.<br/>Pán nedbá o jeho nehu,<br/>no presnými zásahmi<br/>orezáva tie, ktoré sú<br/>pridlhými vetvami.<br/>',NULL,130091,5);
INSERT INTO stanza VALUES('SK635','6','Mal by sa vinič ľutovať<br/>v období takýchto strát?<br/>Nie, no viacej sa odovzdať<br/>tomu, čo ho chce strihať.<br/>Do tých rúk, čo skrátia vetvy,<br/>zbavený nech krásy je,<br/>aby neostal neplodný,<br/>no prinášal ovocie.<br/>',NULL,130092,6);
INSERT INTO stanza VALUES('SK635','7','Na tvrdé drevo pomaly<br/>sa každý kmeň premení.<br/>Každý prút, ktorý ostane,<br/>strapcom bude bohatým.<br/>Listy pod horúcim slnkom<br/>vyschnú a opadajú,<br/>plody tak budú hojnejšie,<br/>potom ich pozbierajú.<br/>',NULL,130093,7);
INSERT INTO stanza VALUES('SK635','8','Vetvy má k zemi ohnuté,<br/>sú pod váhou ovocia –<br/>vinič rástol utrpením,<br/>museli ho orezať.<br/>Teraz má zrelé ovocie,<br/>mohol by byť spokojný,<br/>žatva sa však rýchle blíži,<br/>potešenie uletí.<br/>',NULL,130094,8);
INSERT INTO stanza VALUES('SK635','9','Oberú a šliapať budú<br/>po bohatstve viniča,<br/>až kým rieka vína plná,<br/>z neho bude vytekať.<br/>Rieka plynie po celý deň,<br/>červená, bez prímesí,<br/>prúdi voľne a bohate,<br/>zem radosťou naplní.<br/>',NULL,130095,9);
INSERT INTO stanza VALUES('SK635','10','Vinič potom nie je krásny,<br/>no planý, zúbožený.<br/>Vydal zo seba to, čo mal,<br/>už vstupuje do noci.<br/>Za to víno, čo sa pije,<br/>mu nikto nezaplatí,<br/>naopak, ešte ho skrátia,<br/>nie je z neho takmer nič.<br/>',NULL,130096,10);
INSERT INTO stanza VALUES('SK635','11','Avšak jeho víno v zime<br/>zohrieva a je sladké<br/>tým, ktorí sa zimou trasú,<br/>majú bolesť súženie.<br/>Vinič ostal v snehu, v zime,<br/>sám je a opustený,<br/>aj keď sa to ťažko chápe,<br/>je veľmi neochvejný.<br/>',NULL,130097,11);
INSERT INTO stanza VALUES('SK635','12','Zima prešla, vinič môže<br/>znovu priniesť ovocie,<br/>začne pučať, začne vzrastať,<br/>v nádheru sa oblečie.<br/>Nesťažuje sa, nešomre,<br/>zimu neobviňuje.<br/>Prišiel síce o všetko, no<br/>nestratil zasvätenie.<br/>',NULL,130098,12);
INSERT INTO stanza VALUES('SK635','13','Nebeský, čistý vzduch dýcha,<br/>ruky dvíha k nebesiam,<br/>o emócie nečisté<br/>pozemské sa nestará.<br/>Obeť znáša, usmieva sa,<br/>aj keď súženiu čelí,<br/>rany znáša, ako keby<br/>netrpel nikdy predtým.<br/>',NULL,130099,13);
INSERT INTO stanza VALUES('SK635','14','Zo všetkých vetiev viniča,<br/>krv a víno vyteká.<br/>Vari pre to, čím si prešiel,<br/>chudobnejšie vyzerá?<br/>Opilci a vandrovníci<br/>ho pijú a sú šťastní.<br/>Vari z tohto opojenia<br/>zobudia sa bohatší?<br/>',NULL,130100,14);
INSERT INTO stanza VALUES('SK635','15','Život náš, ten sa nemeria<br/>ziskom, ale stratami,<br/>ó, nie vínom, čo sme pili,<br/>ale vínom vyliatym.<br/>Sila lásky v tom spočíva,<br/>koľko kto obetuje,<br/>kto najviac utrpení má,<br/>najviacej vždy daruje.<br/>',NULL,130101,15);
INSERT INTO stanza VALUES('SK635','16','Len ten, kto sa neľutuje,<br/>bude Bohom získaný,<br/>len taký vie potešovať<br/>tých, ktorí sú v súžení.<br/>Ten, kto útrapy neznášal,<br/>iba prázdnym sudom je,<br/>ten, kto seba neľutoval,<br/>ten sa stále raduje.<br/>',NULL,130102,16);
INSERT INTO stanza VALUES('SK639','1','Neudrží smrť život vzkriesenia,<br/>nám sa zjavil život Boha večný.<br/>nestvorený, neporušiteľný,<br/>ním je Kristus, neporaziteľný.<br/>',NULL,130103,1);
INSERT INTO stanza VALUES('SK639','2','Neudrží smrť život vzkriesenia,<br/>aj keď si všetky sily pozbiera.<br/>smrť iba príležitosť môže dať,<br/>aby božský život prejavil sa.<br/>',NULL,130104,2);
INSERT INTO stanza VALUES('SK639','3','Neudrží smrť život vzkriesenia,<br/>smrť tento život iba znásobí.<br/>rásť mu pomáhajú utrpenia,<br/>prinášať hojné života plody.<br/>',NULL,130105,3);
INSERT INTO stanza VALUES('SK639','4','Neudrží smrť život vzkriesenia,<br/>život prekážky prekoná všetky.<br/>silu temna a pekla porazí,<br/>smrť pohltí, zvíťazí nad všetkým.<br/>',NULL,130106,4);
INSERT INTO stanza VALUES('SK639','5','Neudrží smrť život vzkriesenia,<br/>v ňom sa zjaví všetka plnosť Božia.<br/>Svätosť a spravodlivosť v ňom Božia,<br/>on vyjadrí slávny obraz Boží.<br/>',NULL,130107,5);
INSERT INTO stanza VALUES('SK639','6','Ó, nech poznám ten život vzkriesenia,<br/>tú silu vyliatu v každej smrti.<br/>vo svojom prežívaní chcem poznať,<br/>že život je Kristus, môj Pán živý.<br/>',NULL,130108,6);
INSERT INTO stanza VALUES('SK640','1','Život zo smrti – je pre dnešok, Pane,<br/>alebo niečo pre budúcnosť len?<br/>Nie! Prečo čakať?! Nádobu rozbitú<br/>nech už dnes Hrnčiar znova sformuje.<br/>',NULL,130109,1);
INSERT INTO stanza VALUES('SK640','2','Život zo smrti – úžasné vzkriesenie!<br/>Seje sa slabé, no vstáva mocné.<br/>Pánov život, čo prežívam v ťažkých dňoch,<br/>nežijem ja, ale Kristus vo mne.<br/>',NULL,130110,2);
INSERT INTO stanza VALUES('SK640','3','Život zo smrti – pútnickou cestou je,<br/>sú na nej tí, čo ich slávou je kríž.<br/>Tí v spoločenstve len s Ježišom žijú,<br/>všetko iné je len stratou pre nich.<br/>',NULL,130111,3);
INSERT INTO stanza VALUES('SK640','4','Život zo smrti – požehnané dielo,<br/>dávať tečúcu vodu života.<br/>Hojným životom z jasnej, čistej rieky,<br/>vravieť ľuďom, že žízniť nemusia.<br/>',NULL,130112,4);
INSERT INTO stanza VALUES('SK641','1','Či hladuješ po plnosti<br/>požehnania Kristovho?<br/>Túžiš sa učiť tajomstvu,<br/>ako žiť život Jeho?<br/>Odpoveď je v Jeho slove,<br/>je ňou: Kristus, život náš.<br/>otvor sa a dôveruj Mu,<br/>odteraz v Ňom zotrváš.<br/>',NULL,130113,1);
INSERT INTO stanza VALUES('SK641','2','Kristus, Pánov Pomazaný,<br/>zomrel, aby zvíťazil.<br/>Svoju silu zvonku, zvnútra<br/>stále viacej prejaví.<br/>Jeho Duch, ten uskutoční,<br/>čo je tebe nemožné,<br/>tvoja duša bude svedčiť:<br/>Nie ja, no Kristus vo mne.<br/>',NULL,130114,2);
INSERT INTO stanza VALUES('SK641','3','Božia plnosť v Ňom prebýva,<br/>v Ňom si aj ty úplný,<br/>vstaň, u Otca si uplatňuj<br/>právo prvorodených.<br/>Otec ťa nesklame nikdy,<br/>chváľ Ho, že ten dar je tvoj,<br/>je na všetko dostatočný,<br/>pokračuj, ži len z Neho.<br/>',NULL,130115,3);
INSERT INTO stanza VALUES('SK641','4','Prichádzam a odpočívam<br/>na Tvojom vernom slove,<br/>verím v očisťujúcu krv,<br/>aj že Kristus Pánom je.<br/>Nech Tvoj tok života, lásky<br/>stále prúdi cezo mňa,<br/>dosiahne sediacich vo tme,<br/>získa duše pre Teba.<br/>',NULL,130116,4);
INSERT INTO stanza VALUES('SK642','1','Za oponou je Pán tvojím podielom,<br/>aby si prebýval v skrytosti s Ním.<br/>Hľaď Naň, až kým tvoja tvár Jeho slávu,<br/>tvoj život Jeho lásku vyjadrí.<br/>',NULL,130117,1);
INSERT INTO stanza VALUES('SK642','2','Za oponou, len vtedy, keď hľadíš Naň,<br/>na Jeho nesmierne nádhernú tvár,<br/>len vtedy môžeš Jeho srdca lásky<br/>a milosti zjavenie živé mať.<br/>',NULL,130118,2);
INSERT INTO stanza VALUES('SK642','3','Za oponou Jeho arómu vnímam,<br/>pred oponou však žiadnej vône niet.<br/>On však ladí za oponou pieseň, čo<br/>Pánovi na chválu po zemi znie.<br/>',NULL,130119,3);
INSERT INTO stanza VALUES('SK642','4','Za oponou ak duch je zakotvený,<br/>nad svetom kráčať budeš v tichosti.<br/>za oponou si jednej duše s Pánom<br/>a žiješ na zemi vo vzkriesení.<br/>',NULL,130120,4);
INSERT INTO stanza VALUES('SK643','1','Buď s Pánom, hľaď Naňho,<br/>často s Ním hovor,<br/>stále v Ňom prebývaj<br/>a sýť sa slovom.<br/>Buď mierny, poddajný,<br/>očakávaj v Ňom.<br/>Jeho požehnanie<br/>hľadaj vo všetkom.<br/>',NULL,130121,1);
INSERT INTO stanza VALUES('SK643','2','Buď s Pánom, hľaď Naňho,<br/>nech sa svet ženie.<br/>často buď s Ježišom,<br/>len osamote.<br/>Hľadiac na Ježiša<br/>budeš ako On.<br/>tak v tebe priatelia<br/>uvidia Jeho.<br/>',NULL,130122,2);
INSERT INTO stanza VALUES('SK643','3','Buď s Pánom, hľaď Naňho,<br/>nech ťa vedie On.<br/>čokoľvek sa deje<br/>nepredbiehaj Ho.<br/>V šťastí aj v bolesti<br/>Ho vždy nasleduj.<br/>hľadiac na Ježiša<br/>slovu dôveruj.<br/>',NULL,130123,3);
INSERT INTO stanza VALUES('SK643','4','Buď s Pánom, hľaď Naňho,<br/>utíš si dušu.<br/>myšlienky, nálady<br/>podriaďuj Jemu.<br/>Jeho Duch povedie<br/>k lásky prameňom.<br/>tak prejavíš Jeho<br/>milosrdenstvo.<br/>',NULL,130124,4);
INSERT INTO stanza VALUES('SK656','1','Pána zvažuj, príklad si ber z Krista,<br/>uvedom si, že ťa celkom získal.<br/>Dal ti vlastný život, silu božskú,<br/>’by mal z teba prekrásnu nádobu.<br/>',NULL,130125,1);
INSERT INTO stanza VALUES('SK656','2','Vážim si Pána stále, deň, čo deň,<br/>na najskromnejšom mieste zostanem.<br/>To, kým som ja, nie je dôležité,<br/>nech je meno Otca oslávené.<br/>',NULL,130126,2);
INSERT INTO stanza VALUES('SK656','3','Ó, si Božie dieťa, tak neustúp,<br/>do Ježišovej smrti smelo vstúp,<br/>silu večného života spoznáš,<br/>voľnosť od hriechu, od svojho ja máš.<br/>',NULL,130127,3);
INSERT INTO stanza VALUES('SK656','4','Pána zvažuj, budeš naplnený,<br/>očistený, Jemu odovzdaný,<br/>Boh do teba vpracuje vzor pravý,<br/>príklad Kristov maj vždy pred očami.<br/>',NULL,130128,4);
INSERT INTO stanza VALUES('SK656','5','Pána zvažuj, ak zatiaľ čo bežíš,<br/>ustavične na Jeho tvár hľadíš,<br/>budeš premenený, osvietený,<br/>Kristov obraz bude z teba žiariť.<br/>',NULL,130129,5);
INSERT INTO stanza VALUES('SK710','1','Dni môžu byť temnejšie,<br/>noci únavnejšie,<br/>Ježiš sa zdržať môže,<br/>no jedno iste viem,<br/>že vzácnejší mi bude<br/>a spoločenstvo s Ním<br/>sa stáva dôvernejším<br/>a sladším, vzájomným.<br/>',NULL,130130,1);
INSERT INTO stanza VALUES('SK710','2','Vyčkávame Drahého,<br/>Priateľa a Radosť!<br/>Túžime Ho privítať,<br/>čo ak je za rohom?<br/>Možno sa s Ním stretneme<br/>prv než sa deň skončí,<br/>začne sa odpočinok,<br/>budeme spokojní.<br/>',NULL,130131,2);
INSERT INTO stanza VALUES('SK717','1','Ó, v Pánovi sa radujme naveky,<br/>keď skúšky na nás doliehajú,<br/>keď súženie nás ako búrka chytí,<br/>sme tí, čo nekvília, spievajú.<br/>',NULL,130132,1);
INSERT INTO stanza VALUES('SK717','chorus','A tak sa radujme, vždy sa radujme,<br/>lepšie je spievať, ako len vzdychať.<br/>Lepšie je žiť, ako len umierať,<br/>tak sa naveky radujme.<br/>',NULL,130133,2);
INSERT INTO stanza VALUES('SK717','2','Ó, v Pánovi sa radujme naveky,<br/>keď šípy ten Zlý vystreľuje,<br/>Satan nebojí sa, keď kvílime my,<br/>nášho spevu báť vždy sa bude.<br/>',NULL,130134,3);
INSERT INTO stanza VALUES('SK717','3','Ó, v Pánovi sa naveky radujme,<br/>u nás ak sa snáď nemoc staví,<br/>nič nám nedodá toľko síl, radosť len,<br/>to je prameňom v uzdravení.<br/>',NULL,130135,4);
INSERT INTO stanza VALUES('SK723','1','Keď bremeno rastie, dá nám viac milosti,<br/>keď práce pribúda, zošle viac sily.<br/>Keď súžení viac dá, aj milosrdenstva,<br/>v rozmnožených skúškach pokoj rozmnoží.<br/>',NULL,130136,1);
INSERT INTO stanza VALUES('SK723','chorus','Jeho láska nemá hraníc, ani milosť.<br/>Človek nepozná Božej moci mieru,<br/>pretože z Jeho bohatstva v Ježišovi<br/>Boh dáva a dáva a dáva znovu.<br/>',NULL,130137,2);
INSERT INTO stanza VALUES('SK723','2','Keď sa vyčerpala naša vytrvalosť,<br/>keď energia došla na poludnie,<br/>keď prišli ku koncu všetky naše zdroje,<br/>vtedy začalo Otcovo dávanie.<br/>',NULL,130138,3);
INSERT INTO stanza VALUES('SK733','1','V záhrade Eden postavil<br/>Boh človeka pred dva stromy,<br/>strom života, strom poznania,<br/>Pána, Satana symboly.<br/>',NULL,130139,1);
INSERT INTO stanza VALUES('SK733','2','Strom života je stredobod<br/>večného plánu Božieho,<br/>aby človek prijal Boha<br/>v Kristovi ako život svoj.<br/>',NULL,130140,2);
INSERT INTO stanza VALUES('SK733','3','Strom poznania dobra a zla<br/>výstražným tónom varuje.<br/>Mimo Boha zdroj smrti je,<br/>ktokoľvek si ho vyberie.<br/>',NULL,130141,3);
INSERT INTO stanza VALUES('SK733','4','Ak človek je strom života,<br/>Boha sťa život obdrží,<br/>v kameň drahý sa premení,<br/>dosiahne zámer, cieľ Boží.<br/>',NULL,130142,4);
INSERT INTO stanza VALUES('SK733','5','Ak človek je strom poznania,<br/>Satan doň vstúpi, naplní<br/>ako hriech, vedie ho k smrti,<br/>’by nedosiahol cieľ Boží.<br/>',NULL,130143,5);
INSERT INTO stanza VALUES('SK733','6','To znamená, že iba Boh<br/>naším zdrojom života je,<br/>no budeme usmrtení,<br/>ak zdrojom nám je poznanie.<br/>',NULL,130144,6);
INSERT INTO stanza VALUES('SK733','7','Poznanie nám prináša smrť,<br/>môže sa zlým zdať, aj dobrým,<br/>všetko, čo je mimo Boha,<br/>je ovocím Satanovým.<br/>',NULL,130145,7);
INSERT INTO stanza VALUES('SK733','8','Nie len to zlé, no aj dobré,<br/>protikladné je Kristovi,<br/>nie iba zlého poznanie,<br/>dobro je proti Kristovi.<br/>',NULL,130146,8);
INSERT INTO stanza VALUES('SK733','9','Pane, uč nás len Teba mať,<br/>Tvojím životom sýtiť sa,<br/>dobra a zla sa nedotknúť,<br/>ničoho, čo nie si Ty sám.<br/>',NULL,130147,9);
INSERT INTO stanza VALUES('SK737','1','Život večný ústi<br/>do spoločenstva<br/>života a v Duchu,<br/>zachraňuje ma.<br/>',NULL,130148,1);
INSERT INTO stanza VALUES('SK737','2','Život večný ústi<br/>v prúdenie božské,<br/>s Pánom ako Duchom<br/>sa zmiešavame.<br/>',NULL,130149,2);
INSERT INTO stanza VALUES('SK737','3','Život v Duchu ústi<br/>do spoločenstva,<br/>spoločenstvo v Duchu,<br/>milosť nám dodá.<br/>',NULL,130150,3);
INSERT INTO stanza VALUES('SK737','4','Život dáva schopnosť<br/>mať spoločenstvo,<br/>spoločenstvo v Duchu<br/>nás vedie v svetlo.<br/>',NULL,130151,4);
INSERT INTO stanza VALUES('SK737','5','Očisťujeme sa,<br/>chránime si tok,<br/>vnútri pomazanie,<br/>prúdu výsledok.<br/>',NULL,130152,5);
INSERT INTO stanza VALUES('SK737','6','Prúd sa prehlbuje<br/>krížom Pánovým,<br/>prúd je povznesený<br/>Ducha dýchaním.<br/>',NULL,130153,6);
INSERT INTO stanza VALUES('SK737','7','Prúd nás uvoľňuje<br/>od hriešneho ja,<br/>prúd spoločenstva nás<br/>vnáša do Boha.<br/>',NULL,130154,7);
INSERT INTO stanza VALUES('SK741','1','K synovstvu nás predurčil Boh<br/>pred sveta založením,<br/>Duchom nás obrazu Syna<br/>postupne pripodobní,<br/>aby jednorodený Syn<br/>stal sa Prvorodeným<br/>a spolu s mnohými bratmi<br/>Boha plne vyjadril.<br/>',NULL,130155,1);
INSERT INTO stanza VALUES('SK741','2','Stali sme sa synmi Boha<br/>tým, že nás znovu zrodil,<br/>získanie prvorodenstva<br/>závisí od zrelosti.<br/>Životom novým, zrelosťou,<br/>synovstvo s Ním zdieľame,<br/>mierou plnosti postavy<br/>synovstvo ohlásime.<br/>',NULL,130156,2);
INSERT INTO stanza VALUES('SK741','3','Náš duch, aj duša, i telo<br/>musia ako Kristus byť.<br/>Slávneho až uvidíme,<br/>všetko sa to naplní.<br/>Vykúpením nášho tela<br/>sa synovstvo dokončí,<br/>zámer Boha naplníme,<br/>až nás celkom premení.<br/>',NULL,130157,3);
INSERT INTO stanza VALUES('SK741','4','Touto poslednou premenou<br/>sme celkom posvätení,<br/>Boh nás uvedie do slávy,<br/>so Synom stotožnených.<br/>Synovia Boží sa zjavia,<br/>na to stvorenie čaká,<br/>až sa otroctvo pominie,<br/>príde slávna sloboda.<br/>',NULL,130158,4);
INSERT INTO stanza VALUES('SK742','1','Človek je bytosť z troch častí<br/>s telom i dušou i duchom.<br/>’By večný zámer naplnil,<br/>aby bol Božím dedičstvom.<br/>',NULL,130159,1);
INSERT INTO stanza VALUES('SK742','2','Telo je časťou vonkajšou,<br/>aby ním človek vnímal svet,<br/>aby mohol žiť navonok<br/>a telesne sa vyjadriť.<br/>',NULL,130160,2);
INSERT INTO stanza VALUES('SK742','3','Duša je vnútornou časťou,<br/>samotným „ja“ človeka je,<br/>duša mu dáva seba vnem,<br/>sférou psychologickou je.<br/>',NULL,130161,3);
INSERT INTO stanza VALUES('SK742','4','Duch je najvnútornejšia časť,<br/>Pána môže duchom prijať.<br/>dáva človeku vnem Boha,<br/>svet ducha môže tak chápať.<br/>',NULL,130162,4);
INSERT INTO stanza VALUES('SK742','5','Tri časti sú vnútri duše,<br/>sú tam myseľ, city, vôľa.<br/>človeka sú to funkcie,<br/>aby vyjadriť mohol sa.<br/>',NULL,130163,5);
INSERT INTO stanza VALUES('SK742','6','Vnútri ducha človeka je<br/>svedomie, spoločenstvo a<br/>tiež intuícia, aby<br/>sme mohli uctievať Boha.<br/>',NULL,130164,6);
INSERT INTO stanza VALUES('SK742','7','Človek musí cvičiť dušu,<br/>rozhodovať, či Boha mať,<br/>duchom mať účasť na Bohu<br/>a telom Ho vyjadrovať.<br/>',NULL,130165,7);
INSERT INTO stanza VALUES('SK742','8','Duch človeka tak byť musí<br/>znovu narodený z Neho,<br/>ľudská duša premenená,<br/>tiež podobný bude telom.<br/>',NULL,130166,8);
INSERT INTO stanza VALUES('SK742','9','Takouto božskou prácou v nás<br/>vo všetkých našich troch častiach<br/>je človek s Pánom zmiešaný,<br/>Jeho vyjadrenie zdieľa.<br/>',NULL,130167,9);
INSERT INTO stanza VALUES('SK744','1','Vo vzťahu s Pánom potrebné<br/>je srdce správne mať,<br/>na bohatstvách Jeho by sme<br/>tak mohli účasť mať.<br/>',NULL,130168,1);
INSERT INTO stanza VALUES('SK744','2','Srdce čisté vo všetkom mať,<br/>myseľ zdravú, jasnú,<br/>o chvení, v bázni rozumieť<br/>tak srdcu Pánovmu.<br/>',NULL,130169,2);
INSERT INTO stanza VALUES('SK744','3','Srdce, čo vrúcne miluje,<br/>láskou zapálené,<br/>citmi svojimi stále je<br/>k Pánovi uprené.<br/>',NULL,130170,3);
INSERT INTO stanza VALUES('SK744','4','Nám poslušné srdce treba,<br/>vôľu podriadenú,<br/>čo je pružná, no tiež silná<br/>k Pánovmu zámeru.<br/>',NULL,130171,4);
INSERT INTO stanza VALUES('SK744','5','Srdce, čo neodsudzuje,<br/>pred Bohom správne je,<br/>svedomie má očistené,<br/>je krvou prikryté.<br/>',NULL,130172,5);
INSERT INTO stanza VALUES('SK744','6','Daj srdce nám také, Pane,<br/>pripojené k Tebe,<br/>na Tebe účasť mať, Pane,<br/>byť plnosťou Tebe.<br/>',NULL,130173,6);
INSERT INTO stanza VALUES('SK745','1','Pane, Ty si teraz Duchom,<br/>v našom duchu žiješ.<br/>dvaja duchovia sú jedným,<br/>tak zjednotení sme.<br/>',NULL,130174,1);
INSERT INTO stanza VALUES('SK745','2','Tvoj Duch spolu s naším duchom<br/>svedectvo nesie vždy,<br/>že Otca nášho sme deťmi,<br/>dedičmi Božími.<br/>',NULL,130175,2);
INSERT INTO stanza VALUES('SK745','3','V duchu Ťa vychutnávame,<br/>sme s Tebou spojení.<br/>Ty ako Duch vkladáš do nás<br/>Seba bez prímesí.<br/>',NULL,130176,3);
INSERT INTO stanza VALUES('SK745','4','V našom duchu smieme kráčať,<br/>Teba nasledovať.<br/>ako Duch nás Ty budeš viesť,<br/>svetlo udeľovať.<br/>',NULL,130177,4);
INSERT INTO stanza VALUES('SK745','5','Tým Duchom v duchu žijeme,<br/>Ty si uctievaný,<br/>Tvojím Duchom v našom duchu<br/>sme posilňovaní.<br/>',NULL,130178,5);
INSERT INTO stanza VALUES('SK745','6','V duchu s Tvojím Duchom, Pane,<br/>sa k Tebe modlíme,<br/>zatiaľ čo Ty ako Duch v nás<br/>stonáš nevýslovne.<br/>',NULL,130179,6);
INSERT INTO stanza VALUES('SK745','7','K duchu sa chceme obracať,<br/>tam Ťa kontaktovať,<br/>Božie dedičstvo môžeme<br/>iba v duchu zdieľať.<br/>',NULL,130180,7);
INSERT INTO stanza VALUES('SK745','8','Ó, čo za jednota to je,<br/>z dvoch duchov jeden je,<br/>Tvoj Duch žije v našom duchu,<br/>náš duch, on v Tvojom je.<br/>',NULL,130181,8);
INSERT INTO stanza VALUES('SK746','1','Pane, uč nás rozlíšiť ducha<br/>od duše, poznať Ťa chceme.<br/>Ó, Ty si ten Duch v našom duchu,<br/>s Tebou prevzácne zmiešanie.<br/>',NULL,130182,1);
INSERT INTO stanza VALUES('SK746','2','Pane, uč nás rozlíšiť ducha,<br/>život duše vždy zapierať,<br/>Stále Ťa nasledovať v duchu,<br/>Teba, Ducha uplatňovať.<br/>',NULL,130183,2);
INSERT INTO stanza VALUES('SK746','3','Pane, uč nás rozlíšiť ducha,<br/>myseľ upínať len k duchu,<br/>nikdy k nášmu padlému telu,<br/>neostávať v sebe, v hriechu.<br/>',NULL,130184,3);
INSERT INTO stanza VALUES('SK746','4','Pane, uč nás rozlíšiť ducha,<br/>už nechceme byť duševní,<br/>no duchovní skutočne, v duchu<br/>rozlišovať všetky veci.<br/>',NULL,130185,4);
INSERT INTO stanza VALUES('SK746','5','Pane, uč nás rozlíšiť ducha,<br/>nech sa naše ja odhalí,<br/>aby sme naň kríž uplatnili,<br/>nie sebou, no Tebou žili.<br/>',NULL,130186,5);
INSERT INTO stanza VALUES('SK746','6','Pane, uč nás rozlíšiť ducha,<br/>nech sme v duši premenení,<br/>pripodobnení na Tvoj obraz,<br/>až kým nebudeme zrelí.<br/>',NULL,130187,6);
INSERT INTO stanza VALUES('SK746','7','Pane, uč nás rozlíšiť ducha,<br/>daj nám Svoje slovo živé,<br/>čo rozdelí dušu od ducha,<br/>nech v našom duchu žijeme.<br/>',NULL,130188,7);
INSERT INTO stanza VALUES('SK749','1','Duch Trojjediného Boha<br/>prebýva v našom duchu dnes.<br/>Svoj prietok v nás hľadá, ’by mal<br/>Boh v Kristovi vyjadrenie.<br/>',NULL,130189,1);
INSERT INTO stanza VALUES('SK749','2','No prirodzeným človekom<br/>je v nás Duch obmedzovaný,<br/>takto Preňho nie sme domom,<br/>stávame sa Mu väzením.<br/>',NULL,130190,2);
INSERT INTO stanza VALUES('SK749','3','Je nesmiernym pokladom v nás,<br/>tých nádobách, čo sú z hliny.<br/>Nádoba má byť rozbitá,<br/>nech je poklad viditeľný.<br/>',NULL,130191,3);
INSERT INTO stanza VALUES('SK749','4','Pán nás musí nutne zlomiť,<br/>marí Ho vonkajší človek!<br/>Až keď nás dôkladne zlomí,<br/>bude Duch pretekať voľne.<br/>',NULL,130192,4);
INSERT INTO stanza VALUES('SK749','5','To je dôvodom, prečo Pán<br/>istú mieru utrpení<br/>cez okolnosti nameria,<br/>iba takto nás prelomí.<br/>',NULL,130193,5);
INSERT INTO stanza VALUES('SK749','6','Vonkajší človek, ja, duša,<br/>musí byť vždy umenšený,<br/>tak vnútorný človek, duch náš,<br/>bude s Duchom uvoľnený.<br/>',NULL,130194,6);
INSERT INTO stanza VALUES('SK749','7','Svätú zlomenosť daruj mi,<br/>nech nie je nič nedotknuté,<br/>ochotne chcem prijať rany<br/>mojej duši darované.<br/>',NULL,130195,7);
INSERT INTO stanza VALUES('SK749','8','Pôsob, nech vždy oceňujem<br/>to lámanie bez sťažností<br/>a nech za viac považujem<br/>miesto zisku rôzne straty.<br/>',NULL,130196,8);
INSERT INTO stanza VALUES('SK750','1','Zámer Boha je všetkých nás<br/>pripodobniť Synovi.<br/>kvôli tomuto Duch musí<br/>konať dielo premeny.<br/>',NULL,130197,1);
INSERT INTO stanza VALUES('SK750','chorus','Premieňaj nás na Svoj obraz,<br/>myseľ, city, vôľu zmeň.<br/>Presycuj nás Svätým Duchom,<br/>viacej Seba do nás vlej.<br/>',NULL,130198,2);
INSERT INTO stanza VALUES('SK750','2','Boh nás v duchu znovu splodil,<br/>božský život udelil.<br/>teraz tento život musí<br/>našu dušu premeniť.<br/>',NULL,130199,3);
INSERT INTO stanza VALUES('SK750','3','Pán sa rozširuje z ducha,<br/>našu dušu premieňa<br/>obnovou vnútorných častí,<br/>až sa Mu všetko poddá.<br/>',NULL,130200,4);
INSERT INTO stanza VALUES('SK750','4','Vďaka moci Svojho Ducha<br/>nás na Svoj obraz mení.<br/>postupne od slávy k sláve,<br/>nás k Sebe pripodobní.<br/>',NULL,130201,5);
INSERT INTO stanza VALUES('SK750','5','Premieňa nás, posväcuje<br/>a zrelými nás činí,<br/>získava si našu dušu,<br/>až v nás Seba uvidí.<br/>',NULL,130202,6);
INSERT INTO stanza VALUES('SK769','1','Vstúpim do veľsvätyne,<br/>za oponou ostanem,<br/>trónu milosti sa v nej<br/>dotknem, život poplynie.<br/>',NULL,130203,1);
INSERT INTO stanza VALUES('SK769','2','Najsvätejšie miesto dnes<br/>práve v mojom duchu je.<br/>Pán tam prebýva vo mne,<br/>tam sa v duchu spájame.<br/>',NULL,130204,2);
INSERT INTO stanza VALUES('SK769','3','Do ducha sa otáčam,<br/>v ňom sa s Pánom stretávam.<br/>Je to také úžasné,<br/>v mojom vnútri býva Pán.<br/>',NULL,130205,3);
INSERT INTO stanza VALUES('SK769','4','Vzkrieseného aróma<br/>z môjho ducha sa šíri.<br/>ak sa v duchu modlievam,<br/>Kristus je vyjadrený.<br/>',NULL,130206,4);
INSERT INTO stanza VALUES('SK769','5','V duchu sa Ho dotýkam,<br/>bohatstvo ma napĺňa.<br/>ó, život, svetlo, láska,<br/>milosť, prúdia cezo mňa.<br/>',NULL,130207,5);
INSERT INTO stanza VALUES('SK769','6','Hlbšie sa Ho dotýkam,<br/>bohato Ho zakúšam.<br/>týmto zákon života<br/>a pomazanie vnímam.<br/>',NULL,130208,6);
INSERT INTO stanza VALUES('SK769','7','Milovaného sa chcem<br/>hlbšie v duchu dotýkať.<br/>skryte Ho kontaktovať,<br/>skrytú mannu zakúšať.<br/>',NULL,130209,7);
INSERT INTO stanza VALUES('SK769','8','Ak je život vzkriesenia<br/>pre mňa v sile skutočný,<br/>sťa pučiaca palica,<br/>vtedy budem prijatý.<br/>',NULL,130210,8);
INSERT INTO stanza VALUES('SK769','9','Trón milosti som našiel,<br/>prúdi tu živá voda,<br/>rieka plná milosti,<br/>čo do mňa milosť vkladá.<br/>',NULL,130211,9);
INSERT INTO stanza VALUES('SK769','10','Keď sa spolu modlíme,<br/>ducha uvoľňujeme,<br/>takto v duchu zmiešaní<br/>ako kňazi slúžime.<br/>',NULL,130212,10);
INSERT INTO stanza VALUES('SK769','11','Pána vo veľsvätyni<br/>môžeme sa dotýkať,<br/>trónu veľa spôsobmi,<br/>kým bude milosť na nás.<br/>',NULL,130213,11);
INSERT INTO stanza VALUES('SK770','1','Trónu sa dotkni vo veľsvätyni,<br/>milosť bude riekou tiecť,<br/>trónu milosti vo veľsvätyni,<br/>milosť bude riekou tiecť.<br/>',NULL,130214,1);
INSERT INTO stanza VALUES('SK770','chorus','Aleluja! Aleluja!<br/>Milosť bude riekou tiecť!<br/>Aleluja! Aleluja!<br/>Milosť bude riekou tiecť!<br/>',NULL,130215,2);
INSERT INTO stanza VALUES('SK770','2','Pred Ježišom ži vo veľsvätyni,<br/>slávy svetlo zažiari,<br/>pred Ježišom ži vo veľsvätyni,<br/>slávy svetlo zažiari.<br/>',NULL,130216,3);
INSERT INTO stanza VALUES('SK770','chorus','Aleluja! Aleluja!<br/>Slávy svetlo zažiari!<br/>Aleluja! Aleluja!<br/>Slávy svetlo zažiari!<br/>',NULL,130217,4);
INSERT INTO stanza VALUES('SK770','3','Ducha uplatňuj, kadidlo spaľuj,<br/>pi z prameňa života,<br/>ducha uplatňuj, kadidlo spaľuj,<br/>pi z prameňa života.<br/>',NULL,130218,5);
INSERT INTO stanza VALUES('SK770','chorus','Aleluja! Aleluja!<br/>Pi z prameňa života!<br/>Aleluja! Aleluja!<br/>Pi z prameňa života!<br/>',NULL,130219,6);
INSERT INTO stanza VALUES('SK777','1','Povedz vrchu: „Povstaň,<br/>do mora sa vrhni!“<br/>V srdci nepochybuj<br/>že sa ti to splní.<br/>Uver Slovu, to sa splní.<br/>Prikáž tej hore v Pánovi!<br/>',NULL,130220,1);
INSERT INTO stanza VALUES('SK777','2','Krvou si kúpený,<br/>len si to uplatni.<br/>Trojica jednotná,<br/>pravým to učiní.<br/>Uver Slovu, to sa splní.<br/>Prikáž tej hore v Pánovi!<br/>',NULL,130221,2);
INSERT INTO stanza VALUES('SK777','3','Ego aj súženie<br/>Pán stretol keď prišiel.<br/>„Toho, čo mám tak rád<br/>rozviažte, nech ide!“<br/>Spočiň v Slove, to sa splní.<br/>Prikáž tej hore v Pánovi!<br/>',NULL,130222,3);
INSERT INTO stanza VALUES('SK777','4','Obchádzaj v tichosti<br/>zachmúrenú stenu.<br/>Vstaň, víťazne zvolaj,<br/>hradby sa zosunú.<br/>Vierou istou sa to splní.<br/>Prikáž tej hore v Pánovi!<br/>',NULL,130223,4);
INSERT INTO stanza VALUES('SK777','5','Brány otvorené,<br/>z bronzu aj železné.<br/>Verní môžu vstúpiť,<br/>odvšadiaľ víťazne.<br/>Nepriateľ nech je neschopný.<br/>Prikáž tej hore v Pánovi!<br/>',NULL,130224,5);
INSERT INTO stanza VALUES('SK777','6','Vezmi vieru v Boha,<br/>nemaj pochybnosti.<br/>Zázračnou palicou<br/>odstráň argumenty.<br/>Na Slove stoj, to sa splní.<br/>Prikáž tej hore v Pánovi!<br/>',NULL,130225,6);
INSERT INTO stanza VALUES('SK782','1','Aké tajomné, Pane,<br/>že Tvoj Duch v mojom žije.<br/>Aké nádherné to je,<br/>z dvoch duchov tak jeden je.<br/>',NULL,130226,1);
INSERT INTO stanza VALUES('SK782','2','Duchom môžem ja kráčať,<br/>duchovným tak v duchu byť.<br/>V duchu Teba uctievať,<br/>môžem tiež duchom slúžiť.<br/>',NULL,130227,2);
INSERT INTO stanza VALUES('SK782','3','Slovom a tiež modlitbou<br/>v duchu s Tebou spojený.<br/>môj duch sa tak pozdvihol<br/>a bude posilnený.<br/>',NULL,130228,3);
INSERT INTO stanza VALUES('SK782','4','Daj mi ducha silného<br/>ducha iných obživiť,<br/>pozdvihni ducha môjho<br/>ducha iných obdariť.<br/>',NULL,130229,4);
INSERT INTO stanza VALUES('SK782','5','Pane, vždy keď hovorím,<br/>nech ducha uplatňujem<br/>a nech čokoľvek robím,<br/>nech ma duch motivuje.<br/>',NULL,130230,5);
INSERT INTO stanza VALUES('SK782','6','Vždy keď pôsobí môj duch,<br/>otváraj ducha iných,<br/>vždy keď sa hýbe môj duch,<br/>pozdvihuj ducha iných.<br/>',NULL,130231,6);
INSERT INTO stanza VALUES('SK782','7','Zmiluj sa, Pane drahý,<br/>nech Tvoj Duch na mňa vanie.<br/>môj duch bude bohatý<br/>a Tebou posilnený.<br/>',NULL,130232,7);
INSERT INTO stanza VALUES('SK783','1','Modlitbou sa dotýkaj<br/>trónu Božej milosti,<br/>milosť, milosrdenstvo<br/>nájdeš, budeš spokojný.<br/>',NULL,130233,1);
INSERT INTO stanza VALUES('SK783','2','Trónu Boha sa dotkni,<br/>milosť potrebnú ti dá,<br/>v duchu zostávaj s Bohom<br/>v spoločenstve tvárou v tvár.<br/>',NULL,130234,2);
INSERT INTO stanza VALUES('SK783','3','Trónu Boha sa dotkni,<br/>nájdi milosť bohatú,<br/>stále milosť zakúšaj,<br/>chváľ Boha, vzdaj Mu vďaku.<br/>',NULL,130235,3);
INSERT INTO stanza VALUES('SK783','4','Trónu Boha sa dotkni,<br/>trónu Pánovej moci,<br/>v mene Ježiša Krista,<br/>sprav, čo vykonať musíš.<br/>',NULL,130236,4);
INSERT INTO stanza VALUES('SK783','5','Trónu Boha sa dotkni,<br/>vierou živou sa dotkni,<br/>uplatňuj autoritu,<br/>nad všetkou silou smrti.<br/>',NULL,130237,5);
INSERT INTO stanza VALUES('SK783','6','Trónu Boha sa dotkni,<br/>Zlého modlitbou poraz,<br/>s Pánom kraľuj modlitbou,<br/>s Ním sa modli hneď teraz.<br/>',NULL,130238,6);
INSERT INTO stanza VALUES('SK784','1','Modli sa a buď s Ježišom,<br/>v duchu hľadaj Jeho tvár,<br/>pýtaj sa Ho a počúvaj,<br/>v skrytosti Naňho čakaj.<br/>',NULL,130239,1);
INSERT INTO stanza VALUES('SK784','chorus','Spoločenstvo s Ježišom maj,<br/>v duchu hľadaj Jeho tvár,<br/>pýtaj sa Ho a počúvaj,<br/>v skrytosti Naňho čakaj.<br/>',NULL,130240,2);
INSERT INTO stanza VALUES('SK784','2','Modli sa a buď s Ježišom,<br/>vnútri buď otvorený,<br/>s odhalenou tvárou Naň hľaď,<br/>jednoduchý, úprimný.<br/>',NULL,130241,3);
INSERT INTO stanza VALUES('SK784','3','Modli sa a buď s Ježišom,<br/>hľadaj Ho, dôveru maj,<br/>dotkni sa Ho ako Ducha,<br/>úctivo Naň pozeraj.<br/>',NULL,130242,4);
INSERT INTO stanza VALUES('SK784','4','Modli sa a buď s Ježišom,<br/>nič pred Ním nepredstieraj,<br/>modli sa v súlade s duchom,<br/>podľa vnemu života.<br/>',NULL,130243,5);
INSERT INTO stanza VALUES('SK784','5','Modli sa a buď s Ježišom,<br/>pozorne Mu načúvaj,<br/>nech ti povie, po čom túži,<br/>z hlbiny k Nemu volaj.<br/>',NULL,130244,6);
INSERT INTO stanza VALUES('SK784','6','Modli sa a buď s Ježišom,<br/>celkom doň ponorený,<br/>presiaknutý Jeho krásou,<br/>nech je vyžarovaný.<br/>',NULL,130245,7);
INSERT INTO stanza VALUES('SK786','1','Pracuj s Pánom modlitbou,<br/>cestu Preňho pripravuj,<br/>modli sa, nech sa hýbe<br/>od stredu až po okraj.<br/>',NULL,130246,1);
INSERT INTO stanza VALUES('SK786','2','Pracuj s Pánom modlitbou,<br/>celkom s Ním stotožnený<br/>v zámere, cieli Jeho,<br/>až požehnania prídu.<br/>',NULL,130247,2);
INSERT INTO stanza VALUES('SK786','3','Pracuj s Pánom modlitbou,<br/>vlastná vôľa musí preč,<br/>tiež ambície vlastné,<br/>Jeho zámer naplňme.<br/>',NULL,130248,3);
INSERT INTO stanza VALUES('SK786','4','Pracuj s Pánom modlitbou,<br/>nech všetko začína Pán,<br/>bude pôsobiť skrz nás<br/>každé dielo, každý plán.<br/>',NULL,130249,4);
INSERT INTO stanza VALUES('SK786','5','Pracuj s Pánom modlitbou,<br/>kým sa pohne koleso,<br/>modli sa spolu s Pánom,<br/>kým cirkev prejaví moc.<br/>',NULL,130250,5);
INSERT INTO stanza VALUES('SK792','1','Teba čakám, môj Pane, čakám.<br/>V Tebe odpočiniem,<br/>rozjasni sa vo mne,<br/>to je prianie moje –<br/>Teba čakám, čakám Pane.<br/>',NULL,130251,1);
INSERT INTO stanza VALUES('SK792','2','Teba čakám, môj Pane, čakám.<br/>Zatiaľ čo som s Tebou,<br/>veď ma cestou Svojou,<br/>modlím sa len Tebou –<br/>Teba čakám, čakám Pane.<br/>',NULL,130252,2);
INSERT INTO stanza VALUES('SK792','3','Teba čakám, môj Pane, čakám.<br/>Zmiešavaj sa so mnou,<br/>nech som jedno s Tebou,<br/>len Tvojím obrazom –<br/>Teba čakám, čakám Pane.<br/>',NULL,130253,3);
INSERT INTO stanza VALUES('SK792','4','Teba čakám, môj Pane, čakám.<br/>Čo Tvojou vôľou je?<br/>Buď mi cestou všade,<br/>cezo mňa prúď, Pane –<br/>Teba čakám, čakám Pane.<br/>',NULL,130254,4);
INSERT INTO stanza VALUES('SK792','5','Teba čakám, môj Pane, čakám.<br/>Cez moje modlitby<br/>sa zo mňa vyjadri,<br/>nech nájdem kľúč skrytý –<br/>Teba čakám, čakám Pane.<br/>',NULL,130255,5);
INSERT INTO stanza VALUES('SK800','1','Pán Boh prehovoril, je odhalený,<br/>Svoju povahu, osoby vyjadril.<br/>Zjavil tajomstvo synom Adamovým,<br/>úplne im ho zobrazil, prejavil.<br/>',NULL,130256,1);
INSERT INTO stanza VALUES('SK800','2','Pán Boh prehovoril, srdce otvoril,<br/>že Jeho Syn má byť vo všetkom prvý.<br/>Otec má byť v celom Svojom stvorení<br/>v Svojom drahom Synovi oslávený.<br/>',NULL,130257,2);
INSERT INTO stanza VALUES('SK800','3','Pán Boh prehovoril, Krista nám zjavil,<br/>On je sám Boh, avšak aj človek pravý,<br/>všetko vo všetkom, všetko spočíva v Ňom,<br/>stredom aj obvodom je pre plán Boží.<br/>',NULL,130258,3);
INSERT INTO stanza VALUES('SK800','4','Pán Boh prehovoril, tajomstvo zjavil,<br/>chce mať Krista a Jeho vyjadrenie.<br/>Krista s Božou plnosťou, Hlavu slávnu,<br/>cirkev, Jeho Telo, bohatstiev plné.<br/>',NULL,130259,4);
INSERT INTO stanza VALUES('SK800','5','Pán Boh prehovoril, z nebies nám zjavil,<br/>že Boh sa zmieša so Svojím stvorením:<br/>Otec je v Synovi a Syn je Duchom,<br/>v Tele sídli, ’by naplnil plán Boží.<br/>',NULL,130260,5);
INSERT INTO stanza VALUES('SK800','6','Pán Boh prehovoril, nám dal zjavenie<br/>Jeho stvorenia, narodenia v biede,<br/>aj vykúpenia a spásy úplnej,<br/>nech uctievanie Jeho napĺňa zem.<br/>',NULL,130261,6);
INSERT INTO stanza VALUES('SK811','1','Srdce hladuje a môj duch smäd má,<br/>prichádzam k Tebe, Ty nasýtiš ma.<br/>Pane, si všetko, čo potrebujem,<br/>v Tebe nachádzam uspokojenie.<br/>',NULL,130262,1);
INSERT INTO stanza VALUES('SK811','chorus','Nasýť ma, Pane, napiť mi daj,<br/>uhas môj smäd, tiež utíš môj hlad.<br/>radosť a aj silu k životu daj,<br/>uhas môj smäd, tiež utíš môj hlad.<br/>',NULL,130263,2);
INSERT INTO stanza VALUES('SK811','2','Si pokrmom a vodou života,<br/>ducha pozdvihneš a oživíš ma.<br/>túžim Ťa v duchu, Pane, jesť a piť,<br/>vychutnávať Ťa, Slovom sa modliť.<br/>',NULL,130264,3);
INSERT INTO stanza VALUES('SK811','3','Ty si Slovom, Božia plnosť je v Ňom,<br/>si tiež Duchom, ’by si bol životom.<br/>mojím pokrmom pre mňa v Slove si,<br/>ako Duch vodou, tak pre mňa Ty si.<br/>',NULL,130265,4);
INSERT INTO stanza VALUES('SK811','4','Zostúpil si ako pokrm z neba,<br/>ako puknutá skala vodu dal.<br/>si nezmernou zásobou potravy,<br/>prameňom, čo nevyčerpám nikdy.<br/>',NULL,130266,5);
INSERT INTO stanza VALUES('SK811','5','Ty si Duch a život v Slove Svojom,<br/>preto sa dnes môžem sýtiť Slovom.<br/>Dnes žiješ ako Duch v mojom duchu,<br/>preto vždy môžem piť z Teba v duchu.<br/>',NULL,130267,6);
INSERT INTO stanza VALUES('SK811','6','Teba prichádzam v Slove vychutnať,<br/>sýtiť sa Tebou, hlad utišovať.<br/>Teraz sa v duchu k Tebe obraciam,<br/>pijem z Teba a smäd tak uhášam.<br/>',NULL,130268,7);
INSERT INTO stanza VALUES('SK811','7','Pane Ježišu, sýtim sa, pijem,<br/>jem čítaním a modlitbou pijem.<br/>čítam modlitbou – nápoj prijímam,<br/>modlím sa čítaním – tak pokrm mám.<br/>',NULL,130269,8);
INSERT INTO stanza VALUES('SK811','8','Chcem viac, Pane, na Tebe hodovať,<br/>naplnený Duchom a Slovom byť.<br/>Pane, Ty sám buď pre mňa hostinou,<br/>takou, čo sa nedá zrovnať s inou.<br/>',NULL,130270,9);
INSERT INTO stanza VALUES('SK812','1','Prichádzam žíznivý<br/>k Tebe, drahý Pane.<br/>Teba ja túžim jesť a piť,<br/>vychutnať Ťa plne.<br/>',NULL,130271,1);
INSERT INTO stanza VALUES('SK812','2','Túži srdce moje,<br/>na Tvoju tvár hľadieť,<br/>túžim z Teba piť, môj Pane,<br/>a môj smäd uhasiť.<br/>',NULL,130272,2);
INSERT INTO stanza VALUES('SK812','3','Tvoja žiariaca tvár<br/>srdce potešuje.<br/>chcem takto zostať naveky,<br/>a na Teba hľadieť.<br/>',NULL,130273,3);
INSERT INTO stanza VALUES('SK812','4','V takom spoločenstve<br/>Ťa ako milosť mám.<br/>srdce a duch naplnené,<br/>v odpočinok vchádzam.<br/>',NULL,130274,4);
INSERT INTO stanza VALUES('SK812','5','Pane, chcem zostať tu,<br/>stále hľadať Teba,<br/>zotrvať v Slove, v modlitbe,<br/>nech prúdiš cezo mňa.<br/>',NULL,130275,5);
INSERT INTO stanza VALUES('SK814','1','Nie len z chleba žije človek,<br/>ale taktiež každým slovom,<br/>ktoré vychádza z úst Božích.<br/>jedzme ich, nech sú životom.<br/>',NULL,130276,1);
INSERT INTO stanza VALUES('SK814','2','Nemáme len samé telo,<br/>no telo, dušu a ducha.<br/>duch je najvnútornejšia časť<br/>na kontaktovanie Boha.<br/>',NULL,130277,2);
INSERT INTO stanza VALUES('SK814','3','Ako telo potrebuje<br/>prijímať fyzický pokrm,<br/>tak aj duch náš potrebuje<br/>Tvoje slovo – pravý pokrm.<br/>',NULL,130278,3);
INSERT INTO stanza VALUES('SK814','4','Ty si Duch a Tvoje slovo<br/>Teba samého vyjadrí,<br/>a tak musíš byť ako Duch<br/>naším duchom prijímaný.<br/>',NULL,130279,4);
INSERT INTO stanza VALUES('SK814','5','Slovo nemôžeme prijať<br/>iba očami čítajúc<br/>a len mysľou mu rozumieť,<br/>ale ducha uplatňujúc!<br/>',NULL,130280,5);
INSERT INTO stanza VALUES('SK814','6','Slovo musíme v duchu jesť,<br/>do vnútra ho dostaneme,<br/>ak ducha uplatňujeme,<br/>modliac sa tým, čo chápeme.<br/>',NULL,130281,6);
INSERT INTO stanza VALUES('SK814','7','Slovo, ostávajúc v mysli,<br/>je len únavným poznaním.<br/>ak sa dostane do ducha,<br/>je duchom a nasýtením.<br/>',NULL,130282,7);
INSERT INTO stanza VALUES('SK814','8','Len ak ducha zapájame,<br/>kontaktujúc Teba v Slove,<br/>sme skutočne nasýtení,<br/>hlboko sa Ťa dotkneme.<br/>',NULL,130283,8);
INSERT INTO stanza VALUES('SK814','9','Pri čítaní Tvojho Slova<br/>nás uč uplatňovať ducha.<br/>náš duch bude vyživený,<br/>Tebou budeme sýtení.<br/>',NULL,130284,9);
INSERT INTO stanza VALUES('SK818','1','Kristus je tajomstvom Boha.<br/>Boh je skrytý, nebadaný,<br/>nik nevidel Jeho obraz,<br/>Pán Ježiš Ho spravil známym.<br/>',NULL,130285,1);
INSERT INTO stanza VALUES('SK818','2','Kristus, On je Slovom Božím,<br/>On je Boha objasnením,<br/>plným Božím stelesnením,<br/>obraz prináša On Boží.<br/>',NULL,130286,2);
INSERT INTO stanza VALUES('SK818','3','Obraz neviditeľného,<br/>odblesk Jeho slávy jasnej.<br/>Božia plnosť prebýva v Ňom,<br/>Pán nesie svedectvo Božie.<br/>',NULL,130287,3);
INSERT INTO stanza VALUES('SK818','4','Cirkev je tajomstvom Krista,<br/>teraz ukrytý ľuďom je.<br/>nikto Ho vidieť nemôže,<br/>známym iba cez Cirkev je.<br/>',NULL,130288,4);
INSERT INTO stanza VALUES('SK818','5','Cirkev je plným výrazom<br/>Krista – je v nej stelesnený.<br/>ona Jeho duplikátom,<br/>môže len v nej byť videný.<br/>',NULL,130289,5);
INSERT INTO stanza VALUES('SK818','6','Tá Cirkev má obraz Krista,<br/>ona je Jeho zväčšením.<br/>je Telom pre Hlavu – Krista,<br/>sám Kristus je v nej nájdený.<br/>',NULL,130290,6);
INSERT INTO stanza VALUES('SK818','7','A tak Otec je v Synovi<br/>a Syn, On je teraz Duchom.<br/>Duch Trojjediného Boha<br/>je v Cirkvi a je jedno s ňou.<br/>',NULL,130291,7);
INSERT INTO stanza VALUES('SK819','1','Ako je telo plnosťou –<br/>nás vyjadruje,<br/>Cirkev Telom Krista Jeho<br/>tiež vyjadruje.<br/>',NULL,130292,1);
INSERT INTO stanza VALUES('SK819','2','Ako Eva, časť Adama,<br/>je z neho vzatá,<br/>tak je Cirkev nárast Pána,<br/>Krista vnútri má.<br/>',NULL,130293,2);
INSERT INTO stanza VALUES('SK819','3','Tak ako z jedného zrna<br/>vzišlo zŕn mnoho<br/>a tie zmiešané zrná sú<br/>len jedným chlebom.<br/>',NULL,130294,3);
INSERT INTO stanza VALUES('SK819','4','Tak Cirkev z mnohých kresťanov<br/>zväčšuje Krista,<br/>vyjadruje v jednom Tele,<br/>slávu Boh získa.<br/>',NULL,130295,4);
INSERT INTO stanza VALUES('SK819','5','Tak ako vetvy viniča –<br/>vinič zväčšený,<br/>v ňom prebývajú a nosia<br/>plody jedno s ním.<br/>',NULL,130296,5);
INSERT INTO stanza VALUES('SK819','6','Tak je mnoho údov Cirkvi<br/>Krista zväčšením,<br/>jedno s Ním v živote, Jeho<br/>sú rozšírením.<br/>',NULL,130297,6);
INSERT INTO stanza VALUES('SK819','7','Plnosť, nárast, znásobenie<br/>a vyjadrenie,<br/>rast, hojný prebytok, Jeho<br/>pokračovanie.<br/>',NULL,130298,7);
INSERT INTO stanza VALUES('SK819','8','Toto je Cirkev pre Krista,<br/>’by Boh v Kristovi<br/>bol oslávený naveky<br/>vo vykúpených.<br/>',NULL,130299,8);
INSERT INTO stanza VALUES('SK819','9','Takto sú Cirkev a Kristus<br/>tajomstvom Božím,<br/>ľudia zmiešaní s Bohom sú<br/>tajomstvom veľkým.<br/>',NULL,130300,9);
INSERT INTO stanza VALUES('SK820','1','Krista budeme plnosťou,<br/>bohatstvá vychutnávajúc.<br/>Jeho budeme svedectvom,<br/>na Ňom samom účasť majúc.<br/>',NULL,130301,1);
INSERT INTO stanza VALUES('SK820','2','Sám Pán je týmto bohatstvom<br/>pre nás, čo údmi sme Jeho.<br/>Jeho budeme plnosťou<br/>ako pre človeka telo.<br/>',NULL,130302,2);
INSERT INTO stanza VALUES('SK820','3','Bohatstvo Pána vidíme<br/>v sladkých produktoch v Kanaáne,<br/>z ktorých bol chrám postavený,<br/>obraz Cirkvi v ňom vidíme.<br/>',NULL,130303,3);
INSERT INTO stanza VALUES('SK820','4','Eva plnosťou Adama<br/>aj Cirkev plnosťou Krista.<br/>ako je Eva z Adama,<br/>tak Cirkev pochádza z Krista.<br/>',NULL,130304,4);
INSERT INTO stanza VALUES('SK820','5','Sám Pán je tými pokladmi,<br/>navonok sme Mu plnosťou.<br/>Jeho plným vyjadrením,<br/>a tak sme stavbou úplnou.<br/>',NULL,130305,5);
INSERT INTO stanza VALUES('SK821','1','Cirkev je nádoba Krista,<br/>je v nej, je ňou vyjadrený,<br/>tak ako je ľudské telo<br/>nádobou pre život ľudský.<br/>',NULL,130306,1);
INSERT INTO stanza VALUES('SK821','2','Ako bol chrám pre truhlicu<br/>príbytkom a odpočinkom,<br/>cirkev obsahuje Krista,<br/>cirkev je Jeho príbytkom.<br/>',NULL,130307,2);
INSERT INTO stanza VALUES('SK821','3','Kristus je tajomstvom, Boha<br/>vysvetľuje, vyjadruje,<br/>cirkev je tajomstvom, Krista<br/>vysvetľuje, prejavuje.<br/>',NULL,130308,3);
INSERT INTO stanza VALUES('SK821','4','Údy cirkvi Kristovej sú<br/>nádobami hlinenými,<br/>potrebujú premenu, byť<br/>priezračnými a vzácnymi.<br/>',NULL,130309,4);
INSERT INTO stanza VALUES('SK821','5','Premenou sú budovaní,<br/>Pán si z nich získal nádobu,<br/>Jeho plnosť obsahuje,<br/>spoločne Ho vyjadrujú.<br/>',NULL,130310,5);
INSERT INTO stanza VALUES('SK821','6','Premieňajúcim dielom v nich<br/>pôsobí Boh Trojjediný,<br/>sú sťa Nový Jeruzalem,<br/>nádoba, človek súhrnný.<br/>',NULL,130311,6);
INSERT INTO stanza VALUES('SK821','7','Ó, cirkev je prenádherná,<br/>priezračná je, Krista plná.<br/>Božiu plnosť obsahuje,<br/>slávu Božiu navonok má.<br/>',NULL,130312,7);
INSERT INTO stanza VALUES('SK821','8','Kristus je životom cirkvi,<br/>Boh svetlom, Duch tokom živým.<br/>Trojjediný Boh je v cirkvi,<br/>celý vesmír nech to vidí.<br/>',NULL,130313,8);
INSERT INTO stanza VALUES('SK822','1','Cirkev je svietnikom Krista,<br/>On je lampou, Boh v nej svetlom.<br/>božské svetlo žiari z Pána<br/>a cirkev ho udržiava.<br/>',NULL,130314,1);
INSERT INTO stanza VALUES('SK822','2','Svetlom, ktoré svieti v lampe,<br/>je Boh ako život božský.<br/>a preto je svietnik v zlate,<br/>’by Božej sláve bol rovný.<br/>',NULL,130315,2);
INSERT INTO stanza VALUES('SK822','3','Uprostred temného veku<br/>to svetlo života svieti,<br/>kde sú ľudia sústredení,<br/>svedectvo Ježiša žiari.<br/>',NULL,130316,3);
INSERT INTO stanza VALUES('SK822','4','Pre svedectvo cirkev musí<br/>prvotnú lásku zachovať.<br/>a tak zo stromu života<br/>podiel víťazov môže vziať.<br/>',NULL,130317,4);
INSERT INTO stanza VALUES('SK822','5','Prenasledovania znášať<br/>musí, ak chce korunu mať,<br/>cudzoložstvo prekonávať,<br/>a tak skrytú mannu získať.<br/>',NULL,130318,5);
INSERT INTO stanza VALUES('SK822','6','Skutky Jezábel opustiť,<br/>aby mohla zemi vládnuť,<br/>nečistú smrť prekonávať,<br/>’by mohla v bielom rúchu stáť.<br/>',NULL,130319,6);
INSERT INTO stanza VALUES('SK822','7','Filadelfiou musí byť<br/>s Jeho slovom, s Jeho menom.<br/>vlažnosť, pýchu prekonávať,<br/>hodovať s Ním, byť víťaznou.<br/>',NULL,130320,7);
INSERT INTO stanza VALUES('SK822','8','Takto bude očistená,<br/>svietnikom z čistého zlata,<br/>plná čistého svedectva,<br/>hodná niesť život Ježiša.<br/>',NULL,130321,8);
INSERT INTO stanza VALUES('SK822','9','Miestne cirkvi tu na zemi<br/>sú v tomto veku svietnikmi.<br/>slávny Nový Jeruzalem<br/>bude svietnikom na veky.<br/>',NULL,130322,9);
INSERT INTO stanza VALUES('SK822','10','Mesto bude čisté zlato,<br/>jeden zavŕšený svietnik.<br/>Krista – lampu bude držať,<br/>Božie plné svetlo dávať.<br/>',NULL,130323,10);
INSERT INTO stanza VALUES('SK824','1','Telom Krista je Cirkev,<br/>Otcovým príbytkom,<br/>zvolaných zhromaždenie,<br/>Boh zmiešaný s ľudstvom.<br/>Zvolená pred stvorením,<br/>Golgotou kúpená,<br/>charakter, postavenie<br/>nie zemské, no z neba.<br/>',NULL,130324,1);
INSERT INTO stanza VALUES('SK824','2','Nový človek je Cirkev<br/>vo vzkriesení Pána,<br/>krstená v Bohu – Duchu,<br/>Slovom posvätená.<br/>Jej život a tiež náplň<br/>je Hlava – Kristus sám.<br/>nad Jeho nepriateľmi<br/>je s Ním vyvýšená.<br/>',NULL,130325,2);
INSERT INTO stanza VALUES('SK824','3','Jej základom je Kristus,<br/>iný mať nemôže,<br/>všetko, čo má, ako On<br/>je vo všetkom božské.<br/>Jej údy skrze Ducha<br/>už s Kristom zomreli,<br/>vo vzkriesení sa z nich stal<br/>materiál vzácny.<br/>',NULL,130326,3);
INSERT INTO stanza VALUES('SK824','4','Jeden Boh a jeden Pán,<br/>aj Duch iba jeden,<br/>nádej, krst, jedna viera,<br/>len jedno Telo je.<br/>Údy tvoria jej Telo,<br/>v nej Boh Trojjediný,<br/>v nádeji slávy sú tak<br/>vierou zjednotení.<br/>',NULL,130327,4);
INSERT INTO stanza VALUES('SK824','5','Cirkvi rôzni členovia<br/>zo všetkých národov,<br/>postavenia rôzneho,<br/>no majú jednotu.<br/>Nie vznešený či nízky,<br/>pohan či žid, už nie,<br/>nie slobodný, nie otrok –<br/>jeden nový človek.<br/>',NULL,130328,5);
INSERT INTO stanza VALUES('SK824','6','Univerzálne Telo<br/>v rôznych miestach jedno,<br/>miesto, kde sa nachádza,<br/>je tak Cirkvi pôdou.<br/>Správa, niekedy miestna,<br/>Jemu zodpovedná,<br/>s cirkvami v spoločenstve<br/>je jednomyseľná.<br/>',NULL,130329,6);
INSERT INTO stanza VALUES('SK824','7','Cirkvi tak znázorňujú<br/>Jeruzalem Nový,<br/>jeho rôzne aspekty<br/>v nich byť vidno musí.<br/>Kristus – lampa, čo žiari<br/>s Bohom – svetlom vnútri,<br/>a cirkvi sú svietnikmi,<br/>obrazom Pánovým.<br/>',NULL,130330,7);
INSERT INTO stanza VALUES('SK831','1','Jednotou cirkvi sú svätí,<br/>ktorí žijú v jednote.<br/>Ten Duch, ktorý prebýva v nich,<br/>ich navždy zjednocuje.<br/>Pravá, skutočná jednota,<br/>zvaná jednota Ducha,<br/>stojí na zdedenej viere,<br/>spoločná je všetkým nám.<br/>',NULL,130331,1);
INSERT INTO stanza VALUES('SK831','2','Vzácna viera všetkých svätých<br/>je viera iba v Krista<br/>a v Kristovo vykúpenie,<br/>je svätá, jedinečná.<br/>Svätí v nej majú jednotu,<br/>sú vo vzájomnej zhode,<br/>a z tejto spoločnej viery<br/>sa cirkev produkuje.<br/>',NULL,130332,2);
INSERT INTO stanza VALUES('SK831','3','Len jedna vo vesmíre je,<br/>je Kristovým vlastníctvom,<br/>preto musí byť aj miestne<br/>cirkev prakticky jedno.<br/>Všetky jej zložky sú jedno –<br/>Jeden Boh, jeden Pán, Duch,<br/>jedna viera, krst aj Telo,<br/>nádej máme len jednu.<br/>',NULL,130333,3);
INSERT INTO stanza VALUES('SK831','4','Jednota je pôdou cirkvi<br/>spoločná pre všetkých nás,<br/>jasnou požiadavkou Ducha<br/>je na tejto pôde stáť.<br/>Tak cirkev v praxi zachová<br/>nutnú, živú jednotu,<br/>a jej miestne vyjadrenia<br/>tvoria stavbu jednotnú.<br/>',NULL,130334,4);
INSERT INTO stanza VALUES('SK831','5','Pane, pomôž nám zápasiť,<br/>jednotu zachovávať<br/>státím na pôde jednoty,<br/>žitím života Tela.<br/>’By túžba, ó, Tvojho srdca<br/>mohla byť naplnená,<br/>nech je Božia večná vôľa<br/>úplne dokončená.<br/>',NULL,130335,5);
INSERT INTO stanza VALUES('SK837','1','Pane, za plán Tvoj chvála Ti,<br/>príbytkom Tvojím smieme byť.<br/>v nás žiješ, ’by sme Ťa mohli<br/>v Synovi plne vyjadriť.<br/>',NULL,130336,1);
INSERT INTO stanza VALUES('SK837','2','Hoc stvorení na Tvoj obraz,<br/>právomocou obdarení,<br/>predsa sme bez stopy Božstva,<br/>sme iba z hliny spravení.<br/>',NULL,130337,2);
INSERT INTO stanza VALUES('SK837','3','Ak Tvoj život prijímame,<br/>Tvoju prirodzenosť máme,<br/>my sa s Tebou zmiešavame,<br/>slávne Telo vyjadríme.<br/>',NULL,130338,3);
INSERT INTO stanza VALUES('SK837','4','Keď život prúdi cez duše,<br/>obnovuje, napĺňa nás,<br/>kameňmi vzácnymi tak sme,<br/>premieňaní na Tvoj obraz.<br/>',NULL,130339,4);
INSERT INTO stanza VALUES('SK837','5','My si uvedomujeme,<br/>to nie je iba na obdiv.<br/>z nás materiál získať si chceš<br/>a vybudovať dom slávny.<br/>',NULL,130340,5);
INSERT INTO stanza VALUES('SK837','6','Pane, vydávame sa Ti,<br/>nás prijmi do rúk Svojich.<br/>prelamuj, buduj nás spolu<br/>v dom, ktorý Ťa uspokojí.<br/>',NULL,130341,6);
INSERT INTO stanza VALUES('SK837','7','Zlom život náš prirodzený,<br/>vezmi podivné spôsoby,<br/>nech nie sme viac nezávislí,<br/>no v jednote so svätými.<br/>',NULL,130342,7);
INSERT INTO stanza VALUES('SK837','8','Tak Ti budeme Nevestou,<br/>v Tvojej komnate prebývať,<br/>lásku Tvoju vychutnávať<br/>a Teba uspokojovať.<br/>',NULL,130343,8);
INSERT INTO stanza VALUES('SK839','1','Ty si skúsený Hrnčiar<br/>a tiež slávny Staviteľ,<br/>Ty utváraš nádoby,<br/>Ty si sám dom buduješ.<br/>Ja som aj človek z hliny,<br/>aj nový kameň živý,<br/>aby nádobu si mal<br/>a aj chrám postavený.<br/>',NULL,130344,1);
INSERT INTO stanza VALUES('SK839','2','Hoci sme iba z hliny,<br/>budeme premenení,<br/>životom, zlatom čistým,<br/>v kameň pripodobnení.<br/>Tvojou prácou my, Pane,<br/>nevestou sa stávame,<br/>spojení v jednom tele,<br/>spokojný navždy budeš.<br/>',NULL,130345,2);
INSERT INTO stanza VALUES('SK839','3','Ty netúžiš mať, Pane,<br/>samotné len kamene,<br/>no spolu zbudované<br/>k Tvojej sláve a v dome.<br/>Si všetkým, požaduješ<br/>cirkev mať zbudovanú,<br/>nech tak slávne bohatstvá<br/>žiaria úplne cez ňu.<br/>',NULL,130346,3);
INSERT INTO stanza VALUES('SK839','4','Nie nezávislí ľudia,<br/>každý zvlášť, hoc duchovní,<br/>iba súhrnné žitie<br/>Tvoje túžby prejaví.<br/>Ak sú údy delené,<br/>tak nemáš vyjadrenie,<br/>avšak telo zladené<br/>vyjadrí Ťa úplne.<br/>',NULL,130347,4);
INSERT INTO stanza VALUES('SK839','5','So svätými ma buduj,<br/>nech nezávislosť nemám,<br/>vpracovávaj do stavby,<br/>naplň túžbu aj Svoj plán.<br/>Či už skúsenosťami,<br/>tiež nepýšim sa darmi,<br/>všetko dávam do stavby,<br/>nech je Pán oslávený.<br/>',NULL,130348,5);
INSERT INTO stanza VALUES('SK840','1','Ak voľný od Adama som,<br/>len vtedy sa budujem<br/>so svätými spolu v Tvoj chrám,<br/>Tvoju slávu tam uzriem.<br/>Nás zo zvláštností vysloboď,<br/>spôsobov nezávislých,<br/>aby slávnym príbytkom sme<br/>Tvojím, Pane, mohli byť.<br/>',NULL,130349,1);
INSERT INTO stanza VALUES('SK840','2','Prúdením Tvojho života<br/>rastiem, som premieňaný,<br/>v spolupráci so svätými,<br/>som Ti pripodobnený.<br/>V Tele poriadok zachovať,<br/>v Tvojej vôli tam fungovať,<br/>ľuďom stále posluhovať,<br/>a Tvoj plán tak naplniť.<br/>',NULL,130350,2);
INSERT INTO stanza VALUES('SK840','3','V poznaní a skúsenosti<br/>sa nechcem vyvyšovať,<br/>no vo všetkom sa podriadiť,<br/>Telom dať sa vyrovnať.<br/>Pevne chcem sa držať Hlavy<br/>a Božím rastom vždy rásť,<br/>spojivami zásobený,<br/>s bratmi spájaný, vždy rásť.<br/>',NULL,130351,3);
INSERT INTO stanza VALUES('SK840','4','Denne Tvoj Duch upevňuje<br/>vnútorného človeka,<br/>Tvoju lásku tak poznávam,<br/>ohromné rozmery máš.<br/>Z bohatstiev Tvojich si beriem,<br/>nimi sa naplňujem,<br/>stále k dospelosti rastiem,<br/>tým sa Telo buduje.<br/>',NULL,130352,4);
INSERT INTO stanza VALUES('SK840','5','V Božom dome, v Tvojom Tele<br/>túžim byť budovaný,<br/>aby v nádobe tej všetci<br/>Tvoju slávu videli.<br/>Tak Nevesta, slávne mesto,<br/>sa ukáže na zemi,<br/>bude žiariť ako svietnik,<br/>Tvoju slávu vyjadrí.<br/>',NULL,130353,5);
INSERT INTO stanza VALUES('SK841','1','Pán môj, si môj život,<br/>vo mne prebývaš,<br/>Božia plnosť s Tebou,<br/>Sám mi ju dávaš.<br/>Tvojou povahou som<br/>posväcovaný,<br/>v Tvojom zmŕtvychvstaní<br/>som vždy víťazný.<br/>',NULL,130354,1);
INSERT INTO stanza VALUES('SK841','2','Tvoj život plynúci<br/>ma osvetľuje,<br/>spoločenstvo s Tebou<br/>mi v duchu nesie.<br/>On všetky potreby<br/>hojne naplní,<br/>pokiaľ stojím v Tebe,<br/>som očistený.<br/>',NULL,130355,2);
INSERT INTO stanza VALUES('SK841','3','Tvoj Duch pomazania,<br/>On ma prenikne,<br/>ducha a tiež dušu<br/>hojne presiakne.<br/>Každú časť pretvorí<br/>k Tvojej podobe,<br/>až Tvoj život zrelý<br/>budem mať v sebe.<br/>',NULL,130356,3);
INSERT INTO stanza VALUES('SK841','4','Tvoj život je hojný,<br/>tiež osviežuje,<br/>vždy bohato prúdi<br/>a posilňuje.<br/>Život pohltil smrť,<br/>slabosť je silou,<br/>zlomené putá sú,<br/>radosť je piesňou.<br/>',NULL,130357,4);
INSERT INTO stanza VALUES('SK841','5','Chcem sa vydať, Pane,<br/>plnosťou Tebe,<br/>’by sa Tvoje prianie<br/>splnilo vo mne.<br/>Nebudem sa snažiť<br/>sám seba zmeniť,<br/>aby si sa mohol<br/>vo mne prejaviť.<br/>',NULL,130358,5);
INSERT INTO stanza VALUES('SK841','6','Úplne zastavím<br/>úsilie vlastné,<br/>nechám nech Tvoj život<br/>ma mení plne.<br/>Buduj ma s inými,<br/>kým v nás uvidíš<br/>Svoje vyjadrenie,<br/>v ňom sa osláviš.<br/>',NULL,130359,6);
INSERT INTO stanza VALUES('SK844','1','Dýchaj na nás, daj nám slovo,<br/>hľa, zem plná kostí suchých,<br/>vôkol v hroboch rozptýlených.<br/>Ó, Pane, dýchaj na nás!<br/>',NULL,130360,1);
INSERT INTO stanza VALUES('SK844','2','Dýchaj na nás, daj nám slovo,<br/>kosti suché oživ Pane,<br/>z hrobov svojich vychádzame.<br/>Ó, Pane, dýchaj na nás!<br/>',NULL,130361,2);
INSERT INTO stanza VALUES('SK844','3','Dýchaj na nás, daj nám slovo,<br/>nech je Tvoj ľud oživený<br/>a nepriateľ odstránený.<br/>Ó, Pane, dýchaj na nás!<br/>',NULL,130362,3);
INSERT INTO stanza VALUES('SK844','4','Dýchaj na nás, daj nám slovo,<br/>nech je Tvoj ľud zjednotený,<br/>Synom, Hlavou ovládaný.<br/>Ó, Pane, dýchaj na nás!<br/>',NULL,130363,4);
INSERT INTO stanza VALUES('SK844','5','Dýchaj na nás, daj nám slovo,<br/>milosťou sme utváraní,<br/>Tebe domom, spočinutím.<br/>Ó, Pane, dýchaj na nás!<br/>',NULL,130364,5);
INSERT INTO stanza VALUES('SK844','6','Dýchaj na mňa, hovor ku mne,<br/>oživ, buduj v Svojom Tele,<br/>nech nie je viac rozdelenie.<br/>Ó, Pane, dýchaj na nás!<br/>',NULL,130365,6);
INSERT INTO stanza VALUES('SK844','7','Dýchaj na mňa, hovor ku mne,<br/>bojujeme s nepriateľom,<br/>Boh sa teší, keď má domov.<br/>Ó, Pane, dýchaj na nás!<br/>',NULL,130366,7);
INSERT INTO stanza VALUES('SK846','1','Ó, nech môj duch tečie,<br/>ó, nech tečie!<br/>Prosím Ťa, môj Pane,<br/>ó, nech tečie!<br/>Prekážky zboriť chcem,<br/>minulosť odvrhnem,<br/>uvoľniť ducha chcem.<br/>ó, nech tečie!<br/>',NULL,130367,1);
INSERT INTO stanza VALUES('SK846','2','Ó, nech môj duch tečie,<br/>ó, nech tečie!<br/>Žiadam Ťa pokorne,<br/>ó, nech tečie!<br/>Nie samoľúbym byť,<br/>ani pyšným nebyť,<br/>ducha vyslobodiť.<br/>ó, nech tečie!<br/>',NULL,130368,2);
INSERT INTO stanza VALUES('SK846','3','Ó, nech môj duch tečie,<br/>ó, nech tečie!<br/>Teba prosím, Pane,<br/>ó, nech tečie!<br/>Nebyť namyslený,<br/>pýchou uväznený,<br/>prúdom neprestajným,<br/>ó, nech tečiem!<br/>',NULL,130369,3);
INSERT INTO stanza VALUES('SK846','4','Ó, nech môj duch tečie,<br/>ó, nech tečie!<br/>Teba hľadám, Pane,<br/>ó, nech tečie!<br/>Nebyť uzavretým<br/>či sám dokonalým,<br/>v duchu ma posilni,<br/>ó, nech tečie!<br/>',NULL,130370,4);
INSERT INTO stanza VALUES('SK846','5','Ó, nech môj duch tečie,<br/>ó, nech tečie!<br/>Prosím Ťa, môj Pane,<br/>ó, nech tečie!<br/>V seba nedúfam viac,<br/>nie som na tróne viac,<br/>nechávam prúd len tiecť<br/>v duchu, Pane!<br/>',NULL,130371,5);
INSERT INTO stanza VALUES('SK846','6','Ó, nech môj duch tečie,<br/>ó, nech tečie!<br/>Vyslyš mi modlitby,<br/>ó, nech tečie!<br/>Nie iba ja a Ty,<br/>no byť budovaný,<br/>v duchu s inými byť<br/>zmiešavaný.<br/>',NULL,130372,6);
INSERT INTO stanza VALUES('SK847','1','Túžim po spoločenstve v duchu,<br/>byť so svätými zmiešaný,<br/>zachránený z nezávislosti,<br/>so svätými budovaný.<br/>',NULL,130373,1);
INSERT INTO stanza VALUES('SK847','2','Túžim po spoločenstve v duchu,<br/>otvoreného ducha mať,<br/>od samoty oslobodený,<br/>so svätými Ťa uctievať.<br/>',NULL,130374,2);
INSERT INTO stanza VALUES('SK847','3','Túžim po spoločenstve v duchu,<br/>môj duch, aby sa uvoľnil,<br/>zachránený od sebaklamu,<br/>’by som prekážky prekonal.<br/>',NULL,130375,3);
INSERT INTO stanza VALUES('SK847','4','Túžim po spoločenstve v duchu<br/>a so svätými sa modliť,<br/>zachránený od predstierania,<br/>spoločenstvo pravé chcem mať.<br/>',NULL,130376,4);
INSERT INTO stanza VALUES('SK847','5','Túžim po spoločenstve v duchu<br/>a tak autoritu poznať.<br/>túžim po spoločenstve v službe,<br/>spolu sa koordinovať.<br/>',NULL,130377,5);
INSERT INTO stanza VALUES('SK847','6','Ó, Pane, naplň naše túžby,<br/>pre spoločenstvo inšpiruj,<br/>chceme naplniť Tvoje túžby,<br/>’by sme boli Tvojou stavbou.<br/>',NULL,130378,6);
INSERT INTO stanza VALUES('SK848','1','Výsadou, požehnaním je<br/>kráľovskými kňazmi byť,<br/>Boh volá do služby slávnej,<br/>hoci sme nepatrní.<br/>',NULL,130379,1);
INSERT INTO stanza VALUES('SK848','chorus','Budovanie Jeho Tela<br/>od kňazstva je závislé.<br/>Sústavnou modlitbou v duchu<br/>zúčastním sa na službe.<br/>',NULL,130380,2);
INSERT INTO stanza VALUES('SK848','2','Pod autoritou ak chránim<br/>kráľovské povolanie,<br/>tak napĺňam službu kňaza<br/>a cirkev sa buduje.<br/>',NULL,130381,3);
INSERT INTO stanza VALUES('SK848','3','Sformovať kňazstvo musíme,<br/>lebo cirkev kňazstvom je.<br/>Ak kňazi prepletení sú,<br/>nastane budovanie.<br/>',NULL,130382,4);
INSERT INTO stanza VALUES('SK848','4','Spustnuté kňazstvo svätých je<br/>vinou úpadku cirkvi.<br/>Kázania dnes prevažujú,<br/>v duchu sme veľmi slabí.<br/>',NULL,130383,5);
INSERT INTO stanza VALUES('SK848','5','Dôraz dávame na kázne<br/>a na rôzne učenia,<br/>nemodlíme sa však kňazsky,<br/>nezapájame ducha.<br/>',NULL,130384,6);
INSERT INTO stanza VALUES('SK848','6','Pracuj na mne, vyvažuj ma,<br/>v kázaní aj modlitbe.<br/>Nech iných k modleniu vediem,<br/>keď slovo ohlasujem.<br/>',NULL,130385,7);
INSERT INTO stanza VALUES('SK848','7','Len ak slúžime modlitbou,<br/>náš duch bude zmiešaný.<br/>Modlitbou sa cirkev stavia<br/>a tiež ohlasovaním.<br/>',NULL,130386,8);
INSERT INTO stanza VALUES('SK851','1','Tvoj príbytok je nádherný!<br/>Túžim byť v Tvojich nádvoriach,<br/>môj duch len po Tebe baží,<br/>po Tebe mi srdce volá.<br/>',NULL,130387,1);
INSERT INTO stanza VALUES('SK851','2','Tam, pri obetnom oltári<br/>a kadidlovom oltári,<br/>aj vrabec nájde svoj domov,<br/>lastovička hniezdo tvorí.<br/>',NULL,130388,2);
INSERT INTO stanza VALUES('SK851','3','Sme ako vrabce, slabučkí,<br/>v Tvojom dome sme v bezpečí.<br/>máme tu krv na oltári,<br/>kadidlom sme požehnaní.<br/>',NULL,130389,3);
INSERT INTO stanza VALUES('SK851','4','Skutočne blahoslavení,<br/>ktorých sila je len v Tebe.<br/>na Sion v ich srdciach cesty,<br/>hoc často sú namáhavé.<br/>',NULL,130390,4);
INSERT INTO stanza VALUES('SK851','5','Dolinou plaču kráčajúc,<br/>na prameň ju premieňajú,<br/>dážď požehnania tam majú,<br/>len o Bohu rozprávajú.<br/>',NULL,130391,5);
INSERT INTO stanza VALUES('SK851','6','Od sily k sile kráčajú,<br/>na Sione sa s Ním stretnú.<br/>tí, čo len Pána hľadajú,<br/>Jeho túžby znásobujú.<br/>',NULL,130392,6);
INSERT INTO stanza VALUES('SK851','7','Lepší je deň v Tvojich sieňach<br/>ako tisíce iných dní.<br/>Radšej na Tvojom prahu stáť,<br/>než byť v stanoch bezbožnosti.<br/>',NULL,130393,7);
INSERT INTO stanza VALUES('SK851','8','Ty si slnkom, Ty si štítom,<br/>milosť, slávu udeľuješ.<br/>Prítomnosť Tvoja a Ty sám<br/>ma plne uspokojuješ.<br/>',NULL,130394,8);
INSERT INTO stanza VALUES('SK851','9','Žiadne dobro neodoprieš<br/>tým, čo kráčajú v priamosti.<br/>ten, čo má nádej len v Tebe,<br/>požehnaný je bez miery.<br/>',NULL,130395,9);
INSERT INTO stanza VALUES('SK852','1','Ľúbim Tvoj príbytok, Pane,<br/>požehnanú Cirkev.<br/>máš v nej zaľúbenie, radosť<br/>a odpočinutie.<br/>',NULL,130396,1);
INSERT INTO stanza VALUES('SK852','2','Sám seba si vydal za ňu,<br/>’by Ťa doplnila.<br/>tiež sa jej dám, aby Tvoju<br/>túžbu naplnila.<br/>',NULL,130397,2);
INSERT INTO stanza VALUES('SK852','3','Pre ňu si môj život, aby<br/>bola mojím žitím.<br/>kvôli nej sám seba zapriem,<br/>’by si ju naplnil.<br/>',NULL,130398,3);
INSERT INTO stanza VALUES('SK852','4','Cirkev je Tvojou Nevestou,<br/>Telo vyjadrením,<br/>ona je tiež mojou túžbou,<br/>na cirkvi závisím.<br/>',NULL,130399,4);
INSERT INTO stanza VALUES('SK852','5','V nej zaopatrenie plné<br/>dávaš mi, ó, Pane,<br/>v nej ma vlastníš, srdce Tvoje<br/>týmto potešujem.<br/>',NULL,130400,5);
INSERT INTO stanza VALUES('SK852','6','Ľúbim Tvoj príbytok, Pane,<br/>Tvoj dom, Tvoju Cirkev.<br/>V nej chcem prebývať naveky,<br/>túlať sa nebudem.<br/>',NULL,130401,6);
INSERT INTO stanza VALUES('SK853','1','Kráľovstvo milujem,<br/>Tvoj príbytok, Tvoj dom,<br/>cirkev ktorú si vykúpil,<br/>Pane vzácnou krvou.<br/>',NULL,130402,1);
INSERT INTO stanza VALUES('SK853','2','Ľúbim cirkev Bože!<br/>Jej hradby mohutné,<br/>je Ti vzácna sťa zrenica,<br/>vyrytá na ruke.<br/>',NULL,130403,2);
INSERT INTO stanza VALUES('SK853','3','Pre cirkev nariekam,<br/>za cirkev sa modlím,<br/>o cirkev sa budem starať,<br/>za cirkev sa borím.<br/>',NULL,130404,3);
INSERT INTO stanza VALUES('SK853','4','Nad najvyššiu radosť,<br/>si jej cesty cením,<br/>jej spoločenstvo, modlitby,<br/>hymny lásky, chvály.<br/>',NULL,130405,4);
INSERT INTO stanza VALUES('SK853','5','Ako pravda večná,<br/>Sionu je dané<br/>najjasnejšie požehnanie,<br/>aj blaho nebeské.<br/>',NULL,130406,5);
INSERT INTO stanza VALUES('SK864','1','Vždy, keď sa spolu schádzame,<br/>tak niečo z Krista nesieme,<br/>pokrm Bohu prinášajme –<br/>Krista ukazujme.<br/>',NULL,130407,1);
INSERT INTO stanza VALUES('SK864','chorus','Krista ukazujme.<br/>Krista ukazujme.<br/>Do cirkvi Ho prinášajme.<br/>Krista ukazujme.<br/>',NULL,130408,2);
INSERT INTO stanza VALUES('SK864','2','V Ňom žijeme, bojujeme,<br/>stále na Ňom pracujeme,<br/>z Jeho nadbytku jedno sme –<br/>Krista ukazujme.<br/>',NULL,130409,3);
INSERT INTO stanza VALUES('SK864','3','Život, dielo, to, čím my sme,<br/>pre nás všetkým tým sám On je,<br/>a preto, keď sa zídeme –<br/>Krista ukazujme.<br/>',NULL,130410,4);
INSERT INTO stanza VALUES('SK864','4','Bohu Krista prinášame<br/>a vzájomne Ho zdieľame,<br/>s Bohom sa z Neho tešíme –<br/>Krista ukazujme.<br/>',NULL,130411,5);
INSERT INTO stanza VALUES('SK864','5','Vzkrieseného prinášame,<br/>Vyvýšeného dávame,<br/>Boha Kristom potešíme –<br/>Krista ukazujme.<br/>',NULL,130412,6);
INSERT INTO stanza VALUES('SK864','6','Skutočnosťou a centrom je,<br/>arómou zhromaždenia je,<br/>je naše vysluhovanie –<br/>Krista ukazujme.<br/>',NULL,130413,7);
INSERT INTO stanza VALUES('SK864','7','Zdieľanie, modlitby všetky,<br/>aj naše svedectvá všetky,<br/>užívanie darov všetkých –<br/>ukázať Ho musí.<br/>',NULL,130414,8);
INSERT INTO stanza VALUES('SK864','8','Otca chceme oslavovať<br/>a tak Krista vyzdvihovať,<br/>cieľ stretnutí dosahovať –<br/>Krista ukazovať.<br/>',NULL,130415,9);
INSERT INTO stanza VALUES('SK866','1','Cvičme svojho ducha!<br/>Nie myseľ svoju.<br/>Pre život Tela sa<br/>schádzajme spolu.<br/>',NULL,130416,1);
INSERT INTO stanza VALUES('SK866','2','Cvičme svojho ducha!<br/>Bez foriem a schém.<br/>Zdieľajme navzájom<br/>všetci Krista diel.<br/>',NULL,130417,2);
INSERT INTO stanza VALUES('SK866','3','Cvičme svojho ducha!<br/>Prirodzenosť nie.<br/>Slúžme si navzájom,<br/>Krista zjavujme.<br/>',NULL,130418,3);
INSERT INTO stanza VALUES('SK866','4','Cvičme svojho ducha!<br/>Nie život duše.<br/>Dôverovať Jemu<br/>spolu sa učme.<br/>',NULL,130419,4);
INSERT INTO stanza VALUES('SK866','5','V duchu slobodní sme<br/>z našej dobroty,<br/>aj od odsúdenia<br/>a hanblivosti.<br/>',NULL,130420,5);
INSERT INTO stanza VALUES('SK866','6','V duchu slobodní sme<br/>od sebalásky,<br/>pýchy, vlastnej vôle.<br/>prejdeme všetkým.<br/>',NULL,130421,6);
INSERT INTO stanza VALUES('SK866','7','Cvičme svojho ducha!<br/>Máme víťazstvo<br/>skrze Pánovu krv<br/>a Jeho meno.<br/>',NULL,130422,7);
INSERT INTO stanza VALUES('SK866','8','Cvičme svojho ducha!<br/>S Pánom sa spojme.<br/>svojím duchom v Slove<br/>Ho prijímajme.<br/>',NULL,130423,8);
INSERT INTO stanza VALUES('SK866','9','Jedine cez ducha<br/>Pán dosvedčený.<br/>Jedine cez ducha<br/>človek spokojný.<br/>',NULL,130424,9);
INSERT INTO stanza VALUES('SK866','10','Cvičme svojho ducha!<br/>To je potrebné!<br/>Ku cvičeniu ducha<br/>Pán nech nás vedie!<br/>',NULL,130425,10);
INSERT INTO stanza VALUES('SK867','1','My, ako údy Tela,<br/>Krista ukazujme.<br/>Učme sa byť funkčnými,<br/>Jeho vyjadrujme.<br/>nebyť divákmi, ale<br/>byť údmi živými.<br/>smrť, skazu, neprinášať,<br/>byť užitočnými.<br/>',NULL,130426,1);
INSERT INTO stanza VALUES('SK867','2','My, ako tím, nesmieme<br/>konať nezávisle.<br/>na koordinácii<br/>musíme závisieť.<br/>nevyberať, čo chceme,<br/>no prúd nasledovať.<br/>prekážky neprinášať,<br/>cestu Ducha poznať.<br/>',NULL,130427,2);
INSERT INTO stanza VALUES('SK867','3','Sústreďme sa na Krista,<br/>nič nečiňme stredom.<br/>tešme sa s Ním z bohatstiev,<br/>v spoločenstve sladkom.<br/>Je Hlavou aj obsahom,<br/>vyjadrujeme Ho,<br/>na stretnutí musí Ho<br/>byť vo všetkom vidno.<br/>',NULL,130428,3);
INSERT INTO stanza VALUES('SK867','4','V láske spolu budujme<br/>bez kritizovania<br/>a vzájomne sa cvičme,<br/>zdokonaľujme sa.<br/>Od nášho ja slobodní,<br/>od života duše,<br/>v duchu sme trénovaní,<br/>život Tela žime.<br/>',NULL,130429,4);
INSERT INTO stanza VALUES('SK881','1','V Tebe spočívame, si štít, ochranca,<br/>vždy len s Tebou do boja kráčame.<br/>v Tebe mocní, v nehe Tvojej bezpeční,<br/>v Tebe spočívame a kráčame.<br/>',NULL,130430,1);
INSERT INTO stanza VALUES('SK881','2','Si Vodcom spásy, chcem prebývať v Tebe,<br/>v Tvojom mene, čo nad všetkými znie.<br/>Ježiš je základom pevným, zdrojom je,<br/>je Knieža slávy, Kráľom lásky tiež.<br/>',NULL,130431,2);
INSERT INTO stanza VALUES('SK881','3','Vo viere kráčame, slabí hoci sme,<br/>milosť poznávať potrebujeme.<br/>No aj tak pieseň víťazná v srdciach znie,<br/>v Tebe spočívame a kráčame.<br/>',NULL,130432,3);
INSERT INTO stanza VALUES('SK881','4','V Tebe spočívame, si štít, ochranca,<br/>Tvoj je ten zápas, Tvoja chvála tiež.<br/>Keď Tvojho kráľovstva už vláda príde,<br/>v Tebe spočívať navždy budeme.<br/>',NULL,130433,4);
INSERT INTO stanza VALUES('SK885','1','Zápasíme iba v Tele,<br/>nikdy nie samostatne.<br/>Spolu s Telom, jedno s Hlavou,<br/>zápasíme na tróne.<br/>',NULL,130434,1);
INSERT INTO stanza VALUES('SK885','chorus','Zápasíme iba v Tele,<br/>Pánovou mocou Hlavy,<br/>ak stojíš napevno s Telom,<br/>stále budeš víťazný.<br/>',NULL,130435,2);
INSERT INTO stanza VALUES('SK885','2','Božia výzbroj je pre Telo,<br/>nie je pre jednotlivcov.<br/>Zápasiť keď budeš v Tele,<br/>stále bude pomocou.<br/>',NULL,130436,3);
INSERT INTO stanza VALUES('SK885','3','Nepremôže Satan Cirkev<br/>Kristom ustanovenú.<br/>Telo spolu zbudované,<br/>len to odolá Zlému.<br/>',NULL,130437,4);
INSERT INTO stanza VALUES('SK885','4','V Tele, Kristom ako Hlavou<br/>v nebesiach usadení.<br/>Zápasíme s mocnosťami,<br/>zlý duch je porazený.<br/>',NULL,130438,5);
INSERT INTO stanza VALUES('SK885','5','Ako súčasť Jeho Tela,<br/>za Boha spolu stojme.<br/>Stále sa modlime v Duchu,<br/>Jeho krvou zvíťazme.<br/>',NULL,130439,6);
INSERT INTO stanza VALUES('SK885','6','Viac než víťazi v nebesiach<br/>sme v sile Jeho moci.<br/>Bojujeme v Jeho vojsku,<br/>Pánovi sme vojaci.<br/>',NULL,130440,7);
INSERT INTO stanza VALUES('SK885','7','Pokračujme v boji,<br/>v Tele, zvíťazíme spoločne.<br/>Zväzujme a rozväzujme,<br/>nepriateľov pojedzme.<br/>',NULL,130441,8);
INSERT INTO stanza VALUES('SK887','1','Postavenie v Ježišovi<br/>je víťazstvom naším,<br/>na Teba sa spoliehame,<br/>Ty Pánom si mocným.<br/>Nie sú to zbrane telesné,<br/>lež meč Ducha máme.<br/>Božou zbrojou zaodetí,<br/>Pánom bojujeme.<br/>',NULL,130442,1);
INSERT INTO stanza VALUES('SK887','2','Hľa, nepriateľ spriada plány,<br/>buďme jednej mysle!<br/>Hoc boj krutý a tma hustá,<br/>v Pánovi vzdorujme!<br/>Ten, kto pred bojom zuteká,<br/>spochybňuje iných.<br/>Neoslabuj svojich bratov,<br/>nech nie sú skľúčení.<br/>',NULL,130443,2);
INSERT INTO stanza VALUES('SK887','3','Čas sa kráti, diabol to vie,<br/>je viac rozzúrený,<br/>pred tým ako sa boj začne,<br/>on nás chce oslabiť.<br/>Aj skúšok je dnes viac a viac,<br/>ťažších utrpení,<br/>sily pekla sú proti nám,<br/>viac než boli predtým.<br/>',NULL,130444,3);
INSERT INTO stanza VALUES('SK887','4','Aký by mal byť náš postoj<br/>vo vážnom období?<br/>Hľadať komfort a pohodlie,<br/>’by nás pohltil Zlý?<br/>Či keď sa konflikt zostruje,<br/>odvážne vydržať?<br/>Ide tu o život a smrť!<br/>Kto oslávi Boha?<br/>',NULL,130445,4);
INSERT INTO stanza VALUES('SK887','5','Za Krista sa postavíme,<br/>náš Pán je Víťazom!<br/>Pre Neho bolesť znášame,<br/>v každom zo zápasov.<br/>Čas víťazstva je rýchle tu —<br/>náš Pán príde znovu.<br/>Ak dnes pre Neho strádame,<br/>budeme s Ním vládnuť.<br/>',NULL,130446,5);
INSERT INTO stanza VALUES('SK890','1','Aleluja! Pán je Víťaz,<br/>stále ohlasuj.<br/>Víťazí nad hriechom, smrťou,<br/>stále vyhlasuj.<br/>',NULL,130447,1);
INSERT INTO stanza VALUES('SK890','chorus','Aleluja! Pán je Víťaz,<br/>stále ohlasuj.<br/>Pán Ježiš, On víťazí vždy,<br/>stále vyhlasuj.<br/>',NULL,130448,2);
INSERT INTO stanza VALUES('SK890','2','Aleluja! Pán je Víťaz,<br/>preč nemoc musí.<br/>Keď vyhlasujeme Kristov<br/>triumf na kríži.<br/>',NULL,130449,3);
INSERT INTO stanza VALUES('SK890','3','Aleluja! Pán je Víťaz,<br/>smelo sa modli.<br/>Kam ťa Ježiš pošle, choď,<br/>víťazstvo dosiahni.<br/>',NULL,130450,4);
INSERT INTO stanza VALUES('SK890','4','Aleluja! Pán je Víťaz,<br/>žiaden strach, prehry.<br/>Pán je s nami, víziu nám<br/>nik nezatieni.<br/>',NULL,130451,5);
INSERT INTO stanza VALUES('SK890','5','Aleluja! Pán je Víťaz,<br/>skoro zaznie hlas:<br/>„Víťazi, vystúpte hore,<br/>Pán čaká na vás“.<br/>',NULL,130452,6);
INSERT INTO stanza VALUES('SK893','1','Zúri dnes tuhý boj<br/>a Satan bojuje.<br/>Dnes mocne hlas boja volá<br/>a naliehavo znie.<br/>Hlas pekla sa zdvíha,<br/>počuť ho stále viac,<br/>no polnočný krik zaznieva:<br/>„Hľa, skoro prichádzam.“<br/>',NULL,130453,1);
INSERT INTO stanza VALUES('SK893','2','Skúšky sa zhoršujú<br/>a boj sa zväčšuje.<br/>pekelné sily zbierajú<br/>všetky sily svoje.<br/>No zatiaľ čo bdieme<br/>a vojnu cítime,<br/>pieseň radostnú čujeme,<br/>Pán Ježiš blízko je.<br/>',NULL,130454,2);
INSERT INTO stanza VALUES('SK893','3','Na konci je ťažké<br/>Slovo dosvedčovať,<br/>pretože Satan sa snaží<br/>svätých umlčovať.<br/>Viac sily nám treba<br/>prekonať Satana,<br/>akí radostní budeme,<br/>keď zbadáme Pána.<br/>',NULL,130455,3);
INSERT INTO stanza VALUES('SK893','4','Kto teda pôjde vpred<br/>v Jeho sile mocnej?<br/>Kto sa spoľahne na Pána,<br/>vytrvá do konca,<br/>kým pieseň víťazov<br/>sa slávne rozoznie?<br/>Tak ten sa bude radovať,<br/>že Pán skoro príde.<br/>',NULL,130456,4);
INSERT INTO stanza VALUES('SK893','5','Kto si zvolí Boha,<br/>úzkou cestou pôjde?<br/>Kto prekoná všetky búrky<br/>a z cesty nezíde?<br/>Kto odváži sa ísť,<br/>strach, bolesť vydrží?<br/>Taký sa bude radovať,<br/>keď Pána uvidí.<br/>',NULL,130457,5);
INSERT INTO stanza VALUES('SK893','6','Aj cez tmu hlbokú<br/>dopredu pôjdeme,<br/>kým k uchváteniu prídeme<br/>a v sláve budeme.<br/>Tam Pána uzrieme,<br/>diabla porazíme<br/>a budeme sa radovať,<br/>že náš Pán už prišiel.<br/>',NULL,130458,6);
INSERT INTO stanza VALUES('SK894','1','Chcel by si sa víťazom stať?<br/>Kristus ťa volá!<br/>Pána budeš nasledovať,<br/>či sa len schováš?<br/>',NULL,130459,1);
INSERT INTO stanza VALUES('SK894','chorus','Chcel by si sa víťazom stať?<br/>Kto si to zvolí?<br/>Pán Ježiš nás povoláva,<br/>buďme vnímaví!<br/>',NULL,130460,2);
INSERT INTO stanza VALUES('SK894','2','Chcel by si sa víťazom stať?<br/>Vráť sa k Pánovi!<br/>Lásku najlepšiu zachovaj<br/>kým sa rozbrieždi.<br/>',NULL,130461,3);
INSERT INTO stanza VALUES('SK894','3','Chcel by si sa víťazom stať?<br/>Jeho život máš!<br/>Znášaj Jeho utrpenia,<br/>vydrž dokonca.<br/>',NULL,130462,4);
INSERT INTO stanza VALUES('SK894','4','Chcel by si sa víťazom stať?<br/>Pána dosvedčuj!<br/>Náboženstvo je falošné,<br/>jedz mannu skrytú.<br/>',NULL,130463,5);
INSERT INTO stanza VALUES('SK894','5','Chcel by si sa víťazom stať,<br/>rýdzim, skutočným?<br/>Víťaz dnes nad prímesami,<br/>vládnuť budeš s Ním.<br/>',NULL,130464,6);
INSERT INTO stanza VALUES('SK894','6','Chcel by si sa víťazom stať?<br/>Pánovi vždy ver!<br/>Chráň si rúcho pred starobou,<br/>život dostaneš.<br/>',NULL,130465,7);
INSERT INTO stanza VALUES('SK894','7','Chcel by si sa víťazom stať?<br/>Stráň sa vlažnosti.<br/>Nepovedz si: „už všetko mám,“<br/>viac otvor oči.<br/>',NULL,130466,8);
INSERT INTO stanza VALUES('SK894','8','Chcel by si sa víťazom stať?<br/>Pán volá aj dnes!<br/>Buď Mu verný, nápomocný,<br/>naplň to, čo chce.<br/>',NULL,130467,9);
INSERT INTO stanza VALUES('SK899','1','Dielo je Tvoje, náš Pane,<br/>len preto sme pevní.<br/>Je Tvoje, preto zvíťazí,<br/>ó, nad nepriateľmi.<br/>Pšenica prv než rásť bude<br/>je pochovaná do zeme.<br/>V zemi umrie staré čo je,<br/>nový život z nej povstane.<br/>Tak sme aj my od „ja“, hriechu voľní.<br/>',NULL,130468,1);
INSERT INTO stanza VALUES('SK899','2','Utrpenia Ťa doviedli,<br/>ó, Kriste až na trón.<br/>Vierou a láskou tých verných<br/>dnes vedieš rovnako.<br/>Veď nás, hoc príde súženie,<br/>nech máme v kráľovstve podiel.<br/>Smrťou si zničil Satana,<br/>verných smrť vedie do svetla,<br/>svetlo večné, z tmy do svetla vedie.<br/>',NULL,130469,2);
INSERT INTO stanza VALUES('SK899','3','Agóniou, smrťou prešiel<br/>náš Pán ako prvý.<br/>Svojho Ducha daj nám viacej,<br/>úprimne Ťa prosím!<br/>Pošli všade poslov svojich,<br/>nech privedú domov Tvojich.<br/>Môžeš spasiť, oslobodiť,<br/>my zasväcujeme sa Ti<br/>verne slúžiť, bojovať, smelí byť.<br/>',NULL,130470,3);
INSERT INTO stanza VALUES('SK904','1','Slávneho Kráľa máme my.<br/>trónom Jeho nebesia sú,<br/>vládne nad všetkými svetmi,<br/>má nad kráľovstvami vládu.<br/>Býva tu na zemi s ľuďmi,<br/>znáša tu s nami ťažkosti,<br/>Jeho bremeno nesieme,<br/>kvôli Jeho práci sme s Ním.<br/>',NULL,130471,1);
INSERT INTO stanza VALUES('SK904','2','S Kráľom – Ježišom prebývam,<br/>s tými, čo v Jeho dome sú,<br/>dvere srdca Mu otváram,<br/>aby v ňom mal domov aj trón.<br/>Pánovi sedím pri nohách,<br/>na hrudi Mu odpočívam,<br/>s Ním je vždy radosť úplná,<br/>v náručí Jeho pokoj mám.<br/>',NULL,130472,2);
INSERT INTO stanza VALUES('SK904','3','Kvôli Jeho práci som s Ním,<br/>účasť na Jeho pláne mám.<br/>kráľovstvo Jeho nech príde,<br/>spásu Jeho ohlasujem.<br/>Práce mnoho je vo svete,<br/>tú však za stratu pokladám.<br/>túžim len po Jeho diele,<br/>kríž, ten je mojím posolstvom.<br/>',NULL,130473,3);
INSERT INTO stanza VALUES('SK904','4','Kvôli Jeho práci som s Ním,<br/>dielo je Jeho, nie moje.<br/>plánuje a pripravuje,<br/>Svojou mocou naplňuje.<br/>Bremeno je potešením,<br/>v chválu sa modlitba mení.<br/>kvôli Jeho práci som s Ním,<br/>konám Jeho posilnením.<br/>',NULL,130474,4);
INSERT INTO stanza VALUES('SK904','5','Kvôli Jeho práci sme s Ním,<br/>stále spolu pracujeme.<br/>V sláve možnože sa zjaví,<br/>kým spolu s Ním pracujeme.<br/>Pán nás tak v objatie vezme,<br/>prácu nám dá vznešenejšiu,<br/>sídliť s Kráľom vždy budeme,<br/>zdieľať radosť nekonečnú!<br/>',NULL,130475,5);
INSERT INTO stanza VALUES('SK907','1','Nie kam chceme, ideme,<br/>ale kam Ježiš vedie.<br/>tam živá voda tečie,<br/>naša temnota mizne.<br/>',NULL,130476,1);
INSERT INTO stanza VALUES('SK907','2','Samozvané dielo nám<br/>nikdy neschváli náš Pán.<br/>na diele, čo určil On,<br/>pokorne sa namáham.<br/>',NULL,130477,2);
INSERT INTO stanza VALUES('SK907','3','Nemodliť sa, čo chceme,<br/>klaňajúc sa pred trónom,<br/>no potreby Ducha v nás<br/>dotýkať sa hlboko.<br/>',NULL,130478,3);
INSERT INTO stanza VALUES('SK907','4','Nevšimne si dar taký,<br/>čo hrdo prinášame,<br/>ak na Jeho potreby<br/>v srdci hovoríme „nie“.<br/>',NULL,130479,4);
INSERT INTO stanza VALUES('SK907','5','Umierajúc žijeme<br/>v nebesiach spolu s Pánom.<br/>v službe, modlitbách, daroch,<br/>Kristus nám je odmenou.<br/>',NULL,130480,5);
INSERT INTO stanza VALUES('SK909','1','V prúde len! V prúde len! Pracujme pre Neho<br/>len Jeho spôsobom v Slove odhalenom.<br/>v prúde života pracujme silou Jeho,<br/>pre Jeho kráľovstvo, pre cirkev v dňoch Jeho!<br/>',NULL,130481,1);
INSERT INTO stanza VALUES('SK909','chorus','V prúde len! V prúde len!<br/>Pracujme v prúde len!<br/>V prúde len! V prúde len!<br/>Tímom nebeským budeme!<br/>',NULL,130482,2);
INSERT INTO stanza VALUES('SK909','2','V prúde len! V prúde len! S Pánom vždy pracujme<br/>v Ducha prúde a tiež so Slovom v súlade.<br/>nikdy nie zo seba, voľne, nezávisle,<br/>no v harmónii slúžme spolu úplnej.<br/>',NULL,130483,3);
INSERT INTO stanza VALUES('SK909','3','V prúde len! V prúde len! V Pánovi pracujme!<br/>So svätými, s cirkvou podľa Neho v Slove.<br/>dávaj Slovo ľuďom, život ním odovzdaj,<br/>jedine v prúde tom naplní Boh Svoj plán.<br/>',NULL,130484,4);
INSERT INTO stanza VALUES('SK910','1','Pretekanie života je<br/>dielo, to má byť žitím!<br/>Slová, ktoré prednášame,<br/>musia niesť skúsenosť s Ním.<br/>Keď žitie s dielom sú jedno,<br/>to dielo účinok má.<br/>Ak slovo životom bude,<br/>úspešnosť bude istá.<br/>',NULL,130485,1);
INSERT INTO stanza VALUES('SK910','2','Dielo musí byť ovocím<br/>života, toku Ducha.<br/>Sťa ratolesť na Pánovi,<br/>ktorá ovocie núka.<br/>Sám Kristus cez nás pôsobí,<br/>Svoj život vyjadruje.<br/>Bohatstvo Jeho života<br/>iným sa prejavuje.<br/>',NULL,130486,2);
INSERT INTO stanza VALUES('SK910','3','Toto nie je ľudské hnutie,<br/>no pohyb Jeho moci.<br/>Nie sú to skutky navonok,<br/>no Jeho práca vnútri.<br/>Nie sú to naše zásluhy,<br/>no svedectvo života.<br/>Ani snaha byť úspešní,<br/>no vyjadrenie Pána.<br/>',NULL,130487,3);
INSERT INTO stanza VALUES('SK910','4','Naše ciele, plány, snahy<br/>musíme zanechávať.<br/>Nech Pán môže Svoj cieľ a plán<br/>cez nás uskutočňovať.<br/>Čo sme a to, čo máme my,<br/>vydávame to smrti.<br/>Nech Kristus môže žiť cez nás,<br/>slávnymi bohatstvami.<br/>',NULL,130488,4);
INSERT INTO stanza VALUES('SK911','1','Blažený je život kňaza,<br/>Kristus je preňho všetkým,<br/>odevom, potravou, domom<br/>a všetkými podielmi.<br/>',NULL,130489,1);
INSERT INTO stanza VALUES('SK911','chorus','Blažený je život kňaza,<br/>Kristus je preňho všetkým,<br/>odevom, potravou, domom<br/>a všetkými podielmi.<br/>',NULL,130490,2);
INSERT INTO stanza VALUES('SK911','2','Oblečenia kňaza v službe<br/>krásu Pána zjavujú,<br/>náprsník a náplecníky<br/>nádheru mu dávajú.<br/>',NULL,130491,3);
INSERT INTO stanza VALUES('SK911','3','Keď prináša Krista Bohu,<br/>ako si to Boh želá,<br/>získava Ho ako pokrm,<br/>vzácnosť Krista v sebe má.<br/>',NULL,130492,4);
INSERT INTO stanza VALUES('SK911','4','Tým, že si oblieka Pána,<br/>navonok Ho vyjadrí,<br/>tým, že Pána je a pije,<br/>zvnútra si ho privlastní.<br/>',NULL,130493,5);
INSERT INTO stanza VALUES('SK911','5','Príbytok ich slávny, svätý,<br/>Pána ním rozširujú,<br/>kňazi sú v ňom budovaní,<br/>Bohu dom poskytujú.<br/>',NULL,130494,6);
INSERT INTO stanza VALUES('SK911','6','Podiel kňaza, jeho žitie<br/>a všetko, čo kňaz vlastní,<br/>je len sám Kristus naveky,<br/>v Jeho všeobsažnosti.<br/>',NULL,130495,7);
INSERT INTO stanza VALUES('SK912','1','Kristom slúžiť, to je služba<br/>pre Boha aj človeka.<br/>keď iným Krista predávaš,<br/>to je tá služba pravá.<br/>',NULL,130496,1);
INSERT INTO stanza VALUES('SK912','chorus','Kristom slúžiť, to je služba<br/>pre Boha aj človeka.<br/>keď iným Krista predávaš,<br/>to je tá služba pravá.<br/>',NULL,130497,2);
INSERT INTO stanza VALUES('SK912','2','Ľud Boží dary prinášal<br/>z hojnosti dobrej zeme,<br/>pre iných tak niečo z Krista<br/>my v rukách mať musíme.<br/>',NULL,130498,3);
INSERT INTO stanza VALUES('SK912','3','My na Pánovi, tej zemi,<br/>vždy musíme pracovať.<br/>vychutnávať Pána stále,<br/>s ostatnými Ho zdieľať.<br/>',NULL,130499,4);
INSERT INTO stanza VALUES('SK912','4','Držiac sa Krista rastieme,<br/>máme rôzne funkcie.<br/>máme účasť na Kristovi,<br/>Telu Pánom slúžime.<br/>',NULL,130500,5);
INSERT INTO stanza VALUES('SK912','5','Spoločenstvo a svedectvo,<br/>služba a uctievanie,<br/>Kristus Pán je našou službou,<br/>vo všetkom, čo sa deje.<br/>',NULL,130501,6);
INSERT INTO stanza VALUES('SK913','1','V Tele slúžiť a pracovať,<br/>Pán to dáva najavo,<br/>s tým musíme v zhode konať,<br/>Jeho zámer je Telo.<br/>',NULL,130502,1);
INSERT INTO stanza VALUES('SK913','chorus','Slúžme a pracujme v Tele,<br/>nebuďme nezávislí,<br/>ako údy v Jeho Tele<br/>buďme spoločne funkční.<br/>',NULL,130503,2);
INSERT INTO stanza VALUES('SK913','2','Neboli sme oživení<br/>pre akúsi slobodu,<br/>ale aby sme slúžili,<br/>mali zhodu vzájomnú.<br/>',NULL,130504,3);
INSERT INTO stanza VALUES('SK913','3','Zo živých kameňov bude<br/>dom Boží postavený,<br/>sme sväté kňazstvo, tak slúžme<br/>spoločne v harmónii.<br/>',NULL,130505,4);
INSERT INTO stanza VALUES('SK913','4','Spoločne vybudovaní,<br/>v tom stave posluhovať,<br/>lebo základ našej služby<br/>má charakter Tela mať.<br/>',NULL,130506,5);
INSERT INTO stanza VALUES('SK913','5','Ak posluhujeme v Tele,<br/>máme zaopatrenie,<br/>keby sme sa odpojili,<br/>istotne zahynieme.<br/>',NULL,130507,6);
INSERT INTO stanza VALUES('SK913','6','Bohatstiev Hlavy sme plní,<br/>tým, že slúžime v Tele,<br/>fungujeme ako údy,<br/>plnosť Krista nesieme.<br/>',NULL,130508,7);
INSERT INTO stanza VALUES('SK913','7','Aby sme spoločne rástli,<br/>Hlavy sa držme pevne,<br/>takto nás On zaopatrí,<br/>do Tela z nás potečie.<br/>',NULL,130509,8);
INSERT INTO stanza VALUES('SK913','8','Dávame sa Ti nanovo,<br/>chceme byť premenení,<br/>poznať Tvoju vôľu, Telo,<br/>ostať v posluhovaní.<br/>',NULL,130510,9);
INSERT INTO stanza VALUES('SK914','1','Naše slúženie pre cirkev,<br/>je vôľou dokonalou.<br/>Len takáto bola práca<br/>Pánových apoštolov.<br/>',NULL,130511,1);
INSERT INTO stanza VALUES('SK914','chorus','Máme slúžiť len pre cirkev,<br/>vlastným zámerom však nie.<br/>Božej vôli dokonalej,<br/>tej sa podrobujeme.<br/>',NULL,130512,2);
INSERT INTO stanza VALUES('SK914','2','Svoju nádobu mať – cirkev<br/>je Boží zámer večný,<br/>pre stavbu cirkvi zamýšľa<br/>našu službu použiť.<br/>',NULL,130513,3);
INSERT INTO stanza VALUES('SK914','3','Osoby obdarované,<br/>Telu sú dané Hlavou,<br/>pomôžu budovať cirkev,<br/>aby bola plnosťou.<br/>',NULL,130514,4);
INSERT INTO stanza VALUES('SK914','4','Všetky dary a funkcie,<br/>moci účinky rôzne,<br/>všetko posluhovanie je<br/>iba pre cirkev dané.<br/>',NULL,130515,5);
INSERT INTO stanza VALUES('SK914','5','Kázanie evanjelia,<br/>posluhovanie slova,<br/>aj každá iná služba je<br/>len pre cirkev určená.<br/>',NULL,130516,6);
INSERT INTO stanza VALUES('SK914','6','Posluhovanie pre cirkvi,<br/>nie je tomu opačne.<br/>Nie formou posluhovania,<br/>lež svietnikom cirkev je.<br/>',NULL,130517,7);
INSERT INTO stanza VALUES('SK914','7','To drží jednotu cirkvi,<br/>od sektárstva nás spasí,<br/>preverí naše motívy,<br/>naše ciele napraví.<br/>',NULL,130518,8);
INSERT INTO stanza VALUES('SK914','8','Pane, chráň od našej práce<br/>od diela sekty každej,<br/>pracujeme len pre cirkev,<br/>pre jej vybudovanie.<br/>',NULL,130519,9);
INSERT INTO stanza VALUES('SK917','1','Blúdia mnohí, prebývajú v temnote,<br/>ich duše sa môžu navždy stratiť.<br/>Kto im povie o plnej Božej spáse,<br/>hľadiac na Pána cenu zaplatí?<br/>',NULL,130520,1);
INSERT INTO stanza VALUES('SK917','chorus','„Hľa, všetka moc Mi je daná,<br/>hľa, všetka moc Mi je daná,<br/>choďte do celého sveta, ohlasujte<br/>evanjelium, som s vami.“<br/>',NULL,130521,2);
INSERT INTO stanza VALUES('SK917','2','Otvorené dvere sveta volajú:<br/>Príďte aj k nám vojaci Kristovi!<br/>Zobuďte sa, kresťania! Spojte sily!<br/>Evanjeliom osloboď ľudí.<br/>',NULL,130522,3);
INSERT INTO stanza VALUES('SK917','3','„Prečo zomrieť?“ Boží hlas sa ich pýta.<br/>„Prečo zomrieť?“ My sa s Ním pýtame.<br/>Ježiš zomrel, od smrti zachránil nás,<br/>choď, ohlasuj život a spasenie.<br/>',NULL,130523,4);
INSERT INTO stanza VALUES('SK925','1','Dôsledkom evanjelia<br/>je živý tok vnútri nás.<br/>naším svedectvom môžeme<br/>stratených ľudí vyhrať.<br/>',NULL,130524,1);
INSERT INTO stanza VALUES('SK925','chorus','Pane, daj nám tok živý, nech<br/>Tvoj život je vidieť v nás.<br/>My sme nádoby živé, Ty<br/>oživuj ľudí cez nás.<br/>',NULL,130525,2);
INSERT INTO stanza VALUES('SK925','2','Životom, čo usvedčuje,<br/>ľudia môžu uveriť.<br/>životom, čo sa rozdáva,<br/>duše môžu život mať.<br/>',NULL,130526,3);
INSERT INTO stanza VALUES('SK925','3','Vždy prebývajme v Kristovi,<br/>ovocie prinášajúc.<br/>tečením života vnútri,<br/>ľuďom Pána dávajúc.<br/>',NULL,130527,4);
INSERT INTO stanza VALUES('SK925','4','Naše žitie nech Ho hlása,<br/>nech iní Ho poznajú.<br/>nevyučujme doktríny,<br/>žime život dávajúc.<br/>',NULL,130528,5);
INSERT INTO stanza VALUES('SK937','1','Sme jednotní v Tvojej smrti,<br/>Pane, pokrstením.<br/>Milosrdenstvo a milosť<br/>tú vzácnosť odhalí.<br/>',NULL,130529,1);
INSERT INTO stanza VALUES('SK937','2','Sme jednotní v Tvojej smrti,<br/>krstom pochovaní.<br/>Navždy sme zomreli hriechu,<br/>z okov uvoľnení.<br/>',NULL,130530,2);
INSERT INTO stanza VALUES('SK937','3','Sme jednotní v Tvojej smrti,<br/>s Tebou pochovaní.<br/>So svetom sme sa rozišli,<br/>od Satana voľní.<br/>',NULL,130531,3);
INSERT INTO stanza VALUES('SK937','4','S Tebou sme boli vzkriesení,<br/>od smrti sme voľní.<br/>Nový život s Tebou nesie<br/>ovocie svätosti.<br/>',NULL,130532,4);
INSERT INTO stanza VALUES('SK937','5','Vo vzácne meno vnorení,<br/>nie sme nezávislí,<br/>nasledujeme, žijeme<br/>s Tebou zjednotení.<br/>',NULL,130533,5);
INSERT INTO stanza VALUES('SK938','1','Mŕtvy už som, pochovaný!<br/>Starý človek ukončený!<br/>Mŕtvy už som, pochovaný!<br/>Starý človek ukončený!<br/>',NULL,130534,1);
INSERT INTO stanza VALUES('SK938','2','Už nie som ja, kto žije sám!<br/>Vo mne žije Kristus Pán!<br/>Už nie som ja, kto žije sám!<br/>Vo mne žije Kristus Pán!<br/>',NULL,130535,2);
INSERT INTO stanza VALUES('SK941','1','’By chránil Svoju slávu,<br/>v kráľovstve vládne Boh,<br/>má zvrchovanú vládu,<br/>zachovať poriadok.<br/>Vo Svojom kráľovstve Boh<br/>plne uplatňuje<br/>len Svoju autoritu<br/>večne, neprestajne.<br/>',NULL,130536,1);
INSERT INTO stanza VALUES('SK941','2','Boh z centra božskej vlády<br/>na tróne kraľuje,<br/>’by všetko s Jeho plánom<br/>mohlo byť v súlade.<br/>Božie Hlavenstvo, panstvo<br/>môže uplatňovať,<br/>len ako v kráľovstve Kráľ,<br/>nad všetkým kraľovať.<br/>',NULL,130537,2);
INSERT INTO stanza VALUES('SK941','3','Svoju vôľu koná,<br/>Pán pod Svojou nadvládou<br/>Svoj zámer vykoná.<br/>Iba v kráľovstve Božom<br/>máme požehnanie,<br/>zo všemocného trónu<br/>prúd života plynie.<br/>',NULL,130538,3);
INSERT INTO stanza VALUES('SK941','4','Poddať sa Božej vláde<br/>je cnosťou najvyššou,<br/>vzbura proti Bohu je<br/>koreň všetkých hriechov.<br/>Zlým zámerom Satana<br/>je zvrhnúť Boží trón.<br/>Naším cieľom je navždy,<br/>úplne poznať trón.<br/>',NULL,130539,4);
INSERT INTO stanza VALUES('SK941','5','V kráľovstve nášho Boha<br/>je Kristus zväčšený,<br/>keď v živote kraľuje,<br/>Otec je slávený.<br/>Všetko je požehnané,<br/>keď náš Boh panuje,<br/>Kristus pre Neho vládne<br/>Boh má vyjadrenie.<br/>',NULL,130540,5);
INSERT INTO stanza VALUES('SK941','6','Kristus, v plnosti časov<br/>si všetko podmaní,<br/>uctievať budú Kráľa<br/>veľkí, aj tí malí.<br/>Cirkev už dnes zakúša<br/>tú vládu života,<br/>Kristu sa podriaďuje,<br/>pre príchod kráľovstva.<br/>',NULL,130541,6);
INSERT INTO stanza VALUES('SK942','1','Kráľovstvo Božie na zemi<br/>je vláda Božia, vnútorná.<br/>Je to Kristus žijúci v nás,<br/>’by vládol ako Pán a Kráľ.<br/>',NULL,130542,1);
INSERT INTO stanza VALUES('SK942','2','Jeho život s autoritou<br/>v nás Pána na trón dosadí,<br/>aby riadil naše slová,<br/>skutky a život vnútorný.<br/>',NULL,130543,2);
INSERT INTO stanza VALUES('SK942','3','Pán na tróne v našich srdciach<br/>si kráľovstvo chce založiť,<br/>aby v nás mohol panovať,<br/>pre zámer Boží pripraviť.<br/>',NULL,130544,3);
INSERT INTO stanza VALUES('SK942','4','Svojou vládou v našich srdciach<br/>životom nás zaopatrí.<br/>Ak mu vládnuť dovolíme,<br/>bohato nás uspokojí.<br/>',NULL,130545,4);
INSERT INTO stanza VALUES('SK942','5','Vnútornou vládou Pánovou<br/>je Jeho plnosť zjavená.<br/>Požehnané, budované<br/>Telo, ak túto vládu má.<br/>',NULL,130546,5);
INSERT INTO stanza VALUES('SK942','6','Vnútornou vládou nebeskou<br/>sme nebeskými občanmi,<br/>poddávaním sa vnútorným,<br/>sa kráľovstvo nebies zjaví.<br/>',NULL,130547,6);
INSERT INTO stanza VALUES('SK942','7','V nebeskej sfére žijeme,<br/>mocou z nebies naplnení,<br/>kráčame v nebeskom svetle,<br/>kým sa kráľovstvo prejaví.<br/>',NULL,130548,7);
INSERT INTO stanza VALUES('SK944','1','Esenciou kráľovstva je<br/>život s Božím panovaním<br/>a prirodzenosti božskej,<br/>s Kristom plne zakúšaným.<br/>',NULL,130549,1);
INSERT INTO stanza VALUES('SK944','2','Život v duchu vyprázdnený<br/>mäkké, kajúce srdce má,<br/>čo je k iným milosrdný,<br/>okrem Boha nič nehľadá.<br/>',NULL,130550,2);
INSERT INTO stanza VALUES('SK944','3','Boží synovia pokoja<br/>trpia bôľ pre spravodlivosť,<br/>zlorečení pre Ježiša,<br/>avšak nevýslovná radosť.<br/>',NULL,130551,3);
INSERT INTO stanza VALUES('SK944','4','Ako soľ ničia skazenosť,<br/>svietia vo tme ako svetlá,<br/>praví sú v srdciach a skutkoch,<br/>láska v nich je dokonalá.<br/>',NULL,130552,4);
INSERT INTO stanza VALUES('SK944','5','Život nechce vlastnú slávu,<br/>za Božie kráľovstvo prosí,<br/>spoľahnutie má len v Bohu,<br/>vždy kráľovstvo uprednostní.<br/>',NULL,130553,5);
INSERT INTO stanza VALUES('SK944','6','Prísny k sebe, vľúdny k iným,<br/>Pán ho cibrí neustále,<br/>podľa Jeho slova činí<br/>vôľu Otca neprestajne.<br/>',NULL,130554,6);
INSERT INTO stanza VALUES('SK944','7','Satanovi priestor nedá,<br/>duši, hriechu ani svetu,<br/>len nebeskú vládu hľadá,<br/>Božiu plnú autoritu.<br/>',NULL,130555,7);
INSERT INTO stanza VALUES('SK944','8','Tento život podmaňuje<br/>všetko prikázaniam Božím,<br/>rýchlo sa čas približuje,<br/>keď kráľovstvo Pán prejaví.<br/>',NULL,130556,8);
INSERT INTO stanza VALUES('SK946','1','Pozri, sláva! Hľa, vznešenosť!<br/>Prejav kráľovstva nebies!<br/>Jeho slávny Kráľ a Pán v ňom<br/>má Božie požehnanie.<br/>Prv prišiel pokorne v tele,<br/>opovrhovali Ním.<br/>Dnes opäť prichádza v sláve,<br/>zámer kráľovstva splní.<br/>',NULL,130557,1);
INSERT INTO stanza VALUES('SK946','2','Kráľovstvo odišiel prevziať<br/>od Boha, čo je večný.<br/>S kráľovstvom teraz prichádza,<br/>s jeho slávnym vládnutím.<br/>On je kameňom drviacim,<br/>národy všetky skruší.<br/>A stane sa veľkou horou<br/>kráľovstvo, čo prejaví.<br/>',NULL,130558,2);
INSERT INTO stanza VALUES('SK946','3','Hľa, všetky panstvá, celá zem<br/>Bohu a Kristu patria.<br/>Pod ich zvrchovanou vládou<br/>zem plná je pokoja.<br/>Skončia vojny aj nenávisť<br/>medzi národmi zeme.<br/>Zaplaví ich známosť Boha<br/>sťa vody plnia more.<br/>',NULL,130559,3);
INSERT INTO stanza VALUES('SK946','4','Všetci víťazní kresťania<br/>s Kristom kraľovať budú,<br/>a zostatok Izraela,<br/>ten bude kňazstvom Bohu.<br/>Národy budú pod vládou,<br/>Božím ľudom učené,<br/>uvidí celé stvorenie<br/>nádherné obnovenie.<br/>',NULL,130560,4);
INSERT INTO stanza VALUES('SK946','5','Satan bude poviazaný,<br/>zem sa stane slobodnou.<br/>Pod Kristom, vládnucou Hlavou,<br/>zem bude požehnanou.<br/>Všetko podriadené Kristu,<br/>Jeho vláde a vôli.<br/>Slávna Hlava a stredobod<br/>Boží zámer naplní.<br/>',NULL,130561,5);
INSERT INTO stanza VALUES('SK947','1','Kráľovstvo Božie je nám dnes námahou,<br/>no keď príde Kristus, tak bude odmenou.<br/>my sme dnes Božou múdrosťou trénovaní,<br/>aby tak bol Jeho zámer naplnený.<br/>',NULL,130562,1);
INSERT INTO stanza VALUES('SK947','2','Božie deti, my budeme kráľmi s Ním,<br/>trénovať však musíme a byť víťazní.<br/>vedieť, ako kraľovať v kráľovstve Jeho,<br/>aby kráľovstvo v nás vyjadrené bolo.<br/>',NULL,130563,2);
INSERT INTO stanza VALUES('SK947','3','Učme sa dnes podriaďovať sa trónu,<br/>ako mať striktný život a Jeho vládu.<br/>tak budeme zdieľať Jeho autoritu,<br/>a nad národmi ako dedičia vládnuť.<br/>',NULL,130564,3);
INSERT INTO stanza VALUES('SK947','4','Majme život striktný a spravodlivý,<br/>vľúdny k iným, v Bohu radostný a smelý.<br/>v skutočnosti kráľovstva vždy ostávajme,<br/>na jeho prejavenie sa pripravujme.<br/>',NULL,130565,4);
INSERT INTO stanza VALUES('SK947','5','Keď Kristus príde s kráľovstvom od Boha,<br/>vtedy kráľovstvo bude naša odmena.<br/>bude udržiavať spravodlivosť skrz nás<br/>a Jeho múdrosť bude mocnostiam zjavná.<br/>',NULL,130566,5);
INSERT INTO stanza VALUES('SK947','6','Apoštol pre to platil veľkú cenu,<br/>chcel si byť istý, že nestratí odmenu,<br/>chcel, aby boli aj iní verní Bohu,<br/>aby mali kráľovstvo ako odmenu.<br/>',NULL,130567,6);
INSERT INTO stanza VALUES('SK947','7','Pane, daj nám milosť pre kráľovstvo žiť,<br/>trénuj nás, ’by si nám mohol odmenu dať.<br/>Chceme sa cvičiť v skutočnosti kráľovstva,<br/>aby jeho prejav bol naša odmena.<br/>',NULL,130568,7);
INSERT INTO stanza VALUES('SK948','1','Odveké tajomstvo je mi zjavené:<br/>Kristus je skutočnosťou Božou.<br/>Je Božím vtelením, životom mojím,<br/>bude slávou, nádejou mojou.<br/>',NULL,130569,1);
INSERT INTO stanza VALUES('SK948','chorus','Sláva! Kristus je život vo mne!<br/>Sláva! Sláva! Aká nádej je!<br/>Kristus v mojom duchu tajomstvom dnes je,<br/>slávou vo večnosti sa stane.<br/>',NULL,130570,2);
INSERT INTO stanza VALUES('SK948','2','V mojom duchu som bol znovuzrodený,<br/>v duši som teraz premieňaný.<br/>Telo mi na Svoju podobu zmení,<br/>vo všetkom činí ma rovnakým.<br/>',NULL,130571,3);
INSERT INTO stanza VALUES('SK948','3','V živote, povahe som dnes jedno s Ním,<br/>potom budem v Ňom oslávený.<br/>budem v Jeho prítomnosti naveky<br/>celkom Jemu pripodobnený.<br/>',NULL,130572,4);
INSERT INTO stanza VALUES('SK949','1','Kristus je nádej slávy, je životom mojím,<br/>som Ním znovuzrodený, som Ním nasýtený,<br/>mocou premáhajúcou mi telo premení,<br/>Oslávenému telu pripodobní!<br/>',NULL,130573,1);
INSERT INTO stanza VALUES('SK949','chorus','Prichádza Pán, budem Ním oslávený!<br/>Telo mi premení, budem Mu pripodobnený.<br/>Prichádza Pán, s plným vykúpením!<br/>On, nádej slávy príde k nám, oslávi nás, svätých.<br/>',NULL,130574,2);
INSERT INTO stanza VALUES('SK949','2','Kristus je nádej slávy, je tajomstvom Boha,<br/>Božiu plnosť mi dáva, Boha do mňa vkladá.<br/>Prichádza, ’by ma zmiešaval s Bohom vo všetkom,<br/>aby som v sláve Jeho naveky bol.<br/>',NULL,130575,3);
INSERT INTO stanza VALUES('SK949','3','Kristus je nádej slávy, vykúpenie plné:<br/>vykúpením pre telo, bude nesmrteľné.<br/>Keď príde Pán tak slávne telo mi učiní,<br/>a víťazne už navždy smrť pohltí.<br/>',NULL,130576,4);
INSERT INTO stanza VALUES('SK949','4','Kristus je nádej slávy, mojou históriou,<br/>zakúšam Jeho život, On je jedno so mnou,<br/>prichádza a uvádza do slávnej slobody,<br/>aby som s Ním naveky bol jednotný.<br/>',NULL,130577,5);
INSERT INTO stanza VALUES('SK956','1','Pán Ježiš sa vráti za čas nedlhý,<br/>počuť ako sa približuje.<br/>Preto bdejme, buďme vždy ostražití,<br/>nech si nás vezme, potešuje.<br/>',NULL,130578,1);
INSERT INTO stanza VALUES('SK956','chorus','Sláva, sláva, Kristus vráti sa!<br/>Sláva, budeme s Ním kraľovať!<br/>Slávne telo nám dá, budeme vždy s Ním,<br/>naším spevom bude chválený.<br/>',NULL,130579,2);
INSERT INTO stanza VALUES('SK956','2','Pán Ježiš sa vráti, Hviezda sa javí,<br/>noc temná, deň sa približuje.<br/>Nechceme byť prúdom sveta strhnutí,<br/>nech nemáme súženie veľké.<br/>',NULL,130580,3);
INSERT INTO stanza VALUES('SK956','3','Pán Ježiš sa vráti, odmení verných,<br/>ocení, ak Ho milujeme.<br/>Neoceňujme svet, buďme všímaví,<br/>s láskou Jeho bremeno nesme.<br/>',NULL,130581,4);
INSERT INTO stanza VALUES('SK956','4','Pán Ježiš sa vráti, bude kraľovať,<br/>zviaže Satana, svet podmaní.<br/>Nad nepriateľom musíme zvíťaziť,<br/>potom nás na trón Svoj usadí.<br/>',NULL,130582,5);
INSERT INTO stanza VALUES('SK958','1','V Betánii, čo sme sa rozlúčili,<br/>odvtedy vnútri prázdne miesto mám.<br/>Ako môžem zvesiť citaru z vŕby?<br/>Ako si môžem spievať bez Teba?<br/>Keď v noci bdiem, o Tebe uvažujem –<br/>nevnímam smútok, rozveselenie –<br/>spomínam prísľub Tvoj, že sa späť vrátiš.<br/>Povzdych: „Pane, prečo si ešte neprišiel?“<br/>',NULL,130583,1);
INSERT INTO stanza VALUES('SK958','2','Jasle Tvoje uzriem: viem, domov nemám,<br/>potešenia duše berie Tvoj kríž.<br/>Tvoj príchod núti, že lepšiu vlasť hľadám,<br/>pretože Sám si môj cieľ jediný.<br/>Keďže tu nie si, radosť príchuť nemá<br/>a moja pieseň sladkosť stratila.<br/>Keďže tu nie si, prázdno ma premáha,<br/>aby si už prišiel, ó, ako si želám.<br/>',NULL,130584,2);
INSERT INTO stanza VALUES('SK958','3','Láskyplnú prítomnosť Tvoju hoc mám,<br/>vnútri trpím, lebo Ťa nevidím.<br/>Že si nežný, že Svoje svetlo dávaš,<br/>už nestačí: „Pane, príď späť, prosím.“<br/>Opustený, hoc Tvoj pokoj vnútri mám,<br/>som radostný, napriek tomu vzdychám.<br/>Hoc spokojný, no vnútri tichá túžba,<br/>čo prechádza v nárek, vidieť Ťa tvárou v tvár.<br/>',NULL,130585,3);
INSERT INTO stanza VALUES('SK958','4','Kto z vyhnancov po domove netúži<br/>a neželá si uvidieť svoj ľud?<br/>V zemi cudzej, kto zabúda na blízkych?<br/>Milovaných, kto by nechcel stretnúť?<br/>Čo pozemské sa môže porovnávať<br/>s radosťou z návratu Tvojho, Pane?<br/>Keďže nemôžem hľadieť na Tvoju tvár,<br/>čo môžem robiť? Čakám Tvoje zjavenie.<br/>',NULL,130586,4);
INSERT INTO stanza VALUES('SK958','5','Vari môžeš zabudnúť na Svoj prísľub,<br/>že skoro prídeš, vezmeš ma k Sebe?<br/>Deň čo deň, rok čo rok Ťa očakávam,<br/>stále čakám, no nie si späť, Pane!<br/>Na roky môjho čakania spomeň si,<br/>keď sme boli od seba vzdialení.<br/>Stále čakám, ó, ako dlho ešte,<br/>kým prídeš so Svojím slávnym zoskupením?<br/>',NULL,130587,5);
INSERT INTO stanza VALUES('SK958','6','Z pokolenia na pokolenie mnohí<br/>svätí prichádzali a odišli,<br/>slávneho prísľubu sa nedočkali.<br/>Čas predlhý, dlhý je odvtedy!<br/>Prečo Ťa stále, Pane, nevidíme?<br/>Nebesia sú prečo uzavreté?<br/>Aký dlhý čas ešte čakať máme?<br/>Kedy sa v nádhere Svojej zjavíš, Pane?<br/>',NULL,130588,6);
INSERT INTO stanza VALUES('SK958','7','Pane, spomínam na roky čakania,<br/>na návrat Tvoj, no nie som jediný.<br/>Mnohí drahí svätí Ťa tiež žiadajú,<br/>’by si prišiel pre to, čo Ti patrí.<br/>Odpovedz nám na slzy, naše prosby<br/>tým, že sa vrátiš, skoro prídeš späť.<br/>„Príď, Pane príď,“ už veky sa ozýva,<br/>na toto súhrnné volanie odpovedz!<br/>',NULL,130589,7);
INSERT INTO stanza VALUES('SK960','1','Môj Kráľ sa vráti skoro späť<br/>oblohu naplní,<br/>vesmír bude vykúpený<br/>a svetlo uvidí.<br/>Čoskoro naplní Svoj plán,<br/>čujem Jeho kroky,<br/>Jeho postava vznešená,<br/>začína sa javiť.<br/>',NULL,130590,1);
INSERT INTO stanza VALUES('SK960','2','Želám si Jeho prítomnosť<br/>túžim byť spolu s Ním,<br/>zatiaľ, čo na Neho čakám,<br/>nesmiem byť lenivý.<br/>Keď príde tak Ho uvidím,<br/>veriť už nemusím.<br/>Moje srdce tu na zemi<br/>iné nič neteší.<br/>',NULL,130591,2);
INSERT INTO stanza VALUES('SK960','3','Moje srdce je stále s Ním,<br/>vždy k nebesiam hľadím,<br/>o tom, že s Pánom sa stretnem<br/>rozprávam perami.<br/>Prichádza, približuje sa,<br/>vezme si ma k Sebe.<br/>Jeho prisľúbenie pevné<br/>bude naplnené.<br/>',NULL,130592,3);
INSERT INTO stanza VALUES('SK960','4','Spasiteľ môj, Tvoje slová,<br/>nemožno spochybniť,<br/>nimi som povzbudzovaný,<br/>Tebe Pane verný.<br/>Nech sláva Tvoja sa zjaví,<br/>nepriateľ nech padne,<br/>prisľúbenia sa naplnia,<br/>na tróne budeme.<br/>',NULL,130593,4);
INSERT INTO stanza VALUES('SK960','5','Ty útočiskom si mojím,<br/>Spasiteľ, môj Bože,<br/>všetkých, čo Ti dôverujú,<br/>ochrániš, si Otec.<br/>Ovce aj pastier sú jedno,<br/>ako hlava s telom,<br/>Tvoje deti nik nevezme,<br/>veria v Tvoje meno.<br/>',NULL,130594,5);
INSERT INTO stanza VALUES('SK960','6','Tisíc rúk, ni tisíc očí,<br/>nič ma nezadrží,<br/>prekážky len pomáhajú<br/>za ocenením ísť.<br/>Povstaň duch aj moje srdce,<br/>nech sa svet preč berie,<br/>môj Pán života ma vezme,<br/>už čoskoro k Sebe.<br/>',NULL,130595,6);
INSERT INTO stanza VALUES('SK960','7','Si slnkom, čo uzdravuje<br/>si nádejou ľudí,<br/>spravodlivý a slávny kráľ,<br/>skloním sa a modlím:<br/>Pane, zostúp Tvoj trón skoro,<br/>tvár Svoju rozjasni,<br/>založ nebeské kráľovstvo,<br/>udeľ milosť všetkým.<br/>',NULL,130596,7);
INSERT INTO stanza VALUES('SK960','8','Pravda je kráľom, víťazí,<br/>kráľovnou sloboda,<br/>faloš, ktorej je stále viac,<br/>tá je hlavou sveta.<br/>Prosíme, Pravda, rýchle príď,<br/>zostúp svetlo z nebies,<br/>nepriateľ bude zničený,<br/>synov k Sebe priveď.<br/>',NULL,130597,8);
INSERT INTO stanza VALUES('SK966','1','Ó, nádej slávy, Kristus sa vráti!<br/>Uchváti nás a slávou premení,<br/>oslávi nás, budeme sa tešiť,<br/>budeme Mu úplne podobní,<br/>',NULL,130598,1);
INSERT INTO stanza VALUES('SK966','chorus','Slávna nádej! Pán sa vráti!<br/>Slávna nádej! Pán sa vráti!<br/>Uchváti nás a slávou premení,<br/>Ó, nádej slávy, Kristus sa vráti!<br/>',NULL,130599,2);
INSERT INTO stanza VALUES('SK966','2','Ó, nádej slávy, Kristus sa vráti!<br/>Zanikne celé staré stvorenie,<br/>budeme bez náreku, slobodní,<br/>tešiť sa zo záchrany úplnej.<br/>',NULL,130600,3);
INSERT INTO stanza VALUES('SK966','3','Ó, nádej slávy, Kristus sa vráti!<br/>Nech sme tí, čo spolu s Ním kraľujú,<br/>ako kňazi s Ním slúžiť budeme,<br/>získame Jeho spásu úplnú.<br/>',NULL,130601,4);
INSERT INTO stanza VALUES('SK966','4','Ó, nádej slávy, Kristus sa vráti!<br/>Slúžime verne, bdieme, čakáme,<br/>bežíme závod, k cieľu ideme,<br/>nech Jeho odmenu dostaneme.<br/>',NULL,130602,5);
INSERT INTO stanza VALUES('SK970','1','Stvorenstvo túžobne čaká,<br/>na príchod synov Božích.<br/>Na ich slávne zjavenie sa,<br/>všetci budú slobodní.<br/>',NULL,130603,1);
INSERT INTO stanza VALUES('SK970','2','Stvorenstvo spoločne vzdychá,<br/>podrobené márnosti.<br/>Čaká na vyslobodenie<br/>z otroctva skazenosti.<br/>',NULL,130604,2);
INSERT INTO stanza VALUES('SK970','3','Veď aj my sami vzdycháme,<br/>zrelosť kým dosiahneme.<br/>Rastieme až do synovstva,<br/>spolu s Kristom v podobe.<br/>',NULL,130605,3);
INSERT INTO stanza VALUES('SK970','4','Pre toto aj sám Duch vzdychá,<br/>podobní nech Kristu sme.<br/>Všetko spoločne pôsobí,<br/>na premenu v živote.<br/>',NULL,130606,4);
INSERT INTO stanza VALUES('SK970','5','Boh nás do slávy privedie,<br/>budeme oslávení.<br/>Ním presýtení úplne<br/>a celkom posvätení.<br/>',NULL,130607,5);
INSERT INTO stanza VALUES('SK970','6','Do slobody tejto slávy,<br/>všetko bude slobodné.<br/>Krava sa pasie s medveďom,<br/>Leopard s kozľaťom je.<br/>',NULL,130608,6);
INSERT INTO stanza VALUES('SK970','7','Dedičia s Kristom, synovstvo,<br/>čo je Jeho, zdedíme.<br/>Jeho oslávení bratia,<br/>Božiu slávu zjavíme.<br/>',NULL,130609,7);
INSERT INTO stanza VALUES('SK971','1','S človekom sa spojiť<br/>zámer je Boží.<br/>nádobu Svoju chce<br/>On znovu zrodiť.<br/>Svoj život nám dáva,<br/>ním presycuje.<br/>Človek Ho vyjadrí,<br/>s Ním jedno bude.<br/>',NULL,130610,1);
INSERT INTO stanza VALUES('SK971','2','Na Boží obraz Boh<br/>stvoril človeka,<br/>’by človek schopný bol,<br/>splniť Jeho plán.<br/>Aby prijal Boha –<br/>ten Strom Života,<br/>bol Jeho plnosťou<br/>ako manželka.<br/>',NULL,130611,2);
INSERT INTO stanza VALUES('SK971','3','Prúd Jeho života<br/>človeka zmení,<br/>vzácny materiál tak<br/>z neho vytvorí.<br/>Človeka zbuduje<br/>v náprotivok Svoj,<br/>bude potešený,<br/>získa príbytok.<br/>',NULL,130612,3);
INSERT INTO stanza VALUES('SK971','4','To je Jeruzalem<br/>slávny a nový,<br/>v ňom majú domov Boh<br/>a Jeho svätí.<br/>Boh je ich obsahom,<br/>vyjadrujú Ho,<br/>zdieľajú s Ním slávu,<br/>s Ním navždy jedno.<br/>',NULL,130613,4);
INSERT INTO stanza VALUES('SK971','5','Tým centrom je sám Boh,<br/>vládne na tróne.<br/>život zachováva,<br/>svätých v jednote.<br/>Jeho svetlo slávy<br/>vo svetle drží<br/>a tiež v harmónii<br/>a v potešení.<br/>',NULL,130614,5);
INSERT INTO stanza VALUES('SK971','6','Pán je vodou živou,<br/>ich pokrmom je.<br/>hlad a ich smäd Sebou<br/>uspokojuje.<br/>Pán je pre nich chrámom,<br/>oni v Ňom žijú,<br/>v prítomnosti Jeho<br/>Ho uctievajú.<br/>',NULL,130615,6);
INSERT INTO stanza VALUES('SK972','1','Božia hlavná myšlienka<br/>je byť jedno s človekom.<br/>je všetkým pre človeka,<br/>aby naplnil plán Svoj.<br/>',NULL,130616,1);
INSERT INTO stanza VALUES('SK972','2','Človek – z hliny nádoba –<br/>telo, duša a tiež duch,<br/>môže mať život Boha<br/>a tak s Ním mať jednotu.<br/>',NULL,130617,2);
INSERT INTO stanza VALUES('SK972','3','Prúd Božského života<br/>vzácne kamene tvorí<br/>súce k stavbe príbytku,<br/>tento Boha oslávi.<br/>',NULL,130618,3);
INSERT INTO stanza VALUES('SK972','4','Boh si mesto buduje,<br/>túži mať Svoj príbytok,<br/>len Nový Jeruzalem<br/>poteší srdce Jeho.<br/>',NULL,130619,4);
INSERT INTO stanza VALUES('SK972','5','Touto stavbou sú svätí,<br/>Boh a človek zmiešaní,<br/>zámer tento si zvolil<br/>Otec už pred stvorením.<br/>',NULL,130620,5);
INSERT INTO stanza VALUES('SK972','6','V centre, kde je Jeho moc,<br/>trón je Kristov a Boží,<br/>z trónu vyteká rieka<br/>ako prúd Ducha živý.<br/>',NULL,130621,6);
INSERT INTO stanza VALUES('SK972','7','V prúde tejto rieky je<br/>Pán ako strom života,<br/>On všetkých nasycuje,<br/>dáva plody života.<br/>',NULL,130622,7);
INSERT INTO stanza VALUES('SK972','8','Boh v Kristovi svetlom je,<br/>On mesto prežaruje,<br/>všetku tmu rozptyľuje,<br/>veď svetlom života je.<br/>',NULL,130623,8);
INSERT INTO stanza VALUES('SK972','9','Boh a človek tam v sebe<br/>vzájomne prebývajú.<br/>Boh je obsah v človeku,<br/>ľudia Ho vyjadrujú.<br/>',NULL,130624,9);
INSERT INTO stanza VALUES('SK976','1','Tí, ktorých si Sám vykúpil,<br/>sú Ti nevestou, Pane.<br/>Tvoja plnosť, vyjadrenie,<br/>Ty si oslávený v nej.<br/>Si pre ňu všetko vo všetkom,<br/>ona zjavuje Teba.<br/>úplne si ju presiakol,<br/>slávu Svoju s ňou zdieľaš.<br/>',NULL,130625,1);
INSERT INTO stanza VALUES('SK976','chorus','Pozri, mesto sväté,<br/>slávy Božej plné!<br/>Úplné Božie<br/>vyjadrenie sa v ľudskosti.<br/>',NULL,130626,2);
INSERT INTO stanza VALUES('SK976','2','Boh a človek zmiešaní sú,<br/>nábožnosti tajomstvo.<br/>Boh vo Svojej sláve žiari,<br/>človek vyjadruje Ho.<br/>Nádoba univerzálna<br/>Božiu plnosť zjavuje,<br/>Božiu krásu vyjadruje,<br/>zmiešaná s Ním ona je.<br/>',NULL,130627,3);
INSERT INTO stanza VALUES('SK976','3','To je skladba tých svätých, čo<br/>sú Bohom premenení.<br/>ako perly, drahokamy,<br/>k Nemu pripodobnení.<br/>Od Božieho trónu prúdi<br/>zdarma voda života.<br/>Kristus ako strom života<br/>hojné plody vydáva.<br/>',NULL,130628,4);
INSERT INTO stanza VALUES('SK976','4','Svietnik to zlatý na veky,<br/>Kristus lampou svetla je.<br/>Boh v Kristovi, svetlo slávy,<br/>ako Duch žiari jasne!<br/>Človek v Bohu, Boh v človeku –<br/>úplné vyjadrenie.<br/>vzájomný ich príbytok, to<br/>cieľom Jeho plánu je.<br/>',NULL,130629,5);
INSERT INTO stanza VALUES('SK979','1','Slávne mesto jasne žiari,<br/>Nový Jeruzalem svätý,<br/>hľa, Boží príbytok s ľuďmi,<br/>nevesta Krista bez škvrny.<br/>',NULL,130630,1);
INSERT INTO stanza VALUES('SK979','2','Dávni svätí, aj tí dnešní,<br/>dedičia prísľubov Božích<br/>sú tohto mesta zložkami,<br/>spoločne vybudovaní.<br/>',NULL,130631,2);
INSERT INTO stanza VALUES('SK979','3','Mesto – dokonalý štvorec,<br/>všetky strany má rovnaké,<br/>každý rozmer dokonalý,<br/>všetko rovné, nič krivolaké.<br/>',NULL,130632,3);
INSERT INTO stanza VALUES('SK979','4','Mesto s ulicou sú zlaté,<br/>ako čisté sklo, priehľadné,<br/>Boží skvelý, večný život<br/>jeho prirodzenosťou je.<br/>',NULL,130633,4);
INSERT INTO stanza VALUES('SK979','5','Dvanásť brán je dvanásť perál,<br/>to je človek vykúpený,<br/>oživený, premenený,<br/>do Božej sféry tým patrí.<br/>',NULL,130634,5);
INSERT INTO stanza VALUES('SK979','6','Múr na dvanástich základoch<br/>z dvanástich vzácnych kameňov,<br/>ohňom, tlakom premenených,<br/>sú stavbou s večnou hodnotou.<br/>',NULL,130635,6);
INSERT INTO stanza VALUES('SK979','7','Jasná jaspisová hradba<br/>slávu Božiu ukazuje,<br/>Jeho svetlo cez ňu žiari,<br/>Boh sťa jaspis na pohľad je.<br/>',NULL,130636,7);
INSERT INTO stanza VALUES('SK979','8','Hradba tvorí oddelenie,<br/>nečistí mimo ostanú,<br/>zlato, perly, drahokamy,<br/>len tie vo svätom meste sú.<br/>',NULL,130637,8);
INSERT INTO stanza VALUES('SK979','9','Boh a Baránok chrámom sú!<br/>Vidíme Jeho slávnu tvár,<br/>v prítomnosti nekonečnej,<br/>vždy Ho budeme uctievať.<br/>',NULL,130638,9);
INSERT INTO stanza VALUES('SK979','10','Nepotrebuje slnko, mesiac,<br/>sláva Božia mu je svetlom,<br/>jeho lampou Baránok je,<br/>mesto žiari každým smerom.<br/>',NULL,130639,10);
INSERT INTO stanza VALUES('SK979','11','Z trónu Boha a Baránka<br/>rieka života vyteká,<br/>na oboch jej brehoch rastie,<br/>prosperuje strom života.<br/>',NULL,130640,11);
INSERT INTO stanza VALUES('SK979','12','Nie je to len život Boží<br/>pre pokrm, či voda živá,<br/>no aj Božia autorita,<br/>rovnako mestom preteká.<br/>',NULL,130641,12);
INSERT INTO stanza VALUES('SK979','13','Ulica je zlato čisté,<br/>Božia povaha cestou je,<br/>po nej tečie živá rieka,<br/>ovocie života rastie.<br/>',NULL,130642,13);
INSERT INTO stanza VALUES('SK979','14','Číslo dvanásť – vláda Božia,<br/>večnú dokonalosť javí,<br/>Boh je s človekom zmiešaný<br/>násobením tri krát štyri.<br/>',NULL,130643,14);
INSERT INTO stanza VALUES('SK979','15','Viac nebude tmy a smrti,<br/>smútok a bolesť pominú,<br/>všetko bude navždy nové,<br/>Boh s človekom navždy budú.<br/>',NULL,130644,15);
INSERT INTO stanza VALUES('SK979','16','Mesto nesie obraz Boží,<br/>napĺňa Jeho plán večný<br/>a vládne pre Najvyššieho,<br/>úplne Ho uspokojí.<br/>',NULL,130645,16);
INSERT INTO stanza VALUES('SK981','1','Pánovou ekonómiou<br/>je všetko spojiť v Kristu.<br/>Iba ak je našou Hlavou,<br/>máme jednotu istú.<br/>',NULL,130646,1);
INSERT INTO stanza VALUES('SK981','2','Kristus – Hlava bude stredom,<br/>s Bohom, Svetlom v Pánovi<br/>Kristus tróniť bude s Bohom,<br/>Jeho túžbu naplní.<br/>',NULL,130647,2);
INSERT INTO stanza VALUES('SK981','3','Kristus – Život bude obsah,<br/>zjednotí nás vo Svetle;<br/>a svätí Jeho nádoba,<br/>pre slávne vyjadrenie.<br/>',NULL,130648,3);
INSERT INTO stanza VALUES('SK981','4','Satan vnikol do človeka,<br/>všetky veci pokazil;<br/>prišla skazenosť, temnota,<br/>Boží zámer prekazil.<br/>',NULL,130649,4);
INSERT INTO stanza VALUES('SK981','5','Kristus nám odovzdal Seba,<br/>ako život nás spasil,<br/>aby Satan mocou temna<br/>už nič viac nezotročil.<br/>',NULL,130650,5);
INSERT INTO stanza VALUES('SK981','6','Kristus – Hlava, Svojím Telom,<br/>cirkvou, všetko zjednotí,<br/>vhodne poprepája Sebou,<br/>všetko v Sebe pohltí.<br/>',NULL,130651,6);
INSERT INTO stanza VALUES('SK981','7','Pod Jeho plným vedením<br/>zjednotenie nastane,<br/>vo svetle, ktoré je v cirkvi,<br/>v jednom všetko spočinie.<br/>',NULL,130652,7);
INSERT INTO stanza VALUES('SK981','8','Ak je Kristus stred a hlava,<br/>všetko bude v súlade,<br/>cez žiarenie Jeho tela<br/>oslobodenie príde.<br/>',NULL,130653,8);
INSERT INTO stanza VALUES('SK981','9','Temna, úpadku viac nie je,<br/>smrti ani márnosti,<br/>všetko z okov uvoľnené,<br/>počas celej večnosti.<br/>',NULL,130654,9);
INSERT INTO stanza VALUES('SK984','1','Rieka vody života,<br/>rieka z trónu vyteká,<br/>do spoločenstva uvádza,<br/>autoritu Božiu má.<br/>',NULL,130655,1);
INSERT INTO stanza VALUES('SK984','chorus','Rieka vody života,<br/>spoločenstvom preteká,<br/>v ňom je Božia autorita,<br/>kamkoľvek tok priteká.<br/>',NULL,130656,2);
INSERT INTO stanza VALUES('SK984','2','Tou vodou života je Duch,<br/>prúdi v nej Boh, život náš,<br/>v tej vode je Jeho panstvo,<br/>všade tam, kam priteká.<br/>',NULL,130657,3);
INSERT INTO stanza VALUES('SK984','3','Po zlatej ulici tečie,<br/>tým cestu ukazuje,<br/>je ňou božská prirodzenosť,<br/>Jeho cestou ideme.<br/>',NULL,130658,4);
INSERT INTO stanza VALUES('SK984','4','Strom života vedľa rieky,<br/>je to Boh, je pokrm náš<br/>pri mohutnom toku rieky,<br/>prehojný Strom sýti nás.<br/>',NULL,130659,5);
INSERT INTO stanza VALUES('SK1010','1','Ó, očistný prameň vidím,<br/>žriedlo prehlboké.<br/>Pán Ježiš, Spasiteľ mocný,<br/>Svoj bok ukazuje.<br/>',NULL,130660,1);
INSERT INTO stanza VALUES('SK1010','chorus','Ó, očistný prameň vidím,<br/>doň sa ponáram, som čistý!<br/>Pánovi chvála, som čistý!<br/>Tento prameň ma očistil.<br/>',NULL,130661,2);
INSERT INTO stanza VALUES('SK1010','2','Pána vidím, je vzkriesený,<br/>Jeho krv počujem!<br/>Krv hovorí, môj duch ožil,<br/>ó, je to úžasné.<br/>',NULL,130662,3);
INSERT INTO stanza VALUES('SK1010','3','Kráčať budem v Božom svetle<br/>nad hriechom a svetom.<br/>v rúchu bielom, srdcom novým<br/>a s vládnucim Kristom.<br/>',NULL,130663,4);
INSERT INTO stanza VALUES('SK1025','1','Vzdaj sa sveta, získaj Krista,<br/>treba Ho tvojmu srdcu.<br/>Čo viac si môžeš ešte priať?<br/>Všetky veci prázdne sú!<br/>',NULL,130664,1);
INSERT INTO stanza VALUES('SK1025','chorus','Je bohatý, dostatočný,<br/>potreby Pán naplňuje!<br/>On je dobrý, On je sladký,<br/>želania Pán presahuje!<br/>',NULL,130665,2);
INSERT INTO stanza VALUES('SK1025','2','Vzdaj sa sveta, získaj Krista,<br/>len Jeho potrebuješ.<br/>Prijmeš Ho a už si nikdy<br/>nič menej priať nebudeš.<br/>',NULL,130666,3);
INSERT INTO stanza VALUES('SK1025','3','Hoci veľký je tento svet<br/>a ty malé máš srdce,<br/>aj tak svet s jeho bohatstvom<br/>nenaplní ti srdce.<br/>',NULL,130667,4);
INSERT INTO stanza VALUES('SK1025','4','Ak Krista máš, aj radosť máš,<br/>bez Neho len bolesť je.<br/>kde je Kristus, tam ráno je,<br/>tma je tam, kde On nie je.<br/>',NULL,130668,5);
INSERT INTO stanza VALUES('SK1050','1','Z môjho otroctva, smútku a tmy,<br/>Ježiš, idem! Ježiš, idem!<br/>Do Tvojho svetla a slobody,<br/>Ježiš, idem k Tebe.<br/>Z mojej nemoci, v zdravie Tvoje,<br/>z biedy mojej, v bohatstvo Tvoje,<br/>z môjho hriechu, Ježišu, k Tebe,<br/>Ježiš, idem k Tebe.<br/>',NULL,130669,1);
INSERT INTO stanza VALUES('SK1050','2','Von z hanebného pádu a kríz,<br/>Ježiš, idem! Ježiš, idem!<br/>V slávu, ktorú si získal cez kríž,<br/>Ježiš, idem k Tebe.<br/>Z trápenia von do útechy, kde<br/>búrok nieto, len pokoj v Tebe,<br/>k víťaznej piesni z úzkosti preč,<br/>Ježiš, idem k Tebe.<br/>',NULL,130670,2);
INSERT INTO stanza VALUES('SK1050','3','Von z mojej pýchy, nepokoja,<br/>Ježiš, idem! Ježiš, idem!<br/>Len v Tvojej vôli chcem zotrvať,<br/>Ježiš, idem k Tebe.<br/>Zo seba von do lásky Tvojej,<br/>zúfať nebudem, pôjdem hore<br/>ako na krídlach holubice,<br/>Ježiš, idem k Tebe.<br/>',NULL,130671,3);
INSERT INTO stanza VALUES('SK1050','4','Z hrôzy a strachu, desu smrti,<br/>Ježiš, idem! Ježiš, idem!<br/>Do potechy, čo máš iba Ty,<br/>Ježiš, idem k Tebe.<br/>Kráčam k Tebe z pustých rozvalín,<br/>v stáde Tvojom sa z Teba teším,<br/>na Tvoju tvár naveky hľadím.<br/>Ježiš, idem k Tebe.<br/>',NULL,130672,4);
INSERT INTO stanza VALUES('SK1051','1','Vnímam Tvoj hlas, Pane,<br/>voláš ma ku Sebe<br/>očistiť sa v krvi Tvojej,<br/>preliatej na dreve.<br/>',NULL,130673,1);
INSERT INTO stanza VALUES('SK1051','chorus','Kráčam, Pane môj,<br/>kráčam ku Tebe,<br/>obmy, očisti krvou,<br/>preliatou na dreve.<br/>',NULL,130674,2);
INSERT INTO stanza VALUES('SK1051','2','Slabý som, skazený,<br/>no Ty si mi silou,<br/>očisťuješ ma od zloby,<br/>aby som rýdzi bol.<br/>',NULL,130675,3);
INSERT INTO stanza VALUES('SK1051','3','Pán vnútri potvrdil<br/>dielo požehnané<br/>tým, že pridal viac milosti<br/>tam, kde panoval hriech.<br/>',NULL,130676,4);
INSERT INTO stanza VALUES('SK1051','4','Všetkým verným srdciam<br/>sám Pán dosvedčuje,<br/>že prísľuby sú splnené,<br/>len vierou žiadajme.<br/>',NULL,130677,5);
INSERT INTO stanza VALUES('SK1051','5','Vďaka za Tvoju krv!<br/>Vďaka Ti za milosť!<br/>Za dar Krista, Ty si náš Pán,<br/>sila, spravodlivosť.<br/>',NULL,130678,6);
INSERT INTO stanza VALUES('SK1081','1','Bože Otče, si zdroj života,<br/>spolu Ťa vyjadrujeme.<br/>V Tvojom mene všetko máme,<br/>Bože Otče, si zdroj života.<br/>',NULL,130679,1);
INSERT INTO stanza VALUES('SK1081','chorus','V živote, v živote<br/>jednotu pravú máme.<br/>V živote, v živote,<br/>len v ňom, drahý Otče, jedno sme.<br/>',NULL,130680,2);
INSERT INTO stanza VALUES('SK1081','2','Vďaka za Tvoje sväté Slovo,<br/>Slovo Tebou presycuje,<br/>nás od sveta oddeľuje,<br/>vďaka za Tvoje sväté Slovo.<br/>',NULL,130681,3);
INSERT INTO stanza VALUES('SK1081','chorus','Cez Slovo, cez Slovo<br/>jednotu pravú máme.<br/>Cez Slovo, cez Slovo<br/>všetci učinení jedno sme.<br/>',NULL,130682,4);
INSERT INTO stanza VALUES('SK1081','3','Sláva Trojjediného Boha!<br/>Požehnanie, že sme synmi!<br/>Slávy Božej vyjadrením!<br/>Sláva Trojjediného Boha!<br/>',NULL,130683,5);
INSERT INTO stanza VALUES('SK1081','chorus','V sláve sme, v sláve sme,<br/>v Tvojej sláve jedno sme.<br/>V sláve sme, v sláve sme,<br/>všetci učinení jedno sme!<br/>',NULL,130684,6);
INSERT INTO stanza VALUES('SK1082','1','Kristovo žitie bolo plne hodné,<br/>ako nám to šestnásty žalm zjavuje.<br/>Jeho spôsob žitia nám vykresľuje<br/>človeka, čo v Božom stánku bývať smie.<br/>',NULL,130685,1);
INSERT INTO stanza VALUES('SK1082','2','„Zachráň ma, Bože, k Tebe sa utiekam“ –<br/>vo všetkom mal v Bohu útočisko Pán.<br/>„Si môj Pán, bez Teba niet šťastia pre mňa“ –<br/>hovoril v Sebe k Bohu bez prestania.<br/>',NULL,130686,2);
INSERT INTO stanza VALUES('SK1082','3','„Svätí, ktorí prebývajú na zemi“ –<br/>sú ľudia pre Pána veľmi hodnotní.<br/>V nich nachádza všetku Svoju záľubu –<br/>evanjeliá nám to dokazujú.<br/>',NULL,130687,3);
INSERT INTO stanza VALUES('SK1082','4','„Môj dedičný podiel a kalich je Pán“ –<br/>On vo všetkom stále k Otcovi vzhliadal.<br/>„Velebím Pána, ktorý mi vždy radí“ –<br/>Seba zapieral a žil slovom Božím.<br/>',NULL,130688,4);
INSERT INTO stanza VALUES('SK1082','5','Preto sa v srdci tešil, jasal v duchu,<br/>aj v Jeho smrti zneli chvály Bohu.<br/>Boh nenechal Jeho dušu v podsvetí,<br/>Jeho telo pozdvihol vo vzkriesení.<br/>',NULL,130689,5);
INSERT INTO stanza VALUES('SK1082','6','Boh Ho vzkriesil a slávou korunoval.<br/>v prítomnosti Božej plnú radosť má.<br/>Dnes má miesto po Otcovej pravici,<br/>kde je plynutie radostí naveky.<br/>',NULL,130690,6);
INSERT INTO stanza VALUES('SK1086','1','Slávne meno ľúbime,<br/>to meno Ježiš!<br/>Nad každým menom On je<br/>v nebi, na zemi.<br/>Keď to meno dýchame,<br/>temnota a smrť nás minie,<br/>vzývaním osobu vzácnu získame.<br/>',NULL,130691,1);
INSERT INTO stanza VALUES('SK1086','2','Tvoje meno – Pán Ježiš –<br/>vyznávame radi,<br/>nech je Boh Otec v nebi oslávený.<br/>Spoločne Ťa chválime,<br/>to je naše potešenie,<br/>volať JEŽIŠA, ktorého ľúbime!<br/>',NULL,130692,2);
INSERT INTO stanza VALUES('SK1087','1','Ó, aleluja, aká smrť,<br/>na kríži zomieral.<br/>No Kristus neumieral sám,<br/>s Ním to, čo smrti podlieha:<br/>Boh bol zahrnutý,<br/>so všetkými ľuďmi.<br/>Ó, aleluja za taký kríž!<br/>',NULL,130693,1);
INSERT INTO stanza VALUES('SK1087','2','Človek umrel, umrel v Bohu<br/>a bol ukončený!<br/>Dnes som od neho slobodný,<br/>pretože Boh ma ukončil!<br/>Aká smrť predivná,<br/>aká smrť predivná.<br/>Ó, aleluja za túto smrť!<br/>',NULL,130694,2);
INSERT INTO stanza VALUES('SK1087','3','Boh umrel, umrel v človeku,<br/>’by sa v ňom uvoľnil.<br/>Zrniečko padlo do zeme,<br/>dnes je veľmi rozmnožené.<br/>Sú plné života,<br/>Božieho života.<br/>Ó, aleluja za ten život!<br/>',NULL,130695,3);
INSERT INTO stanza VALUES('SK1087','4','Chvála Ti, Pane, za Tvoj kríž,<br/>za všeobsiahlu smrť!<br/>Kríž je vo všetkom ústredný,<br/>je prenesmierne hodnotný!<br/>Ó, milujeme kríž,<br/>ó, milujeme kríž.<br/>Ó, aleluja za taký kríž!<br/>',NULL,130696,4);
INSERT INTO stanza VALUES('SK1089','1','Hľa, Baránok Boží, čistý,<br/>za hriešnikov zabitý.<br/>Tvoja krv vykupujúca<br/>nás od hriechov očistí.<br/>Ó, Baránok nás vykúpil,<br/>všetky naše hriechy vzal,<br/>všetky naše hriechy vzal!<br/>',NULL,130697,1);
INSERT INTO stanza VALUES('SK1089','2','Bronzový had k Tebe vzhliadam,<br/>Syn ľudský, vyzdvihnutý.<br/>V podobe tela hriechu si<br/>umrel ukrižovaný.<br/>Ukončil staré stvorenie,<br/>skončil Satan, skončil svet,<br/>skončil Satan, skončil svet!<br/>',NULL,130698,2);
INSERT INTO stanza VALUES('SK1089','3','Ak malé pšeničné zrnko<br/>neumrie, bude samé.<br/>Má božský život, musí byť<br/>do smrti zasadené.<br/>Život plynie, Kristus rastie,<br/>dáva mnohým zrnám vzísť,<br/>dáva mnohým zrnám vzísť!<br/>',NULL,130699,3);
INSERT INTO stanza VALUES('SK1089','4','Hľa Baránok – Vykupiteľ,<br/>z bronzu had – diablov koniec,<br/>zrnko – život rozmnožuje,<br/>dnes sú mnohé zmiešané.<br/>Aleluja! Aleluja!<br/>Tá smrť všeobsiahla je!<br/>Tá smrť všeobsiahla je!<br/>',NULL,130700,4);
INSERT INTO stanza VALUES('SK1094','1','Všetky národy sa búria,<br/>márnosti vymýšľajú,<br/>proti Pánovi sa králi<br/>spoločne zhromažďujú.<br/>„Ich okovy pretrhnime<br/>a odhoďme ich putá.“<br/>Proti Bohu a Kristovi<br/>sa mocní spolu radia.<br/>',NULL,130701,1);
INSERT INTO stanza VALUES('SK1094','2','Ten, ktorý sedí v nebesiach,<br/>sa im vysmieva, smeje,<br/>bude k ním hovoriť v hneve,<br/>predesí ich a povie:<br/>„Na svätom vrchu Sione<br/>Kráľa som ustanovil.“<br/>Týmto slovom napomína<br/>Pán Boh kráľov na zemi.<br/>',NULL,130702,2);
INSERT INTO stanza VALUES('SK1094','3','Oznamujem rozhodnutie<br/>Hospodina, povedal:<br/>„Ty si môj Syn (vo vzkriesení),<br/>Ó, ja som ťa dnes splodil.“<br/>Všetky národy ti dávam<br/>ako dedičstvo Tvoje.<br/>Ty ich roztlčieš na kúsky,<br/>Pane, v nádhere Svojej.<br/>',NULL,130703,3);
INSERT INTO stanza VALUES('SK1094','4','Králi, buďte teda múdri,<br/>nechajte sa poučiť,<br/>slúžte s bázňou Pánovi a<br/>stále jasajte s chvením.<br/>Syna ľúbajme my všetci,<br/>aby sa nerozhneval,<br/>tak neumrieme na ceste.<br/>Vždy sa k Nemu utiekaj!<br/>',NULL,130704,4);
INSERT INTO stanza VALUES('SK1094','5','Chválime Ťa, že vidíme<br/>Tvojho vzácneho Krista,<br/>z márností vychádzame a<br/>v láske ľúbame Syna.<br/>Kto je v Ňom, je požehnaný,<br/>nie kto zákon zachová,<br/>ak veríme Vzkriesenému,<br/>navždy nám bude žehnať.<br/>',NULL,130705,5);
INSERT INTO stanza VALUES('SK1097','1','Aké slávne Tvoje meno,<br/>Ó, Pane na zemi!<br/>Nech to ohlasujú ľudia,<br/>kmene a jazyky.<br/>Z úst tých najmenších si, Pane,<br/>pevnosť ustanovil.<br/>’By bol Satan umlčaný,<br/>navždy ukončený.<br/>',NULL,130706,1);
INSERT INTO stanza VALUES('SK1097','2','Keď hľadíme na nebesia,<br/>dielo prstov Tvojich,<br/>ó, na mesiac a na hviezdy,<br/>múdro si ich stvoril.<br/>Čože je človek, ó, Pane,<br/>že naňho pamätáš,<br/>a Syn človeka, že sa ho<br/>sám v láske ujímaš.<br/>',NULL,130707,2);
INSERT INTO stanza VALUES('SK1097','3','Ó, Pán Ježiš, si ten človek,<br/>ktorý prišiel k ľuďom,<br/>prijal si najnižšie miesto,<br/>odel si sa telom.<br/>Dnes slávou korunovaný,<br/>Vládcom učinený<br/>skrze Svoje Telo vládneš,<br/>zem máš pod nohami.<br/>',NULL,130708,3);
INSERT INTO stanza VALUES('SK1097','4','Tvoje vtelenie, vzkriesenie,<br/>Tvoje vystúpenie,<br/>panstvo, hlavenstvo, kráľovstvo<br/>aj Telo tu zrieme.<br/>Týmto dielom si si, Pane,<br/>ustanovil chválu.<br/>Naše srdcia dnes radosťou,<br/>chválou pretekajú.<br/>',NULL,130709,4);
INSERT INTO stanza VALUES('SK1097','5','Čoskoro príde ten deň, keď<br/>budú znieť tie slová!<br/>No ich predchuť môžeme mať<br/>už dnes v miestnych cirkvách.<br/>Aké slávne Tvoje meno,<br/>ó, Pane na zemi!<br/>Nech to ohlasujú ľudia,<br/>kmene a jazyky.<br/>',NULL,130710,5);
INSERT INTO stanza VALUES('SK1098','1','Mnoho slov plných krásy<br/>nám zo srdca plynie,<br/>z toho, že sa tešíme<br/>Kráľovej nádhere.<br/>Jazyk sťa pero máme,<br/>opisuje mnohé –<br/>dielo nášho Ženícha,<br/>naše potešenie.<br/>',NULL,130711,1);
INSERT INTO stanza VALUES('SK1098','2','Pán Ježiš, si čestnejší,<br/>než sú všetci ľudia.<br/>ó, si presahujúci!<br/>Amen! Aleluja!<br/>Tvoje rty, Najsvätejší,<br/>sú milosti plné,<br/>si navždy požehnaný,<br/>vľúdny, slávny Pane!<br/>',NULL,130712,2);
INSERT INTO stanza VALUES('SK1098','3','Si mocným bojovníkom,<br/>čo víťazne jazdí.<br/>vo Svojom majestáte<br/>triumfálne jazdíš!<br/>Národy sa poddajú –<br/>Ty si dobyvateľ.<br/>Tvoje ostré šípy má<br/>už v sebe nepriateľ!<br/>',NULL,130713,3);
INSERT INTO stanza VALUES('SK1098','4','Tvoj trón, ó, Bože, stále<br/>na veky pretrvá.<br/>žezlo kráľovstva Tvojho<br/>nad zemou právo má.<br/>Si Bohom pomazaný<br/>olejom radosti,<br/>viac než Tvoji druhovia,<br/>je vzácne s Tebou žiť!<br/>',NULL,130714,4);
INSERT INTO stanza VALUES('SK1098','5','Myrhou, aloou, kasiou<br/>rúcho Tvoje vonia.<br/>to je predzvesťou Tvojej,<br/>smrti a vzkriesenia.<br/>Chvály miestnych cirkví Ťa,<br/>Pane, potešujú,<br/>keď v nich chválu na chválu<br/>svätí pripájajú.<br/>',NULL,130715,5);
INSERT INTO stanza VALUES('SK1099','1','Po Tvojej pravici je<br/>kráľovná, skrášlená<br/>zlatom z Ofíru, vôkol<br/>sú dcéry kráľovské.<br/>Cirkev vo svojej sláve,<br/>tá Kráľa doplní,<br/>a všetci svätí, dcéry,<br/>Ti budú podobní.<br/>',NULL,130716,1);
INSERT INTO stanza VALUES('SK1099','2','Počúvaj, dcéra, dávaj<br/>pozor a zbystri sluch,<br/>nič vlastné nespomínaj,<br/>zabudni na svoj ľud!<br/>Rozkvitne tvoja krása –<br/>po nej túži sám Kráľ,<br/>k chvále ťa podnecuje,<br/>je tvoj hodnotný Pán.<br/>',NULL,130717,2);
INSERT INTO stanza VALUES('SK1099','3','Dcérine slávne rúcho<br/>zlatom pretkávané –<br/>vo vnútornom paláci<br/>čírou nádherou je!<br/>Prirodzenosťou Boha<br/>je celkom odetá,<br/>’by celé Jeho bytie<br/>životom hlásala.<br/>',NULL,130718,3);
INSERT INTO stanza VALUES('SK1099','4','V prekrásnych výšivkách je<br/>pred Kráľa vedená,<br/>v tomto ľanovom rúchu<br/>bude ukázaná.<br/>Vyšívaním Ducha sa<br/>do nás Pán vpracoval,<br/>iba v tomto odeve<br/>nás k Sebe privádza.<br/>',NULL,130719,4);
INSERT INTO stanza VALUES('SK1099','5','Až Kráľa uvidíme,<br/>bude jasot, radosť,<br/>budeme kričať chvály<br/>už na celú večnosť.<br/>A hoci Ho my ctíme<br/>či sláva v kráľovnej,<br/>v tom potešení sláva<br/>iba pre Neho je.<br/>',NULL,130720,5);
INSERT INTO stanza VALUES('SK1103','1','Kým je Pán? On je Otcom.<br/>On je nekonečným Otcom.<br/>On prvý zo stvorenia je.<br/>On je tým, ktorý žije vo mne.<br/>On je Otec! Úžasné!<br/>',NULL,130721,1);
INSERT INTO stanza VALUES('SK1103','2','Čím je Pán? On je riekou.<br/>Je mocnou tečúcou riekou.<br/>Osviežuje ma na púšti.<br/>On je miestom, kde sa môžem skryť.<br/>On je riekou! Úžasné!<br/>',NULL,130722,2);
INSERT INTO stanza VALUES('SK1103','3','Čím je Pán? Je viničom.<br/>On je koreňom Jesseho.<br/>Je Strom života, jeme Ho.<br/>Na Jeho život máme právo.<br/>On je vinič! Úžasné!<br/>',NULL,130723,3);
INSERT INTO stanza VALUES('SK1103','4','Kto je Pán? On je Pastier.<br/>On je náš Baránok Boží.<br/>Pokrmom, odpočinkom je.<br/>Máme krv a Baránka jeme.<br/>On je Pastier! Úžasné!<br/>',NULL,130724,4);
INSERT INTO stanza VALUES('SK1103','5','Kým je Pán? On je Duchom.<br/>Všezahŕňajúcim Duchom.<br/>On je nám všetkým vo všetkom.<br/>Keď Naň voláme, dáva život.<br/>On je Duchom! Úžasné!<br/>',NULL,130725,5);
INSERT INTO stanza VALUES('SK1103','6','Kým je Pán? Je Osobou.<br/>Skutočnou živou Osobou.<br/>Prebýva vnútri všetkých nás.<br/>Aká nádherná tá Osoba.<br/>Je Osobou! Úžasné!<br/>',NULL,130726,6);
INSERT INTO stanza VALUES('SK1103','7','Čím je Pán? On je Telom.<br/>Ježiš je plnosťou Božstva.<br/>Je centrom plánu Otcovho.<br/>Novým človekom, Kristom s cirkvou.<br/>On je úžasný, úžasný.<br/>On je úžasný, úžasný.<br/>On je úžasný, úžasný.<br/>',NULL,130727,7);
INSERT INTO stanza VALUES('SK1107','1','Zišli sme sa tu ako jedno Telo,<br/>aj keď mnohí, a predsa sme jedno.<br/>Zdieľame Tvoj život, sme Tvoje údy,<br/>a tak sme v živote všetci jedno.<br/>',NULL,130728,1);
INSERT INTO stanza VALUES('SK1107','chorus','V celom vesmíre jedno Telo je<br/>a my ho vyjadrujeme.<br/>’By to všetkým bolo zjavné, my sme<br/>jedno v každej lokalite.<br/>',NULL,130729,2);
INSERT INTO stanza VALUES('SK1107','2','Jeden chlieb je symbolom Tvojho Tela,<br/>ktoré pre nás bolo prelomené.<br/>keď jeme chlieb a máme na ňom účasť,<br/>tak skutočnú jednotu zdieľame.<br/>',NULL,130730,3);
INSERT INTO stanza VALUES('SK1107','3','Na stole je len jeden chlieb a kalich,<br/>preto musíme aj my byť jedno.<br/>vykúpení, sme teraz Jeho Telo.<br/>„Amen“, vravíme: „Pane, sme jedno!“<br/>',NULL,130731,4);
INSERT INTO stanza VALUES('SK1107','4','Sme jednotní a nič nás nerozdelí,<br/>veď Kristus sám je našou jednotou.<br/>v jednote máme jeden chlieb a kalich,<br/>jednota táto je viditeľnou.<br/>',NULL,130732,5);
INSERT INTO stanza VALUES('SK1107','5','Požehnaná jednota je radosťou,<br/>Pane, my vnímame, si spokojný.<br/>sladko sme vzájomne uspokojení<br/>tak, ako je nevesta a ženích.<br/>',NULL,130733,6);
INSERT INTO stanza VALUES('SK1113','1','Trojjediný Boh prišiel, ’by prebýval<br/>ako nádherný Duch vnútri nás.<br/>My sme s Pánom zmiešaní, sme jedno s Ním,<br/>s oživujúcim Duchom, je v nás.<br/>',NULL,130734,1);
INSERT INTO stanza VALUES('SK1113','chorus','Ó, On je nádherný Duch vnútri nás,<br/>On je nádherný Duch vnútri nás.<br/>Otec je v Synovi a Syn je Duchom –<br/>On je nádherný Duch vnútri nás!<br/>',NULL,130735,2);
INSERT INTO stanza VALUES('SK1113','2','Výkrik „Abba, Otče“ vychádza z hlbín,<br/>kde je nádherný Duch vnútri nás.<br/>Je to Duch Syna, čo volá k Otcovi,<br/>oživujúci Duch, vnútri nás.<br/>',NULL,130736,3);
INSERT INTO stanza VALUES('SK1113','3','Ježiš Kristus Pán dnes žije vnútri nás<br/>ako nádherný Duch, On je v nás.<br/>Bol premenený, tak sa tešíme Ním,<br/>oživujúcim Duchom, je v nás.<br/>',NULL,130737,4);
INSERT INTO stanza VALUES('SK1113','4','Teraz je tu s nami Duch skutočnosti<br/>ako nádherný Duch vnútri nás.<br/>Skutočné, jasné sú Kristove veci,<br/>oživujúcim Duchom, je v nás.<br/>',NULL,130738,5);
INSERT INTO stanza VALUES('SK1113','5','Všetci roznecujeme vnútorný dar,<br/>je ním nádherný Duch vnútri nás.<br/>Ak voláme „Pán Ježiš“, duch vyviera<br/>s oživujúcim Duchom von z nás!<br/>',NULL,130739,6);
INSERT INTO stanza VALUES('SK1115','1','Prišli sme, prišli sme do domu Boha,<br/>do domu, čo z neho voda vyteká.<br/>Spod pravej strany vo dne v noci plynie,<br/>zavlažuje nás, nesieme ovocie.<br/>',NULL,130740,1);
INSERT INTO stanza VALUES('SK1115','2','Vyteká, vyteká z domu tok živý,<br/>z domu na zem tečie život najvyšší.<br/>Chceme však, aby bol omnoho hlbší.<br/>Zmeraj nás a všetkých si nás privlastni.<br/>',NULL,130741,2);
INSERT INTO stanza VALUES('SK1115','3','Meraj nás, meraj nás nepretržite,<br/>meraj nás viac a viac veľmi dôkladne.<br/>Z potoka sa stane záplava veľká,<br/>Pre Pána po celej zemi preteká.<br/>',NULL,130742,3);
INSERT INTO stanza VALUES('SK1115','4','Preveď nás, preveď nás, Pane, cez vodu,<br/>kamkoľvek pôjdeme, znovu a znovu.<br/>Voda sa zväčšuje, plávame v Tebe,<br/>v Bohu sme ponorení navždy, večne.<br/>',NULL,130743,4);
INSERT INTO stanza VALUES('SK1115','5','Ožije všetko, kam rieka pritečie,<br/>kamkoľvek pritečie všetko ožije.<br/>Nech prameň preteká, život udelí,<br/>cirkvi pučia uprostred zemských púští!<br/>',NULL,130744,5);
INSERT INTO stanza VALUES('SK1117','1','Chvála buď Bohu<br/>za Ducha Kristovho,<br/>ktorý v nás dnes prebýva<br/>a je náš život.<br/>',NULL,130745,1);
INSERT INTO stanza VALUES('SK1117','chorus','Aleluja! Máme Ducha!<br/>Aleluja! Je v nás!<br/>Aleluja! Život hojný,<br/>čo konca nemá!<br/>',NULL,130746,2);
INSERT INTO stanza VALUES('SK1117','2','V duchu spievame<br/>o Tom, ktorý prišiel,<br/>On – Duch oživujúci<br/>s nami jedno je.<br/>',NULL,130747,3);
INSERT INTO stanza VALUES('SK1117','chorus','Aleluja! Je to Ježiš!<br/>Aleluja! Ba viac!<br/>Aleluja! On je Duchom!<br/>Navždy život náš!<br/>',NULL,130748,4);
INSERT INTO stanza VALUES('SK1117','3','V duchu splodení,<br/>teraz premieňaní,<br/>k Synovi tak budeme<br/>pripodobnení.<br/>',NULL,130749,5);
INSERT INTO stanza VALUES('SK1117','chorus','Aleluja! Dáva život!<br/>Aleluja! Mení!<br/>Aleluja! Veď už skoro<br/>nás pripodobní!<br/>',NULL,130750,6);
INSERT INTO stanza VALUES('SK1117','4','V duchu žijeme,<br/>Pán nás naplňuje,<br/>ako Duch vo Svoj obraz<br/>pripodobňuje.<br/>',NULL,130751,7);
INSERT INTO stanza VALUES('SK1117','chorus','Aleluja! Spása plná!<br/>Aleluja! Pre nás!<br/>Aleluja! Dostatočná<br/>je pre život náš!<br/>',NULL,130752,8);
INSERT INTO stanza VALUES('SK1122','1','Hľa, sedem Duchov Božích –<br/>obdobie sa zmenilo,<br/>o cirkvi sa dnes stará<br/>ten Duch spolu so Synom.<br/>',NULL,130753,1);
INSERT INTO stanza VALUES('SK1122','chorus','Sedemnásobný Duch príď,<br/>obnovu uskutočniť!<br/>Skúmaj, spaľuj dôkladne,<br/>cirkvi sú všetky Tvoje,<br/>spaľuj, skúmaj,<br/>všetky cirkvi sú Tvoje!<br/>',NULL,130754,2);
INSERT INTO stanza VALUES('SK1122','2','Duch je sedemnásobný<br/>vinou úpadku cirkvi,<br/>’by svätí mohli ožiť<br/>a byť Pánom skúmaní.<br/>',NULL,130755,3);
INSERT INTO stanza VALUES('SK1122','3','Duch Boží dnes silu má,<br/>sedemnásobne zmocnel,<br/>sedemkrát nie iba raz,<br/>aby zásobil cirkev!<br/>',NULL,130756,4);
INSERT INTO stanza VALUES('SK1122','4','Dnes je tých sedem Duchov<br/>sedem lámp, horiace sú,<br/>spaľujú, neučia nás,<br/>Boha uspokojujú.<br/>',NULL,130757,5);
INSERT INTO stanza VALUES('SK1122','5','Siedmimi očami sú,<br/>skúmajú, prenikajú,<br/>v cirkvi nás odhaľujú<br/>a cirkev očisťujú.<br/>',NULL,130758,6);
INSERT INTO stanza VALUES('SK1122','6','Sedem Duchov pôsobí<br/>vo všetkých miestnych cirkvách,<br/>’by všetci svätí mohli<br/>potešenie z Ducha mať.<br/>',NULL,130759,7);
INSERT INTO stanza VALUES('SK1131','1','Uväznení a beznádejní,<br/>chceli sme veriť, no nemohli.<br/>Boh to vyjasnil, Ježiša zjavil.<br/>Sme Ním naplnení!<br/>Sme Ním naplnení!<br/>',NULL,130760,1);
INSERT INTO stanza VALUES('SK1131','chorus','Jeho krvou sme uzmierení,<br/>Bohu patríme, vykúpení.<br/>Nie súdení, ospravedlnení!<br/>Máme mier s Bohom!<br/>Máme mier s Bohom!<br/>',NULL,130761,2);
INSERT INTO stanza VALUES('SK1131','2','V Adamovi sme umierali,<br/>nemohli sme byť uzdravení.<br/>Boh poslal Syna, skončil Adama,<br/>je mŕtvy, my voľní!<br/>Je mŕtvy, my voľní!<br/>',NULL,130762,3);
INSERT INTO stanza VALUES('SK1131','3','Stojíme v milosti, radostní,<br/>aleluja, hriech je vymazaný.<br/>Boh cez nás tečie a v srdciach rastie.<br/>V živote sme zachránení!<br/>V živote sme zachránení!<br/>',NULL,130763,4);
INSERT INTO stanza VALUES('SK1132','1','Sám nás uč modliť sa,<br/>nie cestou národov, márne,<br/>odvráť nás z cesty tej<br/>a vzývať nám daj Teba každý deň –<br/>Pán Ježiš, rasti v nás.<br/>',NULL,130764,1);
INSERT INTO stanza VALUES('SK1132','2','Si semä života.<br/>zasadený si, Pane, v nás,<br/>počiatok teraz máš.<br/>tak deň čo deň vkladaj život do nás –<br/>Pán Ježiš, rasti v nás.<br/>',NULL,130765,2);
INSERT INTO stanza VALUES('SK1132','3','Obmäkči, Pane, nás.<br/>Pane, zdroj náš dobre poznáš.<br/>Voláme na Teba,<br/>nech niet ničoho v nás okrem Teba –<br/>Pán Ježiš, rasti v nás.<br/>',NULL,130766,3);
INSERT INTO stanza VALUES('SK1132','4','Svetlo nám zjavuje,<br/>že my sami nemôžeme.<br/>no správa dobrá znie,<br/>že v nás živé semeno vyrastie –<br/>Pán Ježiš, rasti v nás.<br/>',NULL,130767,4);
INSERT INTO stanza VALUES('SK1132','5','Prázdnymi v duchu čiň.<br/>všetko iné vyberaj z nás.<br/>Chceme tok života,<br/>prijímať život, ktorý dáva rast –<br/>Pán Ježiš, rasti v nás.<br/>',NULL,130768,5);
INSERT INTO stanza VALUES('SK1132','6','Čiň čistými v srdci.<br/>my nebudeme spokojní,<br/>pokiaľ nenaplníš,<br/>myseľ, city, vôľu neobnovíš –<br/>Pán Ježiš, rasti v nás.<br/>',NULL,130769,6);
INSERT INTO stanza VALUES('SK1132','7','Do srdca vštepuj nám,<br/>že Ťa prijímať musíme.<br/>semeno rásť bude,<br/>Tvoj rast prinesie kráľovstvo na zem –<br/>Pán Ježiš, rasti v nás.<br/>',NULL,130770,7);
INSERT INTO stanza VALUES('SK1132','8','Amen! Rast v živote!<br/>Tvoj život to uskutoční.<br/>každú časť obnoví,<br/>až Ti budeme všetci podobní –<br/>Pán Ježiš, rasti v nás.<br/>Pán Ježiš, rasti v nás.<br/>',NULL,130771,8);
INSERT INTO stanza VALUES('SK1134','1','Pane, posilni ducha môjho,<br/>posilni môjho ducha,<br/>posilni mocou ducha môjho,<br/>šír sa do môjho srdca.<br/>',NULL,130772,1);
INSERT INTO stanza VALUES('SK1134','chorus','Rozširuj sa, rozširuj sa<br/>do môjho srdca, môj Pane,<br/>čiň si domov a cestu maj<br/>v celom mojom srdci, Pane.<br/>',NULL,130773,2);
INSERT INTO stanza VALUES('SK1134','2','Rozširuj sa do srdca môjho,<br/>Pán Ježiš, rozširuj sa,<br/>šír sa z ducha do srdca môjho,<br/>do srdca rozširuj sa.<br/>',NULL,130774,3);
INSERT INTO stanza VALUES('SK1134','3','Svoj dom v mojom srdci buduj si,<br/>Pane Ježišu, buduj,<br/>aby sme boli naplnení,<br/>Pane, plnosťou Tvojou.<br/>',NULL,130775,4);
INSERT INTO stanza VALUES('SK1134','4','Tomu, čo to vykonať môže<br/>ponad naše chápanie,<br/>široko srdcia otvárame,<br/>v srdci Ho dnes vítame.<br/>',NULL,130776,5);
INSERT INTO stanza VALUES('SK1135','1','Posväcuj nás, Pane, pridávaj sa do nás,<br/>nech Ťa zakúšame, rozprestieraj sa v nás,<br/>v skutočnosti, Pane, nech cirkev slávnu máš.<br/>Pridávaj sa do nás aj dnes.<br/>',NULL,130777,1);
INSERT INTO stanza VALUES('SK1135','chorus','Posväcuj nás, ó, Pane, dnes,<br/>Ježiš jedinou Cestou je.<br/>Berieme Ťa, Pane,<br/>rozširuj sa všade,<br/>Pane, posväcuj nás aj dnes.<br/>',NULL,130778,2);
INSERT INTO stanza VALUES('SK1135','2','Prečisťuj nás, Pane, srdcu sa prihovor,<br/>obmytie spôsobíš Svojím živým slovom.<br/>Povedz nám stále viac, očisťuj nás Sebou.<br/>Pane, prečisťuj nás aj dnes.<br/>',NULL,130779,3);
INSERT INTO stanza VALUES('SK1135','chorus','Prečisťuj nás, ó, Pane, dnes,<br/>prirodzený život odnes.<br/>Tvoje slová sú v nás,<br/>slávnymi činia nás,<br/>Pane, prehovor v nás aj dnes.<br/>',NULL,130780,4);
INSERT INTO stanza VALUES('SK1135','3','Vyživuj nás, Pane, si našou potravou,<br/>zatiaľ čo Ťa jeme, prejdeme premenou,<br/>sme uspokojení, nasýtení Tebou.<br/>Pane, vyživuj nás aj dnes.<br/>',NULL,130781,5);
INSERT INTO stanza VALUES('SK1135','chorus','Vyživuj nás, ó, Pane, dnes,<br/>a celé naše ja odnes.<br/>Ty nás očisťuješ,<br/>aj uspokojuješ.<br/>Pane, vyživuj nás aj dnes.<br/>',NULL,130782,6);
INSERT INTO stanza VALUES('SK1135','4','Zatiaľ čo Ťa jeme, opatruj nás, Pane,<br/>nežne sa postaraj, doplň v čom núdza je,<br/>zjemňuj, keď sme hrubí, patríme len Tebe.<br/>Pane, opatruj nás aj dnes.<br/>',NULL,130783,7);
INSERT INTO stanza VALUES('SK1135','chorus','Opatruj nás, ó, Pane, dnes,<br/>našu chladnú bytosť odnes.<br/>Udržuj pri Sebe,<br/>opatruj nás nežne.<br/>Pane, opatruj nás aj dnes.<br/>',NULL,130784,8);
INSERT INTO stanza VALUES('SK1135','5','Učiň nás slávnymi, vnútornou prácou v nás,<br/>sláva nie je pre nás, no pre cirkev ju máš.<br/>Túžiš po neveste, nájdi to, čo hľadáš.<br/>Pane, pracuj na nás aj dnes.<br/>',NULL,130785,9);
INSERT INTO stanza VALUES('SK1135','chorus','Pane, na nás pracuj aj dnes!<br/>Buduj cirkev, len Ty to vieš.<br/>Ó, rozširuj sa v nás,<br/>až kým nás slávnych máš,<br/>slávnymi učiň nás aj dnes.<br/>',NULL,130786,10);
INSERT INTO stanza VALUES('SK1141','1','Budeme spievať Pánovi s duchom,<br/>budeme Mu spievať z hlbiny,<br/>budeme Mu spievať aleluja,<br/>jedno s Ním, vzájomne zmiešaní.<br/>',NULL,130787,1);
INSERT INTO stanza VALUES('SK1141','2','V náboženstve sme míňali roky,<br/>roky sme v mysli strácali čas,<br/>vo svojich citoch trávili roky,<br/>avšak nič sme nevedeli nájsť.<br/>',NULL,130788,2);
INSERT INTO stanza VALUES('SK1141','3','Učíme sa otáčať sa k duchu,<br/>aby sme Krista získavali,<br/>ako jesť Ježiša chceme vedieť,<br/>od vlastnej námahy slobodní.<br/>',NULL,130789,3);
INSERT INTO stanza VALUES('SK1141','4','Aleluja za život, je v Duchu,<br/>vnútri máme novosť života,<br/>ak sa vrátime od umu k duchu,<br/>vychutnáme Jeho bohatstvá.<br/>',NULL,130790,4);
INSERT INTO stanza VALUES('SK1142','1','Pán Ježiš, On je živý Duch,<br/>naša skutočnosť.<br/>Vzývaním Ho získavame,<br/>ó, jednoduchosť.<br/>',NULL,130791,1);
INSERT INTO stanza VALUES('SK1142','chorus','Vyhlasujeme, že Ježiš<br/>Pán je živý Duch,<br/>je bohatý voči všetkým,<br/>čo Ho vzývajú.<br/>',NULL,130792,2);
INSERT INTO stanza VALUES('SK1142','2','V nás prebýva Pán – živý Duch,<br/>oslobodzuje,<br/>je dobrý a milostivý,<br/>ak Ho vzývame.<br/>',NULL,130793,3);
INSERT INTO stanza VALUES('SK1142','3','Pán Ježiš, On je živý Duch<br/>a Slovo živé,<br/>čítame ho modlitebne,<br/>tým Ho získame.<br/>',NULL,130794,4);
INSERT INTO stanza VALUES('SK1142','4','Pán Ježiš, On je živý Duch,<br/>medzi nami prúd,<br/>spoločenstvom v našom duchu<br/>máme jednotu.<br/>',NULL,130795,5);
INSERT INTO stanza VALUES('SK1142','5','náš stôl bohatý,<br/>ak Ho Telo vychutnáva,<br/>chválu uvoľní.<br/>',NULL,130796,6);
INSERT INTO stanza VALUES('SK1143','1','Aký sladký strom života –<br/>Boh môj životom je.<br/>Bol mŕtvym som, no ožil som,<br/>hladným, no teraz jem.<br/>',NULL,130797,1);
INSERT INTO stanza VALUES('SK1143','2','Boh sám ma k stromu priviedol,<br/>Kristus pokrmom je.<br/>Akým cenným sa ten strom stal,<br/>keď som ho začal jesť.<br/>',NULL,130798,2);
INSERT INTO stanza VALUES('SK1143','3','Pán sám je pre mňa pokrmom,<br/>zásobou života.<br/>bude mi vychutnávaním,<br/>aké nikto nedá.<br/>',NULL,130799,3);
INSERT INTO stanza VALUES('SK1143','4','Zadarmo z toho stromu jem,<br/>jedenie cestou je,<br/>ako získať Boží život<br/>a žiť skrz Neho dnes.<br/>',NULL,130800,4);
INSERT INTO stanza VALUES('SK1146','1','Jedzme telo Ježišovo,<br/>jedzme konkrétnym spôsobom,<br/>aby nám keď sme skúšaní,<br/>Pán bol ako človek všetkým.<br/>',NULL,130801,1);
INSERT INTO stanza VALUES('SK1146','chorus','Jedzme viac Ježiša!<br/>Jedzme viac Ježiša!<br/>Prečo ostať bez výživy?<br/>Človek Ježiš je prístupný.<br/>',NULL,130802,2);
INSERT INTO stanza VALUES('SK1146','2','Chceš mať ľudskosť Ježišovu?<br/>Pi Ježiša ako vodu!<br/>Rieky mŕtvu zem zaplavia,<br/>všade vôkol smäd uhasia.<br/>',NULL,130803,3);
INSERT INTO stanza VALUES('SK1146','chorus','Pime viac Ježiša!<br/>Pime viac Ježiša!<br/>Prečo máme ostať smädní?<br/>Človek Ježiš je prístupný.<br/>',NULL,130804,4);
INSERT INTO stanza VALUES('SK1146','3','Jesť Ježiša musíme kým<br/>plán Boží sa nenaplní,<br/>jeden človek vyjadrený,<br/>prostredníctvom miestnych cirkví.<br/>',NULL,130805,5);
INSERT INTO stanza VALUES('SK1146','chorus','Strávime Ježiša!<br/>Strávime Ježiša!<br/>Pokrmovú obeť pravú<br/>prinesme všetci do stanu.<br/>',NULL,130806,6);
INSERT INTO stanza VALUES('SK1148','1','Pán volá: „Na hostinu príď jesť a piť.“<br/>Pána stále môžeme my jesť a piť!<br/>Denne nás On zásobí,<br/>len On nás uspokojí.<br/>Pán volá: „Na hostinu príď jesť a piť.“<br/>',NULL,130807,1);
INSERT INTO stanza VALUES('SK1148','2','Pán volá: „Na hostinu príď jesť a piť.“<br/>Ak my Pána budeme vždy jesť a piť,<br/>skrze nás On bude žiť,<br/>Sebou nás chce naplniť.<br/>Pán volá: „Na hostinu príď jesť a piť.“<br/>',NULL,130808,2);
INSERT INTO stanza VALUES('SK1151','1','Pi! Rieku čistú a číru, z trónu vyteká.<br/>Jedz! Strom života, hojné, bohaté plody má.<br/>Hľa! Nie je potrebná lampa, slnko či mesiac,<br/>veď stále je tu deň!<br/>',NULL,130809,1);
INSERT INTO stanza VALUES('SK1151','chorus','Tak príď, ó, len príď,<br/>Duch s nevestou volá.<br/>Tak príď, ó, len príď,<br/>kto počuje, volá.<br/>Tak príď, ó, len príď,<br/>smädný, ak si želáš<br/>brať zadarmo vodu živú!<br/>',NULL,130810,2);
INSERT INTO stanza VALUES('SK1151','2','Kristus – rieka, naša voda, čo z nás vyteká!<br/>Kristus je strom, jeho ovocie vždy vychutnám!<br/>Kristus, náš deň, naše svetlo, naša zornička,<br/>On je všetkým pre nás!<br/>',NULL,130811,3);
INSERT INTO stanza VALUES('SK1151','3','Perieme si rúcha, tak strom života jeme!<br/>„Pane, amen, aleluja!“ Ježiš sladký je!<br/>Uplatňujúc ducha, je nami prežívaný!<br/>Náš Pán je úžasný!<br/>',NULL,130812,4);
INSERT INTO stanza VALUES('SK1151','4','Takto máme domov nad slnka žiar jasnejší!<br/>Kde sú všetci bratia jedno, sme zjednotení!<br/>Ježiš nás zhromaždil, teraz je v miestnej cirkvi<br/>cez nás vyjadrený.<br/>',NULL,130813,5);
INSERT INTO stanza VALUES('SK1152','1','Každý deň sme k Ježišovi bližšie pritiahnutí,<br/>je férovejší než ľudia, než ráno sviežejší.<br/>Je viac ako to, čo sme o Ňom povedať schopní,<br/>každý deň nám je vzácnejší, ako bol deň predtým.<br/>',NULL,130814,1);
INSERT INTO stanza VALUES('SK1152','chorus','Nedá sa to opísať, cenný je, nádherný.<br/>Každý deň nám je vzácnejší, ako bol deň predtým.<br/>',NULL,130815,2);
INSERT INTO stanza VALUES('SK1152','2','Zbadali sme Ho v cirkvi, sláva vzplanula na nás,<br/>našli sme Ho tu, sú tu všetky Jeho bohatstvá.<br/>Iba v cirkvi je náš duch plne uspokojený,<br/>každý deň nám je vzácnejší, ako bol deň predtým.<br/>',NULL,130816,3);
INSERT INTO stanza VALUES('SK1152','3','On je živým Duchom, prebýva v našom duchu dnes,<br/>sladkým pomazaním sa Jeho život zväčšuje.<br/>Na stretnutiach sa duch nadnáša, je uvoľnený,<br/>každý deň nám je vzácnejší, ako bol deň predtým.<br/>',NULL,130817,4);
INSERT INTO stanza VALUES('SK1152','4','Kvôli Jeho obnove s Pánom sme zjednotení,<br/>Jeho bohatstvo, Jeho plnosť cirkev vyjadrí.<br/>Každý deň sme na Pána so všetkým vylievaní,<br/>Pre Jeho zámer nádherný, každý deň vzácnejší.<br/>',NULL,130818,5);
INSERT INTO stanza VALUES('SK1153','1','Našli sme Krista, je nám všetkým,<br/>On všetkým vo všetkom je.<br/>Volať Naňho je požehnaním,<br/>je to slávne a božské!<br/>',NULL,130819,1);
INSERT INTO stanza VALUES('SK1153','chorus','Je to nevýslovná radosť plná slávy,<br/>plná slávy, plná slávy.<br/>Je to nevýslovná radosť plná slávy<br/>a len kúsok je odhalený.<br/>',NULL,130820,2);
INSERT INTO stanza VALUES('SK1153','2','Zistili sme, že Pán je Duchom,<br/>v našom duchu prebýva,<br/>je veľmi prístupný, je blízko,<br/>vynikajúcu chuť má.<br/>',NULL,130821,3);
INSERT INTO stanza VALUES('SK1153','3','Modlitebné čítanie Slova,<br/>volanie Jeho mena<br/>je jedením a pitím Pána.<br/>Takto žijeme z Krista!<br/>',NULL,130822,4);
INSERT INTO stanza VALUES('SK1153','4','Našli sme miestnu cirkev, náš dom,<br/>tu sme skutočne doma!<br/>Nepotrebujeme Babylon,<br/>v cirkvi je to, čo treba.<br/>',NULL,130823,5);
INSERT INTO stanza VALUES('SK1153','5','Naše spoločné stretnutia sú<br/>najväčším potešením,<br/>preto náš duch neoslabuje<br/>a my sme naplnení.<br/>',NULL,130824,6);
INSERT INTO stanza VALUES('SK1154','1','Ja milujem Ťa<br/>a láska Tvoja<br/>vždy ma tiahne hľadať Ťa,<br/>za Tebou bežať,<br/>vždy ma tiahne hľadať Ťa,<br/>za Tebou bežať.<br/>Si milovaný<br/>a tiež najľúbeznejší!<br/>Moje srdce sa v Tebe teší.<br/>',NULL,130825,1);
INSERT INTO stanza VALUES('SK1154','2','Nad víno sladšia<br/>je láska Tvoja.<br/>Tvoja vôňa olejov<br/>srdce objíma,<br/>Tvoja vôňa olejov<br/>srdce objíma.<br/>Fontána v sadoch<br/>a studňa vôd živých,<br/>tečú, prúdia z hôr Libanonských.<br/>',NULL,130826,2);
INSERT INTO stanza VALUES('SK1154','3','Len príď do môjho<br/>sadu, môj Milý,<br/>nech len prúdia balzamy<br/>ako bystriny,<br/>nech len prúdia balzamy<br/>ako bystriny.<br/>Sestra, nevesta,<br/>do záhrady som prišiel<br/>na víne a mede hodovať.<br/>',NULL,130827,3);
INSERT INTO stanza VALUES('SK1154','4','Polož si ma na<br/>srdce jak pečať.<br/>žiarlivosť ako hrob je,<br/>láska ako smrť,<br/>žiarlivosť ako hrob je,<br/>láska ako smrť.<br/>Veľké vody ju,<br/>tú lásku, neuhasia.<br/>Čo môžeš dať za túto lásku?<br/>',NULL,130828,4);
INSERT INTO stanza VALUES('SK1159','1','Zajatý, Pán Ježiš, Tvojou krásou<br/>dokorán Ti otváram srdce.<br/>Nemusím sa nábožensky snažiť,<br/>dovoľ mi iba zostať v Tebe.<br/>Zatiaľ čo hľadím na Tvoju slávu,<br/>nasycuj ma božským žiarením.<br/>Ó, celé moje srdce napĺňaj,<br/>premiešaj Svojho Ducha s mojím.<br/>',NULL,130829,1);
INSERT INTO stanza VALUES('SK1159','2','Žiarivý si, všetko je tu jasné,<br/>si na tróne, ó, človeka Syn.<br/>Si Svätý, Boží plameň ma trávi,<br/>až dokiaľ Tebou nezažiarim.<br/>V deň, keď som Ťa uzrel v Tvojom lesku,<br/>samoľúbosť skončila hanbou.<br/>predkladám Ti srdcom z lásky chválu,<br/>vychutnávajúc Tvoje meno.<br/>',NULL,130830,2);
INSERT INTO stanza VALUES('SK1159','3','Svoju nádobu alabastrovú<br/>teraz z lásky k Tebe rozbíjam.<br/>Môj Milý, pomažem Tvoju hlavu,<br/>najcennejšie iba Tebe dám.<br/>Najdrahší, kvôli Tebe sa zmárnim,<br/>milujúc Ťa, uspokojený.<br/>Lásku zvnútra vyliatu Ti dávam,<br/>aj cenný olej, Pane drahý.<br/>',NULL,130831,3);
INSERT INTO stanza VALUES('SK1159','4','Na vonnú horu poď Milovaný,<br/>Teba tvárou v tvár nech uvidím.<br/>Z prameňa môjho srdca pi, až kým<br/>nespočiniem v Tvojom objatí.<br/>Nie som sám kto Ťa miluje,<br/>Pane, sme svätí spoločne, nevesta.<br/>Rýchle príď, veď Ťa spolu čakáme,<br/>budeme Ťa uspokojovať.<br/>',NULL,130832,4);
INSERT INTO stanza VALUES('SK1161','1','Z hľadajúcich milovníkov<br/>budú stĺpy, nosidlá,<br/>koruna, chvála a sláva,<br/>Kristus Pán to vykoná.<br/>',NULL,130833,1);
INSERT INTO stanza VALUES('SK1161','chorus','Svoju milovanú ľúbi,<br/>príťažlivá je, ladná.<br/>Celkom si Ho podmanila,<br/>je prekrásna, úhľadná.<br/>',NULL,130834,2);
INSERT INTO stanza VALUES('SK1161','2','Avšak stále niečo chýba,<br/>ešte nie je spokojný,<br/>chce mať záhradu kvitnúcu,<br/>nevestu, čo Ho teší.<br/>',NULL,130835,3);
INSERT INTO stanza VALUES('SK1161','3','Je sadom granátovníkov<br/>s ovocím utešeným,<br/>nard, šafrán, myrha, aloe,<br/>všetkým týmto Ho teší.<br/>',NULL,130836,4);
INSERT INTO stanza VALUES('SK1161','4','Prišiel do záhrady svojej<br/>myrhu vziať, aj balzamy,<br/>vychutnať si medový plást,<br/>navždy víno, mlieko piť.<br/>',NULL,130837,5);
INSERT INTO stanza VALUES('SK1161','5','Záhrada poskytla mestu<br/>materiály pre stavbu,<br/>nepriateľ je vystrašený,<br/>radosť má Boh úplnú.<br/>',NULL,130838,6);
INSERT INTO stanza VALUES('SK1161','6','Krásna si sťa mesto Tirca,<br/>sťa Jeruzalem pekná.<br/>Amen, Ty všetko vykonáš<br/>Pán Ježiš, Aleluja!<br/>',NULL,130839,7);
INSERT INTO stanza VALUES('SK1162','1','Tajomstvo žitia sme našli,<br/>víziu uvideli.<br/>to, že sme z Boha v Kristovi,<br/>preto prebývame na viniči.<br/>',NULL,130840,1);
INSERT INTO stanza VALUES('SK1162','chorus','Preto prebývame!<br/>Preto prebývame!<br/>Božský život vychutnávame!<br/>Boh nás sem umiestnil,<br/>nastálo sem vložil,<br/>tak prebývame na viniči.<br/>',NULL,130841,2);
INSERT INTO stanza VALUES('SK1162','2','Viacej nemusíme hľadať<br/>do vnútra cestu sami,<br/>pretože my už sme v Bohu,<br/>aleluja, na viniči sme my.<br/>',NULL,130842,3);
INSERT INTO stanza VALUES('SK1162','3','Olej sa pohybuje v nás,<br/>to je to pomazanie,<br/>rozdáva samého Boha,<br/>pretože v Pánovi prebývame.<br/>',NULL,130843,4);
INSERT INTO stanza VALUES('SK1162','4','Tak kráčame v prúde živom,<br/>v tom prúde On v nás žiari.<br/>Majú tak Boh aj človek dom,<br/>spolu prebývajú na viniči.<br/>',NULL,130844,5);
INSERT INTO stanza VALUES('SK1164','1','Pán Ježiš je pre mňa všetkým,<br/>mojou dobrou zemou:<br/>je potokmi, je prameňmi,<br/>voľne tečie s vervou.<br/>Vyviera z hôr aj údolí,<br/>prúdi, všetkých nás naplní,<br/>zavlažuje, osviežuje –<br/>životom!<br/>',NULL,130845,1);
INSERT INTO stanza VALUES('SK1164','2','Vtelený, ukrižovaný –<br/>je zemou pšenice.<br/>Že je životom vzkriesenia,<br/>jačmeň naznačuje.<br/>Je zemou fíg aj viniča –<br/>z hrozna a vína radosť mám.<br/>Zaopatrí, uspokojí –<br/>Kristus – zem!<br/>',NULL,130846,2);
INSERT INTO stanza VALUES('SK1164','3','Prebohatý, hojný Kristus,<br/>granátovníka plod.<br/>Z olivovníka olejom<br/>natiera nanovo.<br/>Je bohatý na mlieko, med,<br/>sladko nás uspokojuje.<br/>On je taký prebohatý!<br/>Ó, Kristus!<br/>',NULL,130847,3);
INSERT INTO stanza VALUES('SK1164','4','V tej dobrej zemi jeme chlieb.<br/>Náš Pán je bohatý.<br/>V Ňom núdza neexistuje,<br/>plný je, prehojný.<br/>Je zemou šírou, nesmiernou,<br/>v každom zmysle dokonalou.<br/>Dnes sa šíri tá zem zemí<br/>nám v srdci!<br/>',NULL,130848,4);
INSERT INTO stanza VALUES('SK1164','5','Kristus je zemou železa,<br/>On právomoci má,<br/>My Ho musíme vykopať,<br/>zviazať nepriateľa.<br/>Musíme prejsť utrpením,<br/>byť bronzoví, prečistení.<br/>Byť železní, prebrúsení,<br/>musíme!<br/>',NULL,130849,5);
INSERT INTO stanza VALUES('SK1164','6','Chválime Ťa za túto zem,<br/>Kristus je nám všetkým!<br/>Jeho jeme, napĺňa nás,<br/>On je dostatočný.<br/>Na skutočnosti rozsiahlej<br/>uč nás namáhať sa ďalej.<br/>Radosť naša, práca naša –<br/>Kristus – Zem!<br/>',NULL,130850,6);
INSERT INTO stanza VALUES('SK1168','1','Na Pánovi, dobrej zemi, pracuj,<br/>or a vysádzaj, pole zavlažuj.<br/>Úrodu skutočnosti prinesie,<br/>Boh zožne plody Ježiša vo mne.<br/>',NULL,130851,1);
INSERT INTO stanza VALUES('SK1168','chorus','Ježiš si dobrou zemou,<br/>na Tebe pracujem!<br/>Po kúskoch Ťa získavam,<br/>celkom privlastňujem!<br/>S Kanánom má Boh zámer,<br/>námahu požehná,<br/>Pán Ježiš, tu Ťa získavam,<br/>Tvoju Osobu mám.<br/>',NULL,130852,2);
INSERT INTO stanza VALUES('SK1168','2','Srdcom na Ježišovi pracujem,<br/>začal som, vôbec to neľutujem.<br/>Boh s námahou mojou zosiela dážď,<br/>prácou na Kristovi mnohé vyhráš.<br/>',NULL,130853,3);
INSERT INTO stanza VALUES('SK1168','3','Na Pánovi pracujem prakticky,<br/>každý deň v duchu Slovom sa modlím.<br/>Nasledujem Jeho pomazanie,<br/>v cirkvi tak nastáva budovanie.<br/>',NULL,130854,4);
INSERT INTO stanza VALUES('SK1168','4','Ó, práca na Ňom v skutočnosť vedie,<br/>stretávanie sa je Krista plné.<br/>Boh aj človek sú uspokojení,<br/>tam prítomnosť Božiu každý vidí.<br/>',NULL,130855,5);
INSERT INTO stanza VALUES('SK1168','5','Pracuj na Ňom, nech sa Ježiš zväčší!<br/>Príď sa do Božieho domu tešiť!<br/>Ponúkni tam Pánovi prebytok,<br/>jedz z bohatstiev, z Pána maj pôžitok!<br/>',NULL,130856,6);
INSERT INTO stanza VALUES('SK1170','1','Pán je mojím Pastierom navždy,<br/>na pastvu ma ukladá,<br/>vodí ma popri tichých vodách<br/>a uspokojuje ma!<br/>',NULL,130857,1);
INSERT INTO stanza VALUES('SK1170','chorus','Tvoja láska a milosť budú so mnou<br/>vo všetkých dňoch môjho života.<br/>Tvoja láska a milosť budú so mnou<br/>vo všetkých dňoch môjho života.<br/>A budem bývať v dome Pánovom naveky<br/>a vychutnávať Ho na hostine vždy.<br/>Tvoja láska a milosť budú so mnou<br/>vo všetkých dňoch môjho života.<br/>',NULL,130858,2);
INSERT INTO stanza VALUES('SK1170','2','Sám môj Pastier je mojou pastvou,<br/>vodami odpočinku.<br/>som požehnaný, ak jem, pijem<br/>Jeho bohatstvá v duchu!<br/>',NULL,130859,3);
INSERT INTO stanza VALUES('SK1170','3','Pastier mi dušu obnovuje,<br/>vôľu, city a myseľ.<br/>hoci kráčam temným údolím,<br/>Spoločníka som našiel!<br/>',NULL,130860,4);
INSERT INTO stanza VALUES('SK1170','4','Na prestretom stole hodujem,<br/>Satan je porazený.<br/>Olejom mažeš moju hlavu,<br/>kalich mám preplnený!<br/>',NULL,130861,5);
INSERT INTO stanza VALUES('SK1170','5','Teraz prebývam v Jeho dome,<br/>z Boha sa veľmi teším.<br/>len ťažko sa to opisuje,<br/>môj Pán Ježiš ma teší!<br/>',NULL,130862,6);
INSERT INTO stanza VALUES('SK1174','1','Čo za víťazstvo a triumf!<br/>stal sa človekom Boh sám,<br/>Vzal si ľudskú prirodzenosť,<br/>’by uskutočnil Svoj plán.<br/>Svojou smrťou zničil diabla,<br/>vstal ako Syn človeka!<br/>',NULL,130863,1);
INSERT INTO stanza VALUES('SK1174','2','Ježiš ľudskými cnosťami<br/>Zákerného uväznil,<br/>človek zniesol pokušenia,<br/>v každej skúške zvíťazil.<br/>Teraz som si svojím duchom,<br/>Jeho cnosti privlastnil.<br/>',NULL,130864,2);
INSERT INTO stanza VALUES('SK1174','3','V Duchu tohto Ježiša<br/>je Jeho život ľudský.<br/>Cnosti ľudské sú pridané,<br/>sú súčasť Ducha, všetky.<br/>Ó, aká to hojnosť v Duchu,<br/>zaopatruje všetkých!<br/>',NULL,130865,3);
INSERT INTO stanza VALUES('SK1174','4','Je tajomné, no skutočné!<br/>Tento človek je vo mne.<br/>Šíri sa mi v celom srdci,<br/>mojím životom byť chce.<br/>Aleluja! Aleluja!<br/>Chvály Mu spievam večné.<br/>',NULL,130866,4);
INSERT INTO stanza VALUES('SK1174','5','Aké predivné a slávne!<br/>Boh je v tele zjavený.<br/>My, údy Jeho Tela sme<br/>prejavom tej ľudskosti.<br/>Jeho ľudský život máme<br/>pre budovanie stavby.<br/>',NULL,130867,5);
INSERT INTO stanza VALUES('SK1177','1','Kristus vo Svojej sláve si ľudskosť obliekol,<br/>’by žil namiesto mňa a bol osobou mojou.<br/>Človek v živote, povahe, sa ku mne hodí,<br/>Osoba slávna, On sám ma zamení.<br/>Pane, Pane, si pre mňa človekom!<br/>Si mojou novou Osobou, plnou identitou.<br/>Pane, Pane, podrob vo mne všetko,<br/>a stále, stále si buduj v mojom srdci domov.<br/>',NULL,130868,1);
INSERT INTO stanza VALUES('SK1177','2','Kristus sa stal Duchom, aby hovoril vo mne,<br/>rozprávajúci Duch, hovorí neprestajne.<br/>Jeho slovo vodou je, čo zvnútra obmyje,<br/>starobu zmýva, Jeho udeľuje.<br/>Pane, Pane, všetko čo chceš povedz.<br/>Rozprávaním Si prítomný, hovor neprestajne.<br/>Pane, Pane, hovor, obmývaj ma,<br/>metabolicky premieňaj, v srdci mojom zostaň.<br/>',NULL,130869,2);
INSERT INTO stanza VALUES('SK1177','3','Kristus – Ženích sa vráti pre nás, sme nevestou,<br/>On vyjde z nás, cirkvou budeme oslávenou.<br/>Jeho Osoba slávna je, v nás rozpína sa,<br/>to je naša Osoba – aká sláva!<br/>Pane, Pane, v domácom zákone<br/>zaplavuj Svojou slávou, nás nasycuj úplne.<br/>Vystúp, vystúp, nech sláva prepukne<br/>zo slávnej cirkvi čoskoro, ó, vráť sa v sláve späť.<br/>',NULL,130870,3);
INSERT INTO stanza VALUES('SK1178','1','Krista – skutočnosť vidíme my,<br/>avšak iba vidieť nestačí.<br/>On musí v našom prežívaní<br/>byť pre nás všetkým.<br/>V modlitbe Ho vychutnávame<br/>milosť na stretnutiach zdieľame.<br/>Ale ako Ho prežívame<br/>v dennom živote?<br/>',NULL,130871,1);
INSERT INTO stanza VALUES('SK1178','chorus','Len Jeho svetlom vidíme my,<br/>aký pre nás bude Pán plný,<br/>ak sa len k Nemu obrátime<br/>vždy, so všetkým, čo máme<br/>a v každom smere, stále.<br/>Pre skutočnosť buďme príznační,<br/>nech Kristus nie je zamieňaný,<br/>ak bude nami prežívaný,<br/>bude pre nás všetkým.<br/>',NULL,130872,2);
INSERT INTO stanza VALUES('SK1178','2','Život mnoho možností ti dá,<br/>veď Otec to tak naplánoval,<br/>nech sa vždy a všade stále dá<br/>Krista získavať.<br/>Aby Kristus mohol žiariť z nás,<br/>Seba ako obsah dáva nám.<br/>nech cestu vo všetkých nás On má,<br/>cestu mať musí.<br/>',NULL,130873,3);
INSERT INTO stanza VALUES('SK1178','chorus','Vo svojom tele prežívame,<br/>že smrť Krista v sebe znášame,<br/>tak Jeho život vychádza z nás,<br/>náš vonkajšok sa láme<br/>a nový človek vládne,<br/>preto v nás, hlinených nádobách,<br/>je táto skutočnosť nádherná<br/>skrze svetlo evanjelia<br/>vždy vyžarovaná.<br/>Nie doktríny, teológia,<br/>ale len skutočnosť nádherná,<br/>Kristus, naše všetko, vládne v nás,<br/>On je všetkým pre nás!<br/>',NULL,130874,4);
INSERT INTO stanza VALUES('SK1179','1','Starý človek bol ukrižovaný<br/>s jeho porušenosťou aj všetkým.<br/>hadia prirodzenosť pochovaná,<br/>ten fakt, že je celkom ukončená,<br/>držím pevne.<br/>',NULL,130875,1);
INSERT INTO stanza VALUES('SK1179','2','V mojom duchu je teraz osoba<br/>narodená ako malé dieťa.<br/>z čistého mlieka Slova bude rásť,<br/>bude víťazom vo mne a získa<br/>moje srdce.<br/>',NULL,130876,2);
INSERT INTO stanza VALUES('SK1179','3','Kristus musí vlastniť moje srdce,<br/>vo všetkom Pán prvé miesto mať chce.<br/>Starý majiteľ zomrel, no máta.<br/>Ó, vstúp! Pane! Moje srdce víta<br/>iba Teba!<br/>',NULL,130877,3);
INSERT INTO stanza VALUES('SK1179','4','V zmiešanom duchu sme jedno, Pane,<br/>božské s ľudským je takto v jednote.<br/>musíš ale mať všetok priestor v nás,<br/>aby Tvoja osoba byť mohla<br/>vyjadrená.<br/>',NULL,130878,4);
INSERT INTO stanza VALUES('SK1179','5','Dnes dávam Ti, Pane, svoje srdce,<br/>aby si v ňom mal Svoj domov plne,<br/>aby si sa plne usadil v ňom,<br/>dielo obnovy v človeku novom<br/>tak zavŕšil.<br/>',NULL,130879,5);
INSERT INTO stanza VALUES('SK1180','1','Stará osoba je zrušená,<br/>s Pánom na kríži ukončená,<br/>už nesmie byť používaná,<br/>mŕtva je pre mňa.<br/>Nová osoba v duchu žije,<br/>ako studňa vyviera vo mne,<br/>tečie, nech sa srdce napije<br/>životom hojným.<br/>',NULL,130880,1);
INSERT INTO stanza VALUES('SK1180','chorus','Pán v duchu je mojou osobou,<br/>v mojom srdci si činí domov,<br/>môj vnútorný človek má domov<br/>kde usadiť sa môže,<br/>čo Svojím nazvať môže.<br/>V duchu je skutočnosť úplná,<br/>v duchu vyjadrujem to, čo mám,<br/>celé srdce Pánom preteká,<br/>Jeho Osobou.<br/>',NULL,130881,2);
INSERT INTO stanza VALUES('SK1180','2','Formuje ma Jeho osoba,<br/>s ďalšími byť súčasťou Tela,<br/>nech sa sám už neponevieram,<br/>som so svätými.<br/>Viac našou Osobou byť musí,<br/>stále sme veľmi prirodzení,<br/>nech sme dôkladne ukončení,<br/>nech je Pán všetkým.<br/>',NULL,130882,3);
INSERT INTO stanza VALUES('SK1180','chorus','Iba Kristus nám ostať musí,<br/>od sebeckých cieľov upustím,<br/>až kým v cirkvi Krista uvidím,<br/>nového človeka a naplnený Boží plán,<br/>zmiešanie sa s ľuďmi úplné,<br/>aby mal miesto na bývanie,<br/>v kráľovstve milosť a vládnutie<br/>nad celou zemou.<br/>Nie iba On sám, jedinečný,<br/>ale spolu s cirkvou, súhrnný.<br/>„Berieme Ťa, nech si nám všetkým,<br/>až budeme zrelí.“<br/>',NULL,130883,4);
INSERT INTO stanza VALUES('SK1184','1','Úvodom knihy Zjavenia<br/>nám Boh dal víziu Syna,<br/>Toho, čo bol, je a príde,<br/>k Nemu teraz všetci poďme.<br/>',NULL,130884,1);
INSERT INTO stanza VALUES('SK1184','2','V duchu Jeho hlas čujeme,<br/>obráťme sa, uvidíme<br/>sedem zlatých svietnikov hneď,<br/>Syna človeka uprostred.<br/>',NULL,130885,2);
INSERT INTO stanza VALUES('SK1184','3','Plášť veľkňaza na Sebe má,<br/>o všetky cirkvi sa stará,<br/>knôty strihá, olej dáva,<br/>oči sťa plameň ohňa má.<br/>',NULL,130886,3);
INSERT INTO stanza VALUES('SK1184','4','Pás zo zlata má cez prsia,<br/>dielo skončil, dnes vylieva<br/>na cirkvi Svoje bohatstvo,<br/>Seba samého láskavo.<br/>',NULL,130887,4);
INSERT INTO stanza VALUES('SK1184','5','Biela Jeho hlava, vlasy,<br/>dlhoveký, avšak mladý.<br/>Ako slnce Mu tvár žiari,<br/>nás všetkých páli, ožiari.<br/>',NULL,130888,5);
INSERT INTO stanza VALUES('SK1184','6','Sťa mŕtvi pred Ním padneme,<br/>ó, keď živého zbadáme.<br/>Potom nám dá potešenie<br/>zomrel som a, hľa, dnes žijem.<br/>',NULL,130889,6);
INSERT INTO stanza VALUES('SK1184','7','Nech Ho cirkvi milujú viac,<br/>aby im dal bohatstiev viac.<br/>To, čo máš rád, vždy odkladaj,<br/>iba Ježiša získavaj.<br/>',NULL,130890,7);
INSERT INTO stanza VALUES('SK1191','1','Z ducha môjho vnútri prameň prúdi živý –<br/>to prúdi Boh Trojjediný.<br/>Boh – Otec je zdrojom, Kristus – Syn riečiskom,<br/>Duchom je život vkladaný.<br/>',NULL,130891,1);
INSERT INTO stanza VALUES('SK1191','chorus','Pane, chránim si ten prúd živý,<br/>duševný život tak odložím.<br/>Pane, prehlbuj ten prúd živý,<br/>Tvoj život bude odmenou mi.<br/>',NULL,130892,2);
INSERT INTO stanza VALUES('SK1191','2','Na sviežich pastvinách ma Ježiš ukladá,<br/>tichými vodami vedie.<br/>viac nechcem bojovať či sa márne snažiť,<br/>ja mám požehnanie v prúde.<br/>',NULL,130893,3);
INSERT INTO stanza VALUES('SK1191','3','Ježiš ma povolal do svätyne svätých,<br/>žiť do Jeho prítomnosti.<br/>Aleluja, ja som počul Jeho slovo:<br/>„Prebývaj – ratolesťou si.“<br/>',NULL,130894,4);
INSERT INTO stanza VALUES('SK1193','1','Život, to je Boh – Otec v Kristovi,<br/>ktorý ako Duch prúdi do nás.<br/>Aká úžasná je táto Osoba!<br/>Je životom daným od Boha.<br/>',NULL,130895,1);
INSERT INTO stanza VALUES('SK1193','2','Keď sme sa Pánovi otvorili,<br/>znovuzrodenie sme prežili.<br/>Znovuzrodením vstúpil život iný,<br/>napĺňa nás až do plnosti.<br/>',NULL,130896,2);
INSERT INTO stanza VALUES('SK1193','3','Živý Duch v našom vnútri prebýva,<br/>vytryskuje von z nášho ducha.<br/>Do srdca plynie a všetko premieňa<br/>tým životom, ktorým je On Sám.<br/>',NULL,130897,3);
INSERT INTO stanza VALUES('SK1193','4','My s Ním musíme spolupracovať,<br/>našu myseľ k Synu obracať.<br/>Zanechávať to, čo je mimo Neho,<br/>až kým myseľ nebude na Ňom.<br/>',NULL,130898,4);
INSERT INTO stanza VALUES('SK1193','5','Pane, v duchu Ťa obsahujeme.<br/>Tvoj cieľ s Tebou dosahujeme.<br/>Myšlienky staré, ak ich opúšťame,<br/>život a pokoj nachádzame.<br/>',NULL,130899,5);
INSERT INTO stanza VALUES('SK1193','6','Myšlienky Ti chceme podriaďovať<br/>skrze vychutnávanie Slova.<br/>Mysľou budeme prebývať len v Slove,<br/>myseľ tak posvätená bude.<br/>',NULL,130900,6);
INSERT INTO stanza VALUES('SK1193','7','Tento život v praxi používajme,<br/>myseľ k Synovi upriamujme.<br/>Chvála Jemu, že z Neho žiť môžeme,<br/>v Ňom zostávajú naše mysle.<br/>',NULL,130901,7);
INSERT INTO stanza VALUES('SK1195','1','Život je tajomný, je to Boh sám,<br/>Svoj zámer sústredí na človeka.<br/>Stvoril ho, ’by jedol strom života,<br/>aby mal Boh človeka života.<br/>',NULL,130902,1);
INSERT INTO stanza VALUES('SK1195','2','Bol však pokúšaný a zvedený,<br/>zjedol poznanie, prijal zdroj iný.<br/>Poznanie ho učinilo padlým,<br/>celou svojou silou vládlo nad ním.<br/>',NULL,130903,2);
INSERT INTO stanza VALUES('SK1195','3','Poznanie sa v človeku rozvilo,<br/>dnes je na zemi ľudskou kultúrou.<br/>Človek stvorený pre Boha zlyhal,<br/>naplnil sa Satanovou smrťou.<br/>',NULL,130904,3);
INSERT INTO stanza VALUES('SK1195','4','V osobe Syna potom prišiel Boh,<br/>je to Ježiš Kristus, žil na zemi.<br/>Je živý vzor žitia skrze život,<br/>aby sme Božiu plnosť dosiahli.<br/>',NULL,130905,4);
INSERT INTO stanza VALUES('SK1195','5','Bohočlovek išiel na kríž, umrel,<br/>skončilo poznanie, človek starý.<br/>Ukrižoval všetko negatívne,<br/>podmanil smrť, začal život nový!<br/>',NULL,130906,5);
INSERT INTO stanza VALUES('SK1195','6','Bol vzkriesený, stal sa Duchom živým,<br/>Jeho život nám je darovaný.<br/>Ak uveríme, keď Ho vzývame,<br/>vstúpi a začne v nás žiť Duch živý.<br/>',NULL,130907,6);
INSERT INTO stanza VALUES('SK1195','7','Týmto je dnes sám Boh Trojjediný,<br/>Duchom živým, s nami premiešaný.<br/>Je spojený v jedno s duchom naším,<br/>takto sme jedným duchom navždy s Ním.<br/>',NULL,130908,7);
INSERT INTO stanza VALUES('SK1195','8','Týmto Duchom konáme, kráčame,<br/>v Ňom zmýšľame, v Ňom všetko vidíme.<br/>Ó, čo za fakt, že v tomto Duchu sme!<br/>Tento Duch nám Božiu plnosť nesie!<br/>',NULL,130909,8);
INSERT INTO stanza VALUES('SK1195','9','Obracajme k Nemu svoju myseľ,<br/>každý deň, hodinu, nech je na Ňom,<br/>aby nás Duch zvnútra zachraňoval<br/>Svojím životom, kraľujme vždy v Ňom.<br/>',NULL,130910,9);
INSERT INTO stanza VALUES('SK1195','10','Týmto Duchom sme oslobodení<br/>od zákona hriechu, vedie k smrti,<br/>naše telá budú oživené,<br/>budeme úplne posvätení.<br/>',NULL,130911,10);
INSERT INTO stanza VALUES('SK1195','11','Duch premení prirodzenosť našu,<br/>nebude tu ja, len človek nový,<br/>až budeme ako Ježiš Kristus,<br/>tak bude plán Boží dokončený.<br/>',NULL,130912,11);
INSERT INTO stanza VALUES('SK1195','12','Život je Boh, život je Kristus Pán,<br/>život je Duch a život cestou je,<br/>až po premenu a vykúpenie,<br/>čakáme, tešíme sa na ten deň.<br/>',NULL,130913,12);
INSERT INTO stanza VALUES('SK1198','1','Ó, náš Boh mocne preteká,<br/>On plynie naprieč vekmi.<br/>Aby vtiekol do človeka,<br/>učinil mnohé kroky.<br/>Boh je iba jeden,<br/>večný tok je jeden.<br/>Aby v nás plynul dnes,<br/>procesmi musel prejsť.<br/>Teraz prúdi vnútri nás!<br/>',NULL,130914,1);
INSERT INTO stanza VALUES('SK1198','2','Na počiatku zrieme Boha,<br/>On je rieka tečúca,<br/>rieka nám prináša Boha,<br/>rastie v nej strom života.<br/>Na konci to isté,<br/>tá rieka ostane,<br/>Boh v Baránkovi je,<br/>Strom života rastie<br/>a Boh naveky plynie.<br/>',NULL,130915,2);
INSERT INTO stanza VALUES('SK1198','3','Sám Boh vplynul do človeka,<br/>Ježiš Kristus sa volal.<br/>Za všetkých ľudí život dal,<br/>uvoľnil život Boha.<br/>Satan chcel zastaviť,<br/>tok Boha prerušiť,<br/>Pán ukrižovaný<br/>mal bok otvorený,<br/>no vytiekla krv a voda!<br/>',NULL,130916,3);
INSERT INTO stanza VALUES('SK1198','4','Krv a voda vytekali<br/>v potokoch čistej spásy.<br/>Krv nás od hriechov očistí,<br/>voda nás znovu zrodí.<br/>A teraz Duch plynie,<br/>Boha ľuďom nesie.<br/>Nepriateľ spôsobil,<br/>že sa tok uvoľnil<br/>a Boh naďalej plynie!<br/>',NULL,130917,4);
INSERT INTO stanza VALUES('SK1199','1','Zámer Boha v tomto vesmíre je s ľudstvom spojený,<br/>takže Pán sa stal Duchom, aby bol s ľudstvom zmiešaný.<br/>Všetci smieme účasť mať na Jeho ekonómii,<br/>zmiešanie je cestou.<br/>',NULL,130918,1);
INSERT INTO stanza VALUES('SK1199','chorus','Zmiešavanie, aleluja,<br/>zmiešavanie, aleluja,<br/>zmiešavanie, aleluja,<br/>cestou je zmiešanie!<br/>',NULL,130919,2);
INSERT INTO stanza VALUES('SK1199','2','V centre našej bytosti, až za mysľou, citmi, vôľou,<br/>stvorené je isté miesto na to, aby Pán bol v ňom,<br/>’by našu bytosť naplnil úplne Svojím tokom.<br/>zmiešanie je cestou.<br/>',NULL,130920,3);
INSERT INTO stanza VALUES('SK1199','3','V Pánovej obnove sme našli cestu, sme tak radi,<br/>môžeme prežívať Otca, Syna, Ducha a žiť Ním –<br/>dostať sa do zmiešaného ducha a zostávať s ním.<br/>to sa dá zmiešaním.<br/>',NULL,130921,4);
INSERT INTO stanza VALUES('SK1199','4','Uprostred siedmich zlatých svietnikov je človeka Syn,<br/>v očiach plameň, nohy – mosadz, Božia obnova je s Ním.<br/>Zámer Boha Pán uskutočňuje – celok súhrnný,<br/>iba zmiešavaním.<br/>',NULL,130922,5);
INSERT INTO stanza VALUES('SK1199','5','Vo všetkom, čo sme, robíme, myslíme a povieme,<br/>získavať hlbšie zmiešanie s Pánom potrebujeme.<br/>Cestou zmiešavania, Pane, sa Ti celkom dávame.<br/>cestou je zmiešanie.<br/>',NULL,130923,6);
INSERT INTO stanza VALUES('SK1199','6','Z ovocia denného žitia je Nový Jeruzalem,<br/>je zmiešavania zavŕšením a božsko–ľudský je.<br/>Čo za radosť, spolu sa na ňom podieľať môžeme.<br/>cestou je zmiešanie.<br/>',NULL,130924,7);
INSERT INTO stanza VALUES('SK1205','1','Pokračuj stále ku cieľu,<br/>ktorým je Kristus sám,<br/>aby si získal odmenu,<br/>ktorou je Kristus sám.<br/>',NULL,130925,1);
INSERT INTO stanza VALUES('SK1205','chorus','Ideme! My ďalej!<br/>Ideme! Aleluja, za odmenou ideme!<br/>My ďalej! Získať Krista chceme!<br/>',NULL,130926,2);
INSERT INTO stanza VALUES('SK1205','2','Všetko počítaj za stratu,<br/>len Krista získavaj,<br/>aby si získal odmenu,<br/>len Krista získavaj.<br/>',NULL,130927,3);
INSERT INTO stanza VALUES('SK1205','3','Snaž sa len Pána poznávať<br/>a silu vzkriesenia,<br/>tak budeme odmenu mať,<br/>hoc cez utrpenia.<br/>',NULL,130928,4);
INSERT INTO stanza VALUES('SK1205','4','Tak teda stále jedno rob,<br/>minulosť zabúdaj,<br/>pokračuj stále za Kristom,<br/>len takto uvažuj.<br/>',NULL,130929,5);
INSERT INTO stanza VALUES('SK1206','1','Závod máme bežať my – Aleluja.<br/>Spôsob, ako závod ten vyhrať,<br/>pre všetkých, čo začali – Aleluja,<br/>Boh vraví: „Na Neho pozerať!“<br/>',NULL,130930,1);
INSERT INTO stanza VALUES('SK1206','chorus','Odhliadaj! Odhliadaj!<br/>Na Ježiša pozeraj!<br/>Od všetkého odhliadaj k Ježišovi!<br/>K Nemu od všetkého odhliadaj!<br/>',NULL,130931,2);
INSERT INTO stanza VALUES('SK1206','2','Od všetkého odhliadaj – Aleluja,<br/>odhliadaj od sporov aj hluku.<br/>Hľaď na to, v čom je pokoj – Aleluja,<br/>od všetkého odhliadaj k Nemu.<br/>',NULL,130932,3);
INSERT INTO stanza VALUES('SK1206','3','Od premenlivej duše – Aleluja,<br/>od upadnutého „ja“ k Nemu.<br/>Pozeraj sa do cieľa – Aleluja,<br/>od všetkého odhliadaj k Nemu.<br/>',NULL,130933,4);
INSERT INTO stanza VALUES('SK1206','4','Zabudni na minulosť – Aleluja,<br/>odhliadaj od dobra aj hriechu.<br/>Živého sa pevne drž – Aleluja,<br/>od všetkého odhliadaj k Nemu.<br/>',NULL,130934,5);
INSERT INTO stanza VALUES('SK1206','5','Hľaď do tváre len Jemu– Aleluja,<br/>to, čo On začal, tiež dokončí.<br/>Závod bežať je milosť – Aleluja,<br/>kto na Neho hľadí zvíťazí.<br/>',NULL,130935,6);
INSERT INTO stanza VALUES('SK1211','1','Daroval, daroval Pán vieru drahú,<br/>prísľuby preveľké aj silu božskú.<br/>Vierou sme prijali, všetko dostali,<br/>týmto môžeme vzrastať a byť zrelí.<br/>',NULL,130936,1);
INSERT INTO stanza VALUES('SK1211','2','V každom z nás je viera vzácna, rovnaká.<br/>Predrahá viera nás v svojej moci má.<br/>Čokoľvek si myslíš, viera ťa drží,<br/>deň čo deň, ba aj naveky vydrží.<br/>',NULL,130937,2);
INSERT INTO stanza VALUES('SK1211','3','Moc božská, čo je v nás, je zdrojom veľkým.<br/>Moc božská, čo je v nás, mocne pôsobí.<br/>Rozkvitne všetko pre život vnútorný,<br/>zbožnosť navonok Ježiša vyjadrí.<br/>',NULL,130938,3);
INSERT INTO stanza VALUES('SK1211','4','Prísľuby preveľké dal povolaným,<br/>vzácnymi prísľubmi sme obdarení.<br/>Účasťou na Božej prirodzenosti<br/>unikáme svetskej žiadostivosti.<br/>',NULL,130939,4);
INSERT INTO stanza VALUES('SK1211','5','Kristus je vnútri, v nás, je v duchu silou.<br/>Navonok je Slovom, Božím prísľubom.<br/>V duchu aj cez slovo sa s Ním spájame,<br/>modlitbou, čítaním slova rastieme.<br/>',NULL,130940,5);
INSERT INTO stanza VALUES('SK1211','6','Viera, moc, prísľuby – zaopatrenie,<br/>uplatňuj to všetko vždy usilovne.<br/>Ak tomu budeme náš čas venovať,<br/>z viery ovocie lásky budeme mať.<br/>',NULL,130941,6);
INSERT INTO stanza VALUES('SK1211','7','Rastom zo semena pochádza mnohé,<br/>len rastom v Pánovi plodní budeme.<br/>Musíme hľadieť na to, čo začal Pán,<br/>nebyť slepými k tomu, čo vykonal.<br/>',NULL,130942,7);
INSERT INTO stanza VALUES('SK1211','8','Sústavným úsilím vždy porastieme,<br/>upevníme si svoje povolanie.<br/>Prehojný vstup do kráľovstva majú tí,<br/>čo so semenom spolupracovali.<br/>',NULL,130943,8);
INSERT INTO stanza VALUES('SK1211','9','Pre tento rast, Pane, sa vydávame,<br/>vierou, prísľubmi a silou žiť chceme.<br/>Nič iné základom naším nebude,<br/>Tvojou milosťou spolupracujeme.<br/>',NULL,130944,9);
INSERT INTO stanza VALUES('SK1219','1','Nádherná zmena sa mi deje v živote,<br/>keď vravím na Slovo: Amen.<br/>Stále viac a viac Krista sa do mňa vleje,<br/>keď vravím na Slovo: Amen.<br/>',NULL,130945,1);
INSERT INTO stanza VALUES('SK1219','chorus','Keď vravím na Slovo: Amen,<br/>keď vravím na Slovo: Amen.<br/>Pán vezme srdce mi a celé premení,<br/>keď vravím na Slovo: Amen.<br/>',NULL,130946,2);
INSERT INTO stanza VALUES('SK1219','2','To na čo ja nemám, Boh vo mne vykoná,<br/>keď vravím na Slovo: Amen.<br/>Zmena je skutočná, aj bratom je zjavná,<br/>keď vravím na Slovo: Amen.<br/>',NULL,130947,3);
INSERT INTO stanza VALUES('SK1219','3','Prestal som z blúdením, stranou viac nechodím,<br/>keď vravím na Slovo: Amen.<br/>K čomu som sklony mal, už mi viac nechutí,<br/>keď vravím na Slovo: Amen.<br/>',NULL,130948,4);
INSERT INTO stanza VALUES('SK1219','4','Dnes vidím tajomstvo ako v Pána veriť,<br/>vravieť Jeho Slovu: Amen.<br/>Skutočný, vzácnejší je nad všetky veci,<br/>keď vravím na Slovo: Amen<br/>',NULL,130949,5);
INSERT INTO stanza VALUES('SK1219','5','Moja láska k bratom sa viacej rozhojní,<br/>keď vravím na Slovo: Amen.<br/>Spojení sme viacej, ako nikdy predtým,<br/>keď vravím na Slovo: Amen.<br/>',NULL,130950,6);
INSERT INTO stanza VALUES('SK1219','6','Moja nádej rastie na Tvoj návrat skorý,<br/>keď vravím na Slovo: Amen.<br/>Môjho Pána stretnúť som viac pripravený,<br/>keď vravím na Slovo: Amen.<br/>',NULL,130951,7);
INSERT INTO stanza VALUES('SK1219','chorus','Pán Ježiš, na Slovo: Amen.<br/>Pán Ježiš, na Slovo: Amen.<br/>Ty prichádzaš znovu - srdcom Amen tomu!<br/>Pán Ježiš, na Slovo: Amen.<br/>',NULL,130952,8);
INSERT INTO stanza VALUES('SK1221','1','Ježiš Pastier nádherný je,<br/>z košiara vyviedol nás<br/>na pastvinu bohatú, kde<br/>Sebou samým pasie nás.<br/>',NULL,130953,1);
INSERT INTO stanza VALUES('SK1221','chorus','Slávny je život<br/>cirkevný, prebohatý!<br/>Tu sme jedno a tu Pánom<br/>je život nariadený.<br/>',NULL,130954,2);
INSERT INTO stanza VALUES('SK1221','2','Vyčerpaných a hladných, On<br/>v rozdeleniach našiel nás.<br/>priviedol do dobrej zeme,<br/>priviedol k duchu On nás.<br/>',NULL,130955,3);
INSERT INTO stanza VALUES('SK1221','3','Sám Ježiš je našou pastvou,<br/>On sám je pokrmom nám.<br/>pri vzájomných stretnutiach On<br/>je vždy nasýtením nám.<br/>',NULL,130956,4);
INSERT INTO stanza VALUES('SK1221','4','Tu sme na hore vysokej<br/>čerstvou rosou umytí,<br/>náš smäd nám prameň uháša<br/>živou vodou, vždy nový.<br/>',NULL,130957,5);
INSERT INTO stanza VALUES('SK1221','5','Tu vychutnávame Pána,<br/>na strach tu dôvodu niet.<br/>všetky ovce v bezpečí sú,<br/>Pánom ochraňované.<br/>',NULL,130958,6);
INSERT INTO stanza VALUES('SK1222','1','Spievaj hlasné chvály Pánovi, všetkých<br/>Pán dnes prebýva v Jeruzaleme.<br/>Jeho diela hlásaj veľké i malé,<br/>má v nebi trón, zároveň s ľuďmi je.<br/>Spása prichádza len zo Sionu,<br/>Pán priviedol nás späť zo zajatia.<br/>Máme radosť a sme potešení!<br/>Máme radosť a sme potešení!<br/>',NULL,130959,1);
INSERT INTO stanza VALUES('SK1222','2','So svätými On býva v Meste Svätom,<br/>Ó, je skvelé, Pane, Tvoje meno!<br/>Na chválach svätých má Hospodin Svoj trón,<br/>záľubou Jeho je iba Sion.<br/>Miestne cirkvi sú dnes Jeho pohyb,<br/>Pán je podiel náš, my sme spokojní,<br/>Ó, čo za veľké dedičstvo to je!<br/>Ó, čo za veľké dedičstvo to je!<br/>',NULL,130960,2);
INSERT INTO stanza VALUES('SK1222','3','Kto v Jeho svätom stánku bývať bude?<br/>Kto smie prebývať na Jeho vrchu?<br/>Ten, kto Ho hľadá, kto sa očisťuje,<br/>tí, čo Jeho tvár denne hľadajú.<br/>Hľadajme všetci iba Jeho tvár.<br/>otvorme sa, nech môže vstúpiť Kráľ.<br/>Vstúpi a bude žiť a kraľovať!<br/>Vstúpi a bude žiť a kraľovať!<br/>',NULL,130961,3);
INSERT INTO stanza VALUES('SK1222','4','Pozri! So svätými je stánok Boží,<br/>hlásame Emanuel – Boh s nami.<br/>Poďme všetci ku Kristovi a cirkvi,<br/>kde Boh a človek sú jedno navždy!<br/>Pozdvihnite hlavy všetky mestá,<br/>otvorte brány, nech tak vstúpi Kráľ.<br/>Volajte chvála! Nech kraľuje Pán!<br/>Volajte chvála! Nech kraľuje Pán!<br/>',NULL,130962,4);
INSERT INTO stanza VALUES('SK1223','1','Obíďme, ó, obíďme Sion,<br/>obstúpme, obstúpme ho.<br/>Obíďme, ó, obíďme Sion,<br/>zrátajme veže jeho.<br/>',NULL,130963,1);
INSERT INTO stanza VALUES('SK1223','2','Upriamme srdcia k jeho hradbám,<br/>srdcia k nemu smerujme.<br/>Upriamme srdcia k jeho hradbám,<br/>paláce si všímajme.<br/>',NULL,130964,2);
INSERT INTO stanza VALUES('SK1223','3','Vypína sa nádherne Sion,<br/>celú zem rozradostní!<br/>Vypína sa nádherne Sion,<br/>mesto veľkej hodnoty!<br/>',NULL,130965,3);
INSERT INTO stanza VALUES('SK1223','4','Ó, rieka tečie na Sione,<br/>obšírna a hlboká.<br/>Ó, jej potoky potešujú,<br/>veselia mesto Boha!<br/>',NULL,130966,4);
INSERT INTO stanza VALUES('SK1223','5','Čaká Ťa chvála na Sione,<br/>Sion je chvály plný.<br/>Čaká Ťa chvála na Sione,<br/>je Tebou naplnený.<br/>',NULL,130967,5);
INSERT INTO stanza VALUES('SK1223','6','Veľký je náš Pán na Sione<br/>a chvály veľkej hoden,<br/>veľký je náš Pán v meste, ktoré<br/>vyvýšené je nad zem.<br/>',NULL,130968,6);
INSERT INTO stanza VALUES('SK1223','7','Žehnajme Pána zo Sionu,<br/>ó, chválou prekypujme.<br/>Žehnajme Pána zo Sionu,<br/>býva v Jeruzaleme.<br/>',NULL,130969,7);
INSERT INTO stanza VALUES('SK1223','8','Nech nás žehná Pán zo Sionu,<br/>nech nás navždy požehná!<br/>Nech nás žehná Pán zo Sionu,<br/>životom, čo navždy dá!<br/>',NULL,130970,8);
INSERT INTO stanza VALUES('SK1223','9','Aké je dobré, aké milé<br/>prebývať spolu s bratmi!<br/>Aké je dobré, aké milé,<br/>ak sú bratia jednotní!<br/>',NULL,130971,9);
INSERT INTO stanza VALUES('SK1223','10','Povedzme všetkým pokoleniam,<br/>aj tým, čo prichádzajú,<br/>povedzme všetkým pokoleniam,<br/>Duch s Nevestou „príď“ volajú!<br/>',NULL,130972,10);
INSERT INTO stanza VALUES('SK1224','1','Všetci sme sa obrátili<br/>od zákona ku Kristovi,<br/>tú slávu sme rozpoznali<br/>a máme len Krista.<br/>',NULL,130973,1);
INSERT INTO stanza VALUES('SK1224','chorus','Dnes máme len Krista!<br/>A dbáme na Krista!<br/>Tú slávu sme rozpoznali,<br/>ceníme si Krista!<br/>',NULL,130974,2);
INSERT INTO stanza VALUES('SK1224','2','Prebývame v Božom dome,<br/>v ňom chválou prekypujeme.<br/>Ó, Aleluja! Chvála znie!<br/>Boží dom krásny je!<br/>',NULL,130975,3);
INSERT INTO stanza VALUES('SK1224','chorus','Boží dom krásny je!<br/>Boží dom krásny je!<br/>Ó, Aleluja! Chvála znie!<br/>Boží dom krásny je!<br/>',NULL,130976,4);
INSERT INTO stanza VALUES('SK1224','3','Rozšírený dom je mestom.<br/>to je radosťou národov,<br/>tým miestom, kde kraľuje Boh,<br/>je pahorok Sion.<br/>',NULL,130977,5);
INSERT INTO stanza VALUES('SK1224','chorus','Ó, pahorok Sion!<br/>Ó, pahorok Sion!<br/>Tým miestom, kde kraľuje Boh,<br/>je pahorok Sion.<br/>',NULL,130978,6);
INSERT INTO stanza VALUES('SK1224','4','Zo Sionu preberie zem,<br/>všetkému vládnuť Pán bude.<br/>Cenným sa národom stane,<br/>tak spievaj víťazne.<br/>',NULL,130979,7);
INSERT INTO stanza VALUES('SK1224','chorus','Tak spievaj víťazne!<br/>Tak spievaj víťazne!<br/>Cenným sa národom stane,<br/>tak spievaj víťazne.<br/>',NULL,130980,8);
INSERT INTO stanza VALUES('SK1224','5','Kristus – dom – mesto – zem celá.<br/>Boh takto naplní Svoj plán.<br/>Buďme kvôli tomu bratia,<br/>s Ním úplne jedno.<br/>',NULL,130981,9);
INSERT INTO stanza VALUES('SK1224','chorus','S Ním úplne jedno!<br/>S Ním úplne jedno!<br/>Buďme kvôli tomu bratia,<br/>s Ním úplne jedno.<br/>',NULL,130982,10);
INSERT INTO stanza VALUES('SK1225','1','Pane znať Ťa ako Telo<br/>zúfalo potrebujem,<br/>uvidieť Ťa v Tvojich údoch,<br/>za to sa modliť budem.<br/>Nestačí mi poznať Hlavu,<br/>len ja sám, jednotlivo,<br/>lež vidieť Ťa vteleného,<br/>to, že si Kristus-Telo.<br/>',NULL,130983,1);
INSERT INTO stanza VALUES('SK1225','2','Roky Ťa svätí hľadajú.<br/>túžia po realite.<br/>Hľadia k nebu aj do vnútra,<br/>všetci chcú Ťa uvidieť.<br/>Odhaľ, že Kristus v nebesiach<br/>je Telom prejavený<br/>a Kristus čo v nás prebýva<br/>je Telom vyjadrený.<br/>',NULL,130984,2);
INSERT INTO stanza VALUES('SK1225','3','Moje zmýšľanie o Tebe,<br/>často je nadnesené,<br/>iba pre seba Ťa chcem mať,<br/>skutočnosti ale niet.<br/>Veľmi Ťa potrebujem nájsť<br/>v Tvojich údoch tu dole.<br/>Boh večný tu s nami býva,<br/>zjavený je dnes v tele.<br/>',NULL,130985,3);
INSERT INTO stanza VALUES('SK1225','4','Ó, nezávislosť obmedzuj,<br/>do Svojho Tela ma veď,<br/>nehľadať len svetlo z nebies,<br/>učiť sa vnímať cirkev.<br/>Nech sme kameňmi pre stavbu,<br/>nie nepotrebnou hlinou,<br/>získaj v nás to, po čom túžiš,<br/>nádobou nech sme Tvojou.<br/>',NULL,130986,4);
INSERT INTO stanza VALUES('SK1226','1','Cirkev Kristova je slávna a my v nej môžeme byť,<br/>sme šťastní, že Pán jedno učinil z nás.<br/>Jedno Telo vo vesmíre, jeho súčasťou sme my.<br/>Aleluja, Pán jedno učinil z nás!<br/>',NULL,130987,1);
INSERT INTO stanza VALUES('SK1226','chorus','Aleluja, že sme Telo,<br/>my sme údmi tohto Tela,<br/>my sme úplne pre Telo.<br/>Aleluja, Pán jedno učinil z nás!<br/>',NULL,130988,2);
INSERT INTO stanza VALUES('SK1226','2','Nie sme iba jednotlivci, ale súhrnné Telo,<br/>Boh ho potrebuje pre vyjadrenie.<br/>Nie iba nezávislé cirkvi, no súhrnné Telo.<br/>Aleluja, spolu v ňom byť môžeme!<br/>',NULL,130989,3);
INSERT INTO stanza VALUES('SK1226','chorus','Aleluja, že sme Telo,<br/>vystraší Satana Telo,<br/>zvíťazíme ako Telo.<br/>Aleluja, spolu v ňom byť môžeme!<br/>',NULL,130990,4);
INSERT INTO stanza VALUES('SK1226','3','Božskej prirodzenosti je sedem svietnikov zlatých,<br/>Telo nič prirodzené nedovolí.<br/>Ak zdieľame Božiu povahu, tak svietnik zažiari.<br/>Aleluja, svietnik tu teraz žiari!<br/>',NULL,130991,5);
INSERT INTO stanza VALUES('SK1226','chorus','Aleluja, že sme Telo,<br/>všetky sviecne tvoria Telo.<br/>Teraz žiari Jeho Telo.<br/>Aleluja, svietnik tu teraz žiari!<br/>',NULL,130992,6);
INSERT INTO stanza VALUES('SK1226','4','Ako môžeme byť jedno, byť božskými a žiariť?<br/>Aleluja, jesť Ježiša cestou je!<br/>On je strom života, manna a hostina na veky.<br/>Aleluja, môžeme Ho denne jesť!<br/>',NULL,130993,7);
INSERT INTO stanza VALUES('SK1226','chorus','Sme jedno jedením Pána!<br/>Sme božskí jedením Pána!<br/>Žiarime jedením Pána!<br/>Aleluja, jesť Ježiša cestou je!<br/>',NULL,130994,8);
INSERT INTO stanza VALUES('SK1229','1','Cirkev je túžbou Pána,<br/>Jeho zaľúbením,<br/>Jeho činy, slová sú<br/>vždy s ohľadom na ňu.<br/>Cirkev miluje náš Pán<br/>a nič to nezmení.<br/>myslel na cirkev už pred<br/>sveta založením.<br/>',NULL,130995,1);
INSERT INTO stanza VALUES('SK1229','2','Prv, ako bol svet stvoril,<br/>premýšľal o nej Pán,<br/>zvažoval jej obrysy,<br/>je pre Neho krásna.<br/>Potom Pán začal tvoriť,<br/>no v Sebe niečo skryl,<br/>On po Neveste slávnej<br/>v srdci Svojom túžil.<br/>',NULL,130996,2);
INSERT INTO stanza VALUES('SK1229','3','Pán ustanovil vôľu,<br/>náprotivok získať,<br/>pevný je Jeho zámer,<br/>platný naveky je.<br/>Hoc hriech človeka zvábil<br/>a úplne skazil,<br/>no Pán na Svoju túžbu<br/>nikdy nezabudol.<br/>',NULL,130997,3);
INSERT INTO stanza VALUES('SK1229','4','Keď si vyhľadal Cirkev<br/>v múdrosti a láske,<br/>milosrdenstvo z Pána<br/>sa vylialo hojné.<br/>On získal si ju láskou,<br/>len Sám jej rozumie,<br/>za Cirkev život Pánov<br/>cennou obeťou je.<br/>',NULL,130998,4);
INSERT INTO stanza VALUES('SK1229','5','A teraz vo vzkriesení<br/>sa k Cirkvi blíži Pán<br/>a s nevýslovnou láskou<br/>v sláve zjavuje sa.<br/>Až Cirkev uzrie Pána,<br/>ju sláva zaplaví,<br/>Pán si Nevestu vezme<br/>a hore uchváti.<br/>',NULL,130999,5);
INSERT INTO stanza VALUES('SK1232','1','Mŕtvi sme boli svojím hriechom,<br/>v nás duch pôsobil neposlušný.<br/>ale Boh nás obživil Kristom,<br/>nás na nebesiach posadil spolu s Ním.<br/>',NULL,131000,1);
INSERT INTO stanza VALUES('SK1232','chorus','Náš Pán Ježiš nás zjednocuje,<br/>uvidíš, svätí sú v jednote.<br/>On láskou vzájomne zlučuje,<br/>v postavu plnosti Pána rastieme.<br/>',NULL,131001,2);
INSERT INTO stanza VALUES('SK1232','2','Spoločne môžeme pochopiť<br/>nekonečné rozmery Boha<br/>a tiež lásku Kristovu poznať,<br/>byť naplnení do plnosti Boha.<br/>',NULL,131002,3);
INSERT INTO stanza VALUES('SK1232','3','Známy zámer nášho Boha dnes,<br/>to tajomstvo je viditeľným.<br/>vidíme Krista a cirkev dnes<br/>a nepriateľ je nimi zahanbený.<br/>',NULL,131003,4);
INSERT INTO stanza VALUES('SK1232','4','Za to sa modlíme k Otcovi:<br/>„Zmocni vnútorného človeka,<br/>učiň si domov v srdciach našich,<br/>v láske založ a zakoreň pre Svoj plán.“<br/>',NULL,131004,5);
INSERT INTO stanza VALUES('SK1232','5','V Tele Kristovom umiestnení<br/>ako mnohé údy Kristove,<br/>pracujúc podľa svojej miery,<br/>rastom v láske Telo vybudujeme.<br/>',NULL,131005,6);
INSERT INTO stanza VALUES('SK1232','6','Teraz sme jeden nový človek,<br/>zámer Boha tak napĺňame,<br/>Otcovi nech sláva v cirkvi je<br/>a v Kristovi na veky vekov – Amen!<br/>',NULL,131006,7);
INSERT INTO stanza VALUES('SK1237','1','Nádherný cirkevný život zelenou záhradou je,<br/>tu prežívame Krista, ktorý rastie!<br/>Pre svätých, čo sú v jednote, je potešenia plný.<br/>je nový, svieži, dostupný a drahý.<br/>',NULL,131007,1);
INSERT INTO stanza VALUES('SK1237','chorus','V záhrade tejto som prešťastný,<br/>veď tu rastiem v Jeho milosti.<br/>Nie je nič lepšieho, než jesť zo živého stromu<br/>a dostávať do seba vodu živú.<br/>',NULL,131008,2);
INSERT INTO stanza VALUES('SK1237','2','Nie je to škola, továreň či kaplnka v nebesiach,<br/>no záhrada, kde môže rozsievať Pán.<br/>Aby sme Mu boli sadom, všetkých nás sem umiestnil,<br/>tu nás môže pestovať, môžeme rásť.<br/>',NULL,131009,3);
INSERT INTO stanza VALUES('SK1237','3','Vnútri cirkevného života je tento strom plodný,<br/>života plný a veľmi dostupný.<br/>Tak buď jednoduchý, začni Ho jesť, odlož názory!<br/>Jedz Ježiša každú chvíľu, je sladký!<br/>',NULL,131010,4);
INSERT INTO stanza VALUES('SK1237','4','Tiež je tam aj voda, prúdiaci Boh v Kristovi do nás,<br/>ukončuje boje, uháša smäd náš.<br/>Aleluja, vo Svojej záhrade Pán prúdi do nás,<br/>je naším zaopatrením pre rast náš.<br/>',NULL,131011,5);
INSERT INTO stanza VALUES('SK1237','5','Nie si uspokojený a vďačný, že Pán ťa sem dal,<br/>kde prúdi Jeho bohatstvo, radosť k nám?<br/>Tak buď šťastný a radostný, Ním sa sýť v duchu hojne,<br/>nech záhrada prináša plody hojné.<br/>',NULL,131012,6);
INSERT INTO stanza VALUES('SK1238','1','Nikdy sa mi nesnilo<br/>o nádhernejšom mieste,<br/>kde sa slzy strácajú<br/>v speve radostnej piesne.<br/>Ten, kto len zriedka spieval,<br/>teraz počuť jeho hlas,<br/>so svätými spieva si,<br/>echo chvál sa ozve z nás.<br/>',NULL,131013,1);
INSERT INTO stanza VALUES('SK1238','2','Rovnako ako pred tým,<br/>svet stále ide ďalej.<br/>Po živote siahame,<br/>vždy by sme chceli viacej,<br/>ja by som bol tiež taký,<br/>avšak On si ma našiel.<br/>Som vďačný, taký vďačný,<br/>že som v rodine Božej.<br/>',NULL,131014,2);
INSERT INTO stanza VALUES('SK1238','3','Aké pôvabné poznať<br/>osobnú, pravú, sladkú<br/>radosť z tejto milosti,<br/>spoločne zakúšanú.<br/>Ježiš dá život hojný,<br/>mojou skutočnosťou je,<br/>Pane chvála, je pravdou,<br/>že som v rodine Božej.<br/>',NULL,131015,3);
INSERT INTO stanza VALUES('SK1238','4','Ku koncu tohto veku,<br/>pred kráľovstva príchodom,<br/>Pane, získaj si ľudí<br/>pre Svoj príbytok, domov.<br/>Pre mňa si vydal všetko,<br/>aj ja všetko odložím,<br/>všetko dávam pre cirkev,<br/>aby si bol spokojný.<br/>',NULL,131016,4);
INSERT INTO stanza VALUES('SK1240','1','Chcem mať hlbšie skúsenosti kríža,<br/>do hĺbky chcem ísť.<br/>Smrť a život sú vždy ruka v ruke,<br/>prehĺb tok živý.<br/>Hlbšie, modlíme sa,<br/>každý deň pracuj v nás.<br/>Hlbšie choď a hlbšie,<br/>obnov nás dokonale.<br/>',NULL,131017,1);
INSERT INTO stanza VALUES('SK1240','2','Vyššie, vyššie v živote Ježiša,<br/>lebo nízko sme.<br/>Tvoj život nás vedie stále vyššie,<br/>stúpame vyššie.<br/>Vyššie, modlíme sa,<br/>Pane, premieňaj nás,<br/>ó, v prúde obohať,<br/>chceme len Tvoj život znať.<br/>',NULL,131018,2);
INSERT INTO stanza VALUES('SK1240','3','Rastie, rastie, dennodenne rastie,<br/>Ježiš rastie v nás.<br/>Do celého nášho žitia vchádza,<br/>rastom to koná.<br/>Rasti, modlíme sa,<br/>Pane zväčšuj sa v nás.<br/>Poznanie nestačí,<br/>Tvoj život v nás rásť musí.<br/>',NULL,131019,3);
INSERT INTO stanza VALUES('SK1240','4','Žitie, žitie, Pán je naše žitie,<br/>On je praktický:<br/>V maličkostiach, aj vo veciach veľkých<br/>je zapojený.<br/>Ži stále len Krista,<br/>každý deň ži Krista.<br/>Volaj Jeho meno,<br/>daj Mu všetko pre všetko.<br/>',NULL,131020,4);
INSERT INTO stanza VALUES('SK1240','5','Ježiš, Ježiš je našou Osobou,<br/>ktorá žije v nás.<br/>Je našimi záľubami, činmi,<br/>sláva preveľká!<br/>Pane, si Osobou,<br/>v srdciach, si čiň domov.<br/>Sťa život deň za dňom,<br/>buď Osobou vo všetkom.<br/>',NULL,131021,5);
INSERT INTO stanza VALUES('SK1242','1','Pán, semeno života, sa do srdca zasial nám,<br/>rastie do plnosti, aby z nás náprotivok mal.<br/>Semeno vodu žiada, nie formy, či pravidlá,<br/>keď ho budeme zavlažovať, ono bude rásť!<br/>',NULL,131022,1);
INSERT INTO stanza VALUES('SK1242','chorus','Tým semenom je Ježiš! Ó, On žije vo mne!<br/>Jeho rastom to semeno v nás zrelosť dosiahne.<br/>',NULL,131023,2);
INSERT INTO stanza VALUES('SK1242','2','Zo semena onedlho pšenica vypučí,<br/>život sa dostane von, ale tým to nekončí.<br/>Pšenica sama nie je semena vyjadrenie,<br/>zrná sa musia premiešať, tvoriť niečo nové.<br/>',NULL,131024,3);
INSERT INTO stanza VALUES('SK1242','chorus','Tým semenom je Ježiš! Ježiš pšenicou je!<br/>Zrná sa musia premiešať, tvoriť niečo nové.<br/>',NULL,131025,4);
INSERT INTO stanza VALUES('SK1242','3','Žiadne jednotlivé zrno nie je nezávislé,<br/>musia sa rozdrviť a byť na prášok zomleté.<br/>Zo zrniečok sa stane múka a z tej bude chlieb,<br/>všetci svätí sa zmiešajú, ako On budeme.<br/>',NULL,131026,5);
INSERT INTO stanza VALUES('SK1242','chorus','Musíme byť zomletí ako mnohé zrná,<br/>až kým budeme sformovaní do Jeho Tela.<br/>',NULL,131027,6);
INSERT INTO stanza VALUES('SK1242','4','Semeno je zasadené, pšenica dozrela<br/>na Božej farme, výsledkom je múka príjemná.<br/>Avšak život rastie pre vybudovanie cirkvi,<br/>aby mali Boh aj človek dom, do cieľa prišli.<br/>',NULL,131028,7);
INSERT INTO stanza VALUES('SK1242','chorus','Farma je tu pre stavbu Božieho príbytku,<br/>kde bývať v jednote Boh a človek môžu spolu.<br/>',NULL,131029,8);
INSERT INTO stanza VALUES('SK1242','5','Boh buduje zo zlata, striebra, kameňov drahých,<br/>od múky cez premenu, tlak, teplo, aj súžením.<br/>Múka sa nesmie uspokojiť s tým, že múkou je,<br/>musí sa vzácnym kameňom stať vďaka premene.<br/>',NULL,131030,9);
INSERT INTO stanza VALUES('SK1242','chorus','Keď stráda múka, vzácne kamene formuje,<br/>tie sú vbudované do Božej stavby nádhernej.<br/>',NULL,131031,10);
INSERT INTO stanza VALUES('SK1242','6','Z plného rastu, premeny, sa perla objaví,<br/>jednoduchý, všeobsiahly klenot veľmi cenný.<br/>Začala smrťou, životom bola sformovaná,<br/>Cirkev, Jeho nevesta, ovocie Jeho diela.<br/>',NULL,131032,11);
INSERT INTO stanza VALUES('SK1242','chorus','Perla je to, čo chce Pán, nevesta nádherná.<br/>Čistá a vzácna, jediná, čo sa Mu vyrovná.<br/>',NULL,131033,12);
INSERT INTO stanza VALUES('SK1242','7','Zasadením na Božej farme život začne rásť,<br/>zo semena je pšenica, na múku melie sa.<br/>Múka sa podriadiť musí, podstúpiť premenu<br/>v zlato, striebro, drahé kamene pre stavbu Božiu.<br/>',NULL,131034,13);
INSERT INTO stanza VALUES('SK1242','chorus','Farma je tu pre stavbu zo vzácnych kameňov.<br/>Z nich je cenná perla, ktorá je Jeho nevestou.<br/>',NULL,131035,14);
INSERT INTO stanza VALUES('SK1242','8','Chceme byť duchom chudobní a v srdci byť čistí,<br/>aby semeno rástlo, dobrou pôdou chceme byť,<br/>aby si získal vzácnu perlu, ďalej chceme ísť,<br/>Pane, len nevestou môžeš byť uspokojený.<br/>',NULL,131036,15);
INSERT INTO stanza VALUES('SK1242','chorus','Nech sme v duchu chudobní, nech sme v srdci čistí,<br/>’by sme Ti náprotivkom Tvojím rastom v nás boli.<br/>',NULL,131037,16);
INSERT INTO stanza VALUES('SK1247','1','Aby naše srdcia boli<br/>do ducha otočené,<br/>aby sme víťazmi boli.<br/>Ježiša nasledujme.<br/>',NULL,131038,1);
INSERT INTO stanza VALUES('SK1247','chorus','Nasledujme Pána v duchu<br/>a tak víťazmi buďme.<br/>nasledujme každú chvíľu,<br/>Ježiš, Ty nám pomôžeš.<br/>',NULL,131039,2);
INSERT INTO stanza VALUES('SK1247','2','’By sme boli zbudovaní,<br/>spojení tak vzájomne,<br/>tiež navzájom utváraní.<br/>tak bratov nasledujme.<br/>',NULL,131040,3);
INSERT INTO stanza VALUES('SK1247','chorus','Nasledujme bratov stále,<br/>nebuďme nezávislí.<br/>nasledujme kvôli stavbe,<br/>fungujme v harmónii.<br/>',NULL,131041,4);
INSERT INTO stanza VALUES('SK1247','3','Ak sme pre obnovu Pána,<br/>aby Pána bola zem,<br/>’by sme kráľovstvo priniesli.<br/>tak cirkvi nasledujme.<br/>',NULL,131042,5);
INSERT INTO stanza VALUES('SK1247','chorus','Miestne cirkvi nasledujme,<br/>tak zbadáme kráľovstvo,<br/>cirkevný prúd nasledujme<br/>pre obnovu Pánovu.<br/>',NULL,131043,6);
INSERT INTO stanza VALUES('SK1247','4','Všetci lepšie nasledujme,<br/>Slovo jedzme s radosťou.<br/>podnieti nás nasledovať<br/>cirkvi, Pána aj bratov.<br/>',NULL,131044,7);
INSERT INTO stanza VALUES('SK1247','chorus','Nasledujme Pána, bratov,<br/>aj cirkvi nasledujme.<br/>naším amen Jeho Slovu<br/>cieľ spolu dosiahneme.<br/>',NULL,131045,8);
INSERT INTO stanza VALUES('SK1248','1','Kráľ Dávid prisahal:<br/>„Do domu si nevkročím,<br/>na lôžko nevstúpim,<br/>spánku si nedoprajem,<br/>až kým nenájdem to miesto<br/>pre Teba, Bože, môj.“<br/>Náš mocný Boh chce mať domov,<br/>kam Jeho ľud patrí.<br/>',NULL,131046,1);
INSERT INTO stanza VALUES('SK1248','2','My sme boli slepí,<br/>len pre seba sme žili,<br/>Boží dom je v troskách,<br/>Ty sám, Pane, obráť nás.<br/>My na horu vystúpime,<br/>po drevo, dom stavať.<br/>Nepovieme: „Snáď iný deň.“<br/>Teraz je čas stavať!<br/>',NULL,131047,2);
INSERT INTO stanza VALUES('SK1248','3','Ó, Pane, v dobe zlej<br/>si nás pre stavbu získaj.<br/>Ako v dňoch Dávida,<br/>zvyšok je pripravený.<br/>prísť, pracovať v Tvojom dome,<br/>aké požehnanie!<br/>Tvoje prianie dnes naším je –<br/>stavať prichádzame.<br/>',NULL,131048,3);
INSERT INTO stanza VALUES('SK1248','4','Vlož do povolaných<br/>nepretržité snahy<br/>dať všetko do stavby,<br/>toto sú dni prípravy.<br/>Brány pekla nepremôžu<br/>Cirkev zbudovanú!<br/>Je krátky čas a málo nás.<br/>Ó, Pane, buduj v nás!<br/>',NULL,131049,4);
INSERT INTO stanza VALUES('SK1254','1','Je čas, aby sme vrúcne stavali Pánov chrám,<br/>aby každá cirkev mohla byť obnovená.<br/>Nebudujme vlastné, pozrime na dom Boží,<br/>pre Božiu stavbu nech nám srdce horí!<br/>',NULL,131050,1);
INSERT INTO stanza VALUES('SK1254','chorus','Buďme silní, budujme dom Boží!<br/>Pán zástupov je s nami, slávou Svoj dom naplní!<br/>Buďme silní a jednomyseľní,<br/>’by chrám bol obdivovaný všetkými národmi.<br/>',NULL,131051,2);
INSERT INTO stanza VALUES('SK1254','2','Teraz uvažujte nad svojimi cestami:<br/>Namáhate sa, prečo sa vám nič nedarí?<br/>Vystúpte do hôr, na stavbu drevo dovezte,<br/>postavte mi dom, oslávený budem.<br/>',NULL,131052,3);
INSERT INTO stanza VALUES('SK1254','3','Kňazi, kresťanov zostatok, buďme poslušní,<br/>veď Pán je stále s nami, nech kto, čo chce, vraví.<br/>Poďme stavať s duchom horiacim, povzbudeným,<br/>nech sa nikomu do práce nelení.<br/>',NULL,131053,4);
INSERT INTO stanza VALUES('SK1254','4','Pán zástupov vraví: „Svoj dom slávou naplním.“<br/>A túžba národov sa zjaví ľuďom všetkým.<br/>Dom bude slávnejší ako čokoľvek predtým,<br/>v tej sláve budeme mať podiel večný.<br/>',NULL,131054,5);
INSERT INTO stanza VALUES('SK1255','1','Sme za Pánovu obnovu<br/>cirkvi miestnej.<br/>sme za Pánovu obnovu<br/>mesta aj zeme celej.<br/>Stojac na pôde jednoty,<br/>v Pánovi jedno,<br/>chrám tu takto budujeme,<br/>chrám Pána nášho.<br/>',NULL,131055,1);
INSERT INTO stanza VALUES('SK1255','chorus','Sme pre obnovu!<br/>Sme pre obnovu!<br/>My sme pre obnovu Pánovu!<br/>Sme pre obnovu!<br/>Sme pre obnovu!<br/>My sme pre obnovu Pána!<br/>',NULL,131056,2);
INSERT INTO stanza VALUES('SK1255','2','Sme za Pánovu obnovu,<br/>je srdciam drahá.<br/>Ak svojho ducha cvičíme,<br/>vízia, taká jasná.<br/>Padol už Babylon veľký,<br/>Satan zvrhnutý.<br/>a na miestnej pôde v cirkvách<br/>sme budovaní.<br/>',NULL,131057,3);
INSERT INTO stanza VALUES('SK1265','1','Miestne cirkvi na zemi<br/>sú Telom Kristovým.<br/>Cez cirkvi cestu má,<br/>sú svedectvom Pánovým.<br/>Sú zlatými svietnikmi,<br/>svietia v rôznych mestách,<br/>sú víťaznou armádou,<br/>Pánova nevesta.<br/>',NULL,131058,1);
INSERT INTO stanza VALUES('SK1265','chorus','Cirkvi máš, cirkvi máš,<br/>na tejto zemi dnes.<br/>Pre zámer Svoj vzbuď nám srdcia,<br/>buduj nás, buduj nás, náš Pane.<br/>',NULL,131059,2);
INSERT INTO stanza VALUES('SK1265','2','Cirkvi potrebujeme,<br/>aj väčšie aj menšie!<br/>Ich podiel potrebný je<br/>pre Krista získanie.<br/>Pán Ježiš zväčšuj cirkvi,<br/>za ich potreby sme,<br/>naše srdcia rozširuj<br/>spolu sa modlíme.<br/>',NULL,131060,3);
INSERT INTO stanza VALUES('SK1265','3','Ó, Sedem očí Pána,<br/>hľadí na zem celú.<br/>Horia, hľadajú, pália,<br/>kto čo chce skúmajú.<br/>Pán chce mať mnoho cirkví,<br/>v súlad zbudovaných,<br/>toto zlaté svedectvo<br/>Ježiša vyjadrí.<br/>',NULL,131061,4);
INSERT INTO stanza VALUES('SK1265','4','Onedlho sa vráti<br/>Kráľ, čo vždy víťazí!<br/>Pre cirkvi si prichádza,<br/>v nich je uctievaný.<br/>Vezme si prvotiny,<br/>hľa, blíži sa žatva,<br/>vezme nás k Svojmu trónu,<br/>budeme kraľovať.<br/>',NULL,131062,5);
INSERT INTO stanza VALUES('SK1269','1','V krajine Chaldejskej, plnej zlyhaní,<br/>Abrám videl Boha, bol povolaný.<br/>„Odíď z tohto kraja, rodiny svojej,<br/>odíď od príbuzných, do zeme inej.“<br/>',NULL,131063,1);
INSERT INTO stanza VALUES('SK1269','chorus','Kolektívneho človeka náš Boh povolal,<br/>’by Ho vyjadroval, splnil Jeho plán.<br/>',NULL,131064,2);
INSERT INTO stanza VALUES('SK1269','2','Pán sa doňho vlieval, život ho zmenil,<br/>stal sa Abrahámom – je otcom verných.<br/>Do zeme sa dostal Pánom zjaveným,<br/>musel mať Izáka, splniť plán Boží.<br/>',NULL,131065,3);
INSERT INTO stanza VALUES('SK1269','3','Izák zdedil všetko od svojho otca,<br/>všetko požehnanie, plnosť synovstva.<br/>Aj keď všetko prijal, bol neúplný,<br/>chýbala mu zrelosť, byť premenený.<br/>',NULL,131066,4);
INSERT INTO stanza VALUES('SK1269','4','Nasledoval Jákob, stal sa kniežaťom,<br/>zápasil aj s Bohom, bol Izraelom.<br/>Duch na ňom pracoval, dozrel, kraľoval<br/>nad zemou, Jozefom vládu získal.<br/>',NULL,131067,5);
INSERT INTO stanza VALUES('SK1269','5','Jákob, Izák, Abrahám, to nám zobrazí<br/>ako máme kráčať, keď sme ľud Boží.<br/>Údy Jeho tela, človek súhrnný,<br/>naplnia Boží plán Ním povolaní.<br/>',NULL,131068,6);
INSERT INTO stanza VALUES('SK1273','1','Kristom sme povolaní,<br/>dnes znovu pozývaní.<br/>Vnútri nám amen zuní!<br/>Zvíťazme!<br/>Cirkev nízko upadla,<br/>máme mnoho poznania,<br/>avšak málo života –<br/>zvíťazme!<br/>',NULL,131069,1);
INSERT INTO stanza VALUES('SK1273','chorus','Zvíťazme! Zvíťazme!<br/>Zvíťazme nad degradáciou cirkvi!<br/>Nech je bokom námaha,<br/>učenia, čo nás delia.<br/>Jedzme Pána Ježiša –<br/>zvíťazme!<br/>',NULL,131070,2);
INSERT INTO stanza VALUES('SK1273','2','Jesť je údel človeka<br/>a obnova Pánova,<br/>to ničí nepriateľa –<br/>zvíťazme!<br/>Poďme jesť strom života,<br/>svoje boje zanechaj,<br/>zvíťaz jedením Krista –<br/>zvíťazme!<br/>',NULL,131071,3);
INSERT INTO stanza VALUES('SK1273','3','Náuky ťa nezmenia,<br/>nedosiahnu cieľ Boha,<br/>iba jedenie Krista –<br/>zvíťazme!<br/>Zvíťazíme jedením,<br/>sami, aj na stretnutí,<br/>jedzme Ho, On nás hostí –<br/>zvíťazme!<br/>',NULL,131072,4);
INSERT INTO stanza VALUES('SK1273','4','Jedenie syna zrodí,<br/>Pán sa vráti jedením.<br/>Jedz uprostred ťažkostí –<br/>zvíťazme!<br/>Máme byť synom – mužom,<br/>tak cirkvou vytúženou,<br/>Jeho nevestou drahou –<br/>zvíťazme!<br/>',NULL,131073,5);
INSERT INTO stanza VALUES('SK1290','1','Ó, Pane, Ty máš zámer priviesť mnohých synov<br/>do Svojej plnej slávy, do kráľovstva Svojho.<br/>Ó, chválime Ťa, Pane, tou slávou si Ty v nás,<br/>aby si mohol žiariť, rozšír sa v každom z nás.<br/>',NULL,131074,1);
INSERT INTO stanza VALUES('SK1290','2','Pane, Tvoj život máme, to semienko rastie,<br/>semä vnútornej slávy, čo s Tebou zdieľame!<br/>Rastie kým kvety slávy úplne rozkvitnú,<br/>vychutnáme Tvoj nárast a slávu prehojnú.<br/>',NULL,131075,2);
INSERT INTO stanza VALUES('SK1290','3','Sláva Ti! Vodca spásy! Nebeský priekopník!<br/>Naše chvály počúvaš, sme jeden bojovník.<br/>Vodcu nasledujeme cez zápasy, boje,<br/>je verný a je slávny, vždy nás podporuje.<br/>',NULL,131076,3);
INSERT INTO stanza VALUES('SK1290','4','Ty si sa prebojoval, do slávy si vošiel,<br/>víťazne zápasíme v stopách, čo si prešiel.<br/>Pane, od slávy k sláve budeme bojovať,<br/>ó, nech sa sláva z vnútra začne prejavovať.<br/>',NULL,131077,4);
INSERT INTO stanza VALUES('SK1290','5','Napokon boj utíchne, pokrik boja skončí,<br/>my sa zjavíme v sláve, kráľovstvo sa zväčší.<br/>Ó, ten deň bude slávny, zbadáme Tvoju tvár,<br/>Pane, požehnaný deň keď Tvoju slávu mám!<br/>',NULL,131078,5);
INSERT INTO stanza VALUES('SK1293','1','Som človekom – tohoto vesmíru významom,<br/>som človekom – tohoto vesmíru významom.<br/>Tak stvorený, tak významný,<br/>som centrom a tohoto vesmíru významom.<br/>',NULL,131079,1);
INSERT INTO stanza VALUES('SK1293','2','Kristus vo mne – ľudského života význam je,<br/>Kristus vo mne – ľudského života význam je.<br/>Žije vo mne, všetkým mi je,<br/>významom, skutočnosťou ľudského života je.<br/>',NULL,131080,2);
INSERT INTO stanza VALUES('SK1293','3','Cirkev – Kristus – Jeho vyjadrenie na zemi,<br/>cirkev – Kristus – Jeho vyjadrenie na zemi.<br/>Cirkev plní ten plán Boží,<br/>aby tento človek súhrnný vládol na zemi.<br/>',NULL,131081,3);
INSERT INTO stanza VALUES('SK1293','4','Miestna cirkev – je rodina skutočná, nová,<br/>miestna cirkev – je rodina skutočná, nová.<br/>Dnes môžeme žiť skutočne,<br/>ak jeme a pijeme Krista, to nás buduje.<br/>',NULL,131082,4);
INSERT INTO stanza VALUES('SK1293','5','Musíme ísť a toto rozpovedať svetu,<br/>musíme ísť a toto rozpovedať svetu.<br/>Povolaní učiť ľudí,<br/>tak rozširujme správu dobrú po celej zemi.<br/>',NULL,131083,5);
INSERT INTO stanza VALUES('SK1294','1','Hovorme, kým kráľovstvo Božie<br/>nepríde sem.<br/>Hovorme, kým kráľovstvo Božie<br/>nepríde sem.<br/>Pokoj nestráž!<br/>Slovo len káž!<br/>Hovorme, kým kráľovstvo Božie<br/>nepríde sem.<br/>',NULL,131084,1);
INSERT INTO stanza VALUES('SK1294','2','Ak uvoľníš slovo, nebude<br/>bez úžitku.<br/>Ak uvoľníš slovo, nebude<br/>bez úžitku.<br/>Saď semená!<br/>To je treba!<br/>Ak uvoľníš slovo, nebude<br/>bez úžitku.<br/>',NULL,131085,2);
INSERT INTO stanza VALUES('SK1294','3','Dnes je čas hlásať evanjelium<br/>na zemi.<br/>Nám nevadí, ak sú ľudia<br/>dnes zachmúrení.<br/>Nie leniví!<br/>Buďme živí!<br/>Nám nevadí, ak sú ľudia<br/>dnes zachmúrení.<br/>',NULL,131086,3);
INSERT INTO stanza VALUES('SK1294','4','Hovorme, Pán tak bude svedčiť<br/>v srdciach ľudí.<br/>Hovorme, Pán tak bude svedčiť<br/>v srdciach ľudí.<br/>Byť víťazní!<br/>Môžu všetci!<br/>Naším hovorením Pán hovorí<br/>do ľudí.<br/>',NULL,131087,4);
INSERT INTO stanza VALUES('SK1294','5','A tak plné evanjelium<br/>my hlásame.<br/>Polia už sú biele, na žatvu<br/>pripravené.<br/>Hľadajme len!<br/>Krista, cirkev!<br/>Žnime a plné evanjelium<br/>hlásajme.<br/>',NULL,131088,5);
INSERT INTO stanza VALUES('SK1299','1','Boh Stvoriteľ má Svoj zámer<br/>pre náš život na zemi.<br/>Stvorení sme v Jeho obraz,<br/>aby vládu vyjadril.<br/>Človek diablovi podľahol,<br/>Boh pred ním Svoj cieľ ukryl,<br/>Boh aj tak získa kráľovstvo,<br/>Jeho Syn to naplní.<br/>',NULL,131089,1);
INSERT INTO stanza VALUES('SK1299','2','Kristus bude mať kráľovstvo,<br/>aj keď to Satan nechce.<br/>Pán získa niečo skutočné<br/>tým, že v srdciach rásť bude.<br/>Náboženstvo iba učí:<br/>„Musíš čakať, až zomrieš.“<br/>Pán však kráľovstvo buduje<br/>na zemi pred nami dnes.<br/>',NULL,131090,2);
INSERT INTO stanza VALUES('SK1299','3','Jeho Syn, Ježiš, Spasiteľ,<br/>prišiel v ľudskej podobe.<br/>Teraz ako dych života<br/>ten Duch do nás vstupuje.<br/>Ako semä v našom duchu<br/>púšťa korene, rastie,<br/>On sa v našom vnútri šíri,<br/>život tak poznávame.<br/>',NULL,131091,3);
INSERT INTO stanza VALUES('SK1299','4','Čas je krátky, bratia, čujte,<br/>Pán túži po Neveste.<br/>Jeho návrat urýchlime<br/>naším rastom v živote.<br/>Nezápasme, nebojujme,<br/>obráťme sa ku Nemu.<br/>Semeno začína kvitnúť,<br/>plne rastie do Neho.<br/>',NULL,131092,4);
INSERT INTO stanza VALUES('SK1299','5','Pán Ježiš získa kráľovstvo<br/>cestou rastu – normálne.<br/>Nie okamžitou premenou,<br/>ale rastom každý deň.<br/>Semeno má všetko v sebe,<br/>všetko, čo je potrebné.<br/>áno, zámer nášho Boha<br/>ukrytý je v semene.<br/>',NULL,131093,5);
INSERT INTO stanza VALUES('SK1301','1','Vstúpil do nás Ježiš, je kráľovstvom,<br/>vládne a žiari, slávou v nás je On.<br/>Kristus ako semeno je Kráľom,<br/>do nášho ducha zasial kráľovstvo.<br/>',NULL,131094,1);
INSERT INTO stanza VALUES('SK1301','chorus','Ó, nech rastie. Ó, nech rastie,<br/>nech život kráľovstva známe.<br/>Ježiš je kráľovstvo v nás zasiate,<br/>Ježiš je kráľovstvom, aké slávne.<br/>',NULL,131095,2);
INSERT INTO stanza VALUES('SK1301','2','Pre príchod kráľovstva sa kajajme.<br/>našu myseľ zmeňme, zanechajme,<br/>všetky pocity, myšlienky, plány,<br/>svet aj sebectvo nech sú za nami.<br/>',NULL,131096,3);
INSERT INTO stanza VALUES('SK1301','3','Náboženstvo to opäť minulo,<br/>názormi ľudí sa obmedzilo.<br/>pasívne na kráľovstvo čakajú,<br/>iba zmenu obdobia vidieť chcú.<br/>',NULL,131097,4);
INSERT INTO stanza VALUES('SK1301','4','No kráľovstvo je do nás zasiate,<br/>je ním sám náš Pán Ježiš, nič menej.<br/>je to osoba Krista v nás všetkých,<br/>semeno v nás začína volaním.<br/>',NULL,131098,5);
INSERT INTO stanza VALUES('SK1303','1','Kráľovstvo Božie blízko je.<br/>A tak vstalo panien desať,<br/>vyšli von, Ženícha stretnúť,<br/>múdrych však bolo iba päť.<br/>Múdre mali oleja dosť,<br/>hlúpe však prázdne ostali.<br/>múdre využívali čas,<br/>tie druhé šancu stratili.<br/>',NULL,131099,1);
INSERT INTO stanza VALUES('SK1303','2','Tvoj odkaz je jasný, Pane:<br/>vziať si prichádzaš rozumných,<br/>tých, čo dnes kupujú olej<br/>a bojujú s prekážkami.<br/>Tí, ktorí premenení sú,<br/>tí, čo sú plní oleja,<br/>život duše nemilujú –<br/>v kráľovstve budú kraľovať.<br/>',NULL,131100,2);
INSERT INTO stanza VALUES('SK1303','3','Ak meno Pána vzývame,<br/>tým lampy podstrihávame.<br/>Ak svojho ducha cvičíme,<br/>tým starobu spaľujeme.<br/>Avšak hlbšou potrebou je,<br/>že skutočnosť v nás musí rásť,<br/>kým v srdciach nebude mať dom,<br/>kým z nás olej nebude tiecť.<br/>',NULL,131101,3);
INSERT INTO stanza VALUES('SK1303','4','Tento vek je veľmi temný,<br/>blízko posledná hodina.<br/>Pán kedykoľvek môže prísť –<br/>Pane, vlož do nás svätý strach,<br/>’by sme vykupovali čas,<br/>prijímali Slovo modlitbou,<br/>Pane, Ty sám vyučuj nás,<br/>to nech je našou prípravou.<br/>',NULL,131102,4);
INSERT INTO stanza VALUES('SK1303','5','Je to veľké požehnanie,<br/>tými byť, čo Ťa vrátia späť,<br/>zjavia všetkým Tvoju cenu,<br/>vládnuť Ti umožnia všade!<br/>Požehnaním byť na svadbe,<br/>kde s Nevestou jedno budeš!<br/>Tak chceme byť panny múdre,<br/>tie, čo prebývajú v Tebe.<br/>',NULL,131103,5);
INSERT INTO stanza VALUES('SK1304','1','Pre nevestu príde Pán,<br/>na hostinu nás volá,<br/>či už rúcho čisté máš?<br/>Obleč sa!<br/>Do Krista oblečená,<br/>cez mnohé utrpenia<br/>spravodlivosť získala.<br/>Obleč sa!<br/>',NULL,131104,1);
INSERT INTO stanza VALUES('SK1304','chorus','Priprav sa! Priprav sa!<br/>Na Ježišovu svadbu sa pripravuj!<br/>Ak život duše zaprieš<br/>a Krista aplikuješ,<br/>tak pripravený budeš –<br/>priprav sa!<br/>',NULL,131105,2);
INSERT INTO stanza VALUES('SK1304','2','Panny, Kristus už ide<br/>po tie, čo olej majú,<br/>nie tie, čo ignorujú –<br/>včas kupuj!<br/>My olej kupujeme,<br/>svoje ja zapierame,<br/>nádoby napĺňame –<br/>včas kupuj!<br/>',NULL,131106,3);
INSERT INTO stanza VALUES('SK1304','3','Pre sluhov si príde Pán,<br/>On verným odmenu dá,<br/>lenivým On nič nedá –<br/>slúž načas!<br/>Využívaj talent svoj,<br/>s „ja“ problémy prekonaj,<br/>Kristom, zdrojom posluhuj –<br/>slúž načas!<br/>',NULL,131107,4);
INSERT INTO stanza VALUES('SK1304','4','Pán po úrodu ide,<br/>prvotiny si vezme,<br/>nezrelá však zostane –<br/>dozrievaj!<br/>Zrno nesmie vodu mať,<br/>svoju dušu zapieraj,<br/>tak budeme dozrievať –<br/>dozrievaj!<br/>',NULL,131108,5);
INSERT INTO stanza VALUES('SK1304','5','Pánom víťazi vzatí,<br/>čo všetko opustili,<br/>tí, čo Ho milovali –<br/>víťaz včas!<br/>Všetku mŕtvosť prekonaj,<br/>vždy jednotu s Pánom maj,<br/>k cieľu rýchlo utekaj –<br/>víťaz včas!<br/>',NULL,131109,6);
INSERT INTO stanza VALUES('SK1304','6','Kráľovstvo prichádza vziať,<br/>treba Ho nasledovať,<br/>Jeho vláde sa poddať –<br/>poddaj sa!<br/>Naše „ja“ musí ísť preč,<br/>lekciám sa tak učme,<br/>Jemu sa poddávajme –<br/>poddaj sa!<br/>',NULL,131110,7);
INSERT INTO stanza VALUES('SK1307','1','Ten deň sa blíži, keď sa Ježiš vráti,<br/>vykupujme čas, nič nezmeškajme.<br/>Ó, na Tvoj príchod nech pripravení sme,<br/>nech každú chvíľu vykupujeme.<br/>',NULL,131111,1);
INSERT INTO stanza VALUES('SK1307','chorus','Keď Ježiš príde, či sa stretneme s Ním?<br/>Či budeme od seba slobodní?<br/>Čoskoro príde, aby si vzal múdrych.<br/>Pane, nech nie sme von vyhodení.<br/>',NULL,131112,2);
INSERT INTO stanza VALUES('SK1307','2','Pane, pomáhaj nám využiť chvíle,<br/>naplniť nádoby pomazaním,<br/>na všetky skúšky nech povieme: „Amen.“<br/>Zväčšuj sa v nás, nech v láske sme hojní.<br/>',NULL,131113,3);
INSERT INTO stanza VALUES('SK1307','chorus','Prichádza Pán – ó, okamihy vzácne.<br/>Máme olej – len viac nakupujme.<br/>Na skúšky, súženia povieme: „Amen.“<br/>Utrpením kráľovstvo získame.<br/>',NULL,131114,4);
INSERT INTO stanza VALUES('SK1307','3','Od duševných potešení odvráť nás.<br/>Pane, hľadíme len na Tvoju tvár.<br/>Ó, nech bežíme, stretneme Ženícha.<br/>Nech každý z nás v tom behu vytrvá.<br/>',NULL,131115,5);
INSERT INTO stanza VALUES('SK1307','chorus','Keď Ježiš príde, či my budeme s Ním?<br/>Či budeme hľadieť na Jeho tvár?<br/>Nebuďme hlúpymi, ni lenivými,<br/>ó, nech každý v tom behu vytrvá.<br/>',NULL,131116,6);
INSERT INTO stanza VALUES('SK1307','4','Ako nevesta poďme Mu oproti,<br/>upravené lampy, oheň horí,<br/>nádoby máme Pánom naplnené,<br/>budeme Ním vždy uspokojení.<br/>',NULL,131117,7);
INSERT INTO stanza VALUES('SK1307','chorus','Sme spokojní, Kristus spolu s nevestou.<br/>Sme spokojní, navždy a naveky.<br/>Ó, čo za láska, radosť, odpočinok,<br/>byť nevestou, hodovať spolu s Ním!<br/>',NULL,131118,8);
INSERT INTO stanza VALUES('SK1308','1','Olej máme v lampách a horíme,<br/>my dnes máme v lampách olej,<br/>k duchu nás obracaj stále, Pane,<br/>k duchu nás otáčaj každý deň.<br/>',NULL,131119,1);
INSERT INTO stanza VALUES('SK1308','chorus','Pane! Amen! Aleluja!<br/>Pane, my horíme každý deň!<br/>Pane! Amen! Aleluja!<br/>Nás otáčaj každý deň!<br/>',NULL,131120,2);
INSERT INTO stanza VALUES('SK1308','2','No na príchod Tvoj zásobu, Pane,<br/>v nádobách potrebujeme,<br/>takže nádoby nám naplň, Pane,<br/>nech tak nikdy nevyhasneme.<br/>',NULL,131121,3);
INSERT INTO stanza VALUES('SK1308','chorus','Ó, napĺňaj nás, Ježišu!<br/>Stále viacej Seba nám dávaj!<br/>Ó, napĺňaj nás, Ježišu!<br/>Skutočnosťou napĺňaj!<br/>',NULL,131122,4);
INSERT INTO stanza VALUES('SK1308','3','A tak stále sme Ním zapálení,<br/>pokiaľ Pána nestretneme,<br/>potom vstúpime s Ním na hostinu,<br/>stále jasne horieť budeme.<br/>',NULL,131123,5);
INSERT INTO stanza VALUES('SK1308','chorus','Príď, Ježišu! Príď, Ježišu!<br/>Príď a horiacimi nás nájdi!<br/>Príď, Ježišu! Príď, Ježišu!<br/>V Neveste radosť nájdi!<br/>',NULL,131124,6);
INSERT INTO stanza VALUES('SK1311','1','Miestne cirkvi sa pripravujú na návrat Kristov –<br/>Čas sa približuje, Ženích už blízko je.<br/>Prichádza si vziať nevestu, túži iba po nej,<br/>aby sme boli s Ním, navždy vo večnosti.<br/>',NULL,131125,1);
INSERT INTO stanza VALUES('SK1311','chorus','Ľúbim Krista, skoro príde a naším Ženíchom bude,<br/>Čakáme Ho, spolu bdieme –<br/>Aj dnes môže prísť, aj dnes môže prísť!<br/>',NULL,131126,2);
INSERT INTO stanza VALUES('SK1311','2','Musíme Mu dať celé srdce, modly odvrhnúť!<br/>Kto okrem Neho je, čo ľúbi nás nežne?<br/>Pán Ježiš, len Ty nám stále zapaľuješ srdcia –<br/>Ó, nemeškaj Pane! Príď skoro, hoc aj dnes!<br/>',NULL,131127,3);
INSERT INTO stanza VALUES('SK1311','3','Slávnu nevestu pripravuje na deň svadobný,<br/>bude jasná, čistá, do ľanu odetá.<br/>Pane, vpracovávaj Svoju spravodlivosť do nás,<br/>na Tvojej hostine byť je požehnanie.<br/>',NULL,131128,4);
INSERT INTO stanza VALUES('SK1314','1','Pán, skoro sa zjavíš,<br/>Tvoj deň je už poblíž,<br/>milujeme návrat skorý!<br/>Nie je iného<br/>Pána milého,<br/>okrem Teba, Ženích drahý!<br/>',NULL,131129,1);
INSERT INTO stanza VALUES('SK1314','2','Blíži sa hodina,<br/>keď začujeme Ťa,<br/>s Tebou z neba zostúpime!<br/>Ó, zajasáme,<br/>keď Ťa stretneme,<br/>lásku veľkú pochopíme!<br/>',NULL,131130,2);
INSERT INTO stanza VALUES('SK1314','3','Rýchlo čas uteká,<br/>temer vidíme Ťa.<br/>Amen, Ježišu, rýchle príď!<br/>Chceme Ťa vidieť.<br/>S Tebou navždy byť,<br/>budeš naše srdce vlastniť!<br/>',NULL,131131,3);
INSERT INTO stanza VALUES('SK1314','4','Chvíľu už len krátku,<br/>zanedlho si tu,<br/>po nevestu vrátiš sa sám!<br/>Ó, aleluja!<br/>Už tešíme sa,<br/>uspokojenie budeš mať!<br/>',NULL,131132,4);
INSERT INTO stanza VALUES('SK1318','1','Bolo to toho dňa večer<br/>pri starej studni s vodou,<br/>Eliezer svoje ťavy zastavil.<br/>Pri tej studni totiž našiel<br/>Izákovi nevestu,<br/>a tak svoju cestu márne nerazil.<br/>',NULL,131133,1);
INSERT INTO stanza VALUES('SK1318','chorus','Počuj, Eliezer ťa volá!<br/>Tak sa priprav! Deň už pokročil!<br/>Zanedlho bude svadba,<br/>radovať sa začneme,<br/>v čase, keď sa karavána tiav zjaví.<br/>',NULL,131134,2);
INSERT INTO stanza VALUES('SK1318','2','Tak vzal pôvabnú Rebeku,<br/>nádherne ozdobenú,<br/>v diaľke čakajúcemu ženíchovi.<br/>Rebeka ho milovala<br/>a Izák miloval ju,<br/>a tak nadišiel šťastný deň svadobný.<br/>',NULL,131135,3);
INSERT INTO stanza VALUES('SK1318','3','Teraz Duch Svätý od Boha –<br/>Otca, čo je na nebi,<br/>zostúpil, ’by našiel vhodnú nevestu.<br/>Lebo náš Izák ďaleko<br/>lásky stan už pripravil,<br/>už chce mať pri Sebe svoju Rebeku.<br/>',NULL,131136,4);
INSERT INTO stanza VALUES('SK1318','4','Tak s radosťou opúšťame<br/>všetkých blízkych, celý svet,<br/>byť čistou Nevestou pre Pána chceme.<br/>My Ježiša uvidíme,<br/>naveky s Ním budeme –<br/>aká šťastná, šťastná svadba to bude.<br/>',NULL,131137,5);
INSERT INTO stanza VALUES('SK1325','1','Už od večnosti minulej<br/>Boh Svoj zámer má večný,<br/>do budúcnosti sa tiahne,<br/>okamih je medzi tým.<br/>Tento čas je tu pre proces,<br/>Boh, čo chce, uskutoční,<br/>na zemi len pútnikmi sme –<br/>pre večnosť sme určení.<br/>',NULL,131138,1);
INSERT INTO stanza VALUES('SK1325','2','Boh chce mať skupinu ľudí<br/>vybudovaných spolu,<br/>zmiešaných a prepojených,<br/>jeden nový človek sú.<br/>Boh chce do tej nádoby vojsť<br/>životom a povahou,<br/>zmiešať Ducha s naším duchom<br/>pre radosť, chválu Jeho.<br/>',NULL,131139,2);
INSERT INTO stanza VALUES('SK1325','3','Boh pracoval troma smermi<br/>pre Svoj vlastný, úžasný plán,<br/>aby ako Otec, Syn, Duch<br/>Seba udeľoval nám!<br/>Stvorenie je len pozadím,<br/>nebo, zem sú tu pre plán,<br/>pre toto je tu aj človek,<br/>telo, dušu, ducha má.<br/>',NULL,131140,3);
INSERT INTO stanza VALUES('SK1325','4','Ako centrum, ako jadro<br/>je náš duch v pláne Božom,<br/>keď voláme na Ježiša,<br/>tak náš duch je s Ním jedno.<br/>Z centra von do okolia chce<br/>Boh presiaknuť každú časť,<br/>obnovuje našu dušu,<br/>v srdci si Svoj dom stavia.<br/>',NULL,131141,4);
INSERT INTO stanza VALUES('SK1325','5','Sme budovaní v živote,<br/>v láske sme prepojení,<br/>Boh Svoj plán uskutočňuje,<br/>čo začal, završuje.<br/>Ó, Pane, rasti vnútri nás,<br/>aby si nás zbudoval,<br/>do tej nádoby súhrnnej<br/>naplnenej len Tebou.<br/>',NULL,131142,5);
INSERT INTO stanza VALUES('SK1325','6','Ako výsledok a záver<br/>bude Cirkev v sláve stáť,<br/>zámeru uskutočnenie<br/>naplánované je Ním.<br/>Boh Svoju nádobu získa,<br/>Božia sláva bude v nej.<br/>Pane, sme tu pre Tvoj zámer,<br/>Ty v nás dosiahni Svoj cieľ.<br/>',NULL,131143,6);
INSERT INTO stanza VALUES('SK1331','1','Zakús a cíť, že je Pán dobrý.<br/>Zakús a cíť, že je Pán dobrý.<br/>K tebe dobrý, tiež ku mne dobrý,<br/>tak, čokoľvek robíš, zakús a cíť.<br/>',NULL,131144,1);
INSERT INTO stanza VALUES('SK1331','2','Volaj: „Pane“ – On ti život zmení.<br/>Volaj: „Pane“ – On ti život zmení.<br/>Milosť veľkú ti Ježiš dá,<br/>ak kdekoľvek budeš „Pane“ volať.<br/>',NULL,131145,2);
INSERT INTO stanza VALUES('SK1331','3','Lásku veľkú do srdca ti On dá.<br/>Lásku veľkú do srdca ti On dá.<br/>Pocítiš prúd, čo Pán ti dá,<br/>potom spoznáš, že lásku máš.<br/>',NULL,131146,3);
INSERT INTO stanza VALUES('SK1331','4','Tak Pána chváľ, že život Jeho máš.<br/>Tak Pána chváľ, že život Jeho máš.<br/>Niečo ti Pán zo Seba dal,<br/>do teba vlial, tak Pána chváľ.<br/>',NULL,131147,4);
INSERT INTO stanza VALUES('SK1333','1','Ó, deň nádherný,<br/>v ktorom som bol zachránený,<br/>Ježiš ma preniesol z temnoty do dňa,<br/>do kráľovstva Svojho svetla.<br/>',NULL,131148,1);
INSERT INTO stanza VALUES('SK1333','2','Mám život nový,<br/>v Synovi život skutočný.<br/>Žiaden zemský sen ma už nepritiahne,<br/>živá rieka vo mne plynie.<br/>',NULL,131149,2);
INSERT INTO stanza VALUES('SK1333','3','Keď sa otvorím,<br/>On ma životom naplní.<br/>Jeho život sa mi stane skutočným,<br/>aleluja, som jedno s Ním!<br/>',NULL,131150,3);
INSERT INTO stanza VALUES('SK1333','4','Teba milujem,<br/>ostatné zväzky pretrhnem.<br/>Pane, budeš mojím životom navždy,<br/>Ty si pre mňa ten jediný.<br/>',NULL,131151,4);
INSERT INTO stanza VALUES('SK1339','1','Hľa, aké je to dobré a milé,<br/>keď bratia prebývajú spolu v jednote!<br/>Hľa, aké je to dobré a milé,<br/>keď bratia prebývajú spolu v jednote!<br/>Je to ako vzácny olej na hlave,<br/>ktorý na bradu steká, bradu Árona,<br/>steká až na okraj jeho rúcha.<br/>',NULL,131152,1);
INSERT INTO stanza VALUES('SK1339','2','Hľa, aké je to dobré a milé,<br/>keď bratia prebývajú spolu v jednote!<br/>',NULL,131153,2);
INSERT INTO stanza VALUES('SK1339','3','Ako rosa, čo na Hermone je,<br/>rosa, ktorá padá na sionské vrchy.<br/>Tam Pán prikázal požehnanie,<br/>ba aj život naveky.<br/>',NULL,131154,3);
INSERT INTO stanza VALUES('SK1340','1','Z prameňov spásy tak s radosťou<br/>vodu načierať budeme<br/>a Pánovi povieme: „Chvála Ti!“<br/>Pána vzývajme,<br/>Jeho skutky hlásajme všetkým,<br/>pripomínajme, že On je slávny.<br/>Plesaj! Jasaj! Ty, čo bývaš na Sione,<br/>lebo je veľký Svätý Izraela uprostred nás.<br/>',NULL,131155,1);
INSERT INTO stanza VALUES('SK1346','1','A Kráľovi vekov,<br/>neporušiteľnému,<br/>neviditeľnému Bohu,<br/>jedinému Bohu,<br/>Jemu česť a sláva na veky vekov!<br/>Amen. Amen.<br/>Jemu česť a sláva na veky vekov!<br/>Amen.<br/>',NULL,131156,1);
INSERT INTO stanza VALUES('SK3000','1','Našiel si už svojho ducha?<br/>K ústam je pripojený!<br/>„Ó, Pán Ježiš! Aleluja!“<br/>Tak bude uvoľnený!<br/>',NULL,131157,1);
INSERT INTO stanza VALUES('SK3000','chorus','Čo sa narodilo z Boha, je náš duch –<br/>dielo je dokonané!<br/>Čo sa narodilo z Ducha, je náš duch.<br/>Ó, z dvoch duchov jeden je.<br/>',NULL,131158,2);
INSERT INTO stanza VALUES('SK3000','2','Podnety neočakávaj –<br/>nepriateľ je zákerný.<br/>Otvor sa! Uvoľni ducha,<br/>dosvedč, že si slobodný.<br/>',NULL,131159,3);
INSERT INTO stanza VALUES('SK3001','1','Vystúpil zo slávy,<br/>prišiel a bol skromný,<br/>pôvodca života<br/>sa stal stvorením.<br/>Stále odmietaný,<br/>trápený súžením,<br/>z večnej vznešenosti<br/>v podobu hanby.<br/>',NULL,131160,1);
INSERT INTO stanza VALUES('SK3001','2','Pokoru si zvolil,<br/>byť obmedzovaný,<br/>konečnosť si zvolil<br/>a človekom byť.<br/>Skrytý Boží zámer<br/>v Ježišovi vidieť!<br/>Dve prirodzenosti –<br/>je Bohočlovek.<br/>',NULL,131161,2);
INSERT INTO stanza VALUES('SK3001','3','On bol prelomený,<br/>sláva uvoľnená<br/>vkladaním života,<br/>mnoho zrniek má.<br/>Je prvorodený<br/>a má mnohých bratov,<br/>sú inkorporáciou<br/>božskou a ľudskou!<br/>',NULL,131162,3);
INSERT INTO stanza VALUES('SK3001','4','Musíme Ho ľúbiť!<br/>Je naším predchodcom,<br/>víťazstvom naším je,<br/>našou radosťou.<br/>Deti odsúdenia<br/>do slávy priviedol.<br/>Mnoho Bohoľudí<br/>sa navždy teší!<br/>',NULL,131163,4);
INSERT INTO stanza VALUES('SK3002','1','Pane, ľúbim Ťa,<br/>nerovná sa Ti nik.<br/>Vo vesmíre celom<br/>nemám nikoho ako Ty.<br/>Pán Ježiš, ľúbim Ťa.<br/>',NULL,131164,1);
INSERT INTO stanza VALUES('SK3003','1','Len jeden dotyk, Drahý,<br/>jeden pohľad do očí,<br/>len bozk od Teba,<br/>ó, ľúbim Ťa, si môj.<br/>Nech mi Tvoj hlas znovu znie.<br/>Navždy si Teba beriem.<br/>S láskou hovor mi.<br/>Dávam sa Ti celkom.<br/>',NULL,131165,1);
INSERT INTO stanza VALUES('SK3003','chorus','Okrem Teba ma už nič a nikto<br/>neuspokojí.<br/>Ježiš, milujem Ťa, túžim po Tebe.<br/>Pane, milujem Ťa.<br/>',NULL,131166,2);
INSERT INTO stanza VALUES('SK3003','2','Znovu sa Ťa len dotknúť,<br/>vždy mám túžbu nemennú.<br/>Ty si najlepší!<br/>Pre Teba sa zničím.<br/>Ó, tie bozky Tvojich úst,<br/>pery Ťa vychvaľujú.<br/>Milosti plný,<br/>ó, vďaka Ti, Pane!<br/>',NULL,131167,3);
INSERT INTO stanza VALUES('SK3003','chorus','Okrem Teba ma už nič a nikto<br/>neuspokojí.<br/>Ježiš, si láskou mojou najlepšou, ó,<br/>Pane, rozpaľuj ma.<br/>',NULL,131168,4);
INSERT INTO stanza VALUES('SK3003','3','Sýť ma pohľadom Svojím,<br/>len to ma uspokojí!<br/>Na Teba hľadím,<br/>Ty ma plníš Sebou.<br/>Iba Ty to učiníš.<br/>Bez Teba som neschopný.<br/>Drž ma pri Sebe,<br/>nech jedno sme spolu.<br/>',NULL,131169,5);
INSERT INTO stanza VALUES('SK3003','chorus','Okrem Teba ma už nič a nikto<br/>neuspokojí.<br/>Ježiš, milujem Ťa, túžim po Tebe,<br/>srdce mi rozpaľuj.<br/>',NULL,131170,6);
INSERT INTO stanza VALUES('SK3003','4','S pokáním idem k Tebe,<br/>daj mi srdce horlivé.<br/>Chcem byť horlivý.<br/>Buď skutočný vo mne!<br/>S pokáním idem k Tebe,<br/>daj mi srdce horlivé.<br/>Chcem byť horlivý.<br/>Buď skutočný vo mne!<br/>',NULL,131171,7);
INSERT INTO stanza VALUES('SK3003','chorus','Ježiš, si láskou prvou a najlepšou!<br/>Kráčam späť k Tebe.<br/>Ježiš, si láskou prvou a najlepšou!<br/>Milujem Ťa, Pane!<br/>',NULL,131172,8);
INSERT INTO stanza VALUES('SK3004','1','Ľúbim Ťa, Pane! Myslím to vážne,<br/>bez Teba je život ničím.<br/>Veľmi príťažlivý, aj okúzľujúci,<br/>si prenesmierne bohatý.<br/>Tvoje meno sladké stále uspokojuje,<br/>Ty si môj a ja som Tvoj, Pane,<br/>s Tebou premiešaný,<br/>v Teba začlenený,<br/>chuť Nového Jeruzalema.<br/>',NULL,131173,1);
INSERT INTO stanza VALUES('SK3005','1','Sám srdce chráň vždy verným Tebe,<br/>stále chcem hľadieť iba v tvár Tebe,<br/>čisté srdce chráň, patrí len Tebe,<br/>ktoré lásku má a hodnotu len v Tebe.<br/>',NULL,131174,1);
INSERT INTO stanza VALUES('SK3005','chorus','Núti ma láska tá vydať všetko Tebe,<br/>nič nezmôžem, srdce mi tiahne len k Tebe.<br/>Ó, čo za vzácnosť to, vydať seba Tebe.<br/>Ó, milujem Teba len, patrím, Pane, len Tebe.<br/>',NULL,131175,2);
INSERT INTO stanza VALUES('SK3005','2','Sám lásku chráň, čo horí k Tebe,<br/>lásku sviežu, tú, čo horí vrúcne,<br/>tú lásku viacej, jasnejšiu k Tebe,<br/>takú, keď prvýkrát som prišiel k Tebe.<br/>',NULL,131176,3);
INSERT INTO stanza VALUES('SK3005','3','Dávam Ti sám život svoj Pane!<br/>Dám hoc aj tisíc, všetko dám Tebe!<br/>Nechránim seba, patrím len Tebe.<br/>Budúcnosť, život, Pane, tie sú v Tebe.<br/>',NULL,131177,4);
INSERT INTO stanza VALUES('SK3006','1','Kam pôjdeš ty, pôjdem i ja,<br/>kde ty budeš bývať, i ja,<br/>tvoj národ mojím bude<br/>a tvoj Boh tiež mojím bude.<br/>Kam pôjdeš ty, pôjdem i ja,<br/>kde ty budeš bývať, i ja,<br/>tvoj národ mojím bude<br/>a tvoj Boh tiež mojím bude.<br/>Tam, kde ty zomrieš, tam i ja,<br/>tam budem pochovaná.<br/>Nech Hospodin strestá a nech pridá,<br/>ak ma niečo odlúči od teba,<br/>nech Hospodin strestá a nech pridá,<br/>nech ma len smrť odlúči od teba.<br/>',NULL,131178,1);
INSERT INTO stanza VALUES('SK3007','1','Boh sníva sen o tom, po čom túži.<br/>Boh sníva sen, sen, v ktorom sme aj my.<br/>Boh sníva sen, ’by sme boli jedno s Ním.<br/>Boh sníva sen, ktorý v nás uskutoční!<br/>Boh chce, aby sme v Ňom prebývali.<br/>Boh v ľuďoch a ľudia v Ňom, celok pevný.<br/>Teraz je to môj sen, mnou prežívaný.<br/>Boh sníva sen a v nás ho uskutoční!<br/>',NULL,131179,1);
INSERT INTO stanza VALUES('SK3008','1','Čo s hriešnou minulosťou?<br/>V svedomí nie je pokoj.<br/>Vnútri iba bolesť mám.<br/>Moje viny odsudzujú ma.<br/>',NULL,131180,1);
INSERT INTO stanza VALUES('SK3008','2','V živote mám trápenie,<br/>v tomto márnivom svete,<br/>ak som si šťastie hľadal,<br/>napokon vnútri som prázdno mal.<br/>',NULL,131181,2);
INSERT INTO stanza VALUES('SK3008','3','Boh bol pre mňa vzdialený,<br/>je skvelý a nádherný.<br/>No ľudskosť si na seba vzal,<br/>prišiel pre mňa,<br/>zomrel za mňa,<br/>krv si prelial za mňa.<br/>',NULL,131182,3);
INSERT INTO stanza VALUES('SK3008','chorus','Preto Ho ľúbim.<br/>Preto si Ho cením.<br/>Preto Mu svoj život celý zverím.<br/>Preto Ho ľúbim.<br/>Preto si Ho cením.<br/>Preto Mu svoj život celý zverím.<br/>',NULL,131183,4);
INSERT INTO stanza VALUES('SK3009','1','Ak sa stávame takými, ako je Kristus<br/>v živote, prirodzenosti, vyjadrení,<br/>sme kvalifikovaní pracovať s Ním<br/>pre Jeho Telo.<br/>',NULL,131184,1);
INSERT INTO stanza VALUES('SK3009','2','Ak sa bezradne spoliehame na Pána,<br/>závisiac na Ňom ako láske a sile,<br/>a počúvame Jeho prehováranie,<br/>našou nádejou je, aby sme boli uchvátení<br/>skrze vykúpenie nášho tela.<br/>',NULL,131185,2);
INSERT INTO stanza VALUES('SK3009','chorus','A modlíme sa – „Príď Pane!“<br/>A modlíme sa – „Príď Pane!“<br/>„Príď, Pán Ježiš! Pán Ježiš, príď!“<br/>',NULL,131186,3);
INSERT INTO stanza VALUES('SK3010','1','Teraz vidím,<br/>Pane, chceš, aby som veril,<br/>nie menil.<br/>V každej porážke, zlyhaní,<br/>len Tvojmu dielu veril,<br/>nie tomu, čo vidím.<br/>',NULL,131187,1);
INSERT INTO stanza VALUES('SK3010','2','Pane, verím,<br/>aj keď je mnoho sklamaní,<br/>navonok sa nič nedeje, nemení.<br/>Nie! Nie som znechutený,<br/>iba Tebe verím.<br/>',NULL,131188,2);
INSERT INTO stanza VALUES('SK3010','3','Áno, verím,<br/>že Ty nič nepožaduješ.<br/>Vieru len, áno, len tú odo mňa chceš.<br/>Už viac nepochybujem,<br/>som voľný, len verím!<br/>',NULL,131189,3);
INSERT INTO stanza VALUES('SK3010','4','Tebe verím,<br/>úspechom, Pane, si mojím!<br/>Keď zlyhám, k Tebe sa vrátim s vyznaním,<br/>ďalej sa z Teba teším,<br/>Pane, Tebe verím!<br/>',NULL,131190,4);
INSERT INTO stanza VALUES('SK3011','1','Padlí, tak sme všetci začali.<br/>Väznení, zlým osudom zajatí.<br/>Ako môžeme byť spasení?<br/>Ako?<br/>',NULL,131191,1);
INSERT INTO stanza VALUES('SK3011','chorus','Len volajme, ó, Pane Ježišu,<br/>stále a celý deň!<br/>Zisťujeme, že volanie<br/>Ježiša cestou je,<br/>ó, Ježiš, Pán Ježiš!<br/>',NULL,131192,2);
INSERT INTO stanza VALUES('SK3011','2','Aj keď Pána veľmi ľúbime,<br/>stane sa, že si Ho nevšímame.<br/>Ako zdolať to rozptýlenie?<br/>Ako?<br/>',NULL,131193,3);
INSERT INTO stanza VALUES('SK3011','3','Vieme, že nie vždy sme úprimní,<br/>často sa riadime len pocitmi.<br/>Ako byť od svojho ja voľní?<br/>Ako?<br/>',NULL,131194,4);
INSERT INTO stanza VALUES('SK3011','4','Kde je Tvoja nevesta, Pane?<br/>Kresťania sú rozptýlení všade.<br/>Ako sa zjednotiť môžeme?<br/>Ako?<br/>',NULL,131195,5);
INSERT INTO stanza VALUES('SK3012','1','Kristus je život náš, veď prešiel celým procesom.<br/>Boh Otec je zdrojom, je v skrytosti, On je žriedlom.<br/>Syn – Prameň, vyvierajúci von,<br/>a Duch je riekou, čo vnáša do nás život!<br/>Ó, ako je toto možné, že Trojica prúdi vo mne?<br/>Ó, máme živú vodu, rieku života, čo prúdi z nás!<br/>Máme živú vodu, rieku života, čo prúdi z nás!<br/>',NULL,131196,1);
INSERT INTO stanza VALUES('SK3012','chorus','Život prúdi cez nás a zaopatruje nás.<br/>Život nuluje hriech! Vládne mocne vo mne!<br/>Som voľný a ten život vo mne víťazí.<br/>',NULL,131197,2);
INSERT INTO stanza VALUES('SK3012','2','Máme život, nie však, aby sme len víťazili.<br/>Náš Boh úmysel má, Jeho prúd nie je bezcieľny.<br/>Život má teda zavŕšenie,<br/>Jeho celistvosť ma stále obklopuje.<br/>Hýbe sa, rastie, prúdom formuje,<br/>zdieľam s ním jeho určenie.<br/>Ó, máme živú vodu, rieku života, čo prúdi z nás!<br/>Máme živú vodu, rieku života, čo prúdi z nás!<br/>',NULL,131198,3);
INSERT INTO stanza VALUES('SK3012','chorus','Sme vo vzájomnosti, aby bol Boh zjavený,<br/>Duch spolu s nevestou.<br/>Príď! Pi! A jedz ten strom!<br/>Je pre nás, naším potešením naveky!<br/>',NULL,131199,4);
INSERT INTO stanza VALUES('SK3012','3','Dôvod na hnev nemám, veď som prijal život, zoe.<br/>Viem, že život plynie a víťazí nevyhnutne.<br/>Ostať v tom toku musím nutne,<br/>ak z neho budem piť, Boh bude rásť vo mne.<br/>Radosť v srdci mám, aj jar v krokoch mám,<br/>na tvári úsmev, keď spievam.<br/>Ó, máme živú vodu, rieku života, čo prúdi z nás!<br/>Máme živú vodu, rieku života, čo prúdi z nás!<br/>',NULL,131200,5);
INSERT INTO stanza VALUES('SK3013','1','Tajomstvom veľkým je<br/>ten nádherný príbeh,<br/>dlho ukrytý bol,<br/>no dnes zjavený je.<br/>Ten príbeh je láska<br/>Boha a človeka,<br/>môžeme ho chápať,<br/>keď Boh prehovára.<br/>',NULL,131201,1);
INSERT INTO stanza VALUES('SK3013','chorus','Iba Božia láska<br/>človeka premieňa,<br/>aby rovnakými sme<br/>my ako Boh boli.<br/>Jeho vyjadrením,<br/>Jeho rozšírením,<br/>nevestou na veky,<br/>pár nerozdeliteľný a žijúci<br/>navždy spolu.<br/>',NULL,131202,2);
INSERT INTO stanza VALUES('SK3013','2','Hoc odmietaný je<br/>On zaslepenými,<br/>tiahne Jeho láska,<br/>srdce nemenné má.<br/>Tak sa vtelením stal<br/>navždy spasením nám,<br/>prišiel, ’by hľadal nás,<br/>On Ježiš volá sa.<br/>',NULL,131203,3);
INSERT INTO stanza VALUES('SK3013','3','Hoc hriešnikom som bol,<br/>krvou ma vykúpil,<br/>tým, že prešiel krížom<br/>a tiež vzkriesený bol,<br/>’by znovuzrodil ma<br/>a v duchu spojil nás.<br/>Jeho vychutnávam,<br/>veď odpustené mám.<br/>',NULL,131204,4);
INSERT INTO stanza VALUES('SK3013','4','Nežná Jeho láska,<br/>Jemu sa poddávam,<br/>ja Ježiša chválim<br/>a radostne vzývam.<br/>Je očarujúci,<br/>srdce víťazí vždy,<br/>viac nebudem váhať,<br/>budem Ho milovať.<br/>',NULL,131205,5);
INSERT INTO stanza VALUES('SK3014','1','Vďačný som, že Pán ma sem dal<br/>s vami budovať Jeho chrám,<br/>moja nádej je Pán vo vás,<br/>Kristus vo mne je tu pre vás.<br/>',NULL,131206,1);
INSERT INTO stanza VALUES('SK3014','chorus','Žijem, keď ste v Pánovi pevní,<br/>vy žijete, keď som ja pevný,<br/>môj pokrok je tu pre vás,<br/>váš pokrok je tu pre mňa,<br/>nie sme oddelení,<br/>potrebujem vás, svätí.<br/>',NULL,131207,2);
INSERT INTO stanza VALUES('SK3014','2','Sladký život cirkvi máme,<br/>nevestou sa Mu stávame,<br/>vďaka vám budem v Ňom pevný,<br/>vaším Kristom povzbudený.<br/>',NULL,131208,3);
INSERT INTO stanza VALUES('SK3014','3','Pomáha mi vaša viera,<br/>môj pokrok závisí od vás,<br/>so zreteľom na vás hľadám,<br/>pre vás mám plné srdce chvál.<br/>',NULL,131209,4);
INSERT INTO stanza VALUES('SK3014','4','Boh túži, aby sme Ho my<br/>všetci spoločne hľadali,<br/>vzájomne sa rozdávali,<br/>jeden pre druhého žili.<br/>',NULL,131210,5);
INSERT INTO stanza VALUES('SK3014','5','Chcem vás všetkých povzbudzovať,<br/>bez vás budem stále padať.<br/>Kristus v tebe nie je malý.<br/>Potrebuje Pán ťa, aj my.<br/>',NULL,131211,6);
INSERT INTO stanza VALUES('SK3015','1','Sme tu, Pán Najvzácnejší,<br/>Tebou povolaní.<br/>Radosť byť povolaní<br/>a vstúpiť do archy.<br/>Denne spásu dávaš nám,<br/>takúto cestu máš.<br/>V Sebe nás všetkých Ty sám<br/>nad týmto vekom zlým držíš.<br/>',NULL,131212,1);
INSERT INTO stanza VALUES('SK3015','chorus','V očiach Pánových máme milosť,<br/>máme už otvorené srdcia,<br/>bez ohľadu, čo nám ukážu priatelia,<br/>my milujeme Teba.<br/>',NULL,131213,2);
INSERT INTO stanza VALUES('SK3015','2','Chceli sme okúsiť svet<br/>a účasť mať na ňom.<br/>No nevedeli sme, že<br/>Ty zármutok máš v tom.<br/>K Tebe dnes prichádzame,<br/>so skrúšeným srdcom.<br/>S Tebou v arche chceme byť,<br/>vydávame sa Ti preto.<br/>',NULL,131214,3);
INSERT INTO stanza VALUES('SK3015','3','Len v Tebe sme v bezpečí,<br/>sme mimo vôd smrti.<br/>Čo som kedysi mal rád,<br/>je vo vodách smrti.<br/>Chceme byť otvorení,<br/>nedovoľ zblúdiť nám.<br/>Aleluja, v arche sme,<br/>sme v cirkvi, Pánovi chvála.<br/>',NULL,131215,4);
INSERT INTO stanza VALUES('SK3016','1','Mária vyliala seba,<br/>pre mnohých to bola strata,<br/>v priebehu všetkých storočí<br/>milujúcich Ťa takých máš.<br/>Drahé životy, vzácnosti,<br/>kariéra a budúcnosť,<br/>na Teba „premárnené“,<br/>výrazná je Tvoja sladkosť.<br/>Ona to využila,<br/>najvzácnejšie Ti dala,<br/>chcem aj ja vyliať seba<br/>aj lásku, všetko, čo mám.<br/>',NULL,131216,1);
INSERT INTO stanza VALUES('SK3016','2','Milujem Ťa, upriamujem<br/>ducha môjho, dušu, telo,<br/>srdce, myseľ, celú silu<br/>a celú bytosť na Teba.<br/>Celú svoju bytosť nechám<br/>len Tebou obsadiť, Pane,<br/>do srdca Tvojho vchádzam<br/>a sladký tok pociťujem.<br/>Pane, v Tebe stratený,<br/>len Ty sám si moje všetko,<br/>v duchu sa z Teba teším<br/>v spoločenstve dôvernom.<br/>',NULL,131217,2);
INSERT INTO stanza VALUES('SK3016','3','Vo vesmíre niet nikoho,<br/>po kom túžim, okrem Teba,<br/>hoci som už porušený,<br/>vždy ako svoj podiel Ťa mám.<br/>Všetko je iba márnosťou,<br/>to, čo nie si Ty, stratou je,<br/>lásku mi všetko berie,<br/>Ty však máš už srdce moje.<br/>Zbadal som Tvoju cennosť,<br/>tiež vzácnosť a skutočnosť,<br/>teraz vyznávam, Pane,<br/>patrí Ti srdce moje.<br/>',NULL,131218,3);
INSERT INTO stanza VALUES('SK3017','1','Niekedy chvíle mám,<br/>sú plné rozhorčenia<br/>a sú bez odpovedí.<br/>Aj tak tiahneš ma,<br/>nech vstúpim do Tvojho svätostánku, Pane.<br/>Obrátim svoj zrak k nebesiam,<br/>zrazu sa otázky zmenia<br/>na tieto slová:<br/>',NULL,131219,1);
INSERT INTO stanza VALUES('SK3017','2','Koho mám na nebesiach<br/>okrem Teba, Pane?<br/>Telo a srdce mi upadá.<br/>Avšak Boh je mojím podielom a silou,<br/>k Nemu sa navždy utiekam.<br/>Hospodin je bezpečnou skrýšou<br/>teraz aj naveky...<br/>',NULL,131220,2);
INSERT INTO stanza VALUES('SK3017','3','Obráť ma, vidieť Ťa<br/>potrebujem, Ježišu!<br/>Aj keď nerozumiem<br/>vždy Tvojim cestám,<br/>učiň ma dieťaťom, čo Ťa stále chváli,<br/>vychutnáva Tvoje slovo.<br/>Nech ma skúsenosti naplnia<br/>Tvoj život vyjadrím<br/>... vždy, vo všetkom.<br/>',NULL,131221,3);
INSERT INTO stanza VALUES('SK3018','1','Boh nás volá pre Svoj zámer<br/>ekonómie preslávnej,<br/>kvôli ktorej prešiel proces<br/>a dnes je dovŕšený!<br/>Ako Duch prebýva v nás<br/>Bohom daný podiel náš,<br/>plnú spásu vykonáva,<br/>rovnakými Sebe činí.<br/>',NULL,131222,1);
INSERT INTO stanza VALUES('SK3018','chorus','Ó, nech jasná riadiaca vízia<br/>Pánovej ekonómie riadi<br/>moje srdce a nech horí, kým môj duch nevzplanie!<br/>Silným, aktívnym duchom môžeme<br/>zavŕšiť plán Boží, Nový Jeruzalem, aleluja!<br/>',NULL,131223,2);
INSERT INTO stanza VALUES('SK3018','2','Ježiš žil Bohoľudský vzor,<br/>bol cestou, naším predchodcom,<br/>zapieral Seba samého,<br/>bol až na smrť poslušný!<br/>Bol jediný Bohočlovek,<br/>dnes sme Jeho rozmnožením,<br/>mnoho zmiešaných zrniečok,<br/>súhrnnou reprodukciou!<br/>',NULL,131224,3);
INSERT INTO stanza VALUES('SK3018','3','Žijeme Jeho vzkriesenie,<br/>telu, duši umierame,<br/>zmiešaným duchom žijeme,<br/>prirodzené zaprieme!<br/>Dnes žijeme v Jeho Tele<br/>a každý deň víťazíme,<br/>chceme byť na vrchu Sion,<br/>očakávať Pánov príchod!<br/>',NULL,131225,4);
INSERT INTO stanza VALUES('SK3018','4','Boh a človek spolu žijú,<br/>vzájomne v zmiešanom duchu,<br/>prebývame v Ňom a On v nás,<br/>organická entita!<br/>Táto vízia vekov nech<br/>riadi naše denné žitie,<br/>aby Pán mohol mať Telo,<br/>žiariť ako sväté mesto.<br/>',NULL,131226,5);
INSERT INTO stanza VALUES('SK3019','1','Posledný Adam sa stal Životodarným Duchom.<br/>A Pán je Duchom, ten Duch dáva život.<br/>Kto sa spája s Pánom, je s Ním, s Ním jeden duch.<br/>Ó, my sme sa s Ním spojili, my sme s Pánom jeden duch.<br/>',NULL,131227,1);
INSERT INTO stanza VALUES('SK3020','1','V bezbožnom veku<br/>Ti treba Samuelov,<br/>ekonómiu Tvoju, ktorí vidia jasne.<br/>Kde je archa dnes?<br/>Kto sa o Teba stará,<br/>kto dnes seba odkladá kvôli túžbe Tvojej?<br/>',NULL,131228,1);
INSERT INTO stanza VALUES('SK3020','chorus','Vzbuď nazirejov pre Svoje potreby,<br/>prorokov, kňazov, sudcov, ľudí modlitby.<br/>S Tvojou mocou Tvoje slovo prehovárajúcich,<br/>fotkou sú Tvojou pre Tvoj pohyb.<br/>',NULL,131229,2);
INSERT INTO stanza VALUES('SK3020','2','Cvič nás, aby sme<br/>s víziou a hľadaním<br/>očakávali Teba, boli podriadení.<br/>Ceniac Tvoju tvár<br/>v Tvojej prítomnosti sme,<br/>čo vidíme len v Tvojich očiach, počúvneme.<br/>',NULL,131230,3);
INSERT INTO stanza VALUES('SK3020','chorus','Vzbuď nazirejov pre Svoje potreby,<br/>aby kráľovstvo Tvoje na zem priviedli.<br/>Tých, čo za kráľa Ťa berú, aby si sa vrátil<br/>a cez nich tento vek ukončil.<br/>',NULL,131231,4);
INSERT INTO stanza VALUES('SK3020','3','Keď chce Boh konať,<br/>musí získať niekoľkých<br/>víťazov, oddelených od súčasnej doby.<br/>Pripojili sa<br/>k Jeho túžbe cez slovo,<br/>víťazi, ustavení Jeho svätým slovom.<br/>',NULL,131232,5);
INSERT INTO stanza VALUES('SK3020','chorus','Vzbuď nazirejov pre Svoje potreby,<br/>čo budú Ti dobrovoľne zasvätení,<br/>tých, čo sa už pripojili slovom k túžbe Tvojej –<br/>mať živé svedectvo na zemi.<br/>',NULL,131233,6);
INSERT INTO stanza VALUES('SK3020','4','Boh potrebuje<br/>tých ľudí, čo sa modlia,<br/>ekonómiu Svoju nimi uskutoční.<br/>Nie sú sebeckí,<br/>ochotne sa vydajú,<br/>stratiť prítomnosť Jeho, zarmútiť Ho nechcú.<br/>',NULL,131234,7);
INSERT INTO stanza VALUES('SK3020','chorus','Učiň z nás tých, čo budú nazireji,<br/>nech cez nás môžeš tento vek uzatvoriť,<br/>nech sme stále jedno s Tebou pre Tvoje kráľovstvo,<br/>mládež pre Tvoj pohyb na zemi.<br/>',NULL,131235,8);
INSERT INTO stanza VALUES('SK3021','1','Čo mi bolo ziskom,<br/>počítam za straty.<br/>To, čím som bol, toho<br/>ma Pán zbavil!<br/>Dobré aj veci zlé,<br/>ktoré boli moje,<br/>dnes sú len smetím,<br/>Pán mi ziskom je.<br/>',NULL,131236,1);
INSERT INTO stanza VALUES('SK3021','chorus','Nezastanem!<br/>Budem bežať, až dokiaľ<br/>nedosiahnem<br/>ten cieľ povolania!<br/>Bežím ďalej!<br/>Až kým sa nezmocním<br/>Toho, ktorý<br/>sa aj mňa zmocnil!<br/>',NULL,131237,2);
INSERT INTO stanza VALUES('SK3021','2','Zabúdať, čo je preč,<br/>uháňať iba vpred,<br/>je zmýšľanie moje,<br/>chcem stále viac!<br/>V Ňom rásť potrebujem,<br/>viacej Ho poznať chcem,<br/>každý deň chcem byť<br/>v Kristovi viacej.<br/>',NULL,131238,3);
INSERT INTO stanza VALUES('SK3022','1','Cieľom evanjelia je,<br/>aby sme, milujúc Pána Ježiša<br/>najlepšou láskou, Naňho vylievali to,<br/>čo je nám najcennejšie,<br/>ba aj duchovné, cenné, krásne, vzácne bohatstvá,<br/>„premárnili“ seba Naň,<br/>ba aj duchovné, cenné, krásne, vzácne bohatstvá,<br/>„premárnili“ seba Naň.<br/>',NULL,131239,1);
INSERT INTO stanza VALUES('SK3023','1','Stvor mi srdce čisté, ó, Bože<br/>a ducha vo mne obnov pevného.<br/>Stvor mi srdce čisté, ó, Bože<br/>a ducha vo mne obnov pevného.<br/>Neodháňaj ma od Seba, nie,<br/>Svätého Ducha neber mi, nie.<br/>Oživ radosť vnútri, že som zachránený,<br/>obnov mi ducha, nech ochotný je.<br/>',NULL,131240,1);
INSERT INTO stanza VALUES('SK3024','1','Božou večnou ekonómiou<br/>je, aby bol človek ako On<br/>v živote, povahe,<br/>no nie v Jeho Božstve.<br/>A zjednotiť sa s človekom,<br/>ľudí so Sebou,<br/>takto sa zväčšiť<br/>a rozšíriť vo vyjadrení,<br/>’by všetky Jeho božské vlastnosti<br/>boli vyjadrené cez naše ľudské cnosti.<br/>',NULL,131241,1);
INSERT INTO stanza VALUES('SK3025','1','Nechcel by si spoznať Boha?<br/>Čo ukryté pre teba má?<br/>Že si želá, ’by si prišiel,<br/>otvoril sa –<br/>dovolil Mu naplniť ťa,<br/>zjaviť ti to, čo vnútri má,<br/>radosť, ktorú pred Sebou mal?<br/>',NULL,131242,1);
INSERT INTO stanza VALUES('SK3025','chorus','Cirkev je Jeho nevesta,<br/>pre ňu ochotne umieral,<br/>radosť veľká, čo vnútri má,<br/>náprotivok a poéma.<br/>',NULL,131243,2);
INSERT INTO stanza VALUES('SK3025','2','Byť súčasťou Jeho diela<br/>a umenia, zvolil teba.<br/>To úžasná je výsada!<br/>Uspokojiť<br/>Jeho prianie, dať sám Seba,<br/>Svoje nesmierne bohatstvá!<br/>Nech múdrosť je vyjadrená!<br/>',NULL,131244,3);
INSERT INTO stanza VALUES('SK3025','3','Zatiaľ čo Ho zakúšame,<br/>tak postupne spoznávame,<br/>aké Jeho je zmýšľanie<br/>o nás všetkých.<br/>Tá láska k nám Ho priviedla,<br/>napriek hriechom prišiel až k nám.<br/>Prečo predal všetko, čo mal?<br/>',NULL,131245,4);
INSERT INTO stanza VALUES('SK3026','1','Boh Jána použil,<br/>ten minulosť opustil,<br/>náboženstvo svojho veku.<br/>Starobu opustil,<br/>odvážne prehovoril.<br/>Zanechajte tento zlý vek.<br/>',NULL,131246,1);
INSERT INTO stanza VALUES('SK3026','chorus','Víťazov Boh musí mať,<br/>milovníkov Ježiša!<br/>Učiň z nás ľudí, čo zmenia vek!<br/>Víťazov Boh musí mať,<br/>milovníkov Ježiša!<br/>Nech sme tí, ktorí ukončia vek!<br/>',NULL,131247,2);
INSERT INTO stanza VALUES('SK3026','2','Boh Šavla povolal,<br/>vlastný mal zámer a plán,<br/>stal sa Pavlom apoštolom.<br/>Víziu uvidel,<br/>kde nie je rozdelenie<br/>v jedinom Pánovom Tele!<br/>',NULL,131248,3);
INSERT INTO stanza VALUES('SK3026','3','Taktiež Timoteja,<br/>s Pavlom jednu dušu mal,<br/>modlil sa, bol naplnený,<br/>jeho duch vždy horel.<br/>Nech môj duch rovnaký je,<br/>nech som Boží človek - víťaz!<br/>',NULL,131249,4);
INSERT INTO stanza VALUES('SK3026','chorus','Nech Tvoji víťazi sme,<br/>nevesta, čo zmení vek.<br/>Nech sme tí, ktorí ukončia vek!<br/>',NULL,131250,5);
INSERT INTO stanza VALUES('SK3027','1','Cirkev je domom živého Boha,<br/>cirkev je stĺpom a oporou pravdy<br/>a veľké je tajomstvo pobožnosti,<br/>že Boh sa zjavil, zjavil sa v tele.<br/>',NULL,131251,1);
INSERT INTO stanza VALUES('SK3028','1','Cirkev je stavbou všetkých<br/>vyvolených, vykúpených,<br/>znovuzrodených a premenených ľudí,<br/>konečné Božie dielo,<br/>je náprotivkom Jeho,<br/>sedem zlatých svietnikov,<br/>Boží dom aj Telo Kristovo,<br/>cirkev je Božou túžbou.<br/>',NULL,131252,1);
INSERT INTO stanza VALUES('SK3028','2','Chvála Pánovi! Filadelfia:<br/>držia sa Tvojho slova,<br/>Tvoje meno nezaprú,<br/>žijú v miestnej cirkvi,<br/>v univerzálnom spoločenstve,<br/>na pôde pravej jednoty,<br/>vytvárajú Telo Kristovo.<br/>',NULL,131253,2);
INSERT INTO stanza VALUES('SK3028','3','Povstaň! Rasti v Ňom!<br/>Všetkým posluhujme Kristom,<br/>dospejme k jednote.<br/>Milosť nám daj, chceme vidieť<br/>Tvoj večný zámer.<br/>Chceme verne obnovovať<br/>a budovať cirkev.<br/>',NULL,131254,3);
INSERT INTO stanza VALUES('SK3029','1','Ja som ten chlieb živý,<br/>ktorý zostúpil z neba;<br/>ak niekto je,<br/>ak niekto je z tohto chleba,<br/>bude žiť naveky.<br/>',NULL,131255,1);
INSERT INTO stanza VALUES('SK3029','2','A chlieb (a chlieb), ktorý dám (ktorý dám),<br/>je moje telo,<br/>vydané (vydané), za život (za)<br/>život sveta.<br/>',NULL,131256,2);
INSERT INTO stanza VALUES('SK3029','3','Ja som ten chlieb živý,<br/>ktorý zostúpil z neba;<br/>ak niekto je,<br/>ak niekto je z tohto chleba,<br/>bude žiť naveky.<br/>',NULL,131257,3);
INSERT INTO stanza VALUES('SK3030','1','My máme Otca,<br/>je láskavý ku všetkým nám.<br/>Veľké srdce má,<br/>Jeho láska je nekonečná.<br/>Aj keď spáchame hriech,<br/>stále sa vrátiť môžeme.<br/>Taká je Otcova láska k nám.<br/>Musíme sa kajať,<br/>v Jeho náručí tak zostať.<br/>Taká je Otcova láska k nám.<br/>',NULL,131258,1);
INSERT INTO stanza VALUES('SK3031','1','Som veľmi šťastný,<br/>som pri Otcovi,<br/>bol som opäť nájdený!<br/>Úsmev Svoj mi dal,<br/>vrúcne ma objal,<br/>milosťou opäť dojal!<br/>',NULL,131259,1);
INSERT INTO stanza VALUES('SK3031','chorus','Stratený, opäť nájdený!<br/>Nežil som, no žijem dnes!<br/>Príď, teš sa s nami! Prešťastný budeš.<br/>V Otcovom dome som opäť!<br/>',NULL,131260,2);
INSERT INTO stanza VALUES('SK3031','2','Rúcho, prsteň mám, (Sandále mám)<br/>svoj hlad som zahnal! (Hlad som zahnal)<br/>Doma opäť miesto mám! (Veď tu patrím, Otec mi)<br/>Krásne šaty dal, (Potom ma)<br/>znovu ma prijal! (Teraz som späť)<br/>Svoju rodinu opäť mám!<br/>',NULL,131261,3);
INSERT INTO stanza VALUES('SK3032','1','Niekedy zdá sa,<br/>že v srdci pre Teba miesta niet.<br/>Tak sa ma dotkneš,<br/>obmäkčíš, vrátiš ma k Sebe.<br/>',NULL,131262,1);
INSERT INTO stanza VALUES('SK3032','chorus','Obnov srdce mi,<br/>nech Ťa ľúbim nanovo.<br/>Láskou ma sýť<br/>večnou, stále len novou,<br/>nech som celý Tvoj.<br/>',NULL,131263,2);
INSERT INTO stanza VALUES('SK3032','2','Pane môj, túžim<br/>byť od všetkého vyprázdnený.<br/>Najlepšiu lásku<br/>Ti dať, nech Si vo všetkom prvý.<br/>',NULL,131264,3);
INSERT INTO stanza VALUES('SK3032','3','Túžim Ťa ľúbiť,<br/>celým svojím srdcom aj dušou.<br/>Nechcem iné nič,<br/>vydávam sa Ti, chcem byť len Tvoj.<br/>',NULL,131265,4);
INSERT INTO stanza VALUES('SK3033','1','S: Videl som,<br/>B: a hľa, On<br/>S: hľa, Baránok<br/>B: na Sione<br/>V: a stoštyridsaťštyritisíc s Ním.<br/>S: S Jeho menom<br/>B: aj s menom<br/>S: Jeho Otca<br/>B: Jeho Otca<br/>V: mali ho na čelách.<br/>',NULL,131266,1);
INSERT INTO stanza VALUES('SK3033','2','S: To sú tí<br/>B: neznečistení.<br/>S: To sú tí<br/>B: bez viny<br/>V: čo Baránka nasledujú.<br/>S: To sú tí<br/>B: vykúpení<br/>S: tí z ľudí<br/>B: Bohu prví<br/>V: čo Baránka nasledujú, čo nasledujú.<br/>',NULL,131267,2);
INSERT INTO stanza VALUES('SK3033','3','Nasledujú iba Jeho,<br/>žijú, chodia v zmiešanom duchu,<br/>a takto sú vedení Duchom,<br/>neprestajne, nepretržite každý jeden deň.<br/>',NULL,131268,3);
INSERT INTO stanza VALUES('SK3034','1','Ak ťa Boh vedie po ceste čo poznáš,<br/>nezískaš toľko, ako keby ťa viedol cestou,<br/>ktorou si nikdy predtým nekráčal.<br/>To ťa prinúti mať stovky,<br/>tisíce rozhovorov s Pánom<br/>a to bude cestou,<br/>ktorá bude nekonečnou<br/>spomienkou medzi tebou a Ním.<br/>',NULL,131269,1);
INSERT INTO stanza VALUES('SK3035','1','Čo za Krista máme, je pre nás všetkým,<br/>pridelený vo svetle podiel svätých,<br/>v kráľovstve Syna Božieho, Syna lásky Božej,<br/>vládne tu vo svetle lásky Svojej.<br/>',NULL,131270,1);
INSERT INTO stanza VALUES('SK3035','2','Porozhliadaj sa z miesta kde stojíš.<br/>Všeobsiahleho Krista - Zem uvidíš,<br/>vychutnávajme zem, ktorú vidíme, prehojnú,<br/>sme živí jedením mlieka, medu.<br/>',NULL,131271,2);
INSERT INTO stanza VALUES('SK3035','3','Pšenica je obmedzený Ježiš.<br/>Vtelením bol Pán telom obmedzený.<br/>Navonok spútaný, Božou mocou voľný,<br/>neobmedzený jačmeň, je vzkriesený.<br/>',NULL,131272,3);
INSERT INTO stanza VALUES('SK3035','4','Vinič je Kristus obetovaný.<br/>Svojím vínom Boha, ľudí teší.<br/>Pijeme nové víno, sme povzbudení,<br/>obeťou živou chceme byť Pánovi.<br/>',NULL,131273,4);
INSERT INTO stanza VALUES('SK3035','5','Figovník je sladký a výživný,<br/>nech sme vo svojej viere radostní.<br/>Pre iných kanálom zaopatrenia buď vždy,<br/>nech zakúšajú Krista a sú šťastní.<br/>',NULL,131274,5);
INSERT INTO stanza VALUES('SK3035','6','Plnosť Jeho života, granátovník<br/>v ňom je krása, na život je bohatý.<br/>Ako oliva, dáva Ducha, ctíme Boha aj ľudí.<br/>sme ratolesti, v Krista naštepení.<br/>',NULL,131275,6);
INSERT INTO stanza VALUES('SK3035','7','Naša porcia je veľmi prístupná,<br/>naplno môže byť vychutnávaná.<br/>Chápeme nesmiernu širokosť tej zeme Dobrej,<br/>keď Ho so svätými vychutnávame.<br/>',NULL,131276,7);
INSERT INTO stanza VALUES('SK3036','1','Dvaja z nich kráčali<br/>do Emauz, zarmútení,<br/>učiteľ im umrel.<br/>Muž sa k nim pripojil,<br/>keď rozprával, horeli,<br/>jemu sa vyliali.<br/>(Vravel im:)<br/>',NULL,131277,1);
INSERT INTO stanza VALUES('SK3036','chorus','Prečo neveríte?<br/>Veď bolo nevyhnutné,<br/>že Kristus si všetko vytrpí<br/>a do slávy vstúpi.<br/>Prečo neveríš?<br/>Prečo neveríš?<br/>',NULL,131278,2);
INSERT INTO stanza VALUES('SK3036','2','K cieľu sa blížili,<br/>„poď do vnútra“, žiadali,<br/>zostal a lámal chlieb.<br/>Oči im otvoril,<br/>zrazu Pána spoznali,<br/>no On sa im stratil.<br/>(Vraveli:)<br/>',NULL,131279,3);
INSERT INTO stanza VALUES('SK3036','chorus','Či sme nehoreli,<br/>keď k nám hovoril?<br/>Keď sme išli s Ním,<br/>Písma nám otvoril.<br/>Či sme nehoreli?<br/>Či sme nehoreli?<br/>',NULL,131280,4);
INSERT INTO stanza VALUES('SK3036','3','Dnes sme na ceste s Ním,<br/>aj dnes nám Pán hovorí:<br/>„Každý deň som s tebou.“<br/>Aj keď sa cítiš zle,<br/>je živým Duchom v tebe,<br/>skutočne v nás žije.<br/>(Vravíme:)<br/>',NULL,131281,5);
INSERT INTO stanza VALUES('SK3036','chorus','Vari nehoríš,<br/>keď On hovorí?<br/>Ježiš v tebe je,<br/>vo vzkriesení žije!<br/>Či nehoríme?<br/>Či nehoríme?<br/>',NULL,131282,6);
INSERT INTO stanza VALUES('SK3037','1','Naplň mi ducha! Naplň mi ducha!<br/>Nech preteká,<br/>zvnútra môjho nech vyteká!<br/>Naplň mi ducha! Naplň mi ducha!<br/>Nech preteká,<br/>zvnútra môjho nech vyteká!<br/>',NULL,131283,1);
INSERT INTO stanza VALUES('SK3037','chorus','Chcem byť plný, dnes sa modlím:<br/>Ó, Pán Ježiš, teč, ako voda živá.<br/>Ó, Pán Ježiš, tryskaj, nech živý prameň<br/>prúdi z môjho vnútra! Amen.<br/>',NULL,131284,2);
INSERT INTO stanza VALUES('SK3037','2','Pane, všade vstúp! Pane, všade vstúp!<br/>Do mysle, citov, vôle srdca.<br/>Pane, všade vstúp! Pane, všade vstúp!<br/>Do mysle, citov, vôle srdca.<br/>',NULL,131285,3);
INSERT INTO stanza VALUES('SK3037','chorus','Príď, všade príď, dnes sa modlím:<br/>Ó, Pán Ježiš, teč, ako voda živá.<br/>Ó, Pán Ježiš, tryskaj, nech živý prameň<br/>prúdi z môjho vnútra! Amen.<br/>',NULL,131286,4);
INSERT INTO stanza VALUES('SK3037','3','Nech rieka tečie! Nech rieka tečie!<br/>Či volám spievam, či sa modlím.<br/>Nech rieka tečie! Nech rieka tečie!<br/>Či volám, spievam, či sa modlím.<br/>',NULL,131287,5);
INSERT INTO stanza VALUES('SK3037','chorus','Dnes, nech tečie! Dnes, nech tečie!<br/>Ó, Pán Ježiš, teč, ako voda živá.<br/>Ó, Pán Ježiš, tryskaj, nech živý prameň<br/>prúdi z môjho vnútra! Amen.<br/>',NULL,131288,6);
INSERT INTO stanza VALUES('SK3038','1','Ak si stratil čo ti patrí<br/>a cítiš sa utlačený,<br/>je tu pre teba milosť, ak uveríš.<br/>Je to veľmi jednoduché,<br/>Pán Ježiš je odpustenie,<br/>vykúpila ťa Jeho krv, prijmi Ho!<br/>',NULL,131289,1);
INSERT INTO stanza VALUES('SK3038','chorus','Dobrou správou je, že máš rok – milostivý!<br/>Hlásame evanjelium! Uveríš?<br/>Toto slovo očakávaš,<br/>dar, hodný oslavovania,<br/>čuj poľnicu povznesenia – buď voľný ....<br/>Z Pána sa tešiť, z milosti prehojnej,<br/>Len sa z Pána teš, z tej tváre žiarivej.<br/>Rok milostivý! Uveríš? buď voľný!<br/>Rok milostivý!<br/>',NULL,131290,2);
INSERT INTO stanza VALUES('SK3038','2','Kristovým slovom milosti,<br/>nie sú žiadne nedostatky,<br/>netráp sa, nesužuj sa, buď spokojný.<br/>V roku milostivom máme<br/>všetky dlhy vymazané,<br/>sme šťastní, radosť, extázu vnímame!<br/>',NULL,131291,3);
INSERT INTO stanza VALUES('SK3038','3','Ak Kristus uspokojuje<br/>a stále nás priťahuje,<br/>vtedy sa nám stal rokom milostivým.<br/>Všetko je uspokojivé,<br/>keď Kristus zaopatruje,<br/>v Jeho pláne bohatstvá nachádzame!<br/>',NULL,131292,4);
INSERT INTO stanza VALUES('SK3039','1','Noachov život zamenil obdobie,<br/>keď milosť Božiu našiel.<br/>Proti svetu stál, nebol vystrašený<br/>v arche potopou prešiel.<br/>',NULL,131293,1);
INSERT INTO stanza VALUES('SK3039','chorus','Si rozhodnutý byť víťazom živým,<br/>nehanbiť sa za Ježiša, milovať Ho všetkým,<br/>budeš jesť strom života,<br/>a piť vodu živú?<br/>Si rozhodnutý byť víťazom živým,<br/>opustiť svet a zasvätiť sa,<br/>aby si vek zmenil?<br/>Vydávam sa Tebe, ó, Pane, príď.<br/>',NULL,131294,2);
INSERT INTO stanza VALUES('SK3039','2','Mojžiš bol ten, ktorého Boh povolal,<br/>aby obdobie zmenil.<br/>Bol Božím druhom, bol pre pohyb Boží,<br/>bol tichý, múdry, verný.<br/>',NULL,131295,3);
INSERT INTO stanza VALUES('SK3039','3','Samuel slúžil Bohu, bol kňaz milý,<br/>Jemu celkom oddaný.<br/>Odovzdal sa, aby bol nazírejom,<br/>bez hriechu, sveta, živý.<br/>',NULL,131296,4);
INSERT INTO stanza VALUES('SK3039','4','Daniel jedol Božie slovo s priateľmi,<br/>od sveta oddelený.<br/>Modlili sa, boli s Bohom spojení,<br/>stáli za Jeho ľudí.<br/>',NULL,131297,5);
INSERT INTO stanza VALUES('SK3039','chorus','Som rozhodnutý byť víťazom živým,<br/>nehanbiť sa za Ježiša, milovať Ho všetkým,<br/>budem jesť strom života<br/>a piť vodu živú.<br/>Som rozhodnutý, byť víťazom živým,<br/>vidieť nebeskú víziu,<br/>nech môj duch stále horí!<br/>Pane, vydávam sa Ti vek zameniť.<br/>',NULL,131298,6);
INSERT INTO stanza VALUES('SK3040','1','Mocne vnímam, že máš, môj Pane drahý,<br/>veľkú túžbu, hlboko vo vnútri.<br/>Spoločníka, takého ako Ty mať,<br/>čo pozná Ťa a chce Ťa milovať.<br/>Stal si sa človekom takým ako ja,<br/>’by si vedel jak sa cítim, dosiahol ma.<br/>Cenu si zaplatil, slávu opustil,<br/>aby si získal ľudí, Svoju nevestu, už naveky.<br/>',NULL,131299,1);
INSERT INTO stanza VALUES('SK3040','chorus','Tak mi obnov srdce, nech ľúbim viac,<br/>obnov mi myseľ, nech znám Ťa viac,<br/>obnov mi silu, ’by žiť Ťa viac, ó, Pane.<br/>Nech som len v Tebe a Ty vo mne,<br/>žijeme stále spoločne, tešíme sa stále, vzájomne.<br/>Tomu obnova vravíme. To je Tvoje.<br/>',NULL,131300,2);
INSERT INTO stanza VALUES('SK3040','2','Pane, tiahni ma, tiahni aj ďalších,<br/>čo pôjdu za Tebou a nie za iným.<br/>Ó, nech dbáme na Tvoj život a cieľ,<br/>nech Ťa poznáme, máme, doplníme!<br/>Tvoja potreba je nadovšetko,<br/>lebo si „JA SOM“, si Stvoriteľom!<br/>Jediný, milovník a ženích drahý,<br/>uskutočni Svoj sen vo všetkých, ktorých získal si.<br/>',NULL,131301,3);
INSERT INTO stanza VALUES('SK3041','1','Musíme vidieť, že Boh chce byť vyjadrený,<br/>preto povieme: „Pane, rasti v nás!“<br/>Daj to srdce nám vravieť, že sme videli<br/>rok milostivý, aj zámer Boží, preto sa modlím…<br/>',NULL,131302,1);
INSERT INTO stanza VALUES('SK3041','chorus','Otvor im oči, obráť ich od tmy ku svetlu,<br/>obráť od autority Satana k Bohu.<br/>’By odpustenie hriechov prijali<br/>a to, čo Boh má, čo Boh vykonal a čo vykoná!<br/>',NULL,131303,2);
INSERT INTO stanza VALUES('SK3041','2','Pane Ježišu, večný život Tvoj hlásame,<br/>svietime všetkým, ’by uverili.<br/>Pane, zmocni nás hlásať rok milostivý,<br/>preto žijeme, svetlo dávame, prosiť budeme.<br/>',NULL,131304,3);
INSERT INTO stanza VALUES('SK3041','chorus','Otvor mi oči, obráť ma od tmy ku svetlu,<br/>obráť od autority Satana k Bohu.<br/>Aby som prijal odpustenie vín<br/>a to, čo Boh má, čo Boh vykonal a čo vykoná!<br/>',NULL,131305,4);
INSERT INTO stanza VALUES('SK3042','1','Jedli chlieb aj z rýb pri mori,<br/>jeho lásku Pán obnoví,<br/>nech už viac Peter nehorí<br/>ohňom svojím.<br/>Dopustil sa chýb ohromných,<br/>až trikrát zaprel pri ohni,<br/>spravil váhavými iných,<br/>Ježiš vraví...<br/>',NULL,131306,1);
INSERT INTO stanza VALUES('SK3042','chorus','Miluješ ma? Baránky moje sýť.<br/>Miluješ ma? Moje ovce pas.<br/>Miluješ ma?<br/>Tak daj mojim ovciam najesť.<br/>',NULL,131307,2);
INSERT INTO stanza VALUES('SK3042','2','Peter nie je sám, jediný,<br/>tiež sme pádmi oslabení,<br/>zlyhaním sme pokorení,<br/>takí slabí.<br/>V týchto chvíľach Pán vstupuje,<br/>hľadá lásku, sympatie,<br/>kto počúva, ten počuje<br/>že nám vraví...<br/>',NULL,131308,3);
INSERT INTO stanza VALUES('SK3042','chorus','Miluješ ma? Baránky moje sýť.<br/>Miluješ ma? Moje ovce pas.<br/>Miluješ ma?<br/>Tak daj mojim ovciam najesť<br/>',NULL,131309,4);
INSERT INTO stanza VALUES('SK3042','3','Dnes je Pán mnohým hatený,<br/>chýbajú ďalší pastieri,<br/>čo majú slová pre iných,<br/>pre stratených.<br/>Spolupráca je potrebná,<br/>aby pásol z nášho vnútra,<br/>budeš tým, kto sa otvára<br/>a povieš mu...<br/>',NULL,131310,5);
INSERT INTO stanza VALUES('SK3042','chorus','Milujem Ťa! Sýtiť budem ľudí!<br/>Milujem Ťa! Budem ľudí pásť.<br/>Milujem Ťa!<br/>Tak dám Tvojim ovciam najesť.<br/>',NULL,131311,6);
INSERT INTO stanza VALUES('SK3043','chorus','Pobozkám, pobozkám<br/>Syna, lebo ľúbi ma.<br/>Vždy teší Pôvabný,<br/>na drevo bol pribitý,<br/>zomrel za mňa, chráni ma,<br/>Jeho Ducha v sebe mám,<br/>Syna bozkám.<br/>',NULL,131312,1);
INSERT INTO stanza VALUES('SK3043','1','V dobrej zvesti Jeho Syna<br/>duchom slúžim zmiešaným<br/>tým, že prijímam Krista, Ducha<br/>On je sám Trojjediný.<br/>',NULL,131313,2);
INSERT INTO stanza VALUES('SK3043','chorus','Pobozkám, pobozkám<br/>Syna, lebo ľúbi ma.<br/>Vždy teší Pôvabný,<br/>na drevo bol pribitý,<br/>zomrel za mňa, chráni ma,<br/>Jeho Ducha v sebe mám,<br/>Syna bozkám.<br/>',NULL,131314,3);
INSERT INTO stanza VALUES('SK3043','2','Boha teší uctievanie,<br/>keď zakúšame Krista,<br/>uctievať a slúžiť v duchu,<br/>to od nás Otec žiada.<br/>',NULL,131315,4);
INSERT INTO stanza VALUES('SK3043','chorus','Pobozkám, pobozkám<br/>Syna, lebo ľúbi ma.<br/>Vždy teší Pôvabný,<br/>na drevo bol pribitý,<br/>zomrel za mňa, chráni ma,<br/>Jeho Ducha v sebe mám,<br/>Syna bozkám.<br/>',NULL,131316,5);
INSERT INTO stanza VALUES('SK3043','3','Kristu slúž, nech ťa pobozká,<br/>neodchádzaj od Neho.<br/>Ak ctíš Boha svojím žitím,<br/>slúžiš evanjeliom.<br/>',NULL,131317,6);
INSERT INTO stanza VALUES('SK3043','chorus','Pobozkám, pobozkám<br/>Syna, lebo ľúbi ma.<br/>Vždy teší Pôvabný,<br/>na drevo bol pribitý,<br/>zomrel za mňa, chráni ma,<br/>Jeho Ducha v sebe mám,<br/>Syna bozkám.<br/>',NULL,131318,7);
INSERT INTO stanza VALUES('SK3043','4','Slúžme Mu v Tele Kristovom,<br/>čo je z nás, v ňom nesmie byť.<br/>Smrťou Krista a vzkriesením,<br/>ctime Ho v skutočnosti.<br/>',NULL,131319,8);
INSERT INTO stanza VALUES('SK3043','chorus','Pobozkám, pobozkám<br/>Syna, lebo ľúbi ma.<br/>Vždy teší Pôvabný,<br/>na drevo bol pribitý,<br/>zomrel za mňa, chráni ma,<br/>Jeho Ducha v sebe mám,<br/>Syna bozkám.<br/>',NULL,131320,9);
INSERT INTO stanza VALUES('SK3044','1','Som pri rieke živej vody stromom zakoreneným.<br/>Prídu skúšky, avšak s koncom víťazným.<br/>Hoc na púšti, bez nádeje, na miestach vyschnutých,<br/>pri Pánovej rieke korene mám.<br/>Príde slnko horúce, moje lístie ostane,<br/>pri Pánovej rieke korene mám.<br/>',NULL,131321,1);
INSERT INTO stanza VALUES('SK3045','1','Ó, čo za zázrak, tajomstvo,<br/>Boh a človek sú zmiešaní!<br/>Boh sa stal človekom, aby<br/>človeka Bohom učinil.<br/>V nádhernej ekonómii<br/>tak cieľ dosiahol najvyšší.<br/>',NULL,131322,1);
INSERT INTO stanza VALUES('SK3045','2','Stal sa telom – Bohočlovekom,<br/>chce, aby som aj ja Boh bol.<br/>v živote, prirodzenosti,<br/>nie však Bohom v Božstve Jeho.<br/>Mne cnosti sú črty Jeho,<br/>žiari zo mňa obraz Jeho.<br/>',NULL,131323,2);
INSERT INTO stanza VALUES('SK3045','3','Nie som to ja, čo žije sám,<br/>no spolu s Bohom žijeme.<br/>V Trojjedinom budovaní<br/>spolu Mu domom budeme.<br/>Jeho Telom organickým<br/>vyjadríme Ho súhrnne.<br/>',NULL,131324,3);
INSERT INTO stanza VALUES('SK3045','4','Jeruzalem – dovŕšenie,<br/>všetkých vízií súhrnom.<br/>Trojjediný Boh s človekom –<br/>pár milujúci naveky,<br/>koinherujú navzájom,<br/>sú si príbytkom vzájomným.<br/>Božia sláva v ľuďoch mnohých<br/>žiari v nádhere skrze nich!<br/>',NULL,131325,4);
INSERT INTO stanza VALUES('SK3046','1','Na počiatku Boh umiestnil<br/>človeka pred rozdielne dva stromy –<br/>Strom života a strom poznania<br/>dobrého a zlého.<br/>Jeden do života vedie,<br/>druhý do smrti, hriechu privedie.<br/>Nuž Krista jedz! Len si nepovedz:<br/>„Všetko viem, som dobrý.“<br/>',NULL,131326,1);
INSERT INTO stanza VALUES('SK3046','chorus','Pán je Strom života. Život nám dodá.<br/>Voľ cestu života! Jedzme Ho, tešme sa z Neho!<br/>Z hĺbky sa otvor. Na Ňom buď závislý.<br/>(Strom života jedz!)<br/>',NULL,131327,2);
INSERT INTO stanza VALUES('SK3046','2','Môžeme sa z Neho tešiť!<br/>Otvoriť sa, po okraj sa plniť!<br/>Jedzme Krista, je Strom života.<br/>Nech je vyjadrený.<br/>V srdci Mu dajme prvenstvo.<br/>Dáva sa, zatiaľ čo ľúbime Ho.<br/>Nášho ducha večne naplní!<br/>Budeme spokojní!<br/>',NULL,131328,3);
INSERT INTO stanza VALUES('SK3047','1','Po rozbúrených vodách,<br/>sa tmavou nocou plavím,<br/>som beznádejný a sám,<br/>len veľké vlny vidím.<br/>V tom sa človek zjaví,<br/>ja naň hľadím,<br/>po vlnách si kráča,<br/>blíži sa ku mne, hovorí:<br/>',NULL,131329,1);
INSERT INTO stanza VALUES('SK3047','chorus','„Neboj sa. Neboj sa.<br/>Veď som to Ja.<br/>More viem ukľudniť,<br/>dovoľ mi vstúpiť.<br/>V tebe prístavom budem,<br/>ochránim ťa.<br/>Len mi otvor srdce,<br/>som Tá cesta.“<br/>',NULL,131330,2);
INSERT INTO stanza VALUES('SK3047','2','Cítim sa obkľúčený,<br/>všetkým súžením čo mám.<br/>Každý bôľ, problém, či spor,<br/>o pokoj ma oberá.<br/>So smútkom zápasím vyčerpaný.<br/>Vari nie je nik, kto ma tohto zbaví?<br/>Pán vraví:<br/>',NULL,131331,3);
INSERT INTO stanza VALUES('SK3047','chorus','„Neboj sa. Neboj sa.<br/>Veď som to Ja.<br/>More viem ukľudniť,<br/>dovoľ mi vstúpiť.<br/>V tebe prístavom budem,<br/>ochránim ťa.<br/>Len mi otvor srdce,<br/>som Tá cesta.“<br/>',NULL,131332,4);
INSERT INTO stanza VALUES('SK3047','3','Ježiš je Synom Božím,<br/>človekom je súcitným.<br/>Bol na kríž položený,<br/>odniesol tvoje hriechy.<br/>Život si podmaní silu smrti.<br/>Boľavé srdce Mu stíšiť dovolíš?<br/>On povie:<br/>',NULL,131333,5);
INSERT INTO stanza VALUES('SK3047','chorus','„Neboj sa. Neboj sa.<br/>Veď som to Ja.<br/>Len mi ver!<br/>Volaj Ma, zachránim ťa!<br/>Ó, Pán Ježiš,<br/>Teba dnes potrebujem,<br/>otváram Ti srdce,<br/>Zostaň vo mne.<br/>',NULL,131334,6);
INSERT INTO stanza VALUES('SK3048','1','Pán Ježiš slobodu dal<br/>každému, kto Ho prijal.<br/>Vrátil nám slobodu.<br/>Príď! Vráť sa k Ježišovi.<br/>Ponúka život, vezmi!<br/>Vzývaj Pána, buď s Ním.<br/>',NULL,131335,1);
INSERT INTO stanza VALUES('SK3048','chorus','Toto je rok milostivý!<br/>Slobodu máme v Pánovi!<br/>Celej zemi hlásame:<br/>Ó, vrátili sa otroci,<br/>od námahy, od hriechu sú voľní!<br/>Toto je rok milostivý!<br/>',NULL,131336,2);
INSERT INTO stanza VALUES('SK3048','2','Žiadajme späť svoj podiel,<br/>naším vlastníctvom Boh je.<br/>Sýť sa Ním, hoduj s Ním!<br/>Teš sa v rodine Božej,<br/>nájdeš uspokojenie.<br/>Stále s Ním, naveky!<br/>',NULL,131337,3);
INSERT INTO stanza VALUES('SK3049','1','Ó, Duch, čo je v slove,<br/>je Boh vyjadrený.<br/>Kristus prelievaný,<br/>Duchom odovzdaný<br/>Len Ho vdychujme...<br/>',NULL,131338,1);
INSERT INTO stanza VALUES('SK3049','chorus','Božie Slovo!<br/>Môj duch dýcha,<br/>Tvoj Duch a život<br/>ma sýtia naveky,<br/>Bohočlovekom ma činia.<br/>',NULL,131339,2);
INSERT INTO stanza VALUES('SK3049','2','Vydýchol písmo Boh,<br/>ja vdýchnuť ho musím.<br/>Prijmem odhalenie,<br/>vnútri ma usvedčí.<br/>Také zjavenie...<br/>',NULL,131340,3);
INSERT INTO stanza VALUES('SK3049','3','Závoj spadne z očí,<br/>sám sebe sa zhnusím.<br/>Odhalený vyznám,<br/>že som pokrivený.<br/>Obmýva ma krv...<br/>',NULL,131341,4);
INSERT INTO stanza VALUES('SK3049','4','Napraví, obnoví,<br/>zjavenie vyrovná,<br/>ó, spravodlivosti<br/>sladké ovocie dá.<br/>Pán vyžaruje...<br/>',NULL,131342,5);
INSERT INTO stanza VALUES('SK3049','5','Zo slova Kristovho<br/>svetlom poučený,<br/>prebudovávaný,<br/>v srdci obnovený.<br/>V ňom si dom činí...<br/>',NULL,131343,6);
INSERT INTO stanza VALUES('SK3049','6','Ó, meč Ducha živý,<br/>na mňa uplatnený.<br/>prenikaj, rozdeľuj<br/>ducha od duše mi.<br/>Aby som Ťa žil...<br/>',NULL,131344,7);
INSERT INTO stanza VALUES('SK3049','7','Ber slovo modlitbou,<br/>Duch v slove pôsobí,<br/>ego, padlé telo,<br/>Duch slovom ukončí.<br/>Kráčaj v novote...<br/>',NULL,131345,8);
INSERT INTO stanza VALUES('SK3049','8','Ó, dnes ma vyživuj,<br/>môj dych a chlieb živý.<br/>Pane, cezo mňa ži,<br/>pre Svoj návrat skorý!<br/>Ó, príď Ježišu...<br/>',NULL,131346,9);
INSERT INTO stanza VALUES('GK1','1','Έχω γλυκό Σωτήρα και Φίλο στη ζωή<br/>που πέθανε για μένα μα τώρα πάλι ζει<br/>Ο κόσμος δεν γνωρίζει και δεν μπορεί να δει<br/>μα εγώ κοντά Τον έχω κάθε στιγμή<br/>',NULL,187694,1);
INSERT INTO stanza VALUES('GK1','chorus','Ναι ζει! Ναι ζει! Ο Ιησούς μου ζει<br/>και μου μιλά και περπατά μαζί μου στη ζωή<br/>Ω ζει, ναι ζει, και δεν θα χωριστεί<br/>ποτέ από κοντά μου πια — ζει μέσα στην καρδιά<br/>',NULL,187695,2);
INSERT INTO stanza VALUES('GK1','2','Οι θησαυροί του κόσμου για πάντα θα χαθούν<br/>κι εκείνοι που τους έχουν φτωχοί θε να βρεθούν<br/>μα εγώ το Θησαυρό μου που ’χω δικό μου πια<br/>θα Τον απολαμβάνω παντοτινά<br/>',NULL,187696,3);
INSERT INTO stanza VALUES('GK1','3','Της δόξας η ελπίδα — εντός μου ο Χριστός<br/>Δεν ζω εγώ πια τώρα, για μένα ζει Αυτός<br/>Χαρές του κόσμου τούτου, σκιές μπροστά στο φως<br/>ζωή για μένα είναι μόνο ο Χριστός<br/>',NULL,187697,4);
INSERT INTO stanza VALUES('GK2','1','Ω Κύριε, είσαι η ζωή<br/>τα πάντα είσαι Εσύ<br/>Οικείος και διαθέσιμος<br/>απολαμβάνω Σε<br/>',NULL,187698,1);
INSERT INTO stanza VALUES('GK2','chorus','Ω Κύριε, είσαι το Πνεύμα<br/>γλυκός και αγαπητός<br/>Κοντά μου είσαι πάντοτε<br/>διαθέσιμος για με<br/>',NULL,187699,2);
INSERT INTO stanza VALUES('GK2','2','Την κάθε μια ανάγκη μου<br/>Εσύ την εκπληρείς<br/>Με επάρκεια κι ετοιμότητα<br/>ζητώ και απαντείς<br/>',NULL,187700,3);
INSERT INTO stanza VALUES('GK2','3','Το χρίσμα Σου και η ισχύς<br/>με κάνουν στερεό<br/>Με τη δική Σου ενέργεια<br/>με κάνεις δυνατό<br/>',NULL,187701,4);
INSERT INTO stanza VALUES('GK2','4','Ο νόμος Πνεύματος ζωής<br/>με ελευθέρωσε<br/>Ο πλούτος της αλήθειας Σου<br/>με διαπότισε<br/>',NULL,187702,5);
INSERT INTO stanza VALUES('GK2','5','Μαζί μου είσαι πάντοτε<br/>Ω, τι ενότητα!<br/>Είμ’ ένα πνεύμα με Εσέ<br/>για την αιωνιότητα<br/>',NULL,187703,6);
INSERT INTO stanza VALUES('GK3','1','Θαυμαστή αλλαγή που ’χω μες στη ζωή<br/>γιατί ήρθε ο Χριστός στην καρδιά!<br/>Έχω φως στην ψυχή που ποθούσα πολύ<br/>γιατί ήρθε ο Χριστός στην καρδιά!<br/>',NULL,187704,1);
INSERT INTO stanza VALUES('GK3','chorus','Ω! Ήρθε ο Χριστός στην καρδιά!<br/>Ναι! Ήρθε ο Χριστός στην καρδιά!<br/>Πλημμυρίζει η ψυχή με χαρά θεϊκή<br/>γιατί ήρθε ο Χριστός στην καρδιά!<br/>',NULL,187705,2);
INSERT INTO stanza VALUES('GK3','2','Έπαψα πια να ψάχνω αλήθεια να βρω<br/>γιατί ήρθε ο Χριστός στην καρδιά!<br/>Κι οι πολλές αμαρτίες μου πάν’ στο βυθό<br/>γιατί ήρθε ο Χριστός στην καρδιά!<br/>',NULL,187706,3);
INSERT INTO stanza VALUES('GK3','3','Με γεμίζει ελπίδα γλυκιά, σταθερή<br/>γιατί ήρθε ο Χριστός στην καρδιά!<br/>Φόβοι κι αμφιβολίες έχουν διαλυθεί<br/>γιατί ήρθε ο Χριστός στην καρδιά!<br/>',NULL,187707,4);
INSERT INTO stanza VALUES('GK3','4','Έχω φως την κοιλάδα σκιάς να διαβώ<br/>γιατί ήρθε ο Χριστός στην καρδιά!<br/>Με χαρά κι αγαλλίαση μπρος προχωρώ<br/>γιατί ήρθε ο Χριστός στην καρδιά!<br/>',NULL,187708,5);
INSERT INTO stanza VALUES('GK3','5','Στην ουράνια πόλη κι εγώ θα βρεθώ<br/>γιατί ήρθε ο Χριστός στην καρδιά!<br/>Τις κατάλαμπρες πύλες κοντά πια θωρώ<br/>γιατί ήρθε ο Χριστός στην καρδιά!<br/>',NULL,187709,6);
INSERT INTO stanza VALUES('GK4','1','Βράχε αιώνιε, δυνατέ<br/>Συ που σκίστηκες για με<br/>στη σχισμή Σου θα κρυφτώ<br/>ο αμαρτωλός εγώ<br/>να ξεφύγω απ’ την οργή<br/>κι απ’ την κάθε ενοχή<br/>',NULL,187710,1);
INSERT INTO stanza VALUES('GK4','2','Τίποτα δεν κουβαλώ<br/>μες στα χέρια μου τα δύο<br/>Με τα μάτια χαμηλά<br/>και με δάκρυα ταπεινά<br/>στο σταυρό Σου ακουμπώ<br/>και Εσένα αποζητώ<br/>',NULL,187711,2);
INSERT INTO stanza VALUES('GK4','3','Αίμα βλέπω και νερό<br/>να κυλούν απ’ το πλευρό<br/>ράντισέ με Συ μ’ αυτά<br/>της καρδιάς μου Βασιλιά<br/>Ξέπλυνέ με εντελώς<br/>μπρος Σου να ’μαι καθαρός<br/>',NULL,187712,3);
INSERT INTO stanza VALUES('GK4','4','Όσο είμαι με πνοή<br/>μα και στη στερνή στιγμή<br/>και στο θρόνο σαν Σε δω<br/>σ’ άλλο κόσμο φωτεινό<br/>πάντοτε μέσα σ’ Εσέ<br/>θα ’μαι, Βράχε δυνατέ<br/>',NULL,187713,4);
INSERT INTO stanza VALUES('GK5','1','Πληθαίνει τη χάρη Του για τα φορτία<br/>Και τη δύναμή Του στις ταλαιπωρίες<br/>Στις θλίψεις μας έχουμε το έλεός Του<br/>Ειρήνη μας δίνει στις δοκιμασίες<br/>',NULL,187714,1);
INSERT INTO stanza VALUES('GK5','chorus','Απέραντη αγάπη! Αμέτρητη χάρη!<br/>Η ισχύς Του δεν έχει ποτέ όρια<br/>Και απ’ του Ιησού τα αστείρευτα πλούτη<br/>Μας δίνει, μας δίνει, ξανά και ξανά<br/>',NULL,187715,2);
INSERT INTO stanza VALUES('GK5','2','Και όταν δεν έχουμε άλλες δυνάμεις<br/>Και η αντοχή μας δεν είν’ αρκετή<br/>Και τα αποθέματα έχουν τελειώσει<br/>Γι’ Αυτόν, τον Πατέρα, είν’ μόνο αρχή<br/>',NULL,187716,3);
INSERT INTO stanza VALUES('GK6','1','Δέσμιος από την ομορφιά Σου<br/>Σου ανοίγω Κύριε την καρδιά<br/>Λεύτερος απ’ όλα—τ’ όνομά Σου<br/>είναι πλούτος, είναι λευτεριά<br/>Καθώς Σ’ ατενίζω μες στη δόξα<br/>έκθαμβος στη θεία ομορφιά<br/>δώσ’ μου να χορτάσω απ’ τη ζωή Σου<br/>γέμισε το πνεύμα μου βαθιά<br/>',NULL,187717,1);
INSERT INTO stanza VALUES('GK6','2','Γιε ανθρώπου—ανοιχτά τα ουράνια<br/>Συ στο θρόνο πάνω κυβερνάς<br/>πλύνε με, καθάρισέ με πλέρια<br/>γίνε μέσα μου ο βασιλιάς<br/>Όταν Σε πρωτόδα μες στη δόξα<br/>έλιωσαν του εγώ μου τα δεσμά<br/>με λατρεία η καρδιά μου τώρα<br/>τ’ όνομά Σου γεύεται γλυκά<br/>',NULL,187718,2);
INSERT INTO stanza VALUES('GK6','3','Κύριε, για Σε τ’ αλαβαστρό μου<br/>σπάω με αγάπη και χαρά<br/>χύνω πάνω Σου τον εαυτό μου<br/>κι όλα που κρατάω ακριβά<br/>Τίποτα άλλο πια, καμιά αξία<br/>δεν μετρά μπρος στον Κατακτητή<br/>στη δική Σου μόνο παρουσία<br/>είναι η χαρά η αληθινή<br/>',NULL,187719,3);
INSERT INTO stanza VALUES('GK6','4','Λαχταρώ να έρθεις Κύριέ μου<br/>να Σε δω, μπροστά Σου να σταθώ<br/>Λυτρωτή, Αφέντη μου, Χριστέ μου<br/>στην αγκάλη Σου ν’ αναπαυθώ<br/>Κύριε, δεν Σε προσμένω μόνος<br/>αλλά μ’ όλους μου τους αδελφούς<br/>νύφη ποθητή, ετοιμασμένη<br/>να μας παραλάβεις καθαρούς<br/>',NULL,187720,4);
INSERT INTO stanza VALUES('GK7','1','Το πιο ένδοξο όνομα, τ’ όνομα του Ιησού<br/>είν’ το πιο ψηλό από κάθε όνομα<br/>Καθώς το φωνάζουμε<br/>σκότος και θάνατος σκορπούν<br/>διότι έρχεται ο ίδιος ο Ιησούς<br/>Με τη γλώσσα μας, Ιησού, ομολογούμε Εσένα—<br/>είσαι Κύριος προς δόξα του Θεού Πατρός<br/>Το να Σε δοξάζουμε<br/>είν’ καθημερινή χαρά<br/>Ω Ιησού, είσαι ο Αγαπημένος μας<br/>',NULL,187721,1);
INSERT INTO stanza VALUES('GK8','1','Σταυρωμένος για τον κόσμο<br/>και με τον Χριστό μαζί<br/>σε ζωή αναστημένη<br/>έρχομαι γλυκά εκεί<br/>μες στο θάνατο και πόνο<br/>του δικού μου Λυτρωτή<br/>παραδίδω μια για πάντα<br/>τη ζωή μου τη μικρή<br/>',NULL,187722,1);
INSERT INTO stanza VALUES('GK8','chorus','Στο σταυρό του Γολγοθά<br/>στη θυσία του Αμνού<br/>κράτα με παντοτινά<br/>στο σταυρό του Γολγοθά<br/>',NULL,187723,2);
INSERT INTO stanza VALUES('GK8','2','Και τις θλίψεις του Χριστού μας<br/>να συμμεριστείς μπορείς<br/>όταν την καρδιά γεμίζει<br/>η χαρά Του η θαυμαστή<br/>και με την ανάστασή Του<br/>κατασκήνωσε σε με<br/>με καρδιά γαληνεμένη<br/>πλησιάζω εγώ σε Σε<br/>',NULL,187724,3);
INSERT INTO stanza VALUES('GK8','3','Αν πεθαίνω κι υποφέρω<br/>με τον Κύριο θα ζω<br/>και της δόξας το στεφάνι<br/>θα μπορέσω να φορώ<br/>πόσο όμορφη θα είναι<br/>του Κυρίου η λαλιά<br/>«Έλα και εσύ μαζί Μου<br/>στο σταυρό του Γολγοθά»<br/>',NULL,187725,4);
INSERT INTO stanza VALUES('GK9','1','Πρόθυμα ναι, παραδίνω τη ζωή μου στον Χριστό<br/>Όλα πίσω μου τα αφήνω και γι’ Αυτόν θέλω να ζω<br/>',NULL,187726,1);
INSERT INTO stanza VALUES('GK9','chorus','Παραδίνομαι, Ιησού Χριστέ<br/>Όπως είμαι ναι σ’ Εσένα παραδίνομαι<br/>',NULL,187727,2);
INSERT INTO stanza VALUES('GK9','2','Ιησού μου παραδίνω όλα ταπεινά σε Σε<br/>Τη ζωή του κόσμου αφήνω για να ζήσω πια για Σε<br/>',NULL,187728,3);
INSERT INTO stanza VALUES('GK9','3','Παραδίνομαι, Χριστέ μου, εις Εσένα εντελώς<br/>Πλήρωσέ με με το Πνεύμα να μην νιώθω αδειανός<br/>',NULL,187729,4);
INSERT INTO stanza VALUES('GK9','4','Σαν θυσία Σου προσφέρω ό,τι έχω στη ζωή<br/>Την καρδιά μου Σου τη δίνω, σώμα, πνεύμα και ψυχή<br/>',NULL,187730,5);
INSERT INTO stanza VALUES('GK10','1','Τι μεγάλος που ’σαι Φίλος, Κύριέ μας Ιησού<br/>Ο γλυκός Σου χαρακτήρας λάμπει μες στο Λόγο Σου<br/>Άλλος σαν Εσέ κανένας και σε θλίψεις και χαρές<br/>Μένεις πάντοτε κοντά μας, ίδιος σήμερα και χτες<br/>',NULL,187731,1);
INSERT INTO stanza VALUES('GK10','2','Όταν φίλοι μας προδίδουν πάντα στέκεσαι πιστός<br/>Όταν πειρασμοί μας θλίβουν είσαι μπρος μας δυνατός<br/>Όταν λύπες συννεφιάζουν της ψυχής τον ουρανό<br/>Έχουμε Εσένα που ’σαι φρούριό μας ισχυρό<br/>',NULL,187732,2);
INSERT INTO stanza VALUES('GK10','3','Όταν της ζωής τα βάρη φέρνουμε με προσευχή<br/>Τα σηκώνεις κι η μορφή Σου χάρη ακτινοβολεί<br/>Όλες μας τις αμαρτίες τις φορτώθηκες, Χριστέ<br/>Πάντα θα Σ’ ευγνωμονούμε, Ιησού μας λατρευτέ<br/>',NULL,187733,3);
INSERT INTO stanza VALUES('GK11','1','Σε υμνώ με το πνεύμα μου, Κύριε<br/>Σε υμνώ βαθιά μες στην καρδιά<br/>Σε υμνώ αλληλούια, Χριστέ μου<br/>Ενωμένοι στο πνεύμα βαθιά<br/>',NULL,187734,1);
INSERT INTO stanza VALUES('GK11','2','Χρόνια ζήσαμε μες στη θρησκεία<br/>Χρόνια ζήσαμε μες στο μυαλό<br/>Συναισθήματα μας κυριαρχούσαν<br/>Και δεν βρήκαμε καν το σωστό<br/>',NULL,187735,2);
INSERT INTO stanza VALUES('GK11','3','Τώρα όμως γυρνάμε στο πνεύμα<br/>Και γεμίζει ζωή η καρδιά<br/>Τώρα τρεφόμαστε με τον Κύριο<br/>Και γευόμαστε τη λευτεριά<br/>',NULL,187736,3);
INSERT INTO stanza VALUES('GK11','4','Αλληλούια ζωή μες στο Πνεύμα<br/>Αλληλούια ζωή εν Χριστώ<br/>Όταν στρεφόμαστε εις το πνεύμα<br/>Βρίσκουμε πάντοτε τον Χριστό<br/>',NULL,187737,4);
INSERT INTO stanza VALUES('GK12','1','Κύριε, Σ’ αγαπώ<br/>Δεν υπάρχει άλλος σαν Εσέ<br/>Σε όλο το σύμπαν<br/>Δεν έχω κανέναν σαν Εσέ<br/>Ω Κύριε, Σ’ αγαπώ<br/>',NULL,187738,1);
INSERT INTO stanza VALUES('GK13','1','Ιησού μου, ναι είσαι ο πιο γλυκός του κόσμου<br/>Και δεν υπάρχει άλλος που θέλω σαν Εσέ<br/>Ιησού μου, ναι είσαι ο πιο όμορφος απ’ όλους<br/>Υπέροχος κι ωραίος και δεν συγκρίνεσαι<br/>',NULL,187739,1);
INSERT INTO stanza VALUES('GK13','2','Όταν Σε βλέπω Κύριε, που έλκεις την καρδιά μου<br/>Βαθιά στην αγκαλιά Σου μπορώ ν’ αναπαυθώ<br/>Πώς χάνεται ο χρόνος και τίποτα δεν μένει<br/>Το πρόσωπό Σου μόνο, λαμπρό και λατρευτό<br/>',NULL,187740,2);
INSERT INTO stanza VALUES('GK13','3','Σου δίνω τη ζωή μου, Εσύ μονάχα αξίζεις<br/>Η κάθε μέρα είναι δικιά Σου, Κύριε<br/>Σου δίνω την καρδιά μου να Σ’ αγαπάει για πάντα<br/>Να Σε υπηρετεί με—τη χάρη Σου, Χριστέ<br/>',NULL,187741,3);
INSERT INTO stanza VALUES('GK14','1','Ένα ποτάμι στην Εδέμ<br/>Και ένα δέντρο είναι κει<br/>Ο άνθρωπος παντοτινά<br/>να ’χει νερό, τροφή<br/>',NULL,187742,1);
INSERT INTO stanza VALUES('GK14','chorus','Έχω τα πάντα με τον Χριστό<br/>Με τ’ Άγιο Πνεύμα πώς ξεδιψώ<br/>Έτσι ο Θεός μού δίνει ζωή<br/>ζωή μες στον Χριστό<br/>',NULL,187743,2);
INSERT INTO stanza VALUES('GK14','2','Το δέντρο είναι ο Χριστός<br/>Δίνει τροφή στο Χριστιανό<br/>Για να ’χει του Θεού χαρά<br/>και όλα τ’ αγαθά<br/>',NULL,187744,3);
INSERT INTO stanza VALUES('GK14','3','Το Πνεύμα είν’ ο ποταμός<br/>Που τους ανθρώπους ξεδιψά<br/>Άγιοι να ’ναι αληθινά<br/>πλούσιοι πνευματικά<br/>',NULL,187745,4);
INSERT INTO stanza VALUES('GK14','4','Είν’ η ζωή μου ο Χριστός<br/>Ζει ως το Πνεύμα μέσα μου<br/>Για να ’μαι ένα με Αυτόν<br/>και να ακτινοβολώ<br/>',NULL,187746,5);
INSERT INTO stanza VALUES('GK14','5','Θα εξυψώνω τον Χριστό<br/>Στο Πνεύμα θα υποταχτώ<br/>Να γίνει η δόξα Του γνωστή<br/>κι η χάρη Του στη γη<br/>',NULL,187747,6);
INSERT INTO stanza VALUES('GK15','1','Ω, τι ζωή! Τι ειρήνη!<br/>Που μέσα μου ζει ο Χριστός<br/>Μαζί Του συσταυρώθηκα<br/>Τι δοξασμένο γεγονός!<br/>Και τώρα πια δεν ζω εγώ<br/>Μα μέσα μου ζει ο Χριστός<br/>',NULL,187748,1);
INSERT INTO stanza VALUES('GK15','2','Ω, τι χαρά! Τι ανάπαυση!<br/>Σε με μορφώνεται ο Χριστός<br/>Με θεία φύση και ζωή<br/>Με διαποτίζει συνεχώς<br/>Όλο το είναι έσβησε<br/>σφυρηλατήθηκε Αυτός<br/>',NULL,187749,2);
INSERT INTO stanza VALUES('GK15','3','Ω, τι δόξα! Τι καύχημα!<br/>Θα μεγαλύνεται ο Χριστός<br/>Για τίποτα δεν θα ντραπώ<br/>Μα το να ζω είναι Χριστός<br/>Στο θάνατο ή στη ζωή<br/>Θα εκδηλώνεται Αυτός<br/>',NULL,187750,3);
INSERT INTO stanza VALUES('GK15','4','Ω, τι κέρδος! Τι θησαυρός!<br/>Χριστός ο μόνος μου σκοπός<br/>Ό,τι πολύτιμο θέλω<br/>Το περιέχει ο Χριστός<br/>Ελπίδα, δόξα και τιμή<br/>Χριστός ο απαράμιλλος<br/>',NULL,187751,4);
INSERT INTO stanza VALUES('GK16','1','Την πλάτη έχω στρέψει πια στον μάταιο τον κόσμο<br/>και έχω βάλει στην καρδιά ουράνιο, άγιο, στόχο<br/>Το λούστρο κι η αναλαμπή δεν φτάνουν την καρδιά μου<br/>πέρασα Θάλασσα Ερυθρά, τα άφησα μακριά μου<br/>',NULL,187752,1);
INSERT INTO stanza VALUES('GK16','chorus','Πίσω, μακριά μου! Πίσω, μακριά μου!<br/>Τον κόσμο τον ξεπέρασα, τον άφησα μακριά μου<br/>',NULL,187753,2);
INSERT INTO stanza VALUES('GK16','2','Άφησα και τη θλιβερή ζωή της αμαρτίας<br/>δεν θα βαδίζω άλλο πια σ’ οδούς ανοησίας<br/>Μέσα στον δρόμο του Χριστού ο κόσμος θα με βρίσκει<br/>πέθανα κι αναστήθηκα και η ζωή μου ανήκει<br/>',NULL,187754,3);
INSERT INTO stanza VALUES('GK16','3','Άλλο πια δεν επιθυμώ αυτά που είχα πρώτα<br/>έχω ειρήνη αληθινή, ξεκούραση αιώνια<br/>Καινούργιο έχω Κύριο—τον άλλον τον αφήκα—<br/>Το όνομά Του Ιησούς, ο Θησαυρός που βρήκα<br/>',NULL,187755,4);
INSERT INTO stanza VALUES('GK16','4','Για πάντα τούτη η εκλογή, δεν θα γυρίσω πίσω<br/>δεν θέλω άλλο λυτρωτή, με τον Χριστό θα ζήσω<br/>Του κόσμου πίσω με καλεί η μάταιη φωνή του<br/>μα ο Χριστός μου με κρατά και θα διαβώ μαζί Του<br/>',NULL,187756,5);
INSERT INTO stanza VALUES('GK17','1','Μυστήριο! Πατέρας, Υιός και Πνεύμα<br/>Πρόσωπα τρία, μα Ένας ο Θεός<br/>Τι θαυμαστό! Οι Τρεις να είναι Ένας<br/>Να ’ναι το παν για μας εν τω Χριστώ<br/>',NULL,187757,1);
INSERT INTO stanza VALUES('GK17','chorus','Τριαδικός είν’ ο Θεός σε μας<br/>Τι υπέροχο! Τι όμορφο!<br/>Το δώρο αυτό είν’ ανεξάντλητο<br/>Θαυμάσιο! Υπέροχο!<br/>',NULL,187758,2);
INSERT INTO stanza VALUES('GK17','2','Τι πλούσια πηγή είν’ ο Πατέρας<br/>Τον πλούτο Του μας δίνει απλόχερα<br/>Είναι ευλογία, το μερίδιο μας<br/>Ν’ απολαμβάνουμε παντοτινά<br/>',NULL,187759,3);
INSERT INTO stanza VALUES('GK17','3','Τώρα ο Υιός εκφράζει τον Πατέρα<br/>Με σάρκα εδώ περπάτησε στη γη<br/>Μας λύτρωσε ώστε να ενωθούμε<br/>Με τον Θεό εμείς οι αμαρτωλοί<br/>',NULL,187760,4);
INSERT INTO stanza VALUES('GK17','4','Μεταμορφώθηκε ο Υιός σε Πνεύμα<br/>Και έτσι αναγεννηθήκαμε<br/>Το Πνεύμα Του με το δικό μας πνεύμα<br/>Συμμαρτυρεί πως ενωθήκαμε<br/>',NULL,187761,5);
INSERT INTO stanza VALUES('GK17','5','Αληθινά Θεός είναι το Πνεύμα<br/>Είν’ η ζωή μας καθημερινά<br/>Εκπληκτικό! Είμαστε ένα Πνεύμα<br/>Και δεν υπάρχει διάκριση καμιά<br/>',NULL,187762,6);
INSERT INTO stanza VALUES('GK18','1','Όλα τα έχει αυτή η γη που λέγεται Ιησούς<br/>Με αναβλύζοντα νερά, ρυάκια και ποταμούς<br/>Από κοιλάδες και βουνά ρέουν τα άφθονα νερά<br/>Και πίνουμε—γεμίζουμε, τι δόξα!<br/>',NULL,187763,1);
INSERT INTO stanza VALUES('GK18','2','Τώρα σιτάρι είν’ ο Ιησούς. Η σάρκα πέθανε<br/>Μα αναστήθηκε Αυτός, κριθάρι έγινε<br/>Γη με αμπέλια και συκιές, κρασί που ευφραίνει τις καρδιές<br/>Έχουμε ’μείς—όλης της γης τις χαρές!<br/>',NULL,187764,2);
INSERT INTO stanza VALUES('GK18','3','Ω, τι πολλά, τι άφθονα τα πλούτη του Χριστού<br/>Είν’ η ροδιά και η ελιά. Μας χρίζει το λάδι Του<br/>Γάλα και μέλι είν’ Αυτός, τόσο γλυκός και θρεπτικός<br/>Τέτοια τροφή—τόσο καλή. Τι Χριστός!<br/>',NULL,187765,3);
INSERT INTO stanza VALUES('GK18','4','Στη γη αυτή τρώμε ψωμί. Δεν έχει έλλειψη<br/>Όλα μας τα παρέχει Αυτός. Ω, τι απόλαυση!<br/>Είναι μια γη πελώρια, με όλα τα εφόδια<br/>Απλώνεται—αυξάνεται—στην καρδιά!<br/>',NULL,187766,4);
INSERT INTO stanza VALUES('GK18','5','Αν σκάψουμε στα βάθη της, λίθους και σίδηρο<br/>Θα βρούμε για τα όπλα μας, ενάντια στον εχθρό<br/>Τότε δοκιμαζόμαστε και επεξεργαζόμαστε<br/>Σαν το χαλκό, το σίδηρο θα ’μαστε!<br/>',NULL,187767,5);
INSERT INTO stanza VALUES('GK18','6','Σε ευλογούμε, Κύριε, γι’ αυτήν την πλούσια γη<br/>Χορτάσαμε—ναι, φάγαμε! Ήπιαμε απ’ την πηγή!<br/>Να εργαζόμαστε στη γη. Μάθε μας, Κύριε, Εσύ<br/>Να ’ναι αυτός—για μας σκοπός στη ζωή!<br/>',NULL,187768,6);
INSERT INTO stanza VALUES('GK19','1','Κύριε, σαν Σε σκεφτόμαστε<br/>Με δέος Σε λατρεύουμε<br/>Είσ’ ό,τι πιο πολύτιμο<br/>Μονάκριβο και ιερό<br/>',NULL,187769,1);
INSERT INTO stanza VALUES('GK19','chorus','Αυτό που είσαι μας πληροί<br/>Γι’ αυτό η καρδιά μας Σε υμνεί<br/>Όλους τους πόθους της ψυχής<br/>Εσύ τους ικανοποιείς<br/>',NULL,187770,2);
INSERT INTO stanza VALUES('GK19','2','Εν αληθεία ’σαι Θεός<br/>Θεός αγάπης και φωτός<br/>Είσαι πηγή ζωής για μας<br/>Θεός ατέλειωτης χαράς<br/>',NULL,187771,3);
INSERT INTO stanza VALUES('GK19','3','Είσαι και άνθρωπος απλός<br/>Τόσο καλός, τόσο αγνός<br/>Και στον Θεό ευάρεστος<br/>Σε μας τόσο αγαπητός<br/>',NULL,187772,4);
INSERT INTO stanza VALUES('GK19','4','Είσαι και δούλος ταπεινός<br/>Για μας Σε έστειλε ο Θεός<br/>Υπάκουος ως το σταυρό<br/>Να λυτρωθούμε εμείς εδώ<br/>',NULL,187773,5);
INSERT INTO stanza VALUES('GK19','5','Εν τούτοις είσαι Βασιλιάς<br/>Μες στη ζωή μας κυβερνάς<br/>Και του Θεού τη δύναμη<br/>Μοιράζεσαι με μας στη γη<br/>',NULL,187774,6);
INSERT INTO stanza VALUES('GK19','6','Κύριε, σαν Σε θυμόμαστε<br/>Με Σένα ενωνόμαστε<br/>Το θαύμα της αγάπης Σου<br/>Απολαμβάνει η νύφη Σου<br/>',NULL,187775,7);
INSERT INTO stanza VALUES('GK20','1','Πόσο γλυκό ακούγεται<br/>Το όνομα Ιησούς!<br/>Διώχνει τους φόβους, τις σκιές<br/>Απ’ όλους τους πιστούς<br/>',NULL,187776,1);
INSERT INTO stanza VALUES('GK20','2','Στο πνεύμα είναι βάλσαμο<br/>Και ανακούφιση<br/>Σαν μάννα απ’ τον ουρανό<br/>Τροφή για την ψυχή<br/>',NULL,187777,2);
INSERT INTO stanza VALUES('GK20','3','Τι όνομα! Ο βράχος μας<br/>Προπύργιο και ασπίς<br/>Το θησαυροφυλάκιο<br/>Χάρης ατέλειωτης<br/>',NULL,187778,3);
INSERT INTO stanza VALUES('GK20','4','Ιησού, Σωτήρα και Ποιμήν<br/>Ιερέα μας, Βασιλιά<br/>Κύριε μας, οδός και ζωή<br/>Δέξου την προσφορά<br/>',NULL,187779,4);
INSERT INTO stanza VALUES('GK20','5','Ω! Τι αδύναμη η καρδιά<br/>Οι σκέψεις μας χλιαρές<br/>Μα όταν Σ’ αντικρίσουμε<br/>Θα είμαστε όπως θες<br/>',NULL,187780,5);
INSERT INTO stanza VALUES('GK20','6','Ως τότε την αγάπη Σου<br/>Θα διακηρύσσουμε<br/>Με τ’ όνομά Σου τον εχθρό<br/>Θα τον νικήσουμε<br/>',NULL,187781,6);
INSERT INTO stanza VALUES('GK21','1','Ω Κύριε, τι ένδοξος!<br/>Στ’ αλήθεια Εσύ ’σαι το Φως<br/>Θεός αιώνιος, άπειρος<br/>Στη γη έγινες άνθρωπος<br/>',NULL,187782,1);
INSERT INTO stanza VALUES('GK21','chorus','Ο Χριστός, η έκφραση του Θεού<br/>Ανεξάντλητος και γλυκός!<br/>Θεός και άνθρωπος μαζί<br/>Σε μένα Αυτός κατοικεί<br/>',NULL,187783,2);
INSERT INTO stanza VALUES('GK21','2','Δείχνεις τη δόξα του Θεού<br/>Και είσαι το πλήρωμά Του<br/>Στη σάρκα Εσύ μας λύτρωσες<br/>Ως Πνεύμα ενώθηκες με μας<br/>',NULL,187784,3);
INSERT INTO stanza VALUES('GK21','3','Δικά Σου όλα του Πατρός<br/>Και τα Σα μέσα στο Πνεύμα<br/>Μέσ’ απ’ το Πνεύμα εγώ μπορώ<br/>Αληθινά να Σε γευτώ<br/>',NULL,187785,4);
INSERT INTO stanza VALUES('GK21','4','Με το ζωντανό Λόγο Σου<br/>Μου δίνει ζωή το Πνεύμα<br/>Τ’ αγγίζω και Σε δέχομαι<br/>Και μέσα μου αυξάνεσαι<br/>',NULL,187786,5);
INSERT INTO stanza VALUES('GK21','5','Στο πνεύμα όταν Σε κοιτώ<br/>Τη δόξα Σου κατοπτρίζω<br/>Τότε μεταμορφώνομαι<br/>Και έκφρασή Σου γίνομαι<br/>',NULL,187787,6);
INSERT INTO stanza VALUES('GK21','6','Είν’ η μόνη οδός αυτή<br/>Για τον αγιασμό και τη νίκη<br/>Για ν’ αγγίζουμε τη ζωή<br/>Και να ’μαστε πνευματικοί<br/>',NULL,187788,7);
INSERT INTO stanza VALUES('GK21','7','Το Πνεύμα Σου με ποτίζει<br/>Το είναι μου όλο πληροί<br/>Ό,τι παλιό θ’ αφαιρεθεί<br/>Για τη δική Σου οικοδομή<br/>',NULL,187789,8);
INSERT INTO stanza VALUES('GK22','1','Δόξα, δόξα στον Πατέρα<br/>Δόξα, δόξα στον Υιό<br/>Δόξα, δόξα στ’ Άγιο Πνεύμα<br/>Στον Τριαδικό Θεό<br/>',NULL,187790,1);
INSERT INTO stanza VALUES('GK22','chorus','Ψάλτε ύμνους, ψάλτε ύμνους<br/>Στον Τριαδικό Θεό<br/>Δώστε δόξα, δώστε δόξα<br/>Για το έργο Του το θαυμαστό<br/>',NULL,187791,2);
INSERT INTO stanza VALUES('GK22','2','Στον Πατέρα που σχεδιάζει<br/>Στον Υιό που εκτελεί<br/>Στο Πνεύμα που ζωοποιεί<br/>Σαν Ένας που δρουν μαζί<br/>',NULL,187792,3);
INSERT INTO stanza VALUES('GK23','1','Απ’ τον Θεό πολύ μακριά<br/>Δεν έβλεπα το φως<br/>Μα μέσα από το Λόγο Του<br/>Μου μίλησε ο Χριστός<br/>',NULL,187793,1);
INSERT INTO stanza VALUES('GK23','chorus','Σε μένα ζει<br/>Σε μένα ζει<br/>Σωτηρία θαυμαστή<br/>Χριστός σε μένα ζει<br/>',NULL,187794,2);
INSERT INTO stanza VALUES('GK23','2','Σαν ήλιος που ζωοποιεί<br/>Τα άνθη του αγρού<br/>Αυτός μου έδωσε ζωή<br/>Ζει τώρα μέσα μου<br/>',NULL,187795,3);
INSERT INTO stanza VALUES('GK23','3','Όπως το άνθος τ’ όμορφο<br/>Στο σπόρο κρύβεται<br/>Έτσι το Πνεύμα του Χριστού<br/>Σε μένα βρίσκεται<br/>',NULL,187796,4);
INSERT INTO stanza VALUES('GK23','4','Ω! Πόσο η καρδιά ποθεί<br/>Να γίνει σύμμορφη<br/>Με την εικόνα του Χριστού<br/>Που μέσα σε μένα ζει<br/>',NULL,187797,5);
INSERT INTO stanza VALUES('GK24','1','Κύριε Ιησού, η σκέψη Σου<br/>Γλυκαίνει την καρδιά<br/>Πώς θέλουμε την αρπαγή<br/>Να Σ’ έχουμε κοντά<br/>',NULL,187798,1);
INSERT INTO stanza VALUES('GK24','chorus','Σαν άνθος μες στους αμπελώνες<br/>Είν’ η δική Σου η ομορφιά<br/>Εσένα, Κύριε, η καρδιά<br/>Θαυμάζει κι αγαπά<br/>',NULL,187799,2);
INSERT INTO stanza VALUES('GK24','2','Ποιος ύμνος μπορεί να αινεί<br/>Όλη τη χάρη Σου;<br/>Και ποια καρδιά να χωρέσει<br/>Όλη την αγάπη Σου;<br/>',NULL,187800,3);
INSERT INTO stanza VALUES('GK24','3','Πιο πολύ απ’ τη χάρη Σου<br/>Κι απ’ την αγάπη Σου<br/>Θέλουμε Εσένα, Κύριε<br/>Την παρουσία Σου<br/>',NULL,187801,4);
INSERT INTO stanza VALUES('GK24','4','Ω, είσαι ωραιότατος!<br/>Είσαι ο πιο γλυκός<br/>Σ’ όλη τη γη και ουρανό<br/>Είσαι μοναδικός<br/>',NULL,187802,5);
INSERT INTO stanza VALUES('GK25','1','Ο Κύριος είν’ ο Βοσκός μου<br/>Αυτός μ’ οδηγεί στην τροφή<br/>Σε μέρη που τρέχουνε πλούσια<br/>Νερά καθαρά απ’ την πηγή<br/>',NULL,187803,1);
INSERT INTO stanza VALUES('GK25','chorus','Το έλεός Του και η χάρη θα με ακολουθούν<br/>για πάντα σε κάθε στιγμή<br/>Το έλεός Του και η χάρη θα με ακολουθούν<br/>για πάντα σε κάθε στιγμή<br/>Και πάντα στον οίκο Του εγώ θα μένω<br/>Τραπέζι μου στρώνει Αυτός<br/>Το έλεός Του και η χάρη θα με ακολουθούν<br/>για πάντα σε κάθε στιγμή<br/>',NULL,187804,2);
INSERT INTO stanza VALUES('GK25','2','Αυτός ο Χριστός η βοσκή μου<br/>Ειρήνη μου κι ανάπαυση<br/>Ο πλούτος Του είν’ η τροφή μου<br/>Νερό μου η δικιά Του ζωή<br/>',NULL,187805,3);
INSERT INTO stanza VALUES('GK25','3','Αυτός την ψυχή στερεώνει<br/>Τη θέληση, νου και καρδιά<br/>Και σαν την κοιλάδα διαβαίνω<br/>Αυτός με κρατά δυνατά<br/>',NULL,187806,4);
INSERT INTO stanza VALUES('GK25','4','Το δείπνο Του απολαμβάνω<br/>Και έτσι νικώ τον εχθρό<br/>Το χρίσμα Του στην κεφαλή μου<br/>Χαράς είναι Πνεύμα Αυτό<br/>',NULL,187807,5);
INSERT INTO stanza VALUES('GK26','1','Προ καταβολής του κόσμου<br/>Κύριε, Συ μας διάλεξες<br/>Με την άπειρη Σου αγάπη<br/>Στον Ιησού μάς έλκυσες<br/>Και αυτή θα μας φυλάξει<br/>Στερεωμένους στον Χριστό<br/>Στερεωμένους στον Χριστό<br/>',NULL,187808,1);
INSERT INTO stanza VALUES('GK26','2','Τι ο κόσμος κι αν αλλάζει<br/>Ίδιος μένει ο Θεός<br/>Η στοργή Του κι η διαθήκη<br/>Θα ισχύουν αιωνίως<br/>Και για πάντα τα παιδιά Του<br/>Τ’ όνομά Του θα υμνούν<br/>Τ’ όνομά Του θα υμνούν<br/>',NULL,187809,2);
INSERT INTO stanza VALUES('GK26','3','Καύχημά μου ο Θεός μου<br/>Η στοργή Του η γλυκιά<br/>Με το μέγα έλεός Του<br/>Οδηγεί τα βήματα<br/>Τι αγάπη! Να δωρίσει<br/>Τον Μονογενή σε μας<br/>Τον Μονογενή σε μας<br/>',NULL,187810,3);
INSERT INTO stanza VALUES('GK26','4','Ω Πατέρα, θα υμνούμε<br/>Την αιώνια αγάπη Σου<br/>Έως ότου να βρεθούμε<br/>Κει ψηλά με τον Ιησού<br/>Δίνοντας όλη τη δόξα<br/>Στον Θεό και στον Αμνό<br/>Στον Θεό και στον Αμνό<br/>',NULL,187811,4);
INSERT INTO stanza VALUES('GK27','1','Δώστε δόξα! Δώστε δόξα!<br/>Στον Χριστό τον Νικητή<br/>Κρίθηκε η αμαρτία<br/>Φάνηκε η λύτρωση<br/>Σύντριψε με το σταυρό Του<br/>Του εχθρού τη δύναμη<br/>',NULL,187812,1);
INSERT INTO stanza VALUES('GK27','2','Αναστήθηκε! Ω δόξα!<br/>Απ’ τον τάφο ο Χριστός<br/>Και ο θάνατος παρήλθε<br/>Για να ζήσει ο άνθρωπος<br/>Ο Άδης έχασε τη μάχη<br/>Κέρδισε το αιώνιο φως<br/>',NULL,187813,2);
INSERT INTO stanza VALUES('GK27','3','Αναλήφθηκε! Ω δόξα!<br/>Κάθεται στον ουρανό<br/>Πάνω απ’ όλες τις δυνάμεις<br/>Μ’ όνομα μοναδικό<br/>Όλη η εξουσία δική Του<br/>Ο εχθρός υποπόδιο<br/>',NULL,187814,3);
INSERT INTO stanza VALUES('GK27','4','Αλληλούια για τη νίκη<br/>Θρίαμβος στο Γολγοθά<br/>Αλληλούια, ναι – ανέστη<br/>Κάθεται πολύ ψηλά<br/>Αλληλούια, ανελήφθη<br/>Και αιώνια κυβερνά<br/>',NULL,187815,4);
INSERT INTO stanza VALUES('GK28','1','Σε Σένα, Κύριε<br/>Έρχομαι πάντοτε<br/>Και ξεδιψώ και τρέφομαι<br/>Εκεί αγάλλομαι<br/>',NULL,187816,1);
INSERT INTO stanza VALUES('GK28','2','Τη δόξα Σου να δω<br/>Άλλο δεν θέλω<br/>Μόνο να στέκομαι εδώ<br/>Και να χορταίνω<br/>',NULL,187817,2);
INSERT INTO stanza VALUES('GK28','3','Και το δικό Σου φως<br/>Να πλημμυρίζει<br/>Το πρόσωπό Σου η καρδιά<br/>Να ατενίζει<br/>',NULL,187818,3);
INSERT INTO stanza VALUES('GK28','4','Στη σχέση μας αυτή<br/>Χάρη μου είσαι Συ<br/>Και το πνεύμα και η καρδιά<br/>Βρίσκουν ανάπαυση<br/>',NULL,187819,4);
INSERT INTO stanza VALUES('GK28','5','Κύριε, θα μείνω εδώ<br/>Και θα Σε καρτερώ<br/>Στο Λόγο και στην προσευχή<br/>Θα Σε αναζητώ<br/>',NULL,187820,5);
INSERT INTO stanza VALUES('GK29','1','Τόσα χρόνια έψαχνα να βρω νερό<br/>Για να μη διψάω πια<br/>Μα δεν βρήκα τίποτα στη γη αυτή<br/>Την ψυχή να ξεδιψά<br/>',NULL,187821,1);
INSERT INTO stanza VALUES('GK29','chorus','Τώρα πίνω από την πηγή ζωής<br/>Πίνω από την αστείρευτη πηγή<br/>Βρήκα ευτυχία, ζωή αιώνια<br/>Εγώ πίνω απ’ την πηγή ζωής<br/>',NULL,187822,2);
INSERT INTO stanza VALUES('GK29','2','Δεν περιπλανώμαι πια στην έρημο<br/>Όπως έκανα παλιά<br/>Κύριος μου τώρα είναι ο Ιησούς<br/>Και με γέμισε χαρά<br/>',NULL,187823,3);
INSERT INTO stanza VALUES('GK29','3','Μέσα στη γαληνή η ζωή κυλά<br/>Βρήκα εδώ παρηγοριά<br/>Τώρα η ψυχή μου αναπαύεται<br/>Κι η καρδιά μου τραγουδά<br/>',NULL,187824,4);
INSERT INTO stanza VALUES('GK29','4','Όσο ζω θα έχω αυτήν την όαση<br/>Μέσα στον αιώνα αυτό<br/>Και σαν το πουλί θ’ ανοίγω τα φτερά<br/>Στην πηγή μου θα πετώ<br/>',NULL,187825,5);
INSERT INTO stanza VALUES('GK30','1','Ω Κύριε, είσαι η πηγή<br/>Που πλούσια κυλά<br/>Είσαι το ζωντανό νερό<br/>Που ρέει αιώνια<br/>',NULL,187826,1);
INSERT INTO stanza VALUES('GK30','2','Μ’ αγάπη μέσα απ’ τον Υιό<br/>Εκχύθηκες στη γη<br/>Και σήμερα το Πνεύμα Σου<br/>Τη χάρη χορηγεί<br/>',NULL,187827,2);
INSERT INTO stanza VALUES('GK30','3','Κι ενώ μακριά Σου ήμασταν<br/>Χαμένοι αμαρτωλοί<br/>Μέσ’ απ’ τον Υιό μάς λύτρωσες<br/>Μας χάρισες ζωή<br/>',NULL,187828,3);
INSERT INTO stanza VALUES('GK30','4','Το Πνεύμα Σου λυπήσαμε<br/>Θεέ, τόσες φορές<br/>Μα Εσύ ξανά μέσ’ απ’ Αυτόν<br/>Μας επισκέφτηκες<br/>',NULL,187829,4);
INSERT INTO stanza VALUES('GK30','5','Διαμέσου Υιού και Πνεύματος<br/>Με μας θα κοινωνείς<br/>Και με το πλούσιο χρίσμα Σου<br/>Εσύ θα αυξηθείς<br/>',NULL,187830,5);
INSERT INTO stanza VALUES('GK30','6','Πατέρα, την αγάπη Σου<br/>Τη χάρη του Χριστού<br/>Τα πλούτη Σου αιώνια<br/>Διαχέει το Πνεύμα Σου<br/>',NULL,187831,6);
INSERT INTO stanza VALUES('GK30','7','Πώς μας φροντίζεις, ω Θεέ!<br/>Με τι γλυκιά στοργή<br/>Υμνούμε την αγάπη Σου<br/>Όλοι με μια ψυχή<br/>',NULL,187832,7);
INSERT INTO stanza VALUES('GK31','1','Ξέχνα τον κόσμο, βρες τον Χριστό<br/>Μόνο Αυτόν θέλει η καρδιά<br/>Τι άλλο ψάχνεις για να βρεις<br/>Όλα του κόσμου μάταια<br/>',NULL,187833,1);
INSERT INTO stanza VALUES('GK31','chorus','Τι πλούσιος είν’ ο Χριστός<br/>Όλα τα έχει τ’ αγαθά<br/>Τόσο καλός, τόσο γλυκός<br/>Τις προσδοκίες σου ξεπερνά<br/>',NULL,187834,2);
INSERT INTO stanza VALUES('GK31','2','Ξέχνα τον κόσμο, βρες τον Χριστό<br/>Ανάγκη έχεις μόνο Αυτόν<br/>Όταν γνωρίσεις τον Χριστό<br/>Δεν θα το θες το παρελθόν<br/>',NULL,187835,3);
INSERT INTO stanza VALUES('GK31','3','Ο κόσμος είναι άβυσσος<br/>Και η καρδιά πολύ μικρή<br/>Όμως μ’ όλα τα πλούτη του<br/>Να την γεμίσει δεν μπορεί<br/>',NULL,187836,4);
INSERT INTO stanza VALUES('GK31','4','Με τον Χριστό θα ’χεις χαρά<br/>Δίχως Αυτόν θα πονάς<br/>Όπου Χριστός κι εκεί το φως<br/>Αλλιώς στο σκότος περπατάς<br/>',NULL,187837,5);
INSERT INTO stanza VALUES('GK32','1','Κάποτε ζητούσα να ευλογηθώ<br/>Τώρα θέλω μόνο τον Ιησού Χριστό<br/>Κάποτε ποθούσα δώρα του Θεού<br/>Τώρα Αυτόν ζητάω και το Λόγο Του<br/>',NULL,187838,1);
INSERT INTO stanza VALUES('GK32','chorus','Ο Χριστός είν’ όλα<br/>κι όλα εν Χριστώ<br/>Τώρα και για πάντα<br/>εγώ θα Τον υμνώ<br/>',NULL,187839,2);
INSERT INTO stanza VALUES('GK32','2','Κάποτε η προσπάθεια πως με κούραζε!<br/>Τώρα τον Ιησού μου εμπιστεύομαι<br/>Κάποτε κρατιόμουν σαν από σχοινί<br/>Τώρα με κρατάει, μ’ αγκυροβολεί<br/>',NULL,187840,3);
INSERT INTO stanza VALUES('GK32','3','Κάποτε είχα έννοιες, σκέψεις συνεχώς<br/>Τώρα την φροντίδα την έχει ο Χριστός<br/>Κάποτε μοχθούσα ακατάπαυστα<br/>Τώρα Τον δοξάζω κι Αυτός μεριμνά<br/>',NULL,187841,4);
INSERT INTO stanza VALUES('GK32','4','Κάποτε το εγώ μου ήταν οδηγός<br/>Τώρα τη ζωή μου οδηγεί Αυτός<br/>Κάποτε σκεφτόμουν πώς θα ωφεληθώ<br/>Τώρα ό,τι κάνω είν’ για τον Χριστό<br/>',NULL,187842,5);
INSERT INTO stanza VALUES('GK32','5','Κάποτε το φως μου σιγοέτρεμε<br/>Τώρα είναι φλόγα που δεν κρύβεται<br/>Κάποτε η πίστη είχε κλονιστεί<br/>Τώρα η άγκυρά μου είν’ ασάλευτη<br/>',NULL,187843,6);
INSERT INTO stanza VALUES('GK33','1','Κύριε, Σ’ ευχαριστούμε<br/>Για την άγια τράπεζα<br/>Για τον άρτο, για τον οίνο<br/>Που μας δίνεις πλούσια<br/>Ναι, ο άρτος είν’ το σώμα<br/>Που για μας συντρίφθηκε<br/>Και ο οίνος είν’ το αίμα<br/>Που για όλους χύθηκε<br/>',NULL,187844,1);
INSERT INTO stanza VALUES('GK33','chorus','Ω! Τι βάθος κρύβει<br/>Τράπεζα η άγια<br/>Όλα τα μυστήριά της<br/>Ανεξήγητα<br/>',NULL,187845,2);
INSERT INTO stanza VALUES('GK33','2','Με το θάνατό Σου, Κύριε<br/>Έφερες τη λύτρωση<br/>Στην αιώνια ζωή Σου<br/>Να ’μαστε συμμέτοχοι<br/>Με τον άρτο και τον οίνο<br/>Θάνατό Σου δείχνουμε<br/>Τρώμε, πίνουμε Εσένα<br/>Και Σε μνημονεύουμε<br/>',NULL,187846,3);
INSERT INTO stanza VALUES('GK33','3','Και ο άρτος συμβολίζει<br/>Σώμα Σου το μυστικό<br/>Κοινωνούμε με τα μέλη<br/>Ο δεσμός αδιάσπαστος<br/>Με το άγιο το ποτήρι<br/>Που ευλογούμε εμείς<br/>Κοινωνούμε με το αίμα<br/>Όλοι οι πιστοί μαζί<br/>',NULL,187847,4);
INSERT INTO stanza VALUES('GK33','4','Της αιώνιας μερίδας<br/>Παίρνουμε μια πρόγευση<br/>Τη δική Σου βασιλεία<br/>Επισπεύδουμε στη γη<br/>Όταν έρθει η βασιλεία<br/>Συντροφιά με νικητές<br/>Θα δειπνήσουμε και πάλι<br/>Νυμφίε αγαπητέ!<br/>',NULL,187848,5);
INSERT INTO stanza VALUES('GK34','1','Ο Βασιλιάς μου έρχεται<br/>στα ουράνια θα φανεί<br/>το σύμπαν που θα λυτρωθεί<br/>το φως Του εκεί θα δει<br/>Ο πόθος Του θα εκπληρωθεί<br/>ακούω τα βήματα<br/>το ένδοξο το σχήμα Του<br/>διακρίνω αμυδρά<br/>',NULL,187849,1);
INSERT INTO stanza VALUES('GK34','2','Και δεν τολμώ να ’μαι νωθρός<br/>καθώς Τον καρτερώ<br/>αυτή τη θαυμαστή μορφή<br/>μια μέρα εγώ θα δω<br/>Η πίστη μου—σαν έρθει Αυτός<br/>θα λάβει υπόσταση<br/>Ω! Μεγαλύτερη χαρά<br/>δεν έχω φανταστεί<br/>',NULL,187850,2);
INSERT INTO stanza VALUES('GK34','3','Σ’ Αυτόν ανήκει η καρδιά<br/>τα μάτια στρέφονται<br/>τα χείλη δεν ομολογούν<br/>παρά ότι έρχεται<br/>Η έλευσή Του δεν αργεί<br/>για μένα, ναι, θαρθεί<br/>η υπόσχεση που έδωσε<br/>ναι, θα εκπληρωθεί<br/>',NULL,187851,3);
INSERT INTO stanza VALUES('GK34','4','Ω Κύριε, τα λόγια Σου<br/>δεν θ’ αμφισβητηθούν<br/>με εμψυχώνουν, με κρατούν<br/>σε Σένα μ’ οδηγούν<br/>Ας μη βραδύνει η δόξα Σου<br/>ο εχθρός ν’ αφανιστεί<br/>και θα ’μαστε στο θρόνο Σου<br/>όπως μας είχες πει<br/>',NULL,187852,4);
INSERT INTO stanza VALUES('GK34','5','Τι καταφύγιο ασφαλές<br/>το χέρι Σου, Θεέ<br/>Εσύ φρουρείς όλους αυτούς<br/>που Σ’ εμπιστεύονται<br/>Ένα το ποίμνιο κι ο Ποιμήν<br/>έτσι εμείς κι Εσύ<br/>και ποιο παιδί που Εσύ κρατάς<br/>θα Σου αφαιρεθεί;<br/>',NULL,187853,5);
INSERT INTO stanza VALUES('GK34','6','Χιλιάδες χέρια δεν μπορούν<br/>να βάλουν πρόσκομμα<br/>τ’ αγκάθια μόνο με ωθούν<br/>στο στέμμα πιο κοντά<br/>Σήκω, καρδιά και πνεύμα μου<br/>τον κόσμο αψήφησε<br/>ταχέως ο Σωτήρας μου<br/>για μένα έρχεται<br/>',NULL,187854,6);
INSERT INTO stanza VALUES('GK34','7','Ω Κύριε, ελπίδα μας<br/>το φως Σου, τι λαμπρό!<br/>Ω Δίκαιε! Ω Ένδοξε!<br/>Εσένα προσκυνώ<br/>Και σύντομα στο θρόνο Σου<br/>ο κόσμος θα Σε δει<br/>Θαρθεί η βασιλεία Σου<br/>κι η χάρη Σου στη γη<br/>',NULL,187855,7);
INSERT INTO stanza VALUES('GK34','8','Η αλήθεια πρέπει να στεφθεί<br/>η ελευθερία, κι αυτή<br/>το ψεύδος όμως φαίνεται<br/>στη γη να κυριαρχεί<br/>Ζητούμε, ω Αλήθεια, Εσύ<br/>να έρθεις με το φως<br/>στην αγκαλιά Σου να ’μαστε<br/>να συντριφτεί ο εχθρός<br/>',NULL,187856,8);
INSERT INTO stanza VALUES('GK35','1','Με τη στοργή με πήρε<br/>Από τα βάσανα<br/>Και στο δικό Του ποίμνιο<br/>Με έβαλε ξανά<br/>Κι οι άγγελοι που έβλεπαν<br/>Στην παρουσία Του έψαλλαν<br/>',NULL,187857,1);
INSERT INTO stanza VALUES('GK35','chorus','Ω! Με τι αγάπη<br/>Έψαχνε εμένα!<br/>Με το αίμα Του μ’ αγόρασε<br/>Με τη χάρη Του με έσωσε<br/>',NULL,187858,2);
INSERT INTO stanza VALUES('GK35','2','Με έλαιο και οίνο<br/>Πληγές καθάρισε<br/>«Σε βρήκα, μη φοβάσαι»<br/>Αυτός ψιθύρισε<br/>Ω! Τέτοια λόγια! Τι γλυκά!<br/>Σαν βάλσαμο μες στην καρδιά<br/>',NULL,187859,3);
INSERT INTO stanza VALUES('GK35','3','Τα καρφωμένα χέρια<br/>Σε μένα έδειξε<br/>Τ’ αγκάθινο στεφάνι<br/>Που φόρεσε για εμέ<br/>«Γιατί για μένα» σκέφτηκα<br/>«Υπέφερε τόσα πολλά;»<br/>',NULL,187860,4);
INSERT INTO stanza VALUES('GK35','4','Όταν στην παρουσία Του<br/>Στο φως Του βρίσκομαι<br/>Αναπολώ με δέος<br/>Πώς με ευλόγησε<br/>Η αιωνιότης δεν αρκεί<br/>Εγώ τον Κύριο να υμνώ<br/>',NULL,187861,5);
INSERT INTO stanza VALUES('GK35','5','Καθώς κυλά ο χρόνος<br/>Μες στην ανάπαυση<br/>Μ’ υπομονή προσμένω<br/>Την πιο λαμπρή αυγή<br/>Που θαρθεί για να νυμφευτεί<br/>Τη νύμφη Του την άμωμη<br/>',NULL,187862,6);
INSERT INTO stanza VALUES('GK36','1','Είμαστε εδώ, Κύριε, σαν ένα Σώμα<br/>Πιστοί πολλοί, κι όμως αχώριστοι<br/>Μεγάλο πλήθος, όμως ένα Σώμα<br/>Μες στη ζωή Σου αλληλένδετοι<br/>',NULL,187863,1);
INSERT INTO stanza VALUES('GK36','chorus','Στο σύμπαν ένα είν’ το Σώμα<br/>Το εκφράζουμε εδώ στη γη<br/>Σε κάθε τόπο είμαστε ένα<br/>Όλοι να δουν, σ’ όλη τη γη<br/>',NULL,187864,2);
INSERT INTO stanza VALUES('GK36','2','Σαν ένας άρτος, Κύριε, είν’ το Σώμα<br/>που κόβεται για όλους τους πιστούς<br/>Όταν τον τρώμε εμείς ομολογούμε<br/>Πως είμαστε ένα μ’ όλους τους πιστούς<br/>',NULL,187865,3);
INSERT INTO stanza VALUES('GK36','3','Ένας ο άρτος, ένα το ποτήρι<br/>που την ενότητά μας μαρτυρούν<br/>Εσύ μας έκανες δικά Σου μέλη<br/>Είμαστε ένα, Κύριε, Αμήν!<br/>',NULL,187866,4);
INSERT INTO stanza VALUES('GK36','4','Στεκόμαστε αδιάσπαστοι σε Σένα<br/>Αδιαίρετοι στο μέλλον, στο παρόν<br/>Με μια ψυχή λαμβάνουμε το δείπνο<br/>Και Σ’ ευλογούμε ομοθυμαδόν<br/>',NULL,187867,5);
INSERT INTO stanza VALUES('GK36','5','Αυτή η ενότητα η ευλογημένη<br/>Ω Κύριε, πώς Σε χαροποιεί!<br/>Εμείς η νύφη Σου Σε καρτερούμε<br/>Στο δείπνο να καθίσουμε μαζί<br/>',NULL,187868,6);
INSERT INTO stanza VALUES('GK37','1','Ω Κύριε, να είμαι κοντά Σου ποθώ<br/>Πρωί ως το βράδυ με Σένα να ζω<br/>Ω! Μην επιτρέπεις να αναπαυθώ<br/>Αν επιθυμήσω ν’ απομακρυνθώ<br/>Μες στην τρικυμία και τη συμφορά<br/>Όταν δεν υπάρχει χαρά πουθενά<br/>Και όταν με πνίγουν οι στεναγμοί<br/>Ω Κύριε, τα δάκρυα πάρε Εσύ<br/>',NULL,187869,1);
INSERT INTO stanza VALUES('GK37','2','Όταν ονειρεύομαι για τη ζωή<br/>Ω Κύριε, πρέπει να είσαι εκεί<br/>Να μην επιτρέπεις χαρές να ζητώ<br/>Και μόνος μου να επιλέγω εγώ<br/>Τις νύχτες που βρίσκομαι μες στη σιωπή<br/>Προσεύχομαι Κύριε να είσαι μαζί<br/>Και ξύπνα με Εσύ πριν κάθε αυγή<br/>Ψιθυρίζοντας μου γλυκά στο αυτί<br/>',NULL,187870,2);
INSERT INTO stanza VALUES('GK37','3','Και όταν το Λόγο Σου θα μελετώ<br/>Σε κάθε Του στίχο το φως σου ζητώ<br/>Να δω τον Σωτήρα μου και Λυτρωτή<br/>Και τη σωτηρία που χάρισες Συ<br/>Όταν γονατίζω μπρος στο θρόνο Σου<br/>Τη χάρη Σου δίνε μου και άκου με<br/>Κι αν Σ’ έχω λυπήσει και δεν με ακούς<br/>Ω! Το πρόσωπό Σου μη στρέφεις αλλού<br/>',NULL,187871,3);
INSERT INTO stanza VALUES('GK37','4','Και όταν ζητάω να ευλογηθώ<br/>Ο πόθος μου είναι ευθύς ν’ αρπαχθώ<br/>Εδώ περιμένω Εσένα να δω<br/>Κι εκεί στην παρουσία Σου να βρεθώ<br/>Ω! Μάθε μου Κύριε κοντά Σου να ζω<br/>Πρωί ως το βράδυ με Σένα να ζω<br/>Ω! Μην επιτρέπεις να αναπαυθώ<br/>Αν επιθυμήσω ν’ απομακρυνθώ<br/>',NULL,187872,4);
INSERT INTO stanza VALUES('GK38','1','Βρήκα τον απαράμιλλο<br/>Πώς να μην τραγουδώ;<br/>Ω! Πόσο χαίρει η καρδιά<br/>Που βρήκα τον Χριστό!<br/>',NULL,187873,1);
INSERT INTO stanza VALUES('GK38','2','Χριστός μου—του Θεού Αμνός<br/>Η σωτηρία μου<br/>Είν’ η δικαιοσύνη μου<br/>Κι η θεραπεία μου<br/>',NULL,187874,2);
INSERT INTO stanza VALUES('GK38','3','Χριστός μου—Δέντρο της Ζωής<br/>Γλυκός και άφθονος<br/>Με τον καρπό τον πλούσιο<br/>Με τρέφει διαρκώς<br/>',NULL,187875,3);
INSERT INTO stanza VALUES('GK38','4','Χριστός μου—είν’ η Πέτρα αυτή<br/>Που έβγαζε νερό<br/>Είν’ η πηγή μες στην καρδιά<br/>Ποτέ μου δεν διψώ<br/>',NULL,187876,4);
INSERT INTO stanza VALUES('GK38','5','Χριστός μου—φως, ζωή, οδός<br/>Υγεία, παρηγοριά<br/>Ειρήνη, πλούτος και δόξα<br/>Ελπίδα και χαρά<br/>',NULL,187877,5);
INSERT INTO stanza VALUES('GK38','6','Χριστός—σοφία, δύναμη<br/>Η ευφροσύνη μου<br/>Η νίκη μου, η λύτρωση<br/>Κι η αγιοσύνη μου<br/>',NULL,187878,6);
INSERT INTO stanza VALUES('GK38','7','Χριστός—Ποιμένας, Κύριος<br/>Και υπερασπιστής<br/>Θεός, Πατέρας, Σύμβουλος<br/>Και υποστηρικτής<br/>',NULL,187879,7);
INSERT INTO stanza VALUES('GK38','8','Χριστός—Φρουρός και Αρχηγός<br/>Αφέντης, Κεφαλή<br/>Νυμφίος μου και Οδηγός<br/>Μέσα μου κατοικεί<br/>',NULL,187880,8);
INSERT INTO stanza VALUES('GK38','9','Χριστός—Ιερέας, Βασιλιάς<br/>Προφήτης πάνσοφος<br/>Ο κρίκος μου με τον Θεό<br/>Ο Παντοδύναμος<br/>',NULL,187881,9);
INSERT INTO stanza VALUES('GK38','10','Χριστός—της πίστης Αρχηγός<br/>Και Τελειωτής Αυτός<br/>Μεσίτης μου κι Εγγύηση<br/>Και Μάρτυρας πιστός<br/>',NULL,187882,10);
INSERT INTO stanza VALUES('GK38','11','Χριστός—αιώνιος οίκος μου<br/>Η εύφορη μου γη<br/>Προπύργιο μου, φρούριο<br/>Σ’ Αυτόν έχω σταθεί<br/>',NULL,187883,11);
INSERT INTO stanza VALUES('GK38','12','Χριστός—είναι το Σάββατο<br/>Αυγή κι ημέρα μου<br/>Είν’ ο αιώνας που διαρκεί<br/>Η αθανασία μου<br/>',NULL,187884,12);
INSERT INTO stanza VALUES('GK38','13','Χριστός—η πίστη, ο πόθος μου<br/>Τι κάλλος τέλειο!<br/>Αυτός ευφραίνει την καρδιά<br/>Και δεν θα στερηθώ<br/>',NULL,187885,13);
INSERT INTO stanza VALUES('GK38','14','Χριστός μου—όλα τα ’χει Αυτός<br/>Πώς να ονομαστεί;<br/>Τα πάντα εν πάσι είν’ Αυτός<br/>Το τέλος κι η αρχή<br/>',NULL,187886,14);
INSERT INTO stanza VALUES('GK38','15','Με τέτοιο θησαυρό εγώ<br/>Πώς να μην τραγουδώ;<br/>Ναι, θα υμνώ και θα υμνώ<br/>Τον θαυμαστό Χριστό!<br/>',NULL,187887,15);
INSERT INTO stanza VALUES('GK39','1','Πόσο γλυκός ο οίκος Σου<br/>και τις αυλές Σου επιποθώ<br/>καρδιά και σάρκα αγάλλωνται<br/>μες στις σκηνές Σου να βρεθώ<br/>',NULL,187888,1);
INSERT INTO stanza VALUES('GK39','2','Στο χάλκινο και στο χρυσό<br/>θυσιαστήριο Σου Θεέ<br/>το σπουργιτάκι έχει φωλιά<br/>το χελιδόνι εκεί γεννά<br/>',NULL,187889,2);
INSERT INTO stanza VALUES('GK39','3','Σαν το σπουργίτι είμαστε<br/>στον οίκο Σου φωλιάζουμε<br/>με το αίμα της θυσίας Σου<br/>ειρήνη απολαμβάνουμε<br/>',NULL,187890,3);
INSERT INTO stanza VALUES('GK39','4','Μακάριος ο άνθρωπος<br/>που η δύναμη του είσαι Συ<br/>και η καρδιά του λαχταρά<br/>προς τη Σιών να ανεβεί<br/>',NULL,187891,4);
INSERT INTO stanza VALUES('GK39','5','Και την κοιλάδα των κλαυθμών<br/>όταν αυτοί διαβαίνουνε<br/>σε πηγή υδάτων ζωντανών<br/>ευθύς τη μετατρέπουνε<br/>',NULL,187892,5);
INSERT INTO stanza VALUES('GK39','6','Με σθένος αυξανόμενο<br/>στη Σιών Εσένα συναντούν<br/>χορταίνουν με τη χάρη Σου<br/>το πρόσωπό Σου εκεί ζητούν<br/>',NULL,187893,6);
INSERT INTO stanza VALUES('GK39','7','Μια μέρα είναι καλύτερα<br/>στον οίκο Σου να κατοικώ<br/>παρά χιλιάδες ημερών<br/>μες στις σκηνές των πονηρών<br/>',NULL,187894,7);
INSERT INTO stanza VALUES('GK39','8','Ήλιος κι ασπίδα είσαι Συ<br/>χάρη και δόξα δίνεις<br/>Μέσα στην παρουσία Σου<br/>Η αγάπη Σου συσφίγγει<br/>',NULL,187895,8);
INSERT INTO stanza VALUES('GK39','9','Δεν θα στερήσεις αγαθό<br/>στους τίμιους προσκυνητές<br/>Μακάριος ο άνθρωπος<br/>Ο ελπίζων μόνο επί Σε<br/>',NULL,187896,9);
INSERT INTO stanza VALUES('GK40','1','Κράτα Εσύ την καρδιά μου, Θεέ<br/>Αφοσιωμένη σ’ Εσέ πάντοτε<br/>Καρδιά που να βλέπει μονάχα Εσέ<br/>Που Σ’ αγαπάει και θέλει μόνο Εσέ<br/>',NULL,187897,1);
INSERT INTO stanza VALUES('GK40','chorus','Αναγκασμένος απ’ την αγάπη Σου<br/>Σ’ Εσένα δίνω όλο το είναι μου<br/>Ω, τι προνόμιο! Σου παραδίνομαι!<br/>Σε αγαπώ, Κύριε<br/>Θεέ μου, Σε αγαπώ<br/>',NULL,187898,2);
INSERT INTO stanza VALUES('GK40','2','Τη φλόγα μου κράτα Εσύ ζωντανή<br/>Ποτέ να μη σβήνει, ό,τι κι αν συμβεί<br/>Μια φλόγα αγάπης που καίει ζωηρά<br/>Σαν τότε που Σ’ άγγιξα πρώτη φορά<br/>',NULL,187899,3);
INSERT INTO stanza VALUES('GK40','3','Ναι, τη ζωή μου προσφέρω σ’ Εσέ<br/>Ω! Να είχα χίλιες να δώσω σ’ Εσέ<br/>Δεν κρατάω κάτι, όλα δικά Σου<br/>Σ’ ανήκει Κύριε όλο το μέλλον μου<br/>',NULL,187900,4);
INSERT INTO stanza VALUES('GK41','1','Γιατί για με Συ πέθανες;<br/>Κύριε γιατί Εσύ αντί για με;<br/>Τη θέση μου Συ πήρες στο σταυρό<br/>Να γίνεις κατάρα για να σωθώ<br/>',NULL,187901,1);
INSERT INTO stanza VALUES('GK41','chorus','Τι Σ’ έκανε Χριστέ να σταυρωθείς για με;<br/>Εγώ εχθρός Σου ήμουν για Σε<br/>Ω, τι μυστήριο! Εσύ ο Άγιος<br/>Να σταυρωθείς αντί για με!<br/>',NULL,187902,2);
INSERT INTO stanza VALUES('GK41','2','Δεν πίστευα ποτέ πως Συ<br/>Αγάπη έχεις κι έλεος πολύ<br/>Πώς μπόρεσες κι αγάπησες εμέ<br/>Ενώ εχθρός Σου ήμουν, Χριστέ;<br/>',NULL,187903,3);
INSERT INTO stanza VALUES('GK41','3','Μ’ αγάπησες τόσο πολύ<br/>Με μια αγάπη αιώνια, δυνατή<br/>Ενώ εγώ Σε χλεύαζα παλιά<br/>Εσύ προσευχόσουν για με βαθιά<br/>',NULL,187904,4);
INSERT INTO stanza VALUES('GK41','4','Άνθρωπος ήμουν δίχως φως<br/>Με μια ζωή πολύ αμαρτωλή<br/>Η καρδιά μου δεν Σ’ ήθελε Χριστέ<br/>Μα Συ με συμπόνια την άγγιξες<br/>',NULL,187905,5);
INSERT INTO stanza VALUES('GK41','chorus','Η αγάπη Σου Χριστέ μόνο με έλκυσε<br/>Μ’ αγάπη Εσύ ήρθες σε με<br/>Το έλεός Σου μόνο με άλλαξε<br/>Η αγάπη Σου με κέρδισε<br/>',NULL,187906,6);
INSERT INTO stanza VALUES('GK41','5','Πόσο κοντά μου ήσουν Χριστέ<br/>Περίμενες μ’ αγάπη εμέ<br/>Πώς θα μπορούσα να ’μενα εχθρός<br/>Αφού με αγάπησες Συ ο Θεός;<br/>',NULL,187907,7);
INSERT INTO stanza VALUES('GK42','1','Στα βάθη του ονόματος Σου, Θεέ<br/>Βρίσκω γαλήνη σαν βυθίζομαι<br/>Συ επαρκείς στη μέρα τη μακρά<br/>Συ επαρκείς στη σκοτεινή νυχτιά<br/>',NULL,187908,1);
INSERT INTO stanza VALUES('GK42','2','Είσ’ ο Θεός μου, όλα τα πληροίς<br/>Ό,τι μου λείπει το δημιουργείς<br/>Έχεις σκορπίσει στην οδό μου Εσύ<br/>Θαύματα αγάπης και γλυκιά στοργή<br/>',NULL,187909,2);
INSERT INTO stanza VALUES('GK42','3','Ρίχνομαι, Κύριε, άλλη μια φορά<br/>Με θάρρος στη δική Σου αγκαλιά<br/>Μέσα στης πίστης την ανάπαυση<br/>Στης πίστης τη βαθιά ανάπαυση<br/>',NULL,187910,3);
INSERT INTO stanza VALUES('GK43','1','Τι αγάπη έδωσες σε μας!<br/>Σ’ ευχαριστούμε<br/>Πατέρα, μ’ όλη την καρδιά<br/>Θα Σε υμνούμε<br/>',NULL,187911,1);
INSERT INTO stanza VALUES('GK43','2','Αυτό που είχες στην καρδιά<br/>Μας αποκάλυψες<br/>Μέσ’ απ’ τον Υιό το σχέδιο<br/>Εσύ εκπλήρωσες<br/>',NULL,187912,2);
INSERT INTO stanza VALUES('GK43','3','Τον Υιό Σου τον μονογενή<br/>Κι αγαπημένο Σου<br/>Θυσίασες να γίνουμε<br/>Εμείς παιδιά Σου<br/>',NULL,187913,3);
INSERT INTO stanza VALUES('GK43','4','Μέσ’ απ’ Αυτόν πάντα για μας<br/>Θα ’σαι Πατέρας<br/>Τη φύση Σου και τη ζωή<br/>Θα χορηγείς σε μας<br/>',NULL,187914,4);
INSERT INTO stanza VALUES('GK43','5','Μας γέννησε το Πνεύμα Σου<br/>Και σφραγιστήκαμε<br/>Τώρα, «Αββά Πατέρα»<br/>Μαζί Του κράζουμε<br/>',NULL,187915,5);
INSERT INTO stanza VALUES('GK43','6','Να φτάσουμε στη δόξα Σου<br/>Είν’ ο σκοπός Σου<br/>Και σύμμορφοι να γίνουμε<br/>Με τον Υιό Σου<br/>',NULL,187916,6);
INSERT INTO stanza VALUES('GK43','7','Τον κάθε έναν από εμάς<br/>Μεταμορφώνεις<br/>Και από δόξα σε δόξα<br/>Εσύ μας φέρνεις<br/>',NULL,187917,7);
INSERT INTO stanza VALUES('GK43','8','Τι αγάπη έδωσες σε μας!<br/>Σ’ ευγνωμονούμε<br/>Πατέρα μας, παντοτινά<br/>Θα Σε υμνούμε<br/>',NULL,187918,8);
INSERT INTO stanza VALUES('GK44','1','Τι βαθιά, ω Κύριέ μου<br/>Είναι η αγάπη Σου!<br/>Ανεξάντλητη, πελώρια<br/>Σαν το βάθος του βυθού!<br/>Σε οδήγησε για μένα<br/>Να πεθάνεις στο σταυρό<br/>Για να μπολιαστώ σε Σένα<br/>Πάντοτε μ’ Εσέ να ζω<br/>',NULL,187919,1);
INSERT INTO stanza VALUES('GK44','2','Τόσα θαύματα για μένα<br/>Με τι λόγια να τα πω;<br/>Μεγαλύτερο απ’ όλα<br/>Τ’ ότι είμαι εν Χριστώ<br/>Μέσ’ απ’ τη δική Σου αγάπη<br/>Ρέει η ζωή Σου συνεχώς<br/>Με τα πλούτη τα δικά Σου<br/>Μ’ εφοδιάζει διαρκώς<br/>',NULL,187920,2);
INSERT INTO stanza VALUES('GK44','3','Η αγάπη Σου εκφράζει<br/>Το γλυκό Σου εαυτό<br/>Δίνει νόημα στη ζωή μου<br/>Ώστε να εκφράζω Εσέ<br/>Και η χάρη κάθε μέρα<br/>Είναι υπεραρκετή<br/>Για να γεύομαι ότι είμαι<br/>Της καρδιάς Σου ο σκοπός<br/>',NULL,187921,3);
INSERT INTO stanza VALUES('GK44','4','Τι μπορεί να μας χωρίσει;<br/>Στην αγάπη υπερτερείς<br/>Τέτοια αγάπη που με μένα<br/>Θέλησες να ενωθείς!<br/>Πάντοτε θα είμαστε ένα<br/>Συ σ’ εμέ κι εγώ σ’ Εσέ<br/>Αυτή είν’ η μαρτυρία μου<br/>Κι η δοξολογία μου<br/>',NULL,187922,4);
INSERT INTO stanza VALUES('GK45','1','Του Θεού η πρόθεση είναι<br/>Να αποκαλυφθεί ο Χριστός<br/>Όχι απ’ έξω σαν θρησκεία<br/>Μα από μέσα μου Αυτός<br/>',NULL,187923,1);
INSERT INTO stanza VALUES('GK45','chorus','Ο Χριστός, είν’ πρόθεση Του<br/>Μέσα μου να υφανθεί<br/>Όχι με δικά μου έργα<br/>Μα Αυτός να με πληροί<br/>',NULL,187924,2);
INSERT INTO stanza VALUES('GK45','2','Του Θεού η πρόθεση είναι<br/>Μέσα μου να ζει ο Χριστός<br/>Όχι να προσέχω σ’ έργα<br/>Μα να γεύομαι Αυτόν<br/>',NULL,187925,3);
INSERT INTO stanza VALUES('GK45','3','Του Θεού η πρόθεση είναι<br/>Ο Χριστός να μορφωθεί<br/>Όχι ακολουθώντας τύπους<br/>Μα εντός μου να αυξηθεί<br/>',NULL,187926,4);
INSERT INTO stanza VALUES('GK45','4','Του Θεού η πρόθεση είναι<br/>Πλήρως να κατακτηθώ<br/>Όχι μόνο υπηρετώντας<br/>Μα οίκος Του να ’μαι εγώ<br/>',NULL,187927,5);
INSERT INTO stanza VALUES('GK45','5','Του Θεού η πρόθεση είναι<br/>Ο Χριστός η ελπίδα μου<br/>Όχι τη δική μου δόξα<br/>Μα να ζω τη δόξα Του<br/>',NULL,187928,6);
INSERT INTO stanza VALUES('GK45','6','Του Θεού η πρόθεση είναι<br/>Ο Χριστός το παν για με<br/>Όχι ο πρόσκαιρος ο κόσμος<br/>Μα για πάντα ο Χριστός<br/>',NULL,187929,7);
INSERT INTO stanza VALUES('GK46','1','Δεν ξέρω ο Θεός γιατί<br/>Μου αποκαλύφθηκε<br/>Κι εμένα τον ανάξιο<br/>Δικό Του μ’ έκανε<br/>',NULL,187930,1);
INSERT INTO stanza VALUES('GK46','chorus','Όμως ξέρω σε Ποιόν πιστεύω<br/>Και είμαι απόλυτα πεπεισμένος<br/>Ότι μπορεί να με φυλάξει<br/>Μέχρι την Ημέρα Του<br/>',NULL,187931,2);
INSERT INTO stanza VALUES('GK46','2','Δεν ξέρω πώς την πίστη Του<br/>Σε μένα έδωσε<br/>Κι η πίστη μου στο Λόγο Του<br/>Γαλήνη έφερε<br/>',NULL,187932,3);
INSERT INTO stanza VALUES('GK46','3','Δεν ξέρω πώς το Πνεύμα Του<br/>Εργάζεται εντός<br/>Και μέσα απ’ το Λόγο Του<br/>Μας δείχνει τον Χριστό<br/>',NULL,187933,4);
INSERT INTO stanza VALUES('GK46','4','Δεν ξέρω τι καραδοκεί<br/>Στο μέλλον, στο παρόν<br/>Τι μου επιφυλάσσεται<br/>Προτού να δω Αυτόν<br/>',NULL,187934,5);
INSERT INTO stanza VALUES('GK46','5','Δεν ξέρω πότε θα φανεί<br/>Και πότε θα Τον δω<br/>Αν θα περάσω θάνατο<br/>Η μ’ άλλους θα αρπαχθώ<br/>',NULL,187935,6);
INSERT INTO stanza VALUES('GK47','1','Ιησούς, θαυμάσιος Ποιμένας<br/>Μας πήρε απ’ το μαντρί<br/>Μέσα σε πλούσια λιβάδια<br/>Να κατοικούμε εκεί<br/>',NULL,187936,1);
INSERT INTO stanza VALUES('GK47','chorus','Στην εκκλησία<br/>Βρίσκουμε πλούσια τροφή<br/>Όπου είν’ ομοψυχία<br/>Είναι η θεία ζωή<br/>',NULL,187937,2);
INSERT INTO stanza VALUES('GK47','2','Μες στις διαιρέσεις μας βρήκε<br/>Στερούμενοι την τροφή<br/>Τώρα το πνεύμα μας χαίρει<br/>Μέσα σε εύφορη γη<br/>',NULL,187938,3);
INSERT INTO stanza VALUES('GK47','3','Είναι ο ίδιος ο Ιησούς<br/>Η χλοερή μας βοσκή<br/>Σαν πρόβατά Του μας τρέφει<br/>Σε κάθε μας σύναξη<br/>',NULL,187939,4);
INSERT INTO stanza VALUES('GK47','4','Πάνω σε λόφους σκιρτούμε<br/>Όπου σταλάζει η δροσιά<br/>Και στην πηγή ξεδιψούμε<br/>Άφθονα ρέουν νερά<br/>',NULL,187940,5);
INSERT INTO stanza VALUES('GK47','5','Ναι, ο Χριστός είν’ ειρήνη<br/>Ασφάλεια κι ανάπαυση<br/>Με τη γλυκιά παρουσία Του<br/>Το ποίμνιό Του φρουρεί<br/>',NULL,187941,6);
INSERT INTO stanza VALUES('GK48','1','Εις τη Βαβυλών, στην αιχμαλωσία<br/>Διέγειρε ο Θεός το πνεύμα μας<br/>Όταν ήμασταν μες στη διασπορά<br/>Διέγειρε ο Θεός το πνεύμα μας<br/>Δόξα! Δόξα!<br/>Διέγειρε ο Θεός το πνεύμα μας<br/>',NULL,187942,1);
INSERT INTO stanza VALUES('GK48','2','Απ’ τη Βαβυλών, απ’ τη διαίρεση<br/>Πρέπει να ξεφύγουμε απ’ αυτή<br/>Δεν είν’ αδελφοί η θέση μας εκεί<br/>Πρέπει να ξεφύγουμε απ’ αυτή<br/>Σήκω! Σήκω!<br/>Πρέπει να ξεφύγουμε απ’ αυτή<br/>',NULL,187943,2);
INSERT INTO stanza VALUES('GK48','3','Στην Ιερουσαλήμ ας διαφύγουμε<br/>Ο Θεός θα είναι μεθ’ ημών<br/>Ενωμένοι εκεί ας διαμείνουμε<br/>Ο Θεός θα είναι μεθ’ ημών<br/>Πάμε! Πάμε!<br/>Ο Θεός θα είναι μεθ’ ημών<br/>',NULL,187944,3);
INSERT INTO stanza VALUES('GK48','4','Με τα σκεύη σας πλήρη με Χριστό<br/>Φέρτε τα αγγεία του Κυρίου<br/>Μες στην εκκλησία, θέλημά Του αυτό<br/>Φέρτε τα αγγεία του Κυρίου<br/>Φέρτε! Φέρτε!<br/>Φέρτε τα αγγεία του Κυρίου<br/>',NULL,187945,4);
INSERT INTO stanza VALUES('GK48','5','Στην Ιερουσαλήμ, πόλη εκλεκτή<br/>Τώρα χτίστε πάλι το ναό<br/>Σε υπηρεσία, όλοι μας μαζί<br/>Τώρα χτίστε πάλι το ναό<br/>Χτίστε! Χτίστε!<br/>Τώρα χτίστε πάλι το ναό<br/>',NULL,187946,5);
INSERT INTO stanza VALUES('GK49','1','Απ’ το πνεύμα μου ρέει ζωντανά ο Θεός<br/>Αυτός που μας δίνει ζωή<br/>Ο Πατέρας πηγή, ο Υιός ποταμός<br/>Και το Άγιο Πνεύμα ροή<br/>',NULL,187947,1);
INSERT INTO stanza VALUES('GK49','chorus','Κύριε, για τη γλυκιά Σου ροή<br/>Παραδίνω όλη μου την ψυχή<br/>Κύριε, αύξησε με Εσύ<br/>Να ’μαι ώριμος όταν έρθεις<br/>',NULL,187948,2);
INSERT INTO stanza VALUES('GK49','2','Σε βοσκές χλοερές και νερά ήσυχα<br/>Εκεί ο Ιησούς μ’ οδηγεί<br/>Δεν κοπιάζω εγώ, ούτε πια προσπαθώ<br/>Στη ροή έχω ευλογηθεί<br/>',NULL,187949,3);
INSERT INTO stanza VALUES('GK49','3','Ο Ιησούς μ’ έφερε στα Άγια των Αγίων<br/>Μες στην παρουσία Του ζω<br/>Αλληλούια θα ζω ενωμένος μ’ Αυτόν<br/>Κλήμα είμαι στην άμπελο<br/>',NULL,187950,4);
INSERT INTO stanza VALUES('GK50','1','Πώς να εισπνεύσω αρκετά<br/>Απ’ τ’ αεράκι Σου;<br/>Πιο ευωδιαστό απ’ τη μυρτιά<br/>Σαν βάλσαμο από ψηλά<br/>Το μύρο του Ουρανού<br/>',NULL,187951,1);
INSERT INTO stanza VALUES('GK50','2','Πώς ν’ ατενίσω αρκετά<br/>Σ’ Εσένα, Κύριε;<br/>Μπροστά Σου μένω έκθαμβος<br/>Στην όψη Σου εκστατικός<br/>Ω, Ωραιότατε!<br/>',NULL,187952,2);
INSERT INTO stanza VALUES('GK50','3','Πώς να υπακούσω αρκετά<br/>Σωτήρα, Κύριε;<br/>Δεν θέλω ν’ απομακρυνθώ<br/>Μα πρόθυμα να υπηρετώ<br/>Εσένα πάντοτε<br/>',NULL,187953,3);
INSERT INTO stanza VALUES('GK50','4','Πώς να υμνήσω αρκετά<br/>Το Όνομα αυτό;<br/>Μια μελωδία, τι γλυκιά!<br/>Μου βγαίνει μέσ’ απ’ την καρδιά<br/>Κι από χαρά πετώ<br/>',NULL,187954,4);
INSERT INTO stanza VALUES('GK50','5','Πώς να μιλήσω αρκετά<br/>Γι’ αυτά τα θαυμαστά;<br/>Όταν μ’ αγάπη με καλείς<br/>Και τρυφερά παρηγορείς<br/>Τότε Εσύ μου αρκείς<br/>',NULL,187955,5);
INSERT INTO stanza VALUES('GK51','1','Πιές, από το θρόνο ρέει ποτάμι καθαρό<br/>Φάε, το δέντρο της ζωής παρέχει τον καρπό<br/>Δες, ο ήλιος κι η σελήνη δεν χρειάζονται<br/>Η νύχτα έφυγε<br/>',NULL,187956,1);
INSERT INTO stanza VALUES('GK51','chorus','Έλα, ω, έλα!<br/>Λεν’ Πνεύμα και Νύφη<br/>Έλα, ω, έλα!<br/>Αυτός που ακούει ας πει<br/>Έλα, ω, έλα!<br/>Όποιος διψά ναρθεί<br/>Νερό της ζωής να πιεί<br/>',NULL,187957,2);
INSERT INTO stanza VALUES('GK51','2','Αναβλύζει το νερό που είναι ο Χριστός<br/>Τρώμε από το δέντρο κι ο Χριστός είν’ ο καρπός<br/>Ο Χριστός είναι το φως, αστέρας πρωινός<br/>Ναι, όλα είν’ Αυτός<br/>',NULL,187958,3);
INSERT INTO stanza VALUES('GK51','3','Τα ιμάτια πλένουμε να φάμε απ’ τον καρπό<br/>Κύριε, Αμήν, Αλληλούια! Τι δέντρο είν’ αυτό;<br/>Με το πνεύμα μας εμείς βιώνουμε Αυτόν<br/>Ω, τον γλυκό Χριστό!<br/>',NULL,187959,4);
INSERT INTO stanza VALUES('GK51','4','Τώρα ζούμε σ’ έναν οίκο τόσο λαμπερό<br/>Τα αδέλφια ενωμένα μέσα στον Χριστό<br/>Η ζωή στην εκκλησία είναι πρόγευση<br/>της Νέας Ιερουσαλήμ<br/>',NULL,187960,5);
INSERT INTO stanza VALUES('GK52','1','Μες στον κόλπο του Πατέρα<br/>Πριν ο κόσμος μορφωθεί<br/>Μες στη δόξα του Πατέρα<br/>Ήσουν Υιός μονογενής<br/>Όταν Σ’ έστειλε ο Πατέρας<br/>Ήσουν ίδιος με Αυτόν<br/>Μες στο Πνεύμα ν’ αναγγείλεις<br/>Όλο Του τον εαυτό<br/>',NULL,187961,1);
INSERT INTO stanza VALUES('GK52','2','Και με την ανάστασή Σου<br/>Έγινες Πρωτότοκος<br/>Και την αιώνια ζωή Σου<br/>Σε εμάς την έδωσες<br/>Τώρα αναγεννημένοι<br/>Είμαστε παιδιά Θεού<br/>Δια του Πνεύματος αδέλφια<br/>Είμαστε εικόνα Σου<br/>',NULL,187962,2);
INSERT INTO stanza VALUES('GK52','3','Κάποτε ήσουν ο κόκκος<br/>Που θα έπεφτε στη γη<br/>Ώστε με το θάνατό Σου<br/>Να ανθίσει η ζωή<br/>Τώρα είμαστε ο καρπός Σου<br/>Σύμμορφοι και σύμφυτοι<br/>Σ’ έναν άρτο ζυμωμένοι<br/>Που Εσένα μαρτυρεί<br/>',NULL,187963,3);
INSERT INTO stanza VALUES('GK52','4','Είμαστε τ’ αντίγραφό Σου<br/>Σώμα Σου και νύμφη Σου<br/>Πλήρωμα και έκφρασή Σου<br/>Ο αιώνιος οίκος Σου<br/>Είμαστε η αύξησή Σου<br/>Η συνέχειά Σου στη γη<br/>Αιωνίως ενωμένοι<br/>Με Εσέ την Κεφαλή<br/>',NULL,187964,4);
INSERT INTO stanza VALUES('GK53','1','Ύψιστος ορισμός της χάριτος<br/>Είν’ ο Θεός μέσ’ απ’ τον Υιό σε μας<br/>Δεν είναι μόνο ένα απόκτημα<br/>Είναι ο Ίδιος η μερίδα μας<br/>',NULL,187965,1);
INSERT INTO stanza VALUES('GK53','2','Έγινε σάρκα να μπορούμε εμείς<br/>Να Τον απολαμβάνουμε εδώ<br/>Αυτή τη χάρη έδωσε ο Θεός<br/>Αυτός ο Ίδιος μέσ’ απ’ τον Χριστό<br/>',NULL,187966,2);
INSERT INTO stanza VALUES('GK53','3','Χάρη στον Παύλο ήταν ο Χριστός<br/>Όλα τα άλλα ήταν σκύβαλα<br/>Μ’ αυτή τη χάρη την αληθινή<br/>Υπερνικούσε τα εμπόδια<br/>',NULL,187967,3);
INSERT INTO stanza VALUES('GK53','4','Αυτή η χάρη – ο Χριστός σε μας<br/>Είναι στο πνεύμα μας η δύναμη<br/>Που μας βοηθάει για να κάνουμε<br/>Το θέλημά Του πάντοτε στη γη<br/>',NULL,187968,4);
INSERT INTO stanza VALUES('GK53','5','Αυτή τη χάρη – ζωντανός Χριστός<br/>Έχουμε ανάγκη εμείς να νιώσουμε<br/>Κύριε, είθε να γνωρίσουμε<br/>Μέσ’ απ’ αυτή να Σε βιώνουμε<br/>',NULL,187969,5);
INSERT INTO stanza VALUES('GK54','1','Κύριε, φύσηξε σε μένα<br/>Να Σ’ εισπνέω μάθε μου<br/>Πώς στον κόλπο Σου να εκπνέω<br/>Τη φθαρτή τη φύση μου<br/>',NULL,187970,1);
INSERT INTO stanza VALUES('GK54','chorus','Ναι, τη φύση μου εκπνέω<br/>Την αμαρτωλή<br/>Και εισπνέω, και εισπνέω<br/>Ό,τι είσ’ Εσύ<br/>',NULL,187971,2);
INSERT INTO stanza VALUES('GK54','2','Ό,τι ήμουν το εκπνέω<br/>Τώρα πλήρωσέ με Εσύ<br/>Τις δυνάμεις παραδίνω<br/>Και εισπνέω θεία ζωή<br/>',NULL,187972,3);
INSERT INTO stanza VALUES('GK54','3','Ναι, την αμαρτία εκπνέω<br/>Γιατί Εσύ τη βάσταξες<br/>Αγιότητα εισπνέω<br/>Τη ζωή που μου ’δωσες<br/>',NULL,187973,4);
INSERT INTO stanza VALUES('GK54','4','Και τη θλίψη μου εκπνέω<br/>Στη δική Σου αγκαλιά<br/>Και ανάπαυση εισπνέω<br/>Την ειρήνη, τη χαρά<br/>',NULL,187974,5);
INSERT INTO stanza VALUES('GK54','5','Τις ασθένειες μου εκπνέω<br/>Γιατί Εσύ τις βάσταξες<br/>Τώρα θεραπεία εισπνέω<br/>Όπως υποσχέθηκες<br/>',NULL,187975,6);
INSERT INTO stanza VALUES('GK54','6','Κάθε πόθο μου εκπνέω<br/>Στο αυτί Σου στοργικά<br/>Και το ρήμα Σου εισπνέω<br/>Που το φόβο μου σκορπά<br/>',NULL,187976,7);
INSERT INTO stanza VALUES('GK54','7','Με την κάθε εισπνοή μου<br/>Από Εσέ αντλώ ζωή<br/>Κύριε, φύσηξε το Πνεύμα<br/>Μέσα μου κάθε στιγμή<br/>',NULL,187977,8);
INSERT INTO stanza VALUES('GK55','1','Μέσ’ απ’ τη λάμψη<br/>Ήρθε ως τη φάτνη<br/>Σωτήρας και Θεός<br/>Το όνομά Του Ιησούς<br/>Ταπεινωμένος<br/>Στους δικούς Του ξένος<br/>Άνθρωπος θλίψης, πόνου και δακρύων<br/>',NULL,187978,1);
INSERT INTO stanza VALUES('GK55','chorus','Πώς Τον λατρεύω! Τον αγαπάω!<br/>Είν’ η ανάσα κι ο ήλιος μου!<br/>Δημιουργός μου και Λυτρωτής μου<br/>Είναι το πλήρωμα του Θεού<br/>',NULL,187979,2);
INSERT INTO stanza VALUES('GK55','2','Τι συγκατάβαση<br/>Για να μας λυτρώσει<br/>Όταν ελπίδα<br/>Δεν είχαμε καμιά<br/>Έγινε σάρκα<br/>Άφησε τη δόξα<br/>Για μένα πέθανε για να σωθώ<br/>',NULL,187980,3);
INSERT INTO stanza VALUES('GK55','3','Πρόθυμα ήρθε<br/>Τη μορφή μας πήρε<br/>Το αιώνιο σχέδιο<br/>Να γίνει φανερό<br/>Ω, τι μυστήριο!<br/>Σταυρικό μαρτύριο<br/>Και τώρα ξέρω πως είσ’ ο Θεός<br/>',NULL,187981,4);
INSERT INTO stanza VALUES('GK56','1','Αναζήτησε τον Κύριο<br/>Ψάξε μες στο πνεύμα σου<br/>Ζήτα κι άκου τη φωνή Του<br/>Κάτω από τη σκέπη Του<br/>',NULL,187982,1);
INSERT INTO stanza VALUES('GK56','chorus','Αναζήτησε τον Κύριο<br/>Ψάξε μες στο πνεύμα σου<br/>Ζήτα κι άκου τη φωνή Του<br/>Κάτω από τη σκέπη Του<br/>',NULL,187983,2);
INSERT INTO stanza VALUES('GK56','2','Αναζήτησε τον Κύριο<br/>Άνοιξε Του την ψυχή<br/>Δίχως κάλυμμα θωρώντας<br/>Με καρδιά ειλικρινή<br/>',NULL,187984,3);
INSERT INTO stanza VALUES('GK56','3','Αναζήτησε τον Κύριο<br/>Μ’ όλη σου την παρρησία<br/>Άγγιξε Τον, είν’ το Πνεύμα<br/>Με ευλάβεια και λατρεία<br/>',NULL,187985,4);
INSERT INTO stanza VALUES('GK56','4','Αναζήτησε τον Κύριο<br/>Δίχως πρόφαση καμιά<br/>Προσευχήσου με το πνεύμα<br/>Με επίγνωση βαθιά<br/>',NULL,187986,5);
INSERT INTO stanza VALUES('GK56','5','Αναζήτησε τον Κύριο<br/>Μένοντας καρτερικά<br/>Γνώρισε το θέλημά Του<br/>Παραδώσου αληθινά<br/>',NULL,187987,6);
INSERT INTO stanza VALUES('GK56','6','Αναζήτησε τον Κύριο<br/>Στην αγάπη ν’ αφεθείς<br/>Και το φως Του να διεισδύσει<br/>Αυτόν ν’ ακτινοβολείς<br/>',NULL,187988,7);
INSERT INTO stanza VALUES('GK57','1','Μόνη αλήθεια είναι ο Χριστός<br/>Σ’ όλη την κτίση και τον άνθρωπο<br/>Είναι ο δρόμος μας προς τον Θεό<br/>Ό,τι είν’ εκτός Του είν’ ψεύτικο<br/>',NULL,187989,1);
INSERT INTO stanza VALUES('GK57','2','Όλοι οι τύποι του παλιού καιρού<br/>Όλες οι ανάγκες του ανθρώπου<br/>Είναι μονάχα σκιές του Χριστού<br/>Απεικονίσεις του αληθινού<br/>',NULL,187990,2);
INSERT INTO stanza VALUES('GK57','3','Όλα! – Τα πάντα! – ματαιότητα<br/>Ο Κύριος είν’ πραγματικότητα<br/>Ό,τι κι αν έχουμε στη γη αυτή<br/>Δίχως Χριστό θα είμαστε κενοί<br/>',NULL,187991,3);
INSERT INTO stanza VALUES('GK57','4','Πράγματι Κύριος, πράγματι Θεός<br/>Πράγματι δύναμη μας είν’ Αυτός<br/>Πράγματι άρτος, πράγματι νερό<br/>Πράγματι η ζωή μας είν’ Αυτός<br/>',NULL,187992,4);
INSERT INTO stanza VALUES('GK57','5','Στις θεολογίες και στα δόγματα<br/>Ο Κύριος είν’ μόνη αλήθεια<br/>Όλες οι γνώσεις και τα γράμματα<br/>Δίχως Αυτόν είναι όλα νεκρά<br/>',NULL,187993,5);
INSERT INTO stanza VALUES('GK57','6','Χρόνος και χώρος είναι ο Χριστός<br/>Σ’ όλες τις φάσεις βρίσκεται Αυτός<br/>Όλα σ’ Αυτόν είναι πραγματικά<br/>Μες στους αιώνες και παντοτινά<br/>',NULL,187994,6);
INSERT INTO stanza VALUES('GK58','1','Γέμισέ με με το Πνεύμα<br/>γέμισέ με Κύριε<br/>με τη θεία παρουσία<br/>έλα κι επισκέψου με<br/>',NULL,187995,1);
INSERT INTO stanza VALUES('GK58','chorus','Πλήρωση, πλήρωση<br/>δώσ’ μου θεία πλήρωση<br/>άδειασέ με απ’ όλα τ’ άλλα<br/>δώσ’ μου θεία πλήρωση<br/>',NULL,187996,2);
INSERT INTO stanza VALUES('GK58','2','Συ μπορείς με τ’ Άγιο Πνεύμα<br/>να γεμίσεις την καρδιά<br/>τόση ανάγκη έχω Κύριε<br/>τη δική Σου λευτεριά<br/>',NULL,187997,3);
INSERT INTO stanza VALUES('GK58','3','Μ’ όλη την αδυναμία<br/>γονατίζω μπρος σ’ Εσέ<br/>Συ τ’ αδύναμό μου πνεύμα<br/>έλα και δυνάμωσε<br/>',NULL,187998,4);
INSERT INTO stanza VALUES('GK58','4','Γιάτρεψε, ξεκούρασέ με<br/>πλύνε κι ανακαίνισε<br/>Φίλος είσαι και Σωτήρας<br/>άγγιξε και σώσε με<br/>',NULL,187999,5);
INSERT INTO stanza VALUES('GK59','1','Πατέρα, σαν το αειθαλές<br/>Ποτέ δεν φθείρεσαι<br/>Σαν τη δροσιά κάθε πρωί<br/>Ανανεώνεσαι<br/>',NULL,188000,1);
INSERT INTO stanza VALUES('GK59','chorus','Πατέρα, ω αναλλοίωτε!<br/>Δεν γνώρισες φθορά<br/>Μες στους αιώνες διαρκώς<br/>Εσύ είσαι δροσιά<br/>',NULL,188001,2);
INSERT INTO stanza VALUES('GK59','2','Ακμαίος μένεις, ω Θεέ!<br/>Ο χρόνος κι αν περνά<br/>Με Σένα όλα είναι νέα<br/>Είν’ ολοκαίνουργια<br/>',NULL,188002,3);
INSERT INTO stanza VALUES('GK59','3','Όλες οι ευλογίες Σου<br/>Είναι μια νέα αρχή<br/>Καινούργια η Διαθήκη Σου<br/>Κι όλοι Σου οι οδοί<br/>',NULL,188003,4);
INSERT INTO stanza VALUES('GK59','4','Δικά Σου νέα κτίσματα<br/>Είμαστε τώρα εμείς<br/>Με νέο πνεύμα, νέα καρδιά<br/>Ζωή μάς χορηγείς<br/>',NULL,188004,5);
INSERT INTO stanza VALUES('GK59','5','Νέος ουρανός και νέα γη<br/>Νέα πόλη θα φανεί<br/>Και κάθε μήνα νέους καρπούς<br/>Σε μας θα χορηγεί<br/>',NULL,188005,6);
INSERT INTO stanza VALUES('GK59','6','Πατέρα, η νεότης Σου<br/>Ω! Δεν παρέρχεται<br/>Μ’ αιώνια νέα άσματα<br/>Θα Σε λατρεύουμε<br/>',NULL,188006,7);
INSERT INTO stanza VALUES('GK60','1','Σε υμνούμε, ω Πατέρα<br/>Που χάρη έδωσες<br/>Για την ευδοκία Σου<br/>Μας υιοθέτησες<br/>Υιοί προορισμένοι<br/>Να ’μαστε ένδοξοι<br/>Με τον αγαπητό Σου<br/>Να ’μαστε σύμμορφοι<br/>',NULL,188007,1);
INSERT INTO stanza VALUES('GK60','2','Πατέρα μας Εσύ<br/>Μες στον Μονογενή<br/>Το Πνεύμα μάς χαρίζεις<br/>Σ’ αιώνια κατοχή<br/>Σύντομα και για πάντα<br/>Όμοιοι κατεξοχήν<br/>Χριστό θ’ αντανακλούμε<br/>Αιώνια, Αμήν!<br/>',NULL,188008,2);
INSERT INTO stanza VALUES('GK61','1','Ο Τριαδικός Θεός ζει μέσα μας<br/>Ως θαυμάσιο Πνεύμα σε μας<br/>Είμαστε αναμιγμένοι με Αυτόν<br/>Είν’ το Πνεύμα το ζωοποιό<br/>',NULL,188009,1);
INSERT INTO stanza VALUES('GK61','chorus','Ω! Τι θαυμάσιο Πνεύμα σε μας!<br/>Τι θαυμάσιο Πνεύμα σε μας!<br/>Εν Χριστώ ο Θεός, το Πνεύμα είναι Αυτός<br/>Τι θαυμάσιο Πνεύμα σε μας!<br/>',NULL,188010,2);
INSERT INTO stanza VALUES('GK61','2','Κράζουμε «Αββά Πατέρα» μέσα μας<br/>Με το υπέροχο Πνεύμα σε μας<br/>Του Υιού το Πνεύμα κράζει σε Αυτόν<br/>Είν’ το Πνεύμα το ζωοποιό<br/>',NULL,188011,3);
INSERT INTO stanza VALUES('GK61','3','Ο Ιησούς Χριστός ζει τώρα μέσα μας<br/>Ως το υπέροχο Πνεύμα σε μας<br/>Σε Πνεύμα έχει μεταμορφωθεί<br/>Για τη δική μας απόλαυση<br/>',NULL,188012,4);
INSERT INTO stanza VALUES('GK61','4','Τώρα Πνεύμα αληθείας έχουμε<br/>Είν’ το υπέροχο Πνεύμα σε μας<br/>Κάνει τον Χριστό τόσο αληθινό<br/>Ως το Πνεύμα το ζωοποιό<br/>',NULL,188013,5);
INSERT INTO stanza VALUES('GK61','5','Αναζωπυρώνουμε το χάρισμα<br/>Το υπέροχο Πνεύμα σε μας<br/>«Κύριε Ιησού» επικαλούμαστε<br/>Και εν πνεύματι χαιρόμαστε<br/>',NULL,188014,6);
INSERT INTO stanza VALUES('GK62','1','Στ’ Άγια των Αγίων μπρος στο θρόνο Του<br/>Ρέει η χάρη σαν ποταμός<br/>Στ’ Άγια των Αγίων μπρος στο θρόνο Του<br/>Ρέει η χάρη σαν ποταμός<br/>Αλληλούια! Αλληλούια! Ρέει η χάρη σαν ποταμός<br/>Αλληλούια! Αλληλούια! Ρέει η χάρη σαν ποταμός<br/>',NULL,188015,1);
INSERT INTO stanza VALUES('GK62','2','Στ’ Άγια των Αγίων μπρος στη θέα Του<br/>Μέσα μου λάμπει το φως<br/>Στ’ Άγια των Αγίων μπρος στη θέα Του<br/>Μέσα μου λάμπει το φως<br/>Αλληλούια! Αλληλούια! Μέσα μου λάμπει το φως<br/>Αλληλούια! Αλληλούια! Μέσα μου λάμπει το φως<br/>',NULL,188016,2);
INSERT INTO stanza VALUES('GK62','3','Στρέψε βαθιά μες στο πνεύμα σου<br/>Πιες απ’ την κρήνη ζωής<br/>Στρέψε βαθιά μες στο πνεύμα σου<br/>Πιες απ’ την κρήνη ζωής<br/>Αλληλούια! Αλληλούια! Πιες απ’ την κρήνη ζωής<br/>Αλληλούια! Αλληλούια! Πιες απ’ την κρήνη ζωής<br/>',NULL,188017,3);
INSERT INTO stanza VALUES('GK63','1','Διψά η καρδιά μου, το πνεύμα πεινά<br/>Σε Σένα έρχομαι Κύριε ξανά<br/>Ό,τι χρειάζομαι είσαι Εσύ<br/>Δίψα και πείνα ικανοποιείς<br/>',NULL,188018,1);
INSERT INTO stanza VALUES('GK63','chorus','Θρέψε με, Κύριε, δώσ’ μου να πιώ<br/>Συ με χορταίνεις, με ξεδιψάς<br/>Πλημμύρισέ με, με κάθε χαρά<br/>Συ με χορταίνεις, με ξεδιψάς<br/>',NULL,188019,2);
INSERT INTO stanza VALUES('GK63','2','Νερό ζωής και τροφή μου είσαι<br/>Το πνεύμα μου αναζωπύρωσε<br/>Πίνω από Σένα και τρέφομαι,<br/>Σ’ απολαμβάνω και προσεύχομαι<br/>',NULL,188020,3);
INSERT INTO stanza VALUES('GK63','3','Λόγος και πλήρωμα Θεού Εσύ<br/>Πνεύμα είσαι και δική μου ζωή<br/>Απολαμβάνω το Λόγο ως τροφή<br/>Νερό ζωής και το Πνεύμα είσαι Εσύ<br/>',NULL,188021,4);
INSERT INTO stanza VALUES('GK63','4','Απ’ τα ουράνια ήρθες ως τροφή<br/>Προσφορά είσαι για μένα άφθονη<br/>Βράχος σχισμένος γεμάτος νερό,<br/>που ρέει για μένα ως ποταμός<br/>',NULL,188022,5);
INSERT INTO stanza VALUES('GK63','5','Στο Λόγο Πνεύμα είσαι και ζωή<br/>Τρέφομαι έτσι με ό,τι είσαι Εσύ<br/>Ως το Πνεύμα μες στο πνεύμα μου ζεις<br/>εκεί με ξεδιψάς και με τρέφεις<br/>',NULL,188023,6);
INSERT INTO stanza VALUES('GK63','6','Σ’ απολαμβάνω μες στο Λόγο Σου<br/>εδώ χορταίνω με τον πλούτο Σου<br/>Στρέφομαι τώρα στο πνεύμα μου εγώ<br/>να ξεδιψάσω τη δίψα μου εδώ<br/>',NULL,188024,7);
INSERT INTO stanza VALUES('GK63','7','Πίνοντας, τρώγοντας, Κύριε, από Σε<br/>Με προσευχή έρχομαι εις Εσέ<br/>Πάντοτε τρέφομαι απ’ το Λόγο<br/>Και πίνω απ’ της προσευχής το νερό<br/>',NULL,188025,8);
INSERT INTO stanza VALUES('GK63','8','Με το Πνεύμα Σου με πλημμύρισες<br/>και με το Λόγο Σου με πλήρωσες<br/>Κύριε, με χαροποιείς πάντοτε<br/>όπως κανένας ποτέ άλλοτε<br/>',NULL,188026,9);
INSERT INTO stanza VALUES('GK64','1','Στα ουράνια καθισμένος<br/>Ο Ιησούς στο θρόνο Του<br/>Άνθρωπος στεφανωμένος<br/>Με τη δόξα του Θεού<br/>',NULL,188027,1);
INSERT INTO stanza VALUES('GK64','2','Του Θεού απεσταλμένος<br/>Το σχέδιο να εκπληρωθεί<br/>Ανθρωπίνως να πεθάνει<br/>Και μετά να αναστηθεί<br/>',NULL,188028,2);
INSERT INTO stanza VALUES('GK64','3','Απαρνήθηκε τη δόξα<br/>Ταπεινός ήταν στη γη<br/>Για να γίνουμε ναός Του<br/>Και σε μας να κατοικεί<br/>',NULL,188029,3);
INSERT INTO stanza VALUES('GK64','4','Μια ανάμειξη θαυμάσια<br/>Ο Θεός κι ο άνθρωπος<br/>Να εκφράζεται ο Πατέρας<br/>Να δοξάζεται ο Υιός<br/>',NULL,188030,4);
INSERT INTO stanza VALUES('GK64','5','Στεφανώθηκε με δόξα<br/>Έστειλε το Πνεύμα Του<br/>Για να διακηρύττει το έργο<br/>Και το Πρόσωπο του Ιησού<br/>',NULL,188031,5);
INSERT INTO stanza VALUES('GK64','6','Ο Ιησούς ο δοξασμένος<br/>Ένωσε τ’ αδέλφια Του<br/>Και μες του Ιησού το Πνεύμα<br/>Οι πιστοί συγκατοικούν<br/>',NULL,188032,6);
INSERT INTO stanza VALUES('GK64','7','Στον ουράνιο θρόνο τώρα<br/>Κάθεται ένας άνθρωπος<br/>Στεφανώθηκε με δόξα<br/>Ο Σωτήρας μας Χριστός<br/>',NULL,188033,7);
INSERT INTO stanza VALUES('GK65','1','Για να λάμψει το ευαγγέλιο<br/>Πρέπει να ’χουμε ροή<br/>Μαρτυρία ναν’ η ζωή μας<br/>Να σωθούν αμαρτωλοί<br/>',NULL,188034,1);
INSERT INTO stanza VALUES('GK65','chorus','Κύριε, από μας ας ρέει<br/>Ζωντανό νερό στη γη<br/>Μέσ’ από τα αγγεία Σου<br/>Ώστε ο κόσμος ν’ αγγιχθεί<br/>',NULL,188035,2);
INSERT INTO stanza VALUES('GK65','2','Μια ζωή που ξεχωρίζει<br/>Ώστε να πειστούν κι αυτοί<br/>Τη ζωή να χορηγούμε<br/>Στη δική τους την ψυχή<br/>',NULL,188036,3);
INSERT INTO stanza VALUES('GK65','3','Πάντα μένοντας στον Κύριο<br/>Για ν’ αυξάνει ο καρπός<br/>Από την πηγή εντός μας<br/>Ν’ αναβλύζει ο Χριστός<br/>',NULL,188037,4);
INSERT INTO stanza VALUES('GK65','4','Κύρηκας ναν’ η ζωή μας<br/>Τον Χριστό να διαλαλεί<br/>Όχι δόγματα και τύπους<br/>Μα να σπέρνουμε ζωή<br/>',NULL,188038,5);
INSERT INTO stanza VALUES('GK66','1','Κύριε, είσαι ο Νυμφίος<br/>Του Θεού ο εκλεκτός<br/>Και για μας που Σε ποθούμε<br/>Είσαι ο Αγαπητός<br/>',NULL,188039,1);
INSERT INTO stanza VALUES('GK66','2','Σε δοξολογούμε, Κύριε<br/>Είσαι τόσο θαυμαστός<br/>Στις καρδιές μας παραμένεις<br/>Θησαυρός μοναδικός<br/>',NULL,188040,2);
INSERT INTO stanza VALUES('GK66','3','Είσαι απ’ όλους πιο ωραίος<br/>Τόσο πράος και γλυκός<br/>Ποιός να συγκριθεί με Σένα<br/>Δεν υπάρχει άνθρωπος<br/>',NULL,188041,3);
INSERT INTO stanza VALUES('GK66','4','Ευωδιάζουν μύρο όλα<br/>Τα ιμάτια που φοράς<br/>Και τα χείλη Σου, καλέ μας<br/>Στάζουν χάρη όπου πας<br/>',NULL,188042,4);
INSERT INTO stanza VALUES('GK66','5','Με το λάδι ευφροσύνης<br/>Ο Θεός Σε έχρισε<br/>Σ’ έλεφάντινα παλάτια<br/>Ύμνοι Θα υψώνονται<br/>',NULL,188043,5);
INSERT INTO stanza VALUES('GK66','6','Δοξασμένος είσαι τώρα<br/>Ύστερα απ’ τη νίκη Σου<br/>Βασιλιάς εις τον αιώνα<br/>Κάθεσαι στο θρόνο Σου<br/>',NULL,188044,6);
INSERT INTO stanza VALUES('GK66','7','Η επιθυμία είσαι<br/>Όλων των λαών της γης<br/>Ωραιότερος απ’ όλους<br/>Σου αξίζει η τιμή<br/>',NULL,188045,7);
INSERT INTO stanza VALUES('GK67','1','Πέθανα με τον Σωτήρα<br/>Στα νερά του θανάτου θάφτηκα<br/>Δεν μ’ ελκύει πια ο κόσμος<br/>Καταργήθηκε η ισχύς αυτού<br/>Αναστήθηκα μ’ Αυτόν<br/>Για να περπατήσω σε νέα ζωή<br/>Με ζωοποιεί το Πνεύμα τώρα<br/>Κοινωνία να ’χουμε στο Σώμα Του<br/>',NULL,188046,1);
INSERT INTO stanza VALUES('GK68','1','Κύριε, η χάρη Σου<br/>Άλλαξε την καρδιά<br/>Η φύση η αμαρτωλή<br/>Δεν κυβερνάει πια<br/>',NULL,188047,1);
INSERT INTO stanza VALUES('GK68','chorus','Η χάρη Σου μου αρκεί<br/>Και με ενισχύει<br/>Κύριε, είσαι στο πνεύμα μου-<br/>Χάρη αστείρευτη<br/>',NULL,188048,2);
INSERT INTO stanza VALUES('GK68','2','Και στη στενή οδό<br/>Με κατευθύνει αυτή<br/>Τα βήματά μου οδηγεί<br/>Και δεν καθυστερεί<br/>',NULL,188049,3);
INSERT INTO stanza VALUES('GK68','3','Ο ύψιστος Θεός<br/>Γεννήθηκε στη γη<br/>Η χάρη ενσαρκώθηκε<br/>Εντός μας τώρα ζει<br/>',NULL,188050,4);
INSERT INTO stanza VALUES('GK68','chorus','Είμαι αυτό που είμαι<br/>Με τη χάρη Σου<br/>Η αιώνια μερίδα μου-<br/>Η χάρη του Θεού<br/>',NULL,188051,5);
INSERT INTO stanza VALUES('GK69','1','Έχω λάβει, Κύριέ μου<br/>Τη χαρά του ουρανού<br/>Τώρα κάνε με κανάλι<br/>Του νερού του ζωντανού<br/>',NULL,188052,1);
INSERT INTO stanza VALUES('GK69','chorus','Αγωγός Σου ευλογημένος<br/>Πλήρης απ’ τη χάρη Σου<br/>Ρέεις μέσα από μένα<br/>Παντού και παντοτινά<br/>',NULL,188053,2);
INSERT INTO stanza VALUES('GK69','2','Αγωγός Σου είμαι τώρα<br/>Τις ψυχές να ξεδιψώ<br/>Και το Ευαγγέλιό Σου<br/>Να κηρύττω όπου βρεθώ<br/>',NULL,188054,3);
INSERT INTO stanza VALUES('GK69','3','Αδειανός και λυτρωμένος<br/>Σκεύος καθαρό για Εσέ<br/>Με τη χάρη, το έλεός Σου<br/>Όχι με δική μου ισχύ<br/>',NULL,188055,4);
INSERT INTO stanza VALUES('GK69','4','Από εγώ και αμαρτία<br/>Δια της χάρης μ’ έσωσες<br/>Μ’ απολύτρωσες Χριστέ μου<br/>Στα πλούτη Σου μ’ έβαλες<br/>',NULL,188056,5);
INSERT INTO stanza VALUES('GK69','5','Παραδίνεται η καρδιά μου<br/>Για να την πληροίς Εσύ<br/>Απ’ το πνεύμα μου να ρέουν<br/>Ποταμοί νερού ζωής<br/>',NULL,188057,6);
INSERT INTO stanza VALUES('GK70','1','Σκάψε την πηγή μου<br/>Κύριε, ν’ αναβλύσει<br/>Το νερό σε μένα<br/>Πλούσια να κυλήσει<br/>',NULL,188058,1);
INSERT INTO stanza VALUES('GK70','2','Ο Χριστός η Πέτρα<br/>Τι νερό παρέχει<br/>Μα η δική μου βρύση<br/>Πώς έχει στερέψει!<br/>',NULL,188059,2);
INSERT INTO stanza VALUES('GK70','3','Με την προσευχή μου<br/>Τώρα εγώ θα σκάψω<br/>Και το Πνεύμα τ’ Άγιο<br/>Θ’ απελευθερώσω<br/>',NULL,188060,3);
INSERT INTO stanza VALUES('GK70','4','Δεν είναι ανάγκη<br/>Πάλι να χτυπήσω<br/>Τον Χριστό την Πέτρα<br/>Μονάχα να σκάψω<br/>',NULL,188061,4);
INSERT INTO stanza VALUES('GK70','5','Έχω ανάγκη μόνο<br/>Απ’ το Άγιο Πνεύμα<br/>Το νερό να τρέχει<br/>Γάργαρο σε μένα<br/>',NULL,188062,5);
INSERT INTO stanza VALUES('GK70','6','Ναι, βαθιά θα σκάψω<br/>Ό,τι έχω φράξει<br/>Με ορμή ο Λόγος<br/>Ζωντανός να ρέει<br/>',NULL,188063,6);
INSERT INTO stanza VALUES('GK70','7','Σκάψε την πηγή μου<br/>Κύριε, ν’ αναβλύσει<br/>Το νερό σε μένα<br/>Πλούσια να κυλήσει<br/>',NULL,188064,7);
INSERT INTO stanza VALUES('GK71','1','Στο φως Του τώρα ζω<br/>Σε κοινωνία γλυκιά<br/>Βλέπω τη δόξα Του<br/>Στο πρόσωπο Αυτού<br/>Το Πνεύμα ακολουθώ<br/>Δοξάζω συνεχώς<br/>Στο φως Του τώρα ζω<br/>',NULL,188065,1);
INSERT INTO stanza VALUES('GK72','1','Σπέρνουμε τους σπόρους του ευαγγελίου<br/>Κάθε μέρα στη δροσιά του Πνεύματος<br/>Όταν έρθει η ώρα της συγκομιδής μας<br/>Θα χαιρόμαστε την πλούσια σοδειά<br/>',NULL,188066,1);
INSERT INTO stanza VALUES('GK72','chorus','Πλούσια σοδειά, πλούσια σοδειά<br/>Θα χαιρόμαστε την πλούσια σοδειά<br/>Πλούσια σοδειά, πλούσια σοδειά<br/>Θα χαιρόμαστε την πλούσια σοδειά<br/>',NULL,188067,2);
INSERT INTO stanza VALUES('GK72','2','Σπέρνοντας στη ζέστη, σπέρνοντας στο ψύχος<br/>Δεν φοβόμαστε τον άσχημο καιρό<br/>Τελείωσε ο κόπος, δεν μοχθούμε άλλο<br/>Θα χαιρόμαστε την πλούσια σοδειά<br/>',NULL,188068,3);
INSERT INTO stanza VALUES('GK72','3','Τόσες δυσκολίες, στην κοιλάδα θρήνων<br/>Την μεταμορφώνουν σε πηγή νερών<br/>Σαν έρθει η ώρα της συγκομιδής μας<br/>Θα χαιρόμαστε μαζί με τον Κύριο<br/>',NULL,188069,4);
INSERT INTO stanza VALUES('GK73','1','Σε λατρεύουμε, Πατέρα<br/>Σε υμνούμε ολημερίς<br/>Άγιο είναι το Όνομά Σου<br/>Είσαι μεγαλοπρεπής<br/>',NULL,188070,1);
INSERT INTO stanza VALUES('GK73','2','Τρυφερή είναι η καρδιά Σου<br/>Οι οδοί Σου δίκαιοι<br/>Ο Υιός Σου μεταγγίζει<br/>Την αγία Σου ζωή<br/>',NULL,188071,2);
INSERT INTO stanza VALUES('GK73','3','Με το αίμα του Κυρίου<br/>Δια παντός μας άγιασες<br/>Δια του Λόγου της αλήθειας<br/>Όλους μας ξεχώρισες<br/>',NULL,188072,3);
INSERT INTO stanza VALUES('GK73','4','Συ μας έκανες αγίους<br/>Δια του Αγίου Πνεύματος<br/>Πνεύμα και ψυχή και σώμα<br/>Θ’ αγιαστούν ολοσχερώς<br/>',NULL,188073,4);
INSERT INTO stanza VALUES('GK73','5','Δια της χάρης Σου, Πατέρα<br/>Μέσα μας ζει ο Ιησούς<br/>Μέτοχους Εσύ μας κάνεις<br/>Της αγιοσύνης Σου<br/>',NULL,188074,5);
INSERT INTO stanza VALUES('GK73','6','Όταν στην άγια πόλη<br/>Κοινωνοί Σου θα ’μαστε<br/>Πάντα θα ομολογούμε<br/>«Άγιος Είσαι» ω Θεέ!<br/>',NULL,188075,6);
INSERT INTO stanza VALUES('GK74','1','Στην κοινωνία, Κύριε, μ’ Εσέ<br/>Δείχνεις τη δόξα Σου<br/>Ελκύεις την ψυχή<br/>Μου μιλάς με στοργή<br/>Κράτα με, Εσύ, κοντά σ’ Εσέ<br/>',NULL,188076,1);
INSERT INTO stanza VALUES('GK74','2','Στην κοινωνία, Κύριε, μ’ Εσέ<br/>Δεν ακούω πια<br/>Του κόσμου τη βοή<br/>Μα του Θεού φωνή<br/>Κράτα με, Εσύ, κοντά σ’ Εσέ<br/>',NULL,188077,2);
INSERT INTO stanza VALUES('GK74','3','Στην κοινωνία, Κύριε, μ’ Εσέ<br/>Δεν με αγγίζει πια<br/>Καμμία έγνοια<br/>Καμμία μέριμνα<br/>Κράτα με, Εσύ, κοντά σ’ Εσέ<br/>',NULL,188078,3);
INSERT INTO stanza VALUES('GK74','4','Στην κοινωνία, Κύριε, μ’ Εσέ<br/>Δεν Σε αμφισβητώ<br/>Δεν έχω φόβο πια<br/>Αμφιβολία καμιά<br/>Κράτα με, Εσύ, κοντά σ’ Εσέ<br/>',NULL,188079,4);
INSERT INTO stanza VALUES('GK74','5','Στην κοινωνία, Κύριε, μ’ Εσέ<br/>Φωτίζεις την καρδιά<br/>Διώχνεις την καταχνιά<br/>Για να ’χω διαύγεια<br/>Κράτα με, Εσύ, κοντά σ’ Εσέ<br/>',NULL,188080,5);
INSERT INTO stanza VALUES('GK74','6','Στην κοινωνία, Κύριε, μ’ Εσέ<br/>Στο φως Σου περπατώ<br/>Μόνο Εσέ να δω<br/>Σ’ Εσέ ανήκω εγώ<br/>Κράτα με, Εσύ, κοντά σ’ Εσέ<br/>',NULL,188081,6);
INSERT INTO stanza VALUES('GK74','7','Στην κοινωνία, Κύριε, μ’ Εσέ<br/>Αστέρας φωτεινός<br/>Φωτίζει συνεχώς<br/>Στο σκότος της νυκτός<br/>Κράτα με, Εσύ, κοντά σ’ Εσέ<br/>',NULL,188082,7);
INSERT INTO stanza VALUES('GK75','1','Ο Θεός μάς μεταμορφώνει<br/>Με το Πνεύμα του Ιησού<br/>Για να μας κάνει σύμμορφους<br/>Της εικόνας του Υιού<br/>',NULL,188083,1);
INSERT INTO stanza VALUES('GK75','chorus','Μεταμόρφωσε το νου μας<br/>βουλή και συναίσθημα<br/>Με το Πνεύμα πλήρωσέ μας<br/>Κύριε, παντοτινά<br/>',NULL,188084,2);
INSERT INTO stanza VALUES('GK75','2','Στο πνεύμα μας αναγέννησε<br/>Με το Πνεύμα της ζωής<br/>Αλλά πρέπει να μεταμορφώσει<br/>Και τα μέρη της ψυχής<br/>',NULL,188085,3);
INSERT INTO stanza VALUES('GK75','3','Η ζωή Του εξαπλώνεται<br/>Μέσα σ’ όλη την ψυχή<br/>Πλήρως να μας ανακαινίζει<br/>Στην καρδιά να κατοικεί<br/>',NULL,188086,4);
INSERT INTO stanza VALUES('GK75','4','Δια της δύναμης του Πνεύματος<br/>Μεταμορφωνόμαστε<br/>Στην εικόνα Του την ένδοξη<br/>Σύμμορφοι γινόμαστε<br/>',NULL,188087,5);
INSERT INTO stanza VALUES('GK75','5','Η ζωή Του μας αγιάζει<br/>Για να γίνουμε ώριμοι,<br/>Για να φτάσουμε στο ανάστημά Του<br/>Κυριεύει την ψυχή<br/>',NULL,188088,6);
INSERT INTO stanza VALUES('GK76','1','Τι θαύμα! Τι μυστήριο!<br/>Οστά και σάρκα πήρε Αυτός<br/>Ένωση ανθρώπου και Θεού<br/>Να γίνει ο άνθρωπος Θεός<br/>Ο πόθος Του θα εκπληρωθεί<br/>Ο στόχος Του ο ύψιστος<br/>',NULL,188089,1);
INSERT INTO stanza VALUES('GK76','2','Ναι, έγινε Θεάνθρωπος<br/>Κι εγώ Θεός μέσω Αυτού<br/>Αντίγραφό Του στη ζωή<br/>Μα όχι στη Θεότητα<br/>Τις αρετές Του μου ’δωσε<br/>Να είμαι η εικόνα Του<br/>',NULL,188090,2);
INSERT INTO stanza VALUES('GK76','3','Δεν ζω πλέον μόνος μου εγώ<br/>Μα εγώ κι ο Θεός μαζί<br/>Τώρα με όλους τους πιστούς<br/>Τον οίκο Του οικοδομεί<br/>Είμαστε εμείς το Σώμα Του<br/>Και η δική Του έκφραση<br/>',NULL,188091,3);
INSERT INTO stanza VALUES('GK76','4','Η Ιερουσαλήμ η έξοχη<br/>Θα ’ναι η ολοκλήρωση<br/>Ο τριμερής ο άνθρωπος<br/>Και ο Θεός θα ζουν μαζί<br/>Οι δύο τους θα αποτελούν<br/>Μια αμοιβαία κατοικία<br/>Η δόξα του Θεού σ’ αυτόν<br/>Θα φαίνεται αιώνια<br/>',NULL,188092,4);
INSERT INTO stanza VALUES('GK77','1','Κεραμέας ικανός<br/>Είσαι, Κύριε, Εσύ<br/>Κτίστης καταπληκτικός<br/>Που με δόξα οικοδομεί<br/>Κι εγώ, λίθος ζωντανός<br/>Και ταυτόχρονα πυλός<br/>Είμαι τώρα σκεύος Σου<br/>Κι ο δικός Σου ο ναός<br/>',NULL,188093,1);
INSERT INTO stanza VALUES('GK77','2','Ναι, μας έκανες πυλό<br/>Μα, να μοιάζουμε Εσύ θες<br/>Με πολύτιμο χρυσό<br/>Και με πέτρες ακριβές<br/>Ύστερα απ’ το κτίσιμο<br/>Νύφη Σου θα είμαστε<br/>Και μ’ Εσένα, Κύριε<br/>Ένα Σώμα θα ’μαστε<br/>',NULL,188094,2);
INSERT INTO stanza VALUES('GK77','3','Σκόρπιες πέτρες δεν ποθείς<br/>Μα μια τέλεια οικοδομή<br/>Έναν οίκο ένδοξο<br/>Για να κατοικείς Εσύ<br/>Ω Χριστέ, Εσύ ποθείς<br/>Εκκλησία στερεή<br/>Τα κρυφά τα πλούτη Σου<br/>Και το φως Σου να ’ναι εκεί<br/>',NULL,188095,3);
INSERT INTO stanza VALUES('GK77','4','Να ’μαστε πνευματικοί<br/>Όμως, όχι ατομικά<br/>Μα μαζί να εκφράζουμε<br/>Τη δική Σου την καρδιά<br/>Μέλη διάσπαρτα ποτέ<br/>Να Σ’ εκφράσουν δεν μπορούν<br/>Για να ’ρθει πληρότητα<br/>Πρέπει να οικοδομηθούν<br/>',NULL,188096,4);
INSERT INTO stanza VALUES('GK77','5','Κύριε, με τα μέλη Σου<br/>Θέλω να οικοδομηθώ<br/>Όλα για να συνεργούν<br/>Στο δικό Σου σχέδιο<br/>Μόνο δώρα κι εμπειρίες<br/>Η καρδιά μου δεν ποθεί<br/>Μόνο ο οίκος Σου μετρά<br/>Και να δοξαστείς Εσύ<br/>',NULL,188097,5);
INSERT INTO stanza VALUES('GK78','1','Ω, η εκκλησία του Κυρίου είναι ένδοξη<br/>Και χαιρόμαστε που είμαστε σ’ αυτήν<br/>Ένα Σώμα μες το σύμπαν κι αυτό είμαστε εμείς<br/>Αλληλούια, εν Χριστώ όλοι μαζί!<br/>Αλληλούια για το Σώμα!<br/>Είμαστε εμείς το Σώμα!<br/>Πλήρως ζούμε για το Σώμα<br/>Αλληλούια, εν Χριστώ όλοι μαζί!<br/>',NULL,188098,1);
INSERT INTO stanza VALUES('GK78','2','Όχι μια ατομική ζωή, αλλά συλλογική -<br/>Του Θεού να ’ναι η τέλεια έκφραση<br/>Όχι εκκλησίες μεμονωμένες, μα όλες μαζί -<br/>Αλληλούια, τώρα είμαστε σ’ αυτήν!<br/>Αλληλούια για το Σώμα!<br/>Τρέμει ο εχθρός το Σώμα!<br/>Νικηφόροι μες στο Σώμα!<br/>Αλληλούια, τώρα είμαστε σ’ αυτό!<br/>',NULL,188099,2);
INSERT INTO stanza VALUES('GK78','3','Οι επτά χρυσές λυχνίες έχουν φύση θεϊκή -<br/>Δεν θα βρεις στο Σώμα ύλη φυσική<br/>Η λυχνία καίει όταν είμαστε όλοι θεϊκοί -<br/>Αλληλούια, τώρα ακτινοβολεί!<br/>Αλληλούια για το Σώμα!<br/>Τις λυχνίες μες στο Σώμα!<br/>Για το ένδοξο το Σώμα!<br/>Αλληλούια, τώρα ακτινοβολεί!<br/>',NULL,188100,3);
INSERT INTO stanza VALUES('GK78','4','Πώς θα είμαστε ενωμένοι, θεϊκοί και φωτεινοί;<br/>Αλληλούια, ο Ιησούς ναν’ η τροφή!<br/>Είν’ Αυτός το δέντρο της ζωής, το μάννα κι η γιορτή -<br/>Αλληλούια, ο Ιησούς είν’ η τροφή!<br/>Ο Ιησούς που μας ενώνει!<br/>Ο Ιησούς που μας αγιάζει!<br/>Ο Ιησούς που μας φωτίζει!<br/>Αλληλούια, ο Ιησούς είν’ η τροφή!<br/>',NULL,188101,4);
INSERT INTO stanza VALUES('GK79','1','Από του Αδάμ τη φύση<br/>Τώρα είμ’ ελεύθερος<br/>Κτίσε με, με τους αγίους<br/>Να ’μαστε ναός λαμπρός<br/>Ελευθέρωσέ με, Κύριε<br/>Από ανεξαρτησία<br/>Κι από πάθη για να έχεις<br/>Τη δική Σου κατοικία<br/>',NULL,188102,1);
INSERT INTO stanza VALUES('GK79','2','Η ροή Σου με αυξάνει<br/>Μ’ όλους τους αγίους μαζί<br/>Στη δική Σου παρουσία<br/>Θα ’μαστε όλοι σύμμορφοι<br/>Και στο σώμα λειτουργούμε<br/>Όπως οδηγείς Εσύ<br/>Με χαρά υπηρετούμε<br/>Τη δική Σου τη βουλή<br/>',NULL,188103,2);
INSERT INTO stanza VALUES('GK79','3','Δεν καυχιέμαι για τις γνώσεις<br/>Ούτε για την πείρα μου<br/>Προτιμώ να υπακούω<br/>Σ’ ό,τι λέει το Σώμα Σου<br/>Αυξανόμενος σ’ Εσένα<br/>Να ’σαι Συ η κεφαλή<br/>Όλοι μας συνδεδεμένοι<br/>Στη δική Σου οικοδομή<br/>',NULL,188104,3);
INSERT INTO stanza VALUES('GK79','4','Και το Πνεύμα Σου μας δίνει<br/>Κάθε μέρα δύναμη<br/>Η δική Σου η αγάπη<br/>Πάντα μας οικοδομεί<br/>Απ’ τα πλούτη Σου λαμβάνω<br/>Με τα Σα να πληρωθώ<br/>Να ωριμάσω και να έχεις<br/>Το δικό Σου αντίγραφο<br/>',NULL,188105,4);
INSERT INTO stanza VALUES('GK79','5','Να ’μαι στου Θεού τον οίκο<br/>Και στο Σώμα Σου ποθώ<br/>Κάποτε με τους αγίους<br/>Ναι, τη δόξα Σου να δω<br/>Και η νύφη, η Άγια πόλη<br/>Να εμφανιστεί στη γη<br/>Της χρυσής λυχνίας το φως<br/>Η δική Σου έκφραση<br/>',NULL,188106,5);
INSERT INTO stanza VALUES('GK80','1','Ω, τι ένδοξο το Πνεύμα<br/>Που ζει τώρα μέσα μας!<br/>Την αλήθεια αποκαλύπτει<br/>Με φωτίζει, μ’ οδηγεί<br/>',NULL,188107,1);
INSERT INTO stanza VALUES('GK80','chorus','Πλήρωση, πλήρωση<br/>Δώσ’ μου θεία πλήρωση!<br/>Άδειασέ με απ’ όλα τ’ άλλα<br/>Δώσ’ μου θεία πλήρωση!<br/>',NULL,188108,2);
INSERT INTO stanza VALUES('GK80','2','Λόγος της υπόσχεσής Σου<br/>Η αλήθεια μέσα μου—<br/>Απ’ το νόμο του θανάτου<br/>Μ’ ελευθέρωσε η ζωή<br/>',NULL,188109,3);
INSERT INTO stanza VALUES('GK80','3','Τα ρυάκια των νερών Σου<br/>Σαν ελάφι επιποθώ<br/>Πότισε, ξεδίψασέ με<br/>Γέμισέ μου την ψυχή<br/>',NULL,188110,4);
INSERT INTO stanza VALUES('GK80','4','Να θανατωθεί το εγώ μου<br/>Να υποταχθώ σ’ Εσέ<br/>Μεταμόρφωσέ με τώρα<br/>Ν’ αναβλύζω δια παντός<br/>',NULL,188111,5);
INSERT INTO stanza VALUES('GK81','1','Πήγες στον Ιησού για να καθαριστείς;<br/>Πλύθηκες με το αίμα του Αμνού;<br/>Ζεις αυτήν την ώρα μες τη χάρη Του;<br/>Πλύθηκες με το αίμα του Αμνού;<br/>',NULL,188112,1);
INSERT INTO stanza VALUES('GK81','chorus','Έχεις καθαριστεί;<br/>Πλύθηκες με το αίμα του Αμνού;<br/>Τα ιμάτιά σου έχουν λευκανθεί;<br/>Πλύθηκες με το αίμα του Αμνού;<br/>',NULL,188113,2);
INSERT INTO stanza VALUES('GK81','2','Είναι ο Σωτήρας που σε οδηγεί;<br/>Πλύθηκες με το αίμα του Αμνού;<br/>Στον εσταυρωμένο αναπαύεσαι;<br/>Πλύθηκες με το αίμα του Αμνού;<br/>',NULL,188114,3);
INSERT INTO stanza VALUES('GK81','3','Ο Νυμφίος θα σε βρει μ’ ένδυμα λευκό;<br/>Πλύθηκες με το αίμα του Αμνού;<br/>Θα ’ναι η ψυχή σου έτοιμη γι’ Αυτόν;<br/>Πλύθηκε με το αίμα του Αμνού;<br/>',NULL,188115,4);
INSERT INTO stanza VALUES('GK81','4','Βγάλε τα ιμάτια αυτά τα ρυπαρά<br/>Να πλυθείς με το αίμα του Αμνού<br/>Μια πηγή υπάρχει όπου η ψυχή<br/>Πλένεται με το αίμα του Αμνού<br/>',NULL,188116,5);
INSERT INTO stanza VALUES('GK82','1','Απ’ την πηγή το αίμα ρέει<br/>Του Εμμανουήλ αυτό<br/>Που κάνει τον αμαρτωλό<br/>Λευκό και άμωμο<br/>Λευκό και άμωμο<br/>Λευκό και άμωμο<br/>Που κάνει τον αμαρτωλό<br/>Λευκό και άμωμο<br/>',NULL,188117,1);
INSERT INTO stanza VALUES('GK82','2','Και ο ληστής ευφράνθηκε<br/>Σαν είδε την πηγή<br/>Κι εγώ εξίσου ρυπαρός<br/>Λευκάνθηκα σ’ αυτή<br/>Λευκάνθηκα σ’ αυτή<br/>Λευκάνθηκα σ’ αυτή<br/>Κι εγώ εξίσου ρυπαρός<br/>Λευκάνθηκα σ’ αυτή<br/>',NULL,188118,2);
INSERT INTO stanza VALUES('GK82','3','Αμνέ, Συ πέθανες για μας<br/>Το αίμα Σου κυλάει<br/>Όλοι αυτοί που έσωσες<br/>Έγιναν δίκαιοι<br/>Έγιναν δίκαιοι<br/>Έγιναν δίκαιοι<br/>Όλοι αυτοί που έσωσες<br/>Έγιναν δίκαιοι<br/>',NULL,188119,3);
INSERT INTO stanza VALUES('GK82','4','Απ’ τη στιγμή που πίστεψα<br/>Και είδα τη ροή<br/>Η αγάπη η λυτρωτική<br/>Σε μένα κυριαρχεί<br/>Σε μένα κυριαρχεί<br/>Σε μένα κυριαρχεί<br/>Η αγάπη η λυτρωτική<br/>Σε μένα κυριαρχεί<br/>',NULL,188120,4);
INSERT INTO stanza VALUES('GK82','5','Και όταν πια δεν θα μιλώ<br/>Στου τάφου τη σιωπή<br/>Τραγούδι πιο γλυκό θα πω<br/>Πως μ’ έσωσες Εσύ<br/>Πως μ’ έσωσες Εσύ<br/>Πως μ’ έσωσες Εσύ<br/>Τραγούδι πιο γλυκό θα πω<br/>Πως μ’ έσωσες Εσύ<br/>',NULL,188121,5);
INSERT INTO stanza VALUES('GK83','1','Είσαι η ζωή μου<br/>Κύριε, εντός μου ζεις<br/>Την πληρότητά Σου<br/>Εσύ μου χορηγείς<br/>Εσύ με αγιάζεις<br/>Με τη φύση Σου<br/>Στην ανάσταση Σου<br/>Είν’ η νίκη μου<br/>',NULL,188122,1);
INSERT INTO stanza VALUES('GK83','2','Η ζωή που ρέει<br/>Μ’ οδηγεί στο φως<br/>Με το Άγιο Πνεύμα<br/>Είμαι κοινωνός<br/>Κάθε μου ανάγκη<br/>Εκπληρώνεται<br/>Καθώς με αγιάζεις<br/>Ζω μέσα σε Σε<br/>',NULL,188123,2);
INSERT INTO stanza VALUES('GK83','3','Χρίσμα Εσύ μου δίνεις<br/>Που με διαπερνά<br/>Και με διαποτίζει<br/>πνεύμα και καρδιά<br/>Συ με συμμορφώνεις<br/>Στην εικόνα Σου<br/>Η ωρίμανσή μου<br/>Είναι έργο Σου<br/>',NULL,188124,3);
INSERT INTO stanza VALUES('GK83','4','Κύριε, η ζωή Σου<br/>Τόσο άφθονη<br/>Με ενδυναμώνει<br/>Μ’ αναζωογονεί<br/>Νίκησες τον Άδη<br/>Είσ’ ο δυνατός<br/>Τώρα όλη η θλίψη<br/>Έγινε ψαλμός<br/>',NULL,188125,4);
INSERT INTO stanza VALUES('GK83','5','Ναι, σ’ Εσένα, Κύριε<br/>Αφιερώνομαι<br/>Κι ο δικός Σου πόθος<br/>Εκπληρώνεται<br/>Πια δεν δίνω μάχη<br/>Να διορθωθώ<br/>Το δικό Σου έργο<br/>Να καθυστερώ<br/>',NULL,188126,5);
INSERT INTO stanza VALUES('GK83','6','Τώρα έχω παύσει<br/>Πια να προσπαθώ<br/>Απ’ τον εαυτό μου<br/>Να ελευθερωθώ<br/>Οικοδόμησέ με<br/>Μες στον οίκο Σου<br/>Μ’ όλους τους αγίους<br/>Για τη δόξα Σου<br/>',NULL,188127,6);
INSERT INTO stanza VALUES('GK84','1','Πώς αγαπώ τον οίκο Σου<br/>Την εκκλησία Σου<br/>Εκεί η καρδιά Σου χαίρεται<br/>Είναι ο πόθος Σου<br/>',NULL,188128,1);
INSERT INTO stanza VALUES('GK84','2','Γι’ αυτήν, ω Κύριε, έδωσες<br/>Τη δική Σου ψυχή<br/>Γι’ αυτό κι εγώ για να χαρείς<br/>Θα πράξω όπως κι Εσύ<br/>',NULL,188129,2);
INSERT INTO stanza VALUES('GK84','3','Γι’ αυτήν, ζωή μου έγινες<br/>Μέσα σ’ αυτήν να ζω<br/>Με Σένα αυτή να πληρωθεί<br/>Εγώ ν’ αφανιστώ<br/>',NULL,188130,3);
INSERT INTO stanza VALUES('GK84','4','Η εκκλησία, η νύφη Σου<br/>Εσένα αντανακλά<br/>Για μένα είν’ ανάπαυση<br/>Και υποστήριγμα<br/>',NULL,188131,4);
INSERT INTO stanza VALUES('GK84','5','Εκεί την άφθονη ζωή<br/>Εσύ μου χορηγείς<br/>Κι όπως ποθείς, ω Κύριε<br/>Εσύ με κυριαρχείς<br/>',NULL,188132,5);
INSERT INTO stanza VALUES('GK84','6','Πώς αγαπώ τον οίκο Σου<br/>Την κατοικία Σου<br/>Δεν θ’ αποχωριστώ ποτέ<br/>Την εκκλησία Σου<br/>',NULL,188133,6);
INSERT INTO stanza VALUES('GK85','1','Ω, τι γλυκιά γιορτή<br/>Καθώς λαμβάνουμε<br/>Τον άρτο και τον οίνο Σου<br/>Και Σε θυμόμαστε<br/>',NULL,188134,1);
INSERT INTO stanza VALUES('GK85','2','Εδώ κάθε πιστός<br/>Τη χάρη Σου ζητά<br/>Να μάθει του Πατέρα μας<br/>Όλα τα μυστικά<br/>',NULL,188135,2);
INSERT INTO stanza VALUES('GK85','3','Εδώ λαμβάνουμε<br/>Τον άρτο της ζωής<br/>Καθώς και με την πίστη Σου<br/>Προμήθεια θεϊκή<br/>',NULL,188136,3);
INSERT INTO stanza VALUES('GK85','4','Το αίμα βλέπουμε<br/>Συμβολικά εδώ<br/>Το τίμημα το πλήρωσες<br/>Μέσα απ’ τον οίνο αυτό<br/>',NULL,188137,4);
INSERT INTO stanza VALUES('GK85','5','Ω, αν η πρόγευση<br/>Είναι τόσο γλυκιά<br/>Φαντάζομαι, ω Κύριε<br/>Πώς θαν’ από κοντά<br/>',NULL,188138,5);
INSERT INTO stanza VALUES('GK85','6','Όταν πλέον θα Σε δω<br/>Μ’ Εσένα σύμμορφος<br/>Τη χάρη Σου την άφθονη<br/>Αιωνίως θα μαρτυρώ<br/>',NULL,188139,6);
INSERT INTO stanza VALUES('GK86','1','Τα δεσμά μου ο Σωτήρας<br/>Ο Χριστός τα έλυσε<br/>Αμαρτία δεν μ’ εξουσιάζει<br/>Ο θάνατος νικήθηκε<br/>',NULL,188140,1);
INSERT INTO stanza VALUES('GK86','chorus','Με το θρίαμβο το δικό Του<br/>Είμαι υπερνικητής<br/>Μες στο πνεύμα τώρα έχω<br/>Δύναμη ανάστασης<br/>',NULL,188141,2);
INSERT INTO stanza VALUES('GK86','2','Μ’ ελευθέρωσε απ’ το νόμο<br/>Εξουσία δεν έχει πια<br/>Τώρα πια δεν με δεσμεύει<br/>Ζω με χάρη, ελεύθερα<br/>',NULL,188142,3);
INSERT INTO stanza VALUES('GK86','3','Κρίθηκε η αμαρτία<br/>Στο σταυρό στο Γολγοθά<br/>Τώρα δεν μ’ εξουσιάζει<br/>Είμαι δίκαιος τώρα πια<br/>',NULL,188143,4);
INSERT INTO stanza VALUES('GK86','4','Αυτός νίκησε τον Άδη<br/>Έδωσε άφθονη ζωή<br/>Και ο θάνατος ηττήθη<br/>Μέσ’ απ’ την ανάσταση<br/>',NULL,188144,5);
INSERT INTO stanza VALUES('GK86','5','Και τις σκοτεινές δυνάμεις<br/>Τις κατάργησε ο Χριστός<br/>Μες το φως απ’ το σκοτάδι<br/>Με μετέφερε Αυτός<br/>',NULL,188145,6);
INSERT INTO stanza VALUES('GK86','6','Η ισχύς Του με καλύπτει<br/>Άφθονη η χάρη Του<br/>Στις δικές μου αδυναμίες<br/>Φαίνεται η δόξα Του<br/>',NULL,188146,7);
INSERT INTO stanza VALUES('GK87','1','Κάποτε όλοι ήμασταν νεκροί<br/>Σ’ έναν κόσμο αμαρτωλό<br/>Μα ο Θεός μάς ζωοποίησε<br/>Και μας κάθισε μαζί με τον Χριστό<br/>',NULL,188147,1);
INSERT INTO stanza VALUES('GK87','chorus','Τώρα ο Κύριος μάς ενώνει<br/>Όλοι λειτουργούμε μ’ έναν νου<br/>Και η αγάπη Του μας δένει<br/>Για να φτάσουμε στο ύψος του Χριστού<br/>',NULL,188148,2);
INSERT INTO stanza VALUES('GK87','2','Τώρα όλοι μας γνωρίζουμε<br/>Όλες τις πτυχές του Χριστού<br/>Ο Χριστός ο Ίδιος μάς πληροί<br/>Κι η αγάπη υπερέχει κάθε νου<br/>',NULL,188149,3);
INSERT INTO stanza VALUES('GK87','3','Το μυστήριο το θαυμάσιο<br/>Τώρα έχει γίνει γνωστό<br/>Ο Χριστός κι η εκκλησία Του<br/>Καταντρόπιασαν για πάντα τον εχθρό<br/>',NULL,188150,4);
INSERT INTO stanza VALUES('GK87','4','Και γι’ αυτό δεόμαστε διαρκώς<br/>Να μας κραταιώνεις, Θεέ<br/>Στην καρδιά Εσύ να κατοικείς<br/>Ριζωμένοι στην αγάπη να ’μαστε<br/>',NULL,188151,5);
INSERT INTO stanza VALUES('GK87','5','Μες στο Σώμα συνδεόμαστε<br/>Όλοι οι πιστοί συνεργοί<br/>Στην αγάπη αυξανόμαστε<br/>Κι όλα γίνονται για την οικοδομή<br/>',NULL,188152,6);
INSERT INTO stanza VALUES('GK87','6','Είμαστε ο Νέος Άνθρωπος<br/>Του σχεδίου Του, όλοι μαζί<br/>Σ’ Αυτόν η δόξα μες στην εκκλησία<br/>Μέσω του Χριστού αιώνια, Αμήν<br/>',NULL,188153,7);
INSERT INTO stanza VALUES('GK88','1','Η ελευθερία της ψυχής<br/>Είν’ απερίγραπτη<br/>Υποταγμένη στον Θεό<br/>Κι αδέσμευτη στη γη<br/>Σ’ αυτήν ανήκει κάθε τι<br/>Στο μέλλον, στο παρόν<br/>Ειρήνη έχει εν Χριστώ<br/>Και κατοικία σ’ Αυτόν<br/>',NULL,188154,1);
INSERT INTO stanza VALUES('GK88','2','Πώς θέλουμε το θρόνο Του<br/>Να μοιραζόμαστε<br/>Μα την υποταγή σ’ Αυτόν<br/>Να την αρνιόμαστε<br/>Ω, μη μιλάτε για θυσία!<br/>Προνόμιο έχουμε<br/>Στο ουράνιο το στράτευμα<br/>Να συμμετέχουμε<br/>',NULL,188155,2);
INSERT INTO stanza VALUES('GK88','3','Ω! Τι θαυμάσια ανταλλαγή<br/>Το λίγο για πολύ<br/>Του λυτρωμένου την ψυχή<br/>Η κτίση υπηρετεί<br/>Όλα ανήκουν εις αυτόν<br/>Που ανήκει στον Χριστό<br/>Η μέλλουσα η βασιλεία<br/>Και η ζωή εδώ<br/>',NULL,188156,3);
INSERT INTO stanza VALUES('GK89','1','Δόξα στον Θεό Πατέρα<br/>Δόξα στον Υιό<br/>Δόξα και στο Άγιο Πνεύμα<br/>Ένας ο Θεός<br/>',NULL,188157,1);
INSERT INTO stanza VALUES('GK89','2','Όταν βλέπουμε τα έργα<br/>Που εποίησες Εσύ<br/>Αγαλλιάζει και σιωπαίνει<br/>Η ψυχή<br/>',NULL,188158,2);
INSERT INTO stanza VALUES('GK89','3','Ήθελες πολλούς γιούς Σου<br/>Να Σε αγαπούν<br/>Ενωμένοι με τον Υιό Σου<br/>Να Σε υμνούν<br/>',NULL,188159,3);
INSERT INTO stanza VALUES('GK89','4','Την αγάπη Σου ο Λόγος<br/>Αποκάλυψε<br/>Τις καρδιές κοντά σε Εσένα<br/>Έφερε<br/>',NULL,188160,4);
INSERT INTO stanza VALUES('GK89','5','Τώρα που είναι ηττημένοι<br/>Όλοι οι εχθροί<br/>Λυτρωμένοι Σε λατρεύουν<br/>Οι πιστοί<br/>',NULL,188161,5);
INSERT INTO stanza VALUES('GK89','6','Δόξα στον Θεό Πατέρα<br/>Δόξα στον Υιό<br/>Δόξα και στο Άγιο Πνεύμα<br/>Ένας ο Θεός<br/>',NULL,188162,6);
INSERT INTO stanza VALUES('GK90','1','Λάδι απ’ την ελιά δεν βγαίνει<br/>Δίχως πίεση<br/>Και χωρίς το πατητήρι<br/>Δεν θα έχουμε κρασί<br/>Με τη συντριβή ο νάρδος<br/>Δίνει ευωδία<br/>Θ’ αρνηθώ εγώ, ω Κύριε<br/>Τη δική Σου την παιδεία;<br/>',NULL,188163,1);
INSERT INTO stanza VALUES('GK90','chorus','Με κάθε πλήγμα<br/>Κέρδος έχω εγώ<br/>Ό,τι κι αν μου αφαιρέσεις<br/>Συ γεμίζεις το κενό<br/>',NULL,188164,2);
INSERT INTO stanza VALUES('GK90','2','Θέλεις, Κύριε, να τεντώσεις<br/>Τις χορδές μου Εσύ<br/>Ν’ ακουστεί μέσ’ απ’ τον πόνο<br/>Μελωδία θεϊκή<br/>Οι στερήσεις αν με φέρνουν<br/>Πιο κοντά σ’ Εσέ<br/>Την αγάπη Σου να βλέπω<br/>Η καρδιά μου λέει «ναι»<br/>',NULL,188165,3);
INSERT INTO stanza VALUES('GK90','3','Ντρέπομαι που τον εαυτό μου<br/>Πάντα τον φρουρώ<br/>Μ’ εκπαιδεύεις με αγάπη<br/>Όμως, δεν το εννοώ<br/>Κύριε, όμως να ευδοκήσεις<br/>Συ εργάσου με<br/>Ν’ αψηφάς αυτό που νιώθω<br/>Να δεσπόζεις πάντοτε<br/>',NULL,188166,4);
INSERT INTO stanza VALUES('GK90','4','Αν η γνώμη μου διαφέρει<br/>Πράξε όπως θες<br/>Ναι, μπορεί να με λυπήσει<br/>Μα θα κάνω αυτό που λες<br/>Θέλω να Σ’ ευαρεστήσω<br/>Κι ας ζημιωθώ<br/>Έστω κι αν αυτό σημαίνει<br/>Να υποφέρω το σταυρό<br/>',NULL,188167,5);
INSERT INTO stanza VALUES('GK90','5','Μέσ’ από τα δάκρυά μου<br/>Θα δοξολογώ<br/>Η γλυκύτης Σου με κάνει<br/>Πάντοτε να Σε υμνώ<br/>Πιο πολύτιμος μου είσαι<br/>Απ’ το κάθε τι<br/>Ν’ αυξηθείς κι εγώ να φθίνω<br/>Είν’ η μόνη μου ευχή<br/>',NULL,188168,6);
INSERT INTO stanza VALUES('GK91','1','Να ’μαι σαν Εσέ, άγιε Σωτήρα<br/>Η προσευχή μου είναι αυτή<br/>Και με χαρά τα πάντα αφήνω<br/>Για να ’χω τη δική Σου μορφή<br/>Να ’μαι σαν Εσέ, να ’μαι σαν Εσέ<br/>Άγιε Σωτήρα, τόσο αγνός<br/>Έλα και σφράγισε την καρδιά μου<br/>Με τη μορφή Σου βαθιά εντός<br/>',NULL,188169,1);
INSERT INTO stanza VALUES('GK91','2','Να ’μαι σαν Εσέ, να ’μαι οικτίρμων<br/>Να συγχωρώ μ’ ευσπλαχνία εγώ<br/>Και να βοηθώ αυτούς που κοπιάζουν<br/>Αμαρτωλούς να ψάχνω να βρω<br/>',NULL,188170,2);
INSERT INTO stanza VALUES('GK91','3','Να ’μαι σαν Εσέ, πράος στο πνεύμα<br/>Τόλμη να έχω και ακακία<br/>Να υπομένω κάθε αισχύνη<br/>Και ν’ αναγγέλλω τη σωτηρία<br/>',NULL,188171,3);
INSERT INTO stanza VALUES('GK91','4','Να ’μαι σαν Εσέ, έρχομαι Κύριε<br/>Τώρα να λάβω το χρίσμα Σου<br/>Ό,τι κι αν έχω, ό,τι κι αν είμαι<br/>Όλα τ’ αφήνω στα χέρια Σου<br/>',NULL,188172,4);
INSERT INTO stanza VALUES('GK91','5','Να ’μαι σαν Εσέ, ω! Πλήρωσέ με<br/>Με την αγάπη, το Πνεύμα Σου<br/>Να ’μαι ναός Σου και κατοικία<br/>Που να τιμά Εσένα, Ιησού<br/>',NULL,188173,5);
INSERT INTO stanza VALUES('GK92','1','Τι θαύμα αυτό, ω Κύριε!<br/>Σ’ ενότητα να είμαστε<br/>Σ’ ενότητα Εσύ κι εγώ<br/>Ω! Τι μυστήριο θαυμαστό!<br/>',NULL,188174,1);
INSERT INTO stanza VALUES('GK92','2','Το σώμα Σου μου έδωσες<br/>Αιώνια να μοιράζομαι<br/>Να αφαιρεί το αίμα Σου<br/>Όλες τις αμαρτίες μου<br/>',NULL,188175,2);
INSERT INTO stanza VALUES('GK92','3','Μετά από την ανάσταση<br/>Πήρες πνευματική μορφή<br/>Εντός μας για να κατοικείς<br/>Τα πλούτη Σου να μοιραστείς<br/>',NULL,188176,3);
INSERT INTO stanza VALUES('GK92','4','Μέσα στη θεία κοινωνία<br/>Διακρίνουμε τη γλύκα Σου<br/>Ευγνωμοσύνη νιώθουμε<br/>Τα πάθη Σου θυμόμαστε<br/>',NULL,188177,4);
INSERT INTO stanza VALUES('GK92','5','Με άρτο και με οίνο εμείς<br/>Λαμβάνουμε τη χάρη Σου<br/>Εν πνεύματι γευόμαστε<br/>Το πλούσιο συμπόσιο Σου<br/>',NULL,188178,5);
INSERT INTO stanza VALUES('GK92','6','Επιθυμία μας είν’ αυτή<br/>Εσύ να είσαι η τροφή<br/>Που τρώμε καθημερινά<br/>Να Σε τιμούμε αληθινά<br/>',NULL,188179,6);
INSERT INTO stanza VALUES('GK93','1','Όλοι θέλουν τον Σωτήρα<br/>Λίγοι το σταυρό<br/>Λίγοι θέλουν να πληρώσουν<br/>Το αντίτιμο<br/>Για το έξοχο της γνώσης<br/>Που είναι στον Χριστό<br/>Για το έξοχο της γνώσης<br/>Που είναι στον Χριστό<br/>',NULL,188180,1);
INSERT INTO stanza VALUES('GK93','2','Ναι, με τον Ιησού παρέα<br/>Θέλουν να δειπνούν<br/>Λίγοι το πικρό ποτήρι<br/>Θέλουν να το πιουν<br/>Στη Γεσθημανή σαν πάει<br/>Λίγοι ακολουθούν<br/>Στη Γεσθημανή σαν πάει<br/>Λίγοι ακολουθούν<br/>',NULL,188181,2);
INSERT INTO stanza VALUES('GK93','3','Όλοι θέλουν τη σοφία Του<br/>Λίγοι την ντροπή<br/>Για τις ευλογίες Του δίνουν<br/>Όλη την τιμή<br/>Εάν για λίγο τους αφήσει<br/>Τον ξεχνούν αυτοί<br/>Εάν για λίγο τους αφήσει<br/>Τον ξεχνούν αυτοί<br/>',NULL,188182,3);
INSERT INTO stanza VALUES('GK93','4','Μα η ψυχή που Σ’ αγαπάει<br/>Δεν κλονίζεται<br/>Και σ’ Εσέ προσκολλημένη<br/>Μένει πάντοτε<br/>Τη δική Σου θεία αγάπη<br/>Δώσ’ μου, Κύριε<br/>Τη δική Σου θεία αγάπη<br/>Δώσ’ μου, Κύριε<br/>',NULL,188183,4);
INSERT INTO stanza VALUES('GK94','1','Τι πλούσια, ω Κύριε<br/>Η σωτηρία Σου<br/>Τέτοιο θαυμάσιο γεγονός<br/>Πώς να συλλάβει ο νους;<br/>Μυστήριος και θεϊκός<br/>Τα λόγια δεν μπορούν<br/>Να Σε τιμήσουν αρκετά<br/>Ποτέ δεν θα αρκούν<br/>',NULL,188184,1);
INSERT INTO stanza VALUES('GK94','chorus','Ω! Τι πλούσια σωτηρία<br/>Μια νέα δημιουργία<br/>Κύριε, για το έργο Σου<br/>Σου δίνουμε λατρεία<br/>',NULL,188185,2);
INSERT INTO stanza VALUES('GK94','2','Το σώμα Σου συντρίφτηκε<br/>Επάνω στο σταυρό<br/>Απ’ το πλευρό Σου έτρεξε<br/>Και αίμα και νερό<br/>Τις αμαρτίες καθάρισες<br/>Μου έδωσες ζωή<br/>Για νά ’μαστε, ω Κύριε<br/>Σε πλήρη ένωση<br/>',NULL,188186,3);
INSERT INTO stanza VALUES('GK94','3','Απ’ ένα κόκκο σιταριού<br/>Συ έφερες καρπό<br/>Τη φύση Σου μας χάρισες<br/>Γίναμε Σώμα Σου<br/>Εσύ ’σαι η πληρότητα<br/>Που βιώνουμε εμείς<br/>Κινείσαι και εκφράζεσαι<br/>Μέσ’ από εμάς στη γη<br/>',NULL,188187,4);
INSERT INTO stanza VALUES('GK94','4','Ναι, είμαστε το Σώμα Σου<br/>Εκεί που κατοικείς<br/>Σε μας βρίσκεις ανάπαυση<br/>Στον οίκο Σου στη γη<br/>Χαρά Σου είμαστε εμείς<br/>Μας έχεις νυμφευθεί<br/>Κι εμείς Σ’ απολαμβάνουμε<br/>Εντός μας κατοικείς<br/>',NULL,188188,5);
INSERT INTO stanza VALUES('GK94','5','Με τα στοιχεία της κοινωνιάς<br/>Σε μνημονεύουμε<br/>Θυμόμαστε τη λύτρωση<br/>Που Εσύ μας έδωσες<br/>Το Σώμα Σου, η νύφη Σου<br/>Ναι, τώρα είμαστε<br/>Μ’ ευγνωμοσύνη στην καρδιά<br/>Λατρεία Σου δίνουμε<br/>',NULL,188189,6);
INSERT INTO stanza VALUES('GK95','1','Κύριε οι λυτρωμένοι είναι<br/>Σώμα Σου και Νύφη Σου<br/>Είναι η πληρότητά Σου<br/>Είναι και η εικόνα Σου<br/>Εις σ’ αυτήν τα πάντα εν πάσι<br/>Να φανεί ο πλούτος Σου<br/>Και Εσύ τη διαποτίζεις<br/>Πλήρως με τη δόξα Σου<br/>',NULL,188190,1);
INSERT INTO stanza VALUES('GK95','chorus','Ω, στην Άγια Πόλη<br/>Του Θεού η δόξα<br/>Βρίσκει τέλεια έκφραση<br/>Στο Νέο Άνθρωπο<br/>',NULL,188191,2);
INSERT INTO stanza VALUES('GK95','2','Άνθρωπος αναμιγμένος<br/>Με Θεό! Μυστήριο!<br/>Φανερώνεται όλη η δόξα<br/>Του Θεού στον άνθρωπο<br/>Οικουμενικό αγγείο<br/>Που εκφράζει τον Θεό<br/>Φαίνεται η αγιοσύνη<br/>Και η ομορφιά σ’ αυτό<br/>',NULL,188192,3);
INSERT INTO stanza VALUES('GK95','3','Είναι σύνολο αγίων<br/>Που μεταμορφώθηκαν<br/>Σαν πολύτιμα πετράδια<br/>Όλοι συμμορφώθηκαν<br/>Κι απ’ το θρόνο ύδωρ βγαίνει<br/>Ζωντανό και άφθονο<br/>Κι ο Χριστός, το αιώνιο δέντρο<br/>Δίνει πλούσιο καρπό<br/>',NULL,188193,4);
INSERT INTO stanza VALUES('GK95','4','Είναι η χρυσή λυχνία<br/>Με το λύχνο, τον Χριστό<br/>Φως της δόξας, ο Πατέρας<br/>Που φεγγοβολεί διαρκώς<br/>Είν’ η έκφραση η τέλεια<br/>Άνθρωπος με τον Θεό<br/>Η συνύπαρξή τους είναι<br/>Το αιώνιο σχέδιο<br/>',NULL,188194,5);
INSERT INTO stanza VALUES('GK96','1','Πρώτα το αίμα καθαρίζει<br/>Και το χρίσμα ακολουθεί<br/>Απ’ το Γολγοθά περνάμε<br/>Να ’ρθει η Πεντηκοστή<br/>Αν το αίμα δεν μας πλύνει<br/>Πώς το Πνεύμα να ’χει ισχύ;<br/>Θάνατος του εαυτού μας<br/>Πρέπει να προηγηθεί<br/>Στο σταυρό Σου, Κύριε<br/>Κράτα την ψυχή μου εκεί<br/>Μ’ όποιο κόστος για να λάβω<br/>Πλήρες χρίσμα και ζωή<br/>',NULL,188195,1);
INSERT INTO stanza VALUES('GK96','2','Πρώτα η Πέτρα θα ραγίσει<br/>Για να βγάλει το νερό<br/>Δίχως θάνατο το Πνεύμα<br/>Δεν ζει μες τον άνθρωπο<br/>Όταν στον Χριστό ποθούμε<br/>Όλα να τα δώσουμε<br/>Δύναμη θα μας ενδύσει<br/>Άλλους για να σώσουμε<br/>',NULL,188196,2);
INSERT INTO stanza VALUES('GK96','3','Πρώτα το θυσιαστήριο<br/>Κι η φωτιά ακολουθεί<br/>Προσφορά του εαυτού μας<br/>Εις το θρόνο οδηγεί<br/>Αν για τον Θεό τα πάντα<br/>Θυσιάσουμε εμείς<br/>Μόνο τότε η ισχύς Του<br/>Σε ’μας θα ’ναι εμφανής<br/>',NULL,188197,3);
INSERT INTO stanza VALUES('GK96','4','Καθαρίζουμε τα σκεύη<br/>Και το λάδι έπεται<br/>Σκάβουμε όλα τα αυλάκια<br/>Τη Βροχή για να χωρούν<br/>Πρέπει μες απ’ τον Ιορδάνη<br/>Ο καθένας να περνά<br/>Για να ’ρθει το Περιστέρι<br/>Προηγείται βάπτισμα<br/>',NULL,188198,4);
INSERT INTO stanza VALUES('GK96','5','Όταν δούμε το σιτάρι<br/>Έτοιμο να θεριστεί<br/>Μαρτυρούμε πως οι κόκκοι<br/>Πέθαναν μέσα στη γη<br/>Ο καρπός για να βλαστήσει<br/>Πρέπει να πεθάνουμε<br/>Μέσ’ από το θάνατό Του<br/>Το Πνεύμα να λάβουμε<br/>',NULL,188199,5);
INSERT INTO stanza VALUES('GK96','6','Αφού πρέπει να περάσω<br/>Απ’ την πύλη τη στενή<br/>Πάρε, Κύριε, το εγώ μου<br/>Μάθε μου υπακοή<br/>Δύναμη πια δεν ζητάω<br/>Τώρα μόνο θάνατο<br/>Και το νόημα του σταυρού Σου<br/>Να γνωρίσω Σου ζητώ<br/>',NULL,188200,6);
INSERT INTO stanza VALUES('GK97','1','Είσ’ αγάπη, είσαι φως Θεέ<br/>Η ζωή μας εν Χριστώ<br/>Φανερώθηκε η αγάπη<br/>Έλαμψε σε μας το φως<br/>',NULL,188201,1);
INSERT INTO stanza VALUES('GK97','chorus','Είσ’ αγάπη, είσαι φως<br/>Η ζωή μας εν Χριστώ<br/>Φανερώθηκε η αγάπη<br/>Έλαμψε σε μας το φως<br/>',NULL,188202,2);
INSERT INTO stanza VALUES('GK97','2','Η ουσία Σου είν’ αγάπη<br/>Φωτεινά τα έργα Σου<br/>Φως κι αγάπη φανερώνουν<br/>Το δικό Σου πρόσωπο<br/>',NULL,188203,3);
INSERT INTO stanza VALUES('GK97','3','Με τη χάρη η αγάπη<br/>Μάς αποκαλύπτεται<br/>Με την αλήθεια και το φως Σου<br/>Έτσι Σε γνωρίζουμε<br/>',NULL,188204,4);
INSERT INTO stanza VALUES('GK97','4','Με αγάπη στο σταυρό Σου<br/>Συ μας έδωσες ζωή<br/>Και το φως μάς φανερώνει<br/>Του αίματος τη δύναμη<br/>',NULL,188205,5);
INSERT INTO stanza VALUES('GK97','5','Ζωή μας δίνει η αγάπη<br/>Και Σε απολαμβάνουμε<br/>Με το φως μάς καθαρίζεις<br/>Κοινωνοί γινόμαστε<br/>',NULL,188206,6);
INSERT INTO stanza VALUES('GK97','6','Με το φως και με το αίμα<br/>Το χρίσμα γνωρίζουμε<br/>Κι η ουσία Σου – η αγάπη<br/>Μέσα μας αυξάνεται<br/>',NULL,188207,7);
INSERT INTO stanza VALUES('GK97','7','Της αγάπης Σου παιδιά, Θεέ<br/>«Αββά» Σε φωνάζουμε<br/>Είν’ το φως Σου που μας κάνει<br/>Με τον Υιό να μοιάζουμε<br/>',NULL,188208,8);
INSERT INTO stanza VALUES('GK97','chorus','Ω, τι δόξα, τι ευλογία!<br/>Φως κι αγάπη βλέπουμε<br/>Και γι’ αυτό, Θεέ Πατέρα<br/>Αιώνια Σε δοξάζουμε<br/>',NULL,188209,9);
INSERT INTO stanza VALUES('GK98','1','Σε δοξάζω, Θεέ<br/>Που εσταυρώθη για μας<br/>Ο μονάκριβος Υιός Σου<br/>Κι ανελήφθη ψηλά<br/>',NULL,188210,1);
INSERT INTO stanza VALUES('GK98','chorus','Αλληλούια! Σε υμνούμε<br/>Αλληλούια! Αμήν<br/>Αλληλούια! Σε υμνούμε<br/>Όλη η δόξα σε Σε<br/>',NULL,188211,2);
INSERT INTO stanza VALUES('GK98','2','Σε δοξάζω, Θεέ<br/>Για το Πνεύμα φωτός<br/>Που σκορπίζει το σκότος<br/>Για να λάμψει ο Χριστός<br/>',NULL,188212,3);
INSERT INTO stanza VALUES('GK98','3','Σε δοξάζω, Θεέ<br/>Που Σε γνωρίζουμε<br/>Ως Πατέρα αγάπης<br/>Διαμέσου του Υιού<br/>',NULL,188213,4);
INSERT INTO stanza VALUES('GK98','4','Σε δοξάζω, Θεέ<br/>Που από κει ψηλά<br/>Τις καρδιές μας ανάβεις<br/>Με ουράνια φωτιά<br/>',NULL,188214,5);
INSERT INTO stanza VALUES('GK99','1','Ετοιμάσου<br/>Δεν γνωρίζεις τη στιγμή<br/>Που η σάλπιγγα θα ηχήσει<br/>Και θα γίνει η αρπαγή<br/>Έχεις λάδι στη λαμπάδα;<br/>Θα δεις τον Μοναδικό<br/>Στρέψε τώρα την καρδιά σου<br/>στον Χριστό<br/>',NULL,188215,1);
INSERT INTO stanza VALUES('GK99','1','Ω! Ανοίγω την καρδιά<br/>Γέμισέ την Βασιλιά<br/>Θέλω να ’μαι και παρθένος και σοφός<br/>Γι’ αυτό πληρώνω κάθε τίμημα<br/>',NULL,188216,2);
INSERT INTO stanza VALUES('GK99','2','Ω! Δικός Σου ο χρόνος μου<br/>Στην αγάπη Σου θα ζω<br/>μες το Λόγο σου θέλω να εντρυφώ<br/>για να μ’ εύρεις άγιο και καθαρό<br/>',NULL,188217,3);
INSERT INTO stanza VALUES('GK99','3','Ω! Μας έδωσες πολλά<br/>Τάλαντα κι άλλα καλά<br/>Γι’ αυτό αμέσως θέλω εγώ να εργαστώ<br/>Για να μ’ εύρεις δούλο άξιο και πιστό<br/>',NULL,188218,4);
INSERT INTO stanza VALUES('GK99','4','Κύριε, όλα τα εκπληροίς<br/>Δικοί Σου είμαστε ιερείς<br/>Πάντα τη ζωή Σου σ’ άλλους διακονώ<br/>Την τροφή Σου δίνω στον σωστό καιρό<br/>',NULL,188219,5);
INSERT INTO stanza VALUES('GK100','1','Στης αγάπης τη γιορτή<br/>Το ποτήρι, το ψωμί<br/>Τα λαμβάνουμε μαζί<br/>Κι η ζωή Σου μας πληροί<br/>Κύριε, Σ’ ευχαριστώ<br/>Για την ευλογία αυτή<br/>Πλήρωσες εγώ να ζω<br/>Με την ίδια τη ζωή<br/>',NULL,188220,1);
INSERT INTO stanza VALUES('GK100','2','Το αίμα Σου το έχυσες<br/>Και συγχώρεση έδωσες<br/>Νέα Διαθήκη έκανες<br/>Ευλογίες μοίρασες<br/>Στο πικρό ποτήρι Εσύ<br/>Γεύτηκες το θάνατο<br/>Η οργή ξεχείλησε<br/>Κι έτσι μας ευλόγησες<br/>',NULL,188221,2);
INSERT INTO stanza VALUES('GK100','3','Λόγω πτώσης του Αδάμ<br/>Έχυσες το αίμα Σου<br/>Τώρα είσαι το παν για με<br/>Και η μερίδα μου Χριστέ<br/>Στη μερίδα μας αυτή<br/>Έχουμε τη λύτρωση<br/>Τέλεια ειρήνη και ζωή<br/>Όλα του Θεού βουλή<br/>',NULL,188222,3);
INSERT INTO stanza VALUES('GK100','4','Θείο το ποτήρι μας<br/>Αιώνια η μερίδα μας<br/>Κάθε ουράνια απόλαυση<br/>Ο Θεός σχεδίασε<br/>Εις ανάμνησή Σου Θεέ<br/>Το ποτήρι πίνουμε<br/>Έτσι εμείς μετέχουμε<br/>Εν πνεύματι στο Γολγοθά<br/>',NULL,188223,4);
INSERT INTO stanza VALUES('GK101','1','Είμαι άρτος ζωντανός<br/>Κατέβηκα απ’ τον ουρανό<br/>Όποιος με γευτεί<br/>Όποιος με γευτεί<br/>Αιώνια θα ζει<br/>Αιώνια μαζί Μου<br/>Το ψωμί (το ψωμί)<br/>Που δίνω (δίνω)<br/>Είν’ η σάρκα Μου<br/>Για ζωή (για ζωή)<br/>Για να ζει (να ζει)<br/>Κάθε άνθρωπος<br/>Είμαι άρτος ζωντανός<br/>Κατέβηκα απ’ τον ουρανό<br/>Όποιος με γευτεί<br/>Όποιος με γευτεί<br/>Αιώνια θα ζει<br/>Αιώνια μαζί Μου<br/>',NULL,188224,1);
INSERT INTO stanza VALUES('GK102','1','Περπατούσαν στην οδό<br/>Μόνοι οι δύο μαθητές<br/>Ο Κύριος πέθανε<br/>Κάποιος τους πλησίασε<br/>Και τους μίλησε γλυκά<br/>Του ανοίξαν την καρδιά<br/>Είπε:<br/>Απιστία γιατί;<br/>Έτσι ήταν γραφτό<br/>Ο Ιησούς Χριστός να σταυρωθεί<br/>Μετά να δοξαστεί<br/>Απιστία γιατί;<br/>Απιστία γιατί;<br/>',NULL,188225,1);
INSERT INTO stanza VALUES('GK102','2','Φτάσαν στον προορισμό<br/>Κάθισαν για φαγητό<br/>Τον άρτο ευλόγησε<br/>Τότε ανοίξαν οι οφθαλμοί<br/>Τον Χριστό αναγνώρισαν<br/>Έγινε άφαντος<br/>Είπαν:<br/>Δεν καιγότανε<br/>Μέσα μας η καρδιά;<br/>Μαζί βαδίζαμε<br/>Ανοίξαν οι γραφές<br/>Δεν καιγότανε<br/>Μέσα μας η καρδιά;<br/>',NULL,188226,2);
INSERT INTO stanza VALUES('GK102','3','Περπατάμε στην οδό<br/>Μας υπενθυμίζει Αυτός<br/>«Μαζί σας είμαι Εγώ»<br/>Το Πνεύμα μέσα μας<br/>Κι η αλήθεια είναι Αυτός<br/>Μέσα μας κατοικεί<br/>Λέμε:<br/>Πώς δεν καίγεται<br/>Μέσα μας η καρδιά;<br/>Στην ανάσταση<br/>Μέσα μας Αυτός ζει<br/>Πώς δεν καίγεται<br/>Μέσα μας η καρδιά;<br/>',NULL,188227,3);
INSERT INTO stanza VALUES('GK103','1','Κύριε, Σ’ αγαπώ<br/>Αλήθεια Σ’ αγαπώ<br/>Χωρίς Εσένα όλα κενά<br/>Είσαι ελκυστικός<br/>Τόσο γοητευτικός<br/>Τα πλούτη Σου αμέτρητα<br/>Τ’ Όνομά Σου το γλυκό<br/>Με κάνει χαρούμενο<br/>Μου ανήκεις και Σου ανήκω<br/>Ενωμένοι σφιχτά<br/>Και αδιάρρηκτα<br/>Πρόγευση της Νέας Ιερουσαλήμ<br/>',NULL,188228,1);
INSERT INTO stanza VALUES('GK104','1','Κρυμμένος πίσω απ’ τη σκηνή<br/>Δουλεύει πάντα με αγάπη<br/>Πάνσοφος, κυρίαρχος<br/>Μας οδηγεί μ’ υπομονή<br/>Κοίτα τον Υιό, τον Ακριβό Μου<br/>Κάθεται στα δεξιά Μου<br/>Είν’ Βασιλιάς, Λυτρωτής<br/>Αλλά ζητά την άδειά σου<br/>Να εργαστεί<br/>',NULL,188229,1);
INSERT INTO stanza VALUES('GK104','chorus','Κύριε, πόσο Σ’ αγαπάμε<br/>Παραδινόμαστε σε Σένα<br/>Η Βασιλεία Σου χαρίζει<br/>Μία γλυκιά ζωή<br/>Ω! Ευλογία πλούσια<br/>Αφήνομαι στον Βασιλιά<br/>Ζητώ μόνο το θέλημά Σου<br/>Εδώ στη γη<br/>',NULL,188230,2);
INSERT INTO stanza VALUES('GK104','2','Μέσα μας είναι ο σπόρος<br/>Μας οδηγεί, μας κυβερνάει<br/>Ενθρονισμένος Βασιλιάς<br/>Ο Ιησούς μας αγιάζει<br/>Μήπως δεν ξέρεις ότι είσαι<br/>Του Βασιλέα ο Ναός;<br/>Μέσα από εμάς Αυτός ζει<br/>Για να διοικεί, να βασιλεύει<br/>Εδώ στη γη<br/>',NULL,188231,3);
INSERT INTO stanza VALUES('GK105','1','Αν τον Κύριο εκζητάς<br/>Μες στον κόσμο μην κοιτάς<br/>Γιατί εκεί ο Κύριος δεν κατοικεί<br/>Δεν κατοικεί, δεν κατοικεί<br/>Ο Κύριος δεν κατοικεί<br/>Γιατί εκεί ο Κύριος δεν κατοικεί<br/>',NULL,188232,1);
INSERT INTO stanza VALUES('GK105','2','Αν τον Κύριο εκζητάς<br/>Μες το νου σου μην κοιτάς<br/>Γιατί ο νους γνωρίζει, μα δεν γεύεται<br/>Δεν γεύεται, δεν γεύεται<br/>Δεν γεύεται, δεν γεύεται<br/>Γιατί ο νους γνωρίζει, μα δεν γεύεται<br/>',NULL,188233,2);
INSERT INTO stanza VALUES('GK105','3','Αν τον Κύριο εκζητάς<br/>Άνοιξέ Του την καρδιά<br/>Άνοιξε σ’ Αυτόν την πόρτα της καρδιάς<br/>Και θα εισέλθει ο Βασιλιάς<br/>Και θα εισέλθει ο Βασιλιάς<br/>Άνοιξε σ’ Αυτόν την πόρτα της καρδιάς<br/>',NULL,188234,3);
INSERT INTO stanza VALUES('GK105','4','Αν Του ανοίξεις την καρδιά<br/>Θα εισέλθει ο Βασιλιάς<br/>Τ’ Όνομα Του επικαλέσου κι άνοιξε<br/>Ω Κύριε Ιησού! Ω Κύριε Ιησού!<br/>Ω Κύριε Ιησού! Ω Κύριε Ιησού!<br/>Τ’ Όνομά Του επικαλέσου κι άνοιξε<br/>',NULL,188235,4);
INSERT INTO stanza VALUES('GK106','1','Σ’ αγαπώ, Ιησού μου<br/>Και η αγάπη Σου<br/>Με ωθεί να Σε ψάχνω<br/>Και να Σε εκζητώ<br/>Με ωθεί να Σε ψάχνω<br/>Και να Σε εκζητώ<br/>Ο Αγαπητός μου<br/>Ολόκληρος ωραίος<br/>Αυτός που η ψυχή μου αγαπάει<br/>',NULL,188236,1);
INSERT INTO stanza VALUES('GK106','2','Η αγάπη Σου, Ιησού<br/>Πιο γλυκιά απ’ το κρασί<br/>Κι η οσμή Σου των μύρων<br/>Την καρδιά μου ελκύει<br/>Κι η οσμή Σου των μύρων<br/>Την καρδιά μου ελκύει<br/>Πηγή κήπου<br/>Απ’ τα όρη του Λιβάνου<br/>Νερά που αναβλύζουν και που κυλούν<br/>',NULL,188237,2);
INSERT INTO stanza VALUES('GK106','3','Έλα, Αγαπητέ μου<br/>Πνεύσε στον κήπο μου<br/>Οι γλυκές ευωδίες του<br/>Παντού να σκορπούν<br/>Οι γλυκές ευωδίες του<br/>Παντού να σκορπούν<br/>Αδελφή Μου, νύφη<br/>Στον κήπο Μου εισήλθα<br/>Να βρω κρασί, γάλα και μέλι<br/>',NULL,188238,3);
INSERT INTO stanza VALUES('GK106','4','Βάλε με σαν σφραγίδα<br/>Στην καρδιά Σου, Ιησού<br/>Σαν τον Άδη η ζήλεια<br/>Αγάπη ισχυρή<br/>Σαν τον Άδη η ζήλεια<br/>Αγάπη ισχυρή<br/>Δεν μπορούν ποτάμια<br/>Να πνίξουν την αγάπη<br/>Ούτ’ άνθρωπος να την αγοράσει<br/>',NULL,188239,4);
INSERT INTO stanza VALUES('GK107','1','Την τέλεια ελευθερία<br/>χαρίζει ο Χριστός μας<br/>σπάσε όλα τα δεσμά<br/>έλα και συ μαζί μας<br/>στη νέα αυτή ζωή μας<br/>δέξου Τον στην καρδιά<br/>Είναι το έτος άφεσης<br/>απελευθέρωση εν Χριστώ<br/>σ’ όλη τη γη χαρίζει<br/>οι σκλάβοι επέστρεψαν σ’ Αυτόν<br/>ελεύθεροι απ’ όλα τα δεσμά<br/>είναι το έτος άφεσης<br/>',NULL,188240,1);
INSERT INTO stanza VALUES('GK107','2','Τη γη μας ανακτούμε<br/>είν’ ο Θεός δικός μας<br/>ζούμε μέσα σ’ Αυτόν<br/>απόλαυσε ειρήνη<br/>με όλους τους αγίους<br/>βρες τέλεια ανάπαυση<br/>',NULL,188241,2);
INSERT INTO stanza VALUES('GK108','1','Στον προκείμενο αγώνα<br/>Ο σκοπός η νίκη μου<br/>Μες στη δόξα Του εγώ θα αρπαχτώ<br/>Κάθε τίμημα πληρώνω<br/>Και κρατώ την πίστη μου<br/>Η Άγια πόλη η αμοιβή<br/>',NULL,188242,1);
INSERT INTO stanza VALUES('GK108','chorus','Μες τη δόξα όταν αρπαχτώ<br/>Στη Νέα Ιερουσαλήμ<br/>Στ’ Άγια θα ζω, στ’ Άγια θα ζω<br/>Με τους υπερνικητές Του<br/>Μ’ ευφροσύνη θα υμνώ<br/>Εις τη Νέα Ιερουσαλήμ<br/>',NULL,188243,2);
INSERT INTO stanza VALUES('GK108','2','Είμαι τώρα οδοιπόρος<br/>Μες τη θλίψη έχω χαρά<br/>Γιατί ελπίδα μου είναι η νέα γη<br/>Ενώ άλλοι επιζητούν<br/>Τη ζωή την κοσμική<br/>Εγώ την Ιερουσαλήμ<br/>',NULL,188244,3);
INSERT INTO stanza VALUES('GK108','3','Κι αν τα πόδια μου πληγώνονται<br/>Μες τη στενή οδό<br/>Όταν σκέφτομαι την πόλη αναθαρρώ<br/>Κι αν τα δάκρυά μου κυλάνε<br/>Η καρδιά ειν’ σταθερή<br/>Η Άγια πόλη η αμοιβή<br/>',NULL,188245,4);
INSERT INTO stanza VALUES('GK108','4','Ο σκοπός είναι ο στόχος<br/>Τώρα τρέχω προς αυτόν<br/>Το ουράνιο βραβείο επιζητώ<br/>Όλα τα παλιά ξεχνάω<br/>Και το τέρμα επιθυμώ<br/>Η Άγια πόλη η αμοιβή<br/>',NULL,188246,5);
INSERT INTO stanza VALUES('GK108','chorus','Με τη χάρη Του κι αγάπη<br/>Μέσα στ’ Άγια θα ζω<br/>Νέα Ιερουσαλήμ, Νέα Ιερουσαλήμ<br/>Όλοι οι άγιοι θα δοξάζουν<br/>Και τον Κύριο θα υμνούν<br/>Εις τη Νέα Ιερουσαλήμ<br/>',NULL,188247,6);
INSERT INTO stanza VALUES('GK109','1','Το Πνεύμα είσαι, Κύριε<br/>Ζεις μες το πνεύμα μας<br/>Δια της ανάμειξης μ’ Εσέ<br/>Ένα γινόμαστε<br/>',NULL,188248,1);
INSERT INTO stanza VALUES('GK109','2','Το Πνεύμα μες το πνεύμα μας<br/>Συμμαρτυρεί για μας<br/>Ότι είμαστε παιδιά Θεού<br/>Και κληρονόμοι Του<br/>',NULL,188249,2);
INSERT INTO stanza VALUES('GK109','3','Τα πλούτη Σου γευόμαστε<br/>Μέσα στο πνεύμα μας<br/>Μας δίνεις τον Παράκλητο<br/>Το Πνεύμα τ’ Άγιο<br/>',NULL,188250,3);
INSERT INTO stanza VALUES('GK109','4','Βαδίζοντας εν πνεύματι<br/>Σ’ ακολουθούμε όλοι<br/>Μας διαφωτίζεις πάντα Εσύ<br/>Και μας καθοδηγείς<br/>',NULL,188251,4);
INSERT INTO stanza VALUES('GK109','5','Εκφράζουμε, λατρεύουμε<br/>Εσένα πάντοτε<br/>Η δύναμή μας είσαι Εσύ<br/>Η εν πνεύματι ζωή<br/>',NULL,188252,5);
INSERT INTO stanza VALUES('GK109','6','Προσεύχεται στο πνεύμα μας<br/>Το Πνεύμα του Ιησού<br/>Με στεναγμούς αλάλητους<br/>Στη μεσιτεία Του<br/>',NULL,188253,6);
INSERT INTO stanza VALUES('GK109','7','Στρεφόμαστε στο πνεύμα μας<br/>Για κοινωνία γλυκιά<br/>Με τον Θεό να έχουμε<br/>Θεία κληρονομιά<br/>',NULL,188254,7);
INSERT INTO stanza VALUES('GK109','8','Το Πνεύμα με το πνεύμα μας<br/>Θα συνυφαίνονται<br/>Σε μια γλυκιά ανάμειξη<br/>Ένα να γίνονται<br/>',NULL,188255,8);
INSERT INTO stanza VALUES('GK110','1','Φίλα Αυτόν, τον Υιό<br/>Τον γλυκύτατο Αμνό<br/>Πέθανε στο σταυρό<br/>Και για με για να σωθώ<br/>Μ’ έλκυσε, μ’ αγάπησε<br/>Το Πνεύμα Του στο πνεύμα μου<br/>Και Τον φιλώ!<br/>',NULL,188256,1);
INSERT INTO stanza VALUES('GK110','1','Έχω λάβει Αυτόν στο πνεύμα<br/>Και θα Τον υπηρετώ<br/>Στο ευαγγέλιο του Υιού Του<br/>Είν’ Θεός Τριαδικός!<br/>',NULL,188257,2);
INSERT INTO stanza VALUES('GK110','2','Ο Ιησούς το βίωμά μας<br/>Είναι ότι επιθυμεί<br/>Ο Ουράνιος Πατέρας<br/>Και αυτό που απαιτεί!<br/>',NULL,188258,3);
INSERT INTO stanza VALUES('GK110','3','Καθώς Τον υπηρετούμε<br/>Αφηνόμαστε σ’ Αυτόν<br/>Ζούμε μέσα στο φιλί Του<br/>Ζούμε μέσα στο ιερό!<br/>',NULL,188259,4);
INSERT INTO stanza VALUES('GK110','4','Ως το Σώμα υπηρετούμε<br/>Τίποτα το φυσικό<br/>Μέσω της ανάστασής Του<br/>Λατρεία στον αληθινό!<br/>',NULL,188260,5);
INSERT INTO stanza VALUES('GK111','1','Eλάτε να χαρούμε εν Κυρίω<br/>Κι ας έχει δυσκολίες η ζωή<br/>Τι κι αν τα κύματα μάς σφυροκοπούν<br/>Καλύτερα ψαλμός παρά κλαυθμός<br/>',NULL,188261,1);
INSERT INTO stanza VALUES('GK111','chorus','Χαρείτε εν Κυρίω<br/>Χαρείτε εν Κυρίω<br/>Καλύτερα ψαλμός παρά κλαυθμός<br/>Καλύτερα ζωή παρά σιγή<br/>Γι’ αυτό ας χαιρόμαστε εμείς<br/>',NULL,188262,2);
INSERT INTO stanza VALUES('GK111','2','Ελάτε να χαρούμε εν Κυρίω<br/>Κι ας μας απειλεί ο πλανευτής<br/>Στον αίνο μας τρέμει και θρηνεί αυτός<br/>Καλύτερα ψαλμός παρά κλαυθμός<br/>',NULL,188263,3);
INSERT INTO stanza VALUES('GK111','3','Ελάτε να χαρούμε εν Κυρίω<br/>Και αν η ασθένεια απειλεί<br/>Η δύναμή μας - του Κυρίου η χαρά<br/>Και η θεραπεία παντοτινά<br/>',NULL,188264,4);
INSERT INTO stanza VALUES('GK111','4','Ελάτε να χαρούμε εν Κυρίω<br/>Το σώμα τούτο μας θα χαθεί<br/>Μαζί Του θα είμαστε στην αρπαγή<br/>Λύπες και πόνοι θα ’χουν ξεχαστεί<br/>',NULL,188265,5);
INSERT INTO stanza VALUES('GK112','1','Στα λυχνάρια μας έχουμε λάδι<br/>Και το πνεύμα μας φλέγεται<br/>Προς το πνεύμα μας στρέψε μας, Κύριε<br/>Στρέψε μας ώσπου να ’ρθεις Εσύ<br/>Κύριε! Αμήν! Άλληλούια!<br/>Αναμμένα τα λυχνάρια μας!<br/>Κύριε! Αμήν! Άλληλούια!<br/>Ναι, σε Σε στρεφόμαστε!<br/>',NULL,188266,1);
INSERT INTO stanza VALUES('GK112','2','Μα τα αγγεία χρειάζονται λάδι<br/>Να ’μαστε σ’ ετοιμότητα<br/>Γέμισε τη ψυχή μας ω Κύριε<br/>Για να έχουμε πλεόνασμα<br/>Πλήρωσέ μας! Πλήρωσέ μας!<br/>Κάθε μέρα με το Πνεύμα Σου!<br/>Πλήρωσέ μας! Πλήρωσέ μας!<br/>Με Σένα Κύριε Ιησού!<br/>',NULL,188267,2);
INSERT INTO stanza VALUES('GK112','3','Μόνο τότε θα καίει το λυχνάρι<br/>Μέχρι που να ’ρθει ο Γαμπρός<br/>Και στο γάμο θα πάμε μαζί Του<br/>Καθ’ οδόν θα φαίνεται το φως<br/>Έλα Κύριε! Έλα Κύριε!<br/>Αναμμένους Εσύ να μας βρεις!<br/>Έλα Κύριε! Έλα Κύριε!<br/>Με τη Νύφη να χαρείς!<br/>',NULL,188268,3);
INSERT INTO stanza VALUES('GK113','1','Ω Πατέρα Πηγή ζωής<br/>Ως υιοί στο Όνομά Σου<br/>Είμαστε η έκφρασή Σου<br/>Ω Πατέρα Πηγή ζωής<br/>Στη ζωή Σου, στη ζωή Σου<br/>Έχουμε ενότητα<br/>Στη ζωή Σου, στη ζωή Σου<br/>Στη ζωή Σου είμαστε ένα<br/>',NULL,188269,1);
INSERT INTO stanza VALUES('GK113','2','Για το Λόγο Σου Σ’ ευχαριστώ<br/>Που τη φύση Σου μας δίνει<br/>Κι απ’ τον κόσμο μας χωρίζει<br/>Για το Λόγο Σου Σ’ ευχαριστώ<br/>Δια του Λόγου, δια του Λόγου<br/>Έχουμε ενότητα<br/>Δια του Λόγου, δια του Λόγου<br/>Δια του Λόγου γινόμαστ’ ένα<br/>',NULL,188270,2);
INSERT INTO stanza VALUES('GK113','3','Ω, η δόξα του Τριαδικού!<br/>Δείχνουμε αυτήν τη δόξα<br/>Ως υιοί, τι ευλογία<br/>Ω, η δόξα του Τριαδικού!<br/>Μες στη δόξα, μες στη δόξα<br/>Έχουμε ενότητα<br/>Μες στη δόξα, μες στη δόξα<br/>Μες στη δόξα γινόμαστ’ ένα<br/>',NULL,188271,3);
INSERT INTO stanza VALUES('GK114','1','Με το αίμα του Χριστού μας<br/>Ο εχθρός θα υποταχθεί<br/>Με τη δύναμη κι ισχύ του<br/>Θα ’σαι υπερνικητής<br/>Με το αίμα του Χριστού μας<br/>Ο εχθρός θα υποταχθεί<br/>Με τη δύναμη κι ισχύ του<br/>Θα ’σαι υπερνικητής<br/>',NULL,188272,1);
INSERT INTO stanza VALUES('GK114','2','Με το αίμα του Χριστού μας<br/>Διώξε τον κατήγορο<br/>Με το αίμα σαν ασπίδα<br/>Στάσου ενάντια σ’ αυτόν<br/>',NULL,188273,2);
INSERT INTO stanza VALUES('GK114','3','Με το αίμα του Χριστού μας<br/>Εμπιστεύσου τον Θεό<br/>Με του λυτρωτή το αίμα<br/>Μας συγχώρησε ο Θεός<br/>',NULL,188274,3);
INSERT INTO stanza VALUES('GK114','4','Με το αίμα του Χριστού μας<br/>Δήλωσε τη θέση σου<br/>Με το αίμα που δεσπόζει<br/>Τη νίκη να μοιραστείς<br/>',NULL,188275,4);
INSERT INTO stanza VALUES('GK114','5','Με το αίμα του Χριστού μας<br/>Εξουσία θα ’χεις εσύ<br/>Τοποθέτησε το αίμα<br/>Κι ο εχθρός θα ηττηθεί<br/>',NULL,188276,5);
INSERT INTO stanza VALUES('GK114','6','Με το αίμα του Χριστού μας<br/>Κάθεσαι εκεί ψηλά<br/>Με την ισχύ του Κυρίου<br/>Αρχές κι εξουσίες νικάς<br/>',NULL,188277,6);
INSERT INTO stanza VALUES('GK115','1','Είσαι ο ύψιστος Θεός<br/>Ωστόσο έγινες θνητός<br/>Έγινες άνθρωπος ταπεινός<br/>Κύριε, δεν Σε ξεχνώ<br/>',NULL,188278,1);
INSERT INTO stanza VALUES('GK115','2','Τη δόξα Σου απαρνήθηκες<br/>Στη σάρκα με μας σκήνωσες<br/>Το κάλλος Σου στερήθηκες<br/>Κύριε, δεν Σε ξεχνώ<br/>',NULL,188279,2);
INSERT INTO stanza VALUES('GK115','3','Ρίζα από διψασμένη γη<br/>Άνθρωπος θλίψεων ήσουν Εσύ<br/>Βίωσες την καταφρόνηση<br/>Κύριε, δεν Σε ξεχνώ<br/>',NULL,188280,3);
INSERT INTO stanza VALUES('GK115','4','Ναι, η καρδιά Σου ήταν ταπεινή<br/>Πρόθυμη να θυσιαστεί<br/>Δίχως να φέρεις αντίρρηση<br/>Κύριε, δεν Σε ξεχνώ<br/>',NULL,188281,4);
INSERT INTO stanza VALUES('GK115','5','Σαν άνθρωπος είσαι τρυφερός<br/>Σε όλα είσαι ισόρροπος<br/>Θυσία αλφίτων προς τον Θεό<br/>Κύριε, δεν Σε ξεχνώ<br/>',NULL,188282,5);
INSERT INTO stanza VALUES('GK115','6','Και του Θεού το θέλημα<br/>Παρά του εχθρού τα ψέματα<br/>Εσύ το εκπλήρωσες τέλεια<br/>Κύριε, δεν Σε ξεχνώ<br/>',NULL,188283,6);
INSERT INTO stanza VALUES('GK115','7','Ήσουν υπάκουος στον Θεό<br/>Και γεύτηκες το θάνατο<br/>Πήρες τη θέση μου στο σταυρό<br/>Κύριε, δεν Σε ξεχνώ<br/>',NULL,188284,7);
INSERT INTO stanza VALUES('GK115','8','Γι’ αυτό τώρα έχεις υψωθεί<br/>Απ’ τον Πατέρα με τιμή<br/>Κάθε γόνατο θα καμφθεί<br/>Κύριε, Σε προσκυνώ<br/>',NULL,188285,8);
INSERT INTO stanza VALUES('GK116','1','Ω, τι πιστός, τι έµπιστος<br/>Θεέ µου, είσαι Εσύ<br/>Για την πιστότητά Σου<br/>Το σύµπαν µαρτυρεί<br/>Η πιστότητά Σου σταθερή<br/>Γι’ αυτό Σε ευλογώ<br/>Η υπόσχεσή Σου στέκεται<br/>Για µε στον ουρανό<br/>',NULL,188286,1);
INSERT INTO stanza VALUES('GK116','2','Σε Σένα δεν υπάρχει, Θεέ<br/>Καµία µεταβολή<br/>Αυτός που ήσουν, είσαι<br/>Και θα ’σαι πάντα Εσύ<br/>',NULL,188287,2);
INSERT INTO stanza VALUES('GK116','3','Ο Λόγος Σου είν’ σίγουρος<br/>Έχει υπόσταση<br/>Αν φύγει η γη κι ο ουρανός<br/>Ο Λόγος θα διαρκεί<br/>',NULL,188288,3);
INSERT INTO stanza VALUES('GK116','4','Τα δώρα Σου αµετάκλητα<br/>Όπως το κάλεσµα<br/>Η χάρη και το έλεος<br/>Είναι αιώνια<br/>',NULL,188289,4);
INSERT INTO stanza VALUES('GK116','5','Στην πίστη και στο Λόγο Σου<br/>Μπορώ να βασιστώ<br/>Την υπόσχεση της σωτηρίας<br/>Μπορώ να διεκδικώ<br/>',NULL,188290,5);
INSERT INTO stanza VALUES('GK116','6','Κι αν η σάρκα Σε αρνηθεί<br/>Εσύ θα ’σαι πιστός<br/>Εσύ ποτέ δεν θα αρνηθείς<br/>Το δικό Σου εαυτό<br/>',NULL,188291,6);
INSERT INTO stanza VALUES('GK116','7','Πιστός είσαι στο κάλεσµα<br/>Και στην υπόσχεση<br/>Η δική Σου η πιστότητα<br/>Είναι για µε τροφή<br/>',NULL,188292,7);
INSERT INTO stanza VALUES('GK116','8','Το ουράνιο τόξο µαρτυρεί<br/>Το πόσο είσαι πιστός<br/>Κι η Άγια Πόλη επιδεικνύει<br/>Αυτό το γεγονός<br/>',NULL,188293,8);
INSERT INTO stanza VALUES('GK117','1','Θεέ Πατέρα, όταν ατενίζω<br/>Τα θαύματα του ουρανού, της γης<br/>Δημιουργήματα μικρά, μεγάλα<br/>Που δείχνουν τη δική Σου την ισχύ<br/>',NULL,188294,1);
INSERT INTO stanza VALUES('GK117','chorus','Τότε όλο μου το είναι Σε υμνεί<br/>Τι θαυμαστός που είσ’ Εσύ<br/>Και αιώνια ο ύμνος θα διαρκεί<br/>Τι θαυμαστός που είσ’ Εσύ!<br/>',NULL,188295,2);
INSERT INTO stanza VALUES('GK117','2','Καθώς τη χάρη Σου απολαμβάνω<br/>Και σκέφτομαι τι έκανες Εσύ<br/>Τον Υιό Σου έστειλες να μας λυτρώσει<br/>Η νέα κτίση να ’μαστε εμείς<br/>',NULL,188296,3);
INSERT INTO stanza VALUES('GK117','3','Στην εκκλησία που τόσοι συμμετέχουν<br/>Κι όλοι μαζί εκφράζουν τη ζωή<br/>Που οικοδομούν τον οίκο το δικό Σου<br/>Και Συ Θεέ, εντός τους κατοικείς<br/>',NULL,188297,4);
INSERT INTO stanza VALUES('GK117','4','Σαν σκέφτομαι τον μέλλοντα αιώνα<br/>Όταν θα ’μαι στη Νέα Ιερουσαλήμ<br/>Όταν Εσύ τα πάντα θα γεμίζεις<br/>Σ’ έναν καινούργιο ουρανό και γη<br/>',NULL,188298,5);
INSERT INTO stanza VALUES('GK118','1','Είδαμε το φως το αληθινό<br/>Όμως δεν αρκεί μόνο αυτό<br/>Ο Χριστός πρέπει να ’ναι για μας<br/>Το παν μας στη ζωή<br/>Ναι, Τον βλέπουμε στην προσευχή<br/>Μες στο Λόγο, στη συνάθροιση<br/>Όμως κάθε μέρα στη ζωή<br/>Τι είν’ Αυτός για μας;<br/>Αλληλούια, μας φωτίζει Αυτός<br/>Όμως πόσο θα ’ναι αληθινός<br/>Αν στρεφόμαστε σ’ Αυτόν<br/>Κάθε στιγμή κάθε λεπτό<br/>Σε όλα να ’ναι πρώτα Αυτός<br/>Βίωσε την πραγματικότητα<br/>Ξεχνά πια τις γενικότητες<br/>Αν Αυτός μας γίνει βίωμα<br/>Θαν’ το παν για μας<br/>',NULL,188299,1);
INSERT INTO stanza VALUES('GK118','2','Στη ζωή μας παρουσιάζονται<br/>Ευκαιρίες απ’ τον Θεό για μας<br/>Όλα βαίνουν τέλεια, γι’ αυτό<br/>Ας βρούμε τον Χριστό!<br/>Να ’μαστέ αγγεία του Χριστού<br/>Για να φαίνεται η εικόνα Του<br/>Πρέπει Αυτός σε μας να υπερισχύει<br/>Να υπερισχύει<br/>Αλληλούια, εμείς το Σώμα Του<br/>Το θάνατό Του φέρουμε παντού<br/>Έτσι φανερώνεται Αυτός<br/>Το θνητό το σώμα φθίνει<br/>Κι ο Χριστός μέσα μας λάμπει, έτσι<br/>Μέσα απ’ τα αγγεία τα πήλινα<br/>Θα φανεί η πραγματικότητα<br/>Τότε του ευαγγελίου το φως<br/>Θα φανεί σε εμάς<br/>Όχι μόνο πια κηρύγματα<br/>Όμως και πραγματικότητα<br/>Για να βλέπουν ότι ο Χριστός<br/>Είν’ το παν για μας<br/>',NULL,188300,2);
INSERT INTO stanza VALUES('GK119','1','Υπάρχει Ένας στη δόξα<br/>Η ζωή Του είναι για εμέ<br/>Αγνός είναι κι άγιος<br/>Θριαμβευτικός<br/>Σοφός κι αγαθός<br/>Τόσο τρυφερός!<br/>Η ζωή Του στη δόξα<br/>Ναι, είναι για εμέ<br/>Η ζωή Του στη δόξα<br/>Ναι, είναι για εμέ<br/>',NULL,188301,1);
INSERT INTO stanza VALUES('GK119','2','Υπάρχει Ένας στη δόξα<br/>Η ζωή Του είναι για εμέ<br/>Το θάνατο νίκησε<br/>Δεν έχει δεσμά<br/>Στη ζωή κυβερνάει<br/>Ω! Τι βασιλιάς!<br/>Η ζωή Του στη δόξα<br/>Ναι, είναι για εμέ<br/>Η ζωή Του στη δόξα<br/>Ναι, είναι για εμέ<br/>',NULL,188302,2);
INSERT INTO stanza VALUES('GK119','3','Υπάρχει Ένας στη δόξα<br/>Η ζωή Του είναι για εμέ<br/>Ασθένεια δεν έχει<br/>Ούτε αδυναμία<br/>Αγέραστος είναι<br/>Ω! Τι κραταιός!<br/>Η ζωή Του στη δόξα<br/>Ναι, είναι για εμέ<br/>Η ζωή Του στη δόξα<br/>Ναι, είναι για εμέ<br/>',NULL,188303,3);
INSERT INTO stanza VALUES('GK119','4','Υπάρχει Ένας στη δόξα<br/>Η ζωή Του είναι για εμέ<br/>Η ειρήνη Του μένει<br/>Έχει υπομονή<br/>Χαρούμενος λάμπει<br/>Καρτερεί να δει<br/>Τη ζωή Του στη δόξα<br/>Να είναι σε εμέ<br/>Τη ζωή Του στη δόξα<br/>Να είναι σε εμέ<br/>',NULL,188304,4);
INSERT INTO stanza VALUES('GK120','1','Μένει σ’ εμέ το θείο χρίσμα<br/>Με διδάσκει σ’ όλα αυτό<br/>Με οδηγεί να ζω εν τω Χριστώ<br/>Και στο θρόνο Του να ’ρθώ<br/>',NULL,188305,1);
INSERT INTO stanza VALUES('GK120','chorus','Μένει μέσα μου το χρίσμα Του<br/>Το θείο χρίσμα Του<br/>Και με διδάσκει αυτό<br/>Μένει μέσα μου το χρίσμα Του<br/>Και με διδάσκει διαρκώς<br/>',NULL,188306,2);
INSERT INTO stanza VALUES('GK120','2','Είν’ η ροή του Πνεύματος Του<br/>Σαν το λάδι χρίσματος<br/>Χάρη στο ράντισμα του αίματος<br/>Θα ισχύει δια παντός<br/>',NULL,188307,3);
INSERT INTO stanza VALUES('GK120','3','Με την ουσία Του με χρίζει<br/>Να γνωρίζω τον Θεό<br/>Θα με γεμίσει το στοιχείο Του<br/>Για να γίνω σαν Αυτόν<br/>',NULL,188308,4);
INSERT INTO stanza VALUES('GK120','4','Με το χρίσμα της ζωής εντός μου<br/>Η φωνή Του μ’ οδηγεί<br/>Στο φως της αλήθειας περπατώ<br/>Κι η αγάπη με πληροί<br/>',NULL,188309,5);
INSERT INTO stanza VALUES('GK121','1','Δώσε μάχη μες στο Σώμα<br/>Μόνος σου μην προσπαθείς<br/>Το Κεφάλι με το Σώμα<br/>Απ’ το θρόνο πολεμά<br/>Δώσε μάχη μες στο Σώμα<br/>Με τη νίκη του Χριστού<br/>Ενωμένος με το Σώμα<br/>Θα ’σαι πάντα νικητής<br/>',NULL,188310,1);
INSERT INTO stanza VALUES('GK121','2','Έχουμε την πανοπλία<br/>Που μας έδωσε ο Θεός<br/>Όταν είσαι μες στο Σώμα<br/>Ωφελείσαι διαρκώς<br/>',NULL,188311,2);
INSERT INTO stanza VALUES('GK121','3','Η χτισμένη εκκλησία<br/>Καταργεί το Σατανά<br/>Με τα μέλη του το Σώμα<br/>Θα νικήσει τον εχθρό<br/>',NULL,188312,3);
INSERT INTO stanza VALUES('GK121','4','Ναι, το Σώμα με τον Κύριο<br/>Κάθονται στον ουρανό<br/>Κι οι αρχές και οι εξουσίες<br/>Υποτάσσονται σε Αυτόν<br/>',NULL,188313,4);
INSERT INTO stanza VALUES('GK121','5','Με τα μέλη μες στο Σώμα<br/>Τον Θεό εκπροσωπείς<br/>Με τη δέηση και το αίμα<br/>Ο εχθρός θα ηττηθεί<br/>',NULL,188314,5);
INSERT INTO stanza VALUES('GK121','6','Στα ουράνια δίνεις μάχη<br/>Κι είσαι υπερνικητής<br/>Ο στρατιώτης του Κυρίου<br/>Δια Αυτού η δύναμη<br/>',NULL,188315,6);
INSERT INTO stanza VALUES('GK121','7','Συνεχώς να δίνεις μάχη<br/>Μες στο Σώμα θριαμβευτής<br/>Και θα δένεις και θα λύνεις<br/>Στους εχθρούς θα υπερισχύεις<br/>',NULL,188316,7);
INSERT INTO stanza VALUES('GK122','1','Υπερνικητής θα γίνεις;<br/>Ο Κύριος σε καλεί!<br/>Και το πως ας μη γνωρίζεις<br/>Θα Τον ακολουθείς;<br/>Υπερνικητής θα γίνεις;<br/>Θ’ ανταποκριθείς;<br/>Ναι, σε προσκαλεί ο Κύριος<br/>Άκου τη φωνή!<br/>',NULL,188317,1);
INSERT INTO stanza VALUES('GK122','2','Υπερνικητής θα γίνεις;<br/>Αυτός θα σε ελκύει;<br/>Θάναι η πρώτη σου αγάπη<br/>Από εδώ και στο εξής;<br/>',NULL,188318,2);
INSERT INTO stanza VALUES('GK122','3','Υπερνικητής θα γίνεις;<br/>Θα βασιστείς σ’ Αυτόν;<br/>Τους διωγμούς θα τους αντέξεις<br/>Πιστά θ’ ακολουθείς;<br/>',NULL,188319,3);
INSERT INTO stanza VALUES('GK122','4','Υπερνικητής θα γίνεις;<br/>Γι’ Αυτόν θα μαρτυρείς;<br/>Μακριά από θρησκείες<br/>Με μάννα εσύ θα ζεις;<br/>',NULL,188320,4);
INSERT INTO stanza VALUES('GK122','5','Υπερνικητής θα γίνεις;<br/>Αγνός κι αληθινός;<br/>Θα αψηφήσεις τις προσμείξεις<br/>Θάχεις εξουσία;<br/>',NULL,188321,5);
INSERT INTO stanza VALUES('GK122','6','Υπερνικητής θα γίνεις;<br/>Αυτόν θα εμπιστευθείς;<br/>Θ’ αφήσεις τα νεκρά τα έργα<br/>θα έχεις τη ζωή;<br/>',NULL,188322,6);
INSERT INTO stanza VALUES('GK122','7','Υπερνικητής θα γίνεις;<br/>Ουδέποτε χλιαρός;<br/>Θα εκζητείς να βλέπεις όλα<br/>Όσα έχει Αυτός;<br/>',NULL,188323,7);
INSERT INTO stanza VALUES('GK122','8','Υπερνικητής θα γίνεις;<br/>Ακόμη σε καλεί!<br/>Στην επιθυμία Του τώρα<br/>Θ’ ανταποκριθείς;<br/>',NULL,188324,8);
INSERT INTO stanza VALUES('GK123','1','Η μέρα φθάνει που ο Ιησούς θα έλθει<br/>Ο χρόνος μας δεν πρέπει να χαθεί<br/>Προετοίμασέ μας για το «Ιδού ο Κύριος»<br/>Ω, Κύριε, Εσύ, κάθε στιγμή<br/>Όταν θα έλθει, θα ’μαστε στο γάμο;<br/>Όταν θα έλθει, θα μοιάζουμε σ’ Αυτόν;<br/>Τις φρόνιμες ο Ιησούς να παραλάβει<br/>Ας μη βρεθούμε εκτός της εορτής<br/>',NULL,188325,1);
INSERT INTO stanza VALUES('GK123','2','Βοήθα, Ιησού, να μη χαθεί ο χρόνος<br/>Να ’χουμε λάδι στα αγγεία μας<br/>Στις θλίψεις μας αμήν να λέμε πάντα<br/>Αύξησε, Κύριε την αγάπη μας<br/>Ναι, έρχεται! Κάθε στιγμή αξίζει<br/>Το λάδι μας ας είναι άφθονο<br/>Αμήν στις θλίψεις και δοκιμασίες<br/>Κι η βασιλεία θα ’ναι δικιά μας<br/>',NULL,188326,2);
INSERT INTO stanza VALUES('GK123','3','Κύριε, πάρε κάθε επιθυμία<br/>Το πρόσωπό Σου να ατενίζουμε<br/>Να εκζητούμε πάντα τον Νυμφίο<br/>Και στον αγώνα να επιμένουμε<br/>Όταν θα έλθει, θα ’μαστε μαζί Του;<br/>Το πρόσωπό Του εμείς θα βλέπουμε;<br/>Ας μην γυρνάμε εμείς στην οκνηρία<br/>Ας μένουμε στην παρουσία Του<br/>',NULL,188327,3);
INSERT INTO stanza VALUES('GK123','4','Ως Νύμφη Του ας Τον υποδεχθούμε<br/>Με λύχνους και καρδιές που φλέγονται<br/>Προς τον Νυμφίο τα μάτια μας στραμμένα<br/>Για να χαιρόμαστε μαζί μ’ Αυτόν<br/>Ω, τι χαρά - ο Κύριος με τη Νύμφη<br/>Ω, τι χαρά - αιώνια μαζί<br/>Τι ανάπαυση, χαρά, αγάπη και χάρη<br/>Να είμαστε η Νύμφη στη γιορτή!<br/>',NULL,188328,4);
INSERT INTO stanza VALUES('GK124','1','Γιατί φοβάμαι, αγωνιώ<br/>Μήπως δεν πλήρωσε ο Χριστός<br/>Το χρέος στο σταυρό;<br/>Την αμαρτία πλήρωσε<br/>Το χρέος μου εξόφλησε<br/>Και παραγράφηκε<br/>',NULL,188329,1);
INSERT INTO stanza VALUES('GK124','2','Με τέλεια απολύτρωση<br/>Τα πάντα Αυτός εξόφλησε<br/>Και μ’ ελευθέρωσε<br/>Και δεν φοβάμαι την οργή<br/>Του Νόμου την κατακραυγή<br/>Σκέπη το αίμα Του<br/>',NULL,188330,2);
INSERT INTO stanza VALUES('GK124','3','Αυτός μου χάρισε ζωή<br/>Συγχώρεση και απαλλαγή<br/>Εξόφληση χρεών<br/>Τώρα ο Θεός πια δεν μπορεί<br/>Να απαιτήσει η ποινή<br/>Διπλά να εφαρμοστεί<br/>',NULL,188331,3);
INSERT INTO stanza VALUES('GK124','4','Την τέλεια ανάπαυση<br/>Ειρήνη, απελευθέρωση<br/>Μου χάρισε ο Σωτήρ<br/>Το αίμα Του με κάλυψε<br/>Την καταδίκη έσβησε<br/>Για μένα πέθανε<br/>',NULL,188332,4);
INSERT INTO stanza VALUES('S1','1','Gloria‿dad a Dios el Padre,<br/>Y al Hijo loor;<br/>Al Espíritu dad gloria;<br/>Uno son.<br/>',NULL,188333,1);
INSERT INTO stanza VALUES('S1','2','Su creación inmensurable,<br/>Fruto de Su plan;<br/>Al mirarla, nos inspira<br/>A adorar.<br/>',NULL,188334,2);
INSERT INTO stanza VALUES('S1','3','Mas Tú anhelas muchos hijos,<br/>Nuestro Dios de amor,<br/>Que en el Hijo hoy te alaben<br/>En unión.<br/>',NULL,188335,3);
INSERT INTO stanza VALUES('S1','4','Fue Tu pensamiento santo<br/>Dar al hombre ver,<br/>Los secretos de Tu afecto<br/>Para él.<br/>',NULL,188336,4);
INSERT INTO stanza VALUES('S1','5','Cristo el mal ha destruido<br/>Por Su redención;<br/>¡Te adoramos como nueva<br/>Creación!<br/>',NULL,188337,5);
INSERT INTO stanza VALUES('S1','6','Hoy al Padre demos gloria,<br/>Y al Hijo de Dios;<br/>Al Espíritu dad gloria;<br/>Uno son.<br/>',NULL,188338,6);
INSERT INTO stanza VALUES('S2','1','Padre nuestro, te‿adoramos<br/>Como hijos de Tu grey;<br/>Escogidos en Tu Cristo<br/>Somos santos hoy en Él.<br/>¡Te‿adoramos! ¡Te‿adoramos!<br/>"Abba, Padre" al proclamar.<br/>¡Te‿adoramos! ¡Te‿adoramos!<br/>"Abba, Padre"‿a proclamar.<br/>',NULL,188339,1);
INSERT INTO stanza VALUES('S2','2','Hijo eterno, te‿adoramos,<br/>Oh, Cordero fiel de Dios;<br/>Ante‿el trono nos postramos,<br/>Pues trajiste redención.<br/>//Adoramos, adoramos,<br/>Al Cordero que murió.//<br/>',NULL,188340,2);
INSERT INTO stanza VALUES('S2','3','Tres en Uno, te alabamos,<br/>Padre, Hijo, Espíritu;<br/>Por la‿herencia que gozamos,<br/>Bajo Tu radiante luz.<br/>//¡Te‿adoramos! ¡Te‿adoramos!<br/>¡Con inmensa gratitud!//<br/>',NULL,188341,3);
INSERT INTO stanza VALUES('S3','1','¡Santo, Santo, Santo, Dios omnipotente!<br/>Te adoraremos por toda la eternidad.<br/>Santo, Santo, Santo, Fuerte y Piadoso!<br/>Dios, Tres en Uno: Santa Trinidad.<br/>',NULL,188342,1);
INSERT INTO stanza VALUES('S3','2','Santo, Santo, Santo! Todos te_adoramos;<br/>Sus coronas los ancianos hechan sobre Ti;<br/>Huestes celestiales rinden sus tributos<br/>Al que es y era y que ha de venir.<br/>',NULL,188343,2);
INSERT INTO stanza VALUES('S3','3','Santo, Santo, Santo! Aunque_estés oculto,<br/>Y Tu gloria_escondas ante_el ojo pecador;<br/>Sólo Tu_eres santo, sólo Tu perfecto<br/>En Tu pureza, fuerza y amor.<br/>',NULL,188344,3);
INSERT INTO stanza VALUES('S4','1','¡Gloria, gloria dad al Padre!<br/>¡Gloria, gloria al Hijo dad!<br/>¡Al Espíritu dad gloria!<br/>¡Al Tres-Uno, gloria dad!<br/>',NULL,188345,1);
INSERT INTO stanza VALUES('S4','chorus','¡Alabadle! ¡Alabadle!<br/>¡Alabad al Triuno Dios!<br/>¡Dadle gloria! ¡Dadle gloria!<br/>¡Maravillas nos ha hecho Dios!<br/>',NULL,188346,2);
INSERT INTO stanza VALUES('S4','2','Lo que el Padre se propuso,<br/>Cristo el Hijo realizó,<br/>El Espíritu imparte,<br/>Alabad al Triuno Dios!<br/>',NULL,188347,3);
INSERT INTO stanza VALUES('S5','1','Al Dios que_emana bendición<br/>Toda criatura alabad;<br/>¡Al  Padre, Hijo, Espíritu<br/>Huestes del cielo adorad!<br/>',NULL,188348,1);
INSERT INTO stanza VALUES('S5','2','Load al Padre, Fuente es;<br/>Honrad al Hijo, el canal,<br/>Gloria al Espíritu, el fluir;<br/>Grata porción: ¡la Trinidad!<br/>',NULL,188349,2);
INSERT INTO stanza VALUES('S6','1','Oh Padre, eterno Dios Tú eres<br/>El increado gran YO SOY;<br/>Tú el Anciano de los días,<br/>Por las edades hasta hoy.<br/>',NULL,188350,1);
INSERT INTO stanza VALUES('S6','2','Eternamente Dios Tú eres,<br/>De espacio y tiempo más allá;<br/>La plenitud de lo eterno<br/>Sin un principio y sin final.<br/>',NULL,188351,2);
INSERT INTO stanza VALUES('S6','3','La fuente eterna, Tú de todo,<br/>Aun antes de los cielos, Tú;<br/>De los primeros, el primero,<br/>Y más que todos en virtud.<br/>',NULL,188352,3);
INSERT INTO stanza VALUES('S6','4','La vida eres que perdura,<br/>No tienes fin de edad á edad;<br/>Tú permaneces para siempre,<br/>Después del último Tú estás.<br/>',NULL,188353,4);
INSERT INTO stanza VALUES('S6','5','El Alfa, eres el primero,<br/>La Omega, que viene al final;<br/>Principio y Fin, el todo Tú_eres,<br/>Perfecto_y completo en verdad.<br/>',NULL,188354,5);
INSERT INTO stanza VALUES('S6','6','Te alabamos, oh Eterno,<br/>Exaltamos Tu infinidad;<br/>Te alabamos, Inmensurable,<br/>Exaltamos Tu vastedad.<br/>',NULL,188355,6);
INSERT INTO stanza VALUES('S7','1','El verdadero‿Espíritu,<br/>Padre santo‿eres Tú;<br/>Te adoramos en verdad<br/>En nuestro‿espíritu.<br/>',NULL,188356,1);
INSERT INTO stanza VALUES('S7','2','Formaste nuestro‿espíritu<br/>Para‿adorarte‿a Ti,<br/>Y con Tu‿Espíritu uno ser<br/>En armonía‿así.<br/>',NULL,188357,2);
INSERT INTO stanza VALUES('S7','3','Vino‿en el Hijo‿el Padre Dios,<br/>El Hijo‿Espíritu es,<br/>Llegando‿a nuestro‿espíritu,<br/>¡Qué gracia‿a nuestro ser!<br/>',NULL,188358,3);
INSERT INTO stanza VALUES('S7','4','Palabra‿eterna Tu‿Hijo es,<br/>Espíritu también;<br/>Renueva nuestro‿espíritu,<br/>Su vida‿infunde‿en él.<br/>',NULL,188359,4);
INSERT INTO stanza VALUES('S7','5','Tu‿Espíritu‿en el nuestro‿está,<br/>Da testimonio‿allí,<br/>Que somos por Tu‿Espíritu<br/>Tus hijos hoy aquí.<br/>',NULL,188360,5);
INSERT INTO stanza VALUES('S7','6','Nos guía hoy Tu‿Espíritu<br/>Para seguirle‿en paz;<br/>Espirituales nos hará<br/>La vida que‿Él nos da.<br/>',NULL,188361,6);
INSERT INTO stanza VALUES('S7','7','Ahora nuestro espíritu<br/>Podemos liberar;<br/>Te alabamos para así<br/>Tu imagen expresar.<br/>',NULL,188362,7);
INSERT INTO stanza VALUES('S7','8','Te alabamos, Padre Dios,<br/>Espíritu‿eres Tú;<br/>Te adoramos en verdad<br/>En nuestro‿espíritu.<br/>',NULL,188363,8);
INSERT INTO stanza VALUES('S8','1','¡Fuente de vida‿eres, oh Dios<br/>Cuán libre‿es Tu caudal!<br/>¡Como‿agua viva‿es Tu fluir,<br/>Hasta la‿eternidad!<br/>',NULL,188364,1);
INSERT INTO stanza VALUES('S8','2','Fluiste‿en el Hijo‿en amor,<br/>Entre la‿humanidad;<br/>Hoy fluyes como‿Espíritu,<br/>Con gracia sin igual.<br/>',NULL,188365,2);
INSERT INTO stanza VALUES('S8','3','Aunque‿en pecado y maldad,<br/>Perdido‿en confusión,<br/>Mas en Su Hijo Dios nos dio<br/>La vida‿y redención.<br/>',NULL,188366,3);
INSERT INTO stanza VALUES('S8','4','Te desdeñamos y además,<br/>Te‿hacemos contristar;<br/>Mas vienes como‿Espíritu,<br/>Tu vida‿a todos dar.<br/>',NULL,188367,4);
INSERT INTO stanza VALUES('S8','5','Mezclado en el Hijo‿estás,<br/>Como‿el Espíritu;<br/>En comunión nos ungirás<br/>Para‿aumentarte Tú.<br/>',NULL,188368,5);
INSERT INTO stanza VALUES('S8','6','Fluye‿el amor del Padre Dios,<br/>La gracia de Jesús,<br/>Para de Dios participar<br/>Por el Espíritu.<br/>',NULL,188369,6);
INSERT INTO stanza VALUES('S8','7','Oh Padre, Hijo,‿Espíritu,<br/>Nos cuidas sin cesar;<br/>Te adoramos por Tu‿amor,<br/>Cantando‿en unidad.<br/>',NULL,188370,7);
INSERT INTO stanza VALUES('S9','1','Dios de amor y luz Tú eres,<br/>En el Hijo vida das;<br/>Alumbrando y amando,<br/>Tú la vida impartirás.<br/>',NULL,188371,1);
INSERT INTO stanza VALUES('S9','chorus','¡Dios de amor! ¡Dios de luz!<br/>En el Hijo vida das;<br/>Alumbrando y amando,<br/>Tú la vida impartirás.<br/>',NULL,188372,2);
INSERT INTO stanza VALUES('S9','2','El amor Tu ser revela,<br/>Y Tus obras por la luz;<br/>Luz externa, amor interno,<br/>El amor conlleva luz.<br/>',NULL,188373,3);
INSERT INTO stanza VALUES('S9','3','El amor se expresa en gracia,<br/>Y la luz, en la verdad;<br/>Por Tu luz te conocemos;<br/>Por Tu amor te haces real.<br/>',NULL,188374,4);
INSERT INTO stanza VALUES('S9','4','Por Tu amor, en el Calvario,<br/>Tú nos diste vida, oh Dios;<br/>La luz hace que a la sangre,<br/>Le demos aplicación.<br/>',NULL,188375,5);
INSERT INTO stanza VALUES('S9','5','Por amor, como la vida,<br/>Nos trajiste a comunión;<br/>En Tu luz la sangre limpia,<br/>Y nos guarda en comunión.<br/>',NULL,188376,6);
INSERT INTO stanza VALUES('S9','6','Por la luz y por la sangre<br/>Conocemos hoy la unción;<br/>Fluirá así la vida<br/>Con la esencia de Tu amor.<br/>',NULL,188377,7);
INSERT INTO stanza VALUES('S9','7','Por Tu amor somos Tus hijos,<br/>Abba Padre eres Tú;<br/>Nos harás igual al Hijo,<br/>Al cambiar la noche en luz.<br/>',NULL,188378,8);
INSERT INTO stanza VALUES('S9','chorus','Por Tu gracia Y verdad<br/>Vemos hoy Tu amor y luz;<br/>Sin cesar te alabaremos<br/>Por mostrarnos tal virtud!<br/>',NULL,188379,9);
INSERT INTO stanza VALUES('S10','1','Oh, sabio,_invisible y Dios inmortal,<br/>Luz inaccesible rodéandote_está.<br/>Anciano de Días, bendito_en honor,<br/>Por Tu magno nombre te damos loor.<br/>',NULL,188380,1);
INSERT INTO stanza VALUES('S10','2','Sin pausa, sin prisa, silente cual luz,<br/>Sin falta ni exceso, así reinas Tú.<br/>Tu justicia_excelsa, cual cumbre sin par;<br/>Tus nubes son fuentes de_amor y bondad.<br/>',NULL,188381,2);
INSERT INTO stanza VALUES('S10','3','Sin excepción, vida a todos Tú das;<br/>De todas las vidas eres realidad.<br/>Brotamos cual hojas con vida fugáz;<br/>Morimos, más Tú nunca has de cambiar.<br/>',NULL,188382,3);
INSERT INTO stanza VALUES('S10','4','Gran Padre de gloria y luz celestial,<br/>Tus ángeles cantan cubriendo su faz.<br/>Loor te rendimos, mas hoy haznos ver<br/>Que_oculto Tu_estás en la luz de Tu ser.<br/>',NULL,188383,4);
INSERT INTO stanza VALUES('S10','5','Oh, sabio,_invisible y Dios inmortal,<br/>Luz inaccesible rodéandote_está.<br/>Anciano de Días, bendito_en honor,<br/>Por Tu magno nombre te damos loor.<br/>',NULL,188384,5);
INSERT INTO stanza VALUES('S11','1','Oh Dios, tan trascendente,<br/>Tan santo eres Tú;<br/>Nadie puede igualarte,<br/>Incomparable, Tú.<br/>En todo_el universo<br/>Lo más santo eres Tú,<br/>Por Tu naturaleza<br/>Imperio y virtud.<br/>',NULL,188385,1);
INSERT INTO stanza VALUES('S11','2','Tan único Y distinto,<br/>No sólo justo y puro,<br/>No sólo sin defectos,<br/>Mas Tú eres perfección.<br/>No_hay nada que Te alcance,<br/>O que sea Tu_igual;<br/>Si algo te reemplaza<br/>Insulto te será.<br/>',NULL,188386,2);
INSERT INTO stanza VALUES('S11','3','Excedes la excelencia,<br/>Pues eres superior;<br/>No sólo eres fino,<br/>Mas sin comparación.<br/>Difieres de los justos<br/>No hay justo como Tú;<br/>Excelsa es Tu belleza,<br/>Tu fama y virtud.<br/>',NULL,188387,3);
INSERT INTO stanza VALUES('S11','4','Tu santidad excelsa<br/>Es nuestro eterno bien;<br/>Pues Tu esencia santa<br/>Legaste a nuestro ser.<br/>Aun Tu trascendencia<br/>Es nuestra por la fe.<br/>Mas santos por Tu vida<br/>Seremos al crecer.<br/>',NULL,188388,4);
INSERT INTO stanza VALUES('S11','5','Te adoramos, Padre<br/>Hoy por Tu santidad,<br/>Por Tu naturaleza<br/>Trascendente y sin par.<br/>Santa naturaleza<br/>Distinta y sin igual,<br/>Por siempre será nuestra<br/>Nos santificará.<br/>',NULL,188389,5);
INSERT INTO stanza VALUES('S12','1','Oh Padre, eres inmarcesible,<br/>Nuevo siempre‿eres Tú,<br/>Como‿el rocío siempre‿estás fresco,<br/>Siempre viviente, Tú.<br/>',NULL,188390,1);
INSERT INTO stanza VALUES('S12','chorus','Oh, Padre,‿eres inmutable,<br/>No‿envejeces jamás;<br/>Se despliega por las edades,<br/>Tu fresca novedad.<br/>',NULL,188391,2);
INSERT INTO stanza VALUES('S12','2','Tú eres Dios y Tú eres “nuevo”;<br/>Todo‿es viejo sin Ti,<br/>Pero contigo todo es fresco,<br/>Aunque‿años pasen mil.<br/>',NULL,188392,3);
INSERT INTO stanza VALUES('S12','3','Las bendiciones que nos has dado<br/>Tienen Tu novedad;<br/>Tu pacto, Tus caminos son nuevos,<br/>Y siempre‿así serán.<br/>',NULL,188393,4);
INSERT INTO stanza VALUES('S12','4','Hoy ya Tu nueva creación somos,<br/>Un nuevo‿espíritu;<br/>A diario‿el corazón nos renuevas,<br/>Le‿impartes vida Tú.<br/>',NULL,188394,5);
INSERT INTO stanza VALUES('S12','5','La nueva tierra‿y los nuevos cielos<br/>Nueva ciudad tendrán;<br/>Supliendo cada mes nuevos frutos,<br/>Pues todo‿es novedad.<br/>',NULL,188395,6);
INSERT INTO stanza VALUES('S12','6','Oh Padre, Tú eres siempre nuevo,<br/>Todo nuevo‿es en Ti;<br/>Un canto eterno‿y nuevo cantamos,<br/>Nueva‿alabanza‿a Ti.<br/>',NULL,188396,7);
INSERT INTO stanza VALUES('S13','1','Mi Padre Dios, al contemplar Tus obras,<br/>La tierra, el cielo, maravillas son;<br/>Cosas pequeñas, grandes e incontables,<br/>De Tu poder son manifestación.<br/>',NULL,188397,1);
INSERT INTO stanza VALUES('S13','chorus','Todo mi ser canta_alabanza a Ti,<br/>¡Grande eres Tú! ¡Grande eres Tú!<br/>Y por la eternidad yo cantaré,<br/>¡Grande eres Tú! ¡Grande eres Tú!<br/>',NULL,188398,2);
INSERT INTO stanza VALUES('S13','2','La gracia de Tu salvación disfruto,<br/>Al ver al Hijo que enviaste Tú,<br/>Quien al morir nueva creación nos hizo,<br/>Para expresar Tu vida_en plenitud.<br/>',NULL,188399,3);
INSERT INTO stanza VALUES('S13','3','Cuando en la iglesia en comunión bendita,<br/>Veo millones con Tu vida hoy;<br/>Edificados como Tu morada<br/>Para expresar Tu plenitud, mi Dios.<br/>',NULL,188400,4);
INSERT INTO stanza VALUES('S13','4','Mientras espero el siglo venidero,<br/>Anhelo la Nueva Jerusalén,<br/>Con cielos nuevos y una tierra nueva,<br/>Que expresarán la gloria de Tu ser.<br/>',NULL,188401,5);
INSERT INTO stanza VALUES('S14','1','Cuán fidedigno y cuán fiel<br/>Mi Dios Padre eres Tú;<br/>El universo y todo en él<br/>Proclaman tal virtud.<br/>',NULL,188402,1);
INSERT INTO stanza VALUES('S14','chorus','Por Tu firme fidelidad<br/>Mi Dios, te adoro yo ;<br/>Fundada en el cielo está,<br/>Siempre por mí será.<br/>',NULL,188403,2);
INSERT INTO stanza VALUES('S14','2','En Ti no hay mudanza ni<br/>Sombra de variación;<br/>Tal como fuiste eres hoy,<br/>No_habrá alteración.<br/>',NULL,188404,3);
INSERT INTO stanza VALUES('S14','3','Es Tu Palabra como Tú,<br/>No pasará jamás.<br/>El cielo Y tierra pasarán,<br/>Ella perdurará.<br/>',NULL,188405,4);
INSERT INTO stanza VALUES('S14','4','Tu llamamiento y dones, cuán<br/>Irrevocables son;<br/>Tu gracia y Tu gran merced,<br/>Eterna provisión!<br/>',NULL,188406,5);
INSERT INTO stanza VALUES('S14','5','Fiel Tu Palabra es para mí,<br/>Certeza sin igual;<br/>Por ella_y con Tu salvación<br/>Tengo seguridad.<br/>',NULL,188407,6);
INSERT INTO stanza VALUES('S14','6','Si mi_ego me hace desconfiar,<br/>Fiel Tú continuarás;<br/>Toda Palabra cumplirás,<br/>Negarte no podrás.<br/>',NULL,188408,7);
INSERT INTO stanza VALUES('S14','7','Ya que eres fiel para cumplir<br/>Tus promesas en mí,<br/>Me nutro en Tu fidelidad,<br/>Tomándote hasta el fin.<br/>',NULL,188409,8);
INSERT INTO stanza VALUES('S14','8','Allí en la Santa Ciudad<br/>Rodeando el trono hay<br/>Un arco iris que_es señal,<br/>De Tu fidelidad.<br/>',NULL,188410,9);
INSERT INTO stanza VALUES('S15','1','¡Qué gran fidélidad! Oh, Dios mi Padre;<br/>En Ti no‿hay sombra, ni cambias jamás.<br/>Tus compasiones nunca‿han decaído;<br/>Tal como has sido por siempre serás.<br/>',NULL,188411,1);
INSERT INTO stanza VALUES('S15','chorus','¡Qué gran fidelidad!<br/>¡Qué gran fidelidad!<br/>Cada mañana Tu gracia se ve;<br/>Tú sacias todas mis necesidades.<br/>¡Tu gran fidelidad hoy mía es!<br/>',NULL,188412,2);
INSERT INTO stanza VALUES('S15','2','Siembra‿y cosecha, invierno‿y verano,<br/>El orbe‿entero, la luna y‿el sol;<br/>Juntan sus fuerzas como‿un gran testigo<br/>De Tu fidelidad, gracia y‿amor.<br/>',NULL,188413,3);
INSERT INTO stanza VALUES('S15','3','Gozo el perdón y la paz que perdura;<br/>Con Tu presencia me has de guiar.<br/>Fuerza me das y brillante_esperanza,<br/>Tus bendiciones colmándome_están.<br/>',NULL,188414,4);
INSERT INTO stanza VALUES('S16','1','Dios y Padre, te adoramos<br/>Por justicia y equidad;<br/>Nos justificaste en Cristo,<br/>Condenarnos, quién podrá?<br/>Tú eres fidedigno Y justo,<br/>Tu justicia es nuestro bien;<br/>No existe en Ti lo injusto,<br/>Sólo Tu justicia fiel.<br/>',NULL,188415,1);
INSERT INTO stanza VALUES('S16','2','Todas nuestras transgreSiónes<br/>Tú pusiste en Jesús;<br/>El cumplió con Tu justicia<br/>Al llevarlas en la cruz.<br/>Recibiste pleno pago<br/>Con satisfacción total;<br/>No podrías, Dios tan justo,<br/>Exigirnos algo más!<br/>',NULL,188416,2);
INSERT INTO stanza VALUES('S16','3','Como nuestro substituto<br/>Aceptaste a Jesús;<br/>Fue juzgado siendo justo,<br/>Cambiarías de actitud?<br/>Como prueba de justicia<br/>A Tu diestra se sentó;<br/>Pues Tus requisitos justos,<br/>Por completo El cumplió.<br/>',NULL,188417,3);
INSERT INTO stanza VALUES('S16','4','Padre nuestro, por Su sangre<br/>Jesucristo nos legó<br/>La justicia inmutable<br/>Para nuestra protección.<br/>Nos hiciste Tu justicia,<br/>Zarandearnos, quién podrá?<br/>En Jerusalén, la nueva,<br/>Testimonio fiel será.<br/>',NULL,188418,4);
INSERT INTO stanza VALUES('S17','1','Por Tu justicia, Padre Dios,<br/>Te alabamos a una voz<br/>Testificando aquí:<br/>El Juez de todos eres Tú,<br/>Sólo en Tu ser hay rectitud,<br/>No hay error en Ti.<br/>',NULL,188419,1);
INSERT INTO stanza VALUES('S17','2','Oh Padre santo, justo Dios,<br/>Tu rectitud al trono dio<br/>Un fundamento fiel.<br/>Por Tu justicia reinan ya<br/>En Cristo, gracia divinal<br/>Y paz en nuestro ser.<br/>',NULL,188420,2);
INSERT INTO stanza VALUES('S17','3','Por Tu justicia Él murió,<br/>Así Tu Hijo nos ganó,<br/>La redención logró.<br/>Al aplicar tal redención<br/>En Cristo hallamos salvación;<br/>Él nos justificó.<br/>',NULL,188421,3);
INSERT INTO stanza VALUES('S17','4','Para mostrar Tu rectitud<br/>En el pasado diste Tú<br/>Perdón al vil mortal.<br/>Por Tu justicia exhibes hoy<br/>La remisión al pecador<br/>En nuestra era actual.<br/>',NULL,188422,4);
INSERT INTO stanza VALUES('S17','5','Tú juzgarás a todo ser,<br/>Tu rectitud se ha de ver<br/>Por Cristo el Señor;<br/>Mas ¿qué de Ti nos moverá?<br/>Tu rectitud nos guardará<br/>Con gracia y amor.<br/>',NULL,188423,5);
INSERT INTO stanza VALUES('S17','6','Con Tu justicia al reino das<br/>El fundamento de Tu paz,<br/>Cuánta armonía allí!<br/>Se llenarán de rectitud<br/>Los cielos y la tierra, Tú<br/>Lo prometiste así.<br/>',NULL,188424,6);
INSERT INTO stanza VALUES('S18','1','Padre Santo, te alabamos<br/>Con reverente canción;<br/>Santo eres y excelso,<br/>Digno de adoración.<br/>',NULL,188425,1);
INSERT INTO stanza VALUES('S18','2','Padre, Tú eres amoroso,<br/>Justos Tus caminos son;<br/>Tu naturaleza santa<br/>Nos da_a Cristo por porción.<br/>',NULL,188426,2);
INSERT INTO stanza VALUES('S18','3','Separaste pecadores<br/>Por la sangre de Jesús;<br/>Tu verdad nos santifica<br/>Por su divinal virtud.<br/>',NULL,188427,3);
INSERT INTO stanza VALUES('S18','4','Por Tu Espíritu Santo<br/>Nos separas para Ti;<br/>Nuestro espíritu, alma y cuerpo<br/>Santificarás así.<br/>',NULL,188428,4);
INSERT INTO stanza VALUES('S18','5','De Jesús, la vida santa,<br/>Por Tu gracia hoy nos das;<br/>Nos harás participantes<br/>De Tu misma santidad.<br/>',NULL,188429,5);
INSERT INTO stanza VALUES('S18','6','Cuando en la Ciudad Santa,<br/>Llenos de Tu santidad,<br/>"Tú eres santo", por los siglos<br/>Siempre se declarará.<br/>',NULL,188430,6);
INSERT INTO stanza VALUES('S19','1','En Tu sabiduría oh Dios,<br/>Y_excelsa voluntad,<br/>Tu Hijo todo‿ha de llenar<br/>Según Tu eterno plan.<br/>',NULL,188431,1);
INSERT INTO stanza VALUES('S19','chorus','¡Sabiduría inmensa es!<br/>¿Quién la podrá entender?<br/>Oh, Padre Dios, en ella está<br/>Tu gracia y Tu merced.<br/>',NULL,188432,2);
INSERT INTO stanza VALUES('S19','2','Cuán admirable_es Tu creación!<br/>No se podrá sondear;<br/>Es para Ti, por Ti y de Ti,<br/>Qué sabio_es Tu pensar!<br/>',NULL,188433,3);
INSERT INTO stanza VALUES('S19','3','No tiene escape_el pecador,<br/>Requiere Tu merced;<br/>En nada se puede gloriar<br/>Mas que en Tu propio ser.<br/>',NULL,188434,4);
INSERT INTO stanza VALUES('S19','4','Tú sabiamente por la cruz<br/>Lograste redención;<br/>Para que en nuestro espíritu<br/>Estés como porción.<br/>',NULL,188435,5);
INSERT INTO stanza VALUES('S19','5','Tu gran sabiduría en<br/>Los cielos hoy se ve;<br/>La iglesia a toda potestad<br/>La da a conocer.<br/>',NULL,188436,6);
INSERT INTO stanza VALUES('S19','6','Alabaremos tal merced<br/>En la Santa Ciudad;<br/>Por Tu sabiduría fiel<br/>Se te conocerá.<br/>',NULL,188437,7);
INSERT INTO stanza VALUES('S20','1','Tu gran saber y gracia, oh Dios,<br/>Centrado_en Cristo está;<br/>Y nos ha sido hecho Él<br/>Sabiduria real.<br/>Y nos ha sido hecho Él<br/>Sabiduria real.<br/>',NULL,188438,1);
INSERT INTO stanza VALUES('S20','2','Todo Tu plan en Cristo está;<br/>Tu gracia nos da El,<br/>//Sabiduría y santidad,<br/>Para Tu gloria ser.//<br/>',NULL,188439,2);
INSERT INTO stanza VALUES('S20','3','En Cristo, nuestra rectitud,<br/>Dios nos justificó;<br/>//En Cristo, nuestra santidad<br/>Nos santifica Dios.//<br/>',NULL,188440,3);
INSERT INTO stanza VALUES('S20','4','Es nuestra redención también,<br/>Conforme_a Tu intención;<br/>//Perfectos hombres nos hará,<br/>La nueva creación.//<br/>',NULL,188441,4);
INSERT INTO stanza VALUES('S20','5','El en Tu_economía,_oh Dios,<br/>Sabiduría es;<br/>//Te alabamos hoy por El,<br/>Glorificándote.//<br/>',NULL,188442,5);
INSERT INTO stanza VALUES('S20','6','Se ve sabiduría_en Él,<br/>Inescrutable es!<br/>//Mas por nosotros se hallará<br/>Más rica cada vez.//<br/>',NULL,188443,6);
INSERT INTO stanza VALUES('S21','1','Nos otorgaste, Padre, Tu merced,<br/>Por Tu favor;<br/>De pecadores, Tu lograste_hacer<br/>Hijos de_amor.<br/>Vasos de_honor Tú nos hiciste, oh Dios;<br/>Vasos de honra que te_expresan hoy.<br/>',NULL,188444,1);
INSERT INTO stanza VALUES('S21','2','Misericordia hoy deseas ver,<br/>Dijiste Tú;<br/>Por ella, Tu favor, nos haces ser<br/>Hijos de luz.<br/>No es de_aquel que puede correr bien,<br/>Sino de Dios que muestra Su merced.<br/>',NULL,188445,2);
INSERT INTO stanza VALUES('S21','3','Padre, Tu amor, Tu gracia y piedad<br/>Hoy nuestros son;<br/>Y cara_a cara nos han de guardar<br/>En comunión.<br/>Por siempre_a Ti daremos todo honor<br/>Por Tu misericordia_y gran favor.<br/>',NULL,188446,3);
INSERT INTO stanza VALUES('S22','1','Dios, por Tu misericordia<br/>Te alabamos sin cesar.<br/>En flaquezas y fracasos<br/>Su grandeza abunda más.<br/>¡Te adoramos! ¡Te adoramos!<br/>Qué misericordia das!<br/>Qué misericordia das!<br/>',NULL,188447,1);
INSERT INTO stanza VALUES('S22','2','¡Oh, qué gran misericordia!<br/>¡Tan extensa y tan capaz!<br/>Aunque somos pecadores,<br/>Nos alcanza y guardará.<br/>De_esta gran misericordia<br/>//¿Separarnos quién podrá?//<br/>',NULL,188448,2);
INSERT INTO stanza VALUES('S22','3','Por Tu fiel misericordia<br/>Admirable y rico don!<br/>En Tu redención nos diste<br/>La merced de Tu perdón.<br/>Sin su apoyo, sin su apoyo,<br/>//¿Cómo ganar Tu favor?//<br/>',NULL,188449,3);
INSERT INTO stanza VALUES('S22','4','Tan inspiradora y dulce<br/>Tu misericordia es!<br/>Tan paciente y tan benigna<br/>Nos provee en escasez.<br/>¡La apreciamos! ¡La apreciamos!<br/>//Cuán incomparable es!//<br/>',NULL,188450,4);
INSERT INTO stanza VALUES('S22','5','Padre, Tu misericordia<br/>Nueva y fresca siempre es.<br/>Nos rocía cada día<br/>Refrescando a la vez.<br/>¡La probamos! ¡La probamos!<br/>//¡Tan lozana_a nuestro ser!//<br/>',NULL,188451,5);
INSERT INTO stanza VALUES('S22','6','¡No cesamos de alabarte<br/>Por Tu gracia y Tu favor!<br/>Pues por Tu misericordia<br/>Nos preservas en Tu amor.<br/>¡Qué confianza! ¡Qué confianza!<br/>//Tu misericordia da.//<br/>',NULL,188452,6);
INSERT INTO stanza VALUES('S23','1','Venid, cantemos en unión:<br/>¡Nuestro Dios es amor!<br/>La tierra y cielo den loor:<br/>¡Nuestro Dios es amor!<br/>Toda_alma libre del pecar,<br/>Con gozo por Jesús cantad,<br/>Y con nosotros alabad:<br/>Nuestro Dios es amor.<br/>',NULL,188453,1);
INSERT INTO stanza VALUES('S23','2','Feliz porción aquí da Dios!<br/>¡Nuestro Dios es amor!<br/>Son Sus promesas bendición:<br/>Nuestro Dios es amor!<br/>Sol, fuerza, fe, ayuda, hogar,<br/>Escudo es y mucho más,<br/>Hasta el final siempre estará:<br/>¡Nuestro Dios es amor!<br/>',NULL,188454,2);
INSERT INTO stanza VALUES('S23','3','En gloria hemos de_entonar:<br/>¡Nuestro Dios es amor!<br/>Sublime himno hay que cantar:<br/>Nuestro Dios es amor!<br/>Concierto_eterno se oirá,<br/>Junto_a la hueste celestial,<br/>Nuestra canción aún será:<br/>¡Nuestro Dios es amor!<br/>',NULL,188455,3);
INSERT INTO stanza VALUES('S24','1','¡Oh, amor de Dios! Tu inmensidad<br/>No se podrá jamás contar;<br/>Traspasa el orbe celestial<br/>Y alcanza hasta el hondo mar.<br/>Al fracasar el primer par<br/>Su Hijo Dios prometió;<br/>Aquel que erró lo perdonó,<br/>Su amor lo reconcilió.<br/>',NULL,188456,1);
INSERT INTO stanza VALUES('S24','chorus','¡Oh amor de Dios! ¡Qué inmenso es!<br/>Qué puro y rico en verdad!<br/>Los santos cantarán de él<br/>Por toda la eternidad.<br/>',NULL,188457,2);
INSERT INTO stanza VALUES('S24','2','Cuando el tiempo quede atrás<br/>Con todo imperio mundanal,<br/>Y caiga todo trono acá<br/>Y llegue el reino celestial;<br/>El gran amor del Redentor<br/>Aún tan fuerte estará,<br/>Y la canción de salvación<br/>Su pueblo allí cantará.<br/>',NULL,188458,3);
INSERT INTO stanza VALUES('S24','3','Si fuera tinta todo el mar,<br/>Y todo el cielo un gran papel,<br/>Y cada hombre un escritor,<br/>Y cada hoja un pincel,<br/>Al intentar contar Su amor<br/>Se vaciaría el mar;<br/>Y ni los cielos con su anchor<br/>Podría el rollo abarcar.<br/>',NULL,188459,4);
INSERT INTO stanza VALUES('S24','note','**Nota: Registrada 1917. Renovada 1945 por Nazarene Publishing House. Usada con permiso.**<br/>',NULL,188460,5);
INSERT INTO stanza VALUES('S25','1','¿Qué fue, bendito Dios,<br/>Lo que a Ti te  llevó,<br/>A dar a Tu‿Hijo así,<br/>Por todo pecador?<br/>Fue por Tu ilimitado amor,<br/>Fue por Tu ilimitado amor,<br/>Por un desecho pecador.<br/>',NULL,188461,1);
INSERT INTO stanza VALUES('S25','2','¿Por qué Tu Hijo, oh Dios,<br/>Tu trono abandonó,<br/>Su sangre derramó,<br/>Y en una cruz murió?<br/>Fue por Su ilimitado amor,<br/>Fue por Su ilimitado amor,<br/>Que por nosotros El murió.<br/>',NULL,188462,2);
INSERT INTO stanza VALUES('S25','3','¿Qué te movió a verter<br/>Tu Espíritu, oh Dios,<br/>En nuestro corazón,<br/>Con tal celeste don?<br/>Fue ese ilimitado amor,<br/>Fue ese ilimitado amor,<br/>El que Tu Espíritu impartió.<br/>',NULL,188463,3);
INSERT INTO stanza VALUES('S25','4','¡Oh, qué deuda de amor<br/>Tu gracia nos legó!<br/>Rebosa el corazón<br/>Con eternal loor.<br/>Que te alabemos, nuestro Dios,<br/>Que te alabemos, nuestro Dios,<br/>Por tal ilimitado amor.<br/>',NULL,188464,4);
INSERT INTO stanza VALUES('S26','1','¡Qué amor nos concediste Tú!<br/>¡Mil gracias damos hoy!<br/>Por lo que eres, Padre Dios,<br/>Ten nuestra adoración.<br/>',NULL,188465,1);
INSERT INTO stanza VALUES('S26','2','Nos revelaste Tu intención<br/>Y eterna voluntad;<br/>En el Hijo viniste así,<br/>Para cumplir Tu plan.<br/>',NULL,188466,2);
INSERT INTO stanza VALUES('S26','3','Al Hijo amado diste Tú;<br/>Vino en amor, murió,<br/>Nos hizo hijos por Su cruz,<br/>Herederos de Dios.<br/>',NULL,188467,3);
INSERT INTO stanza VALUES('S26','4','Por Él Tu vida nuestra es,<br/>Oh, Padre celestial;<br/>Tu mismo ser nos impartió,<br/>Tu esencia divinal.<br/>',NULL,188468,4);
INSERT INTO stanza VALUES('S26','5','Tu Espíritu al nuestro entró,<br/>Para "Abba" clamar;<br/>Nos engendró y nos selló,<br/>Y nos transformará.<br/>',NULL,188469,5);
INSERT INTO stanza VALUES('S26','6','A Tu Hijo nos conformarás,<br/>Según Tu eterno plan;<br/>A Su imagen nos harás<br/>Para en Tu gloria entrar.<br/>',NULL,188470,6);
INSERT INTO stanza VALUES('S26','7','Durante la transformación,<br/>Guiándonos estás,<br/>De gloria en gloria para así,<br/>Tu obra consumar.<br/>',NULL,188471,7);
INSERT INTO stanza VALUES('S26','8','Por tal amor, oh Padre Dios,<br/>¡Mil gracias damos hoy!<br/>Con gratitud de corazón,<br/>A Ti damos loor.<br/>',NULL,188472,8);
INSERT INTO stanza VALUES('S27','1','Postrados, Padre, en Tu luz,<br/>Maravillados por Tu amor,<br/>Oh, ¿qué_es el hombre para que<br/>Le brindes tal gracia y favor?<br/>',NULL,188473,1);
INSERT INTO stanza VALUES('S27','2','Damos loor por Tu intención,<br/>El hombre es Tu imagen fiel,<br/>Y por Tu vida eterna en él<br/>Puede expresar Tu mismo ser.<br/>',NULL,188474,2);
INSERT INTO stanza VALUES('S27','3','Tu misma imagen lleva él,<br/>Le diste Tu autoridad;<br/>Eres la vida para que<br/>El hombre en ella pueda andar.<br/>',NULL,188475,3);
INSERT INTO stanza VALUES('S27','4','Deseas en el hombre entrar<br/>Para mezclarte con su ser;<br/>Al transformarle obtendrás<br/>Tu digna habitación en él.<br/>',NULL,188476,4);
INSERT INTO stanza VALUES('S27','5','Aunque ese hombre sí cayó,<br/>No abandonaste Tu intención;<br/>Lo redimiste para Ti<br/>Probando así Tu gran amor.<br/>',NULL,188477,5);
INSERT INTO stanza VALUES('S27','6','Te revelaste en Cristo Tú,<br/>Por muerte y resurrección;<br/>Eres Espíritu que_entró<br/>Al hombre y vida le_infundió.<br/>',NULL,188478,6);
INSERT INTO stanza VALUES('S27','7','Hoy Tu Santísimo Lugar<br/>En nuestro espíritu está.<br/>El trono de la gracia allí<br/>En oración tocamos ya.<br/>',NULL,188479,7);
INSERT INTO stanza VALUES('S27','8','De ese trono un caudal<br/>De gracia fluye sin cesar;<br/>Por ella nos transformarás<br/>Hasta Tu casa edificar.<br/>',NULL,188480,8);
INSERT INTO stanza VALUES('S27','9','Al recibir Tu gracia hoy,<br/>¡Gratuito don al corazón!<br/>Padre, en nuestro espíritu<br/>Gracias te damos por Tu amor.<br/>',NULL,188481,9);
INSERT INTO stanza VALUES('S28','1','Padre, Tú nos escogiste<br/>Antes de la creación;<br/>A Tu Hijo nos atrae<br/>Tu amor conmovedor,<br/>Y nos guarda, y nos guarda<br/>Firmemente‿en el Señor,<br/>Firmemente‿en el Señor.<br/>',NULL,188482,1);
INSERT INTO stanza VALUES('S28','2','Aunque‿el mundo es cambiante,<br/>Nuestro Dios no cambiará;<br/>Su misericordia‿y pacto<br/>No se pueden alterar.<br/>Y Sus hijos, y Sus hijos<br/>Siempre lo han de‿alabar,<br/>Siempre lo han de‿alabar.<br/>',NULL,188483,2);
INSERT INTO stanza VALUES('S28','3','Mi historia‿y mi jactancia<br/>Es la compasión de Dios;<br/>Siempre‿abunda, nunca falla,<br/>Me dirige‿a donde voy;<br/>Dios nos ama, Dios nos ama,<br/>¡Su‿Unigénito nos dio!<br/>¡Su‿Unigénito nos dio!<br/>',NULL,188484,3);
INSERT INTO stanza VALUES('S28','4','Padre‿amado, te‿alabamos<br/>Por Tu‿inmensurable‿amor;<br/>Cantaremos para siempre<br/>Con el Hijo de Tu‿amor.<br/>Dando gloria, dando gloria<br/>Al Cordero y a Dios,<br/>Al Cordero y a Dios.<br/>',NULL,188485,4);
INSERT INTO stanza VALUES('S29','1','Padre, en amor nos viste<br/>Antes de la creación;<br/>A Jesús nos ha acercado<br/>Tal amor constreñidor,<br/>Y nos guarda, y nos guarda<br/>Hoy y por siempre jamás,<br/>Hoy y por siempre jamás.<br/>',NULL,188486,1);
INSERT INTO stanza VALUES('S29','2','Ese_amor que nos envuelve,<br/>Nos otorga si caudal;<br/>Y su fuerza nos mantiene<br/>En reposo celestial.<br/>Dios y Padre, Dios y Padre,<br/>Fluye a Ti la_adoración,<br/>Fluye a Ti la_adoración.<br/>',NULL,188487,2);
INSERT INTO stanza VALUES('S29','3','¡Dios de amor, nuestra_alma adora!<br/>Pues Tu gracia se verá,<br/>Hasta_hechar nuestras coronas<br/>Y Tu nombre en gloria_honrar.<br/>Alabanzas, alabanzas!<br/>A Dios y al Cordero dad!<br/>A Dios y al Cordero dad!<br/>',NULL,188488,3);
INSERT INTO stanza VALUES('S30','1','Oh Padre, te adoramos,<br/>Tus hijos en verdad,<br/>Los que por gracia pueden<br/>Hoy contemplar Tu faz;<br/>Marcados para gloria<br/>Desde la eternidad,<br/>Con Cristo_el buen Amado<br/>Tu enfoque eternal.<br/>',NULL,188489,1);
INSERT INTO stanza VALUES('S30','2','¿Quién más, sino Tú, Padre,<br/>En Tu Hijo puede dar<br/>Tu Espíritu divino:<br/>La bendición filial?<br/>Nos cuentas como propios,<br/>Y pronto nos verás<br/>Con Cristo en plena gloria<br/>Delante de Tu faz.<br/>',NULL,188490,2);
INSERT INTO stanza VALUES('S31','1','A Dios sea la gloria,<br/>Grandezas obró,<br/>Amó tanto al mundo<br/>Que_a Su Hijo nos dio;<br/>Rindió   El Su vida,<br/>Ganó redención,<br/>La puerta a la vida<br/>A todos abrió.<br/>',NULL,188491,1);
INSERT INTO stanza VALUES('S31','chorus','¡Alabad al Señor!<br/>¡Tierra, oíd Su voz!<br/>¡Alabad al Señor!<br/>¡Alegraos hoy con Dios!<br/>¡Lleguemos al Padre<br/>Por Su Hijo Jesús,<br/>Y dadle la gloria,<br/>Por Su obra en  la cruz!<br/>',NULL,188492,2);
INSERT INTO stanza VALUES('S31','2','Oh, qué redención: con<br/>Su sangre compró<br/>A cada creyente.<br/>Promesa de Dios!<br/>Si en Cristo confía el<br/>Más vil pecador,<br/>Perdón en el acto<br/>Le otorgó el Señor.<br/>',NULL,188493,3);
INSERT INTO stanza VALUES('S31','3','Oh, qué maravillas,<br/>Las obras de Dios!<br/>Hay gran regocijo<br/>Por Su‿Hijo Jesús;<br/>Más puro, más bello,<br/>Más grande será,<br/>El éxtasis cuando<br/>Veamos Su faz.<br/>',NULL,188494,4);
INSERT INTO stanza VALUES('S32','1','¡Te loamos, oh Dios!<br/>Por Tu Hijo de amor,<br/>Quien murió por salvarnos<br/>Y al trono ascendió.<br/>',NULL,188495,1);
INSERT INTO stanza VALUES('S32','chorus','¡Aleluya! ¡Te alabamos!<br/>¡Cuán grande es Tu amor!<br/>¡Aleluya! ¡Te adoramos!<br/>Con gloria y honor.<br/>',NULL,188496,2);
INSERT INTO stanza VALUES('S32','2','Te loamos, oh Dios!<br/>Por Tu Espíritu,<br/>Que anuló nuestra noche<br/>Trayéndonos luz.<br/>',NULL,188497,3);
INSERT INTO stanza VALUES('S32','3','La gloria y honor<br/>Sea al Padre de amor,<br/>Que ofreciendo Su Hijo<br/>Nos dio redención.<br/>',NULL,188498,4);
INSERT INTO stanza VALUES('S32','4','Te damos loor,<br/>Pues nos llena Tu amor<br/>Con el fuego divino<br/>En el corazón.<br/>',NULL,188499,5);
INSERT INTO stanza VALUES('S33','1','No nos cansa el cantar la canción eternal:<br/>Gloria a Dios, aleluya!<br/>Con espíritu ferviente siempre alabad:<br/>¡Gloria a Dios, aleluya!<br/>',NULL,188500,1);
INSERT INTO stanza VALUES('S33','chorus','Oh, los hijos del Señor<br/>Cantarán bella canción;<br/>A la gloria los guiará<br/>Por Su gracia el Señor;<br/>Luego frente a nuestro Rey<br/>Todos ellos estarán.<br/>¡Gloria a Dios, aleluya!<br/>',NULL,188501,2);
INSERT INTO stanza VALUES('S33','2','En un éxtasis envuelto de amor redentor:<br/>¡Gloria a Dios, aleluya!<br/>Procuramos por Su gracia darle todo honor:<br/>¡Gloria a Dios, aleluya!<br/>',NULL,188502,3);
INSERT INTO stanza VALUES('S33','3','Proseguimos a la gloria como ha dicho el Rey,<br/>¡Gloria a Dios, aleluya!<br/>Su belleza esplendorosa pronto se ha de ver.<br/>¡Gloria a Dios, aleluya!<br/>',NULL,188503,4);
INSERT INTO stanza VALUES('S33','4','Luego, de Su inmensa gracia en feliz canción:<br/>¡Gloria a Dios, aleluya!<br/>Cantaremos con gran multitud al Salvador:<br/>¡Gloria a Dios, aleluya!<br/>',NULL,188504,5);
INSERT INTO stanza VALUES('S34','1','Por Ti, Dios, invitados<br/>A Tu_Hijo contemplar;<br/>En Él Tú te complaces:<br/>Cumplió Tu voluntad.<br/>Al darnos libremente<br/>Tu gran tesoro,_oh Dios,<br/>Tu puro amor se aprecia,<br/>Tu plan de salvación.<br/>',NULL,188505,1);
INSERT INTO stanza VALUES('S34','2','¡Oh Dios de gracia: Padre!<br/>Nuestra esperanza es<br/>Jesús, Tu Hijo_amado,<br/>¡Precioso nombre fiel!<br/>El nombre que te_agrada<br/>Y que_amas escuchar,<br/>De culpas y temores<br/>Nos dio la libertad.<br/>',NULL,188506,2);
INSERT INTO stanza VALUES('S34','3','El pecador temía<br/>Juzgado ser por Dios;<br/>Mas un completo pago<br/>La deuda liquidó.<br/>Nadie podía salvarnos<br/>Ni el alma liberar;<br/>Más Cristo, por Su muerte,<br/>Nos pudo rescatar.<br/>',NULL,188507,3);
INSERT INTO stanza VALUES('S34','4','Para los que creemos<br/>No guarda ira Dios;<br/>Todo temor se_aleja<br/>Al recibir Su_amor.<br/>Sus pródigos Él besa;<br/>Los viste con primor;<br/>Y Su amor perfecto<br/>Expulsa el temor.<br/>',NULL,188508,4);
INSERT INTO stanza VALUES('S35','1','¡Abba, Padre! Congregados<br/>En el nombre de Jesús;<br/>Bendiciones disfrutamos<br/>Por ser hijos hoy de luz.<br/>Ya de culpa libertados<br/>Por la sangre del Señor,<br/>"Abba, Padre" invocamos<br/>Por Tu Espíritu en amor.<br/>',NULL,188509,1);
INSERT INTO stanza VALUES('S35','2','Pródigos un tiempo fuimos,<br/>Alejados de Tu hogar;<br/>Mas Tu gracia recibimos<br/>Rescatándonos del mal.<br/>Hoy de salvación vestidos<br/>En la mesa de Tu amor,<br/>Disfrutamos y disfrutas<br/>Las riquezas del Señor.<br/>',NULL,188510,2);
INSERT INTO stanza VALUES('S35','3','Como al pródigo nos diste<br/>Bienvenida y perdón.<br/>Nos "besaste" y el becerro<br/>Tú mataste por amor.<br/>Tú dijiste "Es necesario<br/>Hacer fiesta y disfrutar;<br/>He hallado al perdido;<br/>Muerto estaba y vive ya".<br/>',NULL,188511,3);
INSERT INTO stanza VALUES('S35','4','"Abba, Padre", te adoramos,<br/>Con la hueste celestial,<br/>Quien se asombra de nosotros<br/>Por Tu obra divinal.<br/>Cuando_estén Tus hijos todos<br/>Frente al trono celestial,<br/>Ensalzando allí Tu nombre<br/>"Abba, Padre", clamarán.<br/>',NULL,188512,4);
INSERT INTO stanza VALUES('S36','1','¡Abba, Padre! Te_exaltamos;<br/>Sea_a Ti la_adoración.<br/>Sólo los que son Tus hijos<br/>Claman "Abba" en Tu_honor.<br/>Nuestra herencia tan preciosa<br/>Por la sangre_es nuestro don;<br/>Tu Espíritu_en el nuestro<br/>Testifica: "Hijos sois".<br/>',NULL,188513,1);
INSERT INTO stanza VALUES('S36','2','Por Tu plan hoy existimos;<br/>Fue conforme_a Tu_elección.<br/>Tú nos escogiste en Cristo<br/>Antes de la creación.<br/>Padre, fue Tu amor precioso<br/>Que a Tu seno nos llevó,<br/>Cuando_al Hijo amado diste<br/>Estos hijos de Tu amor.<br/>',NULL,188514,2);
INSERT INTO stanza VALUES('S36','3','Aunque en Adán caímos,<br/>Alejándonos de Dios,<br/>Tu consejo_eterno trajo<br/>Por la sangre redención.<br/>Hoy más cerca_a Ti estamos;<br/>¡Oh qué grande compasión!<br/>Cristo y Sus redimidos<br/>Por Tu gracia uno son.<br/>',NULL,188515,3);
INSERT INTO stanza VALUES('S36','4','Pese_al cambio de los tiempos,<br/>Llanto, pena y dolor,<br/>Nunca cambiará Tu afecto;<br/>Salva Tu divino_amor.<br/>Pronto, en torno_al trono_eterno,<br/>Los que la sangre compró<br/>Cantarán sus alabanzas<br/>Por Tu_excelsa salvación.<br/>',NULL,188516,4);
INSERT INTO stanza VALUES('S37','1','Te bendecimos, Padre Dios,<br/>Tus hijos en verdad,<br/>Con jubiloso corazón<br/>Al contemplar Tu faz.<br/>',NULL,188517,1);
INSERT INTO stanza VALUES('S37','2','Confianza dulce Tu nos das,<br/>Inspira a_adorar;<br/>Elevas nuestro corazón<br/>Al orbe donde_estás.<br/>',NULL,188518,2);
INSERT INTO stanza VALUES('S37','3','Tu rica gracia se verá<br/>Por siglos que vendrán,<br/>En los que han de compartir<br/>Con Tu Hijo Su lugar.<br/>',NULL,188519,3);
INSERT INTO stanza VALUES('S37','4','Aunque ausente Él está,<br/>Seguimos; firme_en pos<br/>De_Aquel que viene_a rescatar<br/>De toda muerte atróz.<br/>',NULL,188520,4);
INSERT INTO stanza VALUES('S37','5','Hay gozo_en Ti; Tu plenitud<br/>Será nuestra porción,<br/>Al disfrutar con Tu Hijo fiel<br/>Tu rica provisión.<br/>',NULL,188521,5);
INSERT INTO stanza VALUES('S37','6','Oh Padre Santo, guárdanos<br/>En Tu nombre_y amor,<br/>Para cumplir Tu voluntad,<br/>Más sin sentir temor.<br/>',NULL,188522,6);
INSERT INTO stanza VALUES('S38','1','Te bendecimos, Padre,<br/>Con gozo celestial,<br/>Pues con Tu Hijo Amado<br/>Está nuestro lugar.<br/>El vive como un Hombre<br/>Delante de Tu faz,<br/>En gloria inmarcesible,<br/>En Tu amor eternal.<br/>',NULL,188523,1);
INSERT INTO stanza VALUES('S38','2','Su Padre y nuestro Padre,<br/>Su Dios y nuestro Dios;<br/>Él es Tu buen Amado<br/>Y Tu satisfacción.<br/>Con gozo El nos lleva<br/>A compartir Tu amor,<br/>El brillo de Tu rostro,<br/>Tu gracia y Tu favor.<br/>',NULL,188524,2);
INSERT INTO stanza VALUES('S38','3','Tu amor que nos envuelve<br/>Jamás se enfriará;<br/>En Él Tu amor se centra,<br/>Y Tu favor nos das.<br/>En Él Tu amor y gloria<br/>Encuentran su lugar,<br/>Y todos Sus hermanos,<br/>Tus hijos, dulce hogar.<br/>',NULL,188525,3);
INSERT INTO stanza VALUES('S39','1','Padre, nos guía Tu Hijo_a_alabar<br/>Cuando_el convite ya se terminó;<br/>Dulce_alabanza El dirige a Ti,<br/>Y_en Su alabanza somos uno_aquí.<br/>',NULL,188526,1);
INSERT INTO stanza VALUES('S39','2','Padre, Tú eres toda la bondad<br/>Que disfrutamos. ¡No‿hay amor igual!<br/>Te adoramos, pues haces saber<br/>La‿inescrutable vida de Tu Ser.<br/>',NULL,188527,2);
INSERT INTO stanza VALUES('S39','3','Padre‿en Tu amor el nuestro crece‿así,<br/>Trasciende todo lazo terrenal;<br/>Tu‿amor con fuerza lleva‿el corazón<br/>A Tu presencia en consolación.<br/>',NULL,188528,3);
INSERT INTO stanza VALUES('S39','4','Padre, en unión con Tu Hijo amado hoy,<br/>Te alabamos en Tu santo amor;<br/>Con alegría disfrutamos más<br/>Tu nombre como hijos al clamar.<br/>',NULL,188529,4);
INSERT INTO stanza VALUES('S40','1','A Ti venimos, nuestro Padre Dios,<br/>Tus hijos hoy,<br/>Justos en santa libertad y amor,<br/>¡Qué bendición!<br/>Bello_es pensar que muchos han de ser<br/>Tal como Cristo, Tu_eternal placer.<br/>',NULL,188530,1);
INSERT INTO stanza VALUES('S40','2','Él, Tu deleite, por la gracia es<br/>Nuestra porción;<br/>Siendo el objeto de Tu_eterno_amor<br/>Y corazón.<br/>Su gloria_en Tu presencia hoy se ve<br/>En agradable_amor, allí con Él.<br/>',NULL,188531,2);
INSERT INTO stanza VALUES('S40','3','Disfruta_el Hijo al cantar loor,<br/>Te_alaba hoy.<br/>Tus hijos unen mente_y corazón<br/>A una voz<br/>Para_adorarte, nuestro Padre Dios,<br/>Por la economía de Tu amor.<br/>',NULL,188532,3);
INSERT INTO stanza VALUES('S41','1','Padre, a Ti un cántico alzamos;<br/>En comunión;<br/>En Tu presencia todos te alabamos,<br/>¡Qué bendición!<br/>Estar en Ti, ¡qué gracia sin igual!<br/>Que con Tu amado Hijo estamos al  par.<br/>',NULL,188533,1);
INSERT INTO stanza VALUES('S41','2','Llena de gozó_esa radiante_escena<br/>Donde se ve<br/>Tu_amor, oh Dios y Padre, que gozamos<br/>Sólo en Él.<br/>Reposa así Tu santa calma aquí,<br/>Cantamos con Aquel que te_ama a Ti.<br/>',NULL,188534,2);
INSERT INTO stanza VALUES('S41','3','Levanta alabanza el Hijo al Padre,<br/>¡Qué dulce es!<br/>A Ti nos lleva Él para_adorarte,<br/>Y estar con Él;<br/>Fue Tu deseo antes de la creación,<br/>Con Tu amado Hijo darnos porción.<br/>',NULL,188535,3);
INSERT INTO stanza VALUES('S42','1','Tu nombre adoramos, Padre Dios,<br/>Tu_amor en Cristo se nos reveló.<br/>Tu voluntad con gozo_Él realizó,<br/>Cuando_el oprobio en la cruz sufrió.<br/>',NULL,188536,1);
INSERT INTO stanza VALUES('S42','2','Aquí Él canta alabanza a Tí;<br/>Al escucharlo, bulle nuestro ser.<br/>Junto_a Su voz alzamos hoy loor<br/>Con nuestro espíritu unido_a Él.<br/>',NULL,188537,2);
INSERT INTO stanza VALUES('S42','3','En Tu Hijo_amado fue Tu elección<br/>Para que_estemos ante Ti_en amor,<br/>Predestinándonos para estar<br/>Donde Tu gracia_abunda_y Tu favor.<br/>',NULL,188538,3);
INSERT INTO stanza VALUES('S42','4','Tus hijos llenas con Tu_Espíritu;<br/>Cristo_en nosotros es nuestra porción;<br/>Sus rasgos en nosotros hoy están,<br/>Para Tu gozo y deleite son.<br/>',NULL,188539,4);
INSERT INTO stanza VALUES('S43','1','Oh Padre Dios, venimos a_alabar,<br/>Ninguno hay tan digno como Tú.<br/>Buscando_adoradores Tú estás,<br/>Que_adoren en verdad y_espíritu.<br/>',NULL,188540,1);
INSERT INTO stanza VALUES('S43','2','Todos los mundos Tú creaste aquí<br/>Por Cristo el Hijo y Su gran poder;<br/>Y hoy venimos en el Hijo a Ti:<br/>¡Causa de_adoración tal hecho es!<br/>',NULL,188541,2);
INSERT INTO stanza VALUES('S43','3','Él nos dirige_en alabanza_a Ti,<br/>¡En la_asamblea, oh qué bendición!<br/>¡Cómo Él se goza, pues nos tiene_así,<br/>Cerca de Él, en libertad y_amor!<br/>',NULL,188542,3);
INSERT INTO stanza VALUES('S43','4','¡Con Él unidos, entonamos hoy!<br/>Hallas, oh Dios, satisfacción total.<br/>Nuestra alabanza, el Hijo inició,<br/>Y_en la_alabanza siempre morarás.<br/>',NULL,188543,4);
INSERT INTO stanza VALUES('S44','1','Tú la Fuente eres, Padre Dios,<br/>De la vida que_expresamos,<br/>Que_en Tu nombre disfrutamos;<br/>Tú la Fuente eres, Padre Dios,<br/>',NULL,188544,1);
INSERT INTO stanza VALUES('S44','chorus','En Tu vida, en Tu vida,<br/>En Tu vida_es nuestra unidad.<br/>En Tu vida, en Tu vida,<br/>En Tu vida, Padre,_es la unidad.<br/>',NULL,188545,2);
INSERT INTO stanza VALUES('S44','2','Tu Palabra santa_es rico don,<br/>Nos satura con Tu esencia,<br/>Del mundo nos da_abstinencia;<br/>Tu Palabra, Padre, es rico don.<br/>',NULL,188546,3);
INSERT INTO stanza VALUES('S44','chorus','Tu Palabra, Tu Palabra,<br/>Es por ella nuestra unidad.<br/>Tu Palabra, Tu Palabra,<br/>Nos mantiene hoy en unidad.<br/>',NULL,188547,4);
INSERT INTO stanza VALUES('S44','3','¡Oh, la gloria del Triuno Dios!<br/>¡Sus benditos hijos somos!<br/>Y Su gloria aquí_expresamos;<br/>¡Oh, la gloria del Triuno Dios!<br/>',NULL,188548,5);
INSERT INTO stanza VALUES('S44','chorus','En Tu gloria, en Tu gloria,<br/>En Tu gloria es nuestra unidad.<br/>En Tu gloria, en Tu gloria,<br/>En Tu gloria se ve la unidad.<br/>',NULL,188549,6);
INSERT INTO stanza VALUES('S45','1','Eres la Palabra de Dios,<br/>El Hijo_amado_y fiel,<br/>La imagen santa del gran Dios,<br/>Por siempre_uno con Él.<br/>',NULL,188550,1);
INSERT INTO stanza VALUES('S45','2','Eres el mismo Dios y<br/>Su Corporificación;<br/>Manifestándole así<br/>Nos haces ver a Dios.<br/>',NULL,188551,2);
INSERT INTO stanza VALUES('S45','3','Eres el resplandor de Dios<br/>Que brilla en nuestro ser,<br/>Y Su substancia expresas Tú,<br/>La_infundes con poder.<br/>',NULL,188552,3);
INSERT INTO stanza VALUES('S45','4','En Ti Dios nuestra vida es,<br/>En Ti la luz es El;<br/>Y Su naturaleza en Ti<br/>Podemos poseer.<br/>',NULL,188553,4);
INSERT INTO stanza VALUES('S45','5','Subsiste en Ti gracia de Dios<br/>Para disfrute_y bien;<br/>Y Su verdad se encuentra en Ti,<br/>Su realidad también.<br/>',NULL,188554,5);
INSERT INTO stanza VALUES('S45','6','En Ti la plenitud de Dios<br/>De gracia en gracia das;<br/>En Ti nos mezclas hoy con Dios,<br/>Hasta la unión total.<br/>',NULL,188555,6);
INSERT INTO stanza VALUES('S45','7','Señor, Tú eres nuestro Dios,<br/>Y nuestro todo aquí;<br/>Tu nombre_amamos proclamar,<br/>Y_atesorarte_así.<br/>',NULL,188556,7);
INSERT INTO stanza VALUES('S46','1','Habita_en Ti, Señor Jesús,<br/>En forma corporal,<br/>La_imagen del viviente Dios<br/>Y toda la Deidad.<br/>',NULL,188557,1);
INSERT INTO stanza VALUES('S46','2','Palabra de Dios eres Tú<br/>Con vida divinal;<br/>En Ti Su gracia nuestra es,<br/>También Su realidad.<br/>',NULL,188558,2);
INSERT INTO stanza VALUES('S46','3','Eres el resplandor de Dios,<br/>El Hijo de Su amor;<br/>Y Su substancia divinal<br/>Habita_en Ti, Señor.<br/>',NULL,188559,3);
INSERT INTO stanza VALUES('S46','4','Tú, la corporificación<br/>De Dios y Su expresión;<br/>En Ti, Señor, nos muestra Dios<br/>Su manifestación.<br/>',NULL,188560,4);
INSERT INTO stanza VALUES('S46','5','Al disfrutar en Ti a Dios,<br/>Su vida y lo demás,<br/>Le damos gracias y loor,<br/>Y te_apreciamos más.<br/>',NULL,188561,5);
INSERT INTO stanza VALUES('S47','1','Palabra viva_eres, Señor,<br/>Desde la_eternidad;<br/>De Dios, la gloria_en plenitud<br/>Mostraste en Tu_andar.<br/>',NULL,188562,1);
INSERT INTO stanza VALUES('S47','chorus','Te alabamos, oh Señor,<br/>En Ti vemos a Dios.<br/>Su gloria y carácter Tú<br/>Nos muestras, oh Señor.<br/>',NULL,188563,2);
INSERT INTO stanza VALUES('S47','2','La gloria del viviente Dios,<br/>Sus rasgos y poder,<br/>Por medio de la creación<br/>Todo_hombre puede ver.<br/>',NULL,188564,3);
INSERT INTO stanza VALUES('S47','3','¡Qué rica Tu Palabra es!<br/>Da testimonio fiel<br/>De la realidad de Dios<br/>Que das a conocer.<br/>',NULL,188565,4);
INSERT INTO stanza VALUES('S47','4','Te encarnaste para_andar<br/>Como_hombre_aquí, Señor,<br/>Y Tu conducta nos mostró<br/>La expresión de Dios.<br/>',NULL,188566,5);
INSERT INTO stanza VALUES('S47','5','Palabra viva, eres luz<br/>Y nuestra vida; Tú<br/>Nos iluminas para ver<br/>Al Padre_en Su virtud.<br/>',NULL,188567,6);
INSERT INTO stanza VALUES('S47','6','El juicio del viviente Dios<br/>Tú ejecutarás;<br/>Esto_a la vez es la expresión<br/>Que_a Dios nos mostrará.<br/>',NULL,188568,7);
INSERT INTO stanza VALUES('S47','7','La expresión de Dios, Señor,<br/>Al hombre_hiciste ver;<br/>Él ya oculto no está,<br/>Lo diste_a conocer.<br/>',NULL,188569,8);
INSERT INTO stanza VALUES('S48','1','Hijo de Hombre, Tú, Señor,<br/>Esencia_humana te vistió;<br/>Fue virginal Tu concepción,<br/>Con carne_y sangre te formó.<br/>',NULL,188570,1);
INSERT INTO stanza VALUES('S48','2','Forma de siervo humilde Tú<br/>Llevaste en Tu caminar;<br/>Fue tan humano Tu vivir<br/>Y muy sufrido Tu andar.<br/>',NULL,188571,2);
INSERT INTO stanza VALUES('S48','3','Naciste en un pesebre Tú,<br/>Muy pobre fuiste en Tu niñez;<br/>Un carpintero sin honor;<br/>Que_en cruz de malhechor murió.<br/>',NULL,188572,3);
INSERT INTO stanza VALUES('S48','4','Venciste Tú la muerte atroz,<br/>Tu humanidad se conservó;<br/>Y como_un hombre divinal<br/>Entraste en gloria celestial.<br/>',NULL,188573,4);
INSERT INTO stanza VALUES('S48','5','Hoy en el trono riges Tú,<br/>Y como hombre_en gloria estás;<br/>Allí con Dios en plena luz<br/>Satisfacción total le das.<br/>',NULL,188574,5);
INSERT INTO stanza VALUES('S48','6','Lleno de gloria volverás,<br/>Y como un hombre te verán;<br/>El Rey de reyes con poder,<br/>Y divinal humanidad.<br/>',NULL,188575,6);
INSERT INTO stanza VALUES('S48','7','Serás el centro Tú, Señor,<br/>Del nuevo orden que vendrá;<br/>Por siempre con divinidad<br/>Viviendo en Tu humanidad.<br/>',NULL,188576,7);
INSERT INTO stanza VALUES('S49','1','Jesucristo, te adoramos,<br/>Tú, simiente de mujer;<br/>Engendrado de una virgen,<br/>Aún Tu nombre_humano es.<br/>La serpiente Tú heriste,<br/>Su cabeza_al aplastar,<br/>En la cruz así cumpliste<br/>De Dios el eterno plan.<br/>',NULL,188577,1);
INSERT INTO stanza VALUES('S49','chorus','Vemos en Tu gloria<br/>¡Tal belleza_humana!<br/>Tu esplendor manifestado<br/>En la humanidad.<br/>',NULL,188578,2);
INSERT INTO stanza VALUES('S49','2','Como hombre te encarnaste<br/>Carne y sangre al tomar,<br/>Vindicaste nuestra causa<br/>Destruyendo a Satanás.<br/>Fue Jesús el nombre dado,<br/>Te llamaron Emanuel;<br/>Salvador, precioso eres,<br/>Salvación a nuestro ser.<br/>',NULL,188579,3);
INSERT INTO stanza VALUES('S49','3','Eres el "segundo hombre"<br/>Eres el "postrer Adán;<br/>De la nueva creación eres<br/>La Cabeza celestial.<br/>Fue Tu vida y Tu conducta<br/>Como Hijo de Hombre fiel,<br/>Y_en el cielo aún como hombre<br/>Tal humanidad se ve.<br/>',NULL,188580,4);
INSERT INTO stanza VALUES('S49','4','En el tiempo señalado<br/>Otra vez vendrás, Jesús,<br/>Con la gloria del Dios Padre<br/>Visto como hombre aún.<br/>En el trono del gran juicio<br/>Hijo de Hombre Tú serás,<br/>Con naturaleza humana,<br/>Que por siempre Tú tendrás.<br/>',NULL,188581,5);
INSERT INTO stanza VALUES('S50','1','La vida de Cristo en la tierra fue,<br/>Según nos lo muestra_el salmo dieciséis,<br/>Valiosa_en Sus actos, gustos y_elección;<br/>Nos muestra al hombre morando con Dios.<br/>',NULL,188582,1);
INSERT INTO stanza VALUES('S50','2','"Oh guárdame, pues he confiado_en Ti, Dios";<br/>Él siempre en Dios Su refugio halló.<br/>"Eres mi Señor y mi único bien",<br/>Decía, hablando con Dios siempre Él.<br/>',NULL,188583,2);
INSERT INTO stanza VALUES('S50','3','"Los santos que_habitan en la tierra hoy",<br/>Para_Él son el pueblo de sumo valor.<br/>En ellos todo Su deleite está,<br/>En los evangelios se ve tal verdad.<br/>',NULL,188584,3);
INSERT INTO stanza VALUES('S50','4','"Jehová_es mi porción y mi copa también",<br/>En todo, del Padre dependía Él.<br/>"Bendito mi Dios, quien consejo me da",<br/>Negóse_y vivió por el Padre_y Su_hablar.<br/>',NULL,188585,4);
INSERT INTO stanza VALUES('S50','5','Con gozo en Su_espíritu_y Su corazón,<br/>Incluso_al morir, Él a Dios alabó.<br/>Su alma Dios no_abandonó al Seol<br/>Mas mora Su cuerpo en resurrección.<br/>',NULL,188586,5);
INSERT INTO stanza VALUES('S50','6','Dios lo levantó y Su gloria le dio,<br/>Y frente_a Su Dios pleno gozo_encontró.<br/>Sentado_a la diestra de Dios hoy está<br/>Gozando delicias que siempre fluirán.<br/>',NULL,188587,6);
INSERT INTO stanza VALUES('S51','1','Tu nombre amo yo,<br/>Señor Jesús;<br/>No hay otro como Tú,<br/>Señor Jesús.<br/>Mi todo debes ser;<br/>Sin Ti no tengo bien;<br/>Descansa_en Ti mi fe,<br/>Señor Jesús.<br/>',NULL,188588,1);
INSERT INTO stanza VALUES('S51','2','Como_Hijo de_Hombre, Tú,<br/>Señor Jesús;<br/>Moriste en la cruz,<br/>Señor Jesús.<br/>Más grande fue Tu_amor<br/>Que todo Tu dolor;<br/>Es sin comparación,<br/>Señor Jesús.<br/>',NULL,188589,2);
INSERT INTO stanza VALUES('S51','3','En Ti ya justo soy,<br/>Señor Jesús;<br/>Tú mi refugio hoy,<br/>Señor Jesús.<br/>¿A quién he de temer?<br/>¿Al duelo o padecer?<br/>En Ti yo confiaré,<br/>Señor Jesús.<br/>',NULL,188590,3);
INSERT INTO stanza VALUES('S51','4','Muy pronto Tú vendrás,<br/>Señor Jesús;<br/>Felices nos harás,<br/>Señor Jesús.<br/>Cuando contigo esté,<br/>Tu rostro yo veré,<br/>Y te reflejaré,<br/>Señor Jesús.<br/>',NULL,188591,4);
INSERT INTO stanza VALUES('S52','1','Cuán dulce el nombre de Jesús<br/>Al fiel en su dolor!<br/>Es bálsamo en su virtud,<br/>Que calma su temor.<br/>Que calma su temor.<br/>Que calma su temor.<br/>Es bálsamo en su virtud,<br/>Que calma su temor.<br/>',NULL,188592,1);
INSERT INTO stanza VALUES('S52','2','Puede al espíritu sanar<br/>Y al pecho confortar;<br/>Al alma hambrienta es maná,<br/>Y al fatigado paz.<br/>',NULL,188593,2);
INSERT INTO stanza VALUES('S52','3','Tu dulce nombre Roca es,<br/>Escudo y protección;<br/>Como un tesoro lleno de<br/>Tu gracia y bendición.<br/>',NULL,188594,3);
INSERT INTO stanza VALUES('S52','4','Jesús, Amigo, Salvador,<br/>Profeta, Rey, Señor,<br/>Camino, Vida, buen Pastor,<br/>Acepta mi loor.<br/>',NULL,188595,4);
INSERT INTO stanza VALUES('S52','5','Aunque es muy débil mi vigor,<br/>Y frió el corazón,<br/>Mas cuando te vea, Señor,<br/>Te alabaré mejor.<br/>',NULL,188596,5);
INSERT INTO stanza VALUES('S52','6','Hasta entonces se oirá<br/>De Tu indecible amor,<br/>Y por Tu nombre que triunfó<br/>Se te dará loor.<br/>',NULL,188597,6);
INSERT INTO stanza VALUES('S52','note','**Nota: Para cantar, se repite la última línea de cada estrofa dos veces, seguido de las dos últimas líneas de cada estrofa, como indicado en la estrofa #1.**<br/>',NULL,188598,7);
INSERT INTO stanza VALUES('S53','1','¡Cuán dulce el nombre de Jesús!<br/>Su música‿amo entonar,<br/>De gozo me hace desbordar,<br/>Jesús, precioso nombre!<br/>',NULL,188599,1);
INSERT INTO stanza VALUES('S53','chorus','¡Jesús! Nombre dulce es.<br/>¡Jesús! Cada día igual.<br/>¡Jesús! Santos proclamad:<br/>Es digno de‿alabanza.<br/>',NULL,188600,2);
INSERT INTO stanza VALUES('S53','2','Yo amo el nombre de Jesús,<br/>Conoce y lleva mi dolor,<br/>De mi_ansiedad quita el temor,<br/>¡Jesús, amado nombre!<br/>',NULL,188601,3);
INSERT INTO stanza VALUES('S53','3','Amo_escuchar el nombre aquel,<br/>Que siempre_alegra el corazón,<br/>Y seca_el llanto su canción,<br/>¡Oh, exaltad Su nombre!<br/>',NULL,188602,4);
INSERT INTO stanza VALUES('S53','4','Nadie podrá jamás decir<br/>Cuán dulce el nombre_es para mí;<br/>Oh, cuánto hay que bendecir,<br/>¡Jesús, Tu dulce nombre!<br/>',NULL,188603,5);
INSERT INTO stanza VALUES('S54','1','¡Oh Jesús, glorioso nombre!<br/>Admirable Salvador,<br/>Tu naciste de_una virgen;<br/>Hijo de_Hombre eres hoy.<br/>Eres Tú Jehová quien salva;<br/>Del pecado libras Tú.<br/>Cuando_a Ti te recibimos,<br/>Nos impartes vida_y luz.<br/>',NULL,188604,1);
INSERT INTO stanza VALUES('S54','2','Es también Tu nombre "Cristo",<br/>Has venido a ministrar;<br/>El Ungido de Dios eres,<br/>Desde la eternidad.<br/>El Mesías de Dios eres;<br/>En amor Él te_eligió<br/>Para exhibir Tu gloria<br/>Y cumplir el plan de Dios.<br/>',NULL,188605,2);
INSERT INTO stanza VALUES('S54','3','Por ser Tú "Dios con nosotros"<br/>Es Tu nombre "Emanuel";<br/>Dios en gracia_así mezclado<br/>Con la humanidad se ve.<br/>Se mostró Dios en la carne<br/>Lleno de gracia y verdad;<br/>Vemos hoy en Ti Su gloria,<br/>Y por fe lo haces real.<br/>',NULL,188606,3);
INSERT INTO stanza VALUES('S54','4','¡Cuán preciados son Tus nombres!<br/>¡Cuánto ellos dejan ver!<br/>Su valor y su dulzura,<br/>¡Qué deleite_a nuestro ser!<br/>Te_adoramos, te honramos,<br/>Oh precioso Salvador;<br/>Emanuel, te alabamos;<br/>Te_exaltamos con loor.<br/>',NULL,188607,4);
INSERT INTO stanza VALUES('S55','1','Un nombre hay el cual amo oír,<br/>Y canto de su valor;<br/>Lo más precioso_en la tierra es,<br/>El nombre de mi Señor.<br/>',NULL,188608,1);
INSERT INTO stanza VALUES('S55','chorus','¡Oh, cuánto amo a Cristo!<br/>¡Oh, cuánto amo a Cristo!<br/>¡Oh, cuánto amo a Cristo!<br/>Pues antes Él me_amó.<br/>',NULL,188609,2);
INSERT INTO stanza VALUES('S55','2','Me habla del que murió por mi<br/>Y de Su grande amor;<br/>También de Su sangre carmesí<br/>Que limpia al pecador.<br/>',NULL,188610,3);
INSERT INTO stanza VALUES('S55','3','Me habla de lo que el Padre da<br/>A diario como porción;<br/>Pues aunque_en valle de oscuridad<br/>Yo ando_en la luz del sol.<br/>',NULL,188611,4);
INSERT INTO stanza VALUES('S55','4','Me habla del corazón de_Aquel<br/>Que puede ver mi dolor;<br/>El cual mi pena cargando_está,<br/>Y la cambia en canción.<br/>',NULL,188612,5);
INSERT INTO stanza VALUES('S56','1','¡Jesús! Tu nombre_al escuchar,<br/>Despliega Tu virtud;<br/>Al perdonado pecador<br/>No_hay otro como Tú.<br/>',NULL,188613,1);
INSERT INTO stanza VALUES('S56','2','Tu nombre_encierra todo bien,<br/>En Ti Dios se mostró.<br/>En Ti logró Dios expresar<br/>Su vida_aquí, Señor.<br/>',NULL,188614,2);
INSERT INTO stanza VALUES('S56','3','Jesús: es nombre de amor,<br/>De pena_y sumisión;<br/>Tu compasión anula_en mi<br/>Toda lamentación.<br/>',NULL,188615,3);
INSERT INTO stanza VALUES('S56','4','Jesús, quien sin pecado es,<br/>Pecado hecho fue;<br/>Justificándonos ganó<br/>Nuestro amor y fe.<br/>',NULL,188616,4);
INSERT INTO stanza VALUES('S56','5','Tu nombre_evoca_adoración<br/>En nuestro corazón;<br/>El principal entre diez mil,<br/>Tu_amor nos libertó.<br/>',NULL,188617,5);
INSERT INTO stanza VALUES('S57','1','Jesús, el nombre sin igual,<br/>En cielo, tierra y mar;<br/>Todo_hombre y_ángel ante Él<br/>Postrado caerá.<br/>',NULL,188618,1);
INSERT INTO stanza VALUES('S57','2','Jesús, Tu nombre dulce es<br/>Al pobre pecador;<br/>Quita la culpa, trae paz,<br/>Y libra del temor.<br/>',NULL,188619,2);
INSERT INTO stanza VALUES('S57','3','Jesús libera de prisión;<br/>Aplasta_a Satanás;<br/>Al alma débil da poder,<br/>Y vida al mortal.<br/>',NULL,188620,3);
INSERT INTO stanza VALUES('S57','4','Oh, si pudiera_el mundo ver<br/>Su gracia_y Su bondad!<br/>El mismo_amor que me_apresó<br/>Podrían abrazar.<br/>',NULL,188621,4);
INSERT INTO stanza VALUES('S57','5','Hoy Su verdad amo_anunciar,<br/>Él mi justicia es;<br/>Todo mi_afán es proclamar:<br/>¡Ved al Cordero fiel!<br/>',NULL,188622,5);
INSERT INTO stanza VALUES('S57','6','Feliz, si puedo respirar<br/>El dulce nombre de_Él,<br/>Y que_al morir pueda gritar:<br/>Ved al Cordero fiel!<br/>',NULL,188623,6);
INSERT INTO stanza VALUES('S58','1','En Tu nombre tan glorioso,<br/>Oh Jesus, me albergué;<br/>Trascendente en Tu nombre,<br/>La victoria_en Ti hallé.<br/>',NULL,188624,1);
INSERT INTO stanza VALUES('S58','2','Salvador, tan poderoso,<br/>Colmas mi necesidad;<br/>Respirar, Jesús, Tu nombre<br/>Me da vida en verdad.<br/>',NULL,188625,2);
INSERT INTO stanza VALUES('S58','3','Todo_el universo muestra<br/>De Tu nombre_el gran poder;<br/>Pero a los perdonados,<br/>Oh Jesús ¡qué dulce es!<br/>',NULL,188626,3);
INSERT INTO stanza VALUES('S58','4','¡Jesucristo! Nombre amado,<br/>Eres bálsamo al dolor;<br/>En Tu Nombre conquistamos,<br/>Ven, glorioso Salvador.<br/>',NULL,188627,4);
INSERT INTO stanza VALUES('S59','1','¡Hoy aquel Nombre exaltad!<br/>Proclame_el cielo su poder;<br/>El Nombre del triunfante Rey<br/>Debe la tierra enaltecer.<br/>',NULL,188628,1);
INSERT INTO stanza VALUES('S59','2','¡Hoy aquel Nombre exaltad!<br/>Nuestro refugio y torre es él;<br/>En aflicción podemos ver<br/>Qué victorioso_el Nombre es.<br/>',NULL,188629,2);
INSERT INTO stanza VALUES('S59','3','¡Hoy aquel Nombre exaltad!<br/>Hasta la tierra conquistar;<br/>Muerte, pecado y el pesar<br/>Cristo en Su reino anulará.<br/>',NULL,188630,3);
INSERT INTO stanza VALUES('S59','4','¡Hoy aquel Nombre exaltad!<br/>Y el Rey de reyes regirá;<br/>Su Nombre sobre todos es,<br/>Nombre que_amamos complacer.<br/>',NULL,188631,4);
INSERT INTO stanza VALUES('S59','5','¡Hoy aquel Nombre exaltad!<br/>Toda rodilla se hincará;<br/>Verá el fruto de Su cruz,<br/>Nuestro Señor y Rey, Jesús.<br/>',NULL,188632,5);
INSERT INTO stanza VALUES('S60','1','Como el "YO SOY" Tu nombre<br/>Es tan rico y abundante,<br/>Todo incluye, pues Tú eres<br/>Nuestra provisión.<br/>',NULL,188633,1);
INSERT INTO stanza VALUES('S60','2','Tú, el Hijo, con el Padre<br/>Como Espíritu en mí vives,<br/>Para que todos Tus bienes<br/>Pueda disfrutar.<br/>',NULL,188634,2);
INSERT INTO stanza VALUES('S60','3','Tú el templo de Dios eres,<br/>De Su vida el despliegue;<br/>Nos gozamos en el Padre<br/>Al mirar Tu faz.<br/>',NULL,188635,3);
INSERT INTO stanza VALUES('S60','4','Tú, el Cordero, Tú, el Novio,<br/>Por Tu novia diste todo;<br/>Fuiste_herido y clavado<br/>En nuestro lugar.<br/>',NULL,188636,4);
INSERT INTO stanza VALUES('S60','5','Tú, el sabio, Tú, el camino<br/>Planificas mi destino;<br/>Por Tu gracia, el suministro,<br/>Puedo_en Ti andar.<br/>',NULL,188637,5);
INSERT INTO stanza VALUES('S60','6','Eres puro, santo y justo,<br/>Y con Dios Tú eres uno,<br/>Le complaces al hacernos<br/>Uno hoy con El.<br/>',NULL,188638,6);
INSERT INTO stanza VALUES('S60','7','Tú_eres vida, luz Tú eres,<br/>Noche_y muerte terminaste,<br/>Alumbrando, avivaste<br/>Todo nuestro ser.<br/>',NULL,188639,7);
INSERT INTO stanza VALUES('S60','8','En resurrección triunfante<br/>Tú el Hades conquistaste;<br/>Con poder nos liberaste<br/>Para en Ti reinar.<br/>',NULL,188640,8);
INSERT INTO stanza VALUES('S60','9','Agua viva y alimento,<br/>Eres Tú nuestro sustento,<br/>Nuestro abastecimiento:<br/>Un banquete real.<br/>',NULL,188641,9);
INSERT INTO stanza VALUES('S60','10','Eres Médico que sanas,<br/>El Pastor de nuestras almas,<br/>Tú nos guías y nos calmas<br/>Dando sanidad.<br/>',NULL,188642,10);
INSERT INTO stanza VALUES('S60','11','Rey y Sacerdote eres,<br/>En Dios Tú nos introduces,<br/>Con Tu autoridad nos suples,<br/>¡Qué lugar de honor!<br/>',NULL,188643,11);
INSERT INTO stanza VALUES('S60','12','Tú, la esperanza viva,<br/>Cambias la creación antigua;<br/>En nosotros te duplicas<br/>Para Tu_expresión.<br/>',NULL,188644,12);
INSERT INTO stanza VALUES('S60','13','Nuestro gozo, paz, y gloria,<br/>Edificio, sol, y gracia,<br/>La verdad, escudo y roca<br/>Todo eres Tú.<br/>',NULL,188645,13);
INSERT INTO stanza VALUES('S60','14','Tú, el eterno y abundante,<br/>Lleno, rico,_inagotable;<br/>En necesidad nos cubres,<br/>¡Hasta desbordar!<br/>',NULL,188646,14);
INSERT INTO stanza VALUES('S61','1','Al Rey supremo alabad,<br/>Al que Su vida dio,<br/>Al  que en lo alto reina hoy,<br/>Al que nos redimió.<br/>',NULL,188647,1);
INSERT INTO stanza VALUES('S61','chorus','Su nombre_ensalzad,<br/>Su nombre_ensalzad,<br/>Del Señor, el nombre_ensalzad.<br/>Su nombre_ensalzad,<br/>Su nombre_ensalzad,<br/>Del Señor, el nombre_ensalzad.<br/>',NULL,188648,2);
INSERT INTO stanza VALUES('S61','2','Su nombre sobre todos es,<br/>El Padre lo exaltó;<br/>A Su derecha lo sentó,<br/>Digno es de adoración.<br/>',NULL,188649,3);
INSERT INTO stanza VALUES('S61','3','Amigo es y Salvador<br/>Del bajo pecador;<br/>El plan de salvación trazó,<br/>Por todos Él murió.<br/>',NULL,188650,4);
INSERT INTO stanza VALUES('S61','4','Su nombre es Consolador<br/>Y Príncipe de Paz;<br/>De reinos es Conquistador,<br/>Por siempre reinará.<br/>',NULL,188651,5);
INSERT INTO stanza VALUES('S62','1','Cerca está el Señor a los que invocan por doquier.<br/>Si clamamos, Su presencia_alienta nuestro ser.<br/>Al buscarlo lo_encontramos en nuestro clamar.<br/>¡Oh, qué consuelo_al corazón Su nombre invocar!<br/>',NULL,188652,1);
INSERT INTO stanza VALUES('S62','chorus','¡Jesús! ¡Qué nombre es!<br/>¡Jesucristo! ¡Vida nos da!<br/>Victorioso! ¡Tan glorioso!<br/>¡Exaltado Su nombre es!<br/>¡Jesús! ¡Fuerza nos da!<br/>¡Jesucristo! ¡Confortará!<br/>Se puede inhalar en cualquier lugar,<br/>¡Jesucristo! ¡Nombre especial!<br/>',NULL,188653,2);
INSERT INTO stanza VALUES('S62','2','Clama al Señor Jesús y salvo tú serás.<br/>¡Aleluya! ¡Oh Señor! ¡Esclavos nunca más!<br/>Copa de la salvación tomamos al clamar,<br/>De multitud de cosas, salvación Su nombre da.<br/>',NULL,188654,3);
INSERT INTO stanza VALUES('S62','3','Para el Señor, judío o griego es igual,<br/>A cualquiera que le_invoque Sus riquezas da.<br/>¡Oh Señor Jesús! Qué gozo es clamar y vivir;<br/>Al respirar Tu nombre qué placer haces sentir.<br/>',NULL,188655,4);
INSERT INTO stanza VALUES('S62','4','¡Hay delicias en el Dios de nuestra salvación!<br/>A Su nombre clamaremos en cada ocasión.<br/>En desgracia o_alegría clamaré al Señor,<br/>Porque Su_oído_inclina y Su gracia nos da Dios.<br/>',NULL,188656,5);
INSERT INTO stanza VALUES('S62','5','Clamaremos al Señor, que_es digno de loor,<br/>Nuestras alabanzas El merece con honor.<br/>Somos los que claman a Su nombre por doquier,<br/>Con los de puro corazón gozamos gracia de_Él.<br/>',NULL,188657,6);
INSERT INTO stanza VALUES('S63','1','Tu nombre, ¡como‿ungüento es,<br/>¡Jesús, Jesús, Jesús, Jesús!<br/>Tu nombre, ¡como‿ungüento es,<br/>Tu nombre, ¡como‿ungüento es.<br/>',NULL,188658,1);
INSERT INTO stanza VALUES('S63','2','Las virgenes te aman, Señor;<br/>¡Jesús, Jesús, Jesús, Jesús!<br/>Las virgenes te aman, Señor;<br/>Las virgenes te aman, Señor.<br/>',NULL,188659,2);
INSERT INTO stanza VALUES('S63','3','Mejor que el vino_es Tu amor:<br/>¡Jesús, Jesús, Jesús, Jesús!<br/>Mejor que el vino_es Tu amor:<br/>Mejor que el vino_es Tu amor.<br/>',NULL,188660,3);
INSERT INTO stanza VALUES('S63','4','Atráeme, iremos a Ti:<br/>¡Jesús, Jesús, Jesús, Jesús!;<br/>Atráeme, iremos a Ti;<br/>Atráeme, iremos a Ti:<br/>',NULL,188661,4);
INSERT INTO stanza VALUES('S63','5','Mi Amado, cuán bello eres Tú:<br/>¡Jesús, Jesús, Jesús, Jesús!<br/>Mi Amado, cuán bello eres Tú:<br/>Mi Amado, cuán bello eres Tú.<br/>',NULL,188662,5);
INSERT INTO stanza VALUES('S63','6','Al que_ama mi alma hallé:<br/>¡Jesús, Jesús, Jesús, Jesús!<br/>Al que_ama mi alma hallé;<br/>Al que_ama mi alma hallé:<br/>',NULL,188663,6);
INSERT INTO stanza VALUES('S63','7','Lo_hallé y no lo dejaré:<br/>¡Jesús, Jesús, Jesús, Jesús!<br/>Lo_hallé y no lo dejaré;<br/>Lo_hallé y no lo dejaré.<br/>',NULL,188664,7);
INSERT INTO stanza VALUES('S63','8','Ven pronto, mi_amado Señor:<br/>¡Jesús, Jesús, Jesús, Jesús!<br/>Ven pronto, mi_amado Señor;<br/>Ven pronto, mi_amado Señor.<br/>',NULL,188665,8);
INSERT INTO stanza VALUES('S63','9','Te_amamos hoy de corazón:<br/>¡Jesús, Jesús, Jesús, Jesús!<br/>Te_amamos hoy de corazón:<br/>Te_amamos hoy de corazón.<br/>',NULL,188666,9);
INSERT INTO stanza VALUES('S64','1','Nombre:_"Admirable" es;<br/>Es Consejero fiel;<br/>Su nombre: Fuerte Dios,<br/>Señor Jesús.<br/>Niño e Hijo es;<br/>Es Padre Eternal;<br/>Mi Príncipe de paz:<br/>Señor Jesús.<br/>Alaba_al Creador,<br/>Salvador, Cristo,<br/>Pneuma que vida da.<br/>En tu espíritu<br/>Adora y ámalo;<br/>Nombre "Admirable" es,<br/>Señor Jesús.<br/>',NULL,188667,1);
INSERT INTO stanza VALUES('S65','1','¡Cuánto amamos proclamar<br/>El nombre de Jesús!<br/>En el cielo o_en la tierra<br/>Muy alto está;<br/>Pues Su nombre_al respirar<br/>Hace_huir la oscuridad;<br/>¡Qué precioso es el nombre de Jesús!<br/>',NULL,188668,1);
INSERT INTO stanza VALUES('S65','2','Nuestra lengua, oh, Señor,<br/>Tu nombre confiesa hoy<br/>Para complacer al Padre Dios de amor;<br/>Alabar Tu nombre así,<br/>Es un disfrute para mí,<br/>Invocar Tu nombre es amarte_a Ti.<br/>',NULL,188669,2);
INSERT INTO stanza VALUES('S66','1','Señor, por siempre existes Tú,<br/>Desde lo antaño eres Dios;<br/>Eres el Padre eternal,<br/>El increado gran YO SOY.<br/>',NULL,188670,1);
INSERT INTO stanza VALUES('S66','2','Aunque te_hiciste un hombre fiel,<br/>Tu ser con Dios eterno es;<br/>Completo_en todo como Él,<br/>E infinito_eres también.<br/>',NULL,188671,2);
INSERT INTO stanza VALUES('S66','3','La misma fuente, Tú y Dios,<br/>Precedes toda la creación;<br/>Antes del delantero, Tú;<br/>Antes de Ti nada_existió.<br/>',NULL,188672,3);
INSERT INTO stanza VALUES('S66','4','El tiempo no te cambiará,<br/>Tus años son la eternidad,<br/>Nada perdura como Tú,<br/>De todo eres el final.<br/>',NULL,188673,4);
INSERT INTO stanza VALUES('S66','5','Tal como_el Padre, oh Jesús,<br/>Perfecto_en todo como Él;<br/>Alfa y_Omega eres Tú,<br/>Primero_y Ultimo también.<br/>',NULL,188674,5);
INSERT INTO stanza VALUES('S66','6','A Ti, Señor, hay que_alabar,<br/>Y admirar Tu vastedad;<br/>Se debe_honrar Tu perfección,<br/>Y elogiar Tu_eternidad.<br/>',NULL,188675,6);
INSERT INTO stanza VALUES('S67','1','¡Qué bella historia!<br/>De Su excelsa gloria<br/>Bajó el Salvador;<br/>Jesús mi Redentor.<br/>Nació_en pesebre,<br/>Despreciado_y pobre,<br/>Varón de lágrimas<br/>Y de dolor.<br/>',NULL,188676,1);
INSERT INTO stanza VALUES('S67','chorus','¡Oh, cuánto lo_amo!<br/>Y fiel, lo_adoro,<br/>Él es mi vida,<br/>¡Mi todo es Él!<br/>El Rey de gloria<br/>Se hizo hombre,<br/>El Dios completo,<br/>Mi Salvador.<br/>',NULL,188677,2);
INSERT INTO stanza VALUES('S67','2','¡Cuánta obediencia!<br/>¡Qué condescendencia!<br/>Cuando_en la noche_atroz,<br/>Sin esperanza en pos,<br/>Humilde_y tierno,<br/>Nuestro Dios viniendo,<br/>Libró mi alma,<br/>Me salvó y ganó.<br/>',NULL,188678,3);
INSERT INTO stanza VALUES('S67','3','¡Sin resistirlo!<br/>¡Como hombre vino!<br/>De carne se vistió,<br/>Su sangre derramó.<br/>¡Qué gran misterio!<br/>Revelose al mundo,<br/>Y_ahora se que_eres<br/>El gran "YÓ SOY".<br/>',NULL,188679,4);
INSERT INTO stanza VALUES('S68','1','Escuchad en alta esfera:<br/>"Gloria al Dios de Israel".<br/>Gracia_y paz trae a la tierra<br/>El recién nacido Rey.<br/>Dios en paz con pecadores,<br/>Gozo_excelso_a las naciones,<br/>//Proclamad a una voz:<br/>"Cristo en Belén nació".//<br/>',NULL,188680,1);
INSERT INTO stanza VALUES('S68','2','Cristo en gloria adorado,<br/>El Ungido celestial,<br/>Vino al cumplirse el tiempo<br/>Desde un vientre virginal.<br/>¡Ved la Deidad tan querida<br/>En la carne escondida!<br/>//Vino al hombre un Hombre fiel<br/>Cuyo nombre es Emanuel.//<br/>',NULL,188681,2);
INSERT INTO stanza VALUES('S68','3','¡Gloria_al Sol de la justicia!<br/>Gloria_al Príncipe de Paz!<br/>Salvación trae en Sus alas,<br/>Luz y vida eternal.<br/>Siendo Dios te despojaste,<br/>De la muerte nos salvaste;<br/>//Tú naciste para dar<br/>Vida eterna al mortal.//<br/>',NULL,188682,3);
INSERT INTO stanza VALUES('S68','4','¡Ven, Deseado de naciones!<br/>¡Haz Tu hogar en nuestro ser!<br/>Y aplasta_a la serpiente<br/>Tú, simiente de mujer.<br/>La fallida semejanza<br/>Cambia a Tu imagen santa,<br/>//Y como_el postrer Adán<br/>Nos reinstales en Tu amor.//<br/>',NULL,188683,4);
INSERT INTO stanza VALUES('S69','1','Aunque_eres Tú el sumo Dios,<br/>Forma de carne te vistió;<br/>Un hombre_humilde nos llegó,<br/>Te recuerdo, Señor.<br/>',NULL,188684,1);
INSERT INTO stanza VALUES('S69','2','Gloria divina se veló,<br/>Cuando la carne te cubrió;<br/>Nada_atractivo_en Ti se vio,<br/>Te recuerdo, Señor.<br/>',NULL,188685,2);
INSERT INTO stanza VALUES('S69','3','El Varón de dolores, Tú,<br/>De tierra seca, la raíz;<br/>Te desechó el mundo_aquí,<br/>Te recuerdo, Señor.<br/>',NULL,188686,3);
INSERT INTO stanza VALUES('S69','4','Tu_humilde corazón, Señor,<br/>Nunca_una queja expresó;<br/>Siempre dispuesto a dolor,<br/>Te recuerdo, Señor.<br/>',NULL,188687,4);
INSERT INTO stanza VALUES('S69','5','Eres perfecto_en todo Tú,<br/>Un hombre de tan grato olor;<br/>Al Padre,_ofrenda de valor;<br/>Te recuerdo, Señor.<br/>',NULL,188688,5);
INSERT INTO stanza VALUES('S69','6','La voluntad del Padre hacer<br/>Fue para Ti de gran placer;<br/>Tú resististe_a Lucifer<br/>Te recuerdo, Señor.<br/>',NULL,188689,6);
INSERT INTO stanza VALUES('S69','7','Obedeciendo siempre_a Dios,<br/>Sufriste en cruenta cruz por mí,<br/>En mi lugar moriste allí,<br/>Te recuerdo, Señor.<br/>',NULL,188690,7);
INSERT INTO stanza VALUES('S69','8','Tu Dios, por tanto, te_exaltó,<br/>Con gloria_así te coronó;<br/>Todos te rendirán honor;<br/>Te_adoro, oh Señor.<br/>',NULL,188691,8);
INSERT INTO stanza VALUES('S70','1','Contemplo_aquí Tu vida hoy,<br/>Tus pasos, oh Señor;<br/>Tu gracia_el hombre recibió,<br/>Y fuiste fiel a Dios.<br/>',NULL,188692,1);
INSERT INTO stanza VALUES('S70','2','Tu_amor: el hombre lo retó,<br/>Mas al Seol venció.<br/>La lanza sangre derramó,<br/>Trayendo salvación.<br/>',NULL,188693,2);
INSERT INTO stanza VALUES('S70','3','Tu vida sin lamentación,<br/>De penas llena fue.<br/>Aunque sufriste afflicción,<br/>Hiciste siempre_el bien.<br/>',NULL,188694,3);
INSERT INTO stanza VALUES('S70','4','Entre infieles fuiste fiel,<br/>Luz en la_oscuridad;<br/>Nos revelaste_al Padre, Tú,<br/>Su nombre_y voluntad.<br/>',NULL,188695,4);
INSERT INTO stanza VALUES('S70','5','Ningún apoyo terrenal<br/>Tuviste en la cruz;<br/>Vergüenza,_oprobio_y Satanás:<br/>Venciste todo Tú.<br/>',NULL,188696,5);
INSERT INTO stanza VALUES('S70','6','¡Oh, qué_admirable humildad!<br/>Deseamos ser así.<br/>Hoy nuestro_anhelo_y buen placer<br/>Es aprender de Ti.<br/>',NULL,188697,6);
INSERT INTO stanza VALUES('S71','1','Nuestro débil canto_acepta<br/>Gloria y fuerza Tuyas son.<br/>Recordamos hoy Tu gracia,<br/>Nuestro_amado Salvador.<br/>',NULL,188698,1);
INSERT INTO stanza VALUES('S71','2','Rico_en gloria, te_humillaste,<br/>¡Nuestra esperanza aquí!<br/>Fuiste pobre para hacernos<br/>Ricos en Tu gloria_así.<br/>',NULL,188699,2);
INSERT INTO stanza VALUES('S71','3','¿Por qué desdeñaste_el cielo<br/>Para_en esta tierra_andar?<br/>¿Por qué padeciste muerte,<br/>Mofa,odio_y soledad?<br/>',NULL,188700,3);
INSERT INTO stanza VALUES('S71','4','En los cielos: El Glorioso;<br/>Pero en la tierra, Tú<br/>Enfrentaste_el sufrimiento<br/>Por Tu_amor y gran virtud.<br/>',NULL,188701,4);
INSERT INTO stanza VALUES('S71','5','Cuando_en tal amor pensamos,<br/>Gozo_y vergüenza se ven;<br/>Por Tu compasión: el gozo;<br/>Vengüenza: por nuestro_hacer.<br/>',NULL,188702,5);
INSERT INTO stanza VALUES('S71','6','Esperamos ver el día,<br/>Sin ninguna restricción,<br/>Cuando_en gloria te sirvamos<br/>Con entera devoción.<br/>',NULL,188703,6);
INSERT INTO stanza VALUES('S71','7','Nuestro anhelo y_esperanza<br/>Es vivir por Ti, Señor;<br/>Y ser fieles hasta verte<br/>Con Tus santos en amor.<br/>',NULL,188704,7);
INSERT INTO stanza VALUES('S72','1','Con afecto apreciamos<br/>Toda Tu_aflicción, Señor.<br/>Contemplamos Tu angustia;<br/>Nos compunge_el corazón.<br/>',NULL,188705,1);
INSERT INTO stanza VALUES('S72','chorus','¡Te_alabamos! ¡Te_alabamos<br/>Por Tu muerte, Salvador!<br/>!Damos gloria! Damos gloria<br/>Por la vida que Jesús nos dio!<br/>',NULL,188706,2);
INSERT INTO stanza VALUES('S72','2','Tus profundos sufrimientos<br/>No se pueden escrutar;<br/>Tan intensa_y santa pena<br/>No se puede enunciar.<br/>',NULL,188707,3);
INSERT INTO stanza VALUES('S72','3','Nadie pudo_allí seguirte,<br/>A la cruz de redención;<br/>Tales penas insondables<br/>Sólo Tuyas son, Señor.<br/>',NULL,188708,4);
INSERT INTO stanza VALUES('S72','4','Te llevaste los pecados,<br/>Juicio, ira_y maldición;<br/>Traicionado, abandonado,<br/>Mas así se vio Tu_amor.<br/>',NULL,188709,5);
INSERT INTO stanza VALUES('S73','1','Qué carga sobre Ti cayó,<br/>Oh Cristo, Salvador;<br/>Sustituiste_al pecador,<br/>Llevaste mi aflicción.<br/>Tu sangre derramada fue;<br/>¡No llevó cargas hoy!<br/>',NULL,188710,1);
INSERT INTO stanza VALUES('S73','2','La copa de la maldición<br/>Bebiste, oh Señor;<br/>Ni una gota_ahí quedó,<br/>Tu_amor ya la tomó.<br/>La copa_amarga se vació;<br/>Hoy tengo bendición.<br/>',NULL,188711,2);
INSERT INTO stanza VALUES('S73','3','¡Jehová Su vará levantó<br/>Y sobre Ti cayó!<br/>Golpeado fuiste_así por Dios,<br/>Mas yo ileso_estoy.<br/>Con lágrimas, sangre fluyó;<br/>Tu_herida me sanó.<br/>',NULL,188712,3);
INSERT INTO stanza VALUES('S73','4','La tempestad así rugió,<br/>¡A Ti te azotó!<br/>Tu pecho_abierto me cubrió<br/>De ese gran turbión.<br/>Tu forma se desfiguró,<br/>Mas paz yo tengo hoy.<br/>',NULL,188713,4);
INSERT INTO stanza VALUES('S73','5','Jehová Su_espada despertó,<br/>¡A ti te traspasó!<br/>Tu sangre ella requirió,<br/>Tu corazón clavó:<br/>¡Con Dios mi paz estableció!<br/>Su_espada no me hirió!<br/>',NULL,188714,5);
INSERT INTO stanza VALUES('S73','6','Por mi moriste, mi Señor,<br/>Y_en Ti he muerto yo;<br/>Resucitaste_y libre soy,<br/>En mí Tú vives hoy.<br/>Más puro_y blanco me harás,<br/>¡Tu gloria me darás!<br/>',NULL,188715,6);
INSERT INTO stanza VALUES('S74','1','Cabeza magullada<br/>Con penas y pesar;<br/>De_espinas la corona<br/>Para burla causar.<br/>Oh Cabeza, hoy llevas<br/>Brillante majestad,<br/>Mas en la cruz llevaste<br/>Oprobio_y mi maldad.<br/>',NULL,188716,1);
INSERT INTO stanza VALUES('S74','2','¡Semblante trascendente!<br/>¡Tú, Sol que vida das!<br/>Tu rostro escupieron,<br/>Golpeada fue Tu faz.<br/>Señor, nuestro pecado<br/>Tormento te causó;<br/>Nuestra deuda_aumentada,<br/>Tu sangre la pagó.<br/>',NULL,188717,2);
INSERT INTO stanza VALUES('S74','3','Sin fin te damos gracias,<br/>Amigo_y Salvador;<br/>Por nuestro bien sangraste<br/>Y Tu_alma padeció.<br/>Que sin dudar confiemos<br/>En Tu fidelidad,<br/>Hasta en gloria verte<br/>Y contemplar Tu faz.<br/>',NULL,188718,3);
INSERT INTO stanza VALUES('S75','1','Es mi canción amor<br/>Me_amó mi Salvador;<br/>Él abrazó a quien<br/>Nunca_amor recibió.<br/>Oh, ¿quién soy yo<br/>Que, por mi bien,<br/>Mi Cristo se_encarnó_y murió?<br/>',NULL,188719,1);
INSERT INTO stanza VALUES('S75','2','Del trono_Él descendió<br/>A darnos salvación.<br/>Mas no reconoció<br/>La gente al Señor.<br/>Qué_Amigo es El,<br/>Mi_Amigo fiel<br/>Que dio Su vida por mi bien.<br/>',NULL,188720,2);
INSERT INTO stanza VALUES('S75','3','A veces el Señor<br/>Elogios recibió;<br/>El pueblo lo_aclamó,<br/>"Hosana" le cantó;<br/>Pero después<br/>Se_oyó_el clamor<br/>Pidiendo Su crucifixión.<br/>',NULL,188721,3);
INSERT INTO stanza VALUES('S75','4','El pueblo decidió<br/>Hacerlo padecer;<br/>Un homicida fue<br/>Librado_en vez de Él.<br/>Mas mi Jesús<br/>Con gozo fue<br/>Por todos ellos a la cruz.<br/>',NULL,188722,4);
INSERT INTO stanza VALUES('S75','5','Aquí no tuvo_hogar,<br/>Y_aún cuando murió,<br/>Yació en un sepulcro<br/>Que_otro proveyó.<br/>Su celestial<br/>Hogar dejó;<br/>Por mi_al sepulcro Él llegó.<br/>',NULL,188723,5);
INSERT INTO stanza VALUES('S75','6','Aquí me quedaré,<br/>Por siempre cantaré<br/>Tu dulce_amor, mi Rey,<br/>Y Tu gran padecer.<br/>Amigo fiel,<br/>¡Te_alabaré!<br/>Contigo permaneceré.<br/>',NULL,188724,6);
INSERT INTO stanza VALUES('S76','1','El Hacedor, como Hombre, fue<br/>Por hombres hecho maldición;<br/>Lo que_exigió Su misma ley,<br/>Hasta lo sumo Él pagó.<br/>',NULL,188725,1);
INSERT INTO stanza VALUES('S76','2','Hizo la rama que brotó<br/>Espinas que_en Su sien llevó;<br/>El clavo que lo traspasó<br/>Salió de minas que_Él creó.<br/>',NULL,188726,2);
INSERT INTO stanza VALUES('S76','3','Hizo el árbol que formó<br/>La cruz de la cual Él colgó;<br/>Él hizo_el monte_en que se_alzó<br/>La cruz en la cual Él murió.<br/>',NULL,188727,3);
INSERT INTO stanza VALUES('S76','4','Él extendió el cielo que<br/>Sobre Su faz se_oscureció;<br/>El sol que su rostro_escondió,<br/>Por Su decreto_Él suspendió.<br/>',NULL,188728,4);
INSERT INTO stanza VALUES('S76','5','La lanza que lo traspasó,<br/>Fuego divino la templó;<br/>La tumba donde reposó<br/>Era_una peña que_El formó.<br/>',NULL,188729,5);
INSERT INTO stanza VALUES('S76','6','El trono_en que sentado_está<br/>Fue Suyo por la_eternidad;<br/>Mas nueva gloria_Él lleva ya;<br/>Todos a Él se_inclinarán.<br/>',NULL,188730,6);
INSERT INTO stanza VALUES('S77','1','Al contemplar la  excelsa cruz<br/>Donde_el Señor por mí murió,<br/>Estimo como pérdida,<br/>Toda ganancia vana_aquí.<br/>',NULL,188731,1);
INSERT INTO stanza VALUES('S77','2','¿En qué me puedo yo gloriar<br/>Si no_en Su muerte en la cruz?<br/>Las cosas que me_atraen más,<br/>Hoy sacrifico por Jesús.<br/>',NULL,188732,2);
INSERT INTO stanza VALUES('S77','3','De Su cabeza, manos, pies,<br/>Preciosa sangre allí corrió;<br/>Corona vil de espinas fue<br/>La que por mí Jesús llevó.<br/>',NULL,188733,3);
INSERT INTO stanza VALUES('S77','4','Cuando Su sangre carmesí<br/>Cubrió el cuerpo del Señor,<br/>Murió el mundo para mí,<br/>Y para el mundo muerto estoy.<br/>',NULL,188734,4);
INSERT INTO stanza VALUES('S77','5','El mundo entero no será<br/>Dádiva digna de_ofrecer.<br/>Amor tan grande y sin igual<br/>Exige en cambio todo el ser.<br/>',NULL,188735,5);
INSERT INTO stanza VALUES('S78','1','Dios nació un ser humano,<br/>Como_infante, en Belén;<br/>Tuvo un vivir humano<br/>Dios y_el hombre: un mismo ser.<br/>Dios y_el hombre, incorporados,<br/>Viven en unión mezclados.<br/>¡Aleluya, aleluya,<br/>Aleluya, amén!<br/>',NULL,188736,1);
INSERT INTO stanza VALUES('S78','2','Luego fue este Dios-hombre<br/>A morir en el altar;<br/>La creación llevó consigo<br/>Para_allí todo_acabar.<br/>El hombre_y toda creación<br/>En total terminación.<br/>¡Aleluya, aleluya,<br/>Aleluya, amén!<br/>',NULL,188737,2);
INSERT INTO stanza VALUES('S78','3','Lo que éramos nosotros,<br/>En la cruz se_aniquiló.<br/>Lo de_Adán quedó en la tumba,<br/>Mas el hombre_en Dios subió.<br/>¡Aleluya, liberados!<br/>El viejo_hombre,_aniquilado.<br/>¡Aleluya, aleluya,<br/>Aleluya, amén!<br/>',NULL,188738,3);
INSERT INTO stanza VALUES('S78','4','Para ser multiplicado,<br/>Sólo_un grano se sembró;<br/>Dios llevó Su vida_a muerte,<br/>Y Su vida_así libró.<br/>¡Sea Cristo alabado!<br/>¡Hombre_en Dios resucitado!<br/>¡Aleluya, aleluya,<br/>Aleluya, amén!<br/>',NULL,188739,4);
INSERT INTO stanza VALUES('S79','1','El Cordero de Dios vino,<br/>Por el pecador murió.<br/>Por Su sangre derramada<br/>Él logró la redención.<br/>El Cordero nos redime,<br/>¡Los pecados Él quitó!<br/>¡Los pecados Él quitó!<br/>',NULL,188740,1);
INSERT INTO stanza VALUES('S79','2','La serpiente de bronce_eres:<br/>Hijo del Hombre_eres Tú.<br/>Como hombre en la carne,<br/>Tú moriste en la cruz.<br/>Tú juzgaste este mundo,<br/>¡La creación y Satanás!<br/>¡La creación y Satanás!<br/>',NULL,188741,2);
INSERT INTO stanza VALUES('S79','3','Si no muere este grano<br/>De trigo, muy sólo_está;<br/>Mas si cae_en tierra_y muere,<br/>Brota vida divinal.<br/>Por la vida Cristo aumenta;<br/>¡Muchos granos nacerán!<br/>¡Muchos granos nacerán!<br/>',NULL,188742,3);
INSERT INTO stanza VALUES('S79','4','El Cordero nos redime,<br/>Y el grano vida da,<br/>Mas la serpiente de bronce<br/>Destruyó a Satanás.<br/>¡Esta muerte todo_incluye!<br/>¡Aleluya, gloria dad!<br/>¡Aleluya, gloria dad!<br/>',NULL,188743,4);
INSERT INTO stanza VALUES('S80','1','Mi soberano Salvador,<br/>¿Por mí sangró_y murió?<br/>¿Sus sienes santas ofreció<br/>Por un vil como yo?<br/>',NULL,188744,1);
INSERT INTO stanza VALUES('S80','2','¿Por los pecados que hice yo<br/>En una cruz gimió?<br/>¡Gracia asombrosa, qué piedad,<br/>E_inmensurable_amor!<br/>',NULL,188745,2);
INSERT INTO stanza VALUES('S80','3','El sol por eso se_escondió;<br/>Su gloria encubrió<br/>Cuando Jesús, el gran Creador,<br/>Por el hombre murió.<br/>',NULL,188746,3);
INSERT INTO stanza VALUES('S80','4','Aunque mi rostro escondo yo<br/>Al contemplar la cruz,<br/>Se me derrite_el corazón<br/>En honda gratitud.<br/>',NULL,188747,4);
INSERT INTO stanza VALUES('S80','5','Jamás mis lágrimas podrán<br/>Pagar por tal amor;<br/>Lo único que puedo_hacer<br/>Es darme_a Tí, Señor.<br/>',NULL,188748,5);
INSERT INTO stanza VALUES('S81','1','El no podía salvarse,<br/>Tenía que morir,<br/>Para que la piedad<br/>Llegara hasta el vil;<br/>Sí, Cristo  tuvo  que sangrar,<br/>Para‿al vil pecador librar,<br/>Para‿al vil pecador librar.<br/>',NULL,188749,1);
INSERT INTO stanza VALUES('S81','2','El no podía salvarse,<br/>Para justicia fue;<br/>Tenían que caer<br/>Las culpas sobre El;<br/>La deuda nuestra así pagó<br/>//Por eso, Dios nos perdonó.//<br/>',NULL,188750,2);
INSERT INTO stanza VALUES('S81','3','El no podía salvarse,<br/>Pues es Fiador veraz<br/>A los que tienen fe<br/>En Su sangre eficaz;<br/>Nuestro castigo El sufrió<br/>//Cuando Su sangre se vertió.//<br/>',NULL,188751,3);
INSERT INTO stanza VALUES('S81','4','El no podía salvarse,<br/>¡Qué admirable amor!<br/>En ese amor tan fiel<br/>Hasta Su vida dio;<br/>Su amor derrite el corazón<br/>//Hasta rendirle adoración.//<br/>',NULL,188752,4);
INSERT INTO stanza VALUES('S82','1','Oh, qué nombre se le dio<br/>¡Al santo Hijo de Dios!<br/>"Varón de dolores" fue<br/>¡Aleluya! ¡Cristo salva!<br/>',NULL,188753,1);
INSERT INTO stanza VALUES('S82','2','Mofa y desdén sufrió,<br/>Mi condenación llevó,<br/>Él por mi perdón sangró,<br/>¡Aleluya! ¡Cristo salva!<br/>',NULL,188754,2);
INSERT INTO stanza VALUES('S82','3','Era un débil reo yo,<br/>Mas el Cordero de Dios<br/>Plena redención logró,<br/>¡Aleluya! ¡Cristo salva!<br/>',NULL,188755,3);
INSERT INTO stanza VALUES('S82','4','Levantado, Él murió,<br/>"Consumado es! clamó;"<br/>Dios al cielo le exaltó,<br/>¡Aleluya! ¡Cristo salva!<br/>',NULL,188756,4);
INSERT INTO stanza VALUES('S82','5','En Su gloria_el Rey vendrá,<br/>En Su reino nos pondrá,<br/>Y de nuevo_hay que cantar:<br/>¡Aleluya! ¡Cristo salva!<br/>',NULL,188757,5);
INSERT INTO stanza VALUES('S83','1','¡El velo ya rasgado fue!<br/>Jesús delante está<br/>Del trono de la gracia hoy;<br/>Incienso brota ya.<br/>',NULL,188758,1);
INSERT INTO stanza VALUES('S83','2','Ya frente_al trono,_y sobre él,<br/>Su sangre Él roció;<br/>Declaran Sus heridas que<br/>La obra_Él terminó.<br/>',NULL,188759,2);
INSERT INTO stanza VALUES('S83','3','El dijo: "Consumado es",<br/>Mientras la cruz sufrió;<br/>Hoy vive para_interceder<br/>Ante la faz de Dios.<br/>',NULL,188760,3);
INSERT INTO stanza VALUES('S83','4','Nuestra_alma puede reposar,<br/>Su obra triunfará;<br/>Por nuestro Sacerdote real,<br/>¡El velo ya cruzad!<br/>',NULL,188761,4);
INSERT INTO stanza VALUES('S84','1','¡Qué dulce, qué bella, la historia de amor!<br/>Que trajo a Cristo_a sufrir mi dolor;<br/>Murió en la cruz del Calvario por mí,<br/>Para redimirme, librándome así.<br/>',NULL,188762,1);
INSERT INTO stanza VALUES('S84','chorus','¡Alabad al Señor! Todo Él consumó.<br/>¡Alabad al Señor! Al Amado de Dios;<br/>Jesús, te alabamos, Amigo y Señor,<br/>Te damos la gloria, nuestro Redentor.<br/>',NULL,188763,2);
INSERT INTO stanza VALUES('S84','2','¡Tremenda la historia de la redención!<br/>Las santas demandas de la ley cumplió;<br/>Por nuestros pecados el juicio llevó<br/>El Hijo que_en todo al Padre honró.<br/>',NULL,188764,3);
INSERT INTO stanza VALUES('S84','3','El Cristo_entronado con gloria sin par,<br/>Merece tal nombre que no tiene_igual;<br/>Está coronado Jesús el Señor,<br/>Es digno por siempre de gloria y honor.<br/>',NULL,188765,4);
INSERT INTO stanza VALUES('S85','1','Dulce sonido sin igual,<br/>La alabanza_a nuestro Dios;<br/>Si rehusáramos cantar,<br/>Las rocas clamarían hoy.<br/>',NULL,188766,1);
INSERT INTO stanza VALUES('S85','2','Él con Su sangre nos lavó;<br/>Cantémosle dulce canción;<br/>Nos encontró lejos de Dios<br/>Y nos preserva siempre hoy.<br/>',NULL,188767,2);
INSERT INTO stanza VALUES('S85','3','Qué melodía sin igual<br/>Canta el salvo pecador;<br/>Sólo el tal podrá cantar<br/>La salvación que recibió.<br/>',NULL,188768,3);
INSERT INTO stanza VALUES('S85','4','Ángeles pueden vislumbrar<br/>La sangre de nuestro Señor;<br/>Mas no podrán jamás probar<br/>De Su virtud que nos limpió.<br/>',NULL,188769,4);
INSERT INTO stanza VALUES('S85','5','Los ángeles dan gloria al Rey<br/>Y lo adoran por ser Dios;<br/>Mas lo que hoy cantamos es:<br/>"¡Un hombre_al trono ascendió!"<br/>',NULL,188770,5);
INSERT INTO stanza VALUES('S85','6','Te adoramos por Tu amor<br/>Que te llevó_a morir aquí<br/>Para salvar al pecador<br/>Llevándolo al Padre_así.<br/>',NULL,188771,6);
INSERT INTO stanza VALUES('S86','1','¡Qué admirable redención<br/>Se halla_en Ti, Señor!<br/>¡Jamás se vio, se_oyó_o pensó<br/>Lo que logró Tu amor!<br/>¡Divino_y misterioso Tú<br/>Excedes todo_hablar!<br/>¡Tan admirable redención<br/>Excede mi alabar!<br/>',NULL,188772,1);
INSERT INTO stanza VALUES('S86','2','Te traspasaron en la cruz<br/>Para_agua y sangre_hallar;<br/>Así Tu vida se nos dio<br/>Y redención sin par.<br/>Preciosa sangre nos limpió,<br/>Para aceptados ser;<br/>Tu vida nos regeneró,<br/>Para la unión tener.<br/>',NULL,188773,2);
INSERT INTO stanza VALUES('S86','3','Divino grano que murió<br/>Para muchos llevar,<br/>Mezclados en perfecta_unión<br/>Tu Cuerpo formarán.<br/>Tu aumento somos, oh Señor<br/>Tú,_el contenido que<br/>Nos vivificas con poder,<br/>Manifestándote.<br/>',NULL,188774,3);
INSERT INTO stanza VALUES('S86','4','Ya que Tu Cuerpo somos hoy,<br/>Morando en él estás;<br/>Debemos ser Tu dulce_hogar,<br/>Confianza te será.<br/>Tu complemento somos y<br/>Tu gran satisfacción;<br/>Un Cuerpo en Ti somos, Señor<br/>Y Tú, nuestra porción.<br/>',NULL,188775,4);
INSERT INTO stanza VALUES('S86','5','Al contemplar los símbolos<br/>Nos hacen recordar<br/>Tu gran y plena redención,<br/>Y alabanzas dar.<br/>Por ser Tu Cuerpo y novia hoy,<br/>Tu misma habitación,<br/>Te damos gracias y loor<br/>En nuestra adoración.<br/>',NULL,188776,5);
INSERT INTO stanza VALUES('S87','1','Señor, Tu sangre_es sin igual,<br/>¡Del nuevo pacto es!<br/>Por ella nos bendice Dios<br/>Y nos mezcla con Él.<br/>',NULL,188777,1);
INSERT INTO stanza VALUES('S87','2','Tu sangre ya nos redimió<br/>Y nos santificó;<br/>De obras muertas y_el pecar,<br/>La conciencia limpió.<br/>',NULL,188778,2);
INSERT INTO stanza VALUES('S87','3','Habla mejor Tu sangre_a Dios<br/>Que la de_Abel, Señor;<br/>Provee perfecta redención;<br/>Complace_al justo Dios.<br/>',NULL,188779,3);
INSERT INTO stanza VALUES('S87','4','Por el eterno Espíritu,<br/>A Dios te diste fiel.<br/>Tal sacrificio_es eficaz;<br/>Tu sangre_eterna es.<br/>',NULL,188780,4);
INSERT INTO stanza VALUES('S87','5','Al trono de la gracia hoy,<br/>Por Tu sangre, Señor,<br/>Vamos confiados hacia Dios,<br/>Hasta el Santísimo.<br/>',NULL,188781,5);
INSERT INTO stanza VALUES('S87','6','Tu sangre obliga_a Dios, Señor,<br/>A dar Si mismo Ser;<br/>Debe tomarnos para Sí<br/>Y_en nosotros vivir.<br/>',NULL,188782,6);
INSERT INTO stanza VALUES('S87','7','Señor, Tu sangre_es sin igual,<br/>¡Del nuevo pacto es!<br/>Por ella nos bendice Dios<br/>Y nos mezcla con Él.<br/>',NULL,188783,7);
INSERT INTO stanza VALUES('S88','1','Te alabamos, oh Señor Jesús,<br/>Nos revelaste el camino_a Dios.<br/>Atrás dejaste_el trono_y su virtud,<br/>¡Qué Sumo Sacerdote nos llegó!<br/>Tu sangre ofreciste, oh Señor,<br/>Y paz por siempre nos diste con Dios.<br/>',NULL,188784,1);
INSERT INTO stanza VALUES('S88','2','El trono con Tu sangre se roció,<br/>Tu pueblo redimiste del pecar.<br/>El dulce_amor que diste_a conocer<br/>Nos llena_en el Santísimo Lugar;<br/>Y por Tu sangre_allí, tenemos hoy<br/>Misericordia_y gracia_en nuestro Dios.<br/>',NULL,188785,2);
INSERT INTO stanza VALUES('S88','3','Viniste no sólo para expiar,<br/>También para_el pecado eliminar.<br/>Podemos hoy al trono_así llegar,<br/>Ya que quitaste nuestro vil pecar.<br/>Su faz, de Ti el Padre la_apartó,<br/>Tal precio cruel, en gracia se pagó.<br/>',NULL,188786,3);
INSERT INTO stanza VALUES('S88','4','Ahora el camino_abierto está<br/>A pecadores que_oyen Tu llamar.<br/>Nuestro temor eliminaste ya<br/>Al derramar Tu sangre,_ y todo dar;<br/>Recibe_ahora nuestro corazón,<br/>Hallamos nuestra vida_en Ti, Señor.<br/>',NULL,188787,4);
INSERT INTO stanza VALUES('S89','1','Cristo ha resucitado,<br/>A- le-lu-ya!<br/>Victoria_a Su pueblo_ha dado,<br/>A- le-lu-ya!<br/>Vuestros gozos proclamad,<br/>A-le-lu- ya!<br/>Cielos canten, tierra_hablad,<br/>A- le-lu-ya!<br/>',NULL,188788,1);
INSERT INTO stanza VALUES('S89','2','Vive_en gloria el Rey ungido,<br/>Aleluya!<br/>Y la muerte_El ha vencido,<br/>Aleluya!<br/>Al morir El nos salvó,<br/>Aleluya!<br/>Del sepulcro nos libró,<br/>Aleluya!<br/>',NULL,188789,2);
INSERT INTO stanza VALUES('S89','3','Redención El consumó,<br/>Aleluya!<br/>La batalla El ganó,<br/>Aleluya!<br/>Muerte_en vano resistió,<br/>Aleluya!<br/>A los cielos ascendió,<br/>Aleluya!<br/>',NULL,188790,3);
INSERT INTO stanza VALUES('S89','4','Con el Rey pronto_estaremos,<br/>Aleluya!<br/>La Cabeza seguiremos,<br/>Aleluya!<br/>A la gloria celestial,<br/>Aleluya!<br/>Libres de lo terrenal,<br/>Aleluya!<br/>',NULL,188791,4);
INSERT INTO stanza VALUES('S90','1','¡Cristo ha resucitado!<br/>Nuestra Cabeza triunfó;<br/>¡Aleluya! Dadle gloria,<br/>Cristo la muerte venció.<br/>Con consuelo lo_adoramos<br/>Al aparecer Su luz,<br/>Y gozosos nos postramos<br/>Con sentida gratitud.<br/>',NULL,188792,1);
INSERT INTO stanza VALUES('S90','chorus','¡Cristo ha resucitado!<br/>Nuestra Cabeza triunfó;<br/>¡Aleluya! Dadle gloria,<br/>Cristo la muerte venció.<br/>',NULL,188793,2);
INSERT INTO stanza VALUES('S90','2','¡Cristo ha resucitado!<br/>Toda pena ya pasó;<br/>Levantado_en vida nueva<br/>En Su gloria Èl entró.<br/>Todo el Hades y la muerte<br/>Se postraron a Sus pies;<br/>Hoy corona de la gloria<br/>En Sus sienes lleva_el Rey.<br/>',NULL,188794,3);
INSERT INTO stanza VALUES('S90','3','¡Cristo ha resucitado!<br/>Nada nos cautivará,<br/>Pues en Cristo_eternamente<br/>Triunfaremos sobre el mal.<br/>Ya las dudas y temores<br/>No_entrarán al corazón;<br/>Levantados, celebremos,<br/>Hoy Su gran resurrección.<br/>',NULL,188795,4);
INSERT INTO stanza VALUES('S91','1','Aleluya, ¡levantado!<br/>Cristo_al cielo ascendió;<br/>Claman ángeles y hombres:<br/>"Vive en resurrección".<br/>//Levantado, levantado,<br/>Muerte_y Hades Él venció.//<br/>',NULL,188796,1);
INSERT INTO stanza VALUES('S91','2','Aleluya, ¡levantado!<br/>¡La Cabeza Cristo es!<br/>El Espíritu confirma:<br/>Él es Abogado fiel.<br/>//Levantado, levantado,<br/>Somos justos ante Él//<br/>',NULL,188797,2);
INSERT INTO stanza VALUES('S91','3','Aleluya, ¡levantado!<br/>¿Dónde, muerte, tu_aguijón?<br/>La resurrección es Cristo;<br/>Del sepulcro nos libró.<br/>//Levantado, levantado,<br/>A reinar viene_el Señor.//<br/>',NULL,188798,3);
INSERT INTO stanza VALUES('S92','1','Resucitó: pena mortal quitó,<br/>Pues con Su sangre Cristo nos compró;<br/>Resucitó: no hay más condenación,<br/>Pues el sepulcro_está vacío hoy.<br/>',NULL,188799,1);
INSERT INTO stanza VALUES('S92','2','Resucitó: con Él nos levantó;<br/>A todo enemigo ya venció;<br/>Resucitó: nuestra victoria es<br/>La vida de resurrección en Él.<br/>',NULL,188800,2);
INSERT INTO stanza VALUES('S92','3','Resucitó: ya Dios nos redimió;<br/>Pasamos por la senda que_Él trazó;<br/>Resucitó: podemos contemplar<br/>Al Padre_en el Santísimo Lugar.<br/>',NULL,188801,3);
INSERT INTO stanza VALUES('S92','4','Resucitó:_el Señor en gloria está;<br/>Queremos verlo_y no pecar ya más;<br/>Resucitó: triunfante grito_habrá:<br/>"¡Venciste y tenemos libertad!"<br/>',NULL,188802,4);
INSERT INTO stanza VALUES('S93','1','Fuiste_a la muerte Tú<br/>Solo Señor;<br/>Te quiso retener,<br/>¡No lo logró!<br/>La muerte y su poder<br/>Se quiso interponer,<br/>Mas derrotada fue<br/>¡Venciste Tú!<br/>',NULL,188803,1);
INSERT INTO stanza VALUES('S93','2','Brotaste en triunfal<br/>Resurrección;<br/>La muerte se postró,<br/>¡No te_apresó!<br/>Lazos de oscuridad<br/>Rompiste en verdad;<br/>¡Muerte_y sepulcro atrás!<br/>¡Venciste Tú!<br/>',NULL,188804,2);
INSERT INTO stanza VALUES('S93','3','¡Qué triufos, oh Señor,<br/>Lograste Tú!<br/>Frutos recibe Dios<br/>Por Tu virtud.<br/>De Tu muerte salió<br/>Viviente multitud;<br/>Si, todos Tuyos son,<br/>Viven en Ti.<br/>',NULL,188805,3);
INSERT INTO stanza VALUES('S93','4','Tú_el Primogénito<br/>De la creación;<br/>Supremo_al Padre, Tú;<br/>¡Damos loor!<br/>Eres el principal,<br/>Tú,_el tema eternal<br/>Digno de alabar;<br/>¡Digno_eres Tu!<br/>',NULL,188806,4);
INSERT INTO stanza VALUES('S94','1','La tumba le encerró,<br/>Cristo, mi Cristo;<br/>El alba allí esperó,<br/>Cristo el Señor.<br/>',NULL,188807,1);
INSERT INTO stanza VALUES('S94','chorus','Cristo la tumba venció,<br/>Y con gran poder resucitó;<br/>Del sepulcro y muerte<br/>Cristo es vencedor,<br/>Vive para siempre<br/>Nuestro Salvador;<br/>¡Gloria a Dios!<br/>¡Gloria a Dios!<br/>El Señor resucitó.<br/>',NULL,188808,2);
INSERT INTO stanza VALUES('S94','2','De guardas escapó,<br/>Cristo, mi Cristo;<br/>El sello destruyó,<br/>Cristo el Señor.<br/>',NULL,188809,3);
INSERT INTO stanza VALUES('S94','3','La muerte dominó,<br/>Cristo, mi Cristo;<br/>Y su poder venció,<br/>Cristo el Señor.<br/>',NULL,188810,4);
INSERT INTO stanza VALUES('S95','1','¡Gloria al Cristo victorioso!<br/>¡La victoria Él ganó!<br/>¡El pecado fue juzgado,<br/>¡Plena redención logró!<br/>¡Destruyó_el poder maligno,<br/>Por la cruz en que triunfó!<br/>',NULL,188811,1);
INSERT INTO stanza VALUES('S95','2','¡Gloria al Cristo levantado,<br/>A quien Dios resucitó!<br/>¡Anulando Él la muerte,<br/>Al hombre vida le dio!<br/>¡Hades, tinieblas vencidos,<br/>Su poder Él exhibió!<br/>',NULL,188812,2);
INSERT INTO stanza VALUES('S95','3','¡Gloria al Cristo ascendido!<br/>¡Dios al trono lo alzó!<br/>¡Sobre todo señorío,<br/>Nombre supremo le dio!<br/>¡Para echar al enemigo,<br/>Todo poder se le dio!<br/>',NULL,188813,3);
INSERT INTO stanza VALUES('S95','4','¡Gloria al Cristo victorioso!<br/>¡En el Calvario triunfó!<br/>Aleluya, levantado,<br/>Su victoria exhibió!<br/>¡Ascendido, aleluya!<br/>¡Reinará sin conclusión!<br/>',NULL,188814,4);
INSERT INTO stanza VALUES('S96','1','¡Aleluya a Jesucristo!<br/>¡Cetro_y trono Suyos son!<br/>¡Aleluya por Su triunfo!<br/>¡La victoria es del Señor!<br/>Cantan hoy Sus redimidos<br/>Como_estruendo a una voz:<br/>"Nos salvó de toda  tribu,<br/>Con Su sangre nos compró".<br/>',NULL,188815,1);
INSERT INTO stanza VALUES('S96','2','¡Aleluya! Ya no estamos<br/>En tristeza y orfandad.<br/>¡Aleluya! Cuán cercano,<br/>Al creer sin preguntar!<br/>Aunque_al cielo fue tomado,<br/>Y la nube le ocultó,<br/>No_olvidamos Su promesa:<br/>"Con vosotros siempre estoy."<br/>',NULL,188816,2);
INSERT INTO stanza VALUES('S96','3','¡Aleluya! Pan del cielo,<br/>A la tierra El bajó;<br/>¡Aleluya!_A los hambrientos<br/>Es de gran satisfacción.<br/>Redentor y Abogado,<br/>Intercede Él por mí,<br/>Frente_al Dios Omnipotente,<br/>Paz eterna_encuentro así.<br/>',NULL,188817,3);
INSERT INTO stanza VALUES('S96','4','¡Aleluya a Jesucristo!<br/>¡Cetro_y trono Suyos son!<br/>¡Aleluya por Su triunfo!<br/>¡La victoria es del Señor!<br/>Cantan hoy Sus redimidos<br/>Como_estruendo a una voz:<br/>"Nos salvó de toda  tribu,<br/>Con Su sangre nos compró".<br/>',NULL,188818,4);
INSERT INTO stanza VALUES('S97','1','Las naciones se reúnen<br/>E_imaginan vanidad.<br/>Todo reino_y principado<br/>Contra Dios opuesto está.<br/>"Sus cadenas hoy rompamos,<br/>Toda cuerda_hay que cortar".<br/>Esto traman contra Cristo,<br/>El Ungido de Jehová.<br/>',NULL,188819,1);
INSERT INTO stanza VALUES('S97','2','Quien se sienta en los cielos<br/>De_ellos pronto se reirá;<br/>En Su_enojo_e ira_ardiente,<br/>Él los ha de aterrar.<br/>Tiene Dios al Rey ungido<br/>Sobre_el monte santo, Sión.<br/>A los reyes les advierte<br/>La declaración de Dios.<br/>',NULL,188820,2);
INSERT INTO stanza VALUES('S97','3','Les declara_el cristo_ungido<br/>Lo que Dios ya decretó:<br/>"Este dia te_he_engendrado,<br/>Primogénito de Dios.<br/>Como Tu herencia propia,<br/>Las naciones te daré.<br/>Las quebrantará Tu vara,<br/>Excelente_ungido Rey".<br/>',NULL,188821,3);
INSERT INTO stanza VALUES('S97','4','Gobernantes de la tierra,<br/>Oigan la_amonestación:<br/>Tomen al Señor y tiemblen,<br/>Sírvanle con gozo hoy.<br/>Tienen que besar al Hijo,<br/>Y no enojar a Dios.<br/>Todos los que_en Él confían,<br/>Gozarán de bendición.<br/>',NULL,188822,4);
INSERT INTO stanza VALUES('S97','5','Hemos visto al Ungido.<br/>Te_alabamos, Dios de_amor,<br/>Y, besando a tu Hijo,<br/>Nuestra vanidad cesó.<br/>No "los que la ley hoy guardan"<br/>Mas "los que confían en Él",<br/>Son benditos para siempre<br/>Por haber creído_en Él.<br/>',NULL,188823,5);
INSERT INTO stanza VALUES('S98','1','Cantando alabanzas<br/>De gloria al Señor,<br/>Se_alegrarán los cielos<br/>Oyendo nuestra voz;<br/>Si_escucha todo_el mundo<br/>Que damos gloria_a Dios,<br/>Satán y sus legiones<br/>Huirán con gran pavor.<br/>',NULL,188824,1);
INSERT INTO stanza VALUES('S98','2','Cerrando nuestras bocas,<br/>El diablo sonreirá;<br/>¿Por qué no abrir batalla<br/>Y_hacerlo claudicar?<br/>Con gritos de alabanzas,<br/>Victoria y loor,<br/>Hay que perder la cara,<br/>Ser necios para Dios.<br/>',NULL,188825,2);
INSERT INTO stanza VALUES('S98','3','El mundo nunca_ayuda<br/>Para_adorar a Dios,<br/>Ni_a darle_a_El las gracias,<br/>O gloria_al Salvador.<br/>No hay que pedir permiso<br/>Para_alabar a Dios,<br/>Tu_espíritu libera,<br/>Recibe Su favor.<br/>',NULL,188826,3);
INSERT INTO stanza VALUES('S98','4','Hermanos, ¡no se callen!<br/>Hermanas, ¡griten más!<br/>El triunfo resonante<br/>De Dios se_escuchará.<br/>Es tiempo de_alabarlo,<br/>A cualquier precio hoy,<br/>Por Su misericordia<br/>Y plena salvación.<br/>',NULL,188827,4);
INSERT INTO stanza VALUES('S99','1','Es la iglesia proclamando:<br/>¡Cristo es Señor!<br/>Y los santos anunciando:<br/>¡Cristo es Señor!<br/>Toda Su_obra_ha completado;<br/>A Satán ha derrotado;<br/>En el trono_está sentado,<br/>¡Cristo el Señor!<br/>',NULL,188828,1);
INSERT INTO stanza VALUES('S99','2','Es Espíritu viviente,<br/>¡Cristo el Señor.<br/>Accesible a la gente,<br/>¡Cristo el Señor!<br/>Por favor no te lamentes,<br/>Clama hasta que_en ti entre;<br/>Y te sostendrá por siempre,<br/>¡Cristo el Señor!<br/>',NULL,188829,2);
INSERT INTO stanza VALUES('S99','3','El transformará tu vida,<br/>¡Cristo el Señor.<br/>Y la_hará tan bendecida,<br/>¡Cristo el Señor!<br/>Sus riquezas hoy son tuyas<br/>Por la vida que_en ti fluya;<br/>Uno con Dios, ¡aleluya!<br/>¡Cristo es Señor!<br/>',NULL,188830,3);
INSERT INTO stanza VALUES('S99','4','Nos mostró misericordia,<br/>¡Cristo el Señor!<br/>Nunca más habrá discordia,<br/>¡Cristo es Señor!<br/>Por Su magnitud inmensa<br/>Que Su Cuerpo aquí expresa,<br/>A Su enemigo apresa<br/>¡Cristo el Señor!<br/>',NULL,188831,4);
INSERT INTO stanza VALUES('S100','1','¡Tu nombre, qué_excelente es<br/>En la tierra, oh Señor!<br/>Que toda lengua y nación<br/>Proclamen su valor.<br/>Fundaste fuerza y loor<br/>De la boca_infantil,<br/>Para callar a Satanás<br/>Y_acelerar su fin.<br/>',NULL,188832,1);
INSERT INTO stanza VALUES('S100','2','Al contemplar los cielos que<br/>Tu manó_así formó,<br/>La luna_y las estrellas mil<br/>Que Tu plan diseñó,<br/>¿Qué es el hombre para que<br/>Tú te acuerdes de‿él?<br/>Y el hijo de hombre a quien<br/>Tú visitaste fiel?<br/>',NULL,188833,2);
INSERT INTO stanza VALUES('S100','3','Tú eres, oh Señor Jesús,<br/>Aquel que se_humanó,<br/>Quien con la carne se vistió<br/>Sufriendo_humillación;<br/>Mas coronado fuiste ya<br/>Con gloria y honor<br/>Y por Tu Cuerpo todo‿está<br/>Bajo Tus pies, Señor.<br/>',NULL,188834,3);
INSERT INTO stanza VALUES('S100','4','Vemos aquí Tu encarnación<br/>Y la resurrección,<br/>Tu señorío_y reino con<br/>Tu Cuerpo en ascensión.<br/>Por estos pasos, oh Señor,<br/>Fundaste así loor;<br/>Con rebozante corazón<br/>Alzamos nuestra voz.<br/>',NULL,188835,4);
INSERT INTO stanza VALUES('S100','5','¡En breve el día llegará,<br/>Tal dicho se oirá!<br/>Mas en la iglesia hoy está<br/>Un presabor real.<br/>¡Tu nombre, qué_excelente es<br/>En la tierra, oh Señor!<br/>Que toda lengua y nación<br/>Proclamen su valor.<br/>',NULL,188836,5);
INSERT INTO stanza VALUES('S101','1','Estamos rebosando<br/>Con la palabra buena,<br/>De nuestra experiencia<br/>Con nuestro amado Rey.<br/>Con lengua como pluma<br/>De ágil escribiente,<br/>Narramos las delicias<br/>De nuestro Novio fiel.<br/>',NULL,188837,1);
INSERT INTO stanza VALUES('S101','2','Jesús, el más hermoso<br/>De los hijos de hombres;<br/>Con Tu bondad trasciendes<br/>¡Aleluya! Amén!<br/>Se derramó_en Tus labios<br/>Tan abundante gracia,<br/>Por eso te bendijo<br/>El Dios de Israel.<br/>',NULL,188838,2);
INSERT INTO stanza VALUES('S101','3','Tú eres el Valiente,<br/>Cabalgas en victoria;<br/>En gloria majestuosa<br/>Triunfantemente vas.<br/>Bajo de Ti los pueblos<br/>Caerán por Tus conquistas;<br/>Tus saetas agudas<br/>Pasaron por Satán.<br/>',NULL,188839,3);
INSERT INTO stanza VALUES('S101','4','Tu trono,_oh Dios, por siempre<br/>Perdurará inmutable;<br/>Y_el cetro de Tu reino<br/>Firme en la tierra está.<br/>Con óleo de alegría<br/>El Dios Tuyo te ungió<br/>Más que a Tus compañeros.<br/>Grande es Tu dignidad!<br/>',NULL,188840,4);
INSERT INTO stanza VALUES('S101','5','Mirra, áloe y casia<br/>Exhalan Tus vestidos,<br/>Ellos van prediciendo<br/>Muerte y resurrección.<br/>En todas las iglesias<br/>(Palacios de marfil),<br/>Los santos te alaban<br/>Con grande exaltación.<br/>',NULL,188841,5);
INSERT INTO stanza VALUES('S102','1','La reina a Tu diestra<br/>Vestida de_oro_está;<br/>Las hijas de los reyes:<br/>Tu séquito nupcial.<br/>La_iglesia con su gloria,<br/>Igual al Rey será;<br/>Los santos, las mujeres,<br/>Tu_imagen llevarán.<br/>',NULL,188842,1);
INSERT INTO stanza VALUES('S102','2','Oh, considera, hija,<br/>Tu_oído_inclina_aquí:<br/>Olvida_aun tu pueblo,<br/>Lo tuyo deja ir.<br/>Mirando tu hermosura,<br/>Te deseará el Rey;<br/>Su dignidad te_inspira<br/>A adorarlo_a Él.<br/>',NULL,188843,2);
INSERT INTO stanza VALUES('S102','3','Gloriosa es la hija;<br/>En su morada_está;<br/>Brocado de_oro viste,<br/>Que la_hace resaltar;<br/>Con la naturaleza<br/>De la gloria de Dios,<br/>Ella en vida muestra<br/>Su ser tan santo hoy.<br/>',NULL,188844,3);
INSERT INTO stanza VALUES('S102','4','Con vestidos bordados<br/>Será llevada_al Rey;<br/>Con su traje de lino<br/>Se_exhibirá_ante Él.<br/>Al ser bordado Cristo<br/>En todo nuestro ser,<br/>Con ropas tan gloriosas,<br/>Se nos llevará_al Rey.<br/>',NULL,188845,4);
INSERT INTO stanza VALUES('S102','5','¡Qué alegría_y gozo<br/>Al ver a nuestro Rey!<br/>Siempre lo_alabaremos,<br/>Pues sólo digno_es Él.<br/>Si se_exalta_a la reina<br/>O se adora_al Rey,<br/>En todo_este disfrute<br/>La gloria_es para Él.<br/>',NULL,188846,5);
INSERT INTO stanza VALUES('S103','1','Dios, levántate triunfante,<br/>Los que te odian huirán;<br/>Como cera ante_el fuego<br/>Los impíos destruirás.<br/>Mas los justos, tan gloriosos,<br/>Con triunfante voz, gozosos,<br/>Continúan alabando,<br/>Alabando a su Dios.<br/>',NULL,188847,1);
INSERT INTO stanza VALUES('S103','2','Cabalgando en el desierto,<br/>A sus santos cuidará;<br/>A los huérfanos es Padre,<br/>Y_un refugio de verdad<br/>En Su santa_habitación:<br/>¡Qué grandiosa salvación!<br/>¡Aleluya, aleluya!<br/>¡Aleluya, amén!<br/>',NULL,188848,2);
INSERT INTO stanza VALUES('S103','3','El perdido_halló su casa,<br/>Y el afligido, hogar;<br/>Prisioneros libertados,<br/>Gozan hoy prosperidad.<br/>Al rebaño - ¡oh qué gracia! -<br/>Dios los trajo a Su casa;<br/>¡Aleluya, aleluya!<br/>¡Aleluya, amén!<br/>',NULL,188849,3);
INSERT INTO stanza VALUES('S103','4','El Señor las buenas nuevas<br/>Manda con triunfal poder;<br/>Las mujeres las propagan:<br/>"¡A los reyes venció Él!"<br/>Sin afán hoy disfrutamos<br/>Del botín que heredamos;<br/>¡Aleluya, aleluya!<br/>¡Aleluya, amén!<br/>',NULL,188850,4);
INSERT INTO stanza VALUES('S103','5','Ved al Cristo ascendido,<br/>Los cautivos Él llevó;<br/>Él los constituye dones<br/>Para Su habitación.<br/>¡Somos hoy los transformados<br/>Santos que_Él ha conquistado!<br/>¡Aleluya, aleluya!<br/>¡Aleluya, amén!<br/>',NULL,188851,5);
INSERT INTO stanza VALUES('S103','6','Bendecid a Dios por siempre;<br/>Diariamente salva Él<br/>Al colmarnos con Él mismo;<br/>¡Proclamadlo por doquier!<br/>Él la muerte ha vencido,<br/>Derrotando_al enemigo;<br/>¡Aleluya, aleluya!<br/>¡Aleluya, amén!<br/>',NULL,188852,6);
INSERT INTO stanza VALUES('S103','7','Ellos vieron Tus salidas<br/>En Tu santa_habitación;<br/>Y, con júbilo, alaban<br/>Tu triunfante procesión.<br/>Los cantores van delante<br/>Con un gozo resonante.<br/>¡Aleluya, aleluya!<br/>¡Aleluya, amén!<br/>',NULL,188853,7);
INSERT INTO stanza VALUES('S103','8','Benjamín, el joven, guía;<br/>A la diestra_está, de Dios;<br/>Con Judá y compañía,<br/>Ved el cetro del León.<br/>Zabulón y Neftalí,<br/>Buenas nuevas dan allí.<br/>¡Aleluya, aleluya!<br/>¡Aleluya, amén!<br/>',NULL,188854,8);
INSERT INTO stanza VALUES('S103','9','Santos, vuestra fortaleza<br/>Desde_el templo se_ordenó;<br/>¡Oh, que Dios hoy fortalezca<br/>Lo que Él ya realizó!<br/>Alabemos hasta_el día<br/>Que la tierra_en eco diga:<br/>¡Aleluya, aleluya!<br/>¡Aleluya, amén!<br/>',NULL,188855,9);
INSERT INTO stanza VALUES('S104','1','¡Ved, los reinos de este mundo<br/>Son el reino del Señor!<br/>¡Qué disfrute a los santos<br/>Trae Su eterno reino hoy!<br/>Proclamemos como estruendo<br/>Su alabanza a una voz:<br/>¡Victoria se ganó!<br/>',NULL,188856,1);
INSERT INTO stanza VALUES('S104','chorus','¡Qué victoria, aleluya!<br/>¡Qué victoria, aleluya!<br/>¡Qué victoria, aleluya!<br/>¡Victoria se ganó!<br/>',NULL,188857,2);
INSERT INTO stanza VALUES('S104','2','El dragón, esa serpiente,<br/>Satanás, lanzado fue,<br/>Y sus ángeles caídos<br/>Ya no pueden pretender;<br/>Todas nuestras alabanzas<br/>Como_un trueno sonarán:<br/>¡Victoria se ganó!<br/>',NULL,188858,3);
INSERT INTO stanza VALUES('S104','3','Ya llegó la salvación, el reino<br/>Y el poder de Dios;<br/>Pues lanzado de los cielos<br/>Fue el malvado acusador;<br/>Hoy la autoridad de Cristo<br/>A la_iglesia se le dio.<br/>¡Victoria se ganó!<br/>',NULL,188859,4);
INSERT INTO stanza VALUES('S104','4','Por la sangre del Cordero<br/>Se venció al acusador;<br/>"Hecho está!", testificamos,<br/>Declarando con fervor;<br/>Despreciando hasta la muerte<br/>Nuestras almas para Dios.<br/>¡Victoria se ganó!<br/>',NULL,188860,5);
INSERT INTO stanza VALUES('S104','5','Oh hermanos y hermanas,<br/>Escuchad la fuerte voz:<br/>"Ha caído Babilonia!"<br/>Aleluya, gloria_a Dios!<br/>¡Qué benditos! pues salimos<br/>De_ella por nuestra elección.<br/>¡Victoria se ganó!<br/>',NULL,188861,6);
INSERT INTO stanza VALUES('S104','6','Misteriosa Babilonia;<br/>"Madre de rameras" es;<br/>¡Todas sus fornicaciones<br/>Debemos aborrecer!<br/>La juzgó Dios doblemente,<br/>¡Oh, qué gozó a nuestro ser!<br/>¡Victoria se ganó!<br/>',NULL,188862,7);
INSERT INTO stanza VALUES('S104','7','¡Aleluya! Gloria y honra<br/>Son de Dios, nuestro Señor;<br/>Verdaderos son Sus juicios<br/>Sobre la ramera hoy;<br/>Al ver como sube su_humo<br/>Canten "Aleluya!!"_a Dios.<br/>¡Victoria se ganó!<br/>',NULL,188863,8);
INSERT INTO stanza VALUES('S104','8','Escuchad todos Sus siervos,<br/>"Alabad a nuestro Dios!"<br/>Como voz de muchas aguas,<br/>Proclamamos en unión:<br/>¡Aleluya, aleluya,<br/>Reina_el poderoso Dios!<br/>¡Victoria se ganó!<br/>',NULL,188864,9);
INSERT INTO stanza VALUES('S104','9','¡Alegrémonos, gocémonos!<br/>¡Qué gloria hoy se ve!<br/>Pues las bodas del Cordero<br/>Ya se_anuncian por doquier;<br/>Lino fino trae la Novia,<br/>Limpia_y pura en todo es.<br/>¡Victoria se ganó!<br/>',NULL,188865,10);
INSERT INTO stanza VALUES('S104','10','En el lago ardiendo_en fuego<br/>Juan al diablo divisó;<br/>¡Aleluya, somos salvos<br/>De su vil provocación!<br/>Y los santos le recuerdan<br/>Que Dios ya lo condenó.<br/>¡Victoria se ganó!<br/>',NULL,188866,11);
INSERT INTO stanza VALUES('S104','11','Qué suprema maravilla:<br/>La Nueva Jerusalén!<br/>Es la mezcla de los hombres<br/>Con el Triuno Dios también<br/>Es la Novia preparada<br/>Y_adornada para El.<br/>¡Victoria se ganó!<br/>',NULL,188867,12);
INSERT INTO stanza VALUES('S104','12','He aquí el tabernáculo<br/>De Dios por fin está;<br/>Por el hombre manifiesta Dios<br/>Su gloria y santidad;<br/>¡Hecho está! Hermanos, vean<br/>¡Cuán gloriosa es la Ciudad!<br/>¡Victoria se ganó!<br/>',NULL,188868,13);
INSERT INTO stanza VALUES('S104','chorus','¡Aleluya, aleluya!<br/>¡Aleluya, aleluya!<br/>¡Aleluya, aleluya!<br/>¡Victoria se ganó!<br/>',NULL,188869,14);
INSERT INTO stanza VALUES('S105','1','"Oh siéntate_a Mi diestra",<br/>Dios dijo_a mi Señor;<br/>Estrado de Tus pies ya<br/>Tus enemigos son.<br/>El cetro de Tu fuerza<br/>Te_envía el Dios de Sion,<br/>Para que siempre rijas,<br/>Sobre toda nación.<br/>',NULL,188870,1);
INSERT INTO stanza VALUES('S105','2','Hermoso_es ver el cuadro<br/>De la consagración<br/>Que jóvenes te_ofrecen<br/>En todo su_esplendor.<br/>Serán como_el rocío,<br/>Pues te refrescarán;<br/>Se_han puesto en Tus manos,<br/>Preciosos te serán.<br/>',NULL,188871,2);
INSERT INTO stanza VALUES('S105','3','Juró_el Señor por siempre,<br/>Y nunca cambiará:<br/>Fiel Sacerdote_eterno,<br/>Melquisedec serás.<br/>¡Tú eres sin principio<br/>De días ni final!<br/>De Ti hoy dependemos,<br/>Intercediendo estás.<br/>',NULL,188872,3);
INSERT INTO stanza VALUES('S105','4','Hoy Cristo está_a Tu diestra<br/>Su día ya vendrá;<br/>Quebrantará_a los reyes,<br/>Naciones juzgará.<br/>Arroyo le seremos<br/>Del cual Él beberá;<br/>Redimirá la tierra,<br/>Él alzará Su faz.<br/>',NULL,188873,4);
INSERT INTO stanza VALUES('S105','5','Señor, has ascendido<br/>A la diestra de Dios;<br/>Como Cabeza, todo<br/>A Tus pies sometió.<br/>Oh, Rey y Sacerdote,<br/>Ministras al reinar;<br/>Conquistador glorioso,<br/>A Ti nos damos ya.<br/>',NULL,188874,5);
INSERT INTO stanza VALUES('S106','1','Miles de voces van proclamando<br/>A una voz, "¡Cordero de Dios!".<br/>Miles de santos van respondiendo<br/>Dándole eco a su clamor.<br/>',NULL,188875,1);
INSERT INTO stanza VALUES('S106','2','Resuena el cielo, "¡Gloria al Cordero!",<br/>Todos le rinden esta canción;<br/>Con voz potente participando<br/>En Su eternal adoración.<br/>',NULL,188876,2);
INSERT INTO stanza VALUES('S106','3','Esta alabanza como el incienso<br/>Asciende al trono del Padre Dios;<br/>Todos se inclinan a Jesucristo,<br/>Todas sus mentes una son.<br/>',NULL,188877,3);
INSERT INTO stanza VALUES('S106','4','Por Su consejo_el Padre reclama:<br/>"Dadle al Hijo el mismo honor";<br/>Toda la gloria de Dios el Padre<br/>Expresa el Hijo en Su esplendor.<br/>',NULL,188878,4);
INSERT INTO stanza VALUES('S106','5','Huestes del cielo frente al Cordero,<br/>Por el Espíritu del Señor<br/>Son coronados con luz y gozo,<br/>Para alabar al gran "YO SOY".<br/>',NULL,188879,5);
INSERT INTO stanza VALUES('S106','6','Descansa hoy sin ningún estorbo<br/>La jubilosa nueva creación,<br/>Tan bendecida en Jesucristo<br/>Por Su completa salvación.<br/>',NULL,188880,6);
INSERT INTO stanza VALUES('S106','7','Desborda el cielo con alabanzas<br/>Por la creciente eterna canción;<br/>"¡Amén!" resuena por todo el orbe,<br/>"¡Amén!" responde la creación.<br/>',NULL,188881,7);
INSERT INTO stanza VALUES('S107','1','Hasta lo sumó ascendió el Salvador,<br/>Fue coronado el Cordero de Dios,<br/>Vive y atiende a nuestro clamor<br/>Dios sobre todos a Cristo_exaltó.<br/>',NULL,188882,1);
INSERT INTO stanza VALUES('S107','chorus','¡Dios lo exaltó! ¡Dios lo exaltó!<br/>¡Al que murió, Dios exaltó!<br/>Él de Sus miembros escucha la voz,<br/>Dios sobre todos a Cristo_exaltó.<br/>',NULL,188883,2);
INSERT INTO stanza VALUES('S107','2','Cuando feroces las hondas del mar,<br/>Embravecidas nos quieren tragar,<br/>Mirando_a Cristo, Su mano nos da;<br/>Sobre las olas podemos andar.<br/>',NULL,188884,3);
INSERT INTO stanza VALUES('S107','3','Pueblos muy grandes retándonos van;<br/>Fuertes barreras nos quieren parar;<br/>Las derrumbamos marchando en pos<br/>De_Aquel que Dios hasta_el cielo_exaltó.<br/>',NULL,188885,4);
INSERT INTO stanza VALUES('S107','4','De polo_a polo rigiendo_Él está,<br/>Por las edades Él dominará;<br/>Los victoriosos con Él reinarán,<br/>Y_en Su realeza participarán.<br/>',NULL,188886,5);
INSERT INTO stanza VALUES('S108','1','De gloria coronado está<br/>El Cordero de Dios:<br/>Dios todo Su poder le dio,<br/>Al cielo lo exaltó.<br/>',NULL,188887,1);
INSERT INTO stanza VALUES('S108','2','Él llena el trono celestial,<br/>Suyo_el derecho es;<br/>Del Padre,_objeto de Su_amor,<br/>¡Nuestra canción es Él!<br/>',NULL,188888,2);
INSERT INTO stanza VALUES('S108','3','Nuestra_alabanza_acepta Él<br/>Aunque tan alto_está;<br/>La voz más débil Él oirá;<br/>Su_oído inclinará.<br/>',NULL,188889,3);
INSERT INTO stanza VALUES('S108','4','Cantamos hoy en unidad<br/>¡El Nombre aclamad<br/>De_Aquel que en el trono está!<br/>¡Al Cordero_exaltad!<br/>',NULL,188890,4);
INSERT INTO stanza VALUES('S108','5','A_Aquel que despreciado fue,<br/>Dad gloria y honor;<br/>¡Al encumbrado alabad!<br/>¡Corona se le dio!<br/>',NULL,188891,5);
INSERT INTO stanza VALUES('S109','1','¡Ved a Jesús sentado_en el cielo!<br/>Cristo_el Señor al tronó_ascendió;<br/>Como un hombre fue exaltado,<br/>Con gloria Dios lo coronó.<br/>',NULL,188892,1);
INSERT INTO stanza VALUES('S109','2','Naturaleza humana se puso,<br/>Conforme al plan de Dios Él murió;<br/>Resucitado fue con un cuerpo,<br/>Y como hombre ascendió.<br/>',NULL,188893,2);
INSERT INTO stanza VALUES('S109','3','Dios se humilló en Él en la tierra,<br/>Dios con el hombre así residió;<br/>El hombre en Él al cielo exaltado,<br/>Reconciliado fue con Dios.<br/>',NULL,188894,3);
INSERT INTO stanza VALUES('S109','4','Él como Dios, se unió con el hombre,<br/>Dios en el hombre se expresó;<br/>Él se mezcló con Dios como hombre,<br/>Glorificando al hombre en Dios.<br/>',NULL,188895,4);
INSERT INTO stanza VALUES('S109','5','Vino el Espíritu inclusivo<br/>Desde el glorificado Jesús;<br/>Toda Su obra y Su Persona<br/>Proclama este Espíritu.<br/>',NULL,188896,5);
INSERT INTO stanza VALUES('S109','6','La Iglesia está identificada<br/>Con el glorificado Jesús,<br/>Siendo Sus miembros edificados<br/>Por Su glorioso Espíritu.<br/>',NULL,188897,6);
INSERT INTO stanza VALUES('S109','7','¡Ved en el cielo a un hombre entronado<br/>De todos es ahora Señor;<br/>Dios con Su gloria lo ha coronado,<br/>Este es Jesús, el Salvador.<br/>',NULL,188898,7);
INSERT INTO stanza VALUES('S110','1','¡Señor de todos! Oh Jesús,<br/>Lleno de gloria estás;<br/>Renombrado por Tu poder,<br/>Corona_y majestad.<br/>',NULL,188899,1);
INSERT INTO stanza VALUES('S110','2','Dios en la tierra hombre fue,<br/>Humilde Servidor;<br/>Un hombre en Dios en los cielos<br/>De todos es Señor.<br/>',NULL,188900,2);
INSERT INTO stanza VALUES('S110','3','Como hombre en la gloria estás,<br/>Tu Dios te entronó;<br/>Todo poder en los cielos<br/>Y en la tierra te dio.<br/>',NULL,188901,3);
INSERT INTO stanza VALUES('S110','4','Dios a los cielos te exaltó,<br/>¡Qué nombre se te dio!<br/>A Ti todos se inclinarán,<br/>Te llamarán Señor.<br/>',NULL,188902,4);
INSERT INTO stanza VALUES('S110','5','Señor y Cristo te hizo Dios,<br/>Su Espíritu afirmó<br/>El trono de la Majestad<br/>Que compartes con Dios.<br/>',NULL,188903,5);
INSERT INTO stanza VALUES('S110','6','Señor de gloria eres Tú,<br/>Te alzamos hoy canción;<br/>De todos eres el Señor,<br/>Digno de adoración.<br/>',NULL,188904,6);
INSERT INTO stanza VALUES('S111','1','Mirando_al Señor en gloria,<br/>Le adoramos en la luz,<br/>Do se ve la bella_historia<br/>Del oprobio en la cruz.<br/>',NULL,188905,1);
INSERT INTO stanza VALUES('S111','2','Marcas de oscura_afrenta<br/>La corona_en Ti dejó;<br/>Lo profundo de Tu pena<br/>Se expresa_en gloria hoy.<br/>',NULL,188906,2);
INSERT INTO stanza VALUES('S111','3','En la cruz desamparado,<br/>Sin un rasgo de piedad;<br/>Mas ahora está en el trono<br/>Donde todos lo_honrarán.<br/>',NULL,188907,3);
INSERT INTO stanza VALUES('S111','4','¿Por Dios fuiste_abandonado?<br/>¿Escondió Su faz de Ti?<br/>Fue Tu rostro maltratado,<br/>Más hoy gloria se ve_allí.<br/>',NULL,188908,4);
INSERT INTO stanza VALUES('S111','5','Al mirarte te_adoramos,<br/>Santo y precioso Señor;<br/>"Sólo el Cordero es digno":<br/>Lo afirma la creación.<br/>',NULL,188909,5);
INSERT INTO stanza VALUES('S111','6','Bendecido sea el Padre,<br/>Con incensante canción;<br/>Eternales aleluyas<br/>Para_el Hijo_y Padre son.<br/>',NULL,188910,6);
INSERT INTO stanza VALUES('S112','1','¡El nombre de Jesús load!<br/>Señor de todos es;<br/>Postrados homenaje dad<br/>Y coronadlo Rey.<br/>Postrados homenaje dad<br/>Y coronadlo Rey.<br/>',NULL,188911,1);
INSERT INTO stanza VALUES('S112','2','Vosotros, santos del Señor<br/>Que redimió la grey,<br/>//Al que por gracia os salvó<br/>Hoy coronadlo Rey.//<br/>',NULL,188912,2);
INSERT INTO stanza VALUES('S112','3','El nombre excelso anunciad<br/>Con celestial poder;<br/>//Al que podemos invocar,<br/>Hoy coronadlo Rey.//<br/>',NULL,188913,3);
INSERT INTO stanza VALUES('S112','4','Los redimidos se verán<br/>En gloria a Sus pies;<br/>//Con ellos todos hoy cantad<br/>Y coronadlo Rey.//<br/>',NULL,188914,4);
INSERT INTO stanza VALUES('S113','1','¡El nombre de Jesús load!<br/>Oh hueste celestial,<br/>La real diadema hoy traed,<br/>',NULL,188915,1);
INSERT INTO stanza VALUES('S113','chorus','Y cononad a Cristo<br/>¡Coronadlo Rey!<br/>',NULL,188916,2);
INSERT INTO stanza VALUES('S113','2','Dad gloria, mártires de Dios<br/>Debajo del altar,<br/>Al vástago de Isaí,<br/>',NULL,188917,3);
INSERT INTO stanza VALUES('S113','3','Linaje de David, load<br/>Al que_él llamó "Señor":<br/>Divino hombre, humano Dios,<br/>',NULL,188918,4);
INSERT INTO stanza VALUES('S113','4','Vosotros, hijos de Israel,<br/>Los que Él redimió,<br/>Dad gloria_a_Aquel que os salvó,<br/>',NULL,188919,5);
INSERT INTO stanza VALUES('S113','5','Oh redimidos, no olvidéis,<br/>Su amor y compasión;<br/>Trofeos traigan a Sus pies,<br/>',NULL,188920,6);
INSERT INTO stanza VALUES('S113','6','Que toda tribu, lengua_y nación<br/>Del mundo_en derredor,<br/>Le rindan toda majestad,<br/>',NULL,188921,7);
INSERT INTO stanza VALUES('S113','7','Hoy con el coro celestial,<br/>Canción de triunfo_y fe<br/>Cantadle por la_eternidad,<br/>',NULL,188922,8);
INSERT INTO stanza VALUES('S114','1','¡El nombre de Jesús load!<br/>Oh, hueste celestial,<br/>Oh, hueste celestial,<br/>La real diadema hoy traed,<br/>',NULL,188923,1);
INSERT INTO stanza VALUES('S114','chorus','Y coronad a Cristo<br/>Rey de reyes para siempre,<br/>Siempre, siempre<br/>¡Sobre todos es Señor!<br/>',NULL,188924,2);
INSERT INTO stanza VALUES('S114','2','Vosotros, hijos de Israel,<br/>Los que Él redimió,<br/>Los que Él redimió,<br/>Dad gloria_a_Aquel que os salvó,<br/>',NULL,188925,3);
INSERT INTO stanza VALUES('S114','3','Oh, redimidos, no olvidéis<br/>Su amor y compasión,<br/>Su amor y compasión;<br/>Trofeos traigan a Sus pies,<br/>',NULL,188926,4);
INSERT INTO stanza VALUES('S114','4','Que toda tribu, lengua_y nación<br/>Del mundo en derredor,<br/>Del mundo en derredor,<br/>Le rindan toda majestad,<br/>',NULL,188927,5);
INSERT INTO stanza VALUES('S114','5','Hoy con el coro celestial,<br/>Canción de triunfo y fe,<br/>Canción de triunfo y fe,<br/>Cantadle por la eternidad,<br/>',NULL,188928,6);
INSERT INTO stanza VALUES('S115','1','¡Ved al Varón de dolores!<br/>¡Qué visión gloriosa es!<br/>Vuelve de la lucha_invicto;<br/>Todos ríndanse_ante Él.<br/>¡Coronadlo! ¡Coronadlo!<br/>¡Coronadlo_invicto Rey!<br/>',NULL,188929,1);
INSERT INTO stanza VALUES('S115','2','¡Ángeles, hoy coronadlo!<br/>Sus trofeos exhibió;<br/>Suene_el cielo entronando<br/>Con poder al Salvador.<br/>¡Coronadlo! ¡Coronadlo!<br/>¡Salvador e_invicto Rey!<br/>',NULL,188930,2);
INSERT INTO stanza VALUES('S115','3','Con escarnio, con espinas<br/>Coronaron al Señor;<br/>Mas los santos hoy alaban<br/>Ese nombre de valor.<br/>¡Coronadlo! ¡Coronadlo!<br/>Proclamad Su fama hoy.<br/>',NULL,188931,3);
INSERT INTO stanza VALUES('S115','4','¡Escuchad triunfante voces!<br/>Bulle fuerte_aclamación,<br/>Fue Jesús enaltecido<br/>A suprema posición.<br/>¡Coronadlo! ¡Coronadlo!<br/>¡Rey de reyes y Señor!<br/>',NULL,188932,4);
INSERT INTO stanza VALUES('S116','1','Jesús, de_espinas coronado,<br/>Con gloria_ahora_estás;<br/>Tú eres hoy el Victorioso<br/>En plena majestad.<br/>',NULL,188933,1);
INSERT INTO stanza VALUES('S116','2','Para los santos, luz Tú eres<br/>Y gozo sin igual;<br/>¡Oh, manifiéstanos Tu_amor<br/>En su profundidad!<br/>',NULL,188934,2);
INSERT INTO stanza VALUES('S116','3','Tu cruz con toda su vergüenza<br/>Y gracia se nos dio;<br/>Tu nombre_aquí fue renegado,<br/>Mas Dios lo exaltó.<br/>',NULL,188935,3);
INSERT INTO stanza VALUES('S116','4','Señor, quien sufra hoy contigo,<br/>Contigo reinará;<br/>Por eso_el precio pagaremos<br/>Hasta_en Tu gozo entrar.<br/>',NULL,188936,4);
INSERT INTO stanza VALUES('S116','5','La cruz que fue Tu muerte y pena,<br/>Nos es vida y salud;<br/>Nuestro presente gozo y gloria<br/>Es por su gran virtud.<br/>',NULL,188937,5);
INSERT INTO stanza VALUES('S117','1','¡Al Rey hoy coronad!<br/>Cordero de mi Dios;<br/>Ahoga‿el canto celestial<br/>Toda otra canción.<br/>Mi alma_ha de cantar<br/>Del que murió por mí,<br/>Y_al Rey divino adorará<br/>Por la eternidad.<br/>',NULL,188938,1);
INSERT INTO stanza VALUES('S117','2','¡Al Hijo coronad!<br/>Al encarnado Dios;<br/>Trofeos las heridas son<br/>Que_en Sus sienes llevó.<br/>Renuevo que brotó,<br/>Del Arbol, fruto es,<br/>Raíz que trajo todo bien,<br/>El niño de Belén.<br/>',NULL,188939,2);
INSERT INTO stanza VALUES('S117','3','¡A Cristo coronad!<br/>Sus manos contemplad;<br/>Bellas heridas que sufrió<br/>Llenas de gloria están.<br/>Ningún ángel podrá<br/>Tal vista penetrar,<br/>Grande señal de eterno amor,<br/>Misterio celestial.<br/>',NULL,188940,3);
INSERT INTO stanza VALUES('S117','4','¡Al que nos trae la paz<br/>Con gloria coronad!<br/>El cetro de Su autoridad<br/>Las guerras detendrá.<br/>Su reino eternal<br/>Alabanzas traerá,<br/>Adorna Sus heridos pies<br/>La gloria eternal.<br/>',NULL,188941,4);
INSERT INTO stanza VALUES('S117','5','¡Al inmortal Señor<br/>Con gozo coronad!<br/>De todo_el orbe_es Creador,<br/>Sublime en majestad.<br/>Excelso Redentor,<br/>Moriste Tú por mí;<br/>Jamás podrá cesar, mi Dios,<br/>La alabanza_a Ti.<br/>',NULL,188942,5);
INSERT INTO stanza VALUES('S118','1','¡En el trono de Su Padre<br/>Se sentó Cristo_el Señor!<br/>Por salvar a pecadores,<br/>Él Su obra completó.<br/>En la gloria, en la gloria,<br/>¡Ved al Hijo_eterno hoy!<br/>',NULL,188943,1);
INSERT INTO stanza VALUES('S118','2','Todos han de arrodillarse<br/>Y Su nombre confesar;<br/>Miles han de adorarle,<br/>¡Él sufrió por mi pecar!<br/>De la gloria, de la gloria,<br/>Dios proclama Su valor.<br/>',NULL,188944,2);
INSERT INTO stanza VALUES('S118','3','Hombre fue, crucificado,<br/>Hombre es el Salvador;<br/>Por el mundo fue juzgado,<br/>¡Satisfizo_al justo Dios!<br/>Por la gloria, por la gloria<br/>Reclamado fue el Señor!<br/>',NULL,188945,3);
INSERT INTO stanza VALUES('S118','4','Hijo de_Hombre, encarnado,<br/>Gracia_al hombre Él brindó;<br/>Del linaje escogido,<br/>Líder es: ¡nueva creación!<br/>Hoy la gloria, hoy la gloria,<br/>Le da el lugar de_honor.<br/>',NULL,188946,4);
INSERT INTO stanza VALUES('S119','1','¡Cristo el Señor es Rey!<br/>Mortales aclamad,<br/>Regocijaos en  Él<br/>Con la canción triunfal:<br/>',NULL,188947,1);
INSERT INTO stanza VALUES('S119','chorus','Alzad la voz,<br/>Alzad el corazón, regocijaos con Dios.<br/>',NULL,188948,2);
INSERT INTO stanza VALUES('S119','2','¡Su reino no caerá!<br/>Las llaves tiene Él<br/>Del Hades infernal<br/>Y de la muerte cruel:<br/>',NULL,188949,3);
INSERT INTO stanza VALUES('S119','3','¡Reinando está Jesús,<br/>El Salvador y Dios!<br/>Las manchas Él purgó<br/>Y el trono Él tomó:<br/>',NULL,188950,4);
INSERT INTO stanza VALUES('S119','4','Se sienta juntó a Dios<br/>Y_espera hasta ver<br/>Postrado a Sus pies<br/>Todo enemigo de Él:<br/>',NULL,188951,5);
INSERT INTO stanza VALUES('S120','1','Señor, Dios te ha_ungido;<br/>De reyes, Tú_eres Rey.<br/>La_adoración que damos<br/>Es canto de Tu grey.<br/>Tu reino es para siempre;<br/>Tu trono, firme es.<br/>Tu reino_y su justicia,<br/>Con gracia_y gloria es.<br/>',NULL,188952,1);
INSERT INTO stanza VALUES('S120','2','En Sion, el monte santo,<br/>Ya Dios te_estableció,<br/>Y todas las naciones<br/>A Ti Dios las legó.<br/>A Ti Dios ha entregado<br/>Total autoridad<br/>Para regir los pueblos<br/>Por la eternidad.<br/>',NULL,188953,2);
INSERT INTO stanza VALUES('S120','3','Señor, antes que vuelvas,<br/>Hay densa oscuridad;<br/>Diez mil voces a diario<br/>Te_aclaman con lealtad.<br/>De costa_a costa_un pueblo<br/>Te sirve y te_es fiel;<br/>¡Te aman y te adoran!<br/>¡Tú, su amado Rey!<br/>',NULL,188954,3);
INSERT INTO stanza VALUES('S120','4','Cuando se cumpla el tiempo,<br/>Con esplendor vendrás;<br/>La tierra y las naciones<br/>Tu reino formarán.<br/>En majestad y gloria,<br/>Oh Rey, te servirán;<br/>Las tribus y los pueblos<br/>Loores te darán.<br/>',NULL,188955,4);
INSERT INTO stanza VALUES('S121','1','Rey de reyes eres Tú,<br/>Nos postramos en Tu luz;<br/>Oh Ungido celestial,<br/>Te_adoramos sin cesar;<br/>De los reyes eres Rey,<br/>Te_ensalzamos en Tu grey.<br/>',NULL,188956,1);
INSERT INTO stanza VALUES('S121','2','Tu poder y autoridad<br/>Por la tierra se verán;<br/>Todos te adorarán,<br/>Frente al trono servirán;<br/>Rey de reyes, en Tu honor,<br/>Ofrecemos hoy loor.<br/>',NULL,188957,2);
INSERT INTO stanza VALUES('S121','3','Es Tu reino celestial,<br/>Y Tu trono eternal;<br/>A Tu gloria y poder<br/>Cantaremos por doquier;<br/>Mas ahora, nuestro Rey,<br/>Te alabamos en la grey.<br/>',NULL,188958,3);
INSERT INTO stanza VALUES('S121','4','Nuestro soberano Rey,<br/>Tu nombre precioso es;<br/>Disfrutamos Tu reinar,<br/>¡Venga el reino en total!<br/>Rey de reyes, hoy aquí<br/>Toda honra_es para Ti.<br/>',NULL,188959,4);
INSERT INTO stanza VALUES('S122','1','Diez mil voces celestiales,<br/>Se_oyen todas a_una voz;<br/>Cristo reina,_el cielo canta:<br/>"Cristo reina,_el Dios de_amor".<br/>Ved, Jesús está_en el trono<br/>Y gobierna_al mundo_Él solo.<br/>',NULL,188960,1);
INSERT INTO stanza VALUES('S122','chorus','Aleluya, aleluya,<br/>Aleluya, amén.<br/>',NULL,188961,2);
INSERT INTO stanza VALUES('S122','2','Canta, que_Él bajó del cielo<br/>Y cargó aquí la cruz;<br/>Recibió poder de lo_alto<br/>Y reina_en gloriosa luz.<br/>Es un tema_inagotable:<br/>Dulce nombre_incomparable.<br/>',NULL,188962,3);
INSERT INTO stanza VALUES('S122','3','Ven Jesús, ven con Tu gloria<br/>Que da_al cielo su valor.<br/>Tu sonrisa nos alumbra,<br/>Nos da ánimo, Señor.<br/>Cuando en Tu_amor pensamos,<br/>¡Tan divino!, te_alabamos.<br/>',NULL,188963,4);
INSERT INTO stanza VALUES('S122','4','Rey de gloria, reina siempre;<br/>Tu corona_eterna es.<br/>Nada de Tu_amor separa<br/>A los que_has de poseer;<br/>Por Tu gracia, ¡qué glorioso!<br/>¡Ellos han de ver Tu rostro!<br/>',NULL,188964,5);
INSERT INTO stanza VALUES('S122','5','Apresura Tu venida,<br/>Salvador, ven a reinar;<br/>En el tiempo señalado,<br/>Cielo y tierra pasarán.<br/>Cantaremos con gran gozo,<br/>Alabando al Rey glorioso.<br/>',NULL,188965,6);
INSERT INTO stanza VALUES('S123','1','Al Rey que viene_alabanzas cantad,<br/>Paz y justicia Su imperio traerá;<br/>Gloria_al Cordero_inmolado en la cruz,<br/>Gozo_a los pueblos al regir Jesús.<br/>',NULL,188966,1);
INSERT INTO stanza VALUES('S123','chorus','Todos cantad al Rey Jesús,<br/>Al Rey Jesús hoy ensalzad;<br/>Esta canción entonad en unión:<br/>Al Rey dad gloria, dad gloria_a Jesús.<br/>',NULL,188967,2);
INSERT INTO stanza VALUES('S123','2','Hará Su cetro brotar la verdad,<br/>Razas cortadas Su amor unirá;<br/>Todos los hombres morando en Su luz,<br/>Fin de los males al regir Jesús.<br/>',NULL,188968,3);
INSERT INTO stanza VALUES('S123','3','Todo lo bueno Su reino tendrá,<br/>Sabiduría y real libertad;<br/>A todo mal vencerá Su virtud,<br/>No habrá más guerras al regir Jesús.<br/>',NULL,188969,4);
INSERT INTO stanza VALUES('S123','4','Conocimiento_y temor del Señor,<br/>Como las aguas del mar han de ser;<br/>Habrá esplendor y perfecta salud,<br/>Dulce armonía al regir Jesús.<br/>',NULL,188970,5);
INSERT INTO stanza VALUES('S123','5','"Venga Tu reino", rogamos, Señor,<br/>Padre, apresura Tu gran resplandor,<br/>Para que apunte el alba su luz,<br/>Y_el diablo caiga al regir Jesús.<br/>',NULL,188971,6);
INSERT INTO stanza VALUES('S124','1','¡Qué profundo, tan extenso<br/>Es, Señor, Tu amor sin par!<br/>Más allá de lo_insondable,<br/>Más profundo que la mar!<br/>Te causó sufrir la muerte,<br/>E_impartir en mí Tu ser;<br/>Tal amor que_a Ti me injerta,<br/>Parte Tuya me_hace ser.<br/>',NULL,188972,1);
INSERT INTO stanza VALUES('S124','2','¿Quién dirá las maravillas<br/>Que logró Tu amor por mí?<br/>La más grande maravilla<br/>Es tenerte siempre_en mí.<br/>Yo Tu ser he recibido<br/>Por completa provisión;<br/>Como vida te disfruto,<br/>Tus riquezas mías son.<br/>',NULL,188973,2);
INSERT INTO stanza VALUES('S124','3','Tu amor, Señor, expresa,<br/>Tu Persona divinal;<br/>A mi vida da sentido,<br/>La_armoniza con Tu plan.<br/>Gracia todo-suficiente,<br/>Cada día es mi porción;<br/>Gusto siempre Tu dulzura,<br/>Y de todo Tu favor.<br/>',NULL,188974,3);
INSERT INTO stanza VALUES('S124','4','¿Qué de Ti podrá apartarme?<br/>¡Hasta el fin me amarás!<br/>¡Oh, qué gran amor tan fuerte<br/>Que nos mezcla_en unidad!<br/>Somos uno para siempre;<br/>¡Mío eres, Tuyo soy!<br/>Este es mi testimonio:<br/>¡Enlazados por Tu amor!<br/>',NULL,188975,4);
INSERT INTO stanza VALUES('S125','1','Bendito Salvador, Tu_amor,<br/>¡Cuán grande_y rico es!<br/>Queremos dedicar a Ti<br/>Nuestro completo ser.<br/>',NULL,188976,1);
INSERT INTO stanza VALUES('S125','2','Te_amamos por el gran valor<br/>Que hemos visto_en Ti;<br/>Te_amamos por sufrir la cruz<br/>Pacientemente allí.<br/>',NULL,188977,2);
INSERT INTO stanza VALUES('S125','3','¡Cuán grande_amor es el morir<br/>Por un amigo fiel!<br/>Mas por Tus enemigos, Tú,<br/>Sufriste lo más cruel.<br/>',NULL,188978,3);
INSERT INTO stanza VALUES('S125','4','Aunque en forma_igual a Dios,<br/>Con gloria celestial,<br/>Te_hiciste un esclavo fiel,<br/>Con pena terrenal.<br/>',NULL,188979,4);
INSERT INTO stanza VALUES('S125','5','Un hombre Tú llegaste_a ser;<br/>Mas sin pecado_en Ti,<br/>Para hacernos como Tú,<br/>En vida y_en vivir.<br/>',NULL,188980,5);
INSERT INTO stanza VALUES('S125','6','Tal como Tú en humildad,<br/>En vida y en amor;<br/>De gloria_en gloria vamos ya<br/>A ver Tu faz, Señor.<br/>',NULL,188981,6);
INSERT INTO stanza VALUES('S125','7','Atesoramos Tu amor<br/>En nuestro corazón;<br/>Tu nombre siempre ha de ser<br/>El más fragante_olor.<br/>',NULL,188982,7);
INSERT INTO stanza VALUES('S126','1','Tu amor, Jesús, excede mi pensar,<br/>Pero mi alma quiere comprobar,<br/>El largo,_el ancho_y la profundidad,<br/>Su altura y fuerza quiere disfrutar<br/>Aún más y más.<br/>',NULL,188983,1);
INSERT INTO stanza VALUES('S126','2','Tu amor, Jesús, excede todo hablar,<br/>Mi Salvador, mas quiero proclamar,<br/>A pecadores en cualquier lugar<br/>Tu amor que puede el temor echar<br/>Con su poder.<br/>',NULL,188984,2);
INSERT INTO stanza VALUES('S126','3','Tu amor, Jesús, excede todo honor,<br/>Pero mi corazón, oh Salvador,<br/>Quiere cantar Tu rico y tierno amor<br/>Que trae a este pobre pecador<br/>Cerca de Dios.<br/>',NULL,188985,3);
INSERT INTO stanza VALUES('S126','4','Aunque Tu amor no pueda comprender,<br/>Hablar, cantar, o_a fondo conocer,<br/>Mi vaso traigo libremente yo<br/>Para que Tú, Fuente de vida, lo<br/>Puedas llenar.<br/>',NULL,188986,4);
INSERT INTO stanza VALUES('S126','5','Un vaso soy, vacío y sin calor,<br/>Jamás te di ni_un rasgo de mi amor,<br/>Mas puedo una y otra vez venir<br/>Con la certeza de saber que_aún<br/>Me amas Tú.<br/>',NULL,188987,5);
INSERT INTO stanza VALUES('S126','6','¡Oh, lléname, Jesús, mi Salvador!<br/>Al manantial me guíes con Tu amor;<br/>Con fe sencilla allí acudiré,<br/>Jamás a otra fuente yo iré,<br/>Mas sólo a Ti.<br/>',NULL,188988,6);
INSERT INTO stanza VALUES('S126','7','Señor, cuando Tu rostro pueda ver<br/>Y en Tu trono pueda comprender<br/>El largo, el ancho_y la profundidad,<br/>La altura y fuerza de Tu amor leal,<br/>Yo cantaré.<br/>',NULL,188989,7);
INSERT INTO stanza VALUES('S127','1','Oh Señor, antes vagamos,<br/>Mas Tu_amor nos encontró;<br/>Nos rodeaste con Tus brazos,<br/>Y moriste,_oh Salvador.<br/>¡Canta, alma! Él te_amó.<br/>Por mi Cristo se_entregó.<br/>',NULL,188990,1);
INSERT INTO stanza VALUES('S127','2','Oh, qué llanto tan amargo<br/>Desde el Getsemaní;<br/>El Señor guarda vigilia<br/>Mientras Pedro duerme_allí.<br/>Alma mía, Él te_amó,<br/>Sí, por mi Jesús se dio.<br/>',NULL,188991,2);
INSERT INTO stanza VALUES('S127','3','Él está hablando_al Padre,<br/>Se rindió para tomar<br/>De_esa copa tan amarga<br/>Para podernos salvar.<br/>¡Oh, qué_amor: Él me amó!<br/>Mi_alma, Él por ti se dio.<br/>',NULL,188992,3);
INSERT INTO stanza VALUES('S127','4','¡Oh, qué_escena de angustia!<br/>Cuando las olas de Dios<br/>Contra Él arremetieron<br/>Y_en la cruz Él me salvó.<br/>¡Qué inmenso_es tal amor!<br/>Por mi Cristo se_entregó.<br/>',NULL,188993,4);
INSERT INTO stanza VALUES('S127','5','¡Otra vez oíd el llanto<br/>Que_en Calvario resonó!<br/>Dios, mi Dios, ¿desamparaste_a<br/>Quien Tu voluntad cumplió?<br/>¡Oh mi alma! fue por ti,<br/>¡Sí! Se dio así por mí.<br/>',NULL,188994,5);
INSERT INTO stanza VALUES('S127','6','Oh Señor, hoy nos gozamos;<br/>Ya no sufres más pesar.<br/>Hasta_el trono ascendiste;<br/>Vives y no mueres más.<br/>¡Mi alma! Vive Él por ti,<br/>Sí, Él se_entregó por mí.<br/>',NULL,188995,6);
INSERT INTO stanza VALUES('S127','7','Te honramos y_adoramos<br/>Por tu gracia_y gran valor;<br/>Cara_a cara te veremos<br/>Ya perfectos, fiel Señor.<br/>Mientras tanto canto_así:<br/>Cristo se_entregó por mí.<br/>',NULL,188996,7);
INSERT INTO stanza VALUES('S128','1','Rey de mi vida, mi Señor,<br/>Yo te corono hoy;<br/>Que nunca_olvide Tu virtud,<br/>Guíame a tu cruz.<br/>',NULL,188997,1);
INSERT INTO stanza VALUES('S128','chorus','Que nunca_olvide tu sufrir,<br/>Ni Tu_agonía al morir,<br/>Ni Tu_infinito_amor por mi,<br/>Guíame a tu cruz.<br/>',NULL,188998,2);
INSERT INTO stanza VALUES('S128','2','Donde yaciste, muéstrame,<br/>Donde se te lloró,<br/>Do vigilaron ángeles,<br/>Do mi Señor durmió.<br/>',NULL,188999,3);
INSERT INTO stanza VALUES('S128','3','Que, cuál María, traiga un don,<br/>Aunque en lobreguez;<br/>La tumba_abierta muéstrame,<br/>Guíame a Tu cruz.<br/>',NULL,189000,4);
INSERT INTO stanza VALUES('S128','4','Por Ti mi cruz deseo llevar<br/>A diario, mi Señor;<br/>La copa_amarga aun tomar,<br/>Siguiéndote_en amor.<br/>',NULL,189001,5);
INSERT INTO stanza VALUES('S128','5','Con Tu deseo lléname<br/>Para llevar Tu luz;<br/>Purga mis labios para_hablar<br/>A todos de Tu cruz.<br/>',NULL,189002,6);
INSERT INTO stanza VALUES('S129','1','Alabanzas y gracias canta la multitud<br/>En presencia de Cristo con gloria_en Su luz.<br/>',NULL,189003,1);
INSERT INTO stanza VALUES('S129','chorus','A Aquel que nos ama y nos perdonó,<br/>A Él sea la gloria y todo_el honor.<br/>',NULL,189004,2);
INSERT INTO stanza VALUES('S129','2','Pecadores tan sucios a los ojos de Dios<br/>Hoy vestidos de lino tan blanco, en unión.<br/>',NULL,189005,3);
INSERT INTO stanza VALUES('S129','3','Del rebelde Él hace_un sacerdote y rey;<br/>Nos compró con Su sangre_y nos trajo a Su grey.<br/>',NULL,189006,4);
INSERT INTO stanza VALUES('S129','4','Miserables, sin fuerzas, en pecado_y temor<br/>Nos buscó y nos lava mostrando Su_amor.<br/>',NULL,189007,5);
INSERT INTO stanza VALUES('S129','5','Nuestras voces con fuerzas alabanzas darán,<br/>Así otros creyendo también cantarán.<br/>',NULL,189008,6);
INSERT INTO stanza VALUES('S130','1','Oh, si tuviera lenguas mil<br/>Para mi Redentor,<br/>Daría glorias a mi Rey<br/>Por Su triunfante_amor.<br/>',NULL,189009,1);
INSERT INTO stanza VALUES('S130','2','Amable Amo y mi Dios,<br/>Aliéntame, Señor,<br/>A propagar por tierra y mar<br/>Tu Nombre_y Tu honor.<br/>',NULL,189010,2);
INSERT INTO stanza VALUES('S130','3','Jesús, Tu Nombre vida da<br/>Y vence el temor,<br/>Trae salvación, salud y paz<br/>A todo pecador.<br/>',NULL,189011,3);
INSERT INTO stanza VALUES('S130','4','Me cautivó Su gran amor,<br/>Cautivo seré yo;<br/>Pues fue vejado y murió,<br/>Y mi alma liberó.<br/>',NULL,189012,4);
INSERT INTO stanza VALUES('S130','5','Rompe_el pecado_y su poder,<br/>Da_al preso libertad;<br/>Hasta_al más vil puede limpiar<br/>Su sangre eficaz.<br/>',NULL,189013,5);
INSERT INTO stanza VALUES('S130','6','Tu Nombre_ahora debo_amar,<br/>Y_hacer Tu voluntad;<br/>Mil corazones, oh Señor,<br/>A Ti quisiera dar.<br/>',NULL,189014,6);
INSERT INTO stanza VALUES('S131','1','Yo cantaré de Cristo,<br/>Mis días coronó<br/>De Sus misericordias;<br/>Reboso bendición.<br/>Yo cantaré de Cristo,<br/>Cordero de mi Dios;<br/>Dio Su preciosa sangre,<br/>Pagó_y me redimió.<br/>',NULL,189015,1);
INSERT INTO stanza VALUES('S131','chorus','Yo cantaré de Cristo<br/>Sentado a Sus pies;<br/>Medito dulcemente<br/>En Su bondad tan fiel;<br/>Yo cantaré de Cristo<br/>En toda adversidad;<br/>Su gracia salvadora<br/>Con Él me guardará.<br/>Su gracia salvadora<br/>Con Él me guardará.<br/>',NULL,189016,2);
INSERT INTO stanza VALUES('S131','2','Yo cantaré de Cristo<br/>Mientras andando voy<br/>Para_alcanzar el reino<br/>Del día_en perfección;<br/>Y cuando logre mi_alma<br/>En tal esfera_entrar,<br/>Le cantaré_alabanzas<br/>Por la eternidad.<br/>',NULL,189017,3);
INSERT INTO stanza VALUES('S132','1','Señor eres precioso,<br/>Muy bello para Dios;<br/>Ungido con aceite,<br/>Su gozo, Su elección.<br/>',NULL,189018,1);
INSERT INTO stanza VALUES('S132','chorus','Señor cuánto apreciamos<br/>Hoy Tu hermosa faz,<br/>Fragancia y dulzura<br/>Con gracia sin igual.<br/>',NULL,189019,2);
INSERT INTO stanza VALUES('S132','2','Eres lo más hermoso<br/>Y bello, mi Señor;<br/>Tus labios vierten gracia;<br/>Conmueves nuestro_amor.<br/>',NULL,189020,3);
INSERT INTO stanza VALUES('S132','3','Los magos te_ofrecieron<br/>Tesoros al nacer;<br/>Te sepultó un noble;<br/>¡Qué hermosa muerte fue!<br/>',NULL,189021,4);
INSERT INTO stanza VALUES('S132','4','Fue_ungida Tu cabeza;<br/>¡Cuán atractivo, Tú!<br/>También Tus pies ungidos<br/>Irradian Tu virtud.<br/>',NULL,189022,5);
INSERT INTO stanza VALUES('S132','5','Tu muerte_es como mirra,<br/>Consuelo_al hombre trae;<br/>Y Tu resurrección hoy<br/>A Dios fragancia da.<br/>',NULL,189023,6);
INSERT INTO stanza VALUES('S132','6','Como la flor de_alheña,<br/>Hermoso es Tu ser;<br/>Como_el manzano_en cierne,<br/>Tu fruto dulce es.<br/>',NULL,189024,7);
INSERT INTO stanza VALUES('S132','7','Mejor que_el dulce vino,<br/>Tu_amor es para mí;<br/>Tu nombre_es como_ungüento,<br/>Y Tú_el banquete_aquí.<br/>',NULL,189025,8);
INSERT INTO stanza VALUES('S132','8','Señor, al contemplarte<br/>Y Tu belleza ver,<br/>Probamos Tu dulzura<br/>Gustando de Tu ser.<br/>',NULL,189026,9);
INSERT INTO stanza VALUES('S133','1','Eres nuestro hermoso Novio,<br/>Dios así te designó;<br/>Atractiva_es Tu persona,<br/>El más bello, Tú, Señor.<br/>',NULL,189027,1);
INSERT INTO stanza VALUES('S133','2','Nuestro_Amado, te_admiramos,<br/>Tu belleza, ¡quién dirá!<br/>Tu amor hoy apreciamos,<br/>Toda Tu preciosidad.<br/>',NULL,189028,2);
INSERT INTO stanza VALUES('S133','3','Más afable que ninguno,<br/>Y más dulce que la miel;<br/>Eres manso y_admirable,<br/>¿A quién te compararé?<br/>',NULL,189029,3);
INSERT INTO stanza VALUES('S133','4','Llevas mirra en Tus ropas,<br/>Y_en Tus labios gracia hay;<br/>En Tu_aroma de Tu pena,<br/>Te_abrazamos sin cesar.<br/>',NULL,189030,4);
INSERT INTO stanza VALUES('S133','5','Con el óleo de alegría<br/>Te ha ungido nuestro Dios;<br/>Y_en palacios de marfiles<br/>Brotará la_adoración.<br/>',NULL,189031,5);
INSERT INTO stanza VALUES('S133','6','Te bendijo Dios por siempre,<br/>En victoria reinarás;<br/>Entronado_estás en gloria<br/>Con poder y majestad.<br/>',NULL,189032,6);
INSERT INTO stanza VALUES('S133','7','Eres Tú de las naciones,<br/>El Deseado de valor;<br/>El mejor de_entre los miles,<br/>Te_ofrecemos nuestro amor.<br/>',NULL,189033,7);
INSERT INTO stanza VALUES('S134','1','Se endulza_el corazón, Señor,<br/>Cuando anhelo ver<br/>Tu gloria_y Tu presencia viva,<br/>Y_arrebatado ser.<br/>',NULL,189034,1);
INSERT INTO stanza VALUES('S134','chorus','Señor, cual linda flor de_alheña,<br/>Que_en viña floreciendo_está,<br/>Incomparable_es Tu  belleza<br/>A nuestro corazón.<br/>',NULL,189035,2);
INSERT INTO stanza VALUES('S134','2','Toda Tu gracia en canción<br/>No se podrá cantar;<br/>Ni_existe un corazón que pueda<br/>Todo Tu amor gozar.<br/>',NULL,189036,3);
INSERT INTO stanza VALUES('S134','3','No es Tu gracia o Tu amor<br/>Que nos deleitará,<br/>Sino Tu mismo Ser amado<br/>Quien nos satisfará.<br/>',NULL,189037,4);
INSERT INTO stanza VALUES('S134','4','Tú, el más dulce_y lo más bello,<br/>No hay comparación;<br/>Eres el único en el mundo,<br/>Que colma_el corazón.<br/>',NULL,189038,5);
INSERT INTO stanza VALUES('S134','note','**Alheña: una planta del Viejo Mundo muy apreciada por sus fragantes flores blancas y amarillas.<br/>',NULL,189039,6);
INSERT INTO stanza VALUES('S135','1','Anhelo respirarte más<br/>Brisa de grato_olor;<br/>Como fragancia celestial,<br/>La flor de alheña_es sin igual,<br/>Un bálsamo de‿amor,<br/>Un bálsamo de‿amor.<br/>',NULL,189040,1);
INSERT INTO stanza VALUES('S135','2','Anhelo contemplarte más,<br/>Hermoso Redentor;<br/>Mi corazón muy lleno está<br/>Mirando Tu gloriosa faz;<br/>//Qué bello resplandor!//<br/>',NULL,189041,2);
INSERT INTO stanza VALUES('S135','3','Anhelo_a Ti rendirme más<br/>Mi Amo,_Amigo, Dios;<br/>Someto a Ti mi voluntad<br/>Para servir sin vacilar<br/>//En santa devoción.//<br/>',NULL,189042,3);
INSERT INTO stanza VALUES('S135','4','Anhelo alabarte más,<br/>Tu nombre_es mi canción;<br/>Con melodía celestial<br/>Mi alma_a Ti cantando está;<br/>//Me alegra el corazón.//<br/>',NULL,189043,4);
INSERT INTO stanza VALUES('S135','5','Anhelo elogiarte más,<br/>Hay mucho que exponer;<br/>Con tanto_amor te quiero hablar<br/>Mas oigo un dulce susurrar:<br/>//"Ten paz, todo está bien".//<br/>',NULL,189044,5);
INSERT INTO stanza VALUES('S136','1','¡Bello Señor Jesús!<br/>¡De este universo el Rey!<br/>¡Tú eres Hijo del Hombre_y Dios!<br/>Siempre te_apreciaré,<br/>Siempre te honraré,<br/>Mi gloria eres Tú, Señor.<br/>',NULL,189045,1);
INSERT INTO stanza VALUES('S136','2','¡Qué bello el campo es!<br/>La floresta más aún,<br/>En su belleza primaveral;<br/>Más bello_es el Señor,<br/>Más puro en Su_amor,<br/>Que hace_al triste ser cantar.<br/>',NULL,189046,2);
INSERT INTO stanza VALUES('S136','3','Bella_es la luz del sol,<br/>Y la luna_en su esplendor,<br/>O las estrellas al centellear;<br/>Jesús es superior,<br/>Brilla con más fulgor<br/>Que luz o ser angelical.<br/>',NULL,189047,3);
INSERT INTO stanza VALUES('S136','4','Belleza terrenal,<br/>Hermosura celestial,<br/>Lo más hermoso es mi Señor;<br/>Excelso_y sin igual,<br/>Y de_un valor sin par,<br/>Es mi querido Salvador.<br/>',NULL,189048,4);
INSERT INTO stanza VALUES('S137','1','Fue coronado_el Salvador<br/>Con gloria_y majestad;<br/>Sus labios fluyen leche_y miel,<br/>Llenos de gracia están.<br/>Llenos de gracia están.<br/>',NULL,189049,1);
INSERT INTO stanza VALUES('S137','2','Ningún mortal hay como Él,<br/>Tan bello, nadie es;<br/>Y en la hueste celestial<br/>//El más hermoso es Él.//<br/>',NULL,189050,2);
INSERT INTO stanza VALUES('S137','3','Mi vida_y todo debo_a Él,<br/>Mi dicha_y mi placer;<br/>Por Él la muerte venceré:<br/>//La tumba_y su poder.//<br/>',NULL,189051,3);
INSERT INTO stanza VALUES('S137','4','Mis pies cansados lleva Él<br/>Al Padre Dios, mi_hogar;<br/>Las glorias de mi Dios allí<br/>//Me hace contemplar.//<br/>',NULL,189052,4);
INSERT INTO stanza VALUES('S137','5','Al recibir de Su caudal<br/>Tal prueba de Su_amor,<br/>Quisiera yo mil veces dar<br/>/Mi vida_a Ti, Señor.//<br/>',NULL,189053,5);
INSERT INTO stanza VALUES('S138','1','¡Mi Cristo colma_el corazón!<br/>Su gloria hay que proclamar.<br/>De Él es nuestra fiel canción,<br/>Por siempre lo_hemos de_alabar;<br/>Y toda lengua cantará<br/>La gloria del Rey celestial.<br/>',NULL,189054,1);
INSERT INTO stanza VALUES('S138','2','Más bello, Tú, que todo ser,<br/>Perfecto_y lleno de virtud;<br/>Tus labios gracia dulce dan,<br/>Tu_amor desborda_en plenitud.<br/>Bendito Dios, hay que decir<br/>Que todo_el bien habita_en Ti.<br/>',NULL,189055,2);
INSERT INTO stanza VALUES('S139','1','¡Al Cristo celestial<br/>Hoy alabanzas dad!<br/>Su nombre_honrad;<br/>Por penas que_Él llevó,<br/>Cielos, dad gloria_a Dios;<br/>¡Digno_el Cordero es!<br/>¡Alabadlo!<br/>',NULL,189056,1);
INSERT INTO stanza VALUES('S139','2','Rodeando_el trono hoy<br/>Con gozo, en unión,<br/>Démosle_honor;<br/>Su sangre nos limpió,<br/>Tenemos paz con Dios.<br/>¡Digno_el Cordero es!<br/>¡Alabadlo!<br/>',NULL,189057,2);
INSERT INTO stanza VALUES('S139','3','Linaje_humano, ven,<br/>Adora_a tu Señor.<br/>Démosle_honor;<br/>Regocijémonos,<br/>Alcemos nuestra voz,<br/>¡Digno_el Cordero es!<br/>¡Alabadlo!<br/>',NULL,189058,3);
INSERT INTO stanza VALUES('S139','4','Nunca_hemos de cesar<br/>Su nombre de_alabar<br/>Y exaltar;<br/>Tributo dadle_a Él,<br/>Nuestro precioso Rey.<br/>¡Digno_el Cordero es!<br/>¡Alabadlo!<br/>',NULL,189059,4);
INSERT INTO stanza VALUES('S140','1','Señor Jesús, te_adoramos con gozo,<br/>Y_hasta Tu trono alzamos canción;<br/>Hoy bendecidos a Ti confesamos<br/>Que sólo Tú eres digno de honor.<br/>',NULL,189060,1);
INSERT INTO stanza VALUES('S140','chorus','Tú eres digno; Tú eres digno;<br/>Tú eres digno, muy digno, Señor;<br/>Hoy, bendecidos, a Ti confesamos<br/>Que sólo Tú eres digno de_honor.<br/>',NULL,189061,2);
INSERT INTO stanza VALUES('S140','2','Tú eres Dios, mas llegaste_a ser hombre,<br/>No como un_ángel moriste_en la cruz,<br/>Para_aplastar la antigua serpiente,<br/>De la mujer la simiente_eres Tú.<br/>',NULL,189062,3);
INSERT INTO stanza VALUES('S140','3','Te humillaste y fuiste clavado<br/>Por Tus criaturas un día_en la cruz;<br/>Aún por Dios siendo desamparado,<br/>La maldición no rehuiste Tú.<br/>',NULL,189063,4);
INSERT INTO stanza VALUES('S140','4','Tú has triunfado, triunfado con gloria,<br/>Ondas de muerte pudiste aplastar;<br/>Nadie podrá acallar esa_historia,<br/>Sobre_el sepulcro invicto Tú_estás.<br/>',NULL,189064,5);
INSERT INTO stanza VALUES('S141','1','Canta la triunfante iglesia:<br/>¡Cordero fiel!<br/>Todo_el cielo_así resuena,<br/>¡Digno es Él!<br/>Sea poder o principado,<br/>A Sus pies arrodillados,<br/>Como incienso entonando:<br/>¡Cordero fiel!<br/>',NULL,189065,1);
INSERT INTO stanza VALUES('S141','2','Todo pueblo y toda lengua,<br/>¡Cordero fiel!<br/>Cantan: ¡Salvación eterna!<br/>¡Digno es Él!<br/>Como_estruendo poderoso,<br/>En diluvio tan coloso<br/>Le adoran victoriosos,<br/>¡Cordero fiel!<br/>',NULL,189066,2);
INSERT INTO stanza VALUES('S141','3','Suenan arpas y canciones:<br/>¡Cordero fiel!<br/>Mucha gracia_en transgresiónes,<br/>¡Digno es Él!<br/>Por Su sangre redimidos,<br/>A Su grey nos ha traído,<br/>En Su gloria bendecidos,<br/>¡Cordero fiel!<br/>',NULL,189067,3);
INSERT INTO stanza VALUES('S141','4','Con expectación cantamos:<br/>¡Cordero fiel!<br/>Jubilosos proclamamos:<br/>¡Digno es Él!<br/>Cánticos incomparables<br/>Sobre_el terna insondable<br/>Del anuncio inefable:<br/>¡Cordero fiel!<br/>',NULL,189068,4);
INSERT INTO stanza VALUES('S142','1','Eres Tú, Jesús, muy digno<br/>De_alabanzas y honor;<br/>Por Tu_amor, bondad y gracia<br/>Te rendimos hoy loor.<br/>',NULL,189069,1);
INSERT INTO stanza VALUES('S142','2','Te_adoramos por Tu nombre<br/>Desde nuestro corazón:<br/>Proclamamos a todo_hombre<br/>Tu piedad y gran valor.<br/>',NULL,189070,2);
INSERT INTO stanza VALUES('S142','3','¡Alabadlo! ¡Alabadlo,<br/>Santos, todos a_una voz!<br/>Hasta que, con Él en gloria,<br/>Le cantemos Su loor.<br/>',NULL,189071,3);
INSERT INTO stanza VALUES('S143','1','Con canto_alegre hoy venid<br/>Al trono celestial;<br/>Miles de voces, entonad<br/>El tema singular.<br/>',NULL,189072,1);
INSERT INTO stanza VALUES('S143','2','¡Digno_el Cordero que_ascendió<br/>Para_exaltado ser!<br/>¡Digno_el Cordero que murió!<br/>Sufrió por nuestro bien.<br/>',NULL,189073,2);
INSERT INTO stanza VALUES('S143','3','Jesús es deigno de_aceptar<br/>Gloria, poder y honor;<br/>Por siempre se le cantará<br/>Con toda bendición.<br/>',NULL,189074,3);
INSERT INTO stanza VALUES('S143','4','Los santos pronto,_en ascención,<br/>Un himno cantarán;<br/>Y los que en la tierra estén<br/>Tu gloria_anunciarán.<br/>',NULL,189075,4);
INSERT INTO stanza VALUES('S143','5','La redimida creación<br/>Adora_el nombre fiel<br/>De_Aquel que en el trono está,<br/>Y_al Cordero también.<br/>',NULL,189076,5);
INSERT INTO stanza VALUES('S144','1','Resonamos aleluyas<br/>Hoy a Ti, Señor;<br/>¡Imposible es rendirte<br/>Digna_adoración!<br/>',NULL,189077,1);
INSERT INTO stanza VALUES('S144','chorus','¡Al Cordero alabemos<br/>Por la eternidad!<br/>¡Aleluya! ¡Aleluya!<br/>¡Amén! ¡Alabad!<br/>',NULL,189078,2);
INSERT INTO stanza VALUES('S144','2','¡Alabemos al Cordero!<br/>¡Él nos redimió!<br/>¡Sacerdotes Él nos hizo,<br/>Reyes para Dios!<br/>',NULL,189079,3);
INSERT INTO stanza VALUES('S144','3','¡Aleluya! Jesucristo,<br/>No cesas de_amar;<br/>Tuyos somos para siempre:<br/>Uno en verdad.<br/>',NULL,189080,4);
INSERT INTO stanza VALUES('S144','4','¡Alabadlo! ¡Aleluya!<br/>¿Quién nos callará?<br/>Santos de todos los pueblos,<br/>A_una voz cantad.<br/>',NULL,189081,5);
INSERT INTO stanza VALUES('S145','1','Los santos por los siglos<br/>Adoran al Señor<br/>Que salva del pecado:<br/>El Cordero de Dios;<br/>Mas raramente_alzamos<br/>Loores al León,<br/>Aunque alabemos mucho<br/>Por nuestra redención.<br/>',NULL,189082,1);
INSERT INTO stanza VALUES('S145','2','Lloró Juan al notar que<br/>Nadie era capaz<br/>De_abrir el rollo_eterno<br/>Del misterio de Dios;<br/>Ninguno_en tierra_o cielo,<br/>Ninguno_alrededor;<br/>Si no hubiera_un digno,<br/>¡Oh, qué lamentación!<br/>',NULL,189083,2);
INSERT INTO stanza VALUES('S145','3','Sería_un gran misterio<br/>El universo hoy,<br/>Sin alguien que_abra_el rollo<br/>Y muestre_el plan de Dios;<br/>Mas, para_abrir los sellos<br/>Y el rollo revelar,<br/>El Digno ha vencido:<br/>El León de Judá.<br/>',NULL,189084,3);
INSERT INTO stanza VALUES('S145','4','Ya no se_encuentra_oculta<br/>La voluntad de Dios;<br/>Se nos ha revelado<br/>Esta clara visión;<br/>Nos damos para esto<br/>Con todo_el corazón;<br/>Gozosos, alabamos<br/>Al Cordero-León.<br/>',NULL,189085,4);
INSERT INTO stanza VALUES('S145','5','Los venticuatro_ancianos<br/>Se postran frente_a Él,<br/>Y los seres vivientes<br/>Lo_alaban siempre fiel;<br/>Juntemos nuestras voces<br/>Para rendir loor<br/>Al que abrió el rollo:<br/>El Cordero-León.<br/>',NULL,189086,5);
INSERT INTO stanza VALUES('S146','1','Muy rico eres, oh Señor,<br/>Tu_amor nos lo revela;<br/>Tu ser inescrutable hoy<br/>Nuestro_espíritu llena.<br/>',NULL,189087,1);
INSERT INTO stanza VALUES('S146','2','Tu eres la Palabra_y Dios,<br/>Con Dios desde_el principio;<br/>Como_hombre te_encarnaste Tú<br/>Para_a Dios definirnos.<br/>',NULL,189088,2);
INSERT INTO stanza VALUES('S146','3','El tabernáculo_eres Tú,<br/>Con la divina gloria;<br/>También el templo para Dios,<br/>En Ti está Su_historia.<br/>',NULL,189089,3);
INSERT INTO stanza VALUES('S146','4','Como_Unigénito de Dios,<br/>El Padre declaraste;<br/>Así Su vida eternal<br/>Y_esencia nos legaste.<br/>',NULL,189090,4);
INSERT INTO stanza VALUES('S146','5','Como_Hijo de_Hombre llevas Tú<br/>Nuestra naturaleza,<br/>Para llevar hijos a Dios<br/>Con Tu_estatura plena.<br/>',NULL,189091,5);
INSERT INTO stanza VALUES('S146','6','Eres el Cristo y_el Señor,<br/>Por Dios fuiste ungido;<br/>El todo_en todos eres Tú;<br/>De Dios, el Escogido.<br/>',NULL,189092,6);
INSERT INTO stanza VALUES('S146','7','Crucificado Salvador,<br/>Sangre_y agua vertiste;<br/>Tu vida_entró en nuestro ser,<br/>También nos redimiste.<br/>',NULL,189093,7);
INSERT INTO stanza VALUES('S146','8','Glorificado_estás, Jesús,<br/>Como_Espíritu vienes;<br/>Este_inclusivo_Espíritu<br/>Tu mérito hoy tiene.<br/>',NULL,189094,8);
INSERT INTO stanza VALUES('S146','9','La luz de vida eres Tú,<br/>Brillando_en nuestras sombras;<br/>Resplandeciendo_así con Dios,<br/>En nuestro ser Tú obras.<br/>',NULL,189095,9);
INSERT INTO stanza VALUES('S146','10','Como la vida divinal<br/>Nuestro_espíritu_avivas;<br/>De toda muerte libras Tú,<br/>Y nuestro ser animas.<br/>',NULL,189096,10);
INSERT INTO stanza VALUES('S146','11','Eres la realidad de Dios,<br/>Verdad que_a Dios complace;<br/>Ella nos trae Tu mismo ser,<br/>Así nos satisface.<br/>',NULL,189097,11);
INSERT INTO stanza VALUES('S146','12','La senda de la vida, Tú<br/>Nos llevas a la gloria;<br/>La senda de Tu realidad<br/>Apremia la victoria.<br/>',NULL,189098,12);
INSERT INTO stanza VALUES('S146','13','Tú eres la resurrección<br/>Que traga toda muerte;<br/>Podemos hoy llevar la cruz<br/>Por su poder tan fuerte.<br/>',NULL,189099,13);
INSERT INTO stanza VALUES('S146','14','Cordero_inmaculado, Tú<br/>La redención lograste;<br/>Al darnos Tu Espíritu,<br/>Tú nos regeneraste.<br/>',NULL,189100,14);
INSERT INTO stanza VALUES('S146','15','Serpiente de bronce_eres Tú,<br/>Que salva del pecado;<br/>Te levantaron en la cruz<br/>Para_aplastar al diablo.<br/>',NULL,189101,15);
INSERT INTO stanza VALUES('S146','16','Eres la puerta y_el Pastor<br/>Que del redil nos saca.<br/>Por Ti gozamos libertad;<br/>En pastos Tú nos sacias.<br/>',NULL,189102,16);
INSERT INTO stanza VALUES('S146','17','Como_el lavacro_en su función,<br/>Muy limpios nos mantienes;<br/>Así, andando_en comunión,<br/>Gozamos de Tus bienes.<br/>',NULL,189103,17);
INSERT INTO stanza VALUES('S146','18','Hendida roca celestial,<br/>Tú fluyes agua viva;<br/>Bebemos de_este manantial<br/>Que sacia con Tu vida.<br/>',NULL,189104,18);
INSERT INTO stanza VALUES('S146','19','Eres el pozo celestial,<br/>Siempre con agua viva;<br/>Bebemos Tu vida_eternal<br/>Que nuestra sed termina.<br/>',NULL,189105,19);
INSERT INTO stanza VALUES('S146','20','El pan del cielo eres Tú,<br/>Nos nutres con Tu vida;<br/>Por Tu_abundancia divinal<br/>Nuestro_espíritu_animas.<br/>',NULL,189106,20);
INSERT INTO stanza VALUES('S146','21','Aliento de vida_eres Tú,<br/>Y_en nuestro ser te soplas;<br/>Viviendo y andando_en Ti,<br/>Tu_herencia nos otorgas.<br/>',NULL,189107,21);
INSERT INTO stanza VALUES('S146','22','Grano de trigo divinal,<br/>por muerte,_en gloria entraste;<br/>Formando muchos granos, Tú<br/>El Cuerpo_así formaste.<br/>',NULL,189108,22);
INSERT INTO stanza VALUES('S146','23','Eres la verdadera vid,<br/>Los pámpanos, nosotros;<br/>Morando mutuamente_así,<br/>Nos das Tu suministro.<br/>',NULL,189109,23);
INSERT INTO stanza VALUES('S146','24','Eres el Novio celestial<br/>Que va_a tomar la novia,<br/>Para contigo uno ser<br/>En vida,_amor y gloria.<br/>',NULL,189110,24);
INSERT INTO stanza VALUES('S146','25','Tú, la_escalera de Jacob,<br/>Por Ti se_abren los cielos;<br/>En Ti somos casa de Dios,<br/>Cielos y tierra_unidos.<br/>',NULL,189111,25);
INSERT INTO stanza VALUES('S146','26','Señor, Tú como el gran "Yo Soy"<br/>Nuestra_escasez hoy llenas;<br/>Por ser el todo_en todos, Tú<br/>El plan de Dios consumas.<br/>',NULL,189112,26);
INSERT INTO stanza VALUES('S147','1','Hijo de Dios eres, Señor,<br/>Su expresión perfecta;<br/>En Ti nos habla nuestro Dios<br/>En forma tan completa.<br/>',NULL,189113,1);
INSERT INTO stanza VALUES('S147','2','Tu eres nuestro mismo Dios,<br/>Su resplandor de gloria;<br/>La_imagen de Su_interno ser,<br/>En Ti está Su_historia.<br/>',NULL,189114,2);
INSERT INTO stanza VALUES('S147','3','Hiciste_el universo, Tú,<br/>Y por Ti él subsiste;<br/>Dios Su_heredero te nombró;<br/>Todo lo recibiste.<br/>',NULL,189115,3);
INSERT INTO stanza VALUES('S147','4','Purgaste los pecados, Tú,<br/>Y_al cielo ascendiste;<br/>La voluntad de Dios harás;<br/>Todo rival venciste.<br/>',NULL,189116,4);
INSERT INTO stanza VALUES('S147','5','Tu nombre sobre todos es,<br/>De Dios lo heredaste;<br/>En el Espíritu hoy, Tú<br/>El Hijo de Dios eres.<br/>',NULL,189117,5);
INSERT INTO stanza VALUES('S147','6','Tu reino, de justicia es;<br/>Tu trono_es para siempre;<br/>Dios te ha_ungido en amor;<br/>Tú nunca envejeces.<br/>',NULL,189118,6);
INSERT INTO stanza VALUES('S147','7','Como hombre tienes Tú también<br/>Naturaleza humana;<br/>Gustaste muerte Tú por mí;<br/>De Ti la vida emana.<br/>',NULL,189119,7);
INSERT INTO stanza VALUES('S147','8','Corona de gloria y_honor,<br/>Todo_a Ti está sujeto;<br/>El Capitán de salvación,<br/>Perfecto_en sufrimientos.<br/>',NULL,189120,8);
INSERT INTO stanza VALUES('S147','9','Tu muerte destruyó a Satán,<br/>Y de_ella nos libraste;<br/>En vida santificarás,<br/>A gloria nos llamaste.<br/>',NULL,189121,9);
INSERT INTO stanza VALUES('S147','10','Has dado_a Tus hermanos hoy<br/>El nombre de Tu Padre;<br/>Y en la_iglesia cantas Tú<br/>Para que_en Ti lo_alaben.<br/>',NULL,189122,10);
INSERT INTO stanza VALUES('S147','11','Más que Moisés, tan superior,<br/>Apóstol con más gloria;<br/>Como a la casa_el constructor<br/>Es digno de más honra.<br/>',NULL,189123,11);
INSERT INTO stanza VALUES('S147','12','Eres nuestro real Josué,<br/>Por Ti_al descanso entramos;<br/>Nuestra completa salvación,<br/>Nuestra fe_en Ti hallamos.<br/>',NULL,189124,12);
INSERT INTO stanza VALUES('S147','13','Tú, el descanso celestial,<br/>Hoy en nosotros moras;<br/>Para_a la buena tierra_entrar<br/>Y heredarla toda.<br/>',NULL,189125,13);
INSERT INTO stanza VALUES('S147','14','También más digno que Aarón,<br/>La misma ofrenda eres;<br/>Entraste_al cielo para ser<br/>Tal Sumo Sacerdote.<br/>',NULL,189126,14);
INSERT INTO stanza VALUES('S147','15','Eres nuestro Melquisedec<br/>Que vida_y fuerza tienes;<br/>Con vino_y pan ministras Tú<br/>Y siempre nos sostienes.<br/>',NULL,189127,15);
INSERT INTO stanza VALUES('S147','16','Nuestro sacrificio mejor<br/>Por el Espíritu_eres;<br/>La_ofrenda única a Dios<br/>Que mérito hoy tiene.<br/>',NULL,189128,16);
INSERT INTO stanza VALUES('S147','17','Lograste un pacto superior<br/>Con tu preciosa sangre;<br/>El nuevo testamento_así<br/>Por nosotros ganaste.<br/>',NULL,189129,17);
INSERT INTO stanza VALUES('S147','18','Del pacto,_eres el Hacedor,<br/>Pues mérito Tu tienes;<br/>Hoy tal herencia nuestra es,<br/>Pues el Dador Tú eres.<br/>',NULL,189130,18);
INSERT INTO stanza VALUES('S147','19','El Albacea_y Mediador<br/>Del pacto hoy Tú eres;<br/>Tú cumples la_elección de Dios<br/>Y nuestra vida eres.<br/>',NULL,189131,19);
INSERT INTO stanza VALUES('S147','20','Tú eres nuestro Precursor<br/>Que_estás dentro del velo;<br/>Tu vida nos hace salir<br/>Fuera del campamento.<br/>',NULL,189132,20);
INSERT INTO stanza VALUES('S147','21','Autor y el Consumador<br/>De la fe verdadera,<br/>Nos sujetamos en amor<br/>A Ti con fe sincera.<br/>',NULL,189133,21);
INSERT INTO stanza VALUES('S147','22','Inigualado_eres, Jesús,<br/>Nuestro_único tesoro;<br/>Completo y perfecto, Tú,<br/>Precioso más que_el oro.<br/>',NULL,189134,22);
INSERT INTO stanza VALUES('S148','1','El Hijo amado eres,<br/>La imagen del gran Dios;<br/>Porción para los santos,<br/>Tu sangre la ganó.<br/>El Primogénito eres<br/>De toda creación,<br/>Por Ti fue creado todo<br/>Para Tu posesión.<br/>',NULL,189135,1);
INSERT INTO stanza VALUES('S148','2','A todo Tú precedes<br/>Y todo existe en Ti;<br/>De todo eres el centro,<br/>Subsiste todo así.<br/>El Primogénito eres<br/>De entre los muertos, Tú,<br/>Y de la iglesia, el Cuerpo,<br/>Cabeza y virtud.<br/>',NULL,189136,2);
INSERT INTO stanza VALUES('S148','3','La plenitud completa<br/>En Ti morando está,<br/>Tienes la preeminencia<br/>Que_en todo se verá.<br/>Reconciliaste todo<br/>Por Tu sangre, Señor,<br/>Para santificados<br/>Llevarnos ante Dios.<br/>',NULL,189137,3);
INSERT INTO stanza VALUES('S148','4','De Dios, misterio eres,<br/>Y_en Ti Su plenitud<br/>Está con los tesoros:<br/>Sabiduría y luz.<br/>Tú eres la esperanza<br/>De gloria_en nuestro ser,<br/>En Ti perfectos somos<br/>Y_a Dios Su gran placer.<br/>',NULL,189138,4);
INSERT INTO stanza VALUES('S148','5','Todo_en verdad es sombra<br/>Que nos da_a conocer<br/>La realidad del Cristo<br/>Que vive_en nuestro ser.<br/>Nos llenan Tus riquezas<br/>Hasta Tu plenitud,<br/>Tu Cuerpo va creciendo<br/>Con Dios en magnitud.<br/>',NULL,189139,5);
INSERT INTO stanza VALUES('S148','6','Contigo nuestra vida<br/>Está_escondida_en Dios;<br/>Tu paz preside_ahora<br/>En nuestro corazón.<br/>En el nuevo_hombre eres,<br/>El todo_en todos Tú;<br/>El Salvador del Cuerpo,<br/>Tu novia y plenitud.<br/>',NULL,189140,6);
INSERT INTO stanza VALUES('S149','1','Señor, considerándote,<br/>Por todo lo que eres Tú,<br/>Te adoramos,   te admiramos,<br/>Por Tus riquezas y virtud.<br/>',NULL,189141,1);
INSERT INTO stanza VALUES('S149','chorus','¡Lo que eres llena mi escasez!<br/>¡Reboso de_alabanza a Ti!<br/>Excedes todos mis anhelos,<br/>Me satisfaces siempre_a mí.<br/>',NULL,189142,2);
INSERT INTO stanza VALUES('S149','2','Tú eres Dios mismo_en verdad,<br/>El Dios que_es nuestra luz y amor;<br/>El Dios que siempre_es nuestra vida,<br/>El Dios que disfrutamos hoy.<br/>',NULL,189143,3);
INSERT INTO stanza VALUES('S149','3','Hombre genuino eres también,<br/>Un hombre tan puro y cabal;<br/>Un hombre_en quien Dios se complace,<br/>Y nuestro amor puede ganar.<br/>',NULL,189144,4);
INSERT INTO stanza VALUES('S149','4','Humilde_esclavo para Dios,<br/>Tú nos viniste a servir;<br/>Hasta la muerte obediente,<br/>La libertad nos diste así.<br/>',NULL,189145,5);
INSERT INTO stanza VALUES('S149','5','Tú eres además un Rey,<br/>Que reina_en vida y_en amor;<br/>Con Su poder Dios te ha_ungido,<br/>Para de todos ser Señor.<br/>',NULL,189146,6);
INSERT INTO stanza VALUES('S149','6','Señor, al recordarte a Ti,<br/>Te disfrutamos en amor;<br/>Y lo que eres compartimos<br/>Como Tu complemento hoy.<br/>',NULL,189147,7);
INSERT INTO stanza VALUES('S150','1','Tú, Señor, naciste como<br/>La simiente de mujer<br/>Para_hollar a Tu_enemigo<br/>Y victoria obtener.<br/>Siendo Dios, te encarnaste<br/>Para Tu sangre verter;<br/>Por Tu muerte aplastaste<br/>La serpiente_y su poder.<br/>',NULL,189148,1);
INSERT INTO stanza VALUES('S150','2','De_Abraham, la descendecia,<br/>La cual Dios nos prometió;<br/>Tú, a todas las naciones<br/>Les serás por bendición.<br/>Antes de_Abraham, Tú eres,<br/>Pues eres el gran "Yo Soy",<br/>Mas te_hiciste su simiente,<br/>Nuestro Cordero de Dios.<br/>',NULL,189149,2);
INSERT INTO stanza VALUES('S150','3','De David, la descendencia,<br/>Quien el reino estableció;<br/>En el trono Dios te_ha puesto<br/>Y Tú_harás Su_habitación.<br/>"Hijo de David" Tú eres,<br/>Mas él te llamó "Señor";<br/>Eres su raíz y fuente<br/>De todos eres Señor.<br/>',NULL,189150,3);
INSERT INTO stanza VALUES('S150','4','Aunque "un niño es nacido",<br/>El "Dios Fuerte" se llamó;<br/>Aunque_"un Hijo" nos es dado,<br/>"Padre_Eterno" se nombró.<br/>Todas las promesas dadas<br/>Por fe_en Ti son realidad;<br/>Eres "Sí" y_"Amén" a ellas,<br/>Contenido y final.<br/>',NULL,189151,4);
INSERT INTO stanza VALUES('S151','1','Venimos hoy a Ti,<br/>Fiel hombre,_Hijo de Dios;<br/>Subsiste todo_en Ti,<br/>Autor de vida, Tú:<br/>Hoy sólo_en Ti vivimos y<br/>Tenemos todo nuestro ser.<br/>',NULL,189152,1);
INSERT INTO stanza VALUES('S151','2','Tú, el camino_a Dios<br/>Nos diste redención;<br/>En Tí, no hay temor<br/>Al ver a nuestro Juez.<br/>Absueltos hoy, delante de<br/>Tu trono_estamos, por Tu_amor.<br/>',NULL,189153,2);
INSERT INTO stanza VALUES('S151','3','¡Verdad viviente, Tú!<br/>Sabiduria real,<br/>Fuente de todo don,<br/>¡La eternal verdad!<br/>¡El gran Yo Soy! ¡Reposo real!<br/>Respuesta_a todo mi afán.<br/>',NULL,189154,3);
INSERT INTO stanza VALUES('S151','4','Tú eres, oh Señor,<br/>La vida de verdad:<br/>Vida_abundante que<br/>La tierra no nos da;<br/>¡Resucitó nuestro Señor!<br/>¡Morada mutua somos hoy!<br/>',NULL,189155,4);
INSERT INTO stanza VALUES('S151','5','Recibe_adoración<br/>Señor, Rey, Salvador;<br/>Nuestra fuerza y vigor<br/>Te damos con loor;<br/>¡Oh, llénanos! ¡Que por nuestro<br/>Vivir ganes a otros hoy!<br/>',NULL,189156,5);
INSERT INTO stanza VALUES('S152','1','Señor, el todo_en todo Tú,<br/>¡Lo máximo en verdad!<br/>Lo que_eres nos satisfará,<br/>Cualquier necesidad.<br/>Te_adora nuestro_espíritu,<br/>Te_aprecia_el corazón;<br/>Al contemplar Tu rico ser<br/>Te damos bendición.<br/>',NULL,189157,1);
INSERT INTO stanza VALUES('S152','2','Tú, el Profeta_eres de Dios<br/>Que hablas con poder;<br/>Como Moisés, nos diste_el plan<br/>De Dios a conocer.<br/>Como Jonás, Dios te envió,<br/>De muerte_a vida_entrar,<br/>Para poder creer en Ti<br/>Por esta gran señal.<br/>',NULL,189158,2);
INSERT INTO stanza VALUES('S152','3','Como_hombre, Dios te levantó,<br/>Profeta con gran luz,<br/>Como_Eliseo en amor<br/>Milagros haces Tú.<br/>Como Isaías, haces ver<br/>Al Cristo sin igual;<br/>Nos das Tu misma vida_así,<br/>Tan rica_y tan real.<br/>',NULL,189159,3);
INSERT INTO stanza VALUES('S152','4','El santo Sacerdote, Tú,<br/>Que lleva el hombre a Dios;<br/>Tal como_Aarón, quien Dios llamó,<br/>Nos sirves con amor.<br/>Oh, Sumo Sacerdote fiel,<br/>Intercediendo estás,<br/>Y nos preservas con poder,<br/>Guardándonos en paz.<br/>',NULL,189160,4);
INSERT INTO stanza VALUES('S152','5','Tu eres Sacerdote real,<br/>Nuestro Melquisedec,<br/>A quien Dios manda_a ministrar<br/>Como_el Rey de Salem.<br/>Tú sacias con el vino_y pan<br/>Nuestra necesidad;<br/>Nos traes a Dios para que de_Él<br/>Podamos disfrutar.<br/>',NULL,189161,5);
INSERT INTO stanza VALUES('S152','6','Tú eres Rey, como David,<br/>Que busca sólo_a Dios;<br/>Luchando por Su interés,<br/>Tú cumples Su_intención.<br/>Hoy entronado con poder,<br/>Divina_autoridad,<br/>Reinando_estás en pro de Dios<br/>Y de la_humanidad.<br/>',NULL,189162,6);
INSERT INTO stanza VALUES('S152','7','Igual que Salomón el Rey,<br/>Tu reino es de paz;<br/>Y con sabiduría_harás<br/>Su casa eternal.<br/>Entre los santos reina ya<br/>Aquel que no se ve,<br/>Mas cuando reinemos con Él<br/>Su reino se_ha de ver.<br/>',NULL,189163,7);
INSERT INTO stanza VALUES('S152','8','Profeta, Sacerdote_y Rey,<br/>¡Qué digno_eres, Señor!<br/>Valioso para_el hombre_y Dios;<br/>Te_honramos con amor.<br/>Lo que_eres apreciamos hoy;<br/>Nos mueve_el corazón;<br/>Te_alabaremos sin cesar<br/>Con gracias y loor.<br/>',NULL,189164,8);
INSERT INTO stanza VALUES('S153','1','El testimonio de Dios Tú,<br/>Superaste la ley.<br/>La ley, un tipo fiel de Ti,<br/>Grabada_en piedras fue.<br/>La ley un cuadro fue de Dios,<br/>Y su definición;<br/>Mas eres Tú Su realidad,<br/>En Ti hoy mora Dios.<br/>',NULL,189165,1);
INSERT INTO stanza VALUES('S153','2','También el Arca_un tipo fue,<br/>Tu testimonio_aquí;<br/>En ella puso Dios Su ley,<br/>Más Él se ve en Ti.<br/>El arca de madera es<br/>Y de_oro se cubrió;<br/>Es tipo de Tu_humanidad,<br/>En donde_habita Dios.<br/>',NULL,189166,2);
INSERT INTO stanza VALUES('S153','3','Eres el tabernáculo,<br/>Morada eternal,<br/>Del mismo Dios que se_encarnó<br/>Con gracia_y realidad.<br/>Su gloria Dios en Ti mostró,<br/>Tú, Su Palabra fiel,<br/>Que por Tu obra, luz y amor<br/>Lo diste_a conocer.<br/>',NULL,189167,3);
INSERT INTO stanza VALUES('S153','4','El templo_un tipo Tuyo fue,<br/>La casa de Dios, Tú.<br/>En Ti habita_el Dios de amor,<br/>Nos das Su plenitud.<br/>Aunque Satán te destruyó,<br/>Por muerto te contó,<br/>Te haces, en resurrección,<br/>Más grande_habitación.<br/>',NULL,189168,4);
INSERT INTO stanza VALUES('S153','5','Es la ciudad Tu plenitud,<br/>Tu novia es señal;<br/>Tu mismo_aumento ella es,<br/>Donde morando_estás.<br/>La luz divina_en Ti es Dios;<br/>La lámpara_eres Tú;<br/>Por ella_alumbra_a todos Dios<br/>Con tal gloriosa luz.<br/>',NULL,189169,5);
INSERT INTO stanza VALUES('S153','6','El Arca_y tabernáculo<br/>Guardan la ley de Dios.<br/>El templo_y la ciudad también<br/>Son todos Tú, Señor.<br/>El eje y la rueda, Tú,<br/>¡El todo_en todos hoy!<br/>En Ti se ven el hombre_y Dios,<br/>¡Cuán grato_al corazón!<br/>',NULL,189170,6);
INSERT INTO stanza VALUES('S154','1','Tú eres las ofrendas<br/>Que Dios nos preparó;<br/>Con mucho simbolismo<br/>Te_expresan, oh Señor.<br/>A Dios le agradaron,<br/>Cumplieron Su‿intención;<br/>También hicieron frente<br/>A nuestra condición.<br/>',NULL,189171,1);
INSERT INTO stanza VALUES('S154','2','Eres el holocausto<br/>Que_el fuego consumió;<br/>A Dios, un olor grato<br/>Que Su placer cumplió.<br/>En Su presencia_andabas,<br/>Viviste para El,<br/>Te diste como ofrenda<br/>A Dios por nuestro bien.<br/>',NULL,189172,2);
INSERT INTO stanza VALUES('S154','3','Eres harina fina,<br/>Fragante oblación,<br/>Mezclada con aceite<br/>Y_olíbano_en unión.<br/>La ofrenda de paz eres<br/>Para traernos paz;<br/>Con Dios te disfrutamos<br/>Como alimento real.<br/>',NULL,189173,3);
INSERT INTO stanza VALUES('S154','4','Ofrenda de pecado<br/>Para propiciación;<br/>Tu muerte fue_el rescate<br/>Pagado_en redención.<br/>Ofrenda por las culpas<br/>Y toda transgresión;<br/>Ganaste por nosotros<br/>Justicia y perdón.<br/>',NULL,189174,4);
INSERT INTO stanza VALUES('S154','5','Como_ofrenda mecida,<br/>Tú en resurrección,<br/>Lograste la victoria<br/>Sobre la muerte atroz.<br/>Como_ofrenda_elevada<br/>Tú ascendiste_a Dios,<br/>Y como tal nos sacias<br/>Al ser nuestra porción.<br/>',NULL,189175,5);
INSERT INTO stanza VALUES('S155','1','Las figuras del pasado,<br/>Símbolos y tipos son<br/>Que, Señor, te muestran como<br/>Toda nuestra provisión.<br/>Contemplando tales cuadros,<br/>Impresiona su_esplendor.<br/>Admirando Tus riquezas,<br/>Te_adoramos con fervor.<br/>',NULL,189176,1);
INSERT INTO stanza VALUES('S155','2','Señor, nuestra Pascua eres;<br/>Dios por Ti nos perdonó.<br/>Por Tu redención gozamos<br/>Armonía hoy con Dios.<br/>El Cordero de Dios eres,<br/>Tu rescate nos libró.<br/>Aplicamos hoy Tu sangre<br/>Al comer de Ti, Señor.<br/>',NULL,189177,2);
INSERT INTO stanza VALUES('S155','3','Eres pan sin levadura,<br/>El pan vivo celestial;<br/>Al comerte, nos mezclamos<br/>Y nos libras del pecar.<br/>El Cordero y_el Pan muestran<br/>Que_eres nuestra vida, Tú;<br/>Disfrutamos en Tu mesa<br/>De Tu rica plenitud.<br/>',NULL,189178,3);
INSERT INTO stanza VALUES('S155','4','Eres el Maná del cielo,<br/>Nuestra diaria provisión;<br/>Fortaleces, vigorizas<br/>Y nos das satisfacción.<br/>Eres Tú la Piedra viva<br/>Que, hendida, agua dio.<br/>Al beber del agua viva,<br/>Toda nuestra sed sació.<br/>',NULL,189179,4);
INSERT INTO stanza VALUES('S155','5','Tierra de Canaán Tu eres,<br/>Rica, buena,_en ascensión.;<br/>Ella fluye miel y leche<br/>En gloriosa profusión.<br/>Con Tus ricos excedentes<br/>Te_alabamos en unión.<br/>En tal comunión gloriosa<br/>Somos Tu_edificación.<br/>',NULL,189180,5);
INSERT INTO stanza VALUES('S156','1','Todo-inclusivo_eres, Señor,<br/>En Ti nos puso Dios;<br/>Y a nosotros te legó<br/>Como nuestra porción.<br/>',NULL,189181,1);
INSERT INTO stanza VALUES('S156','2','Sabiduría eres de Dios,<br/>Por Ti Él nos salvó;<br/>No_existe otro modo hoy<br/>Para la salvación.<br/>',NULL,189182,2);
INSERT INTO stanza VALUES('S156','3','Justicia nuestra eres Tú,<br/>Lo que requiere Dios;<br/>En Ti Él nos justificó,<br/>En Ti nos completó.<br/>',NULL,189183,3);
INSERT INTO stanza VALUES('S156','4','Tú eres nuestra santidad,<br/>Para transformación;<br/>Santificándonos estás<br/>Para conformación.<br/>',NULL,189184,4);
INSERT INTO stanza VALUES('S156','5','Tú eres nuestra redención,<br/>Seremos como Tú;<br/>Dios nuestros cuerpos cambiará<br/>Con gloria y virtud.<br/>',NULL,189185,5);
INSERT INTO stanza VALUES('S156','6','Al recordarte_aquí, Señor,<br/>Te disfrutarnos más;<br/>Quisiéramos apresurar<br/>Tu reino celestial.<br/>',NULL,189186,6);
INSERT INTO stanza VALUES('S156','7','¡Qué dulce es tal presabor!<br/>Nos trae satisfacción;<br/>Mas esperamos lo mejor:<br/>Tu manifestación.<br/>',NULL,189187,7);
INSERT INTO stanza VALUES('S157','1','El Árbol de la vida, Tú;<br/>La vida_ofreces hoy;<br/>Tu vida_así puede saciar<br/>Nuestra_hambre, oh Señor.<br/>',NULL,189188,1);
INSERT INTO stanza VALUES('S157','2','La verdadera Vid, Señor,<br/>Tú_eres, que vida das;<br/>Si permanecesmos en Tí,<br/>Tendremos vida_y paz.<br/>',NULL,189189,2);
INSERT INTO stanza VALUES('S157','3','El Árbol de manzano, Tú,<br/>¡Disfrute_y bendición!<br/>Tu fruto_es dulce_al paladar;<br/>Tu sombra_es protección.<br/>',NULL,189190,3);
INSERT INTO stanza VALUES('S157','4','Tú eres Árbol sanador<br/>Que la muerte sorbió;<br/>Al padecer la cruenta cruz,<br/>Tu muerte nos curó.<br/>',NULL,189191,4);
INSERT INTO stanza VALUES('S157','5','Eres el Vástago de Dios;<br/>Su gracia_en Ti nos da;<br/>Habita en Ti Su plenitud,<br/>También Su realidad.<br/>',NULL,189192,5);
INSERT INTO stanza VALUES('S157','6','Como Renuevo de David,<br/>Te hiciste carne, Tú.<br/>En Tu humanidad se vio<br/>La gracia_y la virtud.<br/>',NULL,189193,6);
INSERT INTO stanza VALUES('S157','7','La Vara que reverdeció<br/>Con vida eternal:<br/>Tal como Tu resurrección<br/>La muerte_anulará.<br/>',NULL,189194,7);
INSERT INTO stanza VALUES('S157','8','Eres el Palo que flotó<br/>Y_el hacha levantó;<br/>Tu vida con Tu gran poder,<br/>De muerte nos sacó.<br/>',NULL,189195,8);
INSERT INTO stanza VALUES('S157','9','La "Planta de renombre", Tú;<br/>¡Qué rico_es compartir!<br/>Te recordamos con amor<br/>Para_expresarte_aquí.<br/>',NULL,189196,9);
INSERT INTO stanza VALUES('S158','1','Eres la Roca eterna;<br/>Fuiste hendido por mí.<br/>Hoy de Tu_Espíritu bebo,<br/>Para unirme a Tí.<br/>Eres la Roca_inmovible,<br/>Roca de_edificación;<br/>Nadie podrá acusarnos<br/>Debido_a Tu redención.<br/>',NULL,189197,1);
INSERT INTO stanza VALUES('S158','chorus','¡Cuán apreciado Tú eres!<br/>Rico_y de mucho valor.<br/>Hoy en memoria_amorosa<br/>Te disfrutamos Señor.<br/>',NULL,189198,2);
INSERT INTO stanza VALUES('S158','2','Eres la Piedra probada;<br/>Precioso, Tú, para Dios.<br/>Tú, tan seguro y firme,<br/>No tienes comparación.<br/>Eres también Piedra viva,<br/>Fuiste_elegido por Dios.<br/>Nos diste la vida_eterna<br/>Con su poder y vigor.<br/>',NULL,189199,3);
INSERT INTO stanza VALUES('S158','3','La Piedra de fundamento<br/>Eres, quien Dios afirmó;<br/>Por este firme cimiento<br/>Seguridad se logró.<br/>No hay ningún fundamento<br/>Que pueda_el hombre poner;<br/>Tú eres el fundamento<br/>Que para siempre_ha de ser.<br/>',NULL,189200,4);
INSERT INTO stanza VALUES('S158','4','Piedra del ángulo eres<br/>En la morada de Dios;<br/>Ya los judíos y griegos<br/>Ambos en Ti uno son.<br/>Eres la Piedra cimera<br/>Llena de gracia, Señor,<br/>Nuestra cubierta y gloria,<br/>A Ti te damos loor.<br/>',NULL,189201,5);
INSERT INTO stanza VALUES('S159','1','El Sol de la justicia, Tú,<br/>Nos traes la sanidad;<br/>Y de Tu rostro_el resplandor,<br/>Hoy Tus riquezas da.<br/>',NULL,189202,1);
INSERT INTO stanza VALUES('S159','2','Por la merced de nuestro Dios<br/>Amaneciste Tú;<br/>La sombra de la noche_atróz<br/>Se disipó_en Tu luz.<br/>',NULL,189203,2);
INSERT INTO stanza VALUES('S159','3','La luz del alba eres Tú,<br/>Y nuestro_amanecer;<br/>Somos los pastos que_en Tu luz<br/>Encuentran gran placer.<br/>',NULL,189204,3);
INSERT INTO stanza VALUES('S159','4','Tu agradable resplandor<br/>A diario_ha de crecer,<br/>Brillando_en nuestro interior<br/>Hasta perfecto ser.<br/>',NULL,189205,4);
INSERT INTO stanza VALUES('S159','5','Tu luz traspasa la_aflicción<br/>Como_a la lluvia_el sol;<br/>Tu brillo nunca cesará<br/>Por Tu bondad y_amor.<br/>',NULL,189206,5);
INSERT INTO stanza VALUES('S159','6','Resplandeciente_estrella, Tú,<br/>Hoy eres galardón<br/>Y luz a los que,_al madrugar,<br/>Te buscan con amor.<br/>',NULL,189207,6);
INSERT INTO stanza VALUES('S159','7','Ayúdanos a_amar Tu luz<br/>Y a buscar, Señor,<br/>Esa estrella que_eres Tú,<br/>Velando_en oración.<br/>',NULL,189208,7);
INSERT INTO stanza VALUES('S160','1','El Paracleto_eres, Señor,<br/>Y fiel Consolador;<br/>Nuestro_Abogado ante Dios<br/>Y nuestro Defensor.<br/>',NULL,189209,1);
INSERT INTO stanza VALUES('S160','2','El Consejero_eres también,<br/>Y nuestro_Intercesor;<br/>Defiendes nuestro caso Tú,<br/>Perfecto Ayudador.<br/>',NULL,189210,2);
INSERT INTO stanza VALUES('S160','3','Tú llevas, con poder, Señor,<br/>Nuestros asuntos hoy;<br/>Así_en los cielos, como_aquí,<br/>Quedamos bien con Dios.<br/>',NULL,189211,3);
INSERT INTO stanza VALUES('S160','4','Con gracia intercedes Tú,<br/>Señor Espíritu;<br/>Tú gimes en nuestro_interior<br/>Y_en lo_alto ruegas Tú.<br/>',NULL,189212,4);
INSERT INTO stanza VALUES('S160','5','Tú, el Viviente, ayuda das<br/>Conforme_al plan de Dios;<br/>Resurrección impartes hoy<br/>Al hombre interior.<br/>',NULL,189213,5);
INSERT INTO stanza VALUES('S160','6','Al débil, el Espíritu<br/>Da vida y sostén;<br/>Y nuestro espíritu así<br/>Mantienes con poder.<br/>',NULL,189214,6);
INSERT INTO stanza VALUES('S160','7','Tu mismo ser nos das, Señor,<br/>Con compasión y_amor;<br/>Al ser el todo_en todos hoy,<br/>Tendrás Tu expresión.<br/>',NULL,189215,7);
INSERT INTO stanza VALUES('S161','1','Señor, eres el Alfa,<br/>La_Omega y_el Amén;<br/>Eres Primero_en todo,<br/>Y_el Último también,<br/>Tú eres el Principio,<br/>Y_el único Final;<br/>En Ti se_incluye todo<br/>Lo que creado_está.<br/>',NULL,189216,1);
INSERT INTO stanza VALUES('S161','2','Ya que Tú_eres el Alfa,<br/>Todo comienza_en Ti;<br/>Y por ser Tú la_Omega,<br/>Todo termina en Ti.<br/>Por ser el Alfabeto,<br/>Toda composición<br/>De Ti está compuesta,<br/>Hasta la conclusión.<br/>',NULL,189217,2);
INSERT INTO stanza VALUES('S161','3','Como el Primero eres<br/>Cabeza en la creación;<br/>Por Ti todo consiste,<br/>Eres la_iniciación.<br/>Como Último Tú eres<br/>La gran consumación;<br/>Y para Ti subsiste<br/>La_entera creación.<br/>',NULL,189218,3);
INSERT INTO stanza VALUES('S161','4','Ya que eres el Principio,<br/>Precedes la creación;<br/>Y como el Fin heredas<br/>Todo como porción.<br/>El único Principio<br/>Que todo originó,<br/>El fin de todo eres<br/>Y la terminación.<br/>',NULL,189219,4);
INSERT INTO stanza VALUES('S161','5','Señor, te alabamos<br/>Por ser Principio_y Fin;<br/>Como_Alfa_y como_Omega<br/>Se rinde todo a Ti.<br/>Como el Primero_en todo,<br/>Recibe nuestro amor;<br/>Como_Último mereces<br/>Eterna adoración.<br/>',NULL,189220,5);
INSERT INTO stanza VALUES('S162','1','Lo que es: es el Padre.<br/>El es el eterno Padre.<br/>Primogénito de la creación<br/>Es Aquel que vive_en mi_interior.<br/>¡Es el Padre! ¡Gloria a Dios!<br/>',NULL,189221,1);
INSERT INTO stanza VALUES('S162','2','Lo que es: es el río.<br/>Es el río caudaloso.<br/>Él me riega cuando seco_estoy,<br/>Mi escondedero,_a Él yo voy.<br/>¡Es el río! ¡Gloria a Dios!<br/>',NULL,189222,2);
INSERT INTO stanza VALUES('S162','3','Lo que es: vid fructuosa.<br/>De_Isaí raíz y rama.<br/>Árbol de vida para comer<br/>Y así Su vida poseer.<br/>¡Vid fructuosa! ¡Gloria a Dios!<br/>',NULL,189223,3);
INSERT INTO stanza VALUES('S162','4','Lo que es: es Cordero.<br/>Es Pastor de Su rebaño.<br/>A los pastos verdes guía El.<br/>Al untar la sangre_hay que comer<br/>Del Cordero. ¡Gloria a Dios!<br/>',NULL,189224,4);
INSERT INTO stanza VALUES('S162','5','Lo que es: es el "pneuma",<br/>El Espíritu_inclusivo.<br/>Es el todo_en todo_a nuestro ser.<br/>Vida nos da clamando a El.<br/>¡Es el "pneuma"! ¡Gloria a Dios!<br/>',NULL,189225,5);
INSERT INTO stanza VALUES('S162','6','Lo que es: es Persona.<br/>¡Tan viviente y real Persona!<br/>En nosotros hoy viviendo está,<br/>Esa Persona es sin igual.<br/>¡Qué Persona! ¡Gloria a Dios!<br/>',NULL,189226,6);
INSERT INTO stanza VALUES('S162','7','Lo que es: es el Cuerpo.<br/>Es la plenitud del Padre.<br/>Es el centro de Su eterno plan,<br/>Cristo y la iglesia en unidad<br/>¡Nuevo hombre! ¡Gloria a Dios!<br/>',NULL,189227,7);
INSERT INTO stanza VALUES('S162','chorus','Aleluya! Gloria a Dios!<br/>Aleluya! Gloria a Dios!<br/>',NULL,189228,8);
INSERT INTO stanza VALUES('S163','1','En el seno del Dios Padre<br/>Antes de  la creación,<br/>Tú estabas en Su gloria,<br/>Unigénito de Dios.<br/>Fuiste dado por el Padre<br/>Como un hombre al mundo, Tú;<br/>En Espíritu nos muestras<br/>De Dios, Su gran plenitud.<br/>',NULL,189229,1);
INSERT INTO stanza VALUES('S163','2','Por Tu muerte inclusiva<br/>Y por Tu resurrección<br/>Tú naciste como_el Hijo<br/>Primogénito de Dios.<br/>Impartiste así Tu vida<br/>Por la regeneración,<br/>Nos hiciste Tus hermanos,<br/>Muchos hijos para Dios.<br/>',NULL,189230,2);
INSERT INTO stanza VALUES('S163','3','Eras Tú un solo grano<br/>Que_en la tierra_aquí cayó,<br/>Al morir, resucitando<br/>Tu vida se duplicó.<br/>Somos hoy los muchos granos,<br/>Amasados en un pan,<br/>A Tu plenitud llegamos<br/>Para Tu_expresión mostrar.<br/>',NULL,189231,3);
INSERT INTO stanza VALUES('S163','4','Somos Tu_expresión,Tu Cuerpo,<br/>Plenitud y_habitación,<br/>Tu_excedente y Tu Novia,<br/>Tu total reproducción.<br/>Como_aumento de Tu vida<br/>Somos Tu propagación;<br/>Eres Tú nuestra Cabeza,<br/>Somos Tu continuación.<br/>',NULL,189232,4);
INSERT INTO stanza VALUES('S164','1','Congregados en Tu nombre<br/>Hoy, Señor Jesús, aquí<br/>Nos da gozo Tu presencia,<br/>Al centrarnos sólo en Ti.<br/>',NULL,189233,1);
INSERT INTO stanza VALUES('S164','2','Así como‿el Padre Te‿ama<br/>Nos amó con tal amor.<br/>Apreciamos Sus afectos<br/>Para contigo, Señor.<br/>',NULL,189234,2);
INSERT INTO stanza VALUES('S164','3','Todo Su descanso‿y gozo,<br/>Su deleite‿eterno,‿en Ti,<br/>Solo Tú Señor sondeas<br/>Lo que‿el Padre_halló en Ti.<br/>',NULL,189235,3);
INSERT INTO stanza VALUES('S164','4','Puso‿en Ti todo Su‿afecto.<br/>“Hijo‿amado” te llamó;<br/>Mas no Te‿eximió de muerte,<br/>Vida‿eterna‿así nos dio.<br/>',NULL,189236,4);
INSERT INTO stanza VALUES('S164','5','¡Oh, qué gozo! ¡Cantaremos<br/>Cuando te podamos ver!<br/>Jesucristo dulce nombre,<br/>Trae al Padre gran placer.<br/>',NULL,189237,5);
INSERT INTO stanza VALUES('S164','6','Cánticos y alabanzas,<br/>Himnos de‿eternal loor,<br/>Salmos de‿inefable gozo,<br/>Por la‿eternidad de Dios.<br/>',NULL,189238,6);
INSERT INTO stanza VALUES('S165','1','Oh, Cristo es la fuente,<br/>El dulce manantial;<br/>Sus aguas vivas pruebo<br/>Que salvan del pesar.<br/>Es Su misericordia<br/>Tan ancha como_el mar,<br/>Su gracia_es suficiente,<br/>Según Su sabio plan.<br/>',NULL,189239,1);
INSERT INTO stanza VALUES('S165','2','Yo soy de mi Amado,<br/>Y Él mi_Amado es,<br/>Aunque tan vil y pobre,<br/>Festejo yo con Él.<br/>Su mérito sostiene,<br/>Mi base firme es;<br/>Me_escondo_en Su presencia<br/>Su mano_es mi retén.<br/>',NULL,189240,2);
INSERT INTO stanza VALUES('S165','3','Radiante_está la Novia<br/>Mas sólo_al Novio ve;<br/>No mengua tanta gloria<br/>La gracia de mi Rey.<br/>Sus manos traspasadas<br/>Más que corona es,<br/>La gloria_es al Cordero,<br/>Mi eternal sostén.<br/>',NULL,189241,3);
INSERT INTO stanza VALUES('S166','1','Pensando_en Tí, Señor Jesús,<br/>Tu gracia y Tu amor,<br/>Anhela nuestro_espíritu<br/>Tu_hermosa faz, Señor.<br/>',NULL,189242,1);
INSERT INTO stanza VALUES('S166','2','Aunque_en desierto_andamos hoy,<br/>Por tierra de_aridéz,<br/>Por tierra que espinos da,<br/>Rivales por doquier.<br/>',NULL,189243,2);
INSERT INTO stanza VALUES('S166','3','Mas al mirar Tu gran amor,<br/>Rebosa_el corazón;<br/>Contentos ante Ti, Señor,<br/>Alzamos hoy canción.<br/>',NULL,189244,3);
INSERT INTO stanza VALUES('S166','4','Descanso_y Vida_eres, Señor,<br/>Roca, Comida_y luz;<br/>Es un deleite_en Ti pensar;<br/>Refrescas siempre Tú.<br/>',NULL,189245,4);
INSERT INTO stanza VALUES('S166','5','Oh, guarda nuestro espíritu<br/>En pos de Ti, Señor,<br/>Hasta, en triunfo, poder ver<br/>Tu gloria y_esplendor.<br/>',NULL,189246,5);
INSERT INTO stanza VALUES('S167','1','¡Jesús, Jesús, oh mi Señor!<br/>Yo amo repetir<br/>Tu santo nombre por amor<br/>Mil veces hacia Ti.<br/>',NULL,189247,1);
INSERT INTO stanza VALUES('S167','chorus','Señor Jesús, habita en mí,<br/>Tú eres mi satisfacción,<br/>Tu mismo ser es mi porción,<br/>Te amo, te amo, Señor.<br/>',NULL,189248,2);
INSERT INTO stanza VALUES('S167','2','Te amo tanto que no sé<br/>Tal éxtasis domar;<br/>Tu_amor es como_un fuego_en mí<br/>Que arde sin cesar.<br/>',NULL,189249,3);
INSERT INTO stanza VALUES('S167','3','Tú eres todo para mí,<br/>Mis bienes y mi_honor,<br/>Salud eterna_a mi alma das,<br/>Y al cuerpo su vigor.<br/>',NULL,189250,4);
INSERT INTO stanza VALUES('S167','4','Que arda_en mí Tu gran amor,<br/>Con fuerza_y sin parar,<br/>Hasta que toda_escoria_en mí<br/>Se pueda_incinerar.<br/>',NULL,189251,5);
INSERT INTO stanza VALUES('S167','5','En pena, gozo;_en sombra, luz,<br/>¡Oh, vida celestial!<br/>Jesús, mi_amor, mi galardón,<br/>¿Quién te podrá valuar?<br/>',NULL,189252,6);
INSERT INTO stanza VALUES('S167','6','¿Qué límite_hay para_este amor?<br/>¿Cuán lejos su poder?<br/>¡Seguid! Más dulce es el Señor<br/>De lo que fue ayer.<br/>',NULL,189253,7);
INSERT INTO stanza VALUES('S168','1','Jesús, me_endulza_el corazón<br/>Sólo pensar en Ti;<br/>Pero más dulce_es ver Tu faz<br/>Y descansar así.<br/>',NULL,189254,1);
INSERT INTO stanza VALUES('S168','2','Ni voz, ni mente_o corazón<br/>Podrán cantar o_hallar<br/>Tan dulce nombre sin igual<br/>Que pueda_aun salvar.<br/>',NULL,189255,2);
INSERT INTO stanza VALUES('S168','3','Tú, la_esperanza_al triste ser,<br/>Al manso, gozo das;<br/>¡Para_el caído_eres bondad!<br/>Y al que busca, paz.<br/>',NULL,189256,3);
INSERT INTO stanza VALUES('S168','4','¿Y qué de_aquél que encontró<br/>Tu gran amor, Jesús?<br/>Nadie podrá_entender Tu_amor,<br/>Sólo_el que amas Tú.<br/>',NULL,189257,4);
INSERT INTO stanza VALUES('S168','5','Fuego y vida_eres, Jesús,<br/>Y para_el mundo, luz;<br/>Excedes todo gozo_aquí,<br/>Y todo_anhelo, Tú.<br/>',NULL,189258,5);
INSERT INTO stanza VALUES('S168','6','La fuente única_eres Tú,<br/>Que calma nuestra sed.<br/>¡Inagotable manantial<br/>Que sacia nuestro ser!<br/>',NULL,189259,6);
INSERT INTO stanza VALUES('S168','7','Sé nuestro Gozo_ahora Tú,<br/>Y_el Galardón serás;<br/>Sé nuestra Gloria hoy, Jesús,<br/>Y por la_eternidad.<br/>',NULL,189260,7);
INSERT INTO stanza VALUES('S169','1','Jesús, en esa noche<br/>Do todo se juntó<br/>Para_arrojar sus sombras<br/>En Tu mente, Señor,<br/>Dijiste: "Haced esto<br/>En memoria de Mí";<br/>Jesús, hoy nos reunimos:<br/>En memoria de Ti.<br/>',NULL,189261,1);
INSERT INTO stanza VALUES('S169','2','Tu hondo sufrimiento<br/>¿Quién podrá concebir?<br/>La copa de la ira<br/>Tomaste Tú por mí.<br/>Por Dios abandonado<br/>En el madero vil;<br/>Con gratitud hacemos<br/>Memoria hoy de Ti.<br/>',NULL,189262,2);
INSERT INTO stanza VALUES('S169','3','Tu_espíritu rodeado<br/>Fue por la_oscuridad;<br/>También golpeó Tu alma<br/>La_horrenda tempestad.<br/>Allí se vio Tu gracia<br/>Y Tu perfecto amor;<br/>Con gratitud y gozo<br/>Te recordamos hoy.<br/>',NULL,189263,3);
INSERT INTO stanza VALUES('S169','4','El Primogénito eres,<br/>A quien Dios levantó;<br/>Cabeza de la iglesia,<br/>Estás en ascensión.<br/>Por gracia aceptados,<br/>Y libre_el corazón,<br/>Pensando_en Tus dolores<br/>Te recordamos hoy.<br/>',NULL,189264,4);
INSERT INTO stanza VALUES('S169','5','Señor, para llevarnos<br/>En gloria Tú vendrás;<br/>En ese día radiante,<br/>Descanso nos darás.<br/>Tu muerte_anunciaremos<br/>Mientras buscamos ser<br/>A ella conformados,<br/>Aún recordándote.<br/>',NULL,189265,5);
INSERT INTO stanza VALUES('S170','1','Conforme_a Tu palabra fiel,<br/>En humildad aquí,<br/>Ya que moriste, mi Señor,<br/>Me_acordaré de Ti.<br/>',NULL,189266,1);
INSERT INTO stanza VALUES('S170','2','Tu cuerpo que quebrado fue,<br/>Mi pan del cielo es;<br/>Tomando de_esta copa_así<br/>Yo te recordaré.<br/>',NULL,189267,2);
INSERT INTO stanza VALUES('S170','3','¿Podré_olvidar Getsemaní,<br/>O Tu conflicto_allí,<br/>Tu agonía_y Tu sudor,<br/>Sin recordarte_a Tí?<br/>',NULL,189268,3);
INSERT INTO stanza VALUES('S170','4','Cuando el Cordero en la cruz<br/>Yo vuelvo a mirar,<br/>Tu sacrificio_allí por mí<br/>Tengo que recordar.<br/>',NULL,189269,4);
INSERT INTO stanza VALUES('S170','5','Recuerdo Tu pena_y dolor,<br/>Y Tu amor por mí;<br/>En tanto tenga_aliento yo,<br/>Me_acordaré de Tí.<br/>',NULL,189270,5);
INSERT INTO stanza VALUES('S170','6','Cuando mis labios callen ya,<br/>Sin más memoria_aquí,<br/>Y vengas en Tu reino, ¡oh,<br/>Acuérdate de mí!<br/>',NULL,189271,6);
INSERT INTO stanza VALUES('S171','1','Percibimos Tu presencia<br/>En Tu mesa, oh Señor:<br/>Tal banquete_inestimable,<br/>Con bandera de Tu_amor.<br/>¡Qué momentos en Tu mesa!<br/>Sin temor ni duda _aquí,<br/>Disfrutando Tu descanso,<br/>Ocupados sólo_en Ti.<br/>',NULL,189272,1);
INSERT INTO stanza VALUES('S171','2','Nos gozamos en Tu mesa,<br/>Guiados por Tu_Espíritu,<br/>Meditando_en el recuerdo<br/>De Tu sangre_y su virtud.<br/>Al tomar el pan y_el vino<br/>En memoria hoy de Ti,<br/>Meditamos en Tu cuerpo<br/>Y Tu sangre carmesí.<br/>',NULL,189273,2);
INSERT INTO stanza VALUES('S171','3','Oh, qué gozo_es poder verte<br/>En los símbolos, Señor:<br/>El pan que nos fortalece<br/>Y el vino_alegrador.<br/>Uno_en Ti, nuestra Cabeza;<br/>Congregados en amor;<br/>Con el pan aquí tomamos<br/>Tu bendita copa hoy.<br/>',NULL,189274,3);
INSERT INTO stanza VALUES('S171','4','Cuán real es Tu promesa:<br/>"Con vosotros estaré,<br/>Al reunirse, congregados<br/>En Mi nombre, cada vez".<br/>Más querida_es la promesa<br/>Para nuestro corazón,<br/>Que_estaremos para siempre<br/>Donde Tú estés, Señor.<br/>',NULL,189275,4);
INSERT INTO stanza VALUES('S172','1','Tu mesa al contemplar, Señor,<br/>Evoca_admiración;<br/>El pan, la copa signos son<br/>De lo que quiere Dios.<br/>',NULL,189276,1);
INSERT INTO stanza VALUES('S172','2','El pan revela que_eres Tú<br/>Comida celestial;<br/>Y por Tu muerte mística<br/>Tu mismo ser nos das.<br/>',NULL,189277,2);
INSERT INTO stanza VALUES('S172','3','Es esta copa mi porción,<br/>Tu sangre la llenó;<br/>Es copa de gran bendición<br/>Para ganar a Dios.<br/>',NULL,189278,3);
INSERT INTO stanza VALUES('S172','4','De Ti comemos en el pan,<br/>Tu vida_así nos das;<br/>Al recordarte en amor<br/>Tu ser nos saciará.<br/>',NULL,189279,4);
INSERT INTO stanza VALUES('S172','5','Hoy disfrutamos bendición<br/>Por la copa_al beber;<br/>Te recordamos con fervor<br/>Hasta llevados ser.<br/>',NULL,189280,5);
INSERT INTO stanza VALUES('S172','6','Al disfrutar del vino_y pan<br/>Tu muerte se_expondrá;<br/>Que nuestra vida eres Tu<br/>También se_anunciara.<br/>',NULL,189281,6);
INSERT INTO stanza VALUES('S172','7','Un día tan glorioso_habrá<br/>De gran satisfacción,<br/>Para_en tu mesa disfrutar<br/>Contigo comunión.<br/>',NULL,189282,7);
INSERT INTO stanza VALUES('S173','1','Damos gracias por tu mesa<br/>Donde_el pan y el vino están;<br/>Tu persona disfrutamos<br/>Como fiesta de amor.<br/>Este pan que_aquí tomamos,<br/>De Tu cuerpo_emblema es;<br/>Y la sangre que vertiste,<br/>En el vino hoy se ve.<br/>',NULL,189283,1);
INSERT INTO stanza VALUES('S173','chorus','¡Ved la santa mesa!<br/>Símbolos sagrados,<br/>Su significado_eterno<br/>Insondable es.<br/>',NULL,189284,2);
INSERT INTO stanza VALUES('S173','2','Por Tu muerte redentora<br/>Impartiste vida real.<br/>A nosotros Tú te diste<br/>Para_en Ti participar.<br/>Al tomar el pan y_el vino<br/>Ya Tu muerte se_exhibió;<br/>Te comemos, te bebemos<br/>Recordándote_en amor.<br/>',NULL,189285,3);
INSERT INTO stanza VALUES('S173','3','Por el pan que representa_el<br/>Cuerpo místico en unión;<br/>Comulgamos con Tus miembros<br/>En gloriosa comunión.<br/>Por la copa bendecida,<br/>Copa de gran bendición,<br/>De Tu sangre los creyentes<br/>Tienen plena comunión.<br/>',NULL,189286,4);
INSERT INTO stanza VALUES('S173','4','Tú_eres la porción eterna<br/>Que gustamos hoy aquí;<br/>Esperando por Tú reino<br/>Apuramos Tu venir.<br/>En Tu reino, a Tu regreso,<br/>Con los que han de vencer,<br/>Siempre_en Ti nos gozaremos,<br/>Para_al fin Tu Novia ser.<br/>',NULL,189287,5);
INSERT INTO stanza VALUES('S174','1','Gracias, Señor, por este pan,<br/>Señal divina es;<br/>De los misterios de Tu plan<br/>De Tu designio fiel.<br/>',NULL,189288,1);
INSERT INTO stanza VALUES('S174','2','El pan un bello signo es,<br/>Tu cuerpo nos da_a ver;<br/>Lo diste para_infundir<br/>Tu vida_en nuestro ser.<br/>',NULL,189289,2);
INSERT INTO stanza VALUES('S174','3','Tu cuerpo quebrantado fue<br/>Para vida impartir;<br/>Así nosotros somos hoy<br/>Tu complemento aquí.<br/>',NULL,189290,3);
INSERT INTO stanza VALUES('S174','4','El pan también nos hace ver<br/>Tu Cuerpo místico;<br/>Los miembros vivos somos de_él,<br/>A Ti idénticos.<br/>',NULL,189291,4);
INSERT INTO stanza VALUES('S174','5','Los muchos granos somos, más<br/>Un solo pan se ve;<br/>Al recordarte en tal unión,<br/>Nos nutres con tu ser.<br/>',NULL,189292,5);
INSERT INTO stanza VALUES('S174','6','Al compartir de este pan<br/>¡Qué gran satisfacción!<br/>Tu testimonio, es Senor,<br/>Y nuestra comunión.<br/>',NULL,189293,6);
INSERT INTO stanza VALUES('S175','1','En la mesa de Tu amor,<br/>Con el pan la copa está.<br/>De_estos signos al tomar,<br/>Tu rico ser nos saciará.<br/>Por la copa de Tu_amor,<br/>Gracias damos, oh Señor,<br/>Copa de gran bendición,<br/>Llena de Tu salvación.<br/>',NULL,189294,1);
INSERT INTO stanza VALUES('S175','2','Esta sangre se vertió<br/>Para darnos el perdón;<br/>Este pacto_estableció,<br/>Y nos legó Su bendición.<br/>La copa de ira fue<br/>Que bebiste Tú por mí;<br/>La copa de bendición,<br/>Tú nos diste por porción.<br/>',NULL,189295,2);
INSERT INTO stanza VALUES('S175','3','Trae a Dios esta porción,<br/>Que perdimos en Adán;<br/>Por Tu sangre eficaz,<br/>El todo_en todo_es nuestro Dios.<br/>Todo_incluye tal porción,<br/>Redención con vida y paz;<br/>Todo lo que Dios planeó,<br/>Llega_a ser nuestra porción.<br/>',NULL,189296,3);
INSERT INTO stanza VALUES('S175','4','La porción eterna es,<br/>Copa que_abundante_está;<br/>Este gusto celestial<br/>Está_en la copa que_Él nos da.<br/>Hoy bebemos, oh Señor,<br/>Recordándote en amor,<br/>Gozando_en espíritu<br/>De Tu obra en la cruz.<br/>',NULL,189297,4);
INSERT INTO stanza VALUES('S176','1','Al tomar la copa hoy,<br/>La_alabanza brotará,<br/>Pues Tu sangre que fluyó<br/>Es preciosa y_eficaz.<br/>Es Tu sangre especial;<br/>Mis problemas allanó;<br/>Es Tu sangre sin igual;<br/>Mis temores disipó.<br/>',NULL,189298,1);
INSERT INTO stanza VALUES('S176','2','Por Su sangre de valor,<br/>Nuevo testamento dio,<br/>Mejor pacto se creó<br/>Con un cimiento mejor.<br/>No con oro_o plata vil,<br/>Nuestro Dios nos redimió,<br/>Mas con sangre del Señor,<br/>La cual despliega Su amor.<br/>',NULL,189299,2);
INSERT INTO stanza VALUES('S176','3','Fue por nuestra remisión<br/>Que Su sangre derramó,<br/>Plenamente así cumplió<br/>Lo que requería Dios.<br/>Con Su sangre de poder<br/>Mis pecados Él lavó;<br/>Para al vivo Dios servir,<br/>Nuestra conciencia purgó.<br/>',NULL,189300,3);
INSERT INTO stanza VALUES('S176','4','Por Tu sangre eficaz<br/>Nos apartas para Dios;<br/>Santificación nos da,<br/>Testimonio y santidad.<br/>Sangre para propiciar,<br/>Nos da justificación,<br/>Sangre para redimir,<br/>A Dios da satisfacción.<br/>',NULL,189301,4);
INSERT INTO stanza VALUES('S176','5','Por Tu sangre en la cruz<br/>Reconciliación nos das,<br/>Para contactar a Dios<br/>Con seguridad y paz.<br/>Por Tu sangre se nos dio<br/>Vida eterna en comunión;<br/>Por Tu sangre y vida das<br/>Descanso y libertad.<br/>',NULL,189302,5);
INSERT INTO stanza VALUES('S176','6','En los cielos el hablar<br/>De la sangre es superior,<br/>Nos defiende de Satán,<br/>Y nos libra de su plan.<br/>Por Tu sangre que venció<br/>Al maligno tentador,<br/>La victoria nuestra es<br/>Sobre nuestro acusador.<br/>',NULL,189303,6);
INSERT INTO stanza VALUES('S176','7','Por Tu sangre tengo yo<br/>Con los santos comunión;<br/>No decae mi_espíritu,<br/>Grande es su liberación.<br/>¿Cómo podremos narrar<br/>De Tu sangre su valor?<br/>Requiere la_eternidad<br/>Para su virtud contar.<br/>',NULL,189304,7);
INSERT INTO stanza VALUES('S177','1','Por el vino y por el pan,<br/>Por la prenda celestial,<br/>Por Tu Palabra_eternal,<br/>Gracias a Ti, Señor.<br/>',NULL,189305,1);
INSERT INTO stanza VALUES('S177','2','Sólo vino y sólo pan<br/>A mi fe son la señal<br/>De Tu‿amor tan divinal,<br/>Gracias a Ti, Señor.<br/>',NULL,189306,2);
INSERT INTO stanza VALUES('S177','3','Por palabras que dan luz,<br/>Revelándonos Tu cruz,<br/>Exponiendo Tu virtud,<br/>Gracias a Ti, Señor.<br/>',NULL,189307,3);
INSERT INTO stanza VALUES('S177','4','Por el dulce y santo hablar<br/>Sobre el vino y sobre el pan,<br/>Que me_infunde con Tu paz,<br/>Gracias a Ti, Señor.<br/>',NULL,189308,4);
INSERT INTO stanza VALUES('S177','5','Por Tu_hablar espiritual<br/>Que mostró Tu voluntad,<br/>De_esta mesa tan vital,<br/>Gracias a Ti, Señor.<br/>',NULL,189309,5);
INSERT INTO stanza VALUES('S177','6','Hasta que regrese Él,<br/>Del pan participaré,<br/>Pues es tipo de Su ser,<br/>Gracias a Ti, Señor.<br/>',NULL,189310,6);
INSERT INTO stanza VALUES('S177','7','Hasta que regrese Él<br/>De la copa beberé,<br/>Por ella me animaré,<br/>Gracias a Ti, Señor.<br/>',NULL,189311,7);
INSERT INTO stanza VALUES('S177','8','Porque pronto Tú vendrás,<br/>Por tal día sin igual,<br/>Por Tu gloria y trono real,<br/>Gracias a Ti, Señor.<br/>',NULL,189312,8);
INSERT INTO stanza VALUES('S178','1','Exhibimos hoy Tu muerte<br/>Por la copa_y por el pan;<br/>Tus sufrimientos honramos,<br/>Pruebas que Tu_amor nos da.<br/>Pan y copa separados,<br/>De Tu muerte indicio son;<br/>Nuestro_espíritu te_adora,<br/>Ofreciéndote canción.<br/>',NULL,189313,1);
INSERT INTO stanza VALUES('S178','chorus','Tú, la copa amarga,<br/>Yo, la bendecida,<br/>Por Tu_amor al redimirnos<br/>Te damos loor.<br/>',NULL,189314,2);
INSERT INTO stanza VALUES('S178','2','En amor vertiste sangre,<br/>Por Tu gracia, oh Señor;<br/>Ya no estando separados<br/>Vemos siempre a nuestro Dios.<br/>Toda Su justicia y gloria<br/>Satisfechas ya están;<br/>¡Por Tu muerte meritoria,<br/>Hoy con Dios puedo morar!<br/>',NULL,189315,3);
INSERT INTO stanza VALUES('S178','3','Al rasgar Tu muerte el velo<br/>Del Santísimo Lugar,<br/>Destruidas las barreras,<br/>En Tu trono puedo hallar<br/>Gracia y misericordia<br/>Para mi necesidad,<br/>Al beber del agua viva,<br/>De Dios puedo disfrutar.<br/>',NULL,189316,4);
INSERT INTO stanza VALUES('S178','4','Sacerdotes para siempre<br/>Somos por Tu redención,<br/>Compartiendo Tu dulzura,<br/>Santo oficio para Dios;<br/>Por Tu muerte recibimos<br/>Esta gracia y bendición,<br/>Beberemos hasta verte<br/>En aquella comunión.<br/>',NULL,189317,5);
INSERT INTO stanza VALUES('S179','1','¡Qué fiesta de amor!<br/>La gracia nos libró<br/>Para tomar en Tu honor<br/>El vino_y pan, Señor.<br/>',NULL,189318,1);
INSERT INTO stanza VALUES('S179','2','Todos los invitados<br/>De Ti han de_aprender<br/>Secretos que_en el Padre_están<br/>Y tu gracia_aprehender.<br/>',NULL,189319,2);
INSERT INTO stanza VALUES('S179','3','Con la conciencia en paz,<br/>La fe gusta probar<br/>Qué dulce_el pan de vida es<br/>Y Tu amor filial.<br/>',NULL,189320,3);
INSERT INTO stanza VALUES('S179','4','En símbolo se ve<br/>Tu sangre que fluyó;<br/>Tus arras en el corazón<br/>Nos confirman Tu amor.<br/>',NULL,189321,4);
INSERT INTO stanza VALUES('S179','5','Si tan glorioso es<br/>Tu dulce amor gustar;<br/>¿Cómo será, oh mi Señor,<br/>Tu rostro contemplar?<br/>',NULL,189322,5);
INSERT INTO stanza VALUES('S179','6','Al verte cara_a cara,<br/>Igual a Ti seré;<br/>Tu gracia, por la_eternidad<br/>Siempre declararé.<br/>',NULL,189323,6);
INSERT INTO stanza VALUES('S180','1','¡Oh, qué milagro, mi Señor,<br/>Que_estés en mí y yo en Ti esté!<br/>De hecho, somos uno Tú y yo;<br/>¡Misterio tan excelso es!<br/>',NULL,189324,1);
INSERT INTO stanza VALUES('S180','2','Tu cuerpo diste Tú por mí,<br/>De Ti yo puedo_así participar;<br/>Por mí Tu sangre derramada fue,<br/>Librándome del cruel pecar.<br/>',NULL,189325,2);
INSERT INTO stanza VALUES('S180','3','Cambiaste en resurrección,<br/>Tu forma_Espíritu ahora es;<br/>Deseas que lleno de Ti esté,<br/>Y Tus riquezas poseer.<br/>',NULL,189326,3);
INSERT INTO stanza VALUES('S180','4','Por estos símbolos, Señor<br/>De nuevo vemos Tu amante ser;<br/>Y por Tu plan te damos gracias hoy,<br/>Al recordar Tu padecer.<br/>',NULL,189327,4);
INSERT INTO stanza VALUES('S180','5','Hoy compartimos vino y pan,<br/>A Tu dulzura Tú nos guiarás;<br/>Al recibirte_en nuestro_espíritu,<br/>Tu mismo ser nos saciará.<br/>',NULL,189328,5);
INSERT INTO stanza VALUES('S180','6','Comer, beber queremos más,<br/>Tomándote en nuestro espíritu<br/>Hasta que llenes todo nuestro ser,<br/>Y recordarte_en plenitud.<br/>',NULL,189329,6);
INSERT INTO stanza VALUES('S181','1','Señor, congregados comemos Tu cena,<br/>Comiendo, bebiendo, se muestra la_unión;<br/>Nos das Tu presencia, nuestra_unidad se_expresa<br/>Comiendo y bebiendo con Tu bendición.<br/>',NULL,189330,1);
INSERT INTO stanza VALUES('S181','2','Comemos del pan que_es Tu cuerpo partido,<br/>Tu Cuerpo al ser uno se disfruta ya;<br/>Un pan en la mesa, un Cuerpo que confiesa<br/>Que_en Ti, Señor, tenemos perfecta_unidad.<br/>',NULL,189331,2);
INSERT INTO stanza VALUES('S181','3','Bebemos también esta copa bendita,<br/>Que_es fiel comunión de Tu sangre, Señor;<br/>Por fe redimidos, a todos recibimos,<br/>Los que por redención han venido a Dios.<br/>',NULL,189332,3);
INSERT INTO stanza VALUES('S181','4','Pues, ¿qué se dirá sino‿"¡Amén, aleluya!"?<br/>Tu gracia nos trajo a tal realidad;<br/>Tu sangre aplicando, Tu Cuerpo disfrutando;<br/>Iglesia tan gloriosa así se obtendrá.<br/>',NULL,189333,4);
INSERT INTO stanza VALUES('S182','1','Reunidos hoy, Señor como Tu Cuerpo,<br/>Aun siendo muchos, uno somos ya;<br/>Tu vida compartimos como miembros,<br/>Y_en esa vida está nuestra_unidad.<br/>',NULL,189334,1);
INSERT INTO stanza VALUES('S182','chorus','Un Cuerpo en el universo hay,<br/>Su expresión somos aquí;<br/>Y somos uno_en la localidad,<br/>Para_exhibir nuestra_unidad.<br/>',NULL,189335,2);
INSERT INTO stanza VALUES('S182','2','Un solo pan, Tu cuerpo representa<br/>Quebrado fue para participar;<br/>Y al comer del pan hoy declaramos<br/>Que con los santos es nuestra unidad.<br/>',NULL,189336,3);
INSERT INTO stanza VALUES('S182','3','Un solo pan y una copa muestran<br/>Que no podemos mas que uno ser;<br/>La redención nos hizo un solo Cuerpo,<br/>Qué se dirá, sino: "‿Señor, Amén!"<br/>',NULL,189337,4);
INSERT INTO stanza VALUES('S182','4','Nuestra unidad no puede dividirse,<br/>Nuestra unidad es sólo en el Señor;<br/>La copa, el pan, tomamos siendo uno,<br/>Y así visible se_hace nuestra unión.<br/>',NULL,189338,5);
INSERT INTO stanza VALUES('S182','5','¡Qué bendición! ¡Qué gozo el ser uno!<br/>Sentimos del Señor satisfacción;<br/>Contigo este gozo disfrutamos:<br/>¡Primicias de las bodas del Señor!<br/>',NULL,189339,6);
INSERT INTO stanza VALUES('S183','1','Come_el pan, oh pueblo del Señor,<br/>Alabad Su nombre_en unidad.<br/>Hoy venimos para_así comer<br/>Con la_iglesia de Su heredad.<br/>',NULL,189340,1);
INSERT INTO stanza VALUES('S183','chorus','¡Con el vino come de este pan!<br/>Somos uno siempre en Él.<br/>Sobre el terreno firme_estad<br/>Hoy en la localidad.<br/>',NULL,189341,2);
INSERT INTO stanza VALUES('S183','2','Bebe el vino, pueblo del Señor,<br/>Somos la iglesia que El compró;<br/>Redimidos para uno ser,<br/>Es la meta que Él siempre buscó.<br/>',NULL,189342,3);
INSERT INTO stanza VALUES('S183','chorus','¡Con el vino come de este pan!<br/>Somos uno siempre en Él.<br/>Sobre el terreno firme_estad<br/>Hoy en la localidad.<br/>',NULL,189343,4);
INSERT INTO stanza VALUES('S183','3','Uno sed, oh pueblo del Señor,<br/>No seáis un grano individual.<br/>Somos uno, amasados bien,<br/>Como un pan en la localidad.<br/>',NULL,189344,5);
INSERT INTO stanza VALUES('S183','chorus','¡Con el vino come de este pan!<br/>Somos uno siempre en Él.<br/>Sobre el terreno firme_estad<br/>Hoy en la localidad.<br/>',NULL,189345,6);
INSERT INTO stanza VALUES('S183','4','Somos uno, oh pueblo del Señor,<br/>Declaramos hoy nuestra unidad;<br/>Testifica lo que Dios obró;<br/>No palabras, sino realidad.<br/>',NULL,189346,7);
INSERT INTO stanza VALUES('S183','chorus','¡Con el vino come de este pan!<br/>Somos uno siempre en Él.<br/>Sobre el terreno firme_estad<br/>Hoy en la localidad.<br/>',NULL,189347,8);
INSERT INTO stanza VALUES('S183','5','Come el pan, oh pueblo del Señor,<br/>Alabad Su nombre en unidad.<br/>Hoy venimos para así comer<br/>Con la iglesia de Su heredad.<br/>',NULL,189348,9);
INSERT INTO stanza VALUES('S183','note','**No se repite el coro después de la última estrofa.**<br/>',NULL,189349,10);
INSERT INTO stanza VALUES('S184','1','Tomad la copa hoy,<br/>La redención de Dios;<br/>Jesus logró la paz<br/>Con Su sangre_eficaz.<br/>Con Cristo_el Hijo_hay comunión:<br/>Todo_en la cruz Él consumó,<br/>Y el camino nos abrió.<br/>',NULL,189350,1);
INSERT INTO stanza VALUES('S184','2','Tomad, hay que beber<br/>Con todos y comer;<br/>Su muerte_hay que anunciar<br/>Hasta que venga Él.<br/>De esta mesa disfrutad,<br/>El pan y vino_asi tomad;<br/>Bendita copa_aquí gustad.<br/>',NULL,189351,2);
INSERT INTO stanza VALUES('S184','3','La sangre animal<br/>No nos puede salvar<br/>De_este pecado vil,<br/>Aunque años pasen mil.<br/>Solo_un Dios-hombre puede ser<br/>La_ofrenda para nuestro bien:<br/>Sin manchas, el Cordero fiel.<br/>',NULL,189352,3);
INSERT INTO stanza VALUES('S184','4','Su sangre disfrutad,<br/>Fluyendo siempre está;<br/>Su poder limpiador<br/>Es nuestro_acceso_a Dios.<br/>Un solo sacrificio hay<br/>A la conciencia le da paz<br/>¡La redención pagada_está!<br/>',NULL,189353,4);
INSERT INTO stanza VALUES('S184','5','¡Oh Redentor y Rey<br/>En Tu sangre se ve<br/>Tu_amor y Tu bondad<br/>Que nos hacen cantar!<br/>Nos trae la copa bendición,<br/>Tu sangre_un nuevo pacto dio;<br/>Preciosa sangre, ¡qué porción!<br/>',NULL,189354,5);
INSERT INTO stanza VALUES('S185','1','Señor Jesús, presentes en Tu mesa,<br/>El vino_y pan podemos contemplar;<br/>Te alabamos por ser alimento<br/>Que todo hombre puede disfrutar.<br/>',NULL,189355,1);
INSERT INTO stanza VALUES('S185','chorus','Todo mi ser canta_alabanza a Ti,<br/>¡Oh, cuán pequeño eres, Señor!<br/>Te comeremos por la_eternidad,<br/>¡Oh, cuán pequeño_eres, Señor!<br/>',NULL,189356,2);
INSERT INTO stanza VALUES('S185','2','Qué triste es que Cristo vino_al mundo,<br/>Con Sus riquezas para vida dar;<br/>Mas vive_el hombre por las enseñanzas,<br/>Y Sus riquezas no quiere_aplicar.<br/>',NULL,189357,3);
INSERT INTO stanza VALUES('S185','chorus','Pero al Señor tenemos que comer;<br/>¡Qué noble es El! ¡Qué_excelso es!<br/>El nos restaura al comer de El,<br/>Y crecerá en nuestro ser.<br/>',NULL,189358,4);
INSERT INTO stanza VALUES('S185','3','Señor Jesús, Tú no viniste al mundo,<br/>Para reinar externamente aquí;<br/>Más Tú viniste como el alimento<br/>Que en vida nutre y nos guía así.<br/>',NULL,189359,5);
INSERT INTO stanza VALUES('S185','chorus','Todo mi ser canta_alabanza a Ti,<br/>¡Oh, cuán pequeño eres, Señor!<br/>Te comeremos por la_eternidad,<br/>¡Oh, cuán pequeño_eres, Señor!<br/>',NULL,189360,6);
INSERT INTO stanza VALUES('S185','4','Señor Jesús, Tu grandeza admiramos,<br/>Y te alabamos por Tu gran poder;<br/>Pero especiales gracias hoy te damos,<br/>Pues lo que eres se puede comer.<br/>',NULL,189361,7);
INSERT INTO stanza VALUES('S185','chorus','Todo mi ser canta_alabanza a Ti,<br/>¡Oh, cuán pequeño eres, Señor!<br/>Te comeremos por la_eternidad,<br/>¡Oh, cuán pequeño_eres, Señor!<br/>',NULL,189362,8);
INSERT INTO stanza VALUES('S186','1','¡Qué gloriosa es Tu mesa, Señor!<br/>Es la mesa de Tu casa,<br/>De Tu hogar, Tu real morada,<br/>¡Qué gloriosa es Tu mesa, Señor!<br/>',NULL,189363,1);
INSERT INTO stanza VALUES('S186','chorus','¡Aleluya, aleluya!<br/>¡Aleluya, qué festín!<br/>¡Aleluya, aleluya!<br/>¡Qué gloriosa es Tu mesa, Señor!<br/>',NULL,189364,2);
INSERT INTO stanza VALUES('S186','2','¡Disfrutable es Tu mesa, Señor!<br/>Donde comunión tenemos;<br/>¡Aleluya, la encontramos!<br/>¡Disfrutable es Tu mesa, Señor!<br/>',NULL,189365,3);
INSERT INTO stanza VALUES('S186','3','¡Qué preciosa es Tu mesa, Señor!<br/>Vino y pan Tu muerte anuncian,<br/>Mi alma á todo aquí renuncia,<br/>Mientras como en Tu mesa, Señor.<br/>',NULL,189366,4);
INSERT INTO stanza VALUES('S186','4','¡Insondable es Tu mesa, Señor!<br/>En el pan todos nos vemos,<br/>Tu expresión de amor tenemos;<br/>¡Insondable es Tu mesa, Señor!<br/>',NULL,189367,5);
INSERT INTO stanza VALUES('S186','5','¡Refrescante es Tu mesa, Señor!<br/>Totalmente satisface,<br/>Diariamente nos complace,<br/>¡Refrescante es Tu mesa, Señor!<br/>',NULL,189368,6);
INSERT INTO stanza VALUES('S186','6','¡Qué animante es Tu mesa, Señor!<br/>Me recuerda Tu venida,<br/>Esperanza de mis días;<br/>¡Qué animante es Tu mesa, Señor!<br/>',NULL,189369,7);
INSERT INTO stanza VALUES('S187','1','Ved la mesa_aderezada,<br/>Con la copa_y con el pan;<br/>Ved, el Salvador espera<br/>Que vengamos a cenar.<br/>Él nos llama: "Ven y cena<br/>Tú conmigo_en comunión".<br/>Él nos preparó Su mesa;<br/>Disfrutemos al  Señor.<br/>',NULL,189370,1);
INSERT INTO stanza VALUES('S187','2','Con Jesús hoy festejamos;<br/>¡Oh, qué gusto_estar con Él!<br/>¡Aleluya! ¡Aleluya!<br/>¡Un banquete_eterno es!<br/>Al comer, Señor, contigo,<br/>Gran satisfacción nos das;<br/>Es primicia del banquete<br/>Que con Tu novia tendrás.<br/>',NULL,189371,2);
INSERT INTO stanza VALUES('S188','1','Tú mismo eres la ofrenda<br/>De paz, nuestro Señor;<br/>Poniendo_en Ti las manos,<br/>Se muestra nuestra unión.<br/>Reunidos en la tienda<br/>Te ofrecemos hoy<br/>Y_a Ti te disfrutamos<br/>Con nuestro Padre Dios.<br/>',NULL,189372,1);
INSERT INTO stanza VALUES('S188','chorus','¡Cristo es la paz! ¡Cristo es la paz!<br/>¡Tú eres la paz, Señor!<br/>Has restaurado nuestra paz<br/>Con hombres y con Dios.<br/>',NULL,189373,2);
INSERT INTO stanza VALUES('S188','2','Qué paz al ver la sangre<br/>Rociada alrededor;<br/>La sangre de Tu ofrenda<br/>Nos trae la paz con Dios.<br/>Valientes, proclamamos:<br/>"Escucha, Satanás:<br/>¡El triunfo está en la sangre<br/>De Cristo, nuestra paz!"<br/>',NULL,189374,3);
INSERT INTO stanza VALUES('S188','chorus','¡Cristo es la paz! ¡Cristo es la paz!<br/>¡Tú eres la paz, Señor!<br/>Has restaurado nuestra paz<br/>Con hombres y con Dios.<br/>',NULL,189375,4);
INSERT INTO stanza VALUES('S188','3','Sobre el holocausto<br/>La flor de harina está;<br/>Allí se ofrece a Cristo,<br/>Como ofrenda de paz.<br/>Comiendo y bebiendo<br/>De Su humanidad,<br/>Reunidos con los santos<br/>Se le disfrutará.<br/>',NULL,189376,5);
INSERT INTO stanza VALUES('S188','chorus','¡Qué comunión, qué comunión<br/>Con hombres y con Dios!<br/>Oh, cuánta paz y qué festín<br/>Se goza en tal reunión.<br/>',NULL,189377,6);
INSERT INTO stanza VALUES('S188','4','Oculta y tan dulce,<br/>Dios goza Su porción;<br/>Y el pecho que se mece<br/>Se come frente a Dios.<br/>Le toca al sacerdote<br/>Comer de lo mejor<br/>La torta y la espaldilla<br/>Derecha que elevó.<br/>',NULL,189378,7);
INSERT INTO stanza VALUES('S188','chorus','¡Cristo es la paz! ¡Cristo es la paz!<br/>¡Tú eres la paz, Señor!<br/>Has restaurado nuestra paz<br/>Con hombres y con Dios.<br/>',NULL,189379,8);
INSERT INTO stanza VALUES('S188','5','El pecho que se mece<br/>Nos habla del amor<br/>Del Cristo levantado,<br/>Que arriba nos llevó.<br/>La torta y la espaldilla<br/>De Aquel que ascendió<br/>Nos nutre con Su fuerza,<br/>Para seguir a Dios.<br/>',NULL,189380,9);
INSERT INTO stanza VALUES('S188','chorus','¡Cristo es la paz! ¡Cristo es la paz!<br/>¡Tú eres la paz, Señor!<br/>Has restaurado nuestra paz<br/>Con hombres y con Dios.<br/>',NULL,189381,10);
INSERT INTO stanza VALUES('S188','6','Limpiados comeremos<br/>De Cristo el buen manjar,<br/>Y comunión genuina<br/>Podemos disfrutar.<br/>Con agradecimiento<br/>Un votó hacemos hoy:<br/>Somos para el recobro<br/>Glorioso del Señor.<br/>',NULL,189382,11);
INSERT INTO stanza VALUES('S188','chorus','¡Cristo es la paz! ¡Cristo es la paz!<br/>¡Tú eres la paz, Señor!<br/>Has restaurado nuestra paz<br/>Con hombres y con Dios.<br/>',NULL,189383,12);
INSERT INTO stanza VALUES('S189','1','Bendición, honra y gloria sea a Ti,<br/>Y gloria sea a Ti,<br/>Y gloria sea a Ti.<br/>Bendición, honra y gloria sea a Ti,<br/>Ahora y por siempre.<br/>',NULL,189384,1);
INSERT INTO stanza VALUES('S189','chorus','¡A-la-bad-le<br/>Vosotros Sus santos!<br/>¡A - do - rad - le!<br/>Ahora ;y por siempre.<br/>¡A-le-lu- ya!<br/>',NULL,189385,2);
INSERT INTO stanza VALUES('S189','2','Bendición, honra y gloria sea a Ti,<br/>Y gloria sea a Ti,<br/>Y gloria sea a Ti.<br/>Bendición, honra y gloria sea a Ti,<br/>Ahora y por siempre.<br/>',NULL,189386,3);
INSERT INTO stanza VALUES('S190','1','Alelu, Alelu, Alelu, Aleluya,<br/>¡Gloria al Señor!<br/>Alelu, Alelu, Alelu, Aleluya,<br/>¡Gloria al Señor!<br/>Gloria al Señor, ¡Aleluya!<br/>Gloria al Señor, ¡Aleluya!<br/>Gloria al Señor, ¡Aleluya!<br/>¡Gloria al Señor!<br/>',NULL,189387,1);
INSERT INTO stanza VALUES('S191','1','El Espíritu de Dios<br/>Es el mismo de Jesús,<br/>El Dios-hombre que murió,<br/>Y a la gloria ascendió.<br/>',NULL,189388,1);
INSERT INTO stanza VALUES('S191','2','De parte de_este Jesús<br/>Vino el Espíritu,<br/>Trayendo Su realidad<br/>A mi_experiencia vital.<br/>',NULL,189389,2);
INSERT INTO stanza VALUES('S191','3','Espíritu de Jesús,<br/>Divino-humano es,<br/>Tiene la gloria de Dios<br/>Y el vivir humano_en Él.<br/>',NULL,189390,3);
INSERT INTO stanza VALUES('S191','4','Los sufrimientos de Él,<br/>Con Su muerte eficaz,<br/>Reinando_y resurrección,<br/>En Su Espíritu están.<br/>',NULL,189391,4);
INSERT INTO stanza VALUES('S191','5','Todo lo que_es de Jesús<br/>Nos trae Su Espíritu,<br/>Y por Su rica unción<br/>Probamos de Su virtud.<br/>',NULL,189392,5);
INSERT INTO stanza VALUES('S191','6','Incluye el Espíritu<br/>Todo lo que es Jesús,<br/>El obra para_obtener<br/>Que Dios llene nuestro ser.<br/>',NULL,189393,6);
INSERT INTO stanza VALUES('S192','1','Hoy el Espíritu de Dios<br/>La realidad de Cristo es;<br/>Es Cristo en mi espíritu<br/>Viviendo dentro de mi ser.<br/>',NULL,189394,1);
INSERT INTO stanza VALUES('S192','2','Tal como Cristo expresa Dios<br/>Y es Su corporificación,<br/>Así el Espíritu también<br/>Es para Cristo Su expresión.<br/>',NULL,189395,2);
INSERT INTO stanza VALUES('S192','3','La plenitud del Padre Dios<br/>Corporalmente en Cristo está;<br/>Y Cristo tomó Espíritu<br/>Es hoy nuestra realidad.<br/>',NULL,189396,3);
INSERT INTO stanza VALUES('S192','4','El Padre en el Hijo está<br/>Y el Hijo el Espíritu es;<br/>El Padre unido al Hijo está<br/>Con el Espíritu a mi ser.<br/>',NULL,189397,4);
INSERT INTO stanza VALUES('S192','5','Con fuerza del Espíritu<br/>Hoy Cristo en mí hará Su hogar;<br/>Y el Padre con Su plenitud<br/>Mi ser entero ha de llenar.<br/>',NULL,189398,5);
INSERT INTO stanza VALUES('S192','6','El Padre en Cristo nuestro es,<br/>El llena nuestra escasez;<br/>Probamos en Espíritu<br/>Que Cristo_el todo_en todo es.<br/>',NULL,189399,6);
INSERT INTO stanza VALUES('S192','7','Señor, por Tu Espíritu<br/>Impártenos Tu realidad,<br/>Hasta llenarnos de Tu ser<br/>Y Tus riquezas disfrutar.<br/>',NULL,189400,7);
INSERT INTO stanza VALUES('S193','1','El Santo Espíritu de Dios,<br/>Espíritu de  vida  es;<br/>Me da la vida divinal,<br/>Para lograr Su buen placer.<br/>',NULL,189401,1);
INSERT INTO stanza VALUES('S193','2','Como agua viva a mi sed,<br/>De Su torrente vida da;<br/>Al impartir a Cristo en mí<br/>Mi hambre El satisfará.<br/>',NULL,189402,2);
INSERT INTO stanza VALUES('S193','3','Como la luz de vida Él<br/>Disipa toda oscuridad;<br/>Al impartir a Cristo en mí<br/>Mi noche en día cambiará.<br/>',NULL,189403,3);
INSERT INTO stanza VALUES('S193','4','Infunde vida con poder<br/>A todo mi hombre interior;<br/>Al impartir a Cristo así<br/>Se cumple en mí el plan de Dios.<br/>',NULL,189404,4);
INSERT INTO stanza VALUES('S193','5','Él por Su ley de vida en mí<br/>Me libra de la ley del mal;<br/>Y por Su esencia divinal<br/>Él siempre me regulará.<br/>',NULL,189405,5);
INSERT INTO stanza VALUES('S193','6','Como el Espíritu en mi ser<br/>Su vida fruto llevará;<br/>Al expresar a Dios así,<br/>Trae Cristo en vida a los demás.<br/>',NULL,189406,6);
INSERT INTO stanza VALUES('S193','7','Por vida el Espíritu<br/>Mi ser hoy transformando está;<br/>Renueva todo mi interior,<br/>Y a Cristo me conformará.<br/>',NULL,189407,7);
INSERT INTO stanza VALUES('S193','8','Oh, que Tu Espíritu, Señor,<br/>Me llene por completo a mí,<br/>Con esa vida divinal,<br/>Hasta que yo te exprese a Ti.<br/>',NULL,189408,8);
INSERT INTO stanza VALUES('S194','1','Doquiera_el hombre esté, las nuevas anunciad<br/>A todo corazón que sufra aflicción;<br/>Con gozo y fervor, cristianos proclamad:<br/>¡Llegó el Consolador!<br/>',NULL,189409,1);
INSERT INTO stanza VALUES('S194','chorus','¡Llegó el Consolador!<br/>¡Llegó el Consolador!<br/>El Santo Espíritu:<br/>Promesa del Señor.<br/>Las nuevas anunciad,<br/>Doquiera_el hombre_esté:<br/>¡Llegó el Consolador!<br/>',NULL,189410,2);
INSERT INTO stanza VALUES('S194','2','Quedó la noche atrás, va_el alba_a despuntar,<br/>Se calma el gemir, pasó la tempestad;<br/>El día_avanza ya, dorado_el monte_está:<br/>¡Llegó el Consolador!<br/>',NULL,189411,3);
INSERT INTO stanza VALUES('S194','3','¡Oh Rey de reyes, traen Tus alas sanidad!<br/>Cautivas almas hoy reciben libertad;<br/>Vacías celdas dan un cántico triunfal:<br/>¡Llegó el Consolador!<br/>',NULL,189412,4);
INSERT INTO stanza VALUES('S194','4','¡Divino_inmenso amor! ¿Cómo podré contar<br/>A todo pecador la gracia divinal?<br/>Que un hijo infernal ¡Su_imagen lleve hoy!<br/>¡Llegó el Consolador!<br/>',NULL,189413,5);
INSERT INTO stanza VALUES('S195','1','Desmayando estaba<br/>El pueblo, Israel,<br/>Cuando Jehová daba<br/>Un mandato fiel:<br/>Sólo con fe<br/>A la Roca hablad,<br/>Agua de vida<br/>Ella te dará;<br/>Sólo con fe<br/>A la Roca_hablad.<br/>',NULL,189414,1);
INSERT INTO stanza VALUES('S195','chorus','Sólo con fe<br/>A la Roca hablad,<br/>El agua viva<br/>De_ella fluirá;<br/>No dudes más, pues<br/>El Espíritu<br/>Quiere que bebas<br/>De Su plenitud.<br/>',NULL,189415,2);
INSERT INTO stanza VALUES('S195','2','Esa Roca_eterna<br/>Hoy abierta está;<br/>Su_Espíritu Santo<br/>Aún puede llenar;<br/>Oye Su voz:<br/>"No vaciles más.<br/>Al Espíritu_habla<br/>Con un susurrar".<br/>Sólo con fe,<br/>A la Roca_hablad.<br/>',NULL,189416,3);
INSERT INTO stanza VALUES('S195','3','Que con fe sencilla<br/>Pueda yo creer;<br/>Que, como_un infante,<br/>Pueda yo beber.<br/>Como_el bebé<br/>Que_en el pecho está,<br/>Mi_espíritu_halle<br/>En Tu seno paz,<br/>Lleno de Ti,<br/>Vida Eternal.<br/>',NULL,189417,4);
INSERT INTO stanza VALUES('S196','1','Fluye de mí, Señor, un váso frágil,<br/>Que redimiste para_en Ti servir.<br/>Fluye de mi, yo me he consagrado<br/>A Tu servicio tan querido_a mi.<br/>',NULL,189418,1);
INSERT INTO stanza VALUES('S196','2','Fluye de mí, Señor, en abundancia,<br/>Hazme sentir hoy Tu profundo_amor.<br/>Forja en mí la fe que mueve montes,<br/>Como_el poder que salva_al pecador.<br/>',NULL,189419,2);
INSERT INTO stanza VALUES('S196','3','Fluye de mí hasta que los cautivos<br/>Sean librados de su_esclavitud;<br/>Fluye de mí hasta que, en Tu fuente,<br/>Encuentren sanidad y plenitud.<br/>',NULL,189420,3);
INSERT INTO stanza VALUES('S196','4','Fluye de mí hasta que, en victoria,<br/>Canten los derrotados su canción;<br/>Y esos labios mudos te alaben<br/>Junto con los que gozan salvación.<br/>',NULL,189421,4);
INSERT INTO stanza VALUES('S196','5','Fluye de mí, hasta que broten aguas<br/>Que sacien almas de su_intensa sed.<br/>Fluye de mí hasta que los desiertos<br/>De rosas frescas puedan florecer.<br/>',NULL,189422,5);
INSERT INTO stanza VALUES('S196','6','Fluye de mí, hasta que toda mi alma<br/>Resuene con Tu inefable_amor.<br/>Fluye de mí hasta que nada pueda<br/>Saciar mi ser, más sólo Tú, Señor.<br/>',NULL,189423,6);
INSERT INTO stanza VALUES('S197','1','Sube,_oh pozo, de agua,<br/>Señor, cava_en mi alma;<br/>Quita las barreras,<br/>Para que_en mí fluyas.<br/>',NULL,189424,1);
INSERT INTO stanza VALUES('S197','2','Cristo, Roca hendida,<br/>Agua viva bulle;<br/>Pero en mi alma<br/>Algo la obstruye.<br/>',NULL,189425,2);
INSERT INTO stanza VALUES('S197','3','Cavaré orando,<br/>Sacaré la tierra,<br/>¡Oh que libremente<br/>Tu Espíritu fluya!<br/>',NULL,189426,3);
INSERT INTO stanza VALUES('S197','4','Hoy golpear la Roca<br/>No es necesario;<br/>Basta con que cave<br/>En mi ser a diario.<br/>',NULL,189427,4);
INSERT INTO stanza VALUES('S197','5','Mi profundo anhelo<br/>Es que Tú me llenes,<br/>Hasta que_agua viva<br/>De mi alma salte.<br/>',NULL,189428,5);
INSERT INTO stanza VALUES('S197','6','Cava hasta que quites<br/>Todo lo que obstruya;<br/>Cava_hasta que el agua<br/>Tu mensaje fluya.<br/>',NULL,189429,6);
INSERT INTO stanza VALUES('S197','7','Sube, oh pozo, de agua,<br/>Señor, cava_en mi alma;<br/>Quita las barreras,<br/>Para que_en mí fluyas.<br/>',NULL,189430,7);
INSERT INTO stanza VALUES('S198','1','Ríos de agua viva<br/>Fluyen del trono de Dios,<br/>Rebosan con bendiciones,<br/>Vienen de nuestro Señor.<br/>',NULL,189431,1);
INSERT INTO stanza VALUES('S198','chorus','Ríos de agua viva<br/>Fluyen con gran libertad;<br/>Oh, Salvador, que_estos ríos<br/>En mí hoy puedan brotar.<br/>',NULL,189432,2);
INSERT INTO stanza VALUES('S198','2','Todo sediento venga<br/>Al abundante caudal;<br/>De las aguas cristalinas<br/>Sin plata puede comprar.<br/>',NULL,189433,3);
INSERT INTO stanza VALUES('S198','3','Límpiame, Salvador mío,<br/>Hazme ahora un canal,<br/>Enséñame a servirte,<br/>A_obedecer y confiar.<br/>',NULL,189434,4);
INSERT INTO stanza VALUES('S198','4','Sólo de esta manera<br/>Ríos saldrán de mi ser;<br/>Para que así otros puedan<br/>Tu plenitud conocer.<br/>',NULL,189435,5);
INSERT INTO stanza VALUES('S198','5','Hoy a Jesús yo me rindo,<br/>Pongo mi todo_a Sus pies;<br/>Cualquier lugar o servicio<br/>Lo que_Él desee, haré.<br/>',NULL,189436,6);
INSERT INTO stanza VALUES('S199','1','Al hogar, al hogar, al hogar de Dios,<br/>Donde_está_el manantial he venido yo,<br/>Un fluir hay aquí que no cesará,<br/>Y_hace crecer vida hasta madurar.<br/>',NULL,189437,1);
INSERT INTO stanza VALUES('S199','2','Fluye aquí, fluye aquí un río que va,<br/>Por la tierra a proveer la vida especial;<br/>Pero ve, oh Señor, más profundo aún,<br/>Hasta que nos midas y poseas Tú.<br/>',NULL,189438,2);
INSERT INTO stanza VALUES('S199','3','Mídenos, mídenos, mide en verdad,<br/>Mídenos, mídenos cada día más;<br/>Hasta ver que_el fluir, torrente de Dios,<br/>Inunde la tierra por Cristo el Señor.<br/>',NULL,189439,3);
INSERT INTO stanza VALUES('S199','4','Llévanos, llévanos por este fluir,<br/>Llévanos más y más, todo hay que medir;<br/>Fluye más, sin cesar, por la eternidad,<br/>Hasta sumergirnos en Su realidad.<br/>',NULL,189440,4);
INSERT INTO stanza VALUES('S199','5','Vivirá, vivirá, todo vivirá,<br/>Vivirá en verdad donde el río está,<br/>Una fuente saldrá para vida dar,<br/>Brotarán iglesias por todo lugar.<br/>',NULL,189441,5);
INSERT INTO stanza VALUES('S200','1','Sopla en mí Tu Espíritu hasta<br/>Inhalarte en mí, Señor;<br/>Desahogándome en Tu pecho<br/>Del pecado y del yo.<br/>',NULL,189442,1);
INSERT INTO stanza VALUES('S200','chorus','Exhalando, exhalando<br/>Culpas y pesar;<br/>Inhalando, inhalando<br/>De Tu gran caudal.<br/>',NULL,189443,2);
INSERT INTO stanza VALUES('S200','2','Exhalando yo mi vida,<br/>Hoy la Tuya ganaré;<br/>Inhalando Tu persona<br/>Yo la mía perderé.<br/>',NULL,189444,3);
INSERT INTO stanza VALUES('S200','3','Exhalando el viejo hombre<br/>Que llevaste a la cruz;<br/>Inhalando yo Tu vida<br/>Brota_en mí Tu pulcritud.<br/>',NULL,189445,4);
INSERT INTO stanza VALUES('S200','4','Exhalando mi tristeza<br/>En Tu pechó alentador;<br/>Yo inhalo el consuelo<br/>Y_el descanso de Tu_amor.<br/>',NULL,189446,5);
INSERT INTO stanza VALUES('S200','5','Exhalando_enfermedades<br/>Que llevaste Tú por mí;<br/>Inhalando sanidades<br/>Me renuevo siempre_en Ti.<br/>',NULL,189447,6);
INSERT INTO stanza VALUES('S200','6','Exhalando mis anhelos<br/>En Tu_oído consultor;<br/>Inhalando Tus respuestas,<br/>Calmas todo mi temor.<br/>',NULL,189448,7);
INSERT INTO stanza VALUES('S200','7','Respirando_a cada instante<br/>Cobro vida yo por Ti;<br/>Soplo_a soplo_en Ti viviendo,<br/>Sóplate, Señor, en mí.<br/>',NULL,189449,8);
INSERT INTO stanza VALUES('S201','1','Oh, sopla_aquí Señor, sobre Tu pueblo hoy;<br/>Oh, ¡recio viento, ven y trae liberación!<br/>Oh, sopla hasta que nos puedas avivar;<br/>¡Sopla, Señor, oramos hoy!<br/>',NULL,189450,1);
INSERT INTO stanza VALUES('S201','chorus','¡Oh, sopla hoy con gran poder!<br/>De la tibieza sálvanos;<br/>¡Oh, ven gran viento y restáuranos aquí!<br/>¡Sopla, Señor, oramos hoy!<br/>',NULL,189451,2);
INSERT INTO stanza VALUES('S201','2','Oh, sopla con Tu_amor; aviva el corazón;<br/>Aliento celestial, ¡oh, ven, anímanos!<br/>Oh, sopla, para_así nuestra frialdad quitar;<br/>¡Sopla, Señor, oramos hoy!<br/>',NULL,189452,3);
INSERT INTO stanza VALUES('S201','3','Oh, sopla con poder en nuestro espíritu;<br/>Oh, sopla,_inspíranos con Tu divina luz;<br/>Oh, sopla hasta que un fuego prendas Tú;<br/>¡Sopla, Señor, oramos hoy!<br/>',NULL,189453,4);
INSERT INTO stanza VALUES('S202','1','Manda del cielo_el Viento Tú,<br/>A nosotros aquí;<br/>Con fuerza_y con poder Señor,<br/>Despliégalo así.<br/>',NULL,189454,1);
INSERT INTO stanza VALUES('S202','chorus','Descienda Tu Espíritu;<br/>Sopla, Señor, aquí;<br/>Que trascendamos con poder<br/>En Tu vivo fluir.<br/>',NULL,189455,2);
INSERT INTO stanza VALUES('S202','2','Toda barrera rompa_al fin<br/>Tu_Espíritu_en poder;<br/>Tu_Espíritu de vida hoy<br/>Exhala_en nuestro ser.<br/>',NULL,189456,3);
INSERT INTO stanza VALUES('S202','3','Es séptuple Tu_Espíritu;<br/>Compartimos de Ti;<br/>Oh, danos la_experiencia real<br/>Del Triuno Dios aquí.<br/>',NULL,189457,4);
INSERT INTO stanza VALUES('S203','1','"Unánimes" y fieles a Jesús,<br/>En aquel aposento_en oración,<br/>Una esperanza_a todos los unió,<br/>Y_un objetivo_a todos poseyó.<br/>',NULL,189458,1);
INSERT INTO stanza VALUES('S203','2','"Unánimes" así en Pentecostés<br/>Fue derramado el poder de Dios;<br/>Luego testigos fueron del Señor<br/>¡Y predicaron Su resurrección!<br/>',NULL,189459,2);
INSERT INTO stanza VALUES('S203','3','"Unánimes" en la casa de Dios<br/>Cantan a diario himnos de loor;<br/>Con "aleluyas", todos a_una voz,<br/>Van alabando_el nombre del Señor.<br/>',NULL,189460,3);
INSERT INTO stanza VALUES('S203','4','Señor, Tu_Espíritu derrama hoy,<br/>"Lluvia tardía" manda_a nuestro ser;<br/>Une_a Tu pueblo en un corazón,<br/>¡Y vendrán días de Pentecostés!<br/>',NULL,189461,4);
INSERT INTO stanza VALUES('S204','1','Como Espíritu hoy ven,<br/>Te abrimos nuestro ser;<br/>Con el Hijo_y Padre ven<br/>Para_así Tu gloria ver.<br/>',NULL,189462,1);
INSERT INTO stanza VALUES('S204','chorus','¡Como Espíritu, oh ven!<br/>¡Tu gran obra haznos ver!<br/>Sacia_así nuestro clamor;<br/>Anhelamos Tu ardor;<br/>Con Tu fuego,<br/>Sacia_así nuestro clamor.<br/>',NULL,189463,2);
INSERT INTO stanza VALUES('S204','2','Puestos sobre el altar:<br/>Cuerpo, alma_y voluntad.<br/>Aniquila mi maldad<br/>Para_así mi ser llenar.<br/>',NULL,189464,3);
INSERT INTO stanza VALUES('S204','3','Sacrificio_hacemos hoy,<br/>Aunque muy costoso es,<br/>Para nuestro Salvador,<br/>Quien por nosotros sangró.<br/>',NULL,189465,4);
INSERT INTO stanza VALUES('S204','4','Hoy reclamo_el don por fe,<br/>Por Tu sangre se me dio;<br/>Por el nombre de poder,<br/>Tus promesas mías son.<br/>',NULL,189466,5);
INSERT INTO stanza VALUES('S205','1','Jesús, Tu victorioso_amor<br/>Fue derramado_en mí.<br/>No vagará mi corazón<br/>Si fijo_está en Ti,<br/>Si fijo_está en Ti.<br/>',NULL,189467,1);
INSERT INTO stanza VALUES('S205','2','Oh, que Tu santo fuego_en mí<br/>Comience a arder,<br/>Quemado_así la_escoria vil;<br/>Que fluyas en mi ser,<br/>Que fluyas en mi ser.<br/>',NULL,189468,2);
INSERT INTO stanza VALUES('S205','3','Él, quien bajó en Pentecostés,<br/>Calcine mi maldad.<br/>Te_invoco: Santo:Espíritu,<br/>Trae fuego del altar,<br/>Trae fuego del altar.<br/>',NULL,189469,3);
INSERT INTO stanza VALUES('S205','4','Que brille_en mi_alma_intensa luz,<br/>Fuego refinador;<br/>Tu vida_esparce_y Tu virtud<br/>En santificación,<br/>En santificación.<br/>',NULL,189470,4);
INSERT INTO stanza VALUES('S205','5','Entonces mi_alma ha de ser<br/>Constante, firme_y fiel,<br/>Cuando de Cristo llena_esté<br/>Y sea su todo Él,<br/>Y sea su todo Él.<br/>',NULL,189471,5);
INSERT INTO stanza VALUES('S206','1','Donde se rocía la sangre<br/>Hay ungüento celestial;<br/>Ahí_el hombre a Dios toca<br/>Para_en comunión entrar.<br/>',NULL,189472,1);
INSERT INTO stanza VALUES('S206','2','Es la sangre redentora<br/>La que limpia todo mal;<br/>El Espíritu_es ungüento<br/>Para_al hombre_a Dios llevar.<br/>',NULL,189473,2);
INSERT INTO stanza VALUES('S206','3','La sangre_habla de Su obrá;<br/>El ungüento, de su ser;<br/>Por Su obra y Su persona<br/>Nos mezclamos hoy con Él.<br/>',NULL,189474,3);
INSERT INTO stanza VALUES('S206','4','Por la sangre redentora<br/>Dios nos puede depurar;<br/>Por Su_Espíritu,_el ungüento,<br/>De_Él podemos disfrutar.<br/>',NULL,189475,4);
INSERT INTO stanza VALUES('S206','5','Dios nos limpia, Dios nos unge,<br/>Y nos une_así con Él;<br/>Por la sangre y_el ungüento<br/>Dios es nuestra porción fiel.<br/>',NULL,189476,5);
INSERT INTO stanza VALUES('S206','6','Es por fe que reclamamos<br/>La sangre para limpiar;<br/>La_obediencia al ungüento<br/>Nos permite_en Dios andar.<br/>',NULL,189477,6);
INSERT INTO stanza VALUES('S206','7','Luego lo conoceremos<br/>Como luz y como amor,<br/>Y_en Su vida creceremos<br/>Hasta madurar en Dios.<br/>',NULL,189478,7);
INSERT INTO stanza VALUES('S207','1','Unción divina en mí mora,<br/>Y me_enseña todo_aquí;<br/>En el Señor me guía a vivir,<br/>Su presencia trae a mí.<br/>',NULL,189479,1);
INSERT INTO stanza VALUES('S207','chorus','En mi_espíritu mora la_unción,<br/>Oh, sí mora la unción,<br/>Me ha de enseñar;<br/>En mi espíritu mora la_unción,<br/>Y siempre me enseñará.<br/>',NULL,189480,2);
INSERT INTO stanza VALUES('S207','2','Cuando el Espíritu se mueve,<br/>Suave_y puro_ungüento es;<br/>Y donde_está la sangre eficaz,<br/>Se puede la_unción mover.<br/>',NULL,189481,3);
INSERT INTO stanza VALUES('S207','3','Unge con Su divina esencia<br/>Para darse a conocer,<br/>Para que pueda Su_elemento así<br/>Saturar todo mi ser.<br/>',NULL,189482,4);
INSERT INTO stanza VALUES('S207','4','Por la unción de vida_interna<br/>Yo me muevo_en comunión;<br/>Andando en Dios, la luz de la verdad,<br/>En Su gracia_encuentro amor.<br/>',NULL,189483,5);
INSERT INTO stanza VALUES('S208','1','¡He_aquí la unción! El buen ungüento se_aplicó;<br/>Se mueve en nosotros el Señor.<br/>Es por Su sangre que tenemos comunión,<br/>Y el fluir de vida_es nuestro hoy.<br/>',NULL,189484,1);
INSERT INTO stanza VALUES('S208','note','**Hermanas:**<br/>',NULL,189485,2);
INSERT INTO stanza VALUES('S208','chorus','¡Tenemos la unción hermanos!<br/>¡Creímos y llegó la_unción!<br/>Su_Espíritu se mueve_en el nuestro,<br/>Y esto Él nos lo_otrogó.<br/>',NULL,189486,3);
INSERT INTO stanza VALUES('S208','note','**Hermanos:**<br/>',NULL,189487,4);
INSERT INTO stanza VALUES('S208','chorus','¡Tenemos la unción hermanas!<br/>Este fluir no cesará.<br/>Mientras nos unge, permanecemos:<br/>¡Oh, aleluya! ¡Vida y paz!<br/>',NULL,189488,5);
INSERT INTO stanza VALUES('S208','2','¡He_aquí la unción! Se mezcla con nosotros Dios;<br/>Los dos ahora uno somos ya.<br/>Nuestro vivir, mover y vida siempre es<br/>Por Padre, Hijo y Espíritu.<br/>',NULL,189489,6);
INSERT INTO stanza VALUES('S208','3','¡He_aquí la unción! En todo nos enseña_así,<br/>Por el sentir de vida en nuestro ser.<br/>Sigue_el sentir y tú sabrás lo que_hay que hacer;<br/>Y, por la vida, vive siempre_en Él.<br/>',NULL,189490,7);
INSERT INTO stanza VALUES('S209','1','La encontré en la Palabra,<br/>¡Qué maravillosa es!<br/>No quiero_enseñanza humana,<br/>Pues la_unción vive_en mi ser.<br/>',NULL,189491,1);
INSERT INTO stanza VALUES('S209','chorus','¡Sí,  en  mi espíritu Él se mueve!<br/>¡Sí,  esta unción me unge!<br/>Es el Dios viviente!<br/>Por  Su  Palabra Dios<br/>Me la reveló<br/>Para que yo_aplique<br/>Está_unción que vive_en mí.<br/>',NULL,189492,2);
INSERT INTO stanza VALUES('S209','2','Hace_a Cristo mi_experiencia,<br/>Creo_en Su Palabra fiel;<br/>Como_Espíritu se une<br/>Y se mezcla con mi ser.<br/>',NULL,189493,3);
INSERT INTO stanza VALUES('S209','3','Por Su sangre que nos limpia<br/>Nuestra_unión perdurará;<br/>Cristo, como_unción, se mueve<br/>En aquel que limpio_está.<br/>',NULL,189494,4);
INSERT INTO stanza VALUES('S209','4','Dios en Cristo es la vida<br/>Del Espíritu_en mi ser;<br/>Como_el Santo Él nos unge<br/>Hasta_hacernos como El.<br/>',NULL,189495,5);
INSERT INTO stanza VALUES('S209','5','En mi_espíritu yo toco<br/>Este_ungüento de valor;<br/>Rico, ancho, lleno, hondo.<br/>¡Oh, conozco al mismo Dios!<br/>',NULL,189496,6);
INSERT INTO stanza VALUES('S209','6','Mientras sigo Su ungimiento<br/>Permaneceré en Él;<br/>Él me_enseña, Él me alcanza<br/>Y se adueña de mi ser.<br/>',NULL,189497,7);
INSERT INTO stanza VALUES('S210','1','Es sello_el Santo_Espíritu,<br/>El anticipo y arras es.<br/>Designa que somos de Dios;<br/>Su_herencia garantiza Él.<br/>',NULL,189498,1);
INSERT INTO stanza VALUES('S210','2','Nos selló_el Santo_Espíritu<br/>Después de nosotros creer<br/>En Cristo_y Su_evangelio fiel;<br/>Nos muestra que somos de Dios.<br/>',NULL,189499,2);
INSERT INTO stanza VALUES('S210','3','Nos da la_imagen del gran Dios,<br/>Viviente sello hoy es Él;<br/>Al Hijo nos conforma_así,<br/>Lo_imprime Él en nuestro ser.<br/>',NULL,189500,3);
INSERT INTO stanza VALUES('S210','4','Espíritu las arras es,<br/>El anticipo, fianza fiel.<br/>Confirma que_hijos somos hoy,<br/>Y nuestro Dios, herencia es.<br/>',NULL,189501,4);
INSERT INTO stanza VALUES('S210','5','Por el Espíritu, hoy Dios<br/>Se_extiende_a todo nuestro ser;<br/>Nos sella en nuestro_interior,<br/>Y cada parte llena Él.<br/>',NULL,189502,5);
INSERT INTO stanza VALUES('S210','6','Señor, queremos cooperar<br/>Con Tu mover, Tu_Espíritu;<br/>Obra maestra nos harás,<br/>Tu plan eterno logra ya.<br/>',NULL,189503,6);
INSERT INTO stanza VALUES('S211','1','Alabamos al Señor que<br/>Al Ungido nos unió;<br/>Con la misma_unción divina<br/>De Su Hijo nos ungió.<br/>',NULL,189504,1);
INSERT INTO stanza VALUES('S211','2','En la unción de este Cristo<br/>Los ungidos somos ya;<br/>Qué bendito_es este_ungüento<br/>Que_a Sus hijos hoy les da.<br/>',NULL,189505,2);
INSERT INTO stanza VALUES('S211','3','¡Aleluya! Este ungüento<br/>Habitando_en nuestro ser<br/>Trae a Dios en Su esencia,<br/>Todo nos enseña él.<br/>',NULL,189506,3);
INSERT INTO stanza VALUES('S211','4','Somos del Señor tesoro,<br/>Con Su sangre nos compró;<br/>En nosotros puso el sello<br/>Con el cual Dios nos marcó.<br/>',NULL,189507,4);
INSERT INTO stanza VALUES('S211','5','El nos sella día a día,<br/>Impartiendo así Su ser,<br/>Hasta que Su semejanza<br/>E imagen puedan ver.<br/>',NULL,189508,5);
INSERT INTO stanza VALUES('S211','6','Hoy las arras poseemos<br/>De_este Cristo que vendrá;<br/>Añoramos nuestra herencia:<br/>Dios, gran fiesta eternal.<br/>',NULL,189509,6);
INSERT INTO stanza VALUES('S211','7','Dios con este plan nos hizo<br/>Y las arras nos legó,<br/>Garantía del disfrute<br/>Del Señor en dulce_amor.<br/>',NULL,189510,7);
INSERT INTO stanza VALUES('S211','8','En mi_espíritu las arras<br/>Con el sello y la_unción,<br/>Son depósitos valiosos,<br/>Dulces dones del Señor.<br/>',NULL,189511,8);
INSERT INTO stanza VALUES('S212','1','El Triuno Dios ahora_habita en mí,<br/>Como_Espíritu morando_está;<br/>Yo mezclado_estoy y_unido al Señor,<br/>Como Espíritu que vida da.<br/>',NULL,189512,1);
INSERT INTO stanza VALUES('S212','chorus','¡Oh, el Espíritu vive en mí!<br/>¡Admirable Espíritu_en mí!<br/>Dios está en el Hijo,_ahora el Hijo es<br/>¡El Espíritu de vida en mí!<br/>',NULL,189513,2);
INSERT INTO stanza VALUES('S212','2','“Abba, Padre”_es el gemir en mi interior,<br/>Del Espíritu que vive en mí.<br/>El Espíritu del Hijo gime a Él,<br/>Como_Espíritu de vida en mí.<br/>',NULL,189514,3);
INSERT INTO stanza VALUES('S212','3','Jesucristo el Señor vive_en mí hoy,<br/>Admirable Espíritu_en mí.<br/>Se transfiguró y lo disfruto yo,<br/>Como_Espíritu de vida_en mí.<br/>',NULL,189515,4);
INSERT INTO stanza VALUES('S212','4','El Espíritu de realidad es Él,<br/>Admirable Espíritu en mí.<br/>Hace Él real las cosas del Señor,<br/>El Espíritu de vida en mí.<br/>',NULL,189516,5);
INSERT INTO stanza VALUES('S212','5','Yo despertaré el don de mi interior,<br/>Admirable Espíritu en mí.<br/>Al clamar “¡Señor!” bulle mi espíritu,<br/>Y_el Espíritu de vida_en mí.<br/>',NULL,189517,6);
INSERT INTO stanza VALUES('S213','1','Mirra y canela con<br/>Casia y cálamo<br/>Tus elementos son<br/>Señor Jesús.<br/>Con santo_aceite están<br/>Mezclados en unión;<br/>Con tal preciosa_unción,<br/>Nos unge Dios.<br/>',NULL,189518,1);
INSERT INTO stanza VALUES('S213','chorus','Cristo en Su muerte<br/>Incluye_a este<br/>Compuesto_Espíritu;<br/>Fluye_el ungüento<br/>Con la fragancia<br/>De la resurrección<br/>De mi Señor.<br/>',NULL,189519,2);
INSERT INTO stanza VALUES('S213','2','Uña_aromática<br/>Estacte y gálbano,<br/>Con puro olíbano:<br/>Tal es Jesús.<br/>Estacte hijos da,<br/>Uña libra del mal,<br/>La muerte,_el gálbano<br/>Repelará.<br/>',NULL,189520,3);
INSERT INTO stanza VALUES('S213','chorus','De igual medida son<br/>En la resurrección,<br/>Sazonados con sal;<br/>Molido_en polvo aquí,<br/>Quemado_en fuego así.<br/>¡Incienso sin igual!<br/>Es mi Señor.<br/>',NULL,189521,4);
INSERT INTO stanza VALUES('S213','3','Cristo, como la unción,<br/>Es nuestra bendición;<br/>Mas Cristo para Dios,<br/>Incienso es.<br/>Nos trae la santa unción<br/>A Cristo por porción;<br/>Mas como_incienso El<br/>Asciende a Dios.<br/>',NULL,189522,5);
INSERT INTO stanza VALUES('S213','chorus','Cristo el ungüento<br/>Se experimenta,<br/>Luego se quemará.<br/>Como_el incienso_a Dios,<br/>Cristo en la_oración,<br/>Precioso para Dios,<br/>Ascenderá.<br/>',NULL,189523,6);
INSERT INTO stanza VALUES('S214','1','Te alabamos, oh Dios,<br/>Por el Espíritu,<br/>Que es Cristo_en nosotros<br/>Con vida_y virtud.<br/>¡Aleluya, qué_abundancia<br/>El Espíritu da!<br/>¡Aleluya, esta vida<br/>Jamás cesará!<br/>',NULL,189524,1);
INSERT INTO stanza VALUES('S214','2','Cantamos de_Aquel<br/>Que_a nosotros se unió;<br/>El Espíritu vivo<br/>Que vida nos dio.<br/>¡Aleluya, Jesucristo<br/>El Espíritu es!<br/>¡Aleluya, nuestra vida<br/>Por siempre_ha de ser!<br/>',NULL,189525,2);
INSERT INTO stanza VALUES('S214','3','Nacidos de Él,<br/>Transformándonos va,<br/>Y al Hijo de Dios Él<br/>Nos conformará.<br/>¡Aleluya, vida imparte!<br/>¡Nos transformará!<br/>¡Aleluya, nuestros cuerpos<br/>Transfigurará!<br/>',NULL,189526,3);
INSERT INTO stanza VALUES('S214','4','Nos conformará<br/>Al llenarnos de_Aquel<br/>Que_en espíritu fluye<br/>La vida y_el bien.<br/>¡Aleluya, qué gran premio!<br/>¡Salvación sin igual!<br/>¡Aleluya, sólo basta<br/>Su vida_eternal!<br/>',NULL,189527,4);
INSERT INTO stanza VALUES('S215','1','Con Tu Espíritu de gracia,<br/>Llena mi espíritu;<br/>Y con Tu presencia santa,<br/>¡Ven, Señor, lléname, Tú!<br/>',NULL,189528,1);
INSERT INTO stanza VALUES('S215','chorus','¡Lléname! ¡Lléname!<br/>¡Lléneme Tu_Espíritu!<br/>Me despoje, me vacíe,<br/>¡Lléneme Tu Espíritu!<br/>',NULL,189529,2);
INSERT INTO stanza VALUES('S215','2','Que Tu_Espíritu me llene,<br/>Como sea, no lo sé;<br/>Mas te necesito tanto;<br/>¡Ven, Señor, y lléname!<br/>',NULL,189530,3);
INSERT INTO stanza VALUES('S215','3','Lleno de debilidades,<br/>Vengo a Tus pies, Señor;<br/>Con Tu_Espíritu eterno,<br/>¡Lléname con Tu vigor!<br/>',NULL,189531,4);
INSERT INTO stanza VALUES('S215','4','Lava, salva y bendice;<br/>¡Llena mi espíritu!<br/>Consolando y salvando,<br/>Dulcemente llenas Tú.<br/>',NULL,189532,5);
INSERT INTO stanza VALUES('S216','1','¡Qué glorioso! ¡Qué precioso!<br/>Vive en mí el Espíritu!<br/>La verdad El me revela,<br/>Y me guía con Su luz.<br/>',NULL,189533,1);
INSERT INTO stanza VALUES('S216','chorus','¡Lléname, lléname,<br/>Lléneme Tu_Espíritu!<br/>Me despoje, me vacíe,<br/>Lléneme Tu‿Espíritu.<br/>',NULL,189534,2);
INSERT INTO stanza VALUES('S216','2','Hoy conforme a Tu promesa<br/>Ya Tu vida mora_en mí;<br/>Me libera del pecado,<br/>Y a mi muerte pone fin.<br/>',NULL,189535,3);
INSERT INTO stanza VALUES('S216','3','Yo anhelo_el agua viva;<br/>Tan sediento_estoy de Ti.<br/>Que Tu plenitud yo beba<br/>Hasta que fluyas de mí.<br/>',NULL,189536,4);
INSERT INTO stanza VALUES('S216','4','Oh Señor, que muera_al ego,<br/>Quiero_andar en sumisión;<br/>Oh, transfórmame a Tu imagen,<br/>Hasta que te_exprese yo.<br/>',NULL,189537,5);
INSERT INTO stanza VALUES('S217','1','Salvador, yo te alabo,<br/>Tu amor logró triunfar;<br/>Me_has salvado y llenado<br/>Para_hacerme Tu canal.<br/>',NULL,189538,1);
INSERT INTO stanza VALUES('S217','chorus','Nada más que Tus canales<br/>Somos por Tu gracia hoy,<br/>Mas fluyendo Tú_en nosotros<br/>Nos podrás usar, Señor.<br/>',NULL,189539,2);
INSERT INTO stanza VALUES('S217','2','Un canal de bendiciones<br/>Al sediento corazón,<br/>Que proclame el mensaje<br/>De Tu grande salvación.<br/>',NULL,189540,3);
INSERT INTO stanza VALUES('S217','3','Como_un vaso en Tus manos<br/>Necesito Tu llenar;<br/>No mi fuerza, mas Tu gracia<br/>Tiene que suministrar.<br/>',NULL,189541,4);
INSERT INTO stanza VALUES('S217','4','Testifico de Tu gracia,<br/>Me libró de la maldad;<br/>Me compraste, yo soy Tuyo,<br/>Ven, Señor, lléname ya.<br/>',NULL,189542,5);
INSERT INTO stanza VALUES('S217','5','Que Tu Espíritu hoy llene<br/>El rendido corazón,<br/>Para que las aguas vivas<br/>Fluyan del hombre_interior.<br/>',NULL,189543,6);
INSERT INTO stanza VALUES('S218','1','Con Tu Santo_Espíritu,<br/>LLéname, Señor Jesús;<br/>Que mi vida sea_un canal<br/>Que te pueda expresar;<br/>Tus riquezas dame hoy<br/>Más y más, mi fiel Señor.<br/>',NULL,189544,1);
INSERT INTO stanza VALUES('S218','2','Con Tu Santo_Espíritu,<br/>LLéname, Señor Jesús;<br/>Que se cumpla en mi ser<br/>Tu palabra firme_y fiel;<br/>Que la vida de Jesús<br/>Entre_en mí con Su virtud.<br/>',NULL,189545,2);
INSERT INTO stanza VALUES('S218','3','Con Tu Santo_Espíritu,<br/>LLéname, Señor Jesús;<br/>Limpio, puro_y santo,_así<br/>Que se vea_a Cristo_en mí;<br/>Con Tu gracia_y Tu poder,<br/>Cada día guíame.<br/>',NULL,189546,3);
INSERT INTO stanza VALUES('S218','4','Con Tu Santo_Espíritu,<br/>LLéname, Señor Jesús;<br/>Que Tu gracia, luz y_amor<br/>Fluyan desde mi_interior;<br/>Hasta verte, Salvador,<br/>Lléname de Ti, Señor.<br/>',NULL,189547,4);
INSERT INTO stanza VALUES('S219','1','En espíritu nacimos<br/>Del divino Espíritu;<br/>Como hijos de Dios Padre<br/>Nuestro es Su Espíritu.<br/>Pero_aún necesitamos<br/>Más de Él en nuestro ser;<br/>Que Tu_Espíritu nos llene<br/>¡Abundante vida es!<br/>',NULL,189548,1);
INSERT INTO stanza VALUES('S219','2','El Espíritu de vida<br/>Conocemos hoy, Señor;<br/>Tus riquezas en nosotros<br/>Él nos trae a Tu favor.<br/>Mas aún necesitamos<br/>El poder que Él nos da,<br/>Para que, en Tu servicio<br/>Nos equipe para_obrar.<br/>',NULL,189549,2);
INSERT INTO stanza VALUES('S219','3','Que Tu_Espíritu nos llene<br/>Y nos vista de poder;<br/>Con el manto de Tu fuerza<br/>La batalla pelearé.<br/>Haz soplar Tu viento recio,<br/>Danos fuego celestial,<br/>Úngenos como testigos<br/>Para_hacer Tu voluntad.<br/>',NULL,189550,3);
INSERT INTO stanza VALUES('S219','4','Con Tu_Espíritu potente<br/>Danos dones a la vez;<br/>La función de cada miembro,<br/>Testimonio Tuyo es.<br/>Si Tu_Espíritu derramas,<br/>Dones nos impartirás<br/>Para edificar Tu Cuerpo,<br/>Y Tu bendición vendrá.<br/>',NULL,189551,4);
INSERT INTO stanza VALUES('S219','5','Por Tu gloria_y por Tu reino,<br/>¡Oye_al Cuerpo en su clamar!<br/>Tu propósito se cumpla,<br/>Nuestra hambre sacia hoy.<br/>Que Tu_Espíritu_apliquemos<br/>Sin poner limitación:<br/>Que nos llene, se derrame,<br/>Y_otros gusten de Su don.<br/>',NULL,189552,5);
INSERT INTO stanza VALUES('S220','1','Fue la concepción de Cristo<br/>Por el Espíritu Santo;<br/>Y Su_espíritu_era lleno<br/>Antes de servir a Dios.<br/>Pero_aún fue bautizado<br/>Con poder desde lo alto;<br/>Al inicio de Su obra<br/>El Espíritu  bajó.<br/>',NULL,189553,1);
INSERT INTO stanza VALUES('S220','2','Los discípulos de Cristo,<br/>Del Espíritu nacieron<br/>Cuando Él sopló en ellos<br/>El Espíritu de Dios.<br/>Pero_aún se bautizaron<br/>En el Espíritu Santo<br/>Cuando fueron equipados<br/>Para_así servir a Dios.<br/>',NULL,189554,2);
INSERT INTO stanza VALUES('S220','3','Los de Efeso_y Samaria<br/>Creyeron junto con Saulo,<br/>Y_el Espíritu a todos<br/>Trajo regeneración.<br/>Pero aún se bautizaron<br/>Con Espíritu de lo_alto;<br/>Con la_imposición de manos<br/>Gran poder los revistió.<br/>',NULL,189555,3);
INSERT INTO stanza VALUES('S220','4','Nosotros también nacimos<br/>Del Espíritu al creer,<br/>Y a diario recibimos<br/>El Espíritu_al beber.<br/>Pero_aún necesitamos<br/>Del Espíritu,_el bautismo,<br/>Para_así ser revestidos<br/>Cuando sirvamos a Dios.<br/>',NULL,189556,4);
INSERT INTO stanza VALUES('S220','5','¡Oh que experimentemos<br/>El bautismo espiritual!<br/>Para_así ser revestidos<br/>Con Tu poder divinal.<br/>¡Oh, bautízanos ahora!<br/>Éste es nuestro clamor;<br/>Con poder desde lo alto<br/>Hoy revístenos, Señor.<br/>',NULL,189557,5);
INSERT INTO stanza VALUES('S221','1','Venimos, Señor, hoy con libertad<br/>Para reclamar Tu poder.<br/>Por Tu reino_aquí hay que batallar,<br/>Ascendidos podremos vencer.<br/>',NULL,189558,1);
INSERT INTO stanza VALUES('S221','chorus','De poder, poder desde lo alto,<br/>¡Vístenos, Señor, de Tu poder!<br/>De poder, poder desde lo alto,<br/>Para_el Cuerpo ¡danos Tu poder!<br/>',NULL,189559,2);
INSERT INTO stanza VALUES('S221','2','Oramos Señor, con tenacidad<br/>Para reclamar Tu llover.<br/>Por Tu Cuerpo_aquí lluvia celestial<br/>Mándanos para Tu obra_hacer.<br/>',NULL,189560,3);
INSERT INTO stanza VALUES('S221','chorus','¡Lluvia! ¡Lluvia! ¡Mándanos Tu lluvia!<br/>Desde lo alto ¡lluvia derramad!<br/>¡Lluvia! ¡Lluvia! ¡Mándanos Tu lluvia!<br/>¡Es Tu Cuerpo que clamando está!<br/>',NULL,189561,4);
INSERT INTO stanza VALUES('S221','3','Seguimos, Señor, con seguridad,<br/>Para reclamar fuego de Ti,<br/>Para predicar y evangelizar,<br/>Y las almas refinar aquí.<br/>',NULL,189562,5);
INSERT INTO stanza VALUES('S221','chorus','¡Fuego! ¡Fuego! ¡Las lenguas de fuego!<br/>¡Para Tu mensaje proclamar!<br/>¡Fuego! ¡Fuego! ¡Las lenguas de fuego!<br/>¡Es Tu Cuerpo que invocando está!<br/>',NULL,189563,6);
INSERT INTO stanza VALUES('S222','1','Señor, buscamos hoy Tu poder<br/>En nuestro_hablar y en nuestro_hacer;<br/>Nuestro servicio no_hacemos bien;<br/>¡Vístenos con poder!<br/>',NULL,189564,1);
INSERT INTO stanza VALUES('S222','chorus','Te_esperamos hoy en humildad;<br/>Mira nuestra gran necesidad;<br/>Danos Tu fuerza; no_esperes más;<br/>¡Vístenos con poder!<br/>',NULL,189565,2);
INSERT INTO stanza VALUES('S222','2','Ven y visita nuestro lugar;<br/>Dones de gracia_a Tu_iglesia da;<br/>Nuestro servicio abraza ya;<br/>¡Vístenos con poder!<br/>',NULL,189566,3);
INSERT INTO stanza VALUES('S222','3','En Ti queremos prevalecer<br/>Como_ocurrió en Pentecostés;<br/>Que Tu respuesta se pueda ver;<br/>¡Vístenos con poder!<br/>',NULL,189567,4);
INSERT INTO stanza VALUES('S222','4','Señor, Tu Cuerpo en plena fe<br/>Pide_en Tu nombre ese poder;<br/>Manda_esa lluvia; ¡oh, fuego ven!<br/>¡Vístenos con poder!<br/>',NULL,189568,5);
INSERT INTO stanza VALUES('S223','1','¡Qué gran bendición! ¡Hecho sin igual!<br/>En Su_Espíritu nos bautizó;<br/>No vaciles más; esto_acepta ya,<br/>En Su_Espíritu nos bautizó.<br/>',NULL,189569,1);
INSERT INTO stanza VALUES('S223','chorus','¡Toma! ¡Toma!<br/>Este_hecho por la viva fe!<br/>¡Toma! ¡Toma!<br/>Este hecho consumado fue.<br/>',NULL,189570,2);
INSERT INTO stanza VALUES('S223','2','En el pacto_está claramente allí;<br/>En Su_Espíritu nos bautizó;<br/>Ya se completó; sólo_hay que_aplicar,<br/>En Su_Espíritu nos bautizó.<br/>',NULL,189571,3);
INSERT INTO stanza VALUES('S223','chorus','¡Guarda! ¡Guarda!<br/>Este_hecho por la viva fe;<br/>¡Guarda! ¡Guarda!<br/>Este hecho consumado fue.<br/>',NULL,189572,4);
INSERT INTO stanza VALUES('S223','3','El Espíritu sobre_el Cuerpo_está,<br/>En Su_Espíritu nos bautizó;<br/>Su porción hoy comparte_en unidad:<br/>En Su_Espíritu nos bautizó.<br/>',NULL,189573,5);
INSERT INTO stanza VALUES('S223','chorus','¡Hoy comparte!<br/>Este_hecho por la viva fe;<br/>¡Hoy comparte!<br/>Este hecho consumado fue.<br/>',NULL,189574,6);
INSERT INTO stanza VALUES('S223','4','Con el cuerpo bien, en el Cuerpo_estad;<br/>Sigue con base_en el hecho real;<br/>Dudas y_el pecar debes condenar;<br/>Por la viva fe hoy hazlo real.<br/>',NULL,189575,7);
INSERT INTO stanza VALUES('S223','chorus','¡Sigue! ¡Sigue!<br/>Este_hecho por la viva fe;<br/>¡Sigue! ¡Sigue!<br/>Este hecho consumado fue.<br/>',NULL,189576,8);
INSERT INTO stanza VALUES('S224','1','Cristo el Salvador en gloria<br/>A los cielos ascendió;<br/>Coronado fue con honra<br/>Por el Padre Dios de_amor.<br/>Es Cabeza sobre todo,<br/>Lo más alto se le dio.<br/>',NULL,189577,1);
INSERT INTO stanza VALUES('S224','2','Desde el Cristo ascendido<br/>El Espíritu bajó;<br/>Derramado sobre el Cuerpo<br/>A Sus miembros bautizó,<br/>Por Su_iglesia_así recibe<br/>El Señor la adoración.<br/>',NULL,189578,2);
INSERT INTO stanza VALUES('S224','3','Por la encarnación de Cristo<br/>En el hombre Dios entró;<br/>Siendo muerto_y levantado<br/>Introdujo al hombre en Dios.<br/>Dios y_el hombre bien mezclados<br/>En Sí mismo realizó.<br/>',NULL,189579,3);
INSERT INTO stanza VALUES('S224','4','En los cielos ascendido<br/>En el trono se sentó;<br/>Señorío y principado<br/>Todo Cristo recibió.<br/>Por Su_Espíritu vertido<br/>Como tal se conoció.<br/>',NULL,189580,4);
INSERT INTO stanza VALUES('S224','5','Por Su Espíritu vertido<br/>A la_iglesia_Él descendió;<br/>En Su_Espíritu por ello<br/>A la_iglesia bautizó.<br/>El bautismo para siempre<br/>Por Su_Espíritu logró.<br/>',NULL,189581,5);
INSERT INTO stanza VALUES('S224','6','¡Aleluya, consumado!<br/>En total consumación.<br/>¡Aleluya, incluidos!<br/>En Su plan nos incluyó.<br/>Con Su_Espíritu enviado<br/>A la_iglesia bautizó.<br/>',NULL,189582,6);
INSERT INTO stanza VALUES('S225','1','Hoy vive el Espíritu en nuestro ser,<br/>Es como el agua que sacia la sed;<br/>Podemos beberlo hasta rebosar<br/>Y ríos de vida veremos brotar.<br/>',NULL,189583,1);
INSERT INTO stanza VALUES('S225','2','Nos cubre_el Espíritu con gran poder,<br/>Es como_un vestido que hay que poner;<br/>En Él bautizados, vestidos de Él,<br/>Podemos servirte, Señor, con poder.<br/>',NULL,189584,2);
INSERT INTO stanza VALUES('S225','3','Aliento de vida_el Espíritu es,<br/>Un soplo viviente para nuestro ser;<br/>Un viento muy fuerte_el Espíritu es,<br/>Que cuando desciende nos da Su poder.<br/>',NULL,189585,3);
INSERT INTO stanza VALUES('S225','4','El Resucitado aliento sopló,<br/>Legando_el Espíritu, vida nos dio.<br/>Como_el Ascendido en Pentecostés<br/>Vertió el Espíritu de gran poder.<br/>',NULL,189586,4);
INSERT INTO stanza VALUES('S225','5','Mi vida_el Espíritu de vida es,<br/>Y para_esta vida es dado_el poder;<br/>Tal como el viento el aire nos trae,<br/>El poder trae vida para respirar.<br/>',NULL,189587,5);
INSERT INTO stanza VALUES('S225','6','No son dos Espíritus, mas uno_es Él,<br/>Y éste conlleva_una doble función:<br/>Nos llena de Dios y nos da Su poder,<br/>Para por completo mezclarnos con Él.<br/>',NULL,189588,6);
INSERT INTO stanza VALUES('S225','7','Señor, nos sature Tu_Espíritu bien,<br/>Así en Tu vida podremos crecer;<br/>Nos vista Tu_Espíritu hoy con poder<br/>Para que Tu obra podamos hacer.<br/>',NULL,189589,7);
INSERT INTO stanza VALUES('S226','1','Sin la sangre y su limpieza<br/>No se puede unción tener;<br/>Sin pasar por el Calvario,<br/>No habrá Pentecostés.<br/>Si la sangre no nos limpia<br/>No_hay poder espiritual,<br/>Si queremos ser testigos<br/>Hoy la cruz hay que llevar.<br/>',NULL,189590,1);
INSERT INTO stanza VALUES('S226','chorus','Por la cruz, quita, Señor,<br/>La vida de mi_alma hoy;<br/>Cualquier precio pagaré<br/>Para plena_unción tener.<br/>',NULL,189591,2);
INSERT INTO stanza VALUES('S226','2','Si no se golpea la Roca,<br/>Agua viva no saldrá;<br/>El Espíritu sin muerte<br/>No se manifestará.<br/>Si morimos hoy con Cristo,<br/>Para todo_así perder,<br/>Salvaremos este mundo<br/>Al vestirnos Su poder.<br/>',NULL,189592,3);
INSERT INTO stanza VALUES('S226','3','Al altar le sigue_el fuego,<br/>No_hay ganancia sin perder;<br/>Si no se ofrece_el todo<br/>Nunca_el trono se ha de ver.<br/>Si_hay un sacrificio vivo<br/>Para_a Dios obedecer,<br/>Dios con él se compromete,<br/>Desplegando Su poder.<br/>',NULL,189593,4);
INSERT INTO stanza VALUES('S226','4','Hay que preparar los vasos<br/>Para_Aceite contener;<br/>Al cavar por fe las zanjas,<br/>Él la Lluvia_ha de verter.<br/>Sólo el Jordán pasando<br/>La unción nos cubrirá;<br/>Bautizados en Su muerte,<br/>La Paloma bajará.<br/>',NULL,189594,5);
INSERT INTO stanza VALUES('S226','5','Cuando vemos la cosecha<br/>Tan dorada_en su esplendor,<br/>Nos recuerda las semillas<br/>Que la tierra consumió.<br/>Antes que florezca_el fruto<br/>A la muerte hay que ir;<br/>Si_el Espíritu queremos,<br/>Hoy con Cristo hay que morir.<br/>',NULL,189595,6);
INSERT INTO stanza VALUES('S226','6','Ya que por Tu senda estrecha<br/>Sólo debo caminar,<br/>Oh Señor, rompe mi orgullo,<br/>Para_en obediencia andar.<br/>No por más poder te pido,<br/>Sino en Tu muerte_estar,<br/>Y que en mí la cruz opere<br/>Tan profunda realidad.<br/>',NULL,189596,7);
INSERT INTO stanza VALUES('S227','1','Señor, haz que Tu sangre<br/>Me limpie de mi mal,<br/>Que Tu_Espíritu Santo<br/>Me unja sin cesar.<br/>Confieso que muy pobre<br/>Es mi servicio_a Ti;<br/>Pero si Tú me llenas,<br/>Por Tí podré vivir.<br/>',NULL,189597,1);
INSERT INTO stanza VALUES('S227','chorus','Que de mi yo libres,<br/>De su miseria vil,<br/>Para que_así por siempre<br/>Yo lleno_esté de Ti.<br/>',NULL,189598,2);
INSERT INTO stanza VALUES('S227','2','Por Ti añora_y clama<br/>Mi seco corazón;<br/>Te ruego que me llene<br/>Tu_Espíritu, Señor.<br/>En Ti, la Peña_hendida,<br/>Me quiero refugiar;<br/>Derrama_el agua viva<br/>Hasta mi sed saciar.<br/>',NULL,189599,3);
INSERT INTO stanza VALUES('S227','3','Mi corazón es frío;<br/>Rehúsa_obedecer;<br/>Tu_Espíritu me llene,<br/>Rebelde no seré.<br/>Sobre Tu_altar me pongo<br/>Y no me moveré;<br/>Consuma hoy Tu fuego,<br/>Señor, todo mi ser.<br/>',NULL,189600,4);
INSERT INTO stanza VALUES('S227','4','Oh, que Tu cruz por dentro<br/>Muy hondo arda_en mí.<br/>Ensancha Tu medida;<br/>Cenizas hazme_al fin.<br/>Tu Espíritu me llene<br/>Hoy mucho más que_ayer,<br/>Para que_el agua viva<br/>Por mí puedas verter.<br/>',NULL,189601,5);
INSERT INTO stanza VALUES('S228','1','Siete_Espíritus de Dios<br/>Con el Hijo obran hoy;<br/>Pues la era  ya cambió<br/>Por la_iglesia_es Su fervor.<br/>',NULL,189602,1);
INSERT INTO stanza VALUES('S228','chorus','¡Ven, o siete_Espíritus,<br/>Dale_a Tu recobro luz!<br/>Quema_y prueba el corazón,<br/>Las iglesias Tuyas son.<br/>Quema, prueba,<br/>Las iglesias Tuyas son.<br/>',NULL,189603,2);
INSERT INTO stanza VALUES('S228','2','Séptuplo_el Espíritu_es<br/>Por la_iglesia_en mortandad;<br/>Dios por Él puede probar<br/>Y a los santos vida dar.<br/>',NULL,189604,3);
INSERT INTO stanza VALUES('S228','3','El Espíritu de Dios<br/>Intensificado está;<br/>Por ser séptuplo podrá<br/>Hoy la iglesia rescatar.<br/>',NULL,189605,4);
INSERT INTO stanza VALUES('S228','4','Cumplen con el plan de Dios<br/>Estos siete_Espíritus;<br/>Nos calientan con ardor<br/>Estas lámparas de luz.<br/>',NULL,189606,5);
INSERT INTO stanza VALUES('S228','5','Ved los siete Espíritus,<br/>Son los ojos del Señor;<br/>Escudriñan con Su luz,<br/>En la iglesia velan hoy.<br/>',NULL,189607,6);
INSERT INTO stanza VALUES('S228','6','Siete Espíritus de Dios<br/>El Señor emplea hoy;<br/>Los podemos disfrutar,<br/>Para las iglesias son.<br/>',NULL,189608,7);
INSERT INTO stanza VALUES('S229','1','Del Espíritu_ha nacido<br/>Nuestro Salvador, Jesús;<br/>Del Espíritu_está lleno:<br/>En Su_esencia_Espíritu.<br/>Como_Espíritu, Él vino;<br/>Hoy Jesús, Espíritu_es.<br/>Por Su_Espíritu, hoy somos<br/>Un espíritu con Él.<br/>',NULL,189609,1);
INSERT INTO stanza VALUES('S229','2','Bautizada e inmersa<br/>En el Santo_Espíritu,<br/>La iglesia ha nacido<br/>Del viviente_Espíritu.<br/>El Espíritu, hermanos,<br/>Es nuestra necesidad,<br/>No la enseñanza_o credo,<br/>Ni la religiosidad.<br/>',NULL,189610,2);
INSERT INTO stanza VALUES('S229','3','En Espíritu guardamos<br/>Toda nuestra comunión;<br/>Sólo_así participamos<br/>Del Espíritu_en unión.<br/>El que tiene_oído, oiga:<br/>El Espíritu_habla_aún,<br/>Bendiciendo_a las iglesias<br/>Con los siete_Espíritus.<br/>',NULL,189611,3);
INSERT INTO stanza VALUES('S229','4','"Ven y bebe_el agua viva",<br/>Dicen hoy a una voz<br/>El Espíritu y la novia,<br/>Siendo uno_en su clamor.<br/>El Espíritu_es la norma<br/>Que Dios quiere recobrar<br/>Hoy en todas las iglesias;<br/>¡Hazlo nuestra realidad!<br/>',NULL,189612,4);
INSERT INTO stanza VALUES('S230','1','Me amó con un amor<br/>Tan divino_y eternal,<br/>Por Su gracia supe yo<br/>De_esta grande realidad.<br/>¡Oh, completa y dulce paz!<br/>¡Me transporta todo el ser!<br/>En amor tan celestial,<br/>Suyo soy y mío es Él.<br/>',NULL,189613,1);
INSERT INTO stanza VALUES('S230','2','Es el cielo más azul,<br/>Y la tierra un verde mar;<br/>Algo vibra en todo aquí,<br/>Pues mi ser en Cristo está.<br/>Dan las aves su canción,<br/>Y las flores, brillantez,<br/>Desde que conozco yo,<br/>Que soy Suyo_y mío_es Él.<br/>',NULL,189614,2);
INSERT INTO stanza VALUES('S230','3','Lo que antes me alarmó<br/>No me puede perturbar;<br/>En Su seno de amor<br/>Yo me calmo_en dulce paz.<br/>Quiero_aquí permanecer<br/>Renunciando a mi avidez;<br/>Mientras le oigo susurrar<br/>Suyo soy y mío_es Él.<br/>',NULL,189615,3);
INSERT INTO stanza VALUES('S230','4','Para siempre suyo soy,<br/>¿Qué nos puede separar?<br/>Cristo en mi corazón,<br/>¡Oh que gran felicidad!<br/>Puede_el cosmos terminar,<br/>O el alba oscurecer,<br/>Pero_estando yo con Dios<br/>Suyo soy y mío es Él.<br/>',NULL,189616,4);
INSERT INTO stanza VALUES('S231','1','¡Conmigo_alégrate!<br/>Mi pobre corazón<br/>Un gran tesoro_un día_halló;<br/>Hoy lleno_está de amor.<br/>',NULL,189617,1);
INSERT INTO stanza VALUES('S231','2','¡Conmigo_alégrate!<br/>Enfermo estaba yo;<br/>Él, con Su arte de sanar,<br/>Mi corazón curó.<br/>',NULL,189618,2);
INSERT INTO stanza VALUES('S231','3','¡Conmigo_alégrate!<br/>Cansado estaba yo,<br/>Pero un brazo fuerte_hallé<br/>Que me sostiene hoy.<br/>',NULL,189619,3);
INSERT INTO stanza VALUES('S231','4','¡Conmigo_alégrate!<br/>Vagaba sin parar.<br/>Él dirigió mis pies aquí;<br/>En Él hallé mi_hogar.<br/>',NULL,189620,4);
INSERT INTO stanza VALUES('S231','5','¡Conmigo_alégrate!<br/>Pues un amigo hallé<br/>Que_escudriñó mi corazón,<br/>Y_aún me ama Él.<br/>',NULL,189621,5);
INSERT INTO stanza VALUES('S231','6','¡No supe de Su_amor<br/>Que por siempre existió;<br/>Tierno, profundo y tan fiel,<br/>Cuán fuerte_es este amor!<br/>',NULL,189622,6);
INSERT INTO stanza VALUES('S231','7','Todo lo_entiendo hoy;<br/>Reconozco Su_hablar;<br/>Lo_escucho cada día_en mí,<br/>¿Qué más puedo desear?<br/>',NULL,189623,7);
INSERT INTO stanza VALUES('S232','1','Perdido en pecado,<br/>Su rico_amor me halló;<br/>Maravillosa gracia,<br/>A Su grey me llevo;<br/>Su gran misericordia,<br/>Profunda más que_el mar,<br/>Mas alta que los cielos,<br/>Mi tema_ella será.<br/>',NULL,189624,1);
INSERT INTO stanza VALUES('S232','chorus','Es más dulce con los años,<br/>Es más dulce cada vez;<br/>Rico_y más profundo,<br/>El amor de Cristo<br/>Es más dulce cada vez.<br/>',NULL,189625,2);
INSERT INTO stanza VALUES('S232','2','Anduvo por Judea<br/>En su peregrinar<br/>La gente se_acercaba,<br/>Su gracia_a disfrutar.<br/>Sano_a los quebrantados,<br/>Al ciego vista dio;<br/>Su corazón anhela<br/>Aun por mí_en amor.<br/>',NULL,189626,3);
INSERT INTO stanza VALUES('S233','1','¡Qué_amigo halle_en mi Salvador!<br/>Me_amo a mí, un perdido;<br/>Me trajo con "cuerdas de amor",<br/>Así me_unió consigo;<br/>Me gana_entero_el corazón,<br/>De_Él nadie me separa,<br/>Pues Suyo soy, y_Él es mi porción;<br/>Él es mi vida eterna<br/>',NULL,189627,1);
INSERT INTO stanza VALUES('S233','2','¡Qué amigo_hallé_en mi Salvador!<br/>Murió para salvarme;<br/>No sólo el don de vida, mas<br/>Su ser Él quiso darme.<br/>De nada digo, "es mío" aquí,<br/>Lo rindo todo_a Cristo;<br/>Mi corazón, fuerza_y todo en mí<br/>Por siempre_a_Él lo_entrego.<br/>',NULL,189628,2);
INSERT INTO stanza VALUES('S233','3','¡Qué_amigo hallé en mi Salvador!<br/>Tan fiel, veraz y tierno;<br/>Potente_es Él, fuerte defensor<br/>Mi guia_y consejero;<br/>Del que me ama tanto á mí,<br/>¿Podrá algo apartarme?<br/>¡Ni vida o muerte o_el Hades vil!<br/>Pues Suyo soy por siempre.<br/>',NULL,189629,3);
INSERT INTO stanza VALUES('S234','1','Dios mis pecados perdonó,<br/>Tras Sus espaldas los tiró;<br/>Más nunca los recordará,<br/>Jamás los examinará.<br/>',NULL,189630,1);
INSERT INTO stanza VALUES('S234','chorus','Dios mis pecados perdonó<br/>Como_a las nubes dispersó,<br/>Desvanecidos hoy están,<br/>Ya para siempre los borró.<br/>',NULL,189631,2);
INSERT INTO stanza VALUES('S234','2','Pesada carga Dios quitó,<br/>Al mar la_echó y sepultó.<br/>El mis pecados alejó,<br/>Del este_al oeste los lanzó.<br/>',NULL,189632,3);
INSERT INTO stanza VALUES('S235','1','Cristo_el Señor, justicia es;<br/>Mi bella vestidura_es Él;<br/>Aunque el mundo_ardiendo_esté,<br/>Mi rostro_alegre alzaré.<br/>',NULL,189633,1);
INSERT INTO stanza VALUES('S235','2','Creo_en Tu sangre eficaz;<br/>En el propiciatorio_está;<br/>Habla_en virtud del pecador;<br/>Por mí, por mi_alma, se vertió.<br/>',NULL,189634,2);
INSERT INTO stanza VALUES('S235','3','Los pecadores, ¿cuántos son?<br/>Más que la_arena de la mar;<br/>El gran rescate se pagó,<br/>Lograste_así su redención.<br/>',NULL,189635,3);
INSERT INTO stanza VALUES('S235','4','Confiado_y firme puedo_estar,<br/>Nadie me puede condenar;<br/>Pues yo por Ti absuelto_estoy,<br/>De culpas, penas y temor.<br/>',NULL,189636,4);
INSERT INTO stanza VALUES('S235','5','Tal vestidura se verá<br/>Resplandeciente_y singular;<br/>Su gloria nunca cambiará,<br/>Es nueva por la_eternidad.<br/>',NULL,189637,5);
INSERT INTO stanza VALUES('S235','6','Oh, Dios de_amor, Dios de poder,<br/>Prueben los santos Tu merced;<br/>Nuestro vestido_y nuestro_honor,<br/>Nuestra justicia: Tú, Señor.<br/>',NULL,189638,6);
INSERT INTO stanza VALUES('S236','1','¿Y puede ser que gane yo<br/>En la sangre un interés?<br/>¿Murió por mí quien le herí?<br/>¿Por mí que_a muerte le llevé?<br/>¿Cómo será -qué gran amor-<br/>Que por mí mueras Tú, mi Dios?<br/>¿Cómo será -qué gran amor-<br/>Que por mí mueras Tú, mi Dios?<br/>',NULL,189639,1);
INSERT INTO stanza VALUES('S236','2','¿Será que muere_el Inmortal?<br/>¿Quién podrá explorar Su plan?<br/>En vano intenta el serafín,<br/>El gran amor de Dios sondear.<br/>//¡Qué gran piedad! Tierra adorad,<br/>Cesen los ángeles de_indagar.//<br/>',NULL,189640,2);
INSERT INTO stanza VALUES('S236','3','¡Oh, qué infinita gracia fue!<br/>El trono celestial dejó;<br/>Se despojó, mas no de_amor,<br/>Por nuestra raza Él sangró.<br/>//¡Oh, qué merced! ¡Qué gran favor!<br/>Tu_inmensa gracia me_encontró.//<br/>',NULL,189641,3);
INSERT INTO stanza VALUES('S236','4','Yacía mi espíritu,<br/>En vil pecado y_en prisión;<br/>Mirar Tu faz me revivió,<br/>El calabozo_iluminó;<br/>//Mi corazón se liberó,<br/>Me levanté, te sigo yo.//<br/>',NULL,189642,4);
INSERT INTO stanza VALUES('S236','5','Condenación, ¿por qué temer?<br/>¡Jesús mi todo ahora es!<br/>Es mi Cabeza viviente Él,<br/>Y mi justicia firme y fiel.<br/>//Confiado_al trono vengo yo<br/>Por mi corona_en el Señor.//<br/>',NULL,189643,5);
INSERT INTO stanza VALUES('S237','1','Mi esperanza firme_está<br/>En Cristo mi justicia_y paz;<br/>Por ser Su nombre dulce y fiel,<br/>En mi Jesús descansaré.<br/>',NULL,189644,1);
INSERT INTO stanza VALUES('S237','chorus','Cristo es la Roca eternal,<br/>No_hay otra base en que confiar,<br/>No_hay otra base en que confiar.<br/>',NULL,189645,2);
INSERT INTO stanza VALUES('S237','2','Aunque Su faz no pueda ver,<br/>Su gracia es mía por la fe;<br/>Y aunque haya tempestad,<br/>Dentro del velo mi_ancla_está.<br/>',NULL,189646,3);
INSERT INTO stanza VALUES('S237','3','Su pacto_y sangre eficaz,<br/>En el diluvio me_alzarán;<br/>Si se desploma todo aquí,<br/>Me_aferro_a Cristo mi mástil.<br/>',NULL,189647,4);
INSERT INTO stanza VALUES('S237','4','Cuando regrese_en Su poder,<br/>Oh, que me halle yo en Él.<br/>Sin culpas compareceré,<br/>Delante de mi justo Juez.<br/>',NULL,189648,5);
INSERT INTO stanza VALUES('S238','1','Tener perfecta paz con Dios<br/>¡Oh, qué_expresión sin par!<br/>Reconciliado_estoy con Él,<br/>Por Su sangre, oh, qué paz!<br/>',NULL,189649,1);
INSERT INTO stanza VALUES('S238','2','En mi_ego y en mi vivir<br/>¡Qué lejos de mi Dios!<br/>Mas, por la sangre de Jesús,<br/>Por fe me acerco hoy.<br/>',NULL,189650,2);
INSERT INTO stanza VALUES('S238','3','Tan cerca_estoy, tan cerca_a Dios,<br/>Ya no se puede más,<br/>Pues en Su Hijo yo estoy<br/>Tan cerca como_Él está.<br/>',NULL,189651,3);
INSERT INTO stanza VALUES('S238','4','Querido soy, querido_a Dios,<br/>Más no me puede_amar;<br/>Como_a Su Hijo me_ama_a mí,<br/>El mismo amor me da.<br/>',NULL,189652,4);
INSERT INTO stanza VALUES('S238','5','¿Por qué ansioso he de_estar,<br/>Si tal Dios mío es?<br/>Me guarda día_y noche Él;<br/>Y me da Su mismo ser.<br/>',NULL,189653,5);
INSERT INTO stanza VALUES('S239','1','¡Despiértate alma! Ven,<br/>Sacude tu temor;<br/>Un sacrificio hay<br/>Sangrando_a tu favor.<br/>Está_en el trono mi Fiador,<br/>Comprado fui por Su dolor,<br/>Comprado fui por Su   dolor.<br/>',NULL,189654,1);
INSERT INTO stanza VALUES('S239','2','En lo_alto vive Él,<br/>Intercediendo_está;<br/>Su_amor redimidor,<br/>Su sangre eficaz.<br/>Por nuestra raza Él sangró,<br/>Rociando_el trono de mi Dios,<br/>Rociando_el trono de mi Dios.<br/>',NULL,189655,2);
INSERT INTO stanza VALUES('S239','3','Cinco heridas son<br/>Las que sufrió por mí,<br/>Ardiendo_en oración<br/>Están rogando_así:<br/>"Perdónalo", es su clamor,<br/>"¡Se redimió_ese pecador!"<br/>"¡Se redimió_ese pecador!"<br/>',NULL,189656,3);
INSERT INTO stanza VALUES('S239','4','El Padre_escucha orar<br/>Al Hijo de Su_amor;<br/>No se puede_apartar<br/>De_Aquel a quien ungió.<br/>Su_Espíritu me confirmó:<br/>"Nacido eres tú de Dios",<br/>"Nacido eres tú de Dios".<br/>',NULL,189657,4);
INSERT INTO stanza VALUES('S239','5','¡Qué reconciliación!<br/>Me perdonó mi Dios.<br/>Su hijo_ahora soy,<br/>No tengo más temor.<br/>Me_acerco con confianza_y paz,<br/>Y "Abba, Padre"_es mi clamar,<br/>Y "Abba, Padre"_es mi clamar.<br/>',NULL,189658,5);
INSERT INTO stanza VALUES('S240','1','Esclavizado, muerto y sin fe;<br/>Creer quería, ¡no lo logré!<br/>Dios se presenta, Cristo me encuentra;<br/>¡Dios me infundió!<br/>¡Dios me infundió!<br/>',NULL,189659,1);
INSERT INTO stanza VALUES('S240','chorus','¡Cristo con sangre nos redimió!<br/>Fuimos comprados, dados a Dios.<br/>¡No condenados, justificados!<br/>¡Paz tenemos con Dios!<br/>¡Paz tenemos con Dios!<br/>',NULL,189660,2);
INSERT INTO stanza VALUES('S240','2','Por nacimiento yo en Adán<br/>Muerto estaba, ¡qué_enfermedad!<br/>Cristo viniendo, Adán muriendo,<br/>¡Él murió, vivo yo!<br/>¡Él murió, vivo yo!<br/>',NULL,189661,3);
INSERT INTO stanza VALUES('S240','3','Hoy tengo gozo, gracia_y amor;<br/>¡Oh, aleluya! ¡Ya libre soy!<br/>Dios en mí fluye, me constituye,<br/>¡Con Su vida eternal!<br/>¡Con Su vida eternal!<br/>',NULL,189662,4);
INSERT INTO stanza VALUES('S241','1','Proclamo: ¡Yo soy redimido!<br/>Fue por el Cordero de Dios.<br/>Y por Su gran misericordia,<br/>Su hijo por siempre soy yo.<br/>',NULL,189663,1);
INSERT INTO stanza VALUES('S241','chorus','Me redimió con sangre_el Cordero de Dios,<br/>¡Me reidmió! Su hijo por siempre soy yo.<br/>',NULL,189664,2);
INSERT INTO stanza VALUES('S241','2','¡Feliz en Jesús! ¡Redimido!<br/>Tal gozo no puedo narrar.<br/>Y sé que_en la luz de Su rostro<br/>Por siempre yo he de morar.<br/>',NULL,189665,3);
INSERT INTO stanza VALUES('S241','3','En mi Redentor yo medito,<br/>Todo_el día pienso en Él.<br/>Le canto, no puedo callarme;<br/>Su_amor bulle_en todo mi ser.<br/>',NULL,189666,4);
INSERT INTO stanza VALUES('S241','4','Yo se que veré la belleza<br/>Del Rey con quien gusto andar;<br/>Él guarda_en amor mis pisadas;<br/>De noche, canciones me da.<br/>',NULL,189667,5);
INSERT INTO stanza VALUES('S242','1','Yo tengo_un himno de loor,<br/>Ya que me redimió,<br/>Para mi Rey y Redentor,<br/>Ya que me redimió.<br/>',NULL,189668,1);
INSERT INTO stanza VALUES('S242','chorus','Ya que me redimió,<br/>Ya que me redimió,<br/>Yo Su nombre ensalzaré;<br/>Ya que me redimió,<br/>A mi Salvador ensalzaré.<br/>',NULL,189669,2);
INSERT INTO stanza VALUES('S242','2','Mi Cristo_es mi satisfacción,<br/>Ya que me redimió,<br/>Su voluntad yo hago hoy,<br/>Ya que me redimió.<br/>',NULL,189670,3);
INSERT INTO stanza VALUES('S242','3','En mí Su_Espíritu está,<br/>Ya que me redimió,<br/>Quitó el temor y la_ansiendad,<br/>Ya que me redimió.<br/>',NULL,189671,4);
INSERT INTO stanza VALUES('S242','4','Mi gozo inefable_es Él,<br/>Ya que me redimió,<br/>Mi Cristo mi justicia es<br/>Ya que me redimió.<br/>',NULL,189672,5);
INSERT INTO stanza VALUES('S242','5','Yo tengo_un Dios que_es para mí,<br/>Ya que me redimió,<br/>Con Él yo moraré sin fin,<br/>Ya que me redimió.<br/>',NULL,189673,6);
INSERT INTO stanza VALUES('S243','1','El oro_y la plata no me_han redimido;<br/>Ninguna riqueza me pudo salvar.<br/>La sangre_en la cruz es mi única base;<br/>La muerte de Cristo logró sanidad.<br/>',NULL,189674,1);
INSERT INTO stanza VALUES('S243','chorus','Me redimió, mas no con plata,<br/>Ni con oro me compró;<br/>Mi Salvador virtió Su sangre,<br/>Alto precio de Su_amor.<br/>',NULL,189675,2);
INSERT INTO stanza VALUES('S243','2','El oro_y la plata no me_han redimido;<br/>La culpa pesaba en mi corazón.<br/>La sangre_en la cruz es mi única base;<br/>La muerte de Cristo mi_aprecio ganó.<br/>',NULL,189676,3);
INSERT INTO stanza VALUES('S243','3','El oro_y la plata no me_han redimido;<br/>La ley me_impedía_acercarme al Señor.<br/>La sangre_en la cruz es mi única base;<br/>La muerte de Cristo quitó mi temor.<br/>',NULL,189677,4);
INSERT INTO stanza VALUES('S243','4','El oro_y la plata no me_han redimido;<br/>Así no se obtiene el reino de Dios.<br/>La sangre_en la cruz es mi única base;<br/>La muerte de Cristo me dio redención.<br/>',NULL,189678,5);
INSERT INTO stanza VALUES('S244','1','A mi Redentor yo canto<br/>Por Su tierno y vasto amor;<br/>En la cruenta cruz muriendo<br/>Me libró de maldición.<br/>',NULL,189679,1);
INSERT INTO stanza VALUES('S244','chorus','Cantaré de Jesucristo,<br/>Mi amado Redentor;<br/>En la cruz pagó mis deudas,<br/>Con Su sangre me compró.<br/>',NULL,189680,2);
INSERT INTO stanza VALUES('S244','2','Contaré la bella_historia<br/>De mi_eterna salvación;<br/>Por Su gran misericordia<br/>Mi rescate Él pagó.<br/>',NULL,189681,3);
INSERT INTO stanza VALUES('S244','3','Cantaré mis alabanzas<br/>Al triunfante Redentor,<br/>Quien la muerte y_el pecado<br/>Destruyó a mi favor.<br/>',NULL,189682,4);
INSERT INTO stanza VALUES('S244','4','A mi Redentor yo canto,<br/>Por Su celestial amor;<br/>Me pasó de muerte_a vida,<br/>Soy con Él hijo de Dios.<br/>',NULL,189683,5);
INSERT INTO stanza VALUES('S245','1','Pertenezco_a Cristo,<br/>No_a mi propio yo;<br/>Todo lo que tengo_y soy<br/>Pertenece_a Dios.<br/>',NULL,189684,1);
INSERT INTO stanza VALUES('S245','2','Pertenezco_a Cristo;<br/>Mi Señor y Rey,<br/>Reina en mi corazón,<br/>Sobre todo es.<br/>',NULL,189685,2);
INSERT INTO stanza VALUES('S245','3','Pertenezco_a Cristo;<br/>¿Qué podrá pasar?<br/>Si_abrazando mi_alma_está<br/>Su brazo_eternal.<br/>',NULL,189686,3);
INSERT INTO stanza VALUES('S245','4','Pertenezco_a Cristo;<br/>¡Qué gran bendición!<br/>Con Su propia sangre fue<br/>Que mi_alma compró.<br/>',NULL,189687,4);
INSERT INTO stanza VALUES('S245','5','Pertenezco_a Cristo;<br/>El por mí murió;<br/>Suyo soy y mío_es Él,<br/>Para_Él vivo yo.<br/>',NULL,189688,5);
INSERT INTO stanza VALUES('S245','6','Pertenezco_a Cristo;<br/>Mi_alma_El guardará,<br/>Si por muerte_he de pasar,<br/>Él me cuidará.<br/>',NULL,189689,6);
INSERT INTO stanza VALUES('S245','7','Pertenezco_a Cristo;<br/>Y pronto_he de_estar<br/>Con mi_amado Salvador,<br/>En Su majestad.<br/>',NULL,189690,7);
INSERT INTO stanza VALUES('S246','1','¿Cómo no_hemos de cantar<br/>De la sangre divinal,<br/>Ni decir al pecador<br/>Del precioso manantial?<br/>',NULL,189691,1);
INSERT INTO stanza VALUES('S246','2','Por la sangre superior,<br/>Vida_eterna Dios nos dio;<br/>Sangre_incorruptible es<br/>La del Cordero de Dios.<br/>',NULL,189692,2);
INSERT INTO stanza VALUES('S246','3','Esta sangre tiene voz,<br/>Ella puede_hablar con Dios;<br/>Ante_el trono del Señor,<br/>Habla a nuestro favor.<br/>',NULL,189693,3);
INSERT INTO stanza VALUES('S246','4','La conciencia hace ver<br/>Todo_el mal en nuestro ser;<br/>Causa pena y dolor<br/>Descubriendo todo_error.<br/>',NULL,189694,4);
INSERT INTO stanza VALUES('S246','5','Sin la_humana percepción,<br/>Oye Dios la_intercesión<br/>De la sangre eficaz<br/>Que nos brinda gracia_y paz.<br/>',NULL,189695,5);
INSERT INTO stanza VALUES('S246','6','Obras muertas sin valor,<br/>No complacerán a Dios;<br/>No_es la_ofrenda terrenal,<br/>Mas Su sangre celestial.<br/>',NULL,189696,6);
INSERT INTO stanza VALUES('S246','7','¡Qué gloriosa redneción!<br/>Superior a la_expiación;<br/>Por la sangre del Señor,<br/>Hay limpieza y perdón.<br/>',NULL,189697,7);
INSERT INTO stanza VALUES('S246','8','Mente_y corazón en paz,<br/>Nunca más vergüenza_habrá;<br/>Nuestra conciencia purgó,<br/>Nuestras manchas Él lavó.<br/>',NULL,189698,8);
INSERT INTO stanza VALUES('S246','9','¡Todo Su sangre logró!<br/>Insondable_es su valor.<br/>¡"Aleluya"_hay que cantar!<br/>¡En Su sangre_hay que confiar!<br/>',NULL,189699,9);
INSERT INTO stanza VALUES('S247','1','Cuando_en la cruz el Señor murió,<br/>El justo Dios satisfecho fue,<br/>Allí con sangre Él me roció,<br/>¡Gloria dad a Él!<br/>',NULL,189700,1);
INSERT INTO stanza VALUES('S247','chorus','¡A Su nombre gloria!<br/>¡A Su nombre gloria!<br/>Allí con sangre Él me roció,<br/>¡Gloria dad a Él!<br/>',NULL,189701,2);
INSERT INTO stanza VALUES('S247','2','En esta fuente_en que salvo fui,<br/>La redención Dios logró por mí;<br/>Disfrutaré gozo_eterno allí,<br/>¡Gloria dad a Él!<br/>',NULL,189702,3);
INSERT INTO stanza VALUES('S247','3','Hecho glorioso cuando_Él murió,<br/>Todas mis deudas Él perdonó,<br/>Fuente de vida Él nos abrió;<br/>¡Gloria dad a Él!<br/>',NULL,189703,4);
INSERT INTO stanza VALUES('S247','chorus','¡A Su nombre gloria!<br/>¡A Su nombre gloria!<br/>Fuente de vida Él nos abrió;<br/>¡Gloria dad a Él!<br/>',NULL,189704,5);
INSERT INTO stanza VALUES('S247','4','Hoy de Su vida y redención,<br/>Tengo total participación,<br/>Bebiendo_el agua de vida_estoy,<br/>¡Gloria dad a Él!<br/>',NULL,189705,6);
INSERT INTO stanza VALUES('S248','1','De Tu presencia, oh Señor,<br/>Queremos disfrutar;<br/>Entramos con confianza_aquí,<br/>Tu sangre_al aplicar.<br/>Nuestra justicia propia_en sí,<br/>Carece de valor;<br/>Sólo Tu sangre eficaz<br/>Es firme solución.<br/>',NULL,189706,1);
INSERT INTO stanza VALUES('S248','2','Tus juicios debo admitir,<br/>Son santos; justos son.<br/>Por mis pecados carmesí,<br/>No hay vindicación.<br/>No puede_un velo encubrir<br/>Toda nuestra maldad.<br/>Pero Tu sangre, oh Señor,<br/>Podemos aplicar.<br/>',NULL,189707,2);
INSERT INTO stanza VALUES('S248','3','Nuestro pecado, Dios juzgó;<br/>Él no lo ignoró;<br/>Mas sobre Su Cordero fiel,<br/>Su ira derramó.<br/>Camino nuevo_y vivo_abrió:<br/>Todo_es justo_y legal;<br/>El Sustituto realizó<br/>Perdón y justa paz.<br/>',NULL,189708,3);
INSERT INTO stanza VALUES('S248','4','Con gozo, disfrutamos hoy<br/>Tu redención, Jesús;<br/>Tu sangre vemos otra vez,<br/>Con toda su virtud.<br/>Señor, qué vasta_es Tu merced;<br/>Es sin limitación.<br/>Te_alabaremos sin cesar,<br/>Cordero fiel de Dios.<br/>',NULL,189709,4);
INSERT INTO stanza VALUES('S249','1','En Egipto_esclavos fuimos, en tal vil prisión,<br/>¡Gloria a Dios, aleluya!<br/>Pero_el Dios de los hebreos ya nos rescató,<br/>¡Gloria a Dios, aleluya!<br/>',NULL,189710,1);
INSERT INTO stanza VALUES('S249','chorus','Cantaremos al Señor<br/>Por Su victoria triunfal;<br/>Los carros de Faraón,<br/>El ha_hechado en el mar.<br/>Aquí se_edificará<br/>La morada del gran Dios,<br/>¡Gloria a Dios, aleluya!<br/>',NULL,189711,2);
INSERT INTO stanza VALUES('S249','2','Hoy estamos de_este lado, no hay que regresar,<br/>¡Gloria a Dios, aleluya!<br/>¡Ved a todos los egipcios muertos junto_al mar!<br/>¡Gloria a Dios, aleluya!<br/>',NULL,189712,3);
INSERT INTO stanza VALUES('S249','3','¡Oh hermanos y hermanas, el mar se cruzó!<br/>¡Gloria a Dios, aleluya!<br/>¡Toda clase de_atadura el Señor rompió!<br/>¡Gloria a Dios, aleluya!<br/>',NULL,189713,4);
INSERT INTO stanza VALUES('S249','4','Como_hebreos en el mar de vidrio hoy cantad,<br/>¡Gloria a Dios, aleluya!<br/>Ese canto de Moisés, pues todo quedó_atrás,<br/>¡Gloria a Dios, aleluya!<br/>',NULL,189714,5);
INSERT INTO stanza VALUES('S250','1','¡Qué gran salvación nos ha dado_el Señor!<br/>Él en Su Palabra nos la reveló.<br/>Todo lo que_Él es y ha hecho nos dio<br/>Por tanto, Su_hablar atended con fervor.<br/>',NULL,189715,1);
INSERT INTO stanza VALUES('S250','2','Es Hijo de Hombre e Hijo de Dios,<br/>Con Él uno somos, qué gozosa_unión;<br/>Sumo Sacerdote, nuestro Capitán,<br/>Nos hará crecer hasta_en Su gloria_estar.<br/>',NULL,189716,2);
INSERT INTO stanza VALUES('S250','3','De nuestros pecados, nos purificó;<br/>Gustó Él la muerte_en la cruz que sufrió.<br/>Rompió las cadenas, al diablo aplastó.<br/>En glorioso séquito Él nos llevó.<br/>',NULL,189717,3);
INSERT INTO stanza VALUES('S250','4','Qué gran magnitud tiene tal salvación:<br/>¡Los socios de Cristo_en Su plan somos hoy!<br/>A gloria nos lleva con Él a reinar,<br/>Nos salva_el Señor por completo_en verdad.<br/>',NULL,189718,4);
INSERT INTO stanza VALUES('S250','5','Atentos estad para no descuidar<br/>La gran salvación que_Él nos ha dado ya,<br/>Para no perder la oportunidad<br/>De reinar con Él y Su vida gozar.<br/>',NULL,189719,5);
INSERT INTO stanza VALUES('S250','6','Tan gran salvación nos ha dado_el Señor,<br/>¡Tal como Él es, seremos nosotros!<br/>El Hijo nos lleva_a Su gloria con Él<br/>Por lo que Él hizo y por lo que_Él es.<br/>',NULL,189720,6);
INSERT INTO stanza VALUES('S251','1','¡Canta_alabanza! Cristo es<br/>Dios, salvación y vida;<br/>No salva por regulación,<br/>Más salva por Su vida.<br/>Nuestro esfuerzo_es vanidad;<br/>Su vida,_al hombre cambiará:<br/>Su vida_así transforma.<br/>',NULL,189721,1);
INSERT INTO stanza VALUES('S251','2','Él por completo salvará<br/>Por Su poder viviente;<br/>Él se transfunde_a nuestro ser,<br/>Nos salva plenamente.<br/>Salva_al perdido, entrando_en él;<br/>Nos salva hoy del ego cruel:<br/>Nos lleva a la gloria.<br/>',NULL,189722,2);
INSERT INTO stanza VALUES('S251','3','Señor y Sacerdote es,<br/>Aquel que nos da vida;<br/>Lleno de vida_está Su ser;<br/>Del ego, Él nos libra.<br/>Su vida_indestructible es;<br/>Completamente salva Él:<br/>¡Él es capaz! ¡Él vive!<br/>',NULL,189723,3);
INSERT INTO stanza VALUES('S251','4','Su vida suficiente es,<br/>Nos llevará_a la gloria;<br/>Sin ella, que probada fue,<br/>Sería otra historia.<br/>Su vida pruebas recibió,<br/>Hasta sufrir crucifixión:<br/>Pasó por muerte_y Hades.<br/>',NULL,189724,4);
INSERT INTO stanza VALUES('S251','5','Nos garantiza salvación,<br/>Su vida_está_operando;<br/>Todo así lo hace Él<br/>Para perfeccionarnos.<br/>Nuestro vivir caído es;<br/>Solo Su vida queda_en pie:<br/>Nos salva por completo.<br/>',NULL,189725,5);
INSERT INTO stanza VALUES('S251','6','Él vive para_interceder,<br/>Continuará por siempre;<br/>Ministra_hasta la_eternidad,<br/>Su sacerdocio_es fuerte.<br/>Hoy vive para_interceder;<br/>Tal Sumo Sacerdote_es Él:<br/>Más alto que los cielos.<br/>',NULL,189726,6);
INSERT INTO stanza VALUES('S251','7','Lleguemos hoy a Dios por Él,<br/>Jamas retrocedamos;<br/>Para_ejercer nuestra función,<br/>Tal vida obtengamos.<br/>Venid, tomad la vida que<br/>Producirá Su pueblo fiel<br/>Y tragará la muerte.<br/>',NULL,189727,7);
INSERT INTO stanza VALUES('S252','1','¡Qué garantía, mío es Jesús!<br/>¡Gloria divina, qué rico sabor!<br/>Dios me compró, me dio salvación,<br/>Me redimió y regeneró.<br/>',NULL,189728,1);
INSERT INTO stanza VALUES('S252','chorus','Esta_es mi_historia y mi canción,<br/>Siempre_alabando al Salvador.<br/>Esta_es mi_historia y mi canción,<br/>Siempre alabando al Salvador.<br/>',NULL,189729,2);
INSERT INTO stanza VALUES('S252','2','Delicia plena en sumisión,<br/>Veo visiónes de gloria estallar;<br/>Angeles bajan, del cielo traen<br/>Voces de amor, ecos de piedad.<br/>',NULL,189730,3);
INSERT INTO stanza VALUES('S252','3','Sumisión plena, todo está en paz;<br/>Me regocijo en mi Salvador;<br/>Orando espero llenado ser<br/>Con Su bondad, perdido en Su amor.<br/>',NULL,189731,4);
INSERT INTO stanza VALUES('S253','1','¡Qué admirable es el cambio forjado en mi ser,<br/>Desde que Jesús vino a mí!<br/>¡En mi alma_hay la luz que por siempre anhelé,<br/>Desde que Jesús vino a mí!<br/>',NULL,189732,1);
INSERT INTO stanza VALUES('S253','chorus','¡Desde que Jesús vino a mí!<br/>¡Desde que Jesús vino a mí!<br/>¡Bulle el gozó en mi alma como_olas del mar,<br/>Desde que Jesús vino a mí!<br/>',NULL,189733,2);
INSERT INTO stanza VALUES('S253','2','¡He cesado el vagar y del camino errar,<br/>Desde que Jesús vino a mí!<br/>¡Y mis muchos pecados lavados ya están,<br/>Desde que Jesús vino a mí!<br/>',NULL,189734,3);
INSERT INTO stanza VALUES('S253','3','¡Una firme esperanza sostiene mi andar,<br/>Desde que Jesús vino a mí!<br/>¡No hay nubes de dudas en mi caminar,<br/>Desde que Jesús vino a mí!<br/>',NULL,189735,4);
INSERT INTO stanza VALUES('S253','4','¡En el valle de muerte la luz brillará,<br/>Desde que Jesús vino a mí!<br/>¡Más allá puedo ver esa Santa Ciudad,<br/>Desde que Jesús vino a mí!<br/>',NULL,189736,5);
INSERT INTO stanza VALUES('S253','5','¡Moraré en la Santa Ciudad, yo lo sé,<br/>Desde que Jesús vino a mí!<br/>¡Soy feliz, tan feliz mientras marchando esté,<br/>Desde que Jesús vino a mí!<br/>',NULL,189737,6);
INSERT INTO stanza VALUES('S254','1','Antes atado por el pecado,<br/>Luchando_en vano me_esclavizó;<br/>Mas libertad gloriosa obtuve,<br/>Cuando Jesús mis grillos rompió.<br/>',NULL,189738,1);
INSERT INTO stanza VALUES('S254','chorus','¡Qué libertad tan maravillosa!<br/>¡No por pecado afligido estoy!<br/>Él para siempre ha de ser mío,<br/>Jesús glorioso Emancipador.<br/>',NULL,189739,2);
INSERT INTO stanza VALUES('S254','2','Libre del yo y afectos carnales,<br/>Libre de envidia, odio y luchar;<br/>Libre de vana ambición mundana,<br/>De la tristeza libre soy ya.<br/>',NULL,189740,3);
INSERT INTO stanza VALUES('S254','3','Libre de orgullo y de locuras,<br/>Libre de amar del oró el brillar;<br/>Libre de ira y todo enojo,<br/>Rapto indecible es mi libertad.<br/>',NULL,189741,4);
INSERT INTO stanza VALUES('S254','4','Libre de miedo y sus tormentos,<br/>De la inquietud y de su dolor;<br/>Libre en Cristo, Redentor mío,<br/>El que mis grillos en dos rompió.<br/>',NULL,189742,5);
INSERT INTO stanza VALUES('S255','1','Nada_he logrado, mas bien, recibí;<br/>Gracia obtuve desde que creí.<br/>Fuera jactancia y presunción,<br/>¡Soy un pecador que gracia_halló!<br/>',NULL,189743,1);
INSERT INTO stanza VALUES('S255','chorus','¡Un pecador que gracia halló!<br/>¡Un pecador que gracia halló!<br/>Esta_es mi_historia, a Dios sea la gloria:<br/>¡Soy un pecador que gracia halló!<br/>',NULL,189744,2);
INSERT INTO stanza VALUES('S255','2','Por el pecado que me dominó<br/>Fui separado muy lejos de Dios.<br/>Jesús me_halló y gozo me dio,<br/>¡Soy un pecador que gracia_halló!<br/>',NULL,189745,3);
INSERT INTO stanza VALUES('S255','3','El llanto nunca logró ayudar,<br/>Misericordia me pudo salvar;<br/>Por mi pecado temí a Dios;<br/>¡Soy un pecador que gracia_halló!<br/>',NULL,189746,4);
INSERT INTO stanza VALUES('S255','4','Hoy yo reboso en mi corazón<br/>Al compartir de mi_amado Señor;<br/>Quiero decirlo con gran fervor:<br/>¡Soy un pecador que gracia_halló!<br/>',NULL,189747,5);
INSERT INTO stanza VALUES('S256','1','Gracia_al oído es<br/>Sonido celestial;<br/>Del cielo_un eco sonará,<br/>La tierra lo_oirá.<br/>',NULL,189748,1);
INSERT INTO stanza VALUES('S256','chorus','¡Gracia sin igual!<br/>¡Basta su poder!<br/>Esta gracia_es Cristo_en mí;<br/>¡Inagotable_es Él!<br/>',NULL,189749,2);
INSERT INTO stanza VALUES('S256','2','La gracia me_otorgó<br/>La vida eternal;<br/>Ella_al Cordero me llevó,<br/>Quitando mi pesar.<br/>',NULL,189750,3);
INSERT INTO stanza VALUES('S256','3','La gracia me guió;<br/>Un peregrino soy;<br/>Me suple cada_hora_a mí<br/>Al ir en pos de Dios.<br/>',NULL,189751,4);
INSERT INTO stanza VALUES('S256','4','La gracia me_hizo orar;<br/>Ella me compungió;<br/>Me ha guardado hasta_aquí;<br/>Me_anima_el corazón.<br/>',NULL,189752,5);
INSERT INTO stanza VALUES('S256','5','La gracia cubrirá<br/>La obra de Su_amor;<br/>La piedra cimera_Èl pondrá;<br/>Digna_es de_aclamación.<br/>',NULL,189753,6);
INSERT INTO stanza VALUES('S256','6','¡Oh, que Tu gracia_en mí<br/>Inspire_el corazón!<br/>Todo mi ser ofrezco_a Ti;<br/>Mis días Tuyos son.<br/>',NULL,189754,7);
INSERT INTO stanza VALUES('S257','1','¡Qué admirable gracia fue<br/>La que_hasta mí llegó!<br/>Yo ciego fui mas veo hoy,<br/>Perdido, me_encontró.<br/>',NULL,189755,1);
INSERT INTO stanza VALUES('S257','2','La gracia me enseñó a temer,<br/>Su gracia me alivió;<br/>¡Preciosa fue tal gracia a mí<br/>La hora en que creí!<br/>',NULL,189756,2);
INSERT INTO stanza VALUES('S257','3','Promesas buenas mi Señor<br/>En Su Palabra dio;<br/>Mi escudo es y mi porción<br/>Mientras que viva yo.<br/>',NULL,189757,3);
INSERT INTO stanza VALUES('S257','4','Y cuando por mil años más<br/>Brillemos como el sol,<br/>Con alabanzas se honrará<br/>Su gracia eternal.<br/>',NULL,189758,4);
INSERT INTO stanza VALUES('S258','1','Cuando_el cordón de plata_en mí<br/>Se_afloje, no podré cantar;<br/>Pero qué gozo_al despertar<br/>Y ver a mi Rey celestial.<br/>',NULL,189759,1);
INSERT INTO stanza VALUES('S258','chorus','Y cara_a cara lo veré,<br/>"Salvo por gracia", clamaré.<br/>Y cara_a cara lo veré,<br/>"Salvo por gracia", clamaré.<br/>',NULL,189760,2);
INSERT INTO stanza VALUES('S258','2','Mi casa terrenal caerá:<br/>Cuando será, yo no lo se;<br/>Mas esto se: que mi lugar<br/>Con mi gran todo_en todo es.<br/>',NULL,189761,3);
INSERT INTO stanza VALUES('S258','3','Oh, cuando venga mi Señor,<br/>¡Qué bendición! ¡Yo lo veré!<br/>Él me dirá: "Bien hecho fue",<br/>Y en Su descanso entraré.<br/>',NULL,189762,4);
INSERT INTO stanza VALUES('S258','4','Hasta_aquel día velaré,<br/>Lista mi lámpara_estará;<br/>Cuando salude al Salvador,<br/>Mi fe en vista cambiará.<br/>',NULL,189763,5);
INSERT INTO stanza VALUES('S259','1','Querido Salvador,<br/>Me perteneces hoy;<br/>Tu nombre_he de clamar;<br/>Mi corazón te doy.<br/>',NULL,189764,1);
INSERT INTO stanza VALUES('S259','chorus','¡Mío, Tú,<br/>Querido Señor!<br/>Sé que_eres mío,<br/>Mi buen Salvador.<br/>',NULL,189765,2);
INSERT INTO stanza VALUES('S259','2','Eres amigo fiel<br/>De todo pecador.<br/>Por gracia salvo fui<br/>Al escuchar Tu voz.<br/>',NULL,189766,3);
INSERT INTO stanza VALUES('S259','3','Mi duro corazón<br/>Tocaste con Tu_hablar.<br/>Debido_a Tu perdón,<br/>Disfruto gozo_y paz.<br/>',NULL,189767,4);
INSERT INTO stanza VALUES('S259','4','Así te_alabaré;<br/>Hoy mío_eres Señor;<br/>Yo nunca dudaré,<br/>Pues sé que Tuyo soy.<br/>',NULL,189768,5);
INSERT INTO stanza VALUES('S260','1','Fuente de las bendiciones,<br/>De Tu gracia_he de cantar;<br/>Por Tu gran misericordia<br/>Tengo que_alabarte más.<br/>Yo, Señor, era un extraño,<br/>Lejos de la faz de Dios;<br/>Mas Tu sangre redentora,<br/>Del peligro me salvó.<br/>',NULL,189769,1);
INSERT INTO stanza VALUES('S260','2','Constreñido soy a diario;<br/>De_esta gracia soy deudor.<br/>Que Tu gracia, como_un lazo,<br/>Me amarre_a Ti Señor.<br/>Muéstrame cuán suficiente<br/>Es Tu gracia para hoy,<br/>Mientras canto del profundo,<br/>Inmutable_amor de Dios.<br/>',NULL,189770,2);
INSERT INTO stanza VALUES('S260','3','Siento que soy muy propenso<br/>A_apartarme de mi Dios.<br/>Sella_el corazón, te ruego,<br/>Con Tu_Espíritu, Señor.<br/>Rescatado del pecado,<br/>Por Tu sangre, Salvador,<br/>Que_ande como_un peregrino,<br/>Como hijo real de Dios.<br/>',NULL,189771,3);
INSERT INTO stanza VALUES('S261','1','¡Oh, qué salvación tan grande!<br/>Una fuente se abrió,<br/>Fluye_a toda tierra_y pueblo<br/>Del herido Salvador.<br/>¡Oh, qué salvación tan grande!<br/>¡Un torrente de_Él fluyó!<br/>¡Un torrente de_Él fluyó!<br/>',NULL,189772,1);
INSERT INTO stanza VALUES('S261','2','¡Qué revelación tan grande!<br/>La corriente carmesí<br/>Lleva toda culpa_y mancha,<br/>Como nieve la_hace así.<br/>¡Oh, qué salvación tan grande!<br/>¡Gozo inefable_aquí!<br/>¡Gozo inefable_aquí!<br/>',NULL,189773,2);
INSERT INTO stanza VALUES('S261','3','Su amor, como_un torrente,<br/>Llega_a todo mi_interior;<br/>Lava todo pensamiento,<br/>Sentimiento e_intención.<br/>¡Oh, qué salvación tan grande!<br/>¡Del pecado_y su poder!<br/>¡Del pecado_y su poder!<br/>',NULL,189774,3);
INSERT INTO stanza VALUES('S261','4','Vida inmortal es mía,<br/>Cristo en mi corazón:<br/>Dios y_el hombre siendo uno,<br/>¡Insondable comunión!<br/>¡Oh, qué salvación tan grande!<br/>¡Vivo_en Su resurrección!<br/>¡Vivo_en Su resurrección!<br/>',NULL,189775,4);
INSERT INTO stanza VALUES('S261','5','Dudas, penas y tinieblas,<br/>Ya no sufro ni su_afán;<br/>Por mi fe en Jesucristo,<br/>Se_esfumó la_oscuridad.<br/>¡Oh, qué salvación tan grande!<br/>¡Plena_y por la_eternidad!<br/>¡Plena_y por la_eternidad!<br/>',NULL,189776,5);
INSERT INTO stanza VALUES('S262','1','En mi espíritu<br/>La gracia reina ya.<br/>Me libra del pecado vil<br/>Y de lo natural.<br/>',NULL,189777,1);
INSERT INTO stanza VALUES('S262','chorus','¡Gracia sin igual!<br/>¡Basta su poder!<br/>Esta gracia_es Cristo_en mí;<br/>¡Inagotable_es Él!<br/>',NULL,189778,2);
INSERT INTO stanza VALUES('S262','2','La gracia me guió;<br/>Un peregrino soy;<br/>Me suple cada hora_a mí<br/>Al ir en pos de Dios.<br/>',NULL,189779,3);
INSERT INTO stanza VALUES('S262','3','Suprema gracia es<br/>El encarnado Dios,<br/>Es Dios que_a la tierra llegó,<br/>Es Dios en mi_interior.<br/>',NULL,189780,4);
INSERT INTO stanza VALUES('S262','chorus','¡Por gracia de Dios<br/>Hoy soy lo que soy!<br/>El Dios-hombre vive_en mi.<br/>Su gracia_es mía hoy.<br/>',NULL,189781,5);
INSERT INTO stanza VALUES('S263','1','Una fuente vanamente yo busqué,<br/>Que no se_agotara más;<br/>Lo que me_ofreció la tierra_inútil fue,<br/>Nada me pudo saciar.<br/>',NULL,189782,1);
INSERT INTO stanza VALUES('S263','chorus','Bebo de la fuente inagotable hoy,<br/>Bebo de la fuente de la vida  yo.<br/>Hallo en gran medida<br/>Gozo y_alegría,<br/>De la fuente de la vida bebo yo.<br/>',NULL,189783,2);
INSERT INTO stanza VALUES('S263','2','Por desierto de pecado ya no voy,<br/>Manantial vivo_encontré;<br/>Y mi copa de_alegría llena_está,<br/>Cristo_es mi Señor y Rey.<br/>',NULL,189784,3);
INSERT INTO stanza VALUES('S263','3','Siempre_encuentro_aquí descanso y solaz,<br/>Con grande satisfacción;<br/>Al volar los días, hay consuelo_y paz,<br/>Bendito_es mi corazón.<br/>',NULL,189785,4);
INSERT INTO stanza VALUES('S263','4','Tengo aquí seguro un suplir sin fin,<br/>Por toda la_eternidad;<br/>A_esta fuente sanadora acudiré,<br/>Mi alma cansada a lavar.<br/>',NULL,189786,5);
INSERT INTO stanza VALUES('S264','1','Oí la voz de mi Jesús:<br/>“Oh ven a descansar;<br/>Reclínate_en Mi pecho ya;,<br/>Sí, ven a reposar".<br/>Yo vine_a Él, tal como soy,<br/>Tan triste_y sin vigor;<br/>En Él hallé descanso_y paz,<br/>Y Él me alegró.<br/>',NULL,189787,1);
INSERT INTO stanza VALUES('S264','2','Oí la voz de mi Jesús:<br/>"Yo libremente doy<br/>Del agua viva a beber:<br/>Tu sed ya sacia hoy".<br/>Yo vine_a Él, y ahí bebí<br/>Del vivo manantial;<br/>Sació mi sed y reviví,<br/>Mi vida_en Él está.<br/>',NULL,189788,2);
INSERT INTO stanza VALUES('S264','3','Oí la voz de mi Jesús:<br/>"La luz del mundo soy;<br/>Miradme, pues el alba doy;<br/>Seré Tu_esplendor".<br/>Miré_a Jesús y_en Él hallé<br/>Mi_estrella y mi sol;<br/>En luz de vida andaré,<br/>Por siempre, como hoy.<br/>',NULL,189789,3);
INSERT INTO stanza VALUES('S265','1','Desde lejos oigo de las luchas y afanes<br/>Que resultan del pecado que reinando_está;<br/>Dudas y temores sólo_en vano a mí me llaman,<br/>Nada_ha de moverme de mi Canaán.<br/>',NULL,189790,1);
INSERT INTO stanza VALUES('S265','chorus','Yo vivo en la montaña bajo un cielo sin igual;<br/>Yo bebo de la fuente que no se secará;<br/>Oh sí, disfruto por Su gracia del maná tan celestial,<br/>Aquí_en la tierra de mi Canaán.<br/>',NULL,189791,2);
INSERT INTO stanza VALUES('S265','2','Más abajo la tormenta de la duda azota,<br/>Batallando el hombre contra el enemigo está;<br/>Me refugio_en la palabra, ella_es mi castillo;<br/>Nada_aquí me_alcanza en mi Canaán.<br/>',NULL,189792,3);
INSERT INTO stanza VALUES('S265','3','Aunque vientos tempestuosos soplan, no me alarman,<br/>En Su mano_eterna Dios a mí me_amparará,<br/>Brilla siempre el sol aquí y nada me hace daño;<br/>Yo estoy seguro en mi Canaan.<br/>',NULL,189793,4);
INSERT INTO stanza VALUES('S265','4','Al mirar lo que hace Dios me causa gran asombro,<br/>Y al escuchar Su voz comprendo más Su plan;<br/>Viviendo en mi_espíritu la salvación obtengo,<br/>Con gozo me quedo en mi Canaán.<br/>',NULL,189794,5);
INSERT INTO stanza VALUES('S266','1','Vivamente anhelaba<br/>Yo un fresco manantial,<br/>Que mi ardiente sed lograra<br/>Dentro de mi ser saciar.<br/>',NULL,189795,1);
INSERT INTO stanza VALUES('S266','chorus','¡Aleluya! He_encontrado<br/>Al que mi_alma siempre ansió;<br/>Cristo llena mis anhelos,<br/>Por Su vida salvo soy.<br/>',NULL,189796,2);
INSERT INTO stanza VALUES('S266','2','Algarrobas yo comía<br/>Hasta casi perecer,<br/>Mi alma allí desfalleciendo,<br/>Yo buscando qué comer.<br/>',NULL,189797,3);
INSERT INTO stanza VALUES('S266','3','Yo buscaba las riquezas<br/>Para mi satisfacción,<br/>Más en polvo se bañaba<br/>Mi alma triste en su dolor.<br/>',NULL,189798,4);
INSERT INTO stanza VALUES('S266','4','Fuente de agua que rebosa,<br/>Pan de vida que busqué,<br/>Las riquezas que perduran,<br/>En mi Redentor hallé.<br/>',NULL,189799,5);
INSERT INTO stanza VALUES('S267','1','Mi corazón entona un salmo,<br/>El Señor es mi cantar;<br/>No hubo nunca tal canción en mí;<br/>¡Tengo gozo celestial!<br/>',NULL,189800,1);
INSERT INTO stanza VALUES('S267','chorus','De mi corazón brota un salmo,<br/>Sí, un dulce salmo,<br/>Salmo celestial;<br/>De mi corazón brota un salmo,<br/>Brota un salmo de amor.<br/>',NULL,189801,2);
INSERT INTO stanza VALUES('S267','2','Su gran amor me dio Su vida,<br/>Recibí la salvación;<br/>¡Qué bendición, por Cristo vivo yo!<br/>Canto con gozo Su amor.<br/>',NULL,189802,3);
INSERT INTO stanza VALUES('S267','3','¡Qué luz, Jesús mis pasos guía!<br/>Con graduales salmos voy;<br/>¡Qué paz, que Cristo ahora vive en mí,<br/>Alabanzas yo le doy.<br/>',NULL,189803,4);
INSERT INTO stanza VALUES('S267','4','¡Qué libertad! Seré llevado,<br/>Y en victoria he de cantar;<br/>¡Qué honra! Reinaré con el Señor,<br/>Gozo de ángeles se oirá.<br/>',NULL,189804,5);
INSERT INTO stanza VALUES('S267','5','¡Qué bendición, la ciudad santa!<br/>Aguas de vida a beber;<br/>El árbol de la vida nos dará<br/>De sus frutos a comer.<br/>',NULL,189805,6);
INSERT INTO stanza VALUES('S267','note','**Cáticos graduales (Salmos 120-134)**<br/>',NULL,189806,7);
INSERT INTO stanza VALUES('S268','1','Hoy frente_al trono celestial,<br/>Defensa firme tengo_allí;<br/>Un Sumo Sacerdote real<br/>Quien intercede hoy por mí.<br/>',NULL,189807,1);
INSERT INTO stanza VALUES('S268','2','Sus manos y Su corazón:<br/>Mi nombre_allí escrito_está;<br/>Yo se que Cristo_está con Dios,<br/>Y nada de_Él me_apartará.<br/>',NULL,189808,2);
INSERT INTO stanza VALUES('S268','3','Cuando se_acerca el tentador,<br/>Cuando Satán viene_a acusar,<br/>Yo miro_arriba, al Señor,<br/>Quien puso fin a mi pecar.<br/>',NULL,189809,3);
INSERT INTO stanza VALUES('S268','4','Ya que murió mi Salvador,<br/>Mi alma libre_ahora_está;<br/>A Cristo mira_el justo Dios,<br/>Y satisfecho queda ya.<br/>',NULL,189810,4);
INSERT INTO stanza VALUES('S268','5','Mirad al Cordero de Dios,<br/>El Justo, quien resucitó,<br/>El inmutable gran Yo Soy,<br/>El Rey de gloria_y gracia hoy.<br/>',NULL,189811,5);
INSERT INTO stanza VALUES('S268','6','Ahora uno soy con Él<br/>Pues con Su sangre me compró;<br/>Mi vida_está_escondida_en Él,<br/>Con Cristo, el Salvador, mi Dios.<br/>',NULL,189812,6);
INSERT INTO stanza VALUES('S269','1','¡Completo_en Ti!, no por mi obrar,<br/>Mas por Tu obra sin igual;<br/>Tu sangre me compró_el perdón,<br/>Estoy completo_en Ti, Señor.<br/>',NULL,189813,1);
INSERT INTO stanza VALUES('S269','chorus','Hoy justo soy, ¡qué bendición!<br/>Y santo en Ti,‿¡qué salvación!<br/>Tu sangre me compró_el perdón;<br/>Me glorificarás, Señor.<br/>',NULL,189814,2);
INSERT INTO stanza VALUES('S269','2','¡Completo_en Ti! no más pecar,<br/>Tu gracia reina_en su lugar;<br/>Tu voz espanta al tentador,<br/>Yo firme en Ti, por Tu favor.<br/>',NULL,189815,3);
INSERT INTO stanza VALUES('S269','3','¡Completo_en Ti!, sin escasez,<br/>Todo lo bueno en Ti se ve;<br/>Ya que eres todo para mí,<br/>No pido más, completo en Ti.<br/>',NULL,189816,4);
INSERT INTO stanza VALUES('S269','4','Cuando a Tu trono, mi Jesús,<br/>Todas las tribus juntes Tú,<br/>Entre los elegidos, yo<br/>Completo en Ti seré, Señor.<br/>',NULL,189817,5);
INSERT INTO stanza VALUES('S270','1','No sé por qué el sumo Dios<br/>Su gracia reveló,<br/>Ni   por qué,_indigno como soy,<br/>Jesús me redimió.<br/>',NULL,189818,1);
INSERT INTO stanza VALUES('S270','chorus','Mas yo sé a quién he creído<br/>Y_estoy seguro que es poderoso,<br/>Guardando lo encomendado<br/>Hasta_el día_en que vendrá.<br/>',NULL,189819,2);
INSERT INTO stanza VALUES('S270','2','No sé cómo Su fe me dio<br/>Para salvarme así,<br/>Ni cómo Su Palabra fiel<br/>Tal paz legó en mí.<br/>',NULL,189820,3);
INSERT INTO stanza VALUES('S270','3','No sé cómo el Espíritu<br/>Convence al pecador,<br/>Y la Palabra de Jesús<br/>Le infunde fe y amor.<br/>',NULL,189821,4);
INSERT INTO stanza VALUES('S270','4','No sé si el bien o si el mal<br/>Me esperan hoy aquí,<br/>O si tristeza o gozo habrá<br/>Antes de Él venir.<br/>',NULL,189822,5);
INSERT INTO stanza VALUES('S270','5','No sé cuándo el Señor vendrá,<br/>De noche ó al clarear,<br/>Ni sé si he de fallecer<br/>O me_arrebatará.<br/>',NULL,189823,6);
INSERT INTO stanza VALUES('S271','1','¡Cuán maravilloso es mi Salvador!<br/>Jesús, mi amado Señor;<br/>Me_esconde_en la peña hendida por mí,<br/>Me_abreva con ríos de_amor.<br/>',NULL,189824,1);
INSERT INTO stanza VALUES('S271','chorus','Me_esconde_en la peña hendida por mi,<br/>Y Él es mi sombra allí;<br/>Esconde mi alma en Su hondo_amor,<br/>Su mano me cubre aquí,<br/>Su mano me cubre aquí.<br/>',NULL,189825,2);
INSERT INTO stanza VALUES('S271','2','¡Cuán maravilloso es mi Salvador!<br/>Me_alivia de todo pesar;<br/>Mi día es Él, fortaleza me da;<br/>Me brinda sostén sin igual.<br/>',NULL,189826,3);
INSERT INTO stanza VALUES('S271','3','Me colma a diario con gran bendición,<br/>Con Su plenitud divinal;<br/>Yo canto con éxtasis: ¡Gloria al Señor<br/>Por tal Redentor sin igual!<br/>',NULL,189827,4);
INSERT INTO stanza VALUES('S271','4','De Su resplandor yo vestido seré;<br/>En nubes al fin lo veré.<br/>Allí con millones podré yo gritar<br/>De Su salvación grande y fiel.<br/>',NULL,189828,5);
INSERT INTO stanza VALUES('S272','1','¡Cuán firme cimiento para nuestra fe<br/>Ha puesto el Señor en Su Palabra fiel!<br/>¿Qué más Él dirá que lo que ya habló<br/>A_aquel que_en Jesús su refugió buscó?<br/>',NULL,189829,1);
INSERT INTO stanza VALUES('S272','2','"No temas, no cedas, contigo estoy,<br/>Pues Yo soy tu Dios y socorro te doy.<br/>Yo te daré fuerzas y firme_estarás;<br/>Mi diestra potente te sustentará".<br/>',NULL,189830,2);
INSERT INTO stanza VALUES('S272','3','"Cuando_aguas profundas te llame_a cruzar,<br/>Los ríos de pena no_haré desbordar.<br/>Contigo_estaré y te bendeciré;<br/>Ahí tus problemas santificaré".<br/>',NULL,189831,3);
INSERT INTO stanza VALUES('S272','4','"Cuando_en prueba_ardiente se halle tu_andar,<br/>Mi gracia_abundante allí te_hallará.<br/>No daña la llama, mas éste_es Mi plan:<br/>Quemaré la_escoria para_oro ganar".<br/>',NULL,189832,4);
INSERT INTO stanza VALUES('S272','5','"Al envejecer, aún Mi pueblo verá<br/>Mi_amor soberano que no cesará;<br/>Aun cuando de canas cubiertos estén,<br/>Serán Mis corderos y los cargaré".<br/>',NULL,189833,5);
INSERT INTO stanza VALUES('S272','6','El alma que_en Cristo reposando_esté,<br/>Nunca_a su_enemigo se la dejaré;<br/>Aún si la_atacan las huestes del mal,<br/>Yo nunca jamás la he de desertar.<br/>',NULL,189834,6);
INSERT INTO stanza VALUES('S273','1','Firme en las promesas de mi Dios y Rey,<br/>Por los siglos mi_alabanza cantaré,<br/>Gloria_en las alturas yo proclamaré,<br/>Firme en las promesas de mi Rey.<br/>',NULL,189835,1);
INSERT INTO stanza VALUES('S273','chorus','Firme, firme,<br/>Firme_en las promesas de mi Dios y Cristo;<br/>Firme, firme,<br/>Hoy firme_en las promesas de mi Dios.<br/>',NULL,189836,2);
INSERT INTO stanza VALUES('S273','2','Firme en las promesas que no fallarán<br/>Cuando ataquen los temores y_el afán;<br/>Afirmado_en Su Palabra eternal,<br/>Firme_en las promesas de mi Dios.<br/>',NULL,189837,3);
INSERT INTO stanza VALUES('S273','3','Firme en las promesas puedo ahora ver<br/>Que Su sangre ha limpiado hoy mi ser,<br/>Firme en Cristo, tengo libertad en Él,<br/>Firme_en las promesas de mi Rey.<br/>',NULL,189838,4);
INSERT INTO stanza VALUES('S273','4','Firme en las promesas de Cristo el Señor,<br/>Siempre_unido_a Él con lazos de amor,<br/>Por Su_Espíritu, mi espada, venzo yo,<br/>Firme_en las promesas de mi Dios.<br/>',NULL,189839,5);
INSERT INTO stanza VALUES('S273','5','Firme en las promesas no desmayaré,<br/>Siempre al Espíritu responderé,<br/>Y_en mi Salvador descansaré por fe,<br/>Firme_en las promesas de mi Rey.<br/>',NULL,189840,6);
INSERT INTO stanza VALUES('S274','1','Dios del mundo me salvó;<br/>Jamás volveré otra vez.<br/>Dios del mundo me salvó;<br/>Jamás volveré otra vez.<br/>',NULL,189841,1);
INSERT INTO stanza VALUES('S274','chorus','No, no, no, no, no,<br/>Jamás volveré otra vez.<br/>No, no, no, no, no,<br/>Jamás volveré otra vez.<br/>',NULL,189842,2);
INSERT INTO stanza VALUES('S274','2','Babilonia ya dejé;<br/>Jamás volveré otra vez.<br/>Babilonia ya dejé;<br/>Jamás volveré otra vez.<br/>',NULL,189843,3);
INSERT INTO stanza VALUES('S274','3','La iglesia local hallé;<br/>Jamás volveré otra vez.<br/>La iglesia local hallé;<br/>Jamás volveré otra vez.<br/>',NULL,189844,4);
INSERT INTO stanza VALUES('S274','4','Desde que toqué_al Señor;<br/>Jamás volveré otra vez.<br/>Desde que toqué_al Señor;<br/>Jamás volveré otra vez.<br/>',NULL,189845,5);
INSERT INTO stanza VALUES('S274','5','Cristo_es todo para mí;<br/>Jamás volveré otra vez.<br/>Cristo_es todo para mí;<br/>Jamás volveré otra vez.<br/>',NULL,189846,6);
INSERT INTO stanza VALUES('S274','6','Gloria_a Dios, ya tengo hogar;<br/>Jamás volveré otra vez.<br/>Gloria_a Dios, ya tengo hogar;<br/>Jamás volveré otra vez.<br/>',NULL,189847,7);
INSERT INTO stanza VALUES('S274','7','Soy para el recobro hoy;<br/>Jamás volveré otra vez.<br/>Soy para el recobro hoy;<br/>Jamás volveré otra vez.<br/>',NULL,189848,8);
INSERT INTO stanza VALUES('S275','1','¡Oh, qué gozo ya<br/>Llena mi corazón!<br/>Ya Dios me quitó<br/>Un corazón duro y<br/>Lo reemplazó<br/>Con uno de carne:<br/>Nuevo hombre soy.<br/>¡Oh, qué gozo ya<br/>Llena mi corazón!<br/>',NULL,189849,1);
INSERT INTO stanza VALUES('S275','2','Su_Espíritu llena,<br/>Me llena a mí.<br/>Borrando_Él está<br/>Todo mi pecado_y<br/>Debilidad;<br/>Su vida en mí, frutos<br/>De justicia da.<br/>Su_Espíritu llena,<br/>Me llena a mí.<br/>',NULL,189850,2);
INSERT INTO stanza VALUES('S276','1','En Cristo disfrutando:<br/>¡Libertado de Adán!<br/>¡Lo viejo ya se hace,<br/>Nuevo y celestial!<br/>¡Gloria a Dios por el probar de<br/>Vida, paz y libertad!<br/>¡En Cristo_estoy por la_eternidad!<br/>',NULL,189851,1);
INSERT INTO stanza VALUES('S277','1','Si paz como_un río ocupa mi ser<br/>O afligen las olas del mar;<br/>Cualquiera que sea Tu_arreglo, diré:<br/>"¡Está bien, con mi_alma_está bien!".<br/>',NULL,189852,1);
INSERT INTO stanza VALUES('S277','chorus','"¡Está bien! (¡Está bien!)<br/>¡Tengo paz! (¡Tengo paz!)<br/>¡Está bien! ¡Con mi alma_está bien!<br/>',NULL,189853,2);
INSERT INTO stanza VALUES('S277','2','Si viene la prueba_o me tienta Satán,<br/>Me guarda_esta seguridad:<br/>Que Cristo mi_incapacidad ya miró,<br/>Y por mi_alma Su sangre vertió.<br/>',NULL,189854,3);
INSERT INTO stanza VALUES('S277','3','¡Qué gozo_es pensar; mi pecado_Él llevó!<br/>Todo mi pecado_Él quitó;<br/>Clavólo_en la cruz, no lo cargo más yo,<br/>¡Alma mía, alaba_al Señor!<br/>',NULL,189855,4);
INSERT INTO stanza VALUES('S277','4','Que Cristo hoy sea mi vida_y vivir,<br/>Incluso en la_oscuridad;<br/>En vida o_en muerte no_habrá ansiedad<br/>Pues Tu paz a mi alma darás.<br/>',NULL,189856,5);
INSERT INTO stanza VALUES('S278','1','Muchos años pasé_en vano yo,<br/>Sin tener en cuenta_a mi Señor;<br/>No sabía que_Él por mí murió<br/>En Gólgota.<br/>',NULL,189857,1);
INSERT INTO stanza VALUES('S278','chorus','Su misericordia me_alcanzó;<br/>Su perdón gratuitamente dio;<br/>Libertad a mi_alma Él brindó<br/>En Gólgota.<br/>',NULL,189858,2);
INSERT INTO stanza VALUES('S278','2','Su Palabra me iluminó,<br/>Mis pecados ella confirmó;<br/>Yo volví con pena y temor<br/>Al Gólgota<br/>',NULL,189859,3);
INSERT INTO stanza VALUES('S278','3','A Jesús mi todo le_entregué,<br/>Él es hoy mi Redentor y Rey;<br/>Gozo indecible cantaré<br/>Por Gólgota.<br/>',NULL,189860,4);
INSERT INTO stanza VALUES('S278','4','¡Oh, qué grande_amor y salvación!<br/>¡Oh, qué gracia Dios nos otorgó!<br/>¡Oh, qué brecha_inmensa Él cerró<br/>En Gólgota!<br/>',NULL,189861,5);
INSERT INTO stanza VALUES('S279','1','En mi alma_ahora brilla_el sol<br/>Con más gloria y fulgor<br/>Que luz del cielo terrenal<br/>Pues mi luz es mi Señor.<br/>',NULL,189862,1);
INSERT INTO stanza VALUES('S279','chorus','Luz bendita, luz bendita<br/>Oh qué paz, oh qué felicidad<br/>Cuando veo la sonrisa de Jesús<br/>En mi alma_hay luz del sol.<br/>',NULL,189863,2);
INSERT INTO stanza VALUES('S279','2','En mi alma hay una canción,<br/>Es música_a mi Rey;<br/>Y aun si no puedo cantar,<br/>Jesús me_escucha bien.<br/>',NULL,189864,3);
INSERT INTO stanza VALUES('S279','3','En mi alma primavera hay<br/>Pues cuando_Él cerca está,<br/>Mi corazón entona paz;<br/>¡Hay gracia sin igual!<br/>',NULL,189865,4);
INSERT INTO stanza VALUES('S279','4','En mi alma_alegre hay loor,<br/>Esperanza y amor<br/>Porque hoy y siempre mi Señor<br/>Es mi gozo_y bendición.<br/>',NULL,189866,5);
INSERT INTO stanza VALUES('S280','1','Desde que Cristo me libró<br/>De mi  pecado_y me salvó,<br/>En medio de_ayes y temor,<br/>Tengo_a Jesús, mi gozo_y paz.<br/>',NULL,189867,1);
INSERT INTO stanza VALUES('S280','chorus','¡Oh, aleluya, Cristo es<br/>Mi gozo y mi eterno bien!<br/>En tierra_o mar, doquiera esté,<br/>Si está Jesús, mi gozo_es Él.<br/>',NULL,189868,2);
INSERT INTO stanza VALUES('S280','2','La tierra amarga antes fue,<br/>Hasta que Cristo trajo fe;<br/>Llena de gozo mi_alma está<br/>Al contemplar aquí Su faz.<br/>',NULL,189869,3);
INSERT INTO stanza VALUES('S280','3','¿Qué_importa dónde vivo yo?<br/>Ya sea en choza o_en mansión;<br/>En el desierto o_en vergel<br/>Si está Jesús, mi gozó_es Él.<br/>',NULL,189870,4);
INSERT INTO stanza VALUES('S281','1','Cual ciervo que_anhela beber<br/>Del agua_en el calor,<br/>Así también anhelo yo<br/>Tu fresca gracia,_oh Dios.<br/>',NULL,189871,1);
INSERT INTO stanza VALUES('S281','2','¿Por qué te_abates, mi_alma, así?<br/>Por qué turbada_estás?<br/>Confía_en Dios; Él cambiará<br/>Tu llanto_en gozo_y paz.<br/>',NULL,189872,2);
INSERT INTO stanza VALUES('S281','3','Por Ti, mi Dios, viviente Dios,<br/>Sedienta mi_alma_está;<br/>Oh, ¿cuándo yo veré Tu faz,<br/>Divina Majestad?<br/>',NULL,189873,3);
INSERT INTO stanza VALUES('S281','4','¿Por cuánto tiempo, Fuerte Dios,<br/>Me quedo_en luto atroz,<br/>Escarnecido y_en prisión,<br/>Expuesto_a mi_opresor?<br/>',NULL,189874,4);
INSERT INTO stanza VALUES('S281','5','Por qué te_abates, mi_alma,_así?<br/>Ten fe y cantarás<br/>Las alabanzas a tu Dios,<br/>Tu fuente eternal.<br/>',NULL,189875,5);
INSERT INTO stanza VALUES('S282','1','Mi meta única_es el mismo Dios,<br/>No paz o gozo ni más bendición;<br/>De Él depende que yo llegue_allí;<br/>Por cualquier senda, hazlo mi Señor.<br/>',NULL,189876,1);
INSERT INTO stanza VALUES('S282','2','Busca la fe su meta: el mismo Dios;<br/>Sigue_el amor confiando en su Señor,<br/>Prosigue mi_alma, apoyada_en Él,<br/>Hasta que cumpla Dios mi oración.<br/>',NULL,189877,2);
INSERT INTO stanza VALUES('S282','3','No_importa que el camino oscuro_esté,<br/>No importa qué costoso pueda ser;<br/>Él sabe cómo_hacerme a mí llegar<br/>Hasta la meta con toda_estrechez.<br/>',NULL,189878,3);
INSERT INTO stanza VALUES('S282','4','Sólo esto sé, no lo puedo negar;<br/>Hago una cosa, sigo_a mi Señor;<br/>Mi Dios, mi gloria día_a día es,<br/>Y en la gloria, Él mi galardón.<br/>',NULL,189879,4);
INSERT INTO stanza VALUES('S283','1','Vida_increada, poderoso Dios,<br/>Inclina Tu oído_a mi clamor;<br/>Gloria_indecible a tu_alrededor;<br/>Tengo que conocerte, mi Creador.<br/>',NULL,189880,1);
INSERT INTO stanza VALUES('S283','2','Oh, por la cruz que mi Cristo sufrió,<br/>Oh, por la muerte de mi Redentor,<br/>De las tinieblas, sálvame Señor,<br/>Al reino de Tu luz, mi Salvador.<br/>',NULL,189881,2);
INSERT INTO stanza VALUES('S283','3','Desde el centro, lléname Señor,<br/>Oh, lléname y hazme rebosar;<br/>Tu gloria_irradie de Tu mismo ser<br/>Y me rodee por completo ya.<br/>',NULL,189882,3);
INSERT INTO stanza VALUES('S283','4','Vida_increada, Santísimo Dios,<br/>Vivificante_Espíritu en mí,<br/>Crea en mi Tu misma expresión,<br/>Algo que_atraiga_a otros hacia Tí.<br/>',NULL,189883,4);
INSERT INTO stanza VALUES('S283','5','¡Padre, mi búsqueda al fin cesó!<br/>Reinando_en vida con Cristo estoy.<br/>En Él yo triunfo, ¡qué satisfacción!<br/>Es por Su misma cruz que Suyo soy.<br/>',NULL,189884,5);
INSERT INTO stanza VALUES('S284','1','¡Una zarza_ardiente_aquí<br/>En la tierra para Dios!<br/>Que_a Tu nombre gloria dé,<br/>Es mi_anhelo, buen Señor.<br/>',NULL,189885,1);
INSERT INTO stanza VALUES('S284','2','Una zarza, nada más,<br/>Donde Dios pueda morar,<br/>Por la cual Él pueda_hablar<br/>Y se pueda expresar.<br/>',NULL,189886,2);
INSERT INTO stanza VALUES('S284','3','Su amor por el mortal,<br/>Su designio eternal,<br/>Que_arde sin luz terrenal,<br/>Mas con gloria celestial.<br/>',NULL,189887,3);
INSERT INTO stanza VALUES('S284','4','Sí, Dios en la zarza_está,<br/>Sólo_el fuego_ahí se ve;<br/>Hazme eso, hazlo_oh, Dios,<br/>Que_a Tu nombre gloria dé.<br/>',NULL,189888,4);
INSERT INTO stanza VALUES('S285','1','¡Tú, de mi alma, Imán!<br/>Acércame_hasta que<br/>Ya no palpite_en mí el yo,<br/>Y en quietud esté.<br/>',NULL,189889,1);
INSERT INTO stanza VALUES('S285','2','¡Sol de mi corazón!<br/>Satura todo_allí<br/>Para que brinde Tu jardín<br/>Fragancia dulce_a Ti.<br/>',NULL,189890,2);
INSERT INTO stanza VALUES('S285','3','¡Tú, mi Rescatador!<br/>A poseerme, ven;<br/>Me redimiste, úsame<br/>Conforme_a Tu placer.<br/>',NULL,189891,3);
INSERT INTO stanza VALUES('S285','4','¡Señor de vida_y luz!<br/>Me postro ante Ti;<br/>Un santo privilegio es<br/>Obedecerte_aquí.<br/>',NULL,189892,4);
INSERT INTO stanza VALUES('S285','5','¡Tú, inefable Don!<br/>Llenas mi corazón;<br/>Al quebrantarlo, pruebo yo<br/>Lo dulce de Tu_amor.<br/>',NULL,189893,5);
INSERT INTO stanza VALUES('S286','1','Con fuego santo ven, Señor,<br/>Ven a_inspirar mi corazón;<br/>Tu sangre me purgó;<br/>Tu mismo ser revela_a mí,<br/>Tu fuerte obra_hazme sentir,<br/>Ya que nací de Dios.<br/>',NULL,189894,1);
INSERT INTO stanza VALUES('S286','2','Nada divida_el corazón,<br/>Ya que_en la cruz contigo_estoy;<br/>Que viva para Dios.<br/>Que muera_al mundo_y su_esplendor,<br/>Con su placer y diversión;<br/>Mi gloria es el Señor.<br/>',NULL,189895,2);
INSERT INTO stanza VALUES('S286','3','Eterno_anhelo_inspira_en mí<br/>Con insaciable sed de Ti,<br/>Y lléname, Jesús.<br/>No me des menos que Tu ser,<br/>En mí que vivas con poder;<br/>Ven con Tu plenitud.<br/>',NULL,189896,3);
INSERT INTO stanza VALUES('S286','4','Se pierda_en Ti mi voluntad,<br/>Luz en Tu luz así verá<br/>Mi alma_al ver Tu faz;<br/>Tú me llamaste a probar<br/>Un corazón de_amor sin par<br/>Y vida_en santidad.<br/>',NULL,189897,4);
INSERT INTO stanza VALUES('S287','1','Oh, amor divino,_excelso,<br/>A la tierra baja ya;<br/>Fija Tu morada_humilde,<br/>En nosotros haz Tu_hogar.<br/>Eres compasión, oh Cristo;<br/>Infinito_y puro_amor;<br/>Que Tu salvación de gracia<br/>Entre_al frágil corazón.<br/>',NULL,189898,1);
INSERT INTO stanza VALUES('S287','2','En el pecho tan herido,<br/>Sopla_el tierno_Espíritu;<br/>Que_heredemos, Señor, todos,<br/>Tu descanso_en plenitud.<br/>Del pecar, quita_el encanto;<br/>Alfa y Omega sé;<br/>Líbranos de ataduras,<br/>Tú,_el Principio_y Fin de fe.<br/>',NULL,189899,2);
INSERT INTO stanza VALUES('S287','3','Ven, oh Todopoderoso,<br/>Tu poder y vida da;<br/>Tu presencia_esté por siempre<br/>En Tus templos sin cesar.<br/>Que nuestro servicio_aceptes<br/>Con Tu santa_aprobación,<br/>Alabándote_y orando<br/>Con entera devoción.<br/>',NULL,189900,3);
INSERT INTO stanza VALUES('S287','4','Haznos puros y sin mancha<br/>Como Tu nueva creación,<br/>Restaurados y perfectos<br/>Por Tu grande salvación;<br/>Llévanos de gloria_en gloria<br/>Hasta contigo reinar,<br/>Hasta_echar nuestras coronas<br/>Ante Ti y exultar.<br/>',NULL,189901,4);
INSERT INTO stanza VALUES('S288','1','¡Oh, Luz de luces, ven!<br/>Y echa hoy de mí<br/>Pecado_y noche vil:<br/>¡Oh, Luz de luces, ven!<br/>',NULL,189902,1);
INSERT INTO stanza VALUES('S288','chorus','¡Oh, Luz tan refulgente,<br/>Mora_en mí por siempre;<br/>¡Oh, Gozo excelente,<br/>Al corazón hoy ven!<br/>',NULL,189903,2);
INSERT INTO stanza VALUES('S288','2','¡Gozo de gozos, ven!<br/>Pon fin a mi pecar,<br/>Trae calma con Tu paz:<br/>¡Gozo de gozos, ven!<br/>',NULL,189904,3);
INSERT INTO stanza VALUES('S288','3','¡Vida de vidas, ven!<br/>Tu vida_expulsará<br/>Pecado_y mortandad:<br/>¡Vida de vidas, ven!<br/>',NULL,189905,4);
INSERT INTO stanza VALUES('S288','4','¡Amor de_amores, ven!<br/>Destruye mi maldad<br/>Traeme Tu novedad:<br/>¡Amor de_amores, ven!<br/>',NULL,189906,5);
INSERT INTO stanza VALUES('S288','5','¡Cielo de cielos, ven!<br/>Que no_haya nube_en mí;<br/>Da_a la tormenta fin:<br/>¡Cielo de cielos, ven!<br/>',NULL,189907,6);
INSERT INTO stanza VALUES('S288','6','¡Mi Dios y Cristo, ven!<br/>Gozo_en suma total,<br/>En mí hoy haz Tu_hogar:<br/>¡Mi Dios y Cristo, ven!<br/>',NULL,189908,7);
INSERT INTO stanza VALUES('S289','1','Ya que_Él murió, hoy vivo yo;<br/>Vivo para Jesús.<br/>Mi_amor, mi vida doy a_Aquel<br/>Que murió en la cruz.<br/>',NULL,189909,1);
INSERT INTO stanza VALUES('S289','chorus','Oh, mi Salvador Jesucristo<br/>Ayúdame_a seguirte_a Ti<br/>En vida, muerte o_al servirte,<br/>Tal como_hiciste Tú por mí.<br/>',NULL,189910,2);
INSERT INTO stanza VALUES('S289','2','Ya que_Él murió, hoy muero yo<br/>Al pecado_y Satán.<br/>¡Qué alta vida_y profunda muerte!<br/>Quiero en ella_entrar.<br/>',NULL,189911,3);
INSERT INTO stanza VALUES('S289','3','Vive_Él por mí; hoy vivo yo<br/>Tal como Él vivió.<br/>Oh, dame hoy Tu naturaleza;<br/>Vive Tu vida_en mí.<br/>',NULL,189912,4);
INSERT INTO stanza VALUES('S289','4','Vive_Él por mí para yo dar<br/>Su_amor al buscador.<br/>Deseo vivir por los demás,<br/>Siguiéndole_en amor.<br/>',NULL,189913,5);
INSERT INTO stanza VALUES('S290','1','Jesús, habita_en mí,<br/>Tu vida mía es;<br/>Déjame ver<br/>Que_inseparable es<br/>Tu vida_en mí.<br/>',NULL,189914,1);
INSERT INTO stanza VALUES('S290','2','Tu vida_exhibe_en mí;<br/>Señor, yo quiero hablar<br/>Y aun pensar<br/>Lo que viene de Ti,<br/>Y no de mí.<br/>',NULL,189915,2);
INSERT INTO stanza VALUES('S290','3','Tu_amor, Tu gozo_y paz<br/>Imparte_al corazón;<br/>¡Hazlo Señor!<br/>Que fluya sin cesar<br/>Tu manantial.<br/>',NULL,189916,3);
INSERT INTO stanza VALUES('S290','4','La vida_y realidad<br/>De Tu resurrección<br/>Con bendición<br/>En la iglesia están;<br/>Oh, ¡dame más!<br/>',NULL,189917,4);
INSERT INTO stanza VALUES('S290','5','En Tu palabra hoy,<br/>Reclamo yo Tu don,<br/>Oh, mi Señor;<br/>En plena_exhultación<br/>Te doy loor.<br/>',NULL,189918,5);
INSERT INTO stanza VALUES('S290','6','Mi vida Tuya es,<br/>Y siempre_así será,<br/>Sin desligar;<br/>Por siempre se_ha de ver<br/>Nuestra_unidad.<br/>',NULL,189919,6);
INSERT INTO stanza VALUES('S291','1','Supremo sé, Señor Jesús;<br/>Ningún credo_o ritual,<br/>Ni_iglesia santa o_humano_amor<br/>A Ti se_igualará.<br/>',NULL,189920,1);
INSERT INTO stanza VALUES('S291','2','Supremo sé, Señor Jesús,<br/>Tu_amor me conquistó;<br/>Mi ego muere_al ver Tu cruz;<br/>Por Ti hoy vivo yo.<br/>',NULL,189921,2);
INSERT INTO stanza VALUES('S291','3','Supremo sé, Señor Jesús,<br/>Oh, llena Tú mi ser;<br/>Así, tal como Tú seré<br/>Y te complaceré.<br/>',NULL,189922,3);
INSERT INTO stanza VALUES('S291','4','Supremo sé, Señor Jesús,<br/>Transforma hoy mi ser;<br/>Tu vida_en mi carne mortal<br/>Pueda resplandecer.<br/>',NULL,189923,4);
INSERT INTO stanza VALUES('S291','5','Supremo sé, Señor Jesús;<br/>Exulta mi_alma_en Ti;<br/>Yo quiero_hacer Tu voluntad,<br/>Tu_esclavo ser, feliz.<br/>',NULL,189924,5);
INSERT INTO stanza VALUES('S292','1','Aumenta, oh Señor,<br/>Mi_amor por Ti.<br/>Escucha mi_oración,<br/>Me_inclino_aquí.<br/>Yo te suplico hoy:<br/>Aumenta mi amor,<br/>Mi amor por Ti,<br/>Señor, por Ti.<br/>',NULL,189925,1);
INSERT INTO stanza VALUES('S292','2','Ansie lo terrenal,<br/>Descanso_y paz;<br/>Ahora sólo_a Ti,<br/>Lo que Tú das.<br/>Ésta_es mi oración:<br/>Aumenta mi amor,<br/>Mi amor por Ti,<br/>Señor, por Ti.<br/>',NULL,189926,2);
INSERT INTO stanza VALUES('S292','3','Que venga la_aflicción,<br/>Penas también;<br/>Tus mensajeros son<br/>Para mi bien.<br/>Con ellos cantaré:<br/>Aumenta mi amor,<br/>Mi amor por Ti,<br/>Señor, por Ti.<br/>',NULL,189927,3);
INSERT INTO stanza VALUES('S292','4','En mi_último gemir<br/>Te_alabaré;<br/>Será_el ruego final<br/>Que te daré.<br/>Aún suplicaré:<br/>Aumenta mi amor,<br/>Mi amor por Ti,<br/>Señor, por Ti.<br/>',NULL,189928,4);
INSERT INTO stanza VALUES('S293','1','La noche viene, ¡oh, conmigo sé!<br/>¡Hondas tinieblas cubren por doquier!<br/>No_hay otra_ayuda ni consolación;<br/>Conmigo sé, querido_Ayudador.<br/>',NULL,189929,1);
INSERT INTO stanza VALUES('S293','2','Veloz el día declinando va;<br/>Se_apaga todo gozo terrenal;<br/>Todo_en mi entorno veo decaer;<br/>Tú, que no cambias, hoy conmigo sé.<br/>',NULL,189930,2);
INSERT INTO stanza VALUES('S293','3','Ven Rey de reyes, sin causar terror;<br/>Trae en Tus alas sanidad, Señor;<br/>Tan compasivo,_atento, tierno_y fiel;<br/>Amigo de_hombres, ven, conmigo sé.<br/>',NULL,189931,3);
INSERT INTO stanza VALUES('S293','4','Yo necesito Tu presencia hoy;<br/>Solo Tu gracia vence_al tentador;<br/>¿Quién como Tú mi guia puede ser?<br/>En sol o sombra, oh conmigo sé.<br/>',NULL,189932,4);
INSERT INTO stanza VALUES('S293','5','Si_estás conmigo, nada temeré:<br/>Penas y llantos pierden su poder.<br/>¿Dónde, sepulcro, tu victoria_está?<br/>Yo triunfaré si Tú conmigo_estás.<br/>',NULL,189933,5);
INSERT INTO stanza VALUES('S294','1','Te necesito hoy,<br/>Cada_hora, buen Señor;<br/>Tu tierna voz a mí<br/>Me trae la paz de Dios.<br/>',NULL,189934,1);
INSERT INTO stanza VALUES('S294','chorus','Señor, te necesito<br/>En cada momento;<br/>Bendíceme, hoy vengo<br/>A Ti, Señor.<br/>',NULL,189935,2);
INSERT INTO stanza VALUES('S294','2','Te necesito hoy,<br/>Mantente junto_a mí;<br/>No sufro tentación<br/>Si_estoy cerca de Ti.<br/>',NULL,189936,3);
INSERT INTO stanza VALUES('S294','3','Te necesito hoy,<br/>En gozo o gemir;<br/>Ven pronto,_habita_en mí<br/>O no podré vivir.<br/>',NULL,189937,4);
INSERT INTO stanza VALUES('S294','4','Te necesito hoy,<br/>Muestra Tu voluntad;<br/>Hoy cumple Tú en mí<br/>Tus promesas sin par.<br/>',NULL,189938,5);
INSERT INTO stanza VALUES('S294','5','Te necesito hoy,<br/>Oh, Santo, Eternal;<br/>Bendito Hijo, así<br/>Hazme Tuyo_en verdad.<br/>',NULL,189939,6);
INSERT INTO stanza VALUES('S295','1','Nada_entre_el Salvador y mi alma,<br/>Nada del mundo_engañador;<br/>Ya renuncié a viles placeres;<br/>Nada_entre mi_alma y mi Señor.<br/>',NULL,189940,1);
INSERT INTO stanza VALUES('S295','chorus','Nada_entre_el Salvador y mi alma,<br/>Para Su faz bendita_apreciar;<br/>Nada impida Su gracia_abundante;<br/>Entre nosotros, nada jamás.<br/>',NULL,189941,2);
INSERT INTO stanza VALUES('S295','2','Nada de los placeres mundanos,<br/>Aunque_inocentes parezcan ser;<br/>Mi corazón jamás se desvíe;<br/>No_hay nada más, mi todo es Él.<br/>',NULL,189942,3);
INSERT INTO stanza VALUES('S295','3','Nada de orgullos y pretenciones;<br/>El yo no se ha de_interponer,<br/>Aunque me cueste tribulaciones,<br/>Estoy resuelto, lo_escojo_a Él.<br/>',NULL,189943,4);
INSERT INTO stanza VALUES('S295','4','Nada, ni_aún las pruebas y luchas,<br/>Ni_el mundo_entero_en oposición;<br/>Negándome, velando_y orando,<br/>He de triunfar sin separación.<br/>',NULL,189944,5);
INSERT INTO stanza VALUES('S296','1','Nada_entre Tú y yo, mi Señor;<br/>Quiero Tu gloria ver,<br/>Mi_alma a Ti traer,<br/>Más de Tu_amor saber;<br/>Entre Tú_y yo, nada Señor.<br/>',NULL,189945,1);
INSERT INTO stanza VALUES('S296','2','Nada_entre Tú y yo, mi Señor;<br/>La bulla terrenal<br/>No_apague_el susurrar<br/>De Tu voz celestial;<br/>Entre Tú_y yo, nada Señor.<br/>',NULL,189946,2);
INSERT INTO stanza VALUES('S296','3','Nada_entre Tú y yo, mi Señor;<br/>Nada que traiga_afán,<br/>Lágrimas o_el rezar,<br/>Nada de falsedad;<br/>Entre Tú_y yo, nada Señor.<br/>',NULL,189947,3);
INSERT INTO stanza VALUES('S296','4','Nada_entre Tú y yo, mi Señor;<br/>Nada de ansiedad,<br/>Duda,_incredulidad,<br/>Cuando tan cerca_estás;<br/>Entre Tú_y yo, nada Señor.<br/>',NULL,189948,4);
INSERT INTO stanza VALUES('S296','5','Nada_entre Tú y yo, mi Señor;<br/>Brilla_en Tu resplandor,<br/>Quita mis velos hoy,<br/>Rey de mi corazón;<br/>Entre Tú_y yo, nada Señor.<br/>',NULL,189949,5);
INSERT INTO stanza VALUES('S296','6','Nada_entre Tú y yo, mi Señor;<br/>Contigo quiero_andar,<br/>Sólo a Ti mirar,<br/>A nadie más amar<br/>Entre Tú_y yo, nada Señor.<br/>',NULL,189950,6);
INSERT INTO stanza VALUES('S296','7','Nada_entre Tú y yo, mi Señor;<br/>Hasta que llegue_a ver<br/>La noche perecer,<br/>Y_el día_amanecer<br/>Entre Tú_y yo, nada Señor.<br/>',NULL,189951,7);
INSERT INTO stanza VALUES('S297','1','Si mi senda lleva<br/>A la cruz, Señor,<br/>Si por donde guías<br/>Sufro yo dolor,<br/>Sea la recompensa<br/>Diaria para mí:<br/>Comunión sin sombra<br/>Con mi Dios aquí.<br/>Comunión sin sombra<br/>Con mi Dios aquí.<br/>',NULL,189952,1);
INSERT INTO stanza VALUES('S297','2','Cuando aquí sin gozo,<br/>Dame el celestial;<br/>Aun con mi_alma rota<br/>Te he de_alabar.<br/>Si lazos humanos<br/>Tú desatas hoy,<br/>Átame contigo<br/>En más dulce_amor.<br/>Átame contigo<br/>En más dulce amor.<br/>',NULL,189953,2);
INSERT INTO stanza VALUES('S297','3','Por camino aislado,<br/>¡Acompáñame!<br/>Y con Tu sonrisa<br/>Siempre_alégrame.<br/>Viva yo sin ego,<br/>Por Tu gracia_en mí,<br/>Hazme un canal limpio<br/>De Tu vida_aquí.<br/>Hazme un canal limpio<br/>De Tu vida aquí.<br/>',NULL,189954,3);
INSERT INTO stanza VALUES('S297','note','**Tomado de la Biografía y poemas de<br/>Margaret E. Barber, traducidos al español.**<br/>',NULL,189955,4);
INSERT INTO stanza VALUES('S298','1','Guíame, Señor, al monte,<br/>Do se ve sólo_a Jesús,<br/>Donde_está la voz del cielo,<br/>Aire puro_y clara luz.<br/>',NULL,189956,1);
INSERT INTO stanza VALUES('S298','chorus','Llévame_a subir el monte,<br/>Dame comunión, Señor;<br/>En Tu luz veo la fuente;<br/>Por Tu sangre, limpio soy.<br/>',NULL,189957,2);
INSERT INTO stanza VALUES('S298','2','Al subir, la luz aumenta;<br/>No hay lucha terrenal;<br/>Todo_esfuerzo_humano cesa;<br/>Y en vida reino ya.<br/>',NULL,189958,3);
INSERT INTO stanza VALUES('S298','3','Oh, manténme_en ese monte,<br/>Prosiguiendo_en comunión;<br/>Que Tu_amor y Tu imagen<br/>En mí_encuentren su_expresión.<br/>',NULL,189959,4);
INSERT INTO stanza VALUES('S299','1','Concédeme, Padre un espíritu hoy<br/>De sabiduría y revelación,<br/>Para que conozca en pleno_al Señor<br/>Al ser alumbrado en mi corazón.<br/>',NULL,189960,1);
INSERT INTO stanza VALUES('S299','2','Enséñame al Cristo que vive en mi ser,<br/>¡Oh, qué esperanza de gloria es Él!<br/>Él todo en todo será_en mi interior:<br/>Riquezas de gloria, y_herencia de Dios.<br/>',NULL,189961,2);
INSERT INTO stanza VALUES('S299','3','Oh Padre, permíteme que pueda ver<br/>Toda la grandeza de este poder<br/>Que resucitó a Jesús el Señor,<br/>Y_así por Cabeza al Cuerpo lo dio.<br/>',NULL,189962,3);
INSERT INTO stanza VALUES('S299','4','Todo_este poder has forjado, oh Dios,<br/>En Cristo, Tu Hijo, que vive_en mí hoy;<br/>Permite que vea que tal gran poder<br/>Es una Persona que mora_en mi ser.<br/>',NULL,189963,4);
INSERT INTO stanza VALUES('S299','5','Cristo_es mi esperanza, mi gloria,_y poder,<br/>Como mi Persona yo lo tomaré;<br/>Entonces en mí Su poder actuará<br/>Y mi esperanza de gloria Él será.<br/>',NULL,189964,5);
INSERT INTO stanza VALUES('S300','1','Oh, Pan de peregrinos,<br/>Oh, Celestial Maná;<br/>Para los re-nacidos:<br/>Comida divinal.<br/>Comemos Tus riquezas;<br/>Nos llenas en verdad;<br/>El mundo ya no_atrae;<br/>Tu ser nos saciará.<br/>',NULL,189965,1);
INSERT INTO stanza VALUES('S300','2','Oh, Agua, que trae vida<br/>Del corazón de Dios;<br/>Señor, eres la fuente<br/>Que fluye con amor.<br/>Probamos libremente,<br/>Saciando nuestra sed,<br/>De Tu dulzura_eterna<br/>Que fresca siempre es.<br/>',NULL,189966,2);
INSERT INTO stanza VALUES('S300','3','Gozamos tal banquete<br/>Sin verte_aquí, Señor,<br/>Creyendo_en Tu Palabra<br/>Sin dudas ni temor.<br/>Oh, que aquí vivamos<br/>En Ti, Amado fiel,<br/>Hasta quitarse_el velo<br/>Y_al fin Tu rostro ver.<br/>',NULL,189967,3);
INSERT INTO stanza VALUES('S301','1','Oh, Salvador, llena mi visión,<br/>Que vea sólo a Jesús hoy;<br/>Y_aunque por valles me guíes Tú,<br/>Me_alumbres con Tu gloria_y Tu luz.<br/>',NULL,189968,1);
INSERT INTO stanza VALUES('S301','chorus','Oh Salvador, llena mi visión,<br/>Hasta que_irradie con Tu resplandor;<br/>Hasta que vea todo_hombre_aquí<br/>Tu santa_imagen reflejada_en mí.<br/>',NULL,189969,2);
INSERT INTO stanza VALUES('S301','2','Oh Salvador, llena mi visión;<br/>Que sólo busque darte_el honor;<br/>Oh, que me inspiren Tu perfección,<br/>Tu luz divina y Tu santo amor.<br/>',NULL,189970,3);
INSERT INTO stanza VALUES('S301','3','Oh Salvador, llena mi visión,<br/>Que nada_opaque_en mí Tu fulgor;<br/>Que vea sólo Tu_hermosa faz,<br/>Y de Tu gracia pueda disfrutar.<br/>',NULL,189971,4);
INSERT INTO stanza VALUES('S302','1','Más de Jesús quiero_aprender,<br/>Más de Su gracia conocer,<br/>Más del amor con que me_amó,<br/>Más de la cruz en que murió.<br/>',NULL,189972,1);
INSERT INTO stanza VALUES('S302','chorus','Más quiero amarlo;<br/>Más quiero honrarlo;<br/>Más de Su salvación gozar,<br/>Más de Su dulce amor gustar.<br/>',NULL,189973,2);
INSERT INTO stanza VALUES('S302','2','Más de Jesús quisiera_hablar,<br/>Más discernir Su voluntad,<br/>Que por el Santo_Espíritu<br/>Conozca más de Su virtud.<br/>',NULL,189974,3);
INSERT INTO stanza VALUES('S302','3','Más de Jesús anhelo ver<br/>En Su Palabra al leer;<br/>Su voz en cada línea_oír<br/>Para Sus dichos recibir.<br/>',NULL,189975,4);
INSERT INTO stanza VALUES('S302','4','Más de Jesús, divino Rey,<br/>Y de Sus glorias comprender;<br/>Más en Su reino quiero_andar;<br/>Espero_al Príncipe de Paz.<br/>',NULL,189976,5);
INSERT INTO stanza VALUES('S303','1','Mi terca voluntad hoy cedor,<br/>Quisiera ser sólo de Ti;<br/>Por fin, Señor, a Ti te ruego:<br/>"Tu voluntad, se haga_en mí".<br/>',NULL,189977,1);
INSERT INTO stanza VALUES('S303','chorus','Oh, dulce voluntad divina,<br/>Anhelo_en Ti perdido_estar;<br/>Oh, dulce voluntad divina,<br/>Anhelo_en Ti perdido_estar.<br/>',NULL,189978,2);
INSERT INTO stanza VALUES('S303','2','Muy fatigado del pecado,<br/>La senda_oscura me cansó;<br/>Mas una luz hoy me anima,<br/>Pues hallo_en Ti mi_estrella_y sol.<br/>',NULL,189979,3);
INSERT INTO stanza VALUES('S303','3','Tu voluntad me_ha conquistado,<br/>Me_envuelve_a mí, oh Salvador;<br/>Disfruto paz, ya no hay discordia,<br/>Y mi_alma libre vuela hoy.<br/>',NULL,189980,4);
INSERT INTO stanza VALUES('S303','4','Señor, contigo encerrado,<br/>Mis pies no más han de vagar;<br/>¿Habrá_un poder que nos aparte?<br/>Tu voluntad es mi hogar.<br/>',NULL,189981,5);
INSERT INTO stanza VALUES('S304','1','Tuyo soy, Jesús; escuché Tu voy<br/>Que me_hablaba de Tu_amor.<br/>Mas por fe anhelo_acercarme hoy,<br/>Aún más cerca_a Ti, Señor.<br/>',NULL,189982,1);
INSERT INTO stanza VALUES('S304','chorus','Aún más cerca, cerca de Tu cruz,<br/>Do sangraste, mi Señor;<br/>Aún más cerca, cerca, cerca_a Ti, Jesús,<br/>Llévame, mi Salvador.<br/>',NULL,189983,2);
INSERT INTO stanza VALUES('S304','2','Hoy conságrame para_así servir<br/>Por Tu gracia divinal;<br/>A mi alma firme_esperanza da;<br/>Pierda_en Ti mi voluntad.<br/>',NULL,189984,3);
INSERT INTO stanza VALUES('S304','3','¡Oh, qué gran placer, una hora_estar<br/>Frente_al trono_en oración,<br/>Cuando me_arrodillo_ante Ti, mi Dios,<br/>Es tan dulce comunión!<br/>',NULL,189985,4);
INSERT INTO stanza VALUES('S304','4','Quiero conocer más profundo_amor<br/>Antes de mirar Tu faz;<br/>Quiero más y más gozo celestial<br/>Antes de_entrar en Tu paz.<br/>',NULL,189986,5);
INSERT INTO stanza VALUES('S305','1','¡Oh, que_en Tu presencia yo viva, Señor!<br/>Del alba_al ocaso mi mundo_eres Tú;<br/>No dejes contento a mi corazón<br/>Cuando busque algo que no seas Tú.<br/>A diario en todo sufrir y pesar,<br/>Si nada_en el mundo consuelo me da,<br/>Estando gimiendo con llanto y dolor,<br/>Señor, calma_el llanto, alivia_el pesar.<br/>',NULL,189987,1);
INSERT INTO stanza VALUES('S305','2','En cuanto yo piense en mi bienestar,<br/>Te pido que_en él estés Tú, oh Señor;<br/>No dejes que escoja yo solo sin Ti,<br/>Ni busque placeres fuera de Ti yo.<br/>Si solo_acostado_en silencio yo_estoy,<br/>Te ruego, Señor, que te_acerques a mí;<br/>Y antes del alba, durmiendo aún<br/>Susurra_en mi oído, llamándome_así.<br/>',NULL,189988,2);
INSERT INTO stanza VALUES('S305','3','En cuanto yo abra Tu libro, Señor,<br/>Que Tu gloria en cada línea pueda ver,<br/>Que vea en claro a mi Salvador,<br/>Y qué salvación me has hecho obtener.<br/>Si débil me acercó a Tu trono, Señor,<br/>Me oigas te pido y Tu gracia me des;<br/>Si por mis defectos no escuchas mi orar,<br/>No escondas Tu rostro, ni alejes Tu ser.<br/>',NULL,189989,3);
INSERT INTO stanza VALUES('S305','4','En cuanto medite en Tu bendición,<br/>Que anhele muy pronto contigo estar;<br/>Que espere orando que vuelvas, Señor,<br/>Pues en Tu presencia mi gozo será.<br/>Enséñame a diario contigo a vivir,<br/>Del alba al ocaso andar en Tu luz;<br/>No dejes contento a mi corazón<br/>Cuando busque algo que no seas Tú.<br/>',NULL,189990,4);
INSERT INTO stanza VALUES('S306','1','Guíame, oh Salvador,<br/>En Espíritu_hacia Ti;<br/>Si‿ando‿en luz de vida yo<br/>Cesaré de resistir.<br/>',NULL,189991,1);
INSERT INTO stanza VALUES('S306','chorus','Guía, guía,<br/>Guíame, oh Salvador,<br/>A lo hondo del fluir<br/>De Tu vida, mi Señor.<br/>',NULL,189992,2);
INSERT INTO stanza VALUES('S306','2','Por la ley de vida en mí<br/>Tú me guías en verdad;<br/>Cuando reinas con poder,<br/>Se hace luz mi oscuridad.<br/>',NULL,189993,3);
INSERT INTO stanza VALUES('S306','3','Me libró Tu Espíritu<br/>Para regularme más,<br/>Y mi mente y voluntad<br/>Tú por Él, renovarás.<br/>',NULL,189994,4);
INSERT INTO stanza VALUES('S307','1','Tu senda_es mi_elección,<br/>Aunque_haya_oscuridad;<br/>Escoge Tú, Señor,<br/>La ruta que_he de_andar.<br/>',NULL,189995,1);
INSERT INTO stanza VALUES('S307','2','Si ardua_o suave es,<br/>No me_ha de importar;<br/>Si dura_o fácil es,<br/>Me lleva_a reposar.<br/>',NULL,189996,2);
INSERT INTO stanza VALUES('S307','3','Yo no me_atreveré<br/>Mi parte escoger;<br/>Escoge Tu por mí,<br/>Y recto andaré.<br/>',NULL,189997,3);
INSERT INTO stanza VALUES('S307','4','Llena mi copa, Tú,<br/>Con gozo o dolor,<br/>Con penas o con bien;<br/>Tú sabes qué_es mejor.<br/>',NULL,189998,4);
INSERT INTO stanza VALUES('S307','5','Escoge Tú por mí,<br/>Salud o_enfermedad,<br/>Pobreza_o bienestar,<br/>Amigo_o soledad.<br/>',NULL,189999,5);
INSERT INTO stanza VALUES('S307','6','No_es mía la_elección,<br/>En toda situación;<br/>Sé mi guía_y poder,<br/>Mi todo, Tú, Señor.<br/>',NULL,190000,6);
INSERT INTO stanza VALUES('S308','1','A aquél que algo tiene<br/>Más le das hasta_abundar.<br/>Señor, vivo porque vives;<br/>De Tu vida dame más.<br/>Que‿en Tu gracia crezca yo,<br/>Y que corra con fervor.<br/>Que‿en Tu gracia crezca yo,<br/>Y que corra con fervor.<br/>',NULL,190001,1);
INSERT INTO stanza VALUES('S308','2','Profundiza_en mí Tu obra,<br/>Fortalece la raíz;<br/>Haz que pronto‿así madure<br/>Rico frutos para Ti.<br/>//Poda‿y corta Tú mi yo,<br/>Que por gracia crezca hoy.//<br/>',NULL,190002,2);
INSERT INTO stanza VALUES('S308','3','Crezca yo por sol y lluvia,<br/>Cada hora riégame;<br/>Y que‿a Ti cada momento<br/>Más moldeado llegue‿a ser.<br/>//Con Tu ojo mídeme,<br/>En Tu gracia‿he de crecer.//<br/>',NULL,190003,3);
INSERT INTO stanza VALUES('S308','4','Por Tu gracia que me llena<br/>Grandes cosas muéstrame;<br/>Como águila‿en Tus alas,<br/>Hasta lo‿alto llévame.<br/>//Haz Tu faz resplandecer<br/>Para‿en gracia‿así crecer.//<br/>',NULL,190004,4);
INSERT INTO stanza VALUES('S308','5','Quiero yo seguir creciendo<br/>Y nunca‿estancado‿estar,<br/>Escuchando‿y conociendo<br/>Más de Ti‿y Tu voluntad.<br/>//Hasta‿el premio alcanzar,<br/>Crezca‿en gracia más y más.//<br/>',NULL,190005,5);
INSERT INTO stanza VALUES('S309','1','Oh, Jesucristo, crece en mí,<br/>Y mengüe lo demás;<br/>Mi corazón se_acerque-a Ti,<br/>Se libre del pecar.<br/>',NULL,190006,1);
INSERT INTO stanza VALUES('S309','chorus','Que Tu poder sostenedor<br/>Me_ampare, mi Jesús;<br/>Cambia mi muerte_en vida hoy,<br/>Mi noche por Tu  luz.<br/>',NULL,190007,2);
INSERT INTO stanza VALUES('S309','2','Que bajó el rayo de Tu luz<br/>Se_eclipse_el mal pensar;<br/>Que Tú_eres todo y nada soy,<br/>Yo debo aceptar.<br/>',NULL,190008,3);
INSERT INTO stanza VALUES('S309','3','Más de Tu gloria_anhelo ver,<br/>Oh Santo, Sabio_y Fiel;<br/>Tu imagen viva quiero ser<br/>En pena o_en placer.<br/>',NULL,190009,4);
INSERT INTO stanza VALUES('S309','4','Me llene_el gozo celestial<br/>Con todo su poder;<br/>Que el fulgor de Tu amor<br/>Hoy brille en mi ser.<br/>',NULL,190010,5);
INSERT INTO stanza VALUES('S309','5','Haz amenguar mi pobre ser,<br/>Mi vida_y meta sé;<br/>Que por Tu gracia pueda yo<br/>Tu nombre_ennoblecer.<br/>',NULL,190011,6);
INSERT INTO stanza VALUES('S310','1','Prosigo hacia arriba hoy,<br/>A un más alto sitio voy,<br/>"Señor", orando sin cesar,<br/>"Quiero a la cumbre al fin llegar".<br/>',NULL,190012,1);
INSERT INTO stanza VALUES('S310','chorus','¡Señor, levántame! Por fe<br/>Quiero en Canaán permanecer;<br/>En lo más alto_anhelo estar,<br/>Quiero_a la cumbre_al fin llegar.<br/>',NULL,190013,2);
INSERT INTO stanza VALUES('S310','2','Mi corazón no quiere andar,<br/>Donde gobierne el afán;<br/>El mundo escoge allí morar,<br/>Mas en la cumbre anhelo estar.<br/>',NULL,190014,3);
INSERT INTO stanza VALUES('S310','3','Abajo el mundo dejaré,<br/>De Satanás me escaparé;<br/>Así por fe podré cantar:<br/>"Quiero a la cumbre al fin llegar".<br/>',NULL,190015,4);
INSERT INTO stanza VALUES('S310','4','Quiero escalar todo escalón,<br/>Captar la gloria de Sión,<br/>Mas oraré hasta llegar,<br/>Señor, la cumbre hazme ganar.<br/>',NULL,190016,5);
INSERT INTO stanza VALUES('S311','1','Más santidad dame,<br/>Más dulzura_en mí,<br/>Más odio_al pecado,<br/>Más gracia_al sufrir,<br/>Más fe_en el que salva,<br/>Más de Tu amor,<br/>Más gozo_al servirte,<br/>Más libre_oración.<br/>',NULL,190017,1);
INSERT INTO stanza VALUES('S311','chorus','Ven y dame Tu_ayuda,<br/>Tu consuelo_y Tu fuerza;<br/>Cada_instante me salvas,<br/>Tú me salvas, Señor.<br/>',NULL,190018,2);
INSERT INTO stanza VALUES('S311','2','Más gratitud dame,<br/>Más en Ti confirar,<br/>Más buscar Tu gloria,<br/>Más de Tu hablar,<br/>Más pena_en Tu_angustia<br/>Más ver Tu dolor,<br/>Ser manso_en las pruebas,<br/>Más puro, Señor.<br/>',NULL,190019,3);
INSERT INTO stanza VALUES('S311','3','Más victoria dame,<br/>Más hazme vencer,<br/>Más libre de manchas,<br/>Más Tu trono ver,<br/>Más digno del reino,<br/>Más úti aquí,<br/>Más santo, oh Cristo,<br/>Hazme_igual a Ti.<br/>',NULL,190020,4);
INSERT INTO stanza VALUES('S312','1','¡Ser como Tú! Oh, Redentor mío,<br/>Es mi_oración y firme sentir;<br/>Feliz renuncio_a todo tesoro,<br/>Ser como Cristo es mi gemir.<br/>',NULL,190021,1);
INSERT INTO stanza VALUES('S312','chorus','¡Ser como Tú! ¡Oh, ser como eres!<br/>Puro y fiel, mi buen Redentor;<br/>Ven con dulzura y_en Tu_abundancia;<br/>Tu_imagen graba_en mi corazón.<br/>',NULL,190022,2);
INSERT INTO stanza VALUES('S312','2','¡Ser como Tú! El más compasivo,<br/>Tierno, amoroso, perdonador,<br/>Cuidando al débil, alzando al triste,<br/>Buscando al pobre vil pecador.<br/>',NULL,190023,3);
INSERT INTO stanza VALUES('S312','3','¡Ser como Tú! Muy manso y valiente,<br/>Crueles reproches pueda aguantar;<br/>Pobre en espíritu, padeciendo,<br/>Para que a otros pueda salvar.<br/>',NULL,190024,4);
INSERT INTO stanza VALUES('S312','4','¡Ser como Tú! Por eso yo vengo<br/>A recibir la santa unción;<br/>Lo que yo soy ahora te traigo;<br/>Lo que yo tengo_es Tuyo, Señor.<br/>',NULL,190025,5);
INSERT INTO stanza VALUES('S312','5','¡Ser como Tú! Y mientras te imploro,<br/>Manda Tu Espíritu con amor.<br/>Hazme un templo, digna morada,<br/>Para que gane Tu aprobación.<br/>',NULL,190026,6);
INSERT INTO stanza VALUES('S313','1','¡Expresar Su imagen,<br/>Esto_anhelo yo!<br/>Que el Señor lo cumpla,<br/>Es mi_aspiración.<br/>',NULL,190027,1);
INSERT INTO stanza VALUES('S313','2','¡Expresar Su imagen!<br/>El, Espíritu es!<br/>Y si me gobierna,<br/>Cambiará mi ser.<br/>',NULL,190028,2);
INSERT INTO stanza VALUES('S313','3','Como_en un espejo<br/>Le contemplo hoy;<br/>Puedo ver Su gloria,<br/>Reflejar Su amor.<br/>',NULL,190029,3);
INSERT INTO stanza VALUES('S313','4','¡Oh, que nada oculte<br/>Su querida faz!<br/>Que mi alma pueda<br/>Reflejarlo más.<br/>',NULL,190030,4);
INSERT INTO stanza VALUES('S313','5','Al mirar Su gloria<br/>Cara a cara aquí,<br/>Y al contemplarlo,<br/>Le reflejó así.<br/>',NULL,190031,5);
INSERT INTO stanza VALUES('S313','6','¡Expresar Su imagen!<br/>Mi objetivo es:<br/>Reflejarlo en mi alma,<br/>Y expresarlo a El.<br/>',NULL,190032,6);
INSERT INTO stanza VALUES('S313','7','¡Expresar Su imagen!<br/>Reflejarlo más;<br/>Ir de gloria en gloria<br/>Por siempre jamás.<br/>',NULL,190033,7);
INSERT INTO stanza VALUES('S314','1','Vive_en mí, Señor, Tu vida,<br/>Pues mi vida eres hoy;<br/>Al tomarle_en mis problemas<br/>Eres Tu la solución.<br/>Vive_en mí, Señor, Tu vida,<br/>Cumple_en mí Tu voluntad;<br/>Hazme_un vaso transparente<br/>Para_al Hijo expresar.<br/>',NULL,190034,1);
INSERT INTO stanza VALUES('S314','2','Consagrado está Tu templo,<br/>Ya purgado de maldad;<br/>Que la llama de Tu gloria<br/>Brille en mí con claridad.<br/>Que con admirable asombro<br/>Pueda el mundo contemplar,<br/>La ofrenda de mi cuerpo,<br/>Que este esclavo a Ti te da.<br/>',NULL,190035,2);
INSERT INTO stanza VALUES('S314','3','Todo el tiempo, todo miembro,<br/>Quede atentó a Tu mandar,<br/>Para trabajar en yugo<br/>O esperar según Tu plan.<br/>Cuando sea restringido<br/>No me intranquilizaré;<br/>En Tu trato fiel conmigo<br/>Nunca yo murmuraré.<br/>',NULL,190036,3);
INSERT INTO stanza VALUES('S314','4','Tierno, quieto y en reposo,<br/>Mis tendencias ya negué,<br/>Para que te sientas libre<br/>Y me indiques Tu querer.<br/>Vive_en mí, Señor, Tu vida,<br/>Pues mi vida eres hoy;<br/>Al tomarle_en mis problemas<br/>Eres Tu la solución.<br/>',NULL,190037,4);
INSERT INTO stanza VALUES('S315','1','Ya que he visto la hermosura<br/>De_este mundo tentador,<br/>Yo prefiero Tu presencia,<br/>Aunque ciego_esté, Señor.<br/>',NULL,190038,1);
INSERT INTO stanza VALUES('S315','chorus','Ya que_he visto la_hermosura<br/>De_este mundo tentador,<br/>Yo prefiero Tu presencia,<br/>Aunque ciego_esté, Señor.<br/>',NULL,190039,2);
INSERT INTO stanza VALUES('S315','2','Aunque en el paraíso<br/>Pueda ver la luz del sol,<br/>Mas aquí a mi ceguera<br/>Su piedad es mi farol.<br/>',NULL,190040,3);
INSERT INTO stanza VALUES('S315','3','Ya no quiero liberarme<br/>De mi diario aguijón;<br/>Tras el velo hallo gracia<br/>En el rostro del Señor.<br/>',NULL,190041,4);
INSERT INTO stanza VALUES('S315','4','En mi noche Su hermosura<br/>Sólo puedo ver por fe,<br/>Al mirar la faz gloriosa<br/>Que por mí sufrió desdén.<br/>',NULL,190042,5);
INSERT INTO stanza VALUES('S315','5','Con Su corona de espinas<br/>Que llevó en mi lugar,<br/>El opaca toda gloria<br/>O galaxia celestial.<br/>',NULL,190043,6);
INSERT INTO stanza VALUES('S315','note','**Este himno fue escrito poco después de que su autor, quien habia nacido ciego, recibió la vista.**<br/>',NULL,190044,7);
INSERT INTO stanza VALUES('S316','1','Tu senda, oh Señor,<br/>¡Házmela ver!<br/>Tu gracia_aporta hoy,<br/>¡Oh, hazme ver!<br/>Dame luz celestial,<br/>No por mi vista_andar,<br/>Mas por fe caminar,<br/>¡Házmela ver!<br/>',NULL,190045,1);
INSERT INTO stanza VALUES('S316','2','En dudas y temor,<br/>¡Házmela ver!<br/>Si_hay nubes y turbión,<br/>¡Oh, hazme ver!<br/>Brilla_en mi cielo gris,<br/>Cuando_esté triste_aquí;<br/>Tu senda_haz clara_a mí,<br/>¡Házmela ver!<br/>',NULL,190046,2);
INSERT INTO stanza VALUES('S316','3','Mientras viva, Señor,<br/>¡Házmela ver!<br/>Cualquiera mi porción,<br/>¡Oh, hazme ver!<br/>Hasta_el premio ganar<br/>En mi peregrinar,<br/>Y Tu senda_acabar.<br/>¡Házmela ver!<br/>',NULL,190047,3);
INSERT INTO stanza VALUES('S317','1','Jesús, mi Señor, sana mi corazón;<br/>Habita_en mi alma por siempre, Señor;<br/>Los ídolos echa, rivales también;<br/>Ven, lávame_y blanco cual nieve seré.<br/>',NULL,190048,1);
INSERT INTO stanza VALUES('S317','chorus','Más blanco que la nieve seré,<br/>Ven, lávame_y blanco cual nieve seré.<br/>',NULL,190049,2);
INSERT INTO stanza VALUES('S317','2','Jesús, mi Señor, borra toda maldad,<br/>Que quite mis manchas Tu sangre_eficaz;<br/>Deseo Tu bendita limpieza obtener.<br/>Ven, lávame_y blanco cual nieve seré.<br/>',NULL,190050,3);
INSERT INTO stanza VALUES('S317','3','Jesús, mi Señor, entronado estás;<br/>Ayúdame_a todo hoy sacrificar;<br/>Te_entrego mi ser y todo lo que sé;<br/>Ven, lávame_y blanco cual nieve seré.<br/>',NULL,190051,4);
INSERT INTO stanza VALUES('S317','4','Jesús, mi Señor, oye mi oración<br/>Mientras a Tus pies yo postrado estoy;<br/>Yo veo que Tu sangre me limpia por fe;<br/>Ven, lávame_y blanco cual nieve seré.<br/>',NULL,190052,5);
INSERT INTO stanza VALUES('S317','5','Jesús, mi Señor, yo espero en Ti;<br/>Ven, crea en mí un nuevo corazón;<br/>A los que te buscan, Tú recibes fiel;<br/>Ven, lávame_y blanco cual nieve seré.<br/>',NULL,190053,6);
INSERT INTO stanza VALUES('S318','1','¡Oh, revélate, Señor!<br/>Y mi carne hazme ver;<br/>Que Tu gracia obre_en mí,<br/>Hasta reducido ser.<br/>¡Cuánto quiero yo vencer!<br/>Mas en mi debilidad,<br/>Yo no logro hacer el bien,<br/>Ni tampoco venzo‿el mal.<br/>',NULL,190054,1);
INSERT INTO stanza VALUES('S318','2','Busco‿a Dios en mi‿interior,<br/>Mas mi porte es atroz;<br/>Aunque trato de cambiar,<br/>Como esclavo vivo yo.<br/>La ley del pecado en mí,<br/>Me mantiene en sujeción;<br/>Aunque libre anhelo ser<br/>Mi alma sigue en opresión.<br/>',NULL,190055,2);
INSERT INTO stanza VALUES('S318','3','Altibajos tengo yo,<br/>Caigo y me levanto bien;<br/>Hago una resolución,<br/>Mas aún vuelvo a caer.<br/>En verdad pecado soy,<br/>Por completo y sin poder;<br/>En mi carne hay maldad,<br/>Nada bueno deja ver.<br/>',NULL,190056,3);
INSERT INTO stanza VALUES('S318','4','Me conozco‿en parte hoy,<br/>Veo mi debilidad;<br/>Mi vivir corrupto‿está,<br/>Rara_es mi mentalidad.<br/>Falso es mi yo sutil,<br/>Odio mi fuerza carnal;<br/>Mi esperanza Cristo es,<br/>Sólo‿en Él puedo confiar.<br/>',NULL,190057,4);
INSERT INTO stanza VALUES('S318','5','Quiero‿en Cristo hoy vivir<br/>Manteniéndome‿en la cruz,<br/>Para poderlo‿aplicar,<br/>Por Su Santo‿Espíritu.<br/>Que Su muerte_opere‿en mí<br/>Más profundo cada vez,<br/>Hasta destruir el yo,<br/>Y Su vida dar a ver.<br/>',NULL,190058,5);
INSERT INTO stanza VALUES('S318','6','¡Oh, qué caso‿amargo soy!<br/>Miserable_y pecador.<br/>¿Quién a mí me librará<br/>Para hacerme un vencedor?<br/>Mi Jesús por mi sangró,<br/>Cristo es mi santidad;<br/>Él ahora es mi porción<br/>Y mi vida eternal.<br/>',NULL,190059,6);
INSERT INTO stanza VALUES('S318','7','Ya santificado estoy,<br/>Te obedezco, sin mi yo;<br/>No me he de_avergonzar<br/>Cuando_acuda_a mi Señor.<br/>¡Esta vida trascendió!<br/>Por fe gracia recibí;<br/>Hoy te_alabo, mi Señor,<br/>Libre Tú me_hiciste_al fin.<br/>',NULL,190060,7);
INSERT INTO stanza VALUES('S319','1','Tu dulce simplicidad<br/>Hoy imparte_en mi, Jesús;<br/>Que te busque sólo_a Ti;<br/>Pobre_y manso, hazme Tú.<br/>',NULL,190061,1);
INSERT INTO stanza VALUES('S319','2','Sálvame de señorear;<br/>Sálvame de desdeñar;<br/>De_avaricia, sálvame,<br/>Y de_elogios codiciar.<br/>',NULL,190062,2);
INSERT INTO stanza VALUES('S319','3','Lo que nutre mi_altivez<br/>Échalo afuera ya;<br/>Humillado a Tus pies,<br/>Rindo_a Ti mi voluntad.<br/>',NULL,190063,3);
INSERT INTO stanza VALUES('S319','4','Hazme como_un niño_aquí,<br/>Caminando_en Tu virtud,<br/>Sólo_obrando_en Tu poder,<br/>Sólo viendo en Tu luz.<br/>',NULL,190064,4);
INSERT INTO stanza VALUES('S319','5','En Tu seno de amor<br/>Puede mi_alma descansar;<br/>Por Tu sangre que fluyó,<br/>Siento_aquí la paz de Dios.<br/>',NULL,190065,5);
INSERT INTO stanza VALUES('S319','6','Quiero_así, Señor, vivir,<br/>Y hosannas siempre dar;<br/>Quiero_así tambien morir<br/>Y hosannas proclamar.<br/>',NULL,190066,6);
INSERT INTO stanza VALUES('S320','1','Hay un rival que_hay que temer;<br/>Muy escondido está;<br/>Más sutil que_el pecado vil,<br/>Y siempre_amado más.<br/>Es el poder del ego_atroz,<br/>Es el muy terco yo;<br/>Para que Cristo viva_en mí,<br/>Debe morir el yo.<br/>',NULL,190067,1);
INSERT INTO stanza VALUES('S320','2','Hoy hay gigantes como_ayer,<br/>Los hijos de Anac:<br/>Son la jactancia, presunción<br/>Y terca voluntad.<br/>Tales altivos, hoy Caleb<br/>Aún debe matar;<br/>Para poder tomar Hebrón<br/>Se deben conquistar.<br/>',NULL,190068,2);
INSERT INTO stanza VALUES('S320','3','Sálvame de mi voluntad,<br/>Quiere_el trono usurpar;<br/>Haz que se rinda_a Ti, Señor;<br/>Se_haga Tu voluntad.<br/>Sálvame de vana_opinión<br/>Y de confiar en mí;<br/>Quiero_a mis fuerzas renunciar<br/>Y recostarme_en Ti.<br/>',NULL,190069,3);
INSERT INTO stanza VALUES('S320','4','Del egoísmo sálvame,<br/>No quiero mío ser;<br/>Cual sacrificio vengo_a Ti;<br/>Que sólo_en Ti yo_esté.<br/>De vanagloria sálvame,<br/>De fama y de poder;<br/>Que rinda_a Cristo todo_honor<br/>Y gloria_al nombre fiel.<br/>',NULL,190070,4);
INSERT INTO stanza VALUES('S320','5','Mata, Señor, el yo en mí,<br/>Con Tu aliento hoy;<br/>Tu sacrificio muéstrame,<br/>Para que muera_el yo.<br/>Cuando Tu gloria descendió,<br/>Aún Moisés se_alejó;<br/>Tu gloria_así me llene hoy,<br/>Hasta que muera_el yo.<br/>',NULL,190071,5);
INSERT INTO stanza VALUES('S321','1','Oh, líbrame, mi fiel Señor,<br/>De_orar por no sufrir dolor,<br/>Del miedo_en vez de aspirar,<br/>De dudas en vez de_escalar;<br/>Libérame del blando yo,<br/>Hazme_un soldado, oh Señor.<br/>',NULL,190072,1);
INSERT INTO stanza VALUES('S321','2','De_amor por cosas, líbrame,<br/>De lo que débil me_hace ser,<br/>(Ese camino no tomó<br/>El crucificado Señor),<br/>¡Haz que_el Calvario pueda ver!<br/>Cordero de Dios, líbrame.<br/>',NULL,190073,2);
INSERT INTO stanza VALUES('S321','3','Dame Tu amor y dirección,<br/>La fe que vence la_aflicción,<br/>Dame_esperanza firme_y fiel,<br/>Pasión que arda por doquier;<br/>Tu combustible, hazme hoy,<br/>Que ardas Tú, Fuego de Dios.<br/>',NULL,190074,3);
INSERT INTO stanza VALUES('S322','1','Tú, insondable_amor de Dios,<br/>Excedes toda comprensión;<br/>Cuando_a lo lejos veo Tu luz,<br/>Por Tu reposo gimo hoy;<br/>Sufre dolor mi corazón<br/>Hasta que_en Ti repose yo.<br/>',NULL,190075,1);
INSERT INTO stanza VALUES('S322','2','Me_invita Tu_apacible voz,<br/>Tu dulce yugo_a conllevar;<br/>Quisiera tal, más tengo aún<br/>Pasiones que me_hacen vagar;<br/>Aunque mi meta_eres, Señor,<br/>Me_enfoco_en Ti, más lejos voy.<br/>',NULL,190076,2);
INSERT INTO stanza VALUES('S322','3','Por Tu bondad yo pude ver<br/>Que sólo_en Ti descanso hay;<br/>Si no te_encuentro_en mi buscar,<br/>Mi alma_errante no_halla paz;<br/>Oh, ¿cuándo_acabará el vagar?<br/>Solo_hacia Ti yo quiero_andar.<br/>',NULL,190077,3);
INSERT INTO stanza VALUES('S322','4','¿Acaso_hay algo bajo_el sol<br/>Que por mí sea_a Ti rival?<br/>Quítalo ya, sé mi Señor;<br/>En mi sentir debes reinar;<br/>Cuando reposo_encuentre_en Ti,<br/>Seré del mundo libre_al fin.<br/>',NULL,190078,4);
INSERT INTO stanza VALUES('S322','5','De mi mirada_esconde_el yo,<br/>No viva yo, más Cristo_en mí;<br/>Por a morir mi_afecto vil,<br/>Todo pecado haz morir;<br/>Que_en todo nada vea_aquí,<br/>Ni busque nada, sólo_a Ti.<br/>',NULL,190079,5);
INSERT INTO stanza VALUES('S322','6','Sálvame del mundano_afán<br/>Y de mi terquedad, Señor;<br/>Caza_en mi ser la rebelión,<br/>Llega_hasta_el último rincón.<br/>Hijo_obediente hazme_aquí,<br/>Que clame "Abba, Padre"_a Ti.<br/>',NULL,190080,6);
INSERT INTO stanza VALUES('S322','7','Aleja_el mundo hoy de mí<br/>Al atraer mi corazón;<br/>Habla_a mi alma_y dile así:<br/>"Yo soy tu todo, soy tu Dios".<br/>Oír Tu voz, gustar Tu_amor,<br/>Sean por siempre mi_elección.<br/>',NULL,190081,7);
INSERT INTO stanza VALUES('S323','1','Cristo, Príncipe de Paz,<br/>Toma Tú mi voluntad:<br/>Mis temores haz cesar,<br/>Da_a mi_espíritu solaz.<br/>',NULL,190082,1);
INSERT INTO stanza VALUES('S323','2','Ya Tu sangre me compró<br/>Y me dio acceso_a Dios;<br/>Pido paz genuina hoy,<br/>Esa paz que_es nuestra_unión.<br/>',NULL,190083,2);
INSERT INTO stanza VALUES('S323','3','Haz Tu voluntad, Señor,<br/>Yo la mía cedo hoy;<br/>Toda duda haz huir,<br/>Y tu paz imparte_en mí.<br/>',NULL,190084,3);
INSERT INTO stanza VALUES('S323','4','A Tus pies postrado_estoy,<br/>Sé mi vida_y todo hoy;<br/>Siempre yo te serviré,<br/>Uno contigo seré.<br/>',NULL,190085,4);
INSERT INTO stanza VALUES('S324','1','Descúbreme, Señor,<br/>Alumbra mi_interior,<br/>Que pueda discernir<br/>El ego_engañador.<br/>',NULL,190086,1);
INSERT INTO stanza VALUES('S324','chorus','Oh, que Tu luz viviente,<br/>Quite de mi mente<br/>La noche absorbente,<br/>Te pido_a Ti, Señor.<br/>',NULL,190087,2);
INSERT INTO stanza VALUES('S324','2','No me conozco bien,<br/>Me creo lo mejor,<br/>Me_engaña mi_altivez,<br/>Y vivo en presunción.<br/>',NULL,190088,3);
INSERT INTO stanza VALUES('S324','3','Yo te conozco a Ti,<br/>Aún menos, mi Señor,<br/>Y de Tu realidad<br/>Me falta más visión.<br/>',NULL,190089,4);
INSERT INTO stanza VALUES('S324','4','Tu vida en mi interior,<br/>La torno en confusión<br/>Me creo espiritual<br/>Cuando en la carne estoy.<br/>',NULL,190090,5);
INSERT INTO stanza VALUES('S324','5','En cuanto a Tu sentir,<br/>Me frustro, oh Señor,<br/>Pues tiendo a reclusión<br/>Y caigo en más error.<br/>',NULL,190091,6);
INSERT INTO stanza VALUES('S324','6','Aún Tu voluntad,<br/>No la conozco bien;<br/>Impongo mi pensar<br/>Queriendo pretender.<br/>',NULL,190092,7);
INSERT INTO stanza VALUES('S324','7','Yo necesito hoy<br/>Tu iglesia conocer,<br/>Y por revelación<br/>Tu Cuerpo comprender.<br/>',NULL,190093,8);
INSERT INTO stanza VALUES('S324','8','Sin velos, oh Señor,<br/>Anhelo claro estar,<br/>Que no me engañen más<br/>Mi orgullo y vanidad.<br/>',NULL,190094,9);
INSERT INTO stanza VALUES('S325','1','Cuando en mi hombre natural,<br/>Yo siento que muy fuerte‿estoy,<br/>No puedo  yo imaginar<br/>¡Cuán débil soy!<br/>',NULL,190095,1);
INSERT INTO stanza VALUES('S325','2','Cuando en el mundo es mi vivir,<br/>No hay sensación de error en mí,<br/>Me jacto en mis logros aquí<br/>Y sigo así.<br/>',NULL,190096,2);
INSERT INTO stanza VALUES('S325','3','Cuando en las sombras vago yo,<br/>No veo lo anímico que estoy.<br/>Sólo medito en lo que soy<br/>Jactándome.<br/>',NULL,190097,3);
INSERT INTO stanza VALUES('S325','4','Pero al final yo vengó a Ti,<br/>Y me escudriñas con Tu luz,<br/>Y veo lo que nunca vi;<br/>Mi yo tan vil.<br/>',NULL,190098,4);
INSERT INTO stanza VALUES('S325','5','Tu rayó agudo penetró,<br/>Mi fortaleza disolvió,<br/>Mi estimación al polvo fue<br/>Y me humillé.<br/>',NULL,190099,5);
INSERT INTO stanza VALUES('S325','6','Cuán ciega y tonta la altivez<br/>Que trajo a mi alma su poder,<br/>Del presumido corazón<br/>Ella emanó.<br/>',NULL,190100,6);
INSERT INTO stanza VALUES('S325','7','Gloriarme en nada puedo yo,<br/>En cada miembro cojo estoy,<br/>Por tanta pena y compunción,<br/>¿Podré orar?<br/>',NULL,190101,7);
INSERT INTO stanza VALUES('S325','8','Tu sangre del juicio libró,<br/>Y de Tu ira me salvó.<br/>Cuán pobre y sucio estoy yo<br/>En realidad.<br/>',NULL,190102,8);
INSERT INTO stanza VALUES('S325','9','Quisiera orar, no tengo fe,<br/>Sólo a Ti yo quiero ver,<br/>¿Quisieras renovar mi ser<br/>¡Oh, ten piedad!<br/>',NULL,190103,9);
INSERT INTO stanza VALUES('S326','1','Enseñanos a_orar,<br/>No como las naciones hoy;<br/>¡Permítenos cambiar!<br/>Que te_invoquemos cada día más:<br/>Crece_en nosotros, Señor.<br/>',NULL,190104,1);
INSERT INTO stanza VALUES('S326','2','Simiente viva, Tú,<br/>Sembrada_en nuestro corazón;<br/>Ya puedes comenzar<br/>A impartir tu vida más y más:<br/>Crece_en nosotros, Señor.<br/>',NULL,190105,2);
INSERT INTO stanza VALUES('S326','3','Señor, ablándanos;<br/>Conoces nuestro_origen bien.<br/>Señor, al invocar<br/>Tu nombre, toda piedra_has de quitar:<br/>Crece_en nosotros, Señor.<br/>',NULL,190106,3);
INSERT INTO stanza VALUES('S326','4','Tu luz nos hace ver<br/>Que sólo vamos a fallar.<br/>Más un mensaje hay;<br/>La simiente de vida triunfará:<br/>Crece_en nosotros, Señor.<br/>',NULL,190107,4);
INSERT INTO stanza VALUES('S326','5','En nuestro espíritu<br/>Deseamos pobres siempre ser;<br/>Tomamos el fluir<br/>De vida, que nos hace_así crecer:<br/>Crece_en nosotros, Señor.<br/>',NULL,190108,5);
INSERT INTO stanza VALUES('S326','6','Puros de corazón,<br/>Te buscaremos hasta ver<br/>Que llenes nuestro ser;<br/>Mente,_emoción y voluntad ganad:<br/>Crece_en nosotros, Señor.<br/>',NULL,190109,6);
INSERT INTO stanza VALUES('S326','7','¡Oh, haznos entender<br/>Que la simiente_ha de vencer!<br/>Tomarte_es menester;<br/>Tu crecimiento,_el reino_ha de traer:<br/>Crece_en nosotros, Señor.<br/>',NULL,190110,7);
INSERT INTO stanza VALUES('S326','8','Crece la vida,_¡amén!<br/>Tu vida, todo puede_hacer;<br/>La vida triunfará,<br/>Y todo nuestro ser renovará:<br/>Crece_en nosotros, Señor.<br/>Crece_en nosotros, Señor.<br/>',NULL,190111,8);
INSERT INTO stanza VALUES('S327','1','Oh, dale‿a mi‿espíritu fuerza,<br/>Oh, dale poder, mi Señor;<br/>Oh, dale‿a mi espíritu vida,<br/>Y‿extiéndete‿a mi corazón.<br/>',NULL,190112,1);
INSERT INTO stanza VALUES('S327','chorus','Al corazón, al corazón,<br/>Extiéndete_allí, oh Cristo,<br/>Y haz en él Tu_habitación<br/>En mi corazón, oh Cristo.<br/>',NULL,190113,2);
INSERT INTO stanza VALUES('S327','2','Extiéndete, Cristo te pido,<br/>Extiéndete‿en mi interior;<br/>Extiéndete y_abre el camino<br/>De mi_espíritu_al corazón.<br/>',NULL,190114,3);
INSERT INTO stanza VALUES('S327','3','En mi corazón haz morada,<br/>En él haz Tu‿hogar, mi Jesús,<br/>Hasta que contigo rebose<br/>Mi alma con Tu plenitud.<br/>',NULL,190115,4);
INSERT INTO stanza VALUES('S327','4','A‿Aquel que es capaz de hacerlo,<br/>Por Su eminente poder.<br/>Hará más de lo que pedimos<br/>Si abrimos a El nuestro ser.<br/>',NULL,190116,5);
INSERT INTO stanza VALUES('S328','1','Oh, santifícanos con más de Ti, Señor,<br/>Que Tu persona hoy se_extienda en lo_interior.<br/>La iglesia_así será gloriosa en realidad,<br/>¡Oh, danos más de Ti, Señor!<br/>',NULL,190117,1);
INSERT INTO stanza VALUES('S328','chorus','¡Oh, santifícanos, Señor!<br/>Solo Tú lo puedes hacer.<br/>Que Tu Persona hoy<br/>Se_extienda en lo_interior<br/>¡Oh, santifícanos, Señor!<br/>',NULL,190118,2);
INSERT INTO stanza VALUES('S328','2','Oh, purifícanos hablando al corazón,<br/>Pues Tu viviente hablar nos lavará, Señor<br/>Por Tu palabra viva en nuestro interior,<br/>¡Oh, purifícanos, Señor!<br/>',NULL,190119,3);
INSERT INTO stanza VALUES('S328','chorus','¡Oh, purifícanos, Señor,<br/>De nuestra vida natural!<br/>Haznos, por Tu hablar,<br/>Gloriosos en verdad;<br/>¡Habla en nosotros hoy, Señor!<br/>',NULL,190120,4);
INSERT INTO stanza VALUES('S328','3','Oh, aliméntanos, Señor, susténtanos,<br/>Pues al comer de Tí se sacia el corazón,<br/>Y en nuestra vida así habrá transformación,<br/>¡Oh, aliméntanos, Señor!<br/>',NULL,190121,5);
INSERT INTO stanza VALUES('S328','chorus','¡Oh, aliméntanos, Señor!<br/>Y lávanos del viejo yo.<br/>No solo púrganos,<br/>Mas llena y sácianos;<br/>¡Oh, aliméntanos, Señor!<br/>',NULL,190122,6);
INSERT INTO stanza VALUES('S328','4','Oh, con Tu tierno amor hoy cuídanos, Señor,<br/>Al darnos de comer, ablanda el corazón.<br/>Así nos ganarás como Tu posesión.<br/>¡Oh, cuídanos, tierno Señor!<br/>',NULL,190123,7);
INSERT INTO stanza VALUES('S328','chorus','¡Oh, tiernamente, buen Señor,<br/>Abrázanos con gran fervor!<br/>Así nuestra frialdad<br/>Se desvanecerá;<br/>¡Oh, cuídanos, tierno Señor!<br/>',NULL,190124,8);
INSERT INTO stanza VALUES('S328','5','Al Tú obrar así en nuestro interior,<br/>La iglesia ha de ser gloriosa en Tí, Señor;<br/>Por fin Tú obtendrás la novia de Tu amor.<br/>¡Obra en nuestro ser, Señor!<br/>',NULL,190125,9);
INSERT INTO stanza VALUES('S328','chorus','¡Obra en nuestro ser, Señor!<br/>Gloriosa haz Tu iglesia hoy.<br/>Extiéndete, Señor,<br/>En todo nuestro ser;<br/>¡Haznos gloriosos hoy, Señor!<br/>',NULL,190126,10);
INSERT INTO stanza VALUES('S329','1','Más revelación pedimos,<br/>Luz y vista para ver<br/>Que en nuestro_espíritu_eres<br/>Vida_y realidad también.<br/>Y que desde allí te_extiendes<br/>Hasta todo_el corazón,<br/>Poseyendo cada parte,<br/>Para_hacer Tu_hogar, Señor.<br/>',NULL,190127,1);
INSERT INTO stanza VALUES('S329','2','No una_actuación externa<br/>Con conducta ejemplar,<br/>O modales refinados,<br/>Obras de un buen pensar;<br/>Sino Cristo, el Viviente,<br/>Quien, mezclado_en nuestro ser,<br/>Se expande en nosotros,<br/>Para_así vivir por Él.<br/>',NULL,190128,2);
INSERT INTO stanza VALUES('S329','3','Sí, que todos nuestros dichos,<br/>Cada hecho y acción,<br/>Nazcan de Tu misma vida<br/>En nosotros, oh Señor.<br/>Rechazamos las doctrinas,<br/>Métodos y_emulación,<br/>Para vivir por la vida<br/>Que rebosa_en lo_interior.<br/>',NULL,190129,3);
INSERT INTO stanza VALUES('S329','4','Es por el sentir interno,<br/>No por nuestra deducción,<br/>Que vivimos y andamos<br/>En la divinal unción;<br/>No por nuestras intenciones<br/>Ni_un motivo personal,<br/>Mas siguiendo al Viviente<br/>Y_el sentir que Él nos da.<br/>',NULL,190130,4);
INSERT INTO stanza VALUES('S329','5','Siendo_así santificados,<br/>Saturados en verdad,<br/>No tan sólo separados<br/>De manera doctrinal,<br/>Cristo vive en nosotros<br/>Y se_añade a nuestro ser;<br/>Nuestro corazón satura,<br/>Hasta_hacer Su_hogar en él.<br/>',NULL,190131,5);
INSERT INTO stanza VALUES('S330','1','Los ángeles pueden Su faz contemplar,<br/>Mas gracia no pueden probar;<br/>Los santos conocen Su_amor eternal,<br/>Mas nunca han visto Su faz.<br/>Los santos muy pronto Su rostro verán<br/>Su gloria también llevarán;<br/>María, en cambio, al verlo llorar,<br/>Sintió Su_angustia_y pesar,<br/>Sintió Su_angustia_y pesar.<br/>',NULL,190132,1);
INSERT INTO stanza VALUES('S330','2','Muy pronto veremos la faz del Señor,<br/>Lo conoceremos como_es;<br/>Pero_el toque tierno de Su sanidad,<br/>Ya no volverá_a nuestro ser.<br/>Aunque_en aquel día habrá gran loor,<br/>No_habrá más pesar ni_oración,<br/>Tampoco_el consuelo que quita_el dolor,<br/>//Ni fe a través de_aflicción.//<br/>',NULL,190133,2);
INSERT INTO stanza VALUES('S330','3','Aquel día, gloria nos coronará,<br/>Más no habrá cruz que llevar;<br/>La comunión dulce de Su aflicción<br/>Hoy sólo podemos probar.<br/>Después de entrar al descanso_eternal,<br/>No_habrá más oportunidad<br/>De padecer pruebas o dificultad<br/>//Por causa de Él en verdad.//<br/>',NULL,190134,3);
INSERT INTO stanza VALUES('S330','4','Oh, muy pocas veces podemos sufrir<br/>La burla y vergüenza por Él;<br/>Y pronto se va la oportunidad<br/>Que_Él nos acompañe_en desdén.<br/>Los malentendidos y penas se irán,<br/>Dolor y desprecio también;<br/>Valoro hoy las bendiciones que traen<br/>//Más comunión dulce con Él.//<br/>',NULL,190135,4);
INSERT INTO stanza VALUES('S330','5','Anhelo Tu faz pronto ver, mi Señor;<br/>¡Qué extasis, contigo_estar!<br/>Mas no quiero ninguna prueba_eludir;<br/>Tan dulces y_escasas son ya.<br/>¡Ten misericordia, que viva por Ti!<br/>¡Oh, llena mi ser de Tu_amor!<br/>No sea que en ese día, Señor<br/>//Lamente lo que se perdió.//<br/>',NULL,190136,5);
INSERT INTO stanza VALUES('S331','1','Tu fuerte_amor me constriñe, Señor,<br/>Como corriente presionando_está,<br/>Buscando_abrir en mi_alma un canal,<br/>Anhela todo_estorbo_en mí quitar.<br/>',NULL,190137,1);
INSERT INTO stanza VALUES('S331','2','¿No debo yo abrirme a tal poder?<br/>¿Y a la corriente de Tu amor ceder?<br/>Mi Dios, Tu gentileza me ganó,<br/>Mi vida ya igual no puede ser.<br/>',NULL,190138,2);
INSERT INTO stanza VALUES('S331','3','Quebrántame con Tu divino amor;<br/>Mi mente limpia y todo mi querer,<br/>Fluye y depura toda mi afección;<br/>Que sólo quede Tu vida en mí ser.<br/>',NULL,190139,3);
INSERT INTO stanza VALUES('S331','4','Así posesionado por mi Dios,<br/>Ha de fluir desde mi corazón,<br/>Un tierno arroyo en espontaneidad,<br/>Lleno de gracia y el amor de Dios.<br/>',NULL,190140,4);
INSERT INTO stanza VALUES('S331','note','**Nota: Tonada alterna. Cada verso se repite dos veces.**<br/>',NULL,190141,5);
INSERT INTO stanza VALUES('S332','1','Oh,‿Amor que no me dejará,<br/>Reposo mi‿alma hoy en Ti;<br/>Mi vida‿es Tuya, tómala,<br/>Para que‿en Tu profundidad,<br/>En Ti, pueda fluir.<br/>',NULL,190142,1);
INSERT INTO stanza VALUES('S332','2','Oh, Luz que‿alumbra mi andar,<br/>Mi‿antorcha cedo ante Ti;<br/>Mi corazón postrado‿está,<br/>Para que‿así, por Tu‿alumbrar,<br/>Su día brille más.<br/>',NULL,190143,2);
INSERT INTO stanza VALUES('S332','3','Oh, Gozo‿en medio del dolor,<br/>No me podré cerrar a Ti;<br/>Tu arco iris veo yo,<br/>Tu fiel promesa; si llovió,<br/>Yo sé que‿el sol saldrá.<br/>',NULL,190144,3);
INSERT INTO stanza VALUES('S332','4','Oh, Cruz que alza hoy mi faz,<br/>De Ti no me atrevo huir;<br/>Muere la gloria terrenal,<br/>Mas de la tierra brotará<br/>Tu vida eternal.<br/>',NULL,190145,4);
INSERT INTO stanza VALUES('S332','note','**Nota: Tonada alterna. El autor fue inspirado a escribir este himno en 5 minutos durante un momento de angustia.**<br/>',NULL,190146,5);
INSERT INTO stanza VALUES('S333','1','¡Soy del Señor! ¡Oh qué inefable gozo!<br/>Es la respuesta a Su eterno amor;<br/>Gozosa fe le da el "sí" oyendo:<br/>"No temas redimido, tuyo soy".<br/>',NULL,190147,1);
INSERT INTO stanza VALUES('S333','2','¡Soy del Señor! ¡Qué confesión tan dulce!<br/>La cual recuerda el día tan feliz<br/>Cuando la Novia respondió, "Sí, quiero<br/>Obedecerte, amarte y ser de Ti".<br/>',NULL,190148,2);
INSERT INTO stanza VALUES('S333','3','¡Soy del Señor! Mas tienes que enseñarme<br/>Lo que envuelve amor y lealtad,<br/>Santo servicio, absoluta entrega,<br/>Y sin reservas que te pueda honrar.<br/>',NULL,190149,3);
INSERT INTO stanza VALUES('S333','4','¡Soy del Señor! Mi espíritu alma y cuerpo,<br/>Lleven Tu sello, pues son para Ti;<br/>Tal como Tú, mi Amado en Tu gracia,<br/>Eres eternamente para mí.<br/>',NULL,190150,4);
INSERT INTO stanza VALUES('S334','1','Señor, ganaste Tú por fin;<br/>Tu gracia me obliga_así<br/>A darte_el corazón.<br/>Podría resistir terror,<br/>Mas no Tu infinito_amor;<br/>Tu_amor me conquistó.<br/>',NULL,190151,1);
INSERT INTO stanza VALUES('S334','2','Mi terquedad se derritió.<br/>No por Tus rayos y_el temor,<br/>Mas por Tu gran merced.<br/>Me subyugó Tu_inmenso_amor,<br/>Vi al sangrante Salvador;<br/>Hoy odio mi vil ser.<br/>',NULL,190152,2);
INSERT INTO stanza VALUES('S334','3','Ven, hazme ya Tu posesión;<br/>Soy sólo Tuyo, mi Señor;<br/>Me liberaste Tú,<br/>Me desataste de Satán,<br/>Y mis poderes ahora están<br/>A Tus pies, mi Jesús.<br/>',NULL,190153,3);
INSERT INTO stanza VALUES('S335','1','Oh, qué pena_amarga y triste,<br/>Que hubiése_un tiempo_en mí<br/>Cuando_al Salvador rehuía<br/>Y_en mi_orgullo respondía;<br/>"Todo del yo, y nada de Ti".<br/>"Todo del yo, y nada de Ti".<br/>',NULL,190154,1);
INSERT INTO stanza VALUES('S335','2','Él me_halló y pude verlo<br/>En la cruz sangrando_allí;<br/>Al oir: "Perdónalos, Padre",<br/>Compungida, mi_alma dijo:<br/>//"Algo del yo, y algo de Ti".//<br/>',NULL,190155,2);
INSERT INTO stanza VALUES('S335','3','Día_a día Su ternura,<br/>Comprensión y Su favor<br/>Me_humillaban con dulzura,<br/>Mientras que yo susurraba:<br/>//"Menos del yo, y aún más de Ti"//<br/>',NULL,190156,3);
INSERT INTO stanza VALUES('S335','4','Es más alto que los cielos,<br/>Hondo como_el mar sin fin;<br/>Tu amor me_ha conquistado,<br/>Oh, Jesús, hoy te suplico:<br/>//Nada del yo, y todo de Ti.//<br/>',NULL,190157,4);
INSERT INTO stanza VALUES('S336','1','Tu vida, oh, Jesús!<br/>Rendiste_a mi favor;<br/>Sangrando_en una cruz,<br/>Para que viva yo.<br/>//Tu vida diste por mí, por mí;<br/>Y yo, ¿qué he dado por Ti?//<br/>',NULL,190158,1);
INSERT INTO stanza VALUES('S336','2','Por mi sufriste Tú,<br/>Años de adversidad,<br/>Para mostrarme_así<br/>Tu gloria eternal.<br/>//Gastaste años por mí, por mí,<br/>¿Cuántos yo he dado por Ti?//<br/>',NULL,190159,2);
INSERT INTO stanza VALUES('S336','3','Tu trono celestial,<br/>Dejaste Tú por mí,<br/>Del Padre, Tu hogar,<br/>Viniste a sufrir.<br/>//Dejaste todo por mí, por mí,<br/>¿Qué he dejado por Ti?//<br/>',NULL,190160,3);
INSERT INTO stanza VALUES('S336','4','Sufriste Tú por mí<br/>La pena y el dolor;<br/>Salvando mi alma‿así<br/>De aquel infierno atroz.<br/>//Sufriste tanto por mí, por mí,<br/>¿Cuánto he sufrido por Ti?//<br/>',NULL,190161,4);
INSERT INTO stanza VALUES('S336','5','De Tu celeste hogar<br/>Trajiste el rico don<br/>De Tu infinito amor:<br/>Gratuita salvación.<br/>//Trajiste tanto por mí, por mí,<br/>¿Cuánto he traído a Ti?//<br/>',NULL,190162,5);
INSERT INTO stanza VALUES('S336','6','Señor, me entrego a Ti,<br/>Mi vida y años doy;<br/>Renuncio al mundo aquí,<br/>Y me consagro hoy.<br/>//Tú todo diste por mí, por mí,<br/>Yo todo entrego a Ti.//<br/>',NULL,190163,6);
INSERT INTO stanza VALUES('S337','1','¿No le has visto y conocido?<br/>¿Te prendió el corazón?<br/>Entre diez mil, señalado,<br/>Hazlo hoy Tu elección.<br/>',NULL,190164,1);
INSERT INTO stanza VALUES('S337','chorus','Cautivado en Su belleza,<br/>Constreñido por Su amor,<br/>Coronando el Rey de gloria<br/>Ríndele tu corazón.<br/>',NULL,190165,2);
INSERT INTO stanza VALUES('S337','2','Idolos te cautivaron,<br/>Bellos a la percepción,<br/>Disfrazado_está el pecado,<br/>Para_hurtar tu corazón.<br/>',NULL,190166,3);
INSERT INTO stanza VALUES('S337','3','¿Qué desvaneció el encanto<br/>Que esos ídolos formó?<br/>No el sentido de lo justo<br/>Sino el ver Su gran valor.<br/>',NULL,190167,4);
INSERT INTO stanza VALUES('S337','4','No los ídolos quebrados<br/>Con vacío y dolor,<br/>Sino el brillo de Su gloria<br/>Y el mirar Su corazón.<br/>',NULL,190168,5);
INSERT INTO stanza VALUES('S337','5','¿Quién desechará la vela<br/>Antes de que salga el sol?<br/>¿O sus ropas de invierno<br/>Antes que llegue el calor?<br/>',NULL,190169,6);
INSERT INTO stanza VALUES('S337','6','Lo que derritió a Pedro,<br/>O la faz que Esteban vio,<br/>Esto, sí, puede tornarte<br/>De los ídolos a Dios.<br/>',NULL,190170,7);
INSERT INTO stanza VALUES('S337','7','¡Oh, atráeme por completo!<br/>Haz mi copa rebosar,<br/>Sólo en comunión contigo,<br/>No con ídolos andar.<br/>',NULL,190171,8);
INSERT INTO stanza VALUES('S338','1','Al mundo yo la_espalda di,<br/>Con todos sus placeres;<br/>Y puse ya mi corazón<br/>En los tesoros santos;<br/>No más su brillo_y resplandor,<br/>Y vanidad me ciegan;<br/>Yo ya crucé la división,<br/>Dejé el mundo lejos.<br/>',NULL,190172,1);
INSERT INTO stanza VALUES('S338','chorus','¡Lejos, muy lejos!<br/>¡Lejos, muy lejos!<br/>Yo ya crucé la división,<br/>¡Dejé el mundo lejos.<br/>',NULL,190173,2);
INSERT INTO stanza VALUES('S338','2','La vida vieja ya dejé,<br/>Con todas sus locuras;<br/>En Cristo mi lugar está,<br/>Sus votos he tomado.<br/>Bajo la norma de la cruz<br/>Me hallará el mundo;<br/>De muerte a vida ya pasé,<br/>Dejé el mundo lejos.<br/>',NULL,190174,3);
INSERT INTO stanza VALUES('S338','chorus','¡Lejos, muy lejos!<br/>Lejos, muy lejos!<br/>De muerte a vida ya pasé,<br/>¡Dejé el mundo lejos!<br/>',NULL,190175,4);
INSERT INTO stanza VALUES('S338','3','Mi alma no regresará<br/>A su anterior estado.<br/>Pues tengo aquí perfecta paz,<br/>Ya encontré descanso.<br/>He hecho cambio de señor,<br/>Sus votos hoy me atan;<br/>De una vez ya lo dejé,<br/>Dejé el mundo lejos.<br/>',NULL,190176,5);
INSERT INTO stanza VALUES('S338','chorus','¡Lejos, muy lejos!<br/>¡Lejos, muy lejos!<br/>De una vez ya lo dejé,<br/>¡Dejé el mundo lejos!<br/>',NULL,190177,6);
INSERT INTO stanza VALUES('S338','4','Mi elección ya hecha está,<br/>No hay otro Salvador.<br/>No pido más felicidad,<br/>Que Su favor y amor.<br/>Jesús mi meta ahora es,<br/>El mundo no me ciega,<br/>Por el Mar Rojo ya crucé,<br/>Dejé el mundo lejos.<br/>',NULL,190178,7);
INSERT INTO stanza VALUES('S338','chorus','¡Lejos, muy lejos!<br/>¡Lejos, muy lejos!<br/>Por el Mar Rojo ya crucé,<br/>¡Dejé el mundo lejos!<br/>',NULL,190179,8);
INSERT INTO stanza VALUES('S339','1','¡Quiero abandonarme<br/>Al Espíritu!<br/>Busco_a cualquier precio<br/>Hoy Su plenitud.<br/>Las profundidades<br/>Quiero alcanzar,<br/>Del poder que salva<br/>Y me guarda ya.<br/>',NULL,190180,1);
INSERT INTO stanza VALUES('S339','chorus','¡Quiero abandonarme,<br/>Todo a mi Señor!<br/>Busco que me llene<br/>Con Su gran amor.<br/>',NULL,190181,2);
INSERT INTO stanza VALUES('S339','2','¡Quiero abandonarme,<br/>Todo a mi Señor!<br/>Quiero en Él hundirme,<br/>Hasta ahogar el yo,<br/>Y ver este vaso<br/>Roto a Sus pies,<br/>Para que El me llene<br/>Y completo esté.<br/>',NULL,190182,3);
INSERT INTO stanza VALUES('S339','3','Quiero abandonarme<br/>A Su voluntad,<br/>Siguiendo Sus pasos<br/>En mi diario andar;<br/>Dejando ambiciones,<br/>Lo hago mi elección<br/>Quiero que Él me guíe<br/>Y escuchar Su voz.<br/>',NULL,190183,4);
INSERT INTO stanza VALUES('S339','4','¡Quiero abandonarme<br/>Por la eternidad!<br/>Completar Su gozo<br/>No mi voluntad.<br/>Planes y deseos<br/>Abandonaré;<br/>Aunque nada tenga<br/>Todo es mío en Él.<br/>',NULL,190184,5);
INSERT INTO stanza VALUES('S339','5','¡Quiero abandonarme!<br/>¡Oh, cuán dulce es!<br/>En Su amor, cautivo,<br/>Mas tan libre en Él;<br/>Libre del dominio<br/>De pecado y mal,<br/>Libre de temores<br/>Dudas y afán.<br/>',NULL,190185,6);
INSERT INTO stanza VALUES('S339','6','¡Quiero abandonarme!<br/>¡Qué descanso y paz<br/>Hallo en Su presencia<br/>Al mirar Su faz!<br/>Anfitrión divino,<br/>Llena mi interior,<br/>Refina las partes<br/>De mi corazón.<br/>',NULL,190186,7);
INSERT INTO stanza VALUES('S339','7','¡Tu Espíritu Santo<br/>Al llenarme así,<br/>Me hace estar completo<br/>Y bendito en Ti!<br/>Su luz no se apaga,<br/>Brilla en mi ser,<br/>Pues abandonado,<br/>Vivo para El.<br/>',NULL,190187,8);
INSERT INTO stanza VALUES('S340','1','A Jesús le rindo todo,<br/>Todo_a Él confiado doy;<br/>Viviré en Su presencia,<br/>Ofreciéndole mi_amor.<br/>',NULL,190188,1);
INSERT INTO stanza VALUES('S340','chorus','Yo me rindo_a Él,<br/>Yo me rindo_a Él,<br/>Todo_a Cristo yo me_entrego,<br/>Yo me rindo a Él.<br/>',NULL,190189,2);
INSERT INTO stanza VALUES('S340','2','A Jesús le rindo todo,<br/>A Sus pies postrado estoy;<br/>Los placeres he dejado,<br/>Y le sigo desde hoy.<br/>',NULL,190190,3);
INSERT INTO stanza VALUES('S340','3','A Jesús le rindo todo,<br/>Hazme Tuyo, mi Señor;<br/>Que Tu Espíritu me toque,<br/>Te haga real en mi interior.<br/>',NULL,190191,4);
INSERT INTO stanza VALUES('S340','4','A Jesús le rindo todo,<br/>Hoy me entregó a Ti, Señor;<br/>Que Tu bendición me alcance,<br/>Y el poder de Tu amor.<br/>',NULL,190192,5);
INSERT INTO stanza VALUES('S340','5','A Jesús le rindo todo,<br/>Siento el santo fuego hoy;<br/>Plena salvación yo gozo,<br/>Y a Su Nombre doy loor.<br/>',NULL,190193,6);
INSERT INTO stanza VALUES('S341','1','Completa es mi_entrega,<br/>A Ti me rindo hoy;<br/>Por siempre_y por completo,<br/>Soy Tuyo, mi Señor.<br/>',NULL,190194,1);
INSERT INTO stanza VALUES('S341','2','Hijo de Dios, me_amaste,<br/>Y Tuyo yo seré;<br/>¡Lo que yo soy y tengo,<br/>Por siempre Tuyo es!<br/>',NULL,190195,2);
INSERT INTO stanza VALUES('S341','3','Señor Jesús, hoy reina<br/>Sobre mi corazón,<br/>Pues siempre será Tuyo,<br/>Amado Salvador.<br/>',NULL,190196,3);
INSERT INTO stanza VALUES('S341','4','¡Oh, ven y reina, Cristo,<br/>Gobierna todo hoy!<br/>Hazme leal, Rey mío<br/>Y fiel a Ti, Señor<br/>',NULL,190197,4);
INSERT INTO stanza VALUES('S342','1','¡Todo sea para Cristo!<br/>Lo que redimió_en mi ser,<br/>Toda_acción, toda palabra,<br/>Todo tiempo y poder.<br/>¡Todo sea para Cristo!<br/>Todo tiempo y poder.<br/>¡Todo sea para Cristo!<br/>Todo tiempo y poder.<br/>',NULL,190198,1);
INSERT INTO stanza VALUES('S342','2','Que mis manos hagan Su_obra,<br/>Que_en su senda_estén mis pies,<br/>Que mis ojos puedan verlo,<br/>Que mi boca honor le dé.<br/>//¡Todo sea para Cristo!<br/>Que mi boca_honor le dé.//<br/>',NULL,190199,2);
INSERT INTO stanza VALUES('S342','3','Este mundo_estima joyas,<br/>Pequeñeces sin valor;<br/>Oro_y fama_es su jactancia;<br/>Mi confianza_es el Señor.<br/>//¡Todo sea para Cristo!<br/>Mi confianza_es el Señor.//<br/>',NULL,190200,3);
INSERT INTO stanza VALUES('S342','4','Desde que me fijé_en Cristo,<br/>Nada_atrae mi_atención;<br/>Al ver al Crucificado,<br/>Me cautiva tal visión.<br/>//¡Todo sea para Cristo!<br/>Me cautiva tal visión.//<br/>',NULL,190201,4);
INSERT INTO stanza VALUES('S342','5','¡Qué precioso! ¡Qué_asombroso!<br/>Que Jesús, supremo Rey,<br/>Se digne_a llamrme_amado,<br/>Y que yo descanse_en Él.<br/>//¡Todo sea para Cristo!<br/>Mi descanso_en Él hallé.//<br/>',NULL,190202,5);
INSERT INTO stanza VALUES('S343','1','Toma mi vida, Señor,<br/>Consagrada te la  doy;<br/>Toma todo lo que soy,<br/>Te lo_ofrezco con amor.<br/>Te lo_ofrezco con amor.<br/>',NULL,190203,1);
INSERT INTO stanza VALUES('S343','2','Toma mis manos, Señor,<br/>Las consagró a Tu labor;<br/>Toma hoy también mis pies<br/>//Para cosechar la mies.//<br/>',NULL,190204,2);
INSERT INTO stanza VALUES('S343','3','Ten mis labios para hablar<br/>Y Tu grey apacentar;<br/>Ten mi voz y cantaré<br/>//Siempre, sólo, por mi Rey.//<br/>',NULL,190205,3);
INSERT INTO stanza VALUES('S343','4','Ten mi plata y oro hoy,<br/>Ni una pizca quiero yo;<br/>Ten mi mente y su poder<br/>//Úsala para Tu bien.//<br/>',NULL,190206,4);
INSERT INTO stanza VALUES('S343','5','Toma aun mi corazón,<br/>Y haz en él Tu trono hoy;<br/>Toma Tú mi voluntad<br/>//A Tus pies postrada está.//<br/>',NULL,190207,5);
INSERT INTO stanza VALUES('S343','6','Toma, oh Señor, mi amor<br/>Que a Tus pies derramo hoy;<br/>Tómame para que así<br/>//Sea sólo para Ti.//<br/>',NULL,190208,6);
INSERT INTO stanza VALUES('S344','1','¿Qué te daré, mi Amo?<br/>Te diste Tú por mi.<br/>¿Doy la mitad? ¿O te daré más?<br/>¿O todo lo doy por Ti?<br/>',NULL,190209,1);
INSERT INTO stanza VALUES('S344','chorus','Mi Salvador y Cristo,<br/>Te diste Tú por mi.<br/>Tu hogar dejaste_allí<br/>Para morir por mí.<br/>¿Qué te daré, mi Amo?<br/>Te diste Tú por mi.<br/>No la mitad, mas todo mi ser,<br/>Yo lo daré a Ti.<br/>',NULL,190210,2);
INSERT INTO stanza VALUES('S344','2','¿Qué te daré, mi Amo,<br/>De mi_alma, Redentor?<br/>Mi don de_amor lo_ofrezco_a Ti hoy,<br/>Señor, bajo Tu control.<br/>',NULL,190211,3);
INSERT INTO stanza VALUES('S344','3','¿Qué te daré, mi Amo,<br/>Si Tú_eres el Dador?<br/>Tiempo_y vigor, talento_y ardor<br/>Serán Tuyos, oh Señor.<br/>',NULL,190212,4);
INSERT INTO stanza VALUES('S345','1','Que mi vida entera esté,<br/>Consagrada a Ti, Señor;<br/>Que mis días puedan ser,<br/>Para Tu gloria y honor.<br/>',NULL,190213,1);
INSERT INTO stanza VALUES('S345','chorus','En la cruz moriste Tú por mí,<br/>Y Tu sangre derramaste allí.<br/>Mi vida y amor te ofrezco, mi Señor,<br/>Quiero consagrarme a Ti.<br/>',NULL,190214,2);
INSERT INTO stanza VALUES('S345','2','Ten mis manos y mis pies<br/>Para cosechar la mies;<br/>Ten mis labios para hablar<br/>Por doquiera Tu verdad.<br/>',NULL,190215,3);
INSERT INTO stanza VALUES('S345','3','Ten mi plata y oro hoy,<br/>Ni una pizca retendré.<br/>Mi intelecto, úsalo,<br/>Oh Señor, para Tu bien.<br/>',NULL,190216,4);
INSERT INTO stanza VALUES('S345','4','Toma aun mi corazón,<br/>Y hazlo Tuyo, mi Señor;<br/>Mi afecto y voluntad<br/>A Tus pies quiero postrar.<br/>',NULL,190217,5);
INSERT INTO stanza VALUES('S345','5','Toma mi completo ser<br/>Y uno contigo seré.<br/>Tómame para que así<br/>Sea sólo para ti.<br/>',NULL,190218,6);
INSERT INTO stanza VALUES('S346','1','Has ansiado más paz, y más de disfrutar,<br/>Y_has orado con todo afán;<br/>Pero no hallarás bendición ni solaz<br/>Sin poner todo sobre_el altar.<br/>',NULL,190219,1);
INSERT INTO stanza VALUES('S346','chorus','¿Está puesto tu todo sobre el altar?<br/>¿Controla Dios Tu corazón?<br/>Solo_habrá bendición, paz, descanso y dulzor,<br/>Si entregas tu todo_al Señor.<br/>',NULL,190220,2);
INSERT INTO stanza VALUES('S346','2','¿Al Señor seguirás? ¿Su Palabra oirás?<br/>Paz y gozo así gustarás;<br/>Sigue Su voluntad y guardado serás,<br/>Si tu todo está_en el altar.<br/>',NULL,190221,3);
INSERT INTO stanza VALUES('S346','3','No podremos saber lo que nos dará Él<br/>En respuesta a la oración<br/>Hasta todo ceder, cuerpo_y alma también,<br/>Sobre el altar, ante el Señor.<br/>',NULL,190222,4);
INSERT INTO stanza VALUES('S346','4','¡Quién podrá expresar el amor que_Él dará,<br/>Alegrando nuestro corazón!<br/>A Sus pies nos dará comunión sin igual<br/>Puestos sobre_el altar del Señor.<br/>',NULL,190223,5);
INSERT INTO stanza VALUES('S347','1','Haz lo que quieras,<br/>Hazlo, Señor;<br/>Tú el Alfarero,<br/>Yo el barro soy.<br/>Hazme conforme‿a<br/>Tu voluntad,<br/>Mientras yo cedo<br/>Gozo Tu paz.<br/>',NULL,190224,1);
INSERT INTO stanza VALUES('S347','2','Haz lo que quieras,<br/>Hazlo, Señor;<br/>Hoy escudriña<br/>Mi corazón.<br/>Lávame, quita<br/>Toda maldad,<br/>Mientras me humillo<br/>Frente a Tu faz.<br/>',NULL,190225,2);
INSERT INTO stanza VALUES('S347','3','Haz lo que quieras,<br/>Hazlo, Señor;<br/>Herido y pobre,<br/>Busco Tu amor.<br/>Cierto que es Tuyo<br/>Todo poder;<br/>Salvador mío,<br/>Sana mi ser.<br/>',NULL,190226,3);
INSERT INTO stanza VALUES('S347','4','Haz lo que quieras,<br/>Hazlo, Señor;<br/>Conquista todo<br/>Mi corazón.<br/>Oh que me llene<br/>Tu Espíritu,<br/>Hasta que exprese<br/>Tu plenitud.<br/>',NULL,190227,4);
INSERT INTO stanza VALUES('S348','1','No me cuenten de placeres<br/>Ni del lucro, su_atracción;<br/>No me_ofrezcan vanidades,<br/>Ni del mundo, su_ilusión.<br/>Todo_ídolo_he traído<br/>No me pertenezco hoy;<br/>Es mi corazón de Cristo<br/>Solamente Suyo soy.<br/>',NULL,190228,1);
INSERT INTO stanza VALUES('S348','chorus','Mío ya no soy,<br/>Mío ya no soy,<br/>Pertenezco_a Cristo<br/>Y mío ya no soy.<br/>',NULL,190229,2);
INSERT INTO stanza VALUES('S348','2','¡Cuán bendito_es el reposo<br/>Cuando somos de Jesús!<br/>Cuando no tenemos nada,<br/>Él nos da Su plenitud.<br/>¡Oh, mi Cristo, sé mi dueño,<br/>Hazme_al fin Tu posesión!<br/>Cuando_afirme que_eres mío,<br/>En mí_encuentra Tu porción.<br/>',NULL,190230,3);
INSERT INTO stanza VALUES('S348','3','Alma mía, ya no luches;<br/>Tuya ya no debes ser;<br/>Date hoy a Jesucristo,<br/>Y sé sólo para Él.<br/>Lo dio todo por ganarte,<br/>Debes tú lo mismo_hacer;<br/>Todo lo que_Él tiene_es tuyo;<br/>Que tu_amor sea para Él.<br/>',NULL,190231,4);
INSERT INTO stanza VALUES('S349','1','Vivo por Cristo la vida que_es fiel,<br/>Anhelo_en todo_agradarlo a Él;<br/>Libre le cedo todo_el corazón;<br/>Ésta_es la senda do hay bendición.<br/>',NULL,190232,1);
INSERT INTO stanza VALUES('S349','chorus','Oh, Salvador y Cristo,<br/>Me_entrego todo_a Ti,<br/>Pues Tú me redimiste,<br/>Te_entregaste por mí.<br/>No tengo otro Amo,<br/>Tuyo_es mi corazón;<br/>Mi vida doy para vivir<br/>Sólo por Ti, Señor.<br/>',NULL,190233,2);
INSERT INTO stanza VALUES('S349','2','Vivo por Cristo, quien por mí murió;<br/>Él mi vergüenza_y pecado llevó.<br/>Honró_el llamado de Su gran amor;<br/>Él es mi guía, mi todo le doy.<br/>',NULL,190234,3);
INSERT INTO stanza VALUES('S349','3','Vivo por Cristo doquiera que_esté;<br/>Su santo nombre en todo honraré.<br/>Por Él, dispuesto_a sufrir aflicción,<br/>Mi cruz a diario yo llevo_en amor.<br/>',NULL,190235,4);
INSERT INTO stanza VALUES('S349','4','Vivo por Cristo mientras vivo_estoy;<br/>Es Su sonrisa mi tesoro hoy.<br/>Busco las almas que Él redimió;<br/>A los cansados, los llevó a Dios.<br/>',NULL,190236,5);
INSERT INTO stanza VALUES('S350','1','Mi Jesús, todo_he dejado,<br/>Con mi cruz te sigo_en pos;<br/>Despreciado,_abandonado,<br/>Mas mi todo eres hoy.<br/>Que perezca todo anhelo,<br/>Esperanza y_ambición;<br/>Mas cuán rica es mi_herencia:<br/>Cristo y Dios mi todo son.<br/>',NULL,190237,1);
INSERT INTO stanza VALUES('S350','2','A mi Salvador el mundo<br/>Despreció_y también a mí;<br/>Engañosos son los hombres,<br/>Mas no_hay falsedad en Ti.<br/>Y si hoy Tú me sonríes,<br/>Dios de amor y de poder,<br/>Aunque me_odien y repudien,<br/>Tu faz suficiente es.<br/>',NULL,190238,2);
INSERT INTO stanza VALUES('S350','3','Si los hombres me angustian,<br/>A Tu pecho_acudiré;<br/>Si mi vida trae sus pruebas,<br/>Mi descanso Cristo es.<br/>Mientras Tu amor no cese,<br/>No me_agravia el sufrir;<br/>No me_atrae gozo_alguno<br/>Si tu no estás allí.<br/>',NULL,190239,3);
INSERT INTO stanza VALUES('S350','4','Muévete de gracia_a gloria,<br/>Fuerte_en oración y fe,<br/>Al gran día sempiterno,<br/>Guiado por Su mano fiel.<br/>Pronto tu peregrinaje<br/>Y misión se_acabarán;<br/>La_oración se_hará_alabanza,<br/>La fe_en vista cambiará.<br/>',NULL,190240,4);
INSERT INTO stanza VALUES('S351','1','¿Cómo seguir a mi Señor?<br/>¿Cómo_expresar al que_amo yo,<br/>Y, fiel, seguir los pasos que<br/>Me llevan a Su trono hoy?<br/>',NULL,190241,1);
INSERT INTO stanza VALUES('S351','2','Escarnio, llanto, privación,<br/>Vida de pena_humillación,<br/>Espinas, beso de traición;<br/>¿Es senda de consagración?<br/>',NULL,190242,2);
INSERT INTO stanza VALUES('S351','3','Que no_haya queja_en mí jamás<br/>Si_abundan penas, mi Señor;<br/>Toda mi_angustia_olvidaré<br/>Si al Calvario vuelvo yo.<br/>',NULL,190243,3);
INSERT INTO stanza VALUES('S351','4','Todo deleite y placer<br/>Tú rehusaste disfrutar<br/>Para_ayunar, sufrir, velar<br/>Y laborar sin un hogar.<br/>',NULL,190244,4);
INSERT INTO stanza VALUES('S351','5','¡Viniste a morir por mí!<br/>No a buscar comodidad;<br/>Me_ofrece_el mundo_un bienestar,<br/>Mas sobre todo te_he de_amar.<br/>',NULL,190245,5);
INSERT INTO stanza VALUES('S352','1','Yo quiero tanto a mi Amo<br/>Que libre no saldré;<br/>Me redimió con precio<br/>Me_ha conquistado El.<br/>No dejaré_el servicio,<br/>Es dulce bendición,<br/>Y_en los momentos duros<br/>Me da consolación.<br/>',NULL,190246,1);
INSERT INTO stanza VALUES('S352','2','Mi Amo dio Su sangre<br/>Por un vasallo_infiel,<br/>Cortó las ataduras<br/>Del mal y el ego cruel.<br/>Me trajo_a Su servicio,<br/>Me permitió_elegir<br/>La libertad perfecta<br/>Que no dejaré ir.<br/>',NULL,190247,2);
INSERT INTO stanza VALUES('S352','3','No acortaré_el servicio,<br/>¡Yo todo aquí daré!<br/>A Él, que me_ama tanto,<br/>Que dio Su mismo ser.<br/>Con gozo yo le adoro,<br/>Por eso cantaré:<br/>Yo quiero tanto a mi Amo<br/>Que libre no saldré.<br/>',NULL,190248,3);
INSERT INTO stanza VALUES('S353','1','Glorioso Príncipe, mi Dios,<br/>A Ti mis manos rindo hoy;<br/>Mi voluntad hoy Tuya es,<br/>Tu_esclavo_alegre yo seré.<br/>',NULL,190249,1);
INSERT INTO stanza VALUES('S353','2','Oh, a la puerta llévame,<br/>Horada mi oreja bien;<br/>Tus lazos son mi libertad,<br/>Contigo quiero siempre_obrar.<br/>',NULL,190250,2);
INSERT INTO stanza VALUES('S353','3','Mi_oreja, manos, voluntad<br/>Son Tuyas por completo ya.<br/>Las libertades de mi yo,<br/>Las rindo a Tus pies, Señor.<br/>',NULL,190251,3);
INSERT INTO stanza VALUES('S353','4','Suprime Tú tal libertad,<br/>Así mis manos llenarás,<br/>Y mis oídos te oirán<br/>Decir que uno somos ya.<br/>',NULL,190252,4);
INSERT INTO stanza VALUES('S354','1','¡Ha entrado! ¡Ha entrado!<br/>Salgan todos los demás;<br/>Hoy mi corazón es Suyo,<br/>Dividido ya no_está.<br/>',NULL,190253,1);
INSERT INTO stanza VALUES('S354','2','¡Ha entrado! ¡Ha entrado!<br/>¡Fuera duda y_el pecar!<br/>Es Señor de cada parte,<br/>¡Todo Él posee ya!<br/>',NULL,190254,2);
INSERT INTO stanza VALUES('S354','3','Me llamó por tanto tiempo,<br/>Sus heridad pude ver;<br/>Ya por fin le he abierto<br/>Cada parte de mi ser.<br/>',NULL,190255,3);
INSERT INTO stanza VALUES('S354','4','¡Ha entrado! ¡Ha entrado!<br/>Toda_angustia huirá.<br/>Donde_Él reine como Amo<br/>No habrá ningun pesar.<br/>',NULL,190256,4);
INSERT INTO stanza VALUES('S355','1','¿Soy un soldado de la cruz?<br/>¿Sigo_al Cordero yo?<br/>¿Su causa temo confesar,<br/>O_hablar Su nombre hoy?<br/>',NULL,190257,1);
INSERT INTO stanza VALUES('S355','chorus','En el nombre de Jesús,<br/>El cual murió por mí,<br/>Por gracia_el reino ganaré,<br/>Mi cruz llevando_aquí.<br/>',NULL,190258,2);
INSERT INTO stanza VALUES('S355','2','Si_otros han peleado ya<br/>Para el premio ganar,<br/>¿Cómo podría yo_esperar<br/>Total comodidad?<br/>',NULL,190259,3);
INSERT INTO stanza VALUES('S355','3','¿No hay rivales que vencer?<br/>¿Ni lluvias ni tifón?<br/>¿Me_ayuda_el mundo a correr,<br/>Por gracia_en pos de Dios?<br/>',NULL,190260,4);
INSERT INTO stanza VALUES('S355','4','Si por la lucha reinaré,<br/>¡Aumenta mi valor!<br/>Por Tu palabra_aguantaré<br/>La carga y_el dolor.<br/>',NULL,190261,5);
INSERT INTO stanza VALUES('S356','1','¿Quién está por Cristo?<br/>¿Quién le servirá?<br/>¿Quién traerá mas vidas?<br/>¿Quién cooperará?<br/>¿Quién, dejando_el mundo,<br/>Se_opondrá_al rival?<br/>¿Quién está por Cristo?<br/>¿Quién por Él irá?<br/>',NULL,190262,1);
INSERT INTO stanza VALUES('S356','chorus','Por Tu_inmensa gracia,<br/>Redención y_amor,<br/>De Tu lado_estamos;<br/>Somos del Señor.<br/>',NULL,190263,2);
INSERT INTO stanza VALUES('S356','2','No es por la gloria<br/>O Corona real<br/>Que nos alistamos<br/>Para_así luchar;<br/>Mas es el reclamo<br/>De Su_amor sin par;<br/>Deben los llamados,<br/>De Su lado_estar.<br/>',NULL,190264,3);
INSERT INTO stanza VALUES('S356','3','No con oro_o plata<br/>Nos compraste Tú,<br/>Mas fue con Tu sangre<br/>Vertida_en la cruz.<br/>Con Tus bendiciones<br/>Llenas nuestro ser;<br/>Nos has liberado,<br/>Para fieles ser.<br/>',NULL,190265,4);
INSERT INTO stanza VALUES('S356','4','¡Qué feroz conflicto!<br/>Fuerte_es el rival,<br/>Mas no puede nadie<br/>Al Rey destronar.<br/>Con Su estandarte<br/>La victoria da;<br/>Su verdad eterna<br/>Siempre triunfará,<br/>',NULL,190266,5);
INSERT INTO stanza VALUES('S356','5','Fuimos reclutados<br/>Por el Capitán;<br/>Somos Sus soldados<br/>Que_en la tierra_están.<br/>Que nuestro servicio<br/>Sea sin frialdad,<br/>Noble, fiel, valiente<br/>Y con lealtad.<br/>',NULL,190267,6);
INSERT INTO stanza VALUES('S357','1','¿Cómo podré quedarme_atrás?<br/>Y contristar Tu_Espíritu,<br/>Si_esperas Tú por mí?<br/>Estoy dispuesto_a regresar;<br/>No quiero yo más demorar,<br/>Sino seguirte_a Ti.<br/>',NULL,190268,1);
INSERT INTO stanza VALUES('S357','2','Hoy sin reservas yo te doy<br/>Lo que poseo_y lo que soy<br/>Para cumplir Tu plan.<br/>¡Oh, que lo_aceptes, mi Señor!<br/>Que sólo busque hacer yo<br/>Padre, Tu voluntad.<br/>',NULL,190269,2);
INSERT INTO stanza VALUES('S357','3','Mirando atrás, dolor sentí:<br/>Jamás yo traje_un alma_a Ti,<br/>Tu palabra_escondí.<br/>Oh, que_el Señor Su_unción me dé<br/>Y que Él viva en mi ser<br/>Para yo_hablar de Él.<br/>',NULL,190270,3);
INSERT INTO stanza VALUES('S357','4','Me dio Su gracia_en Su bondad,<br/>Pues, más que_amigo,_en realidad<br/>Su novia anhelo ser.<br/>Su vida quiero expresar,<br/>Tomar Su cruz sin vacilar<br/>Y uno ser con Él.<br/>',NULL,190271,4);
INSERT INTO stanza VALUES('S358','1','Muchos quieren ver el reino<br/>Sin llevar la cruz;<br/>Muchos luchan por un premio,<br/>Pocos por Jesús.<br/>¿Quién quisiera_a Él seguirlo<br/>No por gratitud?<br/>¿Quién quisiera a Él seguirlo<br/>No por gratitud?<br/>',NULL,190272,1);
INSERT INTO stanza VALUES('S358','2','Muchos quieren ver Su gloria<br/>Sin sufrir desdén;<br/>Muchos creen tener el reino,<br/>Mas sin padecer.<br/>//¿Cuántos por Jesús quisieran<br/>El mundo perder?//<br/>',NULL,190273,2);
INSERT INTO stanza VALUES('S358','3','Muchos comen en Su mesa,<br/>¿Quién ayunará?<br/>Muchos buscan hoy Su trono,<br/>Sin ningún penar.<br/>//Pocos pueden una hora<br/>Con Jesús velar.//<br/>',NULL,190274,3);
INSERT INTO stanza VALUES('S358','4','Muchos buscan Su corona<br/>Sin humillación;<br/>¿Quién al recibir Su gracia<br/>No tendrá canción?<br/>//Mas si El les da una carga<br/>Hay lamentación.//<br/>',NULL,190275,4);
INSERT INTO stanza VALUES('S358','5','Mas los que en verdad le aman<br/>Ya por bien o mal,<br/>No_escatimarán Su sangre<br/>Si hay necesidad.<br/>//Sea por vida o por muerte<br/>Yo te quiero amar.//<br/>',NULL,190276,5);
INSERT INTO stanza VALUES('S359','1','Ningún mortal podrá narrar<br/>La libertad de aquel<br/>Que vence_el cebo terrenal<br/>Y_a Dios se entrega fiel;<br/>Todas las cosas son de él,<br/>Presente_o por venir;<br/>Es Cristo su perfecta paz,<br/>Y Cristo es su fin.<br/>',NULL,190277,1);
INSERT INTO stanza VALUES('S359','2','Ya que podemos escoger<br/>Regir con nuestro Rey,<br/>Sería extraño rehusar<br/>Ser sólo para El.<br/>De sacrificios, ni hablar;<br/>Es gozo sin igual<br/>A todo costo componer<br/>La armada celestial.<br/>',NULL,190278,2);
INSERT INTO stanza VALUES('S359','3','¡Qué ganga tu parte entregar<br/>Por la totalidad!<br/>Todo hombre y todo evento así<br/>Al fiel le servirán.<br/>Lo Suyo, todo tuyo es,<br/>Si tú a Él te das;<br/>Vida abudante hallarás,<br/>Y un reino que vendrá.<br/>',NULL,190279,3);
INSERT INTO stanza VALUES('S360','1','La consagración Tú eres<br/>Consagrado_estás, Señor;<br/>Satisfecho_está el Padre:<br/>Esto_es la consagración.<br/>Nada te_agradó_en la tierra,<br/>Salvo_hacer Su voluntad.<br/>Hoy Tu vives en nosotros;<br/>Consagrados nos harás.<br/>',NULL,190280,1);
INSERT INTO stanza VALUES('S360','2','Te_alabamos por el cuadro,<br/>De aquel carnero que<br/>Fue_inmolado y quemado,<br/>Y Dios satisfecho fue.<br/>Tal carnero eres, Cristo,<br/>Ofrecido para Dios;<br/>Tu consagración nos lleva<br/>A seguir Tus pasos hoy.<br/>',NULL,190281,2);
INSERT INTO stanza VALUES('S360','3','Al comerte, Jesucristo,<br/>Consagrados nos harás;<br/>Por Tu vida en nosotros,<br/>Tu_obediencia_es nuestra ya.<br/>Ya no hay que esforzarnos<br/>Para consagrados ser;<br/>En nosotros hoy Tú vives,<br/>Solo debemos comer.<br/>',NULL,190282,3);
INSERT INTO stanza VALUES('S360','4','Te_alabamos, pues comerte<br/>Es real consagración;<br/>Al comer y disfrutarte,<br/>Somos uno hoy con Dios;<br/>Al comerte, uno somos<br/>Con Tu meta_y voluntad:<br/>Sí, Señor, pues al comerte<br/>Consagrados nos harás.<br/>',NULL,190283,4);
INSERT INTO stanza VALUES('S361','1','Uno soy, Señor, contigo,<br/>En espíritu‿uno soy;<br/>Lo que eres yo poseo,<br/>En mi ser Tú vives hoy.<br/>',NULL,190284,1);
INSERT INTO stanza VALUES('S361','chorus','Tú y yo, en unión,<br/>Tú y yo, en unión,<br/>Tus riquezas tomo‿a diario,<br/>Eres toda mi porción.<br/>',NULL,190285,2);
INSERT INTO stanza VALUES('S361','2','Yo Tu vida humana tengo.<br/>Lleno de Tu humanidad,<br/>Tu completa obediencia,<br/>Disponible ahora está.<br/>',NULL,190286,3);
INSERT INTO stanza VALUES('S361','3','En crucifixión contigo,<br/>En la cruz en Ti morí,<br/>Para_el mundo estoy muerto,<br/>Y el mundo para mí.<br/>',NULL,190287,4);
INSERT INTO stanza VALUES('S361','4','En resurrección contigo,<br/>Levantado, vivo en Ti;<br/>Esa vida_eres Tú Mismo,<br/>Ahora_en mí, Señor, en mí.<br/>',NULL,190288,5);
INSERT INTO stanza VALUES('S361','5','Ascendido yo contigo,<br/>En los cielos ahora estoy,<br/>Escondida en Ti mi vida,<br/>Peregrino al mundo soy.<br/>',NULL,190289,6);
INSERT INTO stanza VALUES('S361','6','Entronado estoy contigo,<br/>Con Tu autoridad en mí,<br/>Participo de Tu vida,<br/>Tú en mí y yo en Ti.<br/>',NULL,190290,7);
INSERT INTO stanza VALUES('S362','1','Somos uno, Hijo_eterno,<br/>En espíritu por fe,<br/>Compartimos en Tu muerte,<br/>Y de Tu vida también.<br/>Somos uno, Hijo_amado,<br/>Somos parte de Tu ser,<br/>De Tu_Espíritu, morada;<br/>La_heredad del Padre fiel.<br/>',NULL,190291,1);
INSERT INTO stanza VALUES('S362','2','Somos uno, Encarnado,<br/>Pues nacimos en unión,<br/>Como miembros de Tu cuerpo,<br/>Por la tierra vamos hoy.<br/>Somos uno, Hijo ungido,<br/>Compartimos el poder<br/>Del Espíritu, obrando<br/>En cooperación con Él.<br/>',NULL,190292,2);
INSERT INTO stanza VALUES('S362','3','Somos uno,_Abandonado,<br/>Juicio_y maldición pasó,<br/>Al pecado_estamos muertos,<br/>El infierno se venció.<br/>Somos uno, Levantado,<br/>Muerte perdió su aguijón,<br/>Damos frutos de justicia,<br/>En Tu nueva creación.<br/>',NULL,190293,3);
INSERT INTO stanza VALUES('S362','4','Somos uno, Ascendido,<br/>Con Tu misma_autoridad,<br/>Compartimos en Tu trono<br/>Y_en Tu rango celestial.<br/>Somos uno, Tú que vienes,<br/>Y nos glorificarás,<br/>Tu belleza_expresaremos,<br/>En eterna unidad.<br/>',NULL,190294,4);
INSERT INTO stanza VALUES('S363','1','Aunque mil veces Cristo<br/>Naciera en Belén<br/>Si Él en ti no nace,<br/>¡Oh, qué desdicha es!<br/>La cruz en el Calvario<br/>Jamás te salvará;<br/>Sólo la cruz en tu_alma<br/>Tu ser puede sanar.<br/>',NULL,190295,1);
INSERT INTO stanza VALUES('S363','chorus','Te tomo,_oh cruz de Cristo,<br/>Hoy en mi corazón,<br/>Para que muera_al ego yo,<br/>Y viva_en resurrección.<br/>',NULL,190296,2);
INSERT INTO stanza VALUES('S363','2','Oh, hombre, lo que ames,<br/>Tú llegarás a ser:<br/>Polvo, si_el polvo amas,<br/>Dios, si_lo amas a Él.<br/>Oh, sal para que_Él entre;<br/>No seas, y Él será.<br/>Si mueres tú, Él vive;<br/>Espera,_Él suplirá.<br/>',NULL,190297,3);
INSERT INTO stanza VALUES('S363','3','La senda más directa<br/>A Dios es el amor;<br/>La del conocimiento<br/>Te llevará al error.<br/>Despójate del mundo,<br/>Y_así tu corazón<br/>Será de_amor más lleno,<br/>Y santo como Dios.<br/>',NULL,190298,4);
INSERT INTO stanza VALUES('S364','1','¡Oh, qué_admirable lugar<br/>Al que me trajo_el Señor!<br/>Yo por Su gracia_he de ser<br/>Como_Aquel que me salvó.<br/>Al estar frente_al Señor,<br/>Tal como Él he de ser;<br/>Mas si yo le sigo hoy,<br/>Puedo ser tal como Él.<br/>',NULL,190299,1);
INSERT INTO stanza VALUES('S364','chorus','Tal como Él.<br/>Tal como Él,<br/>¡Qué gracia es! ¡Palabra fiel!<br/>Todos nosotros podemos ser<br/>Uno con Cristo, tal como Él.<br/>',NULL,190300,2);
INSERT INTO stanza VALUES('S364','2','Uno_en Su muerte_en la cruz,<br/>Uno_en Su resurrección;<br/>Aun tan libre como Él<br/>De terrenal maldición.<br/>Uno_en el trono con Él,<br/>Uno en la filiación;<br/>Uno cual rama_y la vid<br/>La novia y_el Novio son.<br/>',NULL,190301,3);
INSERT INTO stanza VALUES('S364','3','Uno en lo que_Él logró,<br/>Uno_en Su nombre_al orar;<br/>Lo que ordena el Señor,<br/>Lo puedo yo reclamar.<br/>Uno_en Su fe y Su_amor;<br/>Uno en vida_hoy con Él;<br/>Sellado yo por la_unción,<br/>Santo cual Él puedo ser.<br/>',NULL,190302,4);
INSERT INTO stanza VALUES('S365','1','Muerto_estoy con Jesucristo<br/>Para_el mundo,_el yo y_el mal,<br/>En resurrección de vida<br/>Comencé por fin a_entrar.<br/>Conformado a Su muerte<br/>Al sufrir por Su_interés;<br/>Con mi Salvador y Guía<br/>Al Calvario yo iré.<br/>',NULL,190303,1);
INSERT INTO stanza VALUES('S365','chorus','Al Calvario yo iré,<br/>Donde Él por mí ya fue,<br/>Ven, Señor, ayúdame,<br/>Y al Calvario yo iré.<br/>',NULL,190304,2);
INSERT INTO stanza VALUES('S365','2','Dulce es morir con Cristo<br/>Si vivo en resurrección,<br/>Y llevar Sus sufrimientos<br/>Si rebosa el corazón.<br/>En resurrección Él mora<br/>En mi ser con gran poder,<br/>Y por eso muy contento<br/>Al Calvario yo iré.<br/>',NULL,190305,3);
INSERT INTO stanza VALUES('S365','3','Si morimos, viviremos<br/>Por la vida del Señor;<br/>Si sufrimos, reinaremos,<br/>Disfrutando el galardón.<br/>Oh, cuán dulce la mañana<br/>Cuando al Amo puedas ver,<br/>Y te diga_alegremente:,<br/>"Al Calvario fuiste fiel".<br/>',NULL,190306,4);
INSERT INTO stanza VALUES('S366','1','En la cruz estoy con Cristo,<br/>Y me libertó la cruz,<br/>Fui con El resucitado,<br/>Vive en mi‿espíritu.<br/>',NULL,190307,1);
INSERT INTO stanza VALUES('S366','chorus','¡Oh, qué dulce es morir con Cristo!<br/>Para_el mundo,_el mal y_el yo;<br/>¡Oh, qué dulce es vivir con Cristo!<br/>Mientras reina_en mi‿interior.<br/>',NULL,190308,2);
INSERT INTO stanza VALUES('S366','2','El misterio de los siglos,<br/>Por la fe se reveló;<br/>La_esperanza de la gloria:<br/>Cristo_en mí, proclamo yo.<br/>',NULL,190309,3);
INSERT INTO stanza VALUES('S366','3','El secreto de la siega:<br/>Muerto_el grano, vida da;<br/>Y el árbol injertado,<br/>Rica vida obtendrá.<br/>',NULL,190310,4);
INSERT INTO stanza VALUES('S366','4','Un secreto tiene_el santo:<br/>No es la santidad, mas Él;<br/>¡Oh, Señor, ven a vaciarnos,<br/>Y_a llenarnos con Tu ser!<br/>',NULL,190311,5);
INSERT INTO stanza VALUES('S366','5','Es un bálsamo_a la pena,<br/>El morir a nuestro yo,<br/>Y_encontrar la vida_eterna,<br/>Que nos suple nuestro Dios.<br/>',NULL,190312,6);
INSERT INTO stanza VALUES('S366','6','Es la‿historia de mi Amo:<br/>Por la cruz al trono fue;<br/>Como Él yendo_a la gloria,<br/>Por la muerte entraré.<br/>',NULL,190313,7);
INSERT INTO stanza VALUES('S367','1','Muerto con Cristo,‿Él me levantó;<br/>Qué más me queda a mí por hacer?<br/>No más esfuerzos, no más luchar,<br/>En novedad de vida‿he de‿andar.<br/>¡Gloria sea_a Dios!<br/>',NULL,190314,1);
INSERT INTO stanza VALUES('S367','2','Resucitado con Cristo estoy,<br/>Él mi Cabeza gloriosa es,<br/>Mi senda ahora es santidad,<br/>Muerto al pecado, libre en verdad.<br/>¡Gloria sea_a Dios!<br/>',NULL,190315,2);
INSERT INTO stanza VALUES('S367','3','Vivo con Cristo, Él no muere más.<br/>Sigo a Cristo, delante Él va.<br/>Del cautiverio ya libre soy,<br/>Tengo por muerto mi ego hoy.<br/>¡Gloria sea_a Dios!<br/>',NULL,190316,3);
INSERT INTO stanza VALUES('S367','4','Vivo por Cristo, me rindo a Él,<br/>Todos mis miembros pongo a Sus pies;<br/>Hoy por Su gracia, no por la ley,<br/>Venzo el pecado, ¡Cristo es mi Rey!<br/>¡Gloria sea_a Dios!<br/>',NULL,190317,4);
INSERT INTO stanza VALUES('S367','5','Creciendo en Cristo, no se verá<br/>Lo vergonzoso de mi pecar;<br/>Llevaré fruto de santidad,<br/>La vida eterna florecerá.<br/>¡Gloria sea_a Dios!<br/>',NULL,190318,5);
INSERT INTO stanza VALUES('S368','1','Cuando Cristo_en la cruz murió,<br/>También morí;<br/>Por mí, Él mi lugar tomó;<br/>Ya Dios a Cristo aceptó,<br/>También a mí.<br/>',NULL,190319,1);
INSERT INTO stanza VALUES('S368','chorus','Estoy crucificado con Cristo,_ y vivo yo,<br/>Mas no yo, es Cristo quien vive_en mí;<br/>Y la vida que vino hoy,<br/>La vivo por fe_en el Hijo de Dios,<br/>Quien me amó_y se dio por mí.<br/>',NULL,190320,2);
INSERT INTO stanza VALUES('S368','2','Cuando Cristo resucitó,<br/>Estuve_allí;<br/>Hoy mía_es Su resurrección,<br/>La vid es Él; yo,_el pámpano;<br/>Él vive_en mí.<br/>',NULL,190321,3);
INSERT INTO stanza VALUES('S368','3','Cuando Cristo venga por mí,<br/>Allí_estaré;<br/>Con Él, yo como Él seré,<br/>Y Su gloriosa majestad<br/>También tendré.<br/>',NULL,190322,4);
INSERT INTO stanza VALUES('S368','4','Mantenme_en esta vida real,<br/>Bendita_y fiel;<br/>Ayúdame_a vivir con Él,<br/>Y_en Él morir para tener<br/>Su gloria_en mí.<br/>',NULL,190323,5);
INSERT INTO stanza VALUES('S369','1','¡Qué provisión ha hecho Dios:<br/>Jesús murió_en la cruz por mí!<br/>Junto con Él colgado fui,<br/>Su sepultura me_incluyó.<br/>',NULL,190324,1);
INSERT INTO stanza VALUES('S369','2','Con Él también resucité;<br/>Morí_al pecado, ¿seguiré<br/>Viviendo bajo_esclavitud,<br/>Cuando victoria_en Él gané?<br/>',NULL,190325,2);
INSERT INTO stanza VALUES('S369','3','Dios a Su diestra lo sentó;<br/>Intercediendo_está_el Señor;<br/>Me uno a Su_intercesión:<br/>Que_otros reciban salvación.<br/>',NULL,190326,3);
INSERT INTO stanza VALUES('S369','4','¡Qué nuevo nombre recibí<br/>Por nacimiento:_hijo de Dios!<br/>Yo represento_a Su Hijo_aquí,<br/>Y en el cielo, Él a mí.<br/>',NULL,190327,4);
INSERT INTO stanza VALUES('S369','5','En asención está Jesús,<br/>Y yo, en este mundo cruel;<br/>Puesto que_Él vive en mi ser,<br/>En ascensión estoy con Él.<br/>',NULL,190328,5);
INSERT INTO stanza VALUES('S370','1','Muero con Cristo, con Él yo morí;<br/>Vivo con Cristo, Él es mi vivir;<br/>Hasta que brille Su gloria_en mi ser,<br/>Cada momento yo Suyo seré.<br/>',NULL,190329,1);
INSERT INTO stanza VALUES('S370','chorus','Cada momento Su vida me da,<br/>Cada momento Él me guardará;<br/>Hasta que brille Su gloria_en mi ser,<br/>Cada momento yo Suyo seré.<br/>',NULL,190330,2);
INSERT INTO stanza VALUES('S370','2','Toda batalla_o contienda aquí<br/>Ha de pelear y ganar Él por mí;<br/>Sobre nosotros bandera_alzará,<br/>Cada momento me vigilará.<br/>',NULL,190331,3);
INSERT INTO stanza VALUES('S370','3','En cada prueba, muy cerca_Él está,<br/>Lleva mis cargas, alivio me da;<br/>En aflicciones, me muestra Su_amor,<br/>Cada momento me cuida_el Señor.<br/>',NULL,190332,4);
INSERT INTO stanza VALUES('S370','4','Si hay angustias o si hay temor,<br/>O_abatimiento, me_inspira Su_amor;<br/>Desde Su trono me salva_Él aquí,<br/>Cada momento se_acuerda de mí.<br/>',NULL,190333,5);
INSERT INTO stanza VALUES('S370','5','Tenga flaquezas o enfermedad,<br/>Cristo me dice:  "Mi_amparo tendrás";<br/>Cada momento,_en tinieblas o luz,<br/>Mora conmigo aún mi Jesús.<br/>',NULL,190334,6);
INSERT INTO stanza VALUES('S371','1','¡Qué admirable hecho: con Jesús morí!<br/>Me libró de carne_y de pasión;<br/>¡Cuán glorioso hecho, vivo hoy con Él!<br/>Por Su vida de resurrección.<br/>',NULL,190335,1);
INSERT INTO stanza VALUES('S371','chorus','En la cruz clavado fui con mi Señor,<br/>Clavado fui con mi Señor;<br/>Mas hoy, por Su vida de resurrección,<br/>Morando_estoy con Dios.<br/>',NULL,190336,2);
INSERT INTO stanza VALUES('S372','1','¡Qué gran misterio, mi Señor!<br/>Puedo ahora comprender:<br/>Morí contigo en la cruz,<br/>Para triunfar en su poder.<br/>',NULL,190337,1);
INSERT INTO stanza VALUES('S372','2','Tu cruz, Señor, es mía hoy;<br/>Cuando acepto que morí,<br/>Brilla en mi vida su fulgor,<br/>Y el mundo deja de existir.<br/>',NULL,190338,2);
INSERT INTO stanza VALUES('S372','3','Ya que en la cruz contigo estoy,<br/>No busco más la vanidad;<br/>Del yo y pecado libre soy,<br/>No puedo al mundo disfrutar.<br/>',NULL,190339,3);
INSERT INTO stanza VALUES('S372','4','Sobre la cruz, mi buen Señor,<br/>Tomo contigo mi lugar;<br/>Entrelazados Tú y yo,<br/>Tu vida es mía en verdad.<br/>',NULL,190340,4);
INSERT INTO stanza VALUES('S372','5','Ya que heriste a Tu rival,<br/>Y derribaste su poder,<br/>Por Tu poder obrando en mí<br/>Yo puedo en Ti también vencer.<br/>',NULL,190341,5);
INSERT INTO stanza VALUES('S372','6','Mas mi victoria yace en Ti,<br/>Y en Tu muerte eficaz;<br/>Yo en Tu senda quiero andar,<br/>Hasta la meta en Dios llegar.<br/>',NULL,190342,6);
INSERT INTO stanza VALUES('S372','7','Señor, contigo muerto fui,<br/>¡Qué beneficio recibí!<br/>Más de Tu muerte hazme ver,<br/>Para mi carne así vencer.<br/>',NULL,190343,7);
INSERT INTO stanza VALUES('S372','8','Tal como Tú quiero vencer,<br/>Para así reinar también,<br/>Pues si la cruz llevamos hoy,<br/>Tendremos gloria en Ti, Señor.<br/>',NULL,190344,8);
INSERT INTO stanza VALUES('S373','1','Cuando_en la tierra, Tú Señor,<br/>Tuviste compañía fiel;<br/>Creyeron conocerte bien<br/>Sin entender Tu mismo ser.<br/>',NULL,190345,1);
INSERT INTO stanza VALUES('S373','2','Oyeron muchos Tu hablar,<br/>Tu forma vieron bien aquí;<br/>Te apret´la multitud,<br/>Mas fue sin conocerte_a Ti.<br/>',NULL,190346,2);
INSERT INTO stanza VALUES('S373','3','Igual que ellos, hoy también<br/>Tenemos velos por doquier;<br/>Te conocemos, sin poder<br/>Tu mismo ser en claro ver.<br/>',NULL,190347,3);
INSERT INTO stanza VALUES('S373','4','Mas hoy, como Espíritu,<br/>Eres "otro Consolador";<br/>Ya que_en Tu templo moras Tú,<br/>Revélate_en mi corazón.<br/>',NULL,190348,4);
INSERT INTO stanza VALUES('S373','5','¡Oh, lléname Tu_Espíritu!<br/>¡Sí, llena Tú cada rincón!<br/>Inspira cada parte_así;<br/>Renueva todo_en mí, Señor.<br/>',NULL,190349,5);
INSERT INTO stanza VALUES('S373','6','Revela el Espíritu<br/>Lo que_eres en mi corazón,<br/>Haciendo real dentro de mí<br/>Lo que jamás se percibió.<br/>',NULL,190350,6);
INSERT INTO stanza VALUES('S373','7','Ya que quisiste_hacernos ver<br/>Que eres el Espíritu,<br/>¿Qué a nosotros puede ser<br/>Más real que lo que eres Tú?<br/>',NULL,190351,7);
INSERT INTO stanza VALUES('S373','8','¡Oh, que Tu_Espíritu así<br/>Inunde todo_el corazón!<br/>Haz que Tu gloria brille_en mí;<br/>Satura todo Tú de Dios.<br/>',NULL,190352,8);
INSERT INTO stanza VALUES('S373','9','¡Cuán cerca_estamos Túy yo!<br/>¡Hoy cielo y tierra uno son!<br/>Por Tu presencia_en nuestro ser,<br/>Rebosa_a Ti la_adoración.<br/>',NULL,190353,9);
INSERT INTO stanza VALUES('S374','1','El Padre no se  conoció,<br/>Hasta que vino_en Ti, Señor;<br/>Nuestra_ignorancia ya cesó,<br/>El Padre‿en Ti se reveló.<br/>',NULL,190354,1);
INSERT INTO stanza VALUES('S374','2','Mas cuando anduviste aquí,<br/>Pocos te conocieron bien;<br/>Aún un velo te encubrió,<br/>No te pudieron entender.<br/>',NULL,190355,2);
INSERT INTO stanza VALUES('S374','3','Tal como el Padre vino en Ti,<br/>Viniste como Espíritu;<br/>El Padre en Ti se conoció,<br/>Y Tú, por el Espíritu.<br/>',NULL,190356,3);
INSERT INTO stanza VALUES('S374','4','Hoy en la carne ya no estás,<br/>Con toda su limitación;<br/>Mas como el Espíritu<br/>Te impartes libre al corazón.<br/>',NULL,190357,4);
INSERT INTO stanza VALUES('S374','5','"Padre" una vez se te llamó,<br/>Ahora el Santo Espíritu;<br/>Y como tal en nuestro ser,<br/>Nos llenas con Tu plenitud.<br/>',NULL,190358,5);
INSERT INTO stanza VALUES('S374','6','Como el Espíritu, Señor,<br/>Tu vida das a conocer,<br/>Tu gloria y Tu integridad,<br/>Y Tu maravilloso ser.<br/>',NULL,190359,6);
INSERT INTO stanza VALUES('S374','7','Te alabamos sin cesar,<br/>Con rebosante corazón,<br/>Pues Tú nos eres tan real,<br/>El más hermoso eres, Señor.<br/>',NULL,190360,7);
INSERT INTO stanza VALUES('S375','1','Señor, en carne una vez<br/>Los hombres te pudieron ver;<br/>Mas como el Espíritu<br/>En mí te puedo conocer.<br/>',NULL,190361,1);
INSERT INTO stanza VALUES('S375','2','Te conocí por lo exterior<br/>En carne, como el Redentor;<br/>Mas hoy, como el Espíritu,<br/>Como íntimo Consolador.<br/>',NULL,190362,2);
INSERT INTO stanza VALUES('S375','3','Tú como el Espíritu<br/>Te me revelas sin cesar;<br/>Así en mi espíritu<br/>Conozco hoy Tu realidad.<br/>',NULL,190363,3);
INSERT INTO stanza VALUES('S375','4','Hoy más que aquellos del ayer<br/>Conozco yo Tu vida en mí,<br/>Ya que en la carne estabas Tú<br/>Cuando anduvieron juntó a Ti.<br/>',NULL,190364,4);
INSERT INTO stanza VALUES('S375','5','Por Tu Espíritu en mí,<br/>¡Qué real te haces, oh Señor!<br/>Jamás te vi o conocí,<br/>Mas yo te amo con fervor.<br/>',NULL,190365,5);
INSERT INTO stanza VALUES('S375','6','En mí Tu Santo Espíritu,<br/>Tu mismo ser me impartirá<br/>Como justicia, santidad<br/>Y redención; según Tu plan.<br/>',NULL,190366,6);
INSERT INTO stanza VALUES('S375','7','Tu Espíritu te imparte a mí,<br/>Te une a mi espíritu;<br/>Así soy siempre el mismo yo,<br/>Mas, a la vez, también soy Tú.<br/>',NULL,190367,7);
INSERT INTO stanza VALUES('S376','1','Cantaremos con gozo a Cristo,<br/>Cantaremos desde_el interior;<br/>Nuestro_espíritu canta aleluyas,<br/>Y así nos mezclamos con Dios.<br/>',NULL,190368,1);
INSERT INTO stanza VALUES('S376','2','Muchos años en las religiones,<br/>Mucho tiempo en la mente también,<br/>Muchos años en las emociones,<br/>Los pasamos sin nada obtener.<br/>',NULL,190369,2);
INSERT INTO stanza VALUES('S376','3','Nuestro espíritu ejercitamos,<br/>Nuestra vida es Cristo en verdad;<br/>Nuestro pan es Jesús cada día,<br/>Que nos libra del diario luchar.<br/>',NULL,190370,3);
INSERT INTO stanza VALUES('S376','4','¡Aleluya_en Su_Espíritu_hay vida!<br/>¡Aleluya por tal novedad!<br/>Con la mente al espíritu unida,<br/>Sus riquezas podremos gozar.<br/>',NULL,190371,4);
INSERT INTO stanza VALUES('S377','1','Al acabar Tu obra_aquí,<br/>Tú descansaste en la cruz;<br/>Mas sigues hoy obrando_aún,<br/>Teniendo otra forma Tú.<br/>',NULL,190372,1);
INSERT INTO stanza VALUES('S377','2','Nos muestras salvador poder;<br/>Aún nos hablas, nos das luz;<br/>Muchos a vida llevarás<br/>Por Tu fluyente_Espíritu.<br/>',NULL,190373,2);
INSERT INTO stanza VALUES('S377','3','Por Él aplicas Tu poder;<br/>Por Él no cesas Tú de_obrar;<br/>Nos sigues otorgando paz,<br/>Consuelo, fuerza_y libertad.<br/>',NULL,190374,3);
INSERT INTO stanza VALUES('S377','4','En Su venidad, vienes Tú;<br/>Tu y_el Espíritu_uno son;<br/>Donde_Él habita, habitas Tú,<br/>Pues el Espíritu_eres hoy.<br/>',NULL,190375,4);
INSERT INTO stanza VALUES('S377','5','Él ejecuta en mi ser<br/>El deseo de Tu corazón,<br/>Como_en la tierra_hiciste Tú<br/>Lo que el Padre te mandó.<br/>',NULL,190376,5);
INSERT INTO stanza VALUES('S377','6','Así, por el Espíritu,<br/>Hoy te podemos conocer;<br/>Somos, Señor, llenos de Ti<br/>Cuando Él llena nuestro ser.<br/>',NULL,190377,6);
INSERT INTO stanza VALUES('S377','7','No nos dejaste solos, Tú,<br/>Al irte_al cielo, oh, Señor;<br/>Mas vives en la tierra_aún,<br/>Pues vives en mi corazón.<br/>',NULL,190378,7);
INSERT INTO stanza VALUES('S378','1','Señor, el Espíritu eres hoy<br/>Que vivifica_y vida da;<br/>Nos fortalece Tu caudal,<br/>¡Oh, qué glorioso y divinal!<br/>',NULL,190379,1);
INSERT INTO stanza VALUES('S378','2','Señor, el Espíritu eres hoy<br/>Que nos libera con poder;<br/>Nos trae Tu gran liberación<br/>La ley de vida a nuestro ser.<br/>',NULL,190380,2);
INSERT INTO stanza VALUES('S378','3','Señor, el Espíritu eres hoy<br/>Que transformándonos esta,<br/>Y a Tu imagen con Tu luz<br/>A Ti Él nos conformara.<br/>',NULL,190381,3);
INSERT INTO stanza VALUES('S378','4','Señor, el Espíritu eres hoy<br/>Que habita en mi espíritu;<br/>Mi espíritu se une a Él,<br/>Y uno así los haces Tú.<br/>',NULL,190382,4);
INSERT INTO stanza VALUES('S378','5','Señor, enséñame_a ejercitar<br/>Mi espíritu y en él andar,<br/>A contactar Tu Espíritu<br/>Y así vivir Tu realidad.<br/>',NULL,190383,5);
INSERT INTO stanza VALUES('S379','1','El Espíritu viviente,<br/>Nuestra realidad,<br/>Es Jesús al que‿invocamos<br/>Con simplicidad.<br/>',NULL,190384,1);
INSERT INTO stanza VALUES('S379','chorus','El Espíritu viviente,<br/>Hay que proclamar;<br/>Es Jesús, precioso nombre,<br/>Rico‿al invocar.<br/>',NULL,190385,2);
INSERT INTO stanza VALUES('S379','2','Vive ahora en nosotros,<br/>Dando libertad;<br/>Prueba y ve, no tiene fondo<br/>Su benignidad.<br/>',NULL,190386,3);
INSERT INTO stanza VALUES('S379','3','El Espíritu viviente<br/>Bulle en nuestro ser;<br/>Él es la Palabra viva<br/>Al orar-leer.<br/>',NULL,190387,4);
INSERT INTO stanza VALUES('S379','4','El Espíritu viviente<br/>Hoy fluyendo está;<br/>Por la comunión de vida<br/>Surge la unidad.<br/>',NULL,190388,5);
INSERT INTO stanza VALUES('S379','5','El Espíritu viviente,<br/>¡Qué rico manjar!<br/>En el Cuerpo al disfrutarle,<br/>Se le alabará.<br/>',NULL,190389,6);
INSERT INTO stanza VALUES('S380','1','Cristo_en el testimonio real<br/>De Dios en vida_y proceder;<br/>La gloria de Dios Él mostró<br/>En Su esencia y_en Su ser.<br/>',NULL,190390,1);
INSERT INTO stanza VALUES('S380','2','Su testimonio es mejor<br/>Que_el testimonio de la ley,<br/>Que sólo muestra_en letra_a Dios,<br/>Mas no_el poder viviente de_Él.<br/>',NULL,190391,2);
INSERT INTO stanza VALUES('S380','3','La plenitud de la Deidad<br/>Mora en Él, Su_habitación;<br/>Su residencia_y vaso es;<br/>Coorporifica_al mismo Dios.<br/>',NULL,190392,3);
INSERT INTO stanza VALUES('S380','4','El manifiesta_al Padre Dios,<br/>Muestra los rasgos de Su ser;<br/>Perfectamente_en Él se ve<br/>Su corazón y proceder.<br/>',NULL,190393,4);
INSERT INTO stanza VALUES('S380','5','Cristo como_el Espíritu<br/>Siempre será nuestra porción;<br/>Tomamos en espíritu<br/>Todo su ser en comunión.<br/>',NULL,190394,5);
INSERT INTO stanza VALUES('S381','1','Cristo la centralidad<br/>Y la_universalidad;<br/>Para Dios, Su gozo es,<br/>Su deleite eternal.<br/>',NULL,190395,1);
INSERT INTO stanza VALUES('S381','2','Hoy la plenitud de Dios<br/>Mora_en Él, en Cristo está;<br/>Y respecto a la Deidad,<br/>Es supremo y sin igual.<br/>',NULL,190396,2);
INSERT INTO stanza VALUES('S381','3','Se propuso el mismo Dios<br/>Todo en todo de Él hacer;<br/>Lo terreno o celestial<br/>Todo lo_hizo Dios por Él.<br/>',NULL,190397,3);
INSERT INTO stanza VALUES('S381','4','Todo existe para El,<br/>Todo en El creado fue;<br/>Todo en El subsiste, así<br/>Eje y arco hoy es Él.<br/>',NULL,190398,4);
INSERT INTO stanza VALUES('S381','5','Él es todo en redención,<br/>Todo El reconcilió;<br/>Por Su sangre lo logró,<br/>Trajo todo a paz con Dios.<br/>',NULL,190399,5);
INSERT INTO stanza VALUES('S381','6','Cristo a la iglesia hoy<br/>La Cabeza viva es;<br/>Como Primogénito<br/>De los muertos nació Él.<br/>',NULL,190400,6);
INSERT INTO stanza VALUES('S381','7','En el reino Cristo es Rey,<br/>Él con gloria regirá;<br/>Se le dio todo poder,<br/>Sobre todo reinará.<br/>',NULL,190401,7);
INSERT INTO stanza VALUES('S381','8','Cristo el centro en todo es<br/>Del nuevo orden celestial,<br/>Para el hombre y para Dios,<br/>Por toda la eternidad.<br/>',NULL,190402,8);
INSERT INTO stanza VALUES('S381','9','Preeminencia y todo honor<br/>Quiere Dios a Cristo dar,<br/>Para que Él llegue a ser<br/>Nuestra plena realidad.<br/>',NULL,190403,9);
INSERT INTO stanza VALUES('S382','1','Cristo, la realidad de todo es,<br/>De la Deidad, el hombre_y lo demás;<br/>Sin Él, ninguno puede_hallar a Dios,<br/>Sin Él, el hombre y todo‿es falsedad.<br/>',NULL,190404,1);
INSERT INTO stanza VALUES('S382','2','Los tipos y figuras del ayer,<br/>Todas las cosas que son menester,<br/>Sólo son sombras del Cristo de Dios,<br/>Muestran que todo en todo Él debe ser.<br/>',NULL,190405,2);
INSERT INTO stanza VALUES('S382','3','En este mundo todo es vanidad,<br/>De todo Cristo es la realidad;<br/>Aunque de todo pueda disfrutar,<br/>Si falta Cristo, todo es vaciedad.<br/>',NULL,190406,3);
INSERT INTO stanza VALUES('S382','4','Cristo es mi Dios y mi Señor real,<br/>Cristo es mi vida y mi luz real;<br/>Cristo es comida y bebida real,<br/>Mi vestidura y poder real.<br/>',NULL,190407,4);
INSERT INTO stanza VALUES('S382','5','De toda teología doctrinal,<br/>Cristo es la única realidad;<br/>Conocimiento bíblico, sin Él,<br/>Sólo es letras y es vanidad.<br/>',NULL,190408,5);
INSERT INTO stanza VALUES('S382','6','Cristo, del tiempo es la realidad,<br/>Cristo es del espacio la verdad;<br/>Cristo, de todo es la realidad,<br/>En cada edad y por la eternidad.<br/>',NULL,190409,6);
INSERT INTO stanza VALUES('S383','1','Gracia, en su mayor definición<br/>Es Dios en Cristo siendo mi porción;<br/>No sólo_es algo hecho_a mi favor,<br/>Sino Dios mismo como bendición.<br/>',NULL,190410,1);
INSERT INTO stanza VALUES('S383','2','Dios se_encarnó para que pueda yo,<br/>Hoy recibirle en Su realidad;<br/>Esta es la gracia que viene de Dios,<br/>La cual es Cristo en Su_humanidad.<br/>',NULL,190411,2);
INSERT INTO stanza VALUES('S383','3','Pablo, el apóstol, no consideró<br/>Más que a Cristo, la gracia de Dios;<br/>Por esta gracia se fortaleció,<br/>Y en la carrera, a todos pasó.<br/>',NULL,190412,3);
INSERT INTO stanza VALUES('S383','4','Basta la gracia, suficiente es,<br/>Cristo en nosotros: fuerza y vigor;<br/>En nuestro espíritu la gracia está<br/>Energizando, obrando el plan de Dios.<br/>',NULL,190413,4);
INSERT INTO stanza VALUES('S383','5','El Cristo vivo esta gracia es,<br/>La necesito experimentar;<br/>Que pueda yo la gracia conocer,<br/>Y en mi vivir, a Cristo realizar.<br/>',NULL,190414,5);
INSERT INTO stanza VALUES('S384','1','Ésta_es mi gloriosa historia<br/>Cristo en mi entró;<br/>Cristo, el Rey de la gloria,<br/>Vive_en mi corazón.<br/>',NULL,190415,1);
INSERT INTO stanza VALUES('S384','chorus','Cristo‿en mí, Cristo‿en mí,<br/>Cristo en‿mí, ¡qué gloriosa‿historia!<br/>Cristo‿en mí, Cristo en mí,<br/>Cristo_es mi esperanza de gloria.<br/>',NULL,190416,2);
INSERT INTO stanza VALUES('S384','2','¡Qué historia conmovedora<br/>De pena y amor!<br/>Nunca se oyó de tal Novio<br/>Que gane_el corazón.<br/>',NULL,190417,3);
INSERT INTO stanza VALUES('S384','3','¡Cuánto me alegro tenerlo,<br/>Rey de mi corazón!<br/>Antes yo le contristaba,<br/>Hoy le sirvo en amor.<br/>',NULL,190418,4);
INSERT INTO stanza VALUES('S384','4','¿Cómo sentirme tan solo?<br/>¿Cómo podría caer?<br/>¿Qué más podría pedir yo,<br/>Si todo_en todo es Él?<br/>',NULL,190419,5);
INSERT INTO stanza VALUES('S384','5','Hoy en Su seno, confiando,<br/>Tengo dulce canción;<br/>En mí habita hoy Cristo,<br/>Y_Él es mi_habitación.<br/>',NULL,190420,6);
INSERT INTO stanza VALUES('S385','1','¡Oh, qué vivir! ¡Oh, qué solaz!<br/>Pues Cristo vive hoy en mí.<br/>Yo en la cruz con Él estoy,<br/>Tal hecho_en El yo recibí.<br/>Ahora ya no vivo yo,<br/>Mas el Señor hoy vive_en mí.<br/>Ahora ya no vivo yo,<br/>Mas el Señor hoy vive_en mí.<br/>',NULL,190421,1);
INSERT INTO stanza VALUES('S385','2','¡Oh, qué confiar! ¡Oh, qué gozar!<br/>Se está formando Cristo en mí.<br/>Su vida divinal está<br/>Forjándose ahora en mí.<br/>//Lo que soy yo se terminó,<br/>Y Cristo es todo para mí.//<br/>',NULL,190422,2);
INSERT INTO stanza VALUES('S385','3','¡Oh, qué gloriar! ¡Oh qué pensar!<br/>Se hace magno Cristo en mí.<br/>Avergonzado no seré,<br/>Pues yo lo aplico en mi vivir.<br/>//En vida o muerte, bien o mal,<br/>A Cristo tengo que expresar.//<br/>',NULL,190423,3);
INSERT INTO stanza VALUES('S385','4','¡Oh, qué premiar! ¡Oh, qué ganar!<br/>Mi meta sólo en Cristo está.<br/>Ningún tesoro deseo yo,<br/>Mas Cristo en Su totalidad.<br/>//Mi Cristo es mi galardón,<br/>Mi gloria y premio sin igual.//<br/>',NULL,190424,4);
INSERT INTO stanza VALUES('S386','1','¡Oh, qué poder! Oh, qué vigor!<br/>A Cristo, Dios resucitó.<br/>Dios a Su diestra lo sentó,<br/>Y por Cabeza lo_otorgó.<br/>Tal poder a la‿iglesia dio,<br/>Para‿aplastar al tentador.<br/>Tal poder a la‿iglesia dio,<br/>Para‿aplastar al tentador.<br/>',NULL,190425,1);
INSERT INTO stanza VALUES('S386','2','¡Qué realidad! ¡Qué gozo es!<br/>¡De Cristo soy un miembro yo!<br/>Compenetrados en unión,<br/>El nuevo hombre somos hoy.<br/>//Con la Cabeza en ascensión,<br/>La iglesia cumple Su intención.//<br/>',NULL,190426,2);
INSERT INTO stanza VALUES('S386','3','¡Oh, qué anchura y longitud!<br/>¡La altura! ¡La profundidad!<br/>Cristo el Señor inmenso es,<br/>Ilimitado en vastedad.<br/>//Todo lo suyo, más Su ser,<br/>Es nuestra vida en verdad.//<br/>',NULL,190427,3);
INSERT INTO stanza VALUES('S387','1','Oh Cristo, mi buen Salvador,<br/>En verdad, radiante divino;<br/>El infinito,_eterno Dios,<br/>Finito en tiempo, se‿humanó.<br/>',NULL,190428,1);
INSERT INTO stanza VALUES('S387','chorus','¡Oh, Cristo del gran Dios: la‿expresión!<br/>¡Abundante, muy rico es Él!<br/>Dios mezclado con humanidad<br/>Vive‿en mí, mi todo_es Él.<br/>',NULL,190429,2);
INSERT INTO stanza VALUES('S387','2','En Ti mora la plenitud<br/>Del gran Dios y_expresas Su gloria;<br/>Hiciste en carne redención,<br/>Y, como Espíritu, la unión.<br/>',NULL,190430,3);
INSERT INTO stanza VALUES('S387','3','El Padre Su todo te dio,<br/>En Espíritu te tomamos,<br/>Por el Espíritu en mí,<br/>Yo te experimento así.<br/>',NULL,190431,4);
INSERT INTO stanza VALUES('S387','4','Es por Tu Palabra eficaz<br/>Que el Espíritu me da vida;<br/>Tocándola recibiré<br/>Tu misma esencia en mi ser.<br/>',NULL,190432,5);
INSERT INTO stanza VALUES('S387','5','Te miro en mi espíritu hoy<br/>Y Tu gloria voy reflejando;<br/>Yo transformado así seré,<br/>Tu imagen pura expresaré.<br/>',NULL,190433,6);
INSERT INTO stanza VALUES('S387','6','No hay otra forma de ser<br/>Victorioso y santificado,<br/>Pues por Tu gloria divinal,<br/>Tu vida me hace espiritual.<br/>',NULL,190434,7);
INSERT INTO stanza VALUES('S387','7','Tu Espíritu me impregnará,<br/>Saturando Dios cada parte;<br/>Librándonos del viejo Adán,<br/>Podrás Tu iglesia edificar.<br/>',NULL,190435,8);
INSERT INTO stanza VALUES('S388','1','Muerto‿en el mundo‿atroz<br/>Yo‿andaba‿en confusión;<br/>Mas ya con Cristo‿estoy<br/>Al mundo, muerto yo.<br/>',NULL,190436,1);
INSERT INTO stanza VALUES('S388','chorus','¿Y puede ser que Él me‿amó<br/>Y que por mí murió?<br/>¿Y puede ser que Él me‿amó<br/>Y que por mí murió?<br/>',NULL,190437,2);
INSERT INTO stanza VALUES('S388','2','Su altura, ¿quién dirá?<br/>¿Cuán hondo? No lo sé.<br/>Oh, infinito amor<br/>El que en Cristo hallé.<br/>',NULL,190438,3);
INSERT INTO stanza VALUES('S388','3','Hoy ya no vivo yo,<br/>Mas vive Cristo en mí.<br/>De muerte me libró<br/>Y del pecado vil.<br/>',NULL,190439,4);
INSERT INTO stanza VALUES('S389','1','Al Cristo vivo sirvo,<br/>Hoy con Su pueblo_está;<br/>Aunque_otros lo negaren,<br/>Yo sé que_Él vive ya.<br/>Su mano tierna veo,<br/>Su voz, consuelo da,<br/>Y cuando yo lo llamo,<br/>Muy cerca_está.<br/>',NULL,190440,1);
INSERT INTO stanza VALUES('S389','chorus','¡Él vive, Él vive!<br/>¡Hoy vive el Salvador!<br/>¡Conmigo está y me guardará,<br/>Mi amante Redentor!<br/>¡Él vive, Él vive!<br/>Me_imparte salvación;<br/>Sé que_Él viviendo está porque<br/>Vive_en mi corazón.<br/>',NULL,190441,2);
INSERT INTO stanza VALUES('S389','2','En torno a mí yo veo,<br/>Su protección de amor,<br/>Y aunque yo me canse,<br/>Me afirma el Salvador.<br/>En medio de tormentas,<br/>Me viene a guiar,<br/>Y pronto Su presencia<br/>Todos verán.<br/>',NULL,190442,3);
INSERT INTO stanza VALUES('S389','3','¡Regocijaos, cristianos,<br/>¡Hoy himnos entonad!<br/>¡Eternos aleluyas,<br/>A Cristo el Rey cantad!<br/>Socorro y esperanza,<br/>Al que lo busca da,<br/>No hay otro tan amante,<br/>En quien confiar.<br/>',NULL,190443,4);
INSERT INTO stanza VALUES('S390','1','Hay un Hombre‿en la gloria,<br/>Su vida‿es para mí,<br/>Es puro y santo,<br/>Triunfante también.<br/>Es sabio,‿amoroso,<br/>¡Cuán tierno es Él!<br/>Su vida en la gloria<br/>Mi vida debe ser;<br/>Su vida en la gloria<br/>Mi vida debe ser.<br/>',NULL,190444,1);
INSERT INTO stanza VALUES('S390','2','Hay un Hombre‿en la gloria,<br/>Su vida‿es para mí,<br/>Venció Él al diablo<br/>Y libre hoy es.<br/>En vida Él reina,<br/>¡Cuán regio es Él!<br/>Su vida en la gloria<br/>Mi vida debe ser;<br/>Su vida en la gloria<br/>Mi vida debe ser.<br/>',NULL,190445,2);
INSERT INTO stanza VALUES('S390','3','Hay un Hombre‿en la gloria,<br/>Su vida‿es para mí,<br/>Sin enfermedades<br/>Ni debilidad.<br/>Es bien vigoroso,<br/>¡Cuán fuerte es Él!<br/>Su vida en la gloria<br/>Mi vida puede ser;<br/>Su vida en la gloria<br/>Mi vida puede ser.<br/>',NULL,190446,3);
INSERT INTO stanza VALUES('S390','4','Hay un Hombre‿en la gloria,<br/>Su vida‿es para mí,<br/>Su paz permanece,<br/>Paciente es Él.<br/>Radiante‿y gozoso,<br/>Espera poder ver<br/>Su vida en la gloria<br/>Vivida en mi ser;<br/>Su vida en la gloria<br/>Vivida en mi ser.<br/>',NULL,190447,4);
INSERT INTO stanza VALUES('S391','1','Vivía lejos yo de Dios,<br/>Muerto‿y sin luz en mí;<br/>Pero‿en la Biblia luz hallé,<br/>Hoy Cristo vive en mí.<br/>',NULL,190448,1);
INSERT INTO stanza VALUES('S391','chorus','¡Cristo vive en mí!<br/>¡Cristo vive en mí!<br/>¡Oh, qué grande salvación,<br/>Que Cristo viva en mí!<br/>',NULL,190449,2);
INSERT INTO stanza VALUES('S391','2','Tal como aquella luz de sol<br/>Que libera la flor,<br/>Amor y vida han de brotar<br/>Del Cristo que vive en mí.<br/>',NULL,190450,3);
INSERT INTO stanza VALUES('S391','3','Como en el cono un árbol hay,<br/>Y en la semilla, flor,<br/>Así a Cristo alabo yo;<br/>Su Espíritu mora en mí.<br/>',NULL,190451,4);
INSERT INTO stanza VALUES('S391','4','Anhela todo el corazón<br/>Ser como mi Señor,<br/>Al contemplar la realidad<br/>Que Cristo vive en mí.<br/>',NULL,190452,5);
INSERT INTO stanza VALUES('S392','1','Ya libre, oh cautivo,<br/>De‿aquella‿inicua ley,<br/>La ley de vida‿opera<br/>Vivificándote.<br/>Su‿Espíritu de vida<br/>Así controlará<br/>Los miembros de tu cuerpo,<br/>Que‿a tu‿alma son portal.<br/>',NULL,190453,1);
INSERT INTO stanza VALUES('S392','2','¡Ya libre en Jesucristo!<br/>Crucificado en Él,<br/>Del centro hasta la esfera<br/>Rompe el pecado cruel.<br/>No actúes en la carne<br/>Sin frenos y sin ley;<br/>La ley de vida frena<br/>Lo que indomable fue.<br/>',NULL,190454,2);
INSERT INTO stanza VALUES('S392','3','¡Ya libre en Jesucristo!<br/>En la muerte con Él;<br/>Su Espíritu libera<br/>Su vida y Su poder.<br/>Mi espíritu con vida<br/>Se fortalecerá;<br/>El alma gobernada<br/>Y el cuerpo paz tendrán.<br/>',NULL,190455,3);
INSERT INTO stanza VALUES('S392','4','¡Ya libre en Jesucristo!<br/>Con Él en ascensión,<br/>Reclama Su victoria<br/>Y triunfo en oración.<br/>Por Su vida gloriosa<br/>Tienes la libertad<br/>Sobre la ley de muerte<br/>Que en el pecado está.<br/>',NULL,190456,4);
INSERT INTO stanza VALUES('S393','1','¡Gloria! ¡Gloria! Cristo_es vida_en mí.<br/>Como_Espíritu guiando_está;<br/>Cambia noche_en día, fuerza_al débil da,<br/>¡Gloria! ¡Gloria! Cristo reina ya.<br/>',NULL,190457,1);
INSERT INTO stanza VALUES('S393','2','¡Gloria! ¡Gloria! Vivo en el Señor,<br/>¡Gloria! Su Palabra sigo en pos;<br/>Triunfo en el fracaso, canto en el dolor,<br/>¡Gloria! ¡Gloria! Vivo en el Señor.<br/>',NULL,190458,2);
INSERT INTO stanza VALUES('S394','1','El río y el árbol son<br/>Figuras cumbres del Edén;<br/>Al hombre dan con su suplir<br/>Un eternal sostén.<br/>',NULL,190459,1);
INSERT INTO stanza VALUES('S394','chorus','Dios está_en Cristo para suplir,<br/>Como el_Espíritu nutre Él;<br/>Si me_alimento de Cristo yo,<br/>Lleno de Él seré.<br/>',NULL,190460,2);
INSERT INTO stanza VALUES('S394','2','El árbol muestra a Cristo hoy<br/>Como una viva provisión<br/>Que brinda al hombre el rico Dios<br/>Para satisfacción.<br/>',NULL,190461,3);
INSERT INTO stanza VALUES('S394','3','El río del Espíritu<br/>Al hombre viene en Su fluir;<br/>Le trae a Dios en Su caudal<br/>Para ser su suplir.<br/>',NULL,190462,4);
INSERT INTO stanza VALUES('S394','4','Como el Espíritu en mi ser,<br/>Vive el glorioso Cristo hoy,<br/>Para Su imagen expresar<br/>Me mezcla Él con Dios.<br/>',NULL,190463,5);
INSERT INTO stanza VALUES('S394','5','A este Cristo exaltaré,<br/>Su gloria dando a conocer,<br/>Sumiso al Espíritu,<br/>Lleno de gracia y fe.<br/>',NULL,190464,6);
INSERT INTO stanza VALUES('S395','1','El árbol de la vida_es Dios,<br/>Su fruto me sació.<br/>Yo muerto fui, mas vivo hoy,<br/>Hambriento ya no_estoy.<br/>',NULL,190465,1);
INSERT INTO stanza VALUES('S395','2','Al árbol me llevó mi Dios,<br/>Do Cristo el fruto es;<br/>Preciado me llegó a ser,<br/>Cuando empecé_a comer.<br/>',NULL,190466,2);
INSERT INTO stanza VALUES('S395','3','Mi alimento es Jesús,<br/>Mi suministro real,<br/>Es mi total satisfacción<br/>Y eterna provisión.<br/>',NULL,190467,3);
INSERT INTO stanza VALUES('S395','4','Del árbol vivo como yo<br/>Con plena libertad;<br/>Por el comer yo puedo hoy<br/>Vivir así por Dios.<br/>',NULL,190468,4);
INSERT INTO stanza VALUES('S396','1','En la Biblia se ve con claridad<br/>Que Dios a Su_imagen nos creó<br/>Para sojuzgar, dominio expresar<br/>Y llevar a cabo_el plan de Dios.<br/>',NULL,190469,1);
INSERT INTO stanza VALUES('S396','chorus','A Su_imagen,<br/>Dios a Su imagen nos creó.<br/>A Su_imagen,<br/>Para_así cumplir lo que_Él planeó.<br/>',NULL,190470,2);
INSERT INTO stanza VALUES('S396','2','No dio instrucción, sólo dijo que<br/>"Todo árbol es para comer,<br/>Pero_el de la ciencia del bien y_el mal<br/>Lleva_a muerte, ¡no comas de él!<br/>',NULL,190471,3);
INSERT INTO stanza VALUES('S396','chorus','Ciencia, ciencia,<br/>Ese fruto no_es para comer.<br/>Ciencia, ciencia,<br/>Ese fruto te hará perder.<br/>',NULL,190472,4);
INSERT INTO stanza VALUES('S396','3','Bello_el huerto es y allí se ve<br/>Dios como_árbol de la vida_en él;<br/>Pero Satanás entra a tentar,<br/>Y al hombre_el otro árbol da.<br/>',NULL,190473,5);
INSERT INTO stanza VALUES('S396','chorus','Ha caído,<br/>De la muerte_el hombre se llenó.<br/>Ha caído,<br/>Recobrado debe ser por Dios.<br/>',NULL,190474,6);
INSERT INTO stanza VALUES('S396','4','Mas vino Jesús con brillante luz;<br/>Cristo_el árbol de la vida es.<br/>Lo que Dios mandó, Cristo lo cumplió;<br/>Nos compró y se nos dio_a comer.<br/>',NULL,190475,7);
INSERT INTO stanza VALUES('S396','chorus','Jesucristo<br/>La comida verdadera es.<br/>Jesucristo,<br/>De_Él se puede comer y beber.<br/>',NULL,190476,8);
INSERT INTO stanza VALUES('S396','5','Nunca fue su fin la mente nutrir;<br/>Toda ciencia envanecerá.<br/>Vino para ser nuestra cena Él,<br/>¡Come_a Cristo sin analizar!<br/>',NULL,190477,9);
INSERT INTO stanza VALUES('S396','chorus','Toma_a Cristo,<br/>Tómalo y te satisfará.<br/>Toma_a Cristo,<br/>Árbol de la vida_es en verdad.<br/>',NULL,190478,10);
INSERT INTO stanza VALUES('S396','6','Comer al Señor en la comunión<br/>Nos trae vida_y multiplicación.<br/>Hay que entender que_el recobro es<br/>Un banquete, no_una religión.<br/>',NULL,190479,11);
INSERT INTO stanza VALUES('S396','chorus','Come, come,<br/>Come_a Cristo_en tu necesidad.<br/>Come, come,<br/>Si lo comes, por Él vivirás.<br/>',NULL,190480,12);
INSERT INTO stanza VALUES('S396','7','Al comer de Él, nuestra vida es;<br/>El comer nunca ha de faltar.<br/>La_iglesia,_al comer, completa_ha de ser;<br/>De_esta forma_el Novio volverá.<br/>',NULL,190481,13);
INSERT INTO stanza VALUES('S396','chorus','Come, come,<br/>El comer nunca ha de faltar.<br/>Come, come,<br/>De_esta forma_el Novio volverá.<br/>',NULL,190482,14);
INSERT INTO stanza VALUES('S397','1','Su Hijo_a todo hombre, Dios,<br/>Cómo_árbol de la vida dio,<br/>Para que pruebe_y vea hoy<br/>Que Dios comida es.<br/>',NULL,190483,1);
INSERT INTO stanza VALUES('S397','chorus','¡Sí, Dios comida es!<br/>¡Sí, Dios comida es!<br/>Probamos y muy cierto es,<br/>¡Que Dios comida es!<br/>',NULL,190484,2);
INSERT INTO stanza VALUES('S397','2','Es nuestro Dios rico manjar,<br/>Comiendo de Él, nos sostendrá;<br/>Así el hombre vivirá<br/>Por este rico Dios.<br/>',NULL,190485,3);
INSERT INTO stanza VALUES('S397','chorus','¡Jesús, oh qué manjar!<br/>¡Jesús, oh qué manjar!<br/>Por Él vivimos al comer,<br/>¡Jesús, oh qué manjar!<br/>',NULL,190486,4);
INSERT INTO stanza VALUES('S397','3','Jesús nuestra comida es,<br/>Él es el pan: nos nutre Él;<br/>Su vida imparte a nuestro ser<br/>Comiendo a diario de Él.<br/>',NULL,190487,5);
INSERT INTO stanza VALUES('S397','chorus','Comiendo a diario de Él,<br/>Comiendo a diario de Él,<br/>Su vida imparte a nuestro ser<br/>Comiendo a diario de Él.<br/>',NULL,190488,6);
INSERT INTO stanza VALUES('S397','4','¡Qué disfrutable es tal festín!<br/>Y Dios lo ofrece hoy a ti,<br/>Pues nos invita a comer<br/>Gratuitamente de Él.<br/>',NULL,190489,7);
INSERT INTO stanza VALUES('S397','chorus','Gratuitamente de Él,<br/>Gratuitamente de Él,<br/>Dios nos invita a comer<br/>Gratuitamente de Él.<br/>',NULL,190490,8);
INSERT INTO stanza VALUES('S398','1','Comamos siempre a Jesús,<br/>Pues en Su carne hay virtud;<br/>En pruebas Él así será<br/>Un Hombre que  nos   sostendrá.<br/>',NULL,190491,1);
INSERT INTO stanza VALUES('S398','chorus','¡Más de Jesús come!<br/>¡Más de Jesús come!<br/>¿Por qué sufrir debilidad,<br/>Cuando_Él nos da Su_humanidad?<br/>',NULL,190492,2);
INSERT INTO stanza VALUES('S398','2','Bebiendo a Jesús podré<br/>"Jesusmente" humano ser;<br/>Y fluirán los ríos que<br/>Calmen la sed que_hay por doquier.<br/>',NULL,190493,3);
INSERT INTO stanza VALUES('S398','chorus','¡Más de Jesús bebe!<br/>¡Más de Jesús bebe!<br/>Por qué vivir en sequedad<br/>Cuando_Él nos da Su_humanidad?<br/>',NULL,190494,4);
INSERT INTO stanza VALUES('S398','3','Más de Jesús hay que comer<br/>Para que Dios pueda obtener<br/>El nuevo hombre en realidad,<br/>La iglesia en la localidad.<br/>',NULL,190495,5);
INSERT INTO stanza VALUES('S398','chorus','¡Lo masticaremos!<br/>¡Lo masticaremos!<br/>Para traer la oblación<br/>De flor de_harina_a la reunión.<br/>',NULL,190496,6);
INSERT INTO stanza VALUES('S399','1','"¡A comer!" Jesús nos llama:<br/>"¡A comer!"<br/>De Jesús podemos comer y beber;<br/>Brinda diaria provisión,<br/>Y total satisfacción,<br/>"¡A comer!" Jesús nos llama:<br/>"¡A comer!"<br/>',NULL,190497,1);
INSERT INTO stanza VALUES('S399','2','"¡A comer!" Jesús nos llama,<br/>"¡A comer!"<br/>Si comemos y bebemos siempre de Él,<br/>Él nos llena en verdad<br/>Con Su misma realidad,<br/>"¡A comer!" Jesús nos llama:<br/>"¡A comer!"<br/>',NULL,190498,2);
INSERT INTO stanza VALUES('S400','1','Brotó de Él gracia‿y verdad<br/>Bebemos en la fuente;<br/>A este Cristo_hay que‿alabar<br/>En la_iglesia, Su_hogar.<br/>',NULL,190499,1);
INSERT INTO stanza VALUES('S400','chorus','¡Gloria a Dios! ¡Bebemos en la fuente!<br/>¡Gloria a Dios! La_iglesia es nuestro hogar.<br/>',NULL,190500,2);
INSERT INTO stanza VALUES('S400','2','Su gracia se halla al invocar,<br/>Bebemos en la fuente;<br/>Mejor que el cielo, a Él buscad,<br/>Lo encuentras en Su hogar.<br/>',NULL,190501,3);
INSERT INTO stanza VALUES('S400','3','Aunque luchando el diablo está,<br/>Bebemos en la fuente;<br/>El no podrá jamás triunfar<br/>En contra de este hogar.<br/>',NULL,190502,4);
INSERT INTO stanza VALUES('S400','4','La sed nos trae al manantial,<br/>Bebemos en la fuente;<br/>Tal pozo no se agotará,<br/>Aquí en nuestro hogar.<br/>',NULL,190503,5);
INSERT INTO stanza VALUES('S401','1','Hoy comemos del viviente pan,<br/>Y bebemos en el manantial;<br/>Dijo Cristo quien beba de Él,<br/>Nunca, nunca tendrá más sed.<br/>',NULL,190504,1);
INSERT INTO stanza VALUES('S401','chorus','¿Qué, no tendrá más sed?<br/>¡No, no tendrá más sed!<br/>¿Qué, no tendrá más sed?<br/>¡No, no tendrá más sed!<br/>Dijo Cristo quien beba de Él,<br/>Nunca, nunca tendrá más sed.<br/>',NULL,190505,2);
INSERT INTO stanza VALUES('S401','2','Hoy comemos del viviente pan,<br/>De Jesús, quien es nuestro manjar;<br/>Dijo Él: "Quien coma de este pan,<br/>Nunca más hambre él tendrá".<br/>',NULL,190506,3);
INSERT INTO stanza VALUES('S401','chorus','¿Qué, hambre no tendrá?<br/>¡No, hambre no tendrá!<br/>¿Qué, hambre no tendrá?<br/>¡No, hambre no tendrá!<br/>Dijo Él: "Quien coma de este pan,<br/>Nunca más hambre él tendrá".<br/>',NULL,190507,4);
INSERT INTO stanza VALUES('S401','3','Respiramos aire divinal<br/>Esa vida que es sin igual;<br/>Y aquel que respire obtendrá<br/>La vida eternal de Dios.<br/>',NULL,190508,5);
INSERT INTO stanza VALUES('S401','chorus','¿Qué, la vida eternal?<br/>¡Sí, la vida eternal!<br/>¿Qué, la vida eternal?<br/>¡Sí, la vida eternal!<br/>Y aquel que respire obtendrá<br/>La vida eternal de Dios.<br/>',NULL,190509,6);
INSERT INTO stanza VALUES('S401','4','Disfrutamos vino celestial<br/>Al probar la vida divinal;<br/>Y aquel que pruebe así tendrá<br/>El gozo celestial de Dios.<br/>',NULL,190510,7);
INSERT INTO stanza VALUES('S401','chorus','¿Qué, gozo celestial?<br/>¡Sí, gozo celestial!<br/>¿Qué, gozo celestial?<br/>¡Sí, gozo celestial!<br/>Y aquel que pruebe así tendrá<br/>El gozo celestial de Dios.<br/>',NULL,190511,8);
INSERT INTO stanza VALUES('S401','5','Cristo el resucitado Rey,<br/>Nuestro Redentor y vida es;<br/>Si lo recibes cantarás<br/>Y Tú por siempre vivirás.<br/>',NULL,190512,9);
INSERT INTO stanza VALUES('S401','chorus','¿Qué, por siempre viviré?<br/>¡Sí, por siempre vivirás!<br/>¿Qué, por siempre viviré?<br/>¡Sí, por siempre vivirás!<br/>Si lo recibes cantarás<br/>Y tú por siempre vivirás.<br/>',NULL,190513,10);
INSERT INTO stanza VALUES('S402','1','¡Bebe! Fluye‿un río desde‿el trono del Señor;<br/>¡Come!‿El árbol de la vida con sus frutos hoy;<br/>¡Mira!‿Aquí no‿hay sol ni luna‿o luz artificial,<br/>Pues ¡No‿hay oscuridad!<br/>',NULL,190514,1);
INSERT INTO stanza VALUES('S402','chorus','Oh, ven y bebe,<br/>Hay agua‿en plenitud;<br/>Dicen la novia<br/>Y el Espíritu;<br/>Oh, ven y bebe,<br/>Hasta tu sed calmar<br/>Con agua de vida‿eternal.<br/>',NULL,190515,2);
INSERT INTO stanza VALUES('S402','2','Cristo‿el río, Cristo‿el agua, fluye‿en lo‿interior;<br/>Cristo‿el árbol, Cristo‿el fruto‿es nuestro gozo hoy;<br/>Cristo‿el día, Cristo‿el brillo, Cristo‿el resplandor,<br/>¡Cristo‿es lo mejor!<br/>',NULL,190516,3);
INSERT INTO stanza VALUES('S402','3','Hoy lavamos nuestras ropas para‿así comer,<br/>De‿ese árbol de la vida, ¡Aleluya! ¡Amén!<br/>Cuando ejercitamos nuestro‿espíritu se ve<br/>¡Cuán Dulce Cristo es!<br/>',NULL,190517,4);
INSERT INTO stanza VALUES('S402','4','Ya tenemos un hogar que brilla más que‿el sol,<br/>Donde‿en armonía los hermanos uno son;<br/>Al reunirnos como‿iglesia se muestra‿al Señor<br/>En la localidad.<br/>',NULL,190518,5);
INSERT INTO stanza VALUES('S403','1','Hallé a_Aquel que_es sin igual,<br/>Me llena el corazón;<br/>Por eso tengo que cantar,<br/>¡Qué Cristo tengo yo!<br/>',NULL,190519,1);
INSERT INTO stanza VALUES('S403','2','Mi Cristo es el Cordero fiel,<br/>Me trae la salvación;<br/>El Sol de la Justicia es,<br/>Que sana el corazón.<br/>',NULL,190520,2);
INSERT INTO stanza VALUES('S403','3','El Arbol de la vida es Él,<br/>Con frutos a granel;<br/>Mi hambre satisfecha está,<br/>A diario como de Él.<br/>',NULL,190521,3);
INSERT INTO stanza VALUES('S403','4','La Roca herida Cristo es,<br/>Do brotan sin cesar<br/>Las aguas vivas en mi ser,<br/>Para mi sed saciar.<br/>',NULL,190522,4);
INSERT INTO stanza VALUES('S403','5','Mi Cristo es mi vida y paz,<br/>Mi gozo y mi luz;<br/>Mi esperanza y gloria es,<br/>Consuelo y salud.<br/>',NULL,190523,5);
INSERT INTO stanza VALUES('S403','6','Mi Cristo, mi prudencia es,<br/>Jactancia y virtud;<br/>Es mi victoria y santidad,<br/>Verdad y rectitud.<br/>',NULL,190524,6);
INSERT INTO stanza VALUES('S403','7','Mi Cristo es mi Salvador,<br/>Pastor y Defensor;<br/>Mi Consejero, Padre y Dios,<br/>Mi Hermano y mi Amor.<br/>',NULL,190525,7);
INSERT INTO stanza VALUES('S403','8','Mi Cristo es mi Capitán,<br/>Cabeza y Señor;<br/>Mi Guía, Amo y Novio es;<br/>En mí reside hoy.<br/>',NULL,190526,8);
INSERT INTO stanza VALUES('S403','9','Mi Cristo es Profeta y Rey,<br/>Mi Sacerdote fiel;<br/>Por mí intercediendo está,<br/>Y rige con poder.<br/>',NULL,190527,9);
INSERT INTO stanza VALUES('S403','10','Mi Cristo es mi Fiador,<br/>Testigo y Mediador;<br/>El de mi fe es el Autor<br/>Y su Consumador.<br/>',NULL,190528,10);
INSERT INTO stanza VALUES('S403','11','Mi Cristo es mi eterno hogar,<br/>Mi tierra de Canaán;<br/>Mi torre y refugio es,<br/>Firmeza eternal.<br/>',NULL,190529,11);
INSERT INTO stanza VALUES('S403','12','Mi luna nueva Cristo es,<br/>Mi Sábado también;<br/>Mi Cristo es mi eternidad,<br/>Mi alba y día es.<br/>',NULL,190530,12);
INSERT INTO stanza VALUES('S403','13','Mi Cristo, mi deseo es<br/>Y mi satisfacción;<br/>Su hermosura sin igual<br/>Me llena el corazón.<br/>',NULL,190531,13);
INSERT INTO stanza VALUES('S403','14','Mi Cristo, todo incluye El,<br/>¿Qué más le llamaré?<br/>Primero último es Él,<br/>El Todo en todo es.<br/>',NULL,190532,14);
INSERT INTO stanza VALUES('S403','15','Por tal tesoro en mi ser,<br/>Rebosa el corazón;<br/>Por esto canto_y cantaré,<br/>¡Qué Cristo tengo yo!<br/>',NULL,190533,15);
INSERT INTO stanza VALUES('S404','1','Lo más querido es,<br/>Al que yo amo más;<br/>Lo debemos buscar,<br/>Y siempre en Él confiar.<br/>',NULL,190534,1);
INSERT INTO stanza VALUES('S404','2','Oportuna ayuda,<br/>Mi socorro es Él;<br/>Bello de bellos es,<br/>Él permanece fiel.<br/>',NULL,190535,2);
INSERT INTO stanza VALUES('S404','3','Gozo sin fin es Él,<br/>Todo cambia, Él no;<br/>Lo más querido es,<br/>A quien más amo yo.<br/>',NULL,190536,3);
INSERT INTO stanza VALUES('S405','1','Gozo de gozos es,<br/>Mi sed Él ya sació;<br/>Canto de cantos, Él,<br/>Mi soledad quitó.<br/>',NULL,190537,1);
INSERT INTO stanza VALUES('S405','2','Bello de bellos es,<br/>Satisfacción total;<br/>Noble de nobles, Él,<br/>Mi premio sin igual.<br/>',NULL,190538,2);
INSERT INTO stanza VALUES('S405','3','Vida de vidas es,<br/>Él me vivificó;<br/>Santo de santos, Él,<br/>Del mundo me apartó.<br/>',NULL,190539,3);
INSERT INTO stanza VALUES('S405','4','Justo de justos es,<br/>Me hace firme estar;<br/>Fuerza de fuerzas, Él,<br/>Refresca al caminar.<br/>',NULL,190540,4);
INSERT INTO stanza VALUES('S405','5','Triunfo de triunfos es,<br/>Que vence todo mal;<br/>Lo más potente, Él,<br/>Renueva sin cesar.<br/>',NULL,190541,5);
INSERT INTO stanza VALUES('S405','6','Fuerte de fuertes es,<br/>Me vigorizará;<br/>El más capaz es Él,<br/>Mi ser podrá librar.<br/>',NULL,190542,6);
INSERT INTO stanza VALUES('S405','7','Rey de los reyes es,<br/>Reina en mi corazón;<br/>Luz de las luces, Él,<br/>Alumbra mi interior.<br/>',NULL,190543,7);
INSERT INTO stanza VALUES('S405','8','Señor de señores,<br/>Hoy vive en mi ser;<br/>Senda de sendas es,<br/>Mis pasos guía Él.<br/>',NULL,190544,8);
INSERT INTO stanza VALUES('S405','9','Don de los dones es,<br/>Sana todo mi ser;<br/>Magno de magnos, Él,<br/>Me ha de enaltecer.<br/>',NULL,190545,9);
INSERT INTO stanza VALUES('S405','10','Fiel de los fieles, Él,<br/>Guarda mi corazón;<br/>Premio de premios es,<br/>Me guía con amor.<br/>',NULL,190546,10);
INSERT INTO stanza VALUES('S405','11','Amor de amores,<br/>Digno de mi favor;<br/>Manso de mansos, Él,<br/>Merece todo honor.<br/>',NULL,190547,11);
INSERT INTO stanza VALUES('S405','12','Él lo más grande es,<br/>Inspira admiración;<br/>Gloria de glorias, Él,<br/>Ganó mi adoración.<br/>',NULL,190548,12);
INSERT INTO stanza VALUES('S406','1','Sólo Cristo_es el mensaje,<br/>Todo_el tema ha de ser;<br/>A Jesús alzamos siempre;<br/>Sólo Cristo se_ha de ver.<br/>',NULL,190549,1);
INSERT INTO stanza VALUES('S406','chorus','Sólo Cristo para siempre,<br/>Alabémoslo a Él;<br/>Salva, santifica_y sana;<br/>Pronto viene nuestro Rey.<br/>',NULL,190550,2);
INSERT INTO stanza VALUES('S406','2','Sólo Cristo es quien salva;<br/>Toda culpa Él quitó.<br/>Él es la justicia_eterna,<br/>Nuestra vida y vigor.<br/>',NULL,190551,3);
INSERT INTO stanza VALUES('S406','3','Sólo Cristo santifica;<br/>Él nos libra del pecar.<br/>Con Su_Espíritu nos llena<br/>Hasta_el corazón colmar.<br/>',NULL,190552,4);
INSERT INTO stanza VALUES('S406','4','Sólo Cristo es quien sana;<br/>Nuestra_enfermedad llevó.<br/>En resurrección, Su vida<br/>A Sus miembros Él legó.<br/>',NULL,190553,5);
INSERT INTO stanza VALUES('S406','5','Sólo Cristo_es nuestra fuerza,<br/>El don de Pentecostés;<br/>¡Que Tu_Espíritu nos llene,<br/>Oh Jesús, con Tu poder!<br/>',NULL,190554,6);
INSERT INTO stanza VALUES('S406','6','Y por Cristo esperamos;<br/>Su llamado_hay que_escuchar.<br/>Cristo es el todo_en todo<br/>Y por siempre_así será.<br/>',NULL,190555,7);
INSERT INTO stanza VALUES('S407','1','Jesús, sol y‿escudo eres,<br/>Sol y‿escudo siempre;<br/>Nunca dejas de brillar,<br/>Nos das confianza.<br/>Al andar en luz gozamos,<br/>Y‿al enemigo vencemos;<br/>Jesús, sol y‿escudo para siempre.<br/>',NULL,190556,1);
INSERT INTO stanza VALUES('S407','2','Jesús, pan y vino eres,<br/>Vino‿y pan por siempre;<br/>Nunca dejas de nutrirnos<br/>Ni de refrescarnos.<br/>Aliméntanos del pan<br/>Y del vino celestial;<br/>Jesús, pan y vino para siempre.<br/>',NULL,190557,2);
INSERT INTO stanza VALUES('S407','3','Jesús, vida y‿amor eres,<br/>Vida y_amor siempre;<br/>Nunca dejas de‿activarnos,<br/>Tampoco de‿amarnos.<br/>Todo de vida_y amor,<br/>Es en Ti que lo‿encontramos;<br/>Jesús, vida y‿amor para siempre.<br/>',NULL,190558,3);
INSERT INTO stanza VALUES('S407','4','Jesús, paz y gozo eres,<br/>Gozo‿y paz por siempre;<br/>Gozo que no se‿envanece,<br/>Paz que nunca cambia.<br/>En Ti gozo‿y paz tenemos,<br/>Eternos los poseemos;<br/>Jesús, paz y gozo para siempre.<br/>',NULL,190559,4);
INSERT INTO stanza VALUES('S407','5','Jesús, canto‿y fuerza eres,<br/>Fuerza‿y canto siempre;<br/>Fuerza que nunca se‿esfuma,<br/>Ni desaparece.<br/>Canto que perdurará,<br/>Ahora‿y por la‿eternidad;<br/>Jesús, canto‿y fuerza para siempre.<br/>',NULL,190560,5);
INSERT INTO stanza VALUES('S408','1','Antes, bendiciones,<br/>Hoy es el Señor;<br/>Antes, sentimientos,<br/>Hoy revelación;<br/>Antes eran dones,<br/>Hoy tengo‿al Dador;<br/>Antes, sanidades,<br/>Hoy, el Sanador.<br/>',NULL,190561,1);
INSERT INTO stanza VALUES('S408','chorus','Todo‿en todo siempre,<br/>Cristo cantaré;<br/>Todo_en Cristo está,<br/>Y Cristo todo es.<br/>',NULL,190562,2);
INSERT INTO stanza VALUES('S408','2','Antes me esforzaba,<br/>Hoy confío en Él;<br/>Antes, medio salvo,<br/>Hoy, con gran poder;<br/>Antes me aferraba,<br/>Hoy me ase Él;<br/>Antes, en deriva,<br/>Hoy, mi ancla es.<br/>',NULL,190563,3);
INSERT INTO stanza VALUES('S408','3','Antes muchos planes,<br/>Hoy la oración;<br/>Antes, afanoso,<br/>Hoy, sin ambición;<br/>Antes, por lo mío,<br/>Hoy, por el Señor;<br/>Antes le pedía,<br/>Hoy le doy loor.<br/>',NULL,190564,4);
INSERT INTO stanza VALUES('S408','4','Antes yo obraba,<br/>Hoy lo hace Él;<br/>Antes lo usaba,<br/>Hoy me usa Él;<br/>Antes, por mi ego,<br/>Hoy, por el Señor;<br/>Antes quise fuerza,<br/>Hoy, al fuerte Dios.<br/>',NULL,190565,5);
INSERT INTO stanza VALUES('S408','5','Antes, yo sin Cristo,<br/>Hoy, conmigo es;<br/>Antes me_apagaba,<br/>Hoy mi brillo_es Él;<br/>Antes me moría,<br/>Hoy espero en Él,<br/>Firme_en la promesa:<br/>Su regreso fiel.<br/>',NULL,190566,6);
INSERT INTO stanza VALUES('S409','1','Uno hay que nunca cambia,<br/>Que_es firme y muy fiel,<br/>Y que cubre el futuro,<br/>Presente y_el ayer;<br/>Cristo, Roca de los siglos,<br/>Principio_y Final,<br/>Principio_y Final.<br/>',NULL,190567,1);
INSERT INTO stanza VALUES('S409','chorus','El Principio es Él<br/>El Final también;<br/>Cristo_es tu futuro,<br/>Déjale_el ayer;<br/>Cristo_es para mí<br/>El Principio_y Fin,<br/>Roca de los siglos,<br/>Principio y Fin.<br/>',NULL,190568,2);
INSERT INTO stanza VALUES('S409','2','Uno hay que hoy sostiene<br/>El orbe celestial,<br/>Mas nos pide que en Su seno<br/>Echemos todo afán.<br/>Todo hay que llevar a Cristo,<br/>//Principio y Final.//<br/>',NULL,190569,3);
INSERT INTO stanza VALUES('S409','3','Uno hay que siempre guarda<br/>En cada tempestad,<br/>Y nos guiará Su mano<br/>Por toda adversidad.<br/>Confiaremos siempre en Cristo,<br/>//Principio y Final.//<br/>',NULL,190570,4);
INSERT INTO stanza VALUES('S409','4','Oh, Jesús, te coronamos<br/>Con nuestro amor leal;<br/>Al Señor de los señores<br/>Queremos adorar.<br/>Oh, que te coronen Cristo,<br/>//Principio y Final.//<br/>',NULL,190571,5);
INSERT INTO stanza VALUES('S410','1','Maravilloso_es mi Salvador;<br/>Guía_y proteje durante_el turbión.<br/>Mi Salvador es mi todo aquí,<br/>Mi Guardián fuerte; ¡Cristo_es por mí!<br/>',NULL,190572,1);
INSERT INTO stanza VALUES('S410','chorus','¡Cristo_es por mí!<br/>¡Cristo_es por mí!<br/>Siempre,_en cualquier lugar<br/>¡Cristo_es por mí!<br/>',NULL,190573,2);
INSERT INTO stanza VALUES('S410','2','Cristo_en salud o en enfermedad,<br/>Cristo_en riquezas o necesidad;<br/>Con sol, con lluvia, lo que sea_aquí,<br/>Cristo me guarda, ¡Cristo_es por mí!<br/>',NULL,190574,3);
INSERT INTO stanza VALUES('S410','3','Roca, Refugio y mi Torre_es Él,<br/>Mi Fortaleza, mi fuerza y poder;<br/>Mi Mediador, Vida_eterna también,<br/>Redentor bueno: ¡Por mí es Él!<br/>',NULL,190575,4);
INSERT INTO stanza VALUES('S410','4','Mi Sacerdote, Profeta y Rey,<br/>Mi Pan de vida, mi Fuente también;<br/>Sol de justicia, Estrella_hasta_el fín,<br/>Salvación plena: ¡Cristo_es por mí!<br/>',NULL,190576,5);
INSERT INTO stanza VALUES('S410','5','Cristo_en lamento, en gozo_o penar;<br/>Es mi Tesoro_al perder o ganar;<br/>Fiel Compañero, doquiera que_esté,<br/>Viva o muera: ¡Por mí es Él!<br/>',NULL,190577,6);
INSERT INTO stanza VALUES('S411','1','¿A quién tengo_en los cielos, yo<br/>Sino, Señor, a Ti?<br/>Por siempre cantará mi voz:<br/>¡Cristo_es para mí!<br/>Él la serpiente aplastó;<br/>Su sangre_a mí me redimió;<br/>Con Dios Él me reconcilió,<br/>¡Cristo_es para mí!<br/>',NULL,190578,1);
INSERT INTO stanza VALUES('S411','2','No_envidio a los ricos de hoy,<br/>¡Cristo_es para mi!<br/>Ni_algún juquete_encantador,<br/>¡Cristo_es para mi!<br/>Se_agota_el gozo terrenal<br/>Y todo se marchitará,<br/>Pero mi gozo_es eternal,<br/>¡Cristo_es para mi!<br/>',NULL,190579,2);
INSERT INTO stanza VALUES('S411','3','Aunque muy pobre sea yo,<br/>¡Cristo_es para mi!<br/>Él sabe bien lo que_es mejor;<br/>¡Cristo_es para mi!<br/>Aunque la_higuera no_eche flor,<br/>O pierda la_oliva vigor<br/>Y haya muerte_alrededor,<br/>¡Cristo_es para mi!<br/>',NULL,190580,3);
INSERT INTO stanza VALUES('S411','4','Aunque estoy en tierra_hostil,<br/>¡Cristo_es para mi!<br/>Y me acosa_el mundo vil,<br/>¡Cristo_es para mi!<br/>Haya violencia_o destrucción,<br/>Si urge la persecusión<br/>Y sufre mi_alma humillación,<br/>¡Cristo_es para mi!<br/>',NULL,190581,4);
INSERT INTO stanza VALUES('S411','5','Cuando se_acerque ya mi fin,<br/>¡Cristo_es para mi!<br/>Reposaré seguro_en Él;<br/>¡Cristo_es para mi!<br/>Cuando adolorido_esté,<br/>Sin fuerzas propias en mi ser,<br/>Frente_a la muerte cantaré:<br/>¡Cristo_es para mi!<br/>',NULL,190582,5);
INSERT INTO stanza VALUES('S412','1','Gracias, Señor, que_empiezo a ver<br/>Esta revelación:<br/>Lo que_a los Tuyos puedes ser,<br/>Lo que para Ti son.<br/>Si ellos dan a Ti su ser<br/>Dispuestos siempre a_obedecer.<br/>',NULL,190583,1);
INSERT INTO stanza VALUES('S412','2','Maravilloso es descubrir<br/>Que puedo en Ti confiar!<br/>Que eres tanto para mí.<br/>En todo mi andar.<br/>Tú llenas mi necesidad,<br/>Y Tú aplacas todo_afán.<br/>',NULL,190584,2);
INSERT INTO stanza VALUES('S412','3','Te tomo hoy, mi fiel Guardián,<br/>Me comprometo_aquí:<br/>Mi alma, causa, andar y obrar.<br/>Yo todo te ofrecí;<br/>Y mi depósito, lo sé,<br/>Contigo_está guardado bien.<br/>',NULL,190585,3);
INSERT INTO stanza VALUES('S412','4','Te tomo a Ti como la paz<br/>Que llena el corazón;<br/>Tú calmas toda tempestad,<br/>En Ti yo firme estoy.<br/>Como Tu reino aumenta, así<br/>También Tu paz hoy crece en mí.<br/>',NULL,190586,4);
INSERT INTO stanza VALUES('S412','5','Sabiduría para mí,<br/>El más sabio eres Tú;<br/>Lo necio escogiste aquí,<br/>Me trajiste a Tu luz.<br/>Que pueda hablar y obrar por Ti,<br/>Y Tú, hablar y obrar en mí.<br/>',NULL,190587,5);
INSERT INTO stanza VALUES('S412','6','Por ser mi todo, Tú, Señor,<br/>Lo Tuyo es mío hoy;<br/>Yo nada tengo y nada soy,<br/>Mi "nada" a Ti te doy.<br/>Tú eres todo para mí,<br/>Mi suficiencia en todo aquí.<br/>',NULL,190588,6);
INSERT INTO stanza VALUES('S413','1','Oh, Cristo_en Ti, y sólo en Ti,<br/>Mi alma_al fin halló,<br/>La paz y el gozo que buscó,<br/>Mas nunca conoció.<br/>',NULL,190589,1);
INSERT INTO stanza VALUES('S413','chorus','Me satisface Cristo hoy,<br/>Su nombre_invocaré;<br/>La vida,_el gozo y‿el amor,<br/>Jesús, en Ti hallé.<br/>',NULL,190590,2);
INSERT INTO stanza VALUES('S413','2','Buscaba yo descanso y paz,<br/>Mas no pensaba en Ti;<br/>Pero al pasar mi Salvador<br/>Su gran amor sentí.<br/>',NULL,190591,3);
INSERT INTO stanza VALUES('S413','3','Cisternas rotas yo probé<br/>Sin apagar mi sed;<br/>Beber de ellas intenté,<br/>Mas burla sólo hallé.<br/>',NULL,190592,4);
INSERT INTO stanza VALUES('S413','4','Por los placeres que perdí<br/>Lloré, mas no por Ti;<br/>Hasta que vista recibí,<br/>Y Tu_hermosura vi.<br/>',NULL,190593,5);
INSERT INTO stanza VALUES('S414','1','A la Fuente de vida llegué,<br/>La fuente que fluye de Dios.<br/>Yo las aguas de_afanes dejé<br/>Y vine_al Elim del amor;<br/>Yo del pozo de lo_alto bebí<br/>Desde lo_hondo de mi interior.<br/>No puede ninguno decir<br/>El gozo del Consolador.<br/>',NULL,190594,1);
INSERT INTO stanza VALUES('S414','chorus','Oh, ven a la Fuente_a beber<br/>La Fuente de vida_eternal;<br/>Ven, bebe, no se_agotará,<br/>Pues Cristo_es la Fuente_en verdad.<br/>',NULL,190595,2);
INSERT INTO stanza VALUES('S414','2','A la Fuente de sangre llegué<br/>Que fluye por nuestra maldad.<br/>Del pecado, mis ropas lavé;<br/>Más blancas que la nieve están.<br/>Ya no cuenta mi justicia aquí,<br/>Jesús en mi alma vive_hoy.<br/>Su esencia divina está en mí,<br/>Y en Él sano y salvo yo_estoy.<br/>',NULL,190596,3);
INSERT INTO stanza VALUES('S414','3','A la Fuente que sana llegué,<br/>Constante, abundante fluir.<br/>Su secreto nadie comprará;<br/>Ni sabio podrá descubrir.<br/>El secreto el Señor reveló<br/>En la fuente que fluye de Él,<br/>En las llagas que pueden curar,<br/>En Él al llenar nuestro ser.<br/>',NULL,190597,4);
INSERT INTO stanza VALUES('S414','4','A la fuente de gozo llegué,<br/>La fuerza de mi corazón.<br/>Do mi sol no se opacará;<br/>Mi gozo es sin aleación.<br/>La higuera se marchitará,<br/>Los placeres se disminuirán,<br/>Mas mis fuentes no se secarán,<br/>Pues tengo porción divinal.<br/>',NULL,190598,5);
INSERT INTO stanza VALUES('S415','1','Fuente de mis días, Tú,<br/>Gozo de mi corazón,<br/>Eres resplandor de luz,<br/>Mi refugio_en noche_atróz;<br/>Al mirarte, Tú me das<br/>Esperanza_y claridad.<br/>',NULL,190599,1);
INSERT INTO stanza VALUES('S415','2','Arduos años yo pasé<br/>Antes de hallar Tu faz,<br/>Con temores por doquier,<br/>Desaliento_y soledad;<br/>La tormenta arreció<br/>Hasta que llegó_el Señor.<br/>',NULL,190600,2);
INSERT INTO stanza VALUES('S415','3','Tu presencia sobre_el mar<br/>Disipó la tempestad;<br/>Vino la tranquilidad,<br/>Reposé al ver Tu faz;<br/>Y mi terca voluntad<br/>Te_escuchó decir: "Ten paz".<br/>',NULL,190601,3);
INSERT INTO stanza VALUES('S415','4','Uno soy contigo ya:<br/>Corazón y voluntad;<br/>¡Qué tranquilo_el cielo está!<br/>¡Tierra firme_hallamos ya!<br/>Pues me dijo Tu amor:<br/>¡Ya no_hay noche ni turbión!<br/>',NULL,190602,4);
INSERT INTO stanza VALUES('S416','1','Señor, hoy eres en verdad<br/>Una viviente realidad;<br/>Por fe hoy te percibo más<br/>Que todo_objeto terrenal;<br/>Eres más íntimo a mí<br/>Que_el más cercano lazo_aquí.<br/>',NULL,190603,1);
INSERT INTO stanza VALUES('S416','2','Tú, que mi alma contempló,<br/>Me restauraste en amor;<br/>Purificaste mi_intención;<br/>¡Santa_y ferviente_es mi pasión!<br/>Has elevado Tú mi ser;<br/>Gloriosa mi esperanza es.<br/>',NULL,190604,2);
INSERT INTO stanza VALUES('S416','3','Más cerca_y más querido sé,<br/>Mi Salvador, mi_amado Rey;<br/>Más quiero yo Tu rostro ver,<br/>Gracia_en Tu_hablar impárteme;<br/>Vida transformas en amor;<br/>Gracia y piedad hoy mías son.<br/>',NULL,190605,3);
INSERT INTO stanza VALUES('S417','1','¡Cuán lento las horas se van<br/>Cuando_a Cristo no puedo ver!<br/>Sin Él todo pierde_el sabor;<br/>Sin Él nada me da placer;<br/>El sol pierde su clara luz,<br/>Los campos están sin vergel;<br/>Mas si yo disfruto de Él,<br/>Diciembre, como mayo es.<br/>',NULL,190606,1);
INSERT INTO stanza VALUES('S417','2','Su nombre da fragante_olor;<br/>Es música Su dulce voz.<br/>Es por Su presencia gentil<br/>Que la_oscuridad me quitó.<br/>Si Él está cerca de mí,<br/>Carencia_o temor no tendré;<br/>Ninguno cual yo tan feliz,<br/>Todo el año verano es.<br/>',NULL,190607,2);
INSERT INTO stanza VALUES('S417','3','Contento, contemplo Su faz;<br/>Yo busco_agradarlo a Él;<br/>No hay panorama_o lugar<br/>Que a mí me pueda mover.<br/>Al ser bendecido_en Su_amor,<br/>Nada un palacio valdrá;<br/>Pasiones, palacios serán,<br/>Si Cristo conmigo está.<br/>',NULL,190608,3);
INSERT INTO stanza VALUES('S417','4','Señor, si soy Tuyo_en verdad,<br/>Si eres mi sol y canción,<br/>¿Por qué mi invierno está<br/>Tan largo, y lánguido_estoy?<br/>Restaura Tu gozo en mí;<br/>Dispersa las nubes, Señor,<br/>O llévame junto a Ti,<br/>Adonde_el invierno cesó.<br/>',NULL,190609,4);
INSERT INTO stanza VALUES('S418','1','Cristo es todo para mí;<br/>Mi vida_y gozo_es Él;<br/>Día por día_es mi sostén;<br/>Sin Él he de caer.<br/>Si triste_estoy, a Él yo voy;<br/>Solo_Él alegra_el corazón;<br/>Si triste_estoy, con gozo voy<br/>A Jesús.<br/>',NULL,190610,1);
INSERT INTO stanza VALUES('S418','2','Cristo es todo para mí,<br/>Mi_amigo_en el dolor;<br/>Y cada vez que voy a Él,<br/>Me da gran bendición.<br/>Manda la lluvia y el sol;<br/>Madura_el grano nuestro Dios;<br/>Lluvia y sol manda_el Señor:<br/>Mi Jesús.<br/>',NULL,190611,2);
INSERT INTO stanza VALUES('S418','3','Cristo es todo para mí,<br/>Y fiel a Él seré;<br/>¿Cómo podré negar a_Aquel<br/>Que tal amigo es?<br/>Justo_es seguirlo, bien lo sé;<br/>Cuida de mí a diario Él,<br/>Sigo a_Aquél que es mi bien;<br/>Mi Jesús.<br/>',NULL,190612,3);
INSERT INTO stanza VALUES('S418','4','Cristo es todo para mí,<br/>No_hay otro_amigo_así;<br/>Confío hoy y confiaré<br/>Cuando me llegue_el fin.<br/>Bella_es la vida junto_a Él,<br/>Bella con tal amigo fiel;<br/>Gozo_eternal, vida_eternal:<br/>Mi Jesús.<br/>',NULL,190613,4);
INSERT INTO stanza VALUES('S419','1','Que pase_el gozo_aquí;<br/>Mío_es Jesús.<br/>Y todo_enlace vil;<br/>Mío_es Jesús.<br/>Todo_un desierto es,<br/>Solo_hay reposo_en Él;<br/>¡Tal bendición hallé!<br/>Mio_es Jesús!<br/>',NULL,190614,1);
INSERT INTO stanza VALUES('S419','2','¡Fuera la tentación!<br/>Mío_es Jesús.<br/>Con Él me quedo yo;<br/>Mío_es Jesús.<br/>Oh, que lo terrenal,<br/>Con su fugaz afán,<br/>Deje mi alma_en paz;<br/>Mío_es Jesús.<br/>',NULL,190615,2);
INSERT INTO stanza VALUES('S419','3','La noche se_esfumó;<br/>Mío_es Jesús.<br/>El_alba alumbró;<br/>Mío_es Jesús.<br/>Lo que probé aquí<br/>Dejo_un vacío_en mí;<br/>Jesús me colma, sí;<br/>Mío_es Jesús.<br/>',NULL,190616,3);
INSERT INTO stanza VALUES('S419','4','Adiós, mortalidad;<br/>Mío_es Jesús.<br/>Bendita_eternidad;<br/>Mío_es Jesús.<br/>Donde mi_Amado_está<br/>Hay gozo y soláz;<br/>Su seno_es dulce paz;<br/>Mío_es Jesús.<br/>',NULL,190617,4);
INSERT INTO stanza VALUES('S420','1','Tú, fuente_oculta de mi paz;<br/>Tú, suficiente_amor de Dios,<br/>Refugio, ayuda_y protección;<br/>Seguro_en Tí, Jesús, estoy;<br/>De culpa, pena y dolor<br/>Me_escondo_en Ti, mi buen Señor.<br/>',NULL,190618,1);
INSERT INTO stanza VALUES('S420','2','Mi todo_en todo_eres Jesús;<br/>Eres descanso_en mi labor;<br/>La medicina_al corazón;<br/>En guerra,_el Pacificador.<br/>Frente al rival, Tú gozo das;<br/>En mi vergüenza: gloria_y paz.<br/>',NULL,190619,2);
INSERT INTO stanza VALUES('S420','3','En mi_escasez, me llenas más;<br/>Si débil soy, poder me das;<br/>Mi libertad, si_atado_estoy;<br/>Mi luz en densa_oscuridad;<br/>Gozo_inefable_en el dolor;<br/>Mi vida_en muerte, mi Señor.<br/>',NULL,190620,3);
INSERT INTO stanza VALUES('S421','1','Todo_es posible para_aquel<br/>Que en Jesús pueda creer;<br/>Tu nombre ya no insultaré,<br/>Hoy Tu verdad recibiré.<br/>Creo, Señor, yo creo_en Ti,<br/>Todo_es posible para mí.<br/>',NULL,190621,1);
INSERT INTO stanza VALUES('S421','2','Lo más difícil de lograr<br/>Es que el pecado cese en mí;<br/>Mas por Tu gran fidelidad<br/>Yo sé que ha de ser así.<br/>Si nada es arduo para Ti,<br/>Todo es posible para mí.<br/>',NULL,190622,2);
INSERT INTO stanza VALUES('S421','3','Aunque se opone el mundo hoy,<br/>No falla la Palabra fiel;<br/>Pues la verdad de nuestro Dios<br/>Puede el pecado en mí vencer.<br/>Aunque imposible, sólo en Ti<br/>Todo es posible para mí.<br/>',NULL,190623,3);
INSERT INTO stanza VALUES('S421','4','Todo es posible para Dios<br/>Y para Cristo en mi ser;<br/>Todo es posible para mí<br/>Cuando renueva Su poder.<br/>Del vil pecado libre al fin,<br/>Todo es posible para mí.<br/>',NULL,190624,4);
INSERT INTO stanza VALUES('S421','5','Todo es posible para Dios,<br/>Y para Cristo en mi interior;<br/>Derrama en mí Tu propio ser,<br/>No viva yo, mas Tú, Señor,<br/>Para que pueda comprobar<br/>La omnipotencia de Tu amor.<br/>',NULL,190625,5);
INSERT INTO stanza VALUES('S422','1','Cristo_es objetivo_y subjetivo_a mí,<br/>Rogando_en los cielos objetivo es;<br/>Viviendo_en Sus miembros, subjetivo_es Él<br/>E internamente les brinda Su ser.<br/>',NULL,190626,1);
INSERT INTO stanza VALUES('S422','2','Arriba se sienta a la diestra de Dios;<br/>Como Sacerdote Su sangre mostró;<br/>Como Abogado intercede hoy,<br/>Y siempre nos cuida nuestro Fiador.<br/>',NULL,190627,2);
INSERT INTO stanza VALUES('S422','3','Él es el Espíritu en nuestro ser,<br/>Él es nuestra vida y el todo es El;<br/>Él es nuestra fuerza y gracia también,<br/>Nuestro Paracleto que nos da poder.<br/>',NULL,190628,3);
INSERT INTO stanza VALUES('S422','4','Un Hombre en los cielos en gloria está,<br/>Como Precursor, Él cumplió con Su plan;<br/>Al hombre introdujo en el mismo Dios,<br/>Con Él lo hizo uno, mostrando Su amor.<br/>',NULL,190629,4);
INSERT INTO stanza VALUES('S422','5','Toda la plenitud de Dios está en Él<br/>Como el Espíritu en nuestro ser;<br/>Revela a Dios y nos lo hace real,<br/>Su vida nos une al Dios eternal.<br/>',NULL,190630,5);
INSERT INTO stanza VALUES('S422','6','El Cristo ascendido en el cielo está,<br/>Y Él por Su pueblo pronto volverá.<br/>Hoy vive en nosotros el Libertador,<br/>Y nos cambiará con Su gran resplandor.<br/>',NULL,190631,6);
INSERT INTO stanza VALUES('S422','7','Muy pronto veremos la mezcla total<br/>Del cielo y la tierra en esa Ciudad;<br/>Todo lo objetivo mezclado será<br/>Con lo subjetivo en gloria eternal.<br/>',NULL,190632,7);
INSERT INTO stanza VALUES('S423','1','Cristo es tan subjetivo,<br/>Mora en mi_espíritu;<br/>Cristo es todo-inclusivo,<br/>Y_uno con mi_espíritu.<br/>',NULL,190633,1);
INSERT INTO stanza VALUES('S423','chorus','¡Oh, qué subjetivo_es Cristo_en mí,<br/>Rico, dulce y real!<br/>Cristo es todo-inclusivo_en mí,<br/>Llena mi necesidad.<br/>',NULL,190634,2);
INSERT INTO stanza VALUES('S423','2','Cristo es tan subjetivo,<br/>Y Su vida siempre da;<br/>Como Espíritu me aviva,<br/>Y refresca sin cesar.<br/>',NULL,190635,3);
INSERT INTO stanza VALUES('S423','3','Cristo es tan subjetivo,<br/>Transformando mi alma está;<br/>A Su imagen me conforma,<br/>Él mi ser renovará.<br/>',NULL,190636,4);
INSERT INTO stanza VALUES('S423','4','Cristo es tan subjetivo,<br/>Es poder libertador;<br/>Como Espíritu de vida,<br/>Por Su ley me libra hoy.<br/>',NULL,190637,5);
INSERT INTO stanza VALUES('S423','5','Cristo es tan subjetivo,<br/>Regulando siempre está;<br/>El me guía, me corrige<br/>Hasta todo enmendar.<br/>',NULL,190638,6);
INSERT INTO stanza VALUES('S423','6','Cristo es tan subjetivo,<br/>Satisface Él mi sed;<br/>Al suplirme Sus riquezas,<br/>Yo Su plenitud tendré.<br/>',NULL,190639,7);
INSERT INTO stanza VALUES('S424','1','A Dios place_y se_ha propuesto<br/>Revelar a Cristo_en mí;<br/>Nada religioso quiere,<br/>Sino_a Cristo en mi vivir.<br/>',NULL,190640,1);
INSERT INTO stanza VALUES('S424','chorus','A Dios place_y se_ha propuesto<br/>Que se forje Cristo_en mí;<br/>No una_actuación externa,<br/>Sino Cristo_el todo_en mí.<br/>',NULL,190641,2);
INSERT INTO stanza VALUES('S424','2','A Dios place_y se_ha propuesto<br/>Que Su Cristo viva en mí;<br/>No una práctica externa,<br/>Sino Cristo obrando en mí<br/>',NULL,190642,3);
INSERT INTO stanza VALUES('S424','3','A Dios place_y se_ha propuesto<br/>Que se forme Cristo en mí;<br/>No un rito religioso,<br/>Sino Él creciendo en mí.<br/>',NULL,190643,4);
INSERT INTO stanza VALUES('S424','4','A Dios place_y se_ha propuesto<br/>Que habite Cristo en mí;<br/>No una devoción externa,<br/>Sino Él morando en mí.<br/>',NULL,190644,5);
INSERT INTO stanza VALUES('S424','5','A Dios place_y se_ha propuesto<br/>Que Su Cristo sea en mí;<br/>Esperanza de la gloria<br/>Subjetivamente en mí.<br/>',NULL,190645,6);
INSERT INTO stanza VALUES('S424','6','A Dios place_y se_ha propuesto<br/>Que Su Cristo sea en mí<br/>No una posesión externa,<br/>Sino el todo para mí.<br/>',NULL,190646,7);
INSERT INTO stanza VALUES('S425','1','¡Señor, la vida_en mí eres Tú,<br/>Y todo para mí!<br/>Tan accesible_y subjetivo,<br/>Te_experimentó así.<br/>',NULL,190647,1);
INSERT INTO stanza VALUES('S425','chorus','Tú, el Espíritu eres,<br/>Querido_y cerca a mí;<br/>¡Cómo disfruto que estás<br/>Tan disponible_a mí!<br/>',NULL,190648,2);
INSERT INTO stanza VALUES('S425','2','Tú suples abundantemente<br/>Lo que me falta aquí;<br/>Muy suficiente y preparado<br/>Para aplicarte en mí.<br/>',NULL,190649,3);
INSERT INTO stanza VALUES('S425','3','Tu unción tan dulce con Tu poder,<br/>Sostiene al débil hoy;<br/>Al impartirme Tu energía,<br/>Fortalecido soy.<br/>',NULL,190650,4);
INSERT INTO stanza VALUES('S425','4','Tu ley de vida en mi corazón,<br/>Regula mi andar;<br/>Y con Tu rica realidad<br/>Me vas a saturar.<br/>',NULL,190651,5);
INSERT INTO stanza VALUES('S425','5','Conmigo uno siempre eres Tú,<br/>¡Perfecta unidad!<br/>¡Un solo espíritu conmigo<br/>Por la eternidad!<br/>',NULL,190652,6);
INSERT INTO stanza VALUES('S426','1','¡Qué liberación me ha dado!<br/>Cristo, sí, me liberó!<br/>Quebrantado_está el pecado,<br/>¡Muerte, tu aguijón pasó!<br/>',NULL,190653,1);
INSERT INTO stanza VALUES('S426','chorus','Por Su victoria me ha hecho,<br/>Cristo, más que vencedor.<br/>En mi espíritu me infunde<br/>Su vital resurrección.<br/>',NULL,190654,2);
INSERT INTO stanza VALUES('S426','2','Cristo a mí me ha liberado,<br/>De la ley y su poder;<br/>Para siempre desatado,<br/>Por Su gracia viviré.<br/>',NULL,190655,3);
INSERT INTO stanza VALUES('S426','3','Cristo condenó el pecado,<br/>Al Calvario lo llevó;<br/>Ya no tiene en mí más base,<br/>Su poder Él destruyó.<br/>',NULL,190656,4);
INSERT INTO stanza VALUES('S426','4','Cristo abolió la muerte<br/>Por la vida inmortal;<br/>El venció sus ataduras,<br/>Con resurrección triunfal.<br/>',NULL,190657,5);
INSERT INTO stanza VALUES('S426','5','Cristo al diablo y los demonios,<br/>Con Su muerte aplastó;<br/>Del poder de las tinieblas<br/>A la luz me trasladó.<br/>',NULL,190658,6);
INSERT INTO stanza VALUES('S426','6','Da Su gracia suficiente,<br/>Y poder tan cubridor;<br/>Aunque débil, me glorío,<br/>En la fuerza del Señor.<br/>',NULL,190659,7);
INSERT INTO stanza VALUES('S427','1','No la ley de letras<br/>Quiere darnos Dios,<br/>Sino_el Cristo vivo<br/>Para salvación.<br/>No son las doctrinas<br/>Sino_es Cristo quien<br/>Liberarnos puede<br/>Del caído ser.<br/>',NULL,190660,1);
INSERT INTO stanza VALUES('S427','2','No pueden los ritos<br/>Lograr avivar<br/>El espíritu o el<br/>Alma transformar;<br/>Cristo nos da vida<br/>Como Espíritu,<br/>Para que expresemos<br/>Su vida y virtud.<br/>',NULL,190661,2);
INSERT INTO stanza VALUES('S427','3','No filosofía<br/>Ni la instrucción,<br/>Pueden conformarnos<br/>Al Hijo de Dios;<br/>Sólo Cristo mismo<br/>Dando fin al yo,<br/>Nos hace Sus miembros,<br/>En resurrección.<br/>',NULL,190662,3);
INSERT INTO stanza VALUES('S427','4','Ni las religiones,<br/>Ni la cristiandad,<br/>Llevarán a cabo<br/>Su divino plan;<br/>Pero Cristo como el<br/>Todo en mi ser<br/>A Dios satisface<br/>Y le da placer.<br/>',NULL,190663,4);
INSERT INTO stanza VALUES('S427','5','Dones y funciones<br/>Que el Señor nos da,<br/>Nunca a nuestro Cristo<br/>Pueden reemplazar;<br/>¡Sea el todo en todos<br/>Cristo en nuestro ser!<br/>¡Sólo Cristo mismo<br/>En cualquier hacer!<br/>',NULL,190664,5);
INSERT INTO stanza VALUES('S428','1','Las riquezas de mi Cristo,<br/>Plenitud de la Deidad;<br/>Aunque son inescrutables,<br/>Hoy las puedo disfrutar.<br/>',NULL,190665,1);
INSERT INTO stanza VALUES('S428','chorus','¡Las riquezas! ¡Las riquezas!<br/>Que mi Salvador me da,<br/>¡Incontable‿es su medida,<br/>Mas mi plena realidad!<br/>',NULL,190666,2);
INSERT INTO stanza VALUES('S428','2','Las riquezas de mi Cristo,<br/>Todo‿abarcan: vida‿y luz,<br/>Sanidad, poder, consuelo,<br/>¡Qué tesoros! ¡Qué virtud!<br/>',NULL,190667,3);
INSERT INTO stanza VALUES('S428','3','Por la redención divina<br/>Y completa salvación,<br/>Santifica, glorifica,<br/>Su vital resurrección.<br/>',NULL,190668,4);
INSERT INTO stanza VALUES('S428','4','Las riquezas de mi Cristo,<br/>Son el todo de mi Dios;<br/>Su persona‿y posesiones<br/>En mi‿espíritu‿infundió.<br/>',NULL,190669,5);
INSERT INTO stanza VALUES('S428','5','Las riquezas de mi Cristo,<br/>¡Qué anchura‿y longitud,<br/>Qué profundidad y‿altura!<br/>Mas mi gozo‿y plenitud.<br/>',NULL,190670,6);
INSERT INTO stanza VALUES('S428','6','Que conozca las riquezas<br/>De mi Cristo‿en realidad;<br/>Que comparta yo con otros<br/>Toda su inmensidad.<br/>',NULL,190671,7);
INSERT INTO stanza VALUES('S429','1','Jesús, yo te amo, y mío_eres Tú,<br/>Mi buen Salvador, Redentor, mi Jesús;<br/>Por Ti yo renuncio_al placer tentador;<br/>Jamás te_he amado como_hoy, mi Señor.<br/>',NULL,190672,1);
INSERT INTO stanza VALUES('S429','2','Ya que Tu me_amaste, te amo yo hoy;<br/>Tu muerte_en la cruz me compró el perdón;<br/>Tus sienes cargaron espinas de amor;<br/>Jamás te_he amado como_hoy, mi Señor.<br/>',NULL,190673,2);
INSERT INTO stanza VALUES('S429','3','En vida y muerte, Señor, te amaré,<br/>Y mientras respire te bendeciré;<br/>Y cuando la muerte su frío me dé,<br/>"Jamás te_he amado como_hoy", te diré.<br/>',NULL,190674,3);
INSERT INTO stanza VALUES('S429','4','Deleites sin fin en la era_eternal;<br/>En gloria brillante te he de_alabar;<br/>Luciendo corona, yo te_adoraré;<br/>"Jamás te_he amado como_hoy", cantaré.<br/>',NULL,190675,4);
INSERT INTO stanza VALUES('S430','1','Señor, te amo, mas no con mi_amor,<br/>Pues no_hay amor en mí;<br/>Te_amo, Señor, mas es con Tu amor,<br/>Pues vivo yo por Ti.<br/>Soy como nada, y me place_estar,<br/>Siempre vacío para Tu llenar.<br/>',NULL,190676,1);
INSERT INTO stanza VALUES('S430','2','Eres, Señor, nuestra necesidad,<br/>Y no hay nadie más;<br/>Tus bendiciones fluyen sin cesar,<br/>Y Tú eres nuestro hogar.<br/>Fuente de vida, gracia y comunión,<br/>Tú, nuestro centro y nuestra habitación.<br/>',NULL,190677,2);
INSERT INTO stanza VALUES('S431','1','Todo corazón algo‿ama:<br/>Si no‿es Cristo, no hay paz;<br/>Mas mi corazón te ama;<br/>Tómalo, es Tuyo ya.<br/>',NULL,190678,1);
INSERT INTO stanza VALUES('S431','2','Yo así desecho‿el mundo;<br/>Cristo‿el más amado es;<br/>El más bello de lo bello,<br/>Sólo Él mi gozo es.<br/>',NULL,190679,2);
INSERT INTO stanza VALUES('S431','3','Un fulgor radiante,‿eterno,<br/>Es la gloria de Tu faz;<br/>Eres tierno‿y compasivo,<br/>Y de gracia lleno‿estás.<br/>',NULL,190680,3);
INSERT INTO stanza VALUES('S431','4','Te odié, mas Tú me‿amaste,<br/>Sangre vertíste por mí;<br/>Aún amas, amas siempre<br/>¿Cómo no amarte_a Ti?<br/>',NULL,190681,4);
INSERT INTO stanza VALUES('S431','5','Hoy mi corazón mantén fiel;<br/>Que_en la tierra mi vivir;<br/>Sea la sombra de la gloria<br/>De mi vida oculta en Ti.<br/>',NULL,190682,5);
INSERT INTO stanza VALUES('S432','1','Yo de barro hecho fui,<br/>Como_envase para Dios;<br/>Cristo_es el tesoro_en mí<br/>Yo el vaso que‿Él formó.<br/>',NULL,190683,1);
INSERT INTO stanza VALUES('S432','2','A Su imagen hecho fui,<br/>Para que Él se impregne en mí<br/>Dios el vaso así forjó,<br/>Al tesoro lo igualó.<br/>',NULL,190684,2);
INSERT INTO stanza VALUES('S432','3','Mora en mí Su Espíritu,<br/>Me sostiene con poder;<br/>En mi espíritu Él está,<br/>Es en mí la realidad.<br/>',NULL,190685,3);
INSERT INTO stanza VALUES('S432','4','Hoy en mí se mueve Él,<br/>Y se mezcla con mi ser,<br/>Para el alma saturar<br/>Y mis pasos regular.<br/>',NULL,190686,4);
INSERT INTO stanza VALUES('S432','5','Transparente debo ser,<br/>Desde todo mi interior,<br/>Para que otros puedan ver<br/>Su imagen y expresión.<br/>',NULL,190687,5);
INSERT INTO stanza VALUES('S432','6','Debo transformado ser<br/>Quebrantado más y más,<br/>Conformado el barro así,<br/>Al tesoro estará.<br/>',NULL,190688,6);
INSERT INTO stanza VALUES('S433','1','Cruza el velo,_obtén lo celestial,<br/>Fuera del campamento_hay que marchar;<br/>Si gusto del Santísimo Lugar,<br/>¿Cómo de vanidad participar?<br/>',NULL,190689,1);
INSERT INTO stanza VALUES('S433','2','Cruza el velo, ve lo celestial,<br/>Sal de ese campamento terrenal;<br/>Si me cautiva la gloria de Dios,<br/>Mi corazón el mundo no amará.<br/>',NULL,190690,2);
INSERT INTO stanza VALUES('S433','3','Cruza el velo, Cristo en gloria está,<br/>Fuera del campamento va Jesús;<br/>Trono y corona a mi espíritu<br/>Inspiran a sobrellevar la cruz.<br/>',NULL,190691,3);
INSERT INTO stanza VALUES('S433','4','Cruzando el velo hay resurrección<br/>Fuera del campamento está la cruz;<br/>Si Su radiante rostro puedo ver,<br/>Yo seguiré los pasos de Jesús.<br/>',NULL,190692,4);
INSERT INTO stanza VALUES('S433','5','Cruza el velo, ten lo celestial,<br/>Fuera del campamento aguantarás;<br/>Y aunque pruebas sufre el corazón,<br/>Celeste comunión te alentará.<br/>',NULL,190693,5);
INSERT INTO stanza VALUES('S433','6','Cruza el velo, goza del caudal,<br/>Sal de ese campamento a ministrar;<br/>Si vivo yo la vida celestial,<br/>Las almas de la tierra he de saciar.<br/>',NULL,190694,6);
INSERT INTO stanza VALUES('S433','7','Cruza el velo hasta que no esté,<br/>Sal de ese campamento hasta que<br/>El cielo con la tierra llegue a ser<br/>Uno, como el hombre y Dios también.<br/>',NULL,190695,7);
INSERT INTO stanza VALUES('S434','1','Al anuncio yo creí,<br/>¡Al Cordero alabad!<br/>Y el atrio ya pasé,<br/>¡Oh, gloria sea a Dios!<br/>Separado con Jesús,<br/>Hecho santo_en el altar,<br/>Muerto_al mundo por Su cruz,<br/>¡Al Cordero alabad!<br/>',NULL,190696,1);
INSERT INTO stanza VALUES('S434','chorus','¡Aleluya! ¡Aleluya!<br/>Yo el velo crucé ya,<br/>Siempre_aquí la gloria_está;<br/>¡Aleluya! ¡Aleluya!<br/>Hoy yo vivo_en la presencia<br/>de mi Rey.<br/>',NULL,190697,2);
INSERT INTO stanza VALUES('S434','2','Rey y sacerdote soy,<br/>¡Al Cordero alabad!<br/>Pues Su sangre me limpió,<br/>¡Oh, gloria sea a Dios!<br/>Por Su Espíritu y Su luz<br/>Él me trajo a morar<br/>Al Santísimo Lugar,<br/>¡Al Cordero alabad!<br/>',NULL,190698,3);
INSERT INTO stanza VALUES('S434','3','Traspasé el velo exterior,<br/>¡Al Cordero alabad!<br/>Que cubría Su fulgor,<br/>¡Oh, gloria sea a Dios!<br/>Mas yo por la sangre entré<br/>A la santidad de Dios,<br/>Do hay muerte para el yo,<br/>¡Al Cordero alabad!<br/>',NULL,190699,4);
INSERT INTO stanza VALUES('S434','4','El velo interior pasé,<br/>¡Al Cordero alabad!<br/>Al Santísimo llegué,<br/>¡Oh, gloria sea a Dios!<br/>Hecho santo para Dios,<br/>Por Su sangre eficaz,<br/>Mi morada es el Señor,<br/>¡Al Cordero alabad!<br/>',NULL,190700,5);
INSERT INTO stanza VALUES('S435','1','No es de maravillarse,<br/>Cristo_en gloria me ganó;<br/>No_una_estrella que me_alumbra,<br/>Mas Su luz que excede_al sol.<br/>Todo_aquí yace_en la sombra,<br/>Nada_atrae mi corazón,<br/>Sino_el conocer la senda<br/>De las penas que_Él sufrió.<br/>',NULL,190701,1);
INSERT INTO stanza VALUES('S435','2','Bajo rayos terrenales<br/>Muchos viajes con pesar;<br/>Yo he visto luz del cielo,<br/>Más que_el sol en su brillar.<br/>Tu luz no se desvanece,<br/>Mas alumbra_en su fervor<br/>Las riquezas de Su gracia,<br/>Los tesoros de Su amor.<br/>',NULL,190702,2);
INSERT INTO stanza VALUES('S435','3','Maravillas de Su gloria,<br/>Lo profundo de Su amor;<br/>A lugares celestiales<br/>Me_elevó mi Salvador.<br/>No un vistazo tras el velo,<br/>Sino dentro de_él morar,<br/>Contemplando_allí Su rostro,<br/>Escuchando Su hablar.<br/>',NULL,190703,3);
INSERT INTO stanza VALUES('S435','4','Plenamente satisfecho,<br/>Contemplé Su_hermosa faz;<br/>Escuché la voz de Cristo;<br/>Mi_alma satisfecha_está.<br/>En Su gloria tan radiante,<br/>A Jesús yo pude ver;<br/>Para siempre esta gloria<br/>Mi morada ha de ser.<br/>',NULL,190704,4);
INSERT INTO stanza VALUES('S436','1','Escondida en Su presencia,<br/>Mi_alma se complace_estar.<br/>¡Cuán preciosas las lecciones<br/>Que_en Jesús puedo ganar!<br/>Los pesares de_este mundo<br/>No me pueden detener;<br/>Pues si Satanás me tienta,<br/>Al lugar secreto_iré.<br/>',NULL,190705,1);
INSERT INTO stanza VALUES('S436','2','A la sombra de Sus alas,<br/>Mi_alma se refugiará,<br/>Donde -seca y sedienta-<br/>La refresca_el manantial.<br/>A mi lado Él descansa<br/>En tan dulce comunión;<br/>Descubrir me_es imposible,<br/>Lo que me dice_el Señor.<br/>',NULL,190706,2);
INSERT INTO stanza VALUES('S436','3','Penas, dudas y temores:<br/>Todo_a Él le cuento yo.<br/>Con paciencia Él me_escuchá,<br/>Me consuela_el corazón.<br/>¿Piensas que no me reprueba?<br/>Falso_amigo sería Él,<br/>Si jamás me mencionara<br/>Los pecados que_en mí ve.<br/>',NULL,190707,3);
INSERT INTO stanza VALUES('S436','4','Si tú quieres conocer hoy<br/>La dulzura del Señor,<br/>Ve y escóndete_en Su sombra,<br/>Y_Él será tu galardón.<br/>Cuando dejes el silencio<br/>De_ese tan feliz lugar,<br/>Por Su_Espíritu, al Amo<br/>En Tu rostro_exhibirás.<br/>',NULL,190708,4);
INSERT INTO stanza VALUES('S437','1','Vengo_a Su presencia otra vez<br/>Antes que termine la noche;<br/>Hoy Su rostro_en mí resplandece_aquí<br/>Y_en mí Cristo‿amanece.<br/>El me habla_así y revela_a mí<br/>Las riquezas que_hoy mías son;<br/>Y con gran placer participo de‿Él,<br/>Mi hambre, ya la sació.<br/>',NULL,190709,1);
INSERT INTO stanza VALUES('S437','2','Su Espíritu me hace cantar,<br/>Y me habla por la Palabra;<br/>Y la fuente viva de Su poder<br/>Me inunda con Su gracia.<br/>El me habla_así y revela_a mí<br/>Las riquezas que_hoy mías son;<br/>Toda mi_escasez satisface Él,<br/>Mi sed, Él ya la sació.<br/>',NULL,190710,2);
INSERT INTO stanza VALUES('S437','3','Con ternura me trata Él<br/>Al quedarme en Su presencia;<br/>Y mi alma Él saturando va<br/>Con Su preciosa esencia.<br/>El me habla_así y revela_a mí<br/>Las riquezas que_hoy mías son;<br/>Y yo cada vez participo de_Él,<br/>Mis penas, ya las quitó.<br/>',NULL,190711,3);
INSERT INTO stanza VALUES('S438','1','Tu nombre_es como ungüento de valor,<br/>Mejor que_el vino, dulce es Tu_amor;<br/>Si sigo en las huellas de la grey,<br/>Tu comunión de_amor disfrutaré.<br/>',NULL,190712,1);
INSERT INTO stanza VALUES('S438','2','Yo soy Su amor y Él mi Amado es;<br/>Él me atrae, lo sigo por doquier.<br/>Lo escondo en mí, mirra fragante es,<br/>Me cubre como bella *alheña* Él.<br/>',NULL,190713,2);
INSERT INTO stanza VALUES('S438','3','Gusto Su amor, y Su grosura da;<br/>Hallo en Su seno gran reposo y paz.<br/>Me muestra la bandera de Su amor,<br/>Enterneciendo así mi corazón.<br/>',NULL,190714,3);
INSERT INTO stanza VALUES('S438','4','Mi Amado es mío, y yo Suyo soy,<br/>Yo soy un lirio, Él mi buen Pastor;<br/>Que apunte el día, las sombras se irán,<br/>Él como un ciervo en el monte está.<br/>',NULL,190715,4);
INSERT INTO stanza VALUES('S438','5','Mirra de muerte y resurrección,<br/>Olíbano empapa el corazón;<br/>Viento del norte, sopla hasta hacer<br/>Del huerto de mi alma Su placer.<br/>',NULL,190716,5);
INSERT INTO stanza VALUES('S438','6','Como paloma quiero limpio ser,<br/>Un lirio puro delante de Él;<br/>Yo quiero el gozo de Sus gozos ser,<br/>Y mi Cantar de los cantares, Él.<br/>',NULL,190717,6);
INSERT INTO stanza VALUES('S438','7','Como la luna, conformado a Él,<br/>Esclarecido como el sol seré;<br/>Sólo a mi Amado quiero agradar,<br/>Sólo Su vida quiero expresar.<br/>',NULL,190718,7);
INSERT INTO stanza VALUES('S438','8','Eres mi vida, yo Tu imagen soy;<br/>¡Como la muerte, fuerte es este amor!<br/>No se destruye ni decaerá;<br/>Hasta que vengas, él nos guardará.<br/>',NULL,190719,8);
INSERT INTO stanza VALUES('S438','note','**Alheña: una planta del Viejo Mundo muy apreciada por sus fragantes flores blancas y amarillas.<br/>',NULL,190720,9);
INSERT INTO stanza VALUES('S439','1','¡Oh, qué comunión! ¡Gozo divinal!<br/>¡Apoyado en Sus brazos hoy!<br/>¡Oh, qué bendición! ¡Insondable paz!<br/>¡Apoyado en Sus brazos hoy!<br/>',NULL,190721,1);
INSERT INTO stanza VALUES('S439','chorus','Apoyado,<br/>Siempre aquí seguro_estoy;<br/>Apoyado,<br/>Apoyado en Sus brazos hoy.<br/>',NULL,190722,2);
INSERT INTO stanza VALUES('S439','2','Dulce es andar y peregrinar,<br/>¡Apoyado en Sus brazos hoy!<br/>Esta senda a diario brilla más,<br/>¡Apoyado en Sus brazos hoy!<br/>',NULL,190723,3);
INSERT INTO stanza VALUES('S439','3','Me sostiene Él, nada temeré,<br/>¡Apoyado en Sus brazos hoy!<br/>Hay perfecta paz, pues estoy con Él,<br/>¡Apoyado en Sus brazos hoy!<br/>',NULL,190724,4);
INSERT INTO stanza VALUES('S440','1','Salvador, por fe te toco,<br/>Fuente, Tú, de todo bien;<br/>Por Tu sangre hoy reclamo,<br/>Tu virtud, que_es mi sostén.<br/>',NULL,190725,1);
INSERT INTO stanza VALUES('S440','chorus','Al tocarte_hay nueva vida<br/>Que Tu_espíritu me da;<br/>Limpia, purga y me llena:<br/>¡A Tu nombe, gloria dad!<br/>',NULL,190726,2);
INSERT INTO stanza VALUES('S440','2','Al tocarte,_en fe te tomo<br/>Con Tu rica plenitud;<br/>Por completo_a Ti me abro<br/>Para que me llenes Tú.<br/>',NULL,190727,3);
INSERT INTO stanza VALUES('S440','3','Toco_el cetro que me_extiendes,<br/>Oh, mi soberano Rey;<br/>De Tu plenitud recibo<br/>Y transciendo con poder.<br/>',NULL,190728,4);
INSERT INTO stanza VALUES('S440','4','Suministras gracia y fuerza<br/>Para mi necesidad;<br/>Que te toque, que te_invoque,<br/>Que_a Tu lado pueda estar.<br/>',NULL,190729,5);
INSERT INTO stanza VALUES('S441','1','Permaneced en Cristo y_en Su amor;<br/>Tened con Él a diario comunión.<br/>Permaneciendo siempre en el Señor<br/>No_habrá barreras entre Él y yo.<br/>',NULL,190730,1);
INSERT INTO stanza VALUES('S441','2','Permaneciendo en Él la unción fluirá;<br/>En comunión, Su Espíritu guiará.<br/>Obedeciendo, lo disfrutaré;<br/>Y al seguirlo, Su amigo seré.<br/>',NULL,190731,2);
INSERT INTO stanza VALUES('S441','3','Permaneciendo, la luz brillará;<br/>En comunión, las sombras huirán.<br/>Obedeciendo, vida crecerá,<br/>Y mi espíritu se animará.<br/>',NULL,190732,3);
INSERT INTO stanza VALUES('S441','4','Permaneciendo, fuerzas Él me da;<br/>En comunión la muerte pasará.<br/>Permaneciendo, no hay lamentación;<br/>En comunión se alegra el corazón.<br/>',NULL,190733,4);
INSERT INTO stanza VALUES('S441','5','Permaneciendo, huye Satanás;<br/>En comunión, el mundo no me atrae.<br/>Permaneciendo, puedo el mal vencer;<br/>En comunión el ego he de perder.<br/>',NULL,190734,5);
INSERT INTO stanza VALUES('S441','6','Permaneciendo, yo seré como Él;<br/>En comunión, más vida yo tendré.<br/>Permaneciendo, me da Su poder;<br/>En comunión, riquezas obtendré.<br/>',NULL,190735,6);
INSERT INTO stanza VALUES('S441','7','Permaneciendo, anhelo más de Ti;<br/>En comunión, Tu Espíritu arde en mí.<br/>Quiero perderme totalmente en Ti<br/>Para contigo estar mezclado así.<br/>',NULL,190736,7);
INSERT INTO stanza VALUES('S442','1','Viviendo en la luz,<br/>Con Él en comunión,<br/>Contemplo yo Su faz,<br/>Siguiendo la unción;<br/>Alabo sin cesar,<br/>De gloria en gloria voy,<br/>Viviendo en la luz.<br/>',NULL,190737,1);
INSERT INTO stanza VALUES('S443','1','Eres la Vid verdadera<br/>Y yo_el pámpano, Señor,<br/>Mas no sé qué_es lo que_impide<br/>Que produzca fruto yo.<br/>',NULL,190738,1);
INSERT INTO stanza VALUES('S443','2','Llevar fruto es mi deseo,<br/>Y Tu vida expresar,<br/>Para darte a Ti más gloria<br/>Y cumplir Tu voluntad.<br/>',NULL,190739,2);
INSERT INTO stanza VALUES('S443','3','Mas, Señor, yo no comprendo<br/>Que_es "Permaneced en Mí";<br/>Mientras más intentó hacerlo,<br/>Más me siento yo sin Ti.<br/>',NULL,190740,3);
INSERT INTO stanza VALUES('S443','4','Siento que no "permanezco",<br/>Aunque oro sin cesar,<br/>Yo de Ti me siento lejos<br/>Y sin fruto que llevar.<br/>',NULL,190741,4);
INSERT INTO stanza VALUES('S443','5','Mas Tú eres la Vid, dijiste,<br/>Y yo, un pámpano en Ti;<br/>Es un hecho consumado<br/>Desde que te recibí.<br/>',NULL,190742,5);
INSERT INTO stanza VALUES('S443','6','Ahora en Ti yo permanezco,<br/>Ya no necesito entrar,<br/>Pues a Ti estoy unido<br/>Y esta es mi realidad.<br/>',NULL,190743,6);
INSERT INTO stanza VALUES('S443','7','No, "entrar" no es el secreto,<br/>Mas saber que "estoy en Ti";<br/>Que no salga más, te pido,<br/>No que pueda_entrar en Ti.<br/>',NULL,190744,7);
INSERT INTO stanza VALUES('S443','8','Ya estoy en Ti por siempre,<br/>Dios me puso en tal lugar;<br/>Ya no debo orar luchando,<br/>Sólo en Ti en paz morar.<br/>',NULL,190745,8);
INSERT INTO stanza VALUES('S443','9','Puesto que estoy "adentro",<br/>Por "entrar" no pediré;<br/>Mas con gozo y alabanzas<br/>Tu Palabra creeré.<br/>',NULL,190746,9);
INSERT INTO stanza VALUES('S443','10','Yo ahora en Ti reposo,<br/>Pues de mi ego ya salí;<br/>Eres Tú mi fuerza y vida,<br/>Y el todo para mí.<br/>',NULL,190747,10);
INSERT INTO stanza VALUES('S444','1','¡Morando en Ti!, en Tu profundo amor,<br/>Señor Jesús, Cordero de mi Dios;<br/>Cual rama_y árbol en unión vital,<br/>Quiero, mi buen Señor, en Ti morar.<br/>',NULL,190748,1);
INSERT INTO stanza VALUES('S444','2','¡Morando en Ti!, mi Salvador yo sé<br/>Cómo Tu vasto amor se verterá;<br/>Así mi vaso rebosando en Ti<br/>Con inefable gozo fluirá.<br/>',NULL,190749,2);
INSERT INTO stanza VALUES('S444','3','¡Morando en Ti!, ni el ego ni el mal<br/>Podrán Tu vida interna subyugar;<br/>Mi alma, unida a Ti en comunión,<br/>Sólo anhela estar en sumisión.<br/>',NULL,190750,3);
INSERT INTO stanza VALUES('S444','4','¡Morando en Ti!, yo puedo entender,<br/>Hoy los secretos de Tu corazón;<br/>Paz, gozo y Tu Palabra conocer,<br/>Sirviendo a Dios con fruto y poder.<br/>',NULL,190751,4);
INSERT INTO stanza VALUES('S444','note','**Nota: Tonada alterna. Cada verso se repite dos veces.**<br/>',NULL,190752,5);
INSERT INTO stanza VALUES('S445','1','He_aprendido_el gran secreto<br/>De_habitar en el Señor;<br/>He probado de Su vida_en<br/>La Palabra de mi Dios;<br/>Y confiando en la sangre<br/>Fuerza_y paz recibo yo;<br/>En Jesús me he perdido<br/>Y me hundo en mi Dios.<br/>',NULL,190753,1);
INSERT INTO stanza VALUES('S445','chorus','Habitando_en el Señor<br/>Su Palabra_es mi sostén,<br/>Yo me_escondo en el seno de Su_amor.<br/>Habitando_en el Señor<br/>Y confiando_en Su hablar,<br/>Yo me_escondo en el seno de Su_amor.<br/>',NULL,190754,2);
INSERT INTO stanza VALUES('S445','2','Yo estoy crucificado<br/>Con Jesús y Él vive en mí;<br/>Ya mis luchas he depuesto<br/>Y le dejo en mí vivir.<br/>Su Espíritu en mí reina<br/>Pues cedí mi voluntad;<br/>Y Su sangre tan preciosa<br/>Hoy me limpia de maldad.<br/>',NULL,190755,3);
INSERT INTO stanza VALUES('S445','3','Mis dolencias yo le entrego,<br/>Él las puede acarrear;<br/>Mis temores y tristezas<br/>Sólo a Él puedo llevar.<br/>En Jesús obtengo fuerzas,<br/>Por Su aliento vivo yo,<br/>Él aun me da Su mente<br/>Y Su vida, fe amor.<br/>',NULL,190756,4);
INSERT INTO stanza VALUES('S445','4','Por Su Espíritu yo obro,<br/>Mi sabiduría es Él;<br/>Su presencia a mí me guarda<br/>Y me guía siempre fiel.<br/>Es la fuente de mi gozo,<br/>Esperanza de mi amor,<br/>Y el Rey que pronto viene,<br/>Mi Amigo y Salvador.<br/>',NULL,190757,5);
INSERT INTO stanza VALUES('S446','1','Tiene la vida_un secreto,<br/>Mas hoy es nuestra visión:<br/>Permanezcamos en Cristo,<br/>En la vid donde nos ha puesto Dios.<br/>',NULL,190758,1);
INSERT INTO stanza VALUES('S446','chorus','Morando en la vid,<br/>Morando en la vid,<br/>¡Todas Sus riquezas mías son!<br/>Dios nos ha puesto aquí,<br/>Para jamás salir;<br/>¡Aleluya, moramos en la vid!<br/>',NULL,190759,2);
INSERT INTO stanza VALUES('S446','2','Ya no luchamos en vano<br/>Para entrar en la vid;<br/>Dios nos ha puesto en Cristo;<br/>Aleluya, moramos en la vid.<br/>',NULL,190760,3);
INSERT INTO stanza VALUES('S446','3','Se mueve Dios en nosotros<br/>¡Oh qué Divino ungir!<br/>Así imparte Su esencia,<br/>Mientras permanecemos en la vid.<br/>',NULL,190761,4);
INSERT INTO stanza VALUES('S446','4','Hoy por Su "savia" yo vivo;<br/>¡Oh, cuánta luz hay en mí!<br/>Con Dios estamos en casa<br/>Mutuamente morando en la vid.<br/>',NULL,190762,5);
INSERT INTO stanza VALUES('S447','1','Si_en la vid permanecemos<br/>Como pámpanos en Él,<br/>Él también mora_en nosotros<br/>Como vida_en nuestro ser.<br/>',NULL,190763,1);
INSERT INTO stanza VALUES('S447','chorus','En la vid, en la vid,<br/>En la vid, en la vid,<br/>Más de Ti conoceremos<br/>Al quedarnos en la vid.<br/>',NULL,190764,2);
INSERT INTO stanza VALUES('S447','2','Es muy rica Su Palabra<br/>Cuando habla en lo interior;<br/>Pero para en Él quedarnos<br/>Hay que acatar Su voz.<br/>',NULL,190765,3);
INSERT INTO stanza VALUES('S447','3','Es aquí donde entendemos<br/>Lo que es "permanecer";<br/>Si lo amamos, guardaremos<br/>Todo lo que diga Él.<br/>',NULL,190766,4);
INSERT INTO stanza VALUES('S447','4','Sólo así, permaneciendo<br/>En Su_amor y comunión,<br/>Conocemos vida y gozo<br/>Y_el afecto del Señor.<br/>',NULL,190767,5);
INSERT INTO stanza VALUES('S447','5','¡Qué precioso! ¡Oh, qué dulce!<br/>En la vid permanecer<br/>Y llevar así el fruto<br/>De la vida que hay en Él.<br/>',NULL,190768,6);
INSERT INTO stanza VALUES('S448','1','En Jesús confiando_estoy,<br/>Cuando por tormenta voy;<br/>Aunque poca es mi fe,<br/>En Jesús yo confiaré.<br/>',NULL,190769,1);
INSERT INTO stanza VALUES('S448','chorus','Confío al amanecer,<br/>Confío al atardecer,<br/>En cualquier acontecer,<br/>En Jesús yo confiaré.<br/>',NULL,190770,2);
INSERT INTO stanza VALUES('S448','2','En mi corazón la luz<br/>Brilla por Su Espíritu;<br/>Si Él me guía, no caeré,<br/>En Jesús yo confiaré.<br/>',NULL,190771,3);
INSERT INTO stanza VALUES('S448','3','Cantaré en la claridad,<br/>Oraré en la oscuridad,<br/>Si en peligros, clamaré,<br/>En Jesús yo confiaré.<br/>',NULL,190772,4);
INSERT INTO stanza VALUES('S448','4','Confiaré por tierra y mar,<br/>Confiaré hasta el final;<br/>Hasta que regrese Él,<br/>En Jesús yo confiaré.<br/>',NULL,190773,5);
INSERT INTO stanza VALUES('S449','1','Yo Tu promesa tomo, mi Señor<br/>Como mi fuerza diaria y sostén;<br/>Miro_al futuro sin ningún temor,<br/>Pues siempre_estás conmigo, Salvador.<br/>',NULL,190774,1);
INSERT INTO stanza VALUES('S449','2','Días de inseguridad, vendrán,<br/>Cambios de_entorno, confusión y afán;<br/>Más se que nunca_el día llegará<br/>En que mi Salvador me_olvidará.<br/>',NULL,190775,2);
INSERT INTO stanza VALUES('S449','3','Días vendrán con sombras y aflicción,<br/>Cuando_el pecado sea tentador;<br/>Mas esos días no traerán temor,<br/>Porque cercano Tú_estarás, Señor.<br/>',NULL,190776,3);
INSERT INTO stanza VALUES('S449','4','Puede_haber días de gran gozo y paz,<br/>Diáfanos cielos, brillo y claridad;<br/>En ese tiempo atráeme más a Ti,<br/>Que seas Tú mi provisión aquí.<br/>',NULL,190777,4);
INSERT INTO stanza VALUES('S449','5','Los otros días que queden, Señor,<br/>Aunque sin luchas, gozo o dolor,<br/>Días normales, sin nada_especial,<br/>Con cargas de cerácter tan trivial;<br/>',NULL,190778,5);
INSERT INTO stanza VALUES('S449','6','En esos días sé conmigo, Tú;<br/>Así Tu gloria me traerá la luz;<br/>Y cuando pase_el mundo terrenal,<br/>Contigo_el día perfecto será.<br/>',NULL,190779,6);
INSERT INTO stanza VALUES('S450','1','Mi voluntad, cuán débil es,<br/>Y mi esperanza ya se fue;<br/>No puedo más que_en Ti confiar,<br/>Como mi guía y sostén.<br/>Como mi guía y sostén.<br/>',NULL,190780,1);
INSERT INTO stanza VALUES('S450','2','Hice un esfuerzo, más fallé;<br/>Tal como antes fracasé.<br/>Confío en Tu paciencia hoy<br/>Que_a Tu palabra me hace fiel.<br/>Que_a Tu palabra me hace fiel.<br/>',NULL,190781,2);
INSERT INTO stanza VALUES('S450','3','Cuando se_exalta_el corazón,<br/>Estoy a punto de caer.<br/>Pensar u_obrar no osaré,<br/>Sólo de Ti dependeré.<br/>Sólo de Ti dependeré.<br/>',NULL,190782,3);
INSERT INTO stanza VALUES('S450','4','Eres mi fuerza_y Salvador.<br/>Tu rostro quiero ver, Señor;<br/>Aunque_el más débil sé que soy,<br/>Tu gracia es mi fuerza hoy.<br/>Tu gracia es mi fuerza hoy.<br/>',NULL,190783,4);
INSERT INTO stanza VALUES('S451','1','Mi Jesús, hoy yo reposo<br/>En el gozo de Tu ser;<br/>Tu amor voy descubriendo,<br/>¡Insondable es!<br/>Me has hecho contemplarte,<br/>Tu belleza me llenó;<br/>Tu poder que nos transforma,<br/>Hoy me restauró.<br/>',NULL,190784,1);
INSERT INTO stanza VALUES('S451','chorus','Mi Jesús, hoy yo reposo<br/>En el gozo de Tu ser;<br/>Tu amor voy descubriendo,<br/>¡Insondable es!<br/>',NULL,190785,2);
INSERT INTO stanza VALUES('S451','2','Tu amor benevolente<br/>Es más ancho que la mar;<br/>¡Tu bondad maravillosa<br/>Me has dado ya!<br/>Mi Amado,_en Ti reposo<br/>Porque hoy conozco bien<br/>La abundancia de Tu gracia,<br/>Tu promesa fiel.<br/>',NULL,190786,3);
INSERT INTO stanza VALUES('S451','3','Al confiar en Ti, mi Cristo,<br/>Hoy te puedo contemplar,<br/>Y Tu_amor precioso_y puro<br/>Me satisfará.<br/>Mis anhelos satisfaces,<br/>Sacias mi necesidad,<br/>Me colmas de bendiciones,<br/>¡Qué amor sin par!<br/>',NULL,190787,4);
INSERT INTO stanza VALUES('S451','4','Alza sobre mí Tu rostro,<br/>En Ti_espero al obrar;<br/>Tu sonrisa_es mi refugio<br/>De lo terrenal.<br/>Por la gloria de mi Padre,<br/>Por la luz que da Su faz,<br/>Yo confío y reposo<br/>Mientras gracia das.<br/>',NULL,190788,5);
INSERT INTO stanza VALUES('S452','1','Cuando_andamos con Dios<br/>Y_escuchamos Su voz,<br/>Luz y gloria_el camino tendrá;<br/>Sólo se cumplirá<br/>En nosotros Su plan<br/>Si,_obediente, podemos confiar.<br/>',NULL,190789,1);
INSERT INTO stanza VALUES('S452','chorus','Confía_en Él<br/>Si feliz quieres ser;<br/>Para_andar junto_a Cristo<br/>Hay que obedecer.<br/>',NULL,190790,2);
INSERT INTO stanza VALUES('S452','2','Ni_una sombra habrá,<br/>Ni_una nube vendrá,<br/>Que Su rostro no disipará;<br/>No_habrá duda_o temor,<br/>Ni tristeza_o dolor,<br/>Si_obedientes, podemos confiar.<br/>',NULL,190791,3);
INSERT INTO stanza VALUES('S452','3','Cualquier carga_al llevar,<br/>Y también el pesar,<br/>Toda_obra_Él recompensará;<br/>Sea la cruz o_el sufrir,<br/>Él podrá bendecir,<br/>Si_obedientes, podemos confiar.<br/>',NULL,190792,4);
INSERT INTO stanza VALUES('S452','4','No podremos probar<br/>Sus delicias sin par,<br/>Hasta todo llevar a Su_altar;<br/>Mostrará Su favor<br/>Y Su gozo_en amor,<br/>Si_obedientes, podemos confiar.<br/>',NULL,190793,5);
INSERT INTO stanza VALUES('S452','5','Luego en comunión<br/>A los pies del Señor<br/>O andando_en Su senda de paz,<br/>Lo que diga se_hará;<br/>Donde_envía, se_irá,<br/>Si_obedientes, podemos confiar.<br/>',NULL,190794,6);
INSERT INTO stanza VALUES('S453','1','Sal del "campamento" hoy,<br/>Lleva Su afrenta, fiel;<br/>Si afuera Él sufrió,<br/>¿Puedo indiferente ser?<br/>',NULL,190795,1);
INSERT INTO stanza VALUES('S453','2','Sal del "campamento" hoy,<br/>Lleva tú la cruz con Él;<br/>Por camino estrechó Él fue,<br/>Yo también con Él iré.<br/>',NULL,190796,2);
INSERT INTO stanza VALUES('S453','3','Sal del "campamento" hoy,<br/>Tus parientes deja atrás;<br/>Él Su Padre obedeció;<br/>Yo sufriendo lo he de honrar.<br/>',NULL,190797,3);
INSERT INTO stanza VALUES('S453','4','Sal del "campamento" hoy,<br/>Yo con él prefiero andar;<br/>No unido a religión<br/>O a la vana sociedad.<br/>',NULL,190798,4);
INSERT INTO stanza VALUES('S453','5','Sal del "campamento" hoy,<br/>No te importe solo andar;<br/>Tus amigos perderás,<br/>Pero Él te satisfará.<br/>',NULL,190799,5);
INSERT INTO stanza VALUES('S453','6','Sal del "campamento" hoy,<br/>Para allá con Él andar,<br/>Su presencia disfrutar<br/>Y Su rostro contemplar.<br/>',NULL,190800,6);
INSERT INTO stanza VALUES('S453','7','Sal del "campamento" hoy,<br/>Hasta el amanecer;<br/>Cara a cara lo veré<br/>Y en Su reino viviré.<br/>',NULL,190801,7);
INSERT INTO stanza VALUES('S454','1','¡Me guía Él! ¡Oh qué noción!<br/>Me llena de consolación;<br/>Lo que yo haga_y donde_esté,<br/>Su mano guía por doquier.<br/>',NULL,190802,1);
INSERT INTO stanza VALUES('S454','chorus','¡Me guía Él! ¡Me guía Él!<br/>Me guía hoy Su mano fiel;<br/>Siempre seré Su seguidor,<br/>Porque me guía mi Señor.<br/>',NULL,190803,2);
INSERT INTO stanza VALUES('S454','2','Si ando yo en confusión,<br/>O si por un Edén en flor,<br/>En calma o en tempestad,<br/>Su mano_aún me guiará.<br/>',NULL,190804,3);
INSERT INTO stanza VALUES('S454','3','Tu mano tomaré, Señor,<br/>Sin murmurar y sin rencor;<br/>Contento_estoy con mi porción,<br/>Pues Tú me guías en Tu_amor.<br/>',NULL,190805,4);
INSERT INTO stanza VALUES('S454','4','Y cuando_acabe mi labor<br/>Y por Tu gracia venza yo,<br/>Frente_a la muerte no huiré;<br/>Triunfante, yo te seguiré.<br/>',NULL,190806,5);
INSERT INTO stanza VALUES('S455','1','Es tan dulce ir con Cristo,<br/>Paso_apaso, vez tras vez;<br/>Ir pisando_así Sus huellas<br/>Y_hasta_el fin andar con Él.<br/>',NULL,190807,1);
INSERT INTO stanza VALUES('S455','chorus','Paso a paso_iré<br/>Junto con mi Cristo;<br/>Hasta_el fin seguiré<br/>Todo el día_a Cristo.<br/>',NULL,190808,2);
INSERT INTO stanza VALUES('S455','2','Con Jesús andando_a diario,<br/>Nada daño nos hará;<br/>Apoyados de Su brazo,<br/>Él nos guía_hasta_el final.<br/>',NULL,190809,3);
INSERT INTO stanza VALUES('S455','3','Con Jesús en cada paso,<br/>Un momento a la vez,<br/>Cumbres que_antes no_alcanzaba<br/>Paso_a paso subiré.<br/>',NULL,190810,4);
INSERT INTO stanza VALUES('S455','4','Con Jesús voy caminado<br/>Día_y noche, hasta_el fin,<br/>Aunque Sus pisadas guíen<br/>Al sepulcro o_al jardín.<br/>',NULL,190811,5);
INSERT INTO stanza VALUES('S455','5','Con Jesús aquí andamos<br/>Mas pasando_el tiempo va;<br/>Cambiará la noche en día,<br/>Y la pena_en el cantar.<br/>',NULL,190812,6);
INSERT INTO stanza VALUES('S455','6','Luego,_en vestiduras blancas,<br/>Andaremos con Jesús;<br/>Cambiará el llanto en gozo<br/>Y la_oscuridad en luz.<br/>',NULL,190813,7);
INSERT INTO stanza VALUES('S455','7','Oh Jesús, mantenme cerca,<br/>Paso_a paso, vez tras vez;<br/>Y, pisando_así Tus huellas,<br/>Hasta_el fin te seguiré.<br/>',NULL,190814,8);
INSERT INTO stanza VALUES('S456','1','En los cielos un tesoro<br/>Insondable tiene Dios;<br/>Tiene un placer eterno<br/>Cristo_el Hijo de Su_amor.<br/>En la tierra, un tesoro<br/>Tiene Dios de gran valor;<br/>Un placer inescrutable:<br/>Cristo en Sus santos hoy.<br/>',NULL,190815,1);
INSERT INTO stanza VALUES('S456','2','Dios como lenguas de fuego<br/>Desciende para llenar<br/>Estos vasos del tesoro<br/>Que jamás se agotará.<br/>De Su gloria sempiterna<br/>Esos vasos llena Dios,<br/>Para así saciar las almas<br/>Anhelantes de Su amor.<br/>',NULL,190816,2);
INSERT INTO stanza VALUES('S456','3','Santo, aunque sufras pruebas,<br/>Su llamado es firme en ti;<br/>Quédate permaneciendo<br/>Como un pámpano en la vid.<br/>Vasos que desprecia el mundo,<br/>Sin belleza y sin honor,<br/>En sí llevan las riquezas<br/>De la gloria del Señor.<br/>',NULL,190817,3);
INSERT INTO stanza VALUES('S456','4','Oh, que sea despojado<br/>Más vacío y sin valor,<br/>Pero para Dios un vaso<br/>Santo y lleno del Señor.<br/>Nada empañe en mí la gloria,<br/>Ni opaque el "yo" la luz,<br/>Mientras hablo de Su historia<br/>Más me llene de Jesús.<br/>',NULL,190818,4);
INSERT INTO stanza VALUES('S457','1','Desde vasos terrenales<br/>Resplandeces sin cesar,<br/>Alcanzando a las gentes:<br/>¡Cristo_y Su radiante faz!<br/>',NULL,190819,1);
INSERT INTO stanza VALUES('S457','2','Cristo es la luz del cielo<br/>Que nos da Su resplandor;<br/>Luz de vida en las sombras,<br/>Pues Su_Espíritu nos dio.<br/>',NULL,190820,2);
INSERT INTO stanza VALUES('S457','3','Descendió del cielo y trajo<br/>Tal tesoro_el mismo Dios;<br/>¡Qué profundo pensamiento!<br/>¡Oh, qué dulce_y tierno_amor!<br/>',NULL,190821,3);
INSERT INTO stanza VALUES('S457','4','Somos barro, nada_hermoso,<br/>Mas nuestro tesoro es<br/>Reluciente y glorioso,<br/>Celestial, eterno y fiel.<br/>',NULL,190822,4);
INSERT INTO stanza VALUES('S457','5','Vasos frágiles y_endebles,<br/>Mas llevando_en nuestro ser<br/>Sus riquezas insondables;<br/>¡Don de Dios, Su Hijo fiel!<br/>',NULL,190823,5);
INSERT INTO stanza VALUES('S458','1','Cristo, no yo, sea_honrado y_exaltado,<br/>Cristo, no yo, se pueda siempre ver;<br/>Cristo, no yo, en todas mis palabras,<br/>Cristo, no yo, sea dado_a conocer.<br/>',NULL,190824,1);
INSERT INTO stanza VALUES('S458','chorus','¡Oh, que me salves del yo, Señor!<br/>¡Oh, que me pierda_en Ti!<br/>¡Oh, que no surja ya más yo,<br/>Mas viva Cristo_en mí!<br/>',NULL,190825,2);
INSERT INTO stanza VALUES('S458','2','Cristo, no yo, al suavizar tristezas,<br/>Cristo, no yo, al llanto sosegar;<br/>Cristo, no yo, alzando toda carga,<br/>Cristo, no yo, al miedo apaciguar.<br/>',NULL,190826,3);
INSERT INTO stanza VALUES('S458','3','Cristo más bien, que un hablar ocioso,<br/>Cristo más bien, que estéril trabajar;<br/>Cristo más bien, que el engreído ego,<br/>Cristo, o más bien, que el yo manifestar.<br/>',NULL,190827,4);
INSERT INTO stanza VALUES('S458','4','Cristo, no yo, en mis necesidades,<br/>Cristo, no yo, mi fuerza y mi suplir;<br/>Cristo cubriendo espíritu, alma y cuerpo,<br/>¡Oh, que Tu vida vivas, Cristo, en mí!<br/>',NULL,190828,5);
INSERT INTO stanza VALUES('S458','5','Cristo, será mi único ensueño,<br/>Gloria excelsa pronto yo veré;<br/>Cristo será el fin de mis anhelos,<br/>Cristo mi todo en todo ha de ser.<br/>',NULL,190829,6);
INSERT INTO stanza VALUES('S459','1','Muerte y pecado tengo en Adán,<br/>Vida y justicia_en Cristo sólo están;<br/>Si vivo_en la carne siempre_expreso á_Adán,<br/>Mas si_en el espíritu,_a Cristo_en verdad.<br/>',NULL,190830,1);
INSERT INTO stanza VALUES('S459','2','Aunque yo no peque, estando en Adán,<br/>Soy un pecador que condenado está;<br/>Cuando estoy en Cristo, no tengo que actuar,<br/>Soy justificado, de hecho, justo ya.<br/>',NULL,190831,2);
INSERT INTO stanza VALUES('S459','3','Si vivo en la carne, siempre brotará<br/>La naturaleza vil del viejo Adán;<br/>Mas si en el espíritu ando sin luchar<br/>Puedo expresar a Cristo y reinar.<br/>',NULL,190832,3);
INSERT INTO stanza VALUES('S459','4','Al morir con Cristo, libre soy de Adán,<br/>Al vivir con Cristo, Su vida me da;<br/>La mente en la carne trae el viejo Adán;<br/>La mente en mi espíritu trae vida y paz.<br/>',NULL,190833,4);
INSERT INTO stanza VALUES('S459','5','Al poner la mente en el espíritu,<br/>Salvación logramos y eternal salud;<br/>Así venceremos con esta actitud,<br/>Ganaremos la carrera en Su virtud.<br/>',NULL,190834,5);
INSERT INTO stanza VALUES('S459','6','Al poner la mente en el espíritu,<br/>Surgirá la vida que fluyó en la cruz;<br/>Al poner la mente en el espíritu,<br/>Crecerá la vida en su plenitud.<br/>',NULL,190835,6);
INSERT INTO stanza VALUES('S459','7','Cristo en mi espíritu habitando está,<br/>Toda fortaleza y bendición me da;<br/>Si en espíritu ando, pruebo santidad,<br/>Y el Dios Triuno en mí se moverá.<br/>',NULL,190836,7);
INSERT INTO stanza VALUES('S460','1','Cristo es mi vida,<br/>Mi paz interior;<br/>En espíritu uno<br/>Somos Él y yo.<br/>',NULL,190837,1);
INSERT INTO stanza VALUES('S460','chorus','Su Espíritu sigo,<br/>Al vivir en Él;<br/>Vida él me suple,<br/>Y Su paz también.<br/>',NULL,190838,2);
INSERT INTO stanza VALUES('S460','2','Pertenezco_a Cristo,<br/>Preso no he de_estar,<br/>Pues la ley de vida<br/>Me da libertad.<br/>',NULL,190839,3);
INSERT INTO stanza VALUES('S460','3','Yo ya no me ocupo<br/>De la carne hoy;<br/>Mi espíritu sigo,<br/>Negándome al yo.<br/>',NULL,190840,4);
INSERT INTO stanza VALUES('S460','4','Cristo desde adentro<br/>Me hace espiritual;<br/>Hasta el cuerpo aviva<br/>Su poder vital.<br/>',NULL,190841,5);
INSERT INTO stanza VALUES('S460','5','El Espíritu hoy<br/>Testimonio da,<br/>Que de Dios soy hijo,<br/>Y Él, mi heredad.<br/>',NULL,190842,6);
INSERT INTO stanza VALUES('S461','1','Siempre sobra_un excedente,<br/>Si_uno gusta del Señor;<br/>Cada copa se desborda<br/>Al llenarla Su dulzor.<br/>Nada _escaso_o limitado<br/>Ha salido de_Él jamás;<br/>//A los Suyos todo suple,<br/>Hasta_hacerlos rebosar.//<br/>',NULL,190843,1);
INSERT INTO stanza VALUES('S461','2','Siempre sobra_un excedente,<br/>Si del Padre celestial<br/>Aceptamos, dando gracias,<br/>La porción que Él nos da.<br/>Suministra nuestro todo,<br/>Él nos trae satisfacción,<br/>//Al gustar de Jesucristo<br/>Él nos sacia_el corazón.//<br/>',NULL,190844,2);
INSERT INTO stanza VALUES('S461','3','Siempre sobra_un excedente<br/>Al probar Su vasto_amor;<br/>Siempre queda más altura,<br/>Y profundidad mayor.<br/>No podrá la boca humana<br/>Su ternura proferir,<br/>//Sólo puede alabarlo<br/>Y Su nombre bendecir.//<br/>',NULL,190845,3);
INSERT INTO stanza VALUES('S462','1','Estamos atraídos cada día a Jesús,<br/>Es bello cual ninguno, más radiante que la luz;<br/>Es más de lo que digas o que puedas componer,<br/>Y Él se hace más querido_al verlo cada vez.<br/>',NULL,190846,1);
INSERT INTO stanza VALUES('S462','chorus','No puede describirse, ni_aún a la mitad;<br/>Él es nuestro tesoro que queremos más y más.<br/>',NULL,190847,2);
INSERT INTO stanza VALUES('S462','2','Al verle en la iglesia tanta gloria estalló,<br/>Hallando Sus riquezas, nuestra búsqueda cesó;<br/>Aquí se satisface nuestro espíritu con Él,<br/>Y Él se hace más querido al verlo cada vez.<br/>',NULL,190848,3);
INSERT INTO stanza VALUES('S462','3','Es el viviente Espíritu que mora en nuestro ser,<br/>Ungiendo nuestro espíritu, lo inunda todo Él;<br/>Reunidos con los santos nos rebosa el corazón;<br/>Por eso lo queremos con entera devoción.<br/>',NULL,190849,4);
INSERT INTO stanza VALUES('S462','4','Por Su recobro somos uno hoy con el Señor,<br/>Se exhiben Sus riquezas por la iglesia con fervor;<br/>Todo lo que tenemos nos complace derramar<br/>Para que Su propósito se pueda realizar.<br/>',NULL,190850,5);
INSERT INTO stanza VALUES('S463','1','Encontramos a Cristo_el Señor,<br/>Nuestro todo_en todo es Él;<br/>¡Oh, qué bendición el invocar<br/>Su glorioso nombre fiel!<br/>',NULL,190851,1);
INSERT INTO stanza VALUES('S463','chorus','Es un gozo inefable_y tan glorioso,<br/>Tan glorioso, tan glorioso;<br/>Es un gozo inefable_y tan glorioso,<br/>Y jamás se_ha dicho la mitad.<br/>',NULL,190852,2);
INSERT INTO stanza VALUES('S463','2','Encontramos que Cristo el Señor<br/>El Espíritu ahora es;<br/>Él en nuestro espíritu está,<br/>¡Cerca y dulce a la vez!<br/>',NULL,190853,3);
INSERT INTO stanza VALUES('S463','3','Encontramos hoy cómo vivir,<br/>Por Jesús, nuestro Señor;<br/>Al comer, beber y disfrutar<br/>Su Palabra en oración.<br/>',NULL,190854,4);
INSERT INTO stanza VALUES('S463','4','Encontramos la iglesia local,<br/>Y la provisión total;<br/>Nada en Babilonia hay que buscar,<br/>Hoy la iglesia es nuestro hogar.<br/>',NULL,190855,5);
INSERT INTO stanza VALUES('S463','5','Encontramos que cada reunión<br/>Es de gozo sin igual;<br/>Nuestro espíritu no ha de fallar,<br/>Nuestra vida llena está.<br/>',NULL,190856,6);
INSERT INTO stanza VALUES('S464','1','Jesús, te amo,<br/>Y Tu grande_amor<br/>Me atrae a buscarte<br/>Con todo fervor,<br/>Me atrae a buscarte<br/>Con todo fervor.<br/>Eres amado,<br/>Del todo deseable,<br/>En quien mi ser hoy se deleita.<br/>Eres amado,<br/>Del todo deseable,<br/>En quien mi ser hoy se deleita.<br/>',NULL,190857,1);
INSERT INTO stanza VALUES('S464','2','Jesús, mi Amado,<br/>Qué dulce es Tu amor<br/>Y el olor de Tu ungüento<br/>En mi corazón,<br/>Y el olor de Tu ungüento<br/>En mi corazón.<br/>En los jardines<br/>La fuente de agua viva,<br/>Que fluye del Líbano siempre.<br/>En los jardines<br/>La fuente de agua viva,<br/>Que fluye del Líbano siempre.<br/>',NULL,190858,2);
INSERT INTO stanza VALUES('S464','3','Oh ven, mi Amado,<br/>Al huerto a soplar,<br/>Y el olor de su aroma<br/>Se desprenderá,<br/>Y el olor de su aroma<br/>Se desprenderá.<br/>Mi esposa, hermana,<br/>Ya vine a mi huerto<br/>Para ingerir miel, vino y leche.<br/>Mi esposa hermana,<br/>Ya vine a mi huerto<br/>Para ingerir miel, vino y leche.<br/>',NULL,190859,3);
INSERT INTO stanza VALUES('S464','4','Ponme por sello<br/>En Tu corazón;<br/>Pues los celos son duros<br/>Como el cruel Seol;<br/>Y el amor es más fuerte<br/>Que la muerte atroz.<br/>Las muchas aguas<br/>No pueden apagarlo,<br/>Ni fuertes ríos ahogarlo.<br/>Si diese el hombre<br/>Los bienes de su casa<br/>Por este amor, es despreciado.<br/>',NULL,190860,4);
INSERT INTO stanza VALUES('S465','1','Cuánto te_amo, oh mi Cristo,<br/>Tu amor me conquistó;<br/>Me_atrajiste, me besaste,<br/>¡Tu amada_ahora soy!<br/>',NULL,190861,1);
INSERT INTO stanza VALUES('S465','chorus','Cuánto_amamos al Amado,<br/>Atrayente_y bello es,<br/>Nos cautiva por completo,<br/>Y hermosa Él nos ve.<br/>',NULL,190862,2);
INSERT INTO stanza VALUES('S465','2','Me comparas a la yegua<br/>Del carro de Faraón;<br/>Tanta fuerza y_energía<br/>Natural en mi interior.<br/>',NULL,190863,3);
INSERT INTO stanza VALUES('S465','3','Tengo ojos de paloma,<br/>Fijos solamente en Él;<br/>¡Va cambiando mis conceptos,<br/>Pues en mí hoy crece Él.<br/>',NULL,190864,4);
INSERT INTO stanza VALUES('S465','4','Soy un lirio en el valle,<br/>Con espinos por doquier;<br/>Solo_en Cristo yo confío,<br/>Pues mi fuerza_abandoné.<br/>',NULL,190865,5);
INSERT INTO stanza VALUES('S465','5','Cual palomas escondidas<br/>En Tu secreto lugar,<br/>Te deleitan nuestras voces<br/>Y anhelas nuestra faz.<br/>',NULL,190866,6);
INSERT INTO stanza VALUES('S465','6','Como columnas de humo<br/>Tu nos haces, oh Señor.<br/>Nuestra voluntad subyugas<br/>Por muerte_y resurrección.<br/>',NULL,190867,7);
INSERT INTO stanza VALUES('S465','7','Tu litera_ahora somos,<br/>Hoy reposas sobre nos;<br/>Nuestra persona Tú eres,<br/>Lo que somos ya menguó.<br/>',NULL,190868,8);
INSERT INTO stanza VALUES('S465','8','Hoy Tu palanquín nos haces,<br/>Cesa ya lo natural.<br/>Tu mover así realizas<br/>Para Tu expresión ganar.<br/>',NULL,190869,9);
INSERT INTO stanza VALUES('S465','9','La madera has provisto,<br/>Y su fondo, oro es;<br/>Púrpura es su asiento,<br/>Para nuestro_amado Rey.<br/>',NULL,190870,10);
INSERT INTO stanza VALUES('S465','10','Mas nosotros proveemos<br/>Nuestro amor para con Él,<br/>Que por dentro hoy recubre<br/>Ese palanquín del Rey.<br/>',NULL,190871,11);
INSERT INTO stanza VALUES('S465','11','Oh, qué belllo nuestro Amado<br/>Con Su corona nupcial;<br/>Cristo y la_iglesia_unidos<br/>¡Oh, qué gloria_a Él le da!<br/>',NULL,190872,12);
INSERT INTO stanza VALUES('S466','1','Para Cristo, huerto somos<br/>Para_especies producir;<br/>De Jesús, preciosos frutos<br/>Crecen en Su huerto_aquí:<br/>Azafrán, alheña_y nardo,<br/>Mirra_áloe_y cálamo;<br/>El olíbano_y canela<br/>Cultivamos para Ti, Señor.<br/>',NULL,190873,1);
INSERT INTO stanza VALUES('S466','2','Entra a Tu huerto,_Amado,<br/>Ven y come, oh, Señor,<br/>De Tu fruto abundante<br/>Para Tu satisfacción.<br/>"Sí", dijiste,_"estoy comiendo<br/>La dulzura de la miel";<br/>Este huerto_y sus especies:<br/>Tu satisfacción segura_y fiel.<br/>',NULL,190874,2);
INSERT INTO stanza VALUES('S466','3','En el huerto hay productos<br/>Llenos de resurrección,<br/>Y con ellos edifica<br/>Su ciudad nuestro Señor.<br/>Dios transforma estos frutos:<br/>Piedras preciosas serán<br/>Para expresar a Cristo;<br/>Dios en gloria_allí se_exhibirá.<br/>',NULL,190875,3);
INSERT INTO stanza VALUES('S466','4','La ciudad bella y_hermosa<br/>En amanecer triunfal,<br/>Como_armada, firme y fuerte,<br/>Hacia la victoria va.<br/>La ciudad y la armada;<br/>Son los santos en unión,<br/>¡Qué terror al enemigo!<br/>¡Oh, qué_hermosos son para el Señor.<br/>',NULL,190876,4);
INSERT INTO stanza VALUES('S467','1','Su estandarte sobre mí,<br/>Su estandarte es amor;<br/>En la casa del banquete estoy,<br/>Su estandarte es amor.<br/>',NULL,190877,1);
INSERT INTO stanza VALUES('S467','chorus','¡Amor! ¡Amor!<br/>Su estandarte es amor;<br/>En la casa del banquete estoy,<br/>Su estandarte es amor.<br/>',NULL,190878,2);
INSERT INTO stanza VALUES('S467','2','Su fruto, ¡oh, qué dulce es!<br/>Aquí disfruto_el banquete con Él,<br/>Su fruto, ¡oh, qué dulce es!<br/>Su fruto, ¡oh, qué dulce es!<br/>',NULL,190879,3);
INSERT INTO stanza VALUES('S467','chorus','¡Qué dulce es!<br/>Su fruto, ¡oh, qué dulce es!<br/>Aquí disfruto_el banquete con Él,<br/>Su fruto, ¡oh, qué dulce es!<br/>',NULL,190880,4);
INSERT INTO stanza VALUES('S468','1','Oh Señor Jesús precioso,<br/>Tú ganaste mi amor;<br/>No hay nadie tan hermoso,<br/>Ni tan dulce y_amoroso;<br/>Sin rival -incomparable-<br/>¡Nadie te podrá_igualar!<br/>',NULL,190881,1);
INSERT INTO stanza VALUES('S468','2','Oh Señor Jesús precioso,<br/>Yo con gozo te_escuché;<br/>Al oír Tu fiel llamado,<br/>De todo_he sido cortado;<br/>Toda búsqueda_he dejado,<br/>Todo_orgullo se_esfumó.<br/>',NULL,190882,2);
INSERT INTO stanza VALUES('S468','3','Oh Señor Jesús precioso,<br/>¿Puedo_aún tan terco ser?<br/>Yo te entrego mis durezas,<br/>Vuelvo y canto Tus riquezas;<br/>Por amor seré Tu_esclavo,<br/>Mi gozo_es obedecer.<br/>',NULL,190883,3);
INSERT INTO stanza VALUES('S468','4','Oh Señor Jesús precioso,<br/>Tu camino_escogeré;<br/>Mi deseo_es complacerte<br/>Aunque llore al seguirte;<br/>Quiero mantenerme firme<br/>Y andar contigo_en paz.<br/>',NULL,190884,4);
INSERT INTO stanza VALUES('S468','5','Oh Señor Jesús precioso,<br/>Cuando veo que no_estás,<br/>Pierde_el alba sus vestigios,<br/>Y mi rostro, todo brillo;<br/>Sólo añoro que regreses<br/>Para_en Tu presencia_estar.<br/>',NULL,190885,5);
INSERT INTO stanza VALUES('S468','6','Oh Señor Jesús precioso,<br/>Todo digo hoy a Ti.<br/>Tú, mi_amor y mi deleite,<br/>Mi porción eternamente;<br/>Eres lo que yo deseo,<br/>Nada más yo seguiré.<br/>',NULL,190886,6);
INSERT INTO stanza VALUES('S468','7','Oh Señor Jesús precioso,<br/>Lo que tengo, te lo doy;<br/>No hay nadie tan hermoso,<br/>Ni tan dulce y_amoroso;<br/>Sin rival -incomparable-<br/>¡Nadie te podrá_igualar!<br/>',NULL,190887,7);
INSERT INTO stanza VALUES('S469','1','Mi Señor, cautivo en Tu belleza,<br/>Abro‿a Ti todo mi corazón;<br/>Libre de deberes religiosos,<br/>Solo‿en Ti esté mi‿habitación.<br/>Mi Señor al contemplar Tu gloria,<br/>Hoy me llena todo Tu‿esplendor.<br/>Oh Señor, satúrame, te‿imploro,<br/>A mi‿espíritu‿únete, Señor.<br/>',NULL,190888,1);
INSERT INTO stanza VALUES('S469','2','Deslumbrante, ¡qué claro está el cielo!<br/>Sentado en el trono un Hombre está;<br/>Santo Dios, me consuma Tu fuego,<br/>Hasta que en mi ser puedas brillar.<br/>Cuando vi Tu gloria esplendorosa,<br/>En escoria mi todo se hundió;<br/>Hoy, Señor, te alabo y te amo,<br/>De Tu dulce nombre gusto yo.<br/>',NULL,190889,2);
INSERT INTO stanza VALUES('S469','3','Mi Señor, mi frasco de alabastro,<br/>Quiero derramar hoy sobre Ti;<br/>Y ungir Tu cabeza, mi Amo;<br/>Lo mejor, Señor, es para Ti.<br/>Mi Señor, desperdiciarme quiero<br/>Sobre Ti y amarte hasta el fin;<br/>Que mi corazón siga brotando<br/>Fino aceite de mi amor por Ti.<br/>',NULL,190890,3);
INSERT INTO stanza VALUES('S469','4','Ven sobre los montes de aromas,<br/>Mi Amado,_anhelo ver Tu faz;<br/>Bebe de la fuente de mi alma,<br/>Hasta que en Tus brazos pueda estar.<br/>Solo no, Señor, quiero adorarte<br/>Con los santos todos en unión;<br/>Ven, Tu Novia quiere abrazarte,<br/>Y saciar, Señor, Tu corazón.<br/>',NULL,190891,4);
INSERT INTO stanza VALUES('S470','1','Cristo_hará a quien lo ama<br/>Su columna_y palanquín,<br/>Su corona y Su gloria;<br/>¡Todo Él lo_hará! ¡Amén!<br/>',NULL,190892,1);
INSERT INTO stanza VALUES('S470','chorus','Cuánto_Él ama a Su_amada:<br/>Su deleite ella es.<br/>Ella lo ha cautivado;<br/>Es tan bella para Él.<br/>',NULL,190893,2);
INSERT INTO stanza VALUES('S470','2','Mas aún queda_una sombra;<br/>Satisfecho no_está Él.<br/>Quiere_un huerto floreciente<br/>Que Su novia llegue_a ser.<br/>',NULL,190894,3);
INSERT INTO stanza VALUES('S470','3','Paraíso de granadas,<br/>Mirra, frutos a granel,<br/>Azafrán, nardo y_áloe<br/>Para que disfrute Él.<br/>',NULL,190895,4);
INSERT INTO stanza VALUES('S470','4','A Su huerto ha venido<br/>Para mirra recoger;<br/>Del panal, comer las mieles;<br/>Vino_y leche_ha de beber.<br/>',NULL,190896,5);
INSERT INTO stanza VALUES('S470','5','La ciudad del huerto sale,<br/>El cual suple_el material;<br/>A Dios ella satisface,<br/>Y aterra al rival.<br/>',NULL,190897,6);
INSERT INTO stanza VALUES('S470','6','"Tan hermosa,_amiga mía,<br/>Como Tirsa eres tú;<br/>Cual Jerusalén, deseada".<br/>¡Tú lo_harás, Señor Jesús!<br/>',NULL,190898,7);
INSERT INTO stanza VALUES('S471','1','Todo-inclusivo_es mi Jesús,<br/>La tierra de Canaán<br/>Con ríos y arroyos mil,<br/>Es fuente_y manantial.<br/>Cerros y valles siempre están<br/>Brotando aguas sin cesar,<br/>Me riega Él -todo mi ser -<br/>Con vida.<br/>',NULL,190899,1);
INSERT INTO stanza VALUES('S471','2','Tierra de trigo es Jesús:<br/>Él se encarnó y murió.<br/>Mas la cebada ilustra Su<br/>Vida en resurrección.<br/>Tierra de higos, ¡qué sabor!<br/>Tierra del vino alegrador,<br/>Tierra de gran satisfacción,<br/>¡Cristo es!<br/>',NULL,190900,2);
INSERT INTO stanza VALUES('S471','3','¡Oh, qué abundante y rico es Él!<br/>Granada en verdad.<br/>Tierra de olivos que nos da<br/>Unción de vida eternal.<br/>Nos suministra leche y miel,<br/>Nos nutre y satisface Él.<br/>Cristo es tan real, no hay otro igual,<br/>¡Cristo es tal!<br/>',NULL,190901,3);
INSERT INTO stanza VALUES('S471','4','En Canaán comemos pan,<br/>Aquí no hay escasez.<br/>Nada nos falta estando en Él,<br/>Tan lleno y rico es.<br/>La tierra inmensa y vasta es,<br/>Completo en todo es también.<br/>¡Se expande Él en nuestro ser<br/>Sin cesar!<br/>',NULL,190902,4);
INSERT INTO stanza VALUES('S471','5','Tierra de hierro Cristo es,<br/>Emana autoridad.<br/>A este Cristo hay que cavar<br/>Y al enemigo atar.<br/>Los sufrimientos, al pasar<br/>Bronce bruñido nos harán,<br/>Para expresar Su autoridad<br/>Y brillar.<br/>',NULL,190903,5);
INSERT INTO stanza VALUES('S471','6','Por esta tierra, oh Señor,<br/>Te damos bendición.<br/>Todo-inclusivo Cristo es,<br/>¡Qué gran satisfacción!<br/>Enséñanos a cultivar<br/>A diario en esta realidad;<br/>Gozo sin par es laborar<br/>En Canaán.<br/>',NULL,190904,6);
INSERT INTO stanza VALUES('S472','1','En esta tierra_estamos hoy:<br/>La buena tierra, ¡gloria_a Dios!<br/>La buena tierra, Cristo es;<br/>¡Oh, gloria_a Dios! La tierra_es Él.<br/>',NULL,190905,1);
INSERT INTO stanza VALUES('S472','chorus','Tierra que fluye leche_y miel;<br/>El grano,_aceite_y vino_es Él.<br/>En esta tierra_estamos hoy,<br/>En Canaán, ¡oh, gloria_a Dios!<br/>',NULL,190906,2);
INSERT INTO stanza VALUES('S472','2','Incluye mucho mi Canaán:<br/>Cebada,_higueras, trigo_y pan,<br/>Vides y frutos a granel,<br/>¡Qué_extensa esta tierra es!<br/>',NULL,190907,3);
INSERT INTO stanza VALUES('S472','chorus','Para_el producto obtener,<br/>Labrar la tierra_es menester;<br/>Traeremos luego_a la reunión<br/>A Cristo, la mejor porción.<br/>',NULL,190908,4);
INSERT INTO stanza VALUES('S473','1','Dios nos presentó la tierra<br/>Para nuestra posesión;<br/>Dios por fin halló un pueblo<br/>Que_el desierto abandonó;<br/>Fuera peso y pecado;<br/>A la tierra_ahora_entramos.<br/>',NULL,190909,1);
INSERT INTO stanza VALUES('S473','chorus','¡Aleluya, aleluya,<br/>Aleluya, amén!<br/>',NULL,190910,2);
INSERT INTO stanza VALUES('S473','2','Dios ha_abierto el camino,<br/>Pues Su Hijo ya triunfó;<br/>Su_estandarte_ha levantado,<br/>¡Las batallas Él ganó!<br/>Lo que resta por hacer<br/>Es por fe seguirlo_a Él.<br/>',NULL,190911,3);
INSERT INTO stanza VALUES('S473','3','Con colinas y con valles,<br/>Con arroyos sin igual;<br/>¡Fuentes brotan agua viva<br/>Que_abundante fluye ya!<br/>Su presencia nos afirma,<br/>¡Cristo es la tierra misma!<br/>',NULL,190912,4);
INSERT INTO stanza VALUES('S473','4','Hace Dios crecer el fruto,<br/>¡Su sabor, qué dulce es!<br/>Rico_aceite y granadas,<br/>Vid, higueras, trigo_y miel.<br/>Nada más necesitamos,<br/>De la tierra nos saciamos.<br/>',NULL,190913,5);
INSERT INTO stanza VALUES('S473','5','Hoy comemos, nos llenamos,<br/>Bendecimos al Señor,<br/>Pues Su tierra nos ha dado;<br/>¡Su Palabra Él cumplió!<br/>No hay escasez alguna,<br/>¡No retrocedamos nunca!<br/>',NULL,190914,6);
INSERT INTO stanza VALUES('S473','6','En la tierra laboremos<br/>Cada día sin cesar;<br/>El "maná" no esperamos,<br/>Lo normal es laborar.<br/>Dios y_el hombre cooperando,<br/>La cosecha esperamos.<br/>',NULL,190915,7);
INSERT INTO stanza VALUES('S473','7','La labor nos da_el aumento<br/>De_esta tierra especial;<br/>Cuando el Señor regrese,<br/>Su cosecha obtendrán.<br/>Para darle_a Él la vía,<br/>Laboremos cada día.<br/>',NULL,190916,8);
INSERT INTO stanza VALUES('S474','1','Siempre laborando en la buena tierra,<br/>Desde la mañana al atardecer;<br/>Segaremos frutos, y a las reuniones<br/>Todas las gavillas podemos traer.<br/>',NULL,190917,1);
INSERT INTO stanza VALUES('S474','chorus','Las gavillas trae, las gavillas trae,<br/>¡Es un regocijo, las gavillas trae!<br/>Las gavillas trae, las gavillas trae,<br/>¡Es un regocijo, las gavillas trae!<br/>',NULL,190918,2);
INSERT INTO stanza VALUES('S474','2','Cosechamos trigo junto con cebada,<br/>Al pasar por muerte y resurrección;<br/>Sólo así se gana vida en abundancia<br/>Vivientes gavillas para la reunión.<br/>',NULL,190919,3);
INSERT INTO stanza VALUES('S474','3','Grano, vino, aceite, trae el excedente<br/>De cebada y trigo, olivo y la vid;<br/>El aceite unge, con el vino hay gozo;<br/>Trae a Dios el diezmo de Su fruto en ti.<br/>',NULL,190920,4);
INSERT INTO stanza VALUES('S475','1','Voy laborando en Jesús, mi Canaán,<br/>Planto y riego siguiendo Su plan;<br/>Él rinde fruto de Su realidad,<br/>Es las primicias que_en mí Dios tendrá.<br/>',NULL,190921,1);
INSERT INTO stanza VALUES('S475','chorus','Jesús, ¡Oh buena tierra<br/>Que Dios nos entregó!<br/>Yo paulatinamente<br/>Te_haré mi posesión.<br/>Al laborar la tierra<br/>Dios manda bendición;<br/>Yo gano Tu Persona_así,<br/>Pues eres mi porción.<br/>',NULL,190922,2);
INSERT INTO stanza VALUES('S475','2','Voy laborando en Jesús, mi Señor,<br/>No me lamento, pues yo firme estoy;<br/>Mientras laboro la lluvia tendré;<br/>Obrando en Cristo, ganancia veré.<br/>',NULL,190923,3);
INSERT INTO stanza VALUES('S475','3','Voy laborando en Jesús al orar<br/>Con Su Palabra en mi diario andar;<br/>Sigo en mi espíritu Su viva unción,<br/>Y con los santos yo vivo en unión.<br/>',NULL,190924,4);
INSERT INTO stanza VALUES('S475','4','Voy laborando en Jesús para dar<br/>A las reuniones sustancia real;<br/>Allí los hombres con Dios hallarán<br/>En Su presencia disfrute eternal.<br/>',NULL,190925,5);
INSERT INTO stanza VALUES('S475','5','Ve laborando en Jesús, tu porción,<br/>Y luego tráelo a cada reunión;<br/>El excedente ofrece a tu Dios,<br/>Come con gozo y bendice al Señor.<br/>',NULL,190926,6);
INSERT INTO stanza VALUES('S476','1','La verdadera_adoración<br/>Moisés, en tipos, nos mostró;<br/>Con el producto de Canaán<br/>El pueblo adoró a Dios.<br/>',NULL,190927,1);
INSERT INTO stanza VALUES('S476','2','Debemos hoy así venir,<br/>Para_adorar en realidad:<br/>Trayendo_a Cristo, el fruto que<br/>A nuestro Dios satisfará.<br/>',NULL,190928,2);
INSERT INTO stanza VALUES('S476','3','La_adoración que quiere Dios<br/>No es producto del maná,<br/>Sino de laborar en Él<br/>Para tener qué presentar.<br/>',NULL,190929,3);
INSERT INTO stanza VALUES('S476','4','Así, lo que desea Dios<br/>No son milagros por doquier,<br/>Sino a diario, tan normal,<br/>Vivir y laborar en Él.<br/>',NULL,190930,4);
INSERT INTO stanza VALUES('S476','5','De Dios provino el maná,<br/>Mas surge_el fruto del labrar;<br/>¡Mezclándonos con el Señor,<br/>A Dios podemos adorar!<br/>',NULL,190931,5);
INSERT INTO stanza VALUES('S476','6','Vivimos cada día_en Él,<br/>Hoy Cristo nuestro todo es;<br/>Así el fruto ha de ser<br/>La real adoración a Él.<br/>',NULL,190932,6);
INSERT INTO stanza VALUES('S476','7','Ya no buscamos el maná,<br/>Sino a Cristo aplicar;<br/>Así el dulce fruto_habrá,<br/>Que al Señor satisfará.<br/>',NULL,190933,7);
INSERT INTO stanza VALUES('S477','1','Jehová_es mi Pastor para siempre,<br/>En pastos me_hace descansar;<br/>Me guía_a las aguas tranquilas,<br/>¡Oh, cuánto disfrute_Él me da!<br/>',NULL,190934,1);
INSERT INTO stanza VALUES('S477','chorus','Ciertamente el bien y la compasión de Dios<br/>Hasta_el fin, hasta_el fin me seguirán;<br/>Ciertamente el bien y la compasión de Dios<br/>Hasta_el fin siempre me_han de seguir.<br/>Y moraré en la casa de Dios por siempre,<br/>Y cenaré en la mesa con Él.<br/>Ciertamente el bien y la compasión de Dios<br/>Hasta_el fin siempre me_han de seguir.<br/>',NULL,190935,2);
INSERT INTO stanza VALUES('S477','2','El mismo Pastor es mis pastos,<br/>Aguas de reposó a la vez;<br/>Le como y mi espíritu nutre,<br/>Le bebo y Él calma mi sed.<br/>',NULL,190936,3);
INSERT INTO stanza VALUES('S477','3','Mi alma el Pastor me restaura:<br/>Mente, voluntad, emoción,<br/>Y aunque en el valle yo ande,<br/>Conmigo camina el Señor.<br/>',NULL,190937,4);
INSERT INTO stanza VALUES('S477','4','Prepara el Pastor una mesa;<br/>Yo ceno y sufre_el rival;<br/>Me unge con óleo de gozo,<br/>Mi copa rebosando está.<br/>',NULL,190938,5);
INSERT INTO stanza VALUES('S477','5','Ahora yo moro en Su casa,<br/>Disfruto el bien de mi Dios;<br/>Encuentro placer sin medida,<br/>Pues es mi placer mi Señor.<br/>',NULL,190939,6);
INSERT INTO stanza VALUES('S478','1','Mira el arca del ayer,<br/>De acacia_y oro es;<br/>¡Tal humanidad se ve!<br/>¡Gloria a Él! ¡Gloria a Él!<br/>¡Gloria a Él!<br/>',NULL,190940,1);
INSERT INTO stanza VALUES('S478','2','Es Jesús la acacia real;<br/>¡Hombre tan fino y cabal!<br/>Resistió a todo mal.<br/>¡Gloria a Él! ¡Gloria a Él!<br/>¡Gloria a Él!<br/>',NULL,190941,2);
INSERT INTO stanza VALUES('S478','3','El Dios-hombre es Jesús,<br/>¡Qué misterio! ¡Qué virtud!<br/>Un nuevo hombre trajo a luz.<br/>¡Gloria a Él! ¡Gloria a Él!<br/>¡Gloria a Él!<br/>',NULL,190942,3);
INSERT INTO stanza VALUES('S478','4','Por Adán la muerte entró,<br/>Mas Jesús vida nos dio;<br/>Dios al hombre recobró.<br/>¡Gloria a Él! ¡Gloria a Él!<br/>¡Gloria a Él!<br/>',NULL,190943,4);
INSERT INTO stanza VALUES('S478','5','Muchos tipos dan a ver<br/>Que_a Jesús hay que tener,<br/>Debe en nosotros crecer;<br/>¡Digo amén! ¡Oh, Señor!<br/>¡Digo amén!<br/>',NULL,190944,5);
INSERT INTO stanza VALUES('S478','6','Que Tu humanidad, Señor,<br/>Nos sature y, por Tu amor,<br/>Que vean muchos Tu valor;<br/>¡Digo amén! ¡Oh, Señor!<br/>¡Digo amén!<br/>',NULL,190945,6);
INSERT INTO stanza VALUES('S478','note','**La acacia era una madera muy fuerte usada en la construcción del tabernáculo.**<br/>',NULL,190946,7);
INSERT INTO stanza VALUES('S479','1','Haznos ver la necesidad<br/>De una nueva_humanidad;<br/>Nos negamos al yo natural<br/>Sólo comiendo a Jesús.<br/>',NULL,190947,1);
INSERT INTO stanza VALUES('S479','chorus','En la Palabra_y oración<br/>Clama con otros: "Oh, Señor"<br/>Respíralo en comunión,<br/>Come_a Jesús.<br/>',NULL,190948,2);
INSERT INTO stanza VALUES('S479','2','La carne con su corrupción<br/>No cabe_en la edificación;<br/>La humanidad de Cristo es ideal,<br/>Tiene la_esencia divinal.<br/>',NULL,190949,3);
INSERT INTO stanza VALUES('S479','chorus','Queremos por Su vida ser<br/>La casa que desea Él,<br/>La iglesia, el nuevo hombre que<br/>Maduro es.<br/>',NULL,190950,4);
INSERT INTO stanza VALUES('S479','3','Tiene por meta Satanás<br/>A todo hombre arruinar,<br/>Pero el hombre conquistará<br/>Y sobre todo reinará.<br/>',NULL,190951,5);
INSERT INTO stanza VALUES('S479','chorus','Ponemos fin a Satanás<br/>Cuando comemos a Jesús.<br/>Por Su victoria en la cruz<br/>¡El conquistó!<br/>',NULL,190952,6);
INSERT INTO stanza VALUES('S480','1','¡Qué victoria! ¡Oh, qué triunfo!<br/>Dios un hombre vino_a ser,<br/>Con naturaleza_humana,<br/>Para_al diablo_así vencer.<br/>Muerto fue_y resucitado,<br/>Hijo del Hombre es Él.<br/>',NULL,190953,1);
INSERT INTO stanza VALUES('S480','2','Con Sus virtudes humanas<br/>Al astuto arrestó;<br/>Con Su carácter humano<br/>Toda prueba Él pasó.<br/>En mi espíritu lo tomo,<br/>Sus virtudes mías son.<br/>',NULL,190954,2);
INSERT INTO stanza VALUES('S480','3','El Espíritu contiene<br/>Esta vida de Jesús;<br/>Sus virtudes se añadieron<br/>Al divino Espíritu.<br/>¡Oh, qué Espíritu abundante!<br/>¡Suple al hombre en plenitud!<br/>',NULL,190955,3);
INSERT INTO stanza VALUES('S480','4','¡Qué misterio! ¡Qué real es!<br/>Tal Hombre vive en mi ser.<br/>A mi corazón se extiende;<br/>Mi vivir llegando_a ser.<br/>¡Aleluya! ¡Aleluya!<br/>¡Siempre lo alabaré!<br/>',NULL,190956,4);
INSERT INTO stanza VALUES('S480','5','¡Qué glorioso! ¡Qué admirable!<br/>Dios en carne visto es.<br/>En los miembros de Su Cuerpo,<br/>Tal humanidad se ve.<br/>Para edificar Su templo,<br/>Esta vida mía es.<br/>',NULL,190957,5);
INSERT INTO stanza VALUES('S481','1','Hay un supereminente poder,<br/>Que todo_el que creé lo_ha de tener;<br/>Este poder a Jesús levantó,<br/>¡Y_al Cuerpo, Su_iglesia, se dio!<br/>',NULL,190958,1);
INSERT INTO stanza VALUES('S481','chorus','¡Hay poder, poder de resurrección,<br/>Que_a la iglesia se dio!<br/>¡Hay poder, poder de resurrección,<br/>Que a Su Cuerpo lo transmitió!<br/>',NULL,190959,2);
INSERT INTO stanza VALUES('S481','2','Poder que a Cristo a la diestra sentó,<br/>¡Fue dado por Dios! ¡Sí, nos lo dio!<br/>A todo nombre el poder superó,<br/>¡Y al Cuerpo, Su iglesia, se dio!<br/>',NULL,190960,3);
INSERT INTO stanza VALUES('S481','chorus','¡Hay poder, poder para trascender,<br/>Que_a la iglesia se dio!<br/>¡Hay poder, poder para trascender,<br/>Que a Su Cuerpo lo transmitió!<br/>',NULL,190961,4);
INSERT INTO stanza VALUES('S481','3','Poder que todo somete a Sus pies,<br/>¡Y nuestro ahora es! ¡Sí, nuestro es!<br/>Poder completo que todo venció,<br/>¡Y al Cuerpo, Su_iglesia se dio!<br/>',NULL,190962,5);
INSERT INTO stanza VALUES('S481','chorus','¡Hay poder, poder para someter,<br/>Que a la iglesia se dio!<br/>¡Hay poder, poder para someter,<br/>Que a Su Cuerpo lo transmitió!<br/>',NULL,190963,6);
INSERT INTO stanza VALUES('S481','4','Poder que hace Cabeza a Jesús,<br/>¡A Su iglesia dio! ¡Poder le dio!<br/>Poder que exhibe Su fuerza y virtud,<br/>¡Y al Cuerpo, Su iglesia, lo dio!<br/>',NULL,190964,7);
INSERT INTO stanza VALUES('S481','chorus','Hay poder, poder para gobernar,<br/>¡Y a la iglesia se dio!<br/>Hay poder, poder para gobernar,<br/>¡Y a Su Cuerpo lo transmitió!<br/>',NULL,190965,8);
INSERT INTO stanza VALUES('S482','1','Oh, qué gran poder Dios nos demostró<br/>Cuando_al Hijo Él resucitó.<br/>Que podamos ver este gran poder<br/>Y vivir en la resurrección.<br/>',NULL,190966,1);
INSERT INTO stanza VALUES('S482','chorus','¡Este gran poder nos vigoriza,<br/>El poder de Su resurrección!<br/>¡Este gran poder nos vigoriza,<br/>Vigoriza_el hombre interior!<br/>',NULL,190967,2);
INSERT INTO stanza VALUES('S482','2','Alto_es el poder que Dios desplegó,<br/>sobre todos al Hijo alzó.<br/>Principados, poderes, majestad;<br/>Ante Cristo, postrados caerán.<br/>',NULL,190968,3);
INSERT INTO stanza VALUES('S482','chorus','¡Que_el poder que todo lo transciende<br/>Nos eleve en nuestro_interior!<br/>¡Que,_en el hombre interior, nos lleve<br/>En asenso el poder de Dios!<br/>',NULL,190969,4);
INSERT INTO stanza VALUES('S482','3','Cristo recibió gran poder de Dios;<br/>Con poder, Él todo subyugó.<br/>Y Su Cuerpo hoy somos, ¡gloria_a Dios!<br/>¡Todo bajo nuestros pies está!<br/>',NULL,190970,5);
INSERT INTO stanza VALUES('S482','chorus','¡Tal poder que todo lo subyuga,<br/>Todo lo somete_en lo interior!<br/>Tal poder que todo lo subyuga,<br/>Lo somete_al hombre interior.<br/>',NULL,190971,6);
INSERT INTO stanza VALUES('S482','4','Pero lo mejor es que_a Cristo, Dios<br/>Por Cabeza_a la_iglesia lo dio.<br/>Este gran poder sobre todo es;<br/>A la cumbre hoy nos lleva Él.<br/>',NULL,190972,7);
INSERT INTO stanza VALUES('S482','chorus','¡Tal poder que sobre todo reina,<br/>Reina_en lo_exterior y lo_interior!<br/>¡Tal poder que sobre todo reina,<br/>Reina por el hombre interior!<br/>',NULL,190973,8);
INSERT INTO stanza VALUES('S483','1','De_humanidad, el Cristo glorioso se vistió<br/>Para ser mi persona_y que ya no viva yo.<br/>Tal hombre satisface hoy mi necesidad,<br/>Y Su persona me puede reemplazar.<br/>',NULL,190974,1);
INSERT INTO stanza VALUES('S483','chorus','¡Señor, qué hombre eres en verdad!<br/>Te tomo como mi persona y mi_identidad.<br/>Mi ser, Señor, Tú debes subyugar<br/>Para que, en mi corazón, Tú hagas Tu hogar.<br/>',NULL,190975,2);
INSERT INTO stanza VALUES('S483','2','Oh, Cristo el Espíritu habla en mi ser,<br/>¡Su_hablar es incesante! ¡Espíritu es Él!<br/>Su_hablar es agua pura que limpia mi_interior,<br/>Que mi vejez depura_y me_imparte Dios.<br/>',NULL,190976,3);
INSERT INTO stanza VALUES('S483','chorus','¡Señor, Señor, hoy habla en mi ser!<br/>Tu_hablar es Tu presencia, ¡siempre lo quiero tener!<br/>Oh, habla_y limpia todo mi_interior.<br/>Oh, cámbiame y haz Tu_hogar hoy en mi corazón.<br/>',NULL,190977,4);
INSERT INTO stanza VALUES('S483','3','Oh, Cristo_el Novio viene, Su novia obtendrá;<br/>Se nuestro ser Él fluye_y nos glorificará.<br/>Su Persona_es la gloria que_aumenta_en nuestro ser;<br/>Tal gloria_es mi persona, ¡qué gloria es!<br/>',NULL,190978,5);
INSERT INTO stanza VALUES('S483','chorus','Por Tu economía, oh Señor,<br/>Inúndanos de gloria, ¡sí, Señor, satúranos!<br/>En gloria, brota desde nuestro ser,<br/>Y de la iglesia brota más y manifiéstate.<br/>',NULL,190979,6);
INSERT INTO stanza VALUES('S484','1','Sólo Cristo es la realidad,<br/>Pero_aún debemos practicar,<br/>Experimentar hoy en verdad<br/>Todo lo que_Él es.<br/>Cara_a cara se ve_en la_oración,<br/>Su Palabra_es rica_en la reunión,<br/>Mas en nuestra diaria_ocupación<br/>¿Qué hacemos con El?<br/>',NULL,190980,1);
INSERT INTO stanza VALUES('S484','chorus','¡Aleluya! Por Su luz se ve<br/>Cuán real en nuestro ser Él es<br/>Si volvemos simplemente_a Él,<br/>Cada día siendo fiel<br/>A tomarlo cada vez,<br/>Procurando_en todo así ganar<br/>Al Señor en nuestro diario_andar<br/>Como nuestra misma realidad,<br/>El todo Él será.<br/>',NULL,190981,2);
INSERT INTO stanza VALUES('S484','2','Todo lo que la vida nos da<br/>Por el Padre ordenado está,<br/>Todo es una oportunidad.<br/>¡A Cristo ganad!<br/>Cristo_es nuestro contenido real,<br/>Debe_en nuestro ser hoy alumbrar,<br/>Quiere que le demos libertad<br/>Para_así brillar.<br/>',NULL,190982,3);
INSERT INTO stanza VALUES('S484','chorus','Nuestro cuerpo lleva por doquier<br/>La muerte de Cristo siempre en él<br/>Para que Su vida puedan ver;<br/>Aunque el hombre exterior<br/>Se desgaste, el interior<br/>Va alumbrando para reflejar<br/>El tesoro de su realidad<br/>Para que la luz de la verdad<br/>Brille en nuestro ser.<br/>',NULL,190983,4);
INSERT INTO stanza VALUES('S484','chorus','No sólo enseñanza doctrinal,<br/>Mas el peso de la realidad<br/>De este Cristo que reinando está<br/>En nuestra vida hoy.<br/>',NULL,190984,5);
INSERT INTO stanza VALUES('S485','1','Mi viejo hombre con Jesús murió,<br/>Con sus pecados y‿honda corrupción;<br/>Lo serpentino enterrado fue<br/>Llegó_a su fin, y_a este hecho real<br/>Me‿aferro yo.<br/>',NULL,190985,1);
INSERT INTO stanza VALUES('S485','2','Una Persona hay en mi‿espíritu,<br/>Nació como‿un bebé en mí: Jesús,<br/>Quien con la leche pura crecerá,<br/>Y como el interno Vencedor<br/>Conquistará.<br/>',NULL,190986,2);
INSERT INTO stanza VALUES('S485','3','Tú eres mi persona, oh Señor;<br/>Posee Tú todo mi corazón;<br/>El viejo yo murió, mas sigue_allí.<br/>¡Extiéndete, Señor, te pido, haz<br/>Tu_hogar en mí!<br/>',NULL,190987,3);
INSERT INTO stanza VALUES('S485','4','Un solo espíritu con el Señor;<br/>Lo humano y lo divino uno son;<br/>Mas Él mi alma tiene que ganar<br/>Para expresar hoy Su gloriosa<br/>Personalidad.<br/>',NULL,190988,4);
INSERT INTO stanza VALUES('S485','5','Por tanto a Ti te doy mi corazón,<br/>Para que sea Tu hogar, Señor,<br/>Lugar donde te puedas asentar<br/>Y recobrar un solo y nuevo hombre<br/>Para Dios.<br/>',NULL,190989,5);
INSERT INTO stanza VALUES('S486','1','Mi_hombre viejo anulado fue;<br/>En la cruz con el Señor murió;<br/>En nada_aplicado él será;<br/>¡Ya muerto está!<br/>Mi nueva Persona vive_en mí;<br/>Siempre brota como_un manantial;<br/>Fluye caudalosamente_aquí<br/>Vida eternal.<br/>',NULL,190990,1);
INSERT INTO stanza VALUES('S486','chorus','Cristo vive en mi espíritu,<br/>Y mi corazón a Él le doy,<br/>Para que mi hombre interior<br/>Una casa tenga hoy,<br/>Un lugar para vivir:<br/>Esa sea mi plena realidad,<br/>Expresar lo que_Él es para mí,<br/>Y que_habite en mi corazón,<br/>Mi Persona real.<br/>',NULL,190991,2);
INSERT INTO stanza VALUES('S486','2','Esta Persona formada en mí,<br/>Me hace miembro de Su Cuerpo así;<br/>Nunca más independiente actuar,<br/>Sino en unión.<br/>Mi Persona siempre Él debe ser,<br/>Y mi vieja personalidad<br/>Debe totalmente eliminar;<br/>Sea todo Él.<br/>',NULL,190992,3);
INSERT INTO stanza VALUES('S486','chorus','Sólo Cristo tiene que quedar,<br/>Y mis metas tengo que dejar,<br/>Sólo Cristo la iglesia ha de ser<br/>Como el nuevo hombre que<br/>Cumplirá Su eterno plan;<br/>Al mezclarse con la humanidad,<br/>Obtendrá Su propia habitación<br/>Y Su reino Él establecerá<br/>En la tierra hoy.<br/>',NULL,190993,4);
INSERT INTO stanza VALUES('S486','chorus','No lo hará de modo individual,<br/>Mas la iglesia en forma corporal,<br/>Tomando este Cristo para ser<br/>Varón maduro en Él.<br/>',NULL,190994,5);
INSERT INTO stanza VALUES('S487','1','Es mi_anhelo conoerte<br/>Como mi persona hoy,<br/>Que Tu plenitud disfrute<br/>En mi hombre interior.<br/>No de_una manera_externa<br/>O en mi_alma natural;<br/>Mas, Señor, que_al contactarte,<br/>Me poseas en verdad.<br/>',NULL,190995,1);
INSERT INTO stanza VALUES('S487','chorus','Eres mi Persona,<br/>En mi ser hoy moras,<br/>¡Oh, que experimente siempre<br/>Esta realidad!<br/>',NULL,190996,2);
INSERT INTO stanza VALUES('S487','2','Vive el mundo en las tinieblas,<br/>Ocupado en su afán,<br/>Por el alma tan caída<br/>Que controla Satanás.<br/>Éramos así nosotros,<br/>Hasta que vino a reinar<br/>Jesucristo en nuestras vidas,<br/>A quien conocemos ya.<br/>',NULL,190997,3);
INSERT INTO stanza VALUES('S487','3','Como errante yo vagaba<br/>En mi alma sin saber<br/>Que mi espíritu anhelaba<br/>Recibir a Dios en él.<br/>Cuando entró Jesús entonces<br/>Hubo un cambio en mi ser;<br/>Hoy mi espíritu es el centro,<br/>Y la habitación de Él.<br/>',NULL,190998,4);
INSERT INTO stanza VALUES('S487','4','¡Cuán glorioso! Mi persona<br/>Hoy es mi espíritu.<br/>Cristo mismo en mí expresa<br/>Su intención y Su virtud.<br/>No el alma engañosa,<br/>Mas espíritu y verdad.<br/>Cristo ahora es mi Persona,<br/>Mi completa realidad.<br/>',NULL,190999,5);
INSERT INTO stanza VALUES('S488','1','¡Oh, qué_excelente es<br/>Tu ministerio hoy!<br/>Su pacto y sus promesas<br/>Superiores son.<br/>Se_estableció sobre_una ley<br/>Mejor, y eres el Mediador.<br/>',NULL,191000,1);
INSERT INTO stanza VALUES('S488','2','Un pacto aun mejor,<br/>¡Promesas sin igual!<br/>La ley de vida<br/>Y una ofrenda eternal.<br/>Es superior la sangre que<br/>Nos consumó la redención.<br/>',NULL,191001,2);
INSERT INTO stanza VALUES('S488','3','La senda a sanidad<br/>En este pacto está:<br/>La vida en lo interior<br/>Que al alma ha de llegar.<br/>La ley de vida inscrita en<br/>La mente, emoción y voluntad.<br/>',NULL,191002,3);
INSERT INTO stanza VALUES('S488','4','Dejad la antigua ley,<br/>La ley de vida hallad;<br/>La antigua muerte trae,<br/>La nueva vida da.<br/>La letra mata, mas la ley<br/>De vida nos puede ayudar.<br/>',NULL,191003,4);
INSERT INTO stanza VALUES('S488','5','La ley de vida hoy<br/>Ya vemos en función,<br/>Sin nuestro trabajar<br/>Opera en lo interior.<br/>Saturará, para moldearnos<br/>Conforme al Hijo de Dios.<br/>',NULL,191004,5);
INSERT INTO stanza VALUES('S488','6','Quitó el pecado Dios,<br/>Y Su vida impartió;<br/>Somos Su pueblo hoy<br/>Y Dios es nuestro Dios.<br/>En lo interior le conocemos:<br/>¡Qué cuádruple bendición!<br/>',NULL,191005,6);
INSERT INTO stanza VALUES('S488','7','Nos hijifica Dios<br/>Por Su vida interior;<br/>Él nos renueva y hace<br/>La transformación.<br/>Ya hecho está, ¡ahora sólo<br/>Hay que al Hijo alabar!<br/>',NULL,191006,7);
INSERT INTO stanza VALUES('S489','1','Hoy en el trono del Señor<br/>Tenemos un lugar,<br/>Y bajo nuestros pies están<br/>El mundo,_el yo_y Satán.<br/>Cristo_en Su obra lo logró,<br/>Cuando_una vez murió;<br/>Aunque_antes pecadores, ya<br/>Él nos glorificó.<br/>',NULL,191007,1);
INSERT INTO stanza VALUES('S489','2','La vida de iglesia es hoy,<br/>Gloriosa en el Señor;<br/>El cristianismo quedó atrás,<br/>Nuestra vida cambió.<br/>Mente, emoción y voluntad,<br/>Ese santo Lugar,<br/>Dejamos para estar con Dios<br/>En el Santísimo.<br/>',NULL,191008,2);
INSERT INTO stanza VALUES('S489','3','Hoy en el nuevo pacto, Dios<br/>Tres ítems nos legó:<br/>La ley de vida en lo interior,<br/>Para transformación;<br/>Su pueblo Él nos hizo ya,<br/>Y Él es nuestro Dios;<br/>Podemos conocerlo a Él<br/>En nuestro interior.<br/>',NULL,191009,3);
INSERT INTO stanza VALUES('S489','4','Un suplemento Él añadió,<br/>Saberlo nos da paz;<br/>Cristo el pecado eliminó<br/>Dos mil años atrás.<br/>De la memoria lo borró,<br/>Su historia se esfumó;<br/>Opera en nuestro espíritu<br/>La ley de vida hoy.<br/>',NULL,191010,4);
INSERT INTO stanza VALUES('S489','5','Vemos que en la cruz logró<br/>Dos cosas el Señor:<br/>¡La ley de vida, el fin del mal!<br/>La_economía de Dios.<br/>Ya que Su obra allí acabó,<br/>En Su reposo entró;<br/>¡Tomémos lo que nos legó!<br/>Es ésa Su oración.<br/>',NULL,191011,5);
INSERT INTO stanza VALUES('S490','1','Hoy el Hijo del Hombre_en el trono_está;<br/>El Pionero abrió el camino ya;<br/>A Jesús seguiremos; a Él cantad;<br/>Con el Victorioso_al trono_hay que marchar.<br/>',NULL,191012,1);
INSERT INTO stanza VALUES('S490','2','Adelante con Él, al trono llegad;<br/>Esta era oscura crucemos ya;<br/>Fuimos cautivos del cruel rival, Satán;<br/>Mas con el Señor, Dios nos exaltará.<br/>',NULL,191013,2);
INSERT INTO stanza VALUES('S490','3','Nos llamó hijos y hemos de reinar,<br/>Y a lo mundanal no volvemos más;<br/>No somos aptos, y lo sabemos bien,<br/>Pero Cristo purifica nuestro ser.<br/>',NULL,191014,3);
INSERT INTO stanza VALUES('S490','4','Oh Señor, quema todo_en nuestro_interior;<br/>Purifica totalmente_el corazón.<br/>Sin temor; claro está que al refinar<br/>Nos visitas Tú, Señor, y gracia das.<br/>',NULL,191015,4);
INSERT INTO stanza VALUES('S490','5','Con el Hombre_en el trono podemos ver<br/>Un arco iris que declara que_Él es fiel;<br/>Merecimos el juicio de nuestro Dios,<br/>Mas lo alabamos, ¡Él nos libertó!<br/>',NULL,191016,5);
INSERT INTO stanza VALUES('S491','1','Yo sé que vive_el Redentor,<br/>Por mí orando_está;<br/>Su_amor Él me otorga hoy,<br/>Me da Su libertad.<br/>',NULL,191017,1);
INSERT INTO stanza VALUES('S491','2','Yo sé que vive_el Redentor,<br/>Y vida eterna da;<br/>Vivificante_Espíritu,<br/>Es gracia sin igual.<br/>',NULL,191018,2);
INSERT INTO stanza VALUES('S491','3','Él mi cabeza_eleva hoy<br/>Me trae salvación;<br/>En Su presencia_hay libertad,<br/>Y muy pronto vendrá.<br/>',NULL,191019,3);
INSERT INTO stanza VALUES('S491','4','Anhela Él mi santidad,<br/>¡Su gracia lo hará!<br/>Pues Su divina voluntad,<br/>Él siempre cumplirá.<br/>',NULL,191020,4);
INSERT INTO stanza VALUES('S491','5','En Tu palabra firme_estoy:<br/>Por siempre creceré;<br/>Por mí regresarás, Señor;<br/>Contigo estaré.<br/>',NULL,191021,5);
INSERT INTO stanza VALUES('S492','1','Yo ciego fui; no pude ver<br/>La gracia en Tu_herida faz;<br/>Mas hoy Tu_hermoso rostro_aquí<br/>Yo veo en su esplendor.<br/>',NULL,191022,1);
INSERT INTO stanza VALUES('S492','2','Yo sordo fui; no pude oír<br/>La melodía de Tu voz;<br/>Mas hoy Te oigo, ¡qué placer!<br/>Preciosas Tus palabras son.<br/>',NULL,191023,2);
INSERT INTO stanza VALUES('S492','3','Yo mudo fui; jamás conté<br/>La gloria de Tu nombre fiel;<br/>Tu fuego, mis labios tocó,<br/>Y_ahora, siempre_alabo yo.<br/>',NULL,191024,3);
INSERT INTO stanza VALUES('S492','4','Yo muerto estuve: no logré<br/>Llevar mi alma muerta a Ti;<br/>Mas hoy Tu vida a mi llegó,<br/>Y del sepulcro salgo yo.<br/>',NULL,191025,4);
INSERT INTO stanza VALUES('S492','5','Por Ti, Jesús, el ciego vio,<br/>El sordo oyó, el mudo habló,<br/>El muerto vive, y hoy yo,<br/>Soy libre de la esclavitud.<br/>',NULL,191026,5);
INSERT INTO stanza VALUES('S493','1','Mi Dios, mi amor y mi porción,<br/>Mi herencia eternal,<br/>En todo el universo no hay<br/>Ninguno que sea igual.<br/>Ninguno que sea igual.<br/>',NULL,191027,1);
INSERT INTO stanza VALUES('S493','2','¡Oh, qué vacío el cielo está!<br/>La tierra es vanidad,<br/>No llena nada el corazón,<br/>Mi Dios es realidad.<br/>Mi Dios es realidad.<br/>',NULL,191028,2);
INSERT INTO stanza VALUES('S493','3','Riquezas y prosperidad,<br/>Salud o amigo fiel,<br/>De Ti todo lo recibí,<br/>Mas eres Tú mi bien.<br/>Mas eres Tú mi bien.<br/>',NULL,191029,3);
INSERT INTO stanza VALUES('S493','4','Qué vano es mi bienestar,<br/>Al compararlo a Ti;<br/>Así es mi paz y protección,<br/>O algún amigo aquí.<br/>O algún amigo aquí.<br/>',NULL,191030,4);
INSERT INTO stanza VALUES('S493','5','Si fuera mío el orbe hoy<br/>Y las estrellas mil,<br/>Yo sin Tu gracia y Tu ser<br/>Sería un infeliz.<br/>Sería un infeliz.<br/>',NULL,191031,5);
INSERT INTO stanza VALUES('S493','6','Que sigan otros la ambición<br/>De abarcar el mar;<br/>Visítame en Tu gracia hoy,<br/>Y no te pido más.<br/>Y no te pido más.<br/>',NULL,191032,6);
INSERT INTO stanza VALUES('S494','1','Nos llamas hoy, Señor, para Canaán ganar<br/>Como Tu cuerpo y contigo_allí morar,<br/>Mas este mundo_escuro nos quiere_estorbar.<br/>Oh, aparécete, Señor.<br/>',NULL,191033,1);
INSERT INTO stanza VALUES('S494','chorus','Hoy aparécete, Señor;<br/>Es el camino único<br/>Para_ídolos dejar<br/>Y gozar de Canaán.<br/>Oh, aparécete, Señor.<br/>',NULL,191034,2);
INSERT INTO stanza VALUES('S494','2','Atraenos, Dios de gloria,_a ir en pos de Ti;<br/>Sé nuestra fuerza Tú, oh haznos proseguir.<br/>¡Hoy nos atrae Tu luz, disipa todo_aquí!<br/>Oh, resplandece hoy, Señor.<br/>',NULL,191035,3);
INSERT INTO stanza VALUES('S494','chorus','Oh, resplandece_en nuestro ser,<br/>Haz lo demás desvanecer<br/>Al verte sólo_a Ti,<br/>Al verte recluir;<br/>Oh, resplandece hoy, Señor.<br/>',NULL,191036,4);
INSERT INTO stanza VALUES('S494','3','En Tu aparición tenemos Tu hablar;<br/>Tu_hablar nos da poder, y el temor se va.<br/>Sigue llamándonos, queremos escuchar.<br/>Oh, háblanos, Señor, amén.<br/>',NULL,191037,5);
INSERT INTO stanza VALUES('S494','chorus','Oh, en nosotros habla hoy;<br/>Tú sabes qué decir, Señor.<br/>En nuestro corazón,<br/>Tu ser impártenos.<br/>Oh, en nosotros habla hoy.<br/>',NULL,191038,6);
INSERT INTO stanza VALUES('S494','4','No_es de nosotros, esto todo Tuyo es;<br/>Tú_eres quien llama, Originador también.<br/>Podemos responder hoy contemplándote.<br/>Oramos: ¡Dios de gloria, ven!<br/>',NULL,191039,7);
INSERT INTO stanza VALUES('S494','chorus','Oramos: ¡Dios de gloria, ven!<br/>Pues hoy queremos responder<br/>A Tu llamado fiel.<br/>¡Hoy nuestro todo sé!<br/>Oramos: ¡Dios de gloria, ven!<br/>',NULL,191040,8);
INSERT INTO stanza VALUES('S495','1','¡Qué glorioso! ¡Oh, qué santo!<br/>¡Vida eterna es nuestro Dios!<br/>¡Poderoso, ilimitado,<br/>Lleno de toda compasión!<br/>Qué riquezas en Su vida:<br/>Su esencia, luz y amor.<br/>',NULL,191041,1);
INSERT INTO stanza VALUES('S495','2','¡Qué amoroso! ¡Oh, qué gracia!<br/>¡Para el hombre, vida es Dios!<br/>Formó espíritu en el hombre,<br/>Conforme al plan que Él trazó.<br/>Que este hombre lo reciba<br/>Es Su anhelo e intención.<br/>',NULL,191042,2);
INSERT INTO stanza VALUES('S495','3','¡Qué amor e inmensa gracia!<br/>¡Vida al hombre fluye Dios!<br/>Se mostró primero en carne,<br/>Mas el Espíritu es hoy;<br/>Para propagar Su vida<br/>Tal proceso Él pasó.<br/>',NULL,191043,3);
INSERT INTO stanza VALUES('S495','4','¡Qué accesible! ¡Qué cercano!<br/>¡Hoy Dios en Cristo vida es!<br/>Cristo, el Dios encarnado,<br/>Manifestado al hombre es.<br/>Muerto y resucitado,<br/>Vida al hombre viene a ser.<br/>',NULL,191044,4);
INSERT INTO stanza VALUES('S495','5','¡Qué asombroso! ¡Esta vida<br/>Dios en el hombre la impartió!<br/>Al tomar Su otra forma<br/>Como Espíritu entró.<br/>Lo convence, lo inspira,<br/>Y hace en él Su habitación.<br/>',NULL,191045,5);
INSERT INTO stanza VALUES('S495','6','¡Qué glorioso! ¡Qué precioso!<br/>¡Conocer al Triuno Dios!<br/>Vino el Padre en el Hijo,<br/>Mas el Espíritu es hoy.<br/>Este Espíritu al hombre<br/>Le trae la vida de Dios<br/>',NULL,191046,6);
INSERT INTO stanza VALUES('S495','7','¡Qué misterio, pero es cierto!<br/>¡El mismo Dios fluye en mi ser!<br/>Él conmigo se hizo uno<br/>Para mi vida ahora ser.<br/>¡Aleluya! ¡Aleluya!<br/>¡Siempre le alabaré!<br/>',NULL,191047,7);
INSERT INTO stanza VALUES('S496','1','En mi espíritu hoy brota un manantial,<br/>El Triuno Dios fluyendo_está;<br/>Padre: fuente_eternal; Cristo el Hijo:_el canal,<br/>Y_el Espíritu vida me da.<br/>',NULL,191048,1);
INSERT INTO stanza VALUES('S496','chorus','Cuánto_aprecio el dulce fluir,<br/>Y la vida de mi_alma negar;<br/>Profundiza, Señor, el fluir<br/>Y la vida mi premio será.<br/>',NULL,191049,2);
INSERT INTO stanza VALUES('S496','2','En los pastos, Jesús me hace_allí descansar,<br/>Me guía_en reposo a vivir,<br/>No más luchas ni afán, todo esfuerzo es trivial;<br/>Bendecido soy en el fluir.<br/>',NULL,191050,3);
INSERT INTO stanza VALUES('S496','3','De Jesús escuché: "Al Santísimo ven,<br/>Aquí en Mi presencia a morar".<br/>Aleluya, con Él puedo permanecer<br/>En la vid, siendo un pámpano fiel.<br/>',NULL,191051,4);
INSERT INTO stanza VALUES('S497','1','Vida_es Dios el Padre en Jesucristo,<br/>Fluye como_Espíritu_en mi ser;<br/>¡Qué Persona rica para disfrutar!<br/>Nuestra vida_en plenitud es Él.<br/>',NULL,191052,1);
INSERT INTO stanza VALUES('S497','2','Experimentamos nueva vida<br/>Cuando abrimos nuestro ser a Él;<br/>Nos regeneró, Su misma vida entró,<br/>Que nos va inundando con Su Ser.<br/>',NULL,191053,2);
INSERT INTO stanza VALUES('S497','3','Él es el Espíritu viviente,<br/>Fluye en mi espíritu también;<br/>Hasta transformar, mi mente renovar,<br/>Por la vida que impartiendo está.<br/>',NULL,191054,3);
INSERT INTO stanza VALUES('S497','4','Mi cooperación Él necesita,<br/>Al fijar la mente en el Señor;<br/>Del pensar errante vuelvo yo mi ser,<br/>Hasta que se fije sólo en Él.<br/>',NULL,191055,4);
INSERT INTO stanza VALUES('S497','5','Nuestro espíritu hoy te contiene,<br/>Pero aún Tu plan quieres lograr;<br/>Si me despojara del viejo pensar,<br/>Gozaría de Tu vida y paz.<br/>',NULL,191056,5);
INSERT INTO stanza VALUES('S497','6','¡Oh, captura cada pensamiento,<br/>Tu Palabra me renovará;<br/>Ella cambiará mi mente natural<br/>Hasta mi pensar santificar.<br/>',NULL,191057,6);
INSERT INTO stanza VALUES('S497','7','Vamos practicando este principio:<br/>De ocupar la mente en el Señor;<br/>De Él emana nuestro modo de vivir,<br/>¡Qué maravilloso estar en Él!<br/>',NULL,191058,7);
INSERT INTO stanza VALUES('S498','1','La vida es misteriosa, vida_es Dios;<br/>Todo Su_enfoque con el hombre es.<br/>El árbol de la vida Dios lo dio,<br/>Para un hombre de vida_obtener.<br/>',NULL,191059,1);
INSERT INTO stanza VALUES('S498','2','Fue seducido el hombre y pecó,<br/>De otra fuente, recibió el saber;<br/>Por tal conocimiento, él cayó;<br/>Así el hombre dominado fue.<br/>',NULL,191060,2);
INSERT INTO stanza VALUES('S498','3','Trajo_el saber a la humanidad<br/>Toda cultura que en la tierra está;<br/>El hombre que era para el plan de Dios<br/>Por su caída, expresa a Satanás.<br/>',NULL,191061,3);
INSERT INTO stanza VALUES('S498','4','Más tarde como Hijo vino Dios,<br/>Vivió en la tierra, se llamó Jesús;<br/>Fue un modelo vivo para que<br/>La vida el hombre obtenga en plenitud<br/>',NULL,191062,4);
INSERT INTO stanza VALUES('S498','5','Este Dios-hombre en la cruz murió,<br/>Y_al viejo hombre_allí aniquiló;<br/>Lo negativo así crucificó,<br/>Y una nueva vida comenzó.<br/>',NULL,191063,5);
INSERT INTO stanza VALUES('S498','6','Venció a la muerte y resucitó<br/>Como el Espíritu que vida da;<br/>Cuando se creé en Su nombre al invocar<br/>El entra a nuestro ser para morar.<br/>',NULL,191064,6);
INSERT INTO stanza VALUES('S498','7','De este modo el mismo Triuno Dios<br/>Como Espíritu al nuestro entró.<br/>Los dos se unen y se mezclan hoy,<br/>Así un solo espíritu ellos son.<br/>',NULL,191065,7);
INSERT INTO stanza VALUES('S498','8','Por este Espíritu es nuestro andar,<br/>Nuestro vivir hacer proviene de Él.<br/>¡En este Espíritu estamos hoy!<br/>Y Él la plenitud de Dios nos da.<br/>',NULL,191066,8);
INSERT INTO stanza VALUES('S498','9','Por eso hay que poner la mente en Él.<br/>Y ocuparla en Él sin distracción.<br/>Para que por la vida que Él nos da,<br/>Reinemos y gocemos salvación.<br/>',NULL,191067,9);
INSERT INTO stanza VALUES('S498','10','Por este Espíritu hay liberación<br/>De muerte, del pecado, y de su ley;<br/>La vida hasta el cuerpo llegará,<br/>Santificando todo nuestro ser.<br/>',NULL,191068,10);
INSERT INTO stanza VALUES('S498','11','Este Espíritu nos salvará<br/>Del yo, y el Cuerpo edificará;<br/>Al transformarnos, nos conformará<br/>A Cristo para así cumplir Su plan.<br/>',NULL,191069,11);
INSERT INTO stanza VALUES('S498','12','Vida es Dios, y Cristo vida es,<br/>Vida es el Espíritu también.<br/>Hasta que llegue nuestra redención<br/>Sólo esta vida la manera es.<br/>',NULL,191070,12);
INSERT INTO stanza VALUES('S499','1','Nuestro Dios vive; di: "¡Aleluya!"<br/>Vive en nosotros; di: "¡Aleluya!"<br/>De Sus riquezas<br/>Participamos,<br/>Prueba y ve, di: "¡Oh Señor!"<br/>',NULL,191071,1);
INSERT INTO stanza VALUES('S499','2','Siempre al reunirnos como familia<br/>Su Espíritu hace que seamos uno,<br/>Su Cuerpo vivo,<br/>Para expresarlo,<br/>Cristo es nuestra realidad.<br/>',NULL,191072,2);
INSERT INTO stanza VALUES('S499','3','En las iglesias, Dios nos satura<br/>Con las riquezas de Su grosura.<br/>Llevando a Cristo<br/>A cada pueblo,<br/>Esta nación verá a Jesús.<br/>',NULL,191073,3);
INSERT INTO stanza VALUES('S500','1','Dios es luz,<br/>Y en Él no‿existe la‿oscuridad;<br/>En Su presencia, ¡cuánto_amamos estar!<br/>¡En Su luz disfrutamos un constante limpiar,<br/>Del vil pecar!<br/>',NULL,191074,1);
INSERT INTO stanza VALUES('S500','chorus','(**Hnas:**)     En la luz<br/>(**Hnos:**)     Hoy andamos.<br/>(**Hnas:**)     Comunión<br/>(**Hnos:**)     Disfrutamos.<br/>(**Hnas:**)     Siendo así<br/>(**Hnos:**)     Limpios por<br/>(**Todos:**)    La sangre de Jesús.<br/>(**Hnas:**)     Fiel es Dios,<br/>(**Hnos:**)     Confesamos.<br/>(**Hnas:**)     Justo es Él:<br/>(**Hnos:**)     Nos perdona.<br/>(**Hnas:**)     ¡Qué gozo es!<br/>(**Hnos:**)     Limpios ser<br/>(**Todos:**)    Del vil pecar.<br/>',NULL,191075,2);
INSERT INTO stanza VALUES('S501','1','¡Qué gran misterio es el Dios Tri-u-no!<br/>Una esencia_en tres hipóstasis*;<br/>El Padre en el Hijo se introduce<br/>Por el Espíritu a nuestro ser.<br/>',NULL,191076,1);
INSERT INTO stanza VALUES('S501','chorus','¡El Triuno Dios hoy nuestro todo es!<br/>¡Admirable! ¡Glorioso es Él!<br/>¡Divino Don que_excede_a todo bien!<br/>¡Qué excelso es en nuestro ser!<br/>',NULL,191077,2);
INSERT INTO stanza VALUES('S501','2','¡Oh, qué caudal, el Padre es la fuente<br/>Y Sus riquezas quiere al hombre dar!<br/>¡Esta porción inagotable es nuestra,<br/>Paro apreciar y siempre disfrutar!<br/>',NULL,191078,3);
INSERT INTO stanza VALUES('S501','3','El Hijo es la expresión del Padre,<br/>Que en carne vino a la humanidad;<br/>¡Qué redención perfecta y efectiva!<br/>¡Hoy disfrutamos con Dios la unidad!<br/>',NULL,191079,4);
INSERT INTO stanza VALUES('S501','4','El Hijo hoy está transfigurado,<br/>Y como Espíritu vida nos da;<br/>¡Gran hecho es! ¡Su Espíritu viviente<br/>Mezclado con el nuestro en unidad!<br/>',NULL,191080,5);
INSERT INTO stanza VALUES('S501','5','¡Qué realidad que nuestro Dios ahora,<br/>Es el Espíritu para tocar!<br/>¡Qué gran verdad! ¡En vida somos uno<br/>Con nuestro Dios sin diferir jamás!<br/>',NULL,191081,6);
INSERT INTO stanza VALUES('S501','note','**Hipóstasis: del griego hypóstasis; un soporte subyacente, una sustancia que sostiene. Véase la nota 1 de 2 Cor. 13:14, Santa Biblia Versión Recobro.**<br/>',NULL,191082,7);
INSERT INTO stanza VALUES('S502','1','Por Tu misterio doy loor,<br/>Pues yo te puedo contactar;<br/>Eras inaccesible Tú,<br/>Mas hoy Tu_Espíritu nos das.<br/>',NULL,191083,1);
INSERT INTO stanza VALUES('S502','2','El Padre, Hijo, Espíritu:<br/>El Triuno Dios, mi vida es;<br/>Tu misma esencia en mi ser<br/>Naturaleza santa es.<br/>',NULL,191084,2);
INSERT INTO stanza VALUES('S502','3','El Triuno Dios ahora es<br/>Espíritu en consumación;<br/>Lo puedo experimentar<br/>Como aliento y viento hoy.<br/>',NULL,191085,3);
INSERT INTO stanza VALUES('S502','4','Lo que el Padre tiene y es<br/>En Su amado Hijo está;<br/>Y Sus riquezas hoy posee<br/>Su Espíritu de realidad.<br/>',NULL,191086,4);
INSERT INTO stanza VALUES('S502','5','Su Espíritu, llegando a mí,<br/>En mi espíritu entró;<br/>El Padre en el Hijo así<br/>Se constituye mi porción.<br/>',NULL,191087,5);
INSERT INTO stanza VALUES('S502','6','La fuente es el Padre Dios;<br/>El Hijo es toda Su expresión;<br/>Y como el Espíritu,<br/>Es el fluir en mi_interior.<br/>',NULL,191088,6);
INSERT INTO stanza VALUES('S502','7','Vino en el Hijo el Padre Dios<br/>Para expresarse al hombre aquí;<br/>El Hijo como Espíritu<br/>Revela a Dios dentro de mí.<br/>',NULL,191089,7);
INSERT INTO stanza VALUES('S502','8','El Padre quiere al Hijo dar<br/>En todo el primer lugar;<br/>El Hijo lo toma_al Padre así<br/>Como cabeza y realidad.<br/>',NULL,191090,8);
INSERT INTO stanza VALUES('S502','9','Desea el Espíritu<br/>Al Hijo hoy glorificar;<br/>Pues lo revela en mi interior<br/>Para de Él testificar.<br/>',NULL,191091,9);
INSERT INTO stanza VALUES('S502','10','Tú como el Espíritu<br/>Deseas nuestra adoración;<br/>Tocándote en mi espíritu<br/>Hoy Tus riquezas mías son.<br/>',NULL,191092,10);
INSERT INTO stanza VALUES('S502','11','Si vivo en mi espíritu<br/>Y rindo a Ti mi adoración,<br/>Yo toco al Santo Espíritu,<br/>Y te disfruto en comunión.<br/>',NULL,191093,11);
INSERT INTO stanza VALUES('S503','1','Es por Su_Espíritu que Dios<br/>Hoy se transmite_a nuestro ser;<br/>Se_experimenta sólo_así<br/>Al Dios que_en Cristo nuestro es.<br/>',NULL,191094,1);
INSERT INTO stanza VALUES('S503','2','El Padre Dios la fuente es;<br/>El Hijo es Dios en Su expresión;<br/>Como Espíritu entra Dios<br/>A nuestro ser como porción.<br/>',NULL,191095,2);
INSERT INTO stanza VALUES('S503','3','El Padre en luz oculto está;<br/>El Hijo al hombre lo mostró;<br/>Lo transmite_el Espíritu,<br/>Y lo revela en lo interior.<br/>',NULL,191096,3);
INSERT INTO stanza VALUES('S503','4','Dentro del Padre el Hijo está,<br/>Hoy el Espíritu es Él;<br/>Padre, Hijo y Espíritu<br/>Uno son hoy con nuestro ser.<br/>',NULL,191097,4);
INSERT INTO stanza VALUES('S503','5','El Padre en el Hijo está<br/>Corporificado en verdad;<br/>El Hijo con Su realidad,<br/>Dios el Espíritu nos da.<br/>',NULL,191098,5);
INSERT INTO stanza VALUES('S503','6','Venga del Padre Su amor,<br/>Del Hijo, gracia y comunión<br/>Por el Espíritu de Dios,<br/>Para tenerlo por porción.<br/>',NULL,191099,6);
INSERT INTO stanza VALUES('S504','1','Dios en sustancia_Espíritu_es,<br/>Su_esencia santa_y divinal,<br/>Para tocar Su_Espíritu,<br/>Mi_espíritu_he de_ejercitar.<br/>',NULL,191100,1);
INSERT INTO stanza VALUES('S504','2','En el hombre, su espíritu<br/>Es lo mas hondo y real;<br/>Para tocar en vida a Dios,<br/>Debe su espíritu usar.<br/>',NULL,191101,2);
INSERT INTO stanza VALUES('S504','3','Sólo en el espíritu<br/>Se debe al Padre adorar;<br/>Su Espíritu viene a morar<br/>En el nuestro en unidad.<br/>',NULL,191102,3);
INSERT INTO stanza VALUES('S504','4','Su Espíritu a mi espíritu<br/>Llama y hace la unidad;<br/>Su Espíritu es vida en mí,<br/>Y el mío llega a ser Su hogar.<br/>',NULL,191103,4);
INSERT INTO stanza VALUES('S504','5','Si en Sus riquezas quiero entrar,<br/>Su Espíritu debo tocar;<br/>Sólo con mi espíritu<br/>Puedo al Padre adorar.<br/>',NULL,191104,5);
INSERT INTO stanza VALUES('S504','6','La comunión debe llevar<br/>Al hombre a su_espíritu;<br/>Allí él debe orar y hallar<br/>Respuesta del Espíritu.<br/>',NULL,191105,6);
INSERT INTO stanza VALUES('S504','7','Debemos en espíritu<br/>Orar a Dios y a Él servir,<br/>Crecer en vida, edificar,<br/>Para a Cristo exhibir.<br/>',NULL,191106,7);
INSERT INTO stanza VALUES('S504','8','Señor, yo quiero hoy volver<br/>Al espíritu y_aprender<br/>Cómo tocar Tu Espíritu,<br/>Hasta que fluyas en mi ser.<br/>',NULL,191107,8);
INSERT INTO stanza VALUES('S505','1','Dios anhela proveerme<br/>Con Su mismo ser;<br/>En mi_espíritu por eso<br/>Me uno_a Él.<br/>',NULL,191108,1);
INSERT INTO stanza VALUES('S505','chorus','Todo lo de Dios hoy fluye<br/>En Su_Espíritu;<br/>Le conozco_ejercitando<br/>Mi_espíritu.<br/>',NULL,191109,2);
INSERT INTO stanza VALUES('S505','2','Su naturaleza rica<br/>Me ha dado Él;<br/>En mi espíritu lo toco<br/>Para ésta ver.<br/>',NULL,191110,3);
INSERT INTO stanza VALUES('S505','3','Con mi espíritu lo toco,<br/>No con mi pensar;<br/>Si mi espíritu no uso,<br/>Falto he de estar.<br/>',NULL,191111,4);
INSERT INTO stanza VALUES('S505','4','Cuando escucho los mensajes,<br/>Los tengo que orar;<br/>En mi espíritu digiero<br/>Todo el hablar.<br/>',NULL,191112,5);
INSERT INTO stanza VALUES('S505','5','Al Señor en la Palabra<br/>Tengo que tocar;<br/>Si la estudio en mi mente,<br/>Muerta estará.<br/>',NULL,191113,6);
INSERT INTO stanza VALUES('S505','6','¡Oh, qué gloria, qué riquezas<br/>En Su Espíritu!<br/>Mías son cuando ejercito<br/>Mi espíritu.<br/>',NULL,191114,7);
INSERT INTO stanza VALUES('S506','1','Más cerca quiero estar,<br/>Mi Dios, de Ti;<br/>Aunque sea por la cruz,<br/>Llévame_a Ti.<br/>Que sea mi canción;<br/>Más cerca de mi Dios,<br/>Más cerca de mi Dios,<br/>Cerca de Ti.<br/>',NULL,191115,1);
INSERT INTO stanza VALUES('S506','2','Como un errante soy;<br/>El sol se fue.<br/>Sobre una piedra hoy<br/>Descansaré;<br/>Mas soñaré que_estoy<br/>Más cerca de mi Dios,<br/>Más cerca de mi Dios,<br/>Cerca de Ti.<br/>',NULL,191116,2);
INSERT INTO stanza VALUES('S506','3','Del cielo abierto aquí,<br/>Dame visión;<br/>Todo me das a mí<br/>Con compasión.<br/>Me llamas en Tu amor<br/>Más cerca de mi Dios,<br/>Más cerca de mi Dios,<br/>Cerca de Ti.<br/>',NULL,191117,3);
INSERT INTO stanza VALUES('S506','4','Luego, al salir el sol,<br/>Te alabaré;<br/>De mi tribulación,<br/>Bet-el haré.<br/>Me lleve la aflicción<br/>Más cerca de mi Dios,<br/>Más cerca de mi Dios,<br/>Cerca de Ti.<br/>',NULL,191118,4);
INSERT INTO stanza VALUES('S507','1','Tú, dulce voluntad de Dios,<br/>Mi fortaleza, mi_ancla fiel,<br/>Morada a mi_espíritu<br/>En Ti me_escondo_y quieto_estoy.<br/>',NULL,191119,1);
INSERT INTO stanza VALUES('S507','2','Tu voluntad es sólo el bien,<br/>Tú, el mejor, condúceme;<br/>Un niño soy, te seguiré,<br/>Confiando en Ti descansaré.<br/>',NULL,191120,2);
INSERT INTO stanza VALUES('S507','3','Su voluntad endulzará<br/>Lo amargo, y triunfa al final;<br/>Sin la aprobación de Dios,<br/>Gloria en los gozos no habrá.<br/>',NULL,191121,3);
INSERT INTO stanza VALUES('S507','4','Tu dulce voluntad, mi Dios,<br/>Es un abrazo protector;<br/>Mi voluntad cautiva está,<br/>En ámbito de gracia real.<br/>',NULL,191122,4);
INSERT INTO stanza VALUES('S507','5','En este plácido lugar<br/>Extiende alas el amor,<br/>O anida en Tu elección,<br/>Que siempre agrada al corazón.<br/>',NULL,191123,5);
INSERT INTO stanza VALUES('S507','6','Carga ligera ésta es;<br/>Qué dulce el yugo en verdad;<br/>Da alas a mi corazón,<br/>Pues Tu control es libertad.<br/>',NULL,191124,6);
INSERT INTO stanza VALUES('S507','7','Reposo en Tu voluntad,<br/>Cual niño en seno maternal;<br/>No existe un lecho que podrá<br/>Darme descanso tan real.<br/>',NULL,191125,7);
INSERT INTO stanza VALUES('S507','8','Oh, Tu grandiosa voluntad,<br/>Triunfante, la hago mía ya;<br/>¡Amén!, mi fe responderá<br/>A cada orden que Tú das.<br/>',NULL,191126,8);
INSERT INTO stanza VALUES('S508','1','Torrente poderoso_es Dios,<br/>Que fluye para siempre;<br/>Se procesó para_alcanzar<br/>Al hombre_en Su corriente;<br/>Mas sólo_un Dios es Él<br/>Que fluye_a nuestro ser;<br/>Sus pasos claves son,<br/>A Su impartición,<br/>¡Y hoy fluye en nosotros!<br/>',NULL,191127,1);
INSERT INTO stanza VALUES('S508','2','En el principio se ve a Dios<br/>Como un río fluyente;<br/>Conlleva el árbol dentro de él<br/>Al mismo Dios viviente.<br/>También en el final,<br/>Fluyendo el río está<br/>Con el Cordero-Dios,<br/>Y el árbol que creció,<br/>¡Dios fluye eternamente!<br/>',NULL,191128,2);
INSERT INTO stanza VALUES('S508','3','Fluyó en un hombre el mismo Dios,<br/>El hombre Jesucristo.<br/>La vida de Dios liberó<br/>Con sumo sacrificio.<br/>Aunque intentó Satán<br/>Aquel fluir parar,<br/>Crucificáronle,<br/>Y cruel la lanza fue,<br/>Mas salió agua y sangre.<br/>',NULL,191129,3);
INSERT INTO stanza VALUES('S508','4','De Su costado así fluyó<br/>Sangre para limpiarnos,<br/>Y agua allí también brotó<br/>Para regenerarnos.<br/>Hoy el Espíritu<br/>Nos brinda a Jesús;<br/>Sólo logró el rival<br/>Librar el manantial,<br/>Y Dios sigue fluyendo.<br/>',NULL,191130,4);
INSERT INTO stanza VALUES('S509','1','La‿intención que tiene Dios<br/>Se centra en la‿humanidad;<br/>Él se hizo el Espíritu<br/>Para‿en el hombre‿entrar.<br/>De Su‿economía todos podemos participar.<br/>¡Sí, es por el mezclar!<br/>',NULL,191131,1);
INSERT INTO stanza VALUES('S509','chorus','¡Mezcla, mezcla, aleluya!<br/>¡Mezcla, mezcla, aleluya!<br/>¡Mezcla, mezcla, aleluya!<br/>¡Sí, es por el mezclar!<br/>',NULL,191132,2);
INSERT INTO stanza VALUES('S509','2','En el centro de_este hombre,<br/>Más allá del alma, hay<br/>Un lugar por Dios creado<br/>Que_el Señor ha de llenar;<br/>Desde_allí el Dios fluyente<br/>Nuestro ser saturará.<br/>¡Sí, es por el mezclar!<br/>',NULL,191133,3);
INSERT INTO stanza VALUES('S509','3','Ya tenemos la manera<br/>En el recobro del Señor,<br/>De tocar al Dios Triuno<br/>Y andar en Cristo hoy:<br/>Al vivir en el espíritu<br/>Mezclado, en unión.<br/>¡Sí, es por el mezclar!<br/>',NULL,191134,4);
INSERT INTO stanza VALUES('S509','4','Entre siete candeleros<br/>El Hijo del Hombre_está,<br/>Con ardientes pies y ojos,<br/>Su recobro obtendrá.<br/>Su_intención está́logrando:<br/>Esta única_entidad.<br/>¡Sí, es por el mezclar!<br/>',NULL,191135,5);
INSERT INTO stanza VALUES('S509','5','En nuestro vivir a diario,<br/>Al hacer y al pensar,<br/>Esta mezcla requerimos<br/>Para del Señor ganar;<br/>Hoy, Señor, nos consagramos<br/>Para esto practicar.<br/>¡Sí, es por el mezclar!<br/>',NULL,191136,6);
INSERT INTO stanza VALUES('S509','6','Tal vivir produce fruto:<br/>La Nueva Jerusalén;<br/>Esta_humanidad divina,<br/>Del mezclar la cumbre es.<br/>¡Oh, que gozo compartirlo!<br/>Lógralo, Señor,¡amén!<br/>¡Sí, es por el mezclar!<br/>',NULL,191137,7);
INSERT INTO stanza VALUES('S510','1','Desde_el norte_un tempestuoso viento hay;<br/>¡Sopla ya! ¡Sopla ya!<br/>En nuestra experiencia, él a Dios nos trae;<br/>¡Sopla ya! ¡Sopla ya!<br/>',NULL,191138,1);
INSERT INTO stanza VALUES('S510','chorus','Soplará el viento con poder,<br/>A la vida nos traerá;<br/>Soplará con gracia divinal,<br/>Y en Cristo nos pondrá.<br/>',NULL,191139,2);
INSERT INTO stanza VALUES('S510','2','Hoy detrás del viento una nube va;<br/>¡Cúbrenos! ¡Cúbrenos!<br/>La presencia del Señor la nube trae;<br/>¡Cúbrenos! ¡Cúbrenos!<br/>',NULL,191140,3);
INSERT INTO stanza VALUES('S510','chorus','¡Cubrirá! Dios nos ha cubrir,<br/>Con Su nube cubrirá,<br/>¡Cubrirá! Su gracia, al cubrir,<br/>Fuerza y gozo nos dará.<br/>',NULL,191141,4);
INSERT INTO stanza VALUES('S510','3','Con la nube_un fuego resplandecerá;<br/>¡Arderá! ¡Arderá!<br/>Se verá_el pecado y nuestro yo carnal;<br/>¡Arderá! ¡Arderá!<br/>',NULL,191142,5);
INSERT INTO stanza VALUES('S510','chorus','¡Arderá! Su llama arderá,<br/>Con Su celo arderá;<br/>Arderá Su llama en nuestro ser,<br/>Hasta todo incinerar.<br/>',NULL,191143,6);
INSERT INTO stanza VALUES('S510','4','El electro desde_el fuego brillará;<br/>¡Brillará! ¡Brillará!<br/>El Dios redentor así se expresará;<br/>¡Brillará! ¡Brillará!<br/>',NULL,191144,7);
INSERT INTO stanza VALUES('S510','chorus','Brillará y todos lo verán,<br/>¡Oro y plata divinal!<br/>El Cordero-Dios en nuestro ser:<br/>Un disfrute celestial.<br/>',NULL,191145,8);
INSERT INTO stanza VALUES('S510','5','Viento, nube, fuego y electro, hoy<br/>Fórjalos sin cesar<br/>En nosotros, como un ciclo, oh Señor,<br/>Más y más, más y más.<br/>',NULL,191146,9);
INSERT INTO stanza VALUES('S510','chorus','Sopla, cubre, arde_y brilla,_oh Dios,<br/>Hasta nuestro ser ganar;<br/>Para que podamos Tuyos ser,<br/>Y Tu_imagen expresar.<br/>',NULL,191147,10);
INSERT INTO stanza VALUES('S511','1','Desde_el norte viene_el viento,<br/>Desde donde_habita Dios.<br/>Nuestro ser es capturado:<br/>¡El Espíritu sopló!<br/>Este viento nos despierta,<br/>Nos conmueve_en lo_interior.<br/>Hoy la nube_así desciende,<br/>Nos abrimos ya a Dios.<br/>',NULL,191148,1);
INSERT INTO stanza VALUES('S511','2','Es la nube Su presencia:<br/>Permanece y cubre Dios;<br/>Hoy confiamos plenamente,<br/>Pues cercano está el Señor.<br/>Mas la nube trae fuego<br/>Que consume nuestro yo;<br/>Y lo celestial podemos<br/>Recibir en lo interior.<br/>',NULL,191149,2);
INSERT INTO stanza VALUES('S511','3','En el fuego algo brilla<br/>Es electro en su esplendor.<br/>¡Dios es oro, el hombre, plata:<br/>Hoy mezclados en unión!<br/>El metal tan refulgente<br/>Es nuestro Cordero-Dios.<br/>Como electro, resplandece,<br/>Fórjate en nuestro interior.<br/>',NULL,191150,3);
INSERT INTO stanza VALUES('S511','4','Al pasar por este ciclo,<br/>Expresamos a Jesús,<br/>Siendo los seres vivientes;<br/>Con Él, uno en plenitud.<br/>Lo expresamos como hombre<br/>Fino en Su humanidad,<br/>Tan normal y equilibrado,<br/>Mas también tan divinal.<br/>',NULL,191151,4);
INSERT INTO stanza VALUES('S511','5','Cual león, lo expresamos,<br/>Conquistando al rival;<br/>Y cual buey en obediencia<br/>Para siempre ministrar.<br/>Como águila expresamos<br/>Este trascendente Dios,<br/>Quien se eleva sin temores<br/>Sobre todo en ascensión.<br/>',NULL,191152,5);
INSERT INTO stanza VALUES('S511','6','¡Aleluya! ¡Qué figura<br/>De los tratos hoy con Dios!<br/>Viento, nube, fuego, electro<br/>Y criaturas en unión;<br/>Hoy los cuatro: buey y hombre,<br/>Águila, también león,<br/>Lo expresan plenamente<br/>Al comer más del Señor.<br/>',NULL,191153,6);
INSERT INTO stanza VALUES('S512','1','Dios es justo en Sus hechos,<br/>Sus caminos rectos son;<br/>Es perfecto_en Sus acciones<br/>Y merece todo_honor.<br/>Justo_es lo que Él requiere,<br/>Justa_es Su condenación;<br/>Pecadores para juicio,<br/>Ya la ley nos declaró.<br/>',NULL,191154,1);
INSERT INTO stanza VALUES('S512','2','Por la ley fuimos juzgados,<br/>Mas Su amor ya nos libró;<br/>Dios pasó Su juicio al Hijo,<br/>Su justicia Él cumplió.<br/>Para Dios nos compró Cristo,<br/>¡Aleluya al Redentor!<br/>Justicia de Dios nos hace<br/>Gracias a Su redención.<br/>',NULL,191155,2);
INSERT INTO stanza VALUES('S512','3','Su naturaleza es santa,<br/>Todo en Dios es santidad;<br/>Él se une a nosotros<br/>Y nos santificará,<br/>Del espíritu se expande,<br/>A todo nuestro interior;<br/>Renovando cada parte,<br/>Nos satura el corazón.<br/>',NULL,191156,3);
INSERT INTO stanza VALUES('S512','4','¡Es precioso el proceso!<br/>Salva en vida el Señor;<br/>Día a día, nuestra vida<br/>Es constante salvación.<br/>Si fijamos nuestra mente,<br/>Sólo en nuestro espíritu;<br/>Él nos gana y nos transforma,<br/>Por Su amor y Su virtud.<br/>',NULL,191157,4);
INSERT INTO stanza VALUES('S512','5','Gloria es Dios expresado,<br/>Lo que es Él en Su expresión,<br/>Se verá en nuestros cuerpos,<br/>Cuando alcancen redención.<br/>Esta vida santifica:<br/>Gloria es Su consumación;<br/>Y la meta de la vida<br/>Es la transfiguración.<br/>',NULL,191158,5);
INSERT INTO stanza VALUES('S512','6','Qué gloriosa expectativa:<br/>Él nos arrebatará.<br/>Y la tierra ha de verlo:<br/>Cristo a Dios exhibirá.<br/>Siempre así lo expresaremos,<br/>Todos los hijos de Dios;<br/>Manifestando Su gloria,<br/>Gozo para la creación.<br/>',NULL,191159,6);
INSERT INTO stanza VALUES('S512','7','Qué destino tan glorioso:<br/>¡Con piedad nos escogió!<br/>No es del que quiere o corre,<br/>Mas por voluntad de Dios.<br/>Fuimos olivo silvestre,<br/>Mas, en Cristo, ramas hoy;<br/>Creceremos para el reino,<br/>¡Cristo en Él nos injertó!<br/>',NULL,191160,7);
INSERT INTO stanza VALUES('S512','8','Disfrutamos por Su vida,<br/>Nuestra santificación;<br/>Es la vida de iglesia,<br/>Suministro y bendición.<br/>Aquí Dios es nuestro gozo,<br/>Oh, ¡qué práctico y real!<br/>Hijos somos, herederos,<br/>En la iglesia hasta el final.<br/>',NULL,191161,8);
INSERT INTO stanza VALUES('S513','1','En el monte Calvario estaba_una cruz,<br/>El emblema de_afrenta_y dolor,<br/>Mas yo amo_esa cruz do murió mi Jesús<br/>Por salvar al más vil pecador.<br/>',NULL,191162,1);
INSERT INTO stanza VALUES('S513','chorus','¡Oh, yo siempre amaré esa cruz!<br/>En sus triunfos, mi gloria será;<br/>Y_algún día en vez de_una cruz,<br/>Mi corona Jesús me dará.<br/>',NULL,191163,2);
INSERT INTO stanza VALUES('S513','2','Aunque el mundo desprecie la cruz de Jesús,<br/>Para mí tiene suma atracción;<br/>Pues en ella llevó el Cordero de Dios<br/>De mi alma, la condenación.<br/>',NULL,191164,3);
INSERT INTO stanza VALUES('S513','3','En la cruz de Jesús do Su sangre vertió,<br/>Hermosura contemplo sin par;<br/>Pues allí mi Jesús padeció y murió<br/>Para darme el perdón y la paz.<br/>',NULL,191165,4);
INSERT INTO stanza VALUES('S513','note','**Nota: Registrada, 1913. Reanudada 1941; Propiedad de The Rodeheaver Company. Usada con permiso.**<br/>',NULL,191166,5);
INSERT INTO stanza VALUES('S514','1','La cruz muy firme_está,<br/>¡Aleluya! ¡Aleluya!<br/>Y aniquila_el mal,<br/>¡Aleluya! ¡Aleluya!<br/>El Hades la retó,<br/>El mundo la odió,<br/>Mas ella resistió,<br/>¡Aleluya por la cruz!<br/>',NULL,191167,1);
INSERT INTO stanza VALUES('S514','chorus','¡Aleluya! ¡Aleluya!<br/>¡Aleluya por la cruz!<br/>¡Aleluya! ¡Aleluya!<br/>¡Nunca pierde su virtud!<br/>',NULL,191168,2);
INSERT INTO stanza VALUES('S514','2','Por siglos firme está,<br/>¡Aleluya! ¡Aleluya!<br/>Su triunfo proclamad,<br/>¡Aleluya! ¡Aleluya!<br/>La gracia aquí brilló,<br/>En Cristo el Salvador,<br/>Quien redención ganó,<br/>¡Aleluya por la cruz!<br/>',NULL,191169,3);
INSERT INTO stanza VALUES('S514','3','Jesús allí murió,<br/>¡Aleluya! ¡Aleluya!<br/>La deuda Él saldó,<br/>¡Aleluya! ¡Aleluya!<br/>Cantamos hoy de Aquel<br/>Que nuestra ofrenda es,<br/>De Cristo, nuestro Rey,<br/>¡Aleluya por la cruz!<br/>',NULL,191170,4);
INSERT INTO stanza VALUES('S515','1','Junto_a la cruz de Cristo<br/>Anhelo siempre_estar;<br/>La sombra de_esa Peña fiel<br/>Refugio_a mi_alma da.<br/>En el desierto de calor,<br/>En ella hallo_hogar;<br/>De toda carga puedo yo<br/>En ella descansar.<br/>',NULL,191171,1);
INSERT INTO stanza VALUES('S515','2','¡Seguro y contento<br/>En tal refugio estoy,<br/>Do la justicia y_el amor<br/>Se_encuentran en unión!<br/>Así como el patriarca vio<br/>En sueño la visión,<br/>Mi Salvador es, por la cruz,<br/>Tal escalera hoy.<br/>',NULL,191172,2);
INSERT INTO stanza VALUES('S515','3','Al lado de su sombra<br/>Se puede observar<br/>La tumba atróz abierta allí<br/>Y negra oscuridad;<br/>Mas entre ella y yo, la cruz<br/>Se extiende con amor;<br/>Dos brazos que pueden salvar<br/>De eterna perdición.<br/>',NULL,191173,3);
INSERT INTO stanza VALUES('S515','4','Sobre la cruz de Cristo<br/>Mis ojos pueden ver<br/>La forma del que allí sufrió y<br/>Murió para mi bien.<br/>Hoy mi contrito corazón<br/>Confiesa la verdad<br/>De Su maravilloso amor<br/>Y de mi indignidad.<br/>',NULL,191174,4);
INSERT INTO stanza VALUES('S515','5','Tu cruz será, oh Cristo,<br/>Mi eterna habitación;<br/>Yo sólo pido ver Tu faz<br/>Que brilla más que el sol.<br/>Contento, dejo el mundo atrás;<br/>No hallo allí virtud,<br/>Avergonzado de mi yo,<br/>Mi gloria es Tu cruz.<br/>',NULL,191175,5);
INSERT INTO stanza VALUES('S516','1','¿Habrá dolor si hoy tomáramos la cruz?<br/>No sólo_habrá dolor, más bien nos matará;<br/>Si la_experimentamos, hemos de morir,<br/>Ella_está puesta para_el yo aniquilar.<br/>',NULL,191176,1);
INSERT INTO stanza VALUES('S516','2','El hombre que la cruz fulmina, libre es,<br/>Parece cruel, pero es divina salvación;<br/>Sólo es por la cruz que Cristo puede ser<br/>Vida a nosotros, y nosotros, Su expresión.<br/>',NULL,191177,2);
INSERT INTO stanza VALUES('S516','3','Tiene la cruz por meta el deseo de Dios,<br/>Pero el yo se opone a Su voluntad;<br/>La vida anímica se debe eliminar,<br/>La voluntad de Dios así prosperará.<br/>',NULL,191178,3);
INSERT INTO stanza VALUES('S517','1','Si no se exprime la_oliva,<br/>Aceite no_habrá;<br/>Si no se pisan las uvas,<br/>Vino no se obtendrá;<br/>Si no se machaca_el nardo,<br/>Su olor no saldrá;<br/>¿Rehuiré los sufrimientos<br/>Que Tu_amor me proveerá?<br/>',NULL,191179,1);
INSERT INTO stanza VALUES('S517','chorus','Con cada golpe<br/>Ganancia me das;<br/>En lugar de lo que quitas<br/>A Ti mismo Tú me das.<br/>',NULL,191180,2);
INSERT INTO stanza VALUES('S517','2','¿Necesitas compungirme<br/>Para dar loor?<br/>¿Para eso es necesario<br/>Un cruel trato de Tu amor?<br/>Privación, Señor, no temo,<br/>Si me lleva a Ti;<br/>Plenamente yo me rindo<br/>Para ver Tu amor por mí.<br/>',NULL,191181,3);
INSERT INTO stanza VALUES('S517','3','Señor, siento hoy vergüenza,<br/>Mi ego protegí;<br/>Aunque Tú me has podado,<br/>Tu tratar yo resistí.<br/>Tu deseo sea cumplido<br/>Obra Tú en mí;<br/>Sin mirar mis sentimientos,<br/>Haz lo que te plazca a Ti.<br/>',NULL,191182,4);
INSERT INTO stanza VALUES('S517','4','Aunque yo no esté de acuerdo,<br/>Sea Tu voluntad;<br/>Si te place darme penas,<br/>El "Amén" te quiero dar.<br/>Mi deseo es agradarte,<br/>Aunque sufra más;<br/>Por Tu complacencia y gloria<br/>Yo la cruz quiero llevar.<br/>',NULL,191183,5);
INSERT INTO stanza VALUES('S517','5','Aún con lágrimas, te alabo,<br/>Ésta es mi canción;<br/>Tu dulzura que aumenta,<br/>Hoy me trae inspiración.<br/>Más preciado a mí te has hecho,<br/>Todo eres, Señor;<br/>Que Tú crezcas y yo mengüe<br/>Es mi anhelo y oración.<br/>',NULL,191184,6);
INSERT INTO stanza VALUES('S518','1','Por Belén peregrinamos,<br/>Puesto_el corazón en Dios;<br/>De Jesús así_aprendemos,<br/>Como infantes, Su dolor;<br/>El pesebre y_el establo<br/>Poco placenteros son;<br/>Mas si nuestros pies lo siguen,<br/>Nos dará Su galardón.<br/>',NULL,191185,1);
INSERT INTO stanza VALUES('S518','2','¡Luego_en Nazaret! la senda<br/>Más angosta llega a ser;<br/>Nadie comprendió Su vida,<br/>Mas debemos aprender<br/>Que no es mayor el siervo<br/>Que el Señor, quien rechazó<br/>Toda gloria de este mundo,<br/>Aunque llores, sigue en pos.<br/>',NULL,191186,2);
INSERT INTO stanza VALUES('S518','3','Al pasar por Galilea,<br/>Piedras arrojadas son<br/>Por los que al Señor rodean,<br/>¿No erró Su dirección?<br/>¡No! El Salvador, ileso,<br/>Su propósito siguió;<br/>En la senda prosigamos,<br/>Firmes siempre en el Señor.<br/>',NULL,191187,3);
INSERT INTO stanza VALUES('S518','4','He aquí, la horrible angustia<br/>Llegando a Getsemaní,<br/>Do las fuerzas del maligno<br/>Todo el ser han de oprimir,<br/>Mas los ángeles ministran<br/>Y alientan nuestra fe:<br/>"Oh, amados, ved la gloria;<br/>¡El conflicto corto es!".<br/>',NULL,191188,4);
INSERT INTO stanza VALUES('S518','5','¡A la cruz!, pues el Calvario<br/>Todos debemos pasar;<br/>Indescriptible_es la senda,<br/>Solo Él la puede mostrar;<br/>"Si con Él sufrimos", dice,<br/>Por un poco tiempo aquí,<br/>Se disipará el recuerdo<br/>Por Su sonrisa feliz.<br/>',NULL,191189,5);
INSERT INTO stanza VALUES('S518','6','Luego al sepulcro vamos,<br/>Donde ya vida no hay;<br/>(¿Sois aquellos que los hombres<br/>Consideran muertos ya?)<br/>Levantados y entronados<br/>Juntamente con Jesús,<br/>Rechazamos lo que el mundo<br/>Cuenta como "vida" aún.<br/>',NULL,191190,6);
INSERT INTO stanza VALUES('S518','7','¡Prosigamos, peregrinos!<br/>Pues muy cerca se ve hoy<br/>La ciudad esplendorosa<br/>Que nos edifica Dios.<br/>Ya se escuchan melodías<br/>Con los cánticos de Aquel<br/>Que murió para llevarnos<br/>A Su trono junto a Él.<br/>',NULL,191191,7);
INSERT INTO stanza VALUES('S518','8','¡Unas millas más, amados!<br/>Nuestros pies descansarán;<br/>No más duelo ni pecado,<br/>¡Ved! Jesús delante está<br/>Y susurra dulcemente;<br/>"No temáis, aun seguid;<br/>Puede ser que ya mañana<br/>Llegue el viaje a su fin".<br/>',NULL,191192,8);
INSERT INTO stanza VALUES('S519','1','La cruz un camino_angosto es,<br/>Si a Dios todo se da;<br/>Todo lo que se ponga en el altar<br/>El fuego consumirá.<br/>',NULL,191193,1);
INSERT INTO stanza VALUES('S519','chorus','¿Estás listó_a tomar cada día tu cruz?<br/>Para ti, ¿qué es la cruz hoy llevar?<br/>Tú que_has dado tu ser y tu todo a Dios,<br/>¿A Dios eres tú leal?<br/>',NULL,191194,2);
INSERT INTO stanza VALUES('S519','2','Qué fácil decir en la reunión,<br/>"Por Ti todo dejo yo!"<br/>Hasta que una cruz más pesada hay<br/>Que exige tu atención.<br/>',NULL,191195,3);
INSERT INTO stanza VALUES('S519','3','¿Vacilas entonces o eres fiel<br/>A morir tú en la cruz,<br/>Hasta que en tu vida el viviente Dios<br/>Te brinda Su plenitud?<br/>',NULL,191196,4);
INSERT INTO stanza VALUES('S519','4','Si quieres vivir hay que morir<br/>En la cruz con Tu Señor,<br/>Y así vivirás por la vida de Aquel<br/>Que vive en resurrección.<br/>',NULL,191197,5);
INSERT INTO stanza VALUES('S520','1','Si resurrección anhelo,<br/>Tengo que la cruz amar;<br/>De la muerte surge vida,<br/>De la pérdida,_el ganar.<br/>',NULL,191198,1);
INSERT INTO stanza VALUES('S520','chorus','Muerte vida trae,<br/>Muerte vida trae,<br/>Surge vida de la muerte,<br/>Muerte vida trae.<br/>',NULL,191199,2);
INSERT INTO stanza VALUES('S520','2','Para que se forme Cristo<br/>En mi ser, debo morir,<br/>La vida del alma pierdo<br/>Al bajo la cruz vivir.<br/>',NULL,191200,3);
INSERT INTO stanza VALUES('S520','3','Si me clava Dios con Cristo<br/>Por Su Espíritu a la cruz;<br/>Sólo así, Su muerte obrando<br/>Vida en mí saldrá a la luz.<br/>',NULL,191201,4);
INSERT INTO stanza VALUES('S521','1','Hoy la vid consideremos,<br/>De su vida_hay que_aprender:<br/>Sólo_en medio de_aflicciones<br/>puede ella_así crecer.<br/>Muy distinta de_esas flores<br/>Que,_en silvestre confusión,<br/>Crecen libres en los campos<br/>Sin ninguna restricción.<br/>',NULL,191202,1);
INSERT INTO stanza VALUES('S521','2','Mas las flores en la viña<br/>Son sin gloria ni atracción;<br/>Tan pequeñas de tamaño,<br/>Sin ninguna expresión.<br/>Una vez que_han florecido,<br/>Nunca más se exhibirán,<br/>Pues jamás serán carolas;<br/>Sólo el fruto se verá.<br/>',NULL,191203,2);
INSERT INTO stanza VALUES('S521','3','A un poste está atada,<br/>Pierde así su libertad;<br/>Luego de crecer, sus ramas<br/>Amarradas estarán.<br/>Desde el suelo endurecido<br/>Saca ella nutrición;<br/>Nunca elije su camino<br/>Ni se aparta de aflicción.<br/>',NULL,191204,3);
INSERT INTO stanza VALUES('S521','4','El verdor de su hermosura<br/>Coloreando el campo va;<br/>Llena de energía viva,<br/>Plenitud podrá lograr;<br/>Hasta que con tiernas ramas<br/>Que se enredan llena esté,<br/>Alcanzando el azul cielo<br/>Para el aire absorber.<br/>',NULL,191205,4);
INSERT INTO stanza VALUES('S521','5','Mas el amo de la viña<br/>Indulgente nunca es;<br/>Va podando, muy preciso,<br/>Despojando la altivez.<br/>Aunque esté la vid muy tierna,<br/>Con preciso atinar,<br/>Todo pámpano excedente<br/>De la vid él cortará.<br/>',NULL,191206,5);
INSERT INTO stanza VALUES('S521','6','Al sufrir la vid el daño,<br/>¿Tendrá autocompasión?<br/>No, más bien se entrega plena<br/>A aquel que la podó,<br/>A la mano que desgarra<br/>Y le roba su belleza,<br/>Para que su vida entera<br/>Pueda siempre fruto dar.<br/>',NULL,191207,6);
INSERT INTO stanza VALUES('S521','7','Donde se cortó la rama,<br/>La madera seca está;<br/>Mas los pámpanos restantes<br/>Ahora fruto pueden dar.<br/>Luego, bajo el sol candente,<br/>Hojas secas caerán;<br/>Mas el fruto así madura<br/>Y la mies se segará.<br/>',NULL,191208,7);
INSERT INTO stanza VALUES('S521','8','Encorvada por la carga<br/>De su fruto a granel:<br/>El producto de las penas<br/>Que la hizo así crecer.<br/>Con su fruto ya maduro,<br/>Consolada debe estar;<br/>Mas apremia la cosecha<br/>Y más penas sufrirá.<br/>',NULL,191209,8);
INSERT INTO stanza VALUES('S521','9','Con las manos se recogen<br/>Las riquezas de la vid;<br/>Con los pies se va hollando,<br/>Hasta el vino conseguir.<br/>Todo el día fluye un río<br/>Del buen vino del lagar,<br/>Rico, dulce y dando gozo<br/>Hasta la tierra llenar.<br/>',NULL,191210,9);
INSERT INTO stanza VALUES('S521','10','Hasta aquí, en su apariencia,<br/>Luce seca esta vid;<br/>Todo dio y ahora en entra<br/>En la noche cruel sin fin,<br/>Nadie ofrece con pagarle<br/>Por su vino alegrador;<br/>Mas la cortan hasta el tronco,<br/>Desgajada y sin valor.<br/>',NULL,191211,10);
INSERT INTO stanza VALUES('S521','11','Con su vino, en el invierno<br/>Trae dulzura y calor<br/>A los que de frío tiemblan<br/>Con tristeza y dolor.<br/>Sin embargo, a la interperie,<br/>La vid en la nieve está,<br/>Soportando allí su suerte,<br/>¡Qué difícil de explicar!<br/>',NULL,191212,11);
INSERT INTO stanza VALUES('S521','12','Pasa el frío y se prepara<br/>La vid para fruto dar;<br/>Floreciendo, echando ramas,<br/>Con verdor tan singular,<br/>No se queja ni murmura<br/>De ese frío invernal<br/>Ni por pérdidas sufridas;<br/>Sólo fruto quiere dar.<br/>',NULL,191213,12);
INSERT INTO stanza VALUES('S521','13','Respirando el aire limpio,<br/>Busca hallar lo celestial;<br/>No se ocupa de lo impuro,<br/>Ni de afecto terrenal.<br/>Al sufrir, aún sonríe<br/>Mientras la poda el amor;<br/>Nuevos golpes ya recibe<br/>Sin fijarse en el dolor.<br/>',NULL,191214,13);
INSERT INTO stanza VALUES('S521','14','Fluye savia, vino y sangre<br/>De las ramas de la vid;<br/>¿Es acaso ella más pobre<br/>Por ceder y por sufrir?<br/>Los borrachos de la tierra,<br/>De_ella gozan al tomar;<br/>Mas, por todo su deleite,<br/>¿Son más ricos al final?<br/>',NULL,191215,14);
INSERT INTO stanza VALUES('S521','15','No se mide lo ganado,<br/>Sino lo que se perdió;<br/>No el vino ya bebido,<br/>Sino aquel que se vertió.<br/>El amor nos fortalece<br/>Para todo soportar;<br/>Y quien más ha padecido,<br/>Mucho más puede brindar.<br/>',NULL,191216,15);
INSERT INTO stanza VALUES('S521','16','Quien consigo es severo,<br/>Es quien Dios puede ganar;<br/>El que no se considera,<br/>Puede a otros consolar.<br/>El que nunca aguanta penas<br/>Sólo es "bronce que resuena";<br/>El que su alma no escatima,<br/>Tiene gozo sin igual.<br/>',NULL,191217,16);
INSERT INTO stanza VALUES('S522','1','Enterrada, pero es<br/>La semilla que tal vez<br/>Puede_un día_alimentar<br/>Continentes con su pan.<br/>',NULL,191218,1);
INSERT INTO stanza VALUES('S522','2','¡Enterrada, oculta está<br/>En la negra oscuridad!<br/>Todo allí ya se perdió,<br/>Todo excepto el mismo Dios.<br/>',NULL,191219,2);
INSERT INTO stanza VALUES('S522','3','Enterrada: al parecer,<br/>Para el hombre nada es,<br/>Mas Dios no la olvidará;<br/>Vida un día brotará.<br/>',NULL,191220,3);
INSERT INTO stanza VALUES('S522','4','¿Enterrado estás tú hoy?<br/>¿Ya te sangra el corazón?<br/>Canta, no lamentes más,<br/>Sólo así la mies vendrá.<br/>',NULL,191221,4);
INSERT INTO stanza VALUES('S523','1','"Naufragado en Jesús",<br/>¡Qué victoria_así cantar!<br/>Botes que temen zarpar<br/>Por temor al hondo mar,<br/>Nunca en Jesús tendrán<br/>La paz que_en Su seno está.<br/>',NULL,191222,1);
INSERT INTO stanza VALUES('S523','2','"¡Naufragar!" es un clamor<br/>Que nos hace lamentar;<br/>Mas al alma, viva aún<br/>En los brazos del Señor,<br/>No la mueve lo peor,<br/>Abrazada en Su amor.<br/>',NULL,191223,2);
INSERT INTO stanza VALUES('S523','3','"¡Naufragado!", al no tener<br/>Ya ni un barco en que viajar;<br/>El viajero ahora está<br/>Anclado a la infinidad,<br/>Deseschando la inquietud<br/>Y asiéndose a Jesús.<br/>',NULL,191224,3);
INSERT INTO stanza VALUES('S523','4','"Naufragar" ganancia fue;<br/>Otros barcos ya verán<br/>Que en tormenta hay bendición,<br/>Y, aunque agitado el mar,<br/>Dios vigila siempre, iel;<br/>En "naufragios", guarda Él.<br/>',NULL,191225,4);
INSERT INTO stanza VALUES('S524','1','Muerte no impide la resurrección,<br/>La vida_eterna que se_encuentra_en Dios,<br/>Indestructible e_increada, es<br/>El Cristo_invicto en Su expresión.<br/>',NULL,191226,1);
INSERT INTO stanza VALUES('S524','2','Muerte no impide la resurrección,<br/>Aunque su fuerza contra ella esté;<br/>Sólo le da la oportunidad,<br/>De que la vida muestre Su poder.<br/>',NULL,191227,2);
INSERT INTO stanza VALUES('S524','3','Muerte no impide la resurrección,<br/>Al enterrarla, se acrecentará;<br/>Los sufrimientos la hacen crecer más,<br/>Y muchos frutos de vida llevar.<br/>',NULL,191228,3);
INSERT INTO stanza VALUES('S524','4','Muerte no impide la resurrección,<br/>Cada barrera puede penetrar;<br/>Vence al infierno y todo su poder,<br/>Sorbe la muerte y triunfa sobre el mal.<br/>',NULL,191229,4);
INSERT INTO stanza VALUES('S524','5','Muerte no impide la resurrección,<br/>La plenitud de Dios expresará;<br/>Justicia y santidad producirá,<br/>De Dios la imagen manifestará.<br/>',NULL,191230,5);
INSERT INTO stanza VALUES('S524','6','Oh, que conozca la resurrección,<br/>En cualquier muerte grande es su poder,<br/>Que en mi experiencia pueda realizar,<br/>Que el Cristo vivo esta vida es.<br/>',NULL,191231,6);
INSERT INTO stanza VALUES('S525','1','De muerte, ¡vida!  ¿Para cuándo es esto?<br/>¿Es para ahora, o el más allá?<br/>¿Por qué_esperar? El vaso quebrantado<br/>El Alfarero puede hoy moldear.<br/>',NULL,191232,1);
INSERT INTO stanza VALUES('S525','2','De muerte, ¡vida! ¡Qué resurrección es!<br/>El grano muerto dando su poder;<br/>Tu vida en mí vivida en aflicciones,<br/>No yo, mas vive Cristo en mi ser.<br/>',NULL,191233,2);
INSERT INTO stanza VALUES('S525','3','De muerte, ¡vida! Senda solitaria<br/>De los que se glorían en la cruz.<br/>Viven con Cristo en comunión tan dulce<br/>Dejando todo sólo por Jesús.<br/>',NULL,191234,3);
INSERT INTO stanza VALUES('S525','4','De muerte, ¡vida! ¡Qué misión bendita!<br/>El agua viva a todos llevar;<br/>Vida abundante de ese río puro,<br/>Para el que quiera su sed apagar.<br/>',NULL,191235,4);
INSERT INTO stanza VALUES('S526','1','"Detrás del velo", vuestra porción sea,<br/>Morando en secreto_en el Señor;<br/>Mirándolo, hasta que vuestro rostro<br/>Muestre Su_amor y gloria en loor.<br/>',NULL,191236,1);
INSERT INTO stanza VALUES('S526','2','"Detrás del velo", pues si contemplamos<br/>La hermosura de Su faz sin par,<br/>Seremos una revelación viva<br/>De Su insondable gracia y gran amor.<br/>',NULL,191237,2);
INSERT INTO stanza VALUES('S526','3','"Detrás del velo", hallemos Su fragancia,<br/>Fuera del velo, esta fragancia dad;<br/>"Detrás del velo", Él toca melodías<br/>Para en la tierra alabanzas dar.<br/>',NULL,191238,3);
INSERT INTO stanza VALUES('S526','4','"Detrás del velo", espíritu anclado,<br/>En paz andamos, libres de ansiedad;<br/>"Detrás del velo", el alma a Él unida,<br/>Tendrá Su vida de resurrección.<br/>',NULL,191239,4);
INSERT INTO stanza VALUES('S527','1','Contémplalo‿a diario<br/>Con Cristo‿habla más;<br/>Come Su Palabra<br/>Para‿en Él morar.<br/>Siempre‿en Su presencia<br/>Sumiso a Él;<br/>Su bendición busca<br/>En todo tu‿hacer.<br/>',NULL,191240,1);
INSERT INTO stanza VALUES('S527','2','Contémplalo‿a diario,<br/>El mundo se va;<br/>Ten tiempo‿en secreto<br/>Con Él, nada más.<br/>Mirando a Cristo,<br/>Como‿Él tú serás;<br/>En ti tus amigos<br/>Su‿imagen verán.<br/>',NULL,191241,2);
INSERT INTO stanza VALUES('S527','3','Contémplalo‿a diario,<br/>Que te guíe Él;<br/>No te le‿anticipes<br/>Doquiera que estés.<br/>En gozo ó‿en pena<br/>A Cristo ve, tú,<br/>Ten fe‿en Su Palabra<br/>Mirando‿a Jesús.<br/>',NULL,191242,3);
INSERT INTO stanza VALUES('S527','4','Contémplalo‿a diario,<br/>Calma‿el corazón,<br/>Pon tus sentimientos<br/>Bajo Su control.<br/>Su‿Espíritu guía<br/>A fuentes de‿amor,<br/>Allí Él te viste<br/>De Su compasión.<br/>',NULL,191243,4);
INSERT INTO stanza VALUES('S528','1','A Jesús miramos,<br/>¡Sin jamás ceder!<br/>Sobre la_armadura,<br/>Escudo de fe;<br/>Nuestro estandarte<br/>Es Su salvación;<br/>Sea elevado,<br/>¡Al mundo venció!<br/>',NULL,191244,1);
INSERT INTO stanza VALUES('S528','chorus','A Jesús miramos,<br/>¡Sin jamás ceder!<br/>Sobre la_armadura,<br/>Escudo de fe.<br/>',NULL,191245,2);
INSERT INTO stanza VALUES('S528','2','Si a Jesús miramos,<br/>Sin ver lo demás,<br/>No tropezaremos<br/>Ni caeremos más.<br/>Nos libra de trampas<br/>Y del tentador;<br/>Estamos a salvo<br/>Viendo al Señor.<br/>',NULL,191246,3);
INSERT INTO stanza VALUES('S528','3','Al mirar a Cristo<br/>Podemos hallar<br/>Su poder y gloria,<br/>Gracia, amor sin par.<br/>Vistas tan extensas<br/>Vemos por doquier<br/>Al fijar los ojos<br/>Solamente en Él.<br/>',NULL,191247,4);
INSERT INTO stanza VALUES('S528','4','A Jesús miramos,<br/>Sobre el trono está;<br/>Nuestra fe nos une<br/>Al Rey celestial.<br/>De Ti dependemos<br/>Siempre, sin cesar;<br/>Nuestro ser asciende<br/>Para_en Ti morar.<br/>',NULL,191248,5);
INSERT INTO stanza VALUES('S529','1','Oh alma turbada y cansada,<br/>¿No ves luz en la oscuridad?<br/>Hay luz al mirar al que salva,<br/>Y vida abundante hallarás.<br/>',NULL,191249,1);
INSERT INTO stanza VALUES('S529','chorus','Pon tus ojos en Cristo,<br/>Contempla Su preciosa faz,<br/>Y lo terrenal se opacará<br/>A la luz de Su gloria sin par.<br/>',NULL,191250,2);
INSERT INTO stanza VALUES('S529','2','De muerte Él pasó a la vida,<br/>Y vamos siguiendo allí.<br/>Ya no nos domina el pecado,<br/>¡Más que vencedores" al fin!<br/>',NULL,191251,3);
INSERT INTO stanza VALUES('S529','3','No te faltará Su palabra;<br/>En Él cree con Tu corazón;<br/>Ve luego al agónico mundo<br/>Y proclama Su salvación.<br/>',NULL,191252,4);
INSERT INTO stanza VALUES('S530','1','"Consideradlo_a Él", modelo fiel;<br/>Cristo te_asió, debes reconocer,<br/>Para que tengas Su vida_y poder,<br/>Para que brielle_en ti la_imagen de_Él.<br/>',NULL,191253,1);
INSERT INTO stanza VALUES('S530','2','"Consideradlo_a Él", y buscarás<br/>Siempre en el último lugar estar,<br/>Contento de pasar sin fama aquí<br/>Para que obtenga el Padre gloria así.<br/>',NULL,191254,2);
INSERT INTO stanza VALUES('S530','3','¡No retrocedas, oh hijo de Dios!<br/>Con Cristo ve a la muerte sin temor;<br/>Luego el poder de la vida inmortal<br/>El ego y el pecado anulará.<br/>',NULL,191255,3);
INSERT INTO stanza VALUES('S530','4','"Consideradlo_a Él", y has de ser<br/>Más puro, abnegado y más fiel;<br/>Dios forjará el modelo en tu interior;<br/>Ve siempre el ejemplo del Señor.<br/>',NULL,191256,4);
INSERT INTO stanza VALUES('S530','5','"Consideradlo_a Él", y al correr<br/>Alza tus ojos, ponlos sólo en Él;<br/>Él te transformará y alumbrará;<br/>Su imagen viva así reflejarás.<br/>',NULL,191257,5);
INSERT INTO stanza VALUES('S530','note','**Usado con permiso.**<br/>',NULL,191258,6);
INSERT INTO stanza VALUES('S531','1','¿Serás obediente<br/>En todo_al Señor,<br/>Aunque tierra y cielo<br/>Los conmueva Dios?<br/>Y, frente al desastre,<br/>¿Mantendrás tu fe?<br/>¿Seguirás a Cristo<br/>Hoy, confiando en Él?<br/>',NULL,191259,1);
INSERT INTO stanza VALUES('S531','2','¿Serás obediente<br/>En todo al Señor,<br/>Sin retroceder hoy<br/>Y sin distracción?<br/>Aunque pareciera<br/>Que a la muerte vas,<br/>¿Lo obedecerías<br/>Tú, sin vacilar?<br/>',NULL,191260,2);
INSERT INTO stanza VALUES('S531','3','Si te manda el Líder,<br/>¿Podrás tú confiar<br/>Aunque el adversario<br/>Sea fuerte rival?<br/>¿Podrás tú, con gozo,<br/>Ir y obedecer?<br/>¿Pelearás la guerra<br/>Hasta el triunfo ver?<br/>',NULL,191261,3);
INSERT INTO stanza VALUES('S531','4','¿Podrás? Nuestro Cristo<br/>Espera por ti;<br/>Oye Sus mandatos;<br/>Cúmplelos, felíz.<br/>Al pasar revista,<br/>Al anochecer,<br/>Te dirá: "bien hecho,<br/>Buen esclavo fiel".<br/>',NULL,191262,4);
INSERT INTO stanza VALUES('S532','1','¡Oh, regocijaos! Anima el Señor;<br/>Él puede_ataduras romper;<br/>Su sangre vertió, ¿ya quien tendrá temor,<br/>Si Cristo todo_en todo es?<br/>',NULL,191263,1);
INSERT INTO stanza VALUES('S532','chorus','Dios por nosotros, Dios por nosotros,<br/>Dios por nosotros,<br/>¿Quién contra nosotros?<br/>¿Quién? ¿Quién? ¿Quién?<br/>¿Quién contra nosotros? ¡Ninguno!<br/>',NULL,191264,2);
INSERT INTO stanza VALUES('S532','2','¡Sé fuerte en Él! Gozoso en Su poder,<br/>A diario sé firme y fiel;<br/>Si asecha el mal, valiente y justo sé,<br/>Y Dios tu fuerza ha de ser.<br/>',NULL,191265,3);
INSERT INTO stanza VALUES('S532','3','Confía en Su Palabra, que es veráz;<br/>En Cristo está el Sí y el Amén,<br/>Y aunque esta tierra un día pasará,<br/>Él Sus promesas cumplirá.<br/>',NULL,191266,4);
INSERT INTO stanza VALUES('S532','4','En Cristo habitad, seguro Su control;<br/>Te dio vida eterna el Señor.<br/>Ninguno jamás podrá arrebatar<br/>El alma que Él redimió.<br/>',NULL,191267,5);
INSERT INTO stanza VALUES('S533','1','"¡La meta alcanzad!",<br/>Id sin mostrar temor;<br/>Quien te llamó,_el camino_abrió,<br/>Por tanto, firme, ¡id!.<br/>',NULL,191268,1);
INSERT INTO stanza VALUES('S533','2','"¡La meta alcanzad!",<br/>Ojos, que fuego son,<br/>Te observan; ¿qué el hombre es?<br/>¿Qué importa su opinión?<br/>',NULL,191269,2);
INSERT INTO stanza VALUES('S533','3','"¡La meta alcanzad!",<br/>Atrás no mires más;<br/>Al frente está Su aprobación,<br/>Y te coronará,<br/>',NULL,191270,3);
INSERT INTO stanza VALUES('S533','4','"¡La meta alcanzad!",<br/>Sin ver, ni oir, ni hablar,<br/>Seguid la senda que Él subió,<br/>"¡A Cristo alcanzad!".<br/>',NULL,191271,4);
INSERT INTO stanza VALUES('S534','1','"¡Todos, adelante!"<br/>Nuestro lema es;<br/>Busca lo de_arriba<br/>Sin retroceder.<br/>Columna de fuego<br/>Adelante va;<br/>¿Quién caudicaría<br/>Con tal Capitán?<br/>Vamos por desiertos,<br/>Luchas y labor;<br/>Nos espera el reino<br/>Con su esplendor.<br/>',NULL,191272,1);
INSERT INTO stanza VALUES('S534','2','Gloria sobre glorias<br/>Dios ya preparó<br/>Para los que lo_aman<br/>Con ferviente amor.<br/>Cosas nunca vistas,<br/>Que ni oído oyó,<br/>Ni jamás se han dicho,<br/>Ni hombre soñó.<br/>¡Adelante al reino!<br/>¡Su gloria se ve!<br/>¡Cambiará en vista<br/>Lo que era fe!<br/>',NULL,191273,2);
INSERT INTO stanza VALUES('S535','1','Hacia la meta proseguid<br/>Para poder ganar<br/>Al Cristo inclusivo, tan<br/>Glorioso_y sin igual.<br/>',NULL,191274,1);
INSERT INTO stanza VALUES('S535','chorus','¡Proseguid! ¡Proseguid!<br/>¡Proseguid! ¡Aleluya!<br/>Por el premio<br/>Proseguid hasta el fin,<br/>Para a Cristo ganar.<br/>',NULL,191275,2);
INSERT INTO stanza VALUES('S535','2','Dejadlo todo y proseguid<br/>Al premio superior:<br/>El Cristo que ofrece Dios,<br/>De sin igual valor.<br/>',NULL,191276,3);
INSERT INTO stanza VALUES('S535','3','Hoy proseguid a conocer<br/>A Cristo el Señor<br/>Y el sostenedor poder<br/>De Su resurrección.<br/>',NULL,191277,4);
INSERT INTO stanza VALUES('S535','4','Todo olvidad y proseguid,<br/>Sólo una cosa haced;<br/>Al Cristo que delante está<br/>Debemos aprehender.<br/>',NULL,191278,5);
INSERT INTO stanza VALUES('S536','1','¡Vela, la noche _caba!<br/>Al mundo no_ames más;<br/>¡Vela, pues ya_amanece!<br/>Debes despertar.<br/>¡Vela, pues viene Cristo,<br/>Y_el diablo atacará!<br/>¡Vela, pues Cristo espera!<br/>No_hay que desmayar.<br/>',NULL,191279,1);
INSERT INTO stanza VALUES('S536','2','¡Vela y sirve presto!<br/>Los días malos son;<br/>¡Vela y sigue obrando!<br/>Cerca está el Señor.<br/>Ponte ya tu armadura,<br/>Sé fuerte en tu interior;<br/>¡Vela, resiste al diablo!<br/>Cristo da valor.<br/>',NULL,191280,2);
INSERT INTO stanza VALUES('S536','3','¡Vela por la estrella!<br/>Ya viene el Salvador;<br/>¡Vela y busca el reino!<br/>Sin ningún temor.<br/>¡Vela, sé vigilante!<br/>La noche acabará;<br/>¡Vela y verás Su gloria!<br/>El Señor vendrá.<br/>',NULL,191281,3);
INSERT INTO stanza VALUES('S537','1','Hay una carrera hoy, ¡Aleluya!<br/>Y la forma de poder ganar.<br/>A los que empezaron ya, ¡Aleluya!<br/>Dios ha dicho: ¡Sólo_a Él mirad!<br/>',NULL,191282,1);
INSERT INTO stanza VALUES('S537','chorus','¡Sí, mirad! ¡A Él mirad!<br/>¡A Jesús sólo_hoy mirad!<br/>Y atrás no mires más, ¡Aleluya!<br/>¡Deja todo_y mira sólo_a Él!<br/>',NULL,191283,2);
INSERT INTO stanza VALUES('S537','2','Deja todo alrededor, ¡Aleluya!<br/>Toda lucha y distracción de hoy.<br/>Deja todo y paz tendrás, ¡Aleluya!<br/>Deja todo y mira sólo a Él.<br/>',NULL,191284,3);
INSERT INTO stanza VALUES('S537','3','Deja el alma vacilante, ¡Aleluya!<br/>Deja el yo que te hace fallecer.<br/>Deja todo y mira al blanco, ¡Aleluya!<br/>Deja todo y mira sólo a Él.<br/>',NULL,191285,4);
INSERT INTO stanza VALUES('S537','4','Deja todo el pasado, ¡Aleluya!<br/>Deja todo el bien y el mal atrás,<br/>Y asido del Viviente, ¡Aleluya!<br/>Deja todo y mira sólo a Él.<br/>',NULL,191286,5);
INSERT INTO stanza VALUES('S537','5','Mira sólo a Su rostro ¡Aleluya!<br/>Lo empezado, Él lo acabará.<br/>Gracia da para correr, ¡Aleluya!<br/>Y se obtiene al mirarlo a Él.<br/>',NULL,191287,6);
INSERT INTO stanza VALUES('S538','1','Tristes años por la cruz pasé;<br/>Sólo_en mis pecados me_enfoqué.<br/>Mas, por fin, el río yo crucé:<br/>El trono_hallé.<br/>',NULL,191288,1);
INSERT INTO stanza VALUES('S538','chorus','¡Qué misericordia! ¡Gracia da<br/>Para la carrera continuar!<br/>Con confianza vengo a gustar<br/>De mi Señor.<br/>',NULL,191289,2);
INSERT INTO stanza VALUES('S538','2','Mi vivir cristiano siempre fue<br/>De caer y al altar volver,<br/>Hasta que, por fin, yo avancé:<br/>El trono_hallé.<br/>',NULL,191290,3);
INSERT INTO stanza VALUES('S538','3','Al Santísimo hay que_avanzar;<br/>El pecado atrás hay que dejar.<br/>Corran la carrera sin parar;<br/>¡No hay velo ya!<br/>',NULL,191291,4);
INSERT INTO stanza VALUES('S538','4','Tras el velo, a Dios disfruto ya;<br/>Ley de vida, vara y maná;<br/>Cristo mismo, el Arca, es mi hogar,<br/>¡Aleluya!<br/>',NULL,191292,5);
INSERT INTO stanza VALUES('S539','1','¡Qué buenas nuevas hay!<br/>¡Oh, alabad a Dios!<br/>El evangelio_hablad:<br/>Al trono_Él nos llevó,<br/>Y juntos, a su_alrededor,<br/>Podemos disfrutar a Dios.<br/>Podemos disfrutar a Dios.<br/>',NULL,191293,1);
INSERT INTO stanza VALUES('S539','2','En el atrio empezad,<br/>Para luego adentrar;<br/>Id al Santo Lugar,<br/>Mas hay que avanzar.<br/>Dejando el pecado atrás,<br/>//En Dios, detrás del velo entrad.//<br/>',NULL,191294,2);
INSERT INTO stanza VALUES('S539','3','Hay que profundizar;<br/>De la tierra ascended.<br/>Para con Cristo estar,<br/>En Su trono con Él.<br/>El trono de la gracia es<br/>//Donde lo contemplamos bien.//<br/>',NULL,191295,3);
INSERT INTO stanza VALUES('S539','4','Uno nos hace Dios,<br/>¡Fuera lo_individual!<br/>Cristianos somos, mas<br/>En unanimidad.<br/>Como Sus miembros en unión,<br/>//Somos el Cuerpo del Señor//<br/>',NULL,191296,4);
INSERT INTO stanza VALUES('S539','5','Como Su Cuerpo hoy,<br/>Tenemos SU hablar,<br/>No solo de la cruz,<br/>La sangre y el altar;<br/>Nos habla para perfección<br/>//Junto a Su trono en comunión.//<br/>',NULL,191297,5);
INSERT INTO stanza VALUES('S539','6','Cristo objetivo es,<br/>Tan lleno de virtud,<br/>Mas subjetivo es<br/>En nuestro espíritu;<br/>Dios, trono y el Santísimo,<br/>//En nuestro espíritu están hoy.//<br/>',NULL,191298,6);
INSERT INTO stanza VALUES('S539','7','Levítico pasó,<br/>Y la obra de Aarón;<br/>Quedó Melquisedec:<br/>Fiel Sacerdote hoy.<br/>Su ministerio es tan real,<br/>//Nos suministra vino y pan.//<br/>',NULL,191299,7);
INSERT INTO stanza VALUES('S540','1','En lo profundo de Tu Nombre,_Oh Dios,<br/>Yo me sumerjo_en calma celestial;<br/>Durante_el día Tú me bastarás,<br/>También me bastas en la_oscuridad.<br/>',NULL,191300,1);
INSERT INTO stanza VALUES('S540','2','El Todo-suficiente eres mi Dios,<br/>Puedes crear lo que me falta a mí;<br/>Mandas las maravillas de Tu amor,<br/>Por mi camino solitario aquí.<br/>',NULL,191301,2);
INSERT INTO stanza VALUES('S540','3','Confiando en Ti, me atrevo, oh mi Dios,<br/>A echarme en Tu seno otra vez;<br/>Tus sendas yo por fe adoro allí,<br/>En fe adoro y reposo en Ti.<br/>',NULL,191302,3);
INSERT INTO stanza VALUES('S541','1','De Ti acepto mi porción,<br/>Y entender no busco hoy;<br/>Pues ciego soy, mas Tú sí ves,<br/>Tu voluntad aceptaré.<br/>',NULL,191303,1);
INSERT INTO stanza VALUES('S541','chorus','Tu voluntad acepto yo<br/>Cualquiera sea, sin temor;<br/>Pues me sostiene Tu amor,<br/>Tu voluntad acepto yo.<br/>',NULL,191304,2);
INSERT INTO stanza VALUES('S541','2','Cuando no pueda ver Tu faz,<br/>Cuando me abrume el pesar,<br/>En Tu Calvario pensaré,<br/>Tu voluntad aceptaré.<br/>',NULL,191305,3);
INSERT INTO stanza VALUES('S541','3','Cuando de gozo gusto yo,<br/>Te doy las gracias, mi Señor;<br/>Mi copa, Tú la llenas bien,<br/>Tu voluntad aceptaré.<br/>',NULL,191306,4);
INSERT INTO stanza VALUES('S541','4','Enfrento todo con Tu paz,<br/>De Ti lo acepto sin dudar;<br/>Pues todo obra para bien,<br/>Tu voluntad aceptaré.<br/>',NULL,191307,5);
INSERT INTO stanza VALUES('S542','1','Salvo en Jesús, mi_Amado;<br/>Salvo_en Su seno_estoy;<br/>Por Su amor que cubre,<br/>Descansa mi_alma hoy.<br/>¡Oye,_el cantar resuena!<br/>Dulce voz celestial;<br/>Los santos hacen eco<br/>Con gozo espiritual.<br/>',NULL,191308,1);
INSERT INTO stanza VALUES('S542','chorus','Salvo en Jesús, mi_Amado;<br/>Salvo_en Su seno_estoy;<br/>Por Su amor que cubre,<br/>Descansa mi_alma hoy.<br/>',NULL,191309,2);
INSERT INTO stanza VALUES('S542','2','Salvo soy, en Sus brazos,<br/>De ansiedad mordaz,<br/>De tentación mundana,<br/>De muerte y de pecar.<br/>Libre del llanto en penas,<br/>Del miedo y el dudar;<br/>Sólo unas pruebas quedan,<br/>Y un poco más llorar.<br/>',NULL,191310,3);
INSERT INTO stanza VALUES('S542','3','Es mi Jesús, Refugio;<br/>Por mí Jesús murió;<br/>Firme en la Roca eterna<br/>Siempre me hallaré.<br/>Esperaré, paciente,<br/>Hasta que salga el sol,<br/>Hasta que desvanezca<br/>La densa noche atróz.<br/>',NULL,191311,4);
INSERT INTO stanza VALUES('S543','1','Los rayos han destellado,<br/>Los truenos yo oí;<br/>Las olas del pecado<br/>Rompieron sobre mí;<br/>Oí la voz de Cristo,<br/>Que me animó_a continuar;<br/>Y Él me ha prometido<br/>Que nunca me dejará.<br/>',NULL,191312,1);
INSERT INTO stanza VALUES('S543','chorus','No me dejará,<br/>No me dejará,<br/>Sí, Él me ha prometido<br/>Que nunca me dejará;<br/>No me dejará,<br/>No me dejará,<br/>Sí, Él me ha prometido<br/>Que nunca me dejará.<br/>',NULL,191313,2);
INSERT INTO stanza VALUES('S543','2','Los vientos de este mundo<br/>Hoy soplan, con tentación;<br/>Mas siento paz sabiendo<br/>Que tengo al Salvador;<br/>Me guarda Él del peligro<br/>Cuando otros no están,<br/>Y Él me ha prometido<br/>Que nunca me dejará.<br/>',NULL,191314,3);
INSERT INTO stanza VALUES('S543','3','Cuando_en el valle ando,<br/>Por sendas de aflicción,<br/>La cruz pesada, conmigo<br/>La lleva mi Salvador;<br/>Espinos mis pies enredan,<br/>Tropiezo quieren causar;<br/>Mas Él me ha prometido<br/>Que nunca me dejará.<br/>',NULL,191315,4);
INSERT INTO stanza VALUES('S543','4','Murió por mí en el monte,<br/>La lanza lo hirió,<br/>Abierta fue la fuente<br/>Que carmesí fluyó;<br/>Por mí, Él espera en gloria,<br/>Y en Su trono está;<br/>Y Él ha prometido<br/>Que nunca me dejará.<br/>',NULL,191316,5);
INSERT INTO stanza VALUES('S544','1','Peregrino tan cargado<br/>Bajo luchas y labor,<br/>Hay palabras de consuelo;<br/>"Pon tu carga en el Señor".<br/>',NULL,191317,1);
INSERT INTO stanza VALUES('S544','chorus','¡Pon tu carga en el Señor!<br/>¡Pon tu carga en el Señor!<br/>Te fortalecerá,<br/>También te cuidará,<br/>¡Pon tu carga en el Señor!<br/>',NULL,191318,2);
INSERT INTO stanza VALUES('S544','2','¿Ya tus pies no te sostienen,<br/>Y tu luz ya se apagó?<br/>¿Es tu cruz pesada y grande?<br/>"Pon tu carga en el Señor".<br/>',NULL,191319,3);
INSERT INTO stanza VALUES('S544','3','¿Te dejaron tus amigos?<br/>¿Ya no hay voces de candor?<br/>¿Llora tu alma por la angustia?<br/>"Pon tu carga en el Señor".<br/>',NULL,191320,4);
INSERT INTO stanza VALUES('S544','4','¿Olvidaste Su palabra?<br/>¿Titubea tu alma hoy?<br/>¿Es tu fuerza casi nula?<br/>"Pon tu carga en el Señor".<br/>',NULL,191321,5);
INSERT INTO stanza VALUES('S544','5','Él impedirá que caigas;<br/>Él tus pasos guiará;<br/>Él dará fuerza a tu empeño,<br/>Y en poder te guardará.<br/>',NULL,191322,6);
INSERT INTO stanza VALUES('S545','1','Pasando duras pruebas hoy,<br/>Pisando sobre espinos voy;<br/>Por un sentir guardado soy:<br/>¡Tú piensas siempre_en mí!<br/>',NULL,191323,1);
INSERT INTO stanza VALUES('S545','chorus','¡Tú piensas siempre_en mí!<br/>¡Tú piensas siempre_en mí!<br/>¿Cómo podré, Señor, temer?<br/>¡Tú piensas siempre_en mí!<br/>',NULL,191324,2);
INSERT INTO stanza VALUES('S545','2','Las ansiedades y el afán<br/>A mi alma traen oscuridad;<br/>Sus sombras me hacen recordar<br/>¡Que piensas siempre_en mí!<br/>',NULL,191325,3);
INSERT INTO stanza VALUES('S545','3','Si vienen sombras o se van,<br/>En noche oscura o claridad,<br/>¡Estoy contento, porque sé<br/>Que piensas siempre en mí.<br/>',NULL,191326,4);
INSERT INTO stanza VALUES('S546','1','Siempre_el Salvador me guía;<br/>¿Qué más puedo pedir yo?<br/>¿No tendrá misericordia<br/>Quien por vida me guió?<br/>¡Paz divina! ¡Qué consuelo<br/>Es, por fe, andar en luz!<br/>Venga_el bien o_el mal, comprendo:<br/>Todo lo_hace bien Jesús;<br/>Venga_el bien o_el mal, comprendo:<br/>Todo lo_hace bien Jesús;<br/>',NULL,191327,1);
INSERT INTO stanza VALUES('S546','2','Siempre el Salvador me guía;<br/>Gozo tra a mi andar;<br/>Gracia da con cada prueba;<br/>Nutre con viviente pan.<br/>Si mis torpes pies se cansan<br/>Y mi alma seca está,<br/>//Brotan de la Roca_hendida<br/>Aguas de gozo eternal.//<br/>',NULL,191328,2);
INSERT INTO stanza VALUES('S546','3','Siempre el Salvador me guía;<br/>¡Oh, Su gracia plena es!<br/>En los brazos de mi Padre,<br/>¡Qué descanso yo tendré!<br/>Cuando a ese día eterno<br/>Vuele mi espíritu,<br/>//Cantaré yo por los siglos;<br/>"Me guió siempre Jesús".//<br/>',NULL,191329,3);
INSERT INTO stanza VALUES('S547','1','Dios te da, oh peregrino,<br/>Su promesa firme_y fiel,<br/>Mientras vas de_aquí_a la gloria:<br/>"Con Mi ojo te guiaré".<br/>',NULL,191330,1);
INSERT INTO stanza VALUES('S547','chorus','Yo por siempre_he de guiarte,<br/>Con mi ojo te guiaré;<br/>De la tierra a la gloria,<br/>Con Mi ojo te guiaré.<br/>',NULL,191331,2);
INSERT INTO stanza VALUES('S547','2','Si te acosan tentaciones<br/>Y la ayuda no se ve,<br/>Su promesa en ti resuene:<br/>"Con Mi ojo te guiaré".<br/>',NULL,191332,3);
INSERT INTO stanza VALUES('S547','3','Si  anhelos no cumplidos<br/>Con los años ves caer,<br/>Su promesa te aliente;<br/>"Con Mi ojo te guiaré".<br/>',NULL,191333,4);
INSERT INTO stanza VALUES('S547','4','Cuando cese aquí la vida<br/>Y la muerte cerca esté,<br/>Oye sólo a tu fiel Guía;<br/>"Con Mi ojo te guiaré".<br/>',NULL,191334,5);
INSERT INTO stanza VALUES('S548','1','Fresco tal como_el rocío,<br/>Brinda descanso sin par;<br/>Cristo_en ternura me unge,<br/>Me reconforta Su hablar.<br/>Firme durante la prueba,<br/>Firme en la tempestad,<br/>Firme por Cristo_y Su gloria,<br/>Firme_hasta_el reino ganar.<br/>',NULL,191335,1);
INSERT INTO stanza VALUES('S548','chorus','¡Dulce_es Tu voz,<br/>Oh Señor de_esperanza!<br/>En Tu presencia,<br/>Tu gozo me das.<br/>',NULL,191336,2);
INSERT INTO stanza VALUES('S548','2','Si al pasar por problemas,<br/>Débil mi espíritu está,<br/>Toda mi fe y esperanza<br/>Sin duda se esfumarán,<br/>¡Oh, que Tu fe y Tu vida<br/>Puedan mi ser dominar!<br/>Que tus riquezas de gloria<br/>Hoy pueda yo disfrutar.<br/>',NULL,191337,3);
INSERT INTO stanza VALUES('S548','3','Como la luz de la aurora,<br/>Disipa la oscuridad;<br/>Con sanidad en Tus alas,<br/>Mi noche, día harás.<br/>Ven, oh, ven a consolarme;<br/>Ven hoy a mi corazón;<br/>Ven, Esperanza de gloria;<br/>Nunca me dejes, Señor.<br/>',NULL,191338,4);
INSERT INTO stanza VALUES('S549','1','Podrá nublarse_el día,<br/>La noche entristecer,<br/>La_espera prolongarse,<br/>Mas una cosa sé:<br/>Que amo más a Cristo,<br/>Y bella comunión<br/>Más íntima_y más clara<br/>Tendré con mi Señor.<br/>',NULL,191339,1);
INSERT INTO stanza VALUES('S549','2','¡Nuestra esperanza es Cristo!<br/>¡Amigo y Gozo es Él!<br/>Ansiamos recibirlo<br/>Con gran anhelo y fe.<br/>Quizás al fin del día<br/>Jesus regresará;<br/>Empezará el descanso,<br/>La espera acabará.<br/>',NULL,191340,2);
INSERT INTO stanza VALUES('S550','1','No sé lo que me_espera,<br/>Mis ojos cubre Dios,<br/>Y con cada paso de mi_andar<br/>Paisajes nuevos da;<br/>Me_envía dulces gozos que<br/>Gratas sorpresas dan.<br/>',NULL,191341,1);
INSERT INTO stanza VALUES('S550','chorus','Yo voy a donde_Él guíe,<br/>Confío siempre en Él;<br/>Y siempre, en perfecta paz,<br/>"El sabe", cantaré;<br/>Y siempre, en perfecta paz,<br/>"El sabe", cantaré.<br/>',NULL,191342,2);
INSERT INTO stanza VALUES('S550','2','Hoy frente a mí yo veo<br/>Un paso nada más;<br/>La luz del cielo más brillará<br/>Sin velo terrenal;<br/>Y con amor me dice Él;<br/>"¡Confía sólo_en Mí!"<br/>',NULL,191343,3);
INSERT INTO stanza VALUES('S550','3','¡Qué bienaventurado<br/>Es no saber jamás!<br/>Su diestra hoy me sostendrá<br/>Y no me soltará;<br/>Mi alma hace reposar<br/>En Él, quien me amó.<br/>',NULL,191344,4);
INSERT INTO stanza VALUES('S550','4','Hoy, sin saber, prosigo;<br/>Prefiero así estar;<br/>Mejor con Él de noche andar<br/>Que ir solo en claridad;<br/>Prefiero andar por fe con Él<br/>Que por mi vista andar.<br/>',NULL,191345,5);
INSERT INTO stanza VALUES('S551','1','Diá_a día, en cada momento,<br/>Hallo fuerza_en toda prueba_aquí;<br/>Al confiar en lo que_el Padre_asigna,<br/>No_hay por qué temor o_afán sufrir.<br/>El Señor, con corazón tan tierno,<br/>Nos asigna_a diario lo mejor;<br/>En fatiga nos manda_el descanso;<br/>En angustia nos da paz y_amor.<br/>',NULL,191346,1);
INSERT INTO stanza VALUES('S551','2','El Señor a diario está tan cerca;<br/>Gracia da para cada ocasión;<br/>Quita todo_afán, también anima;<br/>Poderoso Consejero es Dios.<br/>Proteger Sus hijos, Su tesoro,<br/>Es la carga que lleva el Señor;<br/>"Como tus días serán tus fuerzas";<br/>Tal promesa el Señor nos dio.<br/>',NULL,191347,2);
INSERT INTO stanza VALUES('S551','3','Oh, Señor, en mis tribulaciones,<br/>Quiero_en Tus promesas descansar;<br/>Que jamás yo pierda el consuelo<br/>Que, por fe, Tu fiel Palabra da.<br/>Que me ayudes, ruego, en las tormentas,<br/>A enfrentarlas con aceptación<br/>Una a una, al pasar los días,<br/>Hasta que contigo esté, Señor.<br/>',NULL,191348,3);
INSERT INTO stanza VALUES('S552','1','Oh, regocijémonos en el Señor<br/>Aunque todo_esté angustioso<br/>Y haya_aflicciones con mucho dolor;<br/>Mejor es cantar que quejarse.<br/>',NULL,191349,1);
INSERT INTO stanza VALUES('S552','chorus','¡Siempre regocijaos! ¡Gozosos estad!<br/>Es mejor el cantar que_el quejarse,<br/>Es mejor el vivir que_el morir,<br/>Por tanto, gozosos estad.<br/>',NULL,191350,2);
INSERT INTO stanza VALUES('S552','2','Oh, regocijémonos en el Señor<br/>Cuando el tentador lance dardos,<br/>Por siempre a Satán le daremos temor,<br/>Si en vez de quejarnos cantamos.<br/>',NULL,191351,3);
INSERT INTO stanza VALUES('S552','3','Oh, regocijémonos en el Señor<br/>Si atacan las enfermedades<br/>Y no hay tratamiento que sea de valor,<br/>El gozo traerá sanidades.<br/>',NULL,191352,4);
INSERT INTO stanza VALUES('S553','1','Gloriosa cual río<br/>Es la paz de Dios;<br/>Siempre ha vencido,<br/>Crece_en su_esplendor;<br/>Perfecta, mas fluye<br/>Cada día más;<br/>Perfecta, mas crece<br/>En profundidad.<br/>',NULL,191353,1);
INSERT INTO stanza VALUES('S553','chorus','Fijo_en Jesucristo,<br/>Halla_el corazón<br/>Esa paz perfecta<br/>Que_Él nos prometió.<br/>',NULL,191354,2);
INSERT INTO stanza VALUES('S553','2','Guardado en el hueco<br/>De Su mano fiel,<br/>No hay rival que siga,<br/>Ni traidor en pie;<br/>Las dudas no existen,<br/>Y ningún afán<br/>Nuestro espíritu hoy<br/>Puede allí tocar.<br/>',NULL,191355,3);
INSERT INTO stanza VALUES('S553','3','Cada prueba o gozo<br/>Que manda el Señor<br/>Ha sido trazado<br/>Por el Sol de amor.<br/>Sin dudar confiemos,<br/>Todo Él cumplirá;<br/>Los que_en Él confían,<br/>Fiel lo hallarán.<br/>',NULL,191356,4);
INSERT INTO stanza VALUES('S554','1','No prometió Dios en tu vivir,<br/>Sendas de flores, cielo feliz;<br/>No prometió Dios sol sin turbión,<br/>Gozo sin llanto, paz sin dolor.<br/>',NULL,191357,1);
INSERT INTO stanza VALUES('S554','chorus','Mas prometió Dios diario vigor,<br/>Luz en la senda, fuerza‿en labor;<br/>Gracia‿en las pruebas y Su sostén,<br/>Su infinito‿amor, Su compasión.<br/>',NULL,191358,2);
INSERT INTO stanza VALUES('S554','2','No prometió Dios eliminar,<br/>Tentación, pena o dificultad;<br/>Él no nos dijo: Nunca tendrás<br/>Cargas pesadas, contrariedad.<br/>',NULL,191359,3);
INSERT INTO stanza VALUES('S554','3','No prometió Dios peregrinar,<br/>Por sendas lisas, sin peligrar,<br/>Sin escarpados, risco o peñón,<br/>Sin ningún río hondo‿y feroz.<br/>',NULL,191360,4);
INSERT INTO stanza VALUES('S554','note','**Nota: Derechos de autos. Evangelical Publishers, Toronto, Canadá.**<br/>',NULL,191361,5);
INSERT INTO stanza VALUES('S555','1','Jesús me legó_una promesa:<br/>"Perfeccionaré Mi poder<br/>En todas tus debilidades;<br/>Mi gracia suficiente es"<br/>Y para que mi_alma recuerde<br/>Y nunca lo pueda_olvidar,<br/>Así Su promesa repite:<br/>"Mi gracia suficiente es".<br/>',NULL,191362,1);
INSERT INTO stanza VALUES('S555','chorus','Sí, una y otra vez dice:<br/>"Perfeccionaré Mi poder<br/>En todas tus debilidades;<br/>Mi gracia suficiente es".<br/>',NULL,191363,2);
INSERT INTO stanza VALUES('S555','2','Su gracia sí puede salvarme,<br/>Lavarme de culpa y maldad,<br/>Y santificarme del todo;<br/>Su Espíritu me ha de llenar.<br/>Su gracia supera las pruebas,<br/>Por más duras que ellas estén;<br/>Pues firme está Su promesa:<br/>"Mi gracia suficiente es".<br/>',NULL,191364,3);
INSERT INTO stanza VALUES('S555','3','Su gracia en enfermedades,<br/>Suficiente para mí es;<br/>Si penas cual olas me cubren,<br/>Su gracia suficiente es;<br/>Nos libra de todo egoísmo,<br/>Y para servir, da el poder;<br/>Nos lleva a decir a quien sufre:<br/>"Su gracia suficiente es".<br/>',NULL,191365,4);
INSERT INTO stanza VALUES('S555','4','Su gracia es más que suficiente;<br/>Por ella podemos vivir;<br/>Y cuando a la muerte lleguemos,<br/>Su luz nos hará resurgir.<br/>Cuando en Su victoria estemos,<br/>Y en gloria le podamos ver,<br/>A sus pies, postrados diremos:<br/>"Tu gracia suficiente fue".<br/>',NULL,191366,5);
INSERT INTO stanza VALUES('S555','5','Mi gracia no es suficiente,<br/>Mas la Suya siempre ha de ser;<br/>Mi gracia es finita y fluctuante,<br/>Mas Su gracia confiable es.<br/>Repito Sus promesas siempre:<br/>"Perfeccionaré mi poder<br/>En todas tus debilidades;<br/>Mi gracia suficiente es".<br/>',NULL,191367,6);
INSERT INTO stanza VALUES('S556','1','La cruz ciertamente_es pesada,<br/>Mas Su gracia es mayor;<br/>Y aunque vinieran tormentas,<br/>Yo veré la faz de Dios.<br/>',NULL,191368,1);
INSERT INTO stanza VALUES('S556','chorus','La gracia de Dios me bastará,<br/>Tormentas, Su faz no_ocultarán;<br/>Satisface el saber<br/>Que Jesús conmigo está,<br/>Que puedo_a Satán vencer.<br/>',NULL,191369,2);
INSERT INTO stanza VALUES('S556','2','No son más agudos mis cardos<br/>Que los que Él llevó por mí;<br/>Ni mi cáliz es tan amargo<br/>Como el de Getsemaní.<br/>',NULL,191370,3);
INSERT INTO stanza VALUES('S556','3','La luz de Su amor va en aumento<br/>Cuando brilla en mi penar;<br/>Mi carga más leve se hace<br/>Si al débil puedo alzar.<br/>',NULL,191371,4);
INSERT INTO stanza VALUES('S556','4','Cumplir Su designio me alegra<br/>Al andar frente a Su faz;<br/>Las pruebas me traen más gracia;<br/>Cristo en ellas es mi paz.<br/>',NULL,191372,5);
INSERT INTO stanza VALUES('S557','1','Si aumentan las cargas,<br/>Él manda más gracia;<br/>En muchas labores,<br/>Más fuerza nos da;<br/>A más aflicciones, más misericordia;<br/>En las muchas pruebas,<br/>Abunda Su paz.<br/>',NULL,191373,1);
INSERT INTO stanza VALUES('S557','chorus','Su gracia insondable,<br/>Su amor sin linderos,<br/>El fin de Su fuerza, ¿quién conocerá?<br/>Pues de Sus riquezas eternas en Cristo,<br/>Nos da y nos da, y de nuevo, nos da.<br/>',NULL,191374,2);
INSERT INTO stanza VALUES('S557','2','Cuando la entereza se ha acabado,<br/>Cuando el día es duro<br/>Y la fuerza se va,<br/>Cuando las reservas<br/>Guardadas se agotan,<br/>Es cuando el Padre comienza a dar:<br/>',NULL,191375,3);
INSERT INTO stanza VALUES('S557','note','**Estrofa #3 es una estrofa adicional:**<br/>',NULL,191376,4);
INSERT INTO stanza VALUES('S557','3','Cuando el diablo ataca<br/>Y las pruebas son crueles,<br/>Sentimos que todo se quiebra al andar;<br/>En nuestra flaqueza, Su gracia nos suple,<br/>Nos cubre y alienta, nos vuelve a abrazar.<br/>',NULL,191377,5);
INSERT INTO stanza VALUES('S558','1','Un pajarito soy;<br/>La libertad perdí,<br/>Y en mi jaula canto_en paz<br/>A quien me puso allí;<br/>Me place_un prisionero ser,<br/>Pues, oh mi Dios, es Tu placer.<br/>',NULL,191378,1);
INSERT INTO stanza VALUES('S558','2','No hago nada más,<br/>Cantando siempre estoy;<br/>Aquel a quien amo_agradar<br/>Escucha mi canción;<br/>Mi ala_errante Él ató<br/>Mas se inclina a mi voz.<br/>',NULL,191379,2);
INSERT INTO stanza VALUES('S558','3','Te gusta escuchar,<br/>Amar y bendecir,<br/>Y aunque torpe es mi entonar,<br/>No dejas de oír.<br/>Pues sabes que esta canción<br/>Fue inspirada por Tu amor.<br/>',NULL,191380,3);
INSERT INTO stanza VALUES('S558','4','Mi jaula alrededor<br/>Mi impide libre ser;<br/>Mas aunque mi ala atada está,<br/>Mi alma libre es;<br/>Pues no hay prisión que sea capaz<br/>De refrenar su libertad.<br/>',NULL,191381,4);
INSERT INTO stanza VALUES('S558','5','¡Cuán bueno es superar<br/>Las barras, la opresión!<br/>Lo amo por cuidar de mí;<br/>Adoro Su intención;<br/>En Su grandiosa voluntad<br/>Me mente goza libertad.<br/>',NULL,191382,5);
INSERT INTO stanza VALUES('S559','1','Pequeñita flor, ¿hoy llueve?<br/>¡Pués alégrate!<br/>No te quemará el sol,<br/>Mas saldrá_otra vez.<br/>Negro_el cielo_está, sin luz,<br/>Pero_atrás brilla_el azul.<br/>',NULL,191383,1);
INSERT INTO stanza VALUES('S559','2','Alma tierna, ¿estás cansada?<br/>Aprecia el dolor;<br/>En pesar, dulzura habrá;<br/>Y_al llover, la flor.<br/>Dios te ve, el sol saldrá<br/>Cuando acabe Él Su obrar.<br/>',NULL,191384,2);
INSERT INTO stanza VALUES('S560','1','Soy presionado hasta_extenuación;<br/>Más que mis fuerzas, más que mi vigor;<br/>En cuerpo y_alma, grande_es la presión,<br/>Hasta_en la mente surgen nubes hoy.<br/>',NULL,191385,1);
INSERT INTO stanza VALUES('S560','chorus','Dios, mi_esperanza y gozo fiel;<br/>Mi vida de resurrección es Él.<br/>',NULL,191386,2);
INSERT INTO stanza VALUES('S560','2','Por mis contrarios presionado soy;<br/>También de amigos tengo opresión;<br/>Soy presionado a sólo en Dios confiar,<br/>Hasta Su vara y cayado amar.<br/>',NULL,191387,3);
INSERT INTO stanza VALUES('S560','3','Soy presionado hasta libre ser,<br/>Hasta, en lo más difícil, fe tener,<br/>Hasta entrar en la vida eternal,<br/>Y esa vida poder derramar.<br/>',NULL,191388,4);
INSERT INTO stanza VALUES('S561','1','Tu Palabra me da la_esperanza<br/>Que, al volver, redimirás mi ser;<br/>Mas en tiempos de tribulaciones,<br/>Vienen dudas y se va mi fe.<br/>Luego no sé cómo expresarme,<br/>Sólo hay gemidos en mi ser;<br/>Mas Tu_Espíritu, siempre me ayuda<br/>A orar a Dios, confiando en Él.<br/>',NULL,191389,1);
INSERT INTO stanza VALUES('S561','2','Mi Señor, no pido por más penas,<br/>Sino que las pueda evitar<br/>Y que "pase esta copa amarga",<br/>Pero hágase Tu voluntad.<br/>Aunque_ahora me rodean pruebas,<br/>En mi corazón y siento paz,<br/>Porque Dios Su amor en mí derrama;<br/>Me inunda, y ceso de dudar.<br/>',NULL,191390,2);
INSERT INTO stanza VALUES('S561','3','¡Qué consuelo! Ver que cada_asunto<br/>En Tu mano soberana está;<br/>Vemos -aunque sea opacamente-<br/>Que todo es conforme a Tu plan.<br/>Cada prueba es respuesta del Padre,<br/>A lo que el Espíritu gimió;<br/>Oh, que al probarnos Él nos gane,<br/>Y nos dé más gloria del Señor.<br/>',NULL,191391,3);
INSERT INTO stanza VALUES('S561','4','No podría Dios quitar las pruebas,<br/>Pues a Su Hijo no escatimó,<br/>No abandona el vaso, el alfarero,<br/>Hasta que Su obra consumó,<br/>Porque el corazón de Dios desea<br/>Que hermanos lleguemos a ser<br/>De Su Primogénito amado,<br/>Conformándonos en todo a Él.<br/>',NULL,191392,4);
INSERT INTO stanza VALUES('S561','5','Herederos somos del Dios vivo,<br/>Coherederos con Su Hijo, Jesús.<br/>Mientras más gravoso el sufrimiento,<br/>Más será la gloria en plenitud.<br/>Por Ti somos más que vencedores;<br/>Tu amor, Señor, nos cautivó,<br/>La creación aguarda ver Tus hijos<br/>En gloriosa manifestación.<br/>',NULL,191393,5);
INSERT INTO stanza VALUES('S562','1','Dios puso_al hombre_en frente de<br/>Dos árboles en el Edén:<br/>El de la vida muestra_a Dios,<br/>El de la ciencia;_a Satanás.<br/>',NULL,191394,1);
INSERT INTO stanza VALUES('S562','2','El centro del eterno plan<br/>El árbol de la vida es:<br/>El mismo Dios que en Cristo está<br/>Quiere la vida al hombre ser.<br/>',NULL,191395,2);
INSERT INTO stanza VALUES('S562','3','El árbol de la ciencia es<br/>Una advertencia y precaución:<br/>La fuente que hay fuera de Dios<br/>Trae muerte a aquel que la escogió.<br/>',NULL,191396,3);
INSERT INTO stanza VALUES('S562','4','Para cumplir el plan de Dios<br/>El hombre tiene que comer<br/>Del árbol de la vida que<br/>Transformará todo su ser.<br/>',NULL,191397,4);
INSERT INTO stanza VALUES('S562','5','Si escoge el de la ciencia hoy,<br/>Entra en el hombre Satanás,<br/>Quien es pecado y muerte trae,<br/>Para frustrar de Dios, el plan.<br/>',NULL,191398,5);
INSERT INTO stanza VALUES('S562','6','Todo lo cual nos hace ver<br/>Que Dios la fuente debe ser<br/>Para nosotros, pues tocar<br/>Toda otra fuente muerte es.<br/>',NULL,191399,6);
INSERT INTO stanza VALUES('S562','7','Conocimiento, muerte trae,<br/>Ya sea malo o luzca bien;<br/>Pues todo lo que no es de Dios<br/>Es artimaña de Satán.<br/>',NULL,191400,7);
INSERT INTO stanza VALUES('S562','8','No sólo el mal, también el bien<br/>Con Cristo está en oposición;<br/>El mal y el bien son, a la vez,<br/>Con Cristo gran contradicción.<br/>',NULL,191401,8);
INSERT INTO stanza VALUES('S562','9','Señor, enséñame a tocar<br/>Sólo la vida que hay en Ti,<br/>Y no tocar el bien o el mal<br/>O lo que no viene de Ti.<br/>',NULL,191402,9);
INSERT INTO stanza VALUES('S563','1','La ley de Dios muy santa es,<br/>Exige practicar el bien;<br/>Nos muestra que_imposible es<br/>A sus demandas responder.<br/>',NULL,191403,1);
INSERT INTO stanza VALUES('S563','2','Mas en la mente hay una ley<br/>Que siempre intenta hacer el bien;<br/>Pero en la carne otra ley<br/>Subyuga a ésta cada vez.<br/>',NULL,191404,2);
INSERT INTO stanza VALUES('S563','3','La mente humana tiene en sí<br/>La ley interna para el bien;<br/>Por el Señor creada fue<br/>Para un buen porte mantener.<br/>',NULL,191405,3);
INSERT INTO stanza VALUES('S563','4','La ley en nuestros miembros es<br/>La ley satánica del mal;<br/>Entró en Adán cuando cayó<br/>Por esa astucia de Satán.<br/>',NULL,191406,4);
INSERT INTO stanza VALUES('S563','5','La ley maligna de Satán<br/>Es de pecado y de maldad;<br/>Más fuerte que la ley del bien<br/>La lleva siempre a fracasar.<br/>',NULL,191407,5);
INSERT INTO stanza VALUES('S563','6','Mas hoy en nuestro espíritu<br/>La misma ley de vida está;<br/>Al renacer nos la impartió<br/>El mismo Espíritu eternal.<br/>',NULL,191408,6);
INSERT INTO stanza VALUES('S563','7','Divina y poderosa es,<br/>Trasciende a todas las demás,<br/>Nos libra de la esclavitud,<br/>Para la ley de Dios lograr.<br/>',NULL,191409,7);
INSERT INTO stanza VALUES('S563','8','Por eso siempre hay que ocupar<br/>La mente en el espíritu,<br/>Y no en la carne que está<br/>Corrupta y en esclavitud.<br/>',NULL,191410,8);
INSERT INTO stanza VALUES('S563','9','La mente puesta en la carne es<br/>Pecado, muerte, oscuridad;<br/>La mente en el espíritu<br/>Trae vida, luz, y dulce paz.<br/>',NULL,191411,9);
INSERT INTO stanza VALUES('S563','10','Así tendremos libertad,<br/>Así victoria se obtendrá;<br/>Señor, que en el espíritu<br/>Contigo siempre pueda andar.<br/>',NULL,191412,10);
INSERT INTO stanza VALUES('S564','1','Define a Dios Su santa ley,<br/>Su testimonio_es en verdad;<br/>Nos muestra nuestro Dios de amor<br/>En Su justicia_y santidad.<br/>',NULL,191413,1);
INSERT INTO stanza VALUES('S564','2','Dios nos exige por Su ley<br/>Que vivamos Su expresión,<br/>Para justificarnos Él,<br/>Y poder darnos bendición.<br/>',NULL,191414,2);
INSERT INTO stanza VALUES('S564','3','La ley jamás vida dará,<br/>Ni fuerzas suministrará;<br/>Sólo demanda y saca a luz<br/>Nuestra gran incapacidad.<br/>',NULL,191415,3);
INSERT INTO stanza VALUES('S564','4','No para el plan final de Dios<br/>Fue que se introdujo la ley,<br/>Mas para que el pecador<br/>Su iniquidad pudiera ver.<br/>',NULL,191416,4);
INSERT INTO stanza VALUES('S564','5','La ley, las bocas calla hoy,<br/>Pues bajo el pecado están;<br/>La ley a Cristo nos llevó,<br/>Y en Él, Dios bendición nos da.<br/>',NULL,191417,5);
INSERT INTO stanza VALUES('S564','6','La ley es tipo de Jesús,<br/>Quién es testimonio de Dios;<br/>Expresa Él Su santidad<br/>Y Su justicia en amor.<br/>',NULL,191418,6);
INSERT INTO stanza VALUES('S564','7','Es Cristo el testimonio real,<br/>Quien trae la vida divinal;<br/>Lo que nos demanda la ley<br/>Se puede en Él ejecutar.<br/>',NULL,191419,7);
INSERT INTO stanza VALUES('S564','8','Es testimonio de Dios, Él;<br/>Por quien Dios nos regeneró;<br/>Por Él morimos a la ley<br/>Y damos frutos para Dios.<br/>',NULL,191420,8);
INSERT INTO stanza VALUES('S565','1','La ley de Dios antigua fue<br/>Grabada_en letras de piedra;<br/>Ahora_es ley de vida que<br/>En nuestro corazón está.<br/>',NULL,191421,1);
INSERT INTO stanza VALUES('S565','2','La antigua ley exige el bien,<br/>Descubre así el débil ser;<br/>La ley de vida, fuerza da<br/>Para al Señor satisfacer.<br/>',NULL,191422,2);
INSERT INTO stanza VALUES('S565','3','La antigua ley revela a Dios<br/>Solo en la forma exterior;<br/>La ley de vida proveerá<br/>Su realidad en lo interior.<br/>',NULL,191423,3);
INSERT INTO stanza VALUES('S565','4','La antigua ley puede regir<br/>Por mandamiento exterior;<br/>La ley de vida reina hoy<br/>Por un sentir en lo interior.<br/>',NULL,191424,4);
INSERT INTO stanza VALUES('S565','5','Esta viviente ley está<br/>Moviéndose en nuestro andar;<br/>Por su sentido interior<br/>Nos puede en todo refrenar.<br/>',NULL,191425,5);
INSERT INTO stanza VALUES('S565','6','¡Profunda es su regulación!<br/>Opera desde lo interior,<br/>Una conciencia viva da<br/>Y nos imparte al mismo Dios.<br/>',NULL,191426,6);
INSERT INTO stanza VALUES('S565','7','Por ser tan viva esta ley<br/>No nos enseña en lo exterior;<br/>Pues todo el saber de Dios<br/>Nos lo revela en lo interior.<br/>',NULL,191427,7);
INSERT INTO stanza VALUES('S565','8','Enséñanos, Señor, a andar<br/>Conforme a esta interna ley,<br/>Para de Ti participar<br/>Y conocerte en nuestro ser.<br/>',NULL,191428,8);
INSERT INTO stanza VALUES('S566','1','Para dar fin al hombre natural,<br/>¡La ley de vida,_amén!<br/>Es automática en su obrar,<br/>¡La ley de vida,_amén!<br/>',NULL,191429,1);
INSERT INTO stanza VALUES('S566','chorus','¡La ley de vida,_amén!<br/>¡La ley de vida,_amén!<br/>Cristo transforma y nos conforma,<br/>¡La ley de vida,_amén!<br/>',NULL,191430,2);
INSERT INTO stanza VALUES('S566','2','Vida divina su origen es,<br/>¡La ley de vida,_amén!<br/>Innata es su función y su poder,<br/>¡La ley de vida,_amén!<br/>',NULL,191431,3);
INSERT INTO stanza VALUES('S566','chorus','¡La ley de vida,_amén!<br/>¡La ley de vida,_amén!<br/>Tu esfuerzo deja; la vida opera,<br/>¡La ley de vida,_amén!<br/>',NULL,191432,4);
INSERT INTO stanza VALUES('S566','3','Cumple esta ley lo que desea Dios,<br/>¡La ley de vida,_amén!<br/>Esfuerzo humano no requiere hoy,<br/>¡La ley de vida,_amén!<br/>',NULL,191433,5);
INSERT INTO stanza VALUES('S566','chorus','¡La ley de vida,_amén!<br/>¡La ley de vida,_amén!<br/>Su plan logramos; prestos estamos,<br/>¡La ley de vida,_amén!<br/>',NULL,191434,6);
INSERT INTO stanza VALUES('S566','4','Qué metabólica transformación,<br/>¡La ley de vida,_amén!<br/>Corporativa es su saturación,<br/>¡La ley de vida,_amén!<br/>',NULL,191435,7);
INSERT INTO stanza VALUES('S566','chorus','¡La ley de vida,_amén!<br/>¡La ley de vida,_amén!<br/>El yo olvida; Dios nos da vida,<br/>¡La ley de vida,_amén!<br/>',NULL,191436,8);
INSERT INTO stanza VALUES('S566','5','Inscribe_a Cristo_en nuestro corazón,<br/>¡La ley de vida,_amén!<br/>Hasta que_escrito_esté_en nuestro_interior,<br/>¡La ley de vida,_amén!<br/>',NULL,191437,9);
INSERT INTO stanza VALUES('S566','chorus','¡La ley de vida,_amén!<br/>¡La ley de vida,_amén!<br/>Cristo es grabado, no imitado,<br/>¡La ley de vida,_amén!<br/>',NULL,191438,10);
INSERT INTO stanza VALUES('S567','1','Trae la vida_eterna<br/>Comunión y luz,<br/>Salvación y vida,<br/>En Espíritu.<br/>',NULL,191439,1);
INSERT INTO stanza VALUES('S567','2','Por la vida eterna<br/>En la comunión,<br/>El Señor se une<br/>A nosotros hoy.<br/>',NULL,191440,2);
INSERT INTO stanza VALUES('S567','3','Su Espíritu brinda<br/>Vida en comunión;<br/>Comunión que equipa<br/>Con gracia y amor.<br/>',NULL,191441,3);
INSERT INTO stanza VALUES('S567','4','Conlleva la vida<br/>Recta comunión;<br/>Comunión que rinde<br/>Luz y perfección.<br/>',NULL,191442,4);
INSERT INTO stanza VALUES('S567','5','La limpieza externa<br/>Con la interna unción,<br/>Nos guarda y mantiene<br/>En la comunión.<br/>',NULL,191443,5);
INSERT INTO stanza VALUES('S567','6','Comunión más honda<br/>Viene por la cruz;<br/>Comunión más alta<br/>Por Su Espíritu,<br/>',NULL,191444,6);
INSERT INTO stanza VALUES('S567','7','Comunión que libra<br/>Del malvado yo;<br/>Comunión que lleva<br/>Hasta el mismo Dios.<br/>',NULL,191445,7);
INSERT INTO stanza VALUES('S568','1','En toda vida el sentir<br/>De vida siempre_está;<br/>En mí la vida eternal<br/>Sentir divino da.<br/>',NULL,191446,1);
INSERT INTO stanza VALUES('S568','2','Cuanto mayor la vida es,<br/>Mejor es su sentir;<br/>La máxima es la de Dios,<br/>Con el mayor sentir.<br/>',NULL,191447,2);
INSERT INTO stanza VALUES('S568','3','Este sentir de vida en mí<br/>Es el sentir de Dios;<br/>Supera el sentir del bien,<br/>Es vida en mi interior.<br/>',NULL,191448,3);
INSERT INTO stanza VALUES('S568','4','Este sentir de vida es<br/>Lo más profundo en mí;<br/>Discierne lo que es de Dios,<br/>Y lo descubre así.<br/>',NULL,191449,4);
INSERT INTO stanza VALUES('S568','5','Por el sentir de vida en mí<br/>Conozco a mi Dios;<br/>No por mi esfuerzo exterior,<br/>Mas por revelación.<br/>',NULL,191450,5);
INSERT INTO stanza VALUES('S568','6','Por el crecer de vida en mí<br/>Más claro es su sentir;<br/>Si más estricto es mi andar,<br/>Más crece en mi vivir.<br/>',NULL,191451,6);
INSERT INTO stanza VALUES('S568','7','Si ejercito el sentir<br/>De la vida interior,<br/>Mi espíritu ha de crecer<br/>En fuerza y comunión.<br/>',NULL,191452,7);
INSERT INTO stanza VALUES('S569','1','En todos los que Dios regeneró<br/>Hay cierto conocimiento_interior;<br/>No la_enseñanza externa e_inferior,<br/>Sino_en lo_interno conocer a Dios.<br/>',NULL,191453,1);
INSERT INTO stanza VALUES('S569','2','La vida eterna en su capacidad<br/>Es la más alta y es la mejor;<br/>Nos hace a fondo conocer a Dios,<br/>Más que el conocimiento exterior.<br/>',NULL,191454,2);
INSERT INTO stanza VALUES('S569','3','La ley de vida a la mente va,<br/>Se graba en vivo en el corazón;<br/>Internamente nos regula hoy,<br/>Más que la enseñanza exterior.<br/>',NULL,191455,3);
INSERT INTO stanza VALUES('S569','4','Unción divina en el espíritu,<br/>Llega a la mente y hasta el corazón,<br/>Más que las enseñanzas, esta unción<br/>Nos da el conocimiento del gran Dios.<br/>',NULL,191456,4);
INSERT INTO stanza VALUES('S569','5','El Triuno Dios reside en nuestro ser,<br/>Viviendo, actuando, obrando sin cesar,<br/>Para que por el sentir interior<br/>Le conozcamos en Su infinidad.<br/>',NULL,191457,5);
INSERT INTO stanza VALUES('S569','6','Este conocimiento interior<br/>Supera la elocuencia exterior;<br/>Pero hay que en el espíritu vivir<br/>Y andar por el sentido interior.<br/>',NULL,191458,6);
INSERT INTO stanza VALUES('S569','7','Si en Cristo por la vida divinal<br/>Vivimos con conciencia interior,<br/>Dios Su conocimiento nos dará,<br/>Grabando a Su Hijo en nuestro corazón.<br/>',NULL,191459,7);
INSERT INTO stanza VALUES('S569','8','Por tal conocimiento interior<br/>Con Dios tenemos viva comunión,<br/>Y, de este modo, Dios Su plenitud<br/>Nos da a conocer en lo interior.<br/>',NULL,191460,8);
INSERT INTO stanza VALUES('S570','1','El principio de encarnación<br/>Es Dios y_el hombre en unión,<br/>Los dos actuando_en cooperación,<br/>Cumpliendo_así el plan de Dios.<br/>',NULL,191461,1);
INSERT INTO stanza VALUES('S570','2','Dios es la vida para el hombre,<br/>Y el hombre es Su expresión;<br/>Dios por el hombre es expresado<br/>Y el hombre es Su posesión.<br/>',NULL,191462,2);
INSERT INTO stanza VALUES('S570','3','La redención del hombre muestra<br/>La sabiduría de Dios;<br/>Y hoy Su salvación el hombre<br/>Proclama a toda la creación.<br/>',NULL,191463,3);
INSERT INTO stanza VALUES('S570','4','Requiere Dios en Su servicio<br/>Una mutua cooperación,<br/>El hombre y Dios bien coordinados<br/>En una estrecha relación.<br/>',NULL,191464,4);
INSERT INTO stanza VALUES('S570','5','No es que Dios trabaje solo,<br/>O el hombre en emancipación;<br/>Mas estos dos obrando juntos<br/>Realizarán el plan de Dios.<br/>',NULL,191465,5);
INSERT INTO stanza VALUES('S570','6','El principio de encarnación<br/>A toda obra hay que aplicar,<br/>A nuestros dones y funciones<br/>Para servir en unidad.<br/>',NULL,191466,6);
INSERT INTO stanza VALUES('S571','1','Hemos sido destinados<br/>Para "hijificación":<br/>A la_imagen de Su Hijo,<br/>Conformarnos quiere Dios.<br/>Para que Su_único Hijo<br/>Sea_el Primogénito<br/>Entre todos Sus hermanos,<br/>Obteniendo Su expresión.<br/>',NULL,191467,1);
INSERT INTO stanza VALUES('S571','2','Somos hijos del Dios Padre<br/>Por la regeneración,<br/>Mas la primogenitura<br/>Se obtendrá por filiación;<br/>Al crecer maduraremos<br/>Esta es nuestra porción;<br/>Al llegar a Su estatura<br/>Se verá la filiación.<br/>',NULL,191468,2);
INSERT INTO stanza VALUES('S571','3','Nuestro espíritu, alma y cuerpo<br/>Conformados al Señor.<br/>Esto ha de consumarse<br/>Cuando venga el Salvador.<br/>Por la redención del cuerpo<br/>Se cumple la fliliación,<br/>Y el propósito eterno<br/>Por la transfiguración.<br/>',NULL,191469,3);
INSERT INTO stanza VALUES('S571','4','Santificación completa<br/>Por tal transfiguración<br/>Nos iguala al Amado<br/>En Su glorificación.<br/>La creación anhela ardiente<br/>La gran manifestación<br/>De estos hijos en su gloria,<br/>Y en total liberación.<br/>',NULL,191470,4);
INSERT INTO stanza VALUES('S572','1','El hombre tripartito es,<br/>Un cuerpo y_alma se le dio<br/>Con un espíritu también<br/>Para que cumpla_el plan de Dios.<br/>',NULL,191471,1);
INSERT INTO stanza VALUES('S572','2','El cuerpo, la parte exterior,<br/>Puede lo físico tocar,<br/>Para lo externo percibir,<br/>Y el ser interno expresar.<br/>',NULL,191472,2);
INSERT INTO stanza VALUES('S572','3','El alma, la parte interior,<br/>El propio yo del hombre es;<br/>Para lo psíquico notar,<br/>Le da sentido de su ser.<br/>',NULL,191473,3);
INSERT INTO stanza VALUES('S572','4','Lo más profundo de su ser<br/>Es el espíritu en él<br/>Que puede recibir a Dios,<br/>Y lo divino comprender.<br/>',NULL,191474,4);
INSERT INTO stanza VALUES('S572','5','Hay en el hombre un alma con<br/>Mente, emocion y voluntad;<br/>Estas funciones buenas son<br/>Para lo humano realizar.<br/>',NULL,191475,5);
INSERT INTO stanza VALUES('S572','6','Hay en el hombre espíritu,<br/>Tiene conciencia, comunión<br/>E intuición, para que él<br/>Rinda a Dios adoración.<br/>',NULL,191476,6);
INSERT INTO stanza VALUES('S572','7','El hombre debe ejercitar<br/>Su espíritu y a Dios ganar;<br/>Su alma a Dios debe escoger,<br/>Su cuerpo a Dios debe expresar.<br/>',NULL,191477,7);
INSERT INTO stanza VALUES('S572','8','El hombre debe renacer,<br/>Con vida en su espíritu;<br/>Dios debe su alma transformar,<br/>Y el cuerpo de él transfigurar.<br/>',NULL,191478,8);
INSERT INTO stanza VALUES('S572','9','Por esta obra divinal,<br/>Se mezcla el hombre con su Dios;<br/>Dios cada parte al saturar<br/>Hace del hombre Su expresión.<br/>',NULL,191479,9);
INSERT INTO stanza VALUES('S573','1','Nos creó Dios como vasos<br/>Para Su_expresión lograr,<br/>Con un corazón que lo_ame<br/>Y_un espíritu sin par.<br/>',NULL,191480,1);
INSERT INTO stanza VALUES('S573','2','Debe el corazón amarlo,<br/>Y el espíritu aceptar<br/>Al Señor como su vida<br/>Para poderlo expresar.<br/>',NULL,191481,2);
INSERT INTO stanza VALUES('S573','3','Nos hirió Satán con muerte,<br/>Corrompiendo el corazón,<br/>Para que en el yo vivamos<br/>Y aislarnos del Señor.<br/>',NULL,191482,3);
INSERT INTO stanza VALUES('S573','4','Mas la salvación de Cristo<br/>Renueva el espíritu,<br/>Y del corazón recobra<br/>Su amante aptitud.<br/>',NULL,191483,4);
INSERT INTO stanza VALUES('S573','5','Con tal corazón buscamos<br/>En amor a nuestro Dios,<br/>Y en espíritu avivados<br/>Contactamos al Señor.<br/>',NULL,191484,5);
INSERT INTO stanza VALUES('S573','6','Siempre puro y verdadero<br/>Debe ser el corazón,<br/>Y en espíritu ser pobres<br/>Para contactar a Dios.<br/>',NULL,191485,6);
INSERT INTO stanza VALUES('S573','7','Guarda nuestros corazones<br/>En lo fresco de Tu amor,<br/>Y al espíritu da fuerzas<br/>Para tocarte, Señor.<br/>',NULL,191486,7);
INSERT INTO stanza VALUES('S574','1','Para tratar con el Señor<br/>Y por Su vida_andar,<br/>Requiere_un corazón cabal,<br/>Para_en Su gracia_entrar.<br/>',NULL,191487,1);
INSERT INTO stanza VALUES('S574','2','Requiere_un puro corazón,<br/>Muy cuerdo_en su pensar,<br/>Con una mente para Dios,<br/>Que tiemble_a Su hablar.<br/>',NULL,191488,2);
INSERT INTO stanza VALUES('S574','3','Requiere_un corazón de amor,<br/>Ardiente_en su sentir,<br/>Lleno de celo_en su_emoción,<br/>Para_Él sin transigir.<br/>',NULL,191489,3);
INSERT INTO stanza VALUES('S574','4','Requiere_un corazón veraz,<br/>Sumisa voluntad,<br/>Flexible_y fuerte ha de ser,<br/>Para cumplir Su plan.<br/>',NULL,191490,4);
INSERT INTO stanza VALUES('S574','5','Requiere_un libre corazón<br/>Do no_hay condenación;<br/>Una conciencia que purgó,<br/>La sangre del Señor.<br/>',NULL,191491,5);
INSERT INTO stanza VALUES('S574','6','Danos, Señor, tal corazón,<br/>Por siempre fijo_en Ti,<br/>Para lograr Tu plenitud,<br/>Participando_en Ti.<br/>',NULL,191492,6);
INSERT INTO stanza VALUES('S575','1','Señor, Espíritu_eres hoy<br/>En nuestro_espíritu;<br/>Los dos ahora uno son,<br/>Vida le_impartes Tú.<br/>',NULL,191493,1);
INSERT INTO stanza VALUES('S575','2','Tu Espíritu al nuestro da<br/>Testimonio eternal<br/>Que, por ser hijos hoy de Dios,<br/>Su gloria nos dará.<br/>',NULL,191494,2);
INSERT INTO stanza VALUES('S575','3','En nuestro espíritu al tocar<br/>Tu divinal caudal,<br/>Como Espíritu nos das<br/>Tu vida celestial.<br/>',NULL,191495,3);
INSERT INTO stanza VALUES('S575','4','En nuestro espíritu estás,<br/>Guiando nuestro andar;<br/>Como el Espíritu, Señor,<br/>Luz nos impartirás.<br/>',NULL,191496,4);
INSERT INTO stanza VALUES('S575','5','En nuestro espíritu, Señor,<br/>Hoy te adoramos más;<br/>El Tuyo al nuestro vida da,<br/>Nos fortalecerá.<br/>',NULL,191497,5);
INSERT INTO stanza VALUES('S575','6','En nuestro espíritu, Señor,<br/>Alzamos oración;<br/>Mientras, como Espíritu,<br/>Guimes en lo interior.<br/>',NULL,191498,6);
INSERT INTO stanza VALUES('S575','7','Volviendo a nuestro espíritu<br/>Y al contactarte allí,<br/>Participamos cada vez<br/>De nuestra herencia en Ti.<br/>',NULL,191499,7);
INSERT INTO stanza VALUES('S575','8','¡Qué dulce unión! Oh mi Señor,<br/>Entrelazado estás<br/>Con nuestro espíritu y allí<br/>Por siempre morarás.<br/>',NULL,191500,8);
INSERT INTO stanza VALUES('S576','1','Que yo mi_espíritu discierna<br/>De mi_alma, ruego_a Ti, Señor;<br/>Pues con mi_espíritu el Tuyo<br/>Está mezclado en unión.<br/>',NULL,191501,1);
INSERT INTO stanza VALUES('S576','2','Que yo mi espíritu discierna<br/>Para mi alma hoy negar,<br/>Así en mi espíritu te puedo<br/>Seguir y_en todo aplicar.<br/>',NULL,191502,2);
INSERT INTO stanza VALUES('S576','3','Que yo mi espíritu discierna,<br/>Mi mente así podré fijar<br/>No en la carne de pecado,<br/>Sino en mi espíritu vital.<br/>',NULL,191503,3);
INSERT INTO stanza VALUES('S576','4','Que yo mi espíritu discierna<br/>Para en mi alma no vivir,<br/>Sino, en mi espíritu andando,<br/>Yo todo pueda discernir.<br/>',NULL,191504,4);
INSERT INTO stanza VALUES('S576','5','Que yo mi espíritu discierna,<br/>Oh, hazme ver el yo sutil;<br/>Para que yo la cruz aplique<br/>Y pueda así por Ti vivir.<br/>',NULL,191505,5);
INSERT INTO stanza VALUES('S576','6','Que yo mi espíritu discierna<br/>Hasta mi alma transformar,<br/>Y, conformado a Tu_imagen,<br/>A madurez he de llegar.<br/>',NULL,191506,6);
INSERT INTO stanza VALUES('S576','7','Parte el espíritu y el alma<br/>Por Tu Palabra eficaz;<br/>Señor, que viva así por siempre<br/>En el Santísimo Lugar.<br/>',NULL,191507,7);
INSERT INTO stanza VALUES('S577','1','En el lugar más interior<br/>Del templo santo del Señor,<br/>Gozaban plena comunión<br/>Los sacerdotes con su Dios.<br/>',NULL,191508,1);
INSERT INTO stanza VALUES('S577','2','Su templo santo somos hoy,<br/>Tenemos un espíritu,<br/>Y Cristo allí junto con Dios<br/>Habita como Espíritu.<br/>',NULL,191509,2);
INSERT INTO stanza VALUES('S577','3','En esta parte interior<br/>Hoy Dios en Cristo el todo es;<br/>Aquí el Santo Espíritu<br/>Lo hace real a nuestro ser.<br/>',NULL,191510,3);
INSERT INTO stanza VALUES('S577','4','Aquí en nuestro espíritu<br/>A Dios podemos adorar,<br/>Tocar a Cristo en comunión,<br/>Y en Su presencia habitar.<br/>',NULL,191511,4);
INSERT INTO stanza VALUES('S577','5','Aquí la tierra Cristo es<br/>Con las riquezas de Canaan;<br/>Aquí con Su autoridad<br/>Luchamos contra el rival.<br/>',NULL,191512,5);
INSERT INTO stanza VALUES('S577','6','Hoy nuestro espíritu interior<br/>Del alma hay que discernir;<br/>Este "Santísimo Lugar"<br/>Es donde debemos vivir.<br/>',NULL,191513,6);
INSERT INTO stanza VALUES('S577','7','El alma hay que rechazar<br/>Para al descanso hoy entrar,<br/>A Cristo en pleno poseer<br/>Y el plan de Dios ejecutar.<br/>',NULL,191514,7);
INSERT INTO stanza VALUES('S578','1','El espíritu discierne,<br/>Pon el alma en la cruz;<br/>Niega el ego_en codo tiempo,<br/>Anda_en el espíritu.<br/>',NULL,191515,1);
INSERT INTO stanza VALUES('S578','2','Por la cruz si lo disciernes,<br/>La Palabra partirá<br/>El espíritu del alma<br/>Y en espíritu andarás.<br/>',NULL,191516,2);
INSERT INTO stanza VALUES('S578','3','El espíritu discierne,<br/>Pon la mente a renovar,<br/>La emoción sea consagrada<br/>Con sumisa voluntad.<br/>',NULL,191517,3);
INSERT INTO stanza VALUES('S578','4','Por la cruz si lo disciernes,<br/>Por el velo pasarás,<br/>Alma y carne quebrantadas,<br/>Tu espíritu regirá.<br/>',NULL,191518,4);
INSERT INTO stanza VALUES('S578','5','El espíritu discierne,<br/>Es santísimo el lugar,<br/>Donde comunión el hombre<br/>Con su Dios disfrutará.<br/>',NULL,191519,5);
INSERT INTO stanza VALUES('S578','6','Por la cruz si lo disciernes,<br/>Cruzarás el gran Jordán;<br/>Sólo por la cruz se obtienen<br/>Las riquezas de Canaán.<br/>',NULL,191520,6);
INSERT INTO stanza VALUES('S578','7','El espíritu discierne,<br/>Para en Cristo laborar;<br/>En la buena tierra obrando<br/>Sus riquezas ganarás.<br/>',NULL,191521,7);
INSERT INTO stanza VALUES('S579','1','El Santo Espíritu de Dios<br/>En nuestro espíritu está;<br/>Él quiere_en nuestro ser fluir<br/>Y_a Dios en Cristo expresar.<br/>',NULL,191522,1);
INSERT INTO stanza VALUES('S579','2','Mas nuestro hombre natural<br/>Lo ha confinado en lo interior;<br/>Y en vez de darle un hogar,<br/>Se constituye una prisión.<br/>',NULL,191523,2);
INSERT INTO stanza VALUES('S579','3','Él es tesoro de valor<br/>Guardado en vaso terrenal;<br/>Se debe el vaso quebrantar<br/>Para el tesoro develar.<br/>',NULL,191524,3);
INSERT INTO stanza VALUES('S579','4','Él debe quebrantar el yo,<br/>¡Qué estorbo es el hombre exterior!<br/>Al quebrantarlo, librará<br/>Al Santo Espíritu de Dios.<br/>',NULL,191525,4);
INSERT INTO stanza VALUES('S579','5','Por esto nos envía Dios<br/>Algún sufrir circunstancial,<br/>Para quebrar en lo exterior<br/>A este hombre natural.<br/>',NULL,191526,5);
INSERT INTO stanza VALUES('S579','6','Que sea consumido el yo,<br/>Que mengüe el alma es menester;<br/>Para que nuestro espíritu<br/>Librado con el Suyo esté<br/>',NULL,191527,6);
INSERT INTO stanza VALUES('S579','7','No quiero entero siempre estar<br/>Quebrántame, oh mi Señor;<br/>Y que dispuesto yo esté<br/>A recibir Tus tratos hoy.<br/>',NULL,191528,7);
INSERT INTO stanza VALUES('S579','8','Que yo aprecie el quebrantar,<br/>Y toda queja deje atrás;<br/>Concédeme siempre estimar<br/>Más el perder que el ganar.<br/>',NULL,191529,8);
INSERT INTO stanza VALUES('S580','1','Dios desea conformarnos,<br/>Al amado Redentor;<br/>Por Su_Espíritu lo cumple<br/>Con poder transformador.<br/>',NULL,191530,1);
INSERT INTO stanza VALUES('S580','chorus','Nos transforme a Tu_imagen<br/>Tu Espíritu, Señor;<br/>Nos sature por completo<br/>Voluntad, mente,_emoción.<br/>',NULL,191531,2);
INSERT INTO stanza VALUES('S580','2','Dios nos ha regenerado,<br/>Nuestro espíritu avivó;<br/>Esta vida llega al alma<br/>Para obrar transformación.<br/>',NULL,191532,3);
INSERT INTO stanza VALUES('S580','3','Del espíritu se extiende,<br/>Para el alma transformar;<br/>Cada parte Él renueva,<br/>Hasta todas controlar.<br/>',NULL,191533,4);
INSERT INTO stanza VALUES('S580','4','Por Su Espíritu de vida<br/>Nos transforma con poder;<br/>De Su gloria a Su gloria,<br/>Como Él hemos de ser.<br/>',NULL,191534,5);
INSERT INTO stanza VALUES('S580','5','Nos transforma y santifica,<br/>Hasta que haya madurez;<br/>Posee el alma, la transforma,<br/>Hasta Su estatura ver.<br/>',NULL,191535,6);
INSERT INTO stanza VALUES('S581','1','No por mis esfuerzos,<br/>Sino al ceder,<br/>Caen hoy mis cargas<br/>Y descansaré.<br/>Es al escucharte,<br/>No al resolver,<br/>Que yo del pecado<br/>Libre puedo ser.<br/>',NULL,191536,1);
INSERT INTO stanza VALUES('S581','2','No es por la letra,<br/>Mas Tu Espíritu,<br/>Que puedo ser justo<br/>En vida y virtud.<br/>No es la enseñanza,<br/>Sino Tu unción,<br/>Lo que imparte vida<br/>Dando comunión.<br/>',NULL,191537,2);
INSERT INTO stanza VALUES('S581','3','No es diciendo:<br/>"Hoy voy a correr",<br/>Sino obteniendo<br/>Tu piedad tan fiel.<br/>No el conocimiento,<br/>Mas Tu gracia hará<br/>Que en los sufrimientos<br/>Te pueda expresar.<br/>',NULL,191538,3);
INSERT INTO stanza VALUES('S581','4','No mi elocuencia,<br/>Sino Tu poder,<br/>Puede a los perdidos<br/>Tu vida traer;<br/>No mi inteligencia,<br/>Mas Tu Espíritu,<br/>Cumple Tu Palabra<br/>En su plenitud.<br/>',NULL,191539,4);
INSERT INTO stanza VALUES('S582','1','Dios nos dio, Dios nos dio, Sus promesas dio;<br/>Fe preciosas_y poder divinal legó.<br/>Estos tres nuestros son al creer en Él;<br/>Por ellos llegamos a la madurez.<br/>',NULL,191540,1);
INSERT INTO stanza VALUES('S582','2','Es preciosa esta fe en los santos hoy;<br/>Nos mantiene hasta ver su consumación.<br/>Si dispuestos o no, ella sostendrá;<br/>Cada día y siempre, ella perdurará.<br/>',NULL,191541,2);
INSERT INTO stanza VALUES('S582','3','Es divino el poder que por dentro está;<br/>Esta fuente interior, todo proveerá<br/>Para que Dios así se pueda expresar<br/>Por Su misma vida como la piedad.<br/>',NULL,191542,3);
INSERT INTO stanza VALUES('S582','4','Sus promesas legó a nosotros, Dios;<br/>Ellas grandísimas y preciosas son.<br/>De Su naturaleza al participar,<br/>Del corrupto mundo se puede escapar.<br/>',NULL,191543,4);
INSERT INTO stanza VALUES('S582','5','Cristo como poder vive en lo interior;<br/>Él la Palabra es en nuestro interior.<br/>Contactémoslo hoy para así crecer,<br/>Orando, leyendo y clamando a Él.<br/>',NULL,191544,5);
INSERT INTO stanza VALUES('S582','6','Las promesas, la fe y el poder de Dios,<br/>Todos ellos nos dan plena provisión;<br/>Si a los tres damos hoy toda la atención,<br/>Crecerá, desde la fe, nuestro amor.<br/>',NULL,191545,6);
INSERT INTO stanza VALUES('S582','7','La semilla de fe Sus virtudes da;<br/>Crecerá en nuestro ser, frutos llevará.<br/>Hay que ver todo lo que Dios empezó,<br/>No ser ciegos, ni olvidad lo que Él logró.<br/>',NULL,191546,7);
INSERT INTO stanza VALUES('S582','8','Diligencia en verdad nos hará crecer,<br/>Y que nuestra elección más segura esté.<br/>La semilla al cuidar, suministrará<br/>La abundante entrada al reino eternal.<br/>',NULL,191547,8);
INSERT INTO stanza VALUES('S582','9','Hoy nos damos, Señor, para así crecer<br/>Y vivir por la fe y por Tu poder.<br/>Tus promesas serán nuestra base fiel,<br/>Para cooperar contigo en nuestro ser.<br/>',NULL,191548,9);
INSERT INTO stanza VALUES('S583','1','Ya el Señor mostró Su plan<br/>A todo santo fiel<br/>Que deja este mundo_atrás<br/>Y_es virgen para Él.<br/>Para Su propia Novia ser<br/>Hay que ser como Él,<br/>Y disfrutarlo sin cesar<br/>En todo_y por doquier.<br/>',NULL,191549,1);
INSERT INTO stanza VALUES('S583','2','¡Oh, haznos esas vírgenes,<br/>Tan llenas de amor,<br/>Que siempre junto al Novio están!<br/>¡Oh, haznos tales hoy!<br/>Que seamos sabios, oh Señor,<br/>Ganando más de Ti;<br/>Gozando a diario del festín,<br/>Pagando el precio aquí.<br/>',NULL,191550,2);
INSERT INTO stanza VALUES('S583','3','Las vírgenes madurarán<br/>En vida al crecer;<br/>De una forma muy normal<br/>Comiendo a diario de Él.<br/>Es hoy nuestra necesidad<br/>La madurez, Señor;<br/>No ciencia, dones, o poder,<br/>Mas Cristo en lo interior.<br/>',NULL,191551,3);
INSERT INTO stanza VALUES('S583','4','Como simiente viva, Tú<br/>Debes crecer, Señor,<br/>Ganando más terreno así<br/>En nuestro corazón.<br/>Da fuerza al hombre interior,<br/>Y a cada parte ve;<br/>Contigo llénanos, Señor,<br/>Y habita nuestro ser.<br/>',NULL,191552,4);
INSERT INTO stanza VALUES('S584','1','Excavad, excavad, excavad,<br/>¡La condenación del alma excavad!<br/>Excavad, excavad, excavad,<br/>¡La condenación del alma excavad!<br/>',NULL,191553,1);
INSERT INTO stanza VALUES('S584','chorus','¡Toda culpa quitad!<br/>Y Su vida fluirá ...¡Aleluya!<br/>Excavad, excavad, excavad,<br/>¡La condenación del alma excavad!<br/>',NULL,191554,2);
INSERT INTO stanza VALUES('S584','2','Excavad, excavad, excavad,<br/>¡La imaginación tan vana excavad!<br/>Excavad, excavad, excavad,<br/>¡La imaginación tan vana excavad!<br/>',NULL,191555,3);
INSERT INTO stanza VALUES('S584','chorus','¡Sueños vanos quitad!<br/>Y Su vida fluirá ...¡Aleluya!<br/>Excavad, excavad, excavad,<br/>¡La imaginación tan vana excavad!<br/>',NULL,191556,4);
INSERT INTO stanza VALUES('S584','3','Excavad, excavad, excavad,<br/>¡Emociones enfadosas excavad!<br/>Excavad, excavad, excavad,<br/>¡Emociones enfadosas excavad!<br/>',NULL,191557,5);
INSERT INTO stanza VALUES('S584','chorus','¡Egoísmo quitad!<br/>Y Su vida fluirá ...¡Aleluya!<br/>Excavad, excavad, excavad,<br/>¡Emociones enfadosas excavad!<br/>',NULL,191558,6);
INSERT INTO stanza VALUES('S584','4','Excavad, excavad, excavad,<br/>¡Hoy el alma obstinada excavad!<br/>Excavad, excavad, excavad,<br/>¡Hoy el alma obstinada excavad!<br/>',NULL,191559,7);
INSERT INTO stanza VALUES('S584','chorus','¡Terquedad ya quitad!<br/>Y Su vida fluirá...¡Aleluya!<br/>Excavad, excavad, excavad,<br/>¡Hoy el alma obstinada excavad!<br/>',NULL,191560,8);
INSERT INTO stanza VALUES('S584','5','Excavad, excavad, excavad,<br/>¡Egoísmo en el alma excavad!<br/>Excavad, excavad, excavad,<br/>¡Egoísmo en el alma excavad!<br/>',NULL,191561,9);
INSERT INTO stanza VALUES('S584','chorus','¡Vanidad ya quitad!<br/>Y Su vida fluirá...¡Aleluya!<br/>Excavad, excavad, excavad,<br/>¡Egoísmo en el alma excavad!<br/>',NULL,191562,10);
INSERT INTO stanza VALUES('S584','6','Vida así fluirá, ¡Gloria a Dios!<br/>¡Fluye vida desde nuestro corazón!<br/>Vida así fluirá, ¡Gloria á Dios!<br/>¡Fluye vida desde nuestro corazón!<br/>',NULL,191563,11);
INSERT INTO stanza VALUES('S584','chorus','Libre así el corazón,<br/>¡Cristo fluye hoy!...¡Aleluya!<br/>Vida así fluirá, ¡Gloria a Dios!<br/>¡Fluye vida desde nuestro corazón!<br/>',NULL,191564,12);
INSERT INTO stanza VALUES('S585','1','Nuestra vida_interior es Cristo el Señor,<br/>Que rige nuestro andar y la reunión;<br/>Viviéndolo a Él en nuestro diario_andar,<br/>La_iglesia se verá en la reunión.<br/>',NULL,191565,1);
INSERT INTO stanza VALUES('S585','2','Nuestra vida_interior es Cristo el Señor,<br/>En nuestro espíritu, ¡cuán cerca está!<br/>Volviéndonos a Él, tomándolo por fe,<br/>Nuestra vida interior Cristo será.<br/>',NULL,191566,2);
INSERT INTO stanza VALUES('S585','3','De la vida interior procede nuestro andar,<br/>Y Cristo llena así nuestro vivir;<br/>Y al vivir por Él, Él vive en nuestro ser<br/>Para que Su vivir se pueda ver.<br/>',NULL,191567,3);
INSERT INTO stanza VALUES('S585','4','Tal experiencia real de Cristo en nuestro andar,<br/>De Cristo llenará nuestra reunión;<br/>No formas sin valor, mas Cristo en Su expresión<br/>Se manifestará en nuestra reunión.<br/>',NULL,191568,4);
INSERT INTO stanza VALUES('S585','5','Sin la vida interior no existe un vivir,<br/>Tampoco la reunión ni iglesia real;<br/>Mas Cristo en lo interior vivido a diario<br/>Hará que la reunión gloriosa esté.<br/>',NULL,191569,5);
INSERT INTO stanza VALUES('S586','1','A los que temen a Jehová,<br/>En la Palabra dicho_está:<br/>El Sol de la justicia trae<br/>Alas de sanidad.<br/>',NULL,191570,1);
INSERT INTO stanza VALUES('S586','2','A los que el nombre temen hoy,<br/>El Salvador poder les da;<br/>Al contristado corazón,<br/>Sus alas sanarán.<br/>',NULL,191571,2);
INSERT INTO stanza VALUES('S586','3','El Sol de la justicia es Él;<br/>Mas, al asirnos del pecar,<br/>No obtendremos sanidad,<br/>Ni en Sus alas, paz.<br/>',NULL,191572,3);
INSERT INTO stanza VALUES('S586','4','Sus alas sanan el dolor,<br/>Hasta el veneno disipar;<br/>Mas en Su seno hay que estar<br/>Para hallar sanidad.<br/>',NULL,191573,4);
INSERT INTO stanza VALUES('S586','5','Sus alas sanadoras hoy<br/>Mi corazón hacen cantar;<br/>El Sol de la justicia trae<br/>Alas de sanidad.<br/>',NULL,191574,5);
INSERT INTO stanza VALUES('S587','1','La oración un santo_incienso es<br/>Que surge de_un quebrado corazón<br/>Cuando_el Espíritu lo hace arder,<br/>Y_en las alas de fe asciende_a Dios.<br/>',NULL,191575,1);
INSERT INTO stanza VALUES('S587','2','Perfume de la gracia es la oración,<br/>Es flor de la paciencia, fe y amor;<br/>Dulce, fragante, grato es su olor,<br/>Y en Sus cortes lo ihnala Dios.<br/>',NULL,191576,2);
INSERT INTO stanza VALUES('S587','3','La oración que asciende llega a ser<br/>Lluvias de bendición y un manantial<br/>Que fluye y cubre toda sequedad,<br/>Que del desierto, un vergel hará.<br/>',NULL,191577,3);
INSERT INTO stanza VALUES('S587','4','Es un teléfono la oración,<br/>Hace que lo distante cerca esté,<br/>A nuestro Padre podemos llevar<br/>Cargas y penas para paz tener.<br/>',NULL,191578,4);
INSERT INTO stanza VALUES('S587','5','Como el telégrafo es la oración;<br/>Con ondas, manda pulsos al Señor;<br/>Vuelve, después de hallar Su corazón,<br/>Con la respuesta a nuestra fe y amor.<br/>',NULL,191579,5);
INSERT INTO stanza VALUES('S587','6','Santo conducto es la oración,<br/>Que a las lámparas aceite da;<br/>Cuando oramos, el Espíritu<br/>Nos llena para brillar con Su luz.<br/>',NULL,191580,6);
INSERT INTO stanza VALUES('S587','7','Como la dinamita es la oración,<br/>En cielo y tierra es el mayor poder;<br/>Mueve la mano fuerte del Señor;<br/>Gira las vivas ruedas por doquier.<br/>',NULL,191581,7);
INSERT INTO stanza VALUES('S587','8','¡Enséñanos a orar! ¡Conmuévenos<br/>Hasta que nos motive Tu pasión!<br/>¡Que sea Cristo en nuestro interior,<br/>Orando al Cristo vivo en ascensión!<br/>',NULL,191582,8);
INSERT INTO stanza VALUES('S587','9','¡Enséñanos a orar Tu voluntad,<br/>Hasta que nos motives con Tu plan!<br/>Que sea Dios en nuestra oración,<br/>Dando respuesta al Dios que arriba está.<br/>',NULL,191583,9);
INSERT INTO stanza VALUES('S588','1','Guardo silencio frente_a Ti, Señor,<br/>Y_en lo profundo vengo ante Ti;<br/>No oraré mi propia oración<br/>Mas oraré Tu oración en mí.<br/>',NULL,191584,1);
INSERT INTO stanza VALUES('S588','2','Parece que en el cielo escuchas Tú,<br/>Mas en mi espíritu habitas hoy;<br/>Parece que yo estoy orando á Ti<br/>Mas de Ti mismo sale la oración.<br/>',NULL,191585,2);
INSERT INTO stanza VALUES('S588','3','Cuando mi carga no puedo expresar,<br/>Gime Tu Espíritu en mí, Señor;<br/>Y, sin mi petición verbalizar,<br/>Tú mismo oras desde mi interior.<br/>',NULL,191586,3);
INSERT INTO stanza VALUES('S588','4','Quisiera inhalarte, mi Señor,<br/>Comer, beber de Ti, mi provisión,<br/>Y en una comunión más honda entrar<br/>Para que tengas en mí Tu expresión.<br/>',NULL,191587,4);
INSERT INTO stanza VALUES('S588','5','Brilla Tu luz en esta comunión,<br/>Me limpia Tu preciosa sangre aquí;<br/>No sólo quiero apreciar Tu luz,<br/>Mas expresarte claramente en mí.<br/>',NULL,191588,5);
INSERT INTO stanza VALUES('S588','6','Me unge aquí Tu aceite celestial<br/>Ungiéndome contigo sin cesar,<br/>Mientras yo mengüo, Tú creciendo estás,<br/>Así Tu plena expresión tendrás.<br/>',NULL,191589,6);
INSERT INTO stanza VALUES('S588','7','Abro mi ser, Señor, a Tu fluir,<br/>Este fluir a otros llevaré;<br/>Y en la corriente siempre en comunión,<br/>Señor, por vida yo te expresaré.<br/>',NULL,191590,7);
INSERT INTO stanza VALUES('S589','1','No busques reposo_aún,<br/>Oye a tu Salvador;<br/>Cerca_el enemigo está:<br/>Velad y_orad.<br/>',NULL,191591,1);
INSERT INTO stanza VALUES('S589','2','Principados de maldad,<br/>Escondidos, buscan ver<br/>Que sin protección estás:<br/>Velad y orad.<br/>',NULL,191592,2);
INSERT INTO stanza VALUES('S589','3','La armadura celestial<br/>Viste siempre sin cesar,<br/>Pues te acecha Satanás:<br/>Velad y orad.<br/>',NULL,191593,3);
INSERT INTO stanza VALUES('S589','4','Los que han vencido ya,<br/>Tu sendero marcarán;<br/>Claman todos a una voz:<br/>"Velad y orad".<br/>',NULL,191594,4);
INSERT INTO stanza VALUES('S589','5','Oye ahora a tu Señor,<br/>Obedece en amor;<br/>Su palabra guarda hoy:<br/>Velad y orad.<br/>',NULL,191595,5);
INSERT INTO stanza VALUES('S589','6','Vela cada día más<br/>Dale a ello prioridad;<br/>Ora, ayuda así tendrás:<br/>Velad y orad.<br/>',NULL,191596,6);
INSERT INTO stanza VALUES('S590','1','Enséñame, Señor, a orar;<br/>Mi corazón lo_anhela_en verdad;<br/>Enséñame, Dios, Tu voluntad;<br/>Enséñame, Señor, a orar.<br/>',NULL,191597,1);
INSERT INTO stanza VALUES('S590','chorus','Vivir en Ti, Señor, y Tú_en mí,<br/>Mi ruego es que yo more_así;<br/>Dame_el poder que_abunda sin fin<br/>Ante los hombres y ante Ti.<br/>',NULL,191598,2);
INSERT INTO stanza VALUES('S590','2','¡Dame la fuerza para orar!<br/>Toda la tierra en angustia está;<br/>Almas muriendo en su afán,<br/>¡Dame el poder que viene al orar!<br/>',NULL,191599,3);
INSERT INTO stanza VALUES('S590','3','Mi voluntad puedes renovar,<br/>Y el pecado en mí subyugar;<br/>¡Con Tu poder hoy llena mi ser<br/>Para orar y para hacer!<br/>',NULL,191600,4);
INSERT INTO stanza VALUES('S590','4','Enséñame, Señor, a orar;<br/>Tú, mi modelo diario serás;<br/>Por siempre en Ti yo he de confiar;<br/>Enséñame, Señor, a orar.<br/>',NULL,191601,5);
INSERT INTO stanza VALUES('S591','1','Señor, enseñanos a_orar<br/>Y_al enemigo_echar,<br/>Todo_el poder maligno_atar<br/>Y_a sus presos soltar.<br/>',NULL,191602,1);
INSERT INTO stanza VALUES('S591','2','Enseñanos a orar y estar<br/>Muy firmes al luchar,<br/>La fortaleza derribar,<br/>Venciendo a Satanás.<br/>',NULL,191603,2);
INSERT INTO stanza VALUES('S591','3','Enseñanos la vara a usar<br/>Con oración triunfal,<br/>Y por Tu sangre sacudir<br/>Hoy toda potestad.<br/>',NULL,191604,3);
INSERT INTO stanza VALUES('S591','4','Obrando en oración con fe,<br/>Deseamos aprender<br/>Que la victoria nuestra es,<br/>Tu autoridad también.<br/>',NULL,191605,4);
INSERT INTO stanza VALUES('S592','1','Vengo al Santísimo,<br/>Para tras el velo_estar,<br/>Para_el trono_allí tocar<br/>Y_agua viva rebosar.<br/>',NULL,191606,1);
INSERT INTO stanza VALUES('S592','2','El Santísimo Lugar<br/>Es mi espíritu interior,<br/>Donde habita mi Señor<br/>Con mi espíritu en unión.<br/>',NULL,191607,2);
INSERT INTO stanza VALUES('S592','3','A mi espíritu entraré,<br/>Aquí encuentro a mi Señor;<br/>Qué maravilloso es!<br/>Mora Él en mi interior.<br/>',NULL,191608,3);
INSERT INTO stanza VALUES('S592','4','Cristo en resurrección<br/>Es fragancia celestial;<br/>En mi espíritu, al orar<br/>Cristo en mí se esparcirá.<br/>',NULL,191609,4);
INSERT INTO stanza VALUES('S592','5','Al tocar mi espíritu<br/>Sus riquezas me dará;<br/>Vida, gracia, luz, y amor<br/>Como un manantial saldrán.<br/>',NULL,191610,5);
INSERT INTO stanza VALUES('S592','6','Si le toco en mi interior<br/>Lo podré experimentar,<br/>Por la ley de vida en mí<br/>Y Su dulce unción probar.<br/>',NULL,191611,6);
INSERT INTO stanza VALUES('S592','7','Yo quisiera disfrutar<br/>En mi espíritu interior,<br/>Del maná escondido allí<br/>Con mi amado Salvador.<br/>',NULL,191612,7);
INSERT INTO stanza VALUES('S592','8','Cuando se haga real en mí<br/>La vida en resurrección,<br/>Aceptado yo seré<br/>Como la vara de Aarón.<br/>',NULL,191613,8);
INSERT INTO stanza VALUES('S592','9','Hallo el vivo manantial<br/>De Tu rica gracia aquí;<br/>Fluye como un gran caudal<br/>Esta gracia para mí.<br/>',NULL,191614,9);
INSERT INTO stanza VALUES('S592','10','Al reunirnos para orar<br/>Cada espíritu estará<br/>Liberado para Tu<br/>Servicio sacerdotal.<br/>',NULL,191615,10);
INSERT INTO stanza VALUES('S592','11','El Santísimo Lugar<br/>Es donde se toca a Dios;<br/>Gracia plena emana allí<br/>Desde el trono del Señor.<br/>',NULL,191616,11);
INSERT INTO stanza VALUES('S593','1','Si Su gracia hoy quieres disfrutar,<br/>Entra al Santísimo Lugar;<br/>Si Su gracia hoy quieres disfrutar,<br/>Entra al Santísimo Lugar.<br/>',NULL,191617,1);
INSERT INTO stanza VALUES('S593','chorus','¡Aleluya! ¡Aleluya!<br/>Gracia como un río fluirá;<br/>¡Aleluya! ¡Aleluya!<br/>Gracia como un río fluirá.<br/>',NULL,191618,2);
INSERT INTO stanza VALUES('S593','2','Luz de gloria en mí siempre ha de brillar,<br/>Aquí en el Santísimo Lugar;<br/>Luz de gloria en mí siempre ha de brillar,<br/>Aquí en el santísimo Lugar.<br/>',NULL,191619,3);
INSERT INTO stanza VALUES('S593','chorus','¡Aleluya! ¡Aleluya!<br/>Luz de gloria en mí brillará;<br/>¡Aleluya! ¡Aleluya!<br/>Luz de gloria en mí brillará.<br/>',NULL,191620,4);
INSERT INTO stanza VALUES('S593','3','Si quieres tocar la fuente eternal,<br/>Debes a tu espíritu entrar;<br/>Si quieres tocar la fuente eternal,<br/>Debes a tu espíritu entrar.<br/>',NULL,191621,5);
INSERT INTO stanza VALUES('S593','chorus','¡Aleluya! ¡Aleluya!<br/>Debes a tu espíritu entrar;<br/>¡Aleluya! ¡Aleluya!<br/>Debes a tu espíritu entrar.<br/>',NULL,191622,6);
INSERT INTO stanza VALUES('S594','1','Rasgado_el velo,_abierto está,<br/>La sangre se roció,<br/>Camino vivo_y nuevo hay<br/>Para orar a Dios.<br/>',NULL,191623,1);
INSERT INTO stanza VALUES('S594','2','Hasta el Santísimo Lugar<br/>Nos trae Tu redención,<br/>Tu Espíritu nos unge aquí<br/>Y gracia nos da Dios.<br/>',NULL,191624,2);
INSERT INTO stanza VALUES('S594','3','En nuestro espíritu, al orar<br/>Nos posees Tú, Señor;<br/>Así, como incienso, Tú<br/>Tendrás Tu expresión.<br/>',NULL,191625,3);
INSERT INTO stanza VALUES('S594','4','Tu gracia como un manantial<br/>Viene del trono aquí,<br/>Para llenar nuestra escasez,<br/>¡Qué rico es su fluir!<br/>',NULL,191626,4);
INSERT INTO stanza VALUES('S594','5','No oramos por ningún afán,<br/>Mas por Tu Espíritu;<br/>Pues en casa necesidad<br/>Cuidado brindas Tú.<br/>',NULL,191627,5);
INSERT INTO stanza VALUES('S594','6','Aunque con pruebas y dolor,<br/>No tengo ansiedad;<br/>Echando todo en Ti, tendrá,<br/>Mi espíritu la paz.<br/>',NULL,191628,6);
INSERT INTO stanza VALUES('S594','7','Que enfocado esté, Señor,<br/>Contigo en comunión;<br/>Te ofrezco por Tu Espíritu<br/>Mi incienso y oración.<br/>',NULL,191629,7);
INSERT INTO stanza VALUES('S595','1','Buscamos Tu faz, Señor,<br/>Para_unánimes orar;<br/>Te_esperamos, siendo_aquí<br/>Santo sacerdocio real.<br/>',NULL,191630,1);
INSERT INTO stanza VALUES('S595','chorus','Aquí juntos para_orar,<br/>Lo_alto_y lo mejor buscar,<br/>Nuestro_espíritu tocar<br/>Y Tu_iglesia_edificar.<br/>',NULL,191631,2);
INSERT INTO stanza VALUES('S595','2','Sacerdotes haznos hoy,<br/>Que perciban Tu sentir,<br/>Que_usen sus espíritus<br/>Para_así Tu plan cumplir.<br/>',NULL,191632,3);
INSERT INTO stanza VALUES('S595','3','Al Santísimo Lugar<br/>Venimos para tocar<br/>Tu trono de gracia real<br/>Y en lo interior orar.<br/>',NULL,191633,4);
INSERT INTO stanza VALUES('S595','4','Desde el trono fluirán<br/>Ríos de Tu gracia en mí;<br/>Refresca mi espíritu<br/>La ayuda que hallo en Ti.<br/>',NULL,191634,5);
INSERT INTO stanza VALUES('S595','5','Haz que nuestra oración<br/>Fluya de Tu Espíritu;<br/>Que no exprese nuestro yo,<br/>Sino lo que quieras Tú.<br/>',NULL,191635,6);
INSERT INTO stanza VALUES('S595','6','Aunque es mucho nuestro afán<br/>Por todo lo temporal,<br/>Te pedimos, al orar,<br/>Que seamos Tu canal.<br/>',NULL,191636,7);
INSERT INTO stanza VALUES('S595','7','Nuestra petición hoy es<br/>Que agua viva fluya aquí;<br/>Si la gracia Tú nos das,<br/>Tu obra puede proseguir.<br/>',NULL,191637,8);
INSERT INTO stanza VALUES('S596','1','Tú, Señor, nos has llamado<br/>Al Santísimo Lugar,<br/>Para contemplar Tu rostro<br/>Y Tu gloria shekiná.<br/>',NULL,191638,1);
INSERT INTO stanza VALUES('S596','chorus','Al Santísimo venimos,<br/>Por Tu incienso, al orar;<br/>Sin el velo que separa,<br/>Con confianza entramos ya.<br/>',NULL,191639,2);
INSERT INTO stanza VALUES('S596','2','Al Santísimo legamos,<br/>La entrada ya se abrió;<br/>Un camino nuevo y vivo<br/>El Señor inaguró.<br/>',NULL,191640,3);
INSERT INTO stanza VALUES('S596','3','A Dios hoy nos acercamos;<br/>En Su trono Él está;<br/>Por la cruz y por la sangre<br/>Sólo se podrá llegar.<br/>',NULL,191641,4);
INSERT INTO stanza VALUES('S596','4','A la nueva era entramos,<br/>Con confiado corazón,<br/>Disfrutando el plan eterno,<br/>Sin volvera lo anterior.<br/>',NULL,191642,5);
INSERT INTO stanza VALUES('S596','5','¡Gloria a Ti, Señor, llegamos<br/>Al Santísimo Lugar!<br/>Eres nuestro Dios en vida,<br/>Y Tu pueblo somos ya.<br/>',NULL,191643,6);
INSERT INTO stanza VALUES('S597','1','En el Nombre poderoso<br/>De Jesús en oración,<br/>Derrotando al enemigo,<br/>Hay victoria_y bendición.<br/>',NULL,191644,1);
INSERT INTO stanza VALUES('S597','chorus','¡Nombre fiel! ¡Nombre fiel!<br/>Que nos lleva a vencer;<br/>¡Nombre fiel! ¡Nombre fiel!<br/>Que derrota a Luzbel.<br/>',NULL,191645,2);
INSERT INTO stanza VALUES('S597','2','Cuando el Nombre declaramos,<br/>No resiste Satanás;<br/>¡Oh, Jesús! ¡Jesús precioso!<br/>¡Qué victoria el nombre da!<br/>',NULL,191646,3);
INSERT INTO stanza VALUES('S597','3','Pronto llegará el momento<br/>La victoria se verá,<br/>Cuando el nombre poderoso<br/>En el trono nos pondrá.<br/>',NULL,191647,4);
INSERT INTO stanza VALUES('S598','1','"Pide_en fe", ¡cuán fiel Su nombre!<br/>Lleva al trono tu_oración;<br/>Al confiar, Jesús susurra;<br/>"La_obra ya se consumó".<br/>',NULL,191648,1);
INSERT INTO stanza VALUES('S598','2','"Pide_en fe", pues Dios contesta<br/>Cargas de Su_Espíritu;<br/>Con poder hará Su obra,<br/>Más de lo que piensas tú.<br/>',NULL,191649,2);
INSERT INTO stanza VALUES('S598','3','"Pide_en fe" y con denuedo;<br/>Con fe, firme_has de pedir<br/>Con expectación gozosa,<br/>Su respuesta a recibir.<br/>',NULL,191650,3);
INSERT INTO stanza VALUES('S598','4','"Pide_en fe", tal fe ferviente<br/>Dios desea contestar;<br/>En tu fe Él se deleita<br/>En cada hora y lugar.<br/>',NULL,191651,4);
INSERT INTO stanza VALUES('S599','1','A este monte dile:<br/>"¡Al mar profundo vete!";<br/>Tu corazón no dude<br/>Y tú verás el hecho.<br/>No dudes Su palabra hoy,<br/>¡Al monte manda_en el Señor!<br/>',NULL,191652,1);
INSERT INTO stanza VALUES('S599','2','Reclama tu derecho,<br/>Pues fuiste redimido;<br/>La Trinidad unida<br/>Lo hace verdadero.<br/>Acata Su Palabra fiel,<br/>¡Al monte manda_en el Señor!<br/>',NULL,191653,2);
INSERT INTO stanza VALUES('S599','3','La enfermedad, el ego,<br/>Tristezas y el pecado:<br/>Todo llevó el Amado,<br/>Y tú fuiste librado.<br/>Descansa en Su Palabra hoy,<br/>¡Al monte manda_en el Señor!<br/>',NULL,191654,3);
INSERT INTO stanza VALUES('S599','4','Rodea el fuerte muro,<br/>Orando en silencio,<br/>Y antes que caiga,<br/>Da el grito victorioso,<br/>Firme en la fe se logrará,<br/>¡Al monte manda_en el Señor!<br/>',NULL,191655,4);
INSERT INTO stanza VALUES('S599','5','De hierro son las harras<br/>De bronce son las puertas,<br/>Las los conquistadores<br/>Las vencen con gran fuerza,<br/>Al enemigo hay que ignorar,<br/>¡Al monte manda_en el Señor!<br/>',NULL,191656,5);
INSERT INTO stanza VALUES('S599','6','La fe de Dios reclama,<br/>No dudes ni un momento;<br/>La milagrosa vara<br/>Derriba argumentos,<br/>En Su Palabra firme y fiel<br/>¡Al monte manda_en el Señor!<br/>',NULL,191657,6);
INSERT INTO stanza VALUES('S600','1','Sigue cantando en fe,<br/>Aunque_haya oscuridad;<br/>Alaba_a Dios, y Él tu fe<br/>En vista cambiará.<br/>En vista cambiará.<br/>',NULL,191658,1);
INSERT INTO stanza VALUES('S600','2','Sigue cantando en fe,<br/>Afirma el corazón;<br/>La fe que alaba en noche atróz<br/>//Es la que agrada a Dios.//<br/>',NULL,191659,2);
INSERT INTO stanza VALUES('S600','3','Sigue cantando en fe,<br/>Y Satanás huirá;<br/>Que él no apague tu canción;<br/>//Si alabas, vencerás.//<br/>',NULL,191660,3);
INSERT INTO stanza VALUES('S600','4','Sigue cantando en fe,<br/>Pronto amanecerá;<br/>Saldremos a ver al Señor<br/>//Con cántico eternal.//<br/>',NULL,191661,4);
INSERT INTO stanza VALUES('S601','1','Ora siempre_en un acuerdo:<br/>Con la unción y_en unidad.<br/>Que_el espíritu te guíe,<br/>No el natural pensar.<br/>',NULL,191662,1);
INSERT INTO stanza VALUES('S601','chorus','Ora siempre_en un acuerdo:<br/>Con la unción y_en unidad.<br/>Que_el espíritu te guíe,<br/>No el natural pensar.<br/>',NULL,191663,2);
INSERT INTO stanza VALUES('S601','2','Ora siempre en un acuerdo,<br/>Por la cruz, rechaza el yo,<br/>Al Espíritu tomando<br/>Todo bajo Su control.<br/>',NULL,191664,3);
INSERT INTO stanza VALUES('S601','3','Ora siempre en un acuerdo,<br/>Es la esfera celestial;<br/>Pisoteando principados,<br/>Huye de lo terrenal.<br/>',NULL,191665,4);
INSERT INTO stanza VALUES('S601','4','Ora siempre en un acuerdo,<br/>Hazlo en cordinación;<br/>Sigue del Señor la guía<br/>De Su mente y dirección.<br/>',NULL,191666,5);
INSERT INTO stanza VALUES('S601','5','Ora siempre en un acuerdo,<br/>Vela con tenacidad,<br/>Por Su reino y por Su gloria<br/>Ora y vela en unidad.<br/>',NULL,191667,6);
INSERT INTO stanza VALUES('S601','6','Ora siempre en un acuerdo,<br/>Busca a Dios en unidad,<br/>Y el Espíritu del Cuerpo<br/>Su armonía mantendrá.<br/>',NULL,191668,7);
INSERT INTO stanza VALUES('S602','1','En espíritu oremos,<br/>No_en la mente natural;<br/>Si guardamos tal principio<br/>Su presencia Dios nos da.<br/>',NULL,191669,1);
INSERT INTO stanza VALUES('S602','chorus','En espíritu oremos,<br/>El secreto se nos dio;<br/>Si_en espíritu oramos<br/>Tocaremos al Señor.<br/>',NULL,191670,2);
INSERT INTO stanza VALUES('S602','2','En espíritu oremos,<br/>No en el hombre natural;<br/>Sólo así con Dios tendremos<br/>Comunión espiritual.<br/>',NULL,191671,3);
INSERT INTO stanza VALUES('S602','3','En espíritu oremos<br/>Por lo que le agrada a Dios;<br/>Nuestro espíritu encendido<br/>Estará por el Señor.<br/>',NULL,191672,4);
INSERT INTO stanza VALUES('S602','4','En espíritu oremos,<br/>Y, gimiendo en lo interior,<br/>Por Su Espíritu expresemos<br/>La intención de nuestro Dios.<br/>',NULL,191673,5);
INSERT INTO stanza VALUES('S602','5','En espíritu oremos<br/>¡Qué Santísimo Lugar!<br/>Donde Dios con Sus creyentes<br/>Se entrelaza en unidad.<br/>',NULL,191674,6);
INSERT INTO stanza VALUES('S602','6','En espíritu oremos<br/>Sólo allí se debe orar;<br/>Y orando así, probamos<br/>Del caudal de la Deidad.<br/>',NULL,191675,7);
INSERT INTO stanza VALUES('S603','1','Quiero_ejercitarme<br/>En mi_espíritu;<br/>Poco he orado<br/>Conforme a Tu luz.<br/>Rara vez he visto<br/>Que, al yo orar,<br/>Mi_espíritu ande<br/>Donde_el Tuyo va.<br/>',NULL,191676,1);
INSERT INTO stanza VALUES('S603','2','Mi espíritu ahora<br/>Gime en oración,<br/>No por la memoria<br/>Sino por la unción.<br/>Mi espíritu uso,<br/>No el razonar;<br/>Que me guíe el Tuyo<br/>Cuando quiero orar.<br/>',NULL,191677,2);
INSERT INTO stanza VALUES('S603','3','Mi espíritu ore<br/>Cuando solo esté,<br/>Mas también con otros<br/>Lo ejercitaré.<br/>Oraremos juntos<br/>En espíritu,<br/>Donde así respuesta<br/>A Su Espíritu.<br/>',NULL,191678,3);
INSERT INTO stanza VALUES('S603','4','Al servir con otros,<br/>Hazlo en oración,<br/>No sólo charlando,<br/>Sino en comunión.<br/>Nunca oren juntos<br/>Con banal clamor;<br/>Si no han tenido<br/>Dulce comunión.<br/>',NULL,191679,4);
INSERT INTO stanza VALUES('S603','5','Tu espíritu siempre<br/>Busca ejercitar,<br/>No importando cuántos<br/>Puedan escuchar.<br/>No me influya el sitio<br/>O cualquier reunión,<br/>Mi espíritu ore<br/>Libre de temor.<br/>',NULL,191680,5);
INSERT INTO stanza VALUES('S603','6','Mi espíritu excelso<br/>Abre pasó a Dios;<br/>Mi espíritu fuerte<br/>Sirve en Su labor.<br/>Mi espíritu fluye<br/>Agua viva aquí,<br/>Para que la iglesia<br/>Se edifique así.<br/>',NULL,191681,6);
INSERT INTO stanza VALUES('S604','1','¡Qué misterio, oh Señor!<br/>Hoy Tu_Espíritu está<br/>En el mío, y los dos<br/>Uno son en realidad.<br/>',NULL,191682,1);
INSERT INTO stanza VALUES('S604','2','En mi espíritu ando yo,<br/>Para ser espiritual;<br/>Sirviendo en mi espíritu,<br/>Yo te puedo adorar.<br/>',NULL,191683,2);
INSERT INTO stanza VALUES('S604','3','Toco con mi espíritu,<br/>Tu Palabra en oración,<br/>Bulle así mi espíritu,<br/>Con la fuerza de Tu unción.<br/>',NULL,191684,3);
INSERT INTO stanza VALUES('S604','4','Fuerte haz mi espíritu,<br/>Para a otros avivar;<br/>Libre en mi espíritu,<br/>Puedo a otros animar.<br/>',NULL,191685,4);
INSERT INTO stanza VALUES('S604','5','Cuando hable, oh Señor,<br/>Pon mi espíritu en acción;<br/>Motivado así por él,<br/>Cumpliré con mi función.<br/>',NULL,191686,5);
INSERT INTO stanza VALUES('S604','6','Al actuar mi espíritu<br/>Los de otros se abrirán,<br/>Al mover mi espíritu<br/>Puedo a otros alentar.<br/>',NULL,191687,6);
INSERT INTO stanza VALUES('S604','7','Ten piedad de mí, Señor,<br/>Sopla fuertemente en mí;<br/>Para que mi espíritu<br/>Sea fuerte y fresco en Ti.<br/>',NULL,191688,7);
INSERT INTO stanza VALUES('S605','1','Toca_el trono en oración,<br/>Gracia_allí recibirás;<br/>Con misericordia Dios<br/>Tu_escasez hoy suplirá<br/>',NULL,191689,1);
INSERT INTO stanza VALUES('S605','2','Toca el trono en oración,<br/>Y la gracia encontrarás;<br/>En Tu espíritu a Dios<br/>Cara a cara le verás.<br/>',NULL,191690,2);
INSERT INTO stanza VALUES('S605','3','Toca el trono en oración,<br/>De Su gracia aprenderás;<br/>Tómala en comunión,<br/>Dando gracias sin cesar.<br/>',NULL,191691,3);
INSERT INTO stanza VALUES('S605','4','Toca el trono en oración,<br/>Toca el trono de poder;<br/>En el nombre de Jesús<br/>Haz lo que se debe hacer.<br/>',NULL,191692,4);
INSERT INTO stanza VALUES('S605','5','Toca el trono en oración,<br/>Usa tu viviente fe,<br/>Ejercita autoridad<br/>Para la muerte vencer.<br/>',NULL,191693,5);
INSERT INTO stanza VALUES('S605','6','Toca el trono en oración,<br/>Sacude el poder del mal;<br/>Ora con autoridad,<br/>Hoy con Cristo hay que orar.<br/>',NULL,191694,6);
INSERT INTO stanza VALUES('S606','1','Ora_en comunión con Cristo,<br/>Búscalo_en espíritu;<br/>Pide y_oye_en Su presencia,<br/>Escondidos Él y tú.<br/>',NULL,191695,1);
INSERT INTO stanza VALUES('S606','chorus','Ora_en comunión con Cristo,<br/>Búscalo_en espíritu;<br/>Pide y_oye_en Su presencia,<br/>Escondidos Él y tú.<br/>',NULL,191696,2);
INSERT INTO stanza VALUES('S606','2','Ora en comunión con Cristo,<br/>Abre todo tu interior;<br/>Mira a cara descubierta,<br/>Simple y puro en corazón.<br/>',NULL,191697,3);
INSERT INTO stanza VALUES('S606','3','Ora en comunión con Cristo<br/>Con confianza y solaz;<br/>Y con reverencia aprende,<br/>Al Espíritu tocar.<br/>',NULL,191698,4);
INSERT INTO stanza VALUES('S606','4','Ora en comunión con Cristo,<br/>Sin hablar con pretensión,<br/>Al espíritu igualando<br/>En su sentir interior.<br/>',NULL,191699,5);
INSERT INTO stanza VALUES('S606','5','Ora en comunión con Cristo,<br/>Ponle toda tu atención;<br/>Sus deseos te consuman,<br/>Cede a Él tu corazón.<br/>',NULL,191700,6);
INSERT INTO stanza VALUES('S606','6','Ora en comunión con Cristo,<br/>Y contempla así Su faz;<br/>Saturado en Su belleza,<br/>Brille en ti Su dignidad.<br/>',NULL,191701,7);
INSERT INTO stanza VALUES('S607','1','Expresadlo_en oración,<br/>No a nuestro propio yo;<br/>Que nos muestre el Señor<br/>Su deseo_en lo_interior.<br/>',NULL,191702,1);
INSERT INTO stanza VALUES('S607','2','Expresadlo_en oración;<br/>Su intención hay que exponer;<br/>Nuestra mente hay que acallar<br/>Para Su mente tener.<br/>',NULL,191703,2);
INSERT INTO stanza VALUES('S607','3','Expresadlo_en oración,<br/>Siempre contemplándolo;<br/>Cual espejo, reflejad<br/>Todo Su glorioso ser.<br/>',NULL,191704,3);
INSERT INTO stanza VALUES('S607','4','Expresadlo_en oración;<br/>En nosotros ruegue Él;<br/>Que al Cristo celestial<br/>Ore el Cristo en nuestro ser.<br/>',NULL,191705,4);
INSERT INTO stanza VALUES('S607','5','Expresadlo_en oración;<br/>Nunca oremos en el yo.<br/>Totalmente orando en Él,<br/>Oremos con el Señor.<br/>',NULL,191706,5);
INSERT INTO stanza VALUES('S608','1','Ora para_obrar con Él;<br/>El camino allánale;<br/>Muévele y muévete,<br/>Desde_el centro_al aro ve.<br/>',NULL,191707,1);
INSERT INTO stanza VALUES('S608','2','Ora para_obrar con Él;<br/>Uno sé con Su intención<br/>Hasta realizar Su plan<br/>Y obtener Su bendición.<br/>',NULL,191708,2);
INSERT INTO stanza VALUES('S608','3','Ora para_obrar con Él;<br/>La ambición y el preferir<br/>Renunciemos para hacer<br/>Su propósito cumplir.<br/>',NULL,191709,3);
INSERT INTO stanza VALUES('S608','4','Ora para_obrar con Él;;<br/>El Señor debe iniciar<br/>La labor y todo el plan,<br/>Y en nosotros operar.<br/>',NULL,191710,4);
INSERT INTO stanza VALUES('S608','5','Ora para_obrar con Él;<br/>Hasta la rueda mover;<br/>Orando con el Señor<br/>La iglesia tendrá poder.<br/>',NULL,191711,5);
INSERT INTO stanza VALUES('S609','1','Antes de que te levantes<br/>Y tu día comenzar<br/>Para_hallar lo que te_espera<br/>En tu diaria_actividad,<br/>Aunque_el cielo este sombrío<br/>O el sol irradie luz,<br/>Sea tu_alba_alegre o triste,<br/>Dile todo a Jesús.<br/>',NULL,191712,1);
INSERT INTO stanza VALUES('S609','2','Que tu obra cotidiana<br/>Sea hecha en comunión;<br/>Se disipen tus afanes,<br/>Desahogando tu alma en Dios;<br/>Y si el mundo con encantos<br/>Quiere atar tu espíritu,<br/>Antes de que tú contestes,<br/>Dile todo a Jesús.<br/>',NULL,191713,2);
INSERT INTO stanza VALUES('S609','3','Luego al pasar las horar,<br/>Dios tu senda guiará;<br/>Si tu carga es más ligera,<br/>Tú podrás a otro alzar;<br/>Dando ayuda al cansado,<br/>Y al caído, fortitud,<br/>Mientras haces tu servicio,<br/>Dile todo a Jesús.<br/>',NULL,191714,3);
INSERT INTO stanza VALUES('S609','4','Si al terminar el día,<br/>El cansancio te venció;<br/>Si con tentaciones crueles<br/>Satanás te enfrentó;<br/>Aunque débil o en peligro,<br/>Pide al cielo su virtud;<br/>Salvación y calma vienen<br/>Al decir todo a Jesús.<br/>',NULL,191715,4);
INSERT INTO stanza VALUES('S610','1','¡Oh, qué_amigo nos es Cristo!<br/>¡Nuestras culpas El cargó!<br/>¡Es un privilegio darlo<br/>Todo_a Dios en oración!<br/>¡Oh, qué paz la que perdemos,<br/>Oh, qué pena, qué dolor,<br/>Si nosotros no llevamos<br/>Todo_a Dios en oración!<br/>',NULL,191716,1);
INSERT INTO stanza VALUES('S610','2','Si acosan tentaciones<br/>Y problemas sin cesar,<br/>En lugar de abatirnos,<br/>Todo a Dios hay que llevar.<br/>¿Se hallará tan buen amigo<br/>Que lleve nuestro dolor?<br/>Él conoce tus flaquezas;<br/>Todo llévalo al Señor.<br/>',NULL,191717,2);
INSERT INTO stanza VALUES('S610','3','Si estamos abrumados<br/>Y cargados de ansiedad,<br/>Es Jesús nuestro refugio:<br/>Dile todo al orar.<br/>¿Te desprecian tus amigos?<br/>Cuéntaselo en oración.<br/>protegido en Sus brazos,<br/>Paz tendrá tu corazón.<br/>',NULL,191718,3);
INSERT INTO stanza VALUES('S611','1','"Quema_incienso siempre"<br/>En Su santo_altar;<br/>Tu profundo anhelo<br/>Suba, al orar.<br/>Como el incienso<br/>Al torno de Dios,<br/>Hasta que se cumpla<br/>Lo que Él deseó.<br/>',NULL,191719,1);
INSERT INTO stanza VALUES('S611','2','"Quema incienso siempre"<br/>En Su santo altar;<br/>Oh Señor, Tu fuego<br/>Hay que alimentar,<br/>Hasta que en Tus hijos<br/>Puedas eco hallar,<br/>Y sean ungidos<br/>Para en Ti hablar.<br/>',NULL,191720,2);
INSERT INTO stanza VALUES('S611','3','"Quema_incienso siempre"<br/>Aun cuando_en tu fe<br/>Faltes las palabras<br/>Y abrumado estés;<br/>Nuestro ser, gimiendo<br/>Con Su Espíritu,<br/>Trae de Dios respuesta<br/>A tal actitud.<br/>',NULL,191721,3);
INSERT INTO stanza VALUES('S611','4','"Quema_incienso siempre",<br/>Suba sin cesar,<br/>Hasta que del cielo<br/>Baje el fuego ya,<br/>Y los corazones<br/>Ardan para Dios;<br/>Gloria así seremos<br/>Para el Salvador.<br/>',NULL,191722,4);
INSERT INTO stanza VALUES('S612','1','El sacerdote para Dios<br/>Es santo en su posición:<br/>Tan cerca_a Él, le_ofrece fiel<br/>Incienso de_oración.<br/>',NULL,191723,1);
INSERT INTO stanza VALUES('S612','chorus','Incienso_hay que quemar,<br/>Orando_ante_el Señor;<br/>Las lámparas hay que_encender<br/>Y darle_a Dios loor.<br/>',NULL,191724,2);
INSERT INTO stanza VALUES('S612','2','Allí en el Santo Lugar<br/>No brilla la luz natural;<br/>La lámpara hay que encender<br/>Para incienso quemar.<br/>',NULL,191725,3);
INSERT INTO stanza VALUES('S612','3','La gracia de Dios ensalzad,<br/>Un dulce cántico entonad;<br/>No sólo lámparas prender,<br/>También hay que alabar.<br/>',NULL,191726,4);
INSERT INTO stanza VALUES('S612','4','Incienso siempre ofreceré,<br/>Orando en resurrección;<br/>Y complaciendo así a Dios,<br/>Me gozo en el Señor.<br/>',NULL,191727,5);
INSERT INTO stanza VALUES('S612','5','En Tu Palabra encuentro luz<br/>Como esa lámpara ante Ti;<br/>La luz que me alumbra aquí,<br/>Yo he de transmitir.<br/>',NULL,191728,6);
INSERT INTO stanza VALUES('S612','6','Sus alabanzas cantaré<br/>Como Su sacerdote fiel;<br/>Llenando Él mi corazón,<br/>Su gracia alabaré.<br/>',NULL,191729,7);
INSERT INTO stanza VALUES('S612','7','Ofrezco a Cristo en oración,<br/>En la Palabra busco luz,<br/>Y por Su gracia alabo a Dios,<br/>Fluye el Espíritu.<br/>',NULL,191730,8);
INSERT INTO stanza VALUES('S613','1','Espero_en Ti, Señor, sólo_en Ti;<br/>Que hoy descanse_en Ti;<br/>Que pueda percibir<br/>Tu voluntad en mí;<br/>Espero_en Ti; sólo en Ti.<br/>',NULL,191731,1);
INSERT INTO stanza VALUES('S613','2','Espero en Ti, Señor, sólo en Ti;<br/>Quiero permanecer,<br/>Orando hasta ver<br/>Tu senda esclarecer;<br/>Espero_en Ti; sólo en Ti.<br/>',NULL,191732,2);
INSERT INTO stanza VALUES('S613','3','Espero en Ti, Señor, sólo en Ti;<br/>Mézclate con mi ser<br/>Hasta poder tener<br/>Tu misma imagen fiel;<br/>Espero_en Ti; sólo en Ti.<br/>',NULL,191733,3);
INSERT INTO stanza VALUES('S613','4','Espero en Ti, Señor, sólo en Ti;<br/>Muestra Tu voluntad;<br/>Hazme en Tu senda andar,<br/>Y vida rebosar:<br/>Espero_en Ti; sólo en Ti.<br/>',NULL,191734,4);
INSERT INTO stanza VALUES('S613','5','Espero en Ti, Señor, sólo en Ti;<br/>Que toda mi oración<br/>Sea Tu expresión;<br/>Dame el secreto hoy:<br/>Espero_en Ti; sólo en Ti.<br/>',NULL,191735,5);
INSERT INTO stanza VALUES('S614','1','¡Cálmate, mi_alma,_espera en el Señor!<br/>Se tú_el canal que_exprese Su sentir;<br/>Deja que_Él hable, luego habla tú;<br/>Que Él inicie Su_oración en ti.<br/>',NULL,191736,1);
INSERT INTO stanza VALUES('S614','2','¡Cálmate, mi alma, espera en el Señor!<br/>Niega tu mente y tu voluntad;<br/>Deja que Dios te unja con Su ser;<br/>Que cumpla, por tu oración, Su plan.<br/>',NULL,191737,2);
INSERT INTO stanza VALUES('S614','3','¡Cálmate, mi alma, espera en el Señor!<br/>Calla el llamado a lo terrenal;<br/>Calma tus planes, calma todo afán;<br/>Que Sus demandas pueda en ti lograr.<br/>',NULL,191738,3);
INSERT INTO stanza VALUES('S614','4','¡Cálmate, mi alma, espera en el Señor!<br/>Cede al espíritu tu corazón;<br/>Deja que allí te dé revelación;<br/>Sé obediente a él, sirviendo a Dios.<br/>',NULL,191739,4);
INSERT INTO stanza VALUES('S614','5','¡Cálmate, mi alma, espera en el Señor!<br/>Sigue al Espíritu en Su sentir;<br/>Todo tu ser, movido así por Dios,<br/>Expresará Su oración aquí.<br/>',NULL,191740,5);
INSERT INTO stanza VALUES('S614','6','¡Cálmate, mi alma, espera en el Señor!<br/>Hasta que Él todo pueda poseer;<br/>Hasta que sean uno tú y Dios,<br/>Y confirmada a Su Hijo estés.<br/>',NULL,191741,6);
INSERT INTO stanza VALUES('S614','7','¡Cálmate, mi alma, espera en el Señor!<br/>Hasta que fluya libremente Dios,<br/>Hasta que todo tu hablar y acción,<br/>Cumplan la voluntad de tu Señor.<br/>',NULL,191742,7);
INSERT INTO stanza VALUES('S615','1','Avívame Señor, y logra ya,<br/>Que por el mundo sienta yo pasión;<br/>Avívame a ir, a dar y_orar,<br/>Que Tu bandera otros vean hoy<br/>En tierras donde hay oscuridad<br/>Y_en los desiertos donde cruz no hay.<br/>',NULL,191743,1);
INSERT INTO stanza VALUES('S615','2','Avíva hoy Señor mi corazón,<br/>Que por las almas sienta compasión;<br/>Hasta que Tu palabra me haga orar,<br/>Y me constriñas con todo Tu amor.<br/>De norte a sur, que ardas en mi ser,<br/>De oeste a este, haz Tu fuego arder.<br/>',NULL,191744,2);
INSERT INTO stanza VALUES('S615','3','Avívame a orar aun con dolor,<br/>Hasta llenar de gozo mi oración;<br/>Mi corazón, mi mente y voluntad:<br/>Que todo tuyo sea mi Señor.<br/>Hasta que intensamente aprenda a orar<br/>Y con expectación sepa esperar.<br/>',NULL,191745,3);
INSERT INTO stanza VALUES('S615','4','Avívame, oh, hazme como Tú,<br/>Que, por el fuego intenso de Tu amor,<br/>Tú entregaste a Tu Unigénito<br/>Para morir y ser mi vida hoy.<br/>Avívame para entregarme a Ti;<br/>Alcanza a otros por medio de mí.<br/>',NULL,191746,4);
INSERT INTO stanza VALUES('S615','5','Avívame Señor, pues puedo ver,<br/>Que Tu radiante día cerca está;<br/>Vislumbra el dorado amanecer,<br/>¡Gloriosa iglesia, oh, despierta ya!<br/>¡Oh, haznos ese día anunciar!<br/>Pasó la noche, el Rey pronto vendrá.<br/>',NULL,191747,5);
INSERT INTO stanza VALUES('S616','1','¡Aviva Tu_obra,_oh Dios!<br/>¡Queremos verte hoy!<br/>¡Oh, habla_a todos con poder!<br/>¡Que se_oiga_aquí Tu voz!<br/>',NULL,191748,1);
INSERT INTO stanza VALUES('S616','chorus','¡Aviva Tu_obra, oh Dios!<br/>Postramos nuestro ser;<br/>¡Desciende en gracia, oh Señor!<br/>¡Bendícenos; hoy ven!<br/>',NULL,191749,2);
INSERT INTO stanza VALUES('S616','2','¡Avíva Tu obra, oh Dios!<br/>¡Inspíranos, Señor!<br/>Con fuego del Pentecostés,<br/>Enciende el corazón.<br/>',NULL,191750,3);
INSERT INTO stanza VALUES('S616','3','¡Avíva Tu obra, oh Dios!<br/>¡Tu nombre exalta hoy!<br/>Que arda en cada corazón<br/>La llama de tu amor.<br/>',NULL,191751,4);
INSERT INTO stanza VALUES('S616','4','¡Avíva Tu obra, oh Dios!<br/>¡Bendíganos Tu hablar!<br/>Se oiga Tu santa verdad<br/>En fe viviente y real.<br/>',NULL,191752,5);
INSERT INTO stanza VALUES('S616','5','¡Avíva Tu obra, oh Dios!<br/>Y danos gran valor<br/>Para poder hoy convencer<br/>Al pecador, Señor.<br/>',NULL,191753,6);
INSERT INTO stanza VALUES('S616','6','¡Avíva Tu obra, oh Dios,<br/>Como en Pentecostés!<br/>¡Nos basta, Dios, Tu bendición!<br/>¡La gloria Tuya es!<br/>',NULL,191754,7);
INSERT INTO stanza VALUES('S617','1','¡Avíva Tu obra, oh Dios!<br/>Tu brazo_extiende hoy;<br/>Que Tu presencia real esté<br/>En nuestro corazón.<br/>',NULL,191755,1);
INSERT INTO stanza VALUES('S617','chorus','¡Avíva Tu_obra, oh Dios!<br/>Exhibe Tu poder,<br/>En Tu iglesia como en<br/>Aquel Pentecostés.<br/>',NULL,191756,2);
INSERT INTO stanza VALUES('S617','2','¡Avíva Tu obra, oh Dios!<br/>Termina el estupor;<br/>Inflama el fuego de Tu amor<br/>En cada corazón.<br/>',NULL,191757,3);
INSERT INTO stanza VALUES('S617','3','¡Avíva Tu obra, oh Dios!<br/>La sed despierta, Tú,<br/>Y hambre para Tu verdad<br/>En nuestro espíritu.<br/>',NULL,191758,4);
INSERT INTO stanza VALUES('S617','4','¡Avíva Tu obra, oh Dios!<br/>Que abunde el gozo aquí;<br/>Llenando el corazón de amor,<br/>La escoria quema así.<br/>',NULL,191759,5);
INSERT INTO stanza VALUES('S617','5','¡Avíva Tu obra, oh Dios!<br/>Repite Tu obra hoy;<br/>Tu nombre ensalzado esté<br/>Con gloria y honor.<br/>',NULL,191760,6);
INSERT INTO stanza VALUES('S618','1','Toda_escritura,_aliento es de Dios,<br/>Soplada fue por el Espíritu;<br/>Por hombres santos ella_escrita fue,<br/>Es la herencia de Su plenitud.<br/>',NULL,191761,1);
INSERT INTO stanza VALUES('S618','2','Este aliento al hombre es como luz,<br/>Brillan sus rayos en su corazón;<br/>En las tinieblas, trae revelación<br/>Al hombre en cuanto a su real condición.<br/>',NULL,191762,2);
INSERT INTO stanza VALUES('S618','3','Este aliento, vida al hombre da<br/>Con la naturaleza de su Dios,<br/>Que imparte al muerto regeneración,<br/>Transforma y renueva el corazón.<br/>',NULL,191763,3);
INSERT INTO stanza VALUES('S618','4','Este aliento al hombre enseñará<br/>Conocimiento santo y divinal,<br/>Muestra el propósito eterno de Dios,<br/>Y guía al hombre a Su meta final.<br/>',NULL,191764,4);
INSERT INTO stanza VALUES('S618','5','Este aliento, fuerza al hombre da<br/>Para que él pueda a Dios complacer,<br/>Poder divino le transmitirá<br/>Fuerza al caído y al débil, poder.<br/>',NULL,191765,5);
INSERT INTO stanza VALUES('S618','6','Se debe este aliento respirar<br/>Para que sea Dios nuestra porción;<br/>Ejercitando nuestro espíritu<br/>Lo recibimos con gran bendición.<br/>',NULL,191766,6);
INSERT INTO stanza VALUES('S619','1','Dios nos ha hablado, Dios se reveló;<br/>Su carácter y personas expresó;<br/>Su misterio a los hombres se mostró;<br/>Lo_ilustró_a nosotros; lo manifestó.<br/>',NULL,191767,1);
INSERT INTO stanza VALUES('S619','2','Dios nos ha hablado desde el corazón:<br/>La preeminencia a Su Hijo dio,<br/>Para que se glorifique el Padre en Él,<br/>Hizo a Cristo el centro de la creación.<br/>',NULL,191768,2);
INSERT INTO stanza VALUES('S619','3','Dios nos ha hablado y nos reveló:<br/>Cristo mismo es Dios y hombre a la vez;<br/>Centro y circunferencia de Su plan,<br/>Es el todo en todos; todo lo une Él.<br/>',NULL,191769,3);
INSERT INTO stanza VALUES('S619','4','Dios nos ha hablado; ¡gran misterio es!<br/>Lo que Él desea es Cristo y Su expresión:<br/>Cristo, la Cabeza, a Su plenitud,<br/>Su iglesia, el Cuerpo, Sus riquezas dio.<br/>',NULL,191770,4);
INSERT INTO stanza VALUES('S619','5','Dios nos ha hablado; del cielo mostró<br/>Que el Dios Triuno al hombre se unirá;<br/>El Padre en el Hijo como Espíritu<br/>Vive en el Cuerpo, cumpliendo Su plan.<br/>',NULL,191771,5);
INSERT INTO stanza VALUES('S619','6','Dios nos ha hablado y nos reveló<br/>Su creación tan vasta y cómo Él se humanó,<br/>Su gran redención y plena salvación;<br/>¡Qué toda la tierra le dé adoración!<br/>',NULL,191772,6);
INSERT INTO stanza VALUES('S620','1','Tú, la Palabra viviente Dios,<br/>En la Palabra_escrita_oí Tu voz;<br/>En Ti encuentro_a Dios en plenitud<br/>Y en la_Escritura te revelas Tú.<br/>',NULL,191773,1);
INSERT INTO stanza VALUES('S620','2','Ninguno ha visto a Dios fuera de Ti,<br/>Sin la Escritura no te conocí;<br/>Tú a la humanidad mostraste a Dios<br/>Y la Escritura es Tu revelación.<br/>',NULL,191774,2);
INSERT INTO stanza VALUES('S620','3','Corporificación eres de Dios,<br/>Es la Escritura un cuadro hoy de Ti;<br/>Su viva imagen, Dios por Ti mostró,<br/>Por la Escritura te haces real a mí.<br/>',NULL,191775,3);
INSERT INTO stanza VALUES('S620','4','Eres Espíritu que vida das,<br/>Y en la Palabra, Espíritu y verdad;<br/>Por la Palabra, me impartirás<br/>El mismo Espíritu de realidad.<br/>',NULL,191776,4);
INSERT INTO stanza VALUES('S620','5','Encuentro en Ti con Dios tal comunión,<br/>Y en la Escritura me alimento yo;<br/>La debo estudiar orando a Dios,<br/>Para que Tus riquezas me des hoy.<br/>',NULL,191777,5);
INSERT INTO stanza VALUES('S620','6','Quiero mi espíritu ejercitar,<br/>Y contactarte en vida al estudiar;<br/>Por la Escritura, Tú, Palabra fiel,<br/>Eres maná diario a mi ser.<br/>',NULL,191778,6);
INSERT INTO stanza VALUES('S621','1','Tú la Palabra_eres, Señor,<br/>Y el Espíritu también;<br/>En Él te adoramos hoy,<br/>Y ella te da_a conocer.<br/>',NULL,191779,1);
INSERT INTO stanza VALUES('S621','2','Ya que uno somos Tú y yo<br/>Mi todo eres, oh Señor;<br/>Palabra y Espíritu<br/>Tú eres como mi porción.<br/>',NULL,191780,2);
INSERT INTO stanza VALUES('S621','3','Si no fueras Palabra Tú,<br/>¿Yo te podría conocer?<br/>Y sin ser el Espíritu,<br/>¿Podría yo contacto hacer?<br/>',NULL,191781,3);
INSERT INTO stanza VALUES('S621','4','En la Palabra puedo ver<br/>Tu ser, te puedo conocer;<br/>Es Tu sustancia Espíritu,<br/>Para tocar Tu mismo ser.<br/>',NULL,191782,4);
INSERT INTO stanza VALUES('S621','5','Mi vida y senda eres Tú,<br/>Mi alimento, fuerza y luz;<br/>Tú, la Palabra, te haces real<br/>A mí como el Espíritu.<br/>',NULL,191783,5);
INSERT INTO stanza VALUES('S621','6','Es Tu Palabra Tu expresión,<br/>Tu Espíritu mora en mi seŕ;<br/>Tu Palabra en mi espíritu,<br/>Espíritu y vida es.<br/>',NULL,191784,6);
INSERT INTO stanza VALUES('S621','7','Para Tu Palabra entender<br/>Debo Tu Espíritu tocar;<br/>No con la mente he de captar,<br/>Sino en mi espíritu al orar.<br/>',NULL,191785,7);
INSERT INTO stanza VALUES('S621','8','Tu preciosa Palabra es<br/>El gozo de mi corazón;<br/>Mi espíritu en el Tuyo da<br/>Alabanzas en comunión.<br/>',NULL,191786,8);
INSERT INTO stanza VALUES('S622','1','Granero Tu Palabra es,<br/>Lleno de provisión,<br/>Do_el buscador puede_encontrar<br/>Tesoros de valor.<br/>Como profunda mina es<br/>Con joyas de_esplendor,<br/>Que_ocultas en el fondo_están<br/>Para el buen buscador.<br/>',NULL,191787,1);
INSERT INTO stanza VALUES('S622','2','Cual astros Tu Palabra es<br/>Con rayos que, al brillar,<br/>Al peregrino guiarán;<br/>Su senda alumbrarán.<br/>Cual armería ella es,<br/>Do el soldado podrá<br/>Sus armas reparar y hallar<br/>Poder para pelear.<br/>',NULL,191788,2);
INSERT INTO stanza VALUES('S622','3','Más quiero Tu Palabra amar,<br/>Y su mina excavar.<br/>Que saque sus riquezas yo,<br/>Al ver su luz brillar.<br/>Mi armadura hallo aquí;<br/>Mi espada ella es;<br/>Aprenderé a combatir<br/>La guerra de mi Rey.<br/>',NULL,191789,3);
INSERT INTO stanza VALUES('S622','4','Palabra del viviente Dios;<br/>De Su Hijo, pactor es;<br/>Sin ella, ¿cómo aquí andar,<br/>O a Cristo y Dios ganar?<br/>Señor, Tu celestial verdad<br/>Queremos entender,<br/>Y como simples niños ser<br/>Para de ella aprender.<br/>',NULL,191790,4);
INSERT INTO stanza VALUES('S623','1','Hoy parte_el pan, Señor,<br/>Para mi bien,<br/>Como partiste_el pan<br/>El día_aquel.<br/>Tras la Escritura yo<br/>Te busco_a Ti,<br/>Eres el Pan de Vida<br/>Para mí.<br/>',NULL,191791,1);
INSERT INTO stanza VALUES('S623','2','El Pan de vida a mí,<br/>Eres, Señor,<br/>Santa Palabra que<br/>Me salva hoy.<br/>Nútreme para que<br/>Pueda vivir<br/>Pon Tu verdad, Señor,<br/>Dentro de mí.<br/>',NULL,191792,2);
INSERT INTO stanza VALUES('S623','3','Manda Tu Espíritu<br/>Ahora_a mí,<br/>Para que pueda ver<br/>Aún más de Ti.<br/>Lo que escondido está<br/>De Tu amor<br/>En Tu Palabra quiero<br/>Ver, Señor.<br/>',NULL,191793,3);
INSERT INTO stanza VALUES('S623','4','Bendice Tu verdad<br/>Como aquel pan<br/>Que Tú partiste un día<br/>Junto al mar.<br/>Mis grillos se caerán,<br/>Mi esclavitud,<br/>Y así serás, Señor,<br/>Mi todo, Tú.<br/>',NULL,191794,4);
INSERT INTO stanza VALUES('S624','1','Abre mis ojos para ver<br/>Destellos de Tu gran verdad;<br/>Pon en mis manos la llave que<br/>Ha de ponerme en libertad.<br/>',NULL,191795,1);
INSERT INTO stanza VALUES('S624','chorus','Tranquilo,_espero_en Ti, mi Dios;<br/>Tu voluntad revela hoy;<br/>Que a mis ojos les dé luz<br/>Tu_Espíritu.<br/>',NULL,191796,2);
INSERT INTO stanza VALUES('S624','2','Abre mi oído a Tu hablar,<br/>Para escuchar con claridad,<br/>Y, mientras oigo de Tu verdad,<br/>Todo lo falso se irá.<br/>',NULL,191797,3);
INSERT INTO stanza VALUES('S624','3','Abre mi boca para hablar,<br/>Quiero Tu gracia anunciar;<br/>Mi corazón he de preparar<br/>Para Tu amor hoy proclamar.<br/>',NULL,191798,4);
INSERT INTO stanza VALUES('S624','4','Abre mi mente al leer<br/>De Tu amor, Tu hablar y hacer;<br/>Eres mi Guía, ¿a qué temeré?<br/>Entre Tu luz hoy en mi ser.<br/>',NULL,191799,5);
INSERT INTO stanza VALUES('S625','1','En quietud espero;<br/>¡Háblame, Señor!<br/>Acallo mi alma<br/>Con expectación.<br/>',NULL,191800,1);
INSERT INTO stanza VALUES('S625','2','Amo mío, habla,<br/>Quieta mi alma está;<br/>Muéstrame Tu rostro,<br/>Tu poder real.<br/>',NULL,191801,2);
INSERT INTO stanza VALUES('S625','3','Tus dulces  palabras,<br/>Vida son, sin par;<br/>Vivo pan del cielo,<br/>Pan espiritual.<br/>',NULL,191802,3);
INSERT INTO stanza VALUES('S625','4','Todo a Ti lo cedo,<br/>Mío ya no soy;<br/>Dulce es esta entrega;<br/>Tuyo soy, Señor.<br/>',NULL,191803,4);
INSERT INTO stanza VALUES('S625','5','Hoy Tu siervo oye,<br/>Háblame, Señor;<br/>Espera mi alma<br/>Tu animante voz.<br/>',NULL,191804,5);
INSERT INTO stanza VALUES('S625','6','Muéstrame la gloria<br/>De Tu voluntad;<br/>Haz lo que te agrada<br/>En Tu hijo ya.<br/>',NULL,191805,6);
INSERT INTO stanza VALUES('S625','7','Hazme hoy Tu huerto<br/>Con Tu aroma aquí;<br/>Dame Tu presencia,<br/>Vida haz surgir.<br/>',NULL,191806,7);
INSERT INTO stanza VALUES('S626','1','Mi corazón tiene hambre, Señor;<br/>Vengo a Ti a buscar provisión;<br/>Te necesito, no hay otro_igual,<br/>Hambre y sed Tú las puedes saciar.<br/>',NULL,191807,1);
INSERT INTO stanza VALUES('S626','chorus','Nútreme Cristo, dame a beber,<br/>Sacia mi hambre, toda mi sed;<br/>Gozo me das, fortaleza también;<br/>Sacia mi hambre, toda mi sed.<br/>',NULL,191808,2);
INSERT INTO stanza VALUES('S626','2','Agua de vida y comida eres Tú,<br/>Tú me revives, levantas mi ser;<br/>Deseo comer y beber más de Ti,<br/>De Ti gozar al orar y leer.<br/>',NULL,191809,3);
INSERT INTO stanza VALUES('S626','3','Eres la viva Palabra de Dios,<br/>Como Espíritu vida me das;<br/>Como Espíritu mi agua eres Tú,<br/>Y en la Palabra, Tú eres mi pan.<br/>',NULL,191810,4);
INSERT INTO stanza VALUES('S626','4','Desde los cielos bajaste, Señor,<br/>Para ser mi alimento eternal;<br/>Fuiste herido y el agua brotó,<br/>Para abrevarme como un manantial.<br/>',NULL,191811,5);
INSERT INTO stanza VALUES('S626','5','En la Palabra me nutro de Ti;<br/>Eres Espíritu y vida a mí;<br/>Como Espíritu vives en mí,<br/>En mi espíritu bebo de Ti.<br/>',NULL,191812,6);
INSERT INTO stanza VALUES('S626','6','En Tu Palabra te disfruto hoy,<br/>Hasta que el hambre termine_en mi ser<br/>En mi espíritu me vuelvo a Ti,<br/>Para beber y saciar toda sed.<br/>',NULL,191813,7);
INSERT INTO stanza VALUES('S626','7','Como y bebo de Ti, mi Señor,<br/>Como leyendo y bebo al orar;<br/>Orar-leer es beber y comer,<br/>Mi vivir eres al leer-orar.<br/>',NULL,191814,8);
INSERT INTO stanza VALUES('S626','8','Oh, que festeje en Ti, mi Señor,<br/>Por Tu Palabra y_Espíritu hoy;<br/>Sé para mí esa fiesta de_amor,<br/>Que el hombre nunca jamás disfrutó.<br/>',NULL,191815,9);
INSERT INTO stanza VALUES('S627','1','Vengo a Ti, Señor,<br/>De Ti yo tengo sed;<br/>Beber de Ti, comer de Ti,<br/>Es mi mayor placer.<br/>',NULL,191816,1);
INSERT INTO stanza VALUES('S627','2','Clama mi corazón<br/>Sólo mirar Tu faz;<br/>Beber de Ti anhelo yo,<br/>Hasta mi sed saciar.<br/>',NULL,191817,2);
INSERT INTO stanza VALUES('S627','3','Desea mi corazón<br/>Ver Tu gloriosa faz;<br/>Yo quiero así permanecer,<br/>Fiel, contemplándola.<br/>',NULL,191818,3);
INSERT INTO stanza VALUES('S627','4','En esta comunión,<br/>Eres la gracia en mí;<br/>De regocijo llenó estoy,<br/>Y descansando en Ti.<br/>',NULL,191819,4);
INSERT INTO stanza VALUES('S627','5','Aquí me quedaré<br/>Buscando más de Ti,<br/>En la Palabra y oración,<br/>Hasta el fluir sentir.<br/>',NULL,191820,5);
INSERT INTO stanza VALUES('S628','1','Al trono de Tu gracia hoy<br/>Hambriento, vengo a comer;<br/>Tu gracia quiero recibir;<br/>En esta hora_ayúdame.<br/>',NULL,191821,1);
INSERT INTO stanza VALUES('S628','2','Mirando Tu radiante faz<br/>Luz brilla en mi corazón;<br/>Tus rayos sanan con poder<br/>Mi flojedad y todo error.<br/>',NULL,191822,2);
INSERT INTO stanza VALUES('S628','3','Aquí descubres con Tu luz,<br/>Mi verdadera condición;<br/>Aquí Tu sangre eficaz<br/>Limpia todo pecado hoy.<br/>',NULL,191823,3);
INSERT INTO stanza VALUES('S628','4','Tu Espíritu me_unge aquí,<br/>Tu misma_esencia Él me da,<br/>Así te puedo disfrutar<br/>Y conocer Tu voluntad.<br/>',NULL,191824,4);
INSERT INTO stanza VALUES('S628','5','Trae Tu Palabra luz a mí,<br/>Es una lámpara en mi ser;<br/>Tu Espíritu su aceite es<br/>Para que resplandezca bien.<br/>',NULL,191825,5);
INSERT INTO stanza VALUES('S628','6','Como los sacerdotes yo<br/>Hoy persevero en oración;<br/>Tu Espíritu, que_incienso es,<br/>Se mezcla con mi oración.<br/>',NULL,191826,6);
INSERT INTO stanza VALUES('S628','7','Con Tu Palabra rica fiel<br/>Comida y luz me suplirás;<br/>Si como y leo de ella yo,<br/>Comida y luz me saciarán.<br/>',NULL,191827,7);
INSERT INTO stanza VALUES('S628','8','El agua viva eres Tú<br/>Que puede siempre avivar;<br/>Bebiendo y orando yo,<br/>Los ríos vivos brotarán.<br/>',NULL,191828,8);
INSERT INTO stanza VALUES('S628','9','Incienso eres para Dios,<br/>Y la completa aceptación;<br/>Orar yo quiero más y más<br/>Para ofrecer un grato olor.<br/>',NULL,191829,9);
INSERT INTO stanza VALUES('S628','10','Tu luz me alumbra al leer,<br/>Mi sed se apaga al orar,<br/>Me suples con Tu mismo ser,<br/>Así me puedes Tú usar.<br/>',NULL,191830,10);
INSERT INTO stanza VALUES('S628','11','Anhelo yo tal comunión,<br/>Satúrame y rebosaré;<br/>Por la Palabra y oración<br/>Mezclado a Ti yo estaré.<br/>',NULL,191831,11);
INSERT INTO stanza VALUES('S629','1','"No sólo de pan vivirá<br/>El hombre, sino de toda<br/>Palabra que sale de Dios",<br/>Comámoslas, pues vida dan.<br/>',NULL,191832,1);
INSERT INTO stanza VALUES('S629','2','No sólo un cuerpo es nuestro ser,<br/>Mas cuerpo, alma, espíritu;<br/>Podemos contactar a Dios<br/>Con nuestro interno espíritu.<br/>',NULL,191833,2);
INSERT INTO stanza VALUES('S629','3','Todo_alimentó al cuerpo es<br/>De_una vital necesidad;<br/>Y Tu Palabra así también<br/>Nutre el espíritu en verdad.<br/>',NULL,191834,3);
INSERT INTO stanza VALUES('S629','4','Tú eres el Espíritu<br/>Y la Palabra_es Tu expresión;<br/>Así como Espíritu<br/>Hay que tomarte en lo interior.<br/>',NULL,191835,4);
INSERT INTO stanza VALUES('S629','5','No basta sólo el leer<br/>Y la Palabra entender,<br/>Mas recibirla en lo_interior,<br/>En nuestro espíritu también.<br/>',NULL,191836,5);
INSERT INTO stanza VALUES('S629','6','Hoy Tu Palabra hay que comer<br/>Por el espíritu al orar,<br/>Y con la mente_en comunión<br/>Nuestro espíritu ejercitar.<br/>',NULL,191837,6);
INSERT INTO stanza VALUES('S629','7','Tu Palabra_en la mente es<br/>Conocimiento, nada más;<br/>Mas  si entra a nuestro espíritu<br/>Vida y espíritu será.<br/>',NULL,191838,7);
INSERT INTO stanza VALUES('S629','8','Sólo por el espíritu<br/>Podemos contactarte a Ti,<br/>Y la Palabra digerir<br/>Nutriéndonos en ella así.<br/>',NULL,191839,8);
INSERT INTO stanza VALUES('S629','9','Enséñanos a ejercitar<br/>Nuestro espíritu, Señor;<br/>En la Palabra al leer<br/>Para ganar su nutrición.<br/>',NULL,191840,9);
INSERT INTO stanza VALUES('S630','1','Hoy Cristo es el Espíritu<br/>Y la Palabra de verdad;<br/>En las palabras que_habla Él<br/>Su_Espíritu y vida da.<br/>',NULL,191841,1);
INSERT INTO stanza VALUES('S630','2','Por fuera la Palabra está;<br/>Por dentro, el Espíritu;<br/>Por estos dones del Señor<br/>Podemos disfrutar a Dios.<br/>',NULL,191842,2);
INSERT INTO stanza VALUES('S630','3','La Palabra es la expresión,<br/>Su Espíritu, la realidad;<br/>Dos lados son de un mismo ser<br/>Que no se deben separar.<br/>',NULL,191843,3);
INSERT INTO stanza VALUES('S630','4','Cuando el Espíritu trae luz<br/>A la Palabra, vida da,<br/>Pero sin el Espíritu,<br/>Es sólo estímulo mental.<br/>',NULL,191844,4);
INSERT INTO stanza VALUES('S630','5','Tocando en el espíritu<br/>Hoy Tu Palabra eficaz,<br/>Palabras del Espíritu<br/>A otros hemos de hablar.<br/>',NULL,191845,5);
INSERT INTO stanza VALUES('S630','6','Debemos hoy ejercitar<br/>Nuestro espíritu interior,<br/>Para la Palabra tocar<br/>Y el Espíritu liberar.<br/>',NULL,191846,6);
INSERT INTO stanza VALUES('S630','7','Que Tu Palabra sea en mí<br/>Vida y Espíritu, Señor,<br/>Y que Tu Espíritu en mi ser<br/>Sea Tu Palabra en mi expresión.<br/>',NULL,191847,7);
INSERT INTO stanza VALUES('S631','1','No se debe la Palabra<br/>Solo_en letras recibir,<br/>Sino como_aquella vida<br/>Que Dios quiere impartir;<br/>No tan sólo_el pensamiento<br/>Del Señor o Su instrucción,<br/>Sino Cristo como vida<br/>Y_experiencia interior.<br/>',NULL,191848,1);
INSERT INTO stanza VALUES('S631','2','Es conocimiento vano<br/>Si la letra sólo ves;<br/>Mas, si el espíritu usamos,<br/>Esto es vida a nuestro ser.<br/>El conocimiento en letras<br/>Siempre a muerte llevará;<br/>Si en espíritu leemos,<br/>Vivo aliento nos dará.<br/>',NULL,191849,2);
INSERT INTO stanza VALUES('S631','3','Sin ver Cristo en la Palabra,<br/>La lectura vana es;<br/>Mas si a Cristo toco en ella,<br/>Su vida podré obtener.<br/>Si leemos sin tocarlo,<br/>Es estímulo mental;<br/>Si, leyendo, lo tocamos,<br/>Él Su vida nos dará.<br/>',NULL,191850,3);
INSERT INTO stanza VALUES('S631','4','El conocimiento en letras,<br/>A la vida hay que cambiar,<br/>Y la comprensión se debe<br/>En espíritu formar.<br/>El conocimiento escrito<br/>Debe en vida resultar;<br/>La Escritura así se puede<br/>En espíritu apreciar.<br/>',NULL,191851,4);
INSERT INTO stanza VALUES('S631','5','Si tocamos la palabra<br/>Por conocimiento hoy,<br/>Caeremos como Eva,<br/>A quien Satanás tentó.<br/>Mas tomar las Escrituras<br/>Como nuestra vida hoy,<br/>Es comer del árbol vivo<br/>En espíritu con Dios.<br/>',NULL,191852,5);
INSERT INTO stanza VALUES('S632','1','No limitamos la verdad<br/>Que nos ha dado Dios<br/>A nuestra mente o noción<br/>Que incompletas son.<br/>Y hoy en nuestro corazón<br/>Una_esperanza hay:<br/>En Su Palabra,_Él nos dará<br/>Más luz y más verdad.<br/>',NULL,191853,1);
INSERT INTO stanza VALUES('S632','2','Oh, ¿quién se atreve a limitar<br/>Oráculos de Dios<br/>Que a toda lengua y nación<br/>Por siempre se nos dio?<br/>¡Qué mucho hay por descubrir<br/>Del universo y mar!<br/>En Su Palabra, Él nos dará<br/>Más luz y más verdad.<br/>',NULL,191854,2);
INSERT INTO stanza VALUES('S632','3','A oscuras anduvieron los<br/>Pioneros de la fe;<br/>Fue eso el alba, mas la luz<br/>Aumenta cada vez.<br/>Hoy nuestro Sol más crecerá,<br/>Sus rayos brillarán:<br/>En Su Palabra, Él nos dará<br/>Más luz y más verdad.<br/>',NULL,191855,3);
INSERT INTO stanza VALUES('S632','4','Atrás los valles quedan ya,<br/>Hoy ascendemos más,<br/>Y en las alturas vemos bien<br/>Lo que pasado está.<br/>¡Subimos más! ¡Sí, escuchad<br/>El canto celestial!<br/>En Su Palabra, Él nos dará<br/>Más luz y más verdad.<br/>',NULL,191856,4);
INSERT INTO stanza VALUES('S632','5','Oh, Padre, Hijo, Espíritu,<br/>Aumento danos hoy;<br/>Agranda nuestro corazón<br/>Para entender Tu amor;<br/>Y llévanos a conocer,<br/>Con Tu poder sin par,<br/>Que en Tu Palabra nos darás<br/>Más luz y más verdad.<br/>',NULL,191857,5);
INSERT INTO stanza VALUES('S633','1','Si tú del mundo_anhelas escapar,<br/>Di_a la Palabra:_¡Amén!<br/>¿Quieres vivir en toda realidad?<br/>Di_a la Palabra:_¡Amén!<br/>',NULL,191858,1);
INSERT INTO stanza VALUES('S633','chorus','Di_a la Palabra:_¡Amén!<br/>Di_a la Palabra:_¡Amén!<br/>Al recibirla y al creerla,<br/>Di_a la Palabra:_¡Amén!<br/>',NULL,191859,2);
INSERT INTO stanza VALUES('S633','2','Si del pecado quieres libertad,<br/>Di_a la Palabra:_¡Amén!<br/>Dios quiere hoy tu mente renovar;<br/>Di_a la Palabra:_¡Amén!<br/>',NULL,191860,3);
INSERT INTO stanza VALUES('S633','chorus','Di_a la Palabra:_¡Amén!<br/>Di_a la Palabra:_¡Amén!<br/>Ella es viva, nos vivifica;<br/>Di_a la Palabra:_¡Amén!<br/>',NULL,191861,4);
INSERT INTO stanza VALUES('S633','3','Cristo es nuestra tierra de Canaán;<br/>Di_a la Palabra:_¡Amén!<br/>No te endurezcas, si quieres entrar;<br/>Di_a la Palabra:_¡Amén!<br/>',NULL,191862,5);
INSERT INTO stanza VALUES('S633','chorus','Di_a la Palabra:_¡Amén!<br/>Di_a la Palabra:_¡Amén!<br/>Por Su palabra, Dios nos discierne;<br/>Di_a la Palabra:_¡Amén!<br/>',NULL,191863,6);
INSERT INTO stanza VALUES('S633','4','Cristo ya viene, pronto llegará;<br/>Di_a la Palabra:_¡Amén!<br/>Si hoy viniese, ¿listo estarás?<br/>Di_a la Palabra:_¡Amén!<br/>',NULL,191864,7);
INSERT INTO stanza VALUES('S633','chorus','Di_a la Palabra:_¡Amén!<br/>Di_a la Palabra:_¡Amén!<br/>Por Su Palabra, Dios nos prepara;<br/>Di_a la Palabra:_¡Amén!<br/>',NULL,191865,8);
INSERT INTO stanza VALUES('S634','1','¡Cuán glorioso_es el cambio forjado en mi ser,<br/>Diciendo_a Su Palabra: "Amén"!<br/>Cristo entra_al instante con Su gran poder,<br/>Diciendo_a Su Palabra: "Amén".<br/>',NULL,191866,1);
INSERT INTO stanza VALUES('S634','chorus','Diciendo_a Su Palabra: "Amén".<br/>Diciendo_a Su Palabra: "Amén".<br/>Hoy transforma_el Señor todo mi corazón,<br/>Diciendo_a Su Palabra: "Amén".<br/>',NULL,191867,2);
INSERT INTO stanza VALUES('S634','2','Lo que no pude yo, Dios lo puede hacer,<br/>Diciendo_a Su Palabra: "Amén".<br/>Y el cambio es tan real, todos lo pueden ver;<br/>Diciendo_a Su Palabra: "Amén".<br/>',NULL,191868,3);
INSERT INTO stanza VALUES('S634','3','He cesado el vagar y mi errante andar,<br/>Diciendo_a Su Palabra: "Amén".<br/>Y mis viejas costumbres perdiéndose van,<br/>Diciendo_a Su Palabra: "Amén".<br/>',NULL,191869,4);
INSERT INTO stanza VALUES('S634','4','El secreto de fe en el Señor puedo ver<br/>Diciendo_a Su Palabra: "Amén".<br/>Lo más real y precioso de todo es Él,<br/>Diciendo_a Su Palabra: "Amén".<br/>',NULL,191870,5);
INSERT INTO stanza VALUES('S634','5','Hoy por todos los santos abunda mi amor,<br/>Diciendo_a Su Palabra: "Amén".<br/>Y más compenetrado con ellos estoy,<br/>Diciendo_a Su Palabra: "Amén".<br/>',NULL,191871,6);
INSERT INTO stanza VALUES('S634','6','Crece en mí la esperanza que vuelva el Señor,<br/>Diciendo_a Su Palabra: "Amén".<br/>Listo estoy para ver a mi buen Salvador,<br/>Diciendo_a Su Palabra: "Amén".<br/>',NULL,191872,7);
INSERT INTO stanza VALUES('S634','chorus','Señor, a Tu Palabra: "Amén".<br/>Señor, a Tu Palabra: "Amén".<br/>¡Tú vendrás otra vez y yo digo: "Amén"!<br/>Señor, a Tu Palabra: "Amén".<br/>',NULL,191873,8);
INSERT INTO stanza VALUES('S635','1','Cristo,_el misterio es de Dios;<br/>Dios invisible siempre fue,<br/>Su_imagen nunca el hombre vio,<br/>Mas Cristo_el Hijo lo mostró.<br/>',NULL,191874,1);
INSERT INTO stanza VALUES('S635','2','Cristo es la explicación de Dios,<br/>Es Su Palabra eternal;<br/>Es Su corporificación,<br/>Su misma imagen en verdad.<br/>',NULL,191875,2);
INSERT INTO stanza VALUES('S635','3','Imagen del oculto Dios<br/>Con Su glorioso resplandor;<br/>Morando en Él Su plenitud,<br/>Su testimonio y expresión.<br/>',NULL,191876,3);
INSERT INTO stanza VALUES('S635','4','La iglesia, el misterio es<br/>Del Cristo que hoy no se ve;<br/>Aunque escondido Él está,<br/>La iglesia lo da a conocer.<br/>',NULL,191877,4);
INSERT INTO stanza VALUES('S635','5','La iglesia expresa a Cristo aquí,<br/>En ella está Su habitación;<br/>El hombre así lo puede ver,<br/>Pues ella es Su duplicación.<br/>',NULL,191878,5);
INSERT INTO stanza VALUES('S635','6','La iglesia es Su imagen fiel,<br/>Es Su aumento y extensión;<br/>Cabeza de ella Cristo es,<br/>Y ella el Cuerpo para Él.<br/>',NULL,191879,6);
INSERT INTO stanza VALUES('S635','7','Ya que en el Hijo el Padre está,<br/>Y Espíritu el Hijo es,<br/>La iglesia tiene al Triuno Dios<br/>Como Espíritu en su ser.<br/>',NULL,191880,7);
INSERT INTO stanza VALUES('S636','1','Como_el cuerpo nuestra vida<br/>Expresando_está,<br/>Por la_iglesia puede Cristo<br/>Su vida_expresar.<br/>',NULL,191881,1);
INSERT INTO stanza VALUES('S636','2','Como Eva fue sacada<br/>Del primer Adán,<br/>El aumento hoy de Cristo<br/>En la iglesia está.<br/>',NULL,191882,2);
INSERT INTO stanza VALUES('S636','3','Como al enterrar un grano,<br/>Muchos más saldrán,<br/>Y los granos bien molidos<br/>Formarán un pan;<br/>',NULL,191883,3);
INSERT INTO stanza VALUES('S636','4','Es la iglesia para Cristo<br/>Su duplicación;<br/>Y expresa como el Cuerpo<br/>La gloria de Dios.<br/>',NULL,191884,4);
INSERT INTO stanza VALUES('S636','5','Por los pámpanos obtiene<br/>La vid su extensión,<br/>Permanecen y dan fruto<br/>Para su expresión.<br/>',NULL,191885,5);
INSERT INTO stanza VALUES('S636','6','Son los miembros de la iglesia<br/>La viva expansión<br/>Del Señor, y a Él unidos<br/>Su amplificación.<br/>',NULL,191886,6);
INSERT INTO stanza VALUES('S636','7','Para Cristo es la iglesia<br/>Su continuación,<br/>Plenitud, agrandamiento,<br/>Y Su expresión.<br/>',NULL,191887,7);
INSERT INTO stanza VALUES('S636','8','Dios en Cristo por la iglesia<br/>Gloria obtendrá<br/>En Sus muchos redimidos<br/>Por la eternidad.<br/>',NULL,191888,8);
INSERT INTO stanza VALUES('S636','9','Gran misterio es la iglesia<br/>Con Cristo_en unión:<br/>Dios mezclado con los hombres<br/>Para Su expresión.<br/>',NULL,191889,9);
INSERT INTO stanza VALUES('S637','1','Por las riquezas del Señor<br/>Su plenitud podemos ser,<br/>Al disfrutarlo_en comunión,<br/>Su testimonio se_ha de ver.<br/>',NULL,191890,1);
INSERT INTO stanza VALUES('S637','2','Con Sus riquezas el Señor<br/>Su mismo ser nos traerá,<br/>Haciéndonos Su plenitud<br/>Su Cuerpo así Él logrará.<br/>',NULL,191891,2);
INSERT INTO stanza VALUES('S637','3','Por las riquezas de Canaán<br/>El templo al fin se levantó;<br/>Tipificando a Cristo están<br/>Y a la iglesia, Su expresión.<br/>',NULL,191892,3);
INSERT INTO stanza VALUES('S637','4','Como fue Eva para Adán<br/>La iglesia para Cristo es,<br/>La plenitud viviente de_Él,<br/>Que por Su vida vino a ser.<br/>',NULL,191893,4);
INSERT INTO stanza VALUES('S637','5','En la iglesia Cristo es<br/>La rica vida en lo interior;<br/>La_iglesia es Su expresión<br/>Y plenitud en lo exterior.<br/>',NULL,191894,5);
INSERT INTO stanza VALUES('S638','1','La iglesia para Cristo es<br/>Su vaso_y manifestación;<br/>A Tal como_el cuerpo humano_en sí<br/>Su vida_interna expresa hoy.<br/>',NULL,191895,1);
INSERT INTO stanza VALUES('S638','2','Tal como el templó al Arca dio<br/>Reposo y ubicación;<br/>Así la iglesia a Cristo es<br/>Descanso y habitación.<br/>',NULL,191896,2);
INSERT INTO stanza VALUES('S638','3','Cristo, el misterio de Dios,<br/>Lo explica y lo expresa a Él,<br/>Así la iglesia a Cristo es<br/>Misterio y manifestación.<br/>',NULL,191897,3);
INSERT INTO stanza VALUES('S638','4','Los miembros de la iglesia son<br/>De barro en primer lugar;<br/>Mas Dios, por la transformación,<br/>Bien transparentes los hará.<br/>',NULL,191898,4);
INSERT INTO stanza VALUES('S638','5','Así Su vaso Cristo_hará,<br/>Con ellos lo_edificará;<br/>Y Su todo-inclusividad<br/>En transparencia expresarán.<br/>',NULL,191899,5);
INSERT INTO stanza VALUES('S638','6','Por toda la transformación<br/>Del Triuno Dios en nuestro ser,<br/>La_iglesia_un vaso_al fin será<br/>Tal como la Jerusalén.<br/>',NULL,191900,6);
INSERT INTO stanza VALUES('S638','7','Preciosa en todo ella es<br/>Transparente en cada fase;<br/>Cristo, la plenitud de Dios,<br/>Su gloria en ella exhibe bien.<br/>',NULL,191901,7);
INSERT INTO stanza VALUES('S638','8','Cristo, su vida y Dios, su luz<br/>Con el Espíritu fluirá,<br/>Ella así al Triuno Dios<br/>Al universo mostrará.<br/>',NULL,191902,8);
INSERT INTO stanza VALUES('S639','1','La_iglesia_el candelero es;<br/>Cristo, la lámpara de Dios;<br/>La luz de Dios brilla de Él,<br/>Su_iglesia muestra_el resplandor.<br/>',NULL,191903,1);
INSERT INTO stanza VALUES('S639','2','La lámpara emite luz:<br/>Es Dios, la vida divinal;<br/>De oro el candelero es<br/>Para tal gloriar igualar.<br/>',NULL,191904,2);
INSERT INTO stanza VALUES('S639','3','En medio de la oscuridad,<br/>La luz de vida ha de alumbrar<br/>Testificando de Jesús<br/>A toda la humanidad.<br/>',NULL,191905,3);
INSERT INTO stanza VALUES('S639','4','Para tal testimonio ser,<br/>Ella guarda el "primer amor";<br/>"El árbol de vida" tendrán<br/>Los vencedores por porción.<br/>',NULL,191906,4);
INSERT INTO stanza VALUES('S639','5','Debe aguantar persecución<br/>Para "la corona" ganar;<br/>Todo el adulterio ha de vencer<br/>Para "el maná escondido" hallar.<br/>',NULL,191907,5);
INSERT INTO stanza VALUES('S639','6','La tierra ella regirá<br/>Si abandona a "Jezebel";<br/>Y "ropas blancas" vestirá<br/>Si toda muerte vence en Él.<br/>',NULL,191908,6);
INSERT INTO stanza VALUES('S639','7','Como "Filadelfia" será:<br/>A Su nombre y palabra, fiel;<br/>Y la "tibieza" vencerá<br/>Para cenar junto con Él.<br/>',NULL,191909,7);
INSERT INTO stanza VALUES('S639','8','Su iglesia Él purificará,<br/>Hasta de oro puro ser;<br/>La vida que Jesús llevó,<br/>Su testimonio debe ser.<br/>',NULL,191910,8);
INSERT INTO stanza VALUES('S639','9','Las iglesias locales hoy<br/>Los candeleros deben ser;<br/>Y el candelero eternal<br/>Es la Nueva Jerusalén.<br/>',NULL,191911,9);
INSERT INTO stanza VALUES('S639','10','De oro puro es la ciudad;<br/>Candelero en consumación;<br/>Su lámpara, Cristo el Señor,<br/>Irradia allí la luz de Dios.<br/>',NULL,191912,10);
INSERT INTO stanza VALUES('S640','1','Antes de fundar el mundo,<br/>Dios en Cristo eligió<br/>Su iglesia pura, santa,<br/>Con Él una_en filiación;<br/>Como posesión preciosa<br/>Que_el Espíritu selló<br/>Con las arras de la_herencia<br/>Su_Hijo_en ella_Él reveló.<br/>',NULL,191913,1);
INSERT INTO stanza VALUES('S640','2','Sobre todo señorío,<br/>Cristo al trono ascendió;<br/>A la iglesia aquí, Su Cuerpo,<br/>Por Cabeza Dios lo dio.<br/>Todo en todo Él lo llena<br/>Hasta Su expresión lograr<br/>Por la iglesia, que es Su Cuerpo,<br/>Plenitud e imagen real.<br/>',NULL,191914,2);
INSERT INTO stanza VALUES('S640','3','Muertos en nuestras ofensas,<br/>Muy mundano nuestro andar,<br/>Lujuriosos en la mente,<br/>Nuestra fuente: Satanás.<br/>Dios nos levantó con Cristo,<br/>En los cielos nos sentó;<br/>Como Su obra maestra,<br/>Dios en Cristo nos creó.<br/>',NULL,191915,3);
INSERT INTO stanza VALUES('S640','4','Los judíos y gentiles<br/>En el Cuerpo hoy están,<br/>Firmes sobre el fundamento:<br/>Cristo, la piedra angular.<br/>Hoy en Él edificados,<br/>Son la habitación de Dios;<br/>Firmemente concertados<br/>Por Su Espíritu en amor.<br/>',NULL,191916,4);
INSERT INTO stanza VALUES('S640','5','Quiso Su sabiduria<br/>Dios a todos revelar<br/>Por la iglesia, Su misterio,<br/>Donde el Hijo hace hogar.<br/>Que en espíritu los santos<br/>Puedan ver Su vastedad,<br/>Conocer Su amor inmenso<br/>Y Su plenitud lograr.<br/>',NULL,191917,5);
INSERT INTO stanza VALUES('S640','6','Solo un Cuerpo y esperanza,<br/>Un Espíritu, un Señor,<br/>Una fe y un bautismo,<br/>En la iglesia, un Padre Dios;<br/>Conociendo en pleno a Cristo<br/>Hasta entrar en madurez,<br/>Sin que seamos zarandeados<br/>Por doctrinas que hombres den.<br/>',NULL,191918,6);
INSERT INTO stanza VALUES('S640','7','Muchos dones Cristo ha dado,<br/>Para el Cuerpo edificar;<br/>Perfeccionan a los santos,<br/>Así pueden ministrar.<br/>Libres ya del viejo hombre<br/>Para el nuevo así llevar,<br/>Con sus mentes renovadas,<br/>A Dios pueden expresar.<br/>',NULL,191919,7);
INSERT INTO stanza VALUES('S640','8','Se dio Cristo a Sí mismo<br/>Para Su iglesia hacer<br/>Santa, sin arruga o mancha;<br/>Su gloriosa novia es.<br/>Él la nutre y la cuida<br/>Como el hombre a su mujer,<br/>Quienes son un solo cuerpo:<br/>Gran misterio esto es.<br/>',NULL,191920,8);
INSERT INTO stanza VALUES('S640','9','Cuerpo, casa, nuevo hombre,<br/>Templo y novia a la vez;<br/>El guerrero es la iglesia<br/>Que a Satán ha de vencer.<br/>La armadura de Dios tiene,<br/>Y Su fuerza es el Señor;<br/>Firme en Él, ella resiste<br/>Y combate en oración.<br/>',NULL,191921,9);
INSERT INTO stanza VALUES('S641','1','La iglesia, los llamados,<br/>Cuerpo de Cristo es,<br/>El hombre_y Dios mezclados,<br/>Su morada también;<br/>Electa_en el pasado,<br/>La redimió_al morir,<br/>Su postura y carácter<br/>Es celestial sin fin.<br/>',NULL,191922,1);
INSERT INTO stanza VALUES('S641','2','La iglesia, el nuevo hombre,<br/>Nació en resurrección;<br/>Se bautizó_en el Santo<br/>Espíritu de Dios;<br/>Santa por la Palabra,<br/>Su vida Cristo es;<br/>Con la Cabeza en gloria,<br/>Todo puesto a sus pies.<br/>',NULL,191923,2);
INSERT INTO stanza VALUES('S641','3','Su único cimiento<br/>Es Cristo el Señor;<br/>Como Él, ella es divina<br/>En todo su interior;<br/>Sus miembros en la muerte<br/>Y en resurrección,<br/>Como oro, plata y piedras,<br/>Edificados son.<br/>',NULL,191924,3);
INSERT INTO stanza VALUES('S641','4','Un Dios, un Señor nuestro,<br/>Un Espíritu fiel,<br/>Una fe, un bautismo,<br/>Una esperanza en Él;<br/>Un Cuerpo son sus miembros,<br/>El Dios Triuno en él,<br/>Esperando Su gloria,<br/>Se unen por la fe.<br/>',NULL,191925,4);
INSERT INTO stanza VALUES('S641','5','De toda tribu y lengua<br/>Todos Sus miembros son;<br/>Sin importar las clases,<br/>Son uno_en el Señor.<br/>No hay libre ni esclavo,<br/>Ni raza alguna en Él,<br/>Mas Cristo el todo en todos<br/>El "nuevo hombre" es.<br/>',NULL,191926,5);
INSERT INTO stanza VALUES('S641','6','Expresa cada Iglesia<br/>El Cuerpo universal;<br/>Su único terreno<br/>Es la localidad;<br/>Local es su gobierno<br/>Sujeta al Señor;<br/>Y universalmente<br/>Son una en comunión.<br/>',NULL,191927,6);
INSERT INTO stanza VALUES('S641','7','En todas sus reuniones<br/>Se ve con claridad<br/>Aspectos y detalles<br/>De la Santa Ciudad.<br/>La lámpara es Cristo,<br/>La luz interna es Dios;<br/>Ellas son candeleros,<br/>Su imagen, Su expresión.<br/>',NULL,191928,7);
INSERT INTO stanza VALUES('S642','1','Cristo, semilla de la iglesia es<br/>Sembrada en humano corazón;<br/>El trigo, flor de_harina llega_a ser,<br/>Un pan que satisface_al hombre y Dios.<br/>',NULL,191929,1);
INSERT INTO stanza VALUES('S642','2','Falsos creyentes Satanás sembró,<br/>Entre los santos la cizaña entró;<br/>Frustró el crecer y trajo confusión,<br/>Queriendo así impedir el plan de Dios.<br/>',NULL,191930,2);
INSERT INTO stanza VALUES('S642','3','La iglesia, hierba de mostaza es,<br/>Nace de Cristo, su semilla es Él;<br/>Aunque se oculta en su pequeñez,<br/>Puede al hambriento hoy satisfacer.<br/>',NULL,191931,3);
INSERT INTO stanza VALUES('S642','4','Mas esa hierba Satanás cambió;<br/>Él su naturaleza trasmutó;<br/>De ella un grande ábrol él formó,<br/>Do se anidan los malignos hoy.<br/>',NULL,191932,4);
INSERT INTO stanza VALUES('S642','5','La "iglesia" caída usó Satan,<br/>El paganismo en ella infiltró;<br/>Con levadura la_harina mezcló,<br/>El alimento puro así dañó.<br/>',NULL,191933,5);
INSERT INTO stanza VALUES('S642','6','Mas Cristo en vida viene a transformar,<br/>Todos Sus santos quiere edificar;<br/>Piedras preciosas, perlas los hará<br/>Para Su iglesia y reino expresar.<br/>',NULL,191934,6);
INSERT INTO stanza VALUES('S642','7','Crece en Cristo la asamblea hoy,<br/>Él la transforma y edifica así;<br/>Ella es la perla de tan gran valor<br/>Y el tesoro que Él escondió.<br/>',NULL,191935,7);
INSERT INTO stanza VALUES('S642','8','De la "cizaña" hoy apártanos;<br/>De tal gran "árbol" líbranos, Señor;<br/>De levadura purificanos;<br/>Haznos comida para el hombre y Dios.<br/>',NULL,191936,8);
INSERT INTO stanza VALUES('S642','9','En vida, a diario, haznos Tú crecer,<br/>Transforma y edifícanos así<br/>Como un cuerpo que te exprese a Ti;<br/>Haznos Tu iglesia y Tu reino aquí.<br/>',NULL,191937,9);
INSERT INTO stanza VALUES('S643','1','Las siete_iglesias vistas en<br/>Apocalipsis dos y tres,<br/>Lecciones guardan, que_el Señor<br/>Presenta_a Su recobro hoy.<br/>',NULL,191938,1);
INSERT INTO stanza VALUES('S643','2','Debemos hoy obedecer<br/>Lo que escrito a ellas fue,<br/>Para Su gloriosa iglesia ser,<br/>Para el Señor satisfacer.<br/>',NULL,191939,2);
INSERT INTO stanza VALUES('S643','3','A Éfeso se escribió:<br/>"Atrás quedó el primer amor,<br/>Lo han dejado para obrar,<br/>¡Arrepentíos, regresad!".<br/>',NULL,191940,3);
INSERT INTO stanza VALUES('S643','4','Volvamos todos al Señor,<br/>Dejando atrás todo otro amor.<br/>Obedezcamos Su clamar,<br/>Si no, perdido todo está.<br/>',NULL,191941,4);
INSERT INTO stanza VALUES('S643','5','A Esmirna, que sufriendo está,<br/>Le dice: "Has padecido ya,<br/>Hasta la muerte sigue fiel"<br/>(En cuerpo y alma también).<br/>',NULL,191942,5);
INSERT INTO stanza VALUES('S643','6','Debemos siempre fieles ser<br/>Hasta lo natural perder;<br/>Se exhiba el primer amor<br/>En todo entorno que Él mandó.<br/>',NULL,191943,6);
INSERT INTO stanza VALUES('S643','7','En Pérgamo unido está<br/>El mundo con la cristiandad.<br/>Antipas firme estuvo así,<br/>En contra de todo hasta el fin.<br/>',NULL,191944,7);
INSERT INTO stanza VALUES('S643','8','Temamos la unión mundanal:<br/>Nos salva Su palabra ya;<br/>Si escuchamos Su hablar,<br/>Del mundo nos separará.<br/>',NULL,191945,8);
INSERT INTO stanza VALUES('S643','9','Tiatira ahora vemos bien:<br/>Mixtura con el mundo es.<br/>La flor de harina se leudó,<br/>Ramera en degradación.<br/>',NULL,191946,9);
INSERT INTO stanza VALUES('S643','10','Señor, hoy ilumínanos;<br/>Oh, tal mixtura muéstranos.<br/>Lo añadido, saca ya,<br/>Y absolutos nos harás.<br/>',NULL,191947,10);
INSERT INTO stanza VALUES('S643','11','Con Sardis conocemos que<br/>Su vida el camino es,<br/>Dice que vive, y muerta está,<br/>A Cristo debe contactar.<br/>',NULL,191948,11);
INSERT INTO stanza VALUES('S643','12','Señor, a vida llévanos,<br/>Sobre la muerte, vence hoy.<br/>Huiremos de la mortandad,<br/>La vida así nos llenará.<br/>',NULL,191949,12);
INSERT INTO stanza VALUES('S643','13','Ya vemos Filadelfia, al fin,<br/>Lo que ella tiene, ha de asir,<br/>Pues satisface al Señor:<br/>Su hablar, Su nombre, Su amor.<br/>',NULL,191950,13);
INSERT INTO stanza VALUES('S643','14','Hermanos somos, en unión,<br/>En vida nos unió el Señor.<br/>Guardando el nombre y el hablar,<br/>Gloriosa iglesia Dios tendrá.<br/>',NULL,191951,14);
INSERT INTO stanza VALUES('S643','15','Laodicea nos advirtió,<br/>En Filadelfia, que cayó,<br/>Pues dijo: "Yo muy rica soy",<br/>Y afuera al Señor dejó.<br/>',NULL,191952,15);
INSERT INTO stanza VALUES('S643','16','Lo tibio hay que rechazar,<br/>Ferviente espíritu llevar<br/>Y todo precio ya pagar<br/>Para con el Señor reinar.<br/>',NULL,191953,16);
INSERT INTO stanza VALUES('S643','17','Concédenos Tu luz, Señor,<br/>Para seguir Tu senda hoy;<br/>Oh, úngenos y haznos ver,<br/>Así el recobro has de obtener.<br/>',NULL,191954,17);
INSERT INTO stanza VALUES('S644','1','La unidad de la iglesia es<br/>Los santos siendo uno,<br/>En ellos el Espíritu<br/>Morando _así los une.<br/>La_unidad del Espíritu<br/>Por Él real es hecha;<br/>Se basa en la común fe<br/>Que los santos heredan.<br/>',NULL,191955,1);
INSERT INTO stanza VALUES('S644','2','Esta preciosa común fe<br/>Se constituye sólo<br/>De Cristo con Su redención,<br/>Que_es único y santo.<br/>En esto de_un acuerdo_están<br/>Todos los que hoy creen,<br/>La_iglesia misma así nació<br/>De esta su común fe.<br/>',NULL,191956,2);
INSERT INTO stanza VALUES('S644','3','La iglesia_universal de Dios<br/>En vida es una_en Cristo;<br/>Por tanto la iglesia local<br/>Es una en su_expresión.<br/>Sus elementos son un Dios,<br/>Un Espíritu, un Señor,<br/>Una_esperanza y una fe,<br/>Un Cuerpo y un bautismo.<br/>',NULL,191957,3);
INSERT INTO stanza VALUES('S644','4','Es sólo esta unidad<br/>Que_a la_iglesia en pleno<br/>Demanda el Espíritu<br/>Como único terreno.<br/>Así la iglesia en práctica<br/>Guarda su_unión vital,<br/>Y_en comunión se_edifica<br/>En cada localidad.<br/>',NULL,191958,4);
INSERT INTO stanza VALUES('S644','5','Háznos solícitos, Señor,<br/>En guardar la unidad<br/>Tomando el terreno hoy<br/>De la_iglesia en realidad.<br/>Así Tu beneplácito<br/>Se podrá ya realizar,<br/>Y el eterno plan de Dios<br/>Se podrá al fin completar.<br/>',NULL,191959,5);
INSERT INTO stanza VALUES('S645','1','Cristo_el Hijo amado con Su redención,<br/>Esto_es nuestro credo, fe y salvación;<br/>Las demás doctrinas no se incluirán,<br/>Sólo Su persona y_obra contarán.<br/>',NULL,191960,1);
INSERT INTO stanza VALUES('S645','2','La_enseñanza impropia sólo traerá<br/>"Vientos de doctrina" contra la_unidad;<br/>Distrae a los santos de la comunión<br/>Que hay en la Cabeza y edificación.<br/>',NULL,191961,2);
INSERT INTO stanza VALUES('S645','3','Todas las doctrinas hay que_abandonar,<br/>Mas la fe genuina se debe guardar;<br/>Esta fe nos lleva a ser uno hoy,<br/>Uno en el Espíritu y en el Señor.<br/>',NULL,191962,3);
INSERT INTO stanza VALUES('S645','4','Debemos asirnos sólo a la verdad<br/>Para el yo sectario poder anular,<br/>Para que crezcamos en todo hacia Aquel<br/>Quien es la Cabeza, y Su Cuerpo ver.<br/>',NULL,191963,4);
INSERT INTO stanza VALUES('S645','5','Para a "la unidad de fe" llegar,<br/>"Vientos de doctrinas" hay que rechazar;<br/>Sólo a Cristo asidos y a Su realidad<br/>Por Su Espíritu el Cuerpo crecerá.<br/>',NULL,191964,5);
INSERT INTO stanza VALUES('S646','1','En espíritu uno por Su vida sin par,<br/>Todas las divisiones por el Cuerpo dejad,<br/>Pues no_existen barreras,<br/>Derrumbadas ya_están.<br/>',NULL,191965,1);
INSERT INTO stanza VALUES('S646','note','**Hermanos:**<br/>',NULL,191966,2);
INSERT INTO stanza VALUES('S646','chorus','En la iglesia, hermanos,<br/>Somos hoy, ¡gloria_a Dios!<br/>',NULL,191967,3);
INSERT INTO stanza VALUES('S646','note','**Hermanas:**<br/>',NULL,191968,4);
INSERT INTO stanza VALUES('S646','chorus','En la iglesia, hermanas,<br/>Somos hoy, ¡gloria_a Dios!<br/>',NULL,191969,5);
INSERT INTO stanza VALUES('S646','note','**Todos:**<br/>',NULL,191970,6);
INSERT INTO stanza VALUES('S646','chorus','¡Aleluya! En Su iglesia la unidad se logró.<br/>',NULL,191971,7);
INSERT INTO stanza VALUES('S646','2','En espíritu uno, pero va más allá,<br/>Alcanzando la mente, emoción y voluntad,<br/>Al estar de un acuerdo para realizar Su plan.<br/>',NULL,191972,8);
INSERT INTO stanza VALUES('S646','3','En espíritu uno, somos uno en verdad.<br/>No es una teoría sino practica real,<br/>Disfrutamos en las iglesias hoy tal realidad.<br/>',NULL,191973,9);
INSERT INTO stanza VALUES('S646','4','En espíritu uno y en la localidad,<br/>Consagrémonos todos para así cumplir Su plan,<br/>Para que el mundo vea que Él nos dio la unidad.<br/>',NULL,191974,10);
INSERT INTO stanza VALUES('S647','1','Jesús el fundamento,<br/>De la iglesia es;<br/>Nueva creación es ella,<br/>Por Su Palabra fiel;<br/>Él descendió del cielo<br/>Para Su novia hallar;<br/>Por ella dio Su vida,<br/>Su sangre al derramar.<br/>',NULL,191975,1);
INSERT INTO stanza VALUES('S647','2','De todas las naciones<br/>Sus elegidos son;<br/>Es una sola iglesia,<br/>Ésta es su salvación:<br/>Una fe, una nacimiento,<br/>Un nombre, un Señor,<br/>Un mismo alimento,<br/>Una esperanza hoy.<br/>',NULL,191976,2);
INSERT INTO stanza VALUES('S647','3','En sus tribulaciones,<br/>En guerra y aflicción,<br/>Por paz ella aguarda<br/>En su consumación;<br/>Una visión gloriosa<br/>Anhela contemplar:<br/>La iglesia victoriosa<br/>Que en reposo está.<br/>',NULL,191977,3);
INSERT INTO stanza VALUES('S647','4','La iglesia hoy es uno<br/>Con el Triuno Dios,<br/>Y con los que reposan,<br/>Goza de comunión.<br/>¡Alegres son sus santos!<br/>Concédenos, Señor,<br/>Ser mansos como ellos,<br/>Morando en Ti en amor.<br/>',NULL,191978,4);
INSERT INTO stanza VALUES('S648','1','Piedra angular Tú eres,<br/>Despreciado de_Israel;<br/>Mas Dios te_ha resucitado,<br/>Precioso_eres para Él.<br/>Los judíos y gentiles,<br/>Todos salvos son por Ti;<br/>Juntos como nuevo hombre,<br/>Tu morada son aquí.<br/>',NULL,191979,1);
INSERT INTO stanza VALUES('S648','2','Tú, Señor, la Roca herida,<br/>Sacias toda nuestra sed;<br/>A Dios casa edificas,<br/>Y al frágil das sostén.<br/>Tú en Sión, Cimiento estable,<br/>Piedra que probada fue;<br/>Tú, la Roca de la iglesia,<br/>Fundamento siempre fiel.<br/>',NULL,191980,2);
INSERT INTO stanza VALUES('S648','3','La iglesia edificada<br/>Sobre Ti perdurará;<br/>Aunque el Hades la asalte,<br/>Ella prevalecerá.<br/>Con Tu autoridad divina,<br/>Ata y desata en Ti;<br/>A Tu reino trae los hombres,<br/>Los catutivos libra así.<br/>',NULL,191981,3);
INSERT INTO stanza VALUES('S648','4','Señor, Piedra viva eres,<br/>Escogida para hacer<br/>De nosotros piedras vivas,<br/>Y contigo uno ser.<br/>Como un templo edificados,<br/>Somos el hogar de Dios;<br/>Siendo un sacerdocio santo,<br/>Grata ofrenda damos hoy.<br/>',NULL,191982,4);
INSERT INTO stanza VALUES('S648','5','De David, el Hijo eres<br/>Para el templo edificar;<br/>Rey y Sacerdote eres,<br/>Todo cargo cumples ya;<br/>Como Rey, por Dios Tú reinas,<br/>Pones todo en sumisión;<br/>Como Sacerdote santo,<br/>Traes los hombres ante Dios.<br/>',NULL,191983,5);
INSERT INTO stanza VALUES('S648','6','Desde el trono fluye un río<br/>Que conlleva autoridad,<br/>Comunión y suministro,<br/>Resultando en dulce paz;<br/>Éstos traen un equilibrio<br/>Para que Dios pueda ver<br/>Su morada edificada<br/>Por Su Sacerdote y Rey.<br/>',NULL,191984,6);
INSERT INTO stanza VALUES('S648','7','Siendo Dios, te hiciste carne;<br/>Mora DIos y el hombre en Ti;<br/>Tú, el Templo de Su gloria;<br/>Dios se manifiesta así.<br/>Igualmente es la iglesia<br/>Dios y el hombre en unión;<br/>Cada miembro sirve en ella<br/>Para edificación.<br/>',NULL,191985,7);
INSERT INTO stanza VALUES('S648','8','Tú por siempre eres Morada:<br/>Nuestra eterna habitación;<br/>Al vivir en Ti, probamos<br/>Que eres nuestra protección.<br/>Eres Tú nuestro Santuario,<br/>Mutua habitación con Dios;<br/>Su presencia, Tú en nosotros,<br/>Nos motiva a adoración.<br/>',NULL,191986,8);
INSERT INTO stanza VALUES('S648','9','Piedra angular, cimera,<br/>Piedra viva, Cimiento,<br/>Eres Santuario y Morada,<br/>También Edificador;<br/>¡Oh, por todo lo que eres,<br/>Te alabamos hoy aquí!<br/>Señor, como piedras vivas,<br/>Edifícanos en Ti.<br/>',NULL,191987,9);
INSERT INTO stanza VALUES('S649','1','Hoy te_alabamos por Tu plan,<br/>Pues nos harás Tu_habitación.<br/>Viviendo_en nuestro ser tendrás<br/>Una morada y expresión.<br/>',NULL,191988,1);
INSERT INTO stanza VALUES('S649','2','Dios a Su_imagen nos creó,<br/>Nos dio Su misma autoridad;<br/>Sólo de barro nos formó,<br/>Mas sin Su esencia divinal.<br/>',NULL,191989,2);
INSERT INTO stanza VALUES('S649','3','Al recibirlo_en nuestro ser<br/>Su esencia y vida nos legó;<br/>Mezclados hoy el hombre y Dios,<br/>Somos un Cuerpo, Su expresión.<br/>',NULL,191990,3);
INSERT INTO stanza VALUES('S649','4','Fluye Tu vida en nuestro ser,<br/>Piedras preciosas nos harás;<br/>Vas renovando el corazón,<br/>Y a Tu imagen nos cambiarás.<br/>',NULL,191991,4);
INSERT INTO stanza VALUES('S649','5','Pero todo_esto no será<br/>Para un elogió o vanidad,<br/>Mas para que_haya material<br/>Para Tu casa edificar.<br/>',NULL,191992,5);
INSERT INTO stanza VALUES('S649','6','A Ti nos damos, oh Señor,<br/>Y a Tus manos sabias hoy;<br/>Quebrántanos hasta obtener<br/>Una gloriosa habitación.<br/>',NULL,191993,6);
INSERT INTO stanza VALUES('S649','7','Quiebra esta vida natural,<br/>Quiebra también lo peculiar,<br/>De independencia líbranos,<br/>Para ser uno en verdad.<br/>',NULL,191994,7);
INSERT INTO stanza VALUES('S649','8','Así Tu Novia nos harás,<br/>Disfrutaremos de Tu amor;<br/>Y Tú tendrás Tu ansiado hogar<br/>Que saciará Tu corazón.<br/>',NULL,191995,8);
INSERT INTO stanza VALUES('S650','1','Valoro el modelo hoy<br/>Del tabernáculo real;<br/>Nos muestra Tu_edificación<br/>En que Tu gloria se verá.<br/>',NULL,191996,1);
INSERT INTO stanza VALUES('S650','2','El Arca en la tienda está,<br/>Y en el Arca está la ley;<br/>La tienda siempre alojará<br/>El Arca, que su centro es.<br/>',NULL,191997,2);
INSERT INTO stanza VALUES('S650','3','Muestra al Dios-hombre el Arca hoy;<br/>Oro y madera: el hombre y Dios;<br/>La ley expresa al mismo Dios<br/>Que mora en Cristo el Señor.<br/>',NULL,191998,3);
INSERT INTO stanza VALUES('S650','4','Cristo en la iglesia el centro es,<br/>Y ella es Su descanso fiel;<br/>Morando en Cristo, el Padre está,<br/>Así en la iglesia habita Él.<br/>',NULL,191999,4);
INSERT INTO stanza VALUES('S650','5','La tienda: el Arca en su expresión,<br/>Madera y oro ambos son;<br/>La iglesia es Cristo en Su expresión,<br/>Mezclado el hombre con su Dios.<br/>',NULL,192000,5);
INSERT INTO stanza VALUES('S650','6','Sus tablas de oro puro están<br/>Cubiertas, firmes, en unión;<br/>Por sus anillos varas van;<br/>Las basas de ellas, plata son<br/>',NULL,192001,6);
INSERT INTO stanza VALUES('S650','7','Así la iglesia es la reunión<br/>De santos que, por redención,<br/>En vida y en espíritu,<br/>Edificados todos son.<br/>',NULL,192002,7);
INSERT INTO stanza VALUES('S650','8','Cuatro cubiertas dan a ver<br/>A Cristo en Su vivir y ser;<br/>Nos muestran la gloria de Dios<br/>Que cubre Su habitación.<br/>',NULL,192003,8);
INSERT INTO stanza VALUES('S650','9','Así, cubiertos del Señor,<br/>Los santos concertados son;<br/>Disfrutan todo lo que Él es,<br/>En gloriosa edificación.<br/>',NULL,192004,9);
INSERT INTO stanza VALUES('S650','10','Dentro del Arca está la ley;<br/>El Arca en la tienda está;<br/>Dios en Cristo en la iglesia está;<br/>Su gloria manifiesta ya.<br/>',NULL,192005,10);
INSERT INTO stanza VALUES('S651','1','Alfarero‿eres, Señor,<br/>Que Tu vaso moldearás;<br/>También  edificador,<br/>Que Tu_hogar construirás.<br/>Yo de barro hecho fui,<br/>Piedra viva_ahora soy,<br/>Para yo Tu vaso ser<br/>Y_además Tu templo  hoy.<br/>',NULL,192006,1);
INSERT INTO stanza VALUES('S651','2','Tu creación de barro fue,<br/>Mas la quieres transformar<br/>En preciosas piedras hoy<br/>Por Tu vida divinal.<br/>Es por la edificación<br/>Que Tu Novia obtendrás,<br/>Como un Cuerpo unido a Ti,<br/>Satisfecho estarás.<br/>',NULL,192007,2);
INSERT INTO stanza VALUES('S651','3','No la piedra individual<br/>Quiere ver Tu corazón;<br/>Por Tu gloria, por Tu hogar,<br/>Quieres la edificación.<br/>Tú, el Cristo sin igual,<br/>Tal iglesia quieres ver,<br/>Donde puedas expresar<br/>Las riquezas de Tu ser.<br/>',NULL,192008,3);
INSERT INTO stanza VALUES('S651','4','No el hombre espiritual<br/>En su forma individual,<br/>Mas la vida corporal,<br/>Tu deseo cumplirá.<br/>Separados no podrán<br/>Hoy Tus miembros realizar<br/>Tu completa expresión,<br/>Sólo el Cuerpo la obtendrá.<br/>',NULL,192009,4);
INSERT INTO stanza VALUES('S651','5','Libre de lo individual,<br/>Concertado quiero estar;<br/>Edifícame, Señor,<br/>Con los santos en Tu plan.<br/>Mi experiencia y mi don<br/>No me han de envanecer,<br/>Para Tu edificación<br/>Quiero todo a Ti ceder.<br/>',NULL,192010,5);
INSERT INTO stanza VALUES('S652','1','Libre de Adán y_el ego,<br/>Edifícame, Señor,<br/>Con los santos como_un templo<br/>Do veremos Tu_esplendor.<br/>De los rasgos peculiares<br/>Y de lo individual<br/>Líbranos, y así seremos<br/>Tu morada eternal.<br/>',NULL,192011,1);
INSERT INTO stanza VALUES('S652','2','Al fluir en mí Tu vida<br/>Transformado yo seré,<br/>Coordinado con los santos<br/>Edificación tendré;<br/>Guardaré en Tu Cuerpo el orden<br/>Al hacer Tu voluntad,<br/>Ayudando y sirviendo<br/>Cumpliré Tu eterno plan.<br/>',NULL,192012,2);
INSERT INTO stanza VALUES('S652','3','Mi saber y experiencia<br/>No me deben exaltar;<br/>Balanceado por el Cuerpo,<br/>Sometido he de estar;<br/>Crezco con el crecimiento<br/>Que ministra la Cabeza;<br/>Me proveen las coyunturas<br/>Nutrición y unidad.<br/>',NULL,192013,3);
INSERT INTO stanza VALUES('S652','4','Con poder fortalecido<br/>En el hombre interior<br/>Por Tu Espíritu, comprendo<br/>Tu grandeza y vasto amor;<br/>Todas Tus riquezas tomo,<br/>Hasta ver Tu plenitud,<br/>Madurando en el Cuerpo,<br/>Así lo edificas Tú.<br/>',NULL,192014,4);
INSERT INTO stanza VALUES('S652','5','En Tu casa y en Tu Cuerpo<br/>Edifícame, Señor;<br/>Este vaso colectivo<br/>Mostrará Tu resplandor;<br/>Que Tu novia, ciudad santa,<br/>Aparezca en la tierra,<br/>Refulgente candelero<br/>Que exprese Tu valor.<br/>',NULL,192015,5);
INSERT INTO stanza VALUES('S653','1','Eres Tú mi vida,<br/>Vives en mí ya,<br/>Y la plenitud de<br/>Dios me_infundirás;<br/>Trae Tu santa_esencia<br/>Santificación,<br/>Y me da victoria<br/>Tu resurrección.<br/>',NULL,192016,1);
INSERT INTO stanza VALUES('S653','2','Al fluir Tu vida,<br/>En mi espíritu,<br/>Comunión contigo,<br/>Gozo en Tu luz;<br/>Todo lo que exiges<br/>Tu vida me da,<br/>Me guía a limpiarme,<br/>Para en Ti andar.<br/>',NULL,192017,2);
INSERT INTO stanza VALUES('S653','3','Tu Espíritu unge,<br/>Me empapará,<br/>Mi alma por completo<br/>Tú saturarás;<br/>Todo me transformas,<br/>Hasta madurar,<br/>A Tu semejanza<br/>Me has de conformar.<br/>',NULL,192018,3);
INSERT INTO stanza VALUES('S653','4','Tu vida abundante<br/>Fluye en mi ser,<br/>Siempre me refresca<br/>Y me da poder;<br/>Sorbida la muerte<br/>Por Tu vida está.<br/>Libre de ataduras,<br/>Me hace cantar.<br/>',NULL,192019,4);
INSERT INTO stanza VALUES('S653','5','Mi vida te rindo<br/>Plenamente a Ti,<br/>Para que Tú cumplas<br/>Tu deseo en mí;<br/>No quiero esforzarme<br/>En querer cambiar<br/>Lo que por Tu vida<br/>Puedes transformar.<br/>',NULL,192020,5);
INSERT INTO stanza VALUES('S653','6','Todo esfuerzo vano<br/>Tengo que parar,<br/>Siendo liberado<br/>Yo te dejó obrar;<br/>Con todos los santos<br/>Edifícame,<br/>Hasta que Tu gloria<br/>Expresada esté.<br/>',NULL,192021,6);
INSERT INTO stanza VALUES('S654','1','Sopla en mí, Señor;<br/>Mi_espíritu sostén;<br/>Quita mi muerte_y mi temor,<br/>Y alabanzas ten.<br/>',NULL,192022,1);
INSERT INTO stanza VALUES('S654','2','Sopla en mí, Señor;<br/>A mi ser, fuerza da;<br/>Que sin fatiga ande yo<br/>En alas de_águila.<br/>',NULL,192023,2);
INSERT INTO stanza VALUES('S654','3','Sopla en mí, Señor,<br/>Para descanso hallar;<br/>Que encuentre gozo el corazón<br/>En Ti, al descansar.<br/>',NULL,192024,3);
INSERT INTO stanza VALUES('S654','4','Sopla en mí, Señor,<br/>Hasta mi ser llenar;<br/>No viva yo, mas Cristo en mí,<br/>En mi sentir y obrar.<br/>',NULL,192025,4);
INSERT INTO stanza VALUES('S654','5','Sopla y quita así<br/>La independencia en mí;<br/>Que con los santos pueda ser<br/>Edificado en Ti.<br/>',NULL,192026,5);
INSERT INTO stanza VALUES('S655','1','Señor, exhala_en mí Tu vida,<br/>Pues secomo como hueso estoy;<br/>Que me avives y restaures,<br/>Oh, úneme al Cuerpo hoy.<br/>',NULL,192027,1);
INSERT INTO stanza VALUES('S655','2','Señor, exhala en mí Tu vida,<br/>Mi espíritu atado está;<br/>Oh, líbrame, rompe mis grillos,<br/>Quiero al fluir del Cuerpo entrar.<br/>',NULL,192028,2);
INSERT INTO stanza VALUES('S655','3','Señor, exhala en mí Tu vida,<br/>Mi espíritu caído está;<br/>Que Tu aliento me reviva,<br/>¡Del Cuerpo dame su caudal!<br/>',NULL,192029,3);
INSERT INTO stanza VALUES('S655','4','Señor, exhala en mí Tu vida,<br/>Mi espíritu sin gozo está;<br/>Que me consueles y bendigas,<br/>Para en Tu Cuerpo disfrutar.<br/>',NULL,192030,4);
INSERT INTO stanza VALUES('S655','5','Señor, exhala en mí Tu vida,<br/>De Ti yo quiero depender;<br/>Da fin a mi aislamiento y muerte,<br/>Y en Tu Cuerpo viviré.<br/>',NULL,192031,5);
INSERT INTO stanza VALUES('S656','1','¡Sopla, Señor! ¡Oh, háblanos!<br/>Reina la muerte_alrededor;<br/>Hay huesos secos por doquier.<br/>¡Sopla en nosotros, Señor!<br/>',NULL,192032,1);
INSERT INTO stanza VALUES('S656','2','¡Sopla, Señor! ¡Oh, háblanos!<br/>Revive nuestros huesos hoy;<br/>De nuestras tumbas sácanos.<br/>¡Sopla en nosotros, Señor!<br/>',NULL,192033,2);
INSERT INTO stanza VALUES('S656','3','¡Sopla, Señor! ¡Oh, háblanos!<br/>Tu pueblo aviva con vigor;<br/>Haznos las huestes contra el mal.<br/>¡Sopla en nosotros, Señor!<br/>',NULL,192034,3);
INSERT INTO stanza VALUES('S656','4','¡Sopla, Señor! Oh, háblanos<br/>Para que el pueblo esté en unión,<br/>Sumisos a Tu autoridad.<br/>¡Sopla en nosotros, Señor!<br/>',NULL,192035,4);
INSERT INTO stanza VALUES('S656','5','¡Sopla, Señor! Oh, háblanos<br/>Para acoplarnos en Tu amor,<br/>Y hacernos Tu habitación.<br/>¡Sopla en nosotros, Señor!<br/>',NULL,192036,5);
INSERT INTO stanza VALUES('S656','6','¡Hoy háblame! ¡Sopla, Señor!<br/>Avívame y edifícame;<br/>Del Cuerpo ya no aislado esté.<br/>¡Sopla, Señor en mi ser!<br/>',NULL,192037,6);
INSERT INTO stanza VALUES('S656','7','¡Hoy háblame! Sopla, Señor,<br/>Para en el Cuerpo combatir<br/>Y Tu enemigo destruir.<br/>¡Sopla, Señor en mi ser!<br/>',NULL,192038,7);
INSERT INTO stanza VALUES('S657','1','Libera mi espíritu, Señor,<br/>Al de los santos entretéjelo;<br/>Libre del yo y mi privacidad,<br/>Podré caber en Tu_edificación.<br/>',NULL,192039,1);
INSERT INTO stanza VALUES('S657','2','Libera mi espíritu, Señor,<br/>Yo confinado no quiero quedar;<br/>Ahogado estoy en mi ser natural.<br/>Si no me libras, ¿qué me librará?<br/>',NULL,192040,2);
INSERT INTO stanza VALUES('S657','3','Libera mi espíritu, Señor,<br/>Quiero escaparme de mi propio ser;<br/>Tu Espíritu así ha de fluir<br/>Y Tu presencia manifestaré.<br/>',NULL,192041,3);
INSERT INTO stanza VALUES('S657','4','Libera mi espíritu, Señor,<br/>Mi reclusión hoy quiero abandonar,<br/>Me ha hecho pobre mi privacidad;<br/>Salvo del yo, Tus bienes me darás.<br/>',NULL,192042,4);
INSERT INTO stanza VALUES('S657','5','Libera mi espíritu, Señor,<br/>No quiero en mis prisiones continuar;<br/>Rompe el engaño que usa Satanás,<br/>Del ego líbrame a Tu infinidad.<br/>',NULL,192043,5);
INSERT INTO stanza VALUES('S657','6','Libera mi espíritu, Señor,<br/>Que nunca el ego lo vuelva a atar;<br/>Que con los santos me pueda mezclar,<br/>En vida y Tus riquezas disfrutar.<br/>',NULL,192044,6);
INSERT INTO stanza VALUES('S658','1','¡Oh, que mi_espíritu<br/>Pueda fluir!<br/>Te ruega_a Ti, Señor,<br/>¡Manda el fluir!<br/>Dejando todo_atrás<br/>Los muros caerán,<br/>Mi_espíritu podrá<br/>Así fluir.<br/>',NULL,192045,1);
INSERT INTO stanza VALUES('S658','2','¡Oh, que mi espíritu<br/>Pueda fluir!<br/>Te imploro a Ti, Señor,<br/>¡Manda el fluir!<br/>No en mi orgullo estar,<br/>O en presunción andar,<br/>Ni mi espíritu atar;<br/>¡Hazlo fluir!<br/>',NULL,192046,2);
INSERT INTO stanza VALUES('S658','3','¡Oh, que mi espíritu<br/>Pueda fluir!<br/>Te pido a Ti, Señor,<br/>¡Manda el fluir!<br/>No inflado por el yo,<br/>O atado en su prisión,<br/>Tenga emancipación<br/>Mi espíritu.<br/>',NULL,192047,3);
INSERT INTO stanza VALUES('S658','4','¡Oh, que mi espíritu<br/>Pueda fluir!<br/>Te busco a Ti, Señor,<br/>¡Manda el fluir!<br/>No debo aislado estar,<br/>Ni mi ego elevar,<br/>Que fluya sin cesar<br/>Mi espíritu.<br/>',NULL,192048,4);
INSERT INTO stanza VALUES('S658','5','¡Oh, que mi espíritu<br/>Pueda fluir!<br/>Te ruego a Ti, Señor,<br/>¡Manda el fluir!<br/>Del trono haz caer,<br/>Hoy mi confiado ser,<br/>Que fluya agua de<br/>Mi espíritu<br/>',NULL,192049,5);
INSERT INTO stanza VALUES('S658','6','¡Oh, que mi espíritu<br/>Pueda fluir!<br/>Respóndeme, Señor,<br/>¡Manda el fluir!<br/>No sólo Tú y yo,<br/>Mas mi edificación<br/>Con otros en amor<br/>Y espíritu.<br/>',NULL,192050,6);
INSERT INTO stanza VALUES('S659','1','La comunión mi_espíritu_ama,<br/>Mezclado con los santos ser,<br/>Y salvo de mi_independencia,<br/>Hoy edificación tener.<br/>',NULL,192051,1);
INSERT INTO stanza VALUES('S659','2','La comunión mi espíritu ama,<br/>Para que abierto siempre esté;<br/>No más en reclusión continua,<br/>Mas con los santos te honraré.<br/>',NULL,192052,2);
INSERT INTO stanza VALUES('S659','3','La comunión mi espíritu ama,<br/>Anhelo su liberación;<br/>No quiero ser más un iluso,<br/>Quiero vencer mi condición.<br/>',NULL,192053,3);
INSERT INTO stanza VALUES('S659','4','La comunión mi espíritu ama,<br/>Y con los santos quiero orar;<br/>Quiero quitar las pretensiónes<br/>Y en dulce comunión entrar.<br/>',NULL,192054,4);
INSERT INTO stanza VALUES('S659','5','La comunión mi espíritu ama,<br/>Y conocer la autoridad;<br/>Anhelo comunión sincera,<br/>Y en el servicio coordinar.<br/>',NULL,192055,5);
INSERT INTO stanza VALUES('S659','6','Señor, se cumpla mi anhelo,<br/>Inspíranos a comunión;<br/>Para que, siendo edificados,<br/>Se plazca así Tu corazón.<br/>',NULL,192056,6);
INSERT INTO stanza VALUES('S660','1','¡Oh, qué bendición gloriosa!<br/>Ser un sacerdote real;<br/>Aunque sea_el más pequeño<br/>Tengo_oficio divinal.<br/>',NULL,192057,1);
INSERT INTO stanza VALUES('S660','chorus','La_edificación del Cuerpo<br/>Por el sacerdocio es;<br/>En mi_espíritu orando<br/>Este_oficio cumpliré.<br/>',NULL,192058,2);
INSERT INTO stanza VALUES('S660','2','Si atiendo este llamado<br/>Bajo Tu autoridad<br/>Se edificará la iglesia<br/>Por el sacerdocio real.<br/>',NULL,192059,3);
INSERT INTO stanza VALUES('S660','3','Es la iglesia el sacerdocio<br/>Concertado en unión;<br/>Hoy los sacerdotes juntos<br/>Forman su edificación.<br/>',NULL,192060,4);
INSERT INTO stanza VALUES('S660','4','En la iglesia degradada<br/>Este oficio se anuló;<br/>Sus espíritus endebles<br/>Sólo quieren un sermón.<br/>',NULL,192061,5);
INSERT INTO stanza VALUES('S660','5','Muchos buscan un mensaje<br/>Y no quieren funcionar,<br/>Descuidando el sacerdocio,<br/>Y, en espíritu, el orar.<br/>',NULL,192062,6);
INSERT INTO stanza VALUES('S660','6','Hazme ser equilibrado<br/>Al orar y predicar;<br/>Que, orando, a otros guíe,<br/>Tu Palabra al liberar.<br/>',NULL,192063,7);
INSERT INTO stanza VALUES('S660','7','Con espíritus unidos<br/>Y vital predicación,<br/>Se edificará la iglesia<br/>Al servir en oración.<br/>',NULL,192064,8);
INSERT INTO stanza VALUES('S661','1','Hoy los sacerdotes son<br/>Piedras vivas para Dios;<br/>Deben aprender a _orar<br/>Para la_edificación.<br/>',NULL,192065,1);
INSERT INTO stanza VALUES('S661','chorus','Entra al Santísimo,<br/>Toca_el trono del Señor;<br/>Que Él fluya en oración<br/>Para la_edificación.<br/>',NULL,192066,2);
INSERT INTO stanza VALUES('S661','2','Su función sacerdotal<br/>Todos tienen que cumplir;<br/>Para piedras vivas ser,<br/>Todos tienen que servir.<br/>',NULL,192067,3);
INSERT INTO stanza VALUES('S661','3','En días de antigüedad,<br/>Tienda y sacerdocio real<br/>Eran una entidad<br/>Que fluía en unidad.<br/>',NULL,192068,4);
INSERT INTO stanza VALUES('S661','4','Hoy la edificación<br/>Es función sacerdotal;<br/>Uno el sacerdocio es<br/>Con la casa espiritual.<br/>',NULL,192069,5);
INSERT INTO stanza VALUES('S661','5','Esta casa del Señor<br/>Sobre el sacerdocio está;<br/>Toda la edificación<br/>Ellos la culminarán.<br/>',NULL,192070,6);
INSERT INTO stanza VALUES('S661','6','Ellos han de edificar<br/>Dios y el hombre en unidad;<br/>Tal divina comunión<br/>Trae la unanimidad.<br/>',NULL,192071,7);
INSERT INTO stanza VALUES('S661','7','Nos compenetramos hoy<br/>En espíritu al orar;<br/>Damos sacrificio a Ti,<br/>Siendo un sacerdocio real.<br/>',NULL,192072,8);
INSERT INTO stanza VALUES('S661','8','Que apreciemos al servir<br/>Como sacerdocio real;<br/>LLévanos así a orar<br/>Y Tu iglesia edificar.<br/>',NULL,192073,9);
INSERT INTO stanza VALUES('S662','1','¡Qué bella Tu morada es!<br/>Yo en Tus atrios quiero_andar;<br/>Anhela mi espíritu,<br/>En Tu presencia siempre_estar.<br/>',NULL,192074,1);
INSERT INTO stanza VALUES('S662','2','En Tus altares, oh Señor,<br/>Su casa encuentra el gorrión,<br/>La golandrina para sí<br/>Prepara el nido de su amor.<br/>',NULL,192075,2);
INSERT INTO stanza VALUES('S662','3','El hombre, como el gorrión,<br/>Viene a Tu casa a reposar,<br/>Fía en la sangre del altar,<br/>Y del incienso gustará.<br/>',NULL,192076,3);
INSERT INTO stanza VALUES('S662','4','Se fortalecen con poder<br/>Los que confiando en Ti están;<br/>Pues las calzadas a Sion<br/>Su corazón afirmarán.<br/>',NULL,192077,4);
INSERT INTO stanza VALUES('S662','5','El valle de lamentación,<br/>Lo cambian en un manantial;<br/>Les trae la lluvia bendición,<br/>Y Tu merced pregonarán.<br/>',NULL,192078,5);
INSERT INTO stanza VALUES('S662','6','De poder en poder irán,<br/>Hasta Contigo estar en Sión,<br/>Buscando sólo ver Tu faz,<br/>Los cubras con Tu compasión.<br/>',NULL,192079,6);
INSERT INTO stanza VALUES('S662','7','Un día en Tus atrios es,<br/>Mejor que mil por fuera andar;<br/>Prefiero en su entrada estar,<br/>Que en las moradas de maldad.<br/>',NULL,192080,7);
INSERT INTO stanza VALUES('S662','8','Eres escudo, eres sol,<br/>Tu gracia y gloria suplirás;<br/>Con Tu presencia y mismo ser,<br/>Hoy llenas mi necesidad.<br/>',NULL,192081,8);
INSERT INTO stanza VALUES('S662','9','A los que siguen rectitud,<br/>Tus bienes no les negarás;<br/>Dichoso es el que espera en Ti,<br/>Tu gracia y gloria obtendrá.<br/>',NULL,192082,9);
INSERT INTO stanza VALUES('S663','1','Tu_habitación amo, Señor;<br/>Bendita_iglesia es,<br/>El gozo de Tu corazón<br/>Y Tu descanso es.<br/>',NULL,192083,1);
INSERT INTO stanza VALUES('S663','2','Por ella, te entregaste Tú,<br/>Para ella Tuya ser;<br/>Por ella, yo mi cuerpo doy,<br/>Para Tu buen placer.<br/>',NULL,192084,2);
INSERT INTO stanza VALUES('S663','3','Por ella, vida eres en mí,<br/>Por ella es mi vivir;<br/>Por ella yo me negaré,<br/>Se llenará de Ti.<br/>',NULL,192085,3);
INSERT INTO stanza VALUES('S663','4','La iglesia es Tu Novia fiel,<br/>Tu Cuerpo, Tu expresión,<br/>Ella mi anhelo y gozo es,<br/>Toda mi protección.<br/>',NULL,192086,4);
INSERT INTO stanza VALUES('S663','5','Tu suministro en ella está,<br/>Para impartirlo a mí;<br/>En ella me posees Tú,<br/>Para agradarte a Ti.<br/>',NULL,192087,5);
INSERT INTO stanza VALUES('S663','6','Tu habitación amo, Señor,<br/>La iglesia, Tu hogar;<br/>En ella siempre viviré,<br/>No vagaré jamás.<br/>',NULL,192088,6);
INSERT INTO stanza VALUES('S664','1','¡Tu reino amo, oh Dios!<br/>Tu casa y_expresión,<br/>La_iglesia que compraste Tú<br/>Con sangre, oh Redentor.<br/>',NULL,192089,1);
INSERT INTO stanza VALUES('S664','2','¡Tu iglesia amo, oh Dios!<br/>Sus muros Tuyos son;<br/>La  niña de Tus ojos es,<br/>Y está en Tu mano hoy.<br/>',NULL,192090,2);
INSERT INTO stanza VALUES('S664','3','Por ella es mi oración,<br/>Mis lágrimas, mi amor,<br/>Solicitud, cuidado, afán,<br/>Por ella son, Señor.<br/>',NULL,192091,3);
INSERT INTO stanza VALUES('S664','4','Tesoro sin igual<br/>Hoy sus caminos son:<br/>Sus votos, dulce comunión<br/>E himnos de amor.<br/>',NULL,192092,4);
INSERT INTO stanza VALUES('S664','5','Ella perdurará,<br/>Oh Dios, cual Tu verdad,<br/>Y victoriosa llegará<br/>Hasta la eternidad.<br/>',NULL,192093,5);
INSERT INTO stanza VALUES('S665','1','Son los santos todos<br/>Miembros del Señor;<br/>Todos coordinando<br/>Llegan a la unión.<br/>',NULL,192094,1);
INSERT INTO stanza VALUES('S665','2','Muchos son los dones,<br/>Un Espíritu;<br/>Muchas las funciones,<br/>Un Señor, Jesús.<br/>',NULL,192095,2);
INSERT INTO stanza VALUES('S665','3','Estimando a otros,<br/>Sin parcialidad;<br/>Cada uno tiene<br/>Su utilidad.<br/>',NULL,192096,3);
INSERT INTO stanza VALUES('S665','4','Conforme a la gracia<br/>Es también el don;<br/>Con cordura todos<br/>Cumplen su función.<br/>',NULL,192097,4);
INSERT INTO stanza VALUES('S665','5','Hace cada uno<br/>Siempre su deber;<br/>Con fervor ceñido<br/>Su espíritu fiel.<br/>',NULL,192098,5);
INSERT INTO stanza VALUES('S665','6','Supliendo y cuidando<br/>Con gracia y amor;<br/>No en discordancia<br/>Dando a Cristo honor.<br/>',NULL,192099,6);
INSERT INTO stanza VALUES('S665','7','Es la iglesia el Cuerpo,<br/>La Cabeza, Tú;<br/>Al fluir nos une<br/>El Espíritu.<br/>',NULL,192100,7);
INSERT INTO stanza VALUES('S666','1','¡Mirad cuán bueno y agradable,<br/>Que guarden los hermanos la_unidad!<br/>La bendición allí envía Jehová,<br/>La bendición de vida eternal.<br/>',NULL,192101,1);
INSERT INTO stanza VALUES('S666','2','Banquete del Señor disfruto hoy,<br/>Pruebo Su rica gracia y el amor;<br/>Por los hermanos en tal comunión,<br/>Vendrá ese día de eternal reunión.<br/>',NULL,192102,2);
INSERT INTO stanza VALUES('S667','1','¡Cuán bueno_y agradable es<br/>Morar en unidad!<br/>Es como_el ólea sobre_Aarón<br/>Que hasta_el borde va;<br/>Como_el rocío de Hermón<br/>Desciende sobre Sión;<br/>La vida_eterna manda allí<br/>Dios como bendición.<br/>',NULL,192103,1);
INSERT INTO stanza VALUES('S668','1','Dad gloria_y honra_al Redentor;<br/>Su gracia nos unió;<br/>Nos quiere ver frente a Su faz<br/>En dulce comunión.<br/>En dulce comunión.<br/>',NULL,192104,1);
INSERT INTO stanza VALUES('S668','2','A mutua edificación<br/>Nos llama el Señor;<br/>Hasta Su gloria heredar,<br/>//Unidos vamos hoy.//<br/>',NULL,192105,2);
INSERT INTO stanza VALUES('S668','3','El don que Cristo a todos dio,<br/>Gozamos en unión;<br/>Su gracia así ha de fluir<br/>//En ríos de amor.//<br/>',NULL,192106,3);
INSERT INTO stanza VALUES('S668','4','El gozo de uno, a todos es<br/>Un gozo sin igual;<br/>Sentimos una mutua paz<br/>//Que el mundo no nos da.//<br/>',NULL,192107,4);
INSERT INTO stanza VALUES('S668','5','Si nuestra comunión aquí<br/>Tan dulce en Cristo es,<br/>¿Qué éxtasis se gozará,<br/>//Estando frente a Él?//<br/>',NULL,192108,5);
INSERT INTO stanza VALUES('S669','1','Bendito es el cordón<br/>De_amor que nos unió;<br/>Es nuestra comunión aquí,<br/>La comunión de Dios.<br/>',NULL,192109,1);
INSERT INTO stanza VALUES('S669','2','A nuestro Padre Dios<br/>Oramos con fervor<br/>Lo que hay en nuestro corazón,<br/>En unidad y amor.<br/>',NULL,192110,2);
INSERT INTO stanza VALUES('S669','3','Las cargas y el pesar<br/>Nos place compartir;<br/>Frecuentes lágrimas se dan<br/>Al ver a otros sufrir.<br/>',NULL,192111,3);
INSERT INTO stanza VALUES('S669','4','Al separarnos hay<br/>Un interior dolor;<br/>Mas somos uno en corazón<br/>Y en cada reunión.<br/>',NULL,192112,4);
INSERT INTO stanza VALUES('S669','5','De penas y el pecar,<br/>Dios nos ha de librar;<br/>Amor y unidad habrá<br/>Por la eternidad.<br/>',NULL,192113,5);
INSERT INTO stanza VALUES('S670','1','¿Los has visto_en las ciudades,<br/>En el terreno local?<br/>Son los candeleros de oro,<br/>Donde Cristo encuentra_hogar.<br/>',NULL,192114,1);
INSERT INTO stanza VALUES('S670','chorus','Lo que quiere Dios: iglesias locales,<br/>Donde se ve la_unidad.<br/>Lo que quiere Dios: iglesias locales,<br/>Donde se ve la_unidad.<br/>',NULL,192115,2);
INSERT INTO stanza VALUES('S670','2','¿Los has visto en las reuniones,<br/>Levantando allí su voz?<br/>Cada hermano compartiendo<br/>Las riquezas del Señor.<br/>',NULL,192116,3);
INSERT INTO stanza VALUES('S670','3','¿Oyes mientras oran-leen<br/>La Palabra al inhalar?<br/>Oran, cantan, beben, fluyen<br/>El Señor al disfrutar.<br/>',NULL,192117,4);
INSERT INTO stanza VALUES('S670','4','¿Has oído como invocan<br/>Al decir: "Señor Jesús"?<br/>Dulce nombre que proclaman<br/>Con amor y gratitud.<br/>',NULL,192118,5);
INSERT INTO stanza VALUES('S670','5','¿Oyes tú sus aleluyas?<br/>Como fuertes truenos son:<br/>¡Aleluya! ¡Aleluya!<br/>¡Cristo al diablo ya venció!<br/>',NULL,192119,6);
INSERT INTO stanza VALUES('S670','6','¿Ven los santos emigrando?<br/>El mover es del Señor;<br/>Cada iglesia edificando<br/>Para que vuelva el Señor.<br/>',NULL,192120,7);
INSERT INTO stanza VALUES('S670','7','¿Ves que pronto viene Cristo<br/>Por la iglesia que Él compró?<br/>Él prepara, en las iglesias,<br/>Esa novia que Él deseó.<br/>',NULL,192121,8);
INSERT INTO stanza VALUES('S670','chorus','¡Qué gloriosa iglesia! Sin mancha alguna:<br/>Llena de gloria de Dios.<br/>¡Qué gloriosa iglesia! Sin mancha alguna:<br/>Llena de gloria de Dios.<br/>',NULL,192122,9);
INSERT INTO stanza VALUES('S671','1','¡Cuán hermosas y preciosas<br/>Tus iglesias son, Señor!<br/>Mi_alma añora hoy los atrios<br/>Donde moras Tú, oh Dios;<br/>Mi espíritu anhela,<br/>Y desea mi corazón<br/>Ver en todas las iglesias<br/>Más estrecha comunión.<br/>',NULL,192123,1);
INSERT INTO stanza VALUES('S671','2','Bienaventurado el hombre<br/>Cuya fuerza en Ti halló;<br/>En su corazón él tiene<br/>Las calzadas a Sion.<br/>En unión con las iglesias<br/>Él, confiado, cantará;<br/>Y las lágrimas del valle,<br/>Las convierte en manantial.<br/>',NULL,192124,2);
INSERT INTO stanza VALUES('S671','3','¡Más vale en Tu iglesia un día<br/>Que mil días fuera estar!<br/>Para el más pequeño miembro,<br/>Sol y escudo es Jehová.<br/>Todo bien con gracia y gloria,<br/>Nos otorga Él allí.<br/>Bendito el que en Tus iglesias<br/>More para siempre así.<br/>',NULL,192125,3);
INSERT INTO stanza VALUES('S672','1','Brillan las iglesias<br/>En la_oscuridad;<br/>Son el testimonio<br/>De Jesús y_están<br/>Hechas a la forma<br/>Del Espíritu;<br/>Su naturaleza<br/>De_oro_irradia luz.<br/>',NULL,192126,1);
INSERT INTO stanza VALUES('S672','chorus','Ved hoy las iglesias<br/>Irradiando luz,<br/>Expresando_a Cristo<br/>Por Su_Espíritu.<br/>',NULL,192127,2);
INSERT INTO stanza VALUES('S672','2','Cristo, el candelero:<br/>Dios en Él está;<br/>Espíritu se hizo,<br/>Es la realidad.<br/>Como candelero,<br/>El Espíritu<br/>Se ha duplicado<br/>En iglesias hoy.<br/>',NULL,192128,3);
INSERT INTO stanza VALUES('S672','3','Cuida las iglesias<br/>El Hijo en Su andar:<br/>Voz de muchas aguas,<br/>Fuego en Su mirar;<br/>En Su diestra, estrellas;<br/>Rostro como el sol;<br/>"No temáis, iglesias,<br/>El que vive soy".<br/>',NULL,192129,4);
INSERT INTO stanza VALUES('S672','4','¿Qué podrá apagarlas?<br/>¿Quién se opondrá?<br/>En oposiciones,<br/>Mas se aumentarán.<br/>Mientras más tinieblas,<br/>Más han de brillar.<br/>Son constituidas<br/>De vida eternal.<br/>',NULL,192130,5);
INSERT INTO stanza VALUES('S672','5','Pronto las iglesias<br/>Llegarán a ser<br/>La novia de Cristo,<br/>Su Jerusalén;<br/>Son un candelero<br/>Santo, universal,<br/>Que al Dios Triuno<br/>Siempre expresará.<br/>',NULL,192131,6);
INSERT INTO stanza VALUES('S672','chorus','Del cielo desciende,<br/>Todos la verán:<br/>Es Dios expresado<br/>Por la eternidad.<br/>',NULL,192132,7);
INSERT INTO stanza VALUES('S673','1','En la_iglesia local<br/>Con la unidad,<br/>Está el terreno<br/>Donde_hay vida_y bendición.<br/>(¡Aleluya!)<br/>De nuestro espíritu<br/>Surge_un clamor:<br/>¡Será echado el enemigo<br/>Por el reino del Señor!<br/>',NULL,192133,1);
INSERT INTO stanza VALUES('S674','1','Son todas las iglesias<br/>El Cuerpo del Señor,<br/>Su vivo testimonio,<br/>Y práctica_expresión.<br/>Son candeleros de oro<br/>Que en cada pueblo_están,<br/>Su_ejército valiente,<br/>Su Novia celestial.<br/>',NULL,192134,1);
INSERT INTO stanza VALUES('S674','chorus','¡Iglesias, iglesias!<br/>Sobre la tierra hoy;<br/>Cumple el anhelo de Tu_amor,<br/>Y haznos Tu habitación, Señor.<br/>',NULL,192135,2);
INSERT INTO stanza VALUES('S674','2','Sean grandes o pequeñas<br/>Son todas del Señor;<br/>Son tan imprecindibles,<br/>Vital es su porción.<br/>Aumenta Tus iglesias,<br/>Deseamos cooperar<br/>En comunión sincera,<br/>Y en oración cargar.<br/>',NULL,192136,3);
INSERT INTO stanza VALUES('S674','3','Contemplan hoy la tierra<br/>Los ojos del Señor;<br/>Ardientes, escudriñan<br/>A cada corazón.<br/>Es su intención genuina<br/>Muchas iglesias ver,<br/>En un acuerdo unidas<br/>Para expresarlo a Él.<br/>',NULL,192137,4);
INSERT INTO stanza VALUES('S674','4','Se acerca la venida<br/>Del Rey en Su esplendor;<br/>Por Sus iglesias viene<br/>Do suena Su loor.<br/>Ven, toma las primicias,<br/>La siega cerca está,<br/>Oh, llévanos al trono<br/>Contigo a reinar.<br/>',NULL,192138,5);
INSERT INTO stanza VALUES('S675','1','¡Qué fervientes hoy estamos!<br/>Nuestro_espíritu tocamos<br/>Para realizar Tu_eterno<br/>Propósito.<br/>Sobre cada localidad,<br/>Se ve nuestra unidad:<br/>Muchos miembros, mas un Cuerpo;<br/>Cabeza_es Él.<br/>',NULL,192139,1);
INSERT INTO stanza VALUES('S675','chorus','¡Cristo_y la_iglesia en<br/>Cada localidad!<br/>Cristo_y la_iglesia<br/>Son nuestra realidad.<br/>¡Aleluya, aleluya!<br/>Nuestras vidas Tuyas son<br/>Para la_edificación hoy<br/>De Tu Cuerpo en amor.<br/>',NULL,192140,2);
INSERT INTO stanza VALUES('S675','2','Respiramos, respiramos,<br/>Vida nueva ihnalamos;<br/>Nos transformas de lo viejo a<br/>Lo nuevo hoy;<br/>Exhalamos vieja vida,<br/>Inhalamos vida nueva;<br/>Ihnalando de la vida,<br/>Inhalamos a Jesús.<br/>',NULL,192141,3);
INSERT INTO stanza VALUES('S676','1','Remueve de mi corazón.<br/>Los velos, oh Señor;<br/>Y dame más clara visión<br/>De Tu recobro hoy.<br/>De Tu recobro hoy,<br/>De Tu recobro hoy,<br/>Y dame más clara visión<br/>De Tu recobro hoy.<br/>',NULL,192142,1);
INSERT INTO stanza VALUES('S676','2','Percibo por revelación<br/>El gran poder de Dios;<br/>Así por la resurrección<br/>La iglesia es mi porción.<br/>',NULL,192143,2);
INSERT INTO stanza VALUES('S676','3','Este poder me liberó<br/>De mundanalidad;<br/>Entrada a la iglesia local<br/>Este poder me da.<br/>',NULL,192144,3);
INSERT INTO stanza VALUES('S676','4','Ya en la iglesia estando yo,<br/>Te tomo, mi Señor;<br/>Mi ego hoy menguando está.<br/>Yo soy para el Señor.<br/>',NULL,192145,4);
INSERT INTO stanza VALUES('S676','5','Tú, mi persona debes ser,<br/>Contigo yo morí;<br/>Restauras mi hombre interior,<br/>Y habitas hoy en mí.<br/>',NULL,192146,5);
INSERT INTO stanza VALUES('S676','6','Si niegan Tus miembros el yo<br/>Tu Cuerpo exhibirán;<br/>Y si de Ti disfrutan hoy<br/>El nuevo hombre saldrá.<br/>',NULL,192147,6);
INSERT INTO stanza VALUES('S676','7','La iglesia el nuevo hombre es,<br/>Te expresa en la ciudad;<br/>El Cuerpo Tu Persona así<br/>Ha de manifestar.<br/>',NULL,192148,7);
INSERT INTO stanza VALUES('S676','note','**Nota: Para cantar, se repite la última línea de cada estrofa dos veces, seguido de las dos últimas líneas de cada estrofa, como indicado en la estrofa #1.**<br/>',NULL,192149,8);
INSERT INTO stanza VALUES('S677','1','Nuestro Pastor admirable,<br/>Cristo Jesús, nos sacó<br/>De_aquel redil a los pastos,<br/>Y Sus riquezas nos dio.<br/>',NULL,192150,1);
INSERT INTO stanza VALUES('S677','chorus','¡Gloriosa iglesia!<br/>¡Rico,_abundante caudal!<br/>Aquí_en unión habitando,<br/>Dios manda vida_eternal.<br/>',NULL,192151,2);
INSERT INTO stanza VALUES('S677','2','Nos encontró en divisiones,<br/>Hambrientos, casi al morir;<br/>A buena tierra nos trajo,<br/>Mi espíritu hizo vivir.<br/>',NULL,192152,3);
INSERT INTO stanza VALUES('S677','3','Nuestro Jesús es el pasto,<br/>Nuestra comida también;<br/>Siempre alimenta el rebaño,<br/>Al congregarnos con Él.<br/>',NULL,192153,4);
INSERT INTO stanza VALUES('S677','4','En este monte habitamos<br/>Bajo el rocio de Dios;<br/>Fluye la vida en la fuente,<br/>Aguas de gran bendición.<br/>',NULL,192154,5);
INSERT INTO stanza VALUES('S677','5','Es nuestro Cristo el descanso,<br/>Nada tememos aquí;<br/>A Sus ovejas Él cuida<br/>Con Su presencia gentil.<br/>',NULL,192155,6);
INSERT INTO stanza VALUES('S678','1','Alabad cantando al Señor Jesús,<br/>Ahora_Él habita en Jerusalén.<br/>Declaremos hoy las obras del Señor,<br/>¡Dios con el hombre_en plena comunión!<br/>',NULL,192156,1);
INSERT INTO stanza VALUES('S678','chorus','La salvación nos viene de Sión;<br/>Ha cautivado la cautividad;<br/>¡Oh, cuánto gozo tiene el corazón!<br/>¡Oh, cuánto gozo tiene el corazón!<br/>',NULL,192157,2);
INSERT INTO stanza VALUES('S678','2','En la Ciudad Santa cantos entonad,<br/>Al Rey de reyes, gloria y majestad;<br/>Alaban los santos, cantan á una voz,<br/>En Sión se escucha grande aclamación.<br/>',NULL,192158,3);
INSERT INTO stanza VALUES('S678','chorus','Se mueve Él en la iglesia local,<br/>Nos satisface, es nuestra porción;<br/>¡Oh, cuán gloriosa, nuestra heredad!<br/>¡Oh, cuán gloriosa, nuestra heredad!<br/>',NULL,192159,4);
INSERT INTO stanza VALUES('S678','3','En Su santo templo, ¿quién podrá morar?<br/>¿Quién en Su santo monte adorará?<br/>Los que lo anhelamos con el corazón.<br/>Los que Su faz buscamos con fervor.<br/>',NULL,192160,5);
INSERT INTO stanza VALUES('S678','chorus','Su faz radiante procuremos hoy,<br/>Abre la puerta, ensancha el corazón;<br/>Llegue reinando e inunde nuestro ser,<br/>Llegue reinando e inunde nuestro ser.<br/>',NULL,192161,6);
INSERT INTO stanza VALUES('S678','4','Con los santos hoy está Su habitación,<br/>¡Emanuel! ¡Qué grande bendición!<br/>Todo ha consumado, mortales acudid,<br/>Cristo y la iglesia unidos hasta el fin.<br/>',NULL,192162,7);
INSERT INTO stanza VALUES('S678','chorus','¡Ciudades de la tierra despertad!<br/>¡Abrid las puertas y el Rey entrará!<br/>¡Canta alabanzas, Cristo reina ya!<br/>¡Canta alabanzas, Cristo reina ya!<br/>',NULL,192163,8);
INSERT INTO stanza VALUES('S679','1','Rodead a Sion y miradla,<br/>Rodeadla llenos de_amor;<br/>Contad hoy todas sus torres,<br/>Andando por su alrededor,<br/>Andando por su alrededor.<br/>',NULL,192164,1);
INSERT INTO stanza VALUES('S679','2','Oh, contemplad sus baluartes,<br/>Sus muros hoy contemplad;<br/>Oh, contemplad sus baluartes<br/>Y en sus palacios andad,<br/>Y en sus palacios andad.<br/>',NULL,192165,2);
INSERT INTO stanza VALUES('S679','3','¡Cuán elevada, cuán bella!<br/>¡Gran gozo a la tierra es!<br/>¡Cuán elevada, cuán bella!<br/>Es Sion la ciudad del gran Rey,<br/>Es Sion la ciudad del gran Rey.<br/>',NULL,192166,3);
INSERT INTO stanza VALUES('S679','4','Oh, desde Sion brota un río,<br/>Muy hondo y ancho en verdad;<br/>Con sus corrientes el río<br/>Alegra de Dios la ciudad,<br/>Alegra de Dios la ciudad.<br/>',NULL,192167,4);
INSERT INTO stanza VALUES('S679','5','En Sion te espera alabanzas,<br/>Loor te espera, Señor;<br/>En Sion te espera alabanzas,<br/>Pues Sion está llena de Dios,<br/>Pues Sion está llena de Dios.<br/>',NULL,192168,5);
INSERT INTO stanza VALUES('S679','6','En Sión, Señor, eres grande<br/>Y digno de admiración;<br/>En la ciudad elevada<br/>Se canta alabanzas a Dios,<br/>Se canta alabanzas a Dios.<br/>',NULL,192169,6);
INSERT INTO stanza VALUES('S679','7','En Sion, Señor, te bendigan,<br/>Es Tu santa habitación;<br/>En Sion, Señor, te bendigan,<br/>Con toda alabanza y loor,<br/>Con toda alabanza y loor.<br/>',NULL,192170,7);
INSERT INTO stanza VALUES('S679','8','En Sion, que Dios os bendiga,<br/>En Sion, aún más y más;<br/>En Sion, que Dios os bendiga<br/>A todos con vida eternal,<br/>A todos con vida eternal.<br/>',NULL,192171,8);
INSERT INTO stanza VALUES('S679','9','¡Mirad, oh cuán delicioso<br/>Con los hermanos estar!<br/>¡Mirad, oh cuán delicioso<br/>En tal armonía morar,<br/>En tal armonía morar!<br/>',NULL,192172,9);
INSERT INTO stanza VALUES('S679','10','Oh, dilo a todos los hombres,<br/>Oh, dilo hoy por doquier,<br/>Que el Espíritu llama<br/>Y dice con la Novia: "Ven",<br/>Y dice con la Novia: "Ven".<br/>',NULL,192173,10);
INSERT INTO stanza VALUES('S680','1','Dejamos por Jesús la ley,<br/>En Él ponemos nuestra fe;<br/>Su gloria hace comprender<br/>Que el todo Cristo es.<br/>',NULL,192174,1);
INSERT INTO stanza VALUES('S680','chorus','¡El todo Cristo es!<br/>¡El todo Cristo es!<br/>Su gloria hace comprender<br/>¡Que el todo Cristo es!<br/>',NULL,192175,2);
INSERT INTO stanza VALUES('S680','2','Nos trajo Cristo a disfrutar<br/>Con nuestro Dios Su dulce hogar;<br/>¡Oh aleluya! ¿Quién dirá?<br/>Cuán dulce es Su hogar!<br/>',NULL,192176,3);
INSERT INTO stanza VALUES('S680','chorus','¡Cuán dulce es Su hogar!<br/>¡Cuán dulce es Su hogar!<br/>¡Oh, aleluya! ¿Quién dirá?<br/>¡Cuán dulce es Su hogar!<br/>',NULL,192177,4);
INSERT INTO stanza VALUES('S680','3','Su casa se hace la ciudad,<br/>¡Que a las naciones gozo da!<br/>En donde Dios puede reinar:<br/>El monte de Sion.<br/>',NULL,192178,5);
INSERT INTO stanza VALUES('S680','chorus','El monte de Sión,<br/>El monte de Sión,<br/>En donde Dios puede reinar:<br/>El monte de Sión.<br/>',NULL,192179,6);
INSERT INTO stanza VALUES('S680','4','La tierra Cristo ganará,<br/>Su reino se establecerá,<br/>Y desde Sion prorrumpirá<br/>El gozo del Señor.<br/>',NULL,192180,7);
INSERT INTO stanza VALUES('S680','chorus','El gozo del Señor,<br/>El gozo del Señor,<br/>Y desde Sión prorrumpirá<br/>El gozo del Señor.<br/>',NULL,192181,8);
INSERT INTO stanza VALUES('S680','5','Por Cristo Dios tendrá Su hogar,<br/>Que crecerá en la ciudad,<br/>La tierra así conquistará,<br/>Nos damos a Su plan.<br/>',NULL,192182,9);
INSERT INTO stanza VALUES('S680','chorus','Nos damos a Su plan,<br/>Nos damos a Su plan,<br/>La tierra así conquistará,<br/>Nos damos a Su plan.<br/>',NULL,192183,10);
INSERT INTO stanza VALUES('S681','1','Conocerte como el Cuerpo<br/>Hoy me urge, mi Señor;<br/>Que te vea en Tus miembros,<br/>Es mi_anhelo y_oración.<br/>No tan sólo verte como<br/>Mi cabeza_individual,<br/>Sino como_el encarnado<br/>Cristo que_en el Cuerpo_está.<br/>',NULL,192184,1);
INSERT INTO stanza VALUES('S681','2','Por los siglos Tus amados<br/>Han buscado realidad<br/>En lo alto_o en lo_interno,<br/>Muy sedientos de Tu faz;<br/>Mas el Cristo ascendido,<br/>con Su cuerpo uno es;<br/>Y el Cristo en nosotros,<br/>En el Cuerpo hoy se ve.<br/>',NULL,192185,2);
INSERT INTO stanza VALUES('S681','3','Tiendo a errar por mis conceptos,<br/>Que en lo alto sólo estás;<br/>En mí mismo yo te busco,<br/>Sin tocar Tu realidad.<br/>Cuánto necesito hallarte<br/>En Tus miembros para ver<br/>A Dios manifiesto en carne<br/>Quien se da a conocer.<br/>',NULL,192186,3);
INSERT INTO stanza VALUES('S681','4','¡Oh, detén mi independencia!<br/>A Tu Cuerpo hazme acudir;<br/>Quiero más que luz del cielo:<br/>La iglesia percibir.<br/>Haznos piedras para el templo,<br/>No más barro sin valor;<br/>Y que así, edificados,<br/>Hoy seamos Tu expresión.<br/>',NULL,192187,4);
INSERT INTO stanza VALUES('S682','1','Es la iglesia tan gloriosa, parte de_ella somos ya;<br/>¡Qué felices, el Señor ya nos unió!<br/>En el universo_un Cuerpo hay y somos parte de_él,<br/>¡Aleluya, el Señor ya nos unió!<br/>',NULL,192188,1);
INSERT INTO stanza VALUES('S682','chorus','¡Aleluya, por el Cuerpo!<br/>¡Somos miembros en el Cuerpo!<br/>¡Totalmente para_el Cuerpo!<br/>¡Aleluya, el Señor ya nos unió!<br/>',NULL,192189,2);
INSERT INTO stanza VALUES('S682','2','No cristianos solitarios, mas Su Cuerpo singular,<br/>Ahora Dios lo quiere para Su expresión;<br/>No iglesias separadas, mas un Cuerpo en unidad,<br/>¡Aleluya, en el Cuerpo estamos ya!<br/>',NULL,192190,3);
INSERT INTO stanza VALUES('S682','chorus','¡Aleluya, por el Cuerpo!<br/>¡Satanás le teme al Cuerpo!<br/>¡Victoriosos en el Cuerpo!<br/>¡Aleluya, en el Cuerpo estamos ya!<br/>',NULL,192191,4);
INSERT INTO stanza VALUES('S682','3','Siete candeleros de oro, de sustancia divinal,<br/>Nada natural el Cuerpo aceptará;<br/>Al participar de Dios el candelero brillará,<br/>¡Aleluya, qué brillante el Cuerpo está!<br/>',NULL,192192,5);
INSERT INTO stanza VALUES('S682','chorus','¡Aleluya, por el Cuerpo!<br/>¡Candeleros de Su Cuerpo!<br/>¡Brilla el oro en el Cuerpo!<br/>¡Aleluya, qué brillante el Cuerpo está!<br/>',NULL,192193,6);
INSERT INTO stanza VALUES('S682','4','¿Cómo vamos a expresar la unidad y así brillar?<br/>¡Aleluya, a Jesús hay que comer!<br/>Cristo el árbol de la vida, el maná y la cena es,<br/>¡Aleluya, cada día a Él comer!<br/>',NULL,192194,7);
INSERT INTO stanza VALUES('S682','chorus','¡Somos uno al comerlo!<br/>¡Y divinos al comerlo!<br/>¡Brillaremos al comerlo!<br/>¡Aleluya, a Jesús hay que comer!<br/>',NULL,192195,8);
INSERT INTO stanza VALUES('S683','1','Nuestro Señor, que es sin igual,<br/>Vino_a morir y vida dar;<br/>Viene_otra vez para_encontrar<br/>Su_hermosa novia_en gloria.<br/>',NULL,192196,1);
INSERT INTO stanza VALUES('S683','chorus','¡Jesús! Pronto_has de volver,<br/>¡Jesús! como Novio fiel;<br/>¡Jesús! Deseamos ser<br/>Tu novia para siempre.<br/>',NULL,192197,2);
INSERT INTO stanza VALUES('S683','2','Lo que el Señor desea hoy<br/>No sólo es darnos redención;<br/>Anhela ver consagración<br/>Para obtener Su novia.<br/>',NULL,192198,3);
INSERT INTO stanza VALUES('S683','3','Cual vírgenes debemos ser,<br/>Sólo al Novio ansiando ver,<br/>Para que cuando venga Él,<br/>Pueda encontrar Su novia.<br/>',NULL,192199,4);
INSERT INTO stanza VALUES('S683','4','¿Por qué al marchito mundo amar?<br/>La perla quiere Cristo hallar;<br/>Si sólo amamos ver Su faz,<br/>Él volverá por siempre.<br/>',NULL,192200,5);
INSERT INTO stanza VALUES('S684','1','La iglesia_es el anhelo<br/>De Cristo_y Su placer;<br/>Su_acción y Su palabra<br/>Concentra_en ella fiel.<br/>Su_amor allí_establece,<br/>Nada lo detendrá;<br/>Antes que_hubiera tierra<br/>Ella_era Su pensar.<br/>',NULL,192201,1);
INSERT INTO stanza VALUES('S684','2','Él meditaba en ella<br/>Antes de la creación;<br/>Por todos sus detalles<br/>Sentía atracción.<br/>Creó el universo,<br/>Mas no se reveló<br/>Su escondido anhelo<br/>La Novia que Él soñó.<br/>',NULL,192202,2);
INSERT INTO stanza VALUES('S684','3','Así que se propuso<br/>Su complemento ver;<br/>Esta intención bendita<br/>Eternamente es.<br/>Aunque vino el pecado y<br/>Del hombre se burló,<br/>Dios no abandonaría<br/>La novia que anheló.<br/>',NULL,192203,3);
INSERT INTO stanza VALUES('S684','4','¡Oh, qué misericordia!<br/>Su amor se desplegó;<br/>Él con sabiduria<br/>Y gracia la buscó.<br/>Su amor para ganarla,<br/>Dios sólo entenderá;<br/>Por ella dio Su vida,<br/>Fragancia eternal.<br/>',NULL,192204,4);
INSERT INTO stanza VALUES('S684','5','A ella Él se acerca<br/>Hoy en resurrección;<br/>En gloria se aparece<br/>Con tierna afección.<br/>Al contemplar el Novio<br/>Le inunda el corazón<br/>De gloria hasta que sea<br/>La Novia que Él soñó.<br/>',NULL,192205,5);
INSERT INTO stanza VALUES('S685','1','Dios planeó un nuevo_hombre_hacer,<br/>Y nos redimió para_uno ser;<br/>Nos compró de cada nación,<br/>Y de toda tribu nos llamó.<br/>En la tierra, Su expresión,<br/>Hoy revela Su valor;<br/>Dios planeó un nuevo hombre hacer,<br/>Y nos redimió para_uno ser.<br/>',NULL,192206,1);
INSERT INTO stanza VALUES('S685','2','Las ordenanzas Él clavó<br/>En la cruz, haciendo uno de dos;<br/>Dios con Él nos reconcilió;<br/>La serpiente, en su cabeza hirió.<br/>Dios derriba la pared<br/>Cuando clamamos a Él;<br/>Las ordenanzas Él clavó<br/>En la cruz, haciendo uno de dos.<br/>',NULL,192207,2);
INSERT INTO stanza VALUES('S685','3','Tu Persona tomamos hoy<br/>Para en un acuerdo estar, Señor;<br/>Nuestro yo hay que abandonar<br/>Para el Cristo-Cuerpo disfrutar.<br/>El nuevo hombre en Cristo está,<br/>Y la tierra ha de tomar;<br/>Tu Persona tomamos hoy<br/>Para en un acuerdo estar, Señor.<br/>',NULL,192208,3);
INSERT INTO stanza VALUES('S686','1','¡Oh, aleluya! Dios formó<br/>Al hombre_en la creación,<br/>Para_expresar Su_autoridad,<br/>Y_así la tierra sojuzgar.<br/>¡Qué gozo tengo yo,<br/>En Su recobro hoy!<br/>¡Oh, aleluya, soy Su_expresión!<br/>',NULL,192209,1);
INSERT INTO stanza VALUES('S686','2','¡Oh, aleluya! Mi Señor<br/>Por mí Su vida dio.<br/>Hoy vive en mi espíritu,<br/>Me da Su vida en plenitud.<br/>Hombre supremo y fiel,<br/>Mi todo en todo es Él,<br/>¡Oh, aleluya, vive en mi ser!<br/>',NULL,192210,2);
INSERT INTO stanza VALUES('S686','3','¡Oh, aleluya! Me hizo Dios<br/>El centro en Su creación.<br/>Su imagen llevo en dignidad,<br/>Para ejercer Su autoridad.<br/>¡Qué bueno: un hombre ser!<br/>¡Un hombre para Él!<br/>¡Oh, aleluya, un hombre fiel!<br/>',NULL,192211,3);
INSERT INTO stanza VALUES('S686','4','Un nuevo hombre, ¡gloria a Dios!<br/>Ya lo logró el Señor.<br/>Un hombre colectivo que<br/>Por Él edificado es.<br/>Un hombre sin rival,<br/>Que reina sobre el mal<br/>La iglesia y Cristo: hombre sin par.<br/>',NULL,192212,4);
INSERT INTO stanza VALUES('S687','1','Muertos en pecados tú y yo,<br/>En el mundo lleno de maldad;<br/>Pero_en Cristo, Dios nos avivó,<br/>Y_en lugares celestiales nos sentó.<br/>',NULL,192213,1);
INSERT INTO stanza VALUES('S687','chorus','Cristo une_a los hermanos,<br/>Véanlos uno_en el Señor.<br/>Su amor nos entreteje juntos<br/>A la estatura de Su plenitud.<br/>',NULL,192214,2);
INSERT INTO stanza VALUES('S687','2','Con los santos hay que comprender<br/>Toda la gran dimensión de Dios;<br/>Conociendo a Cristo y Su amor,<br/>Nos llenamos a la plenitud de Dios.<br/>',NULL,192215,3);
INSERT INTO stanza VALUES('S687','3','Dios Su plan nos dio a conocer,<br/>El misterio es visible ya;<br/>Cristo con la iglesia uno es<br/>Para avergonzar la astucia de Satán.<br/>',NULL,192216,4);
INSERT INTO stanza VALUES('S687','4','Al Dios Padre es nuestra oración:<br/>Fortalece nuestro hombre interior,<br/>Haz Tu hogar en nuestro corazón;<br/>Por Tu plan arráiganos en Tu amor.<br/>',NULL,192217,5);
INSERT INTO stanza VALUES('S687','5','Cada miembro debe proveer<br/>Cristo para el Cuerpo concertar;<br/>Por la actividad de cada cual,<br/>En amor Su Cuerpo edificará.<br/>',NULL,192218,6);
INSERT INTO stanza VALUES('S687','6','Cumpliremos el deseo de Dios,<br/>Como el nuevo hombre de Su plan;<br/>En la iglesia gloria sea a Él,<br/>Y en Jesucristo para siempre, amén.<br/>',NULL,192219,7);
INSERT INTO stanza VALUES('S688','1','Hallamos hogar<br/>Al la_iglesia encontrar;<br/>Con los santos hay gozo y paz;<br/>La vida_aquí es<br/>Cristo en nuestro ser;<br/>¡Aleluya, tenemos hogar!<br/>',NULL,192220,1);
INSERT INTO stanza VALUES('S688','chorus','¡Oh, qué dulce_hogar!<br/>Encontramos la_iglesia sin par.<br/>Por siempre jamás<br/>Hemos de alabar:<br/>"¡Aleluya, Cristo y la_iglesia!".<br/>',NULL,192221,2);
INSERT INTO stanza VALUES('S688','2','Aqui nuestro Dios<br/>Su reposo halló;<br/>¡Su hogar es nuestro corazón!<br/>Gozoso Él está,<br/>Fuera queda Satán,<br/>Y Su gloria despliega el Señor.<br/>',NULL,192222,3);
INSERT INTO stanza VALUES('S688','chorus','¡Dios tiene un hogar!<br/>¡Ha encontrado Su iglesia sin par.<br/>Por siempre jamás<br/>Hemos de alabar:<br/>"¡Aleluya, Cristo y la_iglesia!".<br/>',NULL,192223,4);
INSERT INTO stanza VALUES('S689','1','Sediento en la Babilonia estaba yo,<br/>Do nada me pudo satisfacer;<br/>Pero un día vine_a la_iglesia local,<br/>Y fuentes de_agua viva encontré.<br/>',NULL,192224,1);
INSERT INTO stanza VALUES('S689','chorus','Bebo de la fuente de_agua viva,<br/>Muy contento estoy,<br/>Y satisfecho hoy;<br/>Bebo de la fuente de_agua viva,<br/>Maravillosa es su provisión.<br/>',NULL,192225,2);
INSERT INTO stanza VALUES('S689','2','¡Qué dulce el agua viva que viene de Dios<br/>Fluyendo dentro y fuera de mi ser!<br/>Por fin yo he hallado el lugar que ansié,<br/>Donde abundante vida encontré.<br/>',NULL,192226,3);
INSERT INTO stanza VALUES('S689','3','Hermano, ¿no vendrás a la iglesia local?<br/>Fluyendo aquí la fuente siempre está;<br/>Te quiere a la iglesia el buen Pastor guiar,<br/>La sed en tu espíritu saciar.<br/>',NULL,192227,4);
INSERT INTO stanza VALUES('S690','1','Escucha al errante que<br/>Carente se_encontró;<br/>Y ponle_oído_a su canción<br/>Sus huella sigue hoy.<br/>',NULL,192228,1);
INSERT INTO stanza VALUES('S690','chorus','¡Gloria a Dios! ¡Gloria a Dios!<br/>¡Gloria a Dios! ¡Aleluya, aleluya!<br/>¡Gloria a Dios! ¡Gloria a Dios!<br/>¡El mismo no seré!<br/>',NULL,192229,2);
INSERT INTO stanza VALUES('S690','2','Busca el errante el placer<br/>Que este mundo da;<br/>Mas si lo halla ha de saber<br/>Que es pura vanidad.<br/>',NULL,192230,3);
INSERT INTO stanza VALUES('S690','3','Muchos castillos levanté<br/>Para mi ego yo;<br/>Mas, gloria á Dios, Él los tumbó<br/>Y lo mejor me dio.<br/>',NULL,192231,4);
INSERT INTO stanza VALUES('S690','4','Confuso y solo estaba yo,<br/>Mucha vergüenza hallé;<br/>Mas hoy en la iglesia local<br/>El mismo no seré.<br/>',NULL,192232,5);
INSERT INTO stanza VALUES('S690','5','¡Hoy soy un miembro tan feliz<br/>En la iglesia local!<br/>Aquel errante que encontró<br/>Descanso y dulce hogar.<br/>',NULL,192233,6);
INSERT INTO stanza VALUES('S690','6','Un individualista fui,<br/>Como una isla yo;<br/>Mas con los santos en Su amor<br/>Me edifica Dios.<br/>',NULL,192234,7);
INSERT INTO stanza VALUES('S690','7','Siento una grande atracción<br/>A estar en comunión;<br/>He aprendido a recibir<br/>De Cristo en la reunión.<br/>',NULL,192235,8);
INSERT INTO stanza VALUES('S690','8','Ya he cesado de vagar<br/>¡La iglesia yo encontré!<br/>Muy grande es mi felicidad<br/>¡En Dios descansó hallé!<br/>',NULL,192236,9);
INSERT INTO stanza VALUES('S691','1','En la_iglesia se_oye el sonido de la vida,<br/>Y el gozo del Señor se ve en cada cual;<br/>Babilonia y el mundo_en vano hoy nos llaman.<br/>Nuestro_hogar es Cristo, nuestro Canáan.<br/>',NULL,192237,1);
INSERT INTO stanza VALUES('S691','chorus','La_iglesia se practica<br/>En el terreno local;<br/>Los santos "iglesiando",<br/>¡Aleluyas! darán;<br/>Con nuestro_espíritu_avivado,<br/>La iglesia_alabará<br/>A Jesucristo, nuestro Canáan.<br/>',NULL,192238,2);
INSERT INTO stanza VALUES('S691','2','Lejos del transfondo de los dones y enseñanzas,<br/>Y aún más lejos de todo lo mundanal;<br/>El amor de Jesucristo nuestro ser hoy llena;<br/>Nada nos desplaza de "Canaán".<br/>',NULL,192239,3);
INSERT INTO stanza VALUES('S691','3','"Sobre esta roca edificaré Mi iglesia",<br/>Vemos la edificación de Su deseo y plan;<br/>Colocando miembros en Su Cuerpo como Él quiso,<br/>Edifica Cristo, nuestro Canaán.<br/>',NULL,192240,4);
INSERT INTO stanza VALUES('S691','4','Su recobro está avanzando por el mundo entero;<br/>Las iglesias, al  Señor este mandato dan:<br/>"Apresura el día en que el orar-leer resuene,<br/>Alabando a Cristo, nuestro Canaán".<br/>',NULL,192241,5);
INSERT INTO stanza VALUES('S692','1','¡Oh, qué_espléndida_es la iglesia como_el huerto del Señor!<br/>Él nos trajo_aquí para experimentar<br/>A_este Cristo disfrutable con los santos en unión,<br/>Quien es fresco, disponible,_y sin igual.<br/>',NULL,192242,1);
INSERT INTO stanza VALUES('S692','chorus','¡Qué contento en Su huerto_estoy,<br/>Donde por Su gracia crezco hoy!<br/>Del árbol de la vida puedo_a diario_aquí comer<br/>Y del río de_agua viva_es mi beber.<br/>',NULL,192243,2);
INSERT INTO stanza VALUES('S692','2','No es escuela ni una fábrica o capilla celestial,<br/>Sino un huerto en que el Señor puede sembrar.<br/>Pues, por eso, Él nos hizo hoy Su huerto encantador,<br/>Donde en vida Él nos puede cultivar.<br/>',NULL,192244,3);
INSERT INTO stanza VALUES('S692','3','En la vida de la iglesia hay un árbol para ti<br/>Con el fruto de la vida a granel.<br/>No te enreden tus conceptos, de ese árbol come, así;<br/>Toma a Jesús, ¡es dulce cada vez!<br/>',NULL,192245,4);
INSERT INTO stanza VALUES('S692','4','Con el árbol fluye el agua: Dios en Cristo a nuestro ser,<br/>Apagando toda nuestra sequedad.<br/>¡Aleluya por la vida que nos hace así crecer,<br/>Por el agua que el Espíritu nos da!<br/>',NULL,192246,5);
INSERT INTO stanza VALUES('S692','5','¿No te sientes satisfecho que el Señor te trajo aquí,<br/>Donde fluyen las riquezas de Su ser?<br/>Sé contento y en tu espíritu disfruta de Él allí<br/>Para que Su huerto pueda florecer.<br/>',NULL,192247,6);
INSERT INTO stanza VALUES('S693','1','Nunca antes yo soñé<br/>Un lugar así_encontrar;<br/>El lamento aquí cesó,<br/>Y con gozo_es el cantar.<br/>Quien jamás gustó_entonar,<br/>Hoy disfruta elevar<br/>Con los santos tal canción,<br/>Alabando sin cesar.<br/>',NULL,192248,1);
INSERT INTO stanza VALUES('S693','2','Gira el mundo alrededor<br/>Como siempre rotará.<br/>Miles buscan vanidad<br/>Sin saber que hay algo más.<br/>Yo fui tal, mas ya no soy;<br/>Ya que Su piedad me halló;<br/>Dando gracias digo hoy:<br/>"¡Mi familia es la de Dios!".<br/>',NULL,192249,2);
INSERT INTO stanza VALUES('S693','3','¡Qué deleite es conocer<br/>Esta gracia interior,<br/>Subjetiva y real,<br/>Que se goza en la reunión!<br/>Es Jesús mi vida aquí<br/>Y mi plena realidad.<br/>Hoy te alabo, mi Señor,<br/>Por tenerme en Tu hogar.<br/>',NULL,192250,3);
INSERT INTO stanza VALUES('S693','4','Esta era acabará<br/>Y Tu reino entrará;<br/>Gana Tu pueblo, Señor,<br/>Tu morada y Tu hogar.<br/>Todo diste Tú por mí;<br/>Por Ti todo dejo yo.<br/>A Tu iglesia todo doy<br/>Para Tu satisfacción.<br/>',NULL,192251,4);
INSERT INTO stanza VALUES('S694','1','Más profundo en la cruz de Cristo,<br/>Más profundo iré;<br/>Muerte y vida siempre andan juntas,<br/>Más profundo ve.<br/>Oh, más profundo ve,<br/>Renueva nuestro ser;<br/>Es nuestra oración,<br/>Más profundo ve, Señor.<br/>',NULL,192252,1);
INSERT INTO stanza VALUES('S694','2','Aún más alto, llévanos más alto<br/>En Tu vida hoy;<br/>Por Tu vida llévanos más alto,<br/>Hazlo, oh Señor.<br/>Por más transformación<br/>Es nuestra oración;<br/>Oh, fluye en nuestro ser;<br/>Haznos Tu vida aprehender.<br/>',NULL,192253,2);
INSERT INTO stanza VALUES('S694','3','Crece, crece, en nosotros crece<br/>Cada día más.<br/>En nuestro vivir hoy Cristo fluye:<br/>Operando está.<br/>Oh, crece más, Señor,<br/>Es nuestra oración.<br/>No basta el conocer,<br/>Sino en vida crecer.<br/>',NULL,192254,3);
INSERT INTO stanza VALUES('S694','4','Hoy nueustro vivir es Cristo mismo,<br/>Práctico es Él;<br/>En asuntos grandes y pequeños:<br/>En todo Él se ve.<br/>A cristo vive hoy,<br/>Sé, tú, Su expresión;<br/>Su nombre hay que invocar,<br/>Y te debes consagrar.<br/>',NULL,192255,4);
INSERT INTO stanza VALUES('S694','5','¡Cristo mismo es nuestra persona!<br/>Vive en nuestro ser.<br/>Nuestros gestos, gustos y acciones:<br/>¡Nuestro todo es Él!<br/>Nuestra persona, Tú,<br/>En vida y actitud;<br/>Nuestra persona sé,<br/>Haz Tu hogar en nuestro ser.<br/>',NULL,192256,5);
INSERT INTO stanza VALUES('S694','6','Las iglesias, hoy en las iglesias<br/>Vemos el fluir;<br/>Más y más esta creciendo Cristo<br/>En nuestro vivir.<br/>Hoy las iglesias son<br/>El Cristo en Su expresión;<br/>Por esto hay que menguar,<br/>Para Su cuerpo agrandar.<br/>',NULL,192257,6);
INSERT INTO stanza VALUES('S694','7','La edificación de la iglesia<br/>Así se verá;<br/>Si a Cristo experimentamos,<br/>Se edificará.<br/>Oh, edifícanos,<br/>Creciendo en lo interior;<br/>Así hemos de ser<br/>La Nueva Jerusalén.<br/>',NULL,192258,7);
INSERT INTO stanza VALUES('S694','8','Viene, viene, Cristo pronto viene,<br/>A Su novia hallar,<br/>En Su iglesia hoy nos preparamos<br/>Para en gloria entrar.<br/>"Ven pronto, oh, Señor",<br/>Escucha tal clamor;<br/>La gloria Tuya es;<br/>Vuelve, pronto, ¡sí, amén!<br/>',NULL,192259,8);
INSERT INTO stanza VALUES('S695','1','En El Cantar de Cantares<br/>Podemos apreciar<br/>La vida y edificación:<br/>Cristo y Su novia real.<br/>Cristo y Su novia real.<br/>',NULL,192260,1);
INSERT INTO stanza VALUES('S695','2','Cual yegua la amada es,<br/>Muy fuerte es su amor;<br/>Mas este amor es natural<br/>//Y hala el mundo atróz.//<br/>',NULL,192261,2);
INSERT INTO stanza VALUES('S695','3','Sus ojos, de paloma son,<br/>Cambió ya su pensar;<br/>Hoy nada se compara a Él<br/>//¡Su Amado es sin igual!//<br/>',NULL,192262,3);
INSERT INTO stanza VALUES('S695','4','Ahora ella lirio es<br/>Para nuestro Señor;<br/>Su fe no es en lo terrenal,<br/>//Mas en el Hijo hoy.//<br/>',NULL,192263,4);
INSERT INTO stanza VALUES('S695','5','Paloma escondida es,<br/>En la hendidura está;<br/>Con el Señor, en ascensión,<br/>//Su amor perdurará.//<br/>',NULL,192264,5);
INSERT INTO stanza VALUES('S695','6','De humo, la columna es,<br/>Cesó su deambular;<br/>Subyuga a Él su voluntad,<br/>//¡Fragancia sin igual!//<br/>',NULL,192265,6);
INSERT INTO stanza VALUES('S695','7','Litera es para su Rey<br/>Cuando oscuro está;<br/>Reposo al Señor le da<br/>//Y ahuyenta a Satán.//<br/>',NULL,192266,7);
INSERT INTO stanza VALUES('S695','8','¡Contiene ella_al mismo Rey,<br/>Pues Él en ella está!<br/>Para el mover de Dios será<br/>//Su palanquín real.//<br/>',NULL,192267,8);
INSERT INTO stanza VALUES('S695','9','De Cristo, la humanidad<br/>En la madera ved.<br/>Sus postes, plata pura son,<br/>//El fondo, oro es.//<br/>',NULL,192268,9);
INSERT INTO stanza VALUES('S695','10','Su asiento púrpura real<br/>Es digno para Él;<br/>Le damos todo nuestro amor<br/>//¡Pues Rey de reyes es!//<br/>',NULL,192269,10);
INSERT INTO stanza VALUES('S695','11','El día pronto llegará,<br/>¡Gran gozo Él tendrá!<br/>Su complemento obtendrá,<br/>//¡Corona le será!//<br/>',NULL,192270,11);
INSERT INTO stanza VALUES('S695','12','Cerrado huerto ella es<br/>¡Su aroma es sin igual!<br/>Y para la edificación,<br/>//Produce el material.//<br/>',NULL,192271,12);
INSERT INTO stanza VALUES('S695','13','Ciudad hermosa ella es<br/>¡Grandiosa, sin igual!<br/>Mas es ejército también<br/>//Que aterra a Satán.//<br/>',NULL,192272,13);
INSERT INTO stanza VALUES('S695','14','Comemos al Señor Jesús<br/>Y nos transforma hoy.<br/>¡Su novia Cristo obtiene así<br/>//En tan perfecta unión!//<br/>',NULL,192273,14);
INSERT INTO stanza VALUES('S696','1','Si, en Cristo, los hermanos<br/>Van en orden y_en unión,<br/>Hoy seguidlos, viendo a Cristo,<br/>Dando fin a la opinión.<br/>',NULL,192274,1);
INSERT INTO stanza VALUES('S696','chorus','Oh, seguid a los hermanos<br/>Cuando Cristo_es su vivir;<br/>Y siguiendo a los hermanos,<br/>Preparad la novia aquí.<br/>',NULL,192275,2);
INSERT INTO stanza VALUES('S696','2','Al seguir a los hermanos,<br/>El fiel nombre invocad;<br/>Cristo da confianza plena<br/>Y avergüenza a Satán.<br/>',NULL,192276,3);
INSERT INTO stanza VALUES('S696','3','Cuando hablen los hermanos,<br/>Abran bien el corazón,<br/>Recibiendo la Palabra,<br/>No el hombre, mas de Dios.<br/>',NULL,192277,4);
INSERT INTO stanza VALUES('S696','4','La Palabra ahora corre,<br/>Corre libre y velóz.<br/>Y así en Su recobro<br/>El Señor se nueve hoy.<br/>',NULL,192278,5);
INSERT INTO stanza VALUES('S696','5','Cerca está la boda, hermanos,<br/>¡Alegraos en el Señor!<br/>Lista estará la novia:<br/>Los que han seguido en pos.<br/>',NULL,192279,6);
INSERT INTO stanza VALUES('S697','1','Vamos siguiendo a las iglesias<br/>Guardando la_unidad;<br/>En Su mover hoy en las iglesias<br/>En Su camino_andad.<br/>',NULL,192280,1);
INSERT INTO stanza VALUES('S697','chorus','Al Espíritu sigue,<br/>Tú, en simplicidad;<br/>Nuestro_espíritu tiene<br/>A Cristo en verdad.<br/>',NULL,192281,2);
INSERT INTO stanza VALUES('S697','2','Vamos siguiendo a los que siguen<br/>Para hoy aprender;<br/>No codiciando el liderato,<br/>Mas descansando en Él.<br/>',NULL,192282,3);
INSERT INTO stanza VALUES('S697','3','Vamos siguiendo a Su rebaño,<br/>Bajo el buen Pastor;<br/>En las iglesias Él nos dirige,<br/>Aquí nos habla Dios.<br/>',NULL,192283,4);
INSERT INTO stanza VALUES('S697','4','A Ti nos damos, oh Jesucristo,<br/>Nunca mirando atrás;<br/>Siempre siguiendo fiel al Cordero<br/>Por dondequiera va.<br/>',NULL,192284,5);
INSERT INTO stanza VALUES('S697','5','Nos damos para entrar en el reino,<br/>Fiesta matrimonial;<br/>Persecuciones, penas y pruebas<br/>Nunca nos detendrán.<br/>',NULL,192285,6);
INSERT INTO stanza VALUES('S697','6','Cristo anhela ver seguidores<br/>En las iglesias hoy<br/>Que cumplan Su propósito, fieles;<br/>¡Haznos así, Señor!<br/>',NULL,192286,7);
INSERT INTO stanza VALUES('S698','1','Juró el rey David:<br/>"No entraré en mi casa,<br/>Ni_al lecho subiré,<br/>Ni cerraré mis ojos,<br/>Hasta que halle un lugar,<br/>Señor, para Tu hogar".<br/>Hoy quiere nuestro fuerte Dios<br/>Tener Su habitación.<br/>',NULL,192287,1);
INSERT INTO stanza VALUES('S698','2','Oh, qué ceguera estar<br/>En lo nuestro encerrados,<br/>Mientras desierta está<br/>La casa que Él ansiaba.<br/>Sacúdenos para subir<br/>Al monte y encontrar<br/>Madera para edificar,<br/>Señor, Tu santo hogar.<br/>',NULL,192288,2);
INSERT INTO stanza VALUES('S698','3','Como a David, Señor,<br/>Inspira algunos hombres,<br/>Por Tu edificación,<br/>Que honren hoy Tu nombre,<br/>Que vengan para edificar<br/>Tu casa y cooperar<br/>Contigo y con Tu intención<br/>Señor, ¡qué bendición!<br/>',NULL,192289,3);
INSERT INTO stanza VALUES('S698','4','En los que llamarás<br/>Pon tal anhelo alto,<br/>De todo abandonar<br/>Por Tu edificio santo.<br/>La iglesia prevalecerá<br/>Si edificada está;<br/>Pronto edifica en nuestro ser,<br/>En nuestro ser, Señor.<br/>',NULL,192290,4);
INSERT INTO stanza VALUES('S699','1','Todos en Jerusalén,<br/>De_un acuerdo somos ya,<br/>Babilonia queda atrás,<br/>¡Oh, gloria sea a Dios!<br/>La doctrina se expulsó,<br/>La_opinión se rechazó,<br/>Y el alma se negó,<br/>Hoy en la_iglesia local.<br/>',NULL,192291,1);
INSERT INTO stanza VALUES('S699','chorus','¡Aleluya! ¡Aleluya!<br/>¡De_un acuerdo en comunión<br/>Para la edificación!<br/>¡Aleluya! ¡Aleluya!<br/>¡Qué felices hoy en la_iglesia local<br/>',NULL,192292,2);
INSERT INTO stanza VALUES('S699','2','Cristo a de utilizar<br/>Sacerdotes en verdad<br/>Para todo recobrar,<br/>¡Oh, gloria sea a Dios!<br/>Saturados con Jesús,<br/>Sólo Cristo es su virtud,<br/>Su obra harán en plenitud<br/>Hoy en la iglesia local.<br/>',NULL,192293,3);
INSERT INTO stanza VALUES('S699','3','Se debe el reinado ver<br/>Con divina autoridad,<br/>Lo aceptamos en verdad,<br/>¡Oh, gloria sea a Dios!<br/>Al Espíritu en función,<br/>Le rendimos sumisión,<br/>Para la edificación,<br/>Hoy en la iglesia local.<br/>',NULL,192294,4);
INSERT INTO stanza VALUES('S699','4','El altar hay que obtener,<br/>Nuestro todo allí ofrecer,<br/>Holocausto debe ser,<br/>¡Oh, gloria sea a Dios!<br/>No se debe disputar,<br/>A la iglesia el todo dar,<br/>Lo demás eliminar<br/>Hoy en la iglesia local.<br/>',NULL,192295,5);
INSERT INTO stanza VALUES('S699','5','Puesto el cimiento está;<br/>Esta gloria al contemplar<br/>Causa gozo sin igual,<br/>¡Oh, gloria sea a Dios!<br/>Gritos de alegría dad,<br/>Todo el mundo lo oirá,<br/>Satanás se esfumará<br/>Hoy en la iglesia local.<br/>',NULL,192296,6);
INSERT INTO stanza VALUES('S700','1','Bajo la Babel, en cautividad,<br/>¡Nuestro_espíritu Dios despertó!<br/>Tan dispersos y sin la unidad,<br/>¡Nuestro espíritu Dios despertó!<br/>Despertado,<br/>¡Nuestro_espíritu Dios despertó!<br/>Despertado,<br/>¡Nuestro_espíritu Dios despertó!<br/>',NULL,192297,1);
INSERT INTO stanza VALUES('S700','2','De las sectas y de la división,<br/>¡De la Babilonia hay que salir!<br/>Su terreno no es el de la unidad,<br/>¡De la división hay que salir!<br/>¡Fuera! ¡Fuera!<br/>¡De la división hay que salir!<br/>¡Fuera! ¡Fuera!<br/>¡De la división hay que salir!<br/>',NULL,192298,2);
INSERT INTO stanza VALUES('S700','3','Dios nos levantó de cautividad,<br/>¡A Jerusalén hay que subir!<br/>Su terreno es el de la unidad,<br/>¡A Jerusalén hay que subir!<br/>¡Subid! ¡Subid!<br/>¡Con nosotros el Señor está!<br/>¡Subid! ¡Subid!<br/>¡Con nosotros el Señor está!<br/>',NULL,192299,3);
INSERT INTO stanza VALUES('S700','4','Los vasos de Dios, tazas del Señor,<br/>¡Tráelos llenos del Espíritu!<br/>Conforme a Su plan a la iglesia irán,<br/>Tráelos llenos del Espíritu.<br/>¡Tráelos! ¡Tráelos!<br/>¡Tráelos a la casa del Señor!<br/>¡Tráelos! ¡Tráelos!<br/>¡Tráelos a la casa del Señor!<br/>',NULL,192300,4);
INSERT INTO stanza VALUES('S700','5','En Jerusalén, elección de Dios,<br/>¡Edifica el templo del Señor!<br/>Con los santos hoy sirviendo en amor,<br/>¡Edifica el templo del Señor!<br/>¡Edifica!<br/>¡Edifica el templo del Señor!<br/>¡Edifica!<br/>¡Edifica el templo del Señor!<br/>',NULL,192301,5);
INSERT INTO stanza VALUES('S701','1','Edificad ahora el templo del Señor;<br/>Su casa_está desierta por falta de_atención;<br/>Hoy todas las iglesias locales recobrad,<br/>Hermanos, ¡acudamos a_edificar!<br/>',NULL,192302,1);
INSERT INTO stanza VALUES('S701','chorus','¡Sed fieles! ¡Sed fieles! ¡Su templo_edificad!<br/>¡Jehová de los ejércitos con gloria lo llenará!<br/>¡Sed fieles! ¡Sed fieles! ¡En un acuerdo_obrad!<br/>Y la morada del Señor así se_exhibirá.<br/>',NULL,192303,2);
INSERT INTO stanza VALUES('S701','2','"Medita en tus caminos", dice nuestro Señor,<br/>"Sembráis y traéis poco, os falta devoción;<br/>Subid al monte ahora, traed el material,<br/>Seré glorificado, ¡edificad!"<br/>',NULL,192304,3);
INSERT INTO stanza VALUES('S701','3','Cristianos sacerdotes, ahora obedeced,<br/>No importa lo que digan, con nosotros es Él;<br/>Con espíritu ardiente venid a trabajar,<br/>Que ninguno evada edificar.<br/>',NULL,192305,4);
INSERT INTO stanza VALUES('S701','4','La gloria del Señor a Su casa volverá,<br/>Y el Deseado de las naciones se verá;<br/>La gloria venidera será aún mayor,<br/>Y participaremos en su esplendor.<br/>',NULL,192306,5);
INSERT INTO stanza VALUES('S702','1','Somos para el recobro<br/>En cada ciudad,<br/>De la_iglesia_adecuada,<br/>Hasta la tierra ganar.<br/>Firmes sobre el terreno,<br/>Uno_en el Señor,<br/>Hoy el templo edificamos<br/>Del glorioso Dios.<br/>',NULL,192307,1);
INSERT INTO stanza VALUES('S702','chorus','Somos para Él<br/>Somos para Él,<br/>Somos para Su recobro.<br/>Somos para Él<br/>Somos para Él,<br/>Somos para Su recobro.<br/>',NULL,192308,2);
INSERT INTO stanza VALUES('S702','2','Somos para el recobro,<br/>¡Llena el corazón!<br/>Nuestro espíritu activado<br/>Nos da mejor visión;<br/>Babilonia ha caído,<br/>También Satanás;<br/>Hoy vamos edificando<br/>La iglesia local.<br/>',NULL,192309,3);
INSERT INTO stanza VALUES('S703','1','Somos los hebreos —Éufrates atrás—<br/>Idolatría no queremos más;<br/>Ya cruzado‿el río,‿entramos en Cana͡án;<br/>Buscamos la ciudad que‿es eternal.<br/>',NULL,192310,1);
INSERT INTO stanza VALUES('S703','chorus','Hebreos es nuestro nombre real;<br/>Cruzado‿el río, no somos igual;<br/>Edificamos para Dios Su‿hogar,<br/>Edificamos para Dios Su‿hogar.<br/>',NULL,192311,2);
INSERT INTO stanza VALUES('S703','2','En Egipto‿esclavos bajo Satanás,<br/>Mas dijo Dios: “A Mi pueblo soltad”.<br/>Cruzando‿el mar Rojo, vimos salvación<br/>Cuando el mar tragó a Faraón.<br/>',NULL,192312,3);
INSERT INTO stanza VALUES('S703','chorus','Dios de hebreos, vuelve hoy a‿hablar;<br/>Dios de hebreos, guía‿hasta‿el final;<br/>Salva‿a Tu pueblo de‿este siglo‿atroz,<br/>Salva‿a Tu pueblo de‿este siglo‿atroz.<br/>',NULL,192313,4);
INSERT INTO stanza VALUES('S703','3','Hoy edificamos para Dios Su‿hogar;<br/>Su tienda es nuestra morada re͡al.<br/>La vejez dejamos bajo el Jordán;<br/>Ah͡ora pele͡amos por ganar Canaán.<br/>',NULL,192314,5);
INSERT INTO stanza VALUES('S703','chorus','El Capitán nos llama a pele͡ar,<br/>Y conquistamos hoy cada ciudad,<br/>Para Su reino, y‿al reposo‿entrar,<br/>Para Su reino, y‿al reposo‿entrar.<br/>',NULL,192315,6);
INSERT INTO stanza VALUES('S703','4','Lo que ordenó Dios se hizo‿un ritual;<br/>Juan el Bautista vino‿a proclamar:<br/>El río cruzad, pues Dios delante va,<br/>Y‿el judaísmo ya quedó atrás.<br/>',NULL,192316,7);
INSERT INTO stanza VALUES('S703','chorus','“No‿a los profetas, sino‿al Hijo‿oíd,<br/>Él es mi‿Amado, uno soy con Él”.<br/>En Su palabra hoy hay salvación,<br/>En Su palabra hoy hay salvación.<br/>',NULL,192317,8);
INSERT INTO stanza VALUES('S703','5','Vencedores sobre‿el mar de vidrio‿están;<br/>Sobre‿este mar será‿el cruce final;<br/>Alabad, cantando‿el canto de Moisés,<br/>¡Todo‿enemigo bajo nuestros pies!<br/>',NULL,192318,9);
INSERT INTO stanza VALUES('S703','chorus','Los vencedores vencen a Satán,<br/>Dios ha ganado Su santa ciudad.<br/>Nuestra porción eterna‿es nuestro Dios,<br/>Nuestra porción eterna‿es nuestro Dios.<br/>',NULL,192319,10);
INSERT INTO stanza VALUES('S704','1','Cristo nos llamó_una vez,<br/>Mas nos llama otra vez,<br/>Respondamos hoy: ¡Amén!<br/>¡A vencer!<br/>Pues la_iglesia puedes ver<br/>Enredada_en su saber,<br/>Mas la vida no se ve,<br/>¡A vencer!<br/>',NULL,192320,1);
INSERT INTO stanza VALUES('S704','chorus','¡A vencer! ¡A vencer!<br/>¡Cristianismo degradado hay que vencer!<br/>Toda tu obra deja atrás,<br/>Toda división falaz,<br/>Y de Cristo come más,<br/>¡A vencer!<br/>',NULL,192321,2);
INSERT INTO stanza VALUES('S704','2','Que comamos es Su plan,<br/>Lo que debe recobrar<br/>Para el diablo derrotar,<br/>¡A vencer!<br/>El debate doctrinal<br/>Al comer se acabará,<br/>Y la vida ganarás,<br/>¡A vencer!<br/>',NULL,192322,3);
INSERT INTO stanza VALUES('S704','3','No te puede transformar<br/>La enseñanza clerical,<br/>El comer lo logrará,<br/>¡A vencer!<br/>En verdad es menester<br/>El comer para vencer,<br/>Come siempre por doquier,<br/>¡A vencer!<br/>',NULL,192323,4);
INSERT INTO stanza VALUES('S704','4','Nacerá el hijo varón,<br/>Y vendrá nuestro Señor<br/>Al comer nuestra porción,<br/>¡A vencer!<br/>Sé aquel hijo varón,<br/>Y la iglesia que Él soñó,<br/>Esa Novia en su esplendor,<br/>¡A vencer!<br/>',NULL,192324,5);
INSERT INTO stanza VALUES('S705','1','Oh, iglesia en Filadelfia,<br/>Mucho se_habla de tu_amor,<br/>Estas cosas dice el Santo,<br/>El que habla_a tu favor,<br/>El que_abrió la_entrada_al reino<br/>Con la llave de David:<br/>"Hecho está", ha proclamado,<br/>"Nadie cierre lo que_abrí".<br/>',NULL,192325,1);
INSERT INTO stanza VALUES('S705','2','Tienes obras Filadelfia,<br/>Que complacen al Señor.<br/>Su Palabra has guardado,<br/>Aunque es poco tu vigor.<br/>Tú Su nombre no has negado,<br/>Mas lo confesaste aquí;<br/>Una puerta Él ha puesto<br/>Sólo abierta para ti.<br/>',NULL,192326,2);
INSERT INTO stanza VALUES('S705','3','Has guardado la Palabra<br/>De perseverancia fiel.<br/>De la hora de la prueba<br/>Guardada serás por Él.<br/>Sabrán que Él te ha amado,<br/>A tus pies se postrarán.<br/>"Vengo pronto, lo que tienes<br/>Tú retén hasta_el final"<br/>',NULL,192327,3);
INSERT INTO stanza VALUES('S705','4','Aleluya, vencedores,<br/>"En el templo de mi Dios",<br/>Han de ser edificados,<br/>Las columnas ellos son.<br/>En sus frentes hay los nombres<br/>De su Padre y del Señor,<br/>Con el Triuno Dios mezclados,<br/>Forman la ciudad de Dios.<br/>',NULL,192328,4);
INSERT INTO stanza VALUES('S705','5','Aleluya, de Dios viene<br/>La Nueva Jerusalén;<br/>Ataviada está con perlas,<br/>Jaspe y gemas a la vez.<br/>Filadelfia, Filadelfia,<br/>Su preciosa novia es;<br/>El Espíritu y la novia,<br/>Al que oye dicen: "Ven".<br/>',NULL,192329,5);
INSERT INTO stanza VALUES('S706','1','Todas las iglesias fluyen<br/>Fraterno amor.<br/>Vida, luz y amor imparte,<br/>Fraterno amor.<br/>Comunión hoy disfrutamos,<br/>De la fe común gozamos,<br/>Al Espíritu honramos,<br/>Fraterno_amor.<br/>',NULL,192330,1);
INSERT INTO stanza VALUES('S706','2','Tal unión nos sana en vida,<br/>Fraterno amor;<br/>Para estar en armonía,<br/>Fraterno amor.<br/>Nos da amor por los hermanos,<br/>Por fe, todo lo esperamos;<br/>En el sufrimiento hallamos<br/>Fraterno amor.<br/>',NULL,192331,2);
INSERT INTO stanza VALUES('S706','3','Mucho fruto así llevamos,<br/>Fraterno amor;<br/>¡Oh qué comunión gozamos!<br/>Fraterno amor.<br/>Cuando al alma nos negamos,<br/>Y el Espíritu honramos,<br/>De la muerte a vida entramos,<br/>Fraterno amor.<br/>',NULL,192332,3);
INSERT INTO stanza VALUES('S706','4','¡Oh, la senda de gran gozo!<br/>Fraterno amor;<br/>No es camino doloroso,<br/>¡Fraterno amor!<br/>Vida y fe son el cimiento,<br/>El Espíritu, el aliento,<br/>Y el Cuerpo, el cumplimiento:<br/>Fraterno amor.<br/>',NULL,192333,4);
INSERT INTO stanza VALUES('S706','5','Hoy en vida está creciendo,<br/>Fraterno amor.<br/>Filadelfia así fluyendo,<br/>Fraterno amor.<br/>Dios ya nos ha restaurado<br/>A tal gran amor preciado;<br/>Sobre todo ha conquistado:<br/>¡Fraterno amor!<br/>',NULL,192334,5);
INSERT INTO stanza VALUES('S707','1','En la iglesia viva del Señor Jesús<br/>Hay amor profundo, tierno y veraz;<br/>¿Por qué estar tan solo y sin amistad,<br/>Cuando Su iglesia te puede arropar?<br/>',NULL,192335,1);
INSERT INTO stanza VALUES('S707','2','En la iglesia viva del Señor Jesús,<br/>Una vida fresca vibra sin cesar;<br/>¿Por qué estar ansioso, lleno de temor,<br/>Si Su iglesia cuida a los que Él compró?<br/>',NULL,192336,2);
INSERT INTO stanza VALUES('S707','3','En la iglesia viva del Señor Jesús,<br/>Una obra noble hay que realizar;<br/>¿Por qué estar ocioso? Hay que cosechar;<br/>En la iglesia ahora puedes laborar.<br/>',NULL,192337,3);
INSERT INTO stanza VALUES('S707','4','En la iglesia viva del Señor Jesús,<br/>Un lugar glorioso te espera ya;<br/>¿Por qué estar inquieto y vagar sin paz,<br/>Cuando en Su iglesia tienes un hogar?<br/>',NULL,192338,4);
INSERT INTO stanza VALUES('S708','1','En las reuniones y diario vivir,<br/>Cristo_es el centro, Cristo todo es;<br/>No por doctrinas ni por un ritual,<br/>Sólo por Cristo_es nuestro congregar.<br/>',NULL,192339,1);
INSERT INTO stanza VALUES('S708','2','La luz de vida y el camino es,<br/>En Él andamos, guía nuestros pies;<br/>Cristo agua viva y comida es,<br/>Cristo nos nutre y sacia nuestra sed.<br/>',NULL,192340,2);
INSERT INTO stanza VALUES('S708','3','Cristo es verdad, testificamos de Él,<br/>Cristo es Señor, magnifiquémosle;<br/>Cristo, la vida, ministrado es,<br/>Como Cabeza, ¡exaltémosle!<br/>',NULL,192341,3);
INSERT INTO stanza VALUES('S708','4','Cristo es el todo para el hombre y Dios,<br/>A Dios y al hombre satisface Él;<br/>Para Su iglesia es la realidad,<br/>Por Él la vida en ella crecerá.<br/>',NULL,192342,4);
INSERT INTO stanza VALUES('S708','5','En cada himno y en cada oración,<br/>Se expresa a Cristo como realidad;<br/>Todo servicio en la comunión<br/>Exhibe a Cristo en Su operación.<br/>',NULL,192343,5);
INSERT INTO stanza VALUES('S708','6','Es en Su Nombre y en Espíritu<br/>Que nos reunimos sin formalidad;<br/>Le alabaremos con poder y unción<br/>Con nuestro espíritu y en oración.<br/>',NULL,192344,6);
INSERT INTO stanza VALUES('S708','7','A Cristo asidos, todo hay que olvidar,<br/>Lo aplicaremos hasta madurar;<br/>Todo estimemos pérdida por Él,<br/>Eternamente el todo en todo es.<br/>',NULL,192345,7);
INSERT INTO stanza VALUES('S709','1','Llenos de Cristo en la reunión,<br/>El excedente_es para Dios,<br/>Al ofrecerle tal porción,<br/>Cristo_exhibido es.<br/>',NULL,192346,1);
INSERT INTO stanza VALUES('S709','chorus','¡A Cristo exhibid!<br/>¡A Cristo exhibid!<br/>El excedente_a la_iglesia trae,<br/>¡A Cristo exhibid!<br/>',NULL,192347,2);
INSERT INTO stanza VALUES('S709','2','Nuestro vivir en Cristo está,<br/>Al cultivar a Cristo habrá<br/>Un excedente en la reunión<br/>Que a Cristo exhibirá.<br/>',NULL,192348,3);
INSERT INTO stanza VALUES('S709','3','En nuestro obrar, vivir y ser,<br/>La misma esencia Cristo es;<br/>Así al reunirnos cada vez,<br/>Se exhibe a Cristo bien.<br/>',NULL,192349,4);
INSERT INTO stanza VALUES('S709','4','Llevando Cristo a la reunión,<br/>Y disfrutándolo con Dios,<br/>Los santos en tal comunión<br/>A Cristo han de exhibir.<br/>',NULL,192350,5);
INSERT INTO stanza VALUES('S709','5','El Cristo en resurrección<br/>Le brindo a Dios satisfacción;<br/>Al ofrecerlo en Su ascensión,<br/>Cristo exhibido es.<br/>',NULL,192351,6);
INSERT INTO stanza VALUES('S709','6','El centro y la realidad,<br/>La atmósfera y el ministrar,<br/>Y todo lo de la reunión,<br/>A Cristo exhibirá.<br/>',NULL,192352,7);
INSERT INTO stanza VALUES('S709','7','Los dones y la comunión,<br/>El testimonio u oración,<br/>En todo debe la reunión<br/>A Cristo exhibir.<br/>',NULL,192353,8);
INSERT INTO stanza VALUES('S709','8','¡Al Padre Dios glorificad!<br/>¡A Cristo el Hijo exaltad!<br/>¡De la reunión es la intención<br/>A Cristo exhibir!<br/>',NULL,192354,9);
INSERT INTO stanza VALUES('S710','1','Reunidos, adoramos en<br/>Espíritu y verdad;<br/>Nos acercamos hoy a Dios,<br/>Como Él nos enseñó.<br/>',NULL,192355,1);
INSERT INTO stanza VALUES('S710','2','Gracias que, como Espíritu,<br/>Muy cerca Dios está;<br/>Podemos adorarlo a Él<br/>Al Su vida tocar.<br/>',NULL,192356,2);
INSERT INTO stanza VALUES('S710','3','Creó Dios nuestro espíritu<br/>Para adorarlo a Él;<br/>Buscamos de Él en lo interior,<br/>Sin nada externo hacer.<br/>',NULL,192357,3);
INSERT INTO stanza VALUES('S710','4','Su vida el Señor nos dio,<br/>La mente renovó;<br/>Morando en nuestro interior,<br/>Incita adoración.<br/>',NULL,192358,4);
INSERT INTO stanza VALUES('S710','5','Lo adoramos en verdad<br/>Con conciencia interior;<br/>Ungidos por Su Espíritu,<br/>Hoy somos Su expresión.<br/>',NULL,192359,5);
INSERT INTO stanza VALUES('S710','6','Servimos con veracidad,<br/>En sombras nunca más;<br/>En Cristo, nuestra realidad,<br/>Al Padre hay que adorar.<br/>',NULL,192360,6);
INSERT INTO stanza VALUES('S710','7','Hoy ofrecemos Cristo a Dios<br/>Con la experiencia de Él;<br/>Nos deleitamos de Él con Dios,<br/>Con dulzura y placer.<br/>',NULL,192361,7);
INSERT INTO stanza VALUES('S710','8','En realidad y espíritu<br/>Gozamos comunión;<br/>En el propiciatorio así,<br/>Se ofrece adoración.<br/>',NULL,192362,8);
INSERT INTO stanza VALUES('S711','1','¡Tu_espíritu aviva!<br/>Rechaza_el pensar;<br/>Al ejercitarlo<br/>El Cuerpo_honrarás.<br/>',NULL,192363,1);
INSERT INTO stanza VALUES('S711','2','¡Tu espíritu aviva!<br/>Las formas dejad;<br/>Comparte con otros,<br/>Cristo disfrutad.<br/>',NULL,192364,2);
INSERT INTO stanza VALUES('S711','3','¡Tu espíritu aviva!<br/>Deja el ego atrás;<br/>Sirviendo con otros,<br/>A Cristo anunciad.<br/>',NULL,192365,3);
INSERT INTO stanza VALUES('S711','4','¡Tu espíritu aviva!<br/>Niega tu alma ya;<br/>Al ejercitarlo<br/>En Cristo confiad.<br/>',NULL,192366,4);
INSERT INTO stanza VALUES('S711','5','Tú Espíritu libre<br/>De condenación,<br/>De justicia propia,<br/>De conciencia atroz.<br/>',NULL,192367,5);
INSERT INTO stanza VALUES('S711','6','Tú Espíritu libre,<br/>De la terquedad,<br/>Y sin egoísmo,<br/>Todo vencerá.<br/>',NULL,192368,6);
INSERT INTO stanza VALUES('S711','7','¡Tu espíritu aviva!<br/>Victoria clamad;<br/>Por Su fuerte nombre,<br/>Y sangre eficaz.<br/>',NULL,192369,7);
INSERT INTO stanza VALUES('S711','8','¡Tu espíritu aviva!<br/>Toca a Jesús;<br/>Toma Su Palabra<br/>En espíritu.<br/>',NULL,192370,8);
INSERT INTO stanza VALUES('S711','9','Tu espíritu puede<br/>Expresar a Dios,<br/>Y brindar al hombre<br/>Gran satisfacción.<br/>',NULL,192371,9);
INSERT INTO stanza VALUES('S711','10','¡Oh, que ejercitemos<br/>El espíritu!<br/>Lo necesitamos,<br/>¡Guíanos, Jesús!<br/>',NULL,192372,10);
INSERT INTO stanza VALUES('S712','1','Como miembros del Cuerpo<br/>A Cristo_hay que expresar,<br/>Nuestra función permite<br/>Su plenitud mostrar;<br/>No siendo_expectadores,<br/>Mas todos en función,<br/>Nadie trayendo muerte,<br/>Mas gracia_y bendición.<br/>',NULL,192373,1);
INSERT INTO stanza VALUES('S712','2','Jamás independientes<br/>Debemos proceder,<br/>Mas siempre coordinados,<br/>Para un equipo ser;<br/>Negando preferencias,<br/>Siguiendo el fluir,<br/>Sin leves distracciones,<br/>Al Espíritu oíd.<br/>',NULL,192374,2);
INSERT INTO stanza VALUES('S712','3','En Cristo enfocados,<br/>No otro centró habrá;<br/>En comunión tan dulce,<br/>De Sus riquezas dad;<br/>Él es nuestra Cabeza,<br/>Su Cuerpo debe hacer<br/>Que en la reunión en todo<br/>Se manifieste Él.<br/>',NULL,192375,3);
INSERT INTO stanza VALUES('S712','4','Todos edificados,<br/>Sin crítica, en amor,<br/>Somos perfeccionados<br/>En mutua comunión;<br/>Dejando al viejo hombre,<br/>El ego hay que negar;<br/>Por gracia entrenados<br/>Del Cuerpo disfrutar.<br/>',NULL,192376,4);
INSERT INTO stanza VALUES('S713','1','Antes de irnos de nuestra reunión,<br/>Gracias te damos desde_el corazón<br/>Por Tu presencia_y gracia sin igual<br/>Que impartiste_en nuestro ser, Señor.<br/>',NULL,192377,1);
INSERT INTO stanza VALUES('S713','2','Aunque termine aquí nuestra reunión,<br/>Tu fiel presencia con nosotros va;<br/>Y, como Espíritu, Tu gran poder<br/>En incensante amor impartirás.<br/>',NULL,192378,2);
INSERT INTO stanza VALUES('S713','3','Que con nosotros Tu presencia esté,<br/>Que nuestras cargas puedas Tú llevar,<br/>Que te podamos siempre disfrutar<br/>Hasta en la próxima reunión estar.<br/>',NULL,192379,3);
INSERT INTO stanza VALUES('S714','1','Te alabamos al partir, Señor,<br/>Por Tu presencia y palabra fiel;<br/>Tú nos atraes por Tu preciosidad,<br/>Y, por Tu_hablar, se_inclina el corazón.<br/>',NULL,192380,1);
INSERT INTO stanza VALUES('S714','2','Por Tu palabra nos haces crecer,<br/>Ella espíritu y vida es;<br/>A Tu imagen nos transformará,<br/>Hasta alcanzar la plena madurez.<br/>',NULL,192381,2);
INSERT INTO stanza VALUES('S714','3','Impártete en nosotros más y más,<br/>En el espíritu haznos andar;<br/>Contigo guárdanos en comunión,<br/>Hasta la próxima reunión, Señor.<br/>',NULL,192382,3);
INSERT INTO stanza VALUES('S715','1','Somos hoy Su imagen;<br/>Nos creó a Su imagen,<br/>Para expresar a Cristo_aquí<br/>Y la tierra sojuzgar así:<br/>Su imagen: ¡gloria a Dios!<br/>',NULL,192383,1);
INSERT INTO stanza VALUES('S715','2','Somos hoy los llamados,<br/>A Su eterno plan llamados;<br/>Nos sacó Dios del caído Adán<br/>Para en Su misma gloria entrar:<br/>Los llamados: ¡gloria a Dios!<br/>',NULL,192384,2);
INSERT INTO stanza VALUES('S715','3','Somos hoy coherederos<br/>De Su salvación completa.<br/>Al que venza, un trono le dará,<br/>Y con ello, todo lo demás:<br/>Coherederos: ¡gloria a Dios!<br/>',NULL,192385,3);
INSERT INTO stanza VALUES('S715','4','Somos hoy compañeros,<br/>Compañeros del Ungido;<br/>No tan sólo siervos para Él,<br/>Sus riquezas Él nos da también:<br/>Compañeros: ¡gloria a Dios!<br/>',NULL,192386,4);
INSERT INTO stanza VALUES('S715','5','Somos hoy los hermanos;<br/>Somos los hermanos santos.<br/>Cristo nos legó vida eternal,<br/>Y Su oro nos da santidad:<br/>Los hermanos, ¡gloria a Dios!<br/>',NULL,192387,5);
INSERT INTO stanza VALUES('S715','6','Somos el candelero,<br/>Con Jesús resplandecemos.<br/>En un mundo oscuro y pecador,<br/>Cristo es nuestra vida y resplandor:<br/>Candelero: ¡gloria a Dios!<br/>',NULL,192388,6);
INSERT INTO stanza VALUES('S716','1','En resurrección nos hizo<br/>Sus hermanos, el Señor;<br/>¡Quiere Él que Sus hermanos,<br/>De Su triunfo gocen hoy!<br/>',NULL,192389,1);
INSERT INTO stanza VALUES('S716','chorus','Jescristo_es nuestro_Hermano,<br/>Primogénito de Dios;<br/>¡Libre de la religión! Él<br/>En resurrección nació.<br/>Como_iglesia nos reunimos<br/>Sin vejez, ritual o_el yo;<br/>Para darle_a nuestro hermano<br/>Alabanzas y honor.<br/>',NULL,192390,2);
INSERT INTO stanza VALUES('S716','2','En resurrección, reunidos<br/>Con el hermano mayor,<br/>No en lo natural confiamos;<br/>Esto alegra al Señor.<br/>',NULL,192391,3);
INSERT INTO stanza VALUES('S716','3','Cada día en la Palabra,<br/>A Jesús debemos ver;<br/>Vamos luego a las reuniones,<br/>Rebosando así con Él.<br/>',NULL,192392,4);
INSERT INTO stanza VALUES('S716','4','¡Qué banquete, las reuniones!<br/>Hay comida sin cesar,<br/>Y Jesús nos satisface,<br/>Dándonos viviente pan.<br/>',NULL,192393,5);
INSERT INTO stanza VALUES('S716','5','Nuestro Hermano aún disfruta<br/>Nuestra pequeña porción;<br/>Cada cual su "nuevo plato"<br/>Debe dar en comunión.<br/>',NULL,192394,6);
INSERT INTO stanza VALUES('S716','6','No buscamos los mensajes,<br/>Sino estar con el Señor;<br/>Nos importa la presencia<br/>De nuestro Hermano mayor.<br/>',NULL,192395,7);
INSERT INTO stanza VALUES('S717','1','Las reuniones que_en la tierra<br/>Cristo_aquí estableció.<br/>Se_apartaban de rituales,<br/>Formas y de religión.<br/>La resurrección, hermanos,<br/>Sea nuestra realidad,<br/>Libre de religión muerta,<br/>Al reunirnos en verdad.<br/>',NULL,192396,1);
INSERT INTO stanza VALUES('S717','2','El Señor resucitado<br/>Abolió la religión;<br/>Cristo es nuestras ofrendas,<br/>Nuestro templo vivo hoy.<br/>El Señor resucitado,<br/>¡Aleluya! nos libró<br/>De la reiligión caduca,<br/>¡Qué banquete es la reunión!<br/>',NULL,192397,2);
INSERT INTO stanza VALUES('S717','3','Qué sutil lo religioso<br/>Escondido en nuestro ser;<br/>Danos, Dios, entendimiento<br/>Para este monstruo ver.<br/>Aún somos religiosos,<br/>¡Sana el alma, oh Señor!<br/>Nuestro espíritu avivado<br/>Sea la meta en la reunión.<br/>',NULL,192398,3);
INSERT INTO stanza VALUES('S717','4','Las reuniones, las reuniones,<br/>En el monte o junto al mar;<br/>Jesucristo, Jesucristo,<br/>Está aquí, ¿qué más buscar?<br/>Sepultad lo religioso,<br/>Incluso la cristiandad;<br/>Jesucristo, Jesucristo,<br/>¡Él es nuestra realidad!<br/>',NULL,192399,4);
INSERT INTO stanza VALUES('S718','1','¡Estad por Cristo firmes,<br/>Soldados de la cruz!<br/>Alzad el estandarte<br/>En nombre de Jesús;<br/>Es vuestra la victoria,<br/>Con Él por Capitán;<br/>Por Él sean vencidas<br/>Las huestes de Satán.<br/>',NULL,192400,1);
INSERT INTO stanza VALUES('S718','chorus','¡Por Cristo firmes,<br/>Soldados de la cruz!<br/>Alzad el estandarte<br/>En nombre, en nombre de Jesús.<br/>',NULL,192401,2);
INSERT INTO stanza VALUES('S718','2','¡Estad por Cristo firmes!<br/>Os llama_a combatir;<br/>¡Con Él, pues, a la lucha,<br/>Soldados, todos, id!<br/>Probad que sois valientes<br/>Luchando contra el mal;<br/>Es fuerte el enemigo,<br/>Mas Cristo es sin igual.<br/>',NULL,192402,3);
INSERT INTO stanza VALUES('S718','3','¡Estad por Cristo firmes!<br/>Su fuerza es sin igual;<br/>Las armas de la carne,<br/>Todas fracasarán.<br/>Vestíos la armadura,<br/>Velad en oración,<br/>Y, frente a los peligros,<br/>Tendréis gran provisión.<br/>',NULL,192403,4);
INSERT INTO stanza VALUES('S718','4','¡Estad por Cristo firmes!<br/>Luchad hasta ganar;<br/>Hoy el grito es de guerra,<br/>Mañana, un son triunfal;<br/>De vida es la corona<br/>Que el vencedor tendrá;<br/>Y con el Rey de gloria<br/>Por siempre reinará.<br/>',NULL,192404,5);
INSERT INTO stanza VALUES('S719','1','¡Firmes y adelante!<br/>Marchen a luchar,<br/>Con la cruz de Cristo<br/>Que_adelante va.<br/>El supremo Jefe,<br/>Nos lleva_a pelear;<br/>Contra_el enemigo,<br/>¡Marchen a luchar!<br/>',NULL,192405,1);
INSERT INTO stanza VALUES('S719','chorus','¡Firmes y_adelante!<br/>Marchen a luchar,<br/>Con la cruz de Cristo<br/>Que_adelante va.<br/>',NULL,192406,2);
INSERT INTO stanza VALUES('S719','2','Jesús es el nombre<br/>Que hace al diablo huir;<br/>Entonces, soldados;<br/>¡A victoria id!<br/>Tiembla el infierno<br/>Por nuestro clamor:<br/>¡Entonad, hermanos,<br/>Voces de valor!<br/>',NULL,192407,3);
INSERT INTO stanza VALUES('S719','3','Se mueve potente<br/>La iglesia de Dios,<br/>Como gran armada,<br/>Y sin división.<br/>Somos sólo un Cuerpo,<br/>Y uno en comunión,<br/>Uno en fe y Espíritu,<br/>Uno en el Señor.<br/>',NULL,192408,4);
INSERT INTO stanza VALUES('S719','4','Tronos y dominios<br/>Han de fallecer;<br/>De Jesús, la iglesia<br/>Constante ha de ser.<br/>Las puertas del Hades<br/>No podrán ganar,<br/>Porque Su promesa<br/>Nunca fallará.<br/>',NULL,192409,5);
INSERT INTO stanza VALUES('S719','5','¡Pueblos, adelante!<br/>Con gozo marchad;<br/>Unamos las voces<br/>En canción triunfal.<br/>Ángeles y hombres,<br/>Dad a Cristo el Rey<br/>Gloria y alabanzas,<br/>Para siempre, amén.<br/>',NULL,192410,6);
INSERT INTO stanza VALUES('S720','1','Marchan hoy, marchan hoy,<br/>Las iglesias marchan hoy;<br/>Marchan en el Espíritu hoy.<br/>Marchan hoy, marchan hoy,<br/>Las iglesias marchan hoy;<br/>Marchan en el Espíritu hoy.<br/>Su recobro hoy<br/>En la_iglesia se ve,<br/>Y séptuple_es el Espíritu.<br/>Nuestro marchar,<br/>El mundo_ha de notar,<br/>¡El Señor hoy marchando está!<br/>',NULL,192411,1);
INSERT INTO stanza VALUES('S721','1','Buena batalla_hay que pelear,<br/>Cristo_es tu fuerza sin igual;<br/>La vida_asid, y_así será<br/>Gozo_y corona eternal.<br/>',NULL,192412,1);
INSERT INTO stanza VALUES('S721','2','Esta carrera corre ya,<br/>Fijos los ojos en Su faz;<br/>Cristo la vida y senda es,<br/>Cristo, el premio a obtener.<br/>',NULL,192413,2);
INSERT INTO stanza VALUES('S721','3','Toda preocupación dejad,<br/>Misericordia Cristo da;<br/>Confía en Él y gustarás<br/>Vida y amor que_es sin igual.<br/>',NULL,192414,3);
INSERT INTO stanza VALUES('S721','4','No desfallezcas, cerca está,<br/>Él nunca cambiará jamás;<br/>Tú solo cree y verás<br/>Tu todo_en todo Él será.<br/>',NULL,192415,4);
INSERT INTO stanza VALUES('S722','1','¡Santos, por Cristo luchad!<br/>¡Tomad Su vida_y, firmes, marchad!<br/>¡Nunca teman a Satán,<br/>Mas aplastadlo y triunfad!<br/>Por nuestra vida diaria, orad,<br/>Para en nuestro espíritu andar.<br/>¡Como nuevo_hombre luchad<br/>Cumpliendo así Su plan!<br/>(¡Gloria! ¡Aleluya!)<br/>',NULL,192416,1);
INSERT INTO stanza VALUES('S723','1','¡Soldados, a la carga!<br/>La guerra comenzó;<br/>Con la canción triunfante:<br/>¡Victoria se ganó!<br/>Destriudo el Hades;<br/>Vencido, Satanás.<br/>El Capitán muy pronto<br/>Triunfante volverá.<br/>',NULL,192417,1);
INSERT INTO stanza VALUES('S723','2','¡Soldados, a la carga!<br/>En el Señor confiad;<br/>Pelea en Su batalla<br/>Y el trono Él te dará.<br/>Pelea en espíritu,<br/>No es guerra terrenal;<br/>Sabe el Señor que el diablo<br/>Rodeándonos está.<br/>',NULL,192418,2);
INSERT INTO stanza VALUES('S723','3','¡Soldados, a la carga!<br/>El trono listo está.<br/>Su resurrección puede<br/>Tu espíritu librar.<br/>Por Cristo, fuerzas tienes<br/>Para al diablo aplastar;<br/>Por Él, canta victoria;<br/>Él te coronará.<br/>',NULL,192419,3);
INSERT INTO stanza VALUES('S723','4','¡Soldados, a la carga!<br/>Al trono has de ascender;<br/>Banquete Él te prepara,<br/>Feliz tú lo haces ser.<br/>Con Él, resucitado,<br/>La guerra abajo está;<br/>Trascendiendo todo,<br/>Con Él libre serás.<br/>',NULL,192420,4);
INSERT INTO stanza VALUES('S723','5','¡Soldados, a la carga!<br/>Noble heredero, tú;<br/>Te escogió del polvo<br/>A Su reino, Jesús.<br/>Brillante es tu futuro,<br/>Nada de oscuridad;<br/>Morando tú con Cristo,<br/>Su amor disfrutarás.<br/>',NULL,192421,5);
INSERT INTO stanza VALUES('S723','6','¡Con júbilo a la carga!<br/>Delante el reino está;<br/>Ganada la batalla,<br/>En Sion se cantará.<br/>¡Triunfante es el Cordero!<br/>¡Entronizado está!<br/>Con gritos lo alabamos,<br/>Pues siempre vencerá.<br/>',NULL,192422,6);
INSERT INTO stanza VALUES('S724','1','Si la guerra y Satán<br/>Fieros están,<br/>A la Palabra_asid;<br/>Con fe cantad.<br/>',NULL,192423,1);
INSERT INTO stanza VALUES('S724','2','Grita una sola vez,<br/>Y ganarás;<br/>No calles tu clamar,<br/>Pues perderás.<br/>',NULL,192424,2);
INSERT INTO stanza VALUES('S724','3','Si en tu espíritu<br/>Hoy no hay poder,<br/>Por la sangre, al orar,<br/>Podrás vencer.<br/>',NULL,192425,3);
INSERT INTO stanza VALUES('S724','4','Aunque es feroz Satán,<br/>Debes luchar;<br/>Si firme siempre estás,<br/>Has de ganar.<br/>',NULL,192426,4);
INSERT INTO stanza VALUES('S724','5','Que Cristo es vencedor<br/>Declara ya;<br/>La oscura situación<br/>Ha de cambiar.<br/>',NULL,192427,5);
INSERT INTO stanza VALUES('S725','1','No debo yo rendirme,<br/>Frente al Calvario_estoy,<br/>Donde Jesús triunfante<br/>Al diablo conquistó;<br/>Señor, te pido fuerzas,<br/>Visión para pelear;<br/>Por Tu Espíritu_hazme<br/>Un vencedor triunfal.<br/>',NULL,192428,1);
INSERT INTO stanza VALUES('S725','chorus','¡Triunfante, triunfante!<br/>Por el Calvario estoy.<br/>Hazme en Ti un vencedor<br/>Triunfante, triunfante_en Ti, Señor.<br/>',NULL,192429,2);
INSERT INTO stanza VALUES('S725','2','No debo yo rendirme<br/>Pues Cristo el Rey ganó<br/>La lucha tan temible<br/>A la cual me llamó.<br/>Señor, valor te pido,<br/>Y que el conquistador<br/>Espíritu de vida<br/>Me haga un vencedor.<br/>',NULL,192430,3);
INSERT INTO stanza VALUES('S725','3','No debo yo rendirme<br/>Cuando Él guiando está<br/>Por campos infernales<br/>Que al trono llevarán.<br/>Señor, a Tu soldado<br/>Poder le debes dar,<br/>La espada, Tu Palabra,<br/>Un vencedor me hará.<br/>',NULL,192431,4);
INSERT INTO stanza VALUES('S725','4','No debo yo rendirme,<br/>Viendo el atardecer;<br/>Jesús desea decirme:<br/>"Bien hecho, siervo fiel";<br/>Señor, Tu gloria muestra,<br/>Tu Espíritu y vigor<br/>Me infundan con la fuerza<br/>Que me haga un vencedor.<br/>',NULL,192432,5);
INSERT INTO stanza VALUES('S726','1','Mi palabra al enemigo es: "No",<br/>Mas al Padre digo:_"Amén",<br/>Para que Su plan se cumpla<br/>Su consejo seguiré.<br/>Cuando cumpla Tus mandatos<br/>Dame, Dios, Tu_autoridad;<br/>Y Tu_Espíritu me ayude<br/>A ejecutar Tu plan.<br/>',NULL,192433,1);
INSERT INTO stanza VALUES('S726','2','Mi palabra al enemigo es: "No",<br/>Mas al Padre digo "Amén".<br/>Es mi actitud eterna,<br/>Que el Señor conmigo esté.<br/>Para que cuando obedezca<br/>No interfiera Satanás;<br/>Cuando escuche Tus mandatos<br/>Cúbreme con Tu piedad.<br/>',NULL,192434,2);
INSERT INTO stanza VALUES('S726','3','Mi palabra al enemigo es: "No",<br/>Mas al Padre digo "Amén".<br/>Aunque oprima el sufrimiento<br/>En todo obedeceré.<br/>Si el Señor me salva y guarda<br/>Mientras yo le sigo fiel,<br/>No me pueden los ataques<br/>Ni las pruebas detener.<br/>',NULL,192435,3);
INSERT INTO stanza VALUES('S727','1','Escudo_y Defensor, nuestro Reposo;<br/>No vamos solos contra Satanás;<br/>Nos das Tu fuerza_y Tu tierno cuidado,<br/>Y en Tu nombre hemos de avanzar.<br/>Nos das Tu fuerza_y Tu tierno cuidado,<br/>Y en Tu nombre hemos de avanzar.<br/>',NULL,192436,1);
INSERT INTO stanza VALUES('S727','2','Sí, Capitan de Salvación, Tu nombre,<br/>Que sobre todo otro nombre es;<br/>//Nuestra Justicia, nuestro Fundamento,<br/>Señor de gloria y nuestro Rey de amor.//<br/>',NULL,192437,2);
INSERT INTO stanza VALUES('S727','3','No somos fuertes, mas por fe andamos;<br/>Tu gracia conocemos más y más;<br/>//Del corazón brota canción triunfante,<br/>Y en Tu nombre hemos de avanzar.//<br/>',NULL,192438,3);
INSERT INTO stanza VALUES('S727','4','Escudo y Defensor, nuestro Reposo,<br/>Es Tuya la batalla y el loor;<br/>//Has de reinar en esplendor triunfante;<br/>Victoria y Reposo nos serás.//<br/>',NULL,192439,4);
INSERT INTO stanza VALUES('S728','1','Soldados, hijos de la luz, ¡banderas levantad!<br/>Devotos del Señor Jesús, la guerra_apresurad;<br/>Para que ese vil rival se pueda subyugar;<br/>Ten fe_en Aquel que ya venció, victoria_así lograd.<br/>',NULL,192440,1);
INSERT INTO stanza VALUES('S728','chorus','¡Fe la victoria es!<br/>¡Fe la victoria es!<br/>Gloriosa victoria que<br/>Al mundo vence ya.<br/>',NULL,192441,2);
INSERT INTO stanza VALUES('S728','2','Hoy Su bandera de amor es para batallar,<br/>Y la Palabra fiel de Dios, la espada, hay que emplear;<br/>Marchemos por la senda en que los santos del ayer<br/>Triunfantes fueron por la fe, la muerte aun al vencer.<br/>',NULL,192442,3);
INSERT INTO stanza VALUES('S728','3','Dejemos toda languidez, ¡cerca el peligró está!<br/>Tomemos "yelmo de salud", "ceñidos ... de verdad"<br/>"Del evangelio de la paz" calcémonos los pies,<br/>En "cota de justicia" andar, y "escudo" alzar "de fe".<br/>',NULL,192443,4);
INSERT INTO stanza VALUES('S728','4','"Al que venciere" se dará ropaje blanco en luz;<br/>¡Qué galardón! Confesará su nombre allí, Jesús;<br/>Resueltos, adelante hoy id y a Cristo ensalzad;<br/>Su encargo de amor cumplid, victoria así lograd.<br/>',NULL,192444,5);
INSERT INTO stanza VALUES('S728','note','**1958; EMAD en el "Himnario de los Mensajes del Amor de Dios".**<br/>',NULL,192445,6);
INSERT INTO stanza VALUES('S729','1','Lucha siempre en el Cuerpo,<br/>Por tu cuenta no podrás;<br/>Sólo_unido a la Cabeza,<br/>Desde_el trono vencerás.<br/>',NULL,192446,1);
INSERT INTO stanza VALUES('S729','chorus','Lucha siempre en el Cuerpo,<br/>La Cabeza da el poder;<br/>Sólo firme en el Cuerpo,<br/>La victoria podrás ver.<br/>',NULL,192447,2);
INSERT INTO stanza VALUES('S729','2','La armadura es para el Cuerpo,<br/>No es con fin individual;<br/>Cuando luchas en el Cuerpo<br/>El provecho es total.<br/>',NULL,192448,3);
INSERT INTO stanza VALUES('S729','3','A la iglesia firme en Cristo<br/>Satanás no vencerá;<br/>Es el Cuerpo edificado<br/>Quien al mal resistirá.<br/>',NULL,192449,4);
INSERT INTO stanza VALUES('S729','4','Con el Cuerpo y la Cabeza,<br/>Desde el trono celestial,<br/>Lucha en contra del maligno,<br/>Y los príncipes del mal.<br/>',NULL,192450,5);
INSERT INTO stanza VALUES('S729','5','Con los miembros en el Cuerpo,<br/>Para Dios firme has de estar;<br/>En tu espíritu orando,<br/>Por la sangre triunfarás.<br/>',NULL,192451,6);
INSERT INTO stanza VALUES('S729','6','En lugares celestiales<br/>Con Su fuerza y Su vigor,<br/>Como todo un reclutado,<br/>Lucha y vence en el Señor.<br/>',NULL,192452,7);
INSERT INTO stanza VALUES('S729','7','Sigue luchando en el Cuerpo,<br/>La victoria obtendrás;<br/>Desatando y atando,<br/>El rival será tu pan.<br/>',NULL,192453,8);
INSERT INTO stanza VALUES('S730','1','Castillo fuerte_es nuestro Dios,<br/>Defensa y buen Escudo;<br/>Con Su poder nos librará<br/>En todo trance_agudo.<br/>Con furia_y con afán<br/>Acosa Satanás;<br/>Sus armas deja ver,<br/>Astucia y gran poder;<br/>Cual él no_hay en la tierra.<br/>',NULL,192454,1);
INSERT INTO stanza VALUES('S730','2','Nuestro valor no es nada aquí,<br/>Con él todo es perdido;<br/>Mas por nosotros pugnará<br/>De Dios, el Escogido.<br/>¿Sabéis quién es? ¡Jesús!<br/>El que venció en la cruz,<br/>Dios fuerte y Señor<br/>De los ejércitos;<br/>El triunfa en la batalla.<br/>',NULL,192455,2);
INSERT INTO stanza VALUES('S730','3','Aunque estén demonios mil<br/>Pronto a devorarnos,<br/>No temeremos, porque Dios<br/>Sabrá aún prosperarnos.<br/>Que muestre su vigor<br/>Satán, y su furor;<br/>Dañarnos no podrá;<br/>Pues condenado es ya<br/>Por la Palabra Santa.<br/>',NULL,192456,3);
INSERT INTO stanza VALUES('S730','4','Esta Palabra durará<br/>Aún cuando el mundo pase.<br/>Los dones y el Espíritu<br/>Nos dio Dios como base.<br/>Se debe abandonar<br/>Lo bueno y lo mortal:<br/>Nos pueden hoy matar;<br/>Mas Dios y la verdad<br/>Han de reinar por siempre.<br/>',NULL,192457,4);
INSERT INTO stanza VALUES('S731','1','El nombre del Señor Jesús<br/>Nuestra firmeza es;<br/>Confiamos sólo en Ti, Señor,<br/>No en nuestro poder.<br/>Las armas no de carne son,<br/>Mas del Espíritu;<br/>Con la_armadura de Dios, hoy<br/>Nos haces vencer, Tú.<br/>',NULL,192458,1);
INSERT INTO stanza VALUES('S731','2','Por esa astucia de Satán,<br/>¡Es un acuerdo estad!<br/>Aunque la lucha cruenta es,<br/>En el Señor pelead.<br/>Si uno se retira, él<br/>Traiciona a los demás.<br/>No falles a los santos, tú,<br/>Ni aumentes su penar.<br/>',NULL,192459,2);
INSERT INTO stanza VALUES('S731','3','El diablo sabe que su fin<br/>Muy pronto ha de llegar;<br/>Trama agotar a muchos hoy,<br/>Y busca desgastar.<br/>Las pruebas más severas son;<br/>La lucha, más atroz;<br/>Y el poder de Satanás<br/>Se vuelve más feroz.<br/>',NULL,192460,3);
INSERT INTO stanza VALUES('S731','4','Oh, ¿qué postura hay que tomar?<br/>¡La hora_es tan crucial!<br/>¿Deleites y comodidad?<br/>¿Vencidos por Satán?<br/>O el conflicto, al crecer,<br/>¿Nos fortalecerá?<br/>¡De vida o muerte esto es!<br/>¿A quién Dios premiará?<br/>',NULL,192461,4);
INSERT INTO stanza VALUES('S731','5','Por Cristo firmes hay que estar;<br/>Él es Conquistador.<br/>Hasta el final hay que aguantar<br/>Por Él cualquier dolor.<br/>El triunfo pronto llegará,<br/>Y Cristo volverá;<br/>So hoy sufrimos por Su bien,<br/>Él nos hará reinar.<br/>',NULL,192462,5);
INSERT INTO stanza VALUES('S732','1','Soldados del Señor,<br/>Vuestra_armadura hoy<br/>Vestid con el poder de Dios,<br/>Que suple Su vigor;<br/>Sed fuertes por la fe<br/>En el poder de Dios;<br/>Aque que confíe_en Jesús<br/>Será un vencedor.<br/>',NULL,192463,1);
INSERT INTO stanza VALUES('S732','2','Firmes en Su poder<br/>Y en Su potestad;<br/>Toda la armadura de Dios<br/>Tomad para pelear;<br/>Después de acabar<br/>Y en todo triunfar,<br/>En Cristo podremos vencer<br/>Y firmes siempre estar.<br/>',NULL,192464,2);
INSERT INTO stanza VALUES('S732','3','Todo fortaleced,<br/>El alma hay que cubrir;<br/>Cubrid toda debilidad<br/>Con gracia y poder.<br/>Brillante mantendrás<br/>Tu armadura aquí;<br/>Andando con tu Capitán,<br/>Velad y orad así.<br/>',NULL,192465,3);
INSERT INTO stanza VALUES('S732','4','"Orad", pues, "sin cesar",<br/>Ordena el Capitán;<br/>Con gozo, a Él obedeced<br/>Y Su nombre invocad:<br/>Dadle a saber a Dios<br/>Toda ansiedad y afán;<br/>Orad, orad, sin desmayar;<br/>Orad, pues, sin cesar.<br/>',NULL,192466,4);
INSERT INTO stanza VALUES('S732','5','Con fuerza y poder,<br/>¡Seguid, luchad y orad!<br/>Las potestades derribad,<br/>Hasta el laurel ganar:<br/>Clamad, oh tropas: "Ven",<br/>Por el Espíritu,<br/>Hasta que venga el Señor<br/>Y reine aquí Jesús.<br/>',NULL,192467,5);
INSERT INTO stanza VALUES('S733','1','Por la sangre del Invicto<br/>Al enemigo venced;<br/>La victoria ganaremos<br/>En virtud de su poder.<br/>',NULL,192468,1);
INSERT INTO stanza VALUES('S733','chorus','Por la sangre del Invicto<br/>Al enemigo venced<br/>La victoria ganaremos<br/>En virtud de su poder.<br/>',NULL,192469,2);
INSERT INTO stanza VALUES('S733','2','Por la sangre del Invicto<br/>Vence al acusador;<br/>Por la sangre que defiende<br/>Rechaza al difamador.<br/>',NULL,192470,3);
INSERT INTO stanza VALUES('S733','3','Por la sangre del Invicto<br/>Cree en Su fidelidad;<br/>Por Su sangre redentora,<br/>El perdón de Dios tomad.<br/>',NULL,192471,4);
INSERT INTO stanza VALUES('S733','4','Por la sangre del Invicto<br/>Firme está tu posición;<br/>Por Su sangre vencedora<br/>La victoria es tu porción.<br/>',NULL,192472,5);
INSERT INTO stanza VALUES('S733','5','Por la sangre del Invicto<br/>Tuya es Su autoridad;<br/>De Jesús, la sangre aplica<br/>Y al diablo vencerás.<br/>',NULL,192473,6);
INSERT INTO stanza VALUES('S733','6','Por la sangre del Invicto<br/>En los cielos firme estad;<br/>Con el Cristo ascendido<br/>Potestades aplastad.<br/>',NULL,192474,7);
INSERT INTO stanza VALUES('S734','1','¡Cristo es el victorioso!<br/>Dilo con fervor.<br/>¡De la muerte y del pecado<br/>Cristo es Vencedor!<br/>',NULL,192475,1);
INSERT INTO stanza VALUES('S734','chorus','¡Aleluya! ¡Victorioso!<br/>Dilo por doquier;<br/>Sobre todo enemigo<br/>Vencedor es Él.<br/>',NULL,192476,2);
INSERT INTO stanza VALUES('S734','2','¡Cristo es el victorioso!<br/>¡Fuera enfermedad!<br/>Su victoria en el Calvario<br/>Puedes reclamar.<br/>',NULL,192477,3);
INSERT INTO stanza VALUES('S734','3','¡Cristo es el victorioso!<br/>Ora con poder;<br/>Por doquiera que Él te mande,<br/>Ve confiando en Él.<br/>',NULL,192478,4);
INSERT INTO stanza VALUES('S734','4','¡Cristo es el victorioso!<br/>Fallas ni temor<br/>Nunca deben detenerte;<br/>Sigue la visión.<br/>',NULL,192479,5);
INSERT INTO stanza VALUES('S734','5','¡Cristo es el victorioso!<br/>Pronto clamará:<br/>"Vengan Mis conquistadores,<br/>Con su Rey reinad!".<br/>',NULL,192480,6);
INSERT INTO stanza VALUES('S735','1','¡Victoria hay! ¡Cristo_ha vencido todo mal!<br/>¡Victoria suena por todo lugar!<br/>La sangre de Jesús nos da victoria, ¡sí!<br/>El Victorioso pronto volverá.<br/>',NULL,192481,1);
INSERT INTO stanza VALUES('S735','note','**Hermanas:**<br/>',NULL,192482,2);
INSERT INTO stanza VALUES('S735','chorus','¡Victoria hay, santos hermanos!<br/>¡Esta victoria celebrad!<br/>Llenad la tierra de alabanzas,<br/>Y desde Sion hoy proclamad.<br/>',NULL,192483,3);
INSERT INTO stanza VALUES('S735','note','**Hermanos:**<br/>',NULL,192484,4);
INSERT INTO stanza VALUES('S735','chorus','¡Victoria hay, santas hermanas!<br/>¡Su obra, Cristo consumó!<br/>Él ha ganado nuestra victoria:<br/>El gozo eterno comenzó.<br/>',NULL,192485,5);
INSERT INTO stanza VALUES('S735','2','¡Victoria hay! ¡Hemos vencido a Satán!<br/>De la Palabra, testimonio dad;<br/>En ella está la vida y la libertad;<br/>Por ella, desafiamos a Satán.<br/>',NULL,192486,6);
INSERT INTO stanza VALUES('S735','3','¡Victoria hay! ¡Hollado el enemigo está!<br/>La vida de vuestra alma rechazad;<br/>Gritad: "¡Señor, nuestra victoria eres Tú!"<br/>En el espíritu, hoy alabad.<br/>',NULL,192487,7);
INSERT INTO stanza VALUES('S736','1','Tus siervos lucharán<br/>A diario, fervorosos;<br/>Su_espíritu, gozoso,<br/>Señor, te_escucharán.<br/>Siguiendo al Capitán,<br/>Tus tropas marcharán.<br/>',NULL,192488,1);
INSERT INTO stanza VALUES('S736','chorus','¡Danos poder!<br/>¡Haznos arder!<br/>Para en Tu nombre hoy vencer,<br/>Para en Tu nombre hoy vencer,<br/>¡Danos poder! ¡Haznos arder!<br/>',NULL,192489,2);
INSERT INTO stanza VALUES('S736','2','Equípanos, Señor,<br/>Con Tu perseverancia,<br/>Prudencia y constancia,<br/>Con vista al galardón;<br/>Enciéndenos, Señor,<br/>Con celo y amor.<br/>',NULL,192490,3);
INSERT INTO stanza VALUES('S736','3','Alzamos hoy la cruz,<br/>Glorioso estandarte;<br/>Confiamos en Tu sangre,<br/>Que a Satán venció.<br/>La cruz termina el yo;<br/>¡Confiad en el Señor!<br/>',NULL,192491,4);
INSERT INTO stanza VALUES('S736','4','¡Luchad, sufrid y orad!<br/>Habrá al final victoria;<br/>La corona de gloria,<br/>Nuestro Señor dará.<br/>¡Luchad, sufrid y orad,<br/>Para con Él reinar!<br/>',NULL,192492,5);
INSERT INTO stanza VALUES('S737','1','Al Cristo en resurrección<br/>Se le dio toda potestad;<br/>Viviendo en unidad con Él,<br/>Subyugaremos a Satán.<br/>',NULL,192493,1);
INSERT INTO stanza VALUES('S737','2','Clamando el nombre de Jesús,<br/>Al enemigo vencerás;<br/>Tomando Su autoridad,<br/>A la serpiente aplastarás.<br/>',NULL,192494,2);
INSERT INTO stanza VALUES('S737','3','No importa, monte, que alto estés,<br/>En tierra o en cielo, tú;<br/>Allanaremos tu altivez<br/>Hoy en el nombre de Jesús.<br/>',NULL,192495,3);
INSERT INTO stanza VALUES('S737','4','La fe te ordena: ¡Quítate<br/>De aquí y échate al mar!"<br/>Seremos fieles al cumplir<br/>El plan de Dios con lealtad.<br/>',NULL,192496,4);
INSERT INTO stanza VALUES('S738','1','Hay un conflicto hoy,<br/>Y_ataca Satanás;<br/>El grito de la guerra aquí<br/>Creciendo siempre_está.<br/>Esa voz infernal<br/>Más fuerte_es cada vez;<br/>Empero ya suena el clamor;<br/>¡He_aquí, pronto vendré!<br/>',NULL,192497,1);
INSERT INTO stanza VALUES('S738','2','Crece la lucha hoy,<br/>Y amargas pruebas hay.<br/>Se arremolinan a pelear<br/>Las fuerzas de maldad.<br/>¡Velad y esperad!<br/>La guerra cruenta está,<br/>Mas se oye la triunfal canción:<br/>¡Jesús pronto vendrá!<br/>',NULL,192498,2);
INSERT INTO stanza VALUES('S738','3','Ahora en el final<br/>Duro es testificar;<br/>Pues quiere el diablo destruir<br/>El testimonio real.<br/>Para poder vencer<br/>Más fuerza hay que cobrar;<br/>¡Cuando veamos al Señor,<br/>El llanto cesará!<br/>',NULL,192499,3);
INSERT INTO stanza VALUES('S738','4','¿Quién fiel proseguirá,<br/>Vestido de poder?<br/>¿Quién confiará en el Señor<br/>Hasta Su triunfo ver?<br/>Tendrá tal vencedor<br/>Esta triunfal canción,<br/>Que él un día escuchará:<br/>¡He aquí, viene el Señor!<br/>',NULL,192500,4);
INSERT INTO stanza VALUES('S738','5','¿Quién querrá elegir<br/>La senda angosta andar,<br/>Pasar la tempestad feroz,<br/>Mas sin mirar atrás?<br/>¿Quién adelante irá<br/>Aunque sufra dolor?<br/>El tal se gozará al ver<br/>Que cerca está el Señor.<br/>',NULL,192501,5);
INSERT INTO stanza VALUES('S738','6','Aunque haya oscuridad<br/>Marchamos sin parar,<br/>Hasta que el día del Señor<br/>Se pueda saludar.<br/>En gloria y comunión,<br/>Vencido Satanás,<br/>Los vencedores cantarán:<br/>¡Jesús reinando está!<br/>',NULL,192502,6);
INSERT INTO stanza VALUES('S739','1','¿Eres de los vencedores?<br/>¡Cristo llama hoy!<br/>Sin saber cómo seguirlo,<br/>¿Quieres ir en pos?<br/>',NULL,192503,1);
INSERT INTO stanza VALUES('S739','chorus','¿Eres de los vencedores?<br/>¿Seguirás en pos?<br/>Cristo llama, Cristo llama,<br/>¡Escuchad Su voz!<br/>',NULL,192504,2);
INSERT INTO stanza VALUES('S739','2','¿Eres de los vencedores?<br/>¡Busca al Señor!<br/>Hasta que Él nos lleve, guarda<br/>Tu primer amor.<br/>',NULL,192505,3);
INSERT INTO stanza VALUES('S739','3','¿Eres de los vencedores?<br/>Su vida eternal<br/>En persecución o muerte<br/>Tu sostén será.<br/>',NULL,192506,4);
INSERT INTO stanza VALUES('S739','4','¿Eres de los vencedores?<br/>Testimonio da.<br/>Huye de las herejías,<br/>Come del maná.<br/>',NULL,192507,5);
INSERT INTO stanza VALUES('S739','5','¿Eres de los vencedores,<br/>Simple, puro, y real?<br/>Purga toda levadura<br/>Para así reinar.<br/>',NULL,192508,6);
INSERT INTO stanza VALUES('S739','6','¿Eres de los vencedores?<br/>¡Vive en el Señor!<br/>Sin "manchar tus vestiduras"<br/>Con la muerte atroz.<br/>',NULL,192509,7);
INSERT INTO stanza VALUES('S739','7','¿Eres de los vencedores?<br/>¡Nunca tibio estés!<br/>No te sientas complacido,<br/>Busca más de Él.<br/>',NULL,192510,8);
INSERT INTO stanza VALUES('S739','8','¿Eres de los vencedores?<br/>¿Le serás leal?<br/>¿Cumplirás lo que Él exige,<br/>Su llamado real?<br/>',NULL,192511,9);
INSERT INTO stanza VALUES('S740','1','Hoy la visión tenemos,<br/>La meta clara_está;<br/>Cristo venció al diablo,<br/>La muerte y_el pecar.<br/>Hay un camino_abierto,<br/>Las sendas rectas son;<br/>Oímos el llamado:<br/>¡Hoy acerquémonos!<br/>',NULL,192512,1);
INSERT INTO stanza VALUES('S740','chorus','¡Acérquense, santos!<br/>Cristo_en el trono está.<br/>Su ministerio celestial,<br/>Las tropas traerá a su hogar.<br/>',NULL,192513,2);
INSERT INTO stanza VALUES('S740','2','Hoy la visión tenemos:<br/>Cristo el Conquistador<br/>Nos llama_a la batalla<br/>Que sólo Él ganó.<br/>Ya, hace dos mil años,<br/>Su triunfo Él legó<br/>A todos los guerreros<br/>Que van con Él en pos.<br/>',NULL,192514,3);
INSERT INTO stanza VALUES('S740','3','Hoy la visión tenemos:<br/>Seguimos a Jesús,<br/>Nos lleva a Su trono<br/>En nuestro espíritu.<br/>Nos dio Jesús  las armas:<br/>Su Espíritu vital,<br/>La iglesia y Su palabra,<br/>Que nos hacen triunfar.<br/>',NULL,192515,4);
INSERT INTO stanza VALUES('S741','1','La fe que transmitida fue<br/>A santos del ayer,<br/>Hoy a nosotros se confió,<br/>Para guardarla fiel.<br/>',NULL,192516,1);
INSERT INTO stanza VALUES('S741','chorus','Y sabemos en quien creímos,<br/>Que Él es fiel y es poderoso<br/>En guardar lo encomendado<br/>Por Su santo_Espíritu.<br/>',NULL,192517,2);
INSERT INTO stanza VALUES('S741','2','Hoy este buen depósito<br/>El objeivo es<br/>De la esconomía de Dios,<br/>Y Su recobro fiel.<br/>',NULL,192518,3);
INSERT INTO stanza VALUES('S741','3','La fe común requiere hoy<br/>Conciencia pura hallar,<br/>Y un vivir para el Señor<br/>Que sea con santidad.<br/>',NULL,192519,4);
INSERT INTO stanza VALUES('S741','4','Palabras sanas, en amor<br/>Y en fe hay que guardar;<br/>Mas enseñanzas de error,<br/>Con fuerza rechazad.<br/>',NULL,192520,5);
INSERT INTO stanza VALUES('S741','5','¡Oh, las palabras sanas son<br/>Verdad de la piedad!<br/>La fe, el buen depósito,<br/>Y vida en santidad.<br/>',NULL,192521,6);
INSERT INTO stanza VALUES('S741','6','Oh, haznos fieles en pasar<br/>Lo que se oyó, Señor;<br/>Ejemplos en espíritu,<br/>Palabra, fe y amor.<br/>',NULL,192522,7);
INSERT INTO stanza VALUES('S742','1','Nos llama el Señor<br/>En la iglesia hoy<br/>A laborar, laborar, laborar en Él.<br/>Hoy Cristo es Canaán,<br/>En Cristo firme estad<br/>Al laborar, laborar, laborar en Él.<br/>',NULL,192523,1);
INSERT INTO stanza VALUES('S742','chorus','"¡Santos, proseguid! ¡Victoriosos, id!"<br/>Clama nuestro Capitán.<br/>Hemos de_obedecer,<br/>La tierra_a poseer<br/>Al laborar, laborar, laborar en Él.<br/>',NULL,192524,2);
INSERT INTO stanza VALUES('S742','2','El plan que Dios trazó<br/>Para nuestra labor.<br/>Decir Amén a Su hablar, Su Palabra fiel.<br/>Nos habla el Señor;<br/>¡Atentos a Su voz,<br/>Diciendo Amén a Su hablar, Su Palabra fiel!<br/>',NULL,192525,3);
INSERT INTO stanza VALUES('S742','chorus','"¡Santos, proseguid! ¡Victoriosos, id!"<br/>Clama nuestro Capitán.<br/>Hemos de obedecer,<br/>La tierra a poseer<br/>Diciendo Amén a Su hablar, Su Palabra fiel.<br/>',NULL,192526,4);
INSERT INTO stanza VALUES('S742','3','Y para poseer<br/>La tierra es menester<br/>El ir en pos, ir en pos de la iglesia hoy.<br/>Su Espíritu fluirá,<br/>El Cuerpo seguirá,<br/>Al ir en pos, ir en pos de la iglesia hoy.<br/>',NULL,192527,5);
INSERT INTO stanza VALUES('S742','chorus','"¡Santos, proseguid! ¡Victoriosos, id!"<br/>Clama nuestro Capitán.<br/>Hemos de obedecer,<br/>La tierra a poseer<br/>Al ir en pos, ir en pos de la iglesia hoy.<br/>',NULL,192528,6);
INSERT INTO stanza VALUES('S743','1','Tomemos hoy la tierra que Dios nos legó,<br/>Viviendo_a Cristo_en todo nuestro_andar;<br/>Nos equipo: la sangre, la Palabra fiel,<br/>Su_Espíritu,_y la iglesia nuestros son.<br/>',NULL,192529,1);
INSERT INTO stanza VALUES('S743','note','**Hermanas:**<br/>',NULL,192530,2);
INSERT INTO stanza VALUES('S743','chorus','¡Hay que tomar la tierra,_hermanos,<br/>La tierra que Dios nos legó!<br/>¡Oh, sed valientes, sin deteneros,<br/>Para ganar la tierra hoy!<br/>',NULL,192531,3);
INSERT INTO stanza VALUES('S743','note','**Hermanos:**<br/>',NULL,192532,4);
INSERT INTO stanza VALUES('S743','chorus','¡Hay que tomar la tierra,_hermanas!<br/>A esto pongan atención:<br/>¡Llegó la hora! Dios nos implora,<br/>Pues todo ya nos proveyó.<br/>',NULL,192533,5);
INSERT INTO stanza VALUES('S743','2','Tenemos hoy la sangre del Señor Jesús,<br/>El mismo es nuestra ofrenda para Dios;<br/>Venimos con confianza al trono de la gracia<br/>Por la sangre que Jesús vertió.<br/>',NULL,192534,6);
INSERT INTO stanza VALUES('S743','3','Tenemos la Palabra escrita del Señor;<br/>Comámosla con fe diciendo: "Amén!"<br/>Así durante el día nos regulará<br/>Con la Palabra viva en nuestro ser.<br/>',NULL,192535,7);
INSERT INTO stanza VALUES('S743','4','Tenemos el Espíritu de realidad<br/>Independiente de nuestro sentir;<br/>El nos habita y nos guía a la verdad<br/>Y nos enseña a morar en Él.<br/>',NULL,192536,8);
INSERT INTO stanza VALUES('S743','5','Tenemos hoy la iglesia para poseer<br/>La plenitud de esta realidad;<br/>El Cristo todo-inclusivo hay que ganar,<br/>Y Él será el todo en nuestro andar.<br/>',NULL,192537,9);
INSERT INTO stanza VALUES('S744','1','La obra_es Tuya, oh Señor,<br/>Y nuestra causa es;<br/>Y por ser Tuya, vencerá<br/>Rivales por doquier.<br/>Mas sepultado debe ser<br/>El grano antes de crecer;<br/>Lo viejo así perecerá<br/>Y nueva vida brotará;<br/>Así nos libras del yo y_el pecar.<br/>',NULL,192538,1);
INSERT INTO stanza VALUES('S744','2','Sufriste, Cristo, hasta llegar<br/>Al trono celestial,<br/>Y a Tus fieles guiarás<br/>Por un camino igual;<br/>Condúcenos, pese al sufrir,<br/>Para Tu reino compartir;<br/>Tu muerte quebrantó a Satán<br/>Y a la luz nos guía ya;<br/>De las tinieblas a eterna luz.<br/>',NULL,192539,2);
INSERT INTO stanza VALUES('S744','3','Abriste el camino Tú<br/>Por muerte y aflicción;<br/>¡Oh, danos más Tu Espíritu,<br/>Tu aliento vivo hoy!<br/>Tus mensajeros traerán<br/>Tus escogidos a Tu faz;<br/>Tu nombre trae salvación,<br/>A Ti nos consagramos hoy,<br/>Tus siervos y guerreros seremos.<br/>',NULL,192540,3);
INSERT INTO stanza VALUES('S745','1','Tenemos un glorioso Rey,<br/>Su tronó_en los cielos está;<br/>Los mundos son todos de Él,<br/>Los reinos, Su cetro verán.<br/>Él mora con Su pueblo_aquí,<br/>En pruebas socorro les da;<br/>Por Su_obra moramos con Él,<br/>Su carga nos gusta llevar.<br/>',NULL,192541,1);
INSERT INTO stanza VALUES('S745','2','Yo moro con mi Rey Jesús;<br/>Junto con los Suyos está;<br/>Abriéndole mí corazón,<br/>Su templo y Su trono será.<br/>Así cual María a Sus pies,<br/>Me inclino en Su pecho cual Juan;<br/>¡Qué gozo Su presencia trae!<br/>Su seno es descanso eternal.<br/>',NULL,192542,2);
INSERT INTO stanza VALUES('S745','3','Por Su obra yo moro con El;<br/>Comparto en Su glorioso plan,<br/>Su reino a la tierra traer<br/>Y Su salvación proclamar.<br/>El mundo con Su galardón<br/>Por pérdida lo he de contar;<br/>Su obra es mi único afán,<br/>Su cruz mi mensaje total.<br/>',NULL,192543,3);
INSERT INTO stanza VALUES('S745','4','Por Su obra yo moro con Él,<br/>Es Suya y mía no es;<br/>La traza y prepara por mí,<br/>Llenándome con Su poder.<br/>En gozo se cambia el deber,<br/>Se hace alabanza el orar;<br/>Por Su obra yo moro con Él<br/>Obrando en la fuerza del Rey.<br/>',NULL,192544,4);
INSERT INTO stanza VALUES('S745','5','Por Su obra moramos con Él<br/>Y obramos con Èl sin cesar;<br/>Muy pronto vendrá nuestro Rey,<br/>En gloria se aparecerá.<br/>Y así en más íntima unión<br/>La obra más noble será;<br/>Moraremos con nuestro Rey<br/>Por Su obra en un gozo eternal.<br/>',NULL,192545,5);
INSERT INTO stanza VALUES('S746','1','No donde_elijamos ir,<br/>Mas donde guie Jesús;<br/>El fluir se halla_allí,<br/>Y la noche cambia_a luz.<br/>',NULL,192546,1);
INSERT INTO stanza VALUES('S746','2','No aprobará el Señor<br/>La obra de nuestra elección,<br/>Mas la que nos asignó<br/>Le traerá satisfacción.<br/>',NULL,192547,2);
INSERT INTO stanza VALUES('S746','3','No es aquella oración<br/>Que queramos suplicar,<br/>Mas el profundo gemir<br/>Que el Espíritu nos da.<br/>',NULL,192548,3);
INSERT INTO stanza VALUES('S746','4','Ni una ofrenda aceptará<br/>Cuando en altivez se da,<br/>Si hemos respondido: "No",<br/>A Su quieto susurrar.<br/>',NULL,192549,4);
INSERT INTO stanza VALUES('S746','5','Al morir a nuestro yo,<br/>Viviremos hoy con Dios;<br/>Y al servir, orar y dar,<br/>Cristo es nuestro Galardón.<br/>',NULL,192550,5);
INSERT INTO stanza VALUES('S747','1','En el Nuevo Testamento<br/>El Espíritu_es vital;<br/>Nos da vida fresca_y nueva<br/>Mas la letra matará.<br/>Dios no cuenta la_obra externa,<br/>Sino lo del interior;<br/>No_es servir según la letra,<br/>Sino vida_impartir hoy.<br/>',NULL,192551,1);
INSERT INTO stanza VALUES('S747','2','No solo enseñanza externa,<br/>Mas guiados por la unción;<br/>No sirviendo por lo externo,<br/>Mas por la interna visión;<br/>No por reglas de los hombres,<br/>Mas la interna y celestial;<br/>No por decisión humana,<br/>Mas por Su interno guiar.<br/>',NULL,192552,2);
INSERT INTO stanza VALUES('S747','3','No la religión sirviendo,<br/>Mas a Cristo hay que vivir;<br/>No enseñando teología,<br/>Mas Su vida impartir;<br/>No tan sólo las doctrinas,<br/>Mas a Cristo predicar;<br/>No los dones o los ritos,<br/>Sino Cristo en realidad.<br/>',NULL,192553,3);
INSERT INTO stanza VALUES('S747','4','No la adoración externa,<br/>Más la interna realidad;<br/>No del Cristo objetivo,<br/>Mas del Subjetivo hablar;<br/>No tan sólo la Escritura,<br/>Mas espíritu y verdad;<br/>No en la carne esforzados,<br/>Mas sirviendo en novedad.<br/>',NULL,192554,4);
INSERT INTO stanza VALUES('S748','1','Sólo en el fluir, laboremos por Dios,<br/>Por Su mente,_en Su forma, como Él reveló;<br/>Obrando_en el fluir de Su vida y poder,<br/>Por Su Reino, Su_iglesia, en Su_actual mover.<br/>',NULL,192555,1);
INSERT INTO stanza VALUES('S748','chorus','¡Sólo en el fluir!<br/>¡Laboremos por Dios!<br/>¡Sólo en el fluir!<br/>¡Laboremos en coordinación!<br/>',NULL,192556,2);
INSERT INTO stanza VALUES('S748','2','Sólo en el fluir, laboremos con Dios,<br/>En el Espíritu como Él lo enseñó;<br/>Nunca independiente, obrando en el yo,<br/>Mas en cuanto al servicio: en coordinación.<br/>',NULL,192557,3);
INSERT INTO stanza VALUES('S748','3','Sólo en el fluir, laboremos en Dios,<br/>Con la iglesia, los santos, conforme a Su luz;<br/>La palabra de vida a todos brindad,<br/>Y seguid Su fluir realizando Su plan.<br/>',NULL,192558,4);
INSERT INTO stanza VALUES('S749','1','La vida_interna al rebosar<br/>Resulta_en nuestra obra.<br/>Sólo_un mensaje hay que dar:<br/>Nuestra viva_experiencia.<br/>Cuando_el vivir y_el trabajar<br/>Son una misma cosa,<br/>Entonces la predicación<br/>Podrá ser muy fructuosa.<br/>',NULL,192559,1);
INSERT INTO stanza VALUES('S749','2','Sólo es por el Espíritu<br/>La obra y el producto;<br/>Como las ramas en la vid<br/>Por vida llevan fruto.<br/>Cristo trabaja en nuestro ser,<br/>En vida es expresado,<br/>Y Sus riquezas se verán<br/>Al ser manifestado.<br/>',NULL,192560,2);
INSERT INTO stanza VALUES('S749','3','No es del hombre el mover,<br/>Mas del poder divino;<br/>No es un hacer en lo exterior<br/>Mas Su mover genuino;<br/>No es un trabajó empresarial<br/>Mas proclamar Su vida;<br/>No es para un éxito lograr<br/>Mas darle acogida.<br/>',NULL,192561,3);
INSERT INTO stanza VALUES('S749','4','Meta, energía, y todo plan<br/>Debe abandonarse<br/>Para que Él obre en nuestro ser<br/>Su blanco solamente.<br/>Todo lo nuestro en verdad<br/>Debe llevarse a muerte;<br/>Así en nosotros vivirá<br/>El Cristo refulgente.<br/>',NULL,192562,4);
INSERT INTO stanza VALUES('S750','1','¡Cuán bendito_es el servicio,<br/>Y_el vivir sacerdotal!<br/>Cristo_al sacerdote_es todo,<br/>Su porción y dulce_hogar.<br/>',NULL,192563,1);
INSERT INTO stanza VALUES('S750','chorus','Cristo_al sacerdote es todo,<br/>Su comida celestial;<br/>Cristo es su vestido fino,<br/>Su morada eternal.<br/>',NULL,192564,2);
INSERT INTO stanza VALUES('S750','2','El vestido del servicio<br/>Es lo bello del Señor;<br/>Muestra el pectoral Su gloria,<br/>Las hombreras, Su esplendor.<br/>',NULL,192565,3);
INSERT INTO stanza VALUES('S750','3','Cuando él, en sacrificio,<br/>Le ofrece Cristo a Dios,<br/>Lo disfruta al comerlo,<br/>Sus riquezas suyas son.<br/>',NULL,192566,4);
INSERT INTO stanza VALUES('S750','4','Cuando del Señor se viste,<br/>Cristo es toda su expresión;<br/>Cuando él lo come y bebe,<br/>Cristo es su posesión.<br/>',NULL,192567,5);
INSERT INTO stanza VALUES('S750','5','Santa y pura es su morada,<br/>El aumento del Señor;<br/>Se edifica el sacerdocio<br/>Como casa para Dios.<br/>',NULL,192568,6);
INSERT INTO stanza VALUES('S750','6','Todo su vivir es Cristo,<br/>Su porción y propiedad;<br/>Todo es Cristo y Cristo siempre,<br/>En Su inclusividad.<br/>',NULL,192569,7);
INSERT INTO stanza VALUES('S751','1','Ministrar al Cristo vivo<br/>Es servicio para Dios;<br/>Dar Su excedente_a otros,<br/>Es servicio de valor.<br/>',NULL,192570,1);
INSERT INTO stanza VALUES('S751','chorus','Ministrar al Cristo vivo<br/>Es servicio para Dios;<br/>Dar Su excedente a otros,<br/>Es servicio de valor.<br/>',NULL,192571,2);
INSERT INTO stanza VALUES('S751','2','Como ofreció Su pueblo el<br/>Excedente de Canaan,<br/>Así, algo cosechado<br/>De Jesús, hay que ofrendar.<br/>',NULL,192572,3);
INSERT INTO stanza VALUES('S751','3','Cristo es la buena tierra<br/>Do tenemos que labrar;<br/>Cosechamos Su excedente<br/>Para darlo a los demás.<br/>',NULL,192573,4);
INSERT INTO stanza VALUES('S751','4','Cada miembro en Él creciendo,<br/>Su función ha de cumplir,<br/>Disfrutando así de Cristo,<br/>Cristo al Cuerpo ha de impartir.<br/>',NULL,192574,5);
INSERT INTO stanza VALUES('S751','5','Comunión y testimonio,<br/>Ministerio, adoración,<br/>Todo debe de ser Cristo,<br/>El servicio para Dios.<br/>',NULL,192575,6);
INSERT INTO stanza VALUES('S752','1','Sirve y obra en el Cuerpo,<br/>El Señor nos indicó;<br/>Que Su meta es el Cuerpo,<br/>Acatemos tal visión.<br/>',NULL,192576,1);
INSERT INTO stanza VALUES('S752','chorus','Sirve y obra en el Cuerpo,<br/>Nunca en forma individual,<br/>Como un miembro de este Cuerpo,<br/>Sirve en unanimidad.<br/>',NULL,192577,2);
INSERT INTO stanza VALUES('S752','2','Nos dio vida como miembros,<br/>No en forma individual;<br/>Prosigamos al servicio<br/>Todos en mutualidad.<br/>',NULL,192578,3);
INSERT INTO stanza VALUES('S752','3','Somos hoy las piedras vivas,<br/>Una casa para Dios;<br/>Siendo un sacerdocio santo<br/>Armonioso en su labor.<br/>',NULL,192579,4);
INSERT INTO stanza VALUES('S752','4','Hay que ser edificados<br/>Para entonces ministrar;<br/>Ver que el Cuerpo es la base<br/>Del servicio, es crucial.<br/>',NULL,192580,5);
INSERT INTO stanza VALUES('S752','5','Si servimos en el Cuerpo<br/>Hallaremos provisión;<br/>Separados o aislados,<br/>Moriremos sin función.<br/>',NULL,192581,6);
INSERT INTO stanza VALUES('S752','6','Al servirle en el Cuerpo<br/>Sus riquezas nos dará;<br/>Funcionando como miembros<br/>Cristo en pleno se verá.<br/>',NULL,192582,7);
INSERT INTO stanza VALUES('S752','7','Sólo a la Cabeza asidos<br/>Creceremos en unión;<br/>Nos dará el suministro<br/>Para el Cuerpo en comunión.<br/>',NULL,192583,8);
INSERT INTO stanza VALUES('S752','8','Oh Señor, a Ti nos damos<br/>Para transformados ser;<br/>Al servirte así en el Cuerpo<br/>Tu intención podremos ver.<br/>',NULL,192584,9);
INSERT INTO stanza VALUES('S753','1','Que sirvamos a la iglesia<br/>Es la voluntad de Dios,<br/>Es la única manera<br/>Que trazó nuestro Señor.<br/>',NULL,192585,1);
INSERT INTO stanza VALUES('S753','chorus','Que sirvamos a la iglesia,<br/>No una meta personal,<br/>Es la voluntad divina<br/>Que tenemos que acatar.<br/>',NULL,192586,2);
INSERT INTO stanza VALUES('S753','2','Que la iglesia sea Su vaso<br/>Es el plan de nuestro Dios,<br/>Y que sea el servicio<br/>Para su edificación.<br/>',NULL,192587,3);
INSERT INTO stanza VALUES('S753','3','Varios miembros como dones<br/>La Cabeza al Cuerpo dio,<br/>Para edificar la iglesia<br/>A la plenitud de Dios.<br/>',NULL,192588,4);
INSERT INTO stanza VALUES('S753','4','Las funciones y los dones,<br/>El Espíritu también,<br/>Todo ministerio dado,<br/>Para la iglesia es.<br/>',NULL,192589,5);
INSERT INTO stanza VALUES('S753','5','Predicar el evangelio,<br/>La enseñanza, el ministrar,<br/>O cualquier otro servicio<br/>Para la iglesia serán.<br/>',NULL,192590,6);
INSERT INTO stanza VALUES('S753','6','Sólo para las iglesias<br/>Debe el ministerio ser;<br/>Quiere Dios los candeleros,<br/>No un ministerio ver.<br/>',NULL,192591,7);
INSERT INTO stanza VALUES('S753','7','La unidad de la iglesia<br/>Preservada así será;<br/>Probará nuestros motivos,<br/>Nuestra meta ajustará.<br/>',NULL,192592,8);
INSERT INTO stanza VALUES('S753','8','Oh Señor, ven a librarnos<br/>De un trabajo individual.<br/>Por Tu iglesia serviremos<br/>Hasta el Cuerpo edificar.<br/>',NULL,192593,9);
INSERT INTO stanza VALUES('S754','1','Lejos de aquí morando en las tinieblas<br/>Miles de almas pueden perecer;<br/>¿Quién, quién irá a dar las buenas nuevas,<br/>Confiando en Cristo sin desfallecer?<br/>',NULL,192594,1);
INSERT INTO stanza VALUES('S754','chorus','"Todo poder yo recibí,<br/>Todo poder yo recibí,<br/>Id a predicar a todas las naciones<br/>Yo estoy con vosotros siempre".<br/>',NULL,192595,2);
INSERT INTO stanza VALUES('S754','2','Por todo el inundo hay puertas abiertas,<br/>Con Cristo hoy ¡soldados acudid!<br/>Despierta y ve a predicar rompiendo<br/>Toda cadena del pecado vil.<br/>',NULL,192596,3);
INSERT INTO stanza VALUES('S754','3','"¿Por qué morir?" la voz de Dios os ruega,<br/>"¿Por qué morir?" digamos a una voz;<br/>¡Cristo murió para salvar de muerte!<br/>Por eso ve y proclama salvación.<br/>',NULL,192597,4);
INSERT INTO stanza VALUES('S755','1','Sobre todos reinará<br/>Quien el mundo despreció,<br/>De espinas coronó,<br/>Despreció y_aborreció;<br/>Proclamad las buenas ya;<br/>Ante Él se postrarán.<br/>',NULL,192598,1);
INSERT INTO stanza VALUES('S755','2','Aunque Su herencia fue<br/>Usurpada por Satán,<br/>Cristo la reclamará,<br/>¡Triunfará, venciendo el mal!<br/>Proclamad las buenas ya;<br/>Ante Él se postrarán.<br/>',NULL,192599,2);
INSERT INTO stanza VALUES('S755','3','Bajo Su reino de paz,<br/>Cielo y tierra cantarán;<br/>Más aumento aquí habrá<br/>Para honrar al Rey triunfal.<br/>Proclamad las buenas ya;<br/>Ante Él se postrarán.<br/>',NULL,192600,3);
INSERT INTO stanza VALUES('S755','4','Apresurate Señor,<br/>Muestra a todos Tu esplender;<br/>Tuyo el reino y el poder,<br/>Gloria eterna Tuya es.<br/>Todos ya se postrarán<br/>A Tus pies para adorar.<br/>',NULL,192601,4);
INSERT INTO stanza VALUES('S756','1','Hoy la trompeta_alzad,<br/>Heraldos sois;<br/>A Jesús proclamad<br/>Como Señor.<br/>Él renombrado es;<br/>Es coronado Rey,<br/>Todos se postrarán<br/>Delante de Él.<br/>',NULL,192602,1);
INSERT INTO stanza VALUES('S756','2','¿Quién se levantará?<br/>Hoy, ¿quién irá?<br/>¿Quién lazos cortará,<br/>Aun con pesar?<br/>Por pérdida contad<br/>Todo lo terrenal;<br/>Gloriándose en la cruz,<br/>Hoy, ¿quién irá?<br/>',NULL,192603,2);
INSERT INTO stanza VALUES('S756','3','Ve, pues Su día está<br/>Mas cerca ya;<br/>Pasando el tiempo va,<br/>Cristo vendrá,<br/>Donde haya idólatras,<br/>La cruz allí ensalzad;<br/>El alba anuncia ya<br/>Que Él cerca está.<br/>',NULL,192604,3);
INSERT INTO stanza VALUES('S756','4','Esa trompeta oíd,<br/>¡Jesús es Rey!<br/>Viene a reinar por fin;<br/>Triunfante es Él:<br/>Lo reconocerán,<br/>Ante Él se inclinarán;<br/>Rey solo Él será,<br/>¡Jesús es Rey!<br/>',NULL,192605,4);
INSERT INTO stanza VALUES('S757','1','Rescata con piedad<br/>Los que perecen,<br/>Para salvarlos de muerte eternal;<br/>Llora por todo aquel<br/>Que está perdido,<br/>Dile de Cristo, el fuerte en salvar.<br/>',NULL,192606,1);
INSERT INTO stanza VALUES('S757','chorus','Guía al perdido,<br/>Alza al caído.<br/>Con compasión Jesús<br/>Los salvará.<br/>',NULL,192607,2);
INSERT INTO stanza VALUES('S757','2','En ellos hay desdén,<br/>Mas Cristo espera,<br/>Al penitente Él quiere atender;<br/>Insiste con fervor<br/>Y con ternura,<br/>Perdonará a los que crean en Él.<br/>',NULL,192608,3);
INSERT INTO stanza VALUES('S757','3','La gracia sanará<br/>Los sentimientos<br/>Tan aplastados por el tentador;<br/>De nuevo vibrarán<br/>Las cuerdas rotas,<br/>Al ser tocadas por tan grande amor.<br/>',NULL,192609,4);
INSERT INTO stanza VALUES('S757','4','A todos rescatad,<br/>Es el encargo,<br/>Para la obra da fuerza el Señor;<br/>Tráelos a la verdad<br/>Con fe y paciencia,<br/>Dile al errante que Cristo murió.<br/>',NULL,192610,5);
INSERT INTO stanza VALUES('S758','1','¡Ve a_evangelizar!<br/>¡Rescata almas!<br/>¡Día a día perdiéndose están!<br/>Tu corazón de amor<br/>Nunca acalles:<br/>¡Ve con urgencia, ve a predicar!<br/>',NULL,192611,1);
INSERT INTO stanza VALUES('S758','chorus','¡Ve a_evangelizar!<br/>¡Rescata almas!<br/>¡Tu_amor por ellos los<br/>Rescatará!<br/>',NULL,192612,2);
INSERT INTO stanza VALUES('S759','1','A todo ser hay que impartir<br/>Cristo al hablar y en el vivir;<br/>Con caridad minístralo<br/>Al infeliz en su sufrir.<br/>',NULL,192613,1);
INSERT INTO stanza VALUES('S759','chorus','A todo ser hay que impartir<br/>Cristo en tu andar y proceder,<br/>Imparte Aquel que vive en ti,<br/>Da este Cristo a conocer.<br/>',NULL,192614,2);
INSERT INTO stanza VALUES('S759','2','A todo ser hay que impartir<br/>Al que ganó tu corazón;<br/>Con todo amor minístralo<br/>Haciendo ver Su gran valor.<br/>',NULL,192615,3);
INSERT INTO stanza VALUES('S759','3','A todo ser hay que impartir<br/>Al Cristo que gozo te da;<br/>Impártelo a cada amistad;<br/>Su gozo y gloria Él será.<br/>',NULL,192616,4);
INSERT INTO stanza VALUES('S759','4','A todo ser hay que impartir<br/>Al Cristo que tu vida es;<br/>Brinda al Señor, minístralo<br/>A todo aquel para su bien.<br/>',NULL,192617,5);
INSERT INTO stanza VALUES('S760','1','Ve a ganar las almas para Dios,<br/>Trae materiales de edificación,<br/>Trae a la casa almas que Él creó,<br/>Las almas que el pecado usurpó.<br/>',NULL,192618,1);
INSERT INTO stanza VALUES('S760','2','Ve a ganar las almas para Dios,<br/>Ve a librarlos de este mundo atroz,<br/>De todo engaño y densa oscuridad,<br/>De atracciones que usa Satanás.<br/>',NULL,192619,2);
INSERT INTO stanza VALUES('S760','3','Ve a ganar las almas para Dios,<br/>Tráelas a casa, son para el Señor;<br/>Ve a vencer a Su mortal rival,<br/>Ve coordinando todo en unidad.<br/>',NULL,192620,3);
INSERT INTO stanza VALUES('S760','4','Ve a ganar las almas para Dios,<br/>Ve, como el Cuerpo, proclama al Señor;<br/>Ve, con los fieles y uno sé con Él,<br/>Que el evangelio suene por doquier.<br/>',NULL,192621,4);
INSERT INTO stanza VALUES('S761','1','La expansión del evangelio<br/>Es por la vida interior;<br/>Es por nuestro testimonio<br/>Que se gana al pecador.<br/>',NULL,192622,1);
INSERT INTO stanza VALUES('S761','chorus','Oh, desbórdate en nosotros,<br/>Muestra así Tu vida hoy;<br/>Por nosotros como vasos<br/>Vida al hombre da, Señor.<br/>',NULL,192623,2);
INSERT INTO stanza VALUES('S761','2','Es la convicción de vida<br/>Lo que a otros les da fe;<br/>Es el impartir de vida<br/>Lo que vivifica el ser.<br/>',NULL,192624,3);
INSERT INTO stanza VALUES('S761','3','Siempre en el Señor morando<br/>Muchos frutos se verán;<br/>Compartiendo esta vida<br/>Cristo a otros llegará.<br/>',NULL,192625,4);
INSERT INTO stanza VALUES('S761','4','Que vivamos el mensaje<br/>Dando a Cristo a conocer;<br/>No sembrando las doctrinas<br/>Mas la vida de poder.<br/>',NULL,192626,5);
INSERT INTO stanza VALUES('S762','1','¿Eres un canal que bendice?<br/>¿El amor de Dios fluye por ti?<br/>Al perdido, ¿le hablas de Cristo?<br/>¿Estás presto tú para servir?<br/>',NULL,192627,1);
INSERT INTO stanza VALUES('S762','chorus','Hazme un canal que bendiga, Señor,<br/>Hazme un canal, ésta es mi oración;<br/>Toma mi vida y mi servicio,<br/>Hazme un canal que bendiga, Señor.<br/>',NULL,192628,2);
INSERT INTO stanza VALUES('S762','2','¿Es un canal que bendice?<br/>¿Tienes carga por almas salvar?<br/>¿Has urgido a los que andan errantes<br/>Que acepten a Cristo sin par?<br/>',NULL,192629,3);
INSERT INTO stanza VALUES('S762','3','No seremos los que bendicen,<br/>Si nos ata el pecado sutil;<br/>Mas seremos barreras a aquellos<br/>Que tratemos de ganar aquí.<br/>',NULL,192630,4);
INSERT INTO stanza VALUES('S763','1','¿He de ir sin fruto alguno<br/>Que presente_a mi Señor?<br/>¡No le llevo ni_un trofeo<br/>Ni servicio de valor!<br/>',NULL,192631,1);
INSERT INTO stanza VALUES('S763','chorus','¿He de ir sin fruto alguno?<br/>¿He de ver a Cristo así?<br/>Con el tiempo mal gastado,<br/>¿He de presentarme allí?<br/>',NULL,192632,2);
INSERT INTO stanza VALUES('S763','2','Hoy la muerte no me asusta:<br/>Cristo es ya mi Salvador;<br/>Mas sin fruto alguno verlo,<br/>Esto sí me da dolor.<br/>',NULL,192633,3);
INSERT INTO stanza VALUES('S763','3','Darle todo yo quisiera<br/>De los años que perdí,<br/>A mi Salvador los diera<br/>Para Su deseo cumplir.<br/>',NULL,192634,4);
INSERT INTO stanza VALUES('S763','4','Sigue al día negra noche,<br/>¡Trabajad cuando haya luz!<br/>Para evadir reproches,<br/>Trae las almas a Jesús.<br/>',NULL,192635,5);
INSERT INTO stanza VALUES('S764','1','Sin pena hay que proclamar<br/>El alto_evangelio de Dios;<br/>Más alto evengelio no hay,<br/>Pues vemos lo que Dios planeó.<br/>No como lo_hicimos ayer,<br/>Tan pobres en nuestra expresión;<br/>A todos podemos ganar<br/>Por ser hoy los hijos de Dios.<br/>',NULL,192636,1);
INSERT INTO stanza VALUES('S764','2','Todo nuestro Hermano heredó;<br/>Toda autoridad Dios le dio;<br/>Nos ha hecho participar<br/>Con Él en Su cargo de honor.<br/>Así Dios nos seleccionó,<br/>Antes de la tierra formar;<br/>Su gloria nos otorgará.<br/>A tal Cristo, ¿cómo rehusar?<br/>',NULL,192637,2);
INSERT INTO stanza VALUES('S764','3','¡"Hermanos de Cristo Jesús"!<br/>¡Qué alto evangelio esto es!<br/>Más alto no puede llegar;<br/>Todo hombre lo debe saber.<br/>¿Pudiera alguien rechazar<br/>Este evangelio sin par?<br/>Con Cristo a la diestra de Dios,<br/>¡Más alto evangelio no hay!<br/>',NULL,192638,3);
INSERT INTO stanza VALUES('S765','1','Un hombre soy;<br/>Soy del universo lo vital;<br/>Sí, hombre soy;<br/>Soy del universo lo vital.<br/>Dios me_hizo tal,<br/>Soy sin igual;<br/>Soy del universo_el centro y lo más vital.<br/>',NULL,192639,1);
INSERT INTO stanza VALUES('S765','2','Es Cristo en mí<br/>Lo vital en todo mi vivir;<br/>Es Cristo en mí<br/>Lo vital en todo mi vivir.<br/>Él vive así<br/>Dentro de mí,<br/>Es la realidad vital en todo mi vivir.<br/>',NULL,192640,2);
INSERT INTO stanza VALUES('S765','3','La iglesia es<br/>Cristo mismo en toda Su expresión;<br/>La iglesia es<br/>Cristo mismo en toda Su expresión.<br/>Ella es crucial<br/>Para Su plan,<br/>Es el hombre colectivo que hoy debe reinar.<br/>',NULL,192641,3);
INSERT INTO stanza VALUES('S765','4','Familia real<br/>Es la iglesia en la localidad;<br/>Familia real<br/>Es la en la localidad.<br/>Cristo al comer,<br/>Cristo al beber,<br/>Edificará la iglesia en cada localidad.<br/>',NULL,192642,4);
INSERT INTO stanza VALUES('S765','5','¿Qué haremos, pues?<br/>¡Ir al mundo a darlo a conocer!<br/>¿Qué haremos, pues?<br/>¡Ir al mundo a darlo a conocer!<br/>Salgamos ya<br/>A proclamar,<br/>¡Estas buenas nuevas por la tierra hay que llevar!<br/>',NULL,192643,5);
INSERT INTO stanza VALUES('S766','1','Vamos a_hablar<br/>Hasta que descienda_el reino_acá.<br/>Sí, hay que_hablar<br/>Hasta que descienda_el reino_acá.<br/>¿Por qué callar?<br/>Vamos a hablar;<br/>Hasta que descienda el reino del Señor, ¡hablad!<br/>',NULL,192644,1);
INSERT INTO stanza VALUES('S766','2','¡Oh, proclamad!<br/>Su Palabra hay que liberar;<br/>¡Sí, proclamad!<br/>Su Palabra hay que liberar;<br/>Semilla hay<br/>Para sembrar;<br/>Su Palabra nunca en vano a Él volverá.<br/>',NULL,192645,2);
INSERT INTO stanza VALUES('S766','3','¡Hoy predicad!<br/>¡Su evangelio por doquier llevad!<br/>¡Sí, predicad!<br/>No hay que temer lo que dirán.<br/>Su obra Dios<br/>Ya realizó;<br/>Somos peregrinos sin temor a qué dirán.<br/>',NULL,192646,3);
INSERT INTO stanza VALUES('S766','4','Si hablamos hoy,<br/>Cristo mismo testimonio da;<br/>Si hablamos hoy,<br/>Cristo mismo testimonio da.<br/>Al hombre hablad,<br/>Muchos ganad.<br/>Si proclamas, Dios podrá al corazón hablar.<br/>',NULL,192647,4);
INSERT INTO stanza VALUES('S766','5','¡Ya cosechad!<br/>¡El pleno evangelio predicad!<br/>¡Hay que segar!<br/>¡El pleno evangelio predicad!<br/>Cosecha así<br/>La siega aquí,<br/>¡Busca hombres para Cristo y Su iglesia hoy!<br/>',NULL,192648,5);
INSERT INTO stanza VALUES('S767','1','La comunión en el evangelio<br/>Es una bendición;<br/>Nos consagramos por su progreso<br/>Y su propagación.<br/>Por su confirmación y defensa<br/>Gracia el Señor nos da;<br/>El que_empezó la obra_en nosotros<br/>La perfeccionará.<br/>',NULL,192649,1);
INSERT INTO stanza VALUES('S767','2','Todas las cosas que nos suceden<br/>Por esta causa son:<br/>Que todos oigan el evangelio<br/>Y del amor de Dios;<br/>Que con denuedo hablemos todos<br/>Hoy Su Palabra fiel;<br/>Hazlo viviendo en Jesucristo,<br/>Hazlo con Su poder.<br/>',NULL,192650,2);
INSERT INTO stanza VALUES('S767','3','Danos, Señor, el atrevimiento<br/>Para testificar,<br/>Sea por vida o sea por muerte a<br/>Cristo magnificar.<br/>Pues no queremos ni para nada<br/>Avergonzados ser,<br/>Para nosotros vivir es Cristo,<br/>Y nuestro todo es Él.<br/>',NULL,192651,3);
INSERT INTO stanza VALUES('S767','4','Que nuestras vidas puedan ser dignas<br/>Para evangelizar.<br/>En nuestro espíritu combatimos,<br/>Guardando la unidad.<br/>Anunciaremos el evangelio<br/>Dándonos al Señor;<br/>Cristo es la vida, proclamaremos,<br/>La iglesia, Su expresión.<br/>',NULL,192652,4);
INSERT INTO stanza VALUES('S768','1','No sé_explicar por qué_Él amó al hombre;<br/>Él, quien por ángeles loado fue;<br/>Ni cómo, cual Pastor, buscó al perdido<br/>Para traerlo de regreso_a Él.<br/>Mas esto seé, que nació de Maria<br/>En un pesebre pobre en Belén;<br/>Que_en nazaret vivía y obraba;<br/>De esta forma llegó_al mundo_el Salvador.<br/>',NULL,192653,1);
INSERT INTO stanza VALUES('S768','2','No se_explicar cómo Él sufrió en silencio,<br/>Mientras Su paz y gracia al mundo dio;<br/>Su corazón fue en la cruz quebrado,<br/>Corona de dolor siempre llevó.<br/>Mas esto sé, que Él sana al quebrantado,<br/>Quita el pecado, calma el temor,<br/>Lleva las cargas de quien va cansado,<br/>Ya que al mundo llegó nuestro Salvador.<br/>',NULL,192654,2);
INSERT INTO stanza VALUES('S768','3','No sé explicar que todas las naciones,<br/>Toda la tierra, Él herederá;<br/>Que la necesidad de todo sabio<br/>Y todo pecador Él saciará.<br/>Mas esto sé: todos verán Su gloria,<br/>Y_Él segará aquello que sembró;<br/>Con esplendor Su sol saldrá un día<br/>Cuando conozcan todos nuestro Salvador.<br/>',NULL,192655,3);
INSERT INTO stanza VALUES('S768','4','No sé explicar cómo han de adorarlo<br/>Cuando Él calme toda tempestad,<br/>O que habrá un júbilo tan grande<br/>Pues Su amor a todos llenará.<br/>Mas esto sé, que_Él llenará los cielos,<br/>Miríadas entonarán canción;<br/>En tierra y cielo habrá una respuesta:<br/>Por fin ya reina nuestro Rey y Salvador.<br/>',NULL,192656,4);
INSERT INTO stanza VALUES('S769','1','Siembra en el alba, siembra al mediodía,<br/>Su benevolencia siembra por doquier.<br/>Con el tiempo llega abundante siega;<br/>Con gozo, gavillas hemos de traer.<br/>',NULL,192657,1);
INSERT INTO stanza VALUES('S769','chorus','¡Con gozo, traed! ¡Con gozo, traed!<br/>Con gozo, gavillas hemos de traer.<br/>¡Con gozo, traed! ¡Con gozo, traed!<br/>Con gozo, gavillas hemos de traer.<br/>',NULL,192658,2);
INSERT INTO stanza VALUES('S769','2','Siembra bajo el sol y siembra en la sombra,<br/>En tormenta o frío no hemos de temer.<br/>Pronto cuando acabe la labor y siega,<br/>Con gozo, gavillas hemos de traer.<br/>',NULL,192659,3);
INSERT INTO stanza VALUES('S769','3','A pesar de penas y de aflicciones,<br/>Por nuestro Señor, sembramos por doquier.<br/>Cuando pase el llanto, Él dará acogida;<br/>Con gozo, gavillas hemos de traer.<br/>',NULL,192660,4);
INSERT INTO stanza VALUES('S770','1','¡Oh, qué piedad! Al verdadero Dios vi,<br/>¡Feliz de pasar de oscuridad a luz!<br/>¡Qué gracia ser gratuitamente salvo!<br/>¡No hay que obrar ni en nuestras fuerzas confiar!<br/>',NULL,192661,1);
INSERT INTO stanza VALUES('S770','2','Señor, acuérdate de mi familia,<br/>Sus pecados ya llevaste a la cruz;<br/>Cumple este día Tu promesa dada;<br/>"En Cristo cree; tu casa salva será".<br/>',NULL,192662,2);
INSERT INTO stanza VALUES('S770','3','Gana Señor, te ruego, a mi familia!<br/>En mi corazón arde este voto a Ti:<br/>"¡Mi casa y yo, al Señor serviremos!"<br/>¡Load a Dios! Sólo Él es viviente y real.<br/>',NULL,192663,3);
INSERT INTO stanza VALUES('S771','1','En las aguas de la muerte,<br/>Con mi Salvador sepultado estoy;<br/>No me_acosa más el mundo,<br/>Porque su poder Él anuló.<br/>Con Cristo resucité,<br/>Libre de la muerte camino en_Él;<br/>El Espíritu me imparte vida<br/>Y Su inagotable fuerza da_a mi ser.<br/>',NULL,192664,1);
INSERT INTO stanza VALUES('S772','1','Por el bautismo, uno soy<br/>Contigo, mi Señor;<br/>Oh, por Tu gracia y Tu piedad,<br/>Revela su valor.<br/>',NULL,192665,1);
INSERT INTO stanza VALUES('S772','2','En muerte y sepultura, yo<br/>Contigo uno soy;<br/>Así al pecado muerto estoy.<br/>¡Qué gran liberación!<br/>',NULL,192666,2);
INSERT INTO stanza VALUES('S772','3','En muerte y sepultura, yo<br/>Contigo uno soy;<br/>Así soy libre de Satán,<br/>Y al mundo digo: "Adios".<br/>',NULL,192667,3);
INSERT INTO stanza VALUES('S772','4','Contigo Dios nos levantó,<br/>De muerte nos libró;<br/>El fruto de la santidad<br/>Tu vida nos legó.<br/>',NULL,192668,4);
INSERT INTO stanza VALUES('S772','5','Me bauticé en Tu nombre yo,<br/>Y mío ya no soy;<br/>Uno contigo vivo aquí,<br/>Tus pasos sigo hoy.<br/>',NULL,192669,5);
INSERT INTO stanza VALUES('S773','1','¡Ya se murió y lo enterré!<br/>¡Con el viejo hombre acabé!<br/>¡Ya se murió y lo enterré!<br/>¡Con el viejo hombre acabé!<br/>',NULL,192670,1);
INSERT INTO stanza VALUES('S773','2','¡No vivo yo! ¡No vivo yo!<br/>¡Cristo en mí se manifiesta hoy!<br/>¡No vivo yo! ¡No vivo yo!<br/>¡Cristo en mí se manifiesta hoy!<br/>',NULL,192671,2);
INSERT INTO stanza VALUES('S774','1','El Reino_es Dios que reina<br/>Su gloria mantendrá;<br/>Tal Reino soberano<br/>Su orden sostendrá.<br/>Su_autoridad ejerce<br/>Con toda potestad,<br/>Por siempre en Su Reino<br/>Y por la_eternidad.<br/>',NULL,192672,1);
INSERT INTO stanza VALUES('S774','2','Dios reina desde el trono,<br/>El centro divinal,<br/>Poniendo todo en orden<br/>Conforme a Su plan.<br/>Dios es nuestra Cabeza<br/>Con señorío fiel<br/>Cuando todo es regido<br/>Por el divino Rey.<br/>',NULL,192673,2);
INSERT INTO stanza VALUES('S774','3','Reinando en Su Reino<br/>Hace Él Su voluntad,<br/>Y, bajo Su dominio<br/>Su plan cumpliendo va.<br/>Es sólo en Su reino<br/>Que hayamos bendición,<br/>Pues fluye desde el trono<br/>Su misma vida Dios.<br/>',NULL,192674,3);
INSERT INTO stanza VALUES('S774','4','Si a Dios nos sometemos,<br/>Virtudes se obtendrán;<br/>Mas toda rebeldía<br/>Pecado engendrará.<br/>Satán tiene por meta<br/>El trono derribar,<br/>Mas es nuestro objetivo<br/>Que Dios pueda reinar.<br/>',NULL,192675,4);
INSERT INTO stanza VALUES('S774','5','A Cristo en el reino<br/>Dios magnifica ya,<br/>Y cuando Él reina en vida<br/>La gloria al Padre da.<br/>Si Dios tiene el dominio,<br/>En todo hay bendición;<br/>Y cuando Cristo reina<br/>Dios gana Su expresión.<br/>',NULL,192676,5);
INSERT INTO stanza VALUES('S774','6','Al cumplirse los tiempos<br/>Todo se reunirá<br/>Bajo una Cabeza,<br/>Y fiel lo adorarán.<br/>Del reino, un anticipo<br/>La iglesia gusta ya;<br/>Sujeta a Su gobierno,<br/>Su reinó apurará.<br/>',NULL,192677,6);
INSERT INTO stanza VALUES('S775','1','El reino en la tierra hoy<br/>Es Dios que reina_en lo_interior;<br/>Es Cristo mismo en nuestro ser,<br/>Que rige allí como el Señor.<br/>',NULL,192678,1);
INSERT INTO stanza VALUES('S775','2','Su vida con Su autoridad<br/>Lo entrona en nuestro corazón,<br/>Regula todo lo interior<br/>Y rige toda externa acción.<br/>',NULL,192679,2);
INSERT INTO stanza VALUES('S775','3','Así en nuestro corazón<br/>Su Reino establecido está;<br/>Él nos prepara para Dios<br/>Al ejercer Su autoridad.<br/>',NULL,192680,3);
INSERT INTO stanza VALUES('S775','4','Por Su reinar en lo interior<br/>Su misma vida impartirá;<br/>Por ser el Rey, nuestro Señor,<br/>Con Su caudal nos saciará.<br/>',NULL,192681,4);
INSERT INTO stanza VALUES('S775','5','Al gobernar el corazón<br/>Su plenitud se mostrará;<br/>Rigiendo Él en lo interior<br/>Su Cuerpo se edificará.<br/>',NULL,192682,5);
INSERT INTO stanza VALUES('S775','6','Por nuestra interna sumisión<br/>A este reino celestial,<br/>Vivimos dignos del Señor,<br/>Al expresar su realidad.<br/>',NULL,192683,6);
INSERT INTO stanza VALUES('S775','7','En esta esfera celestial<br/>Vivimos hoy con tal poder,<br/>Luchando y caminando en luz<br/>Hasta Su reino establecer.<br/>',NULL,192684,7);
INSERT INTO stanza VALUES('S776','1','Desde nuestro_espíritu, el Señor<br/>Nuestros vasos llenará,<br/>Inundando nuestra mente,<br/>Emoción y voluntad.<br/>No habrá más rebeldía<br/>Ni tinieblas, sino luz.<br/>Perderá Satán su reino;<br/>Reinanrá sólo Jesús.<br/>¡Esto hoy es Su recobro,<br/>Lo mejor que tiene Dios!<br/>Démosle_al Señor terreno<br/>Por Su reino y_expresión.<br/>',NULL,192685,1);
INSERT INTO stanza VALUES('S777','1','Requiere_el reino mucho más<br/>Que los decretos de la ley;<br/>Más alto y estricto es<br/>Que lo que promulgó Moisés.<br/>',NULL,192686,1);
INSERT INTO stanza VALUES('S777','2','"Arrepentíos para entrar",<br/>Es la primera condición;<br/>Un cambio así debemos dar<br/>Y firme estar por nuestro Dios.<br/>',NULL,192687,2);
INSERT INTO stanza VALUES('S777','3','Para poder al reino entrar<br/>Nuestra justicia debe ser<br/>Mayor que aquella de la ley,<br/>Y de la vida proceder.<br/>',NULL,192688,3);
INSERT INTO stanza VALUES('S777','4','Para poder al reino entrar<br/>La voluntad del Padre obrad;<br/>No actuemos por nuestra elección<br/>Sino para cumplir Su plan.<br/>',NULL,192689,4);
INSERT INTO stanza VALUES('S777','5','Para poder al reino entrar<br/>Debemos como un niño ser,<br/>Flexible y manso en actitud,<br/>Y todo lo del yo vencer.<br/>',NULL,192690,5);
INSERT INTO stanza VALUES('S777','6','Requiere el reino perfección<br/>Tal como el Padre celestial;<br/>A tal nivel hay que llegar<br/>Para en su éxtasis entrar.<br/>',NULL,192691,6);
INSERT INTO stanza VALUES('S777','7','El reino es el regir de Dios,<br/>Y para entrar hay que tener<br/>Su misma vida y expresión<br/>Con la naturaleza de Él.<br/>',NULL,192692,7);
INSERT INTO stanza VALUES('S777','8','El reino que hemos de acatar<br/>Es el gobierno celestial,<br/>El cual, por vida divinal,<br/>Con el Señor se gozará.<br/>',NULL,192693,8);
INSERT INTO stanza VALUES('S778','1','La esencia de Su reino es<br/>Sumisa vida para Dios,<br/>Que vive de lo divinal<br/>Tomando_a Cristo por porción.<br/>',NULL,192694,1);
INSERT INTO stanza VALUES('S778','2','Tal vida es el reino hoy:<br/>Muy pobre en espíritu,<br/>Con manso y puro corazón<br/>Que sólo busca a Dios en luz.<br/>',NULL,192695,2);
INSERT INTO stanza VALUES('S778','3','Los mensajeros de la paz<br/>Por la justicia sufren hoy<br/>El vituperio de Jesús,<br/>Mas gozo es su galardón.<br/>',NULL,192696,3);
INSERT INTO stanza VALUES('S778','4','Es sal que mata corrupción<br/>Y en las tinieblas, plena luz;<br/>Sincera y pura en acción,<br/>Amando con abnegación.<br/>',NULL,192697,4);
INSERT INTO stanza VALUES('S778','5','No busca gloria terrenal<br/>Y por el reino orando va;<br/>En Dios confía sin afán<br/>Y al reino da la prioridad.<br/>',NULL,192698,5);
INSERT INTO stanza VALUES('S778','6','Estricta para con el yo,<br/>Mas muestra a otros compasión;<br/>La voluntad del Padre hará<br/>Con la Palabra y oración.<br/>',NULL,192699,6);
INSERT INTO stanza VALUES('S778','7','No da lugar a Satanás,<br/>Ni al pecado, el mundo o el yo,<br/>Mas busca el reino celestial<br/>Y la autoridad de Dios.<br/>',NULL,192700,7);
INSERT INTO stanza VALUES('S778','8','Tal vida puede subyugar<br/>Todas las cosas para Dios;<br/>Apresurando el reino está<br/>Hasta su manifestación.<br/>',NULL,192701,8);
INSERT INTO stanza VALUES('S779','1','El Hijo de Dios se sembró<br/>Como semilla_en nuestro ser,<br/>Cumpliendo con el plan de Dios<br/>Su reino_así ha de crecer.<br/>',NULL,192702,1);
INSERT INTO stanza VALUES('S779','2','Un solo grano era Él,<br/>Produjo frutos a granel;<br/>Los hizo hijos para Dios<br/>Y así Su reino estableció.<br/>',NULL,192703,2);
INSERT INTO stanza VALUES('S779','3','Sembró cizaña Satanás,<br/>Y entre el trigo la esparció,<br/>Trayendo grande confusión,<br/>Al reino daño así causó.<br/>',NULL,192704,3);
INSERT INTO stanza VALUES('S779','4','Por esa obra tan sutil<br/>Cizaña y trigo mixturó;<br/>En su apariencia el reino está<br/>Grotescamente anormal.<br/>',NULL,192705,4);
INSERT INTO stanza VALUES('S779','5','El reino cual mostaza es,<br/>Pequeña planta con sabor;<br/>Mas como un árbol vino a ser<br/>Un gran sistema impostor.<br/>',NULL,192706,5);
INSERT INTO stanza VALUES('S779','6','En vez de alimento dar,<br/>Brinda a  las aves un lugar<br/>Do hombres y espíritus<br/>Malignos hacen su hogar.<br/>',NULL,192707,6);
INSERT INTO stanza VALUES('S779','7','Es una enorme religión<br/>En su apariencia exterior,<br/>Con paganismo tan sutil<br/>Que así la masa fermentó.<br/>',NULL,192708,7);
INSERT INTO stanza VALUES('S779','8','Su forma externa así cambió,<br/>Del mundo un sistema es,<br/>En su interior se corrompió<br/>Y con maldad se saturó.<br/>',NULL,192709,8);
INSERT INTO stanza VALUES('S779','9','Mas algo oculto busca Dios,<br/>Como "tesoro" y "perla" es;<br/>En tales nos transformará,<br/>Su reino así se ha de ver.<br/>',NULL,192710,9);
INSERT INTO stanza VALUES('S779','10','Del cristianismo oculto está<br/>El reino en su realidad;<br/>Mas por la real transformación<br/>Conforme a Cristo se verá.<br/>',NULL,192711,10);
INSERT INTO stanza VALUES('S779','11','De la "cizaña" apártanos,<br/>Señor, y de ese "árbol" vil;<br/>De "levadura" púrganos,<br/>Y haznos puros para Ti.<br/>',NULL,192712,11);
INSERT INTO stanza VALUES('S779','12','Transforma nuestras almas, Tú.<br/>Preciosas piedras quieres ver,<br/>Para formar Tu habitación<br/>Y en realidad Tu reino ser.<br/>',NULL,192713,12);
INSERT INTO stanza VALUES('S780','1','Ved el esplendor del reino<br/>En su manifestación,<br/>Con su Rey, el Amo amado,<br/>A quien Dios ya designó.<br/>En la carne humilde vino,<br/>Odio y desdén sufrió;<br/>Mas regresará en gloria<br/>A cumplir el plan de Dios.<br/>',NULL,192714,1);
INSERT INTO stanza VALUES('S780','2','Fue al Anciano de Días<br/>Para el reino recibir,<br/>Y ya viene con el reino<br/>Para, en gloria, así regir.<br/>Como "Piedra", las naciones<br/>Él las desmenuzará;<br/>Luego Él será el "gran monte"<br/>Que el reino exhibirá.<br/>',NULL,192715,2);
INSERT INTO stanza VALUES('S780','3','Ved la tierra, las naciones<br/>Son el reino del Señor;<br/>Bajo Su gobierno regio,<br/>Gozan paz y bendición.<br/>No más odio ni mas guerras<br/>Las naciones sufrirán,<br/>Pues el real conocimiento<br/>De Dios ellas obtendrán.<br/>',NULL,192716,3);
INSERT INTO stanza VALUES('S780','4','Los cristianos vencedores<br/>Junto a Cristo reinarán;<br/>Mas de Israel, los salvos,<br/>Sacerdocio obtendrán.<br/>Las naciones bajo ellos,<br/>Pueblo del Señor serán,<br/>Y restauración gloriosa<br/>Toda la creación verá.<br/>',NULL,192717,4);
INSERT INTO stanza VALUES('S780','5','Satanás sera atado,<br/>Y la tierra libre de él;<br/>Con el Cristo soberano,<br/>Bendecida ha de ser.<br/>Todo a Cristo sujetado,<br/>A Su mando y voluntad;<br/>Como Centro y Cabeza<br/>Cristo cumplirá Su plan.<br/>',NULL,192718,5);
INSERT INTO stanza VALUES('S781','1','Es un ejercicio el reino de Dios,<br/>Pero cuando Él regrese, será_un galardón;<br/>En Su sabiduría nos hace_entrenar,<br/>Para cumplir Su plan y justicia_afirmar.<br/>',NULL,192719,1);
INSERT INTO stanza VALUES('S781','2','Nacimos de Dios para con Él reinar,<br/>Pero Su entrenamiento nos preparará,<br/>Hasta poder reinar como reyes con Él,<br/>Para que Su reinado se pueda ejercer.<br/>',NULL,192720,2);
INSERT INTO stanza VALUES('S781','3','Debemos al trono sumisos estar,<br/>Restringidos en todo, Su reino honrar;<br/>Para así compartir en Su autoridad,<br/>Y con Cristo sobre las naciones reinar.<br/>',NULL,192721,3);
INSERT INTO stanza VALUES('S781','4','Debemos ser justos, negando el yo,<br/>Tener paz con los hombres y gozo con Dios;<br/>En el reino viviendo en su realidad,<br/>Su manifestación se podrá realizar.<br/>',NULL,192722,4);
INSERT INTO stanza VALUES('S781','5','Entonces el reino con Cristo vendrá,<br/>Su reinado es el premio que Él nos dará;<br/>El Señor Su justicia así mantendrá,<br/>Y las huestes del cielo la contemplarán.<br/>',NULL,192723,5);
INSERT INTO stanza VALUES('S781','6','Por eso gran precio el apóstol pagó,<br/>Por el reino seguro a la meta corrió;<br/>Y por tanto nos pide más fidelidad,<br/>Para en el futuro el reino lograr.<br/>',NULL,192724,6);
INSERT INTO stanza VALUES('S781','7','Señor, por Tu gracia deseamos vivir<br/>En Tu reino entrenados, ganándolo así,<br/>Y ser ejercitados en su realidad,<br/>Para el reino mañana poder disfrutar.<br/>',NULL,192725,7);
INSERT INTO stanza VALUES('S782','1','Consiste el universo de<br/>La tierra,_el cielo_y mar.<br/>Resiste_el enemigo_a Dios,<br/>Para_impedir Su plan.<br/>La tierra se robó Satán,<br/>De Dios la usurpó;<br/>El aire luego él hurtó:<br/>Vil reino_estableció.<br/>',NULL,192726,1);
INSERT INTO stanza VALUES('S782','2','Mas Dios se ha propuesto aquí<br/>Su reino establecer,<br/>Para reinar en plenitud<br/>Y expresar Su ser.<br/>En Génesis, Dios comenzó<br/>A realizar Su plan;<br/>Y, en esa situación atroz,<br/>Creó Dios a Adán.<br/>',NULL,192727,2);
INSERT INTO stanza VALUES('S782','3','Satán al hombre hizo caer<br/>De la gracia eternal;<br/>Linaje nuevo Dios llamó,<br/>Que encabezó Abraham.<br/>Su pueblo, Dios lo liberó<br/>De Egipto y Faraón.<br/>A Canaán Él los llevó,<br/>Para el reino de Dios.<br/>',NULL,192728,3);
INSERT INTO stanza VALUES('S782','4','El Israel de Dios deseó<br/>A un rey terrenal;<br/>De nuevo el reino se perdió,<br/>Hasta a David llegar.<br/>Lo puso Dios y así ganó<br/>Su reino otra vez;<br/>Mas Israel se degradó<br/>Y el reino hizo caer.<br/>',NULL,192729,4);
INSERT INTO stanza VALUES('S782','5','Tal situación se prolongó<br/>Hasta que, en Su plan,<br/>Dios se hizo hombre y declaró:<br/>"¡El reino cerca está!"<br/>Dios un modelo halló en Jesús,<br/>¡El digno Rey llegó!<br/>Mas, neciamente, Satanás,<br/>A la cruz lo llevó.<br/>',NULL,192730,5);
INSERT INTO stanza VALUES('S782','6','Jesús en el sepulcro entró,<br/>¡Venció la muerte ya!<br/>Resucitado, salvará<br/>Del reino de Satán.<br/>Hoy como Espíritu entra Él,<br/>Y vida al hombre da;<br/>Su plan la iglesia cumple, a fin<br/>De la tierra ganar.<br/>',NULL,192731,6);
INSERT INTO stanza VALUES('S782','7','En la iglesia vemos hoy<br/>El reino en realidad;<br/>Dios puede aquí manifestar<br/>Su plena autoridad.<br/>Por nuestra vara fuerte aquí,<br/>El diablo correrá;<br/>La iglesia, a la tierra, así<br/>El reino traerá.<br/>',NULL,192732,7);
INSERT INTO stanza VALUES('S783','1','En el pasado_eterno, Dios<br/>Nos escogió_y no cambiará;<br/>La salvación segura está,<br/>Sabemos esto en verdad.<br/>',NULL,192733,1);
INSERT INTO stanza VALUES('S783','2','"Ellos jamás perecerán,<br/>La vida eterna Yo les doy;<br/>Nadie los puede arrebatar,<br/>De Nuestras manos", dice Dios.<br/>',NULL,192734,2);
INSERT INTO stanza VALUES('S783','3','A todos los hijos de Dios,<br/>Una advertencia da el Señor:<br/>"Si preparados no están,<br/>Castigo habrá, no galardón".<br/>',NULL,192735,3);
INSERT INTO stanza VALUES('S783','4','La recompensa no será<br/>La vida eterna que Él nos dio;<br/>Hay que correr y edificar<br/>Para alcanzar el galardón.<br/>',NULL,192736,4);
INSERT INTO stanza VALUES('S783','5','Por Dios y el reino, ¡proseguid!<br/>Cual Moisés, somos del Señor;<br/>Sufrimos con Su pueblo aquí,<br/>Mas vemos ese galardón.<br/>',NULL,192737,5);
INSERT INTO stanza VALUES('S783','6','Su vituperio vale más<br/>Que todo lo que Egipto da;<br/>La tierra egipcia abandonad<br/>Y disciplina evitad.<br/>',NULL,192738,6);
INSERT INTO stanza VALUES('S783','7','¡La era del reino anhelad!<br/>¡Vida del alma abandonad!<br/>Así la hemos de salvar<br/>Para en el reino disfrutar.<br/>',NULL,192739,7);
INSERT INTO stanza VALUES('S783','8','Pagad el precio para que<br/>Cristo se forje en nuestro ser;<br/>Nuestra alma Cristo ganará,<br/>¡Sí, ésta nuestra meta es!<br/>',NULL,192740,8);
INSERT INTO stanza VALUES('S784','1','El Creador del hombre tiene<br/>En Su corazón un plan:<br/>Quiere un hombre que lo exprese,<br/>Para todo sojuzgar.<br/>Mas el hombre fue tentado,<br/>Escondido_el plan quedó;<br/>Pero Dios tendrá Su reino<br/>Por Su Hijo que triunfó.<br/>',NULL,192741,1);
INSERT INTO stanza VALUES('S784','2','Cristo ganará Su reino<br/>A pesar de Satanás;<br/>En el corazón del hombre<br/>Algo real creciendo está.<br/>No recibas la enseñanza:<br/>De "esperar hasta morir";<br/>Pues el reino que Dios quiere<br/>Cristo lo edifica aquí.<br/>',NULL,192742,2);
INSERT INTO stanza VALUES('S784','3','Vino el Hijo, Jesucristo,<br/>Y un hombre se hizo Él.<br/>Como Espíritu Él entra<br/>Como vida en nuestro ser.<br/>Como la semilla viva,<br/>Cristo en nuestro espíritu,<br/>Va creciendo hasta llenarnos<br/>Con Su vida en plenitud.<br/>',NULL,192743,3);
INSERT INTO stanza VALUES('S784','4','Cristo añora ver Su Novia,<br/>Ya no hay tiempo que perder.<br/>Apremiemos Su venida<br/>Al crecer en vida en Él.<br/>Deja todos tus afanes,<br/>Vuelve a Cristo en tu interior,<br/>Y contempla la semilla<br/>Que crece en tu corazón.<br/>',NULL,192744,4);
INSERT INTO stanza VALUES('S784','5','Cristo logrará Su reino<br/>De una forma muy normal,<br/>Transformándonos en vida<br/>Día a día lo hará.<br/>La semilla de la vida<br/>Todo-inclusiva es,<br/>Pues conlleva en ella todo<br/>Para el reino establecer.<br/>',NULL,192745,5);
INSERT INTO stanza VALUES('S785','1','Jesús, el reino,_a nosotros llegó;<br/>Rige y brilla con gran esplendor.<br/>Como semilla, el Rey se sembró;<br/>En nuestro_espíritu_el reino entró.<br/>',NULL,192746,1);
INSERT INTO stanza VALUES('S785','chorus','¡Que crezca Él! ¡Que crezca Él!<br/>Crezca Su reino en nuestro ser.<br/>Hoy en nosotros sembrado está Él;<br/>Jesús, el reino, ¡qué glorioso es!<br/>',NULL,192747,2);
INSERT INTO stanza VALUES('S785','2','Arrepentidos de todo ya<br/>Porque el reino muy cerca está.<br/>Todo lo nuestro dejamos atrás,<br/>Y lo del mundo hay que abandonar.<br/>',NULL,192748,3);
INSERT INTO stanza VALUES('S785','3','Por sus doctrinas e ideas de error,<br/>La religión nunca el reino notó;<br/>En vano esperan que el reino vendrá<br/>Como una dispensación, nada más.<br/>',NULL,192749,4);
INSERT INTO stanza VALUES('S785','4','Mas a nosotros se nos reveló<br/>Que el reino es solamente Jesús;<br/>Es Su persona en nuestro interior,<br/>Sembrada cuando invocamos: "Señor".<br/>',NULL,192750,5);
INSERT INTO stanza VALUES('S786','1','El misterio_oculto se me reveló,<br/>Cristo es la realidad de Dios.<br/>Dios en El habita, hoy mi vida es,<br/>Y Su gloria manifestaré.<br/>',NULL,192751,1);
INSERT INTO stanza VALUES('S786','chorus','¡Gloria, gloria, Cristo_es vida_en mí!<br/>¡Gloria, gloria, qué_esperanza es Él!<br/>Hoy es el misterio en mi_espíritu,<br/>Mas con gloria llenará mi ser.<br/>',NULL,192752,2);
INSERT INTO stanza VALUES('S786','2','Me ha regenerado en mi espíritu,<br/>Hoy mi alma transformando está;<br/>Cambiará mi cuerpo, como el de Él será,<br/>Y todo mi ser lo igualará.,<br/>',NULL,192753,3);
INSERT INTO stanza VALUES('S786','3','En esencia vida uno soy con Él;<br/>Y con Él en gloria estaré;<br/>Por la eternidad yo le disfrutaré<br/>En total conformidad con Él.<br/>',NULL,192754,4);
INSERT INTO stanza VALUES('S787','1','Mi vida y_esperanza de gloria Cristo es,<br/>Me ha regenerado y mora en mi ser;<br/>El viene a cambiarme con vencedor poder,<br/>Mi cuerpo_hará glorioso como_el de Él!<br/>',NULL,192755,1);
INSERT INTO stanza VALUES('S787','chorus','¡Él viene, Él viene, me viene a glorificar!<br/>Mi cuerpo transfigurará, igual al Suyo será.<br/>¡Él viene, Él viene y nos redimirá!<br/>Como_esperanza de gloria, nos glorificará.<br/>',NULL,192756,2);
INSERT INTO stanza VALUES('S787','2','Mi vida y esperanza de gloria es Jesús,<br/>Me trae al Dios viviente, me da Su plenitud;<br/>Él viene a mezclarme en todo con mi Dios,<br/>Para que participe en Su gloria yo.<br/>',NULL,192757,3);
INSERT INTO stanza VALUES('S787','3','Mi vida y esperanza, mi redención final,<br/>Es Cristo quien mi cuerpo, de muerte librará;<br/>Él viene a saturarlo con gloria y esplendor,<br/>Absorberá la muerte nuestro Señor.<br/>',NULL,192758,4);
INSERT INTO stanza VALUES('S787','4','Mi vida y esperanza de gloria Cristo es,<br/>Su vida es mi experiencia, pues uno soy con Él;<br/>Él viene a llevarme a gloriosa libertad,<br/>Y para siempre unidos hemos de estar.<br/>',NULL,192759,5);
INSERT INTO stanza VALUES('S788','1','¡Cristo viene! ¡Cristo viene!<br/>La creación no sufra más;<br/>Tal proclamación gloriosa<br/>Fe y esperanza da.<br/>¡Cristo viene! ¡Cristo viene!<br/>¡Ven, oh Príncipe de Paz!<br/>',NULL,192760,1);
INSERT INTO stanza VALUES('S788','2','Hoy la tierra sólo puede<br/>Tu sufrida historia hablar;<br/>Mas contemplará Tu gloria<br/>Cuando vengas a reinar.<br/>¡Cristo viene! ¡Cristo viene!<br/>Se repita sin cesar.<br/>',NULL,192761,2);
INSERT INTO stanza VALUES('S788','3','Cuánto ha suspirado el pueblo<br/>Por Ti, por descanso y paz;<br/>Pronto con radiante gloria,<br/>Su Restaurador verán.<br/>¡Cristo viene! ¡Cristo viene!<br/>Jubiloso gozo habrá.<br/>',NULL,192762,3);
INSERT INTO stanza VALUES('S788','4','Ante esta esperanza,<br/>Toda arpa ha de sonar;<br/>Y ante tal advenimiento,<br/>Suene un coro universal.<br/>¡Cristo viene! ¡Cristo viene!<br/>¡Oh Jesús, ven pronto ya!<br/>',NULL,192763,4);
INSERT INTO stanza VALUES('S789','1','Ya la luz del horizonte<br/>Rompe_el día tan feliz<br/>En que se verá la gloria<br/>Del gran Rey que_ha de venir.<br/>La vigilia de la noche<br/>Dejó_exhausto al corazón,<br/>Mas por fin se_acerca_el día<br/>Con su triunfante canción.<br/>',NULL,192764,1);
INSERT INTO stanza VALUES('S789','2','Palidecen las estrellas<br/>Al brotar la claridad<br/>De un alba tan gloriosa<br/>Que ya quiere despertar.<br/>Está el cielo muy radiante<br/>Como el fuego en su esplendor;<br/>Y en el corazón humano<br/>Hay una esperanza hoy.<br/>',NULL,192765,2);
INSERT INTO stanza VALUES('S789','3','Hay una quietud profunda<br/>Y en el aire, expectación;<br/>Y de Dios viene un aliento<br/>Por ferviente oración.<br/>El Jesús crucificado<br/>Es el Cristo en gloria hoy;<br/>Si sufrimos, también sufre,<br/>Con nosotros el Señor.<br/>',NULL,192766,3);
INSERT INTO stanza VALUES('S789','4','Quiere Dios tumbar barreras<br/>Y el camino edificar;<br/>A Sus ángeles Él llama<br/>Para puertas levantar,<br/>Mas son ángeles humanos<br/>No una hueste celestial,<br/>Pues el toque de Su armada<br/>Es en nuestro palpitar.<br/>',NULL,192767,4);
INSERT INTO stanza VALUES('S789','5','Escuchad en la distancia,<br/>Se acrecienta un himno hoy<br/>Por Jesús, el Rey triunfante,<br/>Nuestro ungido Salvador;<br/>Ve, oh Sión, a recibirlo,<br/>Alma apúrate y trae<br/>Lo más dulce y más querido<br/>Para el Rey, nuestro Emanuel.<br/>',NULL,192768,5);
INSERT INTO stanza VALUES('S790','1','Pronto viene Cristo, cerca_el día está,<br/>Su llegada se_aproxima ya.<br/>Siempre aguardando, esperando_en Él,<br/>Para que nos lleve con poder.<br/>',NULL,192769,1);
INSERT INTO stanza VALUES('S790','chorus','¡Gloria! ¡Gloria! ¡Cristo viene ya!<br/>¡Gloria! ¡Gloria! ¡Vamos a reinar<br/>Con glorioso cuerpo, juntó al Salvador,<br/>Llenos de_alabanzas y loor!<br/>',NULL,192770,2);
INSERT INTO stanza VALUES('S790','2','Pronto viene Cristo, pronto se verá<br/>En la noche el alba deslumbrar;<br/>No debe arrastrarnos este mundo atroz<br/>Si del mal queremos escapar.<br/>',NULL,192771,3);
INSERT INTO stanza VALUES('S790','3','Pronto viene Cristo a recompensar<br/>Y a los que lo aman, coronar;<br/>Vela sin desear del mundo su placer,<br/>Ama y sirve a cristo sin cesar.<br/>',NULL,192772,4);
INSERT INTO stanza VALUES('S790','4','Pronto viene Cristo, viene a reinar,<br/>Satanás y el mundo pasarán;<br/>Vence al enemigo, lucha contra el mal<br/>Para en Su trono gobernar.<br/>',NULL,192773,5);
INSERT INTO stanza VALUES('S791','1','Cuando el Señor descienda<br/>La trompeta sonará.<br/>Los que duermen, a la muerte vencerán.<br/>Cuando el Señor descienda<br/>A los vivos llevará;<br/>Nuestros cuerpos librará_y transformará.<br/>',NULL,192774,1);
INSERT INTO stanza VALUES('S791','chorus','El Señor vendrá en gloria,<br/>Lo veremos cara a cara;<br/>El Señor vendrá en gloria,<br/>Nos transformará_y con Él nos llevará.<br/>',NULL,192775,2);
INSERT INTO stanza VALUES('S791','2','Cuando el Señor descienda<br/>Nuestra alba apuntará,<br/>Y la angustia de la noche pasará.<br/>Cuando el Señor descienda<br/>Con Su gloria brillará;<br/>Los lamentos para siempre acabarán.<br/>',NULL,192776,3);
INSERT INTO stanza VALUES('S791','3','Cuando el Señor descienda<br/>Como estrella en resplandor,<br/>Santos fieles la corona obtendrán.<br/>Viene como sol potente,<br/>Su justicia reinará,<br/>Y la tierra restaurada así será.<br/>',NULL,192777,4);
INSERT INTO stanza VALUES('S791','4','Esperemos Su regreso<br/>Con vigilia y oración,<br/>Con la lámpara encendida y sobriedad.<br/>El Señor ya pronto viene,<br/>Con fidelidad servid,<br/>Y cumplid el ministerio; ¡trabajad!<br/>',NULL,192778,5);
INSERT INTO stanza VALUES('S792','1','¡Velad! Pues ya amanece,<br/>¡Él pronto aquí estará!<br/>La niebla_y las sombras se_esfuman,<br/>Y huye toda_oscuridad.<br/>Por siglos han sido añorado<br/>El Cristo que pronto vendrá;<br/>Vendrá en destellos de gloria,<br/>Vendrá y nos arrebatará.<br/>',NULL,192779,1);
INSERT INTO stanza VALUES('S792','2','¡Velad! Pues ya amanece,<br/>¡El premio al fin se obtendrá!<br/>Ya pronto con Él estaremos,<br/>¡La senda al fin concluirá!<br/>Señor, haz que cada momento<br/>Velemos contigo hasta el fin,<br/>Que hagamos contigo vigilia<br/>A diario en nuestro vivir.<br/>',NULL,192780,2);
INSERT INTO stanza VALUES('S793','1','Desde_aquel día, cuando en Betania,<br/>Al despedirnos un vacío_entró;<br/>¿Cómo podré bajar de nuevo_el arpa<br/>Y disfrutar sin Ti cualquier canción?<br/>Y cuando_en las vigilias de la noche<br/>Soy insensible_al gozo ó al dolor,<br/>Recuerdo Tu promesa: "Vengo pronto",<br/>Y gimo así: ¿Por qué te tardas, oh Señor?<br/>',NULL,192781,1);
INSERT INTO stanza VALUES('S793','2','"No tengo hogar", me acuerda Tu pesebre;<br/>Tu cruz, de mi alma despojó el placer;<br/>Busco otra patria viendo Tu venida<br/>Tu mismo ser mi meta ahora es.<br/>Con Tu partida se esfumó mi gozo,<br/>No tiene el canto su dulzura hoy;<br/>Tu despedida me llevó al vacío,<br/>¡Oh, cuánto anhelo que vinieras, mi Señor!<br/>',NULL,192782,2);
INSERT INTO stanza VALUES('S793','3','Aunque yo aquí disfruto Tu presencia,<br/>Falta ese algo en mi corazón;<br/>Tu luz y Tu sostenimiento tiernos<br/>Ya no me bastan, ¡pronto ven, Señor!<br/>Pese a Tu paz, me siento solitario;<br/>Pese a Tu gozo, queda un suspirar;<br/>Cuando estoy muy contento, aun añoro<br/>Y es mi clamor poder Tu rostro contemplar.<br/>',NULL,192783,3);
INSERT INTO stanza VALUES('S793','4','¿Qué exiliado no desea su tierra,<br/>Y anhela ver su pueblo otra vez?<br/>¿O, en lo ajeno, ver su parentela?<br/>¿O dos amantes el volverse a ver?<br/>No pueden los placeres terrenales<br/>Con Tu venida comparados ser;<br/>Si aquí no puedo contemplar Tu rostro,<br/>Debo gemir hasta que en Tu presencia esté.<br/>',NULL,192784,4);
INSERT INTO stanza VALUES('S793','5','¿Podrías olvidar esa promesa<br/>De regresar, llevándome de aquí?<br/>Todos mis días te sigo esperando,<br/>Y todavía no te veo venir.<br/>Recuerda cuánto llevo esperando,<br/>Aunque Tu paso muy lejano está;<br/>¿Oh, cuánto más? ¿Oh, cuánto he de esperarte<br/>Hasta que llegues en gloriosa majestad?<br/>',NULL,192785,5);
INSERT INTO stanza VALUES('S793','6','Pues, al pasar por las generaciones,<br/>Tus santos vienen y se van sin ver<br/>El cumplimiento de Tu fiel promesa.<br/>Oh, ¿cuánto? ¿Cuánto más te esperaré?<br/>Señor, ¿no hay modo de escuchar Tus pasos?<br/>¿Por qué los cielos tan cerrados son?<br/>Oh, ¿debe aún la espera prolongarse<br/>Hasta que revelado sea Tu esplendor?<br/>',NULL,192786,6);
INSERT INTO stanza VALUES('S793','7','Señor, recuerda cuánto he esperado<br/>Por Tu venida, mas no sólo yo;<br/>Pues Tus queridos santos desde siempre<br/>Por Tu regreso han hecho petición.<br/>A tantas lágrimas y tantos ruegos<br/>Sea Tu presencia la respuesta fiel;<br/>¡Oh ven! Escucha el eco de los siglos;<br/>Contesta este grito colectivo: "¡Ven!".<br/>',NULL,192787,7);
INSERT INTO stanza VALUES('S794','1','Desde Tu ida del monte de_Olivos,<br/>¿Por qué no has regresado_otra vez?<br/>Por largos años ya hemos velado;<br/>¿Nuestra_oración no escuchas, tal vez?<br/>',NULL,192788,1);
INSERT INTO stanza VALUES('S794','chorus','Oh ven; ya ven;<br/>Ésta es nuestra oración.<br/>Nos prometiste que pronto vendrías.<br/>Oh ven muy pronto, Señor.<br/>',NULL,192789,2);
INSERT INTO stanza VALUES('S794','2','Desde que Tú ascendiste, Amado,<br/>Todo es árido y sin sabor;<br/>En oración y velando a menudo,<br/>Por Tu presencia gemimos, Señor.<br/>',NULL,192790,3);
INSERT INTO stanza VALUES('S794','3','Aunque las aves y flores son lindas,<br/>¿Cuándo podremos contigo estar?<br/>Nada se compara con Tu belleza;<br/>Sólo anhelamos Tu faz contemplar.<br/>',NULL,192791,4);
INSERT INTO stanza VALUES('S794','4','Con impaciencia anhelamos que vuelvas,<br/>¿Cuánto más hay que esperarte en amor?<br/>Desde el crepúsculo hasta el ocaso,<br/>Nuestra esperanza es verte Señor.<br/>',NULL,192792,5);
INSERT INTO stanza VALUES('S794','5','Si llueve fuerte o soplan los vientos,<br/>Al ver la luna u olas del mar,<br/>Quisiéramos descubrir Tu venida;<br/>Nos desalienta no ver Tu señal.<br/>',NULL,192793,6);
INSERT INTO stanza VALUES('S794','6','Oh, si no fuera por Tu encomienda,<br/>Desanimante sería servir;<br/>Mas Tú deseas que, mientras velamos,<br/>Seamos prudentes, viviendo por Ti.<br/>',NULL,192794,7);
INSERT INTO stanza VALUES('S794','7','Señor, los días se han alargado<br/>Desde que Tú prometiste volver.<br/>Te esperamos deseando que vengas;<br/>¡Oh, quizás hoy te podamos ya ver!<br/>',NULL,192795,8);
INSERT INTO stanza VALUES('S795','1','Muy pronto volverá mi Rey,<br/>Los cielos llenará;<br/>La creación verá Su luz,<br/>Él la redimirá.<br/>Él pronto cumplirá Su plan,<br/>Sus pasos oigo bien;<br/>Y Su perfil glorioso ya,<br/>Empieza_a_aparecer.<br/>',NULL,192796,1);
INSERT INTO stanza VALUES('S795','2','Anhelo Su presencia ver,<br/>Para apreciar Su faz;<br/>Y mientras viene mi Señor,<br/>No quiero ocioso estar.<br/>Que venga Él deseo yo,<br/>Mi fe consumar;<br/>No existe un gozo terrenal<br/>Que me pueda saciar.<br/>',NULL,192797,2);
INSERT INTO stanza VALUES('S795','3','Mi corazón con Él está,<br/>Mi vista al cielo va;<br/>Mis labios sólo emitirán:<br/>"¡Señor, ven pronto ya!"<br/>Muy cerca Su regreso está,<br/>Por mí regresará;<br/>Pues sé que Su promesa es fiel<br/>Y que la cumplirá.<br/>',NULL,192798,3);
INSERT INTO stanza VALUES('S795','4','Son Tus Palabras, oh Jesús,<br/>El ancla de mi fe;<br/>Con ellas alentado soy,<br/>Y fiel a Ti seré.<br/>¡Oh, que Tu gloria brote ya,<br/>Que caiga Tu rival;<br/>Al trono llévanos, Señor,<br/>Y cumple así Tu plan!<br/>',NULL,192799,4);
INSERT INTO stanza VALUES('S795','5','Tus brazos salvadores son<br/>Refugio para mí;<br/>Tú, como el Padre, guardarás,<br/>Al que confía en Ti.<br/>Cabeza y cuerpo uno son,<br/>La grey con el pastor;<br/>Seguro en Tu mano estoy,<br/>Confiando en Ti, Señor.<br/>',NULL,192800,5);
INSERT INTO stanza VALUES('S795','6','Mil manos no me detendrán,<br/>Ni ojos de diez mil;<br/>Ni espinas me impedirán,<br/>El premio conseguir.<br/>Avívate, mi espíritu,<br/>Y quede el mundo atrás;<br/>Muy pronto volverá mi Rey,<br/>Con Él me llevará.<br/>',NULL,192801,6);
INSERT INTO stanza VALUES('S795','7','¡Sol sanador! Tus rayos son<br/>Salud para el mortal;<br/>¡Glorioso Rey! ¡Justo Señor!<br/>Me inclino para orar:<br/>Asciende al trono, oh Jesús,<br/>Y muéstranos Tu faz;<br/>Que venga el reino celestial,<br/>Con rectitud y paz.<br/>',NULL,192802,7);
INSERT INTO stanza VALUES('S795','8','Debía la verdad reinar,<br/>Con fuerza y libertad;<br/>Pero al cundir la falsedad,<br/>Del mundo es majestad.<br/>Que pronto vengas, oh, Verdad,<br/>Tu luz destruya el mal;<br/>Tus hijos lleva con poder<br/>Al seno eternal.<br/>',NULL,192803,8);
INSERT INTO stanza VALUES('S796','1','¿Hasta cuándo tardarás, Señor?<br/>¡Anhelo contemplar Tu faz!<br/>Y cantar triunfante la canción<br/>De mi amado Jesús, Rey de paz.<br/>¡Oh, pronto ven! ¡No tardes más!<br/>Oh, pronto ven a confortarme_aquí;<br/>¡Oh, pronto ven! ¡No tardes más!<br/>Anhelo estar yo junto a Ti.<br/>',NULL,192804,1);
INSERT INTO stanza VALUES('S797','1','Cara_a cara con mi Cristo<br/>Cara_a cara, ¡qué feliz<br/>Cuando,_en gloria,_a Cristo vea,<br/>Aquel que murió por mí!<br/>',NULL,192805,1);
INSERT INTO stanza VALUES('S797','chorus','Cara_a cara con mi Cristo<br/>En Su gloria yo veré;<br/>Cara_a cara, yo Su rostro<br/>Por siempre contemplaré.<br/>',NULL,192806,2);
INSERT INTO stanza VALUES('S797','2','Hoy borrosamente veo<br/>Tras el velo al Salvador;<br/>Mas el día pronto viene:<br/>¡He de ver Su resplandor!<br/>',NULL,192807,3);
INSERT INTO stanza VALUES('S797','3','¡Oh, qué gozo en Su presencia!<br/>Pronto el llanto no ha de ser<br/>Cuando lo torcido acabe,<br/>Y lo oscuro, claro esté.<br/>',NULL,192808,4);
INSERT INTO stanza VALUES('S797','4','Cara a cara, ¡qué sublime!<br/>Contemplando al Redentor;<br/>Cara a cara con mi Cristo,<br/>Con Aquel que así me amó.<br/>',NULL,192809,5);
INSERT INTO stanza VALUES('S798','1','Cuando regrese mi Señor,<br/>Salvo seré de mi dolor,<br/>Los santos iremos con Él,<br/>¡Gloria al Señor!<br/>¡Gloria al Señor! ¡Gloria al Señor!<br/>Los santos iremos con Él,<br/>¡Gloria al Señor!<br/>',NULL,192810,1);
INSERT INTO stanza VALUES('S798','2','Yo cara a cara le veré,<br/>Con Él yo siempre moraré,<br/>Allí Su gracia cantaré,<br/>¡Gloria al Señor!<br/>¡Gloria al Señor! ¡Gloria al Señor!<br/>Allí Su gracia cantaré,<br/>Gloria al Señor!<br/>',NULL,192811,2);
INSERT INTO stanza VALUES('S798','3','Cuando en Su trono frente a Él,<br/>Mis penas ya no cargaré,<br/>De la victoria gozaré,<br/>¡Gloria al Señor!<br/>¡Gloria al Señor! ¡Gloria al Señor!<br/>De la victoria gozaré,<br/>¡Gloria al Señor!<br/>',NULL,192812,3);
INSERT INTO stanza VALUES('S798','4','Entonces he de afirmar:<br/>La vida en Cristo es sin par;<br/>¡Qué gozo tan glorioso habrá!<br/>¡Gloria al Señor!<br/>¡Gloria al Señor! ¡Gloria al Señor!<br/>¡Qué gozo tan glorioso habrá!<br/>¡Gloria al Señor!<br/>',NULL,192813,4);
INSERT INTO stanza VALUES('S798','5','Que nos quedemos en Su amor,<br/>Unidos y sin división,<br/>Para alegrar Su corazón,<br/>¡Gloria al Señor!<br/>¡Gloria al Señor! ¡Gloria al Señor!<br/>Para alegrar Su corazón,<br/>¡Gloria al Señor!<br/>',NULL,192814,5);
INSERT INTO stanza VALUES('S798','6','¡Oh ven, mi Rey! ¡Oh ven, Señor!<br/>Y cumple Tus promesas hoy,<br/>Ven a premiar al vencedor,<br/>¡Gloria al Señor!<br/>¡Gloria al Señor! ¡Gloria al Señor!<br/>Ven a premiar al vencedor,<br/>¡Gloria al Señor!<br/>',NULL,192815,6);
INSERT INTO stanza VALUES('S799','1','¡Qué esperanza, Cristo volverá!<br/>Arrebatados, ¡nos transformará!<br/>Glorificados con Él, gozo_habrá;<br/>A Su imagen Él nos cambiará.<br/>',NULL,192816,1);
INSERT INTO stanza VALUES('S799','chorus','¡Gloria sin par! ¡Cristo vendrá!<br/>¡Gloria sin par! ¡Cristo vendrá!<br/>Arrebatados, ¡nos transformará!<br/>¡Qué esperanza! ¡Cristo volverá!<br/>',NULL,192817,2);
INSERT INTO stanza VALUES('S799','2','¡Qué esperanza, Cristo volverá!<br/>Se esfumará ya la vieja creación;<br/>No gemiremos, habrá libertad,<br/>Disfrutaremos total salvación.<br/>',NULL,192818,3);
INSERT INTO stanza VALUES('S799','3','¡Qué esperanza, Cristo volverá!<br/>Sobre los pueblos podremos reinar;<br/>Juntos con Él, sacerdocio real,<br/>Su plena salvación nuestra será.<br/>',NULL,192819,4);
INSERT INTO stanza VALUES('S799','4','¡Qué esperanza, Cristo volverá!<br/>Fieles sirviendo velamos con fe,<br/>Corriendo hasta la meta final<br/>Para que el premio del reino nos dé.<br/>',NULL,192820,5);
INSERT INTO stanza VALUES('S800','1','Salvador, Tú pronto vienes,<br/>Vienes pronto, mi Señor,<br/>En belleza refulgente,<br/>En Tu gloria trascendente;<br/>Nos gozamos en canción;<br/>Del oriente vienes Tú,<br/>Nos lo dice_el resplandor;<br/>Sacerdote en esplendor,<br/>Y_estás cerca, mi Señor.<br/>',NULL,192821,1);
INSERT INTO stanza VALUES('S800','2','Pronto vienes, pronto vienes,<br/>Y nos arrebatarás;<br/>Te veremos, te honraremos,<br/>Ese día mostraremos<br/>Todo nuestro amor leal;<br/>Que tonada el corazón<br/>Cantará sólo por Ti,<br/>Y a Tus pies se rendirá<br/>Nuestro ser colmado allí.<br/>',NULL,192822,2);
INSERT INTO stanza VALUES('S800','3','Pronto vienes y en Tu mesa<br/>Bulle esta confesión;<br/>Nuestro corazón conduces<br/>A tan dulce comunión,<br/>Arras de la eterna Sión.<br/>No nos muestra sólo amor<br/>O Tu eterna redención,<br/>Mas Tu reino que vendrá,<br/>Nuestro anhelo y oración.<br/>',NULL,192823,3);
INSERT INTO stanza VALUES('S800','4','¡Oh, el gozo cuando reines<br/>Mi amado y buen Señor!<br/>Toda lengua al fin confiese<br/>Tu nombre que prevalece,<br/>Dándote gloria y honor.<br/>Nuestro Amo, Amigo fiel,<br/>Vindicado te has de ver,<br/>Entronado para ser<br/>Adorado por doquier.<br/>',NULL,192824,4);
INSERT INTO stanza VALUES('S801','1','Hoy escuchad ¡sonido tan divino!<br/>En tierra y_en el cielo hay temblor;<br/>¿Será el trueno del Señor viniendo?<br/>¿Será el sonido de nuestra_oración?<br/>',NULL,192825,1);
INSERT INTO stanza VALUES('S801','2','Él sí vendrá, y con Él diez mil voces<br/>Han de clamar y Sus santos lo oirán;<br/>Él sí vendrá, para traer el goce<br/>De Su venida que segura está.<br/>',NULL,192826,2);
INSERT INTO stanza VALUES('S801','3','Lo prometió, y ¿no lo adoraremos?<br/>Lo cumplirá, ¿podemos desconfiar?<br/>Ven y a Sus pies todos nos postraremos,<br/>Echando nuestras cargas y ansiedad.<br/>',NULL,192827,3);
INSERT INTO stanza VALUES('S801','4','Por vida y muerte, penas y pecados,<br/>Ha hecho frente a mi necesidad;<br/>Cristo es el fin, pues Cristo fue el principio;<br/>Cristo, el principio, y el final será.<br/>',NULL,192828,4);
INSERT INTO stanza VALUES('S802','1','La creación está aguardando<br/>Su total liberación.<br/>Cuando sean manifestados<br/>Todos los hijos de Dios.<br/>',NULL,192829,1);
INSERT INTO stanza VALUES('S802','2','La creación gime a una,<br/>Sujeta a vanidad;<br/>De la esclavitud corrupta<br/>Busca plena libertad.<br/>',NULL,192830,2);
INSERT INTO stanza VALUES('S802','3','Gemimos también nosotros<br/>Esperando madurar;<br/>En la filiación creciendo<br/>Con Cristo en conformidad.<br/>',NULL,192831,3);
INSERT INTO stanza VALUES('S802','4','Es por esto que hoy gime<br/>El Espíritu de Dios;<br/>Todo para el bien coopera<br/>De nuestra transformación.<br/>',NULL,192832,4);
INSERT INTO stanza VALUES('S802','5','Dios nos lleva a Su gloria,<br/>Y nos glorificará;<br/>Saturándonos consigo,<br/>Él nos santificará.<br/>',NULL,192833,5);
INSERT INTO stanza VALUES('S802','6','Toda la creación Él lleva<br/>A gloriosa libertad;<br/>El cabrito y el leopardo<br/>Conviviendo en unidad.<br/>',NULL,192834,6);
INSERT INTO stanza VALUES('S802','7','Hemos de ser herederos<br/>Junto con nuestro Señor;<br/>Se verá en Sus hermanos<br/>Su glorioso resplandor.<br/>',NULL,192835,7);
INSERT INTO stanza VALUES('S803','1','La gracia que Dios nos legó,<br/>Su mismo Hijo es;<br/>Qué insondable_es el placer<br/>De disfrutarlo a Él.<br/>¡Tan magno! ¿Cómo contener<br/>Tal gozo sin igual?<br/>Dios hizo, de hijos de maldad,<br/>Su obra magistral.<br/>',NULL,192836,1);
INSERT INTO stanza VALUES('S803','2','La oprimidad creación<br/>Tendrá liberación<br/>Al ver los hijos del gran Dios<br/>En manifestación.<br/>En plenitud, Su eterno plan<br/>Dios manifestará;<br/>La gloria que oculta está,<br/>Todos contemplarán.<br/>',NULL,192837,2);
INSERT INTO stanza VALUES('S803','3','La zarra, un arrayán será,<br/>Espinos ya no habrá;<br/>Donde hubo guerra, sólo paz;<br/>Y maldición, jamás.<br/>Los árboles aplaudirán,<br/>Los montes cantarán;<br/>Los hijos de Dios tarerán<br/>Gloriosa libertad.<br/>',NULL,192838,3);
INSERT INTO stanza VALUES('S803','4','Oculta a diario, en quietud,<br/>La gracia obrando está,<br/>Hasta que todos puedan ver<br/>Lo que Dios logrará.<br/>Dios mismo se impartirá<br/>En todo nuestro ser;<br/>La creación admirará<br/>Su obra en brillantez.<br/>',NULL,192839,4);
INSERT INTO stanza VALUES('S803','5','Los ángeles, ante el Señor,<br/>En brillo sin igual,<br/>Con todo el orbe alabarán<br/>A Dios por Su gran plan.<br/>Las artimañas de Satán<br/>En ruinas quedarán;<br/>Tal fin el diablo sufrirá.<br/>¡A Cristo alabad!<br/>',NULL,192840,5);
INSERT INTO stanza VALUES('S803','6','Dar nuestra vida entera a Dios<br/>Es el mayor placer,<br/>Dejar que a diario pueda Él<br/>Forjarse en nuestro ser.<br/>La gracia que gozamos hoy,<br/>Aunque oculta esté,<br/>Es Dios forjado en nuestro ser,<br/>Y un día se ha de ver.<br/>',NULL,192841,6);
INSERT INTO stanza VALUES('S804','1','En la iglesia hoy se ve<br/>Nuestro destino tan crucial.<br/>Lo más profundo_y vasto es;<br/>Se ve de forma espiritual.<br/>',NULL,192842,1);
INSERT INTO stanza VALUES('S804','2','No es una vista doctrinal:<br/>Lo revelado, Cristo es;<br/>Él es excelso y sin igual,<br/>Jamás se puede comprender.<br/>',NULL,192843,2);
INSERT INTO stanza VALUES('S804','3','Maravilloso y rico es Él,<br/>Profundo, ilimitado es;<br/>Pero tiene necesidad<br/>De hijos que hereden de Él.<br/>',NULL,192844,3);
INSERT INTO stanza VALUES('S804','4','Dios muchas cosas realizó,<br/>Planeó, creó, también logró;<br/>El Heredero el Hijo es,<br/>Quien administra lo de Dios.<br/>',NULL,192845,4);
INSERT INTO stanza VALUES('S804','5','Mas en Su economía hoy,<br/>Son muchos hijos los de Dios;<br/>Uno es el Primogénito,<br/>Que en muchos se multiplicó.<br/>',NULL,192846,5);
INSERT INTO stanza VALUES('S804','6','Hereda Cristo lo de Dios,<br/>Y Dios con Cristo nuestro es;<br/>Crecemos hasta madurar,<br/>Y Dios nos legalizará.<br/>',NULL,192847,6);
INSERT INTO stanza VALUES('S804','7','Coherederos somos con<br/>El Primogénito de Dios;<br/>Cristo y la iglesia nos harán<br/>El universo heredar.<br/>',NULL,192848,7);
INSERT INTO stanza VALUES('S804','8','En la iglesia vemos hoy<br/>Nuestro llamado de valor;<br/>No es el cielo poseer,<br/>Sino en la tierra reyes ser.<br/>',NULL,192849,8);
INSERT INTO stanza VALUES('S804','9','Pobres, mas reyes somos ya<br/>Que el reino hemos de heredar;<br/>La tierra, el trono y lo demás<br/>Del Padre, nuestro ya será.<br/>',NULL,192850,9);
INSERT INTO stanza VALUES('S805','1','Todo señala_al final,<br/>Pronto Jesús volverá;<br/>Listos debemos estar,<br/>¡Cristo ya viene otra vez!<br/>',NULL,192851,1);
INSERT INTO stanza VALUES('S805','chorus','Viene otra vez, viene otra vez;<br/>Va pasando el tiempo ya,<br/>Un clamor en la noche habrá.<br/>Viene otra vez, viene otra vez,<br/>Vírgenes sabias tenemos que ser,<br/>¡Cristo ya viene otra vez!<br/>',NULL,192852,2);
INSERT INTO stanza VALUES('S805','2','El yo debemos negar,<br/>A Cristo sólo mirar,<br/>El tiempo hay que aprovechar,<br/>¡Cristo ya viene otra vez!<br/>',NULL,192853,3);
INSERT INTO stanza VALUES('S805','3','Las necias no aprenderán,<br/>Mas cuando Él venga verán<br/>Su aceite se acabará,<br/>¡Cristo ya viene otra vez!<br/>',NULL,192854,4);
INSERT INTO stanza VALUES('S805','4','Vírgenes sabias jamás,<br/>Con vino se embriagarán;<br/>LLenas de aceite estarán,<br/>¡Cristo ya viene otra vez!<br/>',NULL,192855,5);
INSERT INTO stanza VALUES('S805','5','Al Novio salgamos ya,<br/>Las lámparas preparad,<br/>Hoy el aceite comprad,<br/>¡Cristo ya viene otra vez!<br/>',NULL,192856,6);
INSERT INTO stanza VALUES('S805','6','Cristo acercándose está,<br/>Vela, pues no tardará,<br/>En Su presencia hay que estar,<br/>¡Cristo ya viene otra vez!<br/>',NULL,192857,7);
INSERT INTO stanza VALUES('S806','1','El reino de Dios cerca está:<br/>Diez vírgenes salen a_hallar<br/>Al Novio con lámparas, mas<br/>Prudentes sólo cinco hay.<br/>Las sabias, aceite tendrán;<br/>Su grupo_el aceite compró.<br/>Las necias vacías están;<br/>Su_oportunidad se perdió.<br/>',NULL,192858,1);
INSERT INTO stanza VALUES('S806','2','Señor, Tu mensaje es veraz:<br/>Solo por las sabias vendrás,<br/>Las que compran aceite hoy<br/>Y sin ataduras están.<br/>Sus almas transformadas son,<br/>Llenas sus vasijas están;<br/>Al sus vidas menospreciar,<br/>En Tu reino han de reinar.<br/>',NULL,192859,2);
INSERT INTO stanza VALUES('S806','3','A diario hay que invocar<br/>Y las mechas despabilar;<br/>Se quemará toda vejéz,<br/>Al nuestro espíritu usar.<br/>La más grande necesidad:<br/>Aceite en el vaso verter,<br/>Hasta el corazón saturar<br/>Y más realidad obtener.<br/>',NULL,192860,3);
INSERT INTO stanza VALUES('S806','4','La era oscura está,<br/>Puede que ya vengas, Señor;<br/>Muy pronto ese día vendrá:<br/>Infúndenos santo temor.<br/>El tiempo hay que redimir,<br/>Y así Tu Palabra orar,<br/>Y cada lección aprender<br/>Para preparados estar.<br/>',NULL,192861,4);
INSERT INTO stanza VALUES('S806','5','¡Cuán benditos somos Señor!<br/>Podemos Tu reino traer,<br/>Para que Tú puedas regir<br/>Y, a todos, Tu gloria hacer ver.<br/>¡Qué gloria en las bodas estar,<br/>Contigo en tal dulce unión,<br/>Y en Tu presencia morar!<br/>¡Oh, haznos las sabias, Señor!<br/>',NULL,192862,5);
INSERT INTO stanza VALUES('S807','1','Cristo pronto volverá,<br/>Por Su novia llegará,<br/>Lino fino suplirá:<br/>¡Sé puntual!<br/>Su vida la vestirá,<br/>El sufrir la_adornará,<br/>Actos justos poseerá:<br/>¡Sé puntual!<br/>',NULL,192863,1);
INSERT INTO stanza VALUES('S807','chorus','¡Sé puntual! ¡Sé puntual!<br/>Para las fiestas de bodas,<br/>¡Sé puntual!<br/>Si el yo puedes negar,<br/>Y el Espíritu_aplicar;<br/>El Señor te aprobará:<br/>¡Sé puntual!<br/>',NULL,192864,2);
INSERT INTO stanza VALUES('S807','2','Por las vírgenes vendrá,<br/>Las que aceite extra tendrán,<br/>Mas las necias dejará:<br/>¡Compra hoy!<br/>Con el yo debes tratar,<br/>Hoy un precio hay que pagar;<br/>Compra aceite sin fallar:<br/>¡Compra hoy!<br/>',NULL,192865,3);
INSERT INTO stanza VALUES('S807','3','A Sus siervos llamará,<br/>A los fieles premiará,<br/>Los infieles sufrirán:<br/>¡Sirve hoy!<br/>Tu talento haz contar,<br/>Todo el ego hay que negar,<br/>Sirve a Cristo en verdad:<br/>¡Sirve hoy!<br/>',NULL,192866,4);
INSERT INTO stanza VALUES('S807','4','Por primicias Él vendrá,<br/>Los maduros tomará,<br/>Lo inmaduro dejará:<br/>¡Madurad!<br/>Seco el grano debe estar;<br/>Si tú quieres madurar,<br/>Niega el alma sin cesar,<br/>¡Madurad!<br/>',NULL,192867,5);
INSERT INTO stanza VALUES('S807','5','Vencedores tomará,<br/>Los que dejan todo atrás,<br/>El primer amor tendrán:<br/>¡Vence ya!<br/>Toda muerte hay que vencer,<br/>Hoy con Cristo uno sé,<br/>Hacia el premio corre fiel:<br/>¡vence ya!<br/>',NULL,192868,6);
INSERT INTO stanza VALUES('S807','6','Por Su reino Él vendrá;<br/>Hoy busquemos Su reinar<br/>Para el yo subyugar:<br/>¡Cede ya!<br/>Destronad el yo infiel,<br/>Las lecciones aprended,<br/>Todo a Cristo hay que ceder:<br/>¡Cede ya!<br/>',NULL,192869,7);
INSERT INTO stanza VALUES('S808','1','La fe en nuestro Dios hoy hay que declarar;<br/>De ídolos, volvimos al viviente Dios.<br/>Mezclando Su Palabra con fe y el "¡Amén!",<br/>Volveremos a Cristo una_y otra vez.<br/>',NULL,192870,1);
INSERT INTO stanza VALUES('S808','chorus','La_obra de fe se debe aumentar,<br/>Y el trabajo de amor debe_abundar;<br/>Su santificación en todos obrará;<br/>La_esperanza que_Él viene nos hace velar.<br/>',NULL,192871,2);
INSERT INTO stanza VALUES('S808','2','Aquí a los hermanos se les brinda amor,<br/>Mas tiene que crecer en toda su expresión.<br/>Que el Señor hoy guíe nuestro corazón<br/>Para que se arraigue en el amor de Dios.<br/>',NULL,192872,3);
INSERT INTO stanza VALUES('S808','3','Espíritu, alma y cuerpo Él santificará;<br/>Su novia el Señor así preparará.<br/>Si a Su voz decimos: "¡Oh Señor, amén!",<br/>Estaremos ya listos cuando llame Él.<br/>',NULL,192873,4);
INSERT INTO stanza VALUES('S808','4','Vendrá nuestro Señor, nos llevará con Él:<br/>¡Tan gloriosa esperanza! ¡Ven, Señor! Amén.<br/>Que pronto en el aire te podamos ver<br/>Y, como hijos del día, tal reunión tener.<br/>',NULL,192874,5);
INSERT INTO stanza VALUES('S809','1','Nuestras lámparas tienen aceite,<br/>Y ardientes estamos hoy.<br/>Al espíritu vuélvenos siempre;<br/>¡Cada día vuélvenos, Señor!<br/>',NULL,192875,1);
INSERT INTO stanza VALUES('S809','chorus','¡Señor, amén, aleluya!<br/>¡Cada día ardemos más y más!<br/>¡Señor, amén, aleluya!<br/>Nos volvemos más y más.<br/>',NULL,192876,2);
INSERT INTO stanza VALUES('S809','2','Mas, aceite para Tu venida<br/>Las vasijas deben tener,<br/>Para que nuestras lámparas brillen<br/>Y que nunca dejen de arder.<br/>',NULL,192877,3);
INSERT INTO stanza VALUES('S809','chorus','¡Llénanos, oh, Jesucristo!<br/>¡Cada_instante danos más de Ti!<br/>¡Llénanos, oh, Jesucristo!<br/>Danos realidad así.<br/>',NULL,192878,4);
INSERT INTO stanza VALUES('S809','3','Encendidos permaneceremos<br/>Hasta_el día_en que vuelvas Tú;<br/>Y contigo_a las bodas iremos;<br/>Brilláremos con ardiente luz.<br/>',NULL,192879,5);
INSERT INTO stanza VALUES('S809','chorus','¡Pronto ven, oh, Jesucristo!<br/>¡Llenos y brillantes nos verás!<br/>¡Pronto ven, oh, Jesucristo!<br/>¡Ven, Tu Novia_a disfrutar!<br/>',NULL,192880,6);
INSERT INTO stanza VALUES('S810','1','Se_acerca‿el día, pronto viene Cristo,<br/>Debemos redimir el tiempo hoy;<br/>Para‿escuchar: "¡He‿aquí, el Novio viene!"<br/>De día‿en día‿alístanos, Señor.<br/>',NULL,192881,1);
INSERT INTO stanza VALUES('S810','chorus','Jesús vendrá, ¿iremos a Su‿encuentro?<br/>Jesús vendrá, ¿se‿habrá negado‿el yo?<br/>A las prudentes llevará consigo.<br/>¡Qué‿entremos a las bodas del Señor!<br/>',NULL,192882,2);
INSERT INTO stanza VALUES('S810','2','Señor, queremos redimir el tiempo,<br/>Brote_el "amén" en cada prueba hoy;<br/>Nuestras vasijas, llénalas de_aceite;<br/>Haznos crecer en vida y_en amor.<br/>',NULL,192883,3);
INSERT INTO stanza VALUES('S810','chorus','Es muy precioso_el tiempo, Cristo viene.<br/>Hoy el aceite debemos comprar.<br/>Diciendo: "amén" a nuestras afliciones,<br/>El reino_así por ellas se_obtendrá.<br/>',NULL,192884,4);
INSERT INTO stanza VALUES('S810','3','Oh, tórnanos de los placeres vanos<br/>A Tu_amorosa_y tierna faz, Señor;<br/>Oh, que corramos a_encontrar al Novio,<br/>Solo pendientes a la meta hoy.<br/>',NULL,192885,5);
INSERT INTO stanza VALUES('S810','chorus','Jesús vendrá, ¿a Su presencia_iremos?<br/>Jesús vendrá, ¿hemos de ver Su faz?<br/>Abandonemos ya toda pereza,<br/>Busquemos hoy en Su presencia_estar.<br/>',NULL,192886,6);
INSERT INTO stanza VALUES('S810','4','Salgamos como Su Novia a Su_encuentro,<br/>Que nuestras lámparas den resplandor;<br/>Nuestras vasijas tengan mucho_aceite,<br/>Para con Él gozar satisfacción.<br/>',NULL,192887,7);
INSERT INTO stanza VALUES('S810','chorus','Sí, satisfechos, Cristo con Su Novia,<br/>Sí, satisfechos por la_eternidad;<br/>Oh, qué favor, descanso,_amor y dicha—<br/>Con Cristo,_el Novio, todo disfrutar.<br/>',NULL,192888,8);
INSERT INTO stanza VALUES('S811','1','Su novia_anhela el Señor<br/>Gloriosa ha de ser.<br/>Su corazón satisfará<br/>Cuando ella lista esté.<br/>',NULL,192889,1);
INSERT INTO stanza VALUES('S811','2','Por Su Palabra ella es<br/>Santa, tal como Él;<br/>Manchas y arrugas lavará,<br/>Hasta Su novia ser.<br/>',NULL,192890,2);
INSERT INTO stanza VALUES('S811','3','Los días hay que redimir,<br/>Y la Palabra orar<br/>Comiéndola, diciendo "Amén";<br/>Listos así hay que estar.<br/>',NULL,192891,3);
INSERT INTO stanza VALUES('S811','4','Cortante la Palabra es;<br/>Sí, puede dividir<br/>El alma del espíritu,<br/>Y todo discernir.<br/>',NULL,192892,4);
INSERT INTO stanza VALUES('S811','5','Gracias por Tu Palabra fiel<br/>Tan viva y eficaz;<br/>Por ella hemos de vivir,<br/>Hasta mirar Tu faz.<br/>',NULL,192893,5);
INSERT INTO stanza VALUES('S811','6','Los que te traigan, haznos hoy:<br/>Tu complemento aquí.<br/>Por Tu Palabra, oh Señor,<br/>Danos aún más de Ti.<br/>',NULL,192894,6);
INSERT INTO stanza VALUES('S812','1','Ya las iglesias se preparan para_el Novio aquí.<br/>El tiempo cerca está, ¡Jesús regresará!<br/>El viene pronto_a reclamar Su Novia para Sí,<br/>Para que_ella esté por siempre_unida a Él.<br/>',NULL,192895,1);
INSERT INTO stanza VALUES('S812','chorus','Pronto vendrá el Cristo_Aquel<br/>Que es nuestro_amado Novio fiel.<br/>Hay que velar en oración.<br/>¡Puede que sea hoy! ¡Puede que sea hoy!<br/>',NULL,192896,2);
INSERT INTO stanza VALUES('S812','2','Debemos darle por completo nuestro corazón.<br/>¡Los ídolos dejad; buscadlo sin cesar!<br/>Pues sólo Tú, Señor Jesú,s nos causas tal fervor;<br/>¡Ven pronto y sin tardar! ¡Apremia Tu llegar!<br/>',NULL,192897,3);
INSERT INTO stanza VALUES('S812','3','Gloriosa Novia Él prepara y la quiere ver<br/>Que en lino fino esté, radiante para Él.<br/>Forja en nosotros Tu justicia para así lograr<br/>En esa boda entrar para contigo estar.<br/>',NULL,192898,4);
INSERT INTO stanza VALUES('S813','1','Pronto, Señor, vendrás,<br/>Muy cerca_el día está;<br/>¡Regresa pronto, Señor Jesús!<br/>No tenemos otro<br/>Señor, vida ni amor<br/>Que nuestro Novio, Tú, Jesús.<br/>',NULL,192899,1);
INSERT INTO stanza VALUES('S813','2','La hora cerca está,<br/>Tu voz resonará,<br/>Y en las nubes descenderás.<br/>Qué dulce ha de ser<br/>La novia al Novio ver<br/>Y un amor sin par gozar.<br/>',NULL,192900,2);
INSERT INTO stanza VALUES('S813','3','¡El tiempo vuela ya,<br/>Hemos de ver Tu faz!<br/>¡Amén! ¡Ven pronto, nuestro Señor!<br/>Deseamos verte ya<br/>Y junto a Ti estar,<br/>Dueño de nuestro corazón.<br/>',NULL,192901,3);
INSERT INTO stanza VALUES('S813','4','Sólo un momento más,<br/>El Novio volverá;<br/>Su novia, Él ha de reclamar.<br/>¡Oh, aleluya!<br/>¡Qué gozo nos dará!<br/>Y satisfecho Tú serás.<br/>',NULL,192902,4);
INSERT INTO stanza VALUES('S814','1','¡Gozaos, gozaos! El Novio viene<br/>Y no tardará_en llegar.<br/>El día de Sus gratas bodas<br/>Se_alzará canción triunfal.<br/>',NULL,192903,1);
INSERT INTO stanza VALUES('S814','chorus','¡Oh, día feliz! ¡Oh, qué mañana!<br/>Cuando llege_el Cristo amado;<br/>Con vasos llenos esperemos<br/>Y las lámparas con luz.<br/>¡Gozaos, gozaos! El Novio viene<br/>Y no tardará_en llegar.<br/>El día de Sus gratas bodas<br/>Se_alzará canción triunfal.<br/>',NULL,192904,2);
INSERT INTO stanza VALUES('S814','2','Oh, redimamos hoy el tiempo,<br/>¡Más aceite hay que comprar!<br/>Antes del grito a medianoche<br/>Cada vaso hay que llenar.<br/>',NULL,192905,3);
INSERT INTO stanza VALUES('S814','3','¡Qué gozo es el prepararse<br/>Para unirnos al Señor!<br/>Aunque pasemos aflicciones<br/>Por ganar el galardón!<br/>',NULL,192906,4);
INSERT INTO stanza VALUES('S814','4','Con rapto excelso y regocijo<br/>Esas bodas han de ser;<br/>Le siguen luego los mil años<br/>De celebración con Él.<br/>',NULL,192907,5);
INSERT INTO stanza VALUES('S815','1','Eliezer a sus camellos<br/>Los llevó a descansar<br/>Una tarde junto_al pozo, a_abrevar.<br/>Para Isaac halló una novia<br/>Antes del día caer,<br/>Pues el viaje no fue_en vano para él.<br/>',NULL,192908,1);
INSERT INTO stanza VALUES('S815','chorus','¡Estad listos! El dia se va.<br/>¡Eliezer llamándonos está!<br/>La boda ya se acerca,<br/>Nuestro gozo_ha de_empezar,<br/>Cuando todos los camellos lleguen ya.<br/>',NULL,192909,2);
INSERT INTO stanza VALUES('S815','2','A Rebeca, adornada<br/>Con sus joyas de esplendor,<br/>Hacia Isaac, el novio, la llevó Eliezer.<br/>Cuando Isaac amó a Rebeca,<br/>Y Rebeca amó a Isaac,<br/>¡Qué feliz día de bodas ése fue!<br/>',NULL,192910,3);
INSERT INTO stanza VALUES('S815','3','De Dios Padre ha venido<br/>El Espíritu a buscar<br/>Una novia pura, santa y sin igual.<br/>Pues Isaac ha preparado<br/>Tiendas de amor nupcial,<br/>Y Él quiere_a Su Rebeca_allí_encontrar.<br/>',NULL,192911,4);
INSERT INTO stanza VALUES('S815','4','Hemos dicho "¡Adios!" al mundo,<br/>A parientes y al hogar,<br/>Para ser Su novia pura, santa y fiel.<br/>Con Jesús pronto estaremos<br/>Por toda la eternidad:<br/>¡Oh, qué boda tan alegre ha de ser!<br/>',NULL,192912,5);
INSERT INTO stanza VALUES('S816','1','Lo que ningún profeta vio<br/>O encontró jamás;<br/>En nuestros días ya llegó<br/>En su realidad.<br/>',NULL,192913,1);
INSERT INTO stanza VALUES('S816','chorus','Y ahora es el cumplimiento,<br/>Y el final de todos los tiempos.<br/>Y todos los que creyeron,<br/>Su promesa heredarán.<br/>',NULL,192914,2);
INSERT INTO stanza VALUES('S816','2','Benditos nuestros ojos son<br/>De ver con claridad<br/>Lo que los ángeles jamás<br/>Pudieron contemplar.<br/>',NULL,192915,3);
INSERT INTO stanza VALUES('S816','3','Estamos en el Cuerpo hoy,<br/>Su gracia a mano está;<br/>Hay que animarse a correr<br/>Y el reinó así ganar.<br/>',NULL,192916,4);
INSERT INTO stanza VALUES('S816','4','No nos cansamos al correr,<br/>Nos trae enorme paz;<br/>Pues pronto el Señor vendrá,<br/>Mostrándonos Su faz.<br/>',NULL,192917,5);
INSERT INTO stanza VALUES('S817','1','Vemos que el Señor ya viene;<br/>Por la iglesia Él vendrá;<br/>Es la era de las eras,<br/>Pues Su novia_Él llevará.<br/>',NULL,192918,1);
INSERT INTO stanza VALUES('S817','chorus','¡Oh, qué gloria, es la era de eras!<br/>¡Pronto vendrá el Señor!<br/>Preparad la_iglesia para las bodas,<br/>¡Cristo_y la iglesia_en unión!<br/>',NULL,192919,2);
INSERT INTO stanza VALUES('S817','2','¡Aleluya! Esta era<br/>De recobro es de Dios.<br/>En las iglesias locales,<br/>Su novia Él prepara hoy.<br/>',NULL,192920,3);
INSERT INTO stanza VALUES('S817','3','Todo damos, sin reservas,<br/>Para Su satisfacción,<br/>Y que así Su santa novia<br/>Logre su edificación.<br/>',NULL,192921,4);
INSERT INTO stanza VALUES('S817','chorus','¡Oh, qué gloria, es la era de eras!<br/>¡Pronto vendrá el Señor!<br/>Hoy nos preparamos para las bodas,<br/>¡Cristo y la iglesia en unión!<br/>',NULL,192922,5);
INSERT INTO stanza VALUES('S818','1','Dios se ha propuesto<br/>En la eternidad<br/>Unirse al hombre,<br/>Al Su vida dar;<br/>Al regenerarlo<br/>Y llenar Su ser,<br/>Dios en él se_expresa,<br/>Siendo uno con él.<br/>',NULL,192923,1);
INSERT INTO stanza VALUES('S818','2','A Su propia imagen<br/>Hizo al hombre Dios,<br/>Para que cumpliera<br/>El plan que Él trazó;<br/>Le ofreció el árbol<br/>De la vida a él,<br/>Para convertirlo<br/>En Su esposa fiel.<br/>',NULL,192924,2);
INSERT INTO stanza VALUES('S818','3','Su fluir de vida<br/>Lo transformará;<br/>A Su misma imagen<br/>Lo conformará;<br/>Como complemento<br/>Lo edificará;<br/>Será Su morada<br/>Lo satisfará.<br/>',NULL,192925,3);
INSERT INTO stanza VALUES('S818','4','Todos los llamados<br/>Mezclados con Dios<br/>Son la Ciudad Santa,<br/>Y Su habitación.<br/>Él, Su contenido,<br/>Ellos Su expresión,<br/>Llenos de Su gloria<br/>En perfecta unión.<br/>',NULL,192926,4);
INSERT INTO stanza VALUES('S818','5','Dios allí es el centro,<br/>En el tronó está;<br/>Su vida los guarda<br/>En grata unidad.<br/>Por Su luz de gloria<br/>Andan en la luz<br/>Gozando armonía,<br/>Divinal salud.<br/>',NULL,192927,5);
INSERT INTO stanza VALUES('S818','6','El es su agua viva<br/>Y su provisión;<br/>Su hambre y sed apaga,<br/>¡Qué satisfacción!<br/>Dios mismo es Su templo,<br/>Siempre en Él están;<br/>Frente a Su presencia<br/>Lo adorarán.<br/>',NULL,192928,6);
INSERT INTO stanza VALUES('S819','1','Se propuso_el Dios eterno<br/>En Su pasado_eternal<br/>Un propósito que_alcanza<br/>La futura_eternidad.<br/>En el medio_existe el tiempo<br/>Para realizar Su plan;<br/>Y, en el tiempo, los viajeros<br/>Vamos a la_eternidad.<br/>',NULL,192929,1);
INSERT INTO stanza VALUES('S819','2','Quiere Dios ganar un pueblo<br/>Concertado en Su plan,<br/>Bien unido, edificado,<br/>Un nuevo hombre él será.<br/>Dios quisiera ese vaso<br/>Con Su vida saturar;<br/>Nuestro espíritu mezclado<br/>Con el Suyo, lo obtendrá.<br/>',NULL,192930,2);
INSERT INTO stanza VALUES('S819','3','Dios ha obrado en tres maneras<br/>Para realizar Su plan:<br/>Como Espíritu, Hijo y Padre<br/>Imparténdose está.<br/>La creación nos da la escena:<br/>Cielo, tierra y la luz,<br/>Hizo al hombre tripartito:<br/>Cuerpo, alma espíritu.<br/>',NULL,192931,3);
INSERT INTO stanza VALUES('S819','4','Nuestro espíritu es el centro,<br/>El meollo de Su plan;<br/>Invocando a Jesucristo,<br/>Nuestro al Suyo se unirá.<br/>Centro y circunferencia,<br/>Todo el ser saturará,<br/>Mente y voluntad renueva,<br/>Y hace al corazón Su hogar.<br/>',NULL,192932,4);
INSERT INTO stanza VALUES('S819','5','En Su vida edificados<br/>Y tejidos en amor,<br/>Dios Su plan va realizando,<br/>Cumpliendo lo que empezó.<br/>Oh Señor, crece en nosotros<br/>Para Tu edificación,<br/>Gana el vaso colectivo<br/>Lleno con el mismo Dios.<br/>',NULL,192933,5);
INSERT INTO stanza VALUES('S819','6','El producto y cumplimiento<br/>De Su plan se obtendrá:<br/>Esa iglesia tan gloriosa,<br/>Planeada en la eternidad.<br/>Ese vaso colectivo<br/>Con Su gloria Dios tendrá;<br/>Hoy Tu plan es nuestra meta,<br/>Lógralo en nosotros ya.<br/>',NULL,192934,6);
INSERT INTO stanza VALUES('S820','1','Hoy desea nuestro Dios<br/>Uno con el hombre ser;<br/>Siendo todo para él,<br/>Cumplirá Su buen placer.<br/>',NULL,192935,1);
INSERT INTO stanza VALUES('S820','2','Cuerpo, alma, espíritu:<br/>Sólo un vaso el hombre es<br/>Para recibir a Dios<br/>Como vida y uno ser.<br/>',NULL,192936,2);
INSERT INTO stanza VALUES('S820','3','Al fluir Su vida Dios,<br/>Cambia al hombre en Su expresión;<br/>Piedras preciosas lo hará<br/>Para Su edificación.<br/>',NULL,192937,3);
INSERT INTO stanza VALUES('S820','4','Ésta es la ciudad de Dios,<br/>Su eterna habitación;<br/>Ésta es Jerusalén,<br/>Que le llena el corazón.<br/>',NULL,192938,4);
INSERT INTO stanza VALUES('S820','5','Son los santos en unión,<br/>Bien mezclados con su Dios,<br/>Lo que el Padre diseñó<br/>Antes de la creación.<br/>',NULL,192939,5);
INSERT INTO stanza VALUES('S820','6','En su centro el trono está,<br/>Dios y Cristo en potestad;<br/>El Espíritu allí<br/>Brota como el manantial.<br/>',NULL,192940,6);
INSERT INTO stanza VALUES('S820','7','Cristo en medio del fluir<br/>Es la provisión vital;<br/>Árbol de la vida es,<br/>Que da fruto divinal.<br/>',NULL,192941,7);
INSERT INTO stanza VALUES('S820','8','Dios en Cristo es la luz<br/>Que alumbra a la ciudad;<br/>Esta luz disipará<br/>Toda sombra y mortandad.<br/>',NULL,192942,8);
INSERT INTO stanza VALUES('S820','9','Dios y hombre, hombre y Dios,<br/>Mutuo hogar en comunión;<br/>Dios su contenido es,<br/>Y el hombre, Su expresión.<br/>',NULL,192943,9);
INSERT INTO stanza VALUES('S821','1','La Ciudad Santa nuestra meta es,<br/>Y la porción de toda alma fiel;<br/>Aun cuando nuestro cuerpo vive_aquí,<br/>Está_el espíritu con el Señor allí,<br/>Está_el espíritu con el Señor allí.<br/>',NULL,192944,1);
INSERT INTO stanza VALUES('S821','2','Es nuestra meta la Jerusalén,<br/>Do Dios y el hombre pueden uno ser,<br/>Los que caminan tras el Redentor,<br/>Tendrán derecho de gozar Su bendición,<br/>Tendrán derecho de gozar Su bendición.<br/>',NULL,192945,2);
INSERT INTO stanza VALUES('S821','3','Cuando miramos hacia la ciudad,<br/>Es nuestro anhelo contemplar Tu faz,<br/>Oir el grito que nos lleva a Ti<br/>Y compartir Tu Dios eternamente así,<br/>Y compartir Tu Dios eternamente así.<br/>',NULL,192946,3);
INSERT INTO stanza VALUES('S821','4','Nuestra deseo no es la dulce paz,<br/>Tampoco el gozo que nos llenará,<br/>Nuestra esperanza eres Tú, Señor.<br/>Señor, Tú mismo eres nuestro galardón.<br/>Señor, Tú mismo eres nuestro galardón.<br/>',NULL,192947,4);
INSERT INTO stanza VALUES('S821','5','Escucha ahora nuestro gran clamor,<br/>¡Ven a llevarnos hasta Ti, Señor!<br/>Compartiremos la Santa Ciudad,<br/>Y de Ti mismo nos harás participar,<br/>Y de Ti mismo nos harás participar.<br/>',NULL,192948,5);
INSERT INTO stanza VALUES('S821','6','¡Todas las cosas, nuevas las harás:<br/>La tierra el cielo y todo lo demás!<br/>El Dios de gloria, la porción allí;<br/>Señor, ven pronto a llevarnos junto a Ti,<br/>Señor, ven pronto a llevarnos junto a Ti.<br/>',NULL,192949,6);
INSERT INTO stanza VALUES('S822','1','La ciudad buscaba; en tiendas moró;<br/>Y, yendo_a la gloria, él peregrinó;<br/>Tan grande promesa de Dios recibió,<br/>Que toda la gloria del mundo dejó.<br/>',NULL,192950,1);
INSERT INTO stanza VALUES('S822','chorus','¡Oh, qué bella ciudad!<br/>Allí Dios y_el hombre por siempre morarán.<br/>',NULL,192951,2);
INSERT INTO stanza VALUES('S822','2','La ciudad buscaba, que Dios diseñó;<br/>Terrenas mansiones jamás codició,<br/>Pues Dios prometía la eterna ciudad<br/>Para el peregrino que llegue al final.<br/>',NULL,192952,3);
INSERT INTO stanza VALUES('S822','3','La ciudad buscaba; a veces gimió;<br/>La senda dificil, sin gloria tomó;<br/>Mas cambiaba en gozo todo su pesar,<br/>Fijando su vista en esa ciudad.<br/>',NULL,192953,4);
INSERT INTO stanza VALUES('S822','4','La ciudad buscaba; nosotros también;<br/>La ciudad brillante nuestra meta es.<br/>A los peregrinos que van con Jesús,<br/>Su porción eterna: la ciudad de luz.<br/>',NULL,192954,5);
INSERT INTO stanza VALUES('S823','1','Cuando acabe la carrera,<br/>Si luchare hasta vencer,<br/>A la gloria del Señor ascenderé;<br/>Aunque sufra el martirio,<br/>Si guardare yo la fe,<br/>La ciudad santa obtendré.<br/>',NULL,192955,1);
INSERT INTO stanza VALUES('S823','chorus','En esa Santa ciudad<br/>En el Señor yo moraré,<br/>¡Oh, Jerusalén! ¡Oh, Jerusalén!<br/>Con todos los vencedores<br/>Su nombre alabaré,<br/>En Nueva Jerusalén.<br/>',NULL,192956,2);
INSERT INTO stanza VALUES('S823','2','Afligido, mas con gozo<br/>En la tierra errante soy,<br/>Porque una mejor patria he de hallar;<br/>Otros buscan lo terreno,<br/>Pero lo que aspiro yo<br/>Es la celestial Ciudad.<br/>',NULL,192957,3);
INSERT INTO stanza VALUES('S823','3','Aunque áspero el camino<br/>Y fatiga el andar,<br/>Cobro fuerzas al pensar en la Ciudad;<br/>Aunque llanto me acongoje,<br/>No decae mi corazón;<br/>Yo espero esa ciudad.<br/>',NULL,192958,4);
INSERT INTO stanza VALUES('S823','4','Con propósito yo lucho,<br/>Mi correr con meta es,<br/>Yo persigo sólo el premio celestial;<br/>Lo que queda atrás olvido,<br/>Y me extiendo hasta alcanzar<br/>Esa gloriosa ciudad.<br/>',NULL,192959,5);
INSERT INTO stanza VALUES('S823','chorus','Por Su amor y por Su gracia<br/>La ciudad santa seré;<br/>¡Oh, Jerusalén! ¡Oh, Jerusalén!<br/>Con los santos jubilosos<br/>Alabanzas cantaré,<br/>En Nueva Jerusalén.<br/>',NULL,192960,6);
INSERT INTO stanza VALUES('S824','1','En el principio un huerto se vio,<br/>Mas al final es la ciudad de Dios;<br/>Fue_el huerto centro de Su creación,<br/>Mas la Ciudad es Su_edificación.<br/>',NULL,192961,1);
INSERT INTO stanza VALUES('S824','2','Tanto en el huerto como en la Ciudad<br/>El río y árbol de la vida están;<br/>Tipos de Cristo, suministro real,<br/>Y del Espíritu, el manantial.<br/>',NULL,192962,2);
INSERT INTO stanza VALUES('S824','3','En ese huerto y en esa ciudad<br/>Tres materiales preciosos se ven:<br/>El oro, perlas y piedras sin par,<br/>Para que Dios Su obra pueda hacer.<br/>',NULL,192963,3);
INSERT INTO stanza VALUES('S824','4','Mas en el huerto por la tierra están<br/>Los materiales, sin utilidad;<br/>Pero se ven en la santa ciudad<br/>Edificados en glorioso hogar.<br/>',NULL,192964,4);
INSERT INTO stanza VALUES('S824','5','Dios en el huerto al hombre formó,<br/>De barro su naturaleza fue;<br/>No disfrutaba vida en su interior,<br/>No estaba el árbol de la vida en él.<br/>',NULL,192965,5);
INSERT INTO stanza VALUES('S824','6','Pero el árbol crece en la ciudad<br/>En este hombre colectivo está;<br/>Es Cristo mismo para el hombre allí,<br/>La provisión de vida divinal.<br/>',NULL,192966,6);
INSERT INTO stanza VALUES('S824','7','Dios en el hombre forjándose está;<br/>Dios por Su vida lo transformará<br/>En oro, perlas y piedras sin par<br/>Un Cuerpo conformado a Cristo hará.<br/>',NULL,192967,7);
INSERT INTO stanza VALUES('S824','8','En ese huerto recibió Adán<br/>La ayuda idónea que Dios proveyó;<br/>Mas al final habrá una ciudad<br/>La misma novia que el Señor deseó.<br/>',NULL,192968,8);
INSERT INTO stanza VALUES('S824','9','Esta Ciudad es la edificación<br/>De todos los que Dios justificó;<br/>Ella es la amada Novia del Señor,<br/>Y para Dios, Su misma habitación.<br/>',NULL,192969,9);
INSERT INTO stanza VALUES('S824','10','Es la completa expresión de Dios,<br/>Corporativa y universal;<br/>Es complemento para el Señor<br/>Que en gloria Dios ha de manifestar.<br/>',NULL,192970,10);
INSERT INTO stanza VALUES('S825','1','Oh, Señor, Tus redimidos<br/>Son Tu_amada Novia hoy;<br/>Ella es Tu mismo Cuerpo,<br/>Plenitud y expresión.<br/>Eres todo para ella,<br/>Tus riquezas Tú le das,<br/>Plenamente la colmaste<br/>De Tu gloria_y santidad.<br/>',NULL,192971,1);
INSERT INTO stanza VALUES('S825','chorus','¡Ved la ciudad santa,<br/>Llena de Su gloria!<br/>La_expresión de Dios completa<br/>En la humanidad.<br/>',NULL,192972,2);
INSERT INTO stanza VALUES('S825','2','Dios y el hombre están mezclados:<br/>¡Qué misterio de piedad!<br/>Siendo el hombre Su morada,<br/>Su fulgor puede expresar.<br/>Manifiesta Su belleza<br/>Este vaso universal,<br/>Toda plenitud divina<br/>Con Su gloria y santidad.<br/>',NULL,192973,3);
INSERT INTO stanza VALUES('S825','3','Tal composición viviente<br/>Son los que Dios transformó,<br/>Como piedras muy preciosas<br/>A Jesús los conformó.<br/>Fluye el río de agua viva<br/>Desde el trono del Dios fiel,<br/>Cristo el árbol de la vida<br/>Lleva frutos a granel.<br/>',NULL,192974,4);
INSERT INTO stanza VALUES('S825','4','Son el candelero de oro<br/>Cuya lámpara es Jesús;<br/>Dios en Él, la luz de gloria,<br/>Brilla como Espíritu.<br/>La expresión final y eterna:<br/>Coinherente el hombre y Dios,<br/>Tal morada mutua cumple<br/>El eterno plan de Dios.<br/>',NULL,192975,5);
INSERT INTO stanza VALUES('S826','1','La Nueva Jerusalén:<br/>Una nueva creación,<br/>Nace desde_el mismo Dios<br/>Y es de Dios Su fulgor.<br/>',NULL,192976,1);
INSERT INTO stanza VALUES('S826','chorus','Su imagen, su expresión,<br/>Y su gloria son de Dios;<br/>Mora_allí nuestro Señor,<br/>En la santa ciudad.<br/>',NULL,192977,2);
INSERT INTO stanza VALUES('S826','2','La ciudad de oro es,<br/>Y su calle también;<br/>Doce puertas, perlas son,<br/>Sus cimientos se ven.<br/>',NULL,192978,3);
INSERT INTO stanza VALUES('S826','3','Agua viva fluye allí<br/>Clara como el cristal;<br/>Lleva el árbol vida en sí<br/>Suministro eternal.<br/>',NULL,192979,4);
INSERT INTO stanza VALUES('S826','4','En esa ciudad de luz<br/>Mora Dios, el YO SOY.<br/>Él brillando en Cristo está;<br/>Ya la noche pasó.<br/>',NULL,192980,5);
INSERT INTO stanza VALUES('S827','1','Llena de gloria_y brillantez:<br/>Santa Nueva Jerusalén;<br/>Habitación del hombre_y Dios,<br/>La novia del Cordero es.<br/>',NULL,192981,1);
INSERT INTO stanza VALUES('S827','2','Todos los santos por igual<br/>Componen la santa ciudad;<br/>Son herederos del Señor,<br/>En donde Dios puede morar.<br/>',NULL,192982,2);
INSERT INTO stanza VALUES('S827','3','Cubo perfecto es la ciudad:<br/>Altura, anchura y largo, igual;<br/>En sus medidas no hay error;<br/>Completa es; erguida está.<br/>',NULL,192983,3);
INSERT INTO stanza VALUES('S827','4','La calle, de oro puro es,<br/>Transparente como el cristal;<br/>Nos muestra la vida de Dios<br/>Con Su esencia y calidad.<br/>',NULL,192984,4);
INSERT INTO stanza VALUES('S827','5','Las doce puertas, perlas son:<br/>El hombre que Dios redimió<br/>Y a Su reino trasladó,<br/>Regeneró y transformó.<br/>',NULL,192985,5);
INSERT INTO stanza VALUES('S827','6','Doce cimientos de valor,<br/>Doce preciosas piedras son,<br/>Producto de transformación<br/>Mediante fuego y gran presión.<br/>',NULL,192986,6);
INSERT INTO stanza VALUES('S827','7','Muro de jaspe, diáfano,<br/>La luz gloriosa deja ver;<br/>La gloria singular de Dios,<br/>Cuyo aspecto jaspe es.<br/>',NULL,192987,7);
INSERT INTO stanza VALUES('S827','8','Separa el muro la ciudad<br/>De todo cuanto impuro es;<br/>Por dentro hay oro y perlas, más<br/>Piedras preciosas por doquier.<br/>',NULL,192988,8);
INSERT INTO stanza VALUES('S827','9','¡Dios y el Cordero el templo son!<br/>Su faz gloriosa se verá;<br/>Y Su presencia no se irá;<br/>La adoraremos sin cesar.<br/>',NULL,192989,9);
INSERT INTO stanza VALUES('S827','10','No hay en ella luna o sol,<br/>La gloria de Dios es su luz;<br/>La lámpara el Cordero es,<br/>Que brilla con Su plenitud.<br/>',NULL,192990,10);
INSERT INTO stanza VALUES('S827','11','Del trono del Cordero y Dios,<br/>El río de la vida va,<br/>Y en sus riberas puedes ver<br/>Que el árbol de la vida está.<br/>',NULL,192991,11);
INSERT INTO stanza VALUES('S827','12','Brinda esta vida divinal<br/>No sólo fruto y agua allí,<br/>Mas trae la autoridad de Dios<br/>A la ciudad por el fluir.<br/>',NULL,192992,12);
INSERT INTO stanza VALUES('S827','13','Su calle de oro puro es:<br/>Naturaleza de Su ser;<br/>Nos muestra que se debe andar<br/>Conforme a Dios, en lo que Él es.<br/>',NULL,192993,13);
INSERT INTO stanza VALUES('S827','14','En el gobierno eternal,<br/>El doce indica perfección;<br/>Cuatro por tres nos hace ver<br/>Que el hombre y Dios mezclados son.<br/>',NULL,192994,14);
INSERT INTO stanza VALUES('S827','15','Sombras y muerte cesarán;<br/>Penas y llanto allí no habrá;<br/>Él todo nuevo lo hará;<br/>Dios con el hombre morará.<br/>',NULL,192995,15);
INSERT INTO stanza VALUES('S827','16','La imagen de su Dios y Rey,<br/>Esta ciudad expresará;<br/>Gobierna y cumple así Su plan;<br/>Satisfacción le brindará.<br/>',NULL,192996,16);
INSERT INTO stanza VALUES('S828','1','En la Escritura Santa ved<br/>Los tipos de la grey de Dios:<br/>Su edificio_y Novia son,<br/>Reposo y satisfacción.<br/>',NULL,192997,1);
INSERT INTO stanza VALUES('S828','2','Los tipos de la iglesia en<br/>El Testamento Antiguo están:<br/>La ayuda idónea para Adán<br/>Y el edificio en majestad.<br/>',NULL,192998,2);
INSERT INTO stanza VALUES('S828','3','Al pueblo antiguo de Israel,<br/>Su misma esposa Dios llamó;<br/>Con ellos Él se edificó<br/>Su casa real, ciudad de Dios.<br/>',NULL,192999,3);
INSERT INTO stanza VALUES('S828','4','El encarnado Dios, Jesús,<br/>El Novio de la Novia es;<br/>Su misma vida Él le dio,<br/>Su complemento así logró.<br/>',NULL,193000,4);
INSERT INTO stanza VALUES('S828','5','Como el Hijo de David,<br/>Cristo edifica para Dios<br/>Un templo para Su solaz,<br/>Do pueda ejecutar Su plan.<br/>',NULL,193001,5);
INSERT INTO stanza VALUES('S828','6','Para el Señor Su iglesia es<br/>La Novia, Su consolación;<br/>Es la morada para Dios<br/>En Su vivir y expresión.<br/>',NULL,193002,6);
INSERT INTO stanza VALUES('S828','7','Jerusalén, la nueva, es<br/>La más completa perfección,<br/>Eterno hogar, esposa fiel,<br/>La máxima consumación.<br/>',NULL,193003,7);
INSERT INTO stanza VALUES('S828','8','Ella es la Novia del Señor,<br/>El tabernáculo de Dios;<br/>Es para Él, Su habitación,<br/>Y para Cristo, Su expresión.<br/>',NULL,193004,8);
INSERT INTO stanza VALUES('S828','9','Es la máxima compleción<br/>Del incesante obrar de Dios,<br/>Que en la electa humanidad<br/>Su gloria eterna expresará.<br/>',NULL,193005,9);
INSERT INTO stanza VALUES('S829','1','Dios en Su economía<br/>Quiere a Su Cristo ver<br/>Como_el Centro_y la Cabeza,<br/>Todo armonizado en Él.<br/>',NULL,193006,1);
INSERT INTO stanza VALUES('S829','2','Cristo, la Cabeza y Centro.<br/>Dios en Él, luz eternal;<br/>Cristo al trono exaltado,<br/>Con substancia divinal.<br/>',NULL,193007,2);
INSERT INTO stanza VALUES('S829','3','Cristo, el contenido y vida,<br/>Encabeza todo en luz;<br/>Y los santos como el vaso<br/>Manifiestan Su virtud.<br/>',NULL,193008,3);
INSERT INTO stanza VALUES('S829','4','Satanás se ha inyectado<br/>En el hombre y lo arruinó;<br/>Trajo corrupción y sombras<br/>Para interferir con Dios.<br/>',NULL,193009,4);
INSERT INTO stanza VALUES('S829','5','Cristo vino y se imparte<br/>Como vida al mortal;<br/>Ya la muerte y las tinieblas<br/>No lo pueden dominar.<br/>',NULL,193010,5);
INSERT INTO stanza VALUES('S829','6','Por la iglesia, que es Su Cuerpo,<br/>Cristo todo reunirá;<br/>Todo en Cristo concertado,<br/>En Sí mismo se unirá.<br/>',NULL,193011,6);
INSERT INTO stanza VALUES('S829','7','Bajo Cristo, la Cabeza,<br/>Todo subsistiendo está;<br/>Por la luz que trae la iglesia<br/>Todo existe en unidad.<br/>',NULL,193012,7);
INSERT INTO stanza VALUES('S829','8','Cristo, la Cabeza y centro,<br/>Todo armonizará;<br/>Por el brillo de Su Cuerpo<br/>Todo se libertará.<br/>',NULL,193013,8);
INSERT INTO stanza VALUES('S829','9','No más corrupción ni sombras,<br/>No más muerte y vanidad;<br/>De la esclavitud librado<br/>Todo, por la eternidad.<br/>',NULL,193014,9);
INSERT INTO stanza VALUES('S830','1','El río de agua viva<br/>Fluye del trono de Dios;<br/>Su autoridad nos revela,<br/>También nos trae comunión.<br/>',NULL,193015,1);
INSERT INTO stanza VALUES('S830','chorus','El río de agua viva,<br/>La comunión nos dará;<br/>La_autoridad trae consigo<br/>Por dondequiera que va.<br/>',NULL,193016,2);
INSERT INTO stanza VALUES('S830','2','Es el Espíritu el agua;<br/>Fluye la vida, que es Dios;<br/>Nos trae Su señorío,<br/>Por donde fluye el Señor.<br/>',NULL,193017,3);
INSERT INTO stanza VALUES('S830','3','Fluye en la calle de oro<br/>Para el camino mostrar;<br/>Fluye en la naturaleza<br/>De Dios, para en Él andar.<br/>',NULL,193018,4);
INSERT INTO stanza VALUES('S830','4','Por ambos lados del río,<br/>El árbol de vida está;<br/>Muestra que Dios es comida<br/>Que el río nos brindará.<br/>',NULL,193019,5);
INSERT INTO stanza VALUES('S831','1','Los vasos, hoy de barro,<br/>Translúcidos serán;<br/>Señor, como tesoro,<br/>En mí Tú brillarás.<br/>',NULL,193020,1);
INSERT INTO stanza VALUES('S831','2','El vaso de oro brilla,<br/>Es Dios su resplandor;<br/>Allí el sol no alumbra;<br/>Su misma luz es Dios.<br/>',NULL,193021,2);
INSERT INTO stanza VALUES('S831','3','La más preciosa Piedra<br/>Es Cristo en la ciudad;<br/>Cual jaspe en suma gloria,<br/>Allí Él brillará.<br/>',NULL,193022,3);
INSERT INTO stanza VALUES('S831','4','Tal vaso grande y claro,<br/>Con gloria en plenitud,<br/>Alumbra bien la tierra<br/>Con su radiante luz.<br/>',NULL,193023,4);
INSERT INTO stanza VALUES('S831','5','Verán todos Su gloria<br/>En la nueva creación:<br/>La novia del Cordero<br/>En su consumación.<br/>',NULL,193024,5);
INSERT INTO stanza VALUES('S831','6','Tal vaso tan glorioso<br/>Evoca adoración,<br/>Pues Dios, en el Cordero,<br/>Encuentra Su expresión.<br/>',NULL,193025,6);
INSERT INTO stanza VALUES('S832','1','¡Milagro tal! ¡Misterio es<br/>Que Dios y el hombre uno son!<br/>¡Dios se hizo hombre para que<br/>El hombre llegue a ser Dios!<br/>¡Economía sin igual!<br/>Ni hombre o ángel sondeará<br/>El buen placer de Su amor;<br/>Lo más grandioso logrará.<br/>',NULL,193026,1);
INSERT INTO stanza VALUES('S832','2','Como un Dios-hombre se encarnó<br/>Para que yo llegue a ser Dios;<br/>Su esencia y vida Él me dio<br/>Mas Su Deidad no compartió.<br/>Los atributos que hay en Él<br/>Son las virtudes en mi ser;<br/>Su gloria manifestaré,<br/>Su imagen viva expresaré.<br/>',NULL,193027,2);
INSERT INTO stanza VALUES('S832','3','No solamente vivo yo<br/>Mas vive Dios conmigo hoy;<br/>Y con los santos en unión<br/>En Dios edificado estoy<br/>Como una casa universal<br/>Su Cuerpo orgánico será<br/>Un vaso colectivo que<br/>Expresará todo Su ser.<br/>',NULL,193028,3);
INSERT INTO stanza VALUES('S832','4','Jerusalén, la cumbre es,<br/>De las visiones, el total;<br/>Mezclado con el Triuno Dios<br/>El tripartito hombre está.<br/>Coinherente el hombre y Dios<br/>Son una mutua habitación;<br/>Dios con Su gloria divinal<br/>Brillando en la humanidad<br/>',NULL,193029,4);
INSERT INTO stanza VALUES('S833','1','La salvación en vida, oh Dios,<br/>Cumple con Tu justicia bien;<br/>Jurídica, orgánica,<br/>Completa es, según Tu plan.<br/>',NULL,193030,1);
INSERT INTO stanza VALUES('S833','2','Jurídica es la redención,<br/>Orgánica es la salvación;<br/>Y tu justicia y corazón<br/>Son satisfechos, justo Dios.<br/>',NULL,193031,2);
INSERT INTO stanza VALUES('S833','3','Justificado he sido ya,<br/>Gozo de unión orgánica;<br/>Como Dios-hombre renací;<br/>Hoy santificas todo en mí.<br/>',NULL,193032,3);
INSERT INTO stanza VALUES('S833','4','A Tu imagen me harás,<br/>Tu vida me transformará,<br/>Hasta a la madurez llegar,<br/>Hasta Tu Cuerpo edificar.<br/>',NULL,193033,4);
INSERT INTO stanza VALUES('S833','5','Mi cuerpo Tú redimirás<br/>En filiación, en gloria real;<br/>Morada mutua junto a Ti,<br/>Nueva Jerusalén será.<br/>',NULL,193034,5);
INSERT INTO stanza VALUES('S834','1','La redención Jesús ganó,<br/>¡Salvador admirable!<br/>Con precio Él nos redimió,<br/>¡Salvador admirable!<br/>',NULL,193035,1);
INSERT INTO stanza VALUES('S834','chorus','¡Salvador admirable!<br/>Es mi Jesucristo,<br/>Salvador admirable!<br/>Es Cristo el Señor.<br/>',NULL,193036,2);
INSERT INTO stanza VALUES('S834','2','Lo alabo por Su sangre hoy<br/>¡Salvador admirable!<br/>Reconciliado estoy con Dios,<br/>¡Salvador admirable!<br/>',NULL,193037,3);
INSERT INTO stanza VALUES('S834','3','Me limpia de toda maldad,<br/>¡Salvador admirable!<br/>En mí Él hoy reinando está,<br/>¡Salvador admirable!<br/>',NULL,193038,4);
INSERT INTO stanza VALUES('S834','4','Él cada día mora en mí,<br/>¡Salvador admirable!<br/>Y fiel me hace hasta el fin,<br/>¡Salvador admirable!<br/>',NULL,193039,5);
INSERT INTO stanza VALUES('S834','5','Me da Su vencedor poder,<br/>¡Salvador admirable!<br/>Y, en cada lucha, triunfa Él,<br/>¡Salvador admirable!<br/>',NULL,193040,6);
INSERT INTO stanza VALUES('S834','6','Yo ya le di mi corazón,<br/>¡Salvador admirable!<br/>No ando ya del mundo en pos,<br/>¡Salvador admirable!<br/>',NULL,193041,7);
INSERT INTO stanza VALUES('S835','1','Un día, cuando_oprimía el pecado,<br/>La alabanza en el cielo brotó;<br/>Vino Jesús al nacer de una virgen;<br/>Moró_entre hombres, ¡mi_ejemplo es hoy!<br/>',NULL,193042,1);
INSERT INTO stanza VALUES('S835','chorus','Me amó viviendo; salvo muriendo;<br/>Y, sepultado, mis culpas quitó;<br/>Él me justificó resucitando;<br/>¡Un día viene con gloria y honor!<br/>',NULL,193043,2);
INSERT INTO stanza VALUES('S835','2','Un día Él fue llevado al Calvario,<br/>Un día en el madero murió;<br/>Lleno de angustia, sufrió el desprecio;<br/>Mi Redentos, mis pecados llevó.<br/>',NULL,193044,3);
INSERT INTO stanza VALUES('S835','3','Un día Él fue dejado en el huerto,<br/>Un día Él del dolor reposó;<br/>Ángeles fieles su tumba velaron;<br/>Nuestra esperanza es mi Salvador.<br/>',NULL,193045,4);
INSERT INTO stanza VALUES('S835','4','Un día fue esa piedra rodada,<br/>Un día Él del sepulcro salió;<br/>Resucitado, Él venció la muerte,<br/>Él ascendió y por siempre es Señor.<br/>',NULL,193046,5);
INSERT INTO stanza VALUES('S835','5','Un día ha de sonar la trompeta,<br/>Un día Cristo vendrá con gran luz;<br/>Traerá consigo a los vencedores,<br/>¡Mi Salvador, mi glorioso Jesús!<br/>',NULL,193047,6);
INSERT INTO stanza VALUES('S835','note','**Derechos de autor: J.W.CH. Rodeheaver Co. Derechos reservados.**<br/>',NULL,193048,7);
INSERT INTO stanza VALUES('S836','1','Noble y amoroso<br/>Padeció dolor;<br/>Por los pecadores,<br/>En la cruz sufrió;<br/>Por nuestros pecados,<br/>A la muerte fue.<br/>Cristo es quien salva:<br/>¿Qué harás con Él?<br/>',NULL,193049,1);
INSERT INTO stanza VALUES('S837','1','Se_escuchó la dulce voz:<br/>¡Por Jesús salvo sé!<br/>Di por todo_el derredor:<br/>¡Por Jesús salvo sé!<br/>Por la tierra proclamad,<br/>Su mandato obedeced,<br/>Por los mares anunciad:<br/>¡Por Jesús salvo sé!<br/>',NULL,193050,1);
INSERT INTO stanza VALUES('S837','2','Cuando en plena tempestad:<br/>¡Por Jesús salvo sé!<br/>Al perdido, predicad:<br/>¡Por Jesús salvo sé!<br/>Canten islas de la mar,<br/>Y la tierra el eco dé,<br/>Jubileo celestial,<br/>¡Por Jesús salvo sé!<br/>',NULL,193051,2);
INSERT INTO stanza VALUES('S837','3','En la lucha hay que cantar:<br/>¡Por Jesús salvo sé!<br/>El murió, mas vivo está,<br/>¡Por Jesús salvo sé!<br/>Al contrito corazón,<br/>Cuando ande en lobreguez,<br/>Canta con quedita voz:<br/>¡Por Jesús salvo sé!<br/>',NULL,193052,3);
INSERT INTO stanza VALUES('S837','4','Da al viento fuerte voz:<br/>¡Por Jesús salvo sé!<br/>Alegraos, naciones hoy,<br/>¡Por Jesús salvo sé!<br/>Publicad la salvación,<br/>Que resuena por doquier,<br/>La triunfante y fiel canción:<br/>¡Por Jesús salvo sé!<br/>',NULL,193053,4);
INSERT INTO stanza VALUES('S838','1','Oh, las dulces buenas nuevas<br/>Nuestras son por fe;<br/>Hoy, ayer y para siempre,<br/>Cristo_el mismo es.<br/>Salva_aún a pecadores,<br/>Sana al mortal;<br/>Él alegra_al quejumbroso,<br/>¡Su nombre alabad!<br/>',NULL,193054,1);
INSERT INTO stanza VALUES('S838','chorus','Hoy, ayer y para siempre,<br/>Cristo_el mismo es;<br/>Todo cambia, menos Cristo,<br/>¡Gloria dad Él!<br/>¡Gloria dad Él!<br/>¡Gloria dad Él!<br/>Todo cambia, menos Cristo,<br/>¡Gloria dad Él!<br/>',NULL,193055,2);
INSERT INTO stanza VALUES('S838','2','El que amó a los pecadores<br/>Hoy te busca a ti;<br/>Ven, perdido, a Su estrado,<br/>Póstrate allí.<br/>Dijo así: "No te condeno,<br/>Ve y no peques más":<br/>El perdón que Él otorgaba,<br/>Aún vigente está.<br/>',NULL,193056,3);
INSERT INTO stanza VALUES('S838','3','En la tierra, a los dolientes<br/>El Señor sanó;<br/>Penas y enfermedades<br/>Huyen con Su voz.<br/>Su virtud salió al toque<br/>De una mujer;<br/>Al que busque hoy Su gracia,<br/>Se la da por fe.<br/>',NULL,193057,4);
INSERT INTO stanza VALUES('S838','4','Fue a Emaús con ellos,<br/>Los acompañó;<br/>Hoy camina a nuestro lado<br/>Nuestro buen Pastor,<br/>Pronto lo contemparemos,<br/>¡Señor, pronto ven!<br/>El Jesús que pronto viene,<br/>Siempre el mismo es.<br/>',NULL,193058,5);
INSERT INTO stanza VALUES('S839','1','¡Qué oscuridad cubría mi espíritu!<br/>Qué grande pesar Jesús halló<br/>Cuando vio mi alma en tormenta atroz,<br/>¡Disipó mi noche, me sanó!<br/>',NULL,193059,1);
INSERT INTO stanza VALUES('S839','chorus','Hasta el Calvario Cristo fue por mí,<br/>Él fue por mí, Él fue por mí;<br/>Para así librarme, Él murió por mí,<br/>Jesús murió por mí.<br/>',NULL,193060,2);
INSERT INTO stanza VALUES('S839','2','Siendo un pecador postrado ante Su faz,<br/>Sin saber de gracia o perdón;<br/>Oí un murmullo: "No lamentes más,<br/>Pues Jesús tu deuda ya pagó".<br/>',NULL,193061,3);
INSERT INTO stanza VALUES('S839','3','¡Admirable amor mostró mi Salvador!<br/>Yendo de Su trono a la cruz;<br/>Él mis transgresiones solo las cargó;<br/>Su nombre por siempre alabo yo.<br/>',NULL,193062,4);
INSERT INTO stanza VALUES('S840','1','Oh Jesús, Hijo de Dios,<br/>Salvador del pecador;<br/>De cadenas, rompedor,<br/>Y de manchas, limpiador.<br/>',NULL,193063,1);
INSERT INTO stanza VALUES('S840','2','Tú moriste en la cruz,<br/>Nuestro sustituto, Tú;<br/>Y Tu carne se rasgó<br/>Por nuestro pecado atroz.<br/>',NULL,193064,2);
INSERT INTO stanza VALUES('S840','3','Con Su sangre nos compró<br/>El Cordero redentor;<br/>Toda culpa nos quitó,<br/>Nuestra deuda Él saldó.<br/>',NULL,193065,3);
INSERT INTO stanza VALUES('S840','4','Nada queda por obrar,<br/>Nada queda por cargar,<br/>Sólo Su perdón y amor,<br/>Su luz, paz y bendición.<br/>',NULL,193066,4);
INSERT INTO stanza VALUES('S840','5','Al mirarte, viviré;<br/>Al mirarte, alabaré;<br/>Al mirarte hay sanidad,<br/>Alegría y claridad.<br/>',NULL,193067,5);
INSERT INTO stanza VALUES('S840','6','Oh Jesús, Hijo de Dios,<br/>Salvador del pecador,<br/>Siempre te contemplaré,<br/>Te amaré y alabaré.<br/>',NULL,193068,6);
INSERT INTO stanza VALUES('S841','1','Mi dice_el Salvador:<br/>"Muy débil eres tú,<br/>Ven y vela_en oración;<br/>Seré tu plenitud".<br/>',NULL,193069,1);
INSERT INTO stanza VALUES('S841','chorus','Todo debo a Él,<br/>Todo Él pagó;<br/>El pecado me manchó,<br/>Mas Cristo me lavó.<br/>',NULL,193070,2);
INSERT INTO stanza VALUES('S841','2','Señor, Tu gran poder<br/>Mi lepra ya sanó;<br/>Y mi duro corazón,<br/>Tu amor lo derritió.<br/>',NULL,193071,3);
INSERT INTO stanza VALUES('S841','3','En mí no mora el bien,<br/>Tu gracia aceptaré;<br/>En Tu sangre eficaz<br/>Mis ropas lavaré.<br/>',NULL,193072,4);
INSERT INTO stanza VALUES('S841','4','Y, frente al trono fiel,<br/>Completo en Él seré;<br/>"Mi Jesús por mi murió",<br/>Aún repetiré.<br/>',NULL,193073,5);
INSERT INTO stanza VALUES('S842','1','Cristo se unió a pecadores,<br/>La vida humana viviendo;<br/>Murió por los pecadores,<br/>Gloriosa vida impartiendo.<br/>',NULL,193074,1);
INSERT INTO stanza VALUES('S842','chorus','Nos redimió Jesús,<br/>Por todos Él murió;<br/>Oh sí, por mí Él fue a la cruz,<br/>Por mí murió Jesús.<br/>',NULL,193075,2);
INSERT INTO stanza VALUES('S843','1','Mi soberano Salvador<br/>¿Por mí sangró y murió?<br/>¿Sus sienes santas ofreció<br/>Por un vil como yo?<br/>',NULL,193076,1);
INSERT INTO stanza VALUES('S843','chorus','En la cruz, en la cruz do primero vi la luz,<br/>Y la carga de mi alma se fue;<br/>En la cruz por fe yo ví a Jesús,<br/>Y siempre feliz con Él seré.<br/>',NULL,193077,2);
INSERT INTO stanza VALUES('S843','2','¿Por los pecados que hice yo,<br/>En una cruz gimió?<br/>¡Gracia asombrosa, qué piedad,<br/>E inmensurable amor!<br/>',NULL,193078,3);
INSERT INTO stanza VALUES('S843','3','El sol por eso se escondió,<br/>Su gloria encubrió<br/>Cuando Jesús, el gran Creador,<br/>Por el hombre murió.<br/>',NULL,193079,4);
INSERT INTO stanza VALUES('S843','4','Aunque mi rostro escondo yo,<br/>Al contemplar la cruz;<br/>Se me derrita el corazón<br/>En honda gratitud.<br/>',NULL,193080,5);
INSERT INTO stanza VALUES('S843','5','Jamás mis lágrimas podrán<br/>Pagar por tal amor;<br/>Lo único que puedo hacer<br/>Es darme a Ti, Señor.<br/>',NULL,193081,6);
INSERT INTO stanza VALUES('S844','1','Nada grande o pequeño,<br/>¡Nada hay que hacer!<br/>Pues Jesús lo hizo todo;<br/>Debes tú creer.<br/>',NULL,193082,1);
INSERT INTO stanza VALUES('S844','chorus','"Consumado", Él clamó;<br/>"¡Consumado es!"<br/>Esto_es lo que necesitas,<br/>Pecador, saber.<br/>',NULL,193083,2);
INSERT INTO stanza VALUES('S844','2','Cuando Él dejó Su trono<br/>Vino aquí y murió;<br/>Todo así fue consumado;<br/>Escuchad Su voz.<br/>',NULL,193084,3);
INSERT INTO stanza VALUES('S844','3','Tú cansado y agobiado,<br/>¿Por qué tanto afán?<br/>No te sigas esforzando,<br/>Sólo en Cristo hay paz.<br/>',NULL,193085,4);
INSERT INTO stanza VALUES('S844','4','Hasta que en Cristo creas<br/>Con sencilla fe,<br/>El "hacer" es peligroso,<br/>Puedes perecer.<br/>',NULL,193086,5);
INSERT INTO stanza VALUES('S844','5','Tira ya tus "obras muertas",<br/>Acude al Señor;<br/>Firme en Él, en Él confía,<br/>Hoy, oh pecador.<br/>',NULL,193087,6);
INSERT INTO stanza VALUES('S845','1','¿Por qué_ansiedad, duda_y temor?<br/>Todo pecado, ¿no cargó<br/>Sobre Su Hijo, Dios?<br/>Cristo en la cruz murió por mí.<br/>¿Pudiera Dios luego exigir<br/>Otro pago de mí?<br/>',NULL,193088,1);
INSERT INTO stanza VALUES('S845','2','Completa redención logró<br/>Mis deudas el Señor pagó,<br/>De la ley libre soy.<br/>No temo más la ira de Dios,<br/>Pues con Su sangre me roció,<br/>Cubierto ahora estoy.<br/>',NULL,193089,2);
INSERT INTO stanza VALUES('S845','3','El mi perdón aseguró,<br/>Obtuvo plena absolución<br/>Mis deudas, las saldó.<br/>Dios no reclamará de dos,<br/>De Su Hijo, mi buen Fiador,<br/>Y otra vez de mí.<br/>',NULL,193090,3);
INSERT INTO stanza VALUES('S845','4','Descanso y paz hoy míos son;<br/>Mi Salvador me liberó,<br/>Él todo consumó;<br/>Sé que por Su sangre eficaz,<br/>Dios ya no me condenará,<br/>Pues, ¡Él por mí murió!<br/>',NULL,193091,4);
INSERT INTO stanza VALUES('S846','1','Qué preciosa es la sangre<br/>Del Señor Jesús;<br/>La vertió por pecadores<br/>Sobre la cruz.<br/>',NULL,193092,1);
INSERT INTO stanza VALUES('S846','chorus','Qué preciosa es la sangre<br/>Del Señor Jesús;<br/>Cree en ella y recibe<br/>Plena salud.<br/>',NULL,193093,2);
INSERT INTO stanza VALUES('S846','2','¡Qué preciosa es la sangre!<br/>Te puede sanar;<br/>Si fluye sobre tu alma,<br/>Te limpiará.<br/>',NULL,193094,3);
INSERT INTO stanza VALUES('S846','3','Aunque sean tus pecados<br/>Como el carmesí,<br/>Puede Su sangre preciosa<br/>Lavarte a ti.<br/>',NULL,193095,4);
INSERT INTO stanza VALUES('S846','4','¡Qué preciosa es la sangre!<br/>Que nos redimió;<br/>Hoy perfecta paz ofrece,<br/>Y el perdón.<br/>',NULL,193096,5);
INSERT INTO stanza VALUES('S846','5','Con confianza a Su presencia<br/>Podemos entrar;<br/>Pues la fuente abierta limpia<br/>De todo mal.<br/>',NULL,193097,6);
INSERT INTO stanza VALUES('S846','6','¡Qué preciosa es la sangre!<br/>La victoria da;<br/>Ella vence al pecado<br/>Y a Satanás.<br/>',NULL,193098,7);
INSERT INTO stanza VALUES('S846','7','¡Qué preciosa es la sangre!<br/>Que nos lleva a Dios;<br/>Un camino nuevo y vivo;<br/>¡Damos loor!<br/>',NULL,193099,8);
INSERT INTO stanza VALUES('S847','1','Mi Redentor murió en la cruz,<br/>Todas las deudas nuestras pagó;<br/>Cuando la sangre se ve por señal,<br/>Sobre vosotros pasará Dios.<br/>',NULL,193100,1);
INSERT INTO stanza VALUES('S847','chorus','Si la sangre ve Dios,<br/>Si la sangre ve Dios,<br/>Si la sangre ve Dios,<br/>Pasará sobre vosotros hoy.<br/>',NULL,193101,2);
INSERT INTO stanza VALUES('S847','2','A los más malos, Dios salvará;<br/>Lo que Él promete, lo cumplirá;<br/>Pongan su fe en la sangre eficaz;<br/>Sobre vosotros, Dios pasará.<br/>',NULL,193102,3);
INSERT INTO stanza VALUES('S847','3','Nadie podrá del juicio escapar,<br/>Un justo pago a todos dará;<br/>Hay que creer en la sangre triunfal,<br/>Sobre vosotros, Dios pasará.<br/>',NULL,193103,4);
INSERT INTO stanza VALUES('S847','4','¡Qué compasión! ¡Oh qué gran amor,<br/>Benevolencia y fidelidad!<br/>Bajo Su sangre albérguense hoy<br/>Sobre vosotros, Dios pasará.<br/>',NULL,193104,5);
INSERT INTO stanza VALUES('S848','1','Hay un precioso manantial<br/>De sangre de_Emanuel;<br/>Las manchas quita_al pecador<br/>Que se sumerge en él,<br/>Que se sumerge en él,<br/>Que se sumerge en él;<br/>Las manchas quita al pecador,<br/>Que se sumerge en él.<br/>',NULL,193105,1);
INSERT INTO stanza VALUES('S848','2','Al ver la fuente el ladrón,<br/>En ella se gozó;<br/>Allí también, vil como él,<br/>Podré lavarme yo,<br/>Podré lavarme yo,<br/>Podré lavarme yo;<br/>Allí también, vil como él,<br/>Podré lavarme yo.<br/>',NULL,193106,2);
INSERT INTO stanza VALUES('S848','3','Tu sangre, mi buen Redentor,<br/>Por siempre limpiará,<br/>Hasta que en la gloria esté<br/>Tu pueblo en santidad,<br/>Tu pueblo en santidad,<br/>Tu pueblo en santidad:<br/>Hasta que en la gloria esté<br/>Tu pueblo en santidad.<br/>',NULL,193107,3);
INSERT INTO stanza VALUES('S848','4','Desde que vi el manantial<br/>Que fluye sin cesar,<br/>Tu redentor amor será<br/>Por siempre mi cantar,<br/>Por siempre mi cantar,<br/>Por siempre mi cantar;<br/>Tu redentor amor será,<br/>Por siempre mi cantar.<br/>',NULL,193108,4);
INSERT INTO stanza VALUES('S848','5','Cuando mi torpe lengua esté<br/>En el sepulcro ya,<br/>Más dulcemente cantaré<br/>Tu salvación sin par,<br/>Tu salvación sin par,<br/>Tu salvación sin par;<br/>Más dulcemente cantaré<br/>Tu salvación sin par.<br/>',NULL,193109,5);
INSERT INTO stanza VALUES('S849','1','¿Al Cordero eterno has venido Tú?<br/>¿Te has lavado en Su sangre eficaz?<br/>¿Has confiado en la gracia de Jesús?<br/>¿Te has lavado en Su sangre eficaz?<br/>',NULL,193110,1);
INSERT INTO stanza VALUES('S849','chorus','¿Te has lavado en la sangre<br/>Que tu alma ahora puede limpiar?<br/>¿Ya tus ropas blancas como nieve están?<br/>¿Te has lavado en Su sangre eficaz?<br/>',NULL,193111,2);
INSERT INTO stanza VALUES('S849','2','¿Andas tú a diario juntó al Salvador?<br/>¿Te has lavado en Su sangre eficaz?<br/>¿Has hallado en Su cruz descanso y paz?<br/>¿Te has lavado en Su sangre eficaz?<br/>',NULL,193112,3);
INSERT INTO stanza VALUES('S849','3','Si el Novio viene, ¿limpio tú estarás?<br/>¿Te has lavado en Su sangre eficaz?<br/>¿Para Su presencia lista tu alma está,<br/>Y lavada en Su sangre eficaz?<br/>',NULL,193113,4);
INSERT INTO stanza VALUES('S849','4','Quítate las ropas de pecado hoy,<br/>Y sé limpio en Su sangre eficaz;<br/>Una fuente fluye por el alma vil,<br/>Oh, sé limpio en Su sangre eficaz.<br/>',NULL,193114,5);
INSERT INTO stanza VALUES('S850','1','¿Qué me puede dar perdón?<br/>Sólo de Jesús la sangre;<br/>¿Y un nuevo corazón?<br/>Sólo de Jesús la sangre.<br/>',NULL,193115,1);
INSERT INTO stanza VALUES('S850','chorus','Precioso es el raudal<br/>Que limpia todo mal;<br/>No hay otro manantial.<br/>Sólo de Jesús la sangre.<br/>',NULL,193116,2);
INSERT INTO stanza VALUES('S850','2','De mi mal me limpiará,<br/>Sólo de Jesús la sangre;<br/>El perdón me brindará,<br/>Sólo de Jesús la sangre.<br/>',NULL,193117,3);
INSERT INTO stanza VALUES('S850','3','Mis pecados borrará,<br/>Sólo de Jesús la sangre;<br/>Por Su gracia, no mi obrar,<br/>Sólo de Jesús la sangre.<br/>',NULL,193118,4);
INSERT INTO stanza VALUES('S850','4','Es mi esperanza y paz,<br/>Sólo de Jesús la sangre;<br/>Mi justicia y santidad,<br/>Sólo de Jesús la sangre.<br/>',NULL,193119,5);
INSERT INTO stanza VALUES('S851','1','¿Quieres ser salvo de toda maldad?<br/>Tan sólo hay poder en mi Jesús.<br/>¿Quieres vivir y gozar santidad?<br/>Tan sólo hay poder en Jesús.<br/>',NULL,193120,1);
INSERT INTO stanza VALUES('S851','chorus','Hay poder, poder, sin igual poder,<br/>En Jesús quien murió;<br/>Hay poder, poder, sin igual poder,<br/>En la sangre que El vertió.<br/>',NULL,193121,2);
INSERT INTO stanza VALUES('S851','2','¿Quieres ser libre de orgullo y pasión?<br/>Tan sólo hay poder en mi Jesús.<br/>¡Ven, limpio sé en la sangre del Señor!<br/>Tan sólo hay poder en Jesús.<br/>',NULL,193122,3);
INSERT INTO stanza VALUES('S851','3','¿Quieres más blanco que la nieve estar?<br/>Tan sólo hay poder en mi Jesús.<br/>¡Las manchas quita Su sangre eficaz!<br/>Tan sólo hay poder en Jesús.<br/>',NULL,193123,4);
INSERT INTO stanza VALUES('S851','4','¿Quieres servir a tu Rey y Señor?<br/>Tan sólo hay poder en mi Jesús.<br/>¿Quieres rendirle a diario loor?<br/>Tan sólo hay poder en Jesús.<br/>',NULL,193124,5);
INSERT INTO stanza VALUES('S852','1','El manantial al fin yo vi<br/>Que limpia todo mal;<br/>Por Su costado_herido así<br/>Jesús puede salvar.<br/>',NULL,193125,1);
INSERT INTO stanza VALUES('S852','chorus','El manantial que limpia vi,<br/>Me sumergí_y me limpia a mí,<br/>¡Oh, gloria a Dios me limpia a mí!<br/>Me limpia a mí, me limpia a mí.<br/>',NULL,193126,2);
INSERT INTO stanza VALUES('S852','2','Yo veo alzado al Redentor,<br/>Su sangre me habla allí;<br/>Aviva mi espíritu<br/>Su río carmesí.<br/>',NULL,193127,3);
INSERT INTO stanza VALUES('S852','3','Yo ando ahora en luz con Dios,<br/>El mundo queda atrás;<br/>Hoy tengo un nuevo corazón<br/>Do Cristo reina ya.<br/>',NULL,193128,4);
INSERT INTO stanza VALUES('S853','1','¿Qué puede salvar el alma que errante va?<br/>¡Solo el amor de Cristo!<br/>¿Qué hará que los caídos vivan sin pecar?<br/>¡Solo el amor de Cristo!<br/>',NULL,193129,1);
INSERT INTO stanza VALUES('S853','chorus','¡Nada nos constriñe como Su amor!<br/>¡Nada nos sostiene como Su amor!<br/>Nada en cielo_ tierra gana al pecador,<br/>¡Salvo el amor de Cristo!<br/>',NULL,193130,2);
INSERT INTO stanza VALUES('S853','2','¿Qué deshace la amargura de quien sufre hoy?<br/>¡Solo el amor de Cristo!<br/>¿Qué podrá secar las lágrimas del gemidor?<br/>¡Solo el amor de Cristo!<br/>',NULL,193131,3);
INSERT INTO stanza VALUES('S853','3','¿Qué ungüento curará el herido corazón?<br/>¡Solo el amor de Cristo!<br/>¿Qué podrá regar con alegría el corazón?<br/>¡Solo el amor de Cristo!<br/>',NULL,193132,4);
INSERT INTO stanza VALUES('S853','4','¿Qué rescata al hombre de vivir en vanidad?<br/>¡Solo el amor de Cristo!<br/>¿Qué podrá salvarme de la cruel mortalidad?<br/>¡Solo el amor de Cristo!<br/>',NULL,193133,5);
INSERT INTO stanza VALUES('S854','1','¡Qué Salvador el que por mí murió!<br/>Me ha librado de condenación;<br/>"Todo aquel que crea en el Hijo<br/>Tiene vida eternal".<br/>',NULL,193134,1);
INSERT INTO stanza VALUES('S854','chorus','"De cierto, de cierto digo Yo";<br/>"De cierto", dice hoy el Señor,<br/>"Todo aquel que crea en el Hijo<br/>Tiene vida eternal".<br/>',NULL,193135,2);
INSERT INTO stanza VALUES('S854','2','Toda mi iniquidad, Él la llevó;<br/>Toda mi deuda, Cristo la pagó;<br/>"Todo aquel que crea en el Hijo<br/>Tiene vida eternal".<br/>',NULL,193136,3);
INSERT INTO stanza VALUES('S854','3','Soy pobre, mas confío en mi Señor;<br/>Creo Su palabra, aunque débil soy;<br/>Oh, qué mensaje: "Todo hijo de Dios<br/>Tiene vida eternal".<br/>',NULL,193137,4);
INSERT INTO stanza VALUES('S854','4','No somos dignos, mas no dudaré;<br/>Él no desecha a quien se acerca a Él:<br/>"Todo el que crea", hoy proclamaré,<br/>"Tiene vida eternal".<br/>',NULL,193138,5);
INSERT INTO stanza VALUES('S855','1','¡Oh, gloria, gloria, vida real<br/>He recibido hoy!<br/>Tinieblas, muerte y_el pecar<br/>( ¡Se disiparon de_una vez! )<br/>Se disiparon ya.<br/>¡Se disiparon ya!<br/>¡Se disiparon de_una vez!<br/>',NULL,193139,1);
INSERT INTO stanza VALUES('S856','1','Cristo vino a ser un hombre,<br/>Se vistió de humanidad;<br/>Él murió en una cruz<br/>Y me libró del viejo Adán.<br/>Cristo ha resucitado<br/>Como Espíritu en verdad<br/>Para_hoy mi vida ser.<br/>',NULL,193140,1);
INSERT INTO stanza VALUES('S856','chorus','¡Gloria, gloria, aleluya!<br/>¡Gloria, gloria, aleluya!<br/>¡Gloria, gloria, aleluya!<br/>¡Mi vida Cristo es!<br/>',NULL,193141,2);
INSERT INTO stanza VALUES('S856','chorus','¡Qué victoria, aleluya!<br/>¡Qué victoria, aleluya!<br/>¡Qué victoria, aleluya!<br/>¡Mi todo Cristo es!<br/>',NULL,193142,3);
INSERT INTO stanza VALUES('S857','1','Un hombre de noche llegó a Jesús,<br/>Buscando la senda de vida_y de luz;<br/>Y Cristo le dijo: "Para el reino ver,<br/>Tendrás que renacer"<br/>',NULL,193143,1);
INSERT INTO stanza VALUES('S857','chorus','"¡Tendrás que renacer!"<br/>"¡Tendrás que renacer!"<br/>"De cierto, de cierto te digo a ti:<br/>¡Tendrás que renacer!"<br/>',NULL,193144,2);
INSERT INTO stanza VALUES('S857','2','Oh, hijos de hombres, atentos estad<br/>A lo que Jesús expresó al hablar,<br/>Jamás el mensaje en vano ha de ser:<br/>"Tendrás que renacer".<br/>',NULL,193145,3);
INSERT INTO stanza VALUES('S857','3','Si hoy tú quisieras al Reino entrar,<br/>Y con los benditos en gloria exultar,<br/>Si vida eterna quisieras tener,<br/>"Tendrás que renacer".<br/>',NULL,193146,4);
INSERT INTO stanza VALUES('S858','1','¿Quién libera del pecar?<br/>¡Cristo es! ¡Cristo es!<br/>¿Quién es vida_en nuestro ser<br/>¡Cristo es!<br/>¡Cristo es! ¡Cristo es!<br/>Sólo Él da libertad,<br/>¡Sólo Él!<br/>',NULL,193147,1);
INSERT INTO stanza VALUES('S859','1','Esclavos del pecado sois;<br/>La muerte os hirió;<br/>Mas Cristo nos puede brindar<br/>Total liberación.<br/>Jesús, con Su_eternal poder,<br/>Nos quiere liberar;<br/>Vil muerte nos esperará,<br/>Si no creemos ya.<br/>',NULL,193148,1);
INSERT INTO stanza VALUES('S860','1','Necesitas a Cristo el Salvador:<br/>El mismo Dios que_un día se_encarnó;<br/>En Su cuerpo sufrió todo dolor,<br/>Y por tus manchas Él murió,<br/>¡Lo necesitas!<br/>',NULL,193149,1);
INSERT INTO stanza VALUES('S860','chorus','¡Necesitas, necesitas,<br/>Necesitas a Jesús!<br/>¡Sí, para tu redención!<br/>¡Sí, para tu salvación!<br/>¡Y para vida eternal!<br/>Lo necesitas!<br/>',NULL,193150,2);
INSERT INTO stanza VALUES('S860','2','De los muertos Jesús resucitó,<br/>Para la vida eterna impartir;<br/>Si lo invocas y crees de corazón,<br/>Lo que te falta ha de suplir,<br/>¡Lo necesitas!<br/>',NULL,193151,3);
INSERT INTO stanza VALUES('S860','chorus','¡Necesitas, necesitas,<br/>Necesitas a Jesús!<br/>¡Sí, para tu redención!<br/>¡Sí, para tu salvación!<br/>¡Y para vida eternal!<br/>Lo necesitas!<br/>',NULL,193152,4);
INSERT INTO stanza VALUES('S860','3','Tu alma oscura Él iluminará,<br/>De tus pecados Él te librará;<br/>Con Su sangre tus manchas lavará,<br/>La vida de Dios te dará,<br/>¡Lo necesitas!<br/>',NULL,193153,5);
INSERT INTO stanza VALUES('S860','chorus','¡Necesitas, necesitas,<br/>Necesitas a Jesús!<br/>¡Sí, para tu redención!<br/>¡Sí, para tu salvación!<br/>¡Y para vida eternal!<br/>Lo necesitas!<br/>',NULL,193154,6);
INSERT INTO stanza VALUES('S860','4','En tu vida sientes una escasez,<br/>Y por los años crece más y más;<br/>Sólo Cristo la puede en ti saciar;<br/>Tu vanidad desafiará,<br/>¡Lo necesitas!<br/>',NULL,193155,7);
INSERT INTO stanza VALUES('S860','chorus','Necesitas, necesitas,<br/>Necesitas a Jesús!<br/>Para huir de vanidad,<br/>Y obtener la realidad,<br/>Valor a tu vida dar,<br/>¡Lo necesitas!<br/>',NULL,193156,8);
INSERT INTO stanza VALUES('S860','5','Este mundo de luchas y afán<br/>En los apuros no te da sostén;<br/>Todo es vano, en qué puedes confiar?<br/>Aquí te muestra todo que,<br/>¡Lo necesitas!<br/>',NULL,193157,9);
INSERT INTO stanza VALUES('S860','chorus','¡Necesitas, necesitas,<br/>Necesitas a Jesús!<br/>¡Sí, para tu redención!<br/>¡Sí, para tu salvación!<br/>¡Y para vida eternal!<br/>Lo necesitas!<br/>',NULL,193158,10);
INSERT INTO stanza VALUES('S861','1','¡Del mundo huid! ¡A Cristo ganad!<br/>Puede saciar hoy tu corazón;<br/>¿Qué más quisieras tú encontrar?<br/>¡Todas las cosas vacías son!<br/>',NULL,193159,1);
INSERT INTO stanza VALUES('S861','chorus','Él es tan rico en Su plenitud,<br/>Puede colmar tu necesidad!<br/>Él es tan bueno, ¡cuán dulce es Él!<br/>¡Todo deseo Él saciará!<br/>',NULL,193160,2);
INSERT INTO stanza VALUES('S861','2','¡Del mundo huid! ¡A Cristo ganad!<br/>Él es tu grande necesidad.<br/>Al recibir a Cristo el Señor,<br/>Ya nada más tú desearás.<br/>',NULL,193161,3);
INSERT INTO stanza VALUES('S861','3','Aunque muy grande el mundo es,<br/>Y muy pequeño tu corazón,<br/>Pero el gran mundo con su caudal<br/>No puede darte satisfacción.<br/>',NULL,193162,4);
INSERT INTO stanza VALUES('S861','4','Con este Cristo, gran gozo habrá;<br/>Sin este Cristo, sólo pesar;<br/>Donde está Cristo, hay claridad,<br/>Donde Él no está, sólo oscuridad.<br/>',NULL,193163,5);
INSERT INTO stanza VALUES('S862','1','Cuán tiernamente Jesús hoy nos llama,<br/>Te llama_a ti y a mí;<br/>Pacientemente_Él espera y vela,<br/>¡Vela por ti y por mí!<br/>',NULL,193164,1);
INSERT INTO stanza VALUES('S862','chorus','¡A casa ven!<br/>Si estás cansado, ¡ya ven!<br/>Cuan tiernamente Jesús hoy te llama:<br/>"Pecador, ¡a casa ven!".<br/>',NULL,193165,2);
INSERT INTO stanza VALUES('S862','2','¿Por qué tardarnos si Cristo nos ruega?<br/>Ruega por ti y por mi;<br/>¿Por qué rehuir todas Sus compasiones<br/>Dadas a ti y a mí?<br/>',NULL,193166,3);
INSERT INTO stanza VALUES('S862','3','El tiempo corre, los momentos pasan,<br/>Pasan de ti y de mi;<br/>Llegan las sombras, la muerte se acerca;<br/>¡Viene por ti y por mí!<br/>',NULL,193167,4);
INSERT INTO stanza VALUES('S862','4','Nos prometió el amor más glorioso:<br/>Amor por ti y por mí;<br/>Aunque pecamos,  perdón nos otorga;<br/>Él nos perdonará, ¡sí!.<br/>',NULL,193168,5);
INSERT INTO stanza VALUES('S863','1','¡Cuán tiernamente te llama Jesús!<br/>¡Te llama hoy! ¡Te llama hoy!<br/>¿Por qué te alejas de Su tierno_amor?<br/>¡Hoy ven a tu Salvador!<br/>',NULL,193169,1);
INSERT INTO stanza VALUES('S863','chorus','¡Te llama hoy! ¡Te llama hoy!<br/>¡Llama Jesús! ¡Con ternura, Jesús llama hoy!<br/>',NULL,193170,2);
INSERT INTO stanza VALUES('S863','2','Cristo al cansado llama a descansar,<br/>¡Te llama hoy! ¡Te llama hoy!<br/>Tráele tu carga y te bendecirá:<br/>Él no te rechazará.<br/>',NULL,193171,3);
INSERT INTO stanza VALUES('S863','3','¡Cristo te espera, ven pronto a Él!<br/>¡Te espera hoy! ¡Te espera hoy!<br/>Trae tus pecados y ven a Sus pies;<br/>No te detengas, ya ven.<br/>',NULL,193172,4);
INSERT INTO stanza VALUES('S863','4','¡Cristo suplica, escucha Su voz!<br/>¡Oye Su voz! ¡Oye Su voz!<br/>Se gozará el que crea en Él:<br/>¡Pronto acércate, ven!<br/>',NULL,193173,5);
INSERT INTO stanza VALUES('S864','1','Aunque rojos tus pecados,<br/>Blancos, sí, se tornarán;<br/>Aunque sean cual escarlata,<br/>Como nieve quedarán;<br/>Aunque carmesí fueses,<br/>Cual lana serán;<br/>Aunque rojos tus pecados,<br/>Aunque rojos tus pecados,<br/>Blancos cual nieve serán,<br/>Blancos cual nieve serán.<br/>',NULL,193174,1);
INSERT INTO stanza VALUES('S864','2','Oye Su voz rogando,<br/>¡Vuélvete pronto a Dios!<br/>Oye Su voz rogando,<br/>¡Vuélvete pronto a Dios!<br/>Él es tan compasivo,<br/>Magno es Su amor;<br/>Oye Su voz rogando,<br/>Oye Su voz rogando,<br/>¡Vuélvete pronto a Dios!<br/>¡Vuélvete pronto a Dios!<br/>',NULL,193175,2);
INSERT INTO stanza VALUES('S864','3','Borrará tus pecados,<br/>Y no los recordará;<br/>Borrará tus pecados,<br/>Y no los recordará;<br/>¡"Poned en Mí la vista!",<br/>Dice el Señor.<br/>Borrará tus pecados,<br/>Borrará tus pecados,<br/>Y no los recordará,<br/>Y no los recordará.<br/>',NULL,193176,3);
INSERT INTO stanza VALUES('S865','1','Si tú cansado ya estás del pecar,<br/>Recibe_a Jesús hoy en ti;<br/>Si vida nueva quisieras hallar,<br/>Recibe_a Jesús hoy en ti.<br/>',NULL,193177,1);
INSERT INTO stanza VALUES('S865','chorus','Deja tus dudas atrás;<br/>No lo rechaces ya más;<br/>Hoy abre tu corazón,<br/>Recibe_a Jesús hoy en ti.<br/>',NULL,193178,2);
INSERT INTO stanza VALUES('S865','2','Si tú pureza anhelando estás,<br/>Recibe_a Jesús hoy en ti;<br/>Fuentes que limpian muy cerca están,<br/>Recibe_a Jesús hoy en ti.<br/>',NULL,193179,3);
INSERT INTO stanza VALUES('S865','3','Si tú no puedes tus luchas calmar,<br/>Recibe_a Jesús hoy en ti;<br/>Si tu vacío no puedes llenar,<br/>Recibe_a Jesús hoy en ti.<br/>',NULL,193180,4);
INSERT INTO stanza VALUES('S866','1','Cristo hoy te llama, llama,<br/>Llama_al corazón.<br/>No lo dejes fuera, fuera,<br/>Oye hoy Su voz.<br/>Abre a Él tu corazón;<br/>Déjalo entrar.<br/>Vida_Él quiere darte, darte,<br/>Y limpiar tu mal.<br/>',NULL,193181,1);
INSERT INTO stanza VALUES('S866','chorus','Deja que entre hoy,<br/>Te llama con Su voz;<br/>Deja que entre hoy<br/>A tu corazón.<br/>',NULL,193182,2);
INSERT INTO stanza VALUES('S866','2','¿Por qué aún te tardas, tardas,<br/>En dejarlo entrar?<br/>Él contigo es tierno, tierno,<br/>Bondadoso y real.<br/>A Su voz presta atención;<br/>No lo ofendas más.<br/>Deja que en ti entre, entre;<br/>Gracia te dará.<br/>',NULL,193183,3);
INSERT INTO stanza VALUES('S867','1','Es la vida un suspirar,<br/>Como un manojo_atar,<br/>O como_un relampaguear,<br/>¡Sé puntual!<br/>Dice el tiempo al pasar<br/>Que la suerte echada está,<br/>Y que todo_acabará,<br/>¡Sé puntual!<br/>',NULL,193184,1);
INSERT INTO stanza VALUES('S867','chorus','¡Sé puntual! ¡Sé puntual!<br/>Mientras que Jesús te llama,<br/>¡Sé puntual!<br/>Si persistes en pecar,<br/>Puerta abierta no hallarás,<br/>Tu clamar tarde será,<br/>¡Sé puntual!<br/>',NULL,193185,2);
INSERT INTO stanza VALUES('S867','2','Toda flor se caerá,<br/>Pasará la mocedad,<br/>Y tu vida acabara,<br/>¡Sé puntual!<br/>Mientras Dios te llama hoy,<br/>No te tardes, pecador,<br/>Salvo sé de perdición,<br/>¡Sé puntual!<br/>',NULL,193186,3);
INSERT INTO stanza VALUES('S867','3','Vuela el tiempo al pasar,<br/>Muerte y juicio cerca están;<br/>A Jesús acude ya,<br/>¡Sé puntual!<br/>Piensa bien tu decisión,<br/>Antes de tu defunción,<br/>Huye de la destrucción,<br/>¡Sé puntual!<br/>',NULL,193187,4);
INSERT INTO stanza VALUES('S867','4','Oye, pecador, Su voz,<br/>Y responde a Tu Señor,<br/>Hoy recibe salvación,<br/>¡Sé puntual!<br/>Ven, te cambiará Jesús,<br/>De tinieblas a la luz,<br/>Vida eterna tendrás tú,<br/>¡Sé puntual!<br/>',NULL,193188,5);
INSERT INTO stanza VALUES('S868','1','¿Preparado estás tú,<br/>Para encontrarte con Dios?<br/>¿Preparado estás tú<br/>Para ver a Dios?<br/>¿Listo estás para el encuentro<br/>Que tendrás con Dios?<br/>',NULL,193189,1);
INSERT INTO stanza VALUES('S869','1','¡Oh, no rechaces la verdad!<br/>Tus ojos hoy abre a la luz;<br/>Ablanda ya tu corazón<br/>Y ven a Jesús.<br/>',NULL,193190,1);
INSERT INTO stanza VALUES('S869','chorus','¡Oh, ven sin tardar!<br/>¡Oh, ven sin tardar!<br/>Acepta a Jesús,<br/>Y salvo serás.<br/>',NULL,193191,2);
INSERT INTO stanza VALUES('S869','2','Sé sabio, el tiempo ahora es;<br/>Tal vez mañana no vendrá;<br/>Hoy es el día de salvación,<br/>¡Oh, ven a Jesús!<br/>',NULL,193192,3);
INSERT INTO stanza VALUES('S869','3','Jesús te tiene compasión;<br/>¿Con qué le pagarás Su amor?<br/>Renuncia a toda terquedad,<br/>Y salvo serás.<br/>',NULL,193193,4);
INSERT INTO stanza VALUES('S869','4','Jesús recibe al pecador<br/>Que abra a Él su corazón;<br/>Confía en Él, por ti murió,<br/>¡Oh, ven a Jesús!<br/>',NULL,193194,5);
INSERT INTO stanza VALUES('S870','1','¿Eres oveja que se perdió?<br/>Te_anda buscando el Salvador;<br/>Entre las cien falta una hoy,<br/>¿Eres éste tú?<br/>',NULL,193195,1);
INSERT INTO stanza VALUES('S870','chorus','¿Eres éste tú?<br/>¿Eres éste tú?<br/>Entre las cien falta una hoy,<br/>¿Eres éste tú?<br/>',NULL,193196,2);
INSERT INTO stanza VALUES('S870','2','¿Eres moneda que se perdió?<br/>Te anda buscando el Espíritu;<br/>Entre las diez falta una hoy,<br/>¿Eres éste tú?<br/>',NULL,193197,3);
INSERT INTO stanza VALUES('S870','chorus','¿Eres éste tú?<br/>¿Eres éste tú?<br/>Entre las diez falta una hoy,<br/>¿Eres éste tú?<br/>',NULL,193198,4);
INSERT INTO stanza VALUES('S870','3','Oh, hijo errante, ¿cansado estás?<br/>Por ti el Padre espera ya;<br/>Quiere que vuelvas al dulce hogar,<br/>¿Eres éste tú?<br/>',NULL,193199,5);
INSERT INTO stanza VALUES('S870','chorus','¿Eres éste tú?<br/>¿Eres éste tú?<br/>Quiere que vuelvas al dulce hogar,<br/>¿Eres éste tú?<br/>',NULL,193200,6);
INSERT INTO stanza VALUES('S871','1','¡Eternidad, la eternidad!<br/>¿Cómo pasar la_eternidad?<br/>¡Esta pregunta hay que_enfrentar!<br/>¿Cómo pasar la_eternidad?<br/>Di cómo responderás:<br/>¿Cómo pasar la_eternidad?<br/>',NULL,193201,1);
INSERT INTO stanza VALUES('S871','2','¡Eternidad, la eternidad!<br/>¿Cómo pasar la_eternidad?<br/>A Cristo escogen muchos hoy,<br/>Arrepentidos de su error;<br/>¡Su gran porción Cristo será!<br/>¿Cómo pasar la_eternidad?<br/>',NULL,193202,2);
INSERT INTO stanza VALUES('S871','3','¡Eternidad, la eternidad!<br/>¿Cómo pasar la_eternidad?<br/>La senda angosta al dejar,<br/>Sólo en descenso tu irás;<br/>Entonces, ¿cuál será el final?<br/>¿Cómo pasar la eternidad?<br/>',NULL,193203,3);
INSERT INTO stanza VALUES('S871','4','¡Eternidad, la eternidad!<br/>¿Cómo pasar la_eternidad?<br/>Hoy crece en Cristo el Salvador,<br/>En Su poder confía hoy;<br/>Entonces tú responderás:<br/>"Soy salvo por la eternidad".<br/>',NULL,193204,4);
INSERT INTO stanza VALUES('S872','1','Tal como soy, sin más decir<br/>Que en Tu sangre yo creí,<br/>Ya que me_invitas, vengo así,<br/>Cordero de Dios, vengo_a Ti.<br/>',NULL,193205,1);
INSERT INTO stanza VALUES('S872','2','Tal como soy, sin demorar<br/>Para quitarme mi maldad;<br/>Mi ser, Tu sangre limpiará;<br/>Cordero de Dios, vengo a Ti.<br/>',NULL,193206,2);
INSERT INTO stanza VALUES('S872','3','Tal como soy, en confusión,<br/>Conflicto, duda y tentación,<br/>Aunque con luchas y temor,<br/>Cordero de Dios, vengo a Ti.<br/>',NULL,193207,3);
INSERT INTO stanza VALUES('S872','4','Tal como soy, pobre infeliz,<br/>Por mi carencia a Ti acudí;<br/>Salud y gozo halló aquí,<br/>Cordero de Dios, vengo a Ti.<br/>',NULL,193208,4);
INSERT INTO stanza VALUES('S872','5','Tal como soy, me aceptarás,<br/>Dando el perdón, con vida y paz;<br/>Pues Tu promesa yo creí,<br/>Cordero de Dios, vengo a Ti.<br/>',NULL,193209,5);
INSERT INTO stanza VALUES('S872','6','Tal como soy, Tu gran amor<br/>Ya mis barreras derribó;<br/>Soy todo Tuyo, mi Señor,<br/>Cordero de Dios, vengo a Ti.<br/>',NULL,193210,6);
INSERT INTO stanza VALUES('S873','1','De mi tristeza y oscuridad,<br/>¡Vengo, Jesús! ¡Vengo, Jesús!<br/>A Tu alegría y claridad,<br/>¡Vengo, Jesús, a Ti!<br/>De mi dolencia a Tu sanidad,<br/>De mi pecado, a Tu santidad,<br/>De mi carencia a Tu caudal,<br/>¡Vengo, Jesús, a Ti!<br/>',NULL,193211,1);
INSERT INTO stanza VALUES('S873','2','De mi fracaso, pena y dolor,<br/>¡Vengo, Jesús! ¡Vengo, Jesús!<br/>Para en Tu cruz hallar mi valor,<br/>¡Vengo, Jesús, a Ti!<br/>De mi lamento a Tu confortar,<br/>De mi tormenta a Tu dulce paz,<br/>De mi angustia a Tu bienestar,<br/>¡Vengo, Jesús, a Ti!<br/>',NULL,193212,2);
INSERT INTO stanza VALUES('S873','3','De la inquietud y vana altivez,<br/>¡Vengo, Jesús! ¡Vengo, Jesús!<br/>Quiero Tu voluntad complacer,<br/>¡Vengo, Jesús, a Ti!<br/>Salgo del yo y entro en Tu amor,<br/>De depresión a expectación,<br/>Como las águilas vuelo yo,<br/>¡Vengo, Jesús, a Ti!<br/>',NULL,193213,3);
INSERT INTO stanza VALUES('S873','4','Del gran terror que la tumba da,<br/>¡Vengo, Jesús! ¡Vengo, Jesús!<br/>Para en Tu gozo poder entrar,<br/>¡Vengo, Jesús, a Ti!<br/>De esa ruina en que estaba yo,<br/>A Tu rebaño lleno de amor,<br/>Tu faz gloriosa miraré yo,<br/>¡Vengo, Jesús, a Ti!<br/>',NULL,193214,4);
INSERT INTO stanza VALUES('S874','1','Yo escucho hoy Tu voz,<br/>Me llamas Tú, Jesús,<br/>Para limpiarme en el fluir<br/>De la sangre en la cruz.<br/>',NULL,193215,1);
INSERT INTO stanza VALUES('S874','chorus','Vengo, oh, Señor,<br/>Vengo a Ti Jesús;<br/>Lávame en el fluir<br/>De la sangre en la cruz.<br/>',NULL,193216,2);
INSERT INTO stanza VALUES('S874','2','Yo vil y débil soy,<br/>Mas vi vigor serás;<br/>Tu limpias mi vileza hoy<br/>Hasta sin mancha estar.<br/>',NULL,193217,3);
INSERT INTO stanza VALUES('S874','3','Confirma mi Jesús<br/>En mí Su santo obrar,<br/>Y gracia sobre gracia trae,<br/>Donde reinó el pecar.<br/>',NULL,193218,4);
INSERT INTO stanza VALUES('S874','4','Su testimonio da<br/>Al fiel de corazón,<br/>Que Sus promesas cumplirá,<br/>Si fe trae la oración.<br/>',NULL,193219,5);
INSERT INTO stanza VALUES('S874','5','Por la sangre, ¡aclamad!<br/>¡A Cristo dad loor!<br/>El don de gracia nos legó:<br/>Justicia y vigor.<br/>',NULL,193220,6);
INSERT INTO stanza VALUES('S875','1','Vagué muy lejos de mi Dios,<br/>Hoy vengo_al hogar;<br/>En el pecado_andaba yo;<br/>Hoy vengo al hogar.<br/>',NULL,193221,1);
INSERT INTO stanza VALUES('S875','chorus','Vengo hoy al hogar<br/>Para no vagar;<br/>En Tu amor abrázame;<br/>Hoy vengo al hogar.<br/>',NULL,193222,2);
INSERT INTO stanza VALUES('S875','2','Preciosos años yo perdí,<br/>Hoy vengó al hogar;<br/>Con gran pesar me tornó a Ti,<br/>Hoy vengo al hogar.<br/>',NULL,193223,3);
INSERT INTO stanza VALUES('S875','3','Cansado del pecado estoy,<br/>Hoy vengo al hogar;<br/>Confiando en Tu gran amor,<br/>Hoy vengo al hogar.<br/>',NULL,193224,4);
INSERT INTO stanza VALUES('S875','4','Mi alma abatida está,<br/>Hoy vengo al hogar;<br/>Renueva mi vitalidad,<br/>Hoy vengo al hogar.<br/>',NULL,193225,5);
INSERT INTO stanza VALUES('S875','5','Mi única esperanza aquí,<br/>Hoy vengo al hogar;<br/>Es que Jesús murió por mí,<br/>Hoy vengo al hogar.<br/>',NULL,193226,6);
INSERT INTO stanza VALUES('S875','6','Yo por Su sangre eficaz,<br/>Hoy vengo al hogar;<br/>Oh, límpiame de mi maldad,<br/>Hoy vengo al hogar.<br/>',NULL,193227,7);
INSERT INTO stanza VALUES('S876','1','No pases de mí, oh Cristo,<br/>Tierno Salvador;<br/>Mientras hoy a otros llamas,<br/>Oye mi clamor.<br/>',NULL,193228,1);
INSERT INTO stanza VALUES('S876','chorus','Jesucristo,<br/>Clamo hoy a Ti;<br/>Mientras hoy a otros llamas,<br/>No pases de mí.<br/>',NULL,193229,2);
INSERT INTO stanza VALUES('S876','2','Que en el trono de Tu gracia<br/>Halle dulce paz;<br/>Que, al postrarme, Tú me ayudes<br/>Mi incredulidad.<br/>',NULL,193230,3);
INSERT INTO stanza VALUES('S876','3','En Tu mérito confiando,<br/>Buscaré Tu faz;<br/>Vengo herido, mas Tu gracia<br/>Me puede salvar.<br/>',NULL,193231,4);
INSERT INTO stanza VALUES('S876','4','Tú, mi fuente de consuelo,<br/>Eres vida en mí;<br/>¿A quién tengo en cielo o tierra<br/>Sino solo a Ti?<br/>',NULL,193232,5);
INSERT INTO stanza VALUES('S877','1','Pecador soy, sin remedio;<br/>Ante Ti me postro hoy;<br/>Con problemas, desahuciado:<br/>¡Sálvame, oh Salvador!<br/>',NULL,193233,1);
INSERT INTO stanza VALUES('S877','chorus','¡Sálvame! ¡Sálvame!<br/>¡Sálvame, oh Salvador!<br/>Sálvame de mis problemas,<br/>¡Sálvame, oh Salvador!<br/>',NULL,193234,2);
INSERT INTO stanza VALUES('S878','1','¡Oh Jesús, mi Salvador!<br/>Huyo de la tempestad<br/>A Tu seno protector,<br/>Fiándome de Tu bondad.<br/>Sálvame, Señor Jesús,<br/>De la furia del turbión;<br/>Guía hoy mi barco, Tú,<br/>¡Oh, refúgiame en Tu amor!<br/>',NULL,193235,1);
INSERT INTO stanza VALUES('S878','2','Ningun otro asilo hay;<br/>Desvalido, acudo a Ti;<br/>Mi necesidad me trae,<br/>Porque mi peligro vi.<br/>Solamente Tú, Señor,<br/>Traes consuelo al corazón;<br/>Cubre mi indefenso ser<br/>Con Tus alas, Salvador.<br/>',NULL,193236,2);
INSERT INTO stanza VALUES('S878','3','Cristo, encuentro todo en Ti,<br/>Y no necesito más;<br/>Débil, me pusiste en pie;<br/>Triste, ánimo me das.<br/>Santo y justo eres Tú;<br/>Yo, inmundo pecador;<br/>Al enfermo das salud,<br/>Por Tu gracia, mi Señor.<br/>',NULL,193237,3);
INSERT INTO stanza VALUES('S878','4','La abundante gracia en Ti,<br/>Mi pecado cubrirá;<br/>El arroyo sanador,<br/>Limpio y puro me hará.<br/>Fuente de la vida, hoy<br/>Libremente acudo a Ti;<br/>Salta, manantial de Dios,<br/>Para vida eterna en mí.<br/>',NULL,193238,4);
INSERT INTO stanza VALUES('S879','1','Roca de la eternidad<br/>Que por mí hendidas estás;<br/>Tu costado se rasgó<br/>Sangre y agua allí fluyó,<br/>Dando doble sanidad<br/>Por las culpas y el pecar.<br/>',NULL,193239,1);
INSERT INTO stanza VALUES('S879','2','Aunque obre hasta el fin<br/>No podré Tu ley cumplir;<br/>Aunque sirva sin parar,<br/>Aunque llore sin cesar,<br/>Nada me podrá salvar,<br/>Mas por gracia Tú lo harás.<br/>',NULL,193240,2);
INSERT INTO stanza VALUES('S879','3','Nada tengo que ofrecer,<br/>A Tu cruz me aferraré;<br/>Vísteme, desnudo estoy,<br/>Desvalido a Ti yo voy,<br/>A la fuente acudiré<br/>Lávame o moriré.<br/>',NULL,193241,3);
INSERT INTO stanza VALUES('S879','4','Cuando tenga que expirar,<br/>Y mis ojos ya cerrar,<br/>Cuando frente al trono esté<br/>Para allí comparecer,<br/>Roca hendida para mí,<br/>Déjame esconderme en Ti.<br/>',NULL,193242,4);
INSERT INTO stanza VALUES('S880','1','Guárdame en Tu cruz, Señor;<br/>Su preciosa fuente<br/>Del Calvario trae salud,<br/>Abundantemente.<br/>',NULL,193243,1);
INSERT INTO stanza VALUES('S880','chorus','En la cruz, en la cruz,<br/>Sea mi gloria siempre;<br/>A Tu cruz se aferrará<br/>Mi alma eternamente.<br/>',NULL,193244,2);
INSERT INTO stanza VALUES('S880','2','En la cruz, a un pecador,<br/>Por Tu amor hallaste;<br/>Estrella de resplandor<br/>Sobre mí brillaste.<br/>',NULL,193245,3);
INSERT INTO stanza VALUES('S880','3','Cerca de la cruz, Señor,<br/>Tráeme sus escenas,<br/>Para que yo pueda andar<br/>En su sombra plena.<br/>',NULL,193246,4);
INSERT INTO stanza VALUES('S880','4','Cerca de la cruz, aquí<br/>Vigilo y espero;<br/>Hasta contemplar Tu faz,<br/>Salvador, me esmero.<br/>',NULL,193247,5);
INSERT INTO stanza VALUES('S881','1','Oh, entra en mi corazón, Cristo;<br/>Que vengas, es mi oración.<br/>Mi alma está atribulada;<br/>¡Oh, entra en mi corazón!<br/>',NULL,193248,1);
INSERT INTO stanza VALUES('S881','chorus','Al corazón, al corazón,<br/>A mi corazón, ven, Cristo;<br/>Oh, entra y permanece en él,<br/>En mi corazón, oh, Cristo.<br/>',NULL,193249,2);
INSERT INTO stanza VALUES('S881','2','Oh, entra en mi corazón, Cristo;<br/>Mi vida es tan triste sin Dios;<br/>Es carga pesada el pecado;<br/>¡Oh, entra en mi corazón!<br/>',NULL,193250,3);
INSERT INTO stanza VALUES('S881','3','Oh, entra en mi corazón, Cristo;<br/>¡Oh, limpia mi alma y trae luz!<br/>Oh, que Tu Espíritu llene<br/>Mi alma, domínala Tú.<br/>',NULL,193251,4);
INSERT INTO stanza VALUES('S882','1','A la cruz vengo, Señor;<br/>Pobre, débil, ciego soy;<br/>Este mundo, escoria es;<br/>Dame plena salvación.<br/>',NULL,193252,1);
INSERT INTO stanza VALUES('S882','chorus','Yo confío_en Ti, Señor,<br/>¡Mi Cordero redentor!<br/>Me_arrodillo ante Tu cruz;<br/>Sálvame, Señor Jesús.<br/>',NULL,193253,2);
INSERT INTO stanza VALUES('S882','2','Cuánto mi alma te ansió;<br/>Cuánto mal hay en mi ser;<br/>Mas me dices con dulzor:<br/>"Tus pecados limpiaré".<br/>',NULL,193254,3);
INSERT INTO stanza VALUES('S882','3','Todo a Ti lo rindo hoy:<br/>Tiempo, amigos, provisión;<br/>Mi alma y cuerpo, Tuyos son:<br/>Todo es Tuyo, mi Señor.<br/>',NULL,193255,4);
INSERT INTO stanza VALUES('S882','4','Tus promesas fieles son;<br/>Por Tu sangre, limpio soy;<br/>A Tus pies me postro yo;<br/>En la cruz con Cristo estoy.<br/>',NULL,193256,5);
INSERT INTO stanza VALUES('S883','1','Grato_es contar la_historia<br/>Del celestial favor,<br/>De Cristo y Su gloria,<br/>De Cristo y Su amor;<br/>Me_agrada referirla,<br/>Pues sé que_es la verdad;<br/>Mi_anhelo satisface,<br/>¡Qué_historia sin igual!<br/>',NULL,193257,1);
INSERT INTO stanza VALUES('S883','chorus','¡Cuán bella_es esa_historia!<br/>Mi tema en la gloria<br/>Será la misma historia<br/>De Cristo y de Su amor.<br/>',NULL,193258,2);
INSERT INTO stanza VALUES('S883','2','Grato es contar la historia;<br/>Más admirable es<br/>Que todos mis anhelos<br/>Y sueños a la vez;<br/>Me agrada referirla<br/>Pues me hace mucho bien;<br/>Por eso hoy deseo<br/>Contártela también.<br/>',NULL,193259,3);
INSERT INTO stanza VALUES('S883','3','Grato es contar la historia;<br/>¡Qué fresca y sin vejez!<br/>Pues es, al repetirla,<br/>Más dulce cada vez;<br/>Me agrada referirla,<br/>Pues hay quien nunca oyó<br/>Lo dicho en la Palabra:<br/>La salvación de Dios.<br/>',NULL,193260,4);
INSERT INTO stanza VALUES('S883','4','Grato es contar la historia;<br/>Aunque se sepa bien,<br/>Pues, al que la conoce,<br/>Más dulce es cada vez.<br/>Y cuando entonemos<br/>Una nueva canción,<br/>Será la misma historia<br/>De Cristo y de Su amor.<br/>',NULL,193261,5);
INSERT INTO stanza VALUES('S884','1','¡Salvación sin medida!<br/>¡Salvación sin medida!<br/>¡Salvación sin medida!<br/>¡Cristo salva hoy!<br/>',NULL,193262,1);
INSERT INTO stanza VALUES('S884','chorus','¡Cristo rompe ataduras!<br/>¡Cristo rompe ataduras!<br/>¡Cristo rompe ataduras!<br/>¡Cristo me libró!<br/>',NULL,193263,2);
INSERT INTO stanza VALUES('S884','2','¡Mis pecados, borrados!<br/>¡Y mis grillos, quebrados!<br/>¡Tengo paz de los cielos!<br/>¡Cristo salva hoy!<br/>',NULL,193264,3);
INSERT INTO stanza VALUES('S884','3','Tentación o pecado<br/>Ni Satán, el malvado,<br/>Ni el placer de este mundo<br/>Me esclavizan hoy.<br/>',NULL,193265,4);
INSERT INTO stanza VALUES('S884','4','¡Cantaré aleluya!<br/>¡Cantaré aleluya!<br/>¡Cantaré aleluya!<br/>¡Cristo salva hoy!<br/>',NULL,193266,5);
INSERT INTO stanza VALUES('S885','1','Mi Salvador en la cruz murió<br/>Y mis pecados allí borró;<br/>Por mí, Su sangre Él derramó,<br/>¡Gloria dad a Él!<br/>',NULL,193267,1);
INSERT INTO stanza VALUES('S885','chorus','A Su nombre, gloria,<br/>A Su nombre, gloria,<br/>Por mí, Su sangre Él derramó,<br/>¡Gloria dad a Él!<br/>',NULL,193268,2);
INSERT INTO stanza VALUES('S885','2','¡Maravillosa es mi salvación!<br/>Mora Jesús dulcemente en mí;<br/>Me recibió en la cruz allí,<br/>¡Gloria dad a Él!<br/>',NULL,193269,3);
INSERT INTO stanza VALUES('S885','3','Preciosa fuente de salvación;<br/>Me trae gran gozo y bendición,<br/>Limpio y salvo por ella soy,<br/>¡Gloria dad a Él!<br/>',NULL,193270,4);
INSERT INTO stanza VALUES('S885','4','Ven a esta fuente, oh pecador;<br/>Ponte a los pies de tu Salvador;<br/>Deja que Cristo te sane hoy,<br/>¡Gloria dad a Él!<br/>',NULL,193271,5);
INSERT INTO stanza VALUES('S886','1','Cansado del pecado,<br/>Buscome con amor;<br/>Me trajo al rebaño<br/>En hombros, el Señor.<br/>Los ángeles con su cantar<br/>Hacen los cielos resonar.<br/>',NULL,193272,1);
INSERT INTO stanza VALUES('S886','chorus','¡Oh, amor que busca!<br/>¡Oh, sangre que compra!<br/>Por gracia al rebaño me llevó,<br/>¡Asombrosa gracia me llevó!<br/>',NULL,193273,2);
INSERT INTO stanza VALUES('S886','2','Lavó Él mis heridas,<br/>Aceite y vino echó;<br/>"Te hallé y eres mío",<br/>Seguro susurró.<br/>Jamás oí tan dulce voz<br/>Que alegró mi corazón.<br/>',NULL,193274,3);
INSERT INTO stanza VALUES('S886','3','Él me mostró las huellas,<br/>Sé que por mí sangró,<br/>Y sobre Su cabeza,<br/>Espinas Él llevó;<br/>Pensé, ¿qué vio Jesús en mí<br/>Para agonía así sufrir?<br/>',NULL,193275,4);
INSERT INTO stanza VALUES('S886','4','Sentado en Su presencia,<br/>Contemplo yo Su faz,<br/>Mientras con gran asombro<br/>Repaso Su bondad.<br/>Es corta aun la eternidad<br/>Para de Su virtud contar.<br/>',NULL,193276,5);
INSERT INTO stanza VALUES('S886','5','Mientras las horas pasan,<br/>Todo es tranquilidad;<br/>Espero la mañana,<br/>De eterna claridad,<br/>Cuando el Señor nos lleve a Él,<br/>Para Su pura Novia ser.<br/>',NULL,193277,6);
INSERT INTO stanza VALUES('S887','1','Hoy comemos del viviente, pan,<br/>Y bebemos en el manantial,<br/>Dijo Cristo quien beba de Él,<br/>Nunca, nunca más tendrá, sed.<br/>',NULL,193278,1);
INSERT INTO stanza VALUES('S887','chorus','¿Qué, nunca más tendrá sed?<br/>No, nunca más tendrá sed!<br/>¿Qué, nunca más tendrá sed?<br/>No, nunca más tendrá sed!<br/>Dijo Cristo quien beba de Él,<br/>Nunca, nunca más tendrá sed.<br/>',NULL,193279,2);
INSERT INTO stanza VALUES('S888','1','Lejos del puerto de paz,<br/>En el pecado, yo<br/>Me hundía más y más,<br/>Con la desesperación;<br/>Pero el Señor del mar,<br/>Oyendo mi clamor,<br/>De las aguas me sacó,<br/>¡Hoy salvo soy!<br/>',NULL,193280,1);
INSERT INTO stanza VALUES('S888','chorus','Sólo Su amor<br/>Me levantó;<br/>Nada más me ayudó,<br/>¡Sólo Su_amor!<br/>Sólo Su_amor<br/>Me levantó;<br/>Nada más me ayudó,<br/>¡Sólo Su_amor!<br/>',NULL,193281,2);
INSERT INTO stanza VALUES('S888','2','Todo el corazón le doy,<br/>Siempre me aferro a Él;<br/>Vivo en su presencia hoy,<br/>Siempre lo alabaré.<br/>Un amor tan especial<br/>Merece lo mejor:<br/>Mi servicio, mi cantar,<br/>Mi fe y amor.<br/>',NULL,193282,3);
INSERT INTO stanza VALUES('S888','3','Alma que en peligro estás,<br/>Jesús da salvación;<br/>Su amor te sacará<br/>De en medio del turbión;<br/>Él es el Señor del mar,<br/>Todo se rinde a Él;<br/>Cristo te quiere salvar:<br/>¡Ven, salvo sé!<br/>',NULL,193283,4);
INSERT INTO stanza VALUES('S889','1','Cristo nos recibirá;<br/>De Su gracia,_a todos da:<br/>Al errante, al infiel,<br/>Al que llegue sin hogar.<br/>',NULL,193284,1);
INSERT INTO stanza VALUES('S889','chorus','Entonadlo vez tras vez;<br/>Cristo nos recibirá;<br/>Pecadores, escuchad:<br/>Cristo nos recibirá.<br/>',NULL,193285,2);
INSERT INTO stanza VALUES('S889','2','Él descanso nos dará;<br/>Su palabra es veraz;<br/>Hasta al más vil pecador,<br/>Cristo lo recibirá.<br/>',NULL,193286,3);
INSERT INTO stanza VALUES('S889','3','Ya no hay condenación<br/>Ni Su ley me juzga hoy,<br/>Para Aquel que me lavó,<br/>Sus demandas ya cumplió.<br/>',NULL,193287,4);
INSERT INTO stanza VALUES('S889','4','Cristo aún me recibió,<br/>Siendo yo tan pecador;<br/>A Su gloria entraré,<br/>Ya que mis manchas borró.<br/>',NULL,193288,5);
INSERT INTO stanza VALUES('S890','1','He aquí_un misterio_oculto,<br/>¡Oculto_a la_historia_humana!<br/>Oye_el misterio glorioso;<br/>¡Con Cristo uno serás!<br/>¡Gloria, gloria, aleluya!<br/>¡Gloria, gloria, aleluya!<br/>Oye_el misterio glorioso;<br/>¡Con Cristo uno serás!<br/>',NULL,193289,1);
INSERT INTO stanza VALUES('S891','1','¡El Salvador conmigo es uno!<br/>¡Gran misterio es!<br/>¡Qué salvación maravillosa,<br/>Dios en Su Hijo es!<br/>¡Aleluya! ¡Aleluya!<br/>¡Gran misterio es! ''<br/>¡Nada en el cielo o en la tierra<br/>Me apartará de Él!<br/>',NULL,193290,1);
INSERT INTO stanza VALUES('S892','1','Enséñame qué indica<br/>La cruz alzada allí,<br/>Con el Hijo del Hombre<br/>Sangrando_hasta morir.<br/>Enséñame el precio<br/>Que salva al pecador;<br/>Y el valor de_una alma<br/>Enséñame, Señor.<br/>',NULL,193291,1);
INSERT INTO stanza VALUES('S892','2','Enséñame qué indica<br/>La sangre carmesí<br/>Y el agua que brotaba<br/>De Tu costado allí.<br/>Oh, dime que si fuera<br/>Quien único pecó,<br/>Aún habrías muerto<br/>Por mí, oh Salvador.<br/>',NULL,193292,2);
INSERT INTO stanza VALUES('S892','3','Enséñame qué indica<br/>Tu singular amor<br/>Que sobrepasa toda<br/>Mi desesperación.<br/>Enséñame, y arda<br/>Mi frío corazón<br/>Con esa llama viva<br/>De Tu ferviente amor.<br/>',NULL,193293,3);
INSERT INTO stanza VALUES('S892','4','Enséñame qué indica,<br/>Pues yo pecado soy,<br/>Y Tu inmensa gracia<br/>Y amor me conquistó.<br/>Enséñame que eres<br/>Mi esperanza hoy,<br/>Ya que en la cruz moriste<br/>Por mí, buen Salvador.<br/>',NULL,193294,4);
INSERT INTO stanza VALUES('S892','5','Enséñame qué indica<br/>Este descanso y paz,<br/>Que a todos los cargados<br/>Que creen en Tí, Tú das.<br/>Ya que soy un rebelde,<br/>Recibo Tu perdón:<br/>Ya que Tú lo requieres,<br/>Yo creo en Ti, Señor.<br/>',NULL,193295,5);
INSERT INTO stanza VALUES('S892','6','Oh Redentor eterno,<br/>No traigo otra oración;<br/>Puesto que me la ofreces,<br/>Recibo salvación.<br/>Y ya que me aceptas,<br/>Te adoro y doy loor;<br/>Ya que Tu amor constriñe<br/>Te alabo, mi Señor.<br/>',NULL,193296,6);
INSERT INTO stanza VALUES('S892','note','**Usado con permiso**<br/>',NULL,193297,7);
INSERT INTO stanza VALUES('S893','1','Si yo gano_el mundo_y pierdo a Cristo,<br/>¿Qué valdría un día_aparte de_Él?<br/>¿Hallaría paz mi alma inquieta<br/>En las cosas que_han de perecer?<br/>Si yo gano_el mundo_y pierdo a Cristo,<br/>¿Es la vida digna sin Su luz?<br/>¿Pueden los placeres de_este mundo<br/>Igualar a_un día con Jesús?<br/>',NULL,193298,1);
INSERT INTO stanza VALUES('S893','2','Si tuviera fama y riquezas,<br/>Y un nombre_amado por doquier,<br/>Mas, sin esperanza y sin puerto,<br/>¿Adónde mi barca llevaré?<br/>Si yo gano el mundo y pierdo a Cristo,<br/>Quien la cruz llevó, y murió por mi,<br/>¿Podrá el mundo entero ser refugio<br/>Donde, en mi angustia, pueda ir?<br/>',NULL,193299,2);
INSERT INTO stanza VALUES('S893','3','¡Oh, qué vaciedad sin este Cristo!<br/>¡Sólo penas y pecado aquí!<br/>Y la eternidad sin Él, ¡qué oscura!<br/>Sólo angustia y noches sin fin.<br/>Si viviera yo sin este Cristo,<br/>Cuando muera al fin, ¿cómo será?<br/>¡Oh, sin Él en el valle de sombras!<br/>¡Y sin Él por la eternidad!<br/>',NULL,193300,3);
INSERT INTO stanza VALUES('S893','4','¡Oh, qué gozo es tener a Cristo!<br/>¡Es un bálsamo al corazón!<br/>¡No hay ni un pecado que Él no borre!<br/>¡De tristezas, es Consolador!<br/>Si yo tengo a Cristo, sólo a Cristo,<br/>Nada de este mundo, sólo a Él,<br/>Oh, entonces todo es mío en Cristo,<br/>Pues mi todo Él ha de proveer.<br/>',NULL,193301,4);
INSERT INTO stanza VALUES('S894','1','¿Qué gano_en tanto laborar?<br/>No hay nada nuevo bajo_el sol;<br/>Y lo pasado se_esfumó,<br/>¡Todo es vanidad!<br/>',NULL,193302,1);
INSERT INTO stanza VALUES('S894','chorus','¡Vanidad! ¡Vanidad!<br/>¡Todo es vanidad!<br/>Es como querer,<br/>El viento atrapar.<br/>',NULL,193303,2);
INSERT INTO stanza VALUES('S894','2','La vida humana trae afán,<br/>La ciencia añade más pesar;<br/>Molestias hay en el saber,<br/>¡Todo es vanidad!<br/>',NULL,193304,3);
INSERT INTO stanza VALUES('S894','3','¿Qué de riquezas y placer?<br/>O del disfrute familiar?<br/>Las quejas permanecerán,<br/>¡Todo es vanidad!<br/>',NULL,193305,4);
INSERT INTO stanza VALUES('S894','4','Si ganas con dificultad,<br/>O logras con facilidad,<br/>La muerte lo arrebatará,<br/>¡Todo es vanidad!<br/>',NULL,193306,5);
INSERT INTO stanza VALUES('S894','5','Acuérdate de tu Creador<br/>En días de tu mocedad,<br/>Con Él tendrás satisfacción,<br/>¡Pues no es vanidad!<br/>',NULL,193307,6);
INSERT INTO stanza VALUES('S894','chorus','¡Todo es vanidad!<br/>¡Cristo es realidad!<br/>Sin Él, perderás,<br/>Con Él, ganarás.<br/>',NULL,193308,7);
INSERT INTO stanza VALUES('S895','1','Yo buscaba una fuente<br/>Que pudiera_apagar mi sed,<br/>Al beber de muchas fuentes<br/>Satisfecho no pude ser.<br/>Pero_un día lo hallé,<br/>La sed en mí Él sació;<br/>De mi ser hoy brotan aguas,<br/>Abundantes son,<br/>¡De_Él yo bebo!<br/>',NULL,193309,1);
INSERT INTO stanza VALUES('S895','chorus','Jesucristo es mi vida,<br/>Jesucristo vida es;<br/>Él sí me satisface,<br/>Clama a Cristo, prueba y ve.<br/>',NULL,193310,2);
INSERT INTO stanza VALUES('S895','2','Al probar de esa fuente,<br/>Un lugar semejante ansié;<br/>Vi en visión en un gran monte:<br/>Reunión en Jerusalén<br/>Luego un día Él me halló,<br/>Su iglesia me mostró;<br/>Gozo eterno aquí encontré, mi<br/>Búsqueda cesó.<br/>¡Aleluya!<br/>',NULL,193311,3);
INSERT INTO stanza VALUES('S895','3','Buscador, ya más no luches;<br/>¿Por qué andas con tanto afán?<br/>Abre el corazón creyendo,<br/>Clama a Cristo y Él entrará.<br/>Luego hoy le encontrarás,<br/>Su nombre al invocar,<br/>Te hará uno con Él y<br/>No serás igual.<br/>¡Ni quisieras!<br/>',NULL,193312,4);
INSERT INTO stanza VALUES('S896','1','Mis días sin fe se volvieron vacíos,<br/>Mientras buscaba cómo<br/>Aliviar mi gran carencia;<br/>Pero_en vano busqué.<br/>El mundo‿intentó con placer engañarme,<br/>Mas muy dentro de mí<br/>Yo‿anhelaba algo real.<br/>Este mundo mintió.<br/>',NULL,193313,1);
INSERT INTO stanza VALUES('S896','chorus','Mi sentir no mentía,<br/>Al tratar de‿acoplarme,<br/>Algo dentro me faltaba,<br/>¿Por qué no_honesto ser?<br/>',NULL,193314,2);
INSERT INTO stanza VALUES('S896','2','Dudé al oír esa vieja historia<br/>Del llamado "Señor";<br/>Mas aún me preguntaba,<br/>¿De verdad es Señor?<br/>Leyendo,‿encontré que me‿habló Su Palabra,<br/>Disipando lo vano.<br/>En la luz de Su presencia,<br/>A Jesús recibí.<br/>',NULL,193315,3);
INSERT INTO stanza VALUES('S896','chorus','Ahora juntos crecemos<br/>Hasta Su plenitud.<br/>¡Oh, Señor Jesús, Te amo!<br/>Eres vida en mí.<br/>',NULL,193316,4);
INSERT INTO stanza VALUES('S897','1','Se terminó el gozo de las bodas<br/>Con su placer: el vino se_acabó;<br/>Así la vida humana, como el vino,<br/>También se agota_hasta ver a Jesús.<br/>',NULL,193317,1);
INSERT INTO stanza VALUES('S897','chorus','Llegó Jesús, cambio el agua en vino.<br/>Llegó Jesús, lo_oscuro a disipar.<br/>La muerte_Él toca y cambia_a vida_eterna,<br/>Da vista al ciego,_y fuerzas al que cae.<br/>',NULL,193318,2);
INSERT INTO stanza VALUES('S897','2','Vino a Jesús de noche un hombre justo;<br/>Buscaba más doctrinas entender.<br/>Ellas no cambian al hombre caído;<br/>Para cambiar, "tendrás que renacer".<br/>',NULL,193319,3);
INSERT INTO stanza VALUES('S897','3','Una mujer que no tuvo marido,<br/>Pues muchos la dejaron con más sed,<br/>Tomaba a diario el agua que no sacia;<br/>Se sed cesó, Jesús le dio a beber.<br/>',NULL,193320,4);
INSERT INTO stanza VALUES('S897','4','Un hombre en la multitud yacía,<br/>Sin fuerzas para en el estanque entrar.<br/>La religión, la ley, no lo ayudaba;<br/>Le habló Jesús, y lo pudo salvar.<br/>',NULL,193321,5);
INSERT INTO stanza VALUES('S897','5','Muerto en la tumba, Lazaro yacía;<br/>Hubo gran duelo y lamentación.<br/>Él fue vendado, preso del silencio;<br/>Jesús llegó, y al muerto despertó.<br/>',NULL,193322,6);
INSERT INTO stanza VALUES('S897','6','Y hasta hoy Jesús es tan viviente;<br/>De toda muerte, Él puede salvar,<br/>Abre tu corazón, Su nombre invoca;<br/>Vendrá a ti, y tú renacerás.<br/>',NULL,193323,7);
INSERT INTO stanza VALUES('S898','1','¡Todo_está listo, ven a comer!<br/>Ven, pues la mesa puesta está;<br/>Hambriento y cansado, ven,<br/>Y nutrido tú serás.<br/>',NULL,193324,1);
INSERT INTO stanza VALUES('S898','chorus','Oigan el llamado,<br/>Quien quiera, venga ya;<br/>A Dios demos gloria<br/>Por salvación sin par.<br/>',NULL,193325,2);
INSERT INTO stanza VALUES('S898','2','¡Todo está listo, ven a comer!<br/>Ven, pues la puerta abierta está;<br/>Te espera un lugar de honor<br/>Al lado del Salvador.<br/>',NULL,193326,3);
INSERT INTO stanza VALUES('S898','3','¡Todo está listo, ven a comer!<br/>La bienvenida Él te da;<br/>No te demores, ¡presto ven!<br/>Pues hoy te puede salvar.<br/>',NULL,193327,4);
INSERT INTO stanza VALUES('S898','4','¡Todo está listo, ven a comer!<br/>Libre de lucha mundanal,<br/>Al rico Cristo de Dios, ven,<br/>Y bebe vida eternal.<br/>',NULL,193328,5);
INSERT INTO stanza VALUES('S899','1','Prueba y ve, qué bueno es Él;<br/>Prueba y ve, qué bueno es Él.<br/>Es para ti, y para mí;<br/>Probemos pues, qué bueno es Él.<br/>',NULL,193329,1);
INSERT INTO stanza VALUES('S899','2','Clama "Oh Señor", y Él te cambiará;<br/>Clama "Oh Señor", y Él te cambiará;<br/>Su gracia a ti otorgará,<br/>Si por doquier clamas: "¡Señor!".<br/>',NULL,193330,2);
INSERT INTO stanza VALUES('S899','3','Amor real tú sentirás<br/>Amor real tú sentirás.<br/>De Dios vendrá, el fluir de amor;<br/>Y amor real conocerás.<br/>',NULL,193331,3);
INSERT INTO stanza VALUES('S899','4','Gloria al Señor por Su vida en ti;<br/>Gloria al Señor por Su vida en ti.<br/>Algo de Cristo se infundió<br/>Dentro de ti, ¡gloria al Señor!<br/>',NULL,193332,4);
INSERT INTO stanza VALUES('S900','1','¿Sabes que fuiste_escogido<br/>Antes del mundo_empezar,<br/>Que Dios te_ha seleccionado<br/>Como parte de Su plan?<br/>Algo muy dentro de ti<br/>Te confirma que es así,<br/>Por eso_es que_estás aquí<br/>Y tienes ese sentir.<br/>',NULL,193333,1);
INSERT INTO stanza VALUES('S900','2','Los pecados que hiciste<br/>Todo lo que has hecho tú,<br/>Dios ya todo ha perdonado,<br/>Gracias a Su Hijo, Jesús.<br/>Ya no luches, sólo cree,<br/>La Palabra es veraz.<br/>Sólo tienes que dar gracias:<br/>Por ti, todo Él hizo ya.<br/>',NULL,193334,2);
INSERT INTO stanza VALUES('S900','3','¿Sabes tú que la Palabra<br/>Testamento es del Señor?<br/>Todo lo que Cristo hizo<br/>A Sus hijos lo legó.<br/>Eres uno de esos hijos,<br/>¡Incluido tú estás!<br/>Ahora por fe has heredado<br/>Todo lo que Él hizo ya.<br/>',NULL,193335,3);
INSERT INTO stanza VALUES('S900','4','¿Sabes tú que los creyentes<br/>Somos familia de Dios?<br/>Por eso es que disfrutamos,<br/>Todo lo que Él es hoy.<br/>Él es Dios, nosotros, pueblo.<br/>Lo amamos más y más;<br/>Hoy contentos, gracias damos,<br/>Lo alabamos, ¡Gloria a Dios!<br/>',NULL,193336,4);
INSERT INTO stanza VALUES('S900','5','Solo sé que lo amamos,<br/>Por lo que Él ha hecho aquí.<br/>Él nos trajo a la iglesia.<br/>Uno somos, ¡Gloria a Dios!<br/>¡Qué gozo estar incluidos!<br/>¡Qué gloriosa comunión!<br/>Por eso es que te invitamos<br/>A la familia de Dios.<br/>',NULL,193337,5);
INSERT INTO stanza VALUES('S901','1','¡Qué día tan feliz,<br/>Cuando no pude resistir,<br/>Y Cristo me sacó de la oscuridad<br/>Al Reino de Su claridad!<br/>',NULL,193338,1);
INSERT INTO stanza VALUES('S901','2','Disfrutando voy<br/>La vida que en el Hijo está;<br/>Futiles sueños no me cautivan ya,<br/>Un río hay en mi corazón.<br/>',NULL,193339,2);
INSERT INTO stanza VALUES('S901','3','Al volverme a Él,<br/>Su vida llenará mi ser;<br/>Su vida es en mí una realidad,<br/>¡Oh, grande es mi felicidad!<br/>',NULL,193340,3);
INSERT INTO stanza VALUES('S901','4','¡Te amo, mi Señor!<br/>Tú desvaneces otro amor;<br/>Mi vida Tú serás por la eternidad,<br/>El único eres en verdad.<br/>',NULL,193341,4);
INSERT INTO stanza VALUES('S902','1','Grande_es Jehová, y digno de ser alabado,<br/>En la ciudad de nuestro Dios,<br/>En el monte de Su santidad.<br/>Hermosa provincia, el gozo de toda la tierra,<br/>Es el monte de Sión<br/>A los lados del norte,<br/>Es el monte de Sión,<br/>La ciudad del gran Rey.<br/>A los lados del norte,<br/>Es el monte de Sión,<br/>La ciudad del gran Rey.<br/>',NULL,193342,1);
INSERT INTO stanza VALUES('S903','1','¿Qué pagaré_al Señor, qué pagaré<br/>Por todos, por todos Sus beneficios para mí?<br/>Tomaré la copa de salvación,<br/>E_invocaré, invocaré el nombre<br/>Del Señor.<br/>',NULL,193343,1);
INSERT INTO stanza VALUES('S904','1','Cuando Él hizo volver de la cautividad a Sion,<br/>Eramos como los,<br/>Como los que sueñan.<br/>',NULL,193344,1);
INSERT INTO stanza VALUES('S904','2','Nuestra boca fue llena de<br/>Risa y canto,<br/>Y decían las naciones:<br/>Grandes cosas por ellos<br/>Ha hecho Jehová.<br/>',NULL,193345,2);
INSERT INTO stanza VALUES('S904','chorus','¡Oh, grandes cosas por nosotros<br/>Ha hecho Jehová!<br/>¡Oh, grandes cosas ha hecho Él!<br/>¡Gozo sin par!<br/>',NULL,193346,3);
INSERT INTO stanza VALUES('S904','3','Haznos volver, Jehová, de nuestra cautividad<br/>Como arroyos del sur,<br/>Como arroyos del sur.<br/>',NULL,193347,4);
INSERT INTO stanza VALUES('S904','4','Los que en lágrimas siembran, con grito resonante<br/>Han de segar,<br/>Han de segar.<br/>',NULL,193348,5);
INSERT INTO stanza VALUES('S904','5','El que sale y llora<br/>Llevando semilla,<br/>Entrará jubiloso,<br/>Entrará jubiloso,<br/>Trayendo sus gavillas.<br/>',NULL,193349,6);
INSERT INTO stanza VALUES('S904','chorus','¡Oh, grandes cosas por nosotros<br/>Ha hecho Jehová!<br/>¡Oh, grandes cosas ha hecho Él!<br/>¡Gozo sin par!<br/>',NULL,193350,7);
INSERT INTO stanza VALUES('S904','6','Cuando Él hizo volver de la cautividad a Sion,<br/>Eramos como los,<br/>Como los que sueñan.<br/>',NULL,193351,8);
INSERT INTO stanza VALUES('S905','1','Moraré aquí por siempre;<br/>Reposaré,<br/>Pues a Sion he escogido,<br/>He deseado_habitar siempre en ella.<br/>Bendeciré_en grande su provisión:<br/>Saciaré a sus pobres de pan.<br/>Vestiré a sus sacerdotes;<br/>Y sus santos gritarán de gozo.<br/>',NULL,193352,1);
INSERT INTO stanza VALUES('S906','1','¡Mirad cuán bueno y delicioso es,<br/>Habitar los hermanos juntos en armonía!<br/>¡Mirad cuán bueno y delicioso es,<br/>Habitar los hermanos juntos en armonía!<br/>',NULL,193353,1);
INSERT INTO stanza VALUES('S906','chorus','Es como_el buen óleo sobre la cabeza,<br/>El cual desciende sobre<br/>La barba de_Aarón:<br/>Y baja_hasta_el borde de sus vestiduras.<br/>',NULL,193354,2);
INSERT INTO stanza VALUES('S906','2','¡Mirad cuán bueno y delicioso es,<br/>Habitar los hermanos juntos en armonía!<br/>',NULL,193355,3);
INSERT INTO stanza VALUES('S906','chorus','Es como el buen óleo sobre la cabeza,<br/>El cual desciende sobre<br/>La barba de Aarón:<br/>Y baja hasta el borde de sus vestiduras.<br/>',NULL,193356,4);
INSERT INTO stanza VALUES('S906','3','Como_el rocío de_Hermón<br/>Que desciende sobre<br/>Los montes de Sión;<br/>Porque_allí envía Jehová bendición:<br/>La vida eterna.<br/>',NULL,193357,5);
INSERT INTO stanza VALUES('S907','1','Y sacaréis con gozo aguas<br/>De fuentes de salvación,<br/>Y en aquel día diréis:<br/>¡Gloria_a Dios!<br/>',NULL,193358,1);
INSERT INTO stanza VALUES('S907','2','Y sacaréis con gozo aguas<br/>De fuentes de salvación,<br/>Y en aquel día diréis:<br/>¡Gloria_a Dios!<br/>',NULL,193359,2);
INSERT INTO stanza VALUES('S907','chorus','A Jehová clamad y exaltad<br/>Su santo Nombre,<br/>Sus obras declarad a los pueblos.<br/>Oh clama ya, tú que_habitas hoy en Sion:<br/>Porque grande es en medio de ti_el Santo de Israel.<br/>',NULL,193360,3);
INSERT INTO stanza VALUES('S908','1','Ciertamente volverán los redimidos del Señor;<br/>Volverán a Sión cantando;<br/>Eterna alegría entonces les coronará.<br/>Ciertamente volverán los redimidos del Señor;<br/>Volverán a Sión cantando;<br/>Eterna alegría entonces les coronará.<br/>',NULL,193361,1);
INSERT INTO stanza VALUES('S908','chorus','Gozo tendrán, alegría también,<br/>Y_el dolor y_el gemido huirán.<br/>',NULL,193362,2);
INSERT INTO stanza VALUES('S908','note','**Se repiten las primeras tres líneas**<br/>',NULL,193363,3);
INSERT INTO stanza VALUES('S909','1','Un mandamiento<br/>Muy nuevo os doy:<br/>Amaos unos a otros<br/>Como Yo os amé;<br/>Amaos unos a otros<br/>Como Yo os amé.<br/>En esto todos<br/>Podrán reconoceros,<br/>Que sois los discípulos Míos;<br/>En esto todos<br/>Podrán reconoceros,<br/>Si os amáis unos a otros.<br/>',NULL,193364,1);
INSERT INTO stanza VALUES('S910','1','Si_el corazón se vuelve_al Señor,<br/>El velo quitado será.<br/>Tu corazón hoy vuelve_al Señor,<br/>Y_el velo quitado será.<br/>El Señor es el Espíritu,_y<br/>Donde_está el Espíritu,<br/>¡Allí hay libertad!<br/>Si_el corazón se vuelve_al Señor,<br/>El velo quitado será.<br/>',NULL,193365,1);
INSERT INTO stanza VALUES('G2001','1','Dreieiner Gott -- Geheimnis:<br/>Sowohl eins als auch drei.<br/>Dreieiner Gott, Du bist wunderbar,<br/>Du bist wunder- wunderbar.<br/>',NULL,194607,1);
INSERT INTO stanza VALUES('G2001','2','Dreieiner Gott -- Geheimnis:<br/>Sowohl eins als auch drei.<br/>Dreieiner Gott, Du bist sagenhaft,<br/>Du bist sagen- sagenhaft.<br/>',NULL,194608,2);
INSERT INTO stanza VALUES('G2001','chorus','(Brüder)<br/>Ein Kind ist uns geborn,<br/>Ein Sohn ist uns gegeb''n --<br/>Das Kind, der starke Gott,<br/>Der Sohn und Vater eins,<br/>(Schwestern)<br/>Der starke Gott ist Er.<br/>Ewiger Vater Er.<br/>Sein Name Wunderbar.<br/>Welch wunderbar Person!<br/>',NULL,194609,3);
INSERT INTO stanza VALUES('G2001','3','Der Herr ist nun der Geist --<br/>Geheimnis wundersam.<br/>Christus, der Leben gebende Geist,<br/>In mich gekommen ist.<br/>',NULL,194610,4);
INSERT INTO stanza VALUES('G2001','4','Der Herr ist nun der Geist<br/>Oh, welche Herrlichkeit!<br/>Christus, der Leben gebende Geist,<br/>In uns gekommen ist.<br/>',NULL,194611,5);
INSERT INTO stanza VALUES('G2001','chorus','(Brüder)<br/>Der letzte Adam wurd<br/>Der Herr ist nun der Geist.<br/>Der letzte Adam wurd<br/>Christus der Herr Geist ist<br/>(Schwestern)<br/>Zum Leben gebenden Geist.<br/>Christus alles umfasst.<br/>Zum Leben gebenden Geist.<br/>Und Er wohnt nun in uns.<br/>',NULL,194612,6);
INSERT INTO stanza VALUES('G2001','5','Der Vater Gott, die Quelle,<br/>Gott, der Sohn, mich erreicht.<br/>Gott als der Geist fließt stark und frei,<br/>Er floss Gott in mein Sein.<br/>',NULL,194613,7);
INSERT INTO stanza VALUES('G2001','6','Der Vater Gott, die Quelle,<br/>Gott, der Sohn, der Flusslauf,<br/>Gott als der Geist kam in mich hinein --<br/>''s ist das größte Geheimnis.<br/>',NULL,194614,8);
INSERT INTO stanza VALUES('G2001','chorus','(Brüder)<br/>Dreieiner Gott in mir<br/>Oh, welche Herrlichkeit!<br/>Dreieiner Gott in mir<br/>Oh, dies ist wundervoll!<br/>(Schwestern)<br/>Das größt'' Geheimnis ist.<br/>Dreieiner Gott in uns.<br/>Das größt'' Geheimnis ist.<br/>Dreieiner Gott in uns.<br/>',NULL,194615,9);
INSERT INTO stanza VALUES('G2002','1','Du, Vater, bist der Lebensquell,<br/>Reich, frei, voll Göttlichkeit!<br/>Aus Dir so rein das Leben quillt<br/>In alle Ewigkeit!<br/>',NULL,194616,1);
INSERT INTO stanza VALUES('G2002','2','In Deiner Lieb strömst Du im Sohn<br/>Zur ganzen Menschheit hin;<br/>Als Geist fließt Du nun auch in uns,<br/>Welch Gnade liegt darin!<br/>',NULL,194617,2);
INSERT INTO stanza VALUES('G2002','3','Obwohl in Bosheit und in Sünd<br/>Von Dir wir waren fern,<br/>Hast Du uns doch im Sohn erlöst,<br/>Gabst uns Dein Leben gern.<br/>',NULL,194618,3);
INSERT INTO stanza VALUES('G2002','4','Obwohl wir Dich missachteten,<br/>Betrübten Deinen Geist,<br/>Kommst Du doch als der Geist zu uns,<br/>Mit Leben uns reich speist.<br/>',NULL,194619,4);
INSERT INTO stanza VALUES('G2002','5','Du als der Geist hast Dich im Sohn<br/>Mit uns vermengt, o Herr;<br/>Willst durch Gemeinschaft salben uns,<br/>Und wachsen täglich mehr.<br/>',NULL,194620,5);
INSERT INTO stanza VALUES('G2002','6','Die Liebe Gottes, Christi Gnad<br/>Im Geist fließn allezeit;<br/>Er teilt uns Gottes Reichtum aus<br/>In alle Ewigkeit.<br/>',NULL,194621,6);
INSERT INTO stanza VALUES('G2002','7','Der Vater, Sohn und Geist -- dreieins,<br/>Versorg''n uns innerlich;<br/>Von Deiner Liebe singen wir,<br/>Verehrn Dich ewiglich.<br/>',NULL,194622,7);
INSERT INTO stanza VALUES('G2003','1','O Vater, Du bist immergrün<br/>Und Du bist immer neu;<br/>Du bist der Herr, der ewig lebt,<br/>So frisch wie Morgentau.<br/>',NULL,194623,1);
INSERT INTO stanza VALUES('G2003','chorus','Du, Vater, änderst Dich niemals,<br/>Und Du wirst niemals alt;<br/>Durch alle Zeiten immer frisch<br/>Stets Deine Neuheit strahlt.<br/>',NULL,194624,2);
INSERT INTO stanza VALUES('G2003','2','Nur Du bist „neu" und ohne Dich<br/>Ist alles alt, verfahrn;<br/>Jedoch mit Dir bleibt alles frisch<br/>Nach noch so vielen Jahrn.<br/>',NULL,194625,3);
INSERT INTO stanza VALUES('G2003','3','Ein jeder Segen, den Du gibst,<br/>Birgt Deine Neuheit -- Dich;<br/>Neu Deine Wege, neu Dein Bund,<br/>Sie bleiben ewiglich.<br/>',NULL,194626,4);
INSERT INTO stanza VALUES('G2003','4','Wir sind die neue Schöpfung jetzt,<br/>Denn neu sind Herz und Geist;<br/>Doch täglich Du erneuerst uns,<br/>Mit neuem Leben speist.<br/>',NULL,194627,5);
INSERT INTO stanza VALUES('G2003','5','Die Erde, Himmel und die Stadt,<br/>Sie werden alle neu;<br/>In jedem Monat neue Frucht<br/>Der Lebensbaum bringt treu.<br/>',NULL,194628,6);
INSERT INTO stanza VALUES('G2003','6','O Vater, ewig neu bist Du,<br/>In Dir ist alles neu;<br/>Und ewig neu ist unser Lied,<br/>Wir bringen''s Dir stets treu.<br/>',NULL,194629,7);
INSERT INTO stanza VALUES('G2004','1','Abba Vater, hör den Schrei<br/>Vom vermengten Geist in uns!<br/>Abba, Vater,<br/>Abba, Vater.<br/>',NULL,194630,1);
INSERT INTO stanza VALUES('G2004','2','Danke, Vater, Du sandtest Ihn,<br/>Den Geist von Deinem Sohn, der ruft tief drin.<br/>',NULL,194631,2);
INSERT INTO stanza VALUES('G2004','3','Oh, wie süß klingt Abbas Nam''<br/>Von unsrem Geist durch unser Herz.<br/>',NULL,194632,3);
INSERT INTO stanza VALUES('G2004','4','Jederzeit macht dieser Schrei<br/>Uns mit Deinem Geliebten eins.<br/>',NULL,194633,4);
INSERT INTO stanza VALUES('G2004','5','Durch das Rufen kommen wir<br/>In Deinem Sohn zurück zu Dir.<br/>',NULL,194634,5);
INSERT INTO stanza VALUES('G2004','6','Nun wir bleiben in Deinem Schoß,<br/>Hier lässt uns Dein Sohn nicht los.<br/>',NULL,194635,6);
INSERT INTO stanza VALUES('G2005','1','Dem Vater sei Ehre, der Großes getan,<br/>Er liebte die Welt, nahm der Sünder Sich an,<br/>Er gab Seinen Sohn, der Erlösung vollbracht,<br/>Hat allen das Lebenstor weit aufgemacht.<br/>',NULL,194636,1);
INSERT INTO stanza VALUES('G2005','chorus','Preist den Herrn, preist den Herrn,<br/>Erde hör diesen Schall!<br/>Preist den Herrn, preist den Herrn,<br/>Völker, preist überall!<br/>Oh, kommt zu dem Vater! In Jesus wir nahn.<br/>Gebt Ihm alle Ehre, der Großes getan!<br/>',NULL,194637,2);
INSERT INTO stanza VALUES('G2005','2','Vollkomm''ne Erlösung, erkauft durch Sein Blut,<br/>Wer glaubt, dem kommt Gottes Verheißung zugut.<br/>Der ärgste der Sünder, der glaubt, Ihm anhängt,<br/>Sofort die Vergebung von Jesus empfängt.<br/>',NULL,194638,3);
INSERT INTO stanza VALUES('G2005','3','Gelehrt hat Er Großes und Großes getan,<br/>In Jesus, dem Sohn, wahre Freude begann.<br/>Doch reiner und höher und größer wird sein<br/>Die Freude, Entzückung, wenn Jesus erscheint.<br/>',NULL,194639,4);
INSERT INTO stanza VALUES('G2006','1','O Gott, Preis sei Dir<br/>Für den Sohn Deiner Lieb,<br/>Für den Retter, der starb,<br/>Der im Himmel jetzt ist.<br/>',NULL,194640,1);
INSERT INTO stanza VALUES('G2006','chorus','Halleluja, Dir sei Ehre,<br/>Halleluja! Amen.<br/>Halleluja! Dir sei Ehre,<br/>Gott Vater, Amen.<br/>',NULL,194641,2);
INSERT INTO stanza VALUES('G2006','2','O Gott, preis sei Dir<br/>Für den Geist ew''gen Lichts,<br/>Der uns zeigte den Retter,<br/>Die Nacht macht zunicht.<br/>',NULL,194642,3);
INSERT INTO stanza VALUES('G2006','3','Die Ehre sei Dir,<br/>Dass Du, Vater, uns liebst,<br/>Denn durch Jesu Erlösung<br/>Du Leben uns gibst.<br/>',NULL,194643,4);
INSERT INTO stanza VALUES('G2006','4','Wir preisen Dich neu,<br/>Voller Liebe sind wir,<br/>Jedes Herz ist entzündet<br/>Mit Feuer von Dir.<br/>',NULL,194644,5);
INSERT INTO stanza VALUES('G2007','1','Christus -- ein echter Mensch,<br/>Vollkommen und so fein ist Er.<br/>Gehorsam, dienend, kein Anschein des Bösen,<br/>Die edelste Persönlichkeit.<br/>Göttlichkeit in Menschlichkeit zum Ausdruck kam.<br/>(Wiederholen)<br/>Christus -- das Vorbild unseres Lebens,<br/>Mit Seinem Leben füllt Er uns.<br/>Christus -- das Vorbild unseres Lebens,<br/>Die ausgewogene Menschlichkeit von Jesus!<br/>',NULL,194645,1);
INSERT INTO stanza VALUES('G2008','1','Wie süß Dein Name ist,<br/>Jesus, mein Herr!<br/>Gnade sich reich ergießt,<br/>Jesus, mein Herr!<br/>Fröhlich ich jubilier,<br/>Denn Du wohnst jetzt in mir,<br/>Alles hab ich in Dir,<br/>Jesus, mein Herr!<br/>',NULL,194646,1);
INSERT INTO stanza VALUES('G2008','2','Dein Leben, Menschensohn,<br/>Jesus, mein Herr!<br/>Gabst hin samt Deinem Thron,<br/>Jesus, mein Herr!<br/>Groß Deine Liebe ist,<br/>Keine sonst reicher fließt,<br/>Uns wie ein Band umschließt,<br/>Jesus, mein Herr!<br/>',NULL,194647,2);
INSERT INTO stanza VALUES('G2008','3','Allein gerecht in Dir,<br/>Jesus, mein Herr!<br/>Zuflucht gewährst Du mir,<br/>Jesus, mein Herr!<br/>Nichts fürcht ich, Du bist nah<br/>Und immer für mich da,<br/>Mein Tröster wunderbar,<br/>Jesus, mein Herr!<br/>',NULL,194648,3);
INSERT INTO stanza VALUES('G2008','4','Du kommst schon bald zurück,<br/>Jesus, mein Herr!<br/>Welch Freude! Welch ein Glück!<br/>Jesus, mein Herr!<br/>Ich schau Dein Angesicht,<br/>So werd ich wie Du bist,<br/>Bleib bei Dir ewiglich,<br/>Jesus, mein Herr!<br/>',NULL,194649,4);
INSERT INTO stanza VALUES('G2009','1','Wie süß der Name Jesu klingt<br/>Im Ohr, von dem, der glaubt!<br/>Heilt seine Wunden, Ängste nimmt,<br/>Und ihm die Sorgen raubt.<br/>Und ihm die Sorgen raubt.<br/>Und ihm die Sorgen raubt.<br/>Heilt seine Wunden, Ängste nimmt,<br/>Und ihm die Sorgen raubt.<br/>',NULL,194650,1);
INSERT INTO stanza VALUES('G2009','2','Er tröstet den verzagten Geist,<br/>Bringt schweren Herzen Ruh;<br/>Macht Seelen satt, die hungrig sind,<br/>Mit Manna immerzu.<br/>',NULL,194651,2);
INSERT INTO stanza VALUES('G2009','3','O Name! Fels, auf den wir baun,<br/>Uns Schild und Schutz zugleich;<br/>Welch wunderbarer Schatz bist Du,<br/>Mit Gnaden-Vorrat reich!<br/>',NULL,194652,3);
INSERT INTO stanza VALUES('G2009','4','Du, Jesus, Retter, Hirte, Freund<br/>Und Priester, König bist;<br/>Herr, unser Leben, Weg und Ziel,<br/>In Dir die Fülle ist.<br/>',NULL,194653,4);
INSERT INTO stanza VALUES('G2009','5','Wie schwach ist unsre Herzensmüh!<br/>Das wärmste Lob so kalt;<br/>Doch bald, wenn wir Dich sehen, Herr,<br/>Der Preis kraftvoll erschallt.<br/>',NULL,194654,5);
INSERT INTO stanza VALUES('G2009','6','Bis dann mit jedem Atemzug<br/>Von Seiner Liebe singt!<br/>Den Namen Jesus rühmen wir,<br/>Der Todesmacht bezwingt.<br/>(Die letzten beiden Zeilen jeder Strophe wiederholen.)<br/>',NULL,194655,6);
INSERT INTO stanza VALUES('G2010','1','Ich liebe einen Namen sehr,<br/>Wie kostbar ist er mir!<br/>In meinem Ohr so süß klingt er,<br/>Der schönste Name hier.<br/>',NULL,194656,1);
INSERT INTO stanza VALUES('G2010','chorus','Oh, ich liebe Jesus,<br/>Oh, ich liebe Jesus,<br/>Oh, ich liebe Jesus,<br/>Denn Er liebt'' mich zuerst!<br/>',NULL,194657,2);
INSERT INTO stanza VALUES('G2010','2','Von Retter-Liebe spricht Er mir,<br/>Er starb, macht frei und rein;<br/>Sein Name spricht vom kostbarn Blut,<br/>Für Sünder steht es ein.<br/>',NULL,194658,3);
INSERT INTO stanza VALUES('G2010','3','Er sagt mir, was der Vater mir<br/>Hat täglich zugedacht;<br/>Befind ich mich auf finstrem Pfad,<br/>Mir doch die Sonne lacht.<br/>',NULL,194659,4);
INSERT INTO stanza VALUES('G2010','4','Dein Name zeigt Dein liebend Herz<br/>In Schwachheit fühlt es mit,<br/>Mich trägt in Sorgen und in Schmerz,<br/>Wenn es sonst keinen gibt.<br/>',NULL,194660,5);
INSERT INTO stanza VALUES('G2011','1','Teurer mächt''ger Name Jesu!<br/>Gern in ihn hinein ich flieh;<br/>Er steht über allen Namen,<br/>Denn Dein Name bringt den Sieg.<br/>',NULL,194661,1);
INSERT INTO stanza VALUES('G2011','2','Liebster Jesus! Starker Retter!<br/>Alles schenkt Dein Name mir;<br/>Wenn ich Deinen Namen atme,<br/>Trink ich Leben reich von Dir.<br/>',NULL,194662,2);
INSERT INTO stanza VALUES('G2011','3','Von der Kraft des Namens Jesus<br/>Spricht das Universum klar,<br/>Doch nur Sünder, die erlöst sind,<br/>Spüren Seinen Trost fürwahr.<br/>',NULL,194663,3);
INSERT INTO stanza VALUES('G2011','4','Jesus! Jesus! Schönster Name --<br/>Balsam hier in Not und Leid;<br/>Wir siegen in Deinem Namen,<br/>Bis Du kommst in Herrlichkeit.<br/>',NULL,194664,4);
INSERT INTO stanza VALUES('G2012','1','Oh, wie ist der Herr uns nahe, rufen wir Ihn an!<br/>Seine Gegenwart uns stärkt und zieht uns neu voran.<br/>Jesus lässt Sich finden. Wenn du rufst, ist Er gleich da --<br/>Oh, welch ein Trost für unser Herz zu wissen: Er ist nah!<br/>Jesus! Oh, welch ein Nam!<br/>',NULL,194665,1);
INSERT INTO stanza VALUES('G2012','chorus','O Herr Jesus! Wie Leben fließt!<br/>Name siegreich und so glorreich,<br/>Er den höchsten Namen genießt!<br/>Jesus! Name voll Kraft!<br/>O Herr Jesus! Trost uns verschafft!<br/>Atmet ihn doch ein, ruft tagaus, tagein,<br/>O Herr Jesus! Oh, welch ein Nam!<br/>',NULL,194666,2);
INSERT INTO stanza VALUES('G2012','2','Ruf den Namen Jesus an, Er macht dich völlig frei,<br/>O Herr Jesus, Halleluja, Knechtschaft ist vorbei!<br/>Trink den Kelch der Rettung, dass Er dich beleben kann;<br/>Uns von so vielem rettet Er, wenn wir Ihn rufen an.<br/>',NULL,194667,3);
INSERT INTO stanza VALUES('G2012','3','Für den Herrn sind Juden, Griechen, alle Menschen gleich;<br/>Und wer Seinen Namen ruft, für den ist Er so reich.<br/>O Herr Jesus! Freudig ruf ich Dich und Leben fließt;<br/>Ich atme Deinen Namen ein, der süß und lieblich ist.<br/>',NULL,194668,4);
INSERT INTO stanza VALUES('G2012','4','Über unsren Retter-Gott erfreuen wir uns sehr.<br/>Ob in Wonne, ob in Kummer, rufen wir: „O Herr!"<br/>Seinen Namen ruf ich an, solang ich leben werd.<br/>Sein Ohr hat Er mir zugeneigt, gibt Gnade mir vermehrt.<br/>',NULL,194669,5);
INSERT INTO stanza VALUES('G2012','5','Ja, den Herrn wir rufen an und geben Ihm die Ehr,<br/>Dankbar und aus ganzem Herzen preisen wir Ihn sehr.<br/>Ruft mit allen Heiligen Ihn an an jedem Ort,<br/>Aus reinem Herzen rufen wir und Gnade fließt sofort.<br/>',NULL,194670,6);
INSERT INTO stanza VALUES('G2013','1','Seinen Namen lieben wir,<br/>Den Namen Jesus!<br/>In dem Himmel, auf der Erd<br/>Kommt ihm gar nichts gleich.<br/>Atmen wir den Namen ein,<br/>Kann Tod und Finsternis nicht sein;<br/>Rufen wir, kommt die Person des Namens her!<br/>',NULL,194671,1);
INSERT INTO stanza VALUES('G2013','2','Deinen Namen, liebster Herr,<br/>Voll Freude bekennen wir<br/>Zu der Herrlichkeit des Vaters nun fortan.<br/>Dich zu preisen für uns ist,<br/>Täglich Genuss, wie süß Du bist!<br/>Herr, wir lieben Dich und rufen Dich nun an!<br/>',NULL,194672,2);
INSERT INTO stanza VALUES('G2014','1','Nieder zu Erden,<br/>Um ein Mensch zu werden,<br/>Mein Gott und Retter kam<br/>Und Jesus war Sein Nam.<br/>Geborn verachtet,<br/>Fremd und unbeachtet,<br/>Ein Mann der Schmerzen, Tränen und der Qual.<br/>',NULL,194673,1);
INSERT INTO stanza VALUES('G2014','chorus','Wie ich Ihn liebe! Wie ich Ihn schätze!<br/>Mein Licht, mein Atem ist Er allein!<br/>Der große Schöpfer ist mein Erlöser,<br/>Und Gottes Fülle wohnt ganz in Ihm!<br/>',NULL,194674,2);
INSERT INTO stanza VALUES('G2014','2','Auf welchen Wegen<br/>Kam uns Gott entgegen!<br/>Hat in der Todesnacht<br/>Uns Hoffnungslicht gebracht.<br/>Der Allerhöchste<br/>Sich vom Glanz loslöste,<br/>Sich beugt, umwirbt mich, meine Seele heilt.<br/>',NULL,194675,3);
INSERT INTO stanza VALUES('G2014','3','Ohne zu klagen,<br/>Fleisch und Blut getragen,<br/>Zog Er das Menschsein an,<br/>Enthüllte Gottes Plan.<br/>Wer kann''s erfassen?<br/>Selbst von Gott verlassen;<br/>Nun weiß ich, Du bist''s, welcher heißt: „ICH BIN".<br/>',NULL,194676,4);
INSERT INTO stanza VALUES('G2015','1','Hört! Es singt das Engelsheer:<br/>„Dem gebornen König Ehr;<br/>Friede nun die Erde krönt,<br/>Gott und Sünder sind versöhnt."<br/>Alle Völker, steht nun auf,<br/>Singt den Himmelssieg zuhauf!<br/>Laut verkünd''t mit Engelchörn:<br/>„Christ -- geborn in Bethlehem."<br/>//Laut verkünd''t mit Engelchörn:<br/>„Christ -- geborn in Bethlehem."//<br/>',NULL,194677,1);
INSERT INTO stanza VALUES('G2015','2','Christus, ewig unsrem Herrn,<br/>Bringen stets die Himmel Ehrn.<br/>Siehe! Der uns Rettung bringt,<br/>Einer Jungfrau Schoß entspringt.<br/>Gottheit in des Fleisches Kleid<br/>Wohnt bei uns in Raum und Zeit!<br/>//Mensch bei Menschen, Ihm gefällt;<br/>Jesus ist Immanuel.//<br/>',NULL,194678,2);
INSERT INTO stanza VALUES('G2015','3','Friedefürst gebenedeit!<br/>Sonne der Gerechtigkeit!<br/>Licht und Leben bringt Er bei,<br/>Seine Flügel voller Heil.<br/>Herrlichkeit sanft gibt Er her,<br/>Dass der Mensch nicht sterbe mehr,<br/>//Weckt die Söhne dieser Erd,<br/>Auf dass Er sie neu gebärt.//<br/>',NULL,194679,3);
INSERT INTO stanza VALUES('G2015','4','Komm, Begehr der Völker, komm!<br/>Nun in uns in Demut wohn!<br/>Steh auf, Same von der Frau,<br/>Schlangenkopf in uns zerhau!<br/>Adams Gleichheit tilge ganz,<br/>An die Stelle Dein Bild stanz!<br/>//Letzter Adam stell uns her,<br/>Tu''s in Deiner Liebe, Herr!//<br/>',NULL,194680,4);
INSERT INTO stanza VALUES('G2016','1','Ich möchte Gott preisen ewiglich,<br/>Weil Er mein Alles ist.<br/>Er wohnt in meinem Geist.<br/>Sein Leben fließt dort frei.<br/>Ich möchte Gott preisen ewiglich,<br/>Weil Er tief in mir wohnt,<br/>Und Er verlässt mich nicht.<br/>',NULL,194681,1);
INSERT INTO stanza VALUES('G2016','chorus','Jetzt essen wir mit unserem Geist,<br/>Jesus Christus unsre Speis.<br/>Ruf Sein'' Namen an und Er wird Wirklichkeit!<br/>Öffne deinen Mund, lass Ihn herein!<br/>O, wie reich wird Er dir sein.<br/>Allumfassende Versorgung ist der Herr.<br/>',NULL,194682,2);
INSERT INTO stanza VALUES('G2016','2','Jetzt lebe ich durch den Lebensbaum.<br/>Sein'' Frucht nährt meinen Geist,<br/>O, wie sehr sie mich speist.<br/>Ich leb in Ewigkeit.<br/>Jetzt lebe ich durch den Lebensbaum.<br/>Ich wend ihn täglich an.<br/>Er mich versorgen kann.<br/>',NULL,194683,3);
INSERT INTO stanza VALUES('G2016','3','Es fließt nun ein Lebensstrom in mir,<br/>Voll Leben fließt er frei --<br/>Ununterbrochen sei!<br/>Er überflutet mich.<br/>Es fließt nun ein Lebensstrom in mir<br/>Und täglich füllt er mich --<br/>Sein Name Jesus ist!<br/>',NULL,194684,4);
INSERT INTO stanza VALUES('G2017','1','Er trat aus der Herrlichkeit<br/>Und Niedrigkeit anzog.<br/>Der Ursprung des Lebens<br/>Ward Selbst ein Geschöpf,<br/>Verachtet, verlassen,<br/>War ein Mann der Schmerzen.<br/>Er kam aus den Himmeln<br/>Und trug unsre Schand.<br/>',NULL,194685,1);
INSERT INTO stanza VALUES('G2017','2','Er wählte die Demut,<br/>Er wählte Beschränkung,<br/>Er wählte die Endlichkeit.<br/>Er wurde ein Mensch.<br/>Sein ewiger Vorsatz<br/>Substanz fand in Jesus --<br/>Ein zweifältig Wesen<br/>Der erste Gott-Mensch.<br/>',NULL,194686,2);
INSERT INTO stanza VALUES('G2017','3','Die Schale -- zerbrochen,<br/>So Herrlichkeit freigab.<br/>Diese Lebens-Vermittlung<br/>Viel Körner ergab.<br/>Es jubelt der Erstgeborn<br/>Mit all Seinen Brüdern.<br/>In der Einverleibung<br/>Sind Gott und Mensch eins!<br/>',NULL,194687,3);
INSERT INTO stanza VALUES('G2017','4','Was sonst, als Ihn lieben!<br/>Den liebsten Vorläufer!<br/>Sein'' Schand'' unser Sieg ist,<br/>Seine Qual unsre Freud.<br/>Uns, Söhne der Strafe,<br/>Zur Herrlichkeit brachte.<br/>Millionen Gott-Menschen<br/>Auf ewig sich freun!<br/>',NULL,194688,4);
INSERT INTO stanza VALUES('G2018','1','Wie wunderbar Erlösung ist,<br/>Mein liebster Herr, in Dir!<br/>Noch nie gesehn, gehört, erkannt,<br/>Was Du vermacht hast mir!<br/>Bist göttlich und geheimnisvoll,<br/>Weit mehr als was ich weiß!<br/>Erlösung ist so wunderbar,<br/>Weit mehr als mein Lobpreis!<br/>',NULL,194689,1);
INSERT INTO stanza VALUES('G2018','2','Durchbohrt für uns am Kreuz warst Du.<br/>Dort Blut und Wasser floss,<br/>Dass Gottes Leben zu uns kommt<br/>Durch die Erlösung groß!<br/>Wir sind gereinigt durch Dein Blut,<br/>Nun nimmt uns Gott gern an;<br/>Dein Leben hat uns neu geborn,<br/>Uns nichts mehr trennen kann.<br/>',NULL,194690,2);
INSERT INTO stanza VALUES('G2018','3','Das Weizenkorn bist Du, das starb,<br/>Die vielen Körner -- wir,<br/>Vermengt, geformt sind wir, Dein Leib,<br/>Mit der Natur von Dir.<br/>Dein Zuwachs sind wir, liebster Herr,<br/>Du unser Inhalt bist;<br/>Durch uns lebst Du und gehst voran,<br/>Dein Wesen sichtbar ist.<br/>',NULL,194691,3);
INSERT INTO stanza VALUES('G2018','4','Weil wir Dein Leib sind, richte Dich<br/>In unsern Herzen ein;<br/>In uns mach Deine Wohnung nun,<br/>Du sollst Zuhause sein.<br/>Dein Gegenüber sind wir, Herr,<br/>Dein Herz voll Freude ist,<br/>Im einen Leib, mit Dir vereint,<br/>Genießen, was Du bist.<br/>',NULL,194692,4);
INSERT INTO stanza VALUES('G2018','5','An Dich erinnern wir uns jetzt,<br/>Wenn wir die Zeichen sehn,<br/>Erlösung ist so wunderbar,<br/>Lobpreise Dir zustehn.<br/>Wir sind zu Deinem Leib gemacht,<br/>Zur Wohnung aufgebaut;<br/>Wir bringen Dir Anbetung dar<br/>Und lieben Dich als Braut.<br/>',NULL,194693,5);
INSERT INTO stanza VALUES('G2019','1','Gefallen -- so fangen wir alle an.<br/>Vom bösen Schicksal wurden wir gefang''n.<br/>Aus dieser Welt der Sünde -- wie wird man befreit?<br/>',NULL,194694,1);
INSERT INTO stanza VALUES('G2019','chorus','Indem wir rufen: „Jesus, Jesus, Jesus!"<br/>Jeden Tag und Moment<br/>Rufen wir den Namen Jesus --<br/>Froh wer den Weg erkennt.<br/>''s ist Jesus! Herr Jesus!<br/>',NULL,194695,2);
INSERT INTO stanza VALUES('G2019','2','Auch wenn wir den Herrn doch lieben sehr,<br/>Fällt uns, Ihn zu kontaktier''n, oft schwer.<br/>Wie nur, wie kommen wir, liebster Herr, da raus?<br/>',NULL,194696,3);
INSERT INTO stanza VALUES('G2019','3','Wir wissen, manchmal sind wir echt verstellt<br/>Und manchmal leben wir, wie''s uns gefällt.<br/>Gibt es einen Weg, wie wir das Selbst bezwing''n?<br/>',NULL,194697,4);
INSERT INTO stanza VALUES('G2019','4','Christen, auf der ganzen Welt zerstreut,<br/>Suchen nach der Braut, die Dich erfreut.<br/>Wie könn''n alle neu Gebor''nen heut eins sein?<br/>',NULL,194698,5);
INSERT INTO stanza VALUES('G2019','5','Rufen hat die Christen stets entzückt.<br/>Rufen bringt den Bräutigam zurück.<br/>Wie erleben wir ein solches Glück schon jetzt?<br/>',NULL,194699,6);
INSERT INTO stanza VALUES('G2020','1','Preist den Sieger, Jesus Christus!<br/>Wunderbar Sein Sieg geschah!<br/>Wir sind frei von Sünd und Adam,<br/>Die Erlösung ist nun da!<br/>Er bezwang die bösen Mächte<br/>Durch das Kreuz von Golgatha.<br/>',NULL,194700,1);
INSERT INTO stanza VALUES('G2020','2','Preist Ihn! Er ist auferstanden!<br/>Aus den Toten rief Gott Ihn!<br/>Er verschlang die Todesmächte,<br/>Führt vom Tod zum Leben hin!<br/>Dunkelheit und Tod durchbrach Er,<br/>Seine Kraft sehn wir darin!<br/>',NULL,194701,2);
INSERT INTO stanza VALUES('G2020','3','Preist Ihn! Er ist aufgefahren!<br/>Gott erhob Ihn auf den Thron!<br/>Über alle Macht und Herrschaft,<br/>Höchster Name ist Sein Lohn!<br/>Vollmacht wurde Ihm gegeben,<br/>Bis der Feind gejagt davon!<br/>',NULL,194702,3);
INSERT INTO stanza VALUES('G2020','4','Halleluja, Er ist Sieger!<br/>Gott hat Ihn vom Tod befreit!<br/>Halleluja, auferstanden,<br/>Triumphiert in Herrlichkeit!<br/>Halleluja, aufgefahren,<br/>Nun herrscht Er in Ewigkeit!<br/>',NULL,194703,4);
INSERT INTO stanza VALUES('G2021','1','Dem Herrn gebührt die Ehre,<br/>Wenn die Gemeinde singt;<br/>Die Engelheere lauschen,<br/>Wenn unser Lob erklingt.<br/>Den Herrn wir froh erhöhen,<br/>Die Welt es hören mag;<br/>Die Heere Satans fliehen<br/>Vor unsrem Siegesstab.<br/>',NULL,194704,1);
INSERT INTO stanza VALUES('G2021','2','Wenn unsre Lippen schweigen,<br/>Freut sich der Feind so sehr;<br/>Warum nicht offen kämpfen?<br/>Verjagt ihn, singt noch mehr!<br/>Erbringen wir „Lobopfer",<br/>Der Siegesschrei ergellt --<br/>Verliern wir das Gesicht nur,<br/>Sind Toren vor der Welt!<br/>',NULL,194705,2);
INSERT INTO stanza VALUES('G2021','3','Die Welt wird uns nie helfen,<br/>Den Retter niemals preist,<br/>Wird Ihn auch niemals ehren,<br/>Ihm keinen Dank erweist;<br/>So brauchen wir Erlaubnis?<br/>Den Aufgefahrnen preist!<br/>Seid kühn, den Geist befreit nun!<br/>Viel Gnade Er erweist!<br/>',NULL,194706,3);
INSERT INTO stanza VALUES('G2021','4','Ihr Brüder sollt nicht still sein!<br/>Ihr Schwestern freudig singt!<br/>Damit die Siegeskunde<br/>Doch weit und breit erklingt.<br/>Zu jedem Preis den Herrn lobt,<br/>Ja, jauchzt zu jeder Zeit!<br/>Rühmt Seine volle Rettung<br/>Und die Barmherzigkeit!<br/>',NULL,194707,4);
INSERT INTO stanza VALUES('G2022','1','Die Gemeinde froh verkündet:<br/>Jesus ist Herr!<br/>Sie ist auf den Herrn gegründet:<br/>Jesus ist Herr!<br/>Jesus hat Sein Werk verrichtet,<br/>Satan und sein Heer vernichtet,<br/>Und Sein Thron ist aufgerichtet,<br/>Jesus ist Herr!<br/>',NULL,194708,1);
INSERT INTO stanza VALUES('G2022','2','Jesus ist der Geist schon heute,<br/>Jesus ist Herr!<br/>Er ist hier! Hört zu, ihr Leute:<br/>Jesus ist Herr!<br/>Klag nicht! Er wird dich erretten.<br/>Ruft Ihn an, Er wird eintreten!<br/>Ja, wir wollen Ihn anbeten --<br/>Jesus ist Herr!<br/>',NULL,194709,2);
INSERT INTO stanza VALUES('G2022','3','Er wird dich vollauf umwandeln,<br/>Jesus ist Herr!<br/>Reich versorgt in allem Handeln,<br/>Jesus ist Herr!<br/>Er wird euch den Frieden geben,<br/>Und versorgt euch reich mit Leben,<br/>Wird euch ganz mit Gott verweben,<br/>Jesus ist Herr!<br/>',NULL,194710,3);
INSERT INTO stanza VALUES('G2022','4','Er empfing uns voll Erbarmen,<br/>Jesus ist Herr!<br/>Hält uns fest in Seinen Armen,<br/>Jesus ist Herr!<br/>Seine ganze Fülle sehen<br/>Wir in Seinem Leibe stehen,<br/>Satan und sein Werk vergehen --<br/>Jesus ist Herr!<br/>',NULL,194711,4);
INSERT INTO stanza VALUES('G2023','1','Sieh! Im Himmel sitzt nun Jesus,<br/>Christus thront dort allezeit;<br/>Als ein Mensch von Gott erhoben<br/>Und gekrönt mit Herrlichkeit.<br/>',NULL,194712,1);
INSERT INTO stanza VALUES('G2023','2','Er zog die Natur des Mensch'' an,<br/>Starb für uns nach Gottes Plan,<br/>Ist im Leib auch auferstanden,<br/>Fuhr als Mensch zu Gott auf dann.<br/>',NULL,194713,2);
INSERT INTO stanza VALUES('G2023','3','Gott hat Sich in Ihm erniedrigt,<br/>Blut teilhaftig, Mensch auch war;<br/>Nun der Mensch in Ihm erhöht ist<br/>Und mit Gott versöhnt fürwahr.<br/>',NULL,194714,3);
INSERT INTO stanza VALUES('G2023','4','Gott und Mensch in Ihm vermengt sind,<br/>Gott im Mensch'' wird klar bezeugt,<br/>Mensch und Gott in Ihm vermengt sind,<br/>Mensch in Gott verherrlicht ist.<br/>',NULL,194715,4);
INSERT INTO stanza VALUES('G2023','5','Vom Verherrlichten im Himmel<br/>Kam der allumfassende Geist;<br/>Jesu Werk und auch Sein Wesen<br/>Uns der Geist stets unterweist.<br/>',NULL,194716,5);
INSERT INTO stanza VALUES('G2023','6','Eins mit Ihm im Himmel ist nun<br/>Die Gemeinde, Seine Braut;<br/>Durch den kostbarn Geist von Jesus<br/>Sind die Glieder aufgebaut.<br/>',NULL,194717,6);
INSERT INTO stanza VALUES('G2023','7','Sieh! Ein Mensch jetzt in den Himmeln<br/>Sitzt als Höchster auf dem Thron;<br/>Jesus Christus, unser Retter,<br/>Herrlichkeit ist Seine Kron.<br/>',NULL,194718,7);
INSERT INTO stanza VALUES('G2024','1','O Jesus, wunderbarer Herr Jesus,<br/>Du auf dem Thron im Himmel sitzt.<br/>Gekrönt mit Herrlichkeit und Ehre<br/>Ziehst uns durch Deine Liebe an.<br/>',NULL,194719,1);
INSERT INTO stanza VALUES('G2024','chorus','O Jesus, Jesus, lieblichster Jesus,<br/>O Jesus, Jesus, liebster Herr,<br/>Dein'' Schönheit nahm uns all'' gefangen,<br/>Wir lieben Dich, kostbarer Herr.<br/>',NULL,194720,2);
INSERT INTO stanza VALUES('G2024','2','Die Herrlichkeit ist Dein heller Glanz,<br/>Bezogen auf Deine Person.<br/>Und Ehre ist die Kostbarkeit,<br/>Die Deinen großen Wert betrifft.<br/>',NULL,194721,3);
INSERT INTO stanza VALUES('G2024','3','Herr, Du bist der größte Anziehungspunkt<br/>Im ganzen Universum hier.<br/>Wie ein gewaltiger Magnet<br/>Ziehst Du die Suchenden zu Dir.<br/>',NULL,194722,4);
INSERT INTO stanza VALUES('G2024','4','Gäb''s Dich, Du anziehende Person, nicht<br/>Wie könnten wir von allem wegschaun?<br/>Wie könnten wir von aller Ablenkung<br/>Auf dieser Erde wegschauen?<br/>',NULL,194723,5);
INSERT INTO stanza VALUES('G2025','1','Erkenntnis fasst, Herr, Deine Liebe nicht,<br/>Mein Retter Jesus, dennoch schenk mir Sicht!<br/>Lass Deine Liebe -- die so lang und breit,<br/>So hoch, so tief, so stark ist allezeit --<br/>Mich sehn noch mehr!<br/>',NULL,194724,1);
INSERT INTO stanza VALUES('G2025','2','Berichte fassen Deine Liebe nicht,<br/>Mein Retter Jesus; dennoch ich bericht<br/>Den Sündern nah und fern, dass Er vergab<br/>Und Seine Liebe Sündenfurcht wäscht ab<br/>Und Liebe zeugt.<br/>',NULL,194725,2);
INSERT INTO stanza VALUES('G2025','3','Mein Preisen fasst, Herr, Deine Liebe nicht,<br/>Mein Retter Jesus, doch mein Herz nun spricht<br/>Von Deiner großen Liebe und davon,<br/>Wie sie mich, Sünder, voller Rebellion,<br/>Bringt nah zu Gott.<br/>',NULL,194726,3);
INSERT INTO stanza VALUES('G2025','4','Wenn ich nicht singen, kennen, reden kann<br/>Von Deiner Liebe, jedoch fang ich an;<br/>Frei bring ich mein Gefäß, so leer, zu Dir;<br/>Als Quell der Liebe fließe frei zu mir,<br/>Füll mein Gefäß!<br/>',NULL,194727,4);
INSERT INTO stanza VALUES('G2025','5','Leer bin ich, habe nie an Dich gedacht<br/>Noch einen Blick der Liebe Dir gebracht;<br/>Doch immer wieder komme ich zu Dir,<br/>Ja, dieses Recht zu kommen gibst Du mir,<br/>Weil Du mich liebst.<br/>',NULL,194728,5);
INSERT INTO stanza VALUES('G2025','6','Mit Deiner Liebe, Retter, füll mein Sein!<br/>Als Lebensquelle nimm mein Herz ganz ein!<br/>Im Glauben will ich mich Dir nahen schlicht,<br/>Zu einer andern Quelle flieh ich nicht,<br/>Als nur zu Dir.<br/>',NULL,194729,6);
INSERT INTO stanza VALUES('G2025','7','Herr Jesus, sehe ich Dein Angesicht,<br/>Wenn auf dem hohen Thron mit Dir ich sitz,<br/>Von Deiner Liebe -- die so lang und breit,<br/>So hoch, so tief, so stark ist allezeit --<br/>Singt dann mein Herz.<br/>',NULL,194730,7);
INSERT INTO stanza VALUES('G2026','1','Lobe den Herrn, den Allmächtigen, König der Schöpfung!<br/>Lob Ihn, o Seele, denn Er ist dein Heil, deine Rettung!<br/>Ihr, die ihr hört,<br/>Zu Seinem Tempel nun geht;<br/>Lasset den Lobgesang hören!<br/>',NULL,194731,1);
INSERT INTO stanza VALUES('G2026','2','Lobe den Herren, der alles so herrlich regieret,<br/>Der dich auf Adelers Fittichen sicher geführet,<br/>Der dich erhält,<br/>Wie es dir selber gefällt;<br/>Hast du nicht dieses verspüret?<br/>',NULL,194732,2);
INSERT INTO stanza VALUES('G2026','3','Lobe den Herren, der künstlich und fein dich bereitet,<br/>Der die Gesundheit verliehen, dich freundlich begleitet!<br/>In wieviel Not<br/>Hat nicht der gnädige Gott<br/>Über dich Flügel gebreitet!<br/>',NULL,194733,3);
INSERT INTO stanza VALUES('G2026','4','Lobe den Herren, der sichtbar dein Leben gesegnet,<br/>Der aus dem Himmel mit Strömen der Liebe geregnet.<br/>Denke daran,<br/>Was der Allmächtige kann,<br/>Der dir mit Liebe begegnet.<br/>',NULL,194734,4);
INSERT INTO stanza VALUES('G2026','5','Lobe den Herren, was in mir ist, lobe den Namen!<br/>Lob Ihn mit allen, die Seine Verheißung bekamen!<br/>Er ist dein Licht,<br/>Seele, vergiss es ja nicht;<br/>Lob Ihn in Ewigkeit, Amen!<br/>',NULL,194735,5);
INSERT INTO stanza VALUES('G2027','1','Du, Herr, für Gott bist kostbar,<br/>Erwählt, geliebt dazu;<br/>Gesalbt mit Öl der Freude,<br/>Wie anmutig bist Du!<br/>',NULL,194736,1);
INSERT INTO stanza VALUES('G2027','chorus','Wir schätzen innig Deine<br/>Vollkommene Schönheit,<br/>Dein''n Duft und Deine Süße,<br/>All Deine Lieblichkeit.<br/>',NULL,194737,2);
INSERT INTO stanza VALUES('G2027','2','An Dir ist alles lieblich,<br/>Der Schönste unter vieln!<br/>Dein Mund fließt voller Gnade;<br/>Das Herz uns bersten will.<br/>',NULL,194738,3);
INSERT INTO stanza VALUES('G2027','3','Die Weisen gaben Schätze,<br/>Sie ehrten Dich, o Gott;<br/>Vom Adligen begraben,<br/>Gar lieblich selbst im Tod.<br/>',NULL,194739,4);
INSERT INTO stanza VALUES('G2027','4','Dein Haupt, Herr, wurd gesalbet,<br/>Der Lieblichste bist Du;<br/>Gesalbt auch Deine Füße,<br/>Gesegnet immerzu.<br/>',NULL,194740,5);
INSERT INTO stanza VALUES('G2027','5','Dein Tod, so süß wie Myrrhe,<br/>Mit Trost uns sanft erfüllt;<br/>Dein Auferstehungsduft, Herr,<br/>Das Sehnen Gottes stillt.<br/>',NULL,194741,6);
INSERT INTO stanza VALUES('G2027','6','So schön wie Hennablüten,<br/>Vollkomm''ne Lieblichkeit;<br/>Wie Apfelbäume blühst Du,<br/>Trägst süße Frucht allzeit.<br/>',NULL,194742,7);
INSERT INTO stanza VALUES('G2027','7','Wie Wein ist Deine Liebe,<br/>Dein Name Salböl ist;<br/>Als unser Fest der Liebe<br/>Du süße Wonne bist.<br/>',NULL,194743,8);
INSERT INTO stanza VALUES('G2027','8','Wenn wir, Herr, an Dich denken,<br/>Wird unser Herz so warm;<br/>Wir schmecken Deine Süße,<br/>Und ruhn in Deinem Arm.<br/>',NULL,194744,9);
INSERT INTO stanza VALUES('G2028','1','Herr, Du bist kostbarer als Silber,<br/>Herr, Du bist viel teurer als Gold,<br/>Herr, Du bist noch schöner als Diamanten<br/>Und nichts lässt sich mit Dir vergleichen, Herr.<br/>',NULL,194745,1);
INSERT INTO stanza VALUES('G2028','2','Herr, Dein Leben ist göttlich und ewig.<br/>Herr, Dein Leben hat mich neu geborn.<br/>Herr, Dein Leben, es wächst und wächst jetzt in mir,<br/>Bis ich Dir ganz entsprechen werde dann.<br/>',NULL,194746,2);
INSERT INTO stanza VALUES('G2028','3','Deine Liebe ist weit wie der Ozean.<br/>Deine Liebe ist tief wie das Meer.<br/>Deine Liebe umfasst die Nationen.<br/>Ich möchte, dass dies alles in mir lebt.<br/>',NULL,194747,3);
INSERT INTO stanza VALUES('G2028','4','Herr, Dein Licht scheint hell in uns allen,<br/>Herr, Dein Licht verdrängt Dunkelheit.<br/>Herr, Dein Licht, es führt uns jetzt vorwärts<br/>Und macht uns für den Hochzeitstag bereit.<br/>',NULL,194748,4);
INSERT INTO stanza VALUES('G2029','1','Kann nicht genug Dich atmen, Herr,<br/>O milde, süße Luft;<br/>Den Duft der Myrte lieb ich sehr,<br/>Doch den der Henna noch vielmehr,<br/>Den Himmelsbalsam-Duft.<br/>Den Himmelsbalsam-Duft.<br/>',NULL,194749,1);
INSERT INTO stanza VALUES('G2029','2','Kann nicht genug anschauen Dich,<br/>Ich ja den Schönsten hab;<br/>Mein Herz zum Bersten übervoll,<br/>Stets Dein Gesicht mir strahlen soll,<br/>//An Dir ich mich nun lab.//<br/>',NULL,194750,2);
INSERT INTO stanza VALUES('G2029','3','Kann nicht genug mich geben Dir,<br/>Mein Retter, Meister, Freund;<br/>Frei ausgehn wünsche ich mir nicht,<br/>Doch immer, ewig, williglich<br/>//Dir dienen bis zum End.//<br/>',NULL,194751,3);
INSERT INTO stanza VALUES('G2029','4','Kann nicht genug lobpreisen Dich,<br/>Den schönsten Namen hier;<br/>Ein Lied voll Harmonie sing ich,<br/>Aus tiefstem Herzen inniglich,<br/>//Voll Freude sing ich Dir.//<br/>',NULL,194752,4);
INSERT INTO stanza VALUES('G2029','5','Kann nicht genug erzähln von Dir,<br/>Mein Mund Dein Ruhm kundtut;<br/>Dein Herz, es schlägt so zart für mich,<br/>Wenn Du mich ziehst so nah an Dich,<br/>//Und sprichst: „''s ist alles gut."//<br/>',NULL,194753,5);
INSERT INTO stanza VALUES('G2030','1','Wir denken nun an Dich, o Herr,<br/>Ehrn Dich für alles, was Du bist;<br/>Du bist so reich, so wunderbar,<br/>In unsern Herzen fließt Du süß.<br/>',NULL,194754,1);
INSERT INTO stanza VALUES('G2030','chorus','Was Du bist, Herr, uns ganz genügt!<br/>Dir unsrem Herzen Lob entquillt!<br/>Du stellst uns voll und ganz zufrieden,<br/>Du bist''s, der unsre Sehnsucht stillt.<br/>',NULL,194755,2);
INSERT INTO stanza VALUES('G2030','2','Du bist der wahre Gott, o Herr,<br/>Der Gott, der unser Leben ist;<br/>Der Gott, der Liebe ist und Licht,<br/>Der Gott, der unsre Freude ist.<br/>',NULL,194756,3);
INSERT INTO stanza VALUES('G2030','3','Doch Du bist auch ein wahrer Mensch,<br/>Ein Mensch so fein und gut gesinnt;<br/>Ein Mensch, an dem Gott hat Gefallen,<br/>Ein Mensch, der unser Herz gewinnt.<br/>',NULL,194757,4);
INSERT INTO stanza VALUES('G2030','4','Du bist sogar ein Sklave, Herr,<br/>Als Knecht zu dienen, ganz bereit;<br/>Gehorsam bis zum Tod am Kreuz,<br/>Dort hast Du uns vollauf befreit.<br/>',NULL,194758,5);
INSERT INTO stanza VALUES('G2030','5','Dazu bist Du ein König, Herr,<br/>Im Leben und in Liebe lenkst;<br/>Von Gott gesalbt mit Seiner Kraft,<br/>Mit uns zu herrschen, Du gedenkst.<br/>',NULL,194759,6);
INSERT INTO stanza VALUES('G2030','6','Gedenken wir in Liebe Dein,<br/>Hab''n wir teil an dem, was Du bist.<br/>Wir sind zudem Dein Gegenüber,<br/>Das voller Liebe Dich genießt.<br/>',NULL,194760,7);
INSERT INTO stanza VALUES('G2031','1','Wie allumfassend, Herr, Du bist!<br/>Von Gott sind wir in Dir --<br/>Was Du für uns geworden bist,<br/>So sehr genießen wir.<br/>',NULL,194761,1);
INSERT INTO stanza VALUES('G2031','2','Die Weisheit Gottes bist Du uns,<br/>Gott rettet uns durch Dich;<br/>Der Weg zur Rettung Du nur bist,<br/>Allein und ewiglich.<br/>',NULL,194762,2);
INSERT INTO stanza VALUES('G2031','3','Du bist für uns Gerechtigkeit,<br/>Der Gottes Recht erfüllt;<br/>Wir alle sind gerecht in Dir,<br/>Ins beste Kleid umhüllt.<br/>',NULL,194763,3);
INSERT INTO stanza VALUES('G2031','4','Herr, Du bist unsre Heiligkeit.<br/>Umwandlung brauchen wir;<br/>In Dir heiligst Du tadellos,<br/>Uns gleichgestaltest Dir.<br/>',NULL,194764,4);
INSERT INTO stanza VALUES('G2031','5','Erlösung bist Du auch für uns,<br/>Dein Abbild unser wird;<br/>Verklären wirst Du unsern Leib,<br/>Von Freiheit sublimiert.<br/>',NULL,194765,5);
INSERT INTO stanza VALUES('G2031','6','Wenn wir nun sinnen über Dich,<br/>Genießen Dich, den Herrn,<br/>So nähert sich Dein Kommen mehr,<br/>Du bleibst nicht lange fern.<br/>',NULL,194766,6);
INSERT INTO stanza VALUES('G2031','7','Wie süß der Vorgeschmack doch ist,<br/>So herrlich und so reich!<br/>Wir sehnen uns, bei Dir zu sein,<br/>In Füll erfahrn Dich.<br/>',NULL,194767,7);
INSERT INTO stanza VALUES('G2032','1','Was ist Er? -- Unser Vater.<br/>Er ist unser ew''ger Vater.<br/>Er der Schöpfung Erstgeborner ist<br/>Und Er lebt in mir und überfließt.<br/>Welch ein Vater! Wunderbar!<br/>',NULL,194768,1);
INSERT INTO stanza VALUES('G2032','2','Was ist Er? -- Lebenswasser.<br/>Wie ein starker Strom des Lebens,<br/>Der mich tränkt in diesem Wüstenland.<br/>Er die Felskluft, wo ich Zuflucht fand.<br/>Welch ein Zustrom! Wunderbar!<br/>',NULL,194769,2);
INSERT INTO stanza VALUES('G2032','3','Was ist Er? -- Unser Weinstock<br/>Und der Zweig, die Wurzel Jesses.<br/>Er -- der Baum des Lebens: Welch Genuss,<br/>Jeder Ihn nun einfach essen muss.<br/>Welch ein Weinstock! Wunderbar!<br/>',NULL,194770,3);
INSERT INTO stanza VALUES('G2032','4','Was ist Er? -- Unser Hirte.<br/>Gottes Lamm und Bock der Sühnung.<br/>Er weidet uns so aufmerksam.<br/>Durch Sein Blut nun essen wir vom Lamm.<br/>Welch ein Hirte! Wunderbar!<br/>',NULL,194771,4);
INSERT INTO stanza VALUES('G2032','5','Was ist Er? -- Er ist Geist jetzt.<br/>Allumfassend als der Geist jetzt.<br/>Unser alles und so umfangreich.<br/>Schon beim Anrufen fließt Leben gleich.<br/>Welch ein Geist jetzt! Wunderbar!<br/>',NULL,194772,5);
INSERT INTO stanza VALUES('G2032','6','Was ist Er? -- Eine Person.<br/>Eine wirkliche Person.<br/>Als Person lebt Er in uns allzeit,<br/>Und Er ist so voller Herrlichkeit!<br/>Welch Person! Wunderbar!<br/>',NULL,194773,6);
INSERT INTO stanza VALUES('G2032','7','Was ist Er? -- Der Leib Christi<br/>Und die ganze Füll der Gottheit.<br/>Im Plan Gottes Er zentral erscheint,<br/>Neuer Mensch, Christus und die Gemeind.<br/>Er ist wunderbar, wunderbar.<br/>Er ist wunderbar, wunderbar.<br/>Er ist wunderbar, wunderbar.<br/>',NULL,194774,7);
INSERT INTO stanza VALUES('G2033','1','Herr, im Schoß des Vaters warst Du<br/>Lange vor Beginn der Zeit.<br/>Du der einziggeborne Sohn warst<br/>In des Vaters Herrlichkeit.<br/>Als der Vater Dich uns schenkte,<br/>Warst Du in Person Ihm gleich;<br/>Hast die Fülle Deines Vaters<br/>Kundgetan im Geist so reich.<br/>',NULL,194775,1);
INSERT INTO stanza VALUES('G2033','2','Du durch Tod und Auferstehung<br/>Bist der erstgeborne Sohn;<br/>Die Verdopplung Deiner sind wir,<br/>Seit Dein Leben in uns wohnt.<br/>Wir in Dir sind neu geboren,<br/>Gottes Söhne wurden wir;<br/>Und als Deine vielen Brüder<br/>Gleich in der Natur sind Dir.<br/>',NULL,194776,2);
INSERT INTO stanza VALUES('G2033','3','Einst warst Du das einzig Korn, Herr,<br/>In die Erde fielst und starbst,<br/>Dass durch Tod und Auferstehung<br/>Reich Du Zuwachs Dir erwarbst.<br/>Wir sind Deine vielen Körner,<br/>Dir ganz gleich -- gezeugt von Dir;<br/>Als ein Brotlaib, der vermengt ist,<br/>Deine Fülle zeigen wir.<br/>',NULL,194777,3);
INSERT INTO stanza VALUES('G2033','4','Deine gänzliche Vermehrung,<br/>Deine Braut, Dein teurer Leib<br/>Und Dein Ausdruck, Deine Fülle,<br/>Sind wir jetzt. In uns nun bleib!<br/>Du hast Dich durch uns verbreitet,<br/>Lebenszuwachs sind wir Dir,<br/>Als Dein Überfluss, Dein Wachstum,<br/>Eins mit Dir, o Haupt, sind wir.<br/>',NULL,194778,4);
INSERT INTO stanza VALUES('G2034','1','Oh, Christus ist der Brunnen,<br/>So süß und tief und weit;<br/>Und Sein lebend''ges Wasser<br/>Befreit von Gram und Streit.<br/>Des Herrn Barmherzigkeit reicht<br/>Viel weiter als das Meer;<br/>So reich fließt Seine Gnade,<br/>Wie weise plante Er!<br/>',NULL,194779,1);
INSERT INTO stanza VALUES('G2034','2','Oh, ich bin meines Liebsten,<br/>Mein Liebster -- Er ist mein;<br/>Er bringt mich, armen Sünder,<br/>In Sein Haus voller Wein!<br/>Mein Stand ist einzig Christus,<br/>Nur diesen kenne ich.<br/>In Ihm bin ich geborgen,<br/>Und Seine Hand hält mich.<br/>',NULL,194780,2);
INSERT INTO stanza VALUES('G2034','3','Die Braut schaut nicht ihr Kleid an,<br/>Doch nur den Bräutigam;<br/>Ich schau nicht Herrlichkeiten,<br/>Doch meinen König an.<br/>Ich schau nicht meine Krone,<br/>Doch die durchbohrte Hand;<br/>Dem Lamm gib alle Ehre,<br/>Es ist mein fester Stand!<br/>',NULL,194781,3);
INSERT INTO stanza VALUES('G2035','1','O Jesus, Jesus, liebster Herr!<br/>Vergib mir, wenn ich sag<br/>Aus Liebe Deinen Namen oft,<br/>Gar tausendmal am Tag!<br/>',NULL,194782,1);
INSERT INTO stanza VALUES('G2035','chorus','O Jesus Herr! Bleib Du bei mir,<br/>Was immer auch geschieht, o Herr!<br/>Dein Lächeln ist mein schönster Lohn;<br/>Ich lieb Dich, lieb Dich sehr!<br/>',NULL,194783,2);
INSERT INTO stanza VALUES('G2035','2','Ich lieb Dich so, wie soll ich nur<br/>Mein Sehnen kontrolliern?<br/>Wie Feuer Deine Liebe brennt,<br/>In der ich mich verlier.<br/>',NULL,194784,3);
INSERT INTO stanza VALUES('G2035','3','Herr, Du bist alles jetzt für mich,<br/>Mein Reichtum, Seelenheil;<br/>Mein Herzenswunsch und meine Kraft<br/>und Herrlichkeit allzeit.<br/>',NULL,194785,4);
INSERT INTO stanza VALUES('G2035','4','Brenn, brenn, o Liebe brenn in mir,<br/>Brenn heftig Tag und Nacht,<br/>Bis Wünsche, die nur irdisch sind,<br/>Zu Asche sind gemacht!<br/>',NULL,194786,5);
INSERT INTO stanza VALUES('G2035','5','O Licht im Dunkeln, Freud im Leid,<br/>O Himmel hier auf Erd;<br/>Du liebster Jesus, teurer Schatz,<br/>Du bist mir alles wert.<br/>',NULL,194787,6);
INSERT INTO stanza VALUES('G2035','6','Die Liebe keine Grenzen kennt,<br/>Sie ist so wunderbar!<br/>Der Herr ist süßer jeden Tag,<br/>Als Er es gestern war.<br/>',NULL,194788,7);
INSERT INTO stanza VALUES('G2036','1','Herr, lebend''ger Brunnen bist,<br/>Des Lebenswassers Fluss.<br/>Du allein löschst meinen Durst.<br/>Nur Du zufriedenstellst.<br/>Herr, lebend''ger Baum bist Du,<br/>Der Baum des Lebens Du.<br/>Du allein stillst meinen Hunger.<br/>Nur Du zufriedenstellst.<br/>',NULL,194789,1);
INSERT INTO stanza VALUES('G2036','chorus','Jeden Moment auf vielerlei Weis<br/>Ist Er Versorgung gewiss.<br/>Jetzt und auf ewig, allezeit<br/>Nur Du zufriedenstellst.<br/>',NULL,194790,2);
INSERT INTO stanza VALUES('G2036','2','Herr, lebend''ger Weinstock bist.<br/>Wir wollen in Dir bleibn.<br/>Nur Du göttlich Leben gibst.<br/>Nur Du zufriedenstellst.<br/>So müssen preisen, singen wir,<br/>Und wir bezeugen auch:<br/>Herr, Du bist der Einzige --<br/>Nur Du zufriedenstellst.<br/>',NULL,194791,3);
INSERT INTO stanza VALUES('G2037','1','Manche Leute sagen, dass man Gott nicht essen kann.<br/>„Gute Werke solln wir tun -- das weiß doch jedermann."<br/>Doch wir wolln euch heute sagen: Er schmeckt wunderbar.<br/>Jesus ist das Brot des Lebens, es ist wirklich wahr!<br/>',NULL,194792,1);
INSERT INTO stanza VALUES('G2037','chorus','Wir lieben die Gemeind:<br/>Jesus essen, trinken, atmen!<br/>Wir lieben die Gemeind,<br/>Essen Gottes Wort.<br/>Wir lieben es zu hörn:<br/>„O Herr, amen, halleluja!"<br/>Wir lieben die Gemeind,<br/>Festen immerfort.<br/>',NULL,194793,2);
INSERT INTO stanza VALUES('G2037','2','Wenn Er unser Sein erfüllt, sind wir niemals mehr gleich.<br/>Seinen Namen rufen wir, denn Er ist wirklich reich!<br/>Wöchentlich ein Gottesdienst, das reicht uns niemals aus.<br/>Täglich brauchen wir Gemeinschaft, stets von Haus zu Haus.<br/>',NULL,194794,3);
INSERT INTO stanza VALUES('G2037','3','Falls der Zustand dieser Welt in der heutigen Zeit<br/>Dich verzweifeln lässt an dieser Welt voll Nichtigkeit.<br/>Dann hör zu, was wir dir sagen, und mal überleg!<br/>Vielleicht findest du mit uns nun einen bessren Weg.<br/>',NULL,194795,4);
INSERT INTO stanza VALUES('G2038','1','Herrlichkeit, Segen und Ehre sei Dir,<br/>Und Ehre sei Dir,<br/>Und Ehre sei Dir.<br/>Herrlichkeit, Segen und Ehre sei Dir,<br/>Jetzt und in Ewigkeit.<br/>',NULL,194796,1);
INSERT INTO stanza VALUES('G2038','chorus','Preist Ihn! Preist Ihn!<br/>All ihr Heil''gen preiset Ihn!<br/>Preist Ihn! Preist Ihn!<br/>Jetzt und in Ewigkeit.<br/>Halleluja!<br/>',NULL,194797,2);
INSERT INTO stanza VALUES('G2038','2','Herrlichkeit, Segen und Ehre sei Dir,<br/>Und Ehre sei Dir,<br/>Und Ehre sei Dir.<br/>Herrlichkeit, Segen und Ehre sei Dir,<br/>Jetzt und in Ewigkeit.<br/>',NULL,194798,3);
INSERT INTO stanza VALUES('G2039','1','Der Dreieine Gott macht Wohnung jetzt in uns<br/>Als der Geist wunderbar heut in uns.<br/>Wir sind mit dem Herrn vermengt und eins mit Ihm<br/>Durch den Geist, der gibt Leben in uns.<br/>',NULL,194799,1);
INSERT INTO stanza VALUES('G2039','chorus','Er ist der Geist wunderbar heut in uns,<br/>Ja, der Geist wunderbar heut in uns!<br/>Gott ist in dem Sohn, der Sohn ist jetzt der Geist,<br/>Ja, der Geist, wunderbar heut in uns!<br/>',NULL,194800,2);
INSERT INTO stanza VALUES('G2039','2','„Abba Vater" ruft nun tief in uns die Stimm<br/>Aus dem Geist wunderbar heut in uns.<br/>Er, der Geist des Sohnes, welcher schreit zu Ihm<br/>Durch den Geist, der gibt Leben in uns.<br/>',NULL,194801,3);
INSERT INTO stanza VALUES('G2039','3','Jesus Christus ist der Herr, in uns lebt Er<br/>Als der Geist wunderbar heut in uns.<br/>Den verklärten Herrn genießen wir nun sehr<br/>Durch den Geist, der gibt Leben in uns.<br/>',NULL,194802,4);
INSERT INTO stanza VALUES('G2039','4','Nun ist Er der Geist der Wirklichkeit fürwahr<br/>Als der Geist wunderbar heut in uns.<br/>Ja, was Christus ist, wird wirklich und so klar<br/>Durch den Geist, der gibt Leben in uns.<br/>',NULL,194803,5);
INSERT INTO stanza VALUES('G2039','5','Diese Gabe tief in uns wecken wir auf<br/>Durch den Geist wunderbar heut in uns.<br/>Rufen wir: „Herr Jesus" -- springt unser Geist auf<br/>Durch den Geist, der gibt Leben in uns!<br/>',NULL,194804,6);
INSERT INTO stanza VALUES('G2040','1','Jeder sollte wissen, wo<br/>(Jeder sollte wissen, wo)<br/>Jeder sollte wissen, wo<br/>(Jeder sollte wissen, wo)<br/>Jeder sollte wissen, wo,<br/>(Jeder sollte wissen, wo)<br/>Wo Jesus wohnt.<br/>(Wiederholen)<br/>',NULL,194805,1);
INSERT INTO stanza VALUES('G2040','chorus','Er wohnt jetzt in unsrem Geiste,<br/>Leben, Atem ist Er uns;<br/>Wir sind eins mit Ihm im Geiste.<br/>Jeder sollte es verstehn.<br/>',NULL,194806,2);
INSERT INTO stanza VALUES('G2040','2','Jeder sollte wissen, dass<br/>Jeder sollte wissen, dass<br/>Jeder sollte wissen, dass<br/>Dass Christus lebt.<br/>(Wiederholen)<br/>',NULL,194807,3);
INSERT INTO stanza VALUES('G2040','chorus','Christus als der Geist gibt Leben,<br/>Gottes Fülle ist in Ihm.<br/>Haben Teil an Seinem Reichtum,<br/>Rufen Seinen Namen an.<br/>',NULL,194808,4);
INSERT INTO stanza VALUES('G2041','1','Ich habe einen Strom, der tief in mir fließt;<br/>Er lässt die Lahmen gehn und die Blinden sehn.<br/>Gefangne er befreit und die Herzen heilt!<br/>Ich habe einen Strom, der tief in mir fließt.<br/>',NULL,194809,1);
INSERT INTO stanza VALUES('G2041','chorus','Steig auf, o Quell, in meinem Geist!<br/>Steh auf, erzähl, dass''s alle hören!<br/>Steig auf, o Quell, und ich erfahre<br/>Dein Leben, das überfließt!<br/>',NULL,194810,2);
INSERT INTO stanza VALUES('G2041','2','Ich habe einen Strom, der tief in mir fließt;<br/>Als Gott mich frei gemacht, fing das Sprudeln an.<br/>Ich will einfach nur, dass er weiter fließt.<br/>Ich habe einen Strom, der tief in mir fließt.<br/>',NULL,194811,3);
INSERT INTO stanza VALUES('G2041','3','Ruf ich Seinen Namen, so strömt''s in mir.<br/>Es wendet mich zu Ihm und macht Ihn zum Herrn.<br/>Wenn mein Geist so brennt, kann der Feind nichts tun.<br/>„O Herr Jesus!", ruf ich und so strömt''s noch mehr.<br/>',NULL,194812,4);
INSERT INTO stanza VALUES('G2042','1','Hauche Deinen Geist auf mich, Herr,<br/>Dich zu atmen, lehre mich,<br/>Und in Deinen Schoß zu schütten<br/>Meine Sünd, mein Selbst, mein Ich!<br/>',NULL,194813,1);
INSERT INTO stanza VALUES('G2042','chorus','Atme aus all meine Sorgen,<br/>Auch mein altes Sein<br/>Und ich atme, atme, atme<br/>Deine Fülle ein.<br/>',NULL,194814,2);
INSERT INTO stanza VALUES('G2042','2','Atme aus mein eignes Leben.<br/>Füll mit Deinem, Herr, allein!<br/>Eigne Kraft und Schwachheit lass ich,<br/>Atme Gottes Leben ein.<br/>',NULL,194815,3);
INSERT INTO stanza VALUES('G2042','3','Atme aus nun meine Sünde,<br/>Diese Last nahmst Du von mir;<br/>Atme ein nun Deine Reinheit,<br/>Find mein Leben ganz in Dir.<br/>',NULL,194816,4);
INSERT INTO stanza VALUES('G2042','4','Atme aus all meine Sorgen,<br/>Herr, auf Deiner lieben Brust;<br/>Atme ein jetzt Deinen Frieden,<br/>Deine Freude, Ruh und Trost.<br/>',NULL,194817,5);
INSERT INTO stanza VALUES('G2042','5','Atme aus all meine Krankheit,<br/>Ihre Last trugst Du so treu;<br/>Atme ein all Deine Heilung,<br/>Längst verheißen, immer neu.<br/>',NULL,194818,6);
INSERT INTO stanza VALUES('G2042','6','Atme aus all meine Sehnsucht<br/>In Dein offnes Ohr, o Herr;<br/>Atme ein nun Deine Antwort,<br/>Zweifel hab ich keine mehr.<br/>',NULL,194819,7);
INSERT INTO stanza VALUES('G2042','7','Ich bin allezeit am Atmen,<br/>All mein Leben schöpf aus Dir;<br/>Zug für Zug, um Deinetwillen,<br/>Atme nun Dein Geist in mir.<br/>',NULL,194820,8);
INSERT INTO stanza VALUES('G2043','1','Ja, nun in mir wohnt Gottes Salbung,<br/>Alles lehrt sie allezeit;<br/>Sie leitet mich, im Herrn zu leben stets,<br/>Seine Gegenwart verleiht.<br/>',NULL,194821,1);
INSERT INTO stanza VALUES('G2043','chorus','Ja, die Salbung wohnt in meinem Geist,<br/>Die Salbung wohnt in mir<br/>Und lehrt mich allezeit.<br/>Ja, die Salbung wohnt in meinem Geist,<br/>Sie lehrt mich alles allezeit.<br/>',NULL,194822,2);
INSERT INTO stanza VALUES('G2043','2','Sie ist der Geist, der Sich beweget,<br/>Sie wie reines Salböl fließt;<br/>Ihr Fundament ist Jesu teures Blut,<br/>Damit sie so standfest ist.<br/>',NULL,194823,3);
INSERT INTO stanza VALUES('G2043','3','Sie salbt mich mit der Essenz Gottes,<br/>Gott zu kennen innerlich;<br/>So hab ich Gottes Element in mir,<br/>Er durchsättigt mich mit Sich.<br/>',NULL,194824,4);
INSERT INTO stanza VALUES('G2043','4','Sie bringt mich mit Gott in Gemeinschaft,<br/>Bis ich mich in Ihm verlier;<br/>In Gott, dem Licht der Wahrheit, wandle ich,<br/>Lieb und Gnade fließt aus mir.<br/>',NULL,194825,5);
INSERT INTO stanza VALUES('G2044','1','Füll mich mit dem Geist der Gnade,<br/>Meinen Geist erfüll stets mehr!<br/>Deine Gegenwart erfüll mich,<br/>Komm und füll mich, liebster Herr!<br/>',NULL,194826,1);
INSERT INTO stanza VALUES('G2044','chorus','Füll mich jetzt! Füll mich jetzt!<br/>Füll mit Deinem Geist mich jetzt!<br/>Streif mich ab, entleer mich gründlich,<br/>Füll mit Deinem Geist mich jetzt!<br/>',NULL,194827,2);
INSERT INTO stanza VALUES('G2044','2','Du allein nur kannst mich füllen,<br/>Über Bitten und Verstehn;<br/>Herr, ich brauch Dich, brauch Dich wirklich,<br/>„Komm und füll mich!", ist mein Flehn.<br/>',NULL,194828,3);
INSERT INTO stanza VALUES('G2044','3','Wie zerbrechlich, voller Schwachheit!<br/>Dir zu Füßen sitze ich;<br/>Segne mich durch Deinen Geist, Herr,<br/>Komm, mit Deiner Kraft füll mich!<br/>',NULL,194829,4);
INSERT INTO stanza VALUES('G2044','4','Wasch und tröste, segne, rette!<br/>Den zerbrochnen Geist erfüll!<br/>Ja, Du tröstest und errettest.<br/>Süß mit Dir mich nun umhüll!<br/>',NULL,194830,5);
INSERT INTO stanza VALUES('G2045','1','Fülle meinen Geist,<br/>Fülle meinen Geist,<br/>Bis er überfließt direkt<br/>aus meinem inneren Sein!<br/>Fülle meinen Geist,<br/>Fülle meinen Geist,<br/>Bis er überfließt direkt<br/>aus meinem inneren Sein!<br/>',NULL,194831,1);
INSERT INTO stanza VALUES('G2045','chorus','Fülle mich heut!<br/>Das bet ich erneut.<br/>Oh, Herr Jesus,<br/>Fließ als lebendiges Wasser!<br/>Oh, Herr Jesus,<br/>Ström als der Lebensquell<br/>Direkt aus meinem inneren Sein!<br/>',NULL,194832,2);
INSERT INTO stanza VALUES('G2045','2','Brich durch jeden Teil!<br/>Brich durch jeden Teil<br/>Von meinem Herzen, Willen,<br/>Verstand, Gefühl.<br/>Brich durch jeden Teil!<br/>Brich durch jeden Teil<br/>Von meinem Herzen, Willen,<br/>Verstand, Gefühl.<br/>',NULL,194833,3);
INSERT INTO stanza VALUES('G2045','3','Fließ aus mir heraus!<br/>Fließ aus mir heraus!<br/>Egal, ob ich rufe,<br/>bet, singe laut.<br/>Fließ aus mir heraus!<br/>Fließ aus mir heraus!<br/>Egal, ob ich rufe,<br/>bet, singe laut.<br/>',NULL,194834,4);
INSERT INTO stanza VALUES('G2046','1','Herr, vor Dir wir stehn und mit Freimut flehn.<br/>Gib uns Deine Macht, stärk uns hier,<br/>Mach uns Kämpfern gleich für Dein Königreich!<br/>Sitzend in den Himmeln kämpfen wir.<br/>',NULL,194835,1);
INSERT INTO stanza VALUES('G2046','chorus','Kraft! Kraft! Kleide uns mit Kraft!<br/>Deiner starken Kraft von oben her!<br/>Kraft! Kraft! Kleide uns mit Kraft!<br/>Als Dein Leib bitten wir dies, o Herr.<br/>',NULL,194836,2);
INSERT INTO stanza VALUES('G2046','2','Herr, auf Dich wir schaun und auf Dich vertraun.<br/>Deinen Regenguss teil uns aus!<br/>Wir für Deinen Leib sind frisch allezeit.<br/>Segne uns und bau mit uns Dein Haus!<br/>',NULL,194837,3);
INSERT INTO stanza VALUES('G2046','chorus','Regen! Regen! Gieß aus Deinen Regen!<br/>Deinen Himmels-Regen gieß aus mehr!<br/>Regen! Regen! Gieß aus Deinen Regen!<br/>Als Dein Leib bitten wir dies, o Herr.<br/>',NULL,194838,4);
INSERT INTO stanza VALUES('G2046','3','Dich erwarten wir, fordern ein von Dir<br/>Gottes Feuer, das uns stärkt sehr.<br/>Schenk uns Feuer nun, um Dich kundzutun,<br/>Herzen rett und läutre Du, o Herr!<br/>',NULL,194839,5);
INSERT INTO stanza VALUES('G2046','chorus','Feuer! Feuer! Gib uns Feuerzungen!<br/>Kundtun Deine Rettung wolln wir mehr!<br/>Feuer! Feuer! Gib uns Feuerzungen!<br/>Als Dein Leib bitten wir dies, o Herr.<br/>',NULL,194840,6);
INSERT INTO stanza VALUES('G2047','1','Glauben wir, glauben wir,<br/>Glauben wir, so reden wir.<br/>Glauben wir, glauben wir,<br/>Glauben wir, so reden wir.<br/>',NULL,194841,1);
INSERT INTO stanza VALUES('G2047','2','Wende dich von all deinen Zweifeln im Verstand<br/>Zum Glauben im vermengten Geist!<br/>Bete nur, um Gott als den Geist zu berührn!<br/>Der Weg zum Leben ist Er.<br/>',NULL,194842,2);
INSERT INTO stanza VALUES('G2047','3','Sprechen ist der Weg,<br/>Den Leib aufzubaun.<br/>Leben und Wahrheit sprich!<br/>So wirst du erfüllt!<br/>',NULL,194843,3);
INSERT INTO stanza VALUES('G2048','1','Ewig hält mich Liebe fest,<br/>Durch die Gnade mir gewährt;<br/>Himmelsatem hier, o Geist,<br/>Dies hast Du mich ja gelehrt.<br/>Oh, wie voll der Friede ist!<br/>Oh, wie göttlich ist''s allein!<br/>Diese Liebe schwindet nicht:<br/>Ich bin Sein und Er ist mein.<br/>',NULL,194844,1);
INSERT INTO stanza VALUES('G2048','2','Heller scheint der Himmel blau,<br/>Sanfter blickt die Erde grün,<br/>Etwas schillert, was das Aug<br/>Ohne Christus nie gesehn.<br/>Blumen strahlen bunter da,<br/>Schöner stimmen Vögel ein,<br/>Seit ich weiß, was ich nun weiß:<br/>Ich bin Sein und Er ist mein.<br/>',NULL,194845,2);
INSERT INTO stanza VALUES('G2048','3','Einst mich plagte manch Alarm,<br/>Jetzt den Frieden nichts verschlägt,<br/>Ewig fest in Seinem Arm,<br/>In der Liebe Schoß umhegt.<br/>Oh, ich läge ewig hier,<br/>Angst und Zweifel lass ich sein,<br/>Und ins Ohr verspricht Er mir:<br/>Ich bin Sein und Er ist mein.<br/>',NULL,194846,3);
INSERT INTO stanza VALUES('G2048','4','Ich bin Sein; ja, ewig Sein:<br/>Wer kann uns denn trennen jetzt?<br/>Ach, welch Ruhe nimmt mich ein,<br/>Mit der Christus füllt das Herz!<br/>Schwinden All und Erd dahin,<br/>Dämmern Himmelsleuchten ein,<br/>Dann, da Gott und ich noch sind,<br/>Bin ich Sein und Er ist mein.<br/>',NULL,194847,4);
INSERT INTO stanza VALUES('G2049','1','Freue dich nun mit mir!<br/>Da mein Herz elend war,<br/>Und ich entdeckte einen Hort<br/>Der Liebe unsagbar.<br/>',NULL,194848,1);
INSERT INTO stanza VALUES('G2049','2','Freue dich nun mit mir!<br/>Ich, einst verzagt und krank,<br/>Bin nun begegnet einem Arzt,<br/>Der nimmt Sich meiner an.<br/>',NULL,194849,2);
INSERT INTO stanza VALUES('G2049','3','Freue dich nun mit mir!<br/>Ich war geschunden sehr,<br/>Und nun mich trägt ein starker Arm;<br/>Der hält mich fest nunmehr.<br/>',NULL,194850,3);
INSERT INTO stanza VALUES('G2049','4','Freue dich nun mit mir!<br/>Arg schweifte ich einst aus,<br/>Und Einer brachte mich zurück,<br/>In Ihm zu sein, zuhaus.<br/>',NULL,194851,4);
INSERT INTO stanza VALUES('G2049','5','Freue dich nun mit mir!<br/>Denn ich fand einen Freund,<br/>Der meine Herzenstiefen kennt,<br/>Doch mich liebt ohne End.<br/>',NULL,194852,5);
INSERT INTO stanza VALUES('G2049','6','Sein'' Liebe war mir fremd,<br/>Lang hat Er auch geliebt,<br/>Liebe so standfest und so treu,<br/>So einfühlsam und tief.<br/>',NULL,194853,6);
INSERT INTO stanza VALUES('G2049','7','Und jetzt ist alles mein,<br/>Ich kenne Seine Stimm;<br/>Wie schöpfe ich denn jemals aus<br/>Die Freude hier an Ihm?<br/>',NULL,194854,7);
INSERT INTO stanza VALUES('G2050','1','Kann es denn sein, dass ich gewinn<br/>Ein''n Anteil an des Retters Blut?<br/>Starb Er für mich, der Ihm Leid gab,<br/>Für mich, der Ihn zu Tod geführt?<br/>Welch große Liebe drängte Dich,<br/>Dass Du, mein Gott, dort starbst für mich?<br/>Welch große Liebe drängte Dich,<br/>Dass Du, mein Gott, dort starbst für mich?<br/>',NULL,194855,1);
INSERT INTO stanza VALUES('G2050','2','Geheimnis groß, dass Gott Selbst stirbt!<br/>Wer kann ergründen diesen Plan?<br/>Der erste Seraph prüft umsonst,<br/>Was Gottes Lieb umfassen kann!<br/>Es war Barmherzigkeit, mein Herr.<br/>Lasst Engel forschen nimmermehr!<br/>Es war Barmherzigkeit, mein Herr.<br/>Lasst Engel forschen nimmermehr!<br/>',NULL,194856,2);
INSERT INTO stanza VALUES('G2050','3','Er kam von Seines Vaters Thron,<br/>Mit Gnade reich und frei, herab,<br/>Entleerte Sich bis auf die Lieb,<br/>Sein Blut für Adams Samen gab.<br/>Frei währt die Gnade ewiglich,<br/>Denn, o mein Gott, sie fand auch mich.<br/>Frei währt die Gnade ewiglich,<br/>Denn, o mein Gott, sie fand auch mich.<br/>',NULL,194857,3);
INSERT INTO stanza VALUES('G2050','4','Lang lag mein Geist in Ketten fest,<br/>Gebunden in der Sünd und Nacht;<br/>Du sandtest einen Lebensstrahl,<br/>Licht flammte auf, ich bin erwacht!<br/>Die Fesseln fielen ab von mir,<br/>Ich ging hinaus und folgte Dir.<br/>Die Fesseln fielen ab von mir,<br/>Ich ging hinaus und folgte Dir.<br/>',NULL,194858,4);
INSERT INTO stanza VALUES('G2050','5','Keine Verdammnis fürcht ich mehr,<br/>In Jesus ist nun alles mein!<br/>Er ist mein Haupt und Lebensquell,<br/>Gerecht bin ich in Ihm allein.<br/>Kühn tret ich vor den ew''gen Thron<br/>Und nehm durch Christus meine Kron.<br/>Kühn tret ich vor den ew''gen Thron<br/>Und nehm durch Christus meine Kron.<br/>',NULL,194859,5);
INSERT INTO stanza VALUES('G2051','1','Ja, meine Hoffnung ruht allzeit<br/>Auf Christus, der Gerechtigkeit;<br/>Wenn alles andre auch zerstäubt,<br/>Der Name Jesu dennoch bleibt.<br/>',NULL,194860,1);
INSERT INTO stanza VALUES('G2051','chorus','Wer Christus, diesem Fels, vertraut,<br/>Der hat auf keinen Sand gebaut,<br/>Der hat auf keinen Sand gebaut.<br/>',NULL,194861,2);
INSERT INTO stanza VALUES('G2051','2','Ist auch verhüllt Sein Angesicht,<br/>Doch Christi Gnade wanket nicht;<br/>Wenn auch der Sturmwind um mich bläst,<br/>Der Fels hält meinen Anker fest.<br/>',NULL,194862,3);
INSERT INTO stanza VALUES('G2051','3','Sein Eid, Sein Bund, Sein teures Blut<br/>Beschützen mich zur Zeit der Flut;<br/>Wenn alles ringsum untergeht,<br/>Christus, der ew''ge Fels besteht.<br/>',NULL,194863,4);
INSERT INTO stanza VALUES('G2051','4','Bricht mit Posaunenton Er ein,<br/>Oh, dann möcht ich gefunden sein<br/>In Ihm, meiner Gerechtigkeit,<br/>Vor Seinem Thron zu stehn, befreit.<br/>',NULL,194864,5);
INSERT INTO stanza VALUES('G2052','1','In tiefem Kerker, hoffnungslos, bang,<br/>Wir wollten glauben, was nicht gelang;<br/>Gott leuchtet in uns, Jesus erscheint uns,<br/>Gott flößt Sich uns ein!<br/>Gott flößt Sich uns ein!<br/>',NULL,194865,1);
INSERT INTO stanza VALUES('G2052','chorus','Jesus versöhnte uns durch Sein Blut,<br/>Hat uns erlöst, erkauft, oh, wie gut!<br/>Keine Verdammung, Rechtfertigung nun!<br/>Jetzt herrscht Frieden mit Gott!<br/>Jetzt herrscht Frieden mit Gott!<br/>',NULL,194866,2);
INSERT INTO stanza VALUES('G2052','2','Sterben in Adam war unser Los;<br/>In Sünden krank und ganz hoffnungslos.<br/>Doch Gott im Sohn kam, Adam ganz wegnahm;<br/>Er ist tot, wir sind frei!<br/>Er ist tot, wir sind frei!<br/>',NULL,194867,3);
INSERT INTO stanza VALUES('G2052','3','Freude und Gnade fülln unser Sein,<br/>O Halleluja! Von Sünden rein!<br/>Gott kann nun fließen und in uns sprießen<br/>Durch Sein Leben in uns!<br/>Durch Sein Leben in uns!<br/>',NULL,194868,4);
INSERT INTO stanza VALUES('G2053','1','Erlöst -- Oh, wie gern ich''s verkünde!<br/>Das Blut des Lamms hat mich erlöst;<br/>Vollkommen erlöst durch Erbarmen,<br/>Auf ewig Sein Kind bin ich jetzt.<br/>',NULL,194869,1);
INSERT INTO stanza VALUES('G2053','chorus','Erlöst, erlöst,<br/>Des Lammes Blut hat mich erlöst;<br/>Erlöst, erlöst,<br/>Auf ewig Sein Kind bin ich jetzt.<br/>',NULL,194870,2);
INSERT INTO stanza VALUES('G2053','2','Erlöst und so glücklich in Jesus,<br/>Entzückung, die Sprache verschlägt;<br/>Das Licht Seiner Gegenwart, weiß ich,<br/>Bleibt immer bei mir und mich hegt.<br/>',NULL,194871,3);
INSERT INTO stanza VALUES('G2053','3','Ich denke an meinen Erlöser,<br/>An Ihn nur den ganzen Tag lang;<br/>Ich singe, ich kann ja nicht schweigen,<br/>Mach aus Seiner Liebe Gesang.<br/>',NULL,194872,4);
INSERT INTO stanza VALUES('G2053','4','Bald werde ich sehen in Schönheit<br/>Den König, nach dem es mich tracht''t,<br/>Der stets meine Schritte behütet<br/>Und Lieder mir gibt in der Nacht.<br/>',NULL,194873,5);
INSERT INTO stanza VALUES('G2054','1','Dort, wo am Kreuz einst mein Retter starb,<br/>Gottes Gerechtigkeit ich erwarb,<br/>Dort wusch Sein Blut meine Sünden ab,<br/>Ehre sei dem Herrn!<br/>',NULL,194874,1);
INSERT INTO stanza VALUES('G2054','chorus','Ehre sei dem Herrn!<br/>Ehre sei dem Herrn!<br/>Dort wusch Sein Blut meine Sünden ab,<br/>Ehre sei dem Herrn!<br/>',NULL,194875,2);
INSERT INTO stanza VALUES('G2054','2','Frei von der Sünde am Brunnen hier,<br/>Unsre Erlösung genießen wir.<br/>Ewig genieß sie und jubilier!<br/>Ehre sei dem Herrn!<br/>',NULL,194876,3);
INSERT INTO stanza VALUES('G2054','3','Ja, diese Tatsache gibt mir Halt:<br/>Nicht nur die Sündenschuld ist bezahlt,<br/>Sein Lebensquell mir entgegenwallt,<br/>Ehre sei dem Herrn!<br/>',NULL,194877,4);
INSERT INTO stanza VALUES('G2054','chorus','Ehre sei dem Herrn!<br/>Ehre sei dem Herrn!<br/>Sein Lebensquell mir entgegenwallt,<br/>Ehre sei dem Herrn!<br/>',NULL,194878,5);
INSERT INTO stanza VALUES('G2054','4','Beides, erlöst und erquickt, sind wir,<br/>Dein Blut uns wusch, ja, wir bleiben hier;<br/>Trinken Dein Leben und danken Dir,<br/>Ehre sei dem Herrn!<br/>',NULL,194879,6);
INSERT INTO stanza VALUES('G2055','1','Welche Gewissheit, Jesus ist mein!<br/>Welch Herrlichkeit, ich bin ewiglich Sein!<br/>Von Gott erkauft, welch Rettung, so gut!<br/>Vom Geist geboren, rein durch Sein Blut.<br/>',NULL,194880,1);
INSERT INTO stanza VALUES('G2055','chorus','Dies ist mein Zeugnis und mein Gesang,<br/>Ich preise Jesus mein Leben lang.<br/>Dies ist mein Zeugnis und mein Gesang,<br/>Ich preise Jesus mein Leben lang.<br/>',NULL,194881,2);
INSERT INTO stanza VALUES('G2055','2','Bin ganz ergeben und voller Freud,<br/>Meine Vision ist Entrückung schon heut;<br/>Auf meinen Pfad streust Du allezeit<br/>Liebe und große Barmherzigkeit.<br/>',NULL,194882,3);
INSERT INTO stanza VALUES('G2055','3','Bin ganz ergeben, Ruhe zieht ein,<br/>Ich bin so fröhlich, gesegnet zu sein;<br/>Wachend und betend schau ich zu Dir,<br/>In Deiner Liebe mich ganz verlier.<br/>',NULL,194883,4);
INSERT INTO stanza VALUES('G2056','1','Wunderbar, Gottes Leben veränderte mich,<br/>Seit Jesus in mein Herz einzog!<br/>Meine Seele hat Licht und ist ganz außer sich,<br/>Seit Jesus in mein Herz einzog!<br/>',NULL,194884,1);
INSERT INTO stanza VALUES('G2056','chorus','Seit Jesus in mein Herz einzog!<br/>Seit Jesus in mein Herz einzog!<br/>Freude zog in mich ein und durchflutet mein Sein,<br/>Seit Jesus in mein Herz einzog!<br/>',NULL,194885,2);
INSERT INTO stanza VALUES('G2056','2','All mein Wandern und Suchen ist endlich vorbei,<br/>Seit Jesus in mein Herz einzog!<br/>Er wusch ab meine Sünden und machte mich frei,<br/>Seit Jesus in mein Herz einzog!<br/>',NULL,194886,3);
INSERT INTO stanza VALUES('G2056','3','Mich erfüllt eine Hoffnung, die felsenfest steht,<br/>Seit Jesus in mein Herz einzog!<br/>Auf dem Weg jede Wolke des Zweifels vergeht,<br/>Seit Jesus in mein Herz einzog!<br/>',NULL,194887,4);
INSERT INTO stanza VALUES('G2056','4','Auf dem Weg durch das Todestal scheint mir ein Licht,<br/>Seit Jesus in mein Herz einzog!<br/>Und danach sind die Tore der Stadt schon in Sicht,<br/>Seit Jesus in mein Herz einzog!<br/>',NULL,194888,5);
INSERT INTO stanza VALUES('G2056','5','In die Stadt werd ich gehen und wohnen darin,<br/>Seit Jesus in mein Herz einzog!<br/>Ich bin glücklich und lauf auf dem Weg froh dorthin,<br/>Seit Jesus in mein Herz einzog!<br/>',NULL,194889,6);
INSERT INTO stanza VALUES('G2057','1','Ich war in Sündenketten gebunden,<br/>Kämpfte vergeblich in Sklaverei;<br/>Herrliche Freiheit hab ich empfangen,<br/>Als Jesus brach die Ketten entzwei.<br/>',NULL,194890,1);
INSERT INTO stanza VALUES('G2057','chorus','Herrliche Freiheit, wirkliche Freiheit,<br/>Denn Sündenketten plagen nicht mehr!<br/>Jesus, mein wunderbarer Befreier,<br/>Jetzt und für immer ist Er mein Herr.<br/>',NULL,194891,2);
INSERT INTO stanza VALUES('G2057','2','Freiheit von jeder fleischlichen Neigung,<br/>Freiheit von Neid, von Hass und von Streit;<br/>Freiheit von eitlem, weltlichem Ehrgeiz,<br/>Freiheit von Gram und Trostlosigkeit.<br/>',NULL,194892,3);
INSERT INTO stanza VALUES('G2057','3','Freiheit von Stolz und sündiger Torheit,<br/>Freiheit von aller Liebe zum Geld;<br/>Freiheit von schlechter Laune und Ärger,<br/>Herrlich, entrückt zu sein von der Welt.<br/>',NULL,194893,4);
INSERT INTO stanza VALUES('G2057','4','Freiheit von Angst mit all ihren Qualen,<br/>Freiheit von Sorgen, Leid und Geschrei;<br/>Freiheit in Christus, meinem Erlöser,<br/>Er brach die Sklavenketten entzwei.<br/>',NULL,194894,5);
INSERT INTO stanza VALUES('G2058','1','Mein Retter, Du bist mein,<br/>Wie süß ist mir doch dies!<br/>Ich rufe Deinen Nam''n,<br/>Erheb mein Herz zu Dir!<br/>',NULL,194895,1);
INSERT INTO stanza VALUES('G2058','chorus','Mein! Mein! Mein!<br/>Ich weiß, Du bist mein;<br/>Retter, o Retter,<br/>Ich weiß, Du bist mein.<br/>',NULL,194896,2);
INSERT INTO stanza VALUES('G2058','2','Du bist des Sünders Freund,<br/>Ich nehm die Freundschaft an;<br/>Gerettet durch die Gnad,<br/>Als Deine Botschaft kam.<br/>',NULL,194897,3);
INSERT INTO stanza VALUES('G2058','3','Mein hartes Herz, gerührt,<br/>Hat Deiner Stimm gehorcht;<br/>Und Friede kam herein<br/>Und Freude durch Dein Wort.<br/>',NULL,194898,4);
INSERT INTO stanza VALUES('G2058','4','So singe ich Dein Lob,<br/>So nenn ich Dich nun mein;<br/>Ich baue auf Dein Wort,<br/>Ich weiß, ja, ich bin Dein.<br/>',NULL,194899,5);
INSERT INTO stanza VALUES('G2059','1','Komm, Du Quelle jedes Segens,<br/>Stimm mein Herz auf Lobgesang!<br/>Gnadenströme, voll Erbarmen,<br/>Fordern Jubel laut und lang!<br/>Jesus suchte mich als Fremden,<br/>Als ich irrte weit von Gott;<br/>Meine Seelennot zu wenden,<br/>Schritt Er ein mit Seinem Blut.<br/>',NULL,194900,1);
INSERT INTO stanza VALUES('G2059','2','O wie viel der Gnade schuld ich,<br/>Wie sie täglich drängt mich sehr!<br/>Band der Gnade, nun umschling mich,<br/>Dass mein Herz nicht strauchle mehr!<br/>Lehr mich, Herr, ein Maß Entzückung,<br/>Das mich Gnad beweisen lässt!<br/>Schätze, über all Erzählung,<br/>Deiner Liebe sing ich jetzt.<br/>',NULL,194901,2);
INSERT INTO stanza VALUES('G2059','3','Öfters schweif ich, Herr; ich fühl es,<br/>Bin oft meinem Gott nicht treu;<br/>Nimm mein Herz, o nimm, versiegle''s<br/>Mit dem Geist von oben neu!<br/>Nun befreit von Not und Sünde,<br/>Durch des Retters Blut erwirkt,<br/>Mög ich wandeln als ein Fremder,<br/>Sohn und Erbe Gottes hier.<br/>',NULL,194902,3);
INSERT INTO stanza VALUES('G2060','1','Ich bin glücklich hier,<br/>Vater, nun mit Dir,<br/>Einst verlorn, bin ich jetzt nah!<br/>(Es war) erst Sein Lächeln warm,<br/>Die Umarmung dann.<br/>Hat mich mit Gnade überrascht.<br/>',NULL,194903,1);
INSERT INTO stanza VALUES('G2060','chorus','Einst verlorn, doch jetzt wieder nah!<br/>Ich war tot, doch jetzt leb- lebe ich!<br/>Kommt und jubelt mit und seid fröhlich heut,<br/>Zurück im Vaterhaus zu sein!<br/>',NULL,194904,2);
INSERT INTO stanza VALUES('G2060','2','Ring, Schuh, Mantel her --<br/>Und kein Hunger mehr!<br/>Dort, wo ich nun hingehör!<br/>(Weil Er mich) eingekleidet hat,<br/>(Dann erneut) aufgenommen hat.<br/>(Ich bin) in der Familie nun zurück.<br/>',NULL,194905,3);
INSERT INTO stanza VALUES('G2061','1','Jahrelang vergeblich sucht'' ich einen Quell,<br/>Der für ewig fließt und quillt;<br/>Was die Welt mir bot, das hat mich nie erfüllt,<br/>Nichts hat meinen Durst gestillt.<br/>',NULL,194906,1);
INSERT INTO stanza VALUES('G2061','chorus','Trinke von dem Brunnen, der niemals versiegt,<br/>Trinke von dem Brunnen, der Leben gibt;<br/>Freude und Vergnügen<br/>Schmeck in vollen Zügen,<br/>Wenn ich trink vom Quell, der Leben gibt.<br/>',NULL,194907,2);
INSERT INTO stanza VALUES('G2061','2','In der Sündenwüste wandre ich nicht mehr,<br/>Denn ich fand den Lebensquell,<br/>Und mein Kelch der Freude überfließt nun sehr,<br/>Jesus thront in meiner Seel!<br/>',NULL,194908,3);
INSERT INTO stanza VALUES('G2061','3','Hier gibt Er mir Tag für Tag Zufriedenheit,<br/>Seinen Frieden, Seine Ruh;<br/>Hier schenkt Er mir Seinen Trost zu jeder Zeit,<br/>Voller Segen immerzu.<br/>',NULL,194909,4);
INSERT INTO stanza VALUES('G2061','4','Hier stellt Er mir Seinen Reichtum stets bereit,<br/>Mich erfrischt auf meinem Pfad;<br/>Ja, zum Quell der Heilung flieh ich allezeit,<br/>Meine matte Seele bad.<br/>',NULL,194910,5);
INSERT INTO stanza VALUES('G2062','1','Es war noch früh. Die Nacht war noch nicht vorbei.<br/>''s war mein Fehler, da zu sein.<br/>Sie platzten rein, unser Verbrechen wurde zur Schau gestellt.<br/>Sie sagten, dass ich laut Gesetz sterben sollt.<br/>Ich war wie betäubt vor Angst.<br/>Dieser Mann hat alles verändert.<br/>Ohne Verurteilung sprach Er mit mir.<br/>Obwohl ich hätte sterben sollen,<br/>Zwang Er die Ankläger wegzugehen.<br/>',NULL,194911,1);
INSERT INTO stanza VALUES('G2062','2','Den Durst in mir zu stillen, hab ich versucht,<br/>Doch nichts war jemals genug.<br/>Die Ehen warn eine Enttäuschung. Die Leere nimmt nur noch zu.<br/>Egal was, verzehrenden Durst hab ich noch.<br/>Im Herzen ein tiefes Loch.<br/>Dieser Mann hat alles verändert.<br/>Er gab das Wasser, das allen Durst stillt.<br/>Obwohl Er meinen Fall gut kannte,<br/>Bat Er mich, Sein Wasser nun zu nehmen.<br/>',NULL,194912,2);
INSERT INTO stanza VALUES('G2062','3','Ich war unheilbar krank. Die Hoffnung vorbei.<br/>Es gab keine Heilung mehr.<br/>Geld gab ich aus bis zur Verzweiflung. Ein Wunder wollt ich so sehr.<br/>Die Heilmittel waren vergeblich, umsonst.<br/>Die Zukunft sah düster aus.<br/>Dieser Mann hat alles verändert.<br/>Ich rührt Ihn an, wurd dann völlig geheilt.<br/>Obwohl es andere mir versprachen,<br/>Hat es ja nun dieser Mann getan!<br/>',NULL,194913,3);
INSERT INTO stanza VALUES('G2062','4','Die ganze Woche haben wir schon gefeiert.<br/>Das Fest war schon fast vorbei.<br/>Wie kann es sein, dass ich so feiere, doch durstig und hungrig bleib?<br/>Vergnügen ist flüchtig und Freude vergeht,<br/>Wo Leere stets noch verweilt.<br/>Dieser Mann hat alles verändert.<br/>Er sagte: „Komm her, wenn du durstig bist!"<br/>Obwohl wir es nicht glauben konnten,<br/>Gab Er uns Wasser der Ewigkeit.<br/>',NULL,194914,4);
INSERT INTO stanza VALUES('G2062','5','Wer ist der Mann, der solche Dinge tun kann?<br/>Er liebt die Bedürftigen.<br/>Suchende, Sünder und Kranke: Er fand sie dort, wo sie warn.<br/>Barmherzigkeit, Mitleid für jeden hat Er<br/>Und Liebe tief wie das Meer.<br/>Dieser Mann ist mein Retter -- Jesus!<br/>Hat mich gefunden, gefüllt und geheilt!<br/>Während ich Frieden suchte, fand Er mich,<br/>Stellt'' mich zufrieden und ließ mich frei.<br/>... nun endlich fand ich Zufriedenheit.<br/>',NULL,194915,5);
INSERT INTO stanza VALUES('G2062','SoundCloud Link','https://soundcloud.com/liederstroeme/es-war-noch-frueh',NULL,194916,6);
INSERT INTO stanza VALUES('G2063','1','Kühlen Trank aus einem Brunnen<br/>Hatt'' ich lebenslang begehrt,<br/>Der den Durst doch löschen sollte,<br/>Der mich innerlich verzehrt.<br/>',NULL,194917,1);
INSERT INTO stanza VALUES('G2063','chorus','Ja, ich habe Ihn gefunden,<br/>Nach dem suchte meine Seel!<br/>Jesus stillt all meine Sehnsucht<br/>Und Sein Leben bringt mir Heil.<br/>',NULL,194918,2);
INSERT INTO stanza VALUES('G2063','2','Ich ernährte mich von Hülsen,<br/>Bis die Kraft mir beinah schwand,<br/>Meine Seele suchte Bess''res,<br/>Jedoch Hunger nur empfand.<br/>',NULL,194919,3);
INSERT INTO stanza VALUES('G2063','3','Ich war arm und suchte Reichtum,<br/>Dachte Friede wär mein Lohn,<br/>Doch der Staub, den ich gesammelt,<br/>Lachte meinem Klagen Hohn.<br/>',NULL,194920,4);
INSERT INTO stanza VALUES('G2063','4','Quell des Wassers immer sprudelnd,<br/>Brot des Lebens nährt mich hier;<br/>Reichtum, welcher nimmer ausgeht,<br/>So viel ist mein Retter mir.<br/>',NULL,194921,5);
INSERT INTO stanza VALUES('G2064','1','Lobt Gott, denn Christus lebt in uns,<br/>Gott uns so reich errettet;<br/>Durch Gottes Leben rettet Er,<br/>Uns nicht an Regeln kettet;<br/>Allein hab ich es nicht geschafft,<br/>Sein Leben ändert mich voll Kraft:<br/>Nur Gottes Leben kann es.<br/>',NULL,194922,1);
INSERT INTO stanza VALUES('G2064','2','Er rettet bis zum Äußersten,<br/>Will Lebenskraft uns geben;<br/>Er teilt Sich aus in uns hinein,<br/>Will uns aus Tod erheben.<br/>Verlorne rettet, nimmt Er ein,<br/>Befreit von mehr als Sünd allein:<br/>In Herrlichkeit Er bringt uns!<br/>',NULL,194923,2);
INSERT INTO stanza VALUES('G2064','3','Zum Priester wurde Er bestimmt,<br/>Um Leben zu verleihen;<br/>Leben ist die Natur von Ihm,<br/>Der kann vom Selbst befreien:<br/>Sein Leben kein Verderben kennt,<br/>Uns voll errettet bis zum End:<br/>Nur Er vermag zu retten!<br/>',NULL,194924,3);
INSERT INTO stanza VALUES('G2064','4','Sein Leben ist qualifiziert,<br/>In Herrlichkeit zu bringen;<br/>Nur Sein geprüftes Leben kann<br/>Rettung für uns erringen;<br/>Bis hin zum Kreuz stand Christus fest,<br/>Hat Sich bewährt in jedem Test:<br/>Er ging durch Tod und Hades.<br/>',NULL,194925,4);
INSERT INTO stanza VALUES('G2064','5','Er bürgt nun sicher unser Heil,<br/>Sein Leben wirkt beständig;<br/>Was Er bewirkt und arrangiert,<br/>Dient uns, macht uns vollständig.<br/>Das eigne Leben steht nicht fest,<br/>Sein Leben nur besteht den Test:<br/>Er rettet uns vollkommen!<br/>',NULL,194926,5);
INSERT INTO stanza VALUES('G2064','6','Er lebt, um für uns einzustehn,<br/>Er lebt auf Ewigkeiten;<br/>Sein Priestertum kann nie vergehn,<br/>Es währt durch alle Zeiten.<br/>Er tritt stets ein, dient dir und mir,<br/>Den Hohen Priester brauchen wir:<br/>Hoch über allen Himmeln.<br/>',NULL,194927,6);
INSERT INTO stanza VALUES('G2064','7','Tretet durch Ihn zu Gott hinzu,<br/>Weicht nicht! Das bringt Verderben;<br/>Sein Leben doch in Anspruch nehmt!<br/>Als Glieder funktionieren.<br/>Kommt vorwärts, nehmt Sein Leben ein,<br/>Wir werden Gottes Volk dann sein,<br/>So wird der Tod verschlungen.<br/>',NULL,194928,7);
INSERT INTO stanza VALUES('G2065','1','Welch fest''s Fundament uns zum Glauben gelegt,<br/>Sich, ihr Heiligen, in Seinem Wort niederschlägt!<br/>Was mehr kann Er dann sagen, dass Er nicht gesagt,<br/>Zu euch, die ihr um Zuflucht in Jesus euch bargt?<br/>',NULL,194929,1);
INSERT INTO stanza VALUES('G2065','2','„Fürchte nicht, Ich bin bei dir, verängstigt nicht sei,<br/>Denn Ich bin noch dein Gott und Ich stehe dir bei!<br/>Ich beschütze und stärk dich, verleihe dir Stand,<br/>Heil in Meiner gerechten, allmächtigen Hand."<br/>',NULL,194930,2);
INSERT INTO stanza VALUES('G2065','3','„Wenn Ich dich dann berufe, durch Tiefen zu gehn,<br/>Sollen Ströme der Trauer nicht über dir stehn;<br/>Denn Ich segne dich, wenn dich Bedrängnis bedroht,<br/>Und Ich heilige dir deine bitterste Not."<br/>',NULL,194931,3);
INSERT INTO stanza VALUES('G2065','4','„Wenn durch Proben von Feuer dich leitet dein Pfad,<br/>Werde Ich dich versorgen anhand Meiner Gnad;<br/>Denn die Flamme verletzt nicht, nur dies Mein Begehr:<br/>Dass dein Gold werd geläutert, dein Unrat verzehrt."<br/>',NULL,194932,4);
INSERT INTO stanza VALUES('G2065','5','„Immer noch soll Mein Volk, auch wenn schon hoch betagt,<br/>Prüfen, wie Meine Liebe, so fest, nie versagt;<br/>Und wenn weißes Haar ihnen die Schläfen verziert,<br/>Trag Ich sie im Schoß noch wie die Lämmer der Hirt."<br/>',NULL,194933,5);
INSERT INTO stanza VALUES('G2065','6','„Und die Seel, die um Ruhe an Jesus sich wend''t,<br/>Überlasse Ich niemals, nein, nie ihrem Feind;<br/>Will die Hölle die Seele erschüttern auch schwer,<br/>So verlass Ich sie nimmer, o nein, nimmermehr."<br/>',NULL,194934,6);
INSERT INTO stanza VALUES('G2066','1','Mein Ziel ist Gott, nicht Friede oder Freud,<br/>Nicht einmal Segen, sondern Gott allein;<br/>Nicht ich, doch Gott Selbst führt mich hin zum Ziel.<br/>Er weist den Weg, mag er auch schwierig sein.<br/>',NULL,194935,1);
INSERT INTO stanza VALUES('G2066','2','Der Glaube eilt zu seinem Ziel in Gott<br/>Und Liebe schaut zum Herrn, der treu hinführt;<br/>In Seiner Hand folgt meine Seele fest,<br/>Bis Gott mein tiefstes Flehen ganz erhört.<br/>',NULL,194936,2);
INSERT INTO stanza VALUES('G2066','3','Wenn auch der Weg durch dunkle Täler führt,<br/>Wenn ich auch einen hohen Preis bezahl,<br/>Er weiß genau, wie ich das Ziel erreich.<br/>Der Weg, der zu Ihm führt ist immer schmal.<br/>',NULL,194937,3);
INSERT INTO stanza VALUES('G2066','4','Ich weiß nur eins -- ich sage Ihm nicht ab;<br/>Ich tu nur eins -- ich jage hin zum Herrn;<br/>Gott -- meine Herrlichkeit hier Tag für Tag<br/>Und dort in Herrlichkeit mein großer Lohn.<br/>',NULL,194938,4);
INSERT INTO stanza VALUES('G2067','1','Ich brauch Dich, Jesus,<br/>Täglich immer mehr.<br/>Ich kann ohne Dich nicht<br/>Mehr leben, mein Herr!<br/>',NULL,194939,1);
INSERT INTO stanza VALUES('G2067','chorus','Ich brauch Dich, Herr,<br/>Jeden Tag immer mehr.<br/>Ohne Dich geht es nicht.<br/>Du so wunderbar bist!<br/>',NULL,194940,2);
INSERT INTO stanza VALUES('G2067','2','Lieblicher Bräutigam,<br/>Der Angenehmste bist!<br/>Bring in Deine Kammern,<br/>Erfrisch mich mit Lieb!<br/>',NULL,194941,3);
INSERT INTO stanza VALUES('G2067','chorus','Ich brauch Dich, Herr,<br/>Jeden Tag immer mehr.<br/>Ohne Dich geht es nicht,<br/>Lieblicher Bräutigam.<br/>',NULL,194942,4);
INSERT INTO stanza VALUES('G2067','3','Küss mich, Herr Jesus,<br/>Mit Küssen Deines Munds!<br/>Gnade Deiner Lippen,<br/>Sie schmeckt mir so süß.<br/>',NULL,194943,5);
INSERT INTO stanza VALUES('G2067','chorus','Ich brauch Dich, Herr,<br/>Jeden Tag immer mehr.<br/>Ohne Dich geht es nicht.<br/>Deine Süße brauch ich.<br/>',NULL,194944,6);
INSERT INTO stanza VALUES('G2067','4','Ich bin krank vor Liebe,<br/>Dein Banner über mir ist Lieb.<br/>Hast mein Herz erobert,<br/>Kein andrer für mich.<br/>',NULL,194945,7);
INSERT INTO stanza VALUES('G2067','chorus','Ich brauch Dich, Herr,<br/>Jeden Tag immer mehr.<br/>Ohne Dich geht es nicht.<br/>Bin erobert von Dir.<br/>',NULL,194946,8);
INSERT INTO stanza VALUES('G2067','5','Ich lieb meinen Meister,<br/>Will nicht frei ausgehn.<br/>Bringe mich zur Türe,<br/>Durchbohre mein Ohr!<br/>',NULL,194947,9);
INSERT INTO stanza VALUES('G2067','chorus','Ich brauch Dich, Herr,<br/>Jeden Tag immer mehr.<br/>Ohne Dich geht es nicht.<br/>Du so wunderbar bist!<br/>',NULL,194948,10);
INSERT INTO stanza VALUES('G2067','6','Mach schnell, Geliebter,<br/>Komme bald zurück!<br/>Jesus, unser Liebster,<br/>Deine Braut ruft nach Dir.<br/>',NULL,194949,11);
INSERT INTO stanza VALUES('G2067','chorus','Komm schnell, Herr Jesus,<br/>Schon so lang warten wir.<br/>Bitte eile, Geliebter,<br/>Deine Braut ruft nach Dir!<br/>Komme doch schnell, Amen!<br/>',NULL,194950,12);
INSERT INTO stanza VALUES('G2068','1','Auf den Berg, o Retter, führ mich,<br/>Wo wir sehen Dich allein,<br/>Wo wir hörn die Himmelsstimme,<br/>Wo die Luft ist klar und rein!<br/>',NULL,194951,1);
INSERT INTO stanza VALUES('G2068','chorus','Führ mich höher auf den Berg, Herr,<br/>Schenk Gemeinschaft, Herr, mir Dir!<br/>Dort im Licht seh ich den Brunnen,<br/>Und das Blut, es reinigt mich.<br/>',NULL,194952,2);
INSERT INTO stanza VALUES('G2068','2','Höher rauf, wo Licht noch zunimmt,<br/>Über allem Zank und Streit,<br/>Wo im Leben frei wir herrschen,<br/>Alle Mühen sind vorbei.<br/>',NULL,194953,3);
INSERT INTO stanza VALUES('G2068','3','Retter, halt mich auf dem Berge,<br/>Bring mich noch ans Ziel heran,<br/>Bis Dein Bild wir alle teilen,<br/>Deine Gnade preisen an!<br/>',NULL,194954,4);
INSERT INTO stanza VALUES('G2069','1','Ziehe mich, Herr!<br/>Ziehe mich heut<br/>Von allem, Herr, außer Dir<br/>Ziehe mich weg!<br/>',NULL,194955,1);
INSERT INTO stanza VALUES('G2069','2','Auch wenn mich die ganze Welt<br/>Niederzudrücken scheint.<br/>So viel Sorgen, Sünd und Kampf<br/>In mir und ringsumher.<br/>',NULL,194956,2);
INSERT INTO stanza VALUES('G2069','3','Doch, Herr, ich setz mein Herz auf Dich<br/>Und, Herr, ich bleibe nur bei Dir.<br/>Denn nur, wenn Du mir nahe bist,<br/>Ist wirklich alles gut.<br/>',NULL,194957,3);
INSERT INTO stanza VALUES('G2069','4','Und ob alles auseinanderbricht,<br/>Ob alles läuft wie geplant,<br/>Es spielt doch keine Rolle, Herr,<br/>Solang ich Dich gewinne heut.<br/>',NULL,194958,4);
INSERT INTO stanza VALUES('G2070','1','Herr Jesus Christus, wachs in mir,<br/>Bis alles andre weicht!<br/>Zieh mein Herz täglich näher Dir!<br/>Von Sünde frei und leicht.<br/>',NULL,194959,1);
INSERT INTO stanza VALUES('G2070','chorus','Lass Deine Macht die Schwachheit mir<br/>Umfangen täglich neu!<br/>Mein Tod im Leben schwinde schier,<br/>Mein Dunkel Dein Licht zerstreu!<br/>',NULL,194960,2);
INSERT INTO stanza VALUES('G2070','2','In Deinem hellen Strahlenschein<br/>Muss böses Denken gehn.<br/>Dass ich soll nichts, Du alles sein,<br/>Dies lehr mich doch zu sehn.<br/>',NULL,194961,3);
INSERT INTO stanza VALUES('G2070','3','Du Weiser, Treuer, zeig mir mehr<br/>Von Deiner Herrlichkeit!<br/>Ich wäre gern Dein Ausdruck hier<br/>In Freude und in Leid.<br/>',NULL,194962,4);
INSERT INTO stanza VALUES('G2070','4','Füll mich mit Freud von oben her,<br/>Stütz mich mit Deiner Kraft,<br/>Bis Deine große Liebe, Herr,<br/>Durch mich sich Bahnen schafft!<br/>',NULL,194963,5);
INSERT INTO stanza VALUES('G2070','5','Wirk, dass mein armes Selbst nimmt ab,<br/>Mögst Du mein Ziel nur sein!<br/>Schenk, dass ich täglich Gnade hab<br/>Zu leben Dir allein!<br/>',NULL,194964,6);
INSERT INTO stanza VALUES('G2071','1','Ich geh hinauf zu Christus hin,<br/>Mehr Höhe jeden Tag gewinn;<br/>Nur ein Gebet füllt meinen Mund:<br/>„Pflanz meinen Fuß auf höhren Grund!"<br/>',NULL,194965,1);
INSERT INTO stanza VALUES('G2071','chorus','Herr, heb mich auf und lass mich stehn,<br/>Im Glauben lass mich Kana''n sehn!<br/>Ja, richt mich auf zu jeder Stund,<br/>„Pflanz meinen Fuß auf höhren Grund!"<br/>',NULL,194966,2);
INSERT INTO stanza VALUES('G2071','2','Mein Herz hat keinen Wunsch zu sein,<br/>Wo Angst und Zweifel dringen ein;<br/>Dort länger weiln ist nicht gesund,<br/>Ich bete für den höhren Grund.<br/>',NULL,194967,3);
INSERT INTO stanza VALUES('G2071','3','Leben will ich, über der Welt<br/>Auch wenn der Böse Tücken stellt,<br/>Denn Glaube tut mit Freuden kund<br/>Der Heil''gen Lied auf höhrem Grund.<br/>',NULL,194968,4);
INSERT INTO stanza VALUES('G2071','4','Ich will erklimm''n die Höhen licht,<br/>Wo Herrlichkeit erfüllt die Sicht;<br/>Ich bete noch, bis dies gefund''n:<br/>„Herr, führe mich auf höhren Grund!"<br/>',NULL,194969,5);
INSERT INTO stanza VALUES('G2072','1','Ihm, der hat, noch mehr bescherest,<br/>Überfließend mehr schenkst Du;<br/>Herr, ich lebe, weil Du lebest,<br/>Drum sprich mir mehr Leben zu!<br/>Herr, bestärke mich im Lauf!<br/>So in Gnade wachs ich auf.<br/>Herr, bestärke mich im Lauf!<br/>So in Gnade wachs ich auf.<br/>',NULL,194970,1);
INSERT INTO stanza VALUES('G2072','2','Stärke all Dein Werk, o Meister,<br/>Schlagen Wurzeln tief und fest;<br/>Bring die Früchte bloß zur Reife,<br/>Die Du mir gedeihen lässt!<br/>//Schneide wildes Selbst bloß weg,<br/>Lass mich wachsen unentwegt!//<br/>',NULL,194971,2);
INSERT INTO stanza VALUES('G2072','3','Lass die Sonne Wachstum stärken,<br/>Schenke Regen, frisch und reich!<br/>Jede Stunde soll verzeichnen:<br/>Wirklich machst Du mich Dir gleich,<br/>//Dass Dein liebend Auge fass,<br/>Wie in Gnad ich täglich wachs.//<br/>',NULL,194972,3);
INSERT INTO stanza VALUES('G2072','4','Gnade Deiner Füll entströmend,<br/>Führ mir Größeres noch vor!<br/>Adlerflügel mir verleihend,<br/>Lass mich steigen hoch empor!<br/>//Durch Dein leuchtend Angesicht<br/>In der Gnade wachse ich.//<br/>',NULL,194973,4);
INSERT INTO stanza VALUES('G2072','5','Deshalb lass mich ständig wachsen,<br/>Stehen nimmer, nimmer still,<br/>Hören, besser kennenlernen<br/>Dich und Dein''n vollkomm''nen Willn!<br/>//Bis ich geh den Siegerpfad,<br/>Lass mich wachsen in der Gnad!//<br/>',NULL,194974,5);
INSERT INTO stanza VALUES('G2073','chorus','Mit Deiner Gnad versorg mich, Herr!<br/>Dein göttlich Leben wachse mehr!<br/>Ja, Stück für Stück und Tag für Tag wachs ich<br/>Immer mehr in Dich hinein.<br/>',NULL,194975,1);
INSERT INTO stanza VALUES('G2073','1','Tag für Tag, nach und nach, Leben wächst, wie es passt,<br/>Allmählich nimmt es zu, bis es dann<br/>-- Wenn es auch kaum zu merken ist --<br/>In mir zur vollen Reife kommt.<br/>',NULL,194976,2);
INSERT INTO stanza VALUES('G2073','2','Allezeit, unentwegt, bin ich, Herr, stets bewegt,<br/>Mit jedem Atemzug Dich zu leben,<br/>Weil ich weiß: während ich atme, dass<br/>Dein Leben mich durchdringen wird.<br/>',NULL,194977,3);
INSERT INTO stanza VALUES('G2073','3','Jeden Tag find ich Ruh, weil ich ja weiß, dass Du<br/>Mich versorgst mit dem, was ich brauche.<br/>Jesus tritt stets fürbittend ein<br/>Für mich, ein Glied des Leibes.<br/>',NULL,194978,4);
INSERT INTO stanza VALUES('G2073','chorus','Herr, schenk einen korp''rativen Blick,<br/>Sodass mein Wachstum und Gebet<br/>Stets Tag für Tag und Stück für Stück bewirkt<br/>Aufbau in Dich hinein!<br/>',NULL,194979,5);
INSERT INTO stanza VALUES('G2073','4','Korp''rativ lass uns sein, wachsen stets mehr hinein,<br/>Bis wir Deiner Fülle Maß erreichen!<br/>Wandle um und gestalt Dir gleich<br/>Dein offenbartes Volk, Herr!<br/>',NULL,194980,6);
INSERT INTO stanza VALUES('G2073','chorus','Mit Deiner Gnad versorg mich, Herr!<br/>Dein göttlich Leben wachse mehr!<br/>Ja, Stück für Stück und Tag für Tag wachs ich<br/>Immer mehr in Dich hinein.<br/>',NULL,194981,7);
INSERT INTO stanza VALUES('G2073','chorus','Herr, schenk einen korp''rativen Blick,<br/>Sodass mein Wachstum und Gebet<br/>Stets Tag für Tag und Stück für Stück bewirkt<br/>Aufbau in das Neue Jerusalem.<br/>',NULL,194982,8);
INSERT INTO stanza VALUES('G2074','1','Sei meine Vision, Herr! Mein Herz Dir gehört.<br/>Außer Dir ist mir nichts andres so wert.<br/>Leit mein'' Gedanken bei Tag und bei Nacht<br/>Du bist mein Licht, ob ich schlaf oder wach.<br/>',NULL,194983,1);
INSERT INTO stanza VALUES('G2074','2','Sei meine Weisheit, auch mein wahres Wort!<br/>Ich bin bei Dir, Du bei mir immerfort.<br/>Du bist mein Vater und ich bin Dein Sohn,<br/>Eins bin mit Dir, ja, und Du mit mir wohnst.<br/>',NULL,194984,2);
INSERT INTO stanza VALUES('G2074','3','Sei Du mein Schild und mein Schwert noch dazu!<br/>Auch meine Würde und Wonne seist Du!<br/>Schutz meiner Seele, Du mein hoher Turm<br/>Gen Himmel heb mich, berg mich vor dem Sturm!<br/>',NULL,194985,3);
INSERT INTO stanza VALUES('G2074','4','Achte kein''n Reichtum, noch leeren Lobpreis.<br/>Du bist mein Erbe, jetzt und allezeit.<br/>In meinem Herzen hast den ersten Platz<br/>König des Himmels, nur Du bist mein Schatz.<br/>',NULL,194986,4);
INSERT INTO stanza VALUES('G2074','5','König des Himmels, gewonnen mein Sieg,<br/>Sonne des Himmels, solch Freuden mir gibt.<br/>Herz meines Herzens, was immer geschieht,<br/>Meine Vision bleib, Du Herr, der regiert!<br/>',NULL,194987,5);
INSERT INTO stanza VALUES('G2075','1','Herr Jesus, zieh mich einen Schritt weiter!<br/>Zieh mich von hier, wo ich bin!<br/>Hier bin ich zu lang gewesen.<br/>Zieh mich, Herr, bring mich voran!<br/>',NULL,194988,1);
INSERT INTO stanza VALUES('G2075','2','Jesus, Dein Flüstern klingt so lieblich,<br/>Nun brennt es in meinem Herzen.<br/>Durch Deine Stille besiege mich!<br/>Dass Dein Gefühl ich erkenn.<br/>',NULL,194989,2);
INSERT INTO stanza VALUES('G2075','3','Leere Gedanken, unrein'' Gefühle<br/>Nimm von Verstand und Herz weg!<br/>Wasch mich im Wasser so klar wie Kristall<br/>Und füg mehr Leben hinzu!<br/>',NULL,194990,3);
INSERT INTO stanza VALUES('G2075','4','Alle die Dinge, die mein Sehn hindern --<br/>Selbstsucht und Stolz, Ambition --<br/>Mit Dein''m verstärkten Blick, o Herr,<br/>Entblöß und verbrenn sie nun!<br/>',NULL,194991,4);
INSERT INTO stanza VALUES('G2075','5','Vermehr das Maß an Herrlichkeit in mir!<br/>Herr, Dein Geist wandle mich um!<br/>Dass keins der Dinge vergeblich sei,<br/>Sondern mich rette noch mehr.<br/>',NULL,194992,5);
INSERT INTO stanza VALUES('G2075','6','Herr Jesus, oh, wie sehr ich Dich brauche!<br/>Danke, dass Du als der Leib<br/>Immer, Herr, gegenwärtig bist.<br/>Mög ich Dich dort suchen stets!<br/>',NULL,194993,6);
INSERT INTO stanza VALUES('G2076','1','Herr, ich lieb Dich; Herr, ich brauch Dich;<br/>Den ich brauche, Herr, bist Du.<br/>Für dieses Leben brauch ich Dich immer;<br/>Sei bei mir und führe mich!<br/>Herr, schau mich an, und<br/>Durchdringe mich, dass ich<br/>Wandle in Deiner Kraft!<br/>Herr, umarm mich<br/>Trag mich in Dir,<br/>Birg mich in Deiner Lieb!<br/>',NULL,194994,1);
INSERT INTO stanza VALUES('G2076','2','Und wenn ich schwach bin und komm nicht mehr weiter<br/>Meine Augen heb zu Dir;<br/>Sprich sanft zu mir, komm und unterwirf mich!<br/>Deine Stärke trägt mich durch.<br/>',NULL,194995,2);
INSERT INTO stanza VALUES('G2077','1','Lebe Du durch mich, Herr Jesus,<br/>Denn mein Leben bist nur Du!<br/>Ich nehm Dich für all Probleme<br/>Als die volle Lösung nun.<br/>Lebe Du durch mich, Herr Jesus!<br/>Stets Dein Wille soll geschehn.<br/>Mein Gefäß soll rein und klar sein,<br/>So wirst Du in mir gesehn.<br/>',NULL,194996,1);
INSERT INTO stanza VALUES('G2077','2','Herr, Dein Tempel ist geweiht Dir<br/>Und gereinigt, fleckenlos;<br/>Mög aus seinem Innern strahlen<br/>Herrlichkeit so grenzenlos.<br/>Lass die Erde staunend sehen,<br/>Dass mein Leib, Dir dargebracht,<br/>Ist gehorsam als Dein Sklave,<br/>Nur gestärkt durch Deine Macht.<br/>',NULL,194997,2);
INSERT INTO stanza VALUES('G2077','3','Alle Glieder, fest umgürtet,<br/>Dein Gebot stets nehmen an,<br/>Sei es unterm Joch der Arbeit<br/>Oder weggestellt nach Plan.<br/>Bin ich eingeschränkt beim Dienen,<br/>Nimmt mich keine Unruh ein.<br/>Unter Deiner treuen Leitung<br/>Will ich stets zufrieden sein.<br/>',NULL,194998,3);
INSERT INTO stanza VALUES('G2077','4','Voller Sanftmut und in Ruhe<br/>Eigne Wünsche abgelegt,<br/>Damit Du für mich kannst wählen,<br/>Wie Dein Finger zeigt den Weg.<br/>Lebe Du durch mich, Herr Jesus,<br/>Denn mein Leben bist nur Du!<br/>Ich nehm Dich für all Probleme<br/>Als die volle Lösung nun.<br/>',NULL,194999,4);
INSERT INTO stanza VALUES('G2078','1','Zeig mir Dein''n Weg, o Herr!<br/>Zeig mir Dein''n Weg!<br/>Dein''n gnädgen Rat gewähr!<br/>Zeig mir Dein''n Weg!<br/>Aufrecht zu gehen, hilf mir!<br/>Mehr durch Vertraun statt Sicht<br/>Leit mich mit himmlischem Licht!<br/>Zeig mir Dein''n Weg!<br/>',NULL,195000,1);
INSERT INTO stanza VALUES('G2078','2','Wenn Zweifel, Angst enstehn,<br/>Zeig mir Dein''n Weg!<br/>Wenn Stürme herbeiziehn,<br/>Zeig mir Dein''n Weg!<br/>Schein durch die Wolken des Sturms,<br/>Durch Mühe, Leid und Schmerz!<br/>Mach meinen Weg frei, Herr!<br/>Zeig mir Dein''n Weg!<br/>',NULL,195001,2);
INSERT INTO stanza VALUES('G2078','3','Solang ich lebe, Herr,<br/>Zeig mir Dein''n Weg!<br/>Wo auch mein Anteil sei,<br/>Zeig mir Dein''n Weg!<br/>Bis hin zum Wettlaufsziel,<br/>Bis ich die Reis'' beend,<br/>Bis die Kron'' gehört mir,<br/>Zeig mir Dein''n Weg!<br/>',NULL,195002,3);
INSERT INTO stanza VALUES('G2079','1','Oh, stärk meinen Geist jetzt, Herr Jesus,<br/>Oh, stärk meinen Geist in mir!<br/>Oh, stärk meinen Geist mit der Kraft, Herr,<br/>Und fülle mein Herz mit Dir!<br/>',NULL,195003,1);
INSERT INTO stanza VALUES('G2079','chorus','Breite Dich aus, breite Dich aus,<br/>Hinein in mein Herz, Herr Jesus!<br/>Oh, wohn in mir, mich füll mit Dir,<br/>Mein Herz nimm ganz ein, Herr Jesus!<br/>',NULL,195004,2);
INSERT INTO stanza VALUES('G2079','2','Oh, breite Dich, Herr, in mein Herz aus!<br/>Hinein in mein Herz, bet ich.<br/>Von meinem Geist breite Dich aus, Herr!<br/>Hinein in mein Herz, bet ich.<br/>',NULL,195005,3);
INSERT INTO stanza VALUES('G2079','3','Mach Wohnung doch in meinem Herzen,<br/>Mach Wohnung darin, o Herr!<br/>So füllt uns so reich Deine Fülle.<br/>Mach Wohnung in mir noch mehr!<br/>',NULL,195006,4);
INSERT INTO stanza VALUES('G2079','4','Dem Herrn, der noch mehr, als wir bitten<br/>Und denken, zu tun vermag,<br/>Ihm öffnen wir weit unsre Herzen --<br/>Empfangen Ihn Tag für Tag.<br/>',NULL,195007,5);
INSERT INTO stanza VALUES('G2080','1','Nimm meine Schleier weg,<br/>Damit im Licht ich geh,<br/>Nicht mehr betrogen bin,<br/>All Dinge richtig seh.<br/>',NULL,195008,1);
INSERT INTO stanza VALUES('G2080','chorus','Oh, mög Dein Licht von Leben<br/>Mir die Nacht entheben<br/>Und klare Sicht mir geben,<br/>Herr, hierfür bete ich.<br/>',NULL,195009,2);
INSERT INTO stanza VALUES('G2080','2','Ich kenne mich selbst kaum,<br/>Der Stolz verblendet mich,<br/>Ich denk, nur ich hab Recht;<br/>Welch selbstzufriednes Ich!<br/>Welch selbstzufriednes Ich!<br/>',NULL,195010,3);
INSERT INTO stanza VALUES('G2080','3','Ich kenne Dich, o Herr,<br/>Nur nach Lehrmäßigkeit;<br/>Mir Offenbarung fehlt<br/>Von Deiner Wirklichkeit.<br/>',NULL,195011,4);
INSERT INTO stanza VALUES('G2080','4','Dein Leben, Herr, in mir<br/>Im Dunkeln ich verkenn --<br/>Was Geist ist und was Fleisch,<br/>Die zwei kann ich nicht trenn''n.<br/>',NULL,195012,5);
INSERT INTO stanza VALUES('G2080','5','Dein Weg für mich, o Herr,<br/>Ist mir oft nicht so klar;<br/>Ich ziehe mich zurück<br/>Und weiche ab sogar.<br/>',NULL,195013,6);
INSERT INTO stanza VALUES('G2080','6','Dein Wille, Herr, für mich<br/>Ist schlecht bekannt doch mir;<br/>Ich lehn ihn öfters ab<br/>Und häufig rebellier.<br/>',NULL,195014,7);
INSERT INTO stanza VALUES('G2080','7','Was die Gemeind betrifft,<br/>Schenk Offenbarung, Herr!<br/>Das Leben in dem Leib<br/>Will ich kennen noch mehr.<br/>',NULL,195015,8);
INSERT INTO stanza VALUES('G2080','8','Herr, nimm die Schleier mir,<br/>Dass ich klar sehen kann.<br/>Will nicht betrogen sein,<br/>Den Stolz leg ab fortan.<br/>',NULL,195016,9);
INSERT INTO stanza VALUES('G2081','1','Wenn wir genau wie Christus werdn<br/>In Natur, Leben, Ausdruck und Funktion<br/>Können wir für Seinen Leib mit Ihm<br/>Zusammenwirken.<br/>',NULL,195017,1);
INSERT INTO stanza VALUES('G2081','2','Wenn wir hilflos auf den Herrn vertraun,<br/>Uns auf Ihn lehnen als Liebe und Kraft<br/>Und Seinem Sprechen zuhörn,<br/>Hoffen wir auf die Entrückung<br/>Durch die Erlösung unsres Leibes.<br/>',NULL,195018,2);
INSERT INTO stanza VALUES('G2081','3','Und wir beten:<br/>„Komm, Herr Jesus!"<br/>Und wir beten:<br/>„Komm, Herr Jesus!<br/>Komm, Herr Jesus!<br/>Herr Jesus, komm!"<br/>',NULL,195019,3);
INSERT INTO stanza VALUES('G2082','1','Herr, Deine Rückkehr ...<br/>Wie lang muss es noch gehn, o Herr?<br/>Die Zeiten sind um,<br/>Jahrhunderte rum,<br/>Die Jahre gingen vorbei.<br/>Liebster, komm doch bald!<br/>Unser Schatz, komm zurück!<br/>Herr, zögere nicht!<br/>Kaufen aus unsre Zeit,<br/>Dass Du bald schon kommst!<br/>',NULL,195020,1);
INSERT INTO stanza VALUES('G2082','2','''ne Generation ...<br/>Sie suchen Dein Angesicht,<br/>Sind Dein Überrest,<br/>So treu ist ihr Herz,<br/>Sie lieben nur Dich, Herr.<br/>König der Herrlichkeit --<br/>Ihm öffnet euch doch weit!<br/>Macht die Tore weit!<br/>Noch haben wir Zeit.<br/>Lasst den König einziehn!<br/>',NULL,195021,2);
INSERT INTO stanza VALUES('G2082','3','''ne Generation ...<br/>Die Dich zurückbring''n will.<br/>Ihr Schatz bist nur Du,<br/>Ihre Zukunft dazu.<br/>Es liegt ihnen nur an Dir.<br/>Dies Ziel ist ganz tief drin,<br/>Ein Feuer, das in ihnen brennt.<br/>Von dem Eifer verzehrt<br/>Ihre Realität:<br/>Deine Wiederkunft.<br/>',NULL,195022,3);
INSERT INTO stanza VALUES('G2082','4','''ne Generation ...<br/>Die Du eingenommen hast.<br/>Ihr Herz ist für Dich,<br/>Für die Welt bleibt nichts.<br/>Ihre Freude bist nur Du.<br/>Jungfrauen weise und rein --<br/>Nur Du nimmst ihren Blick ein.<br/>Sie warten schon lang<br/>Auf Dich, Bräutigam,<br/>Deine Wiederkehr.<br/>',NULL,195023,4);
INSERT INTO stanza VALUES('G2082','5','O Generation ...<br/>Der Geist und die Braut sag''n: „Komm!"<br/>Der Geist ruft dir zu,<br/>Die Braut ruft dazu.<br/>Hört auf den vermengten Ruf!<br/>Kommt, ihr Suchenden, kommt<br/>Zum kostbarsten Bräutigam!<br/>Gottes ewiger Wunsch<br/>Ist Vermengung mit uns.<br/>Stillt Sein''n Herzenswunsch!<br/>',NULL,195024,5);
INSERT INTO stanza VALUES('G2082','6','Oh, komm, Herr Jesus ...<br/>Dafür, Herr, stärke uns!<br/>Hilf uns, treu zu stehn,<br/>Dass bis zum Ende wir gehen!<br/>Halt uns in Deiner Hand!<br/>Komm, Herr Jesus, komm<br/>Für Dein'' Braut, Neu''s Jerusalem!<br/>Bis wir uns endlich sehn,<br/>Lass in Gnade uns stehn!<br/>Mög es schnell geschehn!<br/>',NULL,195025,6);
INSERT INTO stanza VALUES('G2083','1','Ich bin des Herrn! O Freude unaussprechlich!<br/>O süße Antwort auf die Liebesstimm;<br/>„Ja," ruft der Glaube auf Sein treues Flüstern:<br/>Ich muss nicht fürchten, ich gehöre Ihm.<br/>',NULL,195026,1);
INSERT INTO stanza VALUES('G2083','2','Ich bin des Herrn! So klingt das froh Bekenntnis,<br/>Mit dem die Braut den frohen Tag besinnt,<br/>Als Ihm die Liebe ihr Gelübde aussprach<br/>Und Ehre und Gehorsam gab sich hin.<br/>',NULL,195027,2);
INSERT INTO stanza VALUES('G2083','3','Ich bin des Herrn! Mich lehr, was dies bedeutet.<br/>Alles, was Liebe, Treue anbetrifft,<br/>Heiliger Dienst und absolute Weihung,<br/>Was vorbehaltloser Gehorsam ist.<br/>',NULL,195028,3);
INSERT INTO stanza VALUES('G2083','4','Ich bin des Herrn! Ja, Geist samt Leib und Seele.<br/>Komm, nun versiegle alles völlig Dir,<br/>So, Liebster, in der Fülle Deiner Liebe<br/>Immer und ewiglich gehörst Du mir.<br/>',NULL,195029,4);
INSERT INTO stanza VALUES('G2084','1','Herr, lass mein Herz immer treu Dir sein!<br/>Niemals weggleitend, immer Dich im Blick,<br/>Ein Herz, welches rein ist und nur Dich sieht,<br/>Ein Herz, das Dich liebt und Dich allein nur schätzt.<br/>',NULL,195030,1);
INSERT INTO stanza VALUES('G2084','chorus','Gedrängt von Liebe geb ich mein Alles Dir.<br/>Ich kann nichts tun, Herr, Du ziehst mein Herz zu Dir.<br/>Oh, welch ein Vorrecht! Ich gebe mich ganz Dir!<br/>Ich lieb Dich, Herr! Liebster Herr!<br/>Ich lieb Dich! Ich lieb nur Dich!<br/>',NULL,195031,2);
INSERT INTO stanza VALUES('G2084','2','Herr, lass meine Liebe immer brennen für Dich!<br/>Liebe niemals schwindend, immer heiß für Dich.<br/>Liebe immer heller, heller scheinend für Dich.<br/>So frisch wie damals, als ich Dich zuerst berührt.<br/>',NULL,195032,3);
INSERT INTO stanza VALUES('G2084','3','Herr, nimm mein Leben, ich gebe es Dir!<br/>Hätte ich tausend, gäb ich alle Dir!<br/>Kein Wenn und Aber, ich halt nichts zurück.<br/>Mein Leben, meine Zukunft, mein Alles ist für Dich.<br/>',NULL,195033,4);
INSERT INTO stanza VALUES('G2085','1','Herr, Du liebst mich unermesslich<br/>Und genauso liebe ich Dich.<br/>Jeden Tag und ohne Ende,<br/>O Herr, nimm mich ein!<br/>Ziel und Inhalt meines Lebens<br/>Sei es, Dich noch mehr zu lieben<br/>Mit ganzem Herzen, Jesus.<br/>Lass mich immer treu Dir sein!<br/>Zieh mich Herr, zu Dir!<br/>Nimm den Schleier mir!<br/>Und mit reinem Herzen will ich<br/>Sehen Dich, o Herr!<br/>Niemand'' sonst such ich,<br/>Denn es gibt nur Dich.<br/>Ich will völlig und vollkommen<br/>Mich Dir hingeben, O Herr.<br/>',NULL,195034,1);
INSERT INTO stanza VALUES('G2086','1','Die Liebe Christi nimmt mich so sehr ein,<br/>Dass ich Ihn liebe und bin völlig Sein.<br/>Von Seiner Liebe Macht bin ich berührt,<br/>Mein ganzes Leben Ihm, nur Ihm gehört.<br/>Er ist vortrefflich, bezaubernd,<br/>So anziehend und berührend --<br/>Ich ergebe mich, kann mich Ihm nicht mehr entziehn.<br/>',NULL,195035,1);
INSERT INTO stanza VALUES('G2086','2','Der Fluss der Liebe fließt von Ihm zu mir;<br/>Der Fluss der Liebe, er steigt mehr und mehr.<br/>Ich bin für Ihn, ich kann''s nicht kontrolliern;<br/>Ich will mich in Seiner Liebe ganz verliern.<br/>Er starb aus Liebe, sie drängt uns;<br/>Dieser Liebe Fluss durchtränkt uns.<br/>Ich liebe Ihn, kann mich Ihm nicht mehr entziehn.<br/>',NULL,195036,2);
INSERT INTO stanza VALUES('G2086','3','Die Liebe Christi,<br/>Sie nimmt mich völlig ein und ich bin völlig Sein.<br/>Von Seiner Liebe Macht bin ich berührt,<br/>Mein Leben Ihm gehört.<br/>Er ist vortrefflich, bezaubernd;<br/>So anziehend und berührend --<br/>Ich ergebe mich, kann mich Ihm nicht mehr entziehn.<br/>',NULL,195037,3);
INSERT INTO stanza VALUES('G2086','4','Nun Seine Liebe,<br/>Sie fließt von Ihm zu mir und sie wird immer mehr.<br/>Ich geb mich hin,<br/>Mein Herr soll Er nur sein, Er ist mein Ziel allein.<br/>Er starb aus Liebe, sie drängt uns;<br/>Dieser Liebe Fluss durchtränkt uns.<br/>Ich liebe Ihn, kann mich Ihm nicht mehr entziehn.<br/>(Die Strophen 1 und 3, 2 und 4 können gleichzeitig gesungen werden.)<br/>',NULL,195038,4);
INSERT INTO stanza VALUES('G2087','1','Lieb den Herrn, gib dich Ihm hin!<br/>Kein andrer Weg ist so vorherrschend<br/>Und kein andrer Weg so sicher ist und so fest.<br/>',NULL,195039,1);
INSERT INTO stanza VALUES('G2087','2','Lieb den Herrn, gib dich Ihm hin!<br/>Kein andrer Weg ist so reich<br/>Und so voll, oh so voller Genuss.<br/>',NULL,195040,2);
INSERT INTO stanza VALUES('G2087','chorus','Am Morgen, wenn wir aufstehn, neu sagen wir zu Ihm:<br/>„Herr Jesus, ich lieb Dich."<br/>',NULL,195041,3);
INSERT INTO stanza VALUES('G2087','3','Lieb den Herrn, gib dich Ihm hin!<br/>Sorg dich um nichts anderes mehr!<br/>Liebe Ihn! Sorg dich nicht!<br/>Lieb den Herrn, gib dich Ihm hin!<br/>',NULL,195042,4);
INSERT INTO stanza VALUES('G2087','chorus','Du hast uns erkauft, Herr;<br/>Alles geben wir Dir hin.<br/>Herr Jesus! Herr Jesus!<br/>Herr Jesus, wir lieben Dich!<br/>',NULL,195043,5);
INSERT INTO stanza VALUES('G2088','1','Das Ziel des Evangeliums ist,<br/>Wenn wir den Herrn mit unsrer<br/>Ersten Liebe liebn,<br/>Dass wir auf Ihn ausgießen,<br/>Auf Ihn ausgießen,<br/>Was uns am kostbarsten ist --<br/>Selbst unsern teuersten und wertvollsten<br/>Geistlichen Schatz,<br/>Wenn wir uns „verschwenden" an Ihn,<br/>Selbst unsern teuersten und wertvollsten<br/>Geistlichen Schatz,<br/>Wenn wir uns „verschwenden" an Ihn.<br/>',NULL,195044,1);
INSERT INTO stanza VALUES('G2089','1','Manchmal erscheint''s mir,<br/>Als wär kein Raum in mei''m Herz''n für Dich.<br/>Doch dann berührst Du mich<br/>Und regst mich an, zu Dir umzukehrn.<br/>',NULL,195045,1);
INSERT INTO stanza VALUES('G2089','chorus','Erlange mein Herz,<br/>Entfach meine Liebe für Dich!<br/>Fülle mich, Herr,<br/>Für ewig und immer neu!<br/>Mach mich völlig Dein!<br/>',NULL,195046,2);
INSERT INTO stanza VALUES('G2089','2','Herr, ich möchte<br/>Mich leeren von allem außer Dir.<br/>Die beste Liebe,<br/>Vorrang in allem, geb ich Dir.<br/>',NULL,195047,3);
INSERT INTO stanza VALUES('G2089','3','Ich will Dich lieben<br/>Mit Herz und Seele ganz und gar.<br/>Ich will nichts andres.<br/>Geb mich Dir hin, um ganz Dein zu sein.<br/>',NULL,195048,4);
INSERT INTO stanza VALUES('G2090','1','Hast du Ihn gehört, gesehen?<br/>Brennt für Ihn dein Herz noch nicht?<br/>Führer von Zehntausend wolln Ihn,<br/>Wähl Ihn, eh der Tag anbricht.<br/>',NULL,195049,1);
INSERT INTO stanza VALUES('G2090','chorus','Ganz gebannt von Seiner Schönheit,<br/>Lass dich drängen Seinen Wert!<br/>Bring Ihm rasch Tribut entgegen,<br/>Wie''s dem König auch gebührt!<br/>',NULL,195050,2);
INSERT INTO stanza VALUES('G2090','2','Einst entzückten dich die Götzen,<br/>Dich verfing ihr Sinnestand;<br/>Sünd in goldnem Kleid betrog dich,<br/>Süß, dass du dich nicht gewandt.<br/>',NULL,195051,3);
INSERT INTO stanza VALUES('G2090','3','Was hat abgestreift die Schönheit<br/>Von den Götzen dieser Zeit?<br/>Nicht der Sinn für Recht und Pflichten,<br/>Doch die Sicht von Kostbarkeit.<br/>',NULL,195052,4);
INSERT INTO stanza VALUES('G2090','4','Nicht der Bruch mit diesen Götzen,<br/>Der nur Leere bringt und Schmerz;<br/>Doch das Strahlen Seiner Schönheit,<br/>Das Erblicken Seines Herz''.<br/>',NULL,195053,5);
INSERT INTO stanza VALUES('G2090','5','Wer denn löscht die Kerzen aus schon,<br/>Eh'' die Morgensonne strahlt?<br/>Wer legt ab die Winterkleidung,<br/>Eh'' der Sommer zeigt Gestalt?<br/>',NULL,195054,6);
INSERT INTO stanza VALUES('G2090','6','Nur der Blick, der Petrus hinschmolz,<br/>Das Gesicht, das Steph''nus sah,<br/>Herz, das mit Maria weinte,<br/>Uns entzieht die Götzen gar.<br/>',NULL,195055,7);
INSERT INTO stanza VALUES('G2090','7','Zieh, gewinne, uns vollkommen,<br/>Bis der Becher überquillt!<br/>Was solln wir nunmehr mit Götzen,<br/>Die wir uns zu Ihm gesellt?<br/>',NULL,195056,8);
INSERT INTO stanza VALUES('G2091','1','Nimm mein Leben, Dir es sei!<br/>Völlig Dir, Herr, ich mich weih;<br/>Jede Stunde geb ich hin,<br/>Fließen soll Dein Lob darin.<br/>Fließen soll Dein Lob darin.<br/>',NULL,195057,1);
INSERT INTO stanza VALUES('G2091','2','Nimm die Hände, lass sie nun<br/>Alles in der Liebe tun!<br/>Nimm die Füße, lass sie sein<br/>Schnell und schön für Dich allein!<br/>Schnell und schön für Dich allein!<br/>',NULL,195058,2);
INSERT INTO stanza VALUES('G2091','3','Nimm die Stimme, dass sie singt,<br/>Für den König schön erklingt!<br/>Nimm die Lippen, lass sie hier<br/>Reden immerzu von Dir!<br/>Reden immerzu von Dir!<br/>',NULL,195059,3);
INSERT INTO stanza VALUES('G2091','4','Nimm mein Gold und Silber, Herr!<br/>Nichts für mich behalt ich mehr.<br/>Meine Kraft und den Verstand<br/>Nimm auch ganz in Deine Hand!<br/>Nimm auch ganz in Deine Hand!<br/>',NULL,195060,4);
INSERT INTO stanza VALUES('G2091','5','Meinen Willen nimm Du ein,<br/>Er sei nicht mehr länger mein!<br/>Mach mein Herz zu Deinem Thron,<br/>Du als König darin wohn!<br/>Du als König darin wohn!<br/>',NULL,195061,5);
INSERT INTO stanza VALUES('G2091','6','Meine Liebe nimm für Dich!<br/>Deine Füße salbe ich.<br/>Nimm mein ganzes Wesen ein!<br/>Alles soll für Dich, Herr, sein.<br/>Alles soll für Dich, Herr, sein.<br/>',NULL,195062,6);
INSERT INTO stanza VALUES('G2092','1','Herr, in dieser Zeit<br/>Brauchst Du uns als Samuels<br/>Mit der Last und klaren Sicht Deiner Ökonomie.<br/>Deine Suchenden<br/>Und Dein Zeugnis, wo sind sie?<br/>Die sich gar beiseitestelln für Deinen Herzenswunsch?<br/>',NULL,195063,1);
INSERT INTO stanza VALUES('G2092','chorus','Oh, erwecke Nasiräer für Dich Selbst,<br/>Priester und Propheten, Betende,<br/>Die mit Autorität Dein Wort hervorsprechen!<br/>Ein Abbild Deines Herzens sind sie Dir.<br/>',NULL,195064,2);
INSERT INTO stanza VALUES('G2092','2','Schul uns heute, Herr!<br/>Suchen Dich voller Vision,<br/>Warten auch auf Deine Zeit und ordnen uns unter.<br/>Schätzen Dein Gesicht,<br/>Bleibn in Deiner Gegenwart,<br/>Sogar Deinen Augen wollen wir gehorchen stets.<br/>',NULL,195065,3);
INSERT INTO stanza VALUES('G2092','chorus','Oh, erwecke Nasiräer für Dich Selbst,<br/>Um Dein Königreich auf die Erd zu bring''n!<br/>Wir nehm''n Dich als König, dass Du bald kommen kannst,<br/>Um das Ende dieser Zeit einzuführn.<br/>',NULL,195066,4);
INSERT INTO stanza VALUES('G2092','3','Wenn Sich Gott bewegt,<br/>Muss ein Werkzeug Er gewinnen,<br/>Überwinder abgesondert von dem Lauf der Welt.<br/>Sie sind eins mit Gott<br/>Durch Sein Wort für Seinen Wunsch,<br/>Überwinder zusamm''gesetzt mit Seinem heiligen Wort.<br/>',NULL,195067,5);
INSERT INTO stanza VALUES('G2092','chorus','Oh, erwecke Nasiräer für Dich Selbst!<br/>Ganz freiwillig geben sie sich hin.<br/>Sie sind durch Dein Wort eins mit Deinem Herzenswunsch,<br/>Dein lebendiges Zeugnis hier auf Erd.<br/>',NULL,195068,6);
INSERT INTO stanza VALUES('G2092','4','Gott braucht Betende,<br/>Die den Weg bahnen für Ihn.<br/>Gott''s Ökonomie wird ausgeführt durch Betende.<br/>Lieben nicht sich selbst,<br/>Opfern sich Dir freiwillig.<br/>Deine Gegenwart verlieren -- das nur fürchten sie.<br/>',NULL,195069,7);
INSERT INTO stanza VALUES('G2092','chorus','Mach uns, Herr, zu Nasiräern für Dich Selbst!<br/>Dieses Zeitalter schließ durch uns ab!<br/>Wir sind eins mit Dir, um Dein Reich herbeizubring''n.<br/>Mach uns, Herr, absolut für Dein''n Plan.<br/>',NULL,195070,8);
INSERT INTO stanza VALUES('G2093','1','Jesus, lebend''ges Wort von Gott,<br/>Wasche mich rein mit Deinem Blut,<br/>Dass ich Dich hören kann!<br/>Worte der Gnade sprichst zu mir,<br/>Strahlend Dein Angesicht ist hier,<br/>Immer schau ich es an.<br/>',NULL,195071,1);
INSERT INTO stanza VALUES('G2093','chorus','Jesus, lebend''ges Wort,<br/>Mein Herz lechzt nach Dir.<br/>Von Dir ess ich und trink,<br/>Voll Freude sing ich Dir.<br/>',NULL,195072,2);
INSERT INTO stanza VALUES('G2093','2','Jesus, wie kostbar bist Du mir,<br/>Dass ich nur suchen will nach Dir,<br/>Und Du durchsättigst mich.<br/>Herr, Deinen Namen ruf ich an,<br/>Öffne mich Dir, ganz frei von Scham,<br/>Jesus, ich liebe Dich.<br/>',NULL,195073,3);
INSERT INTO stanza VALUES('G2093','chorus','Jesus, Kostbarster,<br/>Sei so echt für mich!<br/>Du bist alles mir.<br/>Weit öffne ich mich Dir.<br/>',NULL,195074,4);
INSERT INTO stanza VALUES('G2093','3','Jesus, Du lebst in mir fürwahr.<br/>Augen gib mir zu sehen klar,<br/>Was Du für mich bist, Herr!<br/>Lass mich nur in Dein Herz hinein,<br/>Lass bleiben mich in Dir allein,<br/>Um Dich zu lieben, Herr!<br/>',NULL,195075,5);
INSERT INTO stanza VALUES('G2093','chorus','Jesus, Lebendiger,<br/>Flut mich durch und durch!<br/>Nimm mein willig Herz<br/>Und überwind in mir!<br/>',NULL,195076,6);
INSERT INTO stanza VALUES('G2093','4','Herr, Deinen Weg in mir schlag ein!<br/>Lass mich nicht Satans Beute sein!<br/>Ich glaube Dir, mein Herr.<br/>Rückhaltlos gebe ich Dir hin:<br/>Mein ganzes Sein, mein Herz, mein''n Sinn.<br/>Herr, ich gehöre Dir.<br/>',NULL,195077,7);
INSERT INTO stanza VALUES('G2093','chorus','Jesus, treuer Gott,<br/>Nimm uns völlig ein!<br/>Geh mit uns voran,<br/>Dein''n Vorsatz zu erfülln!<br/>',NULL,195078,8);
INSERT INTO stanza VALUES('G2094','1','Jetzt wend ich mich, Jesus, zu Dir.<br/>Ich weiß, im Streit bin ich noch häufig mit Dir.<br/>Doch kommt von tief in mir Gebet hervor zu Dir.<br/>Herr, gewinn heute viel mehr in mir,<br/>Mehr als jemals zuvor!<br/>',NULL,195079,1);
INSERT INTO stanza VALUES('G2094','2','Herr, Du weißt, ich kämpf um den Sieg --<br/>Ich geb nicht auf und bin selbst beständig im Krieg.<br/>Wie lange noch, bis Deine Liebe mich besiegt?<br/>Herr, gewinn heute viel mehr in mir,<br/>Mehr als jemals zuvor!<br/>',NULL,195080,2);
INSERT INTO stanza VALUES('G2094','3','Wenn ich gewinne, bin ich besiegt.<br/>Ja, wenn ich siege, weiter versklave ich mich.<br/>Bin erst ein Überwinder, wenn allein Du siegst.<br/>Herr, gewinn heute viel mehr in mir,<br/>Mehr als jemals zuvor!<br/>',NULL,195081,3);
INSERT INTO stanza VALUES('G2094','4','Lass mich nie mehr gewinnen, o Herr!<br/>Mach mich zu diesem: Christi Gefangener.<br/>Nicht länger setze ich mich gegen Dich zur Wehr.<br/>Herr, gewinn heute viel mehr in mir,<br/>Mehr als jemals zuvor!<br/>',NULL,195082,4);
INSERT INTO stanza VALUES('G2094','SoundCloud Link','https://soundcloud.com/liederstroeme/jetzt-wend-ich-mich-jesus-zu-dir?in=liederstroeme/sets/vater-du-weisst',NULL,195083,5);
INSERT INTO stanza VALUES('G2095','1','Gott, unser Schöpfer, Er wurde ein Mensch.<br/>Sein Tod erlöste uns für Seinen Plan.<br/>Und in Auferstehung befreit'' Er den Geist.<br/>Er baut die Gemeinde als Sein Meisterwerk.<br/>',NULL,195084,1);
INSERT INTO stanza VALUES('G2095','2','Herr, ich wähle Dich.<br/>Ich seh Deine Schönheit.<br/>Ich gehöre Dir<br/>Jetzt und allezeit.<br/>Meine erste Wahl.<br/>Herr, Du bist so lieblich.<br/>Herr, ich geb alles für Dein Meisterwerk.<br/>',NULL,195085,2);
INSERT INTO stanza VALUES('G2095','3','Herr, ich lieb Dich.<br/>Sonst gibt es niemand''.<br/>Ich lieb Dich, allezeit.<br/>Herr, ich lieb Dich.<br/>Mein Herz ist erneuert.<br/>Herr, ich geb alles für Dein Meisterwerk.<br/>',NULL,195086,3);
INSERT INTO stanza VALUES('G2095','4','Danke, Herr Jesus, Du nimmst mich ganz ein.<br/>Danke, o Herr, jetzt erfahre ich Dich.<br/>Durch feiern, genießen<br/>Nimmt Dein Leben zu.<br/>Danke, ich bin Teil von Dein''m Meisterwerk.<br/>',NULL,195087,4);
INSERT INTO stanza VALUES('G2095','note','(Alle Strophen können gleichzeitig gesungen werden.)<br/>',NULL,195088,5);
INSERT INTO stanza VALUES('G2096','1','Noahs Leben änderte die Zeiten sehr,<br/>Als er Gottes Gnade fand;<br/>Er stand ohne Furcht gegen die ganze Welt<br/>Und die Arche baute er.<br/>',NULL,195089,1);
INSERT INTO stanza VALUES('G2096','chorus','Wirst du ein lebend''ger Überwinder sein und<br/>Sogar einer, der Jesus liebt, ohne sich zu schämen,<br/>Der vom Lebenswasser trinkt<br/>Und isst vom Baum des Lebens?<br/>Wirst du ein lebend''ger Überwinder sein und<br/>Verlässt die Welt und weihst dich, um das Zeitalter zu wenden?<br/>Für Deine Wiederkunft geb ich mich Dir!<br/>',NULL,195090,2);
INSERT INTO stanza VALUES('G2096','2','Mose war ein Mensch, berufen von dem Herrn,<br/>Um zu wenden diese Zeit.<br/>Er war Gottes Freund, für Seinen Willen hier,<br/>Treu und sanft und weise auch.<br/>',NULL,195091,3);
INSERT INTO stanza VALUES('G2096','3','Samuel erfreute Gott mit seinem Priesterdienst<br/>Er war absolut für Ihn.<br/>Dafür gab er sich, ein Nasiräer zu sein:<br/>Frei von Tod, der Welt und Sünd.<br/>',NULL,195092,4);
INSERT INTO stanza VALUES('G2096','4','Daniel sonderte sich mit sein''n Freunden ab<br/>Von der Welt durch Gottes Wort.<br/>Durch Gebet im Geist waren sie eins mit Gott<br/>Für Sein Volk, nach Gottes Herz.<br/>',NULL,195093,5);
INSERT INTO stanza VALUES('G2096','chorus','Ich will ein lebend''ger Überwinder sein und<br/>Sogar einer, der Jesus liebt, ohne sich zu schämen,<br/>Der vom Lebenswasser trinkt<br/>Und isst vom Baum des Lebens.<br/>Ich will ein lebend''ger Überwinder sein und<br/>Die himmlische Vision wird<br/>So mein''n Geist in Flammen halten.<br/>Ich gebe mich Dir hin -- wende die Zeit!<br/>',NULL,195094,6);
INSERT INTO stanza VALUES('G2097','1','Ein wirklich hingegebener Mensch ist ein Mensch,<br/>Der seine Zukunft aufgegeben hat.<br/>Er erwartet nichts mehr.<br/>Er hofft allein auf Gott.<br/>Er weiß nicht, was das Ergebnis sein wird --<br/>Und es kümmert ihn auch nicht.<br/>Er weiß nur, dass er ein Opfer ist, das<br/>Ganz und gar Gott gehört.<br/>',NULL,195095,1);
INSERT INTO stanza VALUES('G2097','2','Er lebt einzig und allein in der Hand Gottes. Er --<br/>Ist das, was Gott möchte, dass er sei.<br/>Und er tut das, was Gott<br/>Möchte, dass er tät.<br/>',NULL,195096,2);
INSERT INTO stanza VALUES('G2097','SoundCloud Link','https://soundcloud.com/liederstroeme/ein-wirklich-hingegebener',NULL,195097,3);
INSERT INTO stanza VALUES('G2098','1','Herr, ich komme. Ich komme, wie ich bin.<br/>Lass mein kaltes Herz in Flammen aufgehn!<br/>Herr, lass mich nicht ewig gleich bleiben!<br/>Daher nimm mein Herz gefangen!<br/>Besetz mich! Und besitze mich!<br/>Wende mich von allem zu Dir!<br/>Entzücke mich und gewinne mich!<br/>O Herr, ich gehör nur Dir!<br/>',NULL,195098,1);
INSERT INTO stanza VALUES('G2098','SoundCloud Link','https://soundcloud.com/liederstroeme/herr-ich-komme',NULL,195099,2);
INSERT INTO stanza VALUES('G2099','1','Oh, welche Zunge je beschreibt,<br/>Wie frei die Seele wird,<br/>Wenn sie dem eitlen Trug enteilt<br/>Und Gott sie ganz regiert?<br/>Dann hat sie alles, Leben, Tod,<br/>Was ist und kommt dazu;<br/>Sie atmet Frieden ein in Gott,<br/>In Christus kommt zur Ruh.<br/>',NULL,195100,1);
INSERT INTO stanza VALUES('G2099','2','Wer hier den König wählen kann,<br/>Mit Ihm den Thron darf teiln,<br/>Der überbietet Seltsamkeit,<br/>Sich nicht dem Herrn zu weihn.<br/>Von Opfer rede nimmermehr!<br/>Ein Vorrecht ungemein<br/>Ist''s, Sein zu sein zu jedem Preis,<br/>Im Kreuzes-Heer, nur Sein.<br/>',NULL,195101,2);
INSERT INTO stanza VALUES('G2099','3','Auf! Geh mit Gott den Handel ein!<br/>Ein Bruchstück für so viel --<br/>Ja, jeder Mensch und Umstand bringt<br/>Die Seele mehr zum Ziel.<br/>Gehörst du Ihm, ist alles dir,<br/>Eins bist du mit dem Herrn;<br/>Sein Leben überfließt in dir,<br/>Sein Reich ist nicht mehr fern.<br/>',NULL,195102,3);
INSERT INTO stanza VALUES('G2100','1','Dem Herrn singen wir nun mit dem Geist,<br/>Dem Herrn singen wir nun von tief drin.<br/>Singen laut Halleluja zu Jesus,<br/>Und in Einheit vermengt sein mit Ihm.<br/>',NULL,195103,1);
INSERT INTO stanza VALUES('G2100','2','Religion nahm uns ein viele Jahre,<br/>Wir warn jahrelang nur im Verstand,<br/>Viele Jahre in unsren Gefühlen,<br/>Immer suchend, doch gar nichts sich fand.<br/>',NULL,195104,2);
INSERT INTO stanza VALUES('G2100','3','Zum Geist lernen wir uns nun zu wenden,<br/>Christus nehmen als Leben allzeit;<br/>Lernen uns zu ernähren von Jesus --<br/>Das von Kämpfen und Mühen befreit.<br/>',NULL,195105,3);
INSERT INTO stanza VALUES('G2100','4','Halleluja für Leben im Geist,<br/>Halleluja für Neuheit tief drin.<br/>Vom Verstand wenden wir uns zum Geist<br/>Und genießen den Reichtum von Ihm.<br/>',NULL,195106,4);
INSERT INTO stanza VALUES('G2101','1','Nichts ist mir so kostbar<br/>Wie Jesus Christus in mir.<br/>Er nimmt die Sorgen weg,<br/>Füllt mich mit Seiner Ruh,<br/>Verlässt mich nie mehr,<br/>Auch nicht im Tagesärger.<br/>In Seiner Gegenwart<br/>Freut stille sich mein Herz immerzu.<br/>',NULL,195107,1);
INSERT INTO stanza VALUES('G2101','chorus','Ich ruf Ihn an: Herr Jesus,<br/>Wenn ich schwach bin, hilf mir!<br/>Und jeden Tag beweist Er neu:<br/>Sein Lebensstrom ist allgenügend.<br/>',NULL,195108,2);
INSERT INTO stanza VALUES('G2101','2','Nichts ist mir so kostbar<br/>Wie Jesus in mein''m Geiste.<br/>Mein Herz zieht Er zu Sich,<br/>Sein Leben es genießt.<br/>''s ist nichts, das ich tu,<br/>Er ist''s, Sein Glaube in mir --<br/>Durch Gottes Gnade ward<br/>Mir Freude ohne End zuteil.<br/>',NULL,195109,3);
INSERT INTO stanza VALUES('G2102','1','Einst fern von Gott, in Sünde tot,<br/>Kein Licht mein Herz sah hier;<br/>In Gottes Wort doch fand ich Licht,<br/>Jetzt lebt Christus in mir.<br/>',NULL,195110,1);
INSERT INTO stanza VALUES('G2102','chorus','Christus lebt nun in mir,<br/>Christus lebt nun in mir,<br/>Welch eine Errettung ist''s!<br/>Jetzt lebt Christus in mir.<br/>',NULL,195111,2);
INSERT INTO stanza VALUES('G2102','2','Wie Sonnenlicht zum Blühen bringt<br/>Die schönsten Blumen hier,<br/>So Leben, Licht und Liebe komm''n<br/>Vom Herrn, der lebt in mir.<br/>',NULL,195112,3);
INSERT INTO stanza VALUES('G2102','3','Die Blume lebt im Samen drin,<br/>Der Baum, der lebt im Kern.<br/>So wohnt in mir, wie wunderbar,<br/>Der reiche Geist des Herrn.<br/>',NULL,195113,4);
INSERT INTO stanza VALUES('G2102','4','Mit Sehnen wird mein Herz erfüllt,<br/>Ich möcht Ihm gleich sein hier;<br/>In mir nur ein Gedanke wohnt:<br/>Jetzt lebt Christus in mir.<br/>',NULL,195114,5);
INSERT INTO stanza VALUES('G2103','1','Gott gab den Sohn, dass Er uns sei<br/>Der Baum des Lebens, reich und frei,<br/>Dass jeder schmeckt und sieht dabei:<br/>',NULL,195115,1);
INSERT INTO stanza VALUES('G2103','chorus','Ja, Gott ist gut zur Speis!<br/>Ja, Gott ist gut zur Speis!<br/>Ja, Gott ist gut zur Speis!<br/>Wir schmeckten und bezeugen nun:<br/>Ja, Gott ist gut zur Speis!<br/>',NULL,195116,2);
INSERT INTO stanza VALUES('G2103','2','Ein Festmahl ist''s, wir essen Gott --<br/>Wir leben nun durch Gottes Brot,<br/>Da Gott Sich Selbst als Fest anbot,<br/>Ja, Gott ist unser Fest.<br/>',NULL,195117,3);
INSERT INTO stanza VALUES('G2103','chorus','Ja, Gott ist unser Fest!<br/>Ja, Gott ist unser Fest!<br/>Durch Jesus Christus leben wir.<br/>Ja, Gott ist unser Fest!<br/>',NULL,195118,4);
INSERT INTO stanza VALUES('G2103','3','Als Speise Sich der Herr erklärt,<br/>Er ist das Brot, das uns ernährt,<br/>Sein Leben sättigt, sich bewährt,<br/>Iss Christus jeden Tag!<br/>',NULL,195119,5);
INSERT INTO stanza VALUES('G2103','chorus','Iss Christus jeden Tag!<br/>Iss Christus jeden Tag!<br/>Sein Leben sättigt und ernährt,<br/>Iss Christus jeden Tag!<br/>',NULL,195120,6);
INSERT INTO stanza VALUES('G2103','4','Oh, welch Genuss ist dieses Fest!<br/>Für alle so verfügbar jetzt,<br/>Da Gott gern jeden kommen lässt,<br/>Ja, komm und iss umsonst!<br/>',NULL,195121,7);
INSERT INTO stanza VALUES('G2103','chorus','Ja, komm und iss umsonst!<br/>Ja, komm und iss umsonst!<br/>Da Gott gern jeden kommen lässt,<br/>Ja, komm und iss umsonst!<br/>',NULL,195122,8);
INSERT INTO stanza VALUES('G2104','1','Es ist das Leben, Leben, das uns rufen lässt:<br/>Halleluja! Preist den Herrn!<br/>Es ist das Leben, Leben, das uns rufen lässt:<br/>Halleluja! Preist den Herrn!<br/>Wie herrlich! Wir voll Freude sind,<br/>Weil Jesus Christus in uns wohnt!<br/>Weil Jesus Christus in uns wohnt!<br/>',NULL,195123,1);
INSERT INTO stanza VALUES('G2105','1','In meinem Geist ist der Sohn Gottes<br/>Doch Verstand, Gefühl und Wille<br/>Sind noch nicht behandelt<br/>Und ich dank Gott: Ich bin unter dem Vorgang<br/>Der Gleichgestaltung<br/>In das Bild von<br/>Gottes Sohn, Amen!<br/>',NULL,195124,1);
INSERT INTO stanza VALUES('G2105','2','In mir wirkt das Gesetz des Lebens<br/>Er Verstand, Gefühl und Willen<br/>Nun gleichgestaltet.<br/>Seinem Wirken in mir öffne ich mich, bis<br/>Mein ganzes Wesen<br/>Das Bild des Sohnes<br/>Gottes trägt, Amen!<br/>',NULL,195125,2);
INSERT INTO stanza VALUES('G2106','1','Was mir Gewinn einst war,<br/>Das acht ich für Verlust.<br/>Jesus hat mich befreit<br/>Von dem, was ich war!<br/>Alles, was ich einst hatte,<br/>Sei es gut oder schlecht,<br/>Acht ich als Abfall,<br/>Dass ich Christus gewinn!<br/>',NULL,195126,1);
INSERT INTO stanza VALUES('G2106','chorus','Ich geb nicht auf!<br/>Ich jage nach, bis ich<br/>Erreicht hab das Ziel<br/>Meiner Berufung!<br/>Ich jage nach!<br/>Bis ich''s auch ganz ergreif,<br/>Wozu ich von Ihm<br/>Ergriffen worden bin.<br/>',NULL,195127,2);
INSERT INTO stanza VALUES('G2106','2','Vergiss, was hinten liegt!<br/>Strecke dich aus nach vorn!<br/>Jage dem Ziel entgegen:<br/>Wir wollen mehr!<br/>Ich wachs in Ihn hinein,<br/>Erkenne Ihn noch mehr,<br/>Sodass ich täglich werd<br/>Gefunden in Ihm.<br/>',NULL,195128,3);
INSERT INTO stanza VALUES('G2107','1','Der Herr ist der Geist des Lebens,<br/>Der Geist, der das Leben gibt.<br/>Der Herr ist der Geist des Lebens.<br/>So wende dich zum Geist und sprich!<br/>',NULL,195129,1);
INSERT INTO stanza VALUES('G2107','chorus','O Herr, Amen,<br/>O Herr, Amen, Halleluja!<br/>O Herr, Amen,<br/>O Herr, Amen Halleluja!<br/>',NULL,195130,2);
INSERT INTO stanza VALUES('G2107','2','Der Herr ist der Geist des Lebens.<br/>Er ist das lebendige Wort.<br/>Der Geist wird in unserm Geist fließen.<br/>Das Wort wird zum Leben uns durch:<br/>',NULL,195131,3);
INSERT INTO stanza VALUES('G2107','chorus','Beten, Lesen,<br/>Loben und Anrufen Seines Namns.<br/>Wir beten, lesen,<br/>loben und rufen Ihn an!<br/>',NULL,195132,4);
INSERT INTO stanza VALUES('G2108','1','Vom Quell des Lebens trinken wir,<br/>Aus Seinem Brunnen schöpfen hier;<br/>Denn, wer Mich trinkt, so sagt der Herr,<br/>Soll niemals, niemals dürsten mehr.<br/>',NULL,195133,1);
INSERT INTO stanza VALUES('G2108','chorus','Was, dürsten nimmermehr? Ja, dürsten nimmermehr!<br/>Was, dürsten nimmermehr? Ja, dürsten nimmermehr!<br/>Denn, wer Mich trinkt, so sagt der Herr,<br/>Soll niemals, niemals dürsten mehr!<br/>',NULL,195134,2);
INSERT INTO stanza VALUES('G2108','2','Das Brot des Lebens essen wir,<br/>Beim Fest, das unser Herr gibt hier;<br/>Denn, wer Mich isst, so sagt der Herr,<br/>Soll niemals, niemals hungern mehr.<br/>',NULL,195135,3);
INSERT INTO stanza VALUES('G2108','chorus','Was, hungern nimmermehr? Ja, hungern nimmermehr!<br/>Was, hungern nimmermehr? Ja, hungern nimmermehr!<br/>Denn, wer Mich isst, so sagt der Herr,<br/>Soll niemals, niemals hungern mehr.<br/>',NULL,195136,4);
INSERT INTO stanza VALUES('G2108','3','Wir atmen Geist und Leben ein,<br/>Den Geist des Lebens, das wir teiln;<br/>Denn, wer Mich atmet, sagt der Herr,<br/>Hat Gottes Leben mehr und mehr.<br/>',NULL,195137,5);
INSERT INTO stanza VALUES('G2108','chorus','Was, Gottes Leben hat? Ja, Gottes Leben hat!<br/>Was, Gottes Leben hat? Ja, Gottes Leben hat!<br/>Denn, wer Mich atmet, sagt der Herr,<br/>Hat Gottes Leben mehr und mehr.<br/>',NULL,195138,6);
INSERT INTO stanza VALUES('G2108','4','Den Wein des Lebens schmecken wir,<br/>Sein Leben süß im Geist spürn hier;<br/>Denn, wer Mich schmeckt, so sagt der Herr,<br/>Hat Gottes Freude mehr und mehr.<br/>',NULL,195139,7);
INSERT INTO stanza VALUES('G2108','chorus','Was, Gottes Freude hat? Ja, Gottes Freude hat!<br/>Was, Gottes Freude hat? Ja, Gottes Freude hat!<br/>Denn, wer Mich schmeckt, so sagt der Herr,<br/>Hat Gottes Freude mehr und mehr.<br/>',NULL,195140,8);
INSERT INTO stanza VALUES('G2108','5','Ja, Christus starb und auferstand,<br/>Sein Königsleben uns gesandt;<br/>Empfängst du Ihn, so singst du Gott<br/>Und lebest immer, immerfort.<br/>',NULL,195141,9);
INSERT INTO stanza VALUES('G2108','chorus','Was, leben immerfort? Ja, leben immerfort!<br/>Was, leben immerfort? Ja, leben immerfort!<br/>Empfängst du Ihn, so singst du Gott<br/>Und lebest immer, immerfort.<br/>',NULL,195142,10);
INSERT INTO stanza VALUES('G2109','1','Trinkt! Vom reinen, klaren Strom,<br/>aus Gottes Thron er fließt.<br/>Esst! Vom Baum des Lebens,<br/>Seine Früchte jetzt genießt!<br/>Seht! Gar keine Lampe, Sonn noch Mond<br/>mehr braucht''s als Licht,<br/>Denn hier die Nacht gibt''s nicht!<br/>',NULL,195143,1);
INSERT INTO stanza VALUES('G2109','chorus','Komm doch, oh, komm doch!<br/>So sagen Geist und Braut.<br/>Komm doch, oh, komm doch!<br/>Wer''s hört, der rufe laut!<br/>Komm doch, oh, komm doch!<br/>Wer durstig ist und will,<br/>Trink'' Wasser des Lebens umsonst!<br/>',NULL,195144,2);
INSERT INTO stanza VALUES('G2109','2','Christus, unser Strom und Wasser, springt aus uns heraus;<br/>Christus, unser Baum und Frucht, genießen wir daraus;<br/>Christus, unser Tag und Licht und unser Morgenstern;<br/>Christus alles ist!<br/>',NULL,195145,3);
INSERT INTO stanza VALUES('G2109','3','Wascht die Kleider und den Baum des Lebens froh genießt!<br/>„O Herr, Amen, Halleluja!" -- Jesus ist so süß!<br/>Üben alle unsren Geist, um Christus zu erfahren.<br/>Reich versorgt Er uns!<br/>',NULL,195146,4);
INSERT INTO stanza VALUES('G2109','4','Ein Zuhause haben wir, das wie die Sonne scheint,<br/>Wo die Brüder alle eins sind und im Herrn vereint.<br/>Jesus baut uns all zusammen. Ihn stellen wir aus<br/>Hier in der Gemeind.<br/>',NULL,195147,5);
INSERT INTO stanza VALUES('G2110','1','Einst war es der Segen,<br/>Jetzt ist es mein Herr;<br/>Einst warn es Gefühle,<br/>Jetzt Sein Wort vielmehr;<br/>Einst wollt ich die Gabe,<br/>Jetzt den Geber hab;<br/>Einst nur suchte Heilung,<br/>Jetzt an Ihm mich lab.<br/>',NULL,195148,1);
INSERT INTO stanza VALUES('G2110','chorus','Alles und in allem<br/>Christus nur ich sing;<br/>Alles ist in Christus<br/>Und Christus alles ist.<br/>',NULL,195149,2);
INSERT INTO stanza VALUES('G2110','2','Einst war''s zähes Ringen,<br/>Jetzt schau ich auf Ihn;<br/>Einst nur halb errettet,<br/>Jetzt ganz frei ich bin;<br/>Einst nach Halt ich suchte,<br/>Jetzt Er mich umfasst;<br/>Einst umhergetrieben,<br/>Jetzt mein Anker passt.<br/>',NULL,195150,3);
INSERT INTO stanza VALUES('G2110','3','Einst ich emsig plante,<br/>Jetzt bet ich: „O Herr!";<br/>Einst gab''s Angst und Sorgen,<br/>Jetzt Vertraun vielmehr.<br/>Einst, nur was ich wollte,<br/>Jetzt, was Jesus will;<br/>Einst war''s ständig bitten,<br/>Jetzt lob ich Ihn still.<br/>',NULL,195151,4);
INSERT INTO stanza VALUES('G2110','4','Einst galt meine Arbeit,<br/>Jetzt um Seine geht''s;<br/>Einst wollt ich Ihn brauchen,<br/>Jetzt braucht Er mich stets.<br/>Einst die Kraft ich wollte,<br/>Jetzt den starken Gott;<br/>Einst mir selbst ich diente,<br/>Jetzt mich Ihm anbot.<br/>',NULL,195152,5);
INSERT INTO stanza VALUES('G2110','5','Einst auf Jesus hoffte,<br/>Jetzt ist Er doch mein;<br/>Einst mein Licht nur glimmte,<br/>Jetzt ein heller Schein;<br/>Einst den Tod erwartet,<br/>Jetzt die Herrlichkeit;<br/>Christus, meine Hoffnung,<br/>Lebt in mir allzeit.<br/>',NULL,195153,6);
INSERT INTO stanza VALUES('G2111','1','Ich kam hin zum lebendigen Quell,<br/>Der von droben hinunter frei fließt;<br/>Ich verließ so die Wasser des Streits<br/>Und gelangte zum Elim der Lieb.<br/>Ich trank tief aus dem himmlischen Brunnen,<br/>Meinem Herzensgrund tief er entspringt;<br/>Die Erzählung gelingt keinem Menschen<br/>Von der Freud, die der Tröster mir bringt.<br/>',NULL,195154,1);
INSERT INTO stanza VALUES('G2111','chorus','Oh, komm zum lebendigen Quell,<br/>Zum Brunnen, der ewig frei fließt!<br/>Welche Freud meine Seele genießt,<br/>Denn Christus ist mein Lebensquell!<br/>',NULL,195155,2);
INSERT INTO stanza VALUES('G2111','2','Ich kam hin zu dem Brunnen von Blut,<br/>Der für Schuld und Unreinheit frei quillt,<br/>Der die Kleider von Sündflecken reinigt;<br/>Alle Anklagen sind nun gestillt.<br/>Mit Gerechtigkeit bin ich umkleidet,<br/>Die in Jesus mir wurde zuteil;<br/>Ich hab Anteil an Seiner Natur<br/>Und in Ihm find ich mein ganzes Heil.<br/>',NULL,195156,3);
INSERT INTO stanza VALUES('G2111','3','Ich kam hin zu dem Brunnen des Heils,<br/>Zur Versorgung so maßlos und frei;<br/>Weder Weisheit noch Geld dieser Erde<br/>Das Geheimnis entschlüsselt dabei.<br/>Doch den Schlüssel enthüllte mein Herr,<br/>Wie die Flut Seiner Seite entströmt,<br/>Wie die Wunden der Striemen mich heilen,<br/>Wie Er kommt und bei mir ewig wohnt.<br/>',NULL,195157,4);
INSERT INTO stanza VALUES('G2111','4','Ich kam hin zu dem Brunnen der Freud,<br/>Seine Freude ist mir Herzenskraft;<br/>Und mein Sonnenschein kann nie verschwinden<br/>Noch die Wonne, die Er mir verschafft.<br/>Der Feigenbaum stirbt und vertrocknet,<br/>Das Vergnügen der Welt umso mehr;<br/>Doch wie kann denn mein Brunnen versiegen?<br/>Mein Anteil und Freud ist der Herr.<br/>',NULL,195158,5);
INSERT INTO stanza VALUES('G2112','1','Es gibt ein Lied tief in mir,<br/>Das erzählt von Jesus, der in meinem Herzen Sich bewegt.<br/>Ja, Jesus lebt in mir und<br/>Pflanzt dort Blumen von Sich Selbst -- mit Lieb bewässere ich sie.<br/>',NULL,195159,1);
INSERT INTO stanza VALUES('G2112','chorus','Ich liebe Jesus. Er ist so lieblich,<br/>Seine Persönlichkeit so stark.<br/>Er bracht mich zu Sich Selbst<br/>Und sagt zu mir: „Alles, was dein Herz begehrt, findest du in Mir.<br/>Ich bin, was du brauchst, und Ich liebe dich."<br/>',NULL,195160,2);
INSERT INTO stanza VALUES('G2112','2','Es gibt ein''n Frieden in mir,<br/>Der entsprang tiefer Zufriedenheit<br/>Mit meinem lieben Herrn.<br/>Denn meine Freude ist in<br/>Dem Lebendigen in mir,<br/>Der Selbst mein Ein und Alles ist.<br/>',NULL,195161,3);
INSERT INTO stanza VALUES('G2113','1','Herr, Du bist mein einz''ges Ziel.<br/>Die Hoffnung dazu.<br/>Ich kümmer mich nur um Dich.<br/>Ich könnt Dich nie ersetzen.<br/>Das würd ich niemals wollen.<br/>Herr, ich habe alles --<br/>Ich hab Dich!<br/>',NULL,195162,1);
INSERT INTO stanza VALUES('G2113','2','Herr, ich lebe nur für Dich --<br/>Nichts anderes mehr.<br/>Du die Quell all meines Tuns.<br/>Nie mehr gute Absicht,<br/>Richtig oder falsch,<br/>Kein „gutes" Leben --<br/>Ich will Dich!<br/>',NULL,195163,2);
INSERT INTO stanza VALUES('G2114','1','Als Leben, Herr, bist Du in mir,<br/>Und alles jetzt für mich!<br/>Du bist verfügbar, subjektiv,<br/>Und so erfahr ich Dich.<br/>',NULL,195164,1);
INSERT INTO stanza VALUES('G2114','chorus','O Herr, Du bist der Geist jetzt!<br/>Wie kostbar und so nah!<br/>Dass Du allzeit verfügbar bist,<br/>Ist einfach wunderbar!<br/>',NULL,195165,2);
INSERT INTO stanza VALUES('G2114','2','Was ich auch brauch, Du Herr versorgst<br/>Mit Dir mich wunderbar;<br/>Zur rechten Zeit, genügend auch,<br/>Für mich nun anwendbar.<br/>',NULL,195166,3);
INSERT INTO stanza VALUES('G2114','3','Und Deine süße Salbung, Herr,<br/>In Schwachheit stützt mit Macht;<br/>Der stete Zustrom Deiner Kraft<br/>Mich stärkt und neu entfacht.<br/>',NULL,195167,4);
INSERT INTO stanza VALUES('G2114','4','Und Dein Gesetz des Lebens mein<br/>Verhalten reguliert;<br/>Der Reichtum Deiner Wirklichkeit<br/>Mein Sein ganz infundiert.<br/>',NULL,195168,5);
INSERT INTO stanza VALUES('G2114','5','Die Einheit, liebster Herr, mit Dir<br/>Ist einfach Herrlichkeit!<br/>Du bist ein Geist mit mir, o Herr,<br/>In alle Ewigkeit!<br/>',NULL,195169,6);
INSERT INTO stanza VALUES('G2115','1','Zu Sich zieht Jesus unsre Herzen jeden Tag noch mehr,<br/>Er ist wie frischer Tau, der Allerschönste ist der Herr;<br/>Es fehlen uns die Worte, Er ist einfach wunderbar,<br/>Und täglich wird Er teurer als Er''s jemals vorher war.<br/>',NULL,195170,1);
INSERT INTO stanza VALUES('G2115','chorus','Selbst halb so viel des Schatzes ist rein unvorstellbar,<br/>Und täglich wird Er teurer als Er''s jemals vorher war!<br/>',NULL,195171,2);
INSERT INTO stanza VALUES('G2115','2','Als wir Ihn sahen klar und hell in der Gemeinde hier,<br/>Erschien uns Seine Herrlichkeit, welch Reichtum fanden wir;<br/>Gestillt wird hier die Sehnsucht unsres Geistes immerdar,<br/>Und täglich wird Er teurer als Er''s jemals vorher war.<br/>',NULL,195172,3);
INSERT INTO stanza VALUES('G2115','3','Nun wohnt Er als der Geist des Lebens stets in unsrem Geist,<br/>Mit Seiner süßen Salbung uns Sein Leben unterweist!<br/>Befreit fließt unser Geist in der Versammlung wunderbar,<br/>Und täglich wird Er teurer als Er''s jemals vorher war.<br/>',NULL,195173,4);
INSERT INTO stanza VALUES('G2115','4','Der Herr hat uns für Seinen Plan und Herzenswunsch vereint:<br/>Nun die Gemeinde als die Fülle Christi herrlich scheint.<br/>Für diesen Vorsatz geben wir uns Ihm nun völlig dar,<br/>Und täglich wird Er teurer als Er''s jemals vorher war.<br/>',NULL,195174,5);
INSERT INTO stanza VALUES('G2116','1','Christus fanden wir, der alles ist,<br/>Allumfassend anwendbar;<br/>Wer Ihn anruft, reich gesegnet ist,<br/>Oh, wie göttlich, wunderbar!<br/>',NULL,195175,1);
INSERT INTO stanza VALUES('G2116','chorus','Es ist Freude, unsagbare Herrlichkeit<br/>Welch Herrlichkeit, welch Herrlichkeit!<br/>Es ist Freude, unsagbare Herrlichkeit<br/>Nicht die Hälfte wurde je gesagt!<br/>',NULL,195176,2);
INSERT INTO stanza VALUES('G2116','2','Wir entdeckten: Christus ist der Geist,<br/>Der in unsrem Geist nun wohnt;<br/>Wie verfügbar und so nah ist Er!<br/>Christi Süße reich belohnt.<br/>',NULL,195177,3);
INSERT INTO stanza VALUES('G2116','3','Hier der Weg, wie du durch Christus lebst:<br/>Bet Sein Wort und ruf Ihn an!<br/>Dies -- das Essen, Trinken -- uns belebt,<br/>Kostbar ist dies zu erfahrn.<br/>',NULL,195178,4);
INSERT INTO stanza VALUES('G2116','4','Die Gemeinde ist an jedem Ort<br/>Ein Zuhause voll Genuss!<br/>Nicht mehr wandern wir in Babylon,<br/>Leben hier im Überfluss.<br/>',NULL,195179,5);
INSERT INTO stanza VALUES('G2116','5','Sich zu treffen mit den Heiligen,<br/>Ist die größte Freud auf Erd;<br/>Hier wird unser Geist stets angefacht,<br/>Und das Leben voller Wert.<br/>',NULL,195180,6);
INSERT INTO stanza VALUES('G2117','1','Ihn berühren ist das, worauf es ankommt.<br/>Und dein Leben ist nicht mehr, wie es war.<br/>Nur einen Weg gibt''s, Ihn wirklich zu berühren:<br/>Glaube nur und ruf Sein''n Namen an!<br/>',NULL,195181,1);
INSERT INTO stanza VALUES('G2118','1','Oh! die Freude, nichts zu haben,<br/>Nichts zu sein und nichts zu sehen<br/>Als nur Christus -- lebend, herrlich!<br/>Und um nichts besorgt zu sein.<br/>Oh! die Freude, nichts zu haben,<br/>Nichts zu sein und nichts zu sehen<br/>Als nur Christus -- lebend, herrlich!<br/>Und Sein''n Vorsatz auf der Erd!<br/>',NULL,195182,1);
INSERT INTO stanza VALUES('G2119','1','Herr Jesus, ich lieb Dich. Ich weiß, Du bist mein;<br/>Für Dich lass ich Sündenvergnügungen sein;<br/>Du bist mein Erlöser, in Dir will ich ruhn,<br/>Noch nie hab ich Dich, Herr, geliebt so wie nun.<br/>',NULL,195183,1);
INSERT INTO stanza VALUES('G2119','2','Ich lieb Dich, weil Du, Herr, zuerst liebtest mich,<br/>Vergebung Du schenktest, das Kreuz nahmst auf Dich;<br/>Für mich ließt Du Dornen an Deine Stirn tun,<br/>Noch nie hab ich Dich, Herr, geliebt so wie nun.<br/>',NULL,195184,2);
INSERT INTO stanza VALUES('G2119','3','Im Leben, im Tod, werd ich noch lieben Dich,<br/>Ich preis Dich, solange der Atem füllt mich;<br/>Und lieg ich im Sterben, doch kund möcht ich tun:<br/>Noch nie hab ich Dich, Herr, geliebt so wie nun.<br/>',NULL,195185,3);
INSERT INTO stanza VALUES('G2119','4','In endloser Freude der ewigen Zeit<br/>Dann lieb ich Dich lobpreisend in Herrlichkeit;<br/>Mit glitzernder Krone singen werd ich tun,<br/>Noch nie hab ich Dich, Herr, geliebt so wie nun.<br/>',NULL,195186,4);
INSERT INTO stanza VALUES('G2120','1','Liebster Jesus, teurer Jesus,<br/>Oh, ich liebe Dich so sehr!<br/>Wer wie Du ist schön und lieblich?<br/>Wer wie Du ist süß und friedlich?<br/>Voller Anmut, unvergleichlich,<br/>Niemand kommt Dir gleich, o Herr!<br/>',NULL,195187,1);
INSERT INTO stanza VALUES('G2120','2','Liebster Jesus, teurer Jesus,<br/>Gerne hör ich Deinen Ruf;<br/>Deine Worte mich besiegen,<br/>Eitelkeiten nun versiegen;<br/>Andres lass ich stehn und liegen,<br/>Möcht bei Dir sein allezeit.<br/>',NULL,195188,2);
INSERT INTO stanza VALUES('G2120','3','Liebster Jesus, teurer Jesus,<br/>Macht mein Sträuben denn noch Sinn?<br/>Wirf die Härte vor Dich nieder!<br/>Voller Lobpreis komm ich wieder;<br/>Herr, ich weih Dir meine Glieder,<br/>Ich gehorche Dir mit Freud.<br/>',NULL,195189,3);
INSERT INTO stanza VALUES('G2120','4','Liebster Jesus, teurer Jesus,<br/>Ich will wählen Deinen Weg;<br/>Beim Gehorchen auch trotz Tränen<br/>Möcht ich treu sein Deinen Plänen;<br/>Deine Freude ist mein Sehnen,<br/>Deine Liebe macht mich still.<br/>',NULL,195190,4);
INSERT INTO stanza VALUES('G2120','5','Liebster Jesus, teurer Jesus,<br/>Wenn fehlt Deine Gegenwart,<br/>Morgendämmrung ist verschwommen,<br/>Mir mein Lächeln ist genommen;<br/>Ich schau nur nach Deinem Kommen<br/>Und nach Deinem Angesicht.<br/>',NULL,195191,5);
INSERT INTO stanza VALUES('G2120','6','Liebster Jesus, teurer Jesus,<br/>Wie nur sag ich alles Dir?<br/>Ja, für Dich in Lieb ich brenne,<br/>Als mein Anteil Dich erkenne;<br/>Du bist das, was ich ersehne,<br/>Dir allein nur jag ich nach.<br/>',NULL,195192,6);
INSERT INTO stanza VALUES('G2120','7','Liebster Jesus, teurer Jesus,<br/>Für Dich geb ich alles her;<br/>Wer wie Du ist schön und lieblich?<br/>Wer wie Du ist süß und friedlich?<br/>Voller Anmut, unvergleichlich,<br/>Niemand kommt Dir gleich, o Herr!<br/>',NULL,195193,7);
INSERT INTO stanza VALUES('G2121','1','Deine Schönheit, Herr, hat mich gefangen,<br/>Dir nur öffne ich mein Herz jetzt weit;<br/>Religiöse Pflichten sind vergangen,<br/>In Dir lass mich bleiben allezeit.<br/>Wenn ich Deine Herrlichkeit hier sehe,<br/>Nun erfüll mein Herz mit Strahlenglanz!<br/>Herr, durchtränke mich! Dies ich erflehe,<br/>Deinen Geist vermeng mit meinem ganz!<br/>',NULL,195194,1);
INSERT INTO stanza VALUES('G2121','2','Scheinender! -- im offnen Himmel seh ich<br/>Dich, den Sohn des Menschen, auf dem Thron!<br/>Heiliger, nun Gottes Flamm verzehrt mich,<br/>Bis aus mir strahlt nur Deine Person.<br/>Als ich Dich in Deinem hellen Glanz sah,<br/>Sank beschämt all Eigenherrlichkeit;<br/>Nun mein Herz bringt Liebe Dir und Lob dar<br/>Und schmeckt Deines Namens Lieblichkeit.<br/>',NULL,195195,2);
INSERT INTO stanza VALUES('G2121','3','Teurer Herr, mein Fläschchen Alabaster<br/>Nun aus Liebe Dir zerbreche ich,<br/>Und ich salb Dein Haupt, geliebter Meister;<br/>Sieh, das Beste hob ich auf für Dich.<br/>Liebster, ich will mich auf Dich verschwenden,<br/>Dich zu lieben, mich zufriedenstellt;<br/>Liebe strömt aus meinem tiefen Innern,<br/>Teures Öl ist Dir bereitgestellt.<br/>',NULL,195196,3);
INSERT INTO stanza VALUES('G2121','4','Liebster, komm zum Berg mit den Gewürzen!<br/>Wie Dein Angesicht stark ich ersehn!<br/>Trinke, Herr, vom Quell aus meinem Herzen,<br/>Bis in Deinem Arm ich ewig lehn!<br/>Dich verehre ich, Herr, nicht alleine:<br/>Deine liebe Braut stimmt mit mir ein;<br/>Liebster, Dich erwartet unsre Liebe,<br/>Komm doch schnell! Du wirst zufrieden sein.<br/>',NULL,195197,4);
INSERT INTO stanza VALUES('G2122','1','Jesus, Herr, danke, dass<br/>Du starbst dort am Kreuz für mich.<br/>Dein Erbarmen, mein Retter, fand mich.<br/>Du hast den höchsten Preis bezahlt,<br/>Ja, Du gabst Dein Leben hin --<br/>Mein Leben soll Dir nun gehörn.<br/>Und, Herr, ich wend mich niemals von Deiner Liebe ab,<br/>Der ew''gen Liebe, die Du zu mir hast.<br/>Ich geb Dir mein Herz,<br/>Herr, breit Dich darin aus,<br/>Bis mein ganzes Herz Dir gehört!<br/>',NULL,195198,1);
INSERT INTO stanza VALUES('G2122','2','Herr, nimm mein Herz mir ein!<br/>Es soll einfach und sauber sein,<br/>Kein'' andere Liebe kenn ich.<br/>Und, Herr, ich liebe Dich so sehr,<br/>Denn Du bist so lieblich,<br/>Mein Alles, mein lieblicher Herr.<br/>Und, Herr, diese Person in mir möcht ich kennenlernen.<br/>Herr, halt mein Herz offen für Dich!<br/>Lass fließen Dein Leben<br/>In mich, damit ich wachs<br/>Und werde durchsättigt mit Dir!<br/>',NULL,195199,2);
INSERT INTO stanza VALUES('G2123','1','Du bist mein Geliebter, der Schönste bist Du.<br/>Lieblich, sanft und freundlich, ganz reizend dazu.<br/>Du bist''s! Dein Dasein ist -- das, was ich such;<br/>Mein Herz erfreut sich zutiefst an Dir,<br/>Ich liebe''s, Dir zu sagen...<br/>',NULL,195200,1);
INSERT INTO stanza VALUES('G2123','chorus','Jesus, ich lieb Dich.<br/>Mein Schatz, Herr, bist Du.<br/>Wie kann ich was anderes als Dich erwähln?<br/>Herr, Du hast gewonnen mein innerstes Herz.<br/>',NULL,195201,2);
INSERT INTO stanza VALUES('G2123','2','Ich war tot in Sünde, verlorn ohne Dich.<br/>Hilflos, leidend, müde, rebellisch war ich.<br/>Doch, Herr, Du kamst und Du ließt mich nicht los.<br/>Wasser und Blut flossen von Dir aus<br/>Und drängen mich zu sagen...<br/>',NULL,195202,3);
INSERT INTO stanza VALUES('G2123','3','Liebster Herr, Du hast mir die Augen aufgetan,<br/>Du hast mich geheilt, ich kann gehn -- war doch lahm!<br/>Mein''n Aussatz hast Du, Herr, ganz rein gemacht.<br/>Ich kann jetzt hören, wie Du mich rufst.<br/>Ich laufe Dir jetzt nach, denn...<br/>',NULL,195203,4);
INSERT INTO stanza VALUES('G2123','4','Meine Sorgen blenden mich oft ungemein<br/>Und die Welt verlockt mich mit trügerischem Schein.<br/>Du hast mich gefangen, Herr. Lass mich nicht los!<br/>Küss mich, umwirb mich, gewinn mein Herz,<br/>Bis ich Dir immer sage...<br/>',NULL,195204,5);
INSERT INTO stanza VALUES('G2123','5','Mach mein Herz so weich, halt es offen in mir!<br/>Als die gute Erde soll''s Frucht bringen Dir.<br/>Meine Freunde fange und bau uns nun auf!<br/>Als Deine Braut sind wir ganz wie Du<br/>und sagen Dir zusammen...<br/>',NULL,195205,6);
INSERT INTO stanza VALUES('G2123','chorus','Komm schnell, Herr Jesus!<br/>Wir warten auf Dich.<br/>Wir sind Dir die Jungfraun,<br/>So rein und so treu.<br/>Für immer und ewig Dein Antlitz wir schaun.<br/>',NULL,195206,7);
INSERT INTO stanza VALUES('G2124','1','Herr, ich liebe Dich.<br/>Es gibt niemand wie Dich.<br/>Im ganzen Universum<br/>Hab ich keinen anderen wie Dich.<br/>Herr Jesus, ich lieb Dich.<br/>',NULL,195207,1);
INSERT INTO stanza VALUES('G2125','1','Herr, Du bist die erste Lieb.<br/>Dich allein nur lieben wir.<br/>Wenn das Herz Dich völlig liebt,<br/>Süße Ruhe schmecken wir.<br/>',NULL,195208,1);
INSERT INTO stanza VALUES('G2125','2','Dich, Herr, Selbst nur lieben wir,<br/>Mehr als was Du hast getan;<br/>Nichts ja gleicht, Geliebter, Dir<br/>Und der Freude Deines Nahns.<br/>Viele Dinge habn uns abgelenkt --<br/>Unser Herz doch neu zu Dir sich wend!<br/>Wir tun Buße, weil uns andres fängt --<br/>Herr, Du bist die erste Lieb.<br/>',NULL,195209,2);
INSERT INTO stanza VALUES('G2125','3','Nichts soll Dich ersetzen, Herr.<br/>Ich möcht nur noch Dich allein.<br/>Nur dies eine ich begehr:<br/>Ganz mit Dir gefüllt zu sein.<br/>',NULL,195210,3);
INSERT INTO stanza VALUES('G2125','4','Herr, Du bist die erste Lieb.<br/>Dich allein nur lieben wir.<br/>Wenn das Herz Dich völlig liebt,<br/>Süße Ruhe schmecken wir.<br/>',NULL,195211,4);
INSERT INTO stanza VALUES('G2126','1','In Zeiten wie diesen sing ich ein Lied,<br/>Ein Liebeslied für den Herrn Jesus.<br/>In Zeiten wie diesen sing ich ein Lied,<br/>Da sing ich ein Lied meinem Herrn.<br/>',NULL,195212,1);
INSERT INTO stanza VALUES('G2126','chorus','Singe: Ich liebe Dich.<br/>Singe: Ich liebe Dich.<br/>Singe: Ich liebe Dich, Herr.<br/>Ich liebe Dich.<br/>',NULL,195213,2);
INSERT INTO stanza VALUES('G2126','2','In Zeiten wie diesen ruf ich zum Herrn.<br/>Rufe „Herr Jesus" -- Er rettet.<br/>In Zeiten wie diesen ruf ich zum Herrn.<br/>Dann ruf ich, und Er rettet mich.<br/>',NULL,195214,3);
INSERT INTO stanza VALUES('G2126','chorus','Rufe: „Oh Jesus, Herr!"<br/>Rufe: „Oh Jesus, Herr!"<br/>Rufe: „Oh, Herr Jesus!"<br/>Jesus ist Herr!<br/>',NULL,195215,4);
INSERT INTO stanza VALUES('G2127','1','Ich will Dich berühren, Herr,<br/>Will Dir in die Augen sehn,<br/>Nur ein Kuss von Dir,<br/>Mein Liebster, ich brauch Dich!<br/>',NULL,195216,1);
INSERT INTO stanza VALUES('G2127','2','Lass mich Deine Stimme hörn!<br/>Ich will immer nur Dich wähln.<br/>Sprich in Lieb zu mir!<br/>Verschwende mich auf Dich.<br/>',NULL,195217,2);
INSERT INTO stanza VALUES('G2127','chorus','Nichts sonst und niemand stellt mich zufrieden<br/>als nur Du, mein Herr.<br/>Jesus, ich lieb Dich, mein einzig Verlangen.<br/>O Herr, ich liebe nur Dich.<br/>',NULL,195218,3);
INSERT INTO stanza VALUES('G2127','3','Dich berühren wie vorher!<br/>Mich verlangt nach Dir noch mehr.<br/>Du der Beste bist!<br/>Ich lass alles für Dich.<br/>',NULL,195219,4);
INSERT INTO stanza VALUES('G2127','4','Oh, die Küsse deines Munds --<br/>Ich tu Deinen Lobpreis kund.<br/>Du bist voller Gnad,<br/>Mein Liebster, welch Genuss!<br/>',NULL,195220,5);
INSERT INTO stanza VALUES('G2127','chorus','Nichts sonst und niemand stellt mich zufrieden<br/>als nur Du, mein Herr.<br/>Die erste Liebe sollst du neu entfachen<br/>Für Dich, mein einzig Begehr.<br/>',NULL,195221,6);
INSERT INTO stanza VALUES('G2127','5','Nur ein Blick von Dir erhellt -<br/>Einheit, die zufriedenstellt!<br/>Wenn ich Dich anschau,<br/>Werd ich gefüllt mit Dir.<br/>',NULL,195222,7);
INSERT INTO stanza VALUES('G2127','6','Bist der Einzige für mich.<br/>Oh, ich schaff''s nicht ohne Dich.<br/>Halt mich nah bei Dir,<br/>Als eins vereint mit Dir!<br/>',NULL,195223,8);
INSERT INTO stanza VALUES('G2127','chorus','Nichts sonst und niemand stellt mich zufrieden<br/>als Du, mein Herr.<br/>Jesus, ich lieb Dich, mein einzig Verlangen.<br/>Oh Herr, entfache mein Herz!<br/>',NULL,195224,9);
INSERT INTO stanza VALUES('G2127','7','Ich tu Buße, wende mich,<br/>Lass mein Herz brennen für Dich.<br/>Eifer weck in mir!<br/>Sei Wirklichkeit in mir!<br/>',NULL,195225,10);
INSERT INTO stanza VALUES('G2127','8','Ich tu Buße, wende mich,<br/>Lass mein Herz brennen für Dich.<br/>Eifer weck in mir!<br/>Sei Wirklichkeit in mir!<br/>',NULL,195226,11);
INSERT INTO stanza VALUES('G2127','chorus','Jesus, mein Liebster, o Jesus, mein Bester,<br/>Ich kehre um zu Dir.<br/>Jesus, mein Liebster, o Jesus, mein Bester,<br/>Ich lieb Dich, ich liebe nur Dich!<br/>',NULL,195227,12);
INSERT INTO stanza VALUES('G2128','1','Herr, ich lieb Dich!<br/>Herr, nimm mein Herz!<br/>Herr, durchdring mich!<br/>Mit göttlichem Leben fülle jeden Teil!<br/>Herr, ich unterwerfe mich ganz Dir.<br/>Wende mich jeden Tag ganz hin zu Dir,<br/>Bis ich nur noch Dich zum Ausdruck bring allzeit!<br/>Bis ich nur noch Dich zum Ausdruck bring.<br/>',NULL,195228,1);
INSERT INTO stanza VALUES('G2128','2','Herr, brenne in uns!<br/>Mach uns zu Deiner Braut!<br/>Herr, durchdring uns!<br/>Mit göttlichem Leben fülle jeden Teil!<br/>Herr, wir unterwerfen uns ganz Dir.<br/>Wende uns jeden Tag ganz hin zu Dir,<br/>Bis wir nur noch Dich zum Ausdruck bringn, allzeit!<br/>Bis wir nur noch Dich zum Ausdruck bringn.<br/>',NULL,195229,2);
INSERT INTO stanza VALUES('G2129','1','O Herr, ich lieb Dich,<br/>Ich lieb Dich wirklich.<br/>Ohne Dich ist das Leben nichts wert.<br/>Du bist so anziehend<br/>Und bezaubernd dazu.<br/>Deine Reichtümer unerforschlich,<br/>Dein Nam'' ist lieb und süß --<br/>Rufen uns zufriedenstellt.<br/>Jetzt bist Du mein und ich bin Dein, Herr,<br/>Mit Dir eins und vermengt --<br/>Gott-Mensch-Einverleibung,<br/>Vorgeschmack des Neu''n Jerusalem.<br/>',NULL,195230,1);
INSERT INTO stanza VALUES('G2130','1','Ich lieb Gott, aus ganzem Herzen,<br/>Aus ganzer Seel.<br/>Ich liebe meinen Herrn so sehr!<br/>Ich lieb den Herrn aus ganzem Herz''n<br/>Und jedem Teil meiner Seel.<br/>',NULL,195231,1);
INSERT INTO stanza VALUES('G2130','2','Ich lieb Dich, Jesus Herr,<br/>Aus ganzem Herz''n und aus ganzer Seel.<br/>Du bist der Einzige auf der ganzen Welt<br/>Für mich, o Herr.<br/>',NULL,195232,2);
INSERT INTO stanza VALUES('G2130','3','Ich lieb den Herrn und ich weiß, Er liebt auch mich.<br/>Ich lieb die Bibel -- les ich, so wachse ich.<br/>In der Gemeinde mit allen Heiligen<br/>Sing ich, bet ich, ruf ich Seinen Nam''n<br/>',NULL,195233,3);
INSERT INTO stanza VALUES('G2130','4','Ich lieb Gott, ich lieb Gott,<br/>Ich lieb Gott aus ganzem Herz''n,<br/>Aus ganzer Seel,<br/>Aus ganzer Stärk''.<br/>Ich werd Ihn lieben ewiglich.<br/>',NULL,195234,4);
INSERT INTO stanza VALUES('G2131','1','Wo haben sie Ihn denn nur hingelegt?<br/>Der Stein ist von dem Grab hinweg gerollt.<br/>Sie haben Ihn doch fortgebracht!<br/>Ach! Wo ist Er?<br/>',NULL,195235,1);
INSERT INTO stanza VALUES('G2131','2','Die Jünger kamen zu dem leeren Grab,<br/>Doch gingen kurz darauf zurück nach Haus.<br/>Tatsachen reichten ihnen aus,<br/>Doch wo ist Er?<br/>',NULL,195236,2);
INSERT INTO stanza VALUES('G2131','chorus','Wo ist Er, mein Jesus?<br/>Wo ist Er, der mir lieb?<br/>Wo ist Er, den meine Seele liebt?<br/>Jesus, mein Schatz, ich will nur Dich.<br/>',NULL,195237,3);
INSERT INTO stanza VALUES('G2131','3','An dieser tiefen Not zerbrach mein Herz.<br/>Fragt nicht, ihr Engel, was ich weine.<br/>Nichts außer Jesus füllt mein innres Sein,<br/>Ach! Wo ist Er?<br/>',NULL,195238,4);
INSERT INTO stanza VALUES('G2131','4','Es steht da jemand direkt hinter mir,<br/>Es ist der Gärtner, kann ihn fast nicht sehn.<br/>Oh, haben Sie Ihn weggebracht?<br/>Ach! Wo ist Er?<br/>',NULL,195239,5);
INSERT INTO stanza VALUES('G2131','chorus','Wo ist Er, mein Jesus?<br/>Wo ist Er, der mir lieb?<br/>Wohin haben Sie Ihn gelegt?<br/>Und ich trage Ihn hinweg, ich trage Ihn hinweg.<br/>',NULL,195240,6);
INSERT INTO stanza VALUES('G2131','5','Dann sagte eine Stimm: „Maria!" --<br/>Die süße Stimme drang in mich hinein,<br/>Die Stimme meines lieben Herrn --<br/>Jesus, mein Schatz.<br/>',NULL,195241,7);
INSERT INTO stanza VALUES('G2131','chorus','Ich fand meinen Jesus!<br/>Ich fand Ihn, mir so lieb!<br/>Ich fand Ihn, den meine Seele liebt --<br/>Jesus, mein Schatz, ich lieb nur Dich!<br/>',NULL,195242,8);
INSERT INTO stanza VALUES('G2131','6','Doch Jesus sagte mir: „Berühr Mich nicht!<br/>Ich muss noch auffahren zum Vater,<br/>Zu Meinem Vater, eurem Vater,<br/>Meinem Gott, eurem Gott.<br/>',NULL,195243,9);
INSERT INTO stanza VALUES('G2131','chorus','Sag es Meinen Brüdern!<br/>Ich fahr auf zu dem Vater,<br/>Meinem Vater, eurem Vater,<br/>Meinem Gott, eurem Gott; Geh, sag''s den Brüdern!"<br/>',NULL,195244,10);
INSERT INTO stanza VALUES('G2132','1','Gott will, dass wir Ihn lieben,<br/>Anstatt Ihm nur zu dienen.<br/>Er will, dass wir Ihn lieben<br/>Als Seine Braut.<br/>Wir sollen Ihm entsprechen<br/>Anstatt Ihn nachzuahmen.<br/>Er will ein Ebenbild, das aus Ihm kommt.<br/>',NULL,195245,1);
INSERT INTO stanza VALUES('G2132','chorus','Dazu kam Er nieder zur Erd,<br/>Er kam, damit Er uns umwerb.<br/>Er zieht uns weg von allem<br/>Hin zu Ihm.<br/>Jetzt sind wir schon mit Ihm vermählt,<br/>Sind Ihm versprochen, sind verlobt.<br/>Wir sind durch Seine Liebe<br/>Eins mit Ihm.<br/>',NULL,195246,2);
INSERT INTO stanza VALUES('G2132','2','Gott will, dass wir Ihn lieben,<br/>Nicht nur, dass wir Ihn fürchten.<br/>Er will, dass wir Sein Schatz sind,<br/>Seine Braut.<br/>Gott will, dass wir Ihn kennen,<br/>Nicht nur viel von Ihm wissen.<br/>Er will, dass jemand Ihn ganz tief anschaut.<br/>',NULL,195247,3);
INSERT INTO stanza VALUES('G2133','1','Ich bin bezaubert von Deiner Liebe,<br/>Angezogen von Dir.<br/>Deine Süße zieht mich an, ich folg Dir,<br/>Bis ich ganz zufrieden bin.<br/>Ich lieb Dich, ich lieb Dich, ich lieb Dich.<br/>Du bist der Allerschönste.<br/>',NULL,195248,1);
INSERT INTO stanza VALUES('G2133','2','Ich bin gefangen von Deinem Namen<br/>Und entzückt von Dir.<br/>Wohlgerüche hülln mich ein, mich gewinnst<br/>Mit den Küssen Deines Mundes!<br/>Ich lieb Dich, ich lieb Dich, ich lieb Dich.<br/>Du bist der Lieblichste.<br/>',NULL,195249,2);
INSERT INTO stanza VALUES('G2133','3','In Gemeinschaft lieb ich Dich<br/>Und erfreu mich an Dir.<br/>In den Kammern genieß ich unsre Lieb<br/>Für die Gemeinde, Deine Freude.<br/>Ich lieb Dich, ich lieb Dich, ich lieb Dich.<br/>Du bist der Vertrauteste.<br/>Ich lieb Dich.<br/>',NULL,195250,3);
INSERT INTO stanza VALUES('G2134','1','Herr, ich setz mein Herz;<br/>Herr, ich liebe nur Dich.<br/>Daneben hab ich kein andres Verlangen.<br/>Herr, ich möchte nur Dich leben.<br/>',NULL,195251,1);
INSERT INTO stanza VALUES('G2134','chorus','Herr, ich liebe Dich,<br/>Weil Du mich so sehr liebst.<br/>Ich will nur Dich leben und<br/>Unter Deinem unmittelbaren Leiten bleiben.<br/>',NULL,195252,2);
INSERT INTO stanza VALUES('G2134','2','Auf der ganzen Erd,<br/>Im Universum auch<br/>Hab ich kein andres Intresse, Verlangen.<br/>Mein Verlangen bist einzig Du.<br/>',NULL,195253,3);
INSERT INTO stanza VALUES('G2134','3','Danke, liebster Herr;<br/>Du hast mich vorherbestimmt.<br/>Du hast mich berufen, gerettet, bewahrt, Herr,<br/>Und mich bis hierher gebracht.<br/>',NULL,195254,4);
INSERT INTO stanza VALUES('G2135','1','Dich zu lieben ist''s, wofür ich leb.<br/>Bis zum Äußersten lieb ich Dich, Herr.<br/>Oh, vergib mir, falls ich verließ der Braut<br/>Erste Liebe zu Dir, Herr!<br/>Du bist mehr als jeder, den ich lieb,<br/>Du bist mehr als alles, was ich hab,<br/>Sogar als mein Selbst. Nichts vergleichbar ist<br/>Meinem lieben Bräutigam.<br/>',NULL,195255,1);
INSERT INTO stanza VALUES('G2135','chorus','Ich geb Dir durch Glauben jetzt den ersten Platz<br/>In meinem Herzen -- Du bist ja mein Schatz.<br/>Herr, durchdring mich überströmend mit Dir,<br/>Bis ich vor Dir steh!<br/>Lass mich niemals von Dir gehen!<br/>',NULL,195256,2);
INSERT INTO stanza VALUES('G2135','2','Du darfst alles nehmen, was ich lieb,<br/>Doch ersetz es umso mehr mit Dir.<br/>Du bist, was ich brauch, und ich hab Dich auch.<br/>Gib nicht alles, was ich will.<br/>Alles geht mit Sicherheit vorbei,<br/>Menschen gehen ihren eignen Weg,<br/>Doch ich habe Dich und Du hast ja mich --<br/>Süße Liebe zwischen uns.<br/>',NULL,195257,3);
INSERT INTO stanza VALUES('G2135','3','Ich schätze die Zeit allein mit Dir.<br/>Hier gewinne ich die erste Lieb.<br/>Lieber Bräutigam, ziehe mich Dir nach,<br/>Führ in Deine Kammern mich!<br/>Sei das Haupt in meinem Leben, Herr!<br/>Und in meinem ganzen Werk und Dienst<br/>In Beziehungen Du der Erste bist,<br/>Du den Vorrang hast in mir.<br/>',NULL,195258,4);
INSERT INTO stanza VALUES('G2136','1','Nichts mich mehr zufrieden stellt<br/>Als Jesus jeden Morgen.<br/>Freude strömt im Innern meines Herzens.<br/>Wenn aus der Dunkelheit ich geh<br/>Und in Sein liebend Antlitz seh,<br/>Weiß ich für dieses Leben einen Grund.<br/>Jesus, Du bist der Grund, weshalb ich bin.<br/>Du gibst mir Sinn, drum ich sing!<br/>',NULL,195259,1);
INSERT INTO stanza VALUES('G2136','2','Keine größre Freud ich kenn -- ich<br/>Wende mich zu Jesus, wenn die<br/>Tagesschatten fangen an zu quälen.<br/>Sein Geist und Leben dringen durch,<br/>Löschen Zweifel und die Furcht:<br/>Jesus ist der Inbegriff der Lieb.<br/>Jesus, Du bist der Grund, weshalb ich bin.<br/>Du gibst mir Sinn, drum ich sing!<br/>(Zweite Strophe wiederholen)<br/>',NULL,195260,2);
INSERT INTO stanza VALUES('G2137','1','Wie wird ein Landmädchen wie ich<br/>Zu Deiner Braut, die Dir entspricht?<br/>Denn Du bist heilig und göttlich,<br/>Ein gefallner Mensch bin ich.<br/>',NULL,195261,1);
INSERT INTO stanza VALUES('G2137','2','Ohne Dich, Herr, kann''s gar nicht sein,<br/>Dass ich mal Dir gleich werde sein.<br/>Doch Dein Plan steht -- vor Beginn der Welt<br/>Hast Du mich auserwählt.<br/>',NULL,195262,2);
INSERT INTO stanza VALUES('G2137','chorus','Dieses Liebespaar<br/>In Mein''m Herzen war.<br/>Dazu wurde Ich ein Mensch,<br/>Mein Landmädchen umwerb.<br/>Meinen ew''gen Plan<br/>Gar nichts ändern kann.<br/>Meine ew''ge Liebe wird<br/>Mein Landmädchen gewinn''n!<br/>',NULL,195263,3);
INSERT INTO stanza VALUES('G2137','3','Kein Mensch noch Engel wusste je<br/>Von dem Geheimnis tief in Dir.<br/>Mit uns eins sein, dies Dein Herz ersann,<br/>Bevor die Welt begann.<br/>',NULL,195264,4);
INSERT INTO stanza VALUES('G2137','4','Als Sünde kam, verdarb sie mich<br/>Durch Satans Trug und Hinterlist.<br/>Nichts Deine Liebe schwächen kann --<br/>Gewinnt mich voll und ganz.<br/>',NULL,195265,5);
INSERT INTO stanza VALUES('G2137','chorus','Dieses Liebespaar<br/>In Mein''m Herzen war.<br/>Dazu wurde Ich ein Mensch,<br/>Mein Landmädchen umwerb.<br/>Meinen ew''gen Plan<br/>Gar nichts ändern kann.<br/>Meine ew''ge Liebe wird<br/>Mein Landmädchen gewinn''n!<br/>',NULL,195266,6);
INSERT INTO stanza VALUES('G2137','5','Als König wurdest Du ein Mensch,<br/>Du starbst für mich -- ich bin erlöst.<br/>In Auferstehung machtest uns<br/>Zur Königin und Braut.<br/>',NULL,195267,7);
INSERT INTO stanza VALUES('G2137','6','Vom Tod standst auf und kamst in mich.<br/>Dein'' Göttlichkeit nun teile ich,<br/>Natur und Leben entsprechen sich,<br/>Sind menschlich und göttlich.<br/>',NULL,195268,8);
INSERT INTO stanza VALUES('G2137','chorus','Deine Lieb zieht mich.<br/>Ich gehör jetzt Dir.<br/>Ich gehöre nicht mehr mir,<br/>Nein, Dir allein.<br/>Deine Liebe zieht<br/>Und Dein Nam betört.<br/>Deine Liebe ist so süß,<br/>Denn Du hast mich geküsst.<br/>',NULL,195269,9);
INSERT INTO stanza VALUES('G2137','7','Wenn ich mit Dir Gemeinschaft hab,<br/>Herr, sei Du mir so süß und nah!<br/>So sehr persönlich und liebevoll,<br/>Beziehung wundervoll.<br/>',NULL,195270,10);
INSERT INTO stanza VALUES('G2137','8','Herr, ändre Du mein inn''res Sein!<br/>Herr, täglich nimm mein Herz ganz ein!<br/>So machst Du mich in Herz und Sinn<br/>Zur Braut und Königin.<br/>',NULL,195271,11);
INSERT INTO stanza VALUES('G2137','chorus','Deine Lieb zieht mich.<br/>Ich gehör jetzt Dir.<br/>Ich gehöre nicht mehr mir,<br/>Nein, Dir allein.<br/>Deine Liebe zieht<br/>Und Dein Nam betört.<br/>Deine Liebe ist so süß,<br/>Denn Du hast mich geküsst.<br/>',NULL,195272,12);
INSERT INTO stanza VALUES('G2138','1','Ihre Lieb goss Maria aus --<br/>Verschwendung sahn viele darin.<br/>Durch die ganzen Jahrhunderte<br/>Hab''n viele Dein'' Süße geschmeckt.<br/>Viele Leben und Schätze gar,<br/>Auch Stellung und goldne Zukunft<br/>Sind an Dich „verschwendet" word''n<br/>-- Dein'' wohlriechend'' Lieblichkeit!<br/>',NULL,195273,1);
INSERT INTO stanza VALUES('G2138','chorus','Sie ergriff Gelegenheit,<br/>Ihr Bestes zu geben für Dich.<br/>Wie sie ihre Lieb ausgoss,<br/>Geb auch ich alles, was ich hab.<br/>',NULL,195274,2);
INSERT INTO stanza VALUES('G2138','2','Weil ich Dich lieb, richt ich mein Sein<br/>-- Mein''n Geist, meine Seele, mein''n Leib --<br/>Mit dem Herz''n, Verstand und der Kraft<br/>Gänzlich auf Dich aus.<br/>Herr, ich möcht, dass mein ganzes Sein<br/>Werd eingenommen von Dir.<br/>Weil Dein Herz mir offen steht,<br/>Lieblich Gemeinschaft ich fühl.<br/>',NULL,195275,3);
INSERT INTO stanza VALUES('G2138','chorus','Ganz verloren bin in Dir,<br/>Herr, Du bist alles für mich.<br/>Innige Gemeinschaft hab,<br/>Im Geist genieße ich Dich.<br/>',NULL,195276,4);
INSERT INTO stanza VALUES('G2138','3','Nicht im Himmel noch auf der Erd<br/>Begehr ich was andres als Dich.<br/>Wenn mein Herz und mein Fleisch versag''n,<br/>Doch Du bleibst immer mein Anteil!<br/>Alles Nichtigkeit, alles Schmutz,<br/>Ich achte alles als Verlust.<br/>Alles andre dämpft die Lieb.<br/>Du hast gefangen mein Herz.<br/>',NULL,195277,5);
INSERT INTO stanza VALUES('G2138','chorus','Herr, ich sah Deine Kostbarkeit,<br/>Dein''n Wert, Deine Lieblichkeit.<br/>Jetzt, mein Herr, bekenne ich,<br/>Mein Herz ist einzig für Dich!<br/>',NULL,195278,6);
INSERT INTO stanza VALUES('G2139','1','Herr Jesus, so lieblich,<br/>Bist kostbarer als jedes<br/>Der irdischen Vergnügen,<br/>So unvergleichlich schön.<br/>Herr Jesus, Deine Schönheit<br/>Ist größer als sonst jede.<br/>Bist anmutig und zärtlich,<br/>So strahlend und bildschön.<br/>',NULL,195279,1);
INSERT INTO stanza VALUES('G2139','2','Wenn ich Dich anseh, Jesus,<br/>Ziehst Du mein Herz ganz zu Dir.<br/>Ich kann mich nicht abwenden,<br/>Ich ruh in Deinem Arm.<br/>Und mit der Zeit bleibt nur noch<br/>Dein unvergleichlich Dasein<br/>Ich bleib in Dir und schaue<br/>Dein herrlich Angesicht.<br/>',NULL,195280,2);
INSERT INTO stanza VALUES('G2139','3','Herr, Dir geb ich mein Leben,<br/>Denn Du allein bist würdig.<br/>Nichts anderes und niemand<br/>Als Dich allein will ich.<br/>All meine Tage geb Dir,<br/>Mein Herz soll nur Dich lieben,<br/>Dich schätzen und Dir dienen<br/>Durch allgenügend Gnad.<br/>',NULL,195281,3);
INSERT INTO stanza VALUES('G2140','1','Oh, wie süß es ist: Christus kenne ich!<br/>Ihn zu kennen, das erstrebe ich.<br/>Will nur Ihn gewinnen Tag für Tag,<br/>Denn Er ist reich und fein auf jede Art.<br/>Völlig gefangen bin ich, mein Alles Er!<br/>Füllt mein Herz mit Glauben, wenn ich rufe: Herr!<br/>Denn Er verbreitet Sich und nimmt in mir zu,<br/>Wenn ich wohne eins mit Ihm immerzu.<br/>',NULL,195282,1);
INSERT INTO stanza VALUES('G2140','2','Als ein Liebesstrom fließt Sein Leben rein!<br/>Unser Herz liebt Christus nur allein.<br/>Herr, wir geben uns hin -- Wachse mehr<br/>In uns, dann sehn wir: Du bist kostbar, Herr.<br/>Du hast uns eins gemacht. Zu Dir laufen nun,<br/>Jagen nach zusamm''n, in allem, was wir tun.<br/>Mit den Heiligen zu voller Reife komm''n,<br/>So zu Deiner liebend Braut werden wir dann.<br/>',NULL,195283,2);
INSERT INTO stanza VALUES('G2141','1','Jesus Herr, mein Herz gehört Dir.<br/>Meine beste Liebe ist hier.<br/>Auf der ganzen Erd, in den Himmeln auch<br/>Gibt es nichts so Schönes wie Dich.<br/>Deine Stimme höre ich gern,<br/>Sie ist meinem Herzen nicht fern.<br/>Die vergangnen Lieben ziehn mich nicht mehr,<br/>All mein Stolz ist nun Nichtigkeit.<br/>',NULL,195284,1);
INSERT INTO stanza VALUES('G2141','chorus','In der ganzen Welt wer ist Dir denn gleich?<br/>Wer ist sonst so kostbar, so schön und süß?<br/>Du allein bist meiner Liebe wert.<br/>O Herr Jesus, wie ich Dich lieb!<br/>Nicht mehr lebe ich, täusch mich selbst nicht mehr,<br/>Nicht mehr in der Welt fröne ich dem Selbst.<br/>Ich weiß: Du allein meine Liebe bist!<br/>Meine beste Liebe bist Du!<br/>',NULL,195285,2);
INSERT INTO stanza VALUES('G2141','2','Jesus Herr, mein Herz gehört Dir.<br/>Jeden Stein entferne aus mir!<br/>Gern will ich ein Sklave der Liebe sein,<br/>Ein Herz und ein Wille mit Dir.<br/>Dir bin ich oft nicht untertan,<br/>Doch ich möcht Dein''n Weg gehn fortan.<br/>Ich möcht nur, wonach es Dein''m Herz''n verlangt,<br/>Frieden find ich in Deiner Lieb.<br/>',NULL,195286,3);
INSERT INTO stanza VALUES('G2141','3','Jesus Herr, mein Herz gehört Dir!<br/>Niemals mehr geh ich weg von Dir.<br/>Herr, verbirg Dein scheinendes Antlitz nicht!<br/>Ich halt mich an kein''m andren fest.<br/>Herr, Dir gieß ich mein Alles aus.<br/>Deine Liebe füllt mein Herz auf.<br/>Du mein ew''ger Anteil, mein kostbarer Herr.<br/>Ich möcht nur Dich haben allzeit!<br/>',NULL,195287,4);
INSERT INTO stanza VALUES('G2142','1','Ich lieb Dich, Herr Jesus!<br/>Ich lieb Dich, Herr, Kostbarer!<br/>Kein anderer ist vergleichbar mit Dir!<br/>Ich lieb Dich, Herr Jesus!<br/>Ich lieb Dich, Herr, Kostbarer!<br/>Kein anderer ist vergleichbar mit Dir!<br/>Jesus, Herr Jesus,<br/>Du bist der Lieblichste,<br/>Nichts ist vergleichbar mit Dir!<br/>',NULL,195288,1);
INSERT INTO stanza VALUES('G2143','1','Lass mich, Herr, doch hinter Dir stehn,<br/>Meine Tränen besprengen Deine Füß<br/>Und ich wisch sie mit meinem Haar.<br/>Will sie küssen und salben mit dem Salböl.<br/>',NULL,195289,1);
INSERT INTO stanza VALUES('G2143','chorus','Ich liebe Dich!<br/>Jesus, ich liebe Dich!<br/>Herr, mein Leben und alles verschwend ich gern an Dich.<br/>Lass mich Dich mit Salböl salben,<br/>Deinen Kopf und Deine Füß,<br/>Dich, meinen Kostbarsten,<br/>Denn ich liebe Dich.<br/>',NULL,195290,2);
INSERT INTO stanza VALUES('G2143','2','Ein Pfund reines Salböl hohen Wertes<br/>Nehm ich, salbe Deine Füße, Herr,<br/>Und ich wisch sie mit meinem Haar,<br/>Dass das Haus sei voll des Duftes von dem Salböl.<br/>',NULL,195291,3);
INSERT INTO stanza VALUES('G2143','chorus','Ich liebe Dich!<br/>Jesus, ich liebe Dich!<br/>Herr, mein Leben und alles verschwend ich gern an Dich.<br/>Lass mich Dich mit Salböl salben,<br/>Deinen Kopf und Deine Füß,<br/>Dich, meinen Kostbarsten,<br/>Denn ich liebe Dich.<br/>',NULL,195292,4);
INSERT INTO stanza VALUES('G2143','3','Herr, sie sagten: „Wärst Du ein Prophet,<br/>Wüsstest Du, was und wer ich bin."<br/>Eine Sünderin, die Dich berührt,<br/>Eine Frau, die nicht würdig ist, Dich zu salben.<br/>',NULL,195293,5);
INSERT INTO stanza VALUES('G2143','chorus','Doch ich liebe Dich!<br/>Jesus, ich liebe Dich!<br/>Du vergabst mir so viel,<br/>Also lieb ich Dich so sehr.<br/>Lass mich Dich mit Salböl salben,<br/>Deinen Kopf und Deine Füß,<br/>Dich, meinen Kostbarsten,<br/>Denn Du liebst mich.<br/>',NULL,195294,6);
INSERT INTO stanza VALUES('G2143','4','Meine Liebe besprengt Deine Füße,<br/>Meine Herrlichkeit wischt sie dazu,<br/>Wo die Nägel stechen, küss ich sie.<br/>Meine Liebe und Herrlichkeit sind für Dich.<br/>',NULL,195295,7);
INSERT INTO stanza VALUES('G2143','chorus','Ich liebe Dich!<br/>Jesus, ich liebe Dich!<br/>Meine Herrlichkeit und Liebe gieß auf Dich.<br/>Nimm mein Salböl, liebster Herr!<br/>Es ist alles, was ich hab,<br/>Für Dich, mein Kostbarster,<br/>Denn ich liebe Dich.<br/>',NULL,195296,8);
INSERT INTO stanza VALUES('G2144','1','Göttliche Liebe fließt<br/>Tiefer als jedes Meer.<br/>Du kamst zu uns so wirklich, nah,<br/>Die Welt hast geliebt so sehr.<br/>',NULL,195297,1);
INSERT INTO stanza VALUES('G2144','2','Als Mensch umwarbst Du uns --<br/>Göttliche Herrlichkeit.<br/>Unsere Blindheit hast geheilt,<br/>Gefangene ganz befreit.<br/>',NULL,195298,2);
INSERT INTO stanza VALUES('G2144','3','Am Kreuz gabst Du Dich hin --<br/>Opfer vollkommen, rein.<br/>Du hast den höchsten Preis bezahlt,<br/>Mit Blut erwarbst die Gemeind.<br/>',NULL,195299,3);
INSERT INTO stanza VALUES('G2144','4','In Auferstehung nun<br/>Ziehst Du mich als der Geist.<br/>O liebster Jesus, komm herein!<br/>So Liebe in mir beweist.<br/>',NULL,195300,4);
INSERT INTO stanza VALUES('G2144','5','In solch Gemeinschaft, Herr,<br/>Öffne ich mich jetzt Dir.<br/>Mein Herz soll Deine Wohnung sein.<br/>Als ein Geist nun leben wir.<br/>',NULL,195301,5);
INSERT INTO stanza VALUES('G2144','6','Auf dem Thron sitzt Du, Herr,<br/>Priester und Retter mein.<br/>Mit Gold umgürtet an der Brust<br/>In Liebe versorgst die Dein''n.<br/>',NULL,195302,6);
INSERT INTO stanza VALUES('G2144','7','Jesus, ich lieb Dich sehr.<br/>Mach uns zum Ausdruck Dein!<br/>Für Deine Braut, Herr, komm zurück!<br/>Auf ewig ein Paar zu sein.<br/>',NULL,195303,7);
INSERT INTO stanza VALUES('G2145','chorus','Küss den Sohn, küss den Sohn,<br/>Der aus Liebe zu mir kam!<br/>Ermutigt und bezaubert mich<br/>Und am Kreuz gestorben ist.<br/>Er starb für mich, errettet'' mich,<br/>Kommt als Geist in mich hinein.<br/>Hab Ihn geküsst.<br/>',NULL,195304,1);
INSERT INTO stanza VALUES('G2145','1','Im vermengten Geist ich diene<br/>In der Botschaft von dem Sohn.<br/>Christus als den Geist empfang ich,<br/>Den ganzen Dreieinen Gott.<br/>',NULL,195305,2);
INSERT INTO stanza VALUES('G2145','2','Die Anbetung, die Gott möchte,<br/>Ist, wenn Christus wir erfahrn.<br/>Gott im Geist heut anzubeten,<br/>Ist der Dienst, den Gott verlangt.<br/>',NULL,195306,3);
INSERT INTO stanza VALUES('G2145','3','Erlaub Jesus, dich zu küssen!<br/>Er geht mit dir durch den Tag.<br/>Dies der Dienst im Evangelium:<br/>Durch dein Leben bet Ihn an!<br/>',NULL,195307,4);
INSERT INTO stanza VALUES('G2145','4','Im Leib Christi lass uns dienen!<br/>Nichts Natürliches daran.<br/>Nur durch Tod und Auferstehung<br/>Beten wir Ihn wirklich an.<br/>',NULL,195308,5);
INSERT INTO stanza VALUES('G2146','1','Du bist mein Geliebter!<br/>Du mein Herzallerliebster!<br/>Mein Herz und meine Seele<br/>Dürsten nach Dir, Herr!<br/>',NULL,195309,1);
INSERT INTO stanza VALUES('G2146','2','Du bist mein Geliebter!<br/>Du mein Herzallerliebster!<br/>Mein Herz öffne ich Dir jetzt weit!<br/>',NULL,195310,2);
INSERT INTO stanza VALUES('G2146','3','Komm und füll mich! Mit Deinem Geist!<br/>Füll mein Gefäß, Herr! Ich gehöre Dir!<br/>Komm und füll mich mit Deinem Geist!<br/>Lass mich Dein Ausdruck nur sein!<br/>',NULL,195311,3);
INSERT INTO stanza VALUES('G2146','4','Komm und füll mich, Herr, bis zum Rand!<br/>Ja, Herr, sogar mich!<br/>Nimm mich ein, lass mich nie gewinn''n!<br/>Komm und füll mich, Herr, bis zum Rand!<br/>Überfließ in mir!<br/>Überwind in mir!<br/>',NULL,195312,4);
INSERT INTO stanza VALUES('G2147','1','Ein Gefäß aus Ton bin ich,<br/>Christus kam als Schatz in mich;<br/>Sein Behälter muss ich sein,<br/>Ihn, den Inhalt, nehm ich ein.<br/>',NULL,195313,1);
INSERT INTO stanza VALUES('G2147','2','Er schuf mich in Seinem Bild,<br/>Mich zu fülln mit Ihm gezielt;<br/>Gott erschuf Sich ein Gefäß,<br/>Ganz dem Inhalt -- Ihm -- gemäß.<br/>',NULL,195314,2);
INSERT INTO stanza VALUES('G2147','3','Christus wohnt in meinem Geist,<br/>Seine Kraft mir Halt erweist;<br/>Er und ich sind eins allzeit,<br/>Er ist meine Wirklichkeit.<br/>',NULL,195315,3);
INSERT INTO stanza VALUES('G2147','4','Täglich wirkt in mir der Herr,<br/>Sich vermengt mit mir stets mehr,<br/>Schritt für Schritt treu leitet mich,<br/>Jeden Teil füllt Er mit Sich.<br/>',NULL,195316,4);
INSERT INTO stanza VALUES('G2147','5','Ihn von innen bringe ich<br/>Nun zum Ausdruck äußerlich;<br/>Ganz kristallklar muss ich sein,<br/>Dass durch mich Er leuchte rein.<br/>',NULL,195317,5);
INSERT INTO stanza VALUES('G2147','6','Mehr Umwandlung brauch ich sehr,<br/>Muss zerbrochen werden mehr,<br/>Bis der Ton die Form annimmt,<br/>Mit dem Schatz zusammenstimmt.<br/>',NULL,195318,6);
INSERT INTO stanza VALUES('G2148','1','Ja, ich glaubte dem Bericht,<br/>Halleluja sei dem Lamm!<br/>Und den Vorhof ich durchschritt!<br/>Oh, Herrlichkeit sei Gott!<br/>Ich bin ganz auf Jesu Seit,<br/>Der Altar hat mich geweiht,<br/>Von der Welt und Sünd befreit,<br/>Halleluja sei dem Lamm!<br/>',NULL,195319,1);
INSERT INTO stanza VALUES('G2148','chorus','Halleluja! Halleluja!<br/>Durch den Vorhang ging ich ein,<br/>Ew''ge Herrlichkeit ist mein,<br/>Halleluja! Halleluja!<br/>In der Gegenwart des Königs leb ich jetzt.<br/>',NULL,195320,2);
INSERT INTO stanza VALUES('G2148','2','König, Priester nun für Gott,<br/>Halleluja sei dem Lamm!<br/>Durch das reinigende Blut,<br/>Oh, Herrlichkeit sei Gott!<br/>Durch des Geistes Licht und Macht<br/>Leb und web ich Tag und Nacht<br/>Hier im Heiligsten voll Pracht,<br/>Halleluja sei dem Lamm!<br/>',NULL,195321,3);
INSERT INTO stanza VALUES('G2148','3','Durch den äußren Vorhang hin,<br/>Halleluja sei dem Lamm!<br/>Der einst Gottes Licht verhing,<br/>Oh, Herrlichkeit sei Gott!<br/>Brachte mich das Blut hinein<br/>In die Heiligkeit so rein,<br/>Dort kann Selbst und Sünd nicht sein,<br/>Halleluja sei dem Lamm!<br/>',NULL,195322,4);
INSERT INTO stanza VALUES('G2148','4','Ich bin nun am heil''gsten Ort,<br/>Halleluja sei dem Lamm!<br/>Nun der innre Vorhang fort,<br/>Oh, Herrlichkeit sei Gott!<br/>Schon geheiligt hin zu Gott,<br/>Durch die Macht und Kraft im Blut<br/>Wohn ich nun im Herrn, wie gut!<br/>Halleluja sei dem Lamm!<br/>',NULL,195323,5);
INSERT INTO stanza VALUES('G2149','1','Am Morgen früh komm ich zu Ihm,<br/>Eh am Himmel hell aufgeht die Sonne;<br/>Und Sein Angesicht strahlt und scheint auf mich --<br/>In mir fließt süße Wonne.<br/>Und Er spricht zu mir und mir offenbart<br/>Seinen heutigen Reichtum dabei;<br/>Voller Glück und Freude genieß ich Ihn,<br/>Mein Hunger ist ganz vorbei.<br/>',NULL,195324,1);
INSERT INTO stanza VALUES('G2149','2','Er spricht als der Geist durch das Wort,<br/>Bis mein Herz froh ein Echo will singen,<br/>Mich der Lebensbrunnen mit Gnade stärkt,<br/>In mir will freudig springen.<br/>Und Er spricht zu mir und mir offenbart<br/>Seinen heutigen Reichtum dabei;<br/>Und ich trink von Ihm allezeit so gern,<br/>Mein Durst ist jetzt ganz vorbei.<br/>',NULL,195325,2);
INSERT INTO stanza VALUES('G2149','3','Mit Sanftmut behandelt Er mich,<br/>Während ich vor Ihm freudig verweile;<br/>Er durchtränkt mich ganz und versorgt mich reich,<br/>Füllt meine innren Teile.<br/>Und Er spricht zu mir und mir offenbart<br/>Seinen heutigen Reichtum dabei;<br/>Und in jeder Hinsicht genieß ich Ihn,<br/>Die Sorgen sind ganz vorbei.<br/>',NULL,195326,3);
INSERT INTO stanza VALUES('G2150','1','Wir sehn des Lebens Geheimnis,<br/>Die Vision göttlich scheint hier:<br/>Dankt Gott -- wir sind nun in Christus,<br/>Ja, wir bleiben, im Weinstock bleiben wir.<br/>',NULL,195327,1);
INSERT INTO stanza VALUES('G2150','chorus','Im Weinstock bleiben wir,<br/>Im Weinstock bleiben wir,<br/>Gottes Lebensreichtum gibt es hier!<br/>Lobt Gott, Er bracht'' uns her,<br/>Nie zu verlassen mehr --<br/>Wir bleiben, im Weinstock bleiben wir.<br/>',NULL,195328,2);
INSERT INTO stanza VALUES('G2150','2','Nicht mehr mit Mühe und Kämpfen<br/>Müssen wir finden hinein.<br/>Lobt Gott -- wir sind jetzt schon in Ihm,<br/>Halleluja, im Weinstock jetzt zu sein.<br/>',NULL,195329,3);
INSERT INTO stanza VALUES('G2150','3','In uns bewegt sich das Salböl,<br/>Bringt uns das göttliche Sein;<br/>Schenkt uns die göttliche Salbung,<br/>Hier im Weinstock, im Weinstock nur allein.<br/>',NULL,195330,4);
INSERT INTO stanza VALUES('G2150','4','Im Lebensstrom wir nun leben.<br/>Oh, wie Sein Licht uns scheint hier!<br/>Gott und der Mensch sind zu Hause,<br/>Ja, im Weinstock, im Weinstock bleiben wir!<br/>',NULL,195331,5);
INSERT INTO stanza VALUES('G2151','1','Jeden Tag näher mir,<br/>Jeden Tag lieber mir,<br/>Diese Person in mir<br/>Wird mehr und mehr Wirklichkeit.<br/>Rettet mich und liebt mich,<br/>Glauben und Hoffnung mir gibt.<br/>Mehr als die ganze Welt<br/>Bist Du, mein Herr.<br/>',NULL,195332,1);
INSERT INTO stanza VALUES('G2151','2','Selbst wenn mir Glaube fehlt,<br/>Wenn''s keine Hoffnung gibt,<br/>Hör ich Ihn, wie Er spricht:<br/>Vertrau Mir und du wirst sehn,<br/>Was du brauchst, bin Ich dir,<br/>Wenn du bloß Glauben hast.<br/>Kummer und Zweifel enden,<br/>Wenn du Mir vertraust.<br/>',NULL,195333,2);
INSERT INTO stanza VALUES('G2152','1','Der Wandel im ersten Vers (V. 16) heißt „Hin- und hergehn",<br/>„Umherspaziern",<br/>Wie gewohnt, allgemein<br/>Und ganz normal -- Leben im Alltag.<br/>',NULL,195334,1);
INSERT INTO stanza VALUES('G2152','chorus','Leben, handeln und unser ganzes Sein<br/>Völlig richten nach dem Geist.<br/>Peripateo und stoicheo<br/>Beide zeigen einen Wandel an.<br/>',NULL,195335,2);
INSERT INTO stanza VALUES('G2152','2','Der Wandel im zweiten Vers (V. 25) ist „In Reih und Glied",<br/>„Im Takt marschiern",<br/>Absichtlich, zielstrebig<br/>Geordnet gehn -- Gottes Ziel erfülln.<br/>',NULL,195336,3);
INSERT INTO stanza VALUES('G2152','3','Der Geist Selbst ist immer unser Maßstab und Weg,<br/>Das Ziel und Prinzip.<br/>Immerzu folgen wir<br/>Dem Empfinden von Leben und Fried.<br/>',NULL,195337,4);
INSERT INTO stanza VALUES('G2153','1','Jesus als Land ist wunderbar<br/>Und allumfassend reich:<br/>Wie Bäche, Flüsse, Ströme fließn,<br/>Ist klaren Brunnen gleich.<br/>Tälern und Hügeln reich entspringt,<br/>Fließt bis Er jeden Teil durchdringt,<br/>Tränkt uns so gut -- herrliche Flut --<br/>Leben gibt!<br/>',NULL,195338,1);
INSERT INTO stanza VALUES('G2153','2','Jesus das Land des Weizens ist --<br/>Am Kreuz Sein Leben ließ.<br/>Auch Auferstehungsleben ist,<br/>Die Gerste zeigt uns dies.<br/>Weinstöcke, Feigen hier du siehst,<br/>Traubensaft, Wein erfreut und fließt.<br/>Sich sehr bewährt, reich uns ernährt --<br/>Welch ein Land!<br/>',NULL,195339,2);
INSERT INTO stanza VALUES('G2153','3','Christus ist reich, voll Überfluss,<br/>Wie der Granatbaum sprießt,<br/>Mit Öl salbt Er uns jeden Tag,<br/>Welch Ölbaum Er doch ist!<br/>Honig und Milch fließn überreich,<br/>Stellt uns zufrieden, stärkt zugleich,<br/>Er ist so viel, Er unser Ziel!<br/>Welch Christus!<br/>',NULL,195340,3);
INSERT INTO stanza VALUES('G2153','4','Christus ist Brot im guten Land,<br/>Dass niemand leer ausgeht.<br/>In Ihm es keinen Mangel gibt,<br/>Nur Überfluss besteht.<br/>Er ist ein Land, so groß und weit,<br/>So allumfassend allezeit;<br/>Land so ersehnt--sich nun ausdehnt--<br/>Füllt das Herz!<br/>',NULL,195341,4);
INSERT INTO stanza VALUES('G2153','5','Christus, ein Land aus Eisenstein,<br/>Die Vollmacht Ihm entspringt.<br/>Den festen Christus grabt nun aus,<br/>So Seinen Feind bezwingt.<br/>Leid und Plag läutern unser Sein,<br/>Kupfer in uns strahlt hell und rein.<br/>Mit Eisen bind, Kupfer wir sind,<br/>Müssen wir.<br/>',NULL,195342,5);
INSERT INTO stanza VALUES('G2153','6','Herr, für das Land Dich segnen wir,<br/>Für Christus voll und reich!<br/>Wir essen Ihn, Er sättigt uns,<br/>Er hat uns voll gereicht!<br/>Lehr uns, zu bauen allezeit<br/>Auf dieser großen Wirklichkeit;<br/>Wachstum wir schaun, gern wir bebaun<br/>Unser Land!<br/>',NULL,195343,6);
INSERT INTO stanza VALUES('G2154','1','Der Herr ist mein Hirte für ewig,<br/>Er lagert mich auf grünen Au''n;<br/>Er führt mich zu stillen Gewässern<br/>Und sättigt mich, dass ich nur staun.<br/>',NULL,195344,1);
INSERT INTO stanza VALUES('G2154','chorus','Seine Gnade und Liebe<br/>Sind allezeit bei mir<br/>Und sie folgen mir mein Leben lang;<br/>Seine Gnade und Liebe<br/>Sind allezeit bei mir<br/>Und sie folgen mir mein Leben lang.<br/>Und im Haus des Herrn<br/>Werde ich ewig wohnen,<br/>Ihn genießen am Tisch,<br/>Den Er mir deckt;<br/>Seine Gnade und Liebe<br/>Sind allezeit bei mir<br/>Und sie folgen mir mein Leben lang.<br/>',NULL,195345,2);
INSERT INTO stanza VALUES('G2154','2','Mein Hirte ist Selbst meine Weide,<br/>Mein Friede, die Wasser der Ruh;<br/>Ich esse im Geist Seinen Reichtum<br/>Und trink, bin gesegnet dazu!<br/>',NULL,195346,3);
INSERT INTO stanza VALUES('G2154','3','Mein Hirte erneuert die Seele,<br/>Den Willen, Gefühl und Verstand;<br/>Auch wenn ich durchs Tal heute wandre,<br/>Welch einen Begleiter ich fand!<br/>',NULL,195347,4);
INSERT INTO stanza VALUES('G2154','4','Am Tisch, den mein Hirte gedeckt hat,<br/>Da fest ich, zermalmt Satan ist;<br/>Mein Haupt ist gesalbt mit dem Salböl,<br/>Mein Becher vor Glück überfließt!<br/>',NULL,195348,5);
INSERT INTO stanza VALUES('G2154','5','In meines Herrn Hause nun wohn ich,<br/>Genieße die Güte des Herrn;<br/>Und nichts übersteigt meine Freude,<br/>Ich freu mich in Jesus so gern!<br/>',NULL,195349,6);
INSERT INTO stanza VALUES('G2155','1','An dem Ufer nach dem Frühstück<br/>Wollte Jesus Petrus'' Liebe<br/>Wiederherstelln, damit er nicht<br/>Auf sich vertraut.<br/>Er beging einige Fehler:<br/>Verleugnete dreimal den Retter,<br/>Brachte andere zum Wanken,<br/>Doch Jesus sprach:<br/>',NULL,195350,1);
INSERT INTO stanza VALUES('G2155','chorus','Liebst du Mich? Speis die Lämmer!<br/>Liebst du Mich? Weide die Schafe!<br/>Liebst du Mich?<br/>Dann gib Mein''n Schafen ihre Speis!<br/>',NULL,195351,2);
INSERT INTO stanza VALUES('G2155','2','Wir sind alle schon gestolpert,<br/>Dadurch unsre Stärke bröckelt,<br/>Unser Herz -- einst stolz -- voll Demut,<br/>Wir sind so schwach.<br/>Genau dann erscheint der Herr uns<br/>Und sucht nach unserer Liebe.<br/>Während wir Ihn hörn, stellt Er uns<br/>Folgende Frag:<br/>',NULL,195352,3);
INSERT INTO stanza VALUES('G2155','chorus','',NULL,195353,4);
INSERT INTO stanza VALUES('G2155','3','Unser Herr kann nicht vorangehn,<br/>Denn es fehlen Ihm die Hirten,<br/>Die den Verlorenen die Milch des Wortes austeiln.<br/>Durch die Mitarbeit der Menschen<br/>Kann Er sie von innen weiden.<br/>Willst du dich Ihm dafür öffnen?<br/>Dann sag zu Ihm:<br/>',NULL,195354,5);
INSERT INTO stanza VALUES('G2155','chorus','Herr, ich lieb Dich -- ich speis die Lämmer.<br/>Herr, ich lieb Dich -- ich weide die Schafe.<br/>Herr, ich liebe Dich.<br/>Ich geb Dein''n Schafen ihre Speis.<br/>',NULL,195355,6);
INSERT INTO stanza VALUES('G2156','1','Tod und Sünd hab ich in Adam allezeit,<br/>Doch in Christus Leben und Gerechtigkeit;<br/>Bleibe ich im Fleisch, so nimmt man Adam wahr,<br/>Bleibe ich im Geist, ist Christus stets sichtbar.<br/>',NULL,195356,1);
INSERT INTO stanza VALUES('G2156','2','Wenn ich auch in Adam nicht der Sünde dien,<br/>Als ein Sünder ich zum Tod verurteilt bin;<br/>Doch in Christus Jesus, ohne eignes Tun,<br/>Bin ich schon gerecht gemacht, in Ihm kann ruhn.<br/>',NULL,195357,2);
INSERT INTO stanza VALUES('G2156','3','Ohne Mühe zeige ich im Fleisch allzeit<br/>Die Natur von Adam, ihre Sündigkeit;<br/>Doch im Geist, ganz ohne Kraft zu investiern,<br/>Kann ich leben so wie Er, im Geist regiern.<br/>',NULL,195358,3);
INSERT INTO stanza VALUES('G2156','4','Christi Tod wirkt, dass ich frei von Adam bin,<br/>Christi Leben wirkt, dass Leben ich gewinn!<br/>Acht ich nicht aufs Fleisch, führt Adam nichts mehr aus,<br/>Acht ich auf den Geist, strahlt Er aus mir heraus.<br/>',NULL,195359,4);
INSERT INTO stanza VALUES('G2156','5','Achten auf den Geist, so rettet Gott zur Zeit,<br/>Achten auf den Geist, zeigt Christi Herrlichkeit;<br/>Achten auf den Geist, wer überwinden will,<br/>Achten auf den Geist, so laufen wir zum Ziel.<br/>',NULL,195360,5);
INSERT INTO stanza VALUES('G2156','6','Achten auf den Geist, so kennen wir das Kreuz,<br/>Fließt die Auferstehungskraft durch uns ja heut;<br/>Achten auf den Geist, lebt Christus durch mein Sein;<br/>Und so reift Sein Leben in mir voll und fein.<br/>',NULL,195361,6);
INSERT INTO stanza VALUES('G2156','7','Christi reiches Leben strömt in meinem Geist,<br/>Stärkung wie auch Segen Er mir hier erweist;<br/>Wenn ich bleib im Geist, ist Heiligkeit zu sehn,<br/>Und voran in meinem Herzen kann Gott gehn.<br/>',NULL,195362,7);
INSERT INTO stanza VALUES('G2157','chorus','Füll mein''n Kelch, Herr!<br/>Ich heb ihn hoch, Herr.<br/>Komm und still<br/>Das Dürsten meiner Seele!<br/>Brot vom Himmel, speis mich,<br/>Bis mir nichts mehr fehlt!<br/>Füll mein''n Kelch,<br/>Füll ihn auf und mach mich ganz!<br/>',NULL,195363,1);
INSERT INTO stanza VALUES('G2157','1','Wie die Frau dort am Brunnen war ich suchend<br/>Nach Dingen, die nicht füllen könn''n.<br/>Und dann hör ich den Retter sprechen:<br/>„Trink von dem Quell, der nie austrocknen wird!"<br/>',NULL,195364,2);
INSERT INTO stanza VALUES('G2157','2','Es gibt viele in der Welt, die was suchen,<br/>Das sie zufriedenstellen wird.<br/>Doch nichts ist diesem Schatz vergleichbar,<br/>Den ich find in Jesus, meinem Herrn.<br/>',NULL,195365,3);
INSERT INTO stanza VALUES('G2157','3','Darum Bruder, wenn die Dinge dieser Welt<br/>Dich nicht zufriedenstellen könn''n,<br/>Dann kommt mein Herr und wird dich retten,<br/>Wenn du vor Ihm knien und beten wirst.<br/>',NULL,195366,4);
INSERT INTO stanza VALUES('G2158','1','Gott ist lebendig -- sag: Halleluja!<br/>Er lebt in uns nun -- sag: Halleluja!<br/>Sein voller Reichtum,<br/>Oh, wie er schmeckt uns!<br/>Ruf nur: „O Herr" und schmeck und sieh!<br/>',NULL,195367,1);
INSERT INTO stanza VALUES('G2158','2','Zusammen festen ist stets am Besten,<br/>Im Geist sind alle des Herrn Familie,<br/>Sein Leib voll Leben!<br/>Ihm Ausdruck geben,<br/>Jesus ist unsre Wirklichkeit.<br/>',NULL,195368,2);
INSERT INTO stanza VALUES('G2158','3','In den Gemeinden essen und weiden.<br/>Verkünd die Botschaft an jeder Ortschaft!<br/>Von Jesus singen,<br/>Ihn allen bringen --<br/>Bis dieses Land sieht: Christus lebt.<br/>',NULL,195369,3);
INSERT INTO stanza VALUES('G2159','1','Als ich zuerst geglaubt<br/>Und Sein Leben nahm auf,<br/>Der Samen in mich reinkam.<br/>Dieser Same sprießt,<br/>Zoe-Leben jetzt fließt<br/>Und bringt mich zur Reife hin.<br/>',NULL,195370,1);
INSERT INTO stanza VALUES('G2159','chorus','Bin ich lebendig, vital?<br/>Erfahre ich Leben stets?<br/>Zeigt mein Lebenswandel Früchte des Lebens?<br/>Ist die Wurzel gesund,<br/>Geht beim Baum alles rund.<br/>Mein Herzensboden, o Herr!<br/>',NULL,195371,2);
INSERT INTO stanza VALUES('G2159','2','Dass es Wachstum gibt,<br/>Weiß man dann, wenn man sieht,<br/>Dass Lebensfrüchte entstehen:<br/>Freude, Treue und Fried,<br/>Glaube, Güte und Lieb.<br/>Kann mein tägliches Leben bestehn?<br/>',NULL,195372,3);
INSERT INTO stanza VALUES('G2159','3','Wenn die Früchte entstehn,<br/>Können andere sehn<br/>Die Tugenden eben genannt.<br/>Das Evangeliumswort<br/>Bewegt sich so fort,<br/>Macht das Leben den andern bekannt.<br/>',NULL,195373,4);
INSERT INTO stanza VALUES('G2159','4','Herr, gewähre mir doch<br/>Einen Neuanfang heut,<br/>Ein Mensch des Lebens zu sein!<br/>Dich zum Ausdruck bring''n,<br/>In was immer ich tu --<br/>Oh, Leben mög fließen aus mir!<br/>',NULL,195374,5);
INSERT INTO stanza VALUES('G2160','1','Gottes Absicht mit der Schöpfung gilt der Menschheit ganz allein,<br/>Darum wurde Er zum Geist, um mit dem Menschen eins zu sein;<br/>Seine ewige Ökonomie nimmt unser Leben ein,<br/>Vermengung ist der Weg.<br/>',NULL,195375,1);
INSERT INTO stanza VALUES('G2160','chorus','Mehr Vermengung, halleluja,<br/>Mehr Vermengung, halleluja,<br/>Mehr Vermengung, halleluja,<br/>Vermengung ist der Weg!<br/>',NULL,195376,2);
INSERT INTO stanza VALUES('G2160','2','Ganz zentral in uns, noch tiefer als Verstand, Gefühl und Will'',<br/>Da liegt unser Geist, mit ihm will Gott auf eines nur abzieln;<br/>Ihn erfüllen soll der Herr, so wird Er Seine Sehnsucht stilln,<br/>Vermengung ist der Weg.<br/>',NULL,195377,3);
INSERT INTO stanza VALUES('G2160','3','Im Gemeindeleben heute haben wir den Weg forthin,<br/>Wie man den Dreieinen Gott erfährt und ständig lebt durch Ihn:<br/>Tauche in den Geist hinein und im vermengten Geist bleib drin!<br/>Vermengung ist der Weg.<br/>',NULL,195378,4);
INSERT INTO stanza VALUES('G2160','4','Mitten unter sieben Leuchtern, dort den Sohn des Menschen seht,<br/>Augen flammen, Füße glühen, Er für Gottes Vorsatz steht;<br/>Gott den korp''rativen Leib will, nur um ihn sich alles dreht,<br/>Vermengung ist der Weg.<br/>',NULL,195379,5);
INSERT INTO stanza VALUES('G2160','5','Jeden Tag, in allem, was wir denken, sagen, tun und sind,<br/>Brauchen wir Vermengung,<br/>dass der Herr Sich noch vermehrt uns schenkt;<br/>Herr, wir geben uns Dir willig, der vermengte Weg uns lenkt,<br/>Vermengung ist der Weg.<br/>',NULL,195380,6);
INSERT INTO stanza VALUES('G2160','6','Durch die Frucht des Alltags wird das Neu'' Jerusalem bereit,<br/>Gott und Mensch sind dann vollauf vermengt, ja, das ist Herrlichkeit;<br/>Welche Freude! Daran dürfen wir teilhaben allezeit,<br/>Vermengung ist der Weg.<br/>',NULL,195381,7);
INSERT INTO stanza VALUES('G2161','1','Erkannt vom Vater vor Anfang der Zeit,<br/>Das Blut des Lammes, es wusch mich so rein,<br/>In meinem Geist jetzt ein Gott-Mensch zu sein.<br/>Halleluja, Halleluja.<br/>',NULL,195382,1);
INSERT INTO stanza VALUES('G2161','chorus','Halleluja, Halleluja, Halleluja<br/>Halleluja, Halleluja, Halleluja.<br/>',NULL,195383,2);
INSERT INTO stanza VALUES('G2161','2','Vater, Du kanntest mich in Ewigkeit.<br/>Deine Vorkenntnis Barmherzigkeit zeigt.<br/>Hast mich vorherbestimmt zur Herrlichkeit.<br/>Halleluja, Halleluja.<br/>',NULL,195384,3);
INSERT INTO stanza VALUES('G2161','3','Sohn, durch Dein Blut, das so kostbar für mich,<br/>Vom Fall gerettet, erworben bin ich.<br/>Du auferstandst, deshalb rufe ich Dich.<br/>Halleluja, Halleluja.<br/>',NULL,195385,4);
INSERT INTO stanza VALUES('G2161','4','O Geist, Du kamst und du heiligtest mich<br/>Du selbst bist in mir der Glaube an Dich<br/>Jetzt als der Geist bist Du Leben für mich<br/>Halleluja, Halleluja.<br/>',NULL,195386,5);
INSERT INTO stanza VALUES('G2161','5','Du bist mein Vater, Dein''n Samen hab ich<br/>Ich bin erworben, erlöst hast Du mich<br/>Dein Geist wohnt in mir jetzt und ewiglich!<br/>Halleluja, Halleluja.<br/>',NULL,195387,6);
INSERT INTO stanza VALUES('G2162','1','Es ist somit offensichtlich, dass die göttliche Offenbarung<br/>Der Dreieinigkeit der Gottheit im heiligen Wort<br/>Vom ersten Buch Mose bis hin zur Offenbarung<br/>Nicht für das theologische Studium bestimmt ist,<br/>Sondern um zu begreifen, wie Gott in Seiner geheimnisvollen<br/>Und wunderbarn Dreieinigkeit Sich Selbst in Sein außerwähltes Volk<br/>Hinein austeilt, hinein austeilt, hinein austeilt,<br/>Damit wir als Sein außerwähltes und erlöstes Volk<br/>An dem durch einen Prozess gegangenen Dreieinen Gott teilhaben können,<br/>Indem wir Ihn jetzt und in Ewigkeit<br/>Erfahren, genießen und besitzen. Amen.<br/>',NULL,195388,1);
INSERT INTO stanza VALUES('G2162','SoundCloud Link','https://soundcloud.com/liederstroeme/es-ist-somit-offensichtlich',NULL,195389,2);
INSERT INTO stanza VALUES('G2163','1','Nimm Zeit, Ihn zu schauen,<br/>Sprich oft mit dem Herrn,<br/>In Ihm bleib beständig,<br/>Und lies Sein Wort gern!<br/>Stets hör auf Sein Sprechen,<br/>Gehorsam und sanft,<br/>Und such Seinen Segen!<br/>Er stärkt Dich mit Kraft.<br/>',NULL,195390,1);
INSERT INTO stanza VALUES('G2163','2','Nimm Zeit, Ihn zu schauen,<br/>Auch wenn die Welt eilt;<br/>Verbring im Verborgnen<br/>Mit Jesus viel Zeit!<br/>Wie Er wirst du werden<br/>Durch Schauen auf Ihn;<br/>Dein Wandel wird andre<br/>Zu Jesus hinziehn.<br/>',NULL,195391,2);
INSERT INTO stanza VALUES('G2163','3','Nimm Zeit, Ihn zu schauen,<br/>Von Ihm sei geführt;<br/>Ihm eil nicht voraus rasch,<br/>Gleich was auch geschieht!<br/>In Leid oder Freuden<br/>Folg Ihm immer gern;<br/>Vertrau Seinem Wort,<br/>Schau auf Jesus, den Herrn!<br/>',NULL,195392,3);
INSERT INTO stanza VALUES('G2163','4','Nimm Zeit, Ihn zu schauen,<br/>Die Seele zu stilln;<br/>Lass Ihn doch beherrschen<br/>Gefühl, Denken, Willn!<br/>Zu Strömen der Liebe<br/>Dich leitet der Geist,<br/>So Seine Barmherzigkeit<br/>Er dir erweist.<br/>',NULL,195393,4);
INSERT INTO stanza VALUES('G2164','1','O Seel, bist du matt und bekümmert?<br/>Kein Licht in dem Dunkel du siehst?<br/>Ein Blick auf den Retter gibt Licht dir,<br/>Und Leben in Strömen frei fließt.<br/>',NULL,195394,1);
INSERT INTO stanza VALUES('G2164','chorus','Wend den Blick doch auf Jesus,<br/>Schau voll in Sein Antlitz hinein!<br/>Und im Licht Seiner Gnade und Herrlichkeit<br/>Alles Irdische trüb Dir erscheint.<br/>',NULL,195395,2);
INSERT INTO stanza VALUES('G2164','2','Er ging durch den Tod in das Leben,<br/>Zur Nachfolge sind wir bereit.<br/>Die Sünde hat nun keine Macht mehr,<br/>Im Herrn überwinden wir weit!<br/>',NULL,195396,3);
INSERT INTO stanza VALUES('G2164','3','Der Herr hält Sein Wort, das verhieß Er,<br/>Drum glaubt Ihm und alles wird gut!<br/>Dann geht zu den sterbenden Menschen,<br/>Die volle Errettung tut kund!<br/>',NULL,195397,4);
INSERT INTO stanza VALUES('G2165','1','Wie überströmend ist die Gabe der Gerechtigkeit.<br/>Wie unergründlich tief doch Seine Liebe ist.<br/>Sie rettet dich und mich;<br/>Voller Güte erbarmt Er Sich.<br/>Ein Lamm heute auf dem Throne Gottes sitzt.<br/>',NULL,195398,1);
INSERT INTO stanza VALUES('G2165','chorus','Drum öffne dich doch weit<br/>Und rufe laut: „O Herr!"<br/>Finde deinen Geist, wo die Gnade ausgoss Er!<br/>Ruf Ihn an, komm ins Licht,<br/>Übe vor Seinem Angesicht!<br/>Er sehnt sich und wartet,<br/>Er hofft und erwartet,<br/>Er wünscht sich seit jeher,<br/>Dass du dich wendest zu Ihm.<br/>',NULL,195399,2);
INSERT INTO stanza VALUES('G2165','2','Wo immer du auch bist, kennt Er deine Gedanken.<br/>Nur Er versteht dein Herz, Er kennt dich ganz genau.<br/>Er hofft, dass du es wagst,<br/>Er wartet, bis du Ihm sagst:<br/>„Herr Jesus, mein unruhig Herz nur auf Dich schau!"<br/>',NULL,195400,3);
INSERT INTO stanza VALUES('G2166','1','Rufen: „O Herr Jesus!",<br/>Das macht unsern Geist so stark!<br/>Du kannst Ihn berühren<br/>Und aus Schwermut wird Gesang!<br/>Oh, hör nicht auf Satan mit seiner Ablenkung!<br/>Doch wend dich zum Geist und<br/>Spring in Aktion nun!<br/>Rufe: „O Herr Jesus!"<br/>Und genieß Ihn allezeit!<br/>',NULL,195401,1);
INSERT INTO stanza VALUES('G2167','1','Gibt es einen -- einen Freund,<br/>Dem ich mich öffnen kann?<br/>Einen, der mich versteht<br/>Und mich durch Schweres trägt?<br/>Einen, wenn ich zu keinem<br/>Sonst mehr kommen kann.<br/>Nein, es gibt keinen, der Ihm gleicht.<br/>',NULL,195402,1);
INSERT INTO stanza VALUES('G2167','chorus','Ja, es gibt Einen,<br/>Dem ich mich ganz öffnen kann.<br/>Ja, es gibt Einen,<br/>Der mich immer tragen kann.<br/>Ja, es gibt Einen,<br/>Wenn es sonst keinen gibt,<br/>Ja, es gibt Einen, Er ist wunderbar.<br/>',NULL,195403,2);
INSERT INTO stanza VALUES('G2167','2','Gibt es Einen, der sich um mich<br/>In schweren Zeiten sorgt?<br/>Einen, zu dem man sich<br/>Flücht''t an den sichren Ort?<br/>Einen, der mich stets stützt<br/>Und vor Stürmen beschützt,<br/>Nein, es gibt keinen, der Ihm gleicht.<br/>',NULL,195404,3);
INSERT INTO stanza VALUES('G2167','chorus','Ja, es gibt Einen,<br/>Der mich nie mehr lässt allein.<br/>Ja, es gibt Einen,<br/>Immer da, ob Sturm, ob Sonnenschein.<br/>Ja, es gibt Einen,<br/>Wenn es sonst keinen gibt.<br/>Ja, es gibt Einen, der besonders ist.<br/>',NULL,195405,4);
INSERT INTO stanza VALUES('G2167','3','Gibt es Einen, der zu mir steht<br/>Und der mich nie verlässt?<br/>Einen, der mit mir geht<br/>Und bis zum Ende hält fest?<br/>Einen, der mich kennt<br/>Und trotzdem nicht ablehnt.<br/>Nein, es gibt keinen, der Ihm gleicht.<br/>',NULL,195406,5);
INSERT INTO stanza VALUES('G2167','chorus','Ja, es gibt Einen,<br/>Der mich nimmt, so wie ich bin.<br/>Ja, es gibt Einen,<br/>Der mich nah zu Sich zieht hin.<br/>Ja, es gibt Einen,<br/>Er ist der Lieblichste.<br/>Nimm Ihn doch einfach -- so lieblich ist Er!<br/>',NULL,195407,6);
INSERT INTO stanza VALUES('G2167','4','Gibt es Einen, der mich sieht,<br/>So wie ich wirklich bin?<br/>Einen, der Sich mir gibt,<br/>Mein Herz zum Singen bringt?<br/>Einen, der mich liebt,<br/>Wenn''s keine Liebe in mir gibt?<br/>Nein, es gibt keinen, der Ihm gleicht.<br/>',NULL,195408,7);
INSERT INTO stanza VALUES('G2167','chorus','Ja, es gibt Einen,<br/>Der bis in die Tiefe dringt.<br/>Ja, es gibt Einen,<br/>Der dein Herz zum Singen bringt.<br/>Ja, es gibt Einen,<br/>Er ist die Liebe selbst.<br/>Liebe Ihn einfach, Er ist wunderbar!<br/>',NULL,195409,8);
INSERT INTO stanza VALUES('G2167','chorus','Ja, es ist Christus,<br/>Der bis in die Tiefe dringt.<br/>Ja, es ist Christus,<br/>Der dein Herz zum Singen bringt.<br/>Ja, es ist Christus,<br/>Er ist der Kostbarste.<br/>Liebe Ihn einfach, Er ist wunderbar!<br/>',NULL,195410,9);
INSERT INTO stanza VALUES('G2168','chorus','Voran, voran, geh voran in dem Herrn!<br/>Gestärkt geh voran im Herrn!<br/>Deine Mühe ist nie vergeblich im Herrn.<br/>Du musst voran, vorangeh''n im Herrn.<br/>',NULL,195411,1);
INSERT INTO stanza VALUES('G2168','1','Prüfungen kommen und Rückschläge auch,<br/>Du musst voran, vorangehn im Herrn.<br/>Vorbei ist vorbei, Sein Erbarmen ist neu.<br/>Du musst voran, vorangeh''n im Herrn.<br/>',NULL,195412,2);
INSERT INTO stanza VALUES('G2168','chorus','Presch vor, presch vor, presch vor in dem Herrn!<br/>Sei stark und presch vor im Herrn!<br/>Deine Mühe ist nie vergeblich im Herrn.<br/>Darum presch vor, presch vor in dem Herrn!<br/>',NULL,195413,3);
INSERT INTO stanza VALUES('G2168','2','Sich sorgen bringt nichts - denn Er sorgt ja für dich.<br/>Du musst voran, vorangehn im Herrn.<br/>Der morgige Tag ist noch weit und so vag.<br/>Du musst voran, vorangeh''n im Herrn.<br/>',NULL,195414,4);
INSERT INTO stanza VALUES('G2168','chorus','Voran, voran, im Herrn segle voran.<br/>Sei gestärkt, segle weiter im Herrn.<br/>Deine Mühe ist nie vergeblich im Herrn.<br/>Du musst voran, vorangeh''n im Herrn.<br/>',NULL,195415,5);
INSERT INTO stanza VALUES('G2168','chorus','Du musst voransegeln, Voranpreschen<br/>Du musst voran, vorangeh''n im Herrn.<br/>',NULL,195416,6);
INSERT INTO stanza VALUES('G2169','1','Ja! Voran!<br/>Vorwärts komm!<br/>Ein Herz voller Lieb für Ihn,<br/>Ein Herz voller Willigkeit,<br/>Ein Herz voll Erhabenheit,<br/>Nicht Abgeschlagenheit!<br/>Ja! Voran!<br/>Vorwärts komm!<br/>Hin zum Sohn!<br/>',NULL,195417,1);
INSERT INTO stanza VALUES('G2169','chorus','In Deinem Bilde<br/>Erschaffen sind wir,<br/>Deine Gefäße,<br/>Zum Gefülltsein mit Dir.<br/>Du -- mein Genuss, der<br/>Überfließt aus mir!<br/>Ich als Mensch teil Dein Bild, so<br/>Drück ich Dich aus hier!<br/>',NULL,195418,2);
INSERT INTO stanza VALUES('G2169','2','Ja! Voran!<br/>Vorwärts komm!<br/>Ein Geist, immer brennend,<br/>Ein Herz, das stets sprudelt,<br/>Heilige, die essen<br/>Und ständig trinken!<br/>Ja! Voran!<br/>Vorwärts komm!<br/>Hin zum Sohn!<br/>',NULL,195419,3);
INSERT INTO stanza VALUES('G2169','3','Ja! Voran!<br/>Vorwärts komm!<br/>Im Geist ist''s am besten:<br/>Heilige festen,<br/>Analysieren nicht<br/>Und kritisieren nicht.<br/>Ja! Voran!<br/>Vorwärts komm!<br/>Hin zum Sohn!<br/>',NULL,195420,4);
INSERT INTO stanza VALUES('G2169','4','Ja! Voran!<br/>Vorwärts komm!<br/>Leben so voll Genuss,<br/>Sonst wär es nur Verdruss,<br/>Doch Er ist wunderbar<br/>Und immer für uns da!<br/>Ja! Voran!<br/>Vorwärts komm!<br/>Hin zum Sohn!<br/>',NULL,195421,5);
INSERT INTO stanza VALUES('G2170','1','Jag Ihm nach, erkenn Ihn und bleib in Ihm!<br/>Sieh alles als Verlust an!<br/>Gewinn Ihn, erlang Ihn, ergreife Ihn!<br/>Christus ist unsre Vision.<br/>',NULL,195422,1);
INSERT INTO stanza VALUES('G2170','chorus','Die Dinge vergessend,<br/>Die hinter dir sind,<br/>Geh weiter mit diesem Sinn!<br/>Die Zeit kaufe aus,<br/>Was immer geschieht!<br/>Ergreife, was vor dir liegt!<br/>',NULL,195423,2);
INSERT INTO stanza VALUES('G2170','2','Verfolg Ihn, ergreif Ihn -<br/>Höchster ist Er!<br/>Seine Person, so wertvoll.<br/>Vergiss und verlass nur, was sonst umher,<br/>Lieb Ihn mit Dein''m ganzen Sein!<br/>',NULL,195424,3);
INSERT INTO stanza VALUES('G2170','3','Er ist jetzt mein Zentrum, meine Wirklichkeit,<br/>Mein Leben in Ewigkeit.<br/>Sonst ist alles Abfall im Vergleich zu Ihm,<br/>So lieb und gewinn nur Ihn!<br/>',NULL,195425,4);
INSERT INTO stanza VALUES('G2171','1','Wenn ich in der Wüste bin, trocken, unzufrieden,<br/>Wohin geh ich? Wohin?<br/>Wenn ich leer bin und die Eitelkeit des Lebens tief empfind,<br/>Wohin geh ich? Wohin?<br/>',NULL,195426,1);
INSERT INTO stanza VALUES('G2171','chorus','Ich geh zur Quelle lebendigen Wassers!<br/>Der Strom, der Ursprung des Lebens wohnt tief in mir!<br/>Das Wasser fließt zu jeder Zeit in meinem Geist!<br/>Dorthin geh ich, wo mein Gott fließt!<br/>',NULL,195427,2);
INSERT INTO stanza VALUES('G2171','2','Wenn ich voller Sorgen bin, hab nur Fragen, nichts macht Sinn,<br/>Was mach ich dann? Was dann?<br/>Wenn ich es nicht mehr ertragen kann, ich fühl mich ganz verlor''n,<br/>Was mach ich dann? Was dann?<br/>',NULL,195428,3);
INSERT INTO stanza VALUES('G2171','chorus','Zu Gottes Wort als der Speise dann geh ich!<br/>Versorgung, Nahrung und Wonne, Freude find ich!<br/>Durch Betenlesen wird das Wort zu Geist und Leb''n!<br/>Dorthin geh ich, wo Freude ist!<br/>',NULL,195429,4);
INSERT INTO stanza VALUES('G2171','3','Wenn es scheint, dass alles umsonst ist, das Licht verborgen ist,<br/>Wohin kann ich gehen?<br/>Wenn mir nichts so klar erscheint und alles sehr verwirrend ist,<br/>Wohin kann ich gehen?<br/>',NULL,195430,5);
INSERT INTO stanza VALUES('G2171','chorus','Es gibt Licht im Geist und in der Gemeinde!<br/>Ich flieh dorthin in die Heiligtümer von Gott!<br/>Die Heiligen, sie führen, leiten mich zu Gott!<br/>Dorthin geh ich, wo mein Gott ist!<br/>',NULL,195431,6);
INSERT INTO stanza VALUES('G2171','4','Als ein Ankläger kommt Satan, um mich gnadenlos zu stören,<br/>Auf der Suche ist er nun.<br/>Er zermürbt mich, isoliert mich. Das Verschlingen ist sein Ziel.<br/>Er, ein Löwe, der töten will.<br/>',NULL,195432,7);
INSERT INTO stanza VALUES('G2171','chorus','Doch ich kann immer zum Zufluchtsort gehen.<br/>In meinen Geist, Gottes Wort, die Gemeinde, ich geh!<br/>Verweile nicht, um mit dem Angriff umzugehen!<br/>Fels der Rettung, da flieh ich hin.<br/>',NULL,195433,8);
INSERT INTO stanza VALUES('G2171','SoundCloud Link','https://soundcloud.com/liederstroeme/wenn-ich-in-der-wueste-bin',NULL,195434,9);
INSERT INTO stanza VALUES('G2172','1','Einen Wettlauf gibt''s zu laufen -- Halleluja,<br/>Diesen Weg nimm und den Preis gewinn!<br/>Zu all denen, die mitlaufen -- Halleluja,<br/>Unser Gott sprach: „Schaue weg zu Ihm!"<br/>',NULL,195435,1);
INSERT INTO stanza VALUES('G2172','chorus','Schaue weg! Oh, schaue weg!<br/>Schau auf Jesus unentwegt!<br/>Schaue weg von allem hier, schau auf Jesus,<br/>Deinen Blick doch richte nur auf Ihn!<br/>',NULL,195436,2);
INSERT INTO stanza VALUES('G2172','2','Schaue nicht, was rundum ist -- Halleluja,<br/>Schaue weg von jeder Schwierigkeit!<br/>Schau dahin, wo Frieden fließt -- Halleluja,<br/>Schaue nur auf Seine Herrlichkeit!<br/>',NULL,195437,3);
INSERT INTO stanza VALUES('G2172','3','Schaue weg, von deiner Seele -- Halleluja,<br/>Schaue weg vom mürben Selbst doch drin!<br/>Schaue weg von dir aufs Ziel -- Halleluja,<br/>Schaue weg von allem, schau auf Ihn!<br/>',NULL,195438,4);
INSERT INTO stanza VALUES('G2172','4','Schaue weg von dem, was war -- Halleluja,<br/>Schaue weg von Gut und Bös forthin!<br/>Den Lebendigen halt fest -- Halleluja,<br/>Schaue weg von allem, schau auf Ihn!<br/>',NULL,195439,5);
INSERT INTO stanza VALUES('G2172','5','Suche nur Sein Angesicht -- Halleluja,<br/>Er vollendet auch, was Er begann.<br/>Seine Gnade Er verspricht -- Halleluja --<br/>Für den Wettlauf -- deshalb schau Ihn an!<br/>',NULL,195440,6);
INSERT INTO stanza VALUES('G2173','1','Ich bin dankbar, denn Gott stellte mich,<br/>Seinen Leib aufzubaun, neben dich.<br/>Hoffnung ist mir der Christus in dir!<br/>Und du brauchst auch den Christus in mir.<br/>',NULL,195441,1);
INSERT INTO stanza VALUES('G2173','chorus','Ich lebe, wenn du fest stehst im Herrn.<br/>Du lebst, wenn ich fest stehe im Herrn.<br/>Mein Vorwärtsgehn ist für dich,<br/>Dein Vorwärtsgehn ist für mich,<br/>Ich komm allein nicht weit;<br/>Verzweifelt brauch ich den Leib!<br/>',NULL,195442,2);
INSERT INTO stanza VALUES('G2173','2','Die Geschwister sind uns so vertraut!<br/>Als Braut werden wir aufgebaut!<br/>In Ihm stehn wir fest, denn auch mich<br/>Ermutigt der Herr oft durch dich.<br/>',NULL,195443,3);
INSERT INTO stanza VALUES('G2173','3','Dein Glaube an Christus hilft mir,<br/>Mein Fortschritt hängt auch ab von dir!<br/>Wenn ich bete im Hinblick auf dich,<br/>Mein Herz füllt mit Dankbarkeit sich.<br/>',NULL,195444,4);
INSERT INTO stanza VALUES('G2173','4','Gottes Herz verlangt sehnlichst danach,<br/>Dass zusammen wir laufen Ihm nach.<br/>Du wendest gern auf für mich,<br/>Du weißt, auch ich lebe für dich.<br/>',NULL,195445,5);
INSERT INTO stanza VALUES('G2173','5','Seid alle ermutigt, denn ich<br/>Ohne eure Versorgung kann''s nicht.<br/>Denk nicht, dass es dein''n Anteil nicht braucht.<br/>Christus braucht dich und wir alle auch.<br/>',NULL,195446,6);
INSERT INTO stanza VALUES('G2174','1','Frisch wie der Tau früh am Morgen<br/>Bringst Du die Ruhe, o Herr;<br/>Christus, durch Sein sanftes Salben,<br/>Tröstet mich täglich so sehr:<br/>Steh, bis der Sturm ist vorüber!<br/>Steh, bis dein Herz nicht mehr bangt!<br/>Steh für die Herrlichkeit Jesu,<br/>Steh, bis Sein Reich ist erlangt!<br/>',NULL,195447,1);
INSERT INTO stanza VALUES('G2174','chorus','Deine Stimme, o Herr,<br/>Mir Hoffnung bringt,<br/>In Deiner Gegenwart, Herr,<br/>Mein Herz froh singt.<br/>',NULL,195448,2);
INSERT INTO stanza VALUES('G2174','2','Ist in der Prüfung der Trübsal<br/>Matt mein Herz, träge mein Geist,<br/>Schimmert der Stern meines Glaubens,<br/>Doch auch noch er mir entgleist.<br/>Dann mög Dein Glaube mich trösten,<br/>Stärken mit Leben und Kraft,<br/>Damit Dein Reichtum mir reichlich<br/>Herrlichkeit ewig verschafft.<br/>',NULL,195449,3);
INSERT INTO stanza VALUES('G2174','3','Herr, wie die Sonne am Morgen,<br/>Finsternis völlig verjag,<br/>Mit Deinen Flügeln der Heilung<br/>Wend meine Nacht nun zum Tag!<br/>Komm Du, o komm, Herr des Trostes,<br/>Tröstung hinein in mich gieß!<br/>Hoffnung der Herrlichkeit, stärk mich,<br/>Bis ich den Frieden genieß!<br/>',NULL,195450,4);
INSERT INTO stanza VALUES('G2175','1','Obwohl nichts lief, wie ich es geplant hab,<br/>Wende ich mein Herz jetzt zum Herrn.<br/>Ich warte nicht auf das Ende des Chaos.<br/>Gut oder Schlecht -- es ist egal.<br/>',NULL,195451,1);
INSERT INTO stanza VALUES('G2175','chorus','Ich schaue jetzt von allem weg!<br/>Herr, meine Augen sind auf Dich gerichtet!<br/>Mir ist egal, was rundherum passiert,<br/>Mein Herz ist dem Herrn zugewandt.<br/>',NULL,195452,2);
INSERT INTO stanza VALUES('G2175','2','Ändern sich meine Umstände gar nicht --<br/>Nur noch mehr Probleme hab ich.<br/>Vielleicht wird sich das Chaos vermehren --<br/>Das bedeutet gar nichts für mich.<br/>',NULL,195453,3);
INSERT INTO stanza VALUES('G2175','3','Bis ans Ziel, Jesus, kannst Du mich bringen --<br/>Vollender des Glaubens bist Du.<br/>In meinem Chaos doch auf dem Thron bist Du,<br/>Erfüllst Deinen ewigen Plan.<br/>',NULL,195454,4);
INSERT INTO stanza VALUES('G2175','SoundCloud Link','https://soundcloud.com/liederstroeme/ich-schaue-jetzt-von-allem-weg',NULL,195455,5);
INSERT INTO stanza VALUES('G2176','1','Jetzt seh ich, Herr,<br/>Du willst nur, dass ich an Dich glaub,<br/>Nicht verweil<br/>In Mängeln oder Niederlagen.<br/>Soll doch glauben, was Du tatst,<br/>Nicht an das, was ich seh.<br/>',NULL,195456,1);
INSERT INTO stanza VALUES('G2176','2','Ich glaub Dir, Herr,<br/>Wenn Niederlagen rings um mich<br/>Und es scheint, dass sich nichts ändert äußerlich.<br/>Nein, entmutigt werd ich nicht.<br/>Ich glaub Dir, mein Herr.<br/>',NULL,195457,2);
INSERT INTO stanza VALUES('G2176','3','Oh ja, ich glaub,<br/>Ansprüche stellst Du nicht an mich.<br/>Einfach glauben, das ist, was Du von mir willst.<br/>Frei von Ängsten, Zweifeln, Herr.<br/>Befreit, zu glauben Dir.<br/>',NULL,195458,3);
INSERT INTO stanza VALUES('G2176','4','Ich glaube Dir,<br/>Denn Du allein bist mein Erfolg.<br/>Versag ich, muss ich bekennen lediglich,<br/>Dich genießen weiterhin.<br/>Ich glaube Dir so gern.<br/>',NULL,195459,4);
INSERT INTO stanza VALUES('G2177','1','Christus als Leben kam,<br/>Gott dreieins durch den Prozess schritt.<br/>Gott, der Vater: Urquell,<br/>der Brunnen, der dann hervortritt<br/>Als der Sohn -- sprudelnd'' Quelle zu sein,<br/>Und der Geist als der Strom voller Leben ist mein.<br/>Erstaunliches Wunder ist hier:<br/>Der Dreieine Gott fließt in mir!<br/>Oh, Lebensströme in mir<br/>fließen aus meinem innersten Sein!<br/>Lebensströme in mir<br/>fließen aus meinem innersten Sein!<br/>',NULL,195460,1);
INSERT INTO stanza VALUES('G2177','chorus','Dieses Leben nun fließt,<br/>Überfließend Zustrom ist.<br/>Leben Sünde verschlingt!<br/>Kraft tief drinnen entspringt!<br/>Geht voran! Überwinden wird leicht und spontan.<br/>',NULL,195461,2);
INSERT INTO stanza VALUES('G2177','2','Dieses Leben befreit,<br/>doch ist es nicht nur für den Sieg.<br/>Gottes Vorsatz ist mehr,<br/>Sein Plan verspricht uns noch so viel.<br/>Dieses Leben nicht ziellos hinfließt,<br/>Die höchste Vollendung auch mich mit einschließt.<br/>Es wächst und es sprießt, formt uns, wenn es fließt.<br/>Sein'' Bestimmung ist nun auch mein Ziel!<br/>Oh, Lebensströme in mir<br/>fließen aus meinem innersten Sein!<br/>Lebensströme in mir<br/>fließen aus meinem innersten Sein!<br/>',NULL,195462,3);
INSERT INTO stanza VALUES('G2177','chorus','Gott und Mensch bleiben hier,<br/>Gegenseitig wohnen wir,<br/>Lamm, Geist, Ehefrau, Braut.<br/>Kommt! Trinkt! Am Ufer - schaut! --<br/>Wächst der Baum, höchste Freude uns im Weltenraum.<br/>',NULL,195463,4);
INSERT INTO stanza VALUES('G2177','3','Kein Grund, grimmig zu schaun,<br/>denn das Zoe-Leben hab ich.<br/>Leben nimmt seinen Lauf,<br/>und es gewinnt unweigerlich.<br/>Bleibt im Strom! Gott verlangt sonst nichts mehr,<br/>Denn ich weiß, wenn ich trinke, das Wachstum gibt Er.<br/>Mein Herz freudig singt, meine Schritte beschwingt<br/>Und mit strahlender Miene sing ich:<br/>Oh, Lebensströme in mir<br/>fließen aus meinem innersten Sein!<br/>Lebensströme in mir<br/>fließen aus meinem innersten Sein!<br/>',NULL,195464,5);
INSERT INTO stanza VALUES('G2178','1','Unser Herz ist der Grund,<br/>Auf dem der Herr Sein Wachstum sucht.<br/>Doch fällt der Same auf Dornen, Fels oder Wegrand,<br/>Dann brauchen wir die Errettung durch<br/>Das Gebet, das Wort Gottes,<br/>Verborgene Zeit mit unserem Herrn.<br/>',NULL,195465,1);
INSERT INTO stanza VALUES('G2178','chorus','Du kämpfst um unser Herz,<br/>Damit Du wachsen kannst,<br/>Damit Du Dich vermehrst<br/>In unserm ganzen Sein.<br/>Herr, säe, wachse, wandle um,<br/>Bis wir ein Leben für Deine Ökonomie führen!<br/>',NULL,195466,2);
INSERT INTO stanza VALUES('G2178','2','Unser Herz ist der Grund,<br/>Auf dem der Herr Sein Wachstum sucht.<br/>Nun fällt der Same auf gute fruchtbare Erde,<br/>Dann sind wir völlig bereit, um das Wort<br/>Zu empfang''n, uns zu wenden<br/>Und zu bekennen -- Er braucht unser Herz.<br/>',NULL,195467,3);
INSERT INTO stanza VALUES('G2178','SoundCloud Link','https://soundcloud.com/liederstroeme/unser-herz-ist-der-grund',NULL,195468,4);
INSERT INTO stanza VALUES('G2179','1','Hast du deinen Geist gefunden?<br/>Öffne einfach deinen Mund!<br/>„Halleluja, o Herr Jesus!"<br/>So tun wir Ihn heute kund.<br/>',NULL,195469,1);
INSERT INTO stanza VALUES('G2179','chorus','Was aus Gott geboren ist -- unser Geist --<br/>Preist Gott, Er hat es vollbracht!<br/>Was aus Geist geboren ist -- unser Geist,<br/>Und beide sind eins gemacht.<br/>',NULL,195470,2);
INSERT INTO stanza VALUES('G2179','2','Warte nicht mehr auf Eingebung --<br/>Das ist nur des Feindes List.<br/>Öffne dich! Befrei deinen Geist,<br/>Zeige, dass du jetzt frei bist!<br/>',NULL,195471,3);
INSERT INTO stanza VALUES('G2180','chorus','Weißt du''s schon: Ich bin ein Gott-Mensch!<br/>Ein dreiteil''ger Mensch mit dem Dreieinen Gott vermengt.<br/>Und ich hab ''nen Geist,<br/>Wo der Feind keine Hoffnung hat,<br/>Keinen Weg, keinen Raum.<br/>Ich bin ein Gott-Mensch!<br/>[Rufen: Ich bin ein Gott-Mensch!]<br/>',NULL,195472,1);
INSERT INTO stanza VALUES('G2180','1','Der Herr Jesus lebt in mir<br/>Und Er braucht meinen Geist als die Basis.<br/>Er breitet Sich aus in jeden Teil von Verstand, Gefühl und Willn.<br/>Als ein Same hat Er Sich tief in mein Herz gesät<br/>Und das Reich ist hier, heute wächst es in mir,<br/>Und mein Herz gehört jetzt Ihm.<br/>',NULL,195473,2);
INSERT INTO stanza VALUES('G2180','2','Immer, wenn ich „Amen" sag,<br/>Und in meinem vermengten Geist wandle,<br/>Da wächst und sprießt der Lebenssamen und entwickelt sich.<br/>Äußerlich sieht es so aus, als ob gar nichts passiert.<br/>Doch ich bin nicht gleich, denn, wenn der Same wächst,<br/>Werde ich innerlich zu Gott.<br/>',NULL,195474,3);
INSERT INTO stanza VALUES('G2181','1','Gott will gleichgestalten alle<br/>Seinem erstgebornen Sohn;<br/>Darum wandelt uns Sein Geist um<br/>Und Er tut es heute schon.<br/>',NULL,195475,1);
INSERT INTO stanza VALUES('G2181','chorus','Wandle uns, Herr, in Dein Bild um<br/>In Verstand, Gefühl und Willn!<br/>Mög Dein Geist, Herr, uns durchdringen,<br/>Unser ganzes Sein erfülln!<br/>',NULL,195476,2);
INSERT INTO stanza VALUES('G2181','2','Gott hat uns mit Seinem Leben<br/>Neu geborn in unsrem Geist;<br/>Unsre Seele wandelt Er um<br/>Durch Sein Leben, das uns speist.<br/>',NULL,195477,3);
INSERT INTO stanza VALUES('G2181','3','Gott geht stets von unsrem Geist aus,<br/>Wandelt unsre Seele um;<br/>Er erneuert innre Teile,<br/>Bis Er uns regiert rundum.<br/>',NULL,195478,4);
INSERT INTO stanza VALUES('G2181','4','Durch die Kraft des Geistes wandelt<br/>Er uns um in Gottes Bild;<br/>Uns von Herrlichkeit zu Herrlichkeit<br/>Gleich zu machen, ist gewillt.<br/>',NULL,195479,5);
INSERT INTO stanza VALUES('G2181','5','Er verwandelt, alles heiligt,<br/>Bis wir reif sind und Ihm gleich;<br/>Unsre Seele Er durchsättigt,<br/>Bis Sein Wuchs ist ganz erreicht.<br/>',NULL,195480,6);
INSERT INTO stanza VALUES('G2182','1','An dem heil''gsten Ort, Gnade finde dort,<br/>Gnade fließt vom Thron wie ein Strom;<br/>An dem heil''gsten Ort, Gnade finde dort,<br/>Gnade fließt vom Thron wie ein Strom.<br/>',NULL,195481,1);
INSERT INTO stanza VALUES('G2182','chorus','Halleluja! Halleluja!<br/>Gnade fließt vom Thron wie ein Strom;<br/>Halleluja! Halleluja!<br/>Gnade fließt vom Thron wie ein Strom.<br/>',NULL,195482,2);
INSERT INTO stanza VALUES('G2182','2','In des Heil''gsten Licht seh Sein Angesicht,<br/>Herrlichkeit wird scheinen durch mich;<br/>In des Heil''gsten Licht seh Sein Angesicht,<br/>Herrlichkeit wird scheinen durch mich.<br/>',NULL,195483,3);
INSERT INTO stanza VALUES('G2182','chorus','Halleluja! Halleluja!<br/>Herrlichkeit wird scheinen durch mich;<br/>Halleluja! Halleluja!<br/>Herrlichkeit wird scheinen durch mich.<br/>',NULL,195484,4);
INSERT INTO stanza VALUES('G2182','3','Dich zum Geiste wend! Und der Weihrauch brennt.<br/>Komm, die Lebensquelle berühr!<br/>Dich zum Geiste wend! Und der Weihrauch brennt.<br/>Komm, die Lebensquelle berühr!<br/>',NULL,195485,5);
INSERT INTO stanza VALUES('G2182','chorus','Halleluja! Halleluja!<br/>Komm, die Lebensquelle berühr!<br/>Halleluja! Halleluja!<br/>Komm, die Lebensquelle berühr!<br/>',NULL,195486,6);
INSERT INTO stanza VALUES('G2183','1','In dem mächt''gen Namen Jesu<br/>Knien wir nieder vor dem Thron,<br/>Wird dann manch ein Feind bezwungen,<br/>Tragen wir den Sieg davon.<br/>',NULL,195487,1);
INSERT INTO stanza VALUES('G2183','chorus','Nur im Namen des Herrn<br/>Sind wir siegreich immerfort!<br/>In dem Namen des Herrn<br/>Sind besiegt die Sünd und Tod!<br/>',NULL,195488,2);
INSERT INTO stanza VALUES('G2183','2','Bitten wir im Namen Jesu,<br/>Müssen Satans Heere fliehn.<br/>Jesus! Jesus! Teurer Jesus!<br/>Lässt von Sieg zu Sieg uns ziehn.<br/>',NULL,195489,3);
INSERT INTO stanza VALUES('G2183','3','Bald schon ist der Kampf gewonnen,<br/>Siegesfreude uns entzückt,<br/>Wenn der starke Name Jesu<br/>Uns zu Seinem Thron entrückt.<br/>',NULL,195490,4);
INSERT INTO stanza VALUES('G2184','1','Für Gemeinschaft bet zu Jesus,<br/>Such im Geist Sein Angesicht!<br/>Seine Gegenwart genieße,<br/>Hör im Stillen, was Er spricht!<br/>',NULL,195491,1);
INSERT INTO stanza VALUES('G2184','chorus','Für Gemeinschaft bet zu Jesus,<br/>Such im Geist Sein Angesicht!<br/>Seine Gegenwart genieße,<br/>Hör im Stillen, was Er spricht!<br/>',NULL,195492,2);
INSERT INTO stanza VALUES('G2184','2','Für Gemeinschaft bet zu Jesus,<br/>Offne Ihm Dein ganzes Sein<br/>Und mit aufgedecktem Antlitz<br/>Schau Ihn, einfach, echt und rein!<br/>',NULL,195493,3);
INSERT INTO stanza VALUES('G2184','3','Für Gemeinschaft bet zu Jesus,<br/>Ihm in allem stets vertrau!<br/>Ihn als Geist lern zu berühren<br/>Und in Ehrfurcht auf Ihn schau!<br/>',NULL,195494,4);
INSERT INTO stanza VALUES('G2184','4','Für Gemeinschaft bet zu Jesus,<br/>Echt und froh Ihn kontaktier!<br/>Deinem Geist entsprechend bete,<br/>Durchs Empfinden tief in dir!<br/>',NULL,195495,5);
INSERT INTO stanza VALUES('G2184','5','Für Gemeinschaft bet zu Jesus,<br/>Höre ernsthaft, was Er will!<br/>Lass dir zeigen Seine Absicht,<br/>Gib dich hin und folg Ihm still!<br/>',NULL,195496,6);
INSERT INTO stanza VALUES('G2184','6','Für Gemeinschaft bet zu Jesus,<br/>Bad in Seinem Angesicht!<br/>Seine Schönheit dich durchsättigt,<br/>So lässt strahlen hell Sein Licht.<br/>',NULL,195497,7);
INSERT INTO stanza VALUES('G2185','1','Guten Morgen, Herr Jesus!<br/>Danke für diesen Tag.<br/>Danke für mein''n Geist, Herr,<br/>Dass ich beten kann!<br/>Guten Morgen, Herr Jesus!<br/>Dir singe ich so gern.<br/>Danke für alles, o Herr!<br/>',NULL,195498,1);
INSERT INTO stanza VALUES('G2186','1','Die Bibel gottgehaucht --<br/>Essenz des Wesens Gottes. (2.Tim. 3:16)<br/>Von Gott her spricht der Mensch<br/>Vom Heil''gen Geist getrieben. (2.Petr. 1:21)<br/>Die Bibel ist Sein Sprechen<br/>In den Propheten und im Sohn. (Hebr. 1:1-2)<br/>Die Bibel ist die Offenbarung<br/>Vom Heiligen Geist. (Joh. 16:13)<br/>',NULL,195499,1);
INSERT INTO stanza VALUES('G2186','2','Die Bibel, sie bezeugt<br/>Uns über den Herrn Jesus. (Joh. 5:39)<br/>Die Bibel weise macht,<br/>Weise zur Errettung. (2.Tim. 3:15)<br/>Aufgrund der Bibel wird<br/>Der Mensch wiedergeboren. (1.Petr. 1:23)<br/>Uns geistliche Milch (1.Petr. 2:2)<br/>Und Lebensbrot, (Mt. 4:4)<br/>Vollständig macht sie uns. (2.Tim. 3:17).<br/>',NULL,195500,2);
INSERT INTO stanza VALUES('G2187','1','Mein Herz ist hungrig und durstig mein Geist,<br/>Ich komm zu Dir für Versorgung so frei;<br/>Was ich auch brauche, allein bist nur Du,<br/>Hunger und Durst mir stillst Du nur allein.<br/>',NULL,195501,1);
INSERT INTO stanza VALUES('G2187','chorus','Speis mich, Herr Jesus, tränk mich mit Dir,<br/>Still meinen Hunger, lösch meinen Durst;<br/>Flut mich mit Freud, sei die Lebenskraft mir,<br/>Still meinen Hunger, lösch meinen Durst.<br/>',NULL,195502,2);
INSERT INTO stanza VALUES('G2187','2','Wasser und Brot, Herr, des Lebens bist Du.<br/>Nun meinen Geist reich beleb und begieß;<br/>Gern möcht ich essen und trinken von Dir,<br/>Dich durch mein Lesen und Beten genieß.<br/>',NULL,195503,3);
INSERT INTO stanza VALUES('G2187','3','Du bist das Wort, Gottes Fülle in Dir,<br/>Geist bist Du, sodass Gott mein Leben sei;<br/>Dich, Herr, genieß ich als Speise im Wort,<br/>Du als der Geist bist mir Wasser so frei.<br/>',NULL,195504,4);
INSERT INTO stanza VALUES('G2187','4','Du kamst als Speise vom Himmel herab,<br/>Um mich zu tränken, ließt schlagen Du Dich;<br/>Als unerschöpfliche Speise bist Du<br/>Und auch das Wasser des Lebens für mich.<br/>',NULL,195505,5);
INSERT INTO stanza VALUES('G2187','5','Herr, in dem Wort bist Du Leben und Geist,<br/>Sodass durchs Wort ich von Dir mich ernähr;<br/>Du lebst in meinem Geist nun als der Geist,<br/>Sodass im Geist ich von Dir trinke, Herr.<br/>',NULL,195506,6);
INSERT INTO stanza VALUES('G2187','6','Um zu genießen, nun komm ich zum Wort,<br/>Esse von Dir, bis mein Hunger vergeht;<br/>Dir wend ich mich nun in meinem Geist zu,<br/>Trinke von Dir, bis kein Durst mehr besteht.<br/>',NULL,195507,7);
INSERT INTO stanza VALUES('G2187','7','Essen und trinken, Herr Jesus, von Dir,<br/>Esse durch Lesen, und trink durch Gebet;<br/>Lesen und beten -- so ess ich und trink,<br/>Beten und lesen -- mein Geist aufersteht.<br/>',NULL,195508,8);
INSERT INTO stanza VALUES('G2187','8','Hier, feste ich, liebster Herr, nun mit Dir,<br/>Reich tränkt Dein Geist und Dein Wort füllt mich sehr;<br/>Sei Du mein herrliches Fest jeden Tag,<br/>Wie es noch niemand erfahren hat, Herr.<br/>',NULL,195509,9);
INSERT INTO stanza VALUES('G2188','1','Ich komm zu Dir, o Herr,<br/>Es dürstet mich nach Dir.<br/>Von Dir ich ess, von Dir ich trink,<br/>In Dir mich ganz verlier.<br/>',NULL,195510,1);
INSERT INTO stanza VALUES('G2188','2','Dein Angesicht zu sehn,<br/>Ist meines Herzens Schrei.<br/>Ich trinke sehnlich, Herr, von Dir,<br/>Mein Durst erlischt dabei.<br/>',NULL,195511,2);
INSERT INTO stanza VALUES('G2188','3','Mein Herz erfreut''s, zu sehn<br/>Dein helles Angesicht.<br/>Hier will ich bleiben immerdar,<br/>Beständig schauen Dich.<br/>',NULL,195512,3);
INSERT INTO stanza VALUES('G2188','4','In solch Gemeinschaft, Herr,<br/>Bist Du die Gnade mir.<br/>Du füllst mit Freude Herz und Geist,<br/>So find ich Ruh in Dir.<br/>',NULL,195513,4);
INSERT INTO stanza VALUES('G2188','5','Gerne verweil ich hier,<br/>Immerzu suche Dich,<br/>Ich bleib im Wort und im Gebet,<br/>Bis Du, Herr, fließt durch mich.<br/>',NULL,195514,5);
INSERT INTO stanza VALUES('G2189','1','Die Gemeinde ist so herrlich und wir sind ein Teil von ihr --<br/>Wir sind glücklich, denn der Herr hat uns vereint!<br/>Einen Leib im Universum gibt''s, dazu gehören wir.<br/>Halleluja, denn der Herr hat uns vereint!<br/>',NULL,195515,1);
INSERT INTO stanza VALUES('G2189','chorus','Halleluja für den Leib hier!<br/>Wir sind Glieder Seines Leibes!<br/>Wir sind ganz für Seinen Leib hier!<br/>Halleluja, denn der Herr hat uns vereint!<br/>',NULL,195516,2);
INSERT INTO stanza VALUES('G2189','2','Nicht die Einzelchristen, sondern einen korp''rativen Leib,<br/>Ist was Gott für Seinen Ausdruck heut verlangt;<br/>Nicht die einzelnen Gemeinden, sondern ein vermengter Leib --<br/>Halleluja, wir sind in den Leib gelangt!<br/>',NULL,195517,3);
INSERT INTO stanza VALUES('G2189','chorus','Halleluja für den Leib hier!<br/>Satan zittert vor dem Leibe!<br/>Wir sind siegreich nur im Leibe!<br/>Halleluja, wir sind jetzt in Christi Leib!<br/>',NULL,195518,4);
INSERT INTO stanza VALUES('G2189','3','Es gibt sieben goldne Leuchter, alle göttlicher Natur --<br/>Nichts Natürliches der Leib erlauben kann;<br/>Die Natur von Gott vereint uns, deshalb strahlt ihr Licht so hell --<br/>Halleluja, schaut die hellen Leuchter an!<br/>',NULL,195519,5);
INSERT INTO stanza VALUES('G2189','chorus','Halleluja für den Leib hier!<br/>Für die Leuchter Seines Leibes!<br/>Für den goldnen, hellen Leib hier!<br/>Halleluja, schaut die hellen Leuchter an!<br/>',NULL,195520,6);
INSERT INTO stanza VALUES('G2189','4','Wie stehn wir in dieser Einheit, scheinen hell mit Göttlichkeit?<br/>Halleluja, Jesus essen ist der Weg!<br/>Er ist unser Baum des Lebens, Manna, Fest in Ewigkeit --<br/>Halleluja, Ihn zu essen, täglich pfleg!<br/>',NULL,195521,7);
INSERT INTO stanza VALUES('G2189','chorus','Wir sind eins durch essen Jesus!<br/>Göttlich sind durch essen Jesus!<br/>Scheinen hell durch essen Jesus!<br/>Halleluja, Jesus essen ist der Weg!<br/>',NULL,195522,8);
INSERT INTO stanza VALUES('G2190','1','Die Bibel die Geschichte<br/>Einer heil''gen Liebe zeigt.<br/>Gott und die Auserwählten<br/>In Liebe sind vereint.<br/>Ein Ehepaar auf ewig<br/>Man in der Bibel findt.<br/>Bräutigam ist Gott in Christus,<br/>Die Braut die Heil''gen sind.<br/>',NULL,195523,1);
INSERT INTO stanza VALUES('G2190','2','Durch Schatten und Sinnbilder<br/>Man Gott''s tiefsten Wunsch erkennt.<br/>Der Ehemann ist Christus<br/>Durch Adam dargestellt.<br/>Die Rippe kam aus Adam<br/>Und zeigt, worauf Gott schaut.<br/>Aus ihr hat Gott die Eva<br/>Als Adams Frau gebaut.<br/>',NULL,195524,2);
INSERT INTO stanza VALUES('G2190','3','Sein Volk zur Frau zu nehmen,<br/>Ihnen Ehemann zu sein,<br/>Das ist auf Gottes Herzen --<br/>Zu leben in Einheit.<br/>Nur Opfer und Anbetung<br/>Befriedigten Ihn nicht.<br/>Er wollte sie heiraten!<br/>Das war Gottes Absicht.<br/>',NULL,195525,3);
INSERT INTO stanza VALUES('G2190','4','Diese Liebe wird aufs Beste<br/>Dargestellt im Hohelied;<br/>Nach Küssen des Geliebten<br/>Die Suchende sich sehnt.<br/>Das Werk der Lieb'' bringt in ihr<br/>Nichts Eigenes hervor.<br/>Zur Stadt wird sie nun werden,<br/>Nur Christus ihr'' Person.<br/>',NULL,195526,4);
INSERT INTO stanza VALUES('G2190','5','Die Braut ist die Gemeinde,<br/>Christus ist der Bräutigam.<br/>Durch Wiedergeburt sie einst<br/>Aus Seiner Seite kam.<br/>In Ursprung, Leben, Wesen,<br/>Person sind wir ganz eins,<br/>Ewiglich Sein Gegenüber --<br/>Das Neu'' Jerusalem.<br/>',NULL,195527,5);
INSERT INTO stanza VALUES('G2191','1','Von Natur warn wir in Sünde tot,<br/>Lebten nur in Unstimmigkeit;<br/>Doch zusammen hat uns Gott belebt,<br/>Um zu sitzen mit dem Herrn nun allezeit.<br/>',NULL,195528,1);
INSERT INTO stanza VALUES('G2191','chorus','Jesus, Er fügt uns nun zusammen.<br/>Komm und sieh -- die Heiligen vereint!<br/>Seine Liebe bindet uns zusammen,<br/>Bis der Wuchs der Fülle Christi ist erreicht.<br/>',NULL,195529,2);
INSERT INTO stanza VALUES('G2191','2','Mit den Heiligen erfassen wir<br/>Alle Dimensionen des Herrn.<br/>Christi Liebe alles übersteigt,<br/>Bis zur Fülle Gottes füllt Er uns so gern.<br/>',NULL,195530,3);
INSERT INTO stanza VALUES('G2191','3','Unsres Gottes Absicht kennen wir,<br/>Sein Geheimnis ist uns nun bekannt,<br/>Christus, die Gemeinde sehen wir<br/>Und zusammen machen wir den Feind zuschand.<br/>',NULL,195531,4);
INSERT INTO stanza VALUES('G2191','4','Daher beten wir zum Vater Gott --<br/>In den innren Menschen uns doch stärk!<br/>Richte Dich in unsren Herzen ein,<br/>Wurzle uns in Deiner Liebe für Dein Werk!<br/>',NULL,195532,5);
INSERT INTO stanza VALUES('G2191','5','Alle Glieder reichen Christus dar,<br/>Werden eingebaut im Leib so gern,<br/>Jeder wirkt gemäß dem eignen Maß,<br/>Und in Liebe baut sich auf der Leib des Herrn.<br/>',NULL,195533,6);
INSERT INTO stanza VALUES('G2191','6','Als der neue Mensch erfüllen wir<br/>Gottes Plan, da wir in Einheit stehn;<br/>Ehre Ihm in der Gemeinde sei<br/>Und in Christus Jesus ewiglich -- Amen!<br/>',NULL,195534,7);
INSERT INTO stanza VALUES('G2192','1','Preis sei Dir, Herr, für Deinen Plan,<br/>Wir dürfen Deine Wohnung sein!<br/>Du lebst in uns, füllst uns mit Dir,<br/>Dein Ausdruck ist im Sohn allein.<br/>',NULL,195535,1);
INSERT INTO stanza VALUES('G2192','2','Du schufst uns, Herr, in Deinem Bild.<br/>Uns gabst Du die Autorität,<br/>Doch ganz aus Ton sind wir gemacht,<br/>Ohne ein Körnchen Göttlichkeit.<br/>',NULL,195536,2);
INSERT INTO stanza VALUES('G2192','3','Nehmen wir Dich als Leben auf,<br/>Deine Natur durch Gnad Du gibst;<br/>Mit Dir vermengt zum Ausdruck kommt<br/>Dein Leib so herrlich, den Du liebst.<br/>',NULL,195537,3);
INSERT INTO stanza VALUES('G2192','4','Unsere Seele erneure, füll<br/>Mit Deinem Leben immerzu,<br/>Bis wir als Perle, Edelstein<br/>Tragen Dein Bild, sind gleich wie Du!<br/>',NULL,195538,4);
INSERT INTO stanza VALUES('G2192','5','Dir gleich geformt zu werden, ist<br/>Niemals für unsren Ruhm gedacht,<br/>Doch für Dein Haus hast Du aus uns<br/>Wertvolles Material gemacht.<br/>',NULL,195539,5);
INSERT INTO stanza VALUES('G2192','6','Dir geben wir uns hin, o Herr,<br/>Nimm uns in Deine weise Hand!<br/>Brich uns und bau uns in Dir auf,<br/>Bring uns als Haus auf Deinen Stand!<br/>',NULL,195540,6);
INSERT INTO stanza VALUES('G2192','7','Unseren alten Menschen brich,<br/>Schleife an jeder Eigenheit,<br/>Dass wir nicht unabhängig sind,<br/>Sondern in Einheit allezeit.<br/>',NULL,195541,7);
INSERT INTO stanza VALUES('G2192','8','Als Deine Braut dann werden wir<br/>Voll Freud in Deiner Kammer weiln,<br/>Wo Deine Liebe überfließt;<br/>Oh, wie wirst Du zufrieden sein!<br/>',NULL,195542,8);
INSERT INTO stanza VALUES('G2193','1','Welch ein Töpfer bist Du, Herr,<br/>Und ein Baumeister dazu!<br/>Herrlich formst Du Dein Gefäß,<br/>Mit dem Haus in Sicht baust Du.<br/>Herr, ich bin ein Mensch aus Ton<br/>Und ein neu belebter Stein,<br/>Dein Gefäß, das Dich enthält,<br/>Um Dein Tempel hier zu sein.<br/>',NULL,195543,1);
INSERT INTO stanza VALUES('G2193','2','Du Gefäße, ganz aus Ton,<br/>Wandelst um, machst sie so reich;<br/>Durch Dein Leben, rein wie Gold,<br/>Sind wir Edelsteinen gleich.<br/>Schließlich durch Dein Bauwerk, Herr,<br/>Werden wir zu Deiner Braut;<br/>Du und wir -- in einem Leib,<br/>Ganz zufrieden, wie vertraut!<br/>',NULL,195544,2);
INSERT INTO stanza VALUES('G2193','3','Was Dein Herz sich wünscht, sind nicht<br/>Lose Steine, ganz allein;<br/>Du willst sie zusammenbaun,<br/>Deine Wohnung hier zu sein.<br/>Du, der Allerreichste, willst<br/>Die Gemeinde aufgebaut,<br/>Dass Dein ganzer Reichtum hell<br/>Voll und ganz aus ihr erstrahlt.<br/>',NULL,195545,3);
INSERT INTO stanza VALUES('G2193','4','Keine geistliche Person,<br/>Die für sich allein nur lebt,<br/>Korp''ratives Leben nur<br/>Dir gefällt und Dich erhebt.<br/>Lose Glieder, abgetrennt,<br/>Wenig Ausdruck sind allein,<br/>Nur Dein aufgebauter Leib,<br/>Der kann Deine Fülle sein.<br/>',NULL,195546,4);
INSERT INTO stanza VALUES('G2193','5','Mit den Heil''gen bau mich auf!<br/>Will nicht unabhängig sein,<br/>Füg mich ein nach Deinem Plan,<br/>Wie es passt, so setz mich ein!<br/>Auf Erfahrung poch ich nicht,<br/>Gaben machen mich nicht dreist;<br/>Ich geb alles für Dein Haus,<br/>Dass Du, Herr, verherrlicht seist.<br/>',NULL,195547,5);
INSERT INTO stanza VALUES('G2194','1','Es fließe frei mein Geist,<br/>Er fließe frei!<br/>Ich fleh zu Dir, o Herr,<br/>Er fließe frei!<br/>Vergangnes lass ich sein,<br/>Die Mauern reiße ein,<br/>Will meinen Geist befrein,<br/>Er fließe frei!<br/>',NULL,195548,1);
INSERT INTO stanza VALUES('G2194','2','Es fließe frei mein Geist,<br/>Er fließe frei!<br/>Ich ruf Dich an, o Herr,<br/>Er fließe frei!<br/>Nicht Selbstzufriedenheit<br/>Noch Selbstgefälligkeit,<br/>Mein Geist sei ganz bereit,<br/>Er fließe frei!<br/>',NULL,195549,2);
INSERT INTO stanza VALUES('G2194','3','Es fließe frei mein Geist,<br/>Er fließe frei!<br/>Inständig bitt ich Dich,<br/>Er fließe frei!<br/>Hochmütig nicht zu sein,<br/>Stolz nehm mich nicht mehr ein,<br/>Ich fließe nun so rein,<br/>Fließ immerzu!<br/>',NULL,195550,3);
INSERT INTO stanza VALUES('G2194','4','Es fließe frei mein Geist,<br/>Er fließe frei!<br/>Hierzu ersuch ich Dich,<br/>Er fließe frei!<br/>Absondern ist vorbei,<br/>Von Selbstverbessrung frei,<br/>Mein Geist gedämpft nicht sei,<br/>Doch kräftig fließ!<br/>',NULL,195551,4);
INSERT INTO stanza VALUES('G2194','5','Es fließe frei mein Geist,<br/>Er fließe frei!<br/>Ich bitt Dich, lieber Herr,<br/>Er fließe frei!<br/>Mein Selbstvertrauen brich!<br/>Vom Thron des Selbst weich ich,<br/>Im Geist durchströmst Du mich,<br/>Mit Leben, Herr.<br/>',NULL,195552,5);
INSERT INTO stanza VALUES('G2194','6','Es fließe frei mein Geist,<br/>Er fließe frei!<br/>Mein Beten, Herr, erhör,<br/>Er fließe frei!<br/>Oh, nicht nur Du und ich,<br/>Mit andren baue mich,<br/>Vermeng uns innerlich,<br/>Im Geist, o Herr!<br/>',NULL,195553,6);
INSERT INTO stanza VALUES('G2195','1','Einheit ist nicht Einigkeit,<br/>Übereinstimmung,<br/>Ist ein Leben im<br/>Leben von Gott!<br/>Der Dreieine Gott -- Er schloss uns ein<br/>In Seiner göttlichen<br/>Einheit -- Einheit.<br/>',NULL,195554,1);
INSERT INTO stanza VALUES('G2195','2','Dass sie alle eins sei''n,<br/>Genau wie Du, Vater, in Mir bist<br/>Und Ich in Dir,<br/>Dass sie in uns<br/>In uns seien.<br/>Einheit -- Einheit.<br/>',NULL,195555,2);
INSERT INTO stanza VALUES('G2196','1','Ich liebe Deine Wohnung, Herr,<br/>Deine Gemeind, so lieb;<br/>Sie -- Deines Herzens Freude hier --<br/>Allein Dir Ruhe gibt.<br/>',NULL,195556,1);
INSERT INTO stanza VALUES('G2196','2','Für sie gabst Du Dich hin, o Herr,<br/>Dass sie Dir ganz gehör;<br/>Auch ihretwegen geb ich mich<br/>Für Deinen Herzbegehr.<br/>',NULL,195557,2);
INSERT INTO stanza VALUES('G2196','3','Du bist mein Leben und sie ist<br/>Mein Lebenswandel hier;<br/>Für sie verleugne ich mich selbst,<br/>Sie sei erfüllt mit Dir.<br/>',NULL,195558,3);
INSERT INTO stanza VALUES('G2196','4','Deine geliebte Braut ist sie,<br/>Du in dem Leib gesehn;<br/>Sie -- meines Herzens Freude hier,<br/>Auf die ich mich stets lehn.<br/>',NULL,195559,4);
INSERT INTO stanza VALUES('G2196','5','In ihr versorgst Du mich so reich,<br/>Sodass mir nichts mehr fehlt;<br/>In ihr bin ich Dein Eigentum,<br/>Was Dich zufriedenstellt.<br/>',NULL,195560,5);
INSERT INTO stanza VALUES('G2196','6','Ich liebe Deine Wohnung, Herr,<br/>Deine Gemeind, Dein Haus;<br/>Hier möcht ich leben ewiglich,<br/>Nie will ich mehr hinaus.<br/>',NULL,195561,6);
INSERT INTO stanza VALUES('G2197','1','Willst du deinen Gott nicht kenn''n?<br/>Was in Sein''m Herz verborgen ist?<br/>Wie sehr Er wünscht, dass du Ihm nahst<br/>Und dich öffnest --<br/>Lass Ihn in jeden Teil hinein!<br/>Was Ihm am Herz''n liegt, Er dir zeigt.<br/>Was war die Freude, die vor Ihm lag?<br/>',NULL,195562,1);
INSERT INTO stanza VALUES('G2197','chorus','Für die Gemeinde -- Braut des Herrn --<br/>Für die Gemeinde starb Er gern.<br/>Sie ist es, die Sein Herz beglückt,<br/>Sein Gegenüber -- Sein Meisterstück.<br/>',NULL,195563,2);
INSERT INTO stanza VALUES('G2197','2','Er machte uns zu einem Teil<br/>Von Seinem Plan, Sein''m Kunstwerk, weil<br/>Er jemand brauchte, der Sein Herz<br/>Zufriedenstellt.<br/>Der unerforschliche Reichtum<br/>Soll werden uns zum Eigentum!<br/>Welch Weisheit, mannigfaltig ausgedrückt!<br/>',NULL,195564,3);
INSERT INTO stanza VALUES('G2197','3','Je mehr wir all''s, was Er ist, sehn<br/>Und schätzen, können wir verstehen,<br/>Was die Empfindung Seines Herzens<br/>Für uns ist.<br/>Welch große Liebe war der Grund.<br/>Er kam zu uns trotz unsrer Schuld.<br/>Warum hat Er all''s, was Er hat, verkauft?<br/>',NULL,195565,4);
INSERT INTO stanza VALUES('G2198','1','Jesus, der liebliche Hirte,<br/>Führte uns aus dem Pferch raus,<br/>Auf Seine saftige Weide;<br/>Hier sind wir endlich zu Haus!<br/>',NULL,195566,1);
INSERT INTO stanza VALUES('G2198','chorus','In der Gemeinde<br/>Schmecken wir reichen Genuss!<br/>Hier wohnen wir in der Einheit,<br/>Sodass Gott uns segnen muss.<br/>',NULL,195567,2);
INSERT INTO stanza VALUES('G2198','2','Wir warn zerstreut und zerspalten,<br/>Unterernährt, ohne Mut;<br/>Ins gute Land führte Gott uns,<br/>In unsren Geist, o wie gut!<br/>',NULL,195568,3);
INSERT INTO stanza VALUES('G2198','3','Jesus Selbst ist unsre Weide,<br/>Er ist die Speise, die nährt;<br/>Wenn Er die Herde versammelt,<br/>Ihn jedes Schaf reich erfährt.<br/>',NULL,195569,4);
INSERT INTO stanza VALUES('G2198','4','Bleiben wir auf dem Gebirge,<br/>Wo frischer Tau uns umhüllt,<br/>Löschen den Durst an der Quelle,<br/>Wasser des Lebens uns füllt.<br/>',NULL,195570,5);
INSERT INTO stanza VALUES('G2198','5','Wir ruhn und freun uns in Christus,<br/>Hunger und Furcht gibt es nicht;<br/>Sicher sind hier alle Schafe,<br/>Schauen in Sein Angesicht.<br/>',NULL,195571,6);
INSERT INTO stanza VALUES('G2199','1','Zum Gemeindeleben-Garten brachte Gott uns souverän!<br/>Um den Christus zu erfahrn, der hier gedeiht!<br/>Hier die Heiligen, ganz einmütig, genießen reich den Herrn;<br/>Er ist neu und frisch und voller Lieblichkeit.<br/>',NULL,195572,1);
INSERT INTO stanza VALUES('G2199','chorus','Ich bin glücklich hier an diesem Ort,<br/>Wachse in der Gnade immerfort!<br/>Nichts ist schöner, als zu essen froh vom Baum des Lebens hier,<br/>Und das frische Leben trinken mundet mir.<br/>',NULL,195573,2);
INSERT INTO stanza VALUES('G2199','2','Keine Schule noch Fabrik noch Kathedrale sehen wir,<br/>Doch den Garten, wo der Herr nun pflanzt und sät;<br/>Darin setzte Er uns korp''rativ, Sein Garten sind wir hier,<br/>Wo Er uns zum Wachsen bringt von früh bis spät.<br/>',NULL,195574,3);
INSERT INTO stanza VALUES('G2199','3','Im Gemeindeleben-Garten wächst viel Frucht an einem Baum,<br/>Voller Leben, frei verfügbar jederzeit.<br/>Sei so einfach, nicht verhärtet, lass die Meinung -- iss vom Baum!<br/>Lasst uns gerne schmecken Jesu Lieblichkeit!<br/>',NULL,195575,4);
INSERT INTO stanza VALUES('G2199','4','Nebst dem Baum gibt''s auch das Wasser,<br/>Gott in Christus fließt zu uns,<br/>Alle Trockenheit und Streit beendet Er;<br/>Halleluja! Denn im Garten fließt der Herr im Geist zu uns,<br/>Und so wachsen wir im Leben immer mehr.<br/>',NULL,195576,5);
INSERT INTO stanza VALUES('G2199','5','Bist du dankbar und zufrieden, dass dich Christus trug hierhin,<br/>Wo Sein Reichtum und die Süße endlos fließt?<br/>Sei so glücklich, voller Freude und im Geist froh feste Ihn!<br/>Dann bringt Gottes Garten Frucht, die Er genießt.<br/>',NULL,195577,6);
INSERT INTO stanza VALUES('G2200','1','Gedenk, wie David schwur:<br/>„Ich will nicht in mein Haus gehn,<br/>Zu ruhen liegt mir fern,<br/>Noch Schlaf die Augen sehen;<br/>Ich suche einen Ort für Dich,<br/>Ja, einen Ort für Dich."<br/>Gott ist allein, will ein Daheim,<br/>Für Ihn und uns soll''s sein.<br/>',NULL,195578,1);
INSERT INTO stanza VALUES('G2200','2','Wie blind warn wir, o Herr!<br/>Nur mit uns allein beschäftigt,<br/>Doch Gottes Haus liegt wüst --<br/>Brich durch und wend uns ständig!<br/>Wir gehn auf das Gebirge dort,<br/>Holn Holz und baun das Haus;<br/>Wir sagen nicht: „Nicht meine Pflicht."<br/>Kommt, lasst uns heute baun!<br/>',NULL,195579,2);
INSERT INTO stanza VALUES('G2200','3','Entgegen dieser Zeit<br/>Erwecke für Dein Haus, Herr,<br/>So wie zu Davids Zeit<br/>Ein''n Überrest für Dich, Herr,<br/>Der baut und wirkt in Deinem Haus!<br/>Wie segensreich ist dies!<br/>Dein Herzenswunsch ist unser Wunsch --<br/>Wir kommen, Herr, und baun.<br/>',NULL,195580,3);
INSERT INTO stanza VALUES('G2200','4','In jenen, die Du rufst,<br/>Erweck die Last, zu geben<br/>Sich selbst für diesen Bau<br/>Und nur für ihn zu leben!<br/>Die Hadespforten machtlos sind,<br/>Wenn die Gemeind gebaut!<br/>Knapp ist die Zeit, wer ist bereit?<br/>Herr, bau, o bau in uns!<br/>(Die letzten vier Zeilen wiederholen.)<br/>',NULL,195581,4);
INSERT INTO stanza VALUES('G2201','1','Dort in Babylon, in Gefangenschaft,<br/>Ja, der Herr hat unsren Geist erweckt!<br/>Uneins und zerstreut, blind und ohne Kraft,<br/>Ja, der Herr hat unsren Geist erweckt!<br/>',NULL,195582,1);
INSERT INTO stanza VALUES('G2201','chorus','Erweckt! Erweckt!<br/>Ja, der Herr hat unsren Geist erweckt!<br/>Erweckt! Erweckt!<br/>Ja, der Herr hat unsren Geist erweckt!<br/>',NULL,195583,2);
INSERT INTO stanza VALUES('G2201','2','Raus aus Babylon, voller Sekten bunt,<br/>Aus der Spaltung, stehn wir alle auf.<br/>Babylon ist nicht unser rechter Grund,<br/>Aus der Spaltung stehn wir alle auf.<br/>',NULL,195584,3);
INSERT INTO stanza VALUES('G2201','chorus','Steht auf! Steht auf!<br/>Aus der Spaltung stehn wir alle auf.<br/>Steht auf! Steht auf!<br/>Aus der Spaltung stehn wir alle auf.<br/>',NULL,195585,4);
INSERT INTO stanza VALUES('G2201','3','Nach Jerusalem, vom Gefangensein,<br/>Gott ist mit uns. Ziehn wir alle hoch!<br/>Einheit gibt es an diesem Ort allein,<br/>Gott ist mit uns. Ziehn wir alle hoch!<br/>',NULL,195586,5);
INSERT INTO stanza VALUES('G2201','chorus','Zieht hoch! Zieht hoch!<br/>Gott ist mit uns. Ziehn wir alle hoch!<br/>Zieht hoch! Zieht hoch!<br/>Gott ist mit uns. Ziehn wir alle hoch!<br/>',NULL,195587,6);
INSERT INTO stanza VALUES('G2201','4','Schalen christusvoll, Schüsseln geisterfüllt<br/>All des Herrn Gefäße bringt nun hoch!<br/>Bringt sie zur Gemeind, Gott gefällt es wohl --<br/>All des Herrn Gefäße bringt nun hoch!<br/>',NULL,195588,7);
INSERT INTO stanza VALUES('G2201','chorus','Bringt hoch! Bringt hoch!<br/>All des Herrn Gefäße bringt nun hoch!<br/>Bringt hoch! Bringt hoch!<br/>All des Herrn Gefäße bringt nun hoch!<br/>',NULL,195589,8);
INSERT INTO stanza VALUES('G2201','5','In Jerusalem, auserwähltem Ort,<br/>Baut den Tempel unsres Herrn jetzt auf!<br/>Alle einmütig dient zusammen dort,<br/>Baut den Tempel unsres Herrn jetzt auf!<br/>',NULL,195590,9);
INSERT INTO stanza VALUES('G2201','chorus','Baut auf! Baut auf!<br/>Baut den Tempel unsres Herrn jetzt auf!<br/>Baut auf! Baut auf!<br/>Baut den Tempel unsres Herrn jetzt auf!<br/>',NULL,195591,10);
INSERT INTO stanza VALUES('G2202','1','Liebster Herr, Du rufst uns her<br/>Und öffnest uns Dein Herz.<br/>Freudig, Herr, hör ich den Ruf,<br/>Betret die Arche jetzt.<br/>Rettest uns von Tag zu Tag,<br/>O Herr, das ist Dein Weg!<br/>In Dir sinken wir nicht, Herr,<br/>Trotz diesem bösen Zeitalter.<br/>',NULL,195592,1);
INSERT INTO stanza VALUES('G2202','chorus','Danke, Herr, vor Dir finden wir Gnad<br/>Und unser Herz wir öffnen Dir,<br/>Ob unsre Freunde es verstehen oder nicht.<br/>Jesus Herr, wir lieben Dich.<br/>',NULL,195593,2);
INSERT INTO stanza VALUES('G2202','2','Hab''n Geschmack an dieser Welt<br/>Und an ihr haben teil.<br/>Wenn, o Herr, wir wüssten bloß,<br/>Wie wir Dein Herz beschwern,<br/>Kehrten wir uns um zu Dir<br/>Mit bußfertigem Herz'',<br/>Gäben uns, mit Dir zu sein<br/>In Deiner Arche, lieber Herr.<br/>',NULL,195594,3);
INSERT INTO stanza VALUES('G2202','3','In Dir sind wir sicher, Herr,<br/>Wenn Todeswasser fließt.<br/>Auf dem Meeresgrund dort liegt<br/>Das, was ich einst geliebt.<br/>Halt uns für Dich offen, lass<br/>Das Ziel uns nicht verfehln!<br/>Preist den Herrn! In der Gemeinde<br/>Sind wir in der Arche jetzt.<br/>',NULL,195595,4);
INSERT INTO stanza VALUES('G2203','1','Gott hat ein''n Traum,<br/>Er hat eine Sehnsucht.<br/>Gott hat ein''n Traum<br/>Und wir sind Teil davon.<br/>Gott hat ein''n Traum,<br/>Wir können mit Ihm eins sein.<br/>Gott hat ein''n Traum, erfüllt in dir und mir.<br/>',NULL,195596,1);
INSERT INTO stanza VALUES('G2203','chorus','Gott, du und ich werden ein Wohnort sein.<br/>Gott im Mensch''n, der Mensch in Gott: welch Einheit dies!<br/>Jetzt ist''s mein Traum, Leben und meine Vision.<br/>Gott hat ein''n Traum, erfüllt in dir und mir.<br/>',NULL,195597,2);
INSERT INTO stanza VALUES('G2204','1','Wir ruhn in Dir, Du unser Schild und Schützer,<br/>Dem Feind entgegen nicht alleine stehn,<br/>In Deiner Kraft, Du unser Unterstützer,<br/>Ruhn wir in Dir, in Deinem Namen gehn.<br/>In Deiner Kraft, Du unser Unterstützer,<br/>Ruhn wir in Dir, in Deinem Namen gehn.<br/>',NULL,195598,1);
INSERT INTO stanza VALUES('G2204','2','In Deinem Namen, Herzog unsres Heiles,<br/>Ja, Deinem Namen, der sich uns verschrieb,<br/>Gerechtigkeit und unser fester Pfeiler,<br/>Der Fürst der Herrlichkeit und Herr der Lieb.<br/>Gerechtigkeit und unser fester Pfeiler,<br/>Der Fürst der Herrlichkeit und Herr der Lieb.<br/>',NULL,195599,2);
INSERT INTO stanza VALUES('G2204','3','Wir gehn im Glauben, unsre Schwachheit fühlen,<br/>In Gnade jeden Tag mehr müssen stehn,<br/>Doch klingt ein Siegeslied aus unseren Herzen,<br/>Wir ruhn in Dir, in Deinem Namen gehn.<br/>Doch klingt ein Siegeslied aus unseren Herzen,<br/>Wir ruhn in Dir, in Deinem Namen gehn.<br/>',NULL,195600,3);
INSERT INTO stanza VALUES('G2204','4','Wir ruhn in Dir, Du unser Schild und Schützer,<br/>Dein ist die Schlacht und Dein das Lob wird sein,<br/>Und im Reich Deines Glanzes dann als Sieger<br/>Ruhn wir in Dir auf ewig und allein.<br/>Und im Reich Deines Glanzes dann als Sieger<br/>Ruhn wir in Dir auf ewig und allein.<br/>',NULL,195601,4);
INSERT INTO stanza VALUES('G2205','1','Kommt, sprechen wir,<br/>bis das Königreich des Herrn da ist,<br/>Kommt, sprechen wir,<br/>bis das Königreich des Herrn da ist!<br/>Warum nur schweigt?<br/>Das Wort befreit!<br/>Lasst uns sprechen,<br/>bis das Königreich des Herrn da ist.<br/>',NULL,195602,1);
INSERT INTO stanza VALUES('G2205','2','Befreit das Wort! Zu Ihm kehrt es niemals leer zurück.<br/>Befreit das Wort! Zu Ihm kehrt es niemals leer zurück.<br/>Wir säen hier,<br/>Das müssen wir;<br/>Wenn wir sprechen, kehrt es zu Ihm niemals leer zurück.<br/>',NULL,195603,2);
INSERT INTO stanza VALUES('G2205','3','Verkünden wir überall das Evangelium!<br/>Verkünden wir! Auch trotz Tadel kehren niemals um!<br/>Gott tat das Sein'',<br/>Setzt euch doch ein!<br/>Wir sind Pilger hier und wenden uns doch niemals um!<br/>',NULL,195604,3);
INSERT INTO stanza VALUES('G2205','4','Verkünden wir, dann spricht Christus ihre Herzen an.<br/>Verkünden wir, dann spricht Christus ihre Herzen an.<br/>Gewinnen viel<br/>Ist unser Ziel;<br/>Wenn wir sprechen, dann bezeugt der Herr den Menschen hier.<br/>',NULL,195605,4);
INSERT INTO stanza VALUES('G2205','5','Die Ernte -- reif! Sprecht das volle Evangelium!<br/>Die Felder -- weiß! Sprecht das volle Evangelium!<br/>Bringt sie doch heim,<br/>In die Gemeind;<br/>Lasst uns ernten, sprecht das volle Evangelium!<br/>',NULL,195606,5);
INSERT INTO stanza VALUES('G2206','1','Mit Christus tot und auch im Grab!<br/>Mit dem alten Menschen schloss ich ab!<br/>Mit Christus tot und auch im Grab!<br/>Mit dem alten Menschen schloss ich ab!<br/>',NULL,195607,1);
INSERT INTO stanza VALUES('G2206','2','Nicht länger ich! Christus in mir!<br/>Ihn bezeuge ich im Glauben hier!<br/>Nicht länger ich! Christus in mir!<br/>Ihn bezeuge ich im Glauben hier!<br/>',NULL,195608,2);
INSERT INTO stanza VALUES('G2207','1','Im Geist getauft zu werden,<br/>Heißt, dass wir in den Geist hineinkommen<br/>Und in Ihm verloren sind.<br/>Den Geist zu trinken,<br/>Heißt, dass wir den Geist aufnehmen<br/>Und unser Sein mit Ihm durchdrungen wird.<br/>Durch diese beiden Vorgänge<br/>Werden wir mit dem Geist vermengt sein.<br/>Im Geist getauft zu werden,<br/>Ist der Anfang der Vermengung<br/>Und ist ein für alle Mal.<br/>Den Geist heut zu trinken,<br/>Ist das Vollbringen der Vermengung<br/>Und ist fortwährend, für immer.<br/>',NULL,195609,1);
INSERT INTO stanza VALUES('G2208','1','Lobt den Herrn, Er ist erschienen<br/>Unser''m Vater Abraham!<br/>Er erscheint auch uns im Geiste<br/>Für Sein Ziel und Seinen Plan!<br/>',NULL,195610,1);
INSERT INTO stanza VALUES('G2208','chorus','Gott der Herrlichkeit, erschein uns!<br/>Heute und an jedem Tag,<br/>Herr, mit Deinem Geist durchdring uns,<br/>Bis Er uns stets leiten mag!<br/>',NULL,195611,2);
INSERT INTO stanza VALUES('G2208','2','Einst da dienten wir den Götzen<br/>In Chaldäas dunklem Land.<br/>Gott der Herrlichkeit, Du riefst uns,<br/>Rettung gabst aus Satans Hand.<br/>',NULL,195612,3);
INSERT INTO stanza VALUES('G2208','chorus','Kommt heraus, verlasst Chaldäa,<br/>Kommt herein, ins gute Land!<br/>Hier sind wir im neuen Menschen --<br/>Christus ist''s und die Gemeind.<br/>',NULL,195613,4);
INSERT INTO stanza VALUES('G2208','3','Mit dem Ruf kommt die Verheißung:<br/>Lebe heut im Königreich!<br/>Das ist Antrieb uns und Stärke.<br/>Aller Mangel vor uns weicht.<br/>',NULL,195614,5);
INSERT INTO stanza VALUES('G2208','chorus','Jeden Fluss wir überqueren ---<br/>Herr, Dein Rufen sichtbar wird,<br/>Bis Dein Königreich und Ausdruck<br/>Sind gekommen auf der Erd.<br/>',NULL,195615,6);
INSERT INTO stanza VALUES('G2208','4','Dies ist unser Evangelium:<br/>Lass Chaldäa hinter Dir!<br/>Diese Welt ist so gefallen.<br/>Auserwählt für Gott sind wir.<br/>',NULL,195616,7);
INSERT INTO stanza VALUES('G2208','chorus','Gott der Herrlichkeit, erschein uns!<br/>Jeden Tag erfahrbar wird.<br/>Rufe uns für Deinen Aufbau,<br/>Deinen Herzenswunsch auf Erd!<br/>',NULL,195617,8);
INSERT INTO stanza VALUES('G2209','1','Mein König wird bald wiederkehrn,<br/>Den Himmel fülln mit Sich;<br/>Die Schöpfung dann Erlösung sieht<br/>Im Licht, so königlich.<br/>Der Herr wird Seinen Plan erfülln,<br/>Sein Kommen ist nicht fern.<br/>Den Glanz des Herrn kann schwach ich sehn,<br/>Bald wird Er wiederkehrn.<br/>',NULL,195618,1);
INSERT INTO stanza VALUES('G2209','2','Nach Seiner Nähe sehn ich mich<br/>und wag nicht, faul zu sein.<br/>Beim Warten auf den großen Tag<br/>Sein Kommen nimmt mich ein.<br/>Nur eine Hoffnung habe ich:<br/>Er kommt und macht all das<br/>Zur Wirklichkeit, was ich nun glaub;<br/>Welch Freude ohne Maß!<br/>',NULL,195619,2);
INSERT INTO stanza VALUES('G2209','3','Mein Herz ist allezeit bei Ihm,<br/>Die Augen suchen Ihn<br/>Und meine Lippen sagen stets,<br/>Dass ich beim Herrn bald bin.<br/>Ja, Seine Ankunft ist schon nah,<br/>Sein Kommen ist für mich.<br/>Was Er verheißt, bleibt ewig fest,<br/>Wird bald erfüllen sich.<br/>',NULL,195620,3);
INSERT INTO stanza VALUES('G2209','4','An Deinem Wort, mein Retter, ist<br/>Kein Zweifel mehr in mir;<br/>Mit ihm, ermutigt Tag für Tag,<br/>Nun lauf ich, treu bin Dir.<br/>Bald Deine Herrlichkeit erscheint,<br/>Der Feind gestürzt dann schon;<br/>Was Du verheißen hast, erfüllst,<br/>Nimmst uns auf Deinen Thron.<br/>',NULL,195621,4);
INSERT INTO stanza VALUES('G2209','5','Dein starker Arm, mein Retter-Gott,<br/>Ist Zuflucht hier für mich.<br/>Wer Dir vertraut, o Vater, den<br/>Bewahrst Du sicherlich.<br/>Die Schafe und der Hirt sind eins,<br/>So eins wie Leib und Haupt.<br/>Aus Deiner Hand reißt niemand je<br/>Das Kind, das Dir, Herr, glaubt.<br/>',NULL,195622,5);
INSERT INTO stanza VALUES('G2209','6','Nicht tausend Hände hindern mich,<br/>Zehntausend Augen nicht;<br/>Mich treibt der Dornenweg voran,<br/>Der Preis ist schon in Sicht.<br/>Steh auf, mein Geist! Steh auf mein Herz!<br/>Die Welt lass fahrn dahin!<br/>Der Herr des Lebens wird mich bald<br/>Zu Sich nach oben ziehn.<br/>',NULL,195623,6);
INSERT INTO stanza VALUES('G2209','7','Du Sonn des Heils! Du Hoffnung hier!<br/>Ich liebe Deine Strahln;<br/>Gerechter Herr! O König mein!<br/>Ich beug mich, fleh Dich an:<br/>O Herr, steig bald auf Deinen Thron,<br/>Zeig bald Dein Angesicht!<br/>Schenk allen Deine Gnade nun,<br/>Dein Königreich erricht!<br/>',NULL,195624,7);
INSERT INTO stanza VALUES('G2209','8','Die Wahrheit sollte König sein<br/>Und Freiheit Königin,<br/>Doch Falschheit, völlig zügellos,<br/>Regiert die Welt weithin.<br/>Wir flehen: Wahrheit, komm doch schnell,<br/>Dein Himmelslicht verbreit,<br/>Zertritt den Feind, die Söhne lass<br/>Bei Dir sein allezeit!<br/>',NULL,195625,8);
INSERT INTO stanza VALUES('G2210','1','Denn so wie vom Osten der Blitz ausgeht<br/>und zum Westen hin scheint,<br/>Denn so wie vom Osten der Blitz ausgeht<br/>und zum Westen hin scheint,<br/>So wird das Kommen des Menschensohns sein.<br/>Wie vom Osten der Blitz ausgeht.<br/>',NULL,195626,1);
INSERT INTO stanza VALUES('G2210','2','Komm, Herr Jesus!<br/>Wachs in uns!<br/>Bereit uns auf Dein Kommen vor!<br/>Gewinn unser Herz,<br/>Deine Braut!<br/>Wir wolln Dich zurückbringn, Herr.<br/>',NULL,195627,2);
INSERT INTO stanza VALUES('G2210','SoundCloud Link','https://soundcloud.com/liederstroeme/denn-so-wie-vom-osten',NULL,195628,3);
INSERT INTO stanza VALUES('G2211','1','Der Pfad der Gerechten ist wie das Morgenlicht,<br/>Es scheint heller und heller bis zum volln Tag.<br/>Die Gerechten erstrahlen im Königreich<br/>Ihres Vaters wie die Sonne.<br/>',NULL,195629,1);
INSERT INTO stanza VALUES('G2211','2','Herr, wir lieben Dich und Dein Erscheinen!<br/>Wir wolln, dass Du wiederkommst.<br/>Herr, nimm in uns zu für Dein Kommen,<br/>Bis der Morgenstern in unserm Herz'' aufgeht!<br/>',NULL,195630,2);
INSERT INTO stanza VALUES('G2212','1','Voller Öl ist die Lampe -- wir brennen!<br/>Unsre Lampe brennt hell und weit!<br/>Herr, zum Geist hilf uns stets uns zu wenden,<br/>Uns zum Geist zu wenden allezeit!<br/>',NULL,195631,1);
INSERT INTO stanza VALUES('G2212','chorus','O Herr! Amen! Halleluja!<br/>Ja, wir brennen, brennen hell und weit!<br/>O Herr! Amen! Halleluja!<br/>Wenden, wenden allezeit!<br/>',NULL,195632,2);
INSERT INTO stanza VALUES('G2212','2','Doch wir brauchen in unsren Gefäßen<br/>Für Dein Kommen noch Öl-Vorrat;<br/>Und so füllen wir unsre Gefäße,<br/>Dass die Lampe allezeit Licht hat.<br/>',NULL,195633,3);
INSERT INTO stanza VALUES('G2212','chorus','O Herr, füll uns! O Herr, füll uns!<br/>Jeden Augenblick, zu jeder Zeit!<br/>O Herr, füll uns! O Herr, füll uns!<br/>Füll uns mit der Wirklichkeit!<br/>',NULL,195634,4);
INSERT INTO stanza VALUES('G2212','3','Wir wolln brennen, bis Christus zurückkommt,<br/>Brennen stets bis zu jenem Tag.<br/>Wenn wir feiern mit Ihm dann die Hochzeit,<br/>Unsre Lampe hell zu strahln vermag.<br/>',NULL,195635,5);
INSERT INTO stanza VALUES('G2212','chorus','Komm, Herr Jesus! Komm, Herr Jesus!<br/>Finde uns gefüllt und brennend hell!<br/>Komm, Herr Jesus! Komm, Herr Jesus!<br/>Freu Dich an der Braut, komm schnell!<br/>',NULL,195636,6);
INSERT INTO stanza VALUES('G2213','1','Bald, Herr, erscheinst Du hier,<br/>Vorfreude haben wir.<br/>Nah ist Dein Tag, der strahlt so hell!<br/>Du nur bist unser Herr,<br/>Dich lieben wir so sehr,<br/>Oh, liebster Bräutigam, komm schnell!<br/>',NULL,195637,1);
INSERT INTO stanza VALUES('G2213','2','Bald ist Dein Tag schon da,<br/>Dein Ruf ist schon so nah,<br/>Und in der Wolke kommst Du gleich.<br/>Oh, Stunde süß und traut,<br/>Wenn Bräutigam trifft Braut<br/>Und Liebe füllt sie ohnegleich!<br/>',NULL,195638,2);
INSERT INTO stanza VALUES('G2213','3','Schnell wird die Zeit vergehn,<br/>Bis wir Dein Antlitz sehn!<br/>Amen, Herr Jesus! Komm doch bald!<br/>Nach Dir uns sehnen wir,<br/>Ewig zu sein mit Dir,<br/>Dir unser Herz entgegenwallt.<br/>',NULL,195639,3);
INSERT INTO stanza VALUES('G2213','4','Nur noch ein Augenblick.<br/>Du, Herr, kommst schnell zurück<br/>Und Deine Braut dann forderst ein.<br/>O Halleluja!<br/>Bald sind wir Dir so nah,<br/>Und Du wirst dann zufrieden sein.<br/>',NULL,195640,4);
INSERT INTO stanza VALUES('G2214','1','Freut euch! Denn unser Bräutigam kommt<br/>Und die Zeit ist nicht mehr lang,<br/>Bis der Hochzeit wir entgegensehen<br/>Und begrüßen mit Gesang.<br/>',NULL,195641,1);
INSERT INTO stanza VALUES('G2214','chorus','Wunderbarer Tag! Oh, heller Morgen,<br/>An dem Christus wiederkehrt:<br/>Mit Gefäß gefüllt und Lampe leuchtend<br/>Nun Sein Wiederkommen ehrt!<br/>Freut euch! Denn unser Bräutigam kommt<br/>Und die Zeit ist nicht mehr lang,<br/>Bis der Hochzeit wir entgegensehen<br/>Und begrüßen mit Gesang.<br/>',NULL,195642,2);
INSERT INTO stanza VALUES('G2214','2','Oh, kauft doch jeden Augenblick aus,<br/>Auf das Kaufen gebt doch Acht,<br/>Damit auch euer Gefäß voll Öl ist,<br/>Eh es ruft um Mitternacht!<br/>',NULL,195643,3);
INSERT INTO stanza VALUES('G2214','3','Welch Freude bringt uns Vorbereitung<br/>Auf die Hochzeit mit dem Herrn!<br/>Solcher Wonne der Belohnung wegen<br/>Leiden wir gar Trübsal gern!<br/>',NULL,195644,4);
INSERT INTO stanza VALUES('G2214','4','Ja, mit Entrückung und viel Freude<br/>Unser Hochzeitstag beginnt.<br/>Dann feiern wir eintausend Jahre,<br/>Unser Herz nur darauf sinnt!<br/>',NULL,195645,5);
INSERT INTO stanza VALUES('G2215','1','Gott hat ewig einen Vorsatz<br/>Seit vergangner Ewigkeit<br/>Bis in die entfernte Zukunft<br/>Und dazwischen liegt die Zeit.<br/>Um ihn zu erfüllen, wirkt Er,<br/>In der Zeit wird er vollbracht.<br/>Wir sind in der Zeit nur Wandrer,<br/>Weil für Ewigkeit gedacht.<br/>',NULL,195646,1);
INSERT INTO stanza VALUES('G2215','2','Gott will eine Menschengruppe,<br/>Aufgebaut nach Seinem Plan,<br/>Die als Sein Gefäß vereint sind,<br/>Gehn als neuer Mensch voran.<br/>Mit Seiner Natur und Leben<br/>Es zu fülln, ist Gott gewillt,<br/>Seinen Geist vermengt mit unsrem,<br/>Ihm das Lob und Freude gilt.<br/>',NULL,195647,2);
INSERT INTO stanza VALUES('G2215','3','Gott ist Drei für Seinen Vorsatz,<br/>Führt ihn aus so wunderbar.<br/>Als der Vater, Sohn und Geist nun,<br/>Reicht Er Sich uns herrlich dar!<br/>Alle Schöpfung ist der Rahmen --<br/>Gottes Vorsatz Dienst erweist;<br/>Mit drei Teilen machte Gott uns,<br/>Leib und Seele und dem Geist.<br/>',NULL,195648,3);
INSERT INTO stanza VALUES('G2215','4','Kern und Ziel von Gottes Plan ist<br/>Unser tiefster Teil, der Geist;<br/>Wenn wir Jesus rufen, wird er<br/>Eins mit Seinem fest geschweißt!<br/>Gott erneuert uns vom Geist aus,<br/>Jeden Teil von unsrem Sein<br/>Mit Verstand, Gefühl und Willen,<br/>Unser ganzes Herz nimmt ein.<br/>',NULL,195649,4);
INSERT INTO stanza VALUES('G2215','5','Aufgebaut im Leben, sodass<br/>Liebe uns verknüpft sodann;<br/>Gott vollendet Seinen Vorsatz,<br/>Bringt zum Schluss, was Er begann.<br/>Herr, in uns nimm zu doch täglich,<br/>Baue uns nun völlig ein<br/>Ins gemeinsame Gefäß, das<br/>Ist mit Gott erfüllt allein!<br/>',NULL,195650,5);
INSERT INTO stanza VALUES('G2215','6','Die Gemeinde, die Erfüllung,<br/>Wird dann stehn in Herrlichkeit<br/>Als Vollendung Seines Planes,<br/>Schon gefasst vor Ewigkeit.<br/>Sein gemeinsames Gefäß wird<br/>Füllen Seine Herrlichkeit;<br/>Herr, Dein Ziel in uns erreiche!<br/>Dafür Stelln wir uns bereit.<br/>',NULL,195651,6);
INSERT INTO stanza VALUES('G2216','1','Gott rief uns für Seinen Vorsatz,<br/>Sein'' Ökonomie, so herrlich!<br/>Dafür ist Er jetzt vollendet,<br/>Ging für uns durch den Prozess!<br/>Als der Geist lebt Er nun in uns,<br/>Als der zugeloste Anteil,<br/>Bringt uns hin zur vollen Rettung,<br/>Macht uns ebenso, wie Er ist.<br/>',NULL,195652,1);
INSERT INTO stanza VALUES('G2216','chorus','Herr, gib uns eine leitende Vision<br/>Von Deiner ewigen Ökonomie,<br/>Und brenn in mir, bis mein Geist völlig ist angefacht!<br/>Mit einem brennenden und starken Geist<br/>Erreichen wir Dein Ziel --<br/>Neues Jerusalem, Halleluja!<br/>',NULL,195653,2);
INSERT INTO stanza VALUES('G2216','2','Jesus lebte als ein Vorbild<br/>Eines echten Gott-Mensch-Lebens.<br/>Er verleugnete Sein Selbst und<br/>War gehorsam bis zum Tod.<br/>Einst war Er der einz''ge Gott-Mensch,<br/>Doch jetzt sind es viele Körner.<br/>Heute werden wir vermengt als<br/>Sein korporativer Ausdruck.<br/>',NULL,195654,3);
INSERT INTO stanza VALUES('G2216','3','Durch Sein Auferstehungsleben<br/>Sterben wir dem Seelenleben.<br/>Im vermengten Geist verleugnen<br/>Wir das Selbst und unser Fleisch.<br/>Weil wir heute im Leib leben,<br/>Könn''n wir täglich überwinden.<br/>Streben nach dem Gipfel Zions,<br/>Warten auf des Herrn Erscheinen.<br/>',NULL,195655,4);
INSERT INTO stanza VALUES('G2216','4','Gott und Mensch führen zusammen<br/>Im vermengten Geist EIN Leben.<br/>In der organischen Einheit<br/>Wurd''n wir einverleibt mit Ihm!<br/>Dies ist die Vision der Zeiten,<br/>Sie soll uns heut ganz beherrschen,<br/>Dass der Herr Sein''n Leib gewinne,<br/>Wie die heil''ge Stadt zu scheinen!<br/>',NULL,195656,5);
INSERT INTO stanza VALUES('G2217','1','Gott''s Ökonomie ist Sein Plan, Sich Selbst auszuteiln<br/>In Sein auserwähltes, vorherbestimmtes und erlöstes Volk.<br/>Als ihr Leb''n (als ihr Leb''n), ihr Leb''nzustrom (Leb''nszustrom)<br/>Und als ihr Alles.<br/>Bringt hervor (bringt hervor), setzt zusamm''n (setzt zusamm''n)<br/>Und baut den organischen Leib Christi auf,<br/>Der im Neuen Jerusalem vollendet wird.<br/>',NULL,195657,1);
INSERT INTO stanza VALUES('G2217','2','Gottes Ökonomie ist, dass der Mensch werd genau wie Er<br/>In Leben und Natur, doch nicht in der Gottheit.<br/>Mit dem Menschen macht Er Sich eins<br/>Und den Menschen eins mit Sich.<br/>So wird Er vergrößert und erweitert in Seinem Ausdruck,<br/>Dass all Seine göttlichen Eigenschaften<br/>Nun zum Ausdruck kommen in menschlichen Tugenden.<br/>',NULL,195658,2);
INSERT INTO stanza VALUES('G2217','3','Gott''s Ökonomie und Ziel<br/>Gemäß Seinem Herzensverlangen:<br/>Sich Selbst in unser Sein hineinzubauen<br/>Und uns in Sich hineinzubauen,<br/>Um Seine Göttlichkeit mit unsrer Menschlichkeit zu vermengen<br/>Zu einer Einheit (einer Einheit) --<br/>Zum Leib Christi.<br/>Der im Neu''n Jerusalem vollendet wird.<br/>Der im Neu''n Jerusalem vollendet wird.<br/>',NULL,195659,3);
INSERT INTO stanza VALUES('G2218','1','Denn der Herr hat Zion erwählt,<br/>Es zu Seiner Wohnstätt begehrt.<br/>„Dies ist Meine Ruhe, ewiglich,<br/>Hier will Ich wohnen, Ich hab''s begehrt."<br/>Jerusalem, Jerusalem.<br/>',NULL,195660,1);
INSERT INTO stanza VALUES('G2218','2','Alle Heiligen im alten Bund<br/>Warten auf die Stadt mit festem Grund.<br/>Gott ist der Schöpfer, der Architekt.<br/>Er hat geplant seit Ewigkeit.<br/>',NULL,195661,2);
INSERT INTO stanza VALUES('G2218','chorus','Jerusalem, Jerusalem.<br/>Aber wir sind heute gekommen<br/>Zu dem Berge Zions,<br/>Zu der Stadt des lebendigen Gottes,<br/>Dem himmlischen Jerusalem.<br/>',NULL,195662,3);
INSERT INTO stanza VALUES('G2218','3','Das Jerusalem droben ist frei,<br/>Frei von Tod und Gesetz, Sklaverei.<br/>Es ist unsre Mutter, aus Gnade sind wir<br/>Söhne der Freien nach dem Geist.<br/>Jerusalem, Jerusalem.<br/>',NULL,195663,4);
INSERT INTO stanza VALUES('G2218','4','Und ich sah die heilige Stadt<br/>Von Gott kommend, vom Himmel herab.<br/>Wie eine Braut ihrem Manne geschmückt,<br/>Mit Gottes Herrlichkeit erfüllt.<br/>',NULL,195664,5);
INSERT INTO stanza VALUES('G2218','chorus','Jerusalem, Jerusalem.<br/>Siehe, Gott ist unsre ew''ge Wohnung<br/>Und Gott wohnt jetzt im Menschen.<br/>Alles ist aus Gold und aus Perlen<br/>Und aus Edelsteinen gebaut.<br/>Jerusalem, Jerusalem.<br/>',NULL,195665,6);
INSERT INTO stanza VALUES('G2218','SoundCloud Link','https://soundcloud.com/liederstroeme/track-17',NULL,195666,7);
INSERT INTO stanza VALUES('G2219','1','Ja, der Herr ist der Geist -- und so<br/>Kommt Er jetzt in dich und macht dich froh.<br/>Ja, so einfach werden wir gefüllt.<br/>Er machte es so einfach:<br/>Eins, zwei, drei --<br/>Ja, so einfach kann es sein.<br/>',NULL,195667,1);
INSERT INTO stanza VALUES('G2219','chorus','O Herr! Amen!<br/>Ja, so lässt Du Ihn herein.<br/>Halleluja! Ich hör''s so gerne:<br/>„Wer aber dem Herrn anhängt, ist ein Geist."<br/>',NULL,195668,2);
INSERT INTO stanza VALUES('G2219','2','Die lebendige Luft ist Er<br/>Und Ihn einzuatmen, ist nicht schwer --<br/>Ja, die ganze Zeit, wann immer du willst.<br/>Er machte es so einfach:<br/>O Herr! Amen!<br/>Fangen wir von vorne an!<br/>',NULL,195669,3);
INSERT INTO stanza VALUES('G2219','3','Ja, der Herr lebt in meinem Sein<br/>Und beständig schenkt der Herr mir ein.<br/>Jede Lücke füllt Er aus mit Sich.<br/>Er macht mich wirklich glücklich.<br/>Ich bin happy!<br/>Halleluja, schmeck und sieh!<br/>',NULL,195670,4);
INSERT INTO stanza VALUES('G2220','1','Da war ein Mann, Jesus genannt.<br/>Er hat vor langer Zeit gelebt.<br/>Da war ein Mann -- ich hab gehört,<br/>Er heilte die Blinden und Kranken.<br/>Er half den Witwen und Verletzten.<br/>Er vergab den übelsten Sündern.<br/>Da war ein Mann -- ich hab gehört,<br/>Sie glauben, Er sei Gott.<br/>',NULL,195671,1);
INSERT INTO stanza VALUES('G2220','chorus','Wenn das wahr ist, wenn das echt ist,<br/>Dann will ich''s sicher wissen.<br/>Wenn Du echt bist und auch Gott bist,<br/>Dann zeig mir, wer Du bist!<br/>',NULL,195672,2);
INSERT INTO stanza VALUES('G2220','2','Da war ein Mann, Jesus genannt.<br/>Er ist schon am Kreuz gestorben.<br/>Da war ein Mann -- ich hab gehört,<br/>Anscheinend ist Er auferstanden.<br/>Ich find es sehr schwer zu verstehen --<br/>Kann Gott sterben und wieder leben?<br/>Da war ein Mann -- ich hab gehört,<br/>Sie glauben, Er sei Gott.<br/>',NULL,195673,3);
INSERT INTO stanza VALUES('G2220','3','Da ist ein Mann, Jesus genannt.<br/>Wer Ihn trifft, ist ganz verändert.<br/>Da ist ein Mann -- ich hab gehört --<br/>Und oft lassen sie alles stehen,<br/>Um Ihm zu folgen und zu dienen.<br/>Warum sollten sie das tun wollen?<br/>Da ist ein Mann -- ich hab gehört,<br/>Sie glauben, Er sei Gott.<br/>',NULL,195674,4);
INSERT INTO stanza VALUES('G2220','4','Da ist ein Mann, Jesus genannt.<br/>Sie sagen, ich kann Ihn kennen.<br/>Da ist ein Mann -- ich hab gehört --<br/>Er antwortet auf meine Fragen.<br/>Gott redet mit mir -- nicht zu fassen!<br/>Dann würd ich Ihm gerne begegnen!<br/>Da ist ein Mann -- ich hab gehört,<br/>Sie glauben, Er sei Gott.<br/>',NULL,195675,5);
INSERT INTO stanza VALUES('G2220','SoundCloud Link','https://soundcloud.com/liederstroeme/da-ist-ein-mann',NULL,195676,6);
INSERT INTO stanza VALUES('G2221','1','Sündige Vergangenheit,<br/>Mein Gewissen ohne Ruh.<br/>Tief in mir fühl ich den Schmerz,<br/>Werd verdammt von meinem Schuldgefühl.<br/>',NULL,195677,1);
INSERT INTO stanza VALUES('G2221','2','O mein Leben voll Elend<br/>In der Welt voll Nichtigkeit,<br/>Als ich nach dem Glück suchte,<br/>Empfing ich bloße Leere als meinen Lohn<br/>',NULL,195678,2);
INSERT INTO stanza VALUES('G2221','3','Gott war ganz weit weg von mir,<br/>Groß und allerhöchst'' ist Er.<br/>Doch Du Selbst zogst Menschlichkeit an.<br/>Du kamst für mich,<br/>Du hingst am Kreuz,<br/>Blutetest, starbst für mich.<br/>Darum lieb ich Ihn.<br/>Darum schätz ich Ihn.<br/>Darum geb ich mein ganzes Leben Ihm.<br/>Darum lieb ich Ihn.<br/>Darum schätz ich Ihn.<br/>Darum geb ich mein ganzes Leben Ihm.<br/>',NULL,195679,3);
INSERT INTO stanza VALUES('G2222','1','Kennst du Jesu Blut? Es reinigt voller Kraft!<br/>Gottes Lamm wäscht dich rein durch Sein Blut!<br/>Glaubst du, dass die Gnade es in dir auch schafft<br/>Und dich reinigt im kostbaren Blut?<br/>',NULL,195680,1);
INSERT INTO stanza VALUES('G2222','chorus','Bist du rein durch Sein Blut,<br/>Durch das reinigende, kostbare Blut?<br/>Ja, sind Deine Kleider rein und weiß wie Schnee?<br/>Gottes Lamm wäscht dich rein durch Sein Blut!<br/>',NULL,195681,2);
INSERT INTO stanza VALUES('G2222','2','Wandelst du im Alltag mit dem Retter nun?<br/>Gottes Lamm wäscht dich rein durch Sein Blut.<br/>Willst du allezeit am Kreuz in Jesus ruhn?<br/>Gottes Lamm wäscht dich rein durch Sein Blut.<br/>',NULL,195682,3);
INSERT INTO stanza VALUES('G2222','3','Wenn der Bräutigam erscheint, ist weiß dein Kleid?<br/>Gottes Lamm wäscht dich rein durch Sein Blut.<br/>Deine Seele für Sein Kommen mach bereit,<br/>Sei gewaschen im kostbaren Blut!<br/>',NULL,195683,4);
INSERT INTO stanza VALUES('G2222','4','Die von Sünd befleckten Kleider lege ab!<br/>Gottes Lamm wäscht dich rein durch Sein Blut.<br/>Deine Seele froh im Quell des Blutes bad!<br/>Gottes Lamm wäscht dich rein durch Sein Blut.<br/>',NULL,195684,5);
INSERT INTO stanza VALUES('G2223','1','Was wäscht meine Sünde weg?<br/>Nur das Blut des Lammes, Jesu.<br/>Was nur stellt mich wieder her?<br/>Nur das Blut des Lammes, Jesu.<br/>',NULL,195685,1);
INSERT INTO stanza VALUES('G2223','chorus','Kostbar ist Jesu Blut,<br/>Schneeweiß mich wäscht -- wie gut!<br/>Kein andrer Strom dies tut,<br/>Nur das Blut des Lammes, Jesu.<br/>',NULL,195686,2);
INSERT INTO stanza VALUES('G2223','2','Was nur reinigt? Ja, ich seh --<br/>Nur das Blut des Lammes, Jesu!<br/>Gott vergibt mir, wenn ich fleh,<br/>Nur das Blut des Lammes, Jesu!<br/>',NULL,195687,3);
INSERT INTO stanza VALUES('G2223','3','Was tilgt Sündenschulden hier? --<br/>Nur das Blut des Lammes, Jesu!<br/>Nur aus Gnade, nichts aus mir --<br/>Nur das Blut des Lammes, Jesu!<br/>',NULL,195688,4);
INSERT INTO stanza VALUES('G2223','4','Was hat mich gerecht gemacht? --<br/>Nur das Blut des Lammes, Jesu!<br/>Hoffnung, Frieden mir gebracht? --<br/>Nur das Blut des Lammes, Jesu!<br/>',NULL,195689,5);
INSERT INTO stanza VALUES('G2224','1','Möchtest du frei von der Sündenlast sein?<br/>Die Kraft ist im Blut, Kraft ist im Blut.<br/>Willst du, dass Sieg über Böses zieht ein?<br/>Die heilende Kraft ist im Blut.<br/>',NULL,195690,1);
INSERT INTO stanza VALUES('G2224','chorus','Es ist Kraft, Kraft, wunderbare Kraft,<br/>In dem Blut dieses Lamms;<br/>Es ist Kraft, Kraft, wunderbare Kraft,<br/>In dem kostbaren Blut dieses Lamms.<br/>',NULL,195691,2);
INSERT INTO stanza VALUES('G2224','2','Möchtest du frei sein von Stolz und von Lust?<br/>Die Kraft ist im Blut, Kraft ist im Blut.<br/>Reinige dich doch im Golgatha-Fluss!<br/>Die heilende Kraft ist im Blut.<br/>',NULL,195692,3);
INSERT INTO stanza VALUES('G2224','3','Möchtest du weißer als Schneeflocken sein?<br/>Die Kraft ist im Blut, Kraft ist im Blut.<br/>Leben im Strom wäscht von Sündflecken rein,<br/>Die heilende Kraft ist im Blut.<br/>',NULL,195693,4);
INSERT INTO stanza VALUES('G2224','4','Möchtest du Jesus, dem Herrn, dienen mehr?<br/>Die Kraft ist im Blut, Kraft ist im Blut.<br/>Willst du Ihm leben, Ihm singen zur Ehr?<br/>Die heilende Kraft ist im Blut.<br/>',NULL,195694,5);
INSERT INTO stanza VALUES('G2225','1','Warum, mein Herr, starbst Du für mich?<br/>Dein Leben gabst, doch ich war gegen Dich.<br/>Am Kreuz nahmst Du den Platz für mich ein,<br/>Du trugst meine Strafe, ein Fluch zu sein.<br/>',NULL,195695,1);
INSERT INTO stanza VALUES('G2225','chorus','Warum starbst Du für mich?<br/>Ich war doch gegen Dich!<br/>O Herr, Du wurd''st zum Fluch für mich.<br/>Oh, welch Geheimnis dies!<br/>Mein Gott, Du starbst für mich!<br/>Du starbst für mich -- Dein Feind war ich.<br/>',NULL,195696,2);
INSERT INTO stanza VALUES('G2225','2','Niemals dacht ich, dass Du so bist:<br/>So voller Liebe, so barmherzig.<br/>Wie liebst Du nur jemanden wie mich?<br/>Du liebst mich, Herr Jesus, Dein Feind war ich.<br/>',NULL,195697,3);
INSERT INTO stanza VALUES('G2225','chorus','Warum starbst Du für mich?<br/>Ich war doch gegen Dich!<br/>O Herr, Du wurd''st zum Fluch für mich.<br/>Oh, welch Geheimnis dies!<br/>Mein Gott, Du starbst für mich!<br/>Du starbst für mich -- Dein Feind war ich.<br/>',NULL,195698,4);
INSERT INTO stanza VALUES('G2225','3','Du hast mich schon so lang geliebt<br/>Mit einer Liebe, die alles vergibt.<br/>Verfluchte Dich und spottete gar.<br/>Du hast auf mich gewartet -- wie wunderbar!<br/>',NULL,195699,5);
INSERT INTO stanza VALUES('G2225','chorus','Warum starbst Du für mich?<br/>Ich war doch gegen Dich!<br/>O Herr, Du wurd''st zum Fluch für mich.<br/>Oh, welch Geheimnis dies!<br/>Mein Gott, Du starbst für mich!<br/>Du starbst für mich -- Dein Feind war ich.<br/>',NULL,195700,6);
INSERT INTO stanza VALUES('G2225','4','Ich war ein Mensch, der Sünde war.<br/>Drum brachte ich nur Sünden hervor.<br/>Rebellisch war mein Herz gegen Dich,<br/>Doch, Herr, Dein Erbarmen berührte mich.<br/>',NULL,195701,7);
INSERT INTO stanza VALUES('G2225','chorus','Erobert hast Du mich,<br/>Ich war doch gegen Dich.<br/>Deine große Liebe zeigte sich.<br/>Nichts konnte ändern mich,<br/>Doch Gnade zeigte sich.<br/>Deine Liebe hat erobert mich!<br/>',NULL,195702,8);
INSERT INTO stanza VALUES('G2225','5','Ich wandte mich -- schon warst Du da.<br/>Fürsorglich nahmst Du Dich meiner an.<br/>Wie könnte ich noch sein gegen Dich?<br/>Deine Liebe, Herr Jesus, entwaffnete mich.<br/>',NULL,195703,9);
INSERT INTO stanza VALUES('G2225','chorus','Erobert hast Du mich,<br/>Ich war doch gegen Dich.<br/>Deine große Liebe zeigte sich.<br/>Nichts konnte ändern mich,<br/>Doch Gnade zeigte sich.<br/>Deine Liebe hat erobert mich!<br/>',NULL,195704,10);
INSERT INTO stanza VALUES('G2226','1','Gott ist Liebe! Er sandte Seinen Sohn.<br/>Der Mensch ins Verderben gefallen war,<br/>Doch Du sandtest Deinen Sohn.<br/>Seine Güte und Liebe erweist Gott uns,<br/>Dass, als wir noch Sünder waren,<br/>Christus für uns starb.<br/>',NULL,195705,1);
INSERT INTO stanza VALUES('G2226','chorus','Gott Ihn nicht verschonte,<br/>Sein''n geliebten Sohn.<br/>Vater, wir Dich preisen<br/>Für Dein''n kostbarn Sohn!<br/>',NULL,195706,2);
INSERT INTO stanza VALUES('G2226','2','Wer versteht die Liebe von unserem Gott?<br/>Von kein''m Ohr gehört, keinem Aug gesehn,<br/>Doch Herr, ich wurd erlöst!<br/>Gott ist Liebe! O Gott, Du wurdest Mensch.<br/>Um ein Fluch zu sein, ja, Du starbst für mich.<br/>Herr, Du hingst am Holz.<br/>',NULL,195707,3);
INSERT INTO stanza VALUES('G2226','chorus','Vater, Du Ihn sandtest,<br/>Deinen lieben Sohn.<br/>Er hat Sein Blut vergossen.<br/>Deine Lieb erreicht uns.<br/>',NULL,195708,4);
INSERT INTO stanza VALUES('G2226','3','So sehr liebte Gott die Welt, dass Er Seinen Sohn gab.<br/>Glaub an Ihn, geh nicht verloren,<br/>Sondern ewig Leben hab!<br/>Glaub an Ihn, geh nicht verloren,<br/>Sondern ewig Leben hab!<br/>',NULL,195709,5);
INSERT INTO stanza VALUES('G2227','1','Die Gnadenstimm erklingt;<br/>Ihr Klang den Geist durchdringt!<br/>Erfüllt ist nun die Schrift;<br/>Den Willen Gottes spricht!<br/>Erschienen ist der Herr!<br/>Das Wort verlautet Er:<br/>',NULL,195710,1);
INSERT INTO stanza VALUES('G2227','chorus','Das Jubeljahr ist da!<br/>Das Jubeljahr ist da!<br/>Das Jubeljahr ist da!<br/>Verheißen lang vorab;<br/>Der Herr verkündet hat:<br/>Das annehmbare Jahr!<br/>Errettung ganz und gar!<br/>Das Jubeljahr ist da!<br/>',NULL,195711,2);
INSERT INTO stanza VALUES('G2227','2','Herab fuhr Gottes Geist,<br/>Den Menschensohn erreicht!<br/>Den Retter hat gesalbt,<br/>Den Herold hat ernannt!<br/>Frohbotschaft Armen teilt!<br/>Gebrochne Herzen heilt!<br/>Das Jubeljahr ist da!<br/>',NULL,195712,3);
INSERT INTO stanza VALUES('G2227','3','Gefang''ne freigemacht!<br/>Die Freiheit ist entfacht!<br/>Den Blinden gibt Er Sicht!<br/>Empfangt das Augenlicht!<br/>Aus Unterdrückung bringt!<br/>Von Ketten los Ihm singt!<br/>Das Jubeljahr ist da!<br/>',NULL,195713,4);
INSERT INTO stanza VALUES('G2227','4','Verkündet laut und klar<br/>Zur Freude fern und nah!<br/>Wo Kummer sich ergießt,<br/>Wo Trauer überfließt!<br/>Die Frohbotschaft aufblüht!<br/>Erschall, o fröhlich Lied:<br/>Das Jubeljahr ist da!<br/>',NULL,195714,5);
INSERT INTO stanza VALUES('G2228','1','Der Herr gibt Freiheit jedem,<br/>Der nur an Ihn glaubt eben.<br/>Sei nicht länger versklavt!<br/>Komm jetzt zurück zu Jesus!<br/>Empfang befreiend'' Leben!<br/>Ruf Ihn an und erfahr:<br/>',NULL,195715,1);
INSERT INTO stanza VALUES('G2228','chorus','Dies ist die Zeit des Jubeljahrs!<br/>Verkünd die Freiheit nun in Ihm!<br/>Durchs ganze Land wir rufen:<br/>Die Sklaven sind zurückgebracht,<br/>Durch Ihn erlöst von Mühsal, Angst und Sünd!<br/>Dies ist die Zeit des Jubeljahrs!<br/>',NULL,195716,2);
INSERT INTO stanza VALUES('G2228','2','Hol Land und Anteil wieder!<br/>Gott Selbst ist unser Reichtum.<br/>Iss den Herrn jeden Tag!<br/>Mit Gottes Volk genieß Ihn,<br/>Find Frieden und Erfüllung!<br/>Hier verweil ewiglich!<br/>',NULL,195717,3);
INSERT INTO stanza VALUES('G2229','1','So wie ich bin, nichts bringen kann.<br/>Du lädst mich ein, mich Dir zu nahn.<br/>Dein Blut verschafft mir freie Bahn,<br/>Lamm Gottes, ja, ich komm, ich komm!<br/>',NULL,195718,1);
INSERT INTO stanza VALUES('G2229','2','So wie ich bin, noch warten? Nein!<br/>In meiner Seel kehrt Friede ein.<br/>Dein Blut wäscht mich von Flecken rein,<br/>Lamm Gottes, ja, ich komm, ich komm!<br/>',NULL,195719,2);
INSERT INTO stanza VALUES('G2229','3','So wie ich bin, Konflikt-geplagt,<br/>Probleme kreisen, Zweifel nagt,<br/>Durch Furcht und Kämpfe oft verzagt.<br/>Lamm Gottes, ja, ich komm, ich komm!<br/>',NULL,195720,3);
INSERT INTO stanza VALUES('G2229','4','So wie ich bin, so elend, blind,<br/>Doch Sicht und Heilung nun beginnt,<br/>Was ich auch brauch, in Dir nun find,<br/>Lamm Gottes, ja, ich komm, ich komm!<br/>',NULL,195721,4);
INSERT INTO stanza VALUES('G2229','5','So wie ich bin, empfängst Du mich,<br/>Vergibst, machst rein und frei für Dich.<br/>Was Du verheißt, das glaube ich,<br/>Lamm Gottes, ja, ich komm, ich komm!<br/>',NULL,195722,5);
INSERT INTO stanza VALUES('G2229','6','So wie ich bin, Du kennst mein Sein,<br/>In Liebe rissest Mauern ein<br/>Und nun gehör ich Dir allein,<br/>Lamm Gottes, ja, ich komm, ich komm!<br/>',NULL,195723,6);
INSERT INTO stanza VALUES('G2230','1','Aus meinen Ketten, Sorgen und Nacht,<br/>Jesus, ich komm! Jesus, ich komm!<br/>In Deine Freiheit, Freude und Licht,<br/>Jesus, ich komm zu Dir!<br/>In Deine Heilung -- Krankheit muss gehen!<br/>In Deinen Reichtum -- Wünsche lass stehn!<br/>Komme in Dich, die Sünden vergehn,<br/>Jesus, ich komm zu Dir!<br/>',NULL,195724,1);
INSERT INTO stanza VALUES('G2230','2','Aus dem Versagen und tiefer Nacht,<br/>Jesus, ich komm! Jesus, ich komm!<br/>In das, was Du am Kreuz hast vollbracht,<br/>Jesus, ich komm zu Dir!<br/>In Deinen Balsam -- Sorgen lass gehen!<br/>In Deine Ruh -- lass Alltags-Sturm stehn!<br/>In den Gesang -- die Klagen vergehn,<br/>Jesus, ich komm zu Dir!<br/>',NULL,195725,2);
INSERT INTO stanza VALUES('G2230','3','Aus meiner Unruh, eigenen Ehr,<br/>Jesus, ich komm! Jesus, ich komm!<br/>In Deinem Willen zu bleiben, o Herr,<br/>Jesus, ich komm zu Dir!<br/>In Deine Liebe -- Eitles lass gehen!<br/>In die Entrückung -- Schwermut lass stehn!<br/>Auf Deinen Flügeln, Herrlichkeit sehn,<br/>Jesus, ich komm zu Dir!<br/>',NULL,195726,3);
INSERT INTO stanza VALUES('G2230','4','Aus aller Angst, wenn''s Grab mich bedroht,<br/>Jesus, ich komm! Jesus, ich komm!<br/>In Deine Friedensfreude, o Gott,<br/>Jesus, ich komm zu Dir!<br/>Aus dem Verderb -- auf Dich kann ich baun,<br/>In Deine Herde hier auf den Au''n.<br/>Lass mich Dein liebes Angesicht schaun!<br/>Jesus, ich komm zu Dir!<br/>',NULL,195727,4);
INSERT INTO stanza VALUES('G2231','1','Wenn den Herrn du finden willst,<br/>Suche Ihn nicht in der Welt,<br/>Denn die Welt ist nicht der Ort, an dem Er wohnt.<br/>An dem Er wohnt, an dem Er wohnt,<br/>An dem Er wohnt, an dem Er wohnt,<br/>Denn die Welt ist nicht der Ort, an dem Er wohnt.<br/>',NULL,195728,1);
INSERT INTO stanza VALUES('G2231','2','Wenn den Herrn du finden willst,<br/>Suche Ihn nicht im Verstand!<br/>Der Verstand nur Wissen kennt, nicht schmecken kann.<br/>Nicht schmecken kann, nicht schmecken kann,<br/>Nicht schmecken kann, nicht schmecken kann.<br/>Der Verstand nur Wissen kennt, nicht schmecken kann.<br/>',NULL,195729,2);
INSERT INTO stanza VALUES('G2231','3','Wenn den Herrn du finden willst,<br/>Öffne Ihm dein ganzes Herz,<br/>Öffne Ihm dein ganzes Herz, lass Ihn hinein!<br/>Lass Ihn hinein, lass Ihn hinein,<br/>Lass Ihn hinein, lass Ihn hinein,<br/>Öffne ihm dein ganzes Herz, lass Ihn hinein!<br/>',NULL,195730,3);
INSERT INTO stanza VALUES('G2231','4','Wenn du Ihn aufnehmen willst,<br/>Rufe Seinen Namen an,<br/>Rufe Seinen Namen an und nimm Ihn auf!<br/>Ruf Ihn an, ruf Ihn an,<br/>Ruf Ihn an, ruf Ihn an,<br/>Rufe Seinen Namen an und nimm Ihn auf!<br/>',NULL,195731,4);
INSERT INTO stanza VALUES('G2232','1','Vater, Du weißt, dass ich schon weg bin.<br/>Ich hab all meinen Besitz genomm''n.<br/>Ich fand oft, dass ich etwas verpasste.<br/>Jetzt wohn ich in einem fremden Land.<br/>Doch denk ich oft an Dich, lieber Vater.<br/>Ich denk voll Liebe noch an Dein Haus.<br/>Die gute Stimmung an dem Tisch, Deine Gegenwart<br/>Ziehn immer noch mein Herz zärtlich an.<br/>',NULL,195732,1);
INSERT INTO stanza VALUES('G2232','2','Vater, weißt Du, ich hab mein Erbe<br/>vergeudet, frönt'' am Vergnügen sehr.<br/>Ich wollt ja alle irdischen Freuden.<br/>Warum fühl ich mich dann nur so leer?<br/>Doch denk ich an Dein Haus, lieber Vater.<br/>Sogar dein Knecht ist ganz fröhlich dort.<br/>Um mich herum gibt''s keinen hier, der zufrieden ist.<br/>Dein Knecht lebt jedoch im Überfluss.<br/>',NULL,195733,2);
INSERT INTO stanza VALUES('G2232','3','Vater, weißt Du, was Hungersnot ist?<br/>Hier hab ich Hunger, der nagend ist.<br/>Selbst würd ich Futter der Schweine essen --<br/>Wir alle sterben an diesem Ort.<br/>Doch warum sollt ich sowas ertragen<br/>Wenn Dein Haus so voller Reichtum ist?<br/>Sogar die Knechte haben stets so viel mehr als ich.<br/>Vater, ich werd jetzt nach Hause komm''n.<br/>',NULL,195734,3);
INSERT INTO stanza VALUES('G2232','4','Vater, Du weißt, ich komme endlich,<br/>erschöpft, beschmutzt, beschämt und verarmt.<br/>Es tut mir leid, ich hab alles verschwendet.<br/>Ich bin es nicht wert, Dein Sohn zu sein.<br/>Doch seh ich, Vater, dass Du schnell läufst.<br/>Wie hast Du mich von weit her erkannt?<br/>Warum fällst Du mir um den Hals, küsst mich liebevoll?<br/>Wie kannst Du doch so barmherzig sein?<br/>',NULL,195735,4);
INSERT INTO stanza VALUES('G2232','5','Vater, Du weißt, ich hab gesündigt,<br/>gegen den Himmel und auch vor Dir.<br/>Unerwartet hast Du mich empfangen.<br/>Es gibt gar keine Beschuldigung.<br/>„Bringt schnell das beste Gewand her", sagst Du.<br/>„Streift ihm den Ring und Sandalen an.<br/>Bringt das gemästete Kalb her, schlachtet es sofort,<br/>Und lasst uns essen und fröhlich sein,<br/>Weil mein Sohn tot war und wieder lebt.<br/>Verloren war und gefunden ist".<br/>',NULL,195736,5);
INSERT INTO stanza VALUES('G2232','SoundCloud Link','https://soundcloud.com/liederstroeme/vater-du-weisst',NULL,195737,6);
INSERT INTO stanza VALUES('G2233','1','Fels des Heils, geöffnet mir,<br/>Birg mich, ew''ger Hort, in Dir!<br/>Lass das Wasser und das Blut,<br/>Deiner Seite heil''ge Flut,<br/>Mir das Heil sein zweierfach<br/>Von der Sünde Schuld und Macht!<br/>',NULL,195738,1);
INSERT INTO stanza VALUES('G2233','2','Dem, was Dein Gesetze spricht,<br/>Kann mein Werk genügen nicht.<br/>Mag ich ringen, wie ich will,<br/>Fließen auch der Tränen viel,<br/>Tilgt das doch nicht meine Schuld.<br/>Herr, mir hilft nur Deine Huld.<br/>',NULL,195739,2);
INSERT INTO stanza VALUES('G2233','3','Da ich denn nichts bringen kann,<br/>Schmieg ich an Dein Kreuz mich an.<br/>Nackt und bloß, o kleid mich doch,<br/>Hilflos, ach, erbarm Dich noch,<br/>Unrein, Herr, flieh ich zu Dir,<br/>Wasche mich, sonst sterb ich hier!<br/>',NULL,195740,3);
INSERT INTO stanza VALUES('G2233','4','Jetzt, da ich noch leb im Licht,<br/>Wenn mein Aug im Tode bricht,<br/>Wenn durchs finstre Tal ich geh,<br/>Dann vor meinem Herren steh:<br/>Fels des Heils, geöffnet mir,<br/>Birg mich, ew''ger Hort, in Dir!<br/>',NULL,195741,4);
INSERT INTO stanza VALUES('G2234','1','Ich bin ein Mensch --<br/>Bin der Sinn des ganzen Weltenraums;<br/>Ich bin ein Mensch --<br/>Bin der Sinn des ganzen Weltenraums.<br/>Gott schuf mich so,<br/>Ich bin so froh;<br/>Ja, der Mittelpunkt und Sinn des ganzen Weltenraums.<br/>',NULL,195742,1);
INSERT INTO stanza VALUES('G2234','2','Christus in mir --<br/>Meines Lebens Sinn allein ist Er;<br/>Christus in mir --<br/>Meines Lebens Sinn allein ist Er.<br/>Er ist in mir,<br/>Mein alles hier;<br/>Wirklichkeit und meines Lebens Sinn allein ist Er.<br/>',NULL,195743,2);
INSERT INTO stanza VALUES('G2234','3','Sein Ausdruck ist --<br/>Die Gemeinde auf der Erde heut;<br/>Sein Ausdruck ist --<br/>Die Gemeinde auf der Erde heut;<br/>Jetzt Seinen Plan<br/>Erfüllen kann<br/>Dieser neue Mensch; ja, er wird herrschen über die Erd.<br/>',NULL,195744,3);
INSERT INTO stanza VALUES('G2234','4','Ja, die Gemeind --<br/>Das Familienleben, neu und echt;<br/>Ja, die Gemeind --<br/>Das Familienleben, neu und echt;<br/>Dies ist der Weg,<br/>Welch Privileg! --<br/>Christus essen baut die örtliche Gemeinde auf.<br/>',NULL,195745,4);
INSERT INTO stanza VALUES('G2234','5','Was solln wir tun?<br/>Wir gehn hin und sagen''s überall.<br/>Was solln wir tun?<br/>Wir gehn hin und sagen''s überall.<br/>Von Ihm doch sprich --<br/>Drum rief Er dich.<br/>Voller Freude gehn wir hin und sagen''s überall.<br/>',NULL,195746,5);
INSERT INTO stanza VALUES('G2235','1','Hätt ich alle Macht, doch keinen Retter,<br/>Nur ein''n Tag zu leben, wär Verdruss;<br/>Kann mein Herz denn Trost und Ruhe finden,<br/>Wenn doch alles hier vergehen muss?<br/>Hätt ich alle Macht, doch keinen Retter,<br/>Wozu soll ich lebenslang abmühn mich?<br/>Sind die irdischen Vergnügen mehr wert,<br/>Als wenn Christus mich erfüllt mit Sich?<br/>',NULL,195747,1);
INSERT INTO stanza VALUES('G2235','2','Hätt ich Wohlstand, jeder würd mich lieben,<br/>Wär mein Name allen ein Begriff,<br/>Doch wenn ohne Hoffnung, ohne Hafen,<br/>Wohin lenk ich denn im Sturm mein Schiff?<br/>Hätt ich alle Macht, doch keinen Retter,<br/>Der das Kreuz ertrug und starb für mich,<br/>Könnte mir die Welt hier Zuflucht bieten?<br/>Wenn in Angst und Leid, wohin flieh ich?<br/>',NULL,195748,2);
INSERT INTO stanza VALUES('G2235','3','Oh, wie leer ist alles ohn'' den Retter!<br/>Wie die Sündensorge nimmt dich ein!<br/>Und die Ewigkeit so trüb und dunkel,<br/>Voller Weh und Tränen wird sie sein.<br/>Was ist, wenn ich lebe ohne Retter?<br/>Wenn ich sterben muss, was steht bereit?<br/>Ohne Ihn ich dort im finstren Tal steh,<br/>Ohne Ihn allein in Ewigkeit!<br/>',NULL,195749,3);
INSERT INTO stanza VALUES('G2235','4','Welche Freud, in Jesus hab ich alles!<br/>Er ist Balsam für mein krankes Herz!<br/>Er vergibt die allergrößten Sünden,<br/>Zeigt Sein Mitgefühl in jedem Schmerz!<br/>Wenn ich Jesus habe, einzig Jesus,<br/>In der ganzen Welt nichts sonst will ich --<br/>Alles habe ich in Christus Jesus;<br/>Was ich brauch, weiß Er und sorgt für mich.<br/>',NULL,195750,4);
INSERT INTO stanza VALUES('G2236','1','Einst nach einem Brunnen suchte,<br/>Der zutiefst zufriedenstellt,<br/>Von so vielen Brunnen trank ich,<br/>Doch der Durst blieb, denn Leben fehlt''.<br/>Doch dann fand ich Jesus,<br/>Der meinen Durst nun stillt,<br/>Er ist ein tiefer Quell in mir,<br/>Wo Lebenswasser quillt.<br/>Nun trink ich Ihn!<br/>',NULL,195751,1);
INSERT INTO stanza VALUES('G2236','chorus','Jesus, Jesus ist mein Leben,<br/>Jesus ist mein Leben nun;<br/>Ich bin voll und ganz zufrieden,<br/>Jesus ist mein Leben nun.<br/>',NULL,195752,2);
INSERT INTO stanza VALUES('G2236','2','Da der Brunnen mir gemundet,<br/>Sucht'' mein Herz nach dem Ort seitdem;<br/>Die Vision am Berg erhaschte:<br/>Man sich trifft in Jerusalem.<br/>Ja, dann fand mich Jesus,<br/>Mich zur Gemeinde trug;<br/>Hier ewig Freude überfließt,<br/>Gesucht hab ich genug.<br/>Halleluja!<br/>',NULL,195753,3);
INSERT INTO stanza VALUES('G2236','chorus','Jesus, Jesus ist mein Leben,<br/>Jesus ist mein Leben nun;<br/>Ich bin voll und ganz zufrieden,<br/>Jesus ist mein Leben nun.<br/>',NULL,195754,4);
INSERT INTO stanza VALUES('G2236','3','Leerer Wandrer, lass dein Trachten --<br/>Letztlich wird alles wertlos sein;<br/>Öffne nun dein Herz im Glauben,<br/>Ruf: „Herr Jesus!" Er kommt herein!<br/>Du wirst Ihn heut finden,<br/>Ruf Seinen Namen an,<br/>So hängst du Ihm nun an im Geist --<br/>Wirst anders sein fortan.<br/>Ja, das willst du!<br/>',NULL,195755,5);
INSERT INTO stanza VALUES('G2236','chorus','Jesus, Jesus ist mein Leben,<br/>Jesus ist mein Leben nun;<br/>Ich bin voll und ganz zufrieden,<br/>Jesus ist mein Leben nun.<br/>',NULL,195756,6);
INSERT INTO stanza VALUES('G2237','1','Schmeck doch und sieh: ja, der Herr ist gut,<br/>Schmeck doch und sieh: ja, der Herr ist gut!<br/>Er ist gut für dich sowie auch für mich,<br/>Was auch immer du tust, schmeck doch und sieh!<br/>',NULL,195757,1);
INSERT INTO stanza VALUES('G2237','2','Ruf doch: „O Herr!" -- Er verändert dich,<br/>Ruf doch: „O Herr!" -- Er verändert dich;<br/>Herrliche Gnade fließt so sehr,<br/>Wenn an jedem Ort du rufst: „O Herr!"<br/>',NULL,195758,2);
INSERT INTO stanza VALUES('G2237','3','Ja, Liebe fließt in dein Herz hinein,<br/>Ja, Liebe fließt in dein Herz hinein;<br/>Ein Strom aus Gott fließt dir jetzt zu,<br/>Die wahre Liebe ja fandest du.<br/>',NULL,195759,3);
INSERT INTO stanza VALUES('G2237','4','Drum preis den Herrn für Sein Leben in dir,<br/>Ja, preis den Herrn für Sein Leben in dir;<br/>Etwas von Christus goss Er gern<br/>Jetzt in dein Leben, drum preis den Herrn!<br/>',NULL,195760,4);
INSERT INTO stanza VALUES('G2238','1','Welch ein Jubeltag,<br/>Seit dem ich nicht zurück mehr mag!<br/>Seit Jesus mich heraus aus der dunklen Nacht<br/>Ins Reich des Lichtes hat gebracht.<br/>',NULL,195761,1);
INSERT INTO stanza VALUES('G2238','2','Neu mein Leben jetzt,<br/>Denn Er hat mich in Seins versetzt;<br/>Mich locken keine irdischen Träume mehr,<br/>Mein wahres Leben ist der Herr.<br/>',NULL,195762,2);
INSERT INTO stanza VALUES('G2238','3','Wenn ich offen bin,<br/>Erfüllt Er mich mit Leben drin;<br/>Sein Leben wird zu meinem in Wirklichkeit,<br/>Er wohnt in mir für allezeit!<br/>',NULL,195763,3);
INSERT INTO stanza VALUES('G2238','4','Herr, ich lieb Dich sehr,<br/>Nimm Du mein Herz ein immer mehr;<br/>Du bist mein Leben jetzt und ewiglich,<br/>Du bist der Einzige für mich.<br/>',NULL,195764,4);
INSERT INTO stanza VALUES('G2239','1','Man ein Evangelium hört:<br/>Ach, glaube nur, gerettet wirst und dann<br/>Kannst du in den Himmel gehn und Perlen sehn<br/>Und goldne Straßen begehn.<br/>Solche Worte -- helfen nicht,<br/>All die Nichtigkeit -- tief in mir zu verstehn.<br/>',NULL,195765,1);
INSERT INTO stanza VALUES('G2239','2','Doch das Evangelium ist:<br/>Dass Gott, dreieins, die Menschlichkeit anzog,<br/>Als der Geist erreicht Er mich,<br/>Um tief in mir die Wirklichkeit zu sein.<br/>Tiefe Liebe -- gute Nachricht,<br/>Die nie vergeht -- wird auf ewig erzählt.<br/>',NULL,195766,2);
INSERT INTO stanza VALUES('G2239','3','Neunundneunzig waren da,<br/>Doch das verlorne Schaf hast Du gesucht.<br/>Mich auf Deine Schultern hobst,<br/>Dort trugst Du mich in Deiner großen Liebe.<br/>Welche Freude -- Du fandst mich,<br/>Das verlorne Schaf -- Du gabst alles und fandst mich.<br/>',NULL,195767,3);
INSERT INTO stanza VALUES('G2239','4','Du erforschst mein tiefstes Sein,<br/>Mit einer Lampe suchst mein inneres Herz,<br/>Heiligst mich und scheinst in mir,<br/>Stellst Sünde bloß, zur Buße leitest mich.<br/>Jetzt seh ich -- Herr, Dein Blut,<br/>Das am Kreuz vergossen -- es besprengt und reinigt mich.<br/>',NULL,195768,4);
INSERT INTO stanza VALUES('G2239','5','Voller Eifer wartest Du,<br/>Bis ich die kleinste Wendung zu Dir mach.<br/>War mein Leben auch dahin,<br/>Du liefst zu mir und fielst mir um den Hals,<br/>Küsstest mich -- liebevoll.<br/>Das Kalb essen wir -- „Kommt und freut euch mit mir."<br/>',NULL,195769,5);
INSERT INTO stanza VALUES('G2240','1','Einst kam der Herr an einen Brunn''n<br/>Und einer Frau dürstete sehr.<br/>Er war nicht zufriedn, bis Er<br/>Ihr das wahre Wasser so rein und klar hinterließ.<br/>',NULL,195770,1);
INSERT INTO stanza VALUES('G2240','chorus','Kommt, seht einen Mann! (Jesus!)<br/>Kommt, seht einen Mann,<br/>Der all meine Taten mir offenbart hat!<br/>Ist Er nicht der Christus? (Oh doch!)<br/>Ist Er nicht der Christus?<br/>Er füllt mich für immer und ewig! Amen. (Amen. Amen. Amen.)<br/>',NULL,195771,2);
INSERT INTO stanza VALUES('G2240','2','Die Worte des Lebens sprach Er,<br/>Die meinen Durst weckten alsbald.<br/>Lebendiges Wasser gab Er,<br/>Dass jeder, der davon trinkt, nimmermehr dürsten wird.<br/>',NULL,195772,3);
INSERT INTO stanza VALUES('G2240','3','Das Wasser des Lebens ist mein!<br/>Ich trinke und steig in die Höh.<br/>Ich preise Ihn an jedem Ort,<br/>Weil ich Christus überall ab jetzt verkündige.<br/>',NULL,195773,4);
INSERT INTO stanza VALUES('G2241','1','Wohin du auch gehst, will ich gehn,<br/>Wo immer du wohnst, will ich wohn''n.<br/>Dein Volk sei mein Volk<br/>Und ebenso Dein Gott, der sei mein Gott. (Wiederholen)<br/>',NULL,195774,1);
INSERT INTO stanza VALUES('G2241','2','Wo immer du stirbst, sterb ich auch,<br/>Will dort begraben werden.<br/>Der Herr tue mir dies und gar noch mehr,<br/>Der Tod allein soll scheiden mich von dir.<br/>Der Herr tue mir dies und gar noch mehr,<br/>Der Tod allein soll scheiden mich von dir.<br/>',NULL,195775,2);
INSERT INTO stanza VALUES('G2242','1','Der Herr ist mir Licht und Errettung,<br/>Wen sollt fürchten ich?<br/>Der Herr ist meines Lebens Kraft,<br/>Vor wem sollte mir denn graun?<br/>',NULL,195776,1);
INSERT INTO stanza VALUES('G2242','2','Eines hab ich erbeten vom Herrn,<br/>Das hätte ich gern.<br/>Dass ich im Haus des Herrn wohnen könne<br/>Alle Tage meines Lebens<br/>Zu schauen die Schönheit des Herrn<br/>Und Ihn zu suchen in Seinem Tempel.<br/>',NULL,195777,2);
INSERT INTO stanza VALUES('G2242','3','Herr, höre mich, wenn ich rufe mit meiner Stimm'',<br/>Und sei mir gnädig und erhöre mich und antworte mir.<br/>Wenn Du mir sagst: „Mein Angesicht sucht!"<br/>Dann hält Mein Herz Dir vor Dein Wort.<br/>Dein Angesicht, Herr, such ich.<br/>',NULL,195778,3);
INSERT INTO stanza VALUES('G2242','4','Harre auf den Herrn,<br/>Guten Mutes sei!<br/>Und dein Herz sei unverzagt<br/>Hoffe deshalb auf den Herrn.<br/>Hoffe deshalb auf den Herrn.<br/>',NULL,195779,4);
INSERT INTO stanza VALUES('G2243','1','Du hast meine Klag verwandelt in einen Tanz,<br/>Du nahmst mir das Sacktuch weg.<br/>Du hast meine Klag verwandelt in einen Tanz,<br/>Umgürtest mich mit Freude,<br/>Dass man Dir zu Ehren singe Lobpreis und Dank<br/>Und nicht verstumme.<br/>O Herr, mein Gott,<br/>Ich will Dir danken in Ewigkeit.<br/>',NULL,195780,1);
INSERT INTO stanza VALUES('G2244','1','Wie ein Hirsch lechzt nach frischen Wasserbächen,<br/>So lechzt meine Seele nach Dir, Gott!<br/>Meine Seele dürstet nach Gott! Nach Gott! Nach Gott!<br/>Meine Seele dürstet nach Gott! Nach Gott! Nach dem lebendigen Gott!<br/>',NULL,195781,1);
INSERT INTO stanza VALUES('G2244','SoundCloud Link','https://soundcloud.com/liederstroeme/psalm-421-2-wie-ein-hirsch-lechzt',NULL,195782,2);
INSERT INTO stanza VALUES('G2245','1','Erschaff in mir ein reines Herz, o Gott!<br/>Und erneuer in mir ein''n festen Geist!<br/>Erschaff in mir ein reines Herz, o Gott!<br/>Und erneuer in mir ein''n festen Geist!<br/>',NULL,195783,1);
INSERT INTO stanza VALUES('G2245','2','Verwirf mich nicht von Deinem Angesicht!<br/>Nimm Deinen heilig''n Geist nicht von mir!<br/>Lass mir wiederkehren die Freude Deines Heils<br/>Und stütze mich mit einem willigen Geist!<br/>',NULL,195784,2);
INSERT INTO stanza VALUES('G2246','1','Herr, ich bleib beständig doch bei Dir.<br/>Du hältst mich bei meiner rechten Hand,<br/>Du leitest mich,<br/>Leitest mich nach Deinem Ratschluss,<br/>Nimmst mich in die Herrlichkeit auf,<br/>Ja, in die Herrlichkeit auf.<br/>',NULL,195785,1);
INSERT INTO stanza VALUES('G2246','2','Wen hab ich im Himmel außer Dir?<br/>Und ich wünsche nichts auf Erden,<br/>Wenn ich nur Dich hab.<br/>Mag mir Leib und Seele schwinden,<br/>Bleibt Gott doch allezeit<br/>Meines Herzens Fels und mein Teil.<br/>',NULL,195786,2);
INSERT INTO stanza VALUES('G2247','1','Erforsch mich, Gott, und erkenne mein Herz!<br/>Prüf mich und erkenn'' meine Gedanken<br/>Und sieh, ob ein Weg der Mühsal bei mir ist,<br/>Und leite mich, und leite mich,<br/>Und leite mich auf dem ewigen Weg!<br/>',NULL,195787,1);
INSERT INTO stanza VALUES('G2247','2','Herr, Du hast mich erforscht.<br/>Herr, Du hast mich erkannt.<br/>Du kennst mein Sitzen,<br/>Du kennst mein Aufstehn,<br/>Du verstehst mein Trachten von fern,<br/>Mit allen meinen Weg''n bist Du vertraut,<br/>Mit allen meinen Weg''n bist Du vertraut.<br/>',NULL,195788,2);
INSERT INTO stanza VALUES('G2248','1','Behüte dein Herz mehr als alles, mehr als alles,<br/>was zu bewahr''n ist!<br/>Denn von ihm aus, von ihm aus, von ihm aus<br/>sind die Ausgänge des Lebens.<br/>Behüte Dein Herz mehr als alles, mehr als alles,<br/>was zu bewahrn ist!<br/>Behüte dein Herz ...<br/>',NULL,195789,1);
INSERT INTO stanza VALUES('G2248','SoundCloud Link','https://soundcloud.com/liederstroeme/spruche-423-behute-dein-herz-mehr-als-alles',NULL,195790,2);
INSERT INTO stanza VALUES('G2249','1','Ihr werdet mit Freuden Wasser schöpfen<br/>Aus den Quellen der Errettung;<br/>An jenem Tag werdet ihr sagen:<br/>Preist den Herrn!<br/>',NULL,195791,1);
INSERT INTO stanza VALUES('G2249','2','Ihr werdet mit Freuden Wasser schöpfen<br/>Aus den Quellen der Errettung;<br/>An jenem Tag werdet ihr sagen:<br/>Preist den Herrn!<br/>',NULL,195792,2);
INSERT INTO stanza VALUES('G2249','chorus','Ruft Sein''n Namen an,<br/>Tut Seine Taten kund bei den Völkern,<br/>Verkündet Seinen Namen erhaben!<br/>O juble laut, du Bewohnerin von Zion!<br/>Denn groß ist in Deiner Mitte der Heilige von Israel.<br/>',NULL,195793,3);
INSERT INTO stanza VALUES('G2250','1','Wenn ihr durstig seid,<br/>Kommt zu den Wassern!<br/>Ihr, die ihr kein Geld habt,<br/>Kommt, kauft und esst!<br/>Ja, kommt! Kauft Wein und Milch,<br/>Ohne Geld, ohne Preis! Hey!<br/>Wenn ihr durstig seid, kommt zu den Wassern!<br/>',NULL,195794,1);
INSERT INTO stanza VALUES('G2250','SoundCloud Link','https://soundcloud.com/user-633471796/wenn-ihr-durstig-seid-everyone',NULL,195795,2);
INSERT INTO stanza VALUES('G2251','1','Lasset uns suchen den Herren,<br/>Während Er nahe ist.<br/>Seinen Weg lasse der Gottlose<br/>Und während Er hört, ruft Ihn an!<br/>Auf, ihr Dürstigen alle,<br/>Zu den Wassern kommt her!<br/>Kommet und trinket die Milch und den Wein<br/>Kommet, die ihr kein Geld habt.<br/>',NULL,195796,1);
INSERT INTO stanza VALUES('G2251','chorus','Und wie ein Strom fließt der Friede<br/>Und göttliches Sein,<br/>Wenn du kommst zu den Wassern.<br/>Wenn du schmeckst Seinen Wein,<br/>Dann fließet die Liebe und völlige Freud,<br/>Immerwährendes Leben, ja für uns.<br/>',NULL,195797,2);
INSERT INTO stanza VALUES('G2251','2','Freudig werdet ihr aufstehen,<br/>In Frieden geleitet sein.<br/>Berge und Hügel in Jubel sind,<br/>Die Bäume des Feldes, sie klatschen.<br/>Statt Dornen Wachholder sprießt auf,<br/>Statt Brennnesseln Myrthe wächst auf.<br/>Und es soll sein zur Erinnrung des Herrn,<br/>Soll ewig ein Zeichen sein.<br/>',NULL,195798,3);
INSERT INTO stanza VALUES('G2252','1','Sucht den Herrn, da Er Sich finden lässt!<br/>Rufet Ihn an, da Er nahe ist!<br/>Der Gottlose lasse seinen Weg,<br/>Der Frevler sein Gedankengut<br/>Und kehre jetzt um zu dem Herrn, unserem Gott!<br/>Und Er ist so reich an Vergebung.<br/>Er wird dir reichlich Vergebung schenken --<br/>Kehr um zu dem Herrn!<br/>',NULL,195799,1);
INSERT INTO stanza VALUES('G2253','1','Wo ist das Haus, das ihr Mir baut? Und der Ort Meiner Ruh?<br/>Wo dann ist das Haus, das ihr Mir baut? Und der Ort Meiner Ruh?<br/>',NULL,195800,1);
INSERT INTO stanza VALUES('G2253','2','Der Himmel ist Mein Thron, die Erde Schemel Meiner Füße.<br/>Wo dann ist das Haus, das ihr Mir baut? Und der Ort Meiner Ruh?<br/>',NULL,195801,2);
INSERT INTO stanza VALUES('G2253','3','„Hat Meine Hand nicht alles gemacht,<br/>und alles dies ist geworden durch Mich?",<br/>so spricht Jehovah.<br/>„Aber auf die will ich schauen, die demütig sind,<br/>Zerbrochen im Geist und ehrfurchtsvoll, erzittern vor Meinem Wort."<br/>',NULL,195802,3);
INSERT INTO stanza VALUES('G2253','4','Wo dann ist das Haus, das ihr Mir baut? Und der Ort Meiner Ruh?<br/>Wo dann ist das Haus, das ihr Mir baut? Und der Ort Meiner Ruh?<br/>',NULL,195803,4);
INSERT INTO stanza VALUES('G2254','1','Ich bin ein Baum mit Wurzeln<br/>An Bächen lebendigen Wassers.<br/>Versuchungen mögen kommen,<br/>Doch sie enden immer im Sieg.<br/>Und sogar in der Wüste,<br/>Wenn es keine Hoffnung mehr gibt,<br/>Hab ich Wurzeln an Bächen des Herrn.<br/>Wenn die stechende Sonne rauskommt,<br/>Sterben meine Blätter nicht --<br/>Ich hab Wurzeln an Bächen des Herrn.<br/>',NULL,195804,1);
INSERT INTO stanza VALUES('G2255','1','Kommt alle her zu Mir - kommt zu Mir,<br/>Die ihr euch abmüht und beladen seid!<br/>Kommt alle her zu Mir - kommt,<br/>Und Ich werde euch Ruhe geben.<br/>',NULL,195805,1);
INSERT INTO stanza VALUES('G2255','chorus','O Herr, wir kommen -- kommen zu Dir.<br/>Wir sind schwer beladen, wir mühen uns ab.<br/>Du hast gesagt, dass Du uns Ruhe geben wirst.<br/>Jetzt kommen wir -- die Ruhe gib uns, o Herr!<br/>',NULL,195806,2);
INSERT INTO stanza VALUES('G2255','2','Nehmt Mein Joch auf euch! Lernt von Mir!<br/>Ich bin sanftmütig und von Herzen demütig.<br/>Ihr werdet Ruhe finden --<br/>Ruhe finden für eure Seelen.<br/>',NULL,195807,3);
INSERT INTO stanza VALUES('G2255','SoundCloud Link','https://soundcloud.com/liederstroeme/matthaeus-11-28-29-kommt-alle-her-zu-mir',NULL,195808,4);
INSERT INTO stanza VALUES('G2256','1','Denn ebenso, wie die Tage Noahs waren,<br/>So wird das Kommen des Sohnes des Menschen sein.<br/>Die Leute aßen und die Leute tranken,<br/>Heirateten, verheirateten.<br/>',NULL,195809,1);
INSERT INTO stanza VALUES('G2256','chorus','Und sie merkten nicht,<br/>Dass ihnen ein Gericht bevorstand.<br/>Und sie merkten nichts,<br/>Bis die Flut kam und alle wegnahm.<br/>',NULL,195810,2);
INSERT INTO stanza VALUES('G2256','2','Zu jener Zeit werdn zwei Männer auf dem Feld sein.<br/>Es wird von ihnen nur einer mitgenommen.<br/>Zwei Frauen werden mit der Mühle mahlen,<br/>Eine von ihnen zurückgelassen.<br/>',NULL,195811,3);
INSERT INTO stanza VALUES('G2256','chorus','Seid darum wachsam!<br/>Denn ihr wisst nicht, wann euer Herr kommt.<br/>Seid darum wachsam!<br/>Seid ihr auch bereit, weil der Herr kommt!<br/>',NULL,195812,4);
INSERT INTO stanza VALUES('G2256','3','Mach uns, o Herr, wie den Noah, völlig nüchtern!<br/>Uns möge doch dieses Zeitalter nicht gefallen.<br/>Von der Berauschung dieser Welt befrei nun!<br/>Herr, Du kommst schnell. Lass uns bereit sein!<br/>',NULL,195813,5);
INSERT INTO stanza VALUES('G2256','chorus','Lass uns überwinden!<br/>In dieser so betäubenden Zeit.<br/>Lass uns überwinden!<br/>Für Dein Erscheinen --<br/>Mach uns, Herr, bereit!<br/>',NULL,195814,6);
INSERT INTO stanza VALUES('G2256','SoundCloud Link','https://soundcloud.com/liederstroeme/matthaeus-24-37-44',NULL,195815,7);
INSERT INTO stanza VALUES('G2257','1','Ich bin das lebendige Brot,<br/>Das aus dem Himmel herabgekommen ist.<br/>Wenn jemand, wenn jemand<br/>Von diesem Brot isst,<br/>Wird er in Ewigkeit leben.<br/>',NULL,195816,1);
INSERT INTO stanza VALUES('G2257','2','Und das Brot, (und das Brot)<br/>Das ich geb (das ich)<br/>Geben werd, ist mein Fleisch,<br/>Das ich geb (das ich geb)<br/>Geben werd (gebe)<br/>Für das Leben der Welt.<br/>',NULL,195817,2);
INSERT INTO stanza VALUES('G2257','3','Ich bin das lebendige Brot,<br/>Das aus dem Himmel herabgekommen ist.<br/>Wenn jemand, wenn jemand<br/>Von diesem Brot isst,<br/>Wird er in Ewigkeit leben.<br/>',NULL,195818,3);
INSERT INTO stanza VALUES('G2258','1','Am letzten Tag nun (am letzten Tag nun)<br/>Dem großen Tag (dem großen Tag)<br/>Dem Tag des Fests (dem Tag des Fests)<br/>Dem Tag des Fests (dem Tag des Fests)<br/>(Wiederholen)<br/>Stand Jesus da (stand Jesus da)<br/>Und rief aus: (und rief aus)<br/>Wenn jemanden dürstet,<br/>Der komme zu Mir ...<br/>Wenn jemand Durst hat, (wenn jemand Durst hat)<br/>Der komme zu Mir (der komme zu Mir)<br/>Und trinke und trinke und trink''!<br/>',NULL,195819,1);
INSERT INTO stanza VALUES('G2259','1','So habt ihr nun Traurigkeit,<br/>Ich werde euch aber wiedersehen<br/>Und euer Herz wird sich freuen<br/>Und eure Freude nimmt euch niemand weg.<br/>Dies habe ich zu euch geredet, damit ihr in Mir,<br/>In Mir Frieden habt.<br/>In der Welt habt ihr Bedrängnis,<br/>Aber seid getrost,<br/>Ich habe überwunden die Welt.<br/>',NULL,195820,1);
INSERT INTO stanza VALUES('G2259','SoundCloud Link','https://soundcloud.com/liederstroeme/johannes-162233',NULL,195821,2);
INSERT INTO stanza VALUES('G2260','1','Und Ich habe ihnen Deinen Namen bekannt gemacht<br/>Und werde ihn weiterhin bekannt machen,<br/>Damit die Liebe, mit der Du mich geliebt hast --<br/>Geliebt hast, in ihnen sei und Ich in ihnen.<br/>Und Ich habe ihnen Deinen Namen bekannt gemacht<br/>Und werde ihn weiterhin bekannt machen,<br/>Damit die Liebe, mit der Du mich geliebt hast --<br/>Geliebt hast, in ihnen sei und Ich in ihnen.<br/>',NULL,195822,1);
INSERT INTO stanza VALUES('G2260','SoundCloud Link','https://soundcloud.com/liederstroeme/johannes-1726-lydiagebreselassie',NULL,195823,2);
INSERT INTO stanza VALUES('G2261','1','„Simon, Barjona,<br/>Sag Mir, liebst du Mich?"<br/>Er sagte Ihm: „Ja, Herr,<br/>Du weißt, dass ich Dich lieb.<br/>Ich lieb Dich, ich lieb Dich.<br/>Du weißt, dass ich Dich lieb."<br/>Er sagte ihm: „Weide Meine Schaf''!"<br/>',NULL,195824,1);
INSERT INTO stanza VALUES('G2262','1','Doch ihr werdet Kraft empfangen,<br/>Wenn der Heil''ge Geist auf euch herabkommt,<br/>Und ihr werdet Meine Zeugen sein --<br/>Ihr werdet Meine Zeugen sein,<br/>Sowohl in Jerusalem als auch in ganz Judäa<br/>Und Samarien und bis ans äußerste Ende der Erde.<br/>(Wiederholen)<br/>',NULL,195825,1);
INSERT INTO stanza VALUES('G2262','2','Doch wir haben Kraft empfangen,<br/>Weil der Heil''ge Geist auf uns herabkam.<br/>Heute sind wir Seine Zeugen treu --<br/>Ja, sind wir Seine Zeugen treu!<br/>Sowohl in Jerusalem als auch in ganz Judäa<br/>Und Samarien und bis ans äußerste --<br/>Bis ans äußerste End der Erd.<br/>',NULL,195826,2);
INSERT INTO stanza VALUES('G2262','SoundCloud Link','https://soundcloud.com/liederstroeme/apostelgeschichte-1-8',NULL,195827,3);
INSERT INTO stanza VALUES('G2263','1','Und indem sie Tag für Tag<br/>Beharrlich mit Einmütigkeit<br/>Im Tempel blieben<br/>Und von Haus zu Haus<br/>Das Brot brachen,<br/>Nahmen sie ihre Speise mit Jubel und<br/>Schlichtheit des Herzens zu sich.<br/>',NULL,195828,1);
INSERT INTO stanza VALUES('G2263','SoundCloud Link','https://soundcloud.com/liederstroeme/apostelgeschichte-2-46',NULL,195829,2);
INSERT INTO stanza VALUES('G2264','1','Denn wenn wir, als wir Feinde waren --<br/>Mit Gott versöhnt wurden --<br/>Durch den Tod Seines Sohnes, werden wir viel mehr --<br/>In Seinem Leben gerettet werden, nachdem wir versöhnt worden sind --<br/>In Seinem Leben gerettet werden, nachdem wir versöhnt worden sind.<br/>',NULL,195830,1);
INSERT INTO stanza VALUES('G2265','1','Darum verlieren wir nicht den Mut,<br/>Sondern wenn auch unser äußerer Mensch verfällt,<br/>So wird doch unser innerer Mensch Tag für Tag,<br/>Tag für Tag, Tag für Tag, erneuert.<br/>Denn die augenblickliche Leichtgewichtigkeit<br/>Unserer Bedrängnis bewirkt für uns<br/>auf eine immer überragendere Weise<br/>Ein ewiges Gewicht, ein ewiges Gewicht,<br/>Ein ewiges Gewicht an Herrlichkeit.<br/>',NULL,195831,1);
INSERT INTO stanza VALUES('G2265','SoundCloud Link','https://soundcloud.com/liederstroeme/2-korinther-4-16-17-darum-verlieren-wir-nicht-den-mut',NULL,195832,2);
INSERT INTO stanza VALUES('G2266','chorus','Mit Christus gekreuzigt bin<br/>Und jetzt lebe nicht mehr ich,<br/>Nein, es ist Christus, der in mir lebt.<br/>Und das Leben, das ich leb,<br/>In dem Fleisch, im Glauben leb --<br/>Glauben an den Gottessohn,<br/>Der mich liebte und Sich hingab für mich.<br/>',NULL,195833,1);
INSERT INTO stanza VALUES('G2266','1','Von nun an wandle ich im Geist<br/>Schritt für Schritt -- Tag für Tag.<br/>O Herr, ich lieb Dich.<br/>Bist der Kostbarste für mich.<br/>Wenn ich tue irgendwas,<br/>Herr, erinnere mich, dass<br/>Du in mein''m Geist bist<br/>Und die Gnade mir austeilst.<br/>',NULL,195834,2);
INSERT INTO stanza VALUES('G2266','2','Von nun an wandle ich im Geist<br/>Und marschiere hin zum Ziel.<br/>O Herr, dein Vorsatz<br/>Bedeutet alles mir.<br/>Eigenliebe leg ich ab<br/>Für die Gemeinden, Deine Braut,<br/>Für die Erfüllung<br/>Deiner Ökonomie.<br/>',NULL,195835,3);
INSERT INTO stanza VALUES('G2267','1','Er ist Herr! Er ist Herr!<br/>Er ist auferstanden<br/>Und Er ist der Herr!<br/>Jedes Knie wird sich beugen,<br/>Jede Zunge bekennen:<br/>Ja, Jesus ist der Herr!<br/>',NULL,195836,1);
INSERT INTO stanza VALUES('G2268','1','Und Er Selbst, der Gott des Friedens,<br/>Heilige euch vollständig und ganz,<br/>Und es möge unversehrt bewahrt werden<br/>Euer Geist, eure Seel, euer Leib<br/>Ohne Tadel, bei dem Kommen<br/>Unseres Herrn Jesus Christus.<br/>Treu ist Er, der euch beruft, der wird es auch tun.<br/>',NULL,195837,1);
INSERT INTO stanza VALUES('G2268','SoundCloud Link','https://soundcloud.com/liederstroeme/1-thess-523-24-und-er-selbst-der-gott-des-friedens',NULL,195838,2);
INSERT INTO stanza VALUES('G2269','1','Darum, weil wir eine so große Wolke von Zeugen haben,<br/>die uns umgibt,<br/>Lasst auch uns jede hemmende Belastung ablegen und die Sünde,<br/>die uns so leicht umstrickt,<br/>Und mit standhaftem Ausharren den vor uns liegenden Wettlauf laufen,<br/>Indem wir wegschauen und unseren Blick auf Jesus -- Jesus -- richten,<br/>Den Urheber und Vollender unseres Glaubens,<br/>der für die vor Ihm liegende<br/>Freude, die Freude, das Kreuz erduldete<br/>und die Schande verachtete und Sich zur<br/>Rechten des Thrones Gottes niedergesetzt hat -- niedergesetzt hat.<br/>Rechten des Thrones Gottes niedergesetzt hat -- niedergesetzt hat.<br/>',NULL,195839,1);
INSERT INTO stanza VALUES('G2269','SoundCloud Link','https://soundcloud.com/liederstroeme/hebraer-121-2',NULL,195840,2);
INSERT INTO stanza VALUES('G2270','chorus','Und sie haben ihn überwunden wegen des Blutes des Lammes<br/>Und wegen des Wortes ihres Zeugnisses,<br/>Und sie haben ihr Seelenleben nicht geliebt bis zum Tod.<br/>',NULL,195841,1);
INSERT INTO stanza VALUES('G2270','1','Das Blut des Lammes antwortet vor Gott<br/>Auf alle Anklagen, die der Teufel vorbringt.<br/>Wir müssen dieses Blut anwenden,<br/>Wann immer wir spüren, dass der Teufel uns verklagt.<br/>',NULL,195842,2);
INSERT INTO stanza VALUES('G2270','2','Das Wort von unsrem Zeugnis ist unser Wort,<br/>Dass Gott mit Satan schon abgerechnet hat.<br/>Wir müssen mit gesprochnen Worten<br/>Den Sieg unsres Herrn über Satan verkünden.<br/>',NULL,195843,3);
INSERT INTO stanza VALUES('G2270','SoundCloud Link','https://soundcloud.com/liederstroeme/offenbarung-12-11',NULL,195844,4);
INSERT INTO stanza VALUES('G2271','1','Er zeigte mir den Strom<br/>Des Wassers des Lebens,<br/>Klar wie Kristall,<br/>Der hervorging<br/>Aus dem Thron Gottes<br/>Und des Lammes.<br/>Und Du sollst sie tränken mit<br/>Dem Strom Deiner Freuden.<br/>',NULL,195845,1);
INSERT INTO stanza VALUES('G2271','2','Es gibt einen Fluss,<br/>Dessen Ströme erfreun<br/>Die Stadt Gottes.<br/>Wanken soll sie nicht.<br/>Gott wird ihr helfen,<br/>In ihrer Mitte sein.<br/>Und sie sollen völlig zufrieden sein<br/>Mit der Wonne Deines Hauses.<br/>',NULL,195846,2);
INSERT INTO stanza VALUES('S2000','1','El uso de este medio no tiene el propósito de reemplazar nuestro precioso himnario.<br/>',NULL,195847,1);
INSERT INTO stanza VALUES('S2000','2','Los siguientes himnos a partir del #2001 son simplemente una recopilación de himnos y cánticos. Náda más que eso. Incluye cánticos e himnos de diferentes cancioneros de varios países de habla hispana.<br/>',NULL,195848,2);
INSERT INTO stanza VALUES('S2000','3','Algunos de los himnos recopilados son traducciones provisionales de himnos originalmente publicados en otros idiomas, por lo cual, las mismas pueden estar sujetas a cambios y/o modificaciones.<br/>',NULL,195849,3);
INSERT INTO stanza VALUES('S2000','4','Que todos nos sintamos animados a disfrutar del Señor a través del canto, y que el gozo de Cristo entre todos aumente, para que seamos llenos del Espíritu, cantando con gracia en nuestros corazones al Señor. Que la palabra de Cristo, tanto cantada como hablada, habite ricamente en nosotros. Alabamos sea Él.<br/>',NULL,195850,4);
INSERT INTO stanza VALUES('S2000','5','La gracia sea con todos los santos.<br/>',NULL,195851,5);
INSERT INTO stanza VALUES('S2001','1','Qué contento aquí,<br/>Con mi Padre, sí,<br/>Perdido estuve y me encontró.<br/>Él me sonrió;<br/>Luego, me abrazó,<br/>Con Su gracia me sorprendió.<br/>',NULL,195852,1);
INSERT INTO stanza VALUES('S2001','chorus','Me perdí, pero Él me_encontró;<br/>Muerto estuve, más me revivió.<br/>Regocíjate, ven y alégrate.<br/>En la casa del Padre estoy.<br/>',NULL,195853,2);
INSERT INTO stanza VALUES('S2001','2','Mi hambre la quitó,<br/>Túnica me dio,<br/>Anillo y sandalias también.<br/>Me arropó muy bien,<br/>Él me restauró.<br/>De vuelta en la familia estoy.<br/>',NULL,195854,3);
INSERT INTO stanza VALUES('S2002','1','Dios nos salva completamente,<br/>No es la meta la redención;<br/>Por completo<br/>Su vida en mí se extiende<br/>Y llena todo mi ser.<br/>',NULL,195855,1);
INSERT INTO stanza VALUES('S2002','2','¡Cristo! Mi esperanza de<br/>Gloria ¡Qué bueno es!<br/>Y al fin seré glorificado,<br/>Dios me saturará.<br/>',NULL,195856,2);
INSERT INTO stanza VALUES('S2003','1','Quiero tocarte, Señor.<br/>Quiero contemplar Tu faz.<br/>Ven y bésame,<br/>Te necesito hoy.<br/>',NULL,195857,1);
INSERT INTO stanza VALUES('S2003','2','Déjame oír Tu voz.<br/>Me entrego a Ti Señor.<br/>Háblame en amor.<br/>Mi ser derramo a Ti .<br/>',NULL,195858,2);
INSERT INTO stanza VALUES('S2003','chorus','Nada ni nadie<br/>Me puede satisfacer,<br/>Sólo Tú.<br/>Jesús, te amo,<br/>Mi único anhelo eres Tú,<br/>Te amo, Señor.<br/>',NULL,195859,3);
INSERT INTO stanza VALUES('S2003','3','Déjame tocarte a Ti;<br/>Pues te anhelo más y más.<br/>¡Tú eres lo mejor!<br/>¡Oh, bésame Señor!<br/>',NULL,195860,4);
INSERT INTO stanza VALUES('S2003','4','Por los besos de Tu amor,<br/>Te alabo con fervor.<br/>¡Oh, dulce sabor!<br/>¡Oh, gracia sin igual!<br/>',NULL,195861,5);
INSERT INTO stanza VALUES('S2003','chorus','Nada ni nadie<br/>Me puede satisfacer,<br/>Sólo Tú.<br/>Jesús, te amo,<br/>Mi único anhelo eres Tú,<br/>Te amo, Señor.<br/>',NULL,195862,6);
INSERT INTO stanza VALUES('S2003','5','Me infunde Tu mirada,<br/>Satisface esta unión.<br/>¡Contemplándote<br/>Me llenas, mi amor!<br/>',NULL,195863,7);
INSERT INTO stanza VALUES('S2003','6','Nada puedo hacer sin Ti,<br/>Quiero en Ti permanecer<br/>Como un pámpano,<br/>Morando sólo en Ti.<br/>',NULL,195864,8);
INSERT INTO stanza VALUES('S2003','chorus','Nada ni nadie<br/>Me puede satisfacer,<br/>Sólo Tú.<br/>Préndeme en fuego,<br/>Mi único anhelo eres Tú,<br/>Te amo, Señor.<br/>',NULL,195865,9);
INSERT INTO stanza VALUES('S2003','7','Me arrepiento y vuelvo a Ti,<br/>Eres mi primer amor.<br/>Sé mi realidad,<br/>Arde en mi corazón.<br/>',NULL,195866,10);
INSERT INTO stanza VALUES('S2003','8','Me arrepiento y vuelvo a Ti,<br/>Eres mi primer amor.<br/>Sé mi realidad,<br/>Arde en mi corazón.<br/>',NULL,195867,11);
INSERT INTO stanza VALUES('S2003','chorus','Jesús precioso,<br/>Mi Amado te amo.<br/>Me abro hoy a Ti.<br/>Jesús precioso, mi Amado,<br/>Mi todo, Te amo, te amo, Jesús.<br/>',NULL,195868,12);
INSERT INTO stanza VALUES('S2003','YouTube Link','https://www.youtube.com/watch?v=QTENZzmFk34',NULL,195869,13);
INSERT INTO stanza VALUES('S2004','1','Señor, sólo te amo a Ti,<br/>Y no hay nadie como Tú.<br/>En el universo<br/>No tengo a nadie como Tú.<br/>Te amo, mi Señor.<br/>',NULL,195870,1);
INSERT INTO stanza VALUES('S2004','YouTube Link','https://www.youtube.com/watch?v=GRu-0gp-x0k',NULL,195871,2);
INSERT INTO stanza VALUES('S2005','1','Amo a Dios de corazón<br/>Y con todo mi ser;<br/>Él es Aquel a quien amo.<br/>Amo al Señor de corazón<br/>Y con todo mi ser.<br/>',NULL,195872,1);
INSERT INTO stanza VALUES('S2005','2','Te aman, Señor Jesús<br/>Todo mi ser y mi corazón.<br/>Tú eres el único<br/>En el universo, Mi Señor.<br/>',NULL,195873,2);
INSERT INTO stanza VALUES('S2005','3','Amo al Señor<br/>Y Él me ama, yo lo sé.<br/>Amo la Biblia,<br/>Cuánto me hace crecer.<br/>Amo a los santos<br/>Y a la iglesia también.<br/>Canto, invoco y alabo al Señor.<br/>[Canto, invoco y alabo al Señor]<br/>',NULL,195874,3);
INSERT INTO stanza VALUES('S2006','1','¡Oh Señor Jesús!<br/>Cuán precioso eres.<br/>Cada vez que pronuncio<br/>Tu nombre me llenas<br/>De vida y alegría,<br/>Mi provisión todo-inclusiva.<br/>Sigue salvándome<br/>Al dispensarte en mí.<br/>*****<br/>Oh Lord Jesus,<br/>I love You for You are so precious.<br/>Each time I call on Your name<br/>I get filled with Your riches.<br/>Your life and unending joy,<br/>As my all-inclusive supply.<br/>Keep saving me by dispensing Yourself into me.<br/>',NULL,195875,1);
INSERT INTO stanza VALUES('S2006','2','¡Oh Señor Jesús!<br/>Cuán dulce Tú eres.<br/>En este mundo no_hay nada<br/>No se_iguale_a Ti.<br/>Mi fe y mi potestad.<br/>Siempre mi refugio serás.<br/>Al conocerte<br/>Mi ansiedad ha de cesar.<br/>*****<br/>¡Oh, Señor Jesús!<br/>Cuán dulce Tú eres.<br/>(Jesus! Sweetest!<br/>You’re the sweetest of all)<br/>En este mundo no‿hay nada<br/>Que se‿iguale‿a Ti.<br/>(Peerless! Jesus!<br/>My incomparable One)<br/>Mi fe y mi potestad.<br/>(Power and faith)<br/>Siempre mi refugio serás.<br/>(Shelter and rest)<br/>Al conocerte mi ansiedad ha de cesar.<br/>(All my anxiety ceases the more I know You.)<br/>',NULL,195876,2);
INSERT INTO stanza VALUES('S2006','3','¡Oh Señor Jesús!<br/>La realidad eres.<br/>Ahora mismo<br/>Mi meta es Cristo ganar,<br/>Su ejército formar.<br/>Los santos al transformar,<br/>La Nueva Jerusalén<br/>El Señor nos hará.<br/>*****<br/>¡Oh, Señor Jesús!<br/>La realidad eres.<br/>(Real One! True One! All-inclusive to me)<br/>Ahora mismo mi meta<br/>Es Cristo ganar,<br/>(My goal! Right now! To experience You)<br/>Su‿ejército formar.<br/>(The stronger part)<br/>Los santos al transformar,<br/>(Transforming us)<br/>La Nueva Jerusalén<br/>El Señor nos hará.<br/>(We overcome that New Jerusalem we will be.)<br/>',NULL,195877,3);
INSERT INTO stanza VALUES('S2006','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/oh-sen-or-jesu-s-cua-n-1',NULL,195878,4);
INSERT INTO stanza VALUES('S2007','1','¿Cómo podría llegar a ser<br/>Igual que Tú, Tu novia ser?<br/>Santo y Divino eres, Señor,<br/>Mas yo humana soy.<br/>',NULL,195879,1);
INSERT INTO stanza VALUES('S2007','2','No hay manera sin Ti, Señor.<br/>De igualarte en este amor.<br/>Más me escogiste eras atrás,<br/>No cambiaría Tu plan.<br/>',NULL,195880,2);
INSERT INTO stanza VALUES('S2007','chorus','En mi corazón<br/>Este plan está:<br/>Hombre humilde vine a ser,<br/>Mi amada a cortejar.<br/>Nada detendrá,<br/>Nada cambiará,<br/>El amor que hay en Mí,<br/>Mi novia ganaré.<br/>',NULL,195881,3);
INSERT INTO stanza VALUES('S2007','3','Nadie jamás imaginó<br/>El deseo de Tu corazón:<br/>El hombre y Dios en unidad,<br/>Tu plan en la creación.<br/>',NULL,195882,4);
INSERT INTO stanza VALUES('S2007','4','Aunque el pecado me arruinó,<br/>Pues Satanás me engañó,<br/>Tu amor por mí prevaleció;<br/>Tu plan realizarás.<br/>',NULL,195883,5);
INSERT INTO stanza VALUES('S2007','chorus','En mi corazón<br/>Este plan está:<br/>Hombre humilde vine a ser,<br/>Mi amada a cortejar.<br/>Nada detendrá,<br/>Nada cambiará,<br/>El amor que hay en Mí,<br/>Mi novia ganaré.<br/>',NULL,195884,6);
INSERT INTO stanza VALUES('S2007','5','De Rey Supremo viniste a ser,<br/>Un hombre que murió por mí,<br/>A fin de ser Tu reina; así<br/>Contigo una ser<br/>',NULL,195885,7);
INSERT INTO stanza VALUES('S2007','6','Entraste en mí al resucitar:<br/>Me distes Tu divinidad.<br/>Tenemos, pues, humanidad,<br/>También divinidad.<br/>',NULL,195886,8);
INSERT INTO stanza VALUES('S2007','chorus','Me atrae Tu amor.<br/>Soy Tuya, Señor.<br/>No me pertenezco,<br/>Más Tuya soy.<br/>Me atraes en Tu amor,<br/>Cautivada estoy.<br/>Y Tu ser me cautivó:<br/>¡Besada fui por Ti!<br/>',NULL,195887,9);
INSERT INTO stanza VALUES('S2007','7','En esta dulce comunión,<br/>Íntimamente en unión.<br/>¡Cuán amoroso eres, Señor!<br/>¡Cuán dulce relación!<br/>',NULL,195888,10);
INSERT INTO stanza VALUES('S2007','8','Transforma mi ser interior,<br/>Toma mi corazón, Señor.<br/>Todo mi ser transforma,<br/>hasta Tu novia y reina ser.<br/>',NULL,195889,11);
INSERT INTO stanza VALUES('S2007','chorus','En mi corazón<br/>Este plan está:<br/>Hombre humilde vine a ser,<br/>Mi amada a cortejar.<br/>Nada detendrá,<br/>Nada cambiará,<br/>El amor que hay en Mí,<br/>Mi novia ganaré.<br/>',NULL,195890,12);
INSERT INTO stanza VALUES('S2007','chorus','Me atrae Tu amor.<br/>Soy Tuya, Señor.<br/>No me pertenezco,<br/>Más Tuya soy.<br/>Me atraes en Tu amor,<br/>Cautivada estoy.<br/>Y Tu ser me cautivó:<br/>¡Besada fui por Ti!<br/>',NULL,195891,13);
INSERT INTO stanza VALUES('S2007','YouTube Link','https://www.youtube.com/watch?v=fNfLUfgekxc',NULL,195892,14);
INSERT INTO stanza VALUES('S2008','1','Nos llama hoy a la consagración.<br/>Vivamos para con Cristo,<br/>No hay nada mejor;<br/>La corona de vida<br/>Es para aquel que es fiel,<br/>Vivamos para con Cristo,<br/>Sirviéndole sólo a Él. (x2)<br/>',NULL,195893,1);
INSERT INTO stanza VALUES('S2008','2','Su reino se avecina<br/>Con cada amanecer,<br/>El mundo está pasando<br/>Y su maldad.<br/>Escucho el llamado,<br/>Le entrego hoy mi ser,<br/>Su amor mi vida a Él constreñirá.<br/>',NULL,195894,2);
INSERT INTO stanza VALUES('S2008','3','Nos llama hoy a la consagración<br/>Vivamos para con Cristo<br/>No hay nada mejor.<br/>La corona de vida<br/>Es para aquel que es fiel<br/>Vivamos para con Cristo<br/>Sirviéndole sólo a Él.<br/>',NULL,195895,3);
INSERT INTO stanza VALUES('S2008','YouTube Link','https://www.youtube.com/watch?v=_zE1zuWabLg',NULL,195896,4);
INSERT INTO stanza VALUES('S2009','1','Jesús mi Amado,<br/>Mi galardón.<br/>Mi gran tesoro,<br/>Mi Señor, mi dulce amor.<br/>',NULL,195897,1);
INSERT INTO stanza VALUES('S2009','2','Jesús mi Amado,<br/>Tú vives en mí.<br/>Somos uno por siempre,<br/>Mezclados en unión.<br/>',NULL,195898,2);
INSERT INTO stanza VALUES('S2009','3','Jesús mi Amado,<br/>Yo te rindo mi vida,<br/>Transforma,<br/>Satura mi ser por completo.<br/>',NULL,195899,3);
INSERT INTO stanza VALUES('S2009','4','Jesús mi Amado,<br/>Cuán glorioso eres Tú.<br/>¿Cómo podría yo<br/>Dejar de amarte a Ti?<br/>',NULL,195900,4);
INSERT INTO stanza VALUES('S2009','SoundCloud Link','https://soundcloud.com/user-581404845/jesus-mi-amado-etcc-2020',NULL,195901,5);
INSERT INTO stanza VALUES('S2010','1','Déjame estar tras de Ti,<br/>Con mis lágrimas lavar Tus pies,<br/>Con mi gloria, Te amaré,<br/>Al besarlos y ungirlos con<br/>Ungüento.<br/>',NULL,195902,1);
INSERT INTO stanza VALUES('S2010','chorus','¡Te amo!<br/>¡Jesús, yo te amo!<br/>Que mi vida y todo desperdicie en Ti.<br/>Que derrame ungüento puro<br/>En Tu cabeza y en Tus pies.<br/>¡El más precioso eres!<br/>Te amo, Señor.<br/>',NULL,195903,2);
INSERT INTO stanza VALUES('S2010','2','Déjame ungir Tus pies<br/>Con ungüento de gran valor,<br/>Enjugarlos en amor,<br/>Y la casa sea llenada con fragancia.<br/>',NULL,195904,3);
INSERT INTO stanza VALUES('S2010','chorus','¡Te amo!<br/>¡Jesús, yo te amo!<br/>Que mi vida y todo desperdicie en Ti.<br/>Que derrame ungüento puro<br/>En Tu cabeza y en Tus pies.<br/>¡El más precioso eres!<br/>Te amo, Señor.<br/>',NULL,195905,4);
INSERT INTO stanza VALUES('S2010','3','Dicen que si fueras profeta,<br/>Debías saber lo que soy,<br/>Pecadora tocándote.<br/>Soy mujer que no es digna de ungirte.<br/>',NULL,195906,5);
INSERT INTO stanza VALUES('S2010','chorus','¡Pero Te amo!<br/>¡Jesús, yo te amo!<br/>Te amo más<br/>Porque me perdonaste más.<br/>Que derrame ungüento puro<br/>En Tu cabeza y en Tus pies.<br/>¡El más precioso eres!<br/>Te amo, Señor.<br/>',NULL,195907,6);
INSERT INTO stanza VALUES('S2010','4','Que mi amor, Señor, unja Tus pies,<br/>Mis cabellos los secarán;<br/>Y besar donde entrarán los clavos;<br/>Mi todo desperdicio en Ti.<br/>',NULL,195908,7);
INSERT INTO stanza VALUES('S2010','chorus','¡Te amo!<br/>¡Jesús, yo Te amo!<br/>Mi amor y gloria desperdicio en Ti.<br/>Recibe mi ungüento,<br/>Es mi todo para Ti.<br/>¡El más precioso eres!<br/>Te amo, Señor.<br/>',NULL,195909,8);
INSERT INTO stanza VALUES('S2011','1','Vivo para amarte, mi Jesús,<br/>Pues Tú eres mi mejor amor.<br/>Si yo te olvidé te pido perdón,<br/>Vuelvo a mi amor nupcial.<br/>Tú excedes lo que amo aquí,<br/>Eres bello y sin comparación.<br/>¿Quién podrá igualar el amor sin par,<br/>De mi Novio para mí?<br/>',NULL,195910,1);
INSERT INTO stanza VALUES('S2011','chorus','Hoy por fe declaro:<br/>Que en mi corazón<br/>Tú siempre el primer lugar tendrás.<br/>Que Tu ser inunde todo mi ser.<br/>Mi Jesús, mi Amor,<br/>Yo te amaré hasta el fin.<br/>',NULL,195911,2);
INSERT INTO stanza VALUES('S2011','2','Lo que quieras puedes Tú quitar,<br/>Más reemplázalo con más de Ti.<br/>¿Qué más quiero yo si te tengo a Ti?<br/>Todo en Ti precioso es.<br/>Todos buscan lo que es vanidad.<br/>Todo llega pronto a su fin.<br/>Yo te tengo a Ti, Tuyo soy, Señor,<br/>Para amarnos con fervor.<br/>',NULL,195912,3);
INSERT INTO stanza VALUES('S2011','3','Cuánto amo dedicar, Señor,<br/>Tiempo a solas para amarnos más,<br/>Para contemplar Tu gloriosa faz.<br/>¡Qué tesoro tengo en mí!<br/>En mi vida, en toda relación;<br/>En mi obra y servicio a Ti.<br/>En todo mi ser, con gozo, Señor,<br/>Tú el primer lugar tendrás.<br/>',NULL,195913,4);
INSERT INTO stanza VALUES('S2011','SoundCloud Link','https://soundcloud.com/jovenesudamerica/vivo-para-amarte-mi-jesus',NULL,195914,5);
INSERT INTO stanza VALUES('S2012','1','El Señor llama hoy<br/>Una raza de vencedores,<br/>Que le amen sólo a Él.<br/>Que le amen sólo a Él.<br/>',NULL,195915,1);
INSERT INTO stanza VALUES('S2012','2','¿Vencedor quieres ser?<br/>Pues toma a Cristo hoy,<br/>Como el primer amor.<br/>Como el primer amor.<br/>',NULL,195916,2);
INSERT INTO stanza VALUES('S2012','chorus','Cristo es nuestra porción,<br/>En Él hallamos vida.<br/>Es la fuente del disfrute,<br/>De la gracia divina.<br/>Debemos darle<br/>Preeminencia<br/>En nuestras vidas.<br/>',NULL,195917,3);
INSERT INTO stanza VALUES('S2012','YouTube Link','https://www.youtube.com/watch?v=fTVSOwHEKCQ',NULL,195918,4);
INSERT INTO stanza VALUES('S2013','1','¡Señor Jesús, Te amo!<br/>Por eso yo Te invoco;<br/>Quiere el mundo<br/>Amoldarme a su medida,<br/>Mas soy un vaso para contenerte.<br/>Me tomarán por “loco”,<br/>Pero mi amor te entrego a Ti;<br/>Que sepa yo que_en mi está este tesoro.<br/>¡Señor Jesús, te amo!<br/>',NULL,195919,1);
INSERT INTO stanza VALUES('S2013','2','¡Señor Jesús, Te amo!<br/>Por eso de Ti bebo;<br/>Tiene el mundo su vino y sus placeres,<br/>Más Tú me satisfaces plenamente.<br/>Me tomarán por loco<br/>pero más beberé de Ti.<br/>Tú_eres en mí la fuente de_agua viva.<br/>¡Señor Jesús, te amo!<br/>',NULL,195920,2);
INSERT INTO stanza VALUES('S2013','3','¡Señor Jesús, Te amo!<br/>Por eso de Ti como.<br/>Si de Ti como y Tu vida asimilo,<br/>El mundo y mi ego elimino.<br/>Me tomarán por loco,<br/>Pero más comeré de Ti:<br/>El pan de vida que bajó del cielo.<br/>¡Señor Jesús, te amo!<br/>',NULL,195921,3);
INSERT INTO stanza VALUES('S2013','SoundCloud Link','https://soundcloud.com/andrea-aguayo-110628249/senor-jesus-te-amo-m4a',NULL,195922,4);
INSERT INTO stanza VALUES('S2014','1','Ya me decidí:<br/>Yo te amo Jesús,<br/>Aparte de Ti<br/>No tengo otro anhelo.<br/>Sólo quiero vivirte a Ti.<br/>',NULL,195923,1);
INSERT INTO stanza VALUES('S2014','chorus','Oh, Te amo,<br/>Pues Tú me amas.<br/>Sólo quiero vivirte a Ti,<br/>Y bajo Tu guiar<br/>Constante y al instante estar.<br/>',NULL,195924,2);
INSERT INTO stanza VALUES('S2014','2','Yo te quiero a Ti,<br/>¡Sí!, sólo a Ti.<br/>En el mundo entero<br/>Y el universo<br/>Nada anhelo más que a Ti.<br/>',NULL,195925,3);
INSERT INTO stanza VALUES('S2014','3','Gracias mi Señor:<br/>Me predestinaste,<br/>Llamaste, salvaste<br/>Y preservaste.<br/>¡Me has traído hasta aquí!<br/>',NULL,195926,4);
INSERT INTO stanza VALUES('S2015','1','Señor Jesús,<br/>Mi vida rindo hoy a Ti.<br/>Para cumplir Tu voluntad,<br/>Por Ti, por Tu plan.<br/>',NULL,195927,1);
INSERT INTO stanza VALUES('S2015','2','Oh fuego de Dios,<br/>Ven, arde en todo mi ser.<br/>Mi todo eres Señor,<br/>Mi vida y mi Amor.<br/>',NULL,195928,2);
INSERT INTO stanza VALUES('S2015','3','Por Tu amor y compasión<br/>puedo hoy consagrarme a Ti;<br/>Pues fuiste Tú, Señor,<br/>Quien Su vida entregó por mí.<br/>',NULL,195929,3);
INSERT INTO stanza VALUES('S2015','4','¡Cuánto amor mi Señor!<br/>Me constriñe a vivir por Ti.<br/>Por siempre te amaré,<br/>Jesús, mi_Amor,<br/>Yo te amaré.<br/>',NULL,195930,4);
INSERT INTO stanza VALUES('S2015','SoundCloud Link','https://soundcloud.com/user-998120858/senor-jesus-mi-vida-rindo-hoy',NULL,195931,5);
INSERT INTO stanza VALUES('S2016','1','Guarda, Señor, hoy mi corazón,<br/>Puro y sincero, sólo para Ti.<br/>Que no se desvíe,<br/>Que Te ame a Ti,<br/>Y que Te contemple<br/>Y mire sólo a Ti.<br/>',NULL,195932,1);
INSERT INTO stanza VALUES('S2016','chorus','Tu amor me atrae<br/>A consagrarme a Ti.<br/>Me has cautivado,<br/>Te entrego todo a Ti.<br/>¡Qué privilegio,<br/>Rendir mi ser a Ti!<br/>Eres mi amor, ¡Oh, Señor!<br/>Te amo, Te amo Señor.<br/>',NULL,195933,2);
INSERT INTO stanza VALUES('S2016','2','Arde Señor en mi corazón,<br/>Que no se apague<br/>Mi fulgente amor.<br/>Que más resplandezca<br/>Mi amor por Ti,<br/>Amor tan nuevo<br/>Como el día en que Te conocí.<br/>',NULL,195934,3);
INSERT INTO stanza VALUES('S2016','3','Toma mi vida, la ofrezco a Ti.<br/>Si mil yo tuviera,<br/>Las entregaría a Ti.<br/>Nada retengo, pertenezco a Ti,<br/>Mi ser y futuro,<br/>Señor, son para Ti.<br/>',NULL,195935,4);
INSERT INTO stanza VALUES('S2016','YouTube Link','https://www.youtube.com/watch?v=vGshG-AsMvk',NULL,195936,5);
INSERT INTO stanza VALUES('S2017','1','Algunas veces,<br/>No hay lugar en mí para Ti,<br/>Más Tú me tocas,<br/>Y haces que yo vuelva a Ti.<br/>',NULL,195937,1);
INSERT INTO stanza VALUES('S2017','chorus','Recobra mi ser,<br/>Enciende mi amor por Ti.<br/>Llena, Jesús,<br/>Mi ser con Tu eterno amor.<br/>¡Hazme Tuyo hoy!<br/>',NULL,195938,2);
INSERT INTO stanza VALUES('S2017','2','¡Oh, cuánto anhelo<br/>Vaciar mi ser, llenarme de Ti!<br/>Darte mi amor,<br/>Sí, mi primer y mejor amor.<br/>',NULL,195939,3);
INSERT INTO stanza VALUES('S2017','3','Quiero amarte<br/>Con toda mi alma y corazón.<br/>A nadie tengo,<br/>Sino a Ti, Señor, sólo a Ti.<br/>',NULL,195940,4);
INSERT INTO stanza VALUES('S2017','SoundCloud Link','https://soundcloud.com/user116415537/recobra-mi-ser-w-wendy',NULL,195941,5);
INSERT INTO stanza VALUES('S2018','1','Mi corazón tiene<br/>Un canto alegre;<br/>Para el Señor es,<br/>No hay ningún otro:<br/>¡Cuánto Te amo,<br/>Señor Jesús!<br/>',NULL,195942,1);
INSERT INTO stanza VALUES('S2018','chorus','Con mi corazón<br/>Y con mi espíritu te canto.<br/>Lo que has hecho,<br/>Quién Tú eres<br/>Me está enamorando.<br/>Vuelvo a Ti, me abro a Ti,<br/>Bebo de Ti, Señor,<br/>Pues Te amo.<br/>',NULL,195943,2);
INSERT INTO stanza VALUES('S2018','2','Ellos te hirieron<br/>En Tu costado,<br/>Pero Tu novia<br/>Así has ganado.<br/>¡Cuánto Te amo,<br/>Señor Jesús!<br/>',NULL,195944,3);
INSERT INTO stanza VALUES('S2018','3','Sin Tu amor me<br/>Siento vacío.<br/>Nada en la vida<br/>Tiene sentido.<br/>¡Oh Señor Jesús,<br/>Realidad!<br/>',NULL,195945,4);
INSERT INTO stanza VALUES('S2018','4','Cristo en mí:<br/>Admirable!<br/>Agua viva<br/>De mí sale.<br/>¡Oh qué gozo da,<br/>Mi Señor!<br/>',NULL,195946,5);
INSERT INTO stanza VALUES('S2018','SoundCloud Link','https://soundcloud.com/damarisleg/mi-corazon-tiene-un-canto',NULL,195947,6);
INSERT INTO stanza VALUES('S2019','1','Cada día es un nuevo inicio,<br/>Cada día nuevo es,<br/>Es por eso que yo quiero:<br/>Amarte con mi corazón.<br/>',NULL,195948,1);
INSERT INTO stanza VALUES('S2019','chorus','Señor, hoy Te amo,<br/>No te dejaré ir,<br/>Te amo tanto a Ti.<br/>',NULL,195949,2);
INSERT INTO stanza VALUES('S2019','2','Cada día es para amarte,<br/>Para eso el día es,<br/>Es por eso que yo quiero;<br/>Darme para amarte más.<br/>',NULL,195950,3);
INSERT INTO stanza VALUES('S2019','chorus','Señor, yo te amo,<br/>Tienes que saber:<br/>¡Cuánto te amo a Ti!<br/>',NULL,195951,4);
INSERT INTO stanza VALUES('S2019','SoundCloud Link','https://soundcloud.com/recobro-c-nticos-lords-recovery-music/cada-di-a-nuevo-es-m4a',NULL,195952,5);
INSERT INTO stanza VALUES('S2020','1','Necesita Dios,<br/>Jóvenes como Samuel;<br/>Que_en_esta_era_impía puedan ver<br/>Su eterno plan.<br/>Tu arca, ¿dónde está?<br/>¿Quién se entregará por Ti?<br/>¿Perdiendo sus vidas<br/>Para honrar Tu corazón?<br/>',NULL,195953,1);
INSERT INTO stanza VALUES('S2020','chorus','Nazareos por Tu plan<br/>Levanta hoy<br/>Que proclamen con Tu autoridad.<br/>Hombres de oración,<br/>Profetas, jueces y<br/>Sacerdotes<br/>Con Tu mismo corazón.<br/>',NULL,195954,2);
INSERT INTO stanza VALUES('S2020','2','Hoy, adiéstranos,<br/>Con visión, buscándote;<br/>Esperando y sujetos a Tu voluntad.<br/>Mirando Tu faz,<br/>En Tu presencia, Señor;<br/>Tu mirada nos indicará Tu dirección.<br/>',NULL,195955,3);
INSERT INTO stanza VALUES('S2020','chorus','Nazareos por Tu plan<br/>Levanta hoy,<br/>Que traigan Tu reino<br/>A la tierra hoy.<br/>Al tomarte como Rey regresarás,<br/>Y esta era, finalmente,<br/>cambiarás.<br/>',NULL,195956,4);
INSERT INTO stanza VALUES('S2020','3','Instrumento fiel<br/>Necesita nuestro Dios;<br/>Vencedores apartados para Su mover.<br/>El deseo de Dios<br/>El de ellos es también.<br/>Su Palabra santa<br/>Es hoy su constitución.<br/>',NULL,195957,5);
INSERT INTO stanza VALUES('S2020','chorus','Nazareos por Tu plan<br/>Levanta hoy,<br/>Entregados libremente a Ti.<br/>Han hallado<br/>En Tu Palabra Tu intención;<br/>Son Tu vivo testimonio hoy aquí.<br/>',NULL,195958,6);
INSERT INTO stanza VALUES('S2020','4','Necesita Dios<br/>Hombres que puedan orar;<br/>Su intención se desarrolla<br/>Por la oración.<br/>Aman al Señor,<br/>Sacrificio vivo son.<br/>Temen ofender a Dios,<br/>Su presencia perder.<br/>',NULL,195959,7);
INSERT INTO stanza VALUES('S2020','chorus','Nazareos por Tu plan,<br/>Haznos Señor.<br/>Para que este siglo puedas cerrar;<br/>Contigo uno son<br/>Para el reino traer,<br/>Jóvenes!<br/>Absolutos por Tu mover.<br/>',NULL,195960,8);
INSERT INTO stanza VALUES('S2021','1','Dio María su ofrenda de amor,<br/>A otros desperdicio fue.<br/>En todo tiempo amantes hay,<br/>Que prueban Tu amor dulce.<br/>Vidas preciosas, tesoros,<br/>Futuros brillantes también,<br/>"Desperdiciados"  han sido en Ti;<br/>Tu dulzura fragancia fiel.<br/>',NULL,195961,1);
INSERT INTO stanza VALUES('S2021','chorus','Tomó la oportunidad<br/>De amarte con lo mejor.<br/>Como ella, yo también<br/>Derramo todo mi amor.<br/>',NULL,195962,2);
INSERT INTO stanza VALUES('S2021','2','Mientras Te amo, centro mi ser:<br/>Espíritu, alma y cuerpo;<br/>Mente, fuerzas, y corazón,<br/>También en Ti centro yo.<br/>Dejo que mi completo ser<br/>Sea ocupado por Ti .<br/>Así entro_en Tu corazón,<br/>dulce comunión aquí.<br/>',NULL,195963,3);
INSERT INTO stanza VALUES('S2021','chorus','Ocupado y perdido en Ti,<br/>Señor, mi todo eres Tú.<br/>Comunión tan íntima,<br/>Disfruto en espíritu.<br/>',NULL,195964,4);
INSERT INTO stanza VALUES('S2021','3','A nadie más puedo desear<br/>En la tierra ni en el cielo.<br/>Mi corazón podrá fallar,<br/>Más Tú serás mi porción.<br/>Todo es vano, basura es;<br/>"Ganancias", pérdidas son.<br/>Usurpan mi corazón,<br/>Más Tú has ganado mi amor.<br/>',NULL,195965,5);
INSERT INTO stanza VALUES('S2021','chorus','¡Cuán precioso eres Señor!<br/>Tu belleza ha llegado a mí.<br/>Hoy confieso yo, Señor,<br/>Mi amor sólo es para Ti.<br/>',NULL,195966,6);
INSERT INTO stanza VALUES('S2021','YouTube Link','https://www.youtube.com/watch?v=1kWFSfksYGg&list=RD1kWFSfksYGg&start_radio=1',NULL,195967,7);
INSERT INTO stanza VALUES('S2022','1','Oh Tu amor, Señor,<br/>¡Qué inmenso!<br/>Mi amor hacia Ti,<br/>¡Qué intenso!<br/>Cada día, cada instante,<br/>Gáname, Señor.<br/>Que la meta y el motivo<br/>De mi vida sea amarte,<br/>Que mi corazón sea siempre<br/>Fiel hacia Ti, mi Señor.<br/>',NULL,195968,1);
INSERT INTO stanza VALUES('S2022','chorus','¡Sí, atráeme!<br/>(¡Sí, atráeme!)<br/>¡Ven, desvélame!<br/>(¡Ven, desvélame!)<br/>Que mi corazón sea puro<br/>Para verte a Ti.<br/>Que yo te ame a Ti<br/>(Que yo te ame a Ti)<br/>Y a ninguno más.<br/>(Y a ninguno más)<br/>¡Oh Señor, completamente,<br/>Entrego mi ser a Ti!<br/>',NULL,195969,2);
INSERT INTO stanza VALUES('S2022','SoundCloud Link','https://soundcloud.com/user-871371384/aud-20211031-wa0016-aac',NULL,195970,3);
INSERT INTO stanza VALUES('S2023','1','Da tu ser para amar al Señor,<br/>No hay otra manera tan prevaleciente.<br/>Ni hay otra más,<br/>Ni hay otra más tan segura.<br/>',NULL,195971,1);
INSERT INTO stanza VALUES('S2023','2','Da tu ser para amar al Señor,<br/>No hay otra manera tan rica.<br/>Y llena, tan llena de disfrute.<br/>',NULL,195972,2);
INSERT INTO stanza VALUES('S2023','chorus','Temprano cada día<br/>Le debemos decir:<br/>Te amo, Señor Jesús.<br/>',NULL,195973,3);
INSERT INTO stanza VALUES('S2023','3','Da tu ser para amar al Señor,<br/>Que nada más te interese.<br/>¡Ámale! ¡no hagas más!<br/>Al Señor, conságrate a amar.<br/>',NULL,195974,4);
INSERT INTO stanza VALUES('S2023','chorus','Señor, no somos nuestros,<br/>Pues damos todo a Ti.<br/>¡Te amamos! ¡Te amamos!<br/>Te amamos ¡Señor Jesús!<br/>',NULL,195975,5);
INSERT INTO stanza VALUES('S2023','YouTube Link','https://www.youtube.com/watch?v=c0fn-7_cbMo',NULL,195976,6);
INSERT INTO stanza VALUES('S2024','1','En esta era de hoy,<br/>Rebeldía, idolatría,<br/>Con todos sus pecados y deleites.<br/>Éramos esclavos bajo cautiverio,<br/>Faraón nos amargaba la vida.<br/>',NULL,195977,1);
INSERT INTO stanza VALUES('S2024','chorus','Por eso un día<br/>El Señor nos rescató.<br/>¡Prepáranos, en pos de Ti correremos!<br/>Vacíanos por completo,<br/>Haznos útiles.<br/>Ser el Moisés corporativo de hoy.<br/>Seguiremos Tus caminos<br/>Fuera del mundo,<br/>Sin mirar atrás.<br/>',NULL,195978,2);
INSERT INTO stanza VALUES('S2024','2','Señor, ayúdanos<br/>A depender más de Ti,<br/>Para ser Tus instrumentos en la tierra.<br/>Yo no soy nada,<br/>EL GRAN YO SOY Tú eres,<br/>Más debemos prepararnos<br/>Sólo para Ti.<br/>',NULL,195979,3);
INSERT INTO stanza VALUES('S2024','chorus','Por eso un día<br/>El Señor nos rescató.<br/>¡Prepáranos, en pos de Ti correremos!<br/>Vacíanos por completo,<br/>Haznos útiles.<br/>Ser el Moisés corporativo de hoy.<br/>Seguiremos Tus caminos<br/>Fuera del mundo,<br/>Sin mirar atrás.<br/>',NULL,195980,4);
INSERT INTO stanza VALUES('S2024','3','No nos engañemos,<br/>A Faraón no hagamos caso.<br/>Si estamos en el mundo<br/>no estamos con Dios.<br/>Tú derramaste Tu sangre por nosotros<br/>Y también nos libraste del pecado.<br/>',NULL,195981,5);
INSERT INTO stanza VALUES('S2024','chorus','Por eso ya, Tu pueblo te clama:<br/>¡Señor ven ya,<br/>Aquí te esperaremos!<br/>Deseamos Tu regreso,<br/>Y contigo estar.<br/>Derrotaremos a Tu enemigo hasta el fin.<br/>Deseamos Tu regreso,<br/>Y contigo estar.<br/>¡Oh Señor, ven pronto!<br/>',NULL,195982,6);
INSERT INTO stanza VALUES('S2025','1','Te amo, Señor Jesús.<br/>Te amo precioso Señor.<br/>Tú no tienes comparación. (x2)<br/>',NULL,195983,1);
INSERT INTO stanza VALUES('S2025','2','Jesús, Señor Jesús.<br/>Querido, encantador,<br/>Nadie te igualará.<br/>',NULL,195984,2);
INSERT INTO stanza VALUES('S2026','1','Eres mi amor, mi primer amor Jesús,<br/>Y Tu valor, ¿Quién podría traducir?<br/>Tesoro mío, precioso, singular;<br/>En cielo y tierra otro como Tú no hay.<br/>',NULL,195985,1);
INSERT INTO stanza VALUES('S2026','2','Amado mío, ¿A quién te compararé?<br/>Tú eres Dios, ¿Con qué te confrontaré?<br/>Tú mismo me conduces junto a Ti;<br/>Y me atraes mucho más que el mundo aquí.<br/>',NULL,195986,2);
INSERT INTO stanza VALUES('S2026','chorus','Te amo, mi Jesús,<br/>¡Tu valor nadie supera!<br/>Quién satisface sino Tú,<br/>No hay otro como Tú en la tierra.<br/>',NULL,195987,3);
INSERT INTO stanza VALUES('S2026','3','Oh, Tu mirar alumbra la oscuridad,<br/>Y Tu hablar es muy dulce al corazón.<br/>Sólo Tu amor me constriñe a vivir<br/>Por Ti, Señor, quien ganó todo mi ser.<br/>',NULL,195988,4);
INSERT INTO stanza VALUES('S2026','4','Tan sólo Tú eres mi real placer;<br/>Consolador, plena gracia en mi sufrir;<br/>Satisfacción y alegría que es sin fin.<br/>Un manantial de aguas vivas que hay en mí.<br/>',NULL,195989,5);
INSERT INTO stanza VALUES('S2026','chorus','Oh, mi Amado ven,<br/>Cara a cara anhelo verte,<br/>No tardes, ven pronto a nos,<br/>Despósanos eternamente.<br/>',NULL,195990,6);
INSERT INTO stanza VALUES('S2026','SoundCloud Link','https://soundcloud.com/melissa-c-jara/eres-mi-amor-mi-primer-amor',NULL,195991,7);
INSERT INTO stanza VALUES('S2027','1','Doy mi ser a Ti, Señor Jesús,<br/>Quiero estar ocupado en Ti, Señor,<br/>Lo dejo todo atrás<br/>Y mi ser concentro en Ti,<br/>Sólo en Ti.<br/>',NULL,195992,1);
INSERT INTO stanza VALUES('S2027','chorus','Tú eres mi enfoque,<br/>Tú eres mi meta,<br/>Me entrego ahora mismo a Ti.<br/>Tú eres mi enfoque,<br/>Tú eres mi meta,<br/>Me entrego ahora mismo a Ti.<br/>',NULL,195993,2);
INSERT INTO stanza VALUES('S2027','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2027_doy-mi-ser-a-ti-sen-or',NULL,195994,3);
INSERT INTO stanza VALUES('S2028','1','Tú‿eres el primer amor<br/>De todos es el mejor,<br/>Y así el corazón,<br/>Descansa sólo‿en Tu‿amor.<br/>',NULL,195995,1);
INSERT INTO stanza VALUES('S2028','2','Te amamos por ser Tú,<br/>No por lo que Tú nos das,<br/>No se puede comparar,<br/>El gozo de‿amarte‿a Ti.<br/>',NULL,195996,2);
INSERT INTO stanza VALUES('S2028','chorus','¡Cuántas cosas se han dejado ya!<br/>Nuestro corazón se vuelve a Ti.<br/>No amamos nada más,<br/>Tú eres el mejor amor.<br/>',NULL,195997,3);
INSERT INTO stanza VALUES('S2028','3','Nada deseamos ya,<br/>Nada que no seas Tú;<br/>Nada aspiramos ya,<br/>Sólo ser llenos de Ti.<br/>',NULL,195998,4);
INSERT INTO stanza VALUES('S2028','4','Tu eres el primer amor,<br/>De todos es el mejor;<br/>Y así el corazón,<br/>Descansa sólo en Tu amor.<br/>',NULL,195999,5);
INSERT INTO stanza VALUES('S2028','chorus','¡Cuántas cosas se han dejado ya!<br/>Nuestro corazón se vuelve a Ti.<br/>No amamos nada más,<br/>Tú eres el mejor amor.<br/>',NULL,196000,6);
INSERT INTO stanza VALUES('S2028','SoundCloud Link','https://soundcloud.com/damarisleg/tu-eres-el-primer-amor-jesus',NULL,196001,7);
INSERT INTO stanza VALUES('S2029','1','Sencillamente, Señor,<br/>Quiero decirte que te amo tanto.<br/>Que te amo de corazón y te adoro,<br/>Yo tanto, tanto, tanto.<br/>Sin Ti no puedo vivir;<br/>Sin Ti no puedo reír.<br/>Mi vida la llenas Tú<br/>Y nadie más que Tú,<br/>Y nadie más que Tú.<br/>',NULL,196002,1);
INSERT INTO stanza VALUES('S2029','YouTube Link','https://www.youtube.com/watch?v=YV3g1vbjct0',NULL,196003,2);
INSERT INTO stanza VALUES('S2030','1','Jesús, Tú eres bello,<br/>Tú eres más deseable<br/>Que el mundo y sus deleites.<br/>Fino eres, dulce y fiel.<br/>Señor, Tu belleza<br/>Excede lo más bello.<br/>Gentil, Tú eres tierno.<br/>Radiante, encantador.<br/>',NULL,196004,1);
INSERT INTO stanza VALUES('S2030','2','Al contemplarte, Cristo,<br/>Me atraes por completo.<br/>No puedo alejarme,<br/>Descanso en Tu paz.<br/>Y mientras pasa el tiempo<br/>Yo vivo en Tu presencia,<br/>Tan santa e inigualable,<br/>Mirando allí Tu faz.<br/>',NULL,196005,2);
INSERT INTO stanza VALUES('S2030','3','Te doy toda mi vida,<br/>Pues sólo Tú eres digno.<br/>No hay nada, no hay nadie,<br/>¡Te anhelo sólo a Ti!<br/>Que mis días sean tuyos,<br/>Mi corazón te ame;<br/>Por Tu abundante gracia,<br/>Te adore y sirva a Ti.<br/>',NULL,196006,3);
INSERT INTO stanza VALUES('S2030','SoundCloud Link','https://soundcloud.com/user-537299855/aud-20240412-wa0020-mp3',NULL,196007,4);
INSERT INTO stanza VALUES('S2031','1','Dios tiene hoy un plan,<br/>Hacernos de valor dispensacional<br/>Para poder cambiar,<br/>Cambiar la era actual.<br/>',NULL,196008,1);
INSERT INTO stanza VALUES('S2031','chorus','Todos voluntariamente,<br/>Nos consagraremos<br/>Para cooperar con Dios,<br/>Cambiar la era actual.<br/>',NULL,196009,2);
INSERT INTO stanza VALUES('S2031','2','Señor, hazme un Samuel<br/>Y dedicar mi vida sólo para Ti;<br/>Ver sólo Tu mover<br/>En santificación.<br/>',NULL,196010,3);
INSERT INTO stanza VALUES('S2031','3','Para ídolos vencer<br/>Como Daniel debemos<br/>Siempre orar a Ti<br/>Y en Ti firmes estar.<br/>Y en Ti firmes estar.<br/>',NULL,196011,4);
INSERT INTO stanza VALUES('S2031','4','Daniel y compañeros<br/>No se contaminaron<br/>De lo terrenal;<br/>Como un grupo vital<br/>Comieron del Señor.<br/>',NULL,196012,5);
INSERT INTO stanza VALUES('S2032','1','El Señor Jesús nos prometió volver.<br/>Su venida hoy a la puerta está.<br/>El vendrá a llevarse al que es vencedor,<br/>Su gloriosa novia así Él ganará.<br/>',NULL,196013,1);
INSERT INTO stanza VALUES('S2032','chorus','Señor, me consagro plenamente a Ti.<br/>Satura, limpia y purifica mi ser.<br/>Velaré, oraré, te amaré hasta el fin.<br/>Quiero Señor ser Tu satisfacción.<br/>',NULL,196014,2);
INSERT INTO stanza VALUES('S2032','2','Mas Tú sabes que no califico, Señor,<br/>Que te necesito para ser vencedor.<br/>Ven amado Sol de la justicia a mí,<br/>Extiende Tus alas, sana todo mi ser.<br/>',NULL,196015,3);
INSERT INTO stanza VALUES('S2032','3','Hazme atento a estar a las señales Señor,<br/>A velar y orar y no embotado estar.<br/>Este mundo quiere mi alma cautivar,<br/>Mi alma no está en venta -<br/>Pertenece al Señor.<br/>',NULL,196016,4);
INSERT INTO stanza VALUES('S2032','4','Una virgen pura y prudente Señor,<br/>Que acumula aceite, que lo compra de Ti.<br/>Que mi lámpara siempre ardiendo esté<br/>Para entrar contigo a las bodas Señor.<br/>',NULL,196017,5);
INSERT INTO stanza VALUES('S2032','5','Un esclavo fiel y constituido de Ti<br/>Que imparte a otros tus riquezas, Señor;<br/>Que cuando Tú vuelvas, pueda yo escuchar:<br/>¡Buen esclavo fiel, entra a disfrutar!<br/>',NULL,196018,6);
INSERT INTO stanza VALUES('S2032','SoundCloud Link','https://soundcloud.com/ashley-sagal-561607758/me-consagro-plenamente-a-ti',NULL,196019,7);
INSERT INTO stanza VALUES('S2033','1','Inmerso en Tu amor,<br/>Tu me refrescas,<br/>Aquí estoy<br/>Guardado de preocupación.<br/>Eres tan tierno,<br/>Tu acariciándome,<br/>El más amoroso<br/>Y justo cada vez.<br/>',NULL,196020,1);
INSERT INTO stanza VALUES('S2033','chorus','Contigo estar,<br/>¡Me llenas de amor!<br/>Y ahora yo Te quiero confesar:<br/>Que Te amo.<br/>Nunca Te dejaré,<br/>Pase lo que pase.<br/>',NULL,196021,2);
INSERT INTO stanza VALUES('S2033','2','No lo puedo evitar,<br/>Enamorado estoy.<br/>Tus amores<br/>Me embriagaron más y más.<br/>Empapado en Tú amor<br/>Mi todo es para Ti<br/>Sea cual sea mi futuro,<br/>Tuyo es.<br/>',NULL,196022,3);
INSERT INTO stanza VALUES('S2033','3','Tan atraído por<br/>Tu amor constreñidor,<br/>Por Tu nombre<br/>Dulce como Tu unción.<br/>Cautivado estoy<br/>Por Tu persona.<br/>Ráptame de ésta era para Ti.<br/>',NULL,196023,4);
INSERT INTO stanza VALUES('S2033','YouTube Link','https://www.youtube.com/watch?v=6RdrG-2IISQ',NULL,196024,5);
INSERT INTO stanza VALUES('S2034','1','El testimonio de Jesús,<br/>Aquí debemos expresar<br/>Para el mundo cautivar<br/>Y por Él así brillar.<br/>',NULL,196025,1);
INSERT INTO stanza VALUES('S2034','chorus','No hay nada aquí en el mundo,<br/>Solo Cristo es nuestra meta.<br/>Nosotros somos los que edifican,<br/>Para expresarle y hacerle volver.<br/>',NULL,196026,2);
INSERT INTO stanza VALUES('S2034','2','Cuando Dios le ordenó<br/>A Noé el arca crear,<br/>Todo el mundo de él dudó,<br/>Pero él firme siguió.<br/>',NULL,196027,3);
INSERT INTO stanza VALUES('S2034','chorus','No hay nada aquí en el mundo,<br/>Solo Cristo es nuestra meta.<br/>Nosotros somos los que edifican,<br/>Para expresarle y hacerle volver.<br/>',NULL,196028,4);
INSERT INTO stanza VALUES('S2034','3','Abrirle el corazón<br/>Y darle el primer lugar.<br/>Ser aquel hijo varón<br/>Que derrota a Satanás.<br/>',NULL,196029,5);
INSERT INTO stanza VALUES('S2034','chorus','No hay nada aquí en el mundo,<br/>Solo Cristo es nuestra meta.<br/>Nosotros somos los que edifican,<br/>Para expresarle y hacerle volver.<br/>',NULL,196030,6);
INSERT INTO stanza VALUES('S2034','4','Semillas hay que ser,<br/>Debemos a Cristo plantar.<br/>No ser pasivos más<br/>Y nuevas almas rescatar.<br/>',NULL,196031,7);
INSERT INTO stanza VALUES('S2034','chorus','Debemos ser hoy Su testimonio<br/>Edificar el arca, la iglesia.<br/>Resplandecer en la era maligna,<br/>Y de este modo hacerle volver.<br/>',NULL,196032,8);
INSERT INTO stanza VALUES('S2034','5','La Nueva Jerusalén,<br/>Nuestra meta debe ser,<br/>Venciendo a Satanás<br/>Diciéndole al Señor ¡Amén!<br/>',NULL,196033,9);
INSERT INTO stanza VALUES('S2034','chorus','No hay nada aquí en el mundo,<br/>Solo Cristo es nuestra meta.<br/>Nosotros somos los que edifican,<br/>Para expresarle y hacerle volver.<br/>',NULL,196034,10);
INSERT INTO stanza VALUES('S2034','chorus','Debemos ser hoy Su testimonio<br/>Edificar el arca, la iglesia.<br/>Resplandecer en la era maligna,<br/>Y de este modo hacerle volver.<br/>',NULL,196035,11);
INSERT INTO stanza VALUES('S2034','SoundCloud Link','',NULL,196036,12);
INSERT INTO stanza VALUES('S2035','1','Cuando yo sentí el amor de Dios<br/>Que me demostró en la cruz.<br/>Cuando yo sentí en mi corazón<br/>Que en la cruz por mí_El sufrió.<br/>',NULL,196037,1);
INSERT INTO stanza VALUES('S2035','chorus','Tan grande amor es del Señor,<br/>Que no puedo comprender,<br/>Que me amara a mí,<br/>Siendo lo que soy.<br/>Es imposible entender,<br/>La grandeza de Su amor.<br/>Gracias Señor, por Tu amor.<br/>',NULL,196038,2);
INSERT INTO stanza VALUES('S2035','2','Por esta causa doblo mis rodillas,<br/>Ante el Padre de Jesús;<br/>Quien te quiere revelar a ti,<br/>Su justica en la cruz.<br/>',NULL,196039,3);
INSERT INTO stanza VALUES('S2035','SoundCloud Link','https://soundcloud.com/user-518979615/cuando-yo-senti-el-amor-de-dios-ayn',NULL,196040,4);
INSERT INTO stanza VALUES('S2036','chorus','Al Señor besa hoy,<br/>Al que vino por amor.<br/>Me animó y cautivó,<br/>Y en la cruz por mí murió.<br/>Murió por mí, salvándome,<br/>Y Su Espíritu en mí entró,<br/>¡Besé al Señor!<br/>',NULL,196041,1);
INSERT INTO stanza VALUES('S2036','1','En mi espíritu mezclado<br/>Sirviendo al Hijo de Dios;<br/>El Espíritu en mí ha entrado:<br/>Procesado Triuno Dios.<br/>',NULL,196042,2);
INSERT INTO stanza VALUES('S2036','2','En nuestra experiencia,Cristo,<br/>La alabanza buena es;<br/>Que en espíritu alabemos,<br/>Lo que requiere Dios es.<br/>',NULL,196043,3);
INSERT INTO stanza VALUES('S2036','3','Dejo que Cristo me bese<br/>Al servirle, vivo en Él.<br/>Si con mi vivir le alabo,<br/>A Cristo predicaré.<br/>',NULL,196044,4);
INSERT INTO stanza VALUES('S2036','4','Sirve a Dios, hoy, en el Cuerpo,<br/>No en la vida natural.<br/>Si en resurrección tú vives,<br/>Adórale en realidad.<br/>',NULL,196045,5);
INSERT INTO stanza VALUES('S2036','YouTube Link','https://www.youtube.com/watch?v=QYrnQhLdnOM',NULL,196046,6);
INSERT INTO stanza VALUES('S2037','1','Después que desayunase,<br/>Para que en sí no confiase;<br/>El amor de Pedro, Cristo,<br/>Fue a restaurar.<br/>Pedro fracasó con creces,<br/>Al Señor negó tres veces,<br/>Y aunque al final se fuese, Dijo Jesús…<br/>',NULL,196047,1);
INSERT INTO stanza VALUES('S2037','chorus','¿Tu Me amas? Pastorea…<br/>¿Tu Me amas? …a mis ovejas.<br/>¿Tu Me amas?<br/>A mis ovejas da de comer.<br/>',NULL,196048,2);
INSERT INTO stanza VALUES('S2037','2','Todos hemos tropezado,<br/>Como Pedro, derrotados;<br/>De orgullosos a humillados,<br/>En depresión.<br/>El Señor, entonces, viene;<br/>Busca nuestro amor y afecto.<br/>Le escuchamos y al oído<br/>Nos dice así…<br/>',NULL,196049,3);
INSERT INTO stanza VALUES('S2037','chorus','¿Tu Me amas? Pastorea…<br/>¿Tu Me amas? …a mis ovejas.<br/>¿Tu Me amas?<br/>A mis ovejas da de comer.<br/>',NULL,196050,4);
INSERT INTO stanza VALUES('S2037','3','Al Señor hoy le detiene<br/>Que no hay muchos pastores<br/>Que alimenten a la oveja<br/>Que se perdió.<br/>Él desea que cooperemos<br/>Con Él y que pastoreemos.<br/>¿Eres uno que está abierto<br/>Y dice así…?<br/>',NULL,196051,5);
INSERT INTO stanza VALUES('S2037','chorus','¡Sí, Te amo! Pastorearé.<br/>¡Sí, Te amo! Apacentaré.<br/>¡Sí! Mi Señor, Te amo.<br/>A Tus ovejas cuidaré.<br/>',NULL,196052,6);
INSERT INTO stanza VALUES('S2038','1','¿Existe alguien, un amigo,<br/>A quien me pueda abrir;<br/>Alguien, que entiende<br/>Lo que sucede en mí.<br/>Alguien, cuando no hay<br/>Nadie a quien pueda ir?<br/>No existe nadie, como Él.<br/>',NULL,196053,1);
INSERT INTO stanza VALUES('S2038','chorus','Sí existe alguien,<br/>A quien te puedas abrir.<br/>Sí existe alguien,<br/>Que te llevará hasta el fin,<br/>Sí existe alguien,<br/>Cuando no hay nadie.<br/>Sí existe alguien, Admirable.<br/>',NULL,196054,2);
INSERT INTO stanza VALUES('S2038','2','¿Existe alguien, que me cuide<br/>En los momentos duros;<br/>Alguien, siempre allí,<br/>Aunque  haga sol o llueva;<br/>Alguien, un apoyo,<br/>Bajo la tempestad?<br/>No existe nadie, como Él.<br/>',NULL,196055,3);
INSERT INTO stanza VALUES('S2038','chorus','Sí existe alguien,<br/>En las dificultades.<br/>Sí existe alguien,<br/>Aunque llueva o haga sol.<br/>Sí existe alguien,<br/>Cuando no hay nadie.<br/>Existe alguien, muy especial.<br/>',NULL,196056,4);
INSERT INTO stanza VALUES('S2038','3','¿Existe alguien, que me acepte,<br/>Acepte tal como soy;<br/>Alguien que no huya,<br/>En quien confiar hasta el fin;<br/>Uno que me conoce,<br/>Y aun me quiere así?<br/>No existe nadie, como Él.<br/>',NULL,196057,5);
INSERT INTO stanza VALUES('S2038','chorus','Sí existe alguien,<br/>Que te acepta como eres.<br/>Sí existe alguien,<br/>Cerca o lejos llegará a Ti.<br/>Sí existe alguien,<br/>El más encantador.<br/>A Él elige, Admirable.<br/>',NULL,196058,6);
INSERT INTO stanza VALUES('S2038','4','¿Existe alguien que si llegue<br/>A lo profundo en mi ser;<br/>Alguien que afine<br/>Las cuerdas rotas en mí;<br/>Alguien que me ame,<br/>Cuando no hay más amor?<br/>No existe nadie, como Él.<br/>',NULL,196059,7);
INSERT INTO stanza VALUES('S2038','chorus','Sí existe alguien,<br/>Que te pueda conmover.<br/>Sí existe alguien,<br/>Que te puede hacer cantar.<br/>Sí existe alguien,<br/>Él es el gran Amor.<br/>A Este ama, Admirable.<br/>',NULL,196060,8);
INSERT INTO stanza VALUES('S2038','chorus','Cristo es el "Alguien"<br/>Que te puede conmover;<br/>Cristo es el "Alguien"<br/>Que te puede hacer cantar;<br/>Cristo es el "Alguien"<br/>Cristo precioso es.<br/>A Cristo ama, el Admirable.<br/>',NULL,196061,9);
INSERT INTO stanza VALUES('S2039','1','Dedícale tiempo,<br/>Recibe al Señor,<br/>Leyendo la Biblia<br/>Te inunde Su ser.<br/>Su luz tan radiante<br/>Nos da sanidad.<br/>Su luz se hace vida<br/>Al gozarnos en Él.<br/>',NULL,196062,1);
INSERT INTO stanza VALUES('S2039','2','Dedícale tiempo,<br/>Absorbe  al Señor,<br/>Para ser nutrido<br/>Y suplido por Él.<br/>Raíces profundas,<br/>Profundo el fluir.<br/>Más fuerte y más alto<br/>En ti Él crecerá.<br/>',NULL,196063,2);
INSERT INTO stanza VALUES('S2039','3','Dedícale tiempo,<br/>Inhala al Señor,<br/>Recibe la vida en<br/>El Verbo de Dios.<br/>Él se ha exhalado<br/>Para así inhalar<br/>Su vida, Su plenitud<br/>Y realidad.<br/>',NULL,196064,3);
INSERT INTO stanza VALUES('S2039','4','Dedícale tiempo,<br/>Disfruta al Señor,<br/>Quien es tu porción,<br/>Vida y realidad.<br/>¡Oh cuán disfrutable,<br/>Cuán rico y real!<br/>Él es nuestro todo<br/>Al leer-orar.<br/>',NULL,196065,4);
INSERT INTO stanza VALUES('S2039','5','Dedícale tiempo,<br/>contempla al Señor,<br/>Recibe Su gracia,<br/>Su ser y Su amor.<br/>Su luz agradable<br/>Él te infundirá,<br/>Tu rostro brillante,<br/>Radiante estará.<br/>',NULL,196066,5);
INSERT INTO stanza VALUES('S2040','1','Noble sostén<br/>De la esperanza mía,<br/>Fuente bendita de vida eterna.<br/>Tan solo el alma,<br/>Que en Tus fuerzas fía,<br/>Tiene paz,  tiene paz.<br/>',NULL,196067,1);
INSERT INTO stanza VALUES('S2040','chorus','Mi sostén es Jesús,<br/>Nunca en la lucha<br/>Desmayar podré.<br/>Mi sostén es Jesús,<br/>Nunca en la lucha<br/>Desmayar podré.<br/>',NULL,196068,2);
INSERT INTO stanza VALUES('S2040','2','Dura es la lucha,<br/>Difícil la tarea,<br/>Más Tú me dotas<br/>De Tu gran poder.<br/>Mi espíritu renuevas<br/>con la idea nueva,<br/>De vencer, de vencer.<br/>',NULL,196069,3);
INSERT INTO stanza VALUES('S2040','3','Yo soy muy débil,<br/>Pero en Ti soy fuerte,<br/>Nunca en la lucha<br/>Desmayar podré.<br/>Si Tú estás conmigo,<br/>Ni a la misma muerte,<br/>Temeré; temeré.<br/>',NULL,196070,4);
INSERT INTO stanza VALUES('S2040','YouTube Link','https://www.youtube.com/watch?v=bt5uUICzgcg',NULL,196071,5);
INSERT INTO stanza VALUES('S2041','1','Sobre vacío y desolación,<br/>El Espíritu de Dios se cernió,<br/>Trayendo en nosotros Su hablar,<br/>¡Oh, se hizo la luz!<br/>',NULL,196072,1);
INSERT INTO stanza VALUES('S2041','chorus','Y la luz brilla en las tinieblas,<br/>Y la oscuridad no prevaleció.<br/>En Él estaba la vida,<br/>Que era nuestra luz.<br/>',NULL,196073,2);
INSERT INTO stanza VALUES('S2041','2','Día aumenta, noche mengua,<br/>Cada día Su palabra al buscar.<br/>Anímate y libera tu espíritu.<br/>¡Somos los hijos de luz!<br/>',NULL,196074,3);
INSERT INTO stanza VALUES('S2041','SoundCloud Link','https://soundcloud.com/jules-campos-kalaidjian/la-luz',NULL,196075,4);
INSERT INTO stanza VALUES('S2042','1','Hay momentos<br/>Que mi alma es llena<br/>De amargura,<br/>Preguntas sin respuestas,<br/>Más Tú me atraes...<br/>',NULL,196076,1);
INSERT INTO stanza VALUES('S2042','chorus','A ir y entrar<br/>En Tu bendito santuario;<br/>A lo alto volver mi mirar,<br/>Vuelves mis persistentes dudas<br/>En dulce oración.<br/>',NULL,196077,2);
INSERT INTO stanza VALUES('S2042','2','¿A quién tengo<br/>En los cielos<br/>Sino a Ti, Señor?<br/>Mi corazón y carne<br/>Fallan sin cesar.<br/>',NULL,196078,3);
INSERT INTO stanza VALUES('S2042','chorus','Más Dios es<br/>Mi porción y<br/>Mi fortaleza,<br/>Por siempre<br/>A Él me acercaré.<br/>Mi dulce y eterno refugio,<br/>Mi Salvador es.<br/>',NULL,196079,4);
INSERT INTO stanza VALUES('S2042','3','Vuélveme,<br/>Necesito verte a Ti, Jesús.<br/>Aún cuando no comprendo<br/>Tus sendas Señor;<br/>',NULL,196080,5);
INSERT INTO stanza VALUES('S2042','chorus','Haz de mí<br/>Un tierno lactante que_alabe,<br/>Tu bien disfrute cada vez,<br/>Impártete_en cada experiencia,<br/>Que en todo yo_exhiba<br/>Hoy Tu ser.<br/>',NULL,196081,6);
INSERT INTO stanza VALUES('S2042','SoundCloud Link','https://soundcloud.com/clara-orjuela-78079798/hay-momentos',NULL,196082,7);
INSERT INTO stanza VALUES('S2043','chorus','¡Seguid, seguid, en Cristo seguid!<br/>¡Sed fuertes, en Cristo seguid!<br/>En vano no ha de ser la labor,<br/>Debéis seguir, en Cristo seguir.<br/>',NULL,196083,1);
INSERT INTO stanza VALUES('S2043','1','Las pruebas vendrán,<br/>Y desánimo traen,<br/>Debéis seguir, en Cristo seguir.<br/>Dejad el de ayer,<br/>Y a Cristo seguid,<br/>Nuevas Sus misericordias son.<br/>',NULL,196084,2);
INSERT INTO stanza VALUES('S2043','chorus','¡Corred, corred en Cristo corred!<br/>¡Sed fuertes, en Cristo corred!<br/>En vano no ha de ser la labor,<br/>Debéis correr, en Cristo correr.<br/>',NULL,196085,3);
INSERT INTO stanza VALUES('S2043','2','Es vano el afán, la preocupación,<br/>Si el mañana nunca vendrá.<br/>Él supliendo está toda necesidad,<br/>Debéis correr, en Cristo correr.<br/>',NULL,196086,4);
INSERT INTO stanza VALUES('S2043','chorus','¡En el Señor, debéis proseguir!<br/>¡Sed fuertes, proseguid en Él!<br/>En vano no ha de ser la labor.<br/>Debéis seguir, seguir,<br/>Correr, correr<br/>En el Señor debéis proseguir.<br/>',NULL,196087,5);
INSERT INTO stanza VALUES('S2044','1','Cuán abundante es<br/>El don de la justicia,<br/>¡Lo hondo de Su amor<br/>Nunca lo entenderé!<br/>Nos alcanza ya Su amor,<br/>¡Cuánta compasión mostró!<br/>Mirad, en el trono está_el<br/>Cordero fiel.<br/>',NULL,196088,1);
INSERT INTO stanza VALUES('S2044','chorus','¿Por qué no abrirte<br/>Y llamarle: "¡Oh Señor!"?<br/>Ve a tu espíritu<br/>Donde gracia derramó.<br/>Llámale, gústale,<br/>Ejercítate ante Él<br/>Él es quien anhela,<br/>Añora y espera,<br/>Y siempre desea<br/>Que tú te vuelvas a Él.<br/>',NULL,196089,2);
INSERT INTO stanza VALUES('S2044','2','Él sabe qué_hay en ti<br/>Y todo lo que sientes.<br/>Él te conoce bien,<br/>Tu_historia y situación.<br/>Es cierto, Él listo está,<br/>Mas tu voz quiere escuchar:<br/>"Te rindo, Señor Jesús, mi corazón."<br/>',NULL,196090,3);
INSERT INTO stanza VALUES('S2044','YouTube Link','https://www.youtube.com/watch?v=1RDod20XLRY',NULL,196091,4);
INSERT INTO stanza VALUES('S2045','1','Lléname, Señor.<br/>Lléname, Señor.<br/>Hasta que reboses<br/>De mi ser interior.<br/>Lléname, Señor.<br/>Lléname, Señor.<br/>Hasta que reboses<br/>De mi ser interior.<br/>',NULL,196092,1);
INSERT INTO stanza VALUES('S2045','chorus','Lléname hoy,<br/>Es mí oración<br/>Oh Señor Jesús,<br/>Fluye como el agua viva<br/>Oh Señor Jesús,<br/>¡Salta, vivo manantial!<br/>Brota de mi ser interior.<br/>',NULL,196093,2);
INSERT INTO stanza VALUES('S2045','2','Ven a quebrantar-<br/>Ven a quebrantar-<br/>Mi emoción, mi mente<br/>Y mi voluntad.<br/>Ven a quebrantar -<br/>Ven a quebrantar -<br/>Mi emoción, mi mente<br/>Y mi voluntad.<br/>',NULL,196094,3);
INSERT INTO stanza VALUES('S2045','chorus','Quebrántame,<br/>Es mi oración,<br/>Oh Señor Jesús,<br/>Fluye como el agua viva<br/>Oh Señor Jesús,<br/>¡Salta, vivo manantial!<br/>Brota de mi ser interior.<br/>',NULL,196095,4);
INSERT INTO stanza VALUES('S2045','3','Fluya el río en mí,<br/>Fluya el río en mí.<br/>¡Al cantar, invocar,<br/>Y proclamar!<br/>Fluya el río en mí,<br/>Fluya el río en mí.<br/>¡Al cantar, invocar,<br/>Y proclamar! (¡ALELUYA!)<br/>',NULL,196096,5);
INSERT INTO stanza VALUES('S2045','chorus','¡Sí, fluye hoy,<br/>Es mi oración!<br/>Oh Señor Jesús,<br/>Fluye como el agua viva<br/>Oh Señor Jesús,<br/>¡Salta, vivo manantial!<br/>Brota de mi ser interior.<br/>',NULL,196097,6);
INSERT INTO stanza VALUES('S2045','SoundCloud Link','https://soundcloud.com/maryorie-villa/llename-senor-fill-my-spirit-upw-vale-edras',NULL,196098,7);
INSERT INTO stanza VALUES('S2046','1','En tu ser un dulce cambio gozarás,<br/>Cuando invoques al Señor;<br/>Las tristezas y las penas se irán,<br/>Si disfrutas y te llenas de Su amor.<br/>',NULL,196099,1);
INSERT INTO stanza VALUES('S2046','chorus','Clama: ¡Oh Señor!<br/>Y el cambio sentirás<br/>En tí crecerá y se expandirá;<br/>Clamando Su nombre,<br/>Le disfrutarás,<br/>Él te llenará y también te saciará.<br/>',NULL,196100,2);
INSERT INTO stanza VALUES('S2046','2','Cuando sientas<br/>Que solo y triste estás,<br/>Clama: ¡Oh, Señor Jesús!<br/>Sentirás que algo del mundo perderás,<br/>Y que Cristo creciendo en ti estará.<br/>',NULL,196101,3);
INSERT INTO stanza VALUES('S2046','chorus','Clama: ¡Oh Señor!<br/>Y el cambio sentirás<br/>En tí crecerá y se expandirá;<br/>Clamando_a Su nombre,<br/>Le disfrutarás,<br/>Él te llenará y también te saciará.<br/>',NULL,196102,4);
INSERT INTO stanza VALUES('S2046','3','Aún si alegre y lleno de felicidad<br/>En tu vida tú estás,<br/>Nunca dejes ni ceses de invocar,<br/>Pues tu gozo el Señor completará.<br/>',NULL,196103,5);
INSERT INTO stanza VALUES('S2046','chorus','Clama: ¡Oh Señor!<br/>Y el cambio sentirás<br/>En tí crecerá y se expandirá;<br/>Clamando_a Su nombre,<br/>Le disfrutarás,<br/>Él te llenará y también te saciará.<br/>',NULL,196104,6);
INSERT INTO stanza VALUES('S2046','4','De este mundo nada puedes esperar,<br/>Todo es pena y condena;<br/>Pero en Cristo libertad tú obtendrás,<br/>Porque de la muerte Él te liberó.<br/>',NULL,196105,7);
INSERT INTO stanza VALUES('S2046','chorus','Clama: ¡Oh Señor!<br/>Y el cambio sentirás<br/>En tí crecerá y se expandirá;<br/>Clamando_a Su nombre,<br/>Le disfrutarás,<br/>Él te llenará y también te saciará.<br/>',NULL,196106,8);
INSERT INTO stanza VALUES('S2046','5','Ya tu vida no será lo que antes fue,<br/>No le temas, ¡ámale!<br/>Toma a Cristo todo el tiempo,<br/>Dulce es Él,<br/>Sólo Él puede llenar tu corazón.<br/>',NULL,196107,9);
INSERT INTO stanza VALUES('S2046','chorus','Clamando al Señor lleno te sentirás,<br/>Regocijo y paz manifestarás,<br/>Invocándole salida encontrarás,<br/>Y todo tu ser a Él reflejará.<br/>',NULL,196108,10);
INSERT INTO stanza VALUES('S2046','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2046_en-tu-ser-un-dulce-cambio',NULL,196109,11);
INSERT INTO stanza VALUES('S2047','1','Mis pecados lavó,<br/>Un nuevo corazón me dio,<br/>Y así confié,<br/>Amé y busqué Su palabra.<br/>',NULL,196110,1);
INSERT INTO stanza VALUES('S2047','chorus','Sobre lo que has guardado,<br/>Me dice: Guarda el corazón,<br/>Porque del mismo fluye,<br/>Sí, fluye la vida.<br/>',NULL,196111,2);
INSERT INTO stanza VALUES('S2047','2','Camina conmigo,<br/>Y así me abro yo a Él,<br/>Él es mi vida y mi estancia<br/>Y mi necesidad.<br/>',NULL,196112,3);
INSERT INTO stanza VALUES('S2047','chorus','Sobre lo que has guardado,<br/>Me dice: Guarda el corazón.<br/>Porque del mismo fluye,<br/>Sí, fluye la vida.<br/>',NULL,196113,4);
INSERT INTO stanza VALUES('S2047','3','Me olvido que está allí,<br/>A veces en mi resbalar,<br/>Más Él espera y vigila<br/>Y me acerca a Él.<br/>',NULL,196114,5);
INSERT INTO stanza VALUES('S2047','chorus','Sobre lo que has guardado,<br/>Me dice: Guarda el corazón.<br/>Porque del mismo fluye,<br/>Sí, fluye la vida.<br/>',NULL,196115,6);
INSERT INTO stanza VALUES('S2047','chorus','Sobre lo que has guardado,<br/>Me dice: Guarda el corazón.<br/>Porque del mismo fluye,<br/>Sí,<br/>La vida.<br/>',NULL,196116,7);
INSERT INTO stanza VALUES('S2047','SoundCloud Link','https://soundcloud.com/valen_torres/sobre-lo-que-has-guardado-pr-4',NULL,196117,8);
INSERT INTO stanza VALUES('S2048','1','Nunca pensé que<br/>Dios sería disfrutable.<br/>Mi experiencia de_Él<br/>Indescriptible es.<br/>Cuando mi corazón abrí hacia Él,<br/>Él vino y me llenó hasta rebosar.<br/>',NULL,196118,1);
INSERT INTO stanza VALUES('S2048','chorus','Señor, ¡Maravilloso!<br/>Maravilloso,<br/>Jesús, Jesús.<br/>',NULL,196119,2);
INSERT INTO stanza VALUES('S2048','2','No lo busqué<br/>Ni le pedí: "Ven hacia mi".<br/>A veces pienso:<br/>"¿Es esto un sueño celestial?"<br/>No le merezco<br/>Un pecador como yo;<br/>Su compasión, amigos,<br/>Es la razón.<br/>',NULL,196120,3);
INSERT INTO stanza VALUES('S2048','chorus','¡Oh Tu misericordia!<br/>Señor, me ha alcanzado,<br/>Jesús, Jesús.<br/>',NULL,196121,4);
INSERT INTO stanza VALUES('S2048','3','Mis amigos dicen:<br/>"No te des tanto a Él;<br/>Sé muy normal<br/>Y sin al extremo llegar".<br/>Mas no lo puedo impedir,<br/>No hay otro igual,<br/>Él me tocó<br/>Y ahora vivo feliz.<br/>',NULL,196122,5);
INSERT INTO stanza VALUES('S2048','chorus','Tu amor me tocó,<br/>Tu amor me ha "arruinado",<br/>Jesús, Jesús.<br/>',NULL,196123,6);
INSERT INTO stanza VALUES('S2048','4','Cada momento<br/>Quiero vivir para Él.<br/>En todo mi Señor,<br/>Tú me debes ganar.<br/>Soy sólo un vaso,<br/>Tú el tesoro en mí.<br/>Señor espárcete<br/>En todo mi ser.<br/>',NULL,196124,7);
INSERT INTO stanza VALUES('S2048','chorus','¡Señor Jesús! Clamando,<br/>El precioso nombre,<br/>Jesús, Jesús.<br/>',NULL,196125,8);
INSERT INTO stanza VALUES('S2048','5','Ahora espero<br/>Que Tú vuelvas otra vez.<br/>Mantenme fiel a Ti,<br/>Señor hasta el final,<br/>A fin de verte<br/>Cara a cara Señor,<br/>Este es mi gran deseo:<br/>Ser vencedor.<br/>',NULL,196126,9);
INSERT INTO stanza VALUES('S2048','chorus','Señor, Tú vienes pronto,<br/>Oh, amado Novio,<br/>Jesús, Jesús.<br/>',NULL,196127,10);
INSERT INTO stanza VALUES('S2048','SoundCloud Link','https://soundcloud.com/user-517717210-909260187/nunca-pense-que-dios-seria',NULL,196128,11);
INSERT INTO stanza VALUES('S2049','1','Veo, Señor,<br/>Que sólo quieres que yo crea,<br/>No cambiar.<br/>En mi fracaso y desliz,<br/>Creer lo que has hecho,<br/>No lo que veo yo.<br/>',NULL,196129,1);
INSERT INTO stanza VALUES('S2049','2','Creo, Señor,<br/>Cuando derrota me rodee;<br/>Sigue igual,<br/>Al parecer, la situación;<br/>No me desanimo,<br/>Yo creo en Ti.<br/>',NULL,196130,2);
INSERT INTO stanza VALUES('S2049','3','Creo en Ti,<br/>Y no hay demanda en mí.<br/>Simple fe,<br/>Es lo que deseas en mí.<br/>Libre de ansiedades,<br/>Libre al creer.<br/>',NULL,196131,3);
INSERT INTO stanza VALUES('S2049','4','Creo en Ti<br/>Porque mi logro eres Tú.<br/>Al caer,<br/>Sólo debo de confesar,<br/>Seguir en Tu gozo,<br/>Amo creer en Ti.<br/>',NULL,196132,4);
INSERT INTO stanza VALUES('S2049','YouTube Link','https://www.youtube.com/watch?v=mOhAKKBiQZ4',NULL,196133,5);
INSERT INTO stanza VALUES('S2050','1','Querido y cerca a mí,<br/>Más cada día a mí;<br/>Su persona dentro en mí<br/>Se hace realidad.<br/>Esperanza y fe me da<br/>Al salvarme y amar.<br/>Mi todo en todo,<br/>Tú eres Señor.<br/>',NULL,196134,1);
INSERT INTO stanza VALUES('S2050','2','Si esperanza no hay<br/>Y corta es mi fe,<br/>Oigo Su voz decir:<br/>Confía y verás,<br/>Yo todo supliré<br/>Si sólo tú me crees,<br/>Toda duda se irá<br/>Confiando en Mí.<br/>',NULL,196135,2);
INSERT INTO stanza VALUES('S2050','YouTube Link','https://www.youtube.com/watch?v=5ahCoi5K444',NULL,196136,3);
INSERT INTO stanza VALUES('S2051','1','Hoy, Señor, te doy gracias,<br/>Por haberme seleccionado.<br/>Hoy, Señor, te doy gracias<br/>Porque de Ti estoy disfrutando.<br/>Puedo disfrutarte, puedo amarte,<br/>Puedo besarte y de Ti llenarme.<br/>¡Oh Señor Jesús! ¡Oh Señor Jesús!<br/>',NULL,196137,1);
INSERT INTO stanza VALUES('S2051','2','Hoy, Señor, te doy gracias<br/>Por la familia que me has dado.<br/>Esta gran familia,<br/>Que es la iglesia, mis hermanos.<br/>En el mundo nada tengo que buscar,<br/>Nada tengo que hallar.<br/>¡Hoy te tengo a Ti!<br/>¡Hoy te tengo a Ti!<br/>',NULL,196138,2);
INSERT INTO stanza VALUES('S2051','chorus','¡Qué milagro tan maravilloso<br/>El poder contenerte en mí!<br/>¡El poder disfrutarte y amarte!<br/>¡Oh qué hermoso es tenerte en mí!<br/>',NULL,196139,3);
INSERT INTO stanza VALUES('S2051','3','¡Qué glorioso, Señor, es saber<br/>Que estás presente!<br/>Pero, más glorioso es saber<br/>Que es para siempre.<br/>Una vez que entras no te vas,<br/>¡Oh qué grande fidelidad!<br/>¡Te amo Señor! ¡Te amo Señor!<br/>',NULL,196140,4);
INSERT INTO stanza VALUES('S2051','4','¡Oh Señor Jesús!<br/>Hoy un voto he de hacer contigo:<br/>Quiero decirte que siempre<br/>Puedes contar conmigo.<br/>Ya no vivo yo, más vives en mí,<br/>Hoy Te pertenezco a Ti.<br/>¡Señor, úsame! ¡Señor, úsame!<br/>',NULL,196141,5);
INSERT INTO stanza VALUES('S2051','chorus','Hoy declaro que quiero vencer,<br/>Hoy declaro que no he de temer<br/>A las máscaras del enemigo,<br/>Pues en Cristo está vencido.<br/>',NULL,196142,6);
INSERT INTO stanza VALUES('S2051','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/hoy-senor-te-doy-gracias-3',NULL,196143,7);
INSERT INTO stanza VALUES('S2052','1','Camino de Emaús,<br/>Iban dos discipulos,<br/>Solos y con temor.<br/>Un hombre se acercó,<br/>Le contaron que pasó,<br/>Entonces respondió:  (Dijo:)<br/>',NULL,196144,1);
INSERT INTO stanza VALUES('S2052','chorus','¿Por qué no creéis?<br/>Pues era necesario,<br/>Que para en Su gloria Cristo entrar<br/>Tuviera que sufrir.<br/>¿Por qué no creéis?<br/>¿Por qué no creéis?<br/>',NULL,196145,2);
INSERT INTO stanza VALUES('S2052','2','Llegaron a Emaús,<br/>Fue con ellos a cenar,<br/>Bendijo y partió pan.<br/>Se dieron cuenta de<br/>Que ese hombre era Jesús.<br/>Más desapareció.   (Dicen:)<br/>',NULL,196146,3);
INSERT INTO stanza VALUES('S2052','chorus','Mientras Él habló<br/>¿No ardía tu corazón?<br/>Cuando nos habló<br/>Todo nos reveló.<br/>Cuando nos habló,<br/>¿No ardía tu corazón?<br/>',NULL,196147,4);
INSERT INTO stanza VALUES('S2052','3','Contigo siempre estoy<br/>Siempre nos recordará<br/>En nuestro caminar.<br/>Ya que esté bien o mal,<br/>Es Espíritu, es real,<br/>Mora dentro de mi.   (Digo:)<br/>',NULL,196148,5);
INSERT INTO stanza VALUES('S2052','chorus','Me arde el corazón<br/>Si escucho Su voz.<br/>Jesucristo en mí<br/>¡Vive en resurrección!<br/>Me arde el corazón,<br/>Me arde el corazón.<br/>',NULL,196149,6);
INSERT INTO stanza VALUES('S2052','SoundCloud Link','https://soundcloud.com/noemi-gimenez-856202770/camino-de-emaus',NULL,196150,7);
INSERT INTO stanza VALUES('S2053','1','Persigue, disfruta,<br/>Se hallado en Él,<br/>Olvida y deja todo.<br/>Y gana, posee, captura a Aquel<br/>Que es tu visión central.<br/>',NULL,196151,1);
INSERT INTO stanza VALUES('S2053','chorus','Olvidando todo<br/>Lo que queda atrás,<br/>Ve en pos de Él con vehemencia.<br/>Redime el tiempo,<br/>Extiéndete a Él.<br/>A Cristo logra asir.<br/>',NULL,196152,2);
INSERT INTO stanza VALUES('S2053','2','A Cristo el Supremo persigue hoy,<br/>¡Él es el más precioso!<br/>Olvida y suelta hoy lo demás,<br/>Con fuerza ama al Señor.<br/>',NULL,196153,3);
INSERT INTO stanza VALUES('S2053','3','Jesús es mi centro y realidad;<br/>También mi vida eterna.<br/>Todo es basura<br/>Comparado a Él,<br/>Por tanto ¡gana al Señor!<br/>',NULL,196154,4);
INSERT INTO stanza VALUES('S2053','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/persigue-disfruta-1',NULL,196155,5);
INSERT INTO stanza VALUES('S2054','1','¿Qué te llevó a morir por mí?<br/>¿Morir por mí quien Tu enemigo fui?<br/>Tomaste en la cruz mi lugar,<br/>Maldito, maldito, llegaste a ser.<br/>',NULL,196156,1);
INSERT INTO stanza VALUES('S2054','chorus','¿Por qué morir por mí?<br/>Yo Tu enemigo fui;<br/>Maldito Tú llegaste a ser.<br/>¡Qué gran misterio es,<br/>Que muera Dios por mí!<br/>Por mí quien Su enemigo fui.<br/>',NULL,196157,2);
INSERT INTO stanza VALUES('S2054','2','Nunca pensé que eras un Ser,<br/>Lleno de amor, bondad y compasión.<br/>¿Cómo Señor?<br/>¿Por qué me amaste Tú?<br/>Te odiaba, me amaste, ¡Te amo, Jesús!<br/>',NULL,196158,3);
INSERT INTO stanza VALUES('S2054','chorus','¿Por qué morir por mí?<br/>Yo Tu enemigo fui;<br/>Maldito Tú llegaste a ser.<br/>¡Qué gran misterio es,<br/>Que muera Dios por mí!<br/>Por mí quien Su enemigo fui.<br/>',NULL,196159,4);
INSERT INTO stanza VALUES('S2054','3','Por largo tiempo amaste Tú,<br/>Perseverante y fuerte, tal amor.<br/>Yo te maldije y escarnecí,<br/>Paciente orabas, orabas por mí.<br/>',NULL,196160,5);
INSERT INTO stanza VALUES('S2054','chorus','¿Por qué morir por mí?<br/>Yo Tu enemigo fui;<br/>Maldito Tú llegaste a ser.<br/>¡Qué gran misterio es,<br/>Que muera Dios por mí!<br/>Por mí quien Su enemigo fui.<br/>',NULL,196161,6);
INSERT INTO stanza VALUES('S2054','4','Un hombre de pecado fui,<br/>Pecaminoso sucio mi vivir.<br/>Mi corazón rebelde hacia Ti;<br/>Tocaste mi alma con Tu compasión.<br/>',NULL,196162,7);
INSERT INTO stanza VALUES('S2054','chorus','Tu amor me conquistó,<br/>Vencido hoy estoy;<br/>Viniste a mí con Tu amor.<br/>Nada antes me cambió,<br/>Pero Tu amor venció.<br/>¡Tu amor, Señor, me conquistó!<br/>',NULL,196163,8);
INSERT INTO stanza VALUES('S2054','5','Volví mi corazón a Ti,<br/>Estabas esperándome ahí.<br/>¿Podría aún Tu enemigo ser?<br/>No puedo,<br/>Tu amor, Jesús me ganó.<br/>',NULL,196164,9);
INSERT INTO stanza VALUES('S2054','chorus','Tu amor me conquistó,<br/>Vencido hoy estoy;<br/>Viniste a mí con Tu amor.<br/>Nada antes me cambió,<br/>Pero Tu amor venció.<br/>¡Tu amor, Señor, me conquistó!<br/>',NULL,196165,10);
INSERT INTO stanza VALUES('S2054','YouTube Link','https://www.youtube.com/watch?v=kYTkntj6GPQ',NULL,196166,11);
INSERT INTO stanza VALUES('S2055','1','Cosas que antes gané,<br/>Pérdidas ahora son.<br/>Jesús me liberó<br/>De lo que fui.<br/>Y toda posesión,<br/>Lo bueno o malo igual,<br/>Todo es basura<br/>Para a Cristo ganar.<br/>',NULL,196167,1);
INSERT INTO stanza VALUES('S2055','chorus','No pararé *¡NO!*<br/>Voy a correr<br/>Hasta poder alcanzar<br/>La meta suprema.<br/>He de seguir, *¡SÍ!*<br/>Proseguiré<br/>Hasta asirme de Él,<br/>Quien me capturó.<br/>',NULL,196168,2);
INSERT INTO stanza VALUES('S2055','2','El pasado olvidar,<br/>En pos de Él seguir.<br/>Correr pensando en esto:<br/>¡Hoy quiero más!<br/>Buscar crecer en Él,<br/>Y conocerle más,<br/>Así hallado en Él<br/>Siempre seré.<br/>',NULL,196169,3);
INSERT INTO stanza VALUES('S2056','1','Recuérdame,<br/>Por qué vivo y respiro yo.<br/>Recuérdame,<br/>Que por Tu plan un vaso soy.<br/>Recuérdame,<br/>Que nada puedo hacer sin Ti.<br/>¡Vive Tu por mí!<br/>',NULL,196170,1);
INSERT INTO stanza VALUES('S2056','2','Perdón, Señor,<br/>Por buscar cosas fuera de Ti.<br/>Perdón, Señor,<br/>Si el primer amor yo no te di.<br/>Perdón, Señor,<br/>Tanto te reemplaza a Ti.<br/>¡Trátalo, Señor!<br/>',NULL,196171,2);
INSERT INTO stanza VALUES('S2056','3','Susténtame,<br/>Para correr en pos de Ti.<br/>Susténtame,<br/>Hasta poseerte por completo.<br/>Susténtame,<br/>Alimentándome de Ti.<br/>¡Cada día, Señor!<br/>',NULL,196172,3);
INSERT INTO stanza VALUES('S2056','4','Te amo, Señor,<br/>Mas tienes que enseñarme aún.<br/>Te amo, Señor,<br/>Aunque al no verte esto me cueste.<br/>Te amo, Señor,<br/>Aún quiero amarte mucho más.<br/>¡Solo te amo a Ti!<br/>',NULL,196173,4);
INSERT INTO stanza VALUES('S2056','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/recuerdame-porque-respiro-y-vivo-yo-remind-me-lord',NULL,196174,5);
INSERT INTO stanza VALUES('S2057','1','La vida es Dios,<br/>Mi vida no es vida sin Él.<br/>Es luz y amor,<br/>Es justicia y santidad.<br/>Jesús siempre será,<br/>La vida para mí,<br/>A Él conoceré,<br/>Le experimentaré.<br/>',NULL,196175,1);
INSERT INTO stanza VALUES('S2057','2','La vida de Dios<br/>Divina, indestructible es,<br/>Eterna, increada<br/>Dios mismo esta vida es.<br/>Nos hace conquistar,<br/>Y nos lleva a expresar,<br/>En nosotros a Dios,<br/>Hasta el madurar.<br/>',NULL,196176,2);
INSERT INTO stanza VALUES('S2057','SoundCloud Link','https://soundcloud.com/christiancandia/la-vida-es-dios',NULL,196177,3);
INSERT INTO stanza VALUES('S2058','1','Quiero estar en Ti,<br/>Tal como Tú en mí,<br/>Quiero en Ti, Señor,<br/>Permanecer.<br/>Somos uno aquí:<br/>Tú en mí, yo en Ti.<br/>¡Qué unión Señor!<br/>¡Qué hermosa entidad!<br/>',NULL,196178,1);
INSERT INTO stanza VALUES('S2058','chorus','Dios se imparte<br/>En Su Trinidad,<br/>Conforme a Su plan.<br/>Él infunde y Él mezcla<br/>Lo que Él es en mí.<br/>',NULL,196179,2);
INSERT INTO stanza VALUES('S2058','2','Soy un pámpano,<br/>Tú eres la vid,<br/>Mientras viva en Ti<br/>Hay descanso y paz.<br/>Siempre aquí, Señor,<br/>Yo quiero estar.<br/>Aquí Tuyo soy,<br/>Mío eres Tú.<br/>',NULL,196180,3);
INSERT INTO stanza VALUES('S2058','3','Soy un pámpano<br/>Injertado en Ti,<br/>Soy suplido en<br/>Esta unión vital.<br/>Fluye en mí, Señor,<br/>Tu rico Ser.<br/>Al morar en Ti,<br/>Yo creceré.<br/>',NULL,196181,4);
INSERT INTO stanza VALUES('S2058','4','Al morar en Ti<br/>Y Tú en mí,<br/>Soy unido a Ti<br/>En verdad, Señor.<br/>Al estar en Ti<br/>Y Tú en mí,<br/>Nos mezclamos hoy<br/>En perfecta unión.<br/>',NULL,196182,5);
INSERT INTO stanza VALUES('S2058','5','Al amarte y<br/>Gozarme en Ti,<br/>El verbo de vida<br/>En mi serás.<br/>Tú oras en mí,<br/>yo oro en Ti,<br/>Mucho fruto en mí,<br/>Tú llevarás.<br/>',NULL,196183,6);
INSERT INTO stanza VALUES('S2058','6','Al vivir en Ti,<br/>Tú fluyes en mí,<br/>Y me llenarás<br/>Hasta desbordar.<br/>Somos uno aquí<br/>Y Tú expresión,<br/>Lleno gozo hay<br/>Al morar en Ti.<br/>',NULL,196184,7);
INSERT INTO stanza VALUES('S2058','chorus','# (No se repite el coro después de la última estrofa)<br/>',NULL,196185,8);
INSERT INTO stanza VALUES('S2058','YouTube Link','https://www.youtube.com/watch?v=hKvnICeBXpE',NULL,196186,9);
INSERT INTO stanza VALUES('S2059','chorus','Porque para mí el vivir es Cristo,<br/>Y ya no vivo yo,<br/>Mas vive Cristo en mí.<br/>Porque para mí el vivir es Cristo,<br/>Y ya no vivo yo,<br/>Mas vive Cristo en mí.<br/>',NULL,196187,1);
INSERT INTO stanza VALUES('S2059','1','Cuando Satanás viene<br/>Y me acusa a mí,<br/>Me hace dudar<br/>Que Cristo está en mi ser,<br/>Pero, la verdad que ahora vivo yo,<br/>Es que el Dios Triuno vive en mí.<br/>',NULL,196188,2);
INSERT INTO stanza VALUES('S2059','chorus','Porque para mí el vivir es Cristo,<br/>Y ya no vivo yo,<br/>Mas vive Cristo en mí.<br/>Porque para mí el vivir es Cristo,<br/>Y ya no vivo yo,<br/>Mas vive Cristo en mí.<br/>',NULL,196189,3);
INSERT INTO stanza VALUES('S2059','2','Antes yo creía en un Cristo objetivo,<br/>Que tenía barba<br/>Y muy bello Su exterior,<br/>Pero ahora dentro de mí Él vive,<br/>Como el Espíritu.<br/>',NULL,196190,4);
INSERT INTO stanza VALUES('S2059','chorus','Porque para mí el vivir es Cristo,<br/>Y ya no vivo yo,<br/>Mas vive Cristo en mí.<br/>Porque para mí el vivir es Cristo,<br/>Y ya no vivo yo,<br/>Mas vive Cristo en mí.<br/>',NULL,196191,5);
INSERT INTO stanza VALUES('S2059','3','Porque el Señor se ha procesado,<br/>Fuente de amor, Dios en Cristo está.<br/>Como la gracia para disfrutar,<br/>Espíritu de vida en mí.<br/>',NULL,196192,6);
INSERT INTO stanza VALUES('S2059','chorus','Porque para mí el vivir es Cristo,<br/>Y ya no vivo yo,<br/>Mas vive Cristo en mí.<br/>Porque para mí el vivir es Cristo,<br/>Y ya no vivo yo,<br/>Mas vive Cristo en mí.<br/>',NULL,196193,7);
INSERT INTO stanza VALUES('S2059','YouTube Link','https://www.youtube.com/watch?v=ykZIbrhP_FA',NULL,196194,8);
INSERT INTO stanza VALUES('S2060','1','Yo creí, yo creí<br/>Yo creí, por tanto hablé.<br/>Yo creí, yo creí<br/>Yo creí, por tanto hablé.<br/>',NULL,196195,1);
INSERT INTO stanza VALUES('S2060','2','Salte de tu mente dudosa<br/>Y vuelve<br/>A tu espíritu mezclado de fe.<br/>Contacta al Espíritu<br/>En tu interior,<br/>Pues Él mismo es tu proceder.<br/>',NULL,196196,2);
INSERT INTO stanza VALUES('S2060','3','Habla la verdad<br/>Y lleno serás.<br/>Vida a ministrar,<br/>Para edificar.<br/>',NULL,196197,3);
INSERT INTO stanza VALUES('S2060','SoundCloud Link','https://soundcloud.com/damarisleg/yo-crei-i-believed?in=oralia-hern-ndez/sets/amaras-al-senor',NULL,196198,4);
INSERT INTO stanza VALUES('S2061','1','Nada‿es más precioso<br/>Que Él en mi espíritu,<br/>Cuida siempre de mí<br/>Me llena con Su paz.<br/>Nunca‿Él me deja,<br/>Aunque‿el día‿esté‿oscuro,<br/>Cristo‿está siempre‿en mí<br/>Mi alma se deleita en Él.<br/>',NULL,196199,1);
INSERT INTO stanza VALUES('S2061','chorus','Y clamo‿a Él:<br/>“¡Señor, ayúdame, soy débil!”<br/>Y es tan fiel, siempre‿hallo<br/>Que Su vida es suficiente.<br/>',NULL,196200,2);
INSERT INTO stanza VALUES('S2061','2','Nada‿es más precioso<br/>Que Él en mi espíritu;<br/>Quiere mi corazón<br/>Para yo‿así gozar.<br/>Nada‿hago yo,<br/>Su gracia‿es sobre mí.<br/>Y Su‿inefable don<br/>Es gozo‿eterno para mí.<br/>',NULL,196201,3);
INSERT INTO stanza VALUES('S2061','chorus','Y clamo‿a Él:<br/>“¡Señor, ayúdame, soy débil!”<br/>Y es tan fiel, siempre‿hallo<br/>Que Su vida es suficiente.<br/>',NULL,196202,4);
INSERT INTO stanza VALUES('S2061','chorus','(Final: Se canta hasta la mitad de la segunda estrofa)<br/>',NULL,196203,5);
INSERT INTO stanza VALUES('S2061','SoundCloud Link','https://soundcloud.com/user-268559970/nada-es-mas-precioso',NULL,196204,6);
INSERT INTO stanza VALUES('S2062','1','Dios al hombre creó,<br/>Con un espíritu<br/>Para que él fuese Su expresión.<br/>Más el hombre cayó,<br/>Y se corrompió;<br/>Esto no detuvo el plan de Dios.<br/>',NULL,196205,1);
INSERT INTO stanza VALUES('S2062','2','Los días de Noé,<br/>Llenos de maldad;<br/>Dios dispuso<br/>Al hombre eliminar.<br/>Pero Noé halló,<br/>Gracia ante su Dios;<br/>Dios a él abrió Su corazón.<br/>',NULL,196206,2);
INSERT INTO stanza VALUES('S2062','chorus','¡Oh, Señor Jesús!<br/>¡Oh, Señor Jesús!<br/>Quiero ante Tus ojos<br/>Hoy la gracia hallar.<br/>Uno ser contigo,<br/>Y esta era consumar.<br/>',NULL,196207,3);
INSERT INTO stanza VALUES('S2062','3','El arca construyó,<br/>De brea la cubrió,<br/>De tres pisos él la edificó.<br/>Una ventana allí, para luz recibir,<br/>Y una puerta para en ella entrar.<br/>',NULL,196208,4);
INSERT INTO stanza VALUES('S2062','4','La iglesia el arca es,<br/>Ella cubierta está<br/>Por la sangre de nuestro Señor.<br/>La puerta Cristo es,<br/>Sólo hay una visión,<br/>Y el Dios Triuno unido en ella está.<br/>',NULL,196209,5);
INSERT INTO stanza VALUES('S2062','chorus','¡Oh, Señor Jesús!<br/>¡Oh, Señor Jesús!<br/>Quiero ante Tus ojos<br/>Hoy la gracia hallar.<br/>Uno ser contigo,<br/>Y esta era consumar.<br/>',NULL,196210,6);
INSERT INTO stanza VALUES('S2062','5','Quiero Tu gracia hallar,<br/>Y en el arca entrar.<br/>Quiero ser como Noé, Señor.<br/>La iglesia edificar<br/>Y en la visión andar<br/>Y esta era vamos a cambiar.<br/>',NULL,196211,7);
INSERT INTO stanza VALUES('S2062','chorus','¡Oh, Señor Jesús!<br/>¡Oh, Señor Jesús!<br/>Quiero ante Tus ojos<br/>hoy la gracia hallar.<br/>Uno ser contigo,<br/>Y esta era consumar.<br/>',NULL,196212,8);
INSERT INTO stanza VALUES('S2063','1','Creyentes,<br/>Nos designa Él.<br/>Vivimos y caminamos por fe,<br/>Dependiendo de Él.<br/>',NULL,196213,1);
INSERT INTO stanza VALUES('S2063','2','A quién amáis<br/>Sin haberle visto aún;<br/>Maravilla y gran misterio es<br/>El creer en Jesús.<br/>',NULL,196214,2);
INSERT INTO stanza VALUES('S2063','chorus','Somos creyentes,<br/>Gozo inefable es.<br/>Somos creyentes,<br/>Gozo inefable es.<br/>',NULL,196215,3);
INSERT INTO stanza VALUES('S2063','3','Señor Jesús,<br/>Te amamos sólo a Ti.<br/>Te entregamos todo el corazón<br/>Para que hagas Tu hogar.<br/>',NULL,196216,4);
INSERT INTO stanza VALUES('S2063','4','Edifícanos<br/>Y úsanos en Tu mover,<br/>Para que en nuestro diario andar<br/>Te puedas expresar.<br/>',NULL,196217,5);
INSERT INTO stanza VALUES('S2063','chorus','Somos creyentes,<br/>Gozo inefable es.<br/>Somos creyentes,<br/>Gozo inefable es.<br/>',NULL,196218,6);
INSERT INTO stanza VALUES('S2063','chorus','3+4: *Estrofas adicionales*<br/>',NULL,196219,7);
INSERT INTO stanza VALUES('S2063','SoundCloud Link','https://soundcloud.com/moliniano/somos-creyentes',NULL,196220,8);
INSERT INTO stanza VALUES('S2064','1','Nos diste espíritu<br/>Para entrar en nos,<br/>Siendo desde allí<br/>Nuestro suplir.<br/>Desde mi espíritu,<br/>Fluyes oh Señor,<br/>Para que te puedas expresar.<br/>',NULL,196221,1);
INSERT INTO stanza VALUES('S2064','chorus','¡Oh Señor Jesús!<br/>¡Oh Señor Jesús!<br/>Tu nombre nos unge,<br/>Como ungüento que<br/>Nos imparte Tu vida<br/>Tu muerte y resurrección.<br/>',NULL,196222,2);
INSERT INTO stanza VALUES('S2065','1','Fuimos esclavos en cautividad,<br/>Bajo la usurpación de Faraón,<br/>Y Dios nos llamó.<br/>Al pasar el mar,<br/>Fuimos bautizados por Dios.<br/>Al desierto fue guiado el pueblo<br/>A Mara y Elim.<br/>',NULL,196223,1);
INSERT INTO stanza VALUES('S2065','chorus','Somos creyentes,<br/>¡Gozo inefable es!<br/>Somos creyentes,<br/>¡Gozo inefable es!<br/>',NULL,196224,2);
INSERT INTO stanza VALUES('S2065','2','Al desierto a Su pueblo llevó,<br/>Y maná desde el cielo cayó,<br/>Y su dieta cambió.<br/>Dieta celestial para disfrutar<br/>Desde la mañana y comer<br/>Al Señor como pan.<br/>',NULL,196225,3);
INSERT INTO stanza VALUES('S2065','3','Oh Señor quieres<br/>Que a Ti venga a beber.<br/>Llámame cuando seco este<br/>Y a la roca iré.<br/>Tú, lléname de la roca herida hoy,<br/>Fluye en mí y así a otros llenar<br/>Con Tu agua eternal.<br/>',NULL,196226,4);
INSERT INTO stanza VALUES('S2065','SoundCloud Link','https://soundcloud.com/user-871371384/fuimos-esclavos-en-cautividad',NULL,196227,5);
INSERT INTO stanza VALUES('S2066','1','Señor Jesús, voy a expresarte<br/>A Tu imagen<br/>Y cumplir Tu bello plan.<br/>Primogénitos como sacerdotes,<br/>Para expresar a Dios a Su imagen.<br/>Y como reyes en Tu dominio,<br/>Representarte y tomar la posesión.<br/>',NULL,196228,1);
INSERT INTO stanza VALUES('S2066','chorus','Quiero reinar bajo autoridad,<br/>Contigo por toda la eternidad.<br/>No me dejes que me aleje,<br/>Contigo quiero estar.<br/>',NULL,196229,2);
INSERT INTO stanza VALUES('S2066','2','La buena tierra, nuestra doble porción<br/>Asignada como la herencia de Dios,<br/>La disfrutamos en nuestro espíritu.<br/>¡Qué abundantes las riquezas del Señor!<br/>Invocó Jabes al Dios de Israel:<br/>¡Que Tu mano permanezca sobre mí!<br/>',NULL,196230,3);
INSERT INTO stanza VALUES('S2066','chorus','Tal como Ruth,<br/>Queremos escoger:<br/>Tu vida Señor y así poder crecer.<br/>Donde vayas, yo te seguiré,<br/>Por siempre, Te amaré.<br/>',NULL,196231,4);
INSERT INTO stanza VALUES('S2066','3','Todos nosotros podemos conquistar,<br/>Subyugar y gobernar a Satanás.<br/>No hay nada más precioso<br/>Que ser semillas del evangelio hoy.<br/>Somos sal de esta tierra<br/>Y contra la corrupción poder luchar.<br/>',NULL,196232,5);
INSERT INTO stanza VALUES('S2066','chorus','Quiero reinar bajo autoridad,<br/>Contigo por toda la eternidad.<br/>No me dejes que me aleje,<br/>Contigo quiero estar.<br/>',NULL,196233,6);
INSERT INTO stanza VALUES('S2066','SoundCloud Link','https://soundcloud.com/user-871371384/senor-jesus-voy-a-expresarte',NULL,196234,7);
INSERT INTO stanza VALUES('S2067','1','¿Viste tú la Salvación?<br/>¿Has sentido Su provisión?<br/>¿Viste la victoria de Su muerte?<br/>¿Has entrado en el reino de Dios?<br/>¿Has entrado en el reino de Dios?<br/>',NULL,196235,1);
INSERT INTO stanza VALUES('S2067','chorus','¿Has subido al monte?<br/>¿Estás en la luz?<br/>¿Has cambiado tu dieta?<br/>¿Has comido a Dios?<br/>',NULL,196236,2);
INSERT INTO stanza VALUES('S2067','2','¿Pasas tiempo en Su presencia?<br/>¿Tú conoces Su intención?<br/>Para hacernos iguales a Él<br/>Y siempre amarle a Él.<br/>Y siempre amarle a Él<br/>',NULL,196237,3);
INSERT INTO stanza VALUES('S2067','chorus','¿Has subido al monte?<br/>¿Estás en la luz?<br/>¿Has cambiado tu dieta?<br/>¿Has comido a Dios?<br/>',NULL,196238,4);
INSERT INTO stanza VALUES('S2067','3','¿Buscador, amante tú eres?<br/>No guardemos la ley muerta.<br/>Día a día Su Palabra leer.<br/>Infúndete hoy, Señor.<br/>Oraremos hoy, Señor.<br/>',NULL,196239,5);
INSERT INTO stanza VALUES('S2067','chorus','¿Has subido al monte?<br/>¿Estás en la luz?<br/>¿Has cambiado tu dieta?<br/>¿Has comido a Dios?<br/>',NULL,196240,6);
INSERT INTO stanza VALUES('S2067','4','¿Estás tú en Su recobro?<br/>¿Conoces la gran historia?<br/>Es la mezcla del hombre y Dios.<br/>El propósito de Su plan.<br/>El propósito de Su plan.<br/>',NULL,196241,7);
INSERT INTO stanza VALUES('S2067','chorus','He subido al monte,<br/>Estoy en la luz.<br/>He cambiado mi dieta,<br/>He comido a Dios.<br/>',NULL,196242,8);
INSERT INTO stanza VALUES('S2067','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2067_viste-tu-la-salvacio-n',NULL,196243,9);
INSERT INTO stanza VALUES('S2068','1','¡Qué preciosa es<br/>Nuestra primogenitura:<br/>La doble porción de la buena tierra,<br/>Y reyes, sacerdotes hoy ser!<br/>Cada día a Cristo experimentamos<br/>Y en intimidad le disfrutamos,<br/>Jesucristo es nuestra porción.<br/>',NULL,196244,1);
INSERT INTO stanza VALUES('S2068','chorus','No la vendas por nada.<br/>Todo el que la disfrute,<br/>La obtendrá en el milenio.<br/>Galardón, galardón, del Juez justo.<br/>',NULL,196245,2);
INSERT INTO stanza VALUES('S2068','2','Ser los que expresan a Dios<br/>En Su imagen,<br/>Representan a Dios en Su dominio,<br/>Toman la tierra para Dios.<br/>Más debemos conservar nuestro sabor,<br/>Ser luminares hoy en la tierra,<br/>Semillas que la vida dan.<br/>',NULL,196246,3);
INSERT INTO stanza VALUES('S2068','3','¡Oh Señor, bendíceme con Tu sonrisa!<br/>Te ruego que mi territorio ensanches,<br/>Sobre mí, Tu mano mantén.<br/>Líbrame del mal para que no me dañe.<br/>Hoy vuelvo a Ti mi corazón, Señor,<br/>¡Nada es más precioso que Tú!<br/>',NULL,196247,4);
INSERT INTO stanza VALUES('S2069','1','Muertos en pecado estábamos;<br/>Esclavos todos a un destino atroz.<br/>¿Cómo salvos de este mundo hemos de ser?<br/>',NULL,196248,1);
INSERT INTO stanza VALUES('S2069','chorus','Invocándole:<br/>¡Oh, Jesús, Jesús!<br/>Cada momento a Él.<br/>Invocándole: ¡Jesús!<br/>¡Oh, qué manera es!<br/>¡Jesús! ¡Señor Jesús!<br/>',NULL,196249,2);
INSERT INTO stanza VALUES('S2069','2','Aunque tanto amamos al Señor,<br/>Parece no le damos atención.<br/>¿Cómo salvos de esta angustia<br/>hemos de ser?<br/>',NULL,196250,3);
INSERT INTO stanza VALUES('S2069','3','A veces no somos auténticos,<br/>Vivimos sólo por la emoción.<br/>¿Cuál es la manera de tratar<br/>al yo?<br/>',NULL,196251,4);
INSERT INTO stanza VALUES('S2069','4','Muchos salvos en el mundo hay<br/>Que vagan; ¿dónde está la unidad?<br/>¿Cómo hoy Tu novia ganarás,<br/>Señor?<br/>',NULL,196252,5);
INSERT INTO stanza VALUES('S2069','YouTube Link','https://www.youtube.com/watch?v=u3jz2D3abVY',NULL,196253,6);
INSERT INTO stanza VALUES('S2070','1','Amo a Dios,<br/>Porque mucho antes<br/>De la creación me amó.<br/>Amo a Dios,<br/>Pues mi destino Él conoció.<br/>Amo a Dios,<br/>Porque me hizo parte<br/>De Su eterno plan.<br/>Yo le amo,<br/>Pues primero Él me amó.<br/>',NULL,196254,1);
INSERT INTO stanza VALUES('S2070','chorus','Le amo por lo que<br/>Ha hecho Él por mí.<br/>Le amo por todo lo que Él es,<br/>Lo que Él es para mí.<br/>Y más aún,<br/>Le amo como Espíritu<br/>Que en el mío vive hoy.<br/>',NULL,196255,2);
INSERT INTO stanza VALUES('S2070','2','Amo a Dios,<br/>Porque en el tiempo<br/>Hijo de Hombre vino a ser.<br/>Amo a Dios,<br/>Porque vino a morir por mí.<br/>Amo a Dios,<br/>Triunfó sobre la muerte<br/>Y tengo vida hoy.<br/>Yo le amo,<br/>Pues primero Él me amó.<br/>',NULL,196256,3);
INSERT INTO stanza VALUES('S2070','3','Amo a Dios,<br/>Porque Él se procesó<br/>Para mi vida ser.<br/>Amo a Dios,<br/>Porque transformándome está.<br/>Amo a Dios,<br/>Porque edifica la Nueva Jerusalén.<br/>Yo le amo,<br/>Pues aún me ama Él.<br/>',NULL,196257,4);
INSERT INTO stanza VALUES('S2070','SoundCloud Link','https://soundcloud.com/user-976102747/amo-a-dios',NULL,196258,5);
INSERT INTO stanza VALUES('S2071','1','Espíritu de luz,<br/>Que me iluminó.<br/>Que todo mi ser<br/>De Él se llenó,<br/>Y en mi espíritu se impregnó.<br/>',NULL,196259,1);
INSERT INTO stanza VALUES('S2071','chorus','El Señor me vivificó,<br/>Me vivificó,<br/>Pues en mi espíritu<br/>Vida impartió;<br/>Y me unió en uno con Él,<br/>En uno con Él.<br/>El Dios divino<br/>Me llenó de Él.<br/>',NULL,196260,2);
INSERT INTO stanza VALUES('S2071','2','Su Cuerpo el Señor<br/>Me reveló.<br/>Con santos en luz<br/>Su amor me cuidó.<br/>El Dios Triuno me cautivó.<br/>',NULL,196261,3);
INSERT INTO stanza VALUES('S2072','1','Espíritu vivificante,<br/>Hoy, Cristo el Espíritu es.<br/>Espíritu vivificante,<br/>Por eso yo me vuelvo a Él.<br/>',NULL,196262,1);
INSERT INTO stanza VALUES('S2072','chorus','Señor, Amén,<br/>Señor, Amén, aleluya.<br/>Señor, Amén,<br/>Señor, Amén, aleluya.<br/>',NULL,196263,2);
INSERT INTO stanza VALUES('S2072','2','Espíritu vivificante,<br/>Palabra viviente es también,<br/>Y para que en mí ella fluya,<br/>Lo siguiente tengo que hacer:<br/>',NULL,196264,3);
INSERT INTO stanza VALUES('S2072','chorus','Orar, leer,<br/>Clamar Su nombre<br/>¡Señor Jesús!<br/>Orar, leer,<br/>Y alabar al Señor.<br/>',NULL,196265,4);
INSERT INTO stanza VALUES('S2072','SoundCloud Link','https://soundcloud.com/user-581404845/espiritu-vivificante',NULL,196266,5);
INSERT INTO stanza VALUES('S2073','1','El Señor el Espíritu es,<br/>Y por eso puede entrar en ti.<br/>Es muy simple ser lleno de Él,<br/>Nos lo ha hecho muy fácil.<br/>Un, dos, tres,<br/>Tienes que invocarle_así:<br/>',NULL,196267,1);
INSERT INTO stanza VALUES('S2073','chorus','¡Señor! Amén!<br/>Así yo le dejo entrar.<br/>Aleluya, me encanta oírlo,<br/>¡Con el Señor Jesús ahora soy uno!<br/>',NULL,196268,2);
INSERT INTO stanza VALUES('S2073','2','El Señor aire de vida es;<br/>Puedes respirarle por doquier.<br/>Cuando quieras lo puedes hacer,<br/>Nos lo ha puesto muy fácil:<br/>¡Señor! ¡Amén! Cántalo otra vez.<br/>',NULL,196269,3);
INSERT INTO stanza VALUES('S2073','3','Para siempre el Señor vive en mí,<br/>Y me llena hasta rebosar.<br/>Él satura así cada rincón.<br/>¡Oh, qué feliz me hace!<br/>¡Qué contento!<br/>¡Aleluya, prueba y ve!<br/>',NULL,196270,4);
INSERT INTO stanza VALUES('S2074','1','Tengo͜ un río de vida<br/>Fluyendo͜ en mí<br/>Que͜ hace͜ al cojo͜͜ andar<br/>Y al ciego ver.<br/>Abre la prisión y libera͜͜ así.<br/>Tengo͜ un río de vida<br/>Fluyendo͜ en mí.<br/>',NULL,196271,1);
INSERT INTO stanza VALUES('S2074','chorus','¡Brota͜ en mi͜ espíritu, oh fuente!<br/>Proclama͜͜ así:<br/>(¡Señor!) que todos oigan.<br/>Que͜ en abundancia experimente<br/>La vida que brota͜ en mí.<br/>',NULL,196272,2);
INSERT INTO stanza VALUES('S2074','2','Tengo͜ un río de vida<br/>Fluyendo͜ en mí;<br/>Al librarme Dios,<br/>Comenzó ͜ a surgir.<br/>“Haz que yo mantenga ese fluir”.<br/>Tengo͜ un río de vida<br/>Brotando͜ en mí;<br/>',NULL,196273,3);
INSERT INTO stanza VALUES('S2074','3','Cuando yo le͜ invoco hay͜ un fluir<br/>Que me vuelve a Él y lo hace Rey.<br/>Al clamar: “¡Señor!”,<br/>Mantengo͜ el fluir,<br/>Y al enemigo podré resistir.<br/>',NULL,196274,4);
INSERT INTO stanza VALUES('S2074','SoundCloud Link','https://soundcloud.com/valen_torres/brota-en-mi-espi-ritu-oh',NULL,196275,5);
INSERT INTO stanza VALUES('S2075','1','Aguas profundas<br/>Donde puedo nadar,<br/>Aguas que suplen<br/>Hoy mi necesidad;<br/>La gracia viviente<br/>Restringe mi vivir,<br/>La vida de mi alma<br/>Puede sustituir.<br/>',NULL,196276,1);
INSERT INTO stanza VALUES('S2075','chorus','(Hermanas)Bebe el agua viva,<br/>(Hermanos)¡Fluye el río aquí!<br/>(Hermanas)¡Aguas! ¡Aguas vivas!<br/>(Hermanos)¡Operan en mí!<br/>Creciendo en vida,<br/>Bebiendo a Cristo así,<br/>¡Para Su recobro y Su edificio aquí!<br/>',NULL,196277,2);
INSERT INTO stanza VALUES('S2075','2','Fluye hacia el este<br/>El agua del Señor,<br/>Hacia la gloria<br/>Que en Cristo busco yo;<br/>Preeminencia tiene<br/>En mi vida y obrar,<br/>De la vida de iglesia<br/>No me quiero marchar.<br/>',NULL,196278,3);
INSERT INTO stanza VALUES('S2075','3','Capa tras capa<br/>El agua aumentará,<br/>Fluye y aumenta<br/>Hasta la era cambiar;<br/>Juzgando, probando,<br/>Su vida aumentará,<br/>Hasta que todo hombre<br/>Su nombre alabará.<br/>',NULL,196279,4);
INSERT INTO stanza VALUES('S2075','SoundCloud Link','https://soundcloud.com/user-518979615/aguas-profundas-donde-puedo-nadar',NULL,196280,5);
INSERT INTO stanza VALUES('S2076','1','Ven a la fiesta si hambriento estás.<br/>Ábrete a Cristo y Él te llenará.<br/>Alimentó a una multitud.<br/>Sólo abre tu boca y recíbele,<br/>También comerás tú.<br/>Hemos visto<br/>Que al invocarle nos llenará.<br/>Si Él es comida, ¡pues cómetela!<br/>Formas y doctrinas<br/>No has de aprender<br/>Para reunirte aquí.<br/>¡Disfruta al Señor Jesús!<br/>',NULL,196281,1);
INSERT INTO stanza VALUES('S2076','2','Si tienes sed, Él te escuchará.<br/>Él es la fuente que no se secará.<br/>Nos satisfizo, todo suplió.<br/>Comiendo y bebiendo al Señor Jesús,<br/>Por eso es que Él murió;<br/>Luego se hizo el Espíritu,<br/>Al nuestro entró,<br/>¡Oh, qué glorioso! Mi ser ya lo llenó.<br/>Es súper sencillo: sólo comer;<br/>Sólo eso has de hacer tú.<br/>¡Disfruta al Señor Jesús!<br/>',NULL,196282,2);
INSERT INTO stanza VALUES('S2076','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2076-ven-a-la-fiesta-m4a',NULL,196283,3);
INSERT INTO stanza VALUES('S2077','1','Jesús ha liberado<br/>A todos los que creen en Él.<br/>No hay esclavitud<br/>Vida liberadora<br/>Te da Jesús ahora<br/>Clama a Él, salvo sé.<br/>',NULL,196284,1);
INSERT INTO stanza VALUES('S2077','chorus','¡De jubileo este año es!<br/>¡Proclama libertad en Él!<br/>Por la tierra anunciamos:<br/>Pecado, cargas y ansiedad<br/>Ya no hay en Cristo;<br/>¡Libre en Él soy ya!<br/>¡De jubileo este año es!<br/>',NULL,196285,2);
INSERT INTO stanza VALUES('S2077','2','Obten la buena tierra,<br/>Dios nuestra rica posesión<br/>¡Festeja en Él!<br/>Disfruta en Su familia,<br/>¡Paz y satisfacción<br/>Aquí siempre encontrarás!<br/>',NULL,196286,3);
INSERT INTO stanza VALUES('S2077','SoundCloud Link','https://soundcloud.com/damarisleg/jesus-ha-liberado-the-lord-has-give-us-freedom',NULL,196287,4);
INSERT INTO stanza VALUES('S2078','1','¿Qué de mi pasado atroz?<br/>Mi conciencia, sin cesar,<br/>Me acusa de pecar.<br/>No hay paz en mi ser;<br/>Condenado estoy.<br/>',NULL,196288,1);
INSERT INTO stanza VALUES('S2078','2','¡Qué miseria es vivir,<br/>En un mundo sin amor!<br/>Yo buscaba gozo y paz;<br/>Encontré vanidad, sólo vanidad.<br/>',NULL,196289,2);
INSERT INTO stanza VALUES('S2078','chorus','Dios, lejos estabas Tú,<br/>Qué supremo y celestial;<br/>Más vestiste de humanidad,<br/>Fuiste por mí<br/>Hasta la cruz,<br/>Para sangrar por mí.<br/>',NULL,196290,3);
INSERT INTO stanza VALUES('S2078','chorus','Por eso le amo y fiel le adoro a Él.<br/>Por eso doy mi vida y todo a Él.<br/>Por eso le amo y fiel le adoro a Él.<br/>Por eso doy mi vida y todo a Él.<br/>',NULL,196291,4);
INSERT INTO stanza VALUES('S2078','YouTube Link','https://www.youtube.com/watch?v=x6atVaTYUK4',NULL,196292,5);
INSERT INTO stanza VALUES('S2079','1','Hay un evangelio hoy<br/>Que dice: “cree y salvo tú serás,<br/>Luego irás al cielo a ver las perlas y<br/>Por calles de oro andarás”<br/>(Estas palabras)<br/>Sólo exaltan a vanidad<br/>Que está escondida en mí.<br/>',NULL,196293,1);
INSERT INTO stanza VALUES('S2079','2','Pero el evangelio es<br/>El Dios Triuno en la humanidad,<br/>Viene como Espíritu y es en mí<br/>La única realidad.<br/>(Gran amor:)<br/>Tú eres el evangelio hoy<br/>¡Bella historia eterna es!<br/>',NULL,196294,2);
INSERT INTO stanza VALUES('S2079','3','Las noventa y nueve dejó<br/>En busca de la que se le perdió<br/>Me cargó en Sus hombros,<br/>Él me lleva y cuida<br/>Con Su grande y tierno amor.<br/>(Con gozo)<br/>Me encontraste aunque pequeño soy,<br/>Tú dejaste todo por mí.<br/>',NULL,196295,3);
INSERT INTO stanza VALUES('S2079','4','Barres en mi corazón<br/>La lámpara enciendes para buscar.<br/>Al santificarme, Tú me iluminas<br/>Y me expones de mis pecados;<br/>(Arrepentido)<br/>Hoy yo veo que Él me rocía<br/>Con la sangre que vertió.<br/>',NULL,196296,4);
INSERT INTO stanza VALUES('S2079','5','Con anhelo esperas Tú<br/>A que yo pueda a Ti, oh Padre volver.<br/>Aunque he vivido en la ruina,<br/>Tú corres y te echas sobre mí.<br/>(Con afecto)<br/>Tú me besas, matas el becerro<br/>Y haces fiesta por mí.<br/>',NULL,196297,5);
INSERT INTO stanza VALUES('S2079','SoundCloud Link','https://soundcloud.com/pablo-daniel-benitez-lezcano/hay-un-evangelio-hoy',NULL,196298,6);
INSERT INTO stanza VALUES('S2080','1','Si hablas la palabra,<br/>Él te llenará<br/>Por dentro y por fuera.<br/>Llena de poder,<br/>Autoridad e impacto -<br/>¡Fluirá!<br/>',NULL,196299,1);
INSERT INTO stanza VALUES('S2080','chorus','Canal de vida soy,<br/>¡Permito a Dios fluir!<br/>Dentro y fuera de mí,<br/>Así vida impartir.<br/>',NULL,196300,2);
INSERT INTO stanza VALUES('S2080','2','Tras recibir<br/>Tal suplir,<br/>¡Ser enriquecidos!<br/>Crean, salgan y hablen acerca de<br/>Esta vida.<br/>',NULL,196301,3);
INSERT INTO stanza VALUES('S2080','3','Teniendo espíritu de fe,<br/>¡Se fuerte y valiente!<br/>Por el Señor,<br/>Así también tu<br/>Puedes hablar.<br/>',NULL,196302,4);
INSERT INTO stanza VALUES('S2080','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2080_si-hablas-la-palabra-el',NULL,196303,5);
INSERT INTO stanza VALUES('S2081','1','Dejó Él Su gloria,<br/>Fue manso y humilde.<br/>Se hizo criatura quien<br/>La vida creó.<br/>Sufrió el abandono,<br/>Dolor, pena y burla,<br/>De gloria infinita,<br/>A sufrir desdén.<br/>',NULL,196304,1);
INSERT INTO stanza VALUES('S2081','2','Llegó a ser humilde,<br/>Y a estar limitado,<br/>Se hizo finito y es<br/>Un hombre en verdad.<br/>¡En Cristo el plan de Dios<br/>Se hizo tangible!<br/>Dos naturalezas:<br/>El Dios-hombre es Él.<br/>',NULL,196305,2);
INSERT INTO stanza VALUES('S2081','3','Liberó Su gloria<br/>Nos impartió vida,<br/>Y los muchos granos<br/>Él Logró producir.<br/>Se goza el primero con<br/>Sus muchos hermanos.<br/>Lo humano y divino en Él<br/>Se incorporaron.<br/>',NULL,196306,3);
INSERT INTO stanza VALUES('S2081','4','Por tanto hay que amarle.<br/>¡Pionero precioso!<br/>Son nuestra victoria hoy<br/>Su pena y dolor.<br/>A hijos de juicio,<br/>Hoy lleva a la gloria.<br/>Dios-hombres en miles,<br/>Se gozan con Él.<br/>',NULL,196307,4);
INSERT INTO stanza VALUES('S2081','SoundCloud Link','https://soundcloud.com/user-518979615/dejo-el-su-gloria1',NULL,196308,5);
INSERT INTO stanza VALUES('S2082','1','Si Dios te lleva_a_andar<br/>Por un camino que<br/>Tú conoces, esto<br/>No te beneficiará,<br/>Tanto como si Él Te llevara_a_andar<br/>Por uno que no conoces.<br/>Esto te fuerza_a tener<br/>Cientos y miles<br/>De conversaciones con Él,<br/>Resultando en un viaje<br/>Que es un eterno<br/>Memorial - entre tú y Él.<br/>',NULL,196309,1);
INSERT INTO stanza VALUES('S2082','chorus','Obras coleccionadas de Watchman Nee, vol. 7, Tomo No. 3<br/>',NULL,196310,2);
INSERT INTO stanza VALUES('S2082','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/si-dios-te-lleva-a-andar-if',NULL,196311,3);
INSERT INTO stanza VALUES('S2083','1','Las flores se caen<br/>Y la hierba se seca,<br/>Más la palabra de Dios<br/>Permanece siempre.<br/>',NULL,196312,1);
INSERT INTO stanza VALUES('S2083','2','Ciertamente no hay hombre<br/>Justo sobre la tierra,<br/>Que haga siempre el bien,<br/>Y que nunca peque.<br/>',NULL,196313,2);
INSERT INTO stanza VALUES('S2083','chorus','Y la vida no tiene<br/>Propósito alguno,<br/>Si Dios no vive en tu ser (x2).<br/>',NULL,196314,3);
INSERT INTO stanza VALUES('S2083','3','Hay caminos que al hombre<br/>Le parecen derechos,<br/>Más su final son Caminos de muerte.<br/>',NULL,196315,4);
INSERT INTO stanza VALUES('S2083','4','Más hay un camino,<br/>Un camino que es realidad,<br/>Que te puede dar vida,<br/>Es Jesucristo.<br/>',NULL,196316,5);
INSERT INTO stanza VALUES('S2083','chorus','Y la vida no tiene<br/>Propósito alguno,<br/>Si Dios no vive en tu ser. (x2)<br/>',NULL,196317,6);
INSERT INTO stanza VALUES('S2083','YouTube Link','https://www.youtube.com/watch?v=PZ2PZoXbK6o',NULL,196318,7);
INSERT INTO stanza VALUES('S2084','1','Cada día te amo más Señor,<br/>Este día te amo mucho más.<br/>Ya no puedo yo vivir sin Ti,<br/>Ya no puedo como antes seguir.<br/>',NULL,196319,1);
INSERT INTO stanza VALUES('S2084','2','Oh, esos años que pasé sin Ti,<br/>Me salvaste a punto de morir.<br/>Cuando veo el pasado hay,<br/>Lágrimas, dolor y soledad.<br/>',NULL,196320,2);
INSERT INTO stanza VALUES('S2084','chorus','Cada día te amo, aún más Señor;<br/>Este día yo te amo, mucho más Señor.<br/>',NULL,196321,3);
INSERT INTO stanza VALUES('S2084','3','Una inmensa sed dentro de mí,<br/>Me llevó a buscar satisfacción.<br/>Tantas cosas que he tratado yo,<br/>Me han dejado seco e infeliz.<br/>',NULL,196322,4);
INSERT INTO stanza VALUES('S2084','4','En la búsqueda de algo más,<br/>Siempre quise encontrarte a Ti.<br/>Como un ciego, mil cosas probé,<br/>Hasta que de Tu agua yo bebí.<br/>',NULL,196323,5);
INSERT INTO stanza VALUES('S2084','chorus','Cada día te amo, aún más Señor;<br/>Este día yo te amo, mucho más Señor.<br/>',NULL,196324,6);
INSERT INTO stanza VALUES('S2084','5','Mi interior llenaste Tú, Señor,<br/>Eres mi dulce satisfacción.<br/>Como Espíritu eres todo en mí,<br/>Y te mueves en mi espíritu.<br/>',NULL,196325,7);
INSERT INTO stanza VALUES('S2084','6','Gracias por entrar en mí, Señor;<br/>Cada día te extiendes en mi<br/>Haces Tu hogar en mi corazón,<br/>Llenando cada parte de mí.<br/>',NULL,196326,8);
INSERT INTO stanza VALUES('S2084','chorus','Cada día te amo, aún más Señor;<br/>Este día yo te amo, mucho más Señor.<br/>',NULL,196327,9);
INSERT INTO stanza VALUES('S2084','SoundCloud Link','https://soundcloud.com/pablo-suarez-acosta/yo-te-amo-cada-dia-mas',NULL,196328,10);
INSERT INTO stanza VALUES('S2085','1','Atráeme, Señor;<br/>Atráeme a Ti.<br/>De todo lo demás, Señor,<br/>Aléjame.<br/>',NULL,196329,1);
INSERT INTO stanza VALUES('S2085','2','Señor, este mundo<br/>Me hace caer,<br/>Contiendas y pecado<br/>En mi alrededor.<br/>',NULL,196330,2);
INSERT INTO stanza VALUES('S2085','3','Más yo te doy mi corazón,<br/>Quiero en Ti permanecer.<br/>Pues sólo cuando cerca estás,<br/>Conmigo todo está bien.<br/>',NULL,196331,3);
INSERT INTO stanza VALUES('S2085','4','Y aunque todo me salga bien,<br/>O todo vaya mal,<br/>No importa siempre y cuando hoy<br/>Gane más de Ti, Señor.<br/>',NULL,196332,4);
INSERT INTO stanza VALUES('S2085','5','Atráeme, Señor, atráeme a Ti.<br/>De todo lo demás, Señor,<br/>Aléjame, Señor.<br/>',NULL,196333,5);
INSERT INTO stanza VALUES('S2086','1','Yo fui creado para contener<br/>A Dios en mi‿espíritu<br/>Y así‿Él pueda fluir.<br/>Cuando mi ser abro a Él,<br/>Como la fuente fluye‿en mí<br/>Dándose Él a mí.<br/>',NULL,196334,1);
INSERT INTO stanza VALUES('S2086','chorus','Cuando tengo sed<br/>Te busco como el río.<br/>Oh, Tú te das a mí,<br/>Mi manantial vivo.<br/>',NULL,196335,2);
INSERT INTO stanza VALUES('S2086','2','Señor, te pido hoy perdón<br/>Por no‿haber permitido que<br/>Tú fluyas desde mí.<br/>Señor, hoy vengo hacia Ti<br/>Para que quites de mi ser<br/>Lo que te‿estorba‿a Ti.<br/>',NULL,196336,3);
INSERT INTO stanza VALUES('S2086','3','Soy un canal–vaso de<br/>Mi Señor Jesucristo<br/>Quiere moverse‿en mí.<br/>De mi‿interior ríos brotarán<br/>Para la‿iglesia‿edificar,<br/>Cumpliendo con Su plan.<br/>',NULL,196337,4);
INSERT INTO stanza VALUES('S2086','YouTube Link','https://www.youtube.com/watch?v=9JwueK7Vod8',NULL,196338,5);
INSERT INTO stanza VALUES('S2087','1','Dios eligió y predestinó<br/>Con el deseo de filiación,<br/>Para expresar su humanidad<br/>En nuestra vida, en nuestra vida.<br/>',NULL,196339,1);
INSERT INTO stanza VALUES('S2087','chorus','Mi Jesús Salvador,<br/>Nos redimió y regeneró.<br/>Él vendrá como un ladrón,<br/>Se llevará al vencedor.<br/>',NULL,196340,2);
INSERT INTO stanza VALUES('S2087','2','Mi ser está compuesto de tres partes:<br/>Alma, cuerpo, espíritu también.<br/>Quiero volver mi espíritu<br/>Cada día al Señor.<br/>',NULL,196341,3);
INSERT INTO stanza VALUES('S2087','3','En la caída se interrumpió el plan<br/>Porque pecamos contra Dios.<br/>Y poseemos tal naturaleza<br/>En nuestro ser interior.<br/>',NULL,196342,4);
INSERT INTO stanza VALUES('S2087','4','Dios efectúa una salvación<br/>Que es completa y eterna en nos.<br/>Nos capacita para que cumplamos<br/>Su propósito eterno.<br/>',NULL,196343,5);
INSERT INTO stanza VALUES('S2088','1','Mirando Tu vivir humano veo<br/>Que como esclavo viniste a servir;<br/>Y así cumplir con Su eterno deseo,<br/>Sumiso al Padre fuiste en Tu vivir.<br/>',NULL,196344,1);
INSERT INTO stanza VALUES('S2088','chorus','Tal como Tú, quiero llevar la vida,<br/>Dada a cumplir así Su eterno plan;<br/>Te entrego todo, sin buscar salida,<br/>Para que en mí, te puedas expresar.<br/>',NULL,196345,2);
INSERT INTO stanza VALUES('S2088','2','A diario encuentra en mí plena cabida,<br/>Que en todo Tú me puedas reemplazar;<br/>Reproduciendo en mí Tu misma vida,<br/>Para que te puedas magnificar.<br/>',NULL,196346,3);
INSERT INTO stanza VALUES('S2088','chorus','Tal como Tú, quiero llevar la vida,<br/>Dada a cumplir así Su eterno plan;<br/>Te entrego todo, sin buscar salida,<br/>Para que en mí, te puedas expresar.<br/>',NULL,196347,4);
INSERT INTO stanza VALUES('S2088','3','Haz de mi corazón el mejor suelo,<br/>Quita ansiedad, afán y corrupción;<br/>Libre de engaños te cedo el terreno,<br/>Replica en mí, Señor Tu corazón.<br/>',NULL,196348,5);
INSERT INTO stanza VALUES('S2088','chorus','Como un esclavo a Ti yo quiero darme,<br/>Para servirte fielmente hasta el fin;<br/>Y por amor deseo consagrarme,<br/>Declaro que libre no_he de salir.<br/>',NULL,196349,6);
INSERT INTO stanza VALUES('S2089','1','Hoy, Señor, te doy gracias<br/>Por Tu propósito eterno.<br/>Tú le diste al hombre<br/>Tu imagen y semejanza<br/>Para que el fuese Tu expresión<br/>Y Tu representación,<br/>Tal como Jacob,<br/>Tal como José.<br/>',NULL,196350,1);
INSERT INTO stanza VALUES('S2089','2','Tú le diste a José<br/>Una visión controladora.<br/>Su vivir fue excelente,<br/>Su andar lleno de vida.<br/>La visión que recibió lo controló; Señor,<br/>Quiero ser así:<br/>Ser un soñador, ¡dame tal visión!<br/>',NULL,196351,2);
INSERT INTO stanza VALUES('S2089','chorus','Quiero ser como José, Señor.<br/>Quiero ser también un soñador.<br/>Oh, prepárame para reinar,<br/>Para otros vida ministrar.<br/>',NULL,196352,3);
INSERT INTO stanza VALUES('S2089','3','José fue traicionado<br/>Y al final encarcelado.<br/>Como a él, Señor,<br/>Necesitas encarcelarme.<br/>Más yo sé que<br/>Tú_estarás conmigo allí;<br/>Tu presencia cerca a mí.<br/>Y yo debo hablar,<br/>Hablar la verdad.<br/>',NULL,196353,4);
INSERT INTO stanza VALUES('S2089','4','¡Cuán preciosa obediencia<br/>Se manifestó en José!<br/>Su voluntad fue ganada,<br/>Conquistada y encadenada.<br/>El relato de la vida de José<br/>Es una revelación,<br/>Del gobierno del, del Espíritu.<br/>',NULL,196354,5);
INSERT INTO stanza VALUES('S2089','chorus','Quiero ser como José, Señor.<br/>Quiero ser también un soñador.<br/>Oh, prepárame para reinar,<br/>Para otros vida ministrar.<br/>',NULL,196355,6);
INSERT INTO stanza VALUES('S2089','5','Tal como José,<br/>Tú nos pones hoy a prueba.<br/>Tú quieres revelarte,<br/>Más deseas que te vea.<br/>Quiero conocerte mi Señor,<br/>Hoy en toda situación,<br/>Quiero verte a Ti,<br/>Contemplarte a Ti.<br/>',NULL,196356,7);
INSERT INTO stanza VALUES('S2089','6','José fue entronado<br/>Y reinó sobre la tierra.<br/>Se negó a sí mismo<br/>Y nunca buscó venganza,<br/>Restringido fue José para reinar,<br/>Para vida preservar;<br/>Quiero ser así, perfeccióname.<br/>',NULL,196357,8);
INSERT INTO stanza VALUES('S2089','chorus','Quiero ser como José, Señor.<br/>Quiero ser también un soñador.<br/>Oh, prepárame para reinar,<br/>Para otros vida ministrar.<br/>',NULL,196358,9);
INSERT INTO stanza VALUES('S2089','7','Por los sufrimientos<br/>Se llenó del suministro,<br/>Para obtenerlo<br/>Hay que pagar un alto precio.<br/>Se requiere entregar todo al Señor<br/>Para provisión ganar.<br/>Me consagro a Ti,<br/>Todo entrego a Ti.<br/>',NULL,196359,10);
INSERT INTO stanza VALUES('S2089','chorus','Quiero ser como José, Señor.<br/>Quiero ser también un soñador.<br/>Oh, prepárame para reinar,<br/>Para otros vida ministrar.<br/>',NULL,196360,11);
INSERT INTO stanza VALUES('S2089','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2089_hoy-sen-or-te-doy-gracias',NULL,196361,12);
INSERT INTO stanza VALUES('S2090','1','Yo no sé dónde le han puesto,<br/>La piedra del sepulcro ya no está.<br/>¡Se han llevado a mi Jesús!<br/>Oh, ¿dónde está?<br/>',NULL,196362,1);
INSERT INTO stanza VALUES('S2090','2','Vinieron los discípulos a ver,<br/>Más regresaron a sus casas,<br/>Les satisfizo sólo el ver.<br/>Más mi Señor no está.<br/>',NULL,196363,2);
INSERT INTO stanza VALUES('S2090','chorus','¿Dónde está mi Jesús?<br/>Mi amado Señor.<br/>Al que ama mi alma,<br/>Jesús, mi amor.<br/>Sólo le amo a Él.<br/>',NULL,196364,3);
INSERT INTO stanza VALUES('S2090','3','Mi corazón deshecho en gran dolor.<br/>No me pregunten por qué lloro.<br/>Pues sólo Él llena mi ser.<br/>¡Mi amor no está!<br/>',NULL,196365,4);
INSERT INTO stanza VALUES('S2090','4','Alguien de pie está detrás de mí.<br/>¿El hortelano? Puedo apenas ver:<br/>Señor, si tú lo has llevado,<br/>Oh, ¿dónde está?<br/>',NULL,196366,5);
INSERT INTO stanza VALUES('S2090','chorus','¿Dónde está mi Jesús?<br/>Mi amado Señor.<br/>Dime dónde le has puesto,<br/>Y yo lo llevaré.<br/>Sí, yo lo llevaré.<br/>',NULL,196367,6);
INSERT INTO stanza VALUES('S2090','5','Luego le oí decir:  María<br/>¡Qué voz tan dulce!¡Él me cautivó!<br/>Esta es la voz de mi Amado<br/>Jesús, mi Amor.<br/>',NULL,196368,7);
INSERT INTO stanza VALUES('S2090','chorus','¡A Jesús he hallado!<br/>¡A mi Amado encontré!<br/>Al que ama mi alma,<br/>Jesús, mi Amor.<br/>¡Te amo mi Jesús!<br/>',NULL,196369,8);
INSERT INTO stanza VALUES('S2090','6','Mas Él me dijo: “No me toques,<br/>Debo subir primero al Padre,<br/>Y a mi Padre y vuestro Padre<br/>A mi Dios y a vuestro Dios”.<br/>',NULL,196370,9);
INSERT INTO stanza VALUES('S2090','chorus','Ve a Mis hermanos,<br/>Diles que subo al Padre,<br/>A Mi Padre y vuestro Padre,<br/>A Mi Dios y a vuestro Dios.<br/>¡Ve a Mis hermanos!<br/>',NULL,196371,10);
INSERT INTO stanza VALUES('S2091','1','Como a José, dame un sueño Señor,<br/>Un sueño donde seas el centro<br/>Y que no haya nada más,<br/>Sino solo Tú.<br/>',NULL,196372,1);
INSERT INTO stanza VALUES('S2091','chorus','Señor, dame una visión<br/>Enséñame el secreto.<br/>Disfrutarte a Ti,<br/>Sin importar lo demás.<br/>',NULL,196373,2);
INSERT INTO stanza VALUES('S2091','2','Señor Jesús, una estrella quiero ser,<br/>Brillando con Tu luz.<br/>Hasta que otros puedan ver<br/>La belleza de Tu ser.<br/>',NULL,196374,3);
INSERT INTO stanza VALUES('S2091','3','Aunque Señor,<br/>En la cárcel pueda estar,<br/>No me voy a quedar en silencio,<br/>Sino que voy a hablar este sueño,<br/>Donde quiera que esté.<br/>',NULL,196375,4);
INSERT INTO stanza VALUES('S2091','4','Y al hablar, reino con el Señor,<br/>Estoy bajo Su gobierno,<br/>Reconozco Tu cuidado,<br/>Amoroso para mí.<br/>',NULL,196376,5);
INSERT INTO stanza VALUES('S2092','1','A medida que llegamos<br/>A ser iguales a Cristo<br/>En vida, naturaleza,<br/>Expresión y función.<br/>Somos hechos aptos<br/>Para laborar con Él,<br/>En beneficio de Su Cuerpo.<br/>',NULL,196377,1);
INSERT INTO stanza VALUES('S2092','2','Mientras confiamos en el Señor<br/>Con absoluto_abandono,<br/>Dependemos de Él<br/>Como nuestro amor y fuerza,<br/>Y escuchamos Sus palabras,<br/>Abrigamos la esperanza<br/>De ser arrebatados<br/>Mediante la redención<br/>De nuestro cuerpo.<br/>',NULL,196378,2);
INSERT INTO stanza VALUES('S2092','3','Y ofrecemos esta oración:<br/>¡Ven, Señor Jesús!<br/>¡Ven, Señor Jesús!<br/>¡Ven, Señor Jesús!<br/>',NULL,196379,3);
INSERT INTO stanza VALUES('S2092','YouTube Link','https://www.youtube.com/watch?v=vqGhnWZSu0I',NULL,196380,4);
INSERT INTO stanza VALUES('S2093','1','Nuestro Dios nos ha llamado<br/>A Su economía eterna,<br/>Por la cual se ha procesado;<br/>Consumado ahora está.<br/>Como Espíritu en nosotros,<br/>Nos habita y es las arras,<br/>Plena salvación realiza:<br/>Y nos hace igual a Él.<br/>',NULL,196381,1);
INSERT INTO stanza VALUES('S2093','chorus','Que me gobierne una clara visión,<br/>Su economía en mi corazón.<br/>¡Y arda en mi espíritu<br/>Hasta que en fuego esté!<br/>Con fuerte espíritu hay que proseguir<br/>Y consumar Su plan:<br/>¡Nueva Jerusalén! ¡Aleluya!<br/>',NULL,196382,2);
INSERT INTO stanza VALUES('S2093','2','Es Jesús nuestro modelo,<br/>Él vivió como un Dios-hombre<br/>Obediente hasta la muerte,<br/>Su hombre natural negó.<br/>Era el único Dios-hombre;<br/>Más se duplicó en nosotros<br/>Como granos bien mezclados;<br/>Somos Su reproducción.<br/>',NULL,196383,3);
INSERT INTO stanza VALUES('S2093','3','Su resurrección vivimos,<br/>No en la carne ni en el alma;<br/>Nuestro espíritu mezclado,<br/>Niega así lo natural.<br/>Hoy vivimos en el Cuerpo,<br/>Cada día en Él vencemos,<br/>Por llegar a Sión luchamos,<br/>Aguardando Su venida.<br/>',NULL,196384,4);
INSERT INTO stanza VALUES('S2093','4','Vivirán Dios y el hombre<br/>En espíritu mezclados,<br/>Siendo‿así incorporados:<br/>¡Una‿orgánica‿entidad!<br/>Tal visión de las edades<br/>Rige‿hoy nuestra vida diaria,<br/>Para que‿Él obtenga‿el Cuerpo,<br/>¡Refulgente ciudad santa!<br/>',NULL,196385,5);
INSERT INTO stanza VALUES('S2093','YouTube Link','https://www.youtube.com/watch?v=Zs7JyaAX2PU&list=PLjxgN0uiH7Glc25QXM_U9IbNvkoTek4SC&index=8',NULL,196386,6);
INSERT INTO stanza VALUES('S2094','1','Eres Tú mi Amado,<br/>Mi precioso Amado,<br/>Te anhela mi alma y<br/>Mi corazón también.<br/>Eres Tú mi Amado,<br/>Mi precioso Amado,<br/>Te abro todo el corazón.<br/>',NULL,196387,1);
INSERT INTO stanza VALUES('S2094','2','Lléname con Tu Espíritu!<br/>¡Llena mi vaso! ¡Tuyo soy, Señor!<br/>¡Lléname con Tu Espíritu!<br/>¡Y así sea yo Tu expresión!<br/>',NULL,196388,2);
INSERT INTO stanza VALUES('S2094','3','¡Lléname hasta el borde, Señor!<br/>¡Lléname a mí!<br/>¡Derrota, conquista mi ser!<br/>¡Lléname hasta el borde, Señor!<br/>¡Y rebosa en mí!<br/>¡Vence hoy en mí!<br/>',NULL,196389,3);
INSERT INTO stanza VALUES('S2094','SoundCloud Link','https://soundcloud.com/damarisleg/eres-tu-mi-amado',NULL,196390,4);
INSERT INTO stanza VALUES('S2095','1','La suprema preciosidad<br/>De Cristo necesito ver,<br/>Para acercarme hoy a Él,<br/>Y derramar mi ser;<br/>Como una ofrenda de amor.<br/>Olor fragante para Dios,<br/>Ungüento de mucho valor;<br/>Ser para Ti, Señor.<br/>',NULL,196391,1);
INSERT INTO stanza VALUES('S2095','chorus','¡Quita los velos de mí hoy!<br/>Pues yo anhelo ver, Señor,<br/>Toda Tu preciosidad.<br/>¡Concédeme revelación,<br/>Y darme a Ti por Amor!<br/>',NULL,196392,2);
INSERT INTO stanza VALUES('S2095','2','De Ti colirio al comprar,<br/>Nuestra ceguera sanará;<br/>Ungiéndonos Tu Espíritu,<br/>¡Luz nos saturará!<br/>Ésta visión conllevará<br/>Que el precio queramos pagar;<br/>Vida y futuro abandonar,<br/>Por Dios todo dejar.<br/>',NULL,196393,3);
INSERT INTO stanza VALUES('S2095','SoundCloud Link','https://soundcloud.com/pablo-suarez-acosta/la-suprema-preciosidad-de',NULL,196394,4);
INSERT INTO stanza VALUES('S2096','chorus','Oh, Señor, haz<br/>Hoy Tu_hogar en mí,<br/>Conquista mi corazón,<br/>Satura cada rincón.<br/>Con los santos, yo quiero comprender,<br/>¡Oh, cuán vasto mi_amoroso Cristo es!<br/>',NULL,196395,1);
INSERT INTO stanza VALUES('S2096','1','Padre Dios, perdóname otra vez,<br/>Tanto tiempo sin estar en Ti.<br/>De rodillas quiero hoy orar:<br/>Fortalece mi_hombre interior Señor.<br/>',NULL,196396,2);
INSERT INTO stanza VALUES('S2096','2','A Tu palabra_acudí Señor,<br/>Sin fuerzas para_un renglón leer.<br/>Mi Señor, Te necesito hoy.<br/>Siempre Tú me fortaleces con poder.<br/>',NULL,196397,3);
INSERT INTO stanza VALUES('S2096','3','Me desanimaba_al no poder<br/>Comprender cuán vasto Cristo es;<br/>Pero con los santos pude ver,<br/>Es así como Jesús mi gozo es.<br/>',NULL,196398,4);
INSERT INTO stanza VALUES('S2096','4','Todavía hay cosas en mí<br/>Que, Señor, no puedo_abandonar;<br/>Pero en mi interior yo digo  "amén";<br/>Fluye gozo nuevo que nunca sentí.<br/>',NULL,196399,5);
INSERT INTO stanza VALUES('S2096','SoundCloud Link','https://soundcloud.com/user-706981176-732981643/oh-senor-haz-tu-hogar-en-mi',NULL,196400,6);
INSERT INTO stanza VALUES('S2097','1','Mi corazón, Señor,<br/>Mantén abierto a Ti;<br/>Que mi mirar<br/>Vuelvas sólo hacia Ti.<br/>',NULL,196401,1);
INSERT INTO stanza VALUES('S2097','2','No importa que acontezca<br/>Mi corazón, se, deseas ganar.<br/>Aunque no pueda comprender,<br/>Sigue impartiéndote<br/>Hasta mi ser llenar.<br/>',NULL,196402,2);
INSERT INTO stanza VALUES('S2097','3','Hazme un creyente,<br/>Mirando Tu faz,<br/>Firme en Tu palabra,<br/>Fiel y veráz.<br/>',NULL,196403,3);
INSERT INTO stanza VALUES('S2097','SoundCloud Link','https://soundcloud.com/grace-hernandez-518638324/mi-corazon-senor-manten',NULL,196404,4);
INSERT INTO stanza VALUES('S2098','1','Palabra viviente, Jesús,<br/>Lávame con Tu sangre y<br/>Háblame al corazón.<br/>Quiero de Tu gracia escuchar.<br/>Quiero Tu rostro contemplar,<br/>Mirando sin cesar.<br/>',NULL,196405,1);
INSERT INTO stanza VALUES('S2098','chorus','Jesús, eres Tú<br/>La Palabra viviente;<br/>Beber, comer de Ti<br/>Es lo que anhelo yo.<br/>',NULL,196406,2);
INSERT INTO stanza VALUES('S2098','2','Jesús tan precioso para mi,<br/>Quiero besarte sólo a Ti,<br/>Para que te expandas Tú.<br/>Sólo a Tu nombre clamaré,<br/>Me abro a Ti, no temo ya,<br/>Amándote a Ti.<br/>',NULL,196407,3);
INSERT INTO stanza VALUES('S2098','chorus','Jesús, tan precioso!<br/>Sé real a mí!!<br/>Todo eres para mi,<br/>Me abro a Ti, Señor!<br/>',NULL,196408,4);
INSERT INTO stanza VALUES('S2098','3','Eres Tú el Viviente en mí,<br/>Abre mis ojos para ver<br/>Lo que eres para mí.<br/>Quiero en Tu corazón entrar,<br/>Nunca de Ti quiero marchar,<br/>Amándote hasta el fin.<br/>',NULL,196409,5);
INSERT INTO stanza VALUES('S2098','chorus','Jesús, quiero que<br/>Me inundes con Tu vida.<br/>Te doy mi corazón,<br/>Sé el vencedor en mí.<br/>',NULL,196410,6);
INSERT INTO stanza VALUES('S2098','4','Señor, haz lo que haya que hacer.<br/>No quiero derrotado ser,<br/>Señor, yo creo en Ti.<br/>Te lo doy todo, mi Señor,<br/>Todo mi ser derramo en Ti,<br/>Te pertenezco a Ti.<br/>',NULL,196411,7);
INSERT INTO stanza VALUES('S2098','chorus','Jesús, mi Dios fiel,<br/>Gáname al completo;<br/>Úsame, Señor,<br/>Para Tu plan lograr.<br/>',NULL,196412,8);
INSERT INTO stanza VALUES('S2099','1','La unidad no es una unión,<br/>Acuerdo externo<br/>Sino la misma vida de Dios.<br/>El Triuno Dios nos incluyó<br/>En Su divina<br/>Unidad — Unidad.<br/>',NULL,196413,1);
INSERT INTO stanza VALUES('S2099','chorus','Que uno sean así;<br/>Como Tú, Oh Padre,<br/>Estás en Mí<br/>Y Yo en Ti—<br/>Que en nosotros<br/>Ellos estén.<br/>Unidad—Unidad.<br/>',NULL,196414,2);
INSERT INTO stanza VALUES('S2100','1','Dentro de ti hay<br/>Algo especial y único:<br/>Tu porción de Cristo.<br/>Y puede ser verdad<br/>Que ese que tienes sentado frente a ti<br/>Necesite ese Cristo.<br/>',NULL,196415,1);
INSERT INTO stanza VALUES('S2100','chorus','Y aunque ya tengas el sentir,<br/>O si te cuesta compartir.<br/>Si les quieres ayudar darás<br/>La porción que en ti está.<br/>',NULL,196416,2);
INSERT INTO stanza VALUES('S2100','2','Sabes que cuando<br/>Nuestro espíritu ejercitamos<br/>Nuestro gozo es cumplido.<br/>Y que al ministrar<br/>A este Cristo somos edificados<br/>Como una morada eterna.<br/>',NULL,196417,3);
INSERT INTO stanza VALUES('S2100','chorus','La economía de Dios es<br/>Que Dios sature hoy tu ser.<br/>Y que a Cristo puedas dispensar<br/>Para el Cuerpo edificar.<br/>',NULL,196418,4);
INSERT INTO stanza VALUES('S2100','3','Para ser lleno<br/>Solo hay que disfrutarle a Él<br/>Poco a poco, cada día.<br/>Solo hay que cooperar,<br/>Pasar tiempo en la Palabra del Señor,<br/>Para que fluya Su vida.<br/>',NULL,196419,5);
INSERT INTO stanza VALUES('S2100','chorus','No tienes nada que perder,<br/>Tan solo vuélvete a Él.<br/>Si le comes Él te llenará,<br/>Así tú le expresarás.<br/>',NULL,196420,6);
INSERT INTO stanza VALUES('S2100','chorus','La economía de Dios es<br/>Que Dios sature hoy tu ser.<br/>Y que a Cristo puedas dispensar<br/>Para el Cuerpo edificar.<br/>',NULL,196421,7);
INSERT INTO stanza VALUES('S2101','1','Cristo es Dios encarnado,<br/>Nació conforme el plan de Dios;<br/>Trajo la divinidad,<br/>Dentro de la humanidad,<br/>Se unió al hombre así.<br/>',NULL,196422,1);
INSERT INTO stanza VALUES('S2101','2','Cristo es Dios encarnado,<br/>Hijo de hombre vino a ser.<br/>Sin pecado, un hombre es Él,<br/>Que la redención logró.<br/>Perfecto hombre fue.<br/>',NULL,196423,2);
INSERT INTO stanza VALUES('S2101','chorus','Su nombre será Jesús,<br/>Llamado Emanuel.<br/>¡Con nosotros mora Dios!<br/>Al hombre vino a morar.<br/>',NULL,196424,3);
INSERT INTO stanza VALUES('S2101','3','Cristo es Dios encarnado.<br/>¡Cuán bueno y cuán rico es!<br/>Encarnado para que<br/>Él viva en nosotros,<br/>Con nosotros se mezcló.<br/>',NULL,196425,4);
INSERT INTO stanza VALUES('S2101','4','Cristo es Dios encarnado<br/>Primer Dios-hombre llegó a ser.<br/>¡Oh, cuán glorioso<br/>Que Él viva en nosotros<br/>Cumpliendo el plan de Dios!<br/>',NULL,196426,5);
INSERT INTO stanza VALUES('S2101','chorus','Su nombre será Jesús,<br/>Llamado Emanuel.<br/>¡Con nosotros mora Dios!<br/>Al hombre vino a morar.<br/>',NULL,196427,6);
INSERT INTO stanza VALUES('S2102','1','Constantemente alabo a Dios,<br/>Porque Él vive en mí!<br/>Y es todo para mí!!<br/>Vida por siempre da!!<br/>Contantemente alabo a Dios,<br/>Porque Él vive en mí!<br/>Él no me dejará!!<br/>',NULL,196428,1);
INSERT INTO stanza VALUES('S2102','chorus','Él alimenta nuestro ser<br/>Cristo nuestro todo es!<br/>Clama a Su nombre y Él es realidad;<br/>Abre tu boca y tú verás<br/>Que tan rico es el Señor,<br/>¡Nuestra vida completa Él suple hoy!<br/>',NULL,196429,2);
INSERT INTO stanza VALUES('S2102','2','El árbol de vida es Él<br/>Y Él me nutre a mí,<br/>Me fortalece a mí!!<br/>Vida eterna es Él!!<br/>El árbol de vida es Él<br/>Diario me acerco a Él,<br/>Él mi alimento es!<br/>',NULL,196430,3);
INSERT INTO stanza VALUES('S2102','3','La vida fluye en mí<br/>Vívidámente aquí,<br/>Su vida fluye en mí,<br/>El inunda mi ser;<br/>La vida fluye en mí,<br/>Siempre me llena Él,<br/>Su nombre es ¡Jesús!<br/>',NULL,196431,4);
INSERT INTO stanza VALUES('S2103','1','Fue Noé un hombre<br/>Que la_era cambió,<br/>Al hallar gracia de Dios;<br/>Contra_el mundo_estuvo firme,<br/>Sin temor,<br/>Y el arca_edificó.<br/>',NULL,196432,1);
INSERT INTO stanza VALUES('S2103','chorus','¿Quieres ser tú, hoy,<br/>Un vencedor viviente,<br/>Que_ama_a Dios<br/>Sin importar lo que diga la gente,<br/>Que come del árbol<br/>Y del agua viva bebe? (Si, si, si)<br/>¿Quieres ser tú, hoy,<br/>Un vencedor viviente<br/>Que se consagra_a Dios<br/>Para cambiar la_era presente?<br/>Por Tu regreso,<br/>Yo me_entrego_a Ti.<br/>',NULL,196433,2);
INSERT INTO stanza VALUES('S2103','2','Fue Moisés un hombre<br/>A quien Dios llamó,<br/>Y quien la era cambió;<br/>Fiel, humilde_y sabio,<br/>Fue_amigo de Dios,<br/>Para Su mover vivió.<br/>',NULL,196434,3);
INSERT INTO stanza VALUES('S2103','chorus','¿Quieres ser tú, hoy,<br/>Un vencedor viviente,<br/>Que_ama_a Dios<br/>Sin importar lo que diga la gente,<br/>Que come del árbol<br/>Y del agua viva bebe? (Si, si, si)<br/>¿Quieres ser tú, hoy,<br/>Un vencedor viviente<br/>Que se consagra_a Dios<br/>Para cambiar la_era presente?<br/>Por Tu regreso,<br/>Yo me_entrego_a Ti.<br/>',NULL,196435,4);
INSERT INTO stanza VALUES('S2103','3','Sacerdote fiel,<br/>Que complacía_a Dios,<br/>Absoluto fue Samuel.<br/>De muerte,<br/>Pecado_y mundo salvo fue,<br/>Nazaraeo para Dios.<br/>',NULL,196436,5);
INSERT INTO stanza VALUES('S2103','chorus','¿Quieres ser tú, hoy,<br/>Un vencedor viviente,<br/>Que_ama_a Dios<br/>Sin importar lo que diga la gente,<br/>Que come del árbol<br/>Y del agua viva bebe? (Si, si, si)<br/>¿Quieres ser tú, hoy,<br/>Un vencedor viviente<br/>Que se consagra_a Dios<br/>Para cambiar la_era presente?<br/>Por Tu regreso,<br/>Yo me_entrego_a Ti.<br/>',NULL,196437,6);
INSERT INTO stanza VALUES('S2103','4','Con sus compañeros salvo fue Daniel,<br/>Apartados para Dios.<br/>Comían Su Palabra, oraban a Dios,<br/>Uno con Su corazón.<br/>',NULL,196438,7);
INSERT INTO stanza VALUES('S2103','chorus','Mi_elección es ser<br/>Un vencedor viviente,<br/>Que ama_a Dios sin importar<br/>Lo que diga la gente,<br/>Que come del árbol<br/>Y del agua viva bebe. (Si, si, si)<br/>Para ser un vencedor,<br/>Señor, me_entrego,<br/>Para ver la visión,<br/>Y que mi_espíritu esté_en fuego.<br/>Por Tu regreso,<br/>Yo me_entrego_a Ti.<br/>',NULL,196439,8);
INSERT INTO stanza VALUES('S2104','1','La Biblia es un romance,<br/>El más puro y sin par.<br/>A Dios y Sus escogidos<br/>Los muestra en amor.<br/>Presenta a esta pareja<br/>Desde principio a fin:<br/>Dios en Cristo es el Novio,<br/>La novia Sus santos.<br/>',NULL,196440,1);
INSERT INTO stanza VALUES('S2104','2','En sombras y figuras,<br/>Su deseo Él mostró;<br/>A Cristo como Esposo<br/>Lo tipifica Adán.<br/>Una costilla muestra el<br/>Origen por el cual<br/>Dios edificó a Eva,<br/>Tipo de la iglesia.<br/>',NULL,196441,2);
INSERT INTO stanza VALUES('S2104','3','Desea Él ser el Esposo,<br/>Y una esposa obtener.<br/>De Dios es el anhelo:<br/>Vida matrimonial.<br/>Sólo Sus sacrificios<br/>No le harán feliz;<br/>Más casarse con ella,<br/>Es Su intención final.<br/>',NULL,196442,3);
INSERT INTO stanza VALUES('S2104','4','El más fino romance<br/>En Cantares se vio:<br/>Los besos del Amado,<br/>La amada anheló.<br/>Cristo es forjado en ella,<br/>Producto de este amor.<br/>La ciudad llega a ser ella,<br/>Con Cristo en su interior.<br/>',NULL,196443,4);
INSERT INTO stanza VALUES('S2104','5','Cristo es nuestro Novio;<br/>Por Su novia Él vendrá.<br/>De Su costado fluye<br/>Completa salvación.<br/>¡Uno, en vida, en esencia,<br/>En Persona somos ya!<br/>Su pareja por siempre:<br/>¡Nueva Jerusalén!<br/>',NULL,196444,5);
INSERT INTO stanza VALUES('S2104','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/the-biblia-es-un-romance-the',NULL,196445,6);
INSERT INTO stanza VALUES('S2105','1','El Creador Dios-hombre vino a ser,<br/>Muriendo nos redimió para Su plan.<br/>Liberó Su Espíritu en resurrección,<br/>La iglesia, Su obra maestra, surgió.<br/>',NULL,196446,1);
INSERT INTO stanza VALUES('S2105','2','Eres mi elección, he visto Tu belleza,<br/>Pertenezco a Ti, por siempre Señor.<br/>Mi única elección, ¡Eres tan precioso!<br/>Por Tu obra maestra doy todo Señor.<br/>',NULL,196447,2);
INSERT INTO stanza VALUES('S2105','3','Te amo Señor pues no existe otro<br/>A quien yo siempre he de amar.<br/>Señor, te amo a Ti, mi ser Tú recobras,<br/>Por Tu obra maestra doy todo Señor.<br/>',NULL,196448,3);
INSERT INTO stanza VALUES('S2105','4','Gracias Señor por cautivar mi ser,<br/>Y porque a diario te puedo vivir.<br/>Tu vida en mi crece al comer y beber.<br/>De Tu obra maestra soy parte, Señor.<br/>',NULL,196449,4);
INSERT INTO stanza VALUES('S2105','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/eres-mi-eleccio-n-el-creador',NULL,196450,5);
INSERT INTO stanza VALUES('S2106','1','Muchos hoy dirían<br/>Que Jesús no es comida,<br/>Que el conocimiento<br/>Y el esfuerzo nos dan vida;<br/>Más estoy feliz<br/>Pues sé que esto no es así,<br/>¡Cristo es pan de vida,<br/>Le comemos hoy aquí.<br/>',NULL,196451,1);
INSERT INTO stanza VALUES('S2106','chorus','¡Cuánto amamos<br/>Vivir la vida de iglesia!<br/>Comiendo, respirando,<br/>Bebiendo a Jesús.<br/>Qué bueno es invocar:<br/>¡Señor! ¡Amén! ¡Aleluya!<br/>Festejamos con Él en la iglesia local.<br/>',NULL,196452,2);
INSERT INTO stanza VALUES('S2106','2','Cuando Él nos llena<br/>Nunca más los mismos somos,<br/>Pues al invocarlo<br/>Sus riquezas recibimos.<br/>La reunión<br/>Sólo el domingo conmigo no va.<br/>Comunión diaria, eso me sustentará.<br/>',NULL,196453,3);
INSERT INTO stanza VALUES('S2106','3','Si las religiones de este mundo<br/>Y nuestros días<br/>Hacen que te sientas<br/>Atrapado y sin salida,<br/>Escúchame atento<br/>A lo que te voy a decir:<br/>Puede que aquí encuentres<br/>El camino para ti.<br/>',NULL,196454,4);
INSERT INTO stanza VALUES('S2107','1','Qué visión tan singular.<br/>¡Precioso Cuerpo de Cristo!<br/>Es muy práctico y real,<br/>Oh, precioso Cuerpo de Cristo.<br/>',NULL,196455,1);
INSERT INTO stanza VALUES('S2107','chorus','La era ya cambió,<br/>Dios nos compenetró<br/>Y en el Cuerpo se expresó,<br/>¡Oh, qué precioso Cuerpo!<br/>',NULL,196456,2);
INSERT INTO stanza VALUES('S2107','2','Por la compenetración,<br/>Se edifica el Cuerpo de Cristo.<br/>Más mi ego debo negar,<br/>Para ver el Cuerpo de Cristo.<br/>',NULL,196457,3);
INSERT INTO stanza VALUES('S2107','3','Diferencias ya no hay,<br/>Es precioso el Cuerpo de Cristo.<br/>El negar lo natural,<br/>Manifiesta el Cuerpo de Cristo.<br/>',NULL,196458,4);
INSERT INTO stanza VALUES('S2107','4','Somos hoy un solo pan<br/>Que expresa el Cuerpo de Cristo.<br/>Preservando tal unidad,<br/>Se manifiesta el Cuerpo de Cristo<br/>',NULL,196459,5);
INSERT INTO stanza VALUES('S2108','1','¿No quieres conocer a Dios?<br/>¿Qué esconde Él en Su corazón?<br/>Anhela Dios que vengas y<br/>Te abras a Él.<br/>Dejarle en cada parte entrar,<br/>Dejar que pueda revelar,<br/>¿Qué gozo fue puesto frente a Él?<br/>',NULL,196460,1);
INSERT INTO stanza VALUES('S2108','chorus','Fue por la iglesia, Su novia,<br/>Por ella fue que murió en la cruz.<br/>Su complemento, obra maestra,<br/>La iglesia es el gozo de Él.<br/>',NULL,196461,2);
INSERT INTO stanza VALUES('S2108','2','La obra maestra de Su plan,<br/>Dios te ha escogido para ser.<br/>¡Qué privilegio! Es poder satisfacer<br/>Su anhelo por llenar tu ser<br/>Con las riquezas que hay en Él.<br/>Su sabio plan, expresado en ti.<br/>',NULL,196462,3);
INSERT INTO stanza VALUES('S2108','3','Al disfrutar y al entrar<br/>En este Cristo entenderás,<br/>Qué siente en Su corazón<br/>El hacia ti.<br/>Qué amor fue el que le motivó,<br/>A amarte, aunque pecador.<br/>¿Por qué lo dio todo por amor?<br/>',NULL,196463,4);
INSERT INTO stanza VALUES('S2108','SoundCloud Link','https://soundcloud.com/denisse-cuenca/no-quieres-conocer-a-dios-por',NULL,196464,5);
INSERT INTO stanza VALUES('S2109','1','Hoy nos llamas Tú, Señor<br/>Y abres Tu corazón,<br/>Oh, que gozo oír Tu hablar,<br/>Y en el arca entrar.<br/>Diariamente salvas Tú,<br/>En Tu vida, Señor.<br/>Sobre esta perversa edad<br/>Podemos hoy en Ti flotar.<br/>',NULL,196465,1);
INSERT INTO stanza VALUES('S2109','chorus','Encontramos Señor gracia en Ti.<br/>A Ti abrimos hoy el corazón;<br/>No importa<br/>Lo que los amigos digan hoy.<br/>Te amamos, oh Jesús.<br/>',NULL,196466,2);
INSERT INTO stanza VALUES('S2109','2','Buscamos esta edad probar<br/>De ella participar,<br/>Si supiéramos, Señor<br/>Cuanto pesar te da;<br/>Arrepentidos así,<br/>Vendríamos a Ti,<br/>Consagrados a estar<br/>En el arca, en Ti, Señor.<br/>',NULL,196467,3);
INSERT INTO stanza VALUES('S2109','3','En Ti salvos, oh Señor,<br/>Fuera del hondo mar;<br/>Muchas cosas que yo amé<br/>Bajo el océano están.<br/>Abiertos, guardarnos en Ti,<br/>No queremos errar;<br/>Aleluya estamos ya<br/>En el arca, la iglesia hoy.<br/>',NULL,196468,4);
INSERT INTO stanza VALUES('S2109','YouTube Link','https://www.youtube.com/watch?v=vivwcNTt_oI',NULL,196469,5);
INSERT INTO stanza VALUES('S2110','1','La Biblia es el aliento<br/>De Dios,<br/>Su misma esencia.<br/>(2 Tim. 3:16)<br/>Dios hablando en el hombre<br/>Guiado por el Espíritu.<br/>(2 Pe. 1:21)<br/>La Biblia es Dios hablando,<br/>En el Hijo,<br/>En los profetas.<br/>(Hebr. 1:1-2)<br/>La Biblia es la revelación<br/>Del Espíritu Santo.<br/>(Jn. 16:13)<br/>',NULL,196470,1);
INSERT INTO stanza VALUES('S2110','2','La Biblia testifica<br/>Del Señor Jesús mismo;<br/>(Jn. 5:39)<br/>Ella hace al hombre<br/>Sabio para salvación.<br/>(2 Tim. 3:15)<br/>La Biblia hace que el<br/>Hombre sea regenerado,<br/>(1 Pe. 1:23)<br/>Como nuestra leche<br/>(1 Pe. 2:2)<br/>Y pan de vida;<br/>(Mat. 4:4)<br/>Ella nos equipa.<br/>(2 Tim. 3:17)<br/>',NULL,196471,2);
INSERT INTO stanza VALUES('S2111','1','Cristo vida vino a ser,<br/>La Trinidad procesada.<br/>El Padre origen es,<br/>Fuente que brota para ser:<br/>Dios el Hijo como el manantial<br/>En el Espíritu,<br/>Un rio que vida da<br/>¿Cómo este milagro entender?<br/>¡El Triuno Dios fluye en mi ser!<br/>¡Oh, ríos de vida están<br/>Fluyendo desde mi interior!<br/>¡Ríos de vida están<br/>Fluyendo desde mi interior!<br/>',NULL,196472,1);
INSERT INTO stanza VALUES('S2111','chorus','Esta vida al fluir<br/>Se da en abundancia a mí.<br/>Al pecado da fin,<br/>Fluye poder de mí,<br/>Libre soy,<br/>Espontáneamente vence en mí.<br/>',NULL,196473,2);
INSERT INTO stanza VALUES('S2111','2','Tal vida no sólo es<br/>Para vencer y libertar.<br/>Dios tiene una intención,<br/>Fluye para cumplir Su plan.<br/>Esta vida me incluye así<br/>En Su consumación, en Su totalidad.<br/>Al fluir crecimiento me da<br/>Y me lleva a Su destinación.<br/>¡Oh, ríos de vida están<br/>Fluyendo desde mi interior!<br/>¡Ríos de vida están<br/>Fluyendo desde mi interior!<br/>',NULL,196474,3);
INSERT INTO stanza VALUES('S2111','chorus','Y seremos con Dios<br/>Una mutua habitación.<br/>Bebed del río, pues<br/>Del árbol hoy comed,<br/>Que serán<br/>Estos nuestro disfrute eternal.<br/>',NULL,196475,4);
INSERT INTO stanza VALUES('S2111','3','Triste no hay que estar,<br/>Recibí la vida zoé.<br/>Triunfo inevitable,<br/>El rumbo de esta vida es.<br/>Sólo en el fluir debo permanecer,<br/>Si bebo<br/>Dios mismo ocasiona el crecer,<br/>Gozo en mi corazón,<br/>Alegría en mi andar<br/>Y sonríe mi rostro al cantar.<br/>¡Oh, ríos de vida están<br/>Fluyendo desde mi interior!<br/>¡Ríos de vida están<br/>Fluyendo desde mi interior!<br/>',NULL,196476,5);
INSERT INTO stanza VALUES('S2111','YouTube Link','https://www.youtube.com/watch?v=9wzcg2S36Pc',NULL,196477,6);
INSERT INTO stanza VALUES('S2112','1','Nuestro_espíritu_está sujeto_a nosotros,<br/>La Palabra dice así.<br/>No debo esperar a ser inspirado,<br/>Mi_espíritu listo está.<br/>No debo vivir según mis_emociones,<br/>O_esperar un día mejor.<br/>Vuelvo_a_Él e_invoco:  ¡Oh, Señor!<br/>',NULL,196478,1);
INSERT INTO stanza VALUES('S2113','1','¿Tu espíritu has hallado?<br/>Unido a tu boca está.<br/>¡Aleluya! ¡Oh, Señor!<br/>Así lo liberarás.<br/>',NULL,196479,1);
INSERT INTO stanza VALUES('S2113','chorus','Nuestro espíritu de Dios ha nacido.<br/>¡Todo Él ya consumó!<br/>Del Espíritu nació nuestro espíritu,<br/>Y ambos, uno son ya.<br/>',NULL,196480,2);
INSERT INTO stanza VALUES('S2113','2','No esperes ser inspirado,<br/>Engañado puedes ser.<br/>Tu espíritu libera,<br/>Testifica: libre soy.<br/>',NULL,196481,3);
INSERT INTO stanza VALUES('S2114','1','Dios tiene un plan en Su corazón,<br/>Que en la eternidad lo deseó:<br/>Crear un ser a Su imagen<br/>Que lo pudiera contener.<br/>Y así empezó con la creación,<br/>La culminó con la humanidad<br/>Y puso en ella espíritu<br/>Para Él poderse expresar.<br/>',NULL,196482,1);
INSERT INTO stanza VALUES('S2114','2','Se procesó y se encarnó,<br/>Vivió como humano también;<br/>Fue a la cruz y allí murió,<br/>Y con el diablo acabó.<br/>Resucitó y ascendió,<br/>Fue entronado y hecho Señor;<br/>Se le otorgó autoridad<br/>Y sobre todo es Señor.<br/>',NULL,196483,2);
INSERT INTO stanza VALUES('S2114','3','Como el Espíritu bajó,<br/>Accesible hoy es Él;<br/>Tan cerca está que al clamar<br/>Un contacto hay con Él.<br/>Hoy nuestro espíritu con Él<br/>Se ha mezclado para uno ser;<br/>Hoy Dios así cumple Su plan<br/>Morando en nuestro ser.<br/>',NULL,196484,3);
INSERT INTO stanza VALUES('S2114','4','Él hoy anhela obtener<br/>Nuestra alma también:<br/>Mente, emoción y voluntad,<br/>Hasta al cuerpo llegar;<br/>Hasta lograr en nuestro ser<br/>Su plena vida expresar.<br/>Y así tener Su habitación,<br/>Que tanto Él anheló.<br/>',NULL,196485,4);
INSERT INTO stanza VALUES('S2114','5','Nos abrimos a Ti, Señor,<br/>Con todo el espíritu;<br/>Ponemos a Tu disposición<br/>Nuestro ser para Tu obrar,<br/>Y así Tú puedas avanzar;<br/>Y Tu iglesia lograr,<br/>Teniendo un candelero<br/>De Oro en cada ciudad.<br/>',NULL,196486,5);
INSERT INTO stanza VALUES('S2114','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/dios-tiene-un-plan-en-su-2',NULL,196487,6);
INSERT INTO stanza VALUES('S2115','1','Gloria a Dios,<br/>A Su Hijo envió<br/>¡Aleluya!<br/>Él la salvación obró,<br/>¡Gloria a Dios!<br/>Dios un hombre vino a ser<br/>Para hoy vivir por Él.<br/>',NULL,196488,1);
INSERT INTO stanza VALUES('S2115','chorus','Por eso clamo a Él,<br/>Le doy todo mi ser,<br/>',NULL,196489,2);
INSERT INTO stanza VALUES('S2115','2','Él crucificado fue,<br/>¡Aleluya!<br/>Por los muchos Él murió<br/>¡Gloria a Dios!<br/>Un grano en tierra cayó<br/>Para muchos producir.<br/>',NULL,196490,3);
INSERT INTO stanza VALUES('S2115','chorus','Por eso clamo a Él,<br/>Le doy todo mi ser,<br/>',NULL,196491,4);
INSERT INTO stanza VALUES('S2115','3','En victoria Él salió,<br/>¡Aleluya!<br/>De la tumba con poder,<br/>¡Gloria a Dios!<br/>Hoy Él en resurrección<br/>Como Espíritu está en mí.<br/>',NULL,196492,5);
INSERT INTO stanza VALUES('S2115','chorus','Por eso clamo a Él,<br/>Le doy todo mi ser,<br/>',NULL,196493,6);
INSERT INTO stanza VALUES('S2115','4','Clama a Él de tu interior,<br/>¡Aleluya!<br/>Al clamar, Él entrará,<br/>¡Gloria a Dios!<br/>Cuando le invoques, tú<br/>Nunca más serás igual.<br/>',NULL,196494,7);
INSERT INTO stanza VALUES('S2115','chorus','Debemos a Él clamar,<br/>Démosle nuestro ser.<br/>',NULL,196495,8);
INSERT INTO stanza VALUES('S2115','YouTube Link','https://www.youtube.com/watch?v=RMupRrqx-6Y',NULL,196496,9);
INSERT INTO stanza VALUES('S2116','1','Me conoció el Padre eras atrás,<br/>Y me lavó con Su sangre el Señor.<br/>Soy un Dios-hombre en el espíritu.<br/>¡Aleluya! ¡Aleluya!<br/>',NULL,196497,1);
INSERT INTO stanza VALUES('S2116','chorus','¡Aleluya, aleluya, aleluya!<br/>¡Aleluya, aleluya, aleluya!<br/>',NULL,196498,2);
INSERT INTO stanza VALUES('S2116','2','En Su presciencia el Padre me eligió,<br/>Para Su misericordia mostrar,<br/>Y de Su gloria poder disfrutar.<br/>¡Aleluya! ¡Aleluya!<br/>',NULL,196499,3);
INSERT INTO stanza VALUES('S2116','3','Tú, con Tu sangre preciosa, Jesús,<br/>Me redimiste y salvaste también.<br/>Hoy clamo así por Tu resurrección:<br/>¡Aleluya! ¡Aleluya!<br/>',NULL,196500,4);
INSERT INTO stanza VALUES('S2116','4','Me santifica el Espíritu hoy.<br/>Él me dio fe al yo ciego estar.<br/>Mi vida es, hoy en mi Él está.<br/>¡Aleluya! ¡Aleluya!<br/>',NULL,196501,5);
INSERT INTO stanza VALUES('S2116','5','Eres mi Padre, yo tengo Tu gen,<br/>Ya redimido y comprado estoy.<br/>¡Oh, cuán real es Su Espíritu en mí!<br/>¡Aleluya! ¡Aleluya!<br/>',NULL,196502,6);
INSERT INTO stanza VALUES('S2117','1','¡Gloria a Dios! El Dios de gloria,<br/>Quien se_apareció a Abraham;<br/>Y en Espíritu aparece,<br/>Por Su deseo y Su plan<br/>',NULL,196503,1);
INSERT INTO stanza VALUES('S2117','chorus','¡Dios de gloria! ¡Dios de gloria!<br/>Aparécete hoy a nos.<br/>Ven satura y permea<br/>Hasta ser llenos de Dios.<br/>',NULL,196504,2);
INSERT INTO stanza VALUES('S2117','2','Una vez en Caldea estaba,<br/>Adorando ídolos;<br/>Pero‿el Dios de gloria me llamó,<br/>De la trampa me sacó.<br/>',NULL,196505,3);
INSERT INTO stanza VALUES('S2117','chorus','¡Salid! Salid de Caldea,<br/>Esa tierra extraña es;<br/>A la buena tierra entra,<br/>Cristo y la iglesia es.<br/>',NULL,196506,4);
INSERT INTO stanza VALUES('S2117','3','La promesa de Su reino,<br/>Con Su llamado trae ya;<br/>Nos motiva y fortalece,<br/>De escasez nos sacará.<br/>',NULL,196507,5);
INSERT INTO stanza VALUES('S2117','chorus','Señor, a cruzar el río,<br/>Hoy llamándonos estás;<br/>Para que Tu reino y gloria,<br/>En la tierra tengas ya.<br/>',NULL,196508,6);
INSERT INTO stanza VALUES('S2117','4','Evangelio alto_es este,<br/>Para los que en Caldea están;<br/>¡Sal de_este mundo caído!<br/>Eres parte de Su plan.<br/>',NULL,196509,7);
INSERT INTO stanza VALUES('S2117','chorus','¡Dios de gloria! Aparécete,<br/>Cada día más y más;<br/>Para edificar nos llamas,<br/>Tu deseo así tendrás.<br/>',NULL,196510,8);
INSERT INTO stanza VALUES('S2117','YouTube Link','https://www.youtube.com/watch?v=Hq3KIEg8MCI',NULL,196511,9);
INSERT INTO stanza VALUES('S2118','1','Tenemos un Padre<br/>Con un corazón lleno de amor.<br/>¡Cuánto‿Él nos ama!<br/>Su amor no tiene límite.<br/>Y aunque lejos esté,<br/>A Él siempre puedo volver.<br/>¡Qué gran amor tiene el Padre a nos!<br/>',NULL,196512,1);
INSERT INTO stanza VALUES('S2118','chorus','Simplemente volver,<br/>Y en Sus brazos permanecer<br/>¡Qué gran amor tiene el Padre a nos!<br/>',NULL,196513,2);
INSERT INTO stanza VALUES('S2118','YouTube Link','https://www.youtube.com/watch?v=7nrKcpK6M1s',NULL,196514,3);
INSERT INTO stanza VALUES('S2119','1','Dios tiene un plan,<br/>En la tierra quiere Él habitar.<br/>Dios tiene un plan,<br/>En la tierra quiere Él habitar.<br/>Dios un hombre vino a ser<br/>Para dispensarse<br/>En toda la humanidad.<br/>',NULL,196515,1);
INSERT INTO stanza VALUES('S2119','2','El Triuno Dios,<br/>Accesible a nosotros es.<br/>El Triuno Dios,<br/>Accesible a nosotros es.<br/>La fuente es, curso también.<br/>Él se quiere a nosotros<br/>Hoy transmitir.<br/>',NULL,196516,2);
INSERT INTO stanza VALUES('S2119','3','Cristo el Hijo,<br/>Es el Padre y el Espíritu.<br/>Cristo el Hijo,<br/>Es el Padre y el Espíritu.<br/>Misterio es esta unidad.<br/>Disfrutemos al Señor<br/>Con toda simplicidad.<br/>',NULL,196517,3);
INSERT INTO stanza VALUES('S2119','4','Cristo está hoy<br/>Transfigurado al Espíritu.<br/>Cristo está hoy<br/>Transfigurado al Espíritu.<br/>Como aire es Él,<br/>Está doquier.<br/>El Cristo todo-inclusivo<br/>Nuestro debe ser.<br/>',NULL,196518,4);
INSERT INTO stanza VALUES('S2119','5','¿Qué haremos hoy?<br/>Clamar y respirar al Señor.<br/>¿Qué haremos hoy?<br/>Clamar y respirar al Señor.<br/>Seremos para Dios Su hogar.<br/>Seremos uno con Dios<br/>Por toda la eternidad.<br/>',NULL,196519,5);
INSERT INTO stanza VALUES('S2120','1','La economía de Dios<br/>Es hacernos igual a Dios<br/>En vida y naturaleza,<br/>Más no en la Deidad.<br/>Y ser uno con el hombre,<br/>Y él uno con Dios,<br/>A fin de agrandar<br/>Y extender Su expresión.<br/>Que todos Sus atributos divinos<br/>Se expresen por las virtudes humanas.<br/>',NULL,196520,1);
INSERT INTO stanza VALUES('S2120','YouTube Link','https://www.youtube.com/watch?v=nvDaWnx9KiQ',NULL,196521,2);
INSERT INTO stanza VALUES('S2121','1','Dios es amor,<br/>A Su Hijo amado envió.<br/>Es corrupta la humanidad,<br/>Más Tu Hijo enviaste aún.<br/>Dios nos muestra<br/>Su amor y Su bondad,<br/>En que siendo aún pecadores,<br/>Por nosotros Él murió.<br/>',NULL,196522,1);
INSERT INTO stanza VALUES('S2121','chorus','Su Hijo, el Padre<br/>No escatimó.<br/>Padre te alabamos.<br/>Cuán precioso es Él.<br/>',NULL,196523,2);
INSERT INTO stanza VALUES('S2121','2','Y ¿quién podrá sondear,<br/>Padre, todo Tu amor?<br/>Ojo nunca vio, ni oído oyó,<br/>Mas yo redimido soy.<br/>Dios es amor. Oh Dios,<br/>Hombre viniste a ser;<br/>Qué anatema! Moriste por mí!<br/>Tú colgaste de la cruz.<br/>',NULL,196524,3);
INSERT INTO stanza VALUES('S2121','chorus','Su Hijo, el Padre<br/>En amor nos envió;<br/>El vertió Su sangre,<br/>Amor redentor.<br/>',NULL,196525,4);
INSERT INTO stanza VALUES('S2121','3','Amó al mundo,<br/>Y a Su Unigénito dio.<br/>No perezcas, sólo cree en Él<br/>Y la vida eterna obtén.<br/>No perezcas, sólo cree en Él<br/>Y la vida eterna obtén.<br/>',NULL,196526,5);
INSERT INTO stanza VALUES('S2121','YouTube Link','https://www.youtube.com/watch?v=uGwgZOij2yk',NULL,196527,6);
INSERT INTO stanza VALUES('S2122','1','Me quiero llenar<br/>Con el Triuno Dios.<br/>Él me alegra;<br/>Me quiero llenar con Él.<br/>Me quiero llenar<br/>Con el Triuno Dios.<br/>Él me alegra;<br/>Me quiero llenar con Él.<br/>',NULL,196528,1);
INSERT INTO stanza VALUES('S2122','chorus','Voy a beber, beber, beber<br/>Del agua viva.<br/>Voy a comer, comer<br/>Del Árbol de vida.<br/>A Su nombre invocaré<br/>¡Señor Jesús!<br/>Que Tú me llenes más, más, más.<br/>Que Tú me llenes más, más, más.<br/>Que Tú me llenes más, más, más<br/>De Ti!<br/>De Ti!<br/>De Ti!<br/>',NULL,196529,2);
INSERT INTO stanza VALUES('S2122','YouTube Link','https://www.youtube.com/watch?v=zt7S4nS3xQI',NULL,196530,3);
INSERT INTO stanza VALUES('S2123','1','El Hijo con el Padre por el Espíritu,<br/>¡Gran misterio es!<br/>Corporalmente mora en Él<br/>Toda la plenitud de la Deidad.<br/>',NULL,196531,1);
INSERT INTO stanza VALUES('S2123','chorus','Hijo con (el Padre), -<br/>¡Cuán Admirable es!<br/>Por el Es(píritu) -<br/>¡Maravilloso!<br/>Es Jesucristo.<br/>¡Cuán Admirable,<br/>El Dios Triuno es!<br/>',NULL,196532,2);
INSERT INTO stanza VALUES('S2123','2','El Hijo con el Padre por el Espíritu<br/>Concebido fue.<br/>Nació el Dios-hombre, Jesús,<br/>Admirable, Divino y humano.<br/>',NULL,196533,3);
INSERT INTO stanza VALUES('S2123','chorus','Hijo con el (Padre), -<br/>¡Cuán Admirable es!<br/>Por el Es(píritu) -<br/>¡Maravilloso!<br/>Es Jesucristo.<br/>¡Cuán admirable,<br/>El Dios Triuno es!<br/>',NULL,196534,4);
INSERT INTO stanza VALUES('S2123','3','Tal Hombre perfecto<br/>Su vida negó,<br/>Escogió vivir a Dios.<br/>Pecado, Satán, mundo,<br/>No le invadieron,<br/>Su sangre es sin pecar.<br/>',NULL,196535,5);
INSERT INTO stanza VALUES('S2123','chorus','Humani(dad)-<br/>Su sangre limpia,<br/>Divini(dad)-<br/>Mi garantía<br/>Su sangre me limpió.<br/>Mi garantía,<br/>Mi garantía es Dios.<br/>',NULL,196536,6);
INSERT INTO stanza VALUES('S2123','4','A la carne de pecado<br/>Él se unió y prendió a Satanás.<br/>Pecado, Satán y la carne, colgados,<br/>¡Qué gran terminación!<br/>',NULL,196537,7);
INSERT INTO stanza VALUES('S2123','chorus','El termi(nó)<br/>La creación vieja.<br/>Anuló a (Satán) -<br/>Pecado y carne.<br/>¡Qué gran simiente es Él!<br/>Él aplastó a... Él aplastó a...<br/>Él aplastó_a Satán.<br/>',NULL,196538,8);
INSERT INTO stanza VALUES('S2123','5','En resurrección,<br/>Tal persona admirable<br/>El Espíritu vino a ser.<br/>El cual es hoy el Hijo<br/>Con el Padre<br/>Y es la consumación.<br/>',NULL,196539,9);
INSERT INTO stanza VALUES('S2123','chorus','El Espí(ritu) —<br/>Vivificante,<br/>Es el (Hijo hoy), la consumación.<br/>Hijo con el Padre,<br/>Viven en mi hoy,<br/>Como el Espíritu.<br/>',NULL,196540,10);
INSERT INTO stanza VALUES('S2123','6','En Su ascensión,<br/>En el Trono de Dios<br/>Este Hombre se sentó.<br/>La posición más alta<br/>A Él se le dio,<br/>Hoy Él rige y reina.<br/>',NULL,196541,11);
INSERT INTO stanza VALUES('S2123','chorus','Señor de (Señores) -<br/>Y Rey de Reyes.<br/>El nombre (más alto)<br/>Dado a Jesús.<br/>En el Trono de Dios<br/>Este Hombre está,<br/>¡Cuán admirable es Él!<br/>',NULL,196542,12);
INSERT INTO stanza VALUES('S2123','7','En el trono  está y es Cabeza<br/>Sobre todo el Procesado Dios;<br/>Se imparte como el Espíritu vivo<br/>Y produce Su Cuerpo.<br/>',NULL,196543,13);
INSERT INTO stanza VALUES('S2123','chorus','El Triuno (Dios) -<br/>No es doctrina.<br/>La Trini(dad) -<br/>Para impartirse es.<br/>El se imparte a nos,<br/>Le disfrutamos, le disfrutamos,<br/>¡Cuán disfrutable es Él!<br/>',NULL,196544,14);
INSERT INTO stanza VALUES('S2123','SoundCloud Link','https://soundcloud.com/hermanos-en-mixco/02-el-hijo-con-el-padre',NULL,196545,15);
INSERT INTO stanza VALUES('S2124','1','La Trinidad: misterio,<br/>Dios es uno y es tres.<br/>Triuno Dios Admirable,<br/>Tú eres Admirable.<br/>',NULL,196546,1);
INSERT INTO stanza VALUES('S2124','2','La Trinidad: misterio,<br/>Dios es uno y es tres.<br/>Triuno Dios Maravilloso,<br/>Tú eres Maravilloso.<br/>',NULL,196547,2);
INSERT INTO stanza VALUES('S2124','chorus','(Hermanas)   Nacido un niño es<br/>(Hermanos)   El fuerte Dios es Él<br/>(Hermanas)   Hijo nos es dado,<br/>(Todos)      Eterno Padre, Él.<br/>(Hermanas)   El niño, El Fuerte Dios,<br/>(Hermanos)   Su nombre Admirable;<br/>(Hermanas)   Uno, Padre e Hijo<br/>(Todos)      Persona Admirable.<br/>',NULL,196548,3);
INSERT INTO stanza VALUES('S2124','3','¡Misterio asombroso,<br/>El Espíritu es Él!<br/>Cristo, el Espíritu viviente,<br/>¡Ha entrado dentro de mí!<br/>',NULL,196549,4);
INSERT INTO stanza VALUES('S2124','4','¡Oh esto es glorioso,<br/>El Espíritu es Él!<br/>Cristo, el Espíritu viviente<br/>¡Ha entrado dentro de nos!<br/>',NULL,196550,5);
INSERT INTO stanza VALUES('S2124','chorus','(Hermanas)   Hoy el Postrer Adán<br/>(Hermanos)   Espíritu vivo es,<br/>(Hermanas)   Señor Espíritu,<br/>(Todos)      Todo-inclusivo es.<br/>(Hermanas)   Hoy el Postrer Adán<br/>(Hermanos)   Espíritu vivo es,<br/>(Hermanos)   Señor-Espíritu,<br/>(Todos)      Vive en nosotros hoy.<br/>',NULL,196551,6);
INSERT INTO stanza VALUES('S2124','5','El Padre es la Fuente,<br/>El Hijo me alcanzó,<br/>Como el Espíritu que fluye,<br/>Él fluye a Dios en mi ser.<br/>',NULL,196552,7);
INSERT INTO stanza VALUES('S2124','6','El Padre es la Fuente,<br/>El Hijo es el caudal,<br/>Como el Espíritu entra en mí,<br/>¡Este es un gran misterio!<br/>',NULL,196553,8);
INSERT INTO stanza VALUES('S2124','chorus','(Hermanas)    El Triuno Dios en mí<br/>(Hermanos)    Un gran misterio es,<br/>(Hermanas)    Glorioso esto es,<br/>(Todos)       En nosotros está.<br/>(Hermanas)    El Triuno Dios en mí<br/>(Hermanos)    Un gran misterio es,<br/>(Hermanas)    Maravilloso es,<br/>(Todos)       Que Él viva en mi interior.<br/>',NULL,196554,9);
INSERT INTO stanza VALUES('S2124','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/la-trinidad-misterio-the',NULL,196555,10);
INSERT INTO stanza VALUES('S2125','1','Hay un gran misterio,<br/>Escrito en romance;<br/>Por siglos velado,<br/>Mas hoy lo sabemos.<br/>Romance divino<br/>Entre Dios y el hombre.<br/>No puede entenderse,<br/>Mas Dios nos lo dice:<br/>',NULL,196556,1);
INSERT INTO stanza VALUES('S2125','chorus','Dios se ha enamorado<br/>Con el hombre, y por Su amor<br/>Puede hacernos como El<br/>En esencia y vida;<br/>Su expresion hoy somos<br/>Y Su agrandamiento,<br/>Viviendo por siempre<br/>Como una pareja inseparable<br/>Junto a El.<br/>',NULL,196557,2);
INSERT INTO stanza VALUES('S2125','2','Aunque rechazado<br/>Por hombres cegados,<br/>Su amor incambiable<br/>Siempre nos constriñe.<br/>Con un plan divino,<br/>Llegó a ser un hombre,<br/>Jesús es Su nombre,<br/>Buscándonos vino.<br/>',NULL,196558,3);
INSERT INTO stanza VALUES('S2125','3','Nací en pecado,<br/>Mas fui redimido<br/>Por el Cristo en gloria,<br/>Quien fue levantado.<br/>Me ha regenerado,<br/>Y estoy unido a Él.<br/>Pues fui perdonado,<br/>Y hoy le disfruto.<br/>',NULL,196559,4);
INSERT INTO stanza VALUES('S2125','4','Tan tierno Su amor es,<br/>A Él yo me rindo.<br/>Dulce es Su nombre,<br/>Con gozo le llamo.<br/>Su persona amable,<br/>Mi corazón gana.<br/>Nunca he de apartarme,<br/>Le amaré por siempre.<br/>',NULL,196560,5);
INSERT INTO stanza VALUES('S2125','YouTube Link','https://www.youtube.com/watch?v=ycCRhGa7f84',NULL,196561,6);
INSERT INTO stanza VALUES('S2126','1','Entraré por Sus puertas<br/>Dando gracias al Señor,<br/>Y en Sus atrios con alabanzas.<br/>Porque este es el día<br/>Que hizo el Señor.<br/>Me alegraré pues Él me hizo feliz.<br/>',NULL,196562,1);
INSERT INTO stanza VALUES('S2126','chorus','Él me hizo feliz, Él me hizo feliz.<br/>Me alegraré pues Él me hizo feliz.<br/>Él me hizo feliz, Él me hizo feliz.<br/>Me alegraré pues Él me hizo feliz.<br/>',NULL,196563,2);
INSERT INTO stanza VALUES('S2126','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/entrare-por_sus_puertas',NULL,196564,3);
INSERT INTO stanza VALUES('S2127','1','Porque un niño nos es nacido,<br/>Un Hijo nos es dado;<br/>Porque un niño nos es nacido,<br/>Un Hijo nos es dado;<br/>',NULL,196565,1);
INSERT INTO stanza VALUES('S2127','chorus','Y se llamará Su nombre:<br/>Dios Fuerte,<br/>Padre Eterno, Príncipe de Paz.<br/>Dios Fuerte,<br/>Padre Eterno, Príncipe de Paz.<br/>Dios Fuerte,<br/>Padre Eterno, Príncipe de Paz.<br/>',NULL,196566,2);
INSERT INTO stanza VALUES('S2127','2','El Señor es el Espíritu,<br/>Allí hay libertad.<br/>El Señor es el Espíritu,<br/>Allí hay libertad.<br/>',NULL,196567,3);
INSERT INTO stanza VALUES('S2127','3','Y ahora cuando le invocas,<br/>Recibes al Triuno Dios.<br/>Y ahora cuando le invocas,<br/>Recibes al Triuno Dios.<br/>',NULL,196568,4);
INSERT INTO stanza VALUES('S2127','SoundCloud Link','https://soundcloud.com/cabal12/is-9-6-2co-3-17-ro-10-13',NULL,196569,5);
INSERT INTO stanza VALUES('S2128','1','Tu palabra atesoro<br/>Más que mi diaria porción.<br/>Tu palabra atesoro<br/>Más que mi diaria porción.<br/>',NULL,196570,1);
INSERT INTO stanza VALUES('S2128','2','No sólo de pan vivirá el hombre,<br/>Mas de toda palabra,<br/>Palabra que sale de Dios<br/>De la boca de Dios.<br/>Nos anima y nos aviva,<br/>Son Espíritu y son vida.<br/>',NULL,196571,2);
INSERT INTO stanza VALUES('S2128','SoundCloud Link','https://soundcloud.com/maylin-andrade/tu-palabra-atesoro',NULL,196572,3);
INSERT INTO stanza VALUES('S2129','1','//He aquí,<br/>Yo estoy a la puerta y llamo;<br/>Si alguno oye Mi voz<br/>Y abre la puerta,<br/>Entraré a él,<br/>Y cenaré<br/>Con él, y él conmigo.//<br/>',NULL,196573,1);
INSERT INTO stanza VALUES('S2129','2','//Al que venza,<br/>(al que venza)<br/>Le daré<br/>Que se siente<br/>(conmigo en Mi trono)<br/>Como Yo también<br/>He vencido, y me he sentado<br/>Con Mi Padre en Su trono.//<br/>',NULL,196574,2);
INSERT INTO stanza VALUES('S2129','SoundCloud Link','https://soundcloud.com/valen_torres/ap-3-20-21',NULL,196575,3);
INSERT INTO stanza VALUES('S2130','1','Si andamos en luz,<br/>Como Él está en luz,<br/>Tenemos comunión unos con otros.<br/>Si andamos en luz,<br/>Como Él está en luz,<br/>Tenemos comunión unos con otros.<br/>',NULL,196576,1);
INSERT INTO stanza VALUES('S2130','2','Y la sangre de Jesús, Su Hijo,<br/>Nos limpia de todo pecado.<br/>Y la sangre de Jesús, Su Hijo,<br/>Nos limpia de todo pecado.<br/>',NULL,196577,2);
INSERT INTO stanza VALUES('S2130','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/si-andamos-en-luz-i-juan-1-7',NULL,196578,3);
INSERT INTO stanza VALUES('S2131','1','Es algo bueno dar gracias al Señor,<br/>Y cantar salmos a Tu Nombre. (Oh Altísimo).<br/>Es algo bueno dar gracias al Señor,<br/>Y cantar salmos a Tu Nombre.<br/>Anunciar Tu benevolencia<br/>Amorosa por la mañana<br/>Y Tu fidelidad por las noches.<br/>',NULL,196579,1);
INSERT INTO stanza VALUES('S2131','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/es-bueno-dar-gracias-a-jehova',NULL,196580,2);
INSERT INTO stanza VALUES('S2132','1','Todo aquel con sed:<br/>Venga a las aguas;<br/>No tienes dinero?<br/>Ven, compra y comed-!<br/>Compra vino y leche<br/>Sin dinero, sin valor.<br/>Todo aquel con sed:<br/>Venga a las aguas.<br/>',NULL,196581,1);
INSERT INTO stanza VALUES('S2133','1','Porque yo recibí del Señor lo que también<br/>Os he enseñado: que el Señor Jesús,<br/>La noche en que fue entregado,<br/>Tomó el pan; y habiendo<br/>Dado gracias, lo partió, y dijo:<br/>',NULL,196582,1);
INSERT INTO stanza VALUES('S2133','chorus','//Esto es Mi cuerpo<br/>Por vosotros es partido;<br/>Haced esto en memoria de Mí.//<br/>',NULL,196583,2);
INSERT INTO stanza VALUES('S2133','2','Así mismo tomó también la copa,<br/>Después de haber cenado, diciendo:<br/>Esta copa es el nuevo pacto de Mi sangre,<br/>Haced esto cada vez que la bebieres,<br/>En memoria de Mí.<br/>Así pues, todas las veces que comieres<br/>Este pan y bebieres esta copa<br/>La muerte del Señor anunciáis<br/>Hasta que Él (hasta que Él) venga.<br/>',NULL,196584,3);
INSERT INTO stanza VALUES('S2133','chorus','Esto es Mi cuerpo<br/>Por vosotros es partido;<br/>Haced esto en memoria de Mí.<br/>Esto es Mi sangre<br/>Por vosotros derramada;<br/>Haced esto en memoria de Mí.<br/>',NULL,196585,4);
INSERT INTO stanza VALUES('S2134','1','Ellos le han vencido por medio,<br/>Por medio de la sangre del Cordero;<br/>Y de la palabra de su testimonio,<br/>Menospreciaron sus vidas<br/>Hasta la muerte.<br/>',NULL,196586,1);
INSERT INTO stanza VALUES('S2135','1','Amor de Dios -<br/>Gracia de Cristo,<br/>Y comunión del Espíritu<br/>Sean con todos, sean con todos<br/>Sean con todos, sean con todos.<br/>',NULL,196587,1);
INSERT INTO stanza VALUES('S2135','2','Desde el trono de Dios<br/>Y del Cordero fluye un río<br/>De agua de vida,<br/>Brilla, cristalino,<br/>Llega a mí.<br/>',NULL,196588,2);
INSERT INTO stanza VALUES('S2135','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/amor-de-dios-gracia-de-2',NULL,196589,3);
INSERT INTO stanza VALUES('S2136','1','No améis al mundo,<br/>Ni las cosas que están en el mundo.<br/>Si alguno ama al mundo,<br/>El amor del Padre no está en él.<br/>',NULL,196590,1);
INSERT INTO stanza VALUES('S2136','2','Porque todo lo que hay en el mundo:<br/>Los deseos de la carne,<br/>Los deseos de los ojos,<br/>Y la vanagloria de la vida,<br/>No provienen del Padre,<br/>Sino del mundo.<br/>No provienen del Padre,<br/>Sino del mundo.<br/>',NULL,196591,2);
INSERT INTO stanza VALUES('S2136','3','//Y el mundo pasa y su concupisencia;<br/>Pero el que hace la voluntad de Dios<br/>Permanece para siempre<br/>Permanece para siempre.//<br/>',NULL,196592,3);
INSERT INTO stanza VALUES('S2136','SoundCloud Link','https://soundcloud.com/clara-orjuela-78079798/no-ameos-al-mundo-1-jn-2-15-16',NULL,196593,4);
INSERT INTO stanza VALUES('S2137','1','Huye también<br/>De las pasiones juveniles;<br/>Persigue la justicia,<br/>La fe, el amor y la paz<br/>Con los que de corazón puro<br/>Invocan al Señor.<br/>Invocan al Señor.<br/>Invocan al Señor.<br/>',NULL,196594,1);
INSERT INTO stanza VALUES('S2137','YouTube Link','https://www.youtube.com/watch?v=HOSBhNsGW50',NULL,196595,2);
INSERT INTO stanza VALUES('S2138','1','Teniendo el mismo espíritu de fe<br/>Conforme a lo que está escrito:<br/>Creí por lo cual hablé.<br/>Nosotros también creemos.<br/>Por lo cual también hablamos<br/>Porque la fe proviene del oír<br/>Y el oír por medio de la palabra<br/>De Cristo.<br/>',NULL,196596,1);
INSERT INTO stanza VALUES('S2139','1','Para que, alumbrados<br/>Los ojos de vuestro corazón;<br/>Para que, alumbrados<br/>Los ojos de vuestro corazón;<br/>',NULL,196597,1);
INSERT INTO stanza VALUES('S2139','2','Sepáis cuál es la esperanza<br/>A que Él os ha llamado,<br/>Y cuáles las riquezas de la gloria<br/>De Su herencia en los santos.<br/>De la gloria de Su herencia<br/>En los santos.<br/>',NULL,196598,2);
INSERT INTO stanza VALUES('S2140','1','Mas vosotros sois linaje escogido,<br/>Real sacerdocio, nación santa,<br/>Pueblo adquirido por Dios.<br/>',NULL,196599,1);
INSERT INTO stanza VALUES('S2140','2','Mas vosotros sois linaje escogido,<br/>Real sacerdocio, nación santa,<br/>Pueblo adquirido por Dios.<br/>',NULL,196600,2);
INSERT INTO stanza VALUES('S2140','3','Para que anunciéis las virtudes<br/>De Aquel que os llamó de las tinieblas<br/>A Su luz -<br/>A Su luz,<br/>A Su luz admirable.<br/>',NULL,196601,3);
INSERT INTO stanza VALUES('S2140','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/i-pedro-2-9-mas-vosotros-so-is',NULL,196602,4);
INSERT INTO stanza VALUES('S2141','1','Así que hermanos, os exhorto<br/>Por las compasiones de Dios,<br/>Que presentéis vuestros cuerpos<br/>En sacrificio vivo, santo,<br/>',NULL,196603,1);
INSERT INTO stanza VALUES('S2141','chorus','Agradable a Dios,<br/>Que es vuestro servicio racional.<br/>Agradable a Dios,<br/>Que es vuestro servicio racional.<br/>',NULL,196604,2);
INSERT INTO stanza VALUES('S2141','2','No os amoldéis a este siglo,<br/>Sino transformaos por medio<br/>De la renovación de vuestra mente,<br/>Para que comprobéis cuál sea<br/>',NULL,196605,3);
INSERT INTO stanza VALUES('S2141','chorus','La voluntad de Dios:<br/>Lo bueno, lo agradable, lo perfecto.<br/>La voluntad de Dios:<br/>Lo bueno, lo agradable, lo perfecto.<br/>',NULL,196606,4);
INSERT INTO stanza VALUES('S2141','YouTube Link','https://www.youtube.com/watch?v=wWsYiVv6ISQ',NULL,196607,5);
INSERT INTO stanza VALUES('S2142','1','Soy como árbol<br/>Junto al río de aguas vivas,<br/>Pruebas sí vendrán,<br/>Más victoria me dará.<br/>Y aún en el desierto<br/>Cuando esperanza no hay,<br/>Estoy plantado en el río del Señor. (x2)<br/>',NULL,196608,1);
INSERT INTO stanza VALUES('S2142','chorus','Cuando venga sequedad,<br/>Mi hoja no morirá,<br/>Estoy plantado en el río del Señor.<br/>',NULL,196609,2);
INSERT INTO stanza VALUES('S2142','YouTube Link','https://www.youtube.com/watch?v=gvW-FlZG7Sg',NULL,196610,3);
INSERT INTO stanza VALUES('S2143','1','Yo soy el pan vivo,<br/>Que descendió del cielo;<br/>Si alguno,<br/>Si alguno come de este pan,<br/>Vivirá para siempre.<br/>',NULL,196611,1);
INSERT INTO stanza VALUES('S2143','chorus','Y el pan (y el pan),<br/>Que daré (que daré)<br/>Es Mi carne,<br/>La cual Yo (la cual Yo),<br/>Daré por (por)<br/>La vida del mundo.<br/>',NULL,196612,2);
INSERT INTO stanza VALUES('S2143','SoundCloud Link','https://soundcloud.com/damarisleg/yo-soy-el-pan-vivo-i-am-the-living-bread',NULL,196613,3);
INSERT INTO stanza VALUES('S2144','1','Aparta tus ojos de delante de mí,<br/>Porque ellos me vencieron,<br/>Has cautivado mi corazón<br/>Con uno de tus ojos. (x2)<br/>',NULL,196614,1);
INSERT INTO stanza VALUES('S2144','chorus','Prendiste mi corazón<br/>Hermana mía,<br/>Cuanto mejores que el vino tus amores.<br/>',NULL,196615,2);
INSERT INTO stanza VALUES('S2144','2','He aquí tu eres hermosa,<br/>Amiga mía,<br/>He aquí eres bella,<br/>Tus ojos son como paloma. (x2)<br/>',NULL,196616,3);
INSERT INTO stanza VALUES('S2144','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/aparta-tus-ojos-de-delante-de',NULL,196617,4);
INSERT INTO stanza VALUES('S2145','1','Un limpio corazón<br/>Crea en mi, oh Dios,<br/>Y renueva un espíritu firme en mí.<br/>Un limpio corazón<br/>Crea en mi, oh Dios,<br/>Y renueva un espíritu firme en mí.<br/>',NULL,196618,1);
INSERT INTO stanza VALUES('S2145','chorus','No me arrojes de Tu presencia,<br/>Tu Espíritu santo no quites de mí.<br/>Devuélveme la alegría de ser salvo,<br/>Y renueva un espíritu recto en mí.<br/>',NULL,196619,2);
INSERT INTO stanza VALUES('S2146','1','A quien, sin verle aún,<br/>Amáis (amáis);<br/>En quien,<br/>Aunque ahora no le veas,<br/>Creyendo: (x2)<br/>',NULL,196620,1);
INSERT INTO stanza VALUES('S2146','2','Os alegráis con gozo<br/>Que es inefable y<br/>Colmado de gloria. (x2).<br/>(1 P. 1:8)<br/>',NULL,196621,2);
INSERT INTO stanza VALUES('S2146','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2146_a-quien-sin-verle-au-n',NULL,196622,3);
INSERT INTO stanza VALUES('S2147','1','No tenemos un<br/>Sumo Sacerdote,<br/>Que no pueda compadecerse de<br/>Nuestras debilidades<br/>Sino uno que fue tentado<br/>En todo igual, más sin pecado.<br/>Acerquémonos, pues,<br/>Confiadamente al trono de gracia<br/>Para recibir misericordia<br/>Y hallar gracia.<br/>',NULL,196623,1);
INSERT INTO stanza VALUES('S2147','chorus','##[Optional: Puede ser cantado con #2158]##<br/>',NULL,196624,2);
INSERT INTO stanza VALUES('S2147','2','## [#2158] ##<br/>Y sabemos que<br/>A los que aman a Dios;<br/>A los que_aman a Dios<br/>Todas las cosas<br/>Cooperan para bien.<br/>Esto es a los que<br/>Conforme a Su propósito<br/>Son llamados;<br/>Lo dice en<br/>Romanos 8:28.<br/>',NULL,196625,3);
INSERT INTO stanza VALUES('S2147','SoundCloud Link','https://soundcloud.com/eric-aguilar-921081480/he-4-15-porque-no-tenemos-un',NULL,196626,4);
INSERT INTO stanza VALUES('S2148','chorus','OSEAS 11:4<br/>',NULL,196627,1);
INSERT INTO stanza VALUES('S2148','1','Los atraje<br/>Con cuerdas de hombre,<br/>Con lazos de amor...<br/>Fui para ellos como<br/>Los que alzan el yugo<br/>De sus quijadas.<br/>Con ternura les di de comer.<br/>Con ternura les di de comer.<br/>',NULL,196628,2);
INSERT INTO stanza VALUES('S2148','chorus','HEBREOS 7:25<br/>',NULL,196629,3);
INSERT INTO stanza VALUES('S2148','2','Por lo cual puede también<br/>Salvar por completo<br/>Los que se acercan a Dios<br/>Por El. (Por El).<br/>Pues vive siempre<br/>Intercediendo por ellos.<br/>Pues vive siempre<br/>Intercediendo por ellos.<br/>',NULL,196630,4);
INSERT INTO stanza VALUES('S2148','chorus','HEBREOS 4:15-16<br/>',NULL,196631,5);
INSERT INTO stanza VALUES('S2148','3','No tenemos un<br/>Sumo Sacerdote,<br/>Que no pueda compadecerse de<br/>Nuestras debilidades<br/>Sino uno que fue tentado<br/>En todo igual, más sin pecado.<br/>Acerquémonos, pues,<br/>confiadamente al trono de gracia<br/>Para recibir misericordia<br/>Y hallar gracia.<br/>',NULL,196632,6);
INSERT INTO stanza VALUES('S2148','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2148-los-atraje-con-cuerdas',NULL,196633,7);
INSERT INTO stanza VALUES('S2149','1','¡Oh, si me besara,<br/>Con los besos de Su boca!<br/>Porque mejores son Sus amores<br/>Que el vino.<br/>',NULL,196634,1);
INSERT INTO stanza VALUES('S2149','2','Tu ungüento<br/>Tiene olor agradable.<br/>Tu nombre_es como ungüento<br/>Derramado.<br/>',NULL,196635,2);
INSERT INTO stanza VALUES('S2149','3','Por eso las<br/>Doncellas Te aman.<br/>Atráeme,<br/>En pos de Ti correremos,<br/>El Rey me ha metido en Sus cámaras.<br/>',NULL,196636,3);
INSERT INTO stanza VALUES('S2149','4','Nos gozaremos<br/>Y alegraremos en Ti.<br/>Alabaremos Tus amores<br/>Más que el vino,<br/>Con razón Te aman.<br/>',NULL,196637,4);
INSERT INTO stanza VALUES('S2149','SoundCloud Link','https://soundcloud.com/user-631728043-431161926/oh-si-me-besara',NULL,196638,5);
INSERT INTO stanza VALUES('S2150','1','Donde vayas tú, yo iré,<br/>Donde mores tú, moraré;<br/>Tu pueblo será mi pueblo,<br/>Y tu Dios será mi Dios.(x2)<br/>',NULL,196639,1);
INSERT INTO stanza VALUES('S2150','2','Donde mueras tú, moriré;<br/>Y allí seré enterrada.<br/>Que haga así Jehová,<br/>Y aún haga más,<br/>Sólo morir me apartará de ti.<br/>Que haga así Jehová,<br/>Y aún haga más,<br/>Sólo morir me apartará de ti.<br/>',NULL,196640,2);
INSERT INTO stanza VALUES('S2150','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/ruth-1-16-17-donde-vayas-tu-1',NULL,196641,3);
INSERT INTO stanza VALUES('S2151','1','Alabad a nuestro Dios<br/>En Su santuario;<br/>Por la hermosura de Su cielo,<br/>Por Sus proezas, alabadle a Él.<br/>',NULL,196642,1);
INSERT INTO stanza VALUES('S2151','2','Alabadle,<br/>Por la grandeza de Su nombre,<br/>Con el sonido de bocina,<br/>Salterio y arpa, a la vez cantad.<br/>',NULL,196643,2);
INSERT INTO stanza VALUES('S2151','3','Alabadle con el alegre pandero,<br/>Con el candor de la danza,<br/>Cantad con gozo al Señor.<br/>',NULL,196644,3);
INSERT INTO stanza VALUES('S2151','4','Alabadle con cuerdas,<br/>Flautas y címbalos,<br/>De júbilo resonantes,<br/>En su lenguaje - Todo –<br/>Lo que respira alabe a Jehová.<br/>Lo que respira alabe a Jehová.<br/>¡Amén!<br/>',NULL,196645,4);
INSERT INTO stanza VALUES('S2151','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/salmo-150-todo-lo-que-2',NULL,196646,5);
INSERT INTO stanza VALUES('S2152','1','Solamente que os comportéis<br/>Como es digno<br/>Del evangelio de Cristo,<br/>Para que o sea que vaya a veros,<br/>O que esté ausente,<br/>Oiga de vosotros que estáis firmes<br/>En un mismo espíritu,<br/>Combatiendo unánimes<br/>Junto con la fe del evangelio.<br/>',NULL,196647,1);
INSERT INTO stanza VALUES('S2152','SoundCloud Link','https://soundcloud.com/user-518979615/fil-1-27',NULL,196648,2);
INSERT INTO stanza VALUES('S2153','chorus','Porque todo aquel que invoque<br/>El Nombre del Señor será salvo.<br/>',NULL,196649,1);
INSERT INTO stanza VALUES('S2153','1','Cerca de ti está la palabra,<br/>En tu boca y en tu corazón.<br/>Esta es la palabra de la fe<br/>Que proclamamos.<br/>',NULL,196650,2);
INSERT INTO stanza VALUES('S2153','chorus','Porque todo aquel que invoque<br/>El Nombre del Señor será salvo.<br/>',NULL,196651,3);
INSERT INTO stanza VALUES('S2153','2','Que si confiesas con tu boca<br/>A Jesús como Señor,<br/>Y crees en tu corazón,<br/>Serás salvo!!<br/>',NULL,196652,4);
INSERT INTO stanza VALUES('S2153','chorus','Porque todo aquel que invoque<br/>El Nombre del Señor será salvo.<br/>',NULL,196653,5);
INSERT INTO stanza VALUES('S2153','3','Porque con el corazón<br/>Se cree para justicia,<br/>Y con la boca se confiesa salvación.<br/>Todo aquel que en Él crea,<br/>No será avergonzado!<br/>',NULL,196654,6);
INSERT INTO stanza VALUES('S2153','chorus','Porque todo aquel que invoque<br/>El Nombre del Señor será salvo.<br/>',NULL,196655,7);
INSERT INTO stanza VALUES('S2153','4','Porque no hay distinción<br/>Entre judío y griego,<br/>Pues el mismo Señor,<br/>Es Señor de todos!<br/>Y es rico para con todos<br/>Los que le invocan!<br/>',NULL,196656,8);
INSERT INTO stanza VALUES('S2153','chorus','Porque todo aquel que invoque<br/>El Nombre del Señor será salvo.<br/>',NULL,196657,9);
INSERT INTO stanza VALUES('S2153','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/porque-todo-aquel-que-invoque',NULL,196658,10);
INSERT INTO stanza VALUES('S2154','1','Jehová es mi luz y mi salvación.<br/>¿De quién temeré?<br/>Él es mi fortaleza.<br/>Cuando se juntaron contra mí,<br/>Mis enemigos,<br/>Mis angustiadores,<br/>Aunque un ejército acampe contra mí,<br/>No temerá mi corazón.<br/>Aunque contra mí<br/>Se levanten guerras,<br/>Yo viviré confiado.<br/>Pues una cosa<br/>Yo he demandado a mi Dios<br/>Y esa buscaré:<br/>Vivir en Tu casa<br/>Todos los días de mi existencia;<br/>Y contemplar Tu hermosura<br/>E inquirir en Tu templo, Señor.<br/>',NULL,196659,1);
INSERT INTO stanza VALUES('S2154','SoundCloud Link','https://soundcloud.com/user-871371384/jehova-es-mi-luz-y-mi',NULL,196660,2);
INSERT INTO stanza VALUES('S2155','1','Vida y muerte_he puesto frente a ti,<br/>Bendición y maldición,<br/>Escoge, pues la vida<br/>Para que vivas tú.<br/>Vida y muerte_he puesto frente a ti,<br/>Bendición y maldición,<br/>Escoge, pues la vida<br/>Para que vivas tú.<br/>',NULL,196661,1);
INSERT INTO stanza VALUES('S2155','chorus','Amando a Jehová tu Dios<br/>Al escuchar Su voz<br/>Y estar asido de Él<br/>Porque vida es Dios.<br/>Amando a Jehová tu Dios<br/>Al escuchar Su voz<br/>Y estar asido de Él<br/>Porque vida es Dios,<br/>Vida para ti.<br/>',NULL,196662,2);
INSERT INTO stanza VALUES('S2155','SoundCloud Link','https://soundcloud.com/dani_candia/vida-y-muerte-he-puesto-frente-a-ti',NULL,196663,3);
INSERT INTO stanza VALUES('S2156','chorus','{Primera parte}:<br/>',NULL,196664,1);
INSERT INTO stanza VALUES('S2156','1','Y miré<br/>Al Cordero<br/>Y a ciento cuarenta y cuatro mil,<br/>Con el nombre<br/>De Su Padre<br/>Escrito en sus frentes.<br/>Estos son,<br/>Estos son<br/>Quienes siguen al Cordero.<br/>Estos son<br/>Para Dios;<br/>Siguen al Cordero de Dios,<br/>Doquiera que va.<br/>',NULL,196665,2);
INSERT INTO stanza VALUES('S2156','chorus','{Segunda parte}:<br/>',NULL,196666,3);
INSERT INTO stanza VALUES('S2156','2','Hermanas:     Y miré<br/>Hermanos:     Contemplé<br/>Hermanas:     Al Cordero<br/>Hermanos:     Sobre Sión<br/>Todos:        Y a ciento cuarenta y cuatro mil.<br/>Hermanas:     Con el nombre<br/>Hermanos:     El nombre<br/>Hermanas:     De Su Padre<br/>Hermanos:     De Su Padre<br/>Todos:        Escrito en sus frentes.<br/>Hermanas:     Estos son<br/>Hermanos:     Los no vencidos<br/>Hermanas:     Estos son<br/>Hermanos:     Sin astucia<br/>Todos:        Quienes siguen al Cordero.<br/>Hermanas:     Estos son<br/>Hermanos:     Los comprados<br/>Hermanas:     Para Dios<br/>Hermanos:     Las primicias<br/>Todos:        Siguen al Cordero de Dios,<br/>Doquiera que va.<br/>',NULL,196667,4);
INSERT INTO stanza VALUES('S2156','chorus','{Tercera parte}:<br/>',NULL,196668,5);
INSERT INTO stanza VALUES('S2156','3','Quienes siguen, al Cordero,<br/>Tienen un vivir, de espíritu mezclado;<br/>Son guiados, por el Espíritu<br/>Continuamente,<br/>Continuamente - a diario.<br/>',NULL,196669,6);
INSERT INTO stanza VALUES('S2156','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2156_y-mire-m4a',NULL,196670,7);
INSERT INTO stanza VALUES('S2157','1','El amor es sufrido,<br/>El amor es benigno,<br/>No tiene envidia,<br/>No se jacta<br/>Y no se hincha de orgullo. (x2)<br/>',NULL,196671,1);
INSERT INTO stanza VALUES('S2157','2','No se porta indecorosamente,<br/>No busca lo suyo,<br/>No se irrita<br/>Y no toma en cuenta el mal.<br/>No se goza de la injusticia<br/>Más se goza con la verdad.<br/>',NULL,196672,2);
INSERT INTO stanza VALUES('S2157','3','Todo lo cubre, todo lo cree,<br/>Todo lo espera, todo lo soporta,<br/>Nunca deja de ser,<br/>El amor nunca, nunca deja de ser,<br/>Nunca deja de ser.<br/>',NULL,196673,3);
INSERT INTO stanza VALUES('S2157','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/definicio-n-del-amor-i',NULL,196674,4);
INSERT INTO stanza VALUES('S2158','1','Y sabemos que<br/>A los que aman a Dios;<br/>A los que_aman a Dios<br/>Todas las cosas<br/>Cooperan para bien.<br/>Esto es a los que<br/>Conforme a Su propósito<br/>Son llamados;<br/>Lo dice en<br/>Romanos 8:28.<br/>',NULL,196675,1);
INSERT INTO stanza VALUES('S2158','chorus','[Optional: Puede ser cantado con #2147]<br/>',NULL,196676,2);
INSERT INTO stanza VALUES('S2158','2','## [#2147] ##<br/>No tenemos un<br/>Sumo Sacerdote,<br/>Que no pueda compadecerse de<br/>Nuestras debilidades<br/>Sino uno que fue tentado<br/>En todo igual, más sin pecado.<br/>Acerquémonos, pues,<br/>Confiadamente al trono de gracia<br/>Para recibir misericordia<br/>Y hallar gracia.<br/>',NULL,196677,3);
INSERT INTO stanza VALUES('S2159','1','No considero haberlo ya asido;<br/>Ahora pues,<br/>¿Qué he de hacer?<br/>Lo que queda atrás<br/>Lo olvido, lo olvido<br/>Y me extiendo al Cristo<br/>Delante de mí.<br/>Hasta la meta he de seguir,<br/>Para alcanzar<br/>El premio del llamamiento<br/>Que hace Dios en Cristo Jesús.<br/>',NULL,196678,1);
INSERT INTO stanza VALUES('S2160','1','Por esta causa doblo mis rodillas<br/>Ante el Padre de nuestro Señor,<br/>De quien toma nombre toda familia<br/>En los cielos y en la tierra también.<br/>Para que os dé conforme a las riquezas<br/>De Su gloria, fortalecidos ser<br/>Con poder en el hombre interior<br/>Por medio de Su Santo Espíritu.<br/>',NULL,196679,1);
INSERT INTO stanza VALUES('S2160','2','Para que Cristo en vuestros corazones,<br/>Haga Su hogar por medio de la fe,<br/>A fin de que, en amor arraigados<br/>Y cimentados, capaces seáis<br/>De comprender con todos los santos<br/>Cuál sea la anchura y la longitud,<br/>Y la altura y la profundidad,<br/>Y conocer de Cristo el amor.<br/>',NULL,196680,2);
INSERT INTO stanza VALUES('S2160','3','Y conocer de Cristo el amor<br/>Que sobrepasa todo entender,<br/>Para que totalmente seáis llenos<br/>Hacia toda la plenitud de Dios.<br/>Haz Tu hogar en nuestros corazones,<br/>Seamos capaces para comprender<br/>Tus dimensiones y Tu inmensidad,<br/>Señor Jesús, y Tu inclusividad.<br/>',NULL,196681,3);
INSERT INTO stanza VALUES('S2160','YouTube Link','https://www.youtube.com/watch?v=fLXKFxKWqGg',NULL,196682,4);
INSERT INTO stanza VALUES('S2161','1','Conservaos en el amor de Dios,<br/>Esperando la misericordia<br/>De nuestro Señor Jesucristo<br/>Para vida eterna.<br/>',NULL,196683,1);
INSERT INTO stanza VALUES('S2161','2','Y Aquel que es poderoso<br/>Para guardaros de tropiezos,<br/>Y presentaros sin mancha delante<br/>De Su gloria con gran alegría.<br/>',NULL,196684,2);
INSERT INTO stanza VALUES('S2161','3','Al único y sabio Dios,<br/>Nuestro Salvador,<br/>Sea gloria y majestad,<br/>Imperio y potestad,<br/>Ahora y por todos los siglos,<br/>Ahora y por todos los siglos. Amén.<br/>',NULL,196685,3);
INSERT INTO stanza VALUES('S2161','SoundCloud Link','https://soundcloud.com/siul-baez/conservaos-en-el-amor-de-dios',NULL,196686,4);
INSERT INTO stanza VALUES('S2162','1','La meta del evangelio<br/>Es que, amando al Señor<br/>Con el primer amor,<br/>En El desperdiciamos,<br/>Y abandonamos<br/>Lo que es precioso a nos.<br/>Nuestros más valiosos tesoros<br/>Espirituales,<br/>Desperdiciamos en Él.<br/>Nuestros más valiosos tesoros,<br/>Y lo que somos,<br/>Desperdiciamos en Él.<br/>',NULL,196687,1);
INSERT INTO stanza VALUES('S2163','1','Si en nosotros hay un amor<br/>Afectuoso por el Señor Jesús,<br/>Nuestra lengua sería como pluma<br/>De ágil escribiente y estará<br/>Presta a escribir de nuestro amor<br/>Y de nuestra alabanza a Él,<br/>Con la experiencia y disfrute de Él,<br/>Según todo lo,<br/>Según todo lo,<br/>Según todo lo que Él es.<br/>',NULL,196688,1);
INSERT INTO stanza VALUES('S2163','SoundCloud Link','https://soundcloud.com/mateus-gomes-622910749/si-en-nostros-hay-un-amor',NULL,196689,2);
INSERT INTO stanza VALUES('S2164','1','El ministerio del nuevo pacto,<br/>Un ministerio de Dios.<br/>Es el ministerio del Espíritu que da vida<br/>Y el ministerio de la justicia<br/>Como expresión de Dios.<br/>',NULL,196690,1);
INSERT INTO stanza VALUES('S2164','2','Los ministros del nuevo pacto son personas cuyos corazones<br/>Se han vuelto al Señor, quienes disfrutan al Señor como el<br/>Espíritu y quienes están siendo transformados a la imagen<br/>Del Señor, al mirarle y reflejarle.<br/>',NULL,196691,2);
INSERT INTO stanza VALUES('S2164','3','Los ministros del nuevo pacto son embajadores de Cristo,<br/>Que llevan a cabo el ministerio de la reconciliación,<br/>Con el fin de introducirlos en Dios y hacerlos uno con Él.<br/>',NULL,196692,3);
INSERT INTO stanza VALUES('S2164','4','El vivir de los ministros<br/>Del nuevo pacto<br/>Es un vivir lleno de Gracia,<br/>Un vivir en el que experimentan<br/>La gracia la cual es la<br/>Trinidad Divina transmitida<br/>A nosotros para nuestro disfrute.<br/>',NULL,196693,4);
INSERT INTO stanza VALUES('S2165','1','El Cristo todo inclusivo, la centralidad y universalidad<br/>De la economía de Dios, es nuestra vida y el único elemento<br/>constitutivo del nuevo hombre.<br/>',NULL,196694,1);
INSERT INTO stanza VALUES('S2165','2','Debemos andar en Cristo nuestra tierra viva y absorber a Cristo<br/>Nuestro rico suelo, a fin de crecer con el crecimiento de Dios.<br/>',NULL,196695,2);
INSERT INTO stanza VALUES('S2165','3','Dios en Su economía nos provee una sola persona,<br/>El Cristo todo inclusivo, extenso y preeminente,<br/>Y un solo camino, la cruz.<br/>',NULL,196696,3);
INSERT INTO stanza VALUES('S2165','4','Debemos permitir que la paz de Cristo sea el árbitro<br/>En nuestros corazones, dejar que la palabra de Cristo<br/>More ricamente en nosotros. Y perseverar en la oración<br/>Con miras al nuevo hombre.<br/>',NULL,196697,4);
INSERT INTO stanza VALUES('S2166','1','Amo a mi Amo<br/>Y libre yo no saldré,<br/>Pues Él murió por mí,<br/>Un alto precio Él pagó por mi.<br/>Amo a mi Amo<br/>Y servirle es mi elección,<br/>Permanecer cerca de Él<br/>Es mi oración.<br/>',NULL,196698,1);
INSERT INTO stanza VALUES('S2166','chorus','Te amo mi Amo,<br/>De Ti nunca me iré;<br/>Mi gozo eres Tú y mi libertad.<br/>Amo a mi Amo<br/>Y libre yo no saldré;<br/>Mi vida y todo<br/>Eternamente a Ti te doy.<br/>',NULL,196699,2);
INSERT INTO stanza VALUES('S2166','2','Jesús, mi Amo,<br/>A la puerta tráeme,<br/>Horada mi oído<br/>Y ábrelo para oír Tu voz.<br/>Jesús, mi Amo,<br/>Hoy escojo obedecer;<br/>Mi ruego es amarte<br/>Y servirte a Ti.<br/>',NULL,196700,3);
INSERT INTO stanza VALUES('S2166','SoundCloud Link','https://soundcloud.com/dani-b-313753210/amo-a-mi-amo-traduccion-previsional-by-daniela-b-i-love-my-master-nycypcd',NULL,196701,4);
INSERT INTO stanza VALUES('S2167','1','Oh Jesús, cuánto te amo a Ti<br/>Hazme puro<br/>He de consagrar mis días<br/>A gustar Tu amor.<br/>Heme aquí, rindo todo a Ti<br/>Me atraes con<br/>Tu cuidado y compasiones<br/>Que no fallarán.<br/>Mi oreja horádame<br/>En el poste de Tu Hogar<br/>Respondiendo a Tu voz,<br/>Tuyo seré y tuyo siempre.<br/>Por sello en Tu corazón<br/>Ponme con Tu amor y celo<br/>Loco amante en mis días<br/>Déjame ser.<br/>',NULL,196702,1);
INSERT INTO stanza VALUES('S2167','2','De sabiduría y revelación<br/>Espíritu,<br/>Dios de Gloria, danos para<br/>El misterio ver.<br/>Por tu economía, mi Señor<br/>Mi vida doy<br/>Por el Cuerpo de Cristo,<br/>Por Tu buen placer.<br/>En mi espíritu llévame<br/>Del Cuerpo, a su realidad<br/>En Tu intensificación<br/>Haznos de Jesús testimonio<br/>¡Ven pronto, amado Señor!<br/>Y recuerda Tu promesa<br/>Nuestro único anhelo:<br/>Que vuelvas Tú.<br/>',NULL,196703,2);
INSERT INTO stanza VALUES('S2167','SoundCloud Link','https://soundcloud.com/user-820414938/oh-jesus-cuanto-te-amo-a-ti',NULL,196704,3);
INSERT INTO stanza VALUES('S2168','1','Si quieres ser parte<br/>De los que traerán al Señor<br/>Debes consagrarte<br/>Voluntariamente a Él,<br/>En tu espíritu vivir<br/>Disfrutar de Él<br/>Conocer Su corazón<br/>Y cooperar con Él.<br/>',NULL,196705,1);
INSERT INTO stanza VALUES('S2168','2','Tomemos hoy<br/>Resoluciones de corazón;<br/>Aceptemos ya<br/>El encargo del Señor:<br/>Prediquemos el evangelio,<br/>Guardemos la unidad,<br/>Seamos instrumentos<br/>Para la era consumar.<br/>',NULL,196706,2);
INSERT INTO stanza VALUES('S2168','SoundCloud Link','https://soundcloud.com/damarisleg/ser-parte-de-los-que-traeran',NULL,196707,3);
INSERT INTO stanza VALUES('S2169','1','Tu presencia trae gozo<br/>Y Tu vida me da paz,<br/>Tu Espíritu me unge,<br/>Renovándome está.<br/>Tu iglesia lograrás,<br/>Tu expresión así obtendrás.<br/>El deseo de Tu corazón<br/>Así lo lograrás.<br/>',NULL,196708,1);
INSERT INTO stanza VALUES('S2169','2','Cuando yo de Ti me aparto,<br/>Tu Espíritu me busca<br/>Y me da arrepentimiento,<br/>Para que me vuelva a Ti.<br/>Tu amor me sostendrá<br/>Para no apartarme de Ti.<br/>El deseo de Tu corazón<br/>Así lo lograrás.<br/>',NULL,196709,2);
INSERT INTO stanza VALUES('S2169','3','Tu palabra me ilumina<br/>Y me da arrepentimiento,<br/>Para obtener perdón<br/>Y seguir en comunión.<br/>Tu unción me guiará,<br/>En ti me sostendrá.<br/>El deseo de tu corazón<br/>Así lo lograrás<br/>',NULL,196710,3);
INSERT INTO stanza VALUES('S2169','4','Con Su sangre nos lavó<br/>De todos nuestros pecados<br/>Y nos hizo sacerdotes<br/>Para servirle a Él.<br/>A Tu lado permaneceré<br/>Y no te dejaré.<br/>El deseo de Tu corazón<br/>Así lo lograrás.<br/>',NULL,196711,4);
INSERT INTO stanza VALUES('S2169','5','Torno mi ser ante Ti,<br/>Tu roció me refresca.<br/>Te veo y Tu belleza<br/>Quebranta mi corazón.<br/>Ante Ti quiero estar,<br/>En Tu presencia permanecer.<br/>El deseo de Tu corazón<br/>Así lo lograrás.<br/>',NULL,196712,5);
INSERT INTO stanza VALUES('S2169','SoundCloud Link','https://soundcloud.com/ymalv/el-deseo-de-tu-corazon-asi-lo',NULL,196713,6);
INSERT INTO stanza VALUES('S2170','1','Por qué os preocupáis diciendo:<br/>Qué comeremos?<br/>Por qué os afanais diciendo:<br/>Qué hemos de vestir?<br/>Por qué os preocupáis diciendo:<br/>Qué beberemos?<br/>Porque los gentiles<br/>Buscan con afán estas cosas.<br/>',NULL,196714,1);
INSERT INTO stanza VALUES('S2170','chorus','Mas buscad primeramente<br/>El reino de Dios y Su justicia<br/>Y todas estas cosas os serán añadidas.<br/>Mas buscad primeramente<br/>El reino de Dios y Su justicia<br/>Y todas estas cosas os serán añadidas.<br/>',NULL,196715,2);
INSERT INTO stanza VALUES('S2170','2','Mirad y velad también<br/>Por vosotros mismos,<br/>No sea que vuestros corazones<br/>Se carguen<br/>De disipasión, embriagués,<br/>Y afanes de esta vida;<br/>Rogad al Senor que escapéis<br/>De todas éstas cosas.<br/>',NULL,196716,3);
INSERT INTO stanza VALUES('S2170','3','No acumuléis tesoros en esta tierra<br/>Donde los ladrones horadan y hurtan;<br/>Sino acomulad tesoros en los cielos;<br/>Porque donde está tu tesoro,<br/>Allí está tu corazón.<br/>',NULL,196717,4);
INSERT INTO stanza VALUES('S2170','SoundCloud Link','https://soundcloud.com/melissa-c-jara/mas-buscad-primeramente-el',NULL,196718,5);
INSERT INTO stanza VALUES('S2171','1','¡Soy un loco amante del Señor!<br/>Cada día más Te amo.<br/>Tu belleza me ha atraído.<br/>Y anhelo Tu dulce abrazo<br/>Cara a cara vernos<br/>Mil veces vuelvo hoy mi corazón, pues yo:<br/>',NULL,196719,1);
INSERT INTO stanza VALUES('S2171','chorus','¡Te amo!<br/>¡Señor, Te amo!<br/>Sí, es cierto,<br/>¡Estoy enamorado de Ti!<br/>',NULL,196720,2);
INSERT INTO stanza VALUES('S2171','2','Los formalismos acabé;<br/>Quiero estar simplemente en<br/>Mi espíritu donde vives Tú.<br/>Lo que soy, tengo y pueda hacer<br/>Sólo será para amarte.<br/>Mil veces vuelvo hoy mi corazón, pues yo:<br/>',NULL,196721,3);
INSERT INTO stanza VALUES('S2171','chorus','¡Te amo!<br/>¡Señor, Te amo!<br/>Sí, es cierto,<br/>¡Estoy enamorado de Ti!<br/>',NULL,196722,4);
INSERT INTO stanza VALUES('S2171','note','**[Puente:]**<br/>Olvida ser perfecto.<br/>Olvida ser correcto.<br/>Olvida lo que eres o no eres.<br/>(¡Olvída todo!)<br/>El siempre está buscando<br/>Extenderse en nosotros,<br/>Poder hacer Su hogar en nos.<br/>Vuelve‿a‿El tu corazón, dile:<br/>',NULL,196723,5);
INSERT INTO stanza VALUES('S2171','chorus','¡Te amo!<br/>¡Señor, Te amo!<br/>Sí, es cierto,<br/>¡Estoy enamorado de Ti! (x2)<br/>De Ti.<br/>',NULL,196724,6);
INSERT INTO stanza VALUES('S2172','1','Quiero ser hallado en Cristo,<br/>En Sus entrañas vivir;<br/>Que mi corazón Él gane<br/>Y se exprese Él en mí.<br/>',NULL,196725,1);
INSERT INTO stanza VALUES('S2172','chorus','Yo me abro a Ti,<br/>Vive en mí, Señor;<br/>Tus internas partes llenen<br/>Hoy mi corazón.<br/>',NULL,196726,2);
INSERT INTO stanza VALUES('S2172','2','Sea mi mente renovada,<br/>Pon la tuya hoy en mí;<br/>Haya en mi Tú pensamiento,<br/>No en mi vanidad vivir.<br/>',NULL,196727,3);
INSERT INTO stanza VALUES('S2172','3','Que Tu celo por Su casa<br/>Arda en mí como en Ti;<br/>Que consuma otro anhelo,<br/>Por la iglesia yo existir.<br/>',NULL,196728,4);
INSERT INTO stanza VALUES('S2172','4','No mi voluntad se haga,<br/>Sino lo que escojas Tú;<br/>Aunque signifique muerte<br/>¡Oh, que prevalezcas Tú!<br/>',NULL,196729,5);
INSERT INTO stanza VALUES('S2172','5','Que Tu mente y sentimientos,<br/>Se establezcan hoy en mí;<br/>No vivir según yo escoja.<br/>¡Oh, que Cristo viva en mí!<br/>',NULL,196730,6);
INSERT INTO stanza VALUES('S2172','SoundCloud Link','https://soundcloud.com/user-944534727/anhelos-vivir-en-las-partes-internas-de-cristo',NULL,196731,7);
INSERT INTO stanza VALUES('S2173','1','¿Cuándo ha de venir,<br/>Oh Señor, el reino de Dios?<br/>No vendrá de modo que se<br/>Pueda ver.<br/>Ni dirán "Helo aquí",<br/>Porque el reino de Dios,<br/>Éste está en vosotros hoy.<br/>',NULL,196732,1);
INSERT INTO stanza VALUES('S2173','chorus','El reino es,<br/>El Señor Jesucristo,<br/>Sembrado en nuestro corazón.<br/>Hasta llegar<br/>A ser una_esfera_en la<br/>Cual Dios puede gobernar.<br/>',NULL,196733,2);
INSERT INTO stanza VALUES('S2173','2','Como un hombre_Él salió<br/>Y en la tierra se sembró<br/>La semilla de la vida divina.<br/>Esta vida al crecer,<br/>Extendiéndose al corazón,<br/>El desarrollo del reino es.<br/>',NULL,196734,3);
INSERT INTO stanza VALUES('S2173','3','Donde Él está el reino está.<br/>Extiéndete a mi pensar,<br/>A mi emoción, a mi voluntad<br/>Y haz Tu hogar.<br/>Gobierna todo el corazón.<br/>Te cedo el terreno yo;<br/>Tu trono en mi<br/>Establece hoy.<br/>',NULL,196735,4);
INSERT INTO stanza VALUES('S2173','SoundCloud Link','https://soundcloud.com/user-944534727/cuando-ha-de-venir',NULL,196736,5);
INSERT INTO stanza VALUES('S2174','1','Tu plan, Señor, es la iglesia edificar,<br/>Lograda de entre la humanidad.<br/>Tu plan, Señor, antes de la fundación,<br/>Introducirte al hombre<br/>Y crecer dentro de él.<br/>',NULL,196737,1);
INSERT INTO stanza VALUES('S2174','chorus','Es Tu plan la iglesia edificar,<br/>Para que sea Tu duplicación.<br/>Produciendo en la tierra<br/>Tu expresión total.<br/>Es Tu plan la iglesia edificar.<br/>',NULL,196738,2);
INSERT INTO stanza VALUES('S2174','2','La esencia interior<br/>De la iglesia universal<br/>Es la que está en cada localidad.<br/>No hay división, sino unanimidad.<br/>No hay diferencia,<br/>Ni distingo personal.<br/>',NULL,196739,3);
INSERT INTO stanza VALUES('S2174','chorus','Es Tu plan la iglesia edificar,<br/>Para que sea Tu duplicación.<br/>Produciendo en la tierra<br/>Tu expresión total.<br/>Es Tu plan la iglesia edificar.<br/>',NULL,196740,4);
INSERT INTO stanza VALUES('S2174','3','No en lo exterior, ni con organización;<br/>La iglesia es una vida que nació.<br/>Se engendró, dentro de mi espíritu,<br/>Nació del nuevo hombre,<br/>A cumplir Tu eterno plan.<br/>',NULL,196741,5);
INSERT INTO stanza VALUES('S2174','chorus','Es Tu plan la iglesia edificar,<br/>Para que sea Tu duplicación.<br/>Produciendo en la tierra<br/>Tu expresión total.<br/>Es Tu plan la iglesia edificar.<br/>',NULL,196742,6);
INSERT INTO stanza VALUES('S2174','4','En la comunión, en la plenitud de Dios,<br/>Es donde está la edificación.<br/>Al orar, al leer, te liberas, Oh Señor,<br/>Para dispensarte, y lograr Tu cuidad.<br/>',NULL,196743,7);
INSERT INTO stanza VALUES('S2174','chorus','Es Tu plan la Nueva Jerusalén.<br/>Su final: Tu esposa lograr ser,<br/>Formada de vencedores<br/>Y del Triuno Dios.<br/>Es Tu plan la Nueva Jerusalén.<br/>',NULL,196744,8);
INSERT INTO stanza VALUES('S2174','SoundCloud Link','https://soundcloud.com/user-952134958/tu-plan-senor',NULL,196745,9);
INSERT INTO stanza VALUES('S2175','1','El Triuno Dios se ha procesado,<br/>Espíritu llegó a ser,<br/>Quiere forjarse hoy en nosotros<br/>Y saturarnos con Su ser.<br/>Dios es Triuno, ¡Aleluya, amén!<br/>En mi espiritu disfruto de Él.<br/>Si le crees y recibes en tu ser<br/>Puedes disfrutarlo tú también.<br/>',NULL,196746,1);
INSERT INTO stanza VALUES('S2175','SoundCloud Link','https://soundcloud.com/damarisleg/dios-es-triuno?in=oralia-hern-ndez/sets/amaras-al-senor',NULL,196747,2);
INSERT INTO stanza VALUES('S2176','1','La iglesa, edificación<br/>De todos los que Dios llamó,<br/>Regeneró, y transformó.<br/>La ultima obra de Dios<br/>El nuevo hombre de Su plan,<br/>Los siete candeleros,<br/>Casa de Dios, el Cuerpo de Cristo,<br/>El deseo de Su corazón.<br/>',NULL,196748,1);
INSERT INTO stanza VALUES('S2176','2','Gloria a Dios. Filadelfia!<br/>Guardan Su palabra,<br/>Nunca niegan Su nombre.<br/>Aunque es la iglesia local,<br/>Tienen comunión universal,<br/>Ellos son el cuerpo de Cristo,<br/>El terreno de la unidad.<br/>',NULL,196749,2);
INSERT INTO stanza VALUES('S2176','3','Creced! Despertad!<br/>Ministrar a Cristo a los hombres,<br/>Llegad a la unidad.<br/>Que Tu plan veamos Señor,<br/>Ten misericordia<br/>Haznos fieles, que podamos,<br/>Tu iglesia edificar.<br/>',NULL,196750,3);
INSERT INTO stanza VALUES('S2176','YouTube Link','https://www.youtube.com/watch?v=oX79NNoNaLI',NULL,196751,4);
INSERT INTO stanza VALUES('S2176','SoundCloud Link','https://soundcloud.com/damarisleg/la-iglesia-edificacion-the',NULL,196752,5);
INSERT INTO stanza VALUES('S2177','1','La Palabra profética tenemos<br/>A la cual debemos estar atentos<br/>Como_a_una lampara<br/>Que en lo oscuro<br/>Alumbra, hasta que amanezca,<br/>',NULL,196753,1);
INSERT INTO stanza VALUES('S2177','chorus','// Y la estrella<br/>De la mañana<br/>Nazca en nuestro corazón.//<br/>',NULL,196754,2);
INSERT INTO stanza VALUES('S2177','YouTube Link','https://www.youtube.com/watch?v=gAvI7Il3EV4',NULL,196755,3);
INSERT INTO stanza VALUES('S2178','1','//Por tanto,<br/>No nos desanimamos!<br/>Aunque<br/>Nuestro hombre<br/>Exterior se va desgastando.<br/>No obstante,<br/>el hombre interior se<br/>Renueva,<br/>Renueva,<br/>De dia -<br/>En dia.//<br/>',NULL,196756,1);
INSERT INTO stanza VALUES('S2178','chorus','//Porque ésta leve<br/>Tribulación momentánea,<br/>Produce en nosotros<br/>Un cada vez<br/>Más excelente y eterno peso...<br/>Excelente y erterno, -<br/>Excelente y erterno, -<br/>Eterno peso<br/>De gloria. //<br/>',NULL,196757,2);
INSERT INTO stanza VALUES('S2178','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2178_por-tanto-no-nos',NULL,196758,3);
INSERT INTO stanza VALUES('S2179','1','¿Cuándo vas a volver,<br/>Mi Señor, otra vez?<br/>No tardes en<br/>Volver otra vez (otra vez).<br/>Diariamente, Señor,<br/>Lléname más de Ti,<br/>Tómame, llévame hasta el fin.<br/>',NULL,196759,1);
INSERT INTO stanza VALUES('S2179','chorus','¡Ven! ¡Oh Cristo!<br/>¡Jesús, mi amor, Precioso!<br/>Apresura Tu venir! (ven a mi!).<br/>Me consumas!<br/>A Tu guiar soy fiel<br/>Pues desviarme no podré.<br/>',NULL,196760,2);
INSERT INTO stanza VALUES('S2179','2','Haz Tu hogar hoy en mi<br/>Corazón hasta el fin,<br/>Oh Señor! todo es para Ti,<br/>(para Ti).<br/>Eres Tu superior,<br/>Reina en todo, mi Señor;<br/>Poséeme!_Este es mi clamor.<br/>',NULL,196761,3);
INSERT INTO stanza VALUES('S2179','3','En mi_oración e intercesión,<br/>Sé mi eterna inspiración;<br/>Saturado_esté mi ser de Ti,<br/>(sí de Ti).<br/>Diariamente siendo así<br/>Esperando aquí por Ti,<br/>Clamo a Ti, todo lo rendí.<br/>',NULL,196762,4);
INSERT INTO stanza VALUES('S2179','4','El universo al contemplar -<br/>Tu dulce "toque" puedo hallar,<br/>Mi destino eres Tu en verdad,<br/>(en verdad).<br/>Aunque me cueste_esperar<br/>Ven Amado, sin tardar,<br/>Mi amor, te quiero abrazar.<br/>',NULL,196763,5);
INSERT INTO stanza VALUES('S2179','5','Costreñido en Tu amor<br/>Que mi ser conquistó,<br/>Ya no puedo resistir Señor.<br/>(Señor)<br/>Mi amor_quiero derramar<br/>-Ésto elijo, sin dudar-<br/>Novia hermosa Tu iglesia será.<br/>',NULL,196764,6);
INSERT INTO stanza VALUES('S2179','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2179_cua-ndo-vas-a-volver-mi',NULL,196765,7);
INSERT INTO stanza VALUES('S2180','1','Antes de la creación del mundo<br/>Escogido yo fui<br/>Por el Padre en amor;<br/>A fin de ser santo, sin mancha<br/>Por el puro afecto de Su voluntad.<br/>Dame Señor, un puro corazón,<br/>Que es sencillo, está en paz,<br/>Y solo te ama a Ti;<br/>Que solo anhela<br/>En Tu presencia estar:<br/>Ser santificado en mi vivir.<br/>',NULL,196766,1);
INSERT INTO stanza VALUES('S2180','2','Quiero Señor, aunque soy jóven,<br/>Ser santo, distinto y puro en mi vivir.<br/>Todo mi amor es para Ti;<br/>Fiel, prudente y sumiso yo Te serviré.<br/>Con mis fuerzas Señor,<br/>Obediente seré;<br/>Por Tu dulce impartir,<br/>La piedad obtendré.<br/>En Tu preciosa sangre confiaré;<br/>Por Tu gracia yo en Ti creceré.<br/>',NULL,196767,2);
INSERT INTO stanza VALUES('S2180','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2180_antes-de-la-creacio-n-del',NULL,196768,3);
INSERT INTO stanza VALUES('S2181','1','Me embriaga Tu amor, tan fresco es,<br/>Tan tierno y dulce amor, me satura otra vez;<br/>Atado a Tu amor proseguiré,<br/>Y en Tu seno de amor me deleitaré.<br/>Es mi anhelo Señor de Tu amor gozar,<br/>Sumergido y envuelto estar.<br/>Tu estandarte en mi es Tu amor,<br/>Este amor eres Tu, mi Señor.<br/>',NULL,196769,1);
INSERT INTO stanza VALUES('S2181','2','Tú eres mi más precioso amor;<br/>Objeto de mi amor eres Tú, oh, Señor.<br/>Si sólo Tú me impartes salvación,<br/>Mi corazón jamás complacer podrás.<br/>¡Cómo anhelo, oh Señor, Tu amado ser!<br/>Eres Tu mi todo para mi.<br/>Tan lleno de amor estás Señor,<br/>Tu amor desarmó mi ser.<br/>',NULL,196770,2);
INSERT INTO stanza VALUES('S2181','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2181_me-embriaga-tu-amor-tan',NULL,196771,3);
INSERT INTO stanza VALUES('S2182','1','Desde que yo a Ti clamé,<br/>Ya mi vida no es igual,<br/>Al clamar comprendí que me salvaste.<br/>Vivía en desesperación,<br/>No sabiendo que eres real;<br/>Y ahora sé, Jesús, que vivo estás!<br/>',NULL,196772,1);
INSERT INTO stanza VALUES('S2182','chorus','Ahora puedo comprender<br/>Que sin Ti nada seré,<br/>Hasta que este Dios<br/>Ardiente more en mí.<br/>Mi sentir no cuenta ya<br/>Porque sé que eres real;<br/>Y también, Jesús, que vivo estás!<br/>',NULL,196773,2);
INSERT INTO stanza VALUES('S2182','2','Piensan que muy loco estoy;<br/>Pero no me importa hoy,<br/>Porque_eres Señor Palabra viva!<br/>Después de_ellos criticar,<br/>No comprenden que es real;<br/>Encontrar, Jesús, que vivo estás!<br/>',NULL,196774,3);
INSERT INTO stanza VALUES('S2182','3','Una_estatua Él no es,<br/>Ni_un retrato_en la pared,<br/>Sino_una persona que_en mí vive!<br/>Lo que quieres, Oh Señor,<br/>Una puerta abierta hoy;<br/>Y saber, Jesús, que vivo estás!<br/>',NULL,196775,4);
INSERT INTO stanza VALUES('S2182','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2182_desde-que-yo-a-ti-clame',NULL,196776,5);
INSERT INTO stanza VALUES('S2183','1','De mañana al ocaso<br/>Ve͡o su fidelidad.<br/>Y Su misericordia,<br/>Me‿ha de alzanzar.<br/>Y lo sé, sí lo sé.<br/>Su luz tan resplandeciente,<br/>Mi duda͜͜ ha de quitar;<br/>Y Su Palabra viviente‿es<br/>Dulce͜͜ a mi paladar;<br/>Y lo sé, ahora sé.<br/>',NULL,196777,1);
INSERT INTO stanza VALUES('S2183','chorus','Dios para mí está_accesible<br/>Hoy y͜͜ en cada͜͜ amanecer;<br/>Quitará mis ansiedades;<br/>Llevará mis penas Él.<br/>No hay crisis ni tormenta<br/>Que sean mayor que Él;<br/>Es mi Dios, es mi Dios.<br/>',NULL,196778,2);
INSERT INTO stanza VALUES('S2183','2','Cada di͡a Su gracia crece;<br/>Su͜͜ amor me conquistó,<br/>Y‿aun sin cesar me͜͜ inunda<br/>Su͜͜ Espíritu͜͜ a mí hoy.<br/>Al fluir me͜͜ alcanzó.<br/>Aun más alto que los cielos,<br/>Me͜͜ eleva para ver<br/>A Su novia que desciende,<br/>Nueva Jerusalén.<br/>Eternal Su͜͜ amor es.<br/>',NULL,196779,3);
INSERT INTO stanza VALUES('S2184','1','En una era de oscuridad<br/>De violencia y sin Dios<br/>Como en los días de Noé<br/>Y en los días de Lot.<br/>Así serán los días pues<br/>De la venida del Señor<br/>Por ello me consagro a Ti<br/>Hazme un vencedor<br/>',NULL,196780,1);
INSERT INTO stanza VALUES('S2184','chorus','Pero Noé- (pero Noé)<br/>Favor halló - (favor halló)<br/>Ante los ojos de Jehová (de Jehová).<br/>Y así Noé- (y así Noé)<br/>Edificó (edificó)<br/>Y de_esta_era maligna, el<br/>Con su familia se salvó<br/>',NULL,196781,2);
INSERT INTO stanza VALUES('S2184','2','Andar con Dios como Enoc,<br/>Pasar tiempo como Noé<br/>Es la forma de conocer<br/>el corazón de Dios<br/>La única forma de huir<br/>De las pasiones es seguir<br/>Justicia, fé, amor y paz con los<br/>Que te invocan a Ti.<br/>',NULL,196782,3);
INSERT INTO stanza VALUES('S2184','SoundCloud Link','https://soundcloud.com/user-497894694-364595996/2-pero-noe-hallo-favor',NULL,196783,4);
INSERT INTO stanza VALUES('S2185','1','Qué dulce es recordar<br/>En la mesa del Señor,<br/>Que somos solo un pan<br/>Que no tiene levadura.<br/>El anhelo del Señor es que<br/>Todos seamos uno ya,<br/>Comiendo de El, viviendo en El,<br/>Poderle disfrutar.<br/>',NULL,196784,1);
INSERT INTO stanza VALUES('S2185','2','La mesa del Señor<br/>Es una hermosa fiesta.<br/>No es un ceremonial,<br/>Costumbre o ritual.<br/>Es nuestra realidad en El,<br/>Nuestro gozar real,<br/>Experiementar de Cristo y Dios<br/>En la localidad.<br/>',NULL,196785,2);
INSERT INTO stanza VALUES('S2185','3','La copa y el pan<br/>Que están sobre la mesa:<br/>Son nuestro dispensar<br/>De Cristo entre los santos.<br/>El pan es el compartir real<br/>De nuestra experiencia en El,<br/>Lo que sustenta nuestro vivir<br/>Y enriquece el fluir.<br/>',NULL,196786,3);
INSERT INTO stanza VALUES('S2185','4','La copa que bebemos,<br/>Porción de bendición;<br/>Sello es de un pacto nuevo,<br/>Que con Su sangre confirmó.<br/>Por medio de Su sangre hoy,<br/>Podemos estar en pie<br/>Delante de El, y sin temor,<br/>Su sangre nos limpió.<br/>',NULL,196787,4);
INSERT INTO stanza VALUES('S2185','5','La muerte del Señor<br/>Resultó en el nuevo hombre.<br/>Su sangré nos limpió,<br/>Y también nos redimió.<br/>La cruz barreras destruyó,<br/>Causantes de división;<br/>Barreras que el hombre implantó<br/>Según su opinión.<br/>',NULL,196788,5);
INSERT INTO stanza VALUES('S2185','6','La mesa del Señor<br/>Demuestra la unidad;<br/>Nada sectario es,<br/>Ni tampoco exclusivista.<br/>Incluye a los que en su ser,<br/>Tienen al Señor Jesus,<br/>Haciendolos un solo Cuerpo<br/>En la localidad.<br/>',NULL,196789,6);
INSERT INTO stanza VALUES('S2185','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2185_que-dulce-es-recordar-en',NULL,196790,7);
INSERT INTO stanza VALUES('S2186','1','//Así como el relámpago<br/>Sale del oriente<br/>Y brilla hasta el occidente//<br/>Así será también la venida,<br/>La venida del Hijo del Hombre.<br/>',NULL,196791,1);
INSERT INTO stanza VALUES('S2186','2','¡Ven, Señor Jesús!<br/>Crece en nos,<br/>Y alístanos para Tu venida.<br/>Gana nuestro amor,<br/>Obtén Tu novia<br/>Haznos estos que Te traen de vuelta.<br/>',NULL,196792,2);
INSERT INTO stanza VALUES('S2186','SoundCloud Link','https://soundcloud.com/valen_torres/mateo-24-27-eypc-2019',NULL,196793,3);
INSERT INTO stanza VALUES('S2187','chorus','¡Estad listos!<br/>¡El Señor pronto vendrá!<br/>¿Hay aceite en sus vasos?<br/>¿Fieles servidores sois?<br/>Salid a Su encuentro;<br/>Más precioso que Él no hay.<br/>Vuelve tu corazón a quien amáis.<br/>',NULL,196794,1);
INSERT INTO stanza VALUES('S2187','1','Me abro cabalmente a Ti<br/>Para aceite recibir,<br/>Como virgen pura en mi corazón<br/>Yo pagaré el precio por Tu amor.<br/>',NULL,196795,2);
INSERT INTO stanza VALUES('S2187','2','Yo mi tiempo a Ti te doy.<br/>Al amarte velo hoy.<br/>Tu palabra viva quiero recibir.<br/>Que me encuentres puro y limpio a mí.<br/>',NULL,196796,3);
INSERT INTO stanza VALUES('S2187','3','Un talento recibí<br/>Por la habilidad en mí;<br/>Inmediatamente lo negociaré<br/>Para ser hallado siervo fiel.<br/>',NULL,196797,4);
INSERT INTO stanza VALUES('S2187','4','Tú siempre cuidas de mí,<br/>Yo quiero servirte a Ti<br/>Ministrando la vida que recibí<br/>Como sacerdote al servir.<br/>',NULL,196798,5);
INSERT INTO stanza VALUES('S2187','SoundCloud Link','https://soundcloud.com/clara-orjuela-78079798/est-s-listos',NULL,196799,6);
INSERT INTO stanza VALUES('S2188','1','En momentos así<br/>Canto una canción,<br/>Canción de amor a mi Cristo;<br/>En momentos así<br/>Canto una canción<br/>Al Señor, una canción de amor.<br/>',NULL,196800,1);
INSERT INTO stanza VALUES('S2188','chorus','Canto Te_amo,_oh, Señor;<br/>Canto Te_amo,_oh, Señor;<br/>Canto Te_amo, mi Señor,<br/>Te amo Señor.<br/>',NULL,196801,2);
INSERT INTO stanza VALUES('S2188','2','En momentos así,<br/>Invoco al Señor,<br/>Invoco Su nombre, Él me salva.<br/>En momentos así,<br/>Invoco al Señor,<br/>Invoco y me salva El.<br/>',NULL,196802,3);
INSERT INTO stanza VALUES('S2189','1','Dios usó a Juan Bautista<br/>Quien dejo su pasado,<br/>La religión de la edad.<br/>Dejando lo viejo,<br/>Proclamó: "Arrepentidos,<br/>Esta era abandonad"!<br/>',NULL,196803,1);
INSERT INTO stanza VALUES('S2189','chorus','Dios quiere vencedores,<br/>Que le amen por completo<br/>Y vivir para la era cambiar.<br/>Dios quiere vencedores<br/>Que le amen por completo;<br/>Haznos los que consuman la edad.<br/>',NULL,196804,2);
INSERT INTO stanza VALUES('S2189','2','Saulo fue llamado<br/>Para el plan de Dios,<br/>Pablo el apostol llegó a aser.<br/>El tuvo una visión:<br/>Donde no hay división<br/>Un solo Cuerpo del Señor.<br/>',NULL,196805,3);
INSERT INTO stanza VALUES('S2189','3','Llamó a Timoteo;<br/>Uno con Pablo oraba,<br/>En la palabra inmerso fue,<br/>Su espiritu avivó.<br/>Señor: ¡avívame!,<br/>¡Un vencedor hombre de Dios!.<br/>',NULL,196806,4);
INSERT INTO stanza VALUES('S2189','4','Haznos los vencedores,<br/>Tu novia preparada,<br/>Para esta era consumar.<br/>(...)<br/>',NULL,196807,5);
INSERT INTO stanza VALUES('S2189','chorus','*Al finalizar no se canta el coro después de la última estrofa*<br/>',NULL,196808,6);
INSERT INTO stanza VALUES('S2189','SoundCloud Link','https://soundcloud.com/clara-orjuela-78079798/dios-quiere-vencedores',NULL,196809,7);
INSERT INTO stanza VALUES('S2190','1','Nos has llamado hoy aquí,<br/>A disfrutarte en realidad;<br/>En nuestro espíritu podemos recibir<br/>Tu dulce impartición Señor.<br/>',NULL,196810,1);
INSERT INTO stanza VALUES('S2190','chorus','Al escuchar Tu dulce voz<br/>Se me derrite el corazón;<br/>Mientras te gano a Ti, Me ganas Tu,<br/>Haces Tu hogar en mi corazón.<br/>',NULL,196811,2);
INSERT INTO stanza VALUES('S2190','2','Tu nombre puedo invocar<br/>Y respirarte en verdad;<br/>Todo lo que eres Tu podemos recibir<br/>Al invocar Tu nombre hoy.<br/>',NULL,196812,3);
INSERT INTO stanza VALUES('S2190','3','Podemos verte en la reunión,<br/>La iglesia hoy es nuestro hogar;<br/>No más errante soy, sé cuál es mi lugar,<br/>La iglesia Tu habitación.<br/>',NULL,196813,4);
INSERT INTO stanza VALUES('S2190','4','Es Tu deseo, Tu intención<br/>Edificar Tu cuerpo hoy;<br/>Debemos funcionar, abrir la boca hoy,<br/>Trayendo Cristo a la reunión.<br/>',NULL,196814,5);
INSERT INTO stanza VALUES('S2190','SoundCloud Link','https://soundcloud.com/jamany-pastuizaca/al-escuchar-tu-dulce-voz-mp3-1',NULL,196815,6);
INSERT INTO stanza VALUES('S2191','1','En la vida de la iglesia<br/>Hay suplir sin fin;<br/>Vida rica y abundante<br/>Para los que creen.<br/>Solo en la iglesia<br/>Se disfruta del Señor:<br/>Comiendo y bebiendo<br/>De la vida de Jesús.<br/>',NULL,196816,1);
INSERT INTO stanza VALUES('S2191','chorus','¡Oh! Canto de gozo hay<br/>En la vida de la iglesia<br/>Donde se come<br/>Y se bebe a Jesús.<br/>Me satisface con<br/>Su abundancia ¡Aleluya!<br/>Nunca en la iglesia habrá falta o escasez.<br/>',NULL,196817,2);
INSERT INTO stanza VALUES('S2191','2','El Señor Jesús<br/>Es pan de vida celestial;<br/>Solo en la iglesia<br/>Se le puede encontrar:<br/>Pero si dejamos a la iglesia y al Señor,<br/>Estaremos en el mundo<br/>Y en la división.<br/>',NULL,196818,3);
INSERT INTO stanza VALUES('S2191','3','Dios es exclusivo<br/>Y se dispensa en un lugar;<br/>La iglesia local<br/>Es donde Él se expresa ya.<br/>Fluye de mi espíritu<br/>Como un torrente hoy,<br/>Y le entrego totalmente<br/>Todo lo que soy.<br/>',NULL,196819,4);
INSERT INTO stanza VALUES('S2192','1','Esto habla el Santo,<br/>El Verdadero,<br/>Aquel que tiene la llave de David;<br/>Que abre y nadie<br/>Podrá́cerrar,<br/>Que cierra y nadie abrirá.<br/>',NULL,196820,1);
INSERT INTO stanza VALUES('S2192','chorus','Conozco tus obras,<br/>Y he puesto Yo<br/>Una puerta abierta<br/>Que nadie cerrará;<br/>Pues aunque posees<br/>Poco poder,<br/>Guardaste Mi palabra<br/>Y no negaste Mi nombre.<br/>',NULL,196821,2);
INSERT INTO stanza VALUES('S2192','SoundCloud Link','https://soundcloud.com/noemi-gimenez-856202770/conozco-tus-obras',NULL,196822,3);
INSERT INTO stanza VALUES('S2193','1','Cristo constriñe<br/>Hoy con Su amor mi ser<br/>Para completamente<br/>Amarle a Él.<br/>Su fuerte amor,<br/>Profundo me tocó<br/>Para consagrar<br/>Mi vida y todo a Él.<br/>',NULL,196823,1);
INSERT INTO stanza VALUES('S2193','chorus','Es atrayente y excelso;<br/>Al tocar mi ser respondo;<br/>Al rendirme,<br/>Al rendir mi ser a Él.<br/>',NULL,196824,2);
INSERT INTO stanza VALUES('S2193','2','El fluir de amor<br/>Desde_Él a mi fluyó;<br/>Constante en mí,<br/>Por Su inmutable amor.<br/>Hoy soy de Él,<br/>Fuera de mi control;<br/>Él es mi amor,<br/>Sólo Él mi meta es.<br/>',NULL,196825,3);
INSERT INTO stanza VALUES('S2193','chorus','Su muerte en amor conmueve,<br/>Y Su fluir, mi ser constriñe<br/>No puedo evitar,<br/>Entregarme a amarle a Él.<br/>',NULL,196826,4);
INSERT INTO stanza VALUES('S2193','3','Cristo constriñe<br/>Completamente mi<br/>Ser para amarle a Él.<br/>Su gran amor<br/>Ha tocado mi ser,<br/>A consagrarme a Él.<br/>',NULL,196827,5);
INSERT INTO stanza VALUES('S2193','chorus','Es atrayente y excelso;<br/>Al tocar mi ser respondo;<br/>Al rendirme,<br/>al rendir mi ser a Él.<br/>',NULL,196828,6);
INSERT INTO stanza VALUES('S2193','4','Fuente de amor<br/>Desde Él a mi fluyó,<br/>Por Su inmutable amor,<br/>Soy para Él<br/>Fuera de mi control,<br/>Solo‿Él mi meta es.<br/>',NULL,196829,7);
INSERT INTO stanza VALUES('S2193','chorus','Su muerte en amor conmueve,<br/>Y Su fluir, mi ser constriñe<br/>No puedo_evitar,<br/>Entregarme a amarle a Él.<br/>',NULL,196830,8);
INSERT INTO stanza VALUES('S2193','SoundCloud Link','https://soundcloud.com/ana-lescas/cristo-constrine-hoy-con-su',NULL,196831,9);
INSERT INTO stanza VALUES('S2194','1','Cuando abrí mi corazón a Ti,<br/>Desde el principio,<br/>Hasta ahora,<br/>Me he dado cuenta de<br/>Cuan poco sé,<br/>Cuan pequeño soy,<br/>Cuánto necesito en Ti crecer.<br/>',NULL,196832,1);
INSERT INTO stanza VALUES('S2194','2','Oh Jesús，<br/>Cuan grande eres Tú,<br/>Oh, Cristo, el más excelente.<br/>Solo Tú puedes llenar,<br/>Quiero Tu nombre magnificar,<br/>Oh Cristo, el más hermoso Tú.<br/>',NULL,196833,2);
INSERT INTO stanza VALUES('S2194','3','Día a día quiero abrirme a Ti,<br/>Señor quita todo estorbo en mí.<br/>Poco a poco,<br/>Que Tu vida crezca en mí.<br/>Hasta que Tu seas mi visión,<br/>Hazlo Señor.<br/>(Hazlo Señor)<br/>',NULL,196834,3);
INSERT INTO stanza VALUES('S2194','SoundCloud Link','https://soundcloud.com/valen_torres/cuando-abr-mi-corazo-n-a-ti',NULL,196835,4);
INSERT INTO stanza VALUES('S2195','1','Cuando el Señor venga<br/>La fe se tornará en hechos<br/>Y la alabanza<br/>Reemplazará las oraciones.<br/>',NULL,196836,1);
INSERT INTO stanza VALUES('S2195','chorus','¡Qué maravilloso será ese día!<br/>¡Señor Jesús, ven pronto!<br/>',NULL,196837,2);
INSERT INTO stanza VALUES('S2195','2','El amor se consumará<br/>En una perfección sin sombras<br/>Y nosotros le serviremos<br/>En una esfera sin pecado.<br/>',NULL,196838,3);
INSERT INTO stanza VALUES('S2195','chorus','¡Qué maravilloso será ese día!<br/>¡Señor Jesús, ven pronto!<br/>',NULL,196839,4);
INSERT INTO stanza VALUES('S2195','chorus','***(Watchman Nee, El Cantar de los Cantares, pág 126)<br/>',NULL,196840,5);
INSERT INTO stanza VALUES('S2195','SoundCloud Link','https://soundcloud.com/user-33077836/cuando-el-senor-venga-original',NULL,196841,6);
INSERT INTO stanza VALUES('S2196','1','Justo precio dio el rey David<br/>Para la era de Ornan comprar;<br/>Y allí la casa de Dios construir<br/>Alto precio pagó el rey por ella.<br/>Traeremos de corazón<br/>Sacrificios, holocaustos;<br/>Lo precioso a gran costo se obtendrá<br/>Por Su casa sin reservas daré.<br/>',NULL,196842,1);
INSERT INTO stanza VALUES('S2196','chorus','Pagaremos el justo precio;<br/>Seamos firmes, sin adormecer.<br/>Nuestro afecto, alma y corazón<br/>Guarda fieles por Tu casa, Señor.<br/>Nuestra ofrenda un costo tendrá.<br/>Digno eres de todo‿entregar.<br/>Nuestro afecto, alma y corazón<br/>Guarda fieles por Tu casa, Señor.<br/>',NULL,196843,2);
INSERT INTO stanza VALUES('S2196','2','Afrontó gran obra David.<br/>No el hombre, Dios vive aquí;<br/>Generosamente él preparó<br/>Oro, plata y madera‿abundante.<br/>Llevaremos como David<br/>Carga por Tu casa, Señor;<br/>En angustia, calma, sin importar<br/>Tu llamado vamos a obedecer<br/>',NULL,196844,3);
INSERT INTO stanza VALUES('S2196','chorus','Pagaremos el justo precio;<br/>Seamos firmes, sin adormecer.<br/>Nuestro afecto, alma y corazón<br/>Guarda fieles por Tu casa, Señor.<br/>Nuestra ofrenda un costo tendrá.<br/>Digno eres de todo‿entregar.<br/>Nuestro afecto, alma y corazón<br/>Guarda fieles por Tu casa, Señor.<br/>',NULL,196845,4);
INSERT INTO stanza VALUES('S2196','3','Su tesoro particular<br/>Lo dio sin reservas David;<br/>Voluntariamente el rey rindió<br/>Cosas preciosas, oro y plata.<br/>Nuestro bienes, sueños y paz,<br/>Futuros brillantes también<br/>Ofrecemos con gozo en el altar.<br/>Lo mejor, digno eres de recibir.<br/>',NULL,196846,5);
INSERT INTO stanza VALUES('S2196','chorus','Pagaremos el justo precio;<br/>Seamos firmes, sin adormecer.<br/>Nuestro afecto, alma y corazón<br/>Guarda fieles por Tu casa, Señor.<br/>Nuestra ofrenda un costo tendrá.<br/>Digno eres de todo‿entregar.<br/>Nuestro afecto, alma y corazón<br/>Guarda fieles por Tu casa, Señor.<br/>',NULL,196847,6);
INSERT INTO stanza VALUES('S2196','4','¿Cómo nos podríamos jactar<br/>De lo que Te hemos de dar?<br/>Pues todo de Tu mano procedió,<br/>Lo prestado alegres te damos.<br/>¿Quién consagrará a Ti su ser,<br/>Dando voluntariamente<br/>Su alma, mente, fuerzas y corazón?<br/>Señor, damos nuestra vida a Ti.<br/>',NULL,196848,7);
INSERT INTO stanza VALUES('S2196','chorus','¡Oh que gloria! ¡Levantémonos<br/>Con los que el justo precio darán!<br/>Alabamos con fuerte espíritu<br/>Al Dios que Su edificio obtendrá.<br/>Al contarlo, es grande valor,<br/>Mas lo damos con gran devoción.<br/>Destinados a ser uno con Dios<br/>Qué descanso y mutua satisfaccion.<br/>',NULL,196849,8);
INSERT INTO stanza VALUES('S2196','SoundCloud Link','https://soundcloud.com/emilianolopez/el-justo-precio',NULL,196850,9);
INSERT INTO stanza VALUES('S2197','1','El Triuno Dios: Uno en esencia,<br/>Mas en Su economía es tres.<br/>Coexistentes, coinherentes;<br/>El eterno Dios es Él.<br/>',NULL,196851,1);
INSERT INTO stanza VALUES('S2197','2','La gracia del Señor Jesús,<br/>El amor de Dios,<br/>Y la comunión<br/>Del Espíritu sean con vosotros.<br/>',NULL,196852,2);
INSERT INTO stanza VALUES('S2197','3','La meta de Dios es impartirse:<br/>El Dios Triuno en mí.<br/>Y yo sé Señor<br/>Que en cualquier lugar,<br/>Cual sea mi obrar,<br/>Nunca me abandonas. (x2)<br/>(Jamás me abandonas.)<br/>',NULL,196853,3);
INSERT INTO stanza VALUES('S2197','SoundCloud Link','https://soundcloud.com/valen_torres/el-triuno-dios-uno-en-esencia',NULL,196854,4);
INSERT INTO stanza VALUES('S2198','1','Hoy te aprecio más y más.<br/>Por Tu grande misericordia,<br/>Veo Tu inmensa fidelidad.<br/>Que nunca, nunca me abandona.<br/>',NULL,196855,1);
INSERT INTO stanza VALUES('S2198','chorus','Para siempre anhelo amarte,<br/>Prefiero ser Tuyo que_al mundo volver.<br/>Incontables veces M´me_has perdonado,<br/>Con todas mis fuerzas Te quiero ser fiel.<br/>',NULL,196856,2);
INSERT INTO stanza VALUES('S2198','2','Cuán tierno y dulce es Tu amor,<br/>Tu consuelo ha sido grande.<br/>Aunque mil veces te abandone yo,<br/>Tu amor por mí, Dios, siempre arde.<br/>',NULL,196857,3);
INSERT INTO stanza VALUES('S2198','3','Ciertamente no sé apreciar,<br/>Todo lo que por mí has hecho;<br/>Pues queriéndome de Ti apartar,<br/>Me abrazas con perdón, muy bello.<br/>',NULL,196858,4);
INSERT INTO stanza VALUES('S2198','4','Nada he hecho para merecer,<br/>Tu atención y misericordia.<br/>Nada tengo que te pueda ofrecer,<br/>Pues no soy nada, pura escoria.<br/>',NULL,196859,5);
INSERT INTO stanza VALUES('S2198','5','Señor yo me humillo a Tus pies,<br/>Tú me derribas con Tu amor.<br/>Permíteme hoy Tu esclavo ser,<br/>Sirviéndote a Ti las gracias te doy.<br/>',NULL,196860,6);
INSERT INTO stanza VALUES('S2198','SoundCloud Link','https://soundcloud.com/clara-orjuela-78079798/hoy-te-anhelo-mas-y-mas',NULL,196861,7);
INSERT INTO stanza VALUES('S2199','1','La iglesia somos: Ekklesía<br/>Llamados a salir<br/>Del mundo para Dios.<br/>',NULL,196862,1);
INSERT INTO stanza VALUES('S2199','chorus','Guarda y santificanos<br/>En Tu Palabra.<br/>Edifica Tu iglesia, Señor.<br/>',NULL,196863,2);
INSERT INTO stanza VALUES('S2199','2','Su complemento, Su novia.<br/>Nos atrajo a Él,<br/>No amamos nada más.<br/>',NULL,196864,3);
INSERT INTO stanza VALUES('S2199','3','Su obra maestra y poema,<br/>Su máxima expresión,<br/>Testimonio de Su amor.<br/>',NULL,196865,4);
INSERT INTO stanza VALUES('S2199','4','Somos un Cuerpo, en unidad.<br/>Al asirnos de Él,<br/>Lo que es Cristo nuestro es.<br/>',NULL,196866,5);
INSERT INTO stanza VALUES('S2199','5','Su recobro somos, Filadelfia;<br/>Lo que ya nuestro es,<br/>Debemos retener.<br/>',NULL,196867,6);
INSERT INTO stanza VALUES('S2199','YouTube Link','https://youtu.be/Q2D1SIaFPzU?feature=shared',NULL,196868,7);
INSERT INTO stanza VALUES('S2199','SoundCloud Link','https://soundcloud.com/user-33077836/la-iglesia-somos-we-are-the',NULL,196869,8);
INSERT INTO stanza VALUES('S2200','1','Tu mesa es la fiesta<br/>De todos los santos<br/>Que en torno a ella<br/>Tienen comunión.<br/>Somos Tu familia<br/>Tu Cuerpo, Tu iglesia<br/>Estamos comiendo<br/>Tu mesa Señor.<br/>',NULL,196870,1);
INSERT INTO stanza VALUES('S2200','2','Tu Cuerpo, Señor<br/>¡Verdadera comida!<br/>Tu sangre Señor<br/>Verdadera bebida!<br/>¡De gloria en gloria<br/>Somos transformados,<br/>Comiendo de Ti<br/>Aquí te expresamos.<br/>',NULL,196871,2);
INSERT INTO stanza VALUES('S2200','3','El pan es la comunión<br/>De Tu Cuerpo,<br/>La copa es la sangre<br/>De Tu comunión.<br/>Que fiesta, Señor,<br/>¡En comunión contigo!<br/>Con todos los santos<br/>Somos uno ya.<br/>',NULL,196872,3);
INSERT INTO stanza VALUES('S2200','4','En esta ciudad<br/>Hay una sola mesa,<br/>Una sola copa<br/>Y un solo pan<br/>La hemos encontrado<br/>Y hoy la disfrutamos,<br/>Qué fiesta tan gloriosa<br/>Tu mesa Señor!<br/>',NULL,196873,4);
INSERT INTO stanza VALUES('S2200','5','No hay levadura,<br/>Señor, en Tu mesa,<br/>Tu copa es pura,<br/>Tu pan integral<br/>Hoy testificamos<br/>A todos los principados<br/>¡Tu iglesia es una<br/>En esta ciudad!<br/>',NULL,196874,5);
INSERT INTO stanza VALUES('S2201','1','¡Comprendí, Oh! Señor,<br/>Que, en lo profundo,<br/>De Tu corazón hay un deseo,<br/>Tener un complemento que te iguale,<br/>Que te conozca, desee y te ame.<br/>Es por esto que llegaste a ser hombre,<br/>Para así conocerme y alcanzarme,<br/>Tú dejaste Tu gloria, qué alto precio,<br/>Por una novia que eternamente<br/>Contigo vivirá.<br/>',NULL,196875,1);
INSERT INTO stanza VALUES('S2201','chorus','Recobra mi corazón, que te ame más;<br/>Mi mente que te conozca más;<br/>¡Mi fuerza para vivirte más, Oh, Señor!<br/>Ser hallado en Ti y Tu en mí,<br/>Tu y yo siendo uno, así vivir.<br/>Disfruto de Ti y Tu de mi,<br/>¡Oh! este es Tu recobro<br/>Y Tu satisfacción.<br/>',NULL,196876,2);
INSERT INTO stanza VALUES('S2201','2','¡Oh! Atráeme Señor junto con otros,<br/>Que en pos de Ti corran y no de otro.<br/>En Tu deseo y vida: haznos vitales,<br/>Dispuestos a ganarte y completarte.<br/>Tu necesidad es la más grande,<br/>Ya que el "YO SOY"<br/>Y el Gran Creador Tu eres.<br/>Nuestro Amado y tan querido Novio<br/>Está esperando cumplir<br/>Su sueño en los que Él ganó!<br/>',NULL,196877,3);
INSERT INTO stanza VALUES('S2201','SoundCloud Link','https://soundcloud.com/dani-b-313753210/recobra-mi-corazon-traduccion-provisional-recover-my-heart-nycypcd',NULL,196878,4);
INSERT INTO stanza VALUES('S2202','1','Samuel era un hombre<br/>Conforme al corazón de Dios.<br/>Su ser, vida y obra<br/>Concordaban con Dios.<br/>Todo lo que él hizo<br/>Fue conforme a lo que vio:<br/>Una clara visión<br/>De la economía de Dios.<br/>',NULL,196879,1);
INSERT INTO stanza VALUES('S2202','2','Su meta era realizar<br/>El deseo del corazón de Dios,<br/>Esto lo capacitó<br/>Para la era cambiar.<br/>Nada más deseaba,<br/>Sólo a Dios beneficiar,<br/>Y por eso útil fue<br/>Para cumplir el plan de Dios.<br/>',NULL,196880,2);
INSERT INTO stanza VALUES('S2202','3','Así como Samuel<br/>Deseo consagrado ser,<br/>Y que el corazón de Dios<br/>Sea uno con mi ser.<br/>Que no me interese<br/>El beneficio personal,<br/>Sólo el deseo de Dios:<br/>Obtener un reino hoy.<br/>',NULL,196881,3);
INSERT INTO stanza VALUES('S2202','SoundCloud Link','https://soundcloud.com/damarisleg/ser-un-samuel-hoy',NULL,196882,4);
INSERT INTO stanza VALUES('S2203','1','Vengo‿a Ti, Señor;<br/>Esta‿es mi oración,<br/>Que‿esté‿abierto a Ti,<br/>Siempre te‿ame a Ti.<br/>',NULL,196883,1);
INSERT INTO stanza VALUES('S2203','chorus','Hoy Te amo más, Señor;<br/>Te‿amo mucho más que‿ayer;<br/>Te‿amo y te<br/>Necesito.<br/>',NULL,196884,2);
INSERT INTO stanza VALUES('S2203','2','Hoy puedo‿elegir,<br/>Yo te‿elijo‿a Ti;<br/>Sin saber donde‿iré.<br/>En Ti yo confiaré<br/>',NULL,196885,3);
INSERT INTO stanza VALUES('S2203','3','Y si‿algo sale mal,<br/>Si‿es duro‿el caminar.<br/>Guarda mi corazón,<br/>Que‿esté‿abierto, Señor.<br/>',NULL,196886,4);
INSERT INTO stanza VALUES('S2203','4','Guíame, Señor,<br/>Esta‿es mi oración;<br/>Que te mire a Ti,<br/>Sin barreras, Señor.<br/>',NULL,196887,5);
INSERT INTO stanza VALUES('S2203','5','El tiempo pasará,<br/>Aquí yo seguiré,<br/>Pero que te‿ame‿a Ti,<br/>Y te diga sin fin:<br/>',NULL,196888,6);
INSERT INTO stanza VALUES('S2204','1','Señor, te amo a Ti,<br/>Y no existe nadie como Tú.<br/>En todo el universo<br/>Yo no tengo a nadie más que a Ti;<br/>¡Jesús, te amo a Ti!<br/>',NULL,196889,1);
INSERT INTO stanza VALUES('S2204','2','¿Qué pruebas más tendré<br/>De Tu amor por mí,<br/>Si tu vida aquí<br/>Entregaste Tú por mí?<br/>',NULL,196890,2);
INSERT INTO stanza VALUES('S2204','3','Cuán fuerte es Tu amor,<br/>No puedo resistir,<br/>El mundo dejaré,<br/>Siempre fiel te seguiré.<br/>',NULL,196891,3);
INSERT INTO stanza VALUES('S2204','4','Por Tu amor que fluye<br/>Cual viva fuente en mí:<br/>Señor, Te amo a Ti,<br/>¡Oh, como te amo a Ti!<br/>',NULL,196892,4);
INSERT INTO stanza VALUES('S2204','5','Señor, te amo a Ti,<br/>Y no existe nadie como Tú.<br/>En todo el universo<br/>Yo no tengo a nadie más que a Ti;<br/>¡Jesús, te amo a Ti!<br/>',NULL,196893,5);
INSERT INTO stanza VALUES('S2205','1','Dios en Cristo me ha unido a ti<br/>Para Su cuerpo edificar.<br/>¡Cristo en ti, mi esperanza es!<br/>Cristo en mí, tu necesidad.<br/>',NULL,196894,1);
INSERT INTO stanza VALUES('S2205','chorus','Si firme en Cristo estás, vivo yo.<br/>Si firme en Cristo estoy, vives tú.<br/>Prosigo yo por ti,<br/>Prosigues tu por mí.<br/>Juntos y en unidad<br/>¡Con los santos yo quiero estar!<br/>',NULL,196895,2);
INSERT INTO stanza VALUES('S2205','2','¡La iglesia en dulce comunión!<br/>¡Su novia edificada en Él!<br/>Persevero en Dios por ti;<br/>Me anima ver a Cristo en ti.<br/>',NULL,196896,3);
INSERT INTO stanza VALUES('S2205','3','Prosigo por tu fe en el Señor;<br/>¡Progreso por causa de ti!<br/>Y rebosa mi corazón,<br/>Orando a Cristo por ti.<br/>',NULL,196897,4);
INSERT INTO stanza VALUES('S2205','4','Con los santos hoy busco al Señor,<br/>Es éste el anhelo de Dios.<br/>A los santos me brindaré;<br/>Pues por ti vivo y tú por mí.<br/>',NULL,196898,5);
INSERT INTO stanza VALUES('S2205','5','Hermano, te quiero alentar;<br/>Sin ti no sobreviviré,<br/>No menosprecies tu porción.<br/>Cristo y yo precisamos de ti.<br/>',NULL,196899,6);
INSERT INTO stanza VALUES('S2205','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2205_dios-en-cristo-me-ha',NULL,196900,7);
INSERT INTO stanza VALUES('S2206','1','Tu pueblo se ofrecerá<br/>Voluntariamente.<br/>Tu pueblo se ofrecerá<br/>Voluntariamente.<br/>En el día de Tu guerra,<br/>En el esplendor de su consagración.<br/>',NULL,196901,1);
INSERT INTO stanza VALUES('S2206','2','Tus jóvenes te serán<br/>Como el rocío<br/>Desde el seno de la aurora.<br/>Tus jóvenes te serán<br/>Como el rocío<br/>Desde el seno de la aurora.<br/>Desde el seno de la aurora,<br/>(Desde el seno de la aurora)<br/>Desde el seno de la aurora.<br/>',NULL,196902,2);
INSERT INTO stanza VALUES('S2206','SoundCloud Link','https://soundcloud.com/oralia-hern-ndez/tu-pueblo-se-ofrecera',NULL,196903,3);
INSERT INTO stanza VALUES('S2207','1','Gracias, Señor, que es normal amarte<br/>Y que es normal el necesitarte,<br/>De nuevo hoy te pido<br/>‘‘Haz Tu hogar en mi corazón’’;<br/>Tu Espíritu en el mío dispensas,<br/>Y aunque a veces no siento<br/>Que crezca<br/>Estoy feliz al darte<br/>Mi vaso abierto en fe.<br/>',NULL,196904,1);
INSERT INTO stanza VALUES('S2207','chorus','Así que, Señor, de forma normal,<br/>Tu rostro haz resplandecer<br/>Para que Tu gracia pueda llenar<br/>Cada parte de mi ser.<br/>Dame más de Ti,<br/>Que Tu Espíritu<br/>Me pueda guiar,<br/>Quiero abierto estar,<br/>Y así, con amor,<br/>Espontáneamente todo lo harás.<br/>',NULL,196905,2);
INSERT INTO stanza VALUES('S2207','SoundCloud Link','https://soundcloud.com/damarisleg/vaso-abierto-open-vessel',NULL,196906,3);
INSERT INTO stanza VALUES('S2208','1','¿Has visto la visión,<br/>El deseo de Dios?<br/>Nos dio una porción,<br/>Y tendremos en,<br/>Abundancia.<br/>',NULL,196907,1);
INSERT INTO stanza VALUES('S2208','2','Hablar, predicar, pastorear,<br/>Compartir tu porción.<br/>Si no menospreciamos el don,<br/>Tendremos en,<br/>Abundancia.<br/>',NULL,196908,2);
INSERT INTO stanza VALUES('S2208','3','Ahora es el tiempo de edificar,<br/>Porque nuestro Señor viene ya,<br/>Usando nuestro don seremos,<br/>Premiados y tendremos en,<br/>Abundancia.<br/>',NULL,196909,3);
INSERT INTO stanza VALUES('S2208','4','Bien, esclavo, bueno y fiel,<br/>Sobre mucho te pondré.<br/>Porque a todo el que tiene,<br/>Le será dado, y tendrá en,<br/>Abundancia.<br/>',NULL,196910,4);
INSERT INTO stanza VALUES('S2208','SoundCloud Link','https://soundcloud.com/user-33077836/has-visto-la-visi-n',NULL,196911,5);
INSERT INTO stanza VALUES('S2209','1','Oh, Te amo Señor.<br/>Si, Te amo en verdad.<br/>No es nada la vida sin Ti.<br/>Atractivo eres Tú,<br/>Cautivado yo estoy;<br/>Tus riquezas<br/>Qué insondables son.<br/>Tu nombre al invocar<br/>Satisface el corazón;<br/>Mio eres y yo Tuyo soy.<br/>Nueva Jerusalén!<br/>Dios y hombre en unión,<br/>Dulce mezcla e incorporación.<br/>',NULL,196912,1);
INSERT INTO stanza VALUES('S2209','SoundCloud Link','https://soundcloud.com/livingstreamministry/oh-te-amo-senor',NULL,196913,2);
INSERT INTO stanza VALUES('S2210','1','Oh Señor Jesús Te amo;<br/>Y Tu eres mi porción<br/>Tu eres mi suplir,<br/>El todo inclusivo eres.<br/>Señor Tu has despertado<br/>Este amor de mi hacia Ti:<br/>No algo superficial,<br/>Sino una realidad.<br/>',NULL,196914,1);
INSERT INTO stanza VALUES('S2210','chorus','Y entre más te gano a Ti Señor<br/>Encuentro que Te amo más y más.<br/>Tu eres sin igual,<br/>Eres sin comparación.<br/>',NULL,196915,2);
INSERT INTO stanza VALUES('S2210','2','En este amor yo Te disfruto,<br/>Sobre todo eres Tu.<br/>Es aquí donde Te asecho<br/>Y donde gano más de Ti.<br/>Satúrame con Tu amor<br/>Para que no me aleje de Ti;<br/>Yo quiero permanecer<br/>Solo disfrutándote.<br/>',NULL,196916,3);
INSERT INTO stanza VALUES('S2211','1','Días oscuros,<br/>Cuerdas de seol atándome;<br/>Lazos de muerte aquí<br/>La destrucción me atacó.<br/>En profunda angustia,<br/>Invocaba Su nombre.<br/>Oyó mi voz, descendió aquí,<br/>Su mano me salvó.<br/>',NULL,196917,1);
INSERT INTO stanza VALUES('S2211','chorus','Te invocaré<br/>Porque responderás,<br/>Oirás mi voz y me hablarás:<br/>Hay refugio en Tu amor.<br/>',NULL,196918,2);
INSERT INTO stanza VALUES('S2211','2','Mi refugio es Dios,<br/>De Su ojo pupila yo soy;<br/>Dios mi fuerza es,<br/>Peña, roca, y protección.<br/>Sombra de Sus alas,<br/>Lugar donde me escondo yo;<br/>Su presencia, consuelo aquí,<br/>Con Su simple hablar.<br/>',NULL,196919,3);
INSERT INTO stanza VALUES('S2211','3','Sé una cosa Oh Dios:<br/>Eres canción dentro de mí<br/>Corriente eres sin fin,<br/>Para deleite fluyes Tu.<br/>Lléname, Señor,<br/>Satisfacciones hay en Ti.<br/>Quiero quedarme junto a Ti,<br/>En Ti hay salvación.<br/>',NULL,196920,4);
INSERT INTO stanza VALUES('S2211','SoundCloud Link','https://soundcloud.com/noemi-gimenez-856202770/te-invocare',NULL,196921,5);
INSERT INTO stanza VALUES('S2212','1','Qué hay pues hermanos,<br/>Qué hay pues hermanas,<br/>Cuando os reunis<br/>Cada vez que te reunes<br/>Como Iglesia? (x2)<br/>',NULL,196922,1);
INSERT INTO stanza VALUES('S2212','2','Cada uno de vosotros tiene salmos,<br/>Tiene enseñanza, tiene revelación;<br/>Tiene lengua, tiene interpretación,<br/>Hagase todo para edificar.<br/>',NULL,196923,2);
INSERT INTO stanza VALUES('S2212','SoundCloud Link','https://soundcloud.com/user-144035804/hermanos-y-hermanas',NULL,196924,3);
INSERT INTO stanza VALUES('S2213','1','Respondió Rut: No me ruegues<br/>Que te deje y me aparte de ti;<br/>Porque a dondequiera que tu fueres,<br/>Iré yo,<br/>Y dondequiera que vivieres, viviré;<br/>Tu pueblo será mi pueblo,<br/>Y tu Dios mi Dios.<br/>Tu pueblo será mi pueblo,<br/>Y tu Dios mi Dios.<br/>',NULL,196925,1);
INSERT INTO stanza VALUES('S2214','1','Hay_una semilla plantada en mi ser<br/>Que en la buena tierra hoy debe crecer.<br/>Raíces profundas escondidas en Él,<br/>Él mismo creciendo, el reino de Dios.<br/>',NULL,196926,1);
INSERT INTO stanza VALUES('S2214','2','Nuestro corazón Su réplica Él desea,<br/>Un ámbito en el cual Dios pueda reinar.<br/>Su expresión tener, a Él nos entregamos.<br/>Cambiemos la era. ¡Ven pronto, Señor¡<br/>',NULL,196927,2);
INSERT INTO stanza VALUES('S2214','3','Crece Señor en toda mi alma,<br/>La madurez bajo Tu reinar.<br/>Cooperar contigo es todo mi anhelo,<br/>Perlas preciosas en mí obtendrás.<br/>',NULL,196928,3);
INSERT INTO stanza VALUES('S2214','4','Hoy me consagro a Ti, mi Señor,<br/>Como una virgen amándote a Ti.<br/>Comprando aceite que sature mi ser,<br/>Un fiel esclavo, el premio obtendré.<br/>',NULL,196929,4);
INSERT INTO stanza VALUES('S2214','SoundCloud Link','https://soundcloud.com/user-518979615/hay-una-semilla',NULL,196930,5);
INSERT INTO stanza VALUES('S2215','1','Detrás de cada escena esta,<br/>Dulcemente siempre operando,<br/>Aquel que es sabio y fiel,<br/>Pacientemente guia mis ojos.<br/>Mira a Mi Hijo,_el Amado,<br/>A Mi diestra está sentado;<br/>Jesús es Rey, pero no<br/>Puede moverse hasta que Su pueblo<br/>Se abra a El.<br/>',NULL,196931,1);
INSERT INTO stanza VALUES('S2215','chorus','Hoy, Te vemos!<br/>Hoy, Te_amamos!<br/>Rendimos todo a Ti, Amado.<br/>Hoy al regirnos Tú nos traes<br/>Un dulce suplir.<br/>Oh, qué gran Bendición!<br/>Estar en manos de nuestro Rey!<br/>Todo cuando quieras lograr,<br/>Hazlo en mí.<br/>',NULL,196932,2);
INSERT INTO stanza VALUES('S2215','2','La semilla del reino en nos,<br/>Ordena y rige nuestros pasos.<br/>Jesús, entronizado está<br/>En mí, ganando cada parte.<br/>¿No sabes que tú eres templo<br/>De tu Dios, Rey de Reyes?<br/>Obtén, Señor, la vía en nos,<br/>Para reinar en la tierra<br/>Hoy, Señor!<br/>',NULL,196933,3);
INSERT INTO stanza VALUES('S2215','SoundCloud Link','https://soundcloud.com/user-952134958/detras-de-cada-escena-esta-hidden-behind-every-scenespanish-version',NULL,196934,4);
INSERT INTO stanza VALUES('S2216','1','Y me humilló e hizo pasar hambre,<br/>Y me alimentó con maná,<br/>Que no conocía yo,<br/>Ni conocían mis padres,<br/>Para hacerme saber que<br/>No solo de pan vive el hombre;<br/>No solo de pan vive el hombre.<br/>Mas de todo lo que procede<br/>De la boca de Johová,<br/>Vive el hombre.<br/>',NULL,196935,1);
INSERT INTO stanza VALUES('S2217','1','Nosotros también,<br/>Teniendo en derredor<br/>Nuestro tan grande<br/>Nube de testigos,<br/>Despojémonos de todo peso<br/>Y del pecado que tan<br/>Fácilmente nos enreda,<br/>Y corramos pacientes<br/>La carrera que tenemos por delante,<br/>Puestos los ojos en Jesús -<br/>Jesús! El Autor<br/>Y el Consumador de nuestra fe,<br/>El cual por el gozo -<br/>El gozo puesto delante de Él<br/>Sufrió la cruz,<br/>Menospreciando así el oprobio; y<br/>Se sentó a la diestra del trono de Dios.<br/>Se sentó a la diestra del trono de Dios.<br/>',NULL,196936,1);
INSERT INTO stanza VALUES('S2217','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/nosotros_tambien_teniendo_derredor_nuestro',NULL,196937,2);
INSERT INTO stanza VALUES('S2218','1','Necesitas hombres<br/>Para la era cambiar,<br/>Muévete en mi Señor,<br/>Gana el corazón.<br/>Sálvame de buscar lo mío,<br/>Obtén todo mi ser,<br/>Líbrame de la esclavitud,<br/>Desaparécela.<br/>',NULL,196938,1);
INSERT INTO stanza VALUES('S2218','chorus','Señor me necesitas a mí<br/>Para cumplir lo que deseas Tú.<br/>Enciende todo mi amor por Ti,<br/>Para que líbremente<br/>Me consagre a Ti.<br/>',NULL,196939,2);
INSERT INTO stanza VALUES('S2218','2','Necesitas hombres<br/>Para la era cambiar;<br/>Constriñenos<br/>Para poder vencer<br/>Toda rebelión y afecto natural<br/>Los placeres de éste mundo,<br/>Toda mortandad.<br/>',NULL,196940,3);
INSERT INTO stanza VALUES('S2218','chorus','Señor me necesitas a mí<br/>Para cumplir lo que deseas Tú.<br/>Enciende todo mi amor por Ti,<br/>Para que líbremente<br/>Me consagre a Ti.<br/>',NULL,196941,4);
INSERT INTO stanza VALUES('S2218','note','**[Puente:]**<br/>Santifícame absolutamente,<br/>Vence Tú en mi.<br/>Dame victoria<br/>Por Tu vida en mí.<br/>Y ésta era terminar.<br/>',NULL,196942,5);
INSERT INTO stanza VALUES('S2218','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/consagrarme-a-ti-consecrated',NULL,196943,6);
INSERT INTO stanza VALUES('S2219','1','Venid a Mi todos los que...<br/>Todos los que trabajáis arduamente<br/>Y estáis cargados, y Yo os haré...<br/>Yo os haré,<br/>Os haré descansar.<br/>',NULL,196944,1);
INSERT INTO stanza VALUES('S2219','2','//Tomad sobre vosotros Mi yugo,<br/>Y aprended de Mi, que soy manso<br/>Y humilde de corazón;<br/>Y hallaréis descanso para vuestras...//<br/>Almas;<br/>',NULL,196945,2);
INSERT INTO stanza VALUES('S2219','3','Porque Mi yugo es fácil,<br/>Y ligera Mi carga.<br/>Para vuestras almas;<br/>Porque Mi yugo es fácil,<br/>Y ligera Mi carga.<br/>',NULL,196946,3);
INSERT INTO stanza VALUES('S2219','4','//Venid a Mí,<br/>Yo os haré...<br/>Venid a Mí...<br/>Descansar//<br/>',NULL,196947,4);
INSERT INTO stanza VALUES('S2219','SoundCloud Link','https://soundcloud.com/clara-orjuela-78079798/venid-a-mi-todos-los-que',NULL,196948,5);
INSERT INTO stanza VALUES('S2220','1','Pero persiste tú<br/>En lo que has aprendido!<br/>Y de lo que estás convencido!<br/>Sabiendo de quienes has aprendido;<br/>Y desde la niñez<br/>Has sabido las Sagradas Escrituras,<br/>Las cuales te pueden hacer sabio<br/>Para la salvación por la fe<br/>Que es en Cristo Jesús!<br/>',NULL,196949,1);
INSERT INTO stanza VALUES('S2220','SoundCloud Link','https://soundcloud.com/eric-aguilar-921081480/pero-persiste-tu-m4a',NULL,196950,2);
INSERT INTO stanza VALUES('S2221','1','Del mandamiento de Sus labios<br/>No me he apartado;<br/>He atesorado las palabras de Su boca<br/>Más que mi comida asignada.<br/>',NULL,196951,1);
INSERT INTO stanza VALUES('S2221','chorus','¡Cuán dulces son a mi paladar Tus palabras!<br/>¡Cuán dulces son a mi paladar Tus palabras!<br/>¡Más dulce que la miel a mi boca!<br/>¡Más dulce que la miel a mi boca!<br/>',NULL,196952,2);
INSERT INTO stanza VALUES('S2221','SoundCloud Link','https://soundcloud.com/lucero-mart-nez-409607405/del-mandamiento-job-23-12-sal?in=user-497894694-364595996/sets/escuela-de-la-verdad-co-2024',NULL,196953,3);
INSERT INTO stanza VALUES('S2222','1','Escucha oh Jehová, mis palabras;<br/>Considera mi gemir.<br/>A la voz de mi clamor atiende:<br/>¡Mi Dios y mi Rey!<br/>Porque a Ti oraré.<br/>Oh Jehová, de mañana oirás mi voz;<br/>De mañana me presentaré<br/>Delante de Ti y esperaré.<br/>',NULL,196954,1);
INSERT INTO stanza VALUES('S2222','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/escucha-oh-jehova-mis-palabras',NULL,196955,2);
INSERT INTO stanza VALUES('S2223','1','Si tú buscas al Señor,<br/>En el mundo no‿estará,<br/>Porque‿el mundo nunca es Su‿habitación.<br/>Su‿habitación, Su‿habitación,<br/>Su‿habitación, Su‿habitación,<br/>Porque‿el mundo nunca es Su‿habitación.<br/>',NULL,196956,1);
INSERT INTO stanza VALUES('S2223','2','Si tú buscas al Señor,<br/>En la mente no‿estará,<br/>Que la mente sólo sabe razonar.<br/>Y razonar, y razonar,<br/>Y razonar, y razonar,<br/>Que la mente sólo sabe razonar.<br/>',NULL,196957,2);
INSERT INTO stanza VALUES('S2223','3','Si tú buscas al Señor,<br/>Sólo abre‿el corazón,<br/>Sólo abre‿el corazón.<br/>Déjale‿entrar.<br/>Déjale‿entrar, déjale‿entrar.<br/>Déjale‿entrar, déjale‿entrar.<br/>Sólo abre‿el corazón. Déjale‿entrar.<br/>',NULL,196958,3);
INSERT INTO stanza VALUES('S2223','4','Si deseas dejarle‿entrar,<br/>Clama: “Oh, Señor Jesús”<br/>Clama: “Oh, Señor Jesús”.<br/>Déjale‿entrar.<br/>Clama‿a Él, clama‿a Él,<br/>Clama: “Oh, Señor Jesús”<br/>Clama: “Oh, Señor Jesús”.<br/>Déjale‿entrar.<br/>',NULL,196959,4);
INSERT INTO stanza VALUES('S2223','SoundCloud Link','https://soundcloud.com/clara-orjuela-78079798/si-tu-buscas-al-senor',NULL,196960,5);
INSERT INTO stanza VALUES('S2224','1','Pues no habéis recibido espíritu de<br/>Esclavitud para estar otra vez en temor,<br/>No habéis recibido espíritu de esclavitud<br/>Para estar otra vez en temor,<br/>',NULL,196961,1);
INSERT INTO stanza VALUES('S2224','chorus','Sino que habéis recibido espíritu filial,<br/>Sino que habéis recibido espíritu filial,<br/>Con el cual clamamos: ¡Abba, Padre!<br/>Con el cual clamamos: ¡Abba, Padre!<br/>',NULL,196962,2);
INSERT INTO stanza VALUES('S2224','2','Pues no habéis recibido espíritu de<br/>Esclavitud para estar otra vez en temor,<br/>No habéis recibido espíritu de esclavitud<br/>Para estar otra vez en temor.<br/>',NULL,196963,3);
INSERT INTO stanza VALUES('S2224','chorus','**[Puente:]**<br/>El Espíritu mismo da testimonio<br/>Juntamente con nuestro espíritu,<br/>De que somos hijos de Dios.<br/>¡Abba, Padre! ¡Abba, Padre!<br/>Pues no habéis recibido espíritu de<br/>Esclavitud para estar otra vez en temor.<br/>',NULL,196964,4);
INSERT INTO stanza VALUES('S2224','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/romanos-8_15-16-ft-jo-venes-en',NULL,196965,5);
INSERT INTO stanza VALUES('S2225','1','El le respondió y le dijo:<br/>Si alguien Me ama.<br/>Si alguien Me ama. (x2)<br/>',NULL,196966,1);
INSERT INTO stanza VALUES('S2225','2','Mi Palabra guardará<br/>Y Mi Padre le amará.<br/>Y vendremos a él,<br/>Y haremos con el,<br/>Y haremos morada con el.<br/>',NULL,196967,2);
INSERT INTO stanza VALUES('S2225','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2225_el-le-respondio-y-le-1',NULL,196968,3);
INSERT INTO stanza VALUES('S2226','1','La intención de Dios<br/>Es darse a Sí mismo<br/>Como posesión del hombre,<br/>Pero el hombre abandonó<br/>A Dios y cayó_en<br/>La esclavitud de Satanás,<br/>El pecado y el mundo,<br/>Mas Dios prometió salvarlo,<br/>Al proclamar el año agradable<br/>Del jubileo.<br/>',NULL,196969,1);
INSERT INTO stanza VALUES('S2226','2','La realidad del jubileo<br/>No_es un evento sino una Persona,<br/>El jubileo es Jesús,<br/>Quien por medio de Su muerte<br/>Nos libera de todas las cosas<br/>Negativas y recobra<br/>Nuestro derecho<br/>De disfrutar a Dios.<br/>',NULL,196970,2);
INSERT INTO stanza VALUES('S2226','3','A fin de ser liberados<br/>De la pobreza, del cautiverio,<br/>De la ceguera_y de<br/>Toda clase de opresión<br/>Y alcanzar plena libertad,<br/>Debemos recibir al “Jubileo-Jesús”<br/>Y disfrutarle fielmente<br/>Mediante el tono de_una<br/>Vida que vence:<br/>Al invocar Su nombre,<br/>Regocijarnos, alabarle_y convertir<br/>En oración la palabra de Dios.<br/>',NULL,196971,3);
INSERT INTO stanza VALUES('S2226','4','El jubileo llega a ser<br/>Una persona corporativa,<br/>Los vencedores, quienes ven,<br/>Disfrutan, viven,<br/>Proclaman, y son el jubileo mismo<br/>Por causa del testimonio de Jesús<br/>Y con miras a llevar a cabo<br/>Su economía eterna,<br/>La cual tendrá su consumación<br/>En la ciudad del jubileo,<br/>La Nueva Jerusalén.<br/>',NULL,196972,4);
INSERT INTO stanza VALUES('S2226','SoundCloud Link','https://soundcloud.com/ymalv/el-jubileo-jes-s',NULL,196973,5);
INSERT INTO stanza VALUES('S2227','chorus','Oh, dame la gracia de_hoy, Señor;<br/>Crezca Tu vida divinal.<br/>Que día_a día pueda yo crecer;<br/>Más y más en Tu ser.<br/>',NULL,196974,1);
INSERT INTO stanza VALUES('S2227','1','Tu vida crece_así<br/>Poco_a poco en mí;<br/>Gradualmente<br/>Aumenta ͜ en mi ser, mas<br/>Sin saber, ni percibirlo aún,<br/>Tu vida_en mí madura.<br/>',NULL,196975,2);
INSERT INTO stanza VALUES('S2227','chorus','Oh, dame la gracia de_hoy, Señor;<br/>Crezca Tu vida divinal.<br/>Que día_a día pueda yo crecer;<br/>Más y más en Tu ser.<br/>',NULL,196976,3);
INSERT INTO stanza VALUES('S2227','2','Con desesperación,<br/>Anhelo, oh Señor,<br/>Inhalar<br/>Siempre Tu aliento y vida,<br/>Pues sé bien que al yo respirar<br/>Tu vida me satura.<br/>',NULL,196977,4);
INSERT INTO stanza VALUES('S2227','chorus','Oh, dame la gracia de_hoy, Señor;<br/>Crezca Tu vida divinal.<br/>Que día_a día pueda yo crecer;<br/>Más y más en Tu ser.<br/>',NULL,196978,5);
INSERT INTO stanza VALUES('S2227','3','Puedo hoy descansar<br/>Sé que_el legado ya<br/>Suple mi necesidad total y<br/>El Señor intercede por mí,<br/>Un miembro de Su Cuerpo.<br/>',NULL,196979,6);
INSERT INTO stanza VALUES('S2227','chorus','Concédeme una clara visión,<br/>Tan corporativa y celestial;<br/>Que ore_a Ti, crezca_y poco_a poco_así<br/>Cause edificación.<br/>',NULL,196980,7);
INSERT INTO stanza VALUES('S2227','4','Como Cuerpo,_hemos de<br/>Firmemente crecer<br/>Hasta Tu<br/>Plenitud alcanzar;<br/>Nos transformas, nos conformarás,<br/>Tu pueblo que Te expresa.<br/>',NULL,196981,8);
INSERT INTO stanza VALUES('S2227','chorus','Oh, dame la gracia de_hoy, Señor;<br/>Crezca Tu vida divinal.<br/>Que día_a día pueda yo crecer;<br/>Más y más en Tu ser.<br/>',NULL,196982,9);
INSERT INTO stanza VALUES('S2227','chorus','Concédeme una clara visión,<br/>Tan corporativa ͜y celestial;<br/>Que ore_a Ti, crezca_y poco_a poco_así<br/>Cause edificación.<br/>',NULL,196983,10);
INSERT INTO stanza VALUES('S2227','chorus','Concédeme una clara visión,<br/>Tan corporativa ͜y celestial;<br/>Que ore_a Ti, crezca_y poco_a poco_así<br/>Edifique la Nueva Jerusalén.<br/>',NULL,196984,11);
INSERT INTO stanza VALUES('S2227','YouTube Link','https://www.youtube.com/watch?v=n5eClJ1cBZY&list=RDMM',NULL,196985,12);
INSERT INTO stanza VALUES('S2228','1','Sión, allí Dios habita;<br/>Cantemos alabanzas,<br/>En la ciudad del Rey.<br/>Sión, Dios ha escogido;<br/>Los santos gozando están<br/>De Dios su salvación.<br/>',NULL,196986,1);
INSERT INTO stanza VALUES('S2228','chorus','Hermosa Sión, en las alturas;<br/>El gozo eterno,<br/>Su satisfacción;<br/>El gozo de la tierra es.<br/>',NULL,196987,2);
INSERT INTO stanza VALUES('S2228','2','Sión, cuán bueno y cuán dulce.<br/>Qué disfrute inmenso es!<br/>Como ungüento valioso!<br/>Sión, cuán bueno y cuán dulce;<br/>Moramos en unidad,<br/>El ungüento tan fresco.<br/>',NULL,196988,3);
INSERT INTO stanza VALUES('S2228','chorus','Hermosa Sión, en las alturas;<br/>Cuán bueno y cuán dulce,<br/>Qué disfrutable!<br/>Él es nuestra unidad.<br/>',NULL,196989,4);
INSERT INTO stanza VALUES('S2228','3','Sión, Él nuestra unidad es;<br/>Se mueve como un bálsamo,<br/>Desciende como rocío.<br/>Sión, nuestra morada es Dios;<br/>Como bálsamo sanador,<br/>Como el rocío, Él nos suple.<br/>',NULL,196990,5);
INSERT INTO stanza VALUES('S2228','chorus','Hermosa Sión, en las alturas;<br/>Cuán bueno y cuán dulce.<br/>Que satisfacción,<br/>Vivimos en unidad.<br/>',NULL,196991,6);
INSERT INTO stanza VALUES('S2228','4','Sión, en Dios habitamos;<br/>Vivimos en tal unidad,<br/>Siendo Dios nuestro todo.<br/>Sión, bendición eterna;<br/>Dios y hombre mezclados,<br/>Dios triuno Dispensado.<br/>',NULL,196992,7);
INSERT INTO stanza VALUES('S2228','chorus','Bellas Iglesias, los canderelos,<br/>La mezcla completa<br/>De Dios y el hombre,<br/>La última consumación.<br/>',NULL,196993,8);
INSERT INTO stanza VALUES('S2228','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/si-n-all-dios-habita-zion-is-1',NULL,196994,9);
INSERT INTO stanza VALUES('S2229','1','Con toda oración<br/>Y petición<br/>Orando en todo tiempo<br/>En el espíritu,<br/>Y para ello velando<br/>Con toda perseverancia<br/>Y petición por todos los santos;<br/>',NULL,196995,1);
INSERT INTO stanza VALUES('S2229','2','Y por mí, a fin<br/>De que al abrir mi boca<br/>Me sea dada palabra para dar<br/>A conocer con denuedo<br/>El misterio del evangelio.<br/>',NULL,196996,2);
INSERT INTO stanza VALUES('S2229','SoundCloud Link','https://soundcloud.com/noemi-gimenez-856202770/efesios-6-18-19',NULL,196997,3);
INSERT INTO stanza VALUES('S2230','1','La visión respecto<br/>A la función del pueblo<br/>Electo por Dios en la tierra hoy,<br/>Nos perfecciona, dirije y controla,<br/>Para ministrar Cristo y la era cerrar.<br/>',NULL,196998,1);
INSERT INTO stanza VALUES('S2230','chorus','En vida reinar:<br/>Por el Espíritu<br/>Gobernado y restringido.<br/>En vida reinar:<br/>Traer el reino de Dios,<br/>La vida del reino hacer real.<br/>',NULL,196999,2);
INSERT INTO stanza VALUES('S2230','2','Un tiempo en secreto,<br/>Buscando experiencias,<br/>Al estar a solas con el Señor;<br/>Y hablar con denuedo<br/>Los sueños del Padre,<br/>Discipulando para la era cerrar.<br/>',NULL,197000,3);
INSERT INTO stanza VALUES('S2230','YouTube Link','https://www.youtube.com/watch?v=rShNw84oFik',NULL,197001,4);
INSERT INTO stanza VALUES('S2231','1','Oh qué hermoso es ver a Jesús<br/>En tu rostro, oh mi hermano!<br/>Ver cada dia en ti<br/>Su belleza reflejada.<br/>Y amarnos cada vez más,<br/>Sobre todas las diferencias<br/>Y permitir que Él<br/>Nuestras vidas haga perfectas.<br/>//Cada dia te amo mas<br/>Porque Cristo es todo en mi vida;<br/>Unidos  en Su amor<br/>Alabamos hoy Su nombre//<br/>',NULL,197002,1);
INSERT INTO stanza VALUES('S2231','YouTube Link','https://soundcloud.com/johana-duque-montes/5-oh-que-hermoso-es-ver-a-jesu',NULL,197003,2);
INSERT INTO stanza VALUES('S2232','1','Eres tan maravilloso,<br/>No tienes comparación<br/>[Sa. 73:25]<br/>Nada existe tan hermoso<br/>Como Tu en la creación.<br/>',NULL,197004,1);
INSERT INTO stanza VALUES('S2232','chorus','Tu eres Jehová el Salvador<br/>[Jn. 10:28-30]<br/>Y el Rey de los reyes;<br/>[Ap. 19:13-16]<br/>Dios con nosotros eres<br/>[Mt. 1:21-23]<br/>Y el Espíritu viviente.<br/>[1 Cor. 15:45b]<br/>',NULL,197005,2);
INSERT INTO stanza VALUES('S2232','2','Eres la expresión del Padre<br/>[Hbr. 1:1-3]<br/>De su gloria y esplendor ;<br/>Al venir a este mundo<br/>[John 1:14]<br/>Nos mostraste Tu a Dios.<br/>[Mt. 11:27]<br/>',NULL,197006,3);
INSERT INTO stanza VALUES('S2232','chorus','Tu eres Jehová el Salvador<br/>[Jn. 10:28-30]<br/>Y el Rey de los reyes;<br/>[Ap. 19:13-16]<br/>Dios con nosotros eres<br/>[Mt. 1:21-23]<br/>Y el Espíritu viviente.<br/>[1 Cor. 15:45b]<br/>',NULL,197007,4);
INSERT INTO stanza VALUES('S2232','3','Tu vida maravillosa<br/>Liberaste al morir<br/>Para que los muchos granos<br/>Al creer puedan vivir<br/>[Jn. 12:24; 1 Co. 15:35-45]<br/>',NULL,197008,5);
INSERT INTO stanza VALUES('S2232','chorus','Tu eres Jehová el Salvador<br/>[Jn. 10:28-30]<br/>Y el Rey de los reyes;<br/>[Ap. 19:13-16]<br/>Dios con nosotros eres<br/>[Mt. 1:21-23]<br/>Y el Espíritu viviente.<br/>[1 Cor. 15:45b]<br/>',NULL,197009,6);
INSERT INTO stanza VALUES('S2232','4','Eres agua que refresca,<br/>[Jn. 4:14]<br/>Y a cualquier la vida da;<br/>[Ap. 22:17]<br/>Eres camino, eres puerta,<br/>[Jn. 14:6; 10:7,9]<br/>Eres mi realidad<br/>[Jn. 16:13; Col. 2:17]<br/>',NULL,197010,7);
INSERT INTO stanza VALUES('S2232','chorus','Tu eres Jehová el Salvador<br/>[Jn. 10:28-30]<br/>Y el Rey de los reyes;<br/>[Ap. 19:13-16]<br/>Dios con nosotros eres<br/>[Mt. 1:21-23]<br/>Y el Espíritu viviente.<br/>[1 Cor. 15:45b]<br/>',NULL,197011,8);
INSERT INTO stanza VALUES('S2232','5','Eres Cabeza del Cuerpo;<br/>[Col. 1:18; Ef. 5:23]<br/>Eres esposo y Señor.<br/>[Jn. 3:28-29]<br/>Tu que preparas la novia<br/>[Ap. 21:2]<br/>Para Tu satisfacción.<br/>[Ef. 5:25-27]<br/>',NULL,197012,9);
INSERT INTO stanza VALUES('S2232','chorus','Tu eres Jehová el Salvador<br/>[Jn. 10:28-30]<br/>Y el Rey de los reyes;<br/>[Ap. 19:13-16]<br/>Dios con nosotros eres<br/>[Mt. 1:21-23]<br/>Y el Espíritu viviente.<br/>[1 Cor. 15:45b]<br/>',NULL,197013,10);
INSERT INTO stanza VALUES('S2232','6','Edificas a Tu iglesia,<br/>Tu habitación terrenal<br/>Y en la eternidad futura<br/>Jerusalén celestial.<br/>',NULL,197014,11);
INSERT INTO stanza VALUES('S2232','chorus','Tu eres Jehová el Salvador<br/>[Jn. 10:28-30]<br/>Y el Rey de los reyes;<br/>[Ap. 19:13-16]<br/>Dios con nosotros eres<br/>[Mt. 1:21-23]<br/>Y el Espíritu viviente.<br/>[1 Cor. 15:45b]<br/>',NULL,197015,12);
INSERT INTO stanza VALUES('S2232','chorus','Final : Tú eres Jehová!<br/>',NULL,197016,13);
INSERT INTO stanza VALUES('S2232','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/tu-eres_jehova-el_salvador',NULL,197017,14);
INSERT INTO stanza VALUES('S2233','1','Cristo, Cordero, querido Redentor<br/>Mis pecados en la cruz llevó,<br/>Él pagó por redimirme a mí,<br/>Que alejado estaba yo de Dios.<br/>Cordero, no tenías mancha,<br/>Eras manso y sumiso.<br/>¿Cómo no ser obediente como Él, hasta<br/>Incluso una muerte de cruz?<br/>',NULL,197018,1);
INSERT INTO stanza VALUES('S2233','chorus','Quiero seguirlo a Él,<br/>Ya no mas errante ser,<br/>Y mis luchas acabar;<br/>Aunque yo no sé cómo o dónde,<br/>Él sabe bien,<br/>Él nunca se equivocará,<br/>Me guía bien,<br/>Es mi elección, seguir Su voz,<br/>Al Cordero seguiré.<br/>',NULL,197019,2);
INSERT INTO stanza VALUES('S2233','2','Aunque muchos seguidores tuvo Él,<br/>Pocos conocieron Su andar;<br/>Puerta estrecha, camino angosto,<br/>A la vida la senda trazó.<br/>Él se dio aunque le negaron,<br/>Maldecido y despreciado.<br/>¿Cómo no rendir el corazón?<br/>Si Su vida por nosotros dio.<br/>',NULL,197020,3);
INSERT INTO stanza VALUES('S2233','chorus','Quiero seguirlo a Él,<br/>Ya no mas errante ser,<br/>Y mis luchas acabar;<br/>Aunque yo no sé cómo o dónde,<br/>Él sabe bien,<br/>Él nunca se equivocará,<br/>Me guía bien,<br/>Es mi elección, seguir Su voz,<br/>Al Cordero seguiré.<br/>',NULL,197021,4);
INSERT INTO stanza VALUES('S2233','3','Oh! Señor, oramos hoy: Presérvanos<br/>Fieles para en Tu camino andar,<br/>Por Tu gracia yendo en pos de Ti,<br/>Al tomar la cruz, seguirte así.<br/>Consagrado sin reserva a Ti,<br/>Absoluto enteramente a Ti.<br/>Solo en nuestro corazón, Señor,<br/>Quepan las calzadas a Sion.<br/>',NULL,197022,5);
INSERT INTO stanza VALUES('S2233','chorus','Te seguiremos hoy,<br/>Respondemos a Tu voz,<br/>Nuestro todo te damos,<br/>¡Vemos la Nueva Jerusalén!<br/>¡Desciende aquí!<br/>El hombre mezclado con Dios,<br/>Nuestra unidad, glorioso es!<br/>Por siempre ¡Amén!<br/>Nos guía el Cordero aquí.<br/>',NULL,197023,6);
INSERT INTO stanza VALUES('S2233','SoundCloud Link','https://soundcloud.com/dani-b-313753210/quiero-seguirle-a-el',NULL,197024,7);
INSERT INTO stanza VALUES('S2234','1','La gente dice<br/>Que nada aprovechamos<br/>Sirviendo a Cristo<br/>En nuestra juventud.<br/>',NULL,197025,1);
INSERT INTO stanza VALUES('S2234','chorus','Pero nosotros les testificamos<br/>Que es un deleite<br/>Servir al Señor.<br/>Pero nosotros les testificamos<br/>Que es un deleite<br/>Servir al Señor.<br/>',NULL,197026,2);
INSERT INTO stanza VALUES('S2234','SoundCloud Link','https://soundcloud.com/user-497894694-364595996/la-gente-dice-que-nada',NULL,197027,3);
INSERT INTO stanza VALUES('S2235','1','Mi Jesús, mi primer amor,<br/>Todo Tuyo es mi corazón<br/>Nada se compara_a Ti en verdad,<br/>Tan hermoso y bello Señor.<br/>Cuando escucho el susurrar -<br/>De Tu hablar en mi corazón,<br/>Todo_amor y búsqueda queda atrás-<br/>Mis jactancias, ¡Qué vanas son!<br/>',NULL,197028,1);
INSERT INTO stanza VALUES('S2235','chorus','¿Quién tan dulce_en este universo es?<br/>¿Quién tan bello_en la tierra como Tú?<br/>Eres digno Tú de todo mi amor<br/>¡Muy profundo te_amo Jesús!<br/>No seré igual, no me engañaré -<br/>Ni_atrapado en mi mundo estaré<br/>Eres el mejor y mi_único amor.<br/>Tu amor, profundo_en mí ser.<br/>',NULL,197029,2);
INSERT INTO stanza VALUES('S2235','2','Mi Jesús, mi mejor amor,<br/>Aunque es terco mi corazón,<br/>Hazme esclavo hoy de Tu gran amor;<br/>Para amarte y obedecer.<br/>Aunque a veces te rechacé,<br/>Tu guiar siempre seguiré,<br/>Complacerte es mi mayor placer,<br/>Tu amor trae paz a mi ser.<br/>',NULL,197030,3);
INSERT INTO stanza VALUES('S2235','3','Mi Jesús, te adoro Señor.<br/>No me apartare más de Ti;<br/>Tu sonriente faz no se aleje de mí,<br/>Tu presencia deseo sentir.<br/>Yo te ofrezco mi corazón,<br/>Eres Tú mi satisfacción,<br/>Mi porción es Tu dulce ser poseer,<br/>Mi deseo único es.<br/>',NULL,197031,4);
INSERT INTO stanza VALUES('S2235','SoundCloud Link','https://soundcloud.com/kathmichelle12/mi-jesus-mi-primer-amor',NULL,197032,5);
INSERT INTO stanza VALUES('S2236','1','Señor, hay siempre_una persona,<br/>Como_Abraham<br/>Que corrió a verte<br/>Y Samuel que ministró<br/>Y David que dio su corazón<br/>Pero Tú quieres más.<br/>',NULL,197033,1);
INSERT INTO stanza VALUES('S2236','2','Señor, queremos ser como ellos,<br/>Que a Ti te refrescaron.<br/>Satisfacer Tu voluntad,<br/>Complacer Tu corazón,<br/>Ser Tus amigos, ¡sí!<br/>¿Qué haremos pues?<br/>',NULL,197034,2);
INSERT INTO stanza VALUES('S2236','chorus','Clamar, ¡Oh Señor!<br/>Y alabarte a Ti,<br/>Darnos sólo a Ti,<br/>Dejarte crecer.<br/>Señor, sólo para Ti<br/>Somos todos hoy.<br/>',NULL,197035,3);
INSERT INTO stanza VALUES('S2236','3','Eres misericordioso<br/>Para los santos que unidos,<br/>En Tu plan todos están;<br/>Danos hoy un limpio corazón,<br/>Que te ame sólo a Ti,<br/>Pero en verdad.<br/>',NULL,197036,4);
INSERT INTO stanza VALUES('S2236','chorus','Clamar, ¡Oh Señor!<br/>Y alabarte a Ti,<br/>Darnos sólo a Ti,<br/>Dejarte crecer.<br/>Señor, sólo para Ti<br/>Somos todos hoy.<br/>Solo en Ti.<br/>',NULL,197037,5);
INSERT INTO stanza VALUES('S2237','1','Bienaventurados,<br/>Los que lavan sus ropas,<br/>Para tener derecho,<br/>Al árbol de la vida.<br/>// Y para entrar<br/>Por las puertas de la cuidad.//<br/>',NULL,197038,1);
INSERT INTO stanza VALUES('S2237','2','Yo, Jesús, he enviado a mi ángel,<br/>Para daros testimonio,<br/>De estas cosas a la iglesia.<br/>Yo soy la raíz y el linaje de David,<br/>La estrella resplandeciente,<br/>Resplandeciente de la mañana.<br/>',NULL,197039,2);
INSERT INTO stanza VALUES('S2237','3','Y el Espíritu y la Novia,<br/>Dicen: “Ven”; y el que oye<br/>Diga: “Ven”<br/>Y el que tenga sed que venga.<br/>Y el que quiera,<br/>Tome del agua de la vida,<br/>Tome del agua de la vida gratuitamente.<br/>',NULL,197040,3);
INSERT INTO stanza VALUES('S2237','4','Y el que da testimonio,<br/>De estas cosas dice:<br/>//“Ciertamente vengo pronto”//<br/>//¡Amén sí ven! Señor Jesús,<br/>¡Amén sí ven!//<br/>',NULL,197041,4);
INSERT INTO stanza VALUES('S2237','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/apocalipsis-22-14-16',NULL,197042,5);
INSERT INTO stanza VALUES('S2238','1','¿Cómo narrar los sufrimientos<br/>Que Tú llevaste en la cruz, mi Salvador?<br/>Por Dios siendo herido y molido<br/>A causa de un soberbio pecador.<br/>Al considerarte, Te alabo;<br/>Derramo lagrimas, constreñido estoy;<br/>Todo mi ser a Ti consagro,<br/>Pues has pagado un gran precio Señor.<br/>',NULL,197043,1);
INSERT INTO stanza VALUES('S2238','chorus','Todo lo has hecho por mí, Señor Jesús,<br/>¿Y yo qué he hecho por Ti?<br/>Lo único que puedo hacer, mi Amado, es<br/>Consagrar mi ser a Ti.<br/>',NULL,197044,2);
INSERT INTO stanza VALUES('S2238','2','Tu corazón fue como cera<br/>Y derretido desde Tu interior;<br/>Se descoyuntaron Tus huesos,<br/>También Tu lengua al paladar se pegó.<br/>Fuiste como aguas derramado,<br/>Como un tiesto se seco Tu vigor;<br/>Siendo muerto y puesto en la muerte,<br/>Fue por mi causa que Dios Te quebrantó.<br/>',NULL,197045,3);
INSERT INTO stanza VALUES('S2238','3','Estando en gran agonía,<br/>Oraste al Padre en medio de la aflicción;<br/>Su voluntad siempre aceptaste;<br/>Contigo nadie ni una hora veló.<br/>En la cruz Te ven, Te escarnecen,<br/>Te menosprecian y se burlan de Ti;<br/>Fuiste aborrecido y sin causa,<br/>Sufriste oprobio y fue por amor a mí.<br/>',NULL,197046,4);
INSERT INTO stanza VALUES('S2238','4','Descendiste desde los cielos<br/>Para que un hombre pudiera ascender;<br/>Cargaste todas mis ofensas,<br/>Hoy por el Padre aceptado seré.<br/>Y el más grande sufrimiento:<br/>Por Dios un tiempo desamparado ser.<br/>Gracias a este sacrificio<br/>Puedo tener libre acceso a Él.<br/>',NULL,197047,5);
INSERT INTO stanza VALUES('S2238','SoundCloud Link','https://soundcloud.com/olga-maldonado-303867053/los-sufrimientos-de-cristo',NULL,197048,6);
INSERT INTO stanza VALUES('S2239','1','Yo escojo tomar<br/>El camino único que vence,<br/>Para de los valientes ser,<br/>Los del remanente<br/>Del único Valiente.<br/>',NULL,197049,1);
INSERT INTO stanza VALUES('S2239','chorus','Valiente Vencedor,<br/>Los Dios-hombres edificados;<br/>Expertos en batalla,<br/>En la guerra espiritual.<br/>Para combatir al enemigo.<br/>',NULL,197050,2);
INSERT INTO stanza VALUES('S2239','2','Amarle y vencer,<br/>Ejercito que su novia es;<br/>Pelea, vence por amor,<br/>Durante la guerra<br/>En el Armagedón.<br/>',NULL,197051,3);
INSERT INTO stanza VALUES('S2239','chorus','Valiente Vencedor,<br/>Los Dios-hombres edificados;<br/>Expertos en batalla,<br/>En la guerra espiritual.<br/>Para combatir al enemigo.<br/>',NULL,197052,4);
INSERT INTO stanza VALUES('S2239','chorus','Vencer por la sangre del Cordero.<br/>Guardar Tu palabra.<br/>No amar más la vida del alma.<br/>Me entrego a Ti para cumplir<br/>El deseo de Tu corazón,<br/>El deseo de Tu corazón.<br/>',NULL,197053,5);
INSERT INTO stanza VALUES('S2240','1','Eres fuente de aguas vivas,<br/>Pequé y busque otra fuente,<br/>Y he cavado cisternas,<br/>Te abres a mí<br/>Y entro en Ti;<br/>Tú vives en mí,<br/>Mi vida y todo Tú,<br/>Para edificar<br/>Tú complemento y<br/>Tú satisfecho serás.<br/>',NULL,197054,1);
INSERT INTO stanza VALUES('S2240','2','Eres disponible a mí,<br/>¡Puedo comerte y beberte!<br/>Y vivir por causa de Ti,<br/>Debido a<br/>Tu impartición;<br/>Inestimable<br/>Tesoro en mí ser,<br/>Tu satisfacción<br/>Es mi anhelo hoy,<br/>El Cuerpo, Tú expresión.<br/>',NULL,197055,2);
INSERT INTO stanza VALUES('S2240','3','Viniste a ser un hombre,<br/>Y Tú salvación efectuar;<br/>En vida y naturaleza<br/>Igual a Ti,<br/>Seremos al fin;<br/>Solo la novia<br/>Te hará regresar;<br/>Nuestro anhelo es<br/>En vida madurar,<br/>Y eternamente amarnos.<br/>',NULL,197056,3);
INSERT INTO stanza VALUES('S2240','SoundCloud Link','https://soundcloud.com/ymalv/el-dios-triuno-es-mi-vida',NULL,197057,4);
INSERT INTO stanza VALUES('S2241','1','Dios en Su economía eterna,<br/>Tiene a Cristo como realidad;<br/>Es el centro y la universalidad,<br/>Por el cual Su gloria expresará.<br/>',NULL,197058,1);
INSERT INTO stanza VALUES('S2241','2','Disfrutando en la iglesia a Cristo,<br/>Como el agrandamiento de Dios;<br/>Nos da Su suministro de vida eternal,<br/>Es la casa que nos preparó.<br/>',NULL,197059,2);
INSERT INTO stanza VALUES('S2241','chorus','Al experimentar y disfrutar,<br/>A Cristo como realidad.<br/>La iglesia en vida con Dios crecerá,<br/>Para ser Su morada eternal.<br/>El plan de Dios se cumplirá,<br/>La iglesia agrandada será.<br/>Y la casa se convertirá en la ciudad,<br/>Y así Dios la tierra obtendrá.<br/>',NULL,197060,3);
INSERT INTO stanza VALUES('S2241','3','Con la iglesia siendo edificada,<br/>El Señor obtendrá una ciudad;<br/>Donde Dios a través de ella pueda reinar,<br/>Ejerciendo Su autoridad.<br/>',NULL,197061,4);
INSERT INTO stanza VALUES('S2241','4','Dios quiere conquistar hoy la tierra,<br/>Recobrarla en su totalidad;<br/>Al vencer esta era y con Él cooperar,<br/>El Señor pronto regresará.<br/>',NULL,197062,5);
INSERT INTO stanza VALUES('S2241','chorus','Al experimentar y disfrutar,<br/>A Cristo como realidad.<br/>La iglesia en vida con Dios crecerá,<br/>Para ser Su morada eternal.<br/>El plan de Dios se cumplirá,<br/>La iglesia agrandada será.<br/>Y la casa se convertirá en la ciudad,<br/>Y así Dios la tierra obtendrá.<br/>',NULL,197063,6);
INSERT INTO stanza VALUES('S2241','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/himno-gen23',NULL,197064,7);
INSERT INTO stanza VALUES('S2242','1','Y vi la Santa Ciudad<br/>La Nueva Jerusalén,<br/>La mezcla del hombre y Dios<br/>Entidad viviente es.<br/>La novia que llega a ser,<br/>Para Su satisfacción.<br/>',NULL,197065,1);
INSERT INTO stanza VALUES('S2242','chorus','Muerte y resurrección,<br/>Házme experimentar,<br/>Para que en la ciudad,<br/>Otros puedan entrar;<br/>Siendo así transformados<br/>Hasta perlas ser,<br/>Las puertas de la Nueva Jerusalén.<br/>',NULL,197066,2);
INSERT INTO stanza VALUES('S2242','2','Doce puertas perlas son,<br/>Por la regeneración;<br/>La ostra herida Cristo es,<br/>Que su vida liberó.<br/>Su vital resurrección;<br/>Este grano transformó.<br/>',NULL,197067,3);
INSERT INTO stanza VALUES('S2242','3','Por la entrada Triuna,<br/>Padre, Hijo, Espíritu,<br/>Busca hasta encontrar,<br/>Al valioso pecador;<br/>Y lo trae a disfrutar;<br/>Con el Padre en Su amor.<br/>',NULL,197068,4);
INSERT INTO stanza VALUES('S2243','1','Dios me regeneró<br/>Para darme Su vida,<br/>Su vida divina,<br/>Dentro de mi espíritu.<br/>Y así llegar a ser<br/>Su expresión gloriosa<br/>Expresando Sus virtudes<br/>A través de la humanidad.<br/>',NULL,197069,1);
INSERT INTO stanza VALUES('S2243','2','Dios me renovó<br/>Para llegar a ser<br/>Su nueva creación,<br/>El hombre nuevo que Él creo.<br/>Dios me santificó<br/>Para darme Su naturaleza,<br/>Su santa naturaleza,<br/>Dentro de todo mí ser.<br/>',NULL,197070,2);
INSERT INTO stanza VALUES('S2243','3','Dios me transforma sí,<br/>Para que pueda obtener<br/>Su imagen divina<br/>Y expresarlo en plenitud.<br/>Dios me glorifico<br/>Para que Su imagen,<br/>Su imagen divina,<br/>Sea expresada en plenitud.<br/>',NULL,197071,3);
INSERT INTO stanza VALUES('S2243','SoundCloud Link','',NULL,197072,4);
INSERT INTO stanza VALUES('S2244','1','En la tienda de reunión<br/>Alimentamos a Dios,<br/>Trayendo nuestras ofrendas<br/>Del Cristo experimentado.<br/>Nos identificamos con Él<br/>Imponiendo nuestras manos,<br/>Admitiendo que en mi ser<br/>Soy el hombre natural.<br/>Que soy carne de pecado<br/>Cometiendo transgresiones<br/>Y que en mi humanidad<br/>Nada queda para Él.<br/>',NULL,197073,1);
INSERT INTO stanza VALUES('S2244','2','Absoluto para Dios no soy<br/>En mi humanidad tan pobre.<br/>Pero Cristo es mi ofrenda,<br/>Mi ofrenda encendida.<br/>Y Él sí es absoluto,<br/>Como la ofrenda encendida<br/>Y por Él soy aceptado<br/>A los ojos de mi Dios.<br/>Él siempre está dispuesto<br/>A ser puesto en el altar,<br/>Juntamente con Él<br/>Nos dejaremos quemar.<br/>',NULL,197074,2);
INSERT INTO stanza VALUES('S2244','3','Quiero ser un ofrendarte<br/>Que siempre está ofreciendo,<br/>Presentándole a mi Dios<br/>A Cristo en mi adoración.<br/>Señor queremos complacerte<br/>Y queremos sustentarte,<br/>Trayéndote la grosura<br/>A la tienda de reunión.<br/>Deseable es la reunión,<br/>La reunión de los santos<br/>Donde podemos estar<br/>En constante comunión.<br/>',NULL,197075,3);
INSERT INTO stanza VALUES('S2244','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/en-la-tienda-de-reuni-n',NULL,197076,4);
INSERT INTO stanza VALUES('S2245','1','Justificados pues por la fe<br/>Tenemos paz para con Dios,<br/>Por medio de nuestro<br/>Señor Jesucristo.<br/>',NULL,197077,1);
INSERT INTO stanza VALUES('S2245','chorus','Porque el amor de Dios<br/>Ha sido derramado<br/>En nuestros corazones,<br/>Mediante el Espíritu Santo<br/>Que nos fue dado a nosotros.<br/>',NULL,197078,2);
INSERT INTO stanza VALUES('S2245','2','Mas Dios muestra su amor<br/>Para con nosotros,<br/>En que siendo aun pecadores<br/>Cristo murió por nosotros.<br/>',NULL,197079,3);
INSERT INTO stanza VALUES('S2246','1','Y sin afanes,<br/>Mas sean conocidas<br/>Vuestras peticiones<br/>Por medio de oración<br/>Y con acción de gracias,<br/>Orando al Señor.<br/>',NULL,197080,1);
INSERT INTO stanza VALUES('S2246','chorus','Por lo demás, hermanos,<br/>Todo lo que es verdadero,<br/>Todo lo honorable<br/>Y lo justo y lo puro,<br/>Todo lo amable,<br/>Todo lo que es de buen nombre,<br/>Si hay virtud alguna,<br/>Si alguna alabanza,<br/>En esto pensad.<br/>',NULL,197081,2);
INSERT INTO stanza VALUES('S2246','2','Y la paz de Dios<br/>Que sobrepasa<br/>Todo entendimiento,<br/>Guardará vuestros corazones<br/>Y vuestros pensamientos,<br/>En Cristo Jesús.<br/>',NULL,197082,3);
INSERT INTO stanza VALUES('S2246','3','Lo que aprendisteis,<br/>Recibisteis y oísteis<br/>Y visteis en mí,<br/>Esto poned en práctica;<br/>Y el Dios de paz,<br/>En vosotros estará.<br/>',NULL,197083,4);
INSERT INTO stanza VALUES('S2246','SoundCloud Link','',NULL,197084,5);
INSERT INTO stanza VALUES('S2247','1','Y ser hallado en Él,<br/>No teniendo mi propia justicia<br/>Que es por la ley,<br/>Sino la que es por medio<br/>De la fe en Cristo,<br/>La justicia procedente de Dios<br/>Basada en la fe.<br/>',NULL,197085,1);
INSERT INTO stanza VALUES('S2247','2','A fin de conocerle<br/>Y el poder de Su resurrección<br/>Y la comunión en Sus padecimientos,<br/>Configurándome<br/>A Su muerte.<br/>',NULL,197086,2);
INSERT INTO stanza VALUES('S2247','3','Si en alguna<br/>Manera llegase<br/>A la súper resurrección<br/>De entre los muertos.<br/>',NULL,197087,3);
INSERT INTO stanza VALUES('S2247','4','No que lo haya alcanzado ya,<br/>Ni que ya haya sido perfeccionado,<br/>Sino que prosigo por ver si logro<br/>Asir aquello para lo cual fui también<br/>Asido por Cristo Jesús.<br/>',NULL,197088,4);
INSERT INTO stanza VALUES('S2247','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/filipenses-3-9-11-ser-1',NULL,197089,5);
INSERT INTO stanza VALUES('S2248','1','Con desesperación<br/>La mujer el manto tocó<br/>Haciendo a Jesús volver<br/>Al sacar de El virtud.<br/>',NULL,197090,1);
INSERT INTO stanza VALUES('S2248','chorus','No solo ser de los que le aprietan.<br/>Sino acercarse a tocar Su manto,<br/>Sin religión y sin formalismos,<br/>Para tocarle y hacerle volver.<br/>',NULL,197091,2);
INSERT INTO stanza VALUES('S2248','2','Cuando los de Emaús<br/>Lo vieron al partir el pan,<br/>Volvieron a Jerusalén<br/>A la vida de reunión.<br/>',NULL,197092,3);
INSERT INTO stanza VALUES('S2248','3','A los Efesios provocó<br/>Cincuenta mil piezas quemar.<br/>Cuando tocamos al Señor<br/>Queremos limpios estar.<br/>',NULL,197093,4);
INSERT INTO stanza VALUES('S2248','YouTube Link','https://www.youtube.com/watch?app=desktop&v=uzsd9Xy4XwY',NULL,197094,5);
INSERT INTO stanza VALUES('S2249','chorus','Oh Señor Jesús, Oh Señor Jesús.<br/>Justo, santo y glorioso<br/>Eres Tú, Oh Señor Jesús.<br/>',NULL,197095,1);
INSERT INTO stanza VALUES('S2249','1','Sabemos que a los que aman a Dios<br/>Todas las cosas cooperan a bien,<br/>Los que conforme a Su propósito<br/>Llamados son, ¡Oh Señor Jesús!<br/>',NULL,197096,2);
INSERT INTO stanza VALUES('S2249','2','Porque a los que antes conoció,<br/>También los predestinó,<br/>Para conformarlos a la imagen<br/>De Su Hijo Jesús, Oh Señor Jesús.<br/>',NULL,197097,3);
INSERT INTO stanza VALUES('S2249','3','Y a los que predestinó,<br/>A estos también llamó<br/>Y también justificó<br/>Y glorificó, Oh Señor Jesús.<br/>',NULL,197098,4);
INSERT INTO stanza VALUES('S2249','4','Maravilloso es saber<br/>Que Tú nos amas Oh Señor.<br/>Por eso cada día<br/>Te bendeciré y alabaré.<br/>',NULL,197099,5);
INSERT INTO stanza VALUES('S2249','SoundCloud Link','https://soundcloud.com/clara-orjuela-78079798/romanos-8-30',NULL,197100,6);
INSERT INTO stanza VALUES('S2250','1','Debemos amar<br/>La manifestación del Señor.<br/>Debemos esperar<br/>Con anhelo Su regreso.<br/>Como vírgenes sabias<br/>Debemos estar,<br/>Con aceite en las lámparas<br/>Y en los vasos también.<br/>',NULL,197101,1);
INSERT INTO stanza VALUES('S2250','2','Debemos oír<br/>La palabra profética,<br/>como una lámpara<br/>Que alumbra en la oscuridad.<br/>Debemos velar<br/>Y el corazón cuidar,<br/>Libres de la embriagues<br/>Y de toda ansiedad.<br/>',NULL,197102,2);
INSERT INTO stanza VALUES('S2250','3','Alertas estar,<br/>Constantemente orar<br/>Y así escapar<br/>De la ira del Señor<br/>Y delante de Cristo,<br/>De pie poder estar<br/>Como vírgenes sabias<br/>En las bodas entrar.<br/>',NULL,197103,3);
INSERT INTO stanza VALUES('S2251','1','Señor, me quieres para Ti,<br/>Como Novia,<br/>Te abro hoy mi corazón,<br/>Es para Ti.<br/>Un íntimo amor, afectuoso,<br/>Es lo que Tú buscas en mí,<br/>A diario_en Tu presencia vivir,<br/>En unidad.<br/>',NULL,197104,1);
INSERT INTO stanza VALUES('S2251','note','**Coro parte 1:**<br/>Tienes un eterno_amor por mí.<br/>Yo tengo un eterno_amor por Ti,<br/>Mas proviene de Ti.<br/>',NULL,197105,2);
INSERT INTO stanza VALUES('S2251','note','**Coro parte 2:**<br/>Tu infinito amor me halló;<br/>Me_atrajo y me ha ganado.<br/>Vertiste amor en mí para que Te ame.<br/>',NULL,197106,3);
INSERT INTO stanza VALUES('S2251','2','Como_ola poderosa es<br/>Tu amor, Señor,<br/>Que me constriñe a amarte más,<br/>Libre no soy.<br/>Oh, guárdame siempre en Tu amor;<br/>Tu Palabra me da poder<br/>Para_amarte con mi_alma,<br/>Fuerza, todo mi ser.<br/>',NULL,197107,4);
INSERT INTO stanza VALUES('S2251','note','**Coro parte 1:**<br/>Tienes un eterno_amor por mí.<br/>Yo tengo un eterno_amor por Ti,<br/>Mas proviene de Ti.<br/>',NULL,197108,5);
INSERT INTO stanza VALUES('S2251','note','**Coro parte 2:**<br/>Tu infinito amor me halló;<br/>Me_atrajo y me ha ganado.<br/>Vertiste amor en mí para que Te ame.<br/>',NULL,197109,6);
INSERT INTO stanza VALUES('S2251','3','Te amo porque primero<br/>Me amaste Tú<br/>Tú eres el Eterno Amor,<br/>Vives en mí.<br/>Cuanto más me abro a Tu amor,<br/>Más aumenta el amor en mí,<br/>Nuestro amor disfrutaremos para siempre.<br/>',NULL,197110,7);
INSERT INTO stanza VALUES('S2251','note','**Coro parte 1:**<br/>Tienes un eterno_amor por mí.<br/>Yo tengo un eterno_amor por Ti,<br/>Mas proviene de Ti.<br/>',NULL,197111,8);
INSERT INTO stanza VALUES('S2251','note','**Coro parte 2:**<br/>Tu infinito amor me halló;<br/>Me_atrajo y me ha ganado.<br/>Vertiste amor en mí para que Te ame.<br/>',NULL,197112,9);
INSERT INTO stanza VALUES('S2251','note','**Final:**<br/>Tienes un eterno_amor por mí.<br/>Yo tengo un eterno_amor por Ti.<br/>',NULL,197113,10);
INSERT INTO stanza VALUES('S2251','SoundCloud Link','https://soundcloud.com/dani_candia/eterno-amor-forever-love',NULL,197114,11);
INSERT INTO stanza VALUES('S2252','1','El Testimonio de Jesús,<br/>Aquí en la tierra<br/>Debemos expresar.<br/>Y corriendo a la meta con los santos,<br/>Una vida de iglesia y edificación.<br/>',NULL,197115,1);
INSERT INTO stanza VALUES('S2252','chorus','Vencedores, en ésta era.<br/>Haznos fieles, a Tu voluntad.<br/>Resplandecer en la oscuridad,<br/>Y brillar en la Iglesia local.<br/>No importa el precio<br/>Que hay que pagar,<br/>Para Su arca edificar.<br/>',NULL,197116,2);
INSERT INTO stanza VALUES('S2252','2','Necesitamos todos crecer<br/>Al confesarnos<br/>Y así poder vencer.<br/>Y ser las primicias<br/>Que el Señor desea,<br/>Consumar Su plan<br/>En la Nueva Jerusalén.<br/>',NULL,197117,3);
INSERT INTO stanza VALUES('S2252','SoundCloud Link','https://soundcloud.com/ypeurope/11-spanish',NULL,197118,4);
INSERT INTO stanza VALUES('S2253','1','Y vi la santa ciudad<br/>La Nueva Jerusalén<br/>Descender del cielo de Dios;<br/>Dispuesta<br/>Como una Novia<br/>Ataviada para su Marido,<br/>Descender del cielo de Dios. (x2)<br/>',NULL,197119,1);
INSERT INTO stanza VALUES('S2253','SoundCloud Link','https://soundcloud.com/carlos-avendano-601540303/y-vi-la-santa-ciudad-apocalipsis-212',NULL,197120,2);
INSERT INTO stanza VALUES('S2254','1','A mi Señor voy a cantar,<br/>Pues recibí<br/>Misericordia, amor y gracia,<br/>En Cristo Jesús.<br/>¡Oh, qué amor!<br/>Aún sin merecerlo<br/>Se dio para mí.<br/>',NULL,197121,1);
INSERT INTO stanza VALUES('S2254','chorus','Abro mi corazón<br/>Para rendírte loor.<br/>Hay una infinita gratitud<br/>Por todo<br/>Lo que_has hecho por mi.<br/>',NULL,197122,2);
INSERT INTO stanza VALUES('S2254','2','En mi lugar<br/>Cumplió Jesús toda la ley;<br/>Obedeció, por Su sufrir<br/>Me justificó.<br/>Complació<br/>El corazón de Dios<br/>¡Oh, qué redención!<br/>',NULL,197123,3);
INSERT INTO stanza VALUES('S2254','chorus','Abro mi corazón<br/>Para rendírte loor.<br/>Hay una infinita gratitud<br/>Por todo<br/>Lo que_has mostrado a mí.<br/>',NULL,197124,4);
INSERT INTO stanza VALUES('S2254','3','Las buenas nuevas<br/>El Señor me reveló.<br/>¡Oh, cuanta gracia!<br/>Su amor fluyó dentro_en mí<br/>Su mirar,<br/>Tan lleno de ternura<br/>A Dios me llevó.<br/>',NULL,197125,5);
INSERT INTO stanza VALUES('S2254','chorus','Abro mi corazón<br/>Para rendírte loor.<br/>Hay una infinita gratitud<br/>Por todo<br/>Lo que_has hecho por mi.<br/>',NULL,197126,6);
INSERT INTO stanza VALUES('S2254','4','Camino vivo abrió Jesús,<br/>El velo rasgó.<br/>Resucitó,<br/>Cumplió la obra<br/>¡Vive el Señor!<br/>¡Oh, que paz!<br/>Puedo entrar al<br/>Santísimo lugar.<br/>',NULL,197127,7);
INSERT INTO stanza VALUES('S2254','chorus','Abro mi corazón<br/>Para rendírte loor<br/>Tu nombre rico invocaré:<br/>¡Oh Jesús!<br/>Precioso_es para mí.<br/>',NULL,197128,8);
INSERT INTO stanza VALUES('S2254','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/infinita-gratitud-infinite',NULL,197129,9);
INSERT INTO stanza VALUES('S2255','1','Sin Tu presencia, mi Dios<br/>Mi_alma desfallece aquí;<br/>Noche_en día cambiarás<br/>Sólo al contemplar Tu faz.<br/>',NULL,197130,1);
INSERT INTO stanza VALUES('S2255','2','Temo Tu rostro perder<br/>Pero Tu Palabra es fiel<br/>Confieso_y me limpias Tú<br/>Cuando vengo a Tu luz.<br/>',NULL,197131,2);
INSERT INTO stanza VALUES('S2255','3','“Mi presencia contigo_irá<br/>Y reposo te daré”<br/>Creo_en Tu fidelidad.<br/>Dios, negarte no podrás.<br/>',NULL,197132,3);
INSERT INTO stanza VALUES('S2255','4','Dejo este mundo atrás<br/>Virgen sabia he de ser<br/>Me preparo y velaré<br/>Hasta que regrese Él.<br/>',NULL,197133,4);
INSERT INTO stanza VALUES('S2255','5','Por Tu manifestación<br/>Te buscamos en amor.<br/>Anhelamos hoy vivir<br/>En Tu presencia gentil.<br/>',NULL,197134,5);
INSERT INTO stanza VALUES('S2255','6','Tu unción obedecer<br/>Para en Ti permanecer<br/>Amo Tu manifestación<br/>“Ven Señor”_ es mi oración.<br/>',NULL,197135,6);
INSERT INTO stanza VALUES('S2255','7','Tua_unção obedecer<br/>Para em Ti permanecer,<br/>Amo Tua_manifestação<br/>“Vem Senhor”_é mi’a oração.<br/>',NULL,197136,7);
INSERT INTO stanza VALUES('S2255','SoundCloud Link','https://soundcloud.com/camila-gomes-35158922/hino-graduacao-2020-1',NULL,197137,8);
INSERT INTO stanza VALUES('S2256','1','Mi Cristo me quiere limpiar,<br/>Mis pecados Su luz mostrará.<br/>¡Al confesar, Dios nos perdonará!<br/>Entonces Su vida fluirá.<br/>',NULL,197138,1);
INSERT INTO stanza VALUES('S2256','chorus','¡Cristo ͜es viviente ͜en mí!<br/>¡Siempre quiere ͜impartir,<br/>Su vida que ͜en todo puede vencer!<br/>¡Debemos cooperar!<br/>¡No te lo ͜has de pensar!<br/>¡Le dejamos en nuestro ser obrar!<br/>',NULL,197139,2);
INSERT INTO stanza VALUES('S2256','2','El mundo, ͜imposible vencer.<br/>¡Pero fuerte mi ͜espíritu es!<br/>Si ͜invoco ͜al Señor, le respiro también,<br/>¡El mundo no podrá vencer!<br/>',NULL,197140,3);
INSERT INTO stanza VALUES('S2256','3','Debemos tratar con el yo,<br/>Con la carne ͜y con lo natural.<br/>No ͜ independientes, ni en división,<br/>¡Su ͜ Espíritu me liberó!<br/>',NULL,197141,4);
INSERT INTO stanza VALUES('S2256','SoundCloud Link','https://soundcloud.com/valen_torres/cristo-es-viviente-en-m-ft-j',NULL,197142,5);
INSERT INTO stanza VALUES('S2257','1','Dios estaba solo en la eternidad,<br/>Conforme al deseo<br/>De Su corazón planeó;<br/>A Su imagen al hombre Él lo formó,<br/>Se enamoró, se procesó y lo alcanzó.<br/>En la escalera nupcial estoy,<br/>Mi Amado arriba espera por mí;<br/>Mi espíritu es el mejor lugar<br/>Para vivir y estar unido a Él.<br/>',NULL,197143,1);
INSERT INTO stanza VALUES('S2257','chorus','Dios vino en el Hijo y se llamó Jesús,<br/>Nuestro modelo<br/>Quien se entregó en la cruz;<br/>Se transfiguró y como el Espíritu<br/>Al hombre Su vida le dio.<br/>',NULL,197144,2);
INSERT INTO stanza VALUES('S2257','2','Despierto al alba para contemplar<br/>A quien me amó<br/>Y se entregó a Sí mismo por mí;<br/>Ahora ya no quiero vivir más yo,<br/>Mas por Aquél que por mí murió.<br/>Al invocar: ¡Jesús!<br/>Con Su persona estoy;<br/>Se hace real en mi vida,<br/>Dependiente soy,<br/>Disfruto de Sus riquezas y Su salvación,<br/>Soy lleno de Él y le puedo expresar.<br/>',NULL,197145,3);
INSERT INTO stanza VALUES('S2257','chorus','En mi espíritu lo puedo contemplar,<br/>Su sonrisa y Su mirada<br/>Son mi atracción;<br/>En Sus labios:<br/>Miel y leche son mi provisión<br/>Con Sus Palabras me nutro hoy.<br/>',NULL,197146,4);
INSERT INTO stanza VALUES('S2257','3','Sus palabras son mi alimento espiritual,<br/>Obtengo a Cristo como mi plena realidad;<br/>Como de ellas, y vivo por causa de Aquél<br/>Quien por causa del Padre vivió.<br/>Como, digiero y asimilo a mi Señor<br/>Al recibir Su palabra con toda oración;<br/>Produce en mí crecimiento y transformación<br/>Edificado en el Cuerpo en amor.<br/>',NULL,197147,5);
INSERT INTO stanza VALUES('S2257','chorus','Permitimos Su hogar<br/>Haga en nuestro corazón,<br/>Nos sumergimos<br/>En el océano de Su amor,<br/>Conocemos las dimensiones del Señor,<br/>Crecemos hasta Su plenitud.<br/>',NULL,197148,6);
INSERT INTO stanza VALUES('S2257','chorus','La Nueva Jerusalén nuestro destino es,<br/>Ver y entrar<br/>En la cumbre de la revelación;<br/>Cuidar tiernamente y alimentar,<br/>Llegamos a vivir la visión.<br/>',NULL,197149,7);
INSERT INTO stanza VALUES('S2257','SoundCloud Link','https://soundcloud.com/jules-campos-kalaidjian/himno-composicion-etcc-2021-2',NULL,197150,8);
INSERT INTO stanza VALUES('S2258','1','Fueron halladas Tus palabras<br/>Y yo las comí.<br/>Oh, Señor Jesús,<br/>Fueron dulces para mí<br/>Y por gozo‿y‿alegría de mi corazón.<br/>Fueron halladas Tus palabras<br/>Y yo las comí<br/>//Porque Tu nombre se invocó:<br/>¡Oh, Señor Jesús!//<br/>',NULL,197151,1);
INSERT INTO stanza VALUES('S2258','SoundCloud Link','https://soundcloud.com/user-889434062/fueron-halladas-tus-palabras',NULL,197152,2);
INSERT INTO stanza VALUES('S2259','1','El Señor es mi Pastor<br/>Y nada, me faltará;<br/>El Señor es mi Pastor<br/>Y nada, me faltará.<br/>',NULL,197153,1);
INSERT INTO stanza VALUES('S2259','2','Y aunque yo ande<br/>Por el valle<br/>De sombra de muerte nada;<br/>Y aunque yo ande<br/>Por el valle<br/>De sombra de muerte nada...<br/>',NULL,197154,2);
INSERT INTO stanza VALUES('S2259','chorus','Nada temeré;<br/>Nada temeré;<br/>Nada temeré;<br/>Nada temeré. (x2)<br/>',NULL,197155,3);
INSERT INTO stanza VALUES('S2259','SoundCloud Link','https://soundcloud.com/user-541173579/nada-temere-salmo-23',NULL,197156,4);
INSERT INTO stanza VALUES('S2260','1','En el principio puso Dios<br/>Al hombre frente a dos arboles, son:<br/>El arbol de la vida<br/>Y el del conocimiento.<br/>Uno a la vida te llevará,<br/>Pero el otro a morir y pecar.<br/>No te satisfaga<br/>El ser "buen cristiano",<br/>Más come a Cristo!<br/>',NULL,197157,1);
INSERT INTO stanza VALUES('S2260','chorus','Arbol<br/>De vida es El,<br/>Suministro fiel.<br/>Escojamos Su vida!<br/>Cómele<br/>Y disfrútale!<br/>Abrete a El.<br/>Depende de Su vida.<br/>(Final: Come a Cristo hoy).<br/>',NULL,197158,2);
INSERT INTO stanza VALUES('S2260','2','¡Todos pueden comer de El!<br/>Si te abres, lleno tu podras ser,<br/>Y Le expresarás al participar<br/>De_este arbol de vida.<br/>Dale siempre el primer lugar,<br/>Si Le amas, Su vida impartirá;<br/>En tu espíritu El te llenará;<br/>Satisfecho siempre.<br/>',NULL,197159,3);
INSERT INTO stanza VALUES('S2260','SoundCloud Link','https://soundcloud.com/user-537299855/en-el-principio-puso-dios',NULL,197160,4);
INSERT INTO stanza VALUES('S2261','1','El Jesús Maravilloso quien está<br/>Entronizado en los cielos,<br/>Y coronado con gloria y honor<br/>Es la mayor atracción<br/>Que existe en el universo,<br/>Él es como un enorme imán<br/>Que atrae a todos los que le buscan,<br/>Los que le buscan.<br/>',NULL,197161,1);
INSERT INTO stanza VALUES('S2261','2','Al ser atraídos por Su belleza<br/>Encantadora<br/>Dejamos de ver todo lo que no es Él.<br/>Si no tuviéramos<br/>Un objeto tan atractivo<br/>¿Cómo podríamos dejar<br/>De mirar tantas cosas que nos<br/>Distraen en la tierra?<br/>',NULL,197162,2);
INSERT INTO stanza VALUES('S2261','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/el_jesus_maravilloso',NULL,197163,3);
INSERT INTO stanza VALUES('S2262','1','Llamo por testigos<br/>Hoy contra vosotros<br/>Llamo por testigos<br/>Hoy contra vosotros<br/>A los cielos y a la tierra:<br/>Te he puesto delante<br/>La vida y la muerte<br/>A los cielos y a la tierra:<br/>Te he puesto delante<br/>La bendición y la maldición.<br/>',NULL,197164,1);
INSERT INTO stanza VALUES('S2262','chorus','Escoge pues la vida, para<br/>Para que vivas,<br/>Para que vivas,<br/>Escoge, pues, la vida, para<br/>Para que vivas,<br/>Tú y tu descendencia.<br/>',NULL,197165,2);
INSERT INTO stanza VALUES('S2262','SoundCloud Link','https://on.soundcloud.com/hw0FiNQtUVeDwtgoJc',NULL,197166,3);
INSERT INTO stanza VALUES('S2263','1','Cada día en amor,<br/>En tormentas o en sol,<br/>Muy pequeña es mi fe,<br/>¡Amo_a Cristo eso sé!<br/>',NULL,197167,1);
INSERT INTO stanza VALUES('S2263','chorus','Los días podrán pasar,<br/>El tiempo puede volar;<br/>Pero_a Cristo he de_amar<br/>Por toda la_eternidad.<br/>',NULL,197168,2);
INSERT INTO stanza VALUES('S2263','2','Su aliento recibí<br/>En mi pobre corazón;<br/>Mientras Él me guíe_a mí<br/>Mi amor no es fugaz.<br/>',NULL,197169,3);
INSERT INTO stanza VALUES('S2263','3','Cantando_en la claridad<br/>O en densa_oscuridad,<br/>A Su sangre clamaré,<br/>De Su_amor me llenaré.<br/>',NULL,197170,4);
INSERT INTO stanza VALUES('S2263','4','Mi amor ha de durar<br/>Aunque tierra no_haya más,<br/>Su venida_esperaré,<br/>Hasta_entonces le_amaré.<br/>',NULL,197171,5);
INSERT INTO stanza VALUES('S2264','1','No quiero_vivir una vida<br/>Vacía, sin sentido<br/>Quiero un propósito tener ,<br/>Te necesito Señor,<br/>Equípame con Tu Palabra<br/>Para defender la fe<br/>A tu lado_estar, por la Verdad.<br/>',NULL,197172,1);
INSERT INTO stanza VALUES('S2264','2','//Jesús es todo para mi,<br/>Es el Espíritu<br/>Su nombre, Maravilloso_es,<br/>Dios fuerte, Consejero.<br/>Disfrutemos al Triuno Dios.//<br/>Disfrutemos al Triuno Dios<br/>El Triuno Dios.<br/>',NULL,197173,2);
INSERT INTO stanza VALUES('S2264','SoundCloud Link','https://soundcloud.com/user-144035804/no-quiero-vivir-una-vida-sin-sentido',NULL,197174,3);
INSERT INTO stanza VALUES('S2265','1','Tan atraído<br/>Por Tu amor<br/>Y conquistado por Ti.<br/>En Tu dulzura<br/>Corro en pos de Ti<br/>Para mi satisfacción<br/>',NULL,197175,1);
INSERT INTO stanza VALUES('S2265','chorus','Me enamoré,<br/>Me enamoré,<br/>Me enamoré<br/>De Aquel, el más hermoso.<br/>',NULL,197176,2);
INSERT INTO stanza VALUES('S2265','2','Tan cautivado<br/>Por Tu nombre<br/>Y fascinado por Ti;<br/>Tu fragancia<br/>Me envolvió,<br/>Me besaste<br/>Con los besos de Tu boca<br/>',NULL,197177,3);
INSERT INTO stanza VALUES('S2265','chorus','Me enamoré,<br/>Me enamoré,<br/>Me enamoré<br/>Del más afectuoso.<br/>',NULL,197178,4);
INSERT INTO stanza VALUES('S2265','3','Tan amorosa<br/>Comunión<br/>Regocijándome en Ti.<br/>En tus cámaras<br/>Disfruto<br/>Dulce amor<br/>Por la iglesia, Tu deseo<br/>',NULL,197179,5);
INSERT INTO stanza VALUES('S2265','chorus','Me enamoré,<br/>Me enamoré,<br/>Me enamoré<br/>De Aquel, el más íntimo.<br/>{Final: Me enamoré}<br/>',NULL,197180,6);
INSERT INTO stanza VALUES('S2265','SoundCloud Link','https://soundcloud.com/pablo-suarez-acosta/tan-atraido-por-tu-amor-traduccion-provisional',NULL,197181,7);
INSERT INTO stanza VALUES('S2266','1','De ésta era, al final,<br/>Antes que Él venga,<br/>Antes que Él venga;<br/>Hoy debemos<br/>Grandes resoluciones hacer,<br/>De corazón.<br/>',NULL,197182,1);
INSERT INTO stanza VALUES('S2266','chorus','Grandes resoluciones hoy de<br/>Corazón debemos hacer,<br/>Grandes resoluciones y escu-<br/>driñamientos de corazón,<br/>De corazón, de corazón.<br/>',NULL,197183,2);
INSERT INTO stanza VALUES('S2266','2','[Puente:]<br/>Ser absolutamente consagrados<br/>A Dios, con un corazón que<br/>Le_ame, siga_y viva;<br/>Y ser constituidos<br/>Con Él,<br/>Para Su expresión ser,<br/>Debemos hacer:<br/>',NULL,197184,3);
INSERT INTO stanza VALUES('S2266','chorus','Grandes resoluciones hoy de<br/>Corazón debemos hacer,<br/>Grandes resoluciones y escu-<br/>driñamientos de corazón,<br/>De corazón, de corazón.<br/>De corazón, de corazón.<br/>',NULL,197185,4);
INSERT INTO stanza VALUES('S2266','chorus','# Estrofa y coro pueden ser cantados en canon #<br/>',NULL,197186,5);
INSERT INTO stanza VALUES('S2266','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/grandes-resoluciones-de-coraz',NULL,197187,6);
INSERT INTO stanza VALUES('S2267','1','Pueden los montes apartarse<br/>Y los collados temblar,<br/>Pero no se apartará de ti,<br/>Mi Benevolencia,<br/>Ni Mi pacto de paz<br/>Vacilará, dice Jehová;<br/>El que tiene compasión,<br/>Compasión de ti.<br/>',NULL,197188,1);
INSERT INTO stanza VALUES('S2267','chorus','Porque Tu Hacedor es Tu Marido,<br/>Jehová de los Ejercitos!<br/>Y El Santo de Israel.<br/>Es Tu Redentor y Su Nombre<br/>Es Dios de toda la tierra,<br/>Señor Jesús:<br/>Nuestro Salvador y Dios.<br/>',NULL,197189,2);
INSERT INTO stanza VALUES('S2267','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/pueden-los-montes-apartarse-y',NULL,197190,3);
INSERT INTO stanza VALUES('S2268','1','Levántate Aquilón,<br/>Y ven, Austro;<br/>Sopla en mi huerto,<br/>Despréndanse sus aromas. (2x)<br/>',NULL,197191,1);
INSERT INTO stanza VALUES('S2268','2','Venga mi Amado a su huerto,<br/>Y coma de su dulce fruta.(2x)<br/>',NULL,197192,2);
INSERT INTO stanza VALUES('S2268','3','Yo vine a mi huerto,<br/>Oh hermana, esposa mía; (2x)<br/>',NULL,197193,3);
INSERT INTO stanza VALUES('S2268','4','He recogido mi mirra y mis aromas;<br/>He comido mi panal y mi miel. (2x)<br/>',NULL,197194,4);
INSERT INTO stanza VALUES('S2268','5','Yo dormía,<br/>Mi corazón velaba.<br/>Era la voz de mi amado que llama: (2x)<br/>',NULL,197195,5);
INSERT INTO stanza VALUES('S2268','6','Ábreme, hermana mía,<br/>Amiga mía, paloma mía,<br/>Perfecta mía. (2x)<br/>',NULL,197196,6);
INSERT INTO stanza VALUES('S2268','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2268_leva-ntate-aquilo-n-y-ven',NULL,197197,7);
INSERT INTO stanza VALUES('S2269','1','Aunque el mundo_me prometa mas,<br/>Solo me llenaré del Señor.<br/>No vale la pena vivir,<br/>Por las cosas que no durarán.<br/>No importa cuan rico_o exitoso seré,<br/>¡Oh cuantos placeres se me_han de ofrecer!<br/>Nada se compara_a mi gran porvenir:<br/>Ser lleno del Señor hasta el fin.<br/>',NULL,197198,1);
INSERT INTO stanza VALUES('S2269','2','Y aunque muy pequeño aún soy;<br/>Y el futuro esta_en frente de mi,<br/>Su llamado en mi corazón;<br/>Me lleva_a seguir a mi Señor.<br/>Aunque_el camino tenga_alegría o dolor,<br/>Lo que más importa_es ganar del Señor.<br/>No importa que pase, nunca cambiaré.<br/>¡Hecho fui para_a Dios contener!<br/>(¡Si! Amén! Para_a Dios contener!)<br/>',NULL,197199,2);
INSERT INTO stanza VALUES('S2269','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2269_aunque-el-mundo-me',NULL,197200,3);
INSERT INTO stanza VALUES('S2270','1','Es tan fácil alabar en el bien,<br/>Pero hay veces cuando palabras no hay,<br/>Y oro:<br/>',NULL,197201,1);
INSERT INTO stanza VALUES('S2270','chorus','En Tu impartición<br/>Elijo quedarme,<br/>Lléname hoy<br/>Con Tu viviente hablar.<br/>Tu gracia me des,<br/>Tenme en Tu presencia,<br/>Que mi vida hoy te exprese a Ti.<br/>',NULL,197202,2);
INSERT INTO stanza VALUES('S2270','2','Él imparte todo lo que_es en mi.<br/>Al abrime, confío en Su dulce amor,<br/>Y oro:<br/>',NULL,197203,3);
INSERT INTO stanza VALUES('S2270','chorus','En Tu impartición<br/>Elijo quedarme,<br/>Lléname hoy<br/>Con Tu viviente hablar.<br/>Tu gracia me des,<br/>Tenme en Tu presencia,<br/>Que mi vida hoy te exprese a Ti.<br/>',NULL,197204,4);
INSERT INTO stanza VALUES('S2270','note','**[Puente:]**<br/>Nos llamó y predestinó<br/>Para Sus hijos ser.<br/>Cada día El se infunde,<br/>Nos hace Su expresión.<br/>Y oro:<br/>',NULL,197205,5);
INSERT INTO stanza VALUES('S2270','chorus','En Tu impartición<br/>Elijo quedarme,<br/>Lléname hoy<br/>Con Tu viviente hablar.<br/>Tu gracia me des,<br/>Tenme en Tu presencia,<br/>Que mi vida hoy te exprese a Ti.<br/>',NULL,197206,6);
INSERT INTO stanza VALUES('S2271','1','Amados, amemónos unos a otros,<br/>Porqué el amor es de Dios,<br/>Y todo aquel que ama,<br/>Es nacido de Dios<br/>Y conoce a Dios,<br/>El que no ama,<br/>No ha conocido a Dios<br/>Porqué Dios es amor!<br/>Dios es amor!<br/>Amados,<br/>Amémonos unos a otros!<br/>',NULL,197207,1);
INSERT INTO stanza VALUES('S2271','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/amados-amem-nos-unos-a-otros-1',NULL,197208,2);
INSERT INTO stanza VALUES('S2272','1','Amarás al Señor tu Dios<br/>Con todo tu corazón,<br/>Y con toda tu alma,<br/>Y con toda tu mente<br/>Y con todas tus fuerzas.<br/>',NULL,197209,1);
INSERT INTO stanza VALUES('S2272','2','Amarás<br/>Al Señor;<br/>Amarás<br/>Al Señor tu Dios.<br/>',NULL,197210,2);
INSERT INTO stanza VALUES('S2272','chorus','# Pueden ser cantadas en canon<br/>',NULL,197211,3);
INSERT INTO stanza VALUES('S2272','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/amaras_al_senor_tu_dios_marcos',NULL,197212,4);
INSERT INTO stanza VALUES('S2273','1','//Las encontré,<br/>Y las comí;<br/>Tus palabras, si,<br/>Fueron a mí<br/>Por gozo y alegría<br/>De mi corazón,<br/>Fueron por gozo<br/>De mi corazón. //<br/>',NULL,197213,1);
INSERT INTO stanza VALUES('S2273','2','En Tus leyes y caminos,<br/>Reflexionaré;<br/>Convertiré la Biblia en<br/>Oración, canción.<br/>La cantaré en la mañana,<br/>En el día la oraré,<br/>Hasta que sea Dios<br/>Mi fuerza y mi canción.<br/>',NULL,197214,2);
INSERT INTO stanza VALUES('S2274','1','¡Cantad alegres, cantad a Dios!<br/>Habitantes de toda la tierra,<br/>Servid a El con alegría,<br/>Venid a El con regocijo.<br/>',NULL,197215,1);
INSERT INTO stanza VALUES('S2274','2','Reconoced que Jehová es Dios,<br/>El nos hizo, y no nosotros mismos;<br/>Pueblo Suyo somos, y ovejas<br/>Y ovejas de Su prado.<br/>',NULL,197216,2);
INSERT INTO stanza VALUES('S2274','3','Entrad por Sus puertas,<br/>Por Sus puertas con acción de gracias,<br/>Por Sus atrios con alabanza,<br/>¡Alabadle, bendecid Su Nombre!<br/>',NULL,197217,3);
INSERT INTO stanza VALUES('S2274','4','Porqué Jehová, Jehová es bueno<br/>Para siempre es Su misericordia;<br/>Y Su verdad, Su verdad por todas,<br/>Por todas las generaciones!<br/>',NULL,197218,4);
INSERT INTO stanza VALUES('S2274','5','¡Aleluya! ¡Gloria! ¡Aleluya!<br/>¡Aleluya! ¡Gloria! ¡Aleluya!<br/>¡Aleluya! ¡Gloria! ¡Aleluya!<br/>¡Aleluya! ¡Gloria! ¡Aleluya!<br/>',NULL,197219,5);
INSERT INTO stanza VALUES('S2274','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/100-salmo-100-mp3-mp3',NULL,197220,6);
INSERT INTO stanza VALUES('S2275','1','Esta fe maravillosa<br/>Y éste super-excelente amor<br/>Proceden del Triuno Dios,<br/>Quien desea ardientemente<br/>Unirse a nos<br/>Para ser nuestro todo...<br/>',NULL,197221,1);
INSERT INTO stanza VALUES('S2275','chorus','El Triuno Dios<br/>Pasó los procesos,<br/>De encarnación,<br/>Crucifixión,<br/>Resurrección de los muertos,<br/>Y asención_a<br/>Los cielos en lo alto,<br/>Y fue últimamente<br/>Consumado como el<br/>Espíritu de vida.<br/>',NULL,197222,2);
INSERT INTO stanza VALUES('S2275','2','Este Espíritu de vida<br/>Que incluye Su divinidad,<br/>Su humanidad<br/>Y crucifixión,<br/>Resurrección<br/>Y asención,<br/>Y ahora es la realidad<br/>Del Cristo Todo-Inclusivo,<br/>Mora en nuestro regenerado espíritu,<br/>En nuestro regenerado espíritu.<br/>',NULL,197223,3);
INSERT INTO stanza VALUES('S2275','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2275_esta-fe-maravillosa-y',NULL,197224,4);
INSERT INTO stanza VALUES('S2276','1','Buenos dias Señor Jesús<br/>Gracias por hoy<br/>Gracias por mi espiritu,<br/>Gracias que puedo orar.<br/>Buenos dias Senor Jesús<br/>A Ti yo cantaré,<br/>Gracias por todo Señor.<br/>',NULL,197225,1);
INSERT INTO stanza VALUES('S2277','1','Con Tus manos álzame,<br/>Del pantano sálvame;<br/>Aquí no encuentro placidez,<br/>Mi alma inmundicia es<br/>Y Tu irá es su final.<br/>Por senderos me guiarás<br/>Donde espinos han de crecer;<br/>Allí me llevas a morar en Tu ser.<br/>',NULL,197226,1);
INSERT INTO stanza VALUES('S2277','chorus','Apártame con Tu grande amor,<br/>De este mundo de furor;<br/>Ponme en el monte a ver<br/>Lo que el mundo irá a ofrecer,<br/>Hasta de lo alto ver vanidad<br/>Y lo terrenal -Lo cedo yo-<br/>Y mis ojos vuelvo a Ti.<br/>',NULL,197227,2);
INSERT INTO stanza VALUES('S2277','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/con-tus-manos-a-lzame-a-higher',NULL,197228,3);
INSERT INTO stanza VALUES('S2278','1','Durante los veinte siglos,<br/>Miles de vidas preciosas,<br/>Tesoros del corazón,<br/>Puestos altos y<br/>Futuros brillantes han sido<br/>“Desperdiciados” en el Señor.<br/>Aquellos que lo aman así,<br/>Lo encuentran digno de ser<br/>Amado de esta manera<br/>Y digno de su ofrenda.<br/>//Lo que han derramado<br/>Sobre_Él no es<br/>Desperdicio,<br/>Sino un fragante testimonio<br/>De Su dulzura.//<br/>',NULL,197229,1);
INSERT INTO stanza VALUES('S2278','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/durante_los_veinte_siglos_mt26',NULL,197230,2);
INSERT INTO stanza VALUES('S2279','1','Dios busca jóvenes<br/>Que fiel su corazón guarden,<br/>De la corriente del mundo<br/>Hoy se resguarden;<br/>También dirán: "Desde hoy, Señor:<br/>Vamos a huir<br/>De la pasión juvenil;<br/>La justicia perseguir<br/>Con los que invoca...<br/>mos_al Señor<br/>De_un puro corazón."<br/>Alumbra nuestro interior<br/>Hasta que Tu_iglesia pueda ver.<br/>',NULL,197231,1);
INSERT INTO stanza VALUES('S2279','2','Dios busca jóvenes<br/>Que fiel su corazón guarden,<br/>De la corriente del mundo<br/>Hoy se resguarden;<br/>También dirán: "Desde hoy, Señor:<br/>Vamos a huir<br/>De la pasión juvenil;<br/>La justicia perseguir<br/>Para Tu iglesia...<br/>Edificar.<br/>¡Avanzar sin cesar!<br/>¡Hasta la meta llegar!<br/>Tu edificación vamos a amar."<br/>(Tu edificación vamos a amar.)<br/>',NULL,197232,2);
INSERT INTO stanza VALUES('S2279','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2279_dios-busca-jo-venes-que',NULL,197233,3);
INSERT INTO stanza VALUES('S2280','1','Examina, Oh Dios, mi corazón<br/>Prueba mi pensar,<br/>Y ve si hay<br/>Algún perverso camino en mi,<br/>Guíame Señor, guíame Señor,<br/>Guíame en el Camino eterno.<br/>',NULL,197234,1);
INSERT INTO stanza VALUES('S2280','2','Haz indagado, haz conocido<br/>Mis victorias, mis derrotas,<br/>Tú puedes ver<br/>Desde lejos mi pensar,<br/>Sabes todo en mi.<br/>',NULL,197235,2);
INSERT INTO stanza VALUES('S2280','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/examina-oh-dios-mi-corazo-n',NULL,197236,3);
INSERT INTO stanza VALUES('S2281','chorus','Juntos y creciendo en el Señor,<br/>Salvos por Su gracia en comunión;<br/>Siendo unánimes, creciendo<br/>Para ser un templo santo<br/>Juntos y creciendo en el Señor.<br/>',NULL,197237,1);
INSERT INTO stanza VALUES('S2281','1','Por Su vida nos resucitó,<br/>En lugares celestiales nos sentó,<br/>Una puerta al Padre nos abrió,<br/>Para edificar el Cuerpo en Su amor.<br/>',NULL,197238,2);
INSERT INTO stanza VALUES('S2281','2','Dios el Padre en Cristo ahora está,<br/>Mora en el Espíritu uno somos ya;<br/>Dios el Hijo, todo lo logró,<br/>Dios el Padre, Fuente y Originador.<br/>',NULL,197239,3);
INSERT INTO stanza VALUES('S2281','3','No más extranjeros sin hogar,<br/>Sino edificados para Dios morar;<br/>En familia, no más soledad;<br/>Somos uno en Cristo, la piedra angular.<br/>',NULL,197240,4);
INSERT INTO stanza VALUES('S2281','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/juntos-y-creciendo-en-el-senor',NULL,197241,5);
INSERT INTO stanza VALUES('S2282','1','Sueño de Dios,<br/>Esto es lo que Él quiere;<br/>Sueño de Dios,<br/>Y somos parte de_el.<br/>Sueño de Dios…<br/>Seamos uno con el.<br/>¡Sueño de Dios…<br/>Real en ti y en mí!<br/>Dios tú y yo… mutua habitación<br/>Dios y hombre, y hombre en Dios:<br/>Una entidad<br/>¡Este sueño…<br/>Mi visión y vida es!<br/>¡Sueño de Dios, real en ti y en mi!<br/>',NULL,197242,1);
INSERT INTO stanza VALUES('S2282','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/suen-o_de_dios-god-has-a-dream',NULL,197243,2);
INSERT INTO stanza VALUES('S2283','1','Dios quiere que Le amen<br/>No solo que Le sirvan;<br/>Quiere una novia hermosa,<br/>Que Lo_ame_a_El...<br/>Dios quiere que lo igualen,<br/>No solo que Lo imiten;<br/>El quiere Su pareja<br/>Igual a El.<br/>',NULL,197244,1);
INSERT INTO stanza VALUES('S2283','chorus','Por eso El vino, aquí, a nos,<br/>A enamorarnos, ganarnos<br/>Fuera de todo, - Y así<br/>Ser sólo para El.<br/>Ahora Su novia somos hoy,<br/>Comprometidos ya con Él,<br/>Un yugo que nos une<br/>Por Su amor.<br/>',NULL,197245,2);
INSERT INTO stanza VALUES('S2283','2','Dios quiere que Lo amen,<br/>No sólo que Le teman.<br/>El quiere una novia<br/>Su esposa.<br/>Quiere que Le conozcan,<br/>No que sepan de lejos;<br/>Que a los ojos Lo miren<br/>Con amor.<br/>',NULL,197246,3);
INSERT INTO stanza VALUES('S2283','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/dios-quiere-que-lo-amen-god',NULL,197247,4);
INSERT INTO stanza VALUES('S2284','1','Buscad primero el Reino de Dios,<br/>El Reino y Su Justicia,<br/>Y lo demás añadido será,<br/>Alelu-! Aleluya!<br/>',NULL,197248,1);
INSERT INTO stanza VALUES('S2284','2','Pedid, pedid y se os dará,<br/>Buscad y hallarés ,<br/>Llamad, llamad y se os abrira,<br/>Alelu-! Aleluya!<br/>',NULL,197249,2);
INSERT INTO stanza VALUES('S2284','3','No solo de pan, el hombre vivirá,<br/>Sinó de toda Palabra,<br/>Que sale de la boca de Dios,<br/>Alelu-! Aleluya!<br/>',NULL,197250,3);
INSERT INTO stanza VALUES('S2284','4','El Espíritu es el que da vida,<br/>La carne nada aprovecha,<br/>Las Palabras que Yo os He hablado,<br/>Son Espíritu y Vida.<br/>',NULL,197251,4);
INSERT INTO stanza VALUES('S2284','note','**[Puente:]**<br/>Aleluya! Aleluya!<br/>Aleluya! Aleluya!<br/>Son Espíritu y Vida!<br/>',NULL,197252,5);
INSERT INTO stanza VALUES('S2284','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/buscad-primero-el-reino-de',NULL,197253,6);
INSERT INTO stanza VALUES('S2285','1','Levántate,<br/>Amor mío, hermosa mía,<br/>Y ven porque<br/>Ya ha pasado el invierno;<br/>La lluvia ha cesado y se fue.<br/>Han aparecido las flores,<br/>Vino_el tiempo de la canción;<br/>En nuestra tierra se ha oído la voz<br/>De la tórtola.<br/>',NULL,197254,1);
INSERT INTO stanza VALUES('S2285','2','Mí amado es mío, y yo Suya soy;<br/>Él_apacienta<br/>Su rebaño entre los lirios.<br/>Hasta que despunte el día<br/>Y huyan las sombras<br/>Vuelve, amado mío,<br/>Vuelve amado mío.<br/>',NULL,197255,2);
INSERT INTO stanza VALUES('S2285','3','Levántate,<br/>Amor mío, hermosa mía,<br/>Y ven porque<br/>Ya ha pasado el invierno;<br/>La lluvia ha cesado y se fue...<br/>',NULL,197256,3);
INSERT INTO stanza VALUES('S2286','1','¿Estás dispuesto a cambiar la era?<br/>¿Has confiado en escucharlo a El?<br/>Hay que tomar, El Espíritu de vida<br/>¡Dejar el mundo_atrás!<br/>Marchar con denuedo.<br/>',NULL,197257,1);
INSERT INTO stanza VALUES('S2286','chorus','Hay que proclamar este poder Divino<br/>Sin avergonzarse de nuestro hermoso Cristo.<br/>Hay que proclamar el Espíritu Divino,<br/>¡Y ministrar, funcionar, propagar y difundir!<br/>',NULL,197258,2);
INSERT INTO stanza VALUES('S2286','2','Tendrás una nueva consagración?<br/>Y_levantar un altar, prepararte para El;<br/>Depende de nos Su expresión corporal<br/>Marchar con denuedo,<br/>¡Tomad a Cristo como nuestro vivir!<br/>',NULL,197259,3);
INSERT INTO stanza VALUES('S2286','chorus','Hay que proclamar este poder Divino<br/>Sin avergonzarse de nuestro hermoso Cristo.<br/>Hay que proclamar el Espíritu Divino,<br/>¡Y ministrar, funcionar, propagar y difundir!<br/>',NULL,197260,4);
INSERT INTO stanza VALUES('S2286','3','Estás abierto a tal nueva era<br/>¿Estás listo para responderle a El?<br/>Para cambiar la_era,<br/>El necesita muchos jóvenes<br/>Que marchen con denuedo<br/>¡Por el regreso del Señor!<br/>',NULL,197261,5);
INSERT INTO stanza VALUES('S2286','chorus','Hay que proclamar este poder Divino<br/>Sin avergonzarse de nuestro hermoso Cristo.<br/>Hay que proclamar el Espíritu Divino,<br/>¡Y ministrar, funcionar, propagar y difundir!<br/>',NULL,197262,6);
INSERT INTO stanza VALUES('S2286','chorus','¡Si! Declararemos este poder divino,<br/>Sin avergonzarnos_de este hermoso Cristo.<br/>¡Si! Declararemos este Espíritu divino.<br/>¡Y ministrar, funcionar, propagar y difundir!<br/>',NULL,197263,7);
INSERT INTO stanza VALUES('S2286','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/est-s-dispuesto-a-cambiar-la-1',NULL,197264,8);
INSERT INTO stanza VALUES('S2287','1','El gozo de mi Dios,<br/>Mi fortaleza es.<br/>Ungiéndome hoy está,<br/>De gozo llena mi ser.<br/>Olvidando lo demás,<br/>Al servir y laborar,<br/>Solo debo_abrir mi ser,<br/>Con gozo le cantaré.<br/>',NULL,197265,1);
INSERT INTO stanza VALUES('S2287','chorus','¡Mi gozo_es Dios!<br/>Mi fuerza es Él.<br/>Cada día<br/>Le alabaré.<br/>Mi Dios de amor,<br/>Indecible,<br/>Cuan grande_es Él,<br/>Lleno de gloria,<br/>Él mi gozo llega a ser.<br/>',NULL,197266,2);
INSERT INTO stanza VALUES('S2287','2','En Cristo la vid morar,<br/>Su vivo suplir tomar.<br/>Su gozo mi gozo es,<br/>Al Su nombre invocar.<br/>El pleno gozo en mí<br/>Desplaza mi ansiedad,<br/>Me da completa paz<br/>Pues Cristo es mi realidad.<br/>',NULL,197267,3);
INSERT INTO stanza VALUES('S2287','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/el_gozo_de_mi_dios-my-god-is',NULL,197268,4);
INSERT INTO stanza VALUES('S2288','1','Mas nuestra ciudadanía está en los cielos,<br/>De donde esperamos al Señor Jesús,<br/>Él transformará en gloria Suya mi cuerpo,<br/>Este cuerpo de muerte y esclavitud.<br/>',NULL,197269,1);
INSERT INTO stanza VALUES('S2288','chorus','//Con el poder,<br/>Que Él hace sujetar todas las cosas.//<br/>',NULL,197270,2);
INSERT INTO stanza VALUES('S2288','2','Así que, hermanos míos deseados,<br/>Gozo y corona mía, estad así<br/>En el Señor Jesús siempre, amados:<br/>Os ruego que sean de un mismo sentir.<br/>',NULL,197271,3);
INSERT INTO stanza VALUES('S2288','chorus','//Con el poder,<br/>Que Él hace sujetar todas las cosas.//<br/>',NULL,197272,4);
INSERT INTO stanza VALUES('S2288','note','**[Puente 1:]**<br/>Todo ojo le verá,<br/>Confesarán que es el Señor.<br/>',NULL,197273,5);
INSERT INTO stanza VALUES('S2288','chorus','//Con el poder,<br/>Que Él hace sujetar todas las cosas.//<br/>',NULL,197274,6);
INSERT INTO stanza VALUES('S2288','note','**[Puente 2:]**<br/>La iglesia tomando está<br/>Del Espíritu un clamor.<br/>',NULL,197275,7);
INSERT INTO stanza VALUES('S2288','chorus','//Digamos ven,<br/>Para que celebremos ésta boda.//<br/>',NULL,197276,8);
INSERT INTO stanza VALUES('S2288','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/mas-nuestra-ciudadania-esta-en',NULL,197277,9);
INSERT INTO stanza VALUES('S2289','1','Nuestro Alfarero, Dios,<br/>Soberanamente nos creó<br/>Como vasos, - Sus vasos,<br/>Para contenerlo - A Él_mismo<br/>De_acuerdo a Su predestinación;<br/>Su propósito_al crear_al_hombre<br/>Fue_hacerlo Su vaso.<br/>Vasos para_contener y ser llenos<br/>Con Cristo como vida<br/>Para la_edificación<br/>Del Cuerpo_de_Cristo;<br/>Vaso corporativo<br/>Para Su_expresión.<br/>',NULL,197278,1);
INSERT INTO stanza VALUES('S2289','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/nuestro-alfarero-dios',NULL,197279,2);
INSERT INTO stanza VALUES('S2290','1','Un día pasó el Señor<br/>A ver la sedienta mujer;<br/>No estaba feliz hasta que_Él<br/>Le diera_a beber agua viva y real.<br/>',NULL,197280,1);
INSERT INTO stanza VALUES('S2290','chorus','Oh, ¡vengan a ver! (¡A ver!)<br/>Al Hombre Jesús,<br/>Quien me dijo cosas<br/>Que nunca pensé.<br/>¿No es este Jesús?  (ooh, ¡sí!)<br/>¿No es este Jesús?<br/>¡Él me llena siempre<br/>Y por siempre! ¡Amén! (amén, amén, amén)<br/>',NULL,197281,2);
INSERT INTO stanza VALUES('S2290','2','Yo nunca pensé que Su hablar<br/>Erradicaría mi sed;<br/>Él me dio del agua a beber,<br/>Y a todos los que estén sedientos también.<br/>',NULL,197282,3);
INSERT INTO stanza VALUES('S2290','3','Ahora la viva_agua en mi<br/>No puedo dejarla así;<br/>Sino disfrutar y fluir,<br/>Hablando de la vida de este Jesús.<br/>',NULL,197283,4);
INSERT INTO stanza VALUES('S2290','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/oh-vengan-a-ver-al-hombre-1',NULL,197284,5);
INSERT INTO stanza VALUES('S2291','1','¿Qué llevó_a Maria a todo_entregar,<br/>Y a Pedro a seguirte, sin dudar?<br/>Tantas vidas por Ti se han ido a perder,<br/>Señor, ¿Por qué se_aferran a Ti sin entender?<br/>',NULL,197285,1);
INSERT INTO stanza VALUES('S2291','chorus','La vision de Cristo y la_Iglesia ver;<br/>Lo demás: perdida llega_a ser;<br/>Por ganar Cristo, el precio pagar,<br/>Quemar los puentes,<br/>Queda el mundo atrás.<br/>En la meta de Dios todo centrar,<br/>Y una vida sin culpas llevar.<br/>',NULL,197286,2);
INSERT INTO stanza VALUES('S2291','2','Otros dudan por ésta opción,<br/>Más servirte_es la más alta profesión.<br/>Buenos ya no somos para_el mundo con su gloria;<br/>Para Cristo y la Iglesia será nuestra historia.<br/>',NULL,197287,3);
INSERT INTO stanza VALUES('S2291','chorus','La vision de Cristo y la_Iglesia ver;<br/>Lo demás: perdida llega_a ser;<br/>Por ganar Cristo, el precio pagar,<br/>Quemar los puentes,<br/>Queda el mundo atrás.<br/>En la meta de Dios todo centrar,<br/>Y una vida sin...<br/>',NULL,197288,4);
INSERT INTO stanza VALUES('S2291','chorus','Hemos visto esta clara visión,<br/>Y que todo lo demás es perdición.<br/>Pagaremos_el precio, y también<br/>Quemaremos puentes<br/>Para siempre, amén!<br/>En la meta de Dios todo centrar,<br/>Y una vida sin....<br/>En la meta de Dios todo centrar,<br/>Y una vida sin culpas llevar.<br/>',NULL,197289,5);
INSERT INTO stanza VALUES('S2291','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2219_que-llevo-a-mari-a-a-todo',NULL,197290,6);
INSERT INTO stanza VALUES('S2292','1','Que yo ame sin ser apreciado,<br/>Que yo sirva sin ser recompensado;<br/>Que yo obre sin ser recordado,<br/>Que yo sufra sin ser admirado.<br/>',NULL,197291,1);
INSERT INTO stanza VALUES('S2292','2','No es beber, sino derramarse,<br/>No es guardarse, sino quebrantarse;<br/>Una vida que sufra bendiciendo,<br/>Una vida que ame sosteniendo.<br/>',NULL,197292,2);
INSERT INTO stanza VALUES('S2292','3','Que no acepte piedad ni compasión,<br/>Que no acepte elogios ni consuelos;<br/>Mas la soledad y aun el olvido,<br/>Que desprecie el aplauso ofrecido.<br/>',NULL,197293,3);
INSERT INTO stanza VALUES('S2292','4','Sangre y lágrimas<br/>La corona ha de costar,<br/>Pérdida total<br/>Es el precio a pagar.<br/>Peregrina vida el Señor llevó,<br/>Cuando por esta tierra Él pasó.<br/>Con gusto sufrió, injuria y dolor,<br/>Para darnos reposo y comprensión.<br/>',NULL,197294,4);
INSERT INTO stanza VALUES('S2292','5','No puedo ver cuánto más debo avanzar,<br/>Oh, se muy bien que no puedo regresar.<br/>Que yo siga el modelo perfecto y veraz,<br/>Cuando cargue ingratitudes sin quejar.<br/>',NULL,197295,5);
INSERT INTO stanza VALUES('S2292','6','En el tiempo cruel Te ruego Señor<br/>Que mis lágrimas sequen Tu bondad.<br/>Muéstrame Señor que eres galardón<br/>Para ser bendición a los demás.<br/>',NULL,197296,6);
INSERT INTO stanza VALUES('S2292','YouTube Link','https://www.youtube.com/watch?v=FZPPiyPhziI&list=RDFZPPiyPhziI&start_radio=1',NULL,197297,7);
INSERT INTO stanza VALUES('S2293','1','Tú el Soberano eres<br/>El más sabio Creador<br/>Como un vaso me moldeaste,<br/>¡Alfarero eres, Señor!<br/>Que yo fuera un vaso de honra<br/>Para dar a conocer<br/>Las riquezas de Tu gloria,<br/>Soberano hecho fue.<br/>',NULL,197298,1);
INSERT INTO stanza VALUES('S2293','2','No podría exigirte<br/>Que me dieras Tu favor,<br/>Mas por Tu misericordia<br/>Me elegiste Tú, Señor.<br/>Nada digno en mí había<br/>Para que me amaras Tú,<br/>Mas así lo decidiste,<br/>Por Tu gracia y virtud.<br/>',NULL,197299,2);
INSERT INTO stanza VALUES('S2293','3','Fue por Tu soberanía<br/>Que misericordia hallé;<br/>Me has llamado a acercarme<br/>A Tu trono sin temer.<br/>Para hoy poder tocarte<br/>La clave_es mi espíritu;<br/>Por tal gracia te alabo,<br/>Yo no soy, mas eres Tú.<br/>',NULL,197300,3);
INSERT INTO stanza VALUES('S2293','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/tu-el_soberano_eres',NULL,197301,4);
INSERT INTO stanza VALUES('S2294','1','¡Oh, qué gozo el no tener,<br/>Ni querer, ni más ver,<br/>Sino a Cristo en gloria_y fiel,<br/>Y en Su paz permanecer!<br/>¡Oh, qué gozo el nada ser<br/>Ni_obtener, ni tener<br/>Sino a Cristo, en gloria_y fiel<br/>Sólo arder por Su_interés.<br/>',NULL,197302,1);
INSERT INTO stanza VALUES('S2294','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2294_oh-que-gozo-el-no-tener',NULL,197303,2);
INSERT INTO stanza VALUES('S2295','1','Te exaltare, mi Dios, mi Rey<br/>Y bendeciré Tu nombre<br/>Eternamente y para siempre<br/>Cada día Te bendeciré,<br/>',NULL,197304,1);
INSERT INTO stanza VALUES('S2295','chorus','Y alabare Tu nombre.<br/>​Eternamente y para siempre<br/>​Grande es Jehová<br/>​Y digno de suprema alabanza<br/>​Y Su grandeza es inescrutable<br/>​Cada día Te bendeciré.<br/>',NULL,197305,2);
INSERT INTO stanza VALUES('S2295','2','Generación a generación<br/>Celebrarán Tus obras<br/>Y anunciarán Tus poderosos hechos.<br/>Cada día Te bendeciré.<br/>',NULL,197306,3);
INSERT INTO stanza VALUES('S2296','1','A la iglesia de<br/>Dios que_está en Corinto,<br/>A los santificados en Cristo Jesús!<br/>Los santos llamados!<br/>Con todos aquellos<br/>Que invocan el Nombre<br/>Del Señor,<br/>En cualquier lugar...<br/>',NULL,197307,1);
INSERT INTO stanza VALUES('S2296','2','A la iglesia de<br/>Dios que_está en *Corinto,<br/>A los santificados en Cristo Jesús!<br/>Los santos llamados!<br/>Con todos aquellos<br/>Que invocan al Señor,<br/>Señor de_ellos y nuestro.<br/>',NULL,197308,2);
INSERT INTO stanza VALUES('S2296','chorus','Con todos aquellos<br/>Que invocan al Señor en cualquier lugar.<br/>Con todos aquellos<br/>Que invocan el Nombre...del Señor<br/>En cualquier lugar.<br/>',NULL,197309,3);
INSERT INTO stanza VALUES('S2296','chorus','*Corinto puede ser intercambiado<br/>Con el nombre de una localidad.<br/>',NULL,197310,4);
INSERT INTO stanza VALUES('S2296','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2296_a-la-iglesia-de-dios-que',NULL,197311,5);
INSERT INTO stanza VALUES('S2297','1','Es solo un dia ordinario mas,<br/>Pero no lo quiero desperdiciar,<br/>Pués algo espectacular,<br/>Me vuelvo hoy a mi Señor,<br/>Para ganar a Dios!<br/>',NULL,197312,1);
INSERT INTO stanza VALUES('S2297','chorus','Días comunes y ordinarios,<br/>Está es la manera para llenarme de El!<br/>',NULL,197313,2);
INSERT INTO stanza VALUES('S2297','2','Es solo un dia ordinario mas,<br/>Me vuelvo a El, para mirar Su faz,<br/>En pequeñas cosas<br/>Puede Dios impartir Su Vida hoy,<br/>Para llenarme de El!<br/>',NULL,197314,3);
INSERT INTO stanza VALUES('S2297','chorus','Días comunes y ordinarios,<br/>Está es la manera para llenarme de El!<br/>',NULL,197315,4);
INSERT INTO stanza VALUES('S2297','3','Un dia perfecto no debes esperar,<br/>Puedes orar antes de fracasar,<br/>cada instante puede contar cuando Cristo,<br/>Tu vida es, para ganar a Dios.<br/>',NULL,197316,5);
INSERT INTO stanza VALUES('S2297','chorus','Días comunes y ordinarios,<br/>Está es la manera para llenarme de El!<br/>',NULL,197317,6);
INSERT INTO stanza VALUES('S2297','note','**[Puente:]**<br/>Hoy disfruto al Señor<br/>Desde el dia, Hasta anochecer,<br/>Cuando es tarde, en la noche,<br/>Apago la luz puedo orar,<br/>Cada cosa en mi vida,<br/>Es una oportunidad,<br/>Para ganar a Dios!<br/>',NULL,197318,7);
INSERT INTO stanza VALUES('S2297','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/es-solo-un-di-a-ordinario-ma-s',NULL,197319,8);
INSERT INTO stanza VALUES('S2298','1','Un hombre de Dios<br/>Cuando crezca quiero ser,<br/>Uno que lleno de vida esté;<br/>Y ser_ese alguien que<br/>Ama mucho al Señor,<br/>Escojo ser un hombre de Dios.<br/>',NULL,197320,1);
INSERT INTO stanza VALUES('S2298','chorus','No hay nada más que yo prefiera ser.<br/>No hay nada en el mundo que desee ser.<br/>',NULL,197321,2);
INSERT INTO stanza VALUES('S2298','2','Un hombre de Dios<br/>Cuando crezca quiero ser,<br/>Uno que lleno de vida esté;<br/>Y ser_ese alguien que<br/>Ama mucho al Señor,<br/>Escojo ser un hombre de Dios.<br/>',NULL,197322,3);
INSERT INTO stanza VALUES('S2298','note','**[Puente:]**<br/>Aunque aún no lo soy,<br/>Esa es mi elección;<br/>Un hombre de Dios quiero ser,<br/>Es ésto exactamente lo que quiero ser.<br/>',NULL,197323,4);
INSERT INTO stanza VALUES('S2298','3','Un hombre de Dios<br/>Cuando crezca quiero ser,<br/>Uno que lleno de vida esté;<br/>Y ser_ese alguien que<br/>Ama mucho al Señor,<br/>Escojo ser un hombre de Dios.<br/>',NULL,197324,5);
INSERT INTO stanza VALUES('S2298','chorus','No hay nada más que yo prefiera ser.<br/>No hay nada en el mundo que desee ser.<br/>',NULL,197325,6);
INSERT INTO stanza VALUES('S2298','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/un-hombre-de-dios-cuando',NULL,197326,7);
INSERT INTO stanza VALUES('S2299','chorus','// Vuelve, vuelve a nacer, ¡Aleluya!<br/>Qué largo camino habrás de recorrer, ¡Aleluya!<br/>Si tú vuelves a nacer<br/>Al viejo yo podrás vencer<br/>Entonces la luz de Dios, podrás ver//<br/>',NULL,197327,1);
INSERT INTO stanza VALUES('S2299','1','Un hombre vino a mí, // y dijo así //<br/>Quisiera yo sa-ber, // a donde ir //<br/>Me pasa algo que no puede ser<br/>Siento el amor en mí crecer<br/>Y es porque Jesucristo mora en mí.<br/>',NULL,197328,2);
INSERT INTO stanza VALUES('S2299','2','Estamos reunidos aquí, si aquí<br/>Porque todos creemos<br/>Si hay alguno, que no cree aquí, si aquí,<br/>Le rogamos que se entregue:<br/>Acéptalo con todo el corazón<br/>Y usa tus dos manos<br/>Con una alcanza a Jesús<br/>Y con la otra, trae a un hermano.<br/>',NULL,197329,3);
INSERT INTO stanza VALUES('S2299','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/vuelve-a-nacer-iglesia-en',NULL,197330,4);
INSERT INTO stanza VALUES('S2300','1','¿Dónde_está, pues,<br/>La casa que me habréis de_edificar?<br/>¿Y_ese lugar de Mi reposo,<br/>Dónde_está_ese lugar?<br/>Mi trono_está en los cielos,<br/>Y_en la tierra Mis pies.<br/>¿Dónde_está, pues,<br/>Ese lugar que habréis de_edificar?<br/>',NULL,197331,1);
INSERT INTO stanza VALUES('S2300','2','Todas las cosas hice Yo,<br/>Todo lo que llegó_a existir,<br/>Jehová declara.<br/>Pero miraré a_aquel hombre<br/>Cuyo_espíritu es<br/>Contrito y pobre,<br/>Y que tiembla ante Mi.<br/>',NULL,197332,2);
INSERT INTO stanza VALUES('S2300','3','¿Dónde_está, pues,<br/>La casa que me habréis de_edificar?<br/>¿Y_ese lugar de Mi reposo,<br/>Dónde_está_ese lugar?<br/>Mi trono_está en los cielos,<br/>Y_en la tierra Mis pies.<br/>¿Dónde_está, pues,<br/>Ese lugar que habréis de_edificar?<br/>',NULL,197333,3);
INSERT INTO stanza VALUES('S2300','SoundCloud Link','https://soundcloud.com/user-290074669/donde-esta-pues-jh',NULL,197334,4);
INSERT INTO stanza VALUES('S2301','1','Todo inclusivo nuestro Cristo es;<br/>Asignada, nuestra porción en la luz.<br/>En el reino del Hijo de Dios, el Hijo de Su amor<br/>Aquí El gobierna en Su luz y amor.<br/>',NULL,197335,1);
INSERT INTO stanza VALUES('S2301','2','Tus ojos levanta y mira lo qué hay:<br/>La tierra todo inclusiva Cristo es.<br/>Caminamos, disfrutando, bendecida tierra es<br/>Siendo salvos, comiendo leche y miel.<br/>',NULL,197336,2);
INSERT INTO stanza VALUES('S2301','3','Mira el trigo, Cristo restringido es!<br/>En Su encarnación, El restringido fue;<br/>Limitado en lo exterior, pero en_el poder de Dios<br/>Cómo la cebada vida liberó.<br/>',NULL,197337,3);
INSERT INTO stanza VALUES('S2301','4','Mira las vides, sacrificio es!<br/>Este vino alegra al hombre y a Dios;<br/>Al tomar el vino nuevo, energizado así seré<br/>Para ser viviente sacrificio a Dios.<br/>',NULL,197338,4);
INSERT INTO stanza VALUES('S2301','5','Mira las higueras, Cristo dulce es!<br/>Avanzando en disfrute y en la fe.<br/>Para otros suplir siendo un canal de bendición<br/>Y gozosos en Su rica provisión.<br/>',NULL,197339,5);
INSERT INTO stanza VALUES('S2301','6','Mira las granadas: vida en plenitud;<br/>La belleza y la abundancia en Su virtud.<br/>El espíritu como el olivo honra al hombre y Dios<br/>Nos injerta, y glorifica a Jesús.<br/>',NULL,197340,6);
INSERT INTO stanza VALUES('S2301','7','Es nuestra porción, y disponible está<br/>Para caminar y experimentar;<br/>Aprehendiendo lo insondable que está buena tierra es,<br/>Disfrutando con los santos siempre de Él!<br/>',NULL,197341,7);
INSERT INTO stanza VALUES('S2302','1','Jehova es mi luz y mi Salvación,<br/>A quién he de temer?<br/>Es la Fortaleza de mi vida,<br/>Ante quien he de temblar?<br/>',NULL,197342,1);
INSERT INTO stanza VALUES('S2302','2','Una cosa he pedido a Jehová;<br/>Esta buscaré:<br/>Morar en la casa de Jehová<br/>Todos los días de mi vida,<br/>Para contemplar<br/>La hermosura de Jehová<br/>Y para en Su templo inquirir.<br/>',NULL,197343,2);
INSERT INTO stanza VALUES('S2302','3','Oye oh Jehová<br/>Cuando clamo con mi voz,<br/>Concédeme Tu favor y respóndeme!<br/>Cuando dices Tú:<br/>Mi rostro buscad!<br/>Dice mi corazón,<br/>Tu rostro Jehová buscaré!<br/>',NULL,197344,3);
INSERT INTO stanza VALUES('S2302','4','Espera en Jehová y se fuerte;<br/>Aliéntese tu corazón.<br/>Sí, espera en Jehová!<br/>Sí, espera en Jehová!<br/>',NULL,197345,4);
INSERT INTO stanza VALUES('S2303','1','Nadie tenga nunca en poco tu fresca juventud,<br/>Mas se ejemplo a los creyentes en conducta y amor,<br/>En palabra y pureza, espíritu y fe.<br/>No descuides nunca el don que hay en ti.<br/>',NULL,197346,1);
INSERT INTO stanza VALUES('S2303','2','Siempre busca estar nutrido con las palabras de fe,<br/>Y que a la buena enseñanza, la sigas por doquier.<br/>Si esto haces y esto enseñas, muy útil tú serás,<br/>Buen ministro de Jesús, tú serás.<br/>',NULL,197347,2);
INSERT INTO stanza VALUES('S2303','3','Toda fábula profana tú puedas desechar<br/>Para diligentemente ejercitarte en la piedad,<br/>Para poco aprovecha el ejercicio corporal,<br/>Para todo aprovecha la piedad.<br/>',NULL,197348,3);
INSERT INTO stanza VALUES('S2303','4','En la pública lectura, también en la exhortación,<br/>Y en la enseñanza sana, te debes ocupar.<br/>Hoy practica estas cosas, así te salvarás<br/>A ti mismo y a los que oigan tú hablar.<br/>',NULL,197349,4);
INSERT INTO stanza VALUES('S2303','5','De pasiones juveniles también debes huir,<br/>Para que no haya barreras que te impidan seguir<br/>La justicia, el amor, la fe, también la paz<br/>Con aquellos que invocan al Señor.<br/>',NULL,197350,5);
INSERT INTO stanza VALUES('S2303','6','Nadie tenga nunca en poco tu fresca juventud<br/>Más se ejemplo a los creyentes en conducta y amor,<br/>En palabra y pureza, espíritu y fe.<br/>No descuides nunca el don que hay en ti.<br/>',NULL,197351,6);
INSERT INTO stanza VALUES('S2303','SoundCloud Link','https://soundcloud.com/user-952134958/nadie-tenga-nunca-en-poco-oficial',NULL,197352,7);
INSERT INTO stanza VALUES('S2304','chorus','Hoy, mi Señor, recibo el amor<br/>De la verdad para ser salvo<br/>De la confusión, mentira y error;<br/>Me aferro a Ti, Señor.<br/>',NULL,197353,1);
INSERT INTO stanza VALUES('S2304','1','Tinieblas, luz, distintos son;<br/>Amargo y dulce no es igual.<br/>No participaré del mal,<br/>Escojo la verdad amar.<br/>',NULL,197354,2);
INSERT INTO stanza VALUES('S2304','2','Mi Dios existe y es real,<br/>El diablo no me engañara.<br/>La oscuridad rechazaré,<br/>Su luz, Su presencia, toqué.<br/>',NULL,197355,3);
INSERT INTO stanza VALUES('S2304','3','El Alfarero me hizo bien,<br/>Su arreglo no despreciaré;<br/>Su Espíritu en el mío esta<br/>Me hizo así, trae vida y paz.<br/>',NULL,197356,4);
INSERT INTO stanza VALUES('S2304','4','Señor eres la realidad,<br/>Ocupa todo mi pensar;<br/>En Tu palabra hay vida y luz<br/>Mi mente la renuevas Tú.<br/>',NULL,197357,5);
INSERT INTO stanza VALUES('S2304','5','Señor en Tu iglesia hoy,<br/>Los cielos abiertos están;<br/>Constituidos para ser<br/>Columna fiel de la verdad.<br/>',NULL,197358,6);
INSERT INTO stanza VALUES('S2304','SoundCloud Link','https://soundcloud.com/rodrigo-hurtado-onofre/hoy-mi-senor-recibo-el-amor',NULL,197359,7);
INSERT INTO stanza VALUES('S2305','1','Favor halló Noé ante los ojos de Jehová.<br/>Favor halló Noé ante los ojos de Jehová.<br/>Creo yo en la Biblia con fervor.<br/>Favor halló Noé antes los ojos del Señor.<br/>',NULL,197360,1);
INSERT INTO stanza VALUES('S2305','2','Salvo soy,<br/>Lo soy por fe.<br/>Por obras? ¡No!<br/>Sino por fe.<br/>',NULL,197361,2);
INSERT INTO stanza VALUES('S2305','3','Pues Dios es el que realiza,<br/>Realiza en nosotros,<br/>El querer, así como el hacer,<br/>Por Su beneplácito. (2x)<br/>',NULL,197362,3);
INSERT INTO stanza VALUES('S2305','4','Lleva (lleva) a cabo tu salvación<br/>Con temor y temblor.<br/>Lleva (lleva) a cabo tu salvación<br/>Con temor y temblor.<br/>',NULL,197363,4);
INSERT INTO stanza VALUES('S2305','chorus','2, 3 y 4 se pueden cantar en canon.<br/>',NULL,197364,5);
INSERT INTO stanza VALUES('S2305','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2305_favor-hallo-noe-ante-los',NULL,197365,6);
INSERT INTO stanza VALUES('S2306','1','Maná del cielo bajó<br/>Milagroso misterio de Dios.<br/>Jesús dijo "¡Yo soy el pan!"<br/>Que vida al mundo da.<br/>',NULL,197366,1);
INSERT INTO stanza VALUES('S2306','chorus','Come<br/>De este pan vivo;<br/>Gana<br/>Su rico suplir.<br/>Alaba;<br/>Él sí satisface;<br/>Jesús!<br/>El Cristo todo‿inclusivo es.<br/>',NULL,197367,2);
INSERT INTO stanza VALUES('S2306','2','Cristo roca espiritual<br/>Herida y hendida por Dios;<br/>Agua de vida fluyó<br/>Apagando toda sed.<br/>',NULL,197368,3);
INSERT INTO stanza VALUES('S2306','chorus','Bebe<br/>De la fuente de vida;<br/>Prueba<br/>El dulce manantial.<br/>Alaba;<br/>Nunca más sediento.<br/>Jesús!<br/>El Cristo todo inclusivo es.<br/>',NULL,197369,4);
INSERT INTO stanza VALUES('S2306','3','Él fue clavado en la cruz<br/>Sangre y agua fluyó;<br/>Plena redención pagó -<br/>Recibe y disfrutala.<br/>',NULL,197370,5);
INSERT INTO stanza VALUES('S2306','chorus','Toma<br/>Al rey y Salvador;<br/>Dale<br/>El primer lugar.<br/>Alaba;<br/>Sacrificio eterno-<br/>Jesús-<br/>El Cristo todo inclusivo es.<br/>',NULL,197371,6);
INSERT INTO stanza VALUES('S2306','4','Hoy el espíritu es Él,<br/>Puede habitar en mí ser.<br/>Para Sus riquezas ganar<br/>El camino es invocar.<br/>',NULL,197372,7);
INSERT INTO stanza VALUES('S2306','chorus','Inhala<br/>El Pneuma es Él;<br/>Toca-<br/>Cuán cerca está<br/>Alaba.<br/>Viviente Espíritu;<br/>Jesús-<br/>El Cristo todo inclusivo es.<br/>',NULL,197373,8);
INSERT INTO stanza VALUES('S2307','1','Pecador, más salvo soy;<br/>Mucho falta por crecer;<br/>Parece que nada_en mi cambió:<br/>¿Paciencia? No puedo esperar;<br/>En vez de amor, tengo rencor;<br/>Señor, no quiero quedarme igual.<br/>Pensé que debía yo mismo “resolver”,<br/>Mas me muestras la senda_a tomar:<br/>',NULL,197374,1);
INSERT INTO stanza VALUES('S2307','chorus','No debo creer en mis "conflictos";<br/>Solo crecer en el Señor;<br/>Disfrutándolo día a día,<br/>Estando con los santos,<br/>Absorbiéndo yo las riquezas en la Vid.<br/>No tengo que luchar ni batallar;<br/>[mas] En vida crecer.<br/>',NULL,197375,2);
INSERT INTO stanza VALUES('S2307','2','Tu palabra, al despertar,<br/>Yo sin prisa comeré;<br/>Tu nombre, sin cesar, invocaré.<br/>(Oh Jesús)<br/>Con los santos siempre estar,<br/>Hallar Tu gracia sin igual;<br/>Cada día Te_alabaré.<br/>Dejé atrás la vieja norma y tradición;<br/>Descubrí un secreto para andar:<br/>',NULL,197376,3);
INSERT INTO stanza VALUES('S2308','1','Un susurro hay de gloria: ¡el Señor regresará!<br/>¡Al confiar en Su palabra siento gozo a desbordar!<br/>Y en medio del tumulto terrenal,<br/>¡Qué dulce paz!<br/>¡Sé firme, vengo ya!<br/>',NULL,197377,1);
INSERT INTO stanza VALUES('S2308','chorus','¡Gloria, gloria! ¡Aleluya!<br/>Gloria, gloria! ¡Aleluya!<br/>¡Gloria, gloria! ¡Aleluya!<br/>El Rey pronto vendrá!<br/>',NULL,197378,2);
INSERT INTO stanza VALUES('S2308','2','Vivo a diario en Su promesa y Su gloria espero ver;<br/>En desierto de tristeza, luz de sol veo nacer;<br/>Escuchar Su voz anhelo: “¡Sube, amado hijo, ven!”<br/>¡El Rey pronto vendrá!<br/>',NULL,197379,3);
INSERT INTO stanza VALUES('S2308','3','¿Qué importa la tristeza o el tumulto terrenal?<br/>El conflicto ya se acaba, y pronto regresará<br/>Nuestro Príncipe que al vencedor el premio otorgará<br/>¡El Rey pronto vendrá!<br/>',NULL,197380,4);
INSERT INTO stanza VALUES('S2308','4','En los montes y en los mares cierta gloria hoy se ve;<br/>Todo valle y desierto un camino puede ser<br/>Que me lleve a la gloria, desde que me dijo Él:<br/>¡Sé firme, vengo ya!<br/>',NULL,197381,5);
INSERT INTO stanza VALUES('S2309','1','Me entrego a Ti, oh Jehová,<br/>Soy moral, me aparto del mal,<br/>Pero no encuentro reposo ni prosperidad.<br/>',NULL,197382,1);
INSERT INTO stanza VALUES('S2309','2','Clamo queriendo respuesta,<br/>Pero no escucho Tu voz.<br/>Clamo pidiendo justicia, y no hay equidad.<br/>',NULL,197383,2);
INSERT INTO stanza VALUES('S2309','3','En la inquietud, oh Jehová,<br/>Te apareciste a mí,<br/>Te revelaste como la vida para mí.<br/>',NULL,197384,3);
INSERT INTO stanza VALUES('S2309','chorus','De oídas había oído de Ti, mas ahora te he visto;<br/>Por tanto, me aborrezco,<br/>Y me arrepiento en polvo y ceniza.<br/>Vuelvo a la fuente viviente, quien es<br/>Cristo, el árbol de vida,<br/>Y cuando le como vivo por causa de Él.<br/>',NULL,197385,4);
INSERT INTO stanza VALUES('S2309','4','De Jehová son los pasos del hombre.<br/>Adorará a Dios por Sus caminos.<br/>Estos son más altos que los nuestros.<br/>Él es el camino, la vida y también la verdad.<br/>',NULL,197386,5);
INSERT INTO stanza VALUES('S2309','chorus','De oídas había oído de Ti, mas ahora te he visto;<br/>Por tanto, me aborrezco,<br/>Y me arrepiento en polvo y ceniza.<br/>Vuelvo a la fuente viviente, quien es<br/>Cristo, el árbol de vida,<br/>Y cuando le como vivo por causa de Él.<br/>',NULL,197387,6);
INSERT INTO stanza VALUES('S2309','5','Me esforcé por ser un hombre de bien.<br/>Mas encontré en Tu palabra verdad.<br/>Quieres ser, en mi vivir, realidad.<br/>Comiendo el árbol de vida te puedo expresar.<br/>',NULL,197388,7);
INSERT INTO stanza VALUES('S2309','chorus','Hoy puedo decir que te he visto<br/>He ganado una parte de Ti.<br/>Feliz yo renuncio a<br/>Todo esfuerzo alejado de Ti.<br/>Vuelvo a mi fuente viviente quien es:<br/>Cristo, el árbol de vida.<br/>//Y cuando le como vivo por causa de Él.//<br/>',NULL,197389,8);
INSERT INTO stanza VALUES('S2310','1','Siglos atrás, antes de la creación,<br/>Un buen placer tuvo‿en Su corazón:<br/>Hijos tener a la‿imagen del Hijo de Su‿amor,<br/>Dios, en amor, en Él nos escogió.<br/>',NULL,197390,1);
INSERT INTO stanza VALUES('S2310','2','Quería Dios Su vida compartir,<br/>Al Padre fue, nos preparó lugar;<br/>Y regresó y con Él nos tomó, nos colocó<br/>En el divino seno paternal.<br/>',NULL,197391,2);
INSERT INTO stanza VALUES('S2310','3','Ahora‿a los tres un cuarto se‿añadio:<br/>La iglesia que con sangre redimió;<br/>Divinidad y‿humanidad ahora uno son,<br/>Cristo‿en nosotros, nosotros en Dios.<br/>',NULL,197392,3);
INSERT INTO stanza VALUES('S2310','4','Tus muchos hijos dan adoración,<br/>Tu Hijo canta en nuestra canción;<br/>En medio de la‿iglesia que‿es Tu_expression,<br/>Ten en nosotros Tu satisfacción.<br/>',NULL,197393,4);
INSERT INTO stanza VALUES('S2311','1','Buscad las cosas que son de arriba,<br/>Donde Cristo vive, sentado a la diestra de Dios.<br/>Poned la mira en las cosas de arriba,<br/>No en las que son de esta tierra.<br/>Porque habéis muerto, y vuestra vida<br/>Está escondida juntamente con Cristo en Dios.<br/>Cuando Cristo, que es nuestra vida,<br/>Se manifieste, ¡Oh, aleluya!<br/>También vosotros seréis manifestados<br/>Con Él en gloria, ¡Oh! ¡Aleluya!<br/>Con Él en gloria, ¡Oh! ¡Aleluya!<br/>¡Aleluya! ¡Aleluya! ¡Aleluya!<br/>',NULL,197394,1);
INSERT INTO stanza VALUES('S2312','1','El Señor Jehová me ha dado<br/>Lengua de discípulo,<br/>Para que sepa sostener<br/>Con una palabra al cansado.<br/>Mañana tras mañana me despierta;<br/>Despierta mi oído<br/>Para que escuche como discípulo.<br/>El Señor Jehová me abrió el oído;<br/>///Y yo no fui rebelde,///<br/>Ni me volví atrás.<br/>',NULL,197395,1);
INSERT INTO stanza VALUES('S2313','1','Mi corazón Tuyo es Señor,<br/>Nada ni nadie puede robarlo,<br/>Ni, aunque todo intente en mí impedir<br/>El poder derramar<br/>Mi corazón para Ti.<br/>Tuyo es mi corazón, Señor,<br/>Nada ni nadie puede robarlo,<br/>Ni aunque todo intente en mí impedir<br/>El poder derramar<br/>Mi corazón para Ti.<br/>',NULL,197396,1);
INSERT INTO stanza VALUES('S2314','1','Para santificarla, purificándola<br/>Por el lavamiento del agua en la palabra,<br/>A fin de presentársela a Sí mismo,<br/>Una iglesia gloriosa,<br/>Que no tuviese mancha ni arruga<br/>Ni cosa semejante,<br/>Sino que fuese santa y sin defecto.<br/>',NULL,197397,1);
INSERT INTO stanza VALUES('S2315','1','Mi alma tiene sed de Ti Señor.<br/>¿Cuándo podré delante de Ti‿estar?<br/>Cierro la puerta‿al mundo exterior,<br/>Me presento‿a Ti en mi espíritu.<br/>',NULL,197398,1);
INSERT INTO stanza VALUES('S2315','chorus','Orando puedo‿inhalarte,<br/>Y‿al orar puedo‿exhalarme.<br/>¡Oh Señor Jesús! Quiero inhalarte‿a Ti.<br/>',NULL,197399,2);
INSERT INTO stanza VALUES('S2315','2','No me‿apresuro‿en abrir mi boca;<br/>Guardo silencio, detengo mi ser.<br/>Contemplándote,‿eres mi tesoro;<br/>Señor, te miro en mi espíritu.<br/>',NULL,197400,3);
INSERT INTO stanza VALUES('S2315','chorus','Orando puedo‿inhalarte,<br/>Y‿al orar puedo‿exhalarme.<br/>¡Oh Señor Jesús! Quiero inhalarte‿a Ti.<br/>',NULL,197401,4);
INSERT INTO stanza VALUES('S2315','3','Señor, enséñame‿a‿inquirir en Ti.<br/>Me guíe la expresión de tus ojos.<br/>¿Qué es lo que Tú deseas orar?<br/>Eres gentil, yo tan imprudente.<br/>',NULL,197402,5);
INSERT INTO stanza VALUES('S2315','chorus','Orando puedo‿inhalarte,<br/>Y‿al orar puedo‿exhalarme.<br/>¡Oh Señor Jesús! Quiero inhalarte‿a Ti.<br/>',NULL,197403,6);
INSERT INTO stanza VALUES('S2315','4','Aprendo en Ti, Señor, a esperar.<br/>El tiempo lo decides Tú Jesús.<br/>Reflexiono‿en lo que eres para mí,<br/>Medito‿en lo que has hecho Tú por mí.<br/>',NULL,197404,7);
INSERT INTO stanza VALUES('S2315','chorus','Orando puedo‿inhalarte,<br/>Y‿al orar puedo‿exhalarme.<br/>¡Oh Señor Jesús! Quiero inhalarte‿a Ti.<br/>',NULL,197405,8);
INSERT INTO stanza VALUES('S2315','5','Adoración,<br/>Mi ser postrado‿en esplendor santo,‿ofrezco<br/>Alabanzas,<br/>Al meditar en Ti, de mi‿interior fluyen.<br/>',NULL,197406,9);
INSERT INTO stanza VALUES('S2315','chorus','No sé cómo orar, confieso<br/>Mas desde mi interior gimo:<br/>Desvanece Señor toda oscuridad<br/>',NULL,197407,10);
INSERT INTO stanza VALUES('S2315','6','Intercesión.<br/>Permaneciendo en Tu presencia Señor<br/>¿Me‿ocultarás<br/>Las intenciones que hay en Tu corazón?<br/>',NULL,197408,11);
INSERT INTO stanza VALUES('S2315','chorus','No sé cómo orar, confieso<br/>Mas desde mi interior gimo:<br/>Muéstrame Señor que senda debo tomar.<br/>',NULL,197409,12);
INSERT INTO stanza VALUES('S2315','7','Sin marcharme,<br/>No solamente‿hablo‿y luego te despido.<br/>Permanezco‿y,<br/>Permito que Tu termines de‿hablar Señor.<br/>',NULL,197410,13);
INSERT INTO stanza VALUES('S2315','chorus','No sé cómo orar, confieso<br/>Mas desde mi interior gimo:<br/>Absorberte quiero en mi oración Señor.<br/>',NULL,197411,14);
INSERT INTO stanza VALUES('S2316','1','Amo al Señor, mi fuerza es.<br/>Amo al Señor bebida es.<br/>No importa lo que otros piensen de Él,<br/>Amo al Señor, mi fuerza es.<br/>Amo al Señor, me escucha Él,<br/>Amo al Señor, me cuida Él.<br/>Amo al Señor, aún con lágrimas,<br/>Amo al Señor, me escucha Él.<br/>',NULL,197412,1);
INSERT INTO stanza VALUES('S2316','2','Te amo Señor, amo Tu hablar,<br/>Tus palabras, ¡cuán dulces son!<br/>Sería absurdo alejarme de Ti<br/>Te amo, Señor, amo Tu hablar.<br/>Te amo tanto, mi Señor<br/>Tu dulce toque amo yo.<br/>Tu tierno amor apaga lo demás.<br/>Te amo tanto, mi Señor<br/>Te amo Señor.<br/>',NULL,197413,2);
INSERT INTO stanza VALUES('S2317','1','La intención de Dios es un grupo tener<br/>De personas llenas de Él,<br/>Llenas de Él mismo como su vida,<br/>La intención de Dios ahora es.<br/>Que en Su imagen puedan expresarle a Él<br/>Y representarle con Su autoridad,<br/>La intención de Dios ahora es.<br/>',NULL,197414,1);
INSERT INTO stanza VALUES('S2318','1','Dios tiene un deseo: Su Cuerpo‿edificar;<br/>Por medio de Sus miembros lo‿ha de realizar.<br/>',NULL,197415,1);
INSERT INTO stanza VALUES('S2318','chorus','En vida creceremos,<br/>Para‿edificación;<br/>Funcionando‿en el Cuerpo, unidos en amor.<br/>',NULL,197416,2);
INSERT INTO stanza VALUES('S2318','2','Los miembros de Su Cuerpo, coordinan entre sí;<br/>Con Cristo cooperando en su diario vivir.<br/>',NULL,197417,3);
INSERT INTO stanza VALUES('S2318','chorus','En vida creceremos,<br/>Para‿edificación;<br/>Funcionando‿en el Cuerpo, unidos en amor.<br/>',NULL,197418,4);
INSERT INTO stanza VALUES('S2318','3','Santos perfeccionados, ejercen su función;<br/>Causando‿el crecimiento para‿edificación.<br/>',NULL,197419,5);
INSERT INTO stanza VALUES('S2318','chorus','En vida creceremos,<br/>Para‿edificación;<br/>Funcionando‿en el Cuerpo, unidos en amor.<br/>',NULL,197420,6);
INSERT INTO stanza VALUES('S2318','4','El Cuerpo se edifica a sí mismo en amor;<br/>Y éste es el mismo amor del Triuno Dios.<br/>',NULL,197421,7);
INSERT INTO stanza VALUES('S2318','chorus','¡Oh, lógralo‿en nosotros!<br/>Impártenos Tu‿amor;<br/>Y‿así cooperaremos en Tu‿edificación.<br/>',NULL,197422,8);
INSERT INTO stanza VALUES('S2319','1','¡Oh Jesús, te anhelamos!<br/>Con nosotros ven ya.<br/>Nuestro Novio y Amado,<br/>Sólo Tú puedes llenar.<br/>Sí, Tú, Señor.<br/>Sólo Tú puedes llenar.<br/>',NULL,197423,1);
INSERT INTO stanza VALUES('S2319','2','¡Tómame, Amado mío!<br/>Y que Tu compasión<br/>Todo mi ser atraiga;<br/>Quema los ídolos.<br/>Quema, quema,<br/>Quema los ídolos.<br/>',NULL,197424,2);
INSERT INTO stanza VALUES('S2319','3','Guárdame en Tu afecto;<br/>Sencillo, en castidad.<br/>En todo el universo,<br/>Como Tú no hay otro igual.<br/>¡Sólo Cristo!<br/>Como Tú no hay otro igual.<br/>',NULL,197425,3);
INSERT INTO stanza VALUES('S2319','4','Cada día, más cerca<br/>De Ti estamos, Señor.<br/>Nuestro corazón ruega:<br/>¡Ven pronto, ven hoy, Señor!<br/>Señor, amén,<br/>¡Ven pronto, ven hoy, Señor!<br/>',NULL,197426,4);
INSERT INTO stanza VALUES('S2319','note','*Un himno del hermano Andrew Yu.<br/>',NULL,197427,5);
INSERT INTO stanza VALUES('S2320','1','Mora el Espíritu en mi ser,<br/>Compuesto y todo-inclusivo es,<br/>Su dulce muerte y resurrección,<br/>Sus elementos hoy son.<br/>',NULL,197428,1);
INSERT INTO stanza VALUES('S2320','chorus','Que sea nuestra realidad<br/>En el espíritu andar<br/>Para vida ministrar.<br/>',NULL,197429,2);
INSERT INTO stanza VALUES('S2320','2','Para que haya resurrección<br/>A tierra el grano debe caer.<br/>Al quebrar el cascarón será<br/>Que la vida fluirá.<br/>',NULL,197430,3);
INSERT INTO stanza VALUES('S2320','chorus','Haznos estos granos ¡Oh Señor!<br/>Que en la tierra caerán<br/>Para vida liberar.<br/>',NULL,197431,4);
INSERT INTO stanza VALUES('S2320','3','Debemos hoy a Cristo comer<br/>Así vida al Cuerpo fluirá,<br/>Cristo árbol de la vida es,<br/>De Él me puedo alimentar.<br/>',NULL,197432,5);
INSERT INTO stanza VALUES('S2320','chorus','Tal Cristo crucificado fue<br/>Él hoy en resurrección<br/>Produce edificación.<br/>',NULL,197433,6);
INSERT INTO stanza VALUES('S2320','chorus','Y todos los miembros crecerán<br/>Hasta que consumará<br/>La Nueva Jerusalén.<br/>',NULL,197434,7);
INSERT INTO stanza VALUES('S2321','1','En esta noche oscura,<br/>Navegando en la tormenta,<br/>Sin esperanza ni paz, en un agitado mar.<br/>¿Qué es lo que veo sobre las olas?<br/>Es un hombre que camina hacia mí,<br/>Y dice:<br/>',NULL,197435,1);
INSERT INTO stanza VALUES('S2321','chorus','“Yo Soy, Yo Soy, no temáis.<br/>Hazme entrar a tu barca y calmaré<br/>Las olas; y un puerto para ti seré.<br/>El camino Yo Soy, déjame entrar”<br/>',NULL,197436,2);
INSERT INTO stanza VALUES('S2321','2','Todos mis problemas hoy<br/>Me hacen sentir abrumado.<br/>Tantas luchas y dolor, de mi alma roban la paz.<br/>Estoy ya tan cansado de luchar.<br/>¿Habrá alguien que mi dolor pueda aliviar?<br/>Él dice:<br/>',NULL,197437,3);
INSERT INTO stanza VALUES('S2321','chorus','“Yo Soy, Yo Soy, no temáis.<br/>Hazme entrar a tu barca y calmaré<br/>Las olas; y un puerto para ti seré.<br/>El camino Yo Soy, déjame entrar”<br/>',NULL,197438,4);
INSERT INTO stanza VALUES('S2321','3','Jesús el Hijo de Dios,<br/>Lleno de compasión vino<br/>Como un hombre y en la cruz tus pecados Él llevó.<br/>Su vida puede la muerte anular.<br/>¿Dejarás que alivie hoy tu corazón?<br/>Él dirá:<br/>',NULL,197439,5);
INSERT INTO stanza VALUES('S2321','chorus','“Yo Soy, Yo Soy, no temáis.<br/>Solo cree, serás salvo al clamar:<br/>¡Oh Señor Jesús! Te necesito hoy,<br/>Entra en mi corazón y quédate”.<br/>',NULL,197440,6);
INSERT INTO stanza VALUES('S2322','1','El deseo de Dios en Su corazón:<br/>Del hombre Él su vida ser;<br/>Su reproducción, Su expresión ganar,<br/>Al vivirte, Señor Jesús.<br/>',NULL,197441,1);
INSERT INTO stanza VALUES('S2322','chorus','Señor, hoy‿eres mi‿elección,<br/>Jesús precioso,<br/>Sé Tú mi primer amor.<br/>Señor, quiero amarte a Ti,<br/>Y disfrutarte;<br/>Como un Dios-hombre vivir.<br/>',NULL,197442,2);
INSERT INTO stanza VALUES('S2322','2','Sólo el amor nos podrá guardar<br/>En tierna‿y dulce relación.<br/>Atraída soy, corremos en pos,<br/>Al amarte, Señor Jesús.<br/>',NULL,197443,3);
INSERT INTO stanza VALUES('S2322','3','Árbol de vida Cristo‿es para mí,<br/>Es mi plena satisfacción.<br/>Amándote a Ti, puedo disfrutar,<br/>Al comerte, Señor Jesús.<br/>',NULL,197444,4);
INSERT INTO stanza VALUES('S2322','4','En la eternidad, Dios y hombre‿están<br/>Mezclados en una‿entidad.<br/>Gloria y santidad se expresan al<br/>Reflejarte, Señor Jesús.<br/>',NULL,197445,5);
INSERT INTO stanza VALUES('S2322','chorus','Señor, hoy somos Tu‿expresión;<br/>Ciudad gloriosa,<br/>La Nueva Jerusalén.<br/>¡Gloria! en la ciudad de‿amor;<br/>Eternamente,<br/>En un romance vivir<br/>Junto a Ti.<br/>',NULL,197446,6);
INSERT INTO stanza VALUES('S2323','1','Porque hay esperanza para el árbol que,<br/>Aun siendo cortado pronto se renovará,<br/>Y no dejará el renuevo.<br/>Si envejeciere en la tierra su raíz,<br/>Y en polvo muere su tronco, al percibir aguas,<br/>Al percibir aguas brotará,<br/>Y hará copa, como planta nueva,<br/>Al percibir aguas.<br/>',NULL,197447,1);
INSERT INTO stanza VALUES('S2324','1','Yo estaba pescando cuando oí una voz<br/>Que me dijo “Sígueme”<br/>Yo estaba pescando,<br/>Pues soy pescador<br/>De la mar, pero ya no seguiré...<br/>',NULL,197448,1);
INSERT INTO stanza VALUES('S2324','chorus','Ya no tengo barca, ya dejé mi red<br/>Ya no me hace falta, encontré al Rey<br/>Que me dijo “sígueme”, “sígueme”.<br/>(Final: “Sígueme”)<br/>',NULL,197449,2);
INSERT INTO stanza VALUES('S2324','2','Mi guitarra está sonando<br/>Con gran esplendor<br/>Para Cristo mi Señor.<br/>Y la mar quedó llorando,<br/>Marinero ya no soy,<br/>Pescador, de las almas ahora soy.<br/>',NULL,197450,3);
INSERT INTO stanza VALUES('S2325','1','Yo soy una rosa de Sarón,<br/>Un lirio de los valles.<br/>Como lirio entre los espinos,<br/>Así es mi amor entre las hijas.<br/>Como manzano entre los árboles del bosque,<br/>Así es mi Amado entre los hijos:<br/>',NULL,197451,1);
INSERT INTO stanza VALUES('S2325','chorus','En Su sombra me deleité y me senté,<br/>Y Su fruto fue dulce a mi paladar.<br/>Me llevó a la casa del banquete,<br/>Y Su estandarte sobre mí era el amor.<br/>',NULL,197452,2);
INSERT INTO stanza VALUES('S2325','2','Sustentadme con tortas de pasas,<br/>Refrescadme con manzanas,<br/>Porque estoy enferma de amor.<br/>Su izquierda está bajo mi cabeza,<br/>Porque estoy enferma de amor<br/>Y Su derecha me abraza.<br/>',NULL,197453,3);
INSERT INTO stanza VALUES('S2326','1','Señor hazme un vencedor<br/>Para edificar Tu Cuerpo,<br/>Para consagrar mi tiempo<br/>Para Tu edificación.<br/>Aunque sé que nada soy<br/>Como un vaso me presento,<br/>Lléname con Tu elemento,<br/>Quiero más de Ti Señor.<br/>',NULL,197454,1);
INSERT INTO stanza VALUES('S2326','2','Es mi oración que Tu cruz<br/>Obre profundo en mi vida,<br/>Aunque duelan las heridas<br/>Terminando con el yo.<br/>Líbrame de mi opinión<br/>Y de mi ser natural,<br/>Que solamente Tu unción<br/>Gobierne todo mi andar.<br/>',NULL,197455,2);
INSERT INTO stanza VALUES('S2326','3','Tengo Tu vida mi Dios,<br/>También Tu naturaleza.<br/>Aleluya qué riqueza,<br/>Tengo la vida de Dios!<br/>Hoy queremos Tu expresión,<br/>Que la vida de Tus miembros,<br/>Haga realidad Tu Cuerpo<br/>Por la compenetración.<br/>',NULL,197456,3);
INSERT INTO stanza VALUES('S2326','4','Señor hoy quiero vivir<br/>Por Tu vida divinal,<br/>Fórjate en mí más y más,<br/>Quiero a mi opinión morir.<br/>Hoy puedo ser vencedor,<br/>Puedo vencer cada día<br/>Por Tu palabra de vida<br/>Y por Tu sangre Señor.<br/>',NULL,197457,4);
INSERT INTO stanza VALUES('S2326','5','La Nueva Jerusalén<br/>Tu preciosa novia amada<br/>Hoy Señor mi meta es<br/>Del mundo no quiero nada<br/>Intensificado estás<br/>Siete veces mi Señor<br/>Oh lléname de Tu vida<br/>Señor hazme un vencedor.<br/>',NULL,197458,5);
INSERT INTO stanza VALUES('S2327','1','Hermanos proclamemos:<br/>Jesús es el Señor;<br/>Es digno para siempre<br/>De nuestra adoración.<br/>Jesucristo te adoramos<br/>Oh precioso Salvador;<br/>Querido Dios Cordero<br/>Amado Redentor.<br/>',NULL,197459,1);
INSERT INTO stanza VALUES('S2327','chorus','Él nos dio Su vida,<br/>Y por Sus heridas<br/>Purgó nuestras culpas.<br/>Gloria al Salvador!<br/>¡Gloria al Salvador!<br/>',NULL,197460,2);
INSERT INTO stanza VALUES('S2327','2','Señor hoy por Tu sangre<br/>Estamos ante Ti<br/>Venciendo al enemigo<br/>Y adorándote aquí<br/>Querido Dios glorioso<br/>Amado Emanuel<br/>Eres Dios con nosotros<br/>Eternamente fiel.<br/>',NULL,197461,3);
INSERT INTO stanza VALUES('S2327','3','Jesús nuestro querido<br/>Y amado Salvador;<br/>Por nosotros te diste<br/>Que gracia y bendición.<br/>Ya no somos hoy esclavos<br/>Del pecado y la maldad;<br/>Eres hoy Tú nuestra vida<br/>Grande es Tu fidelidad.<br/>',NULL,197462,4);
INSERT INTO stanza VALUES('S2327','4','Por Tu misericordia<br/>Estamos ante Ti;<br/>Rogando que Tu reino<br/>Se manifieste aquí.<br/>Proclamamos Tu victoria<br/>Amado Redentor;<br/>Este es nuestro testimonio<br/>Jesús es el Señor.<br/>',NULL,197463,5);
INSERT INTO stanza VALUES('S2328','1','Un vagabundo era yo,<br/>Mi destino creía tener,<br/>Sin saber que era mi vida,<br/>Sonriendo, a veces llorando.<br/>Un vacío siempre estaba en mi ser,<br/>No tenía paz,<br/>Sólo encontré tristeza.<br/>',NULL,197464,1);
INSERT INTO stanza VALUES('S2328','2','Sin saber por dónde ir,<br/>Sin ayuda ni oración,<br/>Algo en mí seguía buscando,<br/>Si valía seguir viviendo.<br/>La respuesta en un nombre la encontré,<br/>No soy igual,<br/>Desde que hallé a Cristo.<br/>',NULL,197465,2);
INSERT INTO stanza VALUES('S2328','3','Él vive dentro de mi ser,<br/>Para mi vida el todo es Él.<br/>Vida y paz en mi engrandecen,<br/>Cuando clamo a Su nombre.<br/>Ya mi alma nada tiene que buscar,<br/>Le tengo a Él,<br/>Y Él sí me satisface.<br/>',NULL,197466,3);
INSERT INTO stanza VALUES('S2329','1','¡La gracia resonó,<br/>Mi espíritu avivó!<br/>Su Palabra cumplió,<br/>¡Dio muestra de Su amor!<br/>¡Jesús apareció!<br/>Con fuerza proclamó;<br/>El Jubileo llegó!<br/>',NULL,197467,1);
INSERT INTO stanza VALUES('S2329','chorus','¡El Jubileo llegó!<br/>¡El Jubileo llegó!<br/>El profeta anunció;<br/>¡Jehová lo declaró!<br/>Completa salvación,<br/>Este año trajo Dios.<br/>¡El Jubileo llegó!<br/>',NULL,197468,2);
INSERT INTO stanza VALUES('S2329','2','Sobre el hombre Jesús,<br/>¡Vino el Espíritu!<br/>Al Salvador ungió,<br/>¡Heraldo lo hizo Dios!<br/>¡Al pobre enriqueció!<br/>¡Sanó su corazón!<br/>¡El Jubileo llegó”!<br/>',NULL,197469,3);
INSERT INTO stanza VALUES('S2329','3','¡Cautivos liberó!<br/>¡La libertad gritó!<br/>¡A ciegos vista dio!<br/>¡Recibieron visión!<br/>Al oprimido, Dios,<br/>Le dio liberación!<br/>El Jubileo llegó!<br/>',NULL,197470,4);
INSERT INTO stanza VALUES('S2329','4','¡A todo el mundo hablad<br/>De_esta felicidad!<br/>Donde se halle dolor<br/>Y abunde la aflicción;<br/>¡Las nuevas proclamad!<br/>Ésta canción gritad;<br/>¡El Jubileo llegó!<br/>',NULL,197471,5);
INSERT INTO stanza VALUES('S2330','1','Una vida entregada por Él,<br/>Es una vida llena de gozo,<br/>Hasta que aprendas a dar<br/>Jamás vivirás, te sentirás solo.<br/>',NULL,197472,1);
INSERT INTO stanza VALUES('S2330','chorus','Es que Dios no puede ser visto<br/>Por ningún hombre si no nos damos a Él,<br/>Después a otros, entonces sabrás<br/>Que Dios es amor.<br/>',NULL,197473,2);
INSERT INTO stanza VALUES('S2330','2','Amar es derramar<br/>Tu corazón calladamente,<br/>Servir sin nada esperar,<br/>Tu ayuda brindar al pobre y al débil.<br/>',NULL,197474,3);
INSERT INTO stanza VALUES('S2330','chorus','Es que Dios no puede ser visto<br/>Por ningún hombre si no nos damos a Él,<br/>Después a otros, entonces sabrás<br/>Que Dios es amor.<br/>',NULL,197475,4);
INSERT INTO stanza VALUES('S2330','3','Da tu vida al Señor,<br/>Derrama tu vida por causa de otros,<br/>Y ama a aquellos que están<br/>En gran soledad y desconsolados.<br/>',NULL,197476,5);
INSERT INTO stanza VALUES('S2330','chorus','Porque Dios no puede ser visto<br/>Por ningún hombre si no nos damos a Él,<br/>Después a otros, entonces sabrás,<br/>Que Dios es amor.<br/>',NULL,197477,6);
INSERT INTO stanza VALUES('S2331','1','Y de Jesucristo, el Testigo fiel,<br/>Y el Soberano de los reyes de la tierra.<br/>Al que nos amó, y nos lavó<br/>De nuestros pecados<br/>Con Su sangre, con Su sangre.<br/>Y nos hizo reyes y sacerdotes<br/>Para Dios Su Padre<br/>Para Dios Su Padre;<br/>A Él sea gloria e imperio<br/>Por los siglos de los siglos,<br/>Amén. Amén. Amén.<br/>',NULL,197478,1);
INSERT INTO stanza VALUES('S2332','1','Viviente vid en mí, es la realidad<br/>Del hombre y Dios, orgánica unión<br/>Mutuo habitar, dulce comunión,<br/>La expresión, del mezclar total.<br/>',NULL,197479,1);
INSERT INTO stanza VALUES('S2332','2','Permaneciendo en Él, siento el fluir,<br/>Siendo ramas de Él, hay el expresar;<br/>Requiere Dios de mí, depender de Él,<br/>Para fruto dar así, ramas añadir.<br/>',NULL,197480,2);
INSERT INTO stanza VALUES('S2332','chorus','Padre, labrador, hombre, esposo, fuente es Él,<br/>Suelo, sol y aire dan, nutrición total.<br/>Hijo, vid viviente, expresión de Dios es Él.<br/>¡Y el Espíritu real, jugo de vida!<br/>',NULL,197481,3);
INSERT INTO stanza VALUES('S2333','1','Antes bien, como está escrito:<br/>“Cosas que ojo no vio,<br/>Ni oído oyó, ni han subido<br/>En corazón de hombre,<br/>Son las que Dios ha preparado<br/>Para los que le aman, los que le aman”.<br/>Son las que Dios ha preparado<br/>Para los que le aman, los que le aman”.<br/>Los que le aman,<br/>Los que le aman,<br/>Los que le aman,<br/>Los que le aman.<br/>',NULL,197482,1);
INSERT INTO stanza VALUES('S2334','1','Al volver y descansar seréis salvos;<br/>En quietud y en confianza será<br/>Vuestra fortaleza.<br/>Al volver y descansar seréis salvos;<br/>En quietud y en confianza será<br/>Vuestra fortaleza.<br/>',NULL,197483,1);
INSERT INTO stanza VALUES('S2335','1','¡Oh! No andéis tan ansiosos aquí,<br/>Antes a Dios sólo orar y pedir,<br/>Así Su paz, que excede el pensar,<br/>La mente y el corazón guardará.<br/>',NULL,197484,1);
INSERT INTO stanza VALUES('S2335','2','¡Oh! Qué descanso tenemos en Dios,<br/>Y en el Espíritu consuelo hay,<br/>Aun en momentos de muerte y dolor<br/>Paz y vigor Su presencia nos da.<br/>',NULL,197485,2);
INSERT INTO stanza VALUES('S2335','chorus','El rico Dios, con Su valor,<br/>Nos suplirá en toda ocasión,<br/>Pronto en gloria Él regresará<br/>Y toda lágrima así secará.<br/>',NULL,197486,3);
INSERT INTO stanza VALUES('S2335','3','A medianoche en oscura prisión<br/>Pablo y Silas alaban a Dios:<br/>"Siempre y en todo momento aprendí<br/>A estar alegre, aun al sufrir".<br/>',NULL,197487,4);
INSERT INTO stanza VALUES('S2335','4','Todo podemos en nuestro buen Dios,<br/>Nos fortalece con Su gran amor,<br/>La provisión el Espíritu da,<br/>Y a Cristo vamos a magnificar.<br/>',NULL,197488,5);
INSERT INTO stanza VALUES('S2335','chorus','El rico Dios, con Su valor,<br/>Nos suplirá en toda ocasión,<br/>Pronto en gloria Él regresará<br/>Y toda lágrima así secará.<br/>',NULL,197489,6);
INSERT INTO stanza VALUES('S2336','1','Me presento hoy a Ti;<br/>Atiendo al llamado aquí.<br/>En este tiempo final<br/>Puedes conmigo contar.<br/>',NULL,197490,1);
INSERT INTO stanza VALUES('S2336','chorus','Fui convocado hoy<br/>Para correr en pos de Ti.<br/>Mi premio y galardón eres Tu mi Jesús.<br/>Prosigo sin desmayar, sin peso avanzar.<br/>Corriendo así para ganar.<br/>Nada me detendrá ni me enredará,<br/>Mis ojos en Ti se mantendrán<br/>Mis ojos en Ti se mantendrán<br/>Mis ojos en Ti se mantendrán<br/>',NULL,197491,2);
INSERT INTO stanza VALUES('S2336','2','Por mi fuerza no podré,<br/>Todo intento vano es.<br/>Mi fuerza para correr<br/>Es tu poder de atracción.<br/>',NULL,197492,3);
INSERT INTO stanza VALUES('S2336','chorus','Tu amor me cautivó;<br/>Precioso Tu, Encantador<br/>Eres el gran imán, solo Tu, mi Jesús.<br/>Prosigo sin desmayar, sin peso avanzar.<br/>Corriendo así para ganar.<br/>Nada me detendrá ni me enredará,<br/>Mis ojos en Ti se mantendrán<br/>',NULL,197493,4);
INSERT INTO stanza VALUES('S2337','1','Aunque Te_amo, Señor,<br/>Mi vida_aún se deforma.<br/>Te doy todo,_y después<br/>Lejos me voy —<br/>Te ruego que me_atraigas una_y_otra vez,<br/>En pos de Tí yo correré.<br/>',NULL,197494,1);
INSERT INTO stanza VALUES('S2337','chorus','Tu plan, Señor, he visto,<br/>Toqué Tu corazón.<br/>Deseo que_ahora me ganes por completo.<br/>Si_aún Te limito_a veces<br/>Y no cedo en mi_andar:<br/>Nunca me dejes de mirar.<br/>',NULL,197495,2);
INSERT INTO stanza VALUES('S2337','2','Señor, Tu bendición<br/>Sin igual, hoy_yo anhelo.<br/>No hay nada más, mi Dios,<br/>Por pedir hoy...<br/>Que por Tu guiar asirme_a Ti logre Señor.<br/>Hacia la meta seguiré.<br/>',NULL,197496,3);
INSERT INTO stanza VALUES('S2337','3','Moldéame Señor.<br/>Se Tu mi realidad.<br/>Quebrántame si así_es<br/>Tu voluntad.<br/>Desesperado estoy que_en mi_hagas Tu querer.<br/>Otros Te tocarán en mi.<br/>',NULL,197497,4);
INSERT INTO stanza VALUES('S2337','4','Señor avívame;<br/>Igual nunca me dejes.<br/>Sin reservas Te doy<br/>Mi corazón.<br/>Te doy mi vida y todo cuanto mio es.<br/>Señor, me aferro sólo_a Ti.<br/>',NULL,197498,5);
INSERT INTO stanza VALUES('S2338','1','¿Buscando en mí, qué puedo hallar?<br/>Nada he de encontrar<br/>Sólo un ser frágil y mortal.<br/>Buscando en mí, mis ojos verán<br/>Mi condición natural, y mi debilidad.<br/>',NULL,197499,1);
INSERT INTO stanza VALUES('S2338','chorus','Pues sólo en Jesucristo puedo encontrar<br/>Gracia, misericordia y paz<br/>Para una vida cristiana llevar.<br/>Pues sólo en Jesucristo puedo encontrar<br/>Gracia, misericordia y paz<br/>Para una vida cristiana llevar.<br/>',NULL,197500,2);
INSERT INTO stanza VALUES('S2338','2','Buscando en mí, mis ojos verán<br/>Mi condición natural y mi debilidad.<br/>Buscando a Cristo, Él me lavará<br/>Me perdonará y mi ser transformará.<br/>',NULL,197501,3);
INSERT INTO stanza VALUES('S2339','1','Hoy te entrego todo mi corazón,<br/>Mi vida, mi amor.<br/>Hoy te entrego todo lo que soy,<br/>Lo que tengo, lo que quiero.<br/>',NULL,197502,1);
INSERT INTO stanza VALUES('S2339','chorus','Y al oír Tu voz siento el calor<br/>Del verdadero amor,<br/>Y al pensar en Ti,<br/>En cuánto hiciste en mí,<br/>Siento al fin, al fin mi hogar.<br/>',NULL,197503,2);
INSERT INTO stanza VALUES('S2339','2','Saber que siempre a mi lado estás,<br/>Escuchar Tu voz en mi interior.<br/>Sentir Tu infinito amor en mí<br/>Es lo mejor que me puedes dar.<br/>',NULL,197504,3);
INSERT INTO stanza VALUES('S2339','3','A Tu lado tengo tanta paz,<br/>Esperanza, felicidad,<br/>Mi vida entera quiero entregarte,<br/>Es Tuya, hoy te la doy.<br/>',NULL,197505,4);
INSERT INTO stanza VALUES('S2339','chorus','Puedes entenderme hasta sin palabras,<br/>Todo lo sabes Tú;<br/>Eres mi refugio, eres Tú mi fuerza,<br/>Todo, todo, todo lo eres Tú.<br/>',NULL,197506,5);
INSERT INTO stanza VALUES('S2339','4','Y al invocar Tu nombre: “¡Oh Señor!”,<br/>Puedo verte cara a cara,<br/>No se turba ya mi corazón,<br/>Tú me amas, porque tuya soy.<br/>',NULL,197507,6);
INSERT INTO stanza VALUES('S2340','1','Y sacaréis con gozo aguas<br/>Desde las fuentes de salvación<br/>Y en aquel día diréis:<br/>Gloria a Dios!<br/>',NULL,197508,1);
INSERT INTO stanza VALUES('S2340','2','Y sacaréis con gozo aguas<br/>Desde las fuentes de salvación<br/>Y en aquel día diréis:<br/>Gloria a Dios!<br/>',NULL,197509,2);
INSERT INTO stanza VALUES('S2340','3','A Jehová cantad,<br/>Y aclamad Su santo Nombre.<br/>Celebrad en los pueblos Sus obras.<br/>Exulta y canta:<br/>Oh morada de Sión,<br/>Porque grande es<br/>En medio de ti el Santo de Israel.<br/>',NULL,197510,3);
INSERT INTO stanza VALUES('S2340','SoundCloud Link','https://soundcloud.com/valen_torres/y-sacareis-con-gozo-aguas-is',NULL,197511,4);
INSERT INTO stanza VALUES('S2341','1','¡Oh si me besara con besos de Su boca!<br/>(Oh, de Su boca)<br/>Mejores que‿el vino tus amores son, sí;<br/>Tu nombre es como ungüento derramado<br/>(Se‿ha derramado)<br/>Que‿atrae las doncellas en su‿amor a ti.<br/>',NULL,197512,1);
INSERT INTO stanza VALUES('S2341','chorus','Mi‿Amado es. Helo‿aquí, viene Él,<br/>La voz de mi‿Amado<br/>Montes y collados saltando‿está.<br/>Mi‿Amado es. Helo‿aquí, viene Él,<br/>La voz de mi Amado<br/>Quien es señalado‿entre diez mil.<br/>',NULL,197513,2);
INSERT INTO stanza VALUES('S2341','2','Hermosos trenzados adornan mi rostro<br/>(Adornan mi rostro)<br/>Entre collares mi cuello‿eligió, sí;<br/>Trenzados de oro, tachones de plata,<br/>(Oro y plata)<br/>Me dan el adorno de Su‿estimación.<br/>',NULL,197514,3);
INSERT INTO stanza VALUES('S2341','3','Él es para mí un manojo de mirra,<br/>(Como de mirra)<br/>Reposa‿en mis pechos, ¡Oh, qué gran amor! Sí.<br/>Racimo de flores de‿alheña‿en las viñas,<br/>(Viñas de‿En-gadi)<br/>Nuestro lecho‿es verde, fuerte‿es Su dosel.<br/>',NULL,197515,4);
INSERT INTO stanza VALUES('S2341','4','Para Él mis ojos son como paloma,<br/>(Como paloma)<br/>Él es quien me‿atrae y corro tras Él, sí.<br/>Estando‿en Su cámara tenemos amores,<br/>(Nuestros amores)<br/>Con tortas de pasas me sustenta Él.<br/>',NULL,197516,5);
INSERT INTO stanza VALUES('S2341','5','Os conjuro,‿oh hijas de Jerusalén<br/>(Jerusalén)<br/>Que no despertéis a‿este gran amor, sí;<br/>Mirando mi‿Amado‿está por la ventana,<br/>(Por la ventana)<br/>Helo‿aquí,‿Él está tras nuestra pared.<br/>',NULL,197517,6);
INSERT INTO stanza VALUES('S2341','6','Levántate‿hermosa, oh, amiga mía<br/>(Amiga mía)<br/>Ya pasó‿el invierno‿y la lluvia cesó, sí;<br/>Brotaron las flores, la‿higuera dio fruto,<br/>(Flores y frutos)<br/>Las vides en cierne ya dan su olor.<br/>',NULL,197518,7);
INSERT INTO stanza VALUES('S2341','chorus','Mi‿amada, ven, tiempo es de cantar<br/>Y de tener amores,<br/>Tu‿aspecto‿es bello, dulce‿es tu voz.<br/>Mi‿Amada ven, hazme‿oír tu voz,<br/>Muéstrame tu rostro,<br/>Oh, hermosa mía, levántate‿y ven.<br/>',NULL,197519,8);
INSERT INTO stanza VALUES('S2342','1','El Dios Triuno se procesó,<br/>Como‿una ley en mí se‿instaló.<br/>En el contacto con el Señor,<br/>Vivo‿en Su ley de vida hoy.<br/>',NULL,197520,1);
INSERT INTO stanza VALUES('S2342','chorus','Señor te amo, vengo a Ti,<br/>Quiero‿en Ti permanecer.<br/>Jesús te amo, guárdame‿en Ti,<br/>Mantenme‿a diario amándote a Ti.<br/>',NULL,197521,2);
INSERT INTO stanza VALUES('S2342','2','Sin esforzarme por mejorar,<br/>Tal como soy me puedo‿acercar.<br/>Mientras le invoco en comunión,<br/>En Cristo no‿hay condenación.<br/>',NULL,197522,3);
INSERT INTO stanza VALUES('S2342','chorus','Señor te amo, vengo a Ti,<br/>Quiero‿en Ti permanecer.<br/>Jesús te amo, guárdame‿en Ti,<br/>Mantenme‿a diario amándote a Ti.<br/>',NULL,197523,4);
INSERT INTO stanza VALUES('S2342','3','A Su‿Hijo Dios me conformará,<br/>“Todas las cosas” Él dispondrá.<br/>Si amo a Jesús y le digo amén,<br/>Todo coopera para bien.<br/>',NULL,197524,5);
INSERT INTO stanza VALUES('S2342','chorus','La ley de vida: en Su Cuerpo está,<br/>Miembros nos constituirá,<br/>Su‿economía consumará<br/>La Nueva Jerusalén nos hará.<br/>',NULL,197525,6);
INSERT INTO stanza VALUES('S2343','1','//Yo sé que fue pagado‿un alto precio<br/>Para que seamos uno tú y yo.<br/>Cuando Jesús derramaba Su vida,<br/>Él pensaba en ti, Él pensaba en mí,<br/>En nuestra‿unidad.//<br/>',NULL,197526,1);
INSERT INTO stanza VALUES('S2343','2','Nos veía redimidos por Su sangre.<br/>Combatiendo la batalla de la fe.<br/>Codo‿a codo trabajando,<br/>Su‿iglesia‿edificando,<br/>Y rompiendo las barreras por amor.<br/>',NULL,197527,2);
INSERT INTO stanza VALUES('S2343','3','Y mediante‿el Espíritu Santo,<br/>Proclamamos hoy aquí,<br/>Que pagaremos el precio de ser<br/>Todos un corazón en Jesús.<br/>Y si las tinieblas militan,<br/>Y nos quieren separar,<br/>Con nuestros ojos en Cristo<br/>Marchamos a la unidad.<br/>',NULL,197528,3);
INSERT INTO stanza VALUES('S2344','1','Estando yo muerto<br/>En mis delitos y pecados,<br/>Viviendo lejos de mi<br/>Cristo el Salvador,<br/>',NULL,197529,1);
INSERT INTO stanza VALUES('S2344','2','Dios me dio la vida<br/>Juntamente con Cristo,<br/>Por Su gracia salvo soy<br/>Y por la fe vivo en Él.<br/>',NULL,197530,2);
INSERT INTO stanza VALUES('S2344','chorus','//Mi Dios me ha resucitado,<br/>Sí, me ha resucitado,<br/>Él me ha sentado en los cielos<br/>Con Cristo, mi Jesús.//<br/>',NULL,197531,3);
INSERT INTO stanza VALUES('S2344','3','Soy hechura de mi Dios,<br/>Creado en Cristo Jesús,<br/>Andando en buenas obras<br/>Por Su gracia y por Su amor.<br/>',NULL,197532,4);
INSERT INTO stanza VALUES('S2345','1','Mirando hacia atrás,<br/>Me vi entre la gente,<br/>Entre gente que gritaba,<br/>Hacia un cierto hombre.<br/>Eran gritos de odio,<br/>Eran gritos de rencor,<br/>Eran gritos del alma,<br/>Hacia el Hijo de Dios.<br/>',NULL,197533,1);
INSERT INTO stanza VALUES('S2345','chorus','Jesús murió por ti en la cruz<br/>Su sangre derramó, por ti;<br/>Jesús vino a morir en la cruz,<br/>Para darte salvación.<br/>No lo puedo entender, no lo sé,<br/>¿Por qué Él vino a morir?<br/>No lo comprendo, pero una cosa sé:<br/>Que fue por ti, que el Cordero murió.<br/>',NULL,197534,2);
INSERT INTO stanza VALUES('S2345','2','Clavado en una cruz,<br/>El Señor agonizaba;<br/>Clavado en una cruz,<br/>Su sangre derramaba,<br/>La gente le injuriaba,<br/>Sin saber lo que decían,<br/>No podían entender,<br/>Que el sacrificio era por ellos.<br/>',NULL,197535,3);
INSERT INTO stanza VALUES('S2345','chorus','Jesús murió por ti en la cruz<br/>Su sangre derramó, por ti;<br/>Jesús vino a morir en la cruz,<br/>Para darte salvación.<br/>No lo puedo entender, no lo sé,<br/>¿Por qué Él vino a morir?<br/>No lo comprendo, pero una cosa sé:<br/>Que fue por ti, que el Cordero murió.<br/>',NULL,197536,4);
INSERT INTO stanza VALUES('S2345','3','Clavado en una cruz,<br/>El Señor agonizaba;<br/>Clavado en una cruz,<br/>Al Padre así clamaba:<br/>¡Perdónalos Señor,<br/>No saben lo que hacen;<br/>Mas con todo lo que hacen,<br/>Yo así les amo!<br/>',NULL,197537,5);
INSERT INTO stanza VALUES('S2345','chorus','Jesús murió por ti en la cruz<br/>Su sangre derramó, por ti;<br/>Jesús vino a morir en la cruz,<br/>Para darte salvación.<br/>No lo puedo entender, no lo sé,<br/>¿Por qué Él vino a morir?<br/>No lo comprendo, pero una cosa sé:<br/>Que fue por ti, que el Cordero murió.<br/>No lo vas a entender, no podrás,<br/>Nunca lo entenderás, jamás.<br/>Sólo abre el corazón, y sabrás<br/>Que el sacrificio fue por ti.<br/>',NULL,197538,6);
INSERT INTO stanza VALUES('S2346','1','Me dijo: Hijo de Hombre,<br/>Comed lo que halléis;<br/>Este rollo comed,<br/>Lo que halléis,<br/>Y ve, háblale<br/>A la casa de Israel.<br/>',NULL,197539,1);
INSERT INTO stanza VALUES('S2346','chorus','Luego abrí, sí, mi boca abrí,<br/>Y aquel rollo me dio a comer;<br/>Lo comí y en mi boca fue<br/>Como miel en dulzura es.<br/>',NULL,197540,2);
INSERT INTO stanza VALUES('S2346','2','Me dijo: Hijo de Hombre<br/>Tu vientre nutrid,<br/>Y entrañas del rollo llenad.<br/>Y ve, háblale<br/>A la casa de Israel.<br/>',NULL,197541,3);
INSERT INTO stanza VALUES('S2347','1','Gloria al Señor porque<br/>Rey es potente de gloria.<br/>De Sus mercedes<br/>Esté viva en ti la memoria.<br/>Oh despertad!<br/>En Su presencia: Entonad<br/>Himnos de honor y victoria.<br/>',NULL,197542,1);
INSERT INTO stanza VALUES('S2347','2','Gloria al Señor porque_El es<br/>Quien los orbes gobierna;<br/>Y te sostiene, te guarda_y<br/>Protege_en Sus alas.<br/>¿No has de mirar<br/>Como_en todo_El supo obrar<br/>Y siempre actuar por tu causa?<br/>',NULL,197543,2);
INSERT INTO stanza VALUES('S2347','3','Mi alma, bendice al Señor,<br/>De mi vida la fuente-<br/>El me dio vida,<br/>En salud me sostiene fielmente.<br/>En aflicción, en todo trance y dolor,<br/>Tus alas siempre presentes.<br/>',NULL,197544,3);
INSERT INTO stanza VALUES('S2347','4','Gloria al Señor que<br/>Prospera mi obra y defiende;<br/>Lluvias de amor, paz, bondad,<br/>Desde_el cielo El extiende.<br/>Con Su poder<br/>Maravillas puede hacer;<br/>Más con Su amor El me_entiende.<br/>',NULL,197545,4);
INSERT INTO stanza VALUES('S2347','5','Gloria al Señor:<br/>Todo lo que hay en nos Te bendice.<br/>Por Tus proezas<br/>También por Tu inmensa grandeza.<br/>Que nuestro "Amén"<br/>Resuene fuerte también.<br/>Seas por siempre bendito.<br/>',NULL,197546,5);
INSERT INTO stanza VALUES('S2348','1','Alabad a Jehová<br/>Naciones todas, pueblos todos alabadle.<br/>Porque ha engrandecido<br/>Sobre nosotros Su misericordia.<br/>Y la verdad de Jehová<br/>Es para siempre ¡Aleluya! ¡Amén!<br/>//Y la verdad de Jehová<br/>Es para siempre ¡Aleluya, Amén!//<br/>',NULL,197547,1);
INSERT INTO stanza VALUES('S2349','1','Y de alumbrar a todos para que vean<br/>Cuál es la economía del misterio escondido<br/>Desde los siglos en Dios,<br/>Que creó todas las cosas;<br/>A fin de que la multiforme sabiduría de Dios<br/>Sea ahora dada a conocer por medio<br/>De la iglesia a los principados y potestades<br/>En los lugares celestiales,<br/>Conforme al propósito eterno<br/>Que hizo en Cristo Jesús<br/>Nuestro Señor; nuestro Señor.<br/>',NULL,197548,1);
INSERT INTO stanza VALUES('S2350','1','Quiero testificarte<br/>De mi primer amor,<br/>Es mi Rey, es mi vida,<br/>¡Él es el Vencedor!<br/>Él para redimirme,<br/>En una cruz murió,<br/>Vertió toda Su sangre.<br/>¡Que Señor tengo yo!<br/>',NULL,197549,1);
INSERT INTO stanza VALUES('S2350','chorus','El Señor, mi Señor,<br/>Para siempre Él es el Vencedor.<br/>Mi Señor, el Señor,<br/>Aleluya! Jesús es vencedor.<br/>',NULL,197550,2);
INSERT INTO stanza VALUES('S2350','2','Aunque la tenaz muerte<br/>Lo quiso detener,<br/>Rompió Sus ataduras,<br/>¡Qué vencedor es Él!<br/>Ahora Él es mi vida,<br/>Ilimitado Él es,<br/>Y sobre toda prueba<br/>El vencedor es Él.<br/>',NULL,197551,3);
INSERT INTO stanza VALUES('S2350','3','Ni muerte, ni pecado,<br/>Ni el mundo tentador<br/>Hoy podrán derrotarnos,<br/>Jesús es vencedor.<br/>Si a cara descubierta<br/>Miramos al Señor,<br/>Amándole diremos:<br/>Tú eres el Vencedor.<br/>',NULL,197552,4);
INSERT INTO stanza VALUES('S2351','1','Padre santo te amamos<br/>Con todo nuestro ser.<br/>Tú nos diste a Tu Hijo,<br/>Simiente de mujer.<br/>Él para redimirnos<br/>En una cruz murió,<br/>Para hacernos hermanos,<br/>Muchos hijos de Dios.<br/>',NULL,197553,1);
INSERT INTO stanza VALUES('S2351','chorus','¡Aleluya! Padre te adoramos,<br/>Por siempre Tu nombre adoraré.<br/>Y yo le adoraré (Sí) Y yo le adoraré,<br/>Por siempre Su nombre adoraré.<br/>Y yo le adoraré (Sí) Y yo le adoraré,<br/>Por siempre Su nombre adoraré.<br/>',NULL,197554,2);
INSERT INTO stanza VALUES('S2351','2','Abba Padre clamamos<br/>En nuestro espíritu.<br/>Y como Tu morada,<br/>Somos Tu plenitud.<br/>Ya no somos extraños,<br/>Nuestro Padre eres Tú,<br/>Pues Tu vida divina<br/>Nos impartiste Tú.<br/>',NULL,197555,3);
INSERT INTO stanza VALUES('S2351','3','Hoy el Hijo te alaba<br/>En nuestro espíritu,<br/>Desborda en alabanzas<br/>Por Tu amor y virtud.<br/>Fue Tu plan de los siglos<br/>Tener Tu habitación,<br/>Testimonio, morada,<br/>Y eternal expresión.<br/>',NULL,197556,4);
INSERT INTO stanza VALUES('S2351','4','Hoy Padre te alabamos<br/>Con todo nuestro ser.<br/>Eres luz y justicia,<br/>Y santidad también.<br/>No hay palabras que puedan<br/>Tu gran amor mostrar,<br/>Pues el lenguaje humano<br/>No alcanza para más.<br/>',NULL,197557,5);
INSERT INTO stanza VALUES('S2352','1','Muerto estaba lejos de Ti;<br/>Sin Dios en el mundo,<br/>Ninguna esperanza aquí.<br/>Muerto en mi espíritu y también<br/>Mi mente enemiga<br/>Y mi cuerpo carne hoy es.<br/>En mi miseria vino Dios.<br/>Su encarnación es Su amor.<br/>En esa cruz Su vida dio,<br/>Disfrutó de Su salvación.<br/>',NULL,197558,1);
INSERT INTO stanza VALUES('S2352','chorus','Que misericordia me alcanzó.<br/>Necesito Su salvación.<br/>No importándole mi condición,<br/>Disfruto de Su salvación.<br/>',NULL,197559,2);
INSERT INTO stanza VALUES('S2352','2','Hoy por Tu muerte puedo vivir.<br/>Tu preciosa sangre<br/>Me trajo de vuelta a Ti.<br/>Tu liberaste al resucitar<br/>La vida divina<br/>Que me puede regenerar.<br/>Hasta mi alma transformar,<br/>Mi cuerpo glorificar.<br/>¡Imparte más Tu vida en mí,<br/>Completa hoy Tu salvación!<br/>',NULL,197560,3);
INSERT INTO stanza VALUES('S2352','chorus','Cada día quiero amarte más,<br/>Disfrutar de Tu salvación.<br/>Tomo toda oportunidad,<br/>Completa hoy Tu salvación.<br/>',NULL,197561,4);
INSERT INTO stanza VALUES('S2353','1','¡Venid y volvamos a Jehová!<br/>Pues Él nos ha desgarrado, mas nos curará;<br/>Nos ha herido,‿pero nos vendará.<br/>Después de dos días nos hará revivir;<br/>Al tercer día nos levantará, y<br/>Viviremos en Su presencia.<br/>Al tercer día nos levantará, y<br/>Viviremos en Su presencia.<br/>',NULL,197562,1);
INSERT INTO stanza VALUES('S2353','2','Conozcamos; prosigamos en conocer a Jehová.<br/>Conozcamos; prosigamos en conocer a Jehová.<br/>Cierta como‿el alba Su salida es;<br/>Él vendrá‿a nosotros como la lluvia,<br/>Como la lluvia tardía que<br/>Riega la tierra.<br/>¡Prosigamos en conocer a Jehová!<br/>',NULL,197563,2);
INSERT INTO stanza VALUES('S2354','1','Mas, nosotros todos,<br/>A cara descubierta<br/>Mirando y reflejando<br/>Como un espejo<br/>La gloria del Señor,<br/>Somos transformados<br/>De gloria en gloria en la misma imagen,<br/>Como por el Señor,<br/>Señor Espíritu.<br/>De gloria en gloria.<br/>',NULL,197564,1);
INSERT INTO stanza VALUES('S2355','1','La economía divina es el plan de Dios,<br/>El cual consiste en impartir<br/>A Cristo a Sus escogidos<br/>A fin de producir, constituir y edificar<br/>El Cuerpo orgánico de Cristo.<br/>',NULL,197565,1);
INSERT INTO stanza VALUES('S2355','2','La unidad única del Cuerpo de Cristo<br/>Es la unidad del Espíritu<br/>(la unidad del Espíritu),<br/>La mezcla del Dios Triuno procesado<br/>Y todos los creyentes (los creyentes) en Cristo.<br/>',NULL,197566,2);
INSERT INTO stanza VALUES('S2355','chorus','Los vencedores ven el Cuerpo,<br/>Conocen el Cuerpo,<br/>Se preocupan por el Cuerpo,<br/>Honran el Cuerpo,<br/>Realizan la obra del Cuerpo<br/>Y guardan cada uno<br/>De los principios del Cuerpo.<br/>',NULL,197567,3);
INSERT INTO stanza VALUES('S2355','3','Los vencedores viven la Nueva Jerusalén<br/>Y la llevan a cabo mediante la mezcla<br/>De Dios con el hombre<br/>Para la unidad del Cuerpo de Cristo<br/>Del Cuerpo de Cristo.<br/>',NULL,197568,4);
INSERT INTO stanza VALUES('S2356','1','Y si Mi pueblo<br/>Que se llama por Mi nombre<br/>Se humillare, orare y Me buscare.<br/>',NULL,197569,1);
INSERT INTO stanza VALUES('S2356','2','Y si Mi pueblo<br/>Que se llama por Mi nombre<br/>Se convirtiere, de sus caminos malos.<br/>',NULL,197570,2);
INSERT INTO stanza VALUES('S2356','chorus','Entonces, Yo oiré en los cielos<br/>Perdonaré sus pecados<br/>Y sanaré, y sanaré,<br/>A su tierra.<br/>Estarán abiertos Mis ojos<br/>Y atentos Mis oídos<br/>A la oración, que se hiciere<br/>En este lugar.<br/>',NULL,197571,3);
INSERT INTO stanza VALUES('S2357','1','Cristo es el Señor, hoy le damos gloria,<br/>Es quien nos reúne dentro de Su nombre,<br/>Dentro de Su persona.<br/>Él se procesó, se hizo accesible<br/>Para que le disfrutemos desde nuestro espíritu,<br/>Como Espíritu Viviente.<br/>Alaben Su nombre grande y tremendo,<br/>¡Oh, cuán rico! ¡Oh, cuán bueno!<br/>Disfrutemos al Señor nuestro Dios,<br/>En el hablar, con los santos<br/>En cada reunión.<br/>¡Oh, cuán rico! ¡Oh, cuán bueno!<br/>Disfrutemos al Señor nuestro Dios,<br/>Por las casas, con los santos<br/>En cada reunión.<br/>//Su vida tener<br/>De casa en casa, ¡Aleluya!<br/>Su deseo es, con Él uno somos.//<br/>',NULL,197572,1);
INSERT INTO stanza VALUES('S2358','1','// Quiero cantar una linda canción<br/>Para Aquel que mi vida cambió. //<br/>Es mi amigo Jesús, es mi amigo más fiel,<br/>Él es Dios, Él es Rey, es amor y verdad;<br/>Sólo en Él encontré esa paz que busqué,<br/>Sólo en Él encontré la felicidad.<br/>',NULL,197573,1);
INSERT INTO stanza VALUES('S2358','2','Cuando Jesús a mi vida llegó,<br/>Esa paz, ese amor encontré.<br/>Quiero que sepas que tú también<br/>Puedes encontrar esa paz.<br/>Si creyeres en Él, si confiares también,<br/>Como yo, cantarás, esta linda canción<br/>Y con Él reinarás por la eternidad.<br/>',NULL,197574,2);
INSERT INTO stanza VALUES('S2359','1','Es la vida de la iglesia un disfrute para mí,<br/>En ella encuentro gozo y unidad soy tan feliz.<br/>Mi vida diariamente encomiendo más y más,<br/>Mi corazón, mi ser entero llenos son de paz.<br/>',NULL,197575,1);
INSERT INTO stanza VALUES('S2359','chorus','La vida de la iglesia es todo para mí,<br/>En ella encuentro gozo y unidad soy tan feliz.<br/>',NULL,197576,2);
INSERT INTO stanza VALUES('S2359','2','Es aquí donde se encuentra plena salvación y paz,<br/>Mi espíritu responde no saldré de aquí jamás.<br/>Con los hermanos siempre disfrutando comunión,<br/>Es un gozo inefable y de grande bendición.<br/>',NULL,197577,3);
INSERT INTO stanza VALUES('S2359','3','Que alegría es la iglesia para mi Cristo Jesús.<br/>Por ella dio Su vida al sufrir allí en la cruz.<br/>Ahora por Su Espíritu en nosotros Él tendrá<br/>Gloriosa expresión visible todos la verán.<br/>',NULL,197578,4);
INSERT INTO stanza VALUES('S2360','1','Señor por Tu gracia estamos aquí,<br/>Aunque la corriente fuerte es.<br/>Los cielos abiertos están ¡Gloria a Dios!<br/>En Tu presencia entramos Señor<br/>Para saturados ser por Ti.<br/>Con Tu fuego queremos arder,<br/>Carbones ardientes queremos ser<br/>Y servirte en coordinación.<br/>',NULL,197579,1);
INSERT INTO stanza VALUES('S2360','2','Ocultos bajo Tus alas estar,<br/>Hoy has Tu hogar en nuestro ser;<br/>Pues en Tu presencia deseamos morar,<br/>Y de Tu gran rueda ser parte Señor.<br/>Que venga Tu reino es nuestro clamor,<br/>Gana más en nuestro corazón,<br/>Llenos de Tu vida en nuestro interior,<br/>Hasta Tu plenitud alcanzar.<br/>',NULL,197580,2);
INSERT INTO stanza VALUES('S2360','3','Tocando las alas, en coordinación,<br/>Al seguir Tu Espíritu en nuestro ser.<br/>Servirte librados de toda ambición,<br/>Que hoy sólo Tu vida se pueda ver.<br/>Ya no Babilonia ni más división,<br/>Que venga Tu reino Señor;<br/>Tú eres Cordero, eres Vencedor,<br/>Por siempre nuestro Salvador.<br/>',NULL,197581,3);
INSERT INTO stanza VALUES('S2360','4','Los cielos abiertos están ¡Gloria a Dios!<br/>Estás en el trono amado Señor,<br/>Guárdanos amándote en la comunión,<br/>Pues sólo abiertos queremos estar.<br/>Con todos los santos en coordinación,<br/>El fluir de vida aumentará.<br/>Más gracia impartida nos saturará,<br/>Hasta ser conformados a Ti.<br/>',NULL,197582,4);
INSERT INTO stanza VALUES('S2360','5','Como sacerdotes en coordinación,<br/>Tu arca hoy hemos de llevar<br/>Como testimonio de Tu realidad,<br/>Impartes Tu vida y nos llenas de Ti.<br/>Eres Dios y Hombre, eres el Señor;<br/>Tu gloria en Tus hijos está,<br/>Tu novia gloriosa espera por Ti,<br/>¡Oh Señor, ven pronto ya!<br/>',NULL,197583,5);
INSERT INTO stanza VALUES('S2361','1','Dios como el Espíritu<br/>Se extiende en mi ser.<br/>Mi espíritu, alma y cuerpo<br/>Dios está santificando,<br/>Por completo me preserva Él.<br/>Y el mismo Dios de paz<br/>Nos ha de santificar,<br/>Y el mismo Dios de paz<br/>Por completo lo hará.<br/>Nuestro espíritu y alma y cuerpo<br/>Por completo haz de preservar<br/>Santos y sin manchas en amor,<br/>Hasta que regrese nuestro Señor.<br/>',NULL,197584,1);
INSERT INTO stanza VALUES('S2362','1','//Pero si tardo,<br/>Escribo para que sepas<br/>Cómo uno debe conducirse<br/>En la casa de Dios//<br/>//Que es la iglesia del Dios viviente,<br/>Columna y fundamento de la verdad. //<br/>Columna y fundamento de la verdad<br/>',NULL,197585,1);
INSERT INTO stanza VALUES('S2363','1','¡Qué rico‿es Cristo en Su plenitud!<br/>Es buena tierra en Su extensión:<br/>No te‿alcanza‿el tiempo para recorrer<br/>Toda Su‿anchura y Su longitud.<br/>¿Quieres saber algo más?<br/>',NULL,197586,1);
INSERT INTO stanza VALUES('S2363','2','Es como‿el trigo que limitado es.<br/>Cuando cae en tierra, mucho fruto da;<br/>Puedes hacer de Él un delicioso pan.<br/>Para comerlo todos en unidad.<br/>¿Quieres comer algo más?<br/>',NULL,197587,2);
INSERT INTO stanza VALUES('S2363','3','Como cebada que‿ilimitada es,<br/>Que alimenta a más de cinco mil;<br/>Y sobran doce cestas para después.<br/>El que tenga hambre, venga para comer.<br/>¿Quieres comer algo más?<br/>',NULL,197588,3);
INSERT INTO stanza VALUES('S2363','4','Como las vides que buen vino dan,<br/>Es el disfrute del Señor Jesús.<br/>Él es el vino nuevo que nuevos goces da,<br/>Cuando le tomes, Él te‿alegrará.<br/>¿Quieres beber algo más?<br/>',NULL,197589,4);
INSERT INTO stanza VALUES('S2363','5','Entra‿y disfruta la tierra de Canaán,<br/>Muchas riquezas aquí encontrarás;<br/>Nada te faltará, saciado estarás,<br/>Nunca‿en tu vida escasez tendrás.<br/>¡Entra‿y saciado serás!<br/>',NULL,197590,5);
INSERT INTO stanza VALUES('S2363','6','Posee la tierra, experiméntala,<br/>Come y bebe y disfrútala;<br/>Los materiales se producirán,<br/>El edificio se levantará.<br/>¡Dios Su morada tendrá!<br/>',NULL,197591,6);
INSERT INTO stanza VALUES('S2364','1','//Y Yo también te digo,<br/>Que tú eres Pedro<br/>Y sobre esta roca //<br/>Edificaré, edificaré, edificaré Mi iglesia;<br/>Edificaré, edificaré, edificaré Mi iglesia;<br/>Y las puertas del Hades no prevalecerán<br/>Y las puertas del Hades no prevalecerán<br/>Contra ella.<br/>',NULL,197592,1);
INSERT INTO stanza VALUES('S2365','1','Señor, te amo a Ti.<br/>Y Tu palabra atesoro yo.<br/>Ven desvélame,<br/>Quiero ver Tu preciosidad.<br/>',NULL,197593,1);
INSERT INTO stanza VALUES('S2365','chorus','Señor me abro a Ti, despéjame,<br/>Mi lámpara se.<br/>Atráeme más a Tu amor y luz.<br/>',NULL,197594,2);
INSERT INTO stanza VALUES('S2365','2','Pura es Tu palabra,<br/>Santifica y purifica mi alma.<br/>Aquí me quedaré,<br/>En el gozo de Tu palabra.<br/>',NULL,197595,3);
INSERT INTO stanza VALUES('S2365','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/sen-or-te-amo-a-ti',NULL,197596,4);
INSERT INTO stanza VALUES('S2366','1','Permaneced en Mí y Yo en vosotros<br/>Y así fluye la vida que hay en Mí.<br/>Si guardamos Sus mandamientos<br/>En esto le amamos.<br/>',NULL,197597,1);
INSERT INTO stanza VALUES('S2366','chorus','Somos discípulos<br/>“Por tanto id y haced discípulos”<br/>Para la era cambiar.<br/>',NULL,197598,2);
INSERT INTO stanza VALUES('S2366','2','Que os améis unos a otros<br/>Como Yo os he amado;<br/>Somos entretejidos juntos<br/>Para Su novia preparar.<br/>',NULL,197599,3);
INSERT INTO stanza VALUES('S2366','3','No me escogisteis vosotros a Mí<br/>Sino que Yo a vosotros escogí<br/>A llevar fruto que permanezca;<br/>Glorificamos al Padre.<br/>',NULL,197600,4);
INSERT INTO stanza VALUES('S2366','4','Yo soy la vid y vosotros los pámpanos,<br/>Llevando frutos que permanezcan.<br/>Somos discípulos que se aman<br/>Permaneciendo en la verdad.<br/>',NULL,197601,5);
INSERT INTO stanza VALUES('S2367','1','¡Oh, aleluya! ¡Fue en la cruz<br/>Tal muerte de Jesús!<br/>No solo El allí expiró,<br/>También la muerte terminó!<br/>Dios mismo se ofreció—<br/>Y al hombre El incluyó!<br/>¡Oh, aleluya por esa cruz!<br/>',NULL,197602,1);
INSERT INTO stanza VALUES('S2367','2','¡Gloria al Señor! El hombre en Dios<br/>Murió, y su fin halló.<br/>Del viejo hombre libre soy,<br/>Pues Dios mismo lo terminó;<br/>¡Qué muerte sin igual!<br/>¡Qué acto celestial!<br/>¡Oh, aleluya, por tal final!<br/>',NULL,197603,2);
INSERT INTO stanza VALUES('S2367','3','Dios en el hombre se_encarnó,<br/>Su gloria se escondió.<br/>El grano en tierra que cayó,<br/>La vida de Dios liberó.<br/>Son muchos granos con<br/>La vida de Dios hoy.<br/>Oh, aleluya, por Su expresión.<br/>',NULL,197604,3);
INSERT INTO stanza VALUES('S2367','4','¡Gloria! Por Su muerte_en la cruz,<br/>Que todo lo abarcó!<br/>Del universo el centro es,<br/>Ella tiene eternal valor.<br/>Amamos hoy Tu cruz,<br/>Amamos hoy Tu cruz!<br/>¡Oh aleluya, por ésta cruz!<br/>',NULL,197605,4);
INSERT INTO stanza VALUES('S2368','1','A Jesús todo debo contarle,<br/>¡Mis cargas solo,_no puedo llevar!<br/>¡En mi angustia Él me socorre!<br/>¡Los Suyos ama y cuida también!<br/>',NULL,197606,1);
INSERT INTO stanza VALUES('S2368','chorus','¡A Jesús todo debo contarle!<br/>¡Mis cargas solo no puedo llevar!<br/>¡A Jesús todo debo contarle!<br/>¡Solo Jesús me puede ayudar!<br/>',NULL,197607,2);
INSERT INTO stanza VALUES('S2368','2','A Jesús cuento yo mis problemas;<br/>Es compasivo, Amigo gentil,<br/>Si yo le pido, Él me libera,<br/>¡Y en mi angustia conmigọ estará!<br/>',NULL,197608,3);
INSERT INTO stanza VALUES('S2368','3','A Jesús todo puedo contarle,<br/>Al pasar por pruebas y tentación;<br/>Toda preocupación y lamento<br/>Comparte conmigo, mi Salvador.<br/>',NULL,197609,4);
INSERT INTO stanza VALUES('S2368','4','Cuando el mundọ al mal me atrae,<br/>Y cuando soy tentado a pecar,<br/>A Jesús cuento y me capacita<br/>Para el mundo poder vencer.<br/>',NULL,197610,5);
INSERT INTO stanza VALUES('S2369','1','Señor, haz que Tu sangre<br/>Me limpie de mi mal,<br/>Que Tu Espíritu Santo<br/>Me unja sin cesar.<br/>Confieso que muy pobre<br/>Es mi servicio a Ti,<br/>Pero si Tú me llenas<br/>Por Ti podré vivir.<br/>',NULL,197611,1);
INSERT INTO stanza VALUES('S2369','chorus','Oh, líbrame de mi ego,<br/>De su miseria vil,<br/>Para que así por siempre<br/>Yo lleno esté de Ti.<br/>',NULL,197612,2);
INSERT INTO stanza VALUES('S2369','2','Por Ti añora y clama<br/>Mi seco corazón;<br/>Te ruego que me llene<br/>Tu Espíritu Señor.<br/>En Ti, la Peña hendida,<br/>Me quiero refugiar;<br/>Derrama el agua viva<br/>Hasta mi sed saciar.<br/>',NULL,197613,3);
INSERT INTO stanza VALUES('S2369','3','Mi corazón es frío;<br/>Rehúsa obedecer;<br/>Tu Espíritu me llene,<br/>Rebelde no seré.<br/>Sobre Tu altar me pongo<br/>Y no me moveré;<br/>Consuma hoy Tu fuego,<br/>Señor, todo mi ser.<br/>',NULL,197614,4);
INSERT INTO stanza VALUES('S2369','4','Oh, que Tu cruz por dentro<br/>Muy hondo arda en mí;<br/>Ensancha Tu medida;<br/>Cenizas hazme al fin.<br/>Tu Espíritu me llene<br/>Hoy mucho más que ayer,<br/>Para que el agua viva<br/>Por mí puedas verter.<br/>',NULL,197615,5);
INSERT INTO stanza VALUES('S2370','1','Te doy mi corazón,<br/>Oh, Cristo, Amado mío,<br/>A cambio de Tu corazón<br/>Tú hiciste arder el mío.<br/>Los corazones tocas<br/>Y solo Tú los amas,<br/>Te amaré como me amaste,<br/>Oh, Cristo, Amado mío.<br/>',NULL,197616,1);
INSERT INTO stanza VALUES('S2370','2','Qué te puedo ofrecer<br/>Por tal amor, Señor,<br/>Te humillaste para ser<br/>Un hombre como yo,<br/>‘‘Dame tu corazón’’:<br/>Mi corazón ganaste,<br/>Te amaré como me amaste,<br/>Oh, Cristo, Amado mío.<br/>',NULL,197617,2);
INSERT INTO stanza VALUES('S2370','3','Abres Tu corazón;<br/>Todo Tu amor ofreces,<br/>Quiero en Ti permanecer<br/>Dentro de Ti esconderme.<br/>Que arda en mí Tu amor,<br/>Hasta que vuelva a amarte.<br/>Te amaré como me amaste,<br/>Oh, Cristo, Amado mío.<br/>',NULL,197618,3);
INSERT INTO stanza VALUES('S2370','4','Mi corazón en Ti<br/>Halló reposo eterno,<br/>Tu fuerte amor lo guarde aquí:<br/>La Roca herida, Cristo.<br/>Ciñes mi corazón,<br/>Le das refugio en Ti;<br/>Te amaré como me amaste,<br/>Oh, Cristo, Amado mío.<br/>',NULL,197619,4);
INSERT INTO stanza VALUES('S2370','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/te-doy-mi-corazo-n-oh-cristo-2',NULL,197620,5);
INSERT INTO stanza VALUES('S2371','1','Cuando llegué aquí, todo era nuevo,<br/>De Alguien hablaban, de un tal Jesús;<br/>Cosas que nunca había yo_oído,<br/>Sensación nueva, brilló_una luz.<br/>Toda mi angustia y pena atrás quedó;<br/>Dejé inconsciente toda la esclavitud.<br/>Mi corazón vio tal rostros puros,<br/>"Dios está aquí", mi_alma entendió.<br/>',NULL,197621,1);
INSERT INTO stanza VALUES('S2371','2','Decían que Dios, Él, quería habitarme,<br/>Entrar en mi, si Lo dejo entrar.<br/>Jamás lo vi, no Lo conocía,<br/>Pero algo en mí_empezó_a clamar.<br/>Con alma abierta, sincero corazón,<br/>Dije:_ “¡Señor Jesús, ven y sálvame!”<br/>No hay otro Nombre tan dulce y tierno;<br/>Entró en mi ser, ¡cuán real es Él!<br/>',NULL,197622,2);
INSERT INTO stanza VALUES('S2371','3','Cesó mi carga, hallé descanso;<br/>Ya no hay condena: libre yo soy.<br/>Unido a Cristo, mi vida eterna,<br/>Por fe yo vivo, confío en Dios.<br/>En Él me gozo, Él es mi canto,<br/>Mi nueva vida, hoy me glorio en Él.<br/>Esta es mi historia: ¡Salvación plena!<br/>¡Eterno amor, dulce canción!<br/>',NULL,197623,3);
INSERT INTO stanza VALUES('S2371','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2371_cuando-llegue-aqui-todo',NULL,197624,4);
INSERT INTO stanza VALUES('S2372','1','Acercándoos a Él,<br/>Piedra viva, Piedra viva,<br/>Desechada por los hombres,<br/>Mas para Dios<br/>Escogida y preciosa;<br/>Vosotros también,<br/>Como piedras vivas,<br/>Sois edificados<br/>Como casa espiritual<br/>Hasta ser un sacerdocio santo,<br/>Para ofrecer<br/>Sacrificios espirituales<br/>Aceptables a Dios,<br/>Por medio de Jesucristo,<br/>Aceptables a Dios,<br/>Por medio de Jesucristo.<br/>',NULL,197625,1);
INSERT INTO stanza VALUES('S2372','SoundCloud Link','https://soundcloud.com/user-330220130/1-pedro-2-4-5',NULL,197626,2);
INSERT INTO stanza VALUES('S2373','1','Aunque todo sea difícil a mi alrededor,<br/>Días llenos de luchas que no puedo vencer;<br/>Cuando soy débil puedo experimentar<br/>El poder de Cristo en mi debilidad.<br/>',NULL,197627,1);
INSERT INTO stanza VALUES('S2373','chorus','Me ha dicho, me ha dicho:<br/>Bástate Mi gracia;<br/>Porque Mi poder se perfecciona<br/>En la debilidad.<br/>',NULL,197628,2);
INSERT INTO stanza VALUES('S2373','2','Reducido a nada es que debo ser;<br/>Cristo como mi todo manifestado es.<br/>Que en mi espíritu viva solo por El<br/>Y como la gracia sea todo Él.<br/>',NULL,197629,3);
INSERT INTO stanza VALUES('S2373','SoundCloud Link','https://soundcloud.com/damarisleg/bastate-mi-gracia',NULL,197630,4);
INSERT INTO stanza VALUES('S2374','1','Dios que nunca cambias,<br/>Tu amor al hombre das;<br/>Mi vida yo consagro<br/>Para cumplir Tu plan.<br/>En silencio espero<br/>Tu suave voz oír<br/>Mi espíritu inspira<br/>Atráeme hacia Ti.<br/>',NULL,197631,1);
INSERT INTO stanza VALUES('S2374','chorus','Oh, Dios,<br/>Todo es posible para Ti;<br/>Desde hoy yo Te permito<br/>Que obres en mí,<br/>Por mí, obtén todo en mí.<br/>',NULL,197632,2);
INSERT INTO stanza VALUES('S2374','2','Oyendo Tu palabra,<br/>Siguiendo Tu guiar,<br/>Hoy llena de sentido<br/>Mi vida ha de estar.<br/>Lo que_era antes ganancia<br/>Pérdida ahora es,<br/>Cristo es mi centro,<br/>El precio pagaré.<br/>',NULL,197633,3);
INSERT INTO stanza VALUES('S2374','chorus','Oh, Dios,<br/>Todo es posible para Ti;<br/>Desde hoy yo Te permito<br/>Que obres en mí,<br/>Por mí, obtén todo en mí.<br/>',NULL,197634,4);
INSERT INTO stanza VALUES('S2374','note','**[Puente:]**<br/>El hombre traza su camino,<br/>Mas Jehová guía sus pasos.<br/>Tus sendas seguiré,<br/>No temo, proseguiré.<br/>',NULL,197635,5);
INSERT INTO stanza VALUES('S2374','chorus','Oh, Dios,<br/>Todo es posible para Ti;<br/>Desde hoy yo Te permito<br/>Que obres en mí,<br/>Por mí, obtén todo en mí.<br/>',NULL,197636,6);
INSERT INTO stanza VALUES('S2374','SoundCloud Link','https://soundcloud.com/dani-b-313753210/desde-hoy-traduccion-provisional-from-this-day-on',NULL,197637,7);
INSERT INTO stanza VALUES('S2375','1','Gracia es Dios en Cristo,<br/>Cristo es el Espíritu;<br/>Disfruto todo lo que Él es,<br/>Se forja en nosotros,<br/>El Todo-suficiente,<br/>Constituye nuestro ser.<br/>',NULL,197638,1);
INSERT INTO stanza VALUES('S2375','chorus','Por la gracia de Dios,<br/>Soy lo que soy;<br/>Y Su gracia conmigo,<br/>No ha sido en vano.<br/>',NULL,197639,2);
INSERT INTO stanza VALUES('S2375','2','Somos Sus llamados<br/>Hoy en la iglesia,<br/>El verdadero monte Sion.<br/>Aquí Él nos riega,<br/>Refresca y transforma,<br/>Vida para siempre da.<br/>',NULL,197640,3);
INSERT INTO stanza VALUES('S2375','3','La abundante gracia,<br/>Es para la iglesia<br/>Y hoy la podemos ver.<br/>La gracia perfecciona,<br/>Confirma, fortalece,<br/>Cimienta y nos sostiene.<br/>',NULL,197641,4);
INSERT INTO stanza VALUES('S2375','SoundCloud Link','https://soundcloud.com/damarisleg/por-la-gracia-de-dios',NULL,197642,5);
INSERT INTO stanza VALUES('S2376','1','Hombre mortal, frágil soy,<br/>Veo en mí, vanidad.<br/>Mucho tiempo he estado aquí,<br/>//Quiero en mi espíritu entrar.//<br/>',NULL,197643,1);
INSERT INTO stanza VALUES('S2376','2','Abro mi boca: ¡oh Jesús!<br/>Te toco en mi espíritu;<br/>Abundante suministro me das,<br/>//Tu ser me infundirás. //<br/>',NULL,197644,2);
INSERT INTO stanza VALUES('S2376','3','Tomo el Espíritu en Tu palabra,<br/>Para renovado ser;<br/>Tú me transformas, infúndete más,<br/>//Para Tu Cuerpo obtener. //<br/>',NULL,197645,3);
INSERT INTO stanza VALUES('S2376','4','Ao cooperar com o Espír´to,<br/>Edificado serei.<br/>Entrelaçados no Corpo em amor,<br/>//Te expressamos, Senhor. //<br/>',NULL,197646,4);
INSERT INTO stanza VALUES('S2376','5','En mi espíritu puedo ver,<br/>Tu máxima intención,<br/>Corporativa y eterna expresión,<br/>La Nueva Jerusalén,<br/>Corporativa y eterna expresión,<br/>La Nueva Jerusalén,<br/>La Nueva Jerusalén.<br/>',NULL,197647,5);
INSERT INTO stanza VALUES('S2376','SoundCloud Link','https://soundcloud.com/ana-maria-ojeda-348828022/himno-de-graduacion-etc-c-2024_2-experiencia-de-cristo-como-el-espiritu',NULL,197648,6);
INSERT INTO stanza VALUES('S2377','1','Todo lo que hagamos, día tras día,<br/>Nos debería recordar,<br/>A Cristo como la realidad<br/>De aquello que hacemos.<br/>Si seguimos la práctica de tomar a Cristo<br/>Como la realidad de<br/>Todas las cosas materiales<br/>En nuestra vida diaria,<br/>Nuestro diario andar será revolucionado,<br/>Nuestro diario andar será transformado,<br/>Y seremos llenos de Cristo,<br/>Y seremos llenos de Cristo.<br/>',NULL,197649,1);
INSERT INTO stanza VALUES('S2378','1','En Betel Jacob vio la visión en sueños,<br/>En el monte recibió Moisés visiones,<br/>La visión del templo santo vio David,<br/>La casa vio_Ezequiel como visión.<br/>',NULL,197650,1);
INSERT INTO stanza VALUES('S2378','chorus','Juan vio…<br/>La visión de la Nueva Jerusalén,<br/>Que_es Dios…<br/>En ti, edificado bien.<br/>Necesitamos recibir una visión,<br/>Y para lograrlo nos abrimos al Señor<br/>Yendo_a nuestro_espíritu<br/>Para_edificación;<br/>La_iglesia es la plenitud de Dios.<br/>(Efesios uno veintitrés)<br/>',NULL,197651,2);
INSERT INTO stanza VALUES('S2378','2','Zacarías vio visión de Su recobro,<br/>Daniel tuvo la visión del Victorioso,<br/>Pablo_y Pedro vieron la visión del Cuerpo,<br/>Trayendo_a la visión completación.<br/>',NULL,197652,3);
INSERT INTO stanza VALUES('S2378','SoundCloud Link','https://soundcloud.com/user-290074669/ultima-manifestacion-jh',NULL,197653,4);
INSERT INTO stanza VALUES('S2379','1','Por medio de Tu palabra, Señor,<br/>La iglesia es edificada,<br/>Nos reunimos y ganamos de Ti,<br/>Palabra de vida sin fin.<br/>',NULL,197654,1);
INSERT INTO stanza VALUES('S2379','chorus','Tu palabra es Señor,<br/>Más profunda que el mar,<br/>Pero está a nuestro alcance,<br/>Gracias, Señor.<br/>',NULL,197655,2);
INSERT INTO stanza VALUES('S2379','2','Como un almacén, Tu palabra es;<br/>Está llena de Provisiones,<br/>Y todo aquel que busque en él,<br/>Su gloria podrá compartir.<br/>',NULL,197656,3);
INSERT INTO stanza VALUES('S2379','chorus','Más queremos comer,<br/>Más queremos beber.<br/>Tu palabra es muy rica,<br/>Gracias, Señor.<br/>',NULL,197657,4);
INSERT INTO stanza VALUES('S2379','3','Enséñanos la Palabra, Señor,<br/>E impártenos sabiduría<br/>En simplicidad, queremos llegar<br/>Al centro de Tu corazón.<br/>',NULL,197658,5);
INSERT INTO stanza VALUES('S2379','chorus','Tu palabra es Señor,<br/>Más profunda que el mar,<br/>Pero está a nuestro alcance,<br/>Gracias, Señor.<br/>',NULL,197659,6);
INSERT INTO stanza VALUES('S2379','SoundCloud Link','https://soundcloud.com/terapeuta-ocupacional-joel-martinez/por-medio-de-tu-palabra-senor',NULL,197660,7);
INSERT INTO stanza VALUES('S2380','1','La vida eterna fue manifestada<br/>La hemos oído y visto también, sí;<br/>Testificamos y os comunicamos<br/>Sólo esta vida que eterna es.<br/>',NULL,197661,1);
INSERT INTO stanza VALUES('S2380','chorus','Dile tú así: Quiero más, quiero más.<br/>Quiero más de Cristo,<br/>Más de Su vida en mi ser.<br/>Dile tú así: Quiero más, quiero más.<br/>Quiero más de Cristo,<br/>Más de Su vida en mi ser.<br/>',NULL,197662,2);
INSERT INTO stanza VALUES('S2380','2','La vida eterna en el Padre estaba,<br/>Desde el principio la fuente es Él, sí;<br/>Nos fue revelada, también impartida<br/>Y nos introdujo en comunión.<br/>',NULL,197663,3);
INSERT INTO stanza VALUES('S2380','3','La vida eterna es tan divina,<br/>No sólo es perpetua,<br/>Es mucho más, sí;<br/>Es absolutamente completa,<br/>Ilimitada, perfecta es.<br/>',NULL,197664,4);
INSERT INTO stanza VALUES('S2380','SoundCloud Link','https://soundcloud.com/user-889434062/la-vida-eterna-fue-manifestada',NULL,197665,5);
INSERT INTO stanza VALUES('S2381','1','Mi única meta eres Tú,<br/>Mi esperanza,<br/>¡Sólo me importas Tú!<br/>No puedo reemplazarte,<br/>Y no quisiera hacerlo.<br/>Tengo todo hoy<br/>¡Te tengo a Ti!<br/>',NULL,197666,1);
INSERT INTO stanza VALUES('S2381','2','Sólo vivo para Ti<br/>Señor, ¡Nada más!<br/>Mi fuente en todo Tú;<br/>Ya no más bien o mal,<br/>Ni buenas intenciones,<br/>Ni una “buena” vida,<br/>¡Te quiero a Ti!.<br/>',NULL,197667,2);
INSERT INTO stanza VALUES('S2381','SoundCloud Link','https://soundcloud.com/dani-b-313753210/lord-you-are-my-only-goal-traduccion-provisional',NULL,197668,3);
INSERT INTO stanza VALUES('S2382','1','Por Tu dulce amor<br/>Te alabamos, oh Señor,<br/>Vemos hoy todo Tu cuidar,<br/>Tu cuidar.<br/>Antes sin discernir,<br/>Hoy podemos percibir<br/>Que oculto estabas Tú.<br/>',NULL,197669,1);
INSERT INTO stanza VALUES('S2382','chorus','Insondables,<br/>Señor son Tus juicios,<br/>Tus caminos,<br/>¿Quién conocerá?<br/>Elevados, Señor,<br/>Tus pensamientos,<br/>Te adoramos solo a Ti.<br/>',NULL,197670,2);
INSERT INTO stanza VALUES('S2382','2','Bueno eres, Señor,<br/>Para quien espera en Ti,<br/>Esperando te ganamos más,<br/>Más de Ti<br/>Eres nuestra porción,<br/>Al mezclarnos más y más,<br/>Oh, qué gracia es ganarte así.<br/>',NULL,197671,3);
INSERT INTO stanza VALUES('S2382','3','Vamos a colocar<br/>Todo sobre Tu altar,<br/>Damos nuestro futuro a Ti,<br/>Si a Ti.<br/>Sea Tu sonreír<br/>Para nos un mapa aquí,<br/>En el viaje acompáñanos.<br/>',NULL,197672,4);
INSERT INTO stanza VALUES('S2382','4','Es por Ti, oh Señor,<br/>Para Tu buen placer,<br/>Nos rendimos totalmente a Ti,<br/>Sí a Ti.<br/>Al cumplir Tu querer<br/>Y uno contigo ser,<br/>Anhelamos: Ven, Señor Jesús.<br/>',NULL,197673,5);
INSERT INTO stanza VALUES('S2382','SoundCloud Link','https://soundcloud.com/user-19296523/por-tu-dulce-amor-melodia',NULL,197674,6);
INSERT INTO stanza VALUES('S2383','1','Porque si siendo enemigos,<br/>Fuimos reconciliados con Dios<br/>Por la muerte de Su Hijo,<br/>Mucho más, estando<br/>Reconciliados, seremos<br/>Salvos en Su vida.<br/>Y no solo esto, sino que<br/>También nos gloriamos en Dios<br/>Por medio de Jesucristo,<br/>Por quien hemos recibido<br/>Ahora la reconciliación.<br/>',NULL,197675,1);
INSERT INTO stanza VALUES('S2383','SoundCloud Link','https://soundcloud.com/jovenesudamerica/romanos-510-11-ev-paraguay-2019',NULL,197676,2);
INSERT INTO stanza VALUES('S2384','1','Señor Te amo,<br/>Toma mi corazón,<br/>Satura y llena<br/>Con Tu vida divina cada parte.<br/>Señor todo a Ti lo rindo hoy.<br/>Mantenme volviendo a Ti en el día,<br/>Hasta que te exprese sólo a Ti siempre,<br/>Hasta que te exprese sólo a Ti.<br/>',NULL,197677,1);
INSERT INTO stanza VALUES('S2384','SoundCloud Link','https://soundcloud.com/clara-orjuela-78079798/senor-te-amo-toma-mi-corazon',NULL,197678,2);
INSERT INTO stanza VALUES('S2385','1','Si ya todo lo_has perdido,<br/>Si te sientes oprimido,<br/>Hay un don de gracia para_aquel<br/>Que cree;<br/>No te pongas requisitos,<br/>Su perdón es infinito,<br/>Él limpió ya tu delito,<br/>¡Sólo cree!<br/>',NULL,197679,1);
INSERT INTO stanza VALUES('S2385','chorus','Sale el sol en tu_horizonte— ¡Libertad!<br/>Ya se anuncia_el evangelio— ¡Sólo cree!<br/>La palabra que esperabas,<br/>El regalo que anhelabas,<br/>La alegría que soñabas—<br/>Libre sé...<br/>Para disfrutar,<br/>La gracia del Señor,<br/>Sólo disfrutar,<br/>Su rostro contemplar,<br/>¡En la libertad! ¡Cree en Él!<br/>¡Libre sé! ¡Jubileo es!<br/>',NULL,197680,2);
INSERT INTO stanza VALUES('S2385','2','En Sus palabras de gracia<br/>Nada falta ni escasea,<br/>No hay molestias, miedo, ira,<br/>O_ansiedad.<br/>En el jubileo de gracia,<br/>Nuestras deudas son borradas,<br/>¡Qué felicidad, qué gozo, qué bondad!<br/>',NULL,197681,3);
INSERT INTO stanza VALUES('S2385','3','Cuando Cristo nos atrae,<br/>Cuando_Él solo satisface,<br/>Nuestro Jubileo_entonces Cristo es;<br/>Hay satisfacción, reposo,<br/>Libertad, consuelo_y gozo,<br/>¡Disfrutando las riquezas del Señor!<br/>',NULL,197682,4);
INSERT INTO stanza VALUES('S2385','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/libertad-jubilee',NULL,197683,5);
INSERT INTO stanza VALUES('S2386','1','Desde_antes de la fundación,<br/>Una novia anhelabas,<br/>Morada mutua,<br/>Glorioso plan;<br/>Juntos por siempre estar.<br/>',NULL,197684,1);
INSERT INTO stanza VALUES('S2386','2','Y yo sin conocer<br/>Lo que había en Ti,<br/>Pequé_y debía morir,<br/>Más salvo fui.<br/>Te acercaste y me<br/>Diste Tu vida;<br/>¡Oh qué_amor!<br/>Por siempre contigo uno seré.<br/>',NULL,197685,2);
INSERT INTO stanza VALUES('S2386','3','Oh ¡qué glorioso amor!<br/>¿Cómo entender?<br/>Más alto que el cielo,<br/>Profundo cual mar;<br/>La muerte anuló,<br/>También a Satán;<br/>Nada se compara<br/>Con Tu_amor por mí.<br/>¡Profundo y tan real!<br/>¡Ferviente y gentil!<br/>Me atraes así.<br/>',NULL,197686,3);
INSERT INTO stanza VALUES('S2386','4','Te ofrezco mi vida<br/>Y mi corazón,<br/>Venga sufrimiento<br/>O satisfacción.<br/>Por Tu gracia hoy<br/>Todo entrego yo,<br/>Para Tu iglesia-Novia edificar,<br/>Morada mutua seremos así,<br/>Señor, por la eternidad.<br/>',NULL,197687,4);
INSERT INTO stanza VALUES('S2387','1','Si en mi ego estoy pienso que soy mejor que los demás,<br/>Pero lo que yo no veo es que mi ego es tan fuerte en mí.<br/>Ya no quiero pensar que soy mejor que los demás,<br/>Señor, líbrame de mi ego, solo por Tu gracia quiero estar.<br/>',NULL,197688,1);
INSERT INTO stanza VALUES('S2387','chorus','Solo por Tu gracia quiero crecer<br/>Nada de mí Tú quieres, Señor.<br/>Solo por Tu gracia quiero crecer,<br/>Nada de mí Tú quieres, Señor.<br/>',NULL,197689,2);
INSERT INTO stanza VALUES('S2387','2','Señor, si yo pienso que soy mejor que los demás,<br/>Hazme recordar que por Tu gracia es que estoy en pie,<br/>Y tal como Pedro pienso: No te negaré jamás<br/>Señor, haz que escuche al gallo cantar para poder llorar.<br/>',NULL,197690,3);
INSERT INTO stanza VALUES('S2387','3','Señor, ahora sé que por Tu gracia estoy en pie,<br/>Solo en Ti confiaré, porque Tú eres la gracia en mí,<br/>Tú sabes todo, Señor, no podré escapar de Ti,<br/>Por eso en Tu palabra confiaré, te seguiré hasta el fin.<br/>',NULL,197691,4);
INSERT INTO stanza VALUES('S2387','SoundCloud Link','https://soundcloud.com/damarisleg/solo-por-tu-gracia',NULL,197692,5);
INSERT INTO stanza VALUES('S2388','1','Una gavilla‿erguida soy.<br/>Brillando como‿estrella voy.<br/>Mis sueños me revelarán,<br/>Como‿obtener mi libertad.<br/>',NULL,197693,1);
INSERT INTO stanza VALUES('S2388','chorus','Soy un “soñador”,<br/>Y vivo por_esta visión,<br/>En mí Cristo_está,<br/>Viviente resplandecerá.<br/>',NULL,197694,2);
INSERT INTO stanza VALUES('S2388','2','Muchos caerán y pecarán,<br/>Pero ya Dios los escogió.<br/>No estoy aquí para juzgar,<br/>Sino para pastorear.<br/>',NULL,197695,3);
INSERT INTO stanza VALUES('S2388','chorus','Soy un “soñador”,<br/>Y vivo por_esta visión,<br/>En mí Cristo_está,<br/>Viviente resplandecerá.<br/>',NULL,197696,4);
INSERT INTO stanza VALUES('S2388','3','Cerca de mí el mundo está.<br/>A diario me‿incita‿a pecar.<br/>Pero con otros huiré,<br/>Sobre el pecado reinaré.<br/>',NULL,197697,5);
INSERT INTO stanza VALUES('S2388','chorus','¡El sueño ya vi!<br/>Yo vivo_en Cristo_y Cristo_en mí.<br/>¡Su_hablar yo creí!<br/>Visión real que reina_en mí.<br/>',NULL,197698,6);
INSERT INTO stanza VALUES('S2388','4','El mundo no me‿atrapará,<br/>Pues tengo un Cristo que ganar.<br/>Con gracia hoy me‿entrenará,<br/>Para después con El reinar.<br/>',NULL,197699,7);
INSERT INTO stanza VALUES('S2388','chorus','Soy un “soñador”,<br/>Y vivo por_esta visión,<br/>En mí Cristo_está,<br/>Viviente resplandecerá.<br/>',NULL,197700,8);
INSERT INTO stanza VALUES('S2388','chorus','¡El sueño ya vi!<br/>Yo vivo_en Cristo_y Cristo_en mí.<br/>¡Su_hablar yo creí!<br/>Visión real que reina_en mí.<br/>',NULL,197701,9);
INSERT INTO stanza VALUES('S2388','SoundCloud Link','https://soundcloud.com/santigabri14/soy-un-sonador-a-master-of',NULL,197702,10);
INSERT INTO stanza VALUES('S2389','1','//En mi corazón he atesorado<br/>Tu palabra<br/>Para no pecar contra Ti//<br/>// ¡Oh, cuánto amo yo Tu ley! //<br/>Todo el día ella es mi meditativa reflexión.<br/>Cuánto amo yo<br/>Cuánto amo Tu ley.<br/>',NULL,197703,1);
INSERT INTO stanza VALUES('S2390','1','Bendito sea el Dios y Padre<br/>De nuestro Señor Jesucristo,<br/>Que nos bendijo<br/>Con toda bendición espiritual<br/>En los lugares celestiales en Cristo,<br/>Que nos bendijo<br/>Con toda bendición espiritual<br/>En los lugares celestiales en Cristo.<br/>',NULL,197704,1);
INSERT INTO stanza VALUES('S2391','1','Anhelo que mi corazón mire solo a Ti,<br/>Que vea que de hecho<br/>Nada hay fuera de Ti,<br/>No me dejes estar embotada aquí,<br/>Señor, que Tu palabra<br/>Tenga libertad en mí.<br/>Quiero verte a Ti,<br/>Disfrutarte a Ti,<br/>Abrirme a Ti,<br/>Y amarte de todo corazón.<br/>',NULL,197705,1);
INSERT INTO stanza VALUES('S2391','SoundCloud Link','https://soundcloud.com/jules-campos-kalaidjian/mi-deseo-de-hoy-prayer-song',NULL,197706,2);
INSERT INTO stanza VALUES('S2392','1','¿Sabías tú la situación<br/>De‿aquél que no recibe al Señor?<br/>En perdición eterna‿está,<br/>Mas Dios le‿ofrece vida‿eterna.<br/>',NULL,197707,1);
INSERT INTO stanza VALUES('S2392','chorus','Di, "¿dónde estás tú? Pregunto hoy.<br/>Tu corazón buscando está;<br/>Heme aquí, por ti morí.<br/>Ven, te llamo hoy, respóndeme."<br/>Un corazón conforme a Mí<br/>Estoy buscando para cumplir<br/>Mi eterno plan.<br/>',NULL,197708,2);
INSERT INTO stanza VALUES('S2392','2','En este mundo encontrarás<br/>Todo conforme a Satanás;<br/>Aunque parece una gran atracción<br/>Sólo te trae perdición.<br/>',NULL,197709,3);
INSERT INTO stanza VALUES('S2392','3','Mas en la iglesia, dulce hogar,<br/>Junto Conmigo puedes tú morar,<br/>Y con el Cuerpo en comunión<br/>Encontrarás satisfacción.<br/>',NULL,197710,4);
INSERT INTO stanza VALUES('S2392','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/sab-as-tu-la-situaci-n-donde',NULL,197711,5);
INSERT INTO stanza VALUES('S2393','1','Tú guardarás en completa paz<br/>A aquel cuyo pensamiento en Ti persevera.<br/>Tú guardarás en completa paz<br/>A aquel cuyo pensamiento en Ti persevera.<br/>Porque en Ti ha confiado,<br/>Porque en Ti ha confiado,<br/>Porque en Ti ha confiado,<br/>Tú le guardarás en completa paz. (x2)<br/>',NULL,197712,1);
INSERT INTO stanza VALUES('S2393','2','Confiad en Jesús, perpetuamente en Jesús,<br/>Porque en el Señor está la fortaleza de los siglos.<br/>Confiad en Jesús, perpetuamente en Jesús,<br/>Porque en el Señor está la fortaleza<br/>De los siglos ¡En completa paz!<br/>',NULL,197713,2);
INSERT INTO stanza VALUES('S2393','SoundCloud Link','https://soundcloud.com/user-631728043-431161926/tu-guardaras',NULL,197714,3);
INSERT INTO stanza VALUES('S2394','1','¡Dios como‿el Espíritu<br/>Se extiende en mi ser!<br/>Mi espíritu,‿alma‿y cuerpo<br/>Dios está santificando.<br/>¡Por completo me preserva Él!<br/>',NULL,197715,1);
INSERT INTO stanza VALUES('S2394','2','Y el mismo Dios de paz<br/>Nos ha de santificar.<br/>Y el mismo Dios de paz;<br/>Por completo lo‿hará.<br/>',NULL,197716,2);
INSERT INTO stanza VALUES('S2394','3','Nuestro‿espíritu y alma‿y cuerpo<br/>Por completo‿has de preservar<br/>Santos y sin mancha en amor<br/>Hasta que regrese nuestro Señor.<br/>',NULL,197717,3);
INSERT INTO stanza VALUES('S2394','SoundCloud Link','https://soundcloud.com/dani_candia/dios-como-el-espiritu-ft-jc-y',NULL,197718,4);
INSERT INTO stanza VALUES('S2395','1','Todos pueden hoy tomar,<br/>Gratuitamente de la vida.<br/>Antes buscábamos algo real<br/>Y lo encontramos por invocarle.<br/>',NULL,197719,1);
INSERT INTO stanza VALUES('S2395','2','Jesús me libertó<br/>Y descubrí la realidad ya,<br/>El satisface mi espíritu;<br/>Y soy feliz desde que encontré a Cristo.<br/>',NULL,197720,2);
INSERT INTO stanza VALUES('S2395','3','Nueva es mi vida<br/>Desde que Él vive en mí,<br/>Alegre y tranquilo ahora yo estoy,<br/>Tú a este Jesús también puedes tener,<br/>Solo abre tu boca y a Él invoca.<br/>',NULL,197721,3);
INSERT INTO stanza VALUES('S2395','4','Él está muy cerca preparado para entrar,<br/>Al simple llamado de tu corazón,<br/>Invocando Su nombre, Su vida tendrás,<br/>Solo abre tu boca y a Él invoca.<br/>',NULL,197722,4);
INSERT INTO stanza VALUES('S2395','5','Todo está en invocar Su nombre,<br/>Es fácil de hacer solo Invocarle:<br/>¡Oh Señor!<br/>',NULL,197723,5);
INSERT INTO stanza VALUES('S2396','1','No lo que quiera hacer,<br/>Ni a dónde quiera ir,<br/>Pues, ¿Quién soy yo que debo decidir?<br/>Mi Padre ya escogió la senda que es mejor<br/>Y así feliz yo debo ir.<br/>',NULL,197724,1);
INSERT INTO stanza VALUES('S2397','1','Satisfecho no estaré<br/>Hasta obtener de Ti lo mejor;<br/>Tu perfecta voluntad en mi<br/>Debe de ser mi elección.<br/>',NULL,197725,1);
INSERT INTO stanza VALUES('S2397','chorus','No permitas que persista_<br/>En conformarme con menos;<br/>No permitas que yo elija<br/>Cuando Tú has preparado lo mejor.<br/>',NULL,197726,2);
INSERT INTO stanza VALUES('S2397','2','Tu camino aún no me_es claro<br/>Tiendo a descarriarme;<br/>Sin Tu constante guía y luz<br/>Proseguir yo no podré.<br/>',NULL,197727,3);
INSERT INTO stanza VALUES('S2397','3','No me des la elección entre<br/>mi interferir y Tu voluntad;<br/>Aún habitando en lo exterior<br/>Y preferencia natural.<br/>',NULL,197728,4);
INSERT INTO stanza VALUES('S2397','4','Aún lleno de deseos propios<br/>Vuelve mi corazón a Ti<br/>Cómo podría yo vivir feliz,<br/>Si es lejos de Ti.<br/>',NULL,197729,5);
INSERT INTO stanza VALUES('S2397','5','Oh cada día de mi vida<br/>Guía mis pasos así;<br/>Cuando a la encrucijada llegue<br/>Elije Tu por mi.<br/>',NULL,197730,6);
INSERT INTO stanza VALUES('S2397','6','Anhelos en mi corazón<br/>Reemplaza, y lléname;<br/>Hazme satisfecho en Tí<br/>Y yo jamás me iré.<br/>',NULL,197731,7);
INSERT INTO stanza VALUES('S2397','SoundCloud Link','https://soundcloud.com/user-465337419/no-permitas-que-yo-elija',NULL,197732,8);
INSERT INTO stanza VALUES('S2398','1','Tu nombre invoqué,<br/>Oh Jehová<br/>Desde la fosa más profunda.<br/>No_escondas Tu oído a mi voz,<br/>A mi clamor.<br/>Tú has oído mi voz,<br/>Has_oído mi voz.<br/>Jehová_ha oído mi voz,<br/>Ha oído mi voz.<br/>',NULL,197733,1);
INSERT INTO stanza VALUES('S2398','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/tu-nombre-invoque-oh-jehova-i-calle-upon-thy-name-o-lord',NULL,197734,2);
INSERT INTO stanza VALUES('S2399','1','Y Me buscaréis<br/>Y Me hallaréis,<br/>Si me buscáis de...<br/>Todo corazón.<br/>',NULL,197735,1);
INSERT INTO stanza VALUES('S2399','2','Y Me buscaréis<br/>Y Me hallaréis,<br/>Si me buscáis de...<br/>Todo corazón.<br/>',NULL,197736,2);
INSERT INTO stanza VALUES('S2399','3','Por que Yo se<br/>Los pensamientos<br/>Que tengo acerca de...<br/>De vosotros...<br/>Pensamientos de paz<br/>Y no de mal,<br/>Para daros<br/>Un porvenir<br/>Y una esperanza.<br/>',NULL,197737,3);
INSERT INTO stanza VALUES('S2399','4','Y Me buscaréis<br/>Y Me hallaréis,<br/>Si me buscáis de...<br/>Todo corazón.<br/>',NULL,197738,4);
INSERT INTO stanza VALUES('S2399','5','Y Me buscaréis<br/>Y Me hallaréis,<br/>Si me buscáis de...<br/>Todo corazón.<br/>',NULL,197739,5);
INSERT INTO stanza VALUES('S2399','6','Y seré hallado<br/>Por vosotros...<br/>Y seré hallado<br/>Por vosotros...<br/>',NULL,197740,6);
INSERT INTO stanza VALUES('S2399','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/y-me-buscare-is-y-me-hallare',NULL,197741,7);
INSERT INTO stanza VALUES('S2400','1','Acuérdate de la palabra<br/>Dada a Tu siervo,<br/>En la cual me has_hecho esperar.<br/>Me has hecho esperar.<br/>Éste es mi consuelo<br/>En mi aflicción,<br/>Pues Tu palabra me ha<br/>Vivificado<br/>Imploré de<br/>Todo corazón Tu rostro,<br/>[Oh Señor] concédeme<br/>[Hoy] Tu favor conforme<br/>A Tu palabra, [mi Dios].<br/>',NULL,197742,1);
INSERT INTO stanza VALUES('S2400','SoundCloud Link','https://soundcloud.com/dani_candia/sal-11949-50-58-melodia-himno-492',NULL,197743,2);
INSERT INTO stanza VALUES('S2401','1','Para Dios lograr Su plan<br/>Como el Padre se impartió,<br/>Escogió y predestinó para_filiación.<br/>Hoy sus muchos hijos son<br/>Como casa espiritual,<br/>La intención de Dios logró en_santificación.<br/>',NULL,197744,1);
INSERT INTO stanza VALUES('S2401','chorus','La transmisión del Cristo trascendente<br/>En Su ascensión el Cuerpo Él formó;<br/>Su expresión para consumación<br/>Y por la triple impartición.<br/>',NULL,197745,2);
INSERT INTO stanza VALUES('S2401','2','En el Hijo Él ganó una eterna redención,<br/>Una herencia de valor, somos Su posesión.<br/>Es por_la transformación y por_la renovación,<br/>Conformados para_la glorificación.<br/>',NULL,197746,3);
INSERT INTO stanza VALUES('S2401','3','El Espíritu al sellar, hoy_las arras ha de dar,<br/>Su imagen a_expresar, por el saturar,<br/>Para el perfeccionar, nuestra herencia Dios será;<br/>Esta es nuestra seguridad por la eternidad.<br/>',NULL,197747,4);
INSERT INTO stanza VALUES('S2401','SoundCloud Link','https://soundcloud.com/yuri-duraes-997000462/la-transmision-del-cristo-trascendente',NULL,197748,5);
INSERT INTO stanza VALUES('S2402','1','Los que están conmigo<br/>Te saludan. Saluda<br/>A los que nos aman,<br/>Nos aman en fe.<br/>La gracia sea con todos.<br/>',NULL,197749,1);
INSERT INTO stanza VALUES('S2402','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2402_los-que-esta-n-conmigo-te',NULL,197750,2);
INSERT INTO stanza VALUES('S2403','1','Siento una y otra vez<br/>Que mi amor lejos está;<br/>En días grises, horas largas;<br/>Pero Él orando está<br/>En mi hora de oscuridad;<br/>En los santos por mi bien.<br/>',NULL,197751,1);
INSERT INTO stanza VALUES('S2403','chorus','Me acaricia con Su fiel amor.<br/>Del cielo viene Su voz;<br/>Susurrandome<br/>Por hombres de barro está.<br/>Y el mundo quede atrás.<br/>(Que el mundo quede atrás).<br/>',NULL,197752,2);
INSERT INTO stanza VALUES('S2403','2','Que ha hecho, no veo,<br/>El mundo a mi corazón;<br/>Desangrándose, enfría.<br/>A mi puerta Él llamó<br/>Con los santos me alcanzó<br/>Para mi necesidad.<br/>',NULL,197753,3);
INSERT INTO stanza VALUES('S2403','SoundCloud Link','https://soundcloud.com/user-871371384/there-are-times-and-times',NULL,197754,4);
INSERT INTO stanza VALUES('S2404','1','Son sesenta hombres<br/>Que hacen guardia al lecho del rey,<br/>Guerreros valientes de Israel.<br/>',NULL,197755,1);
INSERT INTO stanza VALUES('S2404','2','Todos expertos son<br/>En la guerra; tienen...<br/>Todos expertos son<br/>En la guerra; tienen<br/>Su espada en su muslo por<br/>Los temores nocturnos.<br/>Son sesenta hombres<br/>Que hacen guardia al lecho del rey,<br/>Guerreros valientes de Israel.<br/>',NULL,197756,2);
INSERT INTO stanza VALUES('S2404','3','Con Cristo en una unión de amor<br/>Su amada combate a fin... de que El<br/>Pueda reposar.<br/>Cristo nos da Su palabra fiel:<br/>Una espada con poder,<br/>Viva palabra que_al decir<br/>Hace al enemigo huir.<br/>Descansamos unidos a El,<br/>Combatiendo por Su interés.<br/>Son sesenta hombres<br/>Que hacen guardia al lecho del rey,<br/>Guerreros valientes de Israel.<br/>',NULL,197757,3);
INSERT INTO stanza VALUES('S2404','chorus','1, 2 y 3 se pueden cantar en canon.<br/>',NULL,197758,4);
INSERT INTO stanza VALUES('S2404','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/son-sesenta-hombres-there-is',NULL,197759,5);
INSERT INTO stanza VALUES('S2405','1','Tal cual y como los dias de Noé fueron<br/>Así será la venida del Hijo del Hombre;<br/>Todos comían y todos bebían,<br/>Todos se daban en casamiento.<br/>',NULL,197760,1);
INSERT INTO stanza VALUES('S2405','chorus','Todos ignoraron<br/>Que_el juicio pronto iba_a llegar;<br/>Todos ignoraron;<br/>Y_el diluvio vino a todos a_arrastrar.<br/>',NULL,197761,2);
INSERT INTO stanza VALUES('S2405','2','Dos hombres también estarán en el campo;<br/>Pero sólo uno de_ellos será tomado.<br/>Moliendo_en_el molino dos mujeres,<br/>Una de ellas será dejada.<br/>',NULL,197762,3);
INSERT INTO stanza VALUES('S2405','chorus','Velad, por tanto;<br/>Pues no sabéis cuando venga el Señor.<br/>Velad, por tanto;<br/>Estad preparados; porque_el Señor vendrá.<br/>',NULL,197763,4);
INSERT INTO stanza VALUES('S2405','3','Haznos, Señor, como Noé fiel y sobrios.<br/>De la corriente del mundo hoy nos guardes,<br/>Con ésta éra no estar embotados.<br/>Señor, sí! Ven! No Te retrases.<br/>',NULL,197764,5);
INSERT INTO stanza VALUES('S2405','chorus','Ser los vencedores<br/>En ésta era,_antes del final.<br/>Haznos vencedores<br/>Para Tu venida: preparados estar.<br/>',NULL,197765,6);
INSERT INTO stanza VALUES('S2405','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2405_tal-cual-y-como-los-di-as',NULL,197766,7);
INSERT INTO stanza VALUES('S2406','1','La Biblia es la Palabra de Dios,<br/>Verdad y realidad,<br/>Ella es Espíritu y es vida,<br/>Mi alimento eternal.<br/>',NULL,197767,1);
INSERT INTO stanza VALUES('S2406','2','La Biblia es el aliento de Dios<br/>Que puedo inhalar.<br/>En ella puedo conocerte<br/>Y amarte más y más.<br/>',NULL,197768,2);
INSERT INTO stanza VALUES('S2406','chorus','En ella Te puedo encontrar,<br/>Tu voz puedo escuchar;<br/>Hazmela oir!<br/>Que todos recibamos<br/>El amor de la verdad<br/>Andando en ella.<br/>No solo doctrina, más la realidad:<br/>Columnas en la iglesia.<br/>Y así vencer<br/>Comiendote en la Palabra cada vez;<br/>Oir Tu voz será mi dirección<br/>En cada situación.<br/>',NULL,197769,3);
INSERT INTO stanza VALUES('S2406','SoundCloud Link','https://soundcloud.com/jamany-pastuizaca/la-biblia-borrador',NULL,197770,4);
INSERT INTO stanza VALUES('S2407','1','Lo que hemos visto<br/>Y oído,<br/>Os lo anunciamos también a vosotros<br/>Para que también vosotros tengáis<br/>Comunión con nosotros.<br/>',NULL,197771,1);
INSERT INTO stanza VALUES('S2407','chorus','Y nuestra comunión verdaderamente<br/>Es con el Padre y su Hijo Jesucristo;<br/>Con el Padre y su Hijo Jesucristo.<br/>',NULL,197772,2);
INSERT INTO stanza VALUES('S2407','SoundCloud Link','https://soundcloud.com/user-849491777/1-jn-1-3',NULL,197773,3);
INSERT INTO stanza VALUES('S2408','1','Qué gran misterio es:<br/>Cristo en ti, Cristo en mi.<br/>Oh, qué victoria es:<br/>Cristo en ti, Cristo en mi.<br/>',NULL,197774,1);
INSERT INTO stanza VALUES('S2408','2','Cristo está en ti;<br/>Aun si_el cuerpo de carne muerto está.<br/>Nuestro_espíritu tiene la vida zoé.<br/>[Rom. 8:10]<br/>',NULL,197775,2);
INSERT INTO stanza VALUES('S2408','3','Dios quiso mostrar<br/>Las riquezas de la gloria de_éste misterio:<br/>Que_es Cristo en vosotros:<br/>!Oh qué gloria!<br/>[Col. 1:27]<br/>',NULL,197776,3);
INSERT INTO stanza VALUES('S2408','4','Examinaos y probaos;<br/>¿O acaso no conocéis<br/>Que Cristo está en vosotros?<br/>[2 Co. 13:5]<br/>',NULL,197777,4);
INSERT INTO stanza VALUES('S2408','5','Con Cristo crucifica...<br/>do yo estoy; y ya no vivo yo,<br/>Mas Cristo_hoy vive en mí.<br/>[Gal. 2:20]<br/>',NULL,197778,5);
INSERT INTO stanza VALUES('S2408','6','Qué gran misterio es:<br/>Cristo en ti, Cristo en mi.<br/>Oh, qué victoria es:<br/>Cristo en ti, Cristo en mi.<br/>',NULL,197779,6);
INSERT INTO stanza VALUES('S2408','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/cristo-en-ti-cristo-en-mi',NULL,197780,7);
INSERT INTO stanza VALUES('S2409','1','¿Se ha acabado el vino ya?<br/>Apenas yo lo probé;<br/>Antes que mi lengua_haya saciado su sed,<br/>¿Se ha acabado ya?<br/>',NULL,197781,1);
INSERT INTO stanza VALUES('S2409','2','Todo el dinero gasté<br/>En lo que no perduró.<br/>Más tan pronto como lo tuve, se escapó,<br/>Pronto se secó.<br/>',NULL,197782,2);
INSERT INTO stanza VALUES('S2409','3','Veinte años entrené,<br/>A lo más alto escalé;<br/>Desde allí miré alrededor y lo que vi:<br/>Sólo vanidad.<br/>',NULL,197783,3);
INSERT INTO stanza VALUES('S2409','4','En la ciencia yo exploré,<br/>En mil causas yo creí;<br/>Más la ciencia, la razón, filosofía, no<br/>Satisfizo mi corazón.<br/>',NULL,197784,4);
INSERT INTO stanza VALUES('S2409','5','Mucho tiempo me costó<br/>Ver que todo es vanidad.<br/>Tanto tiempo fingiendo que todo estaba bien,<br/>Pero sin realidad.<br/>',NULL,197785,5);
INSERT INTO stanza VALUES('S2409','6','En profunda oscuridad<br/>De rodillas yo clamé;<br/>Alguien vino a mi, mi muerte por vida cambió,<br/>Me infundió la fe.<br/>',NULL,197786,6);
INSERT INTO stanza VALUES('S2409','7','Su nombre yo invocaré,<br/>De tal Fuente beberé.<br/>Al clamar Su nombre, fluye el agua viva en mi.<br/>Ese nombre amaré.<br/>',NULL,197787,7);
INSERT INTO stanza VALUES('S2409','8','Todo fue solo Él en verdad,<br/>Guardó lo mejor al final;<br/>Finalmente hallé el más dulce eterno "vino" ya<br/>Es el vino celestial.<br/>',NULL,197788,8);
INSERT INTO stanza VALUES('S2410','1','El primer_"andar" es "caminar alrededor"<br/>"Algo común";<br/>"Libre_andar"; "general".<br/>"Andar común, diario y habitual.<br/>{Gal. 5:16}<br/>',NULL,197789,1);
INSERT INTO stanza VALUES('S2410','chorus','Vivir, andar, y_en el espíritu<br/>Todo nuestro ser centrar.<br/>Peripateo y stoicheo;<br/>Dos maneras hay de_andar.<br/>',NULL,197790,2);
INSERT INTO stanza VALUES('S2410','2','El segundo "andar" implica "marcha militar",<br/>"El paso conservar";<br/>"Un andar regulado";<br/>Tomando la única meta de Dios.<br/>{Gal. 5:25}<br/>',NULL,197791,3);
INSERT INTO stanza VALUES('S2410','3','El Espíritu debe ser el camino y dirección,<br/>Principio y ley<br/>Sin cesar; seguimos el<br/>Sentido de vida y paz interior.<br/>{Gal. 5:16,25 y notas}.<br/>',NULL,197792,4);
INSERT INTO stanza VALUES('S2410','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2409_dos-maneras-de-andar-m4a',NULL,197793,5);
INSERT INTO stanza VALUES('S2411','chorus','¿Sabías que yo soy un Dios-hombre,<br/>Un ser tripartito<br/>Unido_al Triuno Dios;<br/>Y tengo un espíritu<br/>Do el diablo no tiene lugar,<br/>O parte, o poder?<br/>¡Soy_un Dios-hombre!<br/>[¡Soy un Dios-hombre!]<br/>',NULL,197794,1);
INSERT INTO stanza VALUES('S2411','1','Dentro de mi vive el Señor<br/>En mi espíritu: el frente de avance;<br/>Luego de_allí Él se extiende a mi voluntad<br/>Mente y emoción.<br/>Como semilla se plantó<br/>En lo profundo de mi;<br/>El reino está aquí<br/>Viviendo dentro de mi.<br/>Su hogar es mi corazón.<br/>',NULL,197795,2);
INSERT INTO stanza VALUES('S2411','2','Cada vez que digo —Amén—<br/>A Su Espíritu dentro del mio.<br/>Brota y crece la semilla del reino<br/>Dentro de mi.<br/>Puede parecer tal vez<br/>Que nada cambie en mi,<br/>Más no soy igual,<br/>Creciendo está Dios en mi.<br/>¡Igual a Él seré!<br/>',NULL,197796,3);
INSERT INTO stanza VALUES('S2411','SoundCloud Link','https://soundcloud.com/cantemos_con_gozo_siempre/2410_sabi-as-que-soy-un-dios',NULL,197797,4);
INSERT INTO stanza VALUES('S2412','1','Debemos hoy ver:<br/>¡Dios se necesita͜ expresar!<br/>Nuestro gemir es:<br/>¡Señor crece͜ en nos!<br/>Pon Tu corazón<br/>En nosotros para͜ hablar<br/>De Tu libertad,<br/>Y Tu dispensar.<br/>Oramos así...<br/>',NULL,197798,1);
INSERT INTO stanza VALUES('S2412','chorus','Sus ojos abrir,<br/>Tornar sus tinieblas en luz,<br/>Volver de la͜ autoridad<br/>De Satán a Dios,<br/>Reciban así<br/>Perdón por pecar,<br/>Lo que tiene Dios,<br/>Lo que͜ ha hecho Dios,<br/>Y lo que hará.<br/>',NULL,197799,2);
INSERT INTO stanza VALUES('S2412','2','Oramos Señor,<br/>Anunciando vida͜ eternal<br/>Dando͜ a conocer<br/>Que pueden creer.<br/>¡Danos fuerzas hoy!<br/>Nos damos a proclamar<br/>Esta libertad<br/>Y‿evangelizar,<br/>Oramos así...<br/>',NULL,197800,3);
INSERT INTO stanza VALUES('S2413','1','Desead, como niños recién nacidos,<br/>La leche de la palabra<br/>Dada sin engaño,<br/>Para que por ella crezcáis<br/>Para salvación.<br/>',NULL,197801,1);
INSERT INTO stanza VALUES('S2413','2','Porque toda la‿Escritura,<br/>Viene del aliento de Dios<br/>Y‿es útil para‿enseñar,<br/>Corregir, redargüir...<br/>',NULL,197802,2);
INSERT INTO stanza VALUES('S2413','3','A fin de que‿el hombre de Dios<br/>Sea cabal, enteramente equipado.<br/>Para toda buena obra.<br/>',NULL,197803,3);
INSERT INTO stanza VALUES('S2414','1','Dios es fiel, por el cual fuisteis llamados<br/>A la comunión de Su Hijo‿amado.<br/>Jesucristo nuestro, nuestro Señor,<br/>Señor de‿ellos y nuestro como porción.<br/>',NULL,197804,1);
INSERT INTO stanza VALUES('S2414','2','Supremo llamado para disfrutar,<br/>Y participar de nuestra porción;<br/>El Todo-inclusivo en todo lo que‿Él es,<br/>Del propósito de Dios el centro es.<br/>',NULL,197805,2);
INSERT INTO stanza VALUES('S2414','3','Toda‿esta porción subjetiva es,<br/>Se‿ha depositado dentro de mi ser;<br/>En mi‿espíritu con Él uno soy,<br/>De la‿unión orgánica disfruto hoy.<br/>',NULL,197806,3);
INSERT INTO stanza VALUES('S2414','4','Todo lo que eres se transmite hoy.<br/>A todos los santos que‿en Tu comunión,<br/>Toman Tu Persona como‿el Espíritu.<br/>Participando de lo que eres Tú.<br/>',NULL,197807,4);
INSERT INTO stanza VALUES('S2414','5','Nuestra buena tierra, que todo lo‿incluye,<br/>Es nuestra porción y nuestro disfrute;<br/>Todas Sus riquezas disfrutadas hoy,<br/>Producirán la‿edificación de Dios.<br/>',NULL,197808,5);
INSERT INTO stanza VALUES('S2414','6','Hoy te poseemos, ¡Oh, Señor Jesús!<br/>Mientras disfrutamos de Tu plenitud;<br/>De las distracciones nos tornamos hoy,<br/>Clamando‿a Tu nombre: ¡Oh, Señor Jesús!<br/>',NULL,197809,6);
INSERT INTO stanza VALUES('S2414','7','Tórnanos a Ti, ¡Oh, señor Jesús!<br/>Céntranos en Ti, ¡Oh, Señor Jesús!<br/>Métenos en Ti, ¡Oh, Señor Jesús!<br/>Quiero disfrutarte, ¡Oh, Señor Jesús!<br/>',NULL,197810,7);
INSERT INTO stanza VALUES('S2415','1','El Padre Dios, el manantial,<br/>Rica fuente eternal<br/>Que brota desde el mismo Dios<br/>En Cristo, el canal;<br/>Espíritu es el fluir,<br/>Saltando El está .<br/>Río de vida, Triuno es<br/>Glorioso y real.<br/>',NULL,197811,1);
INSERT INTO stanza VALUES('S2415','chorus','¡Gran río es, profundo es<br/>Puedo entrar!<br/>Fluyendo está, del Salvador<br/>Roca eternal;<br/>¡Y limpio es, puro también<br/>Brillando está!<br/>El Triuno Dios, Cristo Jesús<br/>En resurrección.<br/>',NULL,197812,2);
INSERT INTO stanza VALUES('S2415','2','Únicamente un fluir<br/>De gracia eternal;<br/>Desde el edén fluyendo esta<br/>Alcanzando a la humanidad.<br/>Por la corriente y el beber<br/>Llegaremos a ser;<br/>Su incremento y compleción,<br/>Cristo en expresión.<br/>',NULL,197813,3);
INSERT INTO stanza VALUES('S2415','3','Gratuitamente este fluir<br/>Para nosotros es;<br/>Nos lleva al árbol para así<br/>Vida a todo traer.<br/>Río turbulento y pleno es<br/>Para regenerar<br/>Corriente que impregnando está<br/>Y nos transformará!<br/>',NULL,197814,4);
INSERT INTO stanza VALUES('S2415','4','No cesará este caudal<br/>Su meta cumplirá;<br/>El hombre con el Triuno Dios:<br/>Nueva Jerusalén.<br/>La dulzura de este fluir<br/>Cristo inclusivo es;<br/>A los santos, consumará<br/>Para vida eternal.<br/>',NULL,197815,5);
INSERT INTO stanza VALUES('S2416','1','El Sembrador se ha sembrado<br/>Como semilla en mi ser;<br/>La buena tierra ha encontrado<br/>La vida rica de Él.<br/>',NULL,197816,1);
INSERT INTO stanza VALUES('S2416','chorus','Vamos creciendo<br/>Hacia la transformación;<br/>Sólo las piedras preciosas<br/>Forman su edificación.<br/>',NULL,197817,2);
INSERT INTO stanza VALUES('S2416','2','Crece a diario la vida<br/>Por el continuo regar,<br/>Por la palabra de vida<br/>En un terreno ideal.<br/>',NULL,197818,3);
INSERT INTO stanza VALUES('S2416','3','Si como plantas quedamos<br/>Nos tocará corrupción;<br/>Pero si a piedras llegamos,<br/>Divina transformación.<br/>',NULL,197819,4);
INSERT INTO stanza VALUES('S2416','4','Cristo cambió Sus riquezas<br/>Por una perla sin par,<br/>Dando Su vida preciosa<br/>Para la iglesia ganar.<br/>',NULL,197820,5);
INSERT INTO stanza VALUES('S2416','5','Él edifica la iglesia,<br/>Su habitación eternal,<br/>Con oro y piedras preciosas<br/>Jerusalén celestial.<br/>',NULL,197821,6);
INSERT INTO stanza VALUES('S2417','1','El nuevo hombre andando va<br/>En este nuevo caminar,<br/>Siendo renovado está,<br/>Lleno del nuevo vino está.<br/>Cantando la nueva canción<br/>Teniendo una nueva visión;<br/>Señor, haznos nuevos en Ti,<br/>Mente espíritu y corazón.<br/>',NULL,197822,1);
INSERT INTO stanza VALUES('S2417','2','Nuevo hombre anda en novedad<br/>En todas las iglesias hoy,<br/>Incluidos estamos en Él,<br/>Renovando la mente está<br/>En calidad, forma y ser<br/>Mente nueva nos llevará<br/>A amar y a escoger al Señor<br/>Como en Colosenses 3:10.<br/>',NULL,197823,2);
INSERT INTO stanza VALUES('S2417','3','El nuevo hombre llenó está<br/>De Cristo, quien vino nuevo es,<br/>Fresco, nuevo en tiempo y vigor,<br/>De vida nueva lleno está.<br/>Bebiendo vida divinal<br/>Vino nuevo rebosará,<br/>Y ser la expresión del Señor,<br/>En Mateo 9 está.<br/>',NULL,197824,3);
INSERT INTO stanza VALUES('S2417','4','Caminemos en novedad<br/>Para traer el reino hoy;<br/>Abierto el camino nos fue<br/>En Hebreos 10:20a<br/>Danos esta nueva visión,<br/>Renueva nuestro hombre interior;<br/>Del nuevo vino llénanos<br/>Hasta ser la nueva Ciudad.<br/>',NULL,197825,4);
INSERT INTO stanza VALUES('S2418','1','El propósito de Dios<br/>Es Su Cristo propagar,<br/>Al Cristo resucitado<br/>Y quien ascendido‿está;<br/>Dios Triuno procesado,<br/>Propagándose está;<br/>El Espíritu es hoy,<br/>Para‿así Su vida dar.<br/>',NULL,197826,1);
INSERT INTO stanza VALUES('S2418','2','Como‿Espíritu‿esencial<br/>Se sopló dentro de mí,<br/>Para ser mi existencia<br/>Y para ser mi vivir.<br/>Económico Espíritu,<br/>Con Su poder me vistió,<br/>Para propagar a Cristo,<br/>Cristo en resurrección.<br/>',NULL,197827,2);
INSERT INTO stanza VALUES('S2418','3','Y para llevar a cabo<br/>Su plan de propagación,<br/>Todos debemos vivirle,<br/>Vivirle‿en resurrección.<br/>Nos ha hecho Sus testigos,<br/>Testigos en ascensión<br/>Para propagar a Cristo,<br/>Cristo en resurrección.<br/>',NULL,197828,3);
INSERT INTO stanza VALUES('S2418','4','Esto está produciendo<br/>Una multiplicación,<br/>Muchas iglesias locales<br/>Que son el reino de Dios.<br/>Señor hoy a Ti nos damos,<br/>Para propagar Tu ser,<br/>Que tengas Tu reino‿en pleno,<br/>La Nueva Jerusalén.<br/>',NULL,197829,4);
INSERT INTO stanza VALUES('S2418','5','Predicando‿el evangelio,<br/>Será la culminación,<br/>Brillaran setenta‿y ocho**<br/>Candeleros del Señor,<br/>Dándonos a la palabra,<br/>Dándonos a la‿oración<br/>Y del Espíritu llenos<br/>Vendrá la culminación.<br/>',NULL,197830,5);
INSERT INTO stanza VALUES('S2418','chorus','**Número de ciudades y pueblos en Puerto Rico**.<br/>',NULL,197831,6);
INSERT INTO stanza VALUES('S2419','1','En la‿eternidad pasada<br/>Dios tuvo‿un deseo<br/>Que brotó de Su corazón.<br/>Este gran deseo<br/>Incluyó al hombre,<br/>Quería hacer de‿él Su‿habitación.<br/>',NULL,197832,1);
INSERT INTO stanza VALUES('S2419','chorus','A‿imagen de Dios el hombre fue hecho.<br/>Frente‿al árbol de vida puesto.<br/>El hombre debía tomarle,<br/>Mas no supo valorarle,<br/>Mas no supo valorarle.<br/>',NULL,197833,2);
INSERT INTO stanza VALUES('S2419','2','Dios no‿ha descansado<br/>Pues quiere lograr<br/>Cumplir con Su‿eterno plan.<br/>Para‿este gran proyecto<br/>Poder consumar,<br/>Cuatro razas fue‿a llamar.<br/>',NULL,197834,3);
INSERT INTO stanza VALUES('S2419','chorus','Tres razas ya‿han fracasado.<br/>En la cuarta,‿Él ha confiado.<br/>No podemos defraudarle.<br/>¡A vencer nos ha llamado!<br/>¡A vencer nos ha llamado!<br/>',NULL,197835,4);
INSERT INTO stanza VALUES('S2419','3','**[Final :]**<br/>En la‿eternidad pasada<br/>Dios tuvo‿un deseo<br/>Que brotó de Su corazón.<br/>',NULL,197836,5);
INSERT INTO stanza VALUES('S2420','1','Mas tú, hombre de Dios,<br/>Huye de estas cosas, y sigue la justicia,<br/>La piedad, la fe, el amor,<br/>La perseverancia, la mansedumbre.<br/>Pelea la batalla de la fe,<br/>De la vida eterna ayúdate,<br/>A la cual fuiste llamado,<br/>A la cual fuiste llamado, mi hermano.<br/>',NULL,197837,1);
INSERT INTO stanza VALUES('S2421','1','¡Oh, mis ojos al fin te͜ han visto!<br/>Hombre͜ inmundo veo en mí.<br/>Eres fino, manso y puro,<br/>Jesús, amo comer de Ti.<br/>',NULL,197838,1);
INSERT INTO stanza VALUES('S2421','2','Al digerir, asimilar,<br/>Mezcla total Tú lograrás.<br/>Divinidad, humanidad,<br/>Tu realidad vista será.<br/>',NULL,197839,2);
INSERT INTO stanza VALUES('S2421','chorus','Máxima meta:<br/>Un reino edificar,<br/>Comiendo a Jesús.<br/>Flor de harina,<br/>Nuestro͜ alimento será,<br/>Reinando,<br/>A diario͜ en Su͜ humanidad.<br/>',NULL,197840,3);
INSERT INTO stanza VALUES('S2421','3','¡He aquí el Hombre Jesús!<br/>A Satanás venciste Tú.<br/>Apta es Tu humanidad,<br/>Para pelear y conquistar.<br/>',NULL,197841,4);
INSERT INTO stanza VALUES('S2421','chorus','Divinamente,<br/>Enriquecida está,<br/>Así es Tu͜ humanidad.<br/>Hombre perfecto,<br/>El Dios completo también.<br/>Te amo,<br/>Hombre tan fino͜ y cabal.<br/>',NULL,197842,5);
INSERT INTO stanza VALUES('S2421','4','Mi mente haz clara, Señor,<br/>Para Ti soy vaso de͜ honor.<br/>La iglesia sea así,<br/>Testimonio firme de Ti.<br/>',NULL,197843,6);
INSERT INTO stanza VALUES('S2421','chorus','Divinamente,<br/>Enriquecida está,<br/>Así es Tu͜ humanidad.<br/>Hombre perfecto,<br/>El Dios completo también.<br/>Te amo,<br/>Hombre tan fino͜ y cabal.<br/>',NULL,197844,7);
INSERT INTO stanza VALUES('S2421','note','',NULL,197845,8);
INSERT INTO stanza VALUES('S2421','chorus','Máxima meta:<br/>Un reino edificar,<br/>Comiendo a Jesús.<br/>Flor de harina,<br/>Nuestro͜ alimento será,<br/>Reinando,<br/>A diario͜ en Su͜ humanidad.<br/>',NULL,197846,9);
INSERT INTO stanza VALUES('S2421','SoundCloud Link','https://soundcloud.com/oralia-hernandez-501143941/oh-mis-ojos-al-fin-te-han',NULL,197847,10);
INSERT INTO stanza VALUES('S2422','1','No con manos una piedra<br/>Del monte se cortará,<br/>Levantando‿un reino‿eterno<br/>Que nunca se quitará;<br/>Destruyendo toda mezcla,<br/>Y gobierno terrenal,<br/>Toda‿apariencia del reino<br/>Su poder destruirá.<br/>',NULL,197848,1);
INSERT INTO stanza VALUES('S2422','chorus','¡Oh, el Rey ya viene,<br/>El Rey ya viene!<br/>¡Mi Señor, venga Tu reino,<br/>Hágase Tu voluntad!<br/>¡El Rey ya viene, el Rey ya viene!<br/>¡Jesús, Su reino traerá!<br/>',NULL,197849,2);
INSERT INTO stanza VALUES('S2422','2','¡Bendito es el que viene<br/>En el nombre del Señor!<br/>De‿Israel el remanente<br/>Tomará su corazón;<br/>Resplandecerá Su gloria,<br/>Más que el sol se‿expresará;<br/>Los creyentes vencedores<br/>Con Cristo han de reinar.<br/>',NULL,197850,3);
INSERT INTO stanza VALUES('S2422','3','Mi Señor, Tu vida‿expresa<br/>Plenamente desde mí,<br/>Que la realidad del reino<br/>Sea todo mi vivir;<br/>La vida de mi‿alma quiero,<br/>Por el reino,‿hacer morir,<br/>El disfrute venidero<br/>Manifestarás al fin.<br/>',NULL,197851,4);
INSERT INTO stanza VALUES('S2422','4','La iglesia‿es nuestra vida,<br/>El reino‿es nuestro vivir,<br/>Anhelamos ser Tu reino,<br/>Desde hoy y desde aquí;<br/>A Tu vida sometidos<br/>Transformándonos estás,<br/>Tu preciada perla seamos<br/>Hoy y por la‿eternidad.<br/>',NULL,197852,5);
INSERT INTO stanza VALUES('S2423','1','Nombre sobre todo nombre<br/>Es el Nombre de mi Cristo,<br/>Ante tan glorioso Nombre<br/>Todos se postrarán.<br/>',NULL,197853,1);
INSERT INTO stanza VALUES('S2423','2','Todas las fuerzas de‿oscuridad,<br/>De todo‿el mundo la‿humanidad,<br/>Todos los cielos y su potestad,<br/>Todos se postrarán.<br/>',NULL,197854,2);
INSERT INTO stanza VALUES('S2423','3','Nuestros ojos le contemplan,<br/>Nuestro corazón le‿adora,<br/>Nuestra lengua hoy proclama:<br/>¡Jesucristo‿es Señor!<br/>',NULL,197855,3);
INSERT INTO stanza VALUES('S2424','1','De Jehová es la tierra y su plenitud;<br/>La tierra y los que en ella habitan.<br/>Porque Él la fundó,<br/>La fundó sobre los mares<br/>Y la afirmó sobre los ríos.<br/>',NULL,197856,1);
INSERT INTO stanza VALUES('S2424','2','¿Quién subirá al monte de Jehová,<br/>Y quién se sentará en Su santo lugar?<br/>El limpio de manos y puro de corazón;<br/>(solamente lo hará)<br/>El que no ha elevado su alma a la maldad<br/>(solamente lo hará)<br/>Ni jurado con engaño.<br/>Oh, bendito Jehová.<br/>',NULL,197857,2);
INSERT INTO stanza VALUES('S2424','3','Esos recibirán bendición de Jehová<br/>Y justicia del Dios de salvación.<br/>Tal es la generación<br/>De los que le buscan,<br/>De los que buscan Tu rostro,<br/>Oh, Dios de Jacob.<br/>Alzad oh puertas,<br/>Alzad vuestras cabezas;<br/>Y alzaos vosotras,<br/>Puertas, puertas eternas;<br/>Que entrará el Rey de gloria.<br/>¿Quién es el Rey de gloria?<br/>Es Jehová el fuerte y valiente<br/>Es Jehová el poderoso en batalla.<br/>Alzad oh puertas,<br/>Alzad vuestras cabezas;<br/>Y alzaos vosotras puertas,<br/>Puertas eternas;<br/>Que entrará el Rey de gloria.<br/>¿Quién es el Rey de gloria?<br/>Es Jehová de los ejércitos<br/>//Él es el Rey de gloria.//<br/>',NULL,197858,3);
INSERT INTO stanza VALUES('S2425','1','En Su segunda venida,<br/>Cristo tomará posesión<br/>De la tierra y establecerá<br/>El reino de Dios,<br/>Y establecerá el reino de Dios en la tierra,<br/>El reino de Dios en la tierra.<br/>Extendiendo el reino consigo mismo,<br/>Como el río que fluye recobrando<br/>La tierra al regarla, y satisfaciendo<br/>A los sedientos con agua viva.<br/>',NULL,197859,1);
INSERT INTO stanza VALUES('S2426','1','Señor, que vivas en mí,<br/>Señor, que yo viva‿en Ti;<br/>Vive Tú en nosotros,<br/>Como nuestro vivir.<br/>Como‿una persona hoy<br/>Vivamos junto Tú‿y yo<br/>Con una misma vida, y‿un mismo vivir.<br/>',NULL,197860,1);
INSERT INTO stanza VALUES('S2426','chorus','Un sólo‿espíritu y‿una sola naturaleza,<br/>Una persona y vida ser.<br/>',NULL,197861,2);
INSERT INTO stanza VALUES('S2426','2','Señor, hoy quiero vivir<br/>En Tu entrañable‿amor,<br/>En Tus sentimientos y‿en Tu corazón<br/>Entrar bien profundo‿en Ti<br/>Y Tu gracia recibir,<br/>Gracia que‿es suficiente,<br/>Y‿excede el pensar.<br/>',NULL,197862,3);
INSERT INTO stanza VALUES('S2426','chorus','Un sólo‿espíritu y‿una sola naturaleza,<br/>Una persona y vida ser.<br/>',NULL,197863,4);
INSERT INTO stanza VALUES('S2426','3','Quiero vivirte, Señor<br/>No‿importa mi situación,<br/>Quiero magnificarte, ser Tu expresión.<br/>Que‿en toda mi‿adversidad<br/>Y cuando no pueda más,<br/>Como‿el inagotable Te pueda alcanzar.<br/>',NULL,197864,5);
INSERT INTO stanza VALUES('S2426','chorus','Un sólo‿espíritu y‿una sola naturaleza,<br/>Una persona y vida ser.<br/>',NULL,197865,6);
INSERT INTO stanza VALUES('S2426','4','Vivirte, dulce Señor<br/>Equivale‿a disfrutar<br/>Tu salvación constante en mi diario‿andar.<br/>En mi circunstancia‿aquí,<br/>Con los santos en reunión,<br/>En casa‿y trabajando, en el mundo‿actual.<br/>',NULL,197866,7);
INSERT INTO stanza VALUES('S2426','chorus','Un sólo‿espíritu y‿una sola naturaleza,<br/>Una persona y vida ser.<br/>**[Final: ¡Tú y yo!]**<br/>',NULL,197867,8);
INSERT INTO stanza VALUES('S2427','1','Si amamos al Señor,<br/>Y velamos por Su_único Cuerpo,<br/>Él se derramará sobre<br/>Nosotros y se moverá<br/>Como el Espíritu intensificado,<br/>Mezclándonos para<br/>La consumación<br/>De la Nueva Jerusalén.<br/>',NULL,197868,1);
INSERT INTO stanza VALUES('S2428','1','Tu dulzura es para nuestro disfrute,<br/>Tu belleza es la atracción de mi corazón.<br/>Tu resplandor me captó.<br/>Despojas mi interior.<br/>A diario Te quiero besar.<br/>Y tomarme de Ti.<br/>',NULL,197869,1);
INSERT INTO stanza VALUES('S2428','chorus','Te amo locamente, oh Jesús,<br/>Te amo locamente, oh Jesús,<br/>Te amo locamente, oh Jesús.<br/>Hasta que yo no esté más.<br/>Te amo locamente, oh Jesús,<br/>Te amo locamente, oh Jesús,<br/>Te amo locamente, oh Jesús.<br/>Hasta perderme‿en Ti.<br/>',NULL,197870,2);
INSERT INTO stanza VALUES('S2428','2','Olvidando todo lo que hago por fuera,<br/>Olvidando mis intenciones de mejorar.<br/>Tu quieres nuestro amor,<br/>Mi amor Te entrego a Ti.<br/>Locamete amando a Jesús,<br/>¡Que alegría me da!<br/>',NULL,197871,3);
INSERT INTO stanza VALUES('S2428','3','Mi vida es simplemente para amarte,<br/>Mi obra es también amarte con todo mi ser,<br/>Amarte es mi placer, y mi servicio también,<br/>Amarte es mi intencion y mi voluntad.<br/>',NULL,197872,4);
INSERT INTO stanza VALUES('S2428','4','Oh mi amor, de todo me has cegado,<br/>Oh mi amor, haces que el mundo sea nada.<br/>Solo quiero verte a Ti, y necesitarte a Ti.<br/>No hay nadie más para mi,<br/>Solo Tú, mi Jesús.<br/>',NULL,197873,5);
INSERT INTO stanza VALUES('S2429','chorus','Triuno Dios,<br/>Oh cuanto nos amas.<br/>Triuno Dios,<br/>Tú te diste a nos,<br/>Triuno Dios,<br/>Ahora el Espíritu en nos.<br/>Somos uno por siempre.<br/>',NULL,197874,1);
INSERT INTO stanza VALUES('S2429','1','Dios, Padre amoroso.<br/>A Tu hijo recibirás,<br/>Cristo el Hijo, el Pastor,<br/>El Espíritu barriendo.<br/>Nos vuelve hacia Ti siempre.<br/>',NULL,197875,2);
INSERT INTO stanza VALUES('S2429','chorus','Triuno Dios,<br/>Oh cuanto nos amas.<br/>Triuno Dios,<br/>Tú te diste a nos,<br/>Triuno Dios,<br/>Ahora el Espíritu en nos.<br/>Somos uno por siempre.<br/>',NULL,197876,3);
INSERT INTO stanza VALUES('S2429','2','Dios, Padre el cayado,<br/>Cristo, roca herida.<br/>Golpeada y agua brotó,<br/>Como Espíritu fluyendo.<br/>Su vida tendremos siempre.<br/>',NULL,197877,4);
INSERT INTO stanza VALUES('S2429','chorus','Triuno Dios,<br/>Oh cuanto nos amas.<br/>Triuno Dios,<br/>Tú te diste a nos,<br/>Triuno Dios,<br/>Ahora el Espíritu en nos.<br/>Somos uno por siempre.<br/>',NULL,197878,5);
INSERT INTO stanza VALUES('S2429','3','Dios Triuno te dispensas,<br/>A Ti mismo como vida.<br/>Tu amor, en gracia expresas,<br/>Y la comunión nos une.<br/>Mezclados contigo siempre.<br/>',NULL,197879,6);
INSERT INTO stanza VALUES('S2429','chorus','Triuno Dios,<br/>Oh cuanto te amamos.<br/>Triuno Dios,<br/>Nos damos a Ti.<br/>Triuno Dios,<br/>A Ti nos abrimos.<br/>Somos uno por siempre.<br/>',NULL,197880,7);
INSERT INTO stanza VALUES('S2430','1','El Dios Triuno se procesó,<br/>Como‿una ley en mí se‿instaló.<br/>En el contacto con el Señor,<br/>Vivo‿en Su ley de vida hoy.<br/>',NULL,197881,1);
INSERT INTO stanza VALUES('S2430','chorus','Señor te amo,<br/>Vengo a Ti,<br/>Quiero‿en Ti permanecer.<br/>Jesús te amo,<br/>Guárdame‿en Ti,<br/>Mantenme‿a diario amándote a Ti.<br/>',NULL,197882,2);
INSERT INTO stanza VALUES('S2430','2','Sin esforzarme por mejorar,<br/>Tal como soy me puedo‿acercar.<br/>Mientras le invoco en comunión,<br/>En Cristo no‿hay condenación.<br/>',NULL,197883,3);
INSERT INTO stanza VALUES('S2430','chorus','Señor te amo,<br/>Vengo a Ti,<br/>Quiero‿en Ti permanecer.<br/>Jesús te amo,<br/>Guárdame‿en Ti,<br/>Mantenme‿a diario amándote a Ti.<br/>',NULL,197884,4);
INSERT INTO stanza VALUES('S2430','3','**[Portugués :]**<br/>A chave o meu coração é,<br/>Exercitando o espírito assim,<br/>Faz-me um vaso aberto, Senhor,<br/>Dispensando Tua vida em mim.<br/>',NULL,197885,5);
INSERT INTO stanza VALUES('S2430','chorus','**[Portugués:]**<br/>Senhor, Te amo,<br/>Venho a Ti,<br/>Quero em Ti permanecer.<br/>Jesus, Te amo,<br/>Guarda-me em Ti,<br/>Diariamente amando a Ti.<br/>',NULL,197886,6);
INSERT INTO stanza VALUES('S2430','4','A Su‿Hijo Dios me conformará,<br/>“Todas las cosas” Él dispondrá.<br/>Si‿amo a Jesús y le digo amén,<br/>Todo coopera para bien.<br/>',NULL,197887,7);
INSERT INTO stanza VALUES('S2430','chorus','La ley de vida:͜ en<br/>Su Cuerpo está,<br/>Miembros nos constituirá,<br/>Su‿economía<br/>Consumará<br/>La Nueva Jerusalén nos hará.<br/>',NULL,197888,8);
INSERT INTO stanza VALUES('S2431','1','¡Exultad, oh pueblos todos!<br/>¡Todo mal Cristo venció!<br/>En acuerdo hoy cantad:<br/>¡Gloria_al triunfante Señor!<br/>',NULL,197889,1);
INSERT INTO stanza VALUES('S2431','2','Jamás al diablo tememos,<br/>Cristo lo venció_en la cruz;<br/>Potestades despojó;<br/>Victoriosos en_Él_hoy.<br/>',NULL,197890,2);
INSERT INTO stanza VALUES('S2431','chorus','Dios de paz aplasta bajo<br/>Nuestros pies hoy_a Satán.<br/>Enemigos se dispersan,<br/>Al gozarnos y_alabar.<br/>',NULL,197891,3);
INSERT INTO stanza VALUES('S2431','3','Todo el día: "¡Aleluyas!"<br/>Toda hueste Él venció;<br/>Alabar nos hace estar<br/>En Su trono de honor.<br/>',NULL,197892,4);
INSERT INTO stanza VALUES('S2431','chorus','No te engañen las mentiras;<br/>¡Su obra, Cristo consumó!<br/>En el lago_ardiente_en fuego<br/>La serpiente Él lanzó.<br/>',NULL,197893,5);
INSERT INTO stanza VALUES('S2431','4','Pronto_exaltarán las tribus<br/>Al Señor en Su_esplendor;<br/>Hasta entonces sea_al Rey,<br/>Toda gloria en Su grey.<br/>',NULL,197894,6);
INSERT INTO stanza VALUES('S2431','chorus','Guerrero Corporativo:<br/>La Nueva Jerusalén;<br/>Con Su_Esposo ascendido,<br/>Su novia_una ha de ser.<br/>',NULL,197895,7);
INSERT INTO stanza VALUES('S2431','5','¡Aleluya, Victorioso!<br/>Con Él uno somos hoy.<br/>Al vivir y_andar en Él,<br/>Su Victoria se_ha de ver.<br/>',NULL,197896,8);
INSERT INTO stanza VALUES('S2432','1','El gran secreto he aprendido<br/>De ͜ en Jesús todo͜ hacer.<br/>Nuestra Cabeza, Rey y Marido,<br/>Escuchar quiere Él.<br/>En dulce comunión<br/>Y con sinceridad,<br/>Derramo mi͜ alma  ͜ante Cristo,<br/>Con toda  ͜ intimidad.<br/>',NULL,197897,1);
INSERT INTO stanza VALUES('S2432','chorus','¡Él escuchará!<br/>Mi  ͜amor y mi  ͜amigo.<br/>¡Solo dile  ͜a Él!<br/>Él te  ͜ escucha  ͜ otra vez.<br/>',NULL,197898,2);
INSERT INTO stanza VALUES('S2432','2','Dile ͜en tus penas y depresiones<br/>Desde tu corazón.<br/>Tus decepciones y frustraciones<br/>Ponlas sobre ͜  el Señor.<br/>Cada͜  afán y dolor,<br/>Cada lágrima Él<br/>Las guardará ͜ en Su *redoma,<br/>Las atesora fiel.<br/>',NULL,197899,3);
INSERT INTO stanza VALUES('S2432','3','Dile tus pecados y ansiedades;<br/>Nada hay que  ͜ocultar.<br/>En las tinieblas y  ͜en los problemas<br/>Ni ͜una queja callar.<br/>Desahogándome así,<br/>Él se ͜acerca a mí;<br/>Él no nos juzga, mas cuida<br/>Lo confiado a Él.<br/>',NULL,197900,4);
INSERT INTO stanza VALUES('S2432','4','Dile tus gozos y alegrías;<br/>Él se goza allí.<br/>Cualquier suceso o experiencia<br/>La quiere compartir.<br/>Todo puro ͜hace Él;<br/>Solo invita  ͜a Jesús.<br/>Guarda siempre Su presencia:<br/>¡Qué tesoro ͜en tu ser!<br/>',NULL,197901,5);
INSERT INTO stanza VALUES('S2432','5','Le ͜he entregado todas mis cargas<br/>A mi Salvador.<br/>Mis confusiones, preocupaciones,<br/>Las hará Suyas hoy.<br/>Misterio puedo ver,<br/>Dios se une a mí;<br/>Él usa cada ͜apertura<br/>Impartiéndose fiel.<br/>',NULL,197902,6);
INSERT INTO stanza VALUES('S2432','chorus','¡Él escuchará!<br/>Mi  ͜amor y mi  ͜amigo.<br/>Se lo diré ͜a Él<br/>Hasta la ͜era ͜acabar.<br/>',NULL,197903,7);
INSERT INTO stanza VALUES('S2432','note','***Redoma: Vasija de vidrio ancha en su fondo que va estrechándose hacia la boca.<br/>(Sal. 56:8)**<br/>',NULL,197904,8);
